-- =============================================================================
-- PROCEDURE: [dbo].[auditCount]
-- =============================================================================
CREATE   PROC auditCount
AS
/*	DATE		AUTHOR		REMARKS
	8/28/05		PPaiva		Initial creation.
	8/30/05		PPaiva		Added CustomerEmailHistory.
	9/6/05		PPaiva		Added ProductRegistrationsHistory.  

	DESCRIPTION
		Shows count of the triggered Audit tables.

*/

	SELECT  'KeycodesAudit' AuditTable, Count(*) Qty
	FROM KeycodesAudit
UNION
	SELECT 'Invoice_ItemsAudit', Count(*)
	FROM Invoice_ItemsAudit
UNION
	SELECT 'InvoicesAudit', Count(*)
	FROM InvoicesAudit
UNION
	SELECT 'CustomersAudit', Count(*)
	FROM CustomersAudit
UNION 
	SELECT 'CustomerEmailHistory', Count(*)
	FROM CustomerEmailHistory
UNION 
	SELECT 'ProductRegHistory', Count(*)
	FROM Product_RegistrationsAudit
	ORDER BY 1






GO
