-- PROCEDURE: [dbo].[csi_comments_insert]
-- =============================================================================
-- =============================================
-- Author:		<Kevin Adams>
-- Create date: <6/25/2007>
-- Description:	<For inserting csi_comment records>
-- =============================================

CREATE PROCEDURE [dbo].[csi_comments_insert] 
(
	@subject varchar(255),
	@comment varchar(8000),	
	@customer_id int,
	@invoice_id int,
	@license_id int,
    @csi_users_id varchar(50) = ''
)
	
AS
BEGIN
	SET NOCOUNT ON;

declare @insert_date datetime,
		@insert_by varchar(50)

Set @insert_date = getdate()
Set @insert_by = system_user

    insert into csi_comments (subject, comment, customer_id, invoice_id, license_id, insert_by, insert_date, csi_users_id)
	values (@subject, @comment, @customer_id, @invoice_id, @license_id, @insert_by, @insert_date, @csi_users_id)

END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[csi_comments_lookup]
-- =============================================================================

CREATE PROCEDURE [dbo].[csi_comments_lookup] 

(
	@customer_id int = 0,
	@invoice_id int = 0,
	@license_id int = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2007-06-25	Kevin Adams	Initial creation.
	2012-12-03	esmart		Modified to simplify selects
	2019-05-09	cnovac		Added csi.csi_users_id in select out

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	if @customer_id is null begin select @customer_id = 0 end
	if @invoice_id is null begin select @invoice_id = 0 end
	if @license_id is null begin select @license_id = 0 end

	declare @search_method int

	select @search_method = 0

	-- pre sort
	if @license_id is not null and @license_id <> 0
		begin
		select @search_method = 1
		end
	if @search_method = 0 and @invoice_id is not null and @invoice_id <> 0
		begin
		select @search_method = 2
		end
	if  @search_method = 0 and @customer_id is not null and @customer_id <> 0
		begin
		select @search_method = 3
		end

		--print @search_method

	if @search_method = 1
		begin
		select distinct csi.subject,
			csi.comment,
			csi.insert_date,
			'Keycode - ' + l.keycode as description ,
			case when csi.csi_users_id = '' then '' when u.first_name is null then csi.csi_users_id else u.first_name end as first_name,
			case when csi.csi_users_id = '' then '' when u.last_name is null then '' else u.last_name end as last_name,
			csi.csi_users_id
		from csi_comments csi
		join license l with (nolock)
			on csi.license_id = l.license_id
		left join csi_users u with (nolock)
			on csi.csi_users_id = u.csi_users_id and u.csi_users_id <>''
		where csi.license_id = @license_id
		order by csi.insert_date desc
		end
	if @search_method = 2
		begin
		declare @vendor_order_code varchar(100)

		select @vendor_order_code = vendor_order_code from vendor_order v inner join order_header h on v.vendor_order_id = h.vendor_order_id where h.order_header_id = @invoice_id
		
		select subject = case 
				when csi.refund_reason_code = 0 then csi.subject
				else csi.subject + rr.description
			end,
			csi.comment,
			csi.insert_date,
			'Invoice - ' + @vendor_order_code as description,
			case when csi.csi_users_id = '' then '' when u.first_name is null then csi.csi_users_id else u.first_name end as first_name,
			case when csi.csi_users_id = '' then '' when u.last_name is null then '' else u.last_name end as last_name,
			csi.csi_users_id
		from csi_comments csi with (nolock)
		left join lu_refund_reasons rr with (nolock) 
			on csi.refund_reason_code = rr.refund_reason_code
		left join csi_users u with (nolock) 
			on csi.csi_users_id = u.csi_users_id and u.csi_users_id <> ''
		where csi.invoice_id = @invoice_id
		order by csi.insert_date desc
		end
	if @search_method = 3
		begin
		select 
			csi.subject,
			csi.comment,
			csi.insert_date,
			' ' as description,
			csi.csi_users_id as first_name,
			csi.csi_users_id as last_name,
			csi.csi_users_id
		from csi_comments csi with (nolock)
		join customer c with (nolock) on csi.customer_id = c.customer_id
		where csi.customer_id = @customer_id
		order by csi.insert_date desc
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
