CREATE PROC epicor_QueueCount
AS
/*	DATE		AUTHOR		REMARKS
	8/31/05		PPaiva		Initial creation.

	DESCRIPTION
		Shows a row count for all epicor queue tables.
*/


-- Examine table counts
SELECT 'Pull' Process, 'OrderQueue' TableName, Count(*) Qty FROM epicor_Epicor2WR_OrderQueue UNION
SELECT 'Pull' Process, 'OrderQueue bk' TableName, Count(*) Qty FROM epicor_Epicor2WR_OrderQueue_bk UNION
