GO
-- =============================================================================
-- PROCEDURE: [dbo].[epicor_ValidateDataFromEpicor2]
-- =============================================================================
CREATE    PROC epicor_ValidateDataFromEpicor2
AS
/*	DATE		AUTHOR		REMARKS
	9/22/05		PPaiva		Initial creation.
	
	DESCRIPTION
		Changes ProcesFlag to 1 for any orders that
		already exist in the WebOps database.  Writes 
		error message to Description column.  
*/

SET NOCOUNT ON

DECLARE @ProcessDate datetime,
		@ErrMsg varchar(500),	
		@ErrMsgLimit int

SET @ErrMsgLimit = 70
SET @ProcessDate = GetDate()	-- Set this to a variable so dates are consistent throughout this proc

-- Get orders that already exist
SELECT  Order_No, Ext, 
		Invoice_Code, 
		ProcessFlag,
		Convert(varchar(70), '') [Description]
INTO #CheckExistingOrders
FROM v_epicor_ProcessStatus 
WHERE ProcessFlag In (0, 11, 12, 13, 15)


CREATE INDEX CheckExistingOrders_InvNum ON #CheckExistingOrders(Invoice_Code)


UPDATE epicor_Epicor2WR_ProcessStatus
SET ProcessFlag = 2,
	ProcessDate = @ProcessDate,
	Description = 'This order number has already been used.'
FROM epicor_Epicor2WR_ProcessStatus S
JOIN #CheckExistingOrders eo
		ON s.Invoice_Code = eo.Invoice_Code
JOIN Invoice_Items ii
		ON eo.Invoice_Code = ii.Invoice_Code


DROP TABLE #CheckExistingOrders 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[epicor_WR2Epicor_StagingPurge]
-- =============================================================================


CREATE  PROC epicor_WR2Epicor_StagingPurge
				@Date1 datetime,
				@Date2 datetime
AS
/*	DATE		AUTHOR		REMARKS
	6/9/05		PPaiva		Initial creation.

	DESCRIPTION
		1.  Part of the Webroot to Epicore process.
		2.  Deletes any rows for a given date range in the 
			staging table, wr_tf_w_web_source.  
		3.  Date range is >= Date1 AND < Date2

*/

DELETE epicor_WR2Epicor_Queue
WHERE Purchased_Date >= @Date1
  AND Purchased_Date <  @Date2


GO
-- =============================================================================
-- PROCEDURE: [dbo].[licensing_insert_license_activation_insert]
-- =============================================================================


CREATE procedure [dbo].[licensing_insert_license_activation_insert]
as
/*
2010-03-22	dsmelker	Created

Purpose: Move over License activation records in a bulk operation


*/
Begin

Begin Try

Declare @max_license_activation_id int,
		@new_max_license_activation_id int,
		@start_date datetime,
		@completed_date datetime,
		@xml nvarchar(max),
		@dbconnect varchar(50),
		@sql nvarchar(max)

select @start_date= getdate()

select @dbconnect=dbo.getConnection('licensing')

----------------------------------------------------------------------------
--	Get the max License_activation_id
--
----------------------------------------------------------------------------
select @max_license_activation_id = max_license_activation_id
from licensing_insert_license_activation
where completed_date = (select max(completed_date) from licensing_insert_license_activation)

if @max_license_activation_id is null
Begin
	select @max_license_activation_id = (max(license_activation_id) - 10000)
	from license_activation with(nolock)

end

select top 1 @new_max_license_activation_id= license_activation_id
from license_activation with(nolock)
order by license_activation_id desc


----------------------------------------------------------------------------
--	Generate XML string
--
----------------------------------------------------------------------------
	select @xml = (
			select
				license_activation_id,
				license_id,guid,
				machine_name,
				insert_date = getdatE()
			from license_activation with(nolock)
			where license_activation_id > @max_license_activation_id
			FOR XML PATH)

		set @xml='<record>'+replace(@xml,'''','''''')+'</record>'


		set @sql = 'exec ' + @dbconnect + '.dbo.usp_license_activation_insert_bulk '''+ @xml + ''''


		

		exec sp_executesql @sql

----------------------------------------------------------------------------
--	Insert Process Record
--
----------------------------------------------------------------------------
set @completed_date = getdatE()

insert into licensing_insert_license_activation
values
(@new_max_license_activation_id,@start_date, @completed_date)


End Try

Begin Catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end Catch

end


GO
