-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_insert_account]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_account_insert_account]

(
		@account_user_name varchar(100), 
		@account_password varchar(64), 
		@password_hint varchar(50), 
		@account_type_id tinyint, 
		@account_status_id tinyint, 
		@parent_account_id int, 
		@insert_by  varchar(20),
		@keycode varchar(40),
		@WARN_opt_in tinyint = 1,
		@email_opt_in tinyint = 1
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation
	2017-08-02	mrobbins	added license check insert for journey

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@account_id int,
			@license_id int,
			@license_status_id int,
			@customer_id int,
			@current_license_category_id tinyint,
			@license_category_id_calculated tinyint,
			@upgrade_product_id int,
			@effective_date datetime,
			@days_remaining int,
			@trial int,
			@license_type_id INT,
			@sfmc_processed_record int

	select @response_code = 0

	if @insert_by = '' or @insert_by is null 
		begin
		select @insert_by = suser_sname()
		end

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check username

	select @response_code = case when count(*) > 0 then -110 else 0 end,
			@message = case when count(*) > 0 then 'Account already exists' else '' end
	from account 
	where account_user_name = @account_user_name

	if @response_code < 0
		begin
		select response_code = @response_code, message = @message
		return
		end

	-- 1.2) check keycode 

	select @license_id = license_id,
			@license_status_id = license_status_id,
			@license_type_id = license_type_id
	from license with (nolock)
	where keycode = @keycode

	if @license_id is null
		begin
			set @response_code = -120
			set @message = 'Keycode not found'
			select response_code = @response_code, message = @message
			return
		end

	if @license_status_id in (2,3)
		begin
			set @response_code = -120
			set @message = 'License disabled. Account cannot be created.'
			select response_code = @response_code, message = @message
			return
		end

	if @license_type_id in (2,3)
		begin
			set @response_code = -120
			set @message = 'License is OEM or Trial parent. Account cannot be created.'
			select response_code = @response_code, message = @message
			return
		end

	-- 1.2.2) Check to see if license is expired	
	select @days_remaining = isnull(datediff(dd,getdate(),capability_expiration_date),0)
	from license_capability with (nolock) 
	where license_id = @license_id and capability_id = 1
	
	if @days_remaining <= 0
		begin
			set @response_code = -122
			set @message = 'License expired. Account cannot be created.'
			select response_code = @response_code, message = @message
			return
		end	

	-- 1.3) if the account_type is superuser then validate the the keycode isn't already associated with another master account
	if @account_type_id = 1
		begin
		if (select count(*) from account_license where license_id = @license_id) > 0
			begin	
				set @response_code = -130
				set @message = 'Keycode associated with a different account'
				select response_code = @response_code, message = @message
				return	
			end
		end

	-- 1.4) check to see if there is a customer match on email

	declare @customer_ids table (customer_id int)
	declare	@customer_count int

	insert into @customer_ids (customer_id)
	select distinct customer_id
	from customer_email
	where customer_email = @account_user_name and email_status_id = 1

	select @c
ustomer_count = count(*) from @customer_ids

--	select customer_count = @customer_count

--	if @customer_count = 0 or @customer_count is null
--		begin
--			select @response_code = -141, @message = 'No customer_email matches account_user_name. Need to create a customer record.'
--		end
--	if @customer_count > 1
--		begin
--			select @response_code = -142, @message = 'Multiple customer_email matches account_user_name. Need to call customer service.'
--		end

	if @customer_count = 1
		begin
			select @customer_id = customer_id from @customer_ids

			if (select customer_id from license where license_id = @license_id) <> @customer_id
				begin
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id)
				select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id = 20
				from license
				where license_id = @license_id
					
				update license
				set customer_id = @customer_id, modified_date = getdate(), modified_by = @account_user_name
				from license
				where license_id = @license_id
				end
		end	

	-- 1.5) get the current license category
	select @current_license_category_id = license_category_id
	from license_category_license
	where license_id = @license_id
	
	if @current_license_category_id is null
		begin
			-- 1.5.1 calculate category
			select @license_category_id_calculated = (select license_category = case
												when count(*) = 4 then 3
												when count(*) in (2,3) then 2
												when count(*) = 1 then 1
											end
			from license_capability
			where license_id = @license_id and capability_type_id = 1 and capability_id < 13)

			if @license_category_id_calculated is null or @license_category_id_calculated = 1
				begin	
					set @response_code = -151
					set @message = 'Spy Sweeper licenses cannot be upgraded.'
					select response_code = @response_code, message = @message
				return	
				end

			select @current_license_category_id = @license_category_id_calculated

		end	

		-- 1.5.3) determine if license is a trial
		set @trial = (select count(*) 
			from license_capability c
			where license_id = @license_id and capability_id = 1 and capability_type_id in (2,3))

		-- 1.5.2 			
			if @current_license_category_id in (2,3) and @trial = 0
				begin
				select @upgrade_product_id = case
							when @current_license_category_id = 2 then 73220000
							when @current_license_category_id = 3 then 73330000
							end	

				declare @sql_string varchar(4000),
							@task_number varchar(10),	
							@db_name varchar(100)

				select @db_name = db_name()
				
				select @sql_string = 
						'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
						' values(' + convert(varchar(10),@license_id) + ',' + '''' + 'declare @effective_date datetime,@license_id int,@response_code int,@message varchar(100) exec ' + @db_name + 
						'..usp_license_sub_renew_license_capability ' + convert(varchar(10),@upgrade_product_id) + ',''''' + @keycode + ''''',''''upgrade'''',''''' + @insert_by + ''''', null, @effective_date OUTPUT,@license_id OUTPUT,@response_code OUTPUT,@message OUTPUT''' +
						',0,getdate()) '
--				print @sql_string
				exec (@sql_string)

				exec tasks..usp_queue_task @license_id
				
--				exec usp_license_sub_renew_license_capability @upgrade_product_id, @keycode, 'upgrade', @insert_by, null, @effective_date output, @license_id output, @response_code output, @message output
				
				end

	-- -------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--select @account_user_name, @account_password, @security_question, @secret_answer, @account_type_id, @account_status_id, @parent_account_id, @insert_by	

	-- 2.1) insert account
	insert into account (account_user_name, account_password, password_hint, account_type_id, account_status_id, parent_account_id, insert_by, WARN_opt_in, email_opt_in)
	values (@account_user_name, @account_password, @password_hint, @account_type_id, @account_status_id, @parent_account_id, @insert_by, @WARN_opt_in, @email_opt_in)

	select @account_id = scope_identity()
	
	-- 2.2) insert account_license 
	insert into account_license (account_id,license_id)
	values (@account_id, @license_id)
	
	-- 2.3) insert account_customer
	if @customer_id is not null
		begin
			insert into account_customer (account_id,customer_id)
			values (@account_id, @customer_id)
		end
        
	-- 2.4) license check insert
	SELECT @sfmc_processed_record = count(*)
	from license_message
	where license_id = @license_id
	and message_type_id = 13
	and message_status_id in (2,3)
			
	if @sfmc_processed_record > 0 
		BEGIN
			INSERT INTO license_check_update_license(license_id,source)
			SELECT @license_id,1
		END
	

	-- 2.5) return result
	select account_id = @account_id,
			customer_id = @customer_id,
		response_code = case
							when @response_code < 0 then @response_code
							else 0
						end,
		[message] = case
							when @response_code < 0 then @message
							else 'account inserted successfully'
						end
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_insert_account_order_staging]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_insert_account_order_staging]

(
	@merchant_id varchar(50), --google_store, apple_store, webroot
	@email varchar(100),
	@order_token varchar(max),
	@merchant_product_id varchar(100) = null, --the product id as defined in the ordering platform (google play, apple store, webroot cart)
	@account_hash_id varchar(65) = null,
	@opt_in bit = null,
	@apple_notification_id int = null,
	@google_notification_id int = null,
	@original_account_order_staging_id int = null,
	@is_trial_to_full_conversion bit = 0,
	@vendor_order_date datetime = null,
	@vendor_expiration_date datetime = null,
	@order_receipt varchar(100) = null,
	@is_product_change_conversion bit = 0,
	@previous_order_receipt varchar(100) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2018-10-08		cnovac		Added in logic if @account_hash_id is passed in for renewals
	2019-01-07		cnovac		Updated logic to handle product changes
	
	DESCRIPTION
	usp_account_insert_account_order_staging
	
*/

AS

	set nocount on

	begin try

	declare	@payment_merchant_id tinyint,
			@account_order_staging_id int,
			@license_id int,
			@order_header_id int,
			@account_order_json varchar(max),
			@response_code int,
			@message varchar(100)

	select @payment_merchant_id = pm.payment_merchant_id
	from payment_merchant pm
	where pm.merchant_id = @merchant_id

	insert into account_order_staging (payment_merchant_id, email, opt_in, order_token, merchant_product_id, account_hash_id, apple_notification_id, google_notification_id, vendor_order_date, vendor_expiration_date, order_receipt)
	select @payment_merchant_id, @email, @opt_in, @order_token, @merchant_product_id, @account_hash_id, @apple_notification_id, @google_notification_id, @vendor_order_date, @vendor_expiration_date, @order_receipt

	set @account_order_staging_id = scope_identity()

	--if this is populated it means a renewal is happening with an existing user in Derby
	if @account_hash_id is not null
	begin
		--for www orders, we haven't associated the order to account_order, so this code does that
		if @merchant_id = 'webroot'
		begin
			--get the order and license associated to the order token passed in and make sure it doesn't exist in account_order
			select @order_header_id = oh.order_header_id, @license_id = oil.license_id
			from order_header oh
			inner join order_item oi on oi.order_header_id = oh.order_header_id
			inner join order_item_license oil on oil.order_item_id = oi.order_item_id
			cross apply fn_license_select_license_profile(oil.license_id) l
			left join account_order ao on ao.order_header_id = oh.order_header_id
			where oh.order_header_token = @order_token
			and l.license_category_name = 'WIFI'
			and ao.account_order_id is null

			if @license_id is not null and @order_header_id is not null
			begin
				set @account_order_json = (select @account_order_staging_id as account_order_staging_id, @order_header_id as order_header_id for json path,without_array_wrapper)
				exec usp_account_order_finalize @license_id = @license_id, @account_order_json = @account_order_json
			end

		end
		--this means there was a product change from previous transaction, so we need to load a new order and set end date on previous
		else if @is_product_change_conversion = 1
		begin
			--set the previous order_item capability_expiration_date equal to cancellation date from store
			update oi
			set oi.capability_expiration_date = isnull(anbr.cancellation_date, getdate()),
				oi.modified_date = getdate(),
				oi.modified_by = 'wifi_product_cancellation'
			from apple_notifications_by_receipt anbr
			inner join account_order_staging aos on aos.order_receipt = anbr.transact
ion_id
			inner join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
			inner join order_item oi on oi.order_header_id = ao.order_header_id
			inner join product_license_category plc on plc.product_id = oi.product_id
			where anbr.transaction_id = @previous_order_receipt
			and plc.license_category_id = 135 --WIFI

			update aos
			set aos.vendor_expiration_date = isnull(anbr.cancellation_date, getdate()),
				aos.modified_date = getdate()
			from apple_notifications_by_receipt anbr
			inner join account_order_staging aos on aos.order_receipt = anbr.transaction_id
			where anbr.transaction_id = @previous_order_receipt

			set @account_order_json = (select @account_order_staging_id as account_order_staging_id, @original_account_order_staging_id as original_account_order_staging_id, @vendor_expiration_date as vendor_expiration_date for json path, without_array_wrapper)
			exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = 'create_ecom_order', @sfdc_update_json = @account_order_json
		end
		else if (@apple_notification_id is not null or @google_notification_id is not null) and @is_trial_to_full_conversion = 0
		begin
			--first check to see if you have an order where the original account staging id exists
			select @license_id = license_id
			from account_order
			where account_order_staging_id = @original_account_order_staging_id

			select @order_header_id = max(order_header_id)
			from account_order
			where license_id = @license_id
			and order_header_id is not null			

			set @account_order_json = (select @account_order_staging_id as account_order_staging_id, 'store_ar_notification' as account_order_type, @original_account_order_staging_id as original_account_order_staging_id, @order_header_id as order_header_id for json path, without_array_wrapper)
			exec usp_account_order_finalize @license_id = @license_id, @account_order_json = @account_order_json
		end
		else if (@apple_notification_id is not null or @google_notification_id is not null) and @is_trial_to_full_conversion = 1
		begin
			set @account_order_json = (select @account_order_staging_id as account_order_staging_id, 'trial_to_full' as account_order_type, @original_account_order_staging_id as original_account_order_staging_id, @vendor_expiration_date as vendor_expiration_date for json path, without_array_wrapper)
			exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = 'create_ecom_order', @sfdc_update_json = @account_order_json
		end

	end

	select @account_order_staging_id as account_order_staging_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_insert_account_order_staging'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;


GO
