-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_insert_eula]

(
	@account_hash_id varchar(65),
	@eula_accepted bit
)

/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	
	DESCRIPTION
	usp_account_insert_eula
	
*/

AS
	
	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100) = null

	update account_eula
	set eula_accepted = @eula_accepted,
		modified_date = getdate()
	where account_hash_id = @account_hash_id

	if @@ROWCOUNT = 0
	begin
		insert into account_eula (account_hash_id, license_id, eula_accepted)
		select distinct @account_hash_id, ao.license_id, @eula_accepted
		from account_order_staging aos
		left join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
		where aos.account_hash_id = @account_hash_id

		if @@ROWCOUNT = 0
			set @message = 'Failed to find Account'
		
	end

	select @message as result

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_insert_eula'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_insert_verification_message]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_account_insert_verification_message]

(
	@email varchar(100)
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2019-09-09		cnovac		updated logic to look at message_service_type_id 1 and 5
	
	DESCRIPTION
	usp_account_insert_verification_message
	
*/

AS

	set nocount on

	begin try

	declare @previous_message_service_id int,
			@message_service_id int,
			@message_service_type_id int,
			@message_service_client_id int,
			@response_code int,
			@message varchar(100)

	--first check to see if email is already verified
	if exists (select 1
				from account_order_staging
				where email = @email
				and account_hash_id is not null)
	begin
		select -1 as status
		return
	end

	--now go find the original message and see if it's in the archive table
	select @previous_message_service_id = max(msa.message_service_id)
	from message_service_archive msa
	inner join message_service_log_json mslj on mslj.message_service_id = msa.message_service_id
	where msa.customer_email = @email
	and msa.message_service_type_id in (1, 5) --wifi_account_create, wifi_existing_account_create

	if @previous_message_service_id is not null
		select @message_service_type_id = message_service_type_id, @message_service_client_id = message_service_client_id
		from message_service_archive
		where message_service_id = @previous_message_service_id

	--now go find the original message and see if it's in the failure table
	if @previous_message_service_id is null
	begin
		select @previous_message_service_id = max(msf.message_service_id)
		from message_service_failure msf
		inner join message_service_log_json mslj on mslj.message_service_id = msf.message_service_id
		where msf.customer_email = @email
		and msf.message_service_type_id in (1, 5) --wifi_account_create, wifi_existing_account_create
	end

	if @previous_message_service_id is not null
		select @message_service_type_id = message_service_type_id, @message_service_client_id = message_service_client_id
		from message_service_failure
		where message_service_id = @previous_message_service_id

	if @previous_message_service_id is null
	begin
		select -2 as status
		return
	end 

	insert into message_service (message_service_type_id, message_service_client_id, message_service_status_id, customer_email, process_date, update_attempts, last_modified_date, last_modified_by)
	select distinct @message_service_type_id, @message_service_client_id, 1, @email, getdate(), 0, getdate(), system_user
	from account_order_staging aos
	left join message_service ms on ms.customer_email = aos.email and ms.message_service_type_id = 1 --wifi_account_create
	where aos.email = @email
	and ms.message_service_id is null

	set @message_service_id = scope_identity()

	if @message_service_id is not null
	begin
		insert into message_service_log_json (message_service_id, message_service_json)
		select @message_service_id, message_service_json
		from  message_service_log_json
		where message_service_id = @previous_message_service_id
	end

	select null as status

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_insert_verification_message'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_order_finalize]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_order_finalize]

(
	@license_id int,
	@account_order_json varchar(max)
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2018-10-01		cnovac		Added temporary code to handle Apple expiration date issue and override @vendor_expiration_date
	2018-10-09		cnovac		Took out Apple code since we are not doing license_message records for AR with them since we get the notifications real-time
	2019-01-07		cnovac		Simplified logic to figure out @process_date since we want to run it daily
	2019-02-20		rvinoche	Change json schema for license_service
	2019-10-25		esmart		Implement product_autorenewal_cycle
	2020-01-24		cnovac		Updated join to use message_autorenewal_cycle to set message_autorenewal_cycle_id for trials since trial_reg is the only place where we store years now for trials

	DESCRIPTION
	usp_account_order_finalize

*/

AS

	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100),
			@process_date date,
			@vendor_expiration_date date,
			@account_order_staging_id int,
			@days int,
			@trial_id int,
			@order_header_id int,
			@license_message_value_str varchar(200),
			@license_message_id int,
			@message_autorenewal_cycle_id tinyint,
			@merchant_id varchar(50),
			@original_account_order_staging_id int,
			@account_order_type varchar(50),
			@license_service_json varchar(max),
			@license_service_type_name varchar(50) = 'license_update',
			@modified_date datetime = getdate()

	set @account_order_type = json_value(@account_order_json, '$.account_order_type')
	set @account_order_staging_id = json_value(@account_order_json, '$.account_order_staging_id')
	set @original_account_order_staging_id = json_value(@account_order_json, '$.original_account_order_staging_id')
	set @trial_id = json_value(@account_order_json, '$.trial_id')
	set @days = json_value(@account_order_json, '$.days')
	set @order_header_id = json_value(@account_order_json, '$.order_header_id')

	select @merchant_id = pm.merchant_id,
		   @vendor_expiration_date = aos.vendor_expiration_date
	from account_order_staging aos
	inner join payment_merchant pm on pm.payment_merchant_id = aos.payment_merchant_id
	where account_order_staging_id = @account_order_staging_id

	--update the license_message record and abandon in case there's one already there
	update license_message
	set message_status_id = 6, --abandoned
		last_modified_date = @modified_date
	where license_id = @license_id
	and message_type_id = 18
	and message_status_id = 1

	--only go into this code if the order came through google, this creates a license_message used for auto-renew check
	if @merchant_id in ('apple_store', 'google_store')
	begin

		if @days is not null --trial order
			set @process_date = dateadd(dd, 1, @vendor_expiration_date) --add 1 day buffer to trials so to make sure we only check after stores would AR after 7 days
		else
			set @process_date = dateadd(dd, 1, cast(@modified_date as date))

		--insert a new record into license_message
		set @license_message_value_str = 'account_order_staging_id=' + ltrim(rtrim(str(@account_order_staging_id)))
		exec usp_message_insert_license_message @license_id, 18, @process_date, @process_date, @process_date, @license_message_value_str, @license_message_id output, @return_result = 0

		--see if we need to extend the license end date if within 30 days
		select @license_service_json = 
			(select l.keycode, @license_service_type_name as account_name,
				(select l.license_category_name, dateadd(dd, 1, @vendor_expiration_date) as expiration_date for json path) license_category
			from fn_license_select_license_profile(@license_id) l
			where l.license_category_name = 'WIFI'
			and
 dateadd(dd, 1, @vendor_expiration_date) != cast(l.expiration_date as date)
			for json path, without_array_wrapper)

		if @license_service_json is not null
			exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @license_service_json, @return_license_service_id = 0

	end
	else if @merchant_id = 'webroot'
	begin
		--if a www order, we need to set the order_receipt in account_order_staging
		update aos
		set aos.order_receipt = vo.vendor_order_code,
			aos.modified_date = @modified_date
		from account_order_staging aos
		inner join order_header oh on oh.order_header_id = @order_header_id
		inner join vendor_order vo on vo.vendor_order_id = oh.vendor_order_id
		where aos.account_order_staging_id = @account_order_staging_id
		and aos.order_receipt is null

	end

	--now select what billing model they are on (annual or monthly) based on if a trial or full order
	if @order_header_id is not null
	begin
		select @message_autorenewal_cycle_id = pa.message_autorenewal_cycle_id
		from order_item oi
		inner join order_item_license oil on oil.order_item_id = oi.order_item_id
		inner join product p on p.product_id = oi.product_id
		inner join product_autorenewal_cycle pa on p.product_id = pa.product_id
		where oil.license_id = @license_id
		and oi.order_header_id = @order_header_id
	end
	else if @trial_id is not null
	begin
		select @message_autorenewal_cycle_id = mac.message_autorenewal_cycle_id
		from trial t
		inner join trial_registration tr on tr.trial_registration_id = t.trial_registration_id
		inner join message_autorenewal_cycle mac on mac.autorenewal_cycle = tr.years
		where t.trial_id = @trial_id
	end

	if @message_autorenewal_cycle_id is not null
	begin
		exec usp_license_update_license_autorenewal_cycle @license_id = @license_id, @message_autorenewal_cycle_id = @message_autorenewal_cycle_id
	end

	--this insert is the link between order and license
	insert into account_order (account_order_staging_id, trial_id, order_header_id, license_id, original_account_order_staging_id, license_message_id, is_trial_to_full_conversion)
	values(@account_order_staging_id, @trial_id, @order_header_id, @license_id, @original_account_order_staging_id, @license_message_id, iif(@account_order_type = 'trial_to_full', 1, 0))

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_order_finalize'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_order_select_account_hash_id]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_order_select_account_hash_id]

(
	@license_id int
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-10-15		cnovac		Initial creation
	
	DESCRIPTION
	usp_account_order_select_account_hash_id
	
*/

AS
	
	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100)

	select max(aos.account_order_staging_id) as account_order_staging_id,
