	where ao.license_id = @license_id
	group by aos.account_hash_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_order_select_account_hash_id'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
