-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_order_select_order_by_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_order_select_order_by_account]

(
	@account_hash_id varchar(65)
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	
	DESCRIPTION
	usp_account_order_select_order_by_account
	
*/

AS

	set nocount on

	begin try

	declare @account_order_staging int,
			@response_code int,
			@message varchar(100)

	select @account_order_staging = max(aos.account_order_staging_id)
	from account_order_staging aos
	inner join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
	where aos.account_hash_id = @account_hash_id

	if @account_order_staging is not null
		exec usp_account_select_account_order_staging @account_order_staging_id = @account_order_staging

	end try

	begin catch

		set @response_code = -200
