-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_order_select_order_by_token]

(
	@order_token uniqueidentifier
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2018-10-15		cnovac		Changed order_status_id to include partial refunds

	DESCRIPTION
	usp_account_order_select_order_by_token

*/

AS
	
	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100)

	select aos.account_order_staging_id,
		   aos.account_hash_id,
		   ltrim(rtrim(str(datediff(day, getdate(), l.expiration_date)))) + 'days' as expirein,
		   ps.seats
	from order_header oh
	inner join account_order ao on ao.order_header_id = oh.order_header_id
	inner join account_order_staging aos on aos.account_order_staging_id = ao.account_order_staging_id
	inner join order_item oi on oi.order_header_id = oh.order_header_id
	inner join product_license_category plc on plc.product_id = oi.product_id
	inner join product_seat ps on ps.product_id = oi.product_id
	inner join order_item_license oil on oil.order_item_id = oi.order_item_id
	cross apply fn_license_select_license_profile(oil.license_id) l
	where oh.order_header_token = @order_token
	and oh.order_status_id in (1, 2) --Transaction, Partial Refund
	and l.license_category_name = 'WIFI'

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_order_select_order_by_token'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
