-- PROCEDURE: [dbo].[usp_account_order_select_orders_by_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_order_select_orders_by_customer]

(
	@email varchar(100)
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2018-11-15		cnovac		Modified query a bit to exclude any AR records indicated by original_account_order_staging_id
	2019-06-12		cnovac		Updated query
	2019-10-25		esmart		Implement product_autorenewal_cycle

	DESCRIPTION
	usp_account_order_select_orders_by_customer

*/

AS

	set nocount on

	begin try

	declare @account_order_staging int,
			@response_code int,
			@message varchar(100)
	declare @results table (account_order_staging_id int, order_date datetime, trial_id int, order_header_id int, order_channel varchar(50), order_receipt varchar(100), order_term varchar(50), price money, seats tinyint, order_action varchar(50))

	insert into @results (account_order_staging_id, order_date, trial_id, order_channel, order_receipt, order_term, price, seats, order_action)
	select ao.account_order_staging_id, tr.insert_date, t.trial_id, pm.merchant_id, aos.order_receipt, mac.autorenewal_cycle_name, 0, tr.license_seats, 'Trial'
	from account_order ao
	inner join account_order_staging aos on aos.account_order_staging_id = ao.account_order_staging_id
	inner join payment_merchant pm on pm.payment_merchant_id = aos.payment_merchant_id
	inner join trial t on t.trial_id = ao.trial_id
	inner join trial_registration tr on tr.trial_registration_id = t.trial_registration_id
	inner join message_autorenewal_cycle mac on mac.autorenewal_cycle = tr.years
	inner join product_license_category plc on plc.product_id = tr.product_id
	where aos.email = @email
	and plc.license_category_id = 135 --only get the WIFI category

	insert into @results (account_order_staging_id, order_date, order_header_id, order_channel, order_receipt, order_term, price, seats, order_action)
	select ao.account_order_staging_id, oh.insert_date, oh.order_header_id, pm.merchant_id, aos.order_receipt, ma.autorenewal_cycle_name, oi.unit_price, ps.seats, iif(oh.order_status_id = 1, pt.product_type_description, 'Refunded')
	from account_order ao
	inner join account_order_staging aos on aos.account_order_staging_id = ao.account_order_staging_id
	inner join payment_merchant pm on pm.payment_merchant_id = aos.payment_merchant_id
	inner join order_header oh on oh.order_header_id = ao.order_header_id
	inner join order_item oi on oi.order_header_id = oh.order_header_id
	inner join product p on p.product_id = oi.product_id
	inner join product_seat ps on ps.product_id = p.product_id
	inner join product_type pt on pt.product_type_id = p.product_type_id
	inner join product_autorenewal_cycle pa on p.product_id = pa.product_id
	inner join message_autorenewal_cycle ma on pa.message_autorenewal_cycle_id = ma.message_autorenewal_cycle_id
	inner join product_license_category plc on plc.product_id = p.product_id
	where aos.email = @email
	and plc.license_category_id = 135 --only get the WIFI category
	and oi.order_item_status_id = 1

	select account_order_staging_id, order_date, trial_id, order_header_id, order_channel, order_receipt, order_term, price, seats, order_action
	from @results
	order by order_date desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_order_select_orders_by_customer'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
