-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_account_order_select_orders_by_license]
(
    @license_id INT
)
/*  
    DATE            AUTHOR      REMARKS
    2019-01-18      jnavarra    Initial creation
    2019-12-13      jnavarra    Refactor using table function    
    
    DESCRIPTION
    Returns all orders for the given license ID
*/
AS
SET NOCOUNT ON;
BEGIN TRY
    DECLARE @response_code INT,
            @message VARCHAR(100);

    select skytell_notification_id, pending_account_id, account_hash_id, account_id, email, opt_in, merchant_product_id, order_token, order_receipt, vendor_order_date, vendor_expiration_date, license_id, keycode, license_status_id, license_seats, autorenewal_cycle_name, license_attribute_license_value, merchant_id
    from dbo.fn_account_order_select_orders_by_license(@license_id)
END TRY
BEGIN CATCH
    SET @response_code=-200;
    SET @message=CASE WHEN @message IS NULL THEN 'error in usp_account_order_select_orders_by_license' ELSE @message END;
    DECLARE @DBName NVARCHAR(128);
    SET @DBName=DB_NAME();
    EXEC usp_LogError @ErrorDB=@DBName;
END CATCH;

GO
