-- =============================================================================



CREATE PROCEDURE [dbo].[usp_account_select_account_by_account_id]

(
    @account_id int
)

/*
  DATE    AUTHOR    REMARKS
  2009-11-11  esmart    Initial creation.
  2016-11-10  mandersen Added partner_account_status columns.

  DESCRIPTION

*/

AS
  set nocount on

  declare @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) validate inputs
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  -- 1.1) check username

  select a.account_id,
      a.account_user_name,
      a.account_password,
      a.password_hint,
      t.account_type_id, t.account_type, t.account_type_description,
      s.account_status_id, s.account_status,
      lastpass_capability_type = (select ct.capability_type_description
                    from license_capability lc
                    inner join capability_type ct
                      on lc.capability_type_id = ct.capability_type_id
                    where lc.license_id = al.license_id and lc.capability_id = 17),
      lastpass_action = (select t.lastpass_update_type_name
                from lastpass_update u
                inner join lastpass_update_type t
                  on u.lastpass_update_type_id = t.lastpass_update_type_id
                where u.account_id = al.account_id and u.lastpass_update_status_id in (0,2) and u.lastpass_update_type_id = 1),
      sugarsync_capability_type = (select t.capability_type_description
                    from license_capability lc
                    inner join capability_type t
                      on lc.capability_type_id = t.capability_type_id
                    where lc.license_id = al.license_id and lc.capability_id = 11),
      sugarsync_action = (select t.sugarsync_update_type_name
                from sugarsync_update u
                inner join sugarsync_update_type t
                  on u.sugarsync_update_type_id = t.sugarsync_update_type_id
                where u.account_id = al.account_id and u.sugarsync_update_status_id in (0,2) and u.sugarsync_update_type_id = 1),
      a.parent_account_id,
      c.customer_id,
      a.insert_date,
      a.insert_by,
      al.license_id,
      a.WARN_opt_in,
      a.email_opt_in,
      partner_key = convert(varchar(36),p.partner_key),
      pa.partner_account_status_id,
      ps.partner_account_status_name
  from account a
  inner join account_type t
    on a.account_type_id = t.account_type_id
  inner join account_status s
    on a.account_status_id = s.account_status_id
  left join account_license al
    on a.account_id = al.account_id
  left join account_customer c
    on a.account_id = c.account_id
  left join partner_account pa
    on a.account_id = pa.account_id
  left join partner_account_status ps
    on pa.partner_account_status_id = ps.partner_account_status_id
  left join partner p
    on pa.partner_id = p.partner_id
  where a.account_id = @account_id



  end try

  begin catch

    set @response_code = -200
    set @message = case when @message is null then 'select account failed'
              else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

  end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_select_account_by_user_name]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_account_select_account_by_user_name]

(
    @account_user_name varchar(100)
)

/*
  DATE    AUTHOR    REMARKS
  2009-05-22  esmart    Initial creation.
  2015-05-29  esmart    Add partner_account_key
  2016-11-10  mandersen Added partner_account_status columns.
  2017-01-04  mandersen Added order clause.
  2020-02-19  esmart	Add partner_account_id as index

  DESCRIPTION

*/

AS
  set nocount on

  declare @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) validate inputs
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  -- 1.1) check username

  select 
	  isnull(pa.partner_account_id,1) as partner_account_id,
	  a.account_id,
      a.account_user_name,
      a.account_password,
      a.password_hint,
      t.account_type_id, t.account_type, t.account_type_description,
      s.account_status_id, s.account_status,
      lastpass_capability_type = (select ct.capability_type_description
                    from license_capability lc
                    inner join capability_type ct
                      on lc.capability_type_id = ct.capability_type_id
                    where lc.license_id = al.license_id and lc.capability_id = 17),
      lastpass_action = (select t.lastpass_update_type_name
                from lastpass_update u
                inner join lastpass_update_type t
                  on u.lastpass_update_type_id = t.lastpass_update_type_id
                where u.account_id = al.account_id and u.lastpass_update_status_id in (0,2) and u.lastpass_update_type_id = 1),
      sugarsync_capability_type = (select t.capability_type_description
                    from license_capability lc
                    inner join capability_type t
                      on lc.capability_type_id = t.capability_type_id
                    where lc.license_id = al.license_id and lc.capability_id = 11),
      sugarsync_action = (select t.sugarsync_update_type_name
                from sugarsync_update u
                inner join sugarsync_update_type t
                  on u.sugarsync_update_type_id = t.sugarsync_update_type_id
                where u.account_id = al.account_id and u.sugarsync_update_status_id in (0,2) and u.sugarsync_update_type_id = 1),
      a.parent_account_id,
      c.customer_id,
      a.insert_date,
      a.insert_by,
      al.license_id,
      a.WARN_opt_in,
      a.email_opt_in,
      p.partner_id,
  	  p.partner_name,
      partner_key = convert(varchar(36),p.partner_key),
      partner_account_key = convert(varchar(36),pa.partner_account_key),
      pa.partner_account_status_id,
      ps.partner_account_status_name
  from account a
  inner join account_type t
    on a.account_type_id = t.account_type_id
  inner join account_status s
    on a.account_status_id = s.account_status_id
  left join account_license al
    on a.account_id = al.account_id
  left join account_customer c
    on a.account_id = c.account_id
  left join partner_account pa
    on a.account_id = pa.account_id
  left join partner_account_status ps
    on pa.partner_account_status_id = ps.partner_account_status_id
  left join partner p
    on pa.partner_id = p.partner_id
  where account_user_name = @account_user_name
  order by
      pa.partner_account_status_id desc



  end try

  begin catch

    set @response_code = -200
    set @message = case when @message is null then 'select account failed'
              else @mess
age end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

  end catch;




GO
