CREATE PROCEDURE [dbo].[usp_account_select_account_license_history]

(
	@account_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-12	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select record_type = 'audit', l.keycode, a.account_license_id, a.account_id, a.license_id, a.license_change_reason_id, r.license_change_reason, a.last_modified_date, a.last_modified_by
	from account_license_audit a
	inner join license l
		on a.license_id = l.license_id
	inner join license_change_reason r
		on a.license_change_reason_id = r.license_change_reason_id
	where account_id = @account_id 
	union 
	select record_type = 'active', l.keycode, a.account_license_id, a.account_id, a.license_id, null, '', a.last_modified_date, a.last_modified_by
	from account_license a
	inner join license l
		on a.license_id = l.license_id
	where account_id = @account_id 

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
