CREATE PROCEDURE [dbo].[usp_account_select_customer_search_results]

(	
	@first_name nvarchar(225),
	@last_name nvarchar(225),
	@customer_email varchar(255),
	@company_name varchar(255),
	@vendor_customer_code varchar(100),
	@phone_number varchar(12),
	@address varchar(200),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2014-11-13		esmart		Search modifications
	2015-10-01		cnovac		Added the partial email search capability
	2017-11-15		esmart		Add license count and other columns
	2017-12-19		acoffel		Active/Disabled licenses
	2018-09-04		cnovac		Added search for WIFI
	2018-10-03		cnovac		Added code to to further search WIFI and return both order email and account email

	DESCRIPTION
	CSI Search
*/

AS
	set nocount on

	declare @partial_email_search bit = 0
			
	if @first_name is null set @first_name = ''
	if @last_name is null set @last_name = ''
	if @customer_email is null set @customer_email = ''
	if @company_name is null set @company_name = ''
	if @vendor_customer_code is null set @vendor_customer_code = ''
	if @phone_number is null set @phone_number = ''
	if @address is null set @address = ''

	set @phone_number =  REPLACE(@phone_number,'-','')
	set @phone_number =  REPLACE(@phone_number,' ','')

	if charindex('%', @customer_email) > 0 set @partial_email_search = 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check for minimum search terms	
	--	NOTE: need to better flush out what restriction we need to make
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if (len(@customer_email) < 1 and len(@first_name) < 1 and len(@last_name) < 1 and len(@company_name) < 1 and len(@vendor_customer_code) < 1 and len(@phone_number) < 1 and len(@address) < 1 )
		begin
			set @response_code = -100
			set @message = 'Minimum search term violation'
			return
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return list of customer_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	
	-- 3.1) set up table
	
	declare @customer_account table (customer_account_id int identity(1,1), customer_id int, account_id int, account_order_staging_id int, search_text varchar(255) null)

	-- 3.2) get matching customers
	if len(@vendor_customer_code) > 0 
		begin
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from vendor_customer c with (nolock)
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where c.vendor_customer_code = @vendor_customer_code
		end
	else if len(@phone_number) > 0 
		begin
			set @phone_number = @phone_number + '%'
			insert into @customer_account(customer_id,account_id) 
			select ac.customer_id, ac.account_id
			from account_customer ac with (nolock)
			left join  customer_phone cp with (nolock)
				on ac.customer_id = cp.customer_id
			where replace(replace(cp.phone_number,'-',''),' ','') like @phone_number
		end

	else if len(@address) > 0 
		begin
			set @address = @address + '%'
			insert into @customer_account(customer_id,account_id) 
			select ca.customer_id, ac.account_id
			from account_customer ac with (nolock)
			full join  customer_address ca with
 (nolock)
				on ac.customer_id = ca.customer_id
			where ca.address_1 like @address
		end

	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) > 1 and len(@company_name) > 1)
		begin
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @customer_email = @customer_email + '%'
			set @company_name = @company_name + '%'
			
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			inner join customer_email ce with (nolock) 
					on c.customer_id = ce.customer_id and ce.email_status_id = 1
			inner join customer_company cc with (nolock) 
					on c.customer_id = cc.customer_id
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where c.first_name like @first_name and c.last_name like @last_name
				and ce.customer_email like @customer_email
				and cc.company_name like @company_name
		end
		
	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) > 1 and len(@company_name) = 0)
		begin
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @customer_email = @customer_email + '%'

			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			inner join customer_email ce with (nolock) 
				on c.customer_id = ce.customer_id and ce.email_status_id = 1
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where c.first_name like @first_name and c.last_name like @last_name
				and ce.customer_email like @customer_email
		end

	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) < 1 and len(@company_name) < 1)
		begin
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where c.first_name like @first_name and c.last_name like @last_name
		end
	else if ((len(@first_name) = 0  and len(@last_name) = 0) and len(@customer_email) > 1 and len(@company_name) > 1)
		begin
			set @customer_email = @customer_email + '%'
			set @company_name = @company_name + '%'
			
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			inner join customer_email ce with (nolock)	
				on c.customer_id = ce.customer_id and ce.email_status_id = 1
			inner join customer_company cc with (nolock) 
				on c.customer_id = cc.customer_id
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where ce.customer_email like @customer_email and cc.company_name like @company_name
		end
	else if ((len(@first_name) = 0 and len(@last_name) = 0) and len(@customer_email) = 0 and len(@company_name) > 1)
		begin
			set @company_name = @company_name + '%'
			
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			inner join customer_company cc with (nolock) 
				on c.customer_id = cc.customer_id
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where cc.company_name like @company_name
		end
	else if (len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) = 0 and len(@company_name) > 1
		begin
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @company_name = @company_name + '%'
			
			insert into @customer_account(customer_id,account_id) 
			select c.customer_id, ac.account_id
			from customer c with (nolock)
			inner join customer_company cc with (nolock) 
				on c.customer_id = cc.customer_id
			left join account_customer ac with (nolock)
				on c.customer_id = ac.customer_id
			where c.first_name like @first_name and c.last_na
me like @last_name
				and cc.company_name like @company_name
		end
	else if ((len(@first_name) = 0 and len(@last_name) = 0) and len(@customer_email) > 1 and len(@company_name) = 0)
		begin

		declare @customers table (customer_id int,first_name nvarchar(225),middle_name nvarchar(32),last_name nvarchar(225),title nvarchar(50),opt_in int,customer_email_id int,customer_email varchar(100),customer_company_id int,company_name nvarchar(255),language_id int,vendor_id int, search_text varchar(255) null)

		if @partial_email_search = 1 
		begin
			set @customer_email = replace(@customer_email, '%', '') + '%' --this ensures we do search with wildcard at end of email string

		    insert into @customers(customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id)
		    select c.customer_id,c.first_name,c.middle_name,c.last_name,c.title,c.opt_in,ce.customer_email_id,ce.customer_email,cc.customer_company_id,cc.company_name,cl.language_id,vc.vendor_id 
		    from customer c with (nolock)
		    join customer_email ce with (nolock)
			    on ce.customer_id = c.customer_id
		    left join customer_language cl with (nolock)
			    on cl.customer_id = c.customer_id
		    left outer join customer_company cc with (nolock)
			    on cc.customer_id = c.customer_id
		    left outer join vendor_customer vc with (nolock)
			    on vc.customer_id = c.customer_id
		    where ce.customer_email like @customer_email and ce.email_status_id = 1
        end
        else
        begin
		    insert into @customers(customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id)
		    select c.customer_id,c.first_name,c.middle_name,c.last_name,c.title,c.opt_in,ce.customer_email_id,ce.customer_email,cc.customer_company_id,cc.company_name,cl.language_id,vc.vendor_id 
		    from customer c with (nolock)
		    join customer_email ce with (nolock)
			    on ce.customer_id = c.customer_id
		    left join customer_language cl with (nolock)
			    on cl.customer_id = c.customer_id
		    left outer join customer_company cc with (nolock)
			    on cc.customer_id = c.customer_id
		    left outer join vendor_customer vc with (nolock)
			    on vc.customer_id = c.customer_id
		    where ce.customer_email = @customer_email and ce.email_status_id = 1
        end

		if (select count(*) from @customers) = 0 and @partial_email_search = 0
		begin

		    declare @email_domain varchar(100)			
		    select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

		    declare @domain_emails int		
		    select @domain_emails = count(*)
		    from customer_email
		    where email_domain = @email_domain

		    if @domain_emails <= 30
		    begin
			    insert into @customers(customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id, search_text)
			    select c.customer_id,c.first_name,c.middle_name,c.last_name,c.title,c.opt_in,ce.customer_email_id,ce.customer_email,cc.customer_company_id,cc.company_name,cl.language_id,vc.vendor_id,'*.' + @email_domain
			    from customer_email ce
			    inner join customer c with (nolock)
				    on ce.customer_id = c.customer_id
			    left join customer_language cl with (nolock)
				    on cl.customer_id = c.customer_id
			    left outer join customer_company cc with (nolock)
				    on cc.customer_id = c.customer_id
			    left outer join vendor_customer vc with (nolock)
				    on vc.customer_id = c.customer_id
			    where ce.email_domain = @email_domain and ce.email_status_id = 1
			end

		end

        insert into @customer_account(customer_id,account_id,search_text) 
        select distinct c.customer_id, ac.account_id, c.search_text
        from @customers c
        left join account_customer ac with (nolock)
	        on 
c.customer_id = ac.customer_id
		end

	-- 3.3) get accounts
		if len(@customer_email) > 1 
			begin
				if @partial_email_search = 1 
				begin
					set @customer_email = replace(@customer_email, '%', '') + '%' --this ensures we do search with wildcard at end of email string

					insert into @customer_account(customer_id, account_id) 
					select c.customer_id, a.account_id
					from account a with (nolock)
					left join account_customer c with (nolock)
						on a.account_id = c.account_id
					left join @customer_account ca 
						on ca.account_id = c.account_id and ca.customer_id = c.customer_id
					where account_user_name like @customer_email and ca.customer_account_id is null
				end
				else
				begin
					insert into @customer_account(customer_id, account_id) 
					select c.customer_id, a.account_id
					from account a with (nolock)
					left join account_customer c with (nolock)
						on a.account_id = c.account_id
					left join @customer_account ca 
						on ca.account_id = c.account_id and ca.customer_id = c.customer_id
					where account_user_name = @customer_email and ca.customer_account_id is null

					insert into @customer_account(account_order_staging_id)
					select ao.account_order_staging_id
					from @customer_account ca 
					inner join license l with (nolock) on l.customer_id = ca.customer_id 
					inner join account_order ao with (nolock) on ao.license_id = l.license_id 

					insert into @customer_account(account_order_staging_id)
					select aos.account_order_staging_id
					from account_order_staging aos with (nolock)
					inner join account_order ao with (nolock) on ao.account_order_staging_id = aos.account_order_staging_id
					left join @customer_account ca on ca.account_order_staging_id = aos.account_order_staging_id
					where aos.email = @customer_email
					and ca.account_order_staging_id is null

					if (select count(*) from @customer_account where account_order_staging_id is not null) = 0
					begin
						insert into @customer_account(account_order_staging_id)
						select max(aos.account_order_staging_id)
						from account_order_staging aos with (nolock)
						where aos.email = @customer_email
						group by account_order_staging_id
					end

				end

			end

	-- 3.4) return results

		if ((select count(*) from @customer_account) = 0) and (@domain_emails > 0) --this basically sets the number of domains found and returned to csi to show appropriate message
			insert into @customer_account(customer_id, account_id, search_text) select -1, @domain_emails, '*.' + @email_domain

		-- 3.4.2) record set
		select iif(aos.account_order_staging_id is not null, row_number() over(order by aos.account_order_staging_id asc), customer_account.customer_id) as customer_id, customer_account.account_id, al.license_id, search_text,
			c.first_name, c.last_name, isnull(ce.customer_email, e.customer_email) as customer_email, cc.company_name, aos.account_order_staging_id, aos.email,
			licenses = (select count(*) from license where customer_id = customer_account.customer_id),
			licenses_active = (select count(distinct license_id) from license where license_status_id = 1 and customer_id = customer_account.customer_id),
			licenses_disabled = (select count(distinct license_id) from license where license_status_id in (2,3) AND customer_id = customer_account.customer_id)
		from @customer_account customer_account
		left join customer c with (nolock)
			on c.customer_id = customer_account.customer_id
		left join customer_email e with (nolock)
			on e.customer_id = customer_account.customer_id and e.email_status_id = 1
		left join customer_company cc with (nolock)
			on cc.customer_id = c.customer_id 
		left join account_license al with (nolock)
			on customer_account.account_id = al.account_id
		left join account_order_staging aos with (nolock)
			on aos.account_order_staging_id = customer_account.account_order_staging_id
		left join account_order ao with (nolock)
			on ao.account_order_staging_id = aos.account_
order_staging_id
		left join license l with (nolock)
			on l.license_id = ao.license_id
		left join customer_email ce with (nolock)
			on ce.customer_id = l.customer_id and ce.email_status_id = 1
		order by c.last_name, c.first_name, c.customer_id

	if @@error > 0
		begin
			set @response_code = -300
			set @message = 'General SQL select error'
			return
		end;


GO
