CREATE PROCEDURE [dbo].[usp_account_select_eula]

(
	@account_hash_id varchar(65)
)

/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	
	DESCRIPTION
	usp_account_select_eula
	
*/

AS
	
	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100)

	select ae.eula_accepted, l.license_id, l.keycode
	from account_eula ae
	left join license l on l.license_id = ae.license_id
	where ae.account_hash_id = @account_hash_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_account_select_eula'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;

GO
