-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_select_license_all]

(
	@account_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-08-05	esmart		Initial creation.

	DESCRIPTION
	select licenses by acount_id
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @licenses table (license_id int, keycode varchar(40), phone_number varchar(64), device_guid varchar(50), license_status_id int, license_status_description varchar(20), license_category_id tinyint, license_category_name varchar(20), insert_date datetime, modified_date datetime)

	insert into @licenses(license_id, keycode, phone_number, device_guid, license_status_id, license_status_description, license_category_id, license_category_name, insert_date, modified_date)
	select l.license_id, 
			l.keycode, 
			ad.phone_number, 
			ad.device_guid, 
			s.license_status_id,
			s.license_status_description,
			lc.license_category_id,
			lc.license_category_name,
			l.insert_date,
			l.modified_date	
	from license l
	inner join license_status s with (nolock)
		on l.license_status_id = s.license_status_id
	left join license_category_license lcl with (nolock)
		on l.license_id = lcl.license_id
	left join license_category lc with (nolock)
		on lcl.license_category_id = lc.license_category_id
	left join account_device ad 
		on l.license_id = ad.license_id
	where ad.account_id = @account_id

	insert into @licenses(license_id, keycode, license_status_id, license_status_description, license_category_id, license_category_name, insert_date, modified_date)
	select l.license_id, 
			l.keycode, 
			s.license_status_id,
			s.license_status_description,
			lc.license_category_id,
			lc.license_category_name,
			l.insert_date,
			l.modified_date	
	from license l
	inner join license_status s with (nolock)
		on l.license_status_id = s.license_status_id
	left join license_category_license lcl with (nolock)
		on l.license_id = lcl.license_id
	left join license_category lc with (nolock)
		on lcl.license_category_id = lc.license_category_id
	left join account_license al 
		on l.license_id = al.license_id
	where al.account_id = @account_id and l.license_id not in (select license_id from @licenses)

	select license_id, keycode, phone_number, device_guid, license_status_id, license_status_description, license_category_id, license_category_name, insert_date, modified_date
	from @licenses

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_select_licenses]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_account_select_licenses]

(
		@account_id int 
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-03	esmart		Initial creation.
	2010-06-21	dsmelker	Added loop to generate the seats_used count
	2010-10-18	esmart		Performance modifications

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@license_cnt int,
			@loop_cnt int,
			@license_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select license activation count by license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @license_activation_count table
		(license_activation_count int)

		declare @license_activation table
		(license_id int,
		 license_activation_count int)

		declare @account_license table
		(record_id int identity(1,1),
		 license_id int)

		insert into @account_license
		select distinct license_id
		from account_license with(nolock)
		where account_id = @account_id

		set @loop_cnt = 1

		select @license_cnt = count(*)
		from @account_license


		while @loop_cnt <= @license_cnt
		Begin

			select @license_id = license_id
			from @account_license
			where record_id = @loop_cnt


			delete from @license_activation_count

			insert into @license_activation_count
			exec usp_license_select_activation_count_csi @license_id

			insert into @license_activation
			select @license_id, license_activation_count
			from @license_activation_count


			set @loop_cnt = @loop_cnt + 1

		end
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select distinct a.account_id, a.license_id,
--				license_category = (select license_category = case
--												when count(*) = 4 then 'WISE'
--												when count(*) in (2,3) then 'WAV'
--												when count(*) = 1 then 'SS'
--												else 'NA'
--											end
--									from license_capability
--									where license_id = l.license_id and capability_type_id = 1),
				license_category_name = isnull(lc.license_category_name,'NA'),
				license_category_description = isnull(lc.license_category_description,'NA'), 
				l.keycode, 
				dashed_keycode = dbo.fn_AddDashes(keycode), 
				machine_name_list = dbo.udf_license_select_activation_machine_name_list(l.license_id),
				max_capability_expiration_date = c.capability_expiration_date,
				license_seats = case
									when s.license_seats is null then 1
									else s.license_seats
								end,
				seats_used = isnull(license_activation_count,1)
		from account_license a with (nolock)
		inner join license l with (nolock)
			on a.license_id = l.license_id
		left join license_category_license lcl with (nolock)
			on a.license_id = lcl.license_id
		left join license_category lc with (nolock)
			on lcl.license_category_id = lc.license_category_id
		left join license_capability c with (nolock)
			on a.license_id = c.license_id and c.capability_id = isnull(lc.base_capability_id,1)
		left join license_seat s with (nolock)
			on a.license_id = s.license_id
		left join @license_activation la
			on a.license_id = la.license_id
		where a.account_id = @account_id

	
	end try
	begin catch

		set @resp
onse_code = -200
		set @message = case when @message is null then 'insert account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
