-- PROCEDURE: [dbo].[usp_account_select_verification_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_select_verification_message]

(
	@email VARCHAR(100)
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2019-10-24		mrobbins	added check in to message_service_response for sent WATERBEARS-1168
	2020-01-28		mrobbins	added message_service_type_id 5 to list WATERBEARS-1642
	2020-10-22		g.lagos		modified the initial assesment to return Status Verified when message_service_vendor_response_status is NULL LAGER-2000
	
	DESCRIPTION
	usp_account_select_verification_message
	
*/

AS

	SET NOCOUNT ON

	BEGIN TRY

	DECLARE @response_code INT,
			@message VARCHAR(100),
			@error_message INT 


	IF EXISTS (select 1
				FROM message_service_archive msa
				INNER JOIN account_order_staging aos 
					ON msa.customer_email = aos.email
				INNER JOIN dbo.message_service_response msr
					ON msr.message_service_id = msa.message_service_id
				WHERE aos.email = @email
					AND msa.message_service_type_id IN (1,5) --wifi_account_create
					AND msa.message_service_status_id = 2
					AND ISNULL(msa.message_service_vendor_response_status,'sent') = 'sent') 
																					/* g.l. this inclusion is to fix the BAD status for some records */
																					/* that weren't update properly during the account verification process STORY LAGER-2000*/
		SELECT 'verified' AS status
	ELSE
		SELECT null AS status

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'error in usp_account_select_verification_message'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_update_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_update_account]

(
		@account_id int,
		@account_user_name varchar(100), 
		@account_password varchar(64), 
		@password_hint varchar(50), 
		@account_type_id int, 
		@account_status_id int, 
		@parent_account_id int, 
		@modified_date datetime,
		@modified_by  varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.
	2011-10-01	esmart		Add prevx_update_license insert
	2015-05-13	esmart		Add password_reset_date
	2019-12-17	esmart		Check for @license_id on account

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @current_account_password varchar(64),
			@password_reset_date datetime,
			@response_code int,
			@message varchar(100),
			@license_id int

	select @response_code = 0

	if @modified_by = '' or @modified_by is null 
		begin
		select @modified_by = suser_sname()
		end
		
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check username

	select @response_code = case when count(*) > 0 then -110 else 0 end,
			@message = case when count(*) > 0 then 'Account user name already exists' else '' end
	from account 
	where account_user_name = @account_user_name and account_id <> @account_id

	if @response_code < 0
		begin
		select response_code = @response_code, message = @message
		return
		end

	-- 1.2) license
	select @license_id = license_id
	from account_license
	where account_id = @account_id

	-- 1.3) @current_account_password
	select @current_account_password = account_password, @password_reset_date = password_reset_date
	from account 
	where account_id = @account_id

	if @current_account_password <> @account_password 
		begin
		select @password_reset_date = getdate()
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) insert audit record

	insert into account_audit(account_id, account_user_name, account_password, password_hint, account_type_id, account_status_id, parent_account_id, insert_date, insert_by, modified_date, modified_by, history_by)
	select account_id, account_user_name, account_password, password_hint, account_type_id, account_status_id, parent_account_id, insert_date, insert_by, modified_date, modified_by, @modified_by
	from account
	where account_id = @account_id

	-- 2.1) update account
	update account 
	set account_user_name = @account_user_name, 
		account_password = @account_password, 
		password_hint = @password_hint, 
		account_type_id = @account_type_id, 
		account_status_id = @account_status_id, 
		parent_account_id = @parent_account_id, 
		modified_date = @modified_date,
		modified_by = @modified_by,
		password_reset_date = @password_reset_date
	where account_id = @account_id

	select response_code = @response_code, message = 'account updated successfully'


	if @license_id is not null
		begin
	
		-- 2.2) update licensing
				declare @load_type int, 
						@dbsource varchar(100)
	
				select @dbsource = db_name(),
						@load_type = 6

				exec [tasks].[dbo].[usp_Licensing_Send_Tasks] @license_id = @license_id,@load_type=@load_type,@dbsource = @dbsource

		-- 2.3)
 prevx_update_license 
			insert into prevx_update_license(license_id) values(@license_id)
		
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_update_account_device]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_update_account_device]

(
	@account_user_name varchar(100),
	@keycode varchar(40),
	@phone_number varchar(64),
	@device_guid varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-25	esmart		Initial creation.
	2011-03-23	esmart		Remove more non-numeric from phone number

	DESCRIPTION
	insert/update account device record

*/

AS
	set nocount on				

	declare	@account_device_id int,
			@account_id int,
			@license_id int,
			@current_account_id int,
			@current_license_id int,
			@current_device_guid varchar(50),
			@last_modified_date datetime,
			@last_modified_by varchar(20),
			@account_license_license_id int,
			@account_license_license_category_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	select @last_modified_date = getdate(), @last_modified_by = suser_sname(), @response_code = 0, @message = 'Success'

	-- 1.1) @account_id
	select @account_id = account_id
	from account
	where account_user_name = @account_user_name

	if @account_id is null
		begin	
			set @response_code = -111
			set @message = 'Account does not exist'
			select response_code = @response_code, message = @message
			return	
		end		

	-- 1.2) @license_id
	select @license_id = license_id
	from license
	where keycode = @keycode

	if @license_id is null
		begin	
			set @response_code = -121
			set @message = 'License does not exist'
			select response_code = @response_code, message = @message
			return	
		end

	-- 1.3) clean phone_number (no spaces/no dashes)
	select @phone_number = replace(replace(replace(replace(replace(@phone_number,'-',''),' ',''),'+',''),')',''),'(','')

	-- 1.4) get existing account and account_device_date data
	if @phone_number is not null or @phone_number <> ''
		-- 1.4.1) phone
		begin
		select @account_device_id = account_device_id,
				@current_account_id = account_id,
				@current_license_id = license_id,
				@current_device_guid = device_guid
		from account_device
		where phone_number = @phone_number
		end
		-- 1.4.2) tablet
	else
		begin
		select @account_device_id = account_device_id,
				@current_account_id = account_id,
				@current_license_id = license_id
		from account_device
		where device_guid = @device_guid
		end
	
--select	account_device_id = @account_device_id,
--		current_account_id = @current_account_id,
--		account_id = @account_id,
--		current_license_id = @current_license_id,
--		license_id = @license_id,
--		current_device_guid = @current_device_guid,
--		device_guid = @device_guid

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @account_device_id is null
	-- 2.1) insert account_device
		begin
--		select '2.1) insert'
			insert into account_device(account_id, license_id, phone_number, device_guid)
			values(@account_id, @license_id, @phone_number, @device_guid)
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
-- 3.) update 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @account_device_id is not null and (@account_id <> @current_account_id or @license_id <> @current_license_id or @device_guid <> @current_device_guid)
		begin
--		select '3.1) update'
			
			-- 3.1) insert audit record
			insert into account_device_audit(account_device_id, account_id, license_id, phone_number, device_guid, last_modified_date, last_modified_by, audit_date, audit_by)
			select account_device_id, account_id, license_id, phone_number, device_guid, last_modified_date, last_modified_by, audit_date = @last_modified_date, audit_by = @last_modified_by
			from account_device
			where account_device_id = @account_device_id
	
			-- 3.2) update account_device
			update account_device
			set account_id = @account_id,
				license_id = @license_id,
				phone_number = @phone_number,
				device_guid = @device_guid,
				last_modified_date = @last_modified_date,
				last_modified_by = @last_modified_by
			where account_device_id = @account_device_id

			-- 3.3) update account_license if Android only account
			select @account_license_license_id = al.license_id,
					@account_license_license_category_id = cl.license_category_id
			from account_license al
			inner join license_category_license cl
				on al.license_id = cl.license_id
			where account_id = @account_id

--select account_license_license_id = @account_license_license_id, account_license_license_category_id = @account_license_license_category_id

			if @account_license_license_id = @current_license_id and @account_license_license_category_id = 50 and (@current_license_id <> @license_id)
				begin
--				select '3.3.1) archive current account_license data'
				-- 3.3.1) archive current account_license data
				insert into account_license_audit(account_license_id, account_id, license_id, license_change_reason_id, last_modified_date, last_modified_by, audit_date, audit_by)
				select account_license_id, account_id, license_id, license_change_reason_id = 25, last_modified_date, last_modified_by, audit_date = @last_modified_date, audit_by = @last_modified_by	
				from account_license
				where account_id = @account_id

				-- 3.3.2) update account_license with new license_id
				update account_license
				set license_id = @license_id, last_modified_date = @last_modified_date, last_modified_by = @last_modified_by	
				where account_id = @account_id	

				-- 3.3.3) add record to license_check_license to force update (can drop this once we have this added to the license_check process)
				insert into license_check_update_license(license_id,source) values(@license_id,2)
				insert into license_check_update_license(license_id,source) values(@current_license_id,2)

				end		
		end

	-- 2.3) return result
	select response_code = @response_code, message = @message

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_update_account_license]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_account_update_account_license]

(
	@account_id int,
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-05-20	esmart		Initial creation.
	2010-03-08	esmart		Add account_device support	

	DESCRIPTION
	update license on account_license
*/

AS
	set nocount on

begin try

		declare @current_license_id int,
				@modified_date datetime,
				@modified_by varchar(20),
				@response_code int,
				@message varchar(100)

		select @modified_date = getdate(),
				@modified_by = suser_sname()

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 1) get data
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) get current license_id for the account
		select @current_license_id = license_id from account_license where account_id = @account_id

		-- 1.2) check to see if new license is already associated with an account
		if (select count(*) from account_license where license_id = @license_id) > 0
			begin
			select @response_code = -120,
					@message = 'new license assoicated with account'
			return
			end

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 2) update license
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) archive current account_license data
		insert into account_license_audit(account_license_id, account_id, license_id, license_change_reason_id, last_modified_date, last_modified_by, audit_date, audit_by)
		select account_license_id, account_id, license_id, license_change_reason_id = 25, last_modified_date, last_modified_by, audit_date = @modified_date, audit_by = @modified_by	
		from account_license
		where account_id = @account_id

		-- 2.2) update account_license with new license_id
		update account_license
		set license_id = @license_id, last_modified_date = @modified_date, last_modified_by = @modified_by	
		where account_id = @account_id

		-- 2.3) archive account_device data
		insert into account_device_audit(account_device_id, account_id, license_id, phone_number, device_guid, last_modified_date, last_modified_by, audit_date, audit_by)
		select account_device_id, account_id, license_id, phone_number, device_guid, last_modified_date, last_modified_by, audit_date = @modified_date, audit_by = @modified_by	
		from account_device
		where account_id = @account_id and license_id = @current_license_id

		-- 2.4) update account_device with new license_id
		update account_device
		set license_id = @license_id, last_modified_date = @modified_date, last_modified_by = @modified_by	
		where account_id = @account_id and license_id = @current_license_id
		
		-- 2.3) add record to license_check_license to force update (can drop this once we have this added to the license_check process)
		insert into license_check_update_license(license_id,source) values(@license_id,3)
		insert into license_check_update_license(license_id,source) values(@current_license_id,3)

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
