	DESCRIPTION
	usp_account_update_account_order_staging
	
*/

AS
	
	set nocount on

	begin try

	declare @response_code int,
			@message varchar(100)

	update account_order_staging
	set account_hash_id = isnull(@account_hash_id, account_hash_id),
		pending_account_id = isnull(@pending_account_id, pending_account_id),
		order_receipt = isnull(@order_receipt, order_receipt),
		vendor_order_date = isnull(@vendor_order_date, vendor_order_date),
		vendor_expiration_date = isnull(@vendor_expiration_date, vendor_expiration_date),
		apple_notification_id = isnull(@apple_notification_id, apple_notification_id),
		google_notification_id = isnull(@google_notification_id, google_notification_id),
		modified_date = getdate()
	where account_order_staging_id = @account_order_staging_id

	end try

	begin catch

