		--	end

		---- 2.2.3) insert lastpass CreateAccount queue record
		--if @password_management_enabled = 1
		--	begin
		--	declare @lastpass_update_type_id tinyint
					
		--	-- 2.2.3.1) prevx?	
		--	select @lastpass_update_type_id = case
		--										when e.encryption_key_hash is null then 1
		--										else 11
