CREATE PROCEDURE [dbo].[usp_account_update_queue_reconciliation]

(
	@account_user_name varchar(100),
	@insert_by varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-11	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@account_id int,
			@license_id int,
			@storage_gb int,
			@storage_plan_code varchar(20),
			@process_date datetime,
			
			@backup_capability_expiration_date datetime,
			@sugarsync_account_status varchar(20),
			@sugarsync_update_id int,
			@sugarsync_update_type_id tinyint,
			@sugarsync_plan_code varchar(20),
			@sugarsync_update_status_id tinyint,

			@password_management_capability_expiration_date datetime,
			@lastpass_update_id int,
			@lastpass_update_type_id tinyint,
			@lastpass_response_text varchar(100),
			@lastpass_update_status_id tinyint,

			@account_reconciliation_id int,

			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) add row to account_reconciliation
		insert into account_reconciliation(account_user_name, reconciliation_type, insert_by) values(@account_user_name, 'fix queue', @insert_by)
	
		select @account_reconciliation_id = scope_identity()

		-- 1.2) get account data
		select @account_id = a.account_id,
				@license_id = al.license_id,
				@storage_gb = ls.storage_gb,
				@storage_plan_code = convert(varchar(8),ls.storage_gb)+'GB'
		from account a
		inner join account_license al
			on a.account_id = al.account_id
		inner join license l
			on al.license_id = l.license_id
		inner join license_storage ls
			on al.license_id = ls.license_id
		where a.account_user_name = @account_user_name

		-- 1.3) get correct state of SugarSync based on ecommerce_data
		select @backup_capability_expiration_date = capability_expiration_date
		from license_capability
		where license_id = @license_id and capability_id = 11 and capability_type_id in (1,9) and capability_expiration_date > getdate()

		-- 1.4) get correct state of SugarSync based on ecommerce_data
		select @sugarsync_account_status = status,
				@sugarsync_plan_code = plan_code		 
		from sugarsync_reconciliation
		where account_user_name = @account_user_name

		-- 1.5) get current sugarsync_update queue data
		select @sugarsync_update_id = sugarsync_update_id, @sugarsync_update_type_id = sugarsync_update_type_id
		from sugarsync_update
		where account_id = @account_id
--
--select * from sugarsync_update where account_id = @account_id
--select * from sugarsync_reconciliation where account_user_name = @account_user_name

		-- 1.6  Password Management 17
		select @password_management_capability_expiration_date = capability_expiration_date
		from license_capability
		where license_id = @license_id and capability_id = 17 and capability_type_id in (1,9) and capability_expiration_date > getdate()

		-- 1.7) get current sugarsync_update queue data
		select @lastpass_update_id = lastpass_update_id, @lastpass_update_type_id = lastpass_update_type_id
		from lastpass_update
		where account_id = @account_id

		-- 1.8) get current sugarsync_update queue data
		select @lastpass_response_text = response_text
		from lastpass_reconciliation
		where account_id = @account_id

--		select backup_capability_expiration_date = @backup_capability_expiration_date,
--				sugars
ync_account_status = @sugarsync_account_status,
--				storage_gb = @storage_gb,
--				storage_plan_code = @storage_plan_code,
--				sugarsync_update_id = @sugarsync_update_id,
--				sugarsync_update_type_id = @sugarsync_update_type_id,
--				lastpass_update_id = @lastpass_update_id,
--				lastpass_update_type_id = @lastpass_update_type_id,			
--				password_management_capability_expiration_date = @password_management_capability_expiration_date,
--				lastpass_response_text = @lastpass_response_text
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) sugarsync insert or update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @sugarsync_update_id is null	
		-- 2.1) sugarsync insert path
		begin
		-- 2.1.1) reactivate inactive account
		if @sugarsync_account_status = 'inactive' and @backup_capability_expiration_date > getdate()
			begin
				select @sugarsync_update_type_id = 8, @process_date = getdate()
				exec usp_sugarsync_insert_account_update @account_id, @sugarsync_update_type_id, 0, @storage_plan_code, @process_date
			end

		-- 2.1.2) create suspend service record
		if @sugarsync_account_status = 'active' and @backup_capability_expiration_date > getdate()
			begin
				select @sugarsync_update_type_id = 6, @process_date = @backup_capability_expiration_date
				exec usp_sugarsync_insert_account_update @account_id, @sugarsync_update_type_id, 0, @storage_plan_code, @process_date
			end

		-- 2.1.2) create suspend service record
		if @sugarsync_account_status is null and @backup_capability_expiration_date > getdate()
			begin
				select @sugarsync_update_type_id = 9, @process_date = getdate()
				exec usp_sugarsync_insert_account_update @account_id, @sugarsync_update_type_id, 0, @storage_plan_code, @process_date
			end


		end
	else
		-- 2.2) sugarsync update path
		begin
		--select '2.2) sugarsync update path'
		-- 2.2.1) reactivate inactive account
		if @sugarsync_account_status = 'inactive' and @backup_capability_expiration_date > getdate()
			begin
				select @sugarsync_update_status_id = 3

				insert into sugarsync_update_archive(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
				select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date = getdate(), process_date
				from sugarsync_update
				where sugarsync_update_id = @sugarsync_update_id

				update sugarsync_update set sugarsync_update_type_id = 8, plan_code = @storage_plan_code, process_date = getdate() where sugarsync_update_id = @sugarsync_update_id
			end
		
		-- 2.2.2) update plan_code
		if @sugarsync_update_type_id = 6 and convert(int,replace(@sugarsync_plan_code,'GB','')) < @storage_gb
			begin
				select @sugarsync_update_status_id = 3

				insert into sugarsync_update_archive(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
				select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date = getdate(), process_date
				from sugarsync_update
				where sugarsync_update_id = @sugarsync_update_id

				update sugarsync_update set sugarsync_update_type_id = 10, plan_code = @storage_plan_code, process_date = getdate() where sugarsync_update_id = @sugarsync_update_id
			end
		end

	-- ----------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------
	-- 3.) lastpass insert or update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @lastpass_update_id is null	
	-- 3.1) lastpass insert path
		begin
		-- 3.1.1) reactivate inactive account
		if @lastpass_response_text = 'DEACTIVATED' and @password_management_capability_expiration_date > getdate()
			begin
				select @lastpass_update_type_id = 8, @process_date = getdate()
				exec usp_lastpass_insert_account_update @account_id, @lastpass_update_type_id, 0, @process_date
			end

		-- 3.1.2) reactivate inactive account
		if @lastpass_response_text = 'ACTIVATED' and @password_management_capability_expiration_date > getdate()
			begin
				select @lastpass_update_type_id = 6, @process_date = @password_management_capability_expiration_date
				exec usp_lastpass_insert_account_update @account_id, @lastpass_update_type_id, 0, @process_date
			end

		-- 3.1.3) create account
		if @lastpass_response_text = 'emaildoesnotexist' and @password_management_capability_expiration_date > getdate()
			begin
				select @lastpass_update_type_id = 9, @process_date = getdate()
				exec usp_lastpass_insert_account_update @account_id, @lastpass_update_type_id, 0, @process_date
			end

		end
	else
		begin
		-- 3.1.4) create account
		if @lastpass_response_text = 'emaildoesnotexist' and @password_management_capability_expiration_date > getdate()
			begin
				
				select @lastpass_update_type_id = 9, @process_date = getdate(), @lastpass_update_status_id = 3

				insert into lastpass_update_archive(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
				select lastpass_update_id, account_id, lastpass_update_type_id, @lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, getdate(), process_date
				from lastpass_update
				where lastpass_update_id = @lastpass_update_id

				update lastpass_update set lastpass_update_type_id = @lastpass_update_type_id, process_date = @process_date, update_attempts = 0 where lastpass_update_id = @lastpass_update_id
			end
		-- 3.1.5) create account
		if @lastpass_response_text = 'DEACTIVATED' and @password_management_capability_expiration_date > getdate()
			begin
				select @lastpass_update_type_id = 8, @process_date = getdate(), @lastpass_update_status_id = 3

				insert into lastpass_update_archive(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
				select lastpass_update_id, account_id, lastpass_update_type_id, @lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, getdate(), process_date
				from lastpass_update
				where lastpass_update_id = @lastpass_update_id
				
				update lastpass_update set lastpass_update_type_id = @lastpass_update_type_id, process_date = @process_date, update_attempts = 0 where lastpass_update_id = @lastpass_update_id
			end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) update account_reconciliation
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	update account_reconciliation
	set status = 1
	where account_reconciliation_id = @account_reconciliation_id

	end try

--sugarsync_update_type_id	sugarsync_update_type_name
--1	S
SCreateAccount
--2	CreateChildAccount
--3	UpdateAccount
--4	UpdateUsername
--5	UpdatePassword
--6	SuspendService
--7	EndService
--8	ReactivateService
--9	BatchCreateAccount
--10	UpdatePlan
--11	UpdatePlanDowngrade
--12	EndServiceRecreate
--13	GetAccountInfo

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_update_rollback_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_update_rollback_account]

(
	@account_user_name varchar(100),
	@insert_by varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-11	esmart		Initial creation.
	2012-01-18	esmart		Check for other capability_type_id on backup capability

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@account_id int,
			@license_id int,
			@account_reconciliation_id int,

			@sugarsync_update_id int,
			@sugarsync_account_status varchar(20),
			@sugarsync_update_type_id tinyint,
			@sugarsync_update_status_id tinyint,

			@lastpass_update_id int,
			@lastpass_response_text varchar(100),
			@lastpass_update_type_id tinyint,
				
			@process_date datetime,
			@modified_date datetime,
			@response_code int,
			@message varchar(100)

			select @modified_date = getdate(), @process_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) add row to account_reconciliation
			insert into account_reconciliation(account_user_name, reconciliation_type, insert_by) values(@account_user_name, 'rollback', @insert_by)
	
			select @account_reconciliation_id = scope_identity()

		-- 1.2) get account identity columns
			select @account_id = a.account_id,
					@license_id = al.license_id
			from account a 
			inner join account_license al
				on a.account_id = al.account_id
			where a.account_user_name = @account_user_name

		-- 1.3) get sugarsync data
			select @sugarsync_update_id = sugarsync_update_id from sugarsync_update where account_id = @account_id

			select @sugarsync_account_status = status	 
			from sugarsync_reconciliation
			where account_user_name = @account_user_name

		-- 1.4) get lastpass data
			select @lastpass_update_id = lastpass_update_id from lastpass_update where account_id = @account_id

			select @lastpass_response_text = response_text
			from lastpass_reconciliation
			where account_id = @account_id
		
--		select account_id = @account_id, license_id = @license_id, sugarsync_update_id = @sugarsync_update_id, lastpass_update_id = @lastpass_update_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) create new queue records
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) archive account_license 
			insert into account_license_audit(account_license_id, account_id, license_id, license_change_reason_id, last_modified_date, last_modified_by, audit_date, audit_by)
			select account_license_id, account_id, license_id, license_change_reason_id = 25, last_modified_date, last_modified_by, audit_date = @modified_date, audit_by = @insert_by	
			from account_license
			where account_id = @account_id

			delete from account_license
			where account_id = @account_id

			-- 2.1.1) mar_user_account
			delete from mar_user_account
			where account_id = @account_id

		-- 2.2) update license_capability.capability_type_id for 3rd party capabilities		
			insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified
_by, audit_date, audit_by)
			select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = @modified_date, audit_by = @insert_by
			from license_capability
			where license_id = @license_id

			update license_capability
			set capability_type_id = 9, modified_date = @modified_date, modified_by = @insert_by
			where license_id = @license_id and capability_id in (11,17)

		-- 2.3) create sugarsync_update record
			if @sugarsync_update_id is null
				begin
				if @sugarsync_account_status is not null
					begin
					select @sugarsync_update_type_id = 13
					exec usp_sugarsync_insert_account_update @account_id, @sugarsync_update_type_id, 0, '0GB', @process_date
					end
				end
			else
				begin
				select @sugarsync_update_status_id = 3

				insert into sugarsync_update_archive(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
				select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date = @modified_date, process_date
				from sugarsync_update
				where sugarsync_update_id = @sugarsync_update_id

				update sugarsync_update set sugarsync_update_type_id = 13, process_date = @process_date where sugarsync_update_id = @sugarsync_update_id
				end

		-- 2.4) create lastpass_update record
			if @lastpass_update_id is null
				begin
				if @lastpass_response_text <> 'emaildoesnotexist' and @lastpass_response_text is not null
					begin
					select @lastpass_update_type_id = 10
					exec usp_lastpass_insert_account_update @account_id, @lastpass_update_type_id, 0, @process_date
					end
				end
			else
				begin
				select @sugarsync_update_status_id = 3

				insert into lastpass_update_archive(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
				select lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, @modified_date, process_date
				from lastpass_update
				where lastpass_update_id = @lastpass_update_id

				update lastpass_update set lastpass_update_type_id = 10, process_date = @process_date, update_attempts = 0 where lastpass_update_id = @lastpass_update_id
			
				end

		-- 2.5) delete licensing account data and insert license_check_update_license row
			-- 2.5.1) insert license_check_update_license
			insert into license_check_update_license(license_id,source) values(@license_id,4)

			-- 2.5.2) insert delete queue
			declare @load_type int, @dbsource varchar(100)
			
			select @dbsource = db_name(),@load_type = 10 -- Delete Account

			exec [tasks].[dbo].[usp_Licensing_Send_Tasks] @license_id = @license_id,@load_type=@load_type,@dbsource = @dbsource

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return result set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @account_reconciliation table(account_reconciliation_id int, account varchar(20), update_id int, account_id int, account_user_name varchar(100), new_account_user_name varchar(100), account_password varchar(64), update_type_id tinyint, update_type_name varchar(20), process_date datetime, plan_code varchar(10))

		-- 3.1) SugarSync
		insert into @account_reconciliation(account_reconciliation_id, account, update_id, account_id, account_user_name, new_account_user
_name, account_password, update_type_id, update_type_name, process_date, plan_code)
		select account_reconciliation_id = @account_reconciliation_id, account = 'sugarsync', update_id = u.sugarsync_update_id, a.account_id, a.account_user_name, new_account_user_name = convert(varchar(20),a.account_id)+'@webroot.com', a.account_password, update_type_id = t.sugarsync_update_type_id, update_type_name = t.sugarsync_update_type_name, u.process_date, u.plan_code
		from sugarsync_update u
		inner join sugarsync_update_type t
			on u.sugarsync_update_type_id = t.sugarsync_update_type_id
		inner join account a
			on u.account_id = a.account_id
		where u.account_id = @account_id
		
		-- 3.2) LastPass
		insert into @account_reconciliation(account_reconciliation_id, account, update_id, account_id, account_user_name, new_account_user_name, account_password, update_type_id, update_type_name, process_date, plan_code)
		select account_reconciliation_id = @account_reconciliation_id, account = 'lastpass', update_id = u.lastpass_update_id, a.account_id, a.account_user_name, new_account_user_name = convert(varchar(20),a.account_id)+'@webroot.com', a.account_password, update_type_id = t.lastpass_update_type_id, update_type_name = t.lastpass_update_type_name, u.process_date, plan_code = null
		from lastpass_update u
		inner join lastpass_update_type t
			on u.lastpass_update_type_id = t.lastpass_update_type_id
		inner join account a
			on u.account_id = a.account_id
		where u.account_id = @account_id

		-- 3.3) If WAV license with no 3rd party accounts
		if (select count(*) from @account_reconciliation) = 0 
			begin
			insert into @account_reconciliation(account_reconciliation_id)
			values(@account_reconciliation_id)
			end

		select account_reconciliation_id, account, update_id, account_id, account_user_name, new_account_user_name, account_password, update_type_id, update_type_name, process_date, plan_code
		from @account_reconciliation

	end try

--sugarsync_update_type_id	sugarsync_update_type_name
--1	SSCreateAccount
--2	CreateChildAccount
--3	UpdateAccount
--4	UpdateUsername
--5	UpdatePassword
--6	SuspendService
--7	EndService
--8	ReactivateService
--9	BatchCreateAccount
--10	UpdatePlan
--11	UpdatePlanDowngrade
--12	EndServiceRecreate
--13	GetAccountInfo

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_account_update_rollback_account_complete]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_account_update_rollback_account_complete]

(
	@account_reconciliation_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-17	esmart		Initial creation
	2011-12-12	esmart		Add delete from mar_user_account

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@account_id int,
			@account_user_name varchar(100),
			@modified_date datetime,
			@modified_by varchar(20),
			@response_code int,
			@message varchar(100)
	
	select @modified_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) @account_user_name
			select @account_id = a.account_id, @account_user_name = r.account_user_name, @modified_by = r.insert_by 
			from account_reconciliation r
			inner join account a
				on r.account_user_name = a.account_user_name
			where account_reconciliation_id = @account_reconciliation_id

		-- 1.2) archive account data and update
			insert into account_audit(account_id, account_user_name, account_password, password_hint, account_type_id, account_status_id, parent_account_id, insert_date, insert_by, modified_date, modified_by, history_date, history_by)
			select account_id, account_user_name, account_password, password_hint, account_type_id, account_status_id, parent_account_id, insert_date, insert_by, modified_date, modified_by, @modified_date, @modified_by
			from account
			where account_user_name = @account_user_name

			update account 
			set account_user_name = convert(varchar(20),account_id)+'@webroot.com',
				modified_date = @modified_date,
				modified_by = @modified_by
			where account_user_name = @account_user_name

		-- 1.3) delete sugarsync_reconciliation and lastpass_reconciliation
			delete from lastpass_reconciliation
			where account_user_name = @account_user_name
			
			delete from sugarsync_reconciliation
			where account_user_name = @account_user_name

		-- 1.4) archive mar_user_account
			
			delete from mar_user_account where account_id = @account_id
			
			
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
