-- =============================================================================
-- PROCEDURE: [dbo].[usp_affiliate_add_rc_code]
-- =============================================================================


CREATE procedure [dbo].[usp_affiliate_add_rc_code]
	(@new_rc_code varchar(48), --Company1
	@affiliate_category_id int,
	@first_name varchar(32) = 'n/a',
	@last_name varchar(32) = 'n/a',
	@title varchar(32) = 'n/a',
	@company2 varchar(48) = NULL,
	@address1 varchar(48) = 'n/a',
	@address2 varchar(48) = NULL,
	@city varchar(48) = 'n/a',
	@state_id char(2) = 'AA',
	@postal_code varchar(10) = 'n/a',
	@country_id smallint = 1,
	@telephone varchar(20) =  'n/a',
	@fax varchar(20) = NULL,
	@email varchar(64) =  'n/a',
	@description varchar(4000) = NULL,
	@referral_source_id smallint = 0,
	@referral_name varchar(50) = NULL,
	@affiliate_status_id smallint = 0,
	@tax_id varchar(32) = NULL,
	@business_type_id smallint = 0,
	@commissionable tinyint = 1,
	@min_check_amount int = 0,
	@payable_to varchar(48) = NULL,
	@applied_date datetime = NULL,
	@approved_date datetime = '1 / 1 / 2100',
	@notified_date datetime = '1 / 1 / 2100',
	@terminated_date datetime = '1 / 1 / 2100',
	@termination_code smallint = 0,
	@userid varchar(48) = 'NO USERID',
	@password varchar(16) = 'NO PASSWORD',
	@password_clue_id smallint = 0,
	@password_clue varchar(50) = NULL,
	@fiscal_month tinyint = 1,
	@fiscal_day tinyint = 1,
	@trial_availability tinyint = NULL,
	@last_modified datetime = null,
    @new_num int = null)
as

/*	
	DATE		AUTHOR		REMARKS
	2007-07-18	bjordan		Initial creation.
	2008-05-09	ybarkalov	Updated the logic to be able to start generating RCs
							for brand-new affiliate category 
	
	DESCRIPTION
	Creates a new RC Code based on an range of assigned_num 
	defined in lu_affiliate_categories by category_id
*/

SET NOCOUNT ON

BEGIN TRANSACTION

    DECLARE 
	    @maxcode VARCHAR(16) ,
	    @newcode VARCHAR(16) ,
	    @seed INT,
        @max_num INT,	
	    @cnt INT,
		@AffiliatePrefix char(1)

	if @affiliate_category_id = 18 --Support
		set @AffiliatePrefix = 'I'
	else
		set @AffiliatePrefix = 'A'

	select @maxcode = max( affiliate_code ) 
	from affiliates
	WHERE affiliate_code LIKE @AffiliatePrefix + '%'

	SELECT @seed = CONVERT( INT, RIGHT( @maxcode , LEN( @maxcode ) - 1 ) )
	SELECT @seed = @seed + 1

	SELECT @newcode = @AffiliatePrefix + REPLICATE( '0' , LEN( @maxcode ) - LEN ( @seed ) -1 ) + CONVERT( varchar,@seed )




/*
	-- 05/09/08 ybarkalov - backup of old logic that was not generating RCs
	--						for newly created affiliate categories
    SELECT @max_num = min(a.assigned_num) 
    FROM affiliates a
	inner join affiliate_category_members m
	on a.affiliate_code = m.affiliate_code
	inner join lu_affiliate_categories c on
	m.category_id = c.category_id
	WHERE a.assigned_num between c.assigned_num_min and c.assigned_num_max
	and m.category_id = @affiliate_category_id
*/

	if @new_num is null
		begin
		SELECT @max_num = Min(CASE WHEN m.affiliate_code IS NOT NULL THEN a.assigned_num ELSE c.assigned_num_min END)
			FROM lu_affiliate_categories c
				LEFT OUTER JOIN affiliates a
					ON a.assigned_num between c.assigned_num_min AND c.assigned_num_max
				LEFT OUTER JOIN affiliate_category_members m
					ON m.affiliate_code = a.affiliate_code
					AND m.category_id = c.category_id
			WHERE c.category_id = @affiliate_category_id
		end
	else
		set @max_num = @new_num
	
	--ensure the new assigned num is unique

	set @cnt = 0

	select @cnt = count(*)
	from affiliates
	where assigned_num = @max_num
	
	while @cnt > 0
		begin
		select @cnt = count(*)
		from affiliates
		where assigned_num = @max_num

		if @cnt > 0
			set @max_num = @max_num + 1

		end

	SET @NEW_NUM = @MAX_NUM

    INSERT INTO [affiliates]
           ([affiliate_code]
           ,[assigned_num]
           ,[assigned_num_str]
           ,[first_n
ame]
           ,[last_name]
           ,[title]
           ,[company1]
           ,[company2]
           ,[address1]
           ,[address2]
           ,[city]
           ,[state_id]
           ,[postal_code]
           ,[country_id]
           ,[telephone]
           ,[fax]
           ,[email]
           ,[description]
           ,[referral_source_id]
           ,[referral_name]
           ,[affiliate_status_id]
           ,[tax_id]
           ,[business_type_id]
           ,[commissionable]
           ,[min_check_amount]
           ,[payable_to]
           ,[applied_date]
           ,[approved_date]
           ,[notified_date]
           ,[terminated_date]
           ,[termination_code]
           ,[userid]
           ,[password]
           ,[password_clue_id]
           ,[password_clue]
           ,[fiscal_month]
           ,[fiscal_day]
           ,[trial_availability]
           ,[last_modified])
     VALUES
           (@newcode 
			,@new_num  -- assigned_num 
			,CONVERT(VARCHAR(12), @new_num)
			,@first_name
			,@last_name
			,@title
			,@NEW_RC_CODE
			,@company2
			,@address1
			,@address2
			,@city
			,@state_id
			,@postal_code
			,@country_id
			,@telephone
			,@fax
			,@email
			,@description
			,@referral_source_id
			,@referral_name
			,@affiliate_status_id
			,@tax_id
			,@business_type_id
			,@commissionable
			,@min_check_amount
			,@payable_to
			,isnull(@applied_date,getdate())
			,isnull(@approved_date,getdate())
			,isnull(@notified_date,getdate())
			,@terminated_date
			,@termination_code
			,@userid
			,@password
			,@password_clue_id
			,@password_clue
			,@fiscal_month
			,@fiscal_day
			,@trial_availability
			,isnull(@last_modified,getdate()))
	
    IF @@ERROR = 0
    begin
        INSERT INTO affiliate_category_members (affiliate_code,start_date,end_date,category_id,last_modified)
                VALUES (@newcode, cast(convert(varchar(12),getdate(),102) as datetime), '2100-12-31 00:00:00.000',@affiliate_category_id,GETDATE())
        IF @@ERROR = 0 
        begin
             COMMIT TRANSACTION
             SELECT @NEW_RC_CODE as affiliate, @newcode as affiliate_code, @new_num as rc 
        end
        ELSE
        begin
             ROLLBACK TRANSACTION       
             SELECT @NEW_RC_CODE, 'ERROR - NO RC CODE GENERATED!'
        end
    end
    ELSE
    begin
         ROLLBACK TRANSACTION       
         SELECT @NEW_RC_CODE, 'ERROR - NO RC CODE GENERATED!'
    end;

SET NOCOUNT OFF;



GO
