CREATE PROCEDURE dbo.usp_affiliate_insert_affiliate
  @first_name varchar(32),
  @last_name varchar(32),
  @title varchar(32),
  @company1 varchar(48),
  @address1 varchar(48),
  @address2 varchar(48),
  @city varchar(48),
  @state_id char(2),
  @postal_code varchar(10),
  @country_id smallint,
  @telephone varchar(20),
  @fax varchar(20),
  @email varchar(64),
  @tax_id varchar(32),
  @payable_to varchar(48),
  @description text,
  @business_type_id smallint,
  @url varchar(64),
  @unique_visitors_month  int,
  @page_views_month int,
  @referral_name varchar(50),
  @userid varchar(48),
  @password varchar(16),
  @password_clue varchar(50),
  @response_code int output,
  @message varchar(100) output

AS

  /*

    DATE    AUTHOR  REMARKS

    2006-09-05  esmart    Initial creation.

    DESCRIPTION

    Insert affiliate

  */

  set nocount on

  declare @affiliate_code varchar(13)
  -----------------------------------------------
  -- 1) Generate affiliate code
  -----------------------------------------------
  exec usp_affiliate_generate_affiliate_code @affiliate_code output

  -----------------------------------------------
  -- 2) Insert affiliate
  -----------------------------------------------
  begin transaction

  insert into affiliates (affiliate_code, assigned_num, assigned_num_str, 
                         first_name, last_name, title, company1, company2, 
                         address1, address2, city, state_id, postal_code, 
                         country_id, telephone, fax, email, description, 
                         referral_source_id, referral_name,
                         affiliate_status_id, tax_id, business_type_id, 
                         commissionable, min_check_amount, payable_to, 
                         applied_date, approved_date, notified_date, 
                         terminated_date, termination_code, userid, password, 
                         password_clue_id, password_clue, fiscal_month, 
                         fiscal_day, trial_availability, last_modified)
  values (@affiliate_code, null, null, @first_name, @last_name, @title, 
           @company1, '', @address1, @address2, @city, @state_id, 
           @postal_code , @country_id, @telephone, @fax, @email, @description, 
           0, @referral_name, 4, @tax_id, @business_type_id, 1, 50, @payable_to, 
           getdate(), '2100-01-01', '2100-01-01', '2100-01-01', 0, @userid, 
           @password, 0, @password_clue, 1, 1, null, getdate())

  if @@error <> 0
    begin
      rollback transaction
      set @response_code = -200
      set @message = 'General SQL Error - Affiliate insert'
      return
    end

  -----------------------------------------------
  -- 3) Insert affiliate_urls
  -----------------------------------------------
  insert into affiliate_urls (affiliate_code, url, site_category_id, unique_visitors_month, page_views_month, is_main, last_modified)
      values (@affiliate_code, @url, 0, @unique_visitors_month, @page_views_month, 1, getdate())

  if @@error <> 0
    begin
      rollback transaction
      set @response_code = -300
      set @message = 'General SQL Error - affiliate_url insert'
      return
    end
  
  -----------------------------------------------
  -- 4) result
  -----------------------------------------------
  commit transaction
  set @response_code = 0
  set @message = ''
  select @affiliate_code as affiliate_code






GO
