-- =============================================================================
-- PROCEDURE: [dbo].[usp_Affiliate_Management]
-- =============================================================================



CREATE procedure [dbo].[usp_Affiliate_Management] 
(@agent_num int = null,
 @affiliate_category_id int = 18, --sales agent
 @first_name varchar(32) = null,
 @last_name varchar(32) = null,
 @company1 varchar(48) = '',
 @affiliate_code varchar(16) = null,
 @new_agent_num int = null,
 @new_affiliate_code varchar(16) = null,
 @department  int = 0, -- 1 = Consumer Sales, 2 = Technical Support
 @change_type int = 2, --1 = insert, 2 = update, 3 = delete
 @message varchar(100) output
)
as
/**********************************************************

	2012-08-01 acoffel set up to roll out of reporting services

************************************************************/
begin

set nocount on 

declare @rc int
declare @user_id varchar(50)
declare @cnt int
declare @update_ran bit
declare @description varchar(100)
declare @csi_user_id_check varchar(50)
declare @csi_user_id_exists varchar(50)

set @update_ran = 0

set @description = case when @department = 1 then 'consumer sales' when @department = 2 then 'technical support' else null end


	if @change_type = 1 and @first_name is not NULL and @last_name is not NULL
		begin
			select @csi_user_id_check = ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,'')))
			select @csi_user_id_exists = csi_users_id from csi_users where csi_users_id = @csi_user_id_check
		end

		if @csi_user_id_exists is not NULL
		begin
			set @message = 'CSI User ID ' + @csi_user_id_check + ' has already been used'
			select @message as [error_message]
			return
		end

create table #affiliate_result(affiliate varchar(48) null,
							   affiliate_code varchar(16) null,
								rc int null)

if @change_type = 1 --Insert
	begin


	
	insert into #affiliate_result
	exec [usp_affiliate_add_rc_code] @new_rc_code = @company1
							       , @affiliate_category_id = @affiliate_category_id
								   , @first_name = @first_name
								   , @last_name = @last_name
								   , @new_num = @new_agent_num
								   , @description = @description

	
	select top 1 @affiliate_code = affiliate_code,
				 @rc = rc,
				 @user_id = ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,'')))
	from #affiliate_result

	insert into csi_users(csi_users_id,first_name,last_name,agent_number)
	values(@user_id,@first_name,@last_name,@rc)

	end
	
if @change_type = 2
	begin


		if @new_agent_num is not null --Ensure assigned num is not already in use
			begin

			if exists(select * from affiliates where assigned_num = @new_agent_num)
				or exists(select * from csi_users where agent_number = @new_agent_num)
				begin

				SELECT @new_agent_num = Min(CASE WHEN m.affiliate_code IS NOT NULL THEN a.assigned_num ELSE c.assigned_num_min END)
				FROM lu_affiliate_categories c
					LEFT OUTER JOIN affiliates a
						ON a.assigned_num between c.assigned_num_min AND c.assigned_num_max
					LEFT OUTER JOIN affiliate_category_members m
						ON m.affiliate_code = a.affiliate_code
						AND m.category_id = c.category_id
					left join csi_users u on
					a.assigned_num = u.agent_number
				WHERE c.category_id = @affiliate_category_id
					and u.agent_number is null

				set @cnt = 0

				select @cnt = count(*)
				from affiliates
				where assigned_num = @new_agent_num
				
				while @cnt > 0
					begin
					select @cnt = count(*)
					from affiliates
					where assigned_num = @new_agent_num

					select @cnt = @cnt + isnull(count(*),0)
					from csi_users
					where agent_number = @new_agent_num

					if @cnt > 0
						set @new_agent_num = @new_agent_num + 1

					end

				end

			end

		if @agent_num is not null
			begin
			update affiliates
				set first_name = isnull(@first_name,first_name),
					last_name = isnull(@last_name,last_name),
					affiliate_code = isnull(@new_affiliate_code,affilia
te_code),
					company1 = isnull(@company1,company1),
					assigned_num = isnull(@new_agent_num,assigned_num),
					assigned_num_str = isnull(@new_agent_num,assigned_num),
				    description = isnull(@description,description)
			where assigned_num = @agent_num
			

			update csi_users
				set csi_users_id = case when ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,''))) = '' then csi_users_id else ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,''))) end,
					first_name = isnull(@first_name,first_name),
					last_name = isnull(@last_name,last_name),
					agent_number = isnull(@new_agent_num,agent_number)
				where agent_number = @agent_num


			set @update_ran = 1

			end

		if @affiliate_code is not null and @update_ran = 0
			begin
			update affiliates
				set first_name = isnull(@first_name,first_name),
					last_name = isnull(@last_name,last_name),
					assigned_num = isnull(@new_agent_num,assigned_num),
					company1 = isnull(@company1,company1),
					affiliate_code = isnull(@new_affiliate_code,affiliate_code),
					assigned_num_str = isnull(@new_agent_num,assigned_num),
					description = isnull(@description,description)
			where affiliate_code = @affiliate_code
			
			select @agent_num = assigned_num from affiliates where affiliate_code = @affiliate_code

			update csi_users
				set csi_users_id = case when ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,''))) = '' then csi_users_id else ltrim(rtrim(left(isnull(@first_name,''),1))) + ltrim(rtrim(isnull(@last_name,''))) end,
					first_name = isnull(@first_name,first_name),
					last_name = isnull(@last_name,last_name),
					agent_number = isnull(@new_agent_num,agent_number)
				where agent_number = @agent_num
			

			end

	end

if @change_type = 3
	begin

		if @agent_num is not null
			begin

			if @affiliate_code is null
				select @affiliate_code = affiliate_code from affiliates
				where assigned_num = @agent_num

			delete from affiliate_category_members where affiliate_code = @affiliate_code 
	
			delete from affiliates where assigned_num = @agent_num

			delete from csi_users where agent_number = @agent_num

			end

		if @affiliate_code is not null
			begin

			delete from affiliate_category_members where affiliate_code = @affiliate_code

			select @agent_num = assigned_num from affiliates where affiliate_code = @affiliate_code

			delete from affiliates where assigned_num = @agent_num

			delete from csi_users where agent_number = @agent_num

			end
			
		if @affiliate_code is not null and @change_type = 3
			begin

			select 'agent number ' + left(@agent_num,5) + ' has successfully been deleted' as affiliate_code, 
					'' as agent_id, '' as first_name, '' as last_name, '' as csi_users_id, '' as [description]

			end

	end


	if @change_type <> 3 
			begin
				select affiliate_code,assigned_num as agent_id,a.first_name, a.last_name,csi_users_id, a.description  
				from affiliates a inner join csi_users c on
				a.assigned_num = c.agent_number
					and (c.agent_number = @agent_num 
					or a.affiliate_code = @affiliate_code
					or c.agent_number = @new_agent_num)
				

				end


					
end		       


GO
