CREATE PROCEDURE [dbo].[usp_agile_log_json_insert_log]

(
	@agile_id varchar(20),
	@agile_json varchar(max) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2017-10-05	acoffel		Initial creation.

	DESCRIPTION
	insert json
*/

AS
	set nocount on				

	declare	@agile_log_json_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.3) log json 
	if @agile_json is not NULL
		begin 
			insert into agile_log_json (agile_id, agile_json, insert_date)
			select @agile_id, @agile_json, getdate()
		end

	select agile_log_json_id = agile_log_json_id from agile_log_json where agile_id = @agile_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
