CREATE PROCEDURE [dbo].[usp_amazon_insert_amazon_account]

(
	 @first_name nvarchar(225) = null,
	 @last_name nvarchar(225) = null,
	 @customer_email varchar(100) = null,
	 @customer_id int = null,
	 @return_amazon_account_key bit = 1
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-12-07		esmart			Initial creation
	2019-06-21		esmart			add @company_id_input
	2021-06-25		abelenkiy		Refactored for Safe Account compatibility; added optional customer_id input; made email/first/last optional; 
									removed variables being used to call usp_customer_insert_customer_service and passed in JSON instead;
									removed customer validation (which will now take place in usp_customer_insert_customer_service);
									added more robust error handling; added @return_amazon_account_key (instead of output param for backwards compatibility) 								
	
	DESCRIPTION
	insert amazon_account
*/

as

	set nocount on
			
	begin try

	declare	@transaction_user varchar(100) = 'usp_amazon_insert_amazon_account'
		, @amazon_account_id int
		, @message varchar(2000)
		, @customer_json nvarchar(1000)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.1) validate inputs
	if @customer_email is null and not exists (select 1 from customer where customer_id = @customer_id)
		begin
			select @message = 'Either email or customer_id is required'
			raiserror (@message, 16, 1)
		end

	-- 1.2) find/create customer if exists
	if @customer_id is null
		begin
			select @customer_json = dbo.fn_customer_variables_to_json(@customer_email, @customer_id
				, @first_name, @last_name, default, default, default, default, default, default
				, default, default, default, default, default, default, default, default, default
				, default, default, default, default, default, default, default, default, default
				, default, @transaction_user)
			
			exec usp_customer_insert_customer_service @customer_id = @customer_id output
													, @input_json = @customer_json
		end

	-- 1.3) look for existing amazon account record
	select @amazon_account_id = amazon_account_id
	from amazon_account 
	where customer_id = @customer_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @amazon_account_id is null
		begin
			insert into amazon_account (customer_id) values (@customer_id)

			select @amazon_account_id = scope_identity()
		end

	if @return_amazon_account_key = 1
		begin
			select amazon_account_key = convert(varchar(36),amazon_account_key)
			from amazon_account
			where amazon_account_id = @amazon_account_id
		end

	end try

	begin catch
		set @message = 'customer_id = ' + isnull(convert(varchar(20), @customer_id), 'null')
					+ ', customer_email = ' + isnull(@customer_email, 'null')
					+ ': ' + error_message()
					
		insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine
			, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line
()
			, @message, @@servername, db_name(), suser_name()

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_amazon_insert_amazon_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_amazon_insert_amazon_subscription]

(
       @amazon_subscription_key varchar(50),
       @amazon_account_key varchar(36),
       @product_id int,
       @external_keycode varchar(40) = null
)
       
/*     
       DATE                 AUTHOR               REMARKS
       2016-12-07           esmart               Initial creation
       2017-06-27           esmart               Add @external_keycode as input for sky licensing
       
       DESCRIPTION
       insert amazon_subscription
*/

as

       set nocount on
       

       declare       @amazon_subscription_id int,
                     @license_distribution_method_id int, 
                     @quantity int,
                     @start_date datetime,
                     @end_date datetime,
                     @months int,
                     -- @external_keycode varchar(40),
                     @amazon_account_id int,
                     @customer_id int,
                     @license_id int,
                     @response_code int,
                     @message varchar(100)
                     
       begin try

       select @quantity = 1

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) select 
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       -- 1.1) check for existing subscription
       select @amazon_subscription_id = amazon_subscription_id
       from amazon_subscription
       where amazon_subscription_key = @amazon_subscription_key

       -- 1.2) @customer_id
       select @customer_id = customer_id, @amazon_account_id = amazon_account_id
       from amazon_account
       where amazon_account_key = @amazon_account_key

              if @amazon_account_id is null
                     begin
                     select response_code = -120, message = 'Invalid account'
                     return
                     end 
       
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 2.) insert 
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       if @amazon_subscription_id is null
              begin

              declare @keycodes table (keycode varchar(40))

              -- 2.1) @license_distribution_method_id
              select @license_distribution_method_id = license_distribution_method_id
              from license_distribution_method
              where license_distribution_method_code = 'AMZS'

              -- 2.2) insert license
              insert into @keycodes(keycode)
              exec usp_license_insert_license_service @product_id, @license_distribution_method_id, @quantity, @start_date, @end_date, @months, @external_keycode

              select @license_id = l.license_id
              from license l
              inner join @keycodes k
                     on k.keycode = l.keycode

                     -- 2.2.1) activate 
                     exec usp_license_update_activate @license_id

              -- 2.3) register license
              update license
              set customer_id = @customer_id
              from license l
              where l.license_id = @license_id

              -- 2.4) amazon_subscription
              insert into
 amazon_subscription (amazon_subscription_key, amazon_account_id,license_id)
              values(@amazon_subscription_key,@amazon_account_id,@license_id)

              select @amazon_subscription_id = scope_identity()

              select amazon_subscription_id = @amazon_subscription_id

              end
       else
              begin
              select amazon_subscription_id = @amazon_subscription_id
              end

       end try

       begin catch

              set @response_code = -200
              set @message = case when @message is null then 'insert amazon_subscription failed'
                                                else @message end

              declare @DBName nvarchar(128)
              set @DBName = db_name()
              exec usp_LogError @ErrorDB = @DBName
              
       end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_amazon_select_amazon_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_amazon_select_amazon_account]

(
	@customer_email varchar(100) = null,
	@amazon_account_key varchar(36) = null
	
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-12-07		esmart			Initial creation
	
	DESCRIPTION
	select amazon_account
*/

as

	set nocount on
	

	declare	@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select z.amazon_account_id, amazon_account_key = convert(varchar(36),z.amazon_account_key), z.customer_id, e.customer_email, z.insert_date, z.modified_date
	from amazon_account z
	inner join customer_email e
		on e.customer_id = z.customer_id and e.email_status_id = 1
	where e.customer_email = case when @customer_email is not null then @customer_email else e.customer_email end and
		z.amazon_account_key = case when @amazon_account_key is not null then @amazon_account_key else z.amazon_account_key end
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select amazon_account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
