-- PROCEDURE: [dbo].[usp_amazon_select_amazon_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_amazon_select_amazon_subscription]

(
	@amazon_subscription_key varchar(50) = null,
	@amazon_account_key varchar(36) = null,
	@license_id int = null	
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-12-07		esmart			Initial creation
	
	DESCRIPTION
	insert amazon_subscription
*/

as

	set nocount on
	

	declare	@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select s.amazon_subscription_id, s.amazon_subscription_key, s.amazon_account_id, amazon_account_key = convert(varchar(36),a.amazon_account_key), s.license_id, l.keycode, s.amazon_subscription_status_id, ss.amazon_subscription_status_name, s.insert_date, s.modified_date
	from amazon_subscription s
	inner join amazon_subscription_status ss
		on ss.amazon_subscription_status_id = s.amazon_subscription_status_id
	inner join amazon_account a
		on a.amazon_account_id = s.amazon_account_id
	inner join license l
		on l.license_id = s.license_id
	inner join customer c
		on c.customer_id = a.customer_id
	inner join customer_email e
		on e.customer_id = a.customer_id and e.email_status_id = 1
	where s.amazon_subscription_key = case when @amazon_subscription_key is not null then @amazon_subscription_key else s.amazon_subscription_key end and
		a.amazon_account_key = case when @amazon_account_key is not null then @amazon_account_key else a.amazon_account_key end and
		s.license_id = case when @license_id is not null then @license_id else s.license_id end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert amazon_subscription failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_amazon_update_amazon_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_amazon_update_amazon_subscription]

(
	@amazon_subscription_key varchar(50),
	@amazon_subscription_status_name varchar(50),
	@amazon_period varchar(30),
	@amazon_reason varchar(30)
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-12-07		esmart			Initial creation
	2018-03-08		esmart			Modify to use license service license_disable
	2018-11-27		rvinoche		change json schema for license_service
	
	DESCRIPTION
	update amazon_subscription
*/

as

	set nocount on
	

	declare	@amazon_subscription_id int,
			@amazon_subscription_status_id tinyint,
			@license_id int, 
			@keycode varchar(40),
			@days int, 
			@modified_by varchar(20),
			@order_item_id int, 
			@effective_date datetime,
			@service_json nvarchar(max), 
			@license_service_type_name varchar(50),
			@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check for existing subscription
	select @amazon_subscription_id = amazon_subscription_id
	from amazon_subscription
	where amazon_subscription_key = @amazon_subscription_key

		-- 1.1.1)
		if @amazon_subscription_id is null
			begin
			select reponse_code = -111, message = 'Invalid subscription'
			end

	-- 1.2) @amazon_subscription_status_id
	select @amazon_subscription_status_id = amazon_subscription_status_id
	from amazon_subscription_status
	where amazon_subscription_status_name = @amazon_subscription_status_name

		-- 1.2.1)
		if @amazon_subscription_id is null
			begin
			select reponse_code = -121, message = 'Invalid subscription status'
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) amazon_subscription_audit
	insert into amazon_subscription_audit (amazon_subscription_id,amazon_subscription_key,amazon_account_id, license_id,amazon_subscription_status_id,insert_date, modified_date,amazon_period, amazon_reason)
	select amazon_subscription_id,amazon_subscription_key,amazon_account_id, license_id,amazon_subscription_status_id,insert_date, modified_date,@amazon_period, @amazon_reason
	from amazon_subscription
	where amazon_subscription_id = @amazon_subscription_id

	-- 2.2) update amazon_subscription
	update amazon_subscription
	set amazon_subscription_status_id = @amazon_subscription_status_id, modified_date = getdate() 
	where amazon_subscription_id = @amazon_subscription_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) deactivate license 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @amazon_subscription_status_id = 2
		begin

		select @license_service_type_name = 'license_disable'
		
		-- 3.1) @service_json
		select @service_json = (select l.keycode, @license_service_type
_name as account_name, (select lc.license_category_name as license_category_name for json path) license_category
										from amazon_subscription s
										inner join license l
											on l.license_id = s.license_id
										inner join license_category_license cl
											on cl.license_id = l.license_id
										inner join license_category lc
											on lc.license_category_id = cl.license_category_id
										where s.amazon_subscription_id = @amazon_subscription_id
										for json path, without_array_wrapper)
		
		

		-- 3.2) usp_license_service_insert_service
		exec usp_license_service_insert_service @license_service_type_name, @service_json

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert amazon_subscription failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_api_monitor]
-- =============================================================================

-- ===============================================================
-- Author:           esmart
-- Create date: 8.22.2019
--                         11.25.2019 added process_date to update table selects
-- Description: logs api queue counts into the api_monitor table. 
-- ===============================================================
CREATE PROCEDURE [dbo].[usp_api_monitor]
AS
BEGIN
       declare @api_id tinyint, 
                     @api_queue_name varchar(50), 
                     @api_template_name varchar(50),
                     @api_update_type_name varchar(50),
                     @api_record_count int,
                     @start_date datetime, 
                     @end_date datetime

       select @end_date = datetimefromparts(datepart(yy,getdate()),datepart(mm,getdate()),datepart(dd,getdate()),datepart(hh,getdate()),datepart(mi,getdate()),0,0)

       select @start_date = dateadd(mi,-1,@end_date)

       select @start_date as start_date, @end_date as end_date

       -- sfdc_opportunity_load
       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 1, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_load with (nolock)
       where process_date < getdate()
       group by sfdc_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 2, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_load_archive with (nolock)
       where archive_date >= @start_date and archive_date < @end_date group by sfdc_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 3, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_load_failure with (nolock) 
       where failure_date >= @start_date and failure_date < @end_date group by sfdc_template_id

       -- sfdc_opportunity_update
       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 4, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_update with (nolock) 
       where process_date < getdate()
       group by sfdc_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 5, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_update_archive with (nolock)
       where archive_date >= @start_date and archive_date < @end_date 
       group by sfdc_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 6, sfdc_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sfdc_opportunity_update_failure with (nolock)
       where failure_date >= @start_date and failure_date < @end_date group by sfdc_template_id

       -- sky_update
       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 7, sky_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sky_update with (nolock) 
       where process_date < getdate()
       group by sky_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 8, sky_template_id, null as api_upda
te_type_id, count(*) as api_record_count, @end_date
       from sky_update_archive with (nolock) 
       where archive_date >= @start_date and archive_date < @end_date 
       group by sky_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 9, sky_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from sky_update_failure with (nolock) 
       where failure_date >= @start_date and failure_date < @end_date group by sky_template_id

       -- oracle_update
       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 10, oracle_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from oracle_update with (nolock) 
       where process_date < getdate()
       group by oracle_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 11, oracle_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from oracle_update_archive with (nolock) 
       where archive_date >= @start_date and archive_date < @end_date 
       group by oracle_template_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 12, oracle_template_id, null as api_update_type_id, count(*) as api_record_count, @end_date
       from oracle_update_failure with (nolock) 
       where failure_date >= @start_date and failure_date < @end_date group by oracle_template_id

       -- prevx_update
       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 13, prevx_update_type_id, null as api_update_type_id, count(*) as api_record_count, @end_date  
       from prevx_update with (nolock)   
       where process_date < getdate()
       group by prevx_update_type_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 14, prevx_update_type_id, null as api_update_type_id, count(*) as api_record_count, @end_date  
       from prevx_update_archive with (nolock)   
       where archive_date >= @start_date and archive_date < @end_date 
       group by prevx_update_type_id

       insert into api_monitor (api_id, api_template_id, api_update_type_id, api_record_count, api_monitor_date)
       select 15, prevx_update_type_id, null as api_update_type_id, count(*) as api_record_count, @end_date  
       from prevx_update_failure with (nolock)   
       where failure_date >= @start_date and failure_date < @end_date 
       group by prevx_update_type_id
END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_api_monitor_alerts]
-- =============================================================================




---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- ======================================================================================================  
-- Author:  jpaulus  
-- Create date: 10.7.2019  
-- Description: Monitors all api queues. 'Triggered' Alerts are currently logged to the api_alerts table  
-- ======================================================================================================  
CREATE PROCEDURE [dbo].[usp_api_monitor_alerts]  
AS  
BEGIN  
 SET NOCOUNT ON;  
  DECLARE @cur_date DATETIME  
 SELECT @cur_date = GETDATE()  
 DECLARE @latestCount TABLE  
 (   
  api_count INT,  
  api_id INT,  
  api_monitor_date DATETIME  
 )  
 DECLARE @queues TABLE  
 ( row_num INT,  
  api_description VARCHAR (100),  
  api_id INT,  
  api_count INT,  
  api_monitor_date DATETIME,  
  record_threshold INT,  
  record_threshold_minutes INT  
 )  
  
 --Get the most recent count for each api  
 ;WITH Max_CTE (api_monitor_date, api_id) AS (  
  SELECT MAX(api_monitor_date) AS api_monitor_date, api_id  
  FROM api_monitor  
  GROUP BY api_id  
 )  
 INSERT INTO @latestCount (api_count, api_id, api_monitor_date)  
 SELECT SUM(m.api_record_count) AS api_count, x.api_id, x.api_monitor_date  
 FROM Max_CTE x  
 JOIN api_monitor m ON (x.api_id = m.api_id AND x.api_monitor_date = m.api_monitor_date)  
 JOIN api a ON x.api_id = a.api_id  
 GROUP BY x.api_ID, x.api_monitor_date  
  
 --SELECT  * FROM    @latestCount  
  
 --This assigns a number 1-3 to each queue type for each api  
 -- 1 is the actual queue.   
 -- 2 is the archive table.   
 -- 3 is the failure table.  
 INSERT INTO @queues (row_num ,api_description, api_id, api_count, api_monitor_date, record_threshold, record_threshold_minutes )  
 SELECT ROW_NUMBER() OVER (PARTITION BY a.api_description ORDER BY a.api_id) AS row_num, a.api_description,   
   l.api_id, l.api_count, l.api_monitor_date, a.record_threshold, a.record_threshold_minutes  
 FROM @latestCount l  
 JOIN api a ON l.api_id = a.api_id  
  
 --SELECT * FROM @queues  
  
 DECLARE @counter INT = 1;  
 DECLARE @recordCount INT;  
 SELECT @recordCount = COUNT(*) FROM @queues WHERE row_num = 1  
  
 DECLARE @api_count INT,  
   @api_id INT,  
   @api_monitor_date DATETIME,  
   @record_threshold INT,  
   @record_threshold_minutes INT,  
   @api_description VARCHAR(100)  
   
 DECLARE @problems TABLE(  
  queue_name VARCHAR(100),  
  api_monitor_id INT,  
  monitor_date DATETIME  
 )  
   
  
 WHILE ( @counter <= @RecordCount )  
 BEGIN  
  SELECT TOP 1  @api_count = api_count,  
      @api_id = api_id,  
      @api_monitor_date = api_monitor_date,  
      @record_threshold = record_threshold,  
      @record_threshold_minutes = record_threshold_minutes,  
      @api_description = api_description  
  FROM @queues  
  WHERE row_num = 1  
  
  -- If the count is over the threshold and the record is recent, then it needs to be looked at  
  IF ( (@api_count > @record_threshold) AND (@cur_date < DATEADD(mi,@record_threshold_minutes,@api_monitor_date)) )  
  BEGIN  
   --look at the archive queue  
   SELECT  @api_monitor_date = api_monitor_date,  
     @record_threshold = record_threshold,   
     @record_threshold_minutes = record_threshold_minutes   
   FROM @queues  
   WHERE row_num = 2 AND api_description = @api_description  
    
   --If the api_monitor_date for archive is NOT recent, then we need to check the failure table  
   IF ( @cur_date > DATEADD(mi,@record_threshold_minutes,@a
pi_monitor_date) )  
   BEGIN    
    --look at the failure table  
    SELECT  @api_monitor_date = api_monitor_date,  
      @record_threshold = record_threshold,   
      @record_threshold_minutes = record_threshold_minutes   
    FROM @queues  
    WHERE row_num = 3 AND api_description = @api_description  
  
    --If the api_monitor_date for failure table is NOT recent, then there is a problem  
    IF ( @cur_date > DATEADD(mi,@record_threshold_minutes,@api_monitor_date) )  
    BEGIN  
     INSERT INTO api_alerts VALUES (@api_description, @api_count, GETDATE());  
     INSERT INTO @problems VALUES (@api_description, @api_count, GETDATE());  
    END  
    ELSE PRINT 'The ' + @api_description + ' queue is OK. The failure table has recent records.'  
   END  
   ELSE PRINT 'The ' + @api_description + ' queue is OK. The archive table has recent records.'  
  END  
  
  DELETE FROM @queues   
  WHERE api_description = @api_description  
  
  SELECT @counter = @counter + 1  
 END  
  
   
  
 IF EXISTS(SELECT TOP 1 * FROM @problems WHERE queue_name LIKE 'SFDC%')  
   BEGIN  
     
    DECLARE @body1   VARCHAR(MAX);
    
    SET @body1 = '<html><head><title>API Monitor Alert</title></head>
          <body>
            <table>
              <tr>
                <th>Queue</th>
                <th>Record Count</th>
                <th>Time</th>
              </tr>'
  
    SELECT @body1 = @body1 + '<tr>
                <td>' + queue_name + '</td>
                <td>' + CAST(api_monitor_id AS varchar(32)) +'</td>
                <td>' + CAST(monitor_date AS varchar(32))+'</td>
              </tr>'

    FROM @Problems
    WHERE queue_name LIKE 'SFDC%'

    SET @body1 = @body1 +  '</table></body></html>'
    
    DELETE FROM @problems WHERE queue_name LIKE 'SFDC%'  
    
    EXEC msdb.dbo.sp_send_dbmail    
        @profile_name = 'DBA',    
        @recipients = 'WR-DLWebDevDB@opentext.com; CT_DBA_Team@opentext.com;MGuenthner@opentext.com;CARB-DBMonitoring@opentext.com', 
        @body = @body1,   
        @subject = 'API Monitor Alert - SFDC',
        @body_format = 'HTML'
    
     END  
    
   IF EXISTS(SELECT TOP 1 * FROM @problems)  
   BEGIN  
    
    DECLARE @body2 VARCHAR(MAX);

    SET @body2 = '<html><head><title>API Monitor Alert</title></head>
          <body>
            <table>
              <tr>
                <th>Queue</th>
                <th>Record Count</th>
                <th>Time</th>
              </tr>'
  
    SELECT @body2 = @body2 + '<tr>
                <td>' + queue_name + '</td>
                <td>' + CAST(api_monitor_id AS varchar(32)) +'</td>
                <td>' + CAST(monitor_date AS varchar(32))+'</td>
              </tr>'

    FROM @Problems
            
    EXEC msdb.dbo.sp_send_dbmail    
     @profile_name = 'DBA',    
     @recipients = 'WR-DLWebDevDB@opentext.com;CT_DBA_Team@opentext.com;CARB-DBMonitoring@opentext.com;', 
     @body = @body2,
     @subject = 'API Monitor Alert',
     @body_format = 'HTML';

   END    
   ELSE  
    PRINT 'Nothing''s wrong.'  
       
END





