-- =============================================================================
-- PROCEDURE: [dbo].[usp_app_config_insert_key_values]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_app_config_insert_key_values] (
		@app_config_name NVARCHAR(50)
		, @app_config_description NVARCHAR(MAX)
		, @app_config_key_value_json NVARCHAR(MAX)
		, @app_config_group_id INT
		, @app_config_type_id INT
		, @response_code INT OUTPUT
		, @message VARCHAR(500) OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2023-09-01	gblandford	Initial creation

	DESCRIPTION
	Inserts key-value pair json into the dbo.app_config table.

	Original design would have additionally stated the app_config_group name in the JSON, but currently OT infrastructure is based on SQL Server 2016 
	which does not support passing the JSON path as a variable (SQL Server 2017 (14.x) + does), so we are using a generic node called 'config'.
	
*/

AS

	SET NOCOUNT ON				


	BEGIN TRY

		IF ( @app_config_name IS NOT NULL
				AND @app_config_description IS NOT NULL
				AND EXISTS (SELECT 1 FROM dbo.app_config_group WHERE app_config_group_id = @app_config_group_id)
				AND EXISTS (SELECT 1 FROM dbo.app_config_type WHERE app_config_type_id = @app_config_type_id)
				AND @app_config_key_value_json IS NOT NULL
				AND ISJSON(@app_config_key_value_json) = 1
			) BEGIN

				INSERT INTO dbo.app_config (
					app_config_name,
					app_config_description,
					app_config_group_id,
					app_config_type_id,
					app_config_key_value_json
				)
				VALUES (
					@app_config_name,
					@app_config_description,
					@app_config_group_id,
					@app_config_type_id,
					@app_config_key_value_json
				);

			SELECT @response_code = 0, @message = 'Success';

		END ELSE BEGIN

			SELECT @response_code = -1
				, @message = 'Unable to insert key-value pairs for ' 
					+ @app_config_name + ' - invalid input values'

		END

		RETURN @response_code;

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE 
							WHEN @message IS NULL THEN 'Unable to insert key-value pairs for ' + @app_config_name 
							ELSE @message 
						END

		SET @message = @message + ': ' + ERROR_MESSAGE()

		RAISERROR(@message, 16, 1)

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()

		EXECUTE dbo.usp_LogError @ErrorDB = @DBName;
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_app_config_select_key_values]
-- =============================================================================


CREATE   PROCEDURE [dbo].[usp_app_config_select_key_values] (
		@app_config_name NVARCHAR(50) = NULL
		, @group_name NVARCHAR(50) = NULL
		, @response_code INT  = NULL OUTPUT
		, @message VARCHAR(500) = NULL OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2023-09-01	gblandford	Initial creation

	DESCRIPTION
	Returns a key-value pair table recordset using the specified app_config_name and the app_config_group name
	An app_config_name can exist in multiple groups, so @group_name must be passed, we do however allow an empty app_config_name which
	will return all key-value pairs in a group. This is useful where a number of procedure or process-specific values are required.


	Original design would have additionally stated the app_config_group name in the JSON, but currently OT infrastructure is based on SQL Server 2016 
	which does not support passing the JSON path as a variable (SQL Server 2017 (14.x) + does), so we are using a generic node called 'config'.
	
*/

AS

	SET NOCOUNT ON				

	BEGIN TRY

		SELECT 
			kv.[group_name]
			, kv.[app_config_name]
			, kv.[key]
			, kv.[value]
		FROM [dbo].[fn_app_config_select_key_values] (	@app_config_name, @group_name ) kv;

	
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'Unable to return key-value pairs for ' + @app_config_name + '/' + @group_name
							ELSE @message 
							END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()

		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_apple_insert_notification]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_apple_insert_notification]

(
	@notification_string varchar(max),
	@is_apple_triggered_notification bit = 0,
	@license_message_id int = null
)

/*	
	DATE			AUTHOR		REMARKS
	2018-10-04		cnovac		Initial creation
	2018-10-09		cnovac		Added logic to parse JSON and process notification
	2019-01-07		cnovac		Updated logic to write to apple_notifications_by_receipt and only process changes to usp_apple_process_notification

	DESCRIPTION
	usp_apple_insert_notification

*/

AS

	set nocount on

	begin try

	declare	@apple_notification_id int,
			@sql_string varchar(4000),
			@task_number varchar(10),
			@db_name varchar(50) = db_name(),
			@response_code int,
			@message varchar(100)

	if @is_apple_triggered_notification = 1
	begin
		--these would be notifications we get from apple from there service
		insert into apple_notifications_temp (notificaton_string)
		values (@notification_string)

	end
	else
	begin
		--these are notifications we trigger internally by license_message
		insert into apple_notifications (notification_string, license_message_id)
		values (@notification_string, @license_message_id)

		set @apple_notification_id = scope_identity()

		--pull the latest_receipt_info json and store in db
		update an
		set an.latest_receipt_info = ns.Value
		from apple_notifications an
		cross apply openjson(an.notification_string) ns
		where an.apple_notification_id = @apple_notification_id
		and ns.[Key] = 'latest_receipt_info'

		--pull the latest_receipt json and store in db (this is used later to populate staging table)
		update an
		set an.latest_receipt = ns.Value
		from apple_notifications an
		cross apply openjson(an.notification_string) ns
		where an.apple_notification_id = @apple_notification_id
		and ns.[Key] = 'latest_receipt'

		--see if the user cancelled their subscription in Apple
		--1 - Customer canceled their subscription.
		--2 - Billing error; for example customer’s payment information was no longer valid.
		--3 - Customer did not agree to a recent price increase.
		--4 - Product was not available for purchase at the time of renewal.
		--5 - Unknown error.
		update an
		set an.expiration_intent = json_value(ns.Value, '$[0].expiration_intent'),
			an.original_transaction_id = json_value(ns.Value, '$[0].original_transaction_id'),
			an.auto_renew_product_id = json_value(ns.Value, '$[0].auto_renew_product_id'),
			an.auto_renew_status = json_value(ns.Value, '$[0].auto_renew_status'),
			an.product_id = json_value(ns.Value, '$[0].product_id')
		from apple_notifications an
		cross apply openjson(an.notification_string) ns
		where an.apple_notification_id = @apple_notification_id
		and ns.[Key] = 'pending_renewal_info'

		--now get all the reciepts which make up latest_receipt_info which don't already exist in apple_notifications_by_receipt
		insert into apple_notifications_by_receipt (apple_notification_id, transaction_id, original_transaction_id, product_id, cancellation_reason, cancellation_date, purchase_date, expires_date)
		select @apple_notification_id,
			   json_value(ns.Value, '$.transaction_id'),
			   json_value(ns.Value, '$.original_transaction_id'),
			   json_value(ns.Value, '$.product_id'),
			   json_value(ns.Value, '$.cancellation_reason'),
			   dateadd(hh, datediff(hh, getutcdate(), getdate()), left(json_value(ns.Value, '$.cancellation_date'), 20)),
			   dateadd(hh, datediff(hh, getutcdate(), getdate()), left(json_value(ns.Value, '$.purchase_date'), 20)),
			   dateadd(hh, datediff(hh, getutcdate(), getdate()), left(json_value(ns.Value, '$.expires_date'), 20))
		from apple_notifications an
		cross apply openjson(an.latest_receipt_info) ns
		left join apple_notificatio
ns_by_receipt anbr on anbr.transaction_id = json_value(ns.Value, '$.transaction_id')
		where an.apple_notification_id = @apple_notification_id
		and anbr.apple_notifications_by_receipt_id is null
		order by json_value(ns.Value, '$.transaction_id')

		--set the service broker transaction to process the notification
		-----------------------------------------------------------------------------------------------
		set @task_number = @apple_notification_id

		set @sql_string = 'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
							' values (' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_apple_process_notification ' + convert(varchar(10), @apple_notification_id) + '''' + ', 0, getdate())'

		exec (@sql_string)
		exec tasks..usp_queue_task @apple_notification_id
		-----------------------------------------------------------------------------------------------

	end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_apple_insert_notification'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_apple_process_notification]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_apple_process_notification]

(
	@apple_notification_id int
)

/*

	DATE			AUTHOR			REMARKS
	2018-10-04		cnovac			Initial creation
	2019-01-07		cnovac			Updated logic to handle daily processing of all receipts not cancelled
	2019-01-30		cnovac			Changed query at top to see if anbr.transaction_id is present in account_order_staging
	2019-02-20		rvinoche		Change json schema for license_service

	DESCRIPTION
	usp_apple_process_notification

*/

AS

	set nocount on

	begin try

		declare @order_receipt varchar(100),
				@previous_order_receipt varchar(100),
				@email varchar(100),
				@order_token varchar(max),
				@merchant_product_id varchar(100),
				@previous_merchant_product_id varchar(100),
				@account_hash_id varchar(65),
				@account_order_staging_id int,
				@vendor_order_date datetime,
				@vendor_expiration_date datetime,
				@previous_vendor_expiration_date datetime,
				@is_trial_to_full_conversion bit,
				@is_product_change_conversion bit = 0,
				@original_account_order_staging_id int,
				@license_id int,
				@license_service_json varchar(max),
				@license_service_type_name varchar(50) = 'license_update',
				@license_message_value_str varchar(200),
				@license_message_id int,
				@process_date date = dateadd(dd, 1, getdate()),
				@rowcount int,
				@response_code int,
				@message varchar(100)
		declare @account_order_staging table (account_order_staging_id int)

		select top 1 @order_receipt = anbr.transaction_id
		from apple_notifications_by_receipt anbr
		where anbr.apple_notification_id = @apple_notification_id
		order by anbr.transaction_id desc

		select @original_account_order_staging_id = aos.account_order_staging_id,
				@email = aos.email,
				@order_token = an.latest_receipt,
				@merchant_product_id = anbr.product_id,
				@account_hash_id = aos.account_hash_id,
				@order_receipt = anbr.transaction_id,
				@license_id = ao.license_id,
				@vendor_order_date = anbr.purchase_date,
				@vendor_expiration_date = anbr.expires_date,
				@is_trial_to_full_conversion = iif(l.category_type_name = 'trial', 1, 0)
		from apple_notifications an
		inner join apple_notifications_by_receipt anbr on anbr.apple_notification_id = an.apple_notification_id
		inner join account_order_staging aos on an.original_transaction_id = aos.order_receipt
		inner join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
		cross apply fn_license_select_license_profile(ao.license_id) l
		left join account_order_staging aos2 on anbr.transaction_id = aos2.order_receipt
		where an.apple_notification_id = @apple_notification_id
		and anbr.transaction_id = @order_receipt
		and aos2.account_order_staging_id is null

		set @rowcount = @@ROWCOUNT

		--this means there are no new transactions which don't already exist in account_order_staging
		if @rowcount = 0
		begin

			select @vendor_expiration_date = max(expires_date)
			from apple_notifications_by_receipt
			where apple_notification_id = @apple_notification_id

			select @license_id = ao.license_id,
					@account_order_staging_id = aos.account_order_staging_id
			from apple_notifications an
			inner join account_order_staging aos on an.original_transaction_id = aos.order_receipt
			inner join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
			where an.apple_notification_id = @apple_notification_id

			--insert a new record into license_message
			set @license_message_value_str = 'account_order_staging_id=' + ltrim(rtrim(str(@account_order_staging_id)))
			exec usp_message_insert_license_message @license_id, 18, @process_date, @process_date, @process_date, @license_message_value_str, @license_mes
sage_id output, @return_result = 0

			--look to see if the max expiration date(+1) from receipt doesn't match the license expiration_date
			select @license_service_json = 
			(select l.keycode, @license_service_type_name as account_name, 
				(select l.license_category_name, @vendor_expiration_date as expiration_date for json path) license_category
			from fn_license_select_license_profile(@license_id) l
			where l.license_category_name = 'WIFI'
			for json PATH, without_array_wrapper)

			if @license_service_json is not null
			begin
				exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @license_service_json, @return_license_service_id = 0

				exec usp_account_update_account_order_staging @account_order_staging_id = @original_account_order_staging_id, @apple_notification_id = @apple_notification_id

			end

		end
		else --this is happy path meaning there was a new transaction found that needs to be processed.
		begin
			--find the product related to previous transaction and compare to new trasaction to see if the product was changed.
			--This will be then processed differently in usp_account_insert_account_order_staging to create a new renewal order and set the end dates on previous order.
			select @previous_merchant_product_id = ambr.product_id,
					@previous_order_receipt = ambr.transaction_id
			from apple_notifications_by_receipt ambr
			where ambr.apple_notification_id = @apple_notification_id
			and ambr.transaction_id = (select max(ambr2.transaction_id)
										from apple_notifications_by_receipt ambr2
										where ambr.apple_notification_id = ambr2.apple_notification_id
										and ambr2.transaction_id != @order_receipt)

			if @merchant_product_id != @previous_merchant_product_id and @is_trial_to_full_conversion = 0
				set @is_product_change_conversion = 1

			--run the insert into account_order_staging
			insert into @account_order_staging (account_order_staging_id)
			exec usp_account_insert_account_order_staging @merchant_id = 'apple_store', @email = @email, @order_token = @order_token, @merchant_product_id = @merchant_product_id, @account_hash_id = @account_hash_id, 
			@apple_notification_id = @apple_notification_id, @original_account_order_staging_id = @original_account_order_staging_id, @is_trial_to_full_conversion = @is_trial_to_full_conversion, @vendor_order_date = @vendor_order_date, 
			@vendor_expiration_date = @vendor_expiration_date, @order_receipt = @order_receipt, @is_product_change_conversion = @is_product_change_conversion, @previous_order_receipt = @previous_order_receipt

			select @account_order_staging_id = account_order_staging_id from @account_order_staging
			exec usp_account_insert_account_order_staging_log @account_order_staging_id = @account_order_staging_id, @account_order_api_reference_id = 6, @account_order_api_status = 1, @account_order_api_message = 'Success'

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_apple_process_notification'
										else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_archive_console_activity_saep]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_archive_console_activity_saep]

(
	@days_to_archive int = -365
)

/*	
	DATE		AUTHOR		REMARKS
	2019-10-30	cnovac		Initial creation.

	DESCRIPTION
	Archives data from console_activity_saep into ecommerce_arcive console_activity_saep_archive
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

		drop table if exists #console_activity_saep_max_row
		drop table if exists #console_activity_saep_delta

		select max(console_activity_id) as console_activity_id,
               license_id
		into #console_activity_saep_max_row
		from console_activity_saep
		where effective_date <= dateadd(day, @days_to_archive, cast(getdate() as date))
		group by license_id

		select cas.console_activity_id
		into #console_activity_saep_delta
		from #console_activity_saep_max_row temp
		inner join console_activity_saep cas on cas.license_id = temp.license_id
		left join eCommerce_Archive.dbo.console_activity_saep_archive acasa on acasa.console_activity_id = cas.console_activity_id
		where cas.console_activity_id < temp.console_activity_id
		and acasa.console_activity_id is null

		insert into eCommerce_Archive.dbo.console_activity_saep_archive (console_activity_id, license_id, total_devices, active_devices, deactivated_devices, effective_date, last_30_day_devices, active_last_30_day_devices, capability_type_id, parent_license_id)
		select cas.console_activity_id, cas.license_id, cas.total_devices, cas.active_devices, cas.deactivated_devices, cas.effective_date, cas.last_30_day_devices, cas.active_last_30_day_devices, cas.capability_type_id, cas.parent_license_id
		from #console_activity_saep_delta delta
		inner join console_activity_saep cas on cas.console_activity_id = delta.console_activity_id

		delete cas
		from #console_activity_saep_delta delta
		inner join console_activity_saep cas on cas.console_activity_id = delta.console_activity_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_product_select_license_distribution_method_code'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_archive_purge_dr_subscription_xml]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_archive_purge_dr_subscription_xml] @days INT,@archive INT, @purge INT 

AS

/*

Usage: To Archive/Purge Data from dr_subscription_xml table based on day

Date          Author     Version  Remarks

4/29/2015     ugangichetty       1.0      Initial

Parameters:

@days - purge data older than @ days

@archive - 1|0 - 1: do archive, 0: Don't archive

@purge - 1|0 - 1: do purge, 0: Don't purge

Eg: EXEC usp_archive_purge_dr_subscription_xml 2, 1, 1

*/

SET NOCOUNT ON

DECLARE @purgedatetime DATETIME

DECLARE @archdatetime DATETIME

DECLARE @activityid_start BIGINT

DECLARE @activityid_end BIGINT

DECLARE @cnt INT

DECLARE @ErrorMessage NVARCHAR(4000);

DECLARE @ErrorSeverity INT;

DECLARE @ErrorState INT;

--SET @purgedatetime = GETDATE()-@days

SET @purgedatetime = DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()-@days))
SELECT @archdatetime=ISNULL(MAX(insert_date),'1900-01-01') FROM eCommerce_archive.dbo.dr_subscription_xml

Print @purgedatetime

Print @archdatetime

IF(@archive = 1) OR (@archdatetime < @purgedatetime)

BEGIN

PRINT 'Last Archived date for ecommerce.dbo.dr_subscription_xml is at ' + CONVERT(VARCHAR,@archdatetime,120)

PRINT 'Archival date requested for ecommerce.dbo.dr_subscription_xml before ' + CONVERT(VARCHAR,@purgedatetime,120)

BEGIN TRY

SELECT @activityid_start = MAX(dr_subscription_xml_id) FROM eCommerce_archive.dbo.dr_subscription_xml

PRINT 'Started inserting dr_subscription_xml_id data AFTER:' + CONVERT(VARCHAR,@activityid_start)

--SET IDENTITY_INSERT eCommerce_archive.[dbo].[dr_subscription_xml] ON

INSERT INTO eCommerce_archive.[dbo].[dr_subscription_xml]
           ([dr_subscription_xml_id]
           ,[dr_subscription_id]
           ,[insert_date]
           ,[dr_subscription_xml])
     
SELECT  [dr_subscription_xml_id]
           ,[dr_subscription_id]
           ,[insert_date]
           ,[dr_subscription_xml] FROM [dr_subscription_xml] WHERE insert_date > @archdatetime  AND insert_date < @purgedatetime
--SET IDENTITY_INSERT eCommerce_archive.[dbo].[dr_subscription_xml] OFF 

SELECT @activityid_end = MAX(dr_subscription_xml_id) FROM eCommerce_archive.dbo.dr_subscription_xml

PRINT 'Completed inserting dr_subscription_xml_id data UNTIL:' + CONVERT(VARCHAR,@activityid_end)
END TRY
BEGIN CATCH
    SELECT 

        @ErrorMessage = ERROR_MESSAGE(),

        @ErrorSeverity = ERROR_SEVERITY(),

        @ErrorState = ERROR_STATE();

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);

END CATCH

END

