CREATE PROCEDURE [dbo].[usp_archive_purge_email_message] @days INT,@archive INT, @purge INT 

AS

/*

Usage: To Archive/Purge Data from Email_message and Email_message_html table based on day

Date          Author     Version  Remarks

4/29/2015     ugangichetty       1.0      Initial
2015-10-15    esmart             1.1	  Remove archiving of message_campaign 149 - WWSS Configuration	

Parameters:

@days - purge data older than @ days

@archive - 1|0 - 1: do archive, 0: Don't archive

@purge - 1|0 - 1: do purge, 0: Don't purge

Eg: EXEC usp_archive_purge_email_message 2, 1, 1

*/

SET NOCOUNT ON

DECLARE @purgedatetime DATETIME

DECLARE @archdatetime DATETIME

DECLARE @activityid_start BIGINT

DECLARE @activityid_end BIGINT

DECLARE @cnt INT

DECLARE @ErrorMessage NVARCHAR(4000);

DECLARE @ErrorSeverity INT;

DECLARE @ErrorState INT;

--SET @purgedatetime = GETDATE()-@days

SET @purgedatetime = DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()-@days))
SELECT @archdatetime=ISNULL(MAX(insert_date),'1900-01-01') FROM eCommerce_archive.dbo.email_message

Print @purgedatetime

Print @archdatetime

IF(@archive = 1) OR (@archdatetime < @purgedatetime)

BEGIN

PRINT 'Last Archived date for ecommerce.dbo.email_message is at ' + CONVERT(VARCHAR,@archdatetime,120)

PRINT 'Archival date requested for ecommerce.dbo.email_message before ' + CONVERT(VARCHAR,@purgedatetime,120)

BEGIN TRY

SELECT @activityid_start = MAX(email_message_id) FROM eCommerce_archive.dbo.email_message

PRINT 'Started inserting email_message_id data AFTER:' + CONVERT(VARCHAR,@activityid_start)

INSERT INTO eCommerce_archive.[dbo].[email_message]
           ([license_id]
           ,[message_campaign_id]
           ,[email_message_status_id]
           ,[insert_date]
           ,[process_date]
           ,[order_header_id])
  SELECT  [license_id]
           ,[message_campaign_id]
           ,[email_message_status_id]
           ,[insert_date]
           ,[process_date]
           ,[order_header_id] FROM [email_message] WHERE insert_date > @archdatetime  AND insert_date < @purgedatetime and message_campaign_id <> 149
         
SELECT @activityid_end = MAX(email_message_id) FROM eCommerce_archive.dbo.email_message

PRINT 'Completed inserting email_message_id data UNTIL:' + CONVERT(VARCHAR,@activityid_end)


SELECT @activityid_start = MAX(email_message_id) FROM eCommerce_archive.dbo.email_message_html

PRINT 'Started inserting email_message_id data AFTER:' + CONVERT(VARCHAR,@activityid_start)

INSERT INTO eCommerce_archive.[dbo].[email_message_html]
           ([email_message_id]
           ,[customer_email]
           ,[email_message_body])
  SELECT  a.[email_message_id]
           ,a.[customer_email]
           ,a. [email_message_body] FROM [email_message_html] a join email_message b on b.insert_date > @archdatetime  AND b.insert_date < @purgedatetime
                 and b.email_message_id=a.email_message_id and message_campaign_id <> 149
         
SELECT @activityid_end = MAX(email_message_id) FROM eCommerce_archive.dbo.email_message_html

PRINT 'Completed inserting email_message_id data UNTIL:' + CONVERT(VARCHAR,@activityid_end)

END TRY
BEGIN CATCH
    SELECT 

        @ErrorMessage = ERROR_MESSAGE(),

        @ErrorSeverity = ERROR_SEVERITY(),

        @ErrorState = ERROR_STATE();

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);

END CATCH

END

ELSE

PRINT 'No Archival Requested for [email_message] and [email_message_html] tables '

IF(@purge=1)

BEGIN

PRINT 'Purge date for email_message set as ' + CONVERT(VARCHAR,@purgedatetime,120)

SELECT @activityid_start = MIN(email_message_id) FROM email_message where message_campaign_id <> 149

PRINT 'Started PURGE email_message_id data in ecommerce.email_message table FROM:' + CONVERT(VARCHAR,@activit
yid_start)

SELECT @cnt=COUNT(email_message_id) FROM email_message WHERE insert_date < @purgedatetime and message_campaign_id <> 149

WHILE(@cnt > 0)

BEGIN

BEGIN TRY

-- Alter table email_message_html Nocheck constraint FK_email_message_html_email_message_id

DELETE FROM email_message_html where email_message_id IN (SELECT TOP 3000 email_message_id FROM email_message WHERE insert_date  < @purgedatetime and message_campaign_id <> 149 order by email_message_id ASC);
DELETE FROM email_message where email_message_id IN (SELECT TOP 3000 email_message_id FROM email_message WHERE insert_date  < @purgedatetime and message_campaign_id <> 149 order by email_message_id ASC);

-- Alter table email_message_html check constraint FK_email_message_html_email_message_id


SELECT @cnt=COUNT(email_message_id) FROM email_message WHERE insert_date < @purgedatetime and message_campaign_id <> 149

PRINT @cnt

WAITFOR DELAY '000:00:03';

END TRY

BEGIN CATCH

    SELECT 

        @ErrorMessage = ERROR_MESSAGE(),

        @ErrorSeverity = ERROR_SEVERITY(),

        @ErrorState = ERROR_STATE();

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);

END CATCH

END

PRINT 'Completed PURGE email_message_id data in ecommerce.email_message and ecommerce.email_message_html table UNTIL:' + CONVERT(VARCHAR,@activityid_end)

END

ELSE

PRINT 'No Purge Requested for email_message table '



GO
