CREATE PROCEDURE dbo.usp_auto_renewal_feed_opt_out_auto_renewal_by_keycode (
   @keycode nvarchar(50)
)

/*
   DATE            AUTHOR         REMARKS
   2008-04-30      bjensen        Initial creation

   DESCRIPTION
   Get the auto-renewal information by keycode

*/

AS
set nocount on

begin try
	begin transaction;

   UPDATE auto_renewal_feed
   SET
      unenroll_date = getdate()
   WHERE
      keycode = @keycode

   commit transaction;
end try
begin catch
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		if @@trancount > 0
	      rollback transaction;
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_auto_renewal_feed_select_by_keycode]
-- =============================================================================

CREATE PROCEDURE dbo.usp_auto_renewal_feed_select_by_keycode (
   @keycode nvarchar(50)
)

/*
   DATE            AUTHOR         REMARKS
   2008-04-30      bjensen        Initial creation

   DESCRIPTION
   Get the auto-renewal information by keycode

*/

AS
set nocount on

   SELECT auto_renewal_id,
          vendor_order_id,
          keycode,
          product_id,
          line_item_id,
          vendor_order_date,
          enroll_date,
          unenroll_date,
          auto_renewal_description
   FROM auto_renewal_feed
   WHERE
      keycode = @keycode


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_auto_renewal_message_insert_license]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_auto_renewal_message_insert_license]
(@process_date DATETIME = NULL)
AS
SET NOCOUNT ON

/*

			DATE		AUTHOR			REMARKS
			2019-09-25	mrobbins		Initial creation 
			2019-11-12	mrobbins		updated locale piece to be inclusive (IN)
			2019-12-09	mrobbins		changed BSN to not check cycles for monthly billing WATERBEARS-1250
			2024-04-19  psatish			ECOM-4330 Handled in a single query for the location code if it is null or not null
										and added the hardcoded values to the app_config table
			2024-04-23	psatish			ECOM-3622 AR Campaign Measure days should check against next_bill_date for Zuora licenses if exists if not expiration date
			
			DESCRIPTION
			Loops through message_campaigns creates AR Notification Queue
				SFDC AR is not included in failure messages
			This procedure is being called by the SQL job named "Exact Target Daily AR" and is scheduled to be run at 8 a.m. MST.

		*/


BEGIN TRY

    DECLARE @response_code INT,
            @message VARCHAR(100),
            @message_measure_days INT,
            @message_campaign_id INT,
            @message_campaign_name VARCHAR(65),
            @exact_target_master_id INT,
            @campaign_id INT,
            @max_campaign_id INT,
            @location_code VARCHAR(10),
            @cart_discount_id INT,
            @date_value DATETIME,
            @auto_renewal_message_auto_renewal_type_id INT,
            @message_campaign_exact_target_name VARCHAR(50)

    IF @process_date IS NULL
        SELECT @date_value = CONVERT(VARCHAR(10), GETDATE(), 101)
    ELSE
        SELECT @date_value = @process_date

    DECLARE @campaigns TABLE
    (
        campaign_id INT IDENTITY(1, 1),
        message_campaign_id INT,
        exact_target_master_id INT,
        message_campaign_name VARCHAR(65),
        message_campaign_enabled TINYINT,
        message_measure_point_name VARCHAR(50),
        message_measure_days INT,
        location_code VARCHAR(10),
        cart_discount_id INT,
        message_campaign_exact_target_name VARCHAR(50)
    );

    DECLARE @auto_renewal_message TABLE
    (
        auto_renewal_message_id INT IDENTITY(1, 1),
        license_id INT NOT NULL,
        customer_id INT NULL,
        customer_email VARCHAR(150) NULL,
        cart_discount_id INT NULL,
        exact_target_master_id INT NOT NULL,
        auto_renewal_message_status_id INT NOT NULL,
        mail_date DATETIME NULL,
        license_category_id INT NULL,
        auto_renewal_message_auto_renewal_type_id INT,
        salesforce_renewal_opportunity_id VARCHAR(50)
    )

    DECLARE @APP_CONFIG TABLE
    (
        DISTRIBUTION_METHOD_CODE VARCHAR(4),
        license_distribution_method_id INT
    )
    INSERT INTO @APP_CONFIG
    (
        DISTRIBUTION_METHOD_CODE,
        license_distribution_method_id
    )
    SELECT dm.license_distribution_method_code,
           dm.license_distribution_method_id
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL')
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_code = [key]


    INSERT INTO @campaigns
    (
        message_campaign_id,
        exact_target_master_id,
        message_campaign_name,
        message_campaign_enabled,
        message_measure_point_name,
        message_measure_days,
        cart_discount_id,
        message_campaign_exact_target_name
    )
    SELECT DISTINCT
           mc.message_campaign_id,
           etm.exact_target_master_id,
           mc.message_campaign_name,
           mc.message_campaign_enabled,
           mmp.message_measure_point_name,
           mcmp.message_measure_days,
 
          cart_discount_id,
           etmc.message_campaign_exact_target_name
    FROM message_campaign mc
        INNER JOIN message_campaign_measure_point mcmp
            ON mc.message_campaign_id = mcmp.message_campaign_id
        INNER JOIN message_measure_point mmp
            ON mcmp.message_measure_point_id = mmp.message_measure_point_id
        INNER JOIN exact_target_master etm
            ON mc.message_campaign_id = etm.message_campaign_id
        LEFT JOIN message_campaign_cart_discount mccd
            ON mc.message_campaign_id = mccd.message_campaign_id
        INNER JOIN exact_target_message_campaign etmc
            ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
        INNER JOIN dbo.exact_target_class etc
            ON etmc.exact_target_class_id = etc.exact_target_class_id
    WHERE mc.message_campaign_class_id = 4
          AND mc.message_campaign_enabled = 1
          AND etc.exact_target_class = 'AR Notification'


    SELECT @campaign_id = MIN(campaign_id),
           @max_campaign_id = MAX(campaign_id)
    FROM @campaigns



    WHILE @campaign_id <= @max_campaign_id
    BEGIN

        SELECT @message_campaign_id = message_campaign_id,
               @message_measure_days = message_measure_days,
               @message_campaign_name = message_campaign_name,
               @exact_target_master_id = exact_target_master_id,
               @cart_discount_id = cart_discount_id,
               @message_campaign_exact_target_name = message_campaign_exact_target_name
        FROM @campaigns
        WHERE campaign_id = @campaign_id


        --Zuora keycodes
        IF EXISTS
        (
            SELECT 1
            FROM @APP_CONFIG ac
                INNER JOIN dbo.message_campaign_license_distribution_method mc
                    ON mc.license_distribution_method_id = ac.license_distribution_method_id
            WHERE mc.message_campaign_id = @message_campaign_id
        )
        BEGIN

            SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
            FROM auto_renewal_message_auto_renewal_type
            WHERE auto_renewal_message_auto_renewal_type_description = 'Auto Renewal';

            INSERT INTO @auto_renewal_message
            (
                license_id,
                customer_id,
                customer_email,
                cart_discount_id,
                exact_target_master_id,
                auto_renewal_message_status_id,
                mail_date,
                license_category_id,
                auto_renewal_message_auto_renewal_type_id
            )
            SELECT DISTINCT
                   ls.license_id,
                   l.customer_id,
                   ce.customer_email,
                   @cart_discount_id,
                   @exact_target_master_id,
                   0,
                   CAST(@date_value AS DATE),
                   ls.license_category_id,
                   @auto_renewal_message_auto_renewal_type_id
            FROM dbo.license_summary ls WITH (NOLOCK)
                INNER JOIN license l WITH (NOLOCK)
                    ON ls.license_id = l.license_id
                INNER JOIN @APP_CONFIG ac
                    ON ac.license_distribution_method_id = l.license_distribution_method_id
                INNER JOIN customer_email ce
                    ON l.customer_id = ce.customer_id
                INNER JOIN dbo.message_campaign_product_line pl
                    ON pl.product_line_id = ls.product_line_id
                INNER JOIN dbo.message_campaign_license_distribution_method mc
                    ON mc.message_campaign_id = pl.message_campaign_id
                       AND mc.license_distribution_method_id = l.license_distribution_method_id
                LEFT JOIN dbo.license_next_bill_date nb
                    ON nb.license_id = l.license_id
            WHERE
 ISNULL(CAST(nb.next_bill_date AS DATE), CAST(ls.capability_expiration_date AS DATE)) = DATEADD(
                                                                                                                    dd,
                                                                                                                    -@message_measure_days,
                                                                                                                    @date_value
                                                                                                                )
                  AND pl.message_campaign_id = @message_campaign_id
                  AND ce.email_status_id = 1
                  AND ls.autorenewal_opt_id = 1



        END
        ELSE
        BEGIN

            --Non failure campaigns
            IF NOT EXISTS
            (
                SELECT 1
                FROM [dbo].[fn_app_config_select_key_values](NULL, 'AUTORENEWAL')
                WHERE [key] = @message_campaign_exact_target_name
            )
            BEGIN

                --Non-Zuora Consumer keycodes

                IF NOT EXISTS
                (
                    SELECT 1
                    FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL')
                        INNER JOIN dbo.message_campaign_product_line pl
                            ON pl.product_line_id = [key]
                    WHERE pl.message_campaign_id = @message_campaign_id
                )
                BEGIN
                    SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
                    FROM auto_renewal_message_auto_renewal_type
                    WHERE auto_renewal_message_auto_renewal_type_description = 'Auto Renewal';
                    WITH CTE
                    AS (SELECT DISTINCT
                               ls.license_id,
                               l.customer_id,
                               ce.customer_email,
                               ls.license_category_id,
                               @message_campaign_id AS message_campaign_id
                        FROM dbo.license_summary ls WITH (NOLOCK)
                            INNER JOIN license l WITH (NOLOCK)
                                ON ls.license_id = l.license_id
                            INNER JOIN
                            (
                                SELECT lm.license_id,
                                       lm.process_date AS capability_expiration_date
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                      AND lm.message_status_id = 1 --not completed to pull failures etc
                                      AND NOT EXISTS
                                (
                                    SELECT lac.license_id
                                    FROM license_autorenewal_cycle lac WITH (NOLOCK)
                                    WHERE lm.license_id = lac.license_id
                                          AND lac.message_autorenewal_cycle_id = 2
                                )
                            ) lm2
                                ON l.license_id = lm2.license_id
                            INNER JOIN customer_email ce
                                ON l.customer_id = ce.customer_id
                            LEFT JOIN @APP_CONFIG ac
                                ON ac.license_distribution_method_id = l.license_distribution_method_id
                        WHERE CAST(lm2.capability_expiration_date AS DATE) = DATEADD(
                                                                                        dd,
                                                                                        -@message_measure_days,
                                      
                                                  @date_value
                                                                                    )
                              AND ls.product_line_id IN
                                  (
                                      SELECT product_line_id
                                      FROM dbo.message_campaign_product_line
                                      WHERE message_campaign_id = @message_campaign_id
                                  )
                              AND ce.email_status_id = 1
                              AND ac.license_distribution_method_id IS NULL)
                    INSERT INTO @auto_renewal_message
                    (
                        license_id,
                        customer_id,
                        customer_email,
                        cart_discount_id,
                        exact_target_master_id,
                        auto_renewal_message_status_id,
                        mail_date,
                        license_category_id,
                        auto_renewal_message_auto_renewal_type_id
                    )
                    SELECT DISTINCT
                           c.license_id,
                           c.customer_id,
                           c.customer_email,
                           @cart_discount_id,
                           @exact_target_master_id,
                           0,
                           CAST(@date_value AS DATE),
                           c.license_category_id,
                           @auto_renewal_message_auto_renewal_type_id
                    FROM CTE c
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON ll.message_campaign_id = c.message_campaign_id
                        LEFT JOIN
                        (
                            SELECT DISTINCT
                                   cl.customer_id,
                                   ct.license_id
                            FROM dbo.customer_locale cl
                                INNER JOIN CTE ct
                                    ON ct.customer_id = cl.customer_id
                                INNER JOIN message_campaign_language_location ml
                                    ON ml.location_code = cl.location_code
                                       AND ml.message_campaign_id = ct.message_campaign_id
                        ) a
                            ON a.license_id = c.license_id
                               AND a.customer_id = c.customer_id
                    WHERE (
                              ll.location_code IS NOT NULL
                              AND a.customer_id IS NOT NULL
                          )
                          OR
                          (
                              ll.location_code IS NULL
                              AND a.customer_id IS NULL
                          )



                END --@message_campaign_name NOT LIKE '%bsn%'

                --Business keycodes
                IF EXISTS
                (
                    SELECT 1
                    FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL')
                        INNER JOIN dbo.message_campaign_product_line pl
                            ON pl.product_line_id = [key]
                    WHERE pl.message_campaign_id = @message_campaign_id
                )
                --check for SFDC records
                BEGIN
                    SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
                    FROM auto_renewal_message_auto_renewal_type
                    WHERE auto_renewal_message_auto_renewal_type_description = 'Auto Renewal';
                    WITH CTE
                    AS (SELECT DISTINCT
                               ls.license_id,
                               l.
customer_id,
                               ce.customer_email,
                               ls.license_category_id,
                               @message_campaign_id AS message_campaign_id
                        FROM dbo.license_summary ls WITH (NOLOCK)
                            INNER JOIN license l WITH (NOLOCK)
                                ON ls.license_id = l.license_id
                            INNER JOIN
                            (
                                SELECT lm.license_id,
                                       lm.process_date AS capability_expiration_date
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                      AND lm.message_status_id = 1 --not completed to pull failures etc
                            --AND NOT EXISTS (SELECT lac.license_id FROM license_autorenewal_cycle lac WITH (NOLOCK) 
                            --				WHERE lm.license_id = lac.license_id 
                            --					AND lac.message_autorenewal_cycle_id = 2)

                            ) lm2
                                ON l.license_id = lm2.license_id
                            INNER JOIN customer_email ce
                                ON l.customer_id = ce.customer_id
                        WHERE CAST(lm2.capability_expiration_date AS DATE) = DATEADD(
                                                                                        dd,
                                                                                        -@message_measure_days,
                                                                                        @date_value
                                                                                    )
                              AND ls.product_line_id IN
                                  (
                                      SELECT product_line_id
                                      FROM dbo.message_campaign_product_line
                                      WHERE message_campaign_id = @message_campaign_id
                                  )
                              AND NOT EXISTS
                        (
                            SELECT lp.child_license_id
                            FROM dbo.license_parent lp
                            WHERE lp.child_license_id = ls.license_id
                        )
                              AND ce.email_status_id = 1)
                    INSERT INTO @auto_renewal_message
                    (
                        license_id,
                        customer_id,
                        customer_email,
                        cart_discount_id,
                        exact_target_master_id,
                        auto_renewal_message_status_id,
                        mail_date,
                        license_category_id,
                        auto_renewal_message_auto_renewal_type_id
                    )
                    SELECT DISTINCT
                           c.license_id,
                           c.customer_id,
                           c.customer_email,
                           @cart_discount_id,
                           @exact_target_master_id,
                           0,
                           CAST(@date_value AS DATE),
                           c.license_category_id,
                           @auto_renewal_message_auto_renewal_type_id
                    FROM CTE c
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON ll.message_campaign_id = c.message_campaign_id
                        LEFT JOIN
                        (
                            SELECT DISTINCT
                                   cl.customer_id,
                                   ct.license_id
                            FROM dbo.customer_locale cl
                                
INNER JOIN CTE ct
                                    ON ct.customer_id = cl.customer_id
                                INNER JOIN message_campaign_language_location ml
                                    ON ml.location_code = cl.location_code
                                       AND ml.message_campaign_id = ct.message_campaign_id
                        ) a
                            ON a.license_id = c.license_id
                               AND a.customer_id = c.customer_id
                    WHERE (
                              ll.location_code IS NOT NULL
                              AND a.customer_id IS NOT NULL
                          )
                          OR
                          (
                              ll.location_code IS NULL
                              AND a.customer_id IS NULL
                          )



                    SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
                    FROM auto_renewal_message_auto_renewal_type
                    WHERE auto_renewal_message_auto_renewal_type_description = 'SFDC Auto Renewal';
                    WITH cte
                    AS (SELECT DISTINCT
                               oil.license_id,
                               oc.customer_id,
                               ce.customer_email,
                               ls.license_category_id,
                               sor.salesforce_renewal_opportunity_id,
                               @message_campaign_id AS message_campaign_id
                        FROM sfdc_opportunity_renewal sor
                            INNER JOIN order_opportunity op
                                ON sor.order_opportunity_id = op.order_opportunity_id
                            INNER JOIN order_company oc
                                ON op.order_header_id = oc.order_header_id
                                   AND oc.order_company_type_id = 2
                            INNER JOIN order_item oi
                                ON op.order_header_id = oi.order_header_id
                            INNER JOIN dbo.order_item_license oil
                                ON oi.order_item_id = oil.order_item_id
                            INNER JOIN license_summary ls
                                ON oil.license_id = ls.license_id
                            INNER JOIN customer_email ce
                                ON oc.customer_id = ce.customer_id
                        WHERE CAST(DATEADD(dd, -7, sor.process_date) AS DATE) = DATEADD(
                                                                                           dd,
                                                                                           -@message_measure_days,
                                                                                           @date_value
                                                                                       )
                              AND ls.product_line_id IN
                                  (
                                      SELECT product_line_id
                                      FROM dbo.message_campaign_product_line
                                      WHERE message_campaign_id = @message_campaign_id
                                  )
                              AND is_autorenewal_enabled = 1
                              AND sor.sfdc_opportunity_renewal_status_id IS NULL
                              AND sor.process_date IS NOT NULL
                              AND NOT EXISTS
                        (
                            SELECT lp.child_license_id
                            FROM dbo.license_parent lp
                            WHERE lp.child_license_id = ls.license_id
                        )
                              AND ce.email_status_id = 1)
                    INSERT INTO @auto_renewal_message
                    (
  
                      license_id,
                        customer_id,
                        customer_email,
                        cart_discount_id,
                        exact_target_master_id,
                        auto_renewal_message_status_id,
                        mail_date,
                        license_category_id,
                        auto_renewal_message_auto_renewal_type_id,
                        salesforce_renewal_opportunity_id
                    )
                    SELECT DISTINCT
                           c.license_id,
                           c.customer_id,
                           c.customer_email,
                           @cart_discount_id,
                           @exact_target_master_id,
                           0,
                           CAST(@date_value AS DATE),
                           c.license_category_id,
                           @auto_renewal_message_auto_renewal_type_id,
                           c.salesforce_renewal_opportunity_id
                    FROM cte c
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON ll.message_campaign_id = c.message_campaign_id
                        LEFT JOIN
                        (
                            SELECT DISTINCT
                                   cl.customer_id,
                                   ct.license_id
                            FROM dbo.customer_locale cl
                                INNER JOIN cte ct
                                    ON ct.customer_id = cl.customer_id
                                INNER JOIN message_campaign_language_location ml
                                    ON ml.location_code = cl.location_code
                                       AND ml.message_campaign_id = ct.message_campaign_id
                        ) a
                            ON a.license_id = c.license_id
                               AND a.customer_id = c.customer_id
                    WHERE (
                              ll.location_code IS NOT NULL
                              AND a.customer_id IS NOT NULL
                          )
                          OR
                          (
                              ll.location_code IS NULL
                              AND a.customer_id IS NULL
                          )
                END --@message_campaign_name NOT LIKE '%bsn%'

            END --@message_campaign_name NOT LIKE '%fail'
            --Failure campaigns
            IF EXISTS
            (
                SELECT 1
                FROM [dbo].[fn_app_config_select_key_values](NULL, 'AUTORENEWAL')
                WHERE [key] = @message_campaign_exact_target_name
            )
            BEGIN
                --Consumer keycodes
                IF NOT EXISTS
                (
                    SELECT 1
                    FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL')
                        INNER JOIN dbo.message_campaign_product_line pl
                            ON pl.product_line_id = [key]
                    WHERE pl.message_campaign_id = @message_campaign_id
                )
                BEGIN --@message_campaign_name NOT LIKE '%bsn%'

                    SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
                    FROM auto_renewal_message_auto_renewal_type
                    WHERE auto_renewal_message_auto_renewal_type_description = 'Auto Renewal';
                    WITH CTE
                    AS (SELECT DISTINCT
                               ls.license_id,
                               l.customer_id,
                               ce.customer_email,
                               ls.license_category_id,
                               @message_campaign_id AS message_campaign_id
                        FROM dbo.license_summary ls WITH (NOLOC
K)
                            INNER JOIN license l WITH (NOLOCK)
                                ON ls.license_id = l.license_id
                            INNER JOIN
                            (
                                SELECT license_id,
                                       MAX(license_message_id) license_message_id
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                      AND NOT EXISTS
                                (
                                    SELECT lac.license_id
                                    FROM license_autorenewal_cycle lac WITH (NOLOCK)
                                    WHERE lm.license_id = lac.license_id
                                          AND lac.message_autorenewal_cycle_id = 2
                                )
                                GROUP BY license_id
                            ) lmm
                                ON l.license_id = lmm.license_id
                            INNER JOIN
                            (
                                SELECT lm.license_id,
                                       lm.license_message_id,
                                       lm.process_date AS capability_expiration_date
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                      AND lm.message_status_id NOT IN ( 1, 3 )
                                      AND NOT EXISTS
                                (
                                    SELECT lac.license_id
                                    FROM license_autorenewal_cycle lac WITH (NOLOCK)
                                    WHERE lm.license_id = lac.license_id
                                          AND lac.message_autorenewal_cycle_id = 2
                                )
                            ) lm2
                                ON l.license_id = lm2.license_id
                                   AND lmm.license_message_id = lm2.license_message_id
                            INNER JOIN customer_email ce
                                ON l.customer_id = ce.customer_id
                            LEFT JOIN @APP_CONFIG ac
                                ON ac.license_distribution_method_id = l.license_distribution_method_id
                        WHERE CAST(lm2.capability_expiration_date AS DATE) = DATEADD(
                                                                                        dd,
                                                                                        -@message_measure_days,
                                                                                        @date_value
                                                                                    )
                              AND ls.product_line_id IN
                                  (
                                      SELECT product_line_id
                                      FROM dbo.message_campaign_product_line
                                      WHERE message_campaign_id = @message_campaign_id
                                  )
                              AND ls.autorenewal_opt_id = 1
                              AND ce.email_status_id = 1
                              AND ac.license_distribution_method_id IS NULL)
                    INSERT INTO @auto_renewal_message
                    (
                        license_id,
                        customer_id,
                        customer_email,
                        cart_discount_id,
                        exact_target_master_id,
                        auto_renewal_message_status_id,
                        mail_date,
                        license_category_id,
                        auto_renewal_message_auto_renewal_type_id
                    )
       
             SELECT DISTINCT
                           c.license_id,
                           c.customer_id,
                           c.customer_email,
                           @cart_discount_id,
                           @exact_target_master_id,
                           0,
                           CAST(@date_value AS DATE),
                           c.license_category_id,
                           @auto_renewal_message_auto_renewal_type_id
                    FROM CTE c
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON ll.message_campaign_id = c.message_campaign_id
                        LEFT JOIN
                        (
                            SELECT DISTINCT
                                   cl.customer_id,
                                   ct.license_id
                            FROM dbo.customer_locale cl
                                INNER JOIN CTE ct
                                    ON ct.customer_id = cl.customer_id
                                INNER JOIN message_campaign_language_location ml
                                    ON ml.location_code = cl.location_code
                                       AND ml.message_campaign_id = ct.message_campaign_id
                        ) a
                            ON a.license_id = c.license_id
                               AND a.customer_id = c.customer_id
                    WHERE (
                              ll.location_code IS NOT NULL
                              AND a.customer_id IS NOT NULL
                          )
                          OR
                          (
                              ll.location_code IS NULL
                              AND a.customer_id IS NULL
                          )

                --@message_campaign_name NOT LIKE '%bsn%'
                END
                --Business keycodes
                IF EXISTS
                (
                    SELECT 1
                    FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL')
                        INNER JOIN dbo.message_campaign_product_line pl
                            ON pl.product_line_id = [key]
                    WHERE pl.message_campaign_id = @message_campaign_id
                )
                BEGIN
                    SELECT @auto_renewal_message_auto_renewal_type_id = auto_renewal_message_auto_renewal_type_id
                    FROM auto_renewal_message_auto_renewal_type
                    WHERE auto_renewal_message_auto_renewal_type_description = 'Auto Renewal';
                    WITH CTE
                    AS (SELECT DISTINCT
                               ls.license_id,
                               l.customer_id,
                               ce.customer_email,
                               ls.license_category_id,
                               @message_campaign_id AS message_campaign_id
                        FROM dbo.license_summary ls WITH (NOLOCK)
                            INNER JOIN license l WITH (NOLOCK)
                                ON ls.license_id = l.license_id
                            INNER JOIN
                            (
                                SELECT license_id,
                                       MAX(license_message_id) license_message_id
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                --      AND NOT EXISTS
                                --(
                                --    SELECT lac.license_id
                                --    FROM license_autorenewal_cycle lac WITH (NOLOCK)
                                --    WHERE lm.license_id = lac.license_id
                                --          AND lac.message_autorenewal_cycle_id = 2
                                --)
                         
       GROUP BY license_id
                            ) lmm
                                ON l.license_id = lmm.license_id
                            INNER JOIN
                            (
                                SELECT lm.license_id,
                                       lm.license_message_id,
                                       lm.process_date AS capability_expiration_date
                                FROM license_message lm WITH (NOLOCK)
                                WHERE lm.message_type_id = 3
                                      AND lm.message_status_id NOT IN ( 1, 3 )
                            --      AND NOT EXISTS
                            --(
                            --    SELECT lac.license_id
                            --    FROM license_autorenewal_cycle lac WITH (NOLOCK)
                            --    WHERE lm.license_id = lac.license_id
                            --          AND lac.message_autorenewal_cycle_id = 2
                            --)
                            ) lm2
                                ON l.license_id = lm2.license_id
                                   AND lmm.license_message_id = lm2.license_message_id
                            INNER JOIN customer_email ce
                                ON l.customer_id = ce.customer_id
                        WHERE CAST(lm2.capability_expiration_date AS DATE) = DATEADD(
                                                                                        dd,
                                                                                        -@message_measure_days,
                                                                                        @date_value
                                                                                    )
                              AND ls.product_line_id IN
                                  (
                                      SELECT product_line_id
                                      FROM dbo.message_campaign_product_line
                                      WHERE message_campaign_id = @message_campaign_id
                                  )
                              AND ls.autorenewal_opt_id = 1
                              AND NOT EXISTS
                        (
                            SELECT lp.child_license_id
                            FROM dbo.license_parent lp
                            WHERE lp.child_license_id = ls.license_id
                        )
                              AND ce.email_status_id = 1)
                    INSERT INTO @auto_renewal_message
                    (
                        license_id,
                        customer_id,
                        customer_email,
                        cart_discount_id,
                        exact_target_master_id,
                        auto_renewal_message_status_id,
                        mail_date,
                        license_category_id,
                        auto_renewal_message_auto_renewal_type_id
                    )
                    SELECT DISTINCT
                           c.license_id,
                           c.customer_id,
                           c.customer_email,
                           @cart_discount_id,
                           @exact_target_master_id,
                           0,
                           CAST(@date_value AS DATE),
                           c.license_category_id,
                           @auto_renewal_message_auto_renewal_type_id
                    FROM CTE c
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON ll.message_campaign_id = c.message_campaign_id
                        LEFT JOIN
                        (
                            SELECT DISTINCT
                                   cl.customer_id,
                                   ct.license_id
                         
   FROM dbo.customer_locale cl
                                INNER JOIN CTE ct
                                    ON ct.customer_id = cl.customer_id
                                INNER JOIN message_campaign_language_location ml
                                    ON ml.location_code = cl.location_code
                                       AND ml.message_campaign_id = ct.message_campaign_id
                        ) a
                            ON a.license_id = c.license_id
                               AND a.customer_id = c.customer_id
                    WHERE (
                              ll.location_code IS NOT NULL
                              AND a.customer_id IS NOT NULL
                          )
                          OR
                          (
                              ll.location_code IS NULL
                              AND a.customer_id IS NULL
                          )
                END
            END
        END
        SET @campaign_id = @campaign_id + 1
    END --campaign loop


    INSERT INTO auto_renewal_message
    (
        license_id,
        license_category_id,
        salesforce_renewal_opportunity_id,
        customer_id,
        customer_email,
        cart_discount_id,
        exact_target_master_id,
        auto_renewal_message_status_id,
        mail_date,
        auto_renewal_message_auto_renewal_type_id
    )
    SELECT ar.license_id,
           ar.license_category_id,
           ar.salesforce_renewal_opportunity_id,
           ar.customer_id,
           ar.customer_email,
           ar.cart_discount_id,
           ar.exact_target_master_id,
           ar.auto_renewal_message_status_id,
           ar.mail_date,
           ar.auto_renewal_message_auto_renewal_type_id
    FROM @auto_renewal_message ar




END TRY
BEGIN CATCH
    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;


GO
