-- PROCEDURE: [dbo].[usp_auto_renewal_message_select_output_file]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_auto_renewal_message_select_output_file]
(@date_value DATETIME = NULL )

AS

SET NOCOUNT ON


/* 

	DATE		AUTHOR			REMARKS
	2019-09-25	mrobbins		Initial creation 
	2019-10-30	mrobbins		defect 1041 for duplicate records - currency_language_location had 2 records for certain countries
								found issue with missing opp.amount therefore provide empty string for output
	2019-12-09	mrobbins		added monthly_billing to output WATERBEARS-1250
	2020-01-06	mrobbins		update to usp_cart_select_license_configurator_pricing - WATERBEARS-1578
	2020-02-24	mrobbins		removed formatting for currency on @rec insert for SFDC AR records - formatting should happen into @return for varchar columns - WATERBEARS 1687
	2023-10-31  psatish			ECOM-2557 Added the user_guid which is safe_Account_user_guid and license_key fields to the @return table
	2023-12-06	schindar		ECOM-1596 selecting latest order based on credit card information/paypal. 
	2024-03-28  psatish			ECOM-4057 Fixed the credit card fields and netprice/json_call
								Step 1: Return the correct payment method in the credit_card_type field and display the credit card information if the latest order payment was made by credit card
								Step 2: For business keycodes, calculate the net price by summing up the unit price total and excluding expired products except for failure campaigns.  
								Step 3: Updated the json_call field for Business Keycodes

	2024-04-09  psatish			ECOM-2381 Return the credit card details at the license level for Zuora licenses if exists
	2024-12-12	rambasana		IM-352435 Return the discount for Zuora license 
	2025-05-01  psatish			US-4653512 Added an additional field called next_bill_date in the output
	2026-03-27  jberry			US-5308586 - Added new fields to @cart_select_license_configurator_pricing

	DESCRIPTION

	DEPENCENCIES : usp_cart_select_license_configurator_pricing
				 : usp_cart_select_renewal_product_set 
	SQL JOB		 : Exact Target Daily AR PROD job is scheduled to run at 8 a.m. MST and calls the Exact Target Daily AR SSIS job in cordenetl2.services.webroot. 
				   It sends the output file for AUTORENEWAL to Salesforce Marketing Cloud.

               
*/

	BEGIN TRY


		

		DECLARE @response_code INT,
			@message VARCHAR(100),
			@rec_id INT,
			@max_rec_id INT,
			@keycode VARCHAR(40),
			@license_category_name VARCHAR(10),
			@seats INT,
			@storage INT,
			@years FLOAT,
			@cart_discount_id INT,
			@language_code VARCHAR(2),
			@location_code VARCHAR(3),
			@retail_price MONEY,
			@net_price MONEY,
			@discount MONEY,
			@currency_symbol VARCHAR(2),
			@product_line_id INT,
			@return_id INT,
			@max_return_id INT,
			@message_service_id INT,
			@message_service_type_id INT,
			@message_service_json VARCHAR(MAX),
            @message_service_type_name VARCHAR(50),
            @message_service_client_id INT,
            @customer_email VARCHAR(100),
			@order_header_id INT,
			@license_id INT,
			@item_json NVARCHAR(MAX),
			@bundle_json NVARCHAR(MAX),
			@PAYMENT_METHOD VARCHAR(50),
			@campaign_name VARCHAR(50),
			@expiration_date DATE,
			@next_bill_date DATETIME

		DECLARE @APP_CONFIG TABLE
		(
		CAMPAIGN_NAME VARCHAR(50),
		DISTRIBUTION_METHOD_CODE VARCHAR(4)
		)
			
		IF @date_value IS NULL OR @date_value = '' OR LEN(@date_value) = 0
			SET @date_value = GETDATE() 

		SELECT @PAYMENT_METHOD = [key]
		FROM [dbo].[fn_app_config_select_key_values]('PAYMENT_METHOD', 'CREDIT_CARD_ORDERS')

		DROP TABLE IF EXISTS #recs
		CREATE TABLE #recs (rec_id INT IDENTITY(1,1) PRIMARY KEY,
			auto_renewal_message_id INT,
			customer_id INT,
			license_id INT,
			keycode VARCHAR(40), 
			license_keycode_type_i
d INT,
			license_category_name VARCHAR(10),
			license_category_id INT,
			license_seats INT,
			storage_gb INT, 
			years FLOAT, 
			cart_discount_id INT NULL,
			language_code VARCHAR(2),
			location_code VARCHAR(3),
			iso VARCHAR(2),
			product_line_id INT,
			retail_price MONEY,
			net_price MONEY,
			discount MONEY,
			currency_symbol VARCHAR(10),
			salesforce_renewal_opportunity_id VARCHAR(50),
			auto_renewal_message_auto_renewal_type_id INT,
			monthly_billing INT DEFAULT 0,
			json_call NVARCHAR(MAX),
			message_campaign_exact_target_name VARCHAR(50),
			license_distribution_method_code VARCHAR(4),
			next_bill_date DATETIME)
	
		CREATE NONCLUSTERED INDEX index_temp_recs ON #recs(rec_id,license_id) INCLUDE(keycode,auto_renewal_message_id,customer_id,location_code,license_distribution_method_code)
		

		INSERT INTO @APP_CONFIG
		(
		    CAMPAIGN_NAME
		)
		SELECT [key]
		FROM [dbo].[fn_app_config_select_key_values]('AR_CAMPAIGN_NAME','AUTORENEWAL')

		INSERT INTO @APP_CONFIG
		(
		    DISTRIBUTION_METHOD_CODE
		)
		SELECT [key]
		FROM [dbo].[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') 


		INSERT INTO #recs(auto_renewal_message_id,
			customer_id,
			license_id,
			keycode, 
			license_keycode_type_id,
			license_category_name,
			license_category_id,
			license_seats,
			storage_gb, 
			years, 
			cart_discount_id,
			product_line_id,
			auto_renewal_message_auto_renewal_type_id,
			monthly_billing,
			message_campaign_exact_target_name,
			license_distribution_method_code)
		SELECT DISTINCT ar.auto_renewal_message_id,
			ar.customer_id,
			ar.license_id,
			ls.keycode,
			l.license_keycode_type_id,
			lc.license_category_name,
			lc.license_category_id,
			ls.license_seats,
			ls2.storage_gb,
			1 years,
			ar.cart_discount_id,
			ls.product_line_id,
			auto_renewal_message_auto_renewal_type_id,
			CASE WHEN lac.license_id IS NOT NULL THEN 
				1 
			ELSE 
				0
			END monthly_billing,
			etmc.message_campaign_exact_target_name,
			dm.license_distribution_method_code
		FROM dbo.auto_renewal_message ar
			INNER JOIN dbo.exact_target_master etm
				ON etm.exact_target_master_id = ar.exact_target_master_id
			INNER JOIN dbo.exact_target_message_campaign  etmc
				ON etmc.exact_target_message_campaign_id = etm.exact_target_message_campaign_id
			INNER JOIN license_summary ls
				ON ar.license_id = ls.license_id
			INNER JOIN license l
				ON l.license_id = ar.license_id
			INNER JOIN  dbo.license_category lc
				ON ls.license_category_id = lc.license_category_id
			LEFT JOIN license_storage ls2
				ON ar.license_id = ls2.license_id
			LEFT JOIN license_autorenewal_cycle lac 
				ON ar.license_id = lac.license_id 
					AND lac.message_autorenewal_cycle_id = 2
			LEFT JOIN dbo.license_distribution_method dm
				ON dm.license_distribution_method_id = l.license_distribution_method_id
		WHERE auto_renewal_message_auto_renewal_type_id = 1
			AND CAST(ar.mail_date AS DATE) = CAST(@date_value AS DATE) 
			AND ar.auto_renewal_message_status_id = 0
		ORDER BY ar.license_id

		--SELECT * FROM #recs
		
		DECLARE @proc_return TABLE(
			product_id INT, 
			product_description VARCHAR(100), 
			retail_price MONEY, 
			upgrade_price MONEY, 
			discount MONEY, 
			standard_discount MONEY DEFAULT 0, 
			net_price MONEY,
			product_type_id INT, 
			license_category_name VARCHAR(10), 
			seats INT, 
			years FLOAT, 
			p_type VARCHAR(20), 
			currency_id TINYINT, 
			currency_code CHAR(3), 
			currency_description VARCHAR(20), 
			symbol_html VARCHAR(10), 
			symbol_utf8 NVARCHAR(10), 
			symbol_text VARCHAR(10), 
			cart_discount_id INT NULL)

		DECLARE @license_profile TABLE (item_id INT, 
			license_id INT, 
			license_category_name VARCHAR(10),
			license_category_description VARCHAR(255),
			license_seats INT,
			storage_gb INT,
			license_keycode_type_id INT,
			start_date DATETIME,

			expiration_date DATETIME,
			license_attribute_id INT,
			license_attribute_description VARCHAR(150),
			license_attribute_license_value VARCHAR(150),
			license_attribute_license_value_description VARCHAR(150),
			category_type_name VARCHAR(50),
			item_hierarchy_id TINYINT,
			item_hierarchy_name VARCHAR(50),
			license_status_id INT,
			license_status_description VARCHAR(150),
			autorenewal_cycle_name VARCHAR(50),
			autorenewal_cycle DECIMAL(18,3))

		DECLARE  @item_json_table TABLE(
			item_json_table_id INT IDENTITY(1,1),
			item_hierarchy_id INT,
			quantity INT,
			cart_item_bundle_id INT,
			years INT,
			license_category_name VARCHAR(10),
			license_seats INT,
			storage_gb INT,
			cart_discount_id INT)

		DECLARE @cart_select_license_configurator_pricing TABLE(
			line_item INT,
			quantity INT, 
			order_item_offer_amount MONEY DEFAULT 0, 
			equivalent_year_price MONEY DEFAULT 0,  
			list_price MONEY DEFAULT 0, 
			unit_price MONEY DEFAULT 0, 
			usage_price MONEY DEFAULT 0,
			product_id INT,
			product_description VARCHAR(155),
			product_type_id INT, 
			product_type_description VARCHAR(155),
			license_keycode_type_id INT,
			license_category_id INT,
			license_category_name VARCHAR (10),
			license_category_description VARCHAR (155),
			product_family_description VARCHAR(155),
			start_date DATETIME ,
			expiration_date DATETIME, 
			cart_item_bundle_id INT,
			item_hierarchy_id TINYINT ,
			dependent_cart_order_itemid INT,
			keycode VARCHAR(40),
			discount FLOAT,
			cart_discount_method_id INT, 
			cart_discount_id INT,
			license_id INT,
			list_price_total MONEY DEFAULT 0,
			unit_price_total MONEY DEFAULT 0,
			json_call NVARCHAR(MAX),
			storage_gb INT, 
			usage_pricing_model_id INT, 
			retention_model_id INT, 
			retention_term INT, 
			retention_model_name INT, 
			actual_storage_quantity INT) 

		DECLARE @max_customer_locale TABLE(
			customer_locale_id INT,
			customer_id INT)

		INSERT INTO @max_customer_locale
		(
		    customer_locale_id,
			customer_id
		)
		SELECT MAX(cl.customer_locale_id),
			cl.customer_id
		FROM #recs r
			INNER JOIN dbo.customer_locale cl
				ON r.customer_id = cl.customer_id
		WHERE r.auto_renewal_message_auto_renewal_type_id = 1
		GROUP BY cl.customer_id

			
		UPDATE r
		SET r.language_code = CASE WHEN cl.language_code IS NULL THEN 'EN' ELSE cl.language_code END ,
			r.location_code = CASE WHEN cl.location_code IS NULL THEN 'USA' ELSE cl.location_code END,
			r.iso = CASE WHEN luc.iso IS NULL THEN 'US' ELSE luc.iso END
		FROM #recs r
			LEFT JOIN @max_customer_locale mcl
				ON r.customer_id = mcl.customer_id
			LEFT JOIN customer_locale cl
				ON mcl.customer_locale_id = cl.customer_locale_id
			LEFT JOIN lu_countries luc
				ON cl.location_code = luc.iso3
		WHERE r.auto_renewal_message_auto_renewal_type_id = 1

		
		SELECT @rec_id = MIN(rec_id), @max_rec_id = MAX(rec_id)
		FROM #recs

		WHILE @rec_id <= @max_rec_id
			BEGIN
				SELECT @license_id = license_id,
					@keycode = keycode,
					@license_category_name = license_category_name,
					@seats = license_seats, 
					@storage = storage_gb, 
					@years = years,
					@cart_discount_id = cart_discount_id,
					@language_code = language_code,
					@location_code = location_code,
					@product_line_id = product_line_id,
					@campaign_name = message_campaign_exact_target_name
				FROM #recs
				WHERE rec_id = @rec_id

				IF @product_line_id = 300
					BEGIN


						DELETE FROM @item_json_table
						DELETE FROM @license_profile
						DELETE FROM @cart_select_license_configurator_pricing

						INSERT INTO @license_profile
						(
							item_id,
							license_id,
							license_category_name,
							license_seats,
							storage_gb,
							license_keycode_type_id,
							start_date,
							expiration_date,
							license_attribute_id,
							license_attribute_description,
					
		license_attribute_license_value,
							license_attribute_license_value_description,
							category_type_name,
							item_hierarchy_id,
							license_status_id,
							license_status_description,
							autorenewal_cycle_name,
							autorenewal_cycle
						)
						SELECT item_id,
							license_id,
							f.license_category_name,
							license_seats,
							storage_gb,
							license_keycode_type_id,
							start_date,
							expiration_date,
							license_attribute_id,
							license_attribute_description,
							license_attribute_license_value,
							license_attribute_license_value_description,
							category_type_name,
							item_hierarchy_id,
							license_status_id,
							license_status_description,
							autorenewal_cycle_name,
							autorenewal_cycle
							FROM dbo.fn_license_select_license_profile(@license_id) f
							WHERE f.expiration_date >= CASE
							                               WHEN EXISTS
													(
														SELECT 1 FROM @APP_CONFIG WHERE CAMPAIGN_NAME = @campaign_name
													) THEN
																					   f.expiration_date
																				   ELSE
																					   GETDATE()
																			   END

						UPDATE lp
						SET lp.license_category_description = lc.license_category_description
						FROM @license_profile lp
							LEFT JOIN dbo.license_category lc
								ON lc.license_category_name = lp.license_category_name
				

						INSERT INTO @item_json_table
						(
							item_hierarchy_id,
							quantity,
							cart_item_bundle_id,
							years,
							license_category_name,
							license_seats,
							storage_gb,
							cart_discount_id
						)
						SELECT item_hierarchy_id,
							1,
							1,
							1,
							license_category_name,
							license_seats,
							storage_gb,
							@cart_discount_id
						FROM @license_profile


						SELECT @item_json = (SELECT quantity,
							item_hierarchy_id,
							cart_item_bundle_id,
							years,
							license_category_name,
							license_seats,
							ISNULL(storage_gb,'') storage_gb,
							cart_discount_id
						FROM @item_json_table
						FOR JSON PATH)

						SELECT @bundle_json = (SELECT LOWER(r.language_code) + '_' + LOWER(lc.iso) locale,
							keycode,
							license_keycode_type_id
						FROM #recs r
							INNER JOIN dbo.lu_countries lc
								ON r.location_code = lc.iso3
						WHERE rec_id = @rec_id
						FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)


						INSERT INTO @cart_select_license_configurator_pricing
						(
							line_item,
							quantity,
							order_item_offer_amount,
							equivalent_year_price,
							list_price,
							unit_price,
							usage_price,
							product_id,
							product_description,
							product_type_id,
							product_type_description,
							license_keycode_type_id,
							license_category_id,
							license_category_name,
							license_category_description,
							product_family_description,
							start_date,
							expiration_date,
							cart_item_bundle_id,
							item_hierarchy_id,
							dependent_cart_order_itemid,
							keycode,
							discount,
							cart_discount_method_id,
							cart_discount_id,
							storage_gb, 
							usage_pricing_model_id, 
							retention_model_id, 
							retention_term, 
							retention_model_name, 
							actual_storage_quantity 
						)
						EXEC usp_cart_select_license_configurator_pricing @item_json, @bundle_json


						UPDATE c
						SET c.license_id = l.license_id,
							c.list_price_total = list_price *quantity,
							c.unit_price_total = unit_price * quantity,
							c.json_call = 'EXEC usp_cart_select_license_configurator_pricing ''' + @item_json + ''', ''' + @bundle_json + ''''
						FROM @cart_select_license_configurator_pricing c
							INNER JOIN dbo.license l
								ON c.keycode = l.keycode

						--SELECT json_call
						--FROM @cart_select_license_configurator_pricing

						UPDATE r
						SET retail_price = c.list_price_total,
							net_price = c.unit_price_total,
							discount = c.list_price_total - c.unit_price_total,
							r.json_call = c.json_call
						FROM #recs r
							INNER JOIN
							(
								SELECT SUM(list_price_total) AS list_price_total,
									   SUM(unit_price_total) AS unit_price_total,
									   license_id,
									   MAX(json_call) AS json_call
								FROM @cart_select_license_configurator_pricing
								GROUP BY license_id
							) c
							ON c.license_id = r.license_id
						WHERE  r.license_id =@license_id




					END 
				ELSE
					BEGIN
						INSERT INTO @proc_return 
						EXEC usp_cart_select_renewal_product_set 
							@keycode, 
							@license_category_name, 
							@seats, 
							@storage,
							@years,
							@cart_discount_id, 
							@language_code,
							@location_code
							--EXEC ecommerce_daily.dbo.usp_cart_select_renewal_product_set 'SSHAONLNAADJXGRBMLRI', 'WSAV', 5, 0,1

						SELECT @retail_price = SUM(retail_price),
							@net_price = SUM(net_price),
							@currency_symbol = symbol_utf8,
							@discount = SUM(discount)
						FROM @proc_return
						WHERE retail_price <> 0.00
						GROUP BY symbol_utf8

						UPDATE #recs
						SET retail_price = @retail_price,
							net_price = @net_price,
							currency_symbol = @currency_symbol,
							discount = @discount
						WHERE license_id =@license_id

						DELETE FROM @proc_return
			
					--Get discount for zuora product
			
						IF EXISTS (SELECT 1 FROM #recs rc
									INNER JOIN @APP_CONFIG ac ON ac.DISTRIBUTION_METHOD_CODE = rc.license_distribution_method_code
									WHERE rc.license_id = @license_id)
						BEGIN
                        
							SELECT @expiration_date = ISNULL( ln.next_bill_date ,c.capability_expiration_date),@next_bill_date=ln.next_bill_date
							FROM #recs rc
							INNER JOIN dbo.license_category_license l ON l.license_id = rc.license_id
							INNER JOIN dbo.license_category lc ON lc.license_category_id = l.license_category_id 
							INNER JOIN dbo.license_capability c ON c.license_id = rc.license_id AND c.capability_id = lc.base_capability_id
							LEFT JOIN dbo.license_next_bill_date ln ON ln.license_id = rc.license_id
							WHERE rc.license_id = @license_id 

							UPDATE rc
							SET rc.discount = dc.autorenewal_discount,
								rc.net_price = ROUND(rc.net_price - (rc.net_price * (dc.autorenewal_discount / 100)), 2)
							FROM  #recs rc
							INNER JOIN (
								SELECT MAX(lad.license_autorenewal_discount_id) max_license_autorenewal_discount_id,
									   lad.license_id
								FROM dbo.license_autorenewal_discount lad
								   INNER JOIN #recs r ON r.license_id = lad.license_id
								WHERE r.license_id = @license_id
								AND @expiration_date BETWEEN lad.discount_start_date AND lad.discount_end_date
								GROUP BY lad.license_id
							) a ON rc.license_id = a.license_id
								INNER JOIN dbo.license_autorenewal_discount lad1
									ON lad1.license_id = rc.license_id
									   AND a.max_license_autorenewal_discount_id = lad1.license_autorenewal_discount_id
								INNER JOIN dbo.autorenewal_discount_type dc
									ON dc.autorenewal_discount_type_id = lad1.autorenewal_discount_type_id
								INNER JOIN @APP_CONFIG ac ON ac.DISTRIBUTION_METHOD_CODE = rc.license_distribution_method_code
								WHERE rc.license_id = @license_id

							UPDATE #recs
							SET next_bill_date=@next_bill_date
							WHERE license_id=@license_id
						END
					END 

				
				--SELECT *
				--FROM @proc_return

				

				SET @rec_id = @rec_id + 1

				SET @license_id = NULL
				SET @keycode = NULL
				SET @license_category_name = NULL
				SET @seats = NULL
				SET @storage = NULL 
				SET @years = NULL
				SET @cart_discount_id = NULL
				SET @bundle_json = NULL
				SET @item_json = NULL 

				SET @retail_price = 0.00
				SET @net_p
rice = 0.00
				SET @discount = 0.00
				SET @next_bill_date = NULL
			
			END --WHILE loop
		
		---------------------------------------------
		--SFDC Pricing From Opp
		---------------------------------------------
		INSERT INTO #recs(auto_renewal_message_id,
			customer_id,
			license_id,
			keycode, 
			license_category_name,
			license_category_id,
			license_seats,
			storage_gb, 
			years, 
			cart_discount_id,
			product_line_id,
			salesforce_renewal_opportunity_id,
			auto_renewal_message_auto_renewal_type_id,
			monthly_billing,
			message_campaign_exact_target_name)
		SELECT DISTINCT ar.auto_renewal_message_id,
			ar.customer_id,
			ar.license_id,
			ls.keycode,
			lc.license_category_name,
			lc.license_category_id,
			ls.license_seats,
			ls2.storage_gb,
			1 years,
			ar.cart_discount_id,
			ls.product_line_id,
			ar.salesforce_renewal_opportunity_id,
			auto_renewal_message_auto_renewal_type_id,
			CASE WHEN lac.license_id IS NOT NULL THEN 
				1 
			ELSE 
				0
			END monthly_billing,
			etmc.message_campaign_exact_target_name
		FROM dbo.auto_renewal_message ar
			INNER JOIN dbo.exact_target_master etm
				ON etm.exact_target_master_id = ar.exact_target_master_id
			INNER JOIN dbo.exact_target_message_campaign  etmc
				ON etmc.exact_target_message_campaign_id = etm.exact_target_message_campaign_id
			INNER JOIN license_summary ls
				ON ar.license_id = ls.license_id
			INNER JOIN  dbo.license_category lc
				ON ls.license_category_id = lc.license_category_id
			LEFT JOIN license_storage ls2
				ON ar.license_id = ls2.license_id
			LEFT JOIN license_autorenewal_cycle lac 
				ON ar.license_id = lac.license_id 
					AND lac.message_autorenewal_cycle_id = 2
		WHERE ar.auto_renewal_message_auto_renewal_type_id = 2
			AND CAST(ar.mail_date AS DATE) = CAST(@date_value AS DATE) 
			AND ar.auto_renewal_message_status_id = 0

 

--Payment info at the license level	for zuora licenses   
    DECLARE @latest_order TABLE
    (
        license_id INT,
        payment_method_name VARCHAR(50),
		payment_account_id INT
    );

	INSERT INTO @latest_order
	(
	    license_id,
	    payment_method_name,
	    payment_account_id
	)
	SELECT a.license_id,
	       pm.payment_method_name,
	       CASE
	           WHEN pm.payment_method_name = @PAYMENT_METHOD
	                OR pm.payment_method_name IN
	                   (
	                       SELECT card_type_description FROM dbo.card_type
	                   ) THEN
	               a.payment_account_id
	       END
	FROM
	(
	    SELECT pl.license_id,
	           pl.payment_header_id,
	           MAX(pa.payment_account_id) AS payment_account_id
	    FROM #recs rc
			INNER JOIN @APP_CONFIG ac
				ON ac.DISTRIBUTION_METHOD_CODE = rc.license_distribution_method_code
	        INNER JOIN dbo.payment_license pl
	            ON pl.license_id = rc.license_id
	        LEFT JOIN dbo.payment_account pa
	            ON pa.payment_header_id = pl.payment_header_id
	    GROUP BY pl.license_id,
	             pl.payment_header_id
	) a
	    INNER JOIN payment_header ph
	        ON ph.payment_header_id = a.payment_header_id
	    INNER JOIN dbo.payment_method pm
	        ON pm.payment_method_id = ph.payment_method_id

--Payment info at the order level for non-zuora licenses

	INSERT INTO @latest_order
	(
		license_id,
		payment_method_name,
		payment_account_id
	)
	SELECT a.license_id,
		   pm.payment_method_name,
		   CASE
			   WHEN pm.payment_method_name = @PAYMENT_METHOD
					OR pm.payment_method_name IN
					   (
						   SELECT card_type_description FROM dbo.card_type
					   ) THEN
				   a.payment_account_id
		   END
	FROM
	(
		SELECT rc.license_id,
			   MAX(oh.order_header_id) AS order_header_id,
			   MAX(pa.payment_account_id) AS payment_account_id
		FROM #recs rc
			INNER JOIN dbo.order_item_license ol
				ON rc.license_id = ol.license_id
			INNER JOIN dbo.or
der_item oi
				ON oi.order_item_id = ol.order_item_id
			INNER JOIN dbo.order_header oh
				ON oh.order_header_id = oi.order_header_id
			INNER JOIN dbo.order_payment_header oph
				ON oh.order_header_id = oph.order_header_id
			LEFT JOIN dbo.payment_account pa
				ON pa.payment_header_id = oph.payment_header_id
			LEFT JOIN @APP_CONFIG ac
				ON ac.DISTRIBUTION_METHOD_CODE = rc.license_distribution_method_code
			WHERE ac.DISTRIBUTION_METHOD_CODE IS NULL
		GROUP BY rc.license_id
	) a
		INNER JOIN dbo.order_payment_header oph
			ON oph.order_header_id = a.order_header_id
		INNER JOIN dbo.payment_header ph
			ON ph.payment_header_id = oph.payment_header_id
		INNER JOIN dbo.payment_method pm
			ON pm.payment_method_id = ph.payment_method_id


		DELETE FROM @max_customer_locale

		INSERT INTO @max_customer_locale
		(
		    customer_locale_id,
			customer_id
		)
		SELECT MAX(cl.customer_locale_id),
			cl.customer_id
		FROM #recs r
			INNER JOIN dbo.customer_locale cl
				ON r.customer_id = cl.customer_id
		WHERE r.auto_renewal_message_auto_renewal_type_id = 2
		GROUP BY cl.customer_id		

	
		UPDATE r
		SET r.language_code = CASE WHEN cl.language_code IS NULL THEN 'EN' ELSE cl.language_code END ,
			r.location_code = CASE WHEN cl.location_code IS NULL THEN 'USA' ELSE cl.location_code END,
			r.iso = CASE WHEN luc.iso IS NULL THEN 'US' ELSE luc.iso END,
			net_price = CASE WHEN opp.amount IS NOT NULL THEN 
							CONVERT(MONEY,opp.Amount)
						ELSE 0
						END,
			currency_symbol = c.symbol_utf8 
		FROM #recs r
			LEFT JOIN @max_customer_locale mcl
				ON r.customer_id = mcl.customer_id
			LEFT JOIN customer_locale cl
				ON mcl.customer_locale_id = cl.customer_locale_id
			LEFT JOIN lu_countries luc
				ON cl.location_code = luc.iso3
			INNER JOIN DATAWAREHOUSEREADONLY.Salesforce.dbo.Opportunity opp
				ON r.salesforce_renewal_opportunity_id = opp.Id 
			INNER JOIN dbo.currency c
				ON opp.CurrencyIsoCode = c.currency_code 
			LEFT JOIN dbo.currency_language_location cll
				ON cll.location_code = cl.location_code
					AND cll.language_code = cl.language_code
		WHERE r.auto_renewal_message_auto_renewal_type_id = 2


		DECLARE @return TABLE(return_id INT IDENTITY(1,1),
			license_id INT,
			campaign NVARCHAR(50),
			keycode varchar(50),
			net_price NVARCHAR(255),
			customer_email NVARCHAR(150),
			first_name nvarchar(255),
			last_name nvarchar(255),
			capability_expiration_date NVARCHAR(255),
			license_category_name NVARCHAR(100),
			license_category_description NVARCHAR(100),
			renewal_length NVARCHAR(50),
			credit_card_type NVARCHAR(50),
			credit_card_last_four NVARCHAR(50),
			credit_card_expiration NVARCHAR(50),
			language NVARCHAR(100),
			location NVARCHAR(100),
			URL nvarchar(1000),
			message_service_type_id INT,
			exact_target_batch_id INT,
			customer_id INT,
			person_id INT,
			auto_renewal_message_auto_renewal_type NVARCHAR(100),
			monthly_billing INT,
			json_call NVARCHAR(MAX),
			license_key VARCHAR(40),
			user_guid VARCHAR(40),
			next_bill_date DATETIME)

	
		

		INSERT INTO @return(license_id,
			campaign,
			keycode,
			net_price,
			customer_email,
			first_name,
			last_name,
			capability_expiration_date,
			license_category_description,
			license_category_name,
			renewal_length,
			credit_card_type,
			credit_card_last_four,
			credit_card_expiration,
			language,
			location,
			URL,
			auto_renewal_message_auto_renewal_type,
			monthly_billing,
			json_call,
			license_key,
			user_guid,
			next_bill_date)
		SELECT DISTINCT ar.license_id,
			LEFT(r.message_campaign_exact_target_name,50) campaign,
			ls.keycode,
			CASE WHEN r.net_price IS NOT NULL THEN 
				FORMAT(r.net_price, 'C', r.language_code + '-' + luc.iso) 
			ELSE 
				''
			END Net_Price,
			LEFT(ar.customer_email,100) customer_email,
			c.first_name,
			c.last_name,
			CASE WHEN ls.capability_expiratio
n_date IS NULL THEN
				CONVERT(VARCHAR(10),lcap.capability_expiration_date,20)
			ELSE
				CONVERT(VARCHAR(10),ls.capability_expiration_date,20)
			END capability_expiration_date,
			CASE WHEN lc.license_category_name IN ('SS', 'SSDF','SSAV', 'SSAVDF') THEN 'Webroot SecureAnywhere AntiVirus'
				WHEN lc.license_category_name IN ('WISC') THEN 'Webroot SecureAnywhere Internet Security Complete'
				WHEN lc.license_category_name IN ('WW') THEN 'Webroot Window Washer'
				WHEN lc.license_category_name IN ('ADP') THEN 'Webroot SecureAnywhere Mobile Premier'
			ELSE 
				lc.license_category_description
			END license_category_description, 
			lc.license_category_name,
			'1 Year' renewal_length,		
			ISNULL(ct.card_type_description,lo.payment_method_name) credit_card_type,
			RIGHT(pa.account_number,4) credit_card_last_four,
			RIGHT('000'+convert(VARCHAR(2),pa.expiration_month),2) + '/' + CONVERT(VARCHAR(4),pa.expiration_year) credit_card_expiration,
			r.language_code language,
			r.location_code location,
			CASE WHEN ar.auto_renewal_message_auto_renewal_type_id = 1 THEN 
				CASE WHEN cd.cart_discount_key IS NULL THEN
					'https://www.webroot.com/' + LOWER(r.iso)  + '/' + LOWER(r.language_code) + '/cart/update?key='  + CONVERT(VARCHAR(50),ls.license_key) + '&routing_action=billing' 
				ELSE
					CASE WHEN lc.license_category_name IN ('SS','WW') THEN
						'https://www.webroot.com/' + LOWER(r.iso)  + '/' + LOWER(r.language_code) + '/cart/update?key='  + CONVERT(VARCHAR(50),ls.license_key) + '&cart_discount_key=' + CONVERT(VARCHAR(50),cd.cart_discount_key) + '&routing_action=billing' 
					ELSE
						'https://www.webroot.com/' + LOWER(r.iso)  + '/' + LOWER(r.language_code) + '/cart/update?key='  + CONVERT(VARCHAR(50),ls.license_key) + '&routing_action=billing'
					END 
				END 
			END URL,
			CASE WHEN r.auto_renewal_message_auto_renewal_type_id = 1 THEN 'ONLINE'
				WHEN r.auto_renewal_message_auto_renewal_type_id = 2 THEN 'SFDC'
			END auto_renewal_message_auto_renewal_type,
			r.monthly_billing,
			r.json_call,
			ls.license_key,  --LicenseKey
			ISNULL(CONVERT(VARCHAR(40),sa.safe_account_user_guid),''), --UserGuid
			r.next_bill_date 
		FROM #recs r
			INNER JOIN dbo.auto_renewal_message ar
				ON r.auto_renewal_message_id = ar.auto_renewal_message_id
			LEFT JOIN cart_discount cd
				ON ar.cart_discount_id = cd.cart_discount_id
			LEFT JOIN cart_discount_specials_mapping cdsm
				ON ar.cart_discount_id = cdsm.cart_discount_id
			INNER JOIN license_summary ls
				ON ar.license_id = ls.license_id
			INNER JOIN customer c
				ON ar.customer_id = c.customer_id
			INNER JOIN license_category lc
				ON r.license_category_id = lc.license_category_id
			LEFT JOIN @latest_order lo
				ON ar.license_id = lo.license_id
			LEFT JOIN dbo.payment_account pa 
				ON pa.payment_account_id = lo.payment_account_id
			LEFT JOIN dbo.card_type ct
				ON pa.card_type_id = ct.card_type_id
			LEFT JOIN dbo.lu_countries luc
				ON r.location_code = luc.iso3
			LEFT JOIN dbo.license_capability lcap
				ON lcap.license_id = ar.license_id
					AND lcap.capability_id = 2
			LEFT JOIN dbo.safe_account_user_customer sa
				ON sa.customer_id = ar.customer_id

		SELECT campaign,
			keycode,
			net_price renewal_price,
			customer_email Email,
			first_name,
			last_name,
			capability_expiration_date product_expiration_date,
			license_category_description product_name,
			license_category_name,
			renewal_length renewal_length,
			credit_card_type,
			credit_card_last_four,
			credit_card_expiration credit_card_expiration_date,
			language lang,
			location loc,
			URL,
			auto_renewal_message_auto_renewal_type,
			monthly_billing,
			json_call,
			license_key,
			user_guid,
			next_bill_date 
		FROM @return


		UPDATE dbo.auto_renewal_message 
		SET auto_renewal_message_status_id = 1
		WHERE auto_renewal_message_id in (SELECT auto_renewal_message_id FROM #recs)




	END try

	BEGIN catch

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'procedure failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_behavior_insert_license_behavior]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_behavior_insert_license_behavior]

/*     
       DATE                 AUTHOR               REMARKS
       2018-11-08           rvinoche             Initial creation
*/
AS 
	declare @min_row INT = 1,
			@max_row int,
			@license_behavior_id int,
			@relationship_table varchar(100),
			@is_query bit,
			@relationship_column varchar(100),
			@previous_check_value varchar(100),
			@new_check_value VARCHAR(100),
			@previous_license_behavior_check_id int,
			@sql_string nvarchar(max),
			@param_definition nvarchar(500),
			@insert_date DATETIME = GETDATE(),
			@response_code INT, 
			@message varchar(100)

	begin try
            
		declare @behavior_table table (row_id int identity(1,1), license_behavior_id int, relationship_column varchar(100), relationship_table varchar(100), is_query bit, sql_string nvarchar(max))

		insert into @behavior_table (license_behavior_id, relationship_column, relationship_table, is_query, sql_string)
		select lb.license_behavior_id, lbr.relationship_column, lbr.relationship_table, lbr.is_query, lbr.sql_string 
		from dbo.license_behavior lb
		inner join dbo.license_behavior_realationship lbr
			on lbr.license_behavior_id = lb.license_behavior_id
		left join dbo.license_behavior_check lbc
			on lbc.license_behavior_id = lb.license_behavior_id and lbc.processed = 0 -- to ensure there is not already a pending row
		where lb.license_behavior_status_id = 1
			and lbc.license_behavior_check_id is null

		select @max_row = @@rowcount 

		while @min_row <= @max_row
		begin	
			select @license_behavior_id = license_behavior_id,
					@is_query = bt.is_query,
					@relationship_table = bt.relationship_table,
					@relationship_column = bt.relationship_column
			from @behavior_table bt 
			where row_id = @min_row

			if @is_query = 0	
				set @sql_string = N'SELECT @max_value = MAX(' + @relationship_column + ') FROM ' + @relationship_table
			else
				select @sql_string = sql_string from @behavior_table where row_id = @min_row

            
			set @param_definition = N'@max_value varchar(100) OUTPUT'

			execute sp_executesql @sql_string, @param_definition, @new_check_value OUTPUT
            
			--Grab last processed check
			select @previous_license_behavior_check_id = max(license_behavior_check_id)
			from dbo.license_behavior_check
			where license_behavior_id = @license_behavior_id
				and processed = 1

			select @previous_check_value = license_behavior_check_value from dbo.license_behavior_check where license_behavior_check_id = @previous_license_behavior_check_id

			if @new_check_value is not null and @new_check_value > @previous_check_value
			begin
				insert into dbo.license_behavior_check(license_behavior_id, license_behavior_check_value, processed, insert_date)
				select @license_behavior_id, @new_check_value, 0, @insert_date
			end
            
			select @min_row = @min_row + 1, @license_behavior_id = null, @is_query = null, @relationship_table = null, @relationship_column = null, @sql_string = null, @param_definition = null, @new_check_value = null
		end
    end try

	begin catch

			set @response_code = -200
			set @message = case when @message is null then 'failed to insert license_behavior_check_license '+ cast(@license_behavior_id as varchar(20))
											else @message end

			declare @dbname nvarchar(128)
			set @dbname = db_name()
			exec dbo.usp_logerror @errordb = @dbname;
			throw 51001, @message,1;

	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_behavior_update_license_behavior]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_behavior_update_license_behavior]

/*     
       DATE                 AUTHOR               REMARKS
       2018-11-08           rvinoche             Initial creation
	   2019-02-01			rvinoche			 Remove join to license_parent
*/
AS 
	declare @min_row INT = 1,
			@max_row int,
			@license_behavior_id int,
			@relationship_table varchar(100),
			@relationship_column varchar(100),
			@license_column varchar(100),
			@is_query bit,
			@relationship_field varchar(50),
			@previous_check_value varchar(100),
			@new_check_value varchar(100),
			@license_behavior_check_id int,
			@sql_string nvarchar(max),
			@insert_date datetime = getdate(),
			@sequence_number int,
			@license_behavior_class_id int, 
			@response_code int, 
			@message varchar(100),
			@license_category_name varchar(10),
			@category_type_name varchar(20)
		

	begin try

		SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 

		declare @pending_behavior_checks table (row_id int identity(1,1), license_behavior_check_id int, license_behavior_id int, sequence_number INT, new_check_value varchar(100), previous_check_value varchar(100))

		insert into @pending_behavior_checks (license_behavior_check_id, license_behavior_id, sequence_number, new_check_value)
		select license_behavior_check_id,
               lb.license_behavior_id,
			   lbs.sequence_number,
               license_behavior_check_value
		from dbo.license_behavior_check lbc
		inner join dbo.license_behavior lb
			on lb.license_behavior_id = lbc.license_behavior_id
		left join dbo.license_behavior_sequence lbs
			on lbs.license_behavior_id = lb.license_behavior_id
		where processed = 0
		order by lb.license_behavior_class_id, lbs.sequence_number --order by is important because we need the loop to progress according to behavior_class sequence

		select  @max_row = @@rowcount

		while @min_row <= @max_row
		begin
			select @license_behavior_id = lbc.license_behavior_id,
				@license_behavior_check_id = license_behavior_check_id,
				@sequence_number = sequence_number,
				@license_behavior_class_id = lb.license_behavior_class_id,
				@new_check_value = lbc.new_check_value,
				@category_type_name = ct.capability_type_description,
				@license_category_name = lc.license_category_name
			from @pending_behavior_checks lbc
			inner join dbo.license_behavior lb
				on lb.license_behavior_id = lbc.license_behavior_id
			inner join dbo.license_behavior_class c
				on c.license_behavior_class_id = lb.license_behavior_class_id
			inner join dbo.license_category lc
				on lc.license_category_id = c.license_category_id
			inner join dbo.capability_type ct
				on ct.capability_type_id = lb.capability_type_id
			where row_id = @min_row

			select @previous_check_value = max(license_behavior_check_value) 
			from dbo.license_behavior_check
			where license_behavior_id = @license_behavior_id
				and processed = 1
				and license_behavior_check_id < @license_behavior_check_id

			select @relationship_table = relationship_table,
				@relationship_field = sql_string,
				@relationship_column = relationship_column,
				@license_column = license_column
			from dbo.license_behavior_realationship 
			where license_behavior_id = @license_behavior_id

			--review status so they can be used universally (0 = pending)

			set @sql_string = N'SELECT DISTINCT  rt.'+@license_column+', ' + convert(varchar(50),@license_behavior_id) + ' FROM ' + @relationship_table + ' rt ' +
								'CROSS APPLY dbo.fn_license_select_license_profile(rt.'+@license_column+') p ' +
								'INNER JOIN dbo.license l on rt.'+@license_column+' = l.license_id ' +
								'WHERE p.license_category_name = ''' + @license_category_name +
 '''' +
									' AND p.category_type_name = ''' + @category_type_name + '''' +
									' AND l.license_distribution_method_id <> 123' +
									' AND p.license_status_id = 1' +
									' AND p.expiration_date > GETDATE()' +
									' AND rt.' + @relationship_column + ' > ' + @previous_check_value + 
									' AND rt.' + @relationship_column + ' <= ' + @new_check_value 
			
			insert into dbo.license_behavior_check_license (license_id, license_behavior_id)
			exec (@sql_string)

			--set license_behavior_check status to completed
			update dbo.license_behavior_check
			set processed = 1
			where license_behavior_check_id = @license_behavior_check_id

			select @license_behavior_check_id = null, @license_behavior_class_id = null, @license_behavior_id = null, @sequence_number = null,
					@relationship_field= null, @relationship_table = null, @previous_check_value= null, @new_check_value = null, @min_row = @min_row + 1
			
		end

	end try

	begin catch

			set @response_code = -200
			set @message = case when @message is null then 'failed to insert license_behavior_check_license '+ cast(@license_behavior_id as varchar(20))
											else @message end

			declare @dbname nvarchar(128)
			set @dbname = db_name()
			exec dbo.usp_logerror @errordb = @dbname;
			throw 51001, @message,1;

	end catch;








GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_beta_insert_70_beta]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_beta_insert_70_beta]

(
	
	@first_name nvarchar(255),
	@last_name nvarchar(255),
	@email_address varchar(100),
	@keycode varchar(20), 
	@product_id int,
	@bby_employee tinyint
)

/*	
	DATE			AUTHOR		REMARKS
	2009-06-30		esmart		Initial creation
	
	DESCRIPTION
	insert 7.0 beta registration
*/

AS

	set nocount on


	begin try

	declare @log_type int,
			@license_distribution_method_id int, 
			@quantity int,
			@beta_live_date datetime,
			@beta_id int,
			@existing_keycode int,
			@response_code int,
			@message varchar(50),
			@processed int,
			@beta_number int,
			@license_id int

		set @log_type = 1
		
		select @beta_live_date = beta_live_date, @beta_number = beta_number from temp_beta_live_date

		if @keycode = '' 
			begin
			select @keycode = null
			end
		
		select @response_code = 0

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) @product_id
			select @response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then '@product_id (' + convert(varchar(10),@product_id) + ') not valid' else '' end
			from product
			where product_id = @product_id

			if @response_code < 0 	
				begin
					select response_code = @response_code, [message] = @message
					return
				end
		
		-- 1.2) registration (need to make sure that we are not updating the same keycode twice). 

			select @response_code =  case when count(*) > 0 then -120 else 0	 end,
				@message = case when count(*) > 0 then @email_address + ' is already registered' else '' end,
				@beta_id = beta_id
			from beta_70_registration		
			where email_address = @email_address 
			group by beta_id

			if @response_code < 0 	
				begin
					goto select_output
					return
				end

		-- 1.3) keycode validation 
				
		-- 1.3.1) check for valid keycode
		if @keycode is not null and (select count(*) from license where keycode = @keycode) = 0
			begin
			select @keycode = null
			end

		if @keycode is null
		-- 1.3.1) create a new keycode
			begin
				select @license_distribution_method_id = 108,
						@quantity = 1
				
				declare @keycode_table table (keycode varchar(40))

				insert into @keycode_table
				exec usp_license_insert_license_cart @product_id,@license_distribution_method_id,@quantity,@response_code OUTPUT,@message OUTPUT

				select @keycode = keycode from @keycode_table

				select @existing_keycode = 0

			end
		else
			begin

				-- 1.3.2 @keycode
				select @license_id = license_id,
					@response_code =  case when count(*) = 0 then -131 else 0	 end,
					@message = case when count(*) = 0 then @keycode + ' not valid' else '' end
				from license
				where keycode = @keycode
				group by license_id

				if @response_code < 0 	
					begin
						select response_code = @response_code, [message] = @message
						return
					end

				-- 1.3.3 check to see if the keycode has already been registered
				select @response_code =  case when count(*) > 0 then -132 else 0	 end,
					@message = case when count(*) > 0 then @keycode + ' has already been registered' else '' end,
					@beta_id = beta_id
				from beta_70_registration
				where keycode = @keycode
				group by beta_id

				if @response_
code < 0 	
					begin
						goto select_output
						return
					end

				select @existing_keycode = 1

			end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert beta_70_registration
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) determine if should mark registration as processed.
		select @processed = 
				case
					when @beta_number >= 1 and @beta_live_date < getdate() and @existing_keycode = 0 then 1
					when @beta_number = 1 and @beta_live_date < getdate() and @existing_keycode = 1 then 0
					when @beta_number = 2 and @beta_live_date < getdate() and @existing_keycode = 1 then 1
					else 0
				end

		-- 2.2) insert registration
		insert into beta_70_registration (first_name, last_name, email_address, keycode, product_id, processed, bby_employee)
		values (@first_name, @last_name, @email_address, @keycode, @product_id, @processed, @bby_employee)

		select @beta_id = scope_identity()


	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update license
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @existing_keycode = 1 and @processed = 1
			begin
					declare @sql_string varchar(4000),
							@task_number varchar(10),	
							@db_name varchar(100),
							@system_user varchar(50)

					select @system_user = suser_sname(),
							@db_name = db_name()
					
					select @sql_string = 
							'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
							' values(' + convert(varchar(10),@license_id) + ',' + '''' + 'declare @effective_date datetime,@license_id int,@response_code int,@message varchar(100) exec ' + @db_name + 
							'..usp_license_update_license_capability_load ' + convert(varchar(10),@product_id) + ',''''' + @keycode + ''''',1, null, @effective_date OUTPUT,@license_id OUTPUT,@response_code OUTPUT,@message OUTPUT''' +
							',0,getdate()) '
					--print @sql_string

					exec (@sql_string)

					exec tasks..usp_queue_task @license_id

--
--				declare @order_type_group_id int,
--						@effective_date datetime,
--						@license_id int
--
--				set @order_type_group_id = 1
--
--				exec usp_license_update_license_capability_load @product_id,@keycode,@order_type_group_id, null, @effective_date OUTPUT,@license_id OUTPUT,@response_code OUTPUT,@message OUTPUT
			end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) select output
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select_output:
		select @processed = 
				case
					when @beta_number >= 1 and @beta_live_date < getdate() and @existing_keycode = 0 then 1
					when @beta_number = 1 and @beta_live_date < getdate() and @existing_keycode = 1 then 0
					when @beta_number = 2 and @beta_live_date < getdate() and @existing_keycode = 1 then 1
					e
lse 0
				end


		select	response_code = 0, 
				[message] = 'inserted beta reg',
				first_name,
				last_name,
				email_address,
				keycode, 
				product_id,
				beta_type = case
								when processed = 1 then 'Live'
								else 'Registration'
							end
		from beta_70_registration
		where beta_id = @beta_id

	end try

	begin catch
			
			declare @DBName nvarchar(128)
			
			set @DBName = db_name()
			set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
			set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
			set @message = case 
								when @message is null then '7.0 beta insert failed'
								else @message 
							end
			
			exec usp_LogError @log_type, @ErrorDB = @DBName
			
	end catch;








GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_beta_insert_beta_registration]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_beta_insert_beta_registration]

(
	@first_name varchar(32), 
	@last_name varchar(32), 
	@email varchar(64), 
	@operating_system varchar(20), 
	@opt_in tinyint, 
	@language varchar(3), 
	@location varchar(3), 
	@sessionid bigint,
	@new_user char(1), 
	@product_version varchar(5),
	@product_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2006-04-26	esmart			Initial creation


	DESCRIPTION
		insert beta_registration record
*/


AS

begin transaction 

	insert into beta_registration (first_name, last_name, email, operating_system, opt_in, language, location, sessionid, new_user, product_version, product_id)
	values (@first_name, @last_name, @email, @operating_system, @opt_in, @language, @location, @sessionid, @new_user, @product_version, @product_id)

	if @@error > 0
		begin
		rollback transaction
		select @response_code = -100
		select @message = 'General SQL Error - beta_registration insert'
		end
	else
		begin
		select @response_code = 0
		select @message = 'Successful beta_registration insert'
		end

commit transaction




GO
