CREATE PROCEDURE [dbo].[usp_beta_insert_beta_tracking]

(
@product_id int,
@product_version varchar(5),
@keycode char(20),
@sessionid bigint,
@operating_system varchar(20),
@response_code int output,
@message varchar(100) output
)

/*	DATE		AUTHOR		REMARKS
	2006-04-26	esmart		Initial creation
	2007-04-19	esmart		Add operating_system as input parameter


	DESCRIPTION
		insert beta_tracking record
*/

AS

begin transaction

	insert into beta_tracking (product_id, product_version, keycode, sessionid, operating_system)
	values (@product_id, @product_version, @keycode, @sessionid, @operating_system)

	if @@error > 0
		begin
		select @response_code = -100
		select @message = 'General SQL Error - bete_tracking insert'
		rollback transaction
		return
		end
	else
		begin
		select @response_code = 0
		select @message = 'Successful bete_tracking insert'
		end

commit transaction



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_beta_select_70_beta_offer]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_beta_select_70_beta_offer]

(
	@keycode varchar(20)
)

/*	
	DATE			AUTHOR		REMARKS
	2009-06-26		esmart		Initial creation
	
	DESCRIPTION
	select the next product_id for 7.0 beta offer
*/

AS

	set nocount on

	declare @WAV_count float, 
			@WISE_count float, 
			@WISC_count float,
			@WAV_ratio float,
			@WISE_ratio float,
			@WISC_ratio float,
			@keycode_type varchar(10),
			@product_id int

	-- 1) Set ratios and get current counts
	select @WAV_ratio = 0.1,
			@WISE_ratio = 0.2,
			@WISC_ratio = 0.7

	select @WAV_count = count(*) from beta_70_registration where product_id = 67014
	select @WISE_count = count(*) from beta_70_registration where product_id = 67015
	select @WISC_count = count(*) from beta_70_registration where product_id = 67016

	-- 2) get type of keycode
	if @keycode is null or @keycode = ''
		begin
			select @keycode_type = 'NA'
		end
	else
		begin
			select @keycode_type =
					case 
						when count(*) = 1 then 'SS'
						when count(*) = 2 then 'WAV'				
						when count(*) > 2 then 'WISE'
						else 'NA'
					end
			from license l
			inner join license_capability c
				on l.license_id = c.license_id
			where l.keycode = @keycode and c.capability_id in (1,2,3,12) and capability_type_id = 1
		end
		
--select keycode_type = @keycode_type
--
--	select @WAV_count/(@WAV_count+@WISE_count+@WISC_count),
--			@WISE_count/(@WAV_count+@WISE_count+@WISC_count),
--			@WISC_count/(@WAV_count+@WISE_count+@WISC_count)

	-- 3) determine product_id
	if @keycode_type = 'SS' or @keycode_type = 'WAV'
		begin
		if (@WAV_count+@WISE_count+@WISC_count) = 0 
			begin
			select @product_id = 67014
			end
		else
			begin
			select @product_id = 
				case
					when @WAV_count/(@WAV_count+@WISE_count+@WISC_count) < @WAV_ratio then 67014
					when @WISE_count/(@WAV_count+@WISE_count+@WISC_count) < @WISE_ratio then 67015
					else 67016
				end	
			end
		end

	if @keycode_type = 'WISE'
		begin
			if (@WAV_count+@WISE_count+@WISC_count) = 0 
			begin
			select @product_id = 67015
			end
		else
			begin
			select @product_id = 
				case
					when @WISE_count/(@WAV_count+@WISE_count+@WISC_count) < @WISE_ratio then 67015
					else 67016
				end	
			end
		end

	if @keycode_type = 'NA'
		begin
			select @product_id = 67016
		end

	select product_id = @product_id
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_beta_select_product_version_max]
-- =============================================================================







CREATE  PROCEDURE [dbo].[usp_beta_select_product_version_max]

(
	@product_id int,
	@product_version varchar(5),
	@os varchar(20)
)

/*	DATE		AUTHOR		REMARKS
	2006-04-26	esmart		Initial creation
	2006-05-04	tblazek		Add join to beta_participant_max table, return 1 = yes, 0 = no instead of count, rename procedure
					Note:  the procedure will be called for GB and USA only, there will be no limit for Japenese version
	2006-05-16	tblazek		Insert into beta-tracking allows for duplicate keycodes.  Modify count(*) to use distinct on keycode 
	2007-04-13	isprod		Changes for 5.5 beta 
	2007-04-19	esmart		Change beta_registration to beta_tracking


	DESCRIPTION
		count number of beta_tracking record with the product_id, version and OS, compare with participant max and return a 1 or 0 
*/

AS
SET NOCOUNT ON

declare @participant_max_reached int

	If (select count(*)
	    from beta_tracking
		where product_id = @product_id and product_version = @product_version and operating_system=@os)
		 >= (Select participant_max_cnt from beta_participant_max 
			where product_id = @product_id and product_version = @product_version and operating_system=@os)
		BEGIN
			Set  @participant_max_reached = 1
		END
	Else
		BEGIN
			Set @participant_max_reached = 0
		END

select participant_max_reached = @participant_max_reached





GO
