-- =============================================================================

CREATE PROCEDURE [dbo].[usp_billing_select_license_usage_pricing]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2016-01-07	cnovac		Initial creation
	2017-06-07	esmart		Add license_category_id
	2019-05-08	abelenkiy	Added support for license_usage_pricing_value in effective_object
	
	DESCRIPTION
	select license usage pricing used to show on CSI billing tab for now
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select flseot.effective_start_date as start_date
		 , flseot.effective_end_date as end_date
		 , cast(flseot.effective_value as money)/100 as retail_price
		 , oc.currency_id
		 , c.currency_code
		 , flseot.license_category_id
		 , lc.license_category_name
	from dbo.fn_license_select_effective_object_element_history(@license_id, 'license_usage_pricing_value', null) flseot 
		inner join dbo.license_category lc on lc.license_category_id = flseot.license_category_id
		left join dbo.license_effective_object_transaction leot on leot.license_effective_object_transaction_id = flseot.license_effective_object_transaction_id
																	and leot.effective_object_transaction_type_id = 1
		left join dbo.order_item oi on oi.order_item_id = leot.effective_object_transaction_type_value
		left join dbo.order_currency oc on oc.order_header_id = oi.order_header_id
		left join dbo.currency c on c.currency_id = oc.currency_id
	where flseot.effective_object_id = 5
	order by lc.license_category_id, start_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_billing_select_order_license_usage]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_billing_select_order_license_usage]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2016-01-07	cnovac		Initial creation
	2017-06-28	cnovac		Adding more data points to return back to CSI
	2019-04-08	cnovac		Added license_seats to be returned back to CSI
	2022-01-11	psatish		ALM# 3526 Updated Usage_seats to pull the pre/post Cyan overage data
	2023-07-17	jberry		ECOM-1169 Remove license category from the usage_seats calc to handle all capacity products

	DESCRIPTION
	select order license usage used to show on CSI billing tab for now

*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100),
			@m365_license_seats int

	declare @order_license_usage table
	(
	id int identity(1,1) primary key,
	order_license_usage_id int,
    usage_seats int,
	license_seats int,
	retail_price money,
	start_date date,
	end_date date,
	license_category_name varchar(10),
	license_attribute_license_value_description varchar(50),
	oracle_update_status_name varchar(50)
	)
	begin try

		   	insert into @order_license_usage
			(
				order_license_usage_id,
				usage_seats,
				license_seats,
				retail_price,
				start_date,
				end_date,
				license_category_name,
				license_attribute_license_value_description,
				oracle_update_status_name
			)
		   select    
				   usage.order_license_usage_id,
				   usage.usage_seats,
				   usage.license_seats,
				   usage.unit_price ,
				   usage.start_date ,
				   usage.end_date,
				   lc.license_category_name,
				   lalv.license_attribute_license_value_description,
				   ous.oracle_update_status_name
			from order_license_usage usage
			left join license_category lc on lc.license_category_id = usage.license_category_id
			left join license_attribute_license_value lalv on lalv.license_attribute_license_value = usage.license_attribute_license_value
			left join oracle_update_status ous on ous.oracle_update_status_id = usage.oracle_update_status_id
			where usage.license_id = @license_id
			and cast(usage.end_date as date)<'2022-09-30'
			union
            select  
				  usage.order_license_usage_id,
				  case when (usage.usage_seats > usage.license_seats) 
						then  case when upm.usage_pricing_model_name='capacity'
							       then ceiling(cast(usage.usage_seats-usage.license_seats as decimal(18,2))/usage_pricing_storagegb)
								   else usage.usage_seats - usage.license_seats end 
						 else 0 end as usage_seats,
				   usage.license_seats,
				   usage.unit_price,
				   usage.start_date ,
				   usage.end_date,
				   lc.license_category_name,
				   lalv.license_attribute_license_value_description,
				   ous.oracle_update_status_name
			from order_license_usage usage
			left join license_category lc on lc.license_category_id = usage.license_category_id
			left join license_attribute_license_value lalv on lalv.license_attribute_license_value = usage.license_attribute_license_value
			left join oracle_update_status ous on ous.oracle_update_status_id = usage.oracle_update_status_id
			left join dbo.usage_pricing_model upm
			on upm.usage_pricing_model_id = usage.usage_pricing_model_id
			where usage.license_id = @license_id
			and cast(usage.end_date as date)>='2022-09-30'
	

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select usage_seats,
		   license_seat
s,
		   retail_price,
		   start_date,
		   end_date,
		   license_category_name,
		   license_attribute_license_value_description,
		   oracle_update_status_name
	from @order_license_usage
	order by order_license_usage_id desc



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_billing_select_partner_license_changes]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_billing_select_partner_license_changes]


(
		@begin_date datetime, 
		@last_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2018-03-21	esmart		Initial creation.

	DESCRIPTION
*/

AS

set nocount on				

begin try

	declare @response_code int,
			@message varchar(100)

	declare @multiple_partners table (license_id int, partners int)
	declare @min_max table (license_id int, max_start_date datetime, min_end_date datetime)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @multiple_partners
	insert into @multiple_partners (license_id, partners)
	select license_id, partners = count(distinct partner_id)
	from partner_license
	where partner_license_status_id = 2
	group by license_id having count(distinct partner_id) > 1

	-- 1.2) @min_max
	insert into @min_max (license_id, max_start_date, min_end_date)
	select pl.license_id, max_start_date = max(pl.start_date), min_end_date = min(pl.end_date)
	from partner_license pl
	inner join license l
		on l.license_id = pl.license_id
	inner join partner p
		on p.partner_id = pl.partner_id
	inner join @multiple_partners t
		on t.license_id = pl.license_id
	where ((@begin_date <= pl.start_date and pl.start_date < @last_date) or (@begin_date <= pl.end_date and pl.end_date < @last_date) )
		and (datediff(dd,pl.start_date,pl.end_date) > 0 or pl.end_date is null)
	group by pl.license_id

	-- 1.3) return results
	select t.license_id, l.keycode, pl.partner_id, p.partner_name, pl.start_date, pl.end_date, plx.partner_id, px.partner_name, plx.start_date, plx.end_date
	from @min_max t
	inner join license l
		on l.license_id = t.license_id
	inner join partner_license pl
		on pl.license_id = t.license_id and pl.end_date = t.min_end_date and (datediff(dd,pl.start_date,pl.end_date) > 0)
	inner join partner p
		on p.partner_id = pl.partner_id
	inner join partner_license plx
		on plx.license_id = t.license_id and plx.start_date = t.max_start_date and (datediff(dd,plx.start_date,plx.end_date) > 0 or plx.end_date is null)
	inner join partner px
		on px.partner_id = plx.partner_id
	order by t.license_id
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'report failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
