-- =============================================================================
-- PROCEDURE: [dbo].[usp_billing_update_utility_expiration]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_billing_update_utility_expiration]

(
	@days_remaining int, 
	@days int,
	@keycode varchar(40) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2016-11-11		acoffel		Initial creation.
	2017-01-20		esmart		Fix issue with @modified_by persisting in while loop
	2017-02-06		esmart		Extend other billing models for partners, remove updates to trials
	2017-04-20		esmart		Add partner_license enhancements and auto_extend_monthly partner configuration override
	2019-06-12		esmart		New license_service_json schema and other enhancements
	2019-10-01		cnovac		Updated @modified_by datatype length to match what is setting it so data isn't truncated	
	2020-05-28		esmart		Add override_billing_entity
	2021-02-26		esmart		Add M365
	2021-12-08		psatish		Added CEP and added the license_attribute_value to update the Perpetual expiry date	
	2022-01-06		psatish		Evergreen Licenses(Utility/Perpetual) have to extend for 2 years, so the in-parameter for @days_remaining value is 730 i.e. 2 years
	2023-05-08		rambasana	Remove expired modules from automated utility update, section 2.2.3 #ECOM-1183

	DESCRIPTION
	Updates Utility Billing License Expiration
*/

as
set nocount on

begin try

		declare	@extend_date datetime = getdate(),
				@modified_by varchar(500),
				@license_id int, 
				@temp_id int, 
				@total_ids int, 
				@partner_id int,
				@license_service_json nvarchar(max),
				@license_service_type_name varchar(50), 
				@comment nvarchar(max),
				@response_code int,
				@message varchar(100),
				@license_attribute_license_value int
				

		declare @license_table table (license_id int, license_category_name varchar(10),license_seats int,storage_gb int,license_keycode_type_id int,license_attribute_license_value int,start_date datetime,expiration_date datetime,category_type_name varchar(50),item_hierarchy_id tinyint, license_status_id int,min_start_date datetime)
		
		select @license_service_type_name = 'license_update'

		declare @license_service table (license_service_id int)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select records
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			declare @licenses table (row_id int identity(1,1), license_id int, keycode varchar(40), partner_id int,license_attribute_license_value int)

			insert into @licenses(license_id, keycode, partner_id,license_attribute_license_value)
			select distinct l.license_id, l.keycode, pl.partner_id,eo.effective_value
			from license_effective_object eo with (nolock)
			inner join license l with (nolock)
					on l.license_id = eo.license_id
			left join partner_license pl with (nolock)
					on pl.license_id = eo.license_id and pl.partner_license_status_id = 2 and (pl.start_date < @extend_date and (pl.end_date is null or pl.end_date >= @extend_date)) 
			where eo.effective_object_id = 2 and eo.license_category_id in (220,233,234)
				and (eo.effective_start_date <= @extend_date and (eo.effective_end_date is null or eo.effective_end_date > @extend_date))
				and eo.effective_value in (12,110,111,112,210,211,212,13,113,213) and l.license_status_id = 1 and
				l.keycode = case when @keycode is not null then @keycode else l.keycode end
			order by 1 desc
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2
.) set up loop table and process
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			declare @temp_update table (temp_id int identity(1,1), keycode varchar(40), license_id int, partner_id int, days int,license_attribute_license_value int )

			-- 2.1) @temp_update
			insert into @temp_update(keycode, license_id, partner_id, days,license_attribute_license_value)
			select l.keycode, l.license_id, l.partner_id, days = 730 - datediff(dd,getdate(),s.capability_expiration_date),l.license_attribute_license_value
			from @licenses l
			inner join license_capability s with (nolock)
				on s.license_id = l.license_id  and s.capability_type_id = 1
			left join license_parent p
				on l.license_id = p.child_license_id
			left join partner_configuration_partner cp
				on l.partner_id = cp.partner_id and cp.partner_configuration_id = 19 and cp.configuration_value = 'No'
			left join partner_license pl
				on pl.license_id = l.license_id and pl.partner_license_status_id = 1
			where p.license_parent_id is null and pl.partner_license_id is null and s.capability_type_id = 1 and s.capability_expiration_date < dateadd(dd,@days_remaining,getdate()) and s.capability_expiration_date > getdate() and cp.partner_configuration_partner_id is null
				/* NEED TO CHECK THIS SO WE ARE NOT INCORRECTLY EXTENDED SOME KEYCODES (e.g. Ninja setting days remaining < 30) */ 
				and (730 - datediff(dd,getdate(),s.capability_expiration_date)) < 500
			order by s.capability_expiration_date

			-- 2.2) set values - limit to 100 in a batch		
			select @temp_id = 1, @total_ids = max(temp_id) from @temp_update
			select @total_ids = case when @total_ids > 100 then 100 else @total_ids end
			
			-- 2.2) loop through licenses to update
			while @total_ids >= @temp_id
				   begin
						-- 2.2.1) select values
						select @keycode = keycode, @license_id = license_id, @partner_id = partner_id, @days = days,@license_attribute_license_value=license_attribute_license_value
						from @temp_update where temp_id = @temp_id
       
						-- 2.2.2) get partner specific modified_by
						select @modified_by = configuration_value from partner_configuration_partner cp where partner_id = @partner_id and cp.partner_configuration_id = 14

						 if @modified_by is null and @license_attribute_license_value in (13,113,213)
							begin
                            select @modified_by = 'Perpetual_update', @comment = 'Automated Perpetual expiration update'
							END
                          else
							begin
							select @modified_by = 'utility_update', @comment = 'Automated utility expiration update'
							end
                        

						print @keycode
						print @days

						-- 2.2.3) create json
						insert into @license_table (license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id, license_status_id)
						select license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id, license_status_id
						from dbo.fn_license_select_license_profile(@license_id)
						where category_type_name = 'full' and license_status_id = 1
						and (start_date <= @extend_date AND (expiration_date is null or expiration_date > @extend_date)) 

						select @license_service_json = (select ll.keycode, @modified_by as account_name, @comment as comment, 1 as override_billing_entity,
														(select l.license_category_name, expiration_date = convert(date,dateadd(dd,@days,l.expiration_date))
														from @license_table l for json path) license_category 
														from license ll
														where ll.license_id = @license_id
						for json path, without_array_wrapper)

						-- 2.2.4) exec license service
						insert into @license_service(license_service_id)						
						exec usp_license_service_insert_service @license_service_type_name,@license_service_json

						-- 2.2.5) cleanup
						select @keycode = null, @modified_by = null, @license_service_json = null, @license_id = null, @days = null
						delete from @license_table

						select @temp_id = @temp_id + 1
					end


	end try

begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

    set @response_code = -100
	set @message = case when @message is null then 'utility update failed' 
						else @message end
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_brtc_select_next_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_brtc_select_next_update]

(

@sky_update_id INT,
@license_id INT = NULL

)

/*	
	DATE		AUTHOR		REMARKS
	2019-05-29	acoffel		Initial creation.
	2019-08-02	acooffel	make it license_id specific

	DESCRIPTION
	select brtc records to send to san diego
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top 1 s.sky_update_id, s.license_id, l.keycode, c.oem_id, c.device_id, t.sky_update_type_id, t.sky_update_type_name, tp.sky_template_id, tp.sky_template_name
	from sky_update s
	inner join sky_update_type t
		on s.sky_update_type_id = t.sky_update_type_id
	inner join sky_template tp
		on s.sky_template_id = tp.sky_template_id
	INNER JOIN license l
		ON s.license_id = l.license_id
	INNER JOIN cisco_license c
		ON l.license_id = c.license_id
	where s.sky_update_id = @sky_update_id 
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
