-- PROCEDURE: [dbo].[usp_brtc_select_update_license_batch]
-- =============================================================================

CREATE procedure [dbo].[usp_brtc_select_update_license_batch]

/*	
	DATE		AUTHOR		REMARKS
	2019-05-30	acoffel		Initial creation.

	DESCRIPTION
	select batch for bright cloud update
*/

as
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = max(process_date)
	from sky_update u
	inner join sky_update_type t
		on u.sky_update_type_id = t.sky_update_type_id
	where process_date <= getdate() and u.sky_template_id = 8
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select update count failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_api_insert_log]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_api_insert_log]
(
	@partner_id int,
	@partner_account_id int,
	@cart_api_endpoint nvarchar(100) = null,
	@cart_api_request nvarchar(max) = null,
	@http_method varchar(10) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-02-01	rvinoche	Initial creation.


	DESCRIPTION
	Insert cart_api request and response into logs
*/

AS
	set nocount on	

	declare	@cart_api_log_id int,
			@response_code int,
			@message varchar(100)

	begin try
		
		--1) Insert into cart_api_log
			
		insert into dbo.cart_api_log (partner_id, partner_account_id)
		values (@partner_id, @partner_account_id)	

		select @cart_api_log_id = scope_identity()

		--2) Insert request/json if available
		if @cart_api_request is not null
			insert into dbo.cart_api_log_request (cart_api_log_id, cart_api_request, cart_api_endpoint, http_request)
			values (@cart_api_log_id, @cart_api_request, @cart_api_endpoint, @http_method)

		--3) Return cart_api_log_id
		select cart_api_log_id = @cart_api_log_id

	end try
    
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed to insert into cart_api_log with for partner_id ' + convert(varchar(20), @partner_id) + ' and partner_account_id ' + convert(varchar(20), @partner_account_id)
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_api_update_log]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_api_update_log]
(
	@cart_api_log_id int,
	@cart_api_request nvarchar(max) = null,
	@cart_api_endpoint nvarchar(100) = null,
	@http_request varchar(20) = null,
	@cart_api_response_code int = null,
	@cart_api_response nvarchar(max) = null,
	@vendor_order_code varchar(100) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-02-01	rvinoche	Initial creation.


	DESCRIPTION
	Update cart_api request and response into logs
*/

AS
	set nocount on	

	declare	@cart_api_status_id int,
			@modify_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

	begin try

		--1) Update request/json/response if available
		if @cart_api_request is not null
			insert into dbo.cart_api_log_request (cart_api_log_id, cart_api_request, cart_api_endpoint, http_request)
			values (@cart_api_log_id, @cart_api_request, @cart_api_endpoint, @http_request)

		if @cart_api_response_code is not null
			insert into dbo.cart_api_log_response (cart_api_log_id, response_code, cart_api_response)
			values (@cart_api_log_id, @cart_api_response_code, @cart_api_response)

		--2) Update cart_api_log
		if @vendor_order_code is not null
		begin

			update dbo.cart_api_log
			set vendor_order_code = @vendor_order_code, modified_date = @modify_date
			where cart_api_log_id = @cart_api_log_id

		end

	end try
    
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed for cart_api_log_id ' + convert(varchar(20), @cart_api_log_id) 
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_check_payment_request_fraud]
-- =============================================================================

CREATE    PROCEDURE [dbo].[usp_cart_check_payment_request_fraud] (
	@request_json NVARCHAR(MAX) = NULL
	, @args VARCHAR(50) = NULL -- 'debug'
)


/*	
	DATE		AUTHOR		REMARKS
	2024-03-14	gblandford	Created.
							- https://jira.opentext.com/browse/ECOM-3922
	2024-03-22	gblandford	- performance improvements and return result_ok 1 if no initial results found
	2024-05-09	jberry		- change field lengths for first_name, last_name, name, bill_address_1 
								and customer_email to match cart_customer field lengths

	DESCRIPTION
    Procedure used to determine whether a payment_request is potentially a fraudulent attempt.
	Uses recent failed histrocial events to determine whether a bad actor is attempting to spam multiple payment_requests

	The database handles all of the checking now, and the PHP will rely on the 'request_ok' value which is returned as part of the JSON response
	request_ok is an aggregation of the other [datapoint]_ok values, if ANY are 0, then request_ok is returned as 0
 
	@args parameter added for debugging & testing
*/

AS

	SET NOCOUNT ON;

	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; -- we can dirty-read here

	BEGIN TRY

		DECLARE @start_date DATETIME,
			@end_date DATETIME,
			@first_name VARCHAR(255), 
			@last_name VARCHAR(255), 
			@name VARCHAR(515),
			@bill_address_1 VARCHAR(255), 
			@customer_email VARCHAR(255), 
			@user_ip VARCHAR(50), 
			@bill_city VARCHAR(130), 
			@bill_state VARCHAR(50), 
			@bill_postal_code VARCHAR(50), 
			@bill_country VARCHAR(50),
		
			@response NVARCHAR(MAX) = NULL,
			@rows INT


		DECLARE @results TABLE (
			first_name_success INT 
			, first_name_fail INT 
			, last_name_success INT 
			, last_name_fail INT 
			, name_success INT 
			, name_fail INT 
			, address_success INT 
			, address_fail INT 
			, email_success INT 
			, email_fail INT 
			, ip_success INT 
			, ip_fail INT 
		)

		/*
		|
		| Create APP_CONFIG table variable
		|
		*/
		DECLARE @APP_CONFIG TABLE (
			[app_config_name] NVARCHAR(50)
			, [key] NVARCHAR(50)
			, [value] NVARCHAR(MAX)
		);

		/*
		|
		| Load APP_CONFIG values required
		|
		*/
		INSERT INTO @APP_CONFIG	(
			app_config_name,
			[key],
			[value]
		)
		SELECT f.app_config_name
			, f.[key]
			, f.[value]
		FROM [dbo].[fn_app_config_select_key_values] (	NULL, 'WRCART' ) f
		WHERE f.app_config_name IN (
				'PAYMENT-FRAUD-CHECK-THRESHOLD',
				'PAYMENT-FRAUD-CHECK-PERIOD'
			);

		DECLARE 
			@NAME_THRESHOLD INT = 0
			, @ADDRESS_THRESHOLD INT = 0
			, @EMAIL_THRESHOLD INT = 0
			, @IP_THRESHOLD INT = 0
			, @CHECK_PERIOD_MINUTES INT = 0

		SELECT
			@NAME_THRESHOLD = ( CASE
										WHEN cfg.[key] = 'NAME' THEN cfg.value 
										ELSE @NAME_THRESHOLD 
									END ),
			@ADDRESS_THRESHOLD = ( CASE
										WHEN cfg.[key] = 'ADDRESS' THEN cfg.value 
										ELSE @ADDRESS_THRESHOLD 
									END ),
			@EMAIL_THRESHOLD = ( CASE
										WHEN cfg.[key] = 'EMAIL' THEN cfg.value 
										ELSE @EMAIL_THRESHOLD 
									END ),
			@IP_THRESHOLD = ( CASE
									WHEN cfg.[key] = 'IP' THEN cfg.value 
									ELSE @IP_THRESHOLD 
								END ),
			@CHECK_PERIOD_MINUTES = ( CASE
											WHEN cfg.[key] = 'CHECK-PERIOD-MINUTES' THEN 0 - cfg.value 
											ELSE @CHECK_PERIOD_MINUTES 
										END )

		FROM @APP_CONFIG cfg


		IF @args = 'debug' BEGIN
				SELECT
					@NAME_THRESHOLD AS NAME_THRESHOLD
					, @ADDRESS_THRESHOLD AS ADDRESS_THRESHOLD
					, @EMAIL_THRESHOLD AS EMAIL_THRESHOLD
					, @IP_THRESHOLD AS IP_THRESHOLD
					, @CHECK_PERIOD_MINUTES AS CHECK_PERIOD_MINUTES
			END

		/*
		|
		| Extract parameters from JSON request
		|
		*/
		SELECT
			@start_date = 
j.start_date
			, @end_date = j.end_date
			, @first_name = j.first_name
			, @last_name = j.last_name
			, @name = CONCAT( @first_name, '_', @last_name )
			, @bill_address_1 = j.bill_address_1
			, @bill_city = j.bill_city
			, @bill_state = j.bill_state
			, @bill_postal_code = j.bill_postal_code
			, @bill_country = j.bill_country
			, @customer_email = j.customer_email
			, @user_ip = j.user_ip

		FROM OPENJSON( @request_json ) 
		WITH (
				start_date DATETIME '$.start_date',
				end_date DATETIME '$.end_date',
				first_name VARCHAR(255) '$.first_name',
				last_name VARCHAR(255) '$.last_name',
				bill_address_1 VARCHAR(255) '$.bill_address_1',
				bill_city VARCHAR(130) '$.bill_city',
				bill_state VARCHAR(50) '$.bill_state',
				bill_postal_code VARCHAR(50) '$.bill_postal_code',
				bill_country VARCHAR(50) '$.bill_country',
				customer_email VARCHAR(255) '$.customer_email',
				user_ip VARCHAR(50) '$.user_ip'
			) AS j

		IF @args = 'debug' BEGIN
				SELECT
					@start_date AS start_date
					, @end_date AS end_date
					, @first_name AS first_name
					, @last_name AS last_name
					, @name AS name
					, @bill_address_1 AS bill_address_1
					, @bill_city AS bill_city
					, @bill_state AS bill_state
					, @bill_postal_code AS bill_postal_code
					, @bill_country AS bill_country
					, @customer_email AS customer_email
					, @user_ip AS user_ip			
			END

		/*
		|
		| Check parameters
		|
		| If no dates are specified, check requests for the last 24 hours
		|
		*/
		IF @end_date IS NULL BEGIN
				SET @end_date   = GETDATE()
			END

		IF @start_date IS NULL BEGIN
				--SET @start_date = DATEADD(HOUR, -24, @end_date)
				SET @start_date = DATEADD(MINUTE, @CHECK_PERIOD_MINUTES, @end_date) 
			END

		/*
		|
		| Phase 2.
		|
		| Check payment_fraud table, we can look for records with matching data points and circumvent the bext steps, returning a return_ok = 0
		| We will need to determine how we match on data points though as it's unlikely we will match on all, and matching on one could return a
		| false fraud check
		|
		*/
		--DECLARE @payment_fraud_id INT

		--SELECT 
		--	@payment_fraud_id = pf.payment_fraud_id
		--FROM dbo.payment_fraud pf
		--	INNER JOIN dbo.payment_header ph
		--		ON ph.payment_header_id = pf.payment_header_id
		--	INNER JOIN dbo.cart_order co
		--		ON co.cart_order_id = ph.cart_order_id
		--	INNER JOIN dbo.cart_customer cc
		--		ON cc.cart_order_id = co.cart_order_id
		--WHERE (
		--		  (
		--			  cc.first_name = @first_name
		--			  OR cc.last_name = @last_name
		--		  )
		--		  OR (cc.bill_address_1 = @bill_address_1)
		--		  OR cc.customer_email = @customer_email
		--		  OR co.user_ip = @user_ip
		--	  )
		--ORDER BY pf.payment_fraud_id DESC;


		/*
		|
		| Adding an initial selection without aggregation for performance
		| Use a temporary table over a variable to handle a large number of rows returned
		|
		*/
		DROP TABLE IF EXISTS #payment_requests

		CREATE TABLE #payment_requests (
			payment_request_id INT
			, payment_header_id INT
			, insert_date DATETIME
			, payment_action_id INT
			, cart_order_id INT
			, site_id VARCHAR(65)
			, cart_order_status_id INT
			, customer_type_id INT
			, modified_date DATETIME 
			, first_name VARCHAR(255)
			, last_name VARCHAR(255)
			, [name] VARCHAR(515)
			, bill_address_1 VARCHAR(255)
			, customer_email VARCHAR(255)
			, user_ip VARCHAR(50)
		)

		INSERT INTO #payment_requests (
		    payment_request_id,
		    payment_header_id,
		    insert_date,
		    payment_action_id,
		    cart_order_id,
		    site_id,
		    cart_order_status_id,
		    customer_type_id,
		    modified_date,
		    first_name,
		    last_name,
		    name,
		    bill_address_1,
		    customer_email,
		    user_ip
		)
		SELECT
			pr.payment_request_id
			, pr.payment_header_id
			, pr.insert_date
			, pr.payment_action_id
			, ph
.cart_order_id
			, co.site_id
			, co.cart_order_status_id
			, cc.customer_type_id
			, cc.modified_date
			, cc.first_name
			, cc.last_name
			, CONCAT( cc.first_name, '_', cc.last_name ) AS [name]
			, cc.bill_address_1
			, cc.customer_email
			, co.user_ip
		FROM dbo.payment_request AS pr
			INNER JOIN dbo.payment_header AS ph
				ON pr.payment_header_id = ph.payment_header_id
			INNER JOIN dbo.cart_customer cc
				ON ph.cart_order_id = cc.cart_order_id
			INNER JOIN dbo.cart_order co
				ON co.cart_order_id = cc.cart_order_id
		
		WHERE pr.insert_date BETWEEN @start_date AND @end_date
			AND pr.payment_action_id < 3 -- auth
			AND co.site_id = 'WRCART'
			AND cc.customer_type_id = 1 --billing
			AND cc.modified_date BETWEEN @start_date AND @end_date
			AND (
					(
						cc.first_name = @first_name
							OR cc.last_name = @last_name
					)
					OR (
						cc.bill_address_1 = @bill_address_1
					)
					OR cc.customer_email = @customer_email
					OR co.user_ip = @user_ip
				)

		SET @rows  = @@ROWCOUNT;

		IF @args = 'debug' BEGIN
				SELECT * FROM #payment_requests
			END

		/*
		|
		| Check if we have rows
		| If we don't, zero-out a row and skip to the aggregation
		|
		*/

		IF ( @rows = 0 ) BEGIN
				INSERT INTO @results (
				    first_name_success,
				    first_name_fail,
				    last_name_success,
				    last_name_fail,
				    name_success,
				    name_fail,
				    address_success,
				    address_fail,
				    email_success,
				    email_fail,
				    ip_success,
				    ip_fail
				)
				VALUES (  
					0, -- first_name_success - int
				    0, -- first_name_fail - int
				    0, -- last_name_success - int
				    0, -- last_name_fail - int
				    0, -- name_success - int
				    0, -- name_fail - int
				    0, -- address_success - int
				    0, -- address_fail - int
				    0, -- email_success - int
				    0, -- email_fail - int
				    0, -- ip_success - int
				    0 -- ip_fail - int
				)
			END
		ELSE BEGIN
				/*
				|
				| Summarize requests and return results
				|
				*/
				INSERT INTO @results (
					first_name_success,
					first_name_fail,
					last_name_success,
					last_name_fail,
					name_success,
					name_fail,
					address_success,
					address_fail,
					email_success,
					email_fail,
					ip_success,
					ip_fail
				)
				SELECT

					SUM( 
						CASE 
								WHEN t.first_name = @first_name
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS first_name_success
					, SUM( 
						CASE 
								WHEN t.first_name = @first_name
									AND t.cart_order_status_id != 2 THEN 1
								ELSE 0
							END ) AS first_name_fail

					, SUM(
						CASE 
								WHEN t.last_name = @last_name
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS last_name_success
					, SUM(
						CASE 
								WHEN t.last_name = @last_name
									AND t.cart_order_status_id != 2 THEN 1
								ELSE 0
							END ) AS last_name_fail

					, SUM(
						CASE 
								WHEN t.name = @name
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS name_success
					, SUM(
						CASE 
								WHEN t.name = @name
									AND t.cart_order_status_id != 2 THEN 1
									ELSE 0
							END ) AS name_fail

					, SUM(
						CASE
								WHEN t.bill_address_1 = @bill_address_1
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS address_success
					, SUM(
						CASE
								WHEN t.bill_address_1 = @bill_address_1
									AND t.cart_order_status_id != 2 THEN 1
								ELSE 0
							END
					) AS address_fail

					, SUM(
						CASE 
								WHEN t.customer_email = @customer_email
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS email_success
					, SUM(	
						CASE 
								WHEN t.customer_email = @customer_email
									AND t.cart
_order_status_id != 2 THEN 1
								ELSE 0
							END ) AS email_fail

					, SUM(
						CASE
								WHEN t.user_ip = @user_ip
									AND t.cart_order_status_id = 2 THEN 1
								ELSE 0
							END ) AS ip_success
					, SUM( 
						CASE 
								WHEN t.user_ip = @user_ip
									AND t.cart_order_status_id != 2 THEN 1
								ELSE 0
							END ) AS ip_fail
		
				FROM #payment_requests t
				--FROM dbo.payment_request AS pr
				--	INNER JOIN dbo.payment_header AS ph
				--		ON pr.payment_header_id = ph.payment_header_id
				--	INNER JOIN dbo.cart_customer cc
				--		ON ph.cart_order_id = cc.cart_order_id
				--	INNER JOIN dbo.cart_order co
				--		ON co.cart_order_id = cc.cart_order_id
		
				--WHERE pr.insert_date BETWEEN @start_date AND @end_date
				--	AND pr.payment_action_id < 3 -- auth
				--	AND co.site_id = 'WRCART'
				--	AND cc.customer_type_id = 1 --billing
				--	AND cc.modified_date BETWEEN @start_date AND @end_date
				--	AND (
				--			(
				--				cc.first_name = @first_name
				--					OR cc.last_name = @last_name
				--			)
				--			OR (
				--				cc.bill_address_1 = @bill_address_1
				--			)
				--			OR cc.customer_email = @customer_email
				--			OR co.user_ip = @user_ip
				--		)
			END

		--SELECT * FROM @results;

		/*
		|
		| Return results
		|
		*/
		SELECT @response = (

			SELECT
				check_period_minutes = @CHECK_PERIOD_MINUTES,
				start_date = @start_date,
				end_date = @end_date,

				first_name_success = ISNULL(first_name_success, 0),
				first_name_fail = ISNULL(first_name_fail, 0),

				last_name_success = ISNULL(last_name_success, 0),
				last_name_fail = ISNULL(last_name_fail, 0),

				name_success = ISNULL(name_success, 0),
				name_fail = ISNULL(name_fail, 0),
				name_threshold = @NAME_THRESHOLD,
				name_ok = ( CASE 
									WHEN name_success = 0 AND name_fail >= @NAME_THRESHOLD THEN 0
									ELSE 1
								END ),

				address_success = ISNULL(address_success, 0),
				address_fail = ISNULL(address_fail, 0),
				address_threshold = @ADDRESS_THRESHOLD,
				address_ok = ( CASE 
									WHEN address_success = 0 AND address_fail >= @ADDRESS_THRESHOLD THEN 0
									ELSE 1
								END ),

				email_success = ISNULL(email_success, 0),
				email_fail = ISNULL(email_fail, 0),
				email_threshold = @EMAIL_THRESHOLD,
				email_ok = ( CASE 
									WHEN email_success = 0 AND email_fail >= @EMAIL_THRESHOLD THEN 0
									ELSE 1
								END ),
				ip_success = ISNULL(ip_success, 0),
				ip_fail = ISNULL(ip_fail, 0),
				ip_threshold = @IP_THRESHOLD,
				ip_ok = ( CASE 
									WHEN ip_success = 0 AND ip_fail >= @IP_THRESHOLD THEN 0
									ELSE 1
								END ),

				request_ok = ( CASE 
									WHEN ( name_success = 0 AND address_success = 0 AND email_success = 0 AND ip_success = 0 )
											AND
											( name_fail >= @NAME_THRESHOLD OR address_fail >= @ADDRESS_THRESHOLD OR email_fail >= @EMAIL_THRESHOLD OR ip_fail >= @IP_THRESHOLD ) THEN 0
									ELSE 1
								END )


			FROM @results
			
			FOR JSON PATH, WITHOUT_ARRAY_WRAPPER );
	
		SELECT @response AS response;

	END TRY

	BEGIN CATCH

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_delete_cart_discount_item]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_delete_cart_discount_item]

(
		@cart_discount_item_id int	
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) delete cart_discount_item
		
		delete from cart_discount_item_discount
		where cart_discount_item_id = @cart_discount_item_id

		delete from cart_discount_item
		where cart_discount_item_id = @cart_discount_item_id
		 
	

	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_delete_cart_order_item]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cart_delete_cart_order_item]
(
    @vendor_order_code VARCHAR(100),
    @line_item INT
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.
	2018-03-21	esmart		Fix cart_order_item_tax delete
	2020-08-07	esmart		cart_order_item_json
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the cart_order_item_audit
	2022-08-17	gblandford	AIP-33: Also remove WSID product from the cart when WSA product is removed
							to ensure it is not orphaned 
							Optimized by pre-selecting @deleted_items and removing duplicated statements
							Added schema (dbo) on objects
	2023-04-05	psatish		ECOM-899 Modified the section 2.1.1 for storage_gb in the cart_order_item_audit
	2023-07-17	jberry		ECOM-923 Modified section 2 to remove any complementary co-term product if WSA product is removed
	2024-02-24	pachanta	ECOM-1275 Purchase of AIP Add-ons/Family Pack Without WSA Keycode
	2024-06-03	pachanta	ECOM-4713 On Decoupling AllState standalone product candyrack options should display
	2025-01-13  mgolla		US-4220862 Added a condition in the secondary section of step 2 to handle the removal of sub-sub-modules  when either EDR or MDR is removed, provided only one									 of them exists. In scenarios where both EDR and MDR are present, removing just one will not remove the sub-sub-modules.
	DESCRIPTION
	delete item

	DEPENDENCY 

		This Store Procedure is getting executed from PHP using API(https://cartapi.webroot.com/cart/cart-order-items/@line_item) 
		with DELETE method. Previously we have added to remove all AllState Addon's. Now i have removed that check and individually
		we can purchase the Allstate product.
*/

AS
SET NOCOUNT ON
BEGIN TRY

    DECLARE @cart_order_id INT,
            @item_hierarchy_id TINYINT,
            @cart_item_bundle_id TINYINT,
            @audit_date DATETIME,
            @total_amount MONEY = 0,
            @sub_total_amount MONEY = 0,
            @response_code INT,
            @count_items INT = 0,
            @total_items INT = 1,
            @message VARCHAR(100)

    SELECT @audit_date = GETDATE()

    DECLARE @delete_items TABLE
    (
        cart_order_item_id INT,
        license_category_name VARCHAR(10) NULL
    )

    DECLARE @cart_order_items TABLE
    (
        cart_order_item_id INT,
        license_category_name VARCHAR(10),
        cart_order_id INT,
        line_item INT,
        item_hierarchy_id INT,
        cart_item_bundle_id INT
    );

    DECLARE @PILLR_PRIMARY_BUNDLE_LICENSE_CATEGORIES TABLE
    (
        license_category_name VARCHAR(10)
    )
    INSERT INTO @PILLR_PRIMARY_BUNDLE_LICENSE_CATEGORIES
    (
        license_category_name
    )
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('PILLR_PRIMARY_BUNDLE_LICENSE_CATEGORIES', 'PILLR') f

    DECLARE @PILLR_SECONDARY_BUNDLE_LICENSE_CATEGORIES TABLE
    (
        license_category_name VARCHAR(10)
    )
    INSERT INTO @PILLR_SECONDARY_BUNDLE_LICENSE_CATEGORIES
    (
        license_category_name
    )
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('PILLR_SECONDARY_BUNDLE_LICENSE_CATEGORIES', 'PILLR') f
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 1.1) @cart_order_id
    SELECT @cart_order_id = cart_order_id
    FROM dbo.cart_order
    WHERE vendor_order_code = @ven
dor_order_code

    -- 1.2) select
    SELECT @item_hierarchy_id = item_hierarchy_id,
           @cart_item_bundle_id = i.cart_item_bundle_id
    FROM dbo.cart_order_item i
    WHERE i.cart_order_id = @cart_order_id
          AND i.line_item = @line_item

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) delete
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- primary
    IF @item_hierarchy_id = 1
    BEGIN

        INSERT INTO @delete_items
        (
            cart_order_item_id
        )
        SELECT cart_order_item_id
        FROM dbo.cart_order_item
        WHERE cart_order_id = @cart_order_id
              AND cart_item_bundle_id = @cart_item_bundle_id

        /*
			| Add associated allstate add-on product to the list of deleted items
			*/
        INSERT INTO @delete_items
        (
            cart_order_item_id
        )
        SELECT coi.cart_order_item_id
        FROM dbo.cart_order_item coi
            INNER JOIN dbo.product p
                ON p.product_id = coi.product_id
            INNER JOIN dbo.product_license_category plc
                ON plc.product_id = p.product_id
        WHERE coi.cart_order_id = @cart_order_id
              AND coi.cart_item_bundle_id <> @cart_item_bundle_id
              AND @line_item = 1
              AND plc.license_category_id NOT IN ( 137, 138, 139 )
              AND EXISTS
        (
            SELECT DISTINCT
                   culc.license_category_id
            FROM dbo.cart_upsell_license_category culc
                JOIN dbo.cart_upsell cu
                    ON cu.cart_upsell_id = culc.cart_upsell_id
            WHERE cu.cart_upsell_type_id = 9
        );
    END
    -- secondary      
    ELSE
    BEGIN

        INSERT INTO @cart_order_items
        (
            cart_order_item_id,
            license_category_name,
            cart_order_id,
            line_item,
            item_hierarchy_id,
            cart_item_bundle_id
        )
        SELECT coi.cart_order_item_id,
               lc.license_category_name,
               coi.cart_order_id,
               coi.line_item,
               coi.item_hierarchy_id,
               coi.cart_item_bundle_id
        FROM dbo.cart_order_item AS coi
            LEFT JOIN dbo.product AS p
                ON p.product_id = coi.product_id
            LEFT JOIN dbo.product_license_category AS plc
                ON plc.product_id = p.product_id
            LEFT JOIN dbo.license_category AS lc
                ON lc.license_category_id = plc.license_category_id
        WHERE cart_order_id = @cart_order_id

        INSERT INTO @delete_items
        (
            cart_order_item_id,
            license_category_name
        )
        SELECT sdi.cart_order_item_id,
               sdi.license_category_name
        FROM @cart_order_items AS sdi
        WHERE sdi.cart_order_id = @cart_order_id
              AND sdi.line_item = @line_item

       
            IF NOT EXISTS
            (
               SELECT *
			   FROM @cart_order_items AS sdi
			    JOIN @PILLR_PRIMARY_BUNDLE_LICENSE_CATEGORIES AS pemlc ON  pemlc.license_category_name = sdi.license_category_name 
				LEFT JOIN @delete_items AS di ON di.license_category_name <> pemlc.license_category_name				  
				WHERE di.cart_order_item_id IS NOT NULL
            ) 
            BEGIN

                INSERT @delete_items
                (
                    cart_order_item_id,
                    license_category_name
                )
                SELECT cart_order_item_id,
                       psmlc.license_category_name
                FRO
M @cart_order_items AS sdi
                    INNER JOIN @PILLR_SECONDARY_BUNDLE_LICENSE_CATEGORIES AS psmlc
                        ON psmlc.license_category_name = sdi.license_category_name
                WHERE sdi.cart_order_id = @cart_order_id

            END

    END

    -- 2.1) do audits and deletes

    -- 2.1.1) insert cart_order_item_audit
    INSERT INTO dbo.cart_order_item_audit
    (
        cart_order_item_id,
        cart_order_id,
        line_item,
        quantity,
        order_item_offer_amount,
        list_price,
        unit_price,
        tax_item_total,
        product_id,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        cart_item_bundle_id,
        start_date,
        expiration_date,
        vendor_order_item_code,
        order_item_update_type_id,
        license_attribute_license_value,
        item_hierarchy_id,
        audit_date,
        sap_material_number,
        storage_gb
    )
    SELECT i.cart_order_item_id,
           i.cart_order_id,
           i.line_item,
           i.quantity,
           i.order_item_offer_amount,
           i.list_price,
           i.unit_price,
           i.tax_item_total,
           i.product_id,
           i.insert_date,
           i.insert_by,
           i.modified_date,
           i.modified_by,
           i.cart_item_bundle_id,
           i.start_date,
           i.expiration_date,
           i.vendor_order_item_code,
           i.order_item_update_type_id,
           i.license_attribute_license_value,
           i.item_hierarchy_id,
           @audit_date,
           i.sap_material_number,
           i.storage_gb
    FROM dbo.cart_order_item i
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = i.cart_order_item_id

    -- 2.1.2) insert cart_order_item_license_audit
    INSERT INTO dbo.cart_order_item_license_audit
    (
        cart_order_item_license_id,
        cart_order_item_id,
        keycode,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        audit_date
    )
    SELECT coil.cart_order_item_license_id,
           coil.cart_order_item_id,
           coil.keycode,
           coil.insert_date,
           coil.insert_by,
           coil.modified_date,
           coil.modified_by,
           @audit_date
    FROM dbo.cart_order_item_license coil
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = coil.cart_order_item_id

    -- 2.1.3) insert into cart_order_item_tax_audit
    INSERT INTO dbo.cart_order_item_tax_audit
    (
        cart_order_item_tax_id,
        cart_order_item_id,
        tax_total_city_tax,
        tax_total_county_tax,
        tax_total_district_tax,
        tax_total_state_tax,
        tax_total_tax,
        insert_date,
        audit_date
    )
    SELECT t.cart_order_item_tax_id,
           t.cart_order_item_id,
           t.tax_total_city_tax,
           t.tax_total_county_tax,
           t.tax_total_district_tax,
           t.tax_total_state_tax,
           t.tax_total_tax,
           t.insert_date,
           @audit_date
    FROM dbo.cart_order_item_tax t
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = t.cart_order_item_id

    -- 2.1.4) delete cart_order_item_license
    DELETE coil
    FROM dbo.cart_order_item_license coil
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = coil.cart_order_item_id

    -- 2.1.5) delete cart_order_item_tax
    DELETE t
    FROM dbo.cart_order_item_tax t
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = t.cart_order_item_id

    -- 2.1.6) delete cart_order_item_json
    DELETE j
    FROM dbo.cart_order_item_json j
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = j.cart_order_item_id

    -- 2.1.7) delete cart_order_item
    DELETE coi
    FROM dbo
.cart_order_item coi
        INNER JOIN @delete_items d
            ON d.cart_order_item_id = coi.cart_order_item_id


    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) update cart_order
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 3.1) new total
    SELECT @total_amount = x.total_amount,
           @sub_total_amount = x.sub_total_amount
    FROM dbo.cart_order o
        INNER JOIN
        (
            SELECT cart_order_id,
                   total_amount = SUM(i.unit_price * i.quantity),
                   sub_total_amount = SUM(i.unit_price * i.quantity)
            FROM dbo.cart_order_item i
            WHERE i.cart_order_id = @cart_order_id
            GROUP BY i.cart_order_id
        ) x
            ON x.cart_order_id = o.cart_order_id

    -- 3.2) update cart_order
    UPDATE dbo.cart_order
    SET total_amount = @total_amount,
        sub_total_amount = @sub_total_amount
    FROM dbo.cart_order
    WHERE cart_order_id = @cart_order_id

    SELECT @count_items = COUNT(coi.cart_order_item_id)
    FROM dbo.cart_order_item AS coi
    WHERE coi.cart_order_id = @cart_order_id

    IF @count_items = @total_items
    BEGIN
        INSERT INTO dbo.cart_order_item_audit
        (
            cart_order_item_id,
            cart_order_id,
            line_item,
            quantity,
            order_item_offer_amount,
            list_price,
            unit_price,
            tax_item_total,
            product_id,
            insert_date,
            insert_by,
            modified_date,
            modified_by,
            cart_item_bundle_id,
            start_date,
            expiration_date,
            vendor_order_item_code,
            order_item_update_type_id,
            license_attribute_license_value,
            item_hierarchy_id,
            audit_date,
            sap_material_number,
            storage_gb
        )
        SELECT i.cart_order_item_id,
               i.cart_order_id,
               i.line_item,
               i.quantity,
               i.order_item_offer_amount,
               i.list_price,
               i.unit_price,
               i.tax_item_total,
               i.product_id,
               i.insert_date,
               i.insert_by,
               i.modified_date,
               i.modified_by,
               i.cart_item_bundle_id,
               i.start_date,
               i.expiration_date,
               i.vendor_order_item_code,
               i.order_item_update_type_id,
               i.license_attribute_license_value,
               i.item_hierarchy_id,
               @audit_date,
               i.sap_material_number,
               i.storage_gb
        FROM dbo.cart_order_item i
        WHERE i.cart_order_id = @cart_order_id
        UPDATE dbo.cart_order_item
        SET line_item = @total_items
        FROM dbo.cart_order_item AS coi
        WHERE coi.cart_order_id = @cart_order_id
    END

END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'Could not delete item for vendor_order_code: ' + @vendor_order_code
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC dbo.usp_LogError @ErrorDB = @DBName

END CATCH;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_delete_cart_order_item_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_delete_cart_order_item_in_process]

(
	@cart_order_in_process_id int,
	@cart_order_item_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-06	esmart		Initial creation.
	2013-08-20	esmart		Correct bug in cart_order total amount calculation for enterprise
	2014-01-09	esmart		Delete cart_order_message_in_process
	2017-03-22	esmart		Module product support

	DESCRIPTION
	select discount
*/

AS
	set nocount on				
				
	declare	@cart_order_in_process_id_from_item int,
			@cart_item_bundle_id int,
			@product_family_id int,
			@product_type_id int,
			@response_code int,
			@message varchar(100),
			@site_id varchar(20)

	begin try

	select @response_code = 0, @message = 'Success'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @cart_order_in_process_id_from_item = cart_order_in_process_id, 
			@cart_item_bundle_id = cart_item_bundle_id,
			@product_family_id = p.product_family_id,
			@product_type_id = p.product_type_id
	from cart_order_item_in_process i
	inner join product p
		on i.product_id = p.product_id
	where cart_order_item_in_process_id = @cart_order_item_in_process_id

	if @cart_order_in_process_id_from_item <> @cart_order_in_process_id
		begin
		select @response_code = -100, @message = 'cart order does not match cart order from item'
		select response_code = @response_code, message = @message
		return
		end

	select @site_id = site_id
	from cart_order_in_process 
	where cart_order_in_process_id = @cart_order_in_process_id

--	select cart_order_in_process_id = @cart_order_in_process_id, cart_item_bundle_id = @cart_item_bundle_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) delete 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) order item part of bundle
	if @cart_item_bundle_id is not null and @product_family_id <> 8 and @product_type_id <> 4
		begin
			-- 2.1.1) delete cart_order_item_license_in_process
			delete
			from cart_order_item_license_in_process
			where cart_order_item_in_process_id in (select cart_order_item_in_process_id
					from cart_order_item_in_process
					where cart_order_in_process_id = @cart_order_in_process_id and cart_item_bundle_id = @cart_item_bundle_id)

			-- 2.1.2) delete cart_order_item_rebate_in_process
			delete
			from cart_order_item_rebate_in_process
			where cart_order_item_in_process_id in (select cart_order_item_in_process_id
					from cart_order_item_in_process
					where cart_order_in_process_id = @cart_order_in_process_id and cart_item_bundle_id = @cart_item_bundle_id)
	
			-- 2.1.3) delete cart_order_item_in_process
			delete
			from cart_order_item_in_process
			where cart_order_in_process_id = @cart_order_in_process_id and cart_item_bundle_id = @cart_item_bundle_id
		end
	-- 2.2) single line item
	else
		begin
			-- 2.2.1) delete cart_order_item_license_in_process
			delete from cart_order_item_license_in_process
			where cart_order_item_in_process_id = @cart_order_item_in_process_id

			-- 2.2.2) delete cart_order_item_rebate_in_process
			delete from cart_order_item_rebate_in_process
			where cart_order_item_in_process_id
 = @cart_order_item_in_process_id
		
			-- 2.2.3) delete cart_order_item_in_process
			delete from cart_order_item_in_process
			where cart_order_item_in_process_id = @cart_order_item_in_process_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update cart_order_in_process with totals
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @total_amount money, @sub_total_amount money, @offer_amount money

	--if @site_id <> 'WRENTERPRISECART' 
	--	begin
	--		select @total_amount = sum(net_price), @sub_total_amount = sum(net_price), @offer_amount = sum(order_item_offer_amount)
	--		from cart_order_item_in_process
	--		where cart_order_in_process_id = @cart_order_in_process_id 
	--	end
	--else
	--	begin
	--		select @total_amount = sum(quantity*net_price), @sub_total_amount = sum(quantity*net_price), @offer_amount = sum(quantity*order_item_offer_amount)
	--		from cart_order_item_in_process
	--		where cart_order_in_process_id = @cart_order_in_process_id 
	--	end

	-- 3.1) update totals
	select @total_amount = sum(quantity*net_price), @sub_total_amount = sum(quantity*net_price), @offer_amount = sum(quantity*order_item_offer_amount)
	from cart_order_item_in_process
	where cart_order_in_process_id = @cart_order_in_process_id 

	update cart_order_in_process
	set total_amount = isnull(@total_amount,0), sub_total_amount = isnull(@sub_total_amount,0), offer_amount = isnull(@offer_amount,0)
	where cart_order_in_process_id = @cart_order_in_process_id 

	-- 3.2) delete cart_order_message_in_process if message_key is from a bundle cart_discount
	if (select count(*) 
		from cart_order_message_in_process k 
		inner join cart_discount d 
			on k.message_key = d.cart_discount_key 
		where cart_order_in_process_id = @cart_order_in_process_id and d.cart_discount_type_id = 3) > 0 and @cart_item_bundle_id = 1
		begin
			delete from cart_order_message_in_process where cart_order_in_process_id = @cart_order_in_process_id
		end

	select response_code = @response_code, message = @message
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
