-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_fraud_select_account_profile]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_fraud_select_account_profile]


(
	@payment_header_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2014-05-22	esmart		Initial creation.

	DESCRIPTION
	get fraud data from payment_request
*/

AS
	set nocount on				

	declare @max_request_id int, 
			@payment_request_ids int, 
			@unique_account_number int, 
			@unique_expiration int, 
			@unique_card_type int, 
			@unique_cv_number int, 
			@unique_account int, 
			@unique_account_threshold tinyint,
			@user_ip varchar(16),
			@response_code int, 
			@message varchar(100)

	begin try

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) select
	-----------------------------------------------------------------------------------------------------------------------------------------------
		
	-- 1.1) @max_request_id
	select @max_request_id = max(payment_request_id)
	from payment_request 
	where payment_header_id = @payment_header_id and payment_action_id = 1 

	-- 1.2) get values
	select @payment_request_ids = count(payment_request_id),
			@unique_account_number = count(distinct account_number),
			@unique_expiration = count(distinct account_number+'|'+expiration_month+'|'+expiration_year),
			@unique_card_type = count(distinct account_number+'|'+expiration_month+'|'+expiration_year+'|'+card_type_id),
			@unique_cv_number = count(distinct cv_number),
			@unique_account = count(distinct account_number+'|'+expiration_month+'|'+expiration_year+'|'+card_type_id+'|'+cv_number)
	from payment_request
	where payment_request_id <= @max_request_id and payment_header_id = @payment_header_id and payment_action_id = 1 
	group by payment_header_id

	-- 1.1) @ip_address_history_hours
	select @unique_account_threshold = unique_accounts from payment_fraud_threshold

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) update
	-----------------------------------------------------------------------------------------------------------------------------------------------

	select payment_request_ids = @payment_request_ids,
			unique_account_number = @unique_account_number,
			unique_expiration = @unique_expiration,
			unique_card_type = @unique_card_type,
			unique_cv_number = @unique_cv_number,
			unique_account = @unique_account,
			unique_account_threshold = @unique_account_threshold

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_fraud_select_user_ip_account_profile]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_fraud_select_user_ip_account_profile]


(
	@payment_header_id int,
	@start_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-05-22	esmart		Initial creation.

	DESCRIPTION
	get fraud data from payment_request
*/

AS
	set nocount on				

	declare @user_ip varchar(16),
			@row_id int,
			@total_rows int,
			@ip_address_history_hours smallint,
			@response_code int, 
			@message varchar(100)

	begin try

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) update
	-----------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @ip_address_history_hours
	select @ip_address_history_hours = ip_address_history_hours from payment_fraud_threshold

	-- 1.2) start_date
	if @start_date is null
		begin
		select @start_date = dateadd(hh,@ip_address_history_hours,getdate())
		end

	-- 1.3) @user_ip
	select @user_ip = c.user_ip
	from cart_order c
	inner join payment_header h
		on c.cart_order_id = h.cart_order_id
	where h.payment_header_id = @payment_header_id

	-- 1.4) @ip_payment_headers
	declare @ip_payment_headers table (row_id int identity(1,1), payment_header_id int)

	insert into @ip_payment_headers(payment_header_id)
	select h.payment_header_id
	from cart_order c
	inner join payment_header h
		on c.cart_order_id = h.cart_order_id
	where c.user_ip = @user_ip and insert_date > @start_date and c.cart_order_status_id = 2

	-- select * from @ip_payment_headers

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) update @account_profile
	-----------------------------------------------------------------------------------------------------------------------------------------------

	declare @account_profile table (payment_request_ids float, unique_account_number float, unique_expiration float, unique_card_type float, unique_cv_number float, unique_account float, unique_account_threshold tinyint)

	select @total_rows = count(*), @row_id = 1 from @ip_payment_headers

	while @total_rows >= @row_id
		begin
			select @payment_header_id = payment_header_id from @ip_payment_headers where row_id = @row_id

			-- select @payment_header_id

			insert into @account_profile(payment_request_ids,unique_account_number,unique_expiration,unique_card_type,unique_cv_number,unique_account,unique_account_threshold)
			exec usp_cart_fraud_select_account_profile @payment_header_id

			select @row_id = @row_id + 1
		end

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) results
	-----------------------------------------------------------------------------------------------------------------------------------------------

	select payment_header_id = @payment_header_id,
		total_orders = @total_rows,
		payment_request_ids = sum(payment_request_ids),
		average_payment_request_ids = round(sum(payment_request_ids)/@total_rows,2),
		--unique_account_number = sum(unique_account_number),
		--unique_expiration = sum(unique_expiration),
		--unique_card_type = sum(unique_card_type),
		--unique_cv_number = sum(unique_cv_number),
		unique_account = sum(unique_account),
		average_unique_account = round(sum(unique_account)/@total_rows,2),
		unique_account_threshold = max(unique_account_threshold)
	from @account_profile


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_
LogError @ErrorDB = @DBName
		
	end catch;
	


GO
