CREATE PROCEDURE [dbo].[usp_cart_insert_cart_customer]

(
        @customer_in_process_id int,
		@external_customer_key varchar(100),
		@first_name nvarchar(255),
        @last_name nvarchar(255),
        @bill_address_1 nvarchar(255),
        @bill_address_2 nvarchar(255),
        @bill_address_3 nvarchar(255),
        @bill_city nvarchar(130),
        @bill_state char(2),
        @bill_postal_code nvarchar(32),
        @bill_country char(3),
        @ship_address_1 nvarchar(255),
        @ship_address_2 nvarchar(255),
        @ship_address_3 nvarchar(255),
        @ship_city nvarchar(130),
        @ship_state char(2),
        @ship_postal_code nvarchar(32),
        @ship_country char(3),
        @phone_number varchar(64),
        @fax_number varchar(64),
        @company_name nvarchar(255),
        @customer_email nvarchar(255),
        @opt_in bit,
        @insert_by varchar(50),
		@vat_id varchar(20) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2009-02-23		esmart		Initial creation.
	2012-01-18		esmart		Add vat_id

	DESCRIPTION
	
*/

AS
	set nocount on				

	begin try

	declare @cart_customer_id int,
			@modified_by varchar(50),
			@cart_order_status_id tinyint,
			@response_code int,
			@message varchar(100)

	select @modified_by = @insert_by,
			@cart_order_status_id = 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	INSERT INTO cart_customer
           (customer_in_process_id
           ,external_customer_key
           ,first_name
           ,last_name
           ,bill_address_1
           ,bill_address_2
           ,bill_address_3
           ,bill_city
           ,bill_state
           ,bill_postal_code
           ,bill_country
           ,ship_address_1
           ,ship_address_2
           ,ship_address_3
           ,ship_city
           ,ship_state
           ,ship_postal_code
           ,ship_country
           ,phone_number
           ,fax_number
           ,company_name
           ,customer_email
           ,opt_in
           ,insert_by
           ,modified_by
           ,cart_order_status_id
		   ,vat_id)
     VALUES
           (@customer_in_process_id,
		   isnull(@external_customer_key,@customer_in_process_id),
           @first_name,
           @last_name,
           @bill_address_1,
           @bill_address_2,
           @bill_address_3,
           @bill_city,
           @bill_state,
           @bill_postal_code,
           @bill_country,
           @ship_address_1,
           @ship_address_2,
           @ship_address_3,
           @ship_city,
           @ship_state,
           @ship_postal_code,
           @ship_country,
           @phone_number,
           @fax_number,
           @company_name,
           @customer_email,
           @opt_in,
           @insert_by,
           @modified_by,
           @cart_order_status_id,
		   @vat_id)

	select @cart_customer_id  = scope_identity()

	select cart_customer_id = @cart_customer_id

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not load cart_customer for @customer_in_process_id = ' + convert(varchar(20),@customer_in_process_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
