CREATE PROCEDURE [dbo].[usp_cart_insert_cart_customer_in_process]


(
		@cart_in_process_id int,
		@first_name nvarchar(255),
        @last_name nvarchar(255),
        @address1 nvarchar(255),
        @address2 nvarchar(255),
        @city nvarchar(130),
        @state_id char(2),
        @postal_code nvarchar(32),
        @country_id int = null,
        @phone_number varchar(64),
        @company_name nvarchar(255),
        @customer_email nvarchar(255),
        @opt_in bit,
		@iso varchar(2) = null,
		@iso3 varchar(3) = null,
		@vat_id varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2009-02-23	esmart		Initial creation.
	2011-09-15	esmart		Extend input parameters
	2013-07-03	acoffel		extend vat into insert

	DESCRIPTION
	
*/

AS

	set nocount on				

	begin try

	declare @cart_customer_in_process_id int,
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @country_id
	if @country_id is null or @country_id = 0
		begin
		if @iso is not null
			begin
			select @country_id = country_id from lu_countries where iso = @iso
			end
		if @iso3 is not null
			begin
			select @country_id = country_id  from lu_countries where iso3 = @iso3
			end 
		end	
	
	-- 1.2) insert
	insert into cart_customer_in_process (cart_in_process_id,first_name,last_name,address1,address2,city,state_id,postal_code,country_id,phone_number,company_name,customer_email,opt_in,vat_id)
    values(@cart_in_process_id,@first_name,@last_name,@address1,@address2,@city,@state_id,@postal_code,@country_id,@phone_number,@company_name,@customer_email,@opt_in,@vat_id)

	select @cart_customer_in_process_id  = scope_identity()

	end try

	begin catch
		set @response_code = -200
		set @message = case when @message is null then 'Could not insert cart_customer_in_process for @cart_in_process_id = ' + convert(varchar(20),@cart_in_process_id)
						else @message end
		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch
	

GO
