CREATE PROCEDURE [dbo].[usp_cart_insert_cart_discount]

(
		@cart_discount_description varchar(50),
		@cart_discount_type_id tinyint,
		@cart_discount_status_id tinyint, 
		@cart_discount_code varchar(20) = null, 
		@specials_code_list varchar(100) = null,
		@last_modified_by varchar(20),	
		@cart_discount_id int output,
		@response_code int output,
		@message varchar(100) output
		
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-31	esmart		Initial creation.
	2012-12-03	esmart		Add special_code insert

	DESCRIPTION
	
*/

AS
	set nocount on				

	begin try

	select @response_code = 0, @message = 'Item added to discount'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @cart_discount_description
	if (select count(*) from cart_discount where cart_discount_description = @cart_discount_description) > 0
		begin
		select @message = 'Duplicate cart_discount_description', @response_code = -110
		--select message = @message, response_code = @response_code
		return
		end
		
	-- 1.2) @cart_discount_code
	if (select count(*) from cart_discount where cart_discount_code = @cart_discount_code) > 0 and @cart_discount_code <> ''
		begin
		select @message = 'Duplicate cart_discount_code', @response_code = -120
		--select message = @message, response_code = @response_code
		return
		end
			
	-- 1.3) @specials_code_list
	if (select count(*) from cart_discount_specials_mapping m inner join (select char_value from dbo.fn_char_string_to_table(@specials_code_list)) t on m.specials_code = t.char_value) > 0 and @specials_code_list <> ''
		begin
		select @message = 'Duplicate specials_code_list', @response_code = -130
		--select message = @message, response_code = @response_code
		return
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into cart_discount(cart_discount_description, cart_discount_type_id, cart_discount_status_id, cart_discount_code, last_modified_by)
	values(@cart_discount_description, @cart_discount_type_id, @cart_discount_status_id, @cart_discount_code, @last_modified_by)

	select @cart_discount_id = scope_identity()
	
	if @specials_code_list is not null and @specials_code_list <> ''
		begin
		insert into cart_discount_specials_mapping(cart_discount_id,specials_code)
		select @cart_discount_id,string_value from dbo.fn_string_to_table(@specials_code_list)
		end

--	select cart_discount_id = @cart_discount_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
