CREATE PROCEDURE [dbo].[usp_cart_insert_cart_discount_bundle]

(	
	@cart_discount_id int,
	@cart_discount_bundle_description nvarchar(200), 
	@cart_discount_bundle_details_list nvarchar(1000)
)


/*	
	DATE		AUTHOR		REMARKS
	2014-08-04	esmart		Initial creation.

	DESCRIPTION
	select
*/

AS
	set nocount on				

	declare	@cart_discount_bundle_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @cart_discount_bundle_id = cart_discount_bundle_id from cart_discount_bundle where cart_discount_id = @cart_discount_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert
	if @cart_discount_bundle_id is null
		begin
			insert into cart_discount_bundle(cart_discount_id, cart_discount_bundle_description, cart_discount_bundle_details_list)
			values(@cart_discount_id, @cart_discount_bundle_description, @cart_discount_bundle_details_list)
		end
	-- 2.2) update
	else
		begin
		-- 2.2.1) delete
		delete from cart_discount_bundle where cart_discount_bundle_id = @cart_discount_bundle_id

		-- 2.2.2) insert
		insert into cart_discount_bundle(cart_discount_id, cart_discount_bundle_description, cart_discount_bundle_details_list)
		values(@cart_discount_id, @cart_discount_bundle_description, @cart_discount_bundle_details_list)
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
