CREATE PROCEDURE [dbo].[usp_cart_insert_cart_discount_item]

(
		@cart_discount_id int,
		@cart_discount_method_id tinyint, 
		@discount float, 
		@low_range float = null, 
		@high_range float = null,
		@product_type_id int, 
		@product_line_id int, 
		@license_category_id tinyint = null,
		@license_category_name varchar(20) = null, 
		@license_seats int = null, 
		@storage_gb int = null, 
		@years float = null, 
		@last_modified_by varchar(20),
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@license_module_id int = null, 
		@response_code int output,
		@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-31	esmart		Initial creation.
	2013-02-28	esmart		Check for license_category_id = 0
	2014-08-04	esmart		Add cart_discount_item_license_module
	2015-10-27	mrobbins	changed year input to float

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@cart_discount_item_id int,
			@cart_discount_type_id tinyint,
			@item_count tinyint,
			@currency varchar(50),
			@currency_id tinyint
	begin try

	select @response_code = 0, @message = 'Item added to discount'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) currency 
	if @language_code is null
		begin
		select @language_code = 'EN', @location_code = 'USA'
		end 

	select @currency_id = i.currency_id,
			@currency = i.currency_description
	from currency i
	inner join currency_language_location cl
		on i.currency_id = cl.currency_id
	where cl.language_code = @language_code and cl.location_code = @location_code

	-- 1.2) check for existing items
	select @cart_discount_type_id = cart_discount_type_id from cart_discount where cart_discount_id = @cart_discount_id

	if @cart_discount_type_id not in (3,4)
		begin
		if (select count(*) from cart_discount_item where cart_discount_id = @cart_discount_id) > 0
			begin
			select @response_code = -120, @message = 'Only one item allowed on non-tier discount'
			return
			end
		end

	if @license_category_id = 0
		begin
		select @license_category_id = null
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) insert cart_discount
		insert into cart_discount_item(cart_discount_id, cart_discount_method_id, discount, low_range, high_range, product_type_id, product_line_id, license_category_id, license_category_name, license_seats, storage_gb, years, last_modified_by)
		values(@cart_discount_id, @cart_discount_method_id, @discount, @low_range, @high_range, @product_type_id, @product_line_id, @license_category_id, @license_category_name, @license_seats, @storage_gb, @years, @last_modified_by)

		select @cart_discount_item_id = scope_identity()

		if @cart_discount_method_id in (1,2)
			begin
			-- 2.2) insert cart_discount_item_discount
			insert cart_discount_item_discount(cart_discount_item_id, discount, language_code, location_code, currency, currency_id)
			values(@cart_discount_item_id, @discount, @language_code, @location_code, @currency, @currency_id)
			

			-- 2.3) insert other currency discounts	
			--declare @lang_loc table (row_id int identi
ty(1,1), language_code varchar(2), location_code varchar(3))

			--insert into @lang_loc(language_code,location_code)
			--select cl.language_code,cl.location_code
			--from currency i
			--inner join currency_language_location cl
			--	on i.currency_id = cl.currency_id

			--declare @rows int, @row_id int

			--select @rows = count(*), @row_id = 1 
			--from @lang_loc

			--while @rows >= @row_id
			--	begin
			--	select @language_code = language_code, @location_code = location_code from @lang_loc where row_id = @row_id
			--	exec usp_product_update_international_cart_discount @cart_discount_method_id,@language_code,@location_code,@last_modified_by,@cart_discount_id
			--	select @row_id = @row_id + 1
			--	end
		end

		select cart_discount_item_id = @cart_discount_item_id 

	-- 2.2) insert cart_discount_item_license_module
	insert into cart_discount_item_license_module(cart_discount_item_id,license_module_id)
	values(@cart_discount_item_id,@license_module_id)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_cart_discount_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_insert_cart_discount_message]

(
		@cart_discount_message_description varchar(50),
		@message_type_id int,
		@insert_by varchar(20),
		@cart_discount_message_value_xml_str varchar(max) = null,
		@cart_discount_message_id int output
)

/*	
	DATE			AUTHOR		REMARKS
	2010-09-10		esmart		Initial creation
	2011-05-25		esmart		Add in insert of message_values from xml string
	2015-04-20		esmart		Check for duplicate message
	2015-06-30		esmart		Default routing_action to billing
	2018-07-10		esmart		Change to use cart_order_id

	DESCRIPTION
	
*/

AS
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON	

	declare @cart_order_id int,
			@cart_discount_message_value_xml xml,
			@response_code int,
			@message varchar(100)

	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @cart_discount_message_value table (message_value_type_id tinyint, value_id int)

	-- 1.1) parse @license_message_value_xml_str
	select 	@cart_discount_message_value_xml = convert(xml,@cart_discount_message_value_xml_str)

	insert into @cart_discount_message_value(message_value_type_id, value_id)
	select v.message_value_type_id, t.value_id
	from message_value_type v
	inner join (select x.item.value('message_value_type_name[1]', 'varchar(50)') as message_value_type_name,
					x.item.value('value_id[1]', 'int') as value_id
				from @cart_discount_message_value_xml.nodes('/root/license_message_value') x(item)) t
		on v.message_value_type_name = t.message_value_type_name

	-- 1.2) @cart_discount_message_id
	select @cart_order_id = value_id
	from @cart_discount_message_value
	where message_value_type_id = 24

	select @cart_discount_message_id = cart_discount_message_id
	from cart_discount_message_value
	where  message_value_type_id = 24 and value_id = @cart_order_id

	--select cart_order_in_process_id = @cart_order_in_process_id, cart_discount_message_id = @cart_discount_message_id
	--return

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @cart_discount_message_id is null
		begin
		-- 2.0) insert cart_discount_message
			insert into cart_discount_message(cart_discount_message_description, message_type_id, insert_by)
			values(@cart_discount_message_description, @message_type_id, @insert_by)
		
			select @cart_discount_message_id = scope_identity()

		-- 2.1) insert cart_discount_message_value
			insert into cart_discount_message_value(cart_discount_message_id, message_value_type_id, value_id)
			select @cart_discount_message_id, message_value_type_id, value_id 
			from @cart_discount_message_value

		-- 2.2) update cart_order_route_in_process
			update cart_order_route_in_process 
			set routing_action = 'billing'
			where cart_order_in_process_id = @cart_order_id

		end
	else
		begin
		-- 2.3) update cart_discount_message
		update cart_discount_message
		set cart_discount_message_description = @cart_discount_message_descrip
tion
		where cart_discount_message_id = @cart_discount_message_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select cart_discount_message_id, cart_discount_message_description, cart_discount_message_key, message_type_id, insert_date, insert_by
		from cart_discount_message
		where cart_discount_message_id = @cart_discount_message_id
		
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_cart_item_in_process_ext]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_insert_cart_item_in_process_ext]

(
		@cart_item_in_process_id int, 
		@item_xml xml		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-07-08	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on		
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON		

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert rows
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) delete existing rows if they exist
		delete from dbo.cart_item_in_process_ext where cart_item_in_process_id = @cart_item_in_process_id

	-- 1.2) insert new rows
		insert into cart_item_in_process_ext(cart_item_in_process_id, cart_item_in_process_ext_type_id, ext_type_value)
		select cart_item_in_process_id = @cart_item_in_process_id, et.cart_item_in_process_ext_type_id, t.ext_type_value
		from cart_item_in_process_ext_type et with (nolock)
		inner join (select x.item.value('name[1]', 'varchar(20)') as ext_type_name,
						x.item.value('value[1]', 'varchar(20)') as ext_type_value
					from @item_xml.nodes('/root/ext_type') x(item)) t
			on et.ext_type_name = t.ext_type_name

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert cart_item_in_process_ext failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_cart_order]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_cart_insert_cart_order]

(
		@site_id varchar(65),
		@locale char(5),
		@user_ip varchar(16),
		@cart_extension_json nvarchar(max) = null,
		@response_code int output,
		@message varchar(100) output	
)

/*	
	DATE		AUTHOR		REMARKS
	2009-02-23	esmart		Initial creation.
	2011-03-22	esmart		payment header updates
	2011-12-19	esmart		cart technical contact
	2013-04-17	esmart		cart_customer.order_header_id
	2017-07-13	esmart		cart refactor
	2018-03-29	esmart		cart_json insert
	2018-08-29	esmart		correct message_key in json
	2019-12-11	esmart		use partner_configuration to set currency

	DESCRIPTION
	insert cart order
*/

AS
	set nocount on
	
begin try

	declare @cart_order_status_id tinyint,
			@language_code varchar(2),
			@location_code varchar(3),
			@vendor_order_code_prefix varchar(5), 
			@sales_order_date datetime,
			@cart_order_id int,
			@currency_code varchar(3),
			@currency_id tinyint,
			@partner_key varchar(36), 
			@partner_id int,
			@account_user_name varchar(100),
			@partner_account_id int,
			@vendor_order_code varchar(100),
			@routing_action varchar(50),
			@message_campaign_id int,
			@message_campaign_platform varchar(50),
			@message_key varchar(36),
			@license_id int,
			@cart_discount_id int,
			@insert_date datetime
	
	declare @next_id table (invoice_code_int int)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		select @insert_date = getdate()

		-- 1.1) parse @cart_extension_json
		select @sales_order_date = case when sales_order_date = '' then null else sales_order_date end, 
				@currency_code = currency_code, 
				@vendor_order_code = vendor_order_code, 
				@partner_key = partner_key, 
				@account_user_name = account_user_name, 
				@routing_action = routing_action,
				@message_campaign_id = message_campaign_id,
				@message_campaign_platform = message_campaign_platform,
				@message_key = case when message_key = '' then null else message_key end,
				@cart_discount_id = cart_discount_id
		from openjson(@cart_extension_json)
		with (sales_order_date datetime '$.sales_order_date', 
				currency_code varchar(3) '$.currency_code', 
				vendor_order_code varchar(100) '$.vendor_order_code',
				partner_key varchar(36) '$.partner_key',
				account_user_name varchar(100) '$.account_user_name',
				routing_action varchar(36) '$.routing_action',
				message_campaign_id int '$.message_campaign_id',
				message_campaign_platform varchar(50) '$.message_campaign_platform',
				message_key varchar(36) '$.key',
				cart_discount_id int '$.cart_discount_id')
		
		-- 1.2) variables
		if @sales_order_date is null
			begin
			select @sales_order_date = convert(date,getdate())
			end

		-- 1.3) @partner_id
		if @partner_key is not null and @partner_key <> ''
			begin
			select @partner_id = partner_id from partner where partner_key = @partner_key
			end

		-- 1.3) currency		
		
			-- 1.3.1) @currency_code
			if @currency_code is not null
				begin
				select @currency_id = currency_id from currency where currency_code = @currency_code
				end

			-- 1.3.2) partner cusrrency
			if @currency_id is null and @partner_id is not null
				begin 
				select @currency_code = c.currency_code, @currency_id = c.currency_id
				from partner_configuration_partner cp
				inner join currency c
					on cp.configuration
_value = c.currency_code
				where cp.partner_id = @partner_id and cp.partner_configuration_id = 15
				end

			-- 1.3.3) default
			if @currency_id is null
				begin
				select @currency_id = 1
				end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) @vendor_order_code
		if @vendor_order_code is null or @vendor_order_code = ''
			begin
				insert into @next_id(invoice_code_int)
				exec usp_next_id @Type=3

				select @vendor_order_code_prefix = vendor_order_code_prefix from cart_site_id_order_code_prefix where site_id = @site_id
				select @vendor_order_code = @vendor_order_code_prefix + convert(varchar(8),invoice_code_int) from @next_id
			end

		-- 2.2) insert cart_order
		insert into cart_order(vendor_order_code,order_type,site_id,site_url,sales_order_date,submission_date,locale,user_ip,currency_id,insert_date)
		select @vendor_order_code,@site_id,@site_id,@site_id,@sales_order_date,@insert_date,@locale,@user_ip,@currency_id,@insert_date
		
		select @cart_order_id = scope_identity()

		-- 2.3) insert cart_order_partner
		if @partner_id is not null
			begin

			select @partner_account_id = p.partner_account_id
			from partner_account p
			inner join account a
				on p.account_id = a.account_id
			where p.partner_id = @partner_id and a.account_user_name = @account_user_name

			insert into cart_order_partner (cart_order_id, partner_id, partner_account_id)
			select @cart_order_id, @partner_id, @partner_account_id
			end

		-- 2.4) @routing_action
		if @routing_action is not null and @routing_action <> ''
			begin
			insert into cart_order_route (cart_order_id, routing_action, insert_date)
			select @cart_order_id, @routing_action, @insert_date
			end

		-- 2.5) cart_order_message
		if @message_key is not null
			begin 
			select @license_id = license_id
			from license_key
			where license_key = @message_key

			insert into cart_order_message (cart_order_id, message_key, message_campaign_id, message_campaign_platform, cart_discount_id, license_id)
			select @cart_order_id, @message_key, @message_campaign_id, @message_campaign_platform, @cart_discount_id, @license_id
			end

		-- 2.6) cart_json
		if @cart_extension_json is not null
			begin
				insert into cart_json (cart_json, cart_order_id)
				values(@cart_extension_json, @cart_order_id)
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select @response_code = 0, @message = 'Success'

		select cart_order_id, vendor_order_code,site_id,offer_amount,total_amount,sub_total_amount,tax_amount,sales_order_date,locale,insert_date,insert_by,modified_date,modified_by,cart_order_status_id,currency_id,user_ip
		from cart_order
		where cart_order_id = @cart_order_id

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert cart_order failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_cart_order_extension]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_insert_cart_order_extension]


(
		@vendor_order_code varchar(100),
		@order_extension_json nvarchar(max)

)

/*	
	DATE		AUTHOR		REMARKS
	2018-09-05	esmart		Initial creation.
	2019-11-04	esmart		Fix bug with null order_extension_value

	DESCRIPTION
	Insert cart_order_extension
*/

AS
	set nocount on
	set ansi_warnings off
					
begin try

	declare @cart_order_id int,
			@response_code int,
			@message varchar(100)


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @cart_order_id
	select @cart_order_id = co.cart_order_id
	from cart_order co
	where co.vendor_order_code = @vendor_order_code

	-- 1.2) @cart_order_extension
	declare @cart_order_extension table (order_extension_type_name varchar(50), order_extension_value varchar(50))

	insert into @cart_order_extension (order_extension_type_name, order_extension_value)
	select order_extension_type_name = convert(varchar(50),[key]), order_extension_value = convert(varchar(50),[Value])
	from openjson(@order_extension_json)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) update
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) delete
	delete c
	from cart_order_extension c
	inner join order_extension_type t
		on t.order_extension_type_id = c.order_extension_type_id
	left join @cart_order_extension ce
		on ce.order_extension_type_name = t.order_extension_type_name 
	where c.cart_order_id = @cart_order_id

	-- 2.2) insert
	insert into cart_order_extension (cart_order_id, order_extension_type_id, order_extension_value)
	select @cart_order_id, t.order_extension_type_id, ce.order_extension_value
	from @cart_order_extension ce
	inner join order_extension_type t
		on t.order_extension_type_name = ce.order_extension_type_name
	left join cart_order_extension c
		on c.order_extension_type_id = t.order_extension_type_id and c.cart_order_id = @cart_order_id
	where ce.order_extension_value is not null and c.cart_order_extension_id is null

	-- 2.3) update
	update c 
	set c.order_extension_value = ce.order_extension_value
	from @cart_order_extension ce
	inner join order_extension_type t
		on t.order_extension_type_name = ce.order_extension_type_name
	inner join cart_order_extension c
		on c.order_extension_type_id = t.order_extension_type_id and c.cart_order_id = @cart_order_id
	where ce.order_extension_value is not null and ce.order_extension_value <> c.order_extension_value

			
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'cart_order_extension insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_cart_order_from_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_insert_cart_order_from_in_process]

(
	@cart_order_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-01	esmart		Initial creation.
	2012-10-31	esmart		cart_order_item_tax
	2013-01-14	esmart		cart_order_partner
	2013-03-12	esmart		customer_type_id
	2013-05-15	esmart		cart_technical_contact
	2013-07-03	acoffel		extended vat_id into cart_customer insert
	2014-05-22	esmart		Add cart_order.user_ip
	2014-12-31	acoffel		Add subscription check to block any S2 keys from cart_order
	2015-04-15	esmart		Update @sales_order_date to be current datetime
	2016-08-02	blu			Update cart_json with cart_order_id.
	2016-11-21	esmart		Add start_date and expiration_date

	DESCRIPTION
	insert cart order from in process
*/

AS
	set nocount on				

	declare	@cart_order_id int,	
			@cart_customer_id int,
			@site_id varchar(20),
			@sales_order_date datetime,
			@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @sales_order_date
	select @sales_order_date = getdate()

	-- 1.1) verify order is not already loaded
	select @cart_order_id = cart_order_id
	from cart_order
	where cart_order_in_process_id = @cart_order_in_process_id
	
	-- 1.2) select @site_id
	select @site_id = site_id
	from cart_order_in_process
	where cart_order_in_process_id = @cart_order_in_process_id

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update cart_order
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @cart_order_id is not null
	-- 2.1) update 
		begin
		--print 'update'

		-- 2.1.2) cart_order
		update cart_order
		set order_type = o.order_type, 
			site_id = o.site_id,
			site_url = o.site_url, 
			p_rc = o.p_rc, 
			p_rsc = o.p_rsc, 
			p_ac = o.p_ac, 
			trx_rc = o.trx_rc, 
			trx_rsc = o.trx_rsc, 
			trx_ac = o.trx_ac, 
			total_amount = o.total_amount, 
			sub_total_amount = o.sub_total_amount, 
			offer_amount = o.offer_amount, 
			tax_amount = o.tax_amount, 
			session_id = o.session_id, 
			submission_date = o.submission_date, 
			sales_order_date = @sales_order_date, 
			locale = o.locale, 
			currency_id = o.currency_id,
			user_ip = o.user_ip,
			restriction = o.restriction
		from cart_order c
		inner join cart_order_in_process o
			on c.cart_order_in_process_id = o.cart_order_in_process_id
		where c.cart_order_id = @cart_order_id
	
		-- 2.1.1)cart_customer
		delete from cart_customer
		where cart_order_id = @cart_order_id
		
		insert into cart_customer(customer_in_process_id, first_name, last_name, company_name, bill_address_1, bill_address_2, bill_city, bill_state, bill_postal_code, bill_country, phone_number, customer_email, opt_in, vat_id, customer_type_id, cart_order_id, external_customer_key)
		select cart_order_in_process_id, first_name, last_name, company_name, address_1, address_2, city, state, postal_code, iso3, phone_number, customer_email, opt_in, vat_id, customer_type_id, @cart_order_id, external_customer_key
		from cart_order_customer_in_process 
p
		left join lu_countries c
			on p.country_id = c.country_id
		where cart_order_in_process_id = @cart_order_in_process_id

		select @cart_customer_id = cart_customer_id from cart_customer where cart_order_id = @cart_order_id and customer_type_id = 1

		if @cart_customer_id is not null
			begin
			update cart_order set cart_customer_id = @cart_customer_id where cart_order_id = @cart_order_id 
			end

		-- 2.1.3) cart_order_item and cart_order_item_license
		
			-- 2.1.3.1) delete records
			delete from cart_order_item_license
			where cart_order_item_id in (select cart_order_item_id from cart_order_item	where cart_order_id = @cart_order_id)

			delete from cart_order_item_rebate
			where cart_order_item_id in (select cart_order_item_id from cart_order_item	where cart_order_id = @cart_order_id)

			delete from cart_order_item_tax
			where cart_order_item_id in (select cart_order_item_id from cart_order_item	where cart_order_id = @cart_order_id)

			delete from cart_order_item
			where cart_order_id = @cart_order_id
	
			-- 2.1.3.2) insert new items
			insert into cart_order_item(cart_order_id, cart_order_item_in_process_id, invoice_item_in_process_id, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, list_price, unit_price, tax_item_total, tax_exempt, product_id, product_locale, cart_item_bundle_id, order_item_update_type_id,license_attribute_license_value,start_date,expiration_date)
			select @cart_order_id, cart_order_item_in_process_id, invoice_item_in_process_id = 0, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, retail_price, net_price, tax_item_total, tax_exempt, product_id, product_locale, cart_item_bundle_id, order_item_update_type_id, i.license_attribute_license_value, i.start_date, i.expiration_date
			from cart_order_item_in_process i
			where i.cart_order_in_process_id = @cart_order_in_process_id


			insert into cart_order_item_license(cart_order_item_id, keycode)
			select oi.cart_order_item_id, il.keycode
			from cart_order_item_license_in_process il
			inner join cart_order_item_in_process i
				on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
			inner join cart_order_item oi
				on i.cart_order_item_in_process_id = oi.cart_order_item_in_process_id
			inner join license l
				on il.keycode = l.keycode
			where i.cart_order_in_process_id = @cart_order_in_process_id
			--and not exists (select * from subscription s where l.license_id = s.license_id)

	
			insert into cart_order_item_rebate(cart_order_item_id, rebate_id)
			select oi.cart_order_item_id, ir.rebate_id
			from cart_order_item_rebate_in_process ir
			inner join cart_order_item_in_process i
				on i.cart_order_item_in_process_id = ir.cart_order_item_in_process_id
			inner join cart_order_item oi
				on i.cart_order_item_in_process_id = oi.cart_order_item_in_process_id
			where cart_order_in_process_id = @cart_order_in_process_id

		-- 2.1.5) cart_shipping
			delete 
			from cart_shipping
			where cart_order_id = @cart_order_id
	
			insert into cart_shipping(cart_order_id, company_name, first_name, last_name, address_1, address_2, city, state, postal_code, country_id, last_modified)
			select @cart_order_id, company_name, first_name, last_name, address_1, address_2, city, state, postal_code, country_id, last_modified
			from cart_order_shipping_in_process
			where cart_order_in_process_id = @cart_order_in_process_id


		-- 2.1.6) cart_order_message
			delete 
			from cart_order_message
			where cart_order_id = @cart_order_id

			insert into cart_order_message(cart_order_id, message_key, license_id, cart_discount_id, status_id)
			select @cart_order_id, message_key, license_id, cart_discount_id, status_id
			from cart_order_message_in_process
			where cart_order_in_process_id = @cart_order_in_process_id

		-- 2.1.7) cart_order_partner
			delete 
			from car
t_order_partner
			where cart_order_id = @cart_order_id

			insert into cart_order_partner(cart_order_id,partner_id,partner_account_id)
			select @cart_order_id, partner_id, partner_account_id
			from cart_order_partner_in_process
			where cart_order_in_process_id = @cart_order_in_process_id

		-- 2.1.8) cart_technical_contact_in_process
			delete 
			from cart_technical_contact
			where cart_order_id = @cart_order_id

			insert into cart_technical_contact(cart_order_id, cart_in_process_id, first_name, last_name, customer_email, phone_number)
			select @cart_order_id, cart_order_in_process_id, first_name, last_name, customer_email, phone_number
			from cart_order_technical_contact_in_process
			where cart_order_in_process_id = @cart_order_in_process_id
			
		end
	-- 2.2 insert
	else
		begin

--		select cart_customer_id = @cart_customer_id

		-- 2.2.2) cart_order
		declare @next_id table (invoice_code_int int)
		declare @vendor_order_code_prefix varchar(5), @vendor_order_code varchar(100)

		insert into @next_id(invoice_code_int)
		exec usp_next_id @Type=3

		select @vendor_order_code_prefix = vendor_order_code_prefix 
		from cart_site_id_order_code_prefix 
		where site_id = @site_id

		select @vendor_order_code = @vendor_order_code_prefix + convert(varchar(8),invoice_code_int) from @next_id

		insert into cart_order(cart_customer_id, cart_order_in_process_id, vendor_order_code, order_type, site_id, site_url, p_rc, p_rsc, p_ac, trx_rc, trx_rsc, trx_ac, total_amount, sub_total_amount, offer_amount, tax_amount, session_id, submission_date, sales_order_date, locale, currency_id, invoice_in_process_id, payment_method, user_ip, restriction)
		select cart_customer_id = 0, cart_order_in_process_id, @vendor_order_code, order_type, site_id, site_url, p_rc, p_rsc, p_ac, trx_rc, trx_rsc, trx_ac, total_amount, sub_total_amount, offer_amount, tax_amount, session_id, submission_date, @sales_order_date, locale, currency_id, invoice_in_process_id = 0, payment_method = 0, user_ip, restriction
		from cart_order_in_process
		where cart_order_in_process_id = @cart_order_in_process_id
	
		select @cart_order_id = scope_identity()
				
		--select path = 'insert'
		-- 2.2.1)cart_customer
		insert into cart_customer(customer_in_process_id, first_name, last_name, company_name, bill_address_1, bill_address_2, bill_city, bill_state, bill_postal_code, bill_country, phone_number, customer_email, opt_in, vat_id, customer_type_id, cart_order_id, external_customer_key)
		select cart_order_in_process_id, first_name, last_name, company_name, address_1, address_2, city, state, postal_code, iso3, phone_number, customer_email, opt_in, vat_id, customer_type_id, @cart_order_id, external_customer_key
		from cart_order_customer_in_process p
		left join lu_countries c
			on p.country_id = c.country_id
		where cart_order_in_process_id = @cart_order_in_process_id

		select @cart_customer_id = cart_customer_id from cart_customer where cart_order_id = @cart_order_id and customer_type_id = 1

		if @cart_customer_id is not null
			begin
			update cart_order set cart_customer_id = @cart_customer_id where cart_order_id = @cart_order_id 
			end

--		select cart_order_id = @cart_order_id
	
		-- 2.2.3) cart_order_item
		insert into cart_order_item(cart_order_id, cart_order_item_in_process_id, invoice_item_in_process_id, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, list_price, unit_price, tax_item_total, tax_exempt, product_id, product_locale, cart_item_bundle_id, order_item_update_type_id, license_attribute_license_value,start_date,expiration_date)
		select @cart_order_id, cart_order_item_in_process_id, invoice_item_in_process_id = 0, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, retail_price, net_price, tax_item_total, tax_exempt, product_id, product_locale, cart_item_bundle_id, order_item_update_type_id, licen
se_attribute_license_value,start_date,expiration_date
		from cart_order_item_in_process
		where cart_order_in_process_id = @cart_order_in_process_id

		
		-- 2.2.4) cart_order_item_license
		insert into cart_order_item_license(cart_order_item_id, keycode)
		select oi.cart_order_item_id, il.keycode
		from cart_order_item_license_in_process il
		inner join cart_order_item_in_process i
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		inner join cart_order_item oi
			on i.cart_order_item_in_process_id = oi.cart_order_item_in_process_id
		inner join license l
			on il.keycode = l.keycode
		where i.cart_order_in_process_id = @cart_order_in_process_id
		and not exists (select * from subscription s where l.license_id = s.license_id)

		-- 2.2.5) cart_order_item_rebate
		insert into cart_order_item_rebate(cart_order_item_id, rebate_id)
		select oi.cart_order_item_id, ir.rebate_id
		from cart_order_item_rebate_in_process ir
		inner join cart_order_item_in_process i
			on i.cart_order_item_in_process_id = ir.cart_order_item_in_process_id
		inner join cart_order_item oi
			on i.cart_order_item_in_process_id = oi.cart_order_item_in_process_id
		where cart_order_in_process_id = @cart_order_in_process_id
				
		-- 2.2.6) cart_shipping
		insert into cart_shipping(cart_order_id, company_name, first_name, last_name, address_1, address_2, city, state, postal_code, country_id, last_modified)
		select @cart_order_id, company_name, first_name, last_name, address_1, address_2, city, state, postal_code, country_id, last_modified
		from cart_order_shipping_in_process
		where cart_order_in_process_id = @cart_order_in_process_id
		
		-- 2.2.7) cart_order_message
		insert into cart_order_message(cart_order_id, message_key, license_id, cart_discount_id, status_id)
		select @cart_order_id, message_key, license_id, cart_discount_id, status_id
		from cart_order_message_in_process
		where cart_order_in_process_id = @cart_order_in_process_id
		
		insert into cart_message(cart_order_id,message_key)
		select @cart_order_id, message_key
		from cart_order_message_in_process
		where cart_order_in_process_id = @cart_order_in_process_id
		
		-- 2.2.8) cart_order_partner
		insert into cart_order_partner(cart_order_id,partner_id,partner_account_id)
		select @cart_order_id, partner_id, partner_account_id
		from cart_order_partner_in_process
		where cart_order_in_process_id = @cart_order_in_process_id

		-- 2.2.9) cart_technical_contact_in_process
		insert into cart_technical_contact(cart_order_id, cart_in_process_id, first_name, last_name, customer_email, phone_number)
		select @cart_order_id, cart_order_in_process_id, first_name, last_name, customer_email, phone_number
		from cart_order_technical_contact_in_process
		where cart_order_in_process_id = @cart_order_in_process_id

		end

	-- 2.3) update cart_order_item start and expiration dates
	update i
	set i.start_date = case
							when p.product_type_id = 1 then convert(date,getdate())
							when p.product_type_id = 2 and cl.end_date > getdate() then cl.end_date
							when p.product_type_id = 2 and cl.end_date <= getdate() then convert(date,getdate())
							when p.product_type_id = 3 then convert(date,getdate())
						end,
		i.expiration_date = case
								when  p.product_type_id = 1 then dateadd(dd,c.capability_activation_days,convert(date,getdate()))
								when  p.product_type_id = 2 and cl.end_date > getdate() then dateadd(dd,c.capability_activation_days,cl.end_date)
								when  p.product_type_id = 2 and cl.end_date <= getdate() then dateadd(dd,c.capability_activation_days,convert(date,getdate()))
								when p.product_type_id = 3 then cl.end_date
							end
	from cart_order_item i
	inner join product p
		on p.product_id = i.product_id
	inner join cart_order_item_license il
		on il.cart_order_item_id = i.cart_order_item_id
	inner join license l
		on l.keycode = il.keycode
	inner join license_category_l
icense cl
		on cl.license_id = l.license_id
	inner join product_capability c
		on c.product_id = i.product_id and c.capability_id = 2
	where i.cart_order_id = @cart_order_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert payment_header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @payment_merchant_id tinyint, @payment_status_id tinyint, @payment_header_id int
	
	select @payment_status_id = 1 -- pending

	-- 3.1) get payment_merchant_id
	select @payment_merchant_id = payment_merchant_id
	from payment_merchant m
	inner join cart_order_in_process p
		on m.merchant_id = p.merchant_id
	where p.cart_order_in_process_id = @cart_order_in_process_id
	
	if @payment_merchant_id is null
		begin
		select @payment_merchant_id = 1
		end

	-- 3.2) insert payment_header
	if (select count(*) from payment_header where cart_order_id = @cart_order_id) = 0
		begin
		insert into payment_header(cart_order_id, payment_merchant_id, payment_status_id)
		values(@cart_order_id, @payment_merchant_id, @payment_status_id)
		end

	-- 4.0) cart_json
	update cart_json
	set cart_order_id = @cart_order_id
	where cart_order_in_process_id = @cart_order_in_process_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select c.cart_order_id, c.vendor_order_code
		from cart_order c
		where c.cart_order_id = @cart_order_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
