-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_insert_cart_order_item]
(
    @vendor_order_code VARCHAR(100),
    @item_json NVARCHAR(MAX),
    @bundle_json NVARCHAR(MAX),
    @response_code INT OUTPUT,
    @message VARCHAR(500) OUTPUT
)

/*
