CREATE PROCEDURE [dbo].[usp_cart_insert_cart_technical_contact_in_process]

(
	@cart_in_process_id int, 
	@first_name nvarchar(255), 
	@last_name nvarchar(255), 
	@customer_email varchar(100), 
	@phone_number varchar(64),
	@active tinyint = NULL
	
)

/*	
	DATE		AUTHOR		REMARKS
	2011-12-19	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@cart_technical_contact_in_process_id int,
			@response_code int,
			@message varchar(100)

	begin try

	if @first_name = '' begin select @first_name = null end
	if @last_name = ''  begin select @last_name = null end
	if @customer_email = ''  begin select @customer_email = null end
	if @phone_number = ''  begin select @phone_number = null end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select cart_technical_contact_in_process_id
		select @cart_technical_contact_in_process_id = cart_technical_contact_in_process_id
		from cart_technical_contact_in_process
		where cart_in_process_id = @cart_in_process_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update/insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @cart_technical_contact_in_process_id is null and @first_name is not null and @last_name is not null and @customer_email is not null and @phone_number is not null 	
	-- 2.1) insert cart_discount
		begin
			insert into cart_technical_contact_in_process(cart_in_process_id, first_name, last_name, customer_email, phone_number, active)
			values(@cart_in_process_id, @first_name, @last_name, @customer_email, @phone_number, @active)
		end	
	-- 2.2) update cart_discount
		begin
			if @first_name is null and @last_name is null and @customer_email is null and @phone_number is null 
			-- 2.2.1) delete
				begin
					delete from cart_technical_contact_in_process where cart_technical_contact_in_process_id = @cart_technical_contact_in_process_id
				end
			else
			-- 2.2.2) update
				begin
					update cart_technical_contact_in_process
					set first_name = @first_name, last_name = @last_name, customer_email = @customer_email, phone_number = @phone_number, active = @active
					where cart_technical_contact_in_process_id = @cart_technical_contact_in_process_id
				end
		end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
