CREATE PROCEDURE [dbo].[usp_cart_insert_cart_upsell]

(		
	@cart_upsell_type_id tinyint, 
	@cart_upsell_description varchar(200),
	@product_type_list varchar(100),
	@product_line_list varchar(100),
	@license_category_list varchar(100),
	@seat_list varchar(100),
	@storage_list varchar(100),
	@years_list varchar(100),
	@sector_list varchar(100),
	@cart_upsell_template_id tinyint,
	@cart_discount_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-31	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@cart_upsell_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) insert cart_upsell
	insert into cart_upsell(cart_upsell_type_id, cart_upsell_description)
	values(@cart_upsell_type_id, @cart_upsell_description)

	select @cart_upsell_id = scope_identity()
	
	-- 1.2) insert cart_upsell_product_type
	delete from cart_upsell_product_type where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_product_type(cart_upsell_id, product_type_id)
	select @cart_upsell_id, product_type_id = integer_value
	from dbo.fn_integer_string_to_table(@product_type_list)
	
	-- 1.2) insert cart_upsell_product_line
	delete from cart_upsell_product_line where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_product_line(cart_upsell_id, product_line_id)
	select @cart_upsell_id, product_line_id = integer_value
	from dbo.fn_integer_string_to_table(@product_line_list)

	-- 1.3) insert cart_upsell_license_category
	delete from cart_upsell_license_category where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_license_category(cart_upsell_id, license_category_id)
	select @cart_upsell_id, license_category_id
	from license_category 
	where license_category_id in (select integer_value from dbo.fn_integer_string_to_table(@license_category_list))

	-- 1.4) insert cart_upsell_seat
	delete from cart_upsell_seat where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_seat(cart_upsell_id, seats)
	select @cart_upsell_id, seats = integer_value
	from dbo.fn_integer_string_to_table(@seat_list)

	-- 1.5) insert cart_upsell_storage
	delete from cart_upsell_storage where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_storage(cart_upsell_id, storage_gb)
	select @cart_upsell_id, storage_gb = integer_value
	from dbo.fn_integer_string_to_table(@storage_list)

	-- 1.6) insert cart_upsell_years
	delete from cart_upsell_years where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_years(cart_upsell_id, years)
	select @cart_upsell_id, years = integer_value
	from dbo.fn_integer_string_to_table(@years_list)

	-- 1.7) insert cart_upsell_sector
	delete from cart_upsell_sector where cart_upsell_id = @cart_upsell_id 

	insert into cart_upsell_sector(cart_upsell_id, cart_sector_id)
	select @cart_upsell_id, cart_sector_id = integer_value
	from dbo.fn_integer_string_to_table(@sector_list)

	-- 1.8) insert cart_upsell_template_mapping
	insert into cart_upsell_template_mapping(cart_upsell_id, cart_upsell_template_id)
	values(@cart_upsell_id, @cart_upsell_template_id)

	-- 1.9) insert cart_upsell_discount
	if @cart_discount_id is not null
		begin
			insert into cart_upsell_discount(cart_upsell_id, cart_discount_id)
			values(@cart_upsell_id, @cart_discount_id)
		end

	-- ------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select cart_upsell_id = @cart_upsell_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
