-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_insert_license_update_queue]

(
	@order_header_id int,
	@order_type_group_id int,
	@account_order_json varchar(max) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2009-03-10	esmart		Initial creation.
	2018-07-17	cnovac		Added @account_order_json which will be passed in for WIFI orders

	DESCRIPTION
	
*/

AS
	set nocount on				

begin try

	set nocount on 

	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@response_code int,
			@message varchar(100)

	set @db_name = db_name()

	select @task_number = @order_header_id

	select @sql_string = 
		'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
		' values (' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_cart_update_order_license ' + convert(varchar(10),@order_header_id) + ', ' + convert(varchar(10),@order_type_group_id) + isnull(', ''''' + nullif(ltrim(rtrim(@account_order_json)), '') + '''''''', '''') + ', 0, getdate())'

	exec (@sql_string)

	exec tasks..usp_queue_task @order_header_id

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update licenses for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_insert_payment_header]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_insert_payment_header]

(
		@vendor_order_code varchar(100),
		@merchant_id varchar(50),
		@payment_method_name varchar(50),
		@response_code int output,
		@message varchar(100) output

)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @cart_order_id int,
			@currency_id tinyint,
			@payment_merchant_id tinyint,
			@payment_method_id tinyint,
			@payment_status_id tinyint, 
			@payment_header_id int
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @cart_order_id
	select @cart_order_id = cart_order_id, @currency_id = currency_id
	from cart_order
	where vendor_order_code = @vendor_order_code

	-- 1.2) @payment_merchant_id
	select @payment_merchant_id = payment_merchant_id
	from payment_merchant
	where merchant_id = @merchant_id

	-- 1.3) @payment_method_id
	select @payment_method_id = payment_method_id
	from payment_method
	where payment_method_name = @payment_method_name

	-- 1.4) @payment_header_id
	select @payment_header_id = payment_header_id 
	from payment_header 
	where cart_order_id = @cart_order_id

	-- select @payment_status_id = 1 -- pending

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert payment_header
	if @payment_header_id is null
		begin
		insert into payment_header(cart_order_id,payment_merchant_id,payment_method_id,currency_id)
		values(@cart_order_id,@payment_merchant_id,@payment_method_id,@currency_id)

		select @payment_header_id = scope_identity()

		select @response_code = 0, @message = 'Success'
		end
	-- 2.2) payment header exists
	else
		begin
		select @response_code = 220, @message = 'payment_header exists'
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select h.payment_header_id, m.payment_merchant_id, m.merchant_id, mt.payment_method_id, mt.payment_method_name, c.currency_id, c.currency_code, s.payment_status_id, s.payment_status_name
	from payment_header h
	inner join payment_merchant m
		on m.payment_merchant_id = h.payment_merchant_id
	inner join payment_method mt
		on mt.payment_method_id = h.payment_method_id
	inner join currency c
		on c.currency_id = h.currency_id
	inner join payment_status s
		on s.payment_status_id = h.payment_status_id
	where h.payment_header_id = @payment_header_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not select cart_order for vendor_order_code: ' + @vendor_order_code
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_finalize_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_load_finalize_order]
    (@cart_order_id INT)

/*	
	DATE		AUTHOR		REMARKS
	2014-03-23	esmart		Initial creation.
	2016-07-01	esmart		Move sfdc_opportunity_update to finalize	
	2017-04-20	acoffel		Logic to trap pending entity approval orders
	2017-05-02	acoffel		license_attribute_value changes with Ryan V.
	2018-07-13	cnovac		added call to usp_license_update_license_attribute_license instead of direct call to insert
	2018-09-07	rvinoche	Allow past record updates when calling usp_license_update_license_attribute_license
	2018-11-08	esmart		Add order_extension
	2019-01-16	rvinoche	Update license_attribute_license if order does not have AR (4.3)
	2018-12-19	abelenkiy	Added logic to invalidate pending carts for the same license and product category in section 2.2
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2020-03-27	wbarton		Section 4.3, fixing how we assign @current_autorenewal_value, and managing implicit disables when @current_autorenewal_value is null. This closes gaps where discrepancies can occur betweeen license_attribute_license and license_effective_object.
	2020-06-05	wbarton		Section 4.3, skipping the implicit AR disable for scenarios where the license carries no autorenewal value.
	2021-01-07	esmart		sfdc_case and sap_order
	2023-06-14	gblandford	https://jira.opentext.com/browse/ECOM-880 - added billing_day_of_month to order_extensions for partner orders in section 6.2. Only sfdc provides this value via
							cart_order_extension and as such we were not pushing to SAP the value for partner cart orders
							- used literal configuration names instead of id, for clarity
	2024-04-23	vsingh8		ECOM-4257, Added check to ensure that the SAP update is not queued for SFDC orders which are awaiting billing entity approval.
	2024-06-17	vsingh8		ECOM-4885, Added default value for pending approval variable, to ensure that the sap license update is not deferred for some of the orders not involving billing entity change.

	DESCRIPTION
	Finalize a cart_order

	6.x we load order_extension records from a number of sources:

		cart_order_extension	- these are typically loaded as part of the sfdc_load process for sfdc orders
		partner configuration	- partner specific defaults loaded from partner_configuration_partner, these are typically used to pass values
								  to SAP using mapping tables. E.g. billing_day_of_month is mapped to SAP values using the table dbo.sap_billing_day - dbo.usp_sap_select_order
								  demonstrates this translation.
	DEPENDENCIES
	usp_cart_load_order

*/

AS
    SET NOCOUNT ON;

    DECLARE
        @order_header_id                 INT,
        @payment_header_id               INT,
        @payment_method_id               TINYINT,
        @credit_card_subscription_id     VARCHAR(24),
        @billing_agreement_id            VARCHAR(24),
        @paypal_customer_email           VARCHAR(100),
        @autorenewal_flag                INT,
        @license_attribute_license_value INT,
        @modified_date                   DATETIME     = GETDATE(),
        @site_id                         VARCHAR(20),
        @sfdc_template_id                VARCHAR(20),
        @sfdc_update_type_id             INT,
        @partner_id                      INT,
        @license_attribute_id            INT,
        @pending_approval                BIT          = 0,
        @current_autorenewal_value       INT,
        @license_id                      INT,
        @order_item_id                   INT,
        @rows_inserted                   INT          = 0,
        @rows_start                      INT          = 1,
        @product_line_id            
     INT,
        @company_type_id                 TINYINT,
        @sysuser                         VARCHAR(20)  = SYSTEM_USER,
        @sfdc_template_name              VARCHAR(50),
        @sfdc_update_json                NVARCHAR(MAX),
        @response_code                   INT,
        @message                         VARCHAR(100),
        @SFDC_ORDER_HEADER_SITE_ID       VARCHAR(20);

    DECLARE @license_table TABLE
        (
            id            INT IDENTITY(1, 1),
            license_id    INT,
            order_item_id INT
        );
    DECLARE @keycode_category_table TABLE
        (
            keycode             VARCHAR(40),
            license_category_id TINYINT
        );

    BEGIN TRY

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 1.1) @order_header_id
        SELECT
            @order_header_id  = order_header_id,
            @autorenewal_flag = autorenewal_flag
        FROM
            dbo.cart_order_header
        WHERE
            cart_order_id = @cart_order_id;

        IF @order_header_id IS NULL
            BEGIN
                SELECT
                    @response_code = -100,
                    @message       = 'no order header';
                SELECT
                    response_code = @response_code,
                    message       = @message;
                RETURN;
            END;

        -- 1.2) @site_id
        SELECT
            @site_id = site_id
        FROM
            dbo.order_header
        WHERE
            order_header_id = @order_header_id;

        SELECT
            @SFDC_ORDER_HEADER_SITE_ID = [key]
        FROM
            dbo.fn_app_config_select_key_values('ORDER_HEADER_SITE_ID', 'SFDC');

        -- 1.3) @partner_id
        SELECT
            @partner_id = partner_id
        FROM
            dbo.partner_order
        WHERE
            order_header_id = @order_header_id;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 2.) update cart order
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 2.1) cart_order	
        UPDATE
            dbo.cart_order
        SET
            cart_order_status_id = 2
        WHERE
            cart_order_id = @cart_order_id;

        -- 2.1) cart_order_in_process	
        UPDATE
                dbo.cart_order_in_process
        SET
                cart_order_in_process_status_id = 2
        FROM
                dbo.cart_order_in_process p
            INNER JOIN
                dbo.cart_order            o
                    ON p.cart_order_in_process_id = o.cart_order_in_process_id
        WHERE
                o.cart_order_id = @cart_order_id;

        -- 2.2.1) insert keycodes and categories for each item in cart_order to table
        INSERT INTO @keycode_category_table
            (
                keycode,
                license_category_id
            )
                    SELECT
                            coil.keycode,
                            plc.license_category_id
                    FROM
                            dbo.cart_order               co
                        INNER JOIN
                            dbo.cart_order_item          coi
                                ON coi.cart_order_id
 = co.cart_order_id
                        INNER JOIN
                            dbo.cart_order_item_license  coil
                                ON coil.cart_order_item_id = coi.cart_order_item_id
                        INNER JOIN
                            dbo.product_license_category plc
                                ON plc.product_id = coi.product_id
                    WHERE
                            co.cart_order_id = @cart_order_id;

        -- 2.2.2) invalidate abandoned orders with matching keycodes and categories to prevent them from completing in the future with stale license management parameters
        UPDATE
                co
        SET
                co.cart_order_status_id = 4, --'Invalidated'
                co.modified_date = @modified_date,
                co.modified_by = 'cart_load_invalidation'
        FROM
                dbo.cart_order               co
            INNER JOIN
                dbo.cart_order_item          coi
                    ON coi.cart_order_id = co.cart_order_id
            INNER JOIN
                dbo.cart_order_item_license  coil
                    ON coil.cart_order_item_id = coi.cart_order_item_id
            INNER JOIN
                dbo.product_license_category plc
                    ON plc.product_id = coi.product_id
            INNER JOIN
                @keycode_category_table      kct
                    ON kct.keycode = coil.keycode
                       AND kct.license_category_id = plc.license_category_id
        WHERE
                co.cart_order_id <> @cart_order_id
                AND co.cart_order_status_id = 1; --'Pending'

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 3.) payment_header
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 3.1) insert order_payment_header	
        SELECT
            @payment_header_id = payment_header_id,
            @payment_method_id = payment_method_id
        FROM
            dbo.payment_header
        WHERE
            cart_order_id = @cart_order_id;

        IF @payment_header_id IS NOT NULL
            BEGIN
                INSERT INTO dbo.order_payment_header
                    (
                        order_header_id,
                        payment_header_id
                    )
                VALUES
                    (
                        @order_header_id, @payment_header_id
                    );
            END;

        -- 3.2) update payment_header status
        UPDATE
            dbo.payment_header
        SET
            payment_status_id = 6,
            last_modified_date = @modified_date
        WHERE
            cart_order_id = @cart_order_id;

        --	select * from payment_method

        -- 3.3) see if the credit card subscription is complete 
        IF @payment_method_id = 1
            BEGIN
                -- 3.3.1) get @credit_card_subscription_id
                SELECT
                    @credit_card_subscription_id = credit_card_subscription_id
                FROM
                    dbo.payment_subscription_credit_card
                WHERE
                    payment_header_id = @payment_header_id;

                -- 3.3.2) lookup @credit_card_subscription_id from order that created AR message
                IF @credit_card_subscription_id IS NULL
                    BEGIN
                        SELECT
                                @credit_card_subscription_id = cc.credit_card_subscription_id
                        FROM
                                dbo.order_message                    m
                            INNER JOIN
          
                      dbo.license_message                  lm
                                    ON m.message_key = lm.license_message_key
                            INNER JOIN
                                dbo.license_message_value            v
                                    ON lm.license_message_id = v.license_message_id
                                       AND v.message_value_type_id = 9
                            INNER JOIN
                                dbo.payment_subscription_credit_card cc
                                    ON v.value_id = cc.payment_header_id
                        WHERE
                                m.order_header_id = @order_header_id;

                        -- 3.3.3) insert payment_subscription_credit_card
                        IF @credit_card_subscription_id IS NOT NULL
                            BEGIN
                                INSERT INTO dbo.payment_subscription_credit_card
                                    (
                                        payment_header_id,
                                        credit_card_subscription_id
                                    )
                                VALUES
                                    (
                                        @payment_header_id, @credit_card_subscription_id
                                    );
                            END;

                    END;
            END;

        -- 3.4) see if the paypal subscription is complete 
        IF @payment_method_id = 2
            BEGIN
                -- 3.4.1) get @billing_agreement_id, @paypal_customer_email
                SELECT
                    @billing_agreement_id  = billing_agreement_id,
                    @paypal_customer_email = paypal_customer_email
                FROM
                    dbo.payment_subscription_paypal
                WHERE
                    payment_header_id = @payment_header_id;

                -- 3.4.2) lookup @billing_agreement_id from order that created AR message
                IF @billing_agreement_id IS NULL
                    BEGIN
                        SELECT
                                @billing_agreement_id  = pp.billing_agreement_id,
                                @paypal_customer_email = pp.paypal_customer_email
                        FROM
                                dbo.order_message               m
                            INNER JOIN
                                dbo.license_message             lm
                                    ON m.message_key = lm.license_message_key
                            INNER JOIN
                                dbo.license_message_value       v
                                    ON lm.license_message_id = v.license_message_id
                                       AND v.message_value_type_id = 9
                            INNER JOIN
                                dbo.payment_subscription_paypal pp
                                    ON v.value_id = pp.payment_header_id
                        WHERE
                                m.order_header_id = @order_header_id;

                        -- 3.4.3) insert payment_subscription_credit_card
                        IF @billing_agreement_id IS NOT NULL
                            BEGIN
                                INSERT INTO dbo.payment_subscription_paypal
                                    (
                                        payment_header_id,
                                        billing_agreement_id,
                                        paypal_customer_email
                                    )
                                VALUES
                                    (
                                        @payment_header_id, @billing_agreement_id, @paypal_customer_email
                                    );
                            END;

                    END;
            END;

     
   -- 3.5) purchase order
        IF @payment_method_id = 5
            BEGIN
                INSERT INTO dbo.purchase_order
                    (
                        order_header_id,
                        purchase_order
                    )
                            SELECT
                                @order_header_id,
                                purchase_order
                            FROM
                                dbo.payment_header_purchase_order
                            WHERE
                                payment_header_id = @payment_header_id;
            END;


        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 4.) update cart order
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        IF @payment_method_id IS NOT NULL
           AND @payment_method_id NOT IN (
                                             4, 7
                                         )
            BEGIN
                -- 4.1) check to see if the order has the 301 Autorenewal product
                IF @autorenewal_flag IS NULL
                    BEGIN
                        SELECT
                                @autorenewal_flag = CASE
                                                        WHEN COUNT(*) > 0
                                                            THEN
                                                            1
                                                        ELSE
                                                            0
                                                    END
                        FROM
                                dbo.order_item i
                            INNER JOIN
                                dbo.product    p
                                    ON i.product_id = p.product_id
                        WHERE
                                p.product_family_id = 22
                                AND i.order_header_id = @order_header_id;
                    END;

                -- 4.3) update license_attribute_license

                INSERT INTO @license_table
                    (
                        license_id,
                        order_item_id
                    )
                            SELECT
                                    oil.license_id,
                                    oil.order_item_id
                            FROM
                                    dbo.order_item         oi
                                INNER JOIN
                                    dbo.order_item_license oil
                                        ON oil.order_item_id = oi.order_item_id
                            WHERE
                                    oi.order_header_id = @order_header_id;

                SELECT
                    @rows_inserted = @@rowcount;

                WHILE @rows_inserted >= @rows_start
                    BEGIN

                        SELECT
                            @license_id    = license_id,
                            @order_item_id = order_item_id
                        FROM
                            @license_table
                        WHERE
                            id = @rows_start;

                        SELECT
                            @current_autorenewal_value = license_attribute_license_value
                        FROM
                            dbo.license_attribute_license
                        WHERE
                            license_id = @license_id
                            AND license_attribute_id = 1;

                        IF @autorenewal_flag = 1 --call if there is ar on 
order 
                            EXEC dbo.usp_license_update_license_attribute_license
                                @license_id = @license_id,
                                @license_attribute_id = 1,
                                @license_attribute_license_value = @autorenewal_flag,
                                @modified_by = @sysuser,
                                @effective_date = @modified_date,
                                @order_header_id = @order_header_id,
                                @order_item_id = @order_item_id;

                        --No need to run the implicit disable if the license doesn't have a @current_autorenewal_value from license_attribute_license. In these cases the license will remain with no autorenewal value. 
                        IF @current_autorenewal_value IS NOT NULL
                           AND
                               (
                                   @autorenewal_flag IS NULL
                                   OR @autorenewal_flag = 0
                               ) --implicit ar disable
                            EXEC dbo.usp_license_update_license_attribute_license
                                @license_id = @license_id,
                                @license_attribute_id = 1,
                                @license_attribute_license_value = 2,
                                @modified_by = @sysuser,
                                @effective_date = @modified_date,
                                @order_header_id = @order_header_id,
                                @order_item_id = @order_item_id;

                        SET @rows_start = @rows_start + 1;

                    END;

            END;


        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 5.) sfdc integration
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 5.1) @license_attribute_id
        SELECT
            @license_attribute_id            = a.license_attribute_id,
            @license_attribute_license_value = a.license_attribute_license_value
        FROM
            (
                SELECT  TOP 1
                        i.cart_order_item_id,
                        v.license_attribute_id,
                        v.license_attribute_license_value
                FROM
                        dbo.cart_order_item                 i
                    INNER JOIN
                        dbo.license_attribute_license_value v
                            ON v.license_attribute_license_value = i.license_attribute_license_value
                WHERE
                        i.cart_order_id = @cart_order_id
                ORDER BY
                        i.cart_order_item_id
            ) a;

        -- 5.2) @sfdc_template
        IF @license_attribute_id IS NOT NULL
            BEGIN
                SELECT
                        @sfdc_template_id = p.sfdc_template_id
                FROM
                        dbo.partner_service_order_process_partner op
                    INNER JOIN
                        dbo.partner_service_order_process         p
                            ON op.partner_service_order_process_id = p.partner_service_order_process_id
                WHERE
                        op.partner_id = @partner_id
                        AND op.site_id = @site_id
                        AND op.license_attribute_id = @license_attribute_id
                        AND op.license_attribute_license_value = @license_attribute_license_value;
            END;
        ELSE
            BEGIN
                SELECT
                        @sfdc_template_id = p.sfdc_template_id
   
             FROM
                        dbo.partner_service_order_process_partner op
                    INNER JOIN
                        dbo.partner_service_order_process         p
                            ON op.partner_service_order_process_id = p.partner_service_order_process_id
                WHERE
                        op.partner_id = @partner_id
                        AND op.site_id = @site_id
                        AND op.license_attribute_id IS NULL;
            END;

        IF @sfdc_template_id IS NULL
           AND @site_id = 'AUTOBILLING'
            BEGIN
                SELECT
                    @sfdc_template_id = sfdc_template_id
                FROM
                    dbo.sfdc_template
                WHERE
                    sfdc_template_name = 'autobilling';
            END;

        -- 5.3) set pending flag
        SELECT
            @pending_approval = CASE
                                    WHEN pl.partner_license_status_id = 1
                                        THEN
                                        1
                                    ELSE
                                        0
                                END
        FROM
            dbo.partner_license pl
        WHERE
            pl.order_header_id = @order_header_id
            AND pl.partner_id = @partner_id;

        -- 5.4) sfdc_opportunity_update
        IF @sfdc_template_id IS NOT NULL
            BEGIN
                SELECT
                    @sfdc_update_type_id =
                    (
                        SELECT TOP 1
                               sfdc_update_type_id
                        FROM
                               dbo.sfdc_template_update_type
                        WHERE
                               sfdc_template_id = @sfdc_template_id
                        ORDER BY
                               sfdc_template_update_type_id
                    );

                INSERT INTO dbo.sfdc_opportunity_update
                    (
                        order_header_id,
                        sfdc_update_type_id,
                        sfdc_update_status_id,
                        process_date,
                        sfdc_template_id
                    )
                VALUES
                    (
                        @order_header_id, @sfdc_update_type_id, CASE
                                                                    WHEN @pending_approval = 1
                                                                        THEN
                                                                        4
                                                                    ELSE
                                                                        0
                                                                END, DATEADD(ss, 60, GETDATE()), @sfdc_template_id
                    );
            END;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 6.) order_extension
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 6.1) insert explicit extension
        INSERT INTO dbo.order_extension
            (
                order_header_id,
                order_extension_type_id,
                order_extension_value
            )
                    SELECT
                        @order_header_id,
                        order_extension_type_id,
                        order_extension_value
                    FROM
                        dbo.cart_order_extension
                    WHERE
                        cart_order_id = @cart_order_id;

        -- 6.2) a
dd default partner extensions
        IF @partner_id IS NOT NULL
            BEGIN
                INSERT INTO dbo.order_extension
                    (
                        order_header_id,
                        order_extension_type_id,
                        order_extension_value
                    )
                            SELECT
                                    order_header_id         = @order_header_id,
                                    order_extension_type_id = oet.order_extension_type_id,
                                    order_extension_value   = pcp.configuration_value
                            FROM
                                    dbo.partner_configuration_partner pcp
                                INNER JOIN
                                    dbo.partner_configuration         pc
                                        ON pc.partner_configuration_id = pcp.partner_configuration_id
                                INNER JOIN
                                    dbo.order_extension_type          oet
                                        ON oet.order_extension_type_name = pc.configuration_name
                                LEFT JOIN
                                    dbo.order_extension               oe
                                        ON oe.order_extension_type_id = oet.order_extension_type_id
                                           AND oe.order_header_id = @order_header_id
                            WHERE
                                    pcp.partner_id = @partner_id
                                    AND pc.configuration_name IN (
                                                                     'billing_day_of_month', 'billing_frequency',
                                                                     'billing_period', 'invoice_day_of_month'
                                                                 )
                                    AND oe.order_extension_id IS NULL;
            END;

        -- 6.3) default order_extensions

        -- 6.3.1) @product_line_id
        SELECT
            @product_line_id =
            (
                SELECT  TOP 1
                        pl.product_line_id
                FROM
                        dbo.order_item           i
                    INNER JOIN
                        dbo.product_line_product pl
                            ON i.product_id = pl.product_id
                WHERE
                        i.order_header_id = @order_header_id
                ORDER BY
                        pl.product_line_id DESC
            );

        -- 6.3.2) @company_type_id
        SELECT
                @company_type_id = cc.company_type_id
        FROM
                dbo.customer_order   co
            INNER JOIN
                dbo.customer_company cc
                    ON co.customer_id = cc.customer_id
        WHERE
                co.order_header_id = @order_header_id
                AND co.customer_type_id = 2;

        -- 6.3.3) insert order_extension
        INSERT INTO dbo.order_extension
            (
                order_header_id,
                order_extension_type_id,
                order_extension_value
            )
                    SELECT
                            @order_header_id,
                            f.order_extension_type_id,
                            f.order_extension_value
                    FROM
                            dbo.fn_order_select_default_order_extension(
                                                                           @site_id, @product_line_id, @company_type_id,
                                                                           @license_attribute_license_value
                                                                       ) f
                        LEFT JOIN
                            dbo.order_extension                          e
                               
 ON f.order_extension_type_id = e.order_extension_type_id
                                   AND e.order_header_id = @order_header_id
                    WHERE
                            e.order_extension_id IS NULL;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 7.) case
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 7.1) @sfdc_update_json
        DECLARE @case_items TABLE
            (
                order_item_id         INT,
                license_category_id   TINYINT,
                license_category_name VARCHAR(50),
                product_platform_id   INT,
                product_platform_name VARCHAR(50),
                sfdc_case_type_id     TINYINT,
                sfdc_case_type_name   VARCHAR(50),
                license_id            INT,
                keycode               VARCHAR(40)
            );

        INSERT INTO @case_items
            (
                order_item_id,
                license_category_id,
                license_category_name,
                product_platform_id,
                product_platform_name,
                sfdc_case_type_id,
                sfdc_case_type_name,
                license_id,
                keycode
            )
                    SELECT
                                    i.order_item_id,
                                    c.license_category_id,
                                    c.license_category_name,
                                    c.product_platform_id,
                                    c.product_platform_name,
                                    c.sfdc_case_type_id,
                                    c.sfdc_case_type_name,
                                    l.license_id,
                                    l.keycode
                    FROM
                                    dbo.order_item                                                     i
                        INNER JOIN
                                    dbo.order_item_license                                             il
                                        ON il.order_item_id = i.order_item_id
                        INNER JOIN
                                    dbo.license                                                        l
                                        ON l.license_id = il.license_id
                        INNER JOIN
                                    dbo.product_license_category                                       plc
                                        ON plc.product_id = i.product_id
                        INNER JOIN
                                    dbo.product_extension                                              pe
                                        ON pe.product_id = i.product_id
                        OUTER APPLY dbo.fn_product_select_product_extension(pe.product_extension_json) f
                        CROSS APPLY dbo.fn_case_select_product_mapping(plc.license_category_id, f.product_platform_id) c
                    WHERE
                                    i.order_header_id = @order_header_id;

        IF @@ROWCOUNT > 0
            BEGIN
                SELECT
                    @sfdc_update_json =
                    (
                        SELECT
                            @order_header_id AS order_header_id,
                    (
                        SELECT
                            order_item_id,
                            license_category_id,
                            license_category_name,
                            product_platform_id,
                            product_platform_name,
        
                    sfdc_case_type_id,
                            sfdc_case_type_name,
                            license_id,
                            keycode
                        FROM
                            @case_items
                        FOR JSON PATH
                    )                        AS case_items
                        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
                    );
            END;

        -- 7.2) insert sfdc_opportunity_update
        IF @sfdc_update_json IS NOT NULL
            BEGIN
                SELECT
                    @sfdc_template_name = 'create_case';

                EXEC dbo.usp_sfdc_insert_sfdc_opportunity_update
                    @sfdc_template_name = @sfdc_template_name,
                    @order_header_id = @order_header_id,
                    @sfdc_update_json = @sfdc_update_json;
            END;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 8.) sap_order
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 8.1) usp_sap_insert_sap_order
        IF @site_id = @SFDC_ORDER_HEADER_SITE_ID
           AND @pending_approval = 0
            BEGIN
                EXEC dbo.usp_sap_insert_sap_order
                    @order_header_id;
            END;


    END TRY
    BEGIN CATCH

        SET @response_code = -200;
        SET @message = CASE
                           WHEN @message IS NULL
                               THEN
                               'select failed'
                           ELSE
                               @message
                       END;

        DECLARE @DBName NVARCHAR(128);
        SET @DBName = DB_NAME();
        EXEC dbo.usp_LogError
            @ErrorDB = @DBName;

    END CATCH;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_insert_customer]
-- =============================================================================

CREATE procedure [dbo].[usp_cart_load_insert_customer] 
(
	@cart_order_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2014-05-08	esmart		vat_id support
	2014-09-10	esmart		Include partner in customer insert
	2015-3-5	cnovac		Added @company_type_name = null to usp_customer_insert_customer_service call
	2018-10-04	esmart		Add @company_type_name 
	2019-06-21	esmart		Add @company_id_input. Make only unique calls to usp_customer_insert_customer_service.
	2019-08-29	esmart		Add distributor and download contact
	2019-11-15	esmart		Update @company_type_name data type
	2020-10-06	abelenkiy	Complete refactor to read from cart_customer_json instead of cart_customer_table
							Optimized handling of multiple customer_types to prevent duplicate calls to usp_customer_insert_customer_service
							Moved vat_id logic to usp_customer_update_customer_service for company_vat

	DESCRIPTION
	Insert customer and company from account and contact
*/
as
set nocount on;

	begin try
		declare @cart_customer_json table (cart_customer_json nvarchar(4000), customer_type_id int, customer_id int, rank int);

		declare @tmp_id int = 1, @max_id int, @input_json nvarchar(4000), @customer_id int;

		-- 1.1) remove existing records
		delete from cart_order_customer where cart_order_id = @cart_order_id

		-- 2) prepare data
		-- 2.1) create cte with json from cart_customer_json for each customer_type_id and format to comply with customer_update schema
		;with json_by_type
		as (select ccj.cart_customer_json
					, cc.customer_type_id
			from cart_customer_json ccj
				inner join cart_customer cc
					on cc.cart_customer_id = ccj.cart_customer_id
				inner join cart_order co
					on co.cart_order_id = cc.cart_order_id
			where co.cart_order_id = @cart_order_id and json_value(cart_customer_json, '$.customer.customer_email') is not null)
		-- 2.2) insert results to table variable and rank to identify duplicate json strings
		insert into @cart_customer_json (cart_customer_json, customer_type_id, rank)
		select j.cart_customer_json
			, j.customer_type_id
			, dense_rank() over (order by j.cart_customer_json)
		from json_by_type j;

		-- 3) loop json through usp_customer_insert_customer_service
		-- 3.1) select max rank (this could be lower than total records if duplicate json exists)
		select @max_id = max(rank)from @cart_customer_json cuj;

		-- 3.2) loop through customer service with unique json 
		while @tmp_id <= @max_id
			begin
				select @input_json = cuj.cart_customer_json
				from @cart_customer_json cuj
				where cuj.rank = @tmp_id;

				exec usp_customer_insert_customer_service @customer_id = @customer_id output
														, @input_json = @input_json;

				-- 3.2.1) update table variable with customer_id output
				update @cart_customer_json
				set customer_id = @customer_id
				where @tmp_id = rank;

				select @tmp_id = @tmp_id + 1, @customer_id = null;

			end;

		-- 4) insert cart_order_customer record for each customer_type_id (regardless of whether json was unique)
		insert into cart_order_customer (cart_order_id, customer_id, customer_type_id)
		select distinct @cart_order_id, cuj.customer_id, cuj.customer_type_id
		from @cart_customer_json cuj;

		return;

	end try
	begin catch
		declare @DBName nvarchar(128);
		set @DBName = db_name();
		exec usp_LogError @ErrorDB = @DBName;
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_insert_header]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_load_insert_header]

(
	@cart_order_id int,
	@autorenewal_flag int = NULL,
	@download_instruction_type_id tinyint = NULL,
	@order_header_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2014-03-23	esmart		Initial creation.
	2015-10-08	esmart		Extend matching on p_rc to permission_group_membership
	2016-08-01	blu			Insert of utm parameters into order_code.
	2017-10-31	esmart		Default Needle to WRCART
	2018-04-10	esmart		@download_instruction_type_id
	2018-09-04	esmart		add default order_code insert
	2018-11-08	esmart		Move order_extensions to finalize
	2019-08-29	esmart		order_opportunity
	2019-11-19	wbarton		Updating 2.6 for site_id AUTORENEWAL
	2019-01-29	wbarton		Adding CBCART to the 2.6 autorenewal_flag = 0 exemption list
	2023-08-25  psatish		ECOM-1954 Modified the secion 2.7 to insert the oppotunity_type_id on the order_opportunity table for SFDC orders
	DESCRIPTION
	Insert order_header
*/

AS
	set nocount on				

	declare	@opportunity_id varchar(18), 
			@vendor_order_date datetime,
			@total_amount money,
			@sub_total_amount money,
			@tax_total money,
			@fee_total money,
			@order_offer_amount money,
			@purchase_order varchar(100),
			@currency_iso_code varchar(3),
			@bill_to_account_id varchar(20),
			@site_id varchar(20), 
			@vendor_id int,
			@insert_by varchar(20), 
			@insert_date datetime, 
			@vendor_order_code_prefix varchar(5), 
			@vendor_order_code varchar(100), 
			@sequence_id int,
			@vendor_order_id int,
			@locale varchar(5),
			@currency_id tinyint,
			@partner_id int, 
			@language_code varchar(2),
			@location_code varchar(3), 
			@location_code_2 varchar(2),
			@p_rc varchar(50),
			@p_rsc varchar(50),
			@p_ac varchar(100),
			@trx_rc varchar(50),
			@trx_rsc varchar(50),
			@trx_ac varchar(100),
			@message_key varchar(36),
			@cart_discount_id int,
			@cart_json nvarchar(max),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select	@insert_by = 'cart_load', 
			@insert_date = getdate()
	
	-- 1.0) @vendor_id
	select @vendor_id = v.vendor_id
	from cart_order c
	inner join order_type t
		on c.order_type = t.order_type
	inner join vendor_order_type v
		on t.order_type_id = v.order_type_id	
	where c.cart_order_id = @cart_order_id

	-- 1.1) setup data
	select  @vendor_order_code = vendor_order_code,
			@site_id = site_id,
			@total_amount = total_amount,
			@sub_total_amount = sub_total_amount,
			@order_offer_amount = offer_amount,
			@tax_total = tax_amount,
			@vendor_order_date = sales_order_date,
			@currency_id = currency_id,
			@p_rc = p_rc,
			@p_rsc = p_rsc,
			@p_ac = p_ac,
			@trx_rc = trx_rc,
			@trx_rsc = trx_rsc,
			@trx_ac = trx_ac,
			@locale = locale
	from cart_order	
	where cart_order_id = @cart_order_id

		-- 1.1.1) Check for Needle reseller carts
		select @partner_id = partner_id
		from cart_order_partner
		where cart_order_id = @cart_order_id

		if @partner_id = 8208 and @site_id = 'RESELLER'
			begin
			select @site_id = 'WRCART'
			end

	-- 1.3) vendor_order
	select @order_header_id = order_header_id
	from order_header h
	inner join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	where v.vendor_order_code = @vendor_order_code and v.vendor_id = @vendor_id

	if @order_header_id is not 
null
		begin
		return
		end
	
	-- 1.4) @download_instruction_type_id
	if @download_instruction_type_id is null
		begin
		select @download_instruction_type_id = json_value(j.cart_json,'$.download_instruction_type_id')
		from cart_json j 
		where j.cart_order_id = @cart_order_id
		end
				
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) vendor_order
		insert into vendor_order(vendor_id, vendor_order_code, insert_date, insert_by, modified_date, modified_by)
		values(@vendor_id, @vendor_order_code, @insert_date, @insert_by, @insert_date, @insert_by)

		select @vendor_order_id = scope_identity()
		
	-- 2.2) order_header
		insert into order_header(vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, fee_total, download_instruction_type_id)
		select @vendor_order_id, order_offer_id=null, @order_offer_amount, @total_amount, @sub_total_amount, @tax_total, payment_method_id=0, 
			session_id=0, @vendor_order_date, @locale, exchange_rate=0, @site_id, site_url='WRCART', order_status_id=1, @insert_date, @insert_by, @insert_date, @insert_by, fee_total=0, isnull(@download_instruction_type_id,0)

		select @order_header_id = scope_identity()

		-- select order_header_id = @order_header_id

	-- 2.3) order_currency
		insert into order_currency(order_header_id, currency_id)
		values(@order_header_id, @currency_id)

	-- 2.4) order_code
	select @cart_json = cart_json
	from cart_json
	where cart_order_id = @cart_order_id

	if @cart_json is not null and @cart_json <> ''
		begin
			declare @order_code table (code_type varchar(50), code_value varchar(50))

			insert into @order_code (code_type, code_value)
			select code_type = convert(varchar(50),j.[Key]),
						code_value = convert(varchar(50), j.Value)
			from openjson(@cart_json) j

			insert into order_code (code_type_id, order_header_id, code_value)
			select t.code_type_id, @order_header_id, c.code_value
			from @order_code c
			inner join code_type t
				on t.code_type = c.code_type
			where c.code_value is not null and c.code_value <> ''
		end

			-- 2.4.1) check for no order_code and add default
			insert into order_code (code_type_id, order_header_id, code_value)
			select code_type_id = 1, h.order_header_id, code_value = 1
			from order_header h
			left join order_code oc
				on oc.order_header_id = h.order_header_id and oc.code_type_id = 1
			where h.order_header_id = @order_header_id and oc.order_code_id is null

	-- 2.5) order_fee
	if (select count(*) from payment_fee where cart_order_id = @cart_order_id) > 0
		begin
		-- 2.5.1) order_fee
		insert into order_fee(order_header_id, payment_fee, insert_date)
		select @order_header_id, payment_fee, @insert_date
		from payment_fee
		where cart_order_id = @cart_order_id

		-- 2.5.2) update order_header
		update order_header
		set fee_total = (select sum(payment_fee) from order_fee where order_header_id = @order_header_id),
			modified_date = @insert_date,
			modified_by = @insert_by
		where order_header_id = @order_header_id
		end

	-- 2.5) @message_key
	select @message_key = message_key, @cart_discount_id = cart_discount_id
	from cart_order_message
	where cart_order_id = @cart_order_id

	if @message_key is not null
					begin
					-- 2.5.1) insert order_message
					insert into order_message (order_header_id, message_key, cart_discount_id, license_id, message_campaign_id, message_cam
paign_platform)
					select @order_header_id, message_key, cart_discount_id, license_id, message_campaign_id, message_campaign_platform
					from cart_order_message
					where cart_order_id = @cart_order_id
					

    
					-- 2.5.2) update license_message
					declare @license_message_id int,
													@message_type_id tinyint,
													@message_status_id tinyint

					select @license_message_id = license_message_id, @message_type_id = message_type_id
					from license_message with (nolock)
					where license_message_key = @message_key

					if @license_message_id is not null and @message_type_id <> 3
									begin
									select @message_status_id = 3
									exec usp_license_message_insert_update_message_queue @license_message_id,@message_status_id
									end
					end

	-- 2.6) cart_order_header
	if @site_id not in ('WRCART','CSI', 'AUTORENEWAL', 'CBCART')
		begin
		select @autorenewal_flag = 0
		end

	insert into cart_order_header(cart_order_id,autorenewal_flag,order_header_id)
	values(@cart_order_id,@autorenewal_flag,@order_header_id)

	-- 2.7) order_opportunity
	insert into order_opportunity (order_header_id, salesforce_opportunity_id,order_opportunity_type_id)
	select x.order_header_id, x.salesforce_opportunity_id, ty.order_opportunity_type_id
	from (select @order_header_id as order_header_id, salesforce_opportunity_id, opportunity_type
		from openjson(@cart_json) 
		with (salesforce_opportunity_id varchar(18) '$.opportunity_id',
		      opportunity_type varchar(18) '$.opportunity_type'))x 
		left join order_opportunity_type ty
		on ty.order_opportunity_type_description=x.opportunity_type
	where x.salesforce_opportunity_id is not NULL




	return 

	end try

	

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_insert_order_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_load_insert_order_customer]

(
	@cart_order_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2015-3-5	cnovac		Added @company_type_name = null to usp_customer_insert_customer_service call
	2019-03-08	esmart		Remove needle as valid partner in 2.3
	2019-05-01	esmart		Refactor insert in customer_order and order_company
	2019-07-29	esmart		Add partner_order even in case of exception
	2019-08-01	abelenkiy	Added DISTINCT to selects for inserts to order_company (sect 3.2.1) and customer_order (sect 2.1) to prevent duplicate inserts; removed @insert_date and other unused variables
	2019-08-29	esmart		Add support for download contact from SFDC. Don't create order_company for download contact.
	2019-11-14	esmart		Update to include all SFDC carts to insert order_company
	
	DESCRIPTION
	Insert customer_order
*/

AS
	set nocount on				

	declare	@order_header_id int,
			@site_id varchar(20),
			@insert_by varchar(20), 
			@response_code int,
			@message varchar(100)

	declare @customer table (customer_id int, company_id int, customer_type_id int, order_company_type_id tinyint)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) set values
	select	@insert_by = 'cart_load'

	-- 1.2) @order_header_id
	select @order_header_id = ch.order_header_id, @site_id = co.site_id
	from cart_order_header ch
	inner join cart_order co
		on ch.cart_order_id = co.cart_order_id
	where ch.cart_order_id = @cart_order_id

	if @order_header_id is null
		begin
		select @response_code = -100, @message = 'no order header'
		select response_code = @response_code, message = @message
		return
		end


	-- 1.3) @customer	

		-- 1.3.1) insert @customer
		insert into @customer (customer_id, company_id, customer_type_id, order_company_type_id)
		select oc.customer_id, cc.company_id, oc.customer_type_id, 
			order_company_type_id = case 
										when oc.customer_type_id = 2 then 1
										when oc.customer_type_id = 1 then 2
										else oc.customer_type_id
									end
		from cart_order_customer oc
		left join customer_company cc
			on oc.customer_id = cc.customer_id
		where oc.cart_order_id = @cart_order_id

		-- 1.3.2) add distributor for partner related to order
		insert into @customer (customer_id, company_id, customer_type_id, order_company_type_id)
		select x.customer_id, x.company_id, x.customer_type_id, x.order_company_type_id
		from (select cc.customer_id, cc.company_id, 4 as customer_type_id, 4 as order_company_type_id
			from cart_order_partner cp
			inner join partner p
				on cp.partner_id = p.partner_id
			inner join partner_customer pc
				on pc.partner_id = cp.partner_id
			inner join customer_company cc
				on pc.customer_id = cc.customer_id
			where cp.cart_order_id = @cart_order_id and p.partner_type_id = 1) x
		left join @customer c
			on x.order_company_type_id = c.order_company_type_id
		where c.customer_id is null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) customer_order
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
---------------------------
	
	-- 2.1) insert customer_order
	insert into customer_order (customer_id, order_header_id, customer_type_id, insert_by, modified_by) 
	select distinct c.customer_id, @order_header_id, c.customer_type_id, @insert_by, @insert_by
	from @customer c
	inner join customer_type t
		on c.customer_type_id = t.customer_type_id
	left join customer_order co
		on co.order_header_id = @order_header_id and c.customer_id = co.customer_id and c.customer_type_id = co.customer_type_id
	where co.customer_order_id is null
	order by c.customer_type_id

	-- 2.2) customer_order_address
	insert into customer_order_address (order_header_id, customer_address_id, insert_by, modified_by)
	select @order_header_id, a.customer_address_id, @insert_by, @insert_by
	from @customer c
	inner join customer_address a
		on c.customer_id = a.customer_id
	left join customer_order_address coa
		on coa.order_header_id = @order_header_id
	where c.customer_type_id = 1 and a.address_status_id = 1 and a.address_type_id = 1 and coa.customer_order_address_id is null
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) order_company
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
					
	-- 3.1) insert partner_order
	insert into partner_order (partner_id, order_header_id, partner_account_id, insert_date)
	select cop.partner_id, @order_header_id, cop.partner_account_id, getdate()
	from cart_order_partner cop
	left join partner_order po
		on cop.partner_id = po.partner_id and po.order_header_id = @order_header_id
	where cart_order_id = @cart_order_id and cop.partner_id not in (8208) and po.partner_order_id is null


	
	-- 3.2) insert order_company for business product lines
	if exists (select i.product_id from cart_order_item i inner join product_line_product plp on i.product_id = plp.product_id where i.cart_order_id = @cart_order_id and plp.product_line_id in (300,55)) or @site_id = 'SFDC'
		begin
   			-- 3.2.1) verify all customers have a company_id and insert order_company
			if not exists (select customer_id from @customer where company_id is null)
				begin
					-- 3.2.1) insert order_company
					insert into order_company (order_header_id, company_id, order_company_type_id, customer_id)
					select distinct @order_header_id, c.company_id, c.order_company_type_id, c.customer_id
					from @customer c
					left join order_company oc
						on oc.order_header_id = @order_header_id and c.company_id = oc.company_id and c.order_company_type_id = oc.order_company_type_id
					where oc.order_company_id is null and c.customer_type_id < 5 
					order by c.order_company_type_id

				end
			-- 3.2.2) insert order_external_load_exception
			else
				begin
					insert into order_external_load_exception(order_header_id, exception_status)
					values(@order_header_id,'pending')
				end
		end

	end try
	
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;









GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_insert_order_item]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_load_insert_order_item]

(
	@cart_order_id INT,
	@license_distribution_method_code VARCHAR(4) = NULL
)

/*
	DATE		AUTHOR		REMARKS
	2014-03-23	esmart		Initial creation.
	2014-05-06	esmart		license registration
	2014-07-09	esmart		Bundle support
	2014-09-10	esmart		Allow update to license.customer_id
	2015-04-07	esmart		Fix issue with bulk quantity of consumer
	2017-08-15	esmart		item_hierarchy_id
	2017-10-25	acoffel		tax calc for domestic business products
	2018-01-16	cnovac		rolled back some tax code
	2018-04-20	cnovac		changed code to pass in @order_item_id to license attribute and cycle inserts and usp_license_insert_license_service
	2018-08-19	esmart		Verify start and expiration dates
	2018-09-07	rvinoche	Allow past record updates when calling usp_license_update_license_attribute_license
	2018-10-12	esmart		Include new purchase start and expiration date verification
	2018-10-22	esmart		Insert license_usage_pricing for autobilling utility and overage
	2018-12-20	esmart		Implement date_override and update to license create for utility
	2019-01-10	rvinoche	Set @billing_day_of_month
	2019-04-24	rvinoche	When renewals have seat increase, prevent the upsell line from having usage 6.1)
	2019-05-08	abelenkiy	Added support for license_usage_pricing_value in effective_object
	2019-07-09	esmart		Add cart_load logging
	2019-08-08	esmart		Add usage_pricing_model
	2019-09-06	cnovac		Changed sp calls to take out @allow_past_record_update and updated 7.) license usage pricing section so we write usage pricing even when there's an upgrade
	2019-09-20	abelenkiy	Added logic to prevent duplicate inserts to order_item_license (sections 3.1, 4.3)
	2019-10-30	esmart		Correct json name for usage_pricing_model_id
	2020-01-30	esmart		Update license registration customer select
	2020-01-29	wbarton		Modifying 6.2.1 so the usp_license_update_license_attribute_license call only takes place when @license_attribute_id <> 1. It's redundant for autorenewal.
	2020-01-30	esmart		Update license registration customer select
	2020-02-21	esmart		Add support for vault
	2020-05-14	esmart		Add retention_model
	2020-07-28	wbarton		Removing the handling of vault. This will be done via usp_cart_update_order_license_new.
	2020-10-14	cnovac		Added logic for storage_gb
	2021-01-13	cnovac		Took out section 8.0 and moved that code to usp_cart_update_order_license_new so effective object elements can get caught in billing entity if needed
	2021-12-08	psatish		Added Perpetual billing model to update the contract end date
	2022-05-17  psatish     ALM# 990 Insert the sap_material_number in the Order_item table and identify the MSP license
	2022-06-09  psatish		ALM# 1377 Select the license category from sap_material_product_mapping for msp_flag
	2023-04-04  psatish		ECOM-899 Added the section 10.0 for storage_GB in the license_effective_object table
	2023-06-06  jberry		ECOM-1169 Remove license category in section 10.0 to support all capacity products
	2023-08-25	psatish		ECOM-1318 Modified the section 10.0 for Amend_upsell_order and modified the join 
	2024-04-24	pachanta	ECOM-3883 When SkyRise is offline, ecom keycode genertion should use distribution_method_code override
	2025-10-14	jberry		US-5004939 - added section 2.5 to update item total for capacity cart orders
	
	DESCRIPTION
	Insert order_item

	DEPENDENCIES
	Having the dependency of usp_cart_load_order procedure.
*/

AS
	set nocount on

	declare	@order_header_id int,
			@order_item_id int,
			@product_id int,
			@product_type_id int,
			@quantity int,
			@item_bundle_id int,
			@insert_by varchar(20),
			@insert_date datetime,
			@vendor_order_date datetime,
			@license_distribution_method_id int,
			@l
icense_bulk_load_description varchar(100),
			@module_product_id int,
			@days_override int,
			@enterprise_seats int,
			@license_type_id int,
			@fixed_expiration_OEM tinyint,
			@license_expiration_date datetime,
			@system_user varchar(50),
			@product_line_id int,
			@license_keycode_type_id int,
			@trial int,
			@contract_start_date datetime,
			@contract_end_date datetime,
			@contract_months int,
			@external_keycode varchar(20),
			@cart_license_distribution_method_id int,
			@customer_type_id int,
			@keycode varchar(40),
			@partner_id int,
			@start_date datetime,
			@expiration_date datetime,
			@order_item_update_type_id tinyint,
			@temp_id int,
			@total_ids int,
			@license_id int,
			@license_attribute_id int,
			@license_attribute_license_value int,
			@message_autorenewal_cycle_id tinyint,
			@billing_day_of_month tinyint,
			@modified_by varchar(20),
			@effective_date datetime,
			@date_override varchar(500),
			@license_effective_object_json nvarchar(max),
			@vault_effective_object_json nvarchar(max),
			@vault_id int,
			@response_code int,
			@message varchar(100),
			@MSP_Flag int,
			--@license_distribution_method_code varchar(5),
			@storage_gb int,
			@usage_pricing_model_id int,
			@order_opportunity_type_id int

	declare @vault table (license_id int, license_category_id tinyint, vault_id int, effective_start_date datetime, order_item_id int)
	

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) set values
	select	@insert_by = 'cart_load',
			@insert_date = getdate(),
			@trial = 0

	-- 1.2) @order_header_id
	-- 1.2) @order_header_id
	select @order_header_id = order_header_id
	from cart_order_header
	where cart_order_id = @cart_order_id

	if @order_header_id is null
		begin
		select @response_code = -100, @message = 'no order header'
		select response_code = @response_code, message = @message
		RETURN
		END

	-- 1.3) @vendor_order_date
	select @vendor_order_date = vendor_order_date
	from order_header
	where order_header_id = @order_header_id

	-- 1.4) license_distribution_method_id for partner
	SELECT @license_distribution_method_id = ldm.license_distribution_method_id
	from partner_order o
	inner join partner_license_distribution_method pm
		on o.partner_id = pm.partner_id
	JOIN dbo.license_distribution_method ldm
        ON ldm.license_distribution_method_id = pm.license_distribution_method_id
	where o.order_header_id = @order_header_id
	AND ldm.license_distribution_method_code = CASE
                                                    WHEN @license_distribution_method_code IS NOT NULL THEN
                                                        @license_distribution_method_code
                                                    ELSE
                                                        ldm.license_distribution_method_code
                                               END;


	-- 1.5) past start date
	select @date_override = json_value(cart_json,'$.date_override')
	from cart_json
	where cart_order_id = @cart_order_id

	if @date_override is null or @date_override <> 'true'
		begin
			insert into cart_order_item_audit(cart_order_item_id, cart_order_id, line_item, quantity,order_item_offer_amount, list_price,unit_price, tax_item_total, product_id,insert_date, insert_by, modified_date,modified_by, cart_item_bundle_id,start_date, expiration_date,vendor_order_item_code,order_item_update_type_id,license_attribute_license_value,item_hierarchy_id,cart_discount_id,cart_discount_method_id,discount,unit_price_pre_vat,sap_materi
al_number,storage_gb)
			select i.cart_order_item_id, i.cart_order_id, i.line_item, i.quantity,i.order_item_offer_amount, i.list_price,i.unit_price, i.tax_item_total, i.product_id,i.insert_date, i.insert_by, i.modified_date, i.modified_by, i.cart_item_bundle_id,i.start_date, i.expiration_date,i.vendor_order_item_code,i.order_item_update_type_id,i.license_attribute_license_value,i.item_hierarchy_id,i.cart_discount_id,i.cart_discount_method_id,i.discount,i.unit_price_pre_vat,i.sap_material_number,i.storage_gb
			from cart_order_item i
			inner join product p
				on p.product_id = i.product_id
			where cart_order_id = @cart_order_id and p.product_type_id in (2,3) and i.start_date < convert(date,getdate())

			UPDATE cart_order_item
			SET start_date = case
									when i.start_date < convert(date,getdate()) then convert(date,getdate())
									else i.start_date
								end,
				expiration_date = case
									when p.product_type_id in (1,2) and i.start_date < convert(date,getdate()) then dateadd(dd,datediff(dd,i.start_date,i.expiration_date),convert(date,getdate()))
									else i.expiration_date
								end,
				modified_date = getdate(),
				modified_by = 'cart_load_item'
			from cart_order_item i
			inner join product p
				on p.product_id = i.product_id
			where cart_order_id = @cart_order_id and i.start_date < convert(date,getdate())
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) order_item
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert order_item records
	insert into order_item (order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, order_item_status_id, item_bundle_id, effective_date, capability_expiration_date, order_item_update_type_id,item_hierarchy_id,sap_material_number)
	select order_header_id = @order_header_id,
		line_item,
		product_id,
		quantity,
		list_price,
		unit_price,
		tax_item_total,
		order_item_offer_code,
		order_item_offer_amount,
		item_total = (quantity * unit_price) + tax_item_total,
		tax_exempt,
		order_item_status_id = 1,
		cart_item_bundle_id,
		effective_date = case when start_date is null then @vendor_order_date else start_date end,
		expiration_date,
		order_item_update_type_id,
		item_hierarchy_id,
		sap_material_number
	from cart_order_item
	where cart_order_id = @cart_order_id

	-- 2.2) vendor_order_item
	INSERT INTO vendor_order_item(order_item_id, order_header_id, transaction_date, insert_date, insert_by, modified_date, modified_by, vendor_order_item_code)
	SELECT i.order_item_id, i.order_header_id, @insert_date, @insert_date, @insert_by, @insert_date, @insert_by, ci.vendor_order_item_code
	FROM order_item i
	INNER JOIN cart_order_item ci
		ON i.line_item = ci.line_item AND ci.cart_order_id = @cart_order_id
	WHERE i.order_header_id = @order_header_id AND ci.vendor_order_item_code IS NOT NULL

	-- 2.3) order_item_opportunity_line_item
	INSERT INTO order_item_opportunity_line_item (order_item_id, opportunity_line_item_id)
	SELECT i.order_item_id, ci.opportunity_line_item_id
	FROM order_item i
	INNER JOIN cart_order_item ci
		ON i.line_item = ci.line_item AND ci.cart_order_id = @cart_order_id
	LEFT JOIN order_item_opportunity_line_item oi
		ON i.order_item_id = oi.order_item_id
	WHERE i.order_header_id = @order_header_id AND ci.opportunity_line_item_id IS NOT NULL AND oi.order_item_opportunity_line_item_id IS NULL

	-- 2.4) order_item_json
	INSERT INTO order_item_json(order_item_id, order_item_json)
	SELECT i.order_item_id, j.cart_order_item_json
	FROM order_item i
	INNER JOIN cart_order_it
em ci
		ON i.line_item = ci.line_item AND ci.cart_order_id = @cart_order_id
	INNER JOIN cart_order_item_json j
		ON j.cart_order_item_id = ci.cart_order_item_id
	left join order_item_json ij
		on i.order_item_id = ij.order_item_id
	where i.order_header_id = @order_header_id and ij.order_item_json_id is NULL

	-- 2.5 update item total for capacity cart orders
	UPDATE dbo.order_item
	SET item_total = CAST((oi.unit_price * TRY_CAST(JSON_VALUE(oij.order_item_json, '$.actual_storage_quantity') AS DECIMAL(12,5))) + oi.tax AS MONEY)
	FROM dbo.order_item oi
	INNER JOIN dbo.order_header oh
	    ON oh.order_header_id = oi.order_header_id
	INNER JOIN dbo.order_item_json oij 
	    ON oij.order_item_id = oi.order_item_id
	WHERE oh.site_id IN ('CSI','WRCART')
	AND JSON_VALUE(oij.order_item_json, '$.usage_pricing_model_id') = 2
	AND oi.order_header_id = @order_header_id

	-- LOG: usp_cart_load_insert_order_item.order_item
	insert into cart_load (cart_order_id,load_step_id,load_step) values(@cart_order_id,4,'usp_cart_load_insert_order_item.order_item')

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) order_item_license - existing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) insert order_item_license
	insert into order_item_license (order_item_id, license_id)
	select i.order_item_id, l.license_id
	from order_item i
	inner join cart_order_item c
		on i.line_item = c.line_item and i.product_id = c.product_id
	inner join cart_order_item_license cl
		on c.cart_order_item_id = cl.cart_order_item_id
	inner join license l
		on cl.keycode = l.keycode
	left join order_item_license oil
		on oil.license_id = l.license_id and oil.order_item_id = i.order_item_id
	where i.order_header_id = @order_header_id and c.cart_order_id = @cart_order_id and oil.order_item_license_id is null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) order_item_license - new
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_category_id tinyint

	declare @order_item_license table (item_license_id int identity(1,1), order_item_id int, license_id int, product_id int, product_type_id int, product_line_id int, license_keycode_type_id int, quantity int, item_bundle_id int, effective_date datetime, capability_expiration_date datetime, order_item_update_type_id tinyint, license_category_id int, license_attribute_license_value int)

	-- 4.1) @order_item_license
	insert into @order_item_license(order_item_id, product_id, product_type_id, product_line_id, license_keycode_type_id, quantity, item_bundle_id, effective_date, capability_expiration_date, order_item_update_type_id, license_category_id,license_attribute_license_value)
	select i.order_item_id, i.product_id, p.product_type_id, pl.product_line_id, p.license_keycode_type_id, i.quantity, i.item_bundle_id, i.effective_date, i.capability_expiration_date, i.order_item_update_type_id, lc.license_category_id, v.license_attribute_license_value
	from order_item i
	inner join product p
		on i.product_id = p.product_id
	inner join product_line_product pl
		on p.product_id = pl.product_id
	inner join cart_order_header h
		on i.order_header_id = h.order_header_id
	inner join cart_order_item c
		on i.line_item = c.line_item and i.product_id = c.product_id and c.cart_order_id = h.cart_order_id
	left join license_attribute_license_value v
		on v.li
cense_attribute_license_value = c.license_attribute_license_value
	left join product_license_category lc
		on lc.product_id = p.product_id
	left join order_item_license il
		on i.order_item_id = il.order_item_id
	where i.order_header_id = @order_header_id and p.uses_keycode = 1 and il.order_item_license_id is null
	order by i.item_hierarchy_id, p.product_type_id



	-- 4.2) insert licenses
	declare @items int, @item_license_id int

	select @items = max(item_license_id), @item_license_id = 1 from @order_item_license

	while @items >= @item_license_id
		begin
		-- print @item_license_id

		select @order_item_id = order_item_id,
				@product_id = product_id,
				@product_type_id = product_type_id,
				@product_line_id = product_line_id,
				@license_keycode_type_id = license_keycode_type_id,
				@license_category_id = license_category_id,
				@quantity = quantity,
				@item_bundle_id = item_bundle_id,
				@contract_start_date = effective_date,
				@contract_end_date = capability_expiration_date,
				@order_item_update_type_id = order_item_update_type_id,
				@license_attribute_license_value = license_attribute_license_value
		from @order_item_license
		where item_license_id = @item_license_id

		if @product_line_id  not in (55,300) and @quantity > 1 and (@order_item_update_type_id is null or @order_item_update_type_id = 1)
			begin
			-- print '4.2.1 bulk'
			-- 4.2.1) bulk load
			declare @license_bulk_load table (license_bulk_load_id int)

			if @license_distribution_method_id is null
				begin
					exec usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
				end

			select @license_bulk_load_description = 'Cart order load: order_item_id '+ convert(varchar(20),@order_item_id),
					@system_user = 'cart_load',
					@license_type_id = 1

			insert into @license_bulk_load(license_bulk_load_id)
			exec usp_license_bulk_load_insert_load @license_bulk_load_description, @product_line_id, @product_id, @module_product_id, @license_distribution_method_id, @quantity, @days_override, @enterprise_seats, @license_type_id, @fixed_expiration_OEM, @license_expiration_date, @system_user

			insert into order_item_license_bulk_load(order_item_id,license_bulk_load_id)
			select @order_item_id, license_bulk_load_id
			from @license_bulk_load

			delete from @license_bulk_load

			end
		else if (@order_item_update_type_id is null or @order_item_update_type_id = 1)
			begin
			-- print '4.2.2 standard'
			-- 4.2.2) standard load
			declare @keycodes table (keycode varchar(40), item_license_id int)

				-- 4.2.2.1) @license_distribution_method_id
				if @license_distribution_method_id is null
					begin
						exec usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
					end

					select @cart_license_distribution_method_id = m.license_distribution_method_id from order_message o inner join cart_discount_license_distribution_method m on o.cart_discount_id = m.cart_discount_id where o.order_header_id = @order_header_id

					if @cart_license_distribution_method_id is not null
						begin
						select @license_distribution_method_id = @cart_license_distribution_method_id
						end

				-- 4.2.2.2) check for bundle
				-- if @product_type_id <> 1
				begin
					select @keycode = l.keycode
					from @order_item_license il
					inner join license l
						on il.license_id = l.license_id
					where il.item_bundle_id = @item_bundle_id and il.order_item_id <> @order_item_id
				end

				-- 4.2.2.3) @keycodes
				if @keycode is null
					begin
						if @license_attribute_license_value in( 12,13)
							begin
								select @contract_end_date = dateadd(mm,12,@contract_start_date) - 1
							end

						insert into @keycodes(keycode)
						exec usp_license_insert_lic
ense_service @product_id, @license_distribution_method_id, @quantity, @contract_start_date, @contract_end_date, @contract_months, @external_keycode, @order_item_id
					end
				else
					begin
						insert into @keycodes(keycode) values(@keycode)
					end

				update @keycodes set item_license_id = @item_license_id where item_license_id is null

				-- 4.2.2.4) @insert item
				update @order_item_license
				set license_id = l.license_id
				from @order_item_license il
				inner join @keycodes k
					on il.item_license_id = k.item_license_id
				inner join license l
					on k.keycode = l.keycode
				where il.item_license_id = @item_license_id

				--insert into order_item_license(order_item_id, license_id, insert_date, insert_by, modified_date, modified_by)
				--select @order_item_id, l.license_id, @insert_date, @insert_by, @insert_date, @insert_by
				--from @keycodes k
				--inner join license l
				--	on k.keycode = l.keycode

				-- delete from @keycodes
				select @keycode = null

			end -- end 4.2.2

		select @item_license_id = @item_license_id + 1

		end

		-- 4.3) insert item
		insert into order_item_license(order_item_id, license_id, insert_date, insert_by, modified_date, modified_by)
		select t.order_item_id, t.license_id, @insert_date, @insert_by, @insert_date, @insert_by
		from @order_item_license t
		left join order_item_license oil
			on oil.license_id = t.license_id and oil.order_item_id = t.order_item_id
		where t.license_id is not null and oil.order_item_license_id is null

	-- LOG: usp_cart_load_insert_order_item.order_item
	insert into cart_load (cart_order_id,load_step_id,load_step) values(@cart_order_id,5,'usp_cart_load_insert_order_item.order_item_license')

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) register license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 5.1) @customer_type_id

		-- 5.1.1) download contact
		select @customer_type_id = 5
		from cart_customer cc
		where cc.cart_order_id = @cart_order_id and cc.customer_type_id = 5

		-- 5.1.2) shipping contact/account contact
		if @customer_type_id is null
			begin
				select @customer_type_id = 2
				from cart_customer cc
				where cc.cart_order_id = @cart_order_id and cc.customer_type_id = 2
			end

		-- 5.1.3) billing contact/bill-to account contact
		if @customer_type_id is null
			begin
				select @customer_type_id = 1
				from cart_customer cc
				where cc.cart_order_id = @cart_order_id and cc.customer_type_id = 1
			end

	-- 5.2) register license
	update license
	set customer_id = co.customer_id
	from customer_order co
	inner join order_item i
		on co.order_header_id = i.order_header_id
	inner join order_item_license il
		on i.order_item_id = il.order_item_id
	inner join license l
		on il.license_id = l.license_id
	where co.order_header_id = @order_header_id and co.customer_type_id = @customer_type_id


	-- LOG: usp_cart_load_insert_order_item.order_item
	insert into cart_load (cart_order_id,load_step_id,load_step) values(@cart_order_id,6,'usp_cart_load_insert_order_item.register_license')

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.) license attribute
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @usage_price money, @currency_id tinyint, @current_bdom tinyint
	declare @license_attribute table (temp_id int ident
ity(1,1), license_id int, license_attribute_id int, license_attribute_license_value int, effective_date datetime, order_item_id int, currency_id tinyint, usage_price money, product_type_id tinyint, license_category_id tinyint)

	-- 6.1) select items with attribute value
	insert into	@license_attribute(license_id,license_attribute_id,license_attribute_license_value,effective_date,order_item_id, currency_id, usage_price, product_type_id, license_category_id)
	select il.license_id, v.license_attribute_id, v.license_attribute_license_value, effective_date = min(i.effective_date), i.order_item_id, oc.currency_id, c.usage_price, p.product_type_id, plc.license_category_id
	from order_item i
	inner join dbo.product p
		on p.product_id = i.product_id
	inner join dbo.product_license_category plc
		on plc.product_id = p.product_id
	inner join order_currency oc
		on i.order_header_id = oc.order_header_id
	inner join cart_order_item c
		on i.line_item = c.line_item and i.product_id = c.product_id
	inner join license_attribute_license_value v
		on v.license_attribute_license_value = c.license_attribute_license_value
	inner join order_item_license il
		on il.order_item_id = i.order_item_id
	where i.order_header_id = @order_header_id  and c.cart_order_id = @cart_order_id
		and p.product_type_id <= case when exists (select 1 from order_item oi inner join dbo.product p on p.product_id = oi.product_id where oi.order_header_id = @order_header_id and product_type_id = 3)
											and exists (select 1 from order_item oi inner join dbo.product p on p.product_id = oi.product_id where oi.order_header_id = @order_header_id and product_type_id <> 3)
									  then 2
									  else p.product_type_id
								 end
	group by il.license_id, v.license_attribute_id, v.license_attribute_license_value, i.order_item_id, oc.currency_id, c.usage_price, p.product_type_id, plc.license_category_id

	-- 6.2) update license_attribute_license
	select @temp_id = 1, @total_ids = max(temp_id) from @license_attribute

	while @total_ids >= @temp_id
	begin
		select @license_id = license_id, @license_attribute_id = license_attribute_id, @license_attribute_license_value = license_attribute_license_value, @effective_date = effective_date, @order_item_id = order_item_id, @currency_id = currency_id, @usage_price = usage_price, @product_type_id = product_type_id, @license_category_id = license_category_id
		from @license_attribute
		where temp_id = @temp_id

		select @current_bdom = dbo.fn_license_select_effective_object_element(@license_id,@license_category_id, 'billing_day_of_month', @effective_date)

		-- 6.2.1) update attribute and billing day of month as needed
		if @license_attribute_id = 1
			begin
				select @message_autorenewal_cycle_id = 1
			end
		else
		--Calling usp_license_update_license_attribute_license only for non-autorenewal values. This is because autorenewal status is currently set by autorenewal_flag on cart_order_header, not item-level data
			begin
				exec usp_license_update_license_attribute_license @license_id, @license_attribute_id, @license_attribute_license_value, @insert_by, @effective_date, @order_header_id, @order_item_id = @order_item_id
				select @billing_day_of_month = datepart(dd,@effective_date)
				select @message_autorenewal_cycle_id = 2
			end
        if @product_type_id <= 2 or @current_bdom is null --to prevent billing_day_of_month changes for upsells on currently owned products (SFDC allows changing billing models in upsell, will need to update it in case the BDOM is currently null)
			exec usp_license_update_license_autorenewal_cycle @license_id, @message_autorenewal_cycle_id, @billing_day_of_month, @product_type_id, @effective_date, @order_header_id, @order_item_id = @order_item_id

		select @temp_id = @temp_id + 1
		select @license_id = null, @license_attribute_id = null, @license_attribute_license_value = null, @effective_date = null, @order_item_id = null, @currency_id = null, 
@usage_price = null, @product_type_id = null, @license_category_id = null
	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.) license usage pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_usage_pricing table (id int identity (1,1), license_id int, license_attribute_license_value int, effective_date date, order_item_id int, usage_price money)
	declare @start int = 1, @rows int

	insert into @license_usage_pricing (license_id, license_attribute_license_value, effective_date, order_item_id, usage_price)
	select oil.license_id, coi.license_attribute_license_value, oi.effective_date, oi.order_item_id, coi.usage_price
	from order_item oi
	inner join order_currency oc on oi.order_header_id = oc.order_header_id
	inner join cart_order_item coi on oi.line_item = coi.line_item and oi.product_id = coi.product_id
	inner join order_item_license oil on oil.order_item_id = oi.order_item_id
	where oi.order_header_id = @order_header_id
	and coi.cart_order_id = @cart_order_id

	select @rows = @@ROWCOUNT

	while @start <= @rows
	begin

		select @license_id = license_id, @license_attribute_license_value = license_attribute_license_value, @contract_start_date = effective_date, @order_item_id = order_item_id, @usage_price = usage_price
		from @license_usage_pricing
		where id = @start

		if @license_attribute_license_value in (11,12,13) and @usage_price is not null
			exec usp_license_insert_license_usage_pricing @license_id, @order_item_id, @contract_start_date, @usage_price

		select @start = @start + 1
		select @license_id = null, @license_attribute_license_value = null, @contract_start_date = null, @order_item_id = null, @usage_price = null

	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8.) cart_load
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- LOG: usp_cart_load_insert_order_item.license_attribute
	insert into cart_load (cart_order_id,load_step_id,load_step) values(@cart_order_id,7,'usp_cart_load_insert_order_item.license_attribute')


	---------------------------------------------------------------------------------------------------------------------------
	-- 9.) Identify the MSP License
	---------------------------------------------------------------------------------------------------------------------------------
	declare @msp_license table(id int identity(1,1), license_id int, license_category_id tinyint, license_distribution_method_code varchar(5), effective_start_date date, order_item_id INT,msp_flag int)
	declare @count int=1

	insert into @msp_license
	(
	    license_id,
	    license_category_id,
	    license_distribution_method_code,
	    effective_start_date,
	    order_item_id,
		msp_flag
	)
	select ol.license_id,pm.license_category_id,dm.license_distribution_method_code,convert(date,oi.effective_date),oi.order_item_id,
	case when sap_material_description like '%msp%' then 1 else 0 end as msp_flag
	from order_item oi
	inner join dbo.order_item_license ol
	on ol.order_item_id = oi.order_item_id
	inner join license lc
	on lc.license_id = ol.license_id
	inner join dbo.sap_material_product_mapping pm
	on pm.sap_material_number=oi.sap_material_number
	inner join dbo.license_distribution_method dm
	on dm.license_distribution_method_id = lc.license_distribution_method_id
	where oi.order_header_id=@order_header_id
	
	
set @rows= @@ROWCOUNT
	while @count <= @rows
	BEGIN

	
		select @license_distribution_method_code= license_distribution_method_code,
			   @license_id=license_id,
			   @license_category_id=license_category_id,
			   @effective_date=effective_start_date,
			   @order_item_id=order_item_id,
			   @msp_flag=msp_flag
		from @msp_license 
		where id=@count
		if @license_distribution_method_code <>'NSBF'
		begin
			
		
					select @license_effective_object_json = (select license_id = @license_id, license_category_id = @license_category_id, 
																	msp_flag=@msp_flag , effective_start_date = @effective_date ,order_item_id = @order_item_id
																	 for json path)
																 	
					exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_cart_load_insert_order_item'

		END
      
	  select @count = @count + 1
		

	 end
    
	---------------------------------------------------------------------------------------------------------------------------
	-- 10.0) Insert the usage pricing model and amend_upsell order for carb products
	---------------------------------------------------------------------------------------------------------------------------------
		--select the order_opportunity_type_id from the order_opportunity table

	select @order_opportunity_type_id=order_opportunity_type_id
	from dbo.order_opportunity
	where order_header_id=@order_header_id

	--to extract the amended_contract from the item_json to identify whether it's an amend upsell order or not
	;with cte
	as
	(
		select cart_order_id,lc.license_category_id,js.license_Category_name,js.amend_upsell_order
		from cart_order_item ci
		inner join dbo.cart_order_item_json it
		on it.cart_order_item_id = ci.cart_order_item_id 
		cross apply openjson(cart_order_item_json) 
		with
		(
		license_Category_name varchar(10) '$.license_category_name',
		amend_upsell_order VARCHAR(18) '$.amended_contract'
		)js
		inner join dbo.license_category lc
		on lc.license_category_name = js.license_category_name
		where cart_order_id=@cart_order_id
	)
    
	--Mark the amend_upsell_order as True if order_opportunity_type_id and amended_contract are not null			
	select @license_effective_object_json = 
		(	
			select license_id				= license_id,
					license_category_id		= pm.license_category_id,
					effective_start_date	= oi.effective_date,
					order_item_id			= oi.order_item_id,		
					usage_pricing_model_id	= JSON_VALUE(js.product_extension_json,'$.usage_pricing_model_id'),
					amend_upsell_order		= CASE WHEN @order_opportunity_type_id IS NOT NULL AND ct.amend_upsell_order IS NOT NULL														 
												   THEN 1 END
			from  order_item oi
			inner join order_item_license ol
			on ol.order_item_id = oi.order_item_id
			inner join dbo.cart_order_header coh
			ON coh.order_header_id = oi.order_header_id
			inner join dbo.cart_order_item coi
			on coi.cart_order_id = coh.cart_order_id
			and oi.line_item = coi.line_item
			inner join dbo.sap_material_product_mapping pm
			on pm.sap_material_number = oi.sap_material_number
			left join dbo.sap_material_product_json js
			on js.sap_material_product_mapping_id = pm.sap_material_product_mapping_id
			left join cte ct
			on ct.cart_order_id = coh.cart_order_id
			and ct.license_category_id = pm.license_category_id
			where coi.cart_order_id = @cart_order_id
			and oi.order_header_id = @order_header_id
			for json path	
		)
				

		if @license_effective_object_json is not null
		begin
															 	
			exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_cart_load_insert_order_item'

		end


--ends	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
						
	else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_load_order]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_load_order]
(
    @cart_order_id INT,
    @autorenewal_flag INT = NULL,
    @download_instruction_type_id TINYINT = NULL,
    @license_distribution_method_code VARCHAR(4) = NULL,
    @return_result BIT = NULL
)
AS
/*    
    DATE        AUTHOR        REMARKS
    2014-04-21    esmart        Initial creation.    
    2015-04-09    acoffel        added @download_instruction_type_id
    2016-07-24    cnovac        added @return_result to make the return an optional item
    2017-08-23    esmart        remove prints
    2019-06-21    esmart        Re-order first two steps. Add cart_load logging.
    2024-04-24    pachanta    ECOM-3883 When SkyRise is offline, ecom keycode genertion should use distribution_method_code override 
    2024-09-10    kkumari3    Added Condition to restrict the repetation of steps on cart_load if cart_order is already in progress.
    2025-02-25	  spatil6     Modified condition 1.1 to process cleverbridge renewal which was coming with same cart order id ECOM-4427987.


    DESCRIPTION
    load order
    DEPENDENCIES
    This Procedure is invoked from PHP.
*/

SET NOCOUNT ON;

DECLARE @order_header_id INT,
        @cart_order_status_id INT,
        @response_code INT,
        @message VARCHAR(100);

BEGIN TRY

    DECLARE @CB_CART TABLE
    (
        site_id VARCHAR(10)
    );

    INSERT INTO @CB_CART
    (
        site_id
    )

    --get value from app_config table
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('CART_SITES', 'CLEVERBRIDGE') f;


    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT @cart_order_status_id = cart_order_status_id
    FROM cart_order
    WHERE cart_order_id = @cart_order_id;

    IF @cart_order_status_id = 2
    BEGIN
        SELECT response_code = -110,
               message = 'Order already loaded';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.cart_load AS cl
            INNER JOIN dbo.cart_order AS co
                ON co.cart_order_id = cl.cart_order_id
            LEFT JOIN @CB_CART AS cc
                ON co.site_id = cc.site_id
        WHERE cl.cart_order_id = @cart_order_id
              AND cc.site_id IS NULL
    )
    BEGIN

        SELECT response_code = -110,
               message = 'Order still in-progress';
        RETURN;

    END;

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) load
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    INSERT INTO cart_load
    (
        cart_order_id,
        load_step_id,
        load_step
    )
    VALUES
    (@cart_order_id, 0, 'load_initiation');

    -- 2.1) header
    EXEC usp_cart_load_insert_header @cart_order_id,
                                     @autorenewal_flag,
                                     @download_instruction_type_id,
                                     @order_header_id OUTPUT;
    INSERT INTO cart_load
    (
        cart_order_id,
        load_step_id,
        load_step
    )
    VALUES
    (@cart_orde
r_id, 1, 'usp_cart_load_insert_header');

    -- 2.2) customer
    EXEC [usp_cart_load_insert_customer] @cart_order_id;
    INSERT INTO cart_load
    (
        cart_order_id,
        load_step_id,
        load_step
    )
    VALUES
    (@cart_order_id, 2, 'usp_cart_load_insert_customer');

    -- 2.3) order customer
    EXEC usp_cart_load_insert_order_customer @cart_order_id;
    INSERT INTO cart_load
    (
        cart_order_id,
        load_step_id,
        load_step
    )
    VALUES
    (@cart_order_id, 3, 'usp_cart_load_insert_order_customer');

    -- 2.4) item
    EXEC usp_cart_load_insert_order_item @cart_order_id,
                                         @license_distribution_method_code;
    -- insert into cart_load (cart_order_id,load_step_id,load_step) values(@cart_order_id,4,'usp_cart_load_insert_order_item') - Broken out within the sub procedure

    -- 2.5) finalize
    EXEC usp_cart_load_finalize_order @cart_order_id;
    INSERT INTO cart_load
    (
        cart_order_id,
        load_step_id,
        load_step
    )
    VALUES
    (@cart_order_id, 8, 'usp_cart_load_finalize_order');

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) return
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF ISNULL(@return_result, 1) = 1
        SELECT order_header_id = @order_header_id;

END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_refund_full]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_refund_full]

(
        @order_header_id int,
		@order_status_id int,
		@refund_reason_code int,
		@comment varchar(8000),
		@csi_user_id varchar(50)
)

/*	
	DATE		AUTHO1R		REMARKS
	2009-03-10	esmart		Initial creation.
	2010-05-20	esmart		Add opt-out autorenewal update to license_attribute_license
	2014-09-18	esmart		Set autorenewal to opt out for all refunds
	2015-02-06	esmart		Fix duplicate order_item_license rows on the refund
	2017-02-13	bennylu		Standardize refund.
	2018-08-10	cnovac		Changed how usp_license_update_license_attribute_license is called
	2019-04-11	cnovac		Took out rollback which referenced a transaction that didn't exist in catch part of code
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2019-09-20	abelenkiy	Added logic to prevent duplicate inserts to order_item_license (section 2.2)
	2020-04-01	wbarton		Removing what was previously section 4 - update license attribute. Moving that logic to usp_cart_refund_order_license. 

	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @max_line_item int,
			@customer_id int,
			@current_license_attribute_license type_license_attribute_license_history,
			@modified_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

	declare @temp_id int, 
			@total_ids int, 
			@license_id int, 
			@license_attribute_id int, 
			@license_attribute_license_value int, 
			@modified_by varchar(20), 
			@effective_date datetime,
			@vendor_order_code varchar(100),
			@order_item_id int


begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update order header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.2) insert order_history
	insert into order_history (order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, history_by)
	select order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id = 3, insert_date, insert_by, modified_date, modified_by, @csi_user_id
	from order_header
	where order_header_id = @order_header_id	

	-- 1.3) update order header
	update order_header 
	set total_amount = 0, 
		sub_total_amount = 0, 
		tax_total = 0, 
		order_status_id = @order_status_id, 
		modified_date = @modified_date, 
		modified_by = @csi_user_id
	where order_header_id = @order_header_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) order_item
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert refund order_item rows
	insert into order_item (order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, capability_expiration_date, insert_by, insert_date, modifie
d_by, modified_date)
	select order_header_id,
		line_item,-- = line_item+@max_line_item,
		product_id,
		quantity,
		(list_price*-1) as list_price,
		(unit_price*-1) as unit_price,
		(tax*-1) as tax,
		order_item_offer_id,
		order_item_offer_amount,
		(item_total*-1) as item_total,
		tax_exempt,
		effective_date = effective_date,
		order_item_status_id = @order_status_id,
		capability_expiration_date,
		insert_by = @csi_user_id,
		insert_date = @modified_date,
		modified_by = @csi_user_id,
		modified_date = @modified_date
	from order_item 
	where order_header_id = @order_header_id
	order by order_item_id

	-- 2.2) insert order_item_license records for refund line items
    insert into order_item_license (order_item_id, license_id, insert_by, modified_by)
    select ir.order_item_id, l.license_id, insert_by = @csi_user_id, modified_by = @csi_user_id
    from order_item i
    inner join order_item_license l
            on i.order_item_id = l.order_item_id
    inner join order_item ir
            on i.line_item = ir.line_item and ir.order_item_status_id = @order_status_id
    left join order_item_license lr
            on ir.order_item_id = lr.order_item_id and l.license_id = lr.license_id
    where i.order_header_id = @order_header_id and ir.order_header_id = @order_header_id and lr.order_item_license_id is null
    order by ir.line_item

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert refund reason
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @refund_license table (temp_id int identity(1,1), license_id int, order_item_id int)

	-- 3.1) @customer_id
	select @customer_id = customer_id
	from customer_order
	where order_header_id = @order_header_id and customer_type_id = 1

	-- 3.2) @refund_license
	insert into @refund_license (license_id, order_item_id)
	select distinct il.license_id, i.order_item_id
	from order_item i
	inner join product p
		on i.product_id = p.product_id
	inner join order_item_license il
		on i.order_item_id = il.order_item_id
	where i.order_header_id = @order_header_id and i.order_item_status_id = @order_status_id

	-- 3.3) csi_comments
	insert into csi_comments (subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id, refund_reason_code, csi_users_id)
	select subject = 
				case
					when @order_status_id = 3 then 'Refund Reason: '
					else 'Submission Failure: '
				end, 
			comment = 
				case 
					when @order_status_id = 4 then @comment
					when @comment is null or @comment = '' then r.description
					else @comment 
				end, 
			insert_date = @modified_date, 
			insert_by = @csi_user_id, 
			customer_id = @customer_id, 
			invoice_id = @order_header_id, 
			l.license_id, 
			r.refund_reason_code, 
			@csi_user_id
	from lu_refund_reasons r
	left join @refund_license l
		on r.refund_reason_code = r.refund_reason_code
	where refund_reason_code = @refund_reason_code 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) usp_cart_refund_order_license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @vendor_order_code = v.vendor_order_code
	from vendor_order v
	inner join order_header h
		on h.vendor_order_id = v.vendor_order_id
	where h.order_header_id = @order_header_id

	exec usp_cart_refund_order_license @vendor_order_code
	

end try
begin catch

	set @
response_code = -200
	set @message = case when @message is null then 'Could not update licenses for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_refund_order_license]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_refund_order_license]
(@vendor_order_code VARCHAR(100))
/*   
DATE  AUTHOR  REMARKS  
2018-07-23 esmart		Initial creation.  
2018-10-29 cnovac		Added call to sky_update for WIFI license  
2018-11-01 cnovac		Took out references to effective columns in license_seats  
2019-04-03 cnovac		Added code to start writing to license contract object  
2019-06-27 cnovac		Updated logic that populates license contract object for child licenses  
2019-09-06 cnovac		Updated how effective object is populated using license contract as baseline  
2020-04-01 wbarton		Adding section 8 to handle autorenewal status maintenance. Also minor change in 3.1.2 for edge-cases where original_storage_gb is null.  
2021-02-04 jberry		SAP RMA support  
2022-10-01 abelenkiy	Hotfix to correct license management during refund; removed join to sap_order_item_rma in Section 1.2 (which reverted procedure to pre-integration state)  
2023-10-31 aprasad2		Capability to terminate the active SAP contracts in REFUND cases with proc usp_sap_update_sap_order_status  
2025-07-16 vgangatharan Modified existing refund logic to handle multiple renewal and refund.
DESCRIPTION  
*/
AS
SET NOCOUNT ON;
SET ANSI_WARNINGS OFF;

BEGIN TRY
    DECLARE @order_header_id INT,
            @order_partner_id INT,
            @order_partner_license_id INT,
            @order_entity_approval VARCHAR(500),
            @license_transaction VARCHAR(MAX),
            @temp_id INT,
            @total_ids INT,
            @license_id INT,
            @license_attribute_id INT,
            @license_attribute_license_value INT,
            @partner_license_source_id TINYINT,
            @comment NVARCHAR(MAX),
            @partner_license_id INT,
            @history_date DATETIME,
            @history_by VARCHAR(20),
            @update_license TINYINT = 1,
            @temp_child_id INT,
            @total_child_ids INT,
            @child_license_id INT,
            @parent_license_id INT,
            @license_effective_object_json VARCHAR(MAX),
            @license_contract_json VARCHAR(MAX),
            @response_code INT,
            @message VARCHAR(100);

    SELECT @history_date = GETDATE(),
           @history_by = 'refund_update';

    SELECT @response_code = 0,
           @message = 'Success';

    DECLARE @order_item TABLE
    (
        order_item_id INT,
        order_header_id INT,
        line_item INT,
        product_id INT,
        product_type_id INT,
        quantity INT,
        effective_date DATETIME,
        new_capability_type_id INT,
        new_capability_type_description VARCHAR(20),
        capability_type_description VARCHAR(20),
        capability_expiration_date DATETIME,
        item_bundle_id INT,
        order_item_update_type_id TINYINT,
        item_hierarchy_id TINYINT,
        license_id INT,
        license_change_reason_id INT,
        start_date DATETIME,
        license_partner_id INT,
        partner_license_status_id TINYINT,
        license_module_id TINYINT,
        license_module_type_id TINYINT,
        license_module_type_name VARCHAR(50),
        new_license_module_type_name VARCHAR(50),
        original_license_category_id TINYINT,
        original_license_seats INT,
        original_storage_gb INT,
        original_capability_type_id INT,
        original_license_module_type_id TINYINT
    );
    DECLARE @parent_license_table TABLE
    (
        license_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        categor
y_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        license_status_id INT
    );
    DECLARE @child_license_table TABLE
    (
        order_action VARCHAR(50),
        new_expiration_date DATETIME,
        new_category_type_name VARCHAR(50),
        license_change_reason_id INT,
        order_item_id INT,
        parent_license_id INT,
        license_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        license_status_id INT,
        effective_date DATE
    );
    DECLARE @child_licenses TABLE
    (
        temp_child_id INT IDENTITY(1, 1),
        parent_license_id INT,
        child_license_id INT
    );
    DECLARE @license_contract_object TABLE
    (
        license_id INT,
        license_category_id TINYINT,
        license_category_type_id INT,
        license_start_date DATE,
        license_end_date DATE,
        license_seats INT,
        order_item_id INT,
        product_type_id INT,
        license_contract_original_order_header_id INT,
        license_contract_refunded_order_header_id INT
    );
    DECLARE @refund_license_attribute TABLE
    (
        temp_id INT IDENTITY(1, 1),
        license_id INT,
        license_attribute_id INT,
        license_attribute_license_value INT
    );

    DECLARE @max_capability_expiration TABLE
    (
        license_id INT,
        capability_expiration_date DATETIME
    );


    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 1.) select order_item  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 1.1) @order_header_id  
    SELECT @order_header_id = h.order_header_id
    FROM order_header h
        INNER JOIN vendor_order v
            ON v.vendor_order_id = h.vendor_order_id
    WHERE v.vendor_order_code = @vendor_order_code;

    -- 1.2) @order_item  
    INSERT INTO @order_item
    (
        order_item_id,
        order_header_id,
        line_item,
        product_id,
        product_type_id,
        quantity,
        effective_date,
        capability_expiration_date,
        new_capability_type_id,
        new_capability_type_description,
        item_bundle_id,
        order_item_update_type_id,
        item_hierarchy_id,
        license_id,
        original_license_category_id
    )
    OUTPUT Inserted.license_id,
           Inserted.original_license_category_id,
           Inserted.new_capability_type_id,
           Inserted.effective_date,
           Inserted.capability_expiration_date,
           Inserted.order_item_id,
           Inserted.product_type_id,
           Inserted.order_header_id
    INTO @license_contract_object
    (
        license_id,
        license_category_id,
        license_category_type_id,
        license_start_date,
        license_end_date,
        order_item_id,
        product_type_id,
        license_contract_refunded_order_header_id
    )
    SELECT i.order_item_id,
           i.order_header_id,
           i.line_item,
           i.product_id,
           p.product_type_id,
           i.quantity,
           i.effective_date,
           i.capability_expiration_date,
           pc.capability_type_id,
           ct.capability_type_description,
           i.item_bundle_id,
           i.order_item_update_type_id,
           i.item_hierarchy_id,
           il.license_id,
           plc.license_category_id
    FROM order_item i
        INNER JOIN product p
            ON p.product_id =
 i.product_id
        LEFT JOIN product_license_category plc
            ON plc.product_id = i.product_id
        LEFT JOIN license_category lc
            ON lc.license_category_id = plc.license_category_id
        LEFT JOIN product_capability pc
            ON pc.product_id = p.product_id
               AND pc.capability_id = lc.base_capability_id
        LEFT JOIN capability_type ct
            ON ct.capability_type_id = pc.capability_type_id
        INNER JOIN order_item_license il
            ON il.order_item_id = i.order_item_id
    WHERE i.order_header_id = @order_header_id
          AND i.order_item_status_id = 1;

    -- 1.3) capability_type_description  
    UPDATE @order_item
    SET capability_type_description = t.capability_type_description
    FROM @order_item i
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
        INNER JOIN license_category c
            ON c.license_category_id = cl.license_category_id
        INNER JOIN license_capability lc
            ON lc.license_id = i.license_id
               AND lc.capability_id = c.base_capability_id
        INNER JOIN capability_type t
            ON t.capability_type_id = lc.capability_type_id;

    -- 1.4) set license module  
    UPDATE @order_item
    SET license_module_id = lm.license_module_id,
        license_module_type_id = mt.license_module_type_id,
        license_module_type_name = mlt.license_module_type_name,
        new_license_module_type_name = mt.license_module_type_name
    FROM @order_item i
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_module_category lmc
            ON lmc.license_category_id = plc.license_category_id
        INNER JOIN license_module lm
            ON lm.license_module_id = lmc.license_module_id
               AND lm.license_module_class_id = 3 -- parent  
        INNER JOIN license_module_type mt
            ON i.new_capability_type_description = mt.license_module_type_name
        LEFT JOIN license_module_license ml
            ON ml.license_id = i.license_id
               AND ml.license_module_id = lm.license_module_id
        LEFT JOIN license_module_type mlt
            ON mlt.license_module_type_id = ml.license_module_type_id
    WHERE i.item_hierarchy_id = 2;

    -- 1.5) set license_change_reason  
    UPDATE @order_item
    SET license_change_reason_id = CASE
                                       WHEN product_type_id = 1 THEN
                                           8
                                       WHEN product_type_id = 2 THEN
                                           9
                                       WHEN product_type_id = 3 THEN
                                           10
                                   END;


    -- select '@order_item - pre 1.6', * from @order_item  
    -- 1.6) start and end date  
    -- 1.6.1) update capability_expiration_date  

    -- get max capability_expiration_date  

    INSERT INTO @max_capability_expiration
    (
        license_id,
        capability_expiration_date
    )
    SELECT lc.license_id,
           MAX(lc.capability_expiration_date) AS capability_expiration_date
    FROM dbo.license_capability lc
        JOIN @order_item oi
            ON lc.license_id = oi.license_id
    WHERE oi.order_header_id = @order_header_id
    GROUP BY lc.license_id;

    -- update capability_expiration_date for the refund

    UPDATE @order_item
    SET capability_expiration_date = CASE
                                         -- Case 1: If days_remaining is negative
                                         WHEN c.days_remaining < 0 THEN
                                             CASE
                                                 WHEN DATEADD(dd,-(c.days_remaining + c.days_added),ce.capability_expiration_date) < @history_date THEN
                               
                      @history_date
                                                 ELSE
                                                     DATEADD(dd,-(c.days_remaining + c.days_added),ce.capability_expiration_date)
                                             END

                                         -- Case 2: Normal logic when days_remaining is not negative
                                         ELSE
                                             CASE
                                                 WHEN DATEADD(dd, -c.days_added, ce.capability_expiration_date) < @history_date THEN
                                                     @history_date
                                                 ELSE
                                                     DATEADD(dd, -c.days_added, ce.capability_expiration_date)
                                             END
                                     END,
        original_capability_type_id = c.capability_type_id
    FROM @order_item i
        INNER JOIN @max_capability_expiration ce
            ON ce.license_id = i.license_id
        INNER JOIN license_capability_history c
            ON c.license_id = i.license_id
               AND c.order_item_id = i.order_item_id
    WHERE c.capability_id = 2
          AND i.item_hierarchy_id = 1;


    -- 1.6.2) new  
    UPDATE @order_item
    SET capability_expiration_date = i.effective_date
    FROM @order_item i
        LEFT JOIN license_capability_history c
            ON c.license_id = i.license_id
               AND c.order_item_id = i.order_item_id
    WHERE c.license_capability_history_id IS NULL
          AND i.item_hierarchy_id = 1;

    -- 1.6.4) module products  
    UPDATE @order_item
    SET original_license_module_type_id = h.license_module_type_id,
        original_license_seats = h.module_seats,
        capability_expiration_date = CASE
                                         WHEN i.product_type_id = 3 THEN
                                             i.capability_expiration_date
                                         WHEN i.product_type_id IN ( 1, 2 )
                                              AND DATEADD(
                                                             dd,
                                                             -DATEDIFF(
                                                                          dd,
                                                                          i.effective_date,
                                                                          i.capability_expiration_date
                                                                      ),
                                                             i.capability_expiration_date
                                                         ) > @history_date THEN
                                             DATEADD(
                                                        dd,
                                                        -DATEDIFF(dd, i.effective_date, i.capability_expiration_date),
                                                        i.capability_expiration_date
                                                    )
                                         WHEN i.product_type_id IN ( 1, 2 )
                                              AND DATEADD(
                                                             dd,
                                                             -DATEDIFF(
                                                                          dd,
                                                                          i.effective_date,
                                                                          i.capability_expiration_date
                                                                      ),
                                                             i.capability_expiration_date
                                       
                  ) <= @history_date THEN
                                             @history_date
                                     END
    FROM @order_item i
        INNER JOIN license_module_license_history h
            ON h.license_id = i.license_id
               AND h.order_item_id = i.order_item_id
    WHERE i.item_hierarchy_id = 2;

    -- 1.6.4) module products  
    UPDATE @order_item
    SET capability_expiration_date = i.effective_date,
        original_license_seats = 0,
        original_license_module_type_id = 19
    FROM @order_item i
        LEFT JOIN license_module_license_history h
            ON h.license_id = i.license_id
               AND h.order_item_id = i.order_item_id
    WHERE h.license_module_license_history_id IS NULL
          AND i.item_hierarchy_id = 2;

    -- 1.6.3) update start_date  
    UPDATE @order_item
    SET start_date = CASE
                         WHEN capability_expiration_date > @history_date THEN
                             @history_date
                         ELSE
                             capability_expiration_date
                     END,
        effective_date = CASE
                             WHEN capability_expiration_date > @history_date THEN
                                 @history_date
                             ELSE
                                 capability_expiration_date
                         END
    FROM @order_item;

    -- 1.7) update original_license_category_id  
    UPDATE @order_item
    SET original_license_category_id = cl.license_category_id
    FROM @order_item i
        INNER JOIN license_category_license_history cl
            ON cl.license_id = i.license_id
               AND cl.order_item_id = i.order_item_id
    WHERE i.item_hierarchy_id = 1;

    -- 1.7.1) new  
    UPDATE @order_item
    SET original_license_category_id = plc.license_category_id
    FROM @order_item i
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
    WHERE i.item_hierarchy_id = 1
          AND i.original_license_category_id IS NULL;

    -- 1.8) update original_license_seats  
    UPDATE @order_item
    SET original_license_seats = s.license_seats
    FROM @order_item i
        INNER JOIN license_seat_history s
            ON s.license_id = i.license_id
               AND s.order_item_id = i.order_item_id
    WHERE i.item_hierarchy_id = 1;

    -- 1.8.1) new  
    UPDATE @order_item
    SET original_license_seats = CASE
                                     WHEN pl.product_line_id IN ( 300, 55 ) THEN
                                         i.quantity
                                     ELSE
                                         s.seats
                                 END
    FROM @order_item i
        INNER JOIN product_line_product pl
            ON pl.product_id = i.product_id
        INNER JOIN product_seat s
            ON s.product_id = i.product_id
    WHERE i.item_hierarchy_id = 1
          AND i.original_license_seats IS NULL;

    -- 1.8) update original_storage_gb  
    UPDATE @order_item
    SET original_storage_gb = s.storage_gb
    FROM @order_item i
        INNER JOIN license_storage_history s
            ON s.license_id = i.license_id
               AND s.order_item_id = i.order_item_id
    WHERE i.item_hierarchy_id = 1;

    -- 1.8.1) new  
    UPDATE @order_item
    SET original_storage_gb = s.storage_gb
    FROM @order_item i
        INNER JOIN product_storage s
            ON s.product_id = i.product_id
    WHERE i.item_hierarchy_id = 1
          AND i.original_storage_gb IS NULL;

    --select '@order_item - post 1.6', * from @order_item  
    --return  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 2.) child licenses  
    -------------------------------------
------------------------------------------------------------------------------------------------------------------------------  
    -- 2.7) @child_license_table  
    INSERT INTO @child_licenses
    (
        parent_license_id,
        child_license_id
    )
    SELECT parent_license_id,
           child_license_id
    FROM license_parent
    WHERE parent_license_id IN
          (
              SELECT license_id FROM @order_item
          );

    SELECT @temp_child_id = 1,
           @total_child_ids = MAX(temp_child_id)
    FROM @child_licenses;

    WHILE @total_child_ids >= @temp_child_id
    BEGIN
        SELECT @child_license_id = child_license_id,
               @parent_license_id = parent_license_id
        FROM @child_licenses
        WHERE temp_child_id = @temp_child_id;

        INSERT @child_license_table
        (
            parent_license_id,
            license_id,
            license_category_name,
            license_seats,
            storage_gb,
            license_keycode_type_id,
            license_attribute_license_value,
            start_date,
            expiration_date,
            category_type_name,
            item_hierarchy_id,
            license_status_id
        )
        SELECT @parent_license_id,
               license_id,
               license_category_name,
               license_seats,
               storage_gb,
               license_keycode_type_id,
               license_attribute_license_value,
               start_date,
               expiration_date,
               category_type_name,
               item_hierarchy_id,
               license_status_id
        FROM dbo.fn_license_select_license_profile(@child_license_id)
        WHERE license_status_id = 1;

        SELECT @temp_child_id = @temp_child_id + 1;
    END;

    INSERT @parent_license_table
    (
        license_id,
        license_category_name,
        license_seats,
        storage_gb,
        license_keycode_type_id,
        license_attribute_license_value,
        start_date,
        expiration_date,
        category_type_name,
        item_hierarchy_id,
        license_status_id
    )
    SELECT license_id,
           license_category_name,
           license_seats,
           storage_gb,
           license_keycode_type_id,
           license_attribute_license_value,
           start_date,
           expiration_date,
           category_type_name,
           item_hierarchy_id,
           license_status_id
    FROM dbo.fn_license_select_license_profile(@parent_license_id);

    -- select '@child_license_table', * from @child_license_table  
    -- 2.8) determin action for child licenses  
    UPDATE c
    SET c.order_action = CASE
                             --when i.license_change_reason_id = 8 and p.category_type_name = 'trial' and cp.category_type_name = 'trial' and p.item_hierarchy_id = 1 then 'convert_primary_site'  
                             --when i.license_change_reason_id = 8 and p.category_type_name = 'trial' and p.category_type_name = 'trial' and p.item_hierarchy_id = 2 and (cp.category_type_name = 'full' or pp.category_type_name = 'trial') then 'convert_secondary_site'  
                             WHEN i.license_change_reason_id = 8
                                  AND p.category_type_name = 'full'
                                  AND c.category_type_name = 'full' THEN
                                 'refund new'
                             WHEN i.license_change_reason_id = 9
                                  AND p.category_type_name = 'full'
                                  AND c.category_type_name = 'full' THEN
                                 'refund renew'
                             WHEN i.license_change_reason_id = 10
                                  AND p.category_type_name = 'full'
                                  AND c.category_type_name = 'full' THEN
                              
   'refund upgrade'
                         END,
        c.new_expiration_date = i.capability_expiration_date,
        c.new_category_type_name = i.new_capability_type_description,
        c.start_date = i.start_date,
        c.license_change_reason_id = i.license_change_reason_id,
        c.order_item_id = i.order_item_id
    FROM @parent_license_table p
        INNER JOIN @child_license_table c
            ON p.license_category_name = c.license_category_name
        INNER JOIN @child_license_table cp
            ON cp.license_id = c.license_id
               AND cp.item_hierarchy_id = 1
        LEFT JOIN @parent_license_table pp
            ON pp.license_id = p.license_id
               AND pp.item_hierarchy_id = 1
        INNER JOIN @order_item i
            ON p.license_id = i.license_id
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_category lc
            ON lc.license_category_id = plc.license_category_id
               AND c.license_category_name = lc.license_category_name
    WHERE i.license_change_reason_id IN ( 8, 9, 10 )
          AND i.order_item_update_type_id = 1;

    -- select '@child_license_table', * from @child_license_table --where order_action is not null  
    -- select '@order_item', * from @order_item  
    --return  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 3.) update license  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 3.0) license  
    INSERT INTO license_history
    (
        license_id,
        keycode,
        customer_id,
        product_line_id,
        license_status_id,
        license_type_id,
        license_distribution_method_id,
        license_keycode_type_id,
        max_daily_activations,
        max_child_licenses,
        license_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT DISTINCT
           l.license_id,
           l.keycode,
           l.customer_id,
           l.product_line_id,
           l.license_status_id,
           l.license_type_id,
           l.license_distribution_method_id,
           l.license_keycode_type_id,
           l.max_daily_activations,
           l.max_child_licenses,
           l.license_expiration_date,
           l.insert_date,
           l.insert_by,
           l.modified_date,
           l.modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM license l
        INNER JOIN @order_item i
            ON i.license_id = l.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND l.license_status_id <> 1;

    UPDATE license
    SET license_status_id = 1,
        modified_date = @history_date,
        modified_by = @history_by
    FROM license l
        INNER JOIN @order_item i
            ON i.license_id = l.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND l.license_status_id <> 1;

    -- 3.1) license_category_license  
    -- 3.1.1) license_category_license_history  
    INSERT INTO license_category_license_history
    (
        license_category_license_id,
        license_id,
        license_category_id,
        start_date,
        end_date,
        order_item_id,
        last_modified_date,
        last_modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
         
  cl.start_date,
           end_date = i.start_date,
           i.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM @order_item i
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
           start_date = CASE
                            WHEN i2.start_date IS NOT NULL THEN
                                i2.start_date
                            ELSE
                                cl.start_date
                        END,
           end_date = CASE
                          WHEN i2.start_date IS NOT NULL THEN
                              i2.start_date
                          ELSE
                              i.start_date
                      END,
           i.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM @order_item i
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
        LEFT JOIN @order_item i2
            ON i2.item_hierarchy_id = i.item_hierarchy_id
               AND i2.product_type_id = 3
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id = 8
              )
          );

    -- 3.1.2) update license_category_license  
    UPDATE license_category_license
    SET license_category_id = x.original_license_category_id,
        start_date = x.start_date,
        end_date = x.end_date,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM
    (
        SELECT license_id,
               item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               license_category_id = MAX(plc.license_category_id),
               original_license_category_id = MIN(i.original_license_category_id)
        FROM @order_item i
            INNER JOIN product_license_category plc
                ON plc.product_id = i.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 8
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id
    ) x
        INNER JOIN license_category_license cl
            ON cl.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1;

    -- 3.2) license_capability  
    -- 3.2.1) license_capability_history  
    INSERT INTO license_capability_history
    (
        license_capability_id,
        license_id,
        capability_id,
        capability_type_id,
        capability_activation_days,
        capability_activation_date,
        capability_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        capability_change_reason_id,
        history_date,
        history_by,
        order_item_id,
        days_used,
        days_remaining,
        days_added,
        days_new
    )
    SELECT license_capability_id,
           license_id,
           capability_id,
           capability_type_id,
           capability_activation_days = DATEDIFF(dd, x.capability_a
ctivation_date, x.capability_expiration_date),
           capability_activation_date,
           capability_expiration_date,
           insert_date,
           insert_by,
           modified_date,
           modified_by,
           x.license_change_reason_id,
           history_date,
           history_by,
           order_item_id,
           x.days_used,
           x.days_remaining,
           x.days_added,
           x.days_new
    FROM
    (
        SELECT c.license_capability_id,
               c.license_id,
               c.capability_id,
               c.capability_type_id,
               c.capability_activation_days,
               c.capability_activation_date,
               capability_expiration_date = i.start_date,
               c.insert_date,
               c.insert_by,
               c.modified_date,
               c.modified_by,
               i.license_change_reason_id,
               history_date = @history_date,
               history_by = @history_by,
               i.order_item_id,
               days_used = DATEDIFF(dd, c.capability_activation_date, @history_date),
               days_added = DATEDIFF(dd, c.capability_expiration_date, i.capability_expiration_date),
               days_remaining = DATEDIFF(dd, @history_date, c.capability_expiration_date),
               days_new = DATEDIFF(dd, c.capability_activation_date, i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability pc
                ON pc.product_id = i.product_id
            INNER JOIN license_capability c
                ON c.license_id = i.license_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND i.product_type_id = 3
        UNION
        SELECT c.license_capability_id,
               c.license_id,
               c.capability_id,
               c.capability_type_id,
               c.capability_activation_days,
               capability_activation_date = CASE
                                                WHEN i2.start_date IS NOT NULL THEN
                                                    i2.start_date
                                                ELSE
                                                    c.capability_activation_date
                                            END,
               capability_expiration_date = CASE
                                                WHEN i2.start_date IS NOT NULL THEN
                                                    i2.start_date
                                                ELSE
                                                    i.start_date
                                            END,
               c.insert_date,
               c.insert_by,
               c.modified_date,
               c.modified_by,
               i.license_change_reason_id,
               history_date = @history_date,
               history_by = @history_by,
               i.order_item_id,
               days_used = DATEDIFF(dd, c.capability_activation_date, @history_date),
               days_added = DATEDIFF(dd, c.capability_expiration_date, i.capability_expiration_date),
               days_remaining = DATEDIFF(dd, @history_date, c.capability_expiration_date),
               days_new = DATEDIFF(dd, @history_date, i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability pc
                ON pc.product_id = i.product_id
            INNER JOIN license_capability c
                ON c.license_id = i.license_id
            LEFT JOIN @order_item i2
                ON i2.item_hierarchy_id = i.item_hierarchy_id
                   AND i2.product_type_id = 3
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id = 2
                  OR
                  (
                      i.produc
t_type_id = 1
                      AND i.license_change_reason_id = 8
                  )
              )
    ) x
    ORDER BY x.order_item_id DESC;

    -- 3.2.2) update license_capability  
    UPDATE license_capability
    SET capability_activation_days = x.capability_activation_days,
        capability_activation_date = x.capability_activation_date,
        capability_expiration_date = x.capability_expiration_date,
        capability_type_id = ISNULL(x.original_capability_type_id, c.capability_type_id),
        modified_date = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               i.original_capability_type_id,
               capability_activation_days = DATEDIFF(dd, MIN(i.start_date), MAX(i.capability_expiration_date)),
               capability_activation_date = MIN(i.start_date),
               capability_expiration_date = MAX(i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability c
                ON c.product_id = i.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 8
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id,
                 i.original_capability_type_id
    ) x
        INNER JOIN license_capability c
            ON c.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1;

    -- 3.3) license_seat  
    -- 3.3.1) license_seat_history  
    INSERT INTO license_seat_history
    (
        license_seat_id,
        license_id,
        license_seats,
        seats_used,
        start_date,
        end_date,
        order_item_id,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT s.license_seat_id,
           s.license_id,
           s.license_seats,
           s.seats_used,
           s.start_date,
           end_date = i.start_date,
           order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @history_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN license_seat s
            ON s.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT s.license_seat_id,
           s.license_id,
           license_seats = CASE
                               WHEN pl.product_line_id NOT IN ( 55, 300 ) THEN
                                   s.license_seats
                               WHEN i.product_type_id = 3 THEN
                                   s.license_seats
                               ELSE
                                   i.quantity
                           END,
           s.seats_used,
           start_date = CASE
                            WHEN i2.start_date IS NOT NULL THEN
                                i2.start_date
                            ELSE
                                s.start_date
                        END,
           end_date = CASE
                          WHEN i2.start_date IS NOT NULL THEN
                              i2.start_date
                          ELSE
                              i.start_date
                      END,
           i.order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @h
istory_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN product_line_product pl
            ON pl.product_id = i.product_id
        INNER JOIN license_seat s
            ON s.license_id = i.license_id
        LEFT JOIN @order_item i2
            ON i2.item_hierarchy_id = i.item_hierarchy_id
               AND i2.product_type_id = 3
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id = 8
              )
          );

    -- 3.3.2) update license_seat  
    UPDATE license_seat
    SET start_date = x.start_date,
        end_date = x.end_date,
        license_seats = x.original_license_seats,
        modified_date = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               pl.product_line_id,
               i.item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               original_license_seats = MIN(i.original_license_seats)
        FROM @order_item i
            INNER JOIN product_line_product pl
                ON pl.product_id = i.product_id
            INNER JOIN product_seat ps
                ON ps.product_id = i.product_id
            INNER JOIN license_seat s
                ON s.license_id = i.license_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 8
                  )
              )
        GROUP BY i.license_id,
                 pl.product_line_id,
                 i.item_hierarchy_id
    ) x
        INNER JOIN license_seat ls
            ON x.license_id = ls.license_id
    WHERE x.item_hierarchy_id = 1;

    -- 3.4) license_module_license  
    -- 3.4.1) license_module_license_history  
    INSERT INTO license_module_license_history
    (
        license_module_license_id,
        license_id,
        license_module_id,
        module_seats,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        order_item_id,
        license_change_reason_id,
        history_date
    )
    SELECT ml.license_module_license_id,
           ml.license_id,
           ml.license_module_id,
           ml.module_seats,
           ml.license_module_type_id,
           ml.start_date,
           end_date = i.start_date,
           ml.license_status_id,
           ml.last_modified_date,
           ml.last_modified_by,
           i.order_item_id,
           i.license_change_reason_id,
           @history_date
    FROM @order_item i
        INNER JOIN license_module_license ml
            ON ml.license_id = i.license_id
               AND ml.license_module_id = i.license_module_id
    WHERE i.item_hierarchy_id = 2;

    -- 3.4.2) update license_module_license  
    UPDATE license_module_license
    SET start_date = x.start_date,
        end_date = x.end_date,
        module_seats = x.module_seats,
        license_module_type_id = x.license_module_type_id,
        license_status_id = 1,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               ml.license_module_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               module_seats = i.original_license_seats,
               license_module_type_id = i.original_license_m
odule_type_id
        FROM @order_item i
            INNER JOIN license_module_license ml
                ON ml.license_id = i.license_id
                   AND ml.license_module_id = i.license_module_id
            INNER JOIN license_module_type t
                ON i.new_capability_type_description = t.license_module_type_name
        WHERE i.item_hierarchy_id = 2
        GROUP BY i.license_id,
                 i.original_license_module_type_id,
                 i.original_license_seats,
                 i.item_hierarchy_id,
                 ml.license_module_id
    ) x
        INNER JOIN license_module_license ls
            ON x.license_id = ls.license_id
               AND ls.license_module_id = x.license_module_id
    WHERE x.item_hierarchy_id = 2;

    -- 3.1.1) license_storage_history  
    INSERT INTO license_storage_history
    (
        license_storage_id,
        license_id,
        storage_gb,
        storage_activation_date,
        storage_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT s.license_storage_id,
           s.license_id,
           s.storage_gb,
           storage_activation_date = CASE
                                         WHEN i.start_date IS NOT NULL THEN
                                             i.start_date
                                         ELSE
                                             s.storage_activation_date
                                     END,
           storage_expiration_date = CASE
                                         WHEN i.start_date IS NOT NULL THEN
                                             i.start_date
                                         ELSE
                                             i.start_date
                                     END,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @history_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN license_storage s
            ON s.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT s.license_storage_id,
           s.license_id,
           s.storage_gb,
           storage_activation_date = CASE
                                         WHEN i.start_date IS NOT NULL THEN
                                             i.start_date
                                         ELSE
                                             s.storage_activation_date
                                     END,
           storage_expiration_date = CASE
                                         WHEN i.start_date IS NOT NULL THEN
                                             i.start_date
                                         ELSE
                                             i.start_date
                                     END,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @history_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN license_storage s
            ON s.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id = 8
              )
          );

    -- 3.1.2) update license_category_license  
    UPDATE license_storage
    SET storage_gb = ISNULL(x.original_storage_gb, 0),
        storage_activation_date = x.start_date,
        storage_
expiration_date = x.end_date,
        modified_date = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               storage_gb = MAX(s.storage_gb),
               original_storage_gb = MIN(i.original_storage_gb)
        FROM @order_item i
            INNER JOIN license_storage s
                ON s.license_id = i.license_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 8
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id
    ) x
        INNER JOIN license_storage ls
            ON ls.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1;

    --select '@child_license_table', * from @child_license_table  
    --return  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 4.) update child license  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 4.1) license_category_license  
    -- 4.1.1) license_category_license_history  
    INSERT INTO license_category_license_history
    (
        license_category_license_id,
        license_id,
        license_category_id,
        start_date,
        end_date,
        order_item_id,
        last_modified_date,
        last_modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
           cl.start_date,
           end_date = c.start_date,
           c.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           c.license_change_reason_id,
           @history_date,
           @history_by
    FROM @child_license_table c
        INNER JOIN license_category_license cl
            ON cl.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.1.2) update license_category_license  
    UPDATE license_category_license
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_category_license cl
            ON cl.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.2) license_capability  
    -- 4.2.1) license_capability_history  
    INSERT INTO license_capability_history
    (
        license_capability_id,
        license_id,
        capability_id,
        capability_type_id,
        capability_activation_days,
        capability_activation_date,
        capability_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        capability_change_reason_id,
        history_date,
        history_by,
        order_item_id
    )
    SELECT lc.license_capability_id,
           lc.license_id,
           lc.capability_id,
           lc.capability_type_id,
           capability_activation_days = DATEDIFF(dd, lc.capability_activation_date, c.start_date),
           capability_activation_date,
           capability_expiration_date = c.start_date,
           insert_date,
           insert_by,
           modified_date,
           modified_by,
           c.li
cense_change_reason_id,
           @history_date,
           @history_by,
           order_item_id
    FROM @child_license_table c
        INNER JOIN license_capability lc
            ON lc.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.2.2) update license_capability  
    UPDATE license_capability
    SET capability_activation_days = DATEDIFF(dd, c.start_date, c.new_expiration_date),
        capability_activation_date = c.start_date,
        capability_expiration_date = c.new_expiration_date,
        capability_type_id = 1,
        modified_date = @history_date,
        modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_capability lc
            ON lc.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.3) license_seat  
    -- 4.3.1) license_seat_history  
    INSERT INTO license_seat_history
    (
        license_seat_id,
        license_id,
        license_seats,
        seats_used,
        start_date,
        end_date,
        order_item_id,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT s.license_seat_id,
           s.license_id,
           s.license_seats,
           s.seats_used,
           s.start_date,
           end_date = c.start_date,
           c.order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           c.license_change_reason_id,
           @history_date,
           @history_by
    FROM @child_license_table c
        INNER JOIN license_seat s
            ON s.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.3.2) update license_seat  
    UPDATE license_seat
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        license_seats = s.license_seats,
        modified_date = @history_date,
        modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_seat s
            ON s.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL;

    -- 4.4) license_module_license  
    -- 4.4.1) license_module_license_history  
    INSERT INTO license_module_license_history
    (
        license_module_license_id,
        license_id,
        license_module_id,
        module_seats,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        order_item_id,
        license_change_reason_id,
        history_date
    )
    SELECT ml.license_module_license_id,
           ml.license_id,
           ml.license_module_id,
           ml.module_seats,
           ml.license_module_type_id,
           ml.start_date,
           end_date = c.start_date,
           ml.license_status_id,
           ml.last_modified_date,
           ml.last_modified_by,
           c.order_item_id,
           c.license_change_reason_id,
           @history_date
    FROM @child_license_table c
        INNER JOIN license_category lc
            ON lc.license_category_name = c.license_category_name
        INNER JOIN license_module_category mc
            ON mc.license_category_id = lc.license_category_id
        INNER JOIN license_module_license ml
            ON ml.license_id = c.license_id
               AND ml.license_module_id = mc.license_module_id
    WHERE c.item_hierarchy_id = 2
          AND c.order_action IS NOT NULL;

    -- 4.4.2) update license_module_license  
    UPDATE license_module_license
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        module_seats = ml.module_seats,
        licens
e_module_type_id = 19,
        license_status_id = 1,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_category lc
            ON lc.license_category_name = c.license_category_name
        INNER JOIN license_module_category mc
            ON mc.license_category_id = lc.license_category_id
        INNER JOIN license_module_license ml
            ON ml.license_id = c.license_id
               AND ml.license_module_id = mc.license_module_id
    WHERE c.item_hierarchy_id = 2
          AND c.order_action IS NOT NULL;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 5.0 ) WIFI license insert into sky_update  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    --put in a record into sky_update so the cron can update Safer  
    INSERT INTO sky_update
    (
        license_id,
        sky_template_id,
        sky_update_type_id
    )
    SELECT oi.license_id,
           7,
           7
    FROM @order_item oi
        LEFT JOIN sky_update su
            ON su.license_id = oi.license_id
               AND su.sky_template_id = 7
               AND su.sky_update_type_id = 7
    WHERE oi.original_license_category_id = 135 --WIFI  
          AND su.sky_update_id IS NULL;

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 6.0)  License Contract call  
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    --get the most recent row from license_contract_table and get the order_header_id for that row.  This will be used below to make sure that  
    --the order_header_id from license_contract_table matches what was set in license_contract_refunded_order_header_id above  
    --do this before inserting the child records so we only set the parent level license_contract_original_order_header_id  
    UPDATE lco
    SET lco.license_contract_original_order_header_id = oi.order_header_id
    FROM @license_contract_object lco
        CROSS APPLY fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
        INNER JOIN license_contract_transaction lct
            ON fn.license_contract_transaction_id = lct.license_contract_transaction_id
        INNER JOIN effective_object_transaction_type eott
            ON eott.effective_object_transaction_type_id = lct.effective_object_transaction_type_id
        INNER JOIN order_item oi
            ON lct.contract_transaction_type_value = oi.order_item_id
    WHERE eott.effective_object_transaction_type_name = 'order_item_id';

    --insert all the child records from @child_license_table which doesn't already exist in @license_contract_object  
    INSERT INTO @license_contract_object
    (
        license_id,
        license_category_id,
        license_category_type_id,
        order_item_id
    )
    SELECT DISTINCT
           clt.license_id,
           lc.license_category_id,
           ct.capability_type_id,
           clt.order_item_id
    FROM @child_license_table clt
        INNER JOIN capability_type ct
            ON ct.capability_type_description = clt.new_category_type_name
        INNER JOIN license_category lc
            ON lc.license_category_name = clt.license_category_name
        INNER JOIN @license_contract_object lco
            ON lco.license_id = clt.parent_license_id
               AND lco.license_category_id = lc.license_catego
ry_id
               AND lco.order_item_id = clt.order_item_id
        LEFT JOIN @license_contract_object lco2
            ON lco2.license_id = clt.license_id
               AND lco2.license_category_id = lco.license_category_id
    WHERE clt.order_action IS NOT NULL
          AND lco2.license_id IS NULL;

    --update the order_item_id and set to the refunded order_item_id by product/line item  
    UPDATE lco
    SET lco.order_item_id = oi2.order_item_id
    FROM @license_contract_object lco
        INNER JOIN order_item oi
            ON oi.order_item_id = lco.order_item_id
        INNER JOIN order_item oi2
            ON oi.order_header_id = oi2.order_header_id
               AND oi.product_id = oi2.product_id
               AND oi.line_item = oi2.line_item
    WHERE oi.order_item_status_id = 1
          AND oi2.order_item_status_id = 3;

    --here we are trying to figure out what the seats were before the order which was just refunded.  Get the min effective_date and look at effective object the day before that.  
    --the reason for min effective_date is immediate upgrade + future renewal possibility on same order  
    UPDATE lco
    SET lco.license_seats = dbo.fn_license_select_effective_object_element(
                                                                              lco.license_id,
                                                                              lco.license_category_id,
                                                                              'license_seats',
                                                                              DATEADD(dd, -1, lco2.license_start_date)
                                                                          )
    FROM @license_contract_object lco
        INNER JOIN
        (
            SELECT license_category_id,
                   license_id,
                   MIN(license_start_date) AS license_start_date
            FROM @license_contract_object
            GROUP BY license_category_id,
                     license_id
        ) lco2
            ON lco2.license_category_id = lco.license_category_id
               AND lco2.license_id = lco.license_id;

    --build up the JSON now based on data in @license_contract_object only for business licenses  
    SELECT @license_contract_json =
    (
        SELECT license_id = lco.license_id,
               license_category_id = lco.license_category_id,
               license_category_type_id = lco.license_category_type_id,
               license_start_date = fn.license_start_date,
               license_end_date = fn.license_end_date,
               order_item_id = lco.order_item_id,
               originating_license_contract_id = fn.license_contract_id,
               originating_license_contract_transaction_id = fn.license_contract_transaction_id,
               license_contract_original_order_header_id = lco.license_contract_original_order_header_id,
               license_contract_refunded_order_header_id = lco.license_contract_refunded_order_header_id,
               is_full_refund = 1
        FROM @license_contract_object lco
            INNER JOIN license l
                ON l.license_id = lco.license_id
            CROSS APPLY fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
        WHERE l.product_line_id IN ( 55, 300 )
        FOR JSON PATH
    );

    --if data exists, call usp_license_insert_license_contract  
    IF @license_contract_json IS NOT NULL
    BEGIN
        EXEC usp_license_insert_license_contract @license_contract_json = @license_contract_json,
                                                 @license_contract_source_caller = 'usp_cart_refund_order_license';
    END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 7.0 ) effective
 object code  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    --build up the JSON now based on data in @license_contract_object only for business licenses  
    SELECT @license_effective_object_json =
    (
        SELECT license_id = lco.license_id,
               license_category_id = lco.license_category_id,
               license_seats = lco.license_seats,
               effective_start_date = lco.license_start_date,
               order_item_id = lco.order_item_id
        FROM @license_contract_object lco
            INNER JOIN license l
                ON l.license_id = lco.license_id
        WHERE l.product_line_id IN ( 55, 300 )
              AND lco.license_seats IS NOT NULL
        FOR JSON PATH
    );

    --if data exists, call the insert now  
    IF @license_effective_object_json IS NOT NULL
    BEGIN
        EXEC usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json,
                                                 @license_effective_source_caller = 'usp_cart_refund_order_license';
    END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 8.0 ) Autorenewal status maintenance for the license categories included in the order, and any original_license_category_ids  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------   
    --stage the licenses and license_category_ids from the order being refunded. To prevent dupe calls, we only need 1 item per category  
    INSERT INTO @refund_license_attribute
    (
        license_id,
        license_attribute_id,
        license_attribute_license_value
    )
    SELECT DISTINCT
           i.license_id,
           lal.license_attribute_id,
           lal.license_attribute_license_value
    FROM @order_item i
        LEFT JOIN license_attribute_license lal
            ON lal.license_id = i.license_id
               AND lal.license_attribute_id = 1;

    --Loop over the licenses in @refund_license_attribute, and update their AR status as needed. One call per license - category-level AR opt-out management is done within usp_license_update_license_attribute_license.  
    IF EXISTS (SELECT 1 FROM @refund_license_attribute)
    BEGIN
        SELECT @temp_id = 1,
               @total_ids = MAX(temp_id)
        FROM @refund_license_attribute;

        WHILE @temp_id <= @total_ids
        BEGIN
            SELECT @license_id = license_id,
                   @license_attribute_id = license_attribute_id,
                   @license_attribute_license_value = license_attribute_license_value
            FROM @refund_license_attribute
            WHERE temp_id = @temp_id;

            --Call the procedure if the license is not already opted-out  
            IF @license_attribute_license_value NOT IN ( 2, 3 )
               OR @license_attribute_license_value IS NULL
            BEGIN
                EXEC usp_license_update_license_attribute_license @license_id = @license_id,
                                                                  @license_attribute_id = @license_attribute_id,
                                                                  @license_attribute_license_value = 2,
                                                                  @modified_by = @history_by,
                                                                  @effective_date = @history_date;
            END;

            SELECT @license_id = NULL,
                   @license_attribute_id = NULL,
                   @license_attribute_license_value = NULL;

            SELECT @temp_id = @temp_id + 1;
        END;
    END
;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------  
    -- 9.0 ) Call Stored Procedure usp_sap_update_sap_order to terminate sap contracts for Refunded order  
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------   
    IF @order_header_id IS NOT NULL
    BEGIN
        EXEC usp_sap_update_sap_order_status @order_header_id;
    END;


END TRY
BEGIN CATCH
    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'Refund license update failed for vendor_order_code: ' + @vendor_order_code
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);

    SET @DBName = DB_NAME();

    EXEC usp_LogError @ErrorDB = @DBName;
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_refund_partial]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_refund_partial]

(
        @order_header_id int,
		@line_item_xml xml,
		@refund_reason_code int,
		@comment varchar(8000),
		@csi_user_id varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-03-10	esmart		Initial creation.
	2015-02-25	cnovac		Updated order_item_status_id to use @order_status_id instead of hardcoded 3, which was wrong
	2017-02-14	blu			Standardize refund.
	2018-08-29	esmart		Modified effective_date and capability_expiration_date
	2018-12-05	cnovac		Added check for oi.order_item_status_id = 1 to ensure dups don't go into order_item

	DESCRIPTION

*/

AS
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON
		
	
	declare @order_status_id int = 2, --this status is specific for partial refund
			@line_items int,
			@total_refund_amount money,
			@total_tax_refund_amount money,
			@customer_id int,
			@modified_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

begin try


	select @customer_id = customer_id
	from customer_order
	where order_header_id = @order_header_id and customer_type_id = 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get total and setup table
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @line_items = count(*),
			@total_refund_amount = sum(unit_price),
			@total_tax_refund_amount = sum(tax)
	from (select x.item.value('line_item[1]','int') as line_item,
				x.item.value('product_id[1]','int') as product_id,
				x.item.value('quantity[1]','int') as quantity,
				x.item.value('unit_price[1]','money') as unit_price,
				x.item.value('tax[1]','money') as tax
			from @line_item_xml.nodes('//order_item') x(item)) t

	declare @order_item table (
		[order_item_id] [int] IDENTITY(1,1) NOT NULL,
		[order_header_id] [int] NOT NULL,
		[line_item] [int] NOT NULL,
		[product_id] [int] NOT NULL,
		[quantity] [int] NOT NULL,
		[list_price] [money] NOT NULL,
		[unit_price] [money] NOT NULL,
		[tax] [money] NULL,
		[order_item_offer_id] [varchar](65),
		[order_item_offer_amount] [money] NULL,
		[item_total] [money] NULL,
		[tax_exempt] [bit] NULL,
		[effective_date] [datetime] NOT NULL,
		[order_item_status_id] [int] NOT NULL,
		[capability_expiration_date] [datetime] NULL)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert order_item
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert refund order_item rows
	insert into @order_item (order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, capability_expiration_date)
	select	order_header_id = @order_header_id, 
			line_item = (x.item.value('line_item[1]','int')), 
			x.item.value('product_id[1]','int') as product_id,
			x.item.value('quantity[1]','int') as quantity,
			x.item.value('list_price[1]','money') as list_price,
			x.item.value('unit_price[1]','money') as unit_price,
			x.item.value('tax[1]','money') as tax, 
			order_item_offer_id = NULL, 
			order_item_offer_amount = 0, 
			(x.item.value('unit_price[1]','money')+x.item.value('tax[1]','money')) as item_total, 
			tax_exempt = 0, 
			effective_date = getdate(), 
			order_item_status_id = @order_status_id, 
			capability_expiration_date = getdate()
	from @line_item_xml.nodes('//order_item') x(item)

	insert into order_item (order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, capability_expiration_date, insert_by, insert_date, modified_by, modified_date)
	select i.order_header_id, 
			i.line_item, 
			i.product_id, i.quantity, i.list_price, i.unit_price, i.tax, i.order_item_offer_id, i.order_item_offer_amount, 
			i.item_total, 
			i.tax_exempt, oi.effective_date, i.order_item_status_id, oi.capability_expiration_date,
			insert_by = @csi_user_id,
			insert_date = @modified_date,
			modified_by = @csi_user_id,
			modified_date = @modified_date
	from @order_item i
	inner join order_item oi
		on oi.order_header_id = i.order_header_id and oi.line_item = i.line_item and oi.order_item_status_id = 1 --only look at the purchase line in case there's multiple partial refunds with same line_item
	order by line_item

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update order header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) insert order_history
	insert into order_history (order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, history_by)
	select order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id = 3, insert_date, insert_by, modified_date, modified_by, @csi_user_id
	from order_header
	where order_header_id = @order_header_id	

	-- 3.2) update order header
	update order_header 
	set total_amount = total_amount + (@total_refund_amount+@total_tax_refund_amount), 
		sub_total_amount = sub_total_amount + @total_refund_amount, 
		tax_total = tax_total + @total_tax_refund_amount,
		order_status_id = @order_status_id, 
		modified_date = getdate(), 
		modified_by = @csi_user_id
	from order_header
	where order_header_id = @order_header_id


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) insert refund reason
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @refund_license table (license_id int)

	insert into @refund_license (license_id)
	select distinct il.license_id
	from order_item i
	inner join product p
		on i.product_id = p.product_id
	inner join order_item_license il
		on i.order_item_id = il.order_item_id
	where i.order_header_id = @order_header_id and i.quantity <= 0

	insert into csi_comments (subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id, refund_reason_code, csi_users_id)
	select subject = 'Refund Reason: ', 
			comment = 
				case 
					when @comment is null or @comment = '' then r.description
					else @comment 
				end, 
			insert_date = getdate(), 
			insert_by = @csi_user_id, 
			customer_id = @customer_i
d, 
			invoice_id = @order_header_id, 
			l.license_id, 
			r.refund_reason_code, 
			@csi_user_id
	from lu_refund_reasons r
	left join @refund_license l
		on r.refund_reason_code  = r.refund_reason_code 
	where refund_reason_code = @refund_reason_code 
	
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not refund order for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	rollback transaction partial_refund

end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_refund_tax]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_refund_tax]

(
        @order_header_id int,
		@refund_reason_code int,
		@comment varchar(8000),
		@csi_user_id varchar(50)
		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-03-10	esmart		Initial creation.
	2015-02-25	cnovac		Set @order_status_id = 5 and took out @tax_refund_amount from passed in variable
	2016-12-02	acoffel		Refactor for SMB
	2017-02-14	blu			Standardize refund.
	2018-01-16	cnovac		Changed order_status_id to be 5 when writing to history and changed item_total to be negated tax amount due to us writing total tax now
	2018-08-29	esmart		Modified effective_date and capability_expiration_date

	DESCRIPTION
	
*/


AS
	set nocount on				
	
	declare @order_status_id int = 5, --this is a new status which indicates full tax refund
			@customer_id int,
			@modified_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

begin try

	begin transaction tax_refund

	select @customer_id = customer_id
	from customer_order
	where order_header_id = @order_header_id and customer_type_id = 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update order header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) insert order_history
	insert into order_history (order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, history_by)
	select order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id = 5, insert_date, insert_by, modified_date, modified_by, @csi_user_id
	from order_header
	where order_header_id = @order_header_id	

	-- 1.2) update order header
	update order_header 
	set total_amount = (total_amount-tax_total), 
		tax_total = 0, 
		order_status_id = @order_status_id, 
		modified_date = getdate(), 
		modified_by = @csi_user_id
	where order_header_id = @order_header_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) order_item
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert refund order_item rows.  Treat this as a full refund of all tax for all items that have tax associated to them
	insert into order_item (order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, capability_expiration_date, insert_by, insert_date, modified_by, modified_date)
	select order_header_id,
		line_item,
		product_id,
		quantity,
		0,
		0,
		(tax*-1) as tax,
		null,
		0,
		(tax*-1) as item_total,
		0,
		effective_date,
		@order_status_id,
		capability_expiration_date,
		insert_by = @csi_user_id,
		insert_date = @modified_date,
		modified_by = @csi_user_id,
		modified_date = @modified_date
	from order_item
	where order_header_id = @order_header_id
	and tax > 0
	and order_item_status_id
 = 1
	order by order_item_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert refund reason
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into csi_comments (subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id, refund_reason_code, csi_users_id)
	select subject = 'Tax Refund: ',
			comment = @comment,
			insert_date = getdate(),
			insert_by = @csi_user_id,
			customer_id = @customer_id,
			invoice_id = @order_header_id,
			license_id = null,
			r.refund_reason_code,
			@csi_user_id
	from lu_refund_reasons r
	where refund_reason_code = @refund_reason_code

	commit transaction tax_refund

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update licenses for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	rollback transaction tax_refund

end catch;
	
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_bundle_upsell]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cart_select_bundle_upsell]
(
    @cart_order_in_process_id INT = NULL,
    @cart_order_id INT = NULL,
    @cart_item_bundle_id INT = NULL,
    @cart_sector_name VARCHAR(50) = NULL,
    @license_json NVARCHAR(MAX) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2011-07-11	esmart		Initial creation.
	2013-06-26	esmart		Fix issue with trial keycodes
	2014-08-15	esmart		Extend @item_summary
	2018-03-21	esmart		Extend for cart_order
	2018-09-03	esmart		New cart fix
	2018-09-07	esmart		Support for complimentary products (pass @cart_order_id to usp_cart_select_cart_standard_upsell)
	2020-04-14	jnavarra	Fallback to cart_discount_id from cart_order_item
	2022-10-12	jberry		AIP-75 - Pass is_allstate flag to allow WSAP offering to WAV customers
	2024-03-05	mgolla		ECOM-1481 - Added upgrade_path and upgrade_path_id parameters to differentiate call is from portal or www
	2024-03-07	jberry		ECOM-1441 - Added upgrade_path value "special" to differentiate call for special skip level upgrade page
				            Added the usage of ALLSTATE_UPGRADE_PATH key value pairs for future scalability of upgrade paths
	2025-05-15	jberry		US-3040357 - Added support for passing license category, years, license_seats and license distribution method in @license_json
				            Added logic in sec 3.3 to set @product_line_id when keycode is not passed in @license_json

	DESCRIPTION
	select upsell

	DEPENDENICIES:
	usp_cart_select_cart_order_item_in_process_summary
	usp_cart_select_cart_standard_upsell
*/

AS
SET NOCOUNT ON

DECLARE @keycode VARCHAR(40),
        @license_key VARCHAR(36),
        @product_type_id INT,
        @license_category_id TINYINT,
        @product_line_id INT,
        @license_category_name VARCHAR(10),
        @license_seats INT,
        @storage_gb INT,
        @years FLOAT,
        @cart_discount_id INT,
        @locale VARCHAR(5),
        @language_code VARCHAR(2),
        @location_code VARCHAR(3),
        @cart_sector_id TINYINT,
        @product_line_cart_type VARCHAR(20),
        @backup_cd TINYINT,
        @license_distribution_method_id INT,
        @currency_code VARCHAR(3),
        @currency_id TINYINT,
        @is_allstate INT,
        @upgrade_path VARCHAR(10)='',
        @upgrade_path_id INT=0,
        @response_code INT,
        @message VARCHAR(100)

BEGIN TRY

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Create APP_CONFIG table variable and load APP_CONFIG values required
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	DECLARE @APP_CONFIG TABLE (
		[app_config_name] NVARCHAR(50)
		, [key] NVARCHAR(50)
		, [value] NVARCHAR(MAX)
	);

	INSERT INTO @APP_CONFIG	(
		app_config_name,
		[key],
		[value]
	)
	SELECT f.app_config_name
		, f.[key]
		, f.[value]
	FROM [dbo].[fn_app_config_select_key_values] (	'ALLSTATE_UPGRADE_PATH', 'ALLSTATE' ) f;

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) @cart_order_in_process_id
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF @cart_order_in_process_id IS NOT NULL
    BEGIN
        DECLARE @item_summary TABLE
        (
    
        cart_item_bundle_id INT,
            cart_order_item_in_process_id INT,
            product_type VARCHAR(50),
            product_id INT,
            product_description VARCHAR(100),
            product_family_description VARCHAR(50),
            license_category_name VARCHAR(10),
            license_category_description VARCHAR(50),
            license_keycode_type_id INT,
            seats INT,
            storage_gb INT,
            quantity INT,
            years INT,
            retail_price MONEY,
            net_price MONEY,
            discount MONEY,
            standard_discount MONEY,
            pricing_level VARCHAR(20),
            keycode VARCHAR(40),
            product_type_id INT,
            max_product_type_id INT,
            current_license_category_id TINYINT,
            license_category_id TINYINT,
            current_seats INT,
            current_storage_gb INT,
            cart_discount_id INT,
            product_line_cart_type VARCHAR(20),
            cart_discount_bundle_description VARCHAR(200),
            cart_discount_bundle_details_list VARCHAR(1000),
            license_distribution_method_id INT,
            license_distribution_method_code VARCHAR(4),
            min_seats INT,
            max_seats INT
        )

        -- 1.1) get bundle item summary 
        INSERT INTO @item_summary
        (
            cart_item_bundle_id,
            cart_order_item_in_process_id,
            product_type,
            product_id,
            product_description,
            product_family_description,
            license_category_name,
            license_category_description,
            license_keycode_type_id,
            seats,
            storage_gb,
            quantity,
            years,
            retail_price,
            net_price,
            discount,
            standard_discount,
            pricing_level,
            keycode,
            product_type_id,
            max_product_type_id,
            current_license_category_id,
            license_category_id,
            current_seats,
            current_storage_gb,
            cart_discount_id,
            product_line_cart_type,
            cart_discount_bundle_description,
            cart_discount_bundle_details_list,
            license_distribution_method_id,
            license_distribution_method_code,
            min_seats,
            max_seats
        )
        EXEC usp_cart_select_cart_order_item_in_process_summary @cart_order_in_process_id,
                                                                @cart_item_bundle_id

        SELECT @keycode = i.keycode,
               @product_type_id = CASE
                                      WHEN i.product_type = 'New' THEN
                                          1
                                      WHEN i.product_type = 'Renewal'
                                           OR i.product_type = ' Upgrade/Renewal' THEN
                                          2
                                      ELSE
                                          1
                                  END,
               @license_category_name = c.license_category_name,
               @license_seats = i.seats,
               @storage_gb = ISNULL(i.storage_gb, 0),
               @years = i.years,
               @cart_discount_id = i.cart_discount_id,
               @product_line_cart_type = product_line_cart_type
        FROM @item_summary i
            INNER JOIN license_category c
                ON i.license_category_description = c.license_category_description
        WHERE product_family_description <> 'S/H'

        -- 1.2) get language and location for the order
        SELECT @language_code = language_code,
               @location_code = location_code
        FROM cart_order_in_process
        WHERE cart_order_in_process_id = @cart_order_in_process_id

        -- 1.3) @back
up_cd
        SELECT @backup_cd = COUNT(*)
        FROM @item_summary i
            INNER JOIN license_category c
                ON i.license_category_description = c.license_category_description
        WHERE product_family_description = 'S/H'


        -- 1.4) @license_distribution_method_id
        SELECT @license_distribution_method_id = dm.license_distribution_method_id
        FROM cart_discount_license_distribution_method b
            INNER JOIN license_distribution_method dm
                ON b.license_distribution_method_id = dm.license_distribution_method_id
            INNER JOIN cart_discount d
                ON b.cart_discount_id = d.cart_discount_id
            INNER JOIN cart_order_message_in_process m
                ON d.cart_discount_key = m.message_key
                   OR d.cart_discount_id = m.cart_discount_id
        WHERE m.cart_order_in_process_id = @cart_order_in_process_id

    END

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) @cart_order_id
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF @cart_order_id IS NOT NULL
    BEGIN
        -- 2.1) @cart_item_bundle_id
        IF @cart_item_bundle_id IS NULL
        BEGIN
            SELECT @cart_item_bundle_id = 1
        END

        -- 2.2) with keycode
        SELECT @keycode = il.keycode,
               @product_type_id = MIN(p.product_type_id),
               @license_category_id = MAX(lc.license_category_id),
               @license_seats = MAX(s.seats),
               @storage_gb = ISNULL(MAX(st.storage_gb), 0),
               @years = MAX(y.years),
               @cart_discount_id = MAX(COALESCE(m.cart_discount_id, i.cart_discount_id)),
               @product_line_id = MAX(pl.product_line_id)
        FROM cart_order co
            INNER JOIN cart_order_item i
                ON i.cart_order_id = co.cart_order_id
                   AND i.item_hierarchy_id = 1
            INNER JOIN product p
                ON p.product_id = i.product_id
            INNER JOIN product_seat s
                ON s.product_id = p.product_id
            INNER JOIN product_years y
                ON y.product_id = p.product_id
            INNER JOIN product_line_product plp
                ON plp.product_id = p.product_id
            INNER JOIN product_line pl
                ON pl.product_line_id = plp.product_line_id
            INNER JOIN product_license_category plc
                ON plc.product_id = p.product_id
            INNER JOIN license_category lc
                ON lc.license_category_id = plc.license_category_id
            LEFT JOIN cart_order_item_license il
                ON il.cart_order_item_id = i.cart_order_item_id
            LEFT JOIN cart_order_message m
                ON m.cart_order_id = co.cart_order_id
            LEFT JOIN product_storage st
                ON st.product_id = p.product_id
        WHERE co.cart_order_id = @cart_order_id
              AND i.cart_item_bundle_id = @cart_item_bundle_id
        GROUP BY il.keycode

        -- 2.3) without keycode
        IF @keycode IS NULL
        BEGIN
            SELECT @product_type_id = MIN(p.product_type_id),
                   @license_category_id = MAX(lc.license_category_id),
                   @license_seats = MAX(s.seats),
                   @storage_gb = ISNULL(MAX(st.storage_gb), 0),
                   @years = MAX(y.years),
                   @cart_discount_id = MAX(COALESCE(m.cart_discount_id, i.cart_discount_id)),
                   @product_line_id = MAX(pl.product_line_id)
            FROM cart_order co
                INNER JOIN cart_order_item i
                    ON i.cart_order_id = co.cart_order_id
                       AND i.i
tem_hierarchy_id = 1
                INNER JOIN product p
                    ON p.product_id = i.product_id
                INNER JOIN product_seat s
                    ON s.product_id = p.product_id
                INNER JOIN product_years y
                    ON y.product_id = p.product_id
                INNER JOIN product_line_product plp
                    ON plp.product_id = p.product_id
                INNER JOIN product_line pl
                    ON pl.product_line_id = plp.product_line_id
                INNER JOIN product_license_category plc
                    ON plc.product_id = p.product_id
                INNER JOIN license_category lc
                    ON lc.license_category_id = plc.license_category_id
                LEFT JOIN cart_order_item_license il
                    ON il.cart_order_item_id = i.cart_order_item_id
                LEFT JOIN cart_order_message m
                    ON m.cart_order_id = co.cart_order_id
                LEFT JOIN product_storage st
                    ON st.product_id = p.product_id
            WHERE co.cart_order_id = @cart_order_id
                  AND i.cart_item_bundle_id = @cart_item_bundle_id
            GROUP BY i.cart_item_bundle_id
        END

        -- 2.4) set values
        SELECT @locale = co.locale
        FROM cart_order co
        WHERE co.cart_order_id = @cart_order_id

        SELECT @product_line_cart_type = pl.product_line_cart_type
        FROM product_line pl
        WHERE pl.product_line_id = @product_line_id

        SELECT @license_category_name = license_category_name
        FROM license_category
        WHERE license_category_id = @license_category_id

        -- 2.5) @language_code and @location_code
        SELECT @language_code = language_code,
               @location_code = location_code
        FROM dbo.fn_locale_to_lang_loc(@locale)

        -- 2.6) @license_distribution_method_id
        SELECT @license_distribution_method_id = dm.license_distribution_method_id
        FROM cart_discount_license_distribution_method b
            INNER JOIN license_distribution_method dm
                ON b.license_distribution_method_id = dm.license_distribution_method_id
            INNER JOIN cart_discount d
                ON b.cart_discount_id = d.cart_discount_id
            INNER JOIN cart_order_message m
                ON d.cart_discount_key = m.message_key
                   OR d.cart_discount_id = m.cart_discount_id
        WHERE m.cart_order_id = @cart_order_id

        -- 2.7) @backup_cd
        SELECT @backup_cd = COUNT(*)
        FROM cart_order_item i
            INNER JOIN product p
                ON p.product_id = i.product_id
            INNER JOIN product_family f
                ON f.product_family_id = p.product_family_id
        WHERE f.product_family_description = 'S/H'
              AND i.cart_order_id = @cart_order_id
              AND i.cart_item_bundle_id = @cart_item_bundle_id

    END


    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) @license_json
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF @license_json IS NOT NULL
    BEGIN

        -- 3.1) license values
        SELECT @keycode = keycode,
               @locale = locale,
               @currency_code = currency_code,
               @license_key = license_key,
               @is_allstate = is_allstate,
               @upgrade_path = upgrade_path,
               @license_category_name = license_category_name,
               @license_seats = license_seats,
               @years = years,
               @license_distribution_method_id = license_distribution_method_id
        FROM
            OPENJSON(@license_json)
     
       WITH
            (
                keycode VARCHAR(40) '$.keycode',
                locale VARCHAR(10) '$.locale',
                currency_code VARCHAR(10) '$.currency_code',
                license_key VARCHAR(36) '$.license_key',
                is_allstate INT '$.is_allstate',
                upgrade_path VARCHAR(10) '$.upgrade_path',
                license_category_name VARCHAR(10) '$.license_category_name',
                license_seats VARCHAR(10) '$.license_seats',
                years float '$.years',
                license_distribution_method_id int '$.license_distribution_method_id'
            )

        SELECT @product_type_id = ISNULL(@product_type_id, 2)
        SELECT @years = ISNULL(@years, 1)
        SELECT @backup_cd = ISNULL(@backup_cd, 0)
        SELECT @storage_gb = ISNULL(@storage_gb, 0)
        SELECT @is_allstate = ISNULL(@is_allstate, 0)
		SELECT @upgrade_path=ISNULL(@upgrade_path,'')
        SELECT @currency_id = currency_id
        FROM currency
        WHERE currency_code = @currency_code

        -- 3.2) @language_code and @location_code
        SELECT @language_code = language_code,
               @location_code = location_code
        FROM dbo.fn_locale_to_lang_loc(@locale)

        IF @keycode IS NULL
        BEGIN
            SELECT @keycode = l.keycode
            FROM license_key k
                INNER JOIN license l
                    ON l.license_id = k.license_id
            WHERE k.license_key = @license_key
        END

        -- 3.3) set values
        SELECT @license_category_id = cl.license_category_id,
               @product_line_id = pl.product_line_id,
               @license_seats = s.license_seats
        FROM license l
            INNER JOIN license_category_license cl
                ON cl.license_id = l.license_id
            INNER JOIN license_category_product_line pl
                ON pl.license_category_id = cl.license_category_id
                   AND pl.language_code = @language_code
                   AND pl.location_code = @location_code
            INNER JOIN license_seat s
                ON s.license_id = l.license_id
        WHERE l.keycode = @keycode

        IF @product_line_id IS NULL
        BEGIN
            SELECT @product_line_id = pl.product_line_id
            FROM product_line pl
              INNER JOIN dbo.license_category_product_line lcp 
			      ON lcp.product_line_id = pl.product_line_id
              INNER JOIN dbo.license_category lc
			      ON lc.license_category_id = lcp.license_category_id
            WHERE lc.license_category_name = @license_category_name
        END

        -- 3.3) @product_line_cart_type
        SELECT @product_line_cart_type = CASE
                                             WHEN @product_line_cart_type IS NULL
                                                  AND @product_line_id IN ( 55, 300 ) THEN
                                                 'Enterprise'
                                             WHEN @product_line_cart_type IS NULL
                                                  AND @product_line_id NOT IN ( 55, 300 ) THEN
                                                 'Consumer'
                                             ELSE
                                                 @product_line_cart_type
                                         END

        -- 3.4) @license_category_name
        IF @license_category_name IS NULL
        BEGIN
            SELECT @license_category_name = license_category_name
            FROM license_category
            WHERE license_category_id = @license_category_id
        END

    END


    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 4.) standard upsells
    -----------------------------------------------------------------------------------------
--------------------------------------------------------------------------

    -- 4.1) select cart_sector_id
	SELECT @cart_sector_id = cart_sector_id
	FROM cart_sector
	WHERE cart_sector_name = @cart_sector_name;

	SELECT @upgrade_path_id = CASE
                              WHEN @cart_sector_id <> 2 THEN
                                   [key]
                              ELSE
                                   0
                              END
	FROM @APP_CONFIG
	WHERE [value] = @upgrade_path;
	
    -- 4.2) select upsell offers
    --select 'usp_cart_select_cart_standard_upsell inputs', keycode = @keycode,product_type_id = @product_type_id,license_category_name = @license_category_name,license_seats = @license_seats,storage_gb = @storage_gb,years = @years,cart_discount_id = @cart_discount_id, language_code =@language_code,location_code = @location_code, cart_sector_id = @cart_sector_id, product_line_cart_type = @product_line_cart_type, backup_cd = @backup_cd, license_distribution_method_id = @license_distribution_method_id
    EXEC usp_cart_select_cart_standard_upsell @keycode,
                                              @product_type_id,
                                              @license_category_name,
                                              @license_seats,
                                              @storage_gb,
                                              @years,
                                              @cart_discount_id,
                                              @language_code,
                                              @location_code,
                                              @cart_sector_id,
                                              @product_line_cart_type,
                                              @backup_cd,
                                              @license_distribution_method_id,
                                              @cart_order_id,
                                              @is_allstate,
                                              @upgrade_path_id

END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'insert failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_campaign_cart_discount]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_campaign_cart_discount]
(
  @license_id int,
  @cart_discount_id int output
)

/*  
  DATE    AUTHOR    REMARKS
  2012-12-05  esmart    Initial creation.
  2013-08-13  esmart    Enterprise support
  2016-07-27  cnovac    changes made by Eric to correctly get @license_category_id for SS products
  2017-03-11  mandersen Altered to recognize autorenewal

  DESCRIPTION
  select campaign driven percent off discount for given license
*/

AS
  set nocount on        

  declare @license_distribution_method_id int,
      @license_seats int,
      @license_category_id tinyint, 
      @product_line_id int,
      @autorenewal_opt_id tinyint,
      @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) select
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  -- 1.1) select @license_distribution_method_id
    select @license_distribution_method_id = license_distribution_method_id,
        @license_seats = s.license_seats,
        @license_category_id = case
                      when license_category_id is null then dbo.fn_GetLicenseCategoryId(@license_id)
                      when license_category_id in (1,2) then 100
                      when license_category_id in (3,4,110) then 120
                      else license_category_id
                    end,
        --@license_category_id = isnull(cl.license_category_id,dbo.fn_GetLicenseCategoryId(@license_id)),
        @product_line_id = l.product_line_id,
        @autorenewal_opt_id = case 
                      when sub.subscription_id is null and al.license_attribute_license_value = 1 then 1 
                      when sub.subscription_id is not null and sub.opt_status = 0 then 1
                      else 0 
                    end
    from license l
    inner join license_category_license cl
      on l.license_id = cl.license_id
    inner join license_seat s
      on cl.license_id = s.license_id
    left join license_attribute_license al
      on al.license_id = s.license_id  and
         al.license_attribute_id = 1            --Auto Renewal
    left join subscription sub
      on l.license_id = sub.license_id
    where l.license_id = @license_id

  -- 1.2) @cart_discount_id
    select @cart_discount_id = (select top 1 i.cart_discount_id
                  from message_campaign m
                  inner join message_campaign_license_distribution_method d
                    on m.message_campaign_id = d.message_campaign_id
                  inner join message_campaign_seat s
                    on m.message_campaign_id = s.message_campaign_id
                  inner join message_campaign_license_category c
                    on m.message_campaign_id = c.message_campaign_id
                  inner join message_campaign_product_line pl
                    on m.message_campaign_id = pl.message_campaign_id
                  inner join message_campaign_platform pf
                    on m.message_campaign_id = pf.message_campaign_id
                  inner join message_campaign_cart_discount cd
                    on m.message_campaign_id = cd.message_campaign_id
                  inner join message_campaign_autorenewal ar
                    on m.message_campaign_id = ar.message_campaign_id
                  inner join cart_discount_item i
                    on cd.cart_discount_id = i.cart_discount_id
                  where d.license_distribution_method_id = @li
cense_distribution_method_id and 
                    i.product_line_id = @product_line_id and
                    d.inclusive = 1 and 
                    s.license_seats = case when @product_line_id in (55,300) then s.license_seats else @license_seats end and
                    c.license_category_id = @license_category_id and
                    i.cart_discount_method_id = 3 and
                    m.message_campaign_enabled = 1 and
                    pf.message_platform_id = 8 and 
                    ar.autorenewal_opt_id = @autorenewal_opt_id and
                    m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date
                  order by i.discount desc)

  end try

  begin catch

    set @response_code = -200
    set @message = case when @message is null then 'select failed'
              else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

  end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_campaign_cart_discount_new]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_campaign_cart_discount_new]


(
	@license_category_name varchar(10), 
	@license_seats int,
	@storage_gb int,
	@years float,
	@language_code varchar(2),
	@location_code varchar(3),
	@product_line_id int,
	@cart_discount_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2012-12-05	esmart		Initial creation.
	2014-02-05	esmart		Fix issue with lower configurations inheriting the discount

	DESCRIPTION
	select campaign driven percent off discount for given license
*/

AS
	set nocount on				

	declare @license_category_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @license_category_id
	select @license_category_id = license_category_id
	from license_category
	where license_category_name = @license_category_name

	-- 1.2) @cart_discount_id
	select @cart_discount_id = (select top 1 d.cart_discount_id
								from message_campaign m
								inner join message_campaign_platform pf
									on m.message_campaign_id = pf.message_campaign_id
								inner join message_campaign_cart_discount cd
									on m.message_campaign_id = cd.message_campaign_id
								inner join message_campaign_language_location ll
									on m.message_campaign_id = ll.message_campaign_id and ll.language_code = @language_code and ll.location_code = @location_code
								inner join cart_discount_item i
									on cd.cart_discount_id = i.cart_discount_id
								inner join cart_discount d
									on i.cart_discount_id = d.cart_discount_id and d.cart_discount_type_id = 1 and d.cart_discount_status_id = 1
								where i.license_seats = @license_seats and
									i.license_category_id = @license_category_id and
									i.years = @years and
									i.cart_discount_method_id = 3 and
									m.message_campaign_enabled = 1 and
									pf.message_platform_id = 8 and 
									m.message_campaign_class_id = 7 and
									m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date
								order by i.discount desc)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_customer]

(
		@vendor_order_code varchar(100),
		@customer_type_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.
	2018-03-19	esmart		Add country to state select
	2020-07-07	esmart		Add cart_customer_json

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @cart_order_id int,
			@response_code int,
			@message varchar(100)
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @cart_order_id
	select @cart_order_id = cart_order_id
	from cart_order
	where vendor_order_code = @vendor_order_code

	-- 1.2) select
	select cc.cart_order_id,
			cc.cart_customer_id,
			case when cc.external_customer_key is null and cp.partner_id is not null then json_value(j.cart_customer_json,'$.partner.partner_customer_code') else cc.external_customer_key end as external_customer_key,
			cc.first_name, 
			cc.last_name, 
			cc.company_name,
			cc.customer_email,
			address_1 = cc.bill_address_1, 
			address_2 = cc.bill_address_2, 
			city = cc.bill_city, 
			state = s.state_iso3,
			postal_code = cc.bill_postal_code, 
			country = c.iso,
			cc.phone_number, 
			cc.opt_in, 
			cc.vat_id, 
			cc.customer_type_id,
			t.customer_type_description,
			cc.company_type_id,
			ct.company_type_name,
			j.cart_customer_json
	from cart_customer cc
	inner join customer_type t
		on t.customer_type_id = cc.customer_type_id
	left join cart_order_partner cp
		on cp.cart_order_id = cc.cart_order_id
	left join company_type ct 
		on cc.company_type_id = ct.company_type_id
	left join lu_countries c
		on cc.bill_country = c.iso3
	left join lu_states s
		on cc.bill_state = rtrim(s.state_id) and s.iso2 = c.iso
	left join cart_customer_json j
		on j.cart_customer_id = cc.cart_customer_id
	where cc.cart_order_id = @cart_order_id and cc.customer_type_id = case when @customer_type_id is null then cc.customer_type_id else @customer_type_id end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not select customer for cart_order_id: ' + convert(varchar(20),@cart_order_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_customer_in_process]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_select_cart_customer_in_process]

(
		@cart_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-02-23	esmart		Initial creation.
	2011-09-15	esmart		Add lu_countries columns
	2013-07-03	acoffel		extend vat_id into select
	2013-07-24	esmart		Make lu_states a left join

	DESCRIPTION
*/


AS

	set nocount on				

	begin try

	declare @cart_customer_in_process_id int,
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top 1 cart_in_process_id,
				cart_customer_in_process_id,
				first_name,
				last_name,
				address1,
				address2,
				city,
				i.state_id,
				s.state_iso3,
				postal_code,
				c.country_id,
				c.description, 
				c.iso, 
				c.iso3, 
				c.web_display, 
				c.parent_country_iso3, 
				c.parent_state_id,
				phone_number,
				company_name,
				customer_email,
				opt_in,
				vat_id
	from cart_customer_in_process i
	left join lu_countries c
		on i.country_id = c.country_id
	left join lu_states s
		on i.state_id = s.state_id
	where cart_in_process_id = @cart_in_process_id;

	end try

	begin catch
		set @response_code = -200
		set @message = case when @message is null then 'Could not update cart_customer_in_process for @cart_in_process_id = ' + convert(varchar(20),@cart_in_process_id)
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_discount]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_cart_discount]

(
	@cart_discount_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2014-08-27	esmart		Add license_distribution_method to the output.

	DESCRIPTION
	select cart discount
*/

AS
	set nocount on				

	declare	@cart_discount_specials_code_list varchar(max),
			@cart_link varchar(200),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @cart_discount_specials_code_list
		select @cart_discount_specials_code_list = coalesce(@cart_discount_specials_code_list+', ','')+ cast(convert(varchar(20),specials_code) as varchar(100)) 
		from cart_discount_specials_mapping 
		where cart_discount_id = @cart_discount_id


	-- 1.2) @cart_link
	if (select count(*) from cart_discount_item	where product_type_id = 1 and license_category_id is not null and license_seats is not null and years is not null and cart_discount_id = @cart_discount_id) > 0
		begin
			select @cart_link = 'https://www.webroot.com/us/en/cart/update?key='+ convert(varchar(36),cart_discount_key)
			from cart_discount
			where cart_discount_id = @cart_discount_id
		end
	else
		begin
			select @cart_link = ''
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) result
		select d.cart_discount_id, cart_discount_description, cart_discount_type_id, cart_discount_status_id, cart_discount_key = convert(varchar(36),cart_discount_key), cart_discount_code, last_modified_date, last_modified_by,
			m.license_distribution_method_id,
			cart_discount_specials_code_list = @cart_discount_specials_code_list,
			cart_link = @cart_link
		from cart_discount d
		left join cart_discount_license_distribution_method m
			on d.cart_discount_id = m.cart_discount_id
		where d.cart_discount_id = @cart_discount_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_discount_bundle]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_cart_discount_bundle]

(	
	@cart_discount_id int
)


/*	
	DATE		AUTHOR		REMARKS
	2014-08-04	esmart		Initial creation.

	DESCRIPTION
	select
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
