CREATE PROCEDURE [dbo].[usp_cart_select_cart_discounts]

(
	@cart_discount_description varchar(50) = null,
	@cart_discount_code varchar(20) = null,
	@cart_discount_type_name varchar(50) = null,
	@cart_discount_status_name varchar(50) = null,
	@cart_discount_method_name varchar(50) = null,
	@product_line_description varchar(40) = null,
	@license_category_name varchar(10) = null,
	@product_type_description varchar(50) = null,
	@discount float = null,
	@license_seats int = null,
	@storage_gb int = null,
	@years float = null,
	@specials_code varchar(100) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-11	esmart		Initial creation.
	2013-01-20	esmart		Add additional search parameters
	2014-08-04	esmart		Add cart link

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@product_line_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @product_line_id = product_line_id from product_line where product_line_description = @product_line_description

	if @cart_discount_description is null 
		begin select @cart_discount_description = '' end
		
	declare @cart_discount_summary_id int,
		@cart_discounts int, 
		@cart_discount_id int,
		@cart_discount_specials_code_list varchar(max),
		@cart_discount_item_discount_list varchar(max)

	declare @cart_discount_summary table
		(cart_discount_summary_id int identity(1,1),
		cart_discount_id int,
		cart_discount_key varchar(36),
		cart_discount_description varchar(50),
		cart_discount_code varchar(20),
		cart_discount_type_name varchar(20),
		cart_discount_status_name varchar(20),
		product_type_id int,
		product_type_description varchar(50),
		product_line_description varchar(40),
		discount float,
		low_range float,
		high_range float,
		license_category_id tinyint, 
		license_category_name varchar(10), 
		license_seats int, 
		storage_gb int, 
		years float,
		cart_discount_method_name varchar(50),
		cart_discount_specials_code_list varchar(max),
		cart_discount_item_discount_list varchar(max))

	insert into @cart_discount_summary(cart_discount_id, cart_discount_key, cart_discount_description, cart_discount_code, cart_discount_type_name, cart_discount_status_name, product_type_id, product_type_description, product_line_description, discount, low_range, high_range, license_category_id, license_category_name, license_seats, storage_gb, years, cart_discount_method_name)
	select d.cart_discount_id, d.cart_discount_key, d.cart_discount_description, d.cart_discount_code, t.cart_discount_type_name, s.cart_discount_status_name, p.product_type_id, p.product_type_description, l.product_line_description, i.discount, i.low_range, i.high_range, i.license_category_id, i.license_category_name, i.license_seats, i.storage_gb, i.years, m.cart_discount_method_name--, i.*
	from cart_discount d
	inner join cart_discount_type t
		on d.cart_discount_type_id = t.cart_discount_type_id
	inner join cart_discount_status s
		on d.cart_discount_status_id = s.cart_discount_status_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	left join product_type p
		on i.product_type_id = p.product_type_id
	left join product_line l
		on i.product_line_id = l.product_line_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	where d.cart_discount_description like '%'+@cart_discount_description+'%' and
		t.cart_dis
count_type_name = case
									when @cart_discount_type_name is null then t.cart_discount_type_name
									else @cart_discount_type_name 
								end and
		s.cart_discount_status_name = case
									when @cart_discount_status_name is null then s.cart_discount_status_name
									else @cart_discount_status_name 
								end and
		i.product_line_id = case
									when @product_line_id is null then i.product_line_id
									else @product_line_id 
								end 
	order by d.cart_discount_id
	
	if @discount is not null
		begin
		delete from @cart_discount_summary where round(discount,0) <> round(@discount,0) or discount is null
		end

	if @product_type_description is not null
		begin
		delete from @cart_discount_summary where product_type_description <> @product_type_description or product_type_description is null
		end

	if @cart_discount_method_name is not null
		begin
		delete from @cart_discount_summary where cart_discount_method_name <> @cart_discount_method_name or cart_discount_method_name is null
		end

	if @cart_discount_code is not null
		begin
		delete from @cart_discount_summary where cart_discount_code <> @cart_discount_code or cart_discount_code is null
		end

	if @years is not null
		begin
		delete from @cart_discount_summary where years <> @years or years is null
		end
		
	if @license_category_name is not null
		begin
		delete from @cart_discount_summary where license_category_name <> @license_category_name or license_category_name is null
		end

	if @license_seats is not null
		begin
		delete from @cart_discount_summary where license_seats <> @license_seats or license_seats is null
		end

	if @specials_code is not null and @specials_code <> ''
		begin
		delete from @cart_discount_summary where cart_discount_id not in (select cart_discount_id from cart_discount_specials_mapping where specials_code = @specials_code)
		end

	select @cart_discounts = max(cart_discount_summary_id), @cart_discount_summary_id = 1 from @cart_discount_summary
	
	while @cart_discounts >= @cart_discount_summary_id
		begin
		select @cart_discount_id = cart_discount_id from @cart_discount_summary where cart_discount_summary_id = @cart_discount_summary_id
		print @cart_discount_id

		-- 1) @cart_discount_specials_code_list
		select @cart_discount_specials_code_list = coalesce(@cart_discount_specials_code_list+', ','')+ cast(convert(varchar(20),specials_code) as varchar(100)) 
		from cart_discount_specials_mapping 
		where cart_discount_id = @cart_discount_id

		-- 2) @cart_discount_item_discount_list
		select @cart_discount_item_discount_list = coalesce(@cart_discount_item_discount_list+', ','')+ cast(convert(varchar(10),language_code)+'-'+convert(varchar(10),location_code)+' ('+isnull(symbol_utf8,'')+convert(varchar(10),id.discount)+')' as varchar(100)) 
		from cart_discount_item_discount id
		inner join currency c
			on id.currency_id = c.currency_id
		inner join cart_discount_item i
			on id.cart_discount_item_id = i.cart_discount_item_id
		where i.cart_discount_id = @cart_discount_id
		order by id.currency_id
	
		update @cart_discount_summary
		set cart_discount_specials_code_list = @cart_discount_specials_code_list,
			cart_discount_item_discount_list = @cart_discount_item_discount_list
		where cart_discount_id = @cart_discount_id

		select @cart_discount_specials_code_list = null,
				@cart_discount_item_discount_list = null
		select @cart_discount_summary_id = min(cart_discount_summary_id) from @cart_discount_summary where cart_discount_summary_id > @cart_discount_summary_id
		end

	select cart_discount_id,
		cart_discount_key,
		cart_link = case 
						when product_type_description = 'New' and license_category_id is not null and license_seats is not null and years is not null then 'https://www.webroot.com/us/en/cart/update?key='+ cart_discount_key 
						else '' 
					end,
		cart_discount_description,
		cart_discount_code,
		cart_discount_type_name,
		cart_discount_method_name,
		discount, low_range, high_range,
		product_type_descr
iption,
		product_line_description,
		license_category_id,
		license_category_name,
		license_seats,
		storage_gb,
		years,
		cart_discount_status_name,
		cart_discount_specials_code_list,
		cart_discount_item_discount_list
	from @cart_discount_summary 
	order by cart_discount_description

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
