CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_customer_in_process]

(
	@cart_order_in_process_id int,
	@customer_type_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2013-03-12	esmart		@customer_type_id
	2013-07-03	acoffel		extended vat_id into select

	DESCRIPTION
	select discount
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @customer_type_id is null
		begin
		select @customer_type_id = 1
		end

	select cart_order_customer_in_process_id, p.external_customer_key, cart_order_in_process_id, first_name, last_name, company_name, address_1, address_2, city, 
			state, state_description = s.description, s.state_iso3,
			postal_code, 
			c.country_id, country_description = c.description, 
			phone_number, customer_email, opt_in, vat_id, p.last_modified_date
	from cart_order_customer_in_process p
	inner join lu_states s
		on p.state = s.state_id
	inner join lu_countries c
		on p.country_id = c.country_id
	where cart_order_in_process_id = @cart_order_in_process_id and p.customer_type_id = @customer_type_id

	end try

	begin catch

