CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_extension]


(
		@vendor_order_code varchar(100)

)

/*	
	DATE		AUTHOR		REMARKS
	2018-09-05	esmart		Initial creation.

	DESCRIPTION
*/

AS
	set nocount on
	set ansi_warnings off
					
begin try

	declare @cart_order_id int,
			@response_code int,
			@message varchar(100)


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @cart_order_id
	select @cart_order_id = co.cart_order_id
	from cart_order co
	where co.vendor_order_code = @vendor_order_code

	-- 1.2) select extensions
	select ce.cart_order_extension_id, ce.cart_order_id, ce.order_extension_type_id, t.order_extension_type_name, t.order_extension_type_description, ce.order_extension_value, ce.insert_date
	from cart_order_extension ce
	inner join order_extension_type t
		on t.order_extension_type_id = ce.order_extension_type_id
	where ce.cart_order_id = @cart_order_id


			
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'cart_order_extension insert failed'
						else @message end

