-- PROCEDURE: [dbo].[usp_cart_select_cart_order_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_in_process]

(
	@cart_order_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2013-01-01	esmart		Add merchant_id
	2014-10-20	esmart		Add routing data
	2015-08-17	esmart		Add message data
	2016-07-13	cnovac		Added currrency code
	2016-08-02	blu			Added cart_json.

	DESCRIPTION
	select discount
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select o.cart_order_in_process_id, vendor_order_code, order_type, site_id, site_url, p_rc, p_rsc, p_ac, trx_rc, trx_rsc, trx_ac, total_amount, sub_total_amount, offer_amount, tax_amount, session_id, user_ip, submission_date, locale, o.last_modified_date, o.last_modified_by, cart_order_in_process_status_id, o.currency_id, c.currency_code, customer_profile_token, message_key = convert(varchar(36),m.message_key), m.license_id, m.cart_discount_id, m.message_campaign_id, m.message_campaign_platform, l.keycode, merchant_id, r.routing_action, o.language_code, o.location_code, location_code_iso = (select iso from lu_countries where iso3 = o.location_code), mc.message_url, o.restriction, cj.cart_json
	from cart_order_in_process o
	left join cart_order_message_in_process m
		on o.cart_order_in_process_id = m.cart_order_in_process_id and status_id = 1
	left join cart_order_route_in_process r
		on o.cart_order_in_process_id = r.cart_order_in_process_id
	left join message_content mc
		on r.routing_action = mc.message_action 
	left join license l
		on m.license_id = l.license_id
	left join currency c
		on c.currency_id = o.currency_id
	left join cart_json cj
		on o.cart_order_in_process_id = cj.cart_order_in_process_id
	where o.cart_order_in_process_id = @cart_order_in_process_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
