(
		@vendor_order_code VARCHAR(100),
		@line_item INT = NULL,
		@cart_item_bundle_id INT = NULL,
		@item_hierarchy_id TINYINT = NULL

)

/*
	DATE			AUTHOR		REMARKS
	2017-07-25		esmart		Initial creation.
	2018-03-30		esmart		product_line_cart_type
	2018-10-22		esmart		Add usage_price for autobilling utility and overage
	2019-08-08		esmart		Add usage_pricing_model
	2019-08-29		esmart		Add opportunity_line_item_id
	2019-11-12		jnavarra	Add equivalent_year_price
	2019-12-09		jnavarra	Rollback equivalent_year_price for deeper testing
	2019-12-09		jnavarra	Re-add equivalent_year_price
	2020-01-14		jnavarra	equivalent_year_price prioritize locale pricing
	2020-02-14		jnavarra	equivalent_year_price product locale fallback to cart locale
	2020-02-19		esmart		vault_id
	2020-05-04		esmart		retention_model, product_platform, cart_order_item_json
	2020-07-29		wbarton		Adding support for an array of multiple vault_ids and datacenters from fn_cart_select_cart_order_item_json
	2020-10-14		cnovac		added logic for storage_gb
	2022-01-07		gblandford	SMCI-6214 - Add retention_term & retention_model_type_id
	2023-03-31      psatish		ECOM-899 Get the storage_GB from cart_order_item table
	2025-10-14      jberry		US-5004939 - Added logic in sec 1.2 to handle equivalent_year_price for capacity orders

	DESCRIPTION
*/

AS
	SET NOCOUNT ON
	BEGIN TRY

	DECLARE @cart_order_id INT,
			@storage_gb INT,
			@cart_locale CHAR(5),
			@response_code INT,
			@message VARCHAR(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @cart_order_id
	SELECT @cart_order_id = cart_order_id, @cart_locale = locale
	FROM cart_order
	WHERE vendor_order_code = @vendor_order_code

	-- 1.2) select
	SELECT i.cart_order_item_id, i.cart_order_id, i.line_item, i.quantity, s.seats, 
		storage_gb = ISNULL(i.storage_gb,dbo.fn_get_item_storage_gb(i.quantity, DEFAULT, i.product_id, DEFAULT, DEFAULT, DEFAULT)),		
		y.years, i.order_item_offer_amount,
	    CASE 
		    WHEN pp.retail_price IS NULL OR y.years IS NULL THEN NULL
		    WHEN jp.usage_pricing_model_id = 2 
			    AND JSON_VALUE(coij.cart_order_item_json, '$.item_total') IS NULL
				AND i.storage_gb < 1024  THEN NULL
			ELSE CONVERT(MONEY, pp.retail_price * y.years) 
	    END AS equivalent_year_price,
		i.list_price, i.unit_price, i.unit_price_pre_vat, i.tax_item_total, i.usage_price, 
		i.product_id, p.product_description, t.product_type_id, t.product_type_description, p.license_keycode_type_id, kt.license_keycode_type_description, lc.license_category_id, lc.license_category_name, lc.license_category_description, pf.product_family_description,
		i.start_date, i.expiration_date, i.cart_item_bundle_id, i.item_hierarchy_id, dependent_cart_order_item_id = d.cart_order_item_id,
		il.keycode, i.license_attribute_license_value, v.license_attribute_license_value_description,
		i.vendor_order_item_code, i.order_item_update_type_id,
		prl.product_line_cart_type, i.discount, i.cart_discount_method_id, i.cart_discount_id, lc.min_order_quantity, lc.max_order_quantity, i.opportunity_line_item_id,
		jp.usage_pricing_model_id, jp.usage_pricing_model_name,
		jp.retention_model_id, jp.retention_model_name, jp.retention_term, jp.retention_model_type_id,
		jp.product_platform_id, jp.product_platform_name,
		jp.vault_id, jp.vault_datac
enter_name, jp.vault,
		jp.product_pricing_level_id, jp.pricing_level_description,
		ij.cart_order_item_json
	FROM cart_order_item i
	INNER JOIN product p
		ON p.product_id = i.product_id
	INNER JOIN product_family pf
		ON pf.product_family_id = p.product_family_id
	INNER JOIN product_line_product plp
		ON plp.product_id = p.product_id
	INNER JOIN product_line prl
		ON plp.product_line_id = prl.product_line_id
	INNER JOIN product_type t
		ON t.product_type_id = p.product_type_id
	LEFT JOIN cart_order_item_json ij
		ON ij.cart_order_item_id = i.cart_order_item_id
	LEFT JOIN product_license_category plc
		ON plc.product_id = p.product_id
	LEFT JOIN license_category lc
		ON lc.license_category_id = plc.license_category_id
	LEFT JOIN license_keycode_type kt
		ON kt.license_keycode_type_id = p.license_keycode_type_id
	LEFT JOIN product_years y
		ON y.product_id = p.product_id
	LEFT JOIN product_seat s
		ON s.product_id = p.product_id
	LEFT JOIN license_attribute_license_value v
		ON v.license_attribute_license_value = i.license_attribute_license_value
	LEFT JOIN cart_order_item_license il
		ON il.cart_order_item_id = i.cart_order_item_id
	LEFT JOIN cart_order_item_json coij
		ON coij.cart_order_item_id = i.cart_order_item_id
	LEFT JOIN (SELECT di.cart_order_item_id, di.cart_order_id, di.line_item, di.cart_item_bundle_id, di.item_hierarchy_id, dlc.license_category_id
				FROM cart_order_item di
				LEFT JOIN product dp
					ON dp.product_id = di.product_id
				LEFT JOIN product_license_category dlc
					ON dlc.product_id = dp.product_id
				WHERE dp.product_type_id IN (1,2)) d
			ON d.cart_order_id = i.cart_order_id AND d.cart_item_bundle_id = i.cart_item_bundle_id AND d.item_hierarchy_id = i.item_hierarchy_id AND (d.license_category_id = plc.license_category_id OR plc.license_category_id IS NULL) AND d.line_item < i.line_item
	OUTER APPLY dbo.fn_locale_to_lang_loc(ISNULL(i.product_locale, @cart_locale)) ll
	OUTER APPLY dbo.fn_cart_select_one_year_products(p.product_id) oyp
	LEFT JOIN dbo.product_pricing pp
		ON pp.product_id = oyp.product_id AND pp.location_code = ll.location_code AND pp.language_code = ll.language_code
	OUTER APPLY fn_cart_select_cart_order_item_json(i.cart_order_item_id) jp
	WHERE i.cart_order_id = @cart_order_id AND
		i.cart_item_bundle_id = CASE WHEN @cart_item_bundle_id IS NULL THEN i.cart_item_bundle_id ELSE @cart_item_bundle_id END AND
		i.item_hierarchy_id = CASE WHEN @item_hierarchy_id IS NULL THEN i.item_hierarchy_id ELSE @item_hierarchy_id END AND
		i.line_item = CASE WHEN @line_item IS NULL THEN i.line_item ELSE @line_item END
		--order by i.cart_item_bundle_id, i.line_item

END TRY

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'Could not select cart_order for vendor_order_code: ' + @vendor_order_code
						ELSE @message END

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXEC usp_LogError @ErrorDB = @DBName

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_order_item_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_item_in_process]

(
	@cart_order_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2014-11-27	acoffel		Added list and unit respectively as retail and net
	2015-01-05	esmart		Add discount_pct and extend_price
	2016-05-25	esmart		Add product family and attribute data
	2016-07-20	cnovac		Added unit_price_per_seat
	2016-11-21	esmart		Add start_date and expiration_date
	2017-04-07	esmart		Fix division by zero
	2017-07-11	cnovac		Fixed issue with unit_price_per_seat and checked for 0 value

	DESCRIPTION
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select i.cart_order_item_in_process_id, i.cart_order_in_process_id, i.vendor_id, i.cart_item_class_id, i.cart_item_bundle_id, i.line_item, i.vendor_product_id, 
		p.product_description,
		i.quantity,
		i.order_item_offer_code, 
		i.order_item_offer_amount, 
		i.retail_price, 
		i.net_price,
		i.discount, 
		i.standard_discount, 
		discount_pct = case when i.retail_price <> 0 then round((i.retail_price - i.net_price)/i.retail_price,2) else 0 end,
		extend_price = i.net_price * i.quantity,
		i.tax_item_total, i.tax_exempt, 
		i.product_id, product_locale, last_modified_date, last_modified_by,
		il.keycode, i.cart_discount_id,
		t.salesforce_product_id,
		pt.product_type_description,
		i.net_price as unit_price,
		isnull(y.years,0) as years,
		isnull(se.seats,0) as seats,
		i.retail_price as list_price,
		i.order_item_update_type_id,
		i.license_attribute_license_value,
		v.license_attribute_license_value_description,
		lc.license_category_name,
		i.net_price/isnull(nullif(se.seats, 0), 1) as unit_price_per_seat,
		i.start_date,
		i.expiration_date
	from cart_order_item_in_process i
	left join cart_order_item_license_in_process il
		on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
	left join product p
		on i.product_id = p.product_id
	left join product_type pt
		on p.product_type_id = pt.product_type_id
	left join product_license_category c
		on p.product_id = c.product_id
	left join license_category lc
		on lc.license_category_id = c.license_category_id
	left join product_years y
		on p.product_id = y.product_id
	left join product_seat se
		on p.product_id = se.product_id
	left join product_pricing_level pl
		on i.pricing_level = pl.pricing_level
	left join sfdc_product_tier t
		on c.license_category_id = t.license_category_id and t.low_range <= i.quantity and i.quantity < t.high_range and p.product_type_id = t.product_type_id and pl.product_pricing_level_id = t.product_pricing_level_id
	left join license l
		on il.keycode = l.keycode
	left join license_seat s
		on l.license_id = s.license_id
	left join license_attribute_license_value v
		on v.license_attribute_license_value = i.license_attribute_license_value
	where cart_order_in_process_id = @cart_order_in_process_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_order_item_in_process_summary]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_item_in_process_summary]

(
	@cart_order_in_process_id int,
	@cart_item_bundle_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2013-03-12	esmart		Add product_line_cart_type
	2013-08-13	esmart		Trial-to-full support as new product
	2013-11-13	esmart		Add bundle description details
	2014-08-20	esmart		Make bundle data nvarchar
	2016-06-06	acoffel		Allow Partner Cart to configure licenses at less than 5 seats
	2017-03-15	acoffel		1.3) New arithmatic on retail_price, net_price, discount, standard_discount

	DESCRIPTION
	select order_item summary
*/

AS
	set nocount on				

	declare	@site_id varchar(20),
			@response_code int,
			@message varchar(100)


	begin try

	declare @item_summary table (cart_item_bundle_id int, product_family_id int, product_line_id int, cart_order_item_in_process_id int, product_id int, keycode varchar(40), product_type_id int, max_product_type_id int,	current_license_category_id int,license_category_id int,current_seats int,seats int,current_storage_gb int,storage_gb int,quantity int,years float,retail_price money,net_price money,discount money,standard_discount money,cart_discount_id int, product_type varchar(50), product_description varchar(200), license_keycode_type_id int, pricing_level varchar(20))

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) add items 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) new product that can be bundled

		insert into @item_summary(cart_item_bundle_id,product_family_id,product_line_id,cart_order_item_in_process_id,product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id,license_keycode_type_id,pricing_level)
		select i.cart_item_bundle_id,  
				p.product_family_id,
				pl.product_line_id,
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = case when pl.product_line_id in (55,300) then max(i.quantity) else max(s.seats) end, 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price), 
				net_price = sum(i.net_price),
				discount = sum(i.discount), 
				standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id),
				license_keycode_type_id = max(p.license_keycode_type_id),
				pricing_level = max(i.pricing_level)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.prod
uct_id
		left join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		where i.cart_order_in_process_id = @cart_order_in_process_id and il.cart_order_item_license_in_process_id is null and p.product_family_id in (1,2,30,31,50,51,55,100,200,300)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id

	-- 1.2) renewal/upgrade products that can be bundled
		insert into @item_summary(cart_item_bundle_id, product_family_id,product_line_id, keycode, cart_order_item_in_process_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id,license_keycode_type_id, pricing_level)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				pl.product_line_id,
				l.keycode, 
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = max(s.seats), 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price), 
				net_price = sum(i.net_price),
				discount = sum(i.discount), 
				standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id),
				license_keycode_type_id = max(p.license_keycode_type_id),
				pricing_level = max(i.pricing_level)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_in_process_id = @cart_order_in_process_id and il.keycode <> '' and p.product_family_id in (1,2,30,31,50,51,100,200)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id,
				l.keycode

	-- 1.3) renewal/upgrade products that can be bundled
		insert into @item_summary(cart_item_bundle_id, product_family_id,product_line_id, keycode, cart_order_item_in_process_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id, license_keycode_type_id,pricing_level)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				pl.product_line_id,
				l.keycode, 
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = case when min(plc.current_license_category_id) = 0 then max(plc.license_category_id) else min(plc.current_license_category_id) end,
				license_category_id = max(plc.license_category_id),
				current_seats = max(st.license_seats), 
				seats = max(i.quantity),
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb)
, 
				quantity = max(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price*i.quantity)/max(i.quantity),
				net_price = sum(i.net_price*i.quantity)/max(i.quantity),
				discount = sum(i.discount*i.quantity)/max(i.quantity),
				standard_discount = sum(i.standard_discount*i.quantity)/max(i.quantity),
				--retail_price = sum(i.retail_price), 
				--net_price = sum(i.net_price),
				--discount = sum(i.discount), 
				--standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id),
				license_keycode_type_id = max(p.license_keycode_type_id),
				pricing_level = max(i.pricing_level)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		inner join license_seat st
			on l.license_id = st.license_id
		where i.cart_order_in_process_id = @cart_order_in_process_id and il.keycode <> '' and p.product_family_id in (55,300)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id,
				l.keycode

	-- 1.4) other products

		insert into @item_summary(cart_item_bundle_id,product_family_id, keycode, cart_order_item_in_process_id, product_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount)
		select i.cart_item_bundle_id,	
				p.product_family_id,
				l.keycode,
				i.cart_order_item_in_process_id,
				p.product_id,
				p.product_type_id,  
				p.product_type_id,
				plc.current_license_category_id,
				plc.license_category_id,
				s.current_seats, 
				s.seats,
				ps.storage_gb, 
				ps.storage_gb, 
				i.quantity, 
				y.years, 
				i.retail_price, 
				i.net_price,
				i.discount, 
				i.standard_discount
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		left join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		left join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_in_process_id = @cart_order_in_process_id and p.product_family_id not in (1,2,30,31,50,51,55,100,200,300)

		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) update
		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		--select * from @item_summary

		-- 2.1) product type and product des
cription
		update @item_summary
		set product_type = case 
								when (keycode is null or max_product_type_id = 1) and s.product_family_id <> 8 then 'New'
								when s.max_product_type_id = 4 and s.product_type_id = 1 then 'New'
								when s.current_license_category_id = s.license_category_id and years > 0 and current_seats = seats and storage_gb > current_storage_gb then 'Renew/Storage Upgrade'
								
								when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years > 0 and current_seats <> seats then ' Upgrade/Renewal'
								--when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years > 0 and current_seats <> seats then convert(varchar(20),(seats - current_seats)) + ' Seat Upgrade/Renewal'
								when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years = 0 then convert(varchar(20),(seats)) + ' Seat Upgrade'

								when s.product_family_id not in (55,300) and s.current_license_category_id = s.license_category_id and years > 0 and current_seats <> seats then ' Upgrade/Renewal'
								when s.product_family_id not in (55,300) and s.current_license_category_id = s.license_category_id and years = 0 and current_seats <> seats then ' Upgrade'
								when s.current_license_category_id is null and current_storage_gb < storage_gb then 'Storage Upgrade'
								when s.current_license_category_id <> s.license_category_id and years = 0 then 'Product Upgrade'
								when s.current_license_category_id <> s.license_category_id and years > 0 then 'Product Upgrade/Renewal'
								when s.current_license_category_id = s.license_category_id and years > 0 and s.product_type_id <> 1 then 'Renewal'
								when s.product_family_id <> 8 then 'New'
							end,
				product_description = case 
						when s.product_family_id in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 then lc.license_category_description  + ' ' + convert(varchar(10),years) + ' Year' + ' ' + convert(varchar(10),seats) + ' Seat '
						when s.product_family_id in (55,300) and p.product_description is null and seats is not null and years = 0 then lc.license_category_description 
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 and storage_gb is null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),years) + ' Year'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 and storage_gb is not null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),storage_gb) + ' GB ' + convert(varchar(10),years) + ' Year'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years = 0 and storage_gb is null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years = 0 and storage_gb is not null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),storage_gb) + ' GB'
						when p.product_description is null then lc.license_category_description
						else p.product_description
					end
		from @item_summary s
		left join product p
			on s.product_id = p.product_id
		left join license_category lc
			on s.license_category_id = lc.license_category_id

		-- 2.2) get bundle details
		declare @cart_discount_bundle_description nvarchar(200), @cart_discount_bundle_details_list nvarchar(1000), @cart_discount_id int, @license_distribution_method_id int, @license_distribution_method_code varchar(4)

		select @cart_discount_bundle_description = car
t_discount_bundle_description, @cart_discount_bundle_details_list = cart_discount_bundle_details_list, @cart_discount_id = m.cart_discount_id
		from cart_discount_bundle b
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join cart_order_message_in_process m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.cart_order_in_process_id = @cart_order_in_process_id

		select @license_distribution_method_id = dm.license_distribution_method_id, @license_distribution_method_code = dm.license_distribution_method_code
		from cart_discount_license_distribution_method b
		inner join license_distribution_method dm
			on b.license_distribution_method_id = dm.license_distribution_method_id
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join cart_order_message_in_process m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.cart_order_in_process_id = @cart_order_in_process_id

		-- 2.3) min seats
		declare @min_seats int, @max_seats int

		select @site_id = site_id from cart_order_in_process where cart_order_in_process_id = @cart_order_in_process_id

		select @min_seats = min(low_range),	
				@max_seats = case 
								when @site_id not in ('WRENTERPRISECART','WRCART') then 5000
								else max(high_range) - 1
							end
		from @item_summary s
		inner join cart_discount_item i
			on s.license_category_id = i.license_category_id
		inner join cart_discount d
			on d.cart_discount_id = i.cart_discount_id
		where d.cart_discount_type_id = 4 and d.cart_discount_status_id = 1 and i.product_type_id = 1 and i.license_category_id not in (100)
			and i.site_display = 1
			
		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) return result
		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select	s.cart_item_bundle_id,
				s.cart_order_item_in_process_id,
				s.product_type,
				p.product_id,
				product_description = s.product_description + ' ' + s.product_type,
				f.product_family_description,
				lc.license_category_name,
				lc.license_category_description,
				s.license_keycode_type_id,
				s.seats,
				s.storage_gb,
				s.quantity,
				s.years,
				s.retail_price,
				s.net_price,
				s.discount,
				s.standard_discount,
				s.pricing_level,
				s.keycode,
				p.product_type_id,
				s.max_product_type_id,
				s.current_license_category_id,
				lc.license_category_id, 
				s.current_seats,
				s.current_storage_gb,
				s.cart_discount_id,
				pl.product_line_cart_type
				,
				cart_discount_bundle_description = case when s.cart_item_bundle_id = 1 then @cart_discount_bundle_description else null end, 
				cart_discount_bundle_details_list = case when s.cart_item_bundle_id = 1 then @cart_discount_bundle_details_list else null end,
				license_distribution_method_id = case when s.cart_item_bundle_id = 1 then @license_distribution_method_id else null end, 
				license_distribution_method_code = case when s.cart_item_bundle_id = 1 then @license_distribution_method_code else null end
				,
				min_seats = case when @site_id in ('RESELLER','MSP') then s.seats else @min_seats end,
				max_seats = @max_seats
		from @item_summary s
		left join product p
			on s.product_id = p.product_id
		left join product_line pl
			on s.product_line_id = pl.product_line_id
		left join product_family f
			on s.product_family_id = f.product_family_id
		left join license_category lc
			on s.license_category_id = lc.license_category_id
		where s.product_type_id is not null and
			s.cart_item_bundle_id = case
										when @cart_item_bundle_id is null then s.cart_item_bundle_id
										else @cart_item_b
undle_id
									end
		order by s.cart_item_bundle_id, net_price desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_order_shipping_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_order_shipping_in_process]

(
	@cart_order_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.

	DESCRIPTION
	select cart shipping in process
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select cart_order_shipping_in_process_id, cart_order_in_process_id, company_name, first_name, last_name, address_1, address_2, city, 
			state, state_description = s.description,
			postal_code, 
			c.country_id, country_description = c.description,
			p.last_modified
	from cart_order_shipping_in_process p
	inner join lu_states s
		on p.state = s.state_id
	inner join lu_countries c
		on p.country_id = c.country_id
	where cart_order_in_process_id = @cart_order_in_process_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_sector]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_sector]

(		
	@cart_sector_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-04-25	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select cart_sector_id, cart_sector_name
	from cart_sector t
	where cart_sector_id = case when @cart_sector_id is null then t.cart_sector_id else @cart_sector_id end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_standard_upsell]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cart_select_cart_standard_upsell]
(
    @keycode VARCHAR(40),
    @product_type_id INT,
    @license_category_name VARCHAR(10),
    @license_seats INT,
    @storage_gb INT,
    @years FLOAT,
    @cart_discount_id INT,
    @language_code VARCHAR(2),
    @location_code VARCHAR(3),
    @cart_sector_id TINYINT,
    @product_line_cart_type VARCHAR(20),
    @backup_cd TINYINT = NULL,
    @license_distribution_method_id INT = NULL,
    @cart_order_id INT = NULL,
    @is_allstate INT = 0,
    @upgrade_path_id INT = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2011-05-25	esmart		Initial creation.
	2018-09-03	esmart		Complimentary upsells
	2020-02-07	jnavarra	Additional template tokens for complimentary upsells
	2020-08-04	abelenkiy	AXIOM-1706: updated complimentary upsell code in 2.2.4.3 to only pass in cart_discount_id if discount specifically has item for license_category, product_type, seats, years
	2022-08-15	gblandford	AIP-33: Handle co-term year matching for allstate candy-rack items dbo.upsell_type.coterm
							and merge in price differential for allstate add-on into wsa additional years upsell
	2022-08-30	gblandford	Always pass 1 seat for wsid add-on when merging term upsells
	2022-10-12	jberry		AIP-75 - Pass is_allstate flag to allow WSAP offering to WAV customers
	2022-11-22	jberry		ECOM-239 - Set cart_discount_id to null for complementary add-on so the base product discount is not applied - sec 2.2.4.3
	2022-12-14	jberry		ECOM-237 - Change multi-year pricing calculation to use retail price to determine year upgrade price difference - sec 2.2.4
	2023-07-21	jberry		ECOM-923: Changed how @license_category_name_allstate_addon is initialized with logic to determine which AIP upsell to use
										Added section 1.4 to determine the current license category to use for upgrades of WSA products
										Added section 3.2 to remove invalid complimentary products from the @upsell_list table
	2023-09-06	jberry		ECOM-2275: Added section 2.2.4.4 to allow adding additional years on AIP Add-on renewals
	2024-02-14	mgolla		ECOM-1481: Added secondary upsell type as 11 for skip level upgrades and added @upgrade_path_id to identify request is coming from Portal or www
	2024-03-07	jberry		ECOM-1441: Added upsell type 12 for special skip level upgrades specific to special upgrade landing page
	2024-03-20	singaravelam	ECOM-2565	Added zuora_product_pricing for renewal/upgrade products and added app_config table to get disti code
	2024-05-09  mgolla		ECOM-3899: Resetting product_type_id to 1 as we need to display new subscriptions for WSAP and									WSAPF products for	license categories WIFI and WSCB, if they originate from the portal.
	2024-05-21	mgolla		ECOM-3858: Added upsell type 13 for WSID and WSIDP products to pull the base price of								 the product, displaying the price difference in Candyrack.
	2024-05-27	singaravelam	ECOM-4285 upgrade product should not include the price difference logics
	2024-06-03	pachanta	ECOM-4744: Upsell string showing incorrectly when we have 2 items in the cart.
	2024-10-15	jberry		ECOM-5598: Add cart upsell type 14 for PC Optimizer and SecureVPN upsells
	2024-10-29	jberry		US-4139212 & US-4195446:  Added a section to remove unneeded upsells for WE (webroot essentials)
                                                      Added cart upsell logic for upsell type 15 license category upsell with seat upgrade
                                                      Changed Zuora pricing logic to use Zuora pricing for all renewals with location code USA
	2025-05-15	jberry		US-3040357 - Changed section 1.4 to use the license distribution method passed into @license_distribution_method_id when the @keycode is NULL

	DESCRIPTION

	select upsell

	DEPENDENCY
	usp_cart_select_bundle_upsell
	usp_cart_select_new_product_set_ENT
	usp_cart_select_new_product_set
	usp_cart_select_renewal_product_set_ENT
	usp_cart_select_renewal_product_set
*/

AS

--SELECT
--@keycode as "@keycode",
--@product_type_id as "@product_type_id",
--@license_category_name as "@license_category_name", 
--@license_seats as "@license_seats", 
--@storage_gb as "@storage_gb", 
--@years as "@years", 
--@cart_discount_id as "@cart_discount_id", 
--@language_code as "@language_code", 
--@location_code as "@location_code",
--@cart_sector_id as "@cart_sector_id",
--@product_line_cart_type as "@product_line_cart_type",
--@backup_cd as "@backup_cd",
--@license_distribution_method_id as "@license_distribution_method_id",
--@cart_order_id as "@cart_order_id"


SET NOCOUNT ON

DECLARE @line_item INT,
        @cart_type_id TINYINT,
        @years2 INT,
        @license_seats2 INT,
        @price_diff MONEY,
        @price_diff_str VARCHAR(20),
        @price_diff_year MONEY,
        @price_diff_year_str VARCHAR(20),
        @pct_diff_year FLOAT,
        @pct_diff_year_str VARCHAR(20),
        @pct_diff_upsell FLOAT,
        @pct_diff_upsell_str VARCHAR(20),
        @cart_upsell_template_text NVARCHAR(200),
        @eq_multi_year_price MONEY,
        @upsell_string VARCHAR(200),
        @cart_upsell_type_id TINYINT,
        @license_category_description VARCHAR(50),
        @current_license_category_name VARCHAR(50),
        @value_str VARCHAR(20),
        @retail_value_str VARCHAR(20),
        @symbol_html VARCHAR(10),
        @symbol_utf8 NVARCHAR(10),
        @product_id INT,
        @coterm TINYINT,
        @license_category_name_allstate_addon VARCHAR(6),
        @current_addon_price MONEY,
        @alt_upsell_string NVARCHAR(200),
        @response_code INT,
        @message VARCHAR(100),
        @license_distribution_method_code VARCHAR(4),
        @PORTAL_CAMPAIGN_ID INT

DECLARE @APP_CONFIG TABLE
(
    [app_config_name] NVARCHAR(50),
    [key] NVARCHAR(50),
    [value] NVARCHAR(MAX)
)

DECLARE @PORTAL_DISTRIBUTION_METHOD TABLE
(
    portal_distribution_method_code VARCHAR(4)
)

DECLARE @PORTAL_LOCATION_CODE TABLE
(
    portal_location_code VARCHAR(4)
)


BEGIN TRY

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	DECLARE @upsell_list TABLE
    (
        upsell_list_id TINYINT IDENTITY(1, 1),
        cart_upsell_id INT,
        cart_upsell_type_id TINYINT,
        coterm TINYINT,
        cart_upsell_type_name VARCHAR(50),
        cart_upsell_template_text NVARCHAR(200),
        cart_upsell_template_supplemental_text VARCHAR(500),
        upsell_string VARCHAR(200),
        price_diff MONEY,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        years FLOAT,
        product_id INT,
        item_hierarchy_id TINYINT
            DEFAULT 1
    );

    -- 1.1) get upsell list
    INSERT INTO @upsell_list
    (
        cart_upsell_id,
        cart_upsell_type_id,
        cart_upsell_type_name,
        coterm,
        cart_upsell_template_text,
        cart_upsell_template_supplemental_text,
        license_category_name,
        license_seats,
        storage_gb,
        years
    )
    SELECT u.cart_upsell_id,
           ut.cart_upsell_type_id,
           ut.cart_upsell_type_name,
           ut.coterm,
           tt.cart_upsell_template_text,
           tt.cart_upsell_template_supplemental_text,
           c.license_category_name,
           st.seats,
  
         cs.storage_gb,
           y.years
    FROM cart_upsell u
        INNER JOIN cart_upsell_product_type pt
            ON u.cart_upsell_id = pt.cart_upsell_id
        INNER JOIN cart_upsell_sector s
            ON u.cart_upsell_id = s.cart_upsell_id
        INNER JOIN cart_upsell_license_category lc
            ON u.cart_upsell_id = lc.cart_upsell_id
        INNER JOIN license_category c
            ON lc.license_category_id = c.license_category_id
        INNER JOIN cart_upsell_seat st
            ON u.cart_upsell_id = st.cart_upsell_id
        INNER JOIN cart_upsell_years y
            ON u.cart_upsell_id = y.cart_upsell_id
        INNER JOIN cart_upsell_type ut
            ON u.cart_upsell_type_id = ut.cart_upsell_type_id
        INNER JOIN cart_upsell_template_mapping m
            ON m.cart_upsell_id = u.cart_upsell_id
        INNER JOIN cart_upsell_template t
            ON t.cart_upsell_template_id = m.cart_upsell_template_id
        INNER JOIN cart_upsell_template_text tt
            ON t.cart_upsell_template_id = tt.cart_upsell_template_id
               AND tt.language_code = @language_code --and tt.location_code = @location_code
        LEFT JOIN cart_upsell_storage cs
            ON u.cart_upsell_id = cs.cart_upsell_id
               AND cs.storage_gb = @storage_gb
        LEFT JOIN cart_upsell_license_distribution_method dm
            ON u.cart_upsell_id = dm.cart_upsell_id
               AND dm.license_distribution_method_id = @license_distribution_method_id
               AND dm.inclusive = 0
    WHERE pt.product_type_id = @product_type_id
          AND c.license_category_name = @license_category_name
          AND st.seats = CASE
                             WHEN @product_line_cart_type = 'Enterprise' THEN
                                 1
                             ELSE
                                 @license_seats
                         END
          AND y.years = @years
          AND s.cart_sector_id = @cart_sector_id
          AND u.cart_upsell_type_id <> 6
          AND dm.cart_upsell_id IS NULL
          AND ut.cart_upsell_type_id = CASE
                                           WHEN ut.cart_upsell_type_id IN ( 11, 12 )
                                                AND
                                                (
                                                    @is_allstate = 1
                                                    /* This is being commented out to allow skip level upgrades for WSAP*/
                                                    --OR
                                                    --(
                                                    --    @cart_sector_id = 5
                                                    --    AND @license_category_name = 'WSAP'
                                                    --)
                                                ) THEN
                                               NULL
                                           ELSE
                                               ut.cart_upsell_type_id
                                       END
          AND lc.upgrade_path = @upgrade_path_id
    ORDER BY ut.type_sort_order

    -- 1.2) currency @symbol_html
    SELECT @symbol_html = symbol_html,
           @symbol_utf8 = symbol_utf8
    FROM currency c
        INNER JOIN currency_language_location ll
            ON c.currency_id = ll.currency_id
    WHERE ll.language_code = @language_code
          AND ll.location_code = @location_code

    -- 1.3) remove upsell for exlusive distribution methods
    DELETE FROM @upsell_list
    WHERE cart_upsell_id IN
          (
              SELECT cart_upsell_id
              FROM cart_upsell_license_distribution_method u
                  INNER JOIN license l
                      ON u.license_distribution_method_id = l.license_distribution_method_id
              WHERE l.keycode = @keycode
          )

    --1
.4) get the current license category on the license 	
    IF @keycode IS NOT NULL
    BEGIN
        SELECT @current_license_category_name = fn.license_category_name,
               @license_distribution_method_code = ldm.license_distribution_method_code
        FROM dbo.license l
            INNER JOIN dbo.license_distribution_method AS ldm
                ON ldm.license_distribution_method_id = l.license_distribution_method_id
            CROSS APPLY dbo.fn_license_select_license_profile(l.license_id) fn
        WHERE l.keycode = @keycode
    END
	ELSE
	BEGIN
	    SELECT @license_distribution_method_code = license_distribution_method_code
	    FROM dbo.license_distribution_method
	    WHERE license_distribution_method_id = @license_distribution_method_id
	END

    --1.5) set license_category_name_allstate_addon
    IF @license_category_name IN ( 'WSAV', 'WSAI', 'WSAC' )
    BEGIN
        SET @license_category_name_allstate_addon
            = CASE
                  WHEN @product_type_id = 1
                       OR
                       (
                           @product_type_id = 2
                           AND @current_license_category_name = @license_category_name
                       ) THEN
        (CASE
             WHEN @license_category_name = 'WSAV' THEN
                 'WSID'
             WHEN @license_category_name = 'WSAI' THEN
                 'WSIDP'
             WHEN @license_category_name = 'WSAC' THEN
                 'WSIDPF'
         END
        )
                  WHEN @product_type_id = 2
                       AND @current_license_category_name <> @license_category_name THEN
        (CASE
             WHEN @current_license_category_name = 'WSAV' THEN
                 'WSIDP'
             WHEN @current_license_category_name = 'WSAI' THEN
                 'WSIDPF'
             WHEN @current_license_category_name = 'WSAC' THEN
                 'WSIDPF'
         END
        )
                  ELSE
                      NULL
              END;
    END;

    ---1.6) get zuora distribution code, campaign id and portal location code
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values](NULL, 'PORTAL') f
    UNION
    SELECT f.app_config_name,
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_LICENSE_CATEGORY', 'ALLSTATE') f
	UNION
	SELECT f.app_config_name,
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_LOCATION_CODE', 'PORTAL') f;

    INSERT INTO @PORTAL_DISTRIBUTION_METHOD
    (
        portal_distribution_method_code
    )
    SELECT ac.[key]
    FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] = 'PORTAL_DISTI_CODES'

    SELECT @PORTAL_CAMPAIGN_ID = ac.[key]
    FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] = 'PORTAL_PRICING_CAMPAIGN_ID'

	INSERT INTO @PORTAL_LOCATION_CODE
	(
	    portal_location_code
	)
    SELECT ac.[key]
    FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] = 'PORTAL_LOCATION_CODE'

	--1.7) remove unneeded upsells for WE (webroot essentials)
	DELETE FROM @upsell_list
	WHERE license_category_name = 'WE'
		  AND (CASE
				   --this removes standard and skip level upgrades for WE 1 device
				   WHEN cart_upsell_type_id IN ( 2, 11 )
						AND license_seats = 1 THEN
					   1
				   --this removes skip level upgrades for WE 3 device
				   WHEN cart_upsell_type_id = 11
						AND license_seats = 3 THEN
					   1
				   --this removes Complementary Co-term products (AIP) for WE 3 and 5 device
				   WHEN cart_upsell_type_id = 9
						AND license_seats IN ( 3, 5 ) THEN
					   1
				   ELSE
					   0
			   END
			  ) = 1;	

    -- ----------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------
    -- 2.) get value, and percents 
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    DECLARE @upsell_list_id TINYINT,
            @max_list_id TINYINT,
            @min_line_item INT,
            @max_line_item INT

    -- 2.1) set up loop
    SELECT @max_list_id = MAX(upsell_list_id)
    FROM @upsell_list
    SELECT @upsell_list_id = 1

    SELECT @line_item = 0
    -- 2.2) gather data
    WHILE @upsell_list_id <= @max_list_id
    BEGIN
        --select * from @upsell_list
        --declare @product_set table(line_item int null,product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money, net_price money,			 product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency varchar(10), cart_discount_id int)
        DECLARE @product_set TABLE
        (
            line_item INT NULL,
            product_id INT,
            product_description VARCHAR(100),
            retail_price MONEY,
            upgrade_price MONEY,
            discount MONEY,
            standard_discount MONEY
                DEFAULT 0,
            net_price MONEY,
            product_type_id INT,
            license_category_name VARCHAR(10),
            seats INT,
            years TINYINT,
            p_type VARCHAR(20),
            currency_id TINYINT,
            currency_code CHAR(3),
            currency_description VARCHAR(20),
            symbol_html VARCHAR(10),
            symbol_utf8 NVARCHAR(10),
            symbol_text VARCHAR(10),
            cart_discount_id INT NULL
        )
        DECLARE @product_set_wsid TABLE
        (
            line_item INT NULL,
            product_id INT,
            product_description VARCHAR(100),
            retail_price MONEY,
            upgrade_price MONEY,
            discount MONEY,
            standard_discount MONEY
                DEFAULT 0,
            net_price MONEY,
            product_type_id INT,
            license_category_name VARCHAR(10),
            seats INT,
            years TINYINT,
            p_type VARCHAR(20),
            currency_id TINYINT,
            currency_code CHAR(3),
            currency_description VARCHAR(20),
            symbol_html VARCHAR(10),
            symbol_utf8 NVARCHAR(10),
            symbol_text VARCHAR(10),
            cart_discount_id INT NULL
        );


        SELECT @cart_upsell_type_id = cart_upsell_type_id,
               @coterm = coterm
        FROM @upsell_list
        WHERE upsell_list_id = @upsell_list_id

        -- 2.2.1) set in baseline 1 yr
        IF @product_type_id = 1
           AND @cart_upsell_type_id IN ( 1, 2, 3, 4, 13 )
        BEGIN
            --print '2.2.1)'
            IF @product_line_cart_type = 'Enterprise'
            BEGIN
                INSERT INTO @product_set
                (
                    product_id,
                    product_description,
                    retail_price,
                    upgrade_price,
                    discount,
                    standard_discount,
                    net_price,
                    product_type_id,
                    license_category_name,
                    seats,
                    years,
                    p_type,
                    currency_id,
                    currency_code,
                    currency_description,
                    symbol_html,
                    symbol_utf8,
                    symbol_text,
                    cart_discount_id
                )
                EXEC usp_cart_select_new_product_set_ENT @license_category_name,
        
                                                 @license_seats,
                                                         @storage_gb,
                                                         @years,
                                                         @cart_discount_id,
                                                         @language_code,
                                                         @location_code
            END
            ELSE
            BEGIN
                INSERT INTO @product_set
                (
                    product_id,
                    product_description,
                    retail_price,
                    upgrade_price,
                    discount,
                    standard_discount,
                    net_price,
                    product_type_id,
                    license_category_name,
                    seats,
                    years,
                    p_type,
                    currency_id,
                    currency_code,
                    currency_description,
                    symbol_html,
                    symbol_utf8,
                    symbol_text,
                    cart_discount_id
                )
                EXEC usp_cart_select_new_product_set @license_category_name,
                                                     @license_seats,
                                                     @storage_gb,
                                                     @years,
                                                     @cart_discount_id,
                                                     @language_code,
                                                     @location_code
            END
        END
        IF @product_type_id IN ( 2, 3 )
           AND @cart_upsell_type_id IN ( 1, 2, 3, 4, 13 )
        BEGIN
            --print '2.2.1) renewal'
            IF @product_line_cart_type = 'Enterprise'
            BEGIN
                INSERT INTO @product_set
                (
                    product_id,
                    product_description,
                    retail_price,
                    upgrade_price,
                    discount,
                    standard_discount,
                    net_price,
                    product_type_id,
                    license_category_name,
                    seats,
                    years,
                    p_type,
                    currency_id,
                    currency_code,
                    currency_description,
                    symbol_html,
                    symbol_utf8,
                    symbol_text,
                    cart_discount_id
                )
                EXEC usp_cart_select_renewal_product_set_ENT @keycode,
                                                             @license_category_name,
                                                             @license_seats,
                                                             @storage_gb,
                                                             @years,
                                                             @cart_discount_id,
                                                             @language_code,
                                                             @location_code
            END
            ELSE
            BEGIN
                INSERT INTO @product_set
                (
                    product_id,
                    product_description,
                    retail_price,
                    upgrade_price,
                    discount,
                    standard_discount,
                    net_price,
                    product_type_id,
                    license_category_name,
                    seats,
                    years,
                    p_type,
                    currency_id,
                    currency_code,
                    currency_description,
              
      symbol_html,
                    symbol_utf8,
                    symbol_text,
                    cart_discount_id
                )
                EXEC usp_cart_select_renewal_product_set @keycode,
                                                         @license_category_name,
                                                         @license_seats,
                                                         @storage_gb,
                                                         @years,
                                                         @cart_discount_id,
                                                         @language_code,
                                                         @location_code

            END
        END

        --Setting product_type_id to 1 if they originating from Portal
        IF @upgrade_path_id = 1
           AND @license_category_name IN
               (
                   SELECT [key]
                   FROM @APP_CONFIG
                   WHERE [app_config_name] = 'PORTAL_LICENSE_CATEGORY'
               )
        BEGIN
            SELECT @product_type_id = 1
        END

        --select @line_item = 0
        UPDATE @product_set
        SET line_item = @line_item
        WHERE line_item IS NULL


        --select @line_item = 1
        --update @product_set set line_item = @line_item where line_item is null

        -- 2.2.3) updated price and products
        IF @cart_upsell_type_id = 1
        BEGIN
            -- 2.2.3.1 Additional year
            SELECT @years2 = @years + 1
        END

        IF @cart_upsell_type_id = 3
        BEGIN
            -- 2.2.3.3 Seat upgrade
            SELECT @years2 = @years
            SELECT @license_seats2 = CASE
                                         WHEN @product_line_cart_type = 'Enterprise' THEN
                                             @license_seats
                                         ELSE
                                             s.seats
                                     END
            FROM product_license_category_seat s
                INNER JOIN license_category c
                    ON s.license_category_id = c.license_category_id
            WHERE c.license_category_name = @license_category_name
                  AND s.seats > @license_seats
            ORDER BY s.seats DESC
        END


        IF @cart_upsell_type_id IN ( 2, 11, 12, 15 )
        BEGIN
            -- 2.2.3.2 License category upgrade
            SELECT @years2 = @years;

            IF @is_allstate = 1
            BEGIN
                SELECT @license_category_name = lc.license_category_name,
                       @license_category_description = lc.license_category_description,
                       @license_seats2 = plc.seats
                FROM dbo.license_category lc
                    JOIN dbo.product_license_category_seat plc
                        ON plc.license_category_id = lc.license_category_id
                WHERE lc.license_category_id = 136;
            END;
            ELSE IF @cart_upsell_type_id = 12
            BEGIN
            SELECT @license_category_name = c2.license_category_name,
                    @license_category_description = c2.license_category_description
            FROM product_license_category_upgrade u
                INNER JOIN license_category c
                    ON u.license_category_id = c.license_category_id
                INNER JOIN license_category c2
                    ON u.upgrade_license_category_id = c2.license_category_id
                INNER JOIN @upsell_list ul
                    ON ul.license_category_name = c.license_category_name
            WHERE c2.license_category_name <> @license_category_name
                    AND u.upgrade_path = @upgrade_path_id
                    AND u.location_code = @location_code
                    AND u.language_code = @language_code
                    AND c2.l
icense_category_name NOT IN
                        (
                            SELECT license_category_name FROM @upsell_list
                        )
            ORDER BY c2.license_category_id DESC;

            SELECT @years2 = 0;

            SELECT @license_seats2 = CASE
                                            WHEN @product_line_cart_type = 'Enterprise' THEN
                                                @license_seats
                                            ELSE
                                                s.seats
                                        END
            FROM product_license_category_seat s
                INNER JOIN license_category c
                    ON s.license_category_id = c.license_category_id
            WHERE c.license_category_name = @license_category_name
                    AND s.seats >= CASE
                                        WHEN @license_category_name = 'WSAC'
                                            AND @license_seats IN ( 1, 3 ) THEN
                                            5
                                        ELSE
                                            @license_seats
                                    END
            ORDER BY s.seats DESC;
            END;
            ELSE IF @cart_upsell_type_id = 15  --license category with seat upgrade
            BEGIN
			SELECT @license_category_name = c2.license_category_name,
				   @license_category_description = c2.license_category_description
			FROM product_license_category_upgrade u
				INNER JOIN license_category c
					ON u.license_category_id = c.license_category_id
				INNER JOIN license_category c2
					ON u.upgrade_license_category_id = c2.license_category_id
			WHERE c.license_category_name = @license_category_name
				  AND c2.license_category_name <> @current_license_category_name
				  AND u.upgrade_path = @upgrade_path_id
				  AND u.location_code = @location_code
			ORDER BY c2.license_category_id DESC;

			SELECT @license_seats2 = s.seats
			FROM product_license_category_seat s
				INNER JOIN license_category c
					ON s.license_category_id = c.license_category_id
			WHERE c.license_category_name = @license_category_name
				  AND s.seats = CASE
									WHEN @license_seats = 1 THEN
										3
									WHEN @license_seats = 3 THEN
										5
									ELSE
										@license_seats
								END
			ORDER BY s.seats DESC;
			END
			ELSE
            BEGIN
			SELECT @license_category_name = c2.license_category_name,
				   @license_category_description = c2.license_category_description
			FROM product_license_category_upgrade u
				INNER JOIN license_category c
					ON u.license_category_id = c.license_category_id
				INNER JOIN license_category c2
					ON u.upgrade_license_category_id = c2.license_category_id
			WHERE c.license_category_name = @license_category_name
				  AND c2.license_category_name <> @license_category_name
				  AND u.upgrade_path = @upgrade_path_id
				  AND u.location_code = @location_code
				  AND u.language_code = @language_code
				  --this blocks the WSAP to WSAPF standard license category upsell
				  AND CASE
						  WHEN c.license_category_name = 'WSAP'
							   AND @cart_upsell_type_id = 2 THEN
							  'WTP'
						  ELSE
							  c2.license_category_name
					  END = c2.license_category_name
			ORDER BY c2.license_category_id DESC;


                --If we don't have an equal number of seats available, we will increase the seat count for skip-level products.
                SELECT @license_seats2 = CASE
                                             WHEN @product_line_cart_type = 'Enterprise' THEN
                                                 @license_seats
                                             ELSE
                                                 s.seats
                                         END
                FROM product_license_category_seat s
            
        INNER JOIN license_category c
                        ON s.license_category_id = c.license_category_id
                WHERE c.license_category_name = @license_category_name
                      AND s.seats >= CASE
                                         WHEN @license_category_name = 'WSAC'
                                              AND @license_seats IN ( 1, 3 ) THEN
                                             5
                                         ELSE
                                             @license_seats
                                     END
                ORDER BY s.seats DESC

            END
        END


        IF @cart_upsell_type_id = 4
        BEGIN
            -- 2.2.3.4 Storage upgrade
            SELECT @years2 = @years
            SELECT @storage_gb = s.storage_gb
            FROM product_license_category_storage s
                INNER JOIN license_category c
                    ON s.license_category_id = c.license_category_id
            WHERE c.license_category_name = @license_category_name
                  AND s.storage_gb > @storage_gb
            ORDER BY s.storage_gb DESC
        END

        -- select license_seats = @license_seats, license_seats2 = @license_seats2

        IF @license_seats2 IS NULL
        BEGIN
            SELECT @license_seats2 = @license_seats
        END

        IF @cart_upsell_type_id IN ( 1, 2, 3, 4, 11, 12, 15 )
        BEGIN
            -- 2.2.3.5 Upgrade product set
            --print '2.2.3.5 Upgrade product set'
            --print '@license_seats2: ' + convert(varchar(10),@license_seats2)
            IF @product_type_id = 1
            BEGIN
                IF @product_line_cart_type = 'Enterprise'
                BEGIN
                    --if @license_seats2 is null begin select @license_seats2 = @license_seats end

                    INSERT INTO @product_set
                    (
                        product_id,
                        product_description,
                        retail_price,
                        upgrade_price,
                        discount,
                        standard_discount,
                        net_price,
                        product_type_id,
                        license_category_name,
                        seats,
                        years,
                        p_type,
                        currency_id,
                        currency_code,
                        currency_description,
                        symbol_html,
                        symbol_utf8,
                        symbol_text,
                        cart_discount_id
                    )
                    EXEC usp_cart_select_new_product_set_ENT @license_category_name,
                                                             @license_seats2,
                                                             @storage_gb,
                                                             @years2,
                                                             @cart_discount_id,
                                                             @language_code,
                                                             @location_code
                END
                ELSE
                BEGIN
                    INSERT INTO @product_set
                    (
                        product_id,
                        product_description,
                        retail_price,
                        upgrade_price,
                        discount,
                        standard_discount,
                        net_price,
                        product_type_id,
                        license_category_name,
                        seats,
                        years,
                        p_type,
                        currency_id,
                        currency_code,
                        currency_description,
            
            symbol_html,
                        symbol_utf8,
                        symbol_text,
                        cart_discount_id
                    )
                    EXEC usp_cart_select_new_product_set @license_category_name,
                                                         @license_seats2,
                                                         @storage_gb,
                                                         @years2,
                                                         @cart_discount_id,
                                                         @language_code,
                                                         @location_code
                END
            END
            ELSE
            BEGIN
                IF @product_line_cart_type = 'Enterprise'
                BEGIN
                    --if @license_seats2 is null begin select @license_seats2 = @license_seats end

                    INSERT INTO @product_set
                    (
                        product_id,
                        product_description,
                        retail_price,
                        upgrade_price,
                        discount,
                        standard_discount,
                        net_price,
                        product_type_id,
                        license_category_name,
                        seats,
                        years,
                        p_type,
                        currency_id,
                        currency_code,
                        currency_description,
                        symbol_html,
                        symbol_utf8,
                        symbol_text,
                        cart_discount_id
                    )
                    EXEC usp_cart_select_renewal_product_set_ENT @keycode,
                                                                 @license_category_name,
                                                                 @license_seats2,
                                                                 @storage_gb,
                                                                 @years2,
                                                                 @cart_discount_id,
                                                                 @language_code,
                                                                 @location_code
                END
                ELSE
                BEGIN
                    INSERT INTO @product_set
                    (
                        product_id,
                        product_description,
                        retail_price,
                        upgrade_price,
                        discount,
                        standard_discount,
                        net_price,
                        product_type_id,
                        license_category_name,
                        seats,
                        years,
                        p_type,
                        currency_id,
                        currency_code,
                        currency_description,
                        symbol_html,
                        symbol_utf8,
                        symbol_text,
                        cart_discount_id
                    )
                    EXEC usp_cart_select_renewal_product_set @keycode,
                                                             @license_category_name,
                                                             @license_seats2,
                                                             @storage_gb,
                                                             @years2,
                                                             @cart_discount_id,
                                                             @language_code,
                                                             @location_code
                END
            END
       
 END

        SELECT @line_item = @line_item + 1
        UPDATE @product_set
        SET line_item = @line_item
        WHERE line_item IS NULL

        -- 2.2.4) get pricing and percents
        SELECT @min_line_item = MIN(line_item),
               @max_line_item = MAX(line_item)
        FROM @product_set

        IF @cart_upsell_type_id = 1
        BEGIN
            SELECT @eq_multi_year_price = CASE
                                              WHEN @product_line_cart_type = 'Enterprise' THEN
            (
                SELECT SUM(net_price)FROM @product_set WHERE line_item = @min_line_item
            ) +
            (
                SELECT SUM(net_price)FROM @product_set WHERE line_item = @min_line_item
            )
                                              ELSE
                (
            (
                SELECT SUM(retail_price)
                FROM @product_set
                WHERE line_item = @min_line_item
            ) / @years
                ) * @years2
                                          END

            SELECT @price_diff =
            (
                SELECT SUM(retail_price)
                FROM @product_set
                WHERE line_item = @max_line_item
            ) -
            (
                SELECT SUM(retail_price)
                FROM @product_set
                WHERE line_item = @min_line_item
            ) --added for ECOM-237
              --select @price_diff = (select sum(net_price) from @product_set where line_item = @max_line_item) - (select sum(net_price) from @product_set where line_item = @min_line_item)  --removed for ECOM-237

            SELECT @price_diff_year = (@eq_multi_year_price -
            (
                SELECT SUM(net_price)FROM @product_set WHERE line_item = @max_line_item
            )
                                      ) / @years2

            SELECT @pct_diff_year = ROUND(@price_diff / @eq_multi_year_price, 2)
            -- select @pct_diff_year = round(@price_diff_year/(select sum(net_price) from @product_set where line_item = @min_line_item),2)


            -- 2.2.4.1) check if we need to merge in additional year pricing on allstate add-on
            -- and look for alt merge text by pulling in upsell for the addon
            IF @license_category_name <> @license_category_name_allstate_addon
            BEGIN
                SELECT @current_addon_price = coi.unit_price
                FROM dbo.cart_order_item coi
                    INNER JOIN dbo.product p
                        ON p.product_id = coi.product_id
                    INNER JOIN dbo.product_license_category plp
                        ON plp.product_id = p.product_id
                    INNER JOIN dbo.license_category lc
                        ON lc.license_category_id = plp.license_category_id
                WHERE cart_order_id = @cart_order_id
                      AND lc.license_category_name = @license_category_name_allstate_addon;

                IF ISNULL(@current_addon_price, 0) > 0
                BEGIN

                    INSERT INTO @product_set_wsid
                    (
                        product_id,
                        product_description,
                        retail_price,
                        upgrade_price,
                        discount,
                        standard_discount,
                        net_price,
                        product_type_id,
                        license_category_name,
                        seats,
                        years,
                        p_type,
                        currency_id,
                        currency_code,
                        currency_description,
                        symbol_html,
                        symbol_utf8,
                        symbol_text,
                        cart_discount_id
                    )
                    EXEC dbo.usp_cart_select_new_product_set @l
icense_category_name_allstate_addon,
                                                             1,
                                                             @storage_gb,
                                                             @years2,
                                                             @cart_discount_id,
                                                             @language_code,
                                                             @location_code
                    /*override Zuora product price if keycode migrated to zuora*/
					IF @product_line_cart_type = 'Consumer'
					   AND
					   (
						   @license_distribution_method_code IN
						   (
							   SELECT portal_distribution_method_code FROM @PORTAL_DISTRIBUTION_METHOD
						   )
						   OR @location_code IN
							  (
								  SELECT portal_location_code FROM @PORTAL_LOCATION_CODE
							  )
					   )
                    BEGIN
                        UPDATE ps
                        SET ps.retail_price = CASE
                                                  WHEN zpp.product_type_id = 2 THEN
                                                      zpp.renewal_price
                                                  ELSE
                                                      zpp.retail_price
                                              END,
                            ps.discount = zpp.discount,
                            ps.standard_discount = 0,
                            ps.upgrade_price = CASE
                                                   WHEN zpp.product_type_id = 2 THEN
                                                       zpp.renewal_price
                                                   ELSE
                                                       zpp.retail_price
                                               END,
                            ps.net_price = CASE
                                               WHEN zpp.product_type_id = 2 THEN
                                                   zpp.renewal_price
                                               ELSE
                                                   zpp.retail_price
                                           END
                        FROM @product_set_wsid AS ps
                            JOIN dbo.zuora_product_pricing AS zpp
                                ON ps.product_id = zpp.product_id
                        WHERE zpp.campaign_id = @PORTAL_CAMPAIGN_ID

                    END

                    SELECT @price_diff = @price_diff + (
                    (
                        SELECT net_price FROM @product_set_wsid
                    ) - @current_addon_price
                                                       );

                    SELECT @alt_upsell_string = tt.cart_upsell_template_text
                    FROM cart_upsell u
                        INNER JOIN cart_upsell_product_type pt
                            ON u.cart_upsell_id = pt.cart_upsell_id
                        INNER JOIN cart_upsell_sector s
                            ON u.cart_upsell_id = s.cart_upsell_id
                        INNER JOIN cart_upsell_license_category lc
                            ON u.cart_upsell_id = lc.cart_upsell_id
                        INNER JOIN license_category c
                            ON lc.license_category_id = c.license_category_id
                        INNER JOIN cart_upsell_seat st
                            ON u.cart_upsell_id = st.cart_upsell_id
                        INNER JOIN cart_upsell_years y
                            ON u.cart_upsell_id = y.cart_upsell_id
                        INNER JOIN cart_upsell_type ut
                            ON u.cart_upsell_type_id = ut.cart_upsell_type_id
                        INNER JOIN cart_upsell_template_mapping m
                            ON m.cart_upsell_id = u.cart_upsell_id
                        INNER JOIN cart_
upsell_template t
                            ON t.cart_upsell_template_id = m.cart_upsell_template_id
                        INNER JOIN cart_upsell_template_text tt
                            ON t.cart_upsell_template_id = tt.cart_upsell_template_id
                               AND tt.language_code = @language_code
                        LEFT JOIN cart_upsell_storage cs
                            ON u.cart_upsell_id = cs.cart_upsell_id
                               AND cs.storage_gb = @storage_gb
                        LEFT JOIN cart_upsell_license_distribution_method dm
                            ON u.cart_upsell_id = dm.cart_upsell_id
                               AND dm.license_distribution_method_id = @license_distribution_method_id
                               AND dm.inclusive = 0
                    WHERE pt.product_type_id = @product_type_id
                          AND c.license_category_name = @license_category_name_allstate_addon
                          AND st.seats = CASE
                                             WHEN @product_line_cart_type = 'Enterprise' THEN
                                                 1
                                             ELSE
                                                 @license_seats
                                         END
                          AND y.years = @years
                          AND s.cart_sector_id = @cart_sector_id
                          AND u.cart_upsell_type_id NOT IN ( 1, 2, 3, 4, 6, 9, 5, 11, 12, 13 )
                          AND dm.cart_upsell_id IS NULL
                    ORDER BY ut.type_sort_order

                    IF @alt_upsell_string IS NOT NULL
                    BEGIN
                        UPDATE u
                        SET u.cart_upsell_template_text = @alt_upsell_string
                        FROM @upsell_list u
                        WHERE u.upsell_list_id = @upsell_list_id
                    END
                END
            END
        END

        -- 2.2.4.2) get price diff and pct_diff_upsell for license category, seat, storeage and skip level upgrades
        IF @cart_upsell_type_id IN ( 2, 3, 4, 11, 15 )
        BEGIN
		    --- Zuora price differece included in retail price itself
			IF @product_line_cart_type = 'Consumer'
				AND
				(
					@license_distribution_method_code IN
					(
						SELECT portal_distribution_method_code FROM @PORTAL_DISTRIBUTION_METHOD
					)
					OR @location_code IN
						(
							SELECT portal_location_code FROM @PORTAL_LOCATION_CODE
						)
				)
			BEGIN
				SELECT @price_diff =
				(
					SELECT retail_price
					FROM @product_set AS ps
					WHERE ps.line_item = @max_line_item
						  AND ps.product_type_id = 2
				);
			END;
            ELSE
            BEGIN

                SELECT @price_diff =
                (
                    SELECT SUM(net_price)FROM @product_set WHERE line_item = @max_line_item
                ) -
                (
                    SELECT SUM(net_price)FROM @product_set WHERE line_item = @min_line_item
                )
                SELECT @pct_diff_upsell = (
                (
                    SELECT SUM(net_price)FROM @product_set WHERE line_item = @max_line_item
                ) -
                (
                    SELECT SUM(net_price)FROM @product_set WHERE line_item = @min_line_item
                )
                                          ) / (
                (
                    SELECT SUM(net_price)FROM @product_set WHERE line_item = @max_line_item
                )
                                              )


            --select price_diff = @price_diff, pct_diff_upsell = @pct_diff_upsell
            END
        END


        IF @cart_upsell_type_id = 12
        BEGIN
            SELECT @price_diff =
            (
                SELECT upgrade_price FROM @product_set WHERE p_type = 'Upgrade'
            );
  
          SELECT @pct_diff_upsell = 0;
        END;

        IF @cart_upsell_type_id IN ( 5, 9, 14 )
        -- 2.2.4.3) complimentary product
        BEGIN
            ----We are deleting data in the Product Set table, as we are displaying the same price for the complementary product.
            DELETE FROM @product_set
            --print '-- 2.2.4.3)'
            DECLARE @license_category_name_comp VARCHAR(20),
                    @license_seats_comp INT,
                    @storage_gb_comp INT,
                    @years_comp INT,
                    @cart_discount_id_comp INT

            SELECT DISTINCT
                   @license_category_name_comp = i.license_category_name,
                   @license_seats_comp = i.license_seats,
                   @storage_gb_comp = i.storage_gb,
                   @years_comp = i.years,
                   @cart_discount_id_comp = NULL --set cart_discount_id to null for complementary add-on
            FROM cart_discount_item i
                INNER JOIN cart_upsell_discount d
                    ON i.cart_discount_id = d.cart_discount_id
                INNER JOIN @upsell_list u
                    ON d.cart_upsell_id = u.cart_upsell_id
                INNER JOIN cart_upsell_product_type cupt
                    ON cupt.cart_upsell_id = u.cart_upsell_id
                LEFT JOIN cart_discount_item cdi
                    ON cdi.license_category_name = u.license_category_name
                       AND cdi.product_type_id = cupt.product_type_id
                       AND cdi.license_seats = u.license_seats
                       AND cdi.years = u.years
                       AND cdi.cart_discount_id = @cart_discount_id
            WHERE u.upsell_list_id = @upsell_list_id
                  AND i.years = (CASE
                                     WHEN u.coterm = 1 THEN
                                         @years
                                     ELSE
                                         i.years
                                 END
                                );

            --select @license_category_name_comp  ,@license_seats_comp  ,@storage_gb_comp  ,@years_comp  ,@cart_discount_id ,@language_code  ,@location_code, @cart_upsell_type_id

            INSERT INTO @product_set
            (
                product_id,
                product_description,
                retail_price,
                upgrade_price,
                discount,
                standard_discount,
                net_price,
                product_type_id,
                license_category_name,
                seats,
                years,
                p_type,
                currency_id,
                currency_code,
                currency_description,
                symbol_html,
                symbol_utf8,
                symbol_text,
                cart_discount_id
            )
            EXEC usp_cart_select_new_product_set @license_category_name_comp,
                                                 @license_seats_comp,
                                                 @storage_gb_comp,
                                                 @years_comp,
                                                 @cart_discount_id_comp,
                                                 @language_code,
                                                 @location_code            

			/*override Zuora product price if keycode migrated to zuora*/
			IF @product_line_cart_type = 'Consumer'
				AND
				(
					@license_distribution_method_code IN
					(
						SELECT portal_distribution_method_code FROM @PORTAL_DISTRIBUTION_METHOD
					)
					OR @location_code IN
						(
							SELECT portal_location_code FROM @PORTAL_LOCATION_CODE
						)
				)
            BEGIN

                UPDATE ps
                SET ps.retail_price = CASE
                                          WHEN zpp.product_type_id = 2 THEN
          
                                    zpp.renewal_price
                                          ELSE
                                              zpp.retail_price
                                      END,
                    ps.discount = zpp.discount,
                    ps.standard_discount = 0,
                    ps.upgrade_price = CASE
                                           WHEN zpp.product_type_id = 2 THEN
                                               zpp.renewal_price
                                           ELSE
                                               zpp.retail_price
                                       END,
                    ps.net_price = CASE
                                       WHEN zpp.product_type_id = 2 THEN
                                           zpp.renewal_price
                                       ELSE
                                           zpp.retail_price
                                   END
                FROM @product_set AS ps
                    JOIN dbo.zuora_product_pricing AS zpp
                        ON ps.product_id = zpp.product_id
                WHERE zpp.campaign_id = @PORTAL_CAMPAIGN_ID
            END


            SELECT @retail_value_str =
            (
                SELECT @symbol_utf8 + CONVERT(VARCHAR(20), retail_price)
                FROM @product_set
            )
            SELECT @value_str =
            (
                SELECT @symbol_utf8 + CONVERT(VARCHAR(20), net_price)FROM @product_set
            )

            --select @retail_value_str, @value_str

            UPDATE @upsell_list
            SET upsell_string = REPLACE(
                                           REPLACE(
                                                      REPLACE(
                                                                 REPLACE(
                                                                            REPLACE(
                                                                                       cart_upsell_template_text,
                                                                                       '<value>',
                                                                                       @value_str
                                                                                   ),
                                                                            '<retail_value>',
                                                                            @retail_value_str
                                                                        ),
                                                                 '<seats>',
                                                                 ISNULL(@license_seats_comp, '')
                                                             ),
                                                      '<storage_gb>',
                                                      ISNULL(@storage_gb_comp, '')
                                                  ),
                                           '<license_category>',
                                           @license_category_name_comp
                                       ),
                price_diff =
                (
                    SELECT net_price FROM @product_set
                ),
                years = @years_comp,
                license_seats = @license_seats_comp,
                storage_gb = @storage_gb_comp,
                license_category_name = @license_category_name_comp
            WHERE upsell_list_id = @upsell_list_id
        END

        -- 2.2.4.4) additional year on standalone AIP Add-on
        IF @cart_upsell_type_id = 10
        BEGIN
            --print '-- 2.2.4.4) additional year on standalone AIP Add-on'

            --confirm there is not a WSA product in the cart to prevent duplicate add-a-year offerings
            IF NOT EXISTS
            (
      
          SELECT 1
                FROM dbo.cart_order_item coi
                    JOIN dbo.cart_order co
                        ON co.cart_order_id = coi.cart_order_id
                    JOIN dbo.product p
                        ON p.product_id = coi.product_id
                    JOIN dbo.product_license_category plc
                        ON plc.product_id = p.product_id
                    JOIN dbo.license_category lc
                        ON lc.license_category_id = plc.license_category_id
                WHERE coi.cart_order_id = @cart_order_id
                      AND lc.license_category_name LIKE 'WSA%'
            )
            BEGIN
                SELECT @years2 = @years + 1

                SELECT @current_addon_price = coi.unit_price
                FROM dbo.cart_order_item coi
                WHERE coi.cart_order_id = @cart_order_id
                AND line_item = 1

                --select @license_category_name as "@license_category_name", @years2 as "@years2", @license_seats as "@license_seats", @storage_gb as "@storage_gb", @language_code as "@language_code"  ,@location_code as "@location_code", @current_addon_price as "@current_addon_price"

                INSERT INTO @product_set
                (
                    product_id,
                    product_description,
                    retail_price,
                    upgrade_price,
                    discount,
                    standard_discount,
                    net_price,
                    product_type_id,
                    license_category_name,
                    seats,
                    years,
                    p_type,
                    currency_id,
                    currency_code,
                    currency_description,
                    symbol_html,
                    symbol_utf8,
                    symbol_text,
                    cart_discount_id
                )
                EXEC usp_cart_select_new_product_set @license_category_name,
                                                     @license_seats,
                                                     @storage_gb,
                                                     @years2,
                                                     @cart_discount_id,
                                                     @language_code,
                                                     @location_code
                /*override Zuora product price if keycode migrated to zuora*/
				IF @product_line_cart_type = 'Consumer'
					AND
					(
						@license_distribution_method_code IN
						(
							SELECT portal_distribution_method_code FROM @PORTAL_DISTRIBUTION_METHOD
						)
						OR @location_code IN
							(
								SELECT portal_location_code FROM @PORTAL_LOCATION_CODE
							)
					)
                BEGIN
                    UPDATE ps
                    SET ps.retail_price = CASE
                                              WHEN zpp.product_type_id = 2 THEN
                                                  zpp.renewal_price
                                              ELSE
                                                  zpp.retail_price
                                          END,
                        ps.discount = zpp.discount,
                        ps.standard_discount = 0,
                        ps.upgrade_price = CASE
                                               WHEN zpp.product_type_id = 2 THEN
                                                   zpp.renewal_price
                                               ELSE
                                                   zpp.retail_price
                                           END,
                        ps.net_price = CASE
                                           WHEN zpp.product_type_id = 2 THEN
                                               zpp.renewal_price
                                           ELSE
            
                                   zpp.retail_price
                                       END
                    FROM @product_set AS ps
                        JOIN dbo.zuora_product_pricing AS zpp
                            ON ps.product_id = zpp.product_id
                    WHERE zpp.campaign_id = @PORTAL_CAMPAIGN_ID
                END

                SELECT @retail_value_str =
                (
                    SELECT @symbol_utf8 + CONVERT(VARCHAR(20), retail_price - @current_addon_price)
                    FROM @product_set
                )
                SELECT @value_str =
                (
                    SELECT @symbol_utf8 + CONVERT(VARCHAR(20), net_price - @current_addon_price)
                    FROM @product_set
                )

                --select @retail_value_str as "@retail_value_str", @value_str as "@value_str"

                UPDATE @upsell_list
                SET upsell_string = REPLACE(
                                               REPLACE(
                                                          REPLACE(
                                                                     REPLACE(
                                                                                cart_upsell_template_text,
                                                                                '<value>',
                                                                                @value_str
                                                                            ),
                                                                     '<retail_value>',
                                                                     @retail_value_str
                                                                 ),
                                                          '<seats>',
                                                          ISNULL(@license_seats_comp, '')
                                                      ),
                                               '<storage_gb>',
                                               ISNULL(@storage_gb_comp, '')
                                           ),
                    price_diff =
                    (
                        SELECT net_price FROM @product_set
                    ) - @current_addon_price,
                    years = @years2
                WHERE upsell_list_id = @upsell_list_id

                UPDATE @upsell_list
                SET upsell_string = LEFT(upsell_string, CHARINDEX('-', upsell_string) - 2)
            END

            DELETE FROM @product_set
            WHERE line_item IS NULL

        END

        -- 2.3) get string values
        SELECT @price_diff_str = @symbol_utf8 + CONVERT(VARCHAR(20), @price_diff)
        SELECT @price_diff_year_str = @symbol_utf8 + CONVERT(VARCHAR(20), CONVERT(INT, FLOOR(@price_diff_year)))
        SELECT @pct_diff_year_str = CONVERT(VARCHAR(20), @pct_diff_year * 100) + '%'

        -- 2.4) update list
        IF @cart_upsell_type_id IN ( 1, 2, 3, 4, 11, 12, 15 )
        BEGIN
            UPDATE @upsell_list
            SET upsell_string =  REPLACE(
                                           REPLACE(
                                                      REPLACE(
                                                                 REPLACE(
                                                                            REPLACE(
                                                                                       cart_upsell_template_text,
                                                                                       '<value>',
                                                                                       @price_diff_str
                                                                                   ),
                                                                            '<percent>',
                         
                                                   ISNULL(@pct_diff_year_str, '')
                                                                        ),
                                                                 '<license_category>',
                                                                 ISNULL(@license_category_description, '')
                                                             ),
                                                      '<seats>',
                                                      ISNULL(@license_seats, '')
                                                  ),
                                           '<storage_gb>',
                                           ISNULL(@storage_gb, '')
                                       ),
                years = @years2,
                license_seats = @license_seats2,
                storage_gb = @storage_gb,
                license_category_name = @license_category_name,
                price_diff = @price_diff
            WHERE upsell_list_id = @upsell_list_id
        END

        -- 2.5) update variables
        -------Retain the base product here to compare its price difference with the skip-level product.
        DELETE FROM @product_set
        WHERE line_item = @line_item 
        SET @license_seats2 = NULL
        SELECT @upsell_list_id = @upsell_list_id + 1
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) check for complimentary product in cart
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    --3.1) Remove complimentary product from the candy rack once they have been added to the cart
    DELETE u
    FROM @upsell_list u
        INNER JOIN license_category lc
            ON lc.license_category_name = u.license_category_name
        INNER JOIN product_license_category plc
            ON plc.license_category_id = lc.license_category_id
        INNER JOIN cart_order_item i
            ON i.product_id = plc.product_id
    WHERE u.cart_upsell_type_id IN ( 5, 9 )
          AND i.cart_order_id = @cart_order_id

    --3.2) Remove invalid complimentary co-term products from @upsell_list	
    --select @product_type_id as "@product_type_id", @license_category_name as "@license_category_name", @license_category_name_allstate_addon as "@license_category_name_allstate_addon", @current_license_category_name as "@current_license_category_name"
    --select * from @upsell_list
    IF @upgrade_path_id = 0
    BEGIN
        DELETE u
        FROM @upsell_list u
        WHERE u.cart_upsell_type_id = 9
              AND u.license_category_name <> @license_category_name_allstate_addon
              AND @license_category_name_allstate_addon IS NOT NULL
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 4.) backup CD
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF @backup_cd = 0
    BEGIN
        INSERT INTO @upsell_list
        (
            cart_upsell_id,
            cart_upsell_type_id,
            cart_upsell_type_name,
            cart_upsell_template_text,
            upsell_string,
            price_diff,
            cart_upsell_template_supplemental_text,
            license_category_name,
            license_seats,
            storage_gb,
            years,
            item_hierarchy_id
        )
        SELECT u.cart_upsel
l_id,
               ut.cart_upsell_type_id,
               ut.cart_upsell_type_name,
               tt.cart_upsell_template_text,
               tt.cart_upsell_template_text,
               0,
               tt.cart_upsell_template_supplemental_text,
               license_category_name = 'S/H',
               st.seats,
               cs.storage_gb,
               y.years,
               item_hierarchy_id = 2
        FROM cart_upsell u
            INNER JOIN cart_upsell_product_type pt
                ON u.cart_upsell_id = pt.cart_upsell_id
            INNER JOIN cart_upsell_sector s
                ON u.cart_upsell_id = s.cart_upsell_id
            INNER JOIN cart_upsell_license_category lc
                ON u.cart_upsell_id = lc.cart_upsell_id
            INNER JOIN license_category c
                ON lc.license_category_id = c.license_category_id
            INNER JOIN cart_upsell_seat st
                ON u.cart_upsell_id = st.cart_upsell_id
            INNER JOIN cart_upsell_years y
                ON u.cart_upsell_id = y.cart_upsell_id
            INNER JOIN cart_upsell_type ut
                ON u.cart_upsell_type_id = ut.cart_upsell_type_id
            INNER JOIN cart_upsell_template_mapping m
                ON m.cart_upsell_id = u.cart_upsell_id
            INNER JOIN cart_upsell_template t
                ON t.cart_upsell_template_id = m.cart_upsell_template_id
            INNER JOIN cart_upsell_template_text tt
                ON t.cart_upsell_template_id = tt.cart_upsell_template_id
                   AND tt.language_code = @language_code --and tt.location_code = @location_code
            LEFT JOIN cart_upsell_storage cs
                ON u.cart_upsell_id = cs.cart_upsell_id
                   AND cs.storage_gb = @storage_gb
            LEFT JOIN cart_upsell_license_distribution_method dm
                ON u.cart_upsell_id = dm.cart_upsell_id
                   AND dm.license_distribution_method_id = @license_distribution_method_id
                   AND dm.inclusive = 0
        WHERE pt.product_type_id = @product_type_id
              AND c.license_category_name = @license_category_name
              AND st.seats = CASE
                                 WHEN @product_line_cart_type = 'Enterprise' THEN
                                     1
                                 ELSE
                                     @license_seats
                             END
              AND y.years = @years
              AND s.cart_sector_id = @cart_sector_id
              AND u.cart_upsell_type_id = 6
              AND dm.cart_upsell_id IS NULL
        ORDER BY ut.type_sort_order

        DECLARE @net_price MONEY
        DECLARE @cd_product_set TABLE
        (
            product_id INT,
            product_description VARCHAR(100),
            retail_price MONEY,
            upgrade_price MONEY,
            discount MONEY,
            standard_discount MONEY
                DEFAULT 0,
            net_price MONEY,
            product_type_id INT,
            license_category_name VARCHAR(10),
            seats INT,
            years TINYINT,
            p_type VARCHAR(20),
            currency_id TINYINT,
            currency_code CHAR(3),
            currency_description VARCHAR(20),
            symbol_html VARCHAR(10),
            symbol_utf8 NVARCHAR(10),
            symbol_text VARCHAR(10),
            cart_discount_id INT NULL
        )

        INSERT INTO @cd_product_set
        (
            product_id,
            product_description,
            retail_price,
            upgrade_price,
            discount,
            standard_discount,
            net_price,
            product_type_id,
            license_category_name,
            seats,
            years,
            p_type,
            currency_id,
            currency_code,
            currency_description,
            symbol_html,
            symbol_utf8
,
            symbol_text,
            cart_discount_id
        )
        EXEC usp_cart_select_cd_product @license_category_name,
                                        @language_code,
                                        @location_code --, @cart_discount_id

        SELECT @price_diff_year_str = symbol_utf8 + CONVERT(VARCHAR(20), net_price),
               @net_price = net_price,
               @product_id = product_id
        FROM @cd_product_set

        UPDATE @upsell_list
        SET upsell_string = REPLACE(upsell_string, '<value>', @price_diff_year_str),
            price_diff = @net_price,
            product_id = @product_id
        WHERE cart_upsell_type_id = 6

    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 5.) return result
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT u.upsell_list_id,
           u.cart_upsell_type_id,
           u.cart_upsell_type_name,
           u.upsell_string,
           price_diff,
           u.cart_upsell_template_supplemental_text,
           license_category_name,
           license_seats,
           storage_gb,
           years,
           product_id,
           item_hierarchy_id
    FROM @upsell_list u
        LEFT JOIN cart_upsell_type t
            ON u.cart_upsell_type_id = t.cart_upsell_type_id
    WHERE price_diff > 0
    ORDER BY t.type_sort_order

END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'insert failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_technical_contact_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_technical_contact_in_process]

(
	@cart_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-12-19	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select cart_technical_contact_in_process_id
		select cart_technical_contact_in_process_id, cart_in_process_id, first_name, last_name, customer_email, phone_number, active
		from cart_technical_contact_in_process
		where cart_in_process_id = @cart_in_process_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_upsell]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_upsell]

(
	@cart_upsell_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-04-25	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @cart_upsell_seat_list varchar(20)
			,@cart_upsell_year_list varchar(20)
			,@cart_upsell_storage_list varchar(20)
			,@cart_upsell_sector_id_list varchar(200)
			,@cart_upsell_sector_list varchar(200)
			,@cart_upsell_license_category_id_list varchar(200)
			,@cart_upsell_license_category_list varchar(200)
			,@cart_upsell_product_type_id_list varchar(200)
			,@cart_upsell_product_type_list varchar(200)
			,@cart_upsell_product_line_id_list varchar(200)
			,@ids int
			,@id int
			,@response_code int
			,@message varchar(100)

	begin try

--	cart_upsell_sector_id(s)
--cart_upsell_license_category_id(s)
--cart_upsell_product_type_id(s)


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @cart_upsells table (id int identity(1,1), cart_upsell_id int,cart_upsell_type_id tinyint, cart_upsell_type_name varchar(50),cart_upsell_status_id tinyint, cart_upsell_description varchar(200), cart_upsell_seat_list varchar(20),cart_upsell_year_list varchar(20),cart_upsell_storage_list varchar(20),cart_upsell_sector_id_list varchar(200),cart_upsell_sector_list varchar(200),cart_upsell_license_category_id_list varchar(200),cart_upsell_license_category_list varchar(200),cart_upsell_product_type_id_list varchar(200),cart_upsell_product_type_list varchar(200), cart_upsell_product_line_id_list varchar(200), cart_upsell_template_id int, cart_upsell_template_name varchar(50))

	insert into @cart_upsells(cart_upsell_id,cart_upsell_type_id,cart_upsell_type_name,cart_upsell_status_id,cart_upsell_description,cart_upsell_template_id,cart_upsell_template_name)
	select u.cart_upsell_id,t.cart_upsell_type_id,t.cart_upsell_type_name,u.cart_upsell_status_id,u.cart_upsell_description,ut.cart_upsell_template_id,ut.cart_upsell_template_name
	from cart_upsell u
	inner join cart_upsell_type t
		on u.cart_upsell_type_id = t.cart_upsell_type_id
	left join cart_upsell_template_mapping m
		on u.cart_upsell_id = m.cart_upsell_id
	left join cart_upsell_template ut
		on m.cart_upsell_template_id = ut.cart_upsell_template_id
	where u.cart_upsell_id = case when @cart_upsell_id is null then u.cart_upsell_id else @cart_upsell_id end

	select @ids = max(id), @id = 1 from @cart_upsells

	while @ids >= @id
		begin
		select @cart_upsell_id = cart_upsell_id from @cart_upsells where id = @id
		print @id

		select @cart_upsell_seat_list = coalesce(@cart_upsell_seat_list+', ','')+ cast(convert(varchar(10),seats) as varchar(100)) 
		from cart_upsell_seat 
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_year_list = coalesce(@cart_upsell_year_list+', ','')+ cast(convert(varchar(10),years) as varchar(100)) 
		from cart_upsell_years
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_storage_list = coalesce(@cart_upsell_storage_list+', ','')+ cast(convert(varchar(10),storage_gb) as varchar(100)) 
		from cart_upsell_storage
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_sector_id_list = coalesce(@cart_upsell_sector_id_list+', ','')+ cast(convert(varchar(10),s.cart_sector_id) as varchar(100)) 
		from cart_upsell_sector c
		inner join cart_sector s
			on c.cart_sector_id = s.cart_sector_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell
_sector_list = coalesce(@cart_upsell_sector_list+', ','')+ cast(convert(varchar(10),s.cart_sector_name) as varchar(100)) 
		from cart_upsell_sector c
		inner join cart_sector s
			on c.cart_sector_id = s.cart_sector_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_license_category_id_list = coalesce(@cart_upsell_license_category_id_list+', ','')+ cast(convert(varchar(10),lc.license_category_id) as varchar(100)) 
		from cart_upsell_license_category c
		inner join license_category lc
			on c.license_category_id = lc.license_category_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_license_category_list = coalesce(@cart_upsell_license_category_list+', ','')+ cast(convert(varchar(10),lc.license_category_name) as varchar(100)) 
		from cart_upsell_license_category c
		inner join license_category lc
			on c.license_category_id = lc.license_category_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_product_type_id_list = coalesce(@cart_upsell_product_type_id_list+', ','')+ cast(convert(varchar(10),t.product_type_id) as varchar(100)) 
		from cart_upsell_product_type c
		inner join product_type t
			on c.product_type_id = t.product_type_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_product_type_list = coalesce(@cart_upsell_product_type_list+', ','')+ cast(convert(varchar(10),t.product_type_description) as varchar(100)) 
		from cart_upsell_product_type c
		inner join product_type t
			on c.product_type_id = t.product_type_id
		where cart_upsell_id = @cart_upsell_id
				
		select @cart_upsell_product_line_id_list = coalesce(@cart_upsell_product_line_id_list+', ','')+ cast(convert(varchar(10),c.product_line_id) as varchar(100)) 
		from cart_upsell_product_line c
		where cart_upsell_id = @cart_upsell_id

		update @cart_upsells
		set cart_upsell_seat_list = @cart_upsell_seat_list, 
			cart_upsell_year_list = @cart_upsell_year_list,
			cart_upsell_storage_list = @cart_upsell_storage_list,
			cart_upsell_sector_list = @cart_upsell_sector_list,
			cart_upsell_sector_id_list = @cart_upsell_sector_id_list,
			cart_upsell_license_category_list = @cart_upsell_license_category_list,
			cart_upsell_license_category_id_list = @cart_upsell_license_category_id_list,
			cart_upsell_product_type_list = @cart_upsell_product_type_list,
			cart_upsell_product_type_id_list = @cart_upsell_product_type_id_list,
			cart_upsell_product_line_id_list = @cart_upsell_product_line_id_list
		where id = @id

		select @cart_upsell_seat_list = null, 
			@cart_upsell_year_list = null,
			@cart_upsell_storage_list = null,
			@cart_upsell_sector_list = null,
			@cart_upsell_sector_id_list = null,
			@cart_upsell_license_category_list = null,
			@cart_upsell_license_category_id_list = null,
			@cart_upsell_product_type_id_list = null,
			@cart_upsell_product_type_list = null

		select @id = @id + 1
		end
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select cart_upsell_id,cart_upsell_description,cart_upsell_type_id,cart_upsell_type_name,cart_upsell_status_id,cart_upsell_seat_list,cart_upsell_year_list,cart_upsell_storage_list,cart_upsell_sector_id_list,cart_upsell_sector_list,cart_upsell_license_category_id_list,cart_upsell_license_category_list,cart_upsell_product_type_id_list,cart_upsell_product_type_list,cart_upsell_product_line_id_list,cart_upsell_template_id,cart_upsell_template_name
	from @cart_upsells

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogErr
or @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cart_upsell_template]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_cart_upsell_template]

(		
	@cart_upsell_template_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-04-25	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)
			,@ids int
			,@id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @cart_upsell_language_location_list varchar(100)

	declare @upsell_templates table (id int identity(1,1), cart_upsell_template_id int, cart_upsell_template_name varchar(50), cart_upsell_language_location_list varchar(100))

	insert into @upsell_templates(cart_upsell_template_id, cart_upsell_template_name)
	select cart_upsell_template_id, cart_upsell_template_name
	from cart_upsell_template t
	where cart_upsell_template_id = case when @cart_upsell_template_id is null then t.cart_upsell_template_id else @cart_upsell_template_id end

	select @ids = max(id), @id = 1 from @upsell_templates

	while @ids >= @id
		begin
		select @cart_upsell_template_id = cart_upsell_template_id from @upsell_templates where id = @id
		print @cart_upsell_template_id
		
		select @cart_upsell_language_location_list = coalesce(@cart_upsell_language_location_list+', ','')+ cast(language_code+'/'+location_code as varchar(100)) 
		from cart_upsell_template_text
		where cart_upsell_template_id = @cart_upsell_template_id

		update @upsell_templates
		set cart_upsell_language_location_list = @cart_upsell_language_location_list
		where id = @id

		select @cart_upsell_language_location_list = null
		select @id = @id + 1
		end

	select cart_upsell_template_id, cart_upsell_template_name, cart_upsell_language_location_list
	from @upsell_templates

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
