-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_cd_product]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_cd_product]

(
		@license_category_name varchar(10),
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@cart_discount_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-11	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	declare @product_set table(product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money default 0, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @language_code and @location_code
		if @language_code is null or @location_code is null
			begin
			select @language_code = 'EN', @location_code = 'USA'
			end

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) create product set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert product
	insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
	select p.product_id, p.product_description, 
			retail_price = case 
								when pp.product_pricing_id is null then p.retail_price
								else pp.retail_price
							end, 
			upgrade_price = case 
								when pp.product_pricing_id is null then p.retail_price
								else pp.retail_price
							end,
			discount = 0, p.product_type_id, lc.license_category_name, s.seats, y.years,
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
			from product p		
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join currency cu
			on pp.currency_id = cu.currency_id
		left join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		left join product_seat s
			on p.product_id = s.product_id
		left join product_years y
			on p.product_id = y.product_id
		where lc.license_category_name = @license_category_name and p.product_family_id = 8 and p.product_lifecycle_id = 1

		-- 2.2) apply discount
			update @product_set
			set discount =  case
							when d.cart_discount_type_id = 5 then s.discount
							when i.cart_discount_method_id = 1 and s.upgrade_price <> 0 then  round(convert(money,isnull(id.discount,i.discount)) * (s.retail_price/(select sum(retail_price) from @product_set where upgrade_price <> 0 and product_type_id = i.product_type_id)),2)
							when i.cart_discount_method_id = 2 and s.upgrade_price <> 0 then (s.retail_price - convert(money,isnull(id.discount,i.discount)))
							when i.cart_discount_method_i
d = 3 and s.upgrade_price <> 0 then ((convert(float,isnull(id.discount,i.discount))/100) * s.retail_price)
							else s.discount
					end,
				cart_discount_id = @cart_discount_id
			from @product_set s
			left join cart_discount_item i
				on i.cart_discount_id = @cart_discount_id and s.product_type_id = i.product_type_id
			left join cart_discount_item_discount id
				on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
			left join cart_discount d
				on i.cart_discount_id = d.cart_discount_id --and d.cart_discount_type_id <> 5
			where i.product_type_id <> 4


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) Return result
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		select product_id, product_description, retail_price, 
				upgrade_price = case
								when retail_price - (discount+standard_discount) <= 0 then 0
								else retail_price - (discount+standard_discount)
							end, 
				--discount,
				discount = case
								when retail_price - (discount+standard_discount) <= 0 then retail_price
								else retail_price - (discount+standard_discount)
							end, 
				standard_discount, 
				net_price = case
								when retail_price - (discount+standard_discount) <= 0 then 0
								else retail_price - (discount+standard_discount)
							end, 
				product_type_id, license_category_name, seats, years, p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id
			from @product_set

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_configurator_data]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_configurator_data]

(
	@keycode varchar(40)
)

AS

/*	DATE		AUTHOR		REMARKS
	2010-04-23	esmart		Initial creation.
	2011-03-25	esmart		Add base_capability for non-SS license categories
	2011-08-29	esmart		Lindbergh support
	2012-08-30	esmart		WSA 2013 WSAI support

	DESCRIPTION
	Select initial data for the configurator
*/

set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_id int,
			@license_status_id int,
			@product_line_id int,
			@months_remaining int,
			@capability_expiration_date datetime,
			@capability_activation_days int,
			@transaction_date datetime,
			@license_activated int,
			@license_distribution_method_id int,
			@license_category_id tinyint,
			@license_category_name varchar(10),
			@root_product_id int,
			@license_seats int,
			@storage_gb int,
			@is_autorenewal int,
			@last_activity_date datetime,
			@major_version int,
			@base_capability_id int

	set @transaction_date = getdate()	

	begin try

--seats_allowed 
--last_activity (need this just in case they come from the www site so we can get the correct mjv [could just make another call]) 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id 
		select @license_id = license_id,
				@product_line_id = l.product_line_id,
				@license_status_id = license_status_id,
				@license_distribution_method_id = l.license_distribution_method_id,
				@root_product_id = p.root_product_id
		from license l
		inner join product_line p
			on l.product_line_id = p.product_line_id
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -100,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

	-- 1.2) select license category
	select @license_category_id = isnull(license_category_id,dbo.fn_GetLicenseCategoryId(@license_id))
	from license_category_license
	where license_id = @license_id

	-- 1.2.1) @base_capability_id
	select @base_capability_id = base_capability_id
	from license_category
	where license_category_id = @license_category_id

	-- 1.2.2)
	select @license_category_id = 
					case
						when @license_category_id = 2 then 100
						when @license_category_id in (3,4,110) then 120
						else @license_category_id
					end

	-- 1.3) select current license seats
	select @license_seats = isnull(license_seats,1)
	from license_seat
	where license_id = @license_id

	-- 1.4) select current license storage
	select @storage_gb = isnull(storage_gb,0)
	from license_storage
	where license_id = @license_id

	-- 1.5) is_autorenewal
	select @is_autorenewal = case
								when license_attribute_license_value = 1 then 1
								else 0
							end
	from license_attribute_license
	where license_id = @license_id and license_attribute_id = 1

	-- 1.6) select @license_category_id
		select @license_category_name = license_category_name 
		from license_category
		where license_category_id = @license_category_id

	-- 1.7) get license_capability days
	select @capability_activation_days = capability_activation_days
	from license_capability
	where license_id = @license_id and capability_id = @base_capability_id
			
	-- 1.8) get remaining months on license
	if @license_status_id = 0 and @capability_activation_days > 0
		begin
			select @capability_expiration_date = dateadd(dd,capability_activation_days,@transaction_date),
					@lic
ense_activated = case when capability_expiration_date is null then 0 else 1 end
			from license_capability
			where license_id = @license_id and capability_id = @base_capability_id
		end
	else
		begin
			select @capability_expiration_date = capability_expiration_date,
					@license_activated = case when capability_expiration_date is null then 0 else 1 end
			from license_capability
			where license_id = @license_id and capability_id = @base_capability_id
		end

	if @license_status_id = 1 and @license_activated = 0 and @capability_activation_days > 0
		begin
			select @capability_expiration_date = dateadd(dd,capability_activation_days,@transaction_date)
			from license_capability
			where license_id = @license_id and capability_id = @base_capability_id
		end

		-- 1.8.1) set expiration date if BestBuy
		if @license_distribution_method_id in (select license_distribution_method_id from subscription_distribution_method)
			begin
			select @capability_expiration_date = case 
													when cancel_reason is null then expiration_date 
													else cancel_date
												end
			from subscription
			where license_id = @license_id
			end

	select @months_remaining = 0

	if datediff(hh,@transaction_date,@capability_expiration_date) > 24
		begin

			while dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
				begin
				select @months_remaining = @months_remaining + 1
				end

			select @months_remaining = 
					case
						when @months_remaining <= 1 and @capability_expiration_date is not null then 1
						when @months_remaining <= 1 and @capability_expiration_date is null then 0
						else @months_remaining - 1
					end
		end

	-- 1.9) check for best buy monthly subscribers and set months remaining = 12
	declare @best_buy_monthly int

	select @best_buy_monthly = 
				case
					when count(*) > 0 then 1
					else 0
				end
	from subscription 
	where license_id = @license_id and subscription_type_id <> 2
	
	if @best_buy_monthly = 1
		begin
			select @months_remaining = 12
		end

	-- 1.10) last_activity 
	select @last_activity_date = getdate()-1,
			@major_version = 7
	--from weblog.dbo.license_activity_summary
	--where license_id = @license_id


	select	license_category_id = @license_category_id,
			license_category_name = @license_category_name,
			license_seats = @license_seats,
			license_distribution_method_id = @license_distribution_method_id,
			root_product_id = @root_product_id,
			license_status_id = @license_status_id,
			is_autorenewal = isnull(@is_autorenewal,0),
			storage_gb = @storage_gb,
			months_remaining = @months_remaining,
			capability_expiration_date = @capability_expiration_date,
			last_activity_date = @last_activity_date,
			major_version = @major_version

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

SET ANSI_NULLS ON

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_configurator_pricing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_configurator_pricing]

(
		@cart_order_in_process_id int,
		@years float,
		@seats int
		
)

/*	
	DATE		AUTHOR		REMARKS
	2010-11-02	esmart		Initial creation.

	DESCRIPTION
	select configurator pricing
*/

AS
	set nocount on				

	declare	@keycode varchar(40), 
			@license_category_name varchar(10), 
			@license_category_id tinyint,	
			@license_seats int, 
			@storage_gb int, 
			@license_storage_gb int, 
			--@years int, 
			@license_id int, 
			@cart_discount_id int,
			@response_code int,
			@message varchar(100),
			@language_code varchar(2),
			@location_code varchar(3)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) get data from cart_in_process	
		select @keycode = l.keycode,
				@cart_discount_id = m.cart_discount_id
		from cart_order_message_in_process m
		inner join license l
			on m.license_id = l.license_id
		where m.cart_order_in_process_id = @cart_order_in_process_id

		select @language_code = language_code,
				@location_code = location_code
		from cart_order_in_process
		where cart_order_in_process_id = @cart_order_in_process_id

--		select keycode = @keycode

	-- 1.1) get ext_types
	--	exec usp_cart_select_license_ext_types @keycode
		declare @ext_type table (cart_item_in_process_ext_type_id tinyint, ext_type_name varchar(20), ext_type_value varchar(20))

		insert into @ext_type(cart_item_in_process_ext_type_id,ext_type_name,ext_type_value)
		exec usp_cart_select_license_ext_types @keycode

--		select * from @ext_type

	-- 1.2) get configurator data
		declare @configurator_data table (license_category_id tinyint,license_category_name varchar(10),license_seats int,license_distribution_method_id int,root_product_id int,license_status_id int,is_autorenewal int,storage_gb int,months_remaining int,capability_expiration_date datetime,last_activity_date datetime,major_version int)

		insert into @configurator_data(license_category_id,license_category_name,license_seats,license_distribution_method_id,root_product_id,license_status_id,is_autorenewal,storage_gb,months_remaining,capability_expiration_date,last_activity_date,major_version)
		exec usp_cart_select_configurator_data @keycode

--	select * from @configurator_data

	-- 1.3) assign parameters
		select 	@license_category_name = (select ext_type_value from @ext_type where ext_type_name = 'category')
				,@license_seats = isnull((select ext_type_value from @ext_type where ext_type_name = 'seats'),1)
				,@license_storage_gb = (select ext_type_value from @ext_type where ext_type_name = 'storage')
			
--		if @years <> 0
--			begin	
--				select @years = (select years = case
--												when (select months_remaining from @configurator_data) <= 6 then 1
--												else 0
--												end)
--			end

--		select @license_category_name = 'WISE'
--		select @license_seats = 3
--		select @storage_gb = 25

	-- 1.4) get categories to process
		declare @license_categories table (license_category_id int, license_category_name varchar(10))
		declare @storage_gbs table (storage_gb int)

		insert into @license_categories(license_category_id,license_category_name)
		select c1.license_category_id, c1.license_category_name
		from product_license_category_upgrade u
		inner join license_category c
			on u.license_category_id = c.license_category_id
		inner join license_category c1
			on u.upgrade_license_category_id = c1.license_category
_id
		where c.license_category_name = @license_category_name

		if @seats is not null and @seats not in (0,1)
			begin
			insert into @license_categories(license_category_id,license_category_name)
			select license_category_id,license_category_name
			from @configurator_data			
			end 

--select storage_gb = @storage_gb
--select * from @license_categories
--select license_seats = @license_seats

	-- 1.5) fill product sets
		--declare @product_set table(license_category_name_input varchar(10), license_category_id_input tinyint, storage_gb_input int, product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money,           net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int)
		declare @product_set table(license_category_name_input varchar(10), license_category_id_input tinyint, storage_gb_input int, product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)
																				     	
		select @license_category_id = min(license_category_id) from @license_categories

		while @license_category_id <= (select max(license_category_id) from @license_categories)
			begin
		
			select @license_category_name = license_category_name from license_category where license_category_id = @license_category_id
			select @license_seats = (select min(seats) from product_license_category_seat where license_category_id = @license_category_id and seats >= @license_seats)
			
			if @seats is not null and @seats not in (0,1) 
				begin 
					select @license_seats = @seats 
				end

			select @storage_gb = @license_storage_gb

			select @storage_gb = (select min(storage_gb) 
								from product_license_category_storage 							
								where license_category_id = @license_category_id and (storage_gb >= @storage_gb or @storage_gb is null))
			
--select license_category_id = @license_category_id, license_category_name = @license_category_name, license_seats = @license_seats, seats = @seats, storage_gb = @storage_gb
			
			if @storage_gb is not null 
				begin
				
				delete from @storage_gbs

				insert into @storage_gbs(storage_gb)
				select storage_gb
				from product_license_category_storage 							
				where license_category_id = @license_category_id and (storage_gb >= @storage_gb or @storage_gb is null)
				
				select @storage_gb = min(storage_gb) from @storage_gbs

				while @storage_gb <= (select max(storage_gb) from @storage_gbs)
					begin

--select license_category_id = @license_category_id, license_category_name = @license_category_name, license_seats = @license_seats, storage_gb = @storage_gb

						insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
						exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
						
						update @product_set 
						set license_category_name_input = @license_category_name, 
							license_category_id_input = @license_category_id,
							storage_gb_input = @storage_gb
						where license_category_name_input is null

					select @storage_gb = min(storage_gb) from @storage_gbs wher
e storage_gb > @storage_gb

					end
					if @storage_gb is null
						begin
						select @storage_gb = min(storage_gb) from @storage_gbs
						end
				end
			else
				begin
	--			select license_category_id = @license_category_id, license_category_name = @license_category_name, license_seats = @license_seats, storage_gb = @storage_gb

				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
				
				update @product_set 
				set license_category_name_input = @license_category_name, 
					license_category_id_input = @license_category_id,
					storage_gb_input = @storage_gb
				where license_category_name_input is null
				end

		-- 1.5. ) increment category
		select @license_category_id = min(license_category_id) from @license_categories where license_category_id > @license_category_id
		
		end

	-- 1.6) select result
	
		select	p_type_order = 1,
				p_type = 'upgrade',
				s.license_category_name_input, s.license_category_id_input, storage_gb_input, 
				retail_price,
				upgrade_price,
				discount,
				standard_discount,
				net_price,
				currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		from @product_set s
		inner join (select license_category_id_input, min_storage_gb = min(storage_gb_input)
					from @product_set
					group by license_category_id_input) t
			on s.license_category_id_input = t.license_category_id_input and (s.storage_gb_input = t.min_storage_gb or s.storage_gb_input is null)
		where p_type in ('upgrade')
		union		
--		select p_type_order = 2,
--				p_type = 'renewal',
--				license_category_name_input, license_category_id_input, storage_gb_input, 
--				retail_price = sum(retail_price),
--				upgrade_price = sum(upgrade_price),
--				discount = sum(discount),
--				standard_discount = sum(standard_discount),
--				net_price = sum(net_price)
--		from @product_set s
--		where p_type in ('renewal','renewal storage')
--		group by license_category_name_input, license_category_id_input, storage_gb_input
		select p_type_order = 2,
				p_type = 'renewal',
				license_category_name_input, license_category_id_input, storage_gb_input, 
				retail_price = sum(retail_price),
				upgrade_price = sum(upgrade_price),
				discount = sum(discount),
				standard_discount = sum(standard_discount),
				net_price = sum(net_price),
				currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		from @product_set s
		where p_type in ('renewal')
		group by license_category_name_input, license_category_id_input, storage_gb_input, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		union		
		select p_type_order = 3,
				p_type = 'renewal storage',
				license_category_name_input, license_category_id_input, storage_gb_input, 
				retail_price = sum(retail_price),
				upgrade_price = sum(upgrade_price),
				discount = sum(discount),
				standard_discount = sum(standard_discount),
				net_price = sum(net_price),
				currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		from @product_set s
		where p_type in ('renewal storage')
		group by license_category_name_input, license_category_id_input, storage_gb_input, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		union
		select p_type_order = 4,
				p_type = 'storage',
				license_category_name_input, license_category_id_input, storage_gb_input, 
				retail_price = sum(retail_price),
				upgrade_price = sum(upgrade_price),
				discount = sum(discount),
				standard_discount = sum(standard_discount),
				net_price = sum(net_price),

				currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		from @product_set s
		where p_type in ('storage')
		group by license_category_name_input, license_category_id_input, storage_gb_input, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
		order by p_type_order, s.license_category_id_input

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_configurator_upsell]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_configurator_upsell]

(
	@cart_order_in_process_id int,
	@cart_item_bundle_id int,
	@license_category_name varchar(10) = null,
	@enterprise_license_seats int = null,
	@years_upgrade float = null,
	@license_json nvarchar(max) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2014-09-18	esmart		Remove >6 month restriction on Additional years upsell
	2015-04-30	esmart		Extend output to include additional columns
	2015-09-23	esmart		Add configuration_option support
	2018-03-23	esmart		Allow json input without cart

	DESCRIPTION
	select seat, year, storage, license_category, and discounts for item
*/

AS
	set nocount on				

	declare	@language_code varchar(2),
			@location_code varchar(3),
			@locale varchar(5),
			@keycode varchar(40),
			@license_key varchar(36),
			@license_category_id tinyint,
			@license_category_name_input varchar(10),
			--@enterprise_license_seats_upgrade int,
			@cart_upsell_type_name varchar(50),
			@license_seats int,
			@product_line_id int,
			@product_type_id int,
			@cart_discount_id int, 
			@storage_gb int,
			@years float,
			@base_price money,
			@base_upgrade_price money,
			@base_retail_price money,
			@base_retail_upgrade_price money,
			@retail_price money,
			@net_price money,
			@discount money,
			@standard_discount money,
			@months_remaining int,
			@cart_type_id tinyint, 
			@currency_code varchar(3),
			@currency_id tinyint,
			--@enterprise_license_seats int,
			@response_code int,
			@message varchar(100)


	begin try

	

	declare @configurator_upsell table (configurator_upsell_id int identity(1,1), cart_upsell_type_id tinyint, cart_upsell_type_name varchar(40), license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, storage_gb int, years float, retail_price money, retail_upgrade_price money, net_price money, upgrade_price money, discount money, standard_discount money, equivalent_year_price money)

	declare @product_set table(license_category_name_input varchar(10), license_category_id_input tinyint, storage_gb_input int, product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) @cart_order_in_process_id 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @cart_order_in_process_id  is not null 
		begin
			declare @item_summary table (cart_item_bundle_id int, product_family_id int, product_line_id int, cart_order_item_in_process_id int, product_id int, keycode varchar(40), product_type_id int, max_product_type_id int,	current_license_category_id int,license_category_id int,current_seats int,seats int,current_storage_gb int,storage_gb int,quantity int,years float,retail_price money,net_price money,discount money,standard_discount money,cart_discount_id int)

			select @license_category_name_input = @license_category_name--, @enterprise_license_seats_upgrade = @enterprise_license_seats
	
			-- 1.1) @item_summary
				insert into @item_summary(cart_item_bundle_id, product_family_id, product_line_id, keycode, cart_order_item_in_process_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id)
				select	i.cart_item_bundle_id, 
						p.product_family_id,
						plp.product_line_id,
						l.keycode, 
						cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
						product_type_id = min(p.product_type_id),  
						max_product_type_id = max(p.product_type_id),
						current_license_category_id = min(plc.current_license_category_id),
						license_category_id = max(plc.license_category_id),
						current_seats = case 
											when plp.product_line_id in (55,300) then max(i.quantity)
											else min(s.current_seats)
										end, 
						seats = case 
									when plp.product_line_id in (55,300) then max(i.quantity)
									else max(s.seats)
								end, 
						current_storage_gb = min(ps.storage_gb), 
						storage_gb = max(ps.storage_gb), 
						quantity = max(i.quantity), 
						years = max(y.years), 
						retail_price = sum(i.retail_price), 
						net_price = sum(i.net_price),
						discount = sum(i.discount), 
						standard_discount = sum(i.standard_discount),
						cart_discount_id = max(i.cart_discount_id)
				from cart_order_item_in_process i with (nolock)
				inner join product p with (nolock)
					on i.product_id = p.product_id
				inner join product_line_product plp with (nolock)
					on p.product_id = plp.product_id
				inner join product_family f with (nolock)
					on p.product_family_id = f.product_family_id
				left join product_license_category plc with (nolock)
					on i.product_id = plc.product_id
				left join license_category lc with (nolock)
					on plc.license_category_id = lc.license_category_id
				left join product_years y with (nolock)
					on i.product_id = y.product_id
				left join product_seat s with (nolock)
					on i.product_id = s.product_id
				left join product_storage ps with (nolock)
					on i.product_id = ps.product_id
				inner join cart_order_item_license_in_process il with (nolock)
					on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
				inner join license l with (nolock)
					on il.keycode = l.keycode
				where i.cart_order_in_process_id = @cart_order_in_process_id and i.cart_item_bundle_id = @cart_item_bundle_id and il.keycode <> '' and p.product_family_id in (1,2,30,31,50,51,55,100,200,300)
				group by i.cart_item_bundle_id,
						p.product_family_id,
						plp.product_line_id,
						l.keycode

				--select * from @item_summary

			-- 1.2) get values
				select @language_code = language_code, 
					@location_code = location_code
				from cart_order_in_process 
				where cart_order_in_process_id = @cart_order_in_process_id

				select @license_category_id = license_category_id, 
					@product_line_id = product_line_id, 
					@product_type_id = product_type_id,
					@cart_discount_id = cart_discount_id,
					@storage_gb = storage_gb,
					@keycode = keycode,
					@base_retail_price = retail_price-standard_discount,
					@base_price = net_price,
					--@enterprise_license_seats = seats,
					@license_seats = seats
				from @item_summary s
		
				-- 1.2.1) @license_category_name
				if @license_category_name is null
					begin
					select @license_category_name = license_category_name,
							@license_category_name_input = license_category_name
					from license_category 
					where license_category_id = @license_category_id
					end

				-- 1.2.2) @enterprise_license_seats
				--if @product_line_id in (300,55)
				--	begin
				--	if @enterprise_license_seats > @license_seats
				--		begin
				--		select @license_seats = @enterprise_license_seats
				--		end
				--	else
				--		begin
				--		select @ente
rprise_license_seats = @license_seats
				--		end
				--	end

				--select license_seats = @license_seats, enterprise_license_seats = @enterprise_license_seats
				if @enterprise_license_seats is null
					begin
					select @enterprise_license_seats = @license_seats
					end
			
			-- 1.3) @configurator_data	
				declare @configurator_data table (license_category_id tinyint,license_category_name varchar(10),license_seats int,license_distribution_method_id int,root_product_id int,license_status_id int,is_autorenewal int,storage_gb int,months_remaining int,capability_expiration_date datetime,last_activity_date datetime,major_version int)

				insert into @configurator_data(license_category_id,license_category_name,license_seats,license_distribution_method_id,root_product_id,license_status_id,is_autorenewal,storage_gb,months_remaining,capability_expiration_date,last_activity_date,major_version)
				exec usp_cart_select_configurator_data @keycode

				select @months_remaining = months_remaining from @configurator_data

				if @months_remaining > 6
					begin
					select @base_price = 0, @base_retail_price = 0
					end

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) @license_json 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	if @license_json is not null
		begin
		
			select @keycode = keycode,
					@locale = locale,
					@currency_code = currency_code,
					@license_key = license_key
			from openjson(@license_json)
			with (keycode varchar(40) '$.keycode',
					locale varchar(10) '$.locale',
					currency_code varchar(10) '$.currency_code',
					license_key varchar(36) '$.license_key')

			select @license_category_name_input = @license_category_name

			select @currency_id = currency_id
			from currency
			where currency_code = @currency_code
			
			-- 1.2.1) @language_code and @location_code
			select @language_code = language_code, @location_code = location_code
			from dbo.fn_locale_to_lang_loc(@locale)

			if @keycode is null
				begin
				select @keycode = l.keycode
				from license_key k
				inner join license l
					on l.license_id = k.license_id
				where k.license_key = @license_key
				end
			
			select @license_category_id = cl.license_category_id, @product_line_id = pl.product_line_id, @license_seats = s.license_seats
			from license l
			inner join license_category_license cl
				on cl.license_id = l.license_id
			inner join license_category_product_line pl
				on pl.license_category_id = cl.license_category_id and pl.language_code = @language_code and pl.location_code = @location_code
			inner join license_seat s
				on s.license_id = l.license_id
			where l.keycode = @keycode

			if @enterprise_license_seats is null
					begin
					select @enterprise_license_seats = @license_seats
					end
			
			-- 1.2.1) @license_category_name
			if @license_category_name is null
				begin
				select @license_category_name = license_category_name,
						@license_category_name_input = license_category_name
				from license_category 
				where license_category_id = @license_category_id
				end
			--declare @product_set table(line_item int identity(1,1), product_id int, product_description varchar(100), quantity int default 1, retail_price money, upgrade_price money, discount money, standard_discount money, net_price money, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), cart_item_class_id tinyint, cart_item_bundle_id int, keycode varchar(40), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_te
xt varchar(10), cart_discount_id int, license_category_id int, license_attribute_id int, license_attribute_license_value int, start_date datetime, expiration_date datetime, contract_days float)
	
			insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)
			exec usp_cart_select_renewal_product_set @keycode, @license_category_name, @license_seats, @storage_gb, @years, @cart_discount_id, @language_code, @location_code, @cart_type_id, @currency_id
			
			select @base_retail_price = retail_price-standard_discount,
					@base_price = net_price
			from @product_set

			delete from @product_set

			-- select @base_retail_price, @base_price, @keycode, @license_category_id, @location_code, @product_line_id, @license_seats, @license_category_name, @language_code, @location_code
			-- return
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) add upsells types 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- select @base_retail_price, @base_price, @keycode, @license_category_id, @years, @location_code, @product_line_id, @license_seats, @license_category_name
	
	-- 2.2) License category upgrade
	insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name, license_category_description)
	select cart_upsell_type_id = 2, cart_upsell_type_name = 'License category upgrade', c.license_category_id, c.license_category_name, c.license_category_description
	from product_license_category_upgrade u
	inner join license_category_product_line pl
		on u.upgrade_license_category_id = pl.license_category_id and pl.language_code = @language_code and pl.location_code = @location_code
	inner join license_category c
		on u.upgrade_license_category_id = c.license_category_id
	where u.license_category_id = @license_category_id and u.language_code = @language_code and u.location_code = @location_code and pl.product_line_id = @product_line_id
	order by c.license_category_id

		-- 2.2.1) update seats
		update @configurator_upsell
		set seats = t.seats
		from @configurator_upsell u
		inner join (select u.license_category_id, seats = case 
																when @product_line_id in (300,55) then @license_seats
																when @license_category_name = 'WSAC' and @license_seats = 3 then 3
																else min(s.seats)
															end
					from @configurator_upsell u
					inner join product_license_category_seat s
						on u.license_category_id = s.license_category_id
					where s.seats >= case when @product_line_id in (300,55) then s.seats else @license_seats end and s.configuration_option = 1
					group by u.license_category_id) t
			on u.license_category_id = t.license_category_id

		-- 2.2.1) update storage
		update @configurator_upsell
		set storage_gb = t.storage_gb
		from @configurator_upsell u
		inner join (select u.license_category_id, storage_gb = min(s.storage_gb)
					from @configurator_upsell u
					inner join product_license_category_storage s
						on u.license_category_id = s.license_category_id
					group by u.license_category_id) t
			on u.license_category_id = t.license_category_id

		-- 2.2.1) update years
		update @configurator_upsell
		set years = t.years -- case when @months_remaining > 6 then 0 else t.years end
		from @configurator_upsell u
		inner join (select u.license_category_id, years = min(y.years)
					from @configurator_upsell u
					inner join product_license_categ
ory_years y
						on u.license_category_id = y.license_category_id
					where y.years >= 1
					group by u.license_category_id) t
			on u.license_category_id = t.license_category_id

	-- 2.3) Seat upgrade
	--if @product_line_id not in (300,55)
	--	begin

			insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name,license_category_description,seats,storage_gb,years)
			select cart_upsell_type_id=3,cart_upsell_type_name='Seat upgrade',u.license_category_id,u.license_category_name,u.license_category_description,
					seats = case when @product_line_id in (300,55) then @enterprise_license_seats else s.seats end,
					u.storage_gb,
					--years = case when @product_line_id in (300,55) then 0 else u.years end
					u.years
			from @configurator_upsell u
			inner join product_license_category_seat s
				on u.license_category_id = s.license_category_id
			where license_category_name = @license_category_name and 
					s.seats >= case when @product_line_id in (300,55) then s.seats else @license_seats end and 
					s.seats <= case 
									when @product_line_id in (300,55) then s.seats 
									when @product_line_id not in (300,55) and @license_seats <= 5 then 5
									when @product_line_id not in (300,55) and @license_seats > 5 then 25
									else 5 
								end and 
					u.cart_upsell_type_name = 'License category upgrade' 
					and (s.configuration_option = 1 or (s.configuration_option = 0 and s.seats = @license_seats))
			order by s.seats
			
		--end

	-- 2.4) Additional year
	--if @months_remaining <= 6
	--	begin
		insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name,license_category_description,seats,storage_gb,years)
		select cart_upsell_type_id=1,cart_upsell_type_name='Additional year',u.license_category_id,u.license_category_name,u.license_category_description,
			seats = @enterprise_license_seats,--case when @product_line_id in (300,55) /*and y.years > 1*/ then @enterprise_license_seats else u.seats end,
			--u.seats,
			u.storage_gb,years=0
		from @configurator_upsell u
		inner join product_license_category_years y
			on u.license_category_id = y.license_category_id
		where license_category_name = @license_category_name and u.cart_upsell_type_name = 'License category upgrade' and y.years in (1)
	
		insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name,license_category_description,seats,storage_gb,years)
		select cart_upsell_type_id=1,cart_upsell_type_name='Additional year',u.license_category_id,u.license_category_name,u.license_category_description,
			seats = @enterprise_license_seats, --case when @product_line_id in (300,55) /*and y.years > 1*/ then @enterprise_license_seats else u.seats end,
			--u.seats,
			u.storage_gb,y.years
		from @configurator_upsell u
		inner join product_license_category_years y
			on u.license_category_id = y.license_category_id
		where license_category_name = @license_category_name and u.cart_upsell_type_name = 'License category upgrade' and y.years in (1,2,3)
		-- end 


	-- 2.5) Storage upgrade
	declare @min_storage_gb int

	select @min_storage_gb = min(s.storage_gb)
	from @configurator_upsell u
	inner join product_license_category_storage s
		on u.license_category_id = s.license_category_id
	where license_category_name = @license_category_name
	
	insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name,license_category_description,seats,storage_gb,years)
	select cart_upsell_type_id=4,cart_upsell_type_name='Storage upgrade',u.license_category_id,u.license_category_name,u.license_category_description,u.seats,s.storage_gb,
		years = case when @years_upgrade is not null then @years_upgrade else u.years end
	from @configurator_upsell u
	inner join product_license_categor
y_storage s
		on u.license_category_id = s.license_category_id
	where license_category_name = @license_category_name and u.cart_upsell_type_name = 'License category upgrade' --and s.storage_gb > @min_storage_gb

	-- select '@configurator_upsell', * from @configurator_upsell

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	declare @configurator_upsell_id int, @total_upsells int

	select @configurator_upsell_id = 1, @total_upsells = count(*) from @configurator_upsell
	select @base_upgrade_price = 0, @base_retail_upgrade_price = 0

	-- select @currency_id

	-- 3.1) start loop
	while @total_upsells >= @configurator_upsell_id
		begin
		--print @configurator_upsell_id
		-- 3.1.1) set values
		select @license_category_name = license_category_name, @license_seats = seats, @storage_gb = storage_gb, @years = years, @cart_upsell_type_name = cart_upsell_type_name
		from @configurator_upsell
		where configurator_upsell_id = @configurator_upsell_id

		-- 3.1.2) get enterprise product set data
		if @product_line_id in (55,300)
			begin
				--select @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_renewal_product_set_ENT @keycode,@license_category_name,@license_seats,@storage_gb,@years,null,@language_code,@location_code
			end
		-- 3.1.3) get consumer product set data
		else
			begin
				-- if @months_remaining > 6 begin select @years = 0 end
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
			end
		
		if @cart_upsell_type_name <> 'Storage upgrade'
			begin
			select @retail_price = isnull(sum(retail_price-standard_discount),0),
					@net_price = isnull(sum(net_price),0),
					@discount = isnull(sum(discount),0),
					@standard_discount = isnull(sum(standard_discount),0)
			from @product_set s
			where p_type not like '%storage%'
			end
		else
			begin
			
			select @retail_price = isnull(sum(retail_price),0),
					@net_price = isnull(sum(net_price),0),
					@discount = isnull(sum(discount),0),
					@standard_discount = isnull(sum(standard_discount),0)
			from @product_set s
			where p_type like '%storage%'
			end

		--- select license_category_name_input = @license_category_name_input, configurator_upsell_id = @configurator_upsell_id, retail_price = @retail_price, net_price = @net_price, base_price = @base_price, base_upgrade_price = @base_upgrade_price, base_retail_upgrade_price = @base_retail_upgrade_price, discount = @discount, standard_discount = @standard_discount
		
		-- 3.1.3) update @configurator_upsell
		--if @cart_upsell_type_name <> 'Storage upgrade'
			begin
				update @configurator_upsell 
				set retail_price = @retail_price,
					--retail_price = case
					--					when @cart_upsell_type_name = 'Storage upgrade' then retail_price + standard_discount
					--					else @retail_price
					--				end,
					retail_upgrade_price = case
							
			when @cart_upsell_type_name = 'License category upgrade' and @product_line_id in (300,55) then @retail_price - (@base_retail_price*seats)
										when @cart_upsell_type_name = 'Storage upgrade' then @retail_price - @standard_discount 
										else @retail_price - @base_retail_upgrade_price
									end,
					net_price = @net_price, 
					upgrade_price = case
										when @cart_upsell_type_name = 'License category upgrade' and @product_line_id in (300,55) then @net_price - (@base_price*seats)
										when @cart_upsell_type_name = 'Storage upgrade' then @retail_price - @standard_discount - @discount
										else @net_price - @base_upgrade_price
									end,
					discount = @discount,
					standard_discount = @standard_discount
				where configurator_upsell_id = @configurator_upsell_id
			end

		-- 3.1.4) set base price for upgrade calculations
		if @cart_upsell_type_name = 'License category upgrade' and @license_category_name_input = @license_category_name
			begin
				select @base_upgrade_price = @net_price, @base_retail_upgrade_price = @retail_price
				
				update @configurator_upsell
				set retail_upgrade_price = 0,
					upgrade_price = 0
				where configurator_upsell_id = @configurator_upsell_id
			end

		if @cart_upsell_type_name = 'License category upgrade' and @license_category_name_input = @license_category_name
			begin
			update @configurator_upsell
			set retail_upgrade_price = 0,
				upgrade_price = 0
			from @configurator_upsell
			where configurator_upsell_id < @configurator_upsell_id
			end
			

		-- select * from @product_set

		delete from @product_set

		--select @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
		select @configurator_upsell_id = @configurator_upsell_id + 1
		end

			--select '@configurator_upsell', * from @configurator_upsell
			--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	update @configurator_upsell
	set equivalent_year_price = case 
			when cart_upsell_type_id = 1 and years > 0 then (select retail_price*c.years from @configurator_upsell where license_category_id = c.license_category_id and years = 1 and cart_upsell_type_id = 1)
			end
	from @configurator_upsell c

	select configurator_upsell_id, 
			cart_upsell_type_id, 
			cart_upsell_type_name, 
			license_category_id, 
			license_category_name, 
			license_category_description, 
			seats, storage_gb, 
			years, 
			retail_price, 
			retail_upgrade_price, 
			net_price, 
			upgrade_price,
			discount,
			standard_discount,

			full_retail_price = equivalent_year_price,
			equivalent_year_price,
			term_discount = equivalent_year_price - retail_price,

			full_retail_price_pspy = case when years > 0 and cart_upsell_type_id = 1 then round(equivalent_year_price/seats/years,2,1) end,
			retail_price_pspy = case when years > 0 and cart_upsell_type_id = 1 then round(retail_price/seats/years,2,1) end,
			upgrade_price_pspy = case when years > 0 and cart_upsell_type_id = 1 then round(upgrade_price/seats/years,2,1) end,
			net_price_pspy = case when years > 0 and cart_upsell_type_id = 1 then round(net_price/seats/years,2,1) end,

			total_discount_pspy = case when years > 0 and cart_upsell_type_id = 1 then round((equivalent_year_price - net_price)/seats/years,2,1) end,
			term_discount_pspy = case when years > 0 and cart_upsell_type_id = 1 then round((equivalent_year_price - retail_price)/seats/years,2,1) end,
			discount_pspy = case when years > 0 and cart_upsell_type_id = 1 then round((discount)/seats/years,2,1)
 end,
			
			total_discount_pct = case when years > 0 and cart_upsell_type_id = 1 then round((round((equivalent_year_price - net_price)/seats/years,2,1)/round(equivalent_year_price/seats/years,2,1))*100,1) end,
			term_discount_pct = case when years > 0 and cart_upsell_type_id = 1 then round((round((equivalent_year_price - retail_price)/seats/years,2,1)/round(equivalent_year_price/seats/years,2,1))*100,1) end,
			discount_pct = case when years > 0 and cart_upsell_type_id = 1 then round((round((discount)/seats/years,2,1)/round(equivalent_year_price/seats/years,2,1))*100,1) end
	

	from @configurator_upsell c
						

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_currency]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_currency]

(
	@currency_id tinyint = null,
	@active tinyint = null

)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2013-02-01	esmart		Add VAT rate

	DESCRIPTION
	select currency
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	if @active is null 
		begin
		select @active = 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, exchange_rate, exchange_multiplier, active, last_modified_date, last_modified_by, vat_rate
	from currency
	where currency_id = case 
							when @currency_id is null then currency_id
							else @currency_id
						end and
			active = case 
							when @currency_id is not null then active
							else @active
						end 

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_currency_language_location]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_currency_language_location]

(
	@currency_id tinyint = null

)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select currency
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select cl.currency_language_location_id, cl.currency_id, c.currency_code, c.currency_description, language_code, location_code
	from currency_language_location cl
	inner join currency c
		on cl.currency_id = c.currency_id
	where cl.currency_id = case 
							when @currency_id is null then cl.currency_id
							else @currency_id
						end
	order by language_code, location_code

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_customer]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @response_code int,
			@message varchar(100)
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select c.first_name, 
			c.last_name, 
			e.customer_email,
			company_name = case when co.company_name is not null then co.company_name else cc.company_name end,
			a.address_1, 
			a.address_2, 
			a.city,
			state = s.state_iso3,
			a.postal_code,
			country = lc.iso,
			v.vendor_customer_code,
			p.phone_number,
			c.opt_in
	from customer c
	left join vendor_customer v
		on v.customer_id = c.customer_id
	left join customer_email e
		on e.customer_id = c.customer_id and e.email_status_id = 1
	left join customer_company cc
		on cc.customer_id = c.customer_id
	left join company co
		on co.company_id = cc.company_id
	left join customer_address a
		on a.customer_id = c.customer_id and a.address_type_id = 1 and a.address_status_id = 1
	left join lu_states s
		on a.state = rtrim(s.state_id)
	left join lu_countries lc
		on lc.country_id = a.country_id
	left join customer_phone p
		on p.customer_id = c.customer_id and p.phone_type_id = 1
	where c.customer_id = @customer_id

		--@first_name nvarchar(255),
  --      @last_name nvarchar(255),
  --      @company_name nvarchar(255),
  --      @address_1 nvarchar(255),
  --      @address_2 nvarchar(255),
  --      @city nvarchar(130),
  --      @state varchar(3),
  --      @postal_code nvarchar(32),
  --      @country varchar(3),
  --      @phone_number varchar(64),
  --      @customer_email nvarchar(255),
  --      @opt_in bit,
		--@customer_type_id int = null,
		--@vat_id varchar(20) = null,
		--@external_customer_key varchar(100) = null,


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not select customer for customer_id : ' + convert(varchar(20),@customer_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_dr_bundle]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_cart_select_dr_bundle]

(
		@upgrade_dr_product_id int,
		@renewal_dr_product_id int,
		@storage_dr_product_id int,
		@renewal_storage_dr_product_id int,
		@language_code varchar(2),
		@location_code varchar(3)	
)

/*	
	DATE		AUTHOR		REMARKS
	2010-02-22	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@dr_bundle_id int,
			@product_count tinyint,
			@offer_id bigint,
			@parent_product_id int,
			@dr_product_id int
			
	select @product_count = 0

	begin try
--
--	select upgrade_dr_product_id = @upgrade_dr_product_id,
--			renewal_dr_product_id = @renewal_dr_product_id,
--			storage_dr_product_id = @storage_dr_product_id,
--			renewal_storage_dr_product_id = @renewal_storage_dr_product_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--	 1.0) change values to null if inputs are blank
		if @upgrade_dr_product_id is null or @upgrade_dr_product_id = 0 
			begin select @upgrade_dr_product_id = 0 end 
		else
			begin select @product_count = @product_count + 1 end

		if @renewal_dr_product_id is null or @renewal_dr_product_id = 0 
			begin select @renewal_dr_product_id = 0 end 
		else
			begin select @product_count = @product_count + 1 end

		if @storage_dr_product_id is null or @storage_dr_product_id = 0 
			begin select @storage_dr_product_id = 0 end 
		else
			begin select @product_count = @product_count + 1 end

		if @renewal_storage_dr_product_id is null or @renewal_storage_dr_product_id = 0 
			begin select @renewal_storage_dr_product_id = 0 end 
		else
			begin select @product_count = @product_count + 1 end

--		select product_count = @product_count

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get upgrade and renewal products
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) get bundle 
		if @product_count > 1
			begin
				select @dr_bundle_id = dr_bundle_id
				from dr_bundle_products
				where upgrade_dr_product_id = @upgrade_dr_product_id 
					and	renewal_dr_product_id = @renewal_dr_product_id 
					and storage_dr_product_id = @storage_dr_product_id 
					and renewal_storage_dr_product_id = @renewal_storage_dr_product_id

				select @offer_id = offer_id,
						@parent_product_id = parent_product_id
				from dr_bundle
				where dr_bundle_id = @dr_bundle_id
			end
		-- 2.2) get bundle 
		else
			begin
			select @dr_product_id = case
									when @upgrade_dr_product_id <> 0 then @upgrade_dr_product_id
									when @renewal_dr_product_id <> 0 then @renewal_dr_product_id
									when @storage_dr_product_id <> 0 then @storage_dr_product_id
									when @renewal_storage_dr_product_id <> 0 then @renewal_storage_dr_product_id
									end
			end

		-- 3.0 return dr_bundle_id

		if @offer_id is null and @parent_product_id is null and @dr_product_id is null
			begin
				select @response_code = -120,
						@message = convert(varchar(20),isnull(@upgrade_dr_product_id,'')) + ',' + convert(varchar(20),isnull(@renewal_dr_pro
duct_id,'')) + ',' + convert(varchar(20),isnull(@storage_dr_product_id,'')) + ',' + convert(varchar(20),isnull(@renewal_storage_dr_product_id,'')) + ',' + @language_code + ',' + @location_code + ' do not have a matching offer'
				RAISERROR (@message, 11, 0)
			end

		select offer_id = @offer_id,
				parent_product_id = @parent_product_id,
				dr_product_id = @dr_product_id
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select bundle failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_license]

(
	@keycode varchar(40) = null,
	@license_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @response_code int,
			@message varchar(100)
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select @license_id if null
	if @license_id is null
		begin
		select @license_id = license_id
		from license
		where keycode = @keycode
		end
	
	-- 1.2) check for alias
	if @license_id is null
		begin
		select @license_id = license_id
		from license_keycode_alias
		where keycode_alias = @keycode
		end

	-- 1.3) result
	select license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id
	from dbo.fn_license_select_license_profile(@license_id)


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not select licesnse for keycode : ' + @keycode
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_billing_model]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_select_license_billing_model]


(
	@locale char(5), 
	@license_id int = null,
	@license_category_id int = null, 
	@product_type_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2018-04-25	esmart		Initial creation.

	DESCRIPTION
	select pricing data for configurator
*/

AS

set nocount on				

begin try

		declare --@license_category_id int, 
				@current_license_attribute_id int, 
				@current_license_attribute_license_value int, 
				@category_type_name varchar(10),
				@expiration_date datetime,
				@days_remaining int,
				@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) license profile data
		select @license_category_id = c.license_category_id, @current_license_attribute_license_value = p.license_attribute_license_value, @category_type_name = p.category_type_name, @expiration_date = p.expiration_date,
				@days_remaining = datediff(dd,getdate(),p.expiration_date)
		from dbo.fn_license_select_license_profile(@license_id) p
		inner join license_category c
			on c.license_category_name = p.license_category_name
		where item_hierarchy_id = 1

		-- 1.2) @product_type_id
		if @product_type_id is null
			begin
				select @product_type_id = case
												when @category_type_name = 'trial' then 1
												when @category_type_name = 'full' and @days_remaining < 90 then 2
												when @category_type_name = 'full' and @days_remaining > 90 then 3
												else 1
											end
			end

		-- select category_type_name = @category_type_name, expiration_date = @expiration_date, days_remaining = @days_remaining, license_category_id = @license_category_id, current_license_attribute_license_value = @current_license_attribute_license_value
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) billing model 
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @product_license_category_attribute table (license_category_id int, license_category_name varchar(50), product_type_id int, product_type_description varchar(50), locale char(5), license_attribute_id int, license_attribute_description varchar(50), license_attribute_license_value int, license_attribute_license_value_description varchar(50), current_license_attribute_id int, current_license_attribute_description varchar(50), current_license_attribute_license_value int, current_license_attribute_license_value_description varchar(50))

		-- 2.1) @product_license_category_attribute
		insert into @product_license_category_attribute (license_category_id, license_category_name, product_type_id, product_type_description, locale, current_license_attribute_id, current_license_attribute_description, current_license_attribute_license_value, current_license_attribute_license_value_description, license_attribute_id, license_attribute_description, license_attribute_license_value, license_attribute_license_value_description)
		select c.license_category_id, c.license_category_name, t.product_type_id, t.product_type_description, pa.locale,
			pa.current_license_attribute_id, current_license_attribute_description = ac.license_attribute_description, pa.current_license_attribute_license_valu
e, 
			current_license_attribute_license_value_description = vc.license_attribute_license_value_description,
			a.license_attribute_id, a.license_attribute_description, v.license_attribute_license_value, v.license_attribute_license_value_description
		from product_license_category_license_attribute pa
		inner join license_category c
			on c.license_category_id = pa.license_category_id
		inner join product_type t
			on t.product_type_id = pa.product_type_id
		inner join license_attribute a
			on a.license_attribute_id = pa.license_attribute_id
		inner join license_attribute_license_value v
			on v.license_attribute_license_value = pa.license_attribute_license_value
		left join license_attribute ac
			on pa.current_license_attribute_id = ac.license_attribute_id
		left join license_attribute_license_value vc
			on vc.license_attribute_license_value = pa.current_license_attribute_license_value
		where pa.license_category_id = @license_category_id and pa.product_type_id = @product_type_id and pa.locale = @locale

		-- 2.2) return results
		if @current_license_attribute_license_value is null	
			begin
				select * 
				from @product_license_category_attribute
				where current_license_attribute_id is null
			end
		else
			begin
				select * 
				from @product_license_category_attribute
				where current_license_attribute_license_value = @current_license_attribute_license_value
			end
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'report failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_cart_discount]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_license_cart_discount]

(
	@license_id int,
	@cart_discount_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2012-12-05	esmart		Initial creation.

	DESCRIPTION
	select campaign driven percent off discount for given license
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @cart_discount_id = (select top 1 cart_discount_id
								from license_cart_discount
								where license_id = @license_id and (start_date <= getdate() and (getdate() <= end_date or end_date is null))
								order by license_cart_discount_id desc)
			
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_configurator_pricing]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_select_license_configurator_pricing] (
    @item_json NVARCHAR(MAX),
    @bundle_json NVARCHAR(MAX),
    @opt_args VARCHAR(100) = ''
)

/*
	DATE			AUTHOR		REMARKS
	2018-04-25		esmart		Initial creation.
	2018-10-22		esmart		Add usage_price for autobilling utility and overage
	2018-12-03		esmart		Fix issue with adding secondary on primary renewal
	2018-12-11		esmart		Fix online discounting
	2019-04-01		jnavarra	Add consumer pricing
	2019-04-02		jnavarra	Compensate for leap years
	2019-05-21		esmart		Fix consumer
	2019-06-30		esmart		No upgrade items on monthly billing models
	2019-10-23		jnavarra	Force quantity "1" on consumer products
	2019-12-17		jnavarra	Add equivalent_year_price
	2020-01-06		wbarton		Modified sections 4.1.2 and 4.1.7.2 to introduce unit_price and usage_price discount grandfathering via newly created discount models. Logic in 4.1.7.2-4 now matches usp_cart_insert_cart_order_item.
	2020-01-14		jnavarra    equivalent_year_price prioritize locale pricing
	2020-02-12		wbarton		Hotfix in 4.1.2, replacing usp_license_select_category_discount_model with a function call, since email processes call the configurator as an insert into - exec, creating a nesting problem
	2020-02-14		wbarton		Refactoring 4.1.2 to support JSON operations in/out of usp_license_select_category_discount_model. This allows us to log data from the subroutine, but avoids creating insert into - exec nesting
	2020-04-14		jnavarra	Parse cart_discount_id
	2020-08-19		jnavarra	Default secondary product start_date as expiration_date (fallback to primary product's new start_date)
	2020-09-22		jnavarra	Correct previous secondary product start_date to account for upgrades
	2020-11-06		abelenkiy   Changed message_campaign_name in table variable from varchar(50) to varchar(65) to match message_campaign table (section 4.1.5)
                                Hardcoded @source_caller input to usp_license_select_category_discount_model to avoid exceeding length limit (section 4.1.2)
	2020-12-01		abelenkiy   AXIOM-2275 - Hotfix to use retail price for list price when discount value of 0 passed in explicitly (section 3.1.4)
	2021-01-15		jnavarra	Update rounding precision (sections 3.1.4, 3.1.5, 4.1.6)
	2021-12-08		psatish		Added Perpetual billing model for Usage pricing
	2024-02-26		rambasana	Update price from cpProduct API, if zuora campaign_id exists. 
	2024-12-27		psatish		US-4224198 Modified the section 3.1.3 to pass the message campaign name to the procedure: usp_cart_select_renewal_product_set
	2025-06-16		jberry		US-4833298 Update sec 2.4 to use fn_product_select_profile to select the product
	          		     		- Changed sec 4.1.7.4 to ignore discounts for licenses with a usage_pricing model (carbonite)
	          		     		- Added storage_gb and retention to @item_discount_json and to the return dataset
	2025-10-14		jberry		US-5004939 - Added actual_storage_quantity to return. This field converts storage_gb to TBs to use for pricing calculations for storage products
	2025-11-19		jberry		US-5093883 - Modified sec 2.2.1 so an upgrade line is not added for carbonite orders when the quantity is being increased on an order
    2026-06-04      gblandford  D-5375484 - https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5375484
                                - Utility licenses with expiration beyond a year were falling through the primary product_type logic. 
                                  (Utility licenses are now extended by two years and in the billing expiration update job).
                                  This was causing the configurator to not assign a product_type_id to the primary product and subsequentl
y not allow checkout
                                  in cart. Resolved by adding an ELSE statement to the primary product_type_id assignment logic in section 2.2
                                - formatting and case changes, removed commented out code, and added additional comments for clarity
                                - added @opt_args to assist in debugging
                                - renumbered sections
                                - added schemas where missing
                                - added SET TRANSACTION ISOLATION LEVEL at the beginning of the proc

    DESCRIPTION
    Calculates and returns cart pricing rows for license configurator requests.
    The procedure normalizes incoming item/bundle JSON, derives product type and
    product selection, applies discount/business pricing rules, and returns
    checkout-ready item rows including list/unit/usage pricing.

    RUN CONTEXT
    - Invoked by configurator and renewal messaging flows (including auto-renewal
        and message output workflows).
    - Executes under READ UNCOMMITTED isolation and uses OPENJSON-based parsing.
    - Supports debug output when @opt_args contains ''debug''.
    - Handles both direct and partner pricing paths.

    HIGH-LEVEL FLOW
    1) Parse request payload
         - Read @bundle_json and @item_json into working variables/table sets.
    2) Resolve license context
         - Load existing license/profile data and derive locale/language/location.
    3) Build product intent
         - Determine start/expiration dates, product_type_id, and upgrade behavior.
    4) Resolve products and prices
         - Select products, populate list/unit/usage pricing, and apply campaign/
             tier/discount logic.
    5) Return output rows
         - Emit normalized line items with pricing, product metadata, discount data,
             and storage/retention-related fields.

    PARAMETERS
    @item_json NVARCHAR(MAX)
        JSON array of incoming cart lines (category, seats, years, dates, bundle,
        hierarchy, discount, storage/retention attributes, etc.).

    @bundle_json NVARCHAR(MAX)
        JSON object with request-level context (locale, keycode, billing model,
        campaign/message values, and optional discount identifiers).

    @opt_args VARCHAR(100) = ''
        Optional execution flags; currently used for debug behavior when it contains
        ''debug''.

    DEPENDENCIES
    Procedures
    - dbo.usp_cart_select_renewal_product_set
    - dbo.usp_license_select_category_discount_model
    - dbo.usp_LogError

    Functions
    - dbo.fn_locale_to_lang_loc
    - dbo.fn_license_select_license_profile
    - dbo.fn_product_select_profile
    - dbo.fn_leap_days_between
    - dbo.fn_cart_select_one_year_products
    - dbo.fn_app_config_select_key_values

    Primary reference tables/views (non-exhaustive)
    - dbo.license, dbo.license_distribution_method
    - dbo.license_category, dbo.license_category_product_line
    - dbo.product, dbo.product_pricing, dbo.product_years,
        dbo.product_capability, dbo.product_storage, dbo.product_extension
    - dbo.partner_pricing_tier, dbo.zuora_product_pricing
    - dbo.license_cart_discount, dbo.cart_discount_item
    - dbo.message_campaign and related message_campaign_* tables

*/

AS

SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

BEGIN TRY

    DECLARE @locale VARCHAR(5),
        @language_code VARCHAR(2),
        @location_code VARCHAR(3),
        @keycode VARCHAR(40),
        @license_id INT,
        @license_category_name VARCHAR(10),
        @license_seats INT,
        @storage_gb INT,
        @years FLOAT,
        @cart_discount_id INT,
        @license_distribution_method_id INT,
        @license_attribute_id INT,
        @license_attribute_license_value INT,
        @license_keycode_type_id INT,
        @partner_id INT,
        @site_id VARCHAR
(20),
        @insert_date DATETIME,
        @insert_by VARCHAR(20),
        @currency_id TINYINT,
        @product_line_id INT,
        @percent_discount FLOAT,
        @product_type_id INT,
        @message_key VARCHAR(36),
        @response_code INT,
        @message VARCHAR(100),
        @campaign_id INT,
        @license_distribution_method_code VARCHAR(4),
	    @message_campaign_name VARCHAR(65),
        @debug_mode BIT = 0

    DECLARE @item_table TABLE (
        item_id INT IDENTITY(1, 1),
        license_category_name VARCHAR(10),
        license_seats INT,
        total_license_seats INT,
        storage_gb INT,
        retention_model_id INT,
        usage_pricing_model_id INT,
        years FLOAT,
        license_keycode_type_id INT,
        start_date DATETIME,
        expiration_date DATETIME,
        vendor_order_item_code VARCHAR(36),
        cart_item_bundle_id INT,
        item_hierarchy_id TINYINT,
        product_id INT,
        product_type_id INT,
        order_item_offer_amount MONEY DEFAULT 0,
        list_price MONEY DEFAULT 0,
        unit_price MONEY DEFAULT 0,
        discount FLOAT,
        cart_discount_method_id TINYINT,
        cart_discount_id INT,
        usage_price MONEY DEFAULT 0
    );

    DECLARE @license_table TABLE (
        license_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        usage_pricing_model_id INT,
        retention_model_id INT,
        product_platform_id INT
    );

    IF @opt_args LIKE '%debug%' BEGIN
            SET @debug_mode = 1;
        END;

    DECLARE @CARBONITE_LICENSE_CATEGORIES TABLE (
        license_category_id INT,
		license_category_name VARCHAR(10)
    )

    DECLARE @message_campaign_cart_discount TABLE (
        message_campaign_id INT,
        message_campaign_name VARCHAR(65),
        message_campaign_class_id TINYINT,
        message_campaign_class_name VARCHAR(50),
        message_campaign_start_date DATETIME,
        message_campaign_end_date DATETIME,
        license_distribution_method_id INT,
        inclusive TINYINT,
        license_seats INT,
        license_category_id INT,
        license_category_name VARCHAR(10),
        autorenewal_opt_id TINYINT,
        language_code VARCHAR(2),
        location_code VARCHAR(3),
        cart_discount_id INT
    );


    INSERT INTO @CARBONITE_LICENSE_CATEGORIES (
        license_category_id,
		license_category_name
    )
    SELECT f.[key],
			f.value
    FROM [dbo].[fn_app_config_select_key_values]('CARBONITE_LICENSE_CATEGORIES', 'CARBONITE') f

    SELECT @insert_date = GETDATE(),
        @insert_by = SUSER_SNAME();

    IF ( @debug_mode = 1 ) BEGIN
            SELECT 'CARBONITE_LICENSE_CATEGORIES' AS debug_message, * FROM @CARBONITE_LICENSE_CATEGORIES;
        END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 1.1) @bundle_json
    SELECT @locale = locale,
           @keycode = ( CASE
                              WHEN keycode = '' THEN NULL
                              ELSE keycode
                          END ),
           @license_attribute_license_value = license_attribute_license_value,
           @license_keycode_type_id = license_keycode_type_id,
           @message_key = message_key,
           @cart_discount_id = cart_discount_id,
		   @message_campaign_name=message_campaign_name
    FROM 
OPENJSON( @bundle_json )
    WITH (
        locale VARCHAR(40) '$.locale',
        keycode VARCHAR(40) '$.keycode',
        license_attribute_license_value INT '$.license_attribute_license_value',
        license_keycode_type_id INT '$.license_keycode_type_id',
        message_key VARCHAR(36) '$.message_key',
        cart_discount_id INT '$.cart_discount_id',
		message_campaign_name VARCHAR(65) '$.message_campaign_name'
    );

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.1' AS debug_message,
                @locale AS locale,
                @keycode AS keycode,
                @license_attribute_license_value AS license_attribute_license_value,
                @license_keycode_type_id AS license_keycode_type_id,
                @message_key AS message_key,
                @cart_discount_id AS cart_discount_id,
                @message_campaign_name AS message_campaign_name;
        END;


    -- 1.1.1) @language_code and @location_code
    SELECT @language_code = language_code,
        @location_code = location_code
    FROM dbo.fn_locale_to_lang_loc(@locale);

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.1.1' AS debug_message,
                @language_code AS language_code,
                @location_code AS location_code;
        END;

    -- 1.1.2) @license_id
    IF @keycode IS NOT NULL BEGIN
            SELECT 
                @license_id = l.license_id,
                @license_keycode_type_id = ( CASE
                                                    WHEN @license_keycode_type_id IS NULL THEN l.license_keycode_type_id
                                                    ELSE @license_keycode_type_id
                                                END ),
                @license_distribution_method_id = l.license_distribution_method_id,
                @product_line_id = l.product_line_id,
                @license_distribution_method_code = ldm.license_distribution_method_code
            FROM dbo.license l
                INNER JOIN dbo.license_distribution_method AS ldm
                    ON ldm.license_distribution_method_id = l.license_distribution_method_id
            WHERE l.keycode = @keycode;

        END;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.1.2' AS debug_message,
                @license_id AS license_id,
                @license_keycode_type_id AS license_keycode_type_id,
                @license_distribution_method_id AS license_distribution_method_id,
                @product_line_id AS product_line_id,
                @license_distribution_method_code AS license_distribution_method_code;
        END;

    -- 1.1.3) @license_attribute_id
    SELECT 
        @license_attribute_id = license_attribute_id
    FROM dbo.license_attribute_license_value
    WHERE license_attribute_license_value = @license_attribute_license_value;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.1.3' AS debug_message,
                @license_attribute_id AS license_attribute_id;
        END;
    
    -- 1.2) @item_table
    INSERT INTO @item_table (
        license_category_name,
        license_seats,
        total_license_seats,
        storage_gb,
        retention_model_id,
        years,
        license_keycode_type_id,
        start_date,
        expiration_date,
        vendor_order_item_code,
        cart_item_bundle_id,
        item_hierarchy_id,
        discount,
        cart_discount_method_id
    )
    SELECT 
        license_category_name,
        license_seats,
        license_seats,
        storage_gb,
        retention_model_id,
        years = CASE
                    WHEN years = '' THEN
                        0
                    ELSE
                        years
                END,
        @license_keycode_type_id,
        start_date = CASE
                        WHEN start_date = '' THEN
                            NULL
                        ELSE
    
                        start_date
                    END,
        expiration_date = CASE
                                WHEN expiration_date = '' THEN
                                    NULL
                                ELSE
                                    expiration_date
                            END,
        vendor_order_item_code = CASE
                                    WHEN vendor_order_item_code = '' THEN
                                        NULL
                                    ELSE
                                        vendor_order_item_code
                                END,
        cart_item_bundle_id = ISNULL(cart_item_bundle_id, 1),
        item_hierarchy_id,
        discount,
        cart_discount_method_id

    FROM OPENJSON( @item_json )
    WITH (  license_category_name VARCHAR(10) '$.license_category_name',
            license_seats INT '$.license_seats',
            storage_gb INT '$.storage_gb',
            retention_model_id INT '$.retention_model_id',
            years FLOAT '$.years',
            license_keycode_type_id INT '$.license_keycode_type_id',
            locale VARCHAR(5) '$.locale',
            license_attribute_license_value INT '$.license_attribute_license_value',
            start_date DATETIME '$.start_date',
            expiration_date DATETIME '$.expiration_date',
            cart_item_bundle_id INT '$.cart_item_bundle_id',
            item_hierarchy_id INT '$.item_hierarchy_id',
            vendor_order_item_code VARCHAR(36) '$.vendor_order_item_code',
            discount FLOAT '$.discount',
            cart_discount_method_id TINYINT '$.cart_discount_method_id'
        );

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.2' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 1.3) @license_table
    IF ( @license_id IS NOT NULL ) BEGIN
            INSERT INTO @license_table (
                license_id,
                license_category_name,
                license_seats,
                storage_gb,
                license_keycode_type_id,
                license_attribute_license_value,
                start_date,
                expiration_date,
                category_type_name,
                item_hierarchy_id,
                usage_pricing_model_id,
                retention_model_id,
                product_platform_id
            )
            SELECT 
                license_id,
                license_category_name,
                license_seats,
                storage_gb,
                license_keycode_type_id,
                license_attribute_license_value,
                start_date,
                expiration_date,
                category_type_name,
                item_hierarchy_id,
                usage_pricing_model_id,
                retention_model_id,
                product_platform_id
            FROM dbo.fn_license_select_license_profile(@license_id);
        END;
	
    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.3' AS debug_message,
                *
            FROM @license_table;
        END;

    -- 1.4) upgrade license_seats and storage
    IF @product_line_id IN ( 55, 300 ) BEGIN
            UPDATE i
                SET license_seats = i.license_seats - l.license_seats
            FROM @item_table i
                INNER JOIN @license_table l
                    ON l.license_category_name = i.license_category_name
            WHERE i.years = 0;

            UPDATE i
               SET storage_gb = i.storage_gb - l.storage_gb
            FROM @item_table i
               INNER JOIN @license_table l
                   ON l.license_category_name = i.license_category_name
            WHERE i.years = 0
                AND l.usage_pricing_model_id = 2;   --capacity
        END;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.4' AS debug_message,
                *
            FR
OM @item_table;
        END;


    -- 1.9) @product_line_id
    IF ( @product_line_id IS NULL ) BEGIN
            SELECT 
                @product_line_id = pl.product_line_id
            FROM @item_table i
                INNER JOIN dbo.license_category lc
                    ON lc.license_category_name = i.license_category_name
                INNER JOIN dbo.license_category_product_line pl
                    ON pl.license_category_id = lc.license_category_id
                       AND pl.language_code = @language_code
                       AND pl.location_code = @location_code;
        END;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '1.9' AS debug_message,
                @product_line_id AS product_line_id;
        END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) product set
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 2.1) primary start_date and expiration_date
    UPDATE i
        SET start_date = CASE
                             WHEN l.license_id IS NULL
                                  AND i.start_date IS NULL THEN
                                 CONVERT(DATE, GETDATE())
                             WHEN l.license_id IS NOT NULL
                                  AND i.start_date IS NULL
                                  AND l.category_type_name = 'trial' THEN
                                 CONVERT(DATE, GETDATE())
                             WHEN l.license_id IS NOT NULL
                                  AND i.start_date IS NULL
                                  AND l.category_type_name = 'full'
                                  AND i.years = 0 THEN
                                 CONVERT(DATE, GETDATE())
                             WHEN l.license_id IS NOT NULL
                                  AND i.start_date IS NULL
                                  AND l.category_type_name = 'full'
                                  AND i.years <> 0
                                  AND l.expiration_date < GETDATE() THEN
                                 CONVERT(DATE, GETDATE())
                             WHEN l.license_id IS NOT NULL
                                  AND i.start_date IS NULL
                                  AND l.category_type_name = 'full'
                                  AND i.years <> 0
                                  AND l.expiration_date >= GETDATE() THEN
                                 l.expiration_date
                             ELSE
                                 i.start_date
                         END,
        expiration_date = CASE
                              WHEN l.license_id IS NULL
                                   AND i.expiration_date IS NULL THEN
                                  DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                              WHEN l.license_id IS NOT NULL
                                   AND i.expiration_date IS NULL
                                   AND l.category_type_name = 'trial' THEN
                                  DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                              WHEN l.license_id IS NOT NULL
                                   AND i.expiration_date IS NULL
                                   AND l.category_type_name = 'full'
                                   AND i.start_date IS NULL
                                   AND l.expiration_date < GETDATE() THEN
                                  DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                              WHEN l.license_id IS NOT NULL
                                   AND i.expiration_date IS NULL
                                   AND l.category_type_name = 'full'
                       
            AND i.start_date IS NULL
                                   AND l.expiration_date >= GETDATE() THEN
                                  DATEADD(mm, i.years * 12, l.expiration_date)
                              WHEN l.license_id IS NOT NULL
                                   AND i.expiration_date IS NULL
                                   AND l.category_type_name = 'full'
                                   AND i.start_date IS NOT NULL THEN
                                  DATEADD(mm, i.years * 12, i.start_date)
                              ELSE
                                  i.expiration_date
                          END
    FROM @item_table i
        LEFT JOIN @license_table l
            ON l.item_hierarchy_id = i.item_hierarchy_id
    WHERE i.item_hierarchy_id = 1;

    if ( @debug_mode = 1 ) BEGIN
            SELECT '2.1' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.1.1) secondary start_date and expiration_date
    UPDATE i
        SET i.start_date = CASE
                               WHEN i2.start_date IS NULL
                                    AND i.years = 0 THEN
                                   CONVERT(DATE, GETDATE())
                               WHEN i2.start_date IS NULL
                                    AND i.years > 0 THEN
                                   ISNULL(l.expiration_date, CONVERT(DATE, GETDATE()))
                               WHEN i2.start_date IS NOT NULL
                                    AND i.years > 0
                                    AND
                                    (
                                        l.category_type_name IS NULL
                                        OR l.category_type_name = 'trial'
                                    ) THEN
                                   CONVERT(DATE, GETDATE())
                               ELSE
                                   COALESCE(
                                               CASE
                                                   WHEN i.years = 0 THEN
                                                       i2.start_date
                                                   WHEN l.expiration_date < GETDATE() -- Default to the previous expiration date, but don't set the start date any earlier than today
                                               THEN
                                                       CONVERT(DATE, GETDATE())
                                                   ELSE
                                                       l.expiration_date
                                               END,
                                               i2.start_date -- Without the previous expiration date, use the start_date of the primary product
                                           )
                           END,
        i.expiration_date = CASE
                                WHEN i2.expiration_date IS NOT NULL THEN
                                    i2.expiration_date -- expiration from primary product
                                WHEN i2.expiration_date IS NULL THEN
                                    x.expiration_date  -- upgrade of secondary only
                            END
    FROM @item_table i
        LEFT JOIN @license_table l
            ON l.license_category_name = i.license_category_name
        LEFT JOIN @item_table i2
            ON i2.cart_item_bundle_id = i.cart_item_bundle_id
               AND i2.item_hierarchy_id = 1
        LEFT JOIN (
                    SELECT license_id,
                           expiration_date = MAX(expiration_date)
                    FROM @license_table
                    GROUP BY license_id
                ) x
            ON x.license_id = @license_id
    WHERE i.item_hierarchy_id = 2;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.1.1' AS debug_message,
                *
            FROM @item_table;
        EN
D;

    -- 2.2) primary product_type
    UPDATE i
        SET product_type_id = CASE
                                    WHEN l.license_id IS NULL THEN 1 -- New
                                    WHEN l.license_id IS NOT NULL
                                        AND l.category_type_name = 'trial' THEN 1 -- Trial conversion
                                    WHEN l.license_id IS NOT NULL
                                        AND l.category_type_name = 'full'
                                        AND i.expiration_date > l.expiration_date THEN 2 -- Renewal
                                    WHEN l.license_id IS NOT NULL
                                        AND l.category_type_name = 'full'
                                        AND i.expiration_date = l.expiration_date
                                        AND (    i.license_category_name <> l.license_category_name
                                                    OR i.total_license_seats > l.license_seats
                                                    OR i.storage_gb > l.storage_gb ) THEN 3 -- Upgrade
                                    ELSE 2 -- Default to Renewal to match logic in cart_item insert
                                  END
    FROM @item_table i
        LEFT JOIN @license_table l
            ON l.item_hierarchy_id = i.item_hierarchy_id
    WHERE i.item_hierarchy_id = 1
          AND i.product_type_id IS NULL;

    if ( @debug_mode = 1 ) BEGIN
            SELECT '2.2' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.2.1) upgrade
    IF @product_line_id IN ( 100, 200 ) BEGIN
            INSERT INTO @item_table (
                license_category_name,
                license_seats,
                total_license_seats,
                storage_gb,
                retention_model_id,
                years,
                license_keycode_type_id,
                start_date,
                expiration_date,
                cart_item_bundle_id,
                item_hierarchy_id,
                product_type_id
            )
            SELECT 
                i.license_category_name,
                l.license_seats,
                i.total_license_seats,
                i.storage_gb,
                i.retention_model_id,
                years = 0,
                i.license_keycode_type_id,
                start_date = CONVERT(DATE, GETDATE()),
                l.expiration_date,
                i.cart_item_bundle_id,
                i.item_hierarchy_id,
                product_type_id = 3
            FROM @item_table i
                INNER JOIN @license_table l
                    ON l.item_hierarchy_id = i.item_hierarchy_id
            WHERE i.item_hierarchy_id = 1
                AND i.product_type_id = 2
                AND ( i.license_category_name <> l.license_category_name
                    OR i.license_seats > l.license_seats )
                AND l.expiration_date > GETDATE();
        END;
    ELSE BEGIN
            INSERT INTO @item_table (
                license_category_name,
                license_seats,
                total_license_seats,
                storage_gb,
                retention_model_id,
                years,
                license_keycode_type_id,
                start_date,
                expiration_date,
                cart_item_bundle_id,
                item_hierarchy_id,
                product_type_id,
                cart_discount_id,
                discount,
                cart_discount_method_id
            )
            SELECT 
                i.license_category_name,
                i.license_seats - l.license_seats,
                i.total_license_seats,
                i.storage_gb - l.storage_gb,
                i.retention_model_id,
                0,
                i.license_keycode_type_id,
                CONVERT(DATE, GETDATE()),
                l.expiration_
date,
                i.cart_item_bundle_id,
                i.item_hierarchy_id,
                product_type_id = 3,
                i.cart_discount_id,
                i.discount,
                i.cart_discount_method_id
            FROM @item_table i
                INNER JOIN @license_table l
                    ON l.item_hierarchy_id = i.item_hierarchy_id
                LEFT JOIN @CARBONITE_LICENSE_CATEGORIES clc
                    ON clc.license_category_name = i.license_category_name
            WHERE i.item_hierarchy_id = 1
                  AND i.product_type_id = 2
                  AND ( i.license_category_name <> l.license_category_name
                      OR i.license_seats > l.license_seats
                      OR i.storage_gb > l.storage_gb )
                  AND l.expiration_date > GETDATE()
                  AND clc.license_category_name IS null
                  AND ( @license_attribute_license_value NOT IN ( 
                            12, 
                            110, 
                            111, 
                            112, 
                            210, 
                            211, 
                            212, 
                            13, 
                            113, 
                            213 
                        )
                        AND l.license_attribute_license_value NOT IN ( 
                            12, 
                            110, 
                            111, 
                            112, 
                            210, 
                            211, 
                            212, 
                            13, 
                            113, 
                            213 
                        )
                  );
        END;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.2.1' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.3) secondary product_type
    UPDATE i
       SET product_type_id = CASE
                                WHEN l.license_id IS NULL THEN 1 -- New
                                WHEN l.license_id IS NOT NULL
                                    AND l.category_type_name = 'trial' THEN 1 -- trial conversion
                                WHEN l.license_id IS NOT NULL
                                    AND l.category_type_name = 'full'
                                    AND i.expiration_date > l.expiration_date THEN 2
                                WHEN l.license_id IS NOT NULL
                                    AND l.category_type_name = 'full'
                                    AND i.expiration_date = l.expiration_date
                                    AND i.total_license_seats > l.license_seats THEN 3
                            END
    FROM @item_table i
        LEFT JOIN @license_table l
            ON l.item_hierarchy_id = i.item_hierarchy_id
                AND l.license_category_name = i.license_category_name
    WHERE i.item_hierarchy_id = 2
        AND i.product_type_id IS NULL;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.3' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.3.1) upgrade
    INSERT INTO @item_table (
        license_category_name,
        license_seats,
        total_license_seats,
        storage_gb,
        years,
        license_keycode_type_id,
        start_date,
        expiration_date,
        cart_item_bundle_id,
        item_hierarchy_id,
        product_type_id
    )
    SELECT 
        i.license_category_name,
        i.license_seats - l.license_seats,
        i.license_seats,
        i.storage_gb,
        0,
        i.license_keycode_type_id,
        CONVERT(DATE, GETDATE()),
        l.expiration_date,
        i.cart_item_bundle_id,
        i.item_hierarchy_id,
        product_type_id = 3
    FROM @item_table i
        INNER JOIN @license
_table l
            ON l.item_hierarchy_id = i.item_hierarchy_id
               AND l.license_category_name = i.license_category_name
    WHERE i.item_hierarchy_id = 2
        AND i.product_type_id = 2
        AND i.total_license_seats > l.license_seats
        AND ( @license_attribute_license_value NOT IN ( 
                12, 
                110, 
                111, 
                112, 
                210, 
                211, 
                212, 
                13, 
                113, 
                213 
            ) 
        AND l.license_attribute_license_value NOT IN (
                12, 
                110, 
                111, 
                112, 
                210, 
                211, 
                212, 
                13, 
                113, 
                213 
            )
        );

    -- 2.3.2) update years on new upgrade
    UPDATE I
        SET years = 1
    FROM @item_table i
    WHERE i.item_hierarchy_id = 2
        AND i.product_type_id IN ( 1, 2 )
        AND i.years = 0;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.3.2' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.3.3) usage pricing model from @license_table 
    UPDATE i
        SET usage_pricing_model_id = l.usage_pricing_model_id
    FROM @item_table i
        INNER JOIN @license_table l
            ON l.license_category_name = i.license_category_name
    WHERE l.usage_pricing_model_id IS NOT NULL;

    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.3.3' AS debug_message,
                *
            FROM @item_table;
        END;

    -- 2.4) product
    IF @product_line_id IN (55,300,100) BEGIN
            UPDATE i
                SET i.product_id = f.product_id
            FROM @item_table i
                INNER JOIN dbo.license_category lc
                    ON lc.license_category_name = i.license_category_name
                LEFT JOIN @license_table l
                    ON l.license_category_name = i.license_category_name 
                        AND l.item_hierarchy_id = i.item_hierarchy_id
                CROSS APPLY dbo.fn_product_select_profile (
                                                        @product_line_id,
                                                        lc.license_category_id,
                                                        i.years,
                                                        ( CASE
                                                                WHEN @product_line_id IN (300,55) THEN 1 
                                                                ELSE i.license_seats 
                                                            END ),
                                                        i.storage_gb,
                                                        DATEDIFF(dd, i.start_date, i.expiration_date),
                                                        i.product_type_id,
                                                        i.license_keycode_type_id,
                                                        l.usage_pricing_model_id,
                                                        i.retention_model_id,
                                                        l.product_platform_id,
                                                        NULL   --sap_material_number
                                                        ) f
        END; 
 
    IF ( @debug_mode = 1 ) BEGIN
            SELECT '2.4' AS debug_message,
                *
            FROM @item_table;
        END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) @product_set consumer
    ---------------------------------------------------------------------------------------------------------------------------
----------------------------------------

    -- 3.1) consumer
    IF @product_line_id NOT IN ( 55, 300 ) BEGIN


        DECLARE @product_set TABLE (
            line_item INT IDENTITY(1, 1),
            product_id INT,
            product_description VARCHAR(100),
            quantity INT DEFAULT 1,
            retail_price MONEY,
            upgrade_price MONEY,
            discount MONEY,
            standard_discount MONEY,
            net_price MONEY,
            product_type_id INT,
            license_category_name VARCHAR(10),
            seats INT,
            years DECIMAL(18, 3),
            p_type VARCHAR(20),
            cart_item_class_id TINYINT,
            cart_item_bundle_id INT,
            keycode VARCHAR(40),
            currency_id TINYINT,
            currency_code CHAR(3),
            currency_description VARCHAR(20),
            symbol_html VARCHAR(10),
            symbol_utf8 NVARCHAR(10),
            symbol_text VARCHAR(10),
            cart_discount_id INT,
            license_category_id INT,
            license_attribute_id INT,
            license_attribute_license_value INT,
            start_date DATETIME,
            expiration_date DATETIME,
            contract_days FLOAT
        );

        -- 3.1.1) varibles
        SELECT 
            @license_category_name = license_category_name,
            @storage_gb = storage_gb
        FROM @item_table
        WHERE item_hierarchy_id = 1;

        SELECT 
            @product_type_id = product_type_id
        FROM @item_table
        WHERE item_hierarchy_id = 1
            AND license_category_name = 'WIFI';

        -- 3.1.2) years, seats
        SELECT 
            @years = MAX(years),
            @license_seats = MAX(total_license_seats)
        FROM @item_table
        WHERE item_hierarchy_id = 1;

        IF @debug_mode = 1 BEGIN
                SELECT '3.1.1 and 3.1.2' AS debug_message,
                    @license_category_name AS license_category_name,
                    @storage_gb AS storage_gb,
                    @product_type_id AS product_type_id,
                    @years AS years,
                    @license_seats AS license_seats;
            END;

        -- 3.1.3) insert product_set
        INSERT INTO @product_set (
            product_id,
            product_description,
            retail_price,
            upgrade_price,
            discount,
            standard_discount,
            net_price,
            product_type_id,
            license_category_name,
            seats,
            years,
            p_type,
            currency_id,
            currency_code,
            currency_description,
            symbol_html,
            symbol_utf8,
            symbol_text,
            cart_discount_id
        )
		EXECUTE dbo.usp_cart_select_renewal_product_set @keycode = @keycode,                     -- varchar(40)
                                             @license_category_name = @license_category_name, -- varchar(10)
                                             @license_seats = @license_seats,                 -- int
                                             @storage_gb = @storage_gb,                       -- int
                                             @years = @years,                                 -- float
                                             @cart_discount_id = @cart_discount_id,           -- int
                                             @language_code = @language_code,                 -- varchar(2)
                                             @location_code = @location_code,                 -- varchar(3)
                                             @cart_type_id = NULL,                            -- tinyint
                                             @currency_id = @currency_id,                     -- tinyint
                                             @product_type_id = @product_type_id,      
       -- int
                                             @message_campaign_name = @message_campaign_name  -- varchar(65)

        IF @debug_mode = 1 BEGIN
                SELECT '3.1.3' AS debug_message,
                    *
                FROM @product_set;
            END;

        -- 3.1.4) update @item_table
        UPDATE i
            SET product_id = p.product_id,
                list_price = p.retail_price,
                unit_price = CASE
                                    WHEN i.cart_discount_method_id = 3
                                        AND i.discount > 0 THEN p.retail_price - ROUND((i.discount / 100) * p.retail_price, 2)
                                    WHEN i.cart_discount_method_id = 1
                                        AND i.discount > 0 THEN p.retail_price - i.discount
                                    WHEN i.discount = 0 THEN p.retail_price
                                    ELSE p.upgrade_price
                                END,
                license_seats = 1,
                total_license_seats = 1
            FROM @item_table i
                INNER JOIN @product_set p
                    ON p.license_category_name = i.license_category_name
                        AND p.product_type_id = i.product_type_id
                        AND i.item_hierarchy_id = 1; -- and i.product_type_id in (2,3)

        IF @debug_mode = 1 BEGIN
                SELECT '3.1.4' AS debug_message,
                    *
                FROM @item_table;
            END;

        -- 3.1.5) update pricing for storage upgrade
        UPDATE i
            SET product_id = p.product_id,
                list_price = p.retail_price,
                unit_price = CASE
                                WHEN i.cart_discount_method_id = 3
                                    AND i.discount > 0 THEN p.retail_price - ROUND((i.discount / 100) * p.retail_price, 2)
                                WHEN i.cart_discount_method_id = 1
                                    AND i.discount > 0 THEN p.retail_price - i.discount
                                ELSE p.upgrade_price
                            END
        FROM @item_table i
            INNER JOIN @product_set p
                ON p.product_type_id = i.product_type_id
                   AND i.item_hierarchy_id = 1
                   AND i.storage_gb IS NOT NULL
                   AND i.product_type_id = 3;

        IF @debug_mode = 1 BEGIN
                SELECT '3.1.5' AS debug_message,
                    *
                FROM @item_table;
            END;

        -- 3.1.6) insert storage product
        INSERT INTO @item_table (
            product_id,
            license_category_name,
            license_seats,
            total_license_seats,
            storage_gb,
            years,
            license_keycode_type_id,
            start_date,
            expiration_date,
            cart_item_bundle_id,
            item_hierarchy_id,
            product_type_id,
            list_price,
            unit_price
        )
        SELECT
            s.product_id,
            NULL,
            1,
            1,
            ps.storage_gb,
            ISNULL(s.years, 0),
            p.license_keycode_type_id,
            NULL,
            NULL,
            1,
            1,
            s.product_type_id,
            s.retail_price,
            s.upgrade_price
        FROM @product_set s
            INNER JOIN dbo.product_storage ps
                ON ps.product_id = s.product_id
            INNER JOIN dbo.product p
                ON p.product_id = s.product_id
            LEFT JOIN @item_table i
                ON i.product_id = s.product_id
        WHERE i.product_id IS NULL
        ORDER BY p.product_type_id DESC;

        IF @debug_mode = 1 BEGIN
                SELECT '3.1.6' AS debug_message,
                    *
                FROM @item_table;
            E
ND;

        IF @license_category_name IS NULL BEGIN
                SELECT @license_category_name = license_category_name
                FROM @license_table
                WHERE item_hierarchy_id = 1;
            END;
        -- 3.1.7) get license_category_name if empty
        IF @debug_mode = 1 BEGIN
                SELECT '3.1.7' AS debug_message,
                    @license_category_name AS license_category_name;
            END;

        -- 3.1.8) update dates
        UPDATE i
            SET start_date = CASE
                                WHEN l.license_id IS NULL
                                    AND i.start_date IS NULL THEN
                                    CONVERT(DATE, GETDATE())
                                WHEN l.license_id IS NOT NULL
                                    AND i.start_date IS NULL
                                    AND l.category_type_name = 'trial' THEN
                                    CONVERT(DATE, GETDATE())
                                WHEN l.license_id IS NOT NULL
                                    AND i.start_date IS NULL
                                    AND l.category_type_name = 'full'
                                    AND i.years = 0 THEN
                                    CONVERT(DATE, GETDATE())
                                WHEN l.license_id IS NOT NULL
                                    AND i.start_date IS NULL
                                    AND l.category_type_name = 'full'
                                    AND i.years <> 0
                                    AND l.expiration_date < GETDATE() THEN
                                    CONVERT(DATE, GETDATE())
                                WHEN l.license_id IS NOT NULL
                                    AND i.start_date IS NULL
                                    AND l.category_type_name = 'full'
                                    AND i.years <> 0
                                    AND l.expiration_date >= GETDATE() THEN
                                    l.expiration_date
                                ELSE
                                    i.start_date
                            END,
                expiration_date = CASE
                                  WHEN l.license_id IS NULL
                                       AND i.expiration_date IS NULL THEN DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                                  WHEN l.license_id IS NOT NULL
                                       AND i.expiration_date IS NULL
                                       AND l.category_type_name = 'trial' THEN DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                                  WHEN l.license_id IS NOT NULL
                                       AND i.expiration_date IS NULL
                                       AND l.category_type_name = 'full'
                                       AND i.start_date IS NULL
                                       AND l.expiration_date < GETDATE() THEN DATEADD(mm, i.years * 12, CONVERT(DATE, GETDATE()))
                                  WHEN l.license_id IS NOT NULL
                                       AND i.expiration_date IS NULL
                                       AND l.category_type_name = 'full'
                                       AND i.start_date IS NULL
                                       AND l.expiration_date >= GETDATE() THEN DATEADD(mm, i.years * 12, l.expiration_date)
                                  WHEN l.license_id IS NOT NULL
                                       AND i.expiration_date IS NULL
                                       AND l.category_type_name = 'full'
                                       AND i.start_date IS NOT NULL THEN DATEADD(mm, i.years * 12, i.start_date)
                                  ELSE i.expiration_date
                              END
        FROM @item_table i
            LEFT JOIN @license_table l
                
ON l.item_hierarchy_id = i.item_hierarchy_id
        WHERE i.item_hierarchy_id = 1;

    END;

	IF @debug_mode = 1 BEGIN
                SELECT '3.1.8' AS debug_message,
                    *
                FROM @item_table;
            END;

    --3.1.9) Update Zuora price if Campaign_id exists
    IF EXISTS (
                SELECT 1
                FROM dbo.zuora_product_pricing
                WHERE campaign_id = @message_key )
                    AND @message_key NOT LIKE '%[A-Z]%'
                    AND @locale = 'en_US' BEGIN

            SET @campaign_id = @message_key;

            UPDATE i
                SET i.list_price = ISNULL(zp.renewal_price, i.list_price),
                    i.unit_price = ISNULL(zp.retail_price,i.unit_price),
                    license_seats = 1,
                    total_license_seats = 1
            FROM @item_table i
                INNER JOIN dbo.zuora_product_pricing zp
                    ON zp.product_type_id = i.product_type_id
                INNER JOIN dbo.license_category lc
                    ON lc.license_category_id = zp.license_category_id
                        AND lc.license_category_name = i.license_category_name
            WHERE zp.campaign_id = @campaign_id
                AND i.item_hierarchy_id = 1
                AND zp.product_id = i.product_id;

        END;

    IF @debug_mode = 1 BEGIN
                SELECT '3.1.9' AS debug_message,
                    *
                FROM @item_table;
            END;


    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 4.) pricing business
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    DECLARE @discount FLOAT,
        @cart_discount_method_id TINYINT;

    IF @product_line_id IN ( 55, 300 ) BEGIN

            -- 4.1) direct
            IF @partner_id IS NULL BEGIN

                    -- 4.1.1) update @item_table
                    UPDATE @item_table
                        SET list_price = pp.retail_price,
                            unit_price = CASE
                                            WHEN i.product_type_id IN ( 1, 2 ) THEN
                                                ROUND(
                                                        (CONVERT(
                                                                    FLOAT,
                                                                    DATEDIFF(dd, i.start_date, i.expiration_date)
                                                                    - dbo.fn_leap_days_between(i.start_date, i.expiration_date)
                                                                ) / c.capability_activation_days
                                                        ) * pp.retail_price,
                                                        2
                                                    )
                                            WHEN i.product_type_id IN ( 3 ) THEN
                                                ROUND(
                                                        (CONVERT(FLOAT, DATEDIFF(dd, i.start_date, i.expiration_date))
                                                        / y.upgrade_days
                                                        ) * pp.retail_price,
                                                        2
                                                    )
                                        END
                    FROM @item_table i
                        INNER JOIN dbo.product_line_product plp
                            ON plp.product_id = i.product_id
                        INNER JOIN dbo.product_pricing pp
                            ON pp.product_id = i.product_id
                     
   INNER JOIN dbo.product_years y
                            ON y.product_id = pp.product_id
                        INNER JOIN dbo.product_capability c
                            ON c.product_id = y.product_id
                    WHERE pp.language_code = @language_code
                        AND pp.location_code = @location_code
                        AND plp.product_line_id IN ( 55, 100, 300 );

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.1' AS debug_message,
                                *
                            FROM @item_table;
                        END;

                    -- 4.1.2) Tier discount models - expanded to support SFDC discount models via usp_license_select_category_discount_model
                    DECLARE @item_discount_profile TABLE (
                        item_id INT,
                        license_id INT,
                        license_category_name VARCHAR(10),
                        product_type_id INT,
                        discount FLOAT,
                        cart_discount_method_id INT,
                        cart_discount_id INT
                    );

                    DECLARE @item_discount_json VARCHAR(MAX);
                    SET @item_discount_json = (
                        SELECT item_id,
                            @license_id AS license_id,
                            license_category_name,
                            total_license_seats AS license_seats,
                            product_type_id,
                            years,
                            @license_attribute_license_value AS license_attribute_license_value,
                            retention_model_id,
                            storage_gb
                        FROM @item_table
                        FOR JSON PATH
                    );

                    DECLARE @item_discount_profile_json NVARCHAR(MAX);
                    EXECUTE dbo.usp_license_select_category_discount_model @item_json = @item_discount_json,
                                                                    @source_caller = 'usp_cart_select_license_configurator_pricing',
                                                                    @item_discount_profile_json = @item_discount_profile_json OUTPUT;

                    INSERT INTO @item_discount_profile (
                        item_id,
                        license_id,
                        license_category_name,
                        product_type_id,
                        discount,
                        cart_discount_method_id,
                        cart_discount_id
                    )
                    SELECT item_id,
                        license_id,
                        license_category_name,
                        product_type_id,
                        discount,
                        cart_discount_method_id,
                        cart_discount_id
                    FROM OPENJSON(@item_discount_profile_json)
                    WITH (
                        item_id INT '$.item_id',
                        license_id INT '$.license_id',
                        license_category_name VARCHAR(10) '$.license_category_name',
                        product_type_id INT '$.product_type_id',
                        discount FLOAT '$.discount',
                        cart_discount_method_id INT '$.cart_discount_method_id',
                        cart_discount_id INT '$.cart_discount_id'
                    );

                    UPDATE s
                        SET s.unit_price = ROUND((1.00 - idp.discount / 100) * s.unit_price, 2),
                            s.cart_discount_id = idp.cart_discount_id,
                            s.discount = idp.discount
                    FROM @item_table s
                        INNER JOIN @item_discount_profile idp
                            ON idp.item_id = s.item_id
 
                               AND idp.license_category_name = s.license_category_name
                                AND idp.product_type_id = s.product_type_id;

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.2' AS debug_message,
                                *
                            FROM @item_table;
                        END;

                    -- 4.1.3) license_Cart_discount
                    SELECT @discount = d.discount,
                        @cart_discount_method_id = d.cart_discount_method_id
                    FROM (
                            SELECT TOP 1
                                di.discount,
                                di.cart_discount_method_id
                            FROM dbo.license_cart_discount ld
                                INNER JOIN dbo.cart_discount_item di
                                    ON di.cart_discount_id = ld.cart_discount_id
                            WHERE ld.license_id = @license_id
                                AND ld.start_date <= @insert_date
                                AND @insert_date < ld.end_date
                            ORDER BY ld.license_cart_discount_id DESC
                        ) d;

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.3' AS debug_message,
                                @discount AS discount,
                                @cart_discount_method_id AS cart_discount_method_id;
                        END;

                    -- 4.1.4) update @item_table discount
                    IF @discount IS NOT NULL BEGIN
                            UPDATE @item_table
                                SET discount = @discount,
                                    cart_discount_method_id = @cart_discount_method_id;
                        --where discount is null --commenting out to allow license_cart_discount to update @item_table, since 4.1.2 is setting a discount value
                        END;

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.4' AS debug_message,
                                *
                            FROM @item_table;
                        END;

                    -- 4.1.5) @message_campaign_cart_discount
                    INSERT INTO @message_campaign_cart_discount (
                        message_campaign_id,
                        message_campaign_name,
                        message_campaign_class_id,
                        message_campaign_class_name,
                        message_campaign_start_date,
                        message_campaign_end_date,
                        license_distribution_method_id,
                        inclusive,
                        license_seats,
                        license_category_id,
                        license_category_name,
                        autorenewal_opt_id,
                        language_code,
                        location_code,
                        cart_discount_id
                    )
                    SELECT DISTINCT
                        m.message_campaign_id,
                        m.message_campaign_name,
                        cc.message_campaign_class_id,
                        cc.message_campaign_class_name,
                        m.message_campaign_start_date,
                        m.message_campaign_end_date,
                        d.license_distribution_method_id,
                        d.inclusive,
                        s.license_seats,
                        c.license_category_id,
                        lc.license_category_name,
                        ar.autorenewal_opt_id,
                        ll.language_code,
                        ll.location_code,
                        cd.cart_discount_id
                    FROM dbo.message_campaign m
                        INNER JOIN dbo.message_campaign_cla
ss cc
                            ON cc.message_campaign_class_id = m.message_campaign_class_id
                        INNER JOIN dbo.message_campaign_cart_discount cd
                            ON m.message_campaign_id = cd.message_campaign_id
                        INNER JOIN dbo.message_campaign_platform pf
                            ON m.message_campaign_id = pf.message_campaign_id
                        LEFT JOIN dbo.message_campaign_seat s
                            ON m.message_campaign_id = s.message_campaign_id
                        LEFT JOIN dbo.message_campaign_license_category c
                            ON m.message_campaign_id = c.message_campaign_id
                        LEFT JOIN dbo.license_category lc
                            ON lc.license_category_id = c.license_category_id
                        LEFT JOIN dbo.message_campaign_product_line pl
                            ON m.message_campaign_id = pl.message_campaign_id
                        LEFT JOIN dbo.message_campaign_autorenewal ar
                            ON m.message_campaign_id = ar.message_campaign_id
                        LEFT JOIN dbo.message_campaign_license_distribution_method d
                            ON m.message_campaign_id = d.message_campaign_id
                        LEFT JOIN dbo.message_campaign_language_location ll
                            ON m.message_campaign_id = ll.message_campaign_id
                    WHERE m.message_campaign_enabled = 1
                        AND pf.message_platform_id = 8
                        AND m.message_campaign_start_date <= @insert_date
                        AND @insert_date < m.message_campaign_end_date;

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.5' AS debug_message,
                                *
                            FROM @message_campaign_cart_discount;
                        END;

                    -- 4.1.5.1) update @item_table_discount
                    UPDATE i
                        SET discount = di.discount,
                            cart_discount_method_id = di.cart_discount_method_id
                    FROM @message_campaign_cart_discount c
                        INNER JOIN dbo.cart_discount_item di
                            ON c.cart_discount_id = di.cart_discount_id
                                AND di.license_category_id = c.license_category_id
                        INNER JOIN @item_table i
                            ON c.license_seats = i.license_seats
                                AND c.license_category_name = i.license_category_name
                                AND di.product_type_id = i.product_type_id
                    WHERE di.cart_discount_method_id = 3
                        AND c.autorenewal_opt_id = ( CASE
                                                        WHEN @license_attribute_license_value = 1 THEN 1
                                                        ELSE 0
                                                    END )
                        AND ( c.license_distribution_method_id IS NULL
                                OR c.license_distribution_method_id = @license_distribution_method_id )
                        AND ( c.location_code IS NULL
                            OR (
                                c.language_code = @language_code
                                    AND c.location_code = @location_code )
                        ); 

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.5.1' AS debug_message,
                                *
                            FROM @message_campaign_cart_discount;
                        END;

                    -- 4.1.6) update pricing
                    UPDATE @item_table
                        SET unit_price = CASE
                                            --when @cart_discount_method_id = 1 then
          
                                  WHEN cart_discount_method_id = 3 THEN unit_price - ROUND((discount / 100) * unit_price, 2)
                                            ELSE unit_price
                                        END
                        WHERE discount IS NOT NULL;

                    IF @debug_mode = 1 BEGIN
                            SELECT '4.1.6' AS debug_message,
                                *
                            FROM @item_table;
                        END;
                            
                    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    -- x.) Business-only pricing
                    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

                    -- 4.1.7) monthly utility
                    IF @license_attribute_license_value IN ( 11, 12, 13 ) BEGIN

                            -- 4.1.7.1) remove upsell in the case of utility
                            DELETE 
                            FROM @item_table
                            WHERE product_type_id NOT IN ( 1, 2 )
                                AND @license_attribute_license_value = 12;

                            IF @debug_mode = 1 BEGIN
                                    SELECT '4.1.7.1' AS debug_message,
                                        *
                                    FROM @item_table;
                                END;

                            -- 4.1.7.2) update pricing
                            UPDATE i
                                SET unit_price = CASE
                                                    WHEN @license_attribute_license_value = 12 THEN 0
                                                    ELSE i.unit_price
                                                END,
                                    list_price = CASE
                                                    WHEN @license_attribute_license_value = 12 THEN 0
                                                    ELSE i.list_price
                                                END
                            FROM @item_table i;

                            IF @debug_mode = 1 BEGIN
                                    SELECT '4.1.7.2' AS debug_message,
                                        *
                                    FROM @item_table;
                                END;

                            -- 4.1.7.3) update usage_price
                            UPDATE i
                                SET usage_price = pp.usage_price
                            FROM @item_table i
                                INNER JOIN dbo.product_pricing pp
                                    ON i.product_id = pp.product_id
                            WHERE pp.location_code = @location_code
                                AND pp.language_code = @language_code;

                            IF @debug_mode = 1 BEGIN
                                    SELECT '4.1.7.3' AS debug_message,
                                        *
                                    FROM @item_table;
                                END;

                            -- 4.1.7.4) apply tier discount model to usage_price when the SFDC Utility discount is selected
                            UPDATE it
                                SET it.usage_price = ROUND((1.00 - idp.discount / 100) * it.usage_price, 2)
                            FROM @item_table it
                                INNER JOIN @item_discount_profile idp
                                    ON idp.item_id = it.item_id
                                        AND idp.license_category_name = it.license_category_name
                                        AND idp.product_
type_id = it.product_type_id
                                LEFT JOIN @CARBONITE_LICENSE_CATEGORIES clc
                                    ON clc.license_category_name = it.license_category_name
                            WHERE clc.license_category_name IS NULL;    --do not apply discount to carbonite orders

                            IF @debug_mode = 1 BEGIN
                                    SELECT '4.1.7.4' AS debug_message,
                                        *
                                    FROM @item_table;
                                END;

                        END;
                END;
        ELSE BEGIN

                -- 4.2) partner

                -- 4.2.1) annual
                IF ( @license_attribute_id IS NULL
                    OR @license_attribute_license_value IN ( 120, 220 ) ) BEGIN
                        UPDATE @item_table
                        SET list_price = t.retail_price,
                            unit_price = CASE
                                            WHEN t.pricing_term = 'monthly' THEN t.retail_price
                                            WHEN t.pricing_term = 'annual' THEN ROUND( t.retail_price
                                                                                        * ( CONVERT(FLOAT, DATEDIFF(dd, i.start_date, i.expiration_date))
                                                                                            / 365.0 ),
                                                                                        2
                                                                                    )
                                        END
                        FROM @item_table i
                            INNER JOIN dbo.license_category lc
                                ON lc.license_category_name = i.license_category_name
                            INNER JOIN dbo.partner_pricing_tier t
                                ON t.license_category_id = lc.license_category_id
                        WHERE t.pricing_status = 'active'
                            AND t.currency_id = @currency_id
                            AND t.partner_id = @partner_id
                            AND t.site_id = @site_id
                            AND t.low_range <= i.total_license_seats
                            AND i.total_license_seats < t.high_range
                            AND t.license_attribute_id IS NULL;

                        IF @debug_mode = 1 BEGIN
                                SELECT '4.2.1' AS debug_message,
                                    *
                                FROM @item_table;
                            END
                    END;

                -- 4.2.2) monthly
                ELSE BEGIN
                        UPDATE i
                            SET list_price = t.retail_price,
                                unit_price = CASE
                                                WHEN t.pricing_term = 'monthly' THEN t.retail_price
                                                WHEN t.pricing_term = 'annual' THEN ROUND( t.retail_price
                                                                                                * ( CONVERT(FLOAT, DATEDIFF(dd, i.start_date, i.expiration_date))
                                                                                                    / 365.0 ),
                                                                                                2 )
                                            END
                        FROM @item_table i
                            INNER JOIN dbo.license_category lc
                                ON lc.license_category_name = i.license_category_name
                            INNER JOIN dbo.partner_pricing_tier t
                                ON t.license_category_id = lc.license_category_id
                        WHERE t.pricing_status = 'active'
         
                   AND t.currency_id = @currency_id
                            AND t.partner_id = @partner_id
                            AND t.site_id = @site_id
                            AND t.low_range <= i.total_license_seats
                            AND i.total_license_seats < t.high_range
                            AND t.license_attribute_id = @license_attribute_id;
                    END;

                IF @debug_mode = 1 BEGIN
                        SELECT '4.2.2' AS debug_message,
                            *
                        FROM @item_table;
                    END;

            END;
    END;

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --RETURN
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT 
        line_item = i.item_id,
        quantity = i.license_seats,
        i.order_item_offer_amount,
        equivalent_year_price = ( CASE
                                        WHEN @campaign_id IS NOT NULL THEN CONVERT(MONEY, zp.renewal_price * i.years)
                                        ELSE ( CASE
                                                    WHEN pp.retail_price IS NULL
                                                            OR i.years IS NULL THEN
                                                        NULL
                                                    ELSE
                                                        CONVERT(MONEY, pp.retail_price * i.years)
                                                END )
                                    END ),
        i.list_price,
        i.unit_price,
        i.usage_price,
        i.product_id,
        p.product_description,
        i.product_type_id,
        t.product_type_description,
        i.license_keycode_type_id,
        lc.license_category_id,
        i.license_category_name,
        lc.license_category_description,
        f.product_family_description,
        i.start_date,
        i.expiration_date,
        i.cart_item_bundle_id,
        i.item_hierarchy_id,
        dependent_cart_order_item_id = NULL,
        keycode = @keycode,
        i.discount,
        i.cart_discount_method_id,
        i.cart_discount_id,
        i.storage_gb,
        i.usage_pricing_model_id,
        i.retention_model_id,		   
        retention_term = JSON_VALUE(pe.product_extension_json,'$.retention_term'),
        retention_model_name = JSON_VALUE(pe.product_extension_json,'$.retention_model_name'),
        actual_storage_quantity = ( CASE WHEN i.usage_pricing_model_id = 2 
                                            AND i.storage_gb >= 1024 THEN CONVERT(DECIMAL(12,5),CONVERT(DECIMAL(12,5),i.storage_gb)/1024)
                                        WHEN i.usage_pricing_model_id = 2 
                                            AND i.storage_gb < 1024 THEN 1.00000
                                        ELSE 0 
                                    END )
    FROM @item_table i
        INNER JOIN dbo.product p
            ON p.product_id = i.product_id
        INNER JOIN dbo.product_family f
            ON f.product_family_id = p.product_family_id
        INNER JOIN dbo.product_type t
            ON t.product_type_id = i.product_type_id
        INNER JOIN dbo.license_category lc
            ON lc.license_category_name = i.license_category_name
        LEFT JOIN dbo.product_extension pe
            ON pe.product_id = p.product_id
        LEFT JOIN dbo.zuora_product_pricing zp
            ON zp.product_id = p.product_id
               AND zp.campaign_id = @campaign_id
        OUTER APPLY dbo.fn_cart_select_one_year_products(i.product_id) oyp
        LEFT JOIN dbo.product_pricing pp
            ON pp.product_id = oyp.produ
ct_id
               AND pp.language_code = @language_code
               AND pp.location_code = @location_code;

END TRY

BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN 'execute dbo.usp_cart_select_license_configurator_pricing failed'
                       ELSE @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXECUTE dbo.usp_LogError @ErrorDB = @DBName;

END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_contract_profile]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_select_license_contract_profile]


(
		@license_id int, 
		@effective_date datetime = null,
		@license_category_name varchar(10) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2018-03-21	esmart		Initial creation.
	2018-11-01	cnovac		took out references to effective columns in attribute

	DESCRIPTION
	select contract details for a given license
*/

AS

set nocount on				

begin try

	declare @response_code int,
			@message varchar(100)

	declare @contract_profile table (license_id int, order_item_id int, order_header_id int, site_id varchar(65), salesforce_opportunity_id varchar(18), license_category_id int, license_category_name varchar(10), license_category_description varchar(50), oracle_contract_id int, oracle_contract_number varchar(20), oracle_line_id varchar(40), start_date datetime, end_date datetime, license_attribute_id int, license_attribute_license_value int)
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @effective_date
	if @effective_date is null
		begin 
		select @effective_date = getdate()
		end

	-- 1.2) result
	insert into @contract_profile (license_id, order_item_id, order_header_id, site_id, salesforce_opportunity_id, license_category_id, license_category_name, license_category_description, oracle_contract_id, oracle_contract_number, oracle_line_id, start_date, end_date, license_attribute_id, license_attribute_license_value)
	select cll.license_id, i.order_item_id, i.order_header_id, h.site_id, oo.salesforce_opportunity_id, plc.license_category_id, lc.license_category_name, lc.license_category_description, cl.oracle_contract_id, c.oracle_contract_number, cl.oracle_line_id, cl.start_date, cl.end_date,
		license_attribute_id = lalv.license_attribute_id,
		license_attribute_license_value = dbo.fn_license_select_effective_object_element(cll.license_id, lc.license_category_id, 'license_attribute_license_value', @effective_date)
	from oracle_contract_line_license cll
	inner join oracle_contract_line cl
		on cl.oracle_contract_line_id = cll.oracle_contract_line_id
	inner join oracle_contract c
		on c.oracle_contract_id = cl.oracle_contract_id
	inner join order_item i
		on i.order_item_id = cl.order_item_id
	inner join order_header h
		on h.order_header_id = i.order_header_id
	left join order_opportunity oo
		on oo.order_header_id = i.order_header_id
	inner join product_license_category plc
		on plc.product_id = i.product_id
	inner join license_category lc
		on lc.license_category_id = plc.license_category_id
	left join license_attribute_license_value lalv
		on lalv.license_attribute_license_value = dbo.fn_license_select_effective_object_element(cll.license_id, lc.license_category_id, 'license_attribute_license_value', @effective_date)
	where cll.license_id = @license_id and cl.start_date < @effective_date and @effective_date < cl.end_date and lc.license_category_name = case when @license_category_name is not null then @license_category_name else lc.license_category_name end

	select c.license_id, c.order_item_id, c.order_header_id, c.site_id, c.salesforce_opportunity_id, c.license_category_id, c.license_category_name, c.license_category_description, 
		c.oracle_contract_id, c.oracle_contract_number, c.oracle_line_id, c.start_date, c.end_date, 
		c.license_attribute_id, a.license_attribute_description, c.license_attribute_license_value, v.license_attribute_license_value_description,
		ac.billing_day_
of_month, mc.autorenewal_cycle_name,
		cu.currency_code,
		payment_method_name = (select top(1) m.payment_method_name
								from order_payment_header oph
								left join payment_header h
									on h.payment_header_id = oph.payment_header_id
								left join payment_method m
									on m.payment_method_id = h.payment_method_id
								where oph.order_header_id = c.order_header_id
								order by oph.order_payment_header_id desc)
	from @contract_profile c
	left join order_currency oc
		on oc.order_header_id = c.order_header_id
	left join currency cu
		on cu.currency_id = oc.currency_id
	left join license_attribute a
		on a.license_attribute_id = c.license_attribute_id
	left join license_attribute_license_value v
		on v.license_attribute_license_value = c.license_attribute_license_value
	left join license_autorenewal_cycle ac
		on ac.license_id = c.license_id 
	left join message_autorenewal_cycle mc
		on mc.message_autorenewal_cycle_id = ac.message_autorenewal_cycle_id


	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'report failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_ext_types]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_license_ext_types]

(
		@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-07-08	esmart		Initial creation
	2010-12-03	esmart		Use function when license_category_id is not set
	2011-08-05	esmart		Add mapping to new license categories
	2012-07-25	essmart		WSA 2013 
	2016-07-25	cnovac		Change made by Eric to support legacy product license_category_name selection

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@license_id int,
			@license_category_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id 
		select @license_id = license_id from license where keycode = @keycode

	-- 1.2) check to see if the license_category has been assigned
		select @license_category_id = license_category_id
		from license_category_license
		where license_id = @license_id

		if @license_category_id is null
			begin
			select @license_category_id = dbo.fn_GetLicenseCategoryId(@license_id)

			if @license_category_id is not null
				begin
				insert into license_category_license(license_id, license_category_id, start_date, end_date)	
				select license_id, @license_category_id, capability_activation_date, capability_expiration_date
				from license_capability
				where license_id = @license_id and capability_id = 1
				end
	
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		declare @ext_type table (cart_item_in_process_ext_type_id tinyint, ext_type_name varchar(20), ext_type_value varchar(20))

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 1, ext_type_name = 'category', 
				license_category_name = case
											when license_category_name in ('WAV','SS') then 'WSAV'
											--when license_category_name = 'WAV' then 'WSAV'
											--when license_category_name = 'WISE' then 'WSAE'
											when license_category_name in ('WISE','WISC','WSAE') then 'WSAC'
											else license_category_name
										end
		from license_category_license c
		inner join license_category l
			on c.license_category_id = l.license_category_id
		where license_id = @license_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 2, ext_type_name = 'seats', convert(varchar(20),license_seats)
		from license_seat
		where license_id = @license_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 3, ext_type_name = 'storage', convert(varchar(20),case when storage_gb < 25 then 25 else storage_gb end)
		from license_storage
		where license_id = @license_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 16, ext_type_name = 'product_line_id', convert(varchar(20),product_line_id) 
		from license
		where license_id = @license_id

		select cart_item_in_p
rocess_ext_type_id, ext_type_name, ext_type_value
		from @ext_type t
--		FOR XML AUTO

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_profile]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_license_profile]

(
	@license_id INT = NULL,
	@keycode VARCHAR(40) = NULL
)

/*
	DATE			AUTHOR		REMARKS
	2017-08-14		esmart		Initial creation.
	2019-06-05		wbarton		Extending the data selected from fn_license_select_license_profile
	2019-08-09		esmart		Add usage_pricing_model
	2020-02-21		esmart		Add vault_id
	2020-05-04		esmart		Add retention_model
	2020-07-21		cnovac		Added license_autorenewal_value and license_category_id
	2020-07-29		esmart		Add product_platform
	2020-09-02		esmart		Add pricing_level
	2020-10-07		abelenkiy	Removed joins to license_category and item_hierarchy to retrieve description from function instead
	2020-10-13		cnovac		Added pricing_level_description
	2020-10-23		wbarton		Removing vault from the profile
	2020-12-11		cnovac		Adding vault info json to profile
	2022-01-07		gblandford	SMCI-6214 - Add retention_term & retention_model_type_id
	2025-07-24		jberry		US-4901500 - Added most_recent_order_term to provide the product term from the most recent new or renewal order
	2026-03-11		jberry		US-5095009 - Added renewal_baseline_amount to provide total order amount (pre-tax) for the previous new or renewal order

	DESCRIPTION
	select license_profile
*/

AS

	SET NOCOUNT ON				

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	IF @license_id IS NULL
		BEGIN
		SELECT @license_id = license_id
		FROM dbo.license
		WHERE keycode = @keycode
		END

	-- 1.2) check for alias
	IF @license_id IS NULL
		BEGIN
		SELECT @license_id = license_id
		FROM dbo.license_keycode_alias
		WHERE keycode_alias = @keycode
		END

	SELECT f.item_id, license_id, f.license_category_name, f.license_category_description, f.license_seats, f.storage_gb, f.license_keycode_type_id, 
			f.start_date, f.expiration_date, f.license_attribute_id, f.license_attribute_description, f.license_attribute_license_value, f.license_attribute_license_value_description, 
			f.category_type_name, f.item_hierarchy_id, f.item_hierarchy_name, f.license_status_id, f.license_status_description, f.autorenewal_cycle_name, f.autorenewal_cycle, 
			f.usage_pricing_model_id, f.usage_pricing_model_name,
			f.retention_model_id, f.retention_model_name, f.retention_term, f.retention_model_type_id,
			f.product_platform_id, f.product_platform_name, 
			f.license_autorenewal_value, f.license_category_id, f.product_pricing_level_id, f.pricing_level, f.pricing_level_description, f.license_vault_json, f.most_recent_order_term,
			f.renewal_baseline_amount
			FROM dbo.fn_license_select_license_profile(@license_id) f

	END TRY

	BEGIN CATCH

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName

	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_license_route]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_license_route]
(
    @keycode VARCHAR(40),
    @language_code VARCHAR(2),
    @location_code VARCHAR(3),
    @message_key VARCHAR(36) = NULL,
    @message_action VARCHAR(50) = NULL,
    @message_campaign_id INT = NULL,
    @message_campaign_platform VARCHAR(50) = NULL
)

/*    
    DATE        AUTHOR      REMARKS
    2013-04-30  esmart      Initial creation
    2013-07-24  esmart      Add @message_key
    2014-03-17  esmart      Add message_url
    2014-03-04  acoffel     extended seat enforcement in routing
    2014-10-31  acoffel     extend WSAC downgrade into routing
    2014-12-31  acoffel     added backup license_summary option
    2015-01-30  acoffel     added renewal dimension
    2015-03-12  acoffel     added channel dimension
    2017-05-23  esmart      add partner license routing
    2018-04-10  acoffel     adjustments to partner license routing
    2018-05-16  jnavarra    Blank out message on partner trial for proper php handling
                            Slight change to partner trial routing
    2018-05-25  mrobbins    extended message_campaign_name
    2018-08-02  acoffel     GSM
    2018-10-19  esmart      log cart_route
    2019-01-04  acoffel     channel 2 handling
    2019-01-14  jnavarra    Update channel 2 handling for locale/language
    2019-01-22  jnavarra    Add order status dimension
    2019-04-11  jnavarra    Rank message_action routes
    2019-12-12  jnavarra    Don't try route to partner if no routing_url is available
    2023-04-24	schindar	Add additional logic to get capability_expiration_date and capability_activation_date if license_summary has null value
                            section modified -- 1.4) get license details
    2024-05-03  psatish     ECOM-3364 Return the routing url for Non-Zuora licenses from partner configuration for Carbonite Partner. 
                            Return the Portal cart URL for Domestic licenses with USA locale and Zuora licenses if routing campaigns are set to
                            redirect to the Portal Cart URL. 
    2024-07-24  psatish     ECOM-5200 Added section 3.2 To prevent upgrade offers for the Non-Zuora consumer keycodes and switch to the portal cart url when the
                            expiration date is more than 30 days from the current date
    2025-05-20  jberry      US-4767893 - Changed section 1.4 to force carbonite products to single-site/non-gsm license routing (GSM Configurator)

   DESCRIPTION
   This procedure is being called by PHP/usp_cart_insert_cart_order_item_in_process during the manual renewal process

*/

AS
    SET NOCOUNT ON                

    DECLARE @license_id INT,
            @product_line_id INT,
            @license_distribution_method_id INT,
            @license_seats INT,
            @license_category_id INT,
            @license_type_id INT,
            @capability_type_id TINYINT,
            @license_status_id INT,
            @contract_detail_update INT,
            @base_capability_id INT,
            @license_keycode_type_id INT,
            @license_keycode_type_message_action INT,
            @account_creation_status TINYINT,
            @license_channel_id TINYINT,
            @renewal_status TINYINT,
            @app_store_status TINYINT,
            @opt_in INT,
            @capability_activation_date DATETIME,
            @capability_expiration_date DATETIME,
            @subscription_start_date DATETIME,
            @subscription_expiration_date DATETIME,
            @trial TINYINT,
            @months INT,
            @hard_cancel INT,
            @message_url VARCHAR(500),
            @bestbuy_adjustment INT,
            @autorenewal_opt_id INT,
          
  @rowcnt INT,
            @route_message_campaign_id INT, 
            @routing_url VARCHAR(500),
            @message_campaign_name VARCHAR(65),
            @partner_id INT,
            @response_code INT,
            @message VARCHAR(100),
			@ZUORA_LICENSE BIT=0,
			@next_bill_date DATETIME,
			@PORTAL_CART_URL VARCHAR(500),
			@BUSINESS_LICENSE BIT=0,
			@LICENSE_REMAINING_DAYS INT,
			@PORTAL_LOCATION_CODE VARCHAR(3)


    BEGIN TRY
		DECLARE @APP_CONFIG TABLE
		(
		    [app_config_name] NVARCHAR(50),
		    [key] NVARCHAR(50),
		    [value] NVARCHAR(MAX)
		);
		DECLARE @portal_cart_routing_campaigns TABLE
		(
		   message_campaign_id INT,
		   message_campaign_name VARCHAR(65)
		)
		DECLARE @interstitial_routing_campaigns  TABLE
		(
		   message_campaign_id INT,
		   message_campaign_name VARCHAR(65)
		)

		INSERT INTO @APP_CONFIG
		(
		    app_config_name,
		    [key],
		    [value]
		)
		SELECT f.app_config_name,
		       f.[key],
		       f.[value]
		FROM [dbo].[fn_app_config_select_key_values](NULL, 'PORTAL') f
		
		INSERT INTO @interstitial_routing_campaigns 
		(
		    message_campaign_id,
		    message_campaign_name
		)
		SELECT mc.message_campaign_id,mc.message_campaign_name
		FROM @APP_CONFIG ac
		INNER JOIN dbo.message_campaign mc
		ON mc.message_campaign_name=ac.[key]
		WHERE app_config_name='PORTAL_INTERSTITIAL_CAMPAIGNS'

		INSERT INTO @portal_cart_routing_campaigns
		(
		    message_campaign_id,
		    message_campaign_name
		)
		SELECT mc.message_campaign_id,mc.message_campaign_name
		FROM @APP_CONFIG ac
		INNER JOIN dbo.message_campaign mc
		ON mc.message_campaign_name=ac.[key]
		WHERE app_config_name='PORTAL_CART_ROUTER_CAMPAIGNS'

		SELECT @PORTAL_CART_URL=[value]
		FROM @APP_CONFIG
		WHERE app_config_name='PORTAL_CART_URL'

		SELECT @LICENSE_REMAINING_DAYS=[key]
		FROM @APP_CONFIG
		WHERE app_config_name='PORTAL_LICENSE_REMAINING_DAYS'

		
		SELECT @PORTAL_LOCATION_CODE=[key]
		FROM @APP_CONFIG
		WHERE app_config_name='PORTAL_LOCATION_CODE'

		--app-config
		DECLARE @INDIRECT_PARTNER_LICENSE_CATEGORIES TABLE
		(
			license_category_id INT,
			license_category_name VARCHAR(10)
		)
		INSERT INTO @INDIRECT_PARTNER_LICENSE_CATEGORIES
		(
			   license_category_id,
			   license_category_name
		)
		SELECT f.[key],
			   f.value
		FROM [dbo].[fn_app_config_select_key_values]('INDIRECT_PARTNER_LICENSE_CATEGORIES', 'LICENSE_CHANNEL_LOGIC') f

		
        --------------------------------------------------------------------------------------------------------------------------------
        -- 1) select license data
        --------------------------------------------------------------------------------------------------------------------------------
    
        -- 1.1) @license_id
        select @license_id = license_id
        from license 
        where keycode = @keycode

        -- 1.1.1) check alias
        if @license_id is null
            begin
                SELECT @license_id = license_id from license_keycode_alias where keycode_alias = @keycode
            end
            
        -- 1.1.2) check @message_key
        if @license_id is null and @message_key is not null and @message_key <> ''
            begin
                -- license_key
                select @license_id = license_id from license_key where license_key = @message_key

                -- license_message_key
                IF @license_id IS NULL
                    BEGIN
                        SELECT @license_id = license_id FROM license_message WHERE license_message_key = @message_key
                    END
            END

        -- 1.1.3) invalid license
        if @license_id is null
            begin
                RETURN
            end
        --1.1.4 Find Zuora license
		--Begins
		SELECT @ZUORA_LICENSE = 1
		FROM license lc
			INNER JOIN dbo.license_distribution_method dm
				ON dm.license_d
istribution_method_id = lc.license_distribution_method_id
			INNER JOIN @APP_CONFIG f
				ON f.[key] = dm.license_distribution_method_code
		WHERE lc.license_id = @license_id
		AND f.app_config_name='PORTAL_DISTI_CODES'
		
		--1.1.5 Find Business license

		SELECT @BUSINESS_LICENSE=1
		FROM dbo.fn_app_config_select_key_values('BUSINESS_PRODUCT_LINE','GENERAL') f
		INNER JOIN license lc
		ON f.[key]=lc.product_line_id
		WHERE license_id=@license_id


		--Ends
		 
        -- 1.2) explicit @message_action
        if @message_action is not NULL
            begin
                SELECT
                    @license_keycode_type_message_action = CASE WHEN license_keycode_type_id = 3 THEN 1 ELSE 0 END,
                    @product_line_id = product_line_id
                FROM license
                WHERE license_id = @license_id
                
                -- 1.2.1) insert cart_route
                insert into cart_route (routing_action, message_key, license_id, message_campaign_id, message_campagn_platform)
                values(@message_action, @message_key, @license_id, @message_campaign_id, @message_campaign_platform)

                -- 1.2.2) return
                ;WITH
                    ranked_message_content AS (
                        SELECT
                            0 AS message_campaign_id,
                            @message_action AS message_campaign_name,
                            @message_action AS message_action,
                            @language_code AS language_code,
                            @location_code AS location_code,
                            (select iso from lu_countries where iso3 = @location_code) AS location_code_iso,
                            c.message_url,
                            CASE
                                WHEN c.language_code = @language_code AND c.location_code = @location_code THEN 3
                                WHEN c.language_code = @language_code AND c.location_code IS NULL THEN 2
                                WHEN c.language_code IS NULL AND c.location_code = @location_code THEN 2
                                WHEN c.language_code IS NULL AND c.location_code IS NULL THEN 1
                                ELSE 0
                            END AS locale_ranking,
                            CASE
                                WHEN mcpl.message_campaign_product_line_id IS NOT NULL THEN 1
                                ELSE 0
                            END AS campaign_ranking
                        FROM dbo.message_content c
                            INNER JOIN dbo.license_keycode_type_message_action a
                                ON c.message_content_id = a.message_content_id
                            LEFT JOIN dbo.message_campaign_content mcc
                                ON mcc.message_content_id = c.message_content_id
                            LEFT JOIN dbo.message_campaign mc
                                ON mc.message_campaign_id = mcc.message_campaign_id AND mc.message_campaign_enabled = 1 AND mc.message_campaign_class_id = 6
                            LEFT JOIN dbo.message_campaign_product_line mcpl
                                ON mcpl.message_campaign_id = mc.message_campaign_id AND mcpl.product_line_id = @product_line_id
                        WHERE message_action = @message_action
                            AND a.license_keycode_type_id = @license_keycode_type_message_action
                    )
                    SELECT TOP(1) message_campaign_id, message_campaign_name, message_action, language_code, location_code, location_code_iso, message_url, @license_keycode_type_message_action
                    FROM ranked_message_content
                    WHERE locale_ranking <> 0
                    ORDER BY locale_ranking DESC, campaign_ranking DESC

                RETURN
            END


        -- 1.3) partner route
        select @partner_id 
= pl.partner_id
        from partner_license pl
        where pl.license_id = @license_id and pl.partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))

        -- 1.3.1) check for partner on parent
        if @partner_id is null    
            begin
                select @partner_id = pl.partner_id
                from partner_license pl
                inner join license_parent p
                    on pl.license_id = p.parent_license_id
                where p.child_license_id = @license_id and pl.partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))
            end

        -- 1.3.2) partner from trial
        if @partner_id is null     
            begin
                select @partner_id = p.partner_id            
                from trial t
                inner join  partner_trial p
                    on t.trial_id = p.trial_id
                inner join  dbo.license_summary s
                    on s.license_id = t.license_id and s.capability_type_id = 2
                where t.license_id = @license_id
            end

        -- 1.3.3) partner route
		--return the configuration value for non-zuora partner licenses
       IF (
       @partner_id IS NOT NULL
       AND
       (
           SELECT COUNT(*)
           FROM partner_configuration_partner
           WHERE partner_id = @partner_id
       ) > 0
       AND @zuora_license = 0
   )
	BEGIN
	    -- 1.3.3.1) @routing_url
	    SELECT @routing_url = p.configuration_value
	    FROM partner_configuration_partner p
	        INNER JOIN partner_configuration c
	            ON c.partner_configuration_id = p.partner_configuration_id
	    WHERE c.configuration_name = 'routing_url'
	          AND p.partner_id = @partner_id
	
	    IF @routing_url IS NOT NULL
	    BEGIN
	        -- 1.3.3.2) log
	        INSERT INTO cart_route
	        (
	            routing_action,
	            message_key,
	            license_id,
	            message_campaign_id,
	            message_campagn_platform
	        )
	        VALUES
	        ('partner_route', @message_key, @license_id, @message_campaign_id, @message_campaign_platform)
	
	        -- 1.3.3.3) return
	        SELECT message_campaign_id = 0,
	               message_campaign_name = '',
	               message_action = '',
	               language_code = @language_code,
	               location_code = @location_code,
	               location_code_iso =
	               (
	                   SELECT iso FROM lu_countries WHERE iso3 = @location_code
	               ),
	               message_url = @routing_url
	
	        RETURN
	    END
	END

        -- 1.4) get license details
	   SELECT @license_distribution_method_id = s.license_distribution_method_id,
		   @license_seats = s.license_seats,
		   @license_category_id = s.license_category_id,
		   @product_line_id = s.product_line_id,
		   @capability_activation_date = s.capability_activation_date,
		   @capability_expiration_date = s.capability_expiration_date,
		   @message_key = s.license_key,
		   @license_type_id = s.license_type_id,
		   @autorenewal_opt_id = s.autorenewal_opt_id,
		   @opt_in = s.opt_in,
		   @license_status_id = s.license_status_id,
		   @contract_detail_update =  CASE
                                      WHEN s.contract_detail_update = 1 THEN
                                          1
                                      ELSE
                                          0
                                     END,
		   @license_keycode_type_id = CASE
                                      WHEN ipl.license_category_id IS NULL AND l.license_keycode_type_id = 3 THEN 1
                                      WHEN ipl.license_category_id IS NOT NULL THEN 1
                                      ELSE
                                          0
									 
 END,
		   @next_bill_date = nb.next_bill_date
		FROM dbo.license_summary s WITH (NOLOCK)
			INNER JOIN dbo.license l
				ON s.license_id = l.license_id
			LEFT JOIN dbo.license_next_bill_date nb
				ON nb.license_id = l.license_id
			LEFT JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES ipl
			    ON ipl.license_category_id = s.license_category_id
		WHERE s.license_id = @license_id

		IF (@capability_activation_date IS NULL OR @capability_expiration_date IS NULL)
			BEGIN
			SELECT   @capability_activation_date = lc.capability_activation_date,
                        @capability_expiration_date = lc.capability_expiration_date
			FROM license l WITH (NOLOCK)
                INNER JOIN license_category_license cl WITH (NOLOCK)
                    ON l.license_id = cl.license_id
                INNER JOIN license_category c WITH (NOLOCK)
                    ON cl.license_category_id = c.license_category_id
                INNER JOIN license_capability lc WITH (NOLOCK)
                    ON l.license_id = lc.license_id AND lc.capability_id = c.base_capability_id
			WHERE l.license_id = @license_id
			END

        -- 1.4.1) get license data if license_summary does not exist
        IF @license_distribution_method_id IS NULL
            BEGIN
                -- 1.4.1.1) license_key
                INSERT INTO license_key(license_id) 
                SELECT l.license_id
                FROM license l WITH (NOLOCK)
                LEFT JOIN license_key k WITH (NOLOCK)
                    ON l.license_id = k.license_id
                WHERE k.license_key IS NULL AND l.license_id = @license_id

                -- 1.4.1.2) license_category_license
                INSERT INTO license_category_license(license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by)
                SELECT l.license_id, c.license_category_id, lc.capability_activation_date, lc.capability_expiration_date, lc.modified_date, lc.modified_by
                FROM license l WITH (NOLOCK)
                INNER JOIN license_category c WITH (NOLOCK)
                    ON dbo.fn_GetLicenseCategoryId(l.license_id) = c.license_category_id
                INNER JOIN license_capability lc WITH (NOLOCK)
                    ON l.license_id = lc.license_id AND lc.capability_id = c.base_capability_id
                LEFT JOIN license_category_license lcl WITH (NOLOCK)
                    ON l.license_id = lcl.license_id
                WHERE lcl.license_category_license_id IS NULL AND c.license_category_id IS NOT NULL AND l.license_id = @license_id

                -- 1.4.1.3) license_seat
                INSERT INTO license_seat(license_id, license_seats, insert_date, insert_by, modified_date, modified_by, start_date, end_date)
                select cl.license_id, 1, lc.insert_date, lc.insert_by, lc.modified_date, lc.modified_by, lc.capability_activation_date, lc.capability_expiration_date
                from license l with (nolock)
                inner join license_category_license cl with (nolock)
                    on l.license_id = cl.license_id
                inner join license_category c with (nolock)
                    on cl.license_category_id = c.license_category_id
                inner join license_capability lc with (nolock)
                    on l.license_id = lc.license_id and lc.capability_id = c.base_capability_id
                left join license_seat s with (nolock)
                    on l.license_id = s.license_id
                where s.license_seat_id is null and l.license_id = @license_id

                select @rowcnt = count(license_id) from license_check_update_license where license_id =  @license_id 

                if @rowcnt = 0 and @license_id is not null
                    INSERT into license_check_update_license(license_id,source) values(@license_id,5)
                
                -- 1.4.1.4) inseert @license_summary
                SELECT @
message_key = k.license_key,
                        @license_distribution_method_id = l.license_distribution_method_id,
                        @license_type_id = l.license_type_id,
                        @license_status_id = l.license_status_id,
                        @product_line_id = l.product_line_id,
                        @license_seats = st.license_seats,
                        @license_category_id = lcl.license_category_id,
                        @opt_in = ISNULL(c.opt_in,1),
                        @autorenewal_opt_id = CASE 
                                                WHEN s.subscription_id IS NULL AND al.license_attribute_license_value = 1 THEN 1 
                                                WHEN s.subscription_id IS NOT NULL AND s.opt_status = 0 THEN 1
                                                ELSE 0 
                                            END,
                        @capability_type_id = lc.capability_type_id,
                        @capability_activation_date = lc.capability_activation_date,
                        @capability_expiration_date = lc.capability_expiration_date,
                        @contract_detail_update = CASE WHEN s.contract_detail_update = 1 THEN 1 ELSE 0 END,
                        @license_keycode_type_id = l.license_keycode_type_id
                FROM license l WITH (NOLOCK)
                LEFT JOIN license_keycode_alias ka WITH (NOLOCK)
                    ON l.license_id = ka.license_id
                LEFT JOIN license_key k WITH (NOLOCK)
                    ON l.license_id = k.license_id
                LEFT JOIN license_seat st WITH (NOLOCK)
                    ON l.license_id = st.license_id
                LEFT JOIN license_category_license lcl WITH (NOLOCK)
                    ON l.license_id = lcl.license_id
                LEFT JOIN license_category ct WITH (NOLOCK)
                    ON lcl.license_category_id = ct.license_category_id
                LEFT JOIN license_capability lc WITH (NOLOCK)
                    ON l.license_id = lc.license_id AND lc.capability_id = ct.base_capability_id
                LEFT JOIN customer c WITH (NOLOCK)
                    ON l.customer_id = c.customer_id
                LEFT JOIN license_attribute_license al WITH (NOLOCK)
                    ON l.license_id = al.license_id
                LEFT JOIN subscription s WITH (NOLOCK)
                    ON l.license_id = s.license_id
                LEFT JOIN subscription_external e WITH (NOLOCK)
                    ON s.subscription_id = e.subscription_id
                WHERE l.license_id = @license_id

            END
        
        --------------------------------------------------------------------------------------------------------------------------------
        -- 2) select other options
        --------------------------------------------------------------------------------------------------------------------------------

        -- 2.1) set @account_creation_status value
        SELECT @account_creation_status = CASE WHEN COUNT(account_id) > 0 THEN 1 ELSE 0 END FROM account_license WHERE license_id = @license_id

        -- 2.2) set @renewal_status value
        SELECT @renewal_status = CASE WHEN COUNT(license_id) > 0 THEN 1 ELSE 0 END FROM license_renewals WHERE license_id = @license_id


        -- 2.3) update license_category if old WAV,WISE
        SELECT @license_category_id = CASE
                                            --when @license_category_id = 1 then 100
                                            WHEN @license_category_id IN (2,150,151) THEN 100
                                            WHEN @license_category_id IN (3,4,110) THEN 120
                                            ELSE @license_category_id
                                        END


        -- 2.4) product line
        SELECT @product_line_id = product_line_id
        FROM license_category_product_line
   
     WHERE license_category_id = @license_category_id AND 
            language_code = @language_code AND 
            location_code = @location_code

		


        -- 2.5) OEM keycodes no messages
        --if @license_type_id in (2,3)
        --    begin
        --    return
        --    end


        -- 2.6) if capability expiration date is not set the exit
        if @capability_expiration_date is null 
            begin
                select @capability_activation_date = getdate(),
                        @capability_expiration_date = dateadd(dd,capability_activation_days,getdate())
                from license_capability with (nolock)
                where license_id = @license_id and capability_id = @base_capability_id
            end

        -- 2.7) @subscription_start_date
        select @bestbuy_adjustment = 0

        select @subscription_start_date = start_date,
                @subscription_expiration_date = case
                                            when cancel_reason is not null then cancel_date
                                            when start_date is not null and cancel_reason is null and expiration_date is null then @capability_expiration_date
                                            else expiration_date
                                        end,
                @hard_cancel = case
                                when cancel_reason like '1%' or opt_status = 1 then 1
                                else 0
                            end
        from subscription with (nolock)
        where license_id = @license_id

        -- 2.8) set @capability_expiration_date if different from bby expiration
        if DATEDIFF(dd,@subscription_expiration_date,@capability_expiration_date) > 0
            begin
                SELECT @capability_expiration_date = @subscription_expiration_date
            end

        -- 2.9) trial
        select     @trial = case when count(*) > 0 then 1 else 0 end
        from license_capability with (nolock)
        where license_id = @license_id and capability_type_id in (2,3)

        -- 2.10) set @months to support the dynamic calculation of days remaining to be in the 6 months remaining
        select @months = -7
    
        -- 2.11) Check specific lang/loc for distribution method
        if (select count(*) from license_distribution_method_language_location where license_distribution_method_id = @license_distribution_method_id) > 0 AND @zuora_license = 0
            begin
                select @language_code = language_code, @location_code = location_code
                from license_distribution_method_language_location 
                where license_distribution_method_id = @license_distribution_method_id
            end
			
        -- 2.12) set @license_channel_id value
        select @license_channel_id = license_channel_id from license_channel_license with (nolock) where license_id = @license_id
        if @license_channel_id is NULL SELECT @license_channel_id = 0


        -- 2.13) App store status
        ;WITH
            app_store_orders AS (
                SELECT o.skytell_notification_id, o.pending_account_id, o.account_hash_id, o.account_id, o.email, o.opt_in, o.merchant_product_id, o.order_token, o.order_receipt, o.vendor_order_date, o.vendor_expiration_date, o.license_id, o.keycode, o.license_status_id, o.license_seats, o.autorenewal_cycle_name, o.license_attribute_license_value, o.merchant_id
                FROM dbo.fn_account_order_select_orders_by_license(@license_id) o
                    INNER JOIN dbo.payment_merchant pm
                        ON pm.merchant_id = o.merchant_id
                    INNER JOIN dbo.merchant_category_merchant mcm
                        ON mcm.payment_merchant_id = pm.payment_merchant_id
                WHERE o.license_id = @license_id
                    AND mcm.merchant_category_id = 1                  --App Store
            )
      
      SELECT @app_store_status = CASE
                    WHEN EXISTS (SELECT * FROM app_store_orders WHERE vendor_expiration_date IS NULL OR vendor_expiration_date > GETDATE()) THEN 1   -- Any active app store agreements?
                    WHEN EXISTS (SELECT * FROM app_store_orders) THEN 0                                                                              -- Any app store agreements at all?
                END


        --------------------------------------------------------------------------------------------------------------------------------
        -- 3) select new campaign data
        --------------------------------------------------------------------------------------------------------------------------------

        -- 3.1) find matching campaigns
        
        DECLARE @message_campaign TABLE (message_campaign_id INT)    

		-- 3.1.1) get campaigns matching distribution methods
		INSERT INTO @message_campaign(message_campaign_id) 
		SELECT message_campaign_id FROM message_campaign WITH (NOLOCK)
		EXCEPT
		SELECT message_campaign_id 
		FROM message_campaign_license_distribution_method WITH (NOLOCK)
		WHERE license_distribution_method_id = @license_distribution_method_id AND inclusive = 0
		EXCEPT
		(SELECT message_campaign_id FROM message_campaign WITH (NOLOCK)
		INTERSECT 
		SELECT message_campaign_id 
		FROM message_campaign_license_distribution_method WITH (NOLOCK)
		WHERE license_distribution_method_id <> @license_distribution_method_id AND inclusive = 1
		EXCEPT
		SELECT message_campaign_id 
		FROM message_campaign_license_distribution_method WITH (NOLOCK)
		WHERE license_distribution_method_id = @license_distribution_method_id AND inclusive = 1)
        
        -- 3.1.2) insert matching campaigns into table variable
        DECLARE @message_campaigns TABLE (message_campaigns_id INT IDENTITY(1,1), message_campaign_id INT, next_message_campaign_id INT, message_duration_days INT, process_date DATETIME, end_date DATETIME, archive_date DATETIME)
	 
	  INSERT INTO @message_campaigns(message_campaign_id, message_duration_days, process_date, end_date, archive_date)
        SELECT c.message_campaign_id,
                message_duration_days,
                process_date = CASE
                                    WHEN message_measure_point_id = 1 THEN DATEADD(dd,message_measure_days,@capability_activation_date)
							        WHEN message_measure_point_id = 2 AND message_measure_days = -180
									THEN 
										CASE WHEN @zuora_license=1 THEN
													 DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))
											 ELSE
													 DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
										END
                                    WHEN message_measure_point_id = 2 AND message_measure_days <> -180 
									THEN 
										CASE
										   WHEN @zuora_license = 1 THEN
											   DATEADD(dd, message_measure_days, ISNULL(@next_bill_date, @capability_expiration_date))
										   ELSE
											   DATEADD(dd, message_measure_days, @capability_expiration_date)
									   END
                                    
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 1 THEN DATEADD(dd,message_measure_days,@subscription_expiration_date)
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 0 THEN DATEADD(dd,message_measure_days+@bestbuy_adjustment,@subscription_expiration_date)
                                    WHEN message_measure_point_id = 4 THEN DATEADD(dd,message_measure_days,@capability_activation_date)
                                    WHEN message_measure_point_id = 5 THEN message_campaign_start_date

									WHEN message_measure_point_id = 7 AND message_measure_days = -180 
									THEN DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))
							        WHEN message_measure_point_id = 7 AND message_measure_days <> -180 
									THEN DATEADD(dd, message_measure_days, ISNULL(@next_bill_date, @capability_expiration_date))
									  
                                END,
                end_date =	 CASE
                                    WHEN message_measure_point_id = 1 THEN DATEADD(dd,message_measure_days+message_duration_days,@capability_activation_date)
                       				WHEN message_measure_point_id = 2 THEN 
										CASE
										   WHEN @zuora_license = 1 THEN
											   DATEADD(dd,message_measure_days + message_duration_days, ISNULL(@next_bill_date, @capability_expiration_date))
										   ELSE
											   DATEADD(dd, message_measure_days + message_duration_days, @capability_expiration_date)
										END
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 1 THEN DATEADD(dd,message_measure_days+message_duration_days,@subscription_expiration_date)
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 0 THEN DATEADD(dd,message_measure_days+message_duration_days+@bestbuy_adjustment,@subscription_expiration_date)
                                 	WHEN message_measure_point_id = 4 AND message_measure_end_days = -180 THEN 
										CASE 
											WHEN @zuora_license =1 THEN 
												DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))),ISNULL(@next_bill_date,@capability_expiration_date))
											ELSE
												DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
										END
                                    WHEN message_measure_point_id = 4 AND message_measure_end_days <> -180 THEN 
										CASE WHEN @zuora_license =1 THEN
                                    			DATEADD(dd,message_measure_end_days, ISNULL(@next_bill_date,@capability_expiration_date))
											 ELSE 
												DATEADD(dd,message_measure_end_days,@capability_expiration_date) 
										END
                                    WHEN message_measure_point_id = 5 THEN message_campaign_end_date
									WHEN message_measure_point_id = 7 THEN DATEADD(dd,message_measure_days + message_duration_days, ISNULL(@next_bill_date, @capability_expiration_date))
										  
                                END,
                archive_date = CASE
                                    WHEN message_measure_point_id = 1 THEN DATEADD(dd,message_measure_days+message_duration_days+30,@capability_activation_date)
                                    WHEN message_measure_point_id = 2 THEN 
										CASE WHEN @zuora_license =1 THEN
                                    		DATEADD(dd,message_measure_days+message_duration_days+30,ISNULL(@next_bill_date,@capability_expiration_date))
										ELSE
											DATEADD(dd,message_measure_days+message_duration_days+30,@capability_expiration_date)
										END
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 1 THEN DATEADD(dd,message_measure_days+message_duration_days+30,@subscription_expiration_date)
                                    WHEN message_measure_point_id = 3 AND @hard_cancel = 0 THEN DATEADD(dd,message_measure_days+message_duration_days+@bestbuy_adjustment+30,@subscription_expiration_date)
                                    WHEN message_measure_point_id = 4 AND @zuora_license=1 THEN ISNULL(@next_bill_date,@capability_expiration_date)
									WHEN message_measure_point_id = 
4 AND message_measure_end_days = -180 THEN DATEADD(dd,-(DATEDIFF(dd,DATEADD(dd,1,DATEADD(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
                                    WHEN message_measure_point_id = 4 AND message_measure_end_days <> -180 THEN DATEADD(dd,message_measure_end_days+30,@capability_expiration_date)
                                    WHEN message_measure_point_id = 5 THEN DATEADD(dd,30,message_campaign_end_date)
									WHEN message_measure_point_id = 7 THEN DATEADD(dd,message_measure_days+message_duration_days+30,ISNULL(@next_bill_date,@capability_expiration_date))
                                 

                                END
        FROM message_campaign c WITH (NOLOCK)
        INNER JOIN message_campaign_seat s WITH (NOLOCK)
            ON c.message_campaign_id = s.message_campaign_id
        INNER JOIN message_campaign_license_category lc WITH (NOLOCK)
            ON c.message_campaign_id = lc.message_campaign_id
        INNER JOIN message_campaign_email_election e WITH (NOLOCK)
            ON c.message_campaign_id = e.message_campaign_id
        INNER JOIN message_campaign_measure_point mp WITH (NOLOCK)
            ON c.message_campaign_id = mp.message_campaign_id
        INNER JOIN message_campaign_autorenewal a WITH (NOLOCK)
            ON c.message_campaign_id = a.message_campaign_id
        INNER JOIN message_campaign_product_line pl WITH (NOLOCK)
            ON c.message_campaign_id = pl.message_campaign_id
        INNER JOIN message_campaign_language_location cll WITH (NOLOCK)
            ON c.message_campaign_id = cll.message_campaign_id
        INNER JOIN message_campaign_trial t WITH (NOLOCK)
            ON c.message_campaign_id = t.message_campaign_id
        INNER JOIN message_campaign_license_status st WITH (NOLOCK)
            ON c.message_campaign_id = st.message_campaign_id
        INNER JOIN message_campaign_contract_detail cd
            ON c.message_campaign_id = cd.message_campaign_id
        INNER JOIN message_campaign_account_creation_status acs
            ON c.message_campaign_id = acs.message_campaign_id
        INNER JOIN message_campaign_renewal_status rt
            ON c.message_campaign_id = rt.message_campaign_id 
        INNER JOIN message_campaign_license_channel ch
            ON c.message_campaign_id = ch.message_campaign_id
        INNER JOIN message_campaign_license_keycode_type lk
            ON c.message_campaign_id = lk.message_campaign_id
        INNER JOIN dbo.message_campaign_app_store_status ss
            ON ss.message_campaign_id = c.message_campaign_id
        WHERE c.message_campaign_id IN (SELECT message_campaign_id FROM @message_campaign) 
            AND pl.product_line_id = @product_line_id
            AND cll.language_code = @language_code AND cll.location_code = @location_code
            AND t.trial = @trial
            AND s.license_seats = CASE WHEN @product_line_id IN (300,55) THEN s.license_seats ELSE @license_seats END
            AND lc.license_category_id = @license_category_id
            AND e.message_email_opt_id = @opt_in
            AND a.autorenewal_opt_id = @autorenewal_opt_id
            AND st.license_status_id = @license_status_id
            AND acs.account_creation_status = @account_creation_status
            AND rt.renewal_status = @renewal_status
            AND ch.license_channel_id = @license_channel_id
            AND cd.contract_detail_update = @contract_detail_update
            AND lk.license_keycode_type_id = @license_keycode_type_id
            AND (ss.app_store_status IS NULL OR ss.app_store_status = @app_store_status)
            AND c.message_campaign_enabled = 1
            AND c.message_campaign_class_id = 6
            AND c.message_campaign_start_date <= GETDATE() AND (c.message_campaign_end_date > GETDATE() OR c.message_campaign_end_date IS NULL)
        ORDER BY process_date  

		--DEBUG!!
      
  --SELECT '@message_campaigns',* from @message_campaigns
        --return
	

--, DATEDIFF(dd,@capability_expiration_date,@subscription_expiration_date), capability_expiration_date = @capability_expiration_date, subscription_expiration_date = @subscription_expiration_date, c.*, hard_cancel = @hard_cancel


	SELECT @route_message_campaign_id = t.message_campaign_id,
		   @message_campaign_name = t.message_campaign_name,
		   @message_action = t.message_action,
		   @message_url = t.message_url

	FROM
	(
		SELECT TOP 1
       mc.message_campaign_id,
       mc.message_campaign_name,
       cn.message_action,
       cn.message_url
		--, DATEDIFF(dd,@capability_expiration_date,@subscription_expiration_date), capability_expiration_date = @capability_expiration_date, subscription_expiration_date = @subscription_expiration_date, c.*, hard_cancel = @hard_cancel
		FROM @message_campaigns c
		    INNER JOIN message_campaign mc
		        ON c.message_campaign_id = mc.message_campaign_id
		    INNER JOIN message_campaign_content cc
		        ON c.message_campaign_id = cc.message_campaign_id
		    INNER JOIN message_content cn
		        ON cc.message_content_id = cn.message_content_id
		    LEFT JOIN message_campaign_license_distribution_method m
		        ON c.message_campaign_id = m.message_campaign_id
		           AND m.license_distribution_method_id = @license_distribution_method_id
		    LEFT JOIN @interstitial_routing_campaigns zc
		        ON zc.message_campaign_id = mc.message_campaign_id
		WHERE DATEADD(dd, -1, c.process_date) <= GETDATE()
		      AND GETDATE() < c.end_date
		      AND c.message_campaign_id = CASE
		                                      WHEN @ZUORA_LICENSE = 1 THEN
		                                          zc.message_campaign_id
		                                      ELSE
		                                          c.message_campaign_id
		                                  END
		ORDER BY m.inclusive DESC
			
	) t

	  -- 3.2 For non-migrated consumer keycodes with USA location
	  --Begins
	IF @BUSINESS_LICENSE = 0
	   AND @ZUORA_LICENSE = 0
	   AND @location_code = @PORTAL_LOCATION_CODE
	BEGIN

		IF EXISTS
		(
			SELECT 1
			FROM @interstitial_routing_campaigns
			WHERE message_campaign_name = @message_campaign_name
				  AND DATEDIFF(dd, GETDATE(), @capability_expiration_date) > @LICENSE_REMAINING_DAYS
		)
		BEGIN
			SELECT @route_message_campaign_id = NULL,
				   @message_campaign_name = NULL,
				   @message_action = NULL,
				   @message_url = @PORTAL_CART_URL
		END
		ELSE IF EXISTS
		(
			SELECT 1
			FROM @portal_cart_routing_campaigns m
			WHERE m.message_campaign_name = @message_campaign_name
		)
		BEGIN
			SET @message_url = @PORTAL_CART_URL
		END

	END
	--Ends

        --------------------------------------------------------------------------------------------------------------------------------
        -- 4) log data and return 
        --------------------------------------------------------------------------------------------------------------------------------

        -- 4.1) insert cart_route
        INSERT INTO cart_route (routing_action, message_key, license_id, message_campaign_id, message_campagn_platform)
        VALUES(@message_action, @message_key, @license_id, @message_campaign_id, @message_campaign_platform)
       
	 

     -- 4.2) return result  

        SELECT 	message_campaign_id = ISNULL(@route_message_campaign_id,0), 
                message_campaign_name = ISNULL(@message_campaign_name,'Default Billing'), 
                message_action = ISNULL(@message_action,'billing'), 
                language_code = @language_code, 
                location_code = @location_code, 
                location_code_iso = (SELECT iso FROM lu_countries WHERE iso3 = @location_code),
                message_url= @message_url            
		 
    END TRY

    BEGIN CATCH

        SET @response_code = -20
0
        SET @message = CASE WHEN @message IS NULL THEN 'insert failed'
                            ELSE @message END

        DECLARE @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_location]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_location]

(
	@language_code varchar(2) = null,
	@active tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select @language_code = null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @locations table (location_id int identity(1,1), country_id int,country_name varchar(75), language_code varchar(2), location_code varchar(3), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), product_line_list varchar(200))

	insert into @locations(country_id, country_name, language_code, location_code, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text)
	select lc.country_id, country_name = lc.description, cl.language_code, cl.location_code, 
		c.currency_id, c.currency_code, c.currency_description, c.symbol_html, c.symbol_utf8, c.symbol_text
	from currency_language_location cl
	inner join currency c
		on cl.currency_id = c.currency_id
	inner join lu_countries lc
		on cl.location_code = lc.iso3
	where cl.language_code = case when @language_code is null then cl.language_code else @language_code end and
		c.active = case when @active is null then 1 else @active end
	
	declare @location_id int, @total_locations int, @location_code varchar(3)

	select @total_locations = max(location_id), @location_id = 1 from @locations

	while @total_locations >= @location_id
		begin
		select @location_code = location_code, @language_code = language_code from @locations where location_id = @location_id

		print @location_code
		declare @product_line_list varchar(200)

		select @product_line_list = coalesce(@product_line_list+', ','')+ cast(convert(varchar(10),t.product_line_id) as varchar(100)) 
		from (select distinct l.product_line_id
			from license_category_product_line lc
			inner join product_line l
				on lc.product_line_id = l.product_line_id
			where language_code = @language_code and location_code = @location_code 
				and status = 1 --and l.product_line_id not in (300) -- TODO come up with a way to restrict this from the data
  			) t

		update @locations set product_line_list = @product_line_list where location_id = @location_id

		select @product_line_list = null
		select @location_id = @location_id + 1
		end

	select country_id, country_name, language_code, location_code, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, product_line_list
	from @locations
	order by language_code, country_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_merchant]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cart_select_merchant] (
    @location_code VARCHAR(3),
    @currency_code VARCHAR(3),
	@license_category_name VARCHAR(20) = NULL
)
AS

/*
	DATE			AUTHOR			REMARKS
	2022-09-01		gblandford		Initial creation. 
	2022-09-07		gblandford		Check @license_category_name for empty
    

    DESCRIPTION
    Reworking of dbo.usp_select_merchant using new architecture 

*/

	SET NOCOUNT ON

	DECLARE @response_code INT

    BEGIN TRY
    
		IF @license_category_name IS NULL 
			BEGIN
				SET @license_category_name = 'SAEP';
            end

        select distinct 
			pm.merchant_id
			, pm.payment_merchant_id
			, pm.payment_merchant_name

        from dbo.payment_merchant pm
		inner join dbo.country_currency_merchant ccm on  ccm.payment_merchant_id = pm.payment_merchant_id
		inner join dbo.lu_countries lu on lu.country_id = ccm.country_id
		inner join dbo.currency cur on cur.currency_id = ccm.currency_id
		inner join dbo.license_category lc on lc.license_category_id = ccm.license_category_id 
		inner join dbo.license_category_product_line lcpl on lcpl.license_category_id = lc.license_category_id

        where pm.is_csi_displayed = 1
		and cur.currency_code = @currency_code
		and lu.iso3 = @location_code
		and lc.license_category_name = (
			case 
				when isnull(@license_category_name, '') = '' then lc.license_category_name
				else @license_category_name
			end	)
		and lcpl.product_line_id = 300 -- business
		and lcpl.location_code = @location_code; -- filter on location

    end try
    
    begin catch

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec dbo.usp_LogError @ErrorDB = @DBName
    end catch

	grant execute on dbo.usp_cart_select_merchant to execsprocs;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_message_campaign_product_set]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_message_campaign_product_set]

(
		@message_platform_name varchar(50),
		@license_distribution_method_code char(4),
		@keycode varchar(40) = null,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-23	esmart		Initial creation.
	2012-12-15	esmart		Modify to take specified discount seat and years
	2013-05-22	esmart		Extended for specific license, lang/loc
	2013-10-22	esmart		Add discount method and discount to result

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@license_id int,
			@product_line_id int,
			@license_distribution_method_id int,
			@license_seats int,
			@license_category_id int,
			@license_type_id int,
			@license_status_id int,
			@base_capability_id int,
			@opt_in int,
			@message_platform_id tinyint,
			@activation_date datetime, 
			@expiration_date datetime,
			@message_campaign_class_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) 
	if @language_code is null or @location_code is null
		begin
		select @language_code = 'EN', @location_code = 'USA'
		end

	-- 1.2) select @license_distribution_method_id
	select @license_distribution_method_id = license_distribution_method_id from license_distribution_method where license_distribution_method_code = @license_distribution_method_code
		
	-- 1.3) get license details
	select	@license_id = l.license_id,
			@license_seats = isnull(s.license_seats,1),
			@license_category_id = isnull(lcl.license_category_id,dbo.fn_GetLicenseCategoryId(@license_id)),
			@opt_in = isnull(c.opt_in,1),
			@license_type_id = l.license_type_id,
			@license_status_id = l.license_status_id
	from license l with (nolock)
	left join license_seat s with (nolock)
		on l.license_id = s.license_id
	left join license_category_license lcl with (nolock)
		on l.license_id = lcl.license_id
	left join customer c with (nolock)
		on l.customer_id = c.customer_id
	left join license_attribute_license al
		on l.license_id = al.license_id
	where l.keycode = @keycode

		-- 1.3.1) update license_category if old WAV,WISE
		select @license_category_id = case
											when @license_category_id = 1 then 100
											when @license_category_id = 2 then 100
											when @license_category_id in (3,4,110) then 120
											else @license_category_id
										end

		-- 1.3.2) product line
		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code

		-- 1.3.3) OEM keycodes no messages
		if @license_type_id in (2,3)
			begin
			return
			end
	
	-- 1.4) @base_capability_id
	select @base_capability_id = base_capability_id from license_category where license_category_id = @license_category_id

	-- 1.5) capability data
	select @activation_date = capability_activation_date,
			@expiration_date = capability_expiration_date
	from license_capability with (nolock)
	where license_id = @license_id and capability_id = @base_capability_id

		-- 1.5.1) if capability expiration date is not set the exit
		if @expiration_date is null 
			begin
			select @activation_date = getdate(),
					@expiration_date = dateadd(dd,capability_activation_days,getdate())
			from license_capability with (nolock)
			where
 license_id = @license_id and capability_id = @base_capability_id
			end

	-- 1.6) @message_platform_id
	select @message_platform_id = message_platform_id from message_platform where massage_platform_name = @message_platform_name

	-- 1.7) @message_campaign_class_id
	select @message_campaign_class_id = 5 -- website campaigns

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) product set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
	-- 2.1) create product set	
		declare @product table (message_campaign_id int, product_id int, product_description varchar(100), retail_price money, seats int, storage_gb int, license_category_id tinyint, years float, cart_discount_id int, message_campaign_start_date datetime, message_campaign_end_date datetime)

		insert into @product(message_campaign_id, product_id, product_description, retail_price, seats, storage_gb, license_category_id, years, cart_discount_id, message_campaign_start_date, message_campaign_end_date)
		select distinct t.message_campaign_id, p.product_id, p.product_description, p.retail_price, ps.seats, st.storage_gb, lc.license_category_id, y.years, t.cart_discount_id, t.message_campaign_start_date, t.message_campaign_end_date
		from product p
		inner join product_seat ps
			on p.product_id = ps.product_id
		inner join product_license_category lc
			on p.product_id = lc.product_id
		inner join product_years y
			on p.product_id = y.product_id
		inner join product_line_product l
			on p.product_id = l.product_id
		inner join (select m.message_campaign_id, s.license_seats, c.license_category_id, pl.product_line_id, cd.cart_discount_id, 
						message_campaign_start_date = case
										when message_measure_point_id = 1 then dateadd(dd,mp.message_measure_days,@activation_date)
										when message_measure_point_id = 2 then dateadd(dd,mp.message_measure_days,@expiration_date)
										when message_measure_point_id = 3 then dateadd(dd,mp.message_measure_days,@activation_date)
										when message_measure_point_id = 4 then dateadd(dd,mp.message_measure_days,@activation_date)
										when message_measure_point_id = 5 then m.message_campaign_start_date
									end,
						message_campaign_end_date = case
										when message_measure_point_id = 1 then dateadd(dd,mp.message_duration_days,@activation_date)
										when message_measure_point_id = 2 then dateadd(dd,mp.message_duration_days,@expiration_date)
										when message_measure_point_id = 3 then dateadd(dd,mp.message_duration_days,@activation_date)
										when message_measure_point_id = 4 then dateadd(dd,mp.message_measure_end_days,@expiration_date)
										when message_measure_point_id = 5 then m.message_campaign_end_date
									end
					from message_campaign m
					inner join message_campaign_license_distribution_method d
						on m.message_campaign_id = d.message_campaign_id
					inner join message_campaign_seat s
						on m.message_campaign_id = s.message_campaign_id
					inner join message_campaign_license_category c
						on m.message_campaign_id = c.message_campaign_id
					inner join message_campaign_product_line pl
						on m.message_campaign_id = pl.message_campaign_id
					inner join message_campaign_platform pf
						on m.message_campaign_id = pf.message_campaign_id
					inner join message_campaign_measure_point mp
						on m.message_campaign_id = mp.message_campaign_id
					left join message_campaign_cart_discount cd
						on m.message_campaign_id = cd.message_campaign_id
					where d.license_distribution_method_id = @license_distribution_method_id and d.inclusive = 1 and pf.message_platform_id = @message_platform_id and m.message_campaign_class_id = @message_campaign_class_id and m.messag
e_campaign_enabled = 1) t
			on t.license_seats = ps.seats and t.license_category_id = lc.license_category_id and l.product_line_id = t.product_line_id
		left join product_storage st
			on p.product_id = st.product_id
		where p.product_type_id = 1 and product_lifecycle_id = 1 and retail_price > 0

		-- 2.2) for backward compatible pages
		if @message_platform_name = 'website'
			begin
			select p.message_campaign_id, p.product_id, p.product_description, p.license_category_id, lc.license_category_name, p.seats, s.storage_gb, p.years, p.cart_discount_id, message_campaign_start_date, message_campaign_end_date,
				m.cart_discount_method_name, i.discount, i.years,
				specials_code = (select top 1 specials_code from cart_discount_specials_mapping where cart_discount_id = p.cart_discount_id)
			from @product p
			inner join license_category lc
				on p.license_category_id = lc.license_category_id
			left join product_storage s
				on p.product_id = s.product_id
			left join cart_discount d
				on p.cart_discount_id = d.cart_discount_id 
			left join cart_discount_item i
				on d.cart_discount_id = i.cart_discount_id
			left join cart_discount_method m
				on i.cart_discount_method_id = m.cart_discount_method_id
			left join cart_discount_item_discount dd
				on i.cart_discount_item_id = dd.cart_discount_item_id
			where p.years = case
								when i.years is null then (select min(years) from product_license_category_years where license_category_id = lc.license_category_id)
								else i.years 
							end 
							and
				p.seats = case
								when i.license_seats is null then (select min(seats) from product_license_category_seat where license_category_id = lc.license_category_id)
								else i.license_seats
							end
			order by p.license_category_id, p.seats, s.storage_gb, p.years
			end
		else
		-- 2.3) new external subscription support
			begin
			declare @message_set table (message_id int identity(1,1), message_campaign_id int, license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, storage_gb int, years float, cart_discount_id int, retail_price money, net_price money, message_campaign_start_date datetime, message_campaign_end_date datetime,message_content_name varchar(50))

			declare @product_set table(license_category_name_input varchar(10), license_category_id_input tinyint, storage_gb_input int, product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

			declare @license_category_name varchar(10),
					@storage_gb int,
					@years float,
					@cart_discount_id int,
					@retail_price money,
					@net_price money

			-- 2.3.1) insert message set
			insert into @message_set(message_campaign_id,license_category_id,license_category_name,license_category_description,seats,storage_gb,years,cart_discount_id,message_campaign_start_date,message_campaign_end_date,message_content_name)
			select 	p.message_campaign_id,lc.license_category_id,lc.license_category_name,lc.license_category_description,seats,storage_gb,years,cart_discount_id,message_campaign_start_date,message_campaign_end_date,cc.message_content_name
			from @product p
			inner join license_category lc
				on p.license_category_id = lc.license_category_id
			left join message_campaign_content c
				on p.message_campaign_id = c.message_campaign_id
			left join message_content cc
				on c.message_content_id = cc.message_content_id
			where years = 1 and message_campaign_start_date <= getdate() and getdate() < message_campaign_end_date
			order by lc.license_category_id


			declare @message_id int, @total_messages int


			select @message_id = 1, @total_messages = count(*) from @message_set

			-- 2.3.3) start loop
			while @total_messages >= @message_id
				begin
				select @license_category_name = license_category_name,
						@license_seats = seats,
						@storage_gb = storage_gb,
						@years = years,
						@cart_discount_id = cart_discount_id
				from @message_set
				where message_id = @message_id

				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_new_product_set @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code

				select @retail_price = sum(retail_price), @net_price = sum(net_price), @cart_discount_id = max(cart_discount_id)
				from @product_set

				update @message_set
				set retail_price = @retail_price, net_price = @net_price, cart_discount_id = @cart_discount_id
				where message_id = @message_id

				delete from @product_set

				select @message_id = @message_id + 1
				end

			-- 2.3.4) return result
			select s.message_campaign_id,s.license_category_id,s.license_category_name,s.license_category_description,s.seats,s.storage_gb,s.years,i.cart_discount_id,s.retail_price,s.net_price,s.message_campaign_start_date,s.message_campaign_end_date,s.message_content_name, m.cart_discount_method_name,i.discount
			from @message_set s
			left join cart_discount_item i
				on s.cart_discount_id = i.cart_discount_id
			left join cart_discount_method m
				on i.cart_discount_method_id = m.cart_discount_method_id

			end
						
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_message_key]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_message_key]
(
    @message_key VARCHAR(36),
    @license_category_name VARCHAR(20) = NULL,
    @years INT = NULL,
    @seats INT = NULL,
    @sku VARCHAR(200) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-11	esmart		Initial creation.
	2018-07-30	esmart		Add license_keycode_type_id
	2020-08-06	wbarton		For license_message_key, changing the payment_header_id and customer_id to reference the license's most recent order data rather than license_message_value, which has data-maintenance issues. 
	2024-03-05	rambasna	Ecom-4248 For zuora product price, return zuora campagn_id and rate_plan_id

	DESCRIPTION
	select message key data

*/

AS
SET NOCOUNT ON;

DECLARE @message_key_type VARCHAR(50),
        @message_key_json NVARCHAR(MAX),
        @keycode VARCHAR(40),
        @license_id INT,
        @cart_order_id INT,
        @response_code INT,
        @message VARCHAR(100);

BEGIN TRY

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --1.0) zoura_campaign_id

    IF ISNUMERIC(@message_key) = 0
    BEGIN
        -- 1.1) license_key
        IF @message_key_type IS NULL
            SELECT @message_key_type = 'license_key'
            FROM license_key
            WHERE license_key = @message_key;

        -- 1.1.1) license_message
        IF @message_key_type IS NULL
        BEGIN
            SELECT @message_key_type = 'license_message_key',
                   @license_id = l.license_id,
                   @keycode = l.keycode
            FROM license_message m
                INNER JOIN license l
                    ON l.license_id = m.license_id
            WHERE m.license_message_key = @message_key;
        END;

        -- 1.1.2) cart_discount_key
        IF @message_key_type IS NULL
        BEGIN
            SELECT @message_key_type = 'cart_discount_key'
            FROM cart_discount
            WHERE cart_discount_key = @message_key;
        END;

        -- 1.1.3) cart_discount_message_key
        IF @message_key_type IS NULL
        BEGIN
            SELECT @message_key_type = 'cart_discount_message_key'
            FROM cart_discount_message
            WHERE cart_discount_message_key = @message_key;
        END;
    END;

    -- 1.1.4) zuora_campaign_id
    IF ISNUMERIC(@message_key) = 1
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM dbo.zuora_product_pricing
            WHERE campaign_id = @message_key
        )
        BEGIN
            SELECT @message_key_type = 'zuora_campaign_id'
            FROM dbo.zuora_product_pricing
            WHERE campaign_id = @message_key;
        END;
    END;

    -- select message_key_type = @message_key_type

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) 
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --2.0) zoura_campaign_id 
    IF @message_key_type = 'zuora_campaign_id'
    BEGIN

        IF @sku IS NOT NULL
        BEGIN
            SELECT @message_key_json =
            (
                SELECT DISTINCT
    
                   zp.campaign_id,
                       lc.license_category_name,
                       zp.years,
                       zp.seats,
                       zp.rate_plan_id,
                       zp.sku,
                       ((zp.renewal_price - zp.retail_price) / zp.renewal_price) * 100 discount
                FROM dbo.zuora_product_pricing zp
                    LEFT JOIN license_category lc
                        ON lc.license_category_id = zp.license_category_id
                WHERE campaign_id = @message_key
                      AND ISNULL(zp.years, 0) = ISNULL(@years, 0)
                      AND ISNULL(zp.seats, 0) = ISNULL(@seats, 0)
                      AND ISNULL(lc.license_category_name, 0) = ISNULL(@license_category_name, 0)
                      AND zp.sku = @sku
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );
        END;
        ELSE IF @license_category_name IS NOT NULL AND @years IS NOT NULL AND @seats IS NOT null
		   SELECT @message_key_json =
            (
                SELECT DISTINCT
                       zp.campaign_id,
                       lc.license_category_name,
                       zp.years,
                       zp.seats,
                       zp.rate_plan_id,
                       zp.sku,
                       ((zp.renewal_price - zp.retail_price) / zp.renewal_price) * 100 discount
                FROM dbo.zuora_product_pricing zp
                    LEFT JOIN license_category lc
                        ON lc.license_category_id = zp.license_category_id
                WHERE campaign_id = @message_key
                      AND ISNULL(zp.years, 0) = ISNULL(@years, 0)
                      AND ISNULL(zp.seats, 0) = ISNULL(@seats, 0)
                      AND ISNULL(lc.license_category_name, 0) = ISNULL(@license_category_name, 0)
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );

        SELECT message_key_type = @message_key_type,
               message_key_json = @message_key_json;
        RETURN;
    END;

    -- 2.1) license_key data
    IF @message_key_type = 'license_key'
    BEGIN
        SELECT @message_key_json =
        (
            SELECT l.license_id,
                   l.keycode,
                   customer_id,
                   l.license_keycode_type_id
            FROM license_key k
                INNER JOIN license l
                    ON k.license_id = l.license_id
            WHERE k.license_key = @message_key
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SELECT message_key_type = @message_key_type,
               message_key_json = @message_key_json;
        RETURN;
    END;

    -- 2.2) license_message data
    IF @message_key_type = 'license_message_key'
    BEGIN
        -- select @message_key_type

        DECLARE @license_message_values TABLE
        (
            message_value_type_name VARCHAR(50),
            value_id VARCHAR(20)
        );
        DECLARE @payment_header_id INT,
                @customer_id INT;

        INSERT INTO @license_message_values
        (
            message_value_type_name,
            v.value_id
        )
        SELECT t.message_value_type_name,
               v.value_id
        FROM license_message m
            INNER JOIN license_message_value v
                ON v.license_message_id = m.license_message_id
            INNER JOIN message_value_type t
                ON v.message_value_type_id = t.message_value_type_id
        WHERE m.license_message_key = @message_key;

        --Setting @payment_header_id and @customer_id to values from the license's most recent order
        SELECT @payment_header_id = oph.payment_header_id,
               @customer_id = co.customer_id
        FROM order_payment_header oph
            INNER JOIN
            (
                SELECT oil.license_id,
                       MAX(oi.order_header_id) AS most_recent_o
rder
                FROM order_item_license oil
                    INNER JOIN order_item oi
                        ON oi.order_item_id = oil.order_item_id
                WHERE oil.license_id = @license_id
                GROUP BY oil.license_id
            ) oi
                ON oph.order_header_id = oi.most_recent_order
            INNER JOIN dbo.customer_order co
                ON co.order_header_id = oph.order_header_id
                   AND co.customer_type_id = 1;

        SELECT @message_key_json =
        (
            SELECT license_id = @license_id,
                   keycode = @keycode,
                   payment_header_id = @payment_header_id,
                   customer_id = @customer_id,
                   cart_discount_id =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'cart_discount_id'
        )   ,
                   p_rc =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'p_rc'
        )   ,
                   p_rsc =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'p_rsc'
        )   ,
                   p_ac =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'p_ac'
        )   ,
                   trx_rc =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'trx_rc'
        )   ,
                   trx_rsc =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'trx_rsc'
        )   ,
                   trx_ac =
        (
            SELECT value_id
            FROM @license_message_values
            WHERE message_value_type_name = 'trx_ac'
        )
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SELECT message_key_type = @message_key_type,
               message_key_json = @message_key_json;
        RETURN;
    END;

    -- 2.3) cart_discount_key data
    IF @message_key_type = 'cart_discount_key'
    BEGIN

        SELECT @message_key_json =
        (
            SELECT d.cart_discount_id,
                   i.license_category_name,
                   i.license_seats,
                   i.storage_gb,
                   years = CONVERT(DECIMAL(4, 2), i.years),
                   i.cart_discount_method_id,
                   discount = CONVERT(DECIMAL(10, 4), i.discount),
                   license_keycode_type_id = CASE
                                                 WHEN i.license_category_id IN ( 220, 230, 231 ) THEN
                                                     3
                                                 ELSE
                                                     1
                                             END
            FROM cart_discount d
                INNER JOIN cart_discount_item i
                    ON i.cart_discount_id = d.cart_discount_id
            WHERE d.cart_discount_key = @message_key
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SELECT message_key_type = @message_key_type,
               message_key_json = @message_key_json;
        RETURN;
    END;

    -- 2.3) cart_discount_message_key data
    IF @message_key_type = 'cart_discount_message_key'
    BEGIN

        DECLARE @discount_message_values TABLE
        (
            message_value_type_name VARCHAR(50),
            value_id VARCHAR(20)
        );

        INSERT INTO @discount_message_values
        (
            message_value_type_name,
            v.value_id
        )
        SELECT t.message_value_type_name,
               v.value_id
        FROM cart_discount_message m
            INNER JOIN cart_discount_me
ssage_value v
                ON v.cart_discount_message_id = m.cart_discount_message_id
            INNER JOIN message_value_type t
                ON v.message_value_type_id = t.message_value_type_id
        WHERE m.cart_discount_message_key = @message_key;

        SELECT @cart_order_id = value_id
        FROM @discount_message_values
        WHERE message_value_type_name = 'cart_order_id';

        IF @cart_order_id IS NOT NULL
        BEGIN
            IF
            (
                SELECT cart_order_status_id
                FROM cart_order
                WHERE cart_order_id = @cart_order_id
            ) = 2
            BEGIN
                SELECT @message_key_json = NULL;
            END;
            ELSE
            BEGIN
                SELECT @message_key_json =
                (
                    SELECT cart_order_id,
                           vendor_order_code
                    FROM cart_order
                    WHERE cart_order_id = @cart_order_id
                    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
                );
            END;
        END;

        SELECT message_key_type = @message_key_type,
               message_key_json = @message_key_json;
        RETURN;
    END;

--end
END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_new_product_discount]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_new_product_discount]

(
		@license_category_name varchar(10), 
		@license_seats int,
		@storage_gb int,
		@years float,
		@cart_discount_method_id tinyint,
		@discount float,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@cart_type_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-09-10	esmart		Initial creation.

	DESCRIPTION
	select discount
*/

AS
	set nocount on				

	declare	@product_line_id int,
			@license_category_id tinyint,
			
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) @language_code and @location_code
		if @language_code is null or @location_code is null
			begin
			select @language_code = 'EN', @location_code = 'USA'
			end

	-- 1.1) select @license_category_id
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name

	-- 1.3) @license_seats
		if @license_seats is null or @license_seats = 0
			begin
				select @license_seats = min(seats) 
				from product_license_category_seat
				where license_category_id = @license_category_id
			end
			
	-- 1.4) @license_storage
		if @storage_gb is null or @storage_gb = 0
			begin
				select @storage_gb = min(storage_gb) 
				from product_license_category_storage
				where license_category_id = @license_category_id
				
				if @storage_gb is null begin select @storage_gb = 0 end
			end

	-- 1.5) @years
--		if @years is null or @years = 0
--			begin
--				select @years = 1
--			end

	-- 1.6) @discount
		if @discount is null 
			begin
			select @discount = 0
			end

	-- 1.7) @cart_discount_method_id
		if @cart_discount_method_id is null or @cart_discount_method_id = 0
			begin
			select @cart_discount_method_id = 1
			end

	-- 1.5) product_line_id
		if @cart_type_id is null
			begin
			select @cart_type_id = 1
			end

			select @product_line_id = product_line_id
			from license_category_product_line
			where license_category_id = @license_category_id and 
				language_code = @language_code and 
				location_code = @location_code and
				cart_type_id = @cart_type_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--select product_line_id = @product_line_id, license_category_id = @license_category_id, license_seats = @license_seats, storage_gb = @storage_gb, years = @years, discount = @discount

	select d.cart_discount_id, d.cart_discount_description, d.cart_discount_type_id, d.cart_discount_status_id, 
		cart_discount_key = convert(varchar(36),d.cart_discount_key), d.cart_discount_code, d.last_modified_date, d.last_modified_by
	from cart_discount_item i
	inner join cart_discount d
		on i.cart_discount_id = d.cart_discount_id
	where i.product_type_id = 1 and
			i.license_category_name = @license_category_name and
			i.license_seats = @license_seats and
			i.storage_gb = @storage_gb and
			i.years = @years and
			i.discount = @discount and 
			i.cart_discount_method_id = @cart_discount_method_id and
			i.product_line_id =
 @product_line_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_new_product_set]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_new_product_set]

(
		@license_category_name varchar(10), 
		@license_seats int,
		@storage_gb int,
		@years float,
		@cart_discount_id int = null,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@cart_type_id tinyint = null,
		@trial_days int = null,
		@license_keycode_type_id int = null
		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-07-08	esmart		Initial creation.
	2010-07-21	esmart		WW support
	2010-09-17	esmart		Discounting rev
	2010-12-17	esmart		Internation pricing support
	2011-12-13	esmart		Buy one, get one discount type (BOGO)
	2012-02-01	esmart		product_line_module
	2012-07-31	esmart		WSA 2013
	2012-12-27	esmart		Support discounts greater than retail
	2013-11-12	esmart		Modification for new product bundles
	2014-01-10	esmart		Update years to float
	2014-02-24	esmart		Add support of new trial product
	2014-03-24  esmart		Fix issue with CSI-beta discounting
	2015-05-11	esmart		Modify to support upgraded storage
	2018-07-09	cnovac		Added code for WIFI to check if trial product is needed
	2021-01-15	jnavarra	Update rounding precision (section 3.2)
	
	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_category_id tinyint,
			@product_id int,
			@product_line_id int,
--			@product_family_id int,
			@product_storage_gb int,
			@storage_product_id int,
			@discount_storage_gb int,
			@cart_discount_type_id tinyint

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) @language_code and @location_code
		if @language_code is null or @location_code is null
			begin
			select @language_code = 'EN', @location_code = 'USA'
			end

	-- 1.1) select @license_category_id
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name

	-- 1.2) product_family_id
--		select @product_family_id = case
--										when @license_category_id = 10 then 31
--										when @license_category_id = 10 then 31
--										when @license_category_id = 100 then 100
--										else 1
--									end

	-- 1.3) @license_seats
		if @license_seats is null or @license_seats = 0 or @license_seats = 1
			begin
				select @license_seats = min(seats) 
				from product_license_category_seat
				where license_category_id = @license_category_id
			end
			
	-- 1.4) @license_storage
		if @storage_gb is null or @storage_gb = 0
			begin
				select @storage_gb = min(storage_gb) 
				from product_license_category_storage
				where license_category_id = @license_category_id
				
				if @storage_gb is null begin select @storage_gb = 0 end
			end

		select @discount_storage_gb = max(storage_gb) from cart_discount_item where cart_discount_id = @cart_discount_id

		if @discount_storage_gb > @storage_gb
			begin
			select @storage_gb = @discount_storage_gb
			end
		
--	-- 1.5) @years
--		if @years is null or @years = 0
--			begin
--				select @years = 1
--			end

	-- 1.6) @product_line

		if @cart_type_id is null
			begin
			select @cart_type_id = 1
			end

		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code and
			cart
_type_id = @cart_type_id

	--	1.7) @cart_discount_type_id
		select @cart_discount_type_id = cart_discount_type_id
		from cart_discount
		where cart_discount_id = @cart_discount_id

	-- 1.8) usp_cart_select_campaign_cart_discount_new
		if @cart_discount_id is null or @cart_discount_id = 0
			begin
			exec usp_cart_select_campaign_cart_discount_new @license_category_name, @license_seats, @storage_gb, @years, @language_code, @location_code, @product_line_id, @cart_discount_id output
			end
			
	-- 1.9) bundle product
	if (select count(*) from cart_discount_item where cart_discount_id = @cart_discount_id) >= 1 and @cart_discount_type_id = 3
		begin
		select @product_line_id = product_line_id, @license_category_id = license_category_id, @license_seats = license_seats, @storage_gb = storage_gb, @years = years, @product_id = product_id
		from cart_discount_item
		where cart_discount_id = @cart_discount_id and product_type_id = 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) @license_keycode_type_id 
		if @license_keycode_type_id is null
			begin
			select @license_keycode_type_id = 1
			end 
	
	-- 2.1) select product
	if @trial_days is not null and (@years = 0 or @license_category_name = 'WIFI')--total hack for WIFI, not sure why @years = 0 is needed here, but need to code around
			begin
			--print 'trial'

			select @product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join license_category lc
				on c.license_category_id = lc.license_category_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_capability pc
				on p.product_id = pc.product_id and pc.capability_id = lc.base_capability_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
					on p.product_id = pl.product_id
			where p.product_type_id = 1 and
					p.license_keycode_type_id = @license_keycode_type_id and
					p.uses_keycode = 1 and
					s.seats = @license_seats and
					pl.product_line_id = @product_line_id and
					c.license_category_id = @license_category_id and 
					y.years = @years and
					pc.capability_activation_days = @trial_days
			end
		else
			begin
			if @storage_gb is null or @storage_gb = 0
				begin
					select @product_id = p.product_id
					from product p
					inner join product_license_category c
						on p.product_id = c.product_id
					inner join product_seat s
						on p.product_id = s.product_id
					inner join product_years y
						on p.product_id = y.product_id
					inner join product_line_product pl
						on p.product_id = pl.product_id
					where p.product_type_id = 1 and
							pl.product_line_id = @product_line_id and 
							p.product_lifecycle_id = 1 and
							c.license_category_id = @license_category_id and 
							s.seats = @license_seats and
							y.years = @years and					
							p.retail_price > 0
				end
			else
				begin
					select @product_id = p.product_id
					from product p
					inner join product_license_category c
						on p.product_id = c.product_id
					inner join product_seat s
						on p.product_id = s.product_id
					inner join product_years y
						on p.product_id = y.product_id
					inner join product_line_product pl
						on p.product_id = pl.product_id
					inner join product_storage st
						on p.product_id = st.product_id
					where p.product_type_id = 1 and
							pl.product_line_id = @product_line_id and 
							p.product_lifecycle_id = 1 and
							c.license_category_id =
 @license_category_id and 
							s.seats = @license_seats and
							y.years = @years and					
							st.storage_gb = @storage_gb and
							p.retail_price > 0
				end

			
			end


	-- 2.2) select storage_gb for product
		--select @product_storage_gb = storage_gb
		--from product_storage
		--where product_id = @product_id

		--if @product_storage_gb < @storage_gb
		--	begin
		--	select @storage_product_id = p.product_id
		--	from product_storage s
		--	inner join product p
		--		on s.product_id = p.product_id
		--	inner join product_years y
		--		on p.product_id = y.product_id
		--	inner join product_line_product pl
		--		on p.product_id = pl.product_id
		--	where pl.product_line_id = @product_line_id and 
		--			p.product_lifecycle_id = 1 and 
		--			p.product_type_id = 2 and
		--			storage_gb = @storage_gb and 
		--			current_storage_gb = @product_storage_gb and 
		--			y.years = @years and
		--			p.retail_price > 0
		--	end		


	--select product_line_id = @product_line_id, license_category_id = @license_category_id, license_seats = @license_seats, storage_gb = @storage_gb, years = @years, trial_days = @trial_days, product_id = @product_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) get product set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @product_set table(product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money default 0, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
		select p.product_id, p.product_description, 
			retail_price = case 
								when pp.product_pricing_id is null then p.retail_price
								else pp.retail_price
							end, 
			upgrade_price = case 
								when pp.product_pricing_id is null then p.retail_price
								else pp.retail_price
							end,
			discount = 0, p.product_type_id, lc.license_category_name, s.seats, y.years,
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
--			currency = case 
--							when pp.product_pricing_id is null then 'dollar'
--							else cu.currency_description
--						end
		from product p		
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join currency cu
			on pp.currency_id = cu.currency_id
		left join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		left join product_seat s
			on p.product_id = s.product_id
		left join product_years y
			on p.product_id = y.product_id
		where p.product_id = @product_id

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
		select p.product_id, p.product_description, 
			retail_price = case 
								when pp.product_pricing_id is null then p.retail_price
								else pp.retail_price
							end, 
			upgrade_price = case 
								when pp.product_pricing_id is null then p.re
tail_price
								else pp.retail_price
							end,
			discount = 0, p.product_type_id, lc.license_category_name, s.seats, y.years,
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
--			currency = case 
--							when pp.product_pricing_id is null then 'dollar'
--							else cu.currency_description
--						end
		from product p		
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join currency cu
			on pp.currency_id = cu.currency_id
		left join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		left join product_seat s
			on p.product_id = s.product_id
		left join product_years y
			on p.product_id = y.product_id
		where p.product_id = @storage_product_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Apply discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) bundle discount
	if @cart_discount_type_id = 3
		begin
			-- 3.1.1) 
			insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
			select p.product_id, p.product_description, 
				retail_price = case 
									when pp.product_pricing_id is null then p.retail_price
									else pp.retail_price
								end, 
				upgrade_price = case 
									when pp.product_pricing_id is null then p.retail_price
									else pp.retail_price
								end,
				discount = 0, p.product_type_id, lc.license_category_name, s.seats, y.years,
				cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
			from product p
			left join product_pricing pp
				on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
			left join currency cu
				on pp.currency_id = cu.currency_id
			inner join product_license_category c
				on p.product_id = c.product_id
			left join license_category lc
				on c.license_category_id = lc.license_category_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			inner join cart_discount_item i
				on c.license_category_id = i.license_category_id and s.seats = i.license_seats and y.years = i.years and pl.product_line_id = i.product_line_id and p.product_type_id = i.product_type_id
			where i.cart_discount_id = @cart_discount_id and i.product_type_id <> 4 and p.product_id <> @product_id
	
			-- 3.1.2) module 
			insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
			select p.product_id, p.product_description, 
				retail_price = isnull(pp.retail_price,p.retail_price)*@years,	
					upgrade_price = isnull(pp.retail_price,p.retail_price)*@years,
					discount = convert(money,isnull(id.discount,i.discount))*@years,
					p.product_type_id, lc.license_category_name, s.seats, y.years,
				cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
			from cart_discount_item i
			inner join cart_discount_item_license_module im
				on i.cart_discount_item_id = im.cart_discount_item_id
			left join cart_dis
count_item_discount id
				on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
			inner join product_license_module m
				on im.license_module_id = m.license_module_id
			inner join product p
				on m.product_id = p.product_id and i.product_type_id = p.product_type_id
			inner join product_license_category c
				on i.license_category_id = c.license_category_id and p.product_id = c.product_id
			inner join license_category lc
				on c.license_category_id = lc.license_category_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			left join product_pricing pp
				on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
			left join currency cu
				on pp.currency_id = cu.currency_id
			left join product_storage  ps
				on p.product_id = ps.product_id	
			where i.cart_discount_id = @cart_discount_id and i.product_type_id in (4) and s.seats = @license_seats and pl.product_line_id = i.product_line_id

		end
	
	-- 3.1) bogo
	if @cart_discount_type_id = 5
		begin
			insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
			select p.product_id, p.product_description, 
				retail_price = case 
									when pp.product_pricing_id is null then p.retail_price
									else pp.retail_price
								end, 
				upgrade_price = case 
									when pp.product_pricing_id is null then p.retail_price
									else pp.retail_price
								end,
--				discount = 0,
				discount =  case
							when i.cart_discount_method_id = 1 then  round(convert(money,isnull(id.discount,i.discount)),2)
							when i.cart_discount_method_id = 3 then ((convert(float,isnull(id.discount,i.discount))/100) * pp.retail_price)
							else 0
					end, 
				p.product_type_id, lc.license_category_name, s.seats, y.years,
				cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
			from product p
			left join product_pricing pp
				on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
			left join currency cu
				on pp.currency_id = cu.currency_id
			inner join product_license_category c
				on p.product_id = c.product_id
			left join license_category lc
				on c.license_category_id = lc.license_category_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			left join cart_discount_item i
				on i.cart_discount_id = @cart_discount_id and p.product_type_id = i.product_type_id
			left join cart_discount_item_discount id
				on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
			left join cart_discount d
				on i.cart_discount_id = d.cart_discount_id and d.cart_discount_type_id <> 5
			where c.license_category_id = @license_category_id and s.seats = @license_seats and y.years = @years and pl.product_line_id = @product_line_id and p.product_type_id = 1
		end

	-- 3.2) gift card
	if @cart_discount_type_id = 6
		begin
		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
		select p.product_id, p.product_description, 
			retail_price = isnull(pp.retail_price,p.retail_price)*@years,	
				upgrade_price = isnull(pp.retail_price,p.retail_price)*@years,
				discoun
t = convert(money,isnull(id.discount,i.discount))*@years,
				p.product_type_id, lc.license_category_name, s.seats, y.years,
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
		from cart_discount_item i
		left join cart_discount_item_discount id
			on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
		inner join product p
			on i.product_id = p.product_id
		inner join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		inner join product_seat s
			on p.product_id = s.product_id
		inner join product_years y
			on p.product_id = y.product_id
		inner join product_line_product pl
			on p.product_id = pl.product_id
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join currency cu
			on pp.currency_id = cu.currency_id
		left join product_storage  ps
			on p.product_id = ps.product_id	
		where i.cart_discount_id = @cart_discount_id
		end
		
	-- 3.2) apply discount
			update @product_set
			set discount =  case
							when d.cart_discount_type_id = 5 then s.discount
							when i.cart_discount_method_id = 1 and s.upgrade_price <> 0 then  round(convert(money,isnull(id.discount,i.discount)) * (s.retail_price/(select sum(retail_price) from @product_set where upgrade_price <> 0 and product_type_id = i.product_type_id)),2)
							when i.cart_discount_method_id = 2 and s.upgrade_price <> 0 then (s.retail_price - convert(money,isnull(id.discount,i.discount)))
							when i.cart_discount_method_id = 3 and s.upgrade_price <> 0 then  round((convert(float,isnull(id.discount,i.discount))/100) * s.retail_price,2)
							else s.discount
					end,
				cart_discount_id = @cart_discount_id
			from @product_set s
			left join cart_discount_item i
				on i.cart_discount_id = @cart_discount_id and ((i.years = s.years and i.license_seats = s.seats) or (i.years is null and i.license_seats is null)) --and s.product_type_id = i.product_type_id
			left join cart_discount_item_discount id
				on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
			left join cart_discount d
				on i.cart_discount_id = d.cart_discount_id and d.cart_discount_status_id = 1 --and d.cart_discount_type_id <> 5
			where i.product_type_id <> 4

			--select discount =  case
			--				when d.cart_discount_type_id = 5 then s.discount
			--				when i.cart_discount_method_id = 1 and s.upgrade_price <> 0 then  round(convert(money,isnull(id.discount,i.discount)) * (s.retail_price/(select sum(retail_price) from @product_set where upgrade_price <> 0 and product_type_id = i.product_type_id)),2)
			--				when i.cart_discount_method_id = 2 and s.upgrade_price <> 0 then (s.retail_price - convert(money,isnull(id.discount,i.discount)))
			--				when i.cart_discount_method_id = 3 and s.upgrade_price <> 0 then  round((convert(float,isnull(id.discount,i.discount))/100) * s.retail_price,1)
			--				else s.discount
			--		end,
			--	cart_discount_id = @cart_discount_id, *
			--from @product_set s
			--left join cart_discount_item i
			--	on i.cart_discount_id = @cart_discount_id and ((i.years = s.years and i.license_seats = s.seats) or (i.years is null and i.license_seats is null)) --and s.product_type_id = i.product_type_id
			--left join cart_discount_item_discount id
			--	on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
			--left join cart_discount d
			--	on i.cart_discount_id = d.cart_discount_id and d.cart_discount_status_id = 1 --and d.cart_discount_type_id <> 5
			--where i.product_type_id <> 4
				
	-- ---------------------------------------------------
------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) Return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select product_id, product_description, retail_price, 
				upgrade_price = case
									when retail_price - (discount+standard_discount) < 0 then 0
									else retail_price - (discount+standard_discount) 
								end, 
				discount  = case
								when retail_price - discount < 0 then retail_price
								else discount
							end,
				standard_discount, 
				net_price = case
								when retail_price - (discount+standard_discount) < 0 then 0
								else retail_price - (discount+standard_discount) 
							end, 
				product_type_id, license_category_name, seats, years, p_type, s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text, cart_discount_id
		from @product_set s
		left join currency c
			on s.currency_id = c.currency_id

--		select product_id,product_description,retail_price,upgrade_price = retail_price - discount,discount,net_price = retail_price - discount, product_type_id,license_category_name,seats,years
--		from @product_set

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_new_product_set_ENT]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_cart_select_new_product_set_ENT]

(
		@license_category_name varchar(10), 
		@license_seats int,
		@storage_gb int,
		@years float,
		@cart_discount_id int = null,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@cart_type_id tinyint = null,
		@trial_days int = null,
		@license_keycode_type_id int = null,
		@pricing_level varchar(20) = null,
		@module_json nvarchar(200) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-07	esmart		Initial creation.
	2013-02-26	esmart		Add support for supplemental cart discount
	2013-10-17	esmart		Support active tier discounts only 3.0)
	2014-01-10	esmart		Extend for license_keycode_type for support of parent products
	2014-03-06	esmart		Add fixed product pricing discounts
	2014-08-29	esmart		Resolve discount issue
	2015-04-03	esmart		Modify discount method to handle per seat per year rounding
	2015-07-22	esmart		Modify supplemental discount to look up years
	
	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_category_id tinyint,
			@product_id int,
			@product_line_id int,
			@product_storage_gb int,
			@storage_product_id int,
			@cart_discount_type_id tinyint,
			@cart_discount_method_id tinyint,
			@supplemental_cart_discount_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) verify language/location
		if @language_code is null or @location_code is null
			begin
			select @language_code = 'EN', @location_code = 'USA'
			end

	-- 1.1) select @license_category_id
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name

	-- 1.2) product_line_id
		select @cart_type_id = 2
--		if @cart_type_id is null
--			begin
--			select @cart_type_id = 2
--			end

		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code and
			cart_type_id = @cart_type_id


	-- 1.4) cart_discount_type

		-- 1.4.1) usp_cart_select_campaign_cart_discount_new
		if @cart_discount_id is null or @cart_discount_id = 0
			begin
			--print '1.4.1'
			exec usp_cart_select_campaign_cart_discount_new @license_category_name, 1, @storage_gb, @years, @language_code, @location_code, @product_line_id, @cart_discount_id output
			end

		-- 1.4.2) @cart_discount_type_id
		select @cart_discount_type_id = cart_discount_type_id
		from cart_discount
		where cart_discount_id = @cart_discount_id

		-- 1.4.3) @cart_discount_method_id
		select @cart_discount_method_id = min(cart_discount_method_id)
		from cart_discount_item
		where cart_discount_id = @cart_discount_id

		-- 1.4.4) if explicit cart discount is not tier set @supplemental_cart_discount_id
		if @cart_discount_type_id <> 4 and @cart_discount_method_id <> 2
			begin
			select @supplemental_cart_discount_id = @cart_discount_id
			select @cart_discount_id = null
			
			select @years = case when years is not null then years else @years end
			from cart_discount_item 
			where cart_discount_id = @supplemental_cart_discount_id
			
			end

			
	-- 1.3) select product
		
		-- 1.3.1) @license_keycode_type_id 
		if @license_keycode_type_id is null
			begin
			select @license_keycode_type_id = 1
			end 

		-- 1.3.2) select product
		if @trial_days is n
ot null and @years = 0
			begin
			select @product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join license_category lc
				on c.license_category_id = lc.license_category_id
			inner join product_capability pc
				on p.product_id = pc.product_id and pc.capability_id = lc.base_capability_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
					on p.product_id = pl.product_id
			where p.product_type_id = 1 and
					p.license_keycode_type_id = @license_keycode_type_id and
					p.uses_keycode = 1 and
					pl.product_line_id = @product_line_id and
					c.license_category_id = @license_category_id and 
					y.years = @years and
					pc.capability_activation_days = @trial_days
			end
		else
			begin
			select @product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
					on p.product_id = pl.product_id
			where p.product_type_id = 1 and
					p.license_keycode_type_id = @license_keycode_type_id and
					p.uses_keycode = 1 and
					pl.product_line_id = @product_line_id and
					c.license_category_id = @license_category_id and 
					y.years = @years
			end
			
	-- 1.5) @pricing_level
	if @pricing_level is null or @pricing_level = ''
		begin
			select @pricing_level = 'retail'
		end

	--select cart_discount_id = @cart_discount_id, cart_type_id = @cart_type_id, product_line_id = @product_line_id, license_category_id = @license_category_id, product_id = @product_id, cart_discount_type_id = @cart_discount_type_id, cart_discount_method_id = @cart_discount_method_id
	--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) standard product
		if @product_id is not null
			begin
				declare @product_set table(product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

				insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
				select p.product_id, p.product_description, 
					quantity = @license_seats, 
					retail_price = case
										when @pricing_level = 'retail' then pp.retail_price
										when @pricing_level = 'edu_nfp' then pp.edu_nfp_price
										when @pricing_level = 'govt' then pp.govt_price
										else pp.retail_price
									end,
					upgrade_price = case
										when @pricing_level = 'retail' then pp.retail_price
										when @pricing_level = 'edu_nfp' then pp.edu_nfp_price
										when @pricing_level = 'govt' then pp.govt_price
										else pp.retail_price
									end,
					discount = 0, 
					p.product_type_id, lc.license_category_name, @license_seats, y.years,
					cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
				from product p		
				left join product_pricing pp
					on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
				left join currency cu
					on pp.currency_id = cu.currenc
y_id
				left join product_license_category c
					on p.product_id = c.product_id
				left join license_category lc
					on c.license_category_id = lc.license_category_id
				left join product_years y
					on p.product_id = y.product_id
				where p.product_id = @product_id
			end

		-- 2.2) module product
		if @module_json is not null 
			begin
				declare @module_products table (license_module_code varchar(50), module_seats int)
	
				insert into @module_products (license_module_code, module_seats)
				select license_module_code, p.module_seats
				from (select row_id = parent_ID, parameter_name = NAME, input_value = case when StringValue = '' then null else StringValue end
					from dbo.fn_parse_json(@module_json) 
					where Object_ID is null and StringValue is not null) j 
				pivot (max(input_value) for parameter_name in (license_module_code, module_seats)) as p
				
				insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,product_type_id,license_category_name,seats,years,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
				select p.product_id,p.product_description,
						quantity=m.module_seats,
						retail_price = case
										when @pricing_level = 'retail' then pp.retail_price
										when @pricing_level = 'edu_nfp' then pp.edu_nfp_price
										when @pricing_level = 'govt' then pp.govt_price
										else pp.retail_price
									end,
					upgrade_price = case
										when @pricing_level = 'retail' then pp.retail_price
										when @pricing_level = 'edu_nfp' then pp.edu_nfp_price
										when @pricing_level = 'govt' then pp.govt_price
										else pp.retail_price
									end,
					discount = 0, 
					p.product_type_id, lc.license_category_name, m.module_seats, y.years,
					cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
				from @module_products m
				inner join license_module lm
					on lm.license_module_code = m.license_module_code
				inner join product_license_module pm
					on pm.license_module_id = lm.license_module_id
				inner join product p
					on p.product_id = pm.product_id
				left join product_pricing pp
					on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
				left join currency cu
					on pp.currency_id = cu.currency_id
				left join product_license_category c
					on p.product_id = c.product_id
				left join license_category lc
					on c.license_category_id = lc.license_category_id
				left join product_years y
					on p.product_id = y.product_id
				where pm.license_module_type_id = 19
			end


		-- select * from @product_set
		--return

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Apply discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 3.0) get cart_discount if @cart_discount_id is null or 0
		if (@cart_discount_id is null or @cart_discount_id = 0) and (@cart_discount_method_id <> 2 or @cart_discount_method_id is null)
			begin
			
			select @cart_discount_id = (select top 1 i.cart_discount_id
										from @product_set s
										left join cart_discount_item i
											on low_range <= @license_seats and @license_seats < high_range and s.product_type_id = i.product_type_id and i.license_category_name = @license_category_name and i.cart_discount_method_id = 3
										left join cart_discount d
											on i.cart_discount_id = d.cart_discount_id
										where d.cart_discount_status_id = 1 and d.cart_discount_type_id = 4
										order by i.discount desc)
			end
		
		
		-- 3.1) update product set with discounts
		if (@cart_discount_method_id <> 2 or @cart
_discount_method_id is null)
			begin
			update @product_set
			set standard_discount = case
								when s.currency_code = 'JPY' and i.cart_discount_method_id = 1 then round(convert(money,i.discount)* (s.retail_price/(select sum(retail_price) from @product_set)),0)
								when s.currency_code = 'JPY' and i.cart_discount_method_id = 3 then round((s.retail_price/s.years) - ((1.00 - i.discount/100) * (s.retail_price/s.years)),0)*s.years
								when s.currency_code <> 'JPY' and i.cart_discount_method_id = 1 then round(convert(money,i.discount)* (s.retail_price/(select sum(retail_price) from @product_set)),2)
								when s.currency_code <> 'JPY' and i.cart_discount_method_id = 3 then round((s.retail_price/s.years) - ((1.00 - i.discount/100) * (s.retail_price/s.years)),2)*s.years
								else s.discount
						end
			from @product_set s
			left join cart_discount_item i
				on i.cart_discount_id = @cart_discount_id and low_range <= @license_seats and @license_seats < high_range and s.product_type_id = i.product_type_id
			left join cart_discount d
				on i.cart_discount_id = d.cart_discount_id
			end

		--select supplemental_cart_discount_id = @supplemental_cart_discount_id, cart_discount_id = @cart_discount_id

		-- 3.2) @supplemental_cart_discount_id
		if @supplemental_cart_discount_id is not null and (@cart_discount_method_id <> 2 or @cart_discount_method_id is null)
			begin
				update @product_set
				set discount =  case
								when i.cart_discount_method_id = 3 then round(((convert(float,i.discount)/100) * (s.retail_price-s.standard_discount)),2)
								else s.discount
					end,
					cart_discount_id = @supplemental_cart_discount_id
				from @product_set s
				left join cart_discount_item i
					on i.cart_discount_id = @supplemental_cart_discount_id
				left join cart_discount_item_discount id
					on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
				left join cart_discount d
					on i.cart_discount_id = d.cart_discount_id
			end

		-- 3.3) fixed price
		if @cart_discount_method_id = 2
			begin
				declare @retail_price money

				select @retail_price = discount * @years
				from cart_discount_item
				where cart_discount_id = @cart_discount_id

				update @product_set
				set retail_price = @retail_price, upgrade_price = @retail_price,
					cart_discount_id = @cart_discount_id
				 
			end
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) Return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
--		select product_id, product_description, quantity, retail_price, upgrade_price = retail_price - (discount+standard_discount), discount, standard_discount, net_price = retail_price -(discount+standard_discount), product_type_id, license_category_name, seats, years, p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id
--		from @product_set

		select product_id, 
				product_description,
				retail_price = retail_price * quantity, 
				upgrade_price = (retail_price - (discount+standard_discount)) * quantity, 
				discount = discount * quantity, 
				standard_discount = standard_discount * quantity, 
				net_price = (retail_price - (discount+standard_discount)) * quantity, 
				product_type_id, license_category_name, seats, years, p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id
		from @product_set

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec
 usp_LogError @ErrorDB = @DBName
		
	end catch;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_new_product_set_INT]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_new_product_set_INT]

(
	@license_category_name varchar(10), 
	@license_seats int,
	@storage_gb int,
	@years int,
	@language_code varchar(2),
	@location_code varchar(3),
	@cart_discount_id int = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2010-01-18	esmart		Initial creation
	2010-09-07	esmart		Add support for WW products
	2012-05-02	esmart		WSA support
	2012-11-02	esmart		webroote site support
	2012-12-09	esmart		add offer support
	2013-03-05	esmart		site_id offer 

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_category_id tinyint,
			@product_id int,
			@product_storage_gb int,
			@storage_product_id int,	
			@product_family_id int,
			@product_line_id int,
			@dr_site_id varchar(20),
			@cart_type_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_category_id
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name

	-- 1.2) product_family_id
		--if @license_category_id in (10)
		--	begin
		--	select @product_family_id = 32
		--	end		
		--else 
		--	begin
		--	select @product_family_id = 2
		--	end
			
	if @cart_type_id is null
			begin
			select @cart_type_id = 1
			end	
			
		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code and
			cart_type_id = @cart_type_id

	-- 1.3) select product
		select @product_id = p.product_id
		from product p
		inner join product_license_category c
			on p.product_id = c.product_id
		inner join product_seat s
			on p.product_id = s.product_id
		inner join product_years y
			on p.product_id = y.product_id
		inner join product_line_product pl
			on p.product_id = pl.product_id
		where p.product_type_id = 1 and
				--p.product_family_id = @product_family_id and
				pl.product_line_id = @product_line_id and
				p.uses_keycode = 1 and
				c.license_category_id = @license_category_id and 
				s.seats = @license_seats and
				y.years = @years 

	-- 1.4) select storage_gb for product
		select @product_storage_gb = storage_gb
		from product_storage
		where product_id = @product_id

		if @product_storage_gb < @storage_gb
			begin
			select @storage_product_id = p.product_id
			from product_storage s
			inner join product p
				on s.product_id = p.product_id
			inner join product_years y
				on s.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where	--p.product_family_id = @product_family_id and 
					pl.product_line_id = @product_line_id and
					storage_gb = @storage_gb and 
					current_storage_gb = @product_storage_gb and
					y.years = @years 
			end		

		-- 1.5) @dr_site_id
		if @location_code = 'JPN'
			begin
			select @dr_site_id = 'webrootj'
			end
		else
			begin
			select @dr_site_id = 'webroote'
			end

		--select license_category_id = @license_category_id, product_id = @product_id, product_storage_gb = @product_storage_gb, storage_product_id = @storage_product_id 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- -----
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @product_set table (product_id int, product_description varchar(100), dr_product_id int, product_type_id int, dr_product_name varchar(150), retail_price money, currency varchar(20), language_code varchar(2), location_code varchar(3), currency_code varchar(3), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), locale varchar(10))
	
		-- 2.1) new product
		if @location_code = 'JPN'
			begin
				insert into @product_set(product_id, product_description, dr_product_id, product_type_id, retail_price, currency, language_code, location_code)
				select p.product_id, p.product_description, d.dr_product_id, p.product_type_id, d.retail_price, d.currency, d.language_code, d.location_code
				from product p
				inner join dr_product_price d
					on p.product_id = d.product_id and language_code = @language_code and location_code = @location_code
				where p.product_id = @product_id

				update @product_set 
				set symbol_html = c.symbol_html, symbol_utf8 = c.symbol_utf8, symbol_text = c.symbol_text, currency_code = c.currency_code, locale = cl.dr_locale
				from currency c
				inner join currency_language_location cl
					on c.currency_id = cl.currency_id
				where c.currency_code = 'JPY'
			end
		else
			begin
				insert into @product_set(product_id, product_description, dr_product_id, product_type_id, retail_price, currency, language_code, location_code, currency_code, symbol_html, symbol_utf8, symbol_text, locale)
				select p.product_id, p.product_description, dr_product_id = dp.dr_variation_product_id, p.product_type_id, d.retail_price, currency = c.currency_description, d.language_code, d.location_code, c.currency_code, c.symbol_html, c.symbol_utf8, c.symbol_text, cl.dr_locale
				from product p
				inner join product_pricing d
					on p.product_id = d.product_id and d.language_code = @language_code and d.location_code = @location_code
				inner join currency c
					on d.currency_id = c.currency_id
				inner join currency_language_location cl
					on d.language_code = cl.language_code and d.location_code = cl.location_code
				inner join dr_product dp
					on p.product_id = dp.product_id
				where p.product_id = @product_id and dp.autorenewal = 'ON'
			end

		
		-- 2.2) storage product
		--insert into @product_set(product_id, product_description, dr_product_id, product_type_id, retail_price, currency, language_code, location_code)
		--select p.product_id, p.product_description, d.dr_product_id, p.product_type_id, retail_price = d.retail_price, d.currency, d.language_code, d.location_code
		--from product p
		--inner join dr_product_price d
		--	on p.product_id = d.product_id and language_code = @language_code and location_code = @location_code
		--where p.product_id = @storage_product_id --and d.start_months = 12


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @dr_offer_id bigint

		if @cart_discount_id is not null and @cart_discount_id <> 0
			begin
			select @dr_offer_id = d.dr_offer_id
			from dr_offer_cart_discount d
			inner join dr_offer o
				on d.dr_offer_id = o.dr_offer_id
			where d.cart_discount_id = @cart_discount_id and o.site_id = @dr_site_id
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) result
	-- ----------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------
	
		-- 4.1) return result set
		select product_id, product_description, dr_product_id, product_type_id,  
			retail_price = case
								when currency = 'yen' then convert(money,round((retail_price * 1.05),0))
								else retail_price
							end,
			currency, language_code, location_code, symbol_html, symbol_utf8, symbol_text,
			DR_cart_url = case
							when @dr_offer_id is null then 'https://store.webroot.com/store/'+@dr_site_id+'/'+ locale + '/buy/productID.' + convert(varchar(20),dr_product_id) + '/currency.'+ currency_code
							else 'https://store.webroot.com/store/'+@dr_site_id+'/'+ locale + '/buy/productID.' + convert(varchar(20),dr_product_id) + '/currency.'+ currency_code + '/OfferID.' + convert(varchar(20),@dr_offer_id)
						end 
		from @product_set
		order by product_type_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;	

GO
