CREATE PROCEDURE [dbo].[usp_cart_select_order_code_prefix]

AS


/*	
	DATE			AUTHOR		REMARKS
	2017-02-27		acoffel		Initial creation.
		

	DESCRIPTION
	dish license lookup
	
