-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_order_item_options]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_order_item_options]
(
    @cart_order_id INT = NULL,
    @cart_order_in_process_id INT = NULL,
    @cart_item_bundle_id INT = NULL,
    @cart_discount_method_id TINYINT = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2014-07-21	esmart		Change default discount method
	2014-08-01	esmart		Add CD product
	2017-10-06	acoffel		fix years bug
    2023-26-06  msoni       Removing the storage_gb option for WSAV
	2025-05-20	mgolla		US-4428854 Added code in section 2.7 to retrieve data center names for EDR/MDR.

	DESCRIPTION
	select seat, year, storage, license_category,vault name and discounts for item
*/

AS
SET NOCOUNT ON

DECLARE @language_code VARCHAR(2),
        @location_code VARCHAR(3),
        @license_category_id TINYINT,
        @product_line_id INT,
        @product_type_id INT,
        @cart_discount_id INT,
        @storage_gb INT,
        @seat_list VARCHAR(50),
        @years_list VARCHAR(200),
        @storage_gb_list VARCHAR(200),
        @license_category_list VARCHAR(100),
        @cart_discount_list NVARCHAR(200),
        @keycode_type_list VARCHAR(200),
        @pricing_level_list VARCHAR(200),
        @cd_product_id INT,
        @locale VARCHAR(5),
        @response_code INT,
        @message VARCHAR(100),
        @vault_name VARCHAR(50)      
        

BEGIN TRY

    DECLARE @license_categories_to_load_vault TABLE
    (
        license_category_id INT
    )

    DECLARE @item_summary TABLE
    (
        cart_item_bundle_id INT,
        product_family_id INT,
        product_line_id INT,
        cart_order_item_in_process_id INT,
        product_id INT,
        keycode VARCHAR(40),
        product_type_id INT,
        max_product_type_id INT,
        current_license_category_id INT,
        license_category_id INT,
        current_seats INT,
        seats INT,
        current_storage_gb INT,
        storage_gb INT,
        quantity INT,
        years FLOAT,
        retail_price MONEY,
        net_price MONEY,
        discount MONEY,
        standard_discount MONEY,
        cart_discount_id INT
    )

    --------------------- APP CONFIG ------------------
	--Fetching EDR/MDR license category id's with existing app config key's.

    INSERT INTO @license_categories_to_load_vault
    (
        license_category_id
    )
    SELECT 	
           lc.license_category_id
    FROM [dbo].[fn_app_config_select_key_values]('PILLR_MODULE_TEMPLATES', 'PILLR') f
        INNER JOIN dbo.license_category AS lc
            ON lc.license_category_name = f.[key]
	-- Getting Primary License category of the modules
	INSERT INTO @license_categories_to_load_vault
	(
	    license_category_id
	)
	SELECT 
	       plcu.license_category_id
	FROM dbo.product_license_category_upgrade AS plcu
	    JOIN @license_categories_to_load_vault AS pm
	        ON pm.license_category_id = plcu.upgrade_license_category_id
	    LEFT JOIN @license_categories_to_load_vault AS pm2
	        ON pm2.license_category_id = plcu.license_category_id
	WHERE pm2.license_category_id IS NULL



    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) @cart_order_in_process_id 
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF @cart_order_in_process_id IS NOT NULL
    BEGIN
        -- 1.1) new product that can be bundled

        INSERT INTO @item_summary
        (

            cart_item_bundle_id,
            product_family_id,
            product_line_id,
            cart_order_item_in_process_id,
            product_type_id,
            max_product_type_id,
            current_license_category_id,
            license_category_id,
            current_seats,
            seats,
            current_storage_gb,
            storage_gb,
            quantity,
            years,
            retail_price,
            net_price,
            discount,
            standard_discount,
            cart_discount_id
        )
        SELECT i.cart_item_bundle_id,
               p.product_family_id,
               plp.product_line_id,
               cart_order_item_in_process_id = MIN(i.cart_order_item_in_process_id),
               product_type_id = MIN(p.product_type_id),
               max_product_type_id = MAX(p.product_type_id),
               current_license_category_id = MIN(plc.current_license_category_id),
               license_category_id = MAX(plc.license_category_id),
               current_seats = MIN(s.current_seats),
               seats = MAX(s.seats),
               current_storage_gb = MIN(ps.storage_gb),
               storage_gb = MAX(ps.storage_gb),
               quantity = SUM(i.quantity),
               years = MAX(y.years),
               retail_price = SUM(i.retail_price),
               net_price = SUM(i.net_price),
               discount = SUM(i.discount),
               standard_discount = SUM(i.standard_discount),
               cart_discount_id = MAX(i.cart_discount_id)
        FROM cart_order_item_in_process i WITH (NOLOCK)
            INNER JOIN product p WITH (NOLOCK)
                ON i.product_id = p.product_id
            INNER JOIN product_line_product plp WITH (NOLOCK)
                ON p.product_id = plp.product_id
            LEFT JOIN product_license_category plc WITH (NOLOCK)
                ON i.product_id = plc.product_id
            LEFT JOIN license_category lc WITH (NOLOCK)
                ON plc.license_category_id = lc.license_category_id
            LEFT JOIN product_years y WITH (NOLOCK)
                ON i.product_id = y.product_id
            LEFT JOIN product_seat s WITH (NOLOCK)
                ON i.product_id = s.product_id
            LEFT JOIN product_storage ps WITH (NOLOCK)
                ON i.product_id = ps.product_id
            LEFT JOIN cart_order_item_license_in_process il WITH (NOLOCK)
                ON i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
        WHERE i.cart_order_in_process_id = @cart_order_in_process_id
              AND i.cart_item_bundle_id = @cart_item_bundle_id
              AND il.cart_order_item_license_in_process_id IS NULL
              AND p.product_family_id IN ( 1, 2, 30, 31, 50, 51, 55, 100, 200, 300 )
        GROUP BY i.cart_item_bundle_id,
                 p.product_family_id,
                 plp.product_line_id

        -- 1.2) renewal/upgrade products that can be bundled
        INSERT INTO @item_summary
        (
            cart_item_bundle_id,
            product_family_id,
            product_line_id,
            keycode,
            cart_order_item_in_process_id,
            product_type_id,
            max_product_type_id,
            current_license_category_id,
            license_category_id,
            current_seats,
            seats,
            current_storage_gb,
            storage_gb,
            quantity,
            years,
            retail_price,
            net_price,
            discount,
            standard_discount,
            cart_discount_id
        )
        SELECT i.cart_item_bundle_id,
               p.product_family_id,
               plp.product_line_id,
               l.keycode,
               cart_order_item_in_process_id = MIN(i.cart_order_item_in_process_id),
               product_type_id = MIN(p.product_type_id),
               max_product_type_id 
= MAX(p.product_type_id),
               current_license_category_id = MIN(plc.current_license_category_id),
               license_category_id = MAX(plc.license_category_id),
               current_seats = MIN(s.current_seats),
               seats = MAX(s.seats),
               current_storage_gb = MIN(ps.storage_gb),
               storage_gb = MAX(ps.storage_gb),
               quantity = MAX(i.quantity),
               years = MAX(y.years),
               retail_price = SUM(i.retail_price),
               net_price = SUM(i.net_price),
               discount = SUM(i.discount),
               standard_discount = SUM(i.standard_discount),
               cart_discount_id = MAX(i.cart_discount_id)
        FROM cart_order_item_in_process i WITH (NOLOCK)
            INNER JOIN product p WITH (NOLOCK)
                ON i.product_id = p.product_id
            INNER JOIN product_line_product plp WITH (NOLOCK)
                ON p.product_id = plp.product_id
            INNER JOIN product_family f WITH (NOLOCK)
                ON p.product_family_id = f.product_family_id
            LEFT JOIN product_license_category plc WITH (NOLOCK)
                ON i.product_id = plc.product_id
            LEFT JOIN license_category lc WITH (NOLOCK)
                ON plc.license_category_id = lc.license_category_id
            LEFT JOIN product_years y WITH (NOLOCK)
                ON i.product_id = y.product_id
            LEFT JOIN product_seat s WITH (NOLOCK)
                ON i.product_id = s.product_id
            LEFT JOIN product_storage ps WITH (NOLOCK)
                ON i.product_id = ps.product_id
            INNER JOIN cart_order_item_license_in_process il WITH (NOLOCK)
                ON i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
            INNER JOIN license l WITH (NOLOCK)
                ON il.keycode = l.keycode
        WHERE i.cart_order_in_process_id = @cart_order_in_process_id
              AND i.cart_item_bundle_id = @cart_item_bundle_id
              AND il.keycode <> ''
              AND p.product_family_id IN ( 1, 2, 30, 31, 50, 51, 55, 100, 200, 300 )
        GROUP BY i.cart_item_bundle_id,
                 p.product_family_id,
                 plp.product_line_id,
                 l.keycode

        --select * from @item_summary

        -- 1.3) get values
        SELECT @language_code = language_code,
               @location_code = location_code
        FROM cart_order_in_process
        WHERE cart_order_in_process_id = @cart_order_in_process_id

        SELECT @license_category_id = license_category_id,
               @product_line_id = product_line_id,
               @product_type_id = product_type_id,
               @cart_discount_id = cart_discount_id,
               @storage_gb = storage_gb
        FROM @item_summary


        -- 1.4) @cart_discount_method_id
        IF @cart_discount_id IS NOT NULL
        BEGIN
            SELECT @cart_discount_method_id = cart_discount_method_id
            FROM cart_discount_item
            WHERE cart_discount_id = @cart_discount_id
        END
        ELSE
        BEGIN
            IF @cart_discount_method_id IS NULL
            BEGIN
                SELECT @cart_discount_method_id = CASE
                                                      WHEN @product_line_id IN ( 55, 300 ) THEN
                                                          3
                                                      ELSE
                                                          1
                                                  END
            END
        END
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) get values @cart_order_id
    -- --------------------------------------------------------------------------
-------------------------------------------------------------------------------------------------------------------------

    IF @cart_order_id IS NOT NULL
    BEGIN
        -- 2.1) @locale
        SELECT @locale = co.locale
        FROM cart_order co
        WHERE co.cart_order_id = @cart_order_id

        -- 2.1.1) @language_code and @location_code
        SELECT @language_code = language_code,
               @location_code = location_code
        FROM dbo.fn_locale_to_lang_loc(@locale)

        -- 2.2) item values
        SELECT @license_category_id = MAX(plc.license_category_id),
               @product_line_id = MAX(plp.product_line_id),
               @product_type_id = MIN(p.product_type_id),
               @cart_discount_method_id = MAX(i.cart_discount_method_id)
        FROM cart_order_item i
            INNER JOIN product_license_category plc
                ON plc.product_id = i.product_id
            INNER JOIN product_line_product plp
                ON plp.product_id = i.product_id
            INNER JOIN product p
                ON p.product_id = i.product_id
        WHERE i.cart_order_id = @cart_order_id
              AND i.cart_item_bundle_id = @cart_item_bundle_id
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) get values 
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 2.1) @seat_list
    SELECT @seat_list = COALESCE(@seat_list + ', ', '') + CAST(CONVERT(VARCHAR(10), seats) AS VARCHAR(100))
    FROM product_license_category_seat
    WHERE license_category_id = @license_category_id
          AND seats IN
              (
                  SELECT DISTINCT
                         (s.seats)
                  FROM product_seat s
                      INNER JOIN product_license_category plc
                          ON s.product_id = plc.product_id
                      INNER JOIN license_category_product_line pl
                          ON plc.license_category_id = pl.license_category_id
                      INNER JOIN product_line_product plp
                          ON s.product_id = plp.product_id
                             AND pl.product_line_id = plp.product_line_id
                      INNER JOIN product p
                          ON s.product_id = p.product_id
                             AND p.product_lifecycle_id = 1
                             AND p.product_type_id = @product_type_id
                  WHERE plc.license_category_id = @license_category_id
                        AND pl.language_code = @language_code
                        AND pl.location_code = @location_code
                        AND pl.product_line_id = @product_line_id
              )

    -- 2.2) @years_list
    SELECT @years_list
        = COALESCE(@years_list + ', ', '')
          + CAST(years_description + '|' + CONVERT(VARCHAR(10), years) AS VARCHAR(100))
    FROM product_license_category_years
    WHERE license_category_id = @license_category_id
          AND years IN
              (
                  SELECT DISTINCT
                         (y.years)
                  FROM product_years y
                      INNER JOIN product_license_category plc
                          ON y.product_id = plc.product_id
                      INNER JOIN license_category_product_line pl
                          ON plc.license_category_id = pl.license_category_id
                      INNER JOIN product_line_product plp
                          ON y.product_id = plp.product_id
                             AND pl.product_line_id = plp.product_line_id
                      INNER JOIN product p
                          ON y
.product_id = p.product_id
                             AND p.product_lifecycle_id = 1
                             AND p.product_type_id = @product_type_id
                  WHERE plc.license_category_id = @license_category_id
                        AND pl.language_code = @language_code
                        AND pl.location_code = @location_code
                        AND pl.product_line_id = @product_line_id
              )

    IF @product_type_id IN ( 2, 3 )
    BEGIN
        SELECT @years_list = '0|0,' + @years_list
    END

    /*  Remove WSAC Storage Options in CSI cart 

        ---- 2.3) @license_storage_list
        select @storage_gb_list = coalesce(@storage_gb_list+', ','')+ cast(convert(varchar(10),s.storage_gb) +' GB |'+convert(varchar(10),s.storage_gb) as varchar(100)) 
        from product_license_category_storage s
        where s.license_category_id = @license_category_id
    */


    -- 2.3) @license_category_list
    SELECT @license_category_list
        = COALESCE(@license_category_list + ', ', '')
          + CAST(c.license_category_name + '|' + CONVERT(VARCHAR(10), c.license_category_id) AS VARCHAR(100))
    FROM product_license_category_upgrade u
        INNER JOIN license_category_product_line pl
            ON u.upgrade_license_category_id = pl.license_category_id
               AND pl.language_code = @language_code
               AND pl.location_code = @location_code
        INNER JOIN license_category c
            ON u.upgrade_license_category_id = c.license_category_id
    WHERE u.license_category_id = @license_category_id
          AND u.language_code = @language_code
          AND u.location_code = @location_code
          AND pl.product_line_id = CASE
                                       WHEN @license_category_id = 1
                                            AND @product_line_id = 1 THEN
                                           100
                                       WHEN @license_category_id = 1
                                            AND @product_line_id = 6 THEN
                                           200
                                       ELSE
                                           pl.product_line_id
                                   END
          AND u.item_hierarchy_id = 1
    ORDER BY c.license_category_id

    -- 2.4) @cart_discount_list
    IF @cart_discount_method_id = 1
    BEGIN
        SELECT @cart_discount_list
            = COALESCE(@cart_discount_list + ', ', '')
              + CAST(ISNULL(symbol_utf8, '') + CONVERT(VARCHAR(10), id.discount) + '|'
                     + CONVERT(VARCHAR(10), i.cart_discount_id) AS NVARCHAR(100))
        FROM cart_discount_item_discount id
            INNER JOIN currency c
                ON id.currency_id = c.currency_id
            INNER JOIN cart_discount_item i
                ON id.cart_discount_item_id = i.cart_discount_item_id
            INNER JOIN cart_discount d
                ON i.cart_discount_id = d.cart_discount_id
                   AND d.cart_discount_description NOT LIKE 'Partner%'
        WHERE cart_discount_method_id = @cart_discount_method_id
              AND product_type_id = @product_type_id
              AND product_line_id = @product_line_id
              AND i.license_category_id IS NULL
              AND id.language_code = @language_code
              AND id.location_code = @location_code
              AND d.cart_discount_status_id = 1
        ORDER BY id.discount
    END
    ELSE IF @cart_discount_method_id = 3
    BEGIN
        SELECT @cart_discount_list
            = COALESCE(@cart_discount_list + ', ', '')
              + CAST(CONVERT(VARCHAR(10), i.discount) + '% |' + CONVERT(VARCHAR(10), i.cart_discount_id) AS NVARCHAR(100))
        FROM cart_discount_item i
            INNER JOIN cart_discount d
                ON i.cart_discount_id = d.cart_discount_id
                   AND d.cart_discount_description
 NOT LIKE 'Partner%'
        WHERE cart_discount_method_id = @cart_discount_method_id
              AND product_type_id = @product_type_id
              AND product_line_id = @product_line_id
              AND i.license_category_id IS NULL
              AND d.cart_discount_status_id = 1
        ORDER BY i.discount
    END

    -- 2.5) @keycode_type_list
    SELECT @keycode_type_list
        = COALESCE(@keycode_type_list + ', ', '')
          + CAST(t.license_keycode_type_description + '|' + CONVERT(VARCHAR(10), t.license_keycode_type_id) AS VARCHAR(100))
    FROM product_license_category_keycode_type l
        INNER JOIN license_keycode_type t
            ON l.license_keycode_type_id = t.license_keycode_type_id
    WHERE license_category_id = @license_category_id

    -- 2.6) @pricing_level_list
    IF @license_category_id IN ( 212, 220, 250, 55 )
    BEGIN
        SELECT @pricing_level_list
            = COALESCE(@pricing_level_list + ', ', '') + CAST(CONVERT(VARCHAR(10), pricing_level) AS NVARCHAR(100))
        FROM product_pricing_level
    END
    ELSE
    BEGIN
        SELECT @pricing_level_list = ''
    END

    -- 2.7) @vault_name
	--If the SAEP,EDR/MDR product is present in the cart, the vault will load.
	
    IF EXISTS (SELECT *
				FROM @license_categories_to_load_vault AS pm
				    JOIN dbo.product_license_category AS plc
				        ON plc.license_category_id = pm.license_category_id
				    JOIN dbo.cart_order_item AS coi
				        ON coi.product_id = plc.product_id
				WHERE coi.cart_order_id = @cart_order_id
				)
    BEGIN

      SELECT @vault_name
    = COALESCE(@vault_name + ', ', '')
      + SUBSTRING(t.vault_datacenter_name, CHARINDEX('-', t.vault_datacenter_name) + 1, LEN(t.vault_datacenter_name))
      + '|' + CONVERT(VARCHAR(10), t.vault_id)
	FROM
	(
	    SELECT DISTINCT
	           v.vault_datacenter_name,
	           vlc.vault_id
	    FROM @license_categories_to_load_vault AS pm
	        INNER JOIN dbo.vault_license_category AS vlc
	            ON vlc.license_category_id = pm.license_category_id
	        INNER JOIN dbo.vault AS v
	            ON v.vault_id = vlc.vault_id
	) AS t
	
    END

    -- 1.2.4) cd_product_id
    SELECT @cd_product_id = p.product_id
    FROM product p
        INNER JOIN product_license_category lc
            ON p.product_id = lc.product_id
    WHERE p.product_family_id = 8
          AND p.product_lifecycle_id = 1
          AND lc.license_category_id = @license_category_id

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) return results
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT seat_list = @seat_list,
           years_list = @years_list,
           storage_gb_list = @storage_gb_list,
           license_category_list = @license_category_list,
           cart_discount_list = @cart_discount_list,
           keycode_type_list = @keycode_type_list,
           pricing_level_list = @pricing_level_list,
           cd_product_id = @cd_product_id,
           vault = @vault_name

END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_order_page_details]
-- =============================================================================

CREATE procedure [dbo].[usp_cart_select_order_page_details]
(
	@product_line_list varchar(200),
	@language_code varchar(2) = null,
	@location_code varchar(3) = null,
	@product_line_cart_type varchar(20) = null,
	@cart_discount_method_name varchar(50) = null,
	@currency_code varchar(3)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2013-03-22	esmart		Add keycode type
	2014-08-01	esmart		Add CD product
	2017-09-11	acoffel		Corrected join for years list
	2020-01-22	wbarton		Updated section 1.2.1 to build seat_list in numerical order
	2022-08-23	jberry		Updated section 1.5 to change sort order for Allstate products - AIP-64
	2022-08-31	abelenkiy	Added currency_code input; enhanced merchant selection to use new country_currency_merchant table (section 1.1)
							Enhanced error handling
	2022-09-08	gblandford	Removed site_id from distinct resultset to address duplicates - ALM-1730
							Added required sort_order column for distinct selection
	2023-08-14	jberry		ECOM-1642 - Adjusted section 1.5 to change sort order for new Allstate products
	2024-02-22	schindar	ECOM-3135 - Disable Ordering Through CSI After Zuora Migration


	DESCRIPTION
	Select products available on order form (www.webroot.com/en_US/buy).
*/

as
	begin try

	SET NOCOUNT ON				

	DECLARE	@message NVARCHAR(4000),
			@seat_list VARCHAR(50),
			@years_list VARCHAR(200), 
			@keycode_type_list VARCHAR(200),
			@cart_discount_list NVARCHAR(200),
			@pricing_level_list VARCHAR(200),
			@product_order_id INT,
			@total_order_set INT,
			@license_category_id INT,
			@product_line_id INT,
			@cart_discount_method_id TINYINT,
			@merchant_id VARCHAR(50),
			@cd_product_id INT

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @discount_method_id
	IF @cart_discount_method_name IS NULL
		BEGIN
			SELECT @cart_discount_method_id = cart_discount_method_id 
			FROM cart_discount_method 
			WHERE cart_discount_method_name = 'percent off'
		end
	else
		begin
			select @cart_discount_method_id = cart_discount_method_id 
			from cart_discount_method 
			where cart_discount_method_name = @cart_discount_method_name
		end

	-- 1.1) setup table
	declare @product_order table (product_order_id int identity(1, 1), license_category_id int, 
		license_category_name varchar(20), license_category_description varchar(100), seat_list varchar(50), 
		years_list varchar(200), keycode_type_list varchar(200), cart_discount_list nvarchar(200), 
		product_line_id int, product_line_cart_type varchar(20), merchant_id varchar(50), site_id varchar(20), 
		cd_product_id int, pricing_level_list varchar(200))

		IF (@language_code ='en' AND @location_code='USA')
		BEGIN
		SET @product_line_list=N'50, 55, 300'
		END

	insert into @product_order (license_category_id, license_category_name, license_category_description, 
		product_line_id, product_line_cart_type, merchant_id, site_id)
	select distinct c.license_category_id, c.license_category_name, c.license_category_description, 
		pl.product_line_id, l.product_line_cart_type, pm.merchant_id, pl.site_id 
	from license_category_product_line pl
		inner join license_category c
			on pl.license_category_id = c.license_category_id and c.status = 1
		inner join product_line l
			on pl.product_line_id = l.product_line_id
		inner join country_currency_merchant ccm
			on c
cm.license_category_id = pl.license_category_id
		inner join currency cu
			on cu.currency_id = ccm.currency_id
				and cu.currency_code = @currency_code
		inner join lu_countries lc
			on lc.country_id = ccm.country_id
				and lc.iso3 = @location_code
		inner join payment_merchant pm
			on pm.payment_merchant_id = ccm.payment_merchant_id
	where pl.product_line_id in ( select integer_value from dbo.fn_integer_string_to_table(@product_line_list) )
		  and c.license_category_id <> 110
		  and pl.language_code = @language_code
		  and pl.location_code = @location_code

	select @product_order_id= 1, @total_order_set = max(product_order_id) 
	from @product_order

	while @total_order_set >= @product_order_id
		begin
		---select @product_order_id
		select @license_category_id = license_category_id, @product_line_id = product_line_id, 
			@merchant_id = merchant_id 
		from @product_order 
		where product_order_id = @product_order_id

		-- 1.2.1) @seat_list
		select @seat_list = coalesce(@seat_list + ', ', '') + convert(varchar(10), plcs.seats)
		from product_license_category_seat plcs
		where license_category_id = @license_category_id
			and plcs.seats in (
			select s.seats
			from product_seat s
			inner join product_license_category plc
				on s.product_id = plc.product_id 
			inner join license_category_product_line pl
				on plc.license_category_id = pl.license_category_id
			inner join product_line_product plp
				on s.product_id = plp.product_id and pl.product_line_id = plp.product_line_id
			inner join product p
				on s.product_id = p.product_id and p.product_lifecycle_id = 1 and p.product_type_id = 1
			where plc.license_category_id = @license_category_id 
				and pl.language_code = @language_code 
				and pl.location_code = @location_code 
				and pl.product_line_id = @product_line_id)
		order by plcs.seats asc

		update @product_order set seat_list = @seat_list where product_order_id = @product_order_id
		select @seat_list = null

		-- 1.2.2) @years_list
		select @years_list = coalesce(@years_list+', ','') 
							+ cast(years_description 
							+ '|' 
							+ convert(varchar(10),years) as varchar(100)) 
		from product_license_category_years 
		where license_category_id = @license_category_id 
			and years in 
			(select distinct(y.years)
			from product_years y
			inner join product_license_category plc
				on y.product_id = plc.product_id 
			inner join license_category_product_line pl
				on plc.license_category_id = pl.license_category_id
			inner join product_line_product plp
				on y.product_id = plp.product_id and pl.product_line_id = plp.product_line_id
			inner join product p
				on y.product_id = p.product_id 
					and p.product_lifecycle_id = 1 
					and p.product_type_id = 1
			where plc.license_category_id = @license_category_id 
				and pl.language_code = @language_code 
				and pl.location_code = @location_code 
				and pl.product_line_id = @product_line_id)

		update @product_order set years_list = @years_list where product_order_id = @product_order_id
		select @years_list = null

		-- 1.2.3) @keycode_type_list
		select @keycode_type_list = coalesce(@keycode_type_list+', ','')
									+ cast(t.license_keycode_type_description 
									+'|'
									+ convert(varchar(10),t.license_keycode_type_id) as varchar(100)) 
		from product_license_category_keycode_type l
		inner join license_keycode_type t
			on l.license_keycode_type_id = t.license_keycode_type_id
		where license_category_id = @license_category_id 

		update @product_order set keycode_type_list = @keycode_type_list where product_order_id = @product_order_id
		select @keycode_type_list = null
		
		-- 1.2.3) @cart_discount_list
		if @cart_discount_method_name = 'total off' and @merchant_id <> 'digital_river'
			begin
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')
										+ cast(isnull(symbol_utf8,'')
										+ convert(varchar(10
),id.discount)
										+ '|'
										+ convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
			from cart_discount_item_discount id
			inner join currency c
				on id.currency_id = c.currency_id
			inner join cart_discount_item i
				on id.cart_discount_item_id = i.cart_discount_item_id
			inner join cart_discount d
				on i.cart_discount_id = d.cart_discount_id 
					and d.cart_discount_description not like 'Partner%'
			where cart_discount_method_id = @cart_discount_method_id 
				and product_type_id = 1 
				and product_line_id = @product_line_id 
				and i.license_category_id is null
				and id.language_code = @language_code 
				and id.location_code = @location_code 
				and d.cart_discount_status_id = 1
			order by id.discount
			end
		else if @cart_discount_method_name = 'percent off'
			begin
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')
										+ cast(convert(varchar(10),i.discount)
										+'% |'
										+convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
			from cart_discount_item i
			inner join cart_discount d
				on i.cart_discount_id = d.cart_discount_id 
					and d.cart_discount_description not like 'Partner%'
			where cart_discount_method_id = @cart_discount_method_id 
				and product_type_id = 1 
				and product_line_id = @product_line_id 
				and i.license_category_id is null 
				and d.cart_discount_status_id = 1
			order by i.discount
			end

		update @product_order 
		set cart_discount_list = @cart_discount_list 
		where product_order_id = @product_order_id
		
		select @cart_discount_list = null

		-- 1.2.4) cd_product_id
		select @cd_product_id = p.product_id
		from product p
		inner join product_license_category lc
			on p.product_id = lc.product_id 
		where p.product_family_id = 8 
			and p.product_lifecycle_id = 1 
			and lc.license_category_id = @license_category_id

		update @product_order 
		set cd_product_id = @cd_product_id 
		where product_order_id = @product_order_id
		
		select @cd_product_id = null

		-- 1.2.5) @pricing_level_list
		if @license_category_id in (212,220,250,55)
			begin
			select @pricing_level_list = coalesce(@pricing_level_list+', ','')
										+ cast(convert(varchar(10),pricing_level) as nvarchar(100)) 
			from product_pricing_level
			end
		else 
			begin
			select @pricing_level_list = ''
			end

		update @product_order 
		set pricing_level_list = @pricing_level_list 
		where product_order_id = @product_order_id
		
		select @pricing_level_list = null		

		select @product_order_id = @product_order_id + 1
		end
		

	-- 1.5) return results
	select
		distinct
		license_category_id, license_category_name, license_category_description, seat_list, years_list,
		keycode_type_list, cart_discount_list, pricing_level_list, product_line_id, merchant_id, 
		--site_id, 
		product_line_cart_type, cd_product_id
		, sort_order = ( case when license_category_id <= 120 then 1 
					when license_category_id in (136,140) then 2
					when license_category_id in (137,138,139) then 3 
					else 4
				end	)
	from @product_order
	where product_line_cart_type = case
										when @product_line_cart_type is null then product_line_cart_type
										else @product_line_cart_type 
									end 
		and years_list is not null

	order by ( case when license_category_id <= 120 then 1 
					when license_category_id in (136,140) then 2
					when license_category_id in (137,138,139) then 3 
					else 4
				end	),
			product_line_cart_type,
			license_category_id;

	end try

	begin catch

	declare	@error_severity int = error_severity(), @error_state int = error_state()
	set @message = 'product_line_list = ' + convert(varchar(20), isnull(@product_line_list, 'null')) 
				+ ', language_code = ' + convert(varchar(20), isnull(@language_code, 'null'))
				+ ', location_code = ' + convert(varchar(20), isnull(@location_code, 'null'))
				+ ', product_line
_cart_type = ' + convert(varchar(20), isnull(@product_line_cart_type, 'null'))
				+ ', cart_discount_method_name = ' + convert(varchar(20), isnull(@cart_discount_method_name, 'null'))
				+ ', currency_code = ' + convert(varchar(20), isnull(@currency_code, 'null'))
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state)

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, 
		ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, 
		@@servername, db_name(), suser_name()
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_partner_service_product]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_partner_service_product]

(
	@keycode varchar(40),
	@partner_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.
	2019-01-09	rvinoche	Support autobilling attributes living only in license_effective_object
	2019-03-01	esmart		Fix setting @license_attribute_id

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare	@product_type_id int,
			@product_line_id int,
			@partner_id int,
			@license_id int,
			@license_keycode_type_id int,
			@license_category_id int,
			@license_attribute_id int,
			@autobilling_attribute int,
			@site_id varchar(20),
			@response_code int,
			@message varchar(100)
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select @partner_id = partner_id
		from partner 
		where partner_key = @partner_key

		--select keycode = @keycode
		select @product_type_id = 3,
				@product_line_id = l.product_line_id,
				@license_category_id = lc.license_category_id,
				@license_keycode_type_id = l.license_keycode_type_id,
				@license_id = l.license_id
		from license l
		inner join license_category_license lcl
			on l.license_id = lcl.license_id
		inner join license_category lc
			on lcl.license_category_id = lc.license_category_id
		left join license_attribute_license al
			on al.license_id = l.license_id
		where l.keycode = @keycode

		select @autobilling_attribute = dbo.fn_license_select_effective_object_element(@license_id,@license_category_id,'license_attribute_license_value',getdate())

		select @license_attribute_id = license_attribute_id
		from license_attribute_license_value
		where license_attribute_license_value = @autobilling_attribute


		select @site_id = pa.site_id
		from partner_license_attribute pa
		where pa.partner_id = @partner_id and pa.license_category_id = @license_category_id and pa.license_attribute_id = @license_attribute_id and pa.license_attribute_license_value = @autobilling_attribute

		if @site_id is null
			begin
			select @site_id = site_id
			from partner_license_category_product_line
			where partner_id = @partner_id and license_category_id = @license_category_id and product_line_id = @product_line_id
			end

		-- select product_line_id = @product_line_id, site_id = @site_id, license_category_id = @license_category_id, license_attribute_license_value = @license_attribute_license_value

		select pp.partner_product_id 
		from partner_service_product pp
		inner join product p
			on p.product_id = pp.product_id
		inner join product_license_category plc
			on plc.product_id = p.product_id
		where pp.partner_id = @partner_id and 
			p.product_type_id = @product_type_id and 
			plc.license_category_id = @license_category_id and
			p.license_keycode_type_id = @license_keycode_type_id and
			pp.site_id = @site_id 
			and pp.license_attribute_license_value = @autobilling_attribute
			
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not select product'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_product_ext_types]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_product_ext_types]

(
		@product_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-07-08	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) build up table
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		declare @ext_type table (cart_item_in_process_ext_type_id tinyint, ext_type_name varchar(20), ext_type_value varchar(20))

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 1, ext_type_name = 'category', l.license_category_name 
		from product_license_category c
		inner join license_category l
			on c.license_category_id = l.license_category_id
		where product_id = @product_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 2, ext_type_name = 'seats', convert(varchar(20),seats)
		from product_seat
		where product_id = @product_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 3, ext_type_name = 'storage', convert(varchar(20),storage_gb)
		from product_storage
		where product_id = @product_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 4, ext_type_name = 'years', convert(varchar(20),years) 
		from product_years
		where product_id = @product_id

		insert into @ext_type(cart_item_in_process_ext_type_id, ext_type_name, ext_type_value)
		select cart_item_in_process_ext_type_id = 16, ext_type_name = 'product_line_id', convert(varchar(20),product_line_id) 
		from product_line_product
		where product_id = @product_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return results (return empty set if there are no product years)
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if (select cart_item_in_process_ext_type_id from @ext_type where cart_item_in_process_ext_type_id = 4) is not null
			begin
			select cart_item_in_process_ext_type_id, ext_type_name, ext_type_value
			from @ext_type t
			end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
