-- PROCEDURE: [dbo].[usp_cart_select_quote]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_quote]

(
	@cart_discount_message_id int = null,
	@user_name varchar(100) = null,
	@start_date datetime = null,
	@end_date datetime = null
	
)

/*	
	DATE		AUTHOR		REMARKS
	2015-02-27	esmart		Initial creation.
	2020-03-26	esmart		Remove redundent locale column

	DESCRIPTION
	Select cart quotes
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select m.cart_discount_message_id, 
		m.cart_discount_message_description, 
		cart_discount_message_key = convert(varchar(36),m.cart_discount_message_key), 
		m.message_type_id, 
		m.insert_date, 
		m.insert_by,
		c.cart_order_id, 
		c.vendor_order_code, 
		cc.first_name,
		cc.last_name,
		cc.company_name,
		cc.customer_email,
		c.total_amount, 
		c.sub_total_amount, 
		c.offer_amount, 
		c.tax_amount, 
		c.submission_date, 
		c.modified_date, 
		c.modified_by, 
		c.cart_order_status_id, 
		s.cart_order_status_description,
		c.currency_id, 
		c.locale,
		pm.merchant_id,
		cart_url = 'https://www.webroot.com/'+lower(right(c.locale,2))+'/'+lower(left(c.locale,2))+'/cart/update?key='+convert(varchar(36),m.cart_discount_message_key)
	from cart_discount_message m
	inner join message_type t
		on m.message_type_id = t.message_type_id
	inner join cart_discount_message_value v
		on m.cart_discount_message_id = v.cart_discount_message_id and v.message_value_type_id = 24
	inner join cart_order c
		on v.value_id = c.cart_order_id
	inner join cart_order_status s
		on c.cart_order_status_id = s.cart_order_status_id 
	left join cart_customer cc
		on c.cart_order_id = cc.cart_order_id and cc.customer_type_id = 1
	--inner join lu_countries lc
	--	on c.location_code = lc.iso3 
	left join payment_header h
		on h.cart_order_id = c.cart_order_id
	left join payment_merchant pm
		on pm.payment_merchant_id = h.payment_merchant_id
	where m.insert_by = case when @user_name is null then m.insert_by else @user_name end and
		m.cart_discount_message_id = case when @cart_discount_message_id is null then m.cart_discount_message_id else @cart_discount_message_id end and
		(m.insert_date > @start_date or @start_date is null) and
		(m.insert_date < @end_date or @end_date is null)
	order by cart_discount_message_id desc

	--select m.cart_discount_message_id, 
	--	m.cart_discount_message_description, 
	--	cart_discount_message_key = convert(varchar(36),m.cart_discount_message_key), 
	--	m.message_type_id, 
	--	m.insert_date, 
	--	m.insert_by,
	--	c.cart_order_in_process_id, 
	--	co.vendor_order_code, 
	--	cc.first_name,
	--	cc.last_name,
	--	cc.company_name,
	--	cc.customer_email,
	--	c.total_amount, 
	--	c.sub_total_amount, 
	--	c.offer_amount, 
	--	c.tax_amount, 
	--	c.submission_date, 
	--	c.locale, 
	--	c.last_modified_date, 
	--	c.last_modified_by, 
	--	c.cart_order_in_process_status_id, 
	--	s.cart_order_status_description,
	--	c.currency_id, 
	--	c.language_code, 
	--	c.location_code, 
	--	lc.iso,
	--	c.merchant_id,
	--	cart_url = 'https://www.webroot.com/'+lower(lc.iso)+'/'+lower(c.language_code)+'/cart/update?key='+convert(varchar(36),m.cart_discount_message_key)
	--from cart_discount_message m
	--inner join message_type t
	--	on m.message_type_id = t.message_type_id
	--inner join cart_discount_message_v
alue v
	--	on m.cart_discount_message_id = v.cart_discount_message_id and v.message_value_type_id = 14
	--inner join cart_order_in_process c
	--	on v.value_id = c.cart_order_in_process_id
	--inner join cart_order_status s
	--	on c.cart_order_in_process_status_id = s.cart_order_status_id 
	--inner join lu_countries lc
	--	on c.location_code = lc.iso3 
	--left join cart_order co
	--	on c.cart_order_in_process_id = co.cart_order_in_process_id
	--left join cart_order_customer_in_process cc
	--	on c.cart_order_in_process_id = cc.cart_order_in_process_id and cc.customer_type_id = 1
	--where m.insert_by = case when @user_name is null then m.insert_by else @user_name end and
	--	m.cart_discount_message_id = case when @cart_discount_message_id is null then m.cart_discount_message_id else @cart_discount_message_id end and
	--	(m.insert_date > @start_date or @start_date is null) and
	--	(m.insert_date < @end_date or @end_date is null)
		
	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_renewal_product_set]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_renewal_product_set]
(
    @keycode VARCHAR(40),
    @license_category_name VARCHAR(10),
    @license_seats INT,
    @storage_gb INT,
    @years FLOAT,
    @cart_discount_id INT = NULL,
    @language_code VARCHAR(2) = NULL,
    @location_code VARCHAR(3) = NULL,
    @cart_type_id TINYINT = NULL,
    @currency_id TINYINT = NULL,
    @product_type_id INT = NULL,
	@message_campaign_name VARCHAR(65)=NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2009-08-11	esmart		Initial creation.
	2010-07-21	esmart		WW support
	2010-09-17	esmart		Discounting rev
	2010-12-17	esmart		International pricing support
	2011-09-14	esmart		WSA related support
	2012-01-10	esmart		license_cart_discount support
	2012-02-01	esmart		product_line_module
	2012-06-01	esmart		lifetime product upgrade support
	2012-07-30	esmart		WSA 2013
	2012-08-28	esmart		license_autorenewal_cycle support
	2013-03-18	esmart		new discounting support
	2013-06-20	esmart		Fix issue with storage discounting
	2013-11-15	esmart		Correct discounting on module products and trial to full
	2014-05-16	mrobbins	Fix issue with years in temp table - changed from int to float
	2014-09-04	esmart		Fix issue with total off discount on renewal/upgrade
	2015-11-20	esmart		Fix issue with discount years overwriting @years
	2015-12-15	esmart		15 month renewal discount
	2016-01-05	esmart		Add support for upgrade only discounts
	2016-07-20	esmart		Add additional module function parameter
	2017-06-26	cnovac		Added @currency_id as an override to all lang/loc queries as an override for Cleverbridge auto-renewal
	2018-04-06	esmart		Allow for new products without trial
	2018-07-11	cnovac		Added @product_type_id override for WIFI
	2018-09-12	esmart		Remove AR years override
	2019-02-01	jnavarra	Force option to correct errant leading comma
	2021-01-13	jnavarra	Allow license_seats to remain unchanged if no keycode provided (section 1.2)
	2021-01-15	jnavarra	Update rounding precision (section 5.3)
	2024-02-07	singaravelam	ECOM-3118 for license distribution method code TTSB to Swapped license seats parameters (section 1.2).
	2024-03-11	singaravelam	ECOM-2565 Added zuora_product_pricing for renewal/upgrade products
	2024-11-12  psatish			US-3650782 Return the price from the Zuora_product_pricing table for Zuora keycodes regardless of customer location
	2024-12-30  psatish			US-4224198 Return the price from the Zuora_product_pricing table for non-zuora consumer keycodes
								with a USA location when a request is made through the interstitial cart
	DESCRIPTION

	DEPENDENCY
		usp_auto_renewal_message_select_output_file
		usp_cart_insert_cart_order_item
		usp_cart_insert_cart_order_item_in_process
		usp_cart_select_cart_standard_upsell
		usp_cart_select_configurator_pricing
		usp_cart_select_configurator_upsell
		usp_cart_select_license_configurator_pricing
		usp_cart_select_seat_enforcement_configurator
		usp_cart_update_cart_order_item
		usp_exact_target_message_select_output_file
		usp_license_update_license_sstowav
		usp_partner_service_insert_order_item
		usp_sfdc_select_next_license_message
	
*/

AS
SET NOCOUNT ON

SET CONCAT_NULL_YIELDS_NULL ON

DECLARE @response_code INT,
        @message VARCHAR(100),
        @license_category_id TINYINT,
        @product_id INT,
        @product_line_id INT,
        @product_storage_gb INT,
        @storage_product_id INT,
        @license_id INT,
        @current_license_category_name VARCHAR(10),
        @current_license_category_id TINYINT,
        @current_license_seats INT,
        @current_storage_gb INT,
        @current_subscription_cycle VARCHAR(50),
        @upgrade_product_id INT,
        @upgrade_product_storage_gb INT,
    
    @license_status_id INT,
        @months_remaining INT,
        @capability_expiration_date DATETIME,
        @capability_activation_days INT,
        @transaction_date DATETIME,
        @license_activated INT,
        @base_capability_id INT,
        @cart_discount_type_id INT,
        @license_module_list VARCHAR(MAX),
        @lifetime_product INT,
        @message_autorenewal_cycle_id TINYINT,
        @autorenewal_cycle FLOAT,
        @trial TINYINT,
        @suppress_discount TINYINT,
        @license_distribution_method_code VARCHAR(4),
        @PORTAL_CAMPAIGN_ID INT,
		@PORTAL_PRICING_CAMPAIGN_ID VARCHAR(10),
		@PORTAL_LOCATION_CODE VARCHAR(3),
		@portal_language_code VARCHAR(2),
		@zuora_license BIT=0,
		@interstitial_campaign_request BIT=0
		
DECLARE @APP_CONFIG TABLE
(
    [app_config_name] NVARCHAR(50),
    [key] NVARCHAR(50),
    [value] NVARCHAR(MAX)
)

DECLARE @PORTAL_DISTRIBUTION_METHOD TABLE
(
    portal_distribution_method_code VARCHAR(4)
)

SELECT @transaction_date = GETDATE(),
       @lifetime_product = 0


BEGIN TRY
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) validate inputs
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 1.1) select @license_id 
    SELECT @license_id = license_id,
           @product_line_id = product_line_id,
           @license_status_id = license_status_id,
           @license_distribution_method_code = ldm.license_distribution_method_code
    FROM license l
        JOIN dbo.license_distribution_method AS ldm
            ON ldm.license_distribution_method_id = l.license_distribution_method_id
    WHERE keycode = @keycode

    --if @license_id is null 	
    --	begin
    --		select @response_code = -100,
    --				@message = '@keycode ' + @keycode + ' is not valid'
    --		RAISERROR (@message, 11, 0)
    --	end

    IF @license_id IS NOT NULL
    BEGIN
        -- 1.1) select current license category
        SELECT @current_license_category_id = ISNULL(license_category_id, dbo.fn_GetLicenseCategoryId(@license_id))
        FROM license_category_license
        WHERE license_id = @license_id

        SELECT @current_license_category_id = CASE
                                                  WHEN @current_license_category_id IN ( 2 ) THEN
                                                      100
                                                  --when @current_license_category_id = 3 then 110
                                                  WHEN @current_license_category_id IN ( 3, 4, 110 ) THEN
                                                      120
                                                  ELSE
                                                      @current_license_category_id
                                              END

        SELECT @current_license_category_name = license_category_name
        FROM license_category
        WHERE license_category_id = @current_license_category_id

        -- 1.1.2) select current license seats
        SELECT @current_license_seats = license_seats
        FROM license_seat
        WHERE license_id = @license_id



        -- 1.1.3) get this for WIFI to be used below for upgrade path to see what their currect model is (annual or monthly)
        IF @license_category_name = 'WIFI'
        BEGIN
            SELECT @current_subscription_cycle = autorenewal_cycle_name
            FROM dbo.fn_license_select_license_profile(@license_id)
        END

    END


    -- 1.2) renewal discount that change 
    IF @cart_discount_id IS NOT NULL
    BEGIN
        SELECT @years = CASE
                            WHEN i.prod
uct_type_id <> 3
                                 AND i.years IS NOT NULL
                                 AND
                                 (
                                     i.years > @years
                                     OR @years IS NULL
                                 ) THEN
                                i.years
                            WHEN i.product_type_id = 3
                                 AND i.years IS NOT NULL
                                 AND @years IS NULL THEN
                                i.years
                            ELSE
                                @years
                        END,
               @license_category_name = CASE
                                            WHEN i.license_category_name IS NOT NULL THEN
                                                i.license_category_name
                                            ELSE
                                                @license_category_name
                                        END,
               @license_seats = CASE
                                    WHEN i.license_seats IS NOT NULL THEN
                                        i.license_seats
                                    WHEN @license_distribution_method_code = 'TTSB' THEN
                                        ISNULL(@license_seats, @current_license_seats)
                                    ELSE
                                        ISNULL(@current_license_seats, @license_seats)
                                END
        FROM cart_discount_item i
        WHERE i.cart_discount_id = @cart_discount_id
    END

    -- 1.2) select @license_category_id
    SELECT @license_category_id = CASE
                                      WHEN license_category_id = 2 THEN
                                          100
                                      --when license_category_id = 3 then 110
                                      WHEN @current_license_category_id IN ( 3, 4, 110 ) THEN
                                          120
                                      ELSE
                                          license_category_id
                                  END
    FROM license_category
    WHERE license_category_name = @license_category_name

    -- 1.3) @current_license_seats
    IF @current_license_seats IS NULL
       OR @current_license_seats = 1
    BEGIN
        SELECT @current_license_seats = MIN(seats)
        FROM product_license_category_seat
        WHERE license_category_id = @current_license_category_id
    END

    -- 1.4) @current_license_seats
    IF @license_seats IS NULL
       OR @license_seats = 0
       OR @license_seats = 1
    BEGIN
        SELECT @license_seats = MIN(seats)
        FROM product_license_category_seat
        WHERE license_category_id = @license_category_id
    END

    -- 1.5) @years
    IF @years IS NULL --or @years = 0
    BEGIN
        SELECT @years = 1
    END

    -- 1.4) @license_storage
    IF @storage_gb IS NULL
       OR @storage_gb = 0
    BEGIN
        SELECT @storage_gb = MIN(storage_gb)
        FROM product_license_category_storage
        WHERE license_category_id = @license_category_id
    END

    -- 1.5) product_line_id
    IF @cart_type_id IS NULL
    BEGIN
        SELECT @cart_type_id = 1
    END

	 ---1.5.1) get portal distribution code and campaign id
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values](NULL, 'PORTAL') f

    INSERT INTO @PORTAL_DISTRIBUTION_METHOD
    (
        portal_distribution_method_code
    )
    SELECT ac.[key]
    FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] = 'PORTAL_DISTI_CODES'

    SELECT @PORTAL_PRICING_CAMPAIGN_ID = ac.[key]
    FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] =
 'PORTAL_PRICING_CAMPAIGN_ID'

	SET @PORTAL_CAMPAIGN_ID = @PORTAL_PRICING_CAMPAIGN_ID

	SELECT @PORTAL_LOCATION_CODE=[key]
	FROM @APP_CONFIG AS ac
    WHERE ac.[app_config_name] = 'PORTAL_LOCATION_CODE'

	SELECT @portal_language_code=language_code
    FROM dbo.currency_language_location
	WHERE location_code=@PORTAL_LOCATION_CODE

	IF EXISTS
	(
		SELECT 1
		FROM @PORTAL_DISTRIBUTION_METHOD
		WHERE portal_distribution_method_code = @license_distribution_method_code
	)
	BEGIN
		SELECT @location_code = @PORTAL_LOCATION_CODE,
			   @language_code = @portal_language_code,
			   @zuora_license = 1
	END
	--Ends

    SELECT @product_line_id = product_line_id
    FROM license_category_product_line
    WHERE license_category_id = @license_category_id
          AND language_code = @language_code
          AND location_code = @location_code
          AND cart_type_id = @cart_type_id

    -- 1.6) get base capability_id
    SELECT @base_capability_id = base_capability_id
    FROM license_category
    WHERE license_category_id = @current_license_category_id

    -- 1.6.1) get license_capability days
    SELECT @capability_activation_days = capability_activation_days
    FROM license_capability
    WHERE license_id = @license_id
          AND capability_id = @base_capability_id

    -- 1.6.2) get remaining months on license
    IF @license_status_id = 0
       AND @capability_activation_days > 0
    BEGIN
        SELECT @capability_expiration_date = DATEADD(dd, capability_activation_days, @transaction_date),
               @license_activated = CASE
                                        WHEN capability_expiration_date IS NULL THEN
                                            0
                                        ELSE
                                            1
                                    END
        FROM license_capability
        WHERE license_id = @license_id
              AND capability_id = @base_capability_id
    END
    ELSE
    BEGIN
        SELECT @capability_expiration_date = capability_expiration_date,
               @license_activated = CASE
                                        WHEN capability_expiration_date IS NULL THEN
                                            0
                                        ELSE
                                            1
                                    END
        FROM license_capability
        WHERE license_id = @license_id
              AND capability_id = @base_capability_id
    END

    IF @license_status_id = 1
       AND @license_activated = 0
       AND @capability_activation_days > 0
    BEGIN
        SELECT @capability_expiration_date = DATEADD(dd, capability_activation_days, @transaction_date)
        FROM license_capability
        WHERE license_id = @license_id
              AND capability_id = @base_capability_id
    END


    -- 1.7) alternative discounts
    -- 1.7.1) usp_cart_select_license_cart_discount
    IF @cart_discount_id IS NULL
       OR @cart_discount_id = 0
    BEGIN
        EXEC usp_cart_select_license_cart_discount @license_id,
                                                   @cart_discount_id OUTPUT
    END

    -- 1.7.2) usp_cart_select_campaign_cart_discount
    IF @cart_discount_id IS NULL
       OR @cart_discount_id = 0
    BEGIN
        EXEC usp_cart_select_campaign_cart_discount @license_id,
                                                    @cart_discount_id OUTPUT
    END

    -- 1.7.3) usp_cart_select_last_license_cart_discount -- disabled 4/8 after initial test
    --if @cart_discount_id is null or @cart_discount_id = 0
    --	begin
    --	exec usp_cart_select_last_license_cart_discount @license_id,@cart_discount_id output
    --	end

    --	1.8) @cart_discount_type_id
    SELECT @cart_discount_type_id = cart_discount_type_id,
           @suppress_discount = suppress_discount
    FROM cart_discount
    WHERE cart_discount_id 
= @cart_discount_id

    -- 1.9) @license_module_list
    SELECT @license_module_list = dbo.fn_license_module_license_key_value(@license_id, 1)

    IF @license_module_list IS NOT NULL
       AND @license_module_list LIKE '%lifetime%'
    BEGIN
        SELECT @lifetime_product = 1
    END

    -- 1.10) @message_autorenewal_cycle_id
    SELECT @message_autorenewal_cycle_id = m.message_autorenewal_cycle_id,
           @autorenewal_cycle = m.autorenewal_cycle
    FROM license_autorenewal_cycle c
        INNER JOIN message_autorenewal_cycle m
            ON c.message_autorenewal_cycle_id = m.message_autorenewal_cycle_id
    WHERE c.license_id = @license_id

    --if @autorenewal_cycle is not null and datediff(dd,getdate(),@capability_expiration_date) < 38 and datediff(dd,getdate(),@capability_expiration_date) > 30
    --	begin
    --	select @years = @autorenewal_cycle
    --	end	

    -- 1.11) trial
    SELECT @trial =
    (
        SELECT COUNT(*)
        FROM license_capability c WITH (NOLOCK)
        WHERE license_id = @license_id
              AND capability_id = @base_capability_id
              AND capability_type_id IN ( 2, 3 )
    )

    -- 1.11.1) if trial keycode make product_type new
    IF @product_type_id IS NULL
    BEGIN
        SELECT @product_type_id = CASE
                                      WHEN @trial = 0 THEN
                                          2
                                      ELSE
                                          1
                                  END
    END

    IF @keycode IS NULL
    BEGIN
        SELECT @product_type_id = 1
    END

    -- 1.11.2) 
    IF @product_type_id = 1
       AND
       (
           @cart_discount_id IS NULL
           OR @cart_discount_id = 0
       )
    BEGIN
        EXEC usp_cart_select_campaign_cart_discount_new @license_category_name,
                                                        @license_seats,
                                                        @storage_gb,
                                                        @years,
                                                        @language_code,
                                                        @location_code,
                                                        @product_line_id,
                                                        @cart_discount_id OUTPUT
    END

   
    --select lifetime_product = @lifetime_product
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) get upgrade and renewal products
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 2.1) if current category does not match new category get upgrade product
    IF (
           @license_category_id > @current_license_category_id
           OR @license_seats > @current_license_seats
       )
       AND @license_category_name != 'WIFI'
    BEGIN
        --select 'upgrade'
        -- 2.1.1) not liftime
        IF @lifetime_product = 0
           AND @trial = 0
        BEGIN
            SELECT @upgrade_product_id = p.product_id,
                   @upgrade_product_storage_gb = storage_gb
            FROM product p
                INNER JOIN product_license_category c
                    ON p.product_id = c.product_id
                INNER JOIN product_seat s
                    ON p.product_id = s.product_id
                INNER JOIN product_years y
                    ON p.product_id = y.product_id
                INNER JOIN product_line_product pl
                    ON p.product_id = pl.product_id
                LEFT JOIN product_storage ps
                    ON p.product_id = ps.product_id
       
     WHERE p.product_type_id = 3
                  AND pl.product_line_id = @product_line_id
                  AND p.uses_keycode = 1
                  AND c.license_category_id = @license_category_id
                  AND s.seats = @license_seats
                  AND c.current_license_category_id = @current_license_category_id
                  AND s.current_seats = @current_license_seats
                  AND p.product_lifecycle_id = 1
        END
        ELSE IF @trial = 0
        BEGIN
            SELECT @upgrade_product_id = p.product_id
            FROM product p
                INNER JOIN product_license_category c
                    ON p.product_id = c.product_id
                INNER JOIN product_seat s
                    ON p.product_id = s.product_id
                INNER JOIN product_years y
                    ON p.product_id = y.product_id
                INNER JOIN product_line_product pl
                    ON p.product_id = pl.product_id
                LEFT JOIN product_storage ps
                    ON p.product_id = ps.product_id
            WHERE p.product_type_id = 3
                  AND pl.product_line_id = @product_line_id
                  AND p.uses_keycode = 1
                  AND c.license_category_id = @license_category_id
                  AND s.seats = @license_seats
                  AND c.current_license_category_id = @current_license_category_id
                  AND s.current_seats = @current_license_seats
                  AND p.product_description LIKE '%lifetime%'
                  AND p.product_lifecycle_id = 1
        END
    END

    --added this piece of code because both Trial and non-Trial WIFI products share exactly same years
    --and needed a way to not pick the trial product as a new/renew
    IF @license_category_name = 'WIFI'
       AND @product_type_id != 3
    BEGIN
        SELECT @product_id = p.product_id
        FROM product p
            INNER JOIN product_license_category plc
                ON p.product_id = plc.product_id
            INNER JOIN product_seat ps
                ON p.product_id = ps.product_id
            INNER JOIN product_years py
                ON p.product_id = py.product_id
            INNER JOIN product_line_product plp
                ON p.product_id = plp.product_id
            INNER JOIN product_capability pc
                ON p.product_id = pc.product_id
        WHERE p.product_type_id = @product_type_id
              AND plp.product_line_id = @product_line_id
              AND p.uses_keycode = 1
              AND plc.license_category_id = @license_category_id
              AND ps.seats = @license_seats
              AND py.years = @years
              AND p.product_lifecycle_id = 1
              AND pc.capability_activation_days >= 30 --basically make sure it's not a trial
    END
    ELSE IF @license_category_name != 'WIFI'
    BEGIN
        -- 2.2.1) select renewal product
        SELECT @product_id = p.product_id
        FROM product p
            INNER JOIN product_license_category c
                ON p.product_id = c.product_id
            INNER JOIN product_seat s
                ON p.product_id = s.product_id
            INNER JOIN product_years y
                ON p.product_id = y.product_id
            INNER JOIN product_line_product pl
                ON p.product_id = pl.product_id
        WHERE p.product_type_id = @product_type_id
              AND pl.product_line_id = @product_line_id
              AND p.uses_keycode = 1
              AND c.license_category_id = @license_category_id
              AND s.seats = @license_seats
              AND y.years = @years
              AND p.product_lifecycle_id = 1
    END

    --added this piece of code because both Trial and non-Trial WIFI products share exactly same years
    --and needed a way to not pick the trial product as an upgrade
    IF @license_category_name = 'WIFI'
       AND @product_
type_id = 3
    BEGIN
        SELECT @upgrade_product_id = p.product_id
        FROM product p
            INNER JOIN product_license_category c
                ON p.product_id = c.product_id
            INNER JOIN product_seat s
                ON p.product_id = s.product_id
            INNER JOIN product_years y
                ON p.product_id = y.product_id
            INNER JOIN product_line_product pl
                ON p.product_id = pl.product_id
            INNER JOIN product_capability pc
                ON p.product_id = pc.product_id
            LEFT JOIN product_storage ps
                ON p.product_id = ps.product_id
        WHERE p.product_type_id = @product_type_id
              AND pl.product_line_id = @product_line_id
              AND p.uses_keycode = 1
              AND c.license_category_id = @license_category_id
              AND s.seats = @license_seats
              AND c.current_license_category_id = @current_license_category_id
              AND s.current_seats = @current_license_seats
              AND y.years = @years
              AND p.product_description LIKE '%' + IIF(@current_subscription_cycle = 'Monthly', 'Monthly', 'Year to')
                                             + '%'
              AND p.product_lifecycle_id = 1
              AND pc.capability_activation_days >= 30 --basically make sure it's not a trial
    END
    -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) get storage
    -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 3.1) get license information
    SELECT @current_storage_gb = ISNULL(s.storage_gb, 25)
    FROM license_storage s
    WHERE license_id = @license_id

    IF @current_storage_gb = 0
       OR @current_storage_gb IS NULL
       OR @current_storage_gb < 25
    BEGIN
        SELECT @current_storage_gb = 25
    END

    -- 3.1.1) if the license is being upgraded then the storage on the upgrade overrides the current storage on the license
    IF @upgrade_product_storage_gb > @current_storage_gb
    BEGIN
        SELECT @current_storage_gb = @upgrade_product_storage_gb
    END

    -- 3.1.2) @product_storage_gb
    SELECT @product_storage_gb = storage_gb
    FROM product_storage
    WHERE product_id = @product_id

    IF @product_storage_gb = 0
       OR @product_storage_gb IS NULL
    BEGIN
        SELECT @product_storage_gb = 25
    END

    -- 3.3) get remaining months on license
    SELECT @months_remaining = 0
    --select months_remaining = @months_remaining, @transaction_date, @capability_expiration_date

    --select datediff(hh,@transaction_date,@capability_expiration_date)
    IF DATEDIFF(hh, @transaction_date, @capability_expiration_date) > 24
    --if @capability_expiration_date >= @transaction_date
    BEGIN

        WHILE DATEADD(mm, @months_remaining, @transaction_date) <= @capability_expiration_date
        BEGIN
            SELECT @months_remaining = @months_remaining + 1
        END
        --select months_remaining = @months_remaining
        SELECT @months_remaining = CASE
                                       WHEN @months_remaining <= 1
                                            AND @capability_expiration_date IS NOT NULL THEN
                                           1
                                       WHEN @months_remaining <= 1
                                            AND @capability_expiration_date IS NULL THEN
                                           0
                                       ELSE
                                           @mo
nths_remaining - 1
                                   END
    END

    -- 3.4) check for best buy monthly subscribers and set months remaining = 12
    DECLARE @best_buy_monthly INT

    SELECT @best_buy_monthly = CASE
                                   WHEN COUNT(*) > 0 THEN
                                       1
                                   ELSE
                                       0
                               END
    FROM subscription
    WHERE license_id = @license_id
          AND subscription_type_id <> 2

    IF @best_buy_monthly = 1
    BEGIN
        SELECT @months_remaining = 12
    END

	--3.5 check if the request comes through the interstitial cart
	IF EXISTS
	(
		SELECT 1
		FROM @APP_CONFIG
		WHERE app_config_name = 'PORTAL_INTERSTITIAL_CAMPAIGNS'
			  AND [key] = @message_campaign_name
	)
	BEGIN
		SELECT @interstitial_campaign_request = 1,
			   @cart_discount_id = NULL

	END
    --select  product_line_id = @product_line_id,license_category_id = @license_category_id, current_license_category_id = @current_license_category_id,product_id = @product_id, product_storage_gb = @product_storage_gb, storage_product_id = @storage_product_id,current_license_seats = @current_license_seats,current_storage_gb = @current_storage_gb,upgrade_product_id = @upgrade_product_id,upgrade_product_storage_gb = @upgrade_product_storage_gb, months_remaining = @months_remaining,capability_expiration_date = @capability_expiration_date,years = @years,autorenewal_cycle = @autorenewal_cycle

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 4.) build product set
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    DECLARE @product_set TABLE
    (
        product_id INT,
        product_description VARCHAR(100),
        retail_price MONEY,
        upgrade_price MONEY,
        discount MONEY,
        standard_discount MONEY
            DEFAULT 0,
        product_type_id INT,
        license_category_name VARCHAR(10),
        seats INT,
        storage_gb INT,
        years FLOAT,
        p_type VARCHAR(20),
        currency_id TINYINT,
        currency_code CHAR(3),
        currency_description VARCHAR(20),
        symbol_html VARCHAR(10),
        symbol_utf8 NVARCHAR(10),
        symbol_text VARCHAR(10),
        cart_discount_id INT NULL
    )

    --		declare @product_set table(product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency varchar(20), cart_discount_id int)

    -- 4.1) upgrade product
    INSERT INTO @product_set
    (
        product_id,
        product_description,
        retail_price,
        upgrade_price,
        discount,
        standard_discount,
        product_type_id,
        license_category_name,
        seats,
        storage_gb,
        years,
        p_type,
        currency_id,
        currency_code,
        currency_description,
        symbol_html,
        symbol_utf8,
        symbol_text
    )
	SELECT DISTINCT
		   p.product_id,
		   product_description = CASE
									 WHEN pd.product_description IS NULL THEN
										 p.product_description
									 ELSE
										 pd.product_description
								 END,
		   retail_price = CASE
							  WHEN zpp.product_id IS NOT NULL THEN
								  zpp.retail_price
							  ELSE
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
						  END,
		   upgrade_price = CASE
							   WHEN zpp.product_id IS NOT NULL THEN
								   zpp.retail_price
							   WHE
N @lifetime_product = 1 THEN
								   COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)
							   WHEN @months_remaining <= 6
									AND @product_id IS NOT NULL THEN
								   0 -- Free upgrade with renewal
							   WHEN @months_remaining <= 6
									AND @months_remaining > 0
									AND @product_id IS NULL THEN
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) / 2
							   WHEN @months_remaining > 6
									AND @months_remaining <= 12 THEN
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
							   ELSE
								   ROUND(
											CONVERT(
													   MONEY,
													   @months_remaining
													   * ((COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) / 12)
												   ),
											2
										)
						   END,
		   discount = CASE
						  WHEN zpp.product_id IS NOT NULL THEN
							  zpp.discount
						  ELSE
							  0
					  END,
		   standard_discount = CASE
								   WHEN zpp.product_id IS NOT NULL THEN
									   zpp.discount
								   WHEN @lifetime_product = 1 THEN
									   0
								   WHEN @months_remaining <= 6
										AND @product_id IS NOT NULL THEN
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) -- Free upgrade with renewal
								   WHEN @months_remaining <= 6
										AND @months_remaining > 0
										AND @product_id IS NULL THEN
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) / 2
								   WHEN @months_remaining > 6
										AND @months_remaining <= 12 THEN
									   0
								   ELSE
		   (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
		   - ROUND(CONVERT(MONEY, @months_remaining * ((COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) / 12)), 2)
							   END,
		   p.product_type_id,
		   lc.license_category_name,
		   s.seats,
		   ISNULL(ps.storage_gb, 0),
		   y.years,
		   p_type = 'upgrade',
		   cu.currency_id,
		   cu.currency_code,
		   cu.currency_description,
		   cu.symbol_html,
		   cu.symbol_utf8,
		   cu.symbol_text
	FROM product p
		LEFT JOIN product_pricing pp
			ON p.product_id = pp.product_id
			   AND pp.language_code = @language_code
			   AND pp.location_code = @location_code
		LEFT JOIN product_pricing pp2
			ON p.product_id = pp2.product_id
			   AND pp2.currency_id = @currency_id
		LEFT JOIN product_description pd
			ON p.product_id = pd.product_id
			   AND pd.language_code = @language_code
			   AND pd.location_code = @location_code
		LEFT JOIN currency cu
			ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
		LEFT JOIN product_license_category c
			ON p.product_id = c.product_id
		LEFT JOIN license_category lc
			ON c.license_category_id = lc.license_category_id
		LEFT JOIN product_seat s
			ON p.product_id = s.product_id
		LEFT JOIN product_storage ps
			ON p.product_id = ps.product_id
		LEFT JOIN product_years y
			ON p.product_id = y.product_id
		LEFT JOIN dbo.zuora_product_pricing AS zpp
			ON zpp.product_id = p.product_id
			   AND zpp.campaign_id = @PORTAL_CAMPAIGN_ID
			   AND
			   (
				   @zuora_license = 1
				   OR
				   (
					   @interstitial_campaign_request = 1
					   AND @location_code = @PORTAL_LOCATION_CODE
				   )
			   )
	WHERE p.product_id = @upgrade_product_id
		  AND @months_remaining > 0

    -- 4.1) renewal product
    INSERT INTO @product_set
    (
        product_id,
        product_description,
        retail_price,
        upgrade_price,
        discount,
        standard_discount,
        product_type_id,
        license_category_name,
        seats,
        storage_gb,
        years,
        p_type,
        currency_id,
        currency_code,
        currency_description,
        symbol_html,
        symbol_utf8,
        symbol_text
    )
    SELECT DISTINCT
           p.product_id,
           product_description = CASE
                                     WHE
N pd.product_description IS NULL THEN
                                         p.product_description
                                     ELSE
                                         pd.product_description
                                 END,
           retail_price = CASE
                              WHEN zpp.product_id IS NOT NULL THEN
                                  zpp.renewal_price
                              ELSE
           (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
                          END,
           upgrade_price = CASE
                               WHEN zpp.product_id IS NOT NULL THEN
                                   zpp.renewal_price
                               ELSE
           (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
                           END,
           discount = CASE
                          WHEN zpp.product_id IS NOT NULL THEN
                              zpp.discount
                          ELSE
                              0
                      END,
           standard_discount = CASE
                                   WHEN zpp.product_id IS NOT NULL THEN
                                       zpp.discount
                                   ELSE
                                       0
                               END,
           p.product_type_id,
           lc.license_category_name,
           s.seats,
           ISNULL(ps.storage_gb, 0),
           y.years,
           p_type = 'renewal',
           cu.currency_id,
           cu.currency_code,
           cu.currency_description,
           cu.symbol_html,
           cu.symbol_utf8,
           cu.symbol_text
    FROM product p
        LEFT JOIN product_pricing pp
            ON p.product_id = pp.product_id
               AND pp.language_code = @language_code
               AND pp.location_code = @location_code
        LEFT JOIN product_pricing pp2
            ON p.product_id = pp2.product_id
               AND pp2.currency_id = @currency_id
        LEFT JOIN product_description pd
            ON p.product_id = pd.product_id
               AND pd.language_code = @language_code
               AND pd.location_code = @location_code
        LEFT JOIN currency cu
            ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
        LEFT JOIN product_license_category c
            ON p.product_id = c.product_id
        LEFT JOIN license_category lc
            ON c.license_category_id = lc.license_category_id
        LEFT JOIN product_seat s
            ON p.product_id = s.product_id
        LEFT JOIN product_storage ps
            ON p.product_id = ps.product_id
        LEFT JOIN product_years y
            ON p.product_id = y.product_id
        LEFT JOIN dbo.zuora_product_pricing AS zpp
            ON zpp.product_id = p.product_id
               AND zpp.campaign_id = @PORTAL_CAMPAIGN_ID
               AND
			   (
				   @zuora_license = 1
				   OR
				   (
					   @interstitial_campaign_request = 1
					   AND @location_code = @PORTAL_LOCATION_CODE
				   )
			   )
    WHERE p.product_id = @product_id

    -- 4.1) storage upgrade product
    IF @trial = 0
    BEGIN
        INSERT INTO @product_set
        (
            product_id,
            product_description,
            retail_price,
            upgrade_price,
            discount,
            standard_discount,
            product_type_id,
            license_category_name,
            seats,
            storage_gb,
            years,
            p_type,
            currency_id,
            currency_code,
            currency_description,
            symbol_html,
            symbol_utf8,
            symbol_text
        )
        SELECT DISTINCT
               p.product_id,
               product_description = CASE
                                         WHEN pd.product_description IS NULL THEN
                           
                  p.product_description
                                         ELSE
                                             pd.product_description
                                     END,
               retail_price = (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)),
               upgrade_price = ROUND(
                                        CONVERT(
                                                   MONEY,
                                                   @months_remaining
                                                   * ((COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) / 12)
                                               ),
                                        2
                                    ),
               discount = 0,
               standard_discount = (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
                                   - ROUND(
                                              CONVERT(
                                                         MONEY,
                                                         @months_remaining
                                                         * ((COALESCE(pp2.retail_price, pp.retail_price, p.retail_price))
                                                            / 12
                                                           )
                                                     ),
                                              2
                                          ),
               p.product_type_id,
               lc.license_category_name,
               s.seats,
               ISNULL(ps.storage_gb, 0),
               y.years,
               p_type = 'storage',
               cu.currency_id,
               cu.currency_code,
               cu.currency_description,
               cu.symbol_html,
               cu.symbol_utf8,
               cu.symbol_text
        FROM product p
            LEFT JOIN product_pricing pp
                ON p.product_id = pp.product_id
                   AND pp.language_code = @language_code
                   AND pp.location_code = @location_code
            LEFT JOIN product_pricing pp2
                ON p.product_id = pp2.product_id
                   AND pp2.currency_id = @currency_id
            LEFT JOIN product_description pd
                ON p.product_id = pd.product_id
                   AND pd.language_code = @language_code
                   AND pd.location_code = @location_code
            LEFT JOIN currency cu
                ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
            INNER JOIN product_line_product pl
                ON p.product_id = pl.product_id
            INNER JOIN product_storage ps
                ON p.product_id = ps.product_id
            LEFT JOIN product_license_category c
                ON p.product_id = c.product_id
            LEFT JOIN license_category lc
                ON c.license_category_id = lc.license_category_id
            LEFT JOIN product_seat s
                ON p.product_id = s.product_id
            LEFT JOIN product_years y
                ON p.product_id = y.product_id
        WHERE pl.product_line_id = @product_line_id
              AND current_storage_gb = @current_storage_gb
              AND storage_gb = @storage_gb
              AND (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) > 0
              AND @months_remaining > 0
              AND y.years IS NULL
              AND p.product_lifecycle_id = 1
    END

    -- 4.4) renewal storage product
    INSERT INTO @product_set
    (
        product_id,
        product_description,
        retail_price,
        upgrade_price,
        discount,
        standard_discount,
        product_type_id,
        license_category_name,
        seats,
        storage_gb,
        years,
        p_type,
        currency_id,
        currency_code,
        cur
rency_description,
        symbol_html,
        symbol_utf8,
        symbol_text
    )
    SELECT DISTINCT
           p.product_id,
           product_description = CASE
                                     WHEN pd.product_description IS NULL THEN
                                         p.product_description
                                     ELSE
                                         pd.product_description
                                 END,
           retail_price = (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)),
           upgrade_price = (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)),
           discount = 0,
           standard_discount = 0,
           p.product_type_id,
           lc.license_category_name,
           s.seats,
           ISNULL(ps.storage_gb, 0),
           y.years,
           p_type = 'renewal storage',
           cu.currency_id,
           cu.currency_code,
           cu.currency_description,
           cu.symbol_html,
           cu.symbol_utf8,
           cu.symbol_text
    FROM product p
        LEFT JOIN product_pricing pp
            ON p.product_id = pp.product_id
               AND pp.language_code = @language_code
               AND pp.location_code = @location_code
        LEFT JOIN product_pricing pp2
            ON p.product_id = pp2.product_id
               AND pp2.currency_id = @currency_id
        LEFT JOIN product_description pd
            ON p.product_id = pd.product_id
               AND pd.language_code = @language_code
               AND pd.location_code = @location_code
        LEFT JOIN currency cu
            ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
        INNER JOIN product_line_product pl
            ON p.product_id = pl.product_id
        INNER JOIN product_storage ps
            ON p.product_id = ps.product_id
        LEFT JOIN product_license_category c
            ON p.product_id = c.product_id
        LEFT JOIN license_category lc
            ON c.license_category_id = lc.license_category_id
        LEFT JOIN product_seat s
            ON p.product_id = s.product_id
        LEFT JOIN product_years y
            ON p.product_id = y.product_id
    WHERE pl.product_line_id = @product_line_id
          AND years = FLOOR(@years)
          AND storage_gb = @storage_gb
          AND current_storage_gb = @product_storage_gb
          AND p.product_type_id = 2
          AND (COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)) > 0
          AND @product_id IS NOT NULL
          AND p.product_lifecycle_id = 1
    ORDER BY p.product_type_id DESC,
             p.product_id

    -- 4.4) renewal license_module_license (for license already upgraded)
    INSERT INTO @product_set
    (
        product_id,
        product_description,
        retail_price,
        upgrade_price,
        discount,
        standard_discount,
        product_type_id,
        license_category_name,
        seats,
        storage_gb,
        years,
        p_type,
        currency_id,
        currency_code,
        currency_description,
        symbol_html,
        symbol_utf8,
        symbol_text
    )
    SELECT DISTINCT
           p.product_id,
           product_description = CASE
                                     WHEN pd.product_description IS NULL THEN
                                         p.product_description
                                     ELSE
                                         pd.product_description
                                 END,
           retail_price = COALESCE(pp2.retail_price, pp.retail_price, p.retail_price) * @years,
           upgrade_price = COALESCE(pp2.retail_price, pp.retail_price, p.retail_price) * @years,
           discount = ISNULL(CONVERT(MONEY, ISNULL(id.discount, i.discount)) * @years, 0),
           standard_discount = 0,
           p.product_type_id,
           lc.license_category_name,
      
     s.seats,
           storage_gb = 0,
           y.years,
           p_type = 'module_upgrade',
           cu.currency_id,
           cu.currency_code,
           cu.currency_description,
           cu.symbol_html,
           cu.symbol_utf8,
           cu.symbol_text
    FROM product p
        LEFT JOIN product_pricing pp
            ON p.product_id = pp.product_id
               AND pp.language_code = @language_code
               AND pp.location_code = @location_code
        LEFT JOIN product_pricing pp2
            ON p.product_id = pp2.product_id
               AND pp2.currency_id = @currency_id
        LEFT JOIN product_description pd
            ON p.product_id = pd.product_id
               AND pd.language_code = @language_code
               AND pd.location_code = @location_code
        LEFT JOIN currency cu
            ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
        INNER JOIN product_line_product pl
            ON p.product_id = pl.product_id
        INNER JOIN product_license_category c
            ON p.product_id = c.product_id
        INNER JOIN license_category lc
            ON c.license_category_id = lc.license_category_id
        INNER JOIN product_seat s
            ON p.product_id = s.product_id
        LEFT JOIN product_years y
            ON p.product_id = y.product_id
        LEFT JOIN cart_discount_item i
            ON pl.product_line_id = i.product_line_id
               AND s.seats = i.license_seats
               AND i.cart_discount_id = @cart_discount_id
               AND i.product_type_id = 4
        LEFT JOIN cart_discount_item_license_module im
            ON i.cart_discount_item_id = im.cart_discount_item_id
        LEFT JOIN cart_discount_item_discount id
            ON i.cart_discount_item_id = id.cart_discount_item_id
               AND id.language_code = @language_code
               AND id.location_code = @location_code
    WHERE p.product_type_id = 4
          AND pl.product_line_id = @product_line_id
          AND dbo.fn_product_license_module_key_value(p.product_id) = @license_module_list
          AND c.license_category_id = @license_category_id
          AND s.seats = @license_seats
          AND @years > 0
          AND p.product_lifecycle_id = 1
    ORDER BY p.product_type_id DESC,
             p.product_id


    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 5.) Apply discount
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 5.1) bundle discount
    IF @cart_discount_type_id = 3
    BEGIN
        -- 5.1.1) new, renewal, upgrade
        INSERT INTO @product_set
        (
            product_id,
            product_description,
            retail_price,
            upgrade_price,
            discount,
            product_type_id,
            license_category_name,
            seats,
            storage_gb,
            years,
            currency_id,
            currency_code,
            currency_description,
            symbol_html,
            symbol_utf8,
            symbol_text
        )
        SELECT DISTINCT
               p.product_id,
               product_description = CASE
                                         WHEN pd.product_description IS NULL THEN
                                             p.product_description
                                         ELSE
                                             pd.product_description
                                     END,
               retail_price = CASE
                                  WHEN zpp.product_id IS NOT NULL THEN
                                      IIF(p.product_type_id = 2, zpp
.renewal_price, zpp.retail_price)
                                  WHEN ISNULL(pp2.product_pricing_id, pp.product_pricing_id) IS NULL THEN
                                      p.retail_price
                                  ELSE
                                      ISNULL(pp2.retail_price, pp.retail_price)
                              END,
               upgrade_price = CASE
                                   WHEN zpp.product_id IS NOT NULL THEN
                                       IIF(p.product_type_id = 2, zpp.renewal_price, zpp.retail_price)
                                   WHEN ISNULL(pp2.product_pricing_id, pp.product_pricing_id) IS NULL THEN
                                       p.retail_price
                                   ELSE
                                       ISNULL(pp2.retail_price, pp.retail_price)
                               END,
               discount = CASE
                              WHEN zpp.product_id IS NOT NULL THEN
                                  zpp.discount
                              ELSE
                                  0
                          END,
               p.product_type_id,
               lc.license_category_name,
               s.seats,
               ISNULL(ps.storage_gb, 0),
               y.years,
               cu.currency_id,
               cu.currency_code,
               cu.currency_description,
               cu.symbol_html,
               cu.symbol_utf8,
               cu.symbol_text
        FROM product p
            LEFT JOIN product_pricing pp
                ON p.product_id = pp.product_id
                   AND pp.language_code = @language_code
                   AND pp.location_code = @location_code
            LEFT JOIN product_pricing pp2
                ON p.product_id = pp2.product_id
                   AND pp2.currency_id = @currency_id
            LEFT JOIN product_description pd
                ON p.product_id = pd.product_id
                   AND pd.language_code = @language_code
                   AND pd.location_code = @location_code
            LEFT JOIN currency cu
                ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
            INNER JOIN product_license_category c
                ON p.product_id = c.product_id
            LEFT JOIN license_category lc
                ON c.license_category_id = lc.license_category_id
            INNER JOIN product_seat s
                ON p.product_id = s.product_id
            LEFT JOIN product_storage ps
                ON p.product_id = ps.product_id
            INNER JOIN product_years y
                ON p.product_id = y.product_id
            INNER JOIN product_line_product pl
                ON p.product_id = pl.product_id
            INNER JOIN cart_discount_item i
                ON c.license_category_id = i.license_category_id
                   AND s.seats = i.license_seats
                   AND y.years = i.years
                   AND pl.product_line_id = i.product_line_id
            LEFT JOIN dbo.zuora_product_pricing AS zpp
                ON zpp.product_id = p.product_id
                   AND zpp.campaign_id = @PORTAL_CAMPAIGN_ID
                   AND
			   (
				   @zuora_license = 1
				   OR
				   (
					   @interstitial_campaign_request = 1
					   AND @location_code = @PORTAL_LOCATION_CODE
				   )
			   )
        WHERE i.cart_discount_id = @cart_discount_id
              AND i.product_type_id IN ( 1, 2, 3 )

        -- 5.1.2) module 
        INSERT INTO @product_set
        (
            product_id,
            product_description,
            retail_price,
            upgrade_price,
            discount,
            standard_discount,
            product_type_id,
            license_category_name,
            seats,
            storage_gb,
            years,
            currency_id,
            currency_code,
            currency_description,
            s
ymbol_html,
            symbol_utf8,
            symbol_text
        )
        SELECT DISTINCT
               p.product_id,
               product_description = CASE
                                         WHEN pd.product_description IS NULL THEN
                                             p.product_description
                                         ELSE
                                             pd.product_description
                                     END,
               retail_price = COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)
                              * (CEILING(@months_remaining / 12.0) + @years),
               upgrade_price = COALESCE(pp2.retail_price, pp.retail_price, p.retail_price)
                               * (CEILING(@months_remaining / 12.0) + @years),
               discount = CONVERT(MONEY, ISNULL(id.discount, i.discount)) * (CEILING(@months_remaining / 12.0) + @years),
               standard_discount = 0, --(round(convert(money,(@months_remaining+@years*12) * ((isnull(pp.retail_price,p.retail_price))/12)),2)) - round(convert(money,(@months_remaining+@years*12) * ((isnull(pp.retail_price,p.retail_price))/12)),2),
               p.product_type_id,
               lc.license_category_name,
               s.seats,
               ISNULL(ps.storage_gb, 0),
               y.years,
               cu.currency_id,
               cu.currency_code,
               cu.currency_description,
               cu.symbol_html,
               cu.symbol_utf8,
               cu.symbol_text
        FROM cart_discount_item i
            INNER JOIN cart_discount_item_license_module im
                ON i.cart_discount_item_id = im.cart_discount_item_id
            LEFT JOIN cart_discount_item_discount id
                ON i.cart_discount_item_id = id.cart_discount_item_id
                   AND id.language_code = @language_code
                   AND id.location_code = @location_code
            INNER JOIN product_license_module m
                ON im.license_module_id = m.license_module_id
            INNER JOIN product p
                ON m.product_id = p.product_id
                   AND i.product_type_id = p.product_type_id
            INNER JOIN product_license_category c
                ON i.license_category_id = c.license_category_id
                   AND p.product_id = c.product_id
            INNER JOIN license_category lc
                ON c.license_category_id = lc.license_category_id
            INNER JOIN product_line_product pl
                ON p.product_id = pl.product_id
            INNER JOIN product_seat s
                ON p.product_id = s.product_id
            INNER JOIN product_years y
                ON p.product_id = y.product_id
            LEFT JOIN product_pricing pp
                ON p.product_id = pp.product_id
                   AND pp.language_code = @language_code
                   AND pp.location_code = @location_code
            LEFT JOIN product_pricing pp2
                ON p.product_id = pp2.product_id
                   AND pp2.currency_id = @currency_id
            LEFT JOIN product_description pd
                ON p.product_id = pd.product_id
                   AND pd.language_code = @language_code
                   AND pd.location_code = @location_code
            LEFT JOIN currency cu
                ON ISNULL(pp2.currency_id, pp.currency_id) = cu.currency_id
            LEFT JOIN product_storage ps
                ON p.product_id = ps.product_id
        WHERE i.cart_discount_id = @cart_discount_id
              AND i.product_type_id IN ( 4 )
              AND s.seats = @license_seats
              AND pl.product_line_id = i.product_line_id
              AND
              (
                  @license_module_list IS NULL
                  OR @license_module_list <> dbo.fn_product_license_module_key_value(p.product_id)
              )
    END


    -- 5.2) check for license_
cart_discount
    IF ISNULL(@cart_discount_id,0) = 0 AND @interstitial_campaign_request = 0
    BEGIN
        SELECT @cart_discount_id =
        (
            SELECT TOP 1
                   cart_discount_id
            FROM license_cart_discount
            WHERE license_id = @license_id
                  AND
                  (
                      start_date <= GETDATE()
                      AND
                      (
                          GETDATE() <= end_date
                          OR end_date IS NULL
                      )
                  )
            ORDER BY license_cart_discount_id DESC
        )
    END

    -- 5.3) update product set with discounts
    UPDATE @product_set
    SET discount = CASE
                       WHEN i.cart_discount_method_id = 1
                            AND s.upgrade_price <> 0 THEN
                           ROUND(
                                    CONVERT(MONEY, ISNULL(id.discount, i.discount))
                                    * (s.retail_price /
                                       (
                                           SELECT SUM(retail_price)FROM @product_set WHERE upgrade_price <> 0
                                       )
                                      ),
                                    2
                                )
                       WHEN i.cart_discount_method_id = 2
                            AND s.upgrade_price <> 0 THEN
        (s.retail_price - CONVERT(MONEY, ISNULL(id.discount, i.discount)))
                       WHEN i.cart_discount_method_id = 3
                            AND s.upgrade_price <> 0
                            AND s.product_type_id <> 3 THEN
                           ROUND((CONVERT(FLOAT, ISNULL(id.discount, i.discount)) / 100) * s.retail_price, 2)
                       WHEN i.cart_discount_method_id = 3
                            AND s.upgrade_price <> 0
                            AND s.product_type_id = 3 THEN
                           ROUND((CONVERT(FLOAT, ISNULL(id.discount, i.discount)) / 100) * s.upgrade_price, 2)
                       ELSE
                           s.discount
                   END,
        cart_discount_id = @cart_discount_id
    FROM @product_set s
        LEFT JOIN cart_discount_item i
            ON i.cart_discount_id = @cart_discount_id
               --and s.product_type_id = i.product_type_id
               AND
               (
                   s.license_category_name = i.license_category_name
                   OR i.license_category_name IS NULL
               )
               AND
               (
                   s.storage_gb = i.storage_gb
                   OR i.storage_gb IS NULL
                   OR i.storage_gb = 0
               )
               AND
               (
                   s.seats = i.license_seats
                   OR i.license_seats IS NULL
                   OR i.license_seats = 0
               )
               AND
               (
                   s.years = i.years
                   OR i.years IS NULL
                   OR i.years = 0
               )
        LEFT JOIN cart_discount_item_discount id
            ON i.cart_discount_item_id = id.cart_discount_item_id
               AND id.language_code = @language_code
               AND id.location_code = @location_code
        LEFT JOIN cart_discount d
            ON i.cart_discount_id = d.cart_discount_id
    WHERE i.product_type_id <> 4
    UPDATE @product_set
    SET discount = 0
    WHERE discount IS NULL

    -- 5.4) check for discount on Module products
    IF
    (
        SELECT COUNT(*)
        FROM @product_set
        WHERE product_type_id = 4
              AND discount = 0
    ) > 0
    BEGIN
        UPDATE @product_set
        SET discount = CONVERT(MONEY, ISNULL(id.discount, i.discount)) * (@years),
            cart_discount_id = i.cart_discount_id
        FROM @product_set s
            INNER JOIN product_license_module pm
                ON s.product_id = pm.product_id
            INNER JOIN cart_discount_item i
                ON s.product_type_id = i.product_type_id
                   AND s.license_category_name = i.license_category_name
                   AND s.seats = i.license_seats
                   AND i.product_line_id = @product_line_id
            INNER JOIN cart_discount_item_discount id
                ON i.cart_discount_item_id = id.cart_discount_item_id
                   AND id.language_code = @language_code
                   AND id.location_code = @location_code
            INNER JOIN cart_discount d
                ON i.cart_discount_id = d.cart_discount_id
            INNER JOIN cart_discount_item_license_module m
                ON i.cart_discount_item_id = m.cart_discount_item_id
                   AND m.license_module_id = pm.license_module_id
        WHERE s.product_type_id = 4
              AND s.discount = 0
    END



    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 6.) Return result
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    UPDATE @product_set
    SET upgrade_price = retail_price - (discount + standard_discount),
        standard_discount = CASE
                                WHEN standard_discount < 0 THEN
                                    0
                                ELSE
                                    standard_discount
                            END

    SELECT product_id,
           product_description,
           retail_price = CASE
                              WHEN @suppress_discount = 1 THEN
                                  upgrade_price
                              ELSE
                                  retail_price
                          END,
           upgrade_price,
           discount = CASE
                          WHEN @suppress_discount = 1 THEN
                              0
                          ELSE
                              discount
                      END,
           standard_discount = CASE
                                   WHEN @suppress_discount = 1 THEN
                                       0
                                   ELSE
                                       standard_discount
                               END,
           net_price = upgrade_price,
           product_type_id,
           license_category_name,
           seats,
           years,
           p_type,
           currency_id,
           currency_code,
           currency_description,
           symbol_html,
           symbol_utf8,
           symbol_text,
           cart_discount_id
    FROM @product_set


END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select product failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_renewal_product_set_ENT]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_cart_select_renewal_product_set_ENT]

(
		@keycode varchar(40),
		@license_category_name varchar(10), 
		@license_seats int,
		@storage_gb int,
		@years float,
		@cart_discount_id int = null,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@pricing_level varchar(20) = null,
		@module_json nvarchar(200) = null,
		@currency_id tinyint = null
		
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-07	esmart		Initial creation.
	2013-02-26	esmart		Add support for supplemental cart discount
	2013-03-07	esmart		Fix upgrades for SAUP
	2013-07-26	esmart		Support for trial-to-full
	2013-10-17	esmart		Support active tier discounts only 3.0)
	2014-08-29	esmart		Resolve discount issue
	2014-10-11	esmart		Update multi-year upgrade pricing
	2015-04-03	esmart		Modify discount method to handle per seat per year rounding
	2015-07-22	esmart		Modify supplemental discount to look up years
	2017-03-07	esmart		Support module products
	2017-06-26	cnovac		Added @currency_id as an override to all lang/loc queries as an override for Cleverbridge auto-renewal

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_category_id tinyint,
			@product_id int,
			@cart_type_id int,
			
			@license_id int,
			@current_license_category_id tinyint,
			@current_license_seats int,
			@upgrade_product_id int,
			@seat_upgrade_product_id int,

			@license_status_id int,
			@product_line_id int,
			@months_remaining int,
			@capability_expiration_date datetime,
			@capability_activation_days int,
			@transaction_date datetime,
			@license_activated int,
			@base_capability_id int,
			@cart_discount_type_id tinyint,
			@supplemental_cart_discount_id int,
			@cart_discount_method_id tinyint,

			@trial tinyint,
			@product_type_id int,
			@license_keycode_type_id int,
			@child_keycode tinyint,

			@alt_language_code varchar(2),
			@alt_location_code varchar(3)

	set @transaction_date = getdate()	

	begin try
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id 
		select @license_id = license_id,
				--@product_line_id = product_line_id,
				@license_status_id = license_status_id,
				@license_keycode_type_id = case when license_type_id = 2 then 3 else 1 end
		from license 
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -100,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

		if @license_id is not null 
			begin
			-- 1.1.1) select current license category
			select @current_license_category_id = isnull(license_category_id,dbo.fn_GetLicenseCategoryId(@license_id))
			from license_category_license
			where license_id = @license_id

			-- 1.1.2) select current license seats
			select @current_license_seats = license_seats
			from license_seat
			where license_id = @license_id

	-- 1.2) select @license_category_id
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name
	
	-- 1.3) @current_license_seats
		if @current_license_seats is null
			begin
			select @current_license_seats = 1
			end

	-- 1.4) @current_license_seats
		if @license_seats is null
			begin
			select @license_seats = 1
			end

	-- 1.5) product_line_id
		select @cart_type_id = 2
--		if @cart_type_id is null
--			begin
--			selec
t @cart_type_id = 2
--			end

		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code and
			cart_type_id = @cart_type_id and 
			payment_merchant_id is not null
			
		if @product_line_id is null
			begin
			select @language_code = alt_language_code, @location_code = alt_location_code
			from license_category_product_line
			where license_category_id = @license_category_id and 
				language_code = @language_code and 
				location_code = @location_code and
				cart_type_id = @cart_type_id

			select @product_line_id = product_line_id
			from license_category_product_line
			where license_category_id = @license_category_id and 
				language_code = @language_code and 
				location_code = @location_code and
				cart_type_id = @cart_type_id
			end

--		if @license_category_id in (1)
--			begin
--			select @product_family_id = 9
--			end
--	
--		if @license_category_id in (2)
--			begin
--			select @product_family_id = 17
--			end

	-- 1.6) get base capability_id
		select @base_capability_id = base_capability_id
		from license_category
		where license_category_id = @license_category_id	
		
		end

	-- 1.7) alternative discounts
		-- 1.7.1) usp_cart_select_license_cart_discount
		if @cart_discount_id is null or @cart_discount_id = 0
			begin
			exec usp_cart_select_license_cart_discount @license_id,@cart_discount_id output
			end

		-- 1.7.2) usp_cart_select_campaign_cart_discount
		if @cart_discount_id is null or @cart_discount_id = 0
			begin
			exec usp_cart_select_campaign_cart_discount @license_id,@cart_discount_id output
			end

	-- 1.7) cart_discount_type
		select @cart_discount_type_id = cart_discount_type_id
		from cart_discount
		where cart_discount_id = @cart_discount_id

		select @cart_discount_method_id = min(cart_discount_method_id) 
		from cart_discount_item
		where cart_discount_id = @cart_discount_id

		-- 1.7.1) if explicit cart discount is not tier set @supplemental_cart_discount_id
		if @cart_discount_type_id <> 4 and @cart_discount_method_id <> 2
			begin
			select @supplemental_cart_discount_id = @cart_discount_id
			select @cart_discount_id = null
						
			select @years = case when years is not null then years else @years end
			from cart_discount_item 
			where cart_discount_id = @supplemental_cart_discount_id
			end

	-- 1.8) trial
	select @trial = (select count(*) 
					from license_capability c with (nolock)
					where license_id = @license_id and capability_id = @base_capability_id and capability_type_id in (2,3))

	select @child_keycode = (select count(*) from license_parent where child_license_id = @license_id)

	-- 1.9) if trial keycode make product_type new
	select @product_type_id = case 
									when @trial = 0 then 2 
									when @trial <> 0 and @child_keycode = 1 then 3 
									else 1 
								end
	-- 1.10) @pricing_level
	if @pricing_level is null or @pricing_level = ''
		begin
			select @pricing_level = 'retail'
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get upgrade and renewal products
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) get license_capability days
		select @capability_activation_days = capability_activation_days
		from license_capability
		where license_id = @license_id and capability_id = @base_capability_id
			
	-- 2.2) get remaining months on license
		if @license_status_id = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,capability_activation_days,@transaction_date),
						@license_activated = case when capability_expiration_date is null then 0
 else 1 end
				from license_capability
				where license_id = @license_id and capability_id = @base_capability_id
			end
		else
			begin
				select @capability_expiration_date = capability_expiration_date,
						@license_activated = case when capability_expiration_date is null then 0 else 1 end
				from license_capability
				where license_id = @license_id and capability_id = @base_capability_id
			end

		if @license_status_id = 1 and @license_activated = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,capability_activation_days,@transaction_date)
				from license_capability
				where license_id = @license_id and capability_id = @base_capability_id
			end

	-- 2.3) months remaining	
		select @months_remaining = 0

		if datediff(hh,@transaction_date,@capability_expiration_date) > 24
			begin

				while dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
					begin
					select @months_remaining = @months_remaining + 1
					end

				select @months_remaining = 
						case
							when @months_remaining <= 1 and @capability_expiration_date is not null then 1
							when @months_remaining <= 1 and @capability_expiration_date is null then 0
							else @months_remaining - 1
						end
			end

	-- 2.4) if current category does not match new category get upgrade product
		if (@license_category_id > @current_license_category_id and @product_type_id <> 1) -- or @child_keycode = 1
			begin
			select @upgrade_product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id 
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where p.product_type_id = 3 and
					pl.product_line_id = @product_line_id and
					p.license_keycode_type_id = @license_keycode_type_id and
					p.uses_keycode = 1
					and c.license_category_id = @license_category_id 
					and c.current_license_category_id = @current_license_category_id
			end

	-- 2.5) if current seats does not match new seats get upgrade product
		if @license_seats <> @current_license_seats and @product_type_id <> 1
			begin
			select @seat_upgrade_product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id 
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where p.product_type_id = 3 and
					p.product_lifecycle_id = 1 and
					p.license_keycode_type_id = @license_keycode_type_id and
					pl.product_line_id = @product_line_id and
					p.uses_keycode = 1 and 
					c.current_license_category_id = @current_license_category_id and 
					c.license_category_id = @current_license_category_id and 
					y.upgrade_months = case 
											when @months_remaining <= 12 then 12
											when @months_remaining > 12 and @months_remaining <= 24 then 24
											when @months_remaining > 24 then 36
										end
			end

	-- 2.6) select product
		if @product_type_id in (1,2) 
			begin
			select @product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where p.product_type_id = @product_type_id and
					p.product_lifecycle_id = 1 and
					pl.product_line_id = @product_line_id and
					p.license_keycode_type_id = @license_keycode_type_id and
					p.uses_keycode = 1 and
					c.license_category_id = @license_category_id and 
					y.years = @years 
			end


	-- 2.7) @module_products
		declare @module_json_table table (license_module_code varchar(50), module_seats int)

		declare @module_products table (license_module_code varchar(50), module_seats int, product_type_id int)

		if @modul
e_json is not null
			begin
				-- 2.7.1) parse json
				insert into @module_json_table (license_module_code, module_seats)
				select license_module_code, p.module_seats
				from (select row_id = parent_ID, parameter_name = NAME, input_value = case when StringValue = '' then null else StringValue end
					from dbo.fn_parse_json(@module_json) 
					where Object_ID is null and StringValue is not null) j 
				pivot (max(input_value) for parameter_name in (license_module_code, module_seats)) as p

				-- 2.7.2) find matching product
				insert into @module_products (license_module_code, module_seats, product_type_id)
				select license_module_code = case
													when x.license_module_code is null then mp.license_module_code
													else x.license_module_code
												end,
						module_seats = case
												when x.module_seats is null then mp.module_seats
												when x.license_module_type_name = 'trial' then mp.module_seats
												when x.license_module_type_name = 'full' and x.module_seats < mp.module_seats and @years = 0 then mp.module_seats - x.module_seats
												when x.license_module_type_name = 'full' and x.module_seats >= mp.module_seats and @years = 0 then 0
												else mp.module_seats
											end,
						product_type_id = case
												when x.module_seats is null then 1
												when x.license_module_type_name = 'trial' then 1
												when x.license_module_type_name = 'full' and x.module_seats < mp.module_seats and @years = 0 then 3
												when x.license_module_type_name = 'full' and x.module_seats >= mp.module_seats and @years = 0 then null
												else 2
											end
				from @module_json_table mp
				left join (select m.license_module_code, t.license_module_type_name, ml.module_seats, ml.start_date, ml.end_date
							from license_module_license ml
							inner join license_module m
								on m.license_module_id = ml.license_module_id
							inner join license_module_type t
								on t.license_module_type_id = ml.license_module_type_id
							where ml.license_id = @license_id) x
					on x.license_module_code = mp.license_module_code
			end
		--else if @years > 0
		--	-- 2.7.3) renewal
		--	begin
		--		insert into @module_products (license_module_code, module_seats, product_type_id)
		--		select m.license_module_code, ml.module_seats, 2
		--		from license_module_license ml
		--		inner join license_module m
		--			on m.license_module_id = ml.license_module_id
		--		where ml.license_id = @license_id and ml.license_module_type_id = 19
		--	end

			--select product_line_id = @product_line_id,license_category_id = @license_category_id, current_license_category_id = @current_license_category_id,product_type_id = @product_type_id, product_id = @product_id, license_seats = @license_seats,current_license_seats = @current_license_seats,upgrade_product_id = @upgrade_product_id,seat_upgrade_product_id = @seat_upgrade_product_id,months_remaining = @months_remaining,capability_expiration_date = @capability_expiration_date,years = @years,license_keycode_type_id = @license_keycode_type_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) @product_set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		declare @product_set table(product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int)

		-- 3.1) renewal product
	
	insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,standard_discount,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
		select	distinct p.product_id, 
				p.product_description, 
				quantity = @license_seats,
				retail_price = case
								when @pricing_level = 'retail' then isnull(pp2.retail_price, pp.retail_price)
								when @pricing_level = 'edu_nfp' then isnull(pp2.edu_nfp_price, pp.edu_nfp_price)
								when @pricing_level = 'govt' then isnull(pp2.govt_price, pp.govt_price)
								else isnull(pp2.retail_price, pp.retail_price)
							end, 
				upgrade_price = case
								when @pricing_level = 'retail' then isnull(pp2.retail_price, pp.retail_price)
								when @pricing_level = 'edu_nfp' then isnull(pp2.edu_nfp_price, pp.edu_nfp_price)
								when @pricing_level = 'govt' then isnull(pp2.govt_price, pp.govt_price)
								else isnull(pp2.retail_price, pp.retail_price)
							end,
				discount = 0, 
				standard_discount = 0,
				p.product_type_id, lc.license_category_name, @license_seats, y.years, p_type = 'renewal',
				cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
		from product p		
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join product_pricing pp2
			on p.product_id = pp2.product_id and pp2.currency_id = @currency_id
		left join currency cu
			on isnull(pp2.currency_id, pp.currency_id) = cu.currency_id
		left join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		left join product_years y
			on p.product_id = y.product_id
		where p.product_id = @product_id

		-- 3.2) upgrade product
		insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,standard_discount,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
		select distinct p.product_id, p.product_description, 
			quantity = @license_seats,
			retail_price = case
								when @pricing_level = 'retail' then round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
								when @pricing_level = 'edu_nfp' then round(convert(money,@months_remaining * (isnull(pp2.edu_nfp_price, pp.edu_nfp_price)/y.upgrade_months)),2)
								when @pricing_level = 'govt' then round(convert(money,@months_remaining * (isnull(pp2.govt_price, pp.govt_price)/y.upgrade_months)),2)
								else round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
							end,
			upgrade_price = case
								when @pricing_level = 'retail' then round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
								when @pricing_level = 'edu_nfp' then round(convert(money,@months_remaining * (isnull(pp2.edu_nfp_price, pp.edu_nfp_price)/y.upgrade_months)),2)
								when @pricing_level = 'govt' then round(convert(money,@months_remaining * (isnull(pp2.govt_price, pp.govt_price)/y.upgrade_months)),2)
								else round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
							end,
			discount = 0,
			standard_discount = 0,
			p.product_type_id, lc.license_category_name, @license_seats, y.years, p_type = 'upgrade',
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
		from product p		
		left join product_pricing pp
			on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
		left join product_pricing pp2
			on p.product_id = pp2.product_id and pp2.currency_id = @currency_id
		left join cu
rrency cu
			on isnull(pp2.currency_id, pp.currency_id) = cu.currency_id
		left join product_license_category c
			on p.product_id = c.product_id
		left join license_category lc
			on c.license_category_id = lc.license_category_id
		left join product_years y
			on p.product_id = y.product_id
		where p.product_id = @upgrade_product_id

		-- 3.3) seat upgrade product
		if @license_seats > @current_license_seats
			begin
			insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,standard_discount,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
			select distinct p.product_id, p.product_description, 
					quantity = @license_seats - @current_license_seats,
					retail_price = case
								when @pricing_level = 'retail' then round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
								when @pricing_level = 'edu_nfp' then round(convert(money,@months_remaining * (isnull(pp2.edu_nfp_price, pp.edu_nfp_price)/y.upgrade_months)),2)
								when @pricing_level = 'govt' then round(convert(money,@months_remaining * (isnull(pp2.govt_price, pp.govt_price)/y.upgrade_months)),2)
								else round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
							end,
					upgrade_price = case
								when @pricing_level = 'retail' then round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
								when @pricing_level = 'edu_nfp' then round(convert(money,@months_remaining * (isnull(pp2.edu_nfp_price, pp.edu_nfp_price)/y.upgrade_months)),2)
								when @pricing_level = 'govt' then round(convert(money,@months_remaining * (isnull(pp2.govt_price, pp.govt_price)/y.upgrade_months)),2)
								else round(convert(money,@months_remaining * (isnull(pp2.retail_price, pp.retail_price)/y.upgrade_months)),2)
							end,
					discount = 0, 
					standard_discount = 0,
					p.product_type_id, lc.license_category_name, @license_seats, y.years, p_type = 'seat upgrade',
					cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
			from product p	
			left join product_pricing pp
				on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code	
			left join product_pricing pp2
				on p.product_id = pp2.product_id and pp2.currency_id = @currency_id
			left join currency cu
				on isnull(pp2.currency_id, pp.currency_id) = cu.currency_id
			left join product_license_category c
				on p.product_id = c.product_id
			left join license_category lc
				on c.license_category_id = lc.license_category_id
			left join product_years y
				on p.product_id = y.product_id
			where p.product_id = @seat_upgrade_product_id
			end

		-- 3.4) module products
			insert into @product_set(product_id,product_description,quantity,retail_price,upgrade_price,discount,standard_discount,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text)
			select distinct p.product_id,p.product_description,
										quantity = mp.module_seats,
										retail_price = case
														when @pricing_level = 'retail' then isnull(pp2.retail_price, pp.retail_price)
														when @pricing_level = 'edu_nfp' then isnull(pp2.edu_nfp_price, pp.edu_nfp_price)
														when @pricing_level = 'govt' then isnull(pp2.govt_price, pp.govt_price)
														else isnull(pp2.retail_price, pp.retail_price)
													end,
									upgrade_price = case
														when @pricing_level = 'retail' then isnull(pp2.retail_price, pp.retail_price)
														when @pricing_level = 'edu_nfp' then isnull(pp2.edu_nfp_price, pp.edu_nfp_price)
														when @pricing_level = 'govt' then isnull(pp2.govt_price, pp.govt_price)
														else isnull(pp2.r
etail_price, pp.retail_price)
													end,
									discount = 0, 
									standard_discount = 0, 
									mp.product_type_id, lc.license_category_name, mp.module_seats, @years,
									p_type = t.product_type_description, 
									cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text 
			from @module_products mp
			inner join license_module m 
				on m.license_module_code = mp.license_module_code
			inner join product_license_module pm
				on m.license_module_id = pm.license_module_id
			inner join product p
				on p.product_id = pm.product_id
			inner join product_type t
				on t.product_type_id = mp.product_type_id
			left join product_pricing pp
				on p.product_id = pp.product_id and pp.language_code = @language_code and pp.location_code = @location_code
			left join product_pricing pp2
				on p.product_id = pp2.product_id and pp2.currency_id = @currency_id
			left join currency cu
				on isnull(pp2.currency_id, pp.currency_id) = cu.currency_id
			left join product_license_category c
				on p.product_id = c.product_id
			left join license_category lc
				on c.license_category_id = lc.license_category_id
			left join product_years y
				on p.product_id = y.product_id
			where p.retail_price > 0
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Apply discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		

		-- 3.0) get cart_discount if @cart_discount_id is null
		if @cart_discount_id is null or @cart_discount_id = 0 and (@cart_discount_method_id <> 2 or @cart_discount_method_id is null)
			begin
			select @cart_discount_id = (select top 1 i.cart_discount_id
										from @product_set s
										left join cart_discount_item i
											on low_range <= @license_seats and @license_seats < high_range and s.product_type_id = i.product_type_id and i.license_category_name = @license_category_name and i.cart_discount_method_id = 3
										left join cart_discount d
											on i.cart_discount_id = d.cart_discount_id
										where d.cart_discount_status_id = 1 and d.cart_discount_type_id = 4
										order by i.discount desc)
			end


		-- 3.1) update product set with discounts
		if (@cart_discount_method_id <> 2 or @cart_discount_method_id is null)
			begin
				update @product_set
				set standard_discount = case
									when s.currency_code = 'JPY' and i.cart_discount_method_id = 1 then round(convert(money,i.discount)* (s.retail_price/(select sum(retail_price) from @product_set)),0)
									when s.currency_code = 'JPY' and i.cart_discount_method_id = 3 and s.years > 0 then round((s.retail_price/s.years) - ((1.00 - i.discount/100) * (s.retail_price/s.years)),0)*s.years
									when s.currency_code = 'JPY' and i.cart_discount_method_id = 3 and s.years = 0 then round((s.retail_price) - ((1.00 - i.discount/100) * (s.retail_price)),0)
									when s.currency_code <> 'JPY' and i.cart_discount_method_id = 1 then round(convert(money,i.discount)* (s.retail_price/(select sum(retail_price) from @product_set)),2)
									when s.currency_code <> 'JPY' and i.cart_discount_method_id = 3 and s.years > 0 then round((s.retail_price/s.years) - ((1.00 - i.discount/100) * (s.retail_price/s.years)),2)*s.years
									when s.currency_code <> 'JPY' and i.cart_discount_method_id = 3 and s.years = 0 then round((s.retail_price) - ((1.00 - i.discount/100) * (s.retail_price)),2)
									else s.discount
							end
				from @product_set s
				left join cart_discount_item i
					on i.cart_discount_id = @cart_discount_id and low_range <= @license_seats and @license_seats < high_range --and s.product_type_id = i.product_type_id
				left join cart_discount d
					on i.cart_dis
count_id = d.cart_discount_id
				where s.upgrade_price > 0
			end

		-- select supplemental_cart_discount_id = @supplemental_cart_discount_id, cart_discount_id = @cart_discount_id

		-- 3.2) @supplemental_cart_discount_id
		if @supplemental_cart_discount_id is not null and (@cart_discount_method_id <> 2 or @cart_discount_method_id is null)
			begin
				update @product_set
				set discount =  case
								when i.cart_discount_method_id = 3 then round(((convert(float,i.discount)/100) * (s.retail_price-s.standard_discount)),2)
								else s.discount
					end,
					cart_discount_id = @supplemental_cart_discount_id
				from @product_set s
				left join cart_discount_item i
					on i.cart_discount_id = @supplemental_cart_discount_id
				left join cart_discount_item_discount id
					on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
				left join cart_discount d
					on i.cart_discount_id = d.cart_discount_id
			end
			
		-- 3.3) fixed price
		if @cart_discount_method_id = 2
			begin
				declare @retail_price money, @discount money

				select @discount = discount
				from cart_discount_item
				where cart_discount_id = @cart_discount_id

				update @product_set
				set retail_price = case 
										when p_type = 'seat upgrade' then round(convert(money,@months_remaining * (@discount/12)),2)
										else @discount * @years
									end, 
					upgrade_price = case 
										when p_type = 'seat upgrade' then round(convert(money,@months_remaining * (@discount/12)),2)
										else @discount * @years
									end
				from @product_set s
				 
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) Return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		select product_id, 
			product_description,
			retail_price = retail_price * quantity, 
			upgrade_price = (retail_price - (discount+standard_discount)) * quantity, 
			discount = discount * quantity, 
			standard_discount = standard_discount * quantity, 
			net_price = (retail_price - (discount+standard_discount)) * quantity, 
			product_type_id, license_category_name, 
			seats = case when product_type_id = 3 then quantity else seats end, 
			years, p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, 
			cart_discount_id = case when @supplemental_cart_discount_id is not null then @supplemental_cart_discount_id else @cart_discount_id end
		from @product_set

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_renewal_product_set_INT]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_renewal_product_set_INT]

(
		@keycode varchar(40),
		@license_category_name varchar(10), 
		@license_seats int,
		@storage_gb int,
		@years int,
		@language_code varchar(2),
		@location_code varchar(3),
		@cart_discount_id int = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2010-01-18	esmart		Initial creation.
	2010-08-11	esmart		Add support for WISC product with less than 10GB
	2010-09-07	esmart		Add support for WW 
	2012-01-23	esmart		Back convert to old license categories
	2012-05-02	esmart		WSA support
	2012-11-02	esmart		webroote support
	2013-01-03	esmart		trial to full
	2013-05-28	esmart		PCCB support
	2014-01-24	esmart		Update @keycode to alias keycode
	2014-03-21	esmart		DR Theme support
	2014-05-16	mrobbins	Fix issue with years in temp table - changed from int to float

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),	
			@license_category_id tinyint,
			@product_id int,
			@product_family_id int,
			@product_storage_gb int,
			@storage_product_id int,
			
			@license_id int,
			@current_license_category_id tinyint,
			@current_license_seats int,
			@current_storage_gb int,
			@upgrade_product_id int,
			@upgrade_product_storage_gb int,
			@initial_storage_gb int,

			@license_status_id int,
			@product_line_id int,
			@months_remaining int,
			@capability_expiration_date datetime,
			@capability_activation_days int,
			@transaction_date datetime,
			@license_activated int,
			@cart_type_id int,
			@dr_site_id varchar(20),

			@base_capability_id int,
			@trial tinyint,
			@product_type_id int,
			@license_distribution_method_id int,
			@dr_theme varchar(20)

	set @transaction_date = getdate()	

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id 
		select @license_id = license_id,
				--@product_line_id = product_line_id,
				@license_status_id = license_status_id,
				@license_distribution_method_id = license_distribution_method_id
		from license 
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -100,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

		if @license_id is not null 
			begin
			-- 1.1.1) select current license category
			select @current_license_category_id = license_category_id 
			from license_category_license
			where license_id = @license_id

			select @current_license_category_id = case
															when @current_license_category_id in (1,2) then 100
															when @current_license_category_id = 3 then 110
															when @current_license_category_id = 4 then 120
															else @current_license_category_id
														end				

			-- 1.1.2) select current license seats
			select @current_license_seats = license_seats
			from license_seat
			where license_id = @license_id

			-- 1.1.3) select current license seats
			select @current_storage_gb = isnull(storage_gb,0)
			from license_storage
			where license_id = @license_id

			-- 1.1.4) alias keycode
			if (select count(*) from license_keycode_alias where license_id = @license_id) > 0
				begin
				select @keycode = keycode_alias from license_keycode_alias where license_id = @license_id
				end

			end

	-- 1.2) select @license_category_id													
			select @license_category_name = case
												when @license_category_name in 
('SS','WAV') then 'WSAV'
												when @license_category_name = 'WISE' then 'WSAE'
												when @license_category_name = 'WISC' then 'WSAC'
												else @license_category_name
											end

		select @license_category_id = license_category_id,
				@base_capability_id = base_capability_id
		from license_category
		where license_category_name = @license_category_name
		
	-- 1.3) @current_license_seats
		if @current_license_seats is null
			begin
			select @current_license_seats = 1
			end

	-- 1.4) @current_license_seats
		if @license_seats is null
			begin
			select @license_seats = 1
			end

	-- 1.5) @original_storage_gb
		if @current_license_category_id = 4 and @current_storage_gb < 25
			begin
			select @current_storage_gb = 25
			end

		if @current_license_category_id = 4 and @current_storage_gb >= 25
			begin
			select @initial_storage_gb = 25
			from license_storage_history
			where license_id = @license_id
			end

	-- 1.6) product_line_id
		if @cart_type_id is null
			begin
			select @cart_type_id = 1
			end

		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id and 
			language_code = @language_code and 
			location_code = @location_code and
			cart_type_id = @cart_type_id

	
	-- 1.7) @dr_site_id
		if @location_code = 'JPN'
			begin
			select @dr_site_id = 'webrootj'
			end
		else
			begin
			select @dr_site_id = 'webroote'
			end

	-- 1.8) trial
	select @trial = (select count(*) 
					from license_capability c with (nolock)
					where license_id = @license_id and capability_id = @base_capability_id and capability_type_id in (2,3))

		-- 1.8.1) if trial keycode make product_type new
		select @product_type_id = case when @trial = 0 then 2 else 1 end

	
	-- 1.9) check PCCB 
	if @license_distribution_method_id = 797
		begin
		select @language_code = 'NL', @location_code = 'NLD'
		end

	-- 1.10) @dr_theme
	select @dr_theme = ''

	select @dr_theme = '/ThemeID.'+t.dr_theme_value
	from dr_theme t
	inner join dr_theme_license_distribution_method m
		on t.dr_theme_id = m.dr_theme_id
	where m.license_distribution_method_id = @license_distribution_method_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get upgrade and renewal products
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) if current category does not match new category get upgrade product
	if @license_category_id > @current_license_category_id or @license_seats > @current_license_seats
		begin
		--	select 'upgrade'
			select @upgrade_product_id = p.product_id,
					@upgrade_product_storage_gb = storage_gb
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id 
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			left join product_storage ps
				on p.product_id = ps.product_id
			where p.product_type_id = 3 and
					--p.product_family_id = @product_family_id and
					pl.product_line_id = @product_line_id and
					p.uses_keycode = 1
					and c.license_category_id = @license_category_id 
					and s.seats = @license_seats 
					and c.current_license_category_id = @current_license_category_id
					and s.current_seats = @current_license_seats 
		end

	-- 2.2) select renewal product
		if @license_category_id = 4
			begin
			if @upgrade_product_storage_gb is not null 
				begin
				select @current_storage_gb = @upgrade_product_storage_gb
				end

			if @current_storage_gb >= 25
				begin
				select @current_storage_gb = @initial_storage_gb
				end
	
			select @product_id = p.product_
id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_storage ps
				on p.product_id = ps.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where p.product_type_id = 2 and
					--p.product_family_id = @product_family_id and
					pl.product_line_id = @product_line_id and
					p.uses_keycode = 1 and
					c.license_category_id = @license_category_id and 
					s.seats = @license_seats and
					y.years = @years and
					ps.storage_gb = @current_storage_gb
			end
		else
			begin
			select @product_id = p.product_id
			from product p
			inner join product_license_category c
				on p.product_id = c.product_id
			inner join product_seat s
				on p.product_id = s.product_id
			inner join product_years y
				on p.product_id = y.product_id
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where p.product_type_id = @product_type_id and
					--p.product_family_id = @product_family_id and
					pl.product_line_id = @product_line_id and
					p.uses_keycode = 1 and
					c.license_category_id = @license_category_id and 
					s.seats = @license_seats and
					y.years = @years 
			end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) get storage
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 3.1) get license storage information
--		select @current_storage_gb = isnull(s.storage_gb,2)
--		from license_storage s
--		where license_id = @license_id

		if @current_storage_gb = 0 or @current_storage_gb is null
			begin
			select @current_storage_gb = 2
			end
	
--		-- 3.1.1) if the license is being upgraded then the storage on the upgrade overrides the current storage on the license
		if @upgrade_product_storage_gb > @current_storage_gb and @upgrade_product_storage_gb is not null
			begin
			select @current_storage_gb = @upgrade_product_storage_gb
			end

			-- 3.1.2) @product_storage_gb
			select @product_storage_gb = storage_gb
			from product_storage
			where product_id = @product_id

			if @product_storage_gb = 0 or @product_storage_gb is null
				begin
				select @product_storage_gb = @upgrade_product_storage_gb
				end
	
		-- 3.2) get license_capability days
		select @capability_activation_days = capability_activation_days
		from license_capability
		where license_id = @license_id and capability_id = @base_capability_id

				
		-- 3.3) get remaining months on license
		if @license_status_id = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,max(capability_activation_days),@transaction_date),
						@license_activated = case when max(capability_expiration_date) is null then 0 else 1 end
				from license_capability
				where license_id = @license_id
			end
		else
			begin
				select @capability_expiration_date = max(capability_expiration_date),
						@license_activated = case when max(capability_expiration_date) is null then 0 else 1 end
				from license_capability
				where license_id = @license_id 
			end

		if @license_status_id = 1 and @license_activated = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,max(capability_activation_days),@transaction_date)
				from license_capability
				where license_id = @license_id
			end

			select @months_remaining = 0


		if datediff(hh,@transaction_date,@capability_expiration_date) > 24--@capability_expiration_date >= @transaction_date
			begin

				wh
ile dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
					begin
					select @months_remaining = @months_remaining + 1
					end

				select @months_remaining = 
						case
							when @months_remaining <= 1 and @capability_expiration_date is not null then 1
							when @months_remaining <= 1 and @capability_expiration_date is null then 0
							else @months_remaining - 1
						end
			end

		-- 3.4) check for best buy monthly subscribers and set months remaining = 12
		declare @best_buy_monthly int

		select @best_buy_monthly = 
					case
						when count(*) > 0 then 1
						else 0
					end
		from subscription 
		where license_id = @license_id and subscription_type_id <> 2
		
		if @best_buy_monthly = 1
			begin
				select @months_remaining = 12
			end

		-- 3.5) if renewal is included then add months
--		select @months_remaining = @months_remaining-- + @years*12

		-- 3.6) if months remaining > 12 then return the prorated portion of the total months remaining. 
		declare @storage_months_remaining int,
				@storage_months_remaining_remainder int,
				@storage_years int

		select @storage_months_remaining = @months_remaining

		select @storage_months_remaining_remainder = isnull(@storage_months_remaining % 12,0)		
		if @storage_months_remaining > 12 and @storage_months_remaining_remainder = 0
			begin
				select @storage_months_remaining = 12
			end
		if @storage_months_remaining > 12 and @storage_months_remaining_remainder > 0
			begin
				select @storage_months_remaining = @storage_months_remaining % 12
			end
	
		select @storage_years = (@months_remaining - @storage_months_remaining)/12 + @years

	-- select license_category_id = @license_category_id, current_license_category_id = @current_license_category_id,product_id = @product_id, product_line_id = @product_line_id,storage_gb = @storage_gb,product_storage_gb = @product_storage_gb, storage_product_id = @storage_product_id,current_storage_gb = @current_storage_gb,upgrade_product_storage_gb = @upgrade_product_storage_gb, initial_storage_gb = @initial_storage_gb,current_license_seats = @current_license_seats,upgrade_product_id = @upgrade_product_id,months_remaining = @months_remaining,capability_expiration_date = @capability_expiration_date,storage_months_remaining = @storage_months_remaining,storage_months_remaining_remainder = @storage_months_remaining_remainder,storage_years = @storage_years,years = @years
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @dr_offer_id bigint

		if @cart_discount_id is not null and @cart_discount_id <> 0
			begin
			select @dr_offer_id = do.dr_offer_id
			from dr_offer_cart_discount dr
			inner join dr_offer do
				on dr.dr_offer_id = do.dr_offer_id
			where cart_discount_id = @cart_discount_id and do.site_id = @dr_site_id
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) insert product set
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		declare @product_set table (dr_product_id int, product_id int, product_description varchar(100), dr_product_name varchar(150), retail_price money, upgrade_price money, discount money default 0, currency varchar(20), language_code varchar(2), location_code varchar(3), product_type_id int, license_category_name varchar(10), seats int, years float,p_type varchar(20), currency_code varchar(3), s
ymbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), locale varchar(10), cart_discount_id int null)

		if @location_code = 'JPN'
			begin
				insert into @product_set(dr_product_id, product_id, product_description, dr_product_name, retail_price, upgrade_price, currency, language_code, location_code, product_type_id, license_category_name, seats, years, p_type)
				select d.dr_product_id, p.product_id, p.product_description, d.dr_product_name, d.retail_price, upgrade_price = d.retail_price, d.currency, d.language_code, d.location_code, p.product_type_id, lc.license_category_name, s.seats, y.years, 
						p_type = 'renewal'
				from product p
				inner join dr_product_price d
					on p.product_id = d.product_id and language_code = @language_code and location_code = @location_code
				left join product_license_category c
					on p.product_id = c.product_id
				left join license_category lc
					on c.license_category_id = lc.license_category_id
				left join product_seat s
					on p.product_id = s.product_id
				left join product_years y
					on p.product_id = y.product_id
				where p.product_id = @product_id

				update @product_set 
				set symbol_html = c.symbol_html, symbol_utf8 = c.symbol_utf8, symbol_text = c.symbol_text, currency_code = c.currency_code, locale = 'ja_JP'
				from currency c
				where c.currency_code = 'JPY'
			end
		else
			begin		
				insert into @product_set(dr_product_id, product_id, product_description, dr_product_name, retail_price, upgrade_price, currency, language_code, location_code, product_type_id, license_category_name, seats, years, p_type, currency_code, symbol_html, symbol_utf8, symbol_text, locale)
				select dr_product_id = dp.dr_variation_product_id, p.product_id, p.product_description, dr_product_name = dp.display_name, d.retail_price, upgrade_price = d.retail_price, currency = cu.currency_description, d.language_code, d.location_code, p.product_type_id, lc.license_category_name, s.seats, y.years, 
						p_type = 'renewal', cu.currency_code, cu.symbol_html, cu.symbol_utf8, cu.symbol_text, cl.dr_locale
				from product p
				inner join product_pricing d
					on p.product_id = d.product_id and d.language_code = @language_code and d.location_code = @location_code
				inner join currency cu
					on d.currency_id = cu.currency_id
				inner join currency_language_location cl
					on cl.language_code = @language_code and cl.location_code = @location_code
				inner join dr_product dp
					on p.product_id = dp.product_id
				left join product_license_category c
					on p.product_id = c.product_id
				left join license_category lc
					on c.license_category_id = lc.license_category_id
				left join product_seat s
					on p.product_id = s.product_id
				left join product_years y
					on p.product_id = y.product_id
				where p.product_id = @product_id and dp.autorenewal = 'OFF'
			end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.) Apply discount
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 6.1) update product set with discounts
		update @product_set
		set discount =  case
							when i.cart_discount_method_id = 1 and s.upgrade_price <> 0 then  round(convert(money,isnull(id.discount,i.discount)) * (s.retail_price/(select sum(retail_price) from @product_set where upgrade_price <> 0 and product_type_id = i.product_type_id)),2)
							when i.cart_discount_method_id = 2 and s.upgrade_price <> 0 then (s.retail_price - convert(money,isnull(id.discount,i.discount)))
							when i.cart_discount_method_id = 3 and s.upgrade_price <> 0 then ((convert(float,isnull(id.discount,i.discount))/100) * s.retail_price)
							else s.discount
					end,
			cart_discount_id = @cart_di
scount_id
		from @product_set s
		left join cart_discount_item i
			on i.cart_discount_id = @cart_discount_id and 
				s.product_type_id = i.product_type_id
				and (s.license_category_name = i.license_category_name or i.license_category_name is null)
				--and (s.storage_gb = i.storage_gb or i.storage_gb is null) 
				and (s.seats = i.license_seats or i.license_seats is null) 
		left join cart_discount_item_discount id
			on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
		left join cart_discount d
			on i.cart_discount_id = d.cart_discount_id
		where i.product_type_id <> 4	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.) return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		

		select dr_product_id, product_id, product_description, dr_product_name, 
			retail_price = case
								when currency = 'yen' then convert(money,round((retail_price * 1.05),0))
								else retail_price
							end, 
			discount = convert(money,round((discount),2)),
			upgrade_price = case
								when currency = 'yen' then convert(money,round(((retail_price-discount) * 1.05),0))
								else convert(money,round(((retail_price-discount)),2))
							end, 
			currency, language_code, location_code, product_type_id, license_category_name, seats, years, p_type, currency_code, symbol_html, symbol_utf8, symbol_text, 
			DR_cart_url = case	
								when @dr_offer_id is not null then 'https://store.webroot.com/store/'+@dr_site_id+'/'+ locale + '/buy/productID.' + convert(varchar(20),dr_product_id) + '/currency.'+ currency_code + '/OfferID.' + convert(varchar(20),@dr_offer_id) + '/License.' + dbo.fn_KeycodeEncrypt(@keycode)+@dr_theme
								else 'https://store.webroot.com/store/'+@dr_site_id+'/'+ locale + '/buy/productID.' + convert(varchar(20),dr_product_id) + '/currency.'+ currency_code + '/License.' + dbo.fn_KeycodeEncrypt(@keycode)+@dr_theme
							end
		from @product_set
		order by product_type_id desc, product_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
		



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_seat_enforcement_configurator]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_seat_enforcement_configurator]

(
	@cart_order_in_process_id int,
	@cart_item_bundle_id int,
	@license_category_name varchar(10) = null,
	@enterprise_license_seats int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-04-16	acoffel		Initial creation.

	DESCRIPTION
	select seat, year, storage, license_category, and discounts for item
*/

AS
	set nocount on				

	declare	@language_code varchar(2),
			@location_code varchar(3),
			@keycode varchar(40),
			@license_category_id tinyint,
			@license_category_description varchar(50),
			@license_category_name_input varchar(10),
			@enterprise_license_seats_upgrade int,
			@license_id int,
			@last_activity_date datetime,
			@cart_upsell_type_name varchar(50),
			@license_seats int,
			@current_license_seats int,
			@product_line_id int,
			@product_type_id int,
			@cart_discount_id int, 
			@current_over_useage int,
			@storage_gb int,
			@years float,
			@base_price money,
			@last_over_usage int,
			@base_upgrade_price money,
			@base_retail_price money,
			@base_retail_upgrade_price money,
			@retail_price money,
			@net_price money,
			@months_remaining int,
			--@enterprise_license_seats int,
			@response_code int,
			@message varchar(100)


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @item_summary table (cart_item_bundle_id int, product_family_id int, product_line_id int, cart_order_item_in_process_id int, product_id int, keycode varchar(40), product_type_id int, max_product_type_id int,	current_license_category_id int,license_category_id int,current_seats int,seats int,current_storage_gb int,storage_gb int,quantity int,years float,retail_price money,net_price money,discount money,standard_discount money,cart_discount_id int)

	select @license_category_name_input = @license_category_name--, @enterprise_license_seats_upgrade = @enterprise_license_seats

	
	-- 1.1) @item_summary
		insert into @item_summary(cart_item_bundle_id, product_family_id, product_line_id, keycode, cart_order_item_in_process_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				plp.product_line_id,
				l.keycode, 
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = case 
									when plp.product_line_id in (55,300) then max(i.quantity)
									else min(s.current_seats)
								end, 
				seats = case 
							when plp.product_line_id in (55,300) then max(i.quantity)
							else max(s.seats)
						end, 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price), 
				net_price = sum(i.net_price),
				discount = sum(i.discount), 
				standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inn
er join product_line_product plp with (nolock)
			on p.product_id = plp.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_in_process_id = @cart_order_in_process_id and i.cart_item_bundle_id = @cart_item_bundle_id and il.keycode <> '' and p.product_family_id in (1,2,30,31,50,51,55,100,200,300)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				plp.product_line_id,
				l.keycode

		--select * from @item_summary

	-- 1.2) get values
		select @language_code = language_code, 
			@location_code = location_code
		from cart_order_in_process 
		where cart_order_in_process_id = @cart_order_in_process_id

		select @license_category_id = license_category_id, 
			@product_line_id = product_line_id, 
			@product_type_id = product_type_id,
			@cart_discount_id = cart_discount_id,
			@storage_gb = storage_gb,
			@keycode = keycode,
			@base_retail_price = retail_price-standard_discount,
			@base_price = net_price,
			--@enterprise_license_seats = seats,
			@license_seats = seats,
			@current_license_seats = seats
		from @item_summary s

		select @license_category_name = license_category_name, @license_category_description = license_category_description from license_category where @license_category_id = license_category_id

		-- 1.2.0) grab usage info
		if @keycode is not NULL
			begin 
				select @license_id = (select license_id from license where keycode = @keycode)	
				
				select @last_activity_date = max(activity_date) 
				from license_usage 
				where license_id = @license_id

				select @current_over_useage = devices - current_seats
				from license_usage 
				where license_id = @license_id and activity_date = @last_activity_date

				select @last_over_usage = devices - current_seats
				from license_usage 
				where license_id = @license_id and activity_date = dateadd(dd,-7,@last_activity_date)

			end

		--select last_activity_date = @last_activity_date, current_over_useage = @current_over_useage, last_over_usage = @last_over_usage
		--return

		
		-- 1.2.1) @license_category_name
		if @license_category_name is null
			begin
			select @license_category_name = license_category_name,
					@license_category_name_input = license_category_name
			from license_category 
			where license_category_id = @license_category_id
			end

		--select license_seats = @license_seats, enterprise_license_seats = @enterprise_license_seats
		if @enterprise_license_seats is null
			begin
			select @enterprise_license_seats = @license_seats
			end
			
	-- 1.3) @configurator_data	
		declare @configurator_data table (license_category_id tinyint,license_category_name varchar(10),license_seats int,license_distribution_method_id int,root_product_id int,license_status_id int,is_autorenewal int,storage_gb int,months_remaining int,capability_expiration_date datetime,last_activity_date datetime,major_version int)

		insert into @configurator_data(license_category_id,license_category_name,license_seats,license_distribution_method_id,root_product_id,license_status_id,is_autorenewal,storage_gb,months_remaining,capability_expiration_date,last_activity_date,major_version)
		exec usp_cart_select_configurator_data @keycode

		select @months_remaining = months_remaining from @configurator_data

		if @months_remaining > 6
			begin
			select @base_price = 0, @base_retail_price
 = 0
			end
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) add upsells types 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @configurator_upsell table (configurator_upsell_id int identity(1,1), cart_upsell_type_id tinyint, cart_upsell_type_name varchar(40), license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, storage_gb int, years float, retail_price money, retail_upgrade_price money, net_price money, upgrade_price money)

	declare @product_set table(license_category_name_input varchar(10), license_category_id_input tinyint, storage_gb_input int, product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

		-- 2.2.1) update years
		update @configurator_upsell
		set years = 0

	-- 2.3) Seat upgrade
	--if @product_line_id not in (300,55)
	--	begin
			insert into @configurator_upsell(cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name,license_category_description,seats,storage_gb,years)
			select cart_upsell_type_id=3,cart_upsell_type_name='Seat upgrade',@license_category_id,@license_category_name,@license_category_description,
					seats = case when @product_line_id in (300,55) then @enterprise_license_seats else s.seats end,
					0 as storage_gb,
					--years = case when @product_line_id in (300,55) then 0 else u.years end
					0 as years
			from product_license_category_seat s
			where license_category_id = @license_category_id and
					s.seats >= case when @product_line_id in (300,55) then s.seats else @license_seats end and 
					s.seats <= case 
									when @product_line_id in (300,55) then s.seats 
									when @product_line_id not in (300,55) and @license_seats <= 10 then 10
									when @product_line_id not in (300,55) and @license_seats > 5 then 25
									else 5 
								end 
					--u.cart_upsell_type_name = 'License category upgrade'
			order by s.seats

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	declare @configurator_upsell_id int, @total_upsells int

	select @configurator_upsell_id = 1, @total_upsells = count(*) from @configurator_upsell

	-- 3.1) start loop
	while @total_upsells >= @configurator_upsell_id
		begin
		--print @configurator_upsell_id
		-- 3.1.1) set values
		select @license_category_name = license_category_name, @license_seats = seats, @storage_gb = storage_gb, @years = years, @cart_upsell_type_name = cart_upsell_type_name
		from @configurator_upsell
		where configurator_upsell_id = @configurator_upsell_id

		-- 3.1.2) get enterprise product set data
		if @product_line_id in (55,300)
			begin
				--select @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_cod
e,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_renewal_product_set_ENT @keycode,@license_category_name,@license_seats,@storage_gb,@years,null,@language_code,@location_code
			end
		-- 3.1.3) get consumer product set data
		else
			begin
				if @months_remaining > 6 begin select @years = 0 end
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
				exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
			end
		
	
			select @retail_price = isnull(sum(retail_price-standard_discount),0),
					@net_price = isnull(sum(net_price),0) 
			from @product_set

			--select * from @product_set
			
		-- select net_price = @net_price, base_price = @base_price, base_upgrade_price = @base_upgrade_price

		-- 3.1.3) update @configurator_upsell
		update @configurator_upsell 
		set retail_price = @retail_price,
			retail_upgrade_price = case
								when @cart_upsell_type_name = 'License category upgrade' and @product_line_id in (300,55) then @retail_price - (@base_retail_price*seats)
								when @cart_upsell_type_name = 'License category upgrade' and @product_line_id not in (300,55) then @retail_price - @base_retail_price 
								else @retail_price - @base_retail_upgrade_price
							end,
			net_price = @net_price, 
			upgrade_price = case
								when @cart_upsell_type_name = 'License category upgrade' and @product_line_id in (300,55) then @net_price - (@base_price*seats)
								when @cart_upsell_type_name = 'License category upgrade' and @product_line_id not in (300,55) then @net_price - @base_price 
								else @net_price - @base_upgrade_price
							end
		where configurator_upsell_id = @configurator_upsell_id
		
		-- 3.1.4) set base price for upgrade calculations
		if @license_category_name_input = @license_category_name and @cart_upsell_type_name = 'License category upgrade'
			begin
			select @base_upgrade_price = @net_price, @base_retail_upgrade_price = @retail_price
			end

		delete from @product_set
		
		--select @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
		
		select @configurator_upsell_id = @configurator_upsell_id + 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select configurator_upsell_id, cart_upsell_type_id, cart_upsell_type_name, license_category_id, license_category_name, license_category_description, seats, storage_gb, years, retail_price, retail_upgrade_price, net_price, upgrade_price
	from @configurator_upsell
	where seats > (@current_license_seats + @current_over_useage) 
	and seats <> 0 			
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_site_campaign_pricing]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_site_campaign_pricing]


(
	@message_campaign_key varchar(36),
	@language_code varchar(2) = null,
	@location_code varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-11-14	esmart		Initial creation.
	2015-01-21	esmart		Add additional columns
	2016-06-20	esmart		Support bundled discounts
	2019-07-29	jnavarra	Monthly pricing

	DESCRIPTION
	select site pricing
*/

AS
	set nocount on				

	declare	@license_category_id tinyint,
			@license_category_name varchar(10),
			@license_seats int,
			@years float,
			@storage_gb int, 
			@cart_discount_id int, 
			@cart_type_id tinyint,
			@location_code2 varchar(2),
			@configurations_id int, 
			@total_configs int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @location_code2 = iso from lu_countries where iso3 = @location_code

	declare @configurations table (configurations_id int identity(1,1), license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, years float, cart_discount_id int)
	
	insert into @configurations(license_category_id, license_category_name, license_category_description, seats, years, cart_discount_id)
	select i.license_category_id, i.license_category_name, c.license_category_description, i.license_seats, i.years, i.cart_discount_id
	from message_campaign m
	inner join message_campaign_cart_discount cd
		on m.message_campaign_id = cd.message_campaign_id
	inner join message_campaign_language_location ll
		on m.message_campaign_id = ll.message_campaign_id and ll.language_code = @language_code and ll.location_code = @location_code
	inner join cart_discount_item i
		on cd.cart_discount_id = i.cart_discount_id
	inner join license_category c
		on i.license_category_id = c.license_category_id
	where m.message_campaign_key = @message_campaign_key and
		m.message_campaign_enabled = 2 and
		m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date and
		i.years <> 0

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @product_set table(product_set_id int identity(1,1), product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, equivalent_year_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)
			
	select @storage_gb = null, @cart_discount_id = null, @cart_type_id = null

	select @configurations_id = 1, @total_configs = count(*) from @configurations

	-- 3.1) start loop
	while @total_configs >= @configurations_id
		begin
		--print @configurator_id
		-- 3.1.1) set values
		select @license_category_name=
license_category_name, @license_seats = seats, @years = years, @cart_discount_id = cart_discount_id
		from @configurations
		where configurations_id = @configurations_id

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
		EXECUTE [usp_cart_select_new_product_set] @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id

		--select product_set_id = scope_identity()
		
		select @configurations_id = @configurations_id + 1
		end

		-- 3.1.2) remove bundled $0 
		delete from @product_set where retail_price = 0

	-- 3.2) 
	update @product_set
	set equivalent_year_price = (select sum(retail_price) from @product_set where license_category_name = s.license_category_name and seats = s.seats and years = 1) * years
	from @product_set s


	--select * from @product_set s
	--return


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select s.product_set_id, s.product_id, 
		product_description = case when b.cart_discount_bundle_id is not null then b.cart_discount_bundle_description else s.product_description end, 
		quantity = isnull(s.quantity,1), 
		s.equivalent_year_price, 
		
		full_retail_price = s.equivalent_year_price,
		s.retail_price, 
		s.upgrade_price, 
		s.net_price, 
		net_price_pm = round(s.net_price / (s.years * 12), 2),

		term_discount = s.equivalent_year_price - s.retail_price,
		s.discount, 
		s.standard_discount, 
		total_discount = s.equivalent_year_price - s.net_price,

		full_retail_price_pspy = round(s.equivalent_year_price/s.seats/s.years,2,1),
		retail_price_pspy = round(s.retail_price/s.seats/s.years,2,1),
		upgrade_price_pspy = round(s.upgrade_price/s.seats/s.years,2,1),
		net_price_pspy = round(s.net_price/s.seats/s.years,2,1),

		total_discount_pspy = round((s.equivalent_year_price - s.net_price)/s.seats/s.years,2,1),
		term_discount_pspy = round((s.equivalent_year_price - s.retail_price)/s.seats/s.years,2,1),
		discount_pspy = round((s.discount)/s.seats/s.years,2,1),

		total_discount_pct = round((round((s.equivalent_year_price - s.net_price)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		term_discount_pct = round((round((s.equivalent_year_price - s.retail_price)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		discount_pct = round((round((s.discount)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		
		s.product_type_id, s.license_category_name, s.seats, s.years, s.p_type, 
		s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text, cl.fraction_unit_separator, cl.whole_unit_separator, cl.symbol_trailing, cl.show_minor,
		d.cart_discount_id, d.cart_discount_description, cart_discount_key = convert(varchar(36),d.cart_discount_key),
		m.cart_discount_method_name, 
		discount = case 
			when m.cart_discount_method_id = 3 then round(i.discount,0) else i.discount end,
		cart_link = case 
			when d.cart_discount_id is null then 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?item[license_category_name]='+s.license_category_name+'&item[license_seats]='+convert(varchar(20),s.seats)+'&item[years]='+convert(varchar(20),s.years)
			else 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/u
pdate?key='+convert(varchar(36),d.cart_discount_key)
			end
	from @product_set s
	inner join license_category c
		on s.license_category_name = c.license_category_name
	inner join currency_language_location cl
		on s.currency_id = cl.currency_id and cl.language_code = @language_code and cl.location_code = @location_code
	left join cart_discount d
		on s.cart_discount_id = d.cart_discount_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id and s.retail_price > 0 and i.product_type_id = s.product_type_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	left join cart_discount_bundle b
		on b.cart_discount_id = d.cart_discount_id
	where s.retail_price > 0
	order by c.license_category_id, s.years

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_site_campaign_pricing_ENT]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_site_campaign_pricing_ENT]


(
	@message_campaign_key varchar(36),
	@license_category_name varchar(10) = null, 
	@license_seats int = null,
	@years float = null,
	@language_code varchar(2) = null,
	@location_code varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-11-14	esmart		Initial creation.
	2014-09-26	esmart		Modify calculations on percentages and add round down.
	2014-10-02	esmart		Discount percent modifications

	DESCRIPTION
	select site pricing
*/

AS
	set nocount on				

	declare	@license_category_id tinyint,
			--@years float,
			@storage_gb int, 
			@cart_discount_id int, 
			@cart_type_id tinyint,
			@location_code2 varchar(2),
			@configurations_id int, 
			@total_configs int,
			@trial_days int,
			@license_keycode_type_id int,
			@low_range int,
			@high_range int,
			@license_seats_input int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) language/location
	if len(@location_code) = 2
		begin
		select @location_code = iso3 from lu_countries where iso = @location_code
		end

		-- 1.1.1) @language_code
		if @language_code is null or @language_code = ''
			begin
			select @language_code = 'EN'
			end
	
		if @location_code is null or @location_code = ''
			begin
			select @location_code = 'USA'
			end

	select @location_code2 = iso from lu_countries where iso3 = @location_code



	select @license_seats_input = @license_seats

	select @location_code2 = iso from lu_countries where iso3 = @location_code

	declare @configurations table (configurations_id int identity(1,1), license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, years float, cart_discount_id int)
	
	insert into @configurations(license_category_id, license_category_name, license_category_description, seats, years, cart_discount_id)
	select i.license_category_id, i.license_category_name, c.license_category_description, i.license_seats, y.years, 
		cart_discount_id = case 
								when m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date and i2.cart_discount_id is null then i.cart_discount_id 
								when m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date and i2.cart_discount_id is not null then i2.cart_discount_id 
								else null 
							end
	from message_campaign m
	inner join message_campaign_cart_discount cd
		on m.message_campaign_id = cd.message_campaign_id
	inner join message_campaign_language_location ll
		on m.message_campaign_id = ll.message_campaign_id and ll.language_code = @language_code and ll.location_code = @location_code
	inner join cart_discount_item i
		on cd.cart_discount_id = i.cart_discount_id
	inner join cart_discount d
		on i.cart_discount_id = d.cart_discount_id
	inner join license_category c
		on i.license_category_id = c.license_category_id
	inner join product_license_category_years y
		on c.license_category_id = y.license_category_id
	left join cart_discount_item i2
		on i.license_category_id = i2.license_category_id and i.discount = i2.discount and i.license_seats = i2.license_seats and i2.years = y.years and i2.cart_discount_id <> i.cart_discount_id and i.product_type_id = i2.product_type_id
	left join cart_discount d2
		on d.cart_discount_type_id = d2.cart_discount_type_id and d2.cart_discount_
id = i2.cart_discount_id
	where m.message_campaign_key = @message_campaign_key and
		m.message_campaign_enabled = 2 and 
		c.license_category_name = case when @license_category_name is null then c.license_category_name else @license_category_name end 
		and y.years = case when @years is null then y.years else @years end
		-- and m.message_campaign_start_date <= getdate() and getdate() < m.message_campaign_end_date

	-- select * from @configurations

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @product_set table(product_set_id int identity(1,1), product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)
	
	declare @seat_data table(license_category_name varchar(10), license_seats int, license_seats_input int, low_range int, high_range int)
			
	select @storage_gb = null, @cart_discount_id = null, @cart_type_id = null

	select @configurations_id = 1, @total_configs = count(*) from @configurations

	-- 3.1) start loop
	while @total_configs >= @configurations_id
		begin
		--print @configurator_id

		-- 1.3) @low_range @high_range
		
		-- 3.1.1) set values
		select @license_category_name=license_category_name, @years = years, @cart_discount_id = cart_discount_id, @license_seats = case when @license_seats is null then seats else @license_seats end
		from @configurations
		where configurations_id = @configurations_id
		
		select @low_range = max(low_range), @high_range = max(high_range) - 1
		from cart_discount_item 
		where site_display = 1 and license_category_name = @license_category_name and product_type_id = 1 and (low_range <= @license_seats)

		if @low_range is null
			begin
			select @low_range = min(low_range), @high_range = min(high_range) - 1
			from cart_discount_item 
			where site_display = 1 and license_category_name = @license_category_name and product_type_id = 1 and (low_range > @license_seats)
			end

			-- 1.3.2)
			if @license_seats > @high_range
				begin
				select @license_seats = @high_range
				end

			-- 1.3.2)
			if @license_seats < @low_range
				begin
				select @license_seats = @low_range
				end

		if (select count(*) from @seat_data where license_category_name = @license_category_name) = 0
			begin
			insert into @seat_data(license_category_name, license_seats, license_seats_input, low_range, high_range) values(@license_category_name, @license_seats, @license_seats_input, @low_range, @high_range)
			end

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html,symbol_utf8,symbol_text,cart_discount_id)
		exec usp_cart_select_new_product_set_ENT @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id,@trial_days,@license_keycode_type_id

		--select product_set_id = scope_identity()

		if @license_seats_input is null
			begin
			select @license_seats = null
			end
		
		select @configurations_id = @configurations_id + 1
		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-------------------
	-- 3.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--select * from @product_set

	--select	s.license_category_name, s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text,
	--				s.cart_discount_id,
	--				s.seats,
	--				s.years,
	--				retail_price,
	--				discount,
	--				standard_discount,
	--				net_price,
	--				full_retail_price_pspy = (select max((retail_price/seats)/years) from @product_set),
	--				term_price_pspy = (s.retail_price/s.seats)/s.years,
	--				net_price_pspy = (s.net_price/s.seats)/s.years,
	--				term_discount_pspy = (select max((retail_price/seats)/years) from @product_set) - (s.retail_price/s.seats)/s.years,
	--				discount_pspy = (s.discount/s.seats)/s.years,
	--				tier_discount_pspy = (s.standard_discount/s.seats)/s.years
	--		from @product_set s

	select t.license_category_name, 
		t.years, 
		t.seats,
		license_seats_input = sd.license_seats_input,
		low_range = sd.low_range,
		high_range = sd.high_range,
		t.retail_price,
		t.discount,
		t.standard_discount,
		full_retail_price = round(t.full_retail_price_pspy,2)*t.seats*t.years, 
		term_price = round(t.term_price_pspy,2)*t.seats*t.years, 
		term_tier_price = round(t.term_price_pspy-t.tier_discount_pspy,2)*t.seats*t.years, 
		t.net_price,
		-- per seat per year
		full_retail_price_pspy = round(t.full_retail_price_pspy,2), 
		term_price_pspy = round(t.term_price_pspy,2), 
		term_tier_price_pspy = round(t.term_price_pspy-t.tier_discount_pspy,2), 
		net_price_pspy = round(t.net_price_pspy,2), 
		-- per seat per year
		term_discount_pspy = round(t.term_discount_pspy,2), 
		discount_pspy = round(t.discount_pspy,2),
		tier_discount_pspy = round(t.tier_discount_pspy,2),
		total_discount_pspy = round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2),
		-- percent per seat per year
		term_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1),
		discount_pct =  round((t.discount_pspy/t.term_price_pspy)*100,1),
		tier_discount_pct =  round((t.tier_discount_pspy/t.term_price_pspy)*100,1),
		total_discount_pct = floor(round(((round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2))/t.full_retail_price_pspy)*100,1)),
		-- total_discount_pct_no_round = round(((round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2))/t.full_retail_price_pspy)*100,1),
		-- total_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1) + round((t.discount_pspy/t.term_price_pspy)*100,1) + round((t.tier_discount_pspy/t.term_price_pspy)*100,1),

		t.currency_id, t.currency_code, t.currency_description, t.symbol_html, t.symbol_utf8, t.symbol_text, cl.fraction_unit_separator, cl.whole_unit_separator, cl.symbol_trailing, cl.show_minor,
		d.cart_discount_id, d.cart_discount_description, 
		cart_discount_key = convert(varchar(36),d.cart_discount_key),
		m.cart_discount_method_name, 
		cart_link = case 
				when d.cart_discount_id is null then 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?item[license_category_name]='+t.license_category_name+'&item[license_seats]='+convert(varchar(20),t.seats)+'&item[years]='+convert(varchar(20),t.years)
				else 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?key='+convert(varchar(36),d.cart_discount_key)+'&quantity='+convert(varchar(20),t.seats)
				end
	from (select	s.license_category_name, s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text,
					s.cart_discount_id,
					s.seats,
					s.years,
					retail_price,
					discount,
					standard_discount,
					net_price,
					full_retail_price_pspy = (select max((retail_price/seats)/years) from @product_set),

					term_price_pspy = (s.retail_price/s.seats)/s.years,
					net_price_pspy = (s.net_price/s.seats)/s.years,
					term_discount_pspy = (select max((retail_price/seats)/years) from @product_set) - (s.retail_price/s.seats)/s.years,
					discount_pspy = (s.discount/s.seats)/s.years,
					tier_discount_pspy = (s.standard_discount/s.seats)/s.years
			from @product_set s) t
	inner join currency_language_location cl
		on t.currency_id = cl.currency_id and cl.language_code = @language_code and cl.location_code = @location_code
	inner join @seat_data sd
		on t.license_category_name = sd.license_category_name
	left join cart_discount d
		on t.cart_discount_id = d.cart_discount_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	order by t.license_category_name, t.years
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_site_pricing]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_site_pricing]


(
	@license_category_name varchar(10), 
	@license_seats int,
	@years float,
	@language_code varchar(2) = null,
	@location_code varchar(3) = null,
	@message_campaign_key varchar(36) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-11-14	esmart		Initial creation.
	2014-06-02	esmart		Modify to support equivalent 1 year price
	2014-08-25	esmart		Make cart_discount_key a varchar(36)
	2014-08-26	esmart		Add message_campaign_key
	2015-01-21	esmart		Add additional columns
	2018-06-04	cnovac		Added site_id to be returned out so PHP can route CBCART to proper cart
	2018-07-31	cnovac		Changed years to be float for WIFI
	2019-07-23	jnavarra	Monthly pricing
	2020-02-18	esmart		Remove duplicate column output for discount

	DESCRIPTION
	select site pricing
*/

AS
	set nocount on				

	declare	@license_category_id tinyint,	
			@location_code2 varchar(2),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) if a campaign call campaign procedure	
	if @message_campaign_key is not null
		begin
		exec usp_cart_select_site_campaign_pricing @message_campaign_key, @language_code, @location_code
		return
		end

	select @location_code2 = iso from lu_countries where iso3 = @location_code

	-- 1.1) select @license_category_id
	if @license_category_name is not null or @license_category_name <> ''
		begin
		select @license_category_id = license_category_id
		from license_category
		where license_category_name = @license_category_name
		end
		
	--else
	--	begin
	--	select @license_category_id_list = coalesce(@license_category_id_list+', ','')+ cast(convert(varchar(10),license_category_id) as varchar(100)) 
	--	from product_license_category_upgrade
	--	where language_code = @language_code and location_code = @location_code and site_display = 1
	--	end

	-- select @message_campaign_seat_list = coalesce(@message_campaign_seat_list+', ','')+ cast(convert(varchar(10),license_seats) as varchar(100)) from message_campaign_seat where message_campaign_id = @message_campaign_id
	
	declare @configurations table (configurations_id int identity(1,1), license_category_id tinyint, license_category_name varchar(10), license_category_description varchar(50), seats int, years float)
	
	insert into @configurations(license_category_id, license_category_name, license_category_description, seats, years)
	select distinct u.license_category_id, c.license_category_name, c.license_category_description, s.seats, y.years
	from product_license_category_upgrade u
	inner join license_category c
		on u.license_category_id = c.license_category_id
	inner join product_license_category_seat s
		on u.license_category_id = s.license_category_id
	inner join product_license_category_years y
		on u.license_category_id = y.license_category_id
	where u.language_code = @language_code and 
		u.location_code = @location_code and 
		u.site_display = 1 and
		u.license_category_id = case when @license_category_id is null then u.license_category_id else @license_category_id end and
		s.site_display = 1 and
		y.site_display = 1 and
		y.years = case when @years is null then y.years else @years end and
		s.seats = case when @years = 1 and @license_category_id is null and @license_seats is null then (select min(seats) from product_lice
nse_category_seat where license_category_id = u.license_category_id) else s.seats end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @product_set table(product_set_id int identity(1,1), product_id int, product_description varchar(100), quantity int, retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, equivalent_year_price money, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null, site_id varchar(20))
			
	declare @configurations_id int, @total_configs int 

	declare @storage_gb int, @cart_discount_id int, @cart_type_id tinyint
	select @storage_gb = null, @cart_discount_id = null, @cart_type_id = null

	select @configurations_id = 1, @total_configs = count(*) from @configurations

	-- 3.1) start loop
	while @total_configs >= @configurations_id
		begin
		--print @configurator_id
		-- 3.1.1) set values
		select @license_category_name=license_category_name, @license_seats = seats, @years = years
		from @configurations
		where configurations_id = @configurations_id

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
		EXECUTE [usp_cart_select_new_product_set] @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id

		--select product_set_id = scope_identity()
		
		select @configurations_id = @configurations_id + 1
		end

	-- 3.2) 
	update @product_set
	set equivalent_year_price = (select retail_price from @product_set where license_category_name = s.license_category_name and seats = s.seats and years = 1) * years
	from @product_set s

	-- 3.3) 
	update ps
	set ps.site_id = lcpl.site_id
	from @product_set ps
	inner join product_license_category plc on plc.product_id = ps.product_id 
	inner join license_category_product_line lcpl on lcpl.license_category_id = plc.license_category_id
	where lcpl.language_code = @language_code
	and lcpl.location_code = @location_code
	and lcpl.site_id = 'CBCART'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select s.product_set_id, s.product_id, s.product_description, quantity = isnull(s.quantity,1), 
		s.equivalent_year_price, 
		
		full_retail_price = s.equivalent_year_price,
		s.retail_price, 
		s.upgrade_price, 
		s.net_price,
		net_price_pm = round(s.net_price / (s.years * 12), 2),

		term_discount = s.equivalent_year_price - s.retail_price,
		--s.discount, 
		s.standard_discount, 
		total_discount = s.equivalent_year_price - s.net_price, 

		full_retail_price_pspy = round(s.equivalent_year_price/s.seats/s.years,2,1),
		retail_price_pspy = round(s.retail_price/s.seats/s.years,2,1),
		upgrade_price_pspy = round(s.upgrade_price/s.seats/s.years,2,1),
		net_price_pspy = round(s.net_price/s.seats/s.years,2,1),

		total_dis
count_pspy = round((s.equivalent_year_price - s.net_price)/s.seats/s.years,2,1),
		term_discount_pspy = round((s.equivalent_year_price - s.retail_price)/s.seats/s.years,2,1),
		discount_pspy = round((s.discount)/s.seats/s.years,2,1),

		total_discount_pct = round((round((s.equivalent_year_price - s.net_price)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		term_discount_pct = round((round((s.equivalent_year_price - s.retail_price)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		discount_pct = round((round((s.discount)/s.seats/s.years,2,1)/round(s.equivalent_year_price/s.seats/s.years,2,1))*100,1),
		
		s.product_type_id, s.license_category_name, s.seats, s.years, s.p_type, 
		s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text, cl.fraction_unit_separator, cl.whole_unit_separator, cl.symbol_trailing, cl.show_minor,
		d.cart_discount_id, d.cart_discount_description, cart_discount_key = convert(varchar(36),d.cart_discount_key),
		m.cart_discount_method_name, 
		discount = case 
			when m.cart_discount_method_id = 3 then round(i.discount,0) else i.discount end,
		cart_link = case 
			when d.cart_discount_id is null then 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?item[license_category_name]='+s.license_category_name+'&item[license_seats]='+convert(varchar(20),s.seats)+'&item[years]='+convert(varchar(20),s.years)
			else 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?key='+convert(varchar(36),d.cart_discount_key)
			end,
		s.site_id
	from @product_set s
	inner join currency_language_location cl
		on s.currency_id = cl.currency_id and cl.language_code = @language_code and cl.location_code = @location_code
	left join cart_discount d
		on s.cart_discount_id = d.cart_discount_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_site_pricing_ENT]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_site_pricing_ENT]


(
	@license_category_name varchar(10), 
	@license_seats int,
	@language_code varchar(2) = null,
	@location_code varchar(3) = null
	--,@message_campaign_key varchar(36) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-07-01	esmart		Initial creation.
	2014-08-26	esmart		Campaign driven pricing
	2014-10-02	esmart		Discount percent modifications
	2017-06-28	esmart		GSM only for SAEP
	2017-10-23	esmart		Rollback GSM only for SAEP
	2018-02-06	esmart		GSM only for SAEP
	2018-06-04	cnovac		Added site_id to be returned out so PHP can route CBCART to proper cart
	2019-07-18	acoffel		Usage pricing
	2020-01-13	esmart		Use product_line_id to set license_keycode_type_id

	DESCRIPTION
	select site pricing
*/

AS
	set nocount on				

	declare	@license_category_id tinyint,
			@product_line_id int,	
			@location_code2 varchar(2), 
			@storage_gb int, 
			@years float, 
			@cart_discount_id int, 
			@cart_type_id tinyint, 
			@trial_days int, 
			@license_keycode_type_id int,
			@low_range int,
			@high_range int,
			@license_seats_input int,
			@response_code int,
			@message varchar(100)

	begin try

	declare @configurations table (config_id tinyint identity(1,1), years float)
	declare @product_set table(product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null, site_id varchar(20))

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		
	---- 1.0) if a campaign call campaign procedure	
	--if @message_campaign_key is not null
	--	begin
	--	select '1.0'
	--	select @message_campaign_key,@license_category_name,@license_seats,@language_code,@location_code
	--	exec usp_cart_select_site_campaign_pricing_ENT @message_campaign_key,@license_category_name,@license_seats,@language_code,@location_code
	--	select 'results'
	--	return
	--	end

	-- 1.1) language/location
	if len(@location_code) = 2
		begin
		select @location_code = iso3 from lu_countries where iso = @location_code
		end

		-- 1.1.1) @language_code
		if @language_code is null or @language_code = ''
			begin
			select @language_code = 'EN'
			end
	
		if @location_code is null or @location_code = ''
			begin
			select @location_code = 'USA'
			end

	select @location_code2 = iso from lu_countries where iso3 = @location_code

	-- 1.2) @license_category_id
	select @license_category_id = license_category_id from license_category where license_category_name = @license_category_name

	-- 1.3) @low_range @high_range
	select @license_seats_input = @license_seats

	select @low_range = max(low_range), @high_range = max(high_range) - 1
	from cart_discount_item 
	where site_display = 1 and license_category_name = @license_category_name and product_type_id = 1 and (low_range <= @license_seats)

	if @low_range is null
		begin
		select @low_range = min(low_range), @high_range = min(high_range) - 1
		from cart_discount_item 
		where site_display = 1 and license_category_name = @license_category_name and produ
ct_type_id = 1 and (low_range > @license_seats)
		end

		-- 1.3.2)
		if @license_seats > @high_range
			begin
			select @license_seats = @high_range
			end

		-- 1.3.2)
		if @license_seats < @low_range
			begin
			select @license_seats = @low_range
			end

	-- 1.4) @product_line_id
	select @product_line_id = product_line_id
	from license_category_product_line
	where license_category_id = @license_category_id and language_code = @language_code and location_code = @location_code

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) configurations
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into @configurations(years)
	select y.years
	from product_license_category_years y
	where license_category_id = @license_category_id
	order by y.years

	declare @config_id tinyint, @configs tinyint

	select @config_id = 1, @configs = max(config_id)
	from @configurations

	while @configs >= @config_id
		begin
		select @years = years from @configurations where config_id = @config_id

		if @product_line_id = 300
			begin
			select @license_keycode_type_id = 3
			end
		else
			begin
			select @license_keycode_type_id = null
			end

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html,symbol_utf8,symbol_text,cart_discount_id)
		exec usp_cart_select_new_product_set_ENT @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id,@trial_days,@license_keycode_type_id

		select @config_id = @config_id + 1
		end

		update ps
		set ps.site_id = lcpl.site_id
		from @product_set ps
		inner join product_license_category plc on plc.product_id = ps.product_id 
		inner join license_category_product_line lcpl on lcpl.license_category_id = plc.license_category_id
		where lcpl.language_code = @language_code
		and lcpl.location_code = @location_code
		and lcpl.site_id = 'CBCART'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	select t.license_category_name, 
		t.years, 
		t.seats,
		license_seats_input = @license_seats_input,
		low_range = @low_range,
		high_range = @high_range,
		t.retail_price,
		t.discount,
		t.standard_discount,
		full_retail_price = round(t.full_retail_price_pspy,2)*t.seats*t.years, 
		term_price = round(t.term_price_pspy,2)*t.seats*t.years, 
		term_tier_price = round(t.term_price_pspy-t.tier_discount_pspy,2)*t.seats*t.years, 
		t.net_price,
		-- per seat per year
		full_retail_price_pspy = round(t.full_retail_price_pspy,2), 
		term_price_pspy = round(t.term_price_pspy,2), 
		term_tier_price_pspy = round(t.term_price_pspy-t.tier_discount_pspy,2), 
		net_price_pspy = round(t.net_price_pspy,2), 
		-- per seat per year
		term_discount_pspy = round(t.term_discount_pspy,2), 
		discount_pspy = round(t.discount_pspy,2),
		tier_discount_pspy = round(t.tier_discount_pspy,2),
		total_discount_pspy = round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2),
		-- percent per seat per year
		term_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1),
		discount_pct =  round((t.discount_pspy/t.ter
m_price_pspy)*100,1),
		tier_discount_pct =  round((t.tier_discount_pspy/t.term_price_pspy)*100,1),
		total_discount_pct = floor(round(((round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2))/t.full_retail_price_pspy)*100,1)),
		-- total_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1) + round((t.discount_pspy/t.term_price_pspy)*100,1) + round((t.tier_discount_pspy/t.term_price_pspy)*100,1),

		t.currency_id, t.currency_code, t.currency_description, t.symbol_html, t.symbol_utf8, t.symbol_text, cl.fraction_unit_separator, cl.whole_unit_separator, cl.symbol_trailing, cl.show_minor,
		d.cart_discount_id, d.cart_discount_description, 
		cart_discount_key = convert(varchar(36),d.cart_discount_key),
		m.cart_discount_method_name, 
		cart_link = case 
				when d.cart_discount_id is null then 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?item[license_category_name]='+t.license_category_name+'&item[license_seats]='+convert(varchar(20),t.seats)+'&item[years]='+convert(varchar(20),t.years)+'&item[license_keycode_type_id]='+convert(varchar(20),p.license_keycode_type_id)
				else 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?key='+convert(varchar(36),d.cart_discount_key)+'&quantity='+convert(varchar(20),t.seats)
				end,
		t.site_id,
		pp.usage_price
	from (select	s.product_id,
					s.license_category_name, s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text,
					s.cart_discount_id,
					s.seats,
					s.years,
					retail_price,
					discount,
					standard_discount,
					net_price,
					full_retail_price_pspy = (select max((retail_price/seats)/years) from @product_set),
					term_price_pspy = (s.retail_price/s.seats)/s.years,
					net_price_pspy = (s.net_price/s.seats)/s.years,
					term_discount_pspy = (select max((retail_price/seats)/years) from @product_set) - (s.retail_price/s.seats)/s.years,
					discount_pspy = (s.discount/s.seats)/s.years,
					tier_discount_pspy = (s.standard_discount/s.seats)/s.years,
					s.site_id
			from @product_set s) t
	inner join product p
		on p.product_id = t.product_id
	inner join currency_language_location cl
		on t.currency_id = cl.currency_id and cl.language_code = @language_code and cl.location_code = @location_code
	INNER JOIN product_pricing pp 
		ON p.product_id = pp.product_id AND pp.language_code = @language_code and pp.location_code = @location_code
	left join cart_discount d
		on t.cart_discount_id = d.cart_discount_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	order by t.years

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_site_pricing_grid_ENT]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_select_site_pricing_grid_ENT]


(
	@license_category_name varchar(10), 
	@language_code varchar(2) = null,
	@location_code varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-07-01	esmart		Initial creation.
	2014-10-02	esmart		Discount percent modifications
	2020-01-13	esmart		Use product_line_id to set @license_keycode_type_id

	DESCRIPTION
	select site pricing
*/

AS
	set nocount on				

	declare	@license_category_id tinyint,
			@product_line_id int,		
			@location_code2 varchar(2), 
			@license_seats int, 
			@storage_gb int, 
			@years float, 
			@cart_discount_id int, 
			@cart_type_id tinyint, 
			@trial_days int, 
			@license_keycode_type_id int,
			@response_code int,
			@message varchar(100)

	begin try

	declare @configurations table (config_id tinyint identity(1,1), low_range float, high_range float, years float)
	declare @product_set table(product_id int, product_description varchar(100), retail_price money, upgrade_price money, discount money, standard_discount money default 0, net_price money, product_type_id int, license_category_name varchar(10), seats int, years tinyint, p_type varchar(20), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int null)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) language/location
	if len(@location_code) = 2
		begin
		select @location_code = iso3 from lu_countries where iso = @location_code
		end

		-- 1.1.1) @language_code
		if @language_code is null or @language_code = ''
			begin
			select @language_code = 'EN'
			end
	
		if @location_code is null or @location_code = ''
			begin
			select @location_code = 'USA'
			end

	select @location_code2 = iso from lu_countries where iso3 = @location_code

	-- 1.2) @product_line_id
	select @license_category_id = license_category_id from license_category where license_category_name = @license_category_name

	select @product_line_id = product_line_id
	from license_category_product_line
	where license_category_id = @license_category_id and language_code = @language_code and location_code = @location_code
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) configurations
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into @configurations(low_range, high_range, years)
	select i.low_range, i.high_range, y.years
	from cart_discount_item i
	inner join product_license_category_years y
		on i.license_category_id = y.license_category_id
	inner join cart_discount d
		on i.cart_discount_id = d.cart_discount_id
	where i.license_category_name = @license_category_name and i.product_type_id = 1 and d.cart_discount_type_id = 4 and d.cart_discount_status_id = 1 and i.site_display = 1 and y.site_display = 1
	order by y.years, i.low_range

	declare @config_id tinyint, @configs tinyint

	select @config_id = 1, @configs = max(config_id)
	from @configurations

	while @configs >= @config_id
		begin
		select @license_seats = low_range, @years = years from @configurations where config_id = @conf
ig_id

		if @product_line_id = 300
			begin
			select @license_keycode_type_id = 3
			end
		else
			begin
			select @license_keycode_type_id = null
			end

		insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html,symbol_utf8,symbol_text,cart_discount_id)
		exec usp_cart_select_new_product_set_ENT @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id,@trial_days,@license_keycode_type_id

		select @config_id = @config_id + 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) pricing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	select t.license_category_name, t.low_range, t.high_range, t.years, 
		-- per seat per year
		full_retail_price_pspy = round(t.full_retail_price_pspy,2), 
		term_price_pspy = round(t.term_price_pspy,2), 
		net_price_pspy = round(t.net_price_pspy,2), 
		-- per seat per year
		term_discount_pspy = round(t.term_discount_pspy,2), 
		discount_pspy = round(t.discount_pspy,2),
		tier_discount_pspy = round(t.tier_discount_pspy,2),
		total_discount_pspy = round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2),
		-- percent per seat per year
		term_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1),
		discount_pct =  round((t.discount_pspy/t.term_price_pspy)*100,1),
		tier_discount_pct =  round((t.tier_discount_pspy/t.term_price_pspy)*100,1),
		total_discount_pct = floor(round(((round(t.term_discount_pspy,2) + round(t.discount_pspy,2) + round(t.tier_discount_pspy,2))/t.full_retail_price_pspy)*100,1)),
		--total_discount_pct = round((t.term_discount_pspy/t.full_retail_price_pspy)*100,1) + round((t.discount_pspy/t.term_price_pspy)*100,1) + round((t.tier_discount_pspy/t.term_price_pspy)*100,1),
		
		t.currency_id, t.currency_code, t.currency_description, t.symbol_html, t.symbol_utf8, t.symbol_text, cl.fraction_unit_separator, cl.whole_unit_separator, cl.symbol_trailing, cl.show_minor,
		d.cart_discount_id, d.cart_discount_description, 
		cart_discount_key = convert(varchar(36),d.cart_discount_key),
		m.cart_discount_method_name, 
		cart_link = case 
				when d.cart_discount_id is null then 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?item[license_category_name]='+t.license_category_name+'&item[license_seats]='+convert(varchar(20),t.low_range)+'&item[years]='+convert(varchar(20),t.years)
				else 'https://www.webroot.com/'+lower(@location_code2)+'/'+lower(@language_code)+'/cart/update?key='+convert(varchar(36),d.cart_discount_key)+'&quantity='+convert(varchar(20),t.low_range)
				end
	from (select	s.license_category_name, s.currency_id, s.currency_code, s.currency_description, s.symbol_html, s.symbol_utf8, s.symbol_text,
					s.cart_discount_id,
					c.low_range,
					high_range = c.high_range - 1, 
					c.years,
					full_retail_price_pspy = (select max((retail_price/seats)/years) from @product_set),
					term_price_pspy = (s.retail_price/s.seats)/s.years,
					net_price_pspy = (s.net_price/s.seats)/s.years,
					term_discount_pspy = (select max((retail_price/seats)/years) from @product_set) - (s.retail_price/s.seats)/s.years,
					discount_pspy = (s.discount/s.seats)/s.years,
					tier_discount_pspy = (s.standard_discount/s.seats)/s.years
			from @product_set s
			inner join @configurations c
				on s.seats = c.low_range and s.years = c.years) t
	inner join currency_language_location cl
		on t.currency_id = cl.currency_id and cl.language_code = @langu
age_code and cl.location_code = @location_code
	left join cart_discount d
		on t.cart_discount_id = d.cart_discount_id
	left join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	left join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	order by t.years, t.low_range

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_select_specials_code_cart_discount]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_select_specials_code_cart_discount]

(
		@cart_discount_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-12-16	esmart		Initial creation.

	DESCRIPTION
	select specials code from discount
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select m.specials_code, d.cart_discount_id, d.cart_discount_description, d.cart_discount_type_id, d.cart_discount_status_id, cart_discount_key = convert(varchar(36),d.cart_discount_key), d.cart_discount_code, 
		i.license_category_name, i.license_seats, i.storage_gb, i.years
	from cart_discount d
	inner join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	inner join cart_discount_specials_mapping m
		on d.cart_discount_id = m.cart_discount_id
	where d.cart_discount_id = @cart_discount_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_autorenewal_test_order]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_autorenewal_test_order]


(
	@vendor_order_code varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-14	esmart		Initial creation.

	DESCRIPTION
	update license data on order to move into current autorenewal queue
*/

AS
	set nocount on				

	declare @license_id int, 
			@keycode varchar(40), 
			@end_days int, 
			@days_added int, 
			@capability_expiration_date datetime, 
			@capability_activation_days int,
			@modified_by varchar(20),
			@parent_warning int, 
			@response_code int, 
			@message varchar(100), 
			@autorenewal_cycle float

	begin try

	select @modified_by = 'AR process'

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) update
	-----------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id
	select @license_id = il.license_id, @keycode = l.keycode
	from vendor_order v
	inner join order_header h
		on v.vendor_order_id = h.vendor_order_id
	inner join order_item i
		on h.order_header_id = i.order_header_id
	inner join order_item_license il
		on i.order_item_id = il.order_item_id
	inner join license l
		on il.license_id = l.license_id
	where v.vendor_order_code = @vendor_order_code

	-- 1.2) get expiration data
	select @capability_expiration_date = c.capability_expiration_date, @capability_activation_days = c.capability_activation_days
	from license_category_license cl
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	inner join license_capability c
		on cl.license_id = c.license_id and c.capability_id = lc.base_capability_id
	where cl.license_id = @license_id

	-- 1.3) check for autorenewal cycle
	select @autorenewal_cycle = a.autorenewal_cycle
	from license_autorenewal_cycle c
	inner join message_autorenewal_cycle a
		on c.message_autorenewal_cycle_id = a.message_autorenewal_cycle_id
	where c.license_id = @license_id

	select @end_days = case
						when @autorenewal_cycle is null or @autorenewal_cycle = 1 then 7
						else 37
						end

	-- 1.4) calculate days to add
	select @days_added = case 
							when @capability_expiration_date is null then @end_days - @capability_activation_days
							else datediff(dd,dateadd(dd,-@end_days,@capability_expiration_date),getdate())
						end

	select keycode = @keycode, end_days = @end_days, days_added = @days_added, capability_expiration_date = @capability_expiration_date, capability_activation_days = @capability_activation_days

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) update
	-----------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) update license
	exec usp_license_update_license_capability_CSI @days_added, @keycode, @modified_by, @parent_warning, @response_code output, @message output

	-- 2.2) if license is not activated then complete activation
	if @capability_expiration_date is null
		begin
		exec usp_license_insert_activation @keycode, @GUID='', @machine_name=''
		end

	-- 2.3)
	exec usp_message_update_license_message_autorenewal @license_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_update_cart_customer]

(
		@vendor_order_code varchar(100),
		@first_name nvarchar(255) = null,
        @last_name nvarchar(255) = null,
        @company_name nvarchar(255) = null,
        @address_1 nvarchar(255) = null,
        @address_2 nvarchar(255) = null,
        @city nvarchar(130) = null,
        @state varchar(50) = null,
        @postal_code nvarchar(32) = null,
        @country varchar(3) = null,
        @phone_number varchar(64) = null,
        @customer_email nvarchar(255) = null,
        @opt_in bit = null,
		@customer_type_id int, -- required param
		@vat_id varchar(20) = null,
		@external_customer_key varchar(100) = null,
		@company_type_id tinyint = null,
		@salesforce_account_id varchar(20) = null,
		@salesforce_contact_id varchar(20) = null,
		@cart_customer_json nvarchar(max) = null,
		@response_code int output,
		@message varchar(500) output
)

/*	
	DATE		AUTHOR		REMARKS
	2017-07-25	esmart		Initial creation.
	2018-10-04	esmart		Add @company_type_id	
	2019-08-29	esmart		extended sfdc salesforce_account_id and salesforce_contact_id
	2020-04-07  esmart		cart_order_partner for SFDC opps with integration partner as bill to
	2020-05-06	esmart		Update lu_state logic 
	2020-07-06	esmart		@cart_customer_json
	2020-10-26	abelenkiy	Refactored to handle json using new validation functions; added better error logging in catch
	2021-02-24	wbarton		Change the update in section 3.2 to set company_name = cct.company_name
	2021-05-07	esmart		Remove requirement for customer_email
	2022-03-01  psatish		ALM# 629 Increased the @state variable length to handle the Japan States
	DESCRIPTION
	Insert new cart_customer record or updates if already exists
*/

as
	set nocount on				
	begin try

	declare @cart_order_id int,
			@cart_customer_id int,
			@partner_id int,
			@site_id varchar(65),
			@customer_json nvarchar(4000),--this and below two vars used to construct json if vars passed in
			@company_json nvarchar(4000),
			@partner_json nvarchar(4000)

	declare @cart_customer_table table
	(external_customer_key varchar(100), first_name nvarchar(255), last_name nvarchar(255), bill_address_1 nvarchar(255), bill_address_2 nvarchar(255), bill_city nvarchar(130)
	  , bill_state char(2), bill_postal_code nvarchar(32), bill_country char(3), phone_number varchar(64), company_name nvarchar(255), customer_email nvarchar(255)
	  , opt_in bit, vat_id varchar(20), customer_type_id int, cart_order_id int, company_type_id tinyint, salesforce_account_id varchar(20), salesforce_contact_id varchar(20))


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @cart_order_id from @vendor_order_code
	select @cart_order_id = cart_order_id, @site_id = site_id
	from cart_order
	where vendor_order_code = @vendor_order_code

	-- 1.2) set @cart_customer_id from @cart_order_id if exists for passed in @customer_type_id
	select @cart_customer_id = cart_customer_id
	from cart_customer
	where cart_order_id = @cart_order_id and customer_type_id = @customer_type_id

	-- 1.3) cart_order_partner for SFDC - select @salesforce_account_id from json (the ISJSON check can be removed once variable use of this proc is deprecated)
	if isjson(@cart_customer_json) = 1
		begin
			select @salesforce_account_id = json_value(@cart_customer_json, '$.company.salesforce_account_id')
		end


	-- 1.3.1) set @partner_id based on @salesforce_account_id if site is SFDC
	if @customer_type_id = 1 and @site_id = 'SFDC'
		begin
			select @partner_id = p.partner_id
			from partner p
			where p.salesforce_id = @salesforce_account_id

			insert into cart_order_partner (cart_order_id, partner_id, partner_account_id)
			select @cart_order_id, cp.partner_id, pa.partner_account_id
			from partner_configuration_partner cp
				inner join partner_account pa
					on pa.partner_id = cp.partner_id
				inner join account a
					on a.account_id = pa.account_id and a.account_user_name = cp.configuration_value
				left join cart_order_partner cop
					on cop.partner_id = cp.partner_id and cop.partner_account_id = pa.partner_account_id and cop.cart_order_id = @cart_order_id
			where cp.partner_configuration_id = 14 and cp.partner_id = @partner_id and cop.cart_order_partner_id is null and pa.partner_account_id is not null
		end
	-- 1.3.2) set @partner_id based on @cart_order_id from cart_order_partner otherwise
	else
		begin
			select @partner_id = cop.partner_id
			from cart_order_partner cop
			where cop.cart_order_id = @cart_order_id
		END
        


	-- 1.4) construct json if variables passed in (all of section 1.4 can be removed once variable use of this proc is deprecated)
	if isjson(isnull(@cart_customer_json,'')) = 0
		begin
			insert into @cart_customer_table (cart_order_id, first_name, last_name, company_name, bill_address_1, bill_address_2, bill_city, bill_state, bill_postal_code, bill_country, phone_number, 
				customer_email, opt_in, customer_type_id, vat_id, external_customer_key, company_type_id, salesforce_account_id, salesforce_contact_id)
			select @cart_order_id, @first_name, @last_name, @company_name, @address_1, @address_2, @city, vcs.state_id, @postal_code, vcs.country_iso3, @phone_number, @customer_email, 
				isnull(@opt_in, 1), @customer_type_id, @vat_id, iif(@partner_id is null, @external_customer_key, null), @company_type_id, @salesforce_account_id, @salesforce_contact_id
			from dbo.fn_validate_country_state(default, @country, @state) vcs
			

			-- this is a hack until PHP always passes json to the procedure so ship_to customers will have the address added as ship_to
			if @customer_type_id = 2 and @site_id in ('WRCART', 'CSI')
				begin
					select @customer_json = dbo.fn_customer_variables_to_json(@customer_email, default, @first_name, @last_name, @phone_number, default, default, default, default, 
											default, default, default, default, default, default, @address_1, @address_2, @city, @state, @postal_code, @country, default, default, default, 
											default, default, iif(@partner_id is null, @external_customer_key, null), isnull(@opt_in, 1), @salesforce_contact_id, default)
				end
			else
				begin
					select @customer_json = dbo.fn_customer_variables_to_json(@customer_email, default, @first_name, @last_name, @phone_number, @address_1, @address_2, @city, @state, 
											@postal_code, @country, default, default, default, default, default, default, default, default, default, default, default, default, default, 
											default, default, iif(@partner_id is null, @external_customer_key, null), isnull(@opt_in, 1), @salesforce_contact_id, default)
				end

			select @company_json = dbo.fn_company_variables_to_json(default, @company_name, default, @company_type_id, @salesforce_account_id, @vat_id, default),
				@partner_json = dbo.fn_partner_variables_to_json(@partner_id, iif(@partner_id is not null, @external_customer_key, null), default)

			select @cart_customer_json = (select json_query(@customer_json, '$.customer') as [customer], json_query(@company_json, '$.company') as [company], 
										json_query(@partner_json, '$.partner') as [partner], N'cart_load' as [transaction_user] for json path, without_array_wrapper)

		END
        
	-- 1.5) parse json into table if provided
	else
		begin
			insert into @cart_customer_table 
(cart_order_id, first_name, last_name, bill_address_1, bill_address_2, bill_city, bill_state, bill_postal_code, bill_country, phone_number, 
						customer_email, opt_in, customer_type_id, external_customer_key, salesforce_contact_id)
			select @cart_order_id, cusj.first_name, cusj.last_name, cusj.bill_address_1, cusj.bill_address_2, cusj.bill_city, csv.state_id, cusj.bill_postal_code, 
					csv.country_iso3, cusj.phone_number, cusj.customer_email, isnull(cusj.opt_in, 1), @customer_type_id, cusj.vendor_customer_code, 
					cusj.salesforce_contact_id 
			from dbo.fn_customer_json_to_table(@cart_customer_json) cusj
			outer apply dbo.fn_validate_country_state(default, cusj.bill_country, cusj.bill_state) csv--state/country validation done here to match cart_customer table schema

			update @cart_customer_table
			set company_name = comj.company_name,
				company_type_id = comj.company_type_id,
				salesforce_account_id = comj.salesforce_account_id,
				vat_id = comj.vat_id
			from dbo.fn_company_json_to_table(@cart_customer_json) comj

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert new cart_customer record if previously null
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @cart_customer_id is null
		begin
			-- 2.1) cart_customer
			insert into cart_customer (cart_order_id, first_name, last_name, company_name, bill_address_1, bill_address_2, bill_city, bill_state, bill_postal_code, bill_country, phone_number, 
						customer_email, opt_in, customer_type_id, vat_id, external_customer_key, company_type_id, salesforce_account_id, salesforce_contact_id)
			select cct.cart_order_id, cct.first_name, cct.last_name, cct.company_name, cct.bill_address_1, cct.bill_address_2, cct.bill_city, cct.bill_state, cct.bill_postal_code, cct.bill_country, 
					cct.phone_number, cct.customer_email, cct.opt_in, cct.customer_type_id, cct.vat_id, cct.external_customer_key, cct.company_type_id, cct.salesforce_account_id, cct.salesforce_contact_id
			from @cart_customer_table cct
			
			select @cart_customer_id = scope_identity()

			-- 2.2) cart_customer_json
			insert into cart_customer_json (cart_customer_id, cart_customer_json)
			values (@cart_customer_id, @cart_customer_json)

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update if cart_customer record already exists
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	else
		begin
			-- 3.1) insert cart_customer_audit
			insert into cart_customer_audit(cart_customer_id, external_customer_key, first_name, last_name, company_name, customer_email, address_1, address_2, city, state, postal_code, 
											country, phone_number, opt_in, vat_id, customer_type_id, company_type_id, salesforce_account_id, salesforce_contact_id)
			select cc.cart_customer_id, cc.external_customer_key, cc.first_name, cc.last_name, cc.company_name, cc.customer_email, cc.bill_address_1, cc.bill_address_2, cc.bill_city, 
					cc.bill_state, cc.bill_postal_code, csv.country_iso, cc.phone_number, cc.opt_in, cc.vat_id, cc.customer_type_id, cc.company_type_id, cc.salesforce_account_id, 
					cc.salesforce_contact_id
			from cart_customer cc
				cross apply dbo.fn_validate_country_state(default, cc.bill_country, cc.bill_state) csv
			where cc.cart_customer_id = @cart_customer_id and cc.customer_type_id = @customer_type_id

			-- 3.2) insert ca
rt_customer
			update cart_customer
			set external_customer_key = cct.external_customer_key,
				first_name = cct.first_name,
				last_name = cct.last_name,
				company_name = cct.company_name,
				customer_email = cct.customer_email,
				bill_address_1 = cct.bill_address_1,
				bill_address_2 = cct.bill_address_2,
				bill_city = cct.bill_city,
				bill_state = cct.bill_state,
				bill_postal_code = cct.bill_postal_code,
				bill_country = cct.bill_country,
				phone_number = cct.phone_number,
				opt_in = cct.opt_in,
				vat_id = cct.vat_id,
				customer_type_id = cct.customer_type_id,
				company_type_id = cct.company_type_id,
				salesforce_account_id = cct.salesforce_account_id,
				salesforce_contact_id = cct.salesforce_contact_id,
				modified_date = getdate()			
			from @cart_customer_table cct
			where cart_customer.cart_customer_id = @cart_customer_id
			
			-- 3.3) update cart_customer_json
			update cart_customer_json
			set cart_customer_json = @cart_customer_json
			where cart_customer_id = @cart_customer_id

			if @@rowcount = 0
			begin
			insert into cart_customer_json (cart_customer_id, cart_customer_json)
			values (@cart_customer_id, @cart_customer_json)
			end

		end	
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @response_code = 0, @message = 'Success'

end try

begin catch

	set @message = 'cart_order_id = ' + convert(varchar(20), @cart_order_id) 
				+ ', vendor_order_code = ' + @vendor_order_code 
				+ ', customer_type_id = ' + convert(varchar(20), @customer_type_id)
				+ ': ' + error_message()

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_customer_in_process]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cart_update_cart_customer_in_process]

(
		@cart_in_process_id int,
		@first_name nvarchar(255),
        @last_name nvarchar(255),
        @address1 nvarchar(255),
        @address2 nvarchar(255),
        @city nvarchar(130),
        @state_id char(2),
        @postal_code nvarchar(32),
        @country_id int = null,
        @phone_number varchar(64),
        @company_name nvarchar(255),
        @customer_email nvarchar(255),
        @opt_in bit,
		@vat_id varchar(20) = null,
		@iso varchar(2) = null,
		@iso3 varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2009-02-23	esmart		Initial creation.
	2011-09-15	esmart		Extend input parameters
	2013-07-03	acoffel		extend vat_id into update

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @cart_customer_in_process_id int,
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @country_id
	if @country_id is null or @country_id = 0
		begin
		if @iso is not null
			begin
			select @country_id = country_id from lu_countries where iso = @iso
			end
		if @iso3 is not null
			begin
			select @country_id = country_id  from lu_countries where iso3 = @iso3
			end 
		end	
	
	-- 1.2) update
	update cart_customer_in_process
	set first_name = @first_name,
           last_name = @last_name,
           address1 = @address1,
           address2 = @address2,
           city = @city,
           state_id = @state_id,
           postal_code = @postal_code,
           country_id = @country_id,
           phone_number = @phone_number ,
           company_name = @company_name ,
           customer_email = @customer_email,
           opt_in = @opt_in,
		   vat_id = @vat_id
	where cart_in_process_id = @cart_in_process_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update cart_customer_in_process for @cart_in_process_id = ' + convert(varchar(20),@cart_in_process_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_discount]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_cart_discount]

(
		@cart_discount_id int,
		@cart_discount_description varchar(50),
		@cart_discount_type_id tinyint,
		@cart_discount_status_id tinyint = null, 
		@cart_discount_code varchar(20) = null, 
		@license_distribution_method_id int = null, 
		@specials_code_list varchar(100),
		@last_modified_by varchar(20),
		@response_code int output,
		@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2013-01-24	esmart		Allow removal of special code
	2014-08-04	esmart		Add license_distribution_method_id

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	begin try

	select @response_code = 0, @message = 'Item added to discount'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @cart_discount_description
	if (select count(*) from cart_discount where cart_discount_description = @cart_discount_description and cart_discount_id <> @cart_discount_id and cart_discount_status_id = 1) > 0
		begin
		select @message = 'Duplicate cart_discount_description', @response_code = -110
		--select message = @message, response_code = @response_code
		return
		end
		
	-- 1.2) @cart_discount_code
	if (select count(*) from cart_discount where cart_discount_code = @cart_discount_code and cart_discount_id <> @cart_discount_id and cart_discount_status_id = 1) > 0 and @cart_discount_code <> ''
		begin
		select @message = 'Duplicate cart_discount_code', @response_code = -120
		--select message = @message, response_code = @response_code
		return
		end
			
	-- 1.3) @specials_code_list
	if (select count(*) from cart_discount_specials_mapping m inner join (select char_value from dbo.fn_char_string_to_table(@specials_code_list)) t on m.specials_code = t.char_value where cart_discount_id <> @cart_discount_id) > 0 and @specials_code_list <> ''
		begin
		select @message = 'Duplicate specials_code_list', @response_code = -130
		--select message = @message, response_code = @response_code
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) cart_discount
	update cart_discount 
	set cart_discount_description = @cart_discount_description, 
		cart_discount_type_id = @cart_discount_type_id, 
		cart_discount_status_id = @cart_discount_status_id, 
		cart_discount_code = @cart_discount_code, 
		last_modified_by = @last_modified_by
	where cart_discount_id = @cart_discount_id
	
	-- 2.2) cart_discount_specials_mapping
	if @specials_code_list is not null and @specials_code_list <> ''
		begin
		delete from cart_discount_specials_mapping
		where cart_discount_id = @cart_discount_id

		insert into cart_discount_specials_mapping(cart_discount_id,specials_code)
		select @cart_discount_id,string_value from dbo.fn_string_to_table(@specials_code_list)
		end
	else if @specials_code_list = ''
		begin
		delete from cart_discount_specials_mapping
		where cart_discount_id = @cart_discount_id
		end

	-- 2.3) cart_discount_license_distribution_method
	if @license_distribution_method_id is not null and @license_distribution_method_id <> 0
		
begin
		delete from cart_discount_license_distribution_method where cart_discount_id = @cart_discount_id

		insert into cart_discount_license_distribution_method(cart_discount_id,license_distribution_method_id)
		values(@cart_discount_id,@license_distribution_method_id)
		end
	else
		begin
		delete from cart_discount_license_distribution_method where cart_discount_id = @cart_discount_id
		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_discount_item]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_cart_discount_item]

(
		@cart_discount_item_id int,
		@cart_discount_method_id tinyint, 
		@discount float, 
		@low_range float = null, 
		@high_range float = null,
		@product_type_id int, 
		@product_line_id int, 
		@license_category_id tinyint = null,
		@license_category_name varchar(20) = null, 
		@license_seats int = null, 
		@storage_gb int = null, 
		@years int = null, 
		@last_modified_by varchar(20),
		@language_code varchar(2) = null,
		@location_code varchar(3) = null		
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@cart_discount_id int,
			@currency varchar(50),
			@currency_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @language_code is null
		begin
		select @language_code = 'EN', @location_code = 'USA'
		end 

	select @currency_id = i.currency_id,
			@currency = i.currency_description
	from currency i
	inner join currency_language_location cl
		on i.currency_id = cl.currency_id
	where cl.language_code = @language_code and cl.location_code = @location_code

	select @cart_discount_id = cart_discount_id from cart_discount_item where cart_discount_item_id = @cart_discount_item_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) insert cart_discount
		
		update cart_discount_item
		set cart_discount_method_id = @cart_discount_method_id, 
			discount = @discount, 
			low_range = @low_range, 
			high_range = @high_range, 
			product_type_id = @product_type_id, 
			product_line_id = @product_line_id, 
			license_category_id = @license_category_id, 
			license_category_name = @license_category_name, 
			license_seats = @license_seats, 
			storage_gb = @storage_gb, 
			years = @years, 
			last_modified_by = @last_modified_by
		where cart_discount_item_id = @cart_discount_item_id
		 
	-- 2.2) insert cart_discount_item_discount
		if @cart_discount_method_id in (1,2)
			begin
			delete from cart_discount_item_discount where cart_discount_item_id = @cart_discount_item_id 

			insert cart_discount_item_discount(cart_discount_item_id, discount, language_code, location_code, currency, currency_id)
			values(@cart_discount_item_id, @discount, @language_code, @location_code, @currency, @currency_id)
			end

	-- 2.3) insert other currency discounts
		
		declare @lang_loc table (row_id int identity(1,1), language_code varchar(2), location_code varchar(3))

		insert into @lang_loc(language_code,location_code)
		select cl.language_code,cl.location_code
		from currency i
		inner join currency_language_location cl
			on i.currency_id = cl.currency_id
		where i.currency_id <> @currency_id

		declare @rows int, @row_id int

		select @rows = count(*), @row_id = 1 
		from @lang_loc

		while @rows >= @row_id
			begin
			select @language_code = language_code, @location_code = location_code from @lang_loc where row_id = @row_id
			exec usp_product_update_international_cart_discount @cart_discount
_method_id,@language_code,@location_code,@last_modified_by,@cart_discount_id
			select @row_id = @row_id + 1
			end

		select cart_discount_item_id = @cart_discount_item_id 

		
	-- 2.4) update licensing
		exec usp_licensing_insert_static_content_update 'discount'
	

	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_item]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_cart_item]

AS

/*	
	DATE			AUTHOR		REMARKS
	2017-05-02		acoffel		Initial creation.
		

	DESCRIPTION
	drtv item update
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert into cart_order_item_tax
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--1.1) insert into cart_order_item_tax
		insert into cart_order_item_tax (cart_order_item_id, tax_total_city_tax, tax_total_county_tax, tax_total_district_tax, tax_total_state_tax, tax_total_tax, insert_date)
		select ci.cart_order_item_id, d.cybscitytax, d.cybscountytax, d.cybsdistricttax, d.cybsstatetax, d.cybstotaltax, getdate()
		from order_item i
		inner join order_header h
			on i.order_header_id = h.order_header_id 
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join cart_order c
			on v.vendor_order_code = c.vendor_order_code
		inner join cart_order_item ci
			on c.cart_order_id = ci.cart_order_id
		inner join datawarehousereadonly.feed.dbo.drtv_item_detail d
			on v.vendor_order_code = d.webrootordernum
		left join [dbo].[cart_order_item_tax] t	
			on ci.cart_order_item_id = t.cart_order_item_id
		where t.cart_order_item_id is NULL

		--1.2) update item
		update i
		set i.item_total = d.totalcost,
			i.tax = d.cybstotaltax, 
			i.modified_date = getdate(),
			i.modified_by = 'acoffel'
		from order_item i
		inner join order_header h
			on i.order_header_id = h.order_header_id 
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join cart_order c
			on v.vendor_order_code = c.vendor_order_code
		inner join cart_order_item ci
			on c.cart_order_id = ci.cart_order_id
		inner join datawarehousereadonly.feed.dbo.drtv_item_detail d
			on v.vendor_order_code = d.webrootordernum

		--1.3) update header
		update h
		set h.total_amount = d.totalcost,
			h.tax_total = d.cybstotaltax, 
			h.modified_date = getdate(),
			h.modified_by = 'acoffel'
		from order_item i
		inner join order_header h
			on i.order_header_id = h.order_header_id 
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join cart_order c
			on v.vendor_order_code = c.vendor_order_code
		inner join cart_order_item ci
			on c.cart_order_id = ci.cart_order_id
		inner join datawarehousereadonly.feed.dbo.drtv_item_detail d
			on v.vendor_order_code = d.webrootordernum

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_item_tax]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_cart_item_tax]

(
		@cart_order_id INT = NULL,
		@cart_order_tax_json VARCHAR(MAX) = NULL,
		@line_item INT = NULL,
		@tax_total_city_tax MONEY = NULL,
		@tax_total_county_tax MONEY = NULL,
		@tax_total_district_tax MONEY = NULL,
		@tax_total_state_tax MONEY = NULL,
		@tax_total_grand MONEY = NULL,
		@local_tax MONEY = NULL,
		@reset_item BIT = NULL

)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2013-06-17	esmart		Fix line_item and 0 tax issue
	2013-06-18	esmart		Fix VAT rounding
	2013-12-06	esmart		Vat calculation change
	2015-07-06	esmart		Fix tax calc for VAT for SMB
	2017-01-09	acoffel		product_line_cart_type change
	2017-03-02	esmart		Add update to in_process tax data
	2017-09-05	acoffel		Deprecate XML 
	2017-10-03	acoffel		item handling
	2017-10-08	acoffel		new quantity handling
	2018-07-26	acoffel		new cart
	2018-08-07	acoffel		reset items
	2019-03-11	acoffel		fix NULLS
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the cart_order_item_audit
	2023-05-03  psatish		ECOM-899 Added storage_GB in the cart_order_item_audit table
	2025-02-20  psatish		US-4387875 Commented out section 1.3 and modified section 1.1 to get the tax rates from the  
							lu_states table if it exists
	2025-10-14	jberry		US-5004939 - Added table variable @cart_order_item_actual_storage_quantity and moved @cart_order_item_tax to the top 
							-- Added sec 1.3 to get actual storage quantity for each cart order item for capacity orders
							-- Updated sec 1.4, 1.5 and 2.2 to use the actual storage quantity to reset pricing for capacity items in the cart
							-- Made general changes to fix section numbering and remove unneeded debug code

	DESCRIPTION
	update item tax 
*/

AS
	SET NOCOUNT ON				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON				

	DECLARE	@vat_rate FLOAT,	
			@tax_xml XML,
			@min_line_item INT,
			@product_line_cart_type VARCHAR(20),
			@vat_id VARCHAR(20),
			@site_id VARCHAR(65),
			@country_id INT,
			@merchant_id VARCHAR(20),
			@response_code INT,
			@message VARCHAR(100)

	DECLARE @cart_order_item_tax TABLE
	(
		cart_order_item_id INT,
		line_item INT,
		unit_price MONEY DEFAULT 0,
		tax_total_city_tax MONEY DEFAULT 0,
		tax_total_county_tax MONEY DEFAULT 0,
		tax_total_district_tax MONEY DEFAULT 0,
		tax_total_state_tax MONEY DEFAULT 0,
		tax_total_tax MONEY
			DEFAULT 0,
		local_tax MONEY
			DEFAULT 0
	);

	DECLARE @cart_order_item_actual_storage_quantity TABLE
	(
		cart_order_id INT,
		cart_order_item_id INT,
		actual_storage_quantity DECIMAL(12, 5)
	);

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @vat_rate and @vat_id
	IF EXISTS (SELECT cart_customer_id FROM cart_customer WHERE cart_order_id = @cart_order_id AND customer_type_id = 2) 
		BEGIN
		   	SELECT @vat_rate = CASE WHEN lc.vat_rate = 0 THEN ls.vat_rate ELSE lc.vat_rate END,
			       @vat_id = c.vat_id,
			       @country_id = lc.country_id
			FROM cart_customer c
			    INNER JOIN lu_countries lc
			        ON c.bill_country = lc.iso3
			    LEFT JOIN dbo.lu_states ls
			        ON ls.iso2 = lc.iso
			           AND c.bill_state = ls.state_id
			WHERE c.cart_order_id = @cart_order_id
			      AND c.customer_type_id = 2
		END
	ELSE
		BEGIN

		   	SELECT @vat_rate = CASE WHEN lc.vat_rate = 0 THEN ls.vat_rate ELSE lc.vat_rate END,
			       @vat_id = c.vat_id,
			       @country_id = lc.country_id
			FROM cart_customer c
			    INNER JOIN lu_countries lc
			        ON c.bill_country = lc.iso3
			    LEFT JOIN dbo.lu_states ls
			        ON ls.iso2 = lc.iso
			           AND c.bill_state = ls.state_id
			WHERE c.cart_order_id = @cart_order_id
			      AND c.customer_type_id = 1
		END
		
	-- 1.2) @merchant_id
	SELECT @merchant_id = merchant_id 
	FROM cart_order_in_process p 
	INNER JOIN cart_order c 
		ON p.cart_order_in_process_id = c.cart_order_in_process_id 
	WHERE cart_order_id = @cart_order_id
	
	-- 1.3) get actual storage quantity for each cart order item for capacity orders
	INSERT INTO @cart_order_item_actual_storage_quantity
	(
	    cart_order_id,
	    cart_order_item_id,
	    actual_storage_quantity
	)
	SELECT coi.cart_order_id, coi.cart_order_item_id, JSON_VALUE(coij.cart_order_item_json, '$.actual_storage_quantity')
	FROM dbo.cart_order_item coi
	    INNER JOIN dbo.cart_order_item_json coij 
		    ON coij.cart_order_item_id = coi.cart_order_item_id
	WHERE coi.cart_order_id = @cart_order_id
	AND JSON_VALUE(coij.cart_order_item_json, '$.usage_pricing_model_id') = 2
	
	-- 1.4) reset items
	DECLARE @tax_amount MONEY, @total_amount MONEY, @sub_total_amount MONEY

	IF @reset_item = 1
		BEGIN
			INSERT INTO cart_order_item_audit (cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, audit_date, cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, sap_material_number, storage_gb)
			SELECT cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, GETDATE(), cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, i.sap_material_number, i.storage_gb
			FROM cart_order_item i
			WHERE i.cart_order_id = @cart_order_id

			UPDATE i
			SET i.tax_item_total = 0,
				i.unit_price = i.unit_price_pre_vat,
				i.modified_date = GETDATE(),
				i.modified_by = 'update_tax_reset'
			FROM cart_order_item i
			INNER JOIN product_line_product p
				ON i.product_id = p.product_id
			INNER JOIN product_line pl
				ON p.product_line_id = pl.product_line_id
			WHERE i.cart_order_id = @cart_order_id
			
			SELECT @tax_amount = SUM(tax_item_total), @total_amount = SUM((unit_price*quantity)+tax_item_total), @sub_total_amount = SUM(unit_price*quantity)
			FROM cart_order_item
			WHERE cart_order_id = @cart_order_id

			IF EXISTS (SELECT 1 FROM @cart_order_item_actual_storage_quantity)
			BEGIN
				SELECT @total_amount = SUM((coi.unit_price * coiasc.actual_storage_quantity) + coi.tax_item_total),
					   @sub_total_amount = SUM(coi.unit_price * coiasc.actual_storage_quantity)
				FROM dbo.cart_order_item coi
					JOIN @cart_order_item_actual_storage_quantity coiasc
						ON coiasc.cart_order_item_id = coi.cart_order_item_id;
			END

			update cart_order
			set tax_amount = @tax_amount, total_amount = @total_amount,  sub_total_amount = @sub_total_amount
				where cart_order_id = @cart_order_id
			
			RETURN
		END
        
	SELECT @min_line_item = MIN(line_item) FROM cart_order_item WHERE cart_order_id = @cart_order_id

	IF @line_item IS NOT NULL AND @vat_rate = 0 --or @site_id not in ('WRENTERPRISECART') @tax_xml_string <> '' and @tax_xml_string is not null and 
		BEGIN	
			INSERT INTO @cart_order_item_tax(cart_order_ite
m_id, line_item, tax_total_city_tax, tax_total_county_tax, tax_total_district_tax, tax_total_state_tax, tax_total_tax, local_tax)
			SELECT NULL, @line_item, @tax_total_city_tax , @tax_total_county_tax, @tax_total_district_tax, @tax_total_state_tax, @tax_total_grand, @local_tax 
	
			UPDATE @cart_order_item_tax
			SET cart_order_item_id = i.cart_order_item_id
			FROM cart_order_item i
			INNER JOIN @cart_order_item_tax t
				ON i.line_item = t.line_item
			WHERE cart_order_id = @cart_order_id

		END
		
	-- 1.5) calculate vat rate
	IF @vat_rate <> 0
		BEGIN		
			INSERT INTO cart_order_item_audit (cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, audit_date, cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, sap_material_number, storage_gb)
			SELECT cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, GETDATE(), cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, i.sap_material_number, i.storage_gb
			FROM cart_order_item i
			WHERE i.cart_order_id = @cart_order_id

			UPDATE i
			SET i.tax_item_total = 0,
				i.unit_price = i.unit_price_pre_vat,
				i.modified_date = GETDATE(),
				i.modified_by = 'update_tax_vat'
			FROM cart_order_item i
			INNER JOIN product_line_product p
				ON i.product_id = p.product_id
			INNER JOIN product_line pl
				ON p.product_line_id = pl.product_line_id
			WHERE i.cart_order_id = @cart_order_id

			INSERT INTO @cart_order_item_tax(cart_order_item_id, line_item, unit_price, tax_total_tax)
			SELECT i.cart_order_item_id, i.line_item, 
				unit_price = CASE 
								WHEN pl.product_line_cart_type = 'enterprise' THEN i.unit_price
								ELSE ROUND(i.unit_price/(1.0+@vat_rate),2)
							END,
				tax_item_total = CASE 
									WHEN pl.product_line_cart_type = 'enterprise' AND coiasc.cart_order_item_id IS NULL THEN ROUND(((i.unit_price*i.quantity) * @vat_rate),2)
									when pl.product_line_cart_type = 'enterprise' AND coiasc.cart_order_item_id IS NOT NULL THEN ROUND(((i.unit_price*coiasc.actual_storage_quantity) * @vat_rate),2)
									ELSE ROUND(i.unit_price - ROUND(i.unit_price/(1.0+@vat_rate),2),2)
							END
			FROM dbo.cart_order_item i
			INNER JOIN dbo.product_line_product p
				ON i.product_id = p.product_id
			INNER  JOIN dbo.product_line pl
				ON p.product_line_id = pl.product_line_id
			LEFT JOIN @cart_order_item_actual_storage_quantity coiasc 
				ON coiasc.cart_order_item_id = i.cart_order_item_id
			WHERE i.cart_order_id = @cart_order_id
			END

		select @product_line_cart_type = pl.product_line_cart_type
		from cart_order_item i
		inner join product_line_product p
			on i.product_id = p.product_id
		inner join product_line pl
			on p.product_line_id = pl.product_line_id
		where i.cart_order_id = @cart_order_id		

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) remove existing tax records
	IF @line_item IS NOT NULL OR @vat_rate <> 0
		BEGIN 
			INSERT INTO cart_order_item_tax_audit (cart_order_item_tax_id,cart_order_item_id, tax_total_city_
tax,tax_total_county_tax,tax_total_district_tax,tax_total_state_tax, tax_total_tax, insert_date, local_tax)
			SELECT cart_order_item_tax_id, cart_order_item_id, tax_total_city_tax,tax_total_county_tax,tax_total_district_tax,tax_total_state_tax, tax_total_tax,insert_date, local_tax
			FROM cart_order_item_tax 
			WHERE cart_order_item_id IN (SELECT cart_order_item_id FROM @cart_order_item_tax) 

			DELETE FROM cart_order_item_tax
			WHERE cart_order_item_id IN (SELECT cart_order_item_id FROM @cart_order_item_tax)

			-- 2.2) insert cart_order_item_tax
			INSERT cart_order_item_tax(cart_order_item_id, tax_total_city_tax, tax_total_county_tax, tax_total_district_tax, tax_total_state_tax, tax_total_tax, local_tax)
			SELECT cart_order_item_id, ISNULL(tax_total_city_tax,0), ISNULL(tax_total_county_tax,0), ISNULL(tax_total_district_tax,0), ISNULL(tax_total_state_tax,0), ISNULL(tax_total_tax,0), ISNULL(local_tax,0)
			FROM @cart_order_item_tax

			INSERT INTO cart_order_item_audit (cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, audit_date, cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, sap_material_number, storage_gb)
			SELECT cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total, product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, GETDATE(), cart_discount_id, cart_discount_method_id, discount, unit_price_pre_vat, i.sap_material_number, i.storage_gb
			FROM cart_order_item i
			WHERE i.cart_order_id = @cart_order_id

			UPDATE cart_order_item
			SET tax_item_total = t.tax_total_tax,
				modified_date = GETDATE(),
				modified_by = 'update_tax_2.1'
			FROM cart_order_item_tax t
			INNER JOIN cart_order_item i
				ON t.cart_order_item_id = i.cart_order_item_id
			WHERE cart_order_id = @cart_order_id
		
		END

	--if @merchant_id = 'webroot' and @country_id <> 1
	--	begin 
	--		update cart_order_item
	--		set tax_item_total = 0
	--		from cart_order_item_tax t
	--		inner join cart_order_item i
	--			on t.cart_order_item_id = i.cart_order_item_id
	--		where cart_order_id = @cart_order_id
	--	end

	--SELECT @line_item, @vat_rate return 

	-- 2.2) update cart_order
	IF @line_item IS NULL --and @vat_rate <> 0
		BEGIN 			
			IF @vat_rate = 0
				BEGIN 
					SELECT @tax_amount = SUM(tax_item_total), @total_amount = SUM((unit_price*quantity)+tax_item_total), @sub_total_amount = SUM(unit_price*quantity)
					FROM cart_order_item
					WHERE cart_order_id = @cart_order_id

					IF EXISTS (SELECT 1 FROM @cart_order_item_actual_storage_quantity)
					BEGIN
							SELECT @total_amount = SUM((coi.unit_price * coiasc.actual_storage_quantity) + coi.tax_item_total),
								   @sub_total_amount = SUM(coi.unit_price * coiasc.actual_storage_quantity)
							FROM dbo.cart_order_item coi
								JOIN @cart_order_item_actual_storage_quantity coiasc
									ON coiasc.cart_order_item_id = coi.cart_order_item_id;
					END
				END
				ELSE
				BEGIN 
					SELECT @tax_amount = SUM(tax_item_total), @total_amount = SUM((unit_price*quantity)+tax_item_total), @sub_total_amount = SUM(unit_price*quantity)
					FROM cart_order_item
					WHERE cart_order_id = @cart_order_id

					IF EXISTS (SELECT 1 FROM @cart_order_item_actual_storage_quantity)
					BEGIN					
					SELECT @total_amount = SUM((coi.unit_price * coiasc.actual_storage_quantity) + coi.tax_item_total),
						   @sub_total_amount = SUM(coi.unit_price * coiasc.actual_storage_quantity)
					FROM dbo.cart_o
rder_item coi
						JOIN @cart_order_item_actual_storage_quantity coiasc
							ON coiasc.cart_order_item_id = coi.cart_order_item_id;
					END

					if @product_line_cart_type <> 'enterprise' --and (select count(*) from cart_order_item where cart_order_id = @cart_order_id and unit_price < list_price) = 0
						begin
							select @sub_total_amount = @sub_total_amount - @tax_amount
							select @total_amount = @total_amount - @tax_amount
							update cart_order_item set unit_price = unit_price - tax_item_total where cart_order_id = @cart_order_id

							update cart_order
							set tax_amount = @tax_amount, total_amount = @total_amount,  sub_total_amount = ISNULL(@sub_total_amount,0)
							where cart_order_id = @cart_order_id	
						end
						else
						begin 
							update cart_order
							set tax_amount = @tax_amount, total_amount = @total_amount,  sub_total_amount = ISNULL(@sub_total_amount,0)
							where cart_order_id = @cart_order_id
						end	
				END
			
			if @vat_rate = 0 or @vat_rate is null
			begin
				update cart_order
				set tax_amount = @tax_amount, total_amount = @total_amount,  sub_total_amount = ISNULL(@sub_total_amount,0)
				where cart_order_id = @cart_order_id	
			end
            

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update in_process cart
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
			--update cart_order_item_in_process
			--set tax_item_total = i.tax_item_total
			--from cart_order_item_in_process ip
			--inner join cart_order_item i
			--	on i.cart_order_item_in_process_id = ip.cart_order_item_in_process_id
			--where i.cart_order_id = @cart_order_id

			--update cart_order_in_process
			--set tax_amount = c.tax_amount, total_amount = c.sub_total_amount + c.tax_amount
			--from cart_order_in_process cp
			--inner join cart_order c
			--	on c.cart_order_in_process_id = cp.cart_order_in_process_id
			--where c.cart_order_id = @cart_order_id

			insert into cart_order_tax_json (cart_order_id, cart_order_tax_json, insert_date)
			select @cart_order_id, @cart_order_tax_json, getdate()
			
		end

	end try

	begin catch
		
		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_cart_order]
-- =============================================================================




create procedure [dbo].[usp_cart_update_cart_order]

(
		@vendor_order_code varchar(100),
		@cart_extension_json nvarchar(max),
		@response_code int output,
		@message varchar(100) output	
)

/*	
	DATE		AUTHOR		REMARKS
	2019-10-02	esmart		Initial creation.

	DESCRIPTION
	update cart order
*/

as
	set nocount on
	
begin try

	declare	@cart_order_id int,
			@insert_date datetime
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		select @insert_date = getdate()

		
		-- 1.1) @cart_order_id
		select @cart_order_id = cart_order_id
		from cart_order
		where vendor_order_code = @vendor_order_code


		-- 1.2) cart_json_audit
		insert into cart_json_audit (cart_json_id, cart_json, cart_order_id, cart_order_in_process_id, audit_date)
		select cart_json_id, cart_json, cart_order_id, cart_order_in_process_id, @insert_date 
		from cart_json
		where cart_order_id = @cart_order_id

		update cart_json
		set cart_json = @cart_extension_json
		where cart_order_id = @cart_order_id

		select @response_code = 0, @message = 'Success'

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert cart_order failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;







GO
