-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_update_cart_order_customer_in_process]

(
		@cart_order_in_process_id int,
		@first_name nvarchar(255),
        @last_name nvarchar(255),
        @company_name nvarchar(255),
        @address_1 nvarchar(255),
        @address_2 nvarchar(255),
        @city nvarchar(130),
        @state char(2),
        @postal_code nvarchar(32),
        @country_id int,
        @phone_number varchar(64),
        @customer_email nvarchar(255),
        @opt_in bit,
		@customer_type_id int = null,
		@vat_id varchar(20) = null,
		@external_customer_key varchar(100) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2009-02-23	esmart		Initial creation.
	2013-03-12	esmart		@customer_type_id
	2013-07-03	acoffel		extended vat_id into sp
	2014-03-05	esmart		Add @external_customer_key
	2018-03-08	acoffel		VAT fixes

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @cart_order_customer_in_process_id int,
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @customer_type_id is null
		begin
		select @customer_type_id = 1
		end

	-- 1.1) @cart_order_customer_in_process_id
	select @cart_order_customer_in_process_id = cart_order_customer_in_process_id
	from cart_order_customer_in_process
	where cart_order_in_process_id = @cart_order_in_process_id and customer_type_id = @customer_type_id
	
	if @cart_order_customer_in_process_id is null
	-- 1.2) insert new cart_order_customer_in_process
		begin
		insert into cart_order_customer_in_process(cart_order_in_process_id, first_name, last_name, company_name, address_1, address_2, city, state, postal_code, country_id, phone_number, customer_email, opt_in, customer_type_id, vat_id, external_customer_key)
		values(@cart_order_in_process_id, @first_name, @last_name, @company_name, @address_1, @address_2, @city, @state, @postal_code, @country_id, @phone_number, @customer_email, @opt_in, @customer_type_id, @vat_id, @external_customer_key)
		end
	else
		begin
	-- 1.3) update cart_order_customer_in_process
		update cart_order_customer_in_process
		set first_name = @first_name,
			last_name = @last_name,
			company_name = @company_name ,
			address_1 = @address_1,
			address_2 = @address_2,
			city = @city,
			state = @state,
			postal_code = @postal_code,
			country_id = @country_id,
			phone_number = @phone_number ,
			customer_email = @customer_email,
			opt_in = @opt_in,
			customer_type_id = @customer_type_id,
			vat_id = @vat_id,
			external_customer_key = @external_customer_key,
			last_modified_date = getdate()
		where cart_order_customer_in_process_id = @cart_order_customer_in_process_id
		end
	

	if @vat_id is not NULL and @country_id <> 1
	-- 1.4) clear tax
		begin
			update co
			set co.total_amount = co.total_amount - co.tax_amount
			from cart_order_item_in_process i
			inner join cart_order_in_process p
				on i.cart_order_in_process_id = p.cart_order_in_process_id
			inner join cart_order co
				on p.cart_order_in_process_id = co.cart_order_in_process_id
			where p.cart_order_in_process_id = @cart_order_in_process_id
			update p
			set p.total_amount = p.total_amount - p.tax_amount
			from cart_order_item_in_process i
			inner join cart_order_in_process p
				on i.cart_order_in_process_id = p.cart_order_in_process_id
			inner join cart_order co
				on p.cart_order_in_process_id = co.cart_order_in_process_id
			where p.cart_order_in_process_i
d = @cart_order_in_process_id
			update co
			set co.tax_amount = 0
			from cart_order_item_in_process i
			inner join cart_order_in_process p
				on i.cart_order_in_process_id = p.cart_order_in_process_id
			inner join cart_order co
				on p.cart_order_in_process_id = co.cart_order_in_process_id
			where p.cart_order_in_process_id = @cart_order_in_process_id
			update p
			set p.tax_amount = 0
			from cart_order_item_in_process i
			inner join cart_order_in_process p
				on i.cart_order_in_process_id = p.cart_order_in_process_id
			inner join cart_order co
				on p.cart_order_in_process_id = co.cart_order_in_process_id
			where p.cart_order_in_process_id = @cart_order_in_process_id
		end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update cart_customer_in_process for @cart_order_in_process_id = ' + convert(varchar(20),@cart_order_in_process_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 
	


GO
