-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_update_cart_order_in_process]

(
	@cart_order_in_process_id int,
	@vendor_order_code varchar(100),
	@order_type varchar(20),
	@site_id varchar(20),
	@site_url varchar(20),
	@p_rc varchar(20),  
	@p_rsc varchar(36), 
	@p_ac varchar(20), 
	@trx_rc varchar(20),  
	@trx_rsc varchar(36), 
	@trx_ac varchar(20), 
	@total_amount money, 
	@sub_total_amount money, 
	@offer_amount money, 
	@tax_amount money,
	@session_id bigint,
	@user_ip varchar(16),
	@submission_date datetime,
	@locale char(5),
	@cart_order_in_process_status_id tinyint,
	@currency_id tinyint,
	@customer_profile_token varchar(24),
	@cart_extension_json nvarchar(max) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-25	esmart		Initial creation.
	2016-06-09	acoffel		Keep agent info when cart comes back in on a quote
	2016-08-02	blu			Added cart_json.

	DESCRIPTION
	select discount
*/

AS
	set nocount on				
				
	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @cart_order_in_process_id is null or @cart_order_in_process_id = 0
	begin
		insert into cart_order_in_process(vendor_order_code, order_type, site_id, site_url, p_rc, p_rsc, p_ac, trx_rc, trx_rsc, trx_ac, total_amount, sub_total_amount, offer_amount, tax_amount, session_id, user_ip, submission_date, locale, last_modified_date, last_modified_by, cart_order_in_process_status_id, currency_id, customer_profile_token)
		values(@vendor_order_code, @order_type, @site_id, @site_url, @p_rc, @p_rsc, @p_ac, @trx_rc, @trx_rsc, @trx_ac, @total_amount, @sub_total_amount, @offer_amount, @tax_amount, @session_id, @user_ip, @submission_date, @locale, getdate(), suser_sname(), @cart_order_in_process_status_id, @currency_id, @customer_profile_token)

		select @cart_order_in_process_id = scope_identity()

		if @cart_extension_json is not null
			begin
				insert into cart_json (cart_json,cart_order_in_process_id)
				values (@cart_extension_json, @cart_order_in_process_id)
			end
		else
			begin
				insert into cart_json (cart_json,cart_order_in_process_id)
				values ('', @cart_order_in_process_id)
			end
	end
	else
	begin
		update cart_order_in_process
		set vendor_order_code = @vendor_order_code, 
			order_type = @order_type, 
			site_id = @site_id, 
			site_url = @site_url, 
			p_rc = case when @site_id = 'CSI' then p_rc else @p_rc end, 
			p_rsc = @p_rsc, 
			p_ac = @p_ac, 
			trx_rc = @trx_rc, 
			trx_rsc = @trx_rsc, 
			trx_ac = @trx_ac, 
			offer_amount = @offer_amount,
			total_amount = @total_amount, 
			sub_total_amount = @sub_total_amount, 
			tax_amount = @tax_amount, 
			session_id = @session_id, 
			user_ip = @user_ip, 
			submission_date = @submission_date, 
			locale = @locale, 
			last_modified_date = getdate(), 
			last_modified_by = suser_sname(), 
			cart_order_in_process_status_id = @cart_order_in_process_status_id, 
			currency_id = @currency_id, 
			customer_profile_token = @customer_profile_token
		where cart_order_in_process_id = @cart_order_in_process_id

		if @cart_extension_json is not null
			begin
				update cart_json
				set cart_json = @cart_extension_json
				where cart_order_in_process_id = @cart_order_in_process_id
			end
	end

	select cart_order_in_process_id = @cart_order_in_process_id
		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @
message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
