-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_disable_autorenewal]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_update_disable_autorenewal]

(
        @order_header_id int,
		@csi_user_id varchar(50),
		@comment varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-04-30	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

begin try

	declare @license_id int,
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) create table and insert rows
		declare @update_license table 
				(
				update_id int identity(1,1) not null,
				license_id int not null
				)

		insert into @update_license (license_id)
		select distinct il.license_id
		from order_item i
		inner join order_item_license il
			on i.order_item_id = il.order_item_id
		where i.order_header_id = @order_header_id

	-- 1.2) loop through rows to complete update 

		declare @update_id int,
				@last_update_id int

		select @update_id = min(update_id), @last_update_id = max(update_id) 
		from @update_license

		while @update_id <= @last_update_id
			begin
		
			select @license_id = license_id from @update_license where update_id = @update_id
--			select license_id = @license_id
			
			exec usp_license_update_disable_autorenewal @license_id,@csi_user_id,@comment

			select @update_id = @update_id + 1
			end
	

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update licenses for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_order_license]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cart_update_order_license]

(

		@order_header_id int,
		@order_type_group_id int,
		@account_order_json varchar(max) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2009-03-10		esmart		Initial creation.
	2010-01-12		esmart		Add check to insert to exclude license_type of OEM or Trial
	2011-03-16		acoffel		extended expiration_date into order_item
	2011-03-31		esmart		Add license_message update
	2014-09-05		esmart		Add order_item_update_type_id
	2015-04-02		acoffel		Added license channel
	2015-07-31		esmart		partner_license 
	2016-01-08		esmart		extend @order_entity_approval
	2016-02-10		esmart		Restrict order_item update when SFDC order
	2016-07-26		esmart		Move module product update to the last step in processing
	2016-12-16		esmart		Make updates to order_item default
	2017-01-26		esmart		order_item.effective_date fix
	2017-03-10		blu			Modified @update_license to look for order_item_status_id = 3 for refunds instead of quantity < 0.
	2017-04-06		esmart		partner_license enhancements
	2017-04-07		cnovac		Fixed and i.quantity < 0 which got written over with push of code on 4/6/2017
	2017-05-16		esmart		Change use of start/end date on partner_license
	2017-08-24		esmart		usp_cart_update_order_license_new
	2018-06-11		esmart		Add CBCART,CSI,WRCART,WRENTERPRISECART to trigger new update proc
	2018-07-17		cnovac		Added @account_order_json which will be passed in for WIFI orders

	DESCRIPTION
	
*/

AS
	set nocount on				

begin try

	declare @product_id int,
			@product_type_id int,
			@keycode varchar(40),
			@order_item_id int,
			@license_id int,
			@effective_date datetime,
			@capability_expiration_date datetime,
			@capability_id int,
			@license_id_check int,
			@license_channel_id int,
			@gsm int,
			@license_type_id int,
			@product_line_id int,
			@license_category_id int,
			@process_date datetime,
			@sky_template_id tinyint,
			@order_item_update_type_id tinyint,
			
			@partner_license_id int,
			@order_partner_id int,
			@order_entity_approval varchar(500),
			@license_partner_id int,
			@license_entity_approval varchar(20),
			@pending_license_partner_id int,
			@pending_entity_approval varchar(20),
			@partner_license_status_id tinyint, 
			@partner_license_source_id tinyint, 
			@comment nvarchar(max),
			@last_modified_user_id varchar(20), 
			@license_transaction varchar(max),
			@site_id varchar(65),
			@vendor_order_code varchar(100),

			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get license data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @site_id
	select @site_id = site_id, @vendor_order_code = v.vendor_order_code
	from order_header h
	inner join vendor_order v
		on v.vendor_order_id = h.vendor_order_id
	where order_header_id = @order_header_id

		-- 1.1.1) call new cart license update
		if @site_id in ('MSP','RESELLER','SFDC','CBCART','CSI','WRCART','WRENTERPRISECART', 'APPLESTORE', 'GOOGLEANDROID','AUTORENEWAL')
			begin
			set @account_order_json = nullif(ltrim(rtrim(@account_order_json)), '')
			exec usp_cart_update_order_license_new @vendor_order_code = @vendor_order_code, @account_order_json = @account_order_json
			return
			end

	-- 1.1) create table and insert rows
		declare @update_license table (update_id int identity(1,1) not null,product_id int not null,keycode varchar(40) not null,order_header_i
d int not null,order_item_id int not null,license_id int,license_type_id int,product_line_id int,order_item_update_type_id tinyint)

		if @order_type_group_id = 1
			begin
			insert into @update_license (product_id, keycode, order_header_id, order_item_id, license_id, license_type_id, product_line_id, order_item_update_type_id)
			select i.product_id, l.keycode, i.order_header_id, i.order_item_id, il.license_id, l.license_type_id, l.product_line_id, i.order_item_update_type_id
			from order_item i with (nolock)
			inner join product p with (nolock)
				on i.product_id = p.product_id
			inner join order_item_license il with (nolock)
				on i.order_item_id = il.order_item_id
			inner join license l	 with (nolock)
				on il.license_id = l.license_id
			where i.order_header_id = @order_header_id and p.product_type_id <> 4
			order by p.product_type_id desc, p.product_id

			insert into @update_license (product_id, keycode, order_header_id, order_item_id, license_id, license_type_id, product_line_id, order_item_update_type_id)
			select i.product_id, l.keycode, i.order_header_id, i.order_item_id, il.license_id, l.license_type_id, l.product_line_id, i.order_item_update_type_id
			from order_item i with (nolock)
			inner join product p with (nolock)
				on i.product_id = p.product_id
			inner join order_item_license il with (nolock)
				on i.order_item_id = il.order_item_id
			inner join license l	 with (nolock)
				on il.license_id = l.license_id
			where i.order_header_id = @order_header_id and p.product_type_id = 4
			order by p.product_type_id desc, p.product_id
			end
		else 
			begin
			insert into @update_license (product_id, keycode, order_header_id, order_item_id, license_id, license_type_id, product_line_id, order_item_update_type_id)
			select i.product_id, l.keycode, i.order_header_id, i.order_item_id, il.license_id, l.license_type_id, l.product_line_id, i.order_item_update_type_id
			from order_item i with (nolock)
			inner join product p with (nolock)
				on i.product_id = p.product_id
			inner join order_item_license il with (nolock)
				on i.order_item_id = il.order_item_id
			inner join license l	 with (nolock)
				on il.license_id = l.license_id
			where i.order_header_id = @order_header_id and i.order_item_status_id = 3
			order by p.product_type_id, p.product_id desc
			end

	-- 1.2) partner
	select @order_partner_id = case 
									when p.partner_id is not null then p.partner_id 
									else null
								end,
			@order_entity_approval = case 
									when pc.configuration_value is null then 'Open'
									else pc.configuration_value
								end
	from order_header h
	inner join partner_order p
		on h.order_header_id = p.order_header_id
	inner join partner_configuration_partner pc
		on p.partner_id = pc.partner_id and pc.partner_configuration_id = 4
	where h.order_header_id = @order_header_id


	-- select order_partner_id = @order_partner_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		declare @update_id int,
				@last_update_id int
				
		select @update_id = min(update_id), @last_update_id = max(update_id) 
		from @update_license

		while @update_id <= @last_update_id
			begin
			
			-- 2.1) get values
			select @product_id = u.product_id, 
					@product_type_id = p.product_type_id,
					@license_id = u.license_id, 
					@keycode = u.keycode, 
					@order_item_id = u.order_item_id, 
					@license_type_id = u.license_type_id, 
					@product_line_id = u.product_line_id,
					@order_item_update_type_id = u.order_item_update_type_id
			from @update_lice
nse u
			inner join product p
				on u.product_id = p.product_id
			where update_id = @update_id

			if @order_item_update_type_id is null
				begin
				select @order_item_update_type_id = 1
				end

			-- 2.2) partner_license
			select @license_partner_id =  pl.partner_id,
					@license_entity_approval = case 
													when pc.configuration_value is null then 'Open'
													else pc.configuration_value
												end
			from partner_license pl
			left join partner_configuration_partner pc
				on pl.partner_id = pc.partner_id and pc.partner_configuration_id = 4
			where pl.license_id = @license_id and pl.partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))

			select @pending_license_partner_id =  pl.partner_id,
					@pending_entity_approval = case 
													when pc.configuration_value is null then 'Open'
													else pc.configuration_value
												end
			from partner_license pl
			left join partner_configuration_partner pc
				on pl.partner_id = pc.partner_id and pc.partner_configuration_id = 4
			where pl.license_id = @license_id and pl.partner_license_status_id = 1

			select @last_modified_user_id = 'order_license_update'

			select @partner_license_source_id = case
													when site_id in ('PARTNERSERVICE') then 2
													when site_id in ('MSP','RESELLER') then 3
													else 5
												end
			from order_header 
			where order_header_id = @order_header_id

			--select license_partner_id = @license_partner_id, license_entity_approval = @license_entity_approval, pending_license_partner_id = @pending_license_partner_id, pending_entity_approval = @pending_entity_approval, order_partner_id = @order_partner_id, order_entity_approval = @order_entity_approval
			--return

			if @license_entity_approval is not null or @pending_entity_approval is not null or @order_entity_approval is not null
				begin

				if @order_partner_id is null and @product_line_id in (300,55)
					begin
					select @order_partner_id = 5559
					end

				-- 2.2.1) partner change
				if @license_partner_id is not null and (@license_partner_id <> @order_partner_id)
					begin
					-- 2.2.1.1) @order_item_update_type_id
					select @order_item_update_type_id = 2, @partner_license_status_id = 1

					-- 2.2.1.2) insert partner_license
					exec usp_partner_insert_partner_license @license_id,@order_partner_id,@partner_license_status_id,@partner_license_source_id,@last_modified_user_id,@comment,@order_header_id,@partner_license_id output

					-- 2.2.1.3) insert partner_license_transaction
					select @license_transaction = '{"procedure":"usp_license_update_license_capability_load","@product_id":"'+ convert(varchar(20),@product_id) + '","@keycode":"' + @keycode + '","@order_type_group_id":"'+ convert(varchar(20),@order_type_group_id) + '","@order_item_id":"'+ convert(varchar(20),@order_item_id) + '"}'
				
					exec usp_partner_insert_partner_license_transaction @partner_license_id,@partner_license_status_id,@license_transaction
					end

				-- 2.2.3) new partner requiring entity approval on renewal/upgrade
				if @license_partner_id is null and @order_partner_id is not null and @order_entity_approval = 'Required' and @product_type_id <> 1
					begin
					-- 2.2.3.1) @order_item_update_type_id
					select @order_item_update_type_id = 2, @partner_license_status_id = 1

					-- 2.2.3.2) insert partner_license
					exec usp_partner_insert_partner_license @license_id,@order_partner_id,@partner_license_status_id,@partner_license_source_id,@last_modified_user_id,@comment,@order_header_id,@partner_license_id output

					-- 2.2.3.3) insert partner_license_transaction
					select @license_transaction = '{"procedure":"usp_license_update_license_capability_load","@product_id":"'+ convert(varchar(20),@product_id) + '","@keycode":"' + @keycode + '","@order_type_group_id":"'+ convert(varchar(20),@o
rder_type_group_id) + '","@order_item_id":"'+ convert(varchar(20),@order_item_id) + '"}'
				
					exec usp_partner_insert_partner_license_transaction @partner_license_id,@partner_license_status_id,@license_transaction
					end

				-- 2.2.4) new partner requiring entity approval on new purchase
				if @order_partner_id is not null and @order_entity_approval = 'Required' and @product_type_id = 1
					begin
					select @partner_license_status_id = 2
					
					exec usp_partner_insert_partner_license @license_id,@order_partner_id,@partner_license_status_id,@partner_license_source_id,@last_modified_user_id,@comment,@order_header_id,@partner_license_id output
					end
			
			end


			-- 2.3) parent license
			if @license_type_id in (2,3) and @product_line_id in (55,300) and @order_item_update_type_id = 1
				begin
				-- 2.3.1) call license update proc
				exec usp_license_update_license_capability_load @product_id,@keycode,@order_type_group_id,@order_item_id,@effective_date OUTPUT,@license_id OUTPUT,@response_code OUTPUT,@message OUTPUT
				
				-- 2.3.2) update child keycodes
				exec usp_license_update_child_licenses @license_id, @order_item_id

				-- 2.3.3) enter sky update for msp registration
				select @sky_template_id = sky_template_id from sky_template where sky_template_name = 'msp_registration'
				select @process_date = dateadd(mi,5,getdate())

				exec [usp_sky_insert_update] @license_id, @sky_template_id, @process_date
				end
			-- 2.4) standard license
			else if @license_type_id not in (2,3) and @order_item_update_type_id = 1
				begin
				-- 2.4.1) call license update proc
				exec usp_license_update_license_capability_load @product_id,@keycode,@order_type_group_id,@order_item_id,@effective_date OUTPUT,@license_id OUTPUT,@response_code OUTPUT,@message OUTPUT

	--			select @keycode, @product_id, @response_code, @message
			

				end

				-- 2.4.2) get new expiration
				select @capability_id = lc.base_capability_id, @license_category_id = lcl.license_category_id from license_category_license lcl	with (nolock) inner join license_category lc with (nolock) on lcl.license_category_id = lc.license_category_id where lcl.license_id = @license_id

				select @capability_expiration_date = isnull(capability_expiration_date,getdate()+capability_activation_days) from license_capability  with (nolock) where license_id = @license_id and capability_id = @capability_id

						-- 2.4.3) update order_item record with new effective date 
				if @site_id <> 'SFDC' and not (@site_id = 'RESELLER' and @order_partner_id is not null) and @site_id not in ('MSP','PARTNERSERVICE')
					begin
					update order_item 
					set effective_date = isnull(@effective_date,getdate()), 
						capability_expiration_date = isnull(@capability_expiration_date,getdate()) 
					where order_item_id = @order_item_id

					--update order_item 
					--set effective_date = case 
					--						when effective_date is null then isnull(@effective_date,getdate())
					--						else effective_date
					--					end, 
					--	capability_expiration_date = isnull(@capability_expiration_date,getdate()) 
					--from order_item
					--where order_item_id = @order_item_id
					end

			/*
			-- 2.5) update license_channel_license
			if @product_line_id in (55,300) and @license_category_id in (55,212,220,250)
				begin	
					select @task_number = @order_header_id 
					select @sql_string = 
					'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
					' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_channel_license_update ' + convert(varchar(10),@license_id) + ', ' + convert(varchar(10),@order_header_id) + '''' + ',0,getdate()) '

					exec (@sql_string)

					exec tasks..usp_queue_task @order_header_id
				end
				*/

			select @update_id = @update_id + 1
			end


	-- ---------------------------------------------------------------------
------------------------------------------------------------------------------------------------------------------------------
	-- 4.) cart_license_update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 4.1) delete vendor_order_code from cart_license_update
	delete
	from cart_license_update
	where vendor_order_code = (select vendor_order_code
								from vendor_order v with (nolock)
								inner join order_header h with (nolock)
									on v.vendor_order_id = h.vendor_order_id
								where h.order_header_id = @order_header_id)
								

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update licenses for @order_header_id = ' + convert(varchar(20),@order_header_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cart_update_order_license_new]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cart_update_order_license_new]
(
    @vendor_order_code VARCHAR(100),
    @partner_license_status_id TINYINT = NULL,
    @account_order_json VARCHAR(MAX) = NULL
)

/*
	DATE		AUTHOR		REMARKS
	2017-08-21	esmart		Initial creation.
	2017-11-02	esmart		Fix issues with partner license and utility from SFDC
	2017-11-14	esmart		Fix issue with child license updates on Excess Usage opps
	2018-02-22	esmart		Add day column update to license_capability_history
	2018-04-17	esmart		Find full secondary products not included in renewal
	2018-04-20	cnovac		Added code to call usp_license_insert_effective_object for seats
	2018-06-20	esmart		Fix defects with secondary products
	2018-07-05	esmart		Fix secondary products (C)
	2018-07-17	cnovac		Added @account_order_json which will be passed in for WIFI orders
	2018-09-20	rvinoche	Added logic to disable CleverBridge subscription
	2018-10-11	cnovac		Added check for @account_order_staging_id to be not null since WWW orders pass in '{"account_order_staging_id":null}'
	2018-10-11	cnovac		Updated call to usp_account_order_finalize
	2018-10-17	rvinoche	Added logic to approve billing entity switch when license expired more than 30 days (--2.5.1)
	2019-01-09	rvinoche	Support autobilling attributes living only in license_effective_object (--1.8)
	2019-03-05	rvinoche	Fix partner_license logic to only approve automatically if license expired for > 30 days (instead of 30 days from now) --2.5)
	2019-03-07	cnovac		Took out references to effective columns in license_seats
	2019-04-03	cnovac		Added code to start writing to license contract object
	2019-06-27	cnovac		Updated logic that populates license contract object for child licenses
	2019-07-19	rvinoche	Abstracted partner license decision to usp_partner_license_transaction_controller
	2019-07-19	cnovac		Changed logic that populates license contract object for non-child licenses and changed query that sets capability_expiration_date to dateadd(dd,365,i.effective_date)
	2019-08-20	cnovac		Added 3.5.4) insert into sky_update so cron can call Safer backend
	2019-09-06	cnovac		Updated how effective object is populated using license contract as baseline
	2019-12-03	esmart		Remove buffer on sky insert
	2020-02-13	esmart		Modify GSM registration insert to only include SAEP (1.7)
	2020-02-18	cnovac		Updated code to look for license_change_reason_id (set to product_type_id when license is full) in the update to license_capability and license_category_license
	2020-02-27	cnovac		Hotfix to not write to history tables for license_capability and license_category_license when a 'New' license is created
	2020-04-03	esmart		Add vault assignment for adding secondary product
	2020-07-28	wbarton		Vault now uses usp_license_insert_external_reference_vault to maintain vault data when applicable
	2020-11-23	jnavarra	Fix code (1.2.1) that's inflating seat counts
	2021-01-13	cnovac		Updated code in 8.0 to add usage_pricing_model_id, retention_model_id, product_platform_id, product_pricing_level_id, and storage_gb...took code out of usp_cart_load_insert_order_item so it now will get stuck in billing entity if needed
	2021-02-28	wbarton		Adding order_header_id in the usp_license_insert_external_reference_vault call
	2021-11-12	abelenkiy	Updated 3.5.3 and 3.5.5 to exclude write to license_storage if product_storage GB value = 0
	2022-01-07	gblandford	SMCI-6214 - Add retention_term
	2023-04-05  psatish		ECOM-899 Added section 3.5.2.1 and Modified the section 3.5.2/3.5.3 to update the storage_gb in the license_storage and modified the 
							section 8.0 for Storage_gb for upsell/renewals
	2023-06-07	jberry		ECOM-1169 Added storage_gb and usage_pricing_model_id to @order_item so license category is no
 longer needed for storage_gb calc
							Added logic to support all capacity products using usage_pricing_model_id to sections 3.5.2.1, 3.5.3 and 8.0
	2023-08-03  psatish		ECOM-1954 Added section 1.9 to update amend_upsell_order and modified section:3.3.2/3.4.2 and 7.0
							to add the condition isnull(amend_upsell_order,0)=0 for the upgrade products to update the correct license_seat for Amend/non-amend Upsell Orders						
	2025-03-14	mgolla		US-4403212 Added new section 10 If the child already has **EDR/MDR**, the **PLRM and/or PLRCB ** modules should be						   added to the child when they are initially added to the parent license.			
	2025-10-14	jberry		US-5004939 - Created a new table variable for @license_effective_object to store data for license effective object call
							- Added logic to sections 3.5.2.3 and 3.5.3 to handle cart storage licenses
							- Changed logic in section 8.0 to handle proper storage for cart orders
							- D-5036846 - Added sec 8.1.1 to update the renewal effective date to the upsell effective date if the renewal has an upsell on it
							- Made general changes to fix section numbering

	DESCRIPTION
*/

AS
SET NOCOUNT ON
BEGIN TRY

    DECLARE @order_header_id INT,
            @license_transaction VARCHAR(MAX),
            @partner_id INT,
            @partner_license_source_id TINYINT,
            @is_new_partner_license BIT,
            @temp_id INT,
            @total_ids INT,
            @license_id INT,
            @comment NVARCHAR(MAX),
            @partner_license_id INT,
            @history_date DATETIME,
            @history_by VARCHAR(20),
            @update_license TINYINT = 1,
            @temp_child_id INT,
            @total_child_ids INT,
            @child_license_id INT,
            @parent_license_id INT,
            @vendor_expiration_date DATE,
            @account_order_staging_id INT,
            @original_account_order_staging_id INT,
            @account_order_type VARCHAR(50),
            @response_code INT,
            @message VARCHAR(100),
            @license_effective_object_json VARCHAR(MAX),
            @license_contract_json VARCHAR(MAX),
            @vault_json NVARCHAR(MAX),
            @site_id VARCHAR(65),
			@lower_bound INT = 1,
            @upper_bound INT,
            @child_license_category VARCHAR(10),
            @child_keycode VARCHAR(40),
            @service_json NVARCHAR(MAX),
			@product_type_id INT

    SELECT @history_date = GETDATE(),
           @history_by = 'cart_license_update'
    SELECT @response_code = 0,
           @message = 'Success'
	SELECT @product_type_id = pt.product_type_id
	FROM dbo.product_type AS pt
	WHERE pt.product_type_description = 'New'

    DECLARE @order_item TABLE
    (
        order_item_id INT,
        order_header_id INT,
        line_item INT,
        product_id INT,
        product_type_id INT,
        quantity INT,
        effective_date DATETIME,
        new_capability_type_id INT,
        new_capability_type_description VARCHAR(20),
        capability_type_description VARCHAR(20),
        capability_expiration_date DATETIME,
        item_bundle_id INT,
        order_item_update_type_id TINYINT,
        item_hierarchy_id TINYINT,
        license_id INT,
        license_change_reason_id INT,
        start_date DATETIME,
        license_partner_id INT,
        partner_license_status_id TINYINT,
        license_module_id TINYINT,
        license_module_type_id TINYINT,
        license_module_type_name VARCHAR(50),
        new_license_module_type_name VARCHAR(50),
        license_category_name VARCHAR(10),
        license_category_id TINYINT,
        storage_gb INT,
        usage_pricing_model_id INT,
        amend_upsell_order INT
    )

    DECLARE @parent_license_table TABLE
    (
        license_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        li
cense_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        license_status_id INT
    )

    DECLARE @child_license_table TABLE
    (
        order_action VARCHAR(50),
        new_expiration_date DATETIME,
        new_category_type_name VARCHAR(50),
        license_change_reason_id INT,
        order_item_id INT,
        parent_license_id INT,
        license_id INT,
        keycode VARCHAR(40),
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        license_status_id INT,
        effective_date DATE
    )

    DECLARE @child_licenses TABLE
    (
        temp_child_id INT IDENTITY(1, 1),
        parent_license_id INT,
        child_license_id INT
    )

    DECLARE @order_item_license_table TABLE
    (
        license_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        license_attribute_license_value INT,
        start_date DATETIME,
        expiration_date DATETIME,
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        license_status_id INT
    )

    DECLARE @previous_items TABLE
    (
        row_id INT IDENTITY(1, 1),
        order_item_id INT,
        license_id INT,
        previous_order_item_id INT,
        previous_subscription_id INT,
        previous_line_item INT
    )

    DECLARE @license_contract_object TABLE
    (
        license_id INT,
        license_category_id TINYINT,
        license_category_type_id INT,
        license_start_date DATE,
        license_end_date DATE,
        license_seats INT,
        order_item_id INT
    )

	DECLARE @license_effective_object TABLE
    (
        license_id INT,
        license_category_id INT,
        license_seats INT,
        usage_pricing_model_id INT,
        retention_model_id INT,
        retention_term INT,
        product_platform_id INT,
        product_pricing_level_id INT,
        product_type_id INT,
        storage_gb INT,
        effective_start_date DATETIME,
        order_item_id INT,
        cart_order_item_id INT
	)

   DECLARE @child_add_modules TABLE
    (
        id INT IDENTITY(1, 1),
        license_category VARCHAR(20),
        keycode VARCHAR(40)
    )

   DECLARE @PILLR_MODULE_TEMPLATES TABLE
    (
        pillr_modules VARCHAR(10),
		pillr_sub_modules VARCHAR(10)
    )
		
	INSERT INTO @PILLR_MODULE_TEMPLATES
	(
	    pillr_modules,
		pillr_sub_modules
	)
	SELECT f.[key],
		   f.value
	FROM [dbo].[fn_app_config_select_key_values]('PILLR_MODULE_TEMPLATES', 'PILLR') f
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select order_item
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    SET @vendor_expiration_date = JSON_VALUE(@account_order_json, '$.vendor_expiration_date')
    SET @account_order_staging_id = JSON_VALUE(@account_order_json, '$.account_order_staging_id')
    SET @account_order_type = JSON_VALUE(@account_order_json, '$.account_order_type')
    SET @original_account_order_staging_id = JSON_VALUE(@account_order_json, '$.original_account_order_staging_id')

    -- 1.1) @order_header_id
    SELECT @order_header_id = h.order_header_id,
           @site_id = h.site_id
    FROM order_header h
        INNER JOIN vendor_order v
        
    ON v.vendor_order_id = h.vendor_order_id
    WHERE v.vendor_order_code = @vendor_order_code

    INSERT INTO @order_item_license_table
    (
        license_id,
        license_category_name,
        license_seats,
        storage_gb,
        license_keycode_type_id,
        license_attribute_license_value,
        start_date,
        expiration_date,
        category_type_name,
        item_hierarchy_id,
        license_status_id
    )
    SELECT license_id,
           license_category_name,
           license_seats,
           storage_gb,
           license_keycode_type_id,
           license_attribute_license_value,
           start_date,
           expiration_date,
           category_type_name,
           item_hierarchy_id,
           license_status_id
    FROM dbo.fn_license_select_order_item_license_profile(@order_header_id)

    -- 1.2) @order_item
    INSERT INTO @order_item
    (
        order_item_id,
        order_header_id,
        line_item,
        product_id,
        product_type_id,
        quantity,
        effective_date,
        capability_expiration_date,
        new_capability_type_id,
        new_capability_type_description,
        item_bundle_id,
        order_item_update_type_id,
        item_hierarchy_id,
        license_id,
        license_category_name,
        license_category_id
    )
    SELECT i.order_item_id,
           i.order_header_id,
           i.line_item,
           i.product_id,
           p.product_type_id,
           i.quantity,
           i.effective_date,
           i.capability_expiration_date,
           pc.capability_type_id,
           ct.capability_type_description,
           i.item_bundle_id,
           i.order_item_update_type_id,
           i.item_hierarchy_id,
           il.license_id,
           lc.license_category_name,
           lc.license_category_id
    FROM order_item i
        INNER JOIN product p
            ON p.product_id = i.product_id
        LEFT JOIN product_license_category plc
            ON plc.product_id = i.product_id
        LEFT JOIN license_category lc
            ON lc.license_category_id = plc.license_category_id
        LEFT JOIN product_capability pc
            ON pc.product_id = p.product_id
               AND pc.capability_id = lc.base_capability_id
        LEFT JOIN capability_type ct
            ON ct.capability_type_id = pc.capability_type_id
        INNER JOIN order_item_license il
            ON il.order_item_id = i.order_item_id
        LEFT JOIN product_seat ps
            ON ps.product_id = p.product_id
    WHERE i.order_header_id = @order_header_id

    -- 1.2.1) secondary products not included in the renewal
    DECLARE @phase_effective_date DATETIME =
            (
                SELECT MAX(effective_date)
                FROM @order_item
                WHERE product_type_id = 2
                      AND item_hierarchy_id = 1
                      AND new_capability_type_description = 'full'
            )

    INSERT INTO @order_item
    (
        order_item_id,
        order_header_id,
        line_item,
        product_id,
        product_type_id,
        quantity,
        effective_date,
        capability_expiration_date,
        new_capability_type_id,
        new_capability_type_description,
        item_bundle_id,
        order_item_update_type_id,
        item_hierarchy_id,
        license_id,
        license_category_id
    )
    SELECT order_item_id = NULL,
           @order_header_id,
           line_item = 0,
           p.product_id,
           p.product_type_id,
           il.license_seats,
           effective_date = @phase_effective_date,
           capability_expiration_date = @phase_effective_date,
           new_capability_type_id = 1,
           new_capability_type_description = 'full',
           item_bundle_id = 0,
           order_item_update_type_id = 1,
           item_hierarchy_i
d = 2,
           il.license_id,
           lc.license_category_id
    FROM @order_item_license_table il
        INNER JOIN dbo.license_category lc
            ON lc.license_category_name = il.license_category_name
        INNER JOIN dbo.product_license_category plc
            ON plc.license_category_id = lc.license_category_id
        INNER JOIN dbo.product p
            ON p.product_id = plc.product_id
               AND p.product_type_id = 2
        INNER JOIN dbo.product_years y
            ON y.product_id = p.product_id
               AND y.years = 1
        LEFT JOIN @order_item oi
            ON oi.license_id = il.license_id
    WHERE il.category_type_name = 'full'
          AND il.expiration_date > @phase_effective_date -- only touch secondary product when exp_date extends original phase
          AND il.license_status_id = 1 -- only touch active licenses
          AND il.item_hierarchy_id <> 1 -- parse out primary item
          AND oi.order_item_id IS NULL

    -- 1.3) capability_type_description
    UPDATE @order_item
    SET capability_type_description = t.capability_type_description
    FROM @order_item i
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
        INNER JOIN license_category c
            ON c.license_category_id = cl.license_category_id
        INNER JOIN license_capability lc
            ON lc.license_id = i.license_id
               AND lc.capability_id = c.base_capability_id
        INNER JOIN capability_type t
            ON t.capability_type_id = lc.capability_type_id

    -- 1.4) set license module
    UPDATE @order_item
    SET license_module_id = lm.license_module_id,
        license_module_type_id = mt.license_module_type_id,
        license_module_type_name = mlt.license_module_type_name,
        new_license_module_type_name = mt.license_module_type_name,
        license_category_id = lmc.license_category_id
    FROM @order_item i
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_module_category lmc
            ON lmc.license_category_id = plc.license_category_id
        INNER JOIN license_module lm
            ON lm.license_module_id = lmc.license_module_id
               AND lm.license_module_class_id = 3 -- parent
        INNER JOIN license_module_type mt
            ON i.new_capability_type_description = mt.license_module_type_name
        LEFT JOIN license_module_license ml
            ON ml.license_id = i.license_id
               AND ml.license_module_id = lm.license_module_id
        LEFT JOIN license_module_type mlt
            ON mlt.license_module_type_id = ml.license_module_type_id
    WHERE i.item_hierarchy_id = 2

    -- 1.5) set license_change_reason
    UPDATE @order_item
    SET license_change_reason_id = CASE
                                       WHEN capability_type_description = 'trial'
                                            OR license_module_type_name = 'trial' THEN
                                           14
                                       WHEN capability_type_description = 'full'
                                            OR license_module_type_name = 'full' THEN
                                           product_type_id
                                   END

    -- 1.6) start and end date
    UPDATE i
    SET start_date = CASE
                         WHEN i.capability_type_description = 'trial' THEN
                             i.effective_date
                         WHEN i.capability_type_description = 'full'
                              AND i.effective_date > CONVERT(DATE, @history_date) THEN
                             CONVERT(DATE, @history_date)
                         --when i.capability_type_description = 'full' and cl.end_date <= i.effective_date and i2.order_item_id is not null then cl.end_date
        --when i.capability_type_description = 'ful
l' and cl.end_date <= i.effective_date and i2.order_item_id is null and i.product_type_id in (2) then convert(date,@history_date)
                         --when i.capability_type_description = 'full' and cl.end_date > i.effective_date and i2.order_item_id is null and i.product_type_id in (3) then convert(date,@history_date)
                         ELSE
                             i.effective_date
                     END
    FROM @order_item i
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id

    -- 1.7) GSM registration
    INSERT INTO sky_update
    (
        license_id,
        sky_template_id,
        sky_update_type_id,
        process_date
    )
    SELECT DISTINCT
           i.license_id,
           sky_template_id = 1,
           sky_update_type_id = 1,
           GETDATE()
    FROM @order_item i
        INNER JOIN license l
            ON l.license_id = i.license_id
        INNER JOIN license_category_license cl
            ON l.license_id = cl.license_id
        LEFT JOIN sky_update u
            ON u.license_id = i.license_id
               AND u.sky_template_id = 1
        LEFT JOIN sky_update_archive a
            ON i.license_id = a.license_id
               AND a.sky_template_id = 1
               AND a.sky_update_status_id = 1
    WHERE l.product_line_id IN ( 300 )
          AND l.license_type_id = 2
          AND l.license_keycode_type_id = 3
          AND a.sky_update_archive_id IS NULL
          AND u.sky_update_id IS NULL
          AND cl.license_category_id = 220

    -- 1.8) SFDC autobilling utility extend capability_expiration_date to be one year vs. the one month that the contract would have
    UPDATE i
    SET capability_expiration_date = DATEADD(dd, 365, i.effective_date)
    FROM @order_item i
        INNER JOIN dbo.license_category lc
            ON lc.license_category_name = i.license_category_name
        CROSS APPLY fn_license_select_effective_object_table(i.license_id, i.effective_date) fn
    WHERE i.item_hierarchy_id = 1 --non-module product
          AND i.new_capability_type_id = 1 --full
          AND fn.effective_object_id = 2 --license_attribute_license_value
          AND fn.license_category_id = lc.license_category_id
          AND fn.effective_value = 12 --utility

    IF @@ROWCOUNT = 0 --this means the billing model wasn't utility or there was an upgrade on a module product and there's no i.item_hierarchy_id = 1
    BEGIN
        UPDATE i
        SET capability_expiration_date = pro.expiration_date
        FROM @order_item i
            INNER JOIN dbo.license_category lc
                ON lc.license_category_name = i.license_category_name
            CROSS APPLY fn_license_select_effective_object_table(i.license_id, i.effective_date) fn
            CROSS APPLY fn_license_select_license_profile(i.license_id) pro
        WHERE i.item_hierarchy_id = 2 --module product
              AND i.new_capability_type_id = 1 --full
              AND fn.effective_object_id = 2 --license_attribute_license_value
              AND fn.license_category_id = lc.license_category_id
              AND fn.effective_value = 12 --utility
              AND pro.item_hierarchy_id = 1 --non-module product

    END
    ELSE
    BEGIN
        UPDATE i --now check to see if there are utility module products that need capability_expiration_date to match item_hierarchy_id = 1 product (endpoint)
        SET capability_expiration_date =
            (
                SELECT MAX(i2.capability_expiration_date)
                FROM @order_item i2
                WHERE i2.license_id = i.license_id
                      AND i2.item_hierarchy_id = 1 --non-module product
                      AND i2.new_capability_type_id = 1
            ) --full
        FROM @order_item i
            INNER JOIN dbo.license_category lc
                ON lc.license_category_name = i.license_category_name
            
CROSS APPLY fn_license_select_effective_object_table(i.license_id, i.effective_date) fn
        WHERE i.item_hierarchy_id = 2 --module product
              AND i.new_capability_type_id = 1 --full
              AND fn.effective_object_id = 2 --license_attribute_license_value
              AND fn.license_category_id = lc.license_category_id
              AND fn.effective_value = 12 --utility

    END

    --1.9 set amend_upsell_order 
    UPDATE i
    SET i.amend_upsell_order = le.effective_value
    FROM @order_item i
        INNER JOIN dbo.license_effective_object le
            ON le.license_category_id = i.license_category_id
               AND le.license_id = i.license_id
        INNER JOIN dbo.effective_object eo
            ON eo.effective_object_id = le.effective_object_id
        INNER JOIN dbo.license_effective_object_transaction let
            ON let.license_effective_object_transaction_id = le.license_effective_object_transaction_id
               AND let.effective_object_transaction_type_value = i.order_item_id
    WHERE i.order_header_id = @order_header_id
          AND eo.object_element_name = 'amend_upsell_order'
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) partner_license
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 2.1) iterate over order_items
    DECLARE @partner_license TABLE
    (
        temp_id INT IDENTITY(1, 1),
        license_id INT,
        effective_date DATETIME,
        partner_license_status_id TINYINT,
        partner_id INT,
        partner_license_source_id TINYINT,
        is_new_partner_license BIT
    )

    INSERT INTO @partner_license
    (
        license_id,
        effective_date
    )
    SELECT license_id,
           MIN(effective_date)
    FROM @order_item
    WHERE order_item_id IS NOT NULL
    GROUP BY license_id

    UPDATE pl
    SET partner_license_status_id = CASE
                                        WHEN @partner_license_status_id = 2 THEN
                                            @partner_license_status_id -- the @partner_license_status_id param will only be passed in (as 2) when it is approved from a pending partner_license, which is why we want to override the function's decision
                                        ELSE
                                            IIF(fn.is_allowed = 0, 1, 2)
                                    END,
        partner_id = fn.partner_id,
        partner_license_source_id = fn.partner_license_source_id,
        pl.is_new_partner_license = CASE
                                        WHEN @partner_license_status_id = 2 THEN
                                            0 -- the @partner_license_status_id param will only be passed in (as 2) when it is approved, in which case there is already a partner_license record for the order and we don't want to insert a new one
                                        ELSE
                                            fn.is_new_partner_license
                                    END
    FROM @partner_license pl
        CROSS APPLY dbo.fn_partner_license_transaction_controller(
                                                                     pl.license_id,
                                                                     pl.effective_date,
                                                                     @order_header_id,
                                                                     NULL
                                                                 ) fn

    -- 2.2) loop through items
    SELECT @temp_id = 1,
           @total_ids = MAX(temp_id)
    FROM @partner_license

    WHILE @total_ids >= @temp_id
    BEGIN

        SELECT @license_id =
 license_id,
               @partner_id = partner_id,
               @partner_license_status_id = partner_license_status_id,
               @partner_license_source_id = partner_license_source_id,
               @is_new_partner_license = is_new_partner_license
        FROM @partner_license
        WHERE temp_id = @temp_id

        IF @is_new_partner_license = 1
           AND @partner_id IS NOT NULL -- make sure that the function wants to insert new partner_license record
        BEGIN
            EXEC usp_partner_insert_partner_license @license_id,
                                                    @partner_id,
                                                    @partner_license_status_id,
                                                    @partner_license_source_id,
                                                    @history_by,
                                                    @comment,
                                                    @order_header_id,
                                                    @partner_license_id OUTPUT

            IF @partner_license_status_id = 1
            BEGIN

                SELECT @license_transaction =
                (
                    SELECT 'usp_cart_update_order_license_new' AS 'procedure',
                           @vendor_order_code AS '@vendor_order_code'
                    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
                )

                EXEC usp_partner_insert_partner_license_transaction @partner_license_id,
                                                                    @partner_license_status_id,
                                                                    @license_transaction
                SELECT @update_license = 0 -- used after loop to halt license management until approval

            END
        END

        SELECT @temp_id = @temp_id + 1,
               @license_id = NULL,
               @partner_id = NULL,
               @partner_license_source_id = NULL,
               @partner_license_status_id = NULL,
               @license_transaction = NULL,
               @is_new_partner_license = NULL

    END

    -- 2.3) return if billing entity triggered
    IF @update_license = 0
    BEGIN
        SELECT @response_code = -200,
               @message = 'Billing entity triggered'
        SELECT response_code = @response_code,
               message = @message
        RETURN
    END

    -- 2.4) @child_license_table
    INSERT INTO @child_licenses
    (
        parent_license_id,
        child_license_id
    )
    SELECT parent_license_id,
           child_license_id
    FROM license_parent
    WHERE parent_license_id IN
          (
              SELECT license_id FROM @order_item
          )

    SELECT @temp_child_id = 1,
           @total_child_ids = MAX(temp_child_id)
    FROM @child_licenses

    WHILE @total_child_ids >= @temp_child_id
    BEGIN
        SELECT @child_license_id = child_license_id,
               @parent_license_id = parent_license_id
        FROM @child_licenses
        WHERE temp_child_id = @temp_child_id

        INSERT @child_license_table
        (
            parent_license_id,
            license_id,
            keycode,
            license_category_name,
            license_seats,
            storage_gb,
            license_keycode_type_id,
            license_attribute_license_value,
            start_date,
            expiration_date,
            category_type_name,
            item_hierarchy_id,
            license_status_id
        )
        SELECT @parent_license_id,
               license_id,
               keycode,
               license_category_name,
               license_seats,
               storage_gb,
               license_keycode_type_id,
               license_attribute_license_value,
               start_date,
               expiration_date,
               category_type_name,
             
  item_hierarchy_id,
               license_status_id
        FROM dbo.fn_license_select_license_profile(@child_license_id)
        WHERE license_status_id = 1

        SELECT @temp_child_id = @temp_child_id + 1
    END

    INSERT @parent_license_table
    (
        license_id,
        license_category_name,
        license_seats,
        storage_gb,
        license_keycode_type_id,
        license_attribute_license_value,
        start_date,
        expiration_date,
        category_type_name,
        item_hierarchy_id,
        license_status_id
    )
    SELECT license_id,
           license_category_name,
           license_seats,
           storage_gb,
           license_keycode_type_id,
           license_attribute_license_value,
           start_date,
           expiration_date,
           category_type_name,
           item_hierarchy_id,
           license_status_id
    FROM dbo.fn_license_select_license_profile(@parent_license_id)

    -- 2.5) determin action for child licenses
    UPDATE c
    SET c.order_action = CASE
                             WHEN i.license_change_reason_id = 14
                                  AND p.category_type_name = 'trial'
                                  AND cp.category_type_name = 'trial'
                                  AND p.item_hierarchy_id = 1 THEN
                                 'convert_primary_site'
                             WHEN i.license_change_reason_id = 14
                                  AND p.category_type_name = 'trial'
                                  AND p.category_type_name = 'trial'
                                  AND p.item_hierarchy_id = 2
                                  AND
                                  (
                                      cp.category_type_name = 'full'
                                      OR pp.category_type_name = 'trial'
                                  ) THEN
                                 'convert_secondary_site'
                             WHEN i.license_change_reason_id = 2
                                  AND p.category_type_name = 'full'
                                  AND c.category_type_name = 'full' THEN
                                 'renew'
                             WHEN i.license_change_reason_id = 1
                                  AND p.category_type_name = 'full'
                                  AND c.category_type_name = 'full' THEN
                                 'new'
                         END,
        c.new_expiration_date = i.capability_expiration_date,
        c.new_category_type_name = i.new_capability_type_description,
        c.start_date = i.start_date,
        c.license_change_reason_id = i.license_change_reason_id,
        c.order_item_id = i.order_item_id,
        c.effective_date = i.effective_date
    FROM @parent_license_table p
        INNER JOIN @child_license_table c
            ON p.license_category_name = c.license_category_name
        INNER JOIN @child_license_table cp
            ON cp.license_id = c.license_id
               AND cp.item_hierarchy_id = 1
        LEFT JOIN @parent_license_table pp
            ON pp.license_id = p.license_id
               AND pp.item_hierarchy_id = 1
        INNER JOIN @order_item i
            ON p.license_id = i.license_id
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_category lc
            ON lc.license_category_id = plc.license_category_id
               AND c.license_category_name = lc.license_category_name
    WHERE i.license_change_reason_id IN ( 1, 2, 14 )
          AND i.order_item_update_type_id = 1

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) update license
    ------------------------------------------------------------------------
-------------------------------------------------------------------------------------------

    -- 3.0) license
    INSERT INTO license_history
    (
        license_id,
        keycode,
        customer_id,
        product_line_id,
        license_status_id,
        license_type_id,
        license_distribution_method_id,
        license_keycode_type_id,
        max_daily_activations,
        max_child_licenses,
        license_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT DISTINCT
           l.license_id,
           l.keycode,
           l.customer_id,
           l.product_line_id,
           l.license_status_id,
           l.license_type_id,
           l.license_distribution_method_id,
           l.license_keycode_type_id,
           l.max_daily_activations,
           l.max_child_licenses,
           l.license_expiration_date,
           l.insert_date,
           l.insert_by,
           l.modified_date,
           l.modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM license l
        INNER JOIN @order_item i
            ON i.license_id = l.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND l.license_status_id <> 1

    UPDATE license
    SET license_status_id = 1,
        modified_date = @history_date,
        modified_by = @history_by
    FROM license l
        INNER JOIN @order_item i
            ON i.license_id = l.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND l.license_status_id <> 1

    -- 3.1) license_category_license
    UPDATE @order_item
    SET capability_expiration_date = DATEADD(dd, 1, @vendor_expiration_date),
        license_change_reason_id = 34
    WHERE license_category_name = 'WIFI'
          AND @vendor_expiration_date IS NOT NULL

    -- 3.1.1) license_category_license_history
    INSERT INTO license_category_license_history
    (
        license_category_license_id,
        license_id,
        license_category_id,
        start_date,
        end_date,
        order_item_id,
        last_modified_date,
        last_modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
           cl.start_date,
           end_date = i.start_date,
           i.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM @order_item i
        INNER JOIN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
           start_date = CASE
                            WHEN i2.start_date IS NOT NULL THEN
                                i2.start_date
                            ELSE
                                cl.start_date
                        END,
           end_date = CASE
                          WHEN i2.start_date IS NOT NULL THEN
                              i2.start_date
                          ELSE
                              i.start_date
                      END,
           i.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by
    FROM @order_item i
        INNER JO
IN product_license_category plc
            ON plc.product_id = i.product_id
        INNER JOIN license_category_license cl
            ON cl.license_id = i.license_id
        LEFT JOIN @order_item i2
            ON i2.item_hierarchy_id = i.item_hierarchy_id
               AND i2.product_type_id = 3
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id IN ( 14, 34 )
              )
          )

    -- 3.1.2) update license_category_license
    UPDATE license_category_license
    SET license_category_id = x.license_category_id,
        start_date = x.start_date,
        end_date = x.end_date,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM
    (
        SELECT license_id,
               item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               license_category_id = MAX(plc.license_category_id)
        FROM @order_item i
            INNER JOIN product_license_category plc
                ON plc.product_id = i.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id IN ( 1, 14, 34 )
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id
    ) x
        INNER JOIN license_category_license cl
            ON cl.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1

    -- 3.2) license_capability

    -- 3.2.1) license_capability_history
    INSERT INTO license_capability_history
    (
        license_capability_id,
        license_id,
        capability_id,
        capability_type_id,
        capability_activation_days,
        capability_activation_date,
        capability_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        capability_change_reason_id,
        history_date,
        history_by,
        order_item_id,
        days_used,
        days_remaining,
        days_added,
        days_new
    )
    SELECT license_capability_id,
           license_id,
           capability_id,
           capability_type_id,
           capability_activation_days = DATEDIFF(dd, x.capability_activation_date, x.capability_expiration_date),
           capability_activation_date,
           capability_expiration_date,
           insert_date,
           insert_by,
           modified_date,
           modified_by,
           x.license_change_reason_id,
           history_date,
           history_by,
           order_item_id,
           x.days_used,
           x.days_remaining,
           x.days_added,
           x.days_new
    FROM
    (
        SELECT c.license_capability_id,
               c.license_id,
               c.capability_id,
               c.capability_type_id,
               c.capability_activation_days,
               c.capability_activation_date,
               capability_expiration_date = i.start_date,
               c.insert_date,
               c.insert_by,
               c.modified_date,
               c.modified_by,
               i.license_change_reason_id,
               history_date = @history_date,
               history_by = @history_by,
               i.order_item_id,
               days_used = DATEDIFF(dd, c.capability_activation_date, @history_date),
               days_added = DATEDIFF(dd, c.capability_expiration_date, i.capability_expiration_date),
               days_remaining = DATEDIFF(dd, @history_date, c
.capability_expiration_date),
               days_new = DATEDIFF(dd, c.capability_activation_date, i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability pc
                ON pc.product_id = i.product_id
            INNER JOIN license_capability c
                ON c.license_id = i.license_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND i.product_type_id = 3
        UNION
        SELECT c.license_capability_id,
               c.license_id,
               c.capability_id,
               c.capability_type_id,
               c.capability_activation_days,
               capability_activation_date = CASE
                                                WHEN i2.start_date IS NOT NULL THEN
                                                    i2.start_date
                                                ELSE
                                                    c.capability_activation_date
                                            END,
               capability_expiration_date = CASE
                                                WHEN i2.start_date IS NOT NULL THEN
                                                    i2.start_date
                                                ELSE
                                                    i.start_date
                                            END,
               c.insert_date,
               c.insert_by,
               c.modified_date,
               c.modified_by,
               i.license_change_reason_id,
               history_date = @history_date,
               history_by = @history_by,
               i.order_item_id,
               days_used = DATEDIFF(dd, c.capability_activation_date, @history_date),
               days_added = DATEDIFF(dd, c.capability_expiration_date, i.capability_expiration_date),
               days_remaining = DATEDIFF(dd, @history_date, c.capability_expiration_date),
               days_new = DATEDIFF(dd, @history_date, i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability pc
                ON pc.product_id = i.product_id
            INNER JOIN license_capability c
                ON c.license_id = i.license_id
            LEFT JOIN @order_item i2
                ON i2.item_hierarchy_id = i.item_hierarchy_id
                   AND i2.product_type_id = 3
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id = 2
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id IN ( 14, 34 )
                  )
              )
    ) x
    ORDER BY x.order_item_id DESC

    -- 3.2.2) update license_capability
    UPDATE license_capability
    SET capability_activation_days = x.capability_activation_days,
        capability_activation_date = x.capability_activation_date,
        capability_expiration_date = x.capability_expiration_date,
        capability_type_id = x.new_capability_type_id,
        modified_date = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               i.new_capability_type_id,
               capability_activation_days = DATEDIFF(dd, MIN(i.start_date), MAX(i.capability_expiration_date)),
               capability_activation_date = MIN(i.start_date),
               capability_expiration_date = MAX(i.capability_expiration_date)
        FROM @order_item i
            INNER JOIN product_capability pc
                ON pc.product_id = i.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
  
                    i.product_type_id = 1
                      AND i.license_change_reason_id IN ( 1, 14, 34 )
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id,
                 i.new_capability_type_id
    ) x
        INNER JOIN license_capability c
            ON c.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1

    -- 3.3) license_seat

    -- 3.3.1) license_seat_history
    INSERT INTO license_seat_history
    (
        license_seat_id,
        license_id,
        license_seats,
        seats_used,
        start_date,
        end_date,
        order_item_id,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT s.license_seat_id,
           s.license_id,
           s.license_seats,
           s.seats_used,
           s.start_date,
           end_date = i.start_date,
           order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @history_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN product_seat ps
            ON ps.product_id = i.product_id
        INNER JOIN license_seat s
            ON s.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT s.license_seat_id,
           s.license_id,
           license_seats = CASE
                               WHEN pl.product_line_id NOT IN ( 55, 300 ) THEN
                                   s.license_seats
                               WHEN i.product_type_id = 3 THEN
                                   s.license_seats
                               ELSE
                                   i.quantity
                           END,
           s.seats_used,
           start_date = CASE
                            WHEN i2.start_date IS NOT NULL THEN
                                i2.start_date
                            ELSE
                                s.start_date
                        END,
           end_date = CASE
                          WHEN i2.start_date IS NOT NULL THEN
                              i2.start_date
                          ELSE
                              i.start_date
                      END,
           i.order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           history_date = @history_date,
           history_by = @history_by
    FROM @order_item i
        INNER JOIN product_seat ps
            ON ps.product_id = i.product_id
        INNER JOIN product_line_product pl
            ON pl.product_id = i.product_id
        INNER JOIN license_seat s
            ON s.license_id = i.license_id
        LEFT JOIN @order_item i2
            ON i2.item_hierarchy_id = i.item_hierarchy_id
               AND i2.product_type_id = 3
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id = 14
              )
          )

    -- 3.3.2) update license_seat
    UPDATE license_seat
    SET start_date = x.start_date,
        end_date = x.end_date,
        license_seats = x.license_seats,
        modified_date = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               pl.product_line_id,
               i.item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),

               license_seats = CASE
                                   WHEN pl.product_line_id NOT IN ( 55, 300 ) THEN
                                       MAX(ps.seats)
                                   WHEN MIN(i.product_type_id) = 3
                                        AND ISNULL(i.amend_upsell_order, 0) = 0 THEN
                                       MAX(s.license_seats) + MAX(i.quantity)
                                   ELSE
                                       MAX(i.quantity)
                               END
        FROM @order_item i
            INNER JOIN product_line_product pl
                ON pl.product_id = i.product_id
            INNER JOIN product_seat ps
                ON ps.product_id = i.product_id
            INNER JOIN license_seat s
                ON s.license_id = i.license_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 14
                  )
              )
        GROUP BY i.license_id,
                 pl.product_line_id,
                 i.item_hierarchy_id,
                 i.amend_upsell_order
    ) x
        INNER JOIN license_seat ls
            ON x.license_id = ls.license_id
    WHERE x.item_hierarchy_id = 1

    -- 3.4) license_module_license

    -- 3.4.1) license_module_license_history
    INSERT INTO license_module_license_history
    (
        license_module_license_id,
        license_id,
        license_module_id,
        module_seats,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        order_item_id,
        license_change_reason_id,
        history_date
    )
    SELECT ml.license_module_license_id,
           ml.license_id,
           ml.license_module_id,
           ml.module_seats,
           ml.license_module_type_id,
           ml.start_date,
           end_date = i.start_date,
           ml.license_status_id,
           ml.last_modified_date,
           ml.last_modified_by,
           i.order_item_id,
           i.license_change_reason_id,
           @history_date
    FROM @order_item i
        INNER JOIN license_module_license ml
            ON ml.license_id = i.license_id
               AND ml.license_module_id = i.license_module_id
    WHERE i.item_hierarchy_id = 2

    -- 3.4.2) update license_module_license
    UPDATE license_module_license
    SET start_date = x.start_date,
        end_date = x.end_date,
        module_seats = x.module_seats,
        license_module_type_id = x.license_module_type_id,
        license_status_id = 1,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM
    (
        SELECT i.order_item_id,
               i.license_id,
               i.item_hierarchy_id,
               ml.license_module_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               module_seats = CASE
                                  WHEN MIN(i.product_type_id) = 3
                                       AND ISNULL(i.amend_upsell_order, 0) = 0 THEN
                                      MAX(ml.module_seats) + MAX(i.quantity)
                                  ELSE
                                      MAX(i.quantity)
                              END,
               t.license_module_type_id
        FROM @order_item i
            INNER JOIN license_module_license ml
                ON ml.license_id = i.license_id
                   AND ml.license_module_id = i.license_module_id
            INNER JOIN license_module_type t
                ON i.new_capability_type_description = t.license_module_typ
e_name
        WHERE i.item_hierarchy_id = 2
        GROUP BY i.order_item_id,
                 i.license_id,
                 t.license_module_type_id,
                 i.item_hierarchy_id,
                 ml.license_module_id,
                 i.amend_upsell_order
    ) x
        INNER JOIN license_module_license ls
            ON x.license_id = ls.license_id
               AND ls.license_module_id = x.license_module_id
    WHERE x.item_hierarchy_id = 2

    -- 3.4.3) insert license_module_license
    DECLARE @license_module_license_insert TABLE
    (
        license_id INT,
        license_module_id TINYINT,
        license_module_type_id TINYINT,
        start_date DATETIME,
        end_date DATETIME,
        license_status_id INT,
        last_modified_date DATETIME,
        last_modified_by VARCHAR(20),
        module_seats INT,
        license_category_id TINYINT,
        order_item_id INT
    )

    INSERT INTO @license_module_license_insert
    (
        license_id,
        license_module_id,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        module_seats,
        license_category_id,
        order_item_id
    )
    SELECT i.license_id,
           i.license_module_id,
           i.license_module_type_id,
           i.start_date,
           i.capability_expiration_date,
           license_status_id = 1,
           @history_date,
           @history_by,
           i.quantity,
           lmc.license_category_id,
           i.order_item_id
    FROM @order_item i
        INNER JOIN license_module_category lmc
            ON lmc.license_module_id = i.license_module_id
        LEFT JOIN license_module_license ml
            ON ml.license_id = i.license_id
               AND ml.license_module_id = i.license_module_id
    WHERE i.item_hierarchy_id = 2
          AND ml.license_module_license_id IS NULL

    INSERT INTO license_module_license
    (
        license_id,
        license_module_id,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        module_seats
    )
    SELECT license_id,
           license_module_id,
           license_module_type_id,
           start_date,
           end_date,
           license_status_id,
           last_modified_date,
           last_modified_by,
           module_seats
    FROM @license_module_license_insert

    -- 3.4.4) EULA for DNS and SECA
    INSERT INTO sky_update
    (
        license_id,
        sky_template_id,
        sky_update_type_id,
        process_date
    )
    SELECT DISTINCT
           i.license_id,
           sky_template_id = 3,
           sky_update_type_id = 3,
           process_date = GETDATE()
    FROM @license_module_license_insert i
        LEFT JOIN sky_update u
            ON u.license_id = i.license_id
               AND u.sky_template_id IN ( 1, 3 )
    WHERE i.license_module_id IN ( 30, 32 )

    -- 3.5) license_storage

    -- 3.5.1) license_storage_history
    INSERT INTO license_storage_history
    (
        license_storage_id,
        license_id,
        storage_gb,
        storage_activation_date,
        storage_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by,
        order_item_id
    )
    SELECT s.license_storage_id,
           s.license_id,
           s.storage_gb,
           s.storage_activation_date,
           storage_expiration_date = i.start_date,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by,
           i.order_item_id
    FROM
 @order_item i
        INNER JOIN license_storage s
            ON s.license_id = i.license_id
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND i.product_type_id = 3
    UNION
    SELECT s.license_storage_id,
           s.license_id,
           s.storage_gb,
           storage_activation_date = CASE
                                         WHEN i2.start_date IS NOT NULL THEN
                                             i2.start_date
                                         ELSE
                                             s.storage_activation_date
                                     END,
           storage_expiration_datee = CASE
                                          WHEN i2.start_date IS NOT NULL THEN
                                              i2.start_date
                                          ELSE
                                              s.storage_activation_date
                                      END,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           i.license_change_reason_id,
           @history_date,
           @history_by,
           i.order_item_id
    FROM @order_item i
        INNER JOIN license_storage s
            ON s.license_id = i.license_id
        LEFT JOIN @order_item i2
            ON i2.item_hierarchy_id = i.item_hierarchy_id
               AND i2.product_type_id = 3
    WHERE i.item_hierarchy_id = 1
          AND i.order_item_update_type_id = 1
          AND
          (
              i.product_type_id = 2
              OR
              (
                  i.product_type_id = 1
                  AND i.license_change_reason_id = 14
              )
          )

    -- 3.5.2) update license_storage

    -- 3.5.2.1 update storage_gb
    UPDATE i
    SET storage_gb = le.effective_value
    --select *
    FROM @order_item i
        CROSS APPLY dbo.fn_license_select_effective_object_element_history(
                                                                              i.license_id,
                                                                              'storage_gb',
                                                                              i.license_category_id
                                                                          ) le
    WHERE le.effective_end_date IS NULL

    -- 3.5.2.2 usage_pricing_model
	UPDATE i
    SET usage_pricing_model_id = le.effective_value
    --select *
    FROM @order_item i
        CROSS APPLY dbo.fn_license_select_effective_object_element_history(
                                                                              i.license_id,
                                                                              'usage_pricing_model_id',
                                                                              i.license_category_id
                                                                          ) le
    WHERE le.effective_end_date IS NULL

    --if usage_pricing_model_id effective object doesn't exist then get from cart order item json
    UPDATE i
    SET usage_pricing_model_id = f.usage_pricing_model_id
    	--SELECT coi.cart_order_id, coi.cart_order_item_id, f.*
	FROM @order_item i
		INNER JOIN cart_order_header coh
			ON coh.order_header_id = i.order_header_id
		INNER JOIN cart_order_item coi
			ON coi.cart_order_id = coh.cart_order_id
				AND i.line_item = coi.line_item
				AND i.product_id = coi.product_id
	OUTER APPLY dbo.fn_cart_select_cart_order_item_json(coi.cart_order_item_id) f
	WHERE i.usage_pricing_model_id IS null

    -- 3.5.2.3 update storage_gb on license_storage if a record exists
    UPDATE license_storage
    SET storage_gb = IIF(x.storage_gb < ls.storage_gb, ls.storage_gb, x.storage_gb),
        storage_activation_date = x.start_date,
        storage_expiration_date = x.end_date,
        modified_date
 = @history_date,
        modified_by = @history_by
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               storage_gb = CASE
                            WHEN @site_id = 'SFDC' AND i.usage_pricing_model_id = 2 THEN
                                coi.storage_gb
                            WHEN @site_id IN ('WRCART', 'CSI') AND i.usage_pricing_model_id = 2 THEN
                                CASE 
                                    WHEN i.product_type_id = 3 THEN coi.storage_gb + i.storage_gb 
                                    ELSE coi.storage_gb 
                                END
                            ELSE
                                MAX(s.storage_gb)
							END
        FROM @order_item i
            INNER JOIN product_storage s
                ON s.product_id = i.product_id
            LEFT JOIN cart_order_header coh
                ON coh.order_header_id = i.order_header_id
            LEFT JOIN cart_order_item coi
                ON coi.cart_order_id = coh.cart_order_id
                   AND i.line_item = coi.line_item
                   AND i.product_id = coi.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 2, 3 )
                  OR
                  (
                      i.product_type_id = 1
                      AND i.license_change_reason_id = 14
                  )
              )
        GROUP BY i.license_id,
                 i.item_hierarchy_id,
                 coi.storage_gb,
                 i.storage_gb,
                 i.license_category_id,
                 i.usage_pricing_model_id,
                 i.product_type_id
    ) x
        INNER JOIN license_storage ls
            ON ls.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1

    -- 3.5.3) insert license_storage
    INSERT INTO license_storage
    (
        license_id,
        storage_gb,
        storage_activation_date,
        storage_expiration_date
    )
    SELECT x.license_id,
           x.storage_gb,
           x.start_date,
           x.end_date
    FROM
    (
        SELECT i.license_id,
               i.item_hierarchy_id,
               start_date = MIN(i.start_date),
               end_date = MAX(i.capability_expiration_date),
               storage_gb = CASE
                            WHEN @site_id = 'SFDC' AND i.usage_pricing_model_id = 2 THEN
                                coi.storage_gb
                            WHEN @site_id IN ('WRCART', 'CSI') AND i.usage_pricing_model_id = 2 THEN
                                CASE 
                                    WHEN i.product_type_id = 3 THEN coi.storage_gb + i.storage_gb 
                                    ELSE coi.storage_gb 
                                END
                            ELSE
                                MAX(s.storage_gb)
							END
        FROM @order_item i
            INNER JOIN product_storage s
                ON s.product_id = i.product_id
            LEFT JOIN cart_order_header coh
                ON coh.order_header_id = i.order_header_id
            LEFT JOIN cart_order_item coi
                ON coi.cart_order_id = coh.cart_order_id
                   AND i.line_item = coi.line_item
                   AND i.product_id = coi.product_id
        WHERE i.item_hierarchy_id = 1
              AND i.order_item_update_type_id = 1
              AND
              (
                  i.product_type_id IN ( 1, 2, 3 )
                  OR i.license_change_reason_id = 14
              )
              AND s.storage_gb > 0
        GROUP BY i.license_id,
                 i.item_hierarchy_id,
                 coi.storage_gb,
                 i.storage_gb,
                 i.lice
nse_category_id,
                 i.usage_pricing_model_id,
                 i.product_type_id
    ) x
        LEFT JOIN license_storage ls
            ON ls.license_id = x.license_id
    WHERE x.item_hierarchy_id = 1
          AND ls.license_storage_id IS NULL

    --3.5.4) insert into sky_update so cron can call Safer backend
    INSERT INTO sky_update
    (
        license_id,
        sky_template_id,
        sky_update_type_id
    )
    SELECT oi.license_id,
           7,
           7
    FROM @order_item oi
    WHERE oi.item_hierarchy_id = 1
          AND oi.product_type_id != 1 --only put in queue if product is not new since when new, php sends directly to Safer
          AND oi.license_category_name = 'WIFI'

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 4.) update child license
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 4.1) license_category_license

    -- 4.1.1) license_category_license_history
    INSERT INTO license_category_license_history
    (
        license_category_license_id,
        license_id,
        license_category_id,
        start_date,
        end_date,
        order_item_id,
        last_modified_date,
        last_modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT cl.license_category_license_id,
           cl.license_id,
           cl.license_category_id,
           cl.start_date,
           end_date = c.start_date,
           c.order_item_id,
           cl.last_modified_date,
           cl.last_modified_by,
           c.license_change_reason_id,
           @history_date,
           @history_by
    FROM @child_license_table c
        INNER JOIN license_category_license cl
            ON cl.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL

    -- 4.1.2) update license_category_license
    UPDATE license_category_license
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_category_license cl
            ON cl.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL

    -- 4.2) license_capability

    -- 4.2.1) license_capability_history
    INSERT INTO license_capability_history
    (
        license_capability_id,
        license_id,
        capability_id,
        capability_type_id,
        capability_activation_days,
        capability_activation_date,
        capability_expiration_date,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        capability_change_reason_id,
        history_date,
        history_by,
        order_item_id
    )
    SELECT lc.license_capability_id,
           lc.license_id,
           lc.capability_id,
           lc.capability_type_id,
           capability_activation_days = DATEDIFF(dd, lc.capability_activation_date, c.start_date),
           capability_activation_date,
           capability_expiration_date = c.start_date,
           insert_date,
           insert_by,
           modified_date,
           modified_by,
           c.license_change_reason_id,
           @history_date,
           @history_by,
           order_item_id
    FROM @child_license_table c
        INNER JOIN license_capability lc
            ON lc.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL

    -- 4.2.2) update license_capability
    UPDATE license_capability
    SET capability_activation_days = DATEDIFF(dd, c.start_date,
 c.new_expiration_date),
        capability_activation_date = c.start_date,
        capability_expiration_date = c.new_expiration_date,
        capability_type_id = 1,
        modified_date = @history_date,
        modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_capability lc
            ON lc.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL

    -- 4.3) license_seat

    -- 4.3.1) license_seat_history
    INSERT INTO license_seat_history
    (
        license_seat_id,
        license_id,
        license_seats,
        seats_used,
        start_date,
        end_date,
        order_item_id,
        insert_date,
        insert_by,
        modified_date,
        modified_by,
        license_change_reason_id,
        history_date,
        history_by
    )
    SELECT s.license_seat_id,
           s.license_id,
           s.license_seats,
           s.seats_used,
           s.start_date,
           end_date = c.start_date,
           c.order_item_id,
           s.insert_date,
           s.insert_by,
           s.modified_date,
           s.modified_by,
           c.license_change_reason_id,
           @history_date,
           @history_by
    FROM @child_license_table c
        INNER JOIN license_seat s
            ON s.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL

    -- 4.3.2) update license_seat
    UPDATE license_seat
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        license_seats = s.license_seats,
        modified_date = @history_date,
        modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_seat s
            ON s.license_id = c.license_id
    WHERE c.item_hierarchy_id = 1
          AND c.order_action IS NOT NULL


    -- 4.4) license_module_license

    -- 4.4.1) license_module_license_history
    INSERT INTO license_module_license_history
    (
        license_module_license_id,
        license_id,
        license_module_id,
        module_seats,
        license_module_type_id,
        start_date,
        end_date,
        license_status_id,
        last_modified_date,
        last_modified_by,
        order_item_id,
        license_change_reason_id,
        history_date
    )
    SELECT ml.license_module_license_id,
           ml.license_id,
           ml.license_module_id,
           ml.module_seats,
           ml.license_module_type_id,
           ml.start_date,
           end_date = c.start_date,
           ml.license_status_id,
           ml.last_modified_date,
           ml.last_modified_by,
           c.order_item_id,
           c.license_change_reason_id,
           @history_date
    FROM @child_license_table c
        INNER JOIN license_category lc
            ON lc.license_category_name = c.license_category_name
        INNER JOIN license_module_category mc
            ON mc.license_category_id = lc.license_category_id
        INNER JOIN license_module_license ml
            ON ml.license_id = c.license_id
               AND ml.license_module_id = mc.license_module_id
    WHERE c.item_hierarchy_id = 2
          AND c.order_action IS NOT NULL

    -- 4.4.2) update license_module_license
    UPDATE license_module_license
    SET start_date = c.start_date,
        end_date = c.new_expiration_date,
        module_seats = ml.module_seats,
        license_module_type_id = 19,
        license_status_id = 1,
        last_modified_date = @history_date,
        last_modified_by = @history_by
    FROM @child_license_table c
        INNER JOIN license_category lc
            ON lc.license_category_name = c.license_category_name
        INNER JOIN license_module_category mc
            ON mc.license_category_id = lc.license_category_id
        INNER JOIN license_module_license ml
            
ON ml.license_id = c.license_id
               AND ml.license_module_id = mc.license_module_id
    WHERE c.item_hierarchy_id = 2
          AND c.order_action IS NOT NULL

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 5.0)  WIFI specific code to log which account order staging id is associated to this trial
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT @license_id = NULL

    SELECT @license_id = license_id
    FROM @order_item_license_table
    WHERE license_category_name = 'WIFI'

    IF @license_id IS NOT NULL
       AND @account_order_staging_id IS NOT NULL
    BEGIN
        SET @account_order_json =
        (
            SELECT @account_order_staging_id AS account_order_staging_id,
                   @account_order_type AS account_order_type,
                   @original_account_order_staging_id AS original_account_order_staging_id,
                   @order_header_id AS order_header_id
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
        EXEC usp_account_order_finalize @license_id = @license_id,
                                        @account_order_json = @account_order_json
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 6.0)  CleverBridge specific code to deactivate CB subscription if the previous order came from CB
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    IF EXISTS (SELECT 1 FROM @order_item WHERE product_type_id > 1)
    BEGIN

        INSERT INTO @previous_items
        (
            order_item_id,
            license_id,
            previous_order_item_id,
            previous_subscription_id,
            previous_line_item
        )
        SELECT i.order_item_id,
               oil.license_id,
               oi.order_item_id,
               ps.payment_subscription_id,
               RIGHT(oi.line_item, 1)
        FROM @order_item i
            INNER JOIN dbo.order_item_license il
                ON il.order_item_id = i.order_item_id
            INNER JOIN order_item_license oil
                ON oil.license_id = il.license_id
            INNER JOIN order_item oi
                ON oi.order_item_id = oil.order_item_id
            INNER JOIN order_header oh
                ON oh.order_header_id = oi.order_header_id
            INNER JOIN order_payment_header oph
                ON oph.order_header_id = oh.order_header_id
            INNER JOIN payment_subscription ps
                ON ps.payment_header_id = oph.payment_header_id
        WHERE oil.order_item_license_id =
        (
            SELECT MAX(oil2.order_item_license_id)
            FROM order_item_license oil2
                INNER JOIN dbo.order_item oi2
                    ON oi2.order_item_id = oil2.order_item_id
                       AND RIGHT(oi2.line_item, 1) = 1
            WHERE oil.license_id = oil2.license_id
                  AND oil2.order_item_id < i.order_item_id
        )
              AND oh.site_id = 'CBCART' -- only orders where the previous order was from cleverbridge
              AND i.product_type_id > 1 -- only order_items that are not new

        IF @@rowcount > 0
        BEGIN
            DECLARE @row INT,
                    @max_row INT,
                    @lic INT,
                    @license_message_value_str VARCHAR(200)
            SELECT @row = 1,
                 
  @max_row = MAX(row_id)
            FROM @previous_items

            WHILE @row <= @max_row
            BEGIN
                SELECT @lic = license_id,
                       @license_message_value_str
                           = 'line_item=' + STR(previous_line_item) + ',' + 'payment_subscription_id='
                             + STR(previous_subscription_id)
                FROM @previous_items
                WHERE row_id = @row

                DECLARE @license_message_id INT
                EXEC usp_message_insert_license_message @lic,
                                                        11,
                                                        @history_date,
                                                        @history_date,
                                                        @history_date,
                                                        @license_message_value_str,
                                                        @license_message_id OUTPUT,
                                                        @return_result = 0

                SELECT @lic = NULL,
                       @license_message_value_str = NULL,
                       @row = @row + 1
            END
        END
    END

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 7.0)  License Contract call
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 7.1 use the @order_item object to populate @license_contract_object and make sure to just pick the positive transactions
    INSERT INTO @license_contract_object
    (
        license_id,
        license_category_id,
        license_category_type_id,
        license_start_date,
        license_end_date,
        order_item_id
    )
    SELECT DISTINCT
           oi.license_id,
           oi.license_category_id,
           oi.new_capability_type_id,
           oi.start_date,
           oi.capability_expiration_date,
           oi.order_item_id
    FROM @order_item oi
    WHERE oi.order_item_update_type_id = 1

    -- 7.2 now just insert all the @child_license_table records where doesn't exist in @license_contract_object
    INSERT INTO @license_contract_object
    (
        license_id,
        license_category_id,
        license_category_type_id,
        license_start_date,
        license_end_date,
        order_item_id
    )
    SELECT DISTINCT
           clt.license_id,
           lc.license_category_id,
           ct.capability_type_id,
           clt.effective_date,
           clt.new_expiration_date,
           clt.order_item_id
    FROM @child_license_table clt
        INNER JOIN capability_type ct
            ON ct.capability_type_description = clt.new_category_type_name
        INNER JOIN license_category lc
            ON lc.license_category_name = clt.license_category_name
        INNER JOIN @license_contract_object lco
            ON lco.license_id = clt.parent_license_id
               AND lco.license_category_id = lc.license_category_id
        LEFT JOIN @license_contract_object lco2
            ON lco2.license_id = clt.license_id
               AND lco2.license_category_id = lco.license_category_id
    WHERE clt.order_action IS NOT NULL
          AND lco2.license_id IS NULL

    -- 7.3 update the seats based on if it's upgrade or not.  If upgrade, get the current seats and add the quantity to it.
    UPDATE lco
    SET lco.license_seats = IIF(
                                oi.product_type_id = 3
                                AND ISNULL(oi.amend_upsell_order, 0) = 0,
                                ISNULL(oilt.license_seats, 0) + oi.quantity,
                        
        oi.quantity)
    FROM @license_contract_object lco
        INNER JOIN license_category lc
            ON lc.license_category_id = lco.license_category_id
        INNER JOIN @order_item oi
            ON oi.order_item_id = lco.order_item_id
               AND oi.license_category_name = lc.license_category_name
               AND oi.license_id = lco.license_id
        LEFT JOIN @order_item_license_table oilt
            ON oilt.license_id = lco.license_id
               AND oilt.license_category_name = lc.license_category_name

    -- 7.4 build up the JSON now based on data in @license_contract_object only for business licenses
    SELECT @license_contract_json =
    (
        SELECT license_id = lco.license_id,
               license_category_id = lco.license_category_id,
               license_category_type_id = lco.license_category_type_id,
               license_start_date = lco.license_start_date,
               license_end_date = lco.license_end_date,
               order_item_id = lco.order_item_id,
               originating_license_contract_id = fn.license_contract_id
        FROM @license_contract_object lco
            INNER JOIN license l
                ON l.license_id = lco.license_id
            OUTER APPLY fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
        WHERE l.product_line_id IN ( 55, 300 )
        FOR JSON PATH
    )

    -- 7.5 if data exists, call the insert now
    IF @license_contract_json IS NOT NULL
    BEGIN
        EXEC usp_license_insert_license_contract @license_contract_json = @license_contract_json,
                                                 @license_contract_source_caller = 'usp_cart_update_order_license_new'
    END

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 8.0 ) license effective object call
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 8.1 - populate @license_effective_object with order details for json call based on data in @license_contract_object for business licenses
    INSERT INTO @license_effective_object 
	(
		license_id, 
		license_category_id, 
		license_seats, 
		usage_pricing_model_id, 
		retention_model_id, 
		retention_term, 
		product_platform_id, 
		product_pricing_level_id, 
		product_type_id, 
		storage_gb, 
		effective_start_date, 
		order_item_id, 
		cart_order_item_id
	)
	SELECT
		license_id = lco.license_id,
		license_category_id = lco.license_category_id,
		license_seats = lco.license_seats,
		jp.usage_pricing_model_id,
		jp.retention_model_id,
		jp.retention_term,
		jp.product_platform_id,
		jp.product_pricing_level_id,
		p.product_type_id,
		-- Determine final storage_gb based on product type and site
		storage_gb = CASE
			WHEN p.product_type_id = 3 AND @site_id NOT IN ('SFDC', 'CSI', 'WRCART') THEN 
				dbo.fn_get_item_storage_gb(oi.quantity, DEFAULT, oi.product_id, DEFAULT, DEFAULT, DEFAULT)
				+ ISNULL(
					dbo.fn_license_select_effective_object_element(
						lco.license_id, plc.license_category_id, 'storage_gb', GETDATE()
					), 0
				)
			WHEN @site_id = 'SFDC' OR (@site_id IN ('WRCART', 'CSI') AND p.product_type_id <> 3) THEN
				coi.storage_gb
			WHEN @site_id IN ('WRCART', 'CSI') AND p.product_type_id = 3 THEN
				coi.storage_gb + ISNULL(
					dbo.fn_license_select_effective_object_element(
						lco.license_id, plc.license_category_id, 'storage_gb', GETDATE()
					), 0
				)
			ELSE
				dbo.fn_get_item_storage_gb(oi.quantity, DEFAULT, oi.product_id, DEFAULT, DEFAULT, DEFAULT)
		END,
		oi.effective_date AS [DATE],
		order_item_id = lco.order_item_id,
		coi.cart_order_item_id
	FROM dbo.order_item oi
	INNER JOIN dbo.order_item_license il 
		
ON il.order_item_id = oi.order_item_id
	INNER JOIN dbo.license l 
		ON l.license_id = il.license_id
	INNER JOIN dbo.product p 
		ON p.product_id = oi.product_id
	INNER JOIN dbo.product_license_category plc 
		ON plc.product_id = p.product_id
	INNER JOIN @license_contract_object lco 
		ON lco.order_item_id = oi.order_item_id 
			AND lco.license_id = l.license_id 
			AND lco.license_category_id = plc.license_category_id
	LEFT JOIN dbo.cart_order_header coh 
		ON coh.order_header_id = oi.order_header_id
	LEFT JOIN dbo.cart_order_item coi 
		ON coi.cart_order_id = coh.cart_order_id 
			AND oi.line_item = coi.line_item 
			AND oi.product_id = coi.product_id
	OUTER APPLY dbo.fn_cart_select_cart_order_item_json(coi.cart_order_item_id) jp
	WHERE 
		oi.order_header_id = @order_header_id AND 
		l.product_line_id IN (55, 300) AND 
		p.product_type_id <= CASE
								WHEN EXISTS (
									SELECT 1
									FROM dbo.order_item oi
									INNER JOIN dbo.product p ON p.product_id = oi.product_id
									WHERE oi.order_header_id = @order_header_id AND p.product_type_id = 3
								) AND EXISTS (
									SELECT 1
									FROM dbo.order_item oi
									INNER JOIN dbo.product p ON p.product_id = oi.product_id
									WHERE oi.order_header_id = @order_header_id AND p.product_type_id <> 3
								)
								THEN 2
								ELSE p.product_type_id
							END


	-- 8.1.1 Update the renewal effective date to the upsell effective date if the order is for a renewal + upsell
	;WITH effective_date AS (
		SELECT oi.license_id, oi.license_category_id, oi.product_type_id, oi.effective_date
		FROM @order_item oi
			left JOIN @license_effective_object leo ON oi.license_category_id = leo.license_category_id
		WHERE oi.product_type_id = 3
	)
	UPDATE @license_effective_object
	SET effective_start_date = ed.effective_date
	FROM @license_effective_object leo
	INNER JOIN effective_date ed 
	     ON ed.license_id = leo.license_id
	          AND ed.license_category_id = leo.license_category_id
	WHERE leo.product_type_id = 2

	-- 8.2 build json
	SELECT @license_effective_object_json = 
	(
		SELECT license_id,
				license_category_id,
				license_seats,
				usage_pricing_model_id,
				retention_model_id,
				retention_term,
				product_platform_id,
				product_pricing_level_id,
				storage_gb,
				effective_start_date = CAST(effective_start_date AS DATE),
				order_item_id
		FROM @license_effective_object

		FOR JSON PATH
	)

    -- 8.3 update the correct storage_GB on the upsell order
    UPDATE coi
    SET coi.storage_gb = CASE
                             WHEN pd.product_type_id = 3
                                 AND ISNULL(i.amend_upsell_order, 0) = 0 
								 AND @site_id = 'SFDC' THEN
                                 coi.storage_gb - i.storage_gb
                             ELSE
                                 coi.storage_gb
                         END
    FROM dbo.order_item oi
        INNER JOIN dbo.order_item_license ol
            ON ol.order_item_id = oi.order_item_id
        INNER JOIN dbo.product pd
            ON pd.product_id = oi.product_id
        INNER JOIN dbo.product_license_category plc
            ON plc.product_id = pd.product_id
        INNER JOIN dbo.cart_order_header coh
            ON coh.order_header_id = oi.order_header_id
        INNER JOIN dbo.cart_order_item coi
            ON coi.cart_order_id = coh.cart_order_id
               AND oi.line_item = coi.line_item
               AND oi.product_id = coi.product_id
        INNER JOIN @order_item i
            ON i.order_item_id = oi.order_item_id
    WHERE oi.order_header_id = @order_header_id
          AND i.usage_pricing_model_id = 2

    -- 8.4 if data exists, call the insert now
    IF @license_effective_object_json IS NOT NULL
    BEGIN
        EXEC dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json,
                       
                          @license_effective_source_caller = 'usp_cart_update_order_license_new'
    END

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 9.0 ) vault
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --Build up a JSON object for any license categories in @order_item that require vault provisioning/maintenance
    SELECT @vault_json =
    (
        SELECT DISTINCT
               i.license_id,
               i.order_header_id,
               i.license_category_id AS [license_category.license_category_id],
               JSON_VALUE(j.order_item_json, '$.vault_id') AS [license_category.vault_id],
               JSON_QUERY(j.order_item_json, '$.vault') AS [license_category.vault]
        FROM @order_item i
            INNER JOIN order_item_json j
                ON j.order_item_id = i.order_item_id
            INNER JOIN dbo.vault_license_category v
                ON v.license_category_id = i.license_category_id
        FOR JSON PATH
    )

    --Call usp_license_insert_external_reference_vault if @vault_json exists. If vault_ids have not been set via cart_order_item, defaulting will take place via this procedure.
    IF @vault_json IS NOT NULL
    BEGIN
        EXEC usp_license_insert_external_reference_vault @license_external_reference_vault_json = @vault_json
    END

 -------------------------------------------------------------------------------------------------------------------------------------------------------------------
 -- 10. If the child already has **EDR/MDR**, add the **PLRM and PLRCB modules** to the child when they are intillay added to the parent license.
 -------------------------------------------------------------------------------------------------------------------------------------------------------------------

    INSERT INTO @child_add_modules
    (
        license_category,
        keycode
    )
    SELECT DISTINCT   
       oi.license_category_name,
       clt.keycode
	FROM @child_license_table AS clt
    INNER JOIN @order_item AS oi
        ON oi.product_type_id=@product_type_id
    INNER JOIN @PILLR_MODULE_TEMPLATES AS pmt
        ON pmt.pillr_modules=clt.license_category_name --checking child licenses have EDR/MDR
		AND pmt.pillr_sub_modules=oi.license_category_name --checking PLRM/PLRCB exists in current @order_item
    
		
    IF @@ROWCOUNT > 0
    BEGIN

        SELECT @upper_bound = COUNT(cam.keycode)
        FROM @child_add_modules AS cam

        WHILE @lower_bound <= @upper_bound
        BEGIN

            SELECT @child_keycode = cam.keycode,
                   @child_license_category = cam.license_category
            FROM @child_add_modules AS cam
            WHERE id = @lower_bound

            SET @service_json
                = N'{"keycode":"' + @child_keycode
                  + '","application":"'+@site_id+'","license_category":[{"license_category_name":"'
                  + @child_license_category + '"}]}'

            EXEC dbo.usp_license_service_insert_service @license_service_type_name = 'site_enable', -- varchar(50)
                                                        @service_json = @service_json,              -- nvarchar(max)
                                                        @return_license_service_id = NULL           -- bit

            SET @lower_bound = @lower_bound + 1
            SET @child_keycode = NULL
            SET @child_license_category = NULL
			SET @service_json=NULL


        END

    END



END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'License update failed for vendor_order_code: ' + @vendor_orde
r_code
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;









GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_insert_notification]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cb_insert_notification]

(
	@cb_order_header VARCHAR(MAX),
	@cb_order_body XML
)

/*	
	DATE		AUTHOR		REMARKS
	2016-06-07	cnovac		Initial creation.
	2024-07-22	gblandford	https://jira.opentext.com/browse/ECOM-5072
							- Rearchitect - move logic of processing to a job queue, handle duplicate requests in the process
							- Case change, formatting, comments and schemas updated

	DESCRIPTION
	This procedure captures notifications from Cleverbridge which represent different actions required

	The following notification types are supported:

		'Order' 
		'Partial Refund' 
		'Full Refund' 
		'Unsubscribe' 
		'Subscribe' 
		'Chargeback' 

		We allow all notifications to be inserted, ( with a status of 'Received' ).
		These will then be dupe-checked dbo.usp_cb_update_notification (in addition to updating the notification with extracted notification_type and vendor_order_code).
		If the check fails, the notification status is set to 'Failed'.
		If the check passes, the status is set to 'Pending' so that the processing agent can be it up - 'Cleverbridge - Process Notifications'

		The processing agent will be responsible for:
		
		1. processing the 'pending', calling dbo.usp_cb_process_notification for each notifications.
		2. The agent job will also archive processed and failed records.

*/
AS

/*
|
|	When dealing with sql xml and php always use
|
*/
SET NOCOUNT ON				
SET CONCAT_NULL_YIELDS_NULL ON
SET ANSI_WARNINGS ON
SET ANSI_PADDING ON
SET ARITHABORT ON
	
BEGIN TRY

	DECLARE	@cb_notification_id INT,
			@vendor_order_code VARCHAR(100),
			@response_code INT,
			@message VARCHAR(100)

	/*
	|	
	| Insert the notification as 'Received'
	|
	*/
	INSERT INTO dbo.cb_notifications (
		cb_order_header, 
		cb_order_body,
		cb_notification_status_id
	)
	SELECT 
		@cb_order_header, 
		@cb_order_body,
		0 -- 'Received'

	SELECT @cb_notification_id = SCOPE_IDENTITY()


	/*
	|
	|	This _does_ update the cb_notification record, but it is merely extracting and updating 
	|	the cb_purchase_code and cb_notification_type_id, whilst returning the former as vendor_order_code
	|
	*/ 
	IF @cb_notification_id IS NOT NULL BEGIN
			EXECUTE dbo.usp_cb_update_notification
				@cb_notification_id, 
				@vendor_order_code OUTPUT
		END

	/*
	|
	|	Processing logic is now moved out to SQL agent job 'Cleverbridge - Process Notifications'
	|   
	*/
	--IF @vendor_order_code IS NOT NULL
	--	EXEC usp_cb_process_notification @cb_notification_id, @vendor_order_code

END TRY

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'Insert to cb_notifications failed'
						ELSE @message END

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXEC dbo.usp_LogError @ErrorDB = @DBName
		
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_license_message_select_next_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cb_license_message_select_next_message]

(
	@batch_limit_date DATETIME
)
	
/*	
	DATE		AUTHOR		REMARKS
	2016-07-22	cnovac		Initial creation.
	2017-06-27	cnovac		Added the currency_id to be returned out
	2020-03-27	jnavarra	Hints to prevent locking
	2020-08-27	abelenkiy	Changed how end date is retrieved to use fn_license_select_license_profile instead of through license_capability_id
							Removed unused variables and moved locking hints to transaction level
	2021-08-23	gblandford	Re-introduced NOLOCK hints to handle deadlocking issues which persist and removed ISOLATION LEVEL set (ITSM#3560296)
	
	DESCRIPTION
	select next message to process

*/

AS

SET NOCOUNT ON

BEGIN TRY			

	DECLARE	@license_message_id INT
	
	SELECT @batch_limit_date = DATEADD(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get next license_message_id
	SELECT @license_message_id = (
		SELECT TOP 1 m.license_message_id
		FROM license_message m WITH (NOLOCK)
		WHERE m.process_date <= @batch_limit_date
			AND m.message_type_id IN (11, 12)
			AND m.message_status_id IN (1,2,4)
		ORDER BY m.process_date
	)

	-- 1.2) insert data into table
	SELECT m.license_message_id, 
		   CAST(m.license_message_key AS VARCHAR(50)) AS license_message_key,
		   mt.message_type_name,
		   m.license_id,
		   v2.value_id AS line_item,
		   ps.subscription_id,
		   ph.currency_id,
		   IIF(m.message_type_id = 12, p.expiration_date, NULL) AS capability_expiration_date,--only pass exp date if message type = modify_license_expiration
		   m.process_date
	FROM license_message m WITH (NOLOCK)
		INNER JOIN message_type mt WITH (NOLOCK)
			ON mt.message_type_id = m.message_type_id
		CROSS APPLY fn_license_select_license_profile(m.license_id) p
		LEFT JOIN license_message_value v1 WITH (NOLOCK)
			ON m.license_message_id = v1.license_message_id AND v1.message_value_type_id = 17 --17 payment_subscription_id
		LEFT JOIN payment_subscription ps WITH (NOLOCK)
			ON v1.value_id = ps.payment_subscription_id
		LEFT JOIN payment_header ph  WITH (NOLOCK)
			ON ph.payment_header_id = ps.payment_header_id
		LEFT JOIN license_message_value v2  WITH (NOLOCK)
			ON m.license_message_id = v2.license_message_id AND v2.message_value_type_id = 18 --18 line_item
	WHERE m.license_message_id = @license_message_id

	 --1.3) if no result then abandon message
	IF @@rowcount = 0
	BEGIN
		UPDATE license_message 
		SET message_status_id = 6, last_modified_date = GETDATE()
		WHERE license_message_id = @license_message_id
		RETURN
	END

END TRY

BEGIN CATCH

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXEC usp_LogError @ErrorDB = @DBName
		
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_process_notification]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cb_process_notification] (		
	@cb_notification_id int,
	@vendor_order_code varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2016-06-08	cnovac		Initial creation.
	2016-08-12	cnovac		TA32708 - added override logic on subscription level opt-out to be applied to all items in @items
	2016-08-12	cnovac		TA32710 - if keycode alias comes in notification, make sure to pass the keycode to @keycodes object
	2016-08-12	cnovac		TA32715 - for gamer product 24101211, make all pricing fields $0
	2016-08-12	cnovac		TA32768 - set vendor_date fields to use payment arrive time from notification
	2016-08-12	cnovac		TA32750 - load smb order differently due to how we calc list/unit/tax prices different than consumer
	2016-08-12	cnovac		TA32717 - for gamer product 24101211, change the line_item to be max line-item + 1 on order
	2016-08-12	cnovac		TA33186 - suppress sending CB license_message to deactivate subscription if the notification coming in is for deactivate
	2016-08-29	cnovac		TA33804 - added a check for isnull around list price for cart_order_item
	2016-08-31	cnovac		TA34409 - took out bundle logic used to combine gamer module product to AV product
	2016-08-31	cnovac		TA34408 - added logic to support bug created by Cleverbridge where they don't pass us previous keycode on a renewal
	2016-10-06	cnovac		TA35999 - changed elements used to get list_price, unit_price, and tax to use CustomerPrice due to rounding issues in clearing file
	2016-10-06	cnovac		TA36000 - took out some code to work around AR and setting the auto-renew flag
	2016-10-26	cnovac		TA35129 - added code to process chargebacks
	2016-11-29	cnovac		TA39286 - changed the insert into cart_order_item for business to group by select columns due to dups coming out product pricing
	2016-12-01	cnovac		TA39497 - added check to make sure a keycode exists in xml before processing order
	2016-12-09	cnovac		TA39852 - now store iso3 for country and changed xml variables to nvarchar
	2017-02-16	blu			Modified partial refund call
	2017-02-22	cnovac		TA42689 - changed logic to process stand-alone cd's which have no keycode.  Cleaned up the business logic code.
	2017-07-11	cnovac		Added logic to take care of usp_license_update_license_capability_CSI @days = 0
	2017-08-17	cnovac		TA47810 - updated code to look for line id 1 when picking up subscription to deactivate
	2017-10-11	cnovac		TA48750 - added code to always set the expiration date back to CB
	2018-01-16	cnovac		Made business tax be total tax as we not doing unit based tax anymore
	2018-03-26	cnovac		Added logic to look for cbt:PreviousLicense[1] due to CB not sending keyraw due to bug
	2018-04-10	cnovac		Added code to figure out @order_opt_in_status differently
	2018-05-14	cnovac		Added code to insert into sky_update if it's a GSM keycode
	2018-06-04	cnovac		took out all code referencing in_process tables which are getting depricated and took out gamer code.
	2018-09-07	rvinoche	Allow past record updates when calling usp_license_update_license_attribute_license
	2018-09-20	rvinoche	Removed code to disable previous CB subscription as it was added in dbo.usp_cart_update_order_license_new
	2018-10-04	esmart		Add company_name and company_type_id to cart_customer
	2019-01-21	rvinoche	Add code back to disable previous CB subscriptions
	2019-01-31	rvinoche	Pass in AR flag to usp_cart_load_order
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2019-09-12	cnovac		Updated code to set start and end date of CD to match the associated product CD is tied to if present	
	2019-09-27	esmart		Change first, last, and company_name to use non-romanized values
	2020-01-30	wbarton		Changing @order_opt_in_status to @cus
tomer_opt_in_status and adding @autorenewal_opt_in_status. Setting @autorenewal_opt_in_status based on item status in the XML, and using it for license_attribute_license maintenance.
	2020-01-30	wbarton		Updating notification_type_id 4 behavior to set @license_attribute_license_value = 2, because cleverbridge has sent us incorrect status data within RecurringBillingCancel notifications.
	2020-03-31	wbarton		Fixing a bug where CD items were included in the setting of @autorenewal_opt_in_status
	2020-04-22	cnovac		Updated code to set keycode2 if keycode not present in @keycodes table variable
	2020-05-11	jnavarra	Accept marketing opt status from new x-param
	2020-06-16	cnovac		Added quantity2 field to item list in order to override if sent through specific to AR call
	2020-08-06	abelenkiy	Refactored parsing of customer object directly to json; replaced insert to cart_customer with proc call; removed unused variables
	2020-08-07	cnovac		Added code back to set @line_item where it was previously taken out by accident
	2020-08-27	abelenkiy	Added back cart_customer insert code previously removed as hotfix; changed call to usp_message_insert_license_message so capability_id no longer passed in and end_date figured out downstream
	2020-10-27	abelenkiy	Set customer_type_id passed into usp_cart_update_cart_customer to 1 (param now required)
	2021-07-14	abelenkiy	Fixed bug (ITSM#3591526) where keycode is retrieved from x-param value if null on order item
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the cart_order_item_audit
	2023-05-03  psatish		ECOM-899 Added storage_gb in the cart_order_item_audit
	2024-07-22	gblandford	https://jira.opentext.com/browse/ECOM-5072
							- Rearchitect - now called from dbo.usp_cb_process_notification_queue via agent job ''Cleverbridge - Process Notifications'
							- Update status on cb_notifications to 4 - 'Failed' or 3 - 'Completed'
							- added schemas


	DESCRIPTION

*/

as

set nocount on

begin try

	declare @notification_xml XML,
			@notification_type_id int,
			@response_code int,
			@message varchar(100),
			@response_code_cc int, 
			@message_cc varchar(100),
			@ship_locale nvarchar(5),
			@keycode varchar(50),
			@keycode_count int,
			@keycode_start int = 1,
			@previous_subscription_id varchar(50),
			@license_id int,
			@license_category_id tinyint,
			@license_message_key uniqueidentifier,
			@license_message_value_str varchar(200),
			@license_message_id int,
			@subscription_id varchar(50),
			@customer_opt_in_status bit = null,
			@autorenewal_opt_in_status bit,
			@license_attribute_license_value int,
			@cart_order_id int,
			@order_header_id int,
			@order_items_xml xml,
			@payment_header_id int,
			@payment_subscription_id int,
			@payment_method_id int,
			@refund_comment varchar(100),
			@system_user varchar(100) = suser_sname(),
			@process_date datetime = getdate(),
			@currency_id int,
			@line_item int,
			@days int,
			@vendor_order_date datetime2,
			@hh_diff int,
			@is_cd_only_order bit = 0,
			@quantity int,
			@cart_customer_json nvarchar(max)

	declare @items table(item_id int identity(1,1),	cart_order_id int, subscription_id varchar(50), item_opt_in_status int, line_item int, 
						 product_id varchar(25), RefSubSellingItemProductId varchar(25), quantity int, list_price money, unit_price money, tax money, list_price_single money, unit_price_single money,
						 tax_single money, keycode varchar(50), previous_line_item int, previous_subscription_id varchar(50), keycode2 varchar(50))
	declare @keycodes table(keycode_id int identity (1,1), subscription_id varchar(50), item_opt_in_status int, line_item int, keycode varchar(50), previous_line_item int, previous_subscription_id varchar(50))
	declare @items_summed table(item_summed_id int identity(1,1), cart_order_id int, list_price money, unit_price money, tax money)
	declare @xparams table(xparam_id int identity(1,1), xparam_name varchar
(50), xparam_value varchar(50))
	declare @xparams_item table(xparam_id int identity(1,1), xparam_name varchar(50), xparam_value varchar(50))

	--get the xml object and notification type into variables
	select @notification_xml = cb_order_body,
		   @notification_type_id = cb_notification_type_id
	from dbo.cb_notifications
	where cb_notification_id = @cb_notification_id

	--get the in-process-cart-id from the xml first which is part of the x parameters object
	;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' as cbn,
	'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' as cbt)
	insert into @xparams(xparam_name, xparam_value)
	select   
		ea.value('cbt:Key[1]', 'varchar(50)') xparam_name,
		ea.value('cbt:Value[1]', 'varchar(50)') xparam_value
	from @notification_xml.nodes('/*/cbn:Purchase/cbt:ExtraParameters/cbt:ExtraParameter') extendedAttributes(ea)

	select @cart_order_id = xparam_value
	from @xparams
	where xparam_name = 'x-cart_order_id'

	--if there's no @cart_order_id, this means it's an order not placed through our cart, but most likely the CB CA tool
	if @cart_order_id is null
	begin
		set @order_header_id = -1
	end
	else
	begin
		update dbo.cb_notifications
		set cart_order_id = @cart_order_id
		where cb_notification_id = @cb_notification_id
	end

	--get the autorenewal message key
	select @license_message_key = xparam_value
	from @xparams
	where xparam_name = 'x-license_message_key'

	--get the autorenewal message key
	if @license_message_key is not null
	begin
		update dbo.cb_notifications
		set license_message_key = @license_message_key
		where cb_notification_id = @cb_notification_id

		select @license_message_key = license_message_key
		from dbo.license_message
		where license_message_key = @license_message_key
		and message_status_id != 3

		--mark the record as paid in license_message.  This logic is here because the paid order notification can come at anytime
		--and is not syncronous with the api call to auto-renew
		if @license_message_key is not null
			exec dbo.usp_license_message_update_autorenewal_message @license_message_key, 'Paid'
	end
	
	--see if there's already an order associated to the vendor_order_code passed in
	select @order_header_id = oh.order_header_id
	from dbo.cart_order co
	left join dbo.vendor_order vo on co.vendor_order_code = vo.vendor_order_code
	left join dbo.order_header oh on oh.vendor_order_id = vo.vendor_order_id
	where co.vendor_order_code = @vendor_order_code

	--load all the purchased or refunded items into object
	;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' as cbn,
	'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' as cbt)
	insert into @items (cart_order_id, subscription_id, item_opt_in_status, line_item, product_id, RefSubSellingItemProductId, quantity, list_price, unit_price, tax, list_price_single, unit_price_single, tax_single, keycode, keycode2)
	select @cart_order_id, 
		ea.value('(cbt:RecurringBilling/@cbt:SubscriptionId)[1]', 'varchar(50)') subscription_id,
		case when ea.value('(cbt:RecurringBilling/cbt:ItemStatus)[1]', 'varchar(50)') = 'Active' then 1 else 0 end item_opt_in_status,
		ea.value('@cbt:RunningNo[1]', 'int') + 1000000 line_item,
		ea.value('cbt:ProductId[1]', 'varchar(25)') product_id,
		ea.value('cbt:RefSubSellingItemProductId[1]', 'varchar(25)') RefSubSellingItemProductId,
		ea.value('cbt:Quantity[1]', 'int') quantity,
		ea.value('(cbt:CustomerPrice/cbt:TotalTotalPrice/cbt:GrossPrice)[1]', 'varchar(50)') list_price,
		ea.value('(cbt:CustomerPrice/cbt:TotalTotalPrice/cbt:NetPrice)[1]', 'varchar(50)') unit_price,
		ea.value('(cbt:CustomerPrice/cbt:TotalTotalPrice/cbt:VatPrice)[1]', 'varchar(50)') tax,
		ea.value('(cbt:CustomerPrice/cbt:ProductSinglePrice/cbt:GrossPrice)[1]', 'varchar(50)') list_price_single,
		ea.value('(cbt:CustomerPrice/cbt:ProductSinglePrice/cbt:NetPrice)[1]
', 'varchar(50)') unit_price_single,
		ea.value('(cbt:CustomerPrice/cbt:ProductSinglePrice/cbt:VatPrice)[1]', 'varchar(50)') tax_single,
		ea.value('(cbt:Deliveries/cbt:Key/cbt:KeyRaw)[1]', 'varchar(50)') keycode,
		ea.value('cbt:PreviousLicense[1]', 'varchar(50)') keycode2
	from @notification_xml.nodes('/*/cbn:Purchase/cbt:Items/cbt:Item') extendedAttributes(ea)

	--get license_seats from the x-params which will override quantity on AR calls from ecomm
	;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' as cbn,
	'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' as cbt)
	insert into @xparams_item(xparam_name, xparam_value)
	select   
		ea.value('cbt:Key[1]', 'varchar(50)') xparam_name,
		ea.value('cbt:Value[1]', 'varchar(50)') xparam_value
	from @notification_xml.nodes('/*/cbn:Purchase/cbt:Items/cbt:Item/cbt:ExtraParameters/cbt:ExtraParameter') extendedAttributes(ea)

	--get the keycode
	select @keycode = xparam_value
	from @xparams_item
	where xparam_name = 'x-license_keycode'

	--get the quantity(license_seats)
	select @quantity = xparam_value
	from @xparams_item
	where xparam_name = 'x-license_seats'

	--make keycode null if it comes in with empty string from xml
	update @items
	set keycode = nullif(ltrim(rtrim(keycode)), '')
	update @items
	set keycode2 = nullif(ltrim(rtrim(keycode2)), '')

	update i
	set keycode = @keycode
	from @items i
		inner join dbo.cb_product_mapping cb 
			on cb.cb_product_id = i.product_id
				and cb.product_id not in (18100000, 18115000, 18120000)
	where i.keycode is null
		and i.keycode2 is null

	update items
	set items.quantity = isnull(@quantity, items.quantity)
	from @items items
	where isnull(items.keycode, items.keycode2) = @keycode

	--update the previous subscription, if exists to be used as return from this proc telling the php to disable that subscription from 
	update items
	set previous_line_item = right(oi.line_item, 1),
	    previous_subscription_id = ps.subscription_id
	from @items items
	left join dbo.license_keycode_alias lka on lka.keycode_alias = items.keycode
	inner join dbo.license l on l.keycode = isnull(lka.keycode, items.keycode)
	inner join dbo.order_item_license oil on oil.license_id = l.license_id
	inner join dbo.order_item oi on oi.order_item_id = oil.order_item_id
	inner join dbo.order_header oh on oh.order_header_id = oi.order_header_id
	inner join dbo.order_payment_header oph on oph.order_header_id = oh.order_header_id
	inner join dbo.payment_subscription ps on ps.payment_header_id = oph.payment_header_id
	where items.keycode is not null
	and oil.order_item_license_id = (select max(oil2.order_item_license_id) 
									from dbo.order_item_license oil2
									inner join dbo.order_item oi2 on oi2.order_item_id = oil2.order_item_id and right(oi2.line_item, 1) = 1
									where oil.license_id = oil2.license_id)



	--load the keycodes associated to order within object
	insert into @keycodes (subscription_id, item_opt_in_status, line_item, keycode, previous_line_item, previous_subscription_id)
	select subscription_id, item_opt_in_status, line_item, isnull(lka.keycode, items.keycode), items.previous_line_item, items.previous_subscription_id
	from @items items
	left join dbo.license_keycode_alias lka on lka.keycode_alias = items.keycode
	where items.keycode is not null

	--load the keycodes associated to order within object
	insert into @keycodes (subscription_id, item_opt_in_status, line_item, keycode, previous_line_item, previous_subscription_id)
	select subscription_id, item_opt_in_status, line_item, isnull(lka.keycode, items.keycode2), previous_line_item, previous_subscription_id
	from @items items
	left join dbo.license_keycode_alias lka on lka.keycode_alias = items.keycode2
	where items.keycode2 is not null
	and items.keycode is null

	select @keycode_count = count(*)
	from @keycodes

	--need this info for cart_order table
	insert in
to @items_summed (cart_order_id, list_price, unit_price, tax)
	select cart_order_id, sum(list_price), sum(unit_price), sum(tax)
	from @items
	group by cart_order_id

	--check to see if the order is only a cd
	if not exists (select 1
					from @items items
					inner join dbo.cb_product_mapping cb on cb.cb_product_id = items.product_id
					where cb.product_id not in (18100000, 18115000, 18120000))
		set @is_cd_only_order = 1

--------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Marketing opt in/out
--------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- Get status from x-params
	select @customer_opt_in_status = case
			when xparam_value = 'YES' then 1
			when xparam_value = 'NO' then 0
			else null
		end
	from @xparams
	where xparam_name = 'x-newsletter'

	-- Get existing status from customer object if no x-param
	if @customer_opt_in_status is null
		begin
			select @customer_opt_in_status = c.opt_in
			from @keycodes keycodes
			inner join dbo.license l with (nolock) on l.keycode = keycodes.keycode
			inner join dbo.customer c on c.customer_id = l.customer_id
		end

	-- Default if nothing else found
	if @customer_opt_in_status is null
		set @customer_opt_in_status = 1

--------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @notification_type_id = 1 --order
	begin

		if @cart_order_id is null
			set @order_header_id = -2

		if @order_header_id is not null
			set @order_header_id = -3

		if @keycode_count = 0 and @is_cd_only_order = 0
			set @order_header_id = -9

		if @order_header_id is null
		begin

			--load all the variables from xml object
			;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' as cbn,
			'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' as cbt)
                select @cart_customer_json = (select
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:Email)[1]', 'nvarchar(255)') as [customer.customer_email],
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:Firstname)[1]', 'nvarchar(255)') as [customer.first_name], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:Lastname)[1]', 'nvarchar(255)') as [customer.last_name], 
												cast(@customer_opt_in_status as char(1)) as [customer.opt_in], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:Street1)[1]', 'nvarchar(255)') as [customer.address.bill_to.address_1],
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:City)[1]', 'nvarchar(130)') as [customer.address.bill_to.city], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:StateId)[1]', 'nvarchar(2)') as [customer.address.bill_to.state], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:PostalCode)[1]', 'nvarchar(32)') as [customer.address.bill_to.postal_code], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:CountryId)[1]', 'varchar(2)') as [customer.address.bill_to.country],
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:Street1)[1]', 'nvarchar(255)') as [customer.address.ship_to.address_1], 
												@notification_xml.value('(/cbn:PaidOrderNotificatio
n/cbn:Purchase/cbt:DeliveryContact/cbt:City)[1]', 'nvarchar(130)') as [customer.address.ship_to.city], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:StateId)[1]', 'nvarchar(2)') as [customer.address.ship_to.state], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:PostalCode)[1]', 'nvarchar(32)') as [customer.address.ship_to.postal_code], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:CountryId)[1]', 'varchar(2)') as [customer.address.ship_to.country], 
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:InternalCustomer)[1]', 'varchar(255)') as [customer.vendor_customer_code],
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:Company)[1]', 'nvarchar(255)') as [company.company_name],
												@notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:CompanyType)[1]', 'varchar(50)') as [company.company_type_name],
												(select company_type_id from company_type where company_type_name = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:BillingContact/cbt:CompanyType)[1]', 'varchar(50)')) as [company.company_type_id],
												@system_user AS [transaction_user]
										 for json path, without_array_wrapper),
					@vendor_order_date = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:PaymentArriveTime)[1]', 'datetime2'),
					@currency_id = (select currency_id from dbo.currency where currency_code = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:PaymentInfo/cbt:CurrencyId)[1]', 'varchar(5)')),
					@subscription_id = @notification_xml.value('(/*/*/*/*/cbt:RecurringBilling/@cbt:SubscriptionId)[1]', 'varchar(50)'),
					@payment_method_id = (select payment_method_id from dbo.cb_payment_method where cb_payment_method_code = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:PaymentInfo/cbt:PaymentTypeId)[1]', 'varchar(50)')),
					@ship_locale = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/cbt:DeliveryContact/cbt:Locale)[1]', 'nvarchar(5)')

			
			--convert the UTC time in xml to MST
			select @hh_diff = datediff(hh, getutcdate(), getdate())
			select @vendor_order_date = dateadd(hh, @hh_diff, @vendor_order_date)

			--update order data into the cart order table from what we got in XML
			update co
			set vendor_order_code = @vendor_order_code, order_type = 'CBCART', site_id = 'CBCART', site_url = 'CBCART',
				total_amount = items.list_price, sub_total_amount = items.unit_price, tax_amount = items.tax, currency_id = @currency_id, payment_method = 0, 
				session_id = 0, submission_date = isnull(@vendor_order_date, co.submission_date), invoice_in_process_id = 0, cart_order_status_id = 1,
				sales_order_date = isnull(@vendor_order_date, co.submission_date)
			from dbo.cart_order co
			inner join @items_summed items on items.cart_order_id = co.cart_order_id
			where co.cart_order_id = @cart_order_id

			--insert/update cart_customer with customer object parsed from xml
			exec dbo.usp_cart_update_cart_customer @vendor_order_code = @vendor_order_code, @cart_customer_json = @cart_customer_json, @customer_type_id = 1,
					@response_code = @response_code_cc output, @message = @message_cc output

			--audit the cart_order_item data since we are going to delete and then insert below
			insert into dbo.cart_order_item_audit (cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total,
												product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, 
												vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, sap_material_number, storage_gb)

			select cart_order_item_id, cart_order_id, line_item, quantity, order_item_offer_amount, list_price, unit_price, tax_item_total,
					product_id, insert_date, insert_by, modified_date, modified_by, cart_item_bundle_id, start_date, expiration_date, 
					vendor_order_item_code, order_item_update_type_id, license_attribute_license_value, item_hierarchy_id, sap_material_number, storage_gb
			from dbo.cart_order_item
			where cart_order_id = @cart_order_id

			delete dbo.cart_order_item_license
			from dbo.cart_order_item coi
			where coi.cart_order_item_id = cart_order_item_license.cart_order_item_id
			and coi.cart_order_id = @cart_order_id

			delete dbo.cart_order_item_tax
			from dbo.cart_order_item coi
			where coi.cart_order_item_id = cart_order_item_tax.cart_order_item_id
			and coi.cart_order_id = @cart_order_id

			delete j
			from dbo.cart_order_item i
			inner join dbo.cart_order_item_json j 
				on j.cart_order_item_id = i.cart_order_item_id
			where i.cart_order_id = @cart_order_id

			delete dbo.cart_order_item
			where cart_order_id = @cart_order_id

			--this update basically sets what the product id is of non-cd product to the cd product
			--it's used below to set as the bundle so we can later set correct start/end dates on cd
			update @items
			set RefSubSellingItemProductId = product_id
			where RefSubSellingItemProductId is null

			--insert order item data into the cart order item table - consumer products
			insert into dbo.cart_order_item(cart_order_id, vendor_id, vendor_product_id, quantity, line_item, list_price, unit_price, tax_item_total, tax_exempt, 
				product_id, product_locale, invoice_item_in_process_id, license_attribute_license_value, cart_item_bundle_id)
			select @cart_order_id, 9, items.product_id,
				case when @is_cd_only_order = 1 then items.quantity else 1 end,
				items.line_item,
				case when @is_cd_only_order = 1 then items.list_price_single else items.list_price end, 
				case when @is_cd_only_order = 1 then items.unit_price_single else items.unit_price end, 
				case when @is_cd_only_order = 1 then items.tax_single else items.tax end,
				0, cb.product_id, @ship_locale, 0, items.item_opt_in_status, items.RefSubSellingItemProductId
			from @items items
			inner join dbo.cb_product_mapping cb on cb.cb_product_id = items.product_id and cb.seats = case when @is_cd_only_order = 1 then 1 else items.quantity end
			where cb.license_category_id not in (55, 220, 250)

			--insert order item data into the cart order item table - business products
			insert into dbo.cart_order_item(cart_order_id, vendor_id, line_item, vendor_product_id, quantity, list_price, unit_price, tax_item_total, tax_exempt, 
				product_id, product_locale, invoice_item_in_process_id, license_attribute_license_value, cart_item_bundle_id)
			select distinct @cart_order_id, 9, items_business.line_item, items_business.product_id, items_business.quantity, isnull(pp.retail_price, items_business.unit_price_single), items_business.unit_price_single, items_business.tax, 0,
				cb.product_id, @ship_locale, 0, items_business.item_opt_in_status, items_business.RefSubSellingItemProductId
			from @items items_business
			inner join dbo.cb_product_mapping cb on cb.cb_product_id = items_business.product_id and cb.seats = 1
			left join dbo.lu_countries lc on substring(@ship_locale, 4, 2) = lc.iso
			left join dbo.product_pricing pp on cb.product_id = pp.product_id and pp.currency_id = @currency_id and pp.location_code = lc.iso3
			where cb.license_category_id in (55, 220, 250)

			--cart_order_item_license
			insert into dbo.cart_order_item_license(cart_order_item_id, keycode)
			select coi.cart_order_item_id, keycodes.keycode 
			from @keycodes keycodes
			inner join dbo.cart_order_item coi on coi.line_item = keycodes.line_item
			where coi.cart_order_id = @cart_order_id

			--update cart_order_item start and expiration dates
			update coi
			set coi.start_date = ca
se
									when p.product_type_id = 2 and cl.end_date > getdate() then cl.end_date
									else convert(date,getdate())
								end,
				coi.expiration_date = case
										when p.product_type_id = 1 then dateadd(dd,c.capability_activation_days,convert(date,getdate()))
										when p.product_type_id = 2 and cl.end_date > getdate() then dateadd(dd,c.capability_activation_days,cl.end_date)
										when p.product_type_id = 2 and cl.end_date <= getdate() then dateadd(dd,c.capability_activation_days,convert(date,getdate()))
										when p.product_type_id = 3 then cl.end_date
										else dateadd(dd, 365, convert(date,getdate()))
									end
			from dbo.cart_order_item coi
			inner join dbo.product p
					on p.product_id = coi.product_id
			inner join dbo.product_capability c
					on c.product_id = coi.product_id and c.capability_id = 2
			left join dbo.cart_order_item_license coil
					on coil.cart_order_item_id = coi.cart_order_item_id
			left join dbo.license l
					on l.keycode = coil.keycode
			left join dbo.license_category_license cl
					on cl.license_id = l.license_id
			where coi.cart_order_id = @cart_order_id

			--update the cd lines to have correct start and end dates based on what the correspending product was
			update coi2
			set coi2.start_date = coi.start_date,
				coi2.expiration_date = coi.expiration_date
			from dbo.cart_order_item coi
			inner join dbo.product p on p.product_id = coi.product_id
			inner join dbo.cart_order_item coi2 on coi2.cart_order_id = coi.cart_order_id and coi2.cart_item_bundle_id = coi.cart_item_bundle_id
			inner join dbo.product p2 on p2.product_id = coi2.product_id
			where coi.cart_order_id = @cart_order_id
			and (p.product_family_id != 8 or p.product_family_id is null) --not cd product
			and p2.product_family_id = 8 --cd has this

			insert into dbo.payment_header (cart_order_id, payment_merchant_id, payment_status_id, payment_method_id, currency_id)
			select co.cart_order_id, 20, 1, @payment_method_id, @currency_id --hard code cleverbridge (20) as the payment_merchant_id
			from dbo.cart_order co
			where co.cart_order_id = @cart_order_id

			select @payment_header_id = scope_identity()

			--payment_subscription_credit_card
			if @payment_header_id is not null and @subscription_id is not null
				exec dbo.usp_payment_insert_payment_subscription @payment_header_id, @subscription_id, @payment_subscription_id output
			
			--Setting @autorenewal_opt_in_status for the upcoming usp_cart_load_order call
			if @is_cd_only_order = 1 
				begin
					set @autorenewal_opt_in_status = 0
				end
			else if exists (
				select 1 
				from @items i
					inner join dbo.cb_product_mapping cb
						on cb.cb_product_id = i.product_id
					inner join dbo.product p
						on p.product_id = cb.product_id and p.product_family_id <> 8 --Removing CD items from being evalued in setting @autorenewal_opt_in_status
				where i.item_opt_in_status = 0
			) 
				begin
					set @autorenewal_opt_in_status = 0
				end
			else 
				begin
					set @autorenewal_opt_in_status = 1
				end

			exec dbo.usp_cart_load_order @cart_order_id = @cart_order_id, @autorenewal_flag = @autorenewal_opt_in_status, @return_result = 0

			select @order_header_id = order_header_id 
			from dbo.order_header oh
			inner join dbo.vendor_order vo on vo.vendor_order_id = oh.vendor_order_id
			where vo.vendor_order_code = @vendor_order_code

			--update @items with previous CB subscriptions

			if @order_header_id is not null
			begin
				while @keycode_start <= @keycode_count
				begin

					select @keycode = l.keycode,
						   @line_item = keycodes.line_item,
						   @license_id = la.license_id,
						   @license_category_id = lcl.license_category_id
					from @keycodes keycodes
					inner join dbo.license l on l.keycode = keycodes.keycode
					left join dbo.license_category_license lcl on lcl.license_id = l.license_id
					left join dbo
.license_activation la on la.license_id = l.license_id
					where keycode_id = @keycode_start

					if @keycode is not null and @license_id is null
					begin
						exec dbo.usp_license_activate @keycode = @keycode, @GUID = '0'

						--this basically puts new licenses into GSM registration queue to send to Derby
						if @license_category_id = 220
						begin
							insert into dbo.sky_update(license_id, sky_template_id, sky_update_type_id, process_date)
							select l.license_id, sky_template_id = 1, sky_update_type_id = 1, dateadd(mi,5,getdate())
							from dbo.license l
							where l.keycode = @keycode
						end

					end

					select @license_id = NULL
                    
					select @license_id = l.license_id
					from @keycodes keycodes
					inner join dbo.license l on l.keycode = keycodes.keycode
					inner join dbo.payment_subscription ps on keycodes.previous_subscription_id = ps.subscription_id
					where keycodes.keycode_id = @keycode_start
					and keycodes.subscription_id != keycodes.previous_subscription_id

					if @license_id is not null
					begin
						set @license_message_value_str = 'line_item=' + right(str(isnull(@line_item, 1)), 1) + ',' + 'payment_subscription_id=' + str(@payment_subscription_id)
						exec dbo.usp_message_insert_license_message @license_id, 12, @process_date, @process_date, @process_date, @license_message_value_str, @license_message_id output, @return_result = 0
					end

					select @keycode = null, @license_id = null, @line_item = null, @license_category_id = null, @license_message_value_str = null
					select @keycode_start = @keycode_start + 1
				end

				exec dbo.usp_cart_insert_license_update_queue @order_header_id, 1

			end
			else
			begin
				set @order_header_id = -4
			end

		end

	end
	if @notification_type_id in (2, 6) --Full Refund, Chargeback
	begin

		set @refund_comment = 'Cleverbridge full refund for vendor order code: ' + @vendor_order_code

		if @order_header_id is null
		begin
			set @order_header_id = -6
		end
		else
		begin
			while @keycode_start <= @keycode_count
			begin
				select @license_id = l.license_id
				from @keycodes keycodes
				inner join dbo.license l on l.keycode = keycodes.keycode
				where keycodes.keycode_id = @keycode_start

				exec dbo.usp_license_update_license_attribute_license @license_id = @license_id, @license_attribute_id = 1, @license_attribute_license_value = 0, @modified_by = @system_user

				select @keycode_start = @keycode_start + 1
			end
			
			set @keycode_start = 1

			--make sure a partial refund doesn't already exist before doing a full refund
			if not exists(select 1 from dbo.order_header where order_header_id = @order_header_id and order_status_id = 2)
			begin
				exec dbo.usp_cart_refund_full @order_header_id, 3, 8, @refund_comment, @system_user
			end
			else
			begin
				while @keycode_start <= @keycode_count
				begin
					select @keycode = keycodes.keycode,
						   @days = datediff(dd, oi.capability_expiration_date, getdate())
					from @keycodes keycodes
					inner join dbo.license l on l.keycode = keycodes.keycode
					inner join dbo.order_item_license oil on l.license_id = oil.license_id
					inner join dbo.order_item oi on oi.order_item_id = oil.order_item_id and oi.order_header_id = @order_header_id
					where keycodes.keycode_id = @keycode_start

					set @days = iif(@days = 0, 1, @days)

					exec dbo.usp_license_update_license_capability_CSI @days = @days, @keycode = @keycode, @modified_by = @system_user, @response_code = @response_code output, @message = @message output 

					select @keycode_start = @keycode_start + 1
				end
				
				set @notification_type_id = 3  --go to partial refund
			end
		end

	end
	if @notification_type_id = 3 --Partial Refund
	begin

		select @order_items_xml = 
			(
			select items.line_item,
				   cb.product_id,
				   1 as quantity,
				   items.list_price,
	
			   items.unit_price,
				   items.tax
			from @items items
			inner join dbo.cb_product_mapping cb on cb.cb_product_id = items.product_id and cb.seats = case when cb.license_category_id not in (55, 220, 250) then items.quantity else 1 end
			where items.unit_price < 0
			for xml raw ('order_item'), elements
			)

		set @refund_comment = 'Cleverbridge partial refund for vendor order code: ' + @vendor_order_code

		if @order_header_id is null
		begin
			set @order_header_id = -5
		end
		else
		begin
			exec dbo.usp_cart_refund_partial @order_header_id, @order_items_xml, 8, @refund_comment, @system_user
		end

	end
	if @notification_type_id in (4, 5) --Unsubscribe, Subscribe
	begin

		if @order_header_id is null
		begin
			set @order_header_id = -7
		end
		else
		begin
			while @keycode_start <= @keycode_count
			begin
				select @license_id = l.license_id,
					   @license_attribute_license_value = case 
							when @notification_type_id = 4 then 2
							when @notification_type_id = 5 then keycodes.item_opt_in_status end,
					   @subscription_id = keycodes.subscription_id,
					   @previous_subscription_id = keycodes.previous_subscription_id
				from @keycodes keycodes
				inner join dbo.license l on l.keycode = keycodes.keycode
				where keycode_id = @keycode_start

				if @previous_subscription_id = @subscription_id
					exec dbo.usp_license_update_license_attribute_license @license_id = @license_id, @license_attribute_id = 1, @license_attribute_license_value = @license_attribute_license_value, @modified_by = @system_user, @vendor_initiated = 1

				select @keycode_start = @keycode_start + 1
			end
		end

	end

	/*
	|
	|	Add status update to 'Completed'
	|	Failures are captured in the CATCH block
	|
	*/
	UPDATE dbo.cb_notifications
		SET order_header_id = ISNULL(@order_header_id, -8)
			, cb_notification_status_id = 2 -- Completed

	WHERE cb_notification_id = @cb_notification_id

end try

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'dbo.usp_cb_process_notification failed for cb_notification_id ' + CAST( @cb_notification_id AS VARCHAR(10) )
						ELSE @message END

	/*
	|
	|	Update cb_notification as failed
	|
	*/
	UPDATE dbo.cb_notifications
		SET cb_notification_status_id = 3 -- Failed

	WHERE cb_notification_id = @cb_notification_id


	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXECUTE dbo.usp_LogError @ErrorDB = @DBName

END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_process_notification_queue]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_cb_process_notification_queue]


/*	
	DATE		AUTHOR		REMARKS
	2024-07-25	gblandford	Initial creation. https://jira.opentext.com/browse/ECOM-5072
							- Rearchitect - moved logic of processing to this job queue

	DESCRIPTION
	This procedure handles the processing of all 'Pending' cb_notification (Cleverbridge) records.
	
	Previously, dbo.usp_cb_process_notification was executed synchronously from dbo.usp_cb_insert_notification

	This procedure is executed as the first step of the Agent job 'Cleverbridge - Process Notifications'

*/
AS

	SET NOCOUNT ON				
	

	DECLARE	@cb_notification_id INT,
			@vendor_order_code VARCHAR(50),
			@response_code INT,
			@message VARCHAR(100)

	DECLARE @rows INT,
		@id INT


	BEGIN TRY

		DECLARE @cb_notifications TABLE (
			id INT IDENTITY (1, 1), 
			cb_notification_id	INT
		);


		INSERT INTO @cb_notifications (
			cb_notification_id
		) 
		SELECT 
			cb.cb_notification_id

		FROM dbo.cb_notifications cb
		WHERE cb.cb_notification_status_id = 1 -- Pending only
			AND cb.process_date <= GETDATE()
		ORDER BY cb.process_date;
    
		SELECT @rows = @@ROWCOUNT;



		SELECT @id = 1;

		WHILE ( @id <= @rows ) BEGIN

				SELECT
					@cb_notification_id = cb.cb_notification_id
						, @vendor_order_code = cb.cb_purchase_code
				FROM dbo.cb_notifications cb
					INNER JOIN @cb_notifications cbt
						ON cbt.cb_notification_id = cb.cb_notification_id
				WHERE cbt.id = @id	
				
				/*
				|
				|	Process the record
				|
				*/
				EXECUTE dbo.usp_cb_process_notification 
					@cb_notification_id = @cb_notification_id,
					@vendor_order_code = @vendor_order_code;
				
				/*
				|
				|	Mark as complete, ready for archiving
				|
				*/

				SET @id = @id + 1
				
			END;

	


	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'Processing cb_notifications failed, cb_notification_id:' 
														+ CAST(@cb_notification_id AS VARCHAR(10) )
														+ ', vendor_order_code: '
														+ @vendor_order_code 

							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_select_cart_item_url]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_cb_select_cart_item_url]

(
	@cart_order_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2016-06-07	cnovac		Initial creation.
	2016-08-08	cnovac		Fixed bug with Keycode Alias and changed logic on @x_current_expiration_date
	2016-08-09	cnovac		Changed to use cdi.discount so we use % instead of fixed amount
	2016-08-12	cnovac		TA32710 - added keycode Alias translation back in
	2016-08-23	cnovac		TA33838 - changed the url to include purl-shoppingcart
	2016-08-23	cnovac		TA33868 - changed the redirect url to webroot.com/[loc]/[lang]/supportmsp
	2016-08-30	cnovac		Took out isnull when building url and used CASE instead.  PHP treats the output differently.
	2016-08-31	cnovac		Added logic to not show @x_current_expiration_date except for renew
	2016-09-09	cnovac		Added variable to get @client_id
	2017-03-24	cnovac		Added logic to figure out @purl_url
	2017-09-12	cnovac		US24730 - commenting out the upgrade path for discounts in url
	2018-02-15	cnovac		changed code to get discount from discount field instead of cart_discount_item
	2018-03-21	cnovac		changed code to reset @purl_url
	2018-06-04	cnovac		took out all code referencing in_process tables which are getting depricated and took out gamer code.
	2018-10-11	rvinoche	changed url to include dp_ for discounting
	2020-07-24	cnovac		took out logging call

	DESCRIPTION
	select discount
*/
as

set nocount on
	
begin try				

	declare	@language_code varchar(2),
			@location_code varchar(2),
			@currency_code varchar(3),
			@p_rc_str varchar(20),
			@p_ac_str varchar(20),
			@trx_rc_str varchar(20),
			@trx_ac_str varchar(20),
			@x_current_expiration_date varchar(20),
			@recommendation varchar(10),
			@product_id_str varchar(500) = null,
			@product_id varchar(100) = null,
			@prev_product_id_str varchar(500),
			@keycode_str varchar(500),
			@quantity_str varchar(500),
			@min_quantity_str varchar(500),
			@allowmultiple_str varchar(500) = null,
			@discount_str varchar(500),
			@discount_str2 varchar(500),
			@checksum_discount_str varchar(500),
			@checksum varchar(500),
			@counter int = 1,
			@client_id varchar(5),
			@purl_url varchar(50),
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) build cb url inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) create working url parm table
	declare @items int, @cb_rec_id int
	declare @cart_items table (cart_items_id int identity (1, 1), cb_product_mapping_id int, line_item int, quantity int, discount float)

	--1.2) get item count info
	insert into @cart_items(cb_product_mapping_id, line_item, quantity, discount)
	select cb.cb_product_mapping_id,
		   coi.line_item,
		   case when cb.license_category_id in (55, 220, 250) then coi.quantity else cb.seats end,
		   coi.list_price - coi.unit_price
	from cart_order_item coi
	inner join cb_product_mapping cb on cb.product_id = coi.product_id
	where coi.cart_order_id = @cart_order_id
	and cb.is_included_in_url = 1

	select @cb_rec_id = @@rowcount

	select @items = min(cart_items_id)
	from @cart_items

	--1.3) loop through and build items
	while @items <= @cb_rec_id
		begin

			select @product_id = ltrim(rtrim(str(cb.cb_product_id))),
				   @product_id_str = isnull(@product_id_str + ',', '') + isnull(ltrim(rtrim(str(cb.cb_product_id))), ''),
				   @keycode_str = isnull(@keycode_str, '') + isnull('&previouslicense
rno_' + right(ltrim(rtrim(str(@counter))), 1) + '=' + isnull(lka.keycode_alias, l.keycode), ''),
				   @quantity_str = isnull(@quantity_str, '') + isnull('&quantityrno_' + right(ltrim(rtrim(str(@counter))), 1) + '=' + ltrim(rtrim(str(ci.quantity))), ''),
				   @min_quantity_str = case when cb.product_type_id = 2
												then isnull(@min_quantity_str, '') + isnull('&minquantityrno_' + right(ltrim(rtrim(str(@counter))), 1) + '=' + ltrim(rtrim(str(ci.quantity))), '')
												else isnull(@min_quantity_str, '')
											end,
				   @discount_str = case when cdi.discount is not null
											then isnull(@discount_str, '') + isnull('&dprno_' + right(ltrim(rtrim(str(@counter))), 1) + '=__DISCOUNT_INTERVAL:0:' + ltrim(rtrim(str(cdi.discount))) + ':' + 'PCT', '')
										when ci.discount > 0 and cb.license_category_id not in (55, 220, 250)
											then isnull(@discount_str, '') + isnull('&dprno_' + right(ltrim(rtrim(str(@counter))), 1) + '=__DISCOUNT_INTERVAL:0:' + ltrim(rtrim(str(ci.discount/ci.quantity, 20, 9))) + ':' + upper(cu.currency_code), '')
										when ci.discount > 0 and cb.license_category_id in (55, 220, 250)
											then isnull(@discount_str, '') + isnull('&dprno_' + right(ltrim(rtrim(str(@counter))), 1) + '=__PRICE_INTERVAL:0:' + ltrim(rtrim(str(coi.unit_price, 20, 2))) + ':' + upper(cu.currency_code), '')
											else isnull(@discount_str, '')
										end,
				   @discount_str2 = CASE when cdi.discount is not NULL
											THEN ISNULL(@discount_str2,'') + ISNULL('&dp_' + RIGHT(LTRIM(RTRIM(STR(@product_id))), 1) + '=_DISCOUNT:' + LTRIM(RTRIM(STR(coi.list_price))) + ':' + ltrim(rtrim(str(cdi.discount))) + ':' + 'PCT', '') 
										 WHEN ci.discount > 0 AND cb.license_category_id NOT IN (55, 220, 250)
											then isnull(@discount_str2, '') + isnull('&dp_' + RIGHT(LTRIM(RTRIM(STR(@product_id))), 1) + '=__DISCOUNT:' + LTRIM(RTRIM(STR(coi.list_price))) + ':' + ltrim(rtrim(str(ci.discount/ci.quantity, 20, 9))) + ':' + upper(cu.currency_code), '')
										 WHEN ci.discount > 0 and cb.license_category_id in (55, 220, 250)
											THEN isnull(@discount_str2, '') + isnull('&dp_' + RIGHT(LTRIM(RTRIM(STR(@product_id))), 1) + '=__DISCOUNT:' + LTRIM(RTRIM(STR(coi.list_price))) + ':' + ltrim(rtrim(str(coi.unit_price, 20, 9))) + ':' + upper(cu.currency_code), '')
										 ELSE ISNULL(@discount_str2, '')
									END,
				   @checksum_discount_str = case when cdi.discount is not null
													then isnull(@checksum_discount_str, '') + isnull('__DISCOUNT_INTERVAL:0:' + ltrim(rtrim(str(cdi.discount))) + ':' + 'PCT' + '#gdsagfsdf', '')
												 when ci.discount > 0 and cb.license_category_id not in (55, 220, 250)
													then isnull(@checksum_discount_str, '') + isnull('__DISCOUNT_INTERVAL:0:' + ltrim(rtrim(str(ci.discount/ci.quantity, 20, 9))) + ':' + upper(cu.currency_code) + '#gdsagfsdf', '')
												 when ci.discount > 0 and cb.license_category_id in (55, 220, 250)
													then isnull(@checksum_discount_str, '') + isnull('__PRICE_INTERVAL:0:' + ltrim(rtrim(str(coi.unit_price, 20, 2))) + ':' + upper(cu.currency_code) + '#gdsagfsdf', '')
													else isnull(@checksum_discount_str, '')
												 end,
				   @recommendation = case when cb.product_type_id = 3 --upgrade product
											 then 'none'
										  end,
				   @location_code = country.iso,
				   @currency_code = cu.currency_code,
				   @language_code = left(co.locale, 2),
				   @p_rc_str = co.p_rc,
				   @p_ac_str = co.p_ac,
				   @trx_rc_str = co.trx_rc,
				   @trx_ac_str = co.trx_ac,
				   @x_current_expiration_date = case when lc.capability_expiration_date >= getdate() and cb.product_type_id = 2
													 then convert(varchar (20), lc.capability_expiration_date, 112)
													 else null
												end
			from cart_order co
			inner join lu_countries country on right(co.locale, 2) = country.iso
			inner join currency cu on co.currency_id = cu.
currency_id
			inner join cart_order_item coi on co.cart_order_id = coi.cart_order_id
			inner join @cart_items ci on coi.line_item = ci.line_item
			inner join cb_product_mapping cb on cb.cb_product_mapping_id = ci.cb_product_mapping_id
			left join cart_discount_item cdi on coi.cart_discount_id = cdi.cart_discount_id and cdi.product_type_id != 4 and cdi.cart_discount_method_id = 3 and cb.license_category_id not in (55, 220, 250)
			left join cart_order_item_license coil	on coi.cart_order_item_id = coil.cart_order_item_id
			left join license_keycode_alias lka on coil.keycode = lka.keycode
			left join license l on l.keycode = coil.keycode
			left join license_capability lc on lc.license_id = l.license_id and lc.capability_id = 2
			where coi.cart_order_id = @cart_order_id
			and ci.cart_items_id = @items
			group by cb.cb_product_id, cb.license_category_id, coi.unit_price, lka.keycode_alias, l.keycode, ci.quantity, ci.discount, cb.product_type_id, country.iso, cu.currency_code, left(co.locale, 2), co.p_rc, co.p_ac, co.trx_rc, co.trx_ac, lc.capability_expiration_date, cdi.discount, coi.list_price

			select @counter = iif(@product_id_str is null, @counter, @counter + 1)

			if charindex(@product_id, @prev_product_id_str) > 0 
				set @allowmultiple_str = 'true'

			select @prev_product_id_str = @product_id_str

			if @checksum_discount_str != ''
				select @checksum = convert(varchar(500), HASHBYTES('MD5', @checksum_discount_str), 2)
			else
				select @checksum = null

			select @items = min(cart_items_id)
			from @cart_items
			where cart_items_id > @items

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) form cb url
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) verify that we have a cb mapping otherwise log error and send to compare page
	if @product_id_str is null
	begin
		select @location_code = lower(country.iso),
			   @language_code = lower(left(co.locale, 2))
		from cart_order co
		inner join lu_countries country on right(co.locale, 2) = country.iso
		where co.cart_order_id = @cart_order_id

		select 'https://www.webroot.com/' + isnull(@location_code, 'us') + '/' + isnull(@language_code, 'en') + '/company/contact-us' as cb_cart_url
	end
	else
	begin
		select @client_id = cb_client_id from cb_client_identification
		select @purl_url = '/purl-shoppingcart?'

		--2.2) write out url
		select 'https://cart.webroot.com/' + @client_id + @purl_url + 'scope=checkout' +
				'&cart=' + @product_id_str +
				case when @allowmultiple_str is null then '' else '&allowmultiple=' + @allowmultiple_str end +
				@keycode_str +
				@quantity_str +
				@min_quantity_str +
				@discount_str +
				@discount_str2 +
				case when @recommendation is null then '' else '&recommendation=' + @recommendation end +
				case when @checksum is null then '' else '__CHECKSUM:' + @checksum end +
				'&country=' + @location_code +
				'&currency=' + @currency_code +
				'&language=' + @language_code +
				'&x-cart_order_id=' + ltrim(rtrim(str(@cart_order_id))) +
				case when @p_rc_str is null then '' else '&x-p_rc=' + @p_rc_str end +
				case when @trx_rc_str is null then '' else '&x-trx_rc=' + @trx_rc_str end +
				case when @p_ac_str is null then '' else '&x-p_ac=' + @p_ac_str end +
				case when @trx_ac_str is null then '' else '&x-trx_ac=' + @trx_ac_str end +
				case when @x_current_expiration_date is null then '' else '&x-current_expiration_date=' + @x_current_expiration_date end as cb_cart_url

	end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	decl
are @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_select_ecom_product]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_cb_select_ecom_product]

(
	@cb_product_id int = NULL, 
	@product_id int = NULL,
	@seats int = null,
	@cart_discount_id int = null
)
	
/*	
	DATE		AUTHOR		REMARKS
	2016-06-06	cnovac		Initial Creation
	2018-03-06	cnovac		Added more response elements needed for skyrise call to generate keycode
	2018-05-16	cnovac		Updated to return license_type
	2018-06-04	cnovac		Took out gamer code.
	2020-02-13	cnovac		Added item_hierarchy_id, start_date, expiration_date which are needed for skyrise call to create keycode

	DESCRIPTION

*/


AS
	set nocount on				

	declare	@license_category_id int,
			@license_distribution_method_id int,
			@response_code int,
			@message varchar(100)

begin try
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 1.) select
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) cb to ecom
	if @cb_product_id is not null
	begin
		select top 1 @license_category_id = license_category_id from dbo.cb_product_mapping where cb_product_id = @cb_product_id
			
		if exists (select 1 from dbo.cb_product_mapping where cb_product_id = @cb_product_id and license_category_id = 131)
			set @license_distribution_method_id = 894 --gamer
		else if exists (select 1 from dbo.cb_product_mapping where cb_product_id = @cb_product_id and license_category_id in (55, 220, 250))
			set @license_distribution_method_id = 147 --enterprise
		else
			set @license_distribution_method_id = 4 --online

		if @license_category_id in (55, 220, 250)
			select distinct cpm.product_id, cpm.cb_product_name, cpm.cb_product_id, cpm.license_category_id, lc.license_category_name, 
				   isnull(pc.capability_activation_days, 365) as capability_activation_days, isnull(@seats, cpm.seats) as seats, 4 as license_type_id,
				   iif(@license_category_id = 55, 'enterprisemobile,full', 'enterprise,full') as license_type, --hard code to full b/c CB does not trial
				   isnull(ps.storage_gb, 0) as storage_gb, ldm.license_distribution_method_id, ldm.license_distribution_method_code,
				   1 as item_hierarchy_id, cast(getdate() as date) as start_date, dateadd(dd, cast(cpm.years as int)*365, cast(getdate() as date)) as expiration_date
			from dbo.cb_product_mapping cpm
			inner join dbo.license_category lc on lc.license_category_id = cpm.license_category_id
			inner join dbo.license_distribution_method ldm on ldm.license_distribution_method_id = @license_distribution_method_id
			left join dbo.product_capability pc on pc.product_id = cpm.product_id
			left join dbo.product_storage ps on ps.product_id = cpm.product_id
			where cpm.cb_product_id = @cb_product_id
			and cpm.is_included_in_url = 1
		else
			select distinct cpm.product_id, cpm.cb_product_name, cpm.cb_product_id, cpm.license_category_id, lc.license_category_name,
				   isnull(pc.capability_activation_days, 365) as capability_activation_days, isnull(@seats, cpm.seats) as seats, 1 as license_type_id, 'consumer,full' as license_type, --hard code to full b/c CB does not trial
				   isnull(ps.storage_gb, 0) as storage_gb, ldm.license_distribution_method_id, ldm.license_distribution_method_code,
				   1 as item_hierarchy_id, cast(getdate() as date) as start_date, dateadd(dd, cast(cpm.years as int)*365, cast(getdate() as date)) as expiration_date
			from dbo.cb_product_mapping cpm
			inner join dbo.license_category lc on lc.license_category_id = cpm.license_category_id
			inner join dbo.license_distribution_
method ldm on ldm.license_distribution_method_id = @license_distribution_method_id
			left join dbo.product_capability pc on pc.product_id = cpm.product_id
			left join dbo.product_storage ps on ps.product_id = cpm.product_id
			where cpm.cb_product_id = @cb_product_id
			and cpm.seats = @seats
			and cpm.is_included_in_url = 1
	end

	-- 1.2) ecom to cb
	if @product_id is not null
	begin

		select distinct cpm.cb_product_id, cpm.license_category_id
		from dbo.cb_product_mapping cpm
		where cpm.product_id = @product_id
		and cpm.is_included_in_url = 1

	end	

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select product_id failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_cb_update_notification]
-- =============================================================================

 

 

CREATE     PROCEDURE [dbo].[usp_cb_update_notification] 

(		 

@cb_notification_id INT, 

@vendor_order_code VARCHAR(100) OUTPUT 

) 

 

/*	 

DATE		AUTHOR		REMARKS 

2016-06-08	cnovac		Initial creation. 

2024-07-22	gblandford	https://jira.opentext.com/browse/ECOM-5072 

- Rearchitect - do duplicate checking here, only allow duplicates for PartialRefund 

- Case change, formatting, comments and schemas updated 

2024-11-06	gblandford	https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=3040498 

- hotfix - update status to 1 once processed 

 

DESCRIPTION 

This procedure takes a recently inserted cb_notification and extracts the notification_type from the XML body 

which has a common location in the schema 

 

'Order'  

'Partial Refund'  

'Full Refund'  

'Unsubscribe'  

'Subscribe'  

'Chargeback'  

 

It then extracts the vendor_order_code based on that type. 

A duplicate check is now performed for all types EXCEPT 'Partial Refund' - wich can have duplicates. If a duplicate is  

found it is marked as failed. The notification record is updated with the extracted values either way. 

 

 

*/ 

 

AS  

  

SET NOCOUNT ON  

  

BEGIN TRY 

 

DECLARE	@notification_type VARCHAR(25), 

@notification_type_id INT, 

@notification_status_id INT, 

@notification_xml XML, 

@response_code INT, 

@message VARCHAR(100) 

 

SELECT  

@notification_xml = cb_order_body 

, @notification_status_id = cb_notification_status_id -- Will be 0 - 'Received' 

FROM dbo.cb_notifications 

WHERE cb_notification_id = @cb_notification_id 

 

-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 

-- 1.) insert 

-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 

 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @notification_type =   

CASE WHEN @notification_xml.value('(/cbn:PaidOrderNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN  

'Order'  

 WHEN @notification_xml.value('(/cbn:PartialRefundNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN   

'Partial Refund'  

 WHEN @notification_xml.value('(/cbn:RefundNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN   

'Full Refund'  

 WHEN @notification_xml.value('(/cbn:RecurringBillingCanceledNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN   

'Unsubscribe'  

 WHEN @notification_xml.value('(/cbn:RecurringBillingReinstatedNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN   

'Subscribe'  

 WHEN @notification_xml.value('(/cbn:ChargebackNotification/cbn:NotificationDate)[1]', 'datetime') IS NOT NULL THEN   

'Chargeback'  

END 

 

SELECT @notification_type_id = cb_notification_type_id  

FROM dbo.cb_notification_type  

WHERE cb_notification_type_description = @notification_type 

 

IF @notification_type = 'Order' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:PaidOrderNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

IF @notification_t
ype = 'Partial Refund' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:PartialRefundNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

IF @notification_type = 'Full Refund' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:RefundNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

IF @notification_type = 'Unsubscribe' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:RecurringBillingCanceledNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

IF @notification_type = 'Subscribe' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:RecurringBillingReinstatedNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

IF @notification_type = 'Chargeback' 

BEGIN 

;WITH XMLNAMESPACES('http://xml.cleverbridge.com/3.12.0.0/cleverbridgeNotification.xsd' AS cbn,  

'http://xml.cleverbridge.com/3.12.0.0/cleverbridgeTypes.xsd' AS cbt)  

SELECT @vendor_order_code = @notification_xml.value('(/cbn:ChargebackNotification/cbn:Purchase/@cbt:Id)[1]', 'varchar(100)') 

END 

 

/* 

| 

|	Check for duplicate notification here 

| 

*/ 

IF @notification_type <> 'Partial Refund' BEGIN 

IF EXISTS ( SELECT 1  

FROM dbo.cb_notifications cb 

WHERE cb.cb_notification_type_id = @notification_type_id 

AND cb.cb_purchase_code = @vendor_order_code ) BEGIN 

 

SELECT  @notification_status_id = 3 -- Failed 

END 

END 

 

/* 

| 

| If status is still 0, we have successfully parsed, so mark as Pending 

| and ready to be processed 

| 

*/ 

IF @notification_status_id = 0 BEGIN 

SET @notification_status_id = 1 -- 'Pending' 

END 

 

/* 

| 

|	Update the notification with the vendor_order_code, type and status 

| 

*/ 

UPDATE dbo.cb_notifications 

SET cb_purchase_code = @vendor_order_code, 

cb_notification_type_id = @notification_type_id, 

cb_notification_status_id = @notification_status_id, 

modified_date = GETDATE() 

WHERE cb_notification_id = @cb_notification_id 

 

END TRY 

 

BEGIN CATCH 

 

SET @response_code = -200 

SET @message = CASE WHEN @message IS NULL THEN 'insert failed' 

ELSE @message END 

 

DECLARE @DBName NVARCHAR(128) 

SET @DBName = DB_NAME() 

EXECUTE dbo.usp_LogError @ErrorDB = @DBName 

 

END CATCH; 

 

 

 

-- https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=3040498 

--							- hotfix - update status to 1 for all pending records 

-- gblandford 

-- 20241106 

 

BEGIN TRY 

 

DECLARE @cb_notifications TABLE ( 

cb_notification_id INT 

); 

 

INSERT INTO @cb_notifications ( 

cb_notification_id 

) 

SELECT 

cn.cb_notification_id 

FROM dbo.cb_notifications cn 

WHERE cn.cb_notification_status_id = 0 -- 'Received' 

 

BEGIN TRANSACTION -- Start Transaction 

 

UPDATE cn 

SET cn.cb_notification_status_id = 1 -- Pending 

FROM dbo.cb_notifications cn 

INNER JOIN @cb_notifications t 

ON t.cb_notification_id = cn.cb_notification_id 

 

COMMIT WORK -- End Transaction 

PRINT 'Transaction Successful, Committed' 

 

END TRY 

 


BEGIN CATCH  

 

ROLLBACK TRANSACTION -- Something went wrong, ROLLBACK 

PRINT 'Transaction Failed, Rolled back' 

 

END CATCH 

 
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_check_auto_renewal_queue]
-- =============================================================================

CREATE procedure [dbo].[usp_check_auto_renewal_queue]    
as    
/***********************************************************************    
 Procedure:  usp_check_auto_renewal_queue    
    
  Purpouse: Maintain System History    
    
----------------------------------------------------------------------    
 M O D I F I C A T I O N  H I S T O R Y    
        Rev    
  Date     Nbr  Author     Details    
----------------------------------------------------------------------    
 20131007   0.0   cfaulkner  Original version    
 20200221     1.0   esmart  add update_attempts  
    
*********************************************************************/    
set nocount on;    
    
    
declare @reccount bigint    
      , @servername varchar(100)    
      , @subject varchar(400)    
      , @body varchar(4000)    
      , @recipients varchar(800)    
      , @currdate datetime;    
    
select @currdate = getDate();    
    
select @reccount = count(*)    
  from license_message m with (nolock)    
  where m.process_date <= @currdate     
    and m.message_type_id = 3    
       and m.update_attempts = 0  
    and m.message_status_id =1;    
    
if @reccount >= 600    
begin    
  select @servername = @@servername    
       , @subject = left(@reccount,5) + ' unprocessed AR records in queue'    
       , @body = 'There are ' + left(@reccount,5) + ' unprocessed Auto Renewal records in queue as of ' + convert(varchar(30),getdate(),100) + '.'     
               + ' Please verify that the AR Cron Job on prddenscpt1 is running correctly. '     
               + char(10) + char(13)    
               + 'Refer to the following wiki for any needed documentation on the AR process: https://webroot.splunkcloud.com/en-US/app/search/posicron'    
               + char(10) + char(13)    
               + 'This job runs once an hour. '    
               + char(10) + char(13)    
               + 'Email generated via SQL Job Autorenewel Process Check on ' + rtrim(@servername) + '.'    
       , @recipients = 'EBS_DBA_Team@opentext.com;WR-WebDevelopment@opentext.com;CARB-DBMonitoring@opentext.com';     
  exec msdb..sp_send_dbmail     
    @recipients = @recipients,    
    @body = @body,    
    @subject = @subject,    
 --@profile_name='DCO DBA',    
    @importance = 'High';    
end 




GO
