-- =============================================================================


CREATE procedure [dbo].[usp_check_count_sky_update_queue]
AS
/***********************************************************************
 Procedure:	 [usp_check_count_sky_update_queue]

  Purpuse: Monitor sky update queue

----------------------------------------------------------------------
 M O D I F I C A T I O N  H I S T O R Y
  				  Rev
  Date	    Nbr  Author           Details
----------------------------------------------------------------------
 20190219   0.0   ugangichetty    Original version

*********************************************************************/
set nocount on;


declare @reccount bigint
      , @servername varchar(100)
      , @subject varchar(400)
      , @body varchar(4000)
      , @recipients varchar(800)
      , @currdate datetime;

select @currdate = DATEADD(hh, 0, GETDATE());

select @reccount = COUNT(*)
  from sky_update sm with (nolock)
  where --sm.insert_date >= @currdate  and
		sm.sky_update_type_id=4

	PRINT @reccount

if @reccount >= 1000
begin
  select @servername = @@SERVERNAME
       , @subject = left(@reccount,5) + '  Records not getting moved Derby'
       , @body =  'Email generated via SQL Job Monitor sky update on ' + RTRIM(@servername) + '.'
       , @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com;wr-dlwebdevdb@opentext.com;601895f0-7446-4fe8-b862-96fc895060bf+DBOps@alert.victorops.com'; 
  exec msdb..sp_send_dbmail 
    @recipients = @recipients,
    @body = @body,
    @subject = @subject,
	--@profile_name='DCO DBA',
    @importance = 'High';
end










GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_check_create_activate_license_queue]
-- =============================================================================


---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE procedure [dbo].[usp_check_create_activate_license_queue]
as
/***********************************************************************
 Procedure:	 usp_check_auto_renewal_queue

  Purpuse: Monitor email message queue

----------------------------------------------------------------------
 M O D I F I C A T I O N  H I S T O R Y
  				  Rev
  Date	    Nbr  Author     Details
----------------------------------------------------------------------
 20140709   0.0   surpal  Original version

*********************************************************************/
set nocount on;


declare @reccount bigint
      , @servername varchar(100)
      , @subject varchar(400)
      , @body varchar(4000)
      , @recipients varchar(800)
      , @currdate datetime;

select @currdate = DATEADD(hh, -1, GETDATE());

select @reccount = COUNT(*)
  from prevx_update em with (nolock)
  where em.insert_date >= @currdate  and
     em.prevx_update_type_id = 1
    
	PRINT @reccount

if @reccount >= 50
begin
  select @servername = @@SERVERNAME
       , @subject = left(@reccount,5) + ' license keycodes not activated for past 1 hr'
       , @body = 'There are ' + left(@reccount,5) + ' keycodes not activated for unknown reasons in past 1 hr as of ' + CONVERT(varchar(30),GETDATE(),100) + '. Please Investigate! '
               + char(10) + char(13) 
			   + ' This job runs once an hour. '
			   + 'Keycode activations are handled by prevx_update queue.'
			   + char(10) + char(13)
               + 'Email generated via SQL Job Monitor keycode activation on ' + RTRIM(@servername) + '.'
       , @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com;wr-dlwebdevdb@opentext.com;601895f0-7446-4fe8-b862-96fc895060bf+DBOps@alert.victorops.com'; 
  exec msdb..sp_send_dbmail 
    @recipients = @recipients,
    @body = @body,
    @subject = @subject,
	--@profile_name='DCO DBA',
    @importance = 'High';
end







GO
