CREATE procedure [dbo].[usp_check_email_message_queue]
as
/***********************************************************************
Procedure:	 usp_check_auto_renewal_queue
 
  Purpuse: Monitor email message queue
 
----------------------------------------------------------------------
M O D I F I C A T I O N  H I S T O R Y
  				  Rev
  Date	    Nbr  Author     Details
----------------------------------------------------------------------
20140620   0.0   surpal  Original version
20230526	1.0   psatish ECOM-1521 Ignore the email_id contains nospam.today
*********************************************************************/
set nocount on;
 
 
declare @reccount bigint
      , @servername varchar(100)
      , @subject varchar(400)
      , @body varchar(4000)
      , @recipients varchar(800)
      , @currdate datetime;
 
select @currdate = DATEADD(hh, -1, GETDATE());
 
select @reccount = COUNT(*)
from email_message em with (nolock)
left join dbo.email_message_html ht
on		ht.email_message_id = em.email_message_id
and		ht.customer_email like '%nospam.today%'
where	em.process_date >= @currdate 
and		em.email_message_status_id = 3
and		ht.email_message_html_id is null
PRINT @reccount
 
if @reccount >= 100
begin
  select @servername = @@SERVERNAME
       , @subject = left(@reccount,5) + ' email messages failed to send in past 1 hr'
       , @body = 'There are ' + left(@reccount,5) + ' email  messages to the recipients failed for unknown reasons in past 1 hr as of ' + CONVERT(varchar(30),GETDATE(),100) + '. Please Investigate! '
               + char(10) + char(13) 
   + ' This job runs once an hour. '
   + 'These email message queue are processed by cron job /home/wr_webroot/webdev_trunk/applications/cron/extensions/console/exactTarget  runs on prddenscpt3.services.webroot'
   + char(10) + char(13)
               + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.'
       , @recipients = 'CT_DBA_Team@opentext.com;wr-DLWebDevDB@opentext.com;CARB-DBmonitoring@opentext.com'; 
  exec msdb..sp_send_dbmail 
    @recipients = @recipients,
    @body = @body,
    @subject = @subject,
    @importance = 'High';
end
 
 


GO
