-- =============================================================================

CREATE PROCEDURE [dbo].[usp_check_oracle_update_queue]

/*
    DATE        AUTHOR      REMARKS
    2021-08-24  gblandford	New procedure

    DESCRIPTION
    Monitor the oracle update queue.

	Compares transactions in the oracle_update and oracle_update_failure tables agains configured thresholds
	to determine if there are potential processing issues. Issues are then reported via email for investigation.
*/

AS

	SET NOCOUNT ON;

	DECLARE @failed_count BIGINT
		  , @update_count BIGINT
		  , @servername VARCHAR(100)
		  , @subject VARCHAR(400)
		  , @body VARCHAR(4000)
		  , @recipients VARCHAR(800)
		  , @currdate DATETIME
		  , @response_code INT
		  , @message varchar(100)
		  , @update_threshold INT
		  , @failure_threshold INT
		  , @notify BIT;

	SELECT @currdate = DATEADD(hh, -1, GETDATE()); -- 1 hour ago

	SELECT @notify = 0;

	BEGIN TRY
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.0) select threshold values from dbo.api
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		SELECT
			@update_threshold = api1.record_threshold,
			@failure_threshold = api2.record_threshold

		FROM dbo.api api1 WITH (NOLOCK)
		INNER JOIN dbo.api api2 WITH (NOLOCK) ON api2.api_description = api1.api_description AND api2.api_queue_name = 'oracle_update_failure'

		WHERE api1.api_description = 'oracle_update'
		AND api1.api_queue_name = 'oracle_update';
	
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.0) get queue counts 
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.0.1) update queue 
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		SELECT 
			@update_count = COUNT(*)
		FROM dbo.oracle_update ou WITH (NOLOCK)
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.0.2) failed 
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		SELECT 
			@failed_count = COUNT(*)
		FROM dbo.oracle_update_failure ouf WITH (NOLOCK)
		WHERE ouf.process_date >= @currdate;
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1) check counts against thresholds
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1.1) oracle_update - check queued items in last hour against threshold (>=300)
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF @update_count >= @update_threshold
			BEGIN
			  SELECT @servername = @@SERVERNAME
				   , @subject = LEFT(@update_count,5) + ' oracle updates queued and not processed in the past 1 hr  (threshold=' + LEFT(@update_threshold,5) + ')'
				   , @body = 'There are ' + LEFT(@update_count,5) + ' oracle updates not processed for unknown reasons in past 1 hr as of ' 
+ CONVERT(VARCHAR(30),GETDATE(),100) + '. Please Investigate! '
						   + CHAR(10) + CHAR(13) 
						   + ' This job runs once an hour. '
						   + 'These oracle update queues are processed by cron job ecom/webdev_trunk/applications/cron/extensions/console/oracleUpdate  runs on prddenscpt2.services.webroot'
						   + CHAR(10) + CHAR(13)
						   + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.'
				   , @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;wr-DLWebDevDB@opentext.com;CARB-DBmonitoring@opentext.com'
				   , @notify = 1;
			END
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1.2) oracle_update_failure - check failed items in last hour against threshold (>=10)
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF @failed_count >= @failure_threshold AND @notify = 0
			BEGIN
			  SELECT @servername = @@SERVERNAME
				   , @subject = LEFT(@failed_count,5) + ' oracle updates failed in the past 1 hr (threshold=' + LEFT(@failure_threshold,5) + ')'
				   , @body = 'There are ' + LEFT(@failed_count,5) + ' oracle update failures for unknown reasons in past 1 hr as of ' + CONVERT(VARCHAR(30),GETDATE(),100) + '. Please Investigate! '
						   + CHAR(10) + CHAR(13) 
						   + ' This job runs once an hour. '
						   + 'These oracle update queues are processed by cron job ecom/webdev_trunk/applications/cron/extensions/console/oracleUpdate  runs on prddenscpt2.services.webroot'
						   + CHAR(10) + CHAR(13)
						   + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.'
				   , @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;wr-DLWebDevDB@opentext.com;CARB-DBmonitoring@opentext.com'
				   , @notify = 1;
			END
			
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.3) send mail
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF @notify = 1
		BEGIN
			EXEC msdb..sp_send_dbmail 
					@recipients = @recipients,
					@body = @body,
					@subject = @subject,
					@importance = 'High';
		END
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'usp_check_oracle_update_queue failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName

	END CATCH







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_check_prevx_update_queue]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_check_prevx_update_queue]
AS
/*	
	DATE		AUTHOR		REMARKS
	2025-05-14	psatish		Initial creation
	2025-11-17	gblandford	US-5101992 - https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5101992
							- summarize counts by status and DISTI


	Monitor the prevx update queue

	DESCRIPTION

*/

SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

BEGIN TRY

	DECLARE @_CR VARCHAR(2) = CHAR(13), -- CHAR(10) + CHAR(13),
		@_SPACER VARCHAR(100) = REPLICATE(' ', 100);
		
    DECLARE @record_count INT,
            @servername VARCHAR(100),
            @subject VARCHAR(400),
            @body VARCHAR(MAX),
            @recipients VARCHAR(800),
            @current_date DATETIME = GETDATE(),
            @check_date DATETIME,
            @LICENSES_COUNT INT,
			@summary_body VARCHAR(MAX),
			@rows INT,
			@row_counter INT

	DECLARE @summary TABLE (
		id INT IDENTITY( 1, 1 ),
		prevx_update_status_id INT,
		license_distribution_method_name VARCHAR(100),
		_count INT
	);

	DECLARE @status VARCHAR(20) = '',
		@last_status VARCHAR(20) = '',
		@disti_name VARCHAR(100) = '',
		@counter VARCHAR(10) = '';


    SELECT @LICENSES_COUNT = ac.value
    FROM dbo.fn_app_config_select_key_values('MONITOR_PREVX_QUEUE', 'SQL_SERVER_AGENT_JOBS') ac;

    SELECT @recipients = ac.value
    FROM dbo.fn_app_config_select_key_values('PREVX_QUEUE_EMAIL_RECEIPIENTS', 'SQL_SERVER_AGENT_JOBS') ac;

	--SET @recipients = 'gblandford@opentext.com';

	SELECT 
		@record_count = COUNT(*)
	FROM dbo.prevx_update prvx
	WHERE prvx.process_date <= @current_date
	
    IF @record_count > @LICENSES_COUNT BEGIN

		INSERT INTO @summary (
		    prevx_update_status_id,
		    license_distribution_method_name,
		    _count
		)
		SELECT 
			prvx.prevx_update_status_id,
			ldm.license_distribution_method_name,
			_count = COUNT(*)
		FROM dbo.prevx_update prvx
			INNER JOIN dbo.license l 
				ON l.license_id = prvx.license_id
			INNER JOIN dbo.prevx_update_status prvxs
				ON prvxs.prevx_update_status_id = prvx.prevx_update_status_id
			INNER JOIN dbo.license_distribution_method ldm
				ON ldm.license_distribution_method_id = l.license_distribution_method_id
		WHERE prvx.process_date <= @current_date
		GROUP BY prvx.prevx_update_status_id,
			ldm.license_distribution_method_name
		ORDER BY prvx.prevx_update_status_id,
			ldm.license_distribution_method_name

		--SELECT 
		--	s.status,
		--	s.license_distribution_method_name,
  --          s._count
		--FROM @summary s

		--ORDER BY s.status,
		--	s.license_distribution_method_name

		SELECT @rows = COUNT(*) FROM @summary;
		SET @row_counter = 1;
		SELECT @summary_body = 'Status              Distribution Method	(Records)' + @_CR
			+ '---------------------------------------------------------------------------------------------------------------------------------------' + @_CR;

		WHILE ( @row_counter <= @rows ) BEGIN

				SELECT 
					@status = prvxs.prevx_update_status_name,
					@disti_name = s.license_distribution_method_name,
					@counter = CAST(s._count AS VARCHAR(10) )
				FROM @summary s
					INNER JOIN dbo.prevx_update_status prvxs
						ON prvxs.prevx_update_status_id = s.prevx_update_status_id
				WHERE s.id = @row_counter;

				SET @summary_body = @summary_body + @_CR

				IF @status <> @last_status BEGIN
						IF @last_status <> '' SET @summary_body = @summary_body;
						SET @summary_body = @summary_body + LEFT( RTRIM ( @status ) + @_SPACER, 50) + @_CR + REPLICATE( ' ', 30) 
					END
				ELSE BEGIN
						SET @summary_body = @summary_body + REPLICATE( ' ', 30 )
					END

				SET @summary_body = @summary_body 
+ LEFT( RTRIM ( @disti_name ) + @_SPACER, 50) + ' (' + @counter + ')';

				SELECT @row_counter = @row_counter + 1,
					@last_status = @status;
			END

        SELECT @servername = @@servername,
               @subject = 'Prevx Update Queue Alert',
               @body
                   = 'There are ' + CAST(@record_count AS VARCHAR(10)) + ' prevx_update records in the queue as of '
                     + CONVERT(VARCHAR(30), GETDATE(), 100) + '. Please Investigate. ' + + CHAR(10) + CHAR(13)
					 + RTRIM(@summary_body) + CHAR(10) + CHAR(13)
                     + 'This job runs once an hour. ' + CHAR(10) + CHAR(13)

					 + 'Steps to investigate:' + CHAR(10) 

                     + '   - Ensure the cron job [skyrise_update/bin/prevx-queue] has not died. If unsure, kill the cron and restart.' + CHAR(10) + CHAR(13)
					 + '   - If there is a large influx of records into the queue, such as a license churn event, a TSO may be required' + CHAR(10)
					 + '     to temporarily remove them from the queue and re-introduce them at a slower rate to ensure regular updates are' + CHAR(10)
					 + '     being serviced in a timely manner.' + CHAR(10) + CHAR(13)
                     + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.',
               @recipients = @recipients

        EXECUTE msdb..sp_send_dbmail @recipients = @recipients,
                                  @body = @body,
                                  @subject = @subject,
                                  @importance = 'High';

    END

END TRY
BEGIN CATCH
	
END CATCH

GO
