-- PROCEDURE: [dbo].[usp_check_SFDC_opportunity_update_queue]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_check_SFDC_opportunity_update_queue]
AS
/*	
	DATE		AUTHOR		REMARKS
	2024-01-24	cibach		intial creation

	DESCRIPTION
	Check total length of SFDC Opportunity Update Queue, as well as 
	Number of queue items for external_order, sap_update_license, finalize_opportunity_load and update_marketo
	templates

	DEPENDENCIES
	This procedure is called by "Monitor Queues" job
*/
BEGIN
    SET NOCOUNT ON;

    DECLARE @totalcount BIGINT,                    -- total items in queue
            @externalordercount BIGINT,            -- count of external_order template
            @sapupdatecount BIGINT,                -- count of sap_update_license
            @finalopploadcount BIGINT,             -- count of finalize_opportunity_load
            @updatemarketocount BIGINT,            --count of update_marketo
            @totalerror VARCHAR(200) = '',         --error string for total items
            @externalordererror VARCHAR(200) = '', --error string for external_orders
            @sapupdateerror VARCHAR(200) = '',     --error string for sap_update_license
            @finalopploaderror VARCHAR(200) = '',  --error string for finalize_opportunity_load
            @updatemarketoerror VARCHAR(200) = '', --error string for update_marketo
            @servername VARCHAR(100),
            @subject VARCHAR(400),
            @body VARCHAR(4000),
            @recipients VARCHAR(800),
            @toomany BIT = 0;                      -- are any counts too high

    SELECT @totalcount = COUNT(*)
    FROM dbo.sfdc_opportunity_update WITH (NOLOCK);

    SELECT @externalordercount = COUNT(*)
    FROM dbo.sfdc_opportunity_update sou WITH (NOLOCK)
        INNER JOIN dbo.sfdc_template st
            ON st.sfdc_template_id = sou.sfdc_template_id
    WHERE st.sfdc_template_name = 'external_order';

    SELECT @sapupdatecount = COUNT(*)
    FROM dbo.sfdc_opportunity_update sou WITH (NOLOCK)
        INNER JOIN dbo.sfdc_template st
            ON st.sfdc_template_id = sou.sfdc_template_id
    WHERE st.sfdc_template_name = 'sap_update_license';

    SELECT @finalopploadcount = COUNT(*)
    FROM dbo.sfdc_opportunity_update sou WITH (NOLOCK)
        INNER JOIN dbo.sfdc_template st
            ON st.sfdc_template_id = sou.sfdc_template_id
    WHERE st.sfdc_template_name = 'finalize_opportunity_load';

    SELECT @updatemarketocount = COUNT(*)
    FROM dbo.sfdc_opportunity_update sou WITH (NOLOCK)
        INNER JOIN dbo.sfdc_template st
            ON st.sfdc_template_id = sou.sfdc_template_id
    WHERE st.sfdc_template_name = 'update_marketo';

    /*
	PRINT @totalcount;

    PRINT @externalordercount;
    PRINT @sapupdatecount;
    PRINT @finalopploadcount;
    PRINT @updatemarketocount;
	*/

    IF @totalcount > 400
    BEGIN
        SET @toomany = 1;
        SET @totalerror
            = 'There are ' + CAST(@totalcount AS VARCHAR(10))
              + ' total records in the sfdc_opportunity_update queue, alert threshold is 400' + CHAR(10);
    END;

    IF @externalordercount > 60
    BEGIN
        SET @toomany = 1;
        SET @externalordererror
            = 'There are ' + CAST(@externalordercount AS VARCHAR(10))
              + ' external_order template records in the sfdc_opportunity_update queue, alert threshold is 60'
              + CHAR(10);
    END;

    IF @sapupdatecount > 20
    BEGIN
        SET @toomany = 1;
        SET @sapupdateerror
            = 'There are ' + CAST(@sapupdatecount AS VARCHAR(10))
              + ' sap_update_license template records in the sfdc_opportunity_update queue, alert threshold is 20.'
              + CHAR(10);
    END;

    IF @finalopploadcount > 25
    BEGIN
    
    SET @toomany = 1;
        SET @finalopploaderror
            = 'There are ' + CAST(@finalopploadcount AS VARCHAR(10))
              + ' finalize_opportunity_load template records in the sfdc_opportunity_update queue, alert threshold is 25.'
              + CHAR(10);
    END;

    IF @updatemarketocount > 15
    BEGIN
        SET @toomany = 1;
        SET @updatemarketoerror
            = 'There are ' + CAST(@updatemarketocount AS VARCHAR(10))
              + ' update marketo template records in the sfdc_opportunity_update queue, alert threshold is 15.'
              + CHAR(10);
    END;

    --PRINT @toomany

    IF @toomany = 1
    BEGIN
        SELECT @servername = @@SERVERNAME,
               @subject = 'SFDC Opportunity Update Queue Length Alert',
               @body
                   = 'As of ' + CONVERT(VARCHAR(30), GETDATE(), 100) + ': ' + CHAR(10) + @totalerror
                     + @externalordererror + @sapupdateerror + @finalopploaderror + @updatemarketoerror + CHAR(10)
                     + 'This job runs once an hour. '
                     + 'This queue is processed by cron job /var/www/html/webdev_trunk/applications/cron/extensions/console/sfdcUpdateOpportunity runs on prddenscpt3.services.webroot'
                     + CHAR(10) + CHAR(13) + 'Email generated via SQL Job Monitor email message on '
                     + RTRIM(@servername) + '.',
               @recipients
                   = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com;wr-DLWebDevDB@opentext.com';

        --PRINT @body;

        EXEC msdb..sp_send_dbmail @recipients = @recipients,
                                  @body = @body,
                                  @subject = @subject,
                                  @importance = 'High';
    END;
END;

GO
