CREATE PROCEDURE [dbo].[usp_check_SFDC_queues]
AS
/*	
	DATE		AUTHOR		REMARKS
	2022-10-13	mrobbins	intial creation

	DESCRIPTION

*/
SET NOCOUNT ON;


DECLARE @reccount BIGINT, 
	@servername VARCHAR(100),
	@subject VARCHAR(400),
	@body VARCHAR(4000),
	@recipients VARCHAR(800),
	@currdate DATETIME;

SELECT @currdate = DATEADD(hh, -1, GETDATE());

SELECT @reccount = COUNT(*)
FROM dbo.sfdc_opportunity_update WITH (NOLOCK)
WHERE process_date >= @currdate 

PRINT @reccount

IF @reccount >= 55
BEGIN   
SELECT @servername = @@SERVERNAME,
	@subject = 'SFDC Opportunity Update Queue Alert',
	@body = 'There are ' + left(@reccount,5) + ' sfdc_opportunity_update records in the queue in the past 1 hr as of ' + CONVERT(varchar(30),GETDATE(),100) + '. Please Investigate. '
               + char(10) + char(13) 
			   + ' This job runs once an hour. '
			   + 'This queue is processed by cron job /var/www/html/webdev_trunk/applications/cron/extensions/console/sfdcUpdateOpportunity runs on prddenscpt3.services.webroot'
			   + char(10) + char(13)
               + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.',
	@recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com;wr-DLWebDevDB@opentext.com'; 
	--

  EXEC msdb..sp_send_dbmail   
    @recipients = @recipients,
    @body = @body,
    @subject = @subject,
    @importance = 'High';
END 


SELECT @reccount = 0, 
	@subject = '',
	@body = ''

SELECT @reccount = COUNT(*)
FROM dbo.sfdc_opportunity_load WITH (NOLOCK)
WHERE process_date >= @currdate 

PRINT @reccount

IF @reccount >= 17
BEGIN   
SELECT @servername = @@SERVERNAME,
	@subject = 'SFDC Opportunity Load Queue Alert',
	@body = 'There are ' + left(@reccount,5) + ' sfdc_opportunity_load records in the queue in the past 1 hr as of ' + CONVERT(varchar(30),GETDATE(),100) + '. Please Investigate. '
               + char(10) + char(13) 
			   + ' This job runs once an hour. '
			   + 'This queue is processed by cron job /var/www/html/webdev_trunk/applications/cron/extensions/console/sfdcLoadOpportunity that runs on prddenscpt3.services.webroot'
			   + char(10) + char(13)
               + 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.',
	@recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBmonitoring@opentext.com;wr-DLWebDevDB@opentext.com'; 


  EXEC msdb..sp_send_dbmail   
    @recipients = @recipients,
    @body = @body,
    @subject = @subject,
    @importance = 'High';
END 




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_client_guid_insert_client_guid]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_client_guid_insert_client_guid]

(
	@client_name nvarchar(255),
	@client_email varchar(100)

)

AS


/*	
	DATE			AUTHOR		REMARKS
	2018-05-03		acoffel		Initial creation.
		

	DESCRIPTION
	insert client guid
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100),
			@message_service_client_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  check for existing client guid
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 
	if (select count(*) from message_service_client where client_email = 'schindarkar-bendkhale@webroot.com' and message_service_client_status_id = 2) > 0
		begin 
			update message_service_client set message_service_client_status_id = 3, last_modified_date = getdate(), last_modified_by = system_user where client_email = @client_email
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  insert new client guid
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert new client
	insert into message_service_client(client_name, client_email, message_service_client_status_id, look_ups, insert_date, insert_by, last_modified_date, last_modified_by)
	values (@client_name, @client_email, 2, 0, getdate(), system_user, getdate(), SYSTEM_USER)	

	-- 2.2) return partner_service_log_id
	select @message_service_client_id = SCOPE_IDENTITY()

	-- 2.3) select record back out
	select message_service_client_id = @message_service_client_id, client_name = client_name, client_email = client_email, client_guid = convert(varchar(36),client_guid), message_service_client_status_id = message_service_client_status_id, look_ups = look_ups
	from message_service_client 
	where message_service_client_id = @message_service_client_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_client_guid_select_client_guid]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_client_guid_select_client_guid]

(
	@client_guid varchar(36)

)

AS


/*	
	DATE			AUTHOR		REMARKS
	2018-05-03		acoffel		Initial creation.
		

	DESCRIPTION
	select client guid
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100),
			@message_service_client_id int,
            @message_service_client_status_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  check for canceled id
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check status
	select @message_service_client_status_id  = message_service_client_status_id  from message_service_client where message_service_client_id = @message_service_client_id 

	-- 1.2) send canceled message
	if @message_service_client_status_id = 3
		begin 
			select client_status = 'client id is canceled'
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  select client guid
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	-- 2.1) select new client
	select @message_service_client_id = case when message_service_client_id is not null then message_service_client_id else NULL end FROM message_service_client where convert(varchar(36),client_guid) = @client_guid

	-- 2.2) return partner_service_log_id
	if @message_service_client_id IS NOT NULL
		begin 
			--update dbo.message_service_client
			--set --message_service_client_status_id = 2,
			--	look_ups = look_ups + 1,
			--	last_modified_date = getdate(),
			--	last_modified_by = system_user
			--where message_service_client_id = @message_service_client_id

			select message_service_client_id = @message_service_client_id, client_name = client_name, client_email = client_email, client_guid = convert(varchar(36),client_guid), message_service_client_status_id = message_service_client_status_id, look_ups = look_ups
			from dbo.message_service_client
			where message_service_client_id = @message_service_client_id
			AND message_service_client_status_id = 2
		end
		else
		begin
			return
		end			

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_client_upload_bug]
-- =============================================================================
/*
2010-04-02	dsmelker	Created

Purpose: Reduce the parallel queries with the MAXDOP option.

Deployment: Run this on Ecommerce

*/
CREATE  PROCEDURE [dbo].[usp_client_upload_bug] 
(@email nvarchar(40) = null,
@keycode nvarchar(40) = null,
@guid nvarchar(40) = null,
@product_version nvarchar(40) = null,
@os nvarchar(40) = null,
@lang nvarchar(2) = null,
@loc nvarchar(3) = null,
@type char(1) = 'b',
@location nvarchar(200) = null,
@comment nvarchar(1000) = null,
@br_class nvarchar(40) = '',
@br_message nvarchar(200) = '',
@br_application nvarchar(40) = '',
@br_version nvarchar(40) = '',
@product_id int = null,
@unique_header varchar(128) = null
)
AS
/*	DATE		AUTHOR		REMARKS
	12/07/07	bjordan		Initial creation.
	10/23/08	flai		change @br_message from nvarchar(40) = '' to nvarchar(200) = '',
	04/02/10	dsmelker	Added MAXDOP 1 to the select statements
	
	DESCRIPTION
	Writes client bugs to appropriate tables

*/
begin try
SET NOCOUNT ON

declare @client_upload_id int
declare @bug_report_header_id int
declare @total_uploads int
declare @maximum_uploads int
declare @upload_flag int --0 not needed, 1 need upload

set @upload_flag = 1

INSERT INTO [client_upload]
           ([email]
           ,[keycode]
           ,[guid]
		   ,[product_id]
           ,[product_version]
           ,[os]
           ,[lang]
           ,[loc]
           ,[type]
           ,[location]
           ,[comment])
     VALUES
           (@email
           ,@keycode
           ,@guid
		   ,@product_id
           ,@product_version
           ,@os
           ,@lang
           ,@loc
           ,@type
           ,@location
           ,@comment)

set @client_upload_id = @@identity

if @type = 'b'
	begin
	
	if @unique_header is null or @unique_header = ''
		begin
			select @bug_report_header_id = min(ch.bug_report_header_id),
				   @total_uploads = max(total_uploads),
				   @maximum_uploads = max(maximum_uploads) -- forcing a value of 1 when null for process flow
			from client_upload_bug_report c
			inner join client_upload_bug_report_header ch 
				on c.bug_report_header_id = ch.bug_report_header_id
			where br_class = isnull(@br_class,'') and
				  br_message = isnull(@br_message,'') and
				  br_application = isnull(@br_application,'') and
				  br_version = isnull(@br_version,'')
			option (MAXDOP 1);
		end
	else
		begin
			select @bug_report_header_id = min(ch.bug_report_header_id),
				   @total_uploads = max(total_uploads),
				   @maximum_uploads = max(maximum_uploads) -- forcing a value of 1 when null for process flow
			from client_upload_bug_report c
			inner join client_upload_bug_report_header ch 
				on c.bug_report_header_id = ch.bug_report_header_id
			where unique_header = @unique_header
			option (MAXDOP 1);
		end

	
	if @bug_report_header_id is null
		begin
	
		insert into client_upload_bug_report_header(total_uploads)
		values(0)

		set @bug_report_header_id = @@identity

		end
	

	INSERT INTO [client_upload_bug_report]
	   ([bug_report_header_id]
	   ,[client_upload_id]
	   ,[br_class]
	   ,[br_message]
	   ,[br_application]
	   ,[br_version]
		,[unique_header])
	 VALUES
		   (@bug_report_header_id
		   ,@client_upload_id
		   ,isnull(@br_class,'')
		   ,isnull(@br_message,'')
		   ,isnull(@br_application,'')
		   ,isnull(@br_version,'')
			,@unique_header)

	update client_upload_bug_report_header
		set total_uploads = total_uploads + 1
		where bug_report_header_id = @bug_report_header_id

	if isnull(@total_uploads,0) >= isnull(@maximum_uploads,1)
		begin
			set @upload_flag = 0
		end
	end

select @client_upload_id as client_upload_id, @upload_flag as upload_flag			

end try
begin catch
	

	selec
t 0 as client_upload_id, 0 as upload_flag	

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	
end catch;
GO
