-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_geocode_insert_address_components]
-- =============================================================================

create   procedure [dbo].[usp_company_address_geocode_insert_address_components]
    @geocode_result_id int,
    @response nvarchar(max) = null
as
    /*
        DATE        AUTHOR      REMARKS
        2020-04-29  jnavarra    Initial creation

        DESCRIPTION
        Parse geocoder results into address components
    */

    set nocount on;

    begin try

        declare
            @response_code int,
            @message varchar(100);



        -- Delete any previous results
        delete
        from dbo.geocode_result_address_component
        where geocode_result_id = @geocode_result_id



        -- Get the response
        if @response is null
            begin
                select @response = req.response
                from dbo.geocode_result res
                    inner join dbo.geocode_request req
                        on req.geocode_request_id = res.geocode_request_id
                where res.geocode_result_id = @geocode_result_id
            end



        -- Make sure all address component types are available
        insert into dbo.address_component (address_component_name, insert_date)
        select distinct j.type, getdate()
        from dbo.fn_parse_google_address_components(@response) j
            left join dbo.address_component ac
                on j.type = ac.address_component_name
        where ac.address_component_id is null



        -- Parse and insert
        insert into dbo.geocode_result_address_component (geocode_result_id, address_component_id, short_value, long_value)
        select @geocode_result_id, ac.address_component_id, j.short_name, j.long_name
        from dbo.fn_parse_google_address_components(@response) j
            inner join dbo.address_component ac
                on j.type = ac.address_component_name
    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'insert company address geocode address components failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_geocode_insert_request]
-- =============================================================================

CREATE    procedure [dbo].[usp_company_address_geocode_insert_request]
    @company_address_id int,
    @geocode_type_name varchar(50),
    @request nvarchar(2000),
    @geocode_request_id int output
as
    /*
        DATE        AUTHOR      REMARKS
        2020-03-13  jnavarra    Initial creation

        DESCRIPTION
        Insert geocode_request
    */

    set nocount on;

    begin try

        declare
            @geocode_type_id int,
            @response_code int,
            @message varchar(100)

        select @geocode_type_id = geocode_type_id
        from dbo.geocode_type
        where geocode_type_name = @geocode_type_name



        -- Expire existing responses
        update gr
        set gr.response_expiration_date = getdate(),
            gr.last_modified_date = getdate()
        from dbo.geocode_request gr
            inner join dbo.company_address_geocode_request cagr
                on cagr.geocode_request_id = gr.geocode_request_id
        where cagr.company_address_id = @company_address_id
            and gr.geocode_type_id = @geocode_type_id
            and (gr.response_expiration_date is null or gr.response_expiration_date > getdate())

        -- Expire existing results
        update gres
        set gres.expiration_date = getdate(),
            gres.last_modified_date = getdate()
        from dbo.geocode_result gres
            inner join dbo.geocode_request greq
                on greq.geocode_request_id = gres.geocode_request_id
            inner join dbo.company_address_geocode_request cagr
                on cagr.geocode_request_id = gres.geocode_request_id
        where cagr.company_address_id = @company_address_id
            and greq.geocode_type_id = @geocode_type_id
            and (gres.expiration_date is null or gres.expiration_date > getdate())



        insert into  dbo.geocode_request (geocode_type_id, request, request_date, response, response_date, response_expiration_date, last_modified_date)
        values (@geocode_type_id, @request, getdate(), null, null, null, getdate())
        
        set @geocode_request_id = scope_identity()

        insert into dbo.company_address_geocode_request (company_address_id, geocode_request_id)
        values (@company_address_id, @geocode_request_id)

    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'insert company address geocode request failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_geocode_insert_result]
-- =============================================================================

CREATE   procedure [dbo].[usp_company_address_geocode_insert_result]
    @geocode_request_id int,
    @response nvarchar(max) = null
as
    /*
        DATE        AUTHOR      REMARKS
        2020-04-02  jnavarra    Initial creation
        2020-04-29  jnavarra    Input response parameter, if available
                                Parse address components

        DESCRIPTION
        Parse and insert geocoder results
    */

    set nocount on;

    begin try

        declare
            @geocode_result_id int,
            @response_code int,
            @message varchar(100);



        -- Delete any previous results
        delete
        from dbo.geocode_result
        where geocode_request_id = @geocode_request_id



        -- Get the response
        if @response is null
            begin
                select @response = response
                from dbo.geocode_request
                where geocode_request_id = @geocode_request_id
            end


        -- Parse and insert
        if isjson(@response) = 1
            begin
                -- If expiration date exists on request, use that, else calculate
                insert into dbo.geocode_result (geocode_request_id, formatted_address, location, location_type, partial_match, google_place_id, plus_code, expiration_date, insert_date, last_modified_date)
                select gr.geocode_request_id, j.formatted_address, case when j.lat is null or j.lng is null then null else geography::Point(j.lat, j.lng, 4326) end, j.location_type, j.partial_match, j.place_id, j.plus_code, case when gr.response_expiration_date is not null then gr.response_expiration_date when gt.expiration_days is not null then dateadd(day, gt.expiration_days, getdate()) else null end, getdate(), getdate()
                from dbo.geocode_request gr
                    inner join dbo.geocode_type gt
                        on gt.geocode_type_id = gr.geocode_type_id
                    cross apply openjson(@response)
                        with (
                            formatted_address nvarchar(1000) '$.formatted_address',
                            lat varchar(20) '$.geometry.location.lat',
                            lng varchar(20) '$.geometry.location.lng',
                            location_type varchar(50) '$.geometry.location_type',
                            partial_match bit '$.partial_match',
                            place_id varchar(60) '$.place_id',
                            plus_code varchar(10) '$.plus_code.global_code'
                        ) j
                 where gr.geocode_request_id = @geocode_request_id

                 set @geocode_result_id = scope_identity()

                 exec dbo.usp_company_address_geocode_insert_address_components @geocode_result_id = @geocode_result_id, @response = @response
            end

    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'insert company address geocode result failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_geocode_select_next_batch]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_company_address_geocode_select_next_batch]
(
    @geocode_type_name varchar(50),
    @batch_size int = 100,
    @filter varchar(max) = null
)
as

/*	
    DATE        AUTHOR      REMARKS
    2020-03-11  jnavarra    Initial creation
    2020-04-20  jnavarra    Fix double-processing bug (reduce filter complexity to look only at response_clear_date)

    DESCRIPTION
    Select company addresses to be processed
*/

    set nocount on

    begin try

        declare
            @geocode_type_id int,
            @response_code int,
            @message varchar(100);

        select @geocode_type_id = geocode_type_id
        from dbo.geocode_type
        where geocode_type_name = @geocode_type_name

        ;with
            has_active_geocode_results as (
                select distinct cagr.company_address_id
                from dbo.company_address_geocode_request cagr
                    inner join dbo.geocode_request gr
                        on gr.geocode_request_id = cagr.geocode_request_id
                where gr.geocode_type_id = @geocode_type_id
                    and gr.response_cleared_date is null
            )
	        select top(@batch_size) c.company_name, ca.company_address_id, ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, co.description as country, co.iso as country_iso
            from dbo.company_address ca
                inner join dbo.lu_countries co
                    on co.country_id = ca.country_id
                inner join dbo.company c
                    on c.company_id = ca.company_id
                left join has_active_geocode_results a
                    on a.company_address_id = ca.company_address_id
            where ca.address_class_id = 1
                and ca.address_status_id = 1
                and a.company_address_id is null
            order by ca.company_address_id

    end try

    begin catch

        set @response_code = -200
        set @message = case
            when @message is null then 'select company address geocode batch failed'
            else @message
        end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName

    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_geocode_update_request]
-- =============================================================================

CREATE    procedure [dbo].[usp_company_address_geocode_update_request]
    @geocode_request_id int,
    @response nvarchar(max)
as
    /*
        DATE        AUTHOR      REMARKS
        2020-03-13  jnavarra    Initial creation
        2020-04-29  jnavarra    Pass response along to next proc
        
        DESCRIPTION
        Update geocode_request
    */

    set nocount on;

    begin try

        declare
            @response_code int,
            @message varchar(100);

        -- Update the request record
        update gr
        set gr.response = @response,
            gr.response_date = getdate(),
            gr.response_expiration_date = dateadd(day, gt.expiration_days, getdate()),
            gr.last_modified_date = getdate()
        from dbo.geocode_request gr
            inner join dbo.geocode_type gt
                on gt.geocode_type_id = gr.geocode_type_id
        where geocode_request_id = @geocode_request_id


        -- Parse and insert the results
        exec dbo.usp_company_address_geocode_insert_result @geocode_request_id = @geocode_request_id, @response = @response
        

    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'update company address geocode request failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_address_validation_select_next_batch]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_company_address_validation_select_next_batch]
(
    @address_validation_method varchar(50),
    @batch_size int = 100,
    @filter varchar(max) = null
)
as

/*	
    DATE        AUTHOR      REMARKS
    2019-10-24  jnavarra    Initial creation.

    DESCRIPTION
    Select company addresses to be processed
*/

    set nocount on

    begin try

        declare
            @address_validation_method_id int,
            @response_code int,
            @message varchar(100);

        select @address_validation_method_id = address_validation_method_id
        from dbo.address_validation_method
        where address_validation_method_name = @address_validation_method

	    select top(@batch_size) ca.company_address_id, ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, co.description as country, co.iso as country_iso
        from dbo.company_address ca
            inner join dbo.lu_countries co
                on co.country_id = ca.country_id
            inner join openjson(@filter) with (country_id int N'$.country_id') f
               on f.country_id = co.country_id
            left join dbo.company_address_validation cav
                on cav.company_address_id = ca.company_address_id
                    and cav.address_validation_method_id = @address_validation_method_id
                    and (cav.expiration_date is null or cav.expiration_date > getdate())
        where cav.company_address_validation_id is null
        order by ca.company_address_id

    end try

    begin catch

        set @response_code = -200
        set @message = case
            when @message is null then 'select company address validation batch failed'
            else @message
        end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName

    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_delete_company_name]
-- =============================================================================

CREATE     procedure [dbo].[usp_company_delete_company_name]
    @company_name_id int,
    @force bit = 0
as
    /*
        DATE        AUTHOR      REMARKS
        2020-05-26  jnavarra    Initial creation

        DESCRIPTION
        Delete a company name and all its derivatives. A "primary" company name cannot be deleted unless forced.
        Currently, operation limited to a specific company_name_id.
    */

    set nocount on

    begin try

        declare
            @derivation_id int,
            @company_name_type_id int,
            @company_name_match_logic_id int,
            @derived_from int,
            @derived_company_name nvarchar(255),
            @new_company_name_id int,
            @response_code int,
            @message varchar(100)

        select
            @company_name_id = company_name_id,
            @company_name_type_id = company_name_type_id,
            @derived_from = derived_from_company_name_id
        from dbo.company_name
        where company_name_id = @company_name_id



        -- Validate company_name_id
        if @company_name_id is null
            begin
                -- Derived name types cannot be manipulated directly, they should be auto-generated
                set @response_code = -104
                set @message = 'company_name_id not found'
                return
            end



        -- Validate company_name_match_logic
        if @derived_from is not null
            begin
                -- Derived name types cannot be manipulated directly, they should be auto-generated
                set @response_code = -102
                set @message = 'Only non-derived company name types allowed'
                return
            end

        if @company_name_type_id = 1 and (@force is null or @force <> 1)
            begin
                -- "Primary" company names cannot be deleted unless forced (this should be immediately followed by inserting a new one.
                set @response_code = -104
                set @message = 'Cannot delete a "primary" company_name without @force parameter'
                return
            end



        if @company_name_id is not null
            begin
                -- Delete the specified company name and its derivations

                declare @derivations table (company_name_id int, processed bit)

                -- Seed the loop
                insert into @derivations (company_name_id, processed)
                values (@company_name_id, 0)

                while 1=1
                    begin
                        select top(1) @company_name_id = company_name_id
                        from @derivations
                        where processed = 0
                        order by company_name_id

                        if @@rowcount = 0
                            begin
                                break   -- Nothing left
                            end

                        -- Find company names derived from the current selection
                        insert into @derivations (company_name_id, processed)
                        select company_name_id, 0
                        from dbo.company_name
                        where derived_from_company_name_id = @company_name_id

                        -- Mark current selection as processed
                        update @derivations
                        set processed = 1
                        where company_name_id = @company_name_id
                    end

                -- Delete all selected company names
                delete cn
                from dbo.company_name cn
                    inner join @derivations d
                    
    on d.company_name_id = cn.company_name_id
            end
    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'delete company name failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_insert_company_from_customer]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_insert_company_from_customer]

( 
	@customer_id int,
	@company_type_id tinyint = null,
	@email_domain_type_id tinyint = null,
	@salesforce_account_id varchar(18) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2021-04-05	esmart		Initial creation.

	DESCRIPTION
	Insert company from customer data. This bypasses company match logic and should be used only in certain use cases.
*/

AS

	declare @company_id int, 
			@company_name nvarchar(255), 
			@company_name_type_id tinyint, 
			@company_name_type varchar(50),
			@email_domain varchar(100),
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) company
	select @company_name_type_id = 1

	insert into company (company_name, company_type_id, company_name_clean, salesforce_account_id)
	select cc.company_name, 
		case when @company_type_id is not null then @company_type_id when @company_type_id is null and cc.company_type_id is not null then cc.company_type_id else 14 end as company_type_id, 
		dbo.fn_clean_company_name(company_name), @salesforce_account_id
	from customer_company cc
	where cc.customer_id = @customer_id
	
	select @company_id = scope_identity()

	-- 1.2) company_address
	insert into company_address (company_id, address_type_id, address_1, address_2, city, state, postal_code, country_id, address_class_id, address_status_id, source, insert_date, insert_by, modified_date, modified_by)
	select @company_id, address_type_id, address_1, address_2, city, state, postal_code, country_id, 1, address_status_id, 'ecommerce', insert_date, insert_by, modified_date, modified_by
	from customer_address a
	where a.customer_id = @customer_id and a.address_type_id = 1 and a.address_status_id = 1

	-- 1.3) customer_company
	update customer_company 
	set company_id = @company_id, modified_date = getdate(), modified_by = suser_sname()
	where customer_id = @customer_id

	-- 1.4) company_email_domain
		
		-- 1.4.1) @email_domain
		if @email_domain_type_id is null
			begin
			select @email_domain_type_id = 2
			end

		select @email_domain = e.email_domain
		from customer_email e
		where e.customer_id = @customer_id and e.email_status_id = 1

		-- 1.4.2) customer_email_domain
		if exists (select ed.customer_email_domain_id from customer_email_domain ed where ed.email_domain = @email_domain)
			begin
			update ed
			set ed.email_domain_type_id = @email_domain_type_id
			from customer_email_domain ed where ed.email_domain = @email_domain
			end
		else 
			begin
			insert into customer_email_domain(email_domain,email_domain_type_id)
			values(@email_domain,@email_domain_type_id)
			end
	
		-- 1.4.3) company_email_domain
		insert into company_email_domain (company_id, email_domain, email_domain_type_id, protected, customers)
		select @company_id, @email_domain, @email_domain_type_id, 0, 1

	-- 1.5) company_name
	select @company_name = c.company_name
	from company c
	where c.company_id = @company_id

	exec usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type_id = @company_name_type_id, @company_name_type = @company_name_type

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp
_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_insert_company_merge]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_insert_company_merge]


(
	@merge_company_json nvarchar(max),
	@insert_by varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2020-01-07	esmart		Initial creation.

	DESCRIPTION
	insert company_merge
*/

AS

set nocount on				

begin try

		declare	@company_merge_id int,
				@response_code int,
				@message varchar(100)

		declare @company_merge_company table (company_id int, merge_type varchar(20))

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) insert
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) company_merge
		insert into company_merge(insert_by,modified_by)
		values(@insert_by,@insert_by)
		
		select @company_merge_id = scope_identity()

		-- 1.2) company_merge_company
		insert into @company_merge_company (company_id,merge_type)
		select company_id, merge_type
		from openjson(@merge_company_json)
		with (company_id int '$.company_id',
			merge_type varchar(20) '$.merge_type')
		
		insert into company_merge_company (company_merge_id, merge_type, company_id, company_name, salesforce_account_id, oracle_customer_id)
		select @company_merge_id, cmc.merge_type, c.company_id, c.company_name, c.salesforce_account_id, c.oracle_customer_id
		from @company_merge_company cmc
		inner join company c
			on cmc.company_id = c.company_id


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_insert_company_name]
-- =============================================================================

CREATE   procedure [dbo].[usp_company_insert_company_name]
    @company_id int,
    @company_name nvarchar(255),
    @company_name_type_id int = null,
    @company_name_type varchar(50) = null
as
    /*
        DATE        AUTHOR      REMARKS
        2020-04-27  jnavarra    Initial creation
        2020-10-01  jnavarra    Update last_modified_date on change
        2021-03-10  jnavarra    Handle customer_company
		2021-01-29	esmart		CHECK WITH JEFF

        DESCRIPTION
        Insert a company name. Auto-detect if romanized or localized. Generate all derived types.
        Names that already exists as either "primary" or "secondary" will not be inserted.
        Inserting a new "primary" name will change the existing "primary" to be a "secondary" since there's only one "primary" allowed (either romanized or localized).
    */

    set nocount on

    begin try
    
        declare
            @existing_company_name nvarchar(255),
            @company_name_match_logic_id int,
            @derived_from int,
            @response_code int,
            @message varchar(100)



        -- Validate company_id
        -- Save the current company_name for use later
        select
            @company_id = company_id,
            @existing_company_name = company_name
        from dbo.company with (nolock)
        where company_id = @company_id

        if @company_id is null
            begin
                set @response_code = -100
                set @message = 'company_id not found'
                return
            end

        
        
        -- Validate company_name_type
        if @company_name_type_id is null and @company_name_type is null
            begin
                -- Default to "Secondary"
                set @company_name_type_id = 2
            end

        select top(1)
            @company_name_type_id = company_name_type_id
        from dbo.company_name_type
        where company_name_type_id = @company_name_type_id
            or company_name_type = @company_name_type
        order by company_name_type_id

        if @company_name_type_id is null
            begin
                set @response_code = -101
                set @message = 'company_name_type not found'
                return
            end



        -- Validate company_name_match_logic
        declare @is_romanized int = dbo.fn_is_romanized(@company_name)

        select
            @company_name_match_logic_id = company_name_match_logic_id,
            @derived_from = derived_from_company_name_match_logic_id
        from dbo.company_name_match_logic
        where company_name_type_id = @company_name_type_id
            and is_romanized = @is_romanized

        if @company_name_match_logic_id is null
            begin
                set @response_code = -103
                set @message = 'Matching logic not found'
                return
            end

        if @derived_from is not null
            begin
                -- Derived name types cannot be manipulated directly, they should be auto-generated
                set @response_code = -102
                set @message = 'Only non-derived company name types allowed'
                return
            end

        

        if @company_name_type_id = 1 and @company_name is not null   -- Primary
            begin
                print('Primary')
				-- The "Primary" name is special. When this is added or changed, the company_name field in the company table also needs to be updated.
                -- Only archive and make into secondary, it will be re-added later
                declare @company_name_id int = (select company_name_id from dbo.company_name where company_i
d = @company_id and company_name_type_id = @company_name_type_id)
               
				exec dbo.usp_company_delete_company_name @company_name_id = @company_name_id, @force = 1

                if @existing_company_name <> @company_name
                    begin
                        -- Update company
                        insert into dbo.company_audit (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, audit_date)
                        select company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, getdate()
                        from dbo.company with (nolock)
                        where company_id = @company_id

                        update dbo.company
                        set company_name = @company_name,
                            company_name_clean = dbo.fn_clean_company_name(@company_name),
                            last_modified_date = getdate()
                        where company_id = @company_id

                        -- Update customer_company
                        insert into dbo.customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id, audit_date)
                        select customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id, getdate()
                        from dbo.customer_company
                        where company_id = @company_id
                            and company_name <> @company_name

                        update dbo.customer_company
                        set company_name = @company_name,
                            modified_date = getdate(),
                            modified_by = system_user
                        where company_id = @company_id
                            and company_name <> @company_name

                        -- Move "Primary" name to "Secondary"
                        exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @existing_company_name, @company_name_type = 'Secondary'
                    end
            end
        else if @company_name is null or exists (select * from dbo.company_name with (nolock) where company_id = @company_id and company_name_type_id in (2) and company_name = @company_name)
            begin
				print('NULL or already exists. Exit doing nothing.')
				-- NULL or already exists. Exit doing nothing.
                return
            end



        declare @derivations table (derivation_id int not null, company_name_match_logic_id int, company_name_type_id int not null, is_romanized bit not null, derived_from_id int null, company_name nvarchar(255) not null, company_name_id int null, derived_from_company_name_id int null)

        -- Save the derived names
        -- We need to process them individually to properly establish the links to the company_name they were derived from.
        insert into @derivations (derivation_id, company_name_match_logic_id, company_name_type_id, is_romanized, derived_from_id, company_name, company_name_id, derived_from_company_name_id)
        select derivation_id, company_name_match_logic_id, company_name_type_id, is_romanized, derived_from_id, company_name, null, null
        from dbo.fn_derive_company_names(@company_name, @company_name_type_id)

        declare
            @derivation_id int,
            @derived_from_company_name_id int,
            @apex_company_name_id int,
            @new_company_name_id int,
            @process_date datetime = getdate(),
            @process_user varchar(50) = system_user

        while exists (select * from @derivations where company_name_id is null)
            begin
                -- Grab the lowest ordered name
                select top(1)
                    @derivation_id = derivation_id,
                  
  @company_name_match_logic_id = company_name_match_logic_id,
                    @company_name_type_id = company_name_type_id,
                    @is_romanized = is_romanized,
                    @company_name = company_name,
                    @derived_from = derived_from_id
                from @derivations
                where company_name_id is null
                order by derivation_id
 
                -- Get the ID that the name was derived from, this will be NULL for the top-level name
                select
                    @derived_from_company_name_id = company_name_id
                from @derivations
                where derivation_id = @derived_from

                -- Record the name into the company_name table
                insert into dbo.company_name (company_id, company_name_match_logic_id, company_name_type_id, is_romanized, derived_from_company_name_id, apex_company_name_id, company_name, insert_date, insert_by, modified_date, modified_by)
                values (@company_id, @company_name_match_logic_id, @company_name_type_id, @is_romanized, @derived_from_company_name_id, @apex_company_name_id, @company_name, @process_date, @process_user, @process_date, @process_user)

                set @new_company_name_id = scope_identity()

                if @apex_company_name_id is null
                    begin
                        -- This facilitates grouping of the company names, this only needs to be done once, after that we just reuse the variable throughout the rest of the loop

                        set @apex_company_name_id = @new_company_name_id

                        -- Because the ID is unknown the on the initial insert, we need to go back and update the apex ID
                        update dbo.company_name
                        set apex_company_name_id = @apex_company_name_id
                        where company_name_id = @new_company_name_id
                    end

                -- Update the derivation table to keep track of the actual company_name_id that was generated and the actual company_name_id it came from
                update @derivations
                set company_name_id = @new_company_name_id,
                    derived_from_company_name_id = @derived_from_company_name_id
                where derivation_id = @derivation_id
            end

    end try
    
    begin catch

        set @response_code = -200
        set @message = case
            when @message is null then 'insert company name failed'
            else @message
        end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_merge_company]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_merge_company]


(
    @company_merge_id int
)

/*
    DATE        AUTHOR      REMARKS
    2020-01-07  esmart      Initial creation.
    2020-04-16  jnavarra    Handle geocode data
    2020-06-16  jnavarra    Modify for new company_name

    DESCRIPTION
    merge ecommerce companies
*/

AS

set nocount on

begin try

        declare    @master_company_id int,
                @company_name nvarchar(255),
                @response_code int,
                @message varchar(100)


        declare @merge_company table (company_id int)

        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
        -- 1.1) @master_company_id
        select @master_company_id = mc.company_id, @company_name = c.company_name
        from company_merge_company mc
        inner join company c
            on mc.company_id = c.company_id
        where mc.company_merge_id = @company_merge_id and mc.merge_type = 'master'

        -- 1.2) @merge_company
        insert into @merge_company(company_id)
        select mc.company_id
        from company_merge_company mc
        where mc.company_merge_id = @company_merge_id and mc.merge_type = 'merge'

        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 2.) merge
        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
        --2.1) customer_company

            insert into customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id)
            select customer_company_id, customer_id, cc.company_name, insert_date, insert_by, modified_date, modified_by, cc.company_id, customer_type_id
            from customer_company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

            update cc 
            set cc.company_id = @master_company_id, cc.company_name = @company_name, cc.modified_date = getdate(), cc.modified_by = 'company_merge'
            from customer_company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        -- 2.2) cybs_subscription_customer

            update cc
            set cc.company_id = @master_company_id
            from cybs_subscription_customer cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        -- 2.3) order_company

            insert into order_company_audit (order_company_id, order_header_id, company_id, order_company_type_id, insert_date, customer_id)
            select order_company_id, order_header_id, cc.company_id, order_company_type_id, insert_date, customer_id
            from order_company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

            update cc
            set cc.company_id = @master_company_id
            from order_company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        --2.4) partner_billing

            update cc
            set cc.company_id = @master_company_id
            from partner_billing cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        -- 2.5) partner_company

            update partner_company
            set company_id = @master_company_id 
            from partner_company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        -- 2.5) company_email_domain

            delete ed
            from company_email_domain ed
            inner join @merge_company c
                on c.company_id = ed.company_id

        -- 2.6) company_address

            delete cagr
            from dbo.company_address ca
                inner join dbo.company_address_geocode_request cagr
                    on cagr.company_address_id = ca.company_address_id
                inner join @merge_company mc
                    on mc.company_id = ca.company_id

            delete av 
            from company_address a
            inner join company_address_validation av
                on a.company_address_id = av.company_address_id
            inner join @merge_company c
                on c.company_id = a.company_id

            delete a 
            from company_address a
            inner join @merge_company c
                on c.company_id = a.company_id

        -- 2.7) company_configuration_company

            delete ccc
            from company_configuration_company ccc
            inner join @merge_company c
                on c.company_id = ccc.company_id

        -- 2.8) sky_account_customer

            update ac
            set ac.company_id = @master_company_id, ac.modified_date = getdate(), ac.modified_by = 'company_merge'
            from sky_account_customer ac
            inner join @merge_company c
                on c.company_id = ac.company_id

        -- 2.9) company_Name

            delete cn
            from dbo.company_name cn
            inner join @merge_company c
                on c.company_id = cn.company_id

        -- 2.10) company

            insert into company_audit (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id)
            select cc.company_id, company_name, salesforce_account_id, last_modified_date, company_type_id
            from company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

            delete cc
            from company cc
            inner join @merge_company c
                on c.company_id = cc.company_id

        
        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 3) update company_merge
        -------------------------------------------------------------------------------------------------------------------------------------------------------------------

        update m
        set m.ecommerce_merge_status_id = 2, m.modified_date = getdate(), m.modified_by = 'company_merge'
        from company_merge m
        where m.company_merge_id = @company_merge_id

end try

begin catch
    
    set @response_code = -200
    set @message = case when @message is null then 'insert failed'
                        else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_select_company]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_company_select_company]
(
    @company_id INT = NULL,
    @company_name NVARCHAR(255) = NULL,
    @email_domain VARCHAR(100) = NULL,
    @partner_key VARCHAR(36) = NULL
)

/*	
	DATE			AUTHOR		REMARKS
	2015-01-25		esmart		Initial creation.
	2015-08-24		esmart		Add search of customer_company
	2016-01-08		esmart		Add verification 
	2016-12-01		esmart		Add support for non-partner submit
	2024-09-16      psatish		ecom-5670 Switched table variable to temp table and added section 1.5 to improve the performance
	DESCRIPTION
	select company
	DEPENDENCY
	usp_partner_select_partner_customer_verify
	
	This procedure is being called on the Invoice Detail page at CSI.(https://csi.webroot.com/en_US/orders/invoice/<<invoiceno>>)
*/


AS
SET NOCOUNT ON

DECLARE @domain_emails INT,
        @response_code INT,
        @message VARCHAR(100)


BEGIN TRY

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    DROP TABLE IF EXISTS #company
    CREATE TABLE #company
    (
        temp_id INT IDENTITY(1, 1) PRIMARY KEY,
        company_id INT,
        company_name NVARCHAR(255),
        company_type_id TINYINT,
        company_type_name VARCHAR(50),
        salesforce_account_id VARCHAR(20),
        last_modified_date DATETIME,
        vendor_customer_code VARCHAR(100),
        customer_id INT,
        first_name NVARCHAR(225),
        last_name NVARCHAR(225),
        customer_email VARCHAR(100),
        verified TINYINT
    )
    CREATE NONCLUSTERED INDEX indx_company_temp_table
    ON #company (
                    company_id,
                    customer_id,
                    verified
                )

    DECLARE @license TABLE
    (
        customer_id INT PRIMARY KEY,
        licenses INT,
        last_license_insert_date DATETIME
    )

    DECLARE @customer_order TABLE
    (
        customer_id INT PRIMARY KEY,
        customer_orders INT,
        last_customer_order_insert_date DATETIME
    )

    DECLARE @order_company TABLE
    (
        company_id INT PRIMARY KEY,
        company_orders INT,
        last_company_order_insert_date DATETIME
    )

    -- 1.1) set values

    SELECT @email_domain = SUBSTRING(@email_domain, CHARINDEX('@', @email_domain) + 1, LEN(@email_domain))

    -- 1.2) search on @company_name
    IF @company_name <> ''
       AND @company_name IS NOT NULL
    BEGIN

        -- 1.2.1) company.company_name
        SELECT @company_name = @company_name + '%'

        INSERT INTO #company
        (
            company_id,
            company_name,
            company_type_id,
            company_type_name,
            salesforce_account_id,
            last_modified_date,
            vendor_customer_code,
            customer_id,
            first_name,
            last_name 
        )
        SELECT DISTINCT
               c.company_id,
               c.company_name,
               t.company_type_id,
               t.company_type_name,
               c.salesforce_account_id,
               c.last_modified_date,
               v.vendor_customer_code,
               cu.customer_id,
               cu.first_name,
               cu.last_name 
        FROM dbo.company c WITH (NOLOCK)
            LEFT JOIN dbo.customer_company cc WITH (NOLOCK)
                ON c.company_id = cc.company_id
            L
EFT JOIN dbo.vendor_customer v WITH (NOLOCK)
                ON cc.customer_id = v.customer_id
            LEFT JOIN dbo.customer cu WITH (NOLOCK)
                ON cc.customer_id = cu.customer_id
            LEFT JOIN dbo.company_type t WITH (NOLOCK)
                ON c.company_type_id = t.company_type_id
        WHERE c.company_name LIKE @company_name



        -- 1.2.2) customer_company.company_name
        INSERT INTO #company
        (
            company_id,
            company_name,
            company_type_id,
            company_type_name,
            last_modified_date,
            vendor_customer_code,
            customer_id,
            first_name,
            last_name 
        )
        SELECT DISTINCT
               cc.company_id,
               cc.company_name,
               company_type_id = 0,
               company_type_name = 'Online Customer',
               cc.modified_date,
               v.vendor_customer_code,
               cu.customer_id,
               cu.first_name,
               cu.last_name --,
        --e.customer_email
        FROM dbo.customer_company cc WITH (NOLOCK)
            LEFT JOIN dbo.vendor_customer v WITH (NOLOCK)
                ON cc.customer_id = v.customer_id
            LEFT JOIN dbo.customer cu WITH (NOLOCK)
                ON cc.customer_id = cu.customer_id
         WHERE cc.company_name LIKE @company_name
              AND cc.company_id IS NULL


    END

    -- 1.3) search on @company_id
    IF @company_id IS NOT NULL
    BEGIN
        INSERT INTO #company
        (
            company_id,
            company_name,
            company_type_id,
            company_type_name,
            salesforce_account_id,
            last_modified_date,
            vendor_customer_code,
            customer_id,
            first_name,
            last_name 
        )
        SELECT DISTINCT
               c.company_id,
               c.company_name,
               t.company_type_id,
               t.company_type_name,
               c.salesforce_account_id,
               c.last_modified_date,
               v.vendor_customer_code,
               cu.customer_id,
               cu.first_name,
               cu.last_name 
        FROM dbo.company c WITH (NOLOCK)
            LEFT JOIN dbo.customer_company cc WITH (NOLOCK)
                ON c.company_id = cc.company_id
            LEFT JOIN dbo.vendor_customer v WITH (NOLOCK)
                ON cc.customer_id = v.customer_id
            LEFT JOIN dbo.customer cu WITH (NOLOCK)
                ON cc.customer_id = cu.customer_id
            LEFT JOIN dbo.company_type t WITH (NOLOCK)
                ON c.company_type_id = t.company_type_id
        WHERE c.company_id = @company_id
    END

    UPDATE cm
    SET cm.customer_email = ce.customer_email
    FROM #company cm
        INNER JOIN dbo.customer_email ce
            ON ce.customer_id = cm.customer_id
    WHERE ce.email_status_id = 1

    -- 1.4) search on email_domain	
    IF @email_domain IS NOT NULL
       AND @email_domain <> ''
    BEGIN
        SELECT @domain_emails = COUNT(customer_id)
        FROM dbo.customer_email
        WHERE email_domain = @email_domain
              AND email_status_id = 1


        -- 1.4.1) restrict down search for common domains
        IF @domain_emails <= 20
        BEGIN
            INSERT INTO #company
            (
                company_id,
                company_name,
                company_type_id,
                company_type_name,
                salesforce_account_id,
                last_modified_date,
                vendor_customer_code,
                customer_id,
                first_name,
                last_name,
                customer_email
            )
            SELECT DISTINCT
                   c.company_id,
                   c.company_name,
                   t.company_type_id,
                   t
.company_type_name,
                   c.salesforce_account_id,
                   c.last_modified_date,
                   v.vendor_customer_code,
                   cu.customer_id,
                   cu.first_name,
                   cu.last_name,
                   e.customer_email
            FROM dbo.customer_email e WITH (NOLOCK)
                INNER JOIN dbo.customer cu WITH (NOLOCK)
                    ON e.customer_id = cu.customer_id
                LEFT JOIN dbo.vendor_customer v WITH (NOLOCK)
                    ON e.customer_id = v.customer_id
                LEFT JOIN dbo.customer_company cc WITH (NOLOCK)
                    ON e.customer_id = cc.customer_id
                LEFT JOIN dbo.company c WITH (NOLOCK)
                    ON cc.company_id = c.company_id
                LEFT JOIN dbo.company_type t WITH (NOLOCK)
                    ON c.company_type_id = t.company_type_id
            WHERE e.email_domain = @email_domain
                  AND e.email_status_id = 1
        END

    END

    -- 1.4.2) verify customers
    IF @partner_key IS NOT NULL
    BEGIN
        DECLARE @temp_id INT,
                @total_ids INT,
                @customer_id INT

        DECLARE @verified TABLE
        (
            verified TINYINT
        )

        SELECT @temp_id = 1,
               @total_ids = COUNT(*)
        FROM #company

        WHILE @total_ids >= @temp_id
        BEGIN
            SELECT @customer_id = customer_id
            FROM #company
            WHERE temp_id = @temp_id

            INSERT INTO @verified
            (
                verified
            )
            EXEC usp_partner_select_partner_customer_verify @partner_key, @customer_id

            UPDATE #company
            SET verified =
                (
                    SELECT verified FROM @verified
                )
            WHERE temp_id = @temp_id

            DELETE FROM @verified
            SELECT @temp_id = @temp_id + 1
        END
    END

    --1.5 Begins
    INSERT INTO @license
    (
        customer_id,
        licenses,
        last_license_insert_date
    )
    SELECT lc.customer_id,
           COUNT(DISTINCT lc.license_id) AS licenses,
           MAX(lc.insert_date) AS last_license_insert_date
    FROM #company c
        INNER JOIN dbo.license lc
            ON lc.customer_id = c.customer_id
    GROUP BY lc.customer_id


    INSERT INTO @customer_order
    (
        customer_id,
        customer_orders,
        last_customer_order_insert_date
    )
    SELECT DISTINCT
           co.customer_id,
           co.customer_orders,
           co.last_customer_order_insert_date
    FROM #company cm
        INNER JOIN dbo.[vw_customer_orders_count] co
            ON cm.customer_id = co.customer_id


    INSERT INTO @order_company
    (
        company_id,
        company_orders,
        last_company_order_insert_date
    )
    SELECT DISTINCT
           oc.company_id,
           oc.company_orders,
           oc.last_company_order_insert_date
    FROM #company cm
        INNER JOIN dbo.[vw_company_orders_count] oc
            ON cm.company_id = oc.company_id

    --Ends




    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) return results
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT c.customer_id,
           c.company_id,
           c.company_name,
           c.company_type_id,
           c.company_type_name,
           c.salesforce_account_id,
           c.last_modified_date,
           c.vendor_customer_code,
           c.first_name,
           c.last_name,
           c.c
ustomer_email,
           ISNULL(lt.licenses, 0) AS licenses,
           lt.last_license_insert_date,
           ISNULL(co.customer_orders, 0) AS customer_orders,
           co.last_customer_order_insert_date,
           ISNULL(oc.company_orders, 0) AS company_orders,
           oc.last_company_order_insert_date
    FROM #company c
        LEFT JOIN @license lt
            ON lt.customer_id = c.customer_id
        LEFT JOIN @customer_order co
            ON co.customer_id = c.customer_id
        LEFT JOIN @order_company oc
            ON oc.company_id = c.company_id
    WHERE c.verified = 1
          OR c.verified IS NULL
    ORDER BY c.customer_id DESC


END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_select_company_address]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_select_company_address]


(
	@company_id int,
	@address_class_id tinyint = null,
	@address_status_id tinyint = null

)

/*	
	DATE		AUTHOR		REMARKS
	2018-10-03	esmart		Initial creation.

	DESCRIPTION
	select company_type
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------



		select ca.company_address_id, ca.company_id, ca.address_type_id, t.address_type_description, ca.address_1, ca.address_2,
			ca.city, ca.state, s.state_iso3, state_description = s.description, 
			ca.postal_code, ca.country_id, country_description = lc.description, 
			ca.address_status_id, st.address_status,
			ca.address_class_id, ac.address_class, 
			ca.insert_date
		from company_address ca
		inner join address_type t 
			on ca.address_type_id = t.address_type_id
		inner join address_status st
			on ca.address_status_id = st.address_status_id
		inner join lu_countries lc
			on ca.country_id = lc.country_id
		inner join address_class ac
			on ca.address_class_id = ac.address_class_id
		left join lu_states s
			on ca.state = s.state_id and s.iso2 = lc.iso
		where ca.company_id = @company_id and 
			ca.address_status_id = case when @address_status_id is null then ca.address_status_id else @address_status_id end and 
			ca.address_class_id = case when @address_class_id is null then ca.address_class_id else @address_class_id end 

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
