-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_select_company_detail]


(
    @company_id INT = NULL,
	@salesforce_account_id VARCHAR(18) = NULL,
	@sap_account_number INT = NULL
)

/*
    DATE        AUTHOR      REMARKS
    2019-10-31  esmart      Initial creation.
    2020-06-10  jnavarra    Modify for new company_name
	2020-10-21	esmart		Add @salesfore_account_id and @sap_account as optional inputs
    2021-11-22  kconvery    Add inline case statement to check for null value and replace with 14 (business) to solve issue in SMCI-5756
	2023-01-19  msoni       Add secodary company name as per #ECOM_348 requirements (section 1.3 - return result )
    
	DESCRIPTION
    select company_detail
*/

AS

SET NOCOUNT ON

BEGIN TRY

        DECLARE @response_code INT,
                @message VARCHAR(100),
                @company_type_id INT

        -------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) use @salesfore_account_id to lookup company_id
		IF @company_id IS NULL AND @salesforce_account_id IS NOT NULL
			BEGIN
			SELECT @company_id = c.company_id
			FROM company c
			WHERE c.salesforce_account_id = @salesforce_account_id
			END

		-- 1.2) use @sap_account_number to lookup company_id
		IF @company_id IS NULL AND @sap_account_number IS NOT NULL
			BEGIN
			SELECT @company_id = a.company_id
			FROM sap_account a
			WHERE a.sap_account_number = @sap_account_number
			END

		-- 1.2.1) selecting for null value, replacing with 14:
		SET @company_type_id = (SELECT ISNULL(company_type_id, 14) FROM company WHERE company_id = @company_id)

	
     -- 1.3) return result ----Add secodary company name as per #ECOM_348 requirements

		 SELECT c.company_id, c.company_name, t.company_type_id, t.company_type_name, dbo.fn_get_company_name_clean(c.company_id) AS company_name_clean,c.salesforce_account_id,
		  c.oracle_customer_id, c.last_modified_date,a.sap_account_number, a.sap_account_name,a.sap_partner_function_json,
		  cnt.company_name_type, cnt.company_name_type_id ,cn.company_name AS company_display_name  ------
		 FROM dbo.company c
          INNER JOIN dbo.company_type t 
           ON @company_type_id = t.company_type_id 
		  LEFT JOIN dbo.sap_account a
		   ON a.company_id = c.company_id  
          LEFT JOIN dbo.company_name cn
	       ON c.company_id = cn.company_id
		  LEFT JOIN dbo.company_name_type cnt 
		   ON cnt.company_name_type_id =cn.company_name_type_id 
            WHERE c.company_id = @company_id
		    AND cnt.company_name_type_id IN (1,2)

end try

begin catch
    
    set @response_code = -200
    set @message = case when @message is null then 'select failed'
                        else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
