-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_select_customers]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_company_select_customers]

(
	@company_id int = null,
	@company_name nvarchar(255) = null
	
)

/*	
	DATE		AUTHOR		REMARKS
	2015-06-15	esmart		Initial creation.

	DESCRIPTION
	Select customers for company
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @company_id is not null
		begin
			select c.company_id, c.company_name, c.company_type_id, c.salesforce_account_id, t.company_type_name, cu.customer_id, v.vendor_customer_code, cu.salesforce_contact_id, cu.first_name, cu.last_name, cu.title, e.customer_email
			from company c
			inner join customer_company cc
				on c.company_id = cc.company_id
			inner join customer cu
				on cc.customer_id = cu.customer_id
			inner join customer_email e
				on cu.customer_id = e.customer_id and e.email_status_id = 1
			left join vendor_customer v
				on cc.customer_id = v.customer_id
			left join company_type t
				on c.company_type_id = t.company_type_id
			where c.company_id = @company_id
		end
		
	if @company_name is not null and @company_id is null
		begin
			select c.company_id, c.company_name, company_type_id=0, salesforce_account_id = null, company_type_name = 'Online Customer', cu.customer_id, v.vendor_customer_code, cu.salesforce_contact_id, cu.first_name, cu.last_name, cu.title, e.customer_email
			from customer_company c
			inner join customer cu
				on c.customer_id = cu.customer_id
			inner join customer_email e
				on cu.customer_id = e.customer_id and e.email_status_id = 1
			left join vendor_customer v
				on c.customer_id = v.customer_id
			where c.company_name = @company_name
		end
	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
