-- =============================================================================

CREATE PROCEDURE [dbo].[usp_company_select_licenses]

(
	@company_id int = null,
	@company_name nvarchar(255) = null
	
)

/*	
	DATE		AUTHOR		REMARKS
	2015-09-10	esmart		Initial creation.

	DESCRIPTION
	Select orders for company
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @company_id is not null
		begin
			select distinct l.license_id, 
					l.keycode, 
					l.customer_id, 
					p.product_line_id, p.product_line_description, p.product_line_prefix, 
					s.license_status_id, 
					s.license_status_description,
					t.license_type_id, 
					t.license_type_description,
					l.license_distribution_method_id, 
					l.license_keycode_type_id, 
					c.license_category_id,
					c.license_category_name,
					lc.capability_activation_days,
					lc.capability_activation_date,
					lc.capability_expiration_date,
					l.max_daily_activations, 
					l.max_child_licenses, 
					l.license_expiration_date, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by
			from order_company oc
			inner join order_header oh
				on oh.order_header_id = oc.order_header_id
			inner join order_item i
				on i.order_header_id = oh.order_header_id
			inner join order_item_license il
				on il.order_item_id = i.order_item_id
			inner join license l
				on l.license_id = il.license_id
			inner join product_line p
				on l.product_line_id = p.product_line_id
			left join license_category_license cl
				on l.license_id = cl.license_id
			left join license_category c
				on cl.license_category_id = c.license_category_id
			left join license_capability lc
				on l.license_id = lc.license_id and lc.capability_id = c.base_capability_id
			inner join license_status s
				on l.license_status_id = s.license_status_id
			inner join license_type t
				on l.license_type_id = t.license_type_id
			where oc.company_id = @company_id
		end

	if @company_name is not null and @company_id is null
		begin
			select distinct l.license_id, 
					l.keycode, 
					l.customer_id, 
					p.product_line_id, p.product_line_description, p.product_line_prefix, 
					s.license_status_id, 
					s.license_status_description,
					t.license_type_id, 
					t.license_type_description,
					l.license_distribution_method_id, 
					l.license_keycode_type_id, 
					c.license_category_id,
					c.license_category_name,
					lc.capability_activation_days,
					lc.capability_activation_date,
					lc.capability_expiration_date,
					l.max_daily_activations, 
					l.max_child_licenses, 
					l.license_expiration_date, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by
			from customer_company cc
			inner join customer_order co
				on co.customer_id = cc.customer_id
			inner join order_header oh
				on oh.order_header_id = co.order_header_id
			inner join order_item i
				on i.order_header_id = oh.order_header_id
			inner join order_item_license il
				on il.order_item_id = i.order_item_id
			inner join license l
				on l.license_id = il.license_id
			inner join product_line p
				on l.product_line_id = p.product_line_id
			left join license_category_license cl
				on l.license_id = cl.license_id
			left join license_category c
				on cl.license_category_id = c.license_category_id
			left join license_capability lc
				on l.license_id = lc.license_id and lc.capability_id = 
c.base_capability_id
			inner join license_status s
				on l.license_status_id = s.license_status_id
			inner join license_type t
				on l.license_type_id = t.license_type_id
			where cc.company_name = @company_name
		end
	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
