)

/*	
	DATE		AUTHOR		REMARKS
	2015-09-10	esmart		Initial creation.

	DESCRIPTION
	Select orders for company
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @company_id is not null
		begin
			select distinct v.vendor_order_code, oh.order_header_id, oo.salesforce_opportunity_id, oh.total_amount, oh.sub_total_amount, oh.tax_total, cu.currency_id, c.currency_code, c.symbol_html, c.symbol_utf8, c.symbol_text, oh.vendor_order_date, oh.locale, oh.site_id, oh.site_url, oh.order_status_id, oh.insert_date
