			from customer_company cc
			inner join customer_order co
				on co.customer_id = cc.customer_id
			inner join order_header oh
				on oh.order_header_id = co.order_header_id
			inner join vendor_order v
				on oh.vendor_order_id = v.vendor_order_id
			left join order_currency cu
				on oh.order_header_id = cu.order_header_id
			left join currency c
				on c.currency_id = cu.currency_id
			left join order_opportunity oo
				on co.order_header_id = oo.order_header_id
			where cc.company_name = @company_name
		end
	
	end try


	begin catch

