-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_update_company_configuration]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_update_company_configuration]

(
	@company_id int,
	@company_configuration_json nvarchar(max),
	@insert_by varchar(50) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-08-01	esmart		Initial creation
	2020-03-31	esmart		Validation configuration_value

	DESCRIPTION
	update company_configuration
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100),
				@modified_date datetime

	


		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) parameters
		if @insert_by is null 
			begin
			select @insert_by = suser_name()
			end
		
		select @modified_date = getdate()

		-- 1.1) parse json
		declare @configurations table (configuration_name varchar(50), configuration_value nvarchar(max))

		insert into @configurations (configuration_name, configuration_value)
		select convert(varchar(50),j.[Key]) as configuration_name, convert(nvarchar(max),j.Value) as configuration_value 
		from openjson(@company_configuration_json) j

		-- 1.2) validate configuration_value
		if not exists (select c.configuration_value
					from @configurations c
					inner join company_configuration cc
						on c.configuration_name = cc.configuration_name
					inner join company_configuration_value cv
						on cc.company_configuration_id = cv.company_configuration_id and c.configuration_value = cv.configuration_value)
			begin
			raiserror ( 'Invalid configuration value',1,1)
			return
			end

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2) insert/update
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 2.1) insert new
		insert into company_configuration_company (company_id, company_configuration_id, configuration_value,insert_by,insert_date,modified_by,modified_date)
		select @company_id, cc.company_configuration_id, c.configuration_value,@insert_by,@modified_date,@insert_by,@modified_date
		from @configurations c
		inner join company_configuration cc
			on c.configuration_name = cc.configuration_name
		left join company_configuration_company ccc
			on cc.company_configuration_id = ccc.company_configuration_id and ccc.company_id = @company_id
		where ccc.company_configuration_company_id is null

		-- 2.2) update existing
		update ccc
		set ccc.configuration_value = c.configuration_value, ccc.modified_by = @insert_by, ccc.modified_date = @modified_date
		from @configurations c
		inner join company_configuration cc
			on c.configuration_name = cc.configuration_name
		inner join company_configuration_company ccc
			on cc.company_configuration_id = ccc.company_configuration_id and ccc.company_id = @company_id
		where ccc.configuration_value <> c.configuration_value

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3) oracle update
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @oracle_update_id int, @oracle_template_id tinyint, @oracle_update_type_id tinyint, @oracle_update_json nvarchar(max)

		inse
rt into oracle_update (oracle_template_id, oracle_update_type_id)
		select ut.oracle_template_id, ut.oracle_update_type_id
		from company_configuration_company ccc
		inner join company_configuration cc
			on ccc.company_configuration_id = cc.company_configuration_id
		inner join oracle_template t
			on cc.oracle_template_name = t.oracle_template_name
		inner join oracle_template_update_type ut
			on t.oracle_template_id = ut.oracle_template_id
		where ccc.company_id = @company_id and ccc.modified_date = @modified_date and cc.oracle_template_name is not null

		select @oracle_update_id = scope_identity()

		if @oracle_update_id is not null
			begin
				select @oracle_update_json = (select c.company_id from company c where c.company_id = @company_id for json path, without_array_wrapper)

				insert into oracle_update_json (oracle_update_id, oracle_update_json)
				values(@oracle_update_id,@oracle_update_json)
			end

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_update_company_merge]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_company_update_company_merge]


(
