-- =============================================================================
-- PROCEDURE: [dbo].[usp_company_update_company_name]
-- =============================================================================

CREATE     procedure [dbo].[usp_company_update_company_name]
    @new_company_name nvarchar(255),
    @company_name_id int = null,
    @company_id int = null
as
    /*
        DATE        AUTHOR      REMARKS
        2020-04-27  jnavarra    Initial creation
        2020-10-01  jnavarra    Update last_modified_date on change
        2021-03-10  jnavarra    Handle customer_company

        DESCRIPTION
        Update a company name variant. This is just a helper proc that deletes the company name, then reinserts using the existing procs.
        Without a company_name_id specified, assume the "primary" company name based on company_id.
    */

    set nocount on

    begin try

        declare
            @existing_company_name nvarchar(255),
            @derived_from int,
            @company_name_type_id int,
            @response_code int,
            @message varchar(100)



        -- Validate company_id
        -- Save the current company_name for use later
        select
            @company_id = company_id,
            @existing_company_name = company_name
        from dbo.company
        where company_id = @company_id


        select
            @company_id = c.company_id,
            @existing_company_name = c.company_name,
            @company_name_type_id = cn.company_name_type_id,
            @derived_from = cn.derived_from_company_name_id
        from dbo.company_name cn
            inner join dbo.company c
                on c.company_id = cn.company_id
        where (@company_name_id is not null and cn.company_name_id = @company_name_id)
            or (@company_name_id is null and cn.company_id = @company_id and cn.company_name_type_id = 1)



        if @company_id is null
            begin
                set @response_code = -100
                set @message = 'company_id not found'
                return
            end

        if @company_name_type_id is null
            begin
                set @response_code = -101
                set @message = 'Company name type not found'
                return
            end


        -- Only non-derived name types can be manipulated directly, they should be auto-generated
        if @derived_from is not null
            begin
                set @response_code = -100
                set @message = 'Only non-derived company name types allowed'
                return
            end



        if @company_name_type_id = 1    -- Primary
            begin
                -- Update company and delete related company_name records.
                -- This will prevent usp_company_insert_company_name from moving the existing "primary" to become a "secondary"
                if @existing_company_name <> @new_company_name
                    begin
                        -- Update company
                        insert into dbo.company_audit (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, audit_date)
                        select company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, getdate()
                        from dbo.company
                        where company_id = @company_id

                        update dbo.company
                        set company_name = @new_company_name,
                            company_name_clean = dbo.fn_clean_company_name(@new_company_name),
                            last_modified_date = getdate()
                        where company_id = @company_id

                        -- Update customer_company
                        insert into dbo.customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date,
 modified_by, company_id, customer_type_id, audit_date)
                        select customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id, getdate()
                        from dbo.customer_company
                        where company_id = @company_id
                            and company_name <> @new_company_name

                        update dbo.customer_company
                        set company_name = @new_company_name,
                            modified_date = getdate(),
                            modified_by = system_user
                        where company_id = @company_id
                            and company_name <> @new_company_name
                    end
            end

        exec dbo.usp_company_delete_company_name @company_name_id = @company_name_id, @force = 1
        exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name_type_id = @company_name_type_id, @company_name = @new_company_name
    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'update company name failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_contract_update_details]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_contract_update_details]
(
    @contract_number NVARCHAR(50), -- sap_order_number
    @new_start_date DATE,
    @new_end_date DATE,
    @update_sap_queue BIT = NULL,
    @contract_status BIT,
    @modified_by VARCHAR(MAX),
    @response_code INT OUTPUT,
    @message VARCHAR(100) OUTPUT
)
/*
DATE            AUTHOR          REMARKS
2025-12-10      apoorvat       US-5090116 Initial creation.

DESCRIPTION
This procedure updates contract details (start date, end date and contract status)
based on sap_order_number. It performs all required audit logging
for order_item, sap_order and sap_order_item. It also inserts into SFDC opportunity update.

DEPENDENCY
This procedure will be invoked by the "edit contract" tab in CSI under contracts.
*/

AS
SET NOCOUNT ON;

BEGIN TRY

    DECLARE @current_date DATETIME = GETDATE();
    DECLARE @order_header_id INT;
    DECLARE @sap_order_id INT;
	DECLARE @sap_order_status_id INT;


    -- fetch sap_order_id and order_header_id
    SELECT @sap_order_id = sap_order_id,
           @order_header_id = order_header_id
    FROM dbo.sap_order
    WHERE sap_order_number = @contract_number;
    IF (@sap_order_id IS NULL)
    BEGIN
        SET @response_code = 50001;
        SET @message = 'Invalid Contract Number. No matching SAP Order found.';
        RAISERROR(@message, 11, 0);
        RETURN;
    END;
	
    -- sap_order
    IF (@contract_status IS NOT NULL)
    BEGIN


		SET @sap_order_status_id =
            CASE
                WHEN @contract_status = 1 THEN 1   -- Active
                WHEN @contract_status = 0 THEN 2   -- Terminated
            END;
			

        -- audit sap_order
        INSERT INTO dbo.sap_order_audit
        (
            sap_order_id,
            sap_order_number,
            order_header_id,
            sap_order_status_id,
            insert_date,
            modified_date,
            delivery_document_number,
            delivery_type,
            insert_by,
            modified_by,
            audit_by,
            audit_date
        )
        SELECT so.sap_order_id,
               so.sap_order_number,
               so.order_header_id,
               so.sap_order_status_id,
               so.insert_date,
               so.modified_date,
               so.delivery_document_number,
               so.delivery_type,
               so.insert_by,
               so.modified_by,
               @modified_by,
               @current_date
        FROM dbo.sap_order so
        WHERE so.sap_order_id = @sap_order_id;

        -- update contract status
        UPDATE dbo.sap_order
        SET sap_order_status_id = @sap_order_status_id,
            modified_date = @current_date,
            modified_by = @modified_by
        WHERE sap_order_id = @sap_order_id;
    END;
	
    --order_item and sap_order_item
    IF (@new_start_date IS NOT NULL AND @new_end_date IS NOT NULL)
    BEGIN
        -- audit order_item
        INSERT INTO dbo.order_item_audit
        (
            order_item_id,
            order_header_id,
            line_item,
            product_id,
            quantity,
            list_price,
            unit_price,
            tax,
            order_item_offer_id,
            order_item_offer_amount,
            item_total,
            tax_exempt,
            effective_date,
            order_item_status_id,
            insert_date,
            insert_by,
            modified_date,
            modified_by,
            capability_expiration_date,
            item_bundle_id,
            order_item_update_type_id,
            audit_date,
            sap_material_number
        )
        SELECT oi.order_item_id,
               oi.order_header_id,
               oi.line_item,
               oi.product_id,
               oi.quantity,
               oi.list_price,
               oi.unit_price,
               oi.tax,
               oi.order_item_offer_id,
               oi.order_item_offer_amount,
               oi.item_total,
               oi.tax_exempt,
               oi.effective_date,
               oi.order_item_status_id,
               oi.insert_date,
               oi.insert_by,
               oi.modified_date,
               oi.modified_by,
               oi.capability_expiration_date,
               oi.item_bundle_id,
               oi.order_item_update_type_id,
               @current_date,
               oi.sap_material_number
        FROM dbo.order_item oi
        WHERE oi.order_header_id = @order_header_id;

        -- audit sap_order_item
        INSERT INTO dbo.sap_order_item_audit
        (
            sap_order_item_id,
            sap_order_id,
            sap_order_status_id,
            sap_item_number,
            order_item_id,
            usage_item,
            start_date,
            end_date,
            insert_date,
            insert_by,
            modified_date,
            modified_by,
            delivery_item_number,
            po_line_number,
            audit_date,
            audit_by
        )
        SELECT soi.sap_order_item_id,
               soi.sap_order_id,
               soi.sap_order_status_id,
               soi.sap_item_number,
               soi.order_item_id,
               soi.usage_item,
               soi.start_date,
               soi.end_date,
               soi.insert_date,
               soi.insert_by,
               soi.modified_date,
               soi.modified_by,
               soi.delivery_item_number,
               soi.po_line_number,
               @current_date,
               @modified_by
        FROM dbo.sap_order_item soi
        WHERE soi.sap_order_id = @sap_order_id;

        UPDATE oi
        SET effective_date = @new_start_date,
           capability_expiration_date = @new_end_date,
           modified_date = @current_date,
           modified_by = @modified_by
        FROM dbo.order_item oi
        WHERE oi.order_header_id = @order_header_id;

        UPDATE soi
        SET start_date = @new_start_date,
           end_date = @new_end_date,
           sap_order_status_id = ISNULL(@contract_status, sap_order_status_id),
           modified_date = @current_date,
           modified_by = @modified_by
        FROM dbo.sap_order_item soi
        WHERE soi.sap_order_id = @sap_order_id;
    END;
    IF (@update_sap_queue = 1)
    BEGIN
        DECLARE @sfdc_template_id INT = 33; -- sap_update_license
        DECLARE @sfdc_update_type_id INT = 158;

        INSERT dbo.sfdc_opportunity_update
        (
            order_header_id,
            sfdc_template_id,
            sfdc_update_type_id,
            insert_date,
            process_date
        )
        SELECT @order_header_id,
               @sfdc_template_id,
               @sfdc_update_type_id,
               @current_date,
               @current_date;

    END;

    SET @response_code = 0;
    SET @message = 'Contract update successful';

END TRY
BEGIN CATCH
    SET @response_code = -100;
    SET @message = 'General Failure, Check dberrorlog';
    DECLARE @db_name NVARCHAR(128);
    SET @db_name = DB_NAME();

    EXEC dbo.usp_LogError @ErrorDB = @db_name;
END CATCH;

GO
