-- =============================================================================
CREATE PROCEDURE [dbo].[usp_country_select_countries]

/*	
	DATE		AUTHOR		REMARKS
	2006-08-11	esmart		Initial creation.
	2006-09-13	esmart		Added order by
	2011-09-16	esmart		New columns
	2016-02-22	esmart		Add primary_sort
	2020-06-12	abelenkiy	AXIOM-1378: Simplified sort_order/primary_sort logic, removed order by from table variable insert, added order by description

	DESCRIPTION
	Select all countries from lu_countries
*/

as

	declare @lu_countries table (country_id smallint, description varchar(75), iso varchar(2), iso3 varchar(3), web_display tinyint, parent_country_iso3 varchar(30), parent_state_id char(2), sort_order int)

	insert into @lu_countries(country_id, description, iso, iso3, web_display, parent_country_iso3, parent_state_id)
	select country_id, description, iso, iso3, web_display,	parent_country_iso3, parent_state_id
	from lu_countries
	where web_display = 0

	update @lu_countries set sort_order = 1 where country_id = 1
	update @lu_countries set sort_order = 2 where country_id = 14
	update @lu_countries set sort_order = 3 where country_id = 39
	update @lu_countries set sort_order = 4 where country_id = 224

	select country_id, description, iso, iso3, web_display,	parent_country_iso3, parent_state_id, primary_sort = sort_order
	from @lu_countries
	order by iif(sort_order is null, 1, 0), sort_order, description





GO
