CREATE PROCEDURE [dbo].[usp_country_select_country]

(
	@iso varchar(2) = null,
	@iso3 varchar(3) = null,
	@country_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-09-13	esmart		Initial creation.
	2022-06-16  rambasana   return new columns - Postal_code_format and is_postal_code_required 

	DESCRIPTION
	select country
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
--	select iso = @iso, iso3 = @iso3, country_id = @country_id

	if @iso is not null
		begin
		select country_id, description, last_modified, iso, iso3, web_display, parent_country_iso3, parent_state_id, is_postal_code_required, postal_code_format 
		from lu_countries
 		where iso = @iso
		return
		end

	if @iso3 is not null
		begin
		select country_id, description, last_modified, iso, iso3, web_display, parent_country_iso3, parent_state_id, is_postal_code_required, postal_code_format
		from lu_countries
 		where iso3 = @iso3
		return
		end

	if @country_id is not null
		begin
		select country_id, description, last_modified, iso, iso3, web_display, parent_country_iso3, parent_state_id, is_postal_code_required, postal_code_format
		from lu_countries
 		where country_id = @country_id
		return
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
