-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_anonymize_customer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_customer_anonymize_customer]
	-- The parameters for the stored procedure
	@customer_id INT,
	@modified_by VARCHAR(50),
	@response_code INT OUTPUT,
	@message VARCHAR(100) OUTPUT

/*	
	DATE		AUTHOR		REMARKS
	2023-10-22	vsingh8		Initial creation

	DESCRIPTION
	Anonymizes customer data. This procedure is used by Webroot CSI. 
	Anonymization process should not create audit history.

	DEPENDENCY
	This procedure is invoked by Anonymize Customer action 
	on CSI Customer Detail page (https://csi.webroot.com/en_US/customers/view/<<CustomerId>>).

*/

AS
BEGIN

	SET NOCOUNT ON;

	BEGIN TRY

		DECLARE @anonymized_email VARCHAR(100),
			@anonymized_domain VARCHAR(20),
			@customer_email VARCHAR(100),
			@modified_date DATETIME;

		-- Validate the input customer id parameter.
		IF NOT EXISTS(SELECT 1 FROM dbo.customer WHERE customer_id = @customer_id)
		BEGIN
			SET @response_code = -100;
			SET @message = 'Non-existing customer id';
			RETURN @response_code;
		END
        
		-- Set anonymized_email to gdpr<<customer_id>>@email.com
		SET @anonymized_domain = 'email.com';
		SET @anonymized_email = CONCAT('gdpr', @customer_id, '@', @anonymized_domain);
		SET @modified_date = GETDATE();
		IF @modified_by = '' OR @modified_by IS NULL 
		BEGIN
			SET @modified_by = SUSER_SNAME();
		END

		SELECT
			@customer_email = customer_email
		FROM
			dbo.customer_email
		WHERE
			customer_id = @customer_id
			AND email_status_id = 1;

		BEGIN TRANSACTION anonymize_customer;
           
		-- Anonymize account user name (email) in account.
		UPDATE
			dbo.account
		SET
			account_user_name = @anonymized_email,
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			account_user_name = @customer_email;

		-- Anonymize email in account order staging.
		UPDATE
			dbo.account_order_staging
		SET
			email = @anonymized_email,
			modified_date = @modified_date
		WHERE
			email = @customer_email;

		-- Anonymize customer name.
		UPDATE
			dbo.customer
		SET
			first_name = '',
			last_name = '',
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			customer_id = @customer_id;

		-- Anonymize customer address.
		UPDATE
			dbo.customer_address
		SET
			address_1 = 'N/A',
			address_2 = '',
			address_3 = '',
			city = '',
			state = '',
			country_id = '',
			postal_code = '',
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			customer_id = @customer_id;

		-- Anonymize customer phone number.
		UPDATE
			dbo.customer_phone
		SET
			phone_number = '',
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			customer_id = @customer_id;

		-- Anonymize customer email id.
		UPDATE
			dbo.customer_email
		SET
			customer_email = @anonymized_email,
			email_domain = @anonymized_domain,
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			customer_id = @customer_id;

		-- Update license to remove anonymized customer association.
		UPDATE
			dbo.license
		SET
			customer_id = NULL,
			modified_date = @modified_date,
			modified_by = @modified_by
		WHERE
			customer_id = @customer_id;

		COMMIT TRANSACTION anonymize_customer;

		SET @response_code = 0;
		SET @message = 'Customer data anonymized successfully'
		RETURN @response_code;

	END TRY
	BEGIN CATCH

		IF @@TRANCOUNT >= 1
		BEGIN
			ROLLBACK TRANSACTION anonymize_customer;
		END

		SET @response_code = ERROR_NUMBER();
		SET @message = 'Customer data anonymization failed';

		-- Log error and return failure.
		DECLARE @db_name NVARCHAR(128);
		SET @db_name = DB_NAME();
		EXEC dbo.usp_LogError @ErrorDB = @db_name;

	END CATCH;

END;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_backfill]
-- =============================================================================

CREATE procedure [dbo].[usp_customer_backfill]
AS
/*	
	DATE		AUTHOR		REMARKS
	2021-08-26	psatish		initial creation
	2022-02-17  psatish		Updated the linked server name

	Description
	Intended for calling the [usp_sap_customer_backfill_new] for company backfill

*/
begin
set nocount on
declare @count int,@id INT=1,@backfill_id int

declare @backfilltable table
(
id int identity(1,1) primary key,
backfillid int
)
insert into @backfilltable
(
    backfillid
)
  select TOP 150 b.backfill_id
	from DATAWAREHOUSEREADONLY.Feed.dbo.sap_customer_master_backfill b
		left join dbo.sap_account s
			on s.sap_account_number = b.sap_account_number
	where s.sap_account_number is NULL
    AND isnull(blocked_reason,'') NOT like 'multiple%'
	AND isnull(exception_reason,'')<>'invalid company name' 
ORDER BY b.backfill_id
select @count= COUNT(*) FROM @backfilltable

while @id<=@count
begin
select @backfill_id=backfillid from @backfilltable where id=@id
exec dbo.usp_sap_customer_backfill_new @backfill_id


set @id=@id+1

end
end

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_create_customer_csi]
-- =============================================================================




CREATE procedure usp_customer_create_customer_csi
(
	@first_name nvarchar(255), 
	@middle_name nvarchar(32) = null, 	
	@last_name nvarchar(255), 
	@title nvarchar(50) = null, 
	@opt_in int ,
	@customer_email varchar(100),
	@company_name nvarchar(255),
	@response_code int OUTPUT,
	@message varchar(100)OUTPUT

)
AS

/*
	DATE		AUTHOR		REMARKS
	08/27/2006	tblazek		initial creation

	DESCRIPTION
	Insert customer record from CSI

*/

declare @insert_date datetime,
	@customer_id int

Set @insert_date = getdate()

---insert the customer record

	exec usp_customer_insert_customer  @first_name, @middle_name,@last_name, @title,@opt_in,@customer_email,@company_name,@customer_id output
			If @@ERROR <> 0 or @customer_id is null
			BEGIN
				Set @response_code = -100
				Set @message = 'SQL error insert customer record in exec usp_customer-insert_customer'
				RETURN
			END
--Return result set

	select 	c.customer_id,
		ce.customer_email_id as 'email_id',
		cc.customer_company_id as 'company_id',
		vc.vendor_customer_code
	from 	customer c
	join	customer_email ce
	on	c.customer_id = ce.customer_id
	left outer join	customer_company cc
	on	c.customer_id = cc.customer_id
	left outer join	customer_language cl
	on 	c.customer_id = cl.customer_id
	join 	vendor_customer vc
	on	c.customer_id = vc.customer_id
	where 	c.customer_id = @customer_id
	and ce.email_status_id = 1

	Set @response_code = 0
	Set @message = 'customer record inserted successfully'
	RETURN




GO
