CREATE PROCEDURE [dbo].[usp_customer_delete_merge_customer]

(
		@customer_merge_id int,	
		@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-01	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) gather data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) delete new master from merge list
	delete from customer_merge_customer where customer_merge_id = @customer_merge_id and customer_id = @customer_id

	if @@error = 0 
			begin
			select @response_code = 0, @message = 'Successfully deleted customer_merge'
			end

	select customer_merge_id = @customer_merge_id, response_code = @response_code, message = @message

	end try
	begin catch

