-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_delete_phone]
-- =============================================================================





CREATE  PROCEDURE usp_customer_delete_phone

(
	@customer_phone_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-12	esmart		Initial creation.

	DESCRIPTION
	Deletes a customer phone number 
*/


AS
	set nocount on

	declare @error int

	set @response_code = 0

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) check to see if the phone number exists
	-- ----------------------------------------------------------------------------------------------------------------------------------------

		select @response_code = 
				case
					when count(*) = 0 then - 100
					else 0
				end,
			@message = 
				case
					when count(*) = 0 then 'Phone number does not exist'
					else ''
				end
		from customer_phone
		where customer_phone_id = @customer_phone_id

		if @response_code <> 0
			begin	
				return
			end

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update phone number
	-- ----------------------------------------------------------------------------------------------------------------------------------------

	if @response_code = 0
		begin
			begin transaction delete_phone

				delete from customer_phone
				where customer_phone_id = @customer_phone_id
				
				if @@error > 0 
					begin
						rollback transaction delete_phone
						set @response_code = - 200
						set @message = 'General SQL error - customer_phone'
					end
				else
					begin
						set @response_code = 0
						set @message = 'Customer phone deleted successfully'
					end

			if @@trancount > 0
				commit transaction delete_phone
		end





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_email_unregister]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_customer_email_unregister]
	(@process_count INT = 1000)


/*	
	DATE		 AUTHOR			REMARKS
	2018-04-23	mrobbins		initial creation

	DESCRIPTION
	
*/

AS

	set nocount ON

	DECLARE @response_code INT,
		@message VARCHAR(100),
		@license_id INT, 
		@customer_id INT, 
		@customer_email VARCHAR(100), 
		@email_unregister_id INT,
		@email_unregister_customer_id INT,
		@max_email_unregister_customer_id INT


	DECLARE @email_unregister_customer TABLE (email_unregister_customer_id INT IDENTITY(1,1),
		email_unregister_id INT,
		license_id INT,
		customer_id INT,
		customer_email VARCHAR(255) NULL)
        
	BEGIN TRY

		-- 1) Selects

		INSERT INTO @email_unregister_customer (email_unregister_id,customer_email)
		SELECT TOP (@process_count)
			email_unregister_id,
			customer_email
		FROM email_unregister eu
		WHERE processed = 0


		SELECT @email_unregister_customer_id = MIN(email_unregister_customer_id),
			@max_email_unregister_customer_id = MAX(email_unregister_customer_id)
		FROM @email_unregister_customer

		WHILE @email_unregister_customer_id <= @max_email_unregister_customer_id
			BEGIN

				-- 2) updates
				select @customer_email = customer_email,
					@email_unregister_id = email_unregister_id
				from @email_unregister_customer 
				where email_unregister_customer_id = @email_unregister_customer_id

				--SELECT @customer_email customer_email,
				--	@email_unregister_id email_unregister_id


				INSERT INTO license_history(license_id,keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by,license_change_reason_id,history_date,history_by)
				SELECT l.license_id,
					l.keycode,
					l.customer_id,
					l.product_line_id,
					l.license_status_id,
					l.license_type_id,
					l.license_distribution_method_id,
					l.license_keycode_type_id,
					l.max_daily_activations,
					l.max_child_licenses,
					l.license_expiration_date,
					l.insert_date,
					l.insert_by,
					l.modified_date,
					l.modified_by,
					license_change_reason_id=4,
					history_date = GETDATE(), 
					history_by = SUSER_SNAME()
					FROM customer_email ce
						INNER JOIN license l
							ON ce.customer_id = l.customer_id
					WHERE ce.customer_email = @customer_email

				UPDATE l
				SET customer_id = NULL, 
					modified_date = GETDATE(), 
					modified_by = SUSER_SNAME()
				FROM customer_email ce
					INNER JOIN license l
						ON ce.customer_id = l.customer_id
				WHERE ce.customer_email = @customer_email

				DELETE lc
				FROM customer_email ce
					INNER JOIN license_customer lc
						ON ce.customer_id = lc.customer_id
				WHERE ce.customer_email = @customer_email


				-- 4) mark record as processed
				UPDATE dbo.email_unregister
				SET processed = 1
				WHERE email_unregister_id = @email_unregister_id


				-- 5) reset varibles

				SET @customer_id = NULL 
				SET @license_id = NULL
				SET	@customer_email = NULL

				SET @email_unregister_customer_id = @email_unregister_customer_id + 1

			END 


	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message is null THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;
GO
