-- PROCEDURE: [dbo].[usp_customer_generate_customer_code]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_customer_generate_customer_code]

(
	@customer_code varchar(13) output
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-11	esmart		Initial creation.

	DESCRIPTION
	Create customer code
*/

AS
begin try
	set nocount on 
	
	declare @customer_sequence_id int

	
	insert into customer_sequence (insert_date)
	values (getdate())

	set @customer_sequence_id = scope_identity()

	set @customer_code = convert(varchar(13),@customer_sequence_id)

	while len(@customer_code) < 12
			begin
				--print @customer_code
				set @customer_code = '0' + @customer_code
			end

	set @customer_code = 'E' + @customer_code



end try
begin catch

		
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;

GO
