-- PROCEDURE: [dbo].[usp_customer_inprocess_select]
-- =============================================================================





CREATE  PROCEDURE dbo.usp_customer_inprocess_select

(
	@customer_in_process_id int
)

/*	
	DATE		AUTHOR	REMARKS
	2006-09-05	rlansky		Initial creation.
	2006-09-05	tblazek		add postal_code to result set
	2006-09-06	tblazek		change country to country_id
	2006-10-25	tblazek		country_id not handled in the PHP, change back to returning ISO3 code as 'country'

	DESCRIPTION
	Select customer_in_process_id record for the customer_in_process_id value passed to procedure
	
	Return result set to PHP
	
Input Parameters:

customer_in_process_id

Output Parameters:

- none

Result Set Parameters:

customer_in_process_id
first_name
last_name
company_name
address1
address2
city
state_id
postal_code
country
phone_number
customer_email
opt_in

*/

AS
	set nocount on

	select	customer_in_process_id,
			first_name,
			last_name,
			company_name,
			address1,
			address2,
			city,
			state_id,
			postal_code,
			iso3 as 'country',
			phone_number,
			customer_email,
			opt_in
	from 	customer_in_process
	join	lu_countries
	on customer_in_process.country_id = lu_countries.country_id
	where 	customer_in_process_id = @customer_in_process_id





GO
