-- =============================================================================






CREATE   PROCEDURE [dbo].[usp_customer_insert_company]

(
	@customer_id int,
	@company_name varchar(255),
	@system_user varchar(50) = null,
	@customer_company_id int OUTPUT,
	@response_code int OUTPUT,
	@message varchar(50) OUTPUT
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-25	tblazek		Initial creation
	10/03/07	bjordan		Added try/catch

	DESCRIPTION
	Insert customer company record 
*/


AS
begin try
-- select @customer_id '@customer_id'
-- select @company_name '@company_name'
	SET NOCOUNT ON 

	if @system_user is null 
		BEGIN
			set @system_user = system_user
		END

	declare @insert_date datetime
	set @insert_date = getdate()

--Validate customer exists
If exists (select customer_id from customer where customer_id = @customer_id) and @company_name <> '' and @company_name <> '1'

	BEGIN
		insert into customer_company (customer_id, company_name, insert_date, insert_by, modified_date, modified_by)
		values (@customer_id, @company_name, @insert_date, @system_user, @insert_date, @system_user)

		set @customer_company_id = SCOPE_IDENTITY()
				
		set @response_code = 0
		set @message = 'customer_company insert complete'

	END

end try
begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	set @response_code = -400
	set @message = case when @message is null then 'customer_company insert failed' else @message end
	set @customer_company_id = null
	
end catch;




GO
