-- =============================================================================

CREATE   procedure [dbo].[usp_customer_insert_company_address_validation]
    @company_address_id int,
    @address_validation_method varchar(50),
    @is_valid bit,
    @insert_by varchar(50) = null,
    @expiration_date datetime = null
as
    /*
        DATE        AUTHOR      REMARKS
        2019-09-17  jnavarra    Initial creation
        2019-10-31  jnavarra    Use validation method name instead of ID for cleaner PHP code

        DESCRIPTION
        insert company_address_validation
    */

    set nocount on;

    begin try

        declare
            @address_validation_method_id int,
            @response_code int,
            @message varchar(100);

        select @address_validation_method_id = address_validation_method_id
        from dbo.address_validation_method
        where address_validation_method_name = @address_validation_method

	    update dbo.company_address_validation
        set expiration_date = getdate()
        where company_address_id = @company_address_id
              and address_validation_method_id = @address_validation_method_id
              and (expiration_date is null or expiration_date > getdate());

        insert into dbo.company_address_validation (company_address_id, address_validation_method_id, is_valid, insert_date, insert_by, expiration_date)
        values (@company_address_id, @address_validation_method_id, @is_valid, getdate(), isnull(@insert_by, system_user), @expiration_date);

    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'insert company address validation failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
