CREATE PROCEDURE [dbo].[usp_customer_insert_customer]

(
	@first_name nvarchar(255), 
	@middle_name nvarchar(32) = null, 	
	@last_name nvarchar(255), 
	@title nvarchar(50) = null, 
	@opt_in int = 1,
	@customer_email varchar(100),
	@company_name nvarchar(255),
	@customer_id int output
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2006-08-07	esmart		Modification to support new vendor_customer table and vendor_customer_id
	2006-08-11	esmart		Add additional error trapping
	2006-08-25	tblazek		Modify inserts to move the customer_id to the vendor_customer table and remove the vendor_customer_id 
					from customer table. add insert date variable, change @customer_id set variable statement to use scope_identity()
	2008-05-13	esmart	Alter proc to eliminate the creation of customer_company where company_name is ' ' or '1'

	DESCRIPTION
	Insert customer record and customer_email. 
	NOTE: This procedure will need to be modified when we get more details on address related data	
*/

	set nocount on




	declare @customer_code varchar(13),
		@vendor_id int,
		@vendor_customer_id int,
		@error int,
		@email_domain varchar(100),
		@insert_date datetime

		set @error = 0
		set @insert_date = getdate()

	-- 1.0) check to see if customer exist
	select @customer_id = 
					(select top 1 c.customer_id 
					from customer c
					inner join customer_email e
						on c.customer_id = e.customer_id and e.customer_email = @customer_email and e.email_status_id = 1
					where c.first_name = @first_name and c.last_name = @last_name
					order by c.customer_id desc)

	if @customer_id is not null
		begin
		return
		end

	-- 1.1) generate vendor customer code for new customer record

		exec usp_customer_generate_customer_code @customer_code output
	
		--print @customer_code
	-- 1.2) insert customer record
		if @customer_code is not null 
			begin
				
				-- 3.1) insert customer record
					insert into customer ( first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by)
					values (@first_name, @middle_name, @last_name, @title, @opt_in, @insert_date, system_user, @insert_date, system_user)
						
					set @error = @@error
					--print @error
			
					if @error <> 0 
						begin
							set @error = -310
							set @customer_id = null
							goto backout
						end
					else 
						begin
							set @customer_id = scope_identity()
						end
							
					--print @customer_id

				-- 3.2) insert customer_email record
					
					if @customer_email is not null and @customer_id is not null
						begin
							select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))
							
							insert into customer_email (customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
							values (@customer_id, @customer_email, 1, @insert_date, system_user, @insert_date, system_user, @email_domain)
		
							set @error = @@error
							--print @error
					
							if @error <> 0 
								begin
									set @error = -320
									goto backout
								end
						end
							
				-- 3.3 ) insert customer_company record
				
					if @company_name is not null and @company_name <> '' and @company_name <> '1' and @customer_id is not null
						begin
							
							insert into customer_company (customer_id, company_name, insert_date, insert_by, modified_date, modified_by)
							values (@customer_id, @company_name, @insert_date, system_user, @insert_date, system_user)

							set @error = @@error
							--print @error
					
							if @error <> 0 
								begin
									
									set @error = -330
									goto backout
									print @error
								end	

						end

				-- 3.4) insert vendor_customer record
				
					set
 @vendor_id = 1 -- webroot
					exec usp_customer_insert_vendor_customer @vendor_id, @customer_id, @customer_code, @vendor_customer_id output
				--select @vendor_customer_id '@vendor_customer_id'
							
			end

	backout:
		if @error < 0
			begin
				delete from customer_email where customer_id = @customer_id
				delete from customer_company where customer_id = @customer_id
				delete from customer where customer_id = @customer_id
				delete from vendor_customer where customer_id = customer_id 
			end
	
	return @customer_id

GO
