-- =============================================================================

CREATE PROCEDURE [dbo].[usp_customer_insert_customer_merge]

(
		@customer_merge_list varchar(100),
		@insert_by varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-01	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @master_customer_id int,
			@merge_customer_id int,
			@customer_merge_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) gather data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @customer_merge table (customer_id int, customer_insert_date datetime, max_order_date datetime)

	insert into @customer_merge (customer_id, customer_insert_date, max_order_date)
	select c.customer_id, 
		c.insert_date, 
		max_order_date = (select max(insert_date) from customer_order where customer_id = c.customer_id)
	from dbo.fn_integer_string_to_table(@customer_merge_list) t
	inner join customer c
		on t.integer_value = c.customer_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert customer merge
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) get @master_customer_id
	select @master_customer_id = (select top 1 customer_id from @customer_merge order by max_order_date desc)

	-- 2.2) insert customer_merge record
	insert into customer_merge (master_customer_id) values (@master_customer_id)

	select @customer_merge_id = scope_identity() 

	-- 2.3) insert customer_merge_customer
	insert into customer_merge_customer (customer_merge_id, customer_id)
	select @customer_merge_id, customer_id
	from @customer_merge
	where customer_id <> @master_customer_id

	if @@error = 0 
		begin
		select @response_code = 0, @message = 'Successfully inserted customer_merge'
		end 

	select customer_merge_id = @customer_merge_id, response_code = @response_code, message = @message

	end try
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert customer merge failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
