					 , @company_json = dbo.fn_company_variables_to_json(@company_id_input, @company_name, @company_type_
name, default, @salesforce_account_id, @vat_id, default)
					 , @partner_json = dbo.fn_partner_variables_to_json(@partner_id, default, default)

				select @input_json = (select json_query(@customer_json, '$.customer') as [customer], json_query(@company_json, '$.company') as [company], 
											json_query(@partner_json, '$.partner') as [partner], @transaction_user as [transaction_user] for json path, without_array_wrapper)

				-- 0.1.3) validate address inputs and insert row to table var
				insert into @customer_address (address_1, address_2, city, state, postal_code, country, address_type_id)
				select @address_1, @address_2, @city, @state, @postal_code, @country, 1-- input variables always use billing

            end

        -- 0.2) Debug
        -- Include     "debug":{"debug_input_parameters":1}     at the root of your @input_json to enable parameter debugging.
        if @debug_input_parameters = 1
