                declare @json_schema varchar(max) = '{"$schema": "http://json-schema.org/draft-04/schema#", "type": "object", "description": "JSON schema for usp_customer_insert_customer_service input parameters", "required": ["customer"], "properties": {
					"customer": {"type": "object", "required": ["customer_email"], "properties": {
