						"customer_email": {"type": "string", "maxLength": 100},
						"first_name": {"type": "string", "maxLength": 225},
						"last_name": {"type": "string", "maxLength": 225},
						"phone_number": {"type": "string", "maxLength": 64},
						"address": {"type": "object", "properties": {
							"bill_to": {"type": "object", "properties": {
								"address_1": {"type": "string", "maxLength": 255},
								"address_2": {"type": "string", "maxLength": 255},
								"city": {"type": "string", "maxLength": 130},
