								"location": {"type": "object", "description": "Currently only used for company address matching", "properties": {
									"lat": {"type": "number"},
									"lng": {"type": "number"},
									"subpremise": {"type": "string", "maxLength": 255}
								}}
							}}
							"ship_to": {"type": "object", "properties": {
								"address_1": {"type": "string", "maxLength": 255},
								"address_2": {"type": "string", "maxLength": 255},
