						"salesforce_contact_id": {"type": "string", "minLength": 18, "maxLength": 18}
					}},

					"company": {"type": "object", "pro
perties": {
						"company_id": {"type": "integer"},
						"company_name": {"type": "string", "maxLength": 255},
						"company_type_name": {"type": "string", "maxLength": 50},
						"company_type_id": {"type": "integer"},
						"salesforce_account_id": {"type": "string", "minLength": 18, "maxLength": 18},
						"vat_id": {"type": "string", "maxLength": 20}
					}},

					"partner": {"type": "object", "properties": {
						"partner_id": {"type": "integer"},
						"partner_customer_code": {"type": "string", "maxLength": 100, "description": "Field also referenced in DB as external_customer_key"},
					}},

					"transaction_user": {"type": "string", "maxLength": 20},

					"debug": {"type": "object", "properties": {
