						"debug_matching": {"type": "integer", "minimum": 0, "maximum": 1, "description": "Take no actions. Return details on different match paths."}
					}}
				}}'

                -- Construct @output_json from parsed JSON. Include JSON schema for reference.
                -- Add new parameters here
                set @output_json = (
                    select
                        @customer_email as customer_email,
                        @first_name as first_name,
                        @last_name as last_name,
                        @company_name as company_name,
                        @company_type_name as company_type_name,
                        @phone_number as phone_number,
                        (case when (select count(*) from @customer_address) > 10 then '>10' else (select customer_address_id, address_1, address_2, city, state, postal_code, country, country_id, google_place_id, address_type_id, location.Lat as lat, location.Long as lng, subpremise from @customer_address for json path) end) as [address],
                        @opt_in as opt_in,
                        @vendor_id as vendor_id,
                        @vendor_customer_code as vendor_customer_code,
                        @partner_id as partner_id,
                        @salesforce_account_id as salesforce_account_id,
                        @salesforce_contact_id as salesforce_contact_id,
                        @transaction_user as transaction_user,
                        @customer_id_input as customer_id_input,
                        @company_id_input as company_id_input,
                        @customer_id as customer_id,
                        @debug_input_parameters as debug_input_parameters,
