                    for json path, without_array_wrapper
                )

                -- Exit at this point without taking any action
                return
            end


        -- Check for email, this is the minimum requirement to continue
        if @customer_email is null or @customer_email = ''
            begin
                set @response_code = -201
                set @message = 'Required parameter "customer_email" not provided'
                return
            end


        -- 0.3) Save JSON
        insert into dbo.customer_update_json (customer_update_json, application_origin, insert_date, insert_by) 
        values (@input_json, left(app_name(),250), @transaction_date, left(system_user, 50))

        set @customer_update_json_id = scope_identity()

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -- ------------------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------

        if @transaction_user is null begin select @transaction_user = suser_sname() end

		-- 1.1.0) set customer_service_type from @customer_service_id (if provided in the JSON)
		--			this will be used to determine source and skip company match logic if SAP
		select @customer_service_type_name = cst.customer_service_type_name
		from customer_service cs
			inner join customer_service_type cst
				on cst.customer_service_type_id = cs.customer_service_type_id
		where cs.customer_service_id = @customer_service_id

		select @customer_service_type_name = isnull(@customer_service_type_name, '')

        -- 1.1)  select customers that match @customer_email
        declare @customers table (customer_id int, salesforce_contact_id varchar(18), first_name nvarchar(225), last_name nvarchar(225), opt_in int, customer_email_id int, customer_email varchar(100), 
			email_domain varchar(100), email_domain_type_id tinyint,  customer_company_id int, cc_company_name nvarchar(255), cc_company_type_id tinyint, company_id int, company_name nvarchar(255), 
			company_type_id tinyint, salesforce_account_id varchar(18),  customer_phone_id int, phone_number varchar(64), vendor_id int, vendor_customer_id int, vendor_customer_code varchar(100), partner_id int)     
        
        insert into @customers (customer_id, salesforce_contact_id, first_name, last_name, opt_in, customer_email_id, customer_email, email_domain, email_domain_type_id, customer_company_id, cc_company_name, 
			cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
        select c.customer_id, c.salesforce_contact_id, c.first_name, c.last_name, c.opt_in, e.customer_email_id, e.customer_email, e.email_domain, ce.email_domain_type_id, cc.customer_company_id, cc.company_name, 
			cc.company_type_id, co.company_id, co.company_name, co.company_type_id, co.salesforce_account_id, p.customer_phone_id, p.phone_number, vc.vendor_id, vc.vendor_customer_id, vc.vendor_customer_code, vc.partner_id
        from customer_email e with (nolock)
        inner join customer c with (nolock)
            on e.customer_id = c.customer_id
        left join customer_email_domain ce with (nolock)
            on e.email_domain = ce.email_domain
        left join vendor_customer vc with (nolock)
            on c.customer_id = vc.customer_id
        left join customer_company cc with (nolock)
            on c.customer_id = cc.customer_id
        left join company co with (nolock)
            on cc.company_id = co.company_id
        left join customer_phone p with (nolock)
            on c.customer_id = p.customer_id and p.phone_type_id = 1
        where e.customer_email = @customer_email and e.email_status_id = 1

        -- 1.2) set parameters
        select @phone_type_id = 1

        if @vendor_id = 0 or @vendor_id is null begin select @vendor_id = 1 end
        if @partner_id = 0 begin select @partner_id = null end
        if @company_name = '' begin select @company_name = null end
        if @salesforce_account_id = '' begin select @salesforce_account_id = null end
        if @salesforce_contact_id = '' begin select @salesforce_contact_id = null end
        if @opt_in is null begin select @opt_in = 1 end

		-- 1.2.0) validate passed in company_type_id; set from company_type_name if not passed in or invalid; set to 14 if neither found
		if not exists (select 1 from company_type with (nolock) where company_type_id = @company_type_id)
			begin
		        select @company_type_id = isnull(company_type_id, 14) from company_type with (nolock) where company_type_name = @company_type_name
			end

		-- 1.2.1) select billing address fields, or shipping if no billing
		if exists (select 1 from @customer_address ca)
		begin

			update @customer_address
			set address_1 = va.address_1
,
			address_2 = va.address_2,
			city = va.city,
			state = va.state_id,
			postal_code = va.postal_code,
			country = va.country,
			country_id = va.country_id
			from @customer_address ca
			cross apply	dbo.fn_clean_validate_address(ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, ca.country, null) va


			select top 1 @address_1 = ca.address_1,
				@address_2 = ca.address_2,
				@city = ca.city,
				@state = ca.state,
				@postal_code = ca.postal_code,
				@country_id = ca.country_id,
				@country = ca.country,
				@address_google_place_id = ca.google_place_id,
				@address_location = ca.location,
				@address_subpremise = ca.subpremise
			from @customer_address ca
			order by ca.address_type_id asc


			--select @address_1 = ca.address_1,
			--	@address_2 = ca.address_2,
			--	@city = ca.city,
			--	@state = ca.state,
			--	@postal_code = ca.postal_code,
			--	@country_id = ca.country_id,
			--	@address_google_place_id = ca.google_place_id,
			--	@address_location = ca.location,
			--	@address_subpremise = ca.subpremise
			--from (select top 1 address_1, address_2, city, state, postal_code, country_id, google_place_id, location, subpremise from @customer_address order by address_type_id asc) ca
            
		end


        -- 1.3) email_domain
        select @email_domain = SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

        select @email_domain_type_id = ed.email_domain_type_id
        from customer_email_domain ed
        where ed.email_domain = @email_domain

        if @email_domain_type_id is null and @email_domain is not null
            begin
                select @email_domain_type_id = 0

                insert into customer_email_domain (email_domain, email_domain_type_id)
                values(@email_domain,0)
            end
            
        -- 1.3) @salesforce_contact_id
        --select @salesforce_contact_id as salesforce_contact_id
        
        if @salesforce_contact_id is not null
            begin
                if exists (select customer_id from @customers where salesforce_contact_id = @salesforce_contact_id)
                    -- 1.3.1) match salesforce_contact_id
                    begin
                        -- print '1.3.1) match salesforce_contact_id'
                        select @customer_id = customer_id from customer with (nolock) where salesforce_contact_id = @salesforce_contact_id
                    end
                else 
                    -- 1.3.2) no match salesforce_contact_id (most likely change to email in SFDC.contact)
                    begin
                        -- print '1.3.2) no match salesforce_contact_id'
                        select @customer_id = customer_id from customer where salesforce_contact_id = @salesforce_contact_id

                        if @customer_id is not null
                        -- 1.3.2.1) add customer to @customers
                            begin
								insert into @customers (customer_id, salesforce_contact_id, first_name, last_name, opt_in, customer_email_id, customer_email, email_domain, email_domain_type_id, customer_company_id, cc_company_name, 
									cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
								select c.customer_id, c.salesforce_contact_id, c.first_name, c.last_name, c.opt_in, e.customer_email_id, e.customer_email, e.email_domain, ce.email_domain_type_id, cc.customer_company_id, cc.company_name, 
									cc.company_type_id, co.company_id, co.company_name, co.company_type_id, co.salesforce_account_id, p.customer_phone_id, p.phone_number, vc.vendor_id, vc.vendor_customer_id, vc.vendor_customer_code, vc.partner_id
                                from customer c with (nolock)
                                inner join customer_email e with (noloc
k)
                                    on e.customer_id = c.customer_id
								left join customer_email_domain ce with (nolock)
									on e.email_domain = ce.email_domain
                                left join vendor_customer vc with (nolock)
                                    on c.customer_id = vc.customer_id
                                left join customer_company cc with (nolock)
                                    on c.customer_id = cc.customer_id
                                left join company co with (nolock)
                                    on cc.company_id = co.company_id
                                left join customer_phone p with (nolock)
                                    on c.customer_id = p.customer_id and p.phone_type_id = 1
                                where c.customer_id = @customer_id
                            end
                        else
                        -- 1.3.2.2) check for duplicate contact email across accounts
                            begin
                                delete from @customers where salesforce_contact_id is not null
                            end
                    end
            end

        -- 1.4) @salesforce_account_id 
        if @salesforce_account_id is not null
            begin
                -- print '-- 1.4) @salesforce_account_id     '
                select @company_id = company_id from company with (nolock) where salesforce_account_id = @salesforce_account_id
            end

        -- 1.5) @customer_id_input
        if @customer_id_input is not null and not exists (select customer_id from @customers where customer_id = @customer_id_input)
            begin
				insert into @customers (customer_id, salesforce_contact_id, first_name, last_name, opt_in, customer_email_id, customer_email, email_domain, email_domain_type_id, customer_company_id, cc_company_name, 
					cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
				select c.customer_id, c.salesforce_contact_id, c.first_name, c.last_name, c.opt_in, e.customer_email_id, e.customer_email, e.email_domain, ce.email_domain_type_id, cc.customer_company_id, cc.company_name, 
					cc.company_type_id, co.company_id, co.company_name, co.company_type_id, co.salesforce_account_id, p.customer_phone_id, p.phone_number, vc.vendor_id, vc.vendor_customer_id, vc.vendor_customer_code, vc.partner_id
                from customer c with (nolock)
                inner join customer_email e with (nolock)
                    on e.customer_id = c.customer_id
				left join customer_email_domain ce with (nolock)
					on e.email_domain = ce.email_domain
                left join vendor_customer vc with (nolock)
                    on c.customer_id = vc.customer_id
                left join customer_company cc with (nolock)
                    on c.customer_id = cc.customer_id
                left join company co with (nolock)
                    on cc.company_id = co.company_id
                left join customer_phone p with (nolock)
                    on c.customer_id = p.customer_id and p.phone_type_id = 1
                where c.customer_id = @customer_id_input

                select @customer_id = @customer_id_input
            end

        -- 1.6) @company_id_input
        if @company_id_input is not null
            begin
                select @company_id = company_id, @company_name = case when @company_name is null then company_name else @company_name end from company where company_id = @company_id_input
            end

        -- Debug
        if @debug_matching = 1
            begin
                select '1.end' as section, @customer_email as customer_email, @company_id as company_id, @company_name as company_name, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id
          
      select * from @customers
            end

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 2.) Company
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
        declare @company_rowcount int, @blacklisted tinyint,@temp_id int, @total_ids int
        
        declare @company_name_match table (company_id int, company_name nvarchar(255), salesforce_account_id varchar(20), last_modified_date datetime, company_type_id tinyint, company_name_clean nvarchar(255), 
			address_1 nvarchar(255), city nvarchar(130), state nvarchar(3), postal_code nvarchar(32), country_id smallint)

        -- 2.1) invalid company name
        if exists (select company_name from company_name_invalid where company_name = @company_name)
            begin
                -- select '2.1) invalid company name'
                goto skip
            end
            
        -- select @company_id as company_id, @company_name as company_name, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id, @customer_id as customer_id, @customer_count as customer_count, @address_1 as address_1, @city as city, @state as state, @country as country, @country_id as country_id
        -- 2.2) match company
        if @company_name is not null and @company_id is null
            begin
				-- 2.2.1.0) skip matching if source is SAP
				if @customer_service_type_name not like 'sap_%'
				begin
					-- 2.2.1) franchise email_domain_type
					if @email_domain_type_id = 3 
						begin
							-- Override to make sure address matching is enabled since that's the primary method here

							insert into @company_name_match (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, company_name_clean, address_1, city, state, 
										postal_code, country_id)
							select c.company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, dbo.fn_get_company_name_clean(c.company_id), a.address_1, a.city, a.state, 
									a.postal_code, a.country_id
							from dbo.fn_match_companies_by_email_domain(default, @email_domain, default) ed
								inner join dbo.company c
									on ed.company_id = c.company_id
								cross apply dbo.fn_match_companies_by_address(c.company_id, default, default, @city, @state, default, @country_id, default, default, default, '{"overrides":{"address_match":{"enabled":1}}}') a
                        
							select @company_rowcount = @@ROWCOUNT
                    
							if @company_rowcount = 0 and @city is null
								begin
									-- select '2.2.1.1 New franchise without address data'
									goto skip
								end
                            
						end
					-- 2.2.2) all other email_domain_types
					else
						begin

							insert into @company_name_match (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, company_name_clean, address_1, city, state, postal_code, country_id)
							select c.company_id, c.company_name, c.salesforce_account_id, c.last_modified_date, c.company_type_id, c.company_name_clean, a.address_1, a.city, a.state, a.postal_code, a.country_id
							from dbo.fn_match_companies_by_name(@company_name, 1, default) n
								inner join dbo.company c
									on c.company_id = n.company_id
								outer apply dbo.fn_match_companies_by_address(c.company_id, default, default, default, default, default, default, default, default, default, default) a

							select @company_rowcount = @@ROWCOUNT
                    
							-- remove name matches for existing salesforce accounts
							if @salesforce_account_id is not null
								begin
						
			delete from @company_name_match 
									where salesforce_account_id is not null

									select @company_rowcount = count(company_id) from @company_name_match
								end
						end
				end
				else 
				begin
					-- set @company_rowcount = 0 to enter section 2.3) new company if source is SAP
					select @company_rowcount = 0
				end

                -- select '@company_name_match' as table_name, @company_rowcount as company_rowcount, * from @company_name_match order by country_id, state, city

                declare @company_address_match int, @company_email_domain_match int
                        
                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                -- 2.3) new company
                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                if @company_rowcount = 0
                    begin
                        -- 2.3.1) @company_address_match    
                        -- select @company_address_match = (select count(*) as 'company_address_match' from company_address a where a.address_1 = @address_1 and a.city = @city and a.state = @state and a.country_id = @country_id and a.address_type_id = 1 and a.address_status_id = 1)
                        
						if @country_id is not null-- this basically just means "is there an address"
							and @customer_service_type_name not like 'sap_%' -- skip exceptions if source is SAP
						begin
							select @address_exception_json = (
								select c.company_id, c.company_name, a.address_1, a.city, a.state, a.postal_code, a.country_id, @country as country
								from dbo.fn_match_companies_by_address(default, @address_1, @address_2, @city, @state, @postal_code, @country_id, @address_google_place_id, @address_location, @address_subpremise, default) a
									inner join dbo.company c
										on c.company_id = a.company_id
								for json path, without_array_wrapper
							)
						end

                        -- 2.3.2) email_domain 
                        if @email_domain_type_id in (2)
							and @customer_service_type_name not like 'sap_%' -- skip exceptions if source is SAP
                            begin
                                select @domain_exception_json = (
                                    select c.company_id, c.company_name, ed.email_domain, ed.email_domain_type_id
                                    from dbo.fn_match_companies_by_email_domain(default, @email_domain, @email_domain_type_id) ed
                                        inner join dbo.company c
                                            on c.company_id = ed.company_id
                                    for json path, without_array_wrapper
                                )
                            end

                        -- Debug
                        if @debug_matching = 1
                            begin
                                select '2.3' as section, @customer_email as customer_email, @company_id as company_id, @company_name as company_name, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id
                                select * from @customer_address
                                select * from @company_name_match
                                select @address_exception_json as address_exception_json, @domain_exception_json as domain_exception_json, case when @address_exception_json is null and @domain_exception_json is null then 'Should create a new company' else 'Should exit with exception' end as action

                                return
                            end

                        -- Exceptions
                        if @address_exception_json is not null
                            begin

                                --select '2.3.1) @company_address_match', * from company_address a where a.address_1 = @address_1 and a.city = @city and a.state = @state and a.country_id = @country_id and a.address_type_id = 1 and a.address_status_id = 1
                                insert into company_match_exception (company_name, company_match_type, exception_reason, exception_date, customer_update_json_id,exception_json)
                                select @company_name,'new company','insert company failed: matching company on company_address', @transaction_date, @customer_update_json_id, @address_exception_json
                                select @company_match_exception = 1

                                goto skip
                            end

                        if @domain_exception_json is not null
                            begin
                                insert into company_match_exception (company_name, company_match_type, exception_reason, exception_date, customer_update_json_id)
                                select @company_name,'new company','insert company failed: matching company on  email_domain_type - business', @transaction_date, @customer_update_json_id
                                select @company_match_exception = 1
                                        
                                goto skip
                            end
                        
                        -- 2.3.1) insert company
                        insert into company (company_name, last_modified_date, company_type_id, company_name_clean,salesforce_account_id)
                        select @company_name, getdate(), @company_type_id, dbo.fn_clean_company_name(@company_name),@salesforce_account_id

                        select @company_id = scope_identity()

                        exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type = 'Primary'

                        if @email_domain is not null
                            begin
								--If we're inserting a company record and the email domain type is currently undefined, default it to business and update accordingly on customer_email_domain
								if @email_domain_type_id = 0 
									begin
										set @email_domain_type_id = 2

										update customer_email_domain
										set email_domain_type_id = @email_domain_type_id
										where email_domain = @email_domain
									end
                                insert into company_email_domain (company_id, email_domain, email_domain_type_id, protected, customers, insert_date)
                                select @company_id, @email_domain, @email_domain_type_id, 0 as protected, 1 as customers, getdate()
                            end

                        exec dbo.usp_customer_update_company_address @company_id=@company_id, @address_1=@address_1, @address_2=@address_2, @city=@city, @state=@state, @postal_code=@postal_code, @country_id=@country_id
                    end

                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                -- 2.4) company name - single match
                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                else if @company_rowcount = 1
                    begin
                        -- select '2.4) company name - single match'

                        select @company_id = c.company_id, @company_type_id = c.company_type_id from @company_name_match c
                                                    
                        -- 2.4.1) @company_address_match
                        select @company_address_match = (select count(*) from dbo.fn_match_companies_by_address(@company_id,
 @address_1, @address_2, @city, @state, @postal_code, @country_id, @address_google_place_id, @address_location, @address_subpremise, default))
                            
                        -- 2.4.2) @company_email_domain_match    
                        select @company_email_domain_match = (select count(*) from dbo.fn_match_companies_by_email_domain(@company_id, @email_domain, @email_domain_type_id))

                        -- Debug
                        if @debug_matching = 1
                            begin
                                select '2.4' as section, @customer_email as customer_email, @company_id as company_id, @company_name as company_name, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id
                                select * from @company_name_match
                                select @company_address_match as company_address_match_count, @company_email_domain_match as company_email_domain_match_count

                                return
                            end

                        -- 2.4.3) log exception
                        if @company_address_match = 0 and @company_email_domain_match = 0
                            begin
                                select @match_exception_json = (
                                    select m.company_id, m.company_name, m.address_1, m.city, m.state, m.postal_code, m.country_id, lc.description as country, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id
                                    from @company_name_match m
                                    left join lu_countries lc
                                        on m.country_id = lc.country_id
                                    for json path, without_array_wrapper
                                )

                                insert into company_match_exception (company_name, company_match_type, exception_reason, exception_date, customer_update_json_id, exception_json)
                                select @company_name,'company name - single match',exception_reason = 'Warning: no match on company_address and company_email_domain. company_id='+convert(varchar(20),@company_id),@transaction_date, 
									@customer_update_json_id, @match_exception_json
                                select @company_id = null
                                select @company_match_exception = 1

                                goto skip
                            end
                        else if @company_address_match = 0
                            begin
                                -- 2.4.4) add new company_address
                                exec dbo.usp_customer_update_company_address @company_id=@company_id, @address_1=@address_1, @address_2=@address_2, @city=@city, @state=@state, @postal_code=@postal_code, @country_id=@country_id
                            end
                    end

                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                -- 2.5) multiple match
                -------------------------------------------------------------------------------------------------------------------------------------------------------------------
                else if @company_rowcount > 1
                    begin
                        -- select ' 2.5) multiple match'
                        
                        -- 2.5.1) franchise domain
                        if @email_domain_type_id = 3
                            begin
                                declare @franchise_match_count int = 0

                                select @franchise_match_count = (select count(distinct m.company_id) from @company_name_match m where m.country_id = @country_id and m.state = @state and m.city = @city)

                                if @fra
nchise_match_count = 1
                                    begin
                                        --select '-- 2.5.1) franchise domain'
                                        select @company_id = m.company_id
                                        from @company_name_match m
                                        where m.country_id = @country_id and m.state = @state and m.city = @city 
                                    end
                                else if @franchise_match_count > 1
                                    begin
                                        select @address_exception_json = (
                                            select m.company_id, m.company_name, m.address_1, m.city, m.state, m.postal_code, m.country_id, lc.description as country, @email_domain as email_domain, @email_domain_type_id as email_domain_type_id
                                            from @company_name_match m
                                            left join lu_countries lc
                                                on m.country_id = lc.country_id
                                            where m.country_id = @country_id and m.state = @state and m.city = @city 
                                            for json path, without_array_wrapper
                                        )

                                        insert into company_match_exception (company_name, company_match_type, exception_reason, exception_date, customer_update_json_id, exception_json)
                                        select @company_name,'company name - multiple match: franchise','multiple matches on city, state, country', @transaction_date, @customer_update_json_id, @address_exception_json
                                        select @company_match_exception = 1

                                        goto skip
                                    end
                            end
                        -- 2.5.2) other domain types
                        else
                            begin
                                -- 2.5.2.1) get company_id from email domain match
                                select @company_id = m.company_id
                                from @company_name_match m
                                cross apply dbo.fn_match_companies_by_email_domain(m.company_id, @email_domain, 2) ed

                                if @company_id is null
                                    begin
                                        select @company_id = m.company_id
                                        from @company_name_match m
                                        where m.country_id = @country_id and m.state = @state and m.city = @city 
                                    end
                            end

                        -- 2.5.2.3) new company
                        if @company_id is null and @country_id is not null
                            begin
                                insert into company (company_name, last_modified_date, company_type_id, company_name_clean,salesforce_account_id)
                                select @company_name, getdate(), @company_type_id, dbo.fn_clean_company_name(@company_name),@salesforce_account_id

                                select @company_id = scope_identity()

                                exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type = 'Primary'

                                if @email_domain is not null
                                    begin
										--Same as the 2.3 condition, if we're inserting a company record and the email domain type is currently undefined, default it to business and update accordingly on customer_email_domain
										if @email_domain_type_id = 0 
											begin
												set @email_domain_type_id = 2

												update customer_email_domain
												set e
mail_domain_type_id = @email_domain_type_id
												where email_domain = @email_domain
											end										 
                                        insert into company_email_domain (company_id, email_domain, email_domain_type_id, protected, customers, insert_date)
                                        select @company_id, @email_domain, @email_domain_type_id, 0 as protected, 1 as customers, getdate()
                                    end

                                exec dbo.usp_customer_update_company_address @company_id=@company_id, @address_1=@address_1, @address_2=@address_2, @city=@city, @state=@state, @postal_code=@postal_code, @country_id=@country_id
                            end
                    end
            end

        -- 2.6) updates
        if @company_id is not null
            begin
                if exists (select company_id from company where company_id = @company_id and 
                                                                (company_name <> @company_name or 
                                                                (salesforce_account_id <> @salesforce_account_id or 
                                                                (salesforce_account_id is null and @salesforce_account_id is not null)) or 
                                                                (company_type_id <> @company_type_id or company_type_id is null)))
                    begin
                        -- 2.6.1) update
                        insert into company_audit (company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, audit_date)
                        select company_id, company_name, salesforce_account_id, last_modified_date, company_type_id, @transaction_date
                        from company where company_id = @company_id
                            
                        update company
                        set salesforce_account_id = case when @salesforce_account_id is null then salesforce_account_id else @salesforce_account_id end, 
                            company_type_id = @company_type_id, last_modified_date = @transaction_date
                        where company_id = @company_id

                        -- If the name is different, the existing name will become a secondary
                        exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type = 'Primary'
					end

				-- 2.6.2) company_vat
				if @vat_id is not null and @vat_id <> '' and exists (select 1 from lu_countries where country_id = @country_id and isnull(is_vat_eligible, 1) = 1)
				begin
					if not exists (select 1 from company_vat where company_id = @company_id and country_id = @country_id)
					begin
						insert into company_vat (company_id, vat_id, country_id)
						values (@company_id, @vat_id, @country_id)
					end
					else
					begin
						insert into company_vat_audit (company_vat_id, company_id, country_id, vat_id, modified_date, modified_by, insert_date, insert_by)
						select cv.company_vat_id, cv.company_id, cv.country_id, cv.vat_id, cv.modified_date, cv.modified_by, cv.insert_date, cv.insert_by 
						from company_vat cv
						where cv.company_id = @company_id and cv.country_id = @country_id and cv.vat_id <> @vat_id

						if @@rowcount > 0
						begin
							update company_vat 
							set vat_id = @vat_id,
								modified_date = @transaction_date,
								modified_by = @transaction_user
							where company_id = @company_id
								and country_id = @country_id
						end
					end
                 end
            end
        
        skip:

        --select 'post 2. company match', @company_id as company_id, @customer_id as customer_id, @company_match_exception as company_match_exception
        --return

        -- ----------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------
        -- 3.) Customer match
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
        select @customer_count = count(*) from @customers
                   
        if @customer_count > 0 and @customer_id is null and @company_id is null and @company_name is null
        -- 3.1) customer match without company data 
            begin
                -- 3.1.2) multiple customers
                if @customer_count > 1
                    begin
                        if (select count(*) from @customers where first_name = @first_name and last_name = @last_name) = 1
                            begin
                                -- print 'Single first/last match'
                                select @customer_id = customer_id, 
                                        @vendor_customer_code = case when @vendor_customer_code is null then vendor_customer_code else @vendor_customer_code end, 
                                        @vendor_customer_id = case when @vendor_customer_id is null then vendor_customer_id else @vendor_customer_id end 
                                from @customers where first_name = @first_name and last_name = @last_name
                            end    
                        else if (select count(*) from @customers where first_name = @first_name and last_name = @last_name) > 1
                            begin
                                -- print 'Multiple first/last match'
                                select @customer_id = max(customer_id) from @customers where first_name = @first_name and last_name = @last_name

                                select @vendor_customer_code = case when @vendor_customer_code is null then vendor_customer_code else @vendor_customer_code end, 
                                        @vendor_customer_id = case when @vendor_customer_id is null then vendor_customer_id else @vendor_customer_id end
                                from @customers
                                where customer_id = @customer_id

                            end
                        else
                            begin
                                select @customer_id = max(customer_id) from @customers

                                select @vendor_customer_code = case when @vendor_customer_code is null then vendor_customer_code else @vendor_customer_code end, 
                                        @vendor_customer_id = case when @vendor_customer_id is null then vendor_customer_id else @vendor_customer_id end
                                from @customers
                                where customer_id = @customer_id
                            end
                    end
                -- 3.1.2) Single match
                else
                    begin
                        -- 3.1.2.1) without salesforce_contact_id
                        if @salesforce_contact_id is null
                            begin
                                select @customer_id = customer_id, 
                                        @vendor_customer_code = case when @vendor_customer_code is null then vendor_customer_code else @vendor_customer_code end, 
                                        @vendor_customer_id = case when @vendor_customer_id is null then vendor_customer_id else @vendor_customer_id end
                                from @customers
                            end
                        -- 3.1.2.2) only find customers without salesforce_contact_id (multiple salesforce contacts with the same email)
                        else
                            begin
                                select @customer_id = customer_id, 
                                        @ve
ndor_customer_code = case when @vendor_customer_code is null then vendor_customer_code else @vendor_customer_code end, 
                                        @vendor_customer_id = case when @vendor_customer_id is null then vendor_customer_id else @vendor_customer_id end
                                from @customers
                                where salesforce_contact_id is null                            
                            end
                    end
            end
        -- 3.2) customer match with company data
        else if @customer_count > 0 and @customer_id is null and (@company_id is not null or @company_name is not null)
            begin
                -- 3.2.1) single match on company_id
                if (select count(*) from @customers where company_id = @company_id) = 1
                    begin
                        --select '3.2.1) single match on company_id'
                        select @customer_id = customer_id from @customers where company_id = @company_id
                    end

                -- 3.2.2) case when we have duplicate customers with the same company
                else if (select count(*) from @customers where company_id = @company_id) > 1
                    begin
                        --select '3.2.2) case when we have duplicate customers with the same company'
                        select @customer_id = max(customer_id) from @customers where company_id = @company_id
                    end

                -- 3.2.3) find customer with matching company_name and no company_id
                if @customer_id is null
                    begin
                        --select '3.2.3) find customer with matching company_name and no company_id'
                        select @customer_id = max(customer_id) from @customers c where c.company_id is null and c.company_name = @company_name
                    end
                
                -- 3.2.4) find customer with no company_name and no company_id
                if @customer_id is null
                    begin
                        --select '3.2.4) find customer with no company_name and no company_id'
                        select @customer_id = max(customer_id) from @customers c where c.company_id is null and c.company_name is null
                    end
            end    
					
		-- 3.3) vendor_customer_id
		if @vendor_customer_id is null
			begin
			select @vendor_customer_id = vendor_customer_id from vendor_customer where customer_id = @customer_id
			end
        
        --select 'post 3. customer match', @company_id as company_id, @customer_id as customer_id, @company_name as company_name, @company_match_exception as company_match_exception
        --select '@customers' as table_name, * from @customers
        --select '@customers matching customer_id' as table_name, * from @customers where customer_id = @customer_id
        --return

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 4.) New customer
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        if @customer_id is null
            begin
               --  select '4.) New customer' as Step

                -- 4.1) customer
                insert into customer (first_name, last_name, opt_in, salesforce_contact_id, insert_date, insert_by, modified_date, modified_by)
                values (@first_name, @last_name, @opt_in, @salesforce_contact_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                
                select @customer_id = scope_identity()        

                -- 4.2) customer_email
                
if @customer_email is not null
                    begin
                        select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))
                        
                        insert into customer_email (customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
                        values (@customer_id, @customer_email, 1, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @email_domain)
                    end

                -- 4.3) customer_company
                if @company_name is not null and @customer_id is not null
                    begin
                        -- 4.3.1) salesforce company
                        if @company_id is not null
                            begin
                                -- print '4.3.1) salesforce company'
                                insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)
                                select @customer_id, company_name, company_id, company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user
                                from company
                                where company_id = @company_id
                            end
                        -- 4.3.2) standard customer company
                        else
                            begin
                                -- print '4.3.2) standard customer company'
                                insert into customer_company (customer_id, company_name, company_type_id, insert_date, insert_by, modified_date, modified_by)
                                select @customer_id, @company_name, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user
                            end
                    end

                -- 4.4) vendor_customer
                -- 4.4.1) generate new code
                if @vendor_customer_code is null
                    begin
                        -- print '4.4.1) vendor_customer'
                        exec usp_customer_generate_customer_code @vendor_customer_code output
                        --select @vendor_customer_code = @customer_code
                    end
                
                -- 4.4.2) insert vendor_customer
                insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
                values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
            
                -- 4.5) customer_phone
                if @phone_number is not null and @phone_number <> ''
                    begin
                        -- print '4.5) customer_phone'
                        insert into customer_phone (customer_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
                        values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                    end
					
                -- 4.6) customer_address
				-- 4.6.1) check if addresses were passed in
				if exists (select 1 from @customer_address)
				
					-- 4.6.2) set @max for while loop
					begin
						select @max = (select max(temp_id) from @customer_address)

						-- 4.6.3) run through @customer_address table with while loop, executing usp_customer_update_customer_address for each address type
						while @max >= @l_temp_id
							begin
								select @l_address_type_id = ca.address_type_id, @l_address_1 = ca.address_1, @l_address_2 = ca.address_2, @l_city = ca.city, @l_state = ca.state, 
									@l_postal_code = ca.postal_code, @l_country_id = ca.country_id
								from @cu
stomer_address ca where ca.temp_id = @l_temp_id 

								if @@rowcount > 0 --temp_id may not exist if address records are deleted from table variable for whatever reason
									begin
										exec usp_customer_update_customer_address @customer_id = @customer_id, @address_type_id = @l_address_type_id, @address_1 = @l_address_1, @address_2 = @l_address_2, 
											@city = @l_city, @state = @l_state, @postal_code = @l_postal_code, @country_id = @l_country_id, @transaction_user = @transaction_user, 
											@customer_address_id = @customer_address_id output, @message = @l_customer_address_message output
									end

								-- 4.6.3.1) update @customer_address_table with active customer_address_id for customer/type (from output of above)
								update @customer_address
								set customer_address_id = @customer_address_id,
									message = @l_customer_address_message
								where address_type_id = @l_address_type_id

								select @l_address_type_id = null, @l_address_1 = null, @l_address_2 = null, @l_city = null, @l_state = null, @l_postal_code = null, @l_country_id = null, 
										@customer_address_id = null, @l_temp_id = @l_temp_id + 1, @l_customer_address_message = null
							end

					end
            
                -- 4.7) customer_locale
                exec usp_customer_update_customer_locale @customer_id

                -- 4.8) partner_company
                if @partner_id is not null and @company_id is not null and @partner_customer_code is not null and @partner_customer_code <> ''
                    begin
                        select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

                        if @partner_company_id is null
                            begin
                                insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
                                values (@partner_id, @partner_customer_code, @company_name, @company_id)    
                            end
                        else
                            begin
								insert into partner_company_audit (partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, audit_date)
								select partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, @transaction_date 
								from partner_company 
								where partner_company_id = @partner_company_id

								if @@rowcount > 0 
								begin 
									update partner_company
									set partner_customer_code = @partner_customer_code,
										company_name = @company_name
									where partner_company_id = @partner_company_id
								end 
                            end                
                    end
            end

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 5.) Update customer
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       else
            begin
                -- 5.1) update customer
                -- select ' -- 5.1) update customer' as step
                
                if exists (select customer_id 
                            from @customers
                            where customer_id = @customer_id 
                                and (first_name <> @first_name or last_name <> @last_name or opt_in <> @opt_in or 
                                    (first_name is null and @first_name is not null) or (last_name is null and @last_name is not null) or
                                        (salesforce_contact_id <> @salesforce_contact_id or 
               
                         (salesforce_contact_id is null and @salesforce_contact_id is not null))
                                    )
                            )
                    begin
                        -- 5.1.1) insert customer_audit
                        insert into customer_audit (customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, audit_date, audit_by)
                        select customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, @transaction_date, @transaction_user
                        from customer with (nolock)
                        where customer_id = @customer_id

                        -- 5.1.2) update customer
                        update customer
                        set    first_name = @first_name, last_name = @last_name, opt_in = @opt_in, modified_date = @transaction_date, modified_by = @transaction_user, 
                            salesforce_contact_id = case when @salesforce_contact_id is null then salesforce_contact_id else @salesforce_contact_id end
                        where customer_id = @customer_id
                    end

                -- 5.2) update customer_email
				if @customer_email <> (select customer_email from customer_email where customer_id = @customer_id and email_status_id = 1)
                    begin
                        -- print '5.2 update customer_email'
                        update customer_email 
                        set email_status_id = 0, modified_date = @transaction_date, modified_by = @transaction_user
                        where customer_id = @customer_id and email_status_id = 1

                        select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

                        insert into customer_email(customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
                        values(@customer_id, @customer_email, 1, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @email_domain)
                    end

                -- 5.3) customer_company
                if @company_name is not null
                    begin
                        declare @current_company_name nvarchar(255), @current_company_id int, @current_company_type_id tinyint
                        --select '5.3) customer_company'
                        select @customer_company_id = customer_company_id, @current_company_name = cc_company_name, @current_company_type_id = cc_company_type_id, @current_company_id = company_id from @customers where customer_id = @customer_id

                        -- 5.3.1) insert customer_company
                        if @customer_company_id is null
                            begin
                                -- select '-- 5.3.1) insert customer_company'
                                insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)    
                                values(@customer_id, @company_name, @company_id, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.3.2) update customer_company
                        else
                            begin
                                --select @customer_company_id, @current_company_id, @current_company_name, @current_company_type_id, @company_id, @company_name, @company_type_id
                                if (@current_company_name <> @company_name or 
                                    (@current_company_id is null and @company_id is not null) or 
                                    (@current_company_type_id is null or @curre
nt_company_type_id <> @company_type_id)) 
                                    begin
                                        -- select '-- 5.3.2) update customer_company'
                                        insert into customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id)
                                        select customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id from customer_company where customer_company_id = @customer_company_id

                                        update customer_company
                                        set company_name = @company_name, 
                                            company_id = case 
                                                            when @company_id is null then company_id
                                                            else @company_id
                                                        end, 
                                            company_type_id = @company_type_id, modified_date = @transaction_date, modified_by = @transaction_user
                                        where customer_company_id = @customer_company_id
                                    end
                            end
                    end
            
                -- 5.4) vendor_customer
                if @vendor_customer_id is null -- and (select count(*) from vendor_customer where vendor_id = @vendor_id and customer_id = @customer_id) = 0
                    begin
                        -- print '5.4.1) insert new vendor_customer' 
                        
                        -- 5.4.1) insert new vendor_customer
                        if @vendor_customer_code is null
                            begin
                                -- 5.4.1.1) insert new
                                exec usp_customer_generate_customer_code @vendor_customer_code output
                            end
                        
                        insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
                        values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user)

                    end
                else 
                    -- 5.4.2) update vendor_customer
                    begin
                        if @vendor_customer_code is not null
                            begin
                                insert into vendor_customer_audit(vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
                                select vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by
                                from vendor_customer with (nolock)
                                where vendor_customer_id = @vendor_customer_id and vendor_customer_code <> @vendor_customer_code

								if @@rowcount > 0
								begin

									update vendor_customer
									set vendor_customer_code = @vendor_customer_code, modified_date = @transaction_date, modified_by = @transaction_user
									where vendor_customer_id = @vendor_customer_id

								end
                            end
                    end

                -- 5.5) customer_phone
                if @phone_number is not null and @phone_number <> ''
                    begin
                        if not exists (select phone_number from @customers where customer_id = @customer_id)
                        -- 5.5.1) insert phone
                            begin
                                -- print '5.5.1 insert phone'
                                insert into customer_phone (custom
er_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
                                values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.5.2) update phone - the TOP is a temporary fix until we clean duplicates in customer_phone table
                        else if (select top (1) phone_number from @customers where customer_id = @customer_id) <> @phone_number
                            begin
                                -- print '5.5.2) update phone'
                                update customer_phone
                                set phone_number = @phone_number, modified_date = @transaction_date, modified_by = @transaction_user
                                where customer_id = @customer_id and phone_type_id = @phone_type_id
                            end
                    end            
					
                -- 5.6) customer_address
				-- 5.6.0) set @customer_address_id to bill_to address
				select @customer_address_id = ca.customer_address_id,
					@l_customer_address_message = 'No address input'
				from customer_address ca
				where ca.customer_id = @customer_id
					and ca.address_type_id = 1

				-- 5.6.1) check if addresses were passed in
				if exists (select 1 from @customer_address)
				
					-- 5.6.2) set @max for while loop
					begin
						select @max = (select max(temp_id) from @customer_address)

						-- 5.6.3) run through @customer_address table with while loop, executing usp_customer_update_customer_address for each address type
						while @max >= @l_temp_id
							begin
								select @l_address_type_id = ca.address_type_id, @l_address_1 = ca.address_1, @l_address_2 = ca.address_2, @l_city = ca.city, @l_state = ca.state, 
									@l_postal_code = ca.postal_code, @l_country_id = ca.country_id
								from @customer_address ca where ca.temp_id = @l_temp_id 

								if @@rowcount > 0 --temp_id may not exist if address records are deleted from table variable for whatever reason
									begin
										exec usp_customer_update_customer_address @customer_id = @customer_id, @address_type_id = @l_address_type_id, @address_1 = @l_address_1, @address_2 = @l_address_2, 
											@city = @l_city, @state = @l_state, @postal_code = @l_postal_code, @country_id = @l_country_id, @transaction_user = @transaction_user, 
											@customer_address_id = @customer_address_id output, @message = @l_customer_address_message output
									end

								-- 5.6.3.1) update @customer_address_table with active customer_address_id for customer/type (from output of above)
								update @customer_address
								set customer_address_id = @customer_address_id,
									message = @l_customer_address_message
								where address_type_id = @l_address_type_id

								select @l_address_type_id = null, @l_address_1 = null, @l_address_2 = null, @l_city = null, @l_state = null, @l_postal_code = null, @l_country_id = null, 
										@customer_address_id = null, @l_temp_id = @l_temp_id + 1, @l_customer_address_message = null
							end

					end

                -- 5.7) partner_company
                if @partner_id is not null and @company_id is not null and @partner_customer_code is not null and @partner_customer_code <> ''
                    begin
                        select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

                        if @partner_company_id is null
                            begin
                                insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
                                values (@partner_id, @partner_customer_code, @company_name, @company_id)    
                            end
                        else
            
                begin
								insert into partner_company_audit (partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, audit_date)
								select partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, @transaction_date 
								from partner_company 
								where partner_company_id = @partner_company_id

								if @@rowcount > 0 
								begin 
									update partner_company
									set partner_customer_code = @partner_customer_code,
										company_name = @company_name
									where partner_company_id = @partner_company_id
								end 
                            end                
                    end
            end



        -- Output execution data
        set @output_json = (
            select
                @customer_id as [customer.customer_id],
                isnull((select ca.customer_address_id from @customer_address ca where ca.address_type_id = 1), @customer_address_id) as [customer.address.bill_to.customer_address_id],
                isnull((select ca.message from @customer_address ca where ca.address_type_id = 1), @l_customer_address_message) as [customer.address.bill_to.customer_address_message],
                (select ca.customer_address_id from @customer_address ca where ca.address_type_id = 2) as [customer.address.ship_to.customer_address_id],
                (select ca.message from @customer_address ca where ca.address_type_id = 2) as [customer.address.ship_to.customer_address_message],
                @vendor_customer_id as [customer.vendor_customer_id],
                @company_id as [company.company_id],
                @email_domain as [company.email_domain],
                @customer_update_json_id as customer_update_json_id,
                @company_address_match as [match.company_address_match_count],
                @company_email_domain_match as [match.company_email_domain_match_count],
                @franchise_match_count as [match.franchise_match_count],
                (case when (select count(*) from @customers) > 10 then '>10' else (select customer_id from @customers for json path) end) as [match.customers],
                (case when (select count(*) from @company_name_match) > 10 then '>10' else (select company_id, company_name from @company_name_match for json path) end) as [match.company_name_match],
                @address_exception_json as [exception.address_exception_json],
                @domain_exception_json as [exception.domain_exception_json],
                @match_exception_json as [exception.match_exception_json]
            for json path, without_array_wrapper
        )

        -- Update the log before exiting
        update dbo.customer_update_json
        set complete_date = getdate(),
            output_json = @output_json
        where customer_update_json_id = @customer_update_json_id

    end try
    begin catch

		declare
			@error_severity int = error_severity(), @error_state int = error_state()
		set @message = 'customer_update_json_id = ' + convert(varchar(20), isnull(@customer_update_json_id, 'null')) 
					+ ', customer_email = ' + isnull(@customer_email, 'null')
					+ ': ' + error_message()
		raiserror(@message, @error_severity, @error_state) with log

		insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()
        
    end catch;
    

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_customer_service_NEW]
-- =============================================================================


CREATE   PROCEDURE [dbo].[usp_customer_insert_customer_service_NEW]
(
    @customer_email varchar(100),
    @first_name nvarchar(225) = null,
    @last_name nvarchar(225) = null,
    @company_name nvarchar(255) = null,
    @company_type_name varchar(20) = null,
    @phone_number varchar(64) = null,
    @address_1 nvarchar(255) = null,
    @address_2 nvarchar(255) = null,
    @city nvarchar(130) = null,
    @state nvarchar(2) = null,
    @postal_code nvarchar(32) = null,
    @country varchar(75) = null,
    @vendor_id int = null,
    @vendor_customer_code varchar(100) = null,
    @partner_id int = null,
    @opt_in int = null,
    @salesforce_account_id char(18) = null,
    @salesforce_contact_id char(18) = null,
    @transaction_user varchar(20) = null,
    @customer_id_input int = null,
    @company_id_input int = null,
    @customer_id int OUTPUT
)
AS
    /*
        DATE        AUTHOR      REMARKS
        2014-02-10  esmart      Initial creation.    
        2014-03-21  esmart      Address update fix
        2014-04-09  esmart      Add partner_id to vendor_customer insert
        2014-05-15  esmart      Additional matching on update customer
        2014-06-03
        2014-10-21  esmart      Fix matching on company with SFDC account 3.3.3
        2015-01-24  esmart      Add email_domain to customer_email insert
        2015-03-05  cnovac      Added call to usp_company_type_insert to insert company types if not already there
        2015-04-21  esmart      Update 3.2 to update email address when matching vendor customer code (partner service)
        2015-06-15  esmart      Add @customer_id_input to allow updates to specific customer
        2015-09-24  esmart      Fix company_name update, Salesforce ID updates, and vendor_customer_code logic.
        2016-03-25  mrobbins    Added usp_customer_update_customer_locale call
        2016-09-20  esmart      Skip 2.7.2) Single match is @customer_id is not null
        2016-10-04  esmart      @salesforce_account_id with no @salesforce_contact_id
        2017-08-22  esmart      Remove print
        2018-05-23  jnavarra    Log input parameters as JSON for audit and gathering test data
        2018-06-21  jnavarra    Update log upon completion to capture end time
        2018-10-04  esmart      company_type_name
        2019-01-11  esmart      New company match logic
        2019-08-14  jnavarra    Address update enhancements
        2019-08-22  esmart      Fix defect with company_company.company_type_id insert
        2019-09-16  jnavarra    Primary/secondary address handling
        2019-10-11  esmart      Performance fix
        2020-06-10  jnavarra    Modify for new company_name
		2020-09-02	wbarton		Updating the email_domain_type_id logic to default to business if currently undefined and we're inserting a company record

        DESCRIPTION
        insert/update customer
    */

    set nocount on

    DECLARE @customer_count int,
            @vendor_customer_id int,
            @customer_address_id int,
            @phone_type_id int,
            @address_type_id int,
            @address_class_id int,
            @country_id int,
            @customer_company_id int,
            @company_id int,
            @company_type_id tinyint,
            @transaction_date datetime,
            @email_domain varchar(100),
            @email_domain_type_id tinyint,
            @customer_update_json_id int,
            @partner_company_id int,
            @address_exception_json nvarchar(max),
            @domain_exception_json nvarchar(max),
            @match_exception_json nvarchar(max),
            @company_match_exception int = 0,
            @response_code int,
            @messa
ge varchar(100)

    begin try

        select @transaction_date = getdate();
        if @transaction_user is null begin select @transaction_user = suser_sname() end

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 0.) customer_update_json
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 0.1) Convert input parameters to JSON
        DECLARE @json NVARCHAR(MAX) = (SELECT @customer_email AS customer_email,@first_name AS first_name,@last_name AS last_name,@company_name AS company_name,@company_type_name AS company_type_name,@phone_number AS phone_number,@address_1 AS address_1,@address_2 AS address_2,@city AS city,@state AS state,@postal_code AS postal_code,@country AS country,@vendor_id AS vendor_id,@vendor_customer_code AS vendor_customer_code,@partner_id AS partner_id,@opt_in AS opt_in,@salesforce_account_id AS salesforce_account_id,@salesforce_contact_id AS salesforce_contact_id,@transaction_user AS transaction_user,@customer_id_input AS customer_id_input,@company_id_input as company_id_input    
        for JSON PATH, WITHOUT_ARRAY_WRAPPER)

        -- 0.2) Save JSON
        insert into dbo.customer_update_json (customer_update_json, application_origin, insert_date, insert_by) 
        values (@json, left(app_name(),250), @transaction_date, LEFT(SYSTEM_USER, 50))

        set @customer_update_json_id = SCOPE_IDENTITY()

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
        -- 1.1)  select customers that match @customer_email
        declare @customers table (customer_id int, salesforce_contact_id varchar(18), first_name nvarchar(225), last_name nvarchar(225), opt_in int, customer_email_id int, customer_email varchar(100), email_domain varchar(100), email_domain_type_id tinyint,  customer_company_id int, cc_company_name nvarchar(255), cc_company_type_id tinyint, company_id int, company_name nvarchar(255), company_type_id tinyint, salesforce_account_id varchar(18),  customer_phone_id int, phone_number varchar(64), customer_address_id int, address_1 nvarchar(255), address_2 nvarchar(255), city nvarchar(130), state nvarchar(2), postal_code nvarchar(32), country_id int, country varchar(75), address_type_id int, vendor_id int, vendor_customer_id int, vendor_customer_code varchar(100), partner_id int)     
        
        insert into @customers (customer_id, salesforce_contact_id, first_name, last_name, opt_in, customer_email_id, customer_email, email_domain, email_domain_type_id, customer_company_id, cc_company_name, cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, customer_address_id, address_1, address_2, city, state, postal_code, country_id, country, address_type_id, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
        select c.customer_id, c.salesforce_contact_id, c.first_name, c.last_name, c.opt_in, e.customer_email_id, e.customer_email, e.email_domain, ce.email_domain_type_id, cc.customer_company_id, cc.company_name, cc.company_type_id, co.company_id, co.company_name, co.company_type_id, co.salesforce_account_id, p.customer_phone_id, p.phone_number, a.customer_address_id, a.address_1, a.address_2, a.city, a.state, a.postal_code, a.country_id, lc.description, a.address_type_id, vc.ve
ndor_id, vc.vendor_customer_id, vc.vendor_customer_code, vc.partner_id
        from customer_email e with (nolock)
        inner join customer c with (nolock)
            on e.customer_id = c.customer_id
        left join customer_email_domain ce with (nolock)
            on e.email_domain = ce.email_domain
        left join vendor_customer vc with (nolock)
            on c.customer_id = vc.customer_id
        left join customer_company cc with (nolock)
            on c.customer_id = cc.customer_id
        left join company co with (nolock)
            on cc.company_id = co.company_id
        left join customer_phone p with (nolock)
            on c.customer_id = p.customer_id and p.phone_type_id = 1
        left join customer_address a with (nolock)
            on c.customer_id = a.customer_id and a.address_type_id = 1 and a.address_status_id = 1
        left join lu_countries lc with (nolock)
            on a.country_id = lc.country_id
        where e.customer_email = @customer_email and e.email_status_id = 1

        -- 1.2) set parameters
        select @phone_type_id = 1, @address_type_id = 1

        if @vendor_id = 0 or @vendor_id is null begin select @vendor_id = 1 end
        if @partner_id = 0 begin select @partner_id = null end
        if @company_name = '' begin select @company_name = null end
        if @salesforce_account_id = '' begin select @salesforce_account_id = null end
        if @salesforce_contact_id = '' begin select @salesforce_contact_id = null end
        if @opt_in is null begin select @opt_in = 1 end

        select @country_id = country_id from lu_countries with (nolock) where description = @country
        if @country_id is null begin select @country_id = country_id from lu_countries with (nolock) where iso3 = @country end
        if @country_id is null begin select @country_id = country_id from lu_countries with (nolock) where iso = @country end
        
        select @company_type_id = company_type_id from company_type with (nolock) where company_type_name = @company_type_name
        if @company_type_id is null begin select @company_type_id = 14 end
            
        -- 1.3) email_domain
        select @email_domain = SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

        select @email_domain_type_id = ed.email_domain_type_id
        from customer_email_domain ed
        where ed.email_domain = @email_domain

        if @email_domain_type_id is null and @email_domain is not null
            begin
                select @email_domain_type_id = 0

                insert into customer_email_domain (email_domain, email_domain_type_id)
                values(@email_domain,0)
            end
            
        -- 1.3) @salesforce_contact_id
        --select @salesforce_contact_id as salesforce_contact_id
        
        if @salesforce_contact_id is not null
            begin
                if exists (select customer_id from @customers where salesforce_contact_id = @salesforce_contact_id)
                    -- 1.3.1) match salesforce_contact_id
                    begin
                        -- print '1.3.1) match salesforce_contact_id'
                        select @customer_id = customer_id from customer with (nolock) where salesforce_contact_id = @salesforce_contact_id
                    end
                else 
                    -- 1.3.2) no match salesforce_contact_id (most likely change to email in SFDC.contact)
                    begin
                        -- print '1.3.2) no match salesforce_contact_id'
                        select @customer_id = customer_id from customer where salesforce_contact_id = @salesforce_contact_id

                        if @customer_id is not null
                        -- 1.3.2.1) add customer to @customers
                            begin
                                insert into @customers (customer_id, salesforce_contact_id, firs
t_name, last_name, opt_in, customer_email_id, customer_email, customer_company_id, cc_company_name, cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, customer_address_id, address_1, address_2, city, state, postal_code, country_id, country, address_type_id, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
