               --  select '4.) New customer' as Step

                -- 4.1) customer
                insert into customer (first_name, last_name, opt_in, salesforce_contact_id, insert_date, insert_by, modified_date, modified_by)
                values (@first_name, @last_name, @opt_in, @salesforce_contact_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                
                select @customer_id = scope_identity()        

                -- 4.2) customer_email
                if @customer_email is not null
                    begin
                        select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))
                        
                        insert into customer_email (customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
                        values (@customer_id, @customer_email, 1, @t
ransaction_date, @transaction_user, @transaction_date, @transaction_user, @email_domain)
                    end

                -- 4.3) customer_company
                if @company_name is not null and @customer_id is not null
                    begin
                        -- 4.3.1) salesforce company
                        if @company_id is not null
                            begin
                                -- print '4.3.1) salesforce company'
                                insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)
                                select @customer_id, company_name, company_id, company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user
                                from company
                                where company_id = @company_id
                            end
                        -- 4.3.2) standard customer company
                        else
                            begin
                                -- print '4.3.2) standard customer company'
                                insert into customer_company (customer_id, company_name, company_type_id, insert_date, insert_by, modified_date, modified_by)
                                select @customer_id, @company_name, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user
                            end
                    end

                -- 4.4) vendor_customer
                -- 4.4.1) generate new code
                if @vendor_customer_code is null
                    begin
                        -- print '4.4.1) vendor_customer'
                        exec usp_customer_generate_customer_code @vendor_customer_code output
                        --select @vendor_customer_code = @customer_code
                    end
                
                -- 4.4.2) insert vendor_customer
                insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id)
                values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @partner_id)
            
                -- 4.5) customer_phone
                if @phone_number is not null and @phone_number <> ''
                    begin
                        -- print '4.5) customer_phone'
                        insert into customer_phone (customer_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
                        values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                    end

                -- 4.6) customer_address
                if @country_id is not null
                    begin
                        -- print '4.6) customer_address'
                        select @city = isnull(@city,'')
                        select @state = isnull(@state,'')
                        select @postal_code = isnull(@postal_code,'')

                        insert into customer_address (customer_id, address_type_id, address_1, address_2, city, state, postal_code, country_id, insert_date, insert_by, modified_date, modified_by)
                        values (@customer_id, @address_type_id, @address_1, @address_2, @city, @state, @postal_code, @country_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                    end

                select @customer_address_id = scope_identity()
            
                -- 4.7) customer_locale
                exec usp_customer_update_customer_locale @customer_id

                -- 4.8) partner_company
                if @partner_id is not null and @company_id is not null
                    begin

                        select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

                        if @partner_company_id is null
                            begin
                                insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
                                values(@partner_id,@vendor_customer_code,@company_name,@company_id)    
                            end
                        else
                            begin
                                update partner_company
                                set partner_customer_code = @vendor_customer_code
                                where partner_company_id = @partner_company_id and partner_customer_code <> @vendor_customer_code
                            end                
                    end


                -- 4.9) Update the log before exiting
                UPDATE dbo.customer_update_json SET complete_date = GETDATE() WHERE customer_update_json_id = @customer_update_json_id;

                return    
            end

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 5.) Update customer
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       else
            begin
                -- 5.1) update customer
                -- select ' -- 5.1) update customer' as step
                
                if exists (select customer_id 
                            from @customers
                            where customer_id = @customer_id 
                                and (first_name <> @first_name or last_name <> @last_name or opt_in <> @opt_in or 
                                    (first_name is null and @first_name is not null) or (last_name is null and @last_name is not null) or
                                        (salesforce_contact_id <> @salesforce_contact_id or 
                                        (salesforce_contact_id is null and @salesforce_contact_id is not null))
                                    )
                            )
                    begin
                        -- 5.1.1) insert customer_audit
                        insert into customer_audit (customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, audit_date, audit_by)
                        select customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, @transaction_date, @transaction_user
                        from customer with (nolock)
                        where customer_id = @customer_id

                        -- 5.1.2) update customer
                        update customer
                        set    first_name = @first_name, last_name = @last_name, opt_in = @opt_in, modified_date = @transaction_date, modified_by = @transaction_user, 
                            salesforce_contact_id = case when @salesforce_contact_id is null then salesforce_contact_id else @salesforce_contact_id end
                        where customer_id = @customer_id
                    end

                -- 5.2) update customer_email
                if exists (select customer_email_id from customer_email where customer_id = @customer_id and customer_email <> @customer_email and email_status_id = 1)
                    begin
                        -- print '5.2 update customer_email'
                        update customer_email 
                        set email_status_id = 0, modified_date = @transactio
n_date, modified_by = @transaction_user
                        where customer_id = @customer_id and email_status_id = 1

                        select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

                        insert into customer_email(customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
                        values(@customer_id, @customer_email, 1, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @email_domain)
                    end

                -- 5.3) customer_company
                if @company_name is not null
                    begin
                        declare @current_company_name nvarchar(255), @current_company_id int, @current_company_type_id tinyint
                        --select '5.3) customer_company'
                        select @customer_company_id = customer_company_id, @current_company_name = cc_company_name, @current_company_type_id = cc_company_type_id, @current_company_id = company_id from @customers where customer_id = @customer_id

                        -- 5.3.1) insert customer_company
                        if @customer_company_id is null
                            begin
                                -- select '-- 5.3.1) insert customer_company'
                                insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)    
                                values(@customer_id, @company_name, @company_id, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.3.2) update customer_company
                        else
                            begin
                                --select @customer_company_id, @current_company_id, @current_company_name, @current_company_type_id, @company_id, @company_name, @company_type_id
                                if (@current_company_name <> @company_name or 
                                    (@current_company_id is null and @company_id is not null) or 
                                    (@current_company_type_id is null or @current_company_type_id <> @company_type_id)) 
                                    begin
                                        -- select '-- 5.3.2) update customer_company'
                                        insert into customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id)
                                        select customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id from customer_company where customer_company_id = @customer_company_id

                                        update customer_company
                                        set company_name = @company_name, 
                                            company_id = case 
                                                            when @company_id is null then company_id
                                                            else @company_id
                                                        end, 
                                            company_type_id = @company_type_id, modified_date = @transaction_date, modified_by = @transaction_user
                                        where customer_company_id = @customer_company_id
                                    end
                            end
                    end
            
                -- 5.4) vendor_customer
                if @vendor_customer_id is null -- and (select count(*) from vendor_customer where vendor_id = @vendor_id and customer_id = @customer_id) = 0
                    begin
                   
     -- print '5.4.1) insert new vendor_customer' 
                        
                        -- 5.4.1) insert new vendor_customer
                        if @vendor_customer_code is null
                            begin
                                -- 5.4.1.1) insert new
                                exec usp_customer_generate_customer_code @vendor_customer_code output
                            end
                        
                        insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id)
                        values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @partner_id)

                        -- 5.4.1.2) archive old 
                        if exists (select count(*) from vendor_customer where customer_id = @customer_id and vendor_customer_code <> @vendor_customer_code )
                            begin
                                insert into vendor_customer_audit(vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id)
                                select vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id
                                from vendor_customer with (nolock)
                                where customer_id = @customer_id and (vendor_customer_code <> @vendor_customer_code or vendor_id <> @vendor_id)

                                delete from vendor_customer
                                where customer_id = @customer_id and (vendor_customer_code <> @vendor_customer_code or vendor_id <> @vendor_id)
                            end
                    end
                else 
                    -- 5.4.2) update vendor_customer
                    begin
                        if @vendor_customer_code is not null and exists (select vendor_customer_id from vendor_customer where vendor_customer_id = @vendor_customer_id and (vendor_customer_code <> @vendor_customer_code or (partner_id <> @partner_id or (partner_id is null and @partner_id is not null))))
                            begin
                                insert into vendor_customer_audit(vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id)
                                select vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id
                                from vendor_customer with (nolock)
                                where vendor_id = @vendor_id and customer_id = @customer_id

                                update vendor_customer
                                set vendor_customer_code = @vendor_customer_code, partner_id = @partner_id, modified_date = @transaction_date, modified_by = @transaction_user
                                where vendor_id = @vendor_id and customer_id = @customer_id

                                --if exists (select count(*) from vendor_customer where customer_id = @customer_id and vendor_customer_code <> @vendor_customer_code )
                                --    begin    
                                --        delete from vendor_customer
                                --        where customer_id = @customer_id and vendor_customer_code <> @vendor_customer_code
                                --    end
                            end
                    end

                -- 5.5) customer_phone
                if @phone_number is not null and @phone_number <> ''
                    begin
                        if not exists (select phone_number from @customers where customer_id = @customer_id)
                        -- 5.5.1) insert phone
             
               begin
                                -- print '5.5.1 insert phone'
                                insert into customer_phone (customer_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
                                values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.5.2) update phone
                        else if (select phone_number from @customers where customer_id = @customer_id) <> @phone_number
                            begin
                                -- print '5.5.2) update phone'
                                update customer_phone
                                set phone_number = @phone_number, modified_date = @transaction_date, modified_by = @transaction_user
                                where customer_id = @customer_id and phone_type_id = @phone_type_id
                            end
                    end            



                -- 5.6) customer_address
                declare @current_address_1 nvarchar(255),@current_address_2 nvarchar(255),@current_city nvarchar(130),@current_state nvarchar(2),@current_postal_code nvarchar(32),@current_country_id tinyint

                -- 5.6.1) select current address
                select @customer_address_id = customer_address_id, @current_address_1 = address_1, @current_address_2 = address_2, @current_city = city, @current_state = state, @current_postal_code = postal_code, @current_country_id = country_id from @customers where customer_id = @customer_id

                set @address_1 = isnull(@address_1, '')
                set @address_2 = isnull(@address_2, '')
                set @city = isnull(@city, '')
                set @state = isnull(@state, '')
                set @postal_code = isnull(@postal_code, '')
                set @current_address_1 = isnull(@current_address_1, '')
                
                if @customer_address_id is not null and @country_id is not null
                    begin
                        -- Do no harm address update
                        if dbo.fn_should_update_address(@current_address_1, @current_address_2, @current_city, @current_state, @current_postal_code, @current_country_id, @address_1, @address_2, @city, @state, @postal_code, @country_id) = 1
                            begin
                                insert into customer_address (customer_id, address_type_id, address_1, address_2, city, state, postal_code, country_id, insert_date, insert_by, modified_date, modified_by)
                                select @customer_id, @address_type_id, @address_1, @address_2, @city, @state, @postal_code, @country_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user

                                select @customer_address_id = SCOPE_IDENTITY()

                                update customer_address
                                set address_status_id = 2, modified_date = @transaction_date, modified_by = @transaction_user
                                where customer_id = @customer_id and customer_address_id <> @customer_address_id and address_status_id <> 2
                            end
                    end
                else if @customer_address_id is null and @country_id is not null
                    begin
                        -- 5.6.2) insert customer address
                        --print '5.6.2) insert customer address'
                        insert into customer_address (customer_id, address_type_id, address_1, address_2, city, state, postal_code, country_id, insert_date, insert_by, modified_date, modified_by)
                        values (@customer_id, @address_type_id, @address_1, @address_2, @city, @state, @postal_code, @country_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
        
            end


                -- 5.7) partner_company
                if @partner_id is not null and @company_id is not null
                    begin
                        select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

                        if @partner_company_id is null
                            begin
                                insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
                                values(@partner_id,@vendor_customer_code,@company_name,@company_id)    
                            end
                        else
                            begin
                                update partner_company
                                set partner_customer_code = @vendor_customer_code
                                where partner_company_id = @partner_company_id and partner_customer_code <> @vendor_customer_code
                            end
                    end


                -- 5.8) Update the log before exiting
                UPDATE dbo.customer_update_json SET complete_date = GETDATE() WHERE customer_update_json_id = @customer_update_json_id;
                return
            end

    end try
    begin catch

        set @response_code = -200
        set @message = case when @message is null then 'select failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;
    

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_customer_service_sap]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_customer_insert_customer_service_sap]
(
    @customer_email VARCHAR(100) = NULL,
    @first_name NVARCHAR(225) = NULL,
    @last_name NVARCHAR(225) = NULL,
    @company_name NVARCHAR(255) = NULL,
    @company_type_name VARCHAR(50) = NULL,
    @phone_number VARCHAR(64) = NULL,
    @address_1 NVARCHAR(255) = NULL,
    @address_2 NVARCHAR(255) = NULL,
    @city NVARCHAR(130) = NULL,
    @state NVARCHAR(2) = NULL,
    @postal_code NVARCHAR(32) = NULL,
    @country VARCHAR(75) = NULL,
    @vendor_id INT = NULL,
    @vendor_customer_code VARCHAR(100) = NULL,
    @partner_id INT = NULL,
    @opt_in INT = NULL,
    @salesforce_account_id CHAR(18) = NULL,
    @salesforce_contact_id CHAR(18) = NULL,
    @transaction_user VARCHAR(20) = NULL,
    @customer_id_input INT = NULL,
    @company_id_input INT = NULL,
    @customer_id INT = NULL OUTPUT,
    @input_json NVARCHAR(2000) = NULL,
    @output_json NVARCHAR(2000) = NULL OUTPUT
	   
)
AS
    /*
        DATE        AUTHOR      REMARKS
        2022-06-06  jberry      Initial creation        

        DESCRIPTION
        ALM 1345:  This will create a new sap customer and company if a company_id is not passed.  
			-If a company_id is passed only a customer will be created.  
			-If the customer is a duplicate for that company then a customer update will happen.
    */

    set nocount on

    DECLARE @customer_count int,
            @vendor_customer_id int,
            @customer_address_id int,
            @phone_type_id int,
            @address_google_place_id varchar(60),
            @address_location geography,
            @address_subpremise nvarchar(255),
            @country_id int,
            @customer_company_id int,
            @company_id int,
            @company_type_id tinyint,
            @transaction_date datetime = getdate(),
            @email_domain varchar(100),
            @email_domain_type_id tinyint,
            @customer_update_json_id int,
            @partner_company_id int,
            @address_exception_json nvarchar(2000),
            @domain_exception_json nvarchar(2000),
            @match_exception_json nvarchar(2000),
            @company_match_exception int = 0,
            @debug_input_parameters bit = null,
			@vat_id varchar(20),
			@partner_customer_code nvarchar(100),
			@customer_json nvarchar(2000),
			@company_json nvarchar(2000),
			@partner_json nvarchar(2000),
            @response_code int,
            @message varchar(100),
			@max tinyint, --this and below are vars for address insert/update loop
			@l_temp_id int = 1, 
			@l_address_type_id int, 
			@l_address_1 nvarchar(255), 
			@l_address_2 nvarchar(255), 
			@l_city nvarchar(130), 
			@l_state nvarchar(50), 
			@l_postal_code nvarchar(32),
			@l_country_id smallint,
			@l_customer_address_message nvarchar(50)

	declare @customer_address table (temp_id int identity(1,1), customer_address_id int, address_1 nvarchar(255), address_2 nvarchar(255), city nvarchar(130), state nvarchar(50), postal_code nvarchar(32), 
		country nvarchar(75), country_id smallint, address_type_id int, google_place_id varchar(60), location geography, subpremise nvarchar(255), message nvarchar(50))
		
	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 0.) customer_update_json
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if isjson(@input_json) = 1
			begin
				-- 0.1.1) Parse JSON for input parameters
				if json_query(@input_json, '$.customer') is not null
					begin
						-- 0.1.1.1) Parse new JSON schema
						--      Add new parameters here
						select
							@customer_id_input = cusj.customer_id,
							@customer_email = cusj.customer_email,
							@first_name = cusj.first_name,
							@last_name = cusj.last_name,
							@phone_number = cusj.phone_number,
							@opt_in = cusj.opt_in,
							@vendor_id = cusj.vendor_id,
							@vendor_customer_code = cusj.vendor_customer_code,
							@salesforce_contact_id = cusj.salesforce_contact_id
						from dbo.fn_customer_json_to_table(@input_json) cusj

						if json_query(@input_json, '$.company') is not null
							begin
								select
									@company_id_input = comj.company_id,
									@company_name = comj.company_name,
									@company_type_name = comj.company_type_name,
									@company_type_id = comj.company_type_id,
									@salesforce_account_id = comj.salesforce_account_id,
									@vat_id = comj.vat_id
								from dbo.fn_company_json_to_table(@input_json) comj
							end
						if json_query(@input_json, '$.partner') is not null
							begin
								select
									@partner_id = pj.partner_id,
									@partner_customer_code = pj.partner_customer_code
								from dbo.fn_partner_json_to_table(@input_json) pj
							end

						-- 0.1.1.2) parse customer_address object into table variable and validate addresses; set variable to billing address fields, or shipping if no billing
						if json_query(@input_json, '$.customer.address.bill_to') is not null
							begin
								insert into @customer_address (address_1, address_2, city, state, postal_code, country, address_type_id, google_place_id)
								--, google_place_id, location, subpremise)
								select ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, ca.country, 1, ca.google_place_id
										--case when ca.lat >= -90.0 and ca.lat <= 90.0 and ca.lng >= -180.0 and ca.lng <= 180.0 
										--then geography::Point(ca.lat, ca.lng, 4326) 
										--else null end, ca.subpremise
								from openjson(@input_json, '$.customer.address.bill_to') with (
												address_1 nvarchar(255) '$.address_1',
												address_2 nvarchar(255) '$.address_2',
												city nvarchar(130) '$.city',
												state nvarchar(50) '$.state',
												postal_code nvarchar(32) '$.postal_code',
												country nvarchar(75) '$.country',
												google_place_id varchar(60) '$.google_place_id',
												lat varchar(20) '$.location.lat',
												lng varchar(20) '$.location.lng',
												subpremise nvarchar(255) '$.location.subpremise'
												) ca

							end
						if json_query(@input_json, '$.customer.address.ship_to') is not null
							begin 
								insert into @customer_address (address_1, address_2, city, state, postal_code, country, address_type_id, google_place_id)
								--, google_place_id, location, subpremise)
								select ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, ca.country, 2, ca.google_place_id
										--case when ca.lat >= -90.0 and ca.lat <= 90.0 and ca.lng >= -180.0 and ca.lng <= 180.0 
										--then geography::Point(ca.lat, ca.lng, 4326) 
										--else null end, ca.subpremise
								from openjson(@input_json, '$.customer.address.ship_to') with (
												address_1 nvarchar(255) '$.address_1',
												address_2 nvarchar(255) '$.address_2',
												city nvarchar(130) '$.city',
												state nvarchar(50) '$.state',
												postal_code nvarchar(32) '$.postal_code',
												country nvarchar(75) '$.country',
												google_place_id varchar(60) '$.google_place_id',
												lat varchar(20) '$.location.lat',
												lng varchar(20) '$.location.lng',
												subpremise nvarchar(255) '$.location.subpremise'
												) ca

							end
							
					end
				else
					begin
						-- 0
.1.1.3) Parse old JSON schema - Flat JSON object
						--      Do not add new parameters here
						select @customer_id_input = j.customer_id, @customer_email = j.customer_email, @first_name = j.first_name, @last_name = j.last_name, @phone_number = j.phone_number, @opt_in = j.opt_in, 
							@vendor_id = j.vendor_id, @vendor_customer_code = j.vendor_customer_code, @partner_id = j.partner_id, @company_id_input = j.company_id, @company_name = j.company_name, 
							@company_type_name = j.company_type_name, @salesforce_account_id = j.salesforce_account_id, @salesforce_contact_id = j.salesforce_contact_id, @transaction_user = j.transaction_user, 
							@debug_input_parameters = j.debug_input_parameters
						from openjson(@input_json)
							with (customer_email varchar(100) '$.customer_email', first_name nvarchar(225) '$.first_name', last_name nvarchar(225) '$.last_name', company_name nvarchar(255) '$.company_name', 
							company_type_name varchar(50) '$.company_type_name', phone_number varchar(64) '$.phone_number', vendor_id int '$.vendor_id', vendor_customer_code varchar(100) '$.vendor_customer_code', 
							partner_id int '$.partner_id', opt_in int '$.opt_in', salesforce_account_id char(18) '$.salesforce_account_id', salesforce_contact_id char(18) '$.salesforce_contact_id', 
							transaction_user varchar(20) '$.transaction_user', customer_id int '$.customer_id_input', company_id int '$.company_id_input', debug_input_parameters bit '$.debug_input_parameters') j

						-- 0.1.1.4) parse address fields separately into table var
						insert into @customer_address (address_1, address_2, city, state, postal_code, country, address_type_id)
						select ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, ca.country, 1-- old json schema always uses billing
						from openjson(@input_json)
							with (address_1 nvarchar(255) '$.address_1', address_2 nvarchar(255) '$.address_2', city nvarchar(130) '$.city', state nvarchar(50) '$.state', postal_code nvarchar(32) '$.postal_code', 
							country varchar(75) '$.country') ca

					end
			end
		else
			begin
				-- 0.1.2) Convert non-JSON input parameters to JSON
				--      Do not add new parameters here
				select @customer_json = dbo.fn_customer_variables_to_json(@customer_email, @customer_id_input, @first_name, @last_name, @phone_number, @address_1, @address_2, @city, @state, 
										@postal_code, @country, default, default, default, default, default, default, default, default, default, default, default, default, default, 
										default, @vendor_id, @vendor_customer_code, @opt_in, @salesforce_contact_id, default)
						, @company_json = dbo.fn_company_variables_to_json(@company_id_input, @company_name, @company_type_name, default, @salesforce_account_id, @vat_id, default)
						, @partner_json = dbo.fn_partner_variables_to_json(@partner_id, default, default)

				select @input_json = (select json_query(@customer_json, '$.customer') as [customer], json_query(@company_json, '$.company') as [company], 
											json_query(@partner_json, '$.partner') as [partner], @transaction_user as [transaction_user] for json path, without_array_wrapper)

				-- 0.1.3) validate address inputs and insert row to table var
				insert into @customer_address (address_1, address_2, city, state, postal_code, country, address_type_id)
				select @address_1, @address_2, @city, @state, @postal_code, @country, 1-- input variables always use billing

			END

		if @customer_email is null or @customer_email = ''
			begin
				set @response_code = -201
				set @message = 'Required parameter "customer_email" not provided'
				return
			end


		-- 0.3) Save JSON
		insert into dbo.customer_update_json (customer_update_json, application_origin, insert_date, insert_by) 
		values (@input_json, left(app_name(),250), @transaction_date, LEFT(SYSTEM_USER, 50))

		set @customer_update_json_id = SCOPE_IDENTITY()

	-- -----------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @transaction_user is null begin select @transaction_user = suser_sname() end
        
		-- 1.1) set parameters
		select @phone_type_id = 1

		if @vendor_id = 0 or @vendor_id is null begin select @vendor_id = 1 end
		if @partner_id = 0 begin select @partner_id = null end
		if @company_name = '' begin select @company_name = null end
		if @salesforce_account_id = '' begin select @salesforce_account_id = null end
		if @salesforce_contact_id = '' begin select @salesforce_contact_id = null end
		if @opt_in is null begin select @opt_in = 1 end

		-- 1.2) validate passed in company_type_id; set from company_type_name if not passed in or invalid; set to 14 if neither found
		if not exists (select 1 from company_type with (nolock) where company_type_id = @company_type_id)
			begin
				select @company_type_id = isnull(company_type_id, 14) from company_type with (nolock) where company_type_name = @company_type_name
			end

		-- 1.3) select billing address fields, or shipping if no billing
		if exists (select 1 from @customer_address ca)
		begin

			update @customer_address
			set address_1 = va.address_1,
			address_2 = va.address_2,
			city = va.city,
			state = va.state_id,
			postal_code = va.postal_code,
			country = va.country,
			country_id = va.country_id
			from @customer_address ca
			cross apply	dbo.fn_clean_validate_address(ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, ca.country, null) va


			select top 1 @address_1 = ca.address_1,
				@address_2 = ca.address_2,
				@city = ca.city,
				@state = ca.state,
				@postal_code = ca.postal_code,
				@country_id = ca.country_id,
				@country = ca.country,
				@address_google_place_id = ca.google_place_id,
				@address_location = ca.location,
				@address_subpremise = ca.subpremise
			from @customer_address ca
			order by ca.address_type_id asc
       
		end

		-- 1.4) email_domain
		select @email_domain = SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

		select @email_domain_type_id = ed.email_domain_type_id
		from customer_email_domain ed
		where ed.email_domain = @email_domain

		if @email_domain_type_id is null and @email_domain is not null
			begin
				select @email_domain_type_id = 0

				insert into customer_email_domain (email_domain, email_domain_type_id)
				values(@email_domain,0)
			end   

		-- 1.5) check to see if Company_Id is passed in JSON, if so get company name
        IF @company_id_input IS NOT NULL
            BEGIN
                SELECT @company_id = company_id
					, @company_name = CASE WHEN @company_name IS NULL THEN company_name ELSE @company_name END
                    ,@company_type_id = company_type_id
				FROM company 
				WHERE company_id = @company_id_input
            END

		-- 1.6) Get customer matches

        declare @customers table (customer_id int, salesforce_contact_id varchar(18), first_name nvarchar(225), last_name nvarchar(225), opt_in int, customer_email_id int, customer_email varchar(100), 
			email_domain varchar(100), email_domain_type_id tinyint,  customer_company_id int, cc_company_name nvarchar(255), cc_company_type_id tinyint, company_id int, company_name nvarchar(255), 
			company_type_id tinyint, salesforce_account_id varchar(18),  customer_phone_id int, phone_number varchar(64), vendor_id int, vendor_customer_id int, vendor_customer_code varchar(100), partner_id int)     
        
        insert into @customers (customer_id, salesforce_contact_id, first_name, last_name, opt_in, customer_email_id, customer_email, email_do
main, email_domain_type_id, customer_company_id, cc_company_name, 
			cc_company_type_id, company_id, company_name, company_type_id, salesforce_account_id, customer_phone_id, phone_number, vendor_id, vendor_customer_id, vendor_customer_code, partner_id)
        select c.customer_id, c.salesforce_contact_id, c.first_name, c.last_name, c.opt_in, e.customer_email_id, e.customer_email, e.email_domain, ce.email_domain_type_id, cc.customer_company_id, cc.company_name, 
			cc.company_type_id, co.company_id, co.company_name, co.company_type_id, co.salesforce_account_id, p.customer_phone_id, p.phone_number, vc.vendor_id, vc.vendor_customer_id, vc.vendor_customer_code, vc.partner_id
        from customer_email e with (nolock)
        inner join customer c with (nolock)
            on e.customer_id = c.customer_id
        left join customer_email_domain ce with (nolock)
            on e.email_domain = ce.email_domain
        left join vendor_customer vc with (nolock)
            on c.customer_id = vc.customer_id
        left join customer_company cc with (nolock)
            on c.customer_id = cc.customer_id
        left join company co with (nolock)
            on cc.company_id = co.company_id
        left join customer_phone p with (nolock)
            on c.customer_id = p.customer_id and p.phone_type_id = 1
        where e.email_status_id = 1
		AND e.customer_email = @customer_email 
		AND co.company_id = @company_id
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) new company
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
 
		IF @company_id IS NULL
			BEGIN
				-- 2.1) insert company
				IF @company_name IS NULL OR @company_type_id IS NULL						
					BEGIN
						SELECT 'company name and company type id are required'
						RETURN
					END
				ELSE
					BEGIN
				
						-- 2.1.1 - insert
						INSERT INTO company (company_name, last_modified_date, company_type_id, company_name_clean,salesforce_account_id)
						SELECT @company_name, GETDATE(), @company_type_id, dbo.fn_clean_company_name(@company_name),@salesforce_account_id

						SELECT @company_id = SCOPE_IDENTITY()

						EXEC dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type = 'Primary'

						-- 2.1.2 - email domain
						IF @email_domain IS NOT NULL
							BEGIN
								--If we're inserting a company record and the email domain type is currently undefined, default it to business and update accordingly on customer_email_domain
								IF @email_domain_type_id = 0 
									BEGIN
										SET @email_domain_type_id = 2

										UPDATE customer_email_domain
										SET email_domain_type_id = @email_domain_type_id
										WHERE email_domain = @email_domain
									END
                            
								INSERT INTO company_email_domain (company_id, email_domain, email_domain_type_id, protected, customers, insert_date)
								SELECT @company_id, @email_domain, @email_domain_type_id, 0 AS protected, 1 AS customers, GETDATE()
							END

						-- 2.1.2 - email domain
						EXEC dbo.usp_customer_update_company_address @company_id=@company_id, @address_1=@address_1, @address_2=@address_2, @city=@city, @state=@state, @postal_code=@postal_code, @country_id=@country_id
					END

				-- 2.2) company_vat
				IF @vat_id IS NOT NULL AND @vat_id <> '' AND EXISTS (SELECT 1 FROM lu_countries WHERE country_id = @country_id AND ISNULL(is_vat_eligible, 1) = 1)
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM company_vat WHERE company_id = @company_id AND country_id = @country_id)
					BEGIN
						INSERT INTO company_vat (company_id, vat_id, country_id)
						VALUES (@company_id, @vat_id, @country_id)
					END
					ELSE
				
	BEGIN
						INSERT INTO company_vat_audit (company_vat_id, company_id, country_id, vat_id, modified_date, modified_by, insert_date, insert_by)
						SELECT cv.company_vat_id, cv.company_id, cv.country_id, cv.vat_id, cv.modified_date, cv.modified_by, cv.insert_date, cv.insert_by 
						FROM company_vat cv
						WHERE cv.company_id = @company_id AND cv.country_id = @country_id AND cv.vat_id <> @vat_id

						IF @@rowcount > 0
						BEGIN
							UPDATE company_vat 
							SET vat_id = @vat_id,
								modified_date = @transaction_date,
								modified_by = @transaction_user
							WHERE company_id = @company_id
								AND country_id = @country_id
						end
					end
				end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3.) Customer match
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        
		if @company_id_input IS NOT NULL
			begin

				-- 3.1) get customer count
				select @customer_count = count(*) from @customers   

				-- 3.2) customer match with company data
				if @customer_count > 0 and @customer_id is null and @company_id is not null
					begin
						-- 3.2.1) single match on company_id
						if (select count(*) from @customers where company_id = @company_id) = 1
							begin
								select @customer_id = customer_id from @customers where company_id = @company_id
							end

						-- 3.2.2) case when we have duplicate customers with the same company
						else if (select count(*) from @customers where company_id = @company_id) > 1
							begin
								select @customer_id = max(customer_id) from @customers where company_id = @company_id
							end

						-- 3.2.3) find customer with matching company_name and no company_id
						if @customer_id is null
							begin
								select @customer_id = max(customer_id) from @customers c where c.company_id is null and c.company_name = @company_name
							end
                
						-- 3.2.4) find customer with no company_name and no company_id
						if @customer_id is null
							begin
								select @customer_id = max(customer_id) from @customers c where c.company_id is null and c.company_name is null
							end
					end    
					
				-- 3.3) vendor_customer_id
				if @vendor_customer_id is null
					begin
					select @vendor_customer_id = vendor_customer_id from vendor_customer where customer_id = @customer_id
					end
			end 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) New customer
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @customer_id is null
			begin

				-- 4.1) customer
				insert into customer (first_name, last_name, opt_in, salesforce_contact_id, insert_date, insert_by, modified_date, modified_by)
				values (@first_name, @last_name, @opt_in, @salesforce_contact_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                
				select @customer_id = scope_identity()        

				-- 4.2) customer_email
				if @customer_email is not null
					begin
						select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))
                        
						insert into customer_email (customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
						values (@customer_id, @customer_email, 1, @transaction_date, @transaction_user, @transa
ction_date, @transaction_user, @email_domain)
					end
                    
				-- 4.3) customer_company
				if @company_name is not null and @customer_id is not null
					begin							
							insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)
							select @customer_id, @company_name, @company_Id, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user
					end
                    
				-- 4.4) vendor_customer
				if @vendor_customer_code is null
				begin
					
					-- 4.4.1 create vendor customer
					EXEC usp_customer_generate_customer_code @vendor_customer_code output
					
					-- 4.4.2) insert vendor_customer
					insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
					values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user)

				END
                
				-- 4.5) customer_phone
				if @phone_number is not null and @phone_number <> ''
					begin
						insert into customer_phone (customer_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
						values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
					end
				
				-- 4.6) customer_address
				if exists (select 1 from @customer_address)
				
					-- 4.6.2 run through @customer_address table with while loop, executing usp_customer_update_customer_address for each address type
					begin
						select @max = (select max(temp_id) from @customer_address)

						while @max >= @l_temp_id
							begin
								select @l_address_type_id = ca.address_type_id, @l_address_1 = ca.address_1, @l_address_2 = ca.address_2, @l_city = ca.city, @l_state = ca.state, 
									@l_postal_code = ca.postal_code, @l_country_id = ca.country_id
								from @customer_address ca where ca.temp_id = @l_temp_id 

								if @@rowcount > 0
									begin
										exec usp_customer_update_customer_address @customer_id = @customer_id, @address_type_id = @l_address_type_id, @address_1 = @l_address_1, @address_2 = @l_address_2, 
											@city = @l_city, @state = @l_state, @postal_code = @l_postal_code, @country_id = @l_country_id, @transaction_user = @transaction_user, 
											@customer_address_id = @customer_address_id output, @message = @l_customer_address_message output
									end

								-- 4.6.2.1 update @customer_address_table with active customer_address_id for customer/type (from output of above)
								update @customer_address
								set customer_address_id = @customer_address_id,
									message = @l_customer_address_message
								where address_type_id = @l_address_type_id

								select @l_address_type_id = null, @l_address_1 = null, @l_address_2 = null, @l_city = null, @l_state = null, @l_postal_code = null, @l_country_id = null, 
										@customer_address_id = null, @l_temp_id = @l_temp_id + 1, @l_customer_address_message = NULL
                                        
							end
					end
          
				-- 4.7) customer_locale
				--exec usp_customer_update_customer_locale @customer_id

				-- 4.8) partner_company
				if @partner_id is not null and @company_id is not null and @partner_customer_code is not null and @partner_customer_code <> ''
					begin
						select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

						if @partner_company_id is null
							begin
								insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
								values (@partner_id, @partner_customer_code, @company_name, @company_id)    
							end
						else
							begin
								insert into partner_company_audit (partner_company_id, partner_id, part
ner_customer_code, company_name, company_id, insert_date, audit_date)
								select partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, @transaction_date 
								from partner_company 
								where partner_company_id = @partner_company_id

								if @@rowcount > 0 
								begin 
									update partner_company
									set partner_customer_code = @partner_customer_code,
										company_name = @company_name
									where partner_company_id = @partner_company_id
								end 
							end                
					end
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 5.) Update customer
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       else 
            begin
                -- 5.1) update customer                
                if exists (select customer_id 
                            from @customers
                            where customer_id = @customer_id 
                                and (first_name <> @first_name or last_name <> @last_name or opt_in <> @opt_in or 
                                    (first_name is null and @first_name is not null) or (last_name is null and @last_name is not null) or
                                        (salesforce_contact_id <> @salesforce_contact_id or 
                                        (salesforce_contact_id is null and @salesforce_contact_id is not null))
                                    )
                            )
                    begin
                        -- 5.1.1) insert customer_audit
                        insert into customer_audit (customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, audit_date, audit_by)
                        select customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, @transaction_date, @transaction_user
                        from customer with (nolock)
                        where customer_id = @customer_id

                        -- 5.1.2) update customer

                        update customer
                        set    first_name = @first_name, last_name = @last_name, opt_in = @opt_in, modified_date = @transaction_date, modified_by = @transaction_user, 
                            salesforce_contact_id = case when @salesforce_contact_id is null then salesforce_contact_id else @salesforce_contact_id end
                        where customer_id = @customer_id
                    end

                -- 5.2) update customer_email
				if @customer_email <> (select customer_email from customer_email where customer_id = @customer_id and email_status_id = 1)
                    begin
                        update customer_email 
                        set email_status_id = 0, modified_date = @transaction_date, modified_by = @transaction_user
                        where customer_id = @customer_id and email_status_id = 1

                        select @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,len(@customer_email))

                        insert into customer_email(customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
                        values(@customer_id, @customer_email, 1, @transaction_date, @transaction_user, @transaction_date, @transaction_user, @email_domain)
                    end

                -- 5.3) customer_company
                if @company_name is not null
                    begin
                        declare @curren
t_company_name nvarchar(255), @current_company_id int, @current_company_type_id tinyint
                        select @customer_company_id = customer_company_id, @current_company_name = cc_company_name, @current_company_type_id = cc_company_type_id, @current_company_id = company_id from @customers where customer_id = @customer_id

                        -- 5.3.1) insert customer_company
                        if @customer_company_id is null
                            begin
                                insert into customer_company (customer_id, company_name, company_id, company_type_id, insert_date, insert_by, modified_date, modified_by)    
                                values(@customer_id, @company_name, @company_id, @company_type_id, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.3.2) update customer_company
                        else
                            begin
                                --select @customer_company_id, @current_company_id, @current_company_name, @current_company_type_id, @company_id, @company_name, @company_type_id
                                if (@current_company_name <> @company_name or 
                                    (@current_company_id is null and @company_id is not null) or 
                                    (@current_company_type_id is null or @current_company_type_id <> @company_type_id)) 
                                    begin
                                        insert into customer_company_audit (customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id)
                                        select customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id from customer_company where customer_company_id = @customer_company_id

                                        update customer_company
                                        set company_name = @company_name, 
                                            company_id = case 
                                                            when @company_id is null then company_id
                                                            else @company_id
                                                        end, 
                                            company_type_id = @company_type_id, modified_date = @transaction_date, modified_by = @transaction_user
                                        where customer_company_id = @customer_company_id
                                    end
                            end
                    end
            
                -- 5.4) vendor_customer
                if @vendor_customer_id is null -- and (select count(*) from vendor_customer where vendor_id = @vendor_id and customer_id = @customer_id) = 0
                    begin                        
                        -- 5.4.1) insert new vendor_customer
                        if @vendor_customer_code is null
                            begin
                                -- 5.4.1.1) insert new
                                exec usp_customer_generate_customer_code @vendor_customer_code output
                            end
                        
                        insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
                        values (@vendor_id, @customer_id, @vendor_customer_code, @transaction_date, @transaction_user, @transaction_date, @transaction_user)

                    end
                else 
                    -- 5.4.2) update vendor_customer
                    begin
                        if @vendor_customer_code is not null
                            begin
                                insert into vendor_customer_audi
t(vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
                                select vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by
                                from vendor_customer with (nolock)
                                where vendor_customer_id = @vendor_customer_id and vendor_customer_code <> @vendor_customer_code

								if @@rowcount > 0
								begin

									update vendor_customer
									set vendor_customer_code = @vendor_customer_code, modified_date = @transaction_date, modified_by = @transaction_user
									where vendor_customer_id = @vendor_customer_id

								end
                            end
                    end

                -- 5.5) customer_phone
                if @phone_number is not null and @phone_number <> ''
                    begin
                        if not exists (select phone_number from @customers where customer_id = @customer_id)
                        -- 5.5.1) insert phone
                            begin
                                insert into customer_phone (customer_id, phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
                                values (@customer_id, @phone_type_id, @phone_number, @transaction_date, @transaction_user, @transaction_date, @transaction_user)
                            end
                        -- 5.5.2) update phone - the TOP is a temporary fix until we clean duplicates in customer_phone table
                        else if (select top (1) phone_number from @customers where customer_id = @customer_id) <> @phone_number
                            BEGIN 
                                update customer_phone
                                set phone_number = @phone_number, modified_date = @transaction_date, modified_by = @transaction_user
                                where customer_id = @customer_id and phone_type_id = @phone_type_id
                            end
                    end            
					
                -- 5.6) customer_address
				-- 5.6.0) set @customer_address_id to bill_to address
				select @customer_address_id = ca.customer_address_id,
					@l_customer_address_message = 'No address input'
				from customer_address ca
				where ca.customer_id = @customer_id
					and ca.address_type_id = 1

				-- 5.6.1) check if addresses were passed in
				if exists (select 1 from @customer_address)
				
					-- 5.6.2) set @max for while loop
					begin
						select @max = (select max(temp_id) from @customer_address)

						-- 5.6.3) run through @customer_address table with while loop, executing usp_customer_update_customer_address for each address type
						while @max >= @l_temp_id
							begin
								select @l_address_type_id = ca.address_type_id, @l_address_1 = ca.address_1, @l_address_2 = ca.address_2, @l_city = ca.city, @l_state = ca.state, 
									@l_postal_code = ca.postal_code, @l_country_id = ca.country_id
								from @customer_address ca where ca.temp_id = @l_temp_id 

								if @@rowcount > 0 --temp_id may not exist if address records are deleted from table variable for whatever reason
									begin
										exec usp_customer_update_customer_address @customer_id = @customer_id, @address_type_id = @l_address_type_id, @address_1 = @l_address_1, @address_2 = @l_address_2, 
											@city = @l_city, @state = @l_state, @postal_code = @l_postal_code, @country_id = @l_country_id, @transaction_user = @transaction_user, 
											@customer_address_id = @customer_address_id output, @message = @l_customer_address_message output
									end

								-- 5.6.3.1) update @customer_address_table with active customer_address_id for customer/type (from output of above)
								update @customer_address
								set customer_address_id = @customer_address_id,
									message
 = @l_customer_address_message
								where address_type_id = @l_address_type_id

								select @l_address_type_id = null, @l_address_1 = null, @l_address_2 = null, @l_city = null, @l_state = null, @l_postal_code = null, @l_country_id = null, 
										@customer_address_id = null, @l_temp_id = @l_temp_id + 1, @l_customer_address_message = null
							end

					end

                -- 5.7) partner_company
                if @partner_id is not null and @company_id is not null and @partner_customer_code is not null and @partner_customer_code <> ''
                    begin
                        select @partner_company_id = partner_company_id from partner_company where partner_id = @partner_id and company_id = @company_id

                        if @partner_company_id is null
                            begin
                                insert into partner_company (partner_id, partner_customer_code, company_name, company_id)
                                values (@partner_id, @partner_customer_code, @company_name, @company_id)    
                            end
                        else
                            begin
								insert into partner_company_audit (partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, audit_date)
								select partner_company_id, partner_id, partner_customer_code, company_name, company_id, insert_date, @transaction_date 
								from partner_company 
								where partner_company_id = @partner_company_id

								if @@rowcount > 0 
								begin 
									update partner_company
									set partner_customer_code = @partner_customer_code,
										company_name = @company_name
									where partner_company_id = @partner_company_id
								end 
                            end                
                    END
            end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) Output
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		   
		set @output_json = (
			select
				@customer_id as [customer.customer_id],
				isnull((select ca.customer_address_id from @customer_address ca where ca.address_type_id = 1), @customer_address_id) as [customer.address.bill_to.customer_address_id],
				isnull((select ca.message from @customer_address ca where ca.address_type_id = 1), @l_customer_address_message) as [customer.address.bill_to.customer_address_message],
				(select ca.customer_address_id from @customer_address ca where ca.address_type_id = 2) as [customer.address.ship_to.customer_address_id],
				(select ca.message from @customer_address ca where ca.address_type_id = 2) as [customer.address.ship_to.customer_address_message],
				@vendor_customer_id as [customer.vendor_customer_id],
				@company_id as [company.company_id],
				@email_domain as [company.email_domain],
				@customer_update_json_id as customer_update_json_id,
				0 as [match.company_address_match_count],
                0 as [match.company_email_domain_match_count],
                0 as [match.franchise_match_count],
                0 as [match.customers],
                0 as [match.company_name_match],
				@address_exception_json as [exception.address_exception_json],
				@domain_exception_json as [exception.domain_exception_json],
				@match_exception_json as [exception.match_exception_json]
			for json path, without_array_wrapper
		)

		-- Update the log before exiting
		update dbo.customer_update_json
		set complete_date = getdate(),
			output_json = @output_json
		where customer_update_json_id = @customer_update_json_id

	end try
    
    begin catch

        set @response_code = -200
        set @mes
sage = case when @message is null then 'select failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;
    

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_email_registration]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_customer_insert_email_registration]
	(@process_count INT = 1000)


/*	
	DATE		 AUTHOR			REMARKS
	2017-10-18	mrobbins		initial creation
	2017-11-29	mrobbins		rewrite & license_customer changes

	DESCRIPTION
	
*/

AS

	set nocount ON

	DECLARE @response_code INT,
		@message VARCHAR(100),
		@license_id INT, 
		@current_license_customer_id INT, 
		@customer_id INT, 
		@customer_email VARCHAR(100), 
		@opt_in INT, 
		@email_registration_insert_id INT,
		@email_registration_insert_email_id INT,
		@max_email_registration_insert_email_id INT,
		@vendor_id INT,
		@email_domain VARCHAR(100),
		@vendor_customer_code VARCHAR(100)


	DECLARE @email_registration_insert_email TABLE (email_registration_insert_email_id INT IDENTITY(1,1),
		email_registration_insert_id INT NULL,
		license_id INT,
		customer_id INT,
		opt_in INT,
		customer_email VARCHAR(255) NULL)
        
	BEGIN TRY

		-- 1) Selects

		INSERT INTO @email_registration_insert_email (email_registration_insert_id,license_id,customer_id,opt_in,customer_email)
		SELECT TOP (@process_count)
			email_registration_insert_id,
			license_id,
			customer_id,
			opt_in,
			customer_email
		FROM email_registration_insert eri
		WHERE processed = 0


		SELECT @email_registration_insert_email_id = MIN(email_registration_insert_email_id),
			@max_email_registration_insert_email_id = MAX(email_registration_insert_email_id)
		FROM @email_registration_insert_email

		WHILE @email_registration_insert_email_id <= @max_email_registration_insert_email_id
			BEGIN

				select @license_id = license_id, 
					@customer_id = customer_id,
					@customer_email = customer_email, 
					@opt_in = opt_in,
					@email_registration_insert_id = email_registration_insert_id
				from @email_registration_insert_email 
				where email_registration_insert_email_id = @email_registration_insert_email_id
				
				--PRINT 'BEFORE @customer_id = ' + STR(ISNULL(@customer_id,''))
			

		-- 2) Customer
				IF @customer_id is null
					   BEGIN
					   --See if the customer_email already exists
							SELECT @customer_id = (SELECT MAX(customer_id) customer_id
								FROM customer_email
								WHERE customer_email = @customer_email)

							IF @customer_id IS NULL AND @customer_email IS NOT NULL 
								BEGIN

										--select 'insert customer'

										INSERT INTO customer (opt_in)
										VALUES(@opt_in)

										SELECT @customer_id = SCOPE_IDENTITY() 

										SELECT @vendor_id = ISNULL(@vendor_id,1)

										SELECT @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,LEN(@customer_email))

										INSERT INTO customer_email (customer_id, customer_email, email_status_id, email_domain)
										VALUES (@customer_id, @customer_email, 1, @email_domain)
            

										IF @vendor_customer_code IS NULL
											BEGIN
												EXEC usp_customer_generate_customer_code @vendor_customer_code OUTPUT
												--select @vendor_customer_code = @customer_code
											END
			
										INSERT INTO vendor_customer (vendor_id, customer_id, vendor_customer_code)
										VALUES(@vendor_id, @customer_id, @vendor_customer_code)
										END 
					   
					   END 

				--PRINT 'AFTER @customer_id = ' + STR(@customer_id)

		-- 3) license registration
				IF EXISTS (SELECT customer_id FROM license WHERE license_id = @license_id AND customer_id IS NOT NULL)
						BEGIN
								--select 'insert license_customer'
								insert into license_customer(license_id,customer_id,license_customer_source_id)
								values(@license_id,@customer_id,1)
						END
				ELSE 
						BEGIN 
								insert into license_history(license_id,keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id
,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by,license_change_reason_id,history_date,history_by)
								select license_id,keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by,
										license_change_reason_id=7,history_date=getdate(), history_by = SUSER_SNAME()
								from license
								where license_id = @license_id

								update license
								set customer_id = @customer_id, modified_date = getdate(), modified_by = SUSER_SNAME()
								where license_id = @license_id
              
						END 


				-- 4) mark record as processed
				UPDATE dbo.email_registration_insert
				SET processed = 1
				WHERE email_registration_insert_id = @email_registration_insert_id


				-- ) reset varibles

				SET @customer_id = NULL 
				SET @license_id = NULL
				SET	@customer_email = NULL

				SET @email_registration_insert_email_id = @email_registration_insert_email_id + 1

			END 


	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message is null THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_email_verification]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_customer_insert_email_verification]
	(@keycode VARCHAR(40),
		@customer_email VARCHAR(100),
		@device_name VARCHAR(255) NULL,
		@device_MID VARCHAR(255) NULL,
		@instance_MID varchar(255) NULL,
		@vendor VARCHAR(255),
		@vendor_status VARCHAR(255),
		@opt_in INT,
		@source VARCHAR(50) NULL)


/*	
	DATE		 AUTHOR			REMARKS
	2018-10-17	mrobbins		initial creation
	2020-06-08	mrobbins		moved @customer_email_verification_id outside of if statement
	2020-09-08	mrobbins		added source to be passed

	DESCRIPTION
	
*/

AS

	SET NOCOUNT ON

	DECLARE @response_code INT,
		@message VARCHAR(100),
		@license_id INT, 
		@customer_id INT, 
		@vendor_id INT,
		@email_domain VARCHAR(100),
		@vendor_customer_code VARCHAR(100),
		@customer_email_verification_id INT,
		@customer_email_verification_status_id INT,
		@customer_email_out VARCHAR(100),
		@webroot_status VARCHAR(100),
		@source_id INT 

        
	BEGIN TRY

		SELECT @customer_email_verification_id = (SELECT MAX(customer_email_verification_id) customer_email_verification_id
		FROM customer_email_verification
		WHERE customer_email = @customer_email)

		SELECT @source_id = license_customer_source_id
		FROM dbo.license_customer_source lcs
		WHERE lcs.license_customer_source_description = @source

		IF @source_id IS NULL BEGIN SET @source_id = 1 END 
		
		--ONLY insert/update license if it's a valid email 
		IF (SELECT webroot_status FROM customer_email_verification_status WHERE vendor_status = @vendor_status) = 'valid'  
		
			BEGIN 

				-- 1) Selects find the customer_id, customer_email_verification_id, license_id 
				SELECT @customer_id = (SELECT MAX(customer_id) customer_id
										FROM customer_email
										WHERE customer_email = @customer_email)

				SELECT @license_id = license_id FROM license WHERE keycode = @keycode
			

				-- 2) Customer
						IF @customer_id IS NULL 
							AND @customer_email IS NOT NULL 

							BEGIN

								--select 'insert customer'

								INSERT INTO customer (opt_in)
								VALUES(@opt_in)

								SELECT @customer_id = SCOPE_IDENTITY() 

								SELECT @vendor_id = ISNULL(@vendor_id,1)

								SELECT @email_domain=SUBSTRING(@customer_email,CHARINDEX('@',@customer_email)+1,LEN(@customer_email))

								INSERT INTO customer_email (customer_id, customer_email, email_status_id, email_domain)
								VALUES (@customer_id, @customer_email, 1, @email_domain)
            

								IF @vendor_customer_code IS NULL
									BEGIN
										EXEC usp_customer_generate_customer_code @vendor_customer_code OUTPUT
										--select @vendor_customer_code = @customer_code
									END
			
								INSERT INTO vendor_customer (vendor_id, customer_id, vendor_customer_code)
								VALUES(@vendor_id, @customer_id, @vendor_customer_code)

							END 

				-- 3) license registration
						IF EXISTS (SELECT customer_id FROM license WHERE license_id = @license_id AND customer_id IS NOT NULL)
								BEGIN
										--select 'insert license_customer'
										insert into license_customer(license_id,customer_id,license_customer_source_id,opt_in)
										values(@license_id,@customer_id,@source_id,@opt_in)
								END
						ELSE 
								BEGIN 
										insert into license_history(license_id,keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by,license_change_reason_id,history_date,history_by)
										select license_id,keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_k
eycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by,
												license_change_reason_id=7,history_date=getdate(), history_by = SUSER_SNAME()
										from license
										where license_id = @license_id

										update license
										set customer_id = @customer_id, modified_date = getdate(), modified_by = SUSER_SNAME()
										where license_id = @license_id
              
								END 
			END
            
		-- 4) Insert customer_email_verification
				--vendor status doesn't matter

				IF @customer_email_verification_id IS NULL
					BEGIN
						INSERT INTO customer_email_verification(customer_email,customer_id,customer_email_verification_status_id)
						SELECT @customer_email customer_email,
							@customer_id customer_id,
							cevs.customer_email_verification_status_id
						FROM dbo.customer_email_verification_status cevs
						WHERE cevs.vendor_status = @vendor_status		
					END 
				ELSE
					BEGIN

						SELECT @customer_email_verification_status_id = customer_email_verification_status_id
						FROM dbo.customer_email_verification_status
						WHERE vendor_status = @vendor_status

						UPDATE customer_email_verification 
						SET customer_email_verification_status_id = @customer_email_verification_status_id,
							modified_date = GETDATE(),
							modified_by = SUSER_SNAME()
						WHERE customer_email_verification_id = @customer_email_verification_id
					END 

				SELECT @customer_email_out = @customer_email,
					@webroot_status = cevs.webroot_status
				FROM customer_email_verification cev
					INNER JOIN dbo.customer_email_verification_status cevs
						ON cev.customer_email_verification_status_id = cevs.customer_email_verification_status_id
				WHERE cev.customer_email = @customer_email

				SELECT @customer_email_out customer_email_out,
					@webroot_status webroot_status



			--5) reset varibles

				SET @customer_id = NULL 
				SET @license_id = NULL
				SET @keycode = NULL 
				SET	@customer_email = NULL
				SET @device_name = NULL
				SET @device_MID = NULL
				SET @instance_MID = NULL
				SET @vendor = NULL
				SET @vendor_status = NULL
				SET @opt_in = 0
				SET @source = NULL
				SET @source_id = 0




	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message is null THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_phone]
-- =============================================================================



CREATE   PROCEDURE [dbo].[usp_customer_insert_phone]

(
	@customer_id int,
	@phone_type_id int,
	@phone_number varchar(64),
	@system_user varchar(50) = null,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-12	esmart		Initial creation.
	2006-08-21	tblazek		Add respond code and message return for successful insert
	2006-12-01	tblazek		Remove display of phone number

	DESCRIPTION
	Inserts new phone number 
*/


AS
begin try

	set nocount on 

	declare @error int,
		@customer_phone_id int
	
	set @response_code = 0
	
	if @system_user is null 
		begin
			set @system_user = system_user
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate phone_type_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select 	@response_code = 
				case
					when count(*) = 0 then - 100
					else 0
				end,
			@message = 
				case
					when count(*) = 0 then 'Invalid phone_type_id @customer_id - ' + isnull(ltrim(rtrim(str(@customer_id))),'Null @customer_id') + ''
					else ''
				end
		from customer_phone_type
		where phone_type_id = @phone_type_id

		--if @response_code <> 0
		--	begin	
		--		RAISERROR (@message, 11, 0)
		--	end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) validate customer_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select 	@response_code = 
				case
					when count(*) = 0 then - 200
					else 0
				end,
			@message = 
				case
					when count(*) = 0 then 'Invalid customer_id @customer_id - ' + isnull(ltrim(rtrim(str(@customer_id))),'Null @customer_id') + ''
					else ''
				end
		from customer
		where customer_id = @customer_id

		--if @response_code <> 0
		--	begin	
		--		RAISERROR (@message, 11, 0)
		--	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) check to see if the phone number exists
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select 	@response_code = 
				case
					when count(*) > 0 then - 300
					else 0
				end,
			@message = 
				case
					when count(*) > 0 then 'Phone number already exists @customer_id - ' + isnull(ltrim(rtrim(str(@customer_id))),'Null @customer_id') + ''
					else ''
				end
		from customer_phone
		where customer_id = @customer_id and
			phone_type_id = @phone_type_id and
			phone_number = @phone_number

		--if @response_code <> 0
		--	begin	
		--		RAISERROR (@message, 11, 0)
		--	end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) insert phone number
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @response_code = 0
		begin
			
			insert into customer_phone (customer_id, 
phone_type_id, phone_number, insert_date, insert_by, modified_date, modified_by)
			values (@customer_id, @phone_type_id, @phone_number, getdate(), @system_user, getdate(), @system_user)

			set @customer_phone_id = @@identity
			
			set @response_code = 0
			set @message = 'customer_phone insert complete'
			
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--select customer_phone_id = @customer_phone_id


end try
begin catch


	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	set @response_code = case when @response_code = 0 then -400 else @response_code end
	set @message = isnull(@message,'customer_phone insert failed')
	set @customer_phone_id = null
	
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_insert_vendor_customer]
-- =============================================================================



CREATE  PROCEDURE [dbo].[usp_customer_insert_vendor_customer]

(
	@vendor_id int,
	@customer_id int,
	@vendor_customer_code varchar(100),
	@vendor_customer_id int output
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-07	esmart		Initial creation.
	2006-08-11	esmart		Add additional error trapping
	2006-08-25	tblazek		Modify inserts to move the customer_id to the vendor_customer table and remove the vendor_customer_id 
					from customer table. 
	2006-09-20	tblazek		Change @@identity to SCOPE_IDENTITY() for setting @vendor_customer_id variable 
	10/03/07	bjordan		added try/catch

	DESCRIPTION
	Insert new vendor customer record
*/

AS
begin try
	set nocount on

	-- declare variables
	declare @error int,
		@insert_date datetime

	set @error = 0
	set @insert_date = getdate()

	-- insert row
	insert into vendor_customer (vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by)
	values (@vendor_id, @customer_id, @vendor_customer_code, @insert_date, system_user, @insert_date, system_user)
	
	set @vendor_customer_id = SCOPE_IDENTITY()

end try
begin catch
	
   set @vendor_customer_id = null
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_load]
-- =============================================================================



CREATE                PROCEDURE [dbo].[usp_customer_load] 
@vendor_order_id bigint,
@vendor_id int,
@vendor_customer_id bigint,
@vendor_address_id int,
@customer_type varchar(10),
@first_name nvarchar(255),
@middle_name nvarchar(255),
@last_name nvarchar(255),
@address_1 nvarchar(255),
@address_2 nvarchar(255),
@address_3 nvarchar(255),
@city nvarchar(130),
@state  char(2),
@postal_code varchar(32),
@country char(3),
@phone_number varchar(64),
@fax_number varchar(64),
@company_name nvarchar(255),
@alternate_phone_number varchar(64),
@customer_email nvarchar(255),
@opt_in bit,
@response_code int OUTPUT,
@message varchar(100) OUTPUT,
@customer_load_id int OUTPUT
AS
/*	DATE		AUTHOR		REMARKS
	08/17/06	TBlazek		Initial creation.
	09/13/06	tblazek		Commenting out logic that limits WR cart order to vendor id 1.  ATT and MSN will flow through the load tables as well.
					This logic will need to be re-worked for digital river to determine when the order_notification_status record
					will be written for that vendor.
	10/18/06	tblazek		If postal code is null, convert to blank
	11/06/06	tblazek		Change vendor_order_id from int to bigint for Digital river
	11/17/06	tblazek		Change vendor_customer_id from int to bigint for Digital river, add update capability for 
					order_notification_status to support m/t/1 customer record for each order.
	11/27/06	tblazek		Remove transaction management
	10/03/07	bjordan		Added Try/Catch and transaction management back in
	10/24/07	bjordan		Added additional logic to trap a null vendor_order_id

	DESCRIPTION
		Insert customer load table for order notification from 3rd party shopping cart vendor.
		Insert customer load table for orders placed on Webroot cart.  

		***Digital River - modify code to allow for inserts and updates of order_notification_status table

*/
begin try
SET NOCOUNT ON
Declare @insert_date datetime,
	@insert_by varchar(50),
	@order_notification_status_id int,
	@order_load_definition_id int,
	@order_load_error_definition_id int

declare @proctrancount int
set @proctrancount = @@trancount

Select @response_code = 0
Select @insert_date = getdate()
Select @insert_by = user


If @postal_code is null  
	BEGIN
		Set @postal_code = ''
	END

Select @order_load_definition_id = order_load_definition_id 
						from order_load_status_definition 
						where order_load_status = 'LOADDATACUST'
--Select @order_load_definition_id
If not exists (Select order_notification_status_id 
		from order_notification_status 
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id)
	BEGIN
		if @vendor_order_id is null
			begin
				select @response_code = -100
				select @message =  'Null Vendor_order_id, @vendor_customer_id - ' + isnull(ltrim(rtrim(str(@vendor_customer_id))),'Null too') + ''
				RAISERROR (@message, 11, 0)
			end
		else
			begin	
			Insert order_notification_status
			Values (@vendor_order_id, @vendor_id, @order_load_definition_id, null, 	
				@insert_date, @insert_by, @insert_date,	@insert_by)
			end
	END
Else
	BEGIN
	
		update order_notification_status
		Set order_load_definition_id = @order_load_definition_id,
		    order_load_error_definition_id = null,
		    modified_date = @insert_date,	
		    Modified_by = @insert_by
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id
	END

Select @order_notification_status_id = order_notification_status_id 
					from order_notification_status 
					where vendor_order_id = @vendor_order_id
					and vendor_id = @vendor_id
--Select @order_notification_status_id

	If not exists (Select customer_load_id 
			from customer_load 
			where vendor_order_id = @vendor_order_id
			and vendor_id = @vendor_id
			and ve
ndor_customer_id = @vendor_customer_id
			and customer_type = @customer_type)
		BEGIN
			Insert customer_load
				(vendor_order_id,
				vendor_id,
				vendor_customer_id,
				vendor_address_id,
				customer_type,
				first_name,
				middle_name,
				last_name,
				address_1,
				address_2,
				address_3,
				city,
				state,
				postal_code,
				country,
				phone_number,
				fax_number,
				company_name,
				alternate_phone_number,
				customer_email,
				opt_in,
				insert_date,
				insert_by,
				modified_date,
				modified_by,
				order_notification_status_id)
			Values
				(@vendor_order_id,
				@vendor_id,
				@vendor_customer_id,
				@vendor_address_id,
				@customer_type,
				@first_name,
				@middle_name,
				@last_name,
				@address_1,
				@address_2,
				@address_3,
				@city,
				@state,
				@postal_code,
				@country,
				@phone_number,
				@fax_number,
				@company_name,
				@alternate_phone_number,
				@customer_email,
				@opt_in,
				@insert_date,
				@insert_by,
				@insert_date,
				@insert_by,
				@order_notification_status_id)

			Select @customer_load_id = SCOPE_IDENTITY() 
		END
	Else
		BEGIN
			Select @customer_load_id = customer_load_id 
			from customer_load 
			where vendor_order_id = @vendor_order_id
			and vendor_id = @vendor_id
			and vendor_customer_id = @vendor_customer_id
			and customer_type = @customer_type
		END

	set @response_code = 0
	set @message = 'Customer record loaded successfully'
	



end try
begin catch
	--RAISERROR (@message, 11, 0)

	Select @order_load_error_definition_id = order_load_error_definition_id
	 From order_load_error_definition
	 Where order_load_error = 'LOADDATACUSTFAIL'

	if @vendor_order_id is not null
		begin

		update order_notification_status
			set order_load_error_definition_id = @order_load_error_definition_id
			where vendor_order_id = @vendor_order_id
			and vendor_id = @vendor_id

		update order_notification_load
			set order_load_status = 'LOADDATACUSTFAIL'
			where vendor_order_id = @vendor_order_id
		end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_merge_customer]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_customer_merge_customer]
(
    @customer_merge_id INT,
    @modified_by VARCHAR(20)
)

/*
    DATE        AUTHOR      REMARKS
    2009-06-01  esmart      Initial creation.
    2011-05-25  esmart      Update for license_message_value 
    2013-09-06  acoffel     added additional table management
    2014-10-27  mandersen   Update for additional foreign keys and align with batch version 
    2018-08-21  jnavarra    Add missing fields for archive tables
                            Handle a bunch of missing tables
    2019-09-04  abelenkiy   Added logic to prevent duplicate record during updates to customer_order and order_company
    2020-01-08  esmart      Add logic on customer_phone management to eliminate duplicate phone records
    2020-02-25  jnavarra    Reorganize to keep tables together
    2020-03-03  jnavarra    Update customer_address logic
    2020-08-25  abelenkiy   Update address update logic to use new procedure and care for dupes; removed @all_customer_ids table var because not being used anywhere
    2020-10-08  abelenkiy   Update address logic to use new "clean" fields from customer_address for duplicate handling
    2024-04-12  cibach      Update customer_id in safe_account_user_customer and insert old into audit table
    2024-06-04  jberry      ECOM-394 - update customer id on ship_cd_without_order to resolve foreign key error when merging customers
                            ECOM-4598 - ensure the master customer company has a primary address after merge

    DESCRIPTION
    
*/

AS
BEGIN
    SET NOCOUNT ON

    DECLARE @master_customer_id INT,
            @response_code INT,
            @message VARCHAR(100)

	DECLARE @merge_customers TABLE (customer_id INT)

    BEGIN TRY


		-- set master_customer_id from customer_merge_table
        SELECT @master_customer_id = master_customer_id
        FROM dbo.customer_merge        
        WHERE customer_merge_id = @customer_merge_id
		
		-- insert all customers to be merged to table
		INSERT INTO @merge_customers (customer_id)
		SELECT cmc.customer_id 
		FROM customer_merge_customer cmc
		WHERE cmc.customer_merge_id = @customer_merge_id

        BEGIN TRANSACTION merge_customer



            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
            -- 1.) update rows
            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
            -- csi_comments
            INSERT INTO eCommerce_archive.dbo.csi_comments(comment_id, subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id, refund_reason_code, csi_users_id)
            SELECT c.comment_id, c.subject, c.comment, c.insert_date, c.insert_by, c.customer_id, c.invoice_id, c.license_id, c.refund_reason_code, c.csi_users_id 
            FROM dbo.csi_comments c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.csi_comments
            SET customer_id = @master_customer_id
            FROM dbo.csi_comments c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            -- customer_address
			-- declare vars			
			DECLARE @address_type TABLE (tmp_id INT IDENTITY, address_type_id INT)

			DECLARE @merge_address TABLE (custom
er_address_id INT, customer_id INT, address_type_id INT, address_1 NVARCHAR(255), address_2 NVARCHAR(255), 
				address_3 NVARCHAR(255), city NVARCHAR(130),state NVARCHAR(2), postal_code NVARCHAR(32), country_id SMALLINT, vendor_address_id INT, insert_date DATETIME, 
				insert_by VARCHAR(50), modified_date DATETIME, modified_by VARCHAR(50), address_status_id TINYINT, clean_address NVARCHAR(510), clean_city NVARCHAR(130),
				clean_postal_code NVARCHAR(32), master_customer_address_id INT)

			DECLARE @master_address TABLE (customer_address_id INT, customer_id INT, address_type_id INT, address_1 NVARCHAR(255), address_2 NVARCHAR(255), 
				address_3 NVARCHAR(255), city NVARCHAR(130),state NVARCHAR(2), postal_code NVARCHAR(32), country_id SMALLINT, vendor_address_id INT, insert_date DATETIME, 
				insert_by VARCHAR(50), modified_date DATETIME, modified_by VARCHAR(50), address_status_id TINYINT, clean_address NVARCHAR(510), clean_city NVARCHAR(130),
				clean_postal_code NVARCHAR(32))

			DECLARE @merge_customer_order_address TABLE (customer_order_address_id INT, customer_address_id INT)

			--	insert all addresses from merged records to archive and temp table - all these will be updated to master customer
			INSERT INTO @merge_address (customer_address_id, customer_id, address_type_id, address_1, address_2, address_3, city, state, postal_code, country_id, vendor_address_id, 
					insert_date, insert_by, modified_date, modified_by, address_status_id, clean_address, clean_city, clean_postal_code)
				OUTPUT Inserted.customer_address_id, Inserted.customer_id, Inserted.address_type_id, Inserted.address_1, Inserted.address_2, Inserted.address_3, Inserted.city, 
					Inserted.state, Inserted.postal_code, Inserted.country_id, Inserted.vendor_address_id, Inserted.insert_date, Inserted.insert_by, Inserted.modified_date, 
					Inserted.modified_by, Inserted.address_status_id
				INTO eCommerce_Archive.dbo.customer_address (customer_address_id, customer_id, address_type_id, address_1, address_2, address_3, city, state, postal_code, 
					country_id, vendor_address_id, insert_date, insert_by, modified_date, modified_by, address_status_id)
			SELECT a.customer_address_id, a.customer_id, a.address_type_id, a.address_1, a.address_2, a.address_3, a.city, a.state, a.postal_code, a.country_id, a.vendor_address_id, 
				a.insert_date, a.insert_by, a.modified_date, a.modified_by, a.address_status_id, a.clean_address, a.clean_city, a.clean_postal_code
			FROM dbo.customer_address a
				INNER JOIN @merge_customers mc ON mc.customer_id = a.customer_id

			-- only proced if records found on merged customers
			IF @@rowcount > 0
				BEGIN

					-- stage all addresses from master customer
					INSERT INTO @master_address (customer_address_id, customer_id, address_type_id, address_1, address_2, address_3, city, state, postal_code, 
						country_id, vendor_address_id, insert_date, insert_by, modified_date, modified_by, address_status_id, clean_address, clean_city, clean_postal_code)
					SELECT ca.customer_address_id, ca.customer_id, ca.address_type_id, ca.address_1, ca.address_2, ca.address_3, ca.city, ca.state, ca.postal_code, ca.country_id, 
						ca.vendor_address_id, ca.insert_date, ca.insert_by, ca.modified_date, ca.modified_by, ca.address_status_id, ca.clean_address, ca.clean_city, ca.clean_postal_code
					FROM customer_address ca 
					WHERE ca.customer_id = @master_customer_id

					-- look for matching addresses between merge and master customers
					UPDATE @merge_address
						SET master_customer_address_id = ca.customer_address_id
					FROM @merge_address ma 
						INNER JOIN @master_address ca 
							ON ma.clean_address = ca.clean_address
							AND ma.clean_city = ca.clean_city
							AND ma.state = ca.state
							AND ma.clean_postal_code = ca.clean_postal_code
							AND ma.country_id = ca.country_id
							AND ma.address_type_id = ca.address_type_id;

					-- proceed to duplicate cleanup
 if found
					IF @@rowcount > 0
						BEGIN
							-- archive and repoint any customer_order_address records from merge address to duplicate master address
							insert into customer_order_address_audit (customer_order_address_id, order_header_id, customer_address_id, insert_date, insert_by, modified_date, modified_by, audit_date)
							output Inserted.customer_order_address_id, Inserted.customer_address_id
							into @merge_customer_order_address (customer_order_address_id, customer_address_id)
							select coa.customer_order_address_id, coa.order_header_id, coa.customer_address_id, coa.insert_date, coa.insert_by, coa.modified_date, coa.modified_by, getdate()
							from customer_order_address coa
								inner join @merge_address ma 
									on ma.customer_address_id = coa.customer_address_id
							where ma.master_customer_address_id is not null

							if @@rowcount > 0
								begin
									update customer_order_address
									set customer_address_id = ma.master_customer_address_id
									from @merge_customer_order_address mcoa
										inner join @merge_address ma on ma.customer_address_id = mcoa.customer_address_id
									where customer_order_address.customer_order_address_id = mcoa.customer_order_address_id
								end

							-- delete duplicate merge customer address
							DELETE customer_address
							FROM @merge_address ma
							WHERE customer_address.customer_address_id = ma.customer_address_id
								AND ma.master_customer_address_id IS NOT NULL
						END


					-- update all addresses to master if any existed
					UPDATE dbo.customer_address
					SET customer_id = @master_customer_id, address_status_id = 2, modified_date = GETDATE(), modified_by = @modified_by
					FROM dbo.customer_address ca
						INNER JOIN @merge_address ca2
							ON ca.customer_address_id = ca2.customer_address_id;

					-- log address types to table var that exist on merged customers but not on master
					INSERT INTO @address_type (address_type_id)
					SELECT DISTINCT ca.address_type_id
					FROM @merge_address ca
						LEFT JOIN @master_address ca2
							ON ca.address_type_id = ca2.address_type_id AND ca2.address_status_id = 1
					WHERE ca.address_status_id = 1 --merge customers have an active address for an address type the master customer doesn't have
						  AND ca2.customer_address_id IS NULL;

					-- if address types already exist on master, no more changes need to be made because master already has an active address for each type
					IF @@rowcount > 0
						BEGIN
							-- loop through addresses on merged customers where address_type missing on master to activate them 
							DECLARE @address_type_id INT, @max_row INT = (SELECT COUNT(address_type_id)FROM @address_type), @min_row INT = 1, @address_1 NVARCHAR(255)
								  , @address_2		 NVARCHAR(255), @city NVARCHAR(130), @state NVARCHAR(50), @postal_code NVARCHAR(32), @country_id SMALLINT;

							WHILE @max_row >= @min_row
								BEGIN
									-- choose active address for each type, prioritizing oldest customer with active record
									SELECT TOP (1) @address_1 = ca2.address_1, @address_2 = ca2.address_2, @city = ca2.city, @state = ca2.state
												 , @postal_code = ca2.postal_code, @country_id = ca2.country_id, @address_type_id = ca2.address_type_id
									FROM @merge_address ca2
										INNER JOIN @address_type at
											ON at.address_type_id = ca2.address_type_id
									WHERE ca2.address_status_id = 1 
										AND at.tmp_id = @min_row
									ORDER BY ca2.customer_id ASC; --oldest customer priority

									DECLARE @customer_address_id INT

									EXEC usp_customer_update_customer_address @customer_id = @master_customer_id, @address_type_id = @address_type_id, @address_1 = @address_1, 
										@address_2 = @address_2, @city = @city, @state = @state, @postal_code = @postal_code, @country_id = @country_id, @transaction_user = @modified_by, 
										@customer
_address_id = @customer_address_id OUTPUT, @message = @message OUTPUT, @response_code = @response_code OUTPUT

									SELECT @min_row = @min_row + 1, @address_type_id = NULL, @address_1 = NULL, @address_2 = NULL, @city = NULL, @state = NULL, 
										@postal_code = NULL, @country_id = NULL;
								END
						END
				END

			-- if master address is missing use the merge address if it exists
			UPDATE ca
			SET ca.address_1 = ca2.address_1,
				ca.clean_address = ca2.clean_address,
				ca.address_2 = ca2.address_2,
				ca.state = ca2.state,
				ca.city = ca2.city,
				ca.clean_city = ca2.clean_city,
				ca.postal_code = ca2.postal_code,
				ca.clean_postal_code = ca2.clean_postal_code
			FROM dbo.customer_address ca2
				INNER JOIN dbo.customer_address ca
					ON ca.customer_id = ca2.customer_id
					   AND ca.address_type_id = ca2.address_type_id
			WHERE ca.customer_id = @master_customer_id
				  AND ISNULL(ca.address_1, '') = ''
				  AND ISNULL(ca2.address_1, '') <> '';

			--create primary address for the company associated to the master customer if it doesn't exist
			--this happens in rare cases when a customer with an address is merged into a customer without a primary address
			DECLARE @company_id INT;

			SELECT @company_id = cc.company_id,
					@address_1 = isnull(ca.address_1, ''),
					@address_2 = isnull(ca.address_2, ''),
					@city = isnull(ca.city, ''),
					@state = ca.state,
					@postal_code = isnull(ca.postal_code, ''),
					@country_id = ca.country_id,
					@address_type_id = ca.address_type_id
						FROM dbo.customer_address ca
							JOIN dbo.customer_company cc
								ON cc.customer_id = ca.customer_id
						WHERE ca.address_type_id = 1
							  AND ca.address_status_id = 1
							  AND ca.customer_id = @master_customer_id
							  
			IF @company_id IS NOT NULL
			BEGIN
				EXEC dbo.usp_customer_update_company_address @company_id = @company_id,
															 @address_1 = @address_1,
															 @address_2 = @address_2,
															 @city = @city,
															 @state = @state,
															 @postal_code = @postal_code,
															 @country_id = @country_id;
			END;

            -- customer_locale
            INSERT INTO eCommerce_archive.dbo.customer_locale(customer_locale_id, customer_id, location_code, language_code, customer_locale_source_id, last_modified_date)
            SELECT l.customer_locale_id, l.customer_id, l.location_code, l.language_code, l.customer_locale_source_id, l.last_modified_date
            FROM dbo.customer_locale l
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = l.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.customer_locale
            SET customer_id = @master_customer_id
            FROM dbo.customer_locale cl
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = cl.customer_id
            WHERE m.customer_merge_id = @customer_merge_id



            -- customer_order
            INSERT INTO eCommerce_archive.dbo.customer_order(customer_order_id, customer_id, order_header_id, customer_type_id, insert_date, insert_by, modified_date, modified_by)
            SELECT o.customer_order_id, o.customer_id, o.order_header_id, o.customer_type_id, o.insert_date, o.insert_by, o.modified_date, o.modified_by 
            FROM dbo.customer_order o
                INNER JOIN dbo.customer_merge_customer m
                    ON o.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

			UPDATE customer_order
			SET customer_id = @master_customer_id
			FROM customer_order o
				INNER JOIN customer_merge_customer m
					ON o.customer_id = m.customer_id
			WHERE m.customer_merge_id = @customer_merge_id
				AND NOT EXISTS (SELECT 1 FROM customer_order co2 WHERE co2.customer_id = @master_customer_id AND co2.customer_typ
e_id = o.customer_type_id AND co2.order_header_id = o.order_header_id)

            -- customer_order_audit
            INSERT INTO eCommerce_archive.dbo.customer_order_audit(customer_order_audit_id, customer_order_id, customer_id, order_header_id, customer_type_id, insert_date, insert_by, modified_date, modified_by, audit_date)
            SELECT coa.customer_order_audit_id, coa.customer_order_id, coa.customer_id, coa.order_header_id, coa.customer_type_id, coa.insert_date, coa.insert_by, coa.modified_date, coa.modified_by, coa.audit_date
            FROM dbo.customer_order_audit coa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = coa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.customer_order_audit
            SET customer_id = @master_customer_id
            FROM dbo.customer_order_audit coa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = coa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id



            -- cybs_customer_profile_customer
            INSERT INTO eCommerce_archive.dbo.cybs_customer_profile_customer(cybs_customer_profile_customer_id, cybs_customer_profile_id, customer_id, license_id, insert_date, insert_by)
            SELECT c.cybs_customer_profile_customer_id, c.cybs_customer_profile_id, c.customer_id, c.license_id, c.insert_date, c.insert_by 
            FROM dbo.cybs_customer_profile_customer c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.cybs_customer_profile_customer
            SET customer_id = @master_customer_id
            FROM dbo.cybs_customer_profile_customer c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id



            -- cybs_subscription_customer
            INSERT INTO eCommerce_archive.dbo.cybs_subscription_customer(cybs_subscription_customer_id, cybs_subscription_id, customer_id, company_id, insert_date)
            SELECT csc.cybs_subscription_customer_id, csc.cybs_subscription_id, csc.customer_id, csc.company_id, csc.insert_date
            FROM dbo.cybs_subscription_customer csc
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = csc.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.cybs_subscription_customer
