                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            UPDATE dbo.amazon_account
            SET customer_id = @master_customer_id
            FROM dbo.amazon_account aa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id



            -- license_message_value_archive
            insert into eCommerce_Archive.dbo.license_message_value_archive (license_message_value_archive_id, license_message_value_id, license_message_id, message_value_type_id, value_id)
            select a.license_message_value_archive_id, a.license_message_value_id, a.license_message_id, a.message_value_type_id, a.value_id
            from dbo.license_message_value_archive a
                inner join dbo.customer_merge_customer m
                    on a.value_id = m.customer_id
            where m.customer_merge_id = @customer_merge_id and a.message_value_type_id = 10

            update a
            set a.value_id = @master_customer_id
            from dbo.license_message_value_archive a
                inner join dbo.customer_merge_customer m
                    on a.value_id = m.customer_id
            where m.customer_merge_id = @customer_merge_id and a.message_value_type_id = 10


   
			-- license_message_value
			insert into ecommerce_archive.dbo.license_message_value (license_message_value_id, license_message_id, message_value_type_id, value_id)
			select license_message_value_id, license_message_id, message_value_type_id, value_id
			from license_message_value a
			inner join customer_merge_customer m
				on a.value_id = m.customer_id
			where customer_merge_id = @customer_merge_id and a.message_value_type_id = 10

			update v
			set v.value_id = @master_customer_id 
			from license_message_value v
			inner join customer_merge_customer m
				on v.value_id = m.customer_id 
			where m.customer_merge_id = @customer_merge_id and v.message_value_type_id = 10



            -- email_registration_insert
			insert into ecommerce_archive.dbo.email_registration_insert (email_registration_insert_id, keycode, opt_in, customer_email, last_modified_date, license_id, customer_id, insert_date, processed)
			select a.email_registration_insert_id, keycode, opt_in, customer_email, last_modified_date, license_id, a.customer_id, insert_date, processed 
			from email_registration_insert a
			inner join customer_merge_customer m
				on a.customer_id = m.customer_id
			where customer_merge_id = @customer_merge_id

            UPDATE dbo.email_registration_insert
            SET customer_id = @master_customer_id
            FROM dbo.email_registration_insert aa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id



            -- customer_email_verification
			insert into eCommerce_Archive.dbo.customer_email_verification (customer_email_verification_id, customer_email, customer_id, customer_email_verification_status_id, insert_date, insert_by, modified_date, modified_by)
	
		select a.customer_email_verification_id, customer_email, a.customer_id, customer_email_verification_status_id, insert_date, insert_by, modified_date, modified_by
			from customer_email_verification a
			inner join customer_merge_customer m
				on a.customer_id = m.customer_id
			where customer_merge_id = @customer_merge_id

            UPDATE dbo.customer_email_verification
            SET customer_id = @master_customer_id
            FROM dbo.customer_email_verification aa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

			--safe_account_user_customer
			INSERT INTO dbo.safe_account_user_customer_audit
			(safe_account_user_customer_id, safe_account_user_guid, customer_id, allstate_registration_status_id, modified_date, modified_by, insert_date, insert_by, audit_date, audit_by)
			SELECT a.safe_account_user_customer_id, a.safe_account_user_guid, a.customer_id, a.allstate_registration_status_id, a.modified_date, a.modified_by, a.insert_date, a.insert_by, GETDATE(), @modified_by
			FROM dbo.safe_account_user_customer a
			INNER JOIN customer_merge_customer m
				ON a.customer_id = m.customer_id
			WHERE customer_merge_id = @customer_merge_id

			UPDATE dbo.safe_account_user_customer
            SET customer_id = @master_customer_id
            FROM dbo.safe_account_user_customer aa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

			--ship_cd_without_order
			INSERT INTO eCommerce_archive.dbo.ship_cd_without_order
			(customer_id, product_id, insert_date)
			SELECT s.customer_id, s.product_id, s.insert_date
            FROM dbo.ship_cd_without_order s
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = s.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

			UPDATE dbo.ship_cd_without_order
            SET customer_id = @master_customer_id
            FROM dbo.ship_cd_without_order aa
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = aa.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
            -- 2.) delete rows
            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

            -- customer_audit
            INSERT INTO eCommerce_archive.dbo.customer_audit(customer_audit_id, customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by, salesforce_contact_id)
            SELECT a.customer_audit_id, a.customer_id, a.first_name, a.middle_name, a.last_name, a.title, a.opt_in, a.insert_date, a.insert_by, a.modified_date, a.modified_by, a.audit_date, a.audit_by, a.salesforce_contact_id
            FROM dbo.customer_audit a
                INNER JOIN dbo.customer_merge_customer m
                    ON a.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer_audit
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- customer_company_audit
            INSERT INTO eCommerce_archive.dbo.customer_company_audit(customer_company_audit_id, customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company
_id, customer_type_id, audit_date)
            SELECT cca.customer_company_audit_id, cca.customer_company_id, cca.customer_id, cca.company_name, cca.insert_date, cca.insert_by, cca.modified_date, cca.modified_by, cca.company_id, cca.customer_type_id, cca.audit_date
            FROM dbo.customer_company_audit cca
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = cca.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer_company_audit
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- customer_company
            INSERT INTO eCommerce_archive.dbo.customer_company(customer_company_id, customer_id, company_name, insert_date, insert_by, modified_date, modified_by, company_id, customer_type_id)
            SELECT c.customer_company_id, c.customer_id, c.company_name, c.insert_date, c.insert_by, c.modified_date, c.modified_by, c.company_id, c.customer_type_id
            FROM dbo.customer_company c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer_company
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- customer_email
            INSERT INTO eCommerce_archive.dbo.customer_email(customer_email_id, customer_id, customer_email, email_status_id, insert_date, insert_by, modified_date, modified_by, email_domain)
            SELECT e.customer_email_id, e.customer_id, e.customer_email, e.email_status_id, e.insert_date, e.insert_by, e.modified_date, e.modified_by, e.email_domain
            FROM dbo.customer_email e
                INNER JOIN dbo.customer_merge_customer m
                    ON e.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer_email
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- customer_type_customer
            INSERT INTO eCommerce_archive.dbo.customer_type_customer(customer_type_customer_id, customer_type_id, customer_id, insert_date, insert_by, modified_date, modified_by)
            SELECT c.customer_type_customer_id, c.customer_type_id, c.customer_id, c.insert_date, c.insert_by, c.modified_date, c.modified_by 
            FROM dbo.customer_type_customer c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer_type_customer
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- vendor_customer_audit
            INSERT INTO eCommerce_archive.dbo.vendor_customer_audit(vendor_customer_audit_id, vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id, audit_date)
            SELECT vca.vendor_customer_audit_id, vca.vendor_customer_id, vca.vendor_id, vca.customer_id, vca.vendor_customer_code, vca.insert_date, vca.insert_by, vca.modified_date, vca.modified_by, vca.partner_id, vca.audit_date
            FROM dbo.vendor_customer_audit vca
                INNER JOIN dbo.customer_merge_customer m
                    ON m.customer_id = vca.customer_id
            WHERE m.customer_merge_id = @cu
stomer_merge_id

            DELETE FROM dbo.vendor_customer_audit
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- vendor_customer
            INSERT INTO eCommerce_archive.dbo.vendor_customer(vendor_customer_id, vendor_id, customer_id, vendor_customer_code, insert_date, insert_by, modified_date, modified_by, partner_id)
            SELECT v.vendor_customer_id, v.vendor_id, v.customer_id, v.vendor_customer_code, v.insert_date, v.insert_by, v.modified_date, v.modified_by, v.partner_id
            FROM dbo.vendor_customer v
                INNER JOIN dbo.customer_merge_customer m
                    ON v.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.vendor_customer
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- customer
            INSERT INTO eCommerce_archive.dbo.customer(customer_id, first_name, middle_name, last_name, title, opt_in, insert_date, insert_by, modified_date, modified_by, salesforce_contact_id, person_id)
            SELECT c.customer_id, c.first_name, c.middle_name, c.last_name, c.title, c.opt_in, c.insert_date, c.insert_by, c.modified_date, c.modified_by, c.salesforce_contact_id, c.person_id
            FROM dbo.customer c
                INNER JOIN dbo.customer_merge_customer m
                    ON c.customer_id = m.customer_id
            WHERE m.customer_merge_id = @customer_merge_id

            DELETE FROM dbo.customer
            WHERE customer_id IN (
                SELECT customer_id
                FROM dbo.customer_merge_customer
                WHERE customer_merge_id = @customer_merge_id
            )

            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
            -- 3.) update customer_merge and add comment
            -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

            -- 3.1) insert comment
            INSERT INTO dbo.csi_comments (subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id, refund_reason_code, csi_users_id)
            VALUES ('Customer merge:', 'Customer merge via CSI', GETDATE(), @modified_by, @master_customer_id, NULL, NULL, 0, @modified_by)
    
            -- 3.2) 
            UPDATE dbo.customer_merge
            SET merge_status_id = 1, modified_date = GETDATE(), modified_by = @modified_by
            WHERE customer_merge_id = @customer_merge_id

            -- 3.3) return success
            SELECT response_code = 0, message = 'Customer successfully merged'

        COMMIT TRANSACTION merge_customer
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION merge_customer

        SET @response_code = -200
        SET @message = 
            CASE 
                WHEN @message IS NULL THEN 'customer merge failed for customer_merge_id: ' + CONVERT(VARCHAR(20),@customer_merge_id)
                ELSE @message
            END

        DECLARE @DBName NVARCHAR(128)
        SET @DBName = DB_NAME()
        EXEC dbo.usp_LogError @ErrorDB = @DBName
    END CATCH;
END


GO
