CREATE   PROCEDURE [dbo].[usp_customer_select]
(
    @customer_id INT = NULL,
    @salesforce_contact_id VARCHAR(18) = NULL
)

/*	
	DATE			AUTHOR		REMARKS
	2006-08-16		tblazek		Initial creation.
	2006-08-21		tblazek		Per ticket 4885, remove type id
	2006-08-27		tblazek		Per ticket 4885, remove language_id, vendor_id and vendor_customer_code
	2009-06-17		esmart		Customer merge changes
	2012-01-18		esmart		Add customer vat_id
	2013-08-06		esmart		Add SFDC support
	2014-03-06		esmart		Extend
	2014-11-13		esmart		Add @salesforce_contact_id
	2018-06-12		acoffel		add person id
	2019-07-16		esmart		company_id
	2020-11-03		abelenkiy	updated to use company_vat instead of customer_vat
	2021-02-08		abelenkiy	Added safe_account_user_guid and wrapped proc in begin/end
	2021-12-28		abelenkiy	Removed customer_vat reference
	2024-09-20      lpraharsha  https://jira.opentext.com/browse/ECOM-5185 added phone number in select statement so that it can be used by php as part of  sky provisoning
	DESCRIPTION
	Return customer data result set to PHP code

*/

AS
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
BEGIN

    SET NOCOUNT ON;

    DECLARE @vendor_customer_code VARCHAR(100),
            @partner_id INT,
            @phone_number VARCHAR(20);

    -- 1.1) @salesforce_contact_id 
    IF @salesforce_contact_id IS NOT NULL
       AND @customer_id IS NULL
    BEGIN
        -- 1.1.1) check length
        IF LEN(@salesforce_contact_id) = 15
        BEGIN
            SELECT @salesforce_contact_id = dbo.fn_ConvertSalesforceID_15to18(@salesforce_contact_id);
        END;

        -- 1.1.2) @customer_id
        SELECT @customer_id = customer_id
        FROM dbo.customer
        WHERE salesforce_contact_id = @salesforce_contact_id;
    END;
    --fetching main phone number from customer_phone
    SELECT TOP 1
           @phone_number = cp.phone_number
    FROM dbo.customer_phone cp
    WHERE cp.customer_id = @customer_id
          AND cp.phone_type_id = 1
    ORDER BY cp.modified_date DESC ;
    -- 1.2) @vendor_customer_code, @partner_id
    SELECT @vendor_customer_code = t.vendor_customer_code,
           @partner_id = t.partner_id
    FROM
    (
        SELECT TOP 1
               vendor_customer_id,
               vendor_customer_code,
               partner_id
        FROM dbo.vendor_customer
        WHERE customer_id = @customer_id
        ORDER BY insert_date DESC
    ) t;

    -- 1.3) results
    SELECT c.customer_id,
           vendor_customer_code = @vendor_customer_code,
           partner_id = @partner_id,
           c.salesforce_contact_id,
           c.first_name,
           c.middle_name,
           c.last_name,
           c.title,
           c.opt_in,
           ce.customer_email_id AS 'email_id',
           ce.customer_email AS 'email',
           ce.customer_email,
           co.company_id,
           company_name = CASE
                              WHEN co.company_name IS NULL THEN
                                  cc.company_name
                              ELSE
                                  co.company_name
                          END,
           company_type_id = CASE
                                 WHEN co.company_type_id IS NULL THEN
                                     cc.company_type_id
                                 ELSE
                                     co.company_type_id
                             END,
           company_type_name = CASE
                                   WHEN co.company_type_id IS NULL THEN
                                       cct.company_type_name
                                   ELSE
                                       t.company_type_name
                               END,

           co.salesforce_account_id,
           co.oracle_customer_id,
           c.insert_date,
           cv.vat_id,
           @phone_number AS phone_number,
           c.person_id,
           sauc.safe_account_user_guid
    FROM dbo.customer c
        LEFT JOIN dbo.customer_email ce
            ON c.customer_id = ce.customer_id
               AND ce.email_status_id = 1
        LEFT JOIN dbo.customer_company cc
            ON c.customer_id = cc.customer_id
        LEFT JOIN dbo.customer_address ca
            ON ca.customer_id = c.customer_id
               AND ca.address_status_id = 1
               AND ca.address_type_id = 1
        LEFT JOIN dbo.company_vat cv
            ON cc.company_id = cv.company_id
               AND ca.country_id = cv.country_id
        LEFT JOIN dbo.company_type cct
            ON cc.company_type_id = cct.company_type_id
        LEFT JOIN dbo.company co
            ON cc.company_id = co.company_id
        LEFT JOIN dbo.company_type t
            ON co.company_type_id = t.company_type_id
        LEFT JOIN dbo.safe_account_user_customer sauc
            ON sauc.customer_id = c.customer_id
    WHERE c.customer_id = @customer_id;

END;


GO
