CREATE PROCEDURE [dbo].[usp_customer_select_accounts]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-05-02	esmart		Initial creation.

	DESCRIPTION
	select accounts by customer_id
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select a.account_id, a.account_user_name, s.account_status_id, s.account_status, t.account_type_id, t.account_type_description
	from account_customer c
	inner join account a
		on c.account_id = a.account_id
	inner join account_status s
		on a.account_status_id = s.account_status_id
	inner join account_type t
		on a.account_type_id = t.account_type_id
	where c.customer_id = @customer_id and a.account_status_id <> 2

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
