CREATE PROCEDURE [dbo].[usp_customer_select_address]

(
	@customer_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2006-08-15		tblazek		Initial creation
	2009-06-10		esmart		Add address_status and maintenance of address status if values are null
	2020-08-20		abelenkiy	Removed logic dealing with null statuses since all null customer_address statuses have now been fixed
								Streamlined to select data without staging since not manipulation now has to be done; added BEGIN/END

	DESCRIPTION
	Return customer address result set to PHP code

*/

as

begin

	-- 1) select data

	select ca.customer_id, ca.customer_address_id, ca.address_type_id, at.address_type_description, ca.address_1, ca.address_2, ca.address_3, ca.city, ca.state, s.state_iso3, 
		s.description as state_description,	ca.postal_code, ca.country_id, c.description as country_description, ca.address_status_id, st.address_status, ca.insert_date
	from customer_address ca
	inner join address_type at
		on ca.address_type_id = at.address_type_id
	inner join address_status st
		on ca.address_status_id = st.address_status_id
	left join lu_countries c
		on c.country_id = ca.country_id
	left join lu_states s
		on ca.state = s.state_id and s.iso2 = c.iso
	where ca.address_status_id = 1
		and ca.customer_id = @customer_id
	order by ca.address_type_id asc
	
end


GO
