CREATE PROCEDURE [dbo].[usp_customer_select_address_both_types]

(
	@customer_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2013-07-10		acoffel		Initial creation
	2020-05-07		esmart		Fix defect
	

*/

AS

	-- 1) create table variable with the address_data
		declare @customer_address table ([customer_address_id] [int] identity(1,1),
										[customer_id] [int],
										[address_type_id] [int],
										[address_type_description] [varchar](50),
										[address_1] [nvarchar](255),
										[address_2] [nvarchar](255),
										[address_3] [nvarchar](255),
										[city] [nvarchar](130),
										[state] [nvarchar](2),
										[postal_code] [nvarchar](32),
										[country_id] [smallint],
										[address_status_id] [tinyint],
										[address_status] [varchar](20),
										[insert_date] [datetime])	

		insert into @customer_address (customer_id,address_type_id,address_type_description,address_1,address_2,address_3,city,state,postal_code,country_id,address_status_id,address_status, insert_date)
		select 	a.customer_id,t.address_type_id,t.address_type_description,address_1,address_2,address_3,city,state,postal_code,country_id,s.address_status_id,s.address_status, a.insert_date
		from customer_address a
		inner join address_type t
			on a.address_type_id = t.address_type_id
		left join address_status s
			on a.address_status_id = s.address_status_id
		where customer_id = @customer_id and a.address_status_id = 1
		order by a.address_type_id asc, a.address_status_id asc, a.customer_address_id desc

		-- 2) find active type and then get most recent opposite type
		if @@ROWCOUNT = 1
			begin
			insert into @customer_address (customer_id,address_type_id,address_type_description,address_1,address_2,address_3,city,state,postal_code,country_id,address_status_id,address_status, insert_date)
			select customer_id,address_type_id = case when address_type_id = 1 then 2 else 1 end,
			address_type_description = case when address_type_id = 1 then 'Ship to' else 'Bill to' end,
			address_1,address_2,address_3,city,state,postal_code,country_id,address_status_id,address_status, insert_date
			from @customer_address		
			end
				
	-- 3) select the data
	select customer_address_id,customer_id,address_type_id,address_type_description,address_1,address_2,address_3,city,state, state_iso3, state_description = s.description, postal_code,a.country_id, country_description = c.description,address_status_id,address_status,insert_date
	from @customer_address a
	left join lu_countries c
		on c.country_id = a.country_id
	left join lu_states s
		on a.state = s.state_id and s.iso2 = c.iso
	order by a.address_type_id




GO
