CREATE proc [dbo].[usp_customer_select_by_email]
	@email varchar(100),
	@max_customer_look_up BIT = NULL

AS
/*
DATE 		AUTHOR 		REMARKS
2006-09-20	D. Brendle	initial creation. See ticket 5325
2006-09-22	Tblazek		Change the name of the procedure in the script and re-compile
2018-06-14	acoffel		person_id

DESCRIPTION
Return information for customer by looking up email address


Input parameters:
	@email varchar(100) -- email address of customer to search

Output Parameters:
	None

Result Set Parameters:
	  customer_id
	  first_name
	  middle_name
	  last_name
	  title
	  opt_in
	  email_id 
	  email 
	  company_id 
	  company_name 
	  language_id 
	  vendor_id

*/

	set nocount on
	
	declare	@email_domain varchar(100),
			@response_code int,
			@message varchar(100),
			@max_customer_id INT 

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @customers table (customer_id int,first_name nvarchar(225),middle_name nvarchar(32),last_name nvarchar(225),title nvarchar(50),opt_in int,customer_email_id int,customer_email varchar(100),customer_company_id int,company_name nvarchar(255),language_id int,vendor_id INT, person_id int)

	insert into @customers(customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id, person_id)
	select c.customer_id,c.first_name,c.middle_name,c.last_name,c.title,c.opt_in,ce.customer_email_id,ce.customer_email,cc.customer_company_id,cc.company_name,cl.language_id,vc.vendor_id, c.person_id 
	from customer c with (nolock)
	join customer_email ce with (nolock)
		on ce.customer_id = c.customer_id
	left join customer_language cl with (nolock)
		on cl.customer_id = c.customer_id
	left outer join customer_company cc with (nolock)
		on cc.customer_id = c.customer_id
	left outer join vendor_customer vc with (nolock)
		on vc.customer_id = c.customer_id
	where ce.customer_email = @email and ce.email_status_id = 1

	if (select count(*) from @customers) = 0
		begin 
		
		select @email_domain=SUBSTRING(@email,CHARINDEX('@',@email)+1,len(@email))

		--select email_domain = @email_domain

		-- select @email_domain = '%'+@email_domain+'%'

		declare @domain_emails int
		
		select @domain_emails = count(*)
		from customer_email
		where email_domain = @email_domain
		
		--print @email_domain
		--print @domain_emails
		-- select * from @customers

		if @domain_emails <= 20
			begin

				insert into @customers(customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id, person_id)
				select c.customer_id,c.first_name,c.middle_name,c.last_name,c.title,c.opt_in,ce.customer_email_id,ce.customer_email,cc.customer_company_id,cc.company_name,cl.language_id,vc.vendor_id, c.person_id 
				from customer_email ce
				inner join customer c with (nolock)
					on ce.customer_id = c.customer_id
				left join customer_language cl with (nolock)
					on cl.customer_id = c.customer_id
				left outer join customer_company cc with (nolock)
					on cc.customer_id = c.customer_id
				left outer join vendor_customer vc with (nolock)
					on vc.customer_id = c.customer_id
				where ce.email_domain = @email_domain and ce.email_status_id = 1
			end

		end
		 
	-- ----------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------
	-- 2.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @max_customer_look_up is not null
		begin 
			select @max_customer_id = max(customer_id) from @customers
			select distinct customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id, person_id
			from @customers
			where customer_id = @max_customer_id
		end 
		else 
		begin 
			select distinct customer_id, first_name, middle_name, last_name, title, opt_in, customer_email_id, customer_email, customer_company_id, company_name, language_id, vendor_id, person_id
			from @customers
		end
        

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
