-- PROCEDURE: [dbo].[usp_customer_select_code]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_customer_select_code]

	(
		@vendor_customer_code varchar(100),
		@vendor_id int,
		@partner_id int = null
	)

/*	
		DATE		AUTHOR	REMARKS
		2006-09-11	tblazek		Initial creation.
		2006-09-12	tblazek		Per ticket 5222, add vendor_id to input params and where clause

		DESCRIPTION
		Return customer data result set to PHP code

*/

AS

SET NOCOUNT ON

if @partner_id is null
	begin
			select 	c.customer_id,
					c.first_name,
					c.middle_name,
					c.last_name,
					c.title,
					c.opt_in,		
					ce.customer_email_id as 'email_id',
					ce.customer_email as 'email',
					cc.customer_company_id as 'company_id',
				cc.company_name
			from customer c
			join customer_email ce
				on c.customer_id = ce.customer_id
			left outer join	customer_company cc
				on c.customer_id = cc.customer_id
			join vendor_customer vc
				on vc.customer_id = c.customer_id
			where vc.vendor_customer_code = @vendor_customer_code
					and vc.vendor_id = @vendor_id
					and ce.email_status_id = 1
	end
else
	begin
			select 	c.customer_id,
						c.first_name,
						c.middle_name,
						c.last_name,
						c.title,
						c.opt_in,		
						ce.customer_email_id as 'email_id',
						ce.customer_email as 'email',
						cc.customer_company_id as 'company_id',
					cc.company_name
				from customer c
				join customer_email ce
					on c.customer_id = ce.customer_id
				left outer join	customer_company cc
					on c.customer_id = cc.customer_id
				join vendor_customer vc
					on vc.customer_id = c.customer_id
				where vc.vendor_customer_code = @vendor_customer_code
						and vc.partner_id = @partner_id
						and ce.email_status_id = 1
	end

	






GO
