CREATE PROCEDURE [dbo].[usp_customer_select_customer_merge]

(
		@customer_merge_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-01	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) gather data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select customer_id = master_customer_id, type = 'master'
	from customer_merge
	where customer_merge_id = @customer_merge_id
	union
	select customer_id, type = 'merge'
	from customer_merge_customer
	where customer_merge_id = @customer_merge_id

	end try
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select customer merge failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
