-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_select_email_verification]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_customer_select_email_verification]

(
	@customer_email VARCHAR(100) 
)

/*	
	DATE			AUTHOR		REMARKS
	2018-10-17		mrobbins	intial creation
	2020-06-08		mrobbins	added case statement to check status against webbula again WATERBEARS-345

	DESCRIPTION
	Returns status if customer has already been verified

*/

AS

SET NOCOUNT ON

	BEGIN TRY 

		DECLARE	@response_code INT,
			@message VARCHAR(100),
			@customer_email_out VARCHAR(100),
			@status VARCHAR(100)

		IF (SELECT COUNT(*) FROM customer_email_verification cev
			INNER JOIN dbo.customer_email_verification_status cevs
				ON cev.customer_email_verification_status_id = cevs.customer_email_verification_status_id
		WHERE cev.customer_email = @customer_email) = 0
			BEGIN
				SET @customer_email_out = @customer_email
				SET @status = 'Unverified'
			END 
		ELSE 
			BEGIN
				SELECT @customer_email_out = @customer_email,
					@status = CASE WHEN SUBSTRING(customer_email,CHARINDEX('@',customer_email,1) + 1,LEN(customer_email)) NOT IN ('AOL.com','att.net','bellsouth.net','centurytel.net','Comcast.com','Comcast.net','cox.net','earthlink.com','earthlink.net','Gmail.com','hotmail.com',
								'hughes.net','HUGHESNET.COM','icoud.com','live.com','mail.com','MSN.com','netzero.com','none.com','optonline.net','Outlook.com','Outlook.net','sbcglobal.net','surfglobal.net','verizon.net','Yahoo.com','Yahoomail.com')
								AND cevs.webroot_status = 'invalid' THEN 
									'Unverified'
							ELSE 
								cevs.webroot_status
							END
				FROM dbo.customer_email_verification cev
					INNER JOIN dbo.customer_email_verification_status cevs
						ON cev.customer_email_verification_status_id = cevs.customer_email_verification_status_id
				WHERE cev.customer_email = @customer_email

			END 
		
		SELECT @customer_email_out customer_email_out,
			@status [status]
		

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select next email record failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;



SET ANSI_NULLS ON

GO
