CREATE PROCEDURE [dbo].[usp_customer_select_license_orders]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-10	esmart		Initial creation

	DESCRIPTION
*/

AS

	select l.license_id, l.keycode, h.vendor_order_date, i.product_id
	from customer_order o
	inner join order_header h
		on o.order_header_id = h.order_header_id
	inner join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	inner join order_item i
		on h.order_header_id = i.order_header_id
	inner join order_item_license il
		on i.order_item_id = il.order_item_id
	inner join license l
		on il.license_id = l.license_id
	where o.customer_id = @customer_id

	

	

GO
