CREATE PROCEDURE [dbo].[usp_customer_select_licenses]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-10	esmart		Initial creation
	2014-09-22	esmart		Extend additional columns

	DESCRIPTION
*/

AS

	select l.license_id, 
		l.keycode, 
		l.customer_id, 
		p.product_line_id, p.product_line_description, p.product_line_prefix, 
		s.license_status_id, 
		s.license_status_description,
		t.license_type_id, 
		t.license_type_description,
		l.license_distribution_method_id, 
		l.license_keycode_type_id, 
		c.license_category_id,
		c.license_category_name,
		lc.capability_activation_days,
		lc.capability_activation_date,
		lc.capability_expiration_date,
		l.max_daily_activations, 
		l.max_child_licenses, 
		l.license_expiration_date, 
		l.insert_date, 
		l.insert_by, 
		l.modified_date, 
		l.modified_by
	from license l
	inner join product_line p
		on l.product_line_id = p.product_line_id
	left join license_category_license cl
		on l.license_id = cl.license_id
	left join license_category c
		on cl.license_category_id = c.license_category_id
	left join license_capability lc
		on l.license_id = lc.license_id and lc.capability_id = c.base_capability_id
	inner join license_status s
		on l.license_status_id = s.license_status_id
	inner join license_type t
		on l.license_type_id = t.license_type_id
	where l.customer_id = @customer_id
	order by lc.capability_expiration_date desc, l.license_id desc

	


GO
