CREATE      PROCEDURE usp_customer_select_lookup
@first_name nvarchar(255),
@last_name nvarchar(255),
@email varchar(100),
@company_name  nvarchar(255) = null

/*	
	DATE		AUTHOR	REMARKS
	2006-08-16	tblazek		Initial creation.
	2006-08-21	tblazek		Per ticket 4886, remove type id
	2006-08-27	tblazek		Per ticket 4886, remove language_id, vendor_id and vendor_customer_code from result set

	DESCRIPTION
	Return customer data result set to PHP code

INPUT:
first_name (required)
last_name (required)
email (required)
company_name (allow nulls)


Result set:
customer_id
first_name
middle_name
last_name
title
opt_in
email_id (from customer_email.customer_email_id)
email (from customer_email.customer_email)
company_id (from customer_company.customer_company_id)
company_name (from customer_company.company_name)
language_id (from customer_language.customer_language_id)
vendor_id
*/

AS

	select 	c.customer_id,
		c.first_name,
		c.middle_name,
		c.last_name,
		c.title,
		c.opt_in,		
		ce.customer_email_id as 'email_id',
		ce.customer_email as 'email',
		cc.customer_company_id as 'company_id',
		cc.company_name --,
--		cl.language_id,
	--	ctc.customer_type_id as 'type_id',
	--	vc.vendor_customer_code,
	--	vc.vendor_id
	from 	customer c
	join	customer_email ce
	on	c.customer_id = ce.customer_id
	left outer join	customer_company cc
	on	c.customer_id = cc.customer_id
--	left outer join	customer_language cl
--	on 	c.customer_id = cl.customer_id
--	join	customer_type_customer ctc
--	on	c.customer_id = ctc.customer_id
--	join 	vendor_customer vc
--	on	c.customer_id = vc.customer_id
	where 	c.first_name = @first_name
	and	c.last_name = @last_name
	and 	ce.customer_email = @email
	and 	ce.email_status_id = 1




GO
