CREATE        PROCEDURE [dbo].[usp_customer_select_non_ss_license_ids] 
@customer_id int

/*	
	DATE		AUTHOR	REMARKS
	2006-08-30	tblazek		Initial creation.
	2006-09-25	tblazek		Change product_line_id to product_line_prefix in where clause

	DESCRIPTION
	Return license_id result set for customer_id where license not SS to PHP code

INPUT:
customer_id


*/

AS

	select 	l.license_id
	from 	license  l
