CREATE PROCEDURE [dbo].[usp_customer_select_orders]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-06-10	esmart		Initial creation
	2015-09-10	esmart		Add currency

	DESCRIPTION
*/

AS

	select v.vendor_order_code, oh.order_header_id, oh.total_amount, oh.sub_total_amount, oh.tax_total, cu.currency_id, c.currency_code, c.symbol_html, c.symbol_utf8, c.symbol_text,  oh.vendor_order_date, oh.locale, oh.site_id, oh.site_url, oh.order_status_id, oh.insert_date
	from vendor_order v
