-- =============================================================================
-- PROCEDURE: [dbo].[usp_customer_select_search_result_count]
-- =============================================================================

CREATE PROCEDURE dbo.usp_customer_select_search_result_count

(	
	@first_name nvarchar(225),
	@last_name nvarchar(225),
	@customer_email varchar(255),
	@company_name varchar(255),
	@vendor_customer_code varchar(100),
	@response_code int output,
	@message varchar(100) output
)

AS
	set nocount on
	
	if @first_name is null set @first_name = ''
	if @last_name is null set @last_name = ''
	if @customer_email is null set @customer_email = ''
	if @company_name is null set @company_name = ''
	if @vendor_customer_code is null set @vendor_customer_code = ''
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check for minimum search terms	
	--	NOTE: need to better flush out what restriction we need to make
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if (len(@customer_email) < 1 and len(@first_name) < 1 and len(@last_name) < 1 and len(@company_name) < 1 and len(@vendor_customer_code) < 1)
		--or (@customer_email is null and @first_name is null and @last_name is null and @company_name is null and @vendor_customer_code is null)
		begin
			set @response_code = -100
			set @message = 'Minimum search term violation'
			return
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return list of customer_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	if len(@vendor_customer_code) > 0 
		--or @vendor_customer_code is not null
		--CUSTOMER CODE
		begin
			--print '(CUSTOMER CODE)'
			select count(customer_id) as customer_count
			from vendor_customer WITH (NOLOCK)
			where vendor_customer_code = @vendor_customer_code
		end
	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) > 1 and len(@company_name) > 1)
		--or ((@first_name is not null or @last_name is not null) and @customer_email is not null and @company_name is not null)
		--FIRSTLAST EMAIL COMPANYNAME
		begin
			--print '(FIRSTLAST EMAIL COMPANYNAME)'
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @customer_email = @customer_email + '%'
			set @company_name = @company_name + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_email as ce with (NOLOCK) on c.customer_id = ce.customer_id and ce.email_status_id = 1
				join customer_company as cc with (NOLOCK) on c.customer_id = cc.customer_id
			where c.first_name like @first_name and c.last_name like @last_name
				and ce.customer_email like @customer_email
				and cc.company_name like @company_name
		end
		
	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) > 1 and len(@company_name) = 0)
		--or ((@first_name is not null or @last_name is not null) and @customer_email is not null and @company_name is null)
		--FIRSTLAST EMAIL
		begin
			--print '(FIRSTLAST EMAIL)'
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @customer_email = @customer_email + '%'

			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_email as ce with (NOLOCK) on c.customer_id = ce.customer_id and ce.email_status_id =
 1
			where c.first_name like @first_name and c.last_name like @last_name
				and ce.customer_email like @customer_email
		end

	else if ((len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) < 1 and len(@company_name) < 1)
		--or ((@first_name is not null or @last_name is not null) and @customer_email is null and @company_name is null)
		--FIRSTLAST
		begin
			--print '(FIRSTLAST)'
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
			where c.first_name like @first_name and c.last_name like @last_name
		end
	else if ((len(@first_name) = 0  and len(@last_name) = 0) and len(@customer_email) > 1 and len(@company_name) > 1)
		--or ((@first_name is null and @last_name is null) and @customer_email is not null and @company_name is not null)
		--EMAIL COMPANYNAME
		begin
			-- print'(EMAIL COMPANYNAME)'
			set @customer_email = @customer_email + '%'
			set @company_name = @company_name + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_email as ce with (NOLOCK) on c.customer_id = ce.customer_id and ce.email_status_id = 1
				join customer_company as cc with (NOLOCK) on c.customer_id = cc.customer_id
			where ce.customer_email like @customer_email
				and cc.company_name like @company_name
		end
	else if ((len(@first_name) = 0 and len(@last_name) = 0) and len(@customer_email) = 0 and len(@company_name) > 1)
		--or ((@first_name is null and @last_name is null) and @customer_email is null and @company_name is not null)
		--COMPANYNAME
		begin
			--print '(COMPANYNAME)'
			set @company_name = @company_name + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_company as cc with (NOLOCK) on c.customer_id = cc.customer_id
			where cc.company_name like @company_name
		end
	else if (len(@first_name) > 1 or len(@last_name) > 1) and len(@customer_email) = 0 and len(@company_name) > 1
		--or ((@first_name is not null or @last_name is not null) and @customer_email is null and @company_name is not null)
		--FIRSTLAST COMPANYNAME
		begin
			--print '(FIRSTLAST COMPANYNAME)'
			set @first_name = @first_name + '%'
			set @last_name = @last_name + '%'
			set @company_name = @company_name + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_company as cc with (NOLOCK) on c.customer_id = cc.customer_id
			where c.first_name like @first_name and c.last_name like @last_name
				and cc.company_name like @company_name
		end
	else if ((len(@first_name) = 0 and len(@last_name) = 0) and len(@customer_email) > 1 and len(@company_name) = 0)
		--or ((@first_name is null and @last_name is null) and @customer_email is not null and @company_name is null)
		--EMAIL
		begin
			--print '(EMAIL)'
			set @customer_email = @customer_email + '%'
			
			select count(c.customer_id) as customer_count
			from customer as c WITH (NOLOCK)
				join customer_email as ce with (NOLOCK) on c.customer_id = ce.customer_id and ce.email_status_id = 1
			where ce.customer_email like @customer_email
		end
		

	if @@error > 0
		begin
			set @response_code = -300
			set @message = 'General SQL select error'
			return
		end




GO
