CREATE PROCEDURE [dbo].[usp_customer_select_ss_license_ids] 

(
	@customer_id int
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-30	tblazek		Initial creation.
	2006-09-05	esmart		Modified query to only one row per license (removed join to license_activity)

	DESCRIPTION
	Return license_id result set for customer_id to PHP code

*/

AS

	select 	l.license_id
	from 	license l
	join product_line pl
		on pl.product_line_id = l.product_line_id
	where 	customer_id = @customer_id and pl.product_line_prefix in ('SS', 'SA','AF','AD')
	order by l.insert_date  desc



GO
