-- PROCEDURE: [dbo].[usp_cybs_select_customer_profile_by_license_id]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_cybs_select_customer_profile_by_license_id]

(
	@license_id int 
)


/*	
	DATE			AUTHOR				REMARKS
	2007-06-11		Randall Gaz			Initial creation
    2009-02-24		Randall Gaz			Include the invoice_in_process_id field
	2009-10-27		esmart				Add support for new order_customer_profile_token table
    
	DESCRIPTION
	select last customer profile inserted for the license_id

*/

AS
	
	declare @cybs_customer_profile_id int, 
			@customer_profile_token varchar(24), 
			@invoice_in_process_id int

	
	-- 1) select data from legacy tables	
		select @cybs_customer_profile_id = t.cybs_customer_profile_id,
				@customer_profile_token = t.customer_profile_token,
				@invoice_in_process_id = t.invoice_in_process_id
		from (select top 1 cp.cybs_customer_profile_id, cp.customer_profile_token, cp.invoice_in_process_id 
				from cybs_customer_profile cp
				join cybs_customer_profile_license cpl 
					on cpl.cybs_customer_profile_id = cp.cybs_customer_profile_id
				where cpl.license_id = @license_id
				order by cpl.insert_date desc) t

	-- 2) if profile does not exist in legacy tables then check new table
	if @customer_profile_token is null
		begin
		select @cybs_customer_profile_id = t.cybs_customer_profile_id,
				@customer_profile_token = t.customer_profile_token,
				@invoice_in_process_id = t.invoice_in_process_id
		from (select top 1 cybs_customer_profile_id = pt.order_customer_profile_token_id,
					pt.customer_profile_token,
					invoice_in_process_id = pt.order_header_id
				from order_item_license il
				inner join order_item i
					on il.order_item_id = i.order_item_id
				inner join order_customer_profile_token pt
					on i.order_header_id = pt.order_header_id
				where il.license_id = @license_id
				order by pt.order_customer_profile_token_id desc) t
		end
		
	-- 3) select results
	select cybs_customer_profile_id = @cybs_customer_profile_id,
			customer_profile_token = @customer_profile_token,
			invoice_in_process_id = @invoice_in_process_id



GO
