-- =============================================================================
-- PROCEDURE: [dbo].[usp_dish_license_subscription_select_history]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dish_license_subscription_select_history]

(
	@dish_license_subscription_id int
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2017-02-27		acoffel		Initial creation.
		

	DESCRIPTION
	dish status and history
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  get history and master record
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @dish_license_subscription_history table (dish_license_subscription_id int NOT NULL, license_id int NOT NULL, dish_guid varchar(50) NOT NULL, customer_code varchar(15), customer_type varchar(15) NULL, customer_status varchar(15) NULL, protection_plan_add_date datetime NULL,
											protection_plan_tier varchar(50) NULL, promotional_period_end_date datetime NULL, plan_drop_date datetime NULL, history_date datetime NULL)


	-- 1.1) subscription_history
	insert into @dish_license_subscription_history(dish_license_subscription_id, license_id, dish_guid, customer_code, customer_type, customer_status, protection_plan_add_date,protection_plan_tier, promotional_period_end_date, plan_drop_date, history_date)
	select d.dish_license_subscription_id, d.license_id, d.dish_guid, d.customer_code, ct.customer_type, cs.customer_status, d.protection_plan_add_date, t.protection_plan_tier, d.promotional_period_end_date, d.plan_drop_date, d.last_modified_date
	from dish_license_subscription_history d
	inner join license l
		on d.license_id = l.license_id 
	left join dish_customer_type ct
		on d.dish_customer_type_id = ct.dish_customer_type_id 
	left join dish_customer_status cs
		on d.dish_customer_status_id = cs.dish_customer_status_id
	left join dish_protection_plan_tier t
		on d.dish_protection_plan_tier_id = t.dish_protection_plan_tier_id
	where d.dish_license_subscription_id = @dish_license_subscription_id

	-- 1.2) subscription_message_history
	insert into @dish_license_subscription_history(dish_license_subscription_id, license_id, dish_guid, customer_code, customer_type, customer_status, protection_plan_add_date,protection_plan_tier, promotional_period_end_date, plan_drop_date, history_date)
	select d.dish_license_subscription_id, d.license_id, d.dish_guid, d.customer_code, ct.customer_type, cs.customer_status, d.protection_plan_add_date, t.protection_plan_tier, d.promotional_period_end_date, d.plan_drop_date, d.last_modified_date
	from dish_license_subscription d 
	inner join license l
		on d.license_id = l.license_id
	left join dish_customer_type ct
		on d.dish_customer_type_id = ct.dish_customer_type_id 
	left join dish_customer_status cs
		on d.dish_customer_status_id = cs.dish_customer_status_id
	left join dish_protection_plan_tier t
		on d.dish_protection_plan_tier_id = t.dish_protection_plan_tier_id
	where d.dish_license_subscription_id = @dish_license_subscription_id

	select * from @dish_license_subscription_history order by history_date desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
