-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dish_license_subscription_select_license]

(
	@customer_code varchar(15)
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2017-02-27		acoffel		Initial creation.
		

	DESCRIPTION
	dish license lookup
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	select d.dish_license_subscription_id, l.keycode, d.license_id, d.customer_code  --,d.dish_guid, ct.customer_type, cs.customer_status, d.protection_plan_add_date, t.protection_plan_tier, d.promotional_period_end_date, d.plan_drop_date, d.last_modified_date
	from dish_license_subscription d 
	inner join license l
		on d.license_id = l.license_id
	left join dish_customer_type ct
		on d.dish_customer_type_id = ct.dish_customer_type_id 
	left join dish_customer_status cs
