							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dish_license_subscription_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dish_license_subscription_update]

	
/*	
	DATE			AUTHOR			REMARKS
	2017-02-24		acoffel			Initial creation
	2017-04-21		acoffel			plan add date adjustments with Wes
	2017-05-01		acoffel			promo end date adjustments with Wes
	2020-04-29		wbarton			Changes to 4.3 and 5.1 to use license service in order to fix a bug where disabled licenses that were never used would be re-enabled without any activation/expiration being set and interfaced to Sky
	
	DESCRIPTION
	Performs daily license and dish_license_subscription management activities
*/

as

set nocount on	

	declare	@response_code int,
			@message varchar(100),
			@account_name varchar(50) = 'dish_integration',
			@expiration_date datetime = dateadd(year, 1, getdate()),
			@service_json nvarchar(max),
			@loop_value int,
			@loop_max int

	declare @license_enable table (
		id int identity(1,1),
		license_id int,
		keycode varchar(40),
		license_category_name varchar(10)
	)

	declare @license_disable table (
		id int identity(1,1),
		license_id int,
		keycode varchar(40),
		license_category_name varchar(10)
	)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert into working @dish_license_subscription
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	declare @dish_license_subscription table (license_id int NOT NULL, customer_code varchar(15), dish_guid varchar(50) NOT NULL, dish_customer_type_id int NULL, dish_customer_status_id int NULL, protection_plan_add_date datetime NULL,
											dish_protection_plan_tier_id int NULL, in_promotional_period varchar(50) NULL, plan_drop_date datetime NULL)



	insert into @dish_license_subscription (license_id, customer_code, dish_guid, dish_customer_type_id, dish_customer_status_id, protection_plan_add_date, dish_protection_plan_tier_id, in_promotional_period, plan_drop_date)
	select r.license_id, r.customer_code, r.dish_guid, ct.dish_customer_type_id, case when cs.dish_customer_status_id is NULL then 1 else cs.dish_customer_status_id end, case when r.protection_plan_add_date = '' then NULL else convert(datetime,r.protection_plan_add_date) end, t.dish_protection_plan_tier_id, r.in_promotional_period, case when r.plan_drop_date = '' then NULL else convert(datetime,r.plan_drop_date) end 
	from datawarehousereadonly.feed.dbo.dish_license_subscription_raw r
	left join dish_customer_type ct
		on r.customer_type = ct.customer_type 
	left join dish_customer_status cs
		on r.customer_status = cs.customer_status
	left join dish_protection_plan_tier t
		on r.protection_plan_tier = t.protection_plan_tier
	where r.license_id is not NULL

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert into dish_license_subscription when new
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--2.1) get new records
	insert into dish_license_subscription (license_id, customer_code, dish_guid, dish_customer_type_id, dish_customer_status_id, protection_plan_add_date, dish_protection_plan_tier_id, promotional_period_end_date, plan_drop_date, install_date, last_deactivation_date, insert_date, insert_by, last_modified_date, last_modified_by)
	select r.license_id, r.customer_code, r.dish_guid
, r.dish_customer_type_id, r.dish_customer_status_id, r.protection_plan_add_date, r.dish_protection_plan_tier_id, case when r.in_promotional_period = 'YES' and r.protection_plan_add_date is not NULL then dateadd(month,6,r.protection_plan_add_date) 
																																										    when r.in_promotional_period = 'YES' and r.protection_plan_add_date is NULL then dateadd(month,6,getdate()) else NULL end, 
	r.plan_drop_date, NULL, NULL, getdate(), system_user, getdate(), 'eComWebP'                          
	from @dish_license_subscription r
	left join dish_license_subscription s
		on r.license_id = s.license_id
	where s.license_id is NULL

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.)  drop protection
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--3.1) handle drop protection records - insert hist
	insert into dish_license_subscription_history (dish_license_subscription_id, license_id, customer_code, dish_guid, dish_customer_type_id, dish_customer_status_id, protection_plan_add_date, dish_protection_plan_tier_id, promotional_period_end_date, plan_drop_date, install_date, last_deactivation_date, insert_date, insert_by, last_modified_date, last_modified_by, history_date, history_by)
	select s.dish_license_subscription_id, s.license_id, s.customer_code, s.dish_guid, s.dish_customer_type_id, s.dish_customer_status_id, s.protection_plan_add_date, s.dish_protection_plan_tier_id, s.promotional_period_end_date, s.plan_drop_date, s.install_date, s.last_deactivation_date, s.insert_date, s.insert_by, s.last_modified_date, s.last_modified_by, getdate(), 'eComWebP'
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id = 3


	--3.2) handle drop protection records - update master
	update s
		set s.dish_customer_type_id = r.dish_customer_type_id,
		  s.dish_customer_status_id = r.dish_customer_status_id,
		  s.dish_protection_plan_tier_id = r.dish_protection_plan_tier_id,
		  s.last_deactivation_date = getdate(),
		  s.plan_drop_date = r.plan_drop_date,
		  s.promotional_period_end_date = case when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is not NULL then dateadd(month,6,s.protection_plan_add_date) 
												when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is NULL then dateadd(month,6,s.insert_date)
												when r.in_promotional_period = 'YES' and s.promotional_period_end_date is not NULL THEN s.promotional_period_end_date 
												when in_promotional_period = 'NO' and s.promotional_period_end_date is not NULL then NULL end,
		  s.last_modified_date = getdate(), 
		  s.last_modified_by = 'eComWebP'
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id = 3

	--3.3) insert into cancelation queue
	insert into dish_license_subscription_cancel (license_id, cancel_date, insert_date, insert_by)
	select s.license_id, dateadd(hh,-2,getdate()+3), getdate(), 'eComWebP'
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	left join dish_license_subscription_cancel c
		on r.license_id = c.license_id
	where r.dish_customer_status_id = 3
	and c.license_id is NULL

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.)  update is add/update protect if master is drop protect 
 	-- ----------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

	--4.1) insert hist
	insert into dish_license_subscription_history (dish_license_subscription_id, license_id, customer_code, dish_guid, dish_customer_type_id, dish_customer_status_id, protection_plan_add_date, dish_protection_plan_tier_id, promotional_period_end_date, plan_drop_date, install_date, last_deactivation_date, insert_date, insert_by, last_modified_date, last_modified_by, history_date, history_by)
	select s.dish_license_subscription_id, s.license_id, s.customer_code, s.dish_guid, s.dish_customer_type_id, s.dish_customer_status_id, s.protection_plan_add_date, s.dish_protection_plan_tier_id, s.promotional_period_end_date, s.plan_drop_date, s.install_date, s.last_deactivation_date, s.insert_date, s.insert_by, s.last_modified_date, s.last_modified_by, getdate(), system_user
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id <> 3
	and s.dish_customer_status_id = 3

	--4.2) archive any pending cancelation records
	declare @dish_license_archive_cancel table (license_id int NOT NULL)
	
	insert into @dish_license_archive_cancel (license_id)
	select r.license_id 	
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id <> 3
	and s.dish_customer_status_id = 3
		
		--4.2.1) remove from pending cancel table and archive
		if (select count(*) from @dish_license_archive_cancel) > 0
			begin 
				insert into dish_license_subscription_cancel_archive (license_id, cancel_date, insert_date, insert_by, archive_date)
				select license_id, cancel_date, insert_date, 'acoffel', getdate()
				from dish_license_subscription_cancel
				where license_id in (select license_id from @dish_license_archive_cancel)
				
				delete from dish_license_subscription_cancel
				where license_id in (select license_id from @dish_license_archive_cancel)
			end

	--4.3) Re-enabling licenses that have been previously disabled, and setting their expiration date out 1 year
	insert into @license_enable (license_id, keycode, license_category_name)
	select r.license_id, l.keycode, lc.license_category_name
	from @dish_license_subscription r
		inner join dish_license_subscription s
			on s.license_id = r.license_id
		inner join license l with (nolock)
			on l.license_id = s.license_id
		inner join license_category_license lcl with (nolock)
			on lcl.license_id = l.license_id
		inner join license_category lc
			on lc.license_category_id = lcl.license_category_id
	where r.dish_customer_status_id <> 3 --status from the ETL ingestion is not DROP_PROTECT
		and s.dish_customer_status_id = 3 --status on the master table is DROP_PROTECT
		and l.license_status_id in (2,3) --license is currently disabled

	--4.3.1) Looping over records from the insert above, and calling license service for license_enable		
	if exists (select 1 from @license_enable)
		begin
			select @loop_value = (select min(id) from @license_enable), @loop_max = (select max(id) from @license_enable)

			while @loop_value <= @loop_max
				begin
					select @service_json = (
						select keycode as keycode, @account_name as account_name, license_category_name as [license_category.license_category_name], @expiration_date as [license_category.expiration_date]
						from @license_enable
						where id = @loop_value
					for json path, without_array_wrapper
					)

					exec usp_license_service_insert_service @license_service_type_name = 'license_enable', @service_json = @service_json, @return_license_service_id = 0

					select @service_json = null, @loop_value = @loop_value + 1
				end
		end

	--4.5) handle dropped protection records - update master to active
	update s
		set s.dish_customer_type_id = r.dish_customer_type_id,
		  s.dish_customer_status_id = r.dish_customer_status_id,
		  s.d
ish_protection_plan_tier_id = r.dish_protection_plan_tier_id,
		  s.last_deactivation_date = getdate(),
		  s.plan_drop_date = r.plan_drop_date,
		  s.promotional_period_end_date = case when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is not NULL then dateadd(month,6,s.protection_plan_add_date) 
												when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is NULL then dateadd(month,6,s.insert_date)
												when r.in_promotional_period = 'YES' and s.promotional_period_end_date is not NULL THEN s.promotional_period_end_date 
												when in_promotional_period = 'NO' and s.promotional_period_end_date is not NULL then NULL end,
		  s.last_modified_date = getdate(), 
		  s.last_modified_by = 'eComWebP'
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id <> 3
	and s.dish_customer_status_id = 3

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.)  process license cancelations 
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--5.1) Disabling applicable licenses based on their cancel_date in dish_license_subscription_cancel 
	insert into @license_disable (license_id, keycode, license_category_name)
	select c.license_id, l.keycode, lc.license_category_name
	from dish_license_subscription_cancel c
		inner join license l with (nolock)
			on l.license_id = c.license_id
		inner join license_category_license lcl with (nolock)
			on lcl.license_id = l.license_id
		inner join license_category lc
			on lc.license_category_id = lcl.license_category_id
	where c.cancel_date < getdate()

	--5.1.1) Looping over applicable licenses from the insert above, and calling license service for license_disable
	if exists (select 1 from @license_disable)
		begin
			select @loop_value = (select min(id) from @license_disable), @loop_max = (select max(id) from @license_disable)

			while @loop_value <= @loop_max
				begin
					select @service_json = (
						select keycode as keycode, @account_name as account_name, 'Cancelled by DISH' as comment, license_category_name as [license_category.license_category_name]
						from @license_disable
						where id = @loop_value
					for json path, without_array_wrapper
					)

					exec usp_license_service_insert_service @license_service_type_name = 'license_disable', @service_json = @service_json, @return_license_service_id = 0

					select @service_json = null, @loop_value = @loop_value + 1
				end
		end

	--5.3) archive to dish_license_subscription_cancel_archive
	delete from @dish_license_archive_cancel
	
	insert into @dish_license_archive_cancel (license_id)
	select l.license_id
	from license l
	inner join dish_license_subscription_cancel c
		on l.license_id = c.license_id
	where c.cancel_date < getdate()
	
		--5.3.1) remove from pending cancel table and archive
		if (select count(*) from @dish_license_archive_cancel) > 0
			begin 
				insert into dish_license_subscription_cancel_archive (license_id, cancel_date, insert_date, insert_by, archive_date)
				select license_id, cancel_date, insert_date, 'acoffel', getdate()
				from dish_license_subscription_cancel
				where license_id in (select license_id from @dish_license_archive_cancel)
				
				delete from dish_license_subscription_cancel
				where license_id in (select license_id from @dish_license_archive_cancel)
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.)  process active to
 active updates
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--6.1) insert hist
	insert into dish_license_subscription_history (dish_license_subscription_id, license_id, customer_code, dish_guid, dish_customer_type_id, dish_customer_status_id, protection_plan_add_date, dish_protection_plan_tier_id, promotional_period_end_date, plan_drop_date, install_date, last_deactivation_date, insert_date, insert_by, last_modified_date, last_modified_by, history_date, history_by)
	select s.dish_license_subscription_id, s.license_id, r.customer_code, s.dish_guid, s.dish_customer_type_id, s.dish_customer_status_id, s.protection_plan_add_date, s.dish_protection_plan_tier_id, s.promotional_period_end_date, s.plan_drop_date, s.install_date, s.last_deactivation_date, s.insert_date, s.insert_by, s.last_modified_date, s.last_modified_by, getdate(), system_user
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id <> 3 and s.dish_customer_status_id <> 3 and convert(date,s.insert_date) <= convert(date,getdate()-1)

	--6.2) handle drop protection records - update master
	update s
		set s.dish_customer_type_id = r.dish_customer_type_id,
		  s.dish_customer_status_id = r.dish_customer_status_id,
		  s.dish_protection_plan_tier_id = r.dish_protection_plan_tier_id,
		  s.protection_plan_add_date = case when r.protection_plan_add_date is not NULL then r.protection_plan_add_date else s.protection_plan_add_date end,
		  s.promotional_period_end_date = case when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is not NULL then dateadd(month,6,s.protection_plan_add_date) 
												when in_promotional_period = 'YES' and s.promotional_period_end_date is NULL and s.protection_plan_add_date is NULL then dateadd(month,6,s.insert_date)
												when r.in_promotional_period = 'YES' and s.promotional_period_end_date is not NULL THEN s.promotional_period_end_date 
												when in_promotional_period = 'NO' and s.promotional_period_end_date is not NULL then NULL end,
		  s.plan_drop_date = r.plan_drop_date,
		  s.last_modified_date = getdate(), 
		  s.last_modified_by = 'eComWebP'
	from @dish_license_subscription r
	inner join dish_license_subscription s
		on r.license_id = s.license_id
	where r.dish_customer_status_id <> 3 and s.dish_customer_status_id <> 3 and convert(date,s.insert_date) <= convert(date,getdate()-1)
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.)  update activation date
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--7.1) get install dates
	declare @dish_license_install table (license_id int NOT NULL, install_date datetime NOT NULL)
	
	insert into @dish_license_install (license_id, install_date)
	select s.license_id, install_date = min(a.insert_date)
	from dish_license_subscription s with (nolock)
	inner join license_activation a with (nolock)
		on s.license_id = a.license_id
	where s.install_date is NULL
	group by s.license_id

	--7.2) get install dates
	update s
	set s.install_date = i.install_date
	from dish_license_subscription s 
	inner join @dish_license_install i 
		on s.license_id = i.license_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'dish_license_subscription update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
