CREATE PROCEDURE [dbo].[usp_dr_insert_dr_pricing_update_task]

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select currency
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set nocount on

		-- 1) insert task queue 
	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50)

	select @system_user = suser_sname(),
			@db_name = db_name()

	select @task_number = datediff(dd,getdate(),'2050-01-01')
	select @sql_string = 
			'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
			' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_dr_insert_dr_pricing_update_template''' + ',0,getdate()) '
	--print @sql_string

	exec (@sql_string)

	exec tasks..usp_queue_task @task_number

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
