-- PROCEDURE: [dbo].[usp_dr_load_refund_order_load]
-- =============================================================================

CREATE PROCEDURE usp_dr_load_refund_order_load

/*	
	DATE		AUTHOR			REMARKS
	2014-03-21	mrobbins		Initial creation
	
	DESCRIPTION
	Pulls in refund records from sales_order_load.
*/

AS
BEGIN

	SET NOCOUNT ON;

	declare @refund_id					int,
		@max_refund_id					int,
		@order_header_id				int,
		@vendor_order_code				nvarchar(100),
		@cart_order_id_in_process		int,
		@dr_order_notification_xml_id	int,
		@db_name						varchar(100),
		@system_user					varchar(100)

	declare @tempRefundLoop table(dr_cart_order_in_process_id int,
		dr_order_notification_xml_id int,
		vendor_order_code varchar(100),
		processed bit);

	Insert into @tempRefundLoop
	select c.dr_cart_order_in_process_id,
		c.dr_order_notification_xml_id,
		soa.vendor_order_id vendor_order_code,
		0 processed		
	from sales_order_load soa
		inner join dr_cart_order_in_process c
		on soa.vendor_order_ID = c.vendor_order_code
		left join dr_cart_order_refund ref
		on soa.vendor_order_ID = ref.vendor_order_code
	where soa.transaction_Description like '%return%'
		and ref.dr_cart_order_refund_id is null

	select IDENTITY(INT,1,1) new_id, 
		dr_cart_order_in_process_id,
		dr_order_notification_xml_id,
		vendor_order_code,
		processed
		into #tempRefundLoop
		from @tempRefundLoop
		order by new_id

	select @refund_id = min(new_id), @max_refund_id = max(new_id)
		from #tempRefundLoop

	while @refund_id <= @max_refund_id
			begin

				select @vendor_order_code = vendor_order_code,
					@cart_order_id_in_process = dr_cart_order_in_process_id,
					@dr_order_notification_xml_id = dr_order_notification_xml_id
				from #tempRefundLoop
				where new_id = @refund_id

				select @order_header_id = oh.order_header_id
				from order_header oh 
					inner join vendor_order vo 
					on oh.vendor_order_id = vo.vendor_order_id
				where vendor_order_code = @vendor_order_code


				if @order_header_id > 0
				begin

					--insert into refund table
					insert into dr_cart_order_refund(dr_cart_order_in_process_id,dr_order_notification_xml_id, vendor_order_code) 
					values(@cart_order_id_in_process,@dr_order_notification_xml_id, @vendor_order_code)

					select @system_user = suser_sname(),
						@db_name = db_name()

					--process the refund
					exec usp_cart_refund_full @order_header_id, 3, 8, 'usp_dr_load_refund_order_load', @system_user 

					--service broker transaction
					exec usp_cart_insert_license_update_queue @order_header_id, 3

				end

					update #tempRefundLoop set processed = 1 where dr_order_notification_xml_id = @dr_order_notification_xml_id

					set @refund_id = @refund_id + 1
					set @order_header_id = 0
			end

			--move records to sales_order_load_archive
			insert into sales_order_load_archive
			select *
			from sales_order_load

			truncate table sales_order_load
END


GO
