-- PROCEDURE: [dbo].[usp_dr_load_xml_order_load]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dr_load_xml_order_load]

/*	
	DATE		AUTHOR			REMARKS
	2013-09-06	mrobbins		Initial creation
	2013-09-30	mrobbins		logging for multiple keycodes and bogus product_id
	2013-11-07	mrobbins		added external customer key
	2013-11-15	mrobbins		error checking change for non numeric product_id
	2013-12-05	mrobbins		check for test orders and do not load
	2013-12-18	mrobbins		updated unit_price from unit_price to pricePerQty as that has the discount subtracted and no tax
	2014-01-29	mrobbins		updated insert into item license
								updated keycode pull for items
	2014-03-19	mrobbins		updated TRX_ref and Primary_ref to check for the length of the char index to split
	2014-08-25	mrobbins		update TRX_ref for the new sites webrootj	
	2015-02/20	mrobbins		added attempts - will only attempt order 3 times						

	DESCRIPTION
	Reads in XML from table for DR orders.  Inserts into order tables
*/

AS
	begin try
	set nocount on

		DECLARE @xml XML,
		--cart_order variables
		@vendor_order_code				nvarchar(100),
		@siteID							nvarchar(65),
		@siteURL						nvarchar(1025),
		@Trx_rc							nvarchar(50),
		@Trx_ac							nvarchar(100),
		@P_rc							nvarchar(50),
		@P_ac							nvarchar(100),
		@total							float,
		@subtotal						float,
		@tax							float,
		@exchangerate					float,
		@paymentmethod					nvarchar(255),
		@submissiondate					nvarchar(50),
		@locale							nvarchar(50),
		@extendedAttributes				bigint,


		--cart_order_item_license
		@keycode						nvarchar(200),

		--cart_order_item
		@item_id						bigint,
		@vendor_id						int,
		@line_item						bigint,
		@vendor_product_id				nvarchar(100),
		@quantity						int,
		@list_price						float,
		@unit_price						float,
		@item_tax						float,
		@tax_exempt						bit,
		@product_id						nvarchar(100),
		@product_locale					nvarchar(10),
		@loop							bigint,
		@testLoop						nvarchar(10),
		@strsql							varchar(2000),
		@cnt							bigint,
		@prod_year						bigint,
		@seats							bigint,
		@transaction_Description		nvarchar(100),

		--cart_customer
		@addressid						bigint,
		@first_name						nvarchar(255),
		@last_name						nvarchar(255),
		@bill_address_1					nvarchar(255),
		@bill_address_2					nvarchar(255),
		@bill_address_3					nvarchar(255),
		@bill_city						nvarchar(130),
		@bill_state						nvarchar(2),
		@bill_postal_code				nvarchar(32),
		@bill_country					nvarchar(3),
		@ship_address_1					nvarchar(255),
		@ship_address_2					nvarchar(255),
		@ship_address_3					nvarchar(255),
		@ship_city						nvarchar(130),
		@ship_state						nvarchar(2),
		@ship_postal_code				nvarchar(32),
		@ship_country					nvarchar(3), 
		@phone_number					nvarchar(64),
		@fax_number						nvarchar(64),
		@company_name					nvarchar(255),
		@customer_email					nvarchar(255),
		@opt_in							bit,
		@external_customer_key			varchar(100),
			
		@cart_customer_id_in_process	int,
		@cart_order_id_in_process		int,
		@cart_order_item_id_in_process	int,
		@cart_customer_id				int,
		@cart_order_id					int,
		@cart_order_item_id				int,
		@dr_order_notification_xml_id	int,
		@response_code					int,
		@message						varchar(100),
		@xml_id							int,
		@max_xml_id						int,
		@loopkeycode					int,
		@cntkeycode						int,
		@keycode_id						int,
		@cart_error						varchar(1000),
		@flag_error						bit,
		@order_header_id				int,
		@order_type_group_id			int,
		@order_type						varchar(30),
		@order_cnt						int,
		@cart_order_item_license_id		int,
		@keycodecnt						int,
		@keycodetotal					int,
		@db_name						varchar(100),
		@system_user					varchar(100),
		@product_id_error_nonnumeric	int,
		@product_id_error_missing		int,
		@quantity_error_missing			int,

		@min_item_id					int,
		@max_item_id					int,

		@TrxRef_char					int,
		@PrimaryRef_char				int,

		@attempts						int


		
--Update records that were attempted at least 3 times to processed

		update dr_order_notification_xml 
					set processed = 1
		where processed = 0
			and attempts >= 3
			

		declare @tempXML table(dr_order_notification_xml_id int,
			order_notification_xml xml,
			processed bit,
			attempts int);


		insert into @tempXML(dr_order_notification_xml_id,order_notification_xml,processed, attempts)
		select top 10 dr_order_notification_xml_id, order_notification_xml, processed, attempts 
		from dr_order_notification_xml
		where processed = 0
			and attempts < 3
		order by dr_order_notification_xml_id


		select IDENTITY(INT,1,1) new_id, dr_order_notification_xml_id,order_notification_xml,processed,attempts
		into #temp_dr_order_notification_xml
		from @tempXML
		order by new_id

		select @xml_id = min(new_id), @max_xml_id = max(new_id)
		from #temp_dr_order_notification_xml

		while @xml_id <= @max_xml_id
			begin
				
				set @flag_error = 0
				set @cart_error = ''
				set @cart_order_item_id_in_process = 0

				select @xml = order_notification_xml,
					@dr_order_notification_xml_id = dr_order_notification_xml_id,
					@attempts = attempts
				from #temp_dr_order_notification_xml
				where new_id = @xml_id


				;WITH XMLNAMESPACES(default 'http://integration.digitalriver.com/commonRequisition/1.0')

				/***************************************************************************************************************************************************************
				1 - cart_customer table
				***************************************************************************************************************************************************************/
				select @addressid = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/addressID)[1]', 'bigint') 
				select @first_name = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/name1)[1]', 'nvarchar(100)') 
				select @last_name = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/name2)[1]', 'nvarchar(100)') 
				select @bill_address_1 = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/line1)[1]', 'nvarchar(255)') 
				select @bill_address_2 = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/line2)[1]', 'nvarchar(255)') 
				select @bill_address_3 = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/line3)[1]', 'nvarchar(255)') 
				select @bill_city = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/city)[1]', 'nvarchar(100)') 
				select @bill_state = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/state)[1]', 'nvarchar(100)') 
				select @bill_postal_code = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/postalCode)[1]', 'nvarchar(100)') 
				select @ship_address_1 = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/line1)[1]', 'nvarchar(255)') 
				select @ship_address_2 = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/line2)[1]', 'nvarchar(255)') 
				select @ship_address_3 = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/line3)[1]', 'nvarchar(255)') 
				select @ship_city = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/city)[1]', 'nvarchar(100)') 
				select @ship_state = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/state)[1]', 'nvarchar(100)') 
				select @ship_postal_code = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/postalCode)[1]', 'nvarchar(100)') 
				select @phone_number = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/phoneNumber)[1]', 'nvarchar(100)') 
				select @fax_number = @xml.value('(/*:OrderInfo/lineItems/item/shipToAddress/faxPhone)[1]', 'nvarchar(100)') 
				select @company_name = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/companyName)[1]', 'nvarchar(100)') 
				select @customer_email = @xml.value('(/*:OrderInfo/paymentInfos/paymentInfo/billingAddress/email)[1]', 'nvarchar(100)') 
				select @opt_in = @xml.value('(/*:OrderInfo/op
tIn)[1]', 'bit') 
				print @customer_email
				select @locale = @xml.value('(/*:OrderInfo/locale)[1]', 'nvarchar(50)') 

				select @external_customer_key = @xml.value('(/*:OrderInfo/customerID)[1]', 'nvarchar(50)') 

				select @bill_country = ISO3 , @ship_country = ISO3 from lu_countries where iso = right(@locale,2)


				insert into dr_cart_customer_in_process(first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, bill_postal_code, bill_country, 
					ship_address_1, ship_address_2, ship_address_3, ship_city, ship_state, ship_postal_code, ship_country, phone_number, fax_number, company_name, customer_email, opt_in, external_customer_key)
				select @first_name, @last_name, @bill_address_1, @bill_address_2, @bill_address_3, @bill_city, @bill_state, @bill_postal_code, @bill_country, 
					@ship_address_1, @ship_address_2, @ship_address_3, @ship_city, @ship_state, @ship_postal_code, @ship_country, @phone_number, @fax_number, @company_name, @customer_email, isnull(@opt_in,1),@external_customer_key 

				select @cart_customer_id_in_process = scope_identity()

				--select @first_name first_name, @last_name last_name, @bill_address_1 bill_address_1, @bill_address_2 bill_address_3, @bill_address_3 bill_address_3, @bill_city bill_city,
				--	@bill_state bill_state, @bill_postal_code bill_postal_code, @bill_country bill_country, @ship_address_1 ship_address_1, @ship_address_2 ship_address_2,
				--	@ship_address_3 ship_address_3, @ship_city ship_city, @ship_state ship_state, @ship_postal_code ship_postal_code, @ship_country ship_country,  @phone_number phone_number,
				--	@fax_number fax_number, @company_name company_name, @customer_email customer_email, @opt_in	opt_in



				/***************************************************************************************************************************************************************
				2 - cart_order table
				***************************************************************************************************************************************************************/

				select @vendor_order_code = @xml.value('(/*:OrderInfo/*:orderID)[1]','nvarchar(50)') 

				select @siteID = @xml.value('(/*:OrderInfo/site/siteID)[1]','nvarchar(50)') 
				select @siteURL = @xml.value('(/*:OrderInfo/site/siteURL)[1]','nvarchar(50)') 

				--Put all OrderInfo/extendedAttributes nodes into @temp to get TRXRef and PrimaryRef values

				declare @temp table(name nVarChar(100),
					value nVarChar(100));

				insert into @temp(name,value)
				select  
					ea.value('name[1]', 'nvarchar(50)') name,
					ea.value('value[1]', 'nvarchar(50)') value
				from @xml.nodes('/*:OrderInfo/extendedAttributes/item') extendedAttributes(ea)

				if @siteID = 'webrootj'
					begin
						select @P_rc = value from @temp where name = 'TrxRef'
					end
				else
					begin
						select @TrxRef_char = charindex('|',value) from @temp where name = 'TrxRef'
						select @PrimaryRef_char = charindex('|',value) from @temp where name = 'PrimaryRef'

						if @TrxRef_char > 1
						begin 
							select @Trx_rc = left(value,charindex('|',value)-1) from @temp where name = 'TrxRef'
							select @Trx_ac = substring(value,charindex('|',value)+1,len(value)-charindex('|',value)-1) from @temp where name = 'TrxRef'

						end

						if @PrimaryRef_char > 1
						begin 
							select @P_rc = left(value,charindex('|',value)-1) from @temp where name = 'PrimaryRef'
							select @P_ac = substring(value,charindex('|',value)+1,len(value)-charindex('|',value)-1) from @temp where name = 'PrimaryRef'
						end
					end

				select @total = @xml.value('(/*:OrderInfo/pricing/total/amount)[1]','float') 
				select @subtotal = @xml.value('(/*:OrderInfo/pricing/subtotal/amount)[1]','float') 
				select @tax = @xml.value('(/*:OrderInfo/pricing/tax/amount)[1]','float') 
				select @exchangerate = @xml.value('(/*:OrderInfo/pricing/exchangeRate/amount)[1]','float') 

				select @paymentmethod = @xml.value('(/*:Or
derInfo/paymentInfos/paymentInfo/paymentMethodName)[1]','nvarchar(50)') 
				select @submissiondate = @xml.value('(/*:OrderInfo/submissionDate)[1]','nvarchar(50)') 
				

				-- insert cart_order
				insert into dr_cart_order_in_process(dr_order_notification_xml_id, dr_cart_customer_in_process_id,vendor_order_code,site_id,site_url,p_rc,p_ac,trx_rc,trx_ac,total_amount,sub_total_amount,tax_amount,payment_method,exchange_rate
					   ,submission_date,locale)
				 values (@dr_order_notification_xml_id, @cart_customer_id_in_process,@vendor_order_code,@siteID,@siteURL,isnull(@P_rc,''),isnull(@P_ac,''),isnull(@Trx_rc,''),isnull(@Trx_ac,''),@total,@subtotal,@tax,@paymentmethod,@exchangerate
					   ,@submissiondate,@locale) --18
           
				--set cart_order_id to match transaction
				select @cart_order_id_in_process  = scope_identity()

				--update cart_customer
					update dr_cart_customer_in_process
					set dr_cart_order_in_process_id = @cart_order_id_in_process
					where dr_cart_customer_in_process_id = @cart_customer_id_in_process

				--Select @extendedAttributes extendedAttributes, @vendor_order_code order_code, @siteID site_id, @siteURL site_URL, @Trx_rc TRX_rc, @Trx_ac Trx_ac,
				--	@P_rc P_rc, @P_ac P_ac, @total total, @subtotal subtotal, @tax tax, @exchangerate exchangerate, @paymentmethod paymentmethod, 
				--	@submissiondate submissiondate, @locale locale


				/***************************************************************************************************************************************************************
				cart_order_item table selects
				***************************************************************************************************************************************************************/
				--Put OrderInfo/lineItems/item nodes into @temp2 to get the multiple values


				declare @temp_item table(item_id int,
					line_item nvarchar(50),
					vendor_product_id nvarchar(100),
					quantity bigint,
					list_price float,
					unit_price float,
					tax float,
					tax_exempt bit,
					product_id nvarchar(100),
					prod_year bigint,
					seats bigint,
					product_locale nvarchar(100),
					transaction_description nvarchar(100));

				declare @temp_keycodes table(keycode_id int,
					line_item nvarchar(50),
					keycode nvarchar(100));

				IF OBJECT_ID('tempdb..#temp_items') IS NOT NULL DROP TABLE #temp_items

				

				select IDENTITY(INT,1,1) item_id, 
					i.value('lineItemID[1]', 'nvarchar(50)') line_item,
					i.value('(product/productID)[1]', ' nvarchar(100)') vendor_product_id,
					i.value('quantity[1]', ' bigint') quantity,
					i.value('(pricing/listPrice/amount)[1]', ' float') list_price,
					--i.value('(pricing/unitPrice/amount)[1]', ' float') unit_price,
					i.value('(pricing/pricePerQty/amount)[1]', ' float') unit_price,
					i.value('(pricing/tax/amount)[1]', ' float') tax,
					i.value('taxExempt[1]', ' bit') tax_exempt,
					i.value('(productInfo/sku)[1]', ' nvarchar(100)') product_id,
					i.value('(productInfo/year)[1]', ' bigint') prod_year,
					i.value('(productInfo/seats)[1]', ' bigint') seats,
					i.value('(product/locale)[1]', 'nvarchar(100)') product_locale,
					i.value('(transactionDescription)[1]', 'nvarchar(100)') transaction_description
				into #temp_items
				from @xml.nodes('/*:OrderInfo/lineItems/item') items(i)


				insert into @temp_item(item_id, line_item, vendor_product_id, quantity, list_price, unit_price, tax, tax_exempt, product_id, prod_year, seats, product_locale,transaction_description)
				select item_id, line_item, vendor_product_id, quantity, list_price, unit_price, tax, tax_exempt, product_id, prod_year, seats, product_locale,transaction_description
				from #temp_items
				order by item_id

				IF OBJECT_ID('tempdb..#temp_keycodes_all') IS NOT NULL DROP TABLE #temp_keycodes_all
				IF OBJECT_ID('tempdb..#temp_keycodes_cleaned') IS NOT NULL DROP TABLE #temp_keycodes_cleaned

				--pull all the keycodes for the entire file
				select 
	
				i2.value('lineItemID[1]', 'nvarchar(50)') line_item,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[1]', 'nvarchar(100)') keycode,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[2]', 'nvarchar(100)') keycode2,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[3]', 'nvarchar(100)') keycode3,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[4]', 'nvarchar(100)') keycode4,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[5]', 'nvarchar(100)') keycode5,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[6]', 'nvarchar(100)') keycode6,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[7]', 'nvarchar(100)') keycode7,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[8]', 'nvarchar(100)') keycode8,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[9]', 'nvarchar(100)') keycode9,
					i2.value('(lineItemDigitalInfoList/digitalInfo/serialNumber)[10]', 'nvarchar(100)') keycode10
				into #temp_keycodes_all
				from @xml.nodes('/*:OrderInfo/lineItems/item') items(i2)

							
				select distinct identity(int,1,1) keycode_id, line_item, keycodes
				into #temp_keycodes_cleaned
				from 
					(select line_item, keycode, keycode2,keycode3,keycode4,keycode5,keycode6,keycode7,keycode8,keycode9,keycode10
					from #temp_keycodes_all) p
				unpivot
					(keycodes for emp in 
						(keycode, keycode2,keycode3,keycode4,keycode5,keycode6,keycode7,keycode8,keycode9,keycode10)
				)as unpvt

				insert into @temp_keycodes (keycode_id, line_item, keycode)
				select keycode_id, line_item, keycodes as keycode
				from #temp_keycodes_cleaned

				--select * from #temp_keycodes

				--Loop through the records in @temp_item to insert into cart_order_item
				select @cnt = count(*) from @temp_item

				set @loop = 1

				while @loop <= @cnt
					BEGIN

						--items
						select @item_id = item_id,
							@line_item = line_item,
							@vendor_product_id = vendor_product_id,
							@quantity = quantity,
							@list_price = list_price,
							@unit_price = unit_price,
							@item_tax = tax,
							@tax_exempt = tax_exempt,
							@product_id = product_id,
							@prod_year = prod_year,
							@seats = seats,
							@product_locale = product_locale,
							@transaction_description = transaction_description
						from @temp_item
						where item_id = @loop

						--loop through to get multiple keycodes

						set @vendor_id = 2

						--check for the CD product_id
						if @product_id like '%CD%'
							begin
								set @product_id = '128'
							end

						insert into dr_cart_order_item_in_process(dr_cart_order_in_process_id, vendor_id, line_item, vendor_product_id, quantity, 
							list_price, unit_price, tax, tax_exempt, product_id, product_locale,transaction_description)
						select @cart_order_id_in_process, @vendor_id, @loop, @vendor_product_id, @quantity, @list_price, @unit_price, @item_tax, @tax_exempt, @product_id, @product_locale,@transaction_description

						select @cart_order_item_id_in_process  = scope_identity()

						/***********************************************************************************************************************************************************
						cart_order_item_license table insert
						***********************************************************************************************************************************************************/


						insert into dr_cart_order_item_license_in_process(dr_cart_order_item_in_process_id, keycode)
						select @cart_order_item_id_in_process, keycode
						from @temp_keycodes
						where line_item = @line_item


						set @loop = @loop + 1
					END		

					delete from @temp_item

					/***********************************************************************************************************************************************************
						error checking
						Required before order insert site, product_id
, customer detail, vendor_order_id, amount, quantity exchange_rate
					***********************************************************************************************************************************************************/		
					
					if @siteID = ''
					BEGIN
						set @cart_error = 'site_id '
						set @flag_error = 1
					END

					if @vendor_order_code = ''
					BEGIN
						set @cart_error = isnull(@cart_error,'') + 'vendor_order_code '
						set @flag_error = 1
					END

					if @total = ''
					BEGIN
						set @cart_error = isnull(@cart_error,'') +  'total '
						set @flag_error = 1
					END

					if @first_name = ''
					BEGIN
						set @cart_error = isnull(@cart_error,'') +  'first_name '
						set @flag_error = 1
					END
					
					if @last_name = ''
					BEGIN
						set @cart_error = isnull(@cart_error,'') +  'last_name '
						set @flag_error = 1
					END

					if @customer_email like  '%@digitalriver.com%'
					BEGIN
						set @cart_error = isnull(@cart_error,'') +  'test order '
						set @flag_error = 1
					END

					/*-----------------------------------------------------------------------
						Check multiple items for missing or wrong format data before loading
					-----------------------------------------------------------------------*/	

					select @quantity_error_missing = count(*)
					from dr_cart_order_item_in_process
					where dr_cart_order_in_process_id = @cart_order_id_in_process
						and (quantity is null
						or quantity = 0)
					
					if @quantity_error_missing > 0
					BEGIN
						set @cart_error = isnull(@cart_error,'') +  'quantity '
						set @flag_error = 1
					END

					select @product_id_error_nonnumeric = count(*)
					from dr_cart_order_item_in_process
					where dr_cart_order_in_process_id = @cart_order_id_in_process
						and isnumeric(product_id) = 0 

					select @product_id_error_missing = count(*)
					from dr_cart_order_item_in_process
					where dr_cart_order_in_process_id = @cart_order_id_in_process
						and product_id is null

					if @product_id_error_missing > 0
					BEGIN
						set @cart_error = isnull(@cart_error,'') + 'product_id '
						set @flag_error = 1
					END
				

					if @product_id_error_nonnumeric > 0
					BEGIN
						set @cart_error = isnull(@cart_error,'') + 'product_id NOT numeric '
						set @flag_error = 1
					END

					/*-----------------------------------------------------------------------*/

					if @flag_error = 1
					BEGIN
						insert into dr_cart_order_error(dr_cart_order_in_process_id,dr_order_notification_xml_id,vendor_order_code,error_reason) 
						values(@cart_order_id_in_process,@dr_order_notification_xml_id,@vendor_order_code,@cart_error)
					END
					
					--******************************************************************************************************************************************************************

					if @flag_error = 0
					BEGIN
						if @total > 0
						BEGIN
							set @order_type_group_id = 1
							set @order_type = 'DRSOAORDER'

							--customer record

							insert into cart_customer(external_customer_key,first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, bill_postal_code, bill_country, 
								ship_address_1, ship_address_2, ship_address_3, ship_city, ship_state, ship_postal_code, ship_country, phone_number, fax_number, company_name, customer_email, opt_in, customer_in_process_id)
							select external_customer_key,first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, bill_postal_code, bill_country, 
								ship_address_1, ship_address_2, ship_address_3, ship_city, ship_state, ship_postal_code, ship_country, phone_number, fax_number, company_name, customer_email, opt_in, @cart_customer_id_in_process from dr_cart_customer_in_process where dr_cart_customer_in_process_id = @cart_customer_id_in_process

							select @cart_customer_id = scope_identity()

							--cart_order

							insert into cart_order(cart
_customer_id,vendor_order_code, order_type,site_id,site_url,p_rc,p_ac,trx_rc,trx_ac,total_amount,sub_total_amount,tax_amount,payment_method,exchange_rate
									,session_id,submission_date,locale,invoice_in_process_id, cart_order_status_id,sales_order_date)
							select @cart_customer_id,vendor_order_code,@order_type,site_id,site_url,p_rc,p_ac,trx_rc,trx_ac,total_amount,sub_total_amount,tax_amount,0,exchange_rate
									,0,submission_date,locale, @cart_order_id_in_process, @order_type_group_id,submission_date from dr_cart_order_in_process where dr_cart_order_in_process_id = @cart_order_id_in_process

							--set cart_order_id to match transaction
							select @cart_order_id  = scope_identity()

							--update cart_customer
							update cart_customer
							set cart_order_id = @cart_order_id
							where cart_customer_id = @cart_customer_id
						
							--cart_order_item
							--loop through the records and add cart_order_item and cart_order_item_license records

							select @min_item_id = min(dr_cart_order_item_in_process_id),
								@max_item_id = max(dr_cart_order_item_in_process_id)  
							from dr_cart_order_item_in_process 
							where dr_cart_order_in_process_id = @cart_order_id_in_process

							while @min_item_id <= @max_item_id
								BEGIN
						
									insert into cart_order_item(cart_order_id, vendor_id, line_item, vendor_product_id, quantity, 
										list_price, unit_price, tax_item_total, tax_exempt, product_id, product_locale,invoice_item_in_process_id)
									select @cart_order_id, vendor_id, line_item, vendor_product_id, quantity, 
										list_price, unit_price, tax, tax_exempt, product_id, product_locale,0 
									from dr_cart_order_item_in_process 
									where dr_cart_order_item_in_process_id = @min_item_id 

									select @cart_order_item_id  = scope_identity()

									--cart_order_item_license

									insert into cart_order_item_license(cart_order_item_id, keycode)
									select @cart_order_item_id, replace(keycode,'-','') keycode  
									from dr_cart_order_item_license_in_process 
									where dr_cart_order_item_in_process_id = @min_item_id 

									set @min_item_id = @min_item_id + 1

								END	

							--process the cart records
							exec usp_cart_process_order @cart_order_id

							select @order_header_id = order_header_id
							from order_header oh 
							inner join vendor_order vo 
								on oh.vendor_order_id = vo.vendor_order_id
							where  vo.vendor_order_code = @vendor_order_code

							--service broker transaction
							exec usp_cart_insert_license_update_queue @order_header_id, @order_type_group_id

						END

						 
					END


					set @keycode = ''

					set @attempts = @attempts + 1

					update #temp_dr_order_notification_xml set processed = 1 where dr_order_notification_xml_id = @dr_order_notification_xml_id

					update dr_order_notification_xml 
					set processed = 1,
						attempts = @attempts 
					where dr_order_notification_xml_id = @dr_order_notification_xml_id

					set @xml_id = @xml_id + 1
					set @order_header_id = 0
					set @product_id_error_missing = 0
					set @product_id_error_nonnumeric = 0
					set @quantity_error_missing = 0
			end		


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'something failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	set @attempts = @attempts + 1
	update dr_order_notification_xml 
					set attempts = @attempts 
					where dr_order_notification_xml_id = @dr_order_notification_xml_id

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_order_notification_insert_xml]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_order_notification_insert_xml]
(		
	@order_notification_xml xml,
	@vendor_order_code varchar(100) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-22	esmart		Initial creation.
	2013-09-10	mrobbins	Updated to check for existing order and if the order is a refund
	2013-11-15	mrobbins	Updated to check for existing order for orders older than 9/13 if not found then check for existing order in dr table
							if order had an error vendor_order_code will not exist in vendor_order but we don't want a duplicate order in the dr table
	DESCRIPTION
	
*/

AS
	--when dealing with Sql XML and PHP always use
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON


	declare	@response_code int,
			@message varchar(100),
			@rec_count int,
			@total int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	;WITH XMLNAMESPACES(default 'http://integration.digitalriver.com/commonRequisition/1.0')
	select @vendor_order_code = @order_notification_xml.value('(/*:OrderInfo/*:orderID)[1]','nvarchar(50)') 
	select @total = @order_notification_xml.value('(/*:OrderInfo/pricing/total/amount)[1]','float')

	select @rec_count = count(*) from vendor_order where vendor_order_code = @vendor_order_code

	if @rec_count = 0 
		begin
			--print 'check dr table'
			select @rec_count = count(*) from dr_order_notification_xml where vendor_order_code = @vendor_order_code
		end

	--record doesn't exist or it's a refund	
	if @rec_count <= 0 or @total < 1
		begin
			--print 'inserted'
			insert into dr_order_notification_xml(vendor_order_code,order_notification_xml) 
			values(@vendor_order_code,@order_notification_xml)
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_select_cart_item_url]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dr_select_cart_item_url]

(
	@cart_order_in_process_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-15	esmart		Initial creation.
	2013-05-24	esmart		Update for PCCB 
	2013-08-27	esmart		Fix trial to full issue
	2014-08-07	esmart		Fix trial to full for JA

	DESCRIPTION
	select discount
*/

AS
	set nocount on				

	declare	@license_distribution_method_id int,
			@autorenewal varchar(100),
			@language_code varchar(2),
			@location_code varchar(3),
			@dr_theme varchar(20),
			@response_code int,
			@message varchar(100)


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @autorenewal = 'ON'	

	-- 1.1) get @location_code
	select @location_code = location_code, @language_code = language_code
	from cart_order_in_process 
	where cart_order_in_process_id = @cart_order_in_process_id

	select @license_distribution_method_id = l.license_distribution_method_id
	from cart_order_item_in_process i 
	inner join cart_order_item_license_in_process il 
		on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id 
	inner join license l 
		on il.keycode = l.keycode 
	where i.cart_order_in_process_id = @cart_order_in_process_id

	if @license_distribution_method_id is null
		begin
		select @license_distribution_method_id = l.license_distribution_method_id
		from cart_order_message_in_process m
		inner join license_key k
			on m.message_key = k.license_key
		inner join license l 
			on k.license_id = l.license_id
		where m.cart_order_in_process_id = @cart_order_in_process_id
		end

	-- 1.1) check PCCB 
	if @license_distribution_method_id = 797	
		begin
		select @language_code = 'NL', @location_code = 'NLD', @autorenewal = 'OFF'
		end

	-- 1.10) @dr_theme
	select @dr_theme = ''

	select @dr_theme = '/ThemeID.'+t.dr_theme_value
	from dr_theme t
	inner join dr_theme_license_distribution_method m
		on t.dr_theme_id = m.dr_theme_id
	where m.license_distribution_method_id = @license_distribution_method_id

	-- 1.2) JPN cart
	if @location_code = 'JPN'
		begin
			select i.cart_order_item_in_process_id,
					DR_cart_url = case
									when p.product_type_id = 1 and t.dr_offer_id is null and il.keycode is null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code
									when p.product_type_id = 1 and t.dr_offer_id is not null and il.keycode is null then  'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id)
									when p.product_type_id = 1 and t.dr_offer_id is null and il.keycode is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode)
									when p.product_type_id = 1 and t.dr_offer_id is not null and il.keycode is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode)
									when p.product_type_id <> 1 and t.dr_offer_id is null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '
/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode)
									when p.product_type_id <> 1 and t.dr_offer_id is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode)
									else 'https://store.webroot.com/store/'+lcp.site_id+'/'+ c.locale + '/buy/productID.' + convert(varchar(20),dp.dr_product_id) + '/currency.'+ cu.currency_code
								end,
					c.locale, cu.currency_code, dp.dr_product_id, t.dr_offer_id, lcp.site_id
			from cart_order_in_process c
			inner join currency cu
				on c.currency_id = cu.currency_id
			inner join cart_order_item_in_process i
				on c.cart_order_in_process_id = i.cart_order_in_process_id
			left join cart_order_item_license_in_process il
				on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
			inner join product p
				on i.product_id = p.product_id
			inner join dr_product_price dp
				on i.product_id = dp.product_id
			inner join product_license_category lc
				on i.product_id = lc.product_id
			inner join product_line_product pl
				on i.product_id = pl.product_id
			inner join license_category_product_line lcp
				on lc.license_category_id = lcp.license_category_id and pl.product_line_id = lcp.product_line_id and @language_code = lcp.language_code and @location_code = lcp.location_code
			left join (select dr.cart_discount_id, do.site_id, dr.dr_offer_id
						from dr_offer_cart_discount dr
						inner join dr_offer do
							on dr.dr_offer_id = do.dr_offer_id) t
				on t.cart_discount_id = i.cart_discount_id and t.site_id = lcp.site_id
			where c.cart_order_in_process_id = @cart_order_in_process_id
			order by 1 desc
		end
	else
		begin
			select distinct i.cart_order_item_in_process_id,
					DR_cart_url = case
									when p.product_type_id = 1 and t.dr_offer_id is null and il.keycode is null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + @dr_theme
									when p.product_type_id = 1 and t.dr_offer_id is not null and il.keycode is null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + @dr_theme
									when p.product_type_id = 1 and t.dr_offer_id is null and il.keycode is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode) + @dr_theme
									when p.product_type_id = 1 and t.dr_offer_id is not null and il.keycode is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode) + @dr_theme
									when p.product_type_id <> 1 and t.dr_offer_id is null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode) + @dr_theme
									when p.product_type_id <> 1 and t.dr_offer_id is not null then 'https://store.webroot.com/store/'+lcp.site_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + '/License.' + dbo.fn_KeycodeEncrypt(il.keycode) + @dr_theme
									else 'https://store.webroot.com/store/'+lcp.sit
e_id+'/'+ cl.dr_locale + '/buy/productID.' + convert(varchar(20),dp.dr_variation_product_id) + '/currency.'+ cu.currency_code + '/OfferID.' + convert(varchar(20),t.dr_offer_id) + @dr_theme
								end,
					c.locale, cu.currency_code, dp.dr_variation_product_id, t.dr_offer_id, lcp.site_id
			from cart_order_in_process c
			inner join currency cu
				on c.currency_id = cu.currency_id
			inner join cart_order_item_in_process i
				on c.cart_order_in_process_id = i.cart_order_in_process_id
			left join cart_order_item_license_in_process il
				on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
			left join license l
				on il.keycode = l.keycode
			inner join product p
				on i.product_id = p.product_id
			inner join dr_product dp
				on i.product_id = dp.product_id and dp.autorenewal = @autorenewal
			inner join product_license_category lc
				on i.product_id = lc.product_id
			inner join product_line_product pl
				on i.product_id = pl.product_id
			inner join license_category_product_line lcp
				on lc.license_category_id = lcp.license_category_id and pl.product_line_id = lcp.product_line_id and @language_code = lcp.language_code and @location_code = lcp.location_code
			inner join currency_language_location cl
				on @language_code = cl.language_code and @location_code = cl.location_code
			left join (select dr.cart_discount_id, do.site_id, dr.dr_offer_id
						from dr_offer_cart_discount dr
						inner join dr_offer do
							on dr.dr_offer_id = do.dr_offer_id) t
				on t.cart_discount_id = i.cart_discount_id and t.site_id = lcp.site_id
			left join dr_theme_license_distribution_method thl
				on l.license_distribution_method_id = thl.license_distribution_method_id
			left join dr_theme th
				on thl.dr_theme_id = th.dr_theme_id
			where c.cart_order_in_process_id = @cart_order_in_process_id
			order by 1 desc
		end
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
