CREATE PROCEDURE [dbo].[usp_dr_select_dr_pricing_update_template]

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select currency
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set nocount on
	
	select 
		[Variation Internal Product Name] = '',
		[Base Product ID] = p.dr_base_product_id,
		[Product ID] = p.dr_variation_product_id,
		[Internal Product Name] = p.variation_name,
		[Site Product Name] = p.display_name,
		[SKU] = p.product_id,
		[* Zero Allowed] = 'FALSE',
		[* EUR (default)] = t.EUR,
		[EUR - de_DE with Tax/VAT] = t.EUR,
		[EUR - en_GB with Tax/VAT] = t.EUR,
		[EUR - es_ES with Tax/VAT] = t.EUR,
		[EUR - fr_FR with Tax/VAT] = t.EUR,
		[EUR - nl_NL with Tax/VAT] = t.EUR,
		[EUR - pt_PT with Tax/VAT] = t.EUR,
		t.ARS,
		t.AUD,
		t.BRL,
		t.CAD,
		[CHF - en_GB with Tax/VAT] = t.CHF,
		t.COP,
		[DKK - en_GB with Tax/VAT] = t.DKK,
		[GBP - en_GB with Tax/VAT] = t.GBP,
		t.HKD,
		t.INR,
		t.JPY,
		t.MXN,
		t.MYR,
		[NOK - en_GB with Tax/VAT]= t.NOK,
		t.NZD,
		[SEK - en_GB with Tax/VAT] = t.SEK,
			t.SGD,t.THB,t.TWD,t.USD,t.ZAR
		from temp_products t
		inner join dr_product p
			on t.product_id = p.product_id
		where product_family_id in (200) --and seats = 25




	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
