-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_insert_license_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dr_subscription_insert_license_subscription]

(
	@dr_subscription_id int,
	@xml_type varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-21	esmart		Initial creation.
	2010-09-08	acoffel		added trap to exit procedure if incoming dr expire
							date matches existing license_capability expire date
	2011-10-07	esmart		Add check on vendor_order
	2012-05-25	esmart		Fix duplicate dr_license_subscription bug

	DESCRIPTION
	
*/
AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100),
			@license_id int,
			@product_id int,
			@subscription_id bigint,
			@dr_user_id bigint,
			@product_type_id int,
			@storage_upgrade_product tinyint,
			@current_expiration_date datetime,
			@license_attribute_license_value int,
			@existing_subscriptions int,
			@duplicate_subscription int,
			@dr_subscription_status_id tinyint,
			@dr_license_subscription_id int,
			@license_category_id tinyint,
			@existing_storage_subscriptions tinyint,
			@dr_subscription_change_reason_id tinyint,
			@vendor_order_id int
			

begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get details from new subscription
		select @license_id = l.license_id,
				@product_id = s.product_id,
				@subscription_id = s.subscription_id,
				@dr_user_id = s.dr_user_id,
				@product_type_id = p.product_type_id,
				@storage_upgrade_product = case
												when product_description like '%Backup%' then 1
												else 0
											end,
				@license_category_id = c.license_category_id,
				@current_expiration_date = (select max(capability_expiration_date) from license_capability where license_id = l.license_id),
				@license_attribute_license_value = (select license_attribute_license_value from license_attribute_license where license_id = l.license_id),
				@existing_subscriptions = (select count(*) from dr_license_subscription where license_id = l.license_id),
				@duplicate_subscription = (select count(*) from dr_license_subscription where subscription_id = s.subscription_id and dr_subscription_status_id in (1,2)),
				@existing_storage_subscriptions = (select count(*) 
													from dr_license_subscription ls
													inner join product p1
														on ls.product_id = p1.product_id
													where ls.license_id = l.license_id and ls.dr_subscription_status_id in (1,2) and p1.product_description like '%Backup%')
				
		from dr_subscription s
		inner join license l
			on s.keycode = l.keycode
		inner join product p
			on s.product_id = p.product_id
		left join product_license_category c
			on p.product_id = c.product_id
		where s.dr_subscription_id = @dr_subscription_id

		-- 1.2) if license is not activated then set status to pending activation
		select @dr_subscription_status_id = case 
												when @current_expiration_date is not null then 2
												else 1	
											end

		-- 1.3) @vendor_order_id
		select @vendor_order_id = v.vendor_order_id 
		from vendor_order v
		inner join dr_subscription s
			on s.vendor_order_code = v.vendor_order_code
		where s.dr_subscription_id = @dr_subscription_id

		--select license_id = @license_id,
		--		product_id = @product_id,
		--		subscription_id = @subscription_id,
		--		dr_user_id = @dr_user_id,
		--		product_type_id = @product_type_id,
		--		license_category_id = @license_category_id,
		--		storage_upgrade_product = @storage_upgrade_product,
		--		curr
ent_expiration_date = @current_expiration_date,
		--		license_attribute_license_value = @license_attribute_license_value,
		--		existing_subscriptions = @existing_subscriptions,
		--		duplicate_subscription = @duplicate_subscription,
		--		existing_storage_subscriptions = @existing_storage_subscriptions,
		--		dr_subscription_status_id = @dr_subscription_status_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) subscription updates
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @xml_type in ('SubscriptionRenewalSuccessNotificationRequest','NewSubscriptionNotificationRequest','BulkActivateSubscriptionRequest')
		begin 
		-- 2.1) no subscriptions exist for license
		if @existing_subscriptions = 0
			begin
			--select '2.1) no subscriptions exist for license'
			-- 2.1.1) insert dr_license_subscription
			insert into dr_license_subscription(license_id, subscription_id, product_id, dr_user_id, current_expiration_date, dr_subscription_status_id)
			values(@license_id, @subscription_id, @product_id, @dr_user_id, @current_expiration_date, @dr_subscription_status_id)

			select @dr_license_subscription_id = scope_identity()
	
			-- 2.1.2) insert dr_subscription_update if license is activated
			if @current_expiration_date is not null and @vendor_order_id is not null
				begin
				insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
				select dr_license_subscription_id, 
						dr_subscription_action_id = 1,
						current_expiration_date,
						dr_subscription_update_status_id = 1
				from dr_license_subscription
				where dr_license_subscription_id = @dr_license_subscription_id
				end
			end
		-- 2.2) existing subscriptions
		else
			begin
			-- 2.2.0) check current_expiration_date 
			if (select max(current_expiration_date) current_expiration_date from dr_license_subscription where subscription_id = @subscription_id and license_id = @license_id) between dateadd(dd,1,@current_expiration_date) and dateadd(dd,-1,@current_expiration_date)
				begin
				return
				end
				
			-- 2.2.1) subscription_id exists 
				if @duplicate_subscription = 1 and @vendor_order_id is not null
					begin
					--select '2.2.1) subscription_id exists '
					select @dr_subscription_change_reason_id = 8

					-- 2.2.1.1) insert dr_license_subscription_history
					insert into dr_license_subscription_history (dr_license_subscription_id, current_expiration_date, dr_subscription_status_id, last_modified_date, dr_subscription_change_reason_id)
					select s.dr_license_subscription_id, s.current_expiration_date, s.dr_subscription_status_id, s.last_modified_date, @dr_subscription_change_reason_id
					from dr_license_subscription s
					where subscription_id = @subscription_id

					-- 2.2.1.2) update dr_license_subscription
					update dr_license_subscription
					set current_expiration_date = @current_expiration_date, dr_user_id = @dr_user_id, product_id = @product_id, last_modified_date = getdate()
					from dr_license_subscription l
					where subscription_id = @subscription_id
					
					-- 2.2.1.3) insert dr_subscription_update
					insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
					select dr_license_subscription_id, 
							dr_subscription_action_id = 2,
							current_expiration_date,
							dr_subscription_update_status_id = 1
					from dr_license_subscription
					where subscription_id = @subscription_id			
					end
			-- 2.2.2) subscription_id does not exist
			else if @duplicate_subscription <> 1 and @vendor_order_id is not null
				begin
				-- 
			
	insert into dr_license_subscription(license_id, subscription_id, product_id, dr_user_id, current_expiration_date, dr_subscription_status_id)
				values(@license_id, @subscription_id, @product_id, @dr_user_id, @current_expiration_date, @dr_subscription_status_id)

				select @dr_license_subscription_id = scope_identity()

				-- 2.2.2.1) renewal
				if @product_type_id in (2)
					begin
					--select '2.2.2.1) renewal'
					select @dr_subscription_change_reason_id = 2	-- new renewal subscription
					
					if @current_expiration_date is not null and @vendor_order_id is not null
					begin
						insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
						select dr_license_subscription_id, 
								dr_subscription_action_id = 1,
								current_expiration_date,
								dr_subscription_update_status_id = 1
						from dr_license_subscription
						where dr_license_subscription_id = @dr_license_subscription_id

						exec usp_dr_subscription_update_license_subscription @dr_license_subscription_id,@license_id,@storage_upgrade_product,@dr_subscription_change_reason_id

					end


					end
				-- 2.2.2.2) upgrade
				if @product_type_id in (3)
					begin
					-- 2.2.2.2.1) product upgrade
					if @storage_upgrade_product = 0
						begin
					--	select '2.2.2.2.1) product upgrade'
						select @dr_subscription_change_reason_id = 1	-- product upgrade

						if @current_expiration_date is not null and @vendor_order_id is not null
						begin
							insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
							select dr_license_subscription_id, 
									dr_subscription_action_id = 1,
									current_expiration_date,
									dr_subscription_update_status_id = 1
							from dr_license_subscription
							where dr_license_subscription_id = @dr_license_subscription_id
	
							exec usp_dr_subscription_update_license_subscription @dr_license_subscription_id,@license_id,@storage_upgrade_product,@dr_subscription_change_reason_id

						end

						end
					-- 2.2.2.2.2) storage upgrade
					else
						begin
						--select '2.2.2.2.2) storage upgrade'
						if @existing_storage_subscriptions = 0
							begin
							-- 2.2.2.2.2.1) new storage upgrade
							--select '2.2.2.2.2.1) new storage upgrade'
								if @current_expiration_date is not null and @vendor_order_id is not null
								begin
									insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
									select dr_license_subscription_id, 
											dr_subscription_action_id = 1,
											current_expiration_date,
											dr_subscription_update_status_id = 1
									from dr_license_subscription
									where dr_license_subscription_id = @dr_license_subscription_id
								end
							end
						else 
							begin
							-- 2.2.2.2.2.2) existing storage upgrade
							--select '2.2.2.2.2.2) existing storage upgrade'
							select @dr_subscription_change_reason_id = 1	-- product upgrade							

							if @current_expiration_date is not null and @vendor_order_id is not null
								begin
									insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
									select dr_license_subscription_id, 
											dr_subscription_action_id = 1,
											current_expiration_date,
											dr_subscription_update_status_id = 1
									from dr_license_subscription
									where dr_license_subscription_id = @dr_license_subscription_id

									exec usp_dr_subscription_update_license_subscription @dr_license_subscription_id,@license_id,@storage_upgrade_product,@dr_subscription_change_reason_id

								end
							end 
						end -- 2.2.2.2.2
					end -- 2.2.2.2
				end -- 2.2.2
			end -- 2.2
		end -- 2.

	-- -------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Cancel subscription
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @xml_type in ('CancelSubscriptionNotificationRequest','ConvertAutoToManualNotificationRequest','BulkCancelSubscriptionRequest') and @duplicate_subscription > 0
		begin

		--select '3.0 Cancel'
		select @dr_subscription_change_reason_id = 7
	
		if @existing_subscriptions = 0
			begin
			--select '3.1) no subscriptions exist for license'
			-- 3.1.1) insert dr_license_subscription
			insert into dr_license_subscription(license_id, subscription_id, product_id, dr_user_id, current_expiration_date, dr_subscription_status_id)
			values(@license_id, @subscription_id, @product_id, @dr_user_id, @current_expiration_date, @dr_subscription_status_id)

			select @dr_license_subscription_id = scope_identity()

			end

		-- 3.1 insert dr_subscription_update
		insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
		select dr_license_subscription_id, 
				dr_subscription_action_id = 3,
				getdate(),
				dr_subscription_update_status_id = 1
		from dr_license_subscription
		where subscription_id = @subscription_id and dr_subscription_status_id in (1,2)

		-- 3.2) insert dr_license_subscription_history
		insert into dr_license_subscription_history (dr_license_subscription_id, current_expiration_date, dr_subscription_status_id, last_modified_date, dr_subscription_change_reason_id)
		select s.dr_license_subscription_id, s.current_expiration_date, s.dr_subscription_status_id, s.last_modified_date, @dr_subscription_change_reason_id
		from dr_license_subscription s
		where subscription_id = @subscription_id and dr_subscription_status_id in (1,2)

		-- 3.3) update dr_license_subscription
		update dr_license_subscription
		set dr_subscription_status_id = 3, last_modified_date = getdate()
		from dr_license_subscription
		where subscription_id = @subscription_id and dr_subscription_status_id in (1,2)
		
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) update dr_subscription 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		update dr_subscription 
		set processed = 1
		where dr_subscription_id = @dr_subscription_id


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not insert new subscription updates'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_insert_xml]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dr_subscription_insert_xml]

(
        @subscription_xml xml	
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-49	esmart		Initial creation.
	2012-05-25	esmart		Add reprocess
	2012-06-12	esmart		Add nvarchar for xml

	DESCRIPTION
	
*/

AS
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON
	
	declare @response_code int,
			@message varchar(100),
			@subscription_id bigint,
			@dr_user_id bigint,
			@vendor_order_code varchar(100),
			@dr_product_id int,
			@product_id int,
			@locale varchar(10),
			@keycode varchar(40),
			@xmldoc xml,
			@xmlhandle int,
			@ParentLocalName varchar(100),
			@dr_subscription_id int

begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get values from subscription xml
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get values
	SELECT @subscription_id = x.item.value('subscriptionID[1]', 'bigint') FROM @subscription_xml.nodes('//subscriptionInfo/subscriptionKey') AS x(item)
	
	SELECT @dr_user_id = x.item.value('userID[1]', 'bigint') FROM @subscription_xml.nodes('//subscriptionInfo/orderInfo/user') AS x(item)

	SELECT @vendor_order_code = x.item.value('orderID[1]', 'bigint') FROM @subscription_xml.nodes('//subscriptionInfo/orderInfo') AS x(item)

	SELECT @dr_product_id = x.item.value('productID[1]', 'bigint'),
			@product_id = x.item.value('externalReferenceID[1]', 'bigint'),
			@locale = x.item.value('locale[1]', 'varchar(10)')
	FROM @subscription_xml.nodes('//subscriptionInfo/orderInfo/lineItemInfo/product') AS x(item)

	SELECT	@keycode = replace(x.item.value('serialNumber[1]', 'varchar(40)'),'-','') FROM @subscription_xml.nodes('//subscriptionInfo/orderInfo/lineItemInfo/lineItemDigitalInfoList/digitalInfo') AS x(item)

	-- 1.1.1) 
	if @keycode is null
		begin
			SELECT	@keycode = replace(x.item.value('serialNumber[1]', 'varchar(40)'),'-','') FROM @subscription_xml.nodes('//subscriptionInfo/originalOrderInfo/lineItemInfo/lineItemDigitalInfoList/digitalInfo') AS x(item)
		end

	if len(@keycode) > 20 
		begin
			select @keycode = left(@keycode,20)
		end

	-- 1.2) get document type
	EXEC sp_xml_preparedocument @xmlHandle OUTPUT, @subscription_xml,'<root xmlns:ns1="http://integration.digitalriver.com/SubscriptionService"/>' 

	SELECT @ParentLocalName = parentLocalName
	FROM OPENXML (@xmlHandle,'//',8) with 
		  (parentIDNo int '@mp:parentid',parentLocalName varchar(50) '@mp:parentlocalname') 
		  where parentIDNo = 0

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert into dr_subscription table
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into dr_subscription (subscription_id, dr_user_id, vendor_order_code, dr_product_id, product_id, locale, keycode,  xml_type)
	values (@subscription_id, @dr_user_id, @vendor_order_code, @dr_product_id, @product_id, @locale, @keycode,  @ParentLocalName)

	select @dr_subscription_id = scope_identity()
	
	insert into dr_subscription_xml(dr_subscription_id,dr_subscription_xml)
	values(@dr_subscription_id,convert(nvarchar(max),@subscription_xml))

	-- -------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
	-- 3.) post processing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @vendor_order_id int
	
	-- 3.1) check to see if order notification is complete
	select @vendor_order_id = vendor_order_id from vendor_order where vendor_order_code = @vendor_order_code
	
	if @vendor_order_id is null
		begin
			insert into dr_subscription_reprocess(dr_subscription_id,xml_type)
			values(@dr_subscription_id,@ParentLocalName)
		end
	else
		begin
	-- 3.2) complete processing	
		-- 3.2.1) update order item license for AR orders
			if @ParentLocalName = 'SubscriptionRenewalSuccessNotificationRequest'
				begin
				exec usp_dr_subscription_update_order_item_license @dr_subscription_id
				end

		-- 3.2.2) insert service 
			declare @sql_string varchar(4000),
					@db_name varchar(100),
					@system_user varchar(50)

			select @system_user = suser_sname(),
					@db_name = db_name()

			select @sql_string = 
					'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
					' values	(' + convert(varchar(10),@dr_subscription_id) + ',' + '''' + 'exec ' + @db_name + '..usp_dr_subscription_insert_license_subscription ' + convert(varchar(10),@dr_subscription_id) + ', ''''' + @ParentLocalName + '''''''' + ',0,getdate()) '
			--print @sql_string

			exec (@sql_string)

			exec tasks..usp_queue_task @dr_subscription_id
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) select values 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select subscription_id = @subscription_id,
		dr_user_id = @dr_user_id,
		vendor_order_code = @vendor_order_code, 
		dr_product_id = @dr_product_id, 
		product_id = @product_id, 
		locale = @locale, 
		keycode = @keycode,
		xml_type = @ParentLocalName

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not load subscription xml'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_reprocess]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_dr_subscription_reprocess]

/*	
	DATE		AUTHOR		REMARKS
	2012-05-24	esmart		Initial creation.
	2015-02-20	mrobbins	added attempts - in case of error will continue to next record

	DESCRIPTION
	reprocess subscriptions loaded before order load
*/

AS
	set nocount on				

	declare @dr_subscription_id int,
			@xml_type varchar(50),
			@response_code int,
			@message varchar(100),
			@attempts int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) setup @dr_subscription_reprocess
	declare @dr_subscription_reprocess table (row_id int identity(1,1), dr_subscription_id int, xml_type varchar(50), attempts int)

	update dr_subscription 
	set processed = 1
	where processed = 0
		and attempts >= 3
	
	insert into @dr_subscription_reprocess(dr_subscription_id, xml_type, attempts)
	select s.dr_subscription_id, s.xml_type, s.attempts
	from dr_subscription_reprocess r
	inner join dr_subscription s
		on r.dr_subscription_id = s.dr_subscription_id
	inner join vendor_order v	
		on s.vendor_order_code = v.vendor_order_code
	where s.processed = 0
		and s.attempts < 3
		
	-- 2.0) loop through orders to reprocess
	declare @rows int, @current_row_id int
	
	select @rows = count(*), @current_row_id = 1 from @dr_subscription_reprocess
	
	while @rows >= @current_row_id
		begin
		print @current_row_id
		
		-- 2.1) get params
		--print '2.1'
		select @dr_subscription_id = dr_subscription_id, @xml_type = xml_type, @attempts = attempts
		from @dr_subscription_reprocess 
		where row_id = @current_row_id 
		
		select dr_subscription_id = @dr_subscription_id, xml_type = @xml_type, attempts = @attempts
		
		-- 2.2) check for autorenewal orders
		--print '2.2'
		if @xml_type = 'SubscriptionRenewalSuccessNotificationRequest'
			begin
				exec usp_dr_subscription_update_order_item_license @dr_subscription_id
			end
	
		-- 2.3) complete subscription management
		--print '2.3'

		set @attempts = @attempts + 1

		exec usp_dr_subscription_insert_license_subscription @dr_subscription_id, @xml_type
		update dr_subscription set processed = 1, attempts = @attempts where dr_subscription_id = @dr_subscription_id
		
		-- 2.4) delete row
		--print '2.4'
		delete from dr_subscription_reprocess where dr_subscription_id = @dr_subscription_id
		
		select @current_row_id = @current_row_id + 1
		
		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

		set @attempts = @attempts + 1
		update dr_subscription 
		set attempts = @attempts 
		where dr_subscription_id = @dr_subscription_id
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_select_next_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_subscription_select_next_update]

(
	@batch_limit_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-21	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100)

begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get next update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top 1 u.dr_subscription_update_id, s.subscription_id, s.dr_user_id, a.dr_subscription_action_id, a.dr_subscription_action, u.dr_subscription_date, st.dr_subscription_update_status_id, st.dr_subscription_update_status, u.insert_date, u.modified_date
	from dr_subscription_update u
	inner join dr_license_subscription s
		on u.dr_license_subscription_id = s.dr_license_subscription_id
	inner join dr_subscription_action a
		on u.dr_subscription_action_id = a.dr_subscription_action_id
	inner join dr_subscription_update_status st
		on u.dr_subscription_update_status_id = st.dr_subscription_update_status_id
	where u.dr_subscription_update_status_id in (1,3) and u.modified_date <= @batch_limit_date
	order by u.dr_subscription_update_status_id, u.modified_date, u.dr_subscription_update_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'No subscriptions to update'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_select_update_batch]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_subscription_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2009-05-21	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100)

begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get batch
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = max(modified_date)
	from dr_subscription_update u
	where u.dr_subscription_update_status_id in (1,3)

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'No subscriptions to update'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_update_license_subscription]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_subscription_update_license_subscription]

(
	@dr_license_subscription_id int,
	@license_id int,
	@storage_upgrade_product tinyint,
	@dr_subscription_change_reason_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2009-11-25	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100),
			@dr_subscription_status_id tinyint

begin try

--select * from dr_subscription_status

--	dr_subscription_status_id	dr_subscription_status
--1	pending license activation
--2	active
--3	cancelled
--4	domestic autorenewal license

--dr_subscription_change_reason_id	dr_subscription_change_reason	dr_subscription_status_id
--								1	product upgrade					3
--								2	new renewal subscription		2
--								3	new subscription				3
--								4	expiration date update			1
--								5	autorenewal opt out				3
--								6	fraud							3
--								7	DR cancel						3


	select @dr_subscription_status_id = case
				when @dr_subscription_change_reason_id = 1 then 3
				when @dr_subscription_change_reason_id = 2 then 3
				when @dr_subscription_change_reason_id = 3 then 3
				when @dr_subscription_change_reason_id = 4 then 1
				when @dr_subscription_change_reason_id = 5 then 3
				when @dr_subscription_change_reason_id = 6 then 3
				when @dr_subscription_change_reason_id = 7 then 3
				when @dr_subscription_change_reason_id = 8 then 2
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) build up table of subscriptions
		declare @existing_subscription_detail table (dr_license_subscription_id int, subscription_id bigint, dr_subscription_status_id int, license_category_id tinyint, storage_upgrade_product tinyint)

		insert into @existing_subscription_detail(dr_license_subscription_id,subscription_id,dr_subscription_status_id,license_category_id,storage_upgrade_product)
		select dr_license_subscription_id,subscription_id,dr_subscription_status_id,license_category_id,
				storage_upgrade_product = case
										when p.product_description like '%Backup%' then 1
										else 0
									end
		from dr_license_subscription s
		left join product_license_category c
			on s.product_id = c.product_id
		inner join product p
			on s.product_id = p.product_id
		where s.license_id = @license_id and dr_license_subscription_id <> @dr_license_subscription_id and
				s.dr_subscription_status_id in (1,2)


	-- 1.2) add cancel update
		insert into dr_subscription_update(dr_license_subscription_id, dr_subscription_action_id, dr_subscription_date, dr_subscription_update_status_id)
		select s.dr_license_subscription_id, 
				dr_subscription_action_id = 3,
				s.current_expiration_date,
				dr_subscription_update_status_id = 1
		from dr_license_subscription s
		inner join @existing_subscription_detail e
				on s.dr_license_subscription_id = e.dr_license_subscription_id
		where storage_upgrade_product = @storage_upgrade_product

	-- 1.3) insert dr_license_subscription_history
	insert into dr_license_subscription_history (dr_license_subscription_id, current_expiration_date, dr_subscription_status_id, last_modified_date, dr_subscription_change_reason_id)
	select s.dr_license_subscription_id, s.current_expiration_date, s.dr_subscription_status_id, s.last_modified_date, @dr_subscription_change_reason_id
	fr
om dr_license_subscription s
	inner join @existing_subscription_detail e
			on s.dr_license_subscription_id = e.dr_license_subscription_id
	where storage_upgrade_product = @storage_upgrade_product

	-- 1.4) update dr_license_subscription
	update dr_license_subscription
	set dr_subscription_status_id = @dr_subscription_status_id, last_modified_date = getdate()
	from dr_license_subscription s
	inner join @existing_subscription_detail e
			on s.dr_license_subscription_id = e.dr_license_subscription_id
	where storage_upgrade_product = @storage_upgrade_product

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update dr_license_subscription for @dr_license_subscription_id ( ' + convert(varchar(20),@dr_license_subscription_id) + ')'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_update_order_item_license]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_subscription_update_order_item_license]

(
	@dr_subscription_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-21	esmart		Initial creation.
	2015-01-02	esmart		Look up product from dr_product
	
	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100),
			@vendor_order_code varchar(100),
			@product_id int,
			@dr_product_id int,
			@keycode varchar(40),
			@license_id int,
			@order_item_id int,
			@order_header_id int,
			@order_type_group_id int

	select @order_type_group_id = 1

begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) subscription data
	select @vendor_order_code = vendor_order_code,
			@product_id = product_id,
			@dr_product_id = dr_product_id,
			@keycode = keycode
	from dr_subscription 
	where dr_subscription_id = @dr_subscription_id
	
	if @product_id is null or @product_id = 0
		begin
		select @product_id = product_id from dr_product_price where dr_product_id = @dr_product_id
		end

	if @product_id is null or @product_id = 0
		begin
		select @product_id = product_id from dr_product where dr_variation_product_id = @dr_product_id
		end

	-- 1.2) license_id
	select @license_id = license_id from license where keycode = @keycode

	if @license_id is null
		begin
		select @license_id = license_id from license_keycode_alias where keycode_alias = @keycode
		end

	-- 1.3) order item and header
	select @order_item_id = i.order_item_id,
			@order_header_id = h.order_header_id
	from vendor_order v with (nolock)
	inner join order_header h with (nolock)
		on v.vendor_order_id = h.vendor_order_id
	inner join order_item i with (nolock)
		on h.order_header_id = i.order_header_id
	inner join product p with (nolock)
		on i.product_id = p.product_id and p.uses_keycode = 1
	left join order_item_license il with (nolock)
		on i.order_item_id = il.order_item_id
	where v.vendor_order_code = @vendor_order_code and v.vendor_id = 2 and 
		il.order_item_license_id is null

	--select dr_product_id = @dr_product_id, product_id = @product_id, order_header_id = @order_header_id, vendor_order_code = @vendor_order_code, order_item_id = @order_item_id, license_id = @license_id
	--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update order
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @order_item_id is not null
		begin

		-- 2.1) insert order_item_license record 
		insert into order_item_license(order_item_id, license_id) values(@order_item_id,@license_id)

		-- 2.2) insert license update queue
		exec usp_cart_insert_license_update_queue @order_header_id, @order_type_group_id

		end
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update order from subscription'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_dr_subscription_update_status]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_dr_subscription_update_status]

(
	@dr_subscription_update_id int,
	@dr_subscription_update_status_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-21	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				
	
	declare @response_code int,
			@message varchar(100),
			@update_attempts tinyint

begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get update attempts
	select @update_attempts = update_attempts + 1
	from dr_subscription_update
	where dr_subscription_update_id = @dr_subscription_update_id

	-- 1.2) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @dr_subscription_update_status_id = 3 -- failed
		begin
		select @dr_subscription_update_status_id = 4 -- abandoned
		end

	-- 1.3) update dr_subscription_update
	update dr_subscription_update
	set dr_subscription_update_status_id = @dr_subscription_update_status_id, 
		update_attempts = @update_attempts,
		modified_date = getdate(), 
		modified_by = suser_sname()
	where dr_subscription_update_id = @dr_subscription_update_id


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update dr_subscription_update for @dr_subscription_update_id ( ' + convert(varchar(20),@dr_subscription_update_id) + ')'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
