-- PROCEDURE: [dbo].[usp_drop_license_activity_refresh_tbl]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_drop_license_activity_refresh_tbl]
AS
/*

Date        Author        Remarks
----------------------------------
07/30/2013   surpal	       Initial - Drops old license_activity_refresh% table based on retention

*/

SET NOCOUNT ON

DECLARE @crdate DATETIME
DECLARE @dropcnt INT
DECLARE @drptblstr NVARCHAR(200)
DECLARE @tblname VARCHAR(150)

SELECT @crdate = GETDATE()-2
SELECT @dropcnt = 0

SELECT 'DROP TABLE ' + name AS tblname, ROW_NUMBER()OVER(ORDER BY name) As rowcnt INTO #tmpdroptbl FROM sys.sysobjects WHERE xtype='u' AND name LIKE 'license_activity_refresh_l1a2r3%' AND crdate < @crdate ORDER BY crdate DESC

SELECT @dropcnt=COUNT(*) FROM #tmpdroptbl

WHILE @dropcnt > 0
BEGIN
	SELECT @drptblstr=tblname FROM #tmpdroptbl WHERE rowcnt=@dropcnt
		
	PRINT @drptblstr
	
	BEGIN TRY
	EXEC sp_executesql @drptblstr
	END TRY

	 BEGIN CATCH
       DECLARE @dbname VARCHAR(100)
       SET @dbname = DB_NAME()
	   EXEC usp_LogError @ErrorDB = @dbname

	   RAISERROR('Drop License Activity refresh table Failed, proc:usp_drop_license_activity_refresh_tbl!! '  , 16,1)
	   
  END CATCH


	SET @dropcnt=@dropcnt-1;
END 



DROP TABLE #tmpdroptbl


GO
