-- PROCEDURE: [dbo].[usp_ecommerce_order_check]
-- =============================================================================











CREATE proc [dbo].[usp_ecommerce_order_check]
	@debug varchar(3) = 'YES'
as
/*
2010-05-03	dsmelker	Modified to call sp_send_dbmail

*/
declare
	@invoice_code varchar(16),
	@purchased_date datetime,
	@customer_code varchar(16) ,
	@last_name nvarchar(64) ,
	@first_name nvarchar(64) ,
	@cdate datetime ,
	@amount decimal(10,2) ,
	@delta bigint ,
	@recipients varchar(1000) ,
	@msg varchar(1000) ,
	@subj varchar(1000)
select 
	@invoice_code = vendor_order_id ,
	@purchased_date = insert_date ,
	@cdate = now ,
	@amount = total_amount ,
	@delta = time ,
	@customer_code = customer_id ,
	@first_name = first_name ,
	@last_name = last_name ,
	@purchased_date = insert_date
from (
	select top 1 
		vendor_order_id, oh.insert_date, getdate() as now, total_amount, datediff(s, oh.insert_date, getdate()) time,
		c.customer_id, first_name, last_name 
	from 
		order_header oh with(nolock)
		inner join customer_order co with(nolock) 
			on co.order_header_id = oh.order_header_id
		inner join customer c with(nolock) 
			on c.customer_id = co.customer_id
	where total_amount > 0 
	order by oh.order_header_id desc 
	) a

if @delta > 600
begin
	if @debug = 'YES'
	begin
		select @recipients = 'WR-DLWebrootWebQA@opentext.com;CARB-DBMonitoring@opentext.com'
		select @subj = 'INF: Order Check Error QA Validation'
	end
	else
	begin
		select @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;WR-DLWebDevDB@opentext.com;CARB-DBMonitoring@opentext.com'
		select @subj = 'INF: Order Check Error'
	end

	select @msg = 	'
There have been no transactions in the last 15 minutes.

This alert may come in during low volume hours.  If this error is received during other times there MAY be an issue with receiving orders.

The details of the last transaction are as follows:
  Purchased Date: ' + convert( varchar(20) ,@purchased_date ) + '
         Invoice: ' + @invoice_code + '
          Amount: ' + convert( varchar, @amount) + '
   Customer Code: ' + @customer_code + '
       Last Name: ' + @last_name + '
      First Name: ' + @first_name + '

Generated by the Order Check Monitor job on '+@@servername+'.
'

	exec msdb.dbo.sp_send_dbmail
		@recipients  = @recipients,
		--@profile_name='DCO DBA',
		@SUBJECT = @subj ,
		@body = @msg 
end







GO
