-- PROCEDURE: [dbo].[usp_ecommerce_s2_license_monitoring]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_ecommerce_s2_license_monitoring]



       @debug varchar(3) = 'YES'



as



/*



		2014-11-14    acoffel      s2 monotoring







*/



declare



       @history_date datetime,



	   @delta bigint,



	   @cdate datetime,



       @recipients varchar(1000),



       @body varchar(1000),



       @subject varchar(1000),



	   @servername varchar(50)



select 



       @history_date = history_date,



       @cdate = now,



       @delta = time



from (



       select top 1 subscription_id, history_date, getdate() as now, datediff(s,history_date, getdate()) time



       from subscription_history with(nolock)



       order by subscription_history_id desc 



       ) a











print @delta







if @delta > 1200



begin



  select @servername = @@SERVERNAME



       , @subject = ' Possible issue with S2 license management'



       , @body = 'There have been no Best Buy - S2 transactions in the last 10 minutes. Last Transaction was at ' + CONVERT(varchar(30),@history_date,100) + '. Please Investigate! '



               + char(10) + char(13) 



			   + char(10) + char(13)



			   + 'Email generated via Monitor S2 License Management Queue on ' + RTRIM(@servername) + '.This job runs every 10mins.'



       , @recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;wr-DLWebDevDB@opentext.com;CARB-DBMonitoring@opentext.com'; 







  exec msdb..sp_send_dbmail 



    @recipients = @recipients,



    @body = @body,



    @subject = @subject,

	--@profile_name = 'DCO DBA',



    @importance = 'High';



end


















GO
