-- PROCEDURE: [dbo].[usp_email_api_alerts]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_email_api_alerts]

( @email VARCHAR(200),
  @queuename VARCHAR(50)
 
  )
   AS

/*

Date            Author         version              Remarks
============================================================
11/8/2019            ugangichetty       1.0         Email API Monitor

*/

DECLARE  @count INT
		 ,@Threshold INT
              ,@alertemail VARCHAR(200)
              ,@subject    VARCHAR(200)
              ,@query      NVARCHAR(4000)
              ,@body       NVARCHAR (500);

select top 1  @count=api_count from api_alerts where queue_name=@queuename and
 alert_date > DATEADD(mi, -1, getdate())

 
select @Threshold=record_threshold from api where api_queue_name=@queuename
if @count> @Threshold

BEGIN

Print 'There is something wrong'

  SELECT @alertemail = @email
            ,@subject   = 'CRITICAL!!! ' + @queuename + ' API alert on  '+@@SERVERNAME
           
	 IF @count>1
     BEGIN
              EXEC msdb.dbo.sp_send_dbmail
                           @recipients  = @alertemail
						  ,@query       = @query
                       , @subject     = @subject
					   , @importance  = 'High'
                       , @body_format = 'HTML';
          END
END
  ELSE
       PRINT @queuename +'  is working fine'
GO
