-- =============================================================================
CREATE PROCEDURE [dbo].[usp_email_api_alerts_prevx]    
AS  
BEGIN  
 DECLARE @PrevxCount INT;  
 DECLARE @Threshold INT;  
  
 SELECT @PrevxCount = COUNT(*)  
 FROM Prevx_Update  
 WHERE prevx_update_type_id != 100  
  
 SELECT @Threshold = record_threshold   
 FROM api  
 WHERE api_id = 13 --prevx_update  
  
 SELECT @PrevxCount  
 SELECT @Threshold  
  
 IF @PrevxCount > @Threshold  
 BEGIN  
  PRINT 'Problem in Prevx - Over threshold'  
  INSERT INTO api_alerts VALUES ('Prevx_Update', @PrevxCount, GETDATE())  
 END  
 ELSE  
  PRINT 'Nothing is wrong'  
  
END
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_email_cart_order_insert]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_email_cart_order_insert]


/*	
	DATE		AUTHOR		REMARKS
	2016-02-04	mrobbins	intial creation
	2016-05-24	mrobbins	added SMB
	2016-06-06	mrobbins	changed "back up" to only go back 12 hours instead of 24 hours
	2017-06-05	mrobbins	changed time from 25 minutes to 60 minutes per US20848
	2017-08-07	mrobbins	extended customer_email to be 255 characters
	2018-02-21	mrobbins	excluded people who made purchases ALCHEMISTS 843
	2018-06-29	mrobbins	ALCHEMISTS 1061 - change to use cart_order for new cart changes
	2026-04-20  psatish		US-5316864 Insert only Business orders into the table: @tmp_email_cart_order table

	DESCRIPTION

*/

AS

	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@cart_discount_message_description varchar(50), 
			@message_type_id int, 
			@insert_by varchar(20), 
			@cart_discount_message_value_xml_str varchar(max), 
			@cart_discount_message_id int,
			@tmp_email_cart_order_id int,
			@max_tmp_email_cart_order_id int,
			@cart_order_id INT
            
	 DECLARE @BUSINESS_PRODUCT_LINES TABLE
    (
        product_line_id INT
    )

	INSERT INTO @BUSINESS_PRODUCT_LINES
	(
	    product_line_id
	)
	SELECT [key]
	FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL')

	begin try

		
		update eco
		set eco.status = 1
		from email_cart_order eco with (nolock)
			inner join cart_order coip with (nolock)
				on eco.cart_order_in_process_id = coip.cart_order_id
		where coip.cart_order_status_id <> 1


		declare @emails table (email_id INT IDENTITY(1,1),
				email varchar(255));
		
		insert into @emails(email)
		select distinct cocip.customer_email
		from email_cart_order eco with (nolock)
			inner join cart_order_in_process coip with (nolock)
				on eco.cart_order_in_process_id = coip.cart_order_in_process_id
			inner join cart_order_customer_in_process cocip with (nolock)
				on coip.cart_order_in_process_id = cocip.cart_order_in_process_id
		where insert_date >= getdate()-1
			and insert_date < getdate()

		insert into @emails(email)
		select distinct cc.customer_email
		from email_cart_order eco with (nolock)
			inner join cart_order co with (nolock)
				on eco.cart_order_in_process_id = co.cart_order_id
			INNER JOIN cart_customer cc with (nolock)
				ON co.cart_order_id = cc.cart_order_id
		where eco.insert_date >= getdate()-1
			and eco.insert_date < getdate()

		insert into @emails(email)
		SELECT DISTINCT ce.customer_email
		FROM vendor_order vo
			INNER JOIN order_header oh
				ON vo.vendor_order_id = oh.vendor_order_id
			INNER JOIN order_item oi
				ON oh.order_header_id = oi.order_header_id
			INNER JOIN order_item_license oil
				ON oi.order_item_id = oil.order_item_id
			INNER JOIN license l
				ON oil.license_id = l.license_id
			INNER JOIN customer_email ce
				ON l.customer_id = ce.customer_id
		WHERE vo.insert_date >= getdate()-1
					and vo.insert_date < getdate()


		declare @tmp_email_cart_order table (tmp_email_cart_order_id INT IDENTITY(1,1),
				cart_order_id int);

		insert into @tmp_email_cart_order(cart_order_id)
		select distinct co.cart_order_id
		from cart_order co with (nolock)
			INNER JOIN cart_customer cc with (nolock)
				on co.cart_order_id = cc.cart_order_id
			inner join cart_order_item coi with (nolock)
				on co.cart_order_id = coi.cart_order_id
			left join email_cart_order eco  with (nolock)
				on co.cart_order_id = eco.cart_order_in_process_id
			inner join product p	
				on coi.product_id = p.product_id
			INNER JOIN @BUSINESS_PRODUCT_LINES pl
				ON pl.product_line_id=p.product_family_id
		where co.cart_order_status_id = 1
			and co.modified_date > dateadd(hh, -12,getdate
())
			and co.modified_date <= dateadd(mi,-60,getdate())
			and co.order_type in ('WRCART','WRENTERPRISECART')
			and eco.cart_order_in_process_id is null
			and cc.customer_email not in (select email from @emails)
			


			declare @proc_return table(cart_discount_message_id int, cart_discount_message_description varchar(50),cart_discount_message_key varchar(36),message_type_id int,insert_date datetime,insert_by varchar(20))
				

		select @tmp_email_cart_order_id = min(tmp_email_cart_order_id), @max_tmp_email_cart_order_id = max(tmp_email_cart_order_id)
		from @tmp_email_cart_order

		while @tmp_email_cart_order_id <= @max_tmp_email_cart_order_id
			begin

				set @cart_discount_message_description = NULL
				set @message_type_id = NULL
				set @cart_discount_message_id = NULL
				set @insert_by = NULL
				set @cart_discount_message_value_xml_str = NULL

				
				delete from @proc_return

				select @cart_order_id = cart_order_id
				from @tmp_email_cart_order
				where tmp_email_cart_order_id = @tmp_email_cart_order_id

				--select * from @tmp_email_cart_order 


				select @cart_discount_message_description = 'email_cart_order ' + convert(varchar(100),@cart_order_id) + ' inserted'
				  ,@message_type_id = 2
				  ,@insert_by = system_user
				  ,@cart_discount_message_value_xml_str = 
					'<root>
					<license_message_value><message_value_type_name>cart_order_id</message_value_type_name><value_id>' + convert(varchar(100),@cart_order_id) + '</value_id></license_message_value>
					</root>'
				

				
				insert into @proc_return (cart_discount_message_id, cart_discount_message_description,cart_discount_message_key,message_type_id,insert_date,insert_by)
				exec usp_cart_insert_cart_discount_message
					@cart_discount_message_description,
					@message_type_id,
					@insert_by,
					@cart_discount_message_value_xml_str,
					@cart_discount_message_id output

				
				select @cart_discount_message_id = cart_discount_message_id from @proc_return

				--select * from @proc_return return

				--select @cart_discount_message_id

				insert into email_cart_order(cart_order_in_process_id, cart_discount_message_id)
				select distinct cart_order_id,
					@cart_discount_message_id
				from @tmp_email_cart_order
				where tmp_email_cart_order_id = @tmp_email_cart_order_id
			

				set @tmp_email_cart_order_id = @tmp_email_cart_order_id + 1

			end

	end try

	begin catch
		set @response_code = -200
		set @message = case when @message is null then 'Could not insert into email_cart_order'
						else @message end
		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_email_cart_order_insert_email_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_email_cart_order_insert_email_message]


/*	
	DATE		AUTHOR		REMARKS
	2016-02-04	mrobbins	intial creation
	2016-02-11	mrobbins	changed usp_insert_email_receipts_dl_instructions call to not set status for go-live date
	2018-06-29	mrobbins	ALCHEMISTS 1061 - change to use cart_order for new cart changes

	DESCRIPTION
		inserts into email_message for 1st and 2nd email messages

		ede_abandoned_cart_first
		ede_abandoned_cart_second

	
*/

AS

	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@email1_id int,
			@max_email1_id int,
			@email2_id int,
			@max_email2_id int,
			@email1_message_id int,
			@email2_message_id int,
			@email1_cart_order_id int,
			@email2_cart_order_id int,
			@customer_email varchar(100)


	begin try
		
		----------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- First Email Inserts 25 minutes after cart started
		----------------------------------------------------------------------------------------------------------------------------------------------------------------
		declare @email1 table (email1_id INT IDENTITY(1,1),
				email_cart_order_id int)

		declare @email1_email_message_id table(email_message_id int)

		insert into @email1(email_cart_order_id)
		select distinct email_cart_order_id
		from email_cart_order
		where process_date is null
			and sent_count = 0
			and [status] = 0


		select @email1_id = min(email1_id), @max_email1_id = max(email1_id)
		from @email1

		while @email1_id <= @max_email1_id
			begin
				
				delete from @email1_email_message_id

				set @email1_message_id = NULL
				
				select @email1_cart_order_id = email_cart_order_id
				from @email1
				where email1_id = @email1_id

				select distinct @customer_email = customer_email
				from email_cart_order emc
					inner join cart_order co on 
						emc.cart_order_in_process_id = co.cart_order_id
					INNER JOIN cart_customer cc with (nolock)
						ON co.cart_order_id = cc.cart_order_id
				where email_cart_order_id = @email1_cart_order_id

				
				insert into @email1_email_message_id(email_message_id)
				exec usp_insert_email_receipts_dl_instructions @customer_email, NULL, NULL, 'ede_abandoned_cart_first',NULL

				select @email1_message_id = email_message_id
				from @email1_email_message_id


				update email_cart_order 
				set email_message_id = @email1_message_id,
					sent_count = 1,
					process_date = getdate()
				where email_cart_order_id = @email1_cart_order_id

				insert into email_cart_order_message (email_cart_order_id,email_message_id)
				values(@email1_cart_order_id,@email1_message_id)

			
			set @email1_id = @email1_id + 1

			end

		----------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- Second Email Inserts	24 hours after first email 
		----------------------------------------------------------------------------------------------------------------------------------------------------------------
		declare @email2 table (email2_id INT IDENTITY(1,1),
				email_cart_order_id int);

		declare @email2_email_message_id table(email_message_id int)

		insert into @email2(email_cart_order_id)
		select distinct email_cart_order_id
		from email_cart_order
		where process_date >= dateadd(mi,-5,getdate()-1)
			and process_date < getdate() -1 
			and sent_count = 1
			and [status] = 0


		select @email2_id = min(email2_id), @max_email2_id = max(email2_id)
		from @email2

		while @email2_id <= @max_email2_
id
			begin

				delete from @email2_email_message_id

				set @email2_message_id = NULL
				
				select @email2_cart_order_id = email_cart_order_id
				from @email2
				where email2_id = @email2_id

				select distinct @customer_email = customer_email
				from email_cart_order emc
					inner join cart_order co on 
						emc.cart_order_in_process_id = co.cart_order_id
					INNER JOIN cart_customer cc with (nolock)
						ON co.cart_order_id = cc.cart_order_id
				where email_cart_order_id = @email2_cart_order_id


				insert into @email2_email_message_id(email_message_id)
				exec usp_insert_email_receipts_dl_instructions @customer_email, NULL, NULL, 'ede_abandoned_cart_second',NULL

				select @email2_message_id = email_message_id
				from @email2_email_message_id

				update email_cart_order 
				set email_message_id = @email2_message_id,
					sent_count = 2,
					process_date = getdate(),
					status = 1
				where email_cart_order_id = @email2_cart_order_id

				insert into email_cart_order_message (email_cart_order_id,email_message_id)
				values(@email2_cart_order_id,@email2_message_id)
			
				set @email2_id = @email2_id + 1

			end



	end try

	begin catch
		set @response_code = -200
		set @message = case when @message is null then 'Could not insert into email_message'
						else @message end
		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

