CREATE PROCEDURE [dbo].[usp_email_message_reset_email_flag_to_resend]
					
 
(
		@order_header_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2014-10-29	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@order_header_id_check int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  check to see if it's the table
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		
	select @order_header_id_check = order_header_id
	from email_message 
	where order_header_id = @order_header_id
		
	
	if @order_header_id_check is NULL	 
		begin
			select 'order_header_id not in receipt table'
			return
		end
	


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	update email_message set email_message_status_id = 1 where order_header_id = @order_header_id 		


	end try

	begin catch

		set @message = case when @message is null then 'resend update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
