-- =============================================================================

CREATE PROCEDURE [dbo].[usp_email_message_select_by_order_header_id]
 
(
		@order_header_id int = NULL,
		@license_id int = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2014-10-29	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@order_header_id_check int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  check to see if it's the table
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @order_header_id_check = order_header_id
	from email_message 
	where order_header_id = @order_header_id
		
	if @order_header_id_check is NULL	 
		begin
			select 'order_header_id not in receipt table'
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select e.email_message_id, h.customer_email, h.email_message_body, c.message_campaign_id, c.message_campaign_name 
	from email_message e
