	where e.order_header_id = @order_header_id
	

	end try

	begin catch

		set @message = case when @message is null then 'select receipt failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_email_select_next_email]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_email_select_next_email]

(
       @batch_limit_date datetime
)
       
/*     
       DATE          AUTHOR        REMARKS
       2013-09-30    acoffel       Initial Creation
       2014-01-08    acoffel       added campaign name
       2015-11-03    esmart        Add order_header_id and support for NULL email_message_body
       2016-01-22    acoffel       adding JSON support and abandoned cart sends
       2016-05-24    mrobbins      added SMB support for product line 55 and 300
       2017-08-07    mrobbins      truncate customer_email to 100 characters as subsriber key only allows 100
       2018-08-29    acoffel       changed lang/loc to lower  
	   2018-12-19	 mrobbins	   accounting cc AccountsReceivable@webroot.com
	   2019-02-06	 mrobbins	   waterbears 351 - acounting added CC AccountsReceivable@webroot.com;ARWebrootServicesLTD@Webroot.com

       DESCRIPTION
       
       
*/


AS
       set nocount,
              concat_null_yields_null,
              ansi_nulls, 
              ansi_padding, 
              ansi_warnings on;
                           

       declare       @response_code int,
                     @message varchar(100)

       begin try

       select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) insert record
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       declare @email_message_record table (email_message_json nvarchar(2000), customer_email varchar(100), first_name nvarchar(255), email_message_body nvarchar(max), cart_order_in_process_id int, location_code varchar(2), language_code varchar(2), cc_email varchar(100))      

       insert into @email_message_record (email_message_json, customer_email, first_name, email_message_body, cart_order_in_process_id, location_code, language_code, cc_email)
       select top 1 email_message_json = [dbo].[fn_message_select_email_message_json_string]
       (m.email_message_id,
       c.message_campaign_name,
       c.message_campaign_description,
       m.license_id,
       mc.message_url + convert(varchar(36),dm.cart_discount_message_key),
       v.value_id,
       case when (select count(*) from cart_discount_gamer_discount where cart_discount_id = ci.cart_discount_id) > 0 then 'GAMR' else lc.license_category_name end,
       m.order_header_id),
       case when o.email_message_id is not NULL then LEFT(cc.customer_email,100) else LEFT(h.customer_email,100) end,
       cc.first_name,
       email_message_body = case when h.email_message_body = '' then null else h.email_message_body end,
       o.cart_order_in_process_id,
       location_code = (select iso from lu_countries where iso = right(co.locale,2)),
       language_code = upper(left(co.locale,2)),
	   cc_email = case when c.message_campaign_name = 'oracle_update_failure' then 'AccountsReceivable@webroot.com;ARWebrootServicesLTD@Webroot.com' else null end
       from email_message_html h
       inner join email_message m 
              on h.email_message_id = m.email_message_id
       inner join message_campaign c
              on m.message_campaign_id = c.message_campaign_id
       left join message_campaign_content mcc
              on m.message_campaign_id = mcc.message_campaign_id
       left join message_content mc
              on mcc.message_cont
ent_id = mc.message_content_id
       left join message_campaign_value v 
              on m.message_campaign_id = v.message_campaign_id
       left join email_cart_order o
              on m.email_message_id = o.email_message_id
       left join cart_order co
              on o.cart_order_in_process_id = co.cart_order_id
       left join cart_customer cc
              on cc.cart_order_id = co.cart_order_id
       left join cart_order_item ci
              on ci.cart_order_id = co.cart_order_id
       left join product_line_product lp
              on ci.product_id = lp.product_id and lp.product_line_id in (100,200,55,300)
       left join product_license_category plc
              on ci.product_id = plc.product_id
       left join license_category lc
              on plc.license_category_id = lc.license_category_id
       left join cart_discount_message dm
              on o.cart_discount_message_id = dm.cart_discount_message_id
       where m.email_message_status_id in (0,1) and m.process_date <= @batch_limit_date 
              --and m.message_campaign_id not in (327)
       order by m.process_date
       
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 2.) update variables  
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       -- 2.0) loc and lang
       if (select cart_order_in_process_id from @email_message_record) is not NULL
              begin 
                     -- 2.0) loc and lang
                     update @email_message_record
                           set email_message_json = case when email_message_json like '%[loc]%' then replace(email_message_json,'[loc]',LOWER(location_code))
                                                                     else email_message_json
                                                              end 
       
                     update @email_message_record
                           set email_message_json = case when email_message_json like '%[lang]%' then replace(email_message_json,'[lang]',LOWER(language_code))
                                                                     else email_message_json
                                                              end
              end

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) select record
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       select email_message_json, customer_email, first_name, email_message_body, cc_email from @email_message_record

       end try

       begin catch

              set @response_code = -200
              set @message = case when @message is null then 'select next email record failed'
                                                else @message end

              declare @DBName nvarchar(128)
              set @DBName = db_name()
              exec usp_LogError @ErrorDB = @DBName
              
       end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_email_select_update_batch]
