CREATE PROCEDURE [dbo].[usp_email_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2013-07-27	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	select batch_count = count(*), batch_limit_date = getdate()
	from email_message_html h
	inner join email_message m	
		on h.email_message_id = m.email_message_id
	where m.email_message_status_id in (1) and process_date <= getdate()

	

GO
