-- =============================================================================
-- PROCEDURE: [dbo].[usp_ent_select_next_mc_update]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_ent_select_next_mc_update]

(

      @product_id int,
      @product_version varchar(20),
      @def_version int, -- AV def version or masters version
      @is_av_update int  -- boolean: 0 = spydef update, non-zero = AV def update

)

AS
    declare @update_sequence_id int,
            @version_tag varchar(10),
		    @version_number int

    -- 1) build version tag
	set @version_tag =
	case
		when @is_av_update <> 0 then 'SSAVDef'
		else 'SSDef'
	end
	
	set @version_number =
	case @product_version
		when '3.1'   then 30 -- versions 3.0 and 3.1 use the same def. types
		when '3.1.5' then 32 -- version 3.1.5 is a special case
		when '3.5'   then 32 -- versions 3.1.5 and 3.5 use the same def. types
		else convert(int, convert(real, @product_version)*10)
	end

	if @version_number <> 21
		begin
			set @version_tag = @version_tag + convert(varchar(4), @version_number)
		end

    -- At this point @version_tag will be
    --   SSDef      for 2.1
    --   SSDef25    for 2.5
    --   SSDef30    for 3.0 or 3.1
    --   SSDef32    for 3.1.5 or 3.5 (spy def)
    --   SSAVDef32  for 3.1.5 or 3.5 (AV def)
    --   SSDefXY    for any X.Y

      -- 2) select max full update.

		set @update_sequence_id = (select max(pu.update_sequence_id)
				from ent_product_update pu
				inner join ent_product_update_file puf 
					on pu.ent_product_update_id=puf.ent_product_update_id
				inner join ent_product_product_update ppu
					on pu.ent_product_update_id=ppu.ent_product_update_id
				inner join (
					select  pup1.ent_product_update_id
						from ent_product_update_property pup1
						inner join ent_product_update_property pup2
							on pup1.ent_product_update_id=pup2.ent_product_update_id
						where
							pup1.ent_property_id = 106  and pup1.property_value=@version_tag -- 'UpdateInfo.Tag'
						and pup2.ent_property_id = 1000 and convert(int,pup2.property_value) > @def_version -- 'Version'
                    ) pup 
					on pu.ent_product_update_id=pup.ent_product_update_id
				where ppu.product_id = @product_id and
					ppu.product_version = @product_version and
					pu.ent_update_type_id = 
							case
								when @is_av_update <> 0 then 300
								else 200
							end
        )


	if @update_sequence_id is null 
			begin
	 -- 3) select next incremental update 

			set @update_sequence_id = (
				select min(pu.update_sequence_id)
				from ent_product_update pu
				inner join ent_product_update_file puf 
					on pu.ent_product_update_id=puf.ent_product_update_id
				inner join ent_product_product_update ppu
					on pu.ent_product_update_id=ppu.ent_product_update_id
				inner join (
					select  pup1.ent_product_update_id
						from ent_product_update_property pup1
						inner join ent_product_update_property pup2
							on pup1.ent_product_update_id=pup2.ent_product_update_id
						where
							pup1.ent_property_id = 106  and pup1.property_value=@version_tag -- 'UpdateInfo.Tag'
						and pup2.ent_property_id = 1000 and convert(int,pup2.property_value) > @def_version -- 'Version'
                ) pup 
					on pu.ent_product_update_id=pup.ent_product_update_id
				where ppu.product_id = @product_id and
					ppu.product_version = @product_version and
					pu.ent_update_type_id = 
						case
							when @is_av_update <> 0 then 301
							else 201
						end
            )

--			select update_sequence_id = @update_sequence_id
--			return
			end

	-- 4) return result
	select	updateseq = pu.update_sequence_id, puf.filepath
		from ent_product_update pu  
		inner join ent_product_update_file puf 
			on pu.ent_product_update_id=puf.ent_product_update_id
		where pu.update_sequence_id = @update_seque
nce_id


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_ent_select_update_list]
-- =============================================================================





CREATE PROCEDURE [dbo].[usp_ent_select_update_list]

(
	@product_id int,
	@product_version varchar(20),
	@current_update_sequence_id int,
	@av_enabled int
)


/*	
	DATE			AUTHOR			REMARKS
	2007-03-12		esmart			Initial creation
	2007-03-28		esmart			Modification to support ent_stopcode
	2007-05-16		skudrya			Selection of most recent updates, fix for TTP6250
	2007-05-31		skudrya			TTP6250: Implemented special case for SSE 3.0/3.1 to take advantage of the "rule of 10"
	2007-06-06		skudrya			TTP6250: Completely revamped the select query.

	DESCRIPTION
	select list of updates

	DETAILS
	The resulting update list may include:
	SSE 2.5
		Most recent AS update for SSE 2.1
		Most recent AS update for SSE 2.5
		Any software updates for 2.1 and 2.5
	SSE 3.0/3.1
		Any updates for SSE 2.5 (see above) excluding software packages for 2.1 and 2.5
		Most recent 11 AS updates for 3.0/3.1
		Any software updates for 3.0 and 3.1
	SME 3.1.5
		Any updates for SSE 3.0/3.1 (see above) excluding software packages for 3.0/3.1
		Most recent full AS update + all subsequent incrementals
		Most recent full AV update + all subsequent incrementals
		Any software updates for 3.1.5
	SSE	3.5
		Same as SME 3.1.5 (see above) excluding updates for 2.1 (no more support for 2.1) and software packages for 3.1.5
*/

AS
	declare @stop_update_sequence_id int,
			@full_spydef_sequence_id int,
			@full_avdef_sequence_id int


	-- 1) find stop code
	select @stop_update_sequence_id = min(stop_update_sequence_id) 
	from ent_stopcode
	where @current_update_sequence_id < stop_update_sequence_id 
		and product_id = @product_id 
		and (product_version = @product_version or  product_version = '')

	-- 2) find the most recent full spydef package
	select @full_spydef_sequence_id = max(pu.update_sequence_id) 
	from ent_product_update pu
		inner join ent_product_product_update ppu
			on pu.ent_product_update_id=ppu.ent_product_update_id
		inner join ent_product_update_property pup1
			on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
	where ppu.product_id = @product_id 
		and ppu.product_version = @product_version
		and pu.update_sequence_id > @current_update_sequence_id
		and pu.update_sequence_id <= @stop_update_sequence_id
		and pu.ent_update_type_id = 200
		and pup1.property_value = 'SSDef32'

	if @full_spydef_sequence_id is null
		set @full_spydef_sequence_id = @current_update_sequence_id + 1

	-- 3) find the most recent full AV def package if AV updates are requested
	--if @av_enabled <> 0
	--begin
	--	select @full_avdef_sequence_id = max(pu.update_sequence_id) 
	--	from ent_product_update pu
	--		inner join ent_product_product_update ppu
	--			on pu.ent_product_update_id=ppu.ent_product_update_id
	--	inner join ent_product_update_property pup1
	--		on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
	--	where ppu.product_id = @product_id 
	--		and ppu.product_version = @product_version
	--		and pu.update_sequence_id > @current_update_sequence_id
	--		and pu.update_sequence_id <= @stop_update_sequence_id
	--		and pu.ent_update_type_id = 300
	--		and pup1.property_value = 'SSAVDef32'

	--	if @full_avdef_sequence_id is null
	--		set @full_avdef_sequence_id  = @current_update_sequence_id + 1
	--end

	-- TODO analyze execution plan, optimize

	-- 4) select results
	select	updateseq = pu.update_sequence_id, 
			puf.filepath
	from ent_product_update pu  
			inner join (

					-- all software updates
					select pu.ent_product_update_id 
					from ent_product_update pu
						inner join ent_product_product_update ppu
							on pu.ent_product_update_id=ppu.ent_product_update_id
					where ppu.produ
ct_id = @product_id 
						and ppu.product_version = @product_version
						and pu.update_sequence_id > @current_update_sequence_id
						and pu.update_sequence_id <= @stop_update_sequence_id
						and pu.ent_update_type_id < 200

				union all

					-- most recent AS update for 2.1
					select pu.ent_product_update_id
					from ent_product_update pu
						inner join (
						select max(pu.update_sequence_id) as update_sequence_id
						from ent_product_update pu
							inner join ent_product_product_update ppu
								on pu.ent_product_update_id=ppu.ent_product_update_id
							inner join ent_product_update_property pup1
								on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
						where ppu.product_id = @product_id 
							and ppu.product_version = @product_version
							and pu.update_sequence_id > @current_update_sequence_id
							and pu.update_sequence_id <= @stop_update_sequence_id
							and pup1.property_value = 'SSDef'
					) maxseq
						on pu.update_sequence_id=maxseq.update_sequence_id

				union all

					-- most recent AS update for 2.5
					select pu.ent_product_update_id
					from ent_product_update pu
						inner join (
						select max(pu.update_sequence_id) as update_sequence_id
						from ent_product_update pu
							inner join ent_product_product_update ppu
								on pu.ent_product_update_id=ppu.ent_product_update_id
							inner join ent_product_update_property pup1
								on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
						where ppu.product_id = @product_id 
							and ppu.product_version = @product_version
							and pu.update_sequence_id > @current_update_sequence_id
							and pu.update_sequence_id <= @stop_update_sequence_id
							and pup1.property_value = 'SSDef25'
					) maxseq
						on pu.update_sequence_id=maxseq.update_sequence_id

				union all

					-- the recent 11 full spydef packages for SSE 3.0/3.1 installations
					-- Reason: Take full advantage of "the rule of 10" - the SSE clients download 
					-- up to 10 incremental updates before downloading a full update.
					select * from (
					select top 11  pu.ent_product_update_id 
					from ent_product_update pu
						inner join ent_product_product_update ppu
							on pu.ent_product_update_id=ppu.ent_product_update_id
						inner join ent_product_update_property pup1
							on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
					where ppu.product_id = @product_id 
						and ppu.product_version = @product_version
						and pu.update_sequence_id > @current_update_sequence_id
						and pu.update_sequence_id <= @stop_update_sequence_id
						and pup1.property_value = 'SSDef30'
					order by
						pu.update_sequence_id desc
					) a -- just a wrapper to prevent error "ORDER BY items must appear in the select list if the statement contains a UNION operator."

				union all

					-- spydefs: most recent full spydef update + all its dependent incrementals
					select pu.ent_product_update_id 
					from ent_product_update pu
						inner join ent_product_product_update ppu
							on pu.ent_product_update_id=ppu.ent_product_update_id
						inner join ent_product_update_property pup1
							on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
					where ppu.product_id = @product_id 
						and ppu.product_version = @product_version
						and pu.update_sequence_id >= @full_spydef_sequence_id
						and pu.update_sequence_id <= @stop_update_sequence_id
						and pup1.property_value = 'SSDef32'

				--union all

				--	-- AV defs: most recent full AV def update + all its dependent incrementals
				--	select pu.ent_product_update_id 
				--	from ent_product_update pu
				--		inner join ent_product_product_update ppu
				--			on pu.ent_product_update_id=ppu.ent_product_update_id
				--		inner join ent_product_update_property
 pup1
				--			on (pu.ent_product_update_id=pup1.ent_product_update_id and pup1.ent_property_id=106)
				--	where ppu.product_id = @product_id 
				--		and ppu.product_version = @product_version
				--		and pu.update_sequence_id >= @full_avdef_sequence_id
				--		and pu.update_sequence_id <= @stop_update_sequence_id
				--		and pup1.property_value = 'SSAVDef32'

			) puid
				on pu.ent_product_update_id=puid.ent_product_update_id
			inner join ent_product_update_file puf 
				on pu.ent_product_update_id=puf.ent_product_update_id

	order by
			updateseq, puf.filepath desc






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_import_campaigns]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_exact_target_import_campaigns]
( @insert_by VARCHAR(20) = NULL)
AS
SET NOCOUNT ON

/*	
	DATE		AUTHOR		REMARKS
	2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968


*/

	declare @response_code int,
		@message varchar(100),
		@campaign_id int,
		@max_campaign_id int,
		@message_campaign_id int,
		@message_campaign_name varchar(50),
		@message_campaign_description varchar(100),
		@message_campaign_class_id int,
		@message_campaign_enabled tinyint,
		@message_campaign_start_date datetime,
		@message_campaign_end_date datetime,
		@message_measure_point_id int,
		@message_measure_days int,
		@message_measure_end_days int,
		@message_duration_days int,
		@license_category_id int,
		@message_email_opt_id tinyint,
		@license_seats int,
		@message_measure_point_name varchar(50),
		@license_distribution_method_id int,
		@inclusive tinyint,
		@exact_target_master_id int,
		@capability_type tinyint,
		@cart_discount_id int,
		@return_value int,
		@categories varchar(100),
		@license_category_list varchar(500),
		@license_seats_list varchar(100),
		@message_email_opt_id_list varchar(100),
		@product_line_list varchar(100),
		@autorenewal_opt_id_list varchar(100),
		@trial_list varchar(100) = null,
		@language_location_list varchar(500) = null,
		@license_status_list varchar(500) = null,
		@subscription_type_list varchar(500) = null,
		@exact_target_file_prefix varchar(4),
		@exact_target_class varchar(50),
		@message_campaign_exact_target_name varchar(100),
		@exact_target_message_campaign_id int
		
		
	IF @insert_by IS NULL
	BEGIN
		SELECT @insert_by = SUSER_SNAME()
	END


	declare @campaigns table (campaign_id INT IDENTITY(1,1),
		message_campaign_exact_target_name varchar(50),
		exact_target_class varchar(50),
		categories varchar(100),
		exact_target_file_prefix  varchar(4),
		message_campaign_name varchar(100),
		message_measure_days int,
		meassage_measure_point_name varchar(50),
		campaign_countries varchar(50),
		capability_type int,
		message_campaign_description varchar(100),
		optid bit);

		insert into @campaigns(message_campaign_exact_target_name,
			exact_target_class,
			categories,
			exact_target_file_prefix,
			message_campaign_name,
			message_measure_days,
			meassage_measure_point_name,
			campaign_countries,
			capability_type,
			message_campaign_description,
			optid)
		select distinct vendorcampaignname message_campaign_exact_target_name,
			import_class exact_target_class,
			REPLACE(category_prefix, '''', '') categories,
			campaign_prefix exact_target_file_prefix,
			campaign_prefix + ' ' + vendorcampaignname message_campaign_name,
			numunits message_measure_days,
			measurepoint message_measure_point_name,
			campaign_countries,
			1 capability_type,
			attribdesc message_campaign_description,
			optid
		from datawarehousereadonly.feed.dbo.campaign
		where import = 1
			and vendorcampaignname not in ('ren1monthpostexp','av_welcome_msg2')
		order by vendorcampaignname

		select @campaign_id = min(campaign_id), @max_campaign_id = max(campaign_id)
			from @campaigns


			while @campaign_id <= @max_campaign_id
				begin

					select @message_campaign_name = message_campaign_name,
						@message_campaign_description = message_campaign_description,
						@message_measure_point_id = m.message_measure_point_id,
						@message_measure_days = message_measure_days,
						@message_measure_point_name = meassage_measure_point_name,
						@message_campaign_start_date = getdate(),
						@message_campaign_end_date = g
etdate() + 3650,
						@categories = c.categories,
						@message_email_opt_id_list = convert(varchar(1),optid),
						@message_campaign_exact_target_name = message_campaign_exact_target_name,
						@exact_target_class = exact_target_class,
						@exact_target_file_prefix = exact_target_file_prefix
					from @campaigns c
						inner join message_measure_point m
							on c.meassage_measure_point_name = m.message_measure_point_name
					where campaign_id = @campaign_id


					select @message_campaign_name,
						@message_campaign_description,
						@message_measure_point_id,
						@message_measure_days,
						@message_measure_point_name,
						@message_campaign_start_date,
						@message_campaign_end_date,
						@categories,
						@message_email_opt_id_list,
						@message_campaign_exact_target_name,
						@exact_target_class,
						@exact_target_file_prefix

						if @exact_target_file_prefix = 'WETI'
							begin
								set @product_line_list = 200
							end
						else
							begin
								set @product_line_list = 100
							end
	
						EXEC @return_value = usp_message_insert_message_campaign
							@message_campaign_name,
							@message_campaign_description,
							4,
							1,
							@message_campaign_start_date,
							@message_campaign_end_date,
							@message_measure_point_id,
							@message_measure_days,
							@message_measure_days,
							0,
							N'boulder/mrobbins',
							@message_campaign_id  OUTPUT

						SELECT	@message_campaign_id as N'@message_campaign_id'

						SELECT	'Return Value' = @return_value



						--Pull out each category for each campaign


						declare @categories_table table (campaign_id int,
							license_category_name varchar(10),
							message_campaign_name varchar(100),
							license_category_id int);
								
						delete from @categories_table

						insert into @categories_table
						Select s.campaign_id,
							s.String license_category_name,
							s.message_campaign_name,
							l.license_category_id
						--into #temp_categories
						from 
						(SELECT A.campaign_id,
							a.message_campaign_name,  
							Split.a.value('.', 'VARCHAR(100)') AS String  
						FROM  (SELECT campaign_id,
								message_campaign_name,  
								CAST ('<M>' + REPLACE(categories, ',', '</M><M>') + '</M>' AS XML) AS String  
								FROM  @campaigns 
								where campaign_id = @campaign_id) AS A 
							CROSS APPLY String.nodes ('/M') AS Split(a)) as S
							left join license_category l
								on s.String = l.license_category_name
						where s.campaign_id = @campaign_id

						------------------------------------------------------------------------------------------
						--if containing any of these then add 'WAV'
						--insert 'WSAV' if need be
						declare @OldCategoryCount int,
							@WSAVCategoryCount int

						select @OldCategoryCount = count(*)
						from @categories_table
						where license_category_name in ('SSDF','SSAV','SSAVDF') 

						select @WSAVCategoryCount = count(*)
						from @categories_table
						where license_category_name in ('WSAV') 

						delete 
						from @categories_table
						where license_category_name in ('SSDF','SSAV','SSAVDF') 

						if @OldCategoryCount > 0 
							begin
								insert into @categories_table(campaign_id,
									license_category_name,
									message_campaign_name,
									license_category_id)
								values (@campaign_id,
									'WAV',
									@message_campaign_name,
									2)
								if @WSAVCategoryCount < 1 
									begin
										insert into @categories_table(campaign_id,
											license_category_name,
											message_campaign_name,
											license_category_id)
										values (@campaign_id,
											'WSAV',
											@message_campaign_name,
											100)
									end
							end
						------------------------------------------------------------------------------------------------
--
								
						--build into comma delimted variable

						SET @license_category_list = '' 
						set @license_category_id = 0


						DECLARE crs_categories CURSOR 
						FOR SELECT license_category_id 
						FROM @categories_table 
						WHERE campaign_id = @campaign_id
								
						OPEN crs_categories 
								
						FETCH NEXT FROM crs_categories INTO @license_category_id 
								
						WHILE @@FETCH_STATUS = 0 
							BEGIN 
								SELECT @license_category_list = @license_category_list + CAST(@license_category_id AS varchar(5))+ ',' 

							FETCH NEXT FROM crs_categories INTO @license_category_id 
							END 
								
						if len(@license_category_list) > 0
						begin
							SET @license_category_list = SUBSTRING(@license_category_list,1,LEN(@license_category_list)-1)
						end
								 
								
						CLOSE crs_categories 
						DEALLOCATE crs_categories 
								
						SELECT @license_category_list


						if @exact_target_file_prefix = 'WETI'
							begin
								EXEC usp_message_update_message_campaign_dimensions 
									@message_campaign_id,
									@license_category_list,
									'1,3,5,10,25', --license_seats_list
									@message_email_opt_id_list,
									@product_line_list,
									'0,1',
									@trial_list,
									null,
									null,
									null,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									@insert_by
							end
						else
							begin
								EXEC usp_message_update_message_campaign_dimensions 
									@message_campaign_id,
									@license_category_list,
									'1,3,5,10,25', --license_seats_list
									@message_email_opt_id_list,
									@product_line_list,
									'0,1',
									@trial_list,
									'EN_USA,EN_AUS,EN_CAN,EN_GBR',
									null,
									null,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									NULL,
									@insert_by
							end

						insert into exact_target_message_campaign(exact_target_file_prefix_id, exact_target_class_id,message_campaign_exact_target_name)
						--values (@exact_target_file_prefix,@exact_target_class,@message_campaign_exact_target_name)
						
						SELECT etfp.exact_target_file_prefix_id,
					           etc.exact_target_class_id,
					           @message_campaign_exact_target_name
				        FROM @campaigns AS c
						     JOIN dbo.exact_target_file_prefix etfp
								ON c.exact_target_file_prefix = etfp.exact_target_file_prefix
							 JOIN dbo.exact_target_class AS etc
								ON c.exact_target_class = etc.exact_target_class

						select @exact_target_message_campaign_id  = scope_identity()


						insert into exact_target_master(exact_target_message_campaign_id, message_campaign_id)
						values (@exact_target_message_campaign_id,@message_campaign_id)

						EXEC usp_message_update_message_campaign_license_distribution_method 
							@message_campaign_id,
							0,
							'704,705,773,106,241,307,489,355,218,492,390,396,769,768,772,770,758,746,760,774,775,776,778,780,781,782,783,785,786,663,690,685',
							 NULL,
							 NULL,
							 @insert_by

					set @campaign_id = @campaign_id + 1

				end --loop



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_activation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_exact_target_message_activation]
	(@date_value DATETIME,
		@message_measure_days INT,
		@exact_target_master_id INT,
		@cart_discount_id INT,
		@exact_target_class_id INT,
		@message_campaign_name VARCHAR(65),
		@message_campaign_id INT)

AS
BEGIN
	/*

		DATE		AUTHOR			REMARKS
					mrobbins		Initial creation 
		2016-03-11	mrobbins		removed license swap licenses
		2016-12-19	mrobbins		changed license swap to only exclude licenses that moved days
		2017-01-26	mrobbins		US21233 added to check that the license hasn't expired
		2017-11-29	mrobbins		added exact_target_license_activation and capability_type_id for first activation date
		2018-01-31	mrobbins		changed trials to be activation date not required to install welcomes to require install
		2018-05-25	mrobbins		extended message_campaign_name
		2018-09-11	mrobbins		added modules for SDNS/WSAT ALCHEMISTS - 1069
		2018-11-14	mrobbins		remove console activity requirement for welcomes ALCHEMISTS - 1936
		2020-01-27	mrobbins		add license_install check for consumer welcomes
		2020-11-23	mrobbins		added  WITH (NOLOCK) AXIOM-2250
		2021-03-04	mrobbins		added license_renewals look up for renewal welcomes AXIOM 1896

	*/


	SET NOCOUNT ON;

	SELECT @date_value = convert(varchar(10),@date_value,101)

	IF @message_campaign_name LIKE '%renewwelcome%' 
		OR @message_campaign_name LIKE '%renewsmb_review%'
		BEGIN
				INSERT INTO exact_target_subset1 (exact_target_master_id,
					license_id,
					cart_discount_id,
					license_distribution_method_id,
					license_category_id,
					product_line_id,
					opt_in,
					autorenewal_opt_id,
					capability_type_id,
					license_seats)
				SELECT DISTINCT @exact_target_master_id,
					ls.license_id,
					@cart_discount_id,
					license_distribution_method_id,
					license_category_id,
					product_line_id,
					opt_in,
					autorenewal_opt_id,
					capability_type_id,
					license_seats
				FROM license_summary ls WITH (NOLOCK)
					INNER JOIN DATAWAREHOUSEREADONLY.license_warehouse.dbo.license_renewals lr
						ON ls.license_id = lr.license_id
				WHERE CAST(capability_activation_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
					AND license_status_id = 1
					AND NOT EXISTS (SELECT *
									FROM license_swap ls2
									WHERE ls.license_id = ls2.original_license_id
										and ls2.license_swap_status_id = 2) 
					AND ls.capability_expiration_date >= @date_value
					AND lr.order_header_id_1 IS NOT NULL 
        END
	ELSE
		BEGIN
			IF @exact_target_class_id = 6  --SMB Welcome Needs to be installed
				BEGIN
					INSERT INTO exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					SELECT DISTINCT @exact_target_master_id,
						ls.license_id,
						@cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						ls.capability_type_id,
						license_seats
					FROM license_summary ls WITH (NOLOCK)
						INNER JOIN exact_target_license_activation etla WITH (NOLOCK)
							ON ls.license_id = etla.license_id
						--INNER JOIN dbo.console_activity ca
						--	ON ls.license_id = ca.license_id
					WHERE CAST(etla.capability_activation_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
						AND license_status_id = 1
						AND NOT EXISTS (SELECT *
										FROM license_swap ls2
										WHERE ls.license_id = ls2.original_license_id
											and ls2.license_swap_status
_id = 2) 
						AND ls.capability_expiration_date >= @date_value

					--license modules
					INSERT INTO exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					SELECT DISTINCT @exact_target_master_id,
						lml.license_id,
						@cart_discount_id,
						ls.license_distribution_method_id,
						lc.license_category_id,
						ls.product_line_id,
						ls.opt_in,
						ls.autorenewal_opt_id,
						CASE WHEN lmt.license_module_type_id = 19 THEN 1 
							WHEN lmt.license_module_type_id = 20 THEN 2
							ELSE lmt.license_module_type_id
						END capability_type_id,
						lml.module_seats license_seats
					FROM license_module_license lml WITH (NOLOCK)
						INNER JOIN license_summary ls WITH (NOLOCK)
							ON lml.license_id = ls.license_id
						--INNER JOIN dbo.console_activity ca
						--	ON ls.license_id = ca.license_id
						INNER JOIN license_module_type lmt WITH (NOLOCK)
							ON lmt.license_module_type_id = lml.license_module_type_id
						INNER JOIN license_module_category lmc WITH (NOLOCK)
							ON lmc.license_module_id = lml.license_module_id
						INNER JOIN license_category lc WITH (NOLOCK)
							ON lc.license_category_id = lmc.license_category_id
					WHERE CAST(lml.start_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
						AND lml.license_status_id = 1
						AND NOT EXISTS (SELECT *
										FROM license_swap ls2
										WHERE ls.license_id = ls2.original_license_id
											AND ls2.license_swap_status_id = 2) 
				END
			 
			IF @exact_target_class_id = 8  --Welcome Needs to be installed
				BEGIN
					IF @message_campaign_name NOT LIKE '%wifi%'
						BEGIN
							INSERT INTO exact_target_subset1 (exact_target_master_id,
								license_id,
								cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats)
							SELECT DISTINCT @exact_target_master_id,
								ls.license_id,
								@cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							FROM license_summary ls WITH (NOLOCK)
								INNER JOIN exact_target_license_activation etla WITH (NOLOCK)
									ON ls.license_id = etla.license_id
							WHERE CAST(etla.capability_activation_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
								AND license_status_id = 1
								AND NOT EXISTS (SELECT *
												FROM license_swap ls2
												WHERE ls.license_id = ls2.original_license_id
													and ls2.license_swap_status_id = 2) 
								AND ls.capability_expiration_date >= @date_value
								AND EXISTS (SELECT *
											FROM dbo.license_install li
											WHERE li.license_id = ls.license_id)  
						END

					IF @message_campaign_name LIKE '%wifi%'
						BEGIN
							INSERT INTO exact_target_subset1 (exact_target_master_id,
								license_id,
								cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats)
							SELECT DISTINCT @exact_target_master_id,
								ls.license_id,
								@cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							FROM license_summary ls WITH (NOLOCK)
								INNER JOIN exact_target_license_activation etla WITH (NOLOCK)
									ON ls.license_id = etla.license_id

							WHERE CAST(etla.capability_activation_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
								AND license_status_id = 1
								AND NOT EXISTS (SELECT *
												FROM license_swap ls2
												WHERE ls.license_id = ls2.original_license_id
													and ls2.license_swap_status_id = 2) 
								AND ls.capability_expiration_date >= @date_value
								AND EXISTS (SELECT *
												FROM dbo.account_order ao
												WHERE ls.license_id = ao.license_id)
						END

					
				END  

			ELSE --Not 6 or 8
				BEGIN
					INSERT INTO exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					SELECT DISTINCT @exact_target_master_id,
						ls.license_id,
						@cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats
					FROM license_summary ls WITH (NOLOCK)
						INNER JOIN exact_target_license_activation etla WITH (NOLOCK)
							ON ls.license_id = etla.license_id
					WHERE CAST(etla.capability_activation_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
						AND license_status_id = 1
						AND NOT EXISTS (SELECT *
										FROM license_swap ls2
										WHERE ls.license_id = ls2.original_license_id
											and ls2.license_swap_status_id = 2) 
						AND ls.capability_expiration_date >= @date_value

					INSERT INTO exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					SELECT DISTINCT @exact_target_master_id,
						lml.license_id,
						@cart_discount_id,
						ls.license_distribution_method_id,
						lc.license_category_id,
						ls.product_line_id,
						ls.opt_in,
						ls.autorenewal_opt_id,
						CASE WHEN lmt.license_module_type_id = 19 THEN 1 
							WHEN lmt.license_module_type_id = 20 THEN 2
							ELSE lmt.license_module_type_id
						END capability_type_id,
						lml.module_seats license_seats
					FROM license_module_license lml WITH (NOLOCK)
						INNER JOIN license_summary ls WITH (NOLOCK)
							ON lml.license_id = ls.license_id
						INNER JOIN license_module_type lmt WITH (NOLOCK)
							ON lmt.license_module_type_id = lml.license_module_type_id
						INNER JOIN license_module_category lmc WITH (NOLOCK)
							ON lmc.license_module_id = lml.license_module_id
						INNER JOIN license_category lc WITH (NOLOCK)
							ON lc.license_category_id = lmc.license_category_id
					WHERE CAST(lml.start_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
						AND lml.license_status_id = 1
						AND NOT EXISTS (SELECT *
										FROM license_swap ls2
										WHERE ls.license_id = ls2.original_license_id
											AND ls2.license_swap_status_id = 2) 
				END 

		END 


END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_expiration]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_exact_target_message_expiration]
	(@date_value datetime,
		@message_measure_days int,
		@exact_target_master_id int,
		@cart_discount_id int)

AS
BEGIN

	/*

		DATE		AUTHOR			REMARKS
					mrobbins		Initial creation 
		2016-03-11	mrobbins		removed license swap licenses
		2016-12-19	mrobbins		changed license swap to only exclude licenses that moved days
		2018-09-11	mrobbins		added modules for SDNS/WSAT ALCHEMISTS - 1069
		2020-11-23	mrobbins		added  WITH (NOLOCK) AXIOM-2250

	*/
	SET NOCOUNT ON;

	select @date_value = convert(varchar(10),@date_value,101)

	insert into exact_target_subset1 (exact_target_master_id,
		license_id,
		cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats)
	select distinct @exact_target_master_id,
		license_id,
		@cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats
	from license_summary ls WITH (NOLOCK)
	where cast(capability_expiration_date As Date) = dateadd(dd, - @message_measure_days , @date_value)
		and license_status_id = 1
		and not exists (select *
						from license_swap ls2 WITH (NOLOCK)
						where ls.license_id = ls2.original_license_id
							and ls2.license_swap_status_id = 2) 

	--license modules
	INSERT INTO exact_target_subset1 (exact_target_master_id,
		license_id,
		cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats)
	SELECT DISTINCT @exact_target_master_id,
		lml.license_id,
		@cart_discount_id,
		ls.license_distribution_method_id,
		lc.license_category_id,
		ls.product_line_id,
		ls.opt_in,
		ls.autorenewal_opt_id,
		CASE WHEN lmt.license_module_type_id = 19 THEN 1 
			WHEN lmt.license_module_type_id = 20 THEN 2
			ELSE lmt.license_module_type_id
		END capability_type_id,
		lml.module_seats license_seats
	FROM license_module_license lml WITH (NOLOCK)
		INNER JOIN license_summary ls WITH (NOLOCK)
			ON lml.license_id = ls.license_id
		INNER JOIN license_module_type lmt WITH (NOLOCK)
			ON lmt.license_module_type_id = lml.license_module_type_id
		INNER JOIN license_module_category lmc WITH (NOLOCK)
			ON lmc.license_module_id = lml.license_module_id
		INNER JOIN license_category lc WITH (NOLOCK)
			ON lc.license_category_id = lmc.license_category_id
	WHERE CAST(lml.end_date As Date) = DATEADD(dd, - @message_measure_days , @date_value)
		AND lml.license_status_id = 1
		AND NOT EXISTS (SELECT *
						FROM license_swap ls2 WITH (NOLOCK)
						WHERE ls.license_id = ls2.original_license_id
							AND ls2.license_swap_status_id = 2) 

END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_activation]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_exact_target_message_insert_activation]
	(@date_value datetime,
		@message_measure_days int,
		@message_measure_end_days int,
		@exact_target_master_id int,
		@cart_discount_id int,
		@capability_type INT,
		@exact_target_class_id INT,
		@message_campaign_id INT)

AS
BEGIN

	/*

		DATE		AUTHOR			REMARKS
					mrobbins		Initial creation 
		2016-03-11	mrobbins		removed license swap licenses
		2016-10-11	mrobbins		US18613  - added capability type
										changed full to check for order date
		2016-12-19	mrobbins		changed license swap to only exclude licenses that moved days
		2017-11-29	mrobbins		added SMB code for no install campaigns
		2018-01-31	mrobbins		changed SMB code for no install campaigns GSM to check for child_license_id in console activity and non GSM no console activity record
		2018-02-01	mrobbins		changed no install to check exact_target_license_activation because of license_summary issue
		2019-07-02	cnovac			changed out reference to console_activity to console_activity_saep
		2019-10-08	mrobbins		changed no install to use new license_install table WATERBEARS-1044
		2019-12-20	mrobbins		added check for Wifi no install because a diff table has to be used WATERBEARS-151
		2020-04-08	mrobbins		added check for only new products for no install campaigns	WATERBEARS-1771
									added code for no activity campaign  WATERBEARS-97
		2020-11-23	mrobbins		added  WITH (NOLOCK) AXIOM-2250
		2023-10-10	schindar		ecom-2602 added  condition to check measure_end_days = 0
		2023-10-24	schindar		Bug fix to exclude noactivity campaings 
	*/

	SET NOCOUNT ON;

	select @date_value = convert(varchar(10),@date_value,101)

	DECLARE @message_campaign_name VARCHAR(150)

	declare @orders table (order_id INT IDENTITY(1,1),
		vendor_order_date datetime,
		license_id int)


	SELECT @message_campaign_name = message_campaign_name
	FROM dbo.message_campaign
	WHERE message_campaign_id = @message_campaign_id

	SELECT @message_measure_end_days = COALESCE(@message_measure_end_days,0)

	--SELECT @message_campaign_name

	if  @message_measure_end_days = 0 AND  @message_campaign_name NOT LIKE '%NoActivity%'
		begin
			if @capability_type = 1 --full
				BEGIN
					IF @message_campaign_name LIKE '%wifi%'
						BEGIN

							insert into @orders (vendor_order_date, license_id)
							select max(oh.vendor_order_date) vendor_order_date, 
								ls.license_id 
							from license_summary ls WITH (NOLOCK)
								inner join order_item_license oil WITH (NOLOCK)
									on oil.license_id = ls.license_id
								inner join order_item oi WITH (NOLOCK)
									on oil.order_item_id = oi.order_item_id
								inner join order_header oh WITH (NOLOCK)
									on oi.order_header_id = oh.order_header_id
								INNER JOIN dbo.product p WITH (NOLOCK)
									ON oi.product_id = p.product_id
							where license_status_id not in (2,3)
								--AND NOT EXISTS (SELECT *
								--				FROM exact_target_license_activation etla
								--				WHERE ls.license_id = etla.license_id)
								and not exists (select *
												from license_swap ls2 WITH (NOLOCK)
												where ls.license_id = ls2.original_license_id
													and ls2.license_swap_status_id = 2) 
								and cast(oh.vendor_order_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
								AND ls.license_category_id = 135
								AND p.product_type_id = 1
							group by ls.license_id

							INSERT into exact_target_subset1 (exact_target_master_id,
								license_id,
								cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
			
					capability_type_id,
								license_seats)
							select distinct @exact_target_master_id exact_target_master_id,
								ls.license_id,
								@cart_discount_id cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							from license_summary ls WITH (NOLOCK)
								inner join @orders o
									on ls.license_id = o.license_id
							where cast(o.vendor_order_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
								AND NOT EXISTS (SELECT *
												FROM dbo.account_order ao WITH (NOLOCK)
												WHERE ls.license_id = ao.license_id)
						END 
					ELSE 
						BEGIN
						
							insert into @orders (vendor_order_date, license_id)
							select max(oh.vendor_order_date) vendor_order_date, 
								ls.license_id 
							from license_summary ls WITH (NOLOCK)
								inner join order_item_license oil WITH (NOLOCK)
									on oil.license_id = ls.license_id
								inner join order_item oi WITH (NOLOCK)
									on oil.order_item_id = oi.order_item_id
								inner join order_header oh WITH (NOLOCK)
									on oi.order_header_id = oh.order_header_id
								INNER JOIN dbo.product p WITH (NOLOCK)
									ON oi.product_id = p.product_id
							where license_status_id not in (2,3)
								--AND NOT EXISTS (SELECT *
								--				FROM exact_target_license_activation etla
								--				WHERE ls.license_id = etla.license_id)
								and not exists (select *
												from license_swap ls2 WITH (NOLOCK)
												where ls.license_id = ls2.original_license_id
													and ls2.license_swap_status_id = 2) 
								and cast(oh.vendor_order_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
								AND ls.license_category_id <> 135
								AND p.product_type_id = 1
							group by ls.license_id
						 
							INSERT into exact_target_subset1 (exact_target_master_id,
								license_id,
								cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats)
							select distinct @exact_target_master_id exact_target_master_id,
								ls.license_id,
								@cart_discount_id cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							from license_summary ls WITH (NOLOCK)
								inner join @orders o 
									on ls.license_id = o.license_id
							where cast(o.vendor_order_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
								AND NOT EXISTS (SELECT *
												FROM dbo.license_install li WITH (NOLOCK)
												WHERE ls.license_id = li.license_id)
						END 

				end
			if @capability_type = 2 -- trial
				BEGIN
					IF @exact_target_class_id <> 5
						BEGIN
							IF @message_campaign_name LIKE '%wifi%'
								BEGIN
									INSERT INTO exact_target_subset1 (exact_target_master_id,
										license_id,
										cart_discount_id,
										license_distribution_method_id,
										license_category_id,
										product_line_id,
										opt_in,
										autorenewal_opt_id,
										capability_type_id,
										license_seats)
									select distinct @exact_target_master_id exact_target_master_id,
										license_id,
										@cart_discount_id cart_discount_id,
										license_distribution_method_id,
										license_category_id,
										product_line_id,
										opt_in,
										autorenewal_opt_id,
										capability_type_id,
										license_seats
									from license_summary ls WITH (NOLOCK)
									where cast(summary_date As Date) = cast(dateadd(dd, - @
message_measure_days , @date_value) as date)
										and license_status_id not in (2,3)
										--AND NOT EXISTS (SELECT *
										--				FROM exact_target_license_activation etla
										--				WHERE ls.license_id = etla.license_id)
										AND NOT EXISTS (SELECT *
														FROM dbo.account_order ao WITH (NOLOCK)
														WHERE ls.license_id = ao.license_id)
										and not exists (select *
													from license_swap ls2 WITH (NOLOCK)
													where ls.license_id = ls2.original_license_id) 
								END
                            ELSE
								BEGIN
									INSERT INTO exact_target_subset1 (exact_target_master_id,
										license_id,
										cart_discount_id,
										license_distribution_method_id,
										license_category_id,
										product_line_id,
										opt_in,
										autorenewal_opt_id,
										capability_type_id,
										license_seats)
									select distinct @exact_target_master_id exact_target_master_id,
										license_id,
										@cart_discount_id cart_discount_id,
										license_distribution_method_id,
										license_category_id,
										product_line_id,
										opt_in,
										autorenewal_opt_id,
										capability_type_id,
										license_seats
									from license_summary ls WITH (NOLOCK)
									where cast(summary_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
										and license_status_id not in (2,3)
										--AND NOT EXISTS (SELECT *
										--				FROM exact_target_license_activation etla
										--				WHERE ls.license_id = etla.license_id)
										AND NOT EXISTS (SELECT *
														FROM dbo.license_install li WITH (NOLOCK)
														WHERE ls.license_id = li.license_id)
										and not exists (select *
													from license_swap ls2 WITH (NOLOCK)
													where ls.license_id = ls2.original_license_id) 
								END 
							
						END
					ELSE --SMB Trial  
						BEGIN
							INSERT into exact_target_subset1 (exact_target_master_id,
								license_id,
								cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats)
							--GSM
							select distinct @exact_target_master_id exact_target_master_id,
								license_id,
								@cart_discount_id cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							from license_summary ls WITH (NOLOCK)
								INNER JOIN license_parent lp WITH (NOLOCK)
									ON ls.license_id = lp.license_parent_id 
							where cast(summary_date As Date) = CAST(DATEADD(dd, - @message_measure_days , @date_value) AS DATE)
								and license_status_id not in (2,3)
								and not exists (select *
												from license_swap ls2 WITH (NOLOCK)
												where ls.license_id = ls2.original_license_id) 
								and NOT EXISTS (SELECT *
											FROM console_activity_saep ca WITH (NOLOCK)
											WHERE lp.child_license_id = ca.license_id) 
							UNION
							--Non GSM
							select distinct @exact_target_master_id exact_target_master_id,
								license_id,
								@cart_discount_id cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							from license_summary ls WITH (NOLOCK)
							where cast(summary_date As Date) = CAST(DATEADD(dd, - @message_measure_days , @date_value) AS DATE)
								and license_status_id not in (2,3)
								and not exists (select *
												from license_swap ls2 WITH (NOLOCK)
												where ls.license_id = ls2.original_license_id) 
								AND NOT EXISTS (SELECT *
								
			FROM console_activity_saep ca WITH (NOLOCK)
											WHERE ls.license_id = ca.license_id)
							UNION 
							select distinct @exact_target_master_id exact_target_master_id,
								license_id,
								@cart_discount_id cart_discount_id,
								license_distribution_method_id,
								license_category_id,
								product_line_id,
								opt_in,
								autorenewal_opt_id,
								capability_type_id,
								license_seats
							from license_summary ls WITH (NOLOCK)
							where cast(summary_date As Date) = cast(dateadd(dd, - @message_measure_days , @date_value) as date)
								and license_status_id not in (2,3)
								and capability_activation_date is null
							and not exists (select *
										from license_swap ls2 WITH (NOLOCK)
										where ls.license_id = ls2.original_license_id) 
							AND ls.license_category_id in (select license_category_id from  message_campaign_license_category where message_campaign_id = @message_campaign_id AND license_category_id = 55)
						END  
					
				end
			

		end
	else
		BEGIN

			IF @message_campaign_name LIKE '%NoActivity%'
				BEGIN
					INSERT INTO exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					SELECT DISTINCT @exact_target_master_id,
						ls.license_id,
						@cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats
					FROM license_summary ls WITH (NOLOCK)
						INNER JOIN exact_target_license_activation etla WITH (NOLOCK)
							ON ls.license_id = etla.license_id
					WHERE ls.license_status_id not in (2,3)
						AND CAST(etla.capability_activation_date As Date) = CAST(DATEADD(dd, - @message_measure_days , @date_value) AS DATE)
						AND NOT EXISTS (SELECT *
								FROM license_swap ls2 WITH (NOLOCK)
								WHERE ls.license_id = ls2.original_license_id
									and ls2.license_swap_status_id = 2) 
						AND NOT EXISTS (SELECT DISTINCT license_id
									FROM dbo.sky_license_activity sla WITH (NOLOCK)
									WHERE sla.license_id = ls.license_id
										AND effective_date >= @date_value - 180)
				END 
			ELSE 
				BEGIN 
					INSERT into exact_target_subset1 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					select distinct @exact_target_master_id,
						license_id,
						@cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats
					from license_summary ls WITH (NOLOCK)
					where cast(summary_date As Date) = dateadd(dd, - @message_measure_days , @date_value)
						and license_status_id not in (2,3)
						and cast(capability_activation_date As Date) = cast(dateadd(dd, - @message_measure_end_days , @date_value) as date)
						and not exists (select *
								from license_swap ls2 WITH (NOLOCK)
								where ls.license_id = ls2.original_license_id
									and ls2.license_swap_status_id = 2) 
				END 
		end

END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_child_license_expiration]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_exact_target_message_insert_child_license_expiration]
	(@date_value DATETIME,
		@message_measure_days INT,
		@exact_target_master_id INT,
		@cart_discount_id INT)

AS
BEGIN

	/*

		DATE		AUTHOR			REMARKS
		2026-01-05			mrobbins		Initial creation 
		2026-01-26			jberry			Removed section for content_behavior

		DESCRIPTION
		Captures parent license details in exact_target_subset1 based on its children and the modules of its children
		for message measure point Child License Expiration.

	*/
	SET NOCOUNT ON;

	DECLARE @message_campaign_id INT

	SELECT @date_value = CONVERT(VARCHAR(10),@date_value,101)
	
	SELECT @message_campaign_id = message_campaign_id
	FROM dbo.exact_target_master 
	WHERE exact_target_master_id = @exact_target_master_id

	IF EXISTS ( SELECT 1 FROM dbo.message_campaign_child_license mccl WHERE mccl.message_campaign_id = @message_campaign_id )
		BEGIN

			----child licenses
			INSERT INTO dbo.exact_target_subset1 (exact_target_master_id,
				license_id,
				cart_discount_id,
				license_distribution_method_id,
				license_category_id,
				product_line_id,
				opt_in,
				autorenewal_opt_id,
				capability_type_id,
				license_seats)
			SELECT DISTINCT @exact_target_master_id,
				lp.parent_license_id license_id,
				@cart_discount_id,
				ls_parent.license_distribution_method_id,
				ls_child.license_category_id,
				ls_parent.product_line_id,
				ls_parent.opt_in,
				ls_parent.autorenewal_opt_id,
				ls_child.capability_type_id,
				ls_parent.license_seats
			FROM dbo.license_parent lp WITH (NOLOCK) 
				INNER JOIN dbo.license_summary ls_child WITH (NOLOCK)
					ON lp.child_license_id = ls_child.license_id
				INNER JOIN dbo.license_summary ls_parent WITH (NOLOCK)
					ON lp.parent_license_id = ls_parent.license_id
			WHERE CAST(ls_child.capability_expiration_date AS DATE) = DATEADD(dd, - @message_measure_days , @date_value)
				AND ls_child.license_status_id = 1
				AND NOT EXISTS (SELECT *
								FROM license_swap ls2 WITH (NOLOCK)
								WHERE ls_child.license_id = ls2.original_license_id
									AND ls2.license_swap_status_id = 2) 

			--child license modules
			INSERT INTO exact_target_subset1 (exact_target_master_id,
				license_id,
				cart_discount_id,
				license_distribution_method_id,
				license_category_id,
				product_line_id,
				opt_in,
				autorenewal_opt_id,
				capability_type_id,
				license_seats)
			SELECT DISTINCT @exact_target_master_id,
				lp.parent_license_id license_id,
				@cart_discount_id,
				ls_parent.license_distribution_method_id,
				lc.license_category_id,
				ls_parent.product_line_id,
				ls_parent.opt_in,
				ls_parent.autorenewal_opt_id,
				CASE WHEN lmt.license_module_type_id = 19 THEN 1 
					WHEN lmt.license_module_type_id = 20 THEN 2
					ELSE lmt.license_module_type_id
				END capability_type_id,
				ls_parent.license_seats
			FROM dbo.license_parent lp WITH (NOLOCK)
				INNER JOIN dbo.license_module_license lml WITH (NOLOCK)
					ON lp.child_license_id = lml.license_id
				INNER JOIN dbo.license_summary ls WITH (NOLOCK)
					ON lml.license_id = ls.license_id
				INNER JOIN dbo.license_module_type lmt WITH (NOLOCK)
					ON lmt.license_module_type_id = lml.license_module_type_id
				INNER JOIN dbo.license_module_category lmc WITH (NOLOCK)
					ON lmc.license_module_id = lml.license_module_id
				INNER JOIN dbo.license_category lc WITH (NOLOCK)
					ON lc.license_category_id = lmc.license_category_id
				INNER JOIN dbo.license_summary ls_parent WITH (NOLOCK)
					ON lp.parent_license_id = ls_parent.license_id
			WHERE CAST(lml.end_date As Date) = DATEADD(dd, - @message_measure_days , @date_va
lue)
				AND lml.license_status_id = 1
				AND NOT EXISTS (SELECT *
								FROM license_swap ls2 WITH (NOLOCK)
								WHERE ls.license_id = ls2.original_license_id
									AND ls2.license_swap_status_id = 2) 

		END		

END



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_distribution]
-- =============================================================================
	CREATE PROCEDURE [dbo].[usp_exact_target_message_insert_distribution]
		(@exact_target_master_id int,
			@exact_target_class_id int,
			@inclusive int)
		/*	
		DATE		AUTHOR		REMARKS
		2015-08-18	mrobbins	Initial Creation
		2015-08-22	mrobbins	changed exact_target_class to exact_target_class_id
		2019-02-06	mrobbins	removed partner class disti exclusion WATERBEARS 438
		2021-03-04	mrobbins	removed S2 class disti exclusion AXIOM 2414

		DESCRIPTION
		*/

	AS
	BEGIN
		-- SET NOCOUNT ON added to prevent extra result sets from
		-- interfering with SELECT statements.
		SET NOCOUNT ON;

		declare @message_campaign_id int

		select @message_campaign_id = message_campaign_id
		from exact_target_master
		where exact_target_master_id = @exact_target_master_id

		--print 'message_campaign - ' + str(@message_campaign_id)

		if @exact_target_class_id = 4 --SMB Special
			begin
				--print @exact_target_class
				if @inclusive = 0
					begin
						insert into exact_target_subset2 (exact_target_master_id,
							license_id,
							cart_discount_id,
							license_distribution_method_id,
							license_category_id,
							product_line_id,
							opt_in,
							autorenewal_opt_id,
							capability_type_id,
							license_seats)
						select distinct s.exact_target_master_id,
							s.license_id,
							s.cart_discount_id,
							s.license_distribution_method_id,
							s.license_category_id,
							s.product_line_id,
							s.opt_in,
							s.autorenewal_opt_id,
							s.capability_type_id,
							s.license_seats
						from exact_target_subset1 s
							inner join license_distribution_method ldm with (nolock)
								on s.license_distribution_method_id = ldm.license_distribution_method_id
							inner join license_distribution_method_channel ldmc with (nolock)
								on ldm.license_distribution_method_id = ldmc.license_distribution_method_id
							inner join distribution_class dc with (nolock)
								on ldmc.distribution_class_id = dc.distribution_class_id
						where s.exact_target_master_id = @exact_target_master_id
							and s.license_distribution_method_id NOT IN (select license_distribution_method_id from  message_campaign_license_distribution_method where message_campaign_id = @message_campaign_id)
							and dc.distribution_class not in ('banking')
					end

				if @inclusive = 1
					begin
						insert into exact_target_subset2 (exact_target_master_id,
							license_id,
							cart_discount_id,
							license_distribution_method_id,
							license_category_id,
							product_line_id,
							opt_in,
							autorenewal_opt_id,
							capability_type_id,
							license_seats)
						select distinct s.exact_target_master_id,
							s.license_id,
							s.cart_discount_id,
							s.license_distribution_method_id,
							s.license_category_id,
							s.product_line_id,
							s.opt_in,
							s.autorenewal_opt_id,
							s.capability_type_id,
							s.license_seats
						from exact_target_subset1 s
							inner join license_distribution_method ldm with (nolock)
								on s.license_distribution_method_id = ldm.license_distribution_method_id
							inner join license_distribution_method_channel ldmc with (nolock)
								on ldm.license_distribution_method_id = ldmc.license_distribution_method_id
							inner join distribution_class dc with (nolock)
								on ldmc.distribution_class_id = dc.distribution_class_id
						where s.exact_target_master_id = @exact_target_master_id
							and s.license_distribution_method_id IN (select license_distribution_method_id from  message_campaign_license_distribution_method where message_campaign_id = @message_campaign_id)
							and dc.distribution_class not in ('banking')
					
end
			end
		else
			begin
				if @inclusive = 0
					begin
						insert into exact_target_subset2 (exact_target_master_id,
							license_id,
							cart_discount_id,
							license_distribution_method_id,
							license_category_id,
							product_line_id,
							opt_in,
							autorenewal_opt_id,
							capability_type_id,
							license_seats)
						select distinct s.exact_target_master_id,
							s.license_id,
							s.cart_discount_id,
							s.license_distribution_method_id,
							s.license_category_id,
							s.product_line_id,
							s.opt_in,
							s.autorenewal_opt_id,
							s.capability_type_id,
							s.license_seats
						from exact_target_subset1 s
							inner join license_distribution_method ldm with (nolock)
								on s.license_distribution_method_id = ldm.license_distribution_method_id
							inner join license_distribution_method_channel ldmc with (nolock)
								on ldm.license_distribution_method_id = ldmc.license_distribution_method_id
							inner join distribution_class dc with (nolock)
								on ldmc.distribution_class_id = dc.distribution_class_id
						where s.exact_target_master_id = @exact_target_master_id
							and s.license_distribution_method_id NOT IN (select license_distribution_method_id from  message_campaign_license_distribution_method where message_campaign_id = @message_campaign_id)
							and dc.distribution_class not in ('banking')
					end

				if @inclusive = 1
					begin
						insert into exact_target_subset2 (exact_target_master_id,
							license_id,
							cart_discount_id,
							license_distribution_method_id,
							license_category_id,
							product_line_id,
							opt_in,
							autorenewal_opt_id,
							capability_type_id,
							license_seats)
						select distinct s.exact_target_master_id,
							s.license_id,
							s.cart_discount_id,
							s.license_distribution_method_id,
							s.license_category_id,
							s.product_line_id,
							s.opt_in,
							s.autorenewal_opt_id,
							s.capability_type_id,
							s.license_seats
						from exact_target_subset1 s
							inner join license_distribution_method ldm with (nolock)
								on s.license_distribution_method_id = ldm.license_distribution_method_id
							inner join license_distribution_method_channel ldmc with (nolock)
								on ldm.license_distribution_method_id = ldmc.license_distribution_method_id
							inner join distribution_class dc with (nolock)
								on ldmc.distribution_class_id = dc.distribution_class_id
						where s.exact_target_master_id = @exact_target_master_id
							and s.license_distribution_method_id IN (select license_distribution_method_id from  message_campaign_license_distribution_method where message_campaign_id = @message_campaign_id)
							and dc.distribution_class not in ('banking')
					end
			end
	


	END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_final]
-- =============================================================================
	CREATE PROCEDURE [dbo].[usp_exact_target_message_insert_final]
		(@exact_target_master_id INT,
			@capability_type INT,
			@exact_target_class_id INT,
			@date_value DATETIME)


	AS
	BEGIN

		SET NOCOUNT ON;
        
		/*

		DATE		AUTHOR			REMARKS
		2015-08-18	mrobbins		initial creation
		2015-08-22	mrobbins		changed exact_target_class to exact_target_class_id
		2015-10-22	mrobbins		changed locale to be "and" so country and language have to match
		2015-11-18	mrobbins		changed license_channel_license join to left and included nulls
		2016-09-26	mrobbins		changed exact_target_class_id on SMB selects to include SMB Security Summary
		2018-09-11	mrobbins		added license_category_id for SDNS/WSAT ALCHEMISTS - 1069
		2018-11-14	mrobbins		added message_campaign_license_channel ALCHEMISTS-1936
										added parent check
		2019-09-05	mrobbins		removed Apple/Google store Wifi records - WATERBEARS 1048
		2026-01-26	jberry			US-5164326 - added logic for child license expiration
						                       - added insert into exact_target_batch_children for child licenses and modules
		2026-04-30	jberry			US-5359090 - Added conversion for child capability type to convert 0 to 1 for full and 1 to 2 for trials

		*/

		DECLARE @account_id INT,
			@max_account_id INT,
			@account_creation_status INT,
			@message_campaign_id INT,
			@message_measure_point_id INT
            
		DECLARE @latest_order TABLE (latest_order_id INT IDENTITY(1,1),
			order_header_id INT,
			license_id INT)

		INSERT INTO @latest_order
		(
			order_header_id,
			license_id
		)
		SELECT MAX(oh.order_header_id) order_header_id,
			e.license_id
		FROM dbo.exact_target_subset3 e
			INNER JOIN dbo.order_item_license oil
				ON e.license_id = oil.license_id
			INNER JOIN dbo.order_item oi
				ON oi.order_item_id = oil.order_item_id
			INNER JOIN dbo.order_header oh
				ON oh.order_header_id = oi.order_header_id
			INNER JOIN dbo.license_category lc
				ON lc.license_category_id = e.license_category_id
			INNER JOIN dbo.exact_target_master etm
				ON etm.exact_target_master_id = e.exact_target_master_id
			INNER JOIN dbo.exact_target_message_campaign etmc
				ON etmc.exact_target_message_campaign_id = etm.exact_target_message_campaign_id
			INNER JOIN dbo.exact_target_class etc
				ON etc.exact_target_class_id = etmc.exact_target_class_id
		WHERE e.license_category_id = 135
			AND etc.exact_target_class IN ('Renewal','SMB Renewal')
		GROUP BY e.license_id
		
		DELETE e
		FROM dbo.exact_target_subset3 e
			INNER JOIN @latest_order o
				ON o.license_id = e.license_id
			INNER JOIN dbo.order_header oh
				ON oh.order_header_id = o.order_header_id
		WHERE oh.site_id IN ('APPLESTORE','GOOGLEANDROID')

		SELECT @message_campaign_id = message_campaign_id
		FROM dbo.exact_target_master
		WHERE exact_target_master_id = @exact_target_master_id

		SELECT @message_measure_point_id = mcmp.message_measure_point_id
		FROM dbo.message_campaign_measure_point mcmp
		WHERE mcmp.message_campaign_id = @message_campaign_id

		DECLARE @account TABLE (account_id INT IDENTITY(1,1),
			account_creation_status INT);

		declare @license_channel table (license_channel_id int);

		INSERT INTO @license_channel
		SELECT DISTINCT license_channel_id
		FROM dbo.message_campaign_license_channel
		WHERE message_campaign_id = @message_campaign_id


		INSERT INTO @account (account_creation_status)
		SELECT DISTINCT account_creation_status
		FROM dbo.message_campaign_account_creation_status mcacs
		WHERE message_campaign_id = @message_campaign_id

		SELECT @account_id = MIN(account_id), @max_account_id = MAX(account_id)
		FROM @account

		WHILE @account_id <= @max_account_id
			BEGIN

		
		SELECT @account_creation_status = account_creation_status
				FROM @account
				WHERE account_id = @account_id


				IF @account_creation_status = 0
					BEGIN

						--print 'account creation 0'

						IF @exact_target_class_id IN (3,5,6,12) --'SMB Renewal','SMB Trial','SMB Welcome'
							BEGIN
								--if 0 is a license_channel also check for null
								IF (SELECT COUNT(*) FROM @license_channel WHERE license_channel_id = 0) >= 1
									BEGIN
										INSERT INTO exact_target_batch (license_id,
												customer_id,
												cart_discount_id,
												exact_target_master_id,
												exact_target_batch_status_id,
												mail_date,
												license_category_id)
										SELECT DISTINCT l.license_id,
											l.customer_id,
											s.cart_discount_id,
											s.exact_target_master_id,
											0 AS message_campaign_email_batch_status_id,
											CAST(@date_value AS DATE),
											s.license_category_id 
										FROM dbo.exact_target_subset3 s
											INNER JOIN dbo.license l
												ON s.license_id = l.license_id
											INNER JOIN dbo.customer c
												ON l.customer_id = c.customer_id
											LEFT JOIN dbo.license_channel_license lcl
												ON l.license_id = lcl.license_id
											LEFT JOIN dbo.customer_locale cl
												ON c.customer_id = cl.customer_id
										WHERE s.exact_target_master_id = @exact_target_master_id
											AND (s.license_category_id IN (SELECT license_category_id FROM  message_campaign_license_category WHERE message_campaign_id = @message_campaign_id)
											    OR s.license_category_id IN (SELECT dimension_value FROM message_campaign_child_license WHERE message_campaign_id = @message_campaign_id AND dimension_type = 'child-license-category'))
											AND s.product_line_id IN (SELECT product_line_id FROM  message_campaign_product_line WHERE message_campaign_id = @message_campaign_id)
											AND s.opt_in IN (SELECT message_email_opt_id FROM  message_campaign_email_election WHERE message_campaign_id = @message_campaign_id)
											AND s.autorenewal_opt_id IN (SELECT autorenewal_opt_id FROM  message_campaign_autorenewal WHERE message_campaign_id = @message_campaign_id)
											AND (s.capability_type_id = @capability_type
											    OR EXISTS (SELECT 1
											               FROM message_campaign_child_license mccl
											               WHERE mccl.message_campaign_id = @message_campaign_id
											                   AND mccl.dimension_type = 'child-capability-type'
											                   AND ((mccl.dimension_value = 1 AND s.capability_type_id = 2) OR (mccl.dimension_value = 0 AND s.capability_type_id = 1))))		
											AND (lcl.license_channel_id IN (SELECT license_channel_id FROM @license_channel)
													OR lcl.license_channel_id IS NULL)
											AND NOT EXISTS (SELECT *
															FROM account_license al
															WHERE s.license_id = al.license_id) 
											AND ((cl.language_code IN (SELECT language_code FROM  message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.language_code IS NULL)
												AND (cl.location_code IN (SELECT location_code FROM  message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.location_code IS NULL))
											AND NOT EXISTS (SELECT DISTINCT license_id 
																FROM dbo.partner_license pl
																WHERE l.license_id = pl.license_id
																	   AND pl.partner_license_status_id = 2 --Approved
																	   AND pl.partner_id <> 5559 --NOT "Webroot direct Partner"
																	   AND pl.start_date <= @date_value
																	   AND (pl.end_date IS NULL
																		   OR pl.end_date > @date_value))
											AND NOT EXISTS (SELECT DISTINCT s.license_id FROM license_parent lp WHERE s.license_id = lp.child_license_id)
									END 
							
	ELSE 
									BEGIN
										INSERT INTO dbo.exact_target_batch (license_id,
												customer_id,
												cart_discount_id,
												exact_target_master_id,
												exact_target_batch_status_id,
												mail_date,
												license_category_id)
										SELECT DISTINCT l.license_id,
											l.customer_id,
											s.cart_discount_id,
											s.exact_target_master_id,
											0 AS message_campaign_email_batch_status_id,
											CAST(@date_value AS DATE),
											s.license_category_id 
										FROM dbo.exact_target_subset3 s
											INNER JOIN dbo.license l
												ON s.license_id = l.license_id
											INNER JOIN dbo.customer c
												ON l.customer_id = c.customer_id
											--inner join customer_locale cl
											--	on c.customer_id = cl.customer_id
											INNER JOIN dbo.license_channel_license lcl
												ON l.license_id = lcl.license_id
											LEFT JOIN dbo.customer_locale cl
												ON c.customer_id = cl.customer_id
										WHERE s.exact_target_master_id = @exact_target_master_id
											AND s.license_category_id IN (SELECT license_category_id FROM dbo.message_campaign_license_category WHERE message_campaign_id = @message_campaign_id)
											AND s.product_line_id IN (SELECT product_line_id FROM dbo.message_campaign_product_line WHERE message_campaign_id = @message_campaign_id)
											AND s.opt_in IN (SELECT message_email_opt_id FROM dbo.message_campaign_email_election WHERE message_campaign_id = @message_campaign_id)
											AND s.autorenewal_opt_id IN (SELECT autorenewal_opt_id FROM dbo.message_campaign_autorenewal WHERE message_campaign_id = @message_campaign_id)
											AND s.capability_type_id = @capability_type
											AND lcl.license_channel_id IN (SELECT license_channel_id FROM @license_channel)
											AND NOT EXISTS (SELECT *
															FROM dbo.account_license al
															WHERE s.license_id = al.license_id) 
											AND ((cl.language_code IN (SELECT language_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.language_code IS NULL)
												AND (cl.location_code IN (SELECT location_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.location_code IS NULL))
											AND NOT EXISTS (SELECT DISTINCT license_id 
																FROM dbo.partner_license pl
																WHERE l.license_id = pl.license_id
																	   AND pl.partner_license_status_id = 2 --Approved
																	   AND pl.partner_id <> 5559 --NOT "Webroot direct Partner"
																	   AND pl.start_date <= @date_value
																	   AND (pl.end_date IS NULL
																		   OR pl.end_date > @date_value))
											AND NOT EXISTS (SELECT DISTINCT s.license_id FROM dbo.license_parent lp WHERE s.license_id = lp.child_license_id)
									END 
								
							
							END 
						IF @exact_target_class_id = 4 --SMB Special
							BEGIN
								INSERT INTO dbo.exact_target_batch (license_id,
										customer_id,
										cart_discount_id,
										exact_target_master_id,
										exact_target_batch_status_id,
										mail_date,
										license_category_id)
								SELECT DISTINCT l.license_id,
									l.customer_id,
									s.cart_discount_id,
									s.exact_target_master_id,
									0 AS message_campaign_email_batch_status_id,
									CAST(@date_value AS DATE),
									s.license_category_id 
								FROM dbo.exact_target_subset3 s
									INNER JOIN dbo.license l
										ON s.license_id = l.license_id
									INNER JOIN dbo.customer c
										ON l.customer_id = c.customer_id
									INNER JOIN dbo.customer_locale cl
										ON c.customer_id = cl.customer_id
									INNER JOIN dbo.license_channel_license lcl
										ON l.license_id = lcl.license_id
								WHERE s.exact_target_
master_id = @exact_target_master_id
									AND s.license_category_id IN (SELECT license_category_id FROM dbo.message_campaign_license_category WHERE message_campaign_id = @message_campaign_id)
									AND s.product_line_id IN (SELECT product_line_id FROM dbo.message_campaign_product_line WHERE message_campaign_id = @message_campaign_id)
									AND s.opt_in IN (SELECT message_email_opt_id FROM dbo.message_campaign_email_election WHERE message_campaign_id = @message_campaign_id)
									AND s.autorenewal_opt_id IN (SELECT autorenewal_opt_id FROM dbo.message_campaign_autorenewal WHERE message_campaign_id = @message_campaign_id)
									AND s.capability_type_id = @capability_type
									AND (cl.language_code IN (SELECT language_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
										AND cl.location_code IN (SELECT location_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id))
									AND NOT EXISTS (SELECT *
													FROM dbo.account_license al
													WHERE s.license_id = al.license_id) 
							
							END

						IF @exact_target_class_id NOT IN (3,4,5,6,12) --'SMB Special','SMB Renewal','SMB Trial','SMB Welcome'
							BEGIN
								INSERT INTO dbo.exact_target_batch (license_id,
										customer_id,
										cart_discount_id,
										exact_target_master_id,
										exact_target_batch_status_id,
										mail_date,
										license_category_id)
								SELECT DISTINCT l.license_id,
									l.customer_id,
									s.cart_discount_id,
									s.exact_target_master_id,
									0 AS message_campaign_email_batch_status_id,
									CAST(@date_value AS DATE),
									s.license_category_id 
								FROM dbo.exact_target_subset3 s
									INNER JOIN dbo.license l
										ON s.license_id = l.license_id
									INNER JOIN dbo.customer c
										ON l.customer_id = c.customer_id
									INNER JOIN dbo.customer_locale cl
										ON c.customer_id = cl.customer_id
								WHERE s.exact_target_master_id = @exact_target_master_id
									AND s.license_category_id IN (SELECT license_category_id FROM dbo.message_campaign_license_category WHERE message_campaign_id = @message_campaign_id)
									AND s.product_line_id IN (SELECT product_line_id FROM dbo.message_campaign_product_line WHERE message_campaign_id = @message_campaign_id)
									AND s.license_seats IN (SELECT license_seats FROM dbo.message_campaign_seat WHERE message_campaign_id = @message_campaign_id)
									AND s.opt_in IN (SELECT message_email_opt_id FROM dbo.message_campaign_email_election WHERE message_campaign_id = @message_campaign_id)
									AND s.autorenewal_opt_id IN (SELECT autorenewal_opt_id FROM dbo.message_campaign_autorenewal WHERE message_campaign_id = @message_campaign_id)
									AND s.capability_type_id = @capability_type
									AND (cl.language_code IN (SELECT language_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
										AND cl.location_code IN (SELECT location_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id))
									AND NOT EXISTS (SELECT *
													FROM dbo.account_license al
													WHERE s.license_id = al.license_id) 
							END
					END

				IF @account_creation_status = 1
					BEGIN

						--print 'account creation 1'

						if @exact_target_class_id in (3,5,6,12) --'SMB Renewal','SMB Trial','SMB Welcome'
							BEGIN
								--if 0 is a license_channel also check for null
								IF (SELECT COUNT(*) FROM @license_channel WHERE license_channel_id = 0) >= 1
									BEGIN
										INSERT INTO dbo.exact_target_batch (license_id,
												customer_id,
												cart_discount_id,
												exact_target_master_id,
												exact_target_batch_status_id,
												mail_date,
												license_category_id)
										SELECT DIS
TINCT l.license_id,
											l.customer_id,
											s.cart_discount_id,
											s.exact_target_master_id,
											0 AS message_campaign_email_batch_status_id,
											CAST(@date_value AS DATE),
											s.license_category_id 
										FROM dbo.exact_target_subset3 s
											INNER JOIN dbo.license l
												ON s.license_id = l.license_id
											INNER JOIN dbo.customer c
												ON l.customer_id = c.customer_id
											LEFT JOIN dbo.license_channel_license lcl
												ON l.license_id = lcl.license_id
											LEFT JOIN dbo.customer_locale cl
												ON c.customer_id = cl.customer_id
										WHERE s.exact_target_master_id = @exact_target_master_id
											AND (s.license_category_id IN (SELECT license_category_id FROM dbo.message_campaign_license_category WHERE message_campaign_id = @message_campaign_id)
													OR s.license_category_id IN (SELECT dimension_value FROM dbo.message_campaign_child_license WHERE message_campaign_id = @message_campaign_id AND dimension_type = 'child-license-category'))
											AND s.product_line_id IN (SELECT product_line_id FROM dbo.message_campaign_product_line WHERE message_campaign_id = @message_campaign_id)
											AND s.opt_in IN (SELECT message_email_opt_id FROM dbo.message_campaign_email_election WHERE message_campaign_id = @message_campaign_id)
											AND s.autorenewal_opt_id IN (SELECT autorenewal_opt_id FROM dbo.message_campaign_autorenewal WHERE message_campaign_id = @message_campaign_id)
											AND (s.capability_type_id = @capability_type
											    OR EXISTS (SELECT 1
											               FROM dbo.message_campaign_child_license mccl
											               WHERE mccl.message_campaign_id = @message_campaign_id
											                   AND mccl.dimension_type = 'child-capability-type'
											                   AND ((mccl.dimension_value = 1 AND s.capability_type_id = 2) OR (mccl.dimension_value = 0 AND s.capability_type_id = 1))))		
											AND (lcl.license_channel_id IN (SELECT license_channel_id FROM @license_channel)
													OR lcl.license_channel_id IS NULL)
											AND EXISTS (SELECT *
															FROM dbo.account_license al
															WHERE s.license_id = al.license_id) 
											AND ((cl.language_code IN (SELECT language_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.language_code IS NULL)
												AND (cl.location_code IN (SELECT location_code FROM dbo.message_campaign_language_location WHERE message_campaign_id = @message_campaign_id)
													OR cl.location_code IS NULL))
											AND NOT EXISTS (SELECT DISTINCT license_id 
																FROM dbo.partner_license pl
																WHERE l.license_id = pl.license_id
																	   AND pl.partner_license_status_id = 2 --Approved
																	   AND pl.partner_id <> 5559 --NOT "Webroot direct Partner"
																	   AND pl.start_date <= @date_value
																	   AND (pl.end_date IS NULL
																		   OR pl.end_date > @date_value))
											AND NOT EXISTS (SELECT DISTINCT s.license_id FROM dbo.license_parent lp WHERE s.license_id = lp.child_license_id)
									END 
								ELSE 
									BEGIN
										INSERT INTO dbo.exact_target_batch (license_id,
												customer_id,
												cart_discount_id,
												exact_target_master_id,
												exact_target_batch_status_id,
												mail_date,
												license_category_id)
										SELECT DISTINCT l.license_id,
											l.customer_id,
											s.cart_discount_id,
											s.exact_target_master_id,
											0 as message_campaign_email_batch_status_id,
											cast(@date_value As Date),
											s.license_category_id 
										from dbo.exact_target_subset3 s
											inner join dbo.license l
												on s.license_id = l.license_id
											inner join dbo.customer c
				
								on l.customer_id = c.customer_id
											INNER join dbo.license_channel_license lcl
												on l.license_id = lcl.license_id
											left join dbo.customer_locale cl
												ON c.customer_id = cl.customer_id
										where s.exact_target_master_id = @exact_target_master_id
											and s.license_category_id in (select license_category_id from dbo.message_campaign_license_category where message_campaign_id = @message_campaign_id)
											and s.product_line_id in (select product_line_id from dbo.message_campaign_product_line where message_campaign_id = @message_campaign_id)
											and s.opt_in in (select message_email_opt_id from dbo.message_campaign_email_election where message_campaign_id = @message_campaign_id)
											and s.autorenewal_opt_id in (select autorenewal_opt_id from dbo.message_campaign_autorenewal where message_campaign_id = @message_campaign_id)
											and s.capability_type_id = @capability_type
											and lcl.license_channel_id IN (SELECT license_channel_id FROM @license_channel)
											and exists (select *
															from dbo.account_license al
															where s.license_id = al.license_id) 
											and ((cl.language_code in (select language_code from dbo.message_campaign_language_location where message_campaign_id = @message_campaign_id)
													OR cl.language_code IS NULL)
												AND (cl.location_code in (select location_code from dbo.message_campaign_language_location where message_campaign_id = @message_campaign_id)
													OR cl.location_code IS NULL))
											AND NOT EXISTS (SELECT DISTINCT license_id 
																FROM dbo.partner_license pl
																WHERE l.license_id = pl.license_id
																	   AND pl.partner_license_status_id = 2 --Approved
																	   AND pl.partner_id <> 5559 --NOT "Webroot direct Partner"
																	   AND pl.start_date <= @date_value
																	   AND (pl.end_date IS NULL
																		   OR pl.end_date > @date_value))
											AND NOT EXISTS (SELECT DISTINCT s.license_id FROM dbo.license_parent lp WHERE s.license_id = lp.child_license_id)
									END 
								
							
							END 

						if @exact_target_class_id = 4 --SMB Special
							begin
								insert into dbo.exact_target_batch (license_id,
										customer_id,
										cart_discount_id,
										exact_target_master_id,
										exact_target_batch_status_id,
										mail_date,
										license_category_id)
								select distinct l.license_id,
									l.customer_id,
									s.cart_discount_id,
									s.exact_target_master_id,
									0 as message_campaign_email_batch_status_id,
									cast(@date_value As Date),
									s.license_category_id 
								from dbo.exact_target_subset3 s
									inner join dbo.license l
										on s.license_id = l.license_id
									inner join dbo.customer c
										on l.customer_id = c.customer_id
									inner join dbo.customer_locale cl
										on c.customer_id = cl.customer_id
									inner join dbo.license_channel_license lcl
										on l.license_id = lcl.license_id
								where s.exact_target_master_id = @exact_target_master_id
									and s.license_category_id in (select license_category_id from dbo.message_campaign_license_category where message_campaign_id = @message_campaign_id)
									and s.product_line_id in (select product_line_id from dbo.message_campaign_product_line where message_campaign_id = @message_campaign_id)
									and s.opt_in in (select message_email_opt_id from dbo.message_campaign_email_election where message_campaign_id = @message_campaign_id)
									and s.autorenewal_opt_id in (select autorenewal_opt_id from dbo.message_campaign_autorenewal where message_campaign_id = @message_campaign_id)
									and s.capability_type_id = @capability_type
									and (cl.language_code in (select language_code from dbo.message_campaign_language_location where mess
age_campaign_id = @message_campaign_id)
										and cl.location_code in (select location_code from dbo.message_campaign_language_location where message_campaign_id = @message_campaign_id))
									and exists (select *
													from dbo.account_license al
													where s.license_id = al.license_id) 
							end

						if @exact_target_class_id not in (3,4,5,6,12) --'SMB Special','SMB Renewal','SMB Trial','SMB Welcome'
							begin
								insert into dbo.exact_target_batch (license_id,
										customer_id,
										cart_discount_id,
										exact_target_master_id,
										exact_target_batch_status_id,
										mail_date,
										license_category_id)
								select distinct l.license_id,
									l.customer_id,
									s.cart_discount_id,
									s.exact_target_master_id,
									0 as message_campaign_email_batch_status_id,
									cast(@date_value As Date),
									s.license_category_id 
								from dbo.exact_target_subset3 s
									inner join dbo.license l
										on s.license_id = l.license_id
									inner join dbo.customer c
										on l.customer_id = c.customer_id
									inner join dbo.customer_locale cl
										on c.customer_id = cl.customer_id
								where s.exact_target_master_id = @exact_target_master_id
									and s.license_category_id in (select license_category_id from dbo.message_campaign_license_category where message_campaign_id = @message_campaign_id)
									and s.product_line_id in (select product_line_id from dbo.message_campaign_product_line where message_campaign_id = @message_campaign_id)
									and s.license_seats in (select license_seats from dbo.message_campaign_seat where message_campaign_id = @message_campaign_id)
									and s.opt_in in (select message_email_opt_id from dbo.message_campaign_email_election where message_campaign_id = @message_campaign_id)
									and s.autorenewal_opt_id in (select autorenewal_opt_id from dbo.message_campaign_autorenewal where message_campaign_id = @message_campaign_id)
									and s.capability_type_id = @capability_type
									and (cl.language_code in (select language_code from dbo.message_campaign_language_location where message_campaign_id = @message_campaign_id)
										and cl.location_code in (select location_code from dbo.message_campaign_language_location where message_campaign_id = @message_campaign_id))
									and exists (select *
													from dbo.account_license al
													where s.license_id = al.license_id) 
							end
					end

					set @account_id = @account_id + 1	
			end   --ACCOUNT LOOP

			-- insert child records into exact_target_batch_children
			IF @message_measure_point_id = 8  --Child License Expiration
				BEGIN
					--child licenses
					INSERT INTO dbo.exact_target_batch_children
					(
						exact_target_batch_id,
						exact_target_master_id,
						parent_license_id,
						child_license_id,
						license_category_id,
						capability_type_id,
						capability_expiration_date,
						mail_date,
						insert_date
					)
					SELECT DISTINCT
						   etb.exact_target_batch_id,
						   etb.exact_target_master_id,
						   lp.parent_license_id,
						   lp.child_license_id,
						   lc.license_category_id,
						   lc.capability_type_id,
						   lc.capability_expiration_date,
							@date_value,
							GETDATE()
					FROM dbo.exact_target_batch etb
						INNER JOIN dbo.exact_target_subset3 ets
							ON ets.license_id = etb.license_id
							   AND ets.exact_target_master_id = etb.exact_target_master_id
						INNER JOIN dbo.exact_target_master etm
							ON etm.exact_target_master_id = etb.exact_target_master_id
						INNER JOIN dbo.message_campaign_measure_point mcmp
							ON mcmp.message_campaign_id = etm.message_campaign_id
						INNER JOIN dbo.license_parent lp
							ON lp.parent_license_id = etb.license_id
						INNER JOIN dbo.license_summary lc
							ON lp.child_license_id = lc.license_id
	
				WHERE 1 = 1
						  AND CAST(lc.capability_expiration_date AS DATE) = DATEADD(dd, -mcmp.message_measure_days, @date_value)
						  AND etb.exact_target_master_id = @exact_target_master_id
						  AND lc.license_category_id = etb.license_category_id
						  AND mcmp.message_measure_point_id = @message_measure_point_id
						  AND ets.capability_type_id = lc.capability_type_id;

					--child modules
					INSERT INTO dbo.exact_target_batch_children
					(
						exact_target_batch_id,
						exact_target_master_id,
						parent_license_id,
						child_license_id,
						license_category_id,
						capability_type_id,
						capability_expiration_date,
						mail_date,
						insert_date
					)
					SELECT DISTINCT
						   etb.exact_target_batch_id,
						   etb.exact_target_master_id,
						   etb.license_id AS parent_license_id,
						   lp.child_license_id,
						   lmc.license_category_id,
						   CASE
							   WHEN lmt.license_module_type_id = 19 THEN
								   1
							   WHEN lmt.license_module_type_id = 20 THEN
								   2
							   ELSE
								   lmt.license_module_type_id
						   END capability_type_id,
						   lml.end_date,
						   @date_value,
						   GETDATE()
					FROM dbo.exact_target_batch etb
						INNER JOIN dbo.exact_target_subset3 ets
							ON ets.license_id = etb.license_id
							   AND ets.exact_target_master_id = etb.exact_target_master_id
						INNER JOIN dbo.exact_target_master etm
							ON etm.exact_target_master_id = etb.exact_target_master_id
						INNER JOIN dbo.message_campaign_measure_point mcmp
							ON mcmp.message_campaign_id = etm.message_campaign_id
						INNER JOIN dbo.license_parent lp
							ON lp.parent_license_id = etb.license_id
						INNER JOIN dbo.license_module_license lml
							ON lp.child_license_id = lml.license_id
						INNER JOIN dbo.license_module_type lmt
							ON lmt.license_module_type_id = lml.license_module_type_id
						INNER JOIN dbo.license_module_category lmc
							ON lmc.license_module_id = lml.license_module_id
					WHERE CAST(lml.end_date AS DATE) = DATEADD(dd, -mcmp.message_measure_days, @date_value)
						  AND etb.exact_target_master_id = @exact_target_master_id
						  AND lmc.license_category_id = etb.license_category_id
						  AND mcmp.message_measure_point_id = @message_measure_point_id
						  AND EXISTS (
						              SELECT 1
						              WHERE (lmt.license_module_type_id = 19 AND ets.capability_type_id = 1)
						                  OR (lmt.license_module_type_id = 20 AND ets.capability_type_id = 2)
						                  OR (lmt.license_module_type_id NOT IN (19, 20)
						                      AND ets.capability_type_id = lmt.license_module_type_id)
						              );
				END

	END



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_exact_target_message_insert_license] (
	@process_date DATETIME = NULL 
)
AS

	SET NOCOUNT ON;

	/*

		DATE		AUTHOR			REMARKS
		2015-01-22	mrobbins		Initial creation 
		2015-07-16	mrobbins		changed to split out to multiple procedures to decrease run time
		2015-08-22	mrobbins		changed exact_target_class to exact_target_class_id
		2016-10-11	mrobbins		US18613 - changed insert/activation to pass capability
		2016-10-20	mrobbins		US17708 - added cycle for campaigns that have it
		2016-11-18	mrobbins		removed message_campaign_id in where for campaigns with cycles
		2017-11-29	mrobbins		added @exact_target_class_id to usp_exact_target_message_insert_activation call
		2018-05-25	mrobbins		extended message_campaign_name
		2019-09-25	mrobbins		changed to exclude new "AR Notification" class - ALCHEMISTS 2226
		2022-09-08	gblandford		added call to usp_exact_target_update_allstate to apply any allstate criteria
									to exact_target_subset3; has-idp, has-wsa, has-account - AIP-32
		2022-11-15	jberry			added the call to usp_exact_target_update_allstate to the "non-cycles" loop
		2024-03-27	cibach			added filter option for next_bill_date
		2026-01-05	mrobbins		added new Child measure point changes US5060635
		2026-01-09	gblandford		US-5060635 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5060635
									- (Removed support for content behaviour change, 2025-12-30	mrobbins Added support for new content behavior US5060635)
									- added child license dimension support
									- child-capability-type & child-license-category
									- formatting, casing, schemas, alias for unqualified column names
		2026-04-18	pachanta		Implemented logic to accommodate seat count enforcement.


		DESCRIPTION
		Loops through email campaigns and inserts license and customer ids into table for processing

		Disi code to exclude BBAS, BBSB, BBAV, BBAW, BBSA, BBWA, BBWI, BBFW, BBSC, TTBB, TTBS, TTBE, AABB, ALLY, GNTI, BNAB, HSBC, BDNZ, BCTR, BHSB, BGAR, BALY, PXAF, PXBA, PXBB, PXCI, PXCP, PXCQ, PXCU, PXDA, PXFB, PXFN, 
		
	*/

	BEGIN TRY

		--truncate table exact_target_batch
		TRUNCATE TABLE exact_target_subset1;
		TRUNCATE TABLE exact_target_subset2;
		TRUNCATE TABLE exact_target_subset3;

		DECLARE @response_code INT,
			@message VARCHAR(100),
			@campaign_id INT,
			@max_campaign_id INT,
			@message_campaign_id INT,
			@message_campaign_name VARCHAR(65),
			@message_campaign_enabled TINYINT,
			@license_category_id INT,
			@message_email_opt_id TINYINT,
			@license_seats INT,
			@message_measure_point_name VARCHAR(50),
			@message_measure_days INT,
			@message_measure_end_days INT,
			@license_distribution_method_id INT,
			@inclusive TINYINT,
			@exact_target_master_id INT,
			@capability_type TINYINT,
			@cart_discount_id INT,
			@renewal_status INT,
			@renewal_status_id INT,
			@max_renewal_status_id INT,
			@exact_target_class_id INT,
			@date_value DATETIME,
			@campaign_cycles INT,
			@cycle_id INT,
			@max_cycle_id INT,
			@seat_overage INT, 
            @seat_available_count INT, 
            @seat_enforcement INT


		IF @process_date IS NULL BEGIN
				SELECT @date_value = CONVERT(VARCHAR(10),GETDATE(),101)
			END
		ELSE BEGIN
				SELECT @date_value = @process_date
			END;

		DECLARE @campaigns TABLE (
			campaign_id INT IDENTITY(1,1),
			message_campaign_id INT,
			exact_target_master_id INT,
			message_campaign_name VARCHAR(65),
			message_campaign_enabled TINYINT,
			license_category_id INT,
			message_email_opt_id TINYINT,
			license_seats INT,
			message_measure_point_name VARCHAR(50),
			message_measure_days INT,
			message_measure_end_days I
NT,
			license_distribution_method_id INT,
			inclusive TINYINT,
			capability_type TINYINT,
			cart_discount_id INT,
			exact_target_class_id INT,
			campaign_cycles INT
		);

		DECLARE @cycle_campaigns TABLE (
			message_campaign_id INT
		);


		DECLARE @renewal TABLE (
			message_campaign_renewal_status_id INT IDENTITY(1,1),
			renewal_status INT
		);

		DECLARE @cycles TABLE (
			cycles_id INT IDENTITY(1,1),
			message_campaign_id INT,
			exact_target_master_id INT,
			exact_target_class_id INT,
			inclusive INT,
			capability_type INT
		);

		INSERT INTO @cycle_campaigns (
		    message_campaign_id
		)
		SELECT DISTINCT 
			mc.message_campaign_id
		FROM dbo.message_campaign mc
			INNER JOIN dbo.message_campaign_platform mcp
				ON mc.message_campaign_id = mcp.message_campaign_id
			INNER JOIN dbo.exact_target_master etm
				ON mc.message_campaign_id = etm.message_campaign_id
			INNER JOIN dbo.exact_target_message_campaign etmc
				ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
			INNER JOIN dbo.exact_target_class etc
				ON etmc.exact_target_class_id = etc.exact_target_class_id
		WHERE mc.message_campaign_class_id = 4
			AND mc.message_campaign_enabled = 1
			AND etc.exact_target_class <> 'AR Notification'

		INSERT INTO @campaigns (
			message_campaign_id,
			exact_target_master_id,
			message_campaign_name,
			message_campaign_enabled,
			message_measure_point_name,
			message_measure_days,
			message_measure_end_days,
			inclusive,
			capability_type,
			cart_discount_id,
			exact_target_class_id,
			campaign_cycles
		)
		SELECT 
			DISTINCT 
			mc.message_campaign_id,
			etm.exact_target_master_id,
			mc.message_campaign_name,
			mc.message_campaign_enabled,
			mmp.message_measure_point_name,
			mcmp.message_measure_days,
			mcmp.message_measure_end_days,
			mcldm.inclusive,
			capability_type = ( CASE 
									WHEN mct.trial = 0 THEN 1  -- Full 
									WHEN mct.trial = 1 THEN 2  -- Trial
								END ),
			cart_discount_id,
			etmc.exact_target_class_id,
			campaign_cycles = 0
		FROM message_campaign mc
			INNER JOIN dbo.message_campaign_measure_point mcmp
				ON mc.message_campaign_id = mcmp.message_campaign_id
			INNER JOIN dbo.message_measure_point mmp
				ON mcmp.message_measure_point_id = mmp.message_measure_point_id
			LEFT JOIN dbo.message_campaign_license_distribution_method mcldm
				ON mc.message_campaign_id = mcldm.message_campaign_id
			INNER JOIN dbo.exact_target_master etm
				ON mc.message_campaign_id = etm.message_campaign_id
			INNER JOIN dbo.message_campaign_trial mct
				ON mc.message_campaign_id = mct.message_campaign_id
			LEFT JOIN dbo.message_campaign_cart_discount mccd
				ON mc.message_campaign_id = mccd.message_campaign_id
			INNER JOIN dbo.exact_target_message_campaign etmc
				ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
			LEFT JOIN dbo.message_campaign_platform mcp
				ON mc.message_campaign_id = mcp.message_campaign_id
			LEFT JOIN dbo.message_cycle mc2
				ON mcp.message_cycle_id = mc2.message_cycle_id
			LEFT JOIN dbo.message_cycle_line mcl
				ON mc2.message_cycle_id = mcl.message_cycle_id
			INNER JOIN dbo.exact_target_class etc
				ON etmc.exact_target_class_id = etc.exact_target_class_id
		WHERE mc.message_campaign_class_id = 4
			AND mc.message_campaign_enabled = 1
			AND etc.exact_target_class <> 'AR Notification'
			AND NOT EXISTS (SELECT cc.message_campaign_id FROM @cycle_campaigns cc WHERE mc.message_campaign_id = cc.message_campaign_id)

		UNION ALL

		SELECT 
			DISTINCT 
			mc.message_campaign_id,
			etm.exact_target_master_id,
			mc.message_campaign_name,
			mc.message_campaign_enabled,
			mmp.message_measure_point_name,
			mcl.cycle_gap_days message_measure_days,
			mcmp.message_measure_end_days,
			mcldm.inclusive,
			capability_type = ( CASE 
									WHEN mct.trial = 0 THEN 1 -- Full
 
									WHEN mct.trial = 1 THEN 2 -- Trial
								END ),
			cart_discount_id,
			etmc.exact_target_class_id,
			campaign_cycles = 1
		FROM dbo.message_campaign mc
			INNER JOIN dbo.message_campaign_measure_point mcmp
				ON mc.message_campaign_id = mcmp.message_campaign_id
			INNER JOIN dbo.message_measure_point mmp
				ON mcmp.message_measure_point_id = mmp.message_measure_point_id
			LEFT JOIN dbo.message_campaign_license_distribution_method mcldm
				ON mc.message_campaign_id = mcldm.message_campaign_id
			INNER JOIN dbo.exact_target_master etm
				ON mc.message_campaign_id = etm.message_campaign_id
			INNER JOIN dbo.message_campaign_trial mct
				ON mc.message_campaign_id = mct.message_campaign_id
			LEFT JOIN dbo.message_campaign_cart_discount mccd
				ON mc.message_campaign_id = mccd.message_campaign_id
			INNER JOIN dbo.exact_target_message_campaign etmc
				ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
			INNER JOIN dbo.message_campaign_platform mcp
				ON mc.message_campaign_id = mcp.message_campaign_id
			INNER JOIN dbo.message_cycle mc2
				ON mcp.message_cycle_id = mc2.message_cycle_id
			INNER JOIN dbo.message_cycle_line mcl
				ON mc2.message_cycle_id = mcl.message_cycle_id
			INNER JOIN dbo.exact_target_class etc
				ON etmc.exact_target_class_id = etc.exact_target_class_id
		WHERE message_campaign_class_id = 4
			AND message_campaign_enabled = 1
			AND etc.exact_target_class <> 'AR Notification'
			AND EXISTS (SELECT cc.message_campaign_id FROM @cycle_campaigns cc WHERE mc.message_campaign_id = cc.message_campaign_id)
			AND mcl.cycle_gap_days IS NOT NULL
		ORDER BY mc.message_campaign_name


		INSERT INTO @cycles (
			message_campaign_id, 
			exact_target_master_id,
			exact_target_class_id, 
			inclusive,
			capability_type
		)
		SELECT 
			DISTINCT 
			message_campaign_id, 
			exact_target_master_id,
			exact_target_class_id, 
			inclusive,
			capability_type
		FROM @campaigns
		WHERE campaign_cycles = 1

		SELECT @campaign_id = MIN(campaign_id), 
			@max_campaign_id = MAX(campaign_id)
		FROM @campaigns

		--select * from @campaigns

		WHILE ( @campaign_id <= @max_campaign_id ) BEGIN

				--print @message_campaign_name

				SELECT @message_campaign_id = message_campaign_id,
					@exact_target_master_id = exact_target_master_id,
					@message_campaign_name = message_campaign_name,
					@message_campaign_enabled = message_campaign_enabled, 
					@message_measure_point_name = message_measure_point_name,
					@message_measure_days = message_measure_days,
					@message_measure_end_days = message_measure_end_days,
					@inclusive = inclusive,
					@capability_type = capability_type,
					@cart_discount_id = cart_discount_id,
					@exact_target_class_id = exact_target_class_id,
					@campaign_cycles = campaign_cycles
				FROM @campaigns
				WHERE campaign_id = @campaign_id
				
				--inserts into subset1
				IF @message_measure_point_name = 'activation' BEGIN
						EXECUTE  dbo.usp_exact_target_message_activation @date_value, @message_measure_days, @exact_target_master_id, @cart_discount_id, @exact_target_class_id, @message_campaign_name,@message_campaign_id
					END

				IF @message_measure_point_name = 'expiration' BEGIN
						EXECUTE dbo.usp_exact_target_message_expiration @date_value, @message_measure_days, @exact_target_master_id, @cart_discount_id
					END
                        
				IF @message_measure_point_name = 'Next Bill Date' BEGIN
						EXECUTE dbo.usp_exact_target_message_next_bill_date @date_value, @message_measure_days, @exact_target_master_id, @cart_discount_id
					END

				IF @message_measure_point_name = 'insert/activation' BEGIN
						--print 'usp_exact_target_message_insert_activation ' + convert(varchar(10),@date_value,101) + ',' +  str(@message_measure_days)+ ',' + str(isnull(@message_measure_end_days,0)) + ',' + str(@exact_target_master_id) + ',' + str(isnull(
@cart_discount_id,0)) + ',' + str(@capability_type)
							
						EXECUTE dbo.usp_exact_target_message_insert_activation @date_value, @message_measure_days, @message_measure_end_days, @exact_target_master_id, @cart_discount_id,@capability_type,@exact_target_class_id,@message_campaign_id
					END

				IF @message_measure_point_name = 'Child License Expiration' BEGIN
						--print 'usp_exact_target_message_insert_child_license_expiration' + convert(varchar(10),@date_value,101) + ',' +  str(@message_measure_days)+ ',' + str(@exact_target_master_id) + ',' + str(isnull(@cart_discount_id,0))
							
						EXECUTE dbo.usp_exact_target_message_insert_child_license_expiration @date_value, @message_measure_days, @exact_target_master_id, @cart_discount_id
					END
					
					
				/***************************Logic for Seat count enforcement************************************************/
						/*********BEGIN***********/

					SELECT @seat_enforcement = mcsce.seatcount_enforcement
					FROM dbo.message_campaign_seat_count_enforcement mcsce 
					WHERE mcsce.message_campaign_id = @message_campaign_id;

					SELECT @seat_overage = mcso.seat_overage
					FROM dbo.message_campaign_seat_overage mcso 
					WHERE mcso.message_campaign_id = @message_campaign_id;

					IF @seat_enforcement IS NOT NULL OR @seat_overage IS NOT NULL

					BEGIN

					------------------------------------------------------------
					--  Seat Available Values
					------------------------------------------------------------
					DECLARE @message_campaign_seat_available TABLE (seat_available INT);

					INSERT INTO @message_campaign_seat_available (seat_available)
					SELECT mcsa.seat_available 
					FROM dbo.message_campaign_seat_available mcsa 
					WHERE mcsa.message_campaign_id = @message_campaign_id;

					SELECT @seat_available_count = COUNT(*) 
					FROM @message_campaign_seat_available;

					------------------------------------------------------------
					--  Seat Overage Logic
					------------------------------------------------------------
					IF @seat_overage = 1
					BEGIN
						-- Remove under-used licenses
						DELETE ets
						FROM exact_target_subset1 ets
						LEFT JOIN dbo.license_active_seats las ON las.license_id = ets.license_id
						JOIN dbo.license_seat ls ON ls.license_id = ets.license_id
						WHERE ls.license_seats > las.consumed_seats or las.consumed_seats IS NULL

					END

					ELSE IF @seat_overage = 0
					BEGIN
						-- Remove over-used licenses
						DELETE ets
						FROM exact_target_subset1 ets
						JOIN dbo.license_active_seats las ON las.license_id = ets.license_id
						JOIN dbo.license_seat ls ON ls.license_id = ets.license_id
						WHERE ls.license_seats < las.consumed_seats;
					END

					------------------------------------------------------------
					-- Seat Enforcement Logic
					------------------------------------------------------------
					IF @seat_enforcement = 1
					BEGIN
						DELETE ets
					FROM exact_target_subset1 ets
					LEFT JOIN dbo.product_line_license_seat_distribution pllsd
						ON pllsd.product_line_id = ets.product_line_id
						AND pllsd.license_distribution_method_id = ets.license_distribution_method_id
						AND pllsd.license_category_id = ets.license_category_id
						WHERE pllsd.product_line_license_distribution_id IS NULL
						OR  pllsd.seat_count_enforcement = 0;
					END
					ELSE IF @seat_enforcement = 0
					BEGIN
					DELETE ets
					FROM exact_target_subset1 ets
					LEFT JOIN dbo.product_line_license_seat_distribution pllsd
						ON pllsd.product_line_id = ets.product_line_id
						AND pllsd.license_distribution_method_id = ets.license_distribution_method_id
						AND pllsd.license_category_id = ets.license_category_id
						WHERE  pllsd.seat_count_enforcement = 1;
					END

					------------------------------------------------------------
					--Seat Available Logic 
					-----------------
-------------------------------------------
					IF @seat_available_count > 0
					BEGIN

						DELETE ets
						FROM #exact_target_subset1 ets
						JOIN dbo.license_active_seats las 
							ON las.license_id = ets.license_id
						JOIN dbo.license_seat ls 
							ON ls.license_id = ets.license_id
						WHERE
						(
							-- Case 1: 11 exists
							EXISTS (SELECT 1 FROM @message_campaign_seat_available WHERE seat_available = 11)
							AND (ls.license_seats - las.consumed_seats) < 11
							AND NOT EXISTS (
								SELECT 1 
								FROM @message_campaign_seat_available sat
								WHERE sat.seat_available = (ls.license_seats - las.consumed_seats)
							)
						)
						OR
						(
							-- Case 2: -11 exists
							EXISTS (SELECT 1 FROM @message_campaign_seat_available WHERE seat_available = -11)
							AND (ls.license_seats - las.consumed_seats) > -11
							AND NOT EXISTS (
								SELECT 1 
								FROM @message_campaign_seat_available sat
								WHERE sat.seat_available = (ls.license_seats - las.consumed_seats)
							)
						)
						OR
						(
							-- Case 3: other values
							NOT EXISTS (
								SELECT 1 FROM @message_campaign_seat_available WHERE seat_available IN (11, -11)
							)
							AND NOT EXISTS (
								SELECT 1 
								FROM @message_campaign_seat_available sat
								WHERE sat.seat_available = (ls.license_seats - las.consumed_seats)
							)
						)
					END

					END
				/*************************************END****************************************************************************/

					
					
				IF @campaign_cycles = 0 BEGIN

						--print '@campaign_cycles = ' + str(@campaign_cycles)

						--inserts into subset2
						EXECUTE dbo.usp_exact_target_message_insert_distribution @exact_target_master_id, @exact_target_class_id, @inclusive 

						--inserts into subset3
						--print 'exec usp_exact_target_message_insert_renewals ' + str(@exact_target_master_id)
						EXECUTE dbo.usp_exact_target_message_insert_renewals @exact_target_master_id

						--do allstate filtering - remove from subset3
						EXECUTE dbo.usp_exact_target_message_update_allstate @exact_target_master_id

						--do child license filtering 
						EXECUTE dbo.usp_exact_target_message_update_child_license @exact_target_master_id

						--inserts into exact_target_batch
						EXECUTE dbo.usp_exact_target_message_insert_final @exact_target_master_id, @capability_type, @exact_target_class_id, @date_value

						--if @exact_target_class_id = 4 --'SMB Special'
						--	begin
						--		exec usp_exact_target_message_insert_WWSS @exact_target_master_id
						--	end
					END

				SET @campaign_id = @campaign_id + 1

			END;  --campaign loop

			SELECT @cycle_id = MIN(cycles_id), 
				@max_cycle_id = MAX(cycles_id)
			FROM @cycles;

			--loop through finish procedures for campaigns with cycles
			WHILE ( @cycle_id <= @max_cycle_id ) BEGIN
					
					--print '@exact_target_master_id = ' + str(@exact_target_master_id)

					SELECT 
						@message_campaign_id = message_campaign_id,
						@exact_target_master_id = exact_target_master_id,
						@inclusive = inclusive,
						@capability_type = capability_type,
						@exact_target_class_id = exact_target_class_id
					FROM @cycles
					WHERE cycles_id = @cycle_id;
				
					--print 'exec usp_exact_target_message_insert_distribution ' + str(@exact_target_master_id) + ',' + str(@exact_target_class_id) + ',' + str(@inclusive)
					EXECUTE dbo.usp_exact_target_message_insert_distribution @exact_target_master_id, @exact_target_class_id, @inclusive 

					--inserts into subset3
					--print 'exec usp_exact_target_message_insert_renewals ' + str(@exact_target_master_id)
					EXECUTE dbo.usp_exact_target_message_insert_renewals @exact_target_master_id

					--do allstate filtering - remove from subset3
					EXECUTE dbo.usp_exact_target_message_update_allstate @exact_target_master_id

			
		--do child license filtering 
					EXECUTE dbo.usp_exact_target_message_update_child_license @exact_target_master_id

					--inserts into exact_target_batch
					--print 'exec usp_exact_target_message_insert_final ' + str(@exact_target_master_id) + ',' + str(@capability_type) + ',' + str(@exact_target_class_id) + ',' + convert(varchar(10),@date_value,101)
					EXECUTE dbo.usp_exact_target_message_insert_final @exact_target_master_id, @capability_type, @exact_target_class_id, @date_value

					SET @cycle_id = @cycle_id + 1
				END

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_renewals]
-- =============================================================================
CREATE PROCEDURE usp_exact_target_message_insert_renewals
	(@exact_target_master_id int)


AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @renewal_status_id int,
		@max_renewal_status_id int,
		@renewal_status int,
		@message_campaign_id int

	select @message_campaign_id = message_campaign_id
	from exact_target_master
	where exact_target_master_id = @exact_target_master_id

	declare @renewal table (message_campaign_renewal_status_id INT IDENTITY(1,1),
		renewal_status int);
				
	insert into @renewal (renewal_status)
	select distinct renewal_status
	from message_campaign_renewal_status mcrs
	where message_campaign_id = @message_campaign_id

	select @renewal_status_id = min(message_campaign_renewal_status_id), @max_renewal_status_id = max(message_campaign_renewal_status_id)
	from @renewal

	while @renewal_status_id <= @max_renewal_status_id
		begin

			select @renewal_status = renewal_status
			from @renewal
			where message_campaign_renewal_status_id = @renewal_status_id

			if @renewal_status = 0
				begin

					--print 'renewal status 0'

					insert into exact_target_subset3 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					select distinct s.exact_target_master_id,
						s.license_id,
						s.cart_discount_id,
						s.license_distribution_method_id,
						s.license_category_id,
						s.product_line_id,
						s.opt_in,
						s.autorenewal_opt_id,
						s.capability_type_id,
						s.license_seats
					from exact_target_subset2 s
					where s.exact_target_master_id = @exact_target_master_id
						and not exists (select *
						from license_renewals lr
						where s.license_id = lr.license_id)
				end

			if @renewal_status = 1
				begin

					--print 'renewal status 1'

					insert into exact_target_subset3 (exact_target_master_id,
						license_id,
						cart_discount_id,
						license_distribution_method_id,
						license_category_id,
						product_line_id,
						opt_in,
						autorenewal_opt_id,
						capability_type_id,
						license_seats)
					select distinct s.exact_target_master_id,
						s.license_id,
						s.cart_discount_id,
						s.license_distribution_method_id,
						s.license_category_id,
						s.product_line_id,
						s.opt_in,
						s.autorenewal_opt_id,
						s.capability_type_id,
						s.license_seats
					from exact_target_subset2 s
					where s.exact_target_master_id = @exact_target_master_id
						and exists (select *
						from license_renewals lr
						where s.license_id = lr.license_id)
				end

				set @renewal_status_id = @renewal_status_id + 1
		end   --RENEWAL LOOP

END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_insert_WWSS]
-- =============================================================================
CREATE PROCEDURE usp_exact_target_message_insert_WWSS
	(@exact_target_master_id int)


AS
BEGIN

	SET NOCOUNT ON;	


	update exact_target_batch
	set email_type = 'license'
	where exact_target_master_id = @exact_target_master_id

	insert into exact_target_batch (license_id, customer_id, cart_discount_id, exact_target_master_id,email_type,exact_target_batch_status_id, mail_date)
	select etb.license_id,
		a.customer_id,
		etb.cart_discount_id,
		etb.exact_target_master_id,
		'admin' email_type,
		0 exact_target_batch_status_id,
		etb.mail_date
	from exact_target_batch etb
		inner join license_channel_license lcl
			on etb.license_id = lcl.license_id
		left join wwss_account a
			on etb.license_id = a.license_id
	where exact_target_master_id = @exact_target_master_id

END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_next_bill_date]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_exact_target_message_next_bill_date]
(
    @date_value DATETIME,
    @message_measure_days INT,
    @exact_target_master_id INT,
    @cart_discount_id INT
)
AS
BEGIN

    /*

        DATE        AUTHOR            REMARKS
        2024-03-27    cibach            initial creation


        DESCRIPTION:
        Filter licenses by next_bill_date to determine if they are eligible for message campaigns

    */
    SET NOCOUNT ON;

    SELECT @date_value = CONVERT(VARCHAR(10), @date_value, 101);

    INSERT INTO exact_target_subset1
    (
        exact_target_master_id,
        license_id,
        cart_discount_id,
        license_distribution_method_id,
        license_category_id,
        product_line_id,
        opt_in,
        autorenewal_opt_id,
        capability_type_id,
        license_seats
    )
    SELECT DISTINCT
           @exact_target_master_id,
           ls.license_id,
           @cart_discount_id,
           ls.license_distribution_method_id,
           ls.license_category_id,
           ls.product_line_id,
           ls.opt_in,
           ls.autorenewal_opt_id,
           ls.capability_type_id,
           ls.license_seats
    FROM license_summary ls WITH (NOLOCK)
        LEFT JOIN dbo.license_next_bill_date lnbd
            ON lnbd.license_id = ls.license_id
    WHERE (
              CAST(lnbd.next_bill_date AS DATE) = DATEADD(dd, -@message_measure_days, @date_value)
              OR
              (
                  lnbd.next_bill_date IS NULL
                  AND CAST(ls.capability_expiration_date AS DATE) = DATEADD(dd, -@message_measure_days, @date_value)
              )
          )
          AND license_status_id = 1
          AND NOT EXISTS
    (
        SELECT *
        FROM license_swap ls2 WITH (NOLOCK)
        WHERE ls.license_id = ls2.original_license_id
              AND ls2.license_swap_status_id = 2
    );
END;


GO
