								           - Added section to capture child records for child license expiration measure point
								           - Added logic to get child license count by parent license and license category for @message_service_json
	2026-03-27  jberry			US-5308586 - Added new fields to @cart_select_license_configurator_pricing
	2026-04-20  jberry			D-5360122 - Fixed data type on @cart_select_license_configurator_pricing for retention_model_name
	2026-04-30  jberry			US-5359090 - Added conversion for @child_capability_type_id to convert 0 to 1 for full and 1 to 2 for trials

	DESCRIPTION

	DEPENCENCIES	: usp_cart_select_renewal_product_set 
					: usp_cart_select_license_configurator_pricing
					: usp_sfdc_select_order_company
	SQL Job			: Exact Target Daily Mail PROD job is scheduled to run at 4 a.m. MST and calls the Exact Target Daily Mail SSIS job in cordenetl2.services.webroot. 
					  It sends the output files (DRAU/DTRX/WETI) to Salesforce Marketing Cloud.
	


	Pull in keycode, category_prefix, seats, storage_gb, years, cart_discount_id, language, location
	To call exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id

	ATTR_STRING10|ATTR_STRING12|EMAIL|FIRST_NAME|LAST_NAME|ATTR_STRING11|ATTR_STRING13|ATTR_DATE3|ATTR_DATE1|ATO_PASSWORD|DECLARED_INTEREST2|DECLARED_INTEREST1|REGION|LANGUAGE|COUNTRY|ATTR_NUM18|ATTR_NUM19|ATTR_NUM20|DiscountCode|InvoiceNumber|Price|ProductVersion|messagecodetrig|specialcodetrig

	campaign|class|email|first_name|last_name|license_category_description|activation|expiration|keycodeencypted|keycode|declared_interest1|region|language|country|OptOffers|OptUpdates|OptNews|discount|invoicecode|price|ProductVersion|license_key|specialscode|UserGuid



*/

BEGIN TRY


    IF @date_value IS NULL
       OR @date_value = ''
       OR LEN(@date_value) = 0
        SET @date_value = GETDATE()


    DECLARE @response_code INT,
            @message VARCHAR(100),
            @rec_id INT,
            @max_rec_id INT,
            @keycode VARCHAR(40),
            @license_category_name VARCHAR(10),
            @seats INT,
            @storage INT,
            @years FLOAT,
            @cart_discount_id INT,
            @language_code VARCHAR(2),
            @location_code VARCHAR(3),
            @retail_price MONEY,
            @net_price MONEY,
            @discount MONEY,
            @currency_symbol VARCHAR(2),
            @product_line_id INT,
            @return_id INT,
            @max_return_id INT,
            @message_service_id INT,
            @message_service_type_id INT,
            @message_service_json NVARCHAR(MAX),
            @message_service_type_name VARCHAR(50),
            @message_service_client_id INT,
            @customer_email VARCHAR(100),
            @order_header_id INT,
            @license_id INT,
            @item_json NVARCHAR(MAX),
            @bundle_json NVARCHAR(MAX),
            @sky_license_seats INT,
            @license_distribution_method_code VARCHAR(4),
            @message_measure_point_id INT,
            @child_license_category_id INT,
            @child_capability_type_id INT,
            @message_campaign_id INT;

	DECLARE @child_licenses TABLE
	(
	    parent_license_id INT,
	    child_license_id INT,
	    license_category_name VARCHAR(50),
	    license_category_description VARCHAR(255),
	    capability_type_description VARCHAR (150),
	    capability_expiration_date DATETIME
	)

   
	DROP TABLE IF EXISTS #exact_target_batch_data
	CREATE TABLE #exact_target_batch_data 
	(
		exact_target_batch_id INT PRIMARY KEY,
		license_id INT,
		license_category_id INT,
		exact_target_file_prefix VARCHAR(50),
		exact_target_master_id INT,
		exact_target_batch_status_id INT,
		customer_id INT,
		cart_discount_id INT,
		message_campaign_id INT,
		exact_target_m
essage_campaign_id INT,
		email_type VARCHAR(30),
		message_measure_point_id INT
		
	)

	INSERT INTO #exact_target_batch_data
	(
	exact_target_batch_id,
	license_id,
	license_category_id,
	exact_target_file_prefix,
	exact_target_master_id,
	exact_target_batch_status_id,
	customer_id,
	cart_discount_id,
	message_campaign_id,
	exact_target_message_campaign_id,
	email_type,
	message_measure_point_id
	)
	SELECT etb.exact_target_batch_id,
	       etb.license_id,
	       etb.license_category_id,
	       etfp.exact_target_file_prefix,
	       etb.exact_target_master_id,
	       etb.exact_target_batch_status_id,
	       etb.customer_id,
	       etb.cart_discount_id,
	       etm.message_campaign_id,
	       etmc.exact_target_message_campaign_id,
	       email_type,
	       mcmp.message_measure_point_id
	FROM exact_target_batch etb
	        INNER JOIN exact_target_master etm
	    ON etb.exact_target_master_id = etm.exact_target_master_id
	        INNER JOIN exact_target_message_campaign etmc
	    ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
	        INNER JOIN exact_target_file_prefix etfp
	    ON etmc.exact_target_file_prefix_id = etfp.exact_target_file_prefix_id
	        INNER JOIN dbo.message_campaign_measure_point mcmp
	    ON mcmp.message_campaign_id = etm.message_campaign_id
	WHERE CAST(etb.mail_date AS DATE) = CAST(@date_value AS DATE)

	 CREATE NONCLUSTERED INDEX IX_exact_target_batch_tmp_1 ON #exact_target_batch_data (license_id)
	 CREATE NONCLUSTERED INDEX IX_exact_target_batch_tmp_2 ON #exact_target_batch_data (exact_target_file_prefix)
	 CREATE NONCLUSTERED INDEX IX_exact_target_batch_tmp_3 ON #exact_target_batch_data (
                                [exact_target_batch_status_id],
                                [exact_target_master_id]
                            )
		INCLUDE (
					[exact_target_batch_id],
					[license_id]
				)
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------
    --	REMOVE REFUNDS FROM ALL MESSAGES
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @refunds TABLE
    (
        rec_id INT IDENTITY(1, 1) ,
        exact_target_batch_id INT ,
        order_status_id INT,
        order_header_id INT,
        license_id INT		
    )

    INSERT INTO @refunds
    (
        order_header_id,
        exact_target_batch_id,
        order_status_id,
        license_id
    )
    SELECT MAX(oh.order_header_id) order_header_id,
           etb.exact_target_batch_id,
           oh.order_status_id,
           etb.license_id  
    FROM #exact_target_batch_data etb
        INNER JOIN order_item_license oil
            ON etb.license_id = oil.license_id
        INNER JOIN order_item oi
            ON oil.order_item_id = oi.order_item_id
        INNER JOIN order_header oh
            ON oi.order_header_id = oh.order_header_id
        --INNER JOIN vendor_order vo
        --    ON oh.vendor_order_id = vo.vendor_order_id
    --WHERE CAST(etb.mail_date AS DATE) = CAST(@date_value AS DATE)
    --      --and etmc.exact_target_class_id in (5,6,7,8)
    --      --and cast(ls.capability_activation_date as date) = cast(oh.modified_date as date)
    --      AND etfp.exact_target_file_prefix = @Campaign_Prefix
	WHERE etb.exact_target_file_prefix=@Campaign_Prefix
    GROUP BY etb.exact_target_batch_id,
             oh.order_status_id,
             etb.license_id


    --select *
    --from @refunds
    --where order_status_id = 3

    DELETE FROM etb
    --update etb
    --set exact_target_batch_status_id = 2
    FROM exact_target_batch etb
        INNER JOIN @refunds r
            ON etb.exact_target_batch_id = r.exact_target_batch_id
    WHERE r.order_status_id = 
3

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------
    --	REMOVE MODULE LEVEL CATEGORIES (SDNS/SECA) IF OUTPUT FILE IS SMB
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------

	IF @message_measure_point_id <> 8  --Child License Expiration
		BEGIN 

			DELETE  etb
			FROM  #exact_target_batch_data eb
			INNER JOIN dbo.exact_target_batch etb
			ON etb.exact_target_batch_id = eb.exact_target_batch_id
				INNER JOIN dbo.license_category lc
					ON etb.license_category_id = lc.license_category_id
			WHERE eb.exact_target_file_prefix = 'SMB'
				 -- AND CAST(etb.mail_date AS DATE) = CAST(@date_value AS DATE)
				  AND lc.license_category_name IN ( 'SDNS', 'SECA' )
				  AND EXISTS
			(
				SELECT etb2.license_id
				FROM #exact_target_batch_data eb2
			INNER JOIN dbo.exact_target_batch etb2
			ON etb2.exact_target_batch_id = eb2.exact_target_batch_id
					INNER JOIN dbo.license_category lc2
						ON etb2.license_category_id = lc2.license_category_id
				WHERE eb2.exact_target_file_prefix = 'SMB'
					  --AND CAST(etb2.mail_date AS DATE) = CAST(@date_value AS DATE)
					  AND lc2.license_category_name = 'SAEP'
					  AND etb.license_id = etb2.license_id
			)

		END

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------
    --	Flag Security Summary Records that don't have any sky_license_activity
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------

    UPDATE etb
    SET etb.exact_target_batch_status_id = 2
	FROM #exact_target_batch_data b
	INNER JOIN dbo.exact_target_batch etb
	ON etb.exact_target_batch_id = b.exact_target_batch_id
        LEFT JOIN dbo.sky_license_activity sla
            ON sla.license_id = b.license_id
    WHERE b.exact_target_master_id IN ( 98, 118, 121, 134, 135 )
          --AND CAST(b.mail_date AS DATE) = CAST(@date_value AS DATE)
          AND b.exact_target_batch_status_id = 0
          AND
          (
              sla.license_id IS NULL
              OR ISNULL(sla.scan_count,0) = 0
          )


	DROP TABLE IF EXISTS #recs 
	CREATE TABLE #recs
    (
        rec_id INT IDENTITY(1, 1) PRIMARY KEY,
        exact_target_batch_id INT,
        license_id INT,
        keycode VARCHAR(40),
        license_keycode_type_id INT,
        license_category_name VARCHAR(10),
        license_category_id INT,
        license_seats INT,
        storage_gb INT,
        years FLOAT,
        cart_discount_id INT NULL,
        language_code VARCHAR(2),
        location_code VARCHAR(3),
        iso VARCHAR(2),
        product_line_id INT,
        retail_price MONEY,
        net_price MONEY,
        discount MONEY,
        currency_symbol VARCHAR(2),
        json_call NVARCHAR(MAX),
        license_distribution_method_code VARCHAR(4),
        message_measure_point_id INT
		
    )
   INSERT INTO #recs
    (
        exact_target_batch_id,
        license_id,
        keycode,
        license_keycode_type_id,
        license_category_name,
        license_category_id,
        license_seats,
        storage_gb,
        years,
        cart_discount_id,
        language_code,
        location_code,
        iso,
        product_line_id,
        license_distribution_method_code,
        message_measure_point_id
    )
	SELECT DISTINCT 
	          b.exact_target_batch_id,
	          s.license_id,
	          s.keycode,
	          l.license_keycode_type_id,
	          lc.license_category_name,
	          lc.license_category_id,
	          s.license_seats,
	          ls.storage_gb,
	   
       1 years,
	          b.cart_discount_id,
	          CASE
	              WHEN cl.language_code IS NULL THEN
	                  'EN'
	              ELSE
	                  cl.language_code
	          END language_code,
	          CASE
	              WHEN cl.location_code IS NULL THEN
	                  'USA'
	              ELSE
	                  cl.location_code
	          END location_code,
	          luc.iso,
	          s.product_line_id,
	          ldm.license_distribution_method_code,
	          b.message_measure_point_id
	   FROM #exact_target_batch_data b
			INNER JOIN dbo.exact_target_batch etb
				ON etb.exact_target_batch_id = b.exact_target_batch_id
	       --INNER JOIN exact_target_master m
	       --    ON b.exact_target_master_id = m.exact_target_master_id
	       --INNER JOIN exact_target_message_campaign etmc
	       --    ON m.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
	       LEFT JOIN customer_locale cl
	           ON b.customer_id = cl.customer_id
	       INNER JOIN license_summary s
	           ON b.license_id = s.license_id
	       INNER JOIN license l
	           ON b.license_id = l.license_id
	       LEFT JOIN license_storage ls
	           ON b.license_id = ls.license_id
	       INNER JOIN license_category lc
	           ON b.license_category_id = lc.license_category_id
	       LEFT JOIN lu_countries luc
	           ON cl.location_code = luc.iso3
	       --INNER JOIN exact_target_file_prefix etfp
	       --    ON etmc.exact_target_file_prefix_id = etfp.exact_target_file_prefix_id
	       INNER JOIN dbo.license_distribution_method AS ldm
	           ON ldm.license_distribution_method_id = l.license_distribution_method_id
	   WHERE etb.exact_target_batch_status_id = 0
	         AND b.exact_target_file_prefix = @Campaign_Prefix
	        -- AND CAST(b.mail_date AS DATE) = CAST(@date_value AS DATE)
	
    --select '#recs - before', * from #recs
    --return
	CREATE NONCLUSTERED INDEX IX_recs_temp ON #recs(license_id)
	DROP TABLE IF EXISTS #proc_return
    CREATE TABLE #proc_return
    (
        product_id INT,
        product_description VARCHAR(100),
        retail_price MONEY,
        upgrade_price MONEY,
        discount MONEY,
        standard_discount MONEY
            DEFAULT 0,
        net_price MONEY,
        product_type_id INT,
        license_category_name VARCHAR(10),
        seats INT,
        years FLOAT,
        p_type VARCHAR(20),
        currency_id TINYINT,
        currency_code CHAR(3),
        currency_description VARCHAR(20),
        symbol_html VARCHAR(10),
        symbol_utf8 NVARCHAR(10),
        symbol_text VARCHAR(10),
        cart_discount_id INT NULL
    )
	CREATE NONCLUSTERED INDEX IX_proc_return_tmp ON #proc_return(retail_price)
    DECLARE @license_profile_pricing TABLE
    (
        item_id INT,
        license_id INT,
        license_category_name VARCHAR(10),
        license_category_description VARCHAR(255),
        license_seats INT,
        storage_gb INT,
        license_keycode_type_id INT,
        start_date DATETIME,
        expiration_date DATETIME,
        license_attribute_id INT,
        license_attribute_description VARCHAR(150),
        license_attribute_license_value VARCHAR(150),
        license_attribute_license_value_description VARCHAR(150),
        category_type_name VARCHAR(50),
        item_hierarchy_id TINYINT,
        item_hierarchy_name VARCHAR(50),
        license_status_id INT,
        license_status_description VARCHAR(150),
        autorenewal_cycle_name VARCHAR(50),
        autorenewal_cycle DECIMAL(18, 3)
    )

    DECLARE @item_json_table TABLE
    (
        item_json_table_id INT IDENTITY(1, 1),
        item_hierarchy_id INT,
        quantity INT,
        cart_item_bundle_id INT,
        years INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        cart_
discount_id INT
    )

    DECLARE @cart_select_license_configurator_pricing TABLE
    (
        line_item INT,
        quantity INT,
        order_item_offer_amount MONEY
            DEFAULT 0,
        equivalent_year_price MONEY
            DEFAULT 0,
        list_price MONEY
            DEFAULT 0,
        unit_price MONEY
            DEFAULT 0,
        usage_price MONEY
            DEFAULT 0,
        product_id INT,
        product_description VARCHAR(155),
        product_type_id INT,
        product_type_description VARCHAR(155),
        license_keycode_type_id INT,
        license_category_id INT,
        license_category_name VARCHAR(10),
        license_category_description VARCHAR(155),
        product_family_description VARCHAR(155),
        start_date DATETIME,
        expiration_date DATETIME,
        cart_item_bundle_id INT,
        item_hierarchy_id TINYINT,
        dependent_cart_order_itemid INT,
        keycode VARCHAR(40),
        discount FLOAT,
        cart_discount_method_id INT,
        cart_discount_id INT,
        license_id INT,
        list_price_total MONEY
            DEFAULT 0,
        unit_price_total MONEY
            DEFAULT 0,
        json_call NVARCHAR(MAX),
        storage_gb INT, 
        usage_pricing_model_id INT, 
        retention_model_id INT, 
        retention_term INT, 
        retention_model_name VARCHAR(50), 
        actual_storage_quantity INT 
    )


    SELECT @rec_id = MIN(rec_id),
           @max_rec_id = MAX(rec_id)
    FROM #recs
	
	
    WHILE @rec_id <= @max_rec_id
    BEGIN
        SELECT @license_id = license_id,
               @keycode = keycode,
               @license_category_name = license_category_name,
               @seats = license_seats,
               @storage = storage_gb,
               @years = years,
               @cart_discount_id = cart_discount_id,
               @language_code = language_code,
               @location_code = location_code,
               @product_line_id = product_line_id,
               @license_distribution_method_code = license_distribution_method_code,
               @message_measure_point_id = message_measure_point_id
        FROM #recs
        WHERE rec_id = @rec_id

        --select @keycode + '   ' + @category + '   ' + str(@seats) + '   ' + str(@storage) + '   ' + str(@years)
        --print 'exec usp_cart_select_renewal_product_set ' + @keycode + ', ' + @license_category_name + ', ' + str(@seats) +', ' + str(@storage) + ', ' + str(@years) + ', ' + str(@cart_discount_id) + ', ' + @language_code  + ', ' + @location_code
      
	   
	   IF @product_line_id <> 300
        BEGIN

            /*Changes applying only DRAU and @license_distribution_method_code = 'TTSB'  */
            IF (
                   @Campaign_Prefix = 'DRAU'
                   AND @license_distribution_method_code = 'TTSB'
               )
            BEGIN
					IF EXISTS
					(
						SELECT 1
						FROM dbo.sky_license_activity
						WHERE license_id = @license_id
					)
					BEGIN
					
						/*Get the discount seats based on the active device*/
						SELECT @sky_license_seats = CASE
														WHEN sla.device_count < 4 THEN
															3
														WHEN sla.device_count < 6 THEN
															5
														WHEN sla.device_count < 11 THEN
															10
														ELSE
															25
													END
						FROM dbo.sky_license_activity AS sla
							JOIN
							(
								SELECT MAX(sla2.last_scan_date) AS last_scan_date
								FROM dbo.sky_license_activity AS sla2
								WHERE sla2.license_id = @license_id
							) AS sl
								ON sl.last_scan_date = sla.last_scan_date
						WHERE sla.license_id = @license_id
					END
                /*Set seats logic based on the active device*/
                IF @sky_license_seats IS NOT NULL
                    SET @seats = @sky_license_seats
            END
			
            IN
SERT INTO #proc_return
            EXEC usp_cart_select_renewal_product_set @keycode,
                                                     @license_category_name,
                                                     @seats,
                                                     @storage,
                                                     @years,
                                                     @cart_discount_id,
                                                     @language_code,
                                                     @location_code
			

            SELECT @retail_price = SUM(retail_price),
                   @net_price = SUM(net_price),
                   @currency_symbol = symbol_utf8,
                   @discount = SUM(discount)
            FROM #proc_return
            WHERE retail_price <> 0.00
            GROUP BY symbol_utf8

            UPDATE #recs
            SET retail_price = @retail_price,
                net_price = @net_price,
                currency_symbol = @currency_symbol,
                discount = @discount
            WHERE license_id =@license_id

           TRUNCATE TABLE #proc_return
        END

        IF @product_line_id = 300
        BEGIN


            DELETE FROM @item_json_table
            DELETE FROM @license_profile_pricing
            DELETE FROM @cart_select_license_configurator_pricing

            INSERT INTO @license_profile_pricing
            (
                item_id,
                license_id,
                license_category_name,
                license_seats,
                storage_gb,
                license_keycode_type_id,
                start_date,
                expiration_date,
                license_attribute_id,
                license_attribute_description,
                license_attribute_license_value,
                license_attribute_license_value_description,
                category_type_name,
                item_hierarchy_id,
                license_status_id,
                license_status_description,
                autorenewal_cycle_name,
                autorenewal_cycle
            )
            SELECT item_id,
                   license_id,
                   f.license_category_name,
                   license_seats,
                   storage_gb,
                   license_keycode_type_id,
                   start_date,
                   expiration_date,
                   license_attribute_id,
                   license_attribute_description,
                   license_attribute_license_value,
                   license_attribute_license_value_description,
                   category_type_name,
                   item_hierarchy_id,
                   license_status_id,
                   license_status_description,
                   autorenewal_cycle_name,
                   autorenewal_cycle
            FROM dbo.fn_license_select_license_profile(@license_id) f

            UPDATE lp
            SET lp.license_category_description = lc.license_category_description
            FROM @license_profile_pricing lp
                LEFT JOIN dbo.license_category lc
                    ON lc.license_category_name = lp.license_category_name



            INSERT INTO @item_json_table
            (
                item_hierarchy_id,
                quantity,
                cart_item_bundle_id,
                years,
                license_category_name,
                license_seats,
                storage_gb,
                cart_discount_id
            )
            SELECT item_hierarchy_id,
                   1,
                   1,
                   1,
                   license_category_name,
                   license_seats,
                   storage_gb,
                   @cart_discount_id
            FROM @license_profile_pricing


            SELECT @item_json =
            (
                SELECT quantity,
       
                item_hierarchy_id,
                       cart_item_bundle_id,
                       years,
                       license_category_name,
                       license_seats,
                       ISNULL(storage_gb, '') storage_gb,
                       cart_discount_id
                FROM @item_json_table
                FOR JSON PATH
            )

            --SELECT * FROM @item_json_table
            --SELECT @item_json item_json

            SELECT @bundle_json =
            (
                SELECT LOWER(r.language_code) + '_' + LOWER(lc.iso) locale,
                       keycode,
                       license_keycode_type_id
                FROM #recs r
                    INNER JOIN dbo.lu_countries lc
                        ON r.location_code = lc.iso3
                WHERE rec_id = @rec_id
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            )

            --SELECT @bundle_json bundle_json

            INSERT INTO @cart_select_license_configurator_pricing
            (
                line_item,
                quantity,
                order_item_offer_amount,
                equivalent_year_price,
                list_price,
                unit_price,
                usage_price,
                product_id,
                product_description,
                product_type_id,
                product_type_description,
                license_keycode_type_id,
                license_category_id,
                license_category_name,
                license_category_description,
                product_family_description,
                start_date,
                expiration_date,
                cart_item_bundle_id,
                item_hierarchy_id,
                dependent_cart_order_itemid,
                keycode,
                discount,
                cart_discount_method_id,
                cart_discount_id,
                storage_gb, 
                usage_pricing_model_id, 
                retention_model_id, 
                retention_term, 
                retention_model_name, 
                actual_storage_quantity 
            )
            EXEC usp_cart_select_license_configurator_pricing @item_json, @bundle_json

            UPDATE c
            SET c.license_id = l.license_id,
                c.list_price_total = list_price * quantity,
                c.unit_price_total = unit_price * quantity,
                c.json_call = 'EXEC usp_cart_select_license_configurator_pricing ''' + @item_json + ''', '''
                              + @bundle_json + ''''
            FROM @cart_select_license_configurator_pricing c
                INNER JOIN dbo.license l
                    ON c.keycode = l.keycode

            --SELECT json_call
            --FROM @cart_select_license_configurator_pricing

            UPDATE r
            SET retail_price = c.list_price_total,
                net_price = c.unit_price_total,
                discount = c.list_price_total - c.unit_price_total,
                r.json_call = c.json_call
            FROM #recs r
                INNER JOIN @cart_select_license_configurator_pricing c
                    ON c.license_id = r.license_id
            WHERE r.license_id=@license_id
			
        END

        SET @rec_id = @rec_id + 1

        SET @keycode = NULL
        SET @license_category_name = NULL
        SET @seats = NULL
        SET @storage = NULL
        SET @years = NULL
        SET @cart_discount_id = NULL

        SET @retail_price = 0.00
        SET @net_price = 0.00

        SET @sky_license_seats = NULL
        SET @license_distribution_method_code = NULL

    END --while loop

    --select *
    --from #recs

    --UPDATE CATEGORY on legacy categories

    UPDATE r
    SET r.license_category_id = etlcu.license_category_upgrade_id,
        r.license_category_name = lc.license_category_name
    FROM #recs r
   
     INNER JOIN exact_target_license_category_upgrade etlcu
            ON r.license_category_id = etlcu.license_category_id
        INNER JOIN license_category lc
            ON etlcu.license_category_upgrade_id = lc.license_category_id


    DECLARE @sky_license_activity TABLE
    (
        license_id INT,
        Threats_removed INT,
        Scan_count INT,
        avg_scan_duration BIGINT,
        last_scan_date DATETIME,
        latest_threat VARCHAR(4000)
    )

    INSERT INTO @sky_license_activity
    (
        license_id,
        Threats_removed,
        Scan_count,
        avg_scan_duration,
        last_scan_date,
        latest_threat
    )
    SELECT sla.license_id,
           sla.threats_removed,
           sla.scan_count,
           CONVERT(BIGINT, sla.avg_scan_duration / 60000) avg_scan_duration,
           sla.last_scan_date,
           REPLACE(sla.latest_threat, '|', '-') latest_threat
    FROM
    (
        SELECT sla.license_id,
               MAX(sla.last_scan_date) last_scan_date
        FROM #recs r
		INNER JOIN sky_license_activity sla
        ON sla.license_id = r.license_id
        GROUP BY sla.license_id
    ) g1
        INNER JOIN sky_license_activity sla
            ON g1.license_id = sla.license_id
               AND g1.last_scan_date = sla.last_scan_date

    --select *
    --from @sky_license_activity

    --select '@Campaign_Prefix' = @Campaign_Prefix
    --select '#recs', * from #recs

	DROP TABLE IF EXISTS #return
    create TABLE #RETURN
    (
        return_id INT IDENTITY(1, 1) PRIMARY KEY,
        license_id INT,
        campaign NVARCHAR(50),
        class NVARCHAR(50),
        customer_email NVARCHAR(100),
        first_name NVARCHAR(255),
        last_name NVARCHAR(255),
        license_category_description NVARCHAR(100),
        ATTR_STRING13 NVARCHAR(10),
        activation NVARCHAR(255),
        expiration NVARCHAR(255),
        encypted NVARCHAR(100),
        keycode NVARCHAR(40),
        declared_interest1 NVARCHAR(64),
        geo NVARCHAR(255),
        region NVARCHAR(75),
        language NVARCHAR(100),
        country NVARCHAR(92),
        attr_num18_OptOffers NVARCHAR(30),
        attr_num19_OptUpdates NVARCHAR(30),
        attr_num20_OptNews NVARCHAR(30),
        discount NVARCHAR(50),
        invoicecode NVARCHAR(30),
        price NVARCHAR(50),
        ProductVersion NVARCHAR(20),
        message_key NVARCHAR(40),
        specials_code NVARCHAR(14),
        URL NVARCHAR(1000),
        DiscountAmount NVARCHAR(255),
        RetailPrice NVARCHAR(255),
        NetPrice NVARCHAR(255),
        max_threats_removed NVARCHAR(10),
        number_scans NVARCHAR(10),
        average_scan_time NVARCHAR(10),
        time_protected NVARCHAR(20),
        Latest_Threat NVARCHAR(4000),
        Last_Scan_date NVARCHAR(255),
        message_service_type_id INT,
        exact_target_batch_id INT,
        customer_id INT,
        person_id INT,
        has_account VARCHAR(10),
        has_wsa VARCHAR(10),
        has_idp VARCHAR(10),
        user_guid VARCHAR(40),
		license_distribution_method_code VARCHAR(4),
		attr_add_field1 VARCHAR(100),
		attr_add_field2 VARCHAR(100),
		attr_add_field3 VARCHAR(100),
		attr_add_field4 VARCHAR(100),
		attr_add_field5 VARCHAR(100),
		message_measure_point_id INT,
		license_category_id INT,
		message_campaign_id INT
    )

    IF @Campaign_Prefix <> 'SMB'
    BEGIN
        INSERT INTO #return
        (
            campaign,
            class,
            customer_email,
            first_name,
            last_name,
            license_category_description,
            ATTR_STRING13,
            activation,
            expiration,
            encypted,
            keycode,
            declared_interest1,
            region,
            language,
            country,
            attr_num18_OptOffers,
            attr_num19_OptUpdates,

            attr_num20_OptNews,
            discount,
            invoicecode,
            price,
            ProductVersion,
            message_key,
            specials_code,
            URL,
            DiscountAmount,
            RetailPrice,
            NetPrice,
            max_threats_removed,
            number_scans,
            average_scan_time,
            time_protected,
            Latest_Threat,
            Last_Scan_date,
            has_account,
            has_wsa,
            has_idp,
            user_guid,
			license_distribution_method_code
        )
        SELECT DISTINCT 
               LEFT(etmc.message_campaign_exact_target_name, 50) campaign,
               LEFT(etc.exact_target_class, 30) class,
               LEFT(ce.customer_email, 100) customer_email,
               c.first_name,
               c.last_name,
               CASE
                   WHEN s.license_distribution_method_id = 1036 THEN
                       'Webroot SecureAnywhere Small Business AntiVirus'
                   ELSE
                       LEFT(lcat.license_category_description, 100)
               END license_category_description,                                         -- ATTR_STRING11,
               CONVERT(NVARCHAR(10), s.license_seats) AS ATTR_STRING13,                  --oi.product_id,  --not used
               CONVERT(VARCHAR(10), etl.capability_activation_date, 20) activation,        --ATTR_DATE3
               CONVERT(VARCHAR(10), s.capability_expiration_date, 20) expiration,        --ATTR_DATE1
                                                                                         --ISNULL(FORMAT(s.capability_activation_date,cu.country_date_format),'') activation,	--ATTR_DATE3
                                                                                         --ISNULL(FORMAT(s.capability_expiration_date,cu.country_date_format),'') expiration,	--ATTR_DATE1
               LEFT([dbo].[fn_KeycodeEncrypt](s.keycode), 100) encypted,                 --[ATO_PASSWORD]
               LEFT(s.keycode, 40) keycode,                                              --[DECLARED_INTEREST2]
               '' declared_interest1,
               LEFT(r.location_code, 75) region,                                         --[REGION]
               LEFT(r.language_code, 100) language,
               LEFT(r.location_code, 92) country,
               '' AS attr_num18_OptOffers,
               '' AS attr_num19_OptUpdates,
               '' AS attr_num20_OptNews,
               ISNULL(LEFT(cdsm.specials_code, 50), '') discount,
               '' invoicecode,
               CONVERT(VARCHAR(50), r.net_price, 0) price,
               '8.0' ProductVersion,
               LEFT(s.license_key, 40) message_key,
               ISNULL(LEFT(cdsm.specials_code, 14), '') specials_code,
               CASE
                   WHEN etc.exact_target_class = 'Security Summary'
                        OR etc.exact_target_class = 'SMB Security Summary' THEN
                       CASE
                           WHEN b.exact_target_master_id IN ( 98, 118, 146 ) THEN --US Security Summary
                               'http://www.webroot.com/us/en/home/resources/security-report?key='
                               + LEFT(s.license_key, 40)
                           WHEN b.exact_target_master_id = 121 THEN --Japan Security Summary
                               'http://www.webroot.com/jp/ja/home/resources/security-report?key='
                               + LEFT(s.license_key, 40)
                           WHEN b.exact_target_master_id IN ( 134, 135 ) THEN --SMB Security Summary or SMB Security Trial Summary
                               'https://www.webroot.com/us/en/business/resources/security-report?key='
                               + LEFT(s.license_key, 40)
                       END
                   ELSE
                       CASE
                           WHEN cd.cart_di
scount_key IS NULL THEN
                               CASE
                                   WHEN b.exact_target_master_id IN ( 147, 148, 149, 154, 155, 156 ) THEN
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key)
                                   ELSE
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key)
                                       + '&routing_action=billing'
                               END
                           ELSE
                               CASE
                                   WHEN b.exact_target_master_id IN ( 147, 148, 149, 154, 155, 156 ) THEN
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key) + '&cart_discount_key='
                                       + CONVERT(VARCHAR(50), cd.cart_discount_key)
                                   ELSE
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key) + '&cart_discount_key='
                                       + CONVERT(VARCHAR(50), cd.cart_discount_key) + '&routing_action=billing'
                               END
                       END
               END URL,
               FORMAT(r.discount, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) DiscountAmount,
               FORMAT(r.retail_price, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) RetailPrice,
               FORMAT(r.net_price, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) NetPrice,
               ISNULL(lsl.bad_scans, 0) max_threats_removed,
                                                                                         --isnull(sla.Threats_removed,0) max_threats_removed,
               ISNULL(sla.Scan_count, 0) number_scans,
               ISNULL(sla.avg_scan_duration, 0) average_scan_time,
               '' time_protected,
               ISNULL(sla.latest_threat, '') Latest_Threat,
               ISNULL(CONVERT(VARCHAR(10), sla.last_scan_date, 101), '') Last_Scan_date, --09/10/2015
                                                                                         --ISNULL(FORMAT(sla.Last_Scan_date,cu.country_date_format),'') Last_Scan_date
               CASE
                   WHEN has_account = 1 THEN
                       'Yes'
                   ELSE
                       'No'
               END has_account,
               CASE
                   WHEN has_wsa = 1 THEN
                       'Yes'
                   ELSE
                       'No'
               END has_wsa,
               CASE
                   WHEN has_idp = 1 THEN
                       'Yes'
                   ELSE
                       'No'
               END has_idp,
               ISNULL(CONVERT(VARCHAR(40), sa.safe_account_user_guid), '')  ,             --UserGuid
			   r.license_distribution_method_code
        FROM #recs r
            INNER JOIN #exact_target_batch_data b
			ON b.exact_target_batch_id = r.exact_target_batch_id
            INNER JOIN message_campaign mc
                ON b.message_campaign_id = mc.message_campaign_id
            INNER JOIN exact_target_message_campaign etmc
                ON b.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
            INNER JOIN exact_target_class etc
                ON etmc.exact_target_class_id = etc.exact_target_class_id
            LEFT JOIN cart_discount cd

                ON b.cart_discount_id = cd.cart_discount_id
            LEFT JOIN cart_discount_specials_mapping cdsm
                ON b.cart_discount_id = cdsm.cart_discount_id
            INNER JOIN license_summary s
                ON b.license_id = s.license_id
            INNER JOIN customer c
                ON b.customer_id = c.customer_id
            INNER JOIN customer_email ce
                ON b.customer_id = ce.customer_id
                   AND ce.email_status_id = 1
            INNER JOIN license_category lcat
                ON r.license_category_id = lcat.license_category_id
            LEFT JOIN @sky_license_activity sla
                ON b.license_id = sla.license_id
            LEFT JOIN dbo.license_scan_license lsl
                ON b.license_id = lsl.license_id
            LEFT JOIN dbo.currency_language_location cll
                ON cll.location_code = r.location_code
                   AND cll.language_code = r.language_code
            LEFT JOIN dbo.lu_countries cu
                ON r.location_code = cu.iso3
            LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate
                ON allstate.license_id = b.license_id
            LEFT JOIN dbo.safe_account_user_customer sa
                ON sa.customer_id = b.customer_id
			LEFT JOIN dbo.exact_target_license_activation etl
				ON etl.license_id = b.license_id
			
        SELECT return_id,
               campaign,
               class,
               customer_email,
               first_name,
               last_name,
               license_category_description,
               ATTR_STRING13,
               activation,
               expiration,
               encypted,
               keycode,
               declared_interest1,
               region,
               language,
               country,
               attr_num18_OptOffers,
               attr_num19_OptUpdates,
               attr_num20_OptNews,
               discount,
               invoicecode,
               price,
               ProductVersion,
               message_key,
               specials_code,
               URL,
               DiscountAmount,
               RetailPrice,
               NetPrice,
               max_threats_removed,
               number_scans,
               average_scan_time,
               time_protected,
               Latest_Threat,
               Last_Scan_date,
               has_account,
               has_wsa,
               has_idp,
               user_guid,
			   license_distribution_method_code,
			   attr_add_field1,
			   attr_add_field2,
			   attr_add_field3,
			   attr_add_field4,
			   attr_add_field5
        FROM #return
        ORDER BY campaign

    END
    ELSE --SMB/300
    BEGIN

	
        INSERT INTO #return
        (
            license_id,
            campaign,
            class,
            customer_email,
            first_name,
            last_name,
            license_category_description,
            ATTR_STRING13,
            activation,
            expiration,
            encypted,
            keycode,
            declared_interest1,
            geo,
            region,
            language,
            country,
            attr_num18_OptOffers,
            attr_num19_OptUpdates,
            attr_num20_OptNews,
            discount,
            invoicecode,
            price,
            ProductVersion,
            message_key,
            specials_code,
            URL,
            DiscountAmount,
            RetailPrice,
            NetPrice,
            max_threats_removed,
            number_scans,
            average_scan_time,
            time_protected,
            Latest_Threat,
            Last_Scan_date,
            message_service_type_id,
            exact_target_batch_id,
            customer_id,
            person_id,
            message_measure_point_id,
      
      license_category_id,
            message_campaign_id
        )
        SELECT DISTINCT 
               r.license_id,
               LEFT(etmc.message_campaign_exact_target_name, 50) campaign,
               LEFT(etc.exact_target_class, 30) class,
               LEFT(ce.customer_email, 100) customer_email,
               c.first_name,
               c.last_name,
               LEFT(lcat.license_category_description, 100) license_category_description, -- ATTR_STRING11,
               CONVERT(NVARCHAR(10), s.license_seats) AS ATTR_STRING13,                   --oi.product_id,  --not used
               CONVERT(VARCHAR(10), s.capability_activation_date, 20) activation,         --ATTR_DATE3
               CONVERT(VARCHAR(10), s.capability_expiration_date, 20) expiration,         --ATTR_DATE1
                                                                                          --ISNULL(FORMAT(s.capability_activation_date,cu.country_date_format),'') activation,	--ATTR_DATE3
                                                                                          --ISNULL(FORMAT(s.capability_expiration_date,cu.country_date_format),'') expiration,	--ATTR_DATE1
               LEFT([dbo].[fn_KeycodeEncrypt](s.keycode), 100) encypted,                  --[ATO_PASSWORD]
               LEFT(s.keycode, 40) keycode,                                               --[DECLARED_INTEREST2]
               '' declared_interest1,
               sg.geography_name geo,
               LEFT(r.location_code, 75) region,                                          --[REGION]
               LEFT(r.language_code, 100) language,
               LEFT(r.location_code, 92) country,
               ISNULL(b.email_type, '') AS attr_num18_OptOffers,
               lc.license_channel_name AS attr_num19_OptUpdates,
               '' AS attr_num20_OptNews,
               ISNULL(LEFT(cdsm.specials_code, 50), '') discount,
               '' invoicecode,
               CONVERT(VARCHAR(50), r.net_price, 0) price,
               '8.0' ProductVersion,
               LEFT(s.license_key, 40) message_key,
               ISNULL(LEFT(cdsm.specials_code, 14), '') specials_code,
               CASE
                   WHEN etc.exact_target_class = 'SMB Security Summary' THEN
                       CASE
                           WHEN b.exact_target_master_id IN ( 134, 135 ) THEN --US Security Summary
                               'https://www.webroot.com/us/en/business/resources/security-report?key='
                               + LEFT(s.license_key, 40)
                       END
                   ELSE
                       --SDNS/WSAT Campaigns can't push to billing

                       CASE
                           WHEN cd.cart_discount_key IS NULL THEN
                               CASE
                                   WHEN b.exact_target_master_id IN ( 147, 148, 149, 154, 155, 156 ) THEN
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key)
                                   ELSE
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key)
                                       + '&routing_action=billing'
                               END
                           ELSE
                               CASE
                                   WHEN b.exact_target_master_id IN ( 147, 148, 149, 154, 155, 156 ) THEN
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key) + '&cart_discount_key='
                                       + CONVERT(VARCHAR(50), cd
.cart_discount_key)
                                   ELSE
                                       'https://www.webroot.com/' + LOWER(r.iso) + '/' + LOWER(r.language_code)
                                       + '/cart/update?key=' + CONVERT(VARCHAR(50), s.license_key) + '&cart_discount_key='
                                       + CONVERT(VARCHAR(50), cd.cart_discount_key) + '&routing_action=billing'
                               END
                       END
               END URL,
               FORMAT(r.discount, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) DiscountAmount,
               FORMAT(r.retail_price, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) RetailPrice,
               FORMAT(r.net_price, 'C', ISNULL(cll.language_code, 'EN') + '-' + ISNULL(cu.iso, 'US')) NetPrice,
               ISNULL(lsl.bad_scans, 0) max_threats_removed,
                                                                                          --isnull(sla.Threats_removed,0) max_threats_removed,
               ISNULL(sla.Scan_count, 0) number_scans,
               ISNULL(sla.avg_scan_duration, 0) average_scan_time,
               '' time_protected,
               ISNULL(sla.latest_threat, '') Latest_Threat,
                                                                                          --ISNULL(FORMAT(sla.Last_Scan_date,cu.country_date_format),'') Last_Scan_date,
               ISNULL(CONVERT(VARCHAR(10), sla.last_scan_date, 101), '') Last_Scan_date,  --09/10/2015
               etmc.message_service_type_id,
               b.exact_target_batch_id,
               c.customer_id,
               c.person_id,
               b.message_measure_point_id,
               r.license_category_id,
               mc.message_campaign_id
		FROM #recs r
          INNER JOIN #exact_target_batch_data b
			ON b.exact_target_batch_id = r.exact_target_batch_id
            INNER JOIN message_campaign mc
                ON b.message_campaign_id = mc.message_campaign_id
            INNER JOIN exact_target_message_campaign etmc
                ON b.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
            INNER JOIN exact_target_class etc
                ON etmc.exact_target_class_id = etc.exact_target_class_id
            LEFT JOIN cart_discount cd
                ON b.cart_discount_id = cd.cart_discount_id
            LEFT JOIN cart_discount_specials_mapping cdsm
                ON b.cart_discount_id = cdsm.cart_discount_id
            INNER JOIN license_summary s
                ON b.license_id = s.license_id
            INNER JOIN customer c
                ON b.customer_id = c.customer_id
            INNER JOIN customer_email ce
                ON b.customer_id = ce.customer_id
                   AND ce.email_status_id = 1
            INNER JOIN license_category lcat
                ON r.license_category_id = lcat.license_category_id
            LEFT JOIN license_channel_license lcl
                ON b.license_id = lcl.license_id
            LEFT JOIN license_channel lc
                ON lcl.license_channel_id = lc.license_channel_id
            LEFT JOIN @sky_license_activity sla
                ON b.license_id = sla.license_id
            LEFT JOIN dbo.license_scan_license lsl
                ON b.license_id = lsl.license_id
            LEFT JOIN dbo.currency_language_location cll
                ON cll.location_code = r.location_code
                   AND cll.language_code = r.language_code
            LEFT JOIN dbo.lu_countries cu
                ON r.location_code = cu.iso3
            LEFT JOIN sfdc_geography_country sgc
                ON cu.country_id = sgc.country_id
            LEFT JOIN dbo.sfdc_geography sg
                ON sg.sfdc_geography_id = sgc.sfdc_geography_id
			
        --message_service insert
        SELECT @return_id = MIN(return_id),
               @max_return_id = MAX(return_id)
 
       FROM #return

        --select '@return_id' = @return_id, '@max_return_id' = @max_return_id
        --select * FROM #return
        --RETURN 

        WHILE @return_id <= @max_return_id
        BEGIN

            --insert into message_service get message_service_id
            --insert json into message_service_log_json

            SELECT @message_service_type_id = r.message_service_type_id,
                   @customer_email = r.customer_email,
                   @license_id = r.license_id,
                   @child_license_category_id = r.license_category_id,
                   @message_campaign_id = r.message_campaign_id
            FROM #return r
                INNER JOIN message_service_type mst
                    ON r.message_service_type_id = mst.message_service_type_id
            WHERE return_id = @return_id

            INSERT INTO dbo.message_service
            (
                message_service_type_id,
                message_service_client_id,
                message_service_status_id,
                customer_email,
                insert_date,
                process_date,
                update_attempts,
                insert_by,
                last_modified_date,
                last_modified_by
            )
            VALUES
            (   @message_service_type_id,  -- message_service_type_id - int
                2,                         -- message_service_client_id - int
                1,                         -- message_service_status_id - int
                                           --'KMaduru@webroot.com',
                                           --'MSanderson' + CONVERT(VARCHAR(25),@license_id) + '@postfix.saasqa.webroot.com', --@customer_email,        
                @customer_email,           -- varchar(100)
                GETDATE(),                 -- insert_date - datetime
                CAST(@date_value AS DATE), -- process_date - datetime
                0,                         -- update_attempts - tinyint
                SYSTEM_USER,               -- insert_by - varchar(20)
                GETDATE(),                 -- last_modified_date - datetime
                SYSTEM_USER                -- last_modified_by - varchar(20)
                )

            SET @message_service_id = SCOPE_IDENTITY()

            --SELECT @message_service_id
            --RETURN 

            --IF @message_service_type_id = 7 --business_trial
            --	BEGIN
            --		--PRINT ' @message_service_type_id = 7'

            --		SELECT @message_service_json = (SELECT exact_target_batch_id business_trial_message_id,
            --			@message_service_id message_service_id,
            --			customer_id,
            --			person_id,
            --			campaign,
            --			customer_email,
            --			first_name,
            --			last_name,
            --			license_category_description,
            --			ATTR_STRING13 license_seats,
            --			activation,
            --			expiration,
            --			encypted encypted_keycode,
            --			keycode,
            --			geo,
            --			language,
            --			country,
            --			attr_num18_OptOffers email_type,
            --			attr_num19_OptUpdates license_channel_name,
            --			discount,
            --			message_key license_key,
            --			URL,
            --			DiscountAmount discount_amount,
            --			RetailPrice retail_price,
            --			NetPrice net_price,
            --			max_threats_removed,
            --			number_scans,
            --			average_scan_time,
            --			Latest_Threat latest_threat,
            --			Last_Scan_date last_scan_date
            --		FROM @return
            --		WHERE return_id = @return_id
            --		FOR json path,  INCLUDE_NULL_VALUES)
            --	END 


            IF @message_service_type_id IN ( 7, 9, 14 ) --business_renewal_MSP, business_on
boarding
            BEGIN
                --PRINT ' @message_service_type_id = 9 or 14'

                SELECT @license_id = r.license_id
                FROM #return r
                WHERE return_id = @return_id

				IF @message_measure_point_id = 8 --Parent License Receives Child Count w/Expiration
				BEGIN

					SELECT @child_capability_type_id =
						   CASE mccl.dimension_value
								WHEN 0 THEN 1   --full
								WHEN 1 THEN 2	--trial
								ELSE NULL
						   END
					FROM dbo.message_campaign_child_license mccl
					WHERE mccl.message_campaign_id = @message_campaign_id
					  AND mccl.dimension_type = 'child-capability-type';

					INSERT INTO @child_licenses
					(
						etbc.etbc.parent_license_id,
						etbc.child_license_id,
						etbc.license_category_name,
						etbc.c.license_category_description,
						etbc.capability_type_description,
						etbc.capability_expiration_date
					)
					SELECT etbc.parent_license_id,
						   etbc.child_license_id,
						   lc.license_category_name,
						   lc.license_category_description,
						   ct.capability_type_description,
						   etbc.capability_expiration_date
					FROM dbo.exact_target_batch_children etbc
						INNER JOIN dbo.license_category lc
							ON lc.license_category_id = etbc.license_category_id
						INNER JOIN dbo.capability_type ct
							ON ct.capability_type_id = etbc.capability_type_id
					WHERE etbc.parent_license_id = @license_id
						  AND etbc.license_category_id = @child_license_category_id
						  AND etbc.capability_type_id = @child_capability_type_id
					ORDER BY etbc.parent_license_id DESC;
				END
                        
                DECLARE @license_profile TABLE
                (
                    item_id INT,
                    license_id INT,
                    license_category_name VARCHAR(10),
                    license_category_description VARCHAR(255),
                    license_seats INT,
                    storage_gb INT,
                    license_keycode_type_id INT,
                    start_date DATETIME,
                    expiration_date DATETIME,
                    license_attribute_id INT,
                    license_attribute_description VARCHAR(150),
                    license_attribute_license_value VARCHAR(150),
                    license_attribute_license_value_description VARCHAR(150),
                    category_type_name VARCHAR(50),
                    item_hierarchy_id TINYINT,
                    item_hierarchy_name VARCHAR(50),
                    license_status_id INT,
                    license_status_description VARCHAR(150),
                    autorenewal_cycle_name VARCHAR(50),
                    autorenewal_cycle DECIMAL(18, 3)
                )

                INSERT INTO @license_profile
                (
                    item_id,
                    license_id,
                    license_category_name,
                    license_seats,
                    storage_gb,
                    license_keycode_type_id,
                    start_date,
                    expiration_date,
                    license_attribute_id,
                    license_attribute_description,
                    license_attribute_license_value,
                    license_attribute_license_value_description,
                    category_type_name,
                    item_hierarchy_id,
                    license_status_id,
                    license_status_description,
                    autorenewal_cycle_name,
                    autorenewal_cycle
                )
                SELECT item_id,
                       license_id,
                       f.license_category_name,
                       license_seats,
                       storage_gb,
                       license_keycode_type_id,
                       start_date,
                       expiration_date,
                   
    license_attribute_id,
                       license_attribute_description,
                       license_attribute_license_value,
                       license_attribute_license_value_description,
                       category_type_name,
                       item_hierarchy_id,
                       license_status_id,
                       license_status_description,
                       autorenewal_cycle_name,
                       autorenewal_cycle
                FROM dbo.fn_license_select_license_profile(@license_id) f

                UPDATE lp
                SET lp.license_category_description = lc.license_category_description
                FROM @license_profile lp
                    LEFT JOIN dbo.license_category lc
                        ON lc.license_category_name = lp.license_category_name

                --INSERT INTO @license_profile
                --(
                --    item_id,
                --    license_id,
                --    license_category_name,
                --    license_category_description,
                --    license_seats,
                --    storage_gb,
                --    license_keycode_type_id,
                --    start_date,
                --    expiration_date,
                --    license_attribute_id,
                --    license_attribute_description,
                --    license_attribute_license_value,
                --    license_attribute_license_value_description,
                --    category_type_name,
                --    item_hierarchy_id,
                --    item_hierarchy_name,
                --    license_status_id,
                --    license_status_description,
                --    autorenewal_cycle_name,
                --    autorenewal_cycle
                --)
                --EXEC usp_cart_select_license_profile @license_id

                SELECT @order_header_id = MAX(oh.order_header_id) -- 
                FROM #return r
                    INNER JOIN dbo.order_item_license oil
                        ON r.license_id = oil.license_id
                    INNER JOIN dbo.order_item oi
                        ON oil.order_item_id = oi.order_item_id
                    INNER JOIN dbo.order_header oh
                        ON oi.order_header_id = oh.order_header_id
                WHERE r.return_id = @return_id

                DECLARE @order_company TABLE
                (
                    order_company_id INT,
                    order_header_id INT,
                    order_company_type_id TINYINT,
                    order_company_type_name VARCHAR(50),
                    order_company_type_description VARCHAR(50),
                    company_id INT,
                    company_name NVARCHAR(255),
                    salesforce_account_id VARCHAR(20),
                    customer_id INT
                )

                INSERT INTO @order_company
                EXEC usp_sfdc_select_order_company @order_header_id


                /*
									call usp_sfdc_select_order_company proc into json array
										order_company_type_id
										order_company_type_name
										order_company_type_description
										company_id
										company_name	renewal_opp_account_name_enduser1
										email_address	customer_email - download contact

									*/

                --URL,end_contact,Lang,Loc
                --order_company where order_company_type_id = 1 --> customer or customer_email on customer_id

                IF @message_service_type_id = 7
                BEGIN
                    SELECT @message_service_json
                        =
                    (
                        SELECT exact_target_batch_id business_trial_message_id,
                               @message_service_id message_service_id,
                               r.customer_id,
                               person_id,
                        
       campaign,
                               --'KMaduru@webroot.com' customer_email,
                               --'MSanderson' + CONVERT(VARCHAR(25),@license_id) + '@postfix.saasqa.webroot.com' customer_email,
                               customer_email,
                               first_name,
                               last_name,
                               encypted encypted_keycode,
                               keycode,
                               geo,
                               language lang,
                               country loc,
                               --attr_num18_OptOffers email_type,
                               --attr_num19_OptUpdates license_channel_name,
                               --discount,
                               message_key license_key,
                               DiscountAmount discount_amount,
                               RetailPrice retail_price,
                               NetPrice net_price,
                               ct.company_type_name end_account_type,
                               lcl.license_channel_id license_channel,
                               URL,
                    (
                        SELECT oc.order_company_type_id,
                               oc.order_company_type_name,
                               oc.order_company_type_description,
                               oc.company_name,
                               oc.company_id
                        FROM @order_company oc
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          company,
                    (
                        SELECT license_category_name,
                               license_category_description,
                               CAST(expiration_date AS DATE) capability_expiration_date,
                               CAST(start_date AS DATE) capability_activation_date,
                               --CONVERT(VARCHAR(10), expiration_date, 102) capability_expiration_date, --2019/10/01
                               --CONVERT(VARCHAR(10), start_date, 102) capability_activation_date,		--2019/10/01
                               UPPER(SUBSTRING(category_type_name, 1, 1)) + LOWER(SUBSTRING(category_type_name, 2, 50)) category_type_name,
                               license_seats
                        FROM @license_profile
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          license_category,
                    (
                        SELECT cl.license_category_description,
							cl.capability_type_description,
							CAST(cl.capability_expiration_date AS DATE) expiration_date,
							COUNT(*) number_of_licenses
                        FROM @child_licenses cl
                        INNER JOIN dbo.license_category lc 
                            ON lc.license_category_name = cl.license_category_name
						INNER JOIN dbo.capability_type ct
                            ON ct.capability_type_description = cl.capability_type_description
						WHERE cl.parent_license_id = @license_id
                            AND lc.license_category_id = @child_license_category_id
                            AND ct.capability_type_id = @child_capability_type_id
						GROUP BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
						ORDER BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    ) child_licenses
                        FROM #return r
                            LEFT JOIN customer_company cc
                                ON r.customer_id = cc.customer_id
                            LEFT JOIN dbo.company c
          
                      ON cc.company_id = c.company_id
                            LEFT JOIN company_type ct
                                ON c.company_type_id = ct.company_type_id
                            LEFT JOIN dbo.license_channel_license lcl
                                ON r.license_id = lcl.license_id
                        WHERE r.return_id = @return_id
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )
                END


                IF @message_service_type_id = 9
                BEGIN
                    SELECT @message_service_json
                        =
                    (
                        SELECT exact_target_batch_id business_renewal_MSP_message_id,
                               @message_service_id message_service_id,
                               r.customer_id,
                               person_id,
                               campaign,
                               --'KMaduru@webroot.com' customer_email,
                               --'MSanderson' + CONVERT(VARCHAR(25),@license_id) + '@postfix.saasqa.webroot.com' customer_email,
                               customer_email,
                               first_name,
                               last_name,
                               encypted encypted_keycode,
                               keycode,
                               geo,
                               language lang,
                               country loc,
                               --attr_num18_OptOffers email_type,
                               --attr_num19_OptUpdates license_channel_name,
                               --discount,
                               message_key license_key,
                               DiscountAmount discount_amount,
                               RetailPrice retail_price,
                               NetPrice net_price,
                               ct.company_type_name end_account_type,
                               lcl.license_channel_id license_channel,
                               URL,
                    (
                        SELECT oc.order_company_type_id,
                               oc.order_company_type_name,
                               oc.order_company_type_description,
                               oc.company_name,
                               oc.company_id
                        FROM @order_company oc
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          company,
                    (
                        SELECT license_category_name,
                               license_category_description,
                               CAST(expiration_date AS DATE) capability_expiration_date,
                               CAST(start_date AS DATE) capability_activation_date,
                               --CONVERT(VARCHAR(10), expiration_date, 102) capability_expiration_date, --2019/10/01
                               --CONVERT(VARCHAR(10), start_date, 102) capability_activation_date,		--2019/10/01
                               UPPER(SUBSTRING(category_type_name, 1, 1)) + LOWER(SUBSTRING(category_type_name, 2, 50)) category_type_name,
                               license_seats
                        FROM @license_profile
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          license_category,
                    (
                        SELECT cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE) expiration_date,
                            COUNT(*) number_of_licenses
                        FROM @child_licenses cl
                        INNER JOIN dbo.license_category lc 
                            ON lc.license_category_name = cl.license_category_name
                        INNER JOIN dbo.capability_ty
pe ct
                            ON ct.capability_type_description = cl.capability_type_description
                        WHERE cl.parent_license_id = @license_id
                            AND lc.license_category_id = @child_license_category_id
                            AND ct.capability_type_id = @child_capability_type_id
                        GROUP BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
                        ORDER BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    ) child_licenses
                        FROM #return r
                            LEFT JOIN customer_company cc
                                ON r.customer_id = cc.customer_id
                            LEFT JOIN dbo.company c
                                ON cc.company_id = c.company_id
                            LEFT JOIN company_type ct
                                ON c.company_type_id = ct.company_type_id
                            LEFT JOIN dbo.license_channel_license lcl
                                ON r.license_id = lcl.license_id
                        WHERE r.return_id = @return_id
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )
                END

                IF @message_service_type_id = 14
                BEGIN
                    SELECT @message_service_json
                        =
                    (
                        SELECT exact_target_batch_id business_onboarding_message_id,
                               @message_service_id message_service_id,
                               r.customer_id,
                               person_id,
                               campaign,
                               --'KMaduru@webroot.com' customer_email,
                               --'MSanderson' + CONVERT(VARCHAR(25),@license_id) + '@postfix.saasqa.webroot.com' customer_email,
                               customer_email,
                               first_name,
                               last_name,
                               encypted encypted_keycode,
                               keycode,
                               geo,
                               language lang,
                               country loc,
                               --attr_num18_OptOffers email_type,
                               --attr_num19_OptUpdates license_channel_name,
                               --discount,
                               message_key license_key,
                               DiscountAmount discount_amount,
                               RetailPrice retail_price,
                               NetPrice net_price,
                               ct.company_type_name end_account_type,
                    (
                        SELECT oc.order_company_type_id,
                               oc.order_company_type_name,
                               oc.order_company_type_description,
                               oc.company_name,
                               oc.company_id
                        FROM @order_company oc
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          company,
                    (
                        SELECT license_category_name,
                               license_category_description,
                               CAST(expiration_date AS DATE) capability_expiration_date,
                               CAST(start_date AS DATE) capability_activation_date,
                               --CONVERT(VARCHAR(10), expiration_date, 102) capability_expiration_date, --2019/10/01
                               --CONVERT(VARC
HAR(10), start_date, 102) capability_activation_date,		--2019/10/01
                               UPPER(SUBSTRING(category_type_name, 1, 1)) + LOWER(SUBSTRING(category_type_name, 2, 50)) category_type_name,
                               license_seats
                        FROM @license_profile
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )          license_category,
                    (
                        SELECT cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE) expiration_date,
                            COUNT(*) number_of_licenses
                        FROM @child_licenses cl
                        INNER JOIN dbo.license_category lc 
                            ON lc.license_category_name = cl.license_category_name
                        INNER JOIN dbo.capability_type ct
                            ON ct.capability_type_description = cl.capability_type_description
                        WHERE cl.parent_license_id = @license_id
                            AND lc.license_category_id = @child_license_category_id
                            AND ct.capability_type_id = @child_capability_type_id
                        GROUP BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
                        ORDER BY cl.license_category_description,
                            cl.capability_type_description,
                            CAST(cl.capability_expiration_date AS DATE)
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    ) child_licenses
                        FROM #return r
                            LEFT JOIN customer_company cc
                                ON r.customer_id = cc.customer_id
                            LEFT JOIN dbo.company c
                                ON cc.company_id = c.company_id
                            LEFT JOIN company_type ct
                                ON c.company_type_id = ct.company_type_id
                        WHERE r.return_id = @return_id
                        FOR JSON PATH, INCLUDE_NULL_VALUES
                    )
                END
            END

            --PRINT @message_service_json

            INSERT INTO dbo.message_service_log_json
            (
                message_service_id,
                message_service_json,
                insert_date
            )
            VALUES
            (   @message_service_id,   -- message_service_id - int
                @message_service_json, -- message_service_json - varchar(max)
                GETDATE()              -- insert_date - datetime
                )


            DELETE FROM @order_company
            DELETE FROM @license_profile
            DELETE FROM @child_licenses


            SET @return_id = @return_id + 1
        END

    END




    UPDATE etb
    SET etb.exact_target_batch_status_id = 1
    FROM #recs rc
	INNER JOIN dbo.exact_target_batch etb
	ON etb.exact_target_batch_id = rc.exact_target_batch_id
	
END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'procedure failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_exact_target_message_update_allstate]
-- =============================================================================
CREATE    PROCEDURE [dbo].[usp_exact_target_message_update_allstate] (
	@exact_target_master_id INT
)
AS

BEGIN

	/*

		DATE		AUTHOR			REMARKS
		2022-09-13	gblandford		Initial creation
		2022-11-15	jberry			Removed EXISTS logic from around the final delete statement so the delete always happens
		
		DESCRIPTION
		Check for allstate specific criteria; has-idp, has-wsa, has-account - AIP-32

	*/
	
	SET NOCOUNT ON;

	DECLARE @message_campaign_id INT,
		@dimension_type VARCHAR(20);

	DECLARE @exact_target_subset3 TABLE (
		[exact_target_master_id] [int] NOT NULL,
		[license_id] [int] NOT NULL,
		[cart_discount_id] [int] NULL,
		[license_distribution_method_id] [int] NOT NULL,
		[license_category_id] [int] NOT NULL,
		[product_line_id] [int] NOT NULL,
		[opt_in] [int] NOT NULL,
		[autorenewal_opt_id] [int] NOT NULL,
		[capability_type_id] [int] NOT NULL,
		[license_seats] [int] NOT NULL
	);

	SELECT @message_campaign_id = message_campaign_id
	FROM dbo.exact_target_master 
	WHERE exact_target_master_id = @exact_target_master_id

	INSERT INTO @exact_target_subset3 (
		exact_target_master_id,
		license_id,
		cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats
	)
	SELECT
		exact_target_master_id,
		license_id,
		cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats
	FROM dbo.exact_target_subset3 ets3
	WHERE ets3.exact_target_master_id = @exact_target_master_id;



	/*
	| 
	| Check if we have Allstate criteria filter results
	|
	*/
	IF EXISTS (SELECT 1 FROM dbo.message_campaign_allstate mca WHERE mca.message_campaign_id = @message_campaign_id)
		BEGIN

			DECLARE @exact_allstate TABLE (exact_allstate_id INT IDENTITY(1, 1), license_id INT, dimension_type VARCHAR(20));

			/*
			|
			| has_account
			|
			*/
			SET @dimension_type = 'has-account'
			IF EXISTS(select 1 from dbo.message_campaign_allstate mca
							where mca.message_campaign_id = @message_campaign_id
							and mca.dimension_type = @dimension_type)
				BEGIN
					INSERT INTO @exact_allstate	(
						license_id,
						dimension_type
					)
					SELECT
						b.license_id
						, @dimension_type
					FROM @exact_target_subset3 b
					LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate
						ON b.license_id = allstate.license_id
					WHERE b.exact_target_master_id = @exact_target_master_id
					AND allstate.has_account IN (SELECT dimension_value
													FROM dbo.message_campaign_allstate
													WHERE message_campaign_id = @message_campaign_id
													AND dimension_type = @dimension_type)

					DELETE ets
					FROM @exact_target_subset3 ets
					LEFT JOIN @exact_allstate allstate ON allstate.license_id = ets.license_id AND allstate.dimension_type = @dimension_type
					WHERE ets.exact_target_master_id = @exact_target_master_id
					AND allstate.exact_allstate_id IS NULL

				END

			/*
			|
			| has_wsa
			|
			*/
			SET @dimension_type = 'has-wsa'
			IF EXISTS(select 1 from dbo.message_campaign_allstate mca
							where mca.message_campaign_id = @message_campaign_id
							and mca.dimension_type = @dimension_type)
				BEGIN
					INSERT INTO @exact_allstate	(
						license_id,
						dimension_type
					)
					SELECT
						b.license_id
						, @dimension_type
					FROM @exact_target_subset3 b
					LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate
						ON b.license_id = allstate.license_id
					WHERE b.exact_target_master_id = @exact_target_master_id
			
		AND allstate.has_wsa IN (SELECT dimension_value
													FROM dbo.message_campaign_allstate
													WHERE message_campaign_id = @message_campaign_id
													AND dimension_type = @dimension_type)
					DELETE ets
					FROM @exact_target_subset3 ets
					LEFT JOIN @exact_allstate allstate ON allstate.license_id = ets.license_id AND allstate.dimension_type = @dimension_type
					WHERE ets.exact_target_master_id = @exact_target_master_id
					AND allstate.exact_allstate_id IS NULL
				END

			/*
			|
			| has_idp
			|
			*/
			SET @dimension_type = 'has-idp'
			IF EXISTS(select 1 from dbo.message_campaign_allstate mca
							where mca.message_campaign_id = @message_campaign_id
							and mca.dimension_type = @dimension_type)
				BEGIN
					INSERT INTO @exact_allstate	(
						license_id,
						dimension_type
					)
					SELECT
						b.license_id
						, @dimension_type
					FROM @exact_target_subset3 b
					LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate
						ON b.license_id = allstate.license_id
					WHERE b.exact_target_master_id = @exact_target_master_id
					AND allstate.has_idp IN (SELECT dimension_value
													FROM dbo.message_campaign_allstate
													WHERE message_campaign_id = @message_campaign_id
													AND dimension_type = @dimension_type)
					DELETE ets
					FROM @exact_target_subset3 ets
					LEFT JOIN @exact_allstate allstate ON allstate.license_id = ets.license_id AND allstate.dimension_type = @dimension_type
					WHERE ets.exact_target_master_id = @exact_target_master_id
					AND allstate.exact_allstate_id IS NULL
				END

			/*
			|
			| Remove 
			|
			*/
	
				DELETE ets
				FROM dbo.exact_target_subset3 ets
				LEFT JOIN @exact_target_subset3 t ON t.exact_target_master_id = ets.exact_target_master_id AND ets.license_id = t.license_id
				WHERE t.license_id IS NULL

		END
END

GO
