-- PROCEDURE: [dbo].[usp_exact_target_message_update_child_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_exact_target_message_update_child_license] (
	@exact_target_master_id INT
)
AS

BEGIN

	/*

		DATE		AUTHOR		REMARKS
		2026-01-09	gblandford	US-5060635 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5060635
								- Initial creation
		2026-01-26	jberry		US-5164326 Added sections to remove records not matching on supported dimension types
		2026-04-30	jberry		US-5359090 Added conversion for child capability type to convert 0 to 1 for full and 1 to 2 for trials

		DESCRIPTION
		Applies child license campaign criteria to the exact target subset3
		Dimensions for child license criteria are stored in dbo.message_campaign_child_license
		Currently supported dimension types are:
			
			child-capabilty-type 
			child-license-category


	*/
	
	SET NOCOUNT ON;

	DECLARE @message_campaign_id INT,
		@dimension_type VARCHAR(100);

	DECLARE @exact_target_subset3 TABLE (
		exact_target_master_id INT NOT NULL,
		license_id INT NOT NULL,
		cart_discount_id INT NULL,
		license_distribution_method_id INT NOT NULL,
		license_category_id INT NOT NULL,
		product_line_id INT NOT NULL,
		opt_in INT NOT NULL,
		autorenewal_opt_id INT NOT NULL,
		capability_type_id INT NOT NULL,
		license_seats INT NOT NULL
	);

	SELECT @message_campaign_id = message_campaign_id
	FROM dbo.exact_target_master 
	WHERE exact_target_master_id = @exact_target_master_id

	INSERT INTO @exact_target_subset3 (
		exact_target_master_id,
		license_id,
		cart_discount_id,
		license_distribution_method_id,
		license_category_id,
		product_line_id,
		opt_in,
		autorenewal_opt_id,
		capability_type_id,
		license_seats
	)
	SELECT
		ets3.exact_target_master_id,
		ets3.license_id,
		ets3.cart_discount_id,
		ets3.license_distribution_method_id,
		ets3.license_category_id,
		ets3.product_line_id,
		ets3.opt_in,
		ets3.autorenewal_opt_id,
		ets3.capability_type_id,
		ets3.license_seats
	FROM dbo.exact_target_subset3 ets3
	INNER JOIN dbo.license_summary ls ON ls.license_id = ets3.license_id
	WHERE ets3.exact_target_master_id = @exact_target_master_id;

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- check if we have child license criteria & filter results
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	IF EXISTS ( SELECT 1 FROM dbo.message_campaign_child_license mccl WHERE mccl.message_campaign_id = @message_campaign_id )
		BEGIN

			DECLARE @exact_child_license TABLE (
				license_id INT,
				license_category_id INT,
				capability_type_id INT,
				dimension_type VARCHAR(100)
			);

			--delete records matching on child-license-category
			SET @dimension_type = 'child-license-category'

			IF EXISTS(SELECT 1 FROM dbo.message_campaign_child_license mccl
							WHERE mccl.message_campaign_id = @message_campaign_id
							AND mccl.dimension_type = @dimension_type)
				BEGIN

					INSERT INTO @exact_child_license(
						license_id,
						license_category_id,
						capability_type_id,
						dimension_type
					)
					SELECT
						b.license_id,
						b.license_category_id,
						b.capability_type_id,
						@dimension_type
					FROM @exact_target_subset3 b
					INNER JOIN dbo.exact_target_master etm 
						ON etm.exact_target_master_id = b.exact_target_master_id
					INNER JOIN dbo.message_campaign_child_license mccl 
						ON mccl.message_campaign_id = etm.message_campaign_id 
					WHERE mccl.dimension_type = @dimension_type
					AND b.lice
nse_category_id = mccl.dimension_value

					DELETE ets
					FROM @exact_target_subset3 ets
					LEFT JOIN @exact_child_license ecl
						ON ecl.license_id = ets.license_id
					WHERE ets.exact_target_master_id = @exact_target_master_id
					  AND
					  (
						  ecl.license_id IS NULL
						  OR NOT EXISTS
							 (
								 SELECT 1
								 FROM dbo.message_campaign_child_license mccl
								 WHERE mccl.dimension_type = @dimension_type
								   AND mccl.message_campaign_id = @message_campaign_id
								   AND mccl.dimension_value = ets.license_category_id
							 )
					  );
				END

			-- delete records matching on child-capability-type
			SET @dimension_type = 'child-capability-type'
			IF EXISTS(SELECT 1 FROM dbo.message_campaign_child_license mccl
							WHERE mccl.message_campaign_id = @message_campaign_id
							AND mccl.dimension_type = @dimension_type)
				BEGIN
					DELETE ets
					FROM @exact_target_subset3 AS ets
					WHERE ets.exact_target_master_id = @exact_target_master_id
					AND NOT EXISTS (
						SELECT 1
						FROM dbo.message_campaign_child_license AS mccl
						WHERE mccl.dimension_type = @dimension_type
						  AND mccl.message_campaign_id = @message_campaign_id
						  AND (
						      (mccl.dimension_value = 0 AND ets.capability_type_id = 1)
						          OR (mccl.dimension_value = 1 AND ets.capability_type_id = 2)
						      )
					);
				END			

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- Remove non matching records from subset3
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
			DELETE ets
			FROM dbo.exact_target_subset3 ets
				LEFT JOIN @exact_target_subset3 t
					ON t.exact_target_master_id = ets.exact_target_master_id
					AND ets.license_id = t.license_id
					AND t.license_category_id = ets.license_category_id
					AND t.capability_type_id = ets.capability_type_id
			WHERE ets.exact_target_master_id = @exact_target_master_id
			  AND t.license_id IS NULL;   

		END
END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_extole_select_next_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_extole_select_next_update]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-12-07	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try
	
	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select top 1 order_header_id
	into #temp
	from extole_update
	where process_date <= @batch_limit_date and modified_date <= @batch_limit_date and extole_update_status_id in (0,2) 

	select u.order_header_id, 
	case when vo.vendor_id = 1 and order_item_status_id = 1 and p.product_id IN (128,129) then (.30 * (isnull((oi.quantity*oi.unit_price),0) ))
	when vo.vendor_id = 1 and order_item_status_id = 1 and unit_price > 0 then isnull((oi.quantity*oi.unit_price),0) 
	when vo.vendor_id = 1 and order_item_status_id > 1  and unit_price <> 0 and quantity <> 0  then (abs(quantity)*abs(unit_price))*-1 -- Added to catch refunds better
	when vo.vendor_id = 1 and order_item_status_id > 1  and quantity = 0 then isnull(-1*(abs(case when unit_price = 0 then isnull(list_price,0)- isnull(order_item_offer_amount,0) else unit_price end)),0)
	when vo.vendor_id = 1 and order_item_status_id > 1  and quantity <> 0 then isnull(-1*(abs(quantity))*(abs(case when unit_price = 0 then isnull(list_price,0)- isnull(order_item_offer_amount,0) else unit_price end)),0)
	when vo.vendor_id = 1 and quantity < 0 and list_price > 0 then isnull((quantity* (case when unit_price = 0 then isnull(list_price,0)- isnull(order_item_offer_amount,0) else unit_price end)),0) 
	when vo.vendor_id = 1 and quantity < 0 and list_price < 0 then isnull((quantity* (case when unit_price = 0 then isnull(list_price,0)-isnull(abs(order_item_offer_amount),0) else unit_price end)),0)*-1   
	when vo.vendor_id = 1 and unit_price <> list_price then unit_price * quantity
	when vo.vendor_id = 2 and p.product_id IN (128,129) then (.30 * (isnull((oi.quantity*oi.list_price),0) - isnull(oi.order_item_offer_amount,0)))
	when vo.vendor_id = 2 and oi.quantity < 0  then isnull((oi.quantity*oi.list_price),0) + isnull(oi.order_item_offer_amount,0)
	when order_item_offer_amount >= list_price then isnull(list_price,0)* quantity - isnull( order_item_offer_amount ,0)
	else (isnull(list_price,0)- isnull( order_item_offer_amount ,0)) * quantity 
	end as amount
	into #temp2
	from #temp u
	inner join order_item oi with (nolock)
		on u.order_header_id = oi.order_header_id 
	inner join order_header oh with (nolock)
		on oi.order_header_id = oh.order_header_id
	inner join vendor_order vo with (nolock)
		on oh.vendor_order_id = vo.vendor_order_id
	left join product p with (nolock)
		on oi.product_id = p.product_id

	select order_header_id, sum(amount) as amount
	into #temp3
	from #temp2
	group by order_header_id

	select u.extole_update_id, u.order_header_id, u.extole_referral_id, u.process_date, t.amount
	from extole_update u
	inner join #temp3 t
		on u.order_header_id = t.order_header_id
	where t.amount >= 0

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_extole_select_update_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_extole_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2010-12-07	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- TODO validate of process date so if an update does occur we do a double check

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = getdate()
	from extole_update
	where extole_update_status_id in (0,2) and process_date <= getdate()

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_extole_update_id_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_extole_update_id_update]

(
		@extole_update_id int,
		@status_code varchar(25)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-12-07	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@extole_update_status_id tinyint,
			@current_extole_update_status_id tinyint,
			@update_attempts tinyint,
			@response_code int,
			@message varchar(100)


	select @response_code = 0

	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select @extole_update_status_id
	select @extole_update_status_id = case when @status_code = 'SUCCESS' then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_extole_update_status_id = extole_update_status_id
	from extole_update
	where extole_update_id = @extole_update_id

	-- 1.3) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @extole_update_status_id = 2 -- failed
		begin
		select @extole_update_status_id = 3 -- abandoned
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


--extole_update_status_id	extole_update_status_name
--0	Pending
--1	Processed
--2	Failed
--3	Abandoned

	-- 2.1) Processed
	if @extole_update_status_id  = 1
		begin
		-- 2.1.1) insert archive record
		--print('2.1.1')
		insert into extole_update_archive(extole_update_id, order_header_id, extole_referral_id, process_date, update_attempts, extole_update_status_id, insert_date, modified_date)
		select extole_update_id, order_header_id, extole_referral_id, process_date, update_attempts, extole_update_status_id, insert_date, modified_date = getdate()
		from extole_update
		where extole_update_id = @extole_update_id

		-- 2.1.2) delete update record
		delete
		from extole_update
		where extole_update_id = @extole_update_id
	
		select @response_code = 0, @message = 'Update processed'	
		end
	
	-- 2.2) Failure
	if @extole_update_status_id = 2
		begin
--		print('2.2')

			-- 2.2.2) update queue
			update extole_update 
			set extole_update_status_id = @extole_update_status_id,
				update_attempts = @update_attempts,
				modified_date = getdate(),
				process_date = dateadd(n,60,process_date)
			where extole_update_id = @extole_update_id

		
			-- 2.2.4) set 
			select @response_code = -220, @message = 'Update failed'
		end
	
	-- 2.3) Abandoned
	if @extole_update_status_id = 3
		begin
			-- 2.3.1) insert archive record
			--print('2.3.1')
			insert into extole_update_archive(extole_update_id, order_header_id, extole_referral_id, process_date, update_attempts, extole_update_status_id, insert_date, modified_date)
			select extole_update_id, order_header_id, extole_referral_id, process_date, update_attempts, extole_update_status_id, insert_date, modified_date = getdate()
			from extole_update
			where extole_update_id = @extole_update_id

			-- 2.3.2) delete update record
			delete
			from extole_update
			where extole_update_id = @extole_update_id

			select @response_code = -230, @message = 'Update abandoned'	
		end


		select response_code = @response_code, [message] 
= @message 
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'extole update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
