-- PROCEDURE: [dbo].[usp_extole_update_referral_id]
-- =============================================================================

create procedure [dbo].[usp_extole_update_referral_id]
	@vendor_order_id int,
	@extole_referral_id varchar(50)
as
/*
Date		Author		Change Reason
2011-01-17	acoffel		Created

Purpose: Update extole_update with actual extole_referral_id

*/
begin

begin try

	update eu
	set eu.extole_referral_id = @extole_referral_id
	from order_header oh
	inner join extole_update eu
		on oh.order_header_id = eu.order_header_id
	where oh.vendor_order_id = @vendor_order_id

end try
begin catch
		declare @response_code int,
				@message varchar(200)

		set @response_code = -200
		set @message = case when @message is null then 'extole referral_id not updated'
							else @message end

		declare @dbname nvarchar(128)
		set @dbname = db_name()
		exec usp_logerror @errordb = @dbname

end catch

end


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_extract_license_datasync_deltaload]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_extract_license_datasync_deltaload]

/*	
    DATE		AUTHOR		REMARKS
    2024-09-12	msoni		Initial creation.
	2025-02-19	rambasana	Remove filter for active license and use app_config for disti code
	2025-04-21  psatish		US-4726456 Added autorenewal_modified_date,autorenewal_modified_by,license_creation_date in the resultset
							and tuned the procedure
    
    Extract ZARB + Trial+ latest CyberSource order for NonZuora KCs from Ecom
    
*/
AS
SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
----------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Extract all KCs which are Active and not expired from Ecom DB- delta load.
----------------------------------------------------------------------------------------------------------------------------------------------------------------
BEGIN TRY
    ------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- find variable value to do delta load
    ------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- To read the value
    DECLARE @current_date DATETIME = GETDATE(),
            @last_run_completed DATETIME;

    DECLARE @APP_CONFIG TABLE
    (
        [app_config_name] NVARCHAR(50),
        [key] VARCHAR(50),
        [value] VARCHAR(MAX)
    );

	DECLARE @license_distribution_method TABLE
	(
		license_distribution_method_id INT PRIMARY KEY
	)
	DECLARE @product_line TABLE
	(
		product_line_id INT PRIMARY KEY
	)
	DECLARE @distribution_class TABLE
	(
		distribution_class_id INT PRIMARY KEY
	)
	DECLARE @license_category TABLE
	(
		license_category_id INT PRIMARY KEY
	)


    INSERT INTO @APP_CONFIG
    (
        [app_config_name],
        [key],
        [value]
    )
    SELECT f.[app_config_name],
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values](NULL, 'PORTAL') f


    INSERT INTO @license_distribution_method
    (
        license_distribution_method_id
    )
    SELECT dm.license_distribution_method_id
    FROM @APP_CONFIG ac
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_code = CONVERT(CHAR(4),ac.[key])
    WHERE app_config_name = 'PORTAL_DISTI_CODES'

    INSERT INTO @product_line
    (
        product_line_id
    )
    SELECT CONVERT(INT,[key])
    FROM @APP_CONFIG
    WHERE app_config_name = 'DATA_RECONCILIATION_PRODUCT_LINE'


    INSERT INTO @distribution_class
    (
        distribution_class_id
    )
    SELECT cl.distribution_class_id
    FROM @APP_CONFIG ac
        INNER JOIN dbo.distribution_class cl
            ON cl.distribution_class = CONVERT(VARCHAR(50),ac.[key])
    WHERE app_config_name = 'EXCLUDED_DISTRIBUTION_CLASS'

	INSERT INTO @license_category
	(
	    license_category_id
	)	
	SELECT lc.license_category_id
    FROM @APP_CONFIG ac
	INNER JOIN dbo.license_category lc
	ON lc.license_category_name=CONVERT(VARCHAR(10),ac.[key])
	WHERE app_config_name='EXCLUDED_LICENSE_CATEGORY'

    SELECT @last_run_completed = CAST(f.value AS DATETIME)
    FROM @APP_CONFIG f
    WHERE f.[key] = 'LAST-RUN-COMPLETION';

    ----------------------------------------------------------------------------------------------------------------------------------------------------
    -- To find payment method for all licenses ( ZUORA and NON-ZUORA) that are either modified or inserted between @last_run_completed 
and @current_date
    ----------------------------------------------------------------------------------------------------------------------------------------------------
    -- initial temp table to get license which are modified in time frame.
    DROP TABLE IF EXISTS #license;
    CREATE TABLE #license
    (
        license_id INT
    )

    INSERT INTO #license
    (
        license_id
    )
    SELECT l.license_id
    FROM dbo.license l
    WHERE l.modified_date >= @last_run_completed
          AND l.modified_date <= @current_date

    INSERT INTO #license
    (
        license_id
    )
    SELECT lcl.license_id
    FROM dbo.license_category_license lcl
    WHERE lcl.last_modified_date >= @last_run_completed
          AND lcl.last_modified_date <= @current_date

    INSERT INTO #license
    (
        license_id
    )
    SELECT lss.license_id
    FROM dbo.license_seat lss
    WHERE lss.modified_date >= @last_run_completed
          AND lss.modified_date <= @current_date

    INSERT INTO #license
    (
        license_id
    )
    SELECT lal.license_id
    FROM dbo.license_attribute_license lal
    WHERE lal.modified_date >= @last_run_completed
          AND lal.modified_date <= @current_date

    INSERT INTO #license
    (
        license_id
    )
    SELECT lnb.license_id
    FROM dbo.license_next_bill_date lnb
    WHERE lnb.last_modified_date >= @last_run_completed
          AND lnb.last_modified_date <= @current_date
    INSERT INTO #license
    (
        license_id
    )
    SELECT pl.license_id
    FROM dbo.payment_license pl
    WHERE pl.last_modified_date >= @last_run_completed
          AND pl.last_modified_date <= @current_date
    INSERT INTO #license
    (
        license_id
    )
    SELECT DISTINCT
           lcp.license_id
    FROM dbo.license_capability lcp
    WHERE lcp.modified_date >= @last_run_completed
          AND lcp.modified_date <= @current_date

    ;WITH customer_data
	AS
    (
	SELECT 
		caa.customer_id
	FROM  dbo.customer caa
			
	WHERE caa.modified_date >= @last_run_completed
		  AND caa.modified_date <= @current_date
	UNION
	SELECT ce.customer_id
	FROM dbo.customer_email ce		
	WHERE ce.modified_date >= @last_run_completed
		  AND ce.modified_date <= @current_date
		  AND ce.email_status_id = 1
	UNION
	SELECT sac.customer_id
	FROM dbo.safe_account_user_customer sac
		
	WHERE sac.modified_date >= @last_run_completed
		  AND sac.modified_date <= @current_date
	)

	INSERT #license
	(
	    license_id
	)
	SELECT l.license_id
	FROM customer_data lc
	INNER JOIN license l
	ON l.customer_id = lc.customer_id
	

    INSERT INTO #license
    (
        license_id
    )
    SELECT pl.license_id
    FROM dbo.payment_header ph
        INNER JOIN dbo.payment_license pl
            ON ph.payment_header_id = pl.payment_header_id
     WHERE ph.last_modified_date >= @last_run_completed
          AND ph.last_modified_date <= @current_date


    DROP TABLE IF EXISTS #keycodes;
    SELECT DISTINCT
           l.keycode,
           lic.license_id,
           l.customer_id,
           l.product_line_id,
           l.license_distribution_method_id,
           st.license_status_description,
           dm.license_distribution_method_code,
           l.insert_date AS license_creation_date
    INTO #keycodes
    FROM #license lic
        INNER JOIN dbo.license l
            ON l.license_id = lic.license_id
		INNER JOIN @product_line pl
            ON pl.product_line_id = l.product_line_id
        INNER JOIN dbo.license_status st
            ON st.license_status_id = l.license_status_id
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_id = l.license_distribution_method_id
        INNER JOIN dbo.license_distribution_method_channel dm1
            ON dm1.license_distribution_method_id = dm.license_distribution_method_id
        INNER JOIN db
o.distribution_class cl
            ON cl.distribution_class_id = dm1.distribution_class_id        
        LEFT JOIN @distribution_class cls
            ON cls.distribution_class_id = cl.distribution_class_id
    --AND st.license_status_id = 1
    WHERE cls.distribution_class_id IS NULL


    DROP TABLE IF EXISTS #license_data;
    SELECT k.keycode,
           k.license_id,
           license_creation_date,
           k.customer_id,
           k.product_line_id,
           k.license_distribution_method_id,
           k.license_status_description,
           k.license_distribution_method_code,
           c.base_capability_id,
           c.license_category_name,
           lk.license_key,
           lss.license_seats,
           lcp.capability_expiration_date AS license_expiration_date,
           ct.capability_type_description,
           ce.customer_email,
           ISNULL(CONVERT(VARCHAR(40), sa.safe_account_user_guid), '') user_GUID,
           cs.first_name,
           cs.last_name
    INTO #license_data
    FROM #keycodes k
        INNER JOIN dbo.license_category_license lcl
            ON lcl.license_id = k.license_id
        INNER JOIN dbo.license_category c
            ON c.license_category_id = lcl.license_category_id
        INNER JOIN dbo.license_key lk
            ON lk.license_id = k.license_id
        INNER JOIN dbo.license_seat lss
            ON lss.license_id = k.license_id
        INNER JOIN dbo.license_capability lcp
            ON lcp.license_id = k.license_id
               AND lcp.capability_id = c.base_capability_id
        INNER JOIN dbo.capability_type ct
            ON ct.capability_type_id = lcp.capability_type_id
        LEFT JOIN dbo.customer_email ce
            ON ce.customer_id = k.customer_id
               AND ce.email_status_id = 1
        LEFT JOIN dbo.customer cs
            ON cs.customer_id = ce.customer_id
        LEFT JOIN dbo.safe_account_user_customer sa
            ON sa.customer_id = ce.customer_id
		LEFT JOIN @license_category ctg
			ON ctg.license_category_id = c.license_category_id
		WHERE ctg.license_category_id IS NULL


    DROP TABLE IF EXISTS #next_bill_date;
    SELECT k.keycode,
           k.license_id,
           k.customer_id,
           k.product_line_id,
           k.license_distribution_method_id,
           k.license_status_description,          
           k.license_distribution_method_code,
           k.base_capability_id,
           k.license_category_name,
           k.license_key,
           k.license_seats,
           k.license_expiration_date,
           k.capability_type_description,
           ISNULL(license_attribute_license_value_description, 'N/A') AS autorenewal_status,
           lal.modified_date AS autorenewal_modified_date,
           lal.modified_by AS autorenewal_modified_by,
           lnb.next_bill_date,
           ps.subscription_payment_status_name,
           k.first_name,
           k.last_name,
           license_creation_date,
           k.customer_email,
           k.user_GUID
    INTO #next_bill_date
    FROM #license_data k
        LEFT JOIN dbo.license_attribute_license lal
            ON lal.license_id = k.license_id
               AND lal.license_attribute_id = 1
        LEFT JOIN dbo.license_attribute_license_value lalv
            ON lalv.license_attribute_license_value = lal.license_attribute_license_value
               AND lalv.license_attribute_id = lal.license_attribute_id
        LEFT JOIN dbo.license_next_bill_date lnb
            ON lnb.license_id = k.license_id
        LEFT JOIN dbo.subscription_payment_status ps
            ON ps.subscription_payment_status_id = lnb.subscription_payment_status_id




    DROP TABLE IF EXISTS #temp;
    SELECT DISTINCT
           k.keycode,
           k.license_id,
           k.customer_id,
           k.first_name,
           k.last_name,
           k.customer_email,
           k.user_GUID
,
           k.product_line_id,
           k.license_distribution_method_id,
           k.license_status_description,
           ph.payment_header_id,
           k.license_distribution_method_code,
           k.base_capability_id,
           k.license_category_name,
           k.license_key,
           k.license_seats,
           k.license_expiration_date,
           k.capability_type_description,
           k.autorenewal_status,
           k.next_bill_date,
           k.subscription_payment_status_name,
           ph.payment_method_id,
           pm.payment_method_name,
           k.autorenewal_modified_date,
           k.autorenewal_modified_by,
           license_creation_date,
           CASE
               WHEN dm.license_distribution_method_id IS NULL THEN
                   0
               ELSE
                   1
           END AS Zuora_license
    INTO #temp
    FROM #next_bill_date k
        LEFT JOIN dbo.payment_license pl
            ON pl.license_id = k.license_id
        LEFT JOIN dbo.payment_header ph
            ON ph.payment_header_id = pl.payment_header_id
        LEFT JOIN dbo.payment_method pm
            ON pm.payment_method_id = ph.payment_method_id
        LEFT JOIN @license_distribution_method dm
            ON dm.license_distribution_method_id = k.license_distribution_method_id
    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Payment info at the license level for Zuora licenses for latest payment account_id when payment_method_name is creditcard or one of the card type
    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    DECLARE @latest_order TABLE
    (
        license_id INT,
        payment_method_name VARCHAR(50),
        payment_account_id INT
    );

    INSERT INTO @latest_order
    (
        license_id,
        payment_method_name,
        payment_account_id
    )
    SELECT a.license_id,
           pm.payment_method_name,
           CASE
               WHEN pm.payment_method_name = 'creditcard'
                    OR pm.payment_method_name IN
                       (
                           SELECT card_type_description FROM dbo.card_type
                       ) THEN
                   a.payment_account_id
           END
    FROM
    (
        SELECT t.license_id,
               pl.payment_header_id,
               MAX(pa.payment_account_id) AS payment_account_id
        FROM #temp t
            INNER JOIN dbo.payment_license pl
                ON pl.license_id = t.license_id
            INNER JOIN dbo.payment_account pa
                ON pa.payment_header_id = pl.payment_header_id
        WHERE Zuora_license = 1
        --WHERE t.license_distribution_method_code = 'ZARB'
        GROUP BY t.license_id,
                 pl.payment_header_id
    ) a
        INNER JOIN dbo.payment_header ph
            ON ph.payment_header_id = a.payment_header_id
        INNER JOIN dbo.payment_method pm
            ON pm.payment_method_id = ph.payment_method_id
    ORDER BY a.license_id;
    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --creating temp file to have latest ZUORA license with lates payment information
    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    DROP TABLE IF EXISTS #license_zarb;
    SELECT DISTINCT
           t.keycode,
           t.license_id,
           t.customer_id,
           t.license_key,
           t.license_seats,
 
          t.product_line_id,
           t.first_name,
           t.last_name,
           t.customer_email,
           t.user_GUID,
           t.license_status_description,
           t.license_distribution_method_code,
           t.license_category_name,
           t.license_expiration_date,
           t.capability_type_description,
           t.autorenewal_status,
           t.next_bill_date,
           t.subscription_payment_status_name,
           t.payment_header_id,
           t.payment_method_id,
           t.payment_method_name,
           pa.payment_account_id,
           ISNULL(ct.card_type_description, lo.payment_method_name) credit_card_type,
           RIGHT(pa.account_number, 4) credit_card_last_four,
           CONVERT(VARCHAR(2), pa.expiration_month) expiration_month,
           CONVERT(VARCHAR(4), pa.expiration_year) expiration_year,
           t.autorenewal_modified_date,
           t.autorenewal_modified_by,
           license_creation_date
    INTO #license_zarb
    FROM #temp t
        LEFT JOIN @latest_order lo
            ON t.license_id = lo.license_id
        LEFT JOIN dbo.payment_account pa
            ON pa.payment_account_id = lo.payment_account_id
        LEFT JOIN dbo.card_type ct
            ON pa.card_type_id = ct.card_type_id
	WHERE t.Zuora_license =1
    --WHERE t.license_distribution_method_code = 'ZARB';

    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --- Extracting keycodes for NON-ZARB in #license_nonZarb
    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


    DROP TABLE IF EXISTS #latest_order;
    ;WITH CTE
    AS (SELECT DISTINCT
               license_id
        FROM #temp
        WHERE Zuora_license = 0)

    SELECT DISTINCT a.license_id,
           oh1.order_header_id,
           oh1.site_id AS order_type,
           ph.payment_merchant_id,
           ph.payment_method_id,
           oph.payment_header_id,
           ISNULL(oc.currency_id, ph.currency_id) AS currency_id
    INTO #latest_order
    FROM #temp a
        INNER JOIN
        (
            SELECT ol.license_id,
                   MAX(oh.order_header_id) AS order_header_id
            FROM CTE a
                INNER JOIN dbo.order_item_license ol
                    ON a.license_id = ol.license_id
                INNER JOIN dbo.order_item oi
                    ON oi.order_item_id = ol.order_item_id
                INNER JOIN dbo.order_header oh
                    ON oh.order_header_id = oi.order_header_id
                INNER JOIN dbo.vendor_order vo
                    ON vo.vendor_order_id = oh.vendor_order_id
            GROUP BY ol.license_id
        --WHERE a.license_distribution_method_code <> 'ZARB'
        ) oh
            ON oh.license_id = a.license_id
        INNER JOIN dbo.order_header oh1
            ON oh1.order_header_id = oh.order_header_id
        INNER JOIN dbo.order_item oi
            ON oi.order_header_id = oh1.order_header_id
        LEFT JOIN dbo.order_payment_header oph
            ON oph.order_header_id = oh.order_header_id
        LEFT JOIN dbo.payment_header ph
            ON ph.payment_header_id = oph.payment_header_id
               AND ph.currency_id = 1
        LEFT JOIN dbo.order_currency oc
            ON oc.order_header_id = oh1.order_header_id
               AND oc.currency_id = 1
    WHERE oi.order_item_status_id = 1

    DROP TABLE IF EXISTS #license_nonZarb
    SELECT DISTINCT tm.*,
           ph.order_header_id,
           pmc.merchant_id,
           RIGHT(pa.account_number, 4) credit_card_last_four,
           CONVERT(VARCHAR(2), pa.expiration_month) expiration_month,
           CONVERT(VARCHAR(4), pa.expira
tion_year) expiration_year,
           pmc.payment_merchant_id,
           ph.currency_id,
           ph.order_type
    INTO #license_nonZarb
    FROM #latest_order ph
        INNER JOIN #temp tm
            ON tm.license_id = ph.license_id
        LEFT JOIN
        (
            SELECT oh.payment_header_id,
                   MAX(pa.payment_account_id) AS payment_account_id
            FROM #latest_order oh
                LEFT JOIN dbo.payment_account pa
                    ON pa.payment_header_id = oh.payment_header_id ---to get max payment_account_id for payment_header_id
             GROUP BY oh.payment_header_id
        ) x
            ON x.payment_header_id = ph.payment_header_id
        LEFT JOIN dbo.payment_merchant pmc
            ON pmc.payment_merchant_id = ph.payment_merchant_id
        LEFT JOIN dbo.payment_method pm
            ON pm.payment_method_id = ph.payment_method_id
        LEFT JOIN dbo.payment_account pa
            ON pa.payment_account_id = x.payment_account_id


    -- Update the merchant_id if it exists in the payment_header-> cart_order  
    UPDATE lc1
    SET lc1.merchant_id = mc.merchant_id,
        lc1.payment_method_name = pm.payment_method_name
    FROM #license_nonZarb lc1
        INNER JOIN dbo.cart_order_header coh
            ON coh.order_header_id = lc1.order_header_id
        INNER JOIN dbo.cart_order co
            ON co.cart_order_id = coh.cart_order_id
        INNER JOIN dbo.payment_header ph
            ON ph.cart_order_id = co.cart_order_id
        INNER JOIN dbo.payment_method pm
            ON pm.payment_method_id = ph.payment_method_id
        INNER JOIN dbo.payment_merchant mc
            ON mc.payment_merchant_id = ph.payment_merchant_id
    WHERE lc1.merchant_id IS NULL;

    ---- Remove the licenses if the latest order payments were not transacted in USD
    IF EXISTS (SELECT 1 FROM #license_nonZarb WHERE currency_id IS NULL)
    BEGIN
        DELETE FROM #license_nonZarb
        WHERE currency_id IS NULL;

    END;

    -- Remove the licenses which latest orders are not from CSI/AUTORENEWAL/WRCART with webroot/webroot_usd merchants 
    IF EXISTS
    (
        SELECT 1
        FROM #license_nonZarb
        WHERE order_type NOT IN ( 'WRCART', 'CSI', 'AUTORENEWAL' ) -- CBCART
              OR merchant_id NOT IN ( 'webroot_usd', 'webroot' ) -- NULL,cleverbridge  
    )
    BEGIN

        DELETE FROM #license_nonZarb
        WHERE order_type NOT IN ( 'WRCART', 'CSI', 'AUTORENEWAL' )
              OR merchant_id NOT IN ( 'webroot_usd', 'webroot' );

    END;

    -----------------------------------------------------------------------------------
    --- Combine Zuora and Non Zuora in feed table
    -----------------------------------------------------------------------------------
    DECLARE @return TABLE
    (
        Id INT, -----CHANGES
        keycode VARCHAR(50),
        customer_id INT NULL,
        first_name NVARCHAR(255),
        last_name NVARCHAR(255),
        customer_email NVARCHAR(150),
        user_GUID VARCHAR(40),
        license_key VARCHAR(40),
        autorenewal_status VARCHAR(50),
        next_bill_date DATETIME,
        subscription_payment_status_name VARCHAR(10),
        license_expiration_date DATETIME,
        license_status_description VARCHAR(20),
        license_distribution_method_code CHAR(4),
        license_category_name VARCHAR(10),
        capability_type_description VARCHAR(20),
        license_seats INT,
        payment_method_name VARCHAR(50),
        credit_card_last_four VARCHAR(50),
        expiration_month TINYINT,
        expiration_year SMALLINT,
        autorenewal_modified_date DATETIME,
        autorenewal_modified_by VARCHAR(50),
        license_creation_date DATETIME
    --	,insert_date DATETIME
    );

    INSERT INTO @return
    (
        keycode,
        customer_id,
        first_name,
        last_name,
        customer
_email,
        user_GUID,
        license_key,
        autorenewal_status,
        next_bill_date,
        subscription_payment_status_name,
        license_expiration_date,
        license_status_description,
        license_distribution_method_code,
        license_category_name,
        capability_type_description,
        license_seats,
        payment_method_name,
        credit_card_last_four,
        expiration_month,
        expiration_year,
        autorenewal_modified_date,
        autorenewal_modified_by,
        license_creation_date
    --,insert_date
    )
    SELECT keycode,
           customer_id,
           first_name,
           last_name,
           customer_email,
           user_GUID,
           license_key,
           autorenewal_status,
           next_bill_date,
           subscription_payment_status_name,
           license_expiration_date,
           license_status_description,
           license_distribution_method_code,
           license_category_name,
           capability_type_description,
           license_seats,
           payment_method_name,
           credit_card_last_four,
           expiration_month,
           expiration_year,
           autorenewal_modified_date,
           autorenewal_modified_by,
           license_creation_date
    -- ,GETDATE()
    FROM #license_zarb
    UNION
    SELECT keycode,
           customer_id,
           first_name,
           last_name,
           customer_email,
           user_GUID,
           license_key,
           autorenewal_status,
           next_bill_date,
           subscription_payment_status_name,
           license_expiration_date,
           license_status_description,
           license_distribution_method_code,
           license_category_name,
           capability_type_description,
           license_seats,
           payment_method_name,
           credit_card_last_four,
           expiration_month,
           expiration_year,
           autorenewal_modified_date,
           autorenewal_modified_by,
           license_creation_date
    -- ,GETDATE()
    FROM #license_nonZarb;



    SELECT ROW_NUMBER() OVER (ORDER BY keycode) AS Id,
           keycode,
           customer_id,
           first_name,
           last_name,
           customer_email,
           user_GUID,
           license_key,
           autorenewal_status,
           next_bill_date,
           subscription_payment_status_name,
           license_expiration_date,
           license_status_description,
           license_distribution_method_code,
           license_category_name,
           capability_type_description,
           license_seats,
           payment_method_name,
           credit_card_last_four,
           expiration_month,
           expiration_year,
           autorenewal_modified_date,
           autorenewal_modified_by,
           license_creation_date
    --,insert_date
    FROM @return;


    -- Update the value for last run time
    UPDATE f
    SET f.value = CONVERT(VARCHAR(30), @current_date, 120) -- New datetime
    FROM @APP_CONFIG f
    WHERE f.[key] = 'LAST-RUN-COMPLETION';

    -- Write out value
    DECLARE @json VARCHAR(MAX);

    SELECT @json =
    (
        SELECT f.[key],
               f.[value]
        FROM @APP_CONFIG f
        WHERE f.[key] = 'LAST-RUN-COMPLETION'
        FOR JSON PATH, ROOT('config')
    );

    ---   SELECT @json;

    UPDATE ac
    SET ac.app_config_key_value_json = @json
    FROM dbo.app_config ac
        INNER JOIN dbo.app_config_group acg
            ON acg.app_config_group_id = ac.app_config_group_id
    WHERE ac.app_config_name = 'ZUORA-EXTRACT-DELTALOAD-JOB'
          AND acg.group_name = 'PORTAL';
END TRY
BEGIN CATCH

    DECLARE @error_severity INT = ERROR_SEVERITY(),
            @error_state INT = ERROR_STATE(),
            @message NVARCHAR(4000);
    SET @message = N'Fail
ed to load Data Reconciliation delta load for Zuora:' + ERROR_MESSAGE();
    RAISERROR(@message, @error_severity, @error_state) WITH LOG;

    INSERT INTO dbo.DBErrorlog
    (
        ErrorNumber,
        ErrorSeverity,
        ErrorState,
        ErrorProcedure,
        ErrorLine,
        ErrorMessage,
        ErrorServer,
        ErrorDB,
        ErrorUser
    )
    SELECT ERROR_NUMBER(),
           ERROR_SEVERITY(),
           ERROR_STATE(),
           ERROR_PROCEDURE(),
           ERROR_LINE(),
           @message,
           @@servername,
           DB_NAME(),
           SUSER_NAME();

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_extract_license_usage_from_wh]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_extract_license_usage_from_wh] @insert INT, @purge INT, @purgedays INT
AS
/*

Date            Author       version              Remarks
============================================================

Initial	           surpal       1.0         Extract license_usage table from warehouse.BI_Stage.BI_license_usage table

*/

SET NOCOUNT ON

DECLARE @maxdate DATETIME
DECLARE @purgedate DATETIME
DECLARE @rename_str NVARCHAR(MAX)
DECLARE @ErrorMessage NVARCHAR(4000)
DECLARE @ErrorSeverity INT
DECLARE @ErrorState INT



SET @purgedate= DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()- @purgedays))

PRINT @purgedate

SELECT @maxdate=MAX(activity_date) FROM license_usage

IF(@maxdate IS null)
BEGIN
SELECT @maxdate=DATEADD(dd, 0, DATEDIFF(dd, 0, GETDATE()- 10))
select @maxdate
END

IF (@insert = 1)
BEGIN
BEGIN TRY
select @maxdate

INSERT INTO license_usage
SELECT * FROM DATAWAREHOUSEREADONLY.BI_stage.dbo.bi_license_usage where activity_date > @maxdate
PRINT 'Licensing Usage data insert from datawarehouse completed'
END TRY

BEGIN CATCH
    SELECT 
        @ErrorMessage = ERROR_MESSAGE(),
        @ErrorSeverity = ERROR_SEVERITY(),
        @ErrorState = ERROR_STATE();

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
END CATCH

END



IF (@purge = 1)
BEGIN
BEGIN TRY
select @purgedate
DELETE FROM license_usage WHERE activity_date < @purgedate
PRINT 'Licensing Usage data purge completed until '+convert(varchar,@purgedate)+' '
END TRY

BEGIN CATCH
    SELECT 
        @ErrorMessage = ERROR_MESSAGE(),
        @ErrorSeverity = ERROR_SEVERITY(),
        @ErrorState = ERROR_STATE();

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
END CATCH

END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_cancel_price]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_cancel_price]
	@license_id int,
	@growth_rate decimal(18, 2),
	@license_category_id int,
	@period int,
	@previous_price money,
	@new_price money,
	@acv_cancel_price_new money output,
	@acv_cancel_price_renew money output

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries
	2017-10-04	cnovac		Added logic to now handle license_category_id
	
*/
as

set nocount on

begin try

	declare	@previous_period int,
			@new_period int,
			@delta_price money

	set @delta_price = @new_price - @previous_price
	set @previous_period = @period/12
	set @new_period = @period
	set @acv_cancel_price_new = 0
	set @acv_cancel_price_renew = 0

	while @previous_period > 1
	begin

		select @acv_cancel_price_renew = @acv_cancel_price_renew + sum(calc.forescast_usage_delta * (24 - @new_period + calc.period) * @delta_price)
		from forecast_calc calc
		inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		where calc.license_id = @license_id
		and calc.growth_rate = @growth_rate
		and calc.license_category_id = @license_category_id
		and calc.forescast_usage_delta >= 0
		and calc.period between (@new_period - 23) and (@new_period - 13)
		and core.model = 'utility'

		set @previous_period = @previous_period - 1
		set @new_period = @new_period - 12

	end

	select @acv_cancel_price_new = sum(calc.forescast_usage_delta * (12 - @period + calc.period) * @delta_price)
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
	where calc.license_id = @license_id
	and calc.growth_rate = @growth_rate
	and calc.license_category_id = @license_category_id
	and calc.forescast_usage_delta >= 0
	and calc.period between (@period - 11) and (@period - 1)
	and core.model = 'utility'

	set @acv_cancel_price_renew = isnull(@acv_cancel_price_renew, 0)
	set @acv_cancel_price_new = isnull(@acv_cancel_price_new, 0)

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_cancel_price - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_cancel_usage]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_cancel_usage]
	@license_id int,
	@growth_rate decimal(18, 2),
	@license_category_id int,
	@period int,
	@previous_price money,
	@forescast_usage_delta decimal(18, 4),
	@acv_cancel_usage money output

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries
	2017-10-04	cnovac		Added logic to now handle license_category_id

*/
as

set nocount on

begin try

	declare	@start_period int = 0,
			@min_period int = 0,
			@max_period int = 0,
			@current_period int = 0,
			@delta_sum decimal(18, 4) = 0,
			@forecast_usage_remainder decimal(18, 4) = 0

	set @acv_cancel_usage = 0

	--find the period where the sum of all the delta's is greater than or equal to @forescast_usage_delta passed in
	select @max_period = min(calc2.period)
	from (select calc.period,
				 calc.forescast_usage_delta,
				 sum(calc.forescast_usage_delta) over (order by period) as running_total
		  from forecast_calc calc
		  inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		  where calc.license_id = @license_id
		  and calc.growth_rate = @growth_rate
		  and calc.license_category_id = @license_category_id
		  and calc.forescast_usage_delta >= 0
		  and calc.period < @period
		  and core.model = 'utility'
		  group by calc.period, calc.forescast_usage_delta) calc2
	where calc2.running_total >= abs(@forescast_usage_delta)

	--find the min period where there we need to start taking seats away
	select @min_period = min(calc.period)
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
	where calc.license_id = @license_id
	and calc.growth_rate = @growth_rate
	and calc.license_category_id = @license_category_id
	and calc.forescast_usage_delta > 0
	and calc.period < @max_period
	and core.model = 'utility'

	while @min_period < @max_period
	begin

		--find the prorated sum of all cancels that are less than @max_period since these will all be zero'd out
		select top 1
			   @acv_cancel_usage = @acv_cancel_usage + (calc.forescast_usage_delta * (12 - (@period - calc.period)) * @previous_price),
			   @delta_sum = @delta_sum + calc.forescast_usage_delta,
			   @current_period = calc.period
		from forecast_calc calc
		inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		where calc.license_id = @license_id
		and calc.growth_rate = @growth_rate
		and calc.license_category_id = @license_category_id
		and calc.forescast_usage_delta > 0
		and calc.period = @min_period
		and core.model = 'utility'

		set @min_period = @min_period + 1

	end

	if @period - @max_period >= 12
		set @period = @period - 12

	--find the prorated sum if cancel that is equal to @max_period and add it to previous @acv_cancel_usage, then negate it at end to be passed out
	select top 1
		   @acv_cancel_usage = (isnull(@acv_cancel_usage, 0) + (abs(@forescast_usage_delta) - isnull(@delta_sum, 0)) * ((12 - (@period - calc.period)) * @previous_price)) * -1
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
	where calc.license_id = @license_id
	and calc.growth_rate = @growth_rate
	and calc.license_category_id = @license_category_id
	and calc.forescast_usage_delta > 0
	and calc.period = @max_period
	and core.model = 'utility'

	--negate all delta's as we know they are all zero'd out of calc up above
	update calc
	set forescast_usage_delta = 0
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
	where calc.license_id = @license_id
	and calc.growth_rate = @growth_rate
	and calc.license_category_id = @license_category_id
	and calc.forescast_usag
e_delta > 0
	and calc.period < @max_period
	and core.model = 'utility'

	--this section of code updates all the delta's after they have been negated
	set @start_period = @max_period

	while @start_period <= @period
	begin

		select top 1
			   @forecast_usage_remainder = case when @start_period = @max_period then (abs(@forescast_usage_delta) - isnull(@delta_sum, 0)) else 0 end
		from forecast_calc calc
		inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		where calc.license_id = @license_id
		and calc.growth_rate = @growth_rate
		and calc.license_category_id = @license_category_id
		and calc.period = case when @start_period = @max_period then @start_period else @start_period - 1 end
		and core.model = 'utility'

		update calc
		set forescast_usage_delta = case when forescast_usage_delta <= 0 or forescast_usage_delta - @forecast_usage_remainder <= 0 then 0 else forescast_usage_delta - @forecast_usage_remainder end
		from forecast_calc calc
		inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		where calc.license_id = @license_id
		and calc.growth_rate = @growth_rate
		and calc.license_category_id = @license_category_id
		and calc.period = @start_period
		and core.model = 'utility'

		set @start_period = @start_period + 1

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_cancel_usage - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_forecast_acv]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_forecast_acv]
	@license_id int,
	@growth_rate decimal(18, 2)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2016-10-30	cnovac		Added logic to zero out acv on price change for first month as the price logic needs to be one month in rear
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries
	2017-10-04	cnovac		Added logic to now handle license_category_id

*/
as

set nocount on

begin try

	declare @forecast_calc_id int,
			@forecast_core_id int,
			@forescast_usage_delta decimal(18, 4),
			@license_category_id int,
			@model varchar(50),
			@usage decimal(18, 4),
			@period int,
			@price money,
			@previous_period int = 0,
			@previous_acv_new12 money = 0,
			@previous_price money = 0,
			@previous_forecast_core_id int = null,
			@previous_model varchar(50) = null,
			@acv_cancel_usage money,
			@acv_usage money,
			@acv_cancel_price_new money,
			@acv_cancel_price_renew money,
			@forecast_calc_forecast_acv_count int = 0,
			@counter int = 1

	declare @forecast_calc_forecast_acv table (forecast_calc_forecast_acv_id int identity (1, 1), forecast_calc_id int, forecast_core_id int, period int,
			forescast_usage_delta decimal (18, 4), price money, model varchar(50), usage decimal(18, 4), license_category_id int)
	declare @previous table (previous_price money, previous_forecast_core_id int, previous_model varchar(50), license_category_id int)

	insert into @forecast_calc_forecast_acv (forecast_calc_id, forecast_core_id, period, forescast_usage_delta, price, model, usage, license_category_id)
	select calc.forecast_calc_id,
		   calc.forecast_core_id,
		   calc.period,
		   calc.forescast_usage_delta,
		   isnull(usage.price, core.price) as price,
		   core.model,
		   usage.usage,
		   calc.license_category_id
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id and core.license_id = calc.license_id
	left join forecast_usage usage on usage.forecast_usage_id = calc.forecast_usage_id and usage.license_id = calc.license_id
	where calc.license_id = @license_id
	and calc.growth_rate = @growth_rate
	order by calc.period, core.forecast_core_id, usage.order_license_usage_id desc

	select @forecast_calc_forecast_acv_count = @@rowcount

	while @forecast_calc_forecast_acv_count > 0
	begin

		select @forecast_calc_id = forecast_calc_id, @forecast_core_id = forecast_core_id, @period = period, @forescast_usage_delta = forescast_usage_delta, 
				@price = price, @model = model, @usage = usage, @license_category_id = license_category_id
		from @forecast_calc_forecast_acv
		where forecast_calc_forecast_acv_id = @counter

		select @previous_price = previous_price,
			   @previous_forecast_core_id = previous_forecast_core_id,
			   @previous_model = previous_model
		from @previous
		where license_category_id = @license_category_id

		set @price = iif(@price = 0, @previous_price, @price)
		set @acv_cancel_usage = 0
		set @acv_cancel_price_new = 0
		set @acv_cancel_price_renew = 0
		set @previous_period = @period/12
		set @acv_usage = isnull(@forescast_usage_delta, 0) * @price * 12

		if @model != 'utility'
			set @acv_usage = isnull(@usage, 0) * @price

		if @model = 'utility' and isnull(@previous_model, @model) = 'utility'
		begin
			--if the usage delta is negative, you need to know substract that acv out from prior periods
			if @forescast_usage_delta < 0
			begin
				--this procedure resets the delta and balance for all periods up to @period and figures out the cancel amount
				exec usp_forecast_calc_cancel_usage @license_id, @growth_rate, @license_category_id, @period, @previous_price, @forescast_usage_delta, @acv_cancel_usage output

				--override @acv_usage with 0, as
 it already takes into account the usage for the period
				set @acv_usage = 0
			end

			--if the previous price and new price don't match want to see if there's cancel acv
			if @price != @previous_price and @previous_price != 0
			begin
				--this procedure resets the delta and balance for all periods up to @period and figures out the cancel amount
				exec usp_forecast_calc_cancel_price @license_id, @growth_rate, @license_category_id, @period, @previous_price, @price, @acv_cancel_price_new output, @acv_cancel_price_renew output
			end

			--after the first year, meaning 12 periods, we will need to look back 12 periods to do calcs
			exec usp_forecast_calc_previous_new_acv @license_id, @growth_rate, @license_category_id, @period, @previous_period, @price, @previous_acv_new12 output
		end

		--basically on the first period within utility, you want to take the full usage amount and figure out acv
		if @model = 'utility' and isnull(@previous_model, @model) != 'utility'
		begin
			set @acv_usage = isnull(@usage, 0) * @price * 12

			--update the delta to be the usage amount on the first period
			update forecast_calc
			set forescast_usage_delta = @usage
			where forecast_calc_id = @forecast_calc_id
		end

		--imply that the first time you've seen this it's 'new'
		if @forecast_core_id = isnull(@previous_forecast_core_id, @forecast_core_id)
		begin
			update forecast_calc
			set acv_sold = 0,
				acv_new = @acv_usage,
				acv_renew = @previous_acv_new12,
				acv_cancel_new = @acv_cancel_usage + @acv_cancel_price_new,
				acv_cancel_renew = 0,
				acv_total = @acv_usage + @previous_acv_new12 + @acv_cancel_usage + @acv_cancel_price_new
			where forecast_calc.forecast_calc_id = @forecast_calc_id
		end
		else --this implies renew or upsell
		begin
			update forecast_calc
			set acv_sold = 0,
				acv_new = @acv_usage,
				acv_renew = @previous_acv_new12,
				acv_cancel_new = @acv_cancel_price_new,
				acv_cancel_renew = @acv_cancel_usage + @acv_cancel_price_renew,
				acv_total = @acv_usage + @previous_acv_new12 + @acv_cancel_price_new + @acv_cancel_usage + @acv_cancel_price_renew
			where forecast_calc.forecast_calc_id = @forecast_calc_id
		end

		if not exists (select 1 from @previous where license_category_id = @license_category_id)
		begin
			insert into @previous (previous_price, previous_forecast_core_id, previous_model, license_category_id)
			select @price, @forecast_core_id, @model, @license_category_id
		end
		else
		begin
			update @previous
			set previous_price = @price,
				previous_forecast_core_id = @forecast_core_id,
				previous_model = @model
			where license_category_id = @license_category_id
		end

		set @forecast_calc_forecast_acv_count = @forecast_calc_forecast_acv_count - 1
		set @counter = @counter + 1

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_forecast_acv - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_multi_period_sold_acv]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_multi_period_sold_acv]
	@license_id int,
	@growth_rate decimal(18, 2)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.

	
*/
as

set nocount on

begin try

	declare @forecast_calc_multi_period_sold_acv table (forecast_core_id int)

	--basically here we are trying to find upsells that happened in the same period as they would not have been accounted for in usp_forecast_insert_forecast_calc
	--due to it deleting all periods after the period it's trying to process while looping.
	insert into @forecast_calc_multi_period_sold_acv (forecast_core_id)
	select distinct core.forecast_core_id
	from forecast_core core
	left join forecast_calc calc on calc.forecast_core_id = core.forecast_core_id and calc.growth_rate = @growth_rate
	where core.license_id = @license_id
	and calc.forecast_core_id is null
	order by core.forecast_core_id

	if @@rowcount > 0
	begin

		insert into forecast_calc (forecast_core_id, forecast_usage_id, license_id, period, growth_rate, forecast_start_date, forecast_end_date, forecast_type, forecast_usage, 
								   forescast_usage_delta, insert_date)
		select sold.forecast_core_id, 
			   null, 
			   core.license_id, 
			   calc.period, 
			   calc.growth_rate, 
			   calc.forecast_start_date, 
			   calc.forecast_end_date, 
			   'actual',
			   0,
			   0,
			   getdate()
		from forecast_core core
		inner join @forecast_calc_multi_period_sold_acv sold on sold.forecast_core_id = core.forecast_core_id
		inner join forecast_calc calc on calc.forecast_calc_id = (select top 1 calc2.forecast_calc_id
																  from forecast_calc calc2
																  where calc.license_id = calc2.license_id
																  and calc.growth_rate = calc2.growth_rate
																  and calc2.forecast_end_date > core.order_item_eff_date
																  order by calc2.period)
		where calc.license_id = @license_id
        and calc.growth_rate = @growth_rate

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_multi_period_sold_acv - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_previous_new_acv]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_previous_new_acv]
	@license_id int,
	@growth_rate decimal(18, 2),
	@license_category_id int,
	@period int,
	@previous_period int,
	@price money,
	@previous_acv_new12 money output

/*	
	DATE		AUTHOR		REMARKS
	2017-04-13	cnovac		Initial creation.
	2017-10-04	cnovac		Added logic to now handle license_category_id

*/
as

set nocount on

begin try

	declare @previous_forecast12 table (acv_new money)

	--after the first year, meaning 12 periods, we will need to look back 12 periods to do calcs further down
	delete @previous_forecast12

	while @previous_period > 0 and @period > 12
	begin

		--insert record into temporary table from respective 12 month period
		insert into @previous_forecast12 (acv_new)
		select case when calc.forescast_usage_delta < 0 then 0 else calc.forescast_usage_delta end * @price * 12
		from forecast_calc calc
		inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id
		where calc.license_id = @license_id
		and calc.growth_rate = @growth_rate
		and calc.license_category_id = @license_category_id
		and calc.period = @period - (12 * @previous_period)
		and core.model = 'utility'

		set @previous_period = @previous_period - 1

	end

	--need to sum up the previous 12 x number of renews acv to be added to acv_renew
	select @previous_acv_new12 = isnull(sum(isnull(previous12.acv_new, 0)), 0)
	from @previous_forecast12 previous12

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_previous_new_acv - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_recurring_acv]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_recurring_acv]
	@license_id int,
	@period int,
	@forecast_start_date date,
	@forecast_end_date date,
	@order_item_total_acv_recurring money output

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries

	
*/
as

set nocount on

begin try

	declare @order_item_total money,
			@order_item_exp_date date,
			@counter int = 1,
			@forecast_calc_recurring_acv_count int = 0,
			@order_term_in_months decimal (18, 4),
			@remaining_months decimal (18, 4),
			@remaining_days decimal (18, 4)
	declare @forecast_calc_recurring_acv table (forecast_calc_recurring_acv_id int identity(1, 1), order_item_total money, order_item_exp_date date, order_term_in_months decimal (18, 4))

	set @order_item_total_acv_recurring = 0

	insert into @forecast_calc_recurring_acv (order_item_total, order_item_exp_date, order_term_in_months)
	select core.order_item_total,
		   core.order_item_exp_date,
		   core.order_term_in_months
	from forecast_core core
	where core.license_id = @license_id
	and core.order_item_exp_date >= @forecast_start_date
	order by core.forecast_core_id

	select @forecast_calc_recurring_acv_count = @@rowcount

	while @forecast_calc_recurring_acv_count > 0
	begin

		select @order_item_total = order_item_total, @order_item_exp_date = order_item_exp_date, @order_term_in_months = order_term_in_months
		from @forecast_calc_recurring_acv
		where forecast_calc_recurring_acv_id = @counter

		if @period - 1 - @order_term_in_months < 0
		begin

			set @remaining_months = dbo.fn_Forecast_Date_Diff_By_DatePart('mm', @forecast_start_date, @order_item_exp_date, 1)			
			if @remaining_months = 0
				set @remaining_months = ((@order_term_in_months*1000)%1000)/1000

			if @remaining_months > 0 and @remaining_months <= 12
				set @order_item_total_acv_recurring = @order_item_total_acv_recurring + (@order_item_total/@order_term_in_months * @remaining_months)
			else
				set @order_item_total_acv_recurring = @order_item_total_acv_recurring + (@order_item_total/@order_term_in_months * 12)
		end

		set @forecast_calc_recurring_acv_count = @forecast_calc_recurring_acv_count - 1
		set @counter = @counter + 1

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_recurring_acv - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_calc_sold_acv]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_calc_sold_acv]
	@license_id int,
	@forecast_core_id int,
	@forecast_start_date date,
	@order_item_total_acv_new money output

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.

	
*/
as

set nocount on

begin try

	declare @order_item_type varchar(50),
			@order_item_total money,
			@order_item_eff_date date,
			@order_term_in_months decimal (18, 4),
			@remaining_months decimal (18, 4),
			@remaining_days decimal (18, 4),
			@previous_order_item_eff_date date

	set @order_item_total_acv_new = 0
	set @previous_order_item_eff_date = null

	select @order_item_type = core.order_item_type,
		   @order_item_total = core.order_item_total,
		   @order_item_eff_date = core.order_item_eff_date,
		   @order_term_in_months = core.order_term_in_months
	from forecast_core core
	where core.forecast_core_id = @forecast_core_id

    --get the most recent sold event effective date that the upsell relates to
	if @order_item_type = 'upsell'
		select @previous_order_item_eff_date = max(core.order_item_eff_date)
		from forecast_core core
		where core.license_id = @license_id
		and core.order_item_type != 'upsell'
		and core.order_item_eff_date <= @order_item_eff_date

	if @order_term_in_months > 0 and @order_term_in_months <= 12
		set @order_item_total_acv_new = @order_item_total
	else
	begin
		set @remaining_months = dbo.fn_Forecast_Date_Diff_By_DatePart('mm', @order_item_eff_date, dateadd(mm, 12, isnull(@previous_order_item_eff_date, @forecast_start_date)) , 0)
		set @remaining_days = dbo.fn_Forecast_Date_Diff_By_DatePart('dd', dateadd(mm, @remaining_months, @order_item_eff_date), dateadd(mm, 12, isnull(@previous_order_item_eff_date, @forecast_start_date)), 0)
		if @remaining_days > 0
			set @remaining_months = @remaining_months + @remaining_days/30

		set @order_item_total_acv_new = @order_item_total/@order_term_in_months * @remaining_months
	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_calc_sold_acv - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_insert_forecast_calc]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_insert_forecast_calc]
	@license_id int,
	@growth_rate decimal(18, 2)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries.  Fixed bug for periods starting in 28, 29, 30, 31.
	2017-04-18	cnovac		Added @order_history_quantity to show license seat changes by order
	2017-06-19	cnovac		Added some more logic to handle upsells
	2017-10-04	cnovac		Added logic to now handle license_category_id
	
*/
as

set nocount on

begin try

	declare @forecast_calc_id int,
			@forecast_core_id int,
			@forecast_usage_id int,
			@order_type varchar(50),
			@order_item_eff_date date,
			@order_quantity int,
			@order_history_quantity int,
			@forecast_type varchar(50),
			@forecast_usage decimal(18, 4),
			@forecast_usage_delta decimal(18, 4),
			@forecast_sold_quantity_total decimal(18, 4),
			@usage_id int,
			@usage decimal(18, 4),
			@usage_start_date date,
			@usage_end_date date,
			@forecast_start_date date,
			@forecast_end_date date,
			@period_start_date date,
			@period_end_date date,
			@period int,
			@previous_period_start_date date,
			@previous_forecast_start_date date,
			@previous_usage decimal(18, 4),
			@previous_forecast_calc_id int,
			@previous_forecast_core_id int = 0,
			@previous_forecast_usage_id int = null,
			@license_category_id int,
			@forecast_calc_count int = 0,
			@counter int = 1

	declare @previous_forecast table (forecast_usage decimal(18, 4), usage decimal(18, 4), forecast_start_date date, period int)
	declare @forecast_calc table (forecast_calc_id int identity(1, 1), forecast_core_id int, forecast_usage_id int, license_category_id int, usage decimal(18, 4), usage_start_date date, usage_end_date date, order_item_eff_date date, order_item_type varchar(50), order_quantity int, order_history_quantity int)
	declare @previous table (previous_forecast_core_id int, previous_forecast_usage_id int, previous_forecast_start_date date, license_category_id int)

	insert into @forecast_calc (forecast_core_id, forecast_usage_id, license_category_id, usage, usage_start_date, usage_end_date, order_item_eff_date, order_item_type, order_quantity, order_history_quantity)
	select core.forecast_core_id,
		   usage.forecast_usage_id,
		   core.license_category_id,
		   usage.usage,
		   dateadd(dd, 1, usage.usage_start_date),
		   dateadd(dd, -1, usage.usage_end_date),
		   core.order_item_eff_date,
		   core.order_item_type,
		   core.order_item_quantity,
		   core.license_seat_count
	from forecast_core core
	left join forecast_usage usage on usage.forecast_core_id = core.forecast_core_id and usage.license_id = core.license_id
	where core.license_id = @license_id
	order by isnull(usage.usage_start_date, core.order_item_eff_date), core.forecast_core_id, usage.order_license_usage_id desc

	select @forecast_calc_count = @@rowcount

	while @forecast_calc_count > 0
	begin

		select @forecast_core_id = forecast_core_id, @forecast_usage_id = forecast_usage_id, @usage = isnull(usage, 0), @usage_start_date = usage_start_date, @usage_end_date = usage_end_date, 
				@order_item_eff_date = order_item_eff_date, @order_type = order_item_type, @order_quantity = order_quantity, @order_history_quantity = order_history_quantity, @license_category_id = license_category_id
		from @forecast_calc
		where forecast_calc_id = @counter

		set @forecast_start_date = @order_item_eff_date
		set @forecast_type = 'forecast'

		select @previous_forecast_core_id = previous_forecast_core_id,
			   @previous_forecast_usage_id = previous_forecast_usage_id,
			   @previous_forecast_start_date = previous_forecast_start_date
		from @previous
		where license_category_id = @license_category_id

		--this mea
ns the current record is not from the same order as previous record, new sold event
		if @forecast_core_id != @previous_forecast_core_id
		begin

			if @forecast_core_id < isnull(@previous_forecast_core_id, 0)
			begin
				select @forecast_start_date = forecast_start_date
				from forecast_calc 
				where license_id = @license_id
				and growth_rate = @growth_rate
				and license_category_id = @license_category_id
				and isnull(@usage_start_date, @forecast_start_date) between forecast_start_date and forecast_end_date
			end

			--if it's an upsell sold event, make the @forecast_start_date = to most current calc start_date.  This ensures
			--we don't throw off the periods if the start date falls somewhere between forecast_start_date and forecast_end_date
			set @forecast_sold_quantity_total = @order_quantity

			if @order_type = 'upsell'
			begin
				--added this code to make sure a new period start date doesn't equal the end of another.  A bit of fuzzy logic, but need to move to next period
				if exists (select 1 from forecast_calc 
							where license_id = @license_id
							and growth_rate = @growth_rate
							and license_category_id = @license_category_id
							and forecast_end_date = @forecast_start_date)
					set @forecast_start_date = dateadd(dd, 1, @forecast_start_date)

				select @forecast_start_date = forecast_start_date
				from forecast_calc 
				where license_id = @license_id
				and growth_rate = @growth_rate
				and license_category_id = @license_category_id
				and @forecast_start_date between forecast_start_date and forecast_end_date

				set @forecast_sold_quantity_total = @order_quantity + @order_history_quantity
			end

		end
		else if @usage_start_date is not null
		begin

			select @forecast_start_date = forecast_start_date
			from forecast_calc 
			where license_id = @license_id
			and growth_rate = @growth_rate
			and license_category_id = @license_category_id
			and @usage_start_date between forecast_start_date and forecast_end_date

			if @@rowcount = 0
			begin
				select @forecast_start_date = forecast_start_date
				from forecast_calc 
				where license_id = @license_id
				and growth_rate = @growth_rate
				and license_category_id = @license_category_id
				and @usage_end_date between forecast_start_date and forecast_end_date
			end
		end

		--figure out all rows in the future you will be re-processing them again
		if @previous_forecast_start_date = @forecast_start_date
		begin
			select @forecast_calc_id = max(calc.forecast_calc_id)
			from forecast_calc calc
			where calc.license_id = @license_id
			and calc.growth_rate = @growth_rate
			and calc.license_category_id = @license_category_id
			and calc.forecast_start_date <= @forecast_start_date
		end
		else if @previous_forecast_usage_id is null
		begin
			select @forecast_calc_id = max(calc.forecast_calc_id)
			from forecast_calc calc
			where calc.license_id = @license_id
			and calc.growth_rate = @growth_rate
			and calc.license_category_id = @license_category_id
			and calc.forecast_usage_id is null
			and calc.forecast_start_date < @forecast_start_date
		end
		else
		begin
			select @forecast_calc_id = max(calc.forecast_calc_id)
			from forecast_calc calc
			where calc.license_id = @license_id
			and calc.growth_rate = @growth_rate
			and calc.license_category_id = @license_category_id
			and calc.forecast_type = 'actual'
		end

		if @order_type = 'upsell'
		begin
			--delete all future rows now
			delete forecast_calc
			where license_id = @license_id
			and growth_rate = @growth_rate
			and license_category_id = @license_category_id
			and forecast_start_date >= @forecast_start_date
		end
		else
		begin
			--delete all future rows now
			delete forecast_calc
			where license_id = @license_id
			and growth_rate = @growth_rate
			and license_category_id = @license_category_id
			and forecast_calc_id > @forecast_calc_id
		end

		--set the variables to begin looping through periods
		set @forecast_end_date = dateadd(mm, 37, @forecast_sta
rt_date)
		set @period_start_date = @forecast_start_date

		while @period_start_date < @forecast_end_date
		begin

			set @period = 0
			set @previous_usage = 0
			set @previous_forecast_calc_id = 0

			--get this to be used below
			select @previous_forecast_calc_id = max(forecast_calc_id)
			from forecast_calc 
			where license_id = @license_id
			and growth_rate = @growth_rate
			and license_category_id = @license_category_id

			--insert previous row into temporary table-------------------------------------------------
			delete @previous_forecast

			insert into @previous_forecast (period, forecast_usage, usage, forecast_start_date)
			select calc.period, calc.forecast_usage, usage.usage, calc.forecast_start_date
			from forecast_calc calc
			left join forecast_usage usage on usage.forecast_usage_id = calc.forecast_usage_id
			where calc.forecast_calc_id = @previous_forecast_calc_id
			--insert previous row into temporary table-------------------------------------------------

			--set the end period to be one day before next start date
			set @period_end_date = dbo.fn_select_next_start_month(@order_item_eff_date, @period_start_date)

			--set variables from previous period.  This will be empty when the first period is being processed
			--added code to look for cancel row (order_license_usage is null) and set period back to match
			select @period = period,
				   @previous_usage = isnull(isnull(forecast_usage, usage), 0),
				   @previous_period_start_date = forecast_start_date
			from @previous_forecast

			--this implies there are two events that happen on same period.  This implies a cancel usage record and actual usage record
			--set the period back one in order to show two events with same period
			set @period = iif(@previous_period_start_date between @period_start_date and @period_end_date, @period - 1, @period)

			--this happens when you are processing first record for different license_category_id and want to make sure to put the row in right period
			if @period = 0
			begin
				select @period = calc.period - 1
				from forecast_calc calc
				where license_id = @license_id
				and growth_rate = @growth_rate
				and @period_start_date between calc.forecast_start_date and calc.forecast_end_date
			end

			--if an actual usage event occured, do all calculations based on usage number and previous period's record
			--check to see if period you are processing is when usage occured
			if @usage_start_date between @period_start_date and @period_end_date
			begin
				set @forecast_type = 'actual'
				set @usage_id = @forecast_usage_id
				set @forecast_usage = null
				set @forecast_usage_delta = @usage - @previous_usage
			end
			else
			begin
				set @usage_id = null
				set @forecast_usage = @previous_usage * (1 + @growth_rate)
				set @forecast_usage_delta = (@previous_usage * (1 + @growth_rate)) - @previous_usage
			end

			insert into forecast_calc (forecast_core_id, forecast_usage_id, license_id, license_category_id, period, growth_rate, forecast_start_date, forecast_end_date, forecast_type, forecast_usage, forescast_usage_delta, forecast_sold_quantity_total, insert_date)
			select @forecast_core_id, @usage_id, @license_id, @license_category_id, @period + 1, @growth_rate, @period_start_date, @period_end_date, @forecast_type, @forecast_usage, @forecast_usage_delta, @forecast_sold_quantity_total, getdate()

			set @period_start_date = dateadd(dd, 1, @period_end_date)
			set @forecast_type = 'forecast'

		end

		if not exists (select 1 from @previous where license_category_id = @license_category_id)
		begin
			insert into @previous (previous_forecast_core_id, previous_forecast_usage_id, previous_forecast_start_date, license_category_id)
			select @forecast_core_id, @forecast_usage_id, @forecast_start_date, @license_category_id
		end
		else
		begin
			update @previous
			set previous_forecast_core_id = @forecast_core_id,
				previous_forecast_usage_id = @forecast_usage_id,
				previous_forecast_start_date = @fore
cast_start_date
			where license_category_id = @license_category_id
		end

		set @forecast_calc_count = @forecast_calc_count - 1
		set @counter = @counter + 1

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_insert_forecast_calc - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_insert_forecast_core]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_insert_forecast_core]
	@license_id int,
	@send_to_sfdc bit = 0

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2016-10-11	cnovac		Changed the query to not look at effective date on order_item
	2016-10-31	cnovac		Added logic to see if license is changing from utility to something else and insert 0 usage for that effective date
	2017-04-13	cnovac		Added logic to now process overage licenses.  Made lots of changes to all queries
	2017-06-19	cnovac		Added @min_order_license_usage_date to weed out orders that have no usage
	2017-10-04	cnovac		Added logic to now handle license_category_id when consuming usage
	2017-10-13	cnovac		Added hook to forecast_order_exclusions which is table maintained with SFDC excess usage orders which were manually booked.  We want to exclude these orders
	2018-11-01	cnovac		took out references to effective columns in attribute
	2020-11-25	cnovac		Rewrite to include all products (business)
	2021-12-08  psatish		Added the Perpetual billing model for usage

*/
as

set nocount on

begin try

	declare @growth_rate decimal(18, 2),
			@growth_rate_count int = 0,
			@counter int = 1
	declare @growth_rate_table table (growth_rate_id int identity(1, 1), growth_rate decimal (18, 2))

	--delete all records for the license you are about to process.  We will reprocess all records for the license
	delete forecast_calc
	where license_id = @license_id

	delete forecast_usage
	where license_id = @license_id

	delete forecast_core
	where license_id = @license_id

	--insert the sold events first into the stage table - forecast_core
	insert into forecast_core
			( license_id ,
			  license_category_id ,
			  license_seat_count ,
			  sfdc_opportunity_id ,
			  sfdc_opportunity_line_id ,
			  order_item_id ,
			  order_item_eff_date ,
			  order_item_exp_date ,
			  order_term_in_months ,
			  order_item_total ,
			  order_item_quantity ,
			  order_item_type ,
			  price ,
			  model ,
			  model_start_date ,
			  model_end_date ,
			  insert_date
			)
	select
		fn.license_id,
		fn.license_category_id,
		dbo.fn_license_select_effective_object_element(fn.license_id, fn.license_category_id, 'license_seats', oi.effective_date),
		oo.salesforce_opportunity_id,
		oioli.opportunity_line_item_id,
		oi.order_item_id,
		oi.effective_date,
		isnull(oi.capability_expiration_date, dateadd(dd, -1, dateadd(yy, 1, oi.effective_date))),
		case --this code is to determine how many months a contract is.  It has to be able to handle partial months
			when dbo.fn_Forecast_Date_Diff_By_DatePart('dd', oi.effective_date, dateadd(mm, dbo.fn_Forecast_Date_Diff_By_DatePart('mm', oi.effective_date, oi.capability_expiration_date, 1), oi.effective_date), 0) = dbo.fn_Forecast_Date_Diff_By_DatePart('dd', oi.effective_date, oi.capability_expiration_date, 1)
				then dbo.fn_Forecast_Date_Diff_By_DatePart('mm', oi.effective_date, oi.capability_expiration_date, 1)
				else cast(dbo.fn_Forecast_Date_Diff_By_DatePart('mm', oi.effective_date, oi.capability_expiration_date, 1) as decimal (18, 4)) + 
						abs(cast(dbo.fn_Forecast_Date_Diff_By_DatePart('dd', oi.effective_date, dateadd(mm, dbo.fn_Forecast_Date_Diff_By_DatePart('mm', oi.effective_date, oi.capability_expiration_date, 1), oi.effective_date), 0) as decimal (18, 4)) - 
						cast(dbo.fn_Forecast_Date_Diff_By_DatePart('dd', oi.effective_date, oi.capability_expiration_date, 1) as decimal (18, 4))) / 30
		end,
		oi.item_total,
		oi.quantity,
		pt.product_type_description,
		0,
		fn.license_attribute_license_value_description,
		oi.effective_date,
		oi.capability_expiration_date,
		getdate()
	from fn_license_select_license_profile(@license_id) fn
	inn
er join order_item_license oil on oil.license_id = fn.license_id
	inner join order_item oi on oil.order_item_id = oi.order_item_id
	inner join product p on p.product_id = oi.product_id
	inner join product_type pt on pt.product_type_id = p.product_type_id
	inner join product_license_category plc on plc.product_id = p.product_id and plc.license_category_id = fn.license_category_id
	inner join order_item_opportunity_line_item oioli on oioli.order_item_id = oi.order_item_id
	inner join order_opportunity oo on oi.order_header_id = oo.order_header_id
	left join license_parent lp on lp.child_license_id = fn.license_id
	left join forecast_order_exclusions foe on foe.order_item_id = oi.order_item_id
	where lp.license_parent_id is null --don't pick up any legacy children
	and fn.license_status_id = 1 --Active
	and fn.category_type_id = 1 --Full, not trial
	and fn.license_attribute_license_value in (11, 12,13)
	and foe.order_item_id is null
	order by oi.effective_date, oi.order_item_id

	--crappy logic for when end date was null from initial insert and we defaulted to 1 yr.
	update core
	set core.order_term_in_months = 12
	from forecast_core core
	where core.license_id = @license_id
	and core.order_term_in_months is null

	--crappy code to handle 12.0333 for annual contracts, utility specific only, and set the total to 0
	update core
	set core.order_term_in_months = iif(core.order_term_in_months > 12, 12, core.order_term_in_months),
		core.order_item_total = 0
	from forecast_core core
	where core.license_id = @license_id
	and core.model = 'utility'

	--insert the overage/Perpetual usage records next
	insert into forecast_usage
			( forecast_core_id ,
			  license_id ,
			  license_category_id ,
			  order_license_usage_id ,
			  usage_start_date ,
			  usage_end_date ,
			  model ,
			  price ,
			  usage ,
			  insert_date
			)
	select core.forecast_core_id,
		core.license_id,
		olu.license_category_id,
		olu.order_license_usage_id,
		cast(olu.start_date as date),
		cast(olu.end_date as date),
		isnull(lalv.license_attribute_license_value_description, case olu.license_attribute_license_value when  11 then 'Overage'
																										  when 13 then 'Perpetual' end),
		olu.unit_price,
		olu.usage_seats,
		getdate()
	from forecast_core core
	inner join order_license_usage olu on olu.license_id = core.license_id
	left join license_attribute_license_value lalv on lalv.license_attribute_license_value = olu.license_attribute_license_value
	where core.license_id = @license_id
	and isnull(olu.oracle_update_status_id, 1) = 1
	and core.forecast_core_id = (select top 1 core2.forecast_core_id
								from forecast_core core2
								where olu.license_id = core2.license_id
								and olu.license_category_id = core2.license_category_id
								and olu.start_date >= core2.model_start_date
								and (olu.start_date < core2.model_end_date or core2.model_end_date is null)
								order by core2.forecast_core_id desc)
	order by core.forecast_core_id, cast(olu.start_date as date)

	--used to see if this license is changing from utility to something else, get the very last usage row
	declare @utility table (license_id int, license_category_id int, forecast_core_id int, usage_start_date date, usage_end_date date, price money)

	insert into @utility (license_id, license_category_id, forecast_core_id, usage_start_date, usage_end_date, price)
	select usage.license_id,
		   usage.license_category_id,
		   max(usage.forecast_core_id),
		   max(usage.usage_start_date),
		   max(usage.usage_end_date),
		   usage.price
	from forecast_usage usage
	where usage.license_id = @license_id
	and usage.model = 'utility'
	group by usage.license_id, usage.license_category_id, usage.price

	--insert a usage record of 0 for following month after license moves off of utility
	insert into forecast_usage (forecast_core_id, license_id, license_category_id, order_license_usage_id, usage_sta
rt_date, usage_end_date, price, model, usage, insert_date)
	select util.forecast_core_id,
		   util.license_id,
		   util.license_category_id,
		   null,
		   dateadd(dd, 1, util.usage_end_date), 
		   dbo.fn_select_next_start_month(dateadd(dd, 1, util.usage_end_date), dateadd(dd, 1, util.usage_end_date)),
		   util.price,
		   'utility',
		   0,
		   getdate()
	from @utility util
	cross apply fn_license_select_effective_object_table(util.license_id, dateadd(dd, 1, util.usage_end_date)) eo
	where util.license_category_id = eo.license_category_id
	and eo.effective_value != 12 --something that is not utility
	and eo.effective_object_id = 2 --license_attribute_license_value

	--loop through all the growth rates and execute the procedures to insert the periods and do the calcs
	insert into @growth_rate_table (growth_rate)
	select growth_rate   
	from forecast_growth_rate
	where growth_rate_active = 1
	order by forecast_growth_rate_id

	select @growth_rate_count = @@rowcount

	while @growth_rate_count > 0
	begin

		select @growth_rate = growth_rate from @growth_rate_table where growth_rate_id = @counter

		exec usp_forecast_insert_forecast_calc @license_id, @growth_rate

		exec usp_forecast_calc_forecast_acv @license_id, @growth_rate

		set @growth_rate_count = @growth_rate_count - 1
		set @counter = @counter + 1

	end

	--this sends the record to be processed by SFDC queue
	if @send_to_sfdc = 1
	begin
		exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = 'create_sfdc_forecast', @license_id = @license_id
	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_insert_forecast_core - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_insert_license_process_queue]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_insert_license_process_queue]

(
    @license_id int,
    @send_to_sfdc bit = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.

	
*/

AS
	set nocount on				

begin try

	set nocount on 

	declare @sql_string varchar(4000),
			@task_number varchar(50),
			@dbname nvarchar(128)

	set @dbname = db_name()
	set @task_number = @license_id

	set @sql_string = 'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
					  'values (' + @task_number + ',' + '''' + 'exec ' + @dbname + '..usp_forecast_insert_forecast_core ' + cast(@license_id as varchar(50)) + ', ' + cast(@send_to_sfdc as char(1)) + '''' + ', 0, getdate())'

	exec (@sql_string)

	exec tasks..usp_queue_task @license_id
	
end try
begin catch

	declare @response_code int,
			@message varchar(100)            

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_insert_forecast_core - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end


	exec usp_LogError @ErrorDB = @dbname

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_forecast_select_forecast_calc]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_forecast_select_forecast_calc]
	@license_id int

/*	
	DATE		AUTHOR		REMARKS
	2016-04-21	cnovac		Initial creation.
	2017-04-18	cnovac		Updated Sold_Total__c and added Order_Type and added Order_End_Date


*/
as

set nocount on

begin try

	select 
		isnull(usage.usage, 0) as Actual_Over_Usage__c ,
		isnull(calc.acv_cancel_new, 0) + isnull(calc.acv_cancel_renew, 0) as Cancel_ACV__c,
		isnull(calc.acv_new, 0) as New_ACV__c,
		isnull(calc.acv_renew, 0) as Renew_ACV__c,
		calc.forecast_end_date as End_Date__c ,
		case calc.growth_rate
			when .00 then 'Flat 0% Growth'
			when .01 then 'Low 1% Growth'
			when .03 then 'Medium 3% Growth'
			when .05 then 'High 5% Growth'
		end as Growth_Rate__c,
		lk.salesforce_license_id as License__c,
		calc.period as Month__c,
		core.sfdc_opportunity_id as opportunity__c,
		core.sfdc_opportunity_line_id as OpportunityLineItem_Id__c,
		isnull(usage.price, core.price) as Price__c,
		core.order_item_quantity as Sold__c,
		core.license_seat_count as Sold_Total__c,
		calc.forecast_start_date as Start_Date__c,
		case calc.forecast_type
			when 'actual' then 'Actual'
			when 'forecast' then 'Forecast'
		end as Type__c,
		isnull(cast(calc.forecast_usage as int), 0) as Usage_Forecast__c,
		1 as Active_Growth_Rate__c,
		isnull(c.currency_code, 'USD') as CurrencyIsoCode,
		core.model as Usage_Type__c
	from forecast_calc calc
	inner join forecast_core core on core.forecast_core_id = calc.forecast_core_id and core.license_id = calc.license_id
	inner join order_item oi on oi.order_item_id = core.order_item_id
	left join forecast_usage usage on usage.forecast_usage_id = calc.forecast_usage_id and usage.license_id = calc.license_id
	left join license_key lk on lk.license_id = calc.license_id
	left join order_currency oc on oc.order_header_id = oi.order_header_id
	left join currency c on c.currency_id = oc.currency_id
	where calc.license_id = @license_id
	order by calc.license_id, calc.growth_rate, calc.period

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'forecast - usp_forecast_select_forecast_calc - error processing @license_id = ' + cast(@license_id as varchar(50))
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_form_insert_form_response]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_form_insert_form_response]

(
	@form_submit_id int,
	@form_response nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2015-04-16	esmart		Initial creation.
	2016-12-01	esmart		Add usp_form_update_form_submit SB transaction

	DESCRIPTION
	Insert form_submit
*/

AS
	set nocount on				

	declare @form_response_id int,
			@form_type_name varchar(50),
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) insert form_response
	insert into form_response(form_submit_id, form_response)
	values(@form_submit_id, @form_response)

	select @form_response_id = scope_identity()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert SB
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) form_type
	select @form_type_name = t.form_type_name
	from form_submit s
	inner join form f
		on f.form_id = s.form_id
	inner join form_type t
		on t.form_type_id = f.form_type_id
	where s.form_submit_id = @form_submit_id

	-- 2.2) insert ServiceBroker
	if @form_type_name <> 'Trial'
		begin
			declare @sql_string varchar(4000),
					@task_number varchar(10),	
					@db_name varchar(100),
					@system_user varchar(50)

			select @system_user = suser_sname(),
					@db_name = db_name()

			select @task_number = @form_submit_id --(select isnull(max(task_number),0) from tasks..task_table) + 10
				select @sql_string = 
					'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
					' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_form_update_form_submit ' + convert(varchar(10),@form_submit_id) + '''' + ',0,getdate()) '

			exec (@sql_string)

			exec tasks..usp_queue_task @form_submit_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select form_response_key = convert(varchar(36),form_response_key)
	from form_response
	where form_response_id = @form_response_id
	


	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_form_insert_form_submit]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_form_insert_form_submit]

(
	@form_name varchar(50),
	@ip_address varchar(24),
	@form_url varchar(500),
	@form_json nvarchar(max),
	@insert_by varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-04-16	esmart		Initial creation.
	2016-12-01	esmart		Remove usp_form_update_form_submit SB transaction

	DESCRIPTION
	Insert form_submit
*/

AS
	set nocount on				

	declare @form_id int,
			@form_type_id tinyint,
			@form_submit_id int,
			@insert_date datetime,
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @insert_date
	select @insert_date = getdate()

	if @insert_by is null
		begin
		select @insert_by = suser_sname()
		end

	-- 1.1) @form_id
	select @form_id = form_id 
	from form 
	where form_name = @form_name

	-- 1.2) insert new form
	if @form_id is null
		begin
		select @form_type_id = 1

		insert into form(form_name,form_type_id,insert_date) 
		values(@form_name, @form_type_id, @insert_date)

		select @form_id = scope_identity()
		end
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert form_submit
	insert into form_submit(form_id, ip_address, form_json, form_url, insert_date, insert_by)
	values(@form_id, @ip_address, @form_json, @form_url, @insert_date, @insert_by)

	select @form_submit_id = scope_identity()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select form_submit_id = @form_submit_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_form_insert_form_submit_customer]
-- =============================================================================

CREATE procedure [dbo].[usp_form_insert_form_submit_customer] 

	(@form_submit_id int)

/*	
	DATE		 AUTHOR		REMARKS
	2015-04-16	 esmart		Initial creation.
	2015-09-03	 esmart		Develop field_name alias to provide mapping
	2018-07-09	 esmart		Check country description and use ISO to look up country
	2018-07-31	 esmart		Convert state to iso2 to use in customer insert
	2018-10-04	 esmart		company_type_name
	2019-06-21	 esmart		add @company_id_input
	2020-06-23	 abelenkiy	AXIOM-1297: set opt_in value (section 1.9)
	2020-08-28	 abelenkiy  AXIOM-1764: refactored to parse out json from form_submit and pass in new json format to usp_customer_insert_customer_service

	DESCRIPTION
	Selects/creates customer from form_submit and writes form_submit_customer record. Called from usp_form_update_form_submit through Service Broker.
*/
as
set nocount on;

begin try
	declare @input_json nvarchar(max), @form_json nvarchar(max), @customer_id int

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select and parse form_json
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.1) select form_json through form_submit_id; return out if json invalid
	select @form_json = fs.form_json
	from form_submit fs
	where fs.form_submit_id = @form_submit_id
		and isjson(fs.form_json) = 1

	if @form_json is null
		begin
			return
		end

	-- 1.2) parse out json into customer object
	else
		begin

			-- 1.3) parse out customer/company object from form_json to input_json variable
			select @input_json = (	 
								select j.customer_email as [customer.customer_email], j.first_name as [customer.first_name]
									, j.last_name as [customer.last_name], j.phone_number as [customer.phone_number], j.opt_in as [customer.opt_in]
									, j.state as [customer.address.bill_to.state], j.country as [customer.address.bill_to.country]
									, j.company_name as [company.company_name]
									, J.company_type_id as [company.company_type_id]
									, 'form_submit' as [transaction_user]
								from openjson(@form_json)
									with (customer_email varchar(100) '$.customer_email', first_name nvarchar(225) '$.first_name'
										, last_name nvarchar(225) '$.last_name', phone_number varchar(64) '$.phone_number', opt_in int '$.opt_in'
										, company_name nvarchar(255) '$.company_name', company_type_id nvarchar(50) '$.company_type_id'
										, state nvarchar(50) '$.state', country nvarchar(75) '$.country') j
								for json path, without_array_wrapper
								);

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 2.) insert values
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			-- 2.1) insert/update customer
			exec usp_customer_insert_customer_service @input_json = @input_json, @customer_id = @customer_id output;

			-- 2.2) insert form_submit_customer
			if @customer_id is not null
				begin
					insert into form_submit_customer (form_submit_id, customer_id)
					values (@form_submit_id, @customer_id);
				end;
		end
end try
begin catch
	declare @DBName nvarchar(128);
	set @DBName = db_name();
	exec usp_LogError @ErrorDB = @DBName;
end catch;

GO
