-- =============================================================================

CREATE PROCEDURE [dbo].[usp_form_select_form_submit]

(
	@form_submit_id int = null,
	@form_name varchar(50) = null,
	@ip_address varchar(24) = null,
	@form_url varchar(500) = null,
	@start_date datetime = null,
	@end_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-04-16	esmart		Initial creation.

	DESCRIPTION
	Select form_submit
*/

AS
	set nocount on				

	declare @form_id int,
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @form_submit_id is not null
		begin
			select s.form_submit_id, f.form_id, f.form_name, t.form_type_id, t.form_type_name, s.ip_address, s.form_url, s.form_json, s.insert_date, s.insert_by
			from form_submit s
			inner join form f
				on s.form_id = f.form_id
			inner join form_type t
				on f.form_type_id = t.form_type_id
			where form_submit_id = @form_submit_id
		end
	else
		begin
			select s.form_submit_id, f.form_id, f.form_name, t.form_type_id, t.form_type_name, s.ip_address, s.form_url, s.form_json, s.insert_date, s.insert_by
			from form_submit s
			inner join form f
				on s.form_id = f.form_id
			inner join form_type t
				on f.form_type_id = t.form_type_id
			where f.form_name = case when @form_name is not null then @form_name else f.form_name end and 
				s.ip_address = case when @ip_address is not null then @ip_address else s.ip_address end and 
				s.form_url = case when @form_url is not null then @form_url else s.form_url end and
				(s.insert_date > @start_date or @start_date is null) and
				(s.insert_date < @end_date or @end_date is null)
		end

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_form_update_form_submit]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_form_update_form_submit]

(
	@form_submit_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2015-04-16	esmart		Initial creation.
	2016-10-06	esmart		Add default field alias

	DESCRIPTION
	Select form_submit
*/

AS
	set nocount on				

	declare @form_json nvarchar(max),
			@form_id int,	
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @form_json
	select @form_json = form_json, @form_id = form_id
	from form_submit 
	where form_submit_id = @form_submit_id

	-- 1.2) 
	declare @form_field_data table (field_name varchar(50), field_value nvarchar(max), field_data_type varchar(10))

	insert into @form_field_data(field_name, field_value, field_data_type)
	select Name, StringValue, ValueType
	from dbo.fn_parse_json(@form_json)
	where Object_ID is null
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) form_fields
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) add new form_fields
	insert into form_field(field_name, field_data_type, field_name_alias)
	select d.field_name, d.field_data_type, d.field_name
	from @form_field_data d
	left join form_field f
		on d.field_name = f.field_name
	where f.form_field_id is null

	-- 2.2) form_field_form
	insert into form_field_form(form_id, form_field_id)
	select @form_id, f.form_field_id
	from @form_field_data d
	inner join form_field f
		on d.field_name = f.field_name
	left join form_field_form ff
		on f.form_field_id = ff.form_field_id
	where ff.form_field_id is null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into form_submit_value(form_submit_id, form_field_id, field_value)
	select form_submit_id = @form_submit_id, f.form_field_id, d.field_value
	from @form_field_data d
	inner join form_field f
		on d.field_name = f.field_name
	inner join form_field_form ff
		on f.form_field_id = ff.form_field_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) form_submit_customer
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	exec usp_form_insert_form_submit_customer @form_submit_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_geocode_clean_up_expired_data]
-- =============================================================================

CREATE    procedure [dbo].[usp_geocode_clean_up_expired_data]
as
    /*
        DATE        AUTHOR      REMARKS
        2020-03-12  jnavarra    Initial creation
        2020-04-29  jnavarra    Clear parsed address components

        DESCRIPTION
        Clean up expired geocode data
    */

    set nocount on;

    begin try

        declare
            @response_code int,
            @message varchar(100)

        -- Clear response data
        update gr
        set gr.response = null,
            gr.response_cleared_date = getdate(),
            gr.last_modified_date = getdate()
        from dbo.geocode_request gr
            inner join dbo.geocode_type gt
                on gt.geocode_type_id = gr.geocode_type_id
        where gr.response_expiration_date <= getdate()
            and gt.clear_expired_response = 1
            and gr.response_cleared_date is null

        -- Clear parsed data from response
        update res
        set res.formatted_address = null,
            res.location = null,
            res.location_type = null,
            res.partial_match = null,
            res.plus_code = null,
            res.result_cleared_date = getdate(),
            res.last_modified_date = getdate()
        from dbo.geocode_result res
            inner join dbo.geocode_request req
                on req.geocode_request_id = res.geocode_request_id
            inner join dbo.geocode_type gt
                on gt.geocode_type_id = req.geocode_type_id
        where res.expiration_date <= getdate()
            and gt.clear_expired_response = 1
            and res.result_cleared_date is null

        -- Clear address components from parsed response
        delete ac
        from dbo.geocode_result_address_component ac
            inner join dbo.geocode_result res
                on res.geocode_result_id = ac.geocode_result_id
        where res.result_cleared_date is not null

    end try
    
	begin catch

		set @response_code = -200
		set @message = case
            when @message is null then 'clean up expired geocode data failed'
			else @message
        end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_google_insert_notification]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_google_insert_notification]

(
	@notification_string varchar(max),
	@license_message_id int = null
)

/*	
	DATE			AUTHOR		REMARKS
	2018-10-18		cnovac		Initial creation

	DESCRIPTION
	usp_google_insert_notification

*/

AS

	set nocount on

	begin try

	declare	@google_notification_id int,
			@sql_string varchar(4000),
			@task_number varchar(10),
			@db_name varchar(50) = db_name(),
			@response_code int,
			@message varchar(100)

	insert into google_notifications (notification_string, license_message_id)
	values (@notification_string, @license_message_id)

	set @google_notification_id = scope_identity()

	-- cancel_reason
	--0 - User canceled the subscription
	--1 - Subscription was canceled by the system, for example because of a billing problem
	--2 - Subscription was replaced with a new subscription
	--3 - Subscription was canceled by the developer
	update google_notifications
	set	transaction_id = left(json_value(notification_string, '$.orderId'), 24),
		purchase_date_utc = dateadd(ss, cast(left(json_value(notification_string, '$.startTimeMillis'), 10) as int), '1970-01-01'),
		expiration_date_utc = dateadd(ss, cast(left(json_value(notification_string, '$.expiryTimeMillis'), 10) as int), '1970-01-01'),
		cancellation_date_utc = dateadd(ss, cast(left(json_value(notification_string, '$.userCancellationTimeMillis'), 10) as int), '1970-01-01'),
		cancel_reason = json_value(notification_string, '$.cancelReason'),
		auto_renewing = json_value(notification_string, '$.autoRenewing')
	where google_notification_id = @google_notification_id

	--set the service broker transaction to process the notification
	-----------------------------------------------------------------------------------------------
	set @task_number = @google_notification_id

	set @sql_string = 'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
						' values (' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_google_process_notification ' + convert(varchar(10), @google_notification_id) + '''' + ', 0, getdate())'

	exec (@sql_string)
	exec tasks..usp_queue_task @google_notification_id
	-----------------------------------------------------------------------------------------------

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_google_insert_notification'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_google_insert_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_google_insert_order]

(
	@google_order_number varchar(100),
	@keycode varchar(40),
	@guid varchar(50),
	@order_status_id int,
	@product varchar(50),
	@order_date datetime

)

/*	
	DATE		AUTHOR		REMARKS
	2011-04-12	esmart		Initial creation.
	2011-06-20	towens		add support for in-app purchase
	2012-02-15  esmart		remove order load without xml
	2015-02-12	acoffel		added WSA trap
	

	DESCRIPTION
	insert google order

*/

AS
	set nocount on				


	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100),
			@license_id int,
			@product_line_id int,
			@order_header_id int,
			@license_type_id int	

	begin try

	select @order_header_id = 0

	select @response_code = 0, @message = 'Success'
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check for OEM license_type
	select @license_type_id = license_type_id, @product_line_id = product_line_id from license where keycode = @keycode

	if @license_type_id = 2 or @product_line_id not in (50,51,55)
		begin
			select @response_code = -200, @message = 'Cannot alter OEM Key'
			RETURN
		end

	-- 1.2) insert google_order
	insert into google_order(google_order_number, keycode, guid, order_date,processed,product,order_status_id)
	values(@google_order_number, @keycode, @guid, @order_date,0,@product,@order_status_id)
	
	-- 1.3) check for xml
	declare @google_order_notification table (row_id int identity(1,1), google_order_notification_id int, serial_number varchar(40))

	insert into @google_order_notification(google_order_notification_id,serial_number)
	select google_order_notification_id,serial_number
	from google_order_notification where google_order_number = @google_order_number

	declare @rows int, @row_id int, @serial_number varchar(40)

	select @rows = max(row_id), @row_id = 1 from @google_order_notification

	while @row_id <= @rows
	begin
		
		select @serial_number = serial_number 
		from @google_order_notification
		where row_id = @row_id
		
		--select row_id = @row_id, serial_number = @serial_number
		--exec usp_google_process_xml @serial_number
		select @db_name = db_name()

		insert into [tasks].[dbo].[task_table]([task_number],[Command],[NoTransaction],[StartTime])
		values (@google_order_number,'exec ' + @db_name + '..usp_google_process_xml  ''' + @serial_number + '''',0,getdate())

		exec tasks..usp_queue_task @google_order_number
		
		
		select @row_id =  @row_id + 1
	end
	
		
	-- 2.3) return result
	select response_code = @response_code, message = @message


--	-- 3) insert work onto the work queue

--	select @system_user = suser_sname(),
--			@db_name = db_name()

