-- PROCEDURE: [dbo].[usp_google_insert_order_notification]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_google_insert_order_notification]

(
	@order_notification_xml varchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-04-12	esmart		Initial creation
	2012-02-28	esmart		Modification of task insert

	DESCRIPTION
	insert google order notification

*/

AS
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON	
			

	declare	@google_order_notification_id int,
			@google_notification_type_id tinyint,
			@response_code int,
			@message varchar(100),
			@google_notification_type_name varchar(100),
			@vendor_order_code varchar(100),
			@subscription_xml xml	,
			@state_type varchar(100),
			@state_type_id int,
			@serial varchar(50),
			@found int,
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@license_id int ,
			@order_header_id int


	begin try

	select @response_code = 0, @message = 'Success'
	set @subscription_xml = convert(xml,@order_notification_xml)
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select  
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @google_notification_type_id
	--select @google_notification_type_id = google_notification_type_id
	--from google_notification_type 
	--where google_notification_type_name = @google_notification_type_name

	select @google_notification_type_id = case
		when substring(@order_notification_xml,1,23) = '<new-order-notification' then 1
		when substring(@order_notification_xml,1,30) = '<risk-information-notification' then 7
		when substring(@order_notification_xml,1,32) = '<order-state-change-notification' then 6
		when substring(@order_notification_xml,1,34) = '<authorization-amount-notification' then 5
		when substring(@order_notification_xml,1,27) = '<charge-amount-notification' then 4
		when substring(@order_notification_xml,1,27) = '<refund-amount-notification' then 2
		when substring(@order_notification_xml,1,31) = '<chargeback-amount-notification' then 3
		end

		if @google_notification_type_id is null
			begin
				select @google_notification_type_id = 1
			end

	-- 1.2) parse for google order number

	if  @google_notification_type_id = 1
		begin
			select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//new-order-notification') AS x(item)
			
			select @serial = (select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
							from @subscription_xml.nodes('new-order-notification') data (x))
		end
	else if  @google_notification_type_id = 2
		begin
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//refund-amount-notification') AS x(item)
		
		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
						from @subscription_xml.nodes('refund-amount-notification') data (x))
		end
	else if  @google_notification_type_id = 3
		begin	
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//chargeback-amount-notification') AS x(item)
	
		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
						from @subscription_xml.nodes('chargeback-amount-notification') data (x))	
		end
	else if  @google_notification_type_id = 4
		begin
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('
//charge-amount-notification') AS x(item)

		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
						from @subscription_xml.nodes('charge-amount-notification') data (x))	
		end
	else if  @google_notification_type_id = 5
		begin
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//authorization-amount-notification') AS x(item)
		
		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
						from @subscription_xml.nodes('authorization-amount-notification') data (x))
	
		end
	else if  @google_notification_type_id = 6
		begin
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//order-state-change-notification') AS x(item)
		select @state_type = x.item.value('new-financial-order-state[1]', 'varchar(20)') from @subscription_xml.nodes('//order-state-change-notification') AS x(item)
		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial from @subscription_xml.nodes('order-state-change-notification') data (x))

		if @state_type  in ('CANCELLED','CANCELLED_BY_GOOGLE','PAYMENT_DECLINED')
			begin
			select @state_type_id = 1
			end
		else 
			begin
			select @state_type_id = 2
			end
			
		end
	else if  @google_notification_type_id = 7
		begin
		select @vendor_order_code = x.item.value('google-order-number[1]', 'varchar(100)') from @subscription_xml.nodes('//risk-information-notification') AS x(item)
		
		select @serial =(select  data.x.query('data(@serial-number)').value('.', 'varchar(100)') as serial
						from @subscription_xml.nodes('risk-information-notification') data (x))
		end
	
	-- 1.3) @state_type_id
	set @state_type_id = isnull(@state_type_id ,2)
	
	-- 1.4) @google_notification_type_id
	if @google_notification_type_id is null
		begin
		select @google_notification_type_id = 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) check to see if the notification has already been loaded for the serial_number
	select @found = count(*) from google_order_notification where serial_number = @serial

	-- 2.2) insert notification
	if isnull(@found,0) = 0 
		begin
			-- 2.2.1) insert google_order_notification 
			if @google_notification_type_id in (1,2,3) or @state_type_id = 1
				begin
			
				insert into google_order_notification(order_notification_xml, google_notification_type_id, google_order_number,processed, serial_number)
				values(@order_notification_xml, @google_notification_type_id, @vendor_order_code,0,@serial)
				
				select @google_order_notification_id = scope_identity()
				
				select @db_name = db_name()

				insert into [tasks].[dbo].[task_table]([task_number],[Command],[NoTransaction],[StartTime])
				values (@google_order_notification_id,'exec ' + @db_name + '..usp_google_process_xml  ''' + @serial + '''',0,getdate())

				exec tasks..usp_queue_task @google_order_notification_id

				end
			-- 2.2.2) we are parking these for future use
			if @google_notification_type_id in (4,5,6,7) or @state_type_id = 2
				begin
					insert into google_order_notification_parking(order_notification_xml, google_notification_type_id, google_order_number)
					values(@order_notification_xml, @google_notification_type_id, @vendor_order_code)
				end

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert
	-- -----------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) return result
	select response_code = @response_code, message = @message

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_google_load_google_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_google_load_google_order]

/*	
	DATE		 AUTHOR			REMARKS
	2013-11-21	 mrobbins		Initial creation.
	2015-09-08	 esmart			New google order number support
	2018-06-11	 mrobbins		Updated pull to check cart_order doesn't already exist
								Updates status to 2 if it's 0 and cart_order_exists

	DESCRIPTION
	Load cart orders from google_order 
*/

as
	
	begin try
	set nocount on
			
	declare @cart_customer_id			varchar(4000),
			@cart_order_id				int,
			@cart_order_item_id			int,
			@customer_in_process_id		int,
			@task_number				varchar(10),	
			@db_name					varchar(100),
			@system_user				varchar(50),
			@response_code				int,
			@message					varchar(300),
			@id							int,
			@max_id						int,
			@google_order_id			int,
			@vendor_order_code			varchar(50),
			@keycode					varchar(50),
			@order_date					datetime,
			@product_id					int,
			@order_header_id			int,
			@order_status				int
			
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get orders to load
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1) update google order when duplicate
		update o      
		set o.processed = 1
		from google_order o with (nolock)
		inner join vendor_order vo with (nolock)
				on substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number)) = vo.vendor_order_code
		inner join order_header h with (nolock)
				on vo.vendor_order_id = h.vendor_order_id
		where o.order_status_id = 1
			and o.processed = 0
			and h.order_status_id in (1,3)

		-- 1.2) update refunds that are already refunded
		update o      
		set o.processed = 1
		from google_order o with (nolock)
		inner join vendor_order vo with (nolock)
				on substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number)) = vo.vendor_order_code
		inner join order_header h with (nolock)
				on vo.vendor_order_id = h.vendor_order_id
		where o.order_status_id = 3
			and o.processed = 0
			and h.order_status_id = 3

		update o      
		set o.processed = 2
		from google_order o with (nolock)
		inner join cart_order vo with (nolock)
				on substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number)) = vo.vendor_order_code
		where o.processed = 0
		

		declare @google_order table (temp_id int identity(1,1), google_order_id int, vendor_order_code varchar(100), product_id int, keycode varchar(40), order_status_id int, order_date datetime, processed int) 

		-- 1.3) get orders to load
		insert into @google_order(google_order_id, vendor_order_code, product_id, keycode, order_status_id, order_date, processed)
		select g.google_order_id, t.vendor_order_code, p.product_id, g.keycode, g.order_status_id, g.order_date, g.processed
		from google_order g
		inner join (select google_order_id = min(o.google_order_id),
						vendor_order_code = substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number)),
						o.order_status_id
					from google_order o
					where o.processed = 0 
					group by o.order_status_id, substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number))) t
			on g.google_order_id = t.google_order_id
		inner join google_product p

			on g.product = p.google_product
		WHERE NOT EXISTS(SELECT vendor_order_code FROM cart_order co WHERE substring(google_order_number,CHARINDEX('.',google_order_number)+1,len(google_order_number)-CHARINDEX('.',google_order_number)) = co.vendor_order_code)

		--select *
		--from @google_order
		--return

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) process orders
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		select @id = min(temp_id), @max_id = max(temp_id)
		from @google_order
		
		while @id <= @max_id
			begin

			select @google_order_id = google_order_id,
					@vendor_order_code = vendor_order_code,
					@keycode = keycode,
					@order_date = order_date,
					@product_id = product_id,
					@order_status = order_status_id
			from @google_order
			where temp_id = @id

			if @order_status = 1 
			-- 2.0) order
			begin
				
				-- 2.1) insert cart_customer
				insert into cart_customer(customer_in_process_id, external_customer_key, first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, bill_postal_code, bill_country, ship_address_1, ship_address_2, ship_address_3, ship_city, ship_state, ship_postal_code, ship_country, phone_number, fax_number, company_name, customer_email, opt_in, vat_id)
				select 0, @vendor_order_code, NULL, NULL, NULL, NULL, NULL, '', '', '', NULL, NULL, NULL, NULL, '', '', '', NULL, NULL, NULL, NULL, NULL, 0 as opt_in, NULL
		
				select @cart_customer_id = scope_identity()

				-- 2.2) insert cart_order
				insert into cart_order(cart_customer_id,invoice_in_process_id,vendor_order_code,order_type,site_id,site_url,p_rc,p_rsc,p_ac,trx_rc,trx_rsc,trx_ac,aid,pid,sid,offer_id,offer_amount,total_amount,sub_total_amount,tax_amount,payment_method,exchange_rate,session_id,submission_date,sales_order_date,locale,subject,comment,insert_by,modified_by,cart_order_status_id,currency_id,customer_profile_token)
				values(@cart_customer_id,0,@vendor_order_code,'GoogleAndroidMarket','google','WRCART',0,NULL,null,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9.99,9.99,9.99,0.00,0,1.00,0,getdate(),@order_date,'en_US',NULL,NULL,getdate(),'google',1,1,null)
           
				select @cart_order_id  = scope_identity()

					-- 2.2.1) update cart_customer
						update cart_customer
						set cart_order_id = @cart_order_id
						where cart_customer_id = @cart_customer_id
	
				-- 2.3) cart_order_item
				insert into cart_order_item(cart_order_id, invoice_item_in_process_id, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, list_price, unit_price, tax_item_total, tax_exempt, product_id, conversion_product_id, product_locale, insert_date, insert_by, modified_date, modified_by, cart_order_status_id, cart_order_item_in_process_id, cart_item_bundle_id)
				select @cart_order_id,  0, 7, 1, @product_id, 1, NULL, 9.99, 9.99, 9.99, 0.00, 0, @product_id, @product_id, 'En_US', getdate(), 'google', getdate(), 'google', 1, NULL, 1
	
				select @cart_order_item_id  = scope_identity()

				-- 2.4) cart_order_item_license
				insert into cart_order_item_license(cart_order_item_id, keycode)
				select @cart_order_item_id, @keycode

				-- 2.5) load order
				exec usp_cart_load_order @cart_order_id

				select @order_header_id = order_header_id
				from order_header oh 
				inner join vendor_order vo 
					on oh.vendor_order_id = vo.vendor_order_id
				where  vo.vendor_order_code = @vendor_order_code

				-- 2.6) update order license
				exec usp_cart_insert_license_update_queue @order_header_id, 1

			end

			else if @order_status = 3
			-- 3.0) refund
			begin

				-- 3.1) @ord
er_header_id
				select @order_header_id = oh.order_header_id
				from order_header oh inner join vendor_order vo on oh.vendor_order_id = vo.vendor_order_id
				where vendor_order_code = @vendor_order_code
					and order_status_id = 1

				if @order_header_id > 0
				begin
					select @system_user = suser_sname(),@db_name = db_name()

					-- 3.2) process the refund
					exec usp_cart_refund_full @order_header_id, 3, 8, 'usp_google_load_google_order', @system_user 

					-- 3.3) update order license
					exec usp_cart_insert_license_update_queue @order_header_id, 3

				end
			end

			-- 4.0) update google order
			update google_order set processed = 1 where google_order_id = @google_order_id

			select @id = @id + 1

			select @order_header_id = null, @order_status = null

			end	--loop

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'something failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_google_process_notification]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_google_process_notification]

(
	@google_notification_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2018-10-04		cnovac		Initial creation
	2019-01-14		cnovac		Updated logic to do daily check of all non-cancelled orders
	2019-02-20		rvinoche	Change json schema for license_service
	2019-03-20		cnovac		Updated call to license_service which was missed in previous update
	
	DESCRIPTION
	usp_google_process_notification
	
*/

AS

	set nocount on

	begin try

	declare	@order_receipt varchar(100),
			@email varchar(100),
			@order_token varchar(max),
			@merchant_product_id varchar(100),
			@account_hash_id varchar(65),
			@account_order_staging_id int,
			@vendor_order_date datetime,
			@vendor_expiration_date datetime,
			@current_expiration_date datetime,
			@is_trial_to_full_conversion bit,
			@is_product_monthly bit,
			@original_account_order_staging_id int,
			@cancelreason tinyint,
			@license_id int,
			@max_account_order_staging_id int,
			@license_service_json varchar(max),
			@license_service_type_name varchar(50) = 'license_update',
			@license_message_value_str varchar(200),
			@license_message_id int,
			@process_date date = dateadd(dd, 1, getdate()),
			@response_code int,
			@message varchar(100)
	declare @account_order_staging table (account_order_staging_id int)

	select @max_account_order_staging_id = max(aos.account_order_staging_id), @original_account_order_staging_id = min(aos.account_order_staging_id), @license_id = ao.license_id
	from google_notifications gn
	inner join account_order_staging aos on gn.transaction_id = aos.order_receipt
	inner join account_order ao on ao.account_order_staging_id = aos.account_order_staging_id
	where gn.google_notification_id = @google_notification_id
	group by ao.license_id

	select 	@email = aos.email,
			@order_token = aos.order_token,
			@merchant_product_id = aos.merchant_product_id,
			@account_hash_id = aos.account_hash_id,
			@order_receipt = gn.transaction_id,
			@vendor_order_date = dateadd(hh, datediff(hh, getutcdate(), getdate()), gn.purchase_date_utc),
			@vendor_expiration_date = dateadd(hh, datediff(hh, getutcdate(), getdate()), gn.expiration_date_utc),
			@current_expiration_date = aos.vendor_expiration_date,
			@cancelreason = gn.cancel_reason,
			@is_trial_to_full_conversion = iif(l.category_type_name = 'trial', 1, 0)
	from google_notifications gn
	inner join account_order_staging aos on aos.account_order_staging_id = @max_account_order_staging_id
	cross apply fn_license_select_license_profile(@license_id) l
	where gn.google_notification_id = @google_notification_id

	set @is_product_monthly = iif(@merchant_product_id like '%monthly%', 1, 0)

	--this means the record says the user cancelled subscription or subscription did not AR for some reason
	if @cancelreason is not null
	begin
		--look for only WIFI license
		select @license_service_json = 
		(select l.keycode, @license_service_type_name as account_name, 
			(select l.license_category_name, @vendor_expiration_date as expiration_date for json path) license_category
		from fn_license_select_license_profile(@license_id) l
		where l.license_category_name = 'WIFI'
		for json path, without_array_wrapper)

		if @license_service_json is not null
		begin
			exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @license_service_json, @return_license_service_id = 0

			exec usp_account_update_account_order_staging @account_order_staging_id = @max_account_order_staging_id, @google_notification_id = @google_notification_id
		end

	end
	--check to see if the AR hasn't happened on the Google side yet.  If it hasn't been cancelled and hasn't
 extended one month/year, just check again next day
	else if (@is_product_monthly = 1 and datediff(mm, cast(@current_expiration_date as date), cast(@vendor_expiration_date as date)) < 1) or
			(@is_product_monthly = 0 and datediff(yy, cast(@current_expiration_date as date), cast(@vendor_expiration_date as date)) < 1)
	begin
		--insert a new record into license_message
		set @license_message_value_str = 'account_order_staging_id=' + ltrim(rtrim(str(@max_account_order_staging_id)))
		exec usp_message_insert_license_message @license_id, 18, @process_date, @process_date, @process_date, @license_message_value_str, @license_message_id output, @return_result = 0

		--look to see if the max expiration date(+1) from receipt doesn't match the license expiration_date
		select @license_service_json = 
		(select l.keycode, @license_service_type_name as account_name, 
			(select l.license_category_name, dateadd(dd, 1, @vendor_expiration_date) as expiration_date for json path) license_category
		from fn_license_select_license_profile(@license_id) l
		where l.license_category_name = 'WIFI'
		for json path, without_array_wrapper)

		if @license_service_json is not null
			exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @license_service_json, @return_license_service_id = 0

	end
	else if @account_hash_id is not null
	begin
		insert into @account_order_staging (account_order_staging_id)
		exec usp_account_insert_account_order_staging @merchant_id = 'google_store', @email = @email, @order_token = @order_token, @merchant_product_id = @merchant_product_id, @account_hash_id = @account_hash_id, @google_notification_id = @google_notification_id, @original_account_order_staging_id = @original_account_order_staging_id, @is_trial_to_full_conversion = @is_trial_to_full_conversion, @vendor_order_date = @current_expiration_date, @vendor_expiration_date = @vendor_expiration_date, @order_receipt = @order_receipt

		select @account_order_staging_id = account_order_staging_id from @account_order_staging
		exec usp_account_insert_account_order_staging_log @account_order_staging_id = @account_order_staging_id, @account_order_api_reference_id = 7, @account_order_api_status = 1, @account_order_api_message = 'Success'

	end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_google_process_notification'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	
	end catch;





GO
