-- =============================================================================

CREATE PROCEDURE [dbo].[usp_incomm_license_insert_target]

(
		@serial_number varchar(20),
		@incomm_merchant_name varchar(50),
		@license_category varchar (4) = null,
		@incomm_product_status_id int = null,
		@barcode varchar(20) = null,
		@currency varchar(3) = null,
		@upc varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-09-27	acoffel		Initial creation.
	2012-01-12	acoffel		New JPN incomm provider
	2014-10-07	acoffel		BB Incomm Gamer
	2015-07-31	acoffel		Gamestop

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@keycode varchar(40),
			@serial_number_check varchar(20),
			@license_distribution_method_code char (4),
			@license_distribution_method_id int,
			@product_id int,
			@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

					
	-- 1.0) check to see if customer email exists and return keycode
		select @serial_number_check = serial_number 
		from incomm_license_status with (nolock)
		where serial_number = @serial_number

	-- 1.1) if serial number already used - return entries and kill process
		if @serial_number_check is not null
			begin
				select 'already entered with following entries' as response_code, i.merchant_name, l.keycode, i.serial_number, i.incomm_product_status_id as current_incomm_product_status_id
				from incomm_license_status i
				left join license l
					on i.license_id = l.license_id 
				where i.serial_number = @serial_number_check 
			return
		end
	
	-- 1.2) if license_category is NULL
		if @license_category is NULL
			begin 	
				select @license_category = 'WSAC'
			end

	-- 1.3) check for BB gamer call
		if @incomm_merchant_name in ('Best Buy', 'GameStop', 'Barnes and Noble CB', 'Apple Campus Stores')
			begin
				select @license_category = 'WSAV'
				select @incomm_product_status_id = 4003
			end

	-- 1.4) set disti code per merchant
		select @license_distribution_method_code = license_distribution_method_code, @product_id = product_id
		from lu_disti_by_incomm_merchant with (nolock)
		where incomm_merchant_name = @incomm_merchant_name
		and license_category = @license_category

	-- 1.5) set disti_id per disti code
		select @license_distribution_method_id = license_distribution_method_id 
		from license_distribution_method with (nolock)
		where license_distribution_method_code = @license_distribution_method_code

	--select @product_id, @license_distribution_method_code
	
	-- 1.6) set intl product_id. currently japan only
		if @upc is not NULL 
			begin
			select @product_id = product_id
			from lu_incomm_upc_to_product_id
			where upc = @upc
			end	



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) create keycode
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) create keycode table
	declare @keycode_table table (keycode varchar(40))

	if @serial_number_check is NULL --and @upc is NULL
		
		begin

		insert into @keycode_table
		exec usp_license_insert_license_cart @product_id,@license_distribution_method_id,1,@response_code OUTPUT,@message OUTPUT

		select @keycode = keycode from @keycode_table

		select @license_i
d = license_id from license with(nolock) where keycode = @keycode
				
				if @incomm_merchant_name in ('Best Buy', 'GameStop')
					begin
						insert into license_module_license (license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by)
						select @license_id, 12, 1, NULL, NULL, getdate(), 'system_user'
					end 
		end

	
	---- 2.2) create keycode table for Japan transactions
	--if @serial_number_check is NULL and @upc is not NULL
		
	--	begin

	--	insert into @keycode_table
	--	exec usp_license_insert_license_cart @product_id,@license_distribution_method_id,1,@response_code OUTPUT,@message OUTPUT

	--	select @keycode = keycode from @keycode_table

	--	select @license_id = license_id from license with(nolock) where keycode = @keycode
		
	--	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert record into incomm_license_status
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 3.1) insert into incomm_license_status
			insert into incomm_license_status (license_id, serial_number, merchant_name, incomm_product_status_id, insert_date, insert_by, modified_date, modified_by)
			select @license_id, @serial_number, @incomm_merchant_name, @incomm_product_status_id, getdate() as insert_date, system_user as insert_by, getdate() as modified_date, system_user as modified_by

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 4.1) return keycode
			select keycode = @keycode, response_code = @response_code, [message] = @message


	end try

	begin catch

		set @response_code = -300
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_incomm_license_status_select]
-- =============================================================================

CREATE procedure [dbo].[usp_incomm_license_status_select]
(	
@keycode varchar(40) = null,
@serial_number varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-09-27	acoffel		Initial creation.
	2015-10-28	acoffel		Support of new Incommm page

	DESCRIPTION
	
*/

as  

set nocount on

	declare @license_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--1.1 find license_id
	select @license_id = license_Id 
	from license with(nolock)
	where keycode = @keycode

	if (select @keycode) is not NULL
	
	begin

	select l.keycode, s.incomm_license_status_id, s.license_id, s.serial_number, s.barcode, s.merchant_name, s.incomm_product_status_id, 
	c.license_category_description, case when m.license_id is not NULL then 'Gamer Product' else 'Standard WSA' end as incomm_product_type, 
	s.insert_date, s.insert_by, s.modified_date, s.modified_by
	from incomm_license_status s
	inner join license l
		on s.license_id = l.license_id
	inner join license_category_license cl
		on l.license_id = cl.license_id
	inner join license_category c
		on cl.license_category_id = c.license_category_id
	left join license_module_license m
		on l.license_id = m.license_id and m.license_module_id = 12
	where s.license_id = @license_id

end
	else
	begin

	select l.keycode, s.incomm_license_status_id, s.license_id, s.serial_number, s.barcode, s.merchant_name, s.incomm_product_status_id, 
	c.license_category_description, case when m.license_id is not NULL then 'Gamer Product' else 'Standard WSA' end as incomm_product_type, 
	s.insert_date, s.insert_by, s.modified_date, s.modified_by
	from incomm_license_status s
	inner join license l
		on s.license_id = l.license_id
		inner join license_category_license cl
		on l.license_id = cl.license_id
	inner join license_category c
		on cl.license_category_id = c.license_category_id
	left join license_module_license m
		on l.license_id = m.license_id and m.license_module_id = 12
	where s.serial_number = @serial_number

end

	end try


begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_incomm_license_status_update_product_status]
-- =============================================================================

CREATE procedure [dbo].[usp_incomm_license_status_update_product_status]

(
	@keycode varchar(40),
	@incomm_product_status_id int,
	@response_code int output,
	@message varchar(200) output
)

/*	
	DATE		AUTHOR		REMARKS
	2010-10-12	acoffel		Initial creation.
	2021-03-25	esmart		Changes needed for new Incomm implementation

	DESCRIPTION
	Update status on incomm_license_status
*/

as

declare @license_id int,
		@license_status_id int,
		@user varchar(20),
		@dt datetime,
		@incomm_license_status_id int,
		@current_incomm_product_status_id int,
		@update_attempts tinyint,
		@max_update_attempts tinyint,
		@retry_interval tinyint,
		@license_service_type_name varchar(50), 
		@service_json nvarchar(max), 
		@return_license_service_id bit

begin try	

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @user = system_user, @dt = getdate(), @max_update_attempts = 3, @retry_interval = 240 -- minutes

	-- 1.1) @license_id
	select @license_id = l.license_id, @license_status_id = l.license_status_id
	from license l
	where keycode = @keycode

	if @license_id is null
	begin
		set @response_code = -100
		set @message = 'Invalid Keycode'
		raiserror('Invalid Keycode',16,1)
		return
	end

	-- 1.2) @incomm_license_status_id
	select @incomm_license_status_id = s.incomm_license_status_id, @current_incomm_product_status_id = s.incomm_product_status_id, @update_attempts = s.update_attempts
	from incomm_license_status s
	where s.license_id = @license_id

	if @incomm_license_status_id is null
	begin
		set @response_code = -110
		set @message = 'Invalid incomm_license_status_id'
		raiserror('Invalid incomm_license_status_id',16,1)
		return
	end

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) successful redeem
	if @current_incomm_product_status_id = 4001 and @incomm_product_status_id = 4003
		begin
			insert into incomm_license_status_history(incomm_license_status_id,license_id,serial_number,barcode,merchant_name,incomm_product_status_id,update_attempts,process_date,insert_date,insert_by,modified_date,modified_by,history_date,history_by)
			select i.incomm_license_status_id, i.license_id, i.serial_number, i.barcode, i.merchant_name, i.incomm_product_status_id, i.update_attempts, i.process_date, i.insert_date, i.insert_by, i.modified_date, i.modified_by, @dt, @user
			from incomm_license_status i
			where incomm_license_status_id = @incomm_license_status_id

			update incomm_license_status
			set incomm_product_status_id = @incomm_product_status_id,
					process_date = null,
			 		modified_by = @user,
			 		modified_date = @dt
			where incomm_license_status_id = @incomm_license_status_id
		end

	-- 2.2) fraud
	else if @current_incomm_product_status_id = 4001 and @incomm_product_status_id = 4002
		begin
			-- 2.2.1) incomm_license_status_history
			insert into incomm_license_status_history(incomm_license_status_id,license_id,serial_number,barcode,merchant_name,incomm_product_status_id,update_attempts,process_date,insert_date,insert_by,modif
ied_date,modified_by,history_date,history_by)
			select i.incomm_license_status_id, i.license_id, i.serial_number, i.barcode, i.merchant_name, i.incomm_product_status_id, i.update_attempts, i.process_date, i.insert_date, i.insert_by, i.modified_date, i.modified_by, @dt, @user
			from incomm_license_status i
			where incomm_license_status_id = @incomm_license_status_id

			-- 2.2.2) update
			if @update_attempts >= @max_update_attempts
				begin
					select  @license_service_type_name = 'license_disable', @return_license_service_id = 0
					select @service_json = (select @keycode as keycode for json path, without_array_wrapper)
					exec usp_license_service_insert_service @license_service_type_name=@license_service_type_name,@service_json=@service_json,@return_license_service_id=@return_license_service_id
					
					update incomm_license_status
					set update_attempts = update_attempts + 1,
						process_date = null,
						incomm_product_status_id = @incomm_product_status_id,
						modified_by = @user,
						modified_date = @dt
					where incomm_license_status_id = @incomm_license_status_id
				end
			else
				begin
					update incomm_license_status
					set update_attempts = update_attempts + 1,
						process_date = dateadd(mi,@retry_interval,getdate()),
						modified_by = @user,
						modified_date = @dt
					where incomm_license_status_id = @incomm_license_status_id

				end
		end

	-- 2.3) successful undo redeem
	else if @current_incomm_product_status_id = 4003 and @incomm_product_status_id in (4001,4002)
		begin
			insert into incomm_license_status_history(incomm_license_status_id,license_id,serial_number,barcode,merchant_name,incomm_product_status_id,update_attempts,process_date,insert_date,insert_by,modified_date,modified_by,history_date,history_by)
			select i.incomm_license_status_id, i.license_id, i.serial_number, i.barcode, i.merchant_name, i.incomm_product_status_id, i.update_attempts, i.process_date, i.insert_date, i.insert_by, i.modified_date, i.modified_by, @dt, @user
			from incomm_license_status i
			where incomm_license_status_id = @incomm_license_status_id

			update incomm_license_status
			set incomm_product_status_id = @incomm_product_status_id,
					process_date = null,
			 		modified_by = @user,
			 		modified_date = @dt
			where incomm_license_status_id = @incomm_license_status_id
		end

	-- 2.4) 
	else
		begin
			-- 2.1.1) incomm_license_status_history
			insert into incomm_license_status_history(incomm_license_status_id,license_id,serial_number,barcode,merchant_name,incomm_product_status_id,update_attempts,process_date,insert_date,insert_by,modified_date,modified_by,history_date,history_by)
			select i.incomm_license_status_id, i.license_id, i.serial_number, i.barcode, i.merchant_name, i.incomm_product_status_id, i.update_attempts, i.process_date, i.insert_date, i.insert_by, i.modified_date, i.modified_by, @dt, @user
			from incomm_license_status i
			where incomm_license_status_id = @incomm_license_status_id

			-- 2.1.2) update
			if @update_attempts >= @max_update_attempts
				begin
					update incomm_license_status
					set update_attempts = update_attempts + 1,
						process_date = null,
						modified_by = @user,
						modified_date = @dt
					where incomm_license_status_id = @incomm_license_status_id
				end
			else
				begin
					update incomm_license_status
					set update_attempts = update_attempts + 1,
						process_date = dateadd(mi,@retry_interval,getdate()),
						modified_by = @user,
						modified_date = @dt
					where incomm_license_status_id = @incomm_license_status_id

				end

			end

	select @response_code = 0, @message = 'Update Completed Successfully'

end try

begin catch
	
	set @response_code =  case when @response_code is null then -200 else @response_code end
	set @message = case when @message is null then 'Update Failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName 
= db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch

GO
