-- PROCEDURE: [dbo].[usp_incomm_log_insert]
-- =============================================================================

CREATE procedure [dbo].[usp_incomm_log_insert]
	@keycode varchar(40),
	@transaction_reference varchar(64),
	@merchant_name varchar(50),
	@request_action varchar(50),
	@php_message varchar(200),
	@source varchar(32),
	@redeem_timeout tinyint = 0,
	@response_code int output,
	@message varchar(200) output
As
/*
2010-09-20	dsmelker	Created

Purpose: Insert incomm_log record

*/
Begin

Declare 
				@user varchar(20),
				@dt datetime
				
set @user = system_user
set @dt = getdate()				


Begin try
	
insert into incomm_log
(keycode,transaction_reference,merchant_name,
 request_action,message,source,insert_date,insert_by,redeem_timeout)
values
(@keycode,@transaction_reference,@merchant_name,
 @request_action,@php_message,@source,@dt,@user,@redeem_timeout)

select @response_code = 0, @message = 'Insert Completed Successfully'

end try

Begin catch
	
	
	set @response_code =  -200
	set @message = 'Insert Failed'

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch


End

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_incomm_log_select_redeem_timeout]
-- =============================================================================

create procedure [dbo].usp_incomm_log_select_redeem_timeout
	@merchant_name varchar(50),
	@record_set int = 1000
As
/*
2010-09-20	dsmelker	Created

Purpose: Pull top 1000 records that have a redeem_timeout = 1

*/
Begin


select top (@record_set)
	incomm_log_id, keycode
from dbo.incomm_log
where redeem_timeout = 1
order by insert_date


End

GO
