create procedure [dbo].[usp_incomm_log_update_redeem_timeout]
	@incomm_log_ids varchar(max),
	@response_code int output,
	@message varchar(200) output
As
/*
2010-09-20	dsmelker	Created

Purpose: Update redeem_timeout for a string of incomm_log_ids

*/
Begin

declare @sql varchar(max)

Begin Try

set @sql = 'update incomm_log
