			where incomm_log_id in (' + @incomm_log_ids + ')'

--print @sql

exec (@sql)


select @response_code = 0, @message = 'Update Completed Successfully'



End Try

Begin Catch

	
	set @response_code =  -200
	set @message = 'Insert Failed'

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	

End Catch

End

GO
