-- PROCEDURE: [dbo].[usp_incomm_response_insert]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_incomm_response_insert]
(
  	@response_incomm_code int,
	@response_message varchar(50),
	@face_value money,
	@upc varchar(30),
	@store_number varchar(20),
	@merchant varchar(50),
	@pin varchar(20),
	@partner_name varchar(20),
	@serial_number varchar(20),
	@authorization_code varchar (20) = NULL,
	@response_code int output,
	@message varchar(100) output

)

/*
   DATE            AUTHOR         REMARKS
   2016-02-02      acoffel        Initial creation

   DESCRIPTION
   insert incomm response

*/

AS

	set nocount on

		begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		insert into incomm_response (response_incomm_code, response_message, face_value, upc, store_number, merchant, pin, partner_name, serial_number, authorization_code, insert_date, insert_by)
		select @response_incomm_code, @response_message, @face_value, @upc, @store_number, @merchant, @pin, @partner_name, @serial_number, @authorization_code, getdate(), system_user



		end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_incomm_select_next_incomm_license_status]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_incomm_select_next_incomm_license_status]

/*	
	DATE		AUTHOR		REMARKS
	2021-03-25	jberry		Initial creation.

	DESCRIPTION
	return incomm license records to cron that are active
*/

AS

	declare	@response_code int,
			@message varchar(100)

begin try

	declare @incomm_license_status table (incomm_license_status_id int, license_id int, keycode varchar(40), incomm_product_status_id int, incomm_product_status_description varchar(50), license_status_id int, license_status_description varchar(50), process_date datetime)

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) active license needing redeem
	insert into @incomm_license_status(incomm_license_status_id,license_id,keycode,incomm_product_status_id,incomm_product_status_description,license_status_id,license_status_description, process_date)	
	select s.incomm_license_status_id, l.license_id, l.keycode, ps.incomm_product_status_id, ps.incomm_product_status_description, ls.license_status_id, ls.license_status_description, s.process_date
	from incomm_license_status s
	inner join incomm_product_status ps
		on ps.incomm_product_status_id = s.incomm_product_status_id
	inner join license l
		on l.license_id = s.license_id
	inner join license_status ls
		on ls.license_status_id = l.license_status_id
	where s.incomm_license_status_id >= 618488 and s.incomm_product_status_id = 4001 and l.license_status_id = 1 and s.process_date < getdate()

	-- 1.2) disabled licenses needing undo redeem
	insert into @incomm_license_status(incomm_license_status_id,license_id,keycode,incomm_product_status_id,incomm_product_status_description,license_status_id,license_status_description, process_date)	
	select s.incomm_license_status_id, l.license_id, l.keycode, ps.incomm_product_status_id, ps.incomm_product_status_description, ls.license_status_id, ls.license_status_description, s.process_date
	from incomm_license_status s
	inner join incomm_product_status ps
		on ps.incomm_product_status_id = s.incomm_product_status_id
	inner join license l
		on l.license_id = s.license_id
	inner join license_status ls
		on ls.license_status_id = l.license_status_id
	where s.incomm_license_status_id >= 618488 and s.incomm_product_status_id = 4003 and l.license_status_id <> 1 and s.process_date < getdate()

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return next update
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top(1) incomm_license_status_id,license_id,keycode,incomm_product_status_id,incomm_product_status_description,license_status_id,license_status_description, process_date
	from @incomm_license_status s
	order by s.process_date

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_incomm_update_incomm_license_status_batch]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_incomm_update_incomm_license_status_batch]

/*	
	DATE		AUTHOR		REMARKS
	2021-03-25	jberry		Initial creation.

	DESCRIPTION
	update incomm licenses that are inactive to active
*/

AS

	declare	@response_code int,
			@message varchar(100)

begin try

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update incomm_license_status
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) update inactive incomm licenses to active
	update s
	set s.incomm_product_status_id = 4001, s.update_attempts = 0, s.process_date = getdate(), s.modified_date = getdate(), s.modified_by = 'license_batch'
	from incomm_license_status s
	inner join license l
		on l.license_id = s.license_id
	inner join license_category_license cl
		on cl.license_id = s.license_id
	where s.incomm_license_status_id >= 618488 and s.incomm_product_status_id in (4001,4002) and l.license_status_id = 1 and cl.end_date is not null and s.process_date is null

	-- 1.2) update redeemed keycode process date if they have been disabled.
	update s
	set s.update_attempts = 0, s.process_date = getdate(), s.modified_date = getdate(), s.modified_by = 'license_batch'
	from incomm_license_status s
	inner join license l
		on l.license_id = s.license_id
	inner join license_category_license cl
		on cl.license_id = s.license_id
	where s.incomm_license_status_id >= 618488 and s.incomm_product_status_id = 4003 and l.license_status_id <> 1 and cl.end_date is not null and s.process_date is null


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
