-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_bulk_licenses]
-- =============================================================================

CREATE procedure [dbo].[usp_insert_bulk_licenses]
(
	@license_bulk_load_id int,
	@system_user varchar(50)
)

AS
/*	
	DATE			AUTHOR		REMARKS
	2008-01-21		mscardino	Initial creation
	2008-07-15		esmart		Add support for license_storage
	2010-01-11		acoffel		Add serial number support for disti codes 355,357 (BBSI,BBSA) 
	2010-04-24		esmart		Modify serial number generation to be standarized result
	2010-05-05		dsmelker	Modified the license_distribution_method_id lookup for BBY to be table driven
	2011-03-24		esmart		Add Prevx queue support
	2012-05-31		esmart		Support for product_license_module
	2012-07-25		esmart		SA13 for BBY
	2012-09-26		esmart		WSAI with SA in serial_number

	DESCRIPTION
	Create bulk keycodes 
*/

set nocount on

declare @keycode_count int,
	@quantity int,
	@product_id int,
	@license_keycode_type_id int,
	@product_line_id int,
	@insert_date datetime,
	@keycode_sequence_id bigint,
	@keycode varchar(40),
	@seats int,
	@license_status_id int,
	@license_type_id int,
	@license_distribution_method_id int,
	@max_daily_activations int,
	@max_child_licenses int,
	@license_expiration_date datetime,
	@license_bulk_status_id int,
	@response_code int,
	@message varchar(100) 

set @keycode_count = 0
set @insert_date = getdate()

set @license_bulk_status_id = (select license_bulk_status_id from license_bulk_status where license_bulk_status_description = 'creating licenses')

update
	license_bulk_load
set
	license_bulk_status_id = @license_bulk_status_id
where
	license_bulk_load_id = @license_bulk_load_id


	

begin try

	begin transaction

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Insert preliminary license_bulk_load_license records
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select 
		@product_id = product_id,
		@license_keycode_type_id = license_keycode_type_id,
		@quantity = quantity,
		@product_line_id = product_line_id,
		@license_status_id = license_status_id,
		@license_type_id = license_type_id,
		@license_distribution_method_id = license_distribution_method_id,
		@max_daily_activations = max_daily_activations,
		@max_child_licenses = max_child_licenses,
		@license_expiration_date = license_expiration_date
	from 
		license_bulk_load 
	where 
		license_bulk_load_id = @license_bulk_load_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Insert preliminary license_bulk_load_license records
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @product_line_id in (300,55)
		begin
		exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output

		insert into license_bulk_load_license (license_bulk_load_id, keycode, product_id, insert_date)
		values (@license_bulk_load_id, @keycode, @product_id, @insert_date)
		end
	else
		begin
			while @keycode_count < @quantity
			begin

				set @keycode_count = @keycode_count + 1

				if @license_keycode_type_id = 1
				begin
					exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
				end
	
			else if @license_keycode_type_id = 2
				begin 
					exec usp_license_generate_enterprise_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
				end
				
				insert into license_bulk_load_license (license_bulk_load_id, keycode, product_id, insert_date)
				values (@license_bulk_load_id, @keycode, @product_id, @insert_date)

			end
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) Insert license records and update license_bulk_load_license with new license_id's 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by)
		select 	l.keycode,
			b.product_line_id,
			license_status_id = 0,
			b.license_type_id,
			b.license_distribution_method_id,
			b.max_daily_activations,
			b.max_child_licenses, 
			b.license_expiration_date,
			b.insert_date,
			b.insert_by,
			b.modified_date,
			b.modified_by
		from license_bulk_load_license l
		inner join license_bulk_load b
			on l.license_bulk_load_id = b.license_bulk_load_id
		where l.license_bulk_load_id = @license_bulk_load_id
		
		update license_bulk_load_license
		set license_id = l.license_id
		from license_bulk_load_license b
		inner join license l
			on b.keycode = l.keycode
		where license_bulk_load_id = @license_bulk_load_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4) Insert license_capability records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
	select license_id, 
		capability_id, 
		capability_type_id, 
		capability_activation_days,
		insert_date = @insert_date,
		insert_by = @system_user,
		modified_date = @insert_date,
		modified_by = @system_user		
	from license_bulk_load_license b
	inner join product_capability c
		on b.product_id = c.product_id
	where license_bulk_load_id = @license_bulk_load_id
	order by b.license_id, c.capability_id
	

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5) Insert license_seat records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- @seats 
	select @seats = isnull(seats,0)
		from product_seat
		where product_id = @product_id

	
	if @product_line_id in (11,13,300,55) 
		begin
			insert into license_seat (license_id, license_seats)
			select license_id, @quantity
			from license_bulk_load_license b
			where license_bulk_load_id = @license_bulk_load_id
		end

	if @product_line_id not in (11,13,300,55) and @seats > 0
		begin
			insert into license_seat (license_id, license_seats)
			select license_id, @seats
			from license_bulk_load_license b
			where license_bulk_load_id = @license_bulk_load_id
		end


	-------------
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8) Insert license_storage records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @storage_gb int

	select @storage_gb = storage_gb
	from product_storage
	where product_id = @product_id

	if @storage_gb is not null
		begin
			insert into license_storage (license_id, storage_gb)
			select license_id, @storage_gb
			from license_bulk_load_license
			where license_bulk_load_id = @license_bulk_load_id
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8) Insert license_storage records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @license_distribution_method_id in (select license_distribution_method_id from subscription_distribution_method)
		begin
				insert into subscription (subscription_type_id, license_id, serial_number, insert_date)
				select subscription_type_id = 0, 
						license_id, 
						serial_number = 'WBR00'+
										case when license_category_id = 1 then 'AS'
												when license_category_id = 2 then 'AV'
												when license_category_id = 100 or license_category_id = 115 then 'SA'
												when license_category_id = 3 or license_category_id = 110then 'IS'
												when license_category_id = 4 or license_category_id = 120 then 'SC'
										 end+
										'14'+--right(convert(varchar(4),datepart(yy,getdate())),2)+
										'00'+
										convert(varchar(8),bl.license_id),
						insert_date = getdate()
				from license_bulk_load b
				inner join product_license_category c
					on b.product_id = c.product_id
				inner join license_bulk_load_license bl
					on b.license_bulk_load_id = bl.license_bulk_load_id
				where b.license_bulk_load_id = @license_bulk_load_id
		end
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9) insert license_category 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @license_category_id int

	select @license_category_id = license_category_id
	from product_license_category
	where product_id = @product_id
	
	if @license_category_id is not null 
		begin
			insert into license_category_license (license_id, license_category_id)
			select bl.license_id, @license_category_id
			from license_bulk_load b
			inner join license_bulk_load_license bl
				on b.license_bulk_load_id = bl.license_bulk_load_id
			where b.license_bulk_load_id = @license_bulk_load_id
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 10) insert license_module_license 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into license_module_license(license_id,license_module_id,license_module_type_id)
	select b.license_id, m.license
_module_id, m.license_module_type_id
	from license_bulk_load_license b
	inner join product_license_module m
		on b.product_id = m.product_id
	where license_bulk_load_id = @license_bulk_load_id
	order by b.license_id, m.license_module_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 11) insert prevx queue
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @product_line_id in (100,200,300,55)
		begin
		insert into prevx_update(license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
		select b.license_id, b.license_bulk_load_id, prevx_update_type_id = 100, prevx_update_status_id = 0, insert_date = @insert_date, modified_date = @insert_date, process_date = @insert_date
		from license_bulk_load_license b
		left join prevx_update u
			on b.license_id = u.license_id
		where b.license_bulk_load_id = @license_bulk_load_id and u.prevx_update_id is null
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 12) complete 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	set @license_bulk_status_id = (select license_bulk_status_id from license_bulk_status where license_bulk_status_description = 'licenses created')

	update
		license_bulk_load
	set
		license_bulk_status_id = @license_bulk_status_id

	commit transaction

end try 
begin catch
	
	if @@trancount > 0 
		rollback transaction
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	update
		license_bulk_load
	set
		license_bulk_status_id = 0
	where
		license_bulk_load_id = @license_bulk_load_id
	
end catch;


GO
