-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_customer_phone_clean]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_insert_customer_phone_clean]

-- =============================================
-- Author:		ACoffel
-- Create date: 6/11/2010
-- Description:	For looking up JPN customer by phone number
-- =============================================
as

set nocount on

truncate table customer_phone_clean

insert into customer_phone_clean
select cp.customer_id, cp.phone_number, dbo.fn_removechars(cp.phone_number) as phone_number_clean
from customer_phone cp with (nolock)
inner join
	customer_email ce with (nolock)
	on cp.customer_id = ce.customer_id
where 
	ce.customer_email like '%.jp'
union all
select ca.customer_id, cp.phone_number, dbo.fn_removechars(cp.phone_number) as phone_number_clean
from customer_address ca with (nolock)
inner join
	customer_phone cp with (nolock)
	on ca.customer_id = cp.customer_id
where 
	ca.country_id = 109


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_email_receipts_dl_instructions]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_insert_email_receipts_dl_instructions]

(
		@customer_email varchar(100),
		@license_id int = NULL,
		@order_header_id int = NULL,
		@email_message_name varchar(65), 
		@email_message_body nvarchar(max) = NULL,
		@email_message_status_id tinyint = NULL 

)

/*	
	DATE		 AUTHOR			REMARKS
	2013-09-27	 acoffel		Initial creation.
	2014-06-18	 acoffel		temp paypal exclusion
	2014-06-18	 surpal		    comment out - temp paypal exclusion
	2014-10-29	 acoffel		added order_header_id to insert
	2015-11-03	 esmart			Support NULL @email_message_body
	2016-02-04	 acoffel		variabilize @email_message_status_id
	2016-02-12	 acoffel		patch for NULL emails
	2018-05-25	 mrobbins		extended @email_message_name to 65 for message_campaign_name

	DESCRIPTION
	
*/


AS
	set nocount on				

		
		declare	@email_message_id int,
				@message_campaign_id int,
				@response_code int, 
				@message varchar(100),
				@paypal_email_check varchar(100)

			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- temp paypal recovery
	/*	select @paypal_email_check = customer_email from paypal_customer_email where customer_email = @customer_email
		
		if @paypal_email_check is not NULL
			begin 
				select 000 as email_message_id
				return
			end*/
	
	if @email_message_status_id is NULL
		begin
		select @email_message_status_id = 1
		end

	if @email_message_body is null
		begin
		select @email_message_body = ''
		end

	--1.0) get message_campaign_id
		select @message_campaign_id = message_campaign_id
		from message_campaign 
		where message_campaign_name = @email_message_name

	-- 1.1) insert into email_message
		insert into email_message (license_id, message_campaign_id, email_message_status_id, insert_date, process_date, order_header_id)
		select @license_id, @message_campaign_id, @email_message_status_id, getdate(), getdate(), @order_header_id

		select @email_message_id = scope_identity()

	--1.2) insert email and html 
		insert into email_message_html (email_message_id, customer_email, email_message_body)
		select @email_message_id, @customer_email, @email_message_body

	--1.3) mark as failed if customer_email is NULL
		if (select customer_email from email_message_html where email_message_id = @email_message_id) is NULL
			begin 
				update email_message set email_message_status_id = 3 where email_message_id = @email_message_id
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return email_message_id to php
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) return email_message_id
		select @email_message_id as email_message_id
		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_purchase_order]
-- =============================================================================

CREATE procedure [dbo].[usp_insert_purchase_order]

(
	@order_header_id int,
	@vendor_order_code varchar(100),
	@purchase_order varchar(40),
	@purchase_order_date datetime, 
	@response_code int output,
	@message varchar(100) output
)

/*
	06/14/2011	acoffel		force purchase order entry

*/

as

set nocount on

begin try

	-- 1.1) select @order_header_id
	select @order_header_id = (select order_header_id 
									from order_header oh
									inner join vendor_order vo
										on oh.vendor_order_id = vo.vendor_order_id
									where vendor_order_code = @vendor_order_code)

	-- 1.2) insert purchase_order
	insert into purchase_order (order_header_id, purchase_order, purchase_order_date)
	values (@order_header_id, @purchase_order, @purchase_order_date)
	
end try

begin catch
	
   if @@trancount > 0
	      rollback transaction;	

	select @response_code, @message
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_sky_license_install]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_insert_sky_license_install]

AS

/*

	DATE			AUTHOR			REMARKS
	2019-10-07		mrobbins		Initial creation
	2021-03-09		abelenkiy		Added description and section 2.2 for S2 redemption notification
									set transaction isolation level read uncommitted
									wrapped proc begin/end
						

	DESCRIPTION
	Process to populate license_install table from skylake. This procedure is called by a job that runs 
	a procedure with the same name in Feed. That procedure populates SKYLAKE/Feed.dbo.license_install_update,
	then this procedure pulls the data into ecommerce.dbo.license_install_update (same table name) and either 
	inserts new record into license_install or updates existing record.

	Section 2.2 was added to insert new BBY/S2 license installation records into the sky_update queue so the 
	BBY license redemption endpoint can be notified. This primarily happens via a different process which runs
	every two hours but that code needed to be put here as well to avoid potential timing issues (since the 
	same license_install table is being populated in both processes). That entire process is outlined in the 
	description of ecommerce.dbo.usp_insert_sky_s2_license_redemption.

*/

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 1.) select - pulls records from feed db on sky
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

begin

	set nocount on 

	set transaction isolation level read uncommitted

	truncate table license_install_update

	INSERT INTO dbo.license_install_update
	(
		license_id,
		keycode,
		first_install_date,
		latest_install_date,
		log_date,
		[update],
		insert_date,
		insert_by,
		modified_date,
		modified_by
	)
	SELECT license_id,
		keycode,
		first_install_date,
		latest_install_date,
		log_date,
		[update],
		insert_date,
		insert_by,
		modified_date,
		modified_by
	FROM skylake.feed.dbo.license_install_update


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.1) insert records not yet existing in license_install

	INSERT INTO dbo.license_install
	(
		license_id,
		first_install_date,
		latest_install_date,
		log_date
	)
	SELECT license_id,
		first_install_date,
		latest_install_date,
		log_date
	FROM dbo.license_install_update
	WHERE [update] = 0

	-- 2.2) insert above records with subscription into sky_update queue for S2 redemption notification
	insert into sky_update (license_id, sky_template_id, sky_update_type_id, process_date)
	output Inserted.license_id, object_name(@@procid)
	into s2_license_redemption_log (license_id, source)
	select liu.license_id, 14, 14, dateadd(minute, 5, getdate())
	from license_install_update liu
		inner join subscription s
			on s.license_id = liu.license_id
		left join sky_update su
			on su.license_id = s.license_id
			and su.sky_template_id = 14 --s2_redemption
	where su.sky_update_id is null
		and liu.[update] = 0

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------
-------------------------------------
	-- 3.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	UPDATE li
	SET li.first_install_date = liu.first_install_date,
		li.latest_install_date = liu.latest_install_date,
		li.log_date = liu.log_date,
		li.modified_date = GETDATE(),
		li.modified_by = SYSTEM_USER
	FROM dbo.license_install_update liu
		INNER JOIN dbo.license_install li
			ON liu.license_id = li.license_id
	WHERE liu.[update] = 1

	end


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_insert_sky_s2_license_redemption]
-- =============================================================================

CREATE procedure [dbo].[usp_insert_sky_s2_license_redemption]
as

    /*

	DATE			AUTHOR			REMARKS
	2021-03-03		abelenkiy		Initial creation 
	2021-04-23		abelenkiy		Fixed join to license_install in section 2 to prevent duplicates


	DESCRIPTION
	Second step of process to populate ecommerce.dbo.license_install with BBY/S2 keys installed in the last 
	two hours. 

	The following description is copy/pasted in SKYLAKE/Feed.dbo.usp_insert_sky_s2_license_redemption_raw 
	and ecommerce.dbo.usp_insert_sky_s2_license_redemption.
	
	SKYLAKE/Feed:
	Job runs every two hours to trigger Feed.dbo.usp_insert_sky_s2_license_redemption_raw, which 
	runs a query (provided by Andrew Manning) at SKYLAKE to retrieve keycodes installed within the last 
	three hours. This is set to three hours instead of two for overlap; duplicates will be removed in the 
	subsequent procedure. 

	ecommerce:
	When Feed.dbo.s2_license_redemption is populated, the job triggers the next procedure, 
	dbo.usp_insert_sky_s2_license_redemption. This procedure copies 
	Feed.dbo.usp_insert_sky_s2_license_redemption_raw into a temp table, then removes:
		1. keycodes that don't exist in ecom
		2. licenses that don't exist in the subscription table (these aren't S2)
		3. licenses already written to license_install table (more on this later)
		4. licenses already in sky_update with the 's2_redemption' type

	Records are inserted into dbo.license_install and then written to dbo.sky_update with 's2_redemption' 
	sky_update_type_name. Inserted records are also logged in dbo.s2_license_redemption_log. 
	
	PHP:
	PHP loops through sky_update queue and picks up records to process. Records with 's2_redemption' type
	are processed with the following steps:
		1. record with 's2_redemption' type picked from queue
		2. DB called with license_id to return keycode
		3. dbo.usp_subscription_select_profile called with keycode to return subscription info
		4. BBY redemption endpoint called with subscription info

	Notes on license_install process:
	The primary process that populates dbo.license_install is also a job that triggers a procedure in Feed 
	and then completes the insert with another procedure in ecommerce. Both procedures are called 
	usp_insert_sky_license_install. The job runs daily and relies on some of the same checks for existing 
	records in the license_install table as this S2 process. To avoid potential timing issues, code has 
	been added to ecommerce.dbo.usp_insert_sky_license_install (section 2.2) to insert sky_update records 
	when S2 subscriptions not previously inserted are encountered during that load.

	Unrelated notes:
               _ 
              / \
          __/    \_
         /_  -  \  \                      ,:',:`,:',:' 
        / / /     \ \                  __||_||_||_||___
       |    |     / |             ____[""""""""""""""""]___
       /   /     \   \            \ " '''''''''''''''''''' \
       ~~^~^~^~^~^~^~^~~^~^~^~^~^~^~^~^^~^~^~^~^~^~^~^~~^~^~^~^~~^~^
      

*/
    begin
        set nocount on

		set transaction isolation level read uncommitted

		-- 1) import data from SKYLAKE into temp table

        drop table if exists #s2_license_redemption_stage

        select slr.keycode
			, slr.first_install_date
			, slr.latest_install_date
			, slr.insert_date as log_date
			, null as license_id
        into #s2_license_redemption_stage
        from SKYLAKE.Feed.dbo.s2_license_redemption slr

		if @@rowcount = 0
			begin
				return
			end

		-- 2) set license_id for eligible keycodes; delete remaining keys from table
        update #s2_license_redemption_stage
        set license_id = s.license_id
        from #s2_license_redemption_stage slrs
 
           inner join license l
                on l.keycode = slrs.keycode
            inner join subscription s
                on s.license_id = l.license_id
            left join license_install li
                on li.license_id = l.license_id
            left join sky_update su
                on su.license_id = l.license_id
                and su.sky_template_id = 14 -- s2_redemption
        where li.license_install_id is null
             and su.sky_update_id is null

		if @@rowcount = 0
			begin
				return
			end

        delete #s2_license_redemption_stage where license_id is null

		-- 3) insert records into license_install table
        insert into license_install (license_id, first_install_date, latest_install_date, log_date)
        select license_id, first_install_date, latest_install_date, log_date
        from #s2_license_redemption_stage 

		if @@rowcount = 0
			begin
				return
			end

		-- 4) insert records into sky_update and log in s2_license_redemption_log
		insert into sky_update (license_id, sky_template_id, sky_update_type_id, process_date)
		output Inserted.license_id, object_name(@@procid)
		into s2_license_redemption_log (license_id, source)
		select slrs.license_id, 14, 14, dateadd(minute, 5, getdate())
		from #s2_license_redemption_stage slrs

    end

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_invoice_inprocess_select]
-- =============================================================================










CREATE       PROCEDURE usp_invoice_inprocess_select

@invoice_in_process_id int

/*	
	DATE		AUTHOR	REMARKS
	2006-08-30	tblazek		Initial creation.
	2006-09-05	tblazek		Add customer_in_process_id and carttype to result set
	2006-09-11	tblazek		Add invoice_code to returned result set per ticket 5045

	DESCRIPTION
	Select invoice_in_process_id record for the invoice_in_process_id passed to procedure
	Return result set to PHP
Input Parameters:

invoice_in_process_id

Output Parameters:

- none

Result Set Parameters:

invoice_in_process_id
order_type_id
p_rc
p_rsc
p_ac
trx_rc
trx_rsc
trx_ac
coupon_code
coupon_amount
amount
tax_total
payment_method_type_description (use the payment_method_id to determine this value)
purchased_date,
customer_in_process_id
carttype
invoice_code


*/

AS
SET NOCOUNT ON

	select iip.invoice_in_process_id,
		iip.order_type_id,
		iip.p_rc,
		iip.p_rsc,
		iip.p_ac,
		iip.trx_rc,
		iip.trx_rsc,
		iip.trx_ac,
		iip.coupon_code,
		iip.coupon_amount,
		iip.amount,
		iip.tax_total,
		pmt.payment_method_type_description, 
		iip.purchased_date,
		cip.customer_in_process_id,
		iip.carttype,
		iip.invoice_code
	from invoice_in_process iip
	left outer join payment_method_type pmt
	on iip.payment_method_id = pmt.payment_method_type_id
	left outer join customer_in_process cip
	on iip.invoice_in_process_id = cip.invoice_in_process_id
	where iip.invoice_in_process_id = @invoice_in_process_id
 










GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_invoice_inprocess_select_items]
-- =============================================================================

CREATE  PROCEDURE [dbo].[usp_invoice_inprocess_select_items]
@invoice_in_process_id int

/*	
	DATE		AUTHOR	REMARKS
	2006-08-23	tblazek		Initial creation.

	DESCRIPTION
	Select all invoice_item_in_process_id 's for the invoice_in_process_id passed to procedure
	Return to  list of invoice_item_in_process_id 's to PHP

*/

AS
SET NOCOUNT ON

select invoice_item_in_process_id
from invoice_item_in_process i
inner join product p
	on i.cartKey = p.product_id
where invoice_in_process_id = @invoice_in_process_id
order by p.product_type_id, p.product_id desc

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_invoice_item_inprocess_select_item]
-- =============================================================================







CREATE     PROCEDURE usp_invoice_item_inprocess_select_item

@invoice_item_in_process_id int

/*	
	DATE		AUTHOR	REMARKS
	2006-08-23	tblazek		Initial creation.
	2006-09-05	tblazek		change product_id returned to use added column final_product_id
	DESCRIPTION
	Select invoice_item_in_process_id record for the invoice_item_in_process_id passed to procedure
	Return result set to PHP
Input Parameters:

invoice_item_in_process_id

Output Parameters:

- none

Result Set Parameters:

invoice_item_in_process_id
product_id
line_item
quantity
serial_number
full_retail_price
extended_price
tax_item_amount
special_code

*/

AS
SET NOCOUNT ON

	select invoice_item_in_process_id,
		invoice_in_process_id,
		final_product_id as 'product_id',
		line_item,
		quantity,
		serial_number,
		full_retail_price,
		extended_price,
		tax_item_amount,
		special_code
	from invoice_item_in_process
	where invoice_item_in_process_id = @invoice_item_in_process_id
 








GO
