-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_insert_account_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_lastpass_insert_account_update]

(
		@account_id int,
		@lastpass_update_type_id tinyint, 
		@lastpass_update_status_id tinyint,
		@process_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2010-04-01	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@insert_date datetime,
			@response_code int,
			@message varchar(100)

	select @response_code = 0,
			@insert_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @process_date
	if @process_date is null
		begin
		select @process_date = @insert_date
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into lastpass_update(account_id, lastpass_update_type_id, lastpass_update_status_id, insert_date, modified_date, process_date)
	values(@account_id, @lastpass_update_type_id, @lastpass_update_status_id, @insert_date, @insert_date, @process_date)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_select_account_maintenance]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_lastpass_select_account_maintenance]

(	
	@account_user_name varchar(100)
)


/*	
	DATE		AUTHOR		REMARKS
	2014-08-22	esmart		Initial creation.

	DESCRIPTION
	select account maintenance
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select e.account_extension_id, e.account_id, e.status_id, e.password_hash, e.encryption_key, e.insert_date, e.modified_date
	from account a
	left join account_maintenance..account_extension e
		on a.account_id = e.account_id
	where a.account_user_name = @account_user_name
	order by e.account_extension_id desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_select_create_account_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_lastpass_select_create_account_update]

(
		@account_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	select @response_code = 0

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select l.lastpass_update_id, 
			a.account_user_name,
			a.account_password,
			timezone = 'MST',
			lang = 'EN-US',
			loglogins = 1,
			improve = 1
	from lastpass_update l
	inner join account a
		on l.account_id = a.account_id
	where l.account_id = @account_id and lastpass_update_status_id in (0,2) and lastpass_update_type_id in (1,9)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select update account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_select_next_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_lastpass_select_next_update]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-02	esmart		Initial creation.
	2010-08-26	esmart		Set lastpass_update_type_id <> 10 for the ImmediateEndService queue records
	2011-08-16	esmart		Prevx support

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select top 1 u.lastpass_update_id, a.account_id, a.account_user_name, a.account_password, t.lastpass_update_type_id, t.lastpass_update_type_name, u.process_date, e.encryption_key_hash
	from lastpass_update u
	inner join lastpass_update_type t
		on u.lastpass_update_type_id = t.lastpass_update_type_id
	inner join account a
		on u.account_id = a.account_id
	left join account_ext e
		on a.account_id = e.account_id
	where u.lastpass_update_type_id <> 10 and u.lastpass_update_status_id in (0,2) and u.process_date <= @batch_limit_date and u.modified_date < @batch_limit_date
	order by process_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_select_update_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_lastpass_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2010-04-02	esmart		Initial creation.
	2010-08-26	esmart		Set lastpass_update_type_id <> 10 for the ImmediateEndService queue records

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- TODO validate of process date so if an update does occur we do a double check

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = getdate()
	from lastpass_update
	where lastpass_update_type_id <> 10 and 
			lastpass_update_status_id in (0,2) and process_date <= getdate()

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_select_update_history]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_lastpass_select_update_history]

(
	@account_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-12	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select source = 'archive', lastpass_update_archive_id, lastpass_update_id, account_id, t.lastpass_update_type_id, t.lastpass_update_type_name, s.lastpass_update_status_id, s.lastpass_update_status_name, response_code, response_text, update_attempts, insert_date, modified_date, process_date
	from lastpass_update_archive a
	inner join lastpass_update_type t
		on a.lastpass_update_type_id = t.lastpass_update_type_id
	inner join lastpass_update_status s
		on a.lastpass_update_status_id = s.lastpass_update_status_id
	where a.account_id = @account_id 
	union 
	select source = 'queue', lastpass_update_archive_id = 0, lastpass_update_id, account_id, t.lastpass_update_type_id, t.lastpass_update_type_name, s.lastpass_update_status_id, s.lastpass_update_status_name, response_code, response_text, update_attempts, insert_date, modified_date, process_date 
	from lastpass_update u
	inner join lastpass_update_type t
		on u.lastpass_update_type_id = t.lastpass_update_type_id
	inner join lastpass_update_status s
		on u.lastpass_update_status_id = s.lastpass_update_status_id
	where account_id = @account_id 
	order by lastpass_update_id, modified_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_update_account_maintenance]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_lastpass_update_account_maintenance]

(	
	@account_user_name varchar(100)
)


/*	
	DATE		AUTHOR		REMARKS
	2014-08-22	esmart		Initial creation.

	DESCRIPTION
	update account maintenance
*/

AS
	set nocount on				

	declare	@account_extension_id int, 
			@account_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) account_id
	select @account_id = account_id from account where account_user_name = @account_user_name

	-- 1.2) @account_extension_id
	select @account_extension_id = max(account_extension_id)
	from account_maintenance..account_extension 
	where account_id = @account_id

	-- select @account_id = @account_id, @account_extension_id = @account_extension_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) update most recent as active
	update account_maintenance..account_extension set status_id = 1, modified_date = getdate() where account_extension_id = @account_extension_id

	-- 2.2) update all others to archive
	update account_maintenance..account_extension set status_id = 2, modified_date = getdate()  where account_extension_id <> @account_extension_id and account_id = @account_id and status_id <> 2

	-- 2.3) update password_hash on account
	update account 
	set account_password = e.password_hash
	from account a
	inner join account_maintenance..account_extension e
		on a.account_id = e.account_id and e.status_id = 1
	where a.account_id = @account_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_update_account_reconciliation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_lastpass_update_account_reconciliation]

(
		@account_user_name varchar(100),
		@response_code tinyint,
		@response_text varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-04	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@account_id int,
			@lastpass_reconciliation_id int, 
			@lastpass_insert_date datetime,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @lastpass_reconciliation_id = lastpass_reconciliation_id
	from lastpass_reconciliation
	where account_user_name = @account_user_name

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert or update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @lastpass_reconciliation_id is null
		-- 2.1) insert account data
		begin
			-- 2.1.1) check account_user_name
			select @account_id = account_id 
			from account
			where account_user_name = @account_user_name
	
			if @account_id is not null
			-- 2.1.2) insert new record
				begin
				insert into lastpass_reconciliation(account_id, account_user_name, response_code, response_text)
				values(@account_id, @account_user_name, @response_code, @response_text)
				end
		end
	else
		-- 2.2) update account data
	begin
			-- 2.2.1) check account_user_name
			select @account_id = account_id 
			from account
			where account_user_name = @account_user_name
			
			if @account_id is not null
			-- 2.2.2) insert new record
				update lastpass_reconciliation
				set account_id = @account_id,
					response_code = @response_code,
					response_text = @response_text,
					last_update_date = getdate()
				where account_user_name = @account_user_name
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_lastpass_update_account_update]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_lastpass_update_account_update]

(
		@lastpass_update_id int,
		@responsecode tinyint,
		@responsetext varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.
	2010-08-17	esmart		Support for ImmediateEndService
	2011-08-11	esmart		Prevx support

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@lastpass_update_status_id tinyint,
			@current_lastpass_update_status_id tinyint,
			@lastpass_update_type_id tinyint,
			@account_id int,
			@update_attempts tinyint,
			@capability_expiration_date datetime,
			@new_lastpass_update_type_id tinyint,
			@process_date datetime,
			@response_code int,
			@message varchar(100)

	select @response_code = 0

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select @lastpass_update_type_id
	select @lastpass_update_status_id = case when @responsecode = 0 then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_lastpass_update_status_id = lastpass_update_status_id,
			@lastpass_update_type_id = lastpass_update_type_id,	
			@account_id = account_id
	from lastpass_update
	where lastpass_update_id = @lastpass_update_id

	if @current_lastpass_update_status_id in (1,3)
		begin
		select @response_code = -120, @message = 'No update on processed or abandoned updates'
		select response_code = @response_code, [message] = @message
		return
		end

	-- 1.3) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @lastpass_update_status_id = 2 -- failed
		begin
		select @lastpass_update_status_id = 3 -- abandoned
		end

--	select lastpass_update_status_id = @lastpass_update_status_id, update_attempts = @update_attempts

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1)  Processed
	if @lastpass_update_status_id = 1
		begin
			-- 2.1.1) insert archive record
			insert into lastpass_update_archive(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select lastpass_update_id, account_id, lastpass_update_type_id, @lastpass_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from lastpass_update
			where lastpass_update_id = @lastpass_update_id

			-- 2.1.2) delete update record
			delete
			from lastpass_update
			where lastpass_update_id = @lastpass_update_id	

			select @response_code = 0, @message = 'Update processed'
			end

	-- 2.2) Failure
	if @lastpass_update_status_id = 2
		begin
			-- 2.1) log failure
			insert into lastpass_update_failure(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select lastpass_update_id, account_id, lastpass_update_type_id, @lastpass_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from lastpass_update
			where lastpass_update_id
 = @lastpass_update_id
	
			-- 2.2.2) update queue
			update lastpass_update 
			set lastpass_update_status_id = @lastpass_update_status_id,
				update_attempts = @update_attempts,
				response_code = @responsecode,
				response_text = @responsetext,
				modified_date = getdate(),
				process_date =   dateadd(mi,5,process_date)
			where lastpass_update_id = @lastpass_update_id

			select @response_code = -220, @message = 'Update failed'
		end

	-- 2.1) Abandonded
	if @lastpass_update_status_id = 3
		begin
			-- 2.1.1) insert archive record
			insert into lastpass_update_archive(lastpass_update_id, account_id, lastpass_update_type_id, lastpass_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select lastpass_update_id, account_id, lastpass_update_type_id, @lastpass_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from lastpass_update
			where lastpass_update_id = @lastpass_update_id

			-- 2.1.2) delete update record
			delete
			from lastpass_update
			where lastpass_update_id = @lastpass_update_id	

			select @response_code = 0, @message = 'Update processed'

			-- 2.1.3) if abandoning a SuspendService update type and @responsetext = 'alreadydeactivated' insert EndService
			if @lastpass_update_type_id = 6 and @responsetext = 'alreadydeactivated'
				begin
				select @new_lastpass_update_type_id = 7, @process_date = dateadd(dd,45,getdate())

				exec usp_lastpass_insert_account_update @account_id, @new_lastpass_update_type_id, 0, @process_date
				end


			-- 2.1.4) if abandoning a CreateAccount update type and @responsetext = 'accountalreadyexists' insert SuspendService
			if @lastpass_update_type_id in (1,9,11) and @responsetext = 'accountalreadyexists'
				begin
				select @new_lastpass_update_type_id = 6, @process_date = dateadd(dd,45,getdate())

				exec usp_lastpass_insert_account_update @account_id, @new_lastpass_update_type_id, 0, @process_date
				end
		end

	-- 2.3) update license
	if @lastpass_update_type_id in (1,9,11) and @responsecode = 0
		begin
		exec usp_account_insert_license_update_queue @account_id, 17
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set up next queue transaction
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @responsecode = 0 and @lastpass_update_type_id <> 10
		begin
	
		-- 3.1) get expiration date for license
		select @capability_expiration_date = capability_expiration_date 
		from license_capability c
		inner join account_license l
			on c.license_id = l.license_id
		where l.account_id = @account_id and capability_id = 1

		-- 3.2) determine next update type
			if @lastpass_update_type_id = 1 or @lastpass_update_type_id = 8 or @lastpass_update_type_id = 9 or @lastpass_update_type_id = 11
			-- 3.2.1) insert deactivate record
				begin
					select @new_lastpass_update_type_id = 6
					select @process_date = @capability_expiration_date
					exec usp_lastpass_insert_account_update @account_id, @new_lastpass_update_type_id, 0, @process_date
				end
			if @lastpass_update_type_id = 6 -- DeactivateAccount
			-- 3.2.2) insert delete record
				begin
					select @new_lastpass_update_type_id = 7
					select @process_date = dateadd(dd,45,getdate())
					exec usp_lastpass_insert_account_update @account_id, @new_lastpass_update_type_id, 0, @process_date
				end

		end

	select response_code = @response_code, [message] = @message 

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @Er
rorDB = @DBName
		
	end catch;
	

GO
