CREATE PROCEDURE [dbo].[usp_license_activate]

(
	@keycode varchar(40),
	@GUID varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2006-06-26	esmart		Initial creation.
	2006-08-07	esmart		Add additional check for cababilities that need to be activated
	2006-09-04	esmart		Modified @keycode to varchar(40) from char(20)
	2006-09-19	esmart		Add insert into license_history and license_capability_history
	2006-10-04	esmart		Add code to disable license and inserts and updates to license, license history,
							license_capability, and license_capability_history. 
	2006-11-08	esmart		Modified insert into license_capability_history to have 0 days_added
	2008-07-16	esmart		Add support for license_storage
	2008-12-01	esmart		Remove usp_license_sub_insert_initial_license_capability_history
	2011-12-05	towens		Prevent OEM activation
	2016-03-22	blue		Stop history insert on license_status = 3
	2018-03-21	cnovac		Added update to license_category_license at bottom

	DESCRIPTION
	creates activation record for license, update license status, and set activation and expiration dates
*/

AS
	
	declare @license_id int,
		@license_status_id int,
		@max_daily_activations int,
		@daily_activations int,
		@error int,
		@license_change_reason_id int,
		@transaction_date datetime,
		@system_user varchar(50),
		@response_code int,
		@message varchar(100),
		@license_type_id int

	set @transaction_date = getdate()
	set @system_user = system_user
	set @license_change_reason_id = 6

	if @guid is null or @guid = '0' 
		begin
			set @guid = ''
		end

	-- 1.) get info from the license	
		
		select @license_id = license_id,@license_type_id  = license_type_id,  @max_daily_activations = max_daily_activations, @license_status_id = license_status_id
		from license
		where keycode = @keycode

		if @license_id is null
			begin
			set @response_code = -100
			set @message = 'Keycode not found'
			select response_code = @response_code, message = @message
			select activation_success = 0,
				fraud_type_id = 0
			return
			end
		if @license_type_id  = 2
			begin
			set @response_code = -100
			set @message = 'Keycode is OEM and should not be Activated'
			select response_code = @response_code, message = @message
			select activation_success = 0,
				fraud_type_id = 0
			return
			end

		--print @max_daily_activations

	-- 2.) check the number of current activations in the last 24 hours

		select @daily_activations = count(*)
		from license_activation
		where license_id = @license_id and 
			insert_date > dateadd(dd,-1,getdate())


		--print @daily_activations
		--set @daily_activations = 40 
		
	-- 3.)  check to see if the daily activation limit (past 24 hours) has been reached and if limit is okay insert activation

		-- 3.0) check to see if seed values in license_capability_history are in place
--		exec usp_license_sub_insert_initial_license_capability_history @license_id

		if @daily_activations >= @max_daily_activations 
			begin
				
				set @license_change_reason_id = 5 -- Fraud detection

				-- 3.1) insert license history and disable license
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, l
icense_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
				select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, history_date = @transaction_date, history_by = @system_user
				from license
				where license_id = @license_id
	
				update license
				set license_status_id = 2,
					modified_date = @transaction_date,
					modified_by = @system_user
				where license_id = @license_id					

				-- 3.2) insert license_capability_history and update license_cability
				select  license_capability_id, 
					license_id, 	
					capability_id, 
					capability_type_id, 
					days_remaining = 
						case 
							when @license_status_id = 0 then isnull(l.capability_activation_days,0)
							when datediff(dd,@transaction_date,l.capability_expiration_date) < 0 then 0
							else  isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
						end,
					capability_activation_days, 
					capability_activation_date, 
					capability_expiration_date, 
					insert_date, 
					insert_by, 
					modified_date, 
					modified_by,
					capability_change_reason_id = @license_change_reason_id, 
					history_date = @transaction_date, 
					history_by = @system_user,
					last_capability_type_id = 
								case
									when (select top 1 capability_type_id from license_capability_history where license_capability_id = l.license_capability_id) is not null then (select top 1 capability_type_id from license_capability_history where license_capability_id = l.license_capability_id)
									else l.capability_type_id
								end,									
					last_days_contiguous = 
								case
									when (select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc) is not null then (select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc)
									else capability_activation_days
								end,	 
					last_days_total = 
								case
									when (select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc) is not null then (select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc)
									else capability_activation_days
								end
				into #temp_license_capability
				from license_capability l
				where license_id = @license_id

				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
				select license_capability_id, 
					license_id, 	
					capability_id, 
					capability_type_id,
					capability_activation_days = capability_activation_days - days_remaining, 
					capability_activation_date, 
					capability_expiration_date = dateadd(dd,capability_activation_days - days_remaining,capability_activation_date), 
					insert_date, 
					insert_by, 
					modified_date, 
					modified_by,
					capability_change_reason_id, 
					history_date,
					history_by,
					days_used = capability_activation_days - days_remaining, 
					days_remaining, 
					days_added = 0, 
					days_new = 0 , 
					days_contiguous = 
						case 
							when days_remaining > 0 and last_capability_type_id = capa
bility_type_id  then last_days_contiguous  - days_remaining
							else isnull(capability_activation_days - days_remaining ,0)
						end
				from #temp_license_capability

				-- Add audit records
				exec usp_license_insert_license_capability_audit @license_id

				update license_capability
				set 	capability_activation_days = 
						case
							when t.capability_activation_days is null then null
							else 0
						end,
					capability_activation_date = dateadd(dd,t.capability_activation_days - t.days_remaining,t.capability_activation_date),
					capability_expiration_date = dateadd(dd,t.capability_activation_days - t.days_remaining,t.capability_activation_date),
					modified_date = @transaction_date,
					modified_by = @system_user
				from license_capability c
				inner join #temp_license_capability t
					on c.license_capability_id = t.license_capability_id
				where c.license_id = @license_id

				set @response_code = -200
				set @message = 'Maximum daily activations reached. License disabled'
				select response_code = @response_code, message = @message
				select activation_success = 0,
					fraud_type_id = 1
				return
				-- select @error  = 1
			end
		else
			begin
				insert into license_activation (license_id, guid)
				values (@license_id, @GUID)
			
				select @error = @@error
				
				-- 3.5.) check if license_status is inactive. change status to active and update activation and exirpation dates on the capabiltes
						
				if @license_status_id = 0
					begin
						-- add existing data to license_history
						insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
						select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, getdate(), system_user
						from license
						where license_id = @license_id					

						-- update license
						update license
						set license_status_id = 1,
							modified_date = getdate(),
							modified_by = system_user
						where license_id = @license_id
					end
	
				-- 3.6. ) update license activations that need activation and expiration date
			--if disabled, do nothing
			if @license_status_id <> 3
			begin
				declare @activation_date datetime
				set @activation_date = getdate()		
				
				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
				select  license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by,@license_change_reason_id, getdate(), system_user,
					days_used = 0, 
					days_remaining = 0, 
					days_added = 0, 
					days_new = capability_activation_days, 
					days_contiguous = capability_activation_days
				from license_capability
				where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4
		
				update license_capability
				set capability_activation_date = 
						case
							when capability_activation_days is null then null
							else @activation_date
						end,
					capability_expiration_date =
						case
							when capability_activation_days is null then null
							else dateadd(dd,capab
ility_activation_days,@activation_date)
						end,
					modified_date = getdate(),
					modified_by = system_user
				where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4
			
				-- 3.7) update license_storage with new 
	
				
				declare @capability_activation_date datetime,
						@capability_expiration_date datetime,
						@needs_storage_activation int

					-- 3.7.1 get activation dates
					select @capability_activation_date = min(capability_activation_date),
						@capability_expiration_date = max(capability_expiration_date)
					from license_capability
					where license_id = @license_id and capability_expiration_date is not null
					
					-- 3.7.2 check to see if storage is activated
					select @needs_storage_activation = count(*)
					from license_storage
					where license_id = @license_id and storage_activation_date is null

					if @needs_storage_activation > 0
						-- 3.7.3 activate storage
						begin
							-- insert audit
							insert into license_storage_audit (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by)
							select license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by
							from license_storage
							where license_id = @license_id

							-- insert license_storage_history
							insert into license_storage_history (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id)
							select license_storage_id, license_id, storage_gb, 
									storage_activation_date,
									storage_expiration_date,
									insert_date, insert_by, modified_date, modified_by, @license_change_reason_id
							from license_storage
							where license_id = @license_id

							-- update license_storage
							update license_storage
							set storage_activation_date = @capability_activation_date,
								storage_expiration_date = @capability_expiration_date,
								modified_date = getdate(),
								modified_by = suser_sname()
							where license_id = @license_id
						end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.8) update license_seat
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			insert into license_seat_history (license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
			select license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id,  getdate(), suser_sname()
			from license_seat
			where license_id = @license_id
			
			update license_seat
			set start_date = @capability_activation_date, 
				end_date = @capability_expiration_date,
				modified_date = getdate(),
				modified_by = suser_sname()
			from license_seat where license_id = @license_id
						
			end
		end

		--this just catches if start and end dates are null for some reason
		update dbo.license_category_license
		set start_date = @capability_activation_date, 
			end_date = @capability_expiration_date,
			last_modified_date = getdate(),
			last_modified_by = suser_sname()
		from license_category_license 
		where license_id = @license_id
		and start_date is null
		and end_date is null

	-- 4.) return results
		if @error  <> 0
			begin
				--print(@error)
				select activation_success = 0,
					fraud_type_id = 0
			end
		else
			begin

				--print('success')
				select activation_success = 1,
					fraud_type_id = 0
			end



set ANSI_NULLS ON
set QUOTED_IDENTIFIER ON


GO
