CREATE PROCEDURE [dbo].[usp_license_activity_update_from_wh]
as

/*
	DATE		AUTHOR		REMARKS
	2016-11-29	blu			Initial creation.
	2017-02-01	blu			Put records in temp table before update to avoid blocking.
	2017-04-14	blu			Update one record at a time.
	2017-11-07	cnovac		Updated script to pull from warehouse instead of doing complex linked server evaluations.

	DESCRIPTION
	Incrementally updates license_activity from warehouse.
*/

set nocount on
begin try

	truncate table dbo.license_activity_staging

	insert into dbo.license_activity_staging
		(license_activity_id,
		license_id,
		keycode,
		mjv,
		version,
		grabword,
		rc,
		operating_system,
		platform,
		language_code,
		location_code,
		device_mid,
		instance_mid,
		threats_removed,
		current_threats,
		number_scans,
		average_scan_time,
		number_events,
		bytes_cleaned,
		time_protected,
		first_activity_date,
		last_activity_date,
		max_activity_id,
		total_checks,
		max_threats_removed,
		max_current_threats,
		hostname,
		sa_score,
		sa_software_status,
		sa_hardware_status,
		sa_threat_status,
		record_type
		)
	select 
		license_activity_id,
		license_id,
		keycode,
		mjv,
		version,
		grabword,
		rc,
		operating_system,
		platform,
		language_code,
		location_code,
		device_mid,
		instance_mid,
		threats_removed,
		current_threats,
		number_scans,
		average_scan_time,
		number_events,
		bytes_cleaned,
		time_protected,
		first_activity_date,
		last_activity_date,
		max_activity_id,
		total_checks,
		max_threats_removed,
		max_current_threats,
		hostname,
		sa_score,
		sa_software_status,
		sa_hardware_status,
		sa_threat_status,
		record_type
	from DATAWAREHOUSEREADONLY.license_warehouse.dbo.license_activity_staging


	insert into dbo.license_activity
		(license_activity_id,
		license_id,
		keycode,
		mjv,
		version,
		grabword,
		rc,
		operating_system,
		platform,
		language_code,
		location_code,
		device_mid,
		instance_mid,
		threats_removed,
		current_threats,
		number_scans,
		average_scan_time,
		number_events,
		bytes_cleaned,
		time_protected,
		first_activity_date,
		last_activity_date,
		max_activity_id,
		total_checks,
		max_threats_removed,
		max_current_threats,
		hostname,
		sa_score,
		sa_software_status,
		sa_hardware_status,
		sa_threat_status
		)
	select 
		license_activity_id,
		license_id,
		keycode,
		mjv,
		version,
		grabword,
		rc,
		operating_system,
		platform,
		language_code,
		location_code,
		device_mid,
		instance_mid,
		threats_removed,
		current_threats,
		number_scans,
		average_scan_time,
		number_events,
		bytes_cleaned,
		time_protected,
		first_activity_date,
		last_activity_date,
		max_activity_id,
		total_checks,
		max_threats_removed,
		max_current_threats,
		hostname,
		sa_score,
		sa_software_status,
		sa_hardware_status,
		sa_threat_status
	from dbo.license_activity_staging
	where record_type = 'I'


	update la
	set la.mjv = t.mjv,
		la.[version] = t.[version],
		la.grabword = t.grabword,
		la.rc = t.rc,
		la.operating_system = t.operating_system,
		la.[platform] = t.[platform],
		la.language_code = t.language_code,
		la.location_code = t.location_code,
		la.threats_removed = t.threats_removed,
		la.current_threats = t.current_threats,
		la.number_scans = t.number_scans,
		la.average_scan_time = t.average_scan_time,
		la.number_events = t.number_events,
		la.bytes_cleaned = t.bytes_cleaned,
		la.time_protected = t.time_protected,
		la.last_activity_date = t.last_activity_date,
		la.max_activity_id = t.max_activity_id,
		la.total_checks = t.total_checks,
		la.max_threats_removed = t.max_threats_removed,
		la.max_current_threats = t.max_current_threats,
		la.hostname = t.hostname,
		la.sa_score = t.sa_score,
		la.sa_software_status = t.sa_software_status,
		la.sa_hardware_status = t.sa_hardware_status
,
		la.sa_threat_status = t.sa_threat_status
	from dbo.license_activity la
	inner join dbo.license_activity_staging t on la.license_activity_id = t.license_activity_id
	where t.record_type = 'U'


end try
begin catch
	declare @DBName nvarchar(128) = db_name()
	exec usp_LogError @ErrorDB = @DBName
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_arbitration_opt_out]
-- =============================================================================
-------------------------------------------------------------------------------
--  Description:
--      Inserts/returns an individual row into/from license_arbitration.
--  Maintenance:
--      2015-12-11  mandersen   Created.
--      2016-04-19  mandersen   Commented out date arithmetic. 
--      2018-12-27  jnavarra    Ignore empty string input and duplicate entries
--      2019-09-17  jnavarra    Update return status for PHP
-------------------------------------------------------------------------------
--  Copyright © 2014-2016 Webroot Inc.
-------------------------------------------------------------------------------
CREATE procedure [dbo].[usp_license_arbitration_opt_out]
(
    @keycode varchar(40) = null,
    @email varchar(100) = null,
    @response_code int = null output,
    @message varchar(100) = null output
)
as
    begin
        set nocount on

        begin try
            declare @license_id int

            declare @license_data table (license_id int, license_key uniqueidentifier, keycode varchar(40), activation_date date, email varchar(100), opted_out bit)

            set @keycode = replace(@keycode, '-', '')

            if @keycode is not null and @keycode <> ''
                begin
                    --print('Keycode: ' + @keycode)

                    insert into @license_data (license_id, license_key, keycode, activation_date, email, opted_out)
                    select ls.license_id, ls.license_key, ls.keycode, ls.capability_activation_date, null, case when la.license_id is null then 0 else 1 end
                    from dbo.license_summary ls
                        left join dbo.license_arbitration la
                            on la.license_id = ls.license_id
                    where ls.keycode = @keycode
                end
            else if @email is not null and @email <> ''
                begin
                    --print('Email: ' + @email)

                    insert into @license_data (license_id, license_key, keycode, activation_date, email, opted_out)
                    select distinct ls.license_id, ls.license_key, ls.keycode, ls.capability_activation_date, aos.email, case when la.email is null then 0 else 1 end
                    from dbo.account_order_staging aos
                        left join dbo.account_order ao
                            on ao.account_order_staging_id = aos.account_order_staging_id
                        left join dbo.license_summary ls
                            on ls.license_id = ao.license_id
                        left join dbo.license_arbitration la
                            on la.email = aos.email
                    where aos.email = @email
                end

            if @@ROWCOUNT = 0
                begin
                    -- Keycode or email NOT found
                    --print('Keycode or email NOT found')

                    select @response_code = -1, @message = 'Not found'
                end
            else if exists (select license_id from @license_data where opted_out = 1)
                begin
                    -- Keycode or email found, but already opted out
                    --print('Keycode or email found, but already opted out')

                    select @response_code = 2, @message = 'Already opted out'
                end
            else
                begin
                    -- Keycode or email found, and NOT already opted out
                    --print('Keycode or email found, and NOT already opted out')

                    insert into dbo.license_arbitration (license_id, license_key, keycode, activation_date, email, opt_out, opt_out_date)
                    select license_id, license_key, keycode, activation_
date, email, 1, getdate()
                    from @license_data
                    where opted_out = 0

                    select @response_code = 0, @message = 'Success'
                end

        end try
        begin catch
            set @response_code = -200
            set @message = case
                               when @message is null then
                                   'error in usp_license_arbitration_opt_out'
                               else
                                   @message
                           end
            declare @DBName nvarchar(128)
            set @DBName = db_name()
            exec dbo.usp_LogError @ErrorDB = @DBName
        end catch
    end


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_attribute_license_select]
-- =============================================================================


CREATE procedure [dbo].[usp_license_attribute_license_select]
(
	@license_id int,
	@license_attribute_id int = null
)

/*	
	date			author		remarks
	2007-07-23		mscardino	initial creation
	2014-09-30		esmart		Add license_attribute_license_id
	2016-01-18		esmart		Add effective columns
	2017-06-29		cnovac		Added more effective columns
	2019-01-08		rvinoche	Support autobilling attributes living only in license_effective_object

	description
	returns a record set of the license attributes of a license. 
 
	any license attributes that are: not in the license_attribute_license table should return 
	the default value from the license_attribute table.

*/

as

	set nocount ON

	declare @autobilling_attribute int,
			@effective_date date = getdate()
    
	select @autobilling_attribute = dbo.fn_license_select_effective_object_element(@license_id,220,'license_attribute_license_value', @effective_date)
    

-- 1) check feature
	if @autobilling_attribute is not null
	begin
		select	@license_id 'license_id',
				la.license_attribute_id,
				la.license_attribute_description,
				v.license_attribute_license_value,
				v.license_attribute_license_value_description
		from dbo.license_attribute_license_value v
		left join dbo.license_attribute la
			on v.license_attribute_id = la.license_attribute_id
		where v.license_attribute_license_value = @autobilling_attribute 
			and la.license_attribute_id = case when @license_attribute_id is null then la.license_attribute_id else @license_attribute_id end
        
	end
    else
    begin	
		select	lal.license_id,
				lal.license_attribute_id,
				la.license_attribute_description,
				v.license_attribute_license_value,
				v.license_attribute_license_value_description
		from dbo.license_attribute_license lal
		left join dbo.license_attribute la
			on lal.license_attribute_id = la.license_attribute_id
		left join dbo.license_attribute_license_value v
			on lal.license_attribute_license_value = v.license_attribute_license_value
		where lal.license_id = @license_id 
			and lal.license_attribute_id = case when @license_attribute_id is null then lal.license_attribute_id else @license_attribute_id end
	end


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_autorenewal_no_keycode_opt_out]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_license_autorenewal_no_keycode_opt_out]
    @first_name VARCHAR(255),
    @last_name VARCHAR(255),
    @customer_email VARCHAR(100),
    @reason_to_cancel VARCHAR(500),
    @request_uid VARCHAR(255),
    @request_open_category VARCHAR(100),
    @request_source VARCHAR(100),
    @request_ip VARCHAR(100),
    @response_code INT OUTPUT,
    @message VARCHAR(100) OUTPUT,
    @license_id INT OUTPUT

/*
    DATE        AUTHOR          REMARKS
    2016-05-11  cnovac          Initial creation.
    2020-02-04  jnavarra        Auto-disable when email has only 1 license. Return status.
    2020-02-27  jnavarra        Block parent/child licenses
								Allow business opt outs
    2020-03-04  jnavarra        Block SFDC
    2024-05-03  rambasana       Ecom-4249 Return response for Zuora migrated license
    2024-05-31  singaravelam    ECOM-1991 added response code and message column to capture values for report.
    2024-07-16  kkumari3        ECOM-4636 Considering only active license.
    2025-02-28  jberry          US-4429096 - Remove block for WIFI and Brightcloud licenses
    
    Description: Auto-disable when email has only 1 active license.

    Dependencies:This procedure is called by PHP(Auto renewal opt out page)
*/

AS
SET NOCOUNT ON

    -- Get Distribution method from app_config 
    DECLARE @APP_CONFIG TABLE
    (
        license_distribution_method_id INT,
        license_distribution_code NVARCHAR(50)
    );

    INSERT INTO @APP_CONFIG
    (
        license_distribution_method_id,
        license_distribution_code
    )
    SELECT dm.license_distribution_method_id,
           f.[key]
    FROM dbo.[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_code = f.[key];

BEGIN TRY

    DECLARE @license_autorenewal_no_keycode_opt_out_id INT
    -- Track all requests
    INSERT INTO license_autorenewal_no_keycode_opt_out
    (
        first_name,
        last_name,
        customer_email,
        reason_to_cancel,
        request_uid,
        request_open_category,
        request_source,
        request_ip
    )
    SELECT @first_name,
           @last_name,
           @customer_email,
           @reason_to_cancel,
           @request_uid,
           @request_open_category,
           @request_source,
           @request_ip

    SET @license_autorenewal_no_keycode_opt_out_id = SCOPE_IDENTITY()

    DECLARE @active_license_status_id INT
    SELECT @active_license_status_id = f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('ACTIVE_LICENSE_STATUS', 'GENERAL') f
    
    -- Gather licenses associated with email address
    DECLARE @license_ids TABLE
    (
        license_id INT,
        product_line_id INT,
        license_category_id INT,
        email_status_id INT,
        autorenewal_opt_id TINYINT,
        is_zuora_distribution_method BIT
    );
        
    INSERT INTO @license_ids
    (
        license_id,
        product_line_id,
        license_category_id,
        email_status_id,
        autorenewal_opt_id,
        is_zuora_distribution_method
    )
    SELECT l.license_id,
           l.product_line_id,
           ls.license_category_id,
           ce.email_status_id,
           ls.autorenewal_opt_id,
           CASE
               WHEN ac.license_distribution_method_id IS NULL THEN
                   0
               ELSE
                   1
           END

    FROM dbo.customer_email ce WITH (NOLOCK)
        INNER JOIN dbo.license l WITH (NOLOCK)
            ON l.customer_id = ce.customer_id
        INNER JOIN dbo.license_summa
ry ls WITH (NOLOCK)
            ON ls.license_id = l.license_id
        LEFT JOIN @APP_CONFIG ac
            ON ac.license_distribution_method_id = ls.license_distribution_method_id
    WHERE ce.customer_email = @customer_email
        AND l.license_status_id = @active_license_status_id

    -- Gather metrics
    DECLARE @count INT =
            (
                SELECT COUNT(*)FROM @license_ids
            );

    DECLARE @opted_in_count INT =
            (
                SELECT COUNT(*)FROM @license_ids WHERE autorenewal_opt_id = 1
            );

    DECLARE @email_enabled_count INT =
            (
                SELECT COUNT(*)FROM @license_ids WHERE email_status_id = 1
            );

    DECLARE @parent_child_license_count INT =
            (
                SELECT COUNT(*)
                FROM @license_ids l
                    LEFT JOIN dbo.license_parent lp_p WITH (NOLOCK)
                        ON lp_p.parent_license_id = l.license_id
                    LEFT JOIN dbo.license_parent lp_c WITH (NOLOCK)
                        ON lp_c.child_license_id = l.license_id
                WHERE lp_p.parent_license_id IS NOT NULL
                      OR lp_c.parent_license_id IS NOT NULL
            );

    DECLARE @is_zuora_distribution_method BIT;
    IF @count = 1
    BEGIN
        SELECT @is_zuora_distribution_method = is_zuora_distribution_method
        FROM @license_ids;
    END;


    SELECT @license_id =
    (
        SELECT TOP (1) license_id FROM @license_ids ORDER BY license_id
    );

    DECLARE @sfdc_count INT = NULL;
    IF @count = 1
    BEGIN
        DECLARE @latest_order_item_id INT =
                (
                    SELECT MAX(order_item_id)
                    FROM dbo.order_item_license WITH (NOLOCK)
                    WHERE license_id = @license_id
                );

        SET @sfdc_count =
        (
            SELECT COUNT(*)
            FROM dbo.order_item_license oil WITH (NOLOCK)
                INNER JOIN dbo.order_item oi WITH (NOLOCK)
                    ON oi.order_item_id = oil.order_item_id
                INNER JOIN dbo.order_header oh WITH (NOLOCK)
                    ON oh.order_header_id = oi.order_header_id
            WHERE oi.order_item_id = @latest_order_item_id
                  AND oh.site_id = 'SFDC'
        );
    END;

    -- Failures
    IF @count = 0
    BEGIN
        -- License wasn't found
        SELECT @response_code = -1,
               @message = 'License not found',
               @license_id = NULL;
    END;
    ELSE IF @count > 1
    BEGIN
        -- Found too many licenses
        SELECT @response_code = -2,
               @message = 'Multiple licenses found',
               @license_id = NULL;
    END;

    ELSE IF @is_zuora_distribution_method = 1
    BEGIN
        -- Zuora License
        SELECT @response_code = -6,
               @message = 'US Domestic license Associated with Carbonite Partner';
    END;

    ELSE IF @sfdc_count IS NOT NULL
            AND @sfdc_count > 0
    BEGIN
        -- There's only 1 license, but the associated email is for a license originating from SalesForce
        SELECT @response_code = -5,
               @message = 'SFDC';
    END;
    ELSE IF @opted_in_count = 0
    BEGIN
        -- There's only 1 license, but it's already opted out
        SELECT @response_code = -3,
               @message = 'License already opted out';
    END;
    ELSE IF @email_enabled_count = 0
            OR @parent_child_license_count > 0
    BEGIN
        -- There's only 1 license, but the associated email is disabled or wifi or brtc or parent or child
        SELECT @response_code = -4,
               @message = 'Unable to opt license out';
    END;

    -- Success
    ELSE
    BEGIN
        -- At this point we should have 1 valid license
        EXEC dbo.usp_license_update_disable_autorenewal @license_id = @license_id,
     
                                                   @csi_user_id = 'Website',
                                                        @comment = 'Disabled from website';

        SELECT @response_code = 0,
               @message = 'Success';
    END;

	    UPDATE license_autorenewal_no_keycode_opt_out
    SET response_code = @response_code,
        message = @message
    WHERE license_autorenewal_no_keycode_opt_out_id = @license_autorenewal_no_keycode_opt_out_id

END TRY
BEGIN CATCH
    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'error processing usp_license_autorenewal_no_keycode_opt_out'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC dbo.usp_LogError @ErrorDB = @DBName;

    RETURN 0;
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_behavior_insert_license_behavior_license]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_behavior_insert_license_behavior_license]

/*     
       DATE                 AUTHOR				REMARKS
       2019-03-06			mrobbins			Initial creation
*/
AS 
	DECLARE @response_code INT, 
			@message VARCHAR(100),
			@behavior_id INT,
			@max_behavior_id INT,
			@license_behavior_id INT,
			@license_category_name VARCHAR(100),
			@license_category_id INT,
			@capability_type_id INT,
			@capability_type_description VARCHAR(100),
			@last_insert_date DATETIME  

	BEGIN TRY 
            
		DECLARE @behavior TABLE (
			behavior_id INT IDENTITY(1,1), 
			license_behavior_id INT,
			license_category_id INT,
			license_category_name VARCHAR(50),
			capability_type_id INT,
			capability_type_description VARCHAR(100))

		DECLARE @console_activity_subset TABLE (console_activity_subset_id INT IDENTITY(1,1),
			license_category_id INT NULL,
			console_activity_id INT NULL,
			license_id INT NULL,
			total_devices INT  NULL,
			active_devices INT NULL,
			deactivated_devices int NULL,
			effective_date datetime NULL,
			last_30_day_devices int NULL,
			active_last_30_day_devices int NULL,
			capability_type_id INT NULL,
			parent_license_id int NULL)

		INSERT INTO @behavior (license_behavior_id,
			license_category_id,
			license_category_name,
			capability_type_id,
			capability_type_description)
		SELECT lb.license_behavior_id,
			lblc.license_category_id,
			lc.license_category_name,
			lblc.capability_type_id,
			ct.capability_type_description 
		FROM dbo.license_behavior lb
			INNER JOIN license_behavior_license_category lblc
				ON lblc.license_behavior_id = lb.license_behavior_id
			INNER JOIN dbo.license_category lc
				ON lblc.license_category_id = lc.license_category_id
			INNER JOIN dbo.capability_type ct
				ON lblc.capability_type_id = ct.capability_type_id
		WHERE lb.license_behavior_status_id = 1
		ORDER BY lb.license_behavior_id

		SELECT @last_insert_date = ISNULL(MAX(insert_date),GETDATE()-1)
		FROM dbo.license_behavior_license_new

		--SELECT @last_insert_date

		SELECT @behavior_id = MIN(behavior_id),
			@max_behavior_id = MAX(behavior_id)
		FROM @behavior

		WHILE @behavior_id <= @max_behavior_id
		BEGIN 	
			SELECT @license_behavior_id = license_behavior_id,
				@license_category_id = license_category_id,
				@license_category_name = license_category_name,
				@capability_type_id = capability_type_id,
				@capability_type_description = capability_type_description
			FROM @behavior 
			WHERE behavior_id = @behavior_id

			--SELECT @license_behavior_id license_behavior_id,
			--	@license_category_id license_category_id,
			--	@license_category_name license_category_name,
			--	@capability_type_id capability_type_id,
			--	@capability_type_description capability_type_description



			IF @license_behavior_id = 1		--trial_created
				BEGIN
					INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id, license_behavior_id, behavior_date)
					SELECT DISTINCT  lc.license_id,
						lc.license_category_id,
						@license_behavior_id,
						lc.insert_date behavior_date
					FROM dbo.license_contract lc
						INNER JOIN dbo.license_summary ls
							ON ls.license_id = lc.license_id
					WHERE NOT EXISTS (SELECT license_id 
										FROM dbo.license_behavior_license_new lbl 
										WHERE lc.license_id = lbl.license_id 
											AND lbl.license_behavior_id = @license_behavior_id
											AND lbl.license_category_id = @license_category_id)
									AND lc.license_category_id = @license_category_id
									AND lc.license_category_type_id = @capability_type_id
									AND ls.license_distribution_method_id not in (919,123)
									
AND lc.license_contract_status_id = 1
									AND lc.license_end_date >= GETDATE()
									AND lc.insert_date >= DATEADD(MINUTE,-5,@last_insert_date)
				END

			--NO behavior 2 because console_login is last log in - not first will enable when Derby changes the data feed
			--IF @license_behavior_id = 2		--console_login
			--	BEGIN
			--		INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id,license_behavior_id, behavior_date)
			--		SELECT DISTINCT  t.license_id,
			--			@license_category_id,
			--			@license_behavior_id,
			--			t.login_date behavior_date
			--		FROM dbo.console_login t 
			--			CROSS APPLY dbo.fn_license_select_license_profile(t.license_id) p 
			--					INNER JOIN dbo.license l on t.license_id = l.license_id 
			--		WHERE NOT EXISTS (SELECT license_id 
			--							FROM dbo.license_behavior_license_new lbl 
			--							WHERE t.license_id = lbl.license_id 
			--								AND lbl.license_behavior_id = @license_behavior_id
			--								AND lbl.license_category_id = @license_category_id)
			--						AND p.license_category_name =  @license_category_name 
			--						AND p.category_type_name = @capability_type_description 
			--						AND l.license_distribution_method_id not in (919,123)
			--						AND p.license_status_id = 1
			--						AND p.expiration_date > GETDATE()
			--						AND t.login_date >= DATEADD(DAY,-2,@last_insert_date)  --go back 2 days because data from Derby is delayed
			--	END

			IF @license_behavior_id = 3		--site_created
				BEGIN
					INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id,license_behavior_id, behavior_date)
					SELECT DISTINCT  t.parent_license_id,
						@license_category_id,
						@license_behavior_id,
						t.insert_date behavior_date
					FROM dbo.license_parent t 
						INNER JOIN dbo.license_summary ls
									ON ls.license_id = t.parent_license_id
					WHERE NOT EXISTS (SELECT license_id 
										FROM dbo.license_behavior_license_new lbl 
										WHERE t.parent_license_id = lbl.license_id 
											AND lbl.license_behavior_id = @license_behavior_id
											AND lbl.license_category_id = @license_category_id)
									AND ls.license_category_id = @license_category_id
									AND ls.capability_type_id = @capability_type_id
									--AND ls.license_distribution_method_id not in (919,123)
									AND ls.license_status_id = 1
									AND ls.capability_expiration_date >= GETDATE()
									AND t.insert_date >=  DATEADD(DAY,-1,@last_insert_date)
				END

			IF @license_behavior_id = 4		--active_devices
				BEGIN

					DELETE FROM @console_activity_subset

					IF @license_category_name = 'SAEP'
						BEGIN
							INSERT INTO @console_activity_subset
								(
									console_activity_id,
									license_category_id,
									license_id,
									effective_date,
									parent_license_id
								)
							SELECT cas.console_activity_id,
								@license_category_id,
								cas.license_id,
								cas.effective_date,
								cas.parent_license_id
							FROM dbo.console_activity_saep cas
								INNER JOIN (SELECT DISTINCT MIN(t.console_activity_id) console_activity_saep_id,
													t.license_id
												FROM dbo.console_activity_saep t 
												WHERE NOT EXISTS (SELECT license_id 
																	FROM dbo.license_behavior_license_new lbl 
																	WHERE t.license_id = lbl.license_id 
																		AND lbl.license_behavior_id = 4
																		AND lbl.license_category_id = @license_category_id)
																--AND l.license_distribution_method_id not in (919,123)
																AND t.effective_date >=  DATEADD(DAY,-3,@last_insert_date) --go back 1 days because data from Derby is delayed
												GROUP BY t.license_id) min_cas
									ON min_cas.console_activity_saep_id = cas.console_activity_id
                        END 

					IF @license_category_name = 'SDNS'
						BEGIN
							INSERT INTO @
console_activity_subset
								(
									console_activity_id,
									license_category_id,
									license_id,
									effective_date,
									parent_license_id
								)
							SELECT cas.console_activity_sdns_id,
								@license_category_id,
								cas.license_id,
								cas.effective_date,
								cas.parent_license_id
							FROM dbo.console_activity_sdns cas
								INNER JOIN (SELECT DISTINCT MIN(t.console_activity_sdns_id) console_activity_sdns_id,
													t.license_id
												FROM dbo.console_activity_sdns t 
												WHERE NOT EXISTS (SELECT license_id 
																	FROM dbo.license_behavior_license_new lbl 
																	WHERE t.license_id = lbl.license_id 
																		AND lbl.license_behavior_id = 4
																		AND lbl.license_category_id = @license_category_id)
																--AND l.license_distribution_method_id not in (919,123)
																AND t.effective_date >=  DATEADD(DAY,-3,@last_insert_date) --go back 1 days because data from Derby is delayed
												GROUP BY t.license_id) min_cas
									ON min_cas.console_activity_sdns_id = cas.console_activity_sdns_id
							
                        END 

						IF @license_category_name = 'SECA'
						BEGIN
							INSERT INTO @console_activity_subset
								(
									console_activity_id,
									license_category_id,
									license_id,
									effective_date,
									parent_license_id
								)
							SELECT cas.console_activity_seca_id,
								@license_category_id,
								cas.license_id,
								cas.effective_date,
								cas.parent_license_id
							FROM dbo.console_activity_seca cas
								INNER JOIN (SELECT DISTINCT MIN(t.console_activity_seca_id) console_activity_seca_id,
													t.license_id
												FROM dbo.console_activity_seca t 
												WHERE NOT EXISTS (SELECT license_id 
																	FROM dbo.license_behavior_license_new lbl 
																	WHERE t.license_id = lbl.license_id 
																		AND lbl.license_behavior_id = 4
																		AND lbl.license_category_id = @license_category_id)
																--AND l.license_distribution_method_id not in (919,123)
																AND t.effective_date >=  DATEADD(DAY,-3,@last_insert_date) --go back 1 days because data from Derby is delayed
												GROUP BY t.license_id) min_cas
									ON min_cas.console_activity_seca_id = cas.console_activity_seca_id
                        END 

					INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id,license_behavior_id, behavior_date)
					SELECT DISTINCT  t.license_id,
						lc.license_category_id,
						@license_behavior_id,
						t.effective_date behavior_date
					FROM @console_activity_subset t 
						INNER JOIN dbo.license_contract lc
							ON lc.license_id = t.license_id
								AND t.license_category_id = lc.license_category_id
					WHERE NOT EXISTS (SELECT license_id 
										FROM dbo.license_behavior_license_new lbl 
										WHERE t.license_id = lbl.license_id 
											AND lbl.license_behavior_id = @license_behavior_id
											AND lbl.license_category_id = @license_category_id)
									AND t.license_category_id = @license_category_id
									AND lc.license_category_type_id = @capability_type_id 
									--AND l.license_distribution_method_id not in (919,123)
									AND lc.license_contract_status_id = 1
									AND lc.license_end_date > GETDATE()
									AND t.effective_date >=  DATEADD(DAY,-5,@last_insert_date)  --go back 1 days because data from Derby is delayed

					DELETE FROM @console_activity_subset

				END

			
			IF @license_behavior_id = 5		--conversion_to_full
				BEGIN
					INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id,license_behavior_id, behavior_date, order_header_id)
					SELECT DISTINCT oil.license_id,
						lc.license_category_id,
						@license_behavior_id,
						o.insert_date,
						o.order_hea
der_id 
					FROM (SELECT DISTINCT plc.license_category_id,
								oi.insert_date,
								oi.order_item_id,
								oi.order_header_id
							FROM dbo.order_item oi
								INNER JOIN dbo.product p
									ON oi.product_id = p.product_id
								INNER JOIN dbo.product_license_category plc
									ON plc.product_id = p.product_id
							WHERE oi.insert_date >=  DATEADD(MINUTE,-5,@last_insert_date)  
								AND p.product_type_id = 1
								AND plc.license_category_id = @license_category_id) o
						INNER JOIN dbo.order_item_license oil
							ON oil.order_item_id = o.order_item_id
						INNER JOIN dbo.license_contract lc
							ON oil.license_id = lc.license_id
								AND o.license_category_id = lc.license_category_id
						INNER JOIN dbo.license_summary ls
							ON ls.license_id = oil.license_id
					WHERE NOT EXISTS (SELECT license_id 
										FROM dbo.license_behavior_license_new lbl 
										WHERE oil.license_id = lbl.license_id 
											AND lbl.license_behavior_id = @license_behavior_id
											AND lbl.license_category_id = @license_category_id)
							AND lc.license_category_id = @license_category_id
							AND lc.license_category_type_id = @capability_type_id
							AND ls.license_distribution_method_id not in (919,123)
							AND lc.license_contract_status_id = 1
							AND lc.license_end_date >= CAST(GETDATE() AS DATE)
							AND EXISTS (SELECT license_id
												FROM dbo.license_behavior_license_new lbl
												WHERE oil.license_id = lbl.license_id
													AND lbl.license_behavior_id = 1
													AND lbl.license_category_id = @license_category_id)

				END

			IF @license_behavior_id = 6		--orders
				BEGIN
					INSERT INTO dbo.license_behavior_license_new (license_id, license_category_id,license_behavior_id, behavior_date, order_header_id)
					SELECT DISTINCT oil.license_id,
						lc.license_category_id,
						@license_behavior_id,
						o.insert_date,
						o.order_header_id 
					FROM (SELECT DISTINCT plc.license_category_id,
								oi.insert_date,
								oi.order_item_id,
								oi.order_header_id
							FROM dbo.order_item oi
								INNER JOIN dbo.product p
									ON oi.product_id = p.product_id
								INNER JOIN dbo.product_license_category plc
									ON plc.product_id = p.product_id
							WHERE oi.insert_date >=  DATEADD(MINUTE,-5,@last_insert_date)  
								AND plc.license_category_id = @license_category_id) o
						INNER JOIN dbo.order_item_license oil
							ON oil.order_item_id = o.order_item_id
						INNER JOIN dbo.license_contract lc
							ON oil.license_id = lc.license_id
								AND o.license_category_id = lc.license_category_id
						INNER JOIN dbo.license_summary ls
							ON ls.license_id = oil.license_id
					WHERE NOT EXISTS (SELECT license_id 
										FROM dbo.license_behavior_license_new lbl 
										WHERE oil.license_id = lbl.license_id 
											AND lbl.license_behavior_id IN (5,@license_behavior_id)
											AND lbl.license_category_id = @license_category_id
											AND lbl.order_header_id = o.order_header_id)
							AND lc.license_category_id = @license_category_id
							AND lc.license_category_type_id = @capability_type_id
							AND ls.license_distribution_method_id not in (919,123)
							AND lc.license_contract_status_id = 1
							AND lc.license_end_date >= CAST(GETDATE() AS DATE)
				END


			select @behavior_id = @behavior_id + 1, 
				@license_behavior_id = NULL

		END

    END TRY 
	BEGIN CATCH 
			SET @response_code = -200
			SET @message = CASE WHEN @message IS NULL THEN 'failed to insert license_behavior_license_new '+ CAST(@license_behavior_id AS VARCHAR(20))
					ELSE 
						@message 
					END

			DECLARE @dbname NVARCHAR(128)
			SET @dbname = db_name()
			EXEC dbo.usp_logerror @errordb = @dbname;
			THROW 51001, @message,1;

	END CATCH;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_behavior_process_bulk_update]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_behavior_process_bulk_update] 

/*     
       DATE                 AUTHOR               REMARKS
       2019-01-22           rvinoche             Initial creation
*/

AS

	declare @license_id int,
			@license_behavior_id int,
			@min_row int = 1,
			@max_row int,
			@batch_size INT = 2000,
			@sequence_number int,
			@row_count int,
			@license_behavior_class_id int,
			@insert_date datetime = getdate(),
			@insert_record bit = 0,
			@license_behavior_license_id int,
			@response_code int, 
			@message varchar(100)


	begin try	

		declare @licenses table (row_id int identity(1,1), license_id int, license_behavior_id int)

		insert into @licenses (license_id, license_behavior_id)
		select top (@batch_size) lbcl.license_id, lbcl.license_behavior_id
		from dbo.license_behavior_check_license lbcl
		inner join dbo.license_behavior_sequence lbs
			on lbs.license_behavior_id = lbcl.license_behavior_id 
		where lbcl.processed = 0
		order by lbs.sequence_number -- to process early behaviors first

		select @row_count = @@rowcount

		while @min_row <= @row_count
		begin

			select @license_id = license_id, @license_behavior_id = license_behavior_id
			from @licenses
			where row_id = @min_row

			select @sequence_number = sequence_number, @license_behavior_class_id = license_behavior_class_id
			from dbo.license_behavior_sequence 
			where license_behavior_id = @license_behavior_id

			if @sequence_number = 1 or exists 
				(select 1 
				from dbo.license_behavior_license lbl 
				inner join dbo.license_behavior lb 
					on lb.license_behavior_id = lbl.license_behavior_id 
				inner join dbo.license_behavior_sequence lbs
					on lbs.license_behavior_class_id = lb.license_behavior_class_id
				where lbl.license_id = @license_id
					and lbs.sequence_number < @sequence_number) --to see if the license was previously being tracked
			begin
				select @insert_record = 1
			end

			if not exists (select 1 from dbo.license_behavior_license where license_id = @license_id and license_behavior_id = @license_behavior_id)
				and @insert_record = 1
			begin
            
				insert into dbo.license_behavior_license (license_id,  license_behavior_id,  insert_date,  completion_status)
				values (@license_id, @license_behavior_id, @insert_date, 'active')

				select @license_behavior_license_id = scope_identity()

				--update previous license_behavior_license records
				update lbl 
				set lbl.completion_date = @insert_date, lbl.completion_status = 'completed'
				from dbo.license_behavior_license lbl
				inner join dbo.license_behavior_sequence lbs
					on lbs.license_behavior_id = lbl.license_behavior_id
					and lbs.license_behavior_class_id = @license_behavior_class_id
				where lbl.license_id = @license_id
					and lbs.sequence_number < @sequence_number
					and lbl.completion_status = 'active'

				if exists (select 1 --will automatically complete inserted record if license is already further along in class sequence
							from dbo.license_behavior_license lbl 
							inner join dbo.license_behavior_sequence lbs on lbs.license_behavior_id = lbl.license_behavior_id 
							where license_id = @license_id 
								and lbs.license_behavior_class_id = @license_behavior_class_id 
								and lbs.sequence_number > @sequence_number)
				begin
					update dbo.license_behavior_license
					set completion_date = insert_date, completion_status =  'completed'
					where license_behavior_license_id = @license_behavior_license_id
				end
			end
            
			--delete from license_behavior_check_license queue
			delete lbcl 
			from dbo.license_behavior_check_license lbcl
			inner join dbo.license_beh
avior_sequence lbs
				on lbs.license_behavior_class_id = @license_behavior_class_id
				and lbs.license_behavior_id = lbcl.license_behavior_id
			where lbcl.license_id = @license_id
				and lbs.sequence_number <= @sequence_number		
				
			select @license_id = null, @license_behavior_id = null, @license_behavior_class_id = null, @sequence_number = null, @min_row = @min_row + 1, @insert_record = 0	
			
			--customer messaging TO DO	     
		
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed to process usp_license_behavior_process_bulk_update '+ cast(@license_id as varchar(20))
										else @message end

		declare @dbname nvarchar(128)
		set @dbname = db_name()
		exec dbo.usp_logerror @errordb = @dbname;
		throw 51001, @message,1;

	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_beta_insert_license]
-- =============================================================================







CREATE PROCEDURE usp_license_beta_insert_license


(
	@keycode char(40),
	@response_code int output,
	@message varchar(100) output

)


AS
	set nocount on

	declare @customer_code varchar(16),
		@allow_upgrade_days int,
		@activation_date datetime,
		@expiration_date datetime,
		@first_name nvarchar(32),
		@last_name nvarchar(32),
		@company nvarchar(48),
		@email varchar(64),
		@vendor_customer_id int,
		@customer_id int,
		@license_id int,
		@error int
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Check to see if license already exists
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @response_code = 
			case
				when count(*) > 0 then -100
				else 0			
			end,
		@message = 
			case
				when count(*) > 0 then 'License already exists'
				else ''		
			end
	from license 
	where keycode = @keycode

	if @response_code < 0 
		begin
			--select success = 0
			return
		end

	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2 ) get values for keycode and customer
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @customer_code = customer_code,
		@allow_upgrade_days = allow_upgrade_days,
		@activation_date = activation_date
	from keycodes
	where keycode = @keycode
	
	-- validate that the keycode matched and returned values for days and activation date 
		
		if @allow_upgrade_days is null and @activation_date is null
			begin
			set @response_code = -200
			set @message = 'No keycode match'
			--goto backout
			--select success = 0
			return
			end

	select @first_name = first_name,
		@last_name = last_name,
		@company = company1,
		@email = email
	from customers
	where customer_code = @customer_code

	-- print @customer_code
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4 ) create customer record
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	
	if @customer_code is not null and @customer_id is null
		begin

			insert into customer (first_name, middle_name, last_name, title, opt_in)
			values (@first_name, null, @last_name, null, 1)
		
			set @error = @@error
			set @customer_id = scope_identity()
		
			if @error > 0
				begin
					set @response_code = -400
					set @message = 'General database error - Customer'
					goto backout
					--select sucess = 0
					--return
				end
			--print @customer_id
		end

	

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3 ) create vendor_customer record
	------------------------------------------------------
-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @vendor_customer_id is null and @customer_code is not null and @customer_id is not null
		begin
			insert into vendor_customer (vendor_id, customer_id, vendor_customer_code)
			values (1, @customer_id, @customer_code)

			set @error = @@error
			
			set @vendor_customer_id = scope_identity()

			if @error > 0
				begin
					set @response_code = -300
					set @message = 'General database error - vendor_customer'
					goto backout
					--select success = 0
					--return
				end

		end	
		
	-- print @vendor_customer_id

		
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5 ) customer email
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @email is not null and @email <> ''  and @customer_id is not null
		begin
			insert into customer_email (customer_id, customer_email, email_status_id)
			values (@customer_id, @email, 1)
		end


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6 ) customer company
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @company is not null and @company <> ''  and @customer_id is not null
		begin
			insert into customer_company (customer_id, company_name)
			values (@customer_id, @company)
		end 


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7 ) license
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license (keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id)
	select keycode,
		c.customer_id,
		product_line_id = p.product_line_id,
		license_status_id = status_id,
		license_type_id = 
			case
				when type_id = 0 then 1
				else 2
			end,
		license_distribution_method_id
	from  keycodes k
	inner join product_line_product p
		on k.product_id = p.product_id
	left join vendor_customer vc
		on vc.vendor_customer_code = k.customer_code
	left join customer c
		on vc.customer_id = c.customer_id
	inner join license_distribution_method m
		on substring(k.keycode,5,4) = m.license_distribution_method_code
	where keycode = @keycode

	set @error = @@error
	set @license_id = @@identity
	
	if @error > 0
		begin
			set @response_code = -700
			set @message = 'General database error - license'
			goto backout
			--select success = 0
			--return
		end
	

	-- print @license_id


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8 )  license_capability
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--------------------
		
	select @customer_code = customer_code,
		@allow_upgrade_days = allow_upgrade_days,
		@activation_date = activation_date,
		@expiration_date = expiration_date
	from keycodes
	where keycode =  @keycode

	-- 7.1 ) check to see if the license is expire and reset the values 
	if @expiration_date < getdate() or @expiration_date is null
		-- 
		begin
			set @allow_upgrade_days = 30
			set @activation_date = null
			set @expiration_date = null
		end
	else 
		-- add 30 days to days and expiration date
		begin
			set @allow_upgrade_days = @allow_upgrade_days + 30
			set @expiration_date = dateadd(dd,@allow_upgrade_days,@activation_date)
			
		end		
	
	-- 8.2 ) add SS capability
	insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date)
	values (@license_id, 1, 1, @allow_upgrade_days, @activation_date, @expiration_date)
	
	set @error = @@error

	if @error > 0
		begin
			set @response_code = -820
			set @message = 'General database error - license capability'
			goto backout
			--select success = 0
			--return
		end

	-- 8.3 ) add AV capability
	insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date)
	values (@license_id, 2, 1, 30, null, null)

	set @error = @@error
	
		if @error > 0
			begin
				set @response_code = -830
				set @message = 'General database error - license capability'
				goto backout
				--select success = 0
				--return
			end

	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9 )  BACKOUT
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	backout: 
		if @response_code < 0
			begin
			
				delete from license_capability where license_id = @license_id
				delete from license where license_id = @license_id
				delete from customer_email where customer_id = @customer_id
				delete from customer_company where customer_id = @customer_id
				delete from customer where customer_id = @customer_id
				delete from vendor_customer where vendor_customer_id = @vendor_customer_id
				--print ('backout')
				--select success = 0	
				return
			end




	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 10 )  RETURN
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @error = 0
		begin
			set @response_code = 0
			set @message = 'License created successfully'
		end
	
	/*select success =
		case 
			when @error = 0 then 1
			else 0
		end
	*/







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_insert_licenses]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_bulk_load_insert_licenses]

(
	@license_bulk_load_id int,
	@system_user varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2014-08-12	esmart		2015 S2 Gamer support 
	2015-02-18	acoffel		added 1 million license_id support
	2019-06-18	wbarton		Adding support for WiFi
	2021-03-29	jberry		Added support for incomm

	DESCRIPTION
	select 
*/

AS
	
set nocount on

declare @keycode_count int,
		@quantity int,
		@days_override int,
		@product_id int,
		@module_product_id int,
		@license_keycode_type_id int,
		@product_line_id int,
		@insert_date datetime,
		@keycode varchar(40),
		@seats int,
		@license_status_id int,
		@license_type_id int,
		@license_distribution_method_id int,
		@max_daily_activations int,
		@max_child_licenses int,
		@license_expiration_date datetime,
		@license_bulk_status_id int,
		@enterprise_seats int,
		@fixed_expiration_OEM tinyint,
		@license_feature_id int,
		@response_code int,
		@message varchar(100),
		@license_category_id INT 

	select @keycode_count = 0, @insert_date = getdate()

	begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Insert preliminary license_bulk_load_license records
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) update status
	select @license_bulk_status_id = (select license_bulk_status_id from license_bulk_status where license_bulk_status_description = 'creating licenses')

	update license_bulk_load
	set license_bulk_status_id = @license_bulk_status_id
	where license_bulk_load_id = @license_bulk_load_id

	-- 1.2) update product
	select @product_id = product_id,
			@module_product_id = module_product_id,
			@license_keycode_type_id = license_keycode_type_id,
			@quantity = quantity,
			@product_line_id = product_line_id,
			@license_status_id = license_status_id,
			@license_type_id = license_type_id,
			@license_distribution_method_id = license_distribution_method_id,
			@max_daily_activations = max_daily_activations,
			@max_child_licenses = max_child_licenses,
			@license_expiration_date = license_expiration_date,
			@enterprise_seats = enterprise_seats,
			@fixed_expiration_OEM = fixed_expiration_OEM,
			@module_product_id = module_product_id,
			@days_override = days_override
	from license_bulk_load 
	where license_bulk_load_id = @license_bulk_load_id

	-- 1.3) @license_feature_id
	select @license_feature_id = license_feature_id from license_feature where license_feature_name = 'Fixed expiration OEM'

	--select * from license_bulk_load 
	--where license_bulk_load_id = @license_bulk_load_id
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) license_bulk_load_license
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--2.1) If the bulk load is for WiFi, carts and orders need to be created via usp_license_bulk_load_insert_wifi_licenses
	SELECT @license_category_id = license_category_id
	FROM dbo.product_license_category
	WHERE product_id = @product_id

	IF @license_category_id 
= 135
	BEGIN
		SELECT @seats = seats
		FROM dbo.product_seat
		WHERE product_id = @product_id
		EXEC dbo.usp_license_bulk_load_insert_wifi_licenses @quantity = @quantity, @license_seats = @seats, @license_bulk_load_id = @license_bulk_load_id, @days_override = @days_override
	END 
	ELSE 
	BEGIN 

		-- 2.2) insert license_bulk_load_license

		while @keycode_count < @quantity
			begin

				set @keycode_count = @keycode_count + 1

				if @license_keycode_type_id = 1
					begin
						exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					end
				else if @license_keycode_type_id = 2
					begin 
						exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					end
				
				insert into license_bulk_load_license (license_bulk_load_id, keycode, product_id, insert_date)
				values (@license_bulk_load_id, @keycode, @product_id, @insert_date)

			end

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3) Insert license records and update license_bulk_load_license with new license_id's 
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
			-- 3.1) insert license
			insert into license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by)
			select 	l.keycode,
				b.product_line_id,
				license_status_id = 0,
				b.license_type_id,
				b.license_distribution_method_id,
				b.max_daily_activations,
				b.max_child_licenses, 
				b.license_expiration_date,
				b.insert_date,
				b.insert_by,
				b.modified_date,
				b.modified_by
			from license_bulk_load_license l
			inner join license_bulk_load b
				on l.license_bulk_load_id = b.license_bulk_load_id
			where l.license_bulk_load_id = @license_bulk_load_id

			-- 3.2) update license_bulk_load_license with license_id
			update license_bulk_load_license
			set license_id = l.license_id
			from license_bulk_load_license b
			inner join license l
				on b.keycode = l.keycode
			where license_bulk_load_id = @license_bulk_load_id

			-- 3.3) license_capability
			insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
			select license_id, 
				capability_id, 
				capability_type_id, 
				capability_activation_days = case 
												when @days_override is not null and c.capability_activation_days is not null then @days_override
												else c.capability_activation_days
											end,
				insert_date = @insert_date,
				insert_by = @system_user,
				modified_date = @insert_date,
				modified_by = @system_user		
			from license_bulk_load_license b
			inner join product_capability c
				on b.product_id = c.product_id
			where license_bulk_load_id = @license_bulk_load_id
			order by b.license_id, c.capability_id
	
			-- 3.4) license_seat 
			select @seats = isnull(seats,0)
			from product_seat
			where product_id = @product_id

			if @product_line_id in (11,13,300,55) 
				begin
					insert into license_seat (license_id, license_seats)
					select license_id, @enterprise_seats
					from license_bulk_load_license b
					where license_bulk_load_id = @license_bulk_load_id
				end

			if @product_line_id not in (11,13,300,55) and @seats > 0
				begin
					insert into license_seat (license_id, license_seats)
					select li
cense_id, @seats
					from license_bulk_load_license b
					where license_bulk_load_id = @license_bulk_load_id
				end

			-- 3.5) license_storage
			declare @storage_gb int

			select @storage_gb = storage_gb
			from product_storage
			where product_id = @product_id

			if @storage_gb is not null
				begin
					insert into license_storage (license_id, storage_gb)
					select license_id, @storage_gb
					from license_bulk_load_license
					where license_bulk_load_id = @license_bulk_load_id
				end

			-- 3.6) subscription
			if @license_distribution_method_id in (select license_distribution_method_id from subscription_distribution_method)
			begin
					insert into subscription (subscription_type_id, license_id, serial_number, insert_date)
					select subscription_type_id = 0, 
							license_id, 
							serial_number = 'WBR00'+
												case 
														when @license_distribution_method_id = 937 then 'GM'
														when license_category_id = 1 then 'AS'
														when license_category_id = 2 then 'AV'
														when license_category_id = 100 or license_category_id = 115 then 'SA'
														when license_category_id = 3 or license_category_id = 110 then 'IS'
														when license_category_id = 4 or license_category_id = 120 then 'SC'
													end+
												case 
													when @license_distribution_method_id = 937 then '15'
													else '14'
												end+
												'0'+
												convert(varchar(9),bl.license_id),
							insert_date = getdate()
					from license_bulk_load b
					inner join product_license_category c
						on b.product_id = c.product_id
					inner join license_bulk_load_license bl
						on b.license_bulk_load_id = bl.license_bulk_load_id
					where b.license_bulk_load_id = @license_bulk_load_id
			end
	
			-- 3.7) insert license_category 
			if @license_category_id is not null 
				begin
					insert into license_category_license (license_id, license_category_id)
					select bl.license_id, @license_category_id
					from license_bulk_load b
					inner join license_bulk_load_license bl
						on b.license_bulk_load_id = bl.license_bulk_load_id
					where b.license_bulk_load_id = @license_bulk_load_id
				end

			-- 3.8) license_module_license

				-- 3.8.1) product 
				insert into license_module_license(license_id,license_module_id,license_module_type_id)
				select b.license_id, m.license_module_id, m.license_module_type_id
				from license_bulk_load_license b
				inner join product_license_module m
					on b.product_id = m.product_id
				where license_bulk_load_id = @license_bulk_load_id
				order by b.license_id, m.license_module_id

				-- 3.8.2) module product
				insert into license_module_license(license_id,license_module_id,license_module_type_id)
				select b.license_id, m.license_module_id, m.license_module_type_id
				from license_bulk_load_license b
				inner join license_bulk_load l
					on b.license_bulk_load_id = l.license_bulk_load_id
				inner join product_license_module m
					on l.module_product_id = m.product_id and m.license_module_id not in (select license_module_id from product_license_module where product_id = b.product_id)
				where b.license_bulk_load_id = @license_bulk_load_id
				order by b.license_id, m.license_module_id

			-- 3.9) fixed expiration OEM
			if @fixed_expiration_OEM is not null and @fixed_expiration_OEM = 1
				begin
					insert into license_feature_license(license_id,license_feature_id)
					select license_id, 8
					from license_bulk_load_license
					where license_bulk_load_id = @license_bulk_load_id
				end

			-- 3.10) incomm_license_status (Add records for dist methods 1111, 1112, 1113)

			if @license_distribution_method_id in (1111, 1112, 1113)
				begin
					insert into incomm_license_status (license_id, merchant_name, incomm_product_status_id, insert_date, insert_by, modified_date, modified_by, update_attempts, process_d
ate)
					select l.license_id, 'walmart', 4002, getdate(), @system_user, getdate(), @system_user, 0, null
					from license_bulk_load_license l
					left join incomm_license_status ils 
						on ils.license_id = l.license_id
					where l.license_bulk_load_id = @license_bulk_load_id and ils.license_id is null   
				end	
			
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 11) insert prevx queue
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if @product_line_id in (100,200,300,55)
			begin
			insert into prevx_update(license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
			select b.license_id, b.license_bulk_load_id, prevx_update_type_id = 100, prevx_update_status_id = 0, insert_date = @insert_date, modified_date = @insert_date, process_date = @insert_date
			from license_bulk_load_license b
			left join prevx_update u
				on b.license_id = u.license_id
			where b.license_bulk_load_id = @license_bulk_load_id and u.prevx_update_id is null
			end

	END 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 12) complete 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	set @license_bulk_status_id = (select license_bulk_status_id from license_bulk_status where license_bulk_status_description = 'licenses created')

	update license_bulk_load
	set license_bulk_status_id = @license_bulk_status_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_insert_load]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_bulk_load_insert_load]

(
	@license_bulk_load_description varchar(100),
	@product_line_id int,
	@product_id int,
	@module_product_id int,
	@license_distribution_method_id int,
	@quantity int,
	@days_override int,
	@enterprise_seats int,
	@license_type_id int,
	@fixed_expiration_OEM tinyint,
	@license_expiration_date datetime,
	@system_user varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@max_child_licenses int,
			@license_bulk_load_id int,
			@sql_string varchar(4000),
			@command varchar(1000),
			@task_number varchar(20),	
			@db_name varchar(100),
	
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @max_child_licenses
	if @license_type_id = 2
		begin
		select @max_child_licenses = @quantity
			,@quantity = 1
		end

	-- 1.2) @license_type_id
	if @product_line_id in (300,55) and @license_type_id = 1
		begin
		select @license_type_id = 4
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) license_bulk_load
		insert into license_bulk_load (license_bulk_load_description, product_line_id, product_id, module_product_id, license_distribution_method_id, quantity, days_override, enterprise_seats, max_child_licenses, license_type_id, fixed_expiration_OEM, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_bulk_load_group_id, license_status_id, license_keycode_type_id, max_daily_activations)
		values (@license_bulk_load_description, @product_line_id, @product_id, @module_product_id, @license_distribution_method_id, @quantity, @days_override, @enterprise_seats, @max_child_licenses, @license_type_id, @fixed_expiration_OEM, @license_expiration_date, getdate(), @system_user, getdate(), @system_user, 1, 1, 1, 1)

		select @license_bulk_load_id = scope_identity()

	-- 2.2) insert service broker queue
		select @task_number = (select isnull(max(task_number),0) from tasks..task_table) + 10
		select @command = 'exec usp_license_bulk_load_insert_licenses ' + convert(varchar(10),@license_bulk_load_id) + ', ' + '''' + @system_user + '' + ''''
		select @db_name = db_name()
		--print @command

		select @sql_string = 
			'insert into tasks..task_table (task_number, Command, NoTransaction) ' + 
			' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_bulk_load_insert_licenses ' + convert(varchar(10),@license_bulk_load_id) + ', ' + '''' + '''' + @system_user + '''' + '''' + '''' + ',0) '

		--select @sql_string

		execute(@sql_string)	

		execute tasks..QueueTasksProc

	-- 2.3) insert license_bulk_load_download
	declare @expiration_date datetime

	select @expiration_date = dateadd(dd,7.0,getdate())

	insert into license_bulk_load_download(license_bulk_load_id,expiration_date) 
	values(@license_bulk_load_id,@expiration_date)

	------------------------------------------------------------------------------------------------------------------------------
-------------------------------------------------------------------------------------------------
	-- 3) select output
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select license_bulk_load_id = @license_bulk_load_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_insert_wifi_licenses]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_bulk_load_insert_wifi_licenses]

(
	@quantity INT,
	@license_seats INT, 
	@license_bulk_load_id INT = NULL,
	@days_override INT = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2019-06-17	wbarton		Initial creation.

	DESCRIPTION
	Procedure to create cart and order records to enable bulk-generation of licenses and order tokens that follow the account_order model. WiFi is the initial use-case
*/

AS

SET NOCOUNT ON

BEGIN TRY

DECLARE @response_code INT,
        @message VARCHAR(100),
		@record INT = 1,
        @vendor_order_code VARCHAR(100),
        @cart_extension_json NVARCHAR(MAX),
        @customer_email VARCHAR(100),
        @external_customer_key VARCHAR(100),
        @cart_order_id INT,
        @order_header_id INT,
		@looper INT = 0,
		@item_json NVARCHAR(MAX),
		@years DECIMAL(18,3) 

DECLARE @cart_order TABLE (
    cart_order_id INT,
    vendor_order_code VARCHAR(100),
    site_id VARCHAR(50),
    offer_amount MONEY,
    total_amount MONEY,
    sub_total_amount MONEY,
    tax_amount MONEY,
    sales_order_date DATETIME,
    locale VARCHAR(50),
    insert_date DATETIME,
    insert_by VARCHAR(100),
    modified_date DATETIME,
    modified_by VARCHAR(100),
    cart_order_status_id TINYINT,
    currency_id INT,
    user_ip VARCHAR(100)
)

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 1.) Set up @item_json for cart order item insert, and loop for @quantity times and create cart, payment header, and order records 
-------------------------------------------------------------------------------------------------------------------------------------------------------------------
SELECT @years = CASE WHEN @license_bulk_load_id IS NULL THEN 1 ELSE
	(SELECT py.years
	FROM dbo.license_bulk_load lbl
		INNER JOIN product_years py
			ON py.product_id = lbl.product_id
	WHERE lbl.license_bulk_load_id = @license_bulk_load_id)
	END

--1.1)Build up the JSON for the cart_order_item insert later
SET @item_json = (
		SELECT 1 AS item_hierarchy_id, 'WIFI' AS license_category_name, @license_seats AS license_seats, @years AS years, 1 AS cart_item_bundle_id, 1 AS quantity
		FOR JSON PATH)

WHILE @looper < @quantity
BEGIN

--1.2)Incrementing @record based on the account_order_bulk_load table to avoid dupe vendor_order_code, customer_emails, and external_customer_key
	SELECT @record = ISNULL(MAX(account_order_bulk_load_id) + 1, 1)
	FROM dbo.account_order_bulk_load

--1.3)Resetting varaibles for each pass in the loop
	SET @vendor_order_code = 'WIFIBULKLOAD' + CAST(@record as varchar(50))
	SET @customer_email = CAST(@record as varchar(50)) + 'wifibulkload@webroot.com'
	SET @external_customer_key = CAST(@record as varchar(50)) + 'wifibulkload'
	SET @cart_extension_json = (select 'USD' as currency_code, @vendor_order_code as vendor_order_code, CAST(GETDATE() AS DATE) AS sales_order_date FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)
	
--1.4)Refreshing the @cart_order table variable, and creating a new cart
	DELETE @cart_order
	INSERT INTO @cart_order
	EXEC dbo.usp_cart_insert_cart_order @site_id=N'WRCART',@locale=N'en_US',@user_ip=N'',@cart_extension_json=@cart_extension_json,@response_code=@response_code OUTPUT,@message=@message OUTPUT

	SELECT @cart_order_id = cart_order_id
	FROM @cart_order

--1.5)Create cart_order_item, set cart_customer data, insert payment_header_record
	EXEC dbo.usp_cart_insert_cart_order_item @vendor_order_code=@vendor_order_code,@item_json=@item_json,@bundle_json=N'{"license_keycode_type_id":1,"keycode":null}',@response_code=@response_code OUTPUT,@message=@message OUTPUT
	EXEC dbo.usp_cart_update_cart_customer @vendor_order_code=@vendor_order_code,@first_name=NULL,@last_name=NULL,@company_name=NULL,@address_1=NULL,@address_2=NULL,@city=NULL,@state=NULL,@postal_code=NULL,@country=NULL,@phone_number=NULL,@customer_email=@customer_email,@opt_in=1,@customer_type_id=1,@vat_id=NULL,@external_customer_key=@external_customer_key,@response_code=@response_code OUTPUT,@message=@message OUTPUT
	EXEC dbo.usp_cart_insert_payment_header @vendor_order_code=@vendor_order_code,@merchant_id=N'webroot',@payment_method_name=N'NonPayment',@response_code=@response_code OUTPUT,@message=@message OUTPUT
	
--1.6)load the order
	EXEC dbo.usp_cart_load_order @cart_order_id=@cart_order_id,@autorenewal_flag=NULL,@download_instruction_type_id=NULL

	SELECT @order_header_id = order_header_id
	FROM dbo.cart_order_header WITH (NOLOCK)
	WHERE cart_order_id = @cart_order_id

--1.7)run license management
	EXEC dbo.usp_cart_insert_license_update_queue @order_header_id=@order_header_id,@order_type_group_id=1

	UPDATE dbo.order_header
	SET tax_total = 0, total_amount = 0, sub_total_amount = 0
	WHERE order_header_id = @order_header_id

	UPDATE dbo.order_item
	SET tax = 0, unit_price = 0, list_price = 0, item_total = 0
	WHERE order_header_id = @order_header_id

--1.8) Add licenses and orders created to logging table which maintains account_order_bulk_load_id as an incrementing value
	INSERT INTO dbo.account_order_bulk_load (license_bulk_load_id, license_id, order_header_id, account_registration_URL)
	SELECT @license_bulk_load_id, oil.license_id, @order_header_id, 'https://www.webroot.com/us/en/home/products/wifi-security?order_token=' + CAST(oh.order_header_token AS NVARCHAR(100))
	FROM dbo.order_header oh WITH (NOLOCK)
		INNER JOIN order_item oi WITH (NOLOCK)
			ON oh.order_header_id = oi.order_header_id
		INNER JOIN dbo.order_item_license oil WITH (NOLOCK)
			ON oi.order_item_id = oil.order_item_id
	WHERE oh.order_header_id = @order_header_id

--1.9) When applicable, adjust expiration date on the license based on what was configured in the bulk load
	IF @days_override IS NOT NULL AND @years*365 <> @days_override 
	BEGIN
		DECLARE @license_service_json NVARCHAR(max) = (
			SELECT l.keycode, SYSTEM_USER AS account_name, lc.license_category_name AS [license_category.license_category_name], DATEADD(dd, @days_override, GETDATE()) AS [license_category.expiration_date]--, lc.category_type_name AS [license_category.category_type_name]
			FROM account_order_bulk_load abl
				INNER JOIN license l WITH(NOLOCK)
					ON l.license_id = abl.license_id
				INNER JOIN license_category_license lcl WITH(NOLOCK)
					ON lcl.license_id = abl.license_id
				INNER JOIN license_category lc
					ON lc.license_category_id = lcl.license_category_id
			WHERE abl.account_order_bulk_load_id = @record
			FOR JSON PATH)
	
		EXEC dbo.usp_license_service_insert_service @license_service_type_name = 'license_update', @service_json = @license_service_json, @return_license_service_id = 0
	END
	 
--1.9)Resetting variables to NULL before the next loop
	SET @record = NULL
	SET @vendor_order_code = NULL
	SET @customer_email = NULL
	SET @external_customer_key = NULL
	SET @cart_extension_json = NULL
	SET @cart_order_id = NULL
	SET @order_header_id = NULL

	SET @looper = @looper + 1

END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 2.) insert records into license_bulk_load_license when applicable
-------------------------------------------------------------------------------------------------------------------------------------------------------------------
 IF @license_bulk_load_id IS NOT NULL
 BEGIN

	INSERT INTO dbo.license_bulk_load_license (license_bulk_load_id, keycode, product_id, license_id, insert_date, insert_by)
	SELECT abl.license_bulk_load_id, l.keycode, lbl.product_id, abl.li
cense_id, GETDATE(), SYSTEM_USER
	FROM dbo.account_order_bulk_load abl
		INNER JOIN dbo.license_bulk_load lbl
			ON abl.license_bulk_load_id = lbl.license_bulk_load_id
		INNER JOIN dbo.license l
			ON l.license_id = abl.license_id
	WHERE @license_bulk_load_id = abl.license_bulk_load_id

END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 3.) return
-------------------------------------------------------------------------------------------------------------------------------------------------------------------
SELECT @response_code = 0, @message = 'Success'

END TRY

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'Failed to generate WiFi subscription' ELSE @message END
	DECLARE @dbname NVARCHAR(128)
	SET @dbname = DB_NAME()
	EXEC dbo.usp_LogError @ErrorDB = @dbname

END CATCH
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_select_BB_licenses]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_bulk_load_select_BB_licenses]

(
	@license_bulk_load_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-01-13	esmart		Initial creation.

	DESCRIPTION
	return results of Best Buy Bulk loads
*/

AS
	set nocount on
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select keycode = substring(keycode,1,4)+'-'+substring(keycode,5,4)+'-'+substring(keycode,9,4)+'-'+substring(keycode,13,4)+'-'+substring(keycode,17,4),
			serial_number = substring(serial_number,1,9)+' '+substring(serial_number,10,5)+' '+substring(serial_number,15,5)
	from license_bulk_load_license l
	inner join subscription s
		on l.license_id = s.license_id
	where license_bulk_load_id = @license_bulk_load_id


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_select_download]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_bulk_load_select_download]

(
	@download_key varchar(36) = null,
	@order_header_id int = null,
	@license_id int = null
)
	
/*	
	DATE			AUTHOR		REMARKS
	2014-10-28 	esmart		Initial creation
	2017-07-12	acoffel		added license_id
	
	DESCRIPTION
	select license bulk download
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100),
			@license_bulk_load_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @license_id is NULL and @order_header_id is not NULL and @download_key is NULL
		begin
		select d.license_bulk_load_download_id, d.license_bulk_load_id, download_key = convert(varchar(36),d.download_key), d.insert_date, d.expiration_date, d.status, h.order_header_id, v.vendor_order_code,
		p.product_description
		from license_bulk_load_download d
		left join order_item_license_bulk_load il
			on d.license_bulk_load_id = il.license_bulk_load_id
		left join order_item i
			on il.order_item_id = i.order_item_id
		left join product p
			on i.product_id = p.product_id
		left join order_header h
			on i.order_header_id = h.order_header_id
		left join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		where d.download_key = case when @download_key is not null then @download_key else d.download_key end and	
		h.order_header_id = case when @order_header_id is not null then @order_header_id else h.order_header_id end
		end	
			
	if @license_id is NULL and @order_header_id is NULL and @download_key is not NULL
		begin
		select d.license_bulk_load_download_id, d.license_bulk_load_id, download_key = convert(varchar(36),d.download_key), d.insert_date, d.expiration_date, d.status, h.order_header_id, v.vendor_order_code,
			p.product_description
		from license_bulk_load_download d
		left join order_item_license_bulk_load il
			on d.license_bulk_load_id = il.license_bulk_load_id 
		left join order_item i
			on il.order_item_id = i.order_item_id
		left join product p
			on i.product_id = p.product_id
		left join order_header h 
			on i.order_header_id = h.order_header_id 
		left join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		where d.download_key = @download_key
		end
	
	if @license_id is not NULL 		
		begin
		select @license_bulk_load_id = license_bulk_load_id from license_bulk_load_license where license_id = @license_id

		select d.license_bulk_load_download_id, d.license_bulk_load_id, download_key = convert(varchar(36),d.download_key), d.insert_date, d.expiration_date, d.status, h.order_header_id, v.vendor_order_code,
			p.product_description
		from license_bulk_load_download d
		left join order_item_license_bulk_load il
			on d.license_bulk_load_id = il.license_bulk_load_id
		left join order_item i
			on il.order_item_id = i.order_item_id
		left join product p
			on i.product_id = p.product_id
		left join order_header h
			on i.order_header_id = h.order_header_id
		left join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		where d.license_bulk_load_id = @license_bulk_load_id
		end
			
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_bulk_load_select_product]
-- =============================================================================

CREATE procedure [dbo].[usp_license_bulk_load_select_product]
(
	@locale tinyint, 
	@pack tinyint
)

as

/*	
		DATE		AUTHOR		REMARKS
		2012-04-04	esmart		Add additional product lines
		
		DESCRIPTION
		select products for bulk keycode generator

*/

set nocount on 

	declare @trial_product_line_id int,
			@product_line_id int,
			@ww_product_line_id int,
			@ps_product_line_id int,
			@ad_product_line_id int,
			@cl_product_line_id int,
			@cl_enterprise_product_line int,
			@ad_enterprise_product_line int

--select * from product_line

	if @locale = 1
		begin
--		select @trial_product_family_id = 11, @ww_product_family_id = 31, 
		select @ww_product_line_id = 20, @ps_product_line_id = 18, @cl_product_line_id = 100,  @cl_enterprise_product_line = 300, @ad_product_line_id = 50, @ad_enterprise_product_line = 55
		end
	else
		begin
--		select @trial_product_family_id = 12, @ww_product_family_id = 32
		select @ww_product_line_id = 21, @ps_product_line_id = 19, @cl_product_line_id = 200, @ad_product_line_id = 51
		end

	select p.product_id, p.product_description, p.product_family_id, p.retail_price, s.seats, c.license_category_id, pl.product_line_id,y.years
	from product p
	left join product_license_category c
		on p.product_id = c.product_id 
	inner join product_seat s
		on p.product_id = s.product_id
	inner join product_years y
		on p.product_id = y.product_id
	inner join product_line_product pl
		on p.product_id = pl.product_id
	where p.product_type_id = 1 and
					(pl.product_line_id = @product_line_id or 
					pl.product_line_id = @ww_product_line_id or 
					pl.product_line_id = @ps_product_line_id or
					pl.product_line_id = @ad_product_line_id or
					pl.product_line_id = @cl_product_line_id or
					pl.product_line_id = @cl_enterprise_product_line or
					pl.product_line_id = @ad_enterprise_product_line) and
					p.uses_keycode = 1 and 
					p.product_lifecycle_id = 1 and
					s.seats = @pack and
					y.years is not null
	order by pl.product_line_id, c.license_category_id, p.product_family_id, y.years

GO
