-- PROCEDURE: [dbo].[usp_license_bulk_load_update_download]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_bulk_load_update_download]

(
	@download_key varchar(36),
	@status varchar(20) = null,
	@expiration_date datetime = null
)
	
/*	
	DATE			AUTHOR		REMARKS
	2014-10-28		esmart		Initial creation
	2015-07-21		esmart		Add additional update parameters
	
	DESCRIPTION
	update license bulk download
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	update license_bulk_load_download
	set status = case when @status is null then status else @status end,
		expiration_date = case when @expiration_date is null then expiration_date else @expiration_date end
	where download_key = @download_key

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
