-- PROCEDURE: [dbo].[usp_license_channel_license_sfdc_sync]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_channel_license_sfdc_sync]
AS
/*
        DATE        AUTHOR      REMARKS
        2015-08-24  acoffel     Initial creation.
        2018-03-05  acoffel     new biz logic
        2018-05-10  jnavarra    Update to utilize refactored code for unified logic
        2019-11-21  jnavarra    Temp hotfix to keep appropriate companies in license_channel_id=5
        2019-12-26  jnavarra    Remove hotfix

        DESCRIPTION
        Use to update license channel routing. Intended to be run as a scheduled job
*/

SET NOCOUNT ON;

DECLARE @response_code INT,
        @message VARCHAR(100);

BEGIN TRY

    EXEC dbo.usp_license_channel_license_update

END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'update failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_channel_license_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_channel_license_update]
(
    @debug INT = 0
)
AS

/*
        DATE        AUTHOR      REMARKS
        2015-08-24  acoffel     Initial creation.
        2018-05-10  jnavarra    Update to utilize refactored function for unified logic when selecting child licenses
                                Remove delay to prevent blocking Service Broker queue
                                Add license/order_header filter handling
        2018-05-14  jnavarra    Change order to exclude partner trials before routing logic
        2018-05-15  jnavarra    Add debug parameter
        2018-06-13  jnavarra    Hotfix: Disambiguate Salesforce joined tables and remove debug transactional stuff
                                        Ignore "deleted" Salesforce records
        2018-06-20  jnavarra    Convert linked server references to views to improve testability
                                Restrict additional "deleted" Salesforce records
                                Use CTE and GROUP BY to eliminate duplicates
        2018-08-15  jnavarra    Remove single license_id and order_header filter and take table of license_ids instead
                                Delete records that don't match conditions, but are in input set
        2018-09-05  jnavarra    Add license channel 4 (GSMC cart)
        2018-09-11  jnavarra    Add logic for mobile and web
        2018-10-17  jnavarra    New flow and eliminate calculation of channel 1
        2018-10-22  jnavarra    Improve performance by better handling of child keys (but lose ability to operate on a subset of licenses)
        2018-11-06  jnavarra    Track logical block to ease debugging
        2018-11-27  jnavarra    Bring back overage and utility billing block to accommodate GSMC Phase 1 release
        2018-11-29  jnavarra    Remove overage and utility billing block to accommodate GSMC Phase 2 release
        2018-12-10  jnavarra    Exclude non-enterprise licenses from Partner Trial logic
        2019-01-08  jnavarra    Add SFDC "Not for Resale" logic
        2019-01-09  jnavarra    Update for new mobile handling
        2019-01-24  jnavarra    Fix update bugs/performance
        2019-04-15  jnavarra    Override for international GSMC
        2019-07-22  jnavarra    Remove hotfix with release of improved GSM migration and backfill
        2019-10-03  jnavarra    New logic for Strategic Distributors
        2019-11-08  jnavarra    Bug fixes and performance improvements
        2019-12-04  jnavarra    New logic for O365
        2020-04-06  jnavarra    Include Carbonite Endpoint (CBEP) with O365 logic
        2020-04-15  jnavarra    Initial license channel exemptions
        2020-04-22  jnavarra    Data-driven logic blocks
        2020-04-24  jnavarra    Performance (remove merge stmt) and clean-up
        2021-12-08  psatish     Added Perpetual Billing model to update the license channel
        2024-12-16  jberry      US-4767893 - Changed Carbonite license channel logic to assign indirect partner licenses to the Indirect MSP/Not For Resale license channel
                                Added new temp table for most recent orders for a license and flag for indirect customers eligable for online renewal
                                Added app-configs for indirect partner license categories and indirect partner company types
                                Added a section to assign direct customers and indirect customers eligible for online renewal to the Non-GSM Direct Customer license channel
        2025-03-24  jberry      D-5246059 - Fixed an issue in Channel 5: Indirect Partners causing customers ineligible for online renewal to be routed to the GSM/C cart


        DESCRIPTION
        U
se to update license channel routing
*/

IF @debug = 0
    BEGIN
        SET NOCOUNT ON
    END

DECLARE @response_code INT,
        @message VARCHAR(100);

BEGIN TRY

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Prepare
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    DROP TABLE IF EXISTS #all_licenses

    CREATE TABLE #all_licenses
    (
        license_id INT NOT NULL PRIMARY KEY,
        license_channel_id INT NOT NULL,
        gsm BIT NOT NULL,
        order_header_id INT NULL,
        license_channel_logic_id INT NULL
    );

    --app-config
    DECLARE @BUSINESS_PRODUCT_LINE TABLE
    (
        product_line_id INT
	)
	INSERT INTO @BUSINESS_PRODUCT_LINE
	(
           product_line_id
	)
	SELECT f.[key]
	FROM [dbo].[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL') f

	DECLARE @INDIRECT_PARTNER_LICENSE_CATEGORIES TABLE
	(
        license_category_id INT,
        license_category_name VARCHAR(10)
	)
	INSERT INTO @INDIRECT_PARTNER_LICENSE_CATEGORIES
	(
           license_category_id,
           license_category_name
	)
	SELECT f.[key],
           f.value
	FROM [dbo].[fn_app_config_select_key_values]('INDIRECT_PARTNER_LICENSE_CATEGORIES', 'LICENSE_CHANNEL_LOGIC') f

	DECLARE @INDIRECT_PARTNER_LICENSE_CATEGORIES_WSA TABLE
	(
        license_category_id INT,
        license_category_name VARCHAR(10)
	)
	INSERT INTO @INDIRECT_PARTNER_LICENSE_CATEGORIES_WSA
	(
           license_category_id,
           license_category_name
	)
	SELECT f.[key],
           f.value
	FROM [dbo].[fn_app_config_select_key_values]('INDIRECT_PARTNER_LICENSE_CATEGORIES_WSA', 'LICENSE_CHANNEL_LOGIC') f

	DECLARE @INDIRECT_PARTNER_COMPANY_TYPES TABLE
	(
        company_type_id INT,
        company_type VARCHAR(25)
	)
	INSERT INTO @INDIRECT_PARTNER_COMPANY_TYPES
	(
           company_type_id,
           company_type
	)
	SELECT f.[key],
           f.value
	FROM [dbo].[fn_app_config_select_key_values]('INDIRECT_PARTNER_COMPANY_TYPES', 'LICENSE_CHANNEL_LOGIC') f

    --capture most recent order for a license
    DROP TABLE IF EXISTS #most_recent_order
    CREATE TABLE #most_recent_order (license_id INT NOT NULL, order_item_id INT null, online_renewal_enabled VARCHAR(5) DEFAULT 'N')
    CREATE NONCLUSTERED INDEX IX_most_recent_order_temp
    ON #most_recent_order (
    license_id,
    order_item_id
    )
    INSERT INTO #most_recent_order
    (
    license_id,
    order_item_id   
    )
    SELECT oil.license_id,
           MAX(oi.order_item_id) AS order_item_id
    FROM dbo.order_item_license oil WITH (NOLOCK)
        INNER JOIN dbo.order_item oi WITH (NOLOCK)
            ON oi.order_item_id = oil.order_item_id
        INNER JOIN dbo.order_header oh WITH (NOLOCK)
            ON oh.order_header_id = oi.order_header_id
        INNER JOIN dbo.order_company oc WITH (NOLOCK)
            ON oc.order_header_id = oh.order_header_id
        INNER JOIN dbo.license l WITH (NOLOCK)
            ON l.license_id = oil.license_id
        INNER JOIN @BUSINESS_PRODUCT_LINE bpl
            ON bpl.product_line_id = l.product_line_id
    GROUP BY oil.license_id;

    --update online renewal enabled licenses
    UPDATE mro
    SET mro.online_renewal_enabled = 'Y'
    FROM #most_recent_order mro
        INNER JOIN dbo.order_item oi WITH (NOLOCK)
            ON oi.order_item_id = mro.order_item_id
        INNER JOIN dbo.order_header oh WITH (NOLOCK)
            ON oh.order_header_id = oi.order_header_id
        INNER JOIN dbo.order_company oc WITH (NOLOCK)
            ON oc.order_header_id = oh.order_header_id
        INNER JOIN d
bo.company_configuration_company ccc WITH (NOLOCK)
            ON ccc.company_id = oc.company_id
        INNER JOIN dbo.company_configuration cc WITH (NOLOCK)
            ON cc.company_configuration_id = ccc.company_configuration_id
    WHERE cc.configuration_name = 'online_renewal'
    AND ccc.configuration_value = 'enabled'	

    -- Capture the active logic blocks
    DECLARE @steps TABLE (license_channel_logic_id INT, license_channel_logic_name VARCHAR(50), license_channel_id TINYINT, priority INT)

    INSERT INTO @steps (license_channel_logic_id, license_channel_logic_name, license_channel_id, priority)
    SELECT license_channel_logic_id, license_channel_logic_name, license_channel_id, priority
    FROM dbo.license_channel_logic
    WHERE enabled = 1
		
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Calculate data
    --      This was set up initially in priority order. That doesn't mean it is still up to date. The priority and status (enabled/disabled) can change. Look at
    --      license_channel_logic to see the proper logical flow.
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    DECLARE
        @license_channel_logic_id INT,
        @license_channel_logic_name VARCHAR(50),
        @license_channel_id TINYINT,
        @debug_string VARCHAR(100)

    DECLARE @license_subset TABLE (license_id INT NOT NULL PRIMARY KEY, license_channel_id INT NOT NULL, gsm BIT NOT NULL, order_header_id INT NULL, license_channel_logic_id INT NULL)

    WHILE 1=1
        BEGIN
            -- Select the next step
            SELECT TOP(1)
                @license_channel_logic_id = license_channel_logic_id,
                @license_channel_logic_name = license_channel_logic_name,
                @license_channel_id = license_channel_id
            FROM @steps
            ORDER BY priority, license_channel_logic_id

            IF @@rowcount = 0
                BEGIN
                    -- Nothing left to do
                    BREAK
                END

            SET @debug_string = CONCAT('Logic ID: ', @license_channel_logic_id, ' - Name: ', @license_channel_logic_name, ' - Channel: ', @license_channel_id)

            IF @debug = 1
                BEGIN
                    PRINT CONCAT(@debug_string, ' - Selected')
                END



            -- Clear any previous results
            DELETE FROM @license_subset

            

            -- Work, work, work
            IF @license_channel_logic_id = 1        -- Channel 3: Web Security
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.license l WITH (NOLOCK)
                        INNER JOIN dbo.license_category_license lcl WITH (NOLOCK)
                            ON lcl.license_id = l.license_id
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                    WHERE l.product_line_id = 300                                                                       --Webroot SecureAnywhere Business
                        AND lcl.license_category_id = 212                                                               --Webroot SecureAnywhere Web Security
            
            AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 2   -- Channel 3: Not for Resale
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.license l WITH (NOLOCK)
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                    WHERE l.license_distribution_method_id = 973                                                        --Not For Resale
                        AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 3   -- Channel 3: SFDC Not for Resale
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.vw_license_channel_Salesforce_SBQQ_Quote sq WITH (NOLOCK)
                       INNER JOIN dbo.vw_license_channel_Salesforce_Opportunity so WITH (NOLOCK)
                           ON so.Id = sq.SBQQ__Opportunity2__c AND so.IsDeleted = 0
                       INNER JOIN dbo.vw_license_channel_Salesforce_License__c sl WITH (NOLOCK)
                           ON sl.Opportunity__c = so.Id AND sl.IsDeleted = 0
                       INNER JOIN dbo.license l WITH (NOLOCK)
                           ON sl.Name = l.keycode
                       LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                           ON lp.child_license_id = l.license_id
                    WHERE sq.IsDeleted = 0
                       AND sq.RecordTypeId = '01261000000ivxHAAQ'
                       AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 4   -- Channel 5: Strategic Distributors
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    ;WITH
                        strategic_distributors AS (
                            SELECT *
                            FROM dbo.company
                            WHERE company_type_id = 27                                                          -- Strategic Distributor
                        )
                        INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                        SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, oc.order_header_id, @license_channel_logic_id
                        FROM dbo.order_item_license oil WITH (NOLOCK)
                            INNER JOIN #most_recent_order lo
                                ON lo.license_id = oil.license_id AND lo.order_item_id = oil.order_item_id
                            INNER JOIN dbo.license l WITH (NOLOCK)
                                ON l.license_id = lo.license_id
                            INNER JOIN dbo.order_item oi WITH (NOLOCK)
                                ON oi.order_item_id = lo.order_item_id
                            INNER JOIN dbo.order_header oh WITH (NOLOCK)
                                ON oh.order_header_id = oi.order_header_id
                            INNER JOIN dbo.order_company oc WITH (NOLOCK)
                                ON oc.order_header_id = oh.order_header_id
                            INNER JOIN strategic_distributors sd
                                ON sd.company_id = oc.company_id
                            INNER JOIN dbo.order_company_type oct WITH (NOLOCK)
                                ON oct.order_company_type_id = oc.order_company_type_id
                                    AND oct.order_company_type_id = 2                                           -- bill_to_account
                            LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                                ON lp.child_license_id = l.license_id
                        WHERE lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 6   -- Channel 3: Partners
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END                        

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.license l WITH (NOLOCK)
                        INNER JOIN dbo.partner_license pl WITH (NOLOCK)
                            ON l.license_id = pl.license_id
                                AND pl.partner_license_status_id = 2                                                     --Approved
                                AND pl.partner_id <> 5559                                                                --NOT "Webroot direct Partner"
                                AND pl.start_date <= GETDATE()
                                AND (pl.end_date IS NULL OR pl.end_date > GETDATE())                                     --License is in phase
                        INNER JOIN @BUSINESS_PRODUCT_LINE bpl
                            ON bpl.product_line_id = l.product_line_id
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                    WHERE l.license_type_id IN (2, 4)                                                                   --OEM or Enterprise
                        AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 7   -- Channel 3: Partner trials
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT t.license_id, @license_channel_id, 0, NULL, @license_channel_logic_id
                    FROM dbo.trial t WITH (NOLOCK)
                        INNER JOIN dbo.license l WITH (NOLOCK)
                            ON l.license_id = t.license_id
                        INNER JOIN dbo.partner_trial pt WITH (NOLOCK)
                            ON t.trial_id = pt.trial_id
                        INNER JOIN dbo.license_summary ls WITH (NOLOCK)
                            ON t.license_id = ls.license_id
                                AND ls.capability_type_id = 2
                        INNER JOIN @BUSINESS_PRODUCT_LINE bpl
                            ON bpl.product_line_id = l.product_line_id
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                    WHERE lp.child_license_id IS NULL
                END
   
         ELSE IF @license_channel_logic_id = 5   -- Channel 5: Indirect Partners
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, 0, oh.order_header_id, @license_channel_logic_id
                    FROM #most_recent_order o
                    INNER JOIN dbo.order_item_license oil WITH (NOLOCK)
                        ON o.license_id = oil.license_id 
                            AND o.order_item_id = oil.order_item_id
                    INNER JOIN dbo.order_item oi WITH (NOLOCK)
                        ON oil.order_item_id = oi.order_item_id
                    INNER JOIN dbo.order_header oh WITH (NOLOCK)
                        ON oi.order_header_id = oh.order_header_id
                    INNER JOIN dbo.order_company oc WITH (NOLOCK)
                        ON oh.order_header_id = oc.order_header_id 
                    INNER JOIN dbo.order_company_type oct WITH (NOLOCK) 
                        ON oct.order_company_type_id = oc.order_company_type_id
                    INNER JOIN dbo.company c WITH (NOLOCK)
                        ON oc.company_id = c.company_id
                    INNER JOIN dbo.license l WITH (NOLOCK) 
                        ON l.license_id = oil.license_id
                    INNER JOIN dbo.license_category_license lcl WITH (NOLOCK) 
                        ON lcl.license_id = l.license_id
                    INNER JOIN dbo.license_summary ls WITH (NOLOCK)                --license_summary links the license_key (code on the box) to the key_code, main reason for the join is to link to the "capability".
                        ON oil.license_id = ls.license_id
                    LEFT JOIN dbo.company_configuration_company ccc WITH (NOLOCK)
                        ON ccc.company_id = oc.company_id
                    LEFT JOIN dbo.company_configuration cc WITH (NOLOCK)
                        ON cc.company_configuration_id = ccc.company_configuration_id
                    LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                        ON lp.child_license_id = l.license_id
					LEFT JOIN dbo.license_module_license lml WITH (NOLOCK)
						ON lml.license_id = ls.license_id
                    LEFT JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES clc
                        ON clc.license_category_id = lcl.license_category_id
                    LEFT JOIN @INDIRECT_PARTNER_COMPANY_TYPES ipct
                       ON ipct.company_type_id = c.company_type_id
                    WHERE clc.license_category_id IS NOT null                      
                       AND (oc.order_company_type_id IN (3,4)                     --distributor, partner
                           OR ipct.company_type_id IS NOT NULL
                           OR ccc.configuration_value = 'disabled')
                       AND o.online_renewal_enabled = 'N'                         --exclude online renewal enabled licenses
                       AND ls.capability_type_id = 1                              --full
                       AND ls.license_type_id IN (2, 4)                           --OEM or Enterprise
                       AND lp.child_license_id IS NULL
                       AND lml.license_module_license_id IS null
                    UNION
                    --carbonite trials
                    SELECT DISTINCT ls.license_id, @license_channel_id, 0, null, @license_channel_logic_id
                    FROM dbo.license_summary ls WITH (NOLOCK)
                    INNER JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES clc
                        ON clc.license_category_id = ls.license_category_id
                    WHERE ls.capability_type_id = 2  --t
rial
                    UNION
                    --carbonite license with a module
                    SELECT DISTINCT ls.license_id, @license_channel_id, 0, null, @license_channel_logic_id
                    FROM dbo.license_summary ls WITH (NOLOCK)
                    INNER JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES clc
                        ON clc.license_category_id = ls.license_category_id
                    INNER JOIN dbo.license_module_license lml WITH (NOLOCK)
                        ON lml.license_id = ls.license_id
                    LEFT JOIN dbo.partner_license pl WITH (NOLOCK)
                        ON pl.license_id = ls.license_id
                    LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                        ON lp.child_license_id = ls.license_id
                    WHERE ls.capability_type_id = 1
                        AND pl.partner_license_id IS NULL
                        AND lp.child_license_id IS NULL
					
                END
            ELSE IF @license_channel_logic_id = 8   -- Channel 2: Reseller/Distributor
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT oil.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, oi.order_header_id, @license_channel_logic_id
                    FROM #most_recent_order o
                        INNER JOIN dbo.order_item_license oil WITH (NOLOCK)
                            ON o.license_id = oil.license_id
                                AND o.order_item_id = oil.order_item_id
                        INNER JOIN dbo.license_summary ls WITH (NOLOCK)                                       --license_summary links the license_key (code on the box) to the key_code, main reason for the join is to link to the "capability".
                            ON oil.license_id = ls.license_id
                        INNER JOIN dbo.license l WITH (NOLOCK)                                                --This join is needed for the license_keycode_type
                            ON ls.license_id = l.license_id
                        INNER JOIN dbo.license_category_license lcl WITH (NOLOCK)                                        
                            ON ls.license_id = lcl.license_id
                        INNER JOIN dbo.order_item oi WITH (NOLOCK)                                             --Order item detail
                            ON oil.order_item_id = oi.order_item_id
                        INNER JOIN dbo.order_header oh WITH (NOLOCK)                                           --Core order record
                            ON oi.order_header_id = oh.order_header_id
                        INNER JOIN dbo.order_company oc WITH (NOLOCK)
                            ON oh.order_header_id = oc.order_header_id
                                AND oc.order_company_type_id IN (3, 4)                                         --Partner or Distributor
                        INNER JOIN @BUSINESS_PRODUCT_LINE bpl
                            ON bpl.product_line_id = ls.product_line_id
                        LEFT JOIN dbo.license_channel_exemption lce
                            ON lce.license_channel_id = 2 AND lce.company_id = oc.company_id
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                        LEFT JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES_WSA clc
                            ON clc.license_category_id = lcl.license_category_id
                    WHERE clc.license_category_id IS NOT null                                                --Webroot SecureAnywhere Business Mobile Protectio
n, Webroot SecureAnywhere Endpoint Protection, Webroot SecureAnywhere User Protection
                        AND ls.license_type_id IN (2, 4)                                                       --OEM or Enterprise
                        AND ls.capability_type_id = 1                                                          --Full
                        AND lce.license_channel_exemption_id IS NULL
                        AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 9   -- Channel 3: SFDC MSP
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.vw_license_channel_Salesforce_License__c sl WITH (NOLOCK)
                        INNER JOIN dbo.license l WITH (NOLOCK)
                            ON sl.Name = l.keycode
                                AND sl.IsDeleted = 0
                        LEFT JOIN dbo.vw_license_channel_Salesforce_Lead sle WITH (NOLOCK)
                            ON sl.Lead__c = sle.Id
                                AND sle.IsDeleted = 0
                        LEFT JOIN dbo.vw_license_channel_Salesforce_Opportunity so WITH (NOLOCK)
                            ON sl.Opportunity__c = so.Id
                                AND so.StageName <> 'Lost'
                                AND so.IsDeleted = 0
                        LEFT JOIN dbo.vw_license_channel_Salesforce_Account sa WITH (NOLOCK)
                            ON so.AccountId = sa.Id
                                AND sa.IsDeleted = 0
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                    WHERE (
                            (so.Id IS NOT NULL
                                AND sa.Type IN ('MSP', 'MSP/Reseller Hybrid')
                                AND (so.Reseller_Account__c IS NOT NULL OR so.Distributor_Account__c IS NOT NULL)
                            )
                            OR
                            (so.Id IS NULL
                                AND sle.Account_Type__c IN ('MSP', 'MSP/Reseller Hybrid')
                                AND (sle.Reseller_Account__c IS NOT NULL OR sle.Distributor_Account__c IS NOT NULL)
                            )
                        )
                        AND lp.child_license_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 10  -- Channel 2: SFDC - Non-MSP
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, CASE WHEN l.license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                    FROM dbo.vw_license_channel_Salesforce_License__c sl WITH (NOLOCK)
                        INNER JOIN dbo.license l WITH (NOLOCK)
                            ON sl.Name = l.keycode
                                AND sl.IsDeleted = 0
                        INNER JOIN license_category_license lcl 
                            ON lcl.license_id = l.license_id
                        LEFT JOIN dbo.vw_license_channel_Salesforce_Lead sle WITH (NOLOCK)
                            ON sl.Lead__c = sle.Id
                                AND sle.IsDeleted = 0
                       
 LEFT JOIN dbo.vw_license_channel_Salesforce_Opportunity so WITH (NOLOCK)
                            ON sl.Opportunity__c = so.Id
                            AND so.StageName <> 'Lost'
                            AND so.IsDeleted = 0
                        LEFT JOIN dbo.vw_license_channel_Salesforce_Account sa WITH (NOLOCK)
                            ON so.AccountId = sa.Id
                                AND sa.IsDeleted = 0
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                        LEFT JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES clc
                            ON clc.license_category_id = lcl.license_category_id
                    WHERE (
                            (so.Id IS NOT NULL
                                AND sa.Type NOT IN ('MSP', 'MSP/Reseller Hybrid')
                                AND (so.Reseller_Account__c IS NOT NULL OR so.Distributor_Account__c IS NOT NULL)
                            )
                            OR
                            (so.Id IS NULL
                                AND sle.Account_Type__c NOT IN ('MSP', 'MSP/Reseller Hybrid')
                                AND (sle.Reseller_Account__c IS NOT NULL OR sle.Distributor_Account__c IS NOT NULL)
                            )
                        )
                        AND lp.child_license_id IS NULL
                        AND clc.license_category_id IS NULL
                END
            ELSE IF @license_channel_logic_id = 14   --Non-GSM Direct Customer
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    SELECT DISTINCT l.license_id, @license_channel_id, 0, NULL, @license_channel_logic_id
                    FROM dbo.license l WITH (NOLOCK)
                        INNER JOIN dbo.license_category_license lcl WITH (NOLOCK)
                            ON lcl.license_id = l.license_id
                        LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                            ON lp.child_license_id = l.license_id
                        LEFT JOIN @INDIRECT_PARTNER_LICENSE_CATEGORIES clc
                            ON clc.license_category_id = lcl.license_category_id
                        WHERE l.product_line_id = 300
                            AND clc.license_category_id IS NOT NULL
                            AND lp.child_license_id IS NULL						
                END
            ELSE IF @license_channel_logic_id = 11  -- Channel 4: GSMC Cart
                BEGIN
                    IF @debug = 1
                        BEGIN
                            PRINT CONCAT(@debug_string, ' - Work')
                        END

                    ;WITH
                        licenses_with_categories AS (
                            SELECT l.license_id, l.license_type_id, l.license_keycode_type_id
                            FROM dbo.license l WITH (NOLOCK)
                                INNER JOIN dbo.license_category_license lcl WITH (NOLOCK)
                                    ON lcl.license_id = l.license_id
                                LEFT JOIN dbo.license_parent lp WITH (NOLOCK)
                                    ON lp.child_license_id = l.license_id
                            WHERE lcl.license_category_id = 220
                                AND l.product_line_id = 300
                                AND lp.child_license_id IS NULL
                        ),
                        gsm1 AS (
                            SELECT lwc.license_id, lwc.license_keycode_type_id
                            FROM licenses_with_categories lwc
                                INNER JOIN dbo
.license_parent lp WITH (NOLOCK)
                                    ON lp.parent_license_id = lwc.license_id
                        ),
                        gsm2 AS (
                            SELECT lwc.license_id, lwc.license_keycode_type_id
                            FROM licenses_with_categories lwc
                            WHERE lwc.license_type_id = 2
                        ),
                        all_gsm AS (
                            SELECT * FROM gsm1
                            UNION
                            SELECT * FROM gsm2
                        )
                        INSERT INTO @license_subset(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                        SELECT license_id, @license_channel_id, CASE WHEN license_keycode_type_id = 3 THEN 1 ELSE 0 END, NULL, @license_channel_logic_id
                        FROM all_gsm
						
                end
            else if @license_channel_logic_id = 12  -- Channel 3: Override for international GSMC
                begin
                    if @debug = 1
                        begin
                            print concat(@debug_string, ' - Work')
                        end

                        -- We don't need to worry about any possible child licenses here because there are no child business licenses in @all_licenses
                        -- Not storing results, just updating the table directly
                        ;WITH 
                            overage_or_utility_licenses AS (
                                SELECT lcl.license_id
                                FROM #all_licenses lcl
                                    INNER JOIN dbo.license_effective_object leo WITH (NOLOCK)
                                        ON leo.license_id = lcl.license_id
                                WHERE lcl.license_channel_id = 4
                                    AND leo.effective_object_id = 2     -- license_attribute_license_value
                                    AND leo.effective_value IN (11, 12, 111, 112, 211, 212, 13, 113, 213)
                                    AND leo.effective_start_date <= GETDATE()
                                    AND (leo.effective_end_date IS NULL OR leo.effective_end_date > GETDATE())
                            ),
                            most_recent_orders AS (
                                SELECT oil.license_id, MAX(oil.order_item_id) AS order_item_id
                                FROM overage_or_utility_licenses oul
                                    INNER JOIN dbo.order_item_license oil WITH (NOLOCK)
                                        ON oil.license_id = oul.license_id
                                GROUP BY oil.license_id
                            ),
                            international_licenses AS (
                                SELECT mro.license_id
                                FROM most_recent_orders mro
                                    INNER JOIN dbo.order_item oi WITH (NOLOCK)
                                        ON oi.order_item_id = mro.order_item_id
                                    INNER JOIN dbo.order_header oh WITH (NOLOCK)
                                        ON oh.order_header_id = oi.order_header_id
                                WHERE oh.locale <> 'EN_US'
                            )
                            UPDATE lcl
                            SET lcl.license_channel_id = @license_channel_id, lcl.license_channel_logic_id = @license_channel_logic_id
                            FROM #all_licenses lcl
                                INNER JOIN international_licenses il
                                    ON il.license_id = lcl.license_id
                end
            else if @license_channel_logic_id = 13  -- Channel 3: Child keys
                begin
                    if @debug = 1
                        begin
                       
     print concat(@debug_string, ' - Work')
                        end

                    -- This is the bulk of the license_channel_license records
                    -- Not storing results, just updating the table directly for performance
                    insert into #all_licenses (license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
                    select lp.child_license_id as license_id, @license_channel_id, case when l.license_keycode_type_id = 3 then 1 else 0 end as gsm, null as order_header_id, @license_channel_logic_id
                    from dbo.license_parent lp with (nolock)
                        inner join dbo.license l with (nolock)
                            on l.license_id = lp.child_license_id
                                and l.product_line_id IN (55, 300)
                        left join #all_licenses a
                            on a.license_id = l.license_id
                    where a.license_id is null
                end



            -- Store the results
            if @debug = 1
                begin
                    select *
                    from @license_subset

                    print concat(@debug_string, ' - Store results')
                end

            insert into #all_licenses(license_id, license_channel_id, gsm, order_header_id, license_channel_logic_id)
            select new.license_id, new.license_channel_id, new.gsm, new.order_header_id, new.license_channel_logic_id
            from @license_subset new
                left join #all_licenses l
                    on l.license_id = new.license_id
            where l.license_id is null

            if @debug = 1
                begin
                    print '---------------------------------------------------------'
                end



            -- Delete the step to mark as complete
            delete
            from @steps
            where license_channel_logic_id = @license_channel_logic_id
        end





    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Update data
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


    -- Debug - MERGE is a single statement but may have performance problems, try switching to separate DML statements

    --merge dbo.license_channel_license as target
    --    using #all_licenses as source
    --        on (target.license_id = source.license_id)

    --    when matched
    --        and (target.license_channel_id <> source.license_channel_id or target.gsm <> source.gsm or isnull(target.order_header_id, '') <> isnull(source.order_header_id, '') or isnull(target.logic_block, '') <> source.logic_block)
    --        then
    --            update set
    --            target.license_channel_id = source.license_channel_id,
    --            target.gsm = source.gsm,
    --            target.order_header_id = source.order_header_id,
    --            target.last_modified_date = getdate(),
    --            target.last_modified_by = system_user,
    --            target.logic_block = source.logic_block

    --    when not matched by target
    --        then
    --            insert (license_id, license_channel_id, gsm, order_header_id, last_modified_date, last_modified_by, logic_block)
    --            values (source.license_id, source.license_channel_id, source.gsm, source.order_header_id, getdate(), system_user, source.logic_block)

    --    when not matched by source
    --        then
    --            delete

    --    output
    --        $action,
    --        inserted.*,
    --        deleted.*
    --    ;

    -- Update matching licenses with
 differences
    update lcl
    set lcl.license_channel_id = a.license_channel_id,
        lcl.gsm = a.gsm,
        lcl.order_header_id = a.order_header_id,
        lcl.last_modified_date = getdate(),
        lcl.last_modified_by = system_user,
        lcl.license_channel_logic_id = a.license_channel_logic_id
    from dbo.license_channel_license lcl with (nolock)
        inner join #all_licenses a
            on a.license_id = lcl.license_id
    where lcl.license_channel_id <> a.license_channel_id
        or lcl.gsm <> a.gsm
        or isnull(lcl.order_header_id, '') <> isnull(a.order_header_id, '')
        or lcl.license_channel_logic_id <> a.license_channel_logic_id                

    -- Insert new licenses that were picked up
    insert into dbo.license_channel_license (license_id, license_channel_id, gsm, order_header_id, last_modified_date, last_modified_by, license_channel_logic_id)
    select a.license_id, a.license_channel_id, a.gsm, a.order_header_id, getdate(), system_user, a.license_channel_logic_id
    from #all_licenses a
        left join dbo.license_channel_license lcl with (nolock)
            on lcl.license_id = a.license_id
    where lcl.license_id is null    

    -- Delete licences no longer picked up
    delete lcl
    from dbo.license_channel_license lcl with (nolock)
        left join #all_licenses a
            on a.license_id = lcl.license_id
    where a.license_id is null

    



    IF @debug = 1
        PRINT 'DEBUG enabled!';

END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'update license channel failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_check]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_check]

(
	@keycode varchar(40),
	@GUID varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2008-11-13	esmart		Initial creation.

	DESCRIPTION
	return results needed for license check
*/

AS
	set nocount on
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) cleanup @guid before performing query
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) retrun results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select license_id, keycode, license_status_id, license_type_id, capability_id, capability_name, capability_description, capability_type_id, capability_activation_date, capability_expiration_date, needs_registration, auto_renewal,
			days_left = 
				case 
					when datediff(dd,getdate(),c.capability_expiration_date) > 0 then datediff(dd,getdate(),c.capability_expiration_date)
					else 0
				end,
			needs_activation = 
				(select needs_activation = 
									case
										when count(*) = 0 then 1
										else 0
									end
				from license_activation with (nolock)
				where license_id = c.license_id and guid = @guid)
		from vw_license_check c with (nolock)
		where keycode = @keycode






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_check_insert_license_check_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_check_insert_license_check_update] (
	@response_code INT OUTPUT,
	@message VARCHAR(100) OUTPUT,
	@opt_args VARCHAR(100) = ''

)

/*	
	DATE		AUTHOR		REMARKS
	2008-11-13	esmart		Initial creation.
	2013-08-28	esmart		Add subscription
	2015-07-15	acoffel		added email opt_in
	2017-02-02	esmart		Add license_module_license support
	2018-12-28	rvinoche	Add license_effective_object for usage billing
	2026-05-05	gblandford	IM-5354138 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5354138
				- identify bulk churned events and set lower priority by storing last license_service_archive_id and license_service_id in license_check_update
				- added schemas, casing and formatting changes
				- added @opt_args for debugging purposes, allowing us to pass in arguments to identify specific runs in the logs if needed
				- remove  and replace with appropriate SET TRANSACTION ISOLATION LEVEL statements
				
	DESCRIPTION
	Snapshots the current high-water mark IDs from all license-related source tables and inserts a single checkpoint row into
	dbo.license_check_update. This checkpoint is consumed by dbo.usp_license_check_update_license_check to determine which
	licenses changed since the previous run and require downstream processing.

	RUN CONTEXT
	Called by SQL Agent job: license_check_maintenance_ecommerce
	Job step: exec usp_license_check_insert_license_check_update

	HIGH-LEVEL FLOW
	1) Collect MAX IDs under READ UNCOMMITTED from all license-related source tables, including:
	   - license, license_history, license_capability_history, license_feature_license
	   - license_attribute_license / _history, license_storage / _history
	   - storage_account / _audit, license_category_license / _history
	   - license_seat / _history, license_message / _archive
	   - subscription_history, subscription_external
	   - customer_audit, customer
	   - license_module_license / _history
	   - license_effective_object  (autobilling endpoint: effective_object_id = 2, is_dup = 0, license_category_id = 220)
	   - license_service_archive, license_service
	2) If @opt_args contains 'debug', SELECT all captured values for diagnostic inspection.
	3) Switch to READ COMMITTED and insert one consolidated checkpoint row into dbo.license_check_update.
	4) On success, set @response_code = 0 and @message = 'successfully inserted license_check_update'.
	5) On failure, set @response_code = -200 and log the error via dbo.usp_LogError.

	PARAMETERS
	@response_code INT OUTPUT : 0 on success, -200 on failure
	@message VARCHAR(100) OUTPUT : Success/failure message
	@opt_args VARCHAR(100) = '' : Optional flags; pass 'debug' to emit captured checkpoint values for diagnostic use

	DEPENDENCIES
	dbo.license_check_update         (INSERT target — consumed by usp_license_check_update_license_check)
	dbo.license_effective_object     (autobilling high-water mark)
	dbo.license_service_archive      (bulk churn detection checkpoint)
	dbo.license_service              (service high-water mark)
	dbo.usp_LogError                 (error logging)
	All other source tables listed in step 1 above (read-only MAX queries)
*/

AS
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	SET NOCOUNT ON

	BEGIN TRY
	
		DECLARE @license_id INT,
			@license_history_id INT,
			@license_capability_history_id INT,
			@license_feature_license_id INT,
			@license_attribute_license_id INT,
			@license_attribute_license_history_id INT, 
			@license_storage_id INT, 
			@license_storage_history_id INT, 
			@storage_account_id INT, 
			@storage_account_audit_id INT,
			@license_category_license__historty_id INT,
			@license_category_li
cense_id INT,
			@license_seat_id INT,
			@license_seat_history_id INT,
			@license_message_id INT,
			@license_message_archive_id INT,
			@license_module_license_id INT,
			@license_module_license_history_id INT, 
			@subscription_history_id INT,
			@subscription_external_id INT,
			@customer_audit_id INT,
			@customer_id INT,
			@autobilling_effective_object_id INT,
			@license_service_id INT,
			@license_service_archive_id INT


		SELECT @response_code = 0, @message = 'successfully inserted license_check_update'

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) get values
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		SELECT @storage_account_audit_id = MAX(storage_account_audit_id) FROM dbo.storage_account_audit 
		SELECT @storage_account_id = MAX(storage_account_id) FROM dbo.storage_account 

		SELECT @license_storage_history_id = MAX(license_storage_history_id) FROM dbo.license_storage_history 
		SELECT @license_storage_id = MAX(license_storage_id) FROM dbo.license_storage 

		SELECT @license_attribute_license_history_id = MAX(license_attribute_license_history_id) FROM dbo.license_attribute_license_history 
		SELECT @license_attribute_license_id = MAX(license_attribute_license_id) FROM dbo.license_attribute_license 

		SELECT @license_feature_license_id = MAX(license_feature_license_id) FROM dbo.license_feature_license 

		SELECT @license_capability_history_id = MAX(license_capability_history_id) FROM dbo.license_capability_history 

		SELECT @license_history_id = MAX(license_history_id) FROM dbo.license_history 
		SELECT @license_id = MAX(license_id) FROM dbo.license 

		SELECT @license_category_license__historty_id = MAX(license_category_license__historty_id) FROM dbo.license_category_license_history  
		SELECT @license_category_license_id = MAX(license_category_license_id) FROM dbo.license_category_license 

		SELECT @license_seat_id = MAX(license_seat_id) FROM dbo.license_seat 
		SELECT @license_seat_history_id = MAX(license_seat_history_id) FROM dbo.license_seat_history 

		SELECT @license_message_id = ISNULL(MAX(license_message_id),0) FROM dbo.license_message 
		SELECT @license_message_archive_id = ISNULL(MAX(license_message_archive_id),0) FROM dbo.license_message_archive 
	
		SELECT @subscription_history_id = ISNULL(MAX(subscription_history_id),0) FROM dbo.subscription_history 
		SELECT @subscription_external_id = ISNULL(MAX(subscription_external_id),0) FROM dbo.subscription_external 

		SELECT @customer_audit_id = ISNULL(MAX(customer_audit_id),0) FROM dbo.customer_audit 
		SELECT @customer_id = ISNULL(MAX(customer_id),0) FROM dbo.customer 

		SELECT @license_module_license_history_id = MAX(license_module_license_history_id) FROM dbo.license_module_license_history 
		SELECT @license_module_license_id = MAX(license_module_license_id) FROM dbo.license_module_license 

		SELECT @autobilling_effective_object_id = MAX(license_effective_object_id) FROM dbo.license_effective_object  WHERE effective_object_id = 2 AND is_dup = 0 AND license_category_id = 220 --only endpoint for now

		SELECT @license_service_archive_id = ISNULL(MAX(license_service_archive_id),0) FROM dbo.license_service_archive
		SELECT @license_service_id = ISNULL(MAX(license_service_id),0) FROM dbo.license_service

		IF @opt_args LIKE '%debug%' BEGIN

				SELECT 
					@storage_account_audit_id AS storage_account_audit_id,
					@storage_account_id AS storage_account_id,
					@license_storage_history_id AS license_storage_history_id,
					@license_storage_id AS license_storage_id,
					@license_attribute_license_history_id AS license_attribute_license_history_id,
					@license_
attribute_license_id AS license_attribute_license_id,
					@license_feature_license_id AS license_feature_license_id,
					@license_capability_history_id AS license_capability_history_id,
					@license_history_id AS license_history_id,
					@license_id AS license_id,
					@license_category_license__historty_id AS license_category_license__historty_id,
					@license_category_license_id AS license_category_license_id,
					@license_seat_id AS license_seat_id,
					@license_seat_history_id AS license_seat_history_id,
					@license_message_id AS license_message_id,
					@license_message_archive_id AS license_message_archive_id,
					@subscription_history_id AS subscription_history_id,
					@subscription_external_id AS subscription_external_id,
					@customer_audit_id AS customer_audit_id,
					@customer_id AS customer_id,
					@license_module_license_id AS license_module_license_id,
					@license_module_license_history_id AS license_module_license_history_id,
					@autobilling_effective_object_id AS autobilling_effective_object_id,
					@license_service_id AS license_service_id,
					@license_service_archive_id AS license_service_archive_id

			END;

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) insert license_check_update
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

		INSERT INTO dbo.license_check_update (
			license_id, 
			license_history_id, 
			license_capability_history_id, 
			license_feature_license_id, 
			license_attribute_license_id, 
			license_attribute_license_history_id, 
			license_storage_id, 
			license_storage_history_id, 
			storage_account_id, 
			storage_account_audit_id,
			license_category_license__historty_id,
			license_category_license_id,
			license_seat_id,
			license_seat_history_id,
			license_message_id,
			license_message_archive_id,
			subscription_history_id,
			subscription_external_id,
			customer_audit_id,
			customer_id,
			license_module_license_id,
			license_module_license_history_id,
			autobilling_effective_object_id,
			license_service_id,
			license_service_archive_id
		) VALUES (
			@license_id, 
			@license_history_id, 
			@license_capability_history_id, 
			@license_feature_license_id, 
			@license_attribute_license_id, 
			@license_attribute_license_history_id, 
			@license_storage_id, 
			@license_storage_history_id, 
			@storage_account_id, 
			@storage_account_audit_id,
			@license_category_license__historty_id,
			@license_category_license_id,
			@license_seat_id,
			@license_seat_history_id,
			@license_message_id,
			@license_message_archive_id,
			@subscription_history_id,
			@subscription_external_id,
			@customer_audit_id,
			@customer_id,
			@license_module_license_id,
			@license_module_license_history_id,
			@autobilling_effective_object_id,
			@license_service_id,
			@license_service_archive_id
		)

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'execution of procedure dbo.usp_license_check_insert_license_check_update failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_check_license_migration]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_check_license_migration]

(
	@keycode varchar(40),
	@parent_license_flag bit = NULL,
	@child_license_flag bit = NULL
)

AS

/*	
	DATE			AUTHOR		REMARKS
	2016-08-26		acoffel		license migration
	2019-01-09		rvinoche	remove reference to license_attribute_license (not used)

	DESCRIPTION
	select license migration details


*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	declare @license_id int, 
			@keycode_alias varchar(40),
			@account_id int, 
			@account_user_name varchar(100),
			@capability_type_id int, 
			@parent_license_id int,
			@parent_keycode varchar(40),
			@license_category_id tinyint, 
			@license_category_name varchar(10),	
			@license_category_description varchar(50),
			@license_migration varchar(10),
			@start_date datetime,
			@end_date datetime, 
			@oem_type varchar(50)

	
	-- 1.0) @license_id
	select @license_id = license_id
	from license 
	where keycode = @keycode

	if @license_id is null
		begin
		select @license_id = license_id,
				@keycode_alias = keycode_alias
		from license_keycode_alias 
		where keycode_alias = @keycode 
		end


	-- 1.2) check account_device
	if @account_id is null
		begin
		select @account_id = account_id, @account_user_name = account_user_name
		from account
		where account_id in (select account_id from account_device where license_id = @license_id)
		end

	-- 1.3) select license_key
	if (select count(*) from license_key where license_id = @license_id) = 0 and @license_id is not null
		begin
		insert into license_key(license_id)
		values(@license_id)
		end

	-- 1.4) select license_parent
	select @parent_license_id = l2.license_id,
			@parent_keycode = l2.keycode
	from license_parent lp with(nolock)
	inner join license l2 with(nolock)
		on lp.parent_license_id = l2.license_id
	where lp.child_license_id = @license_id

	-- 1.6) select license_category
	select @license_category_id = c.license_category_id, 
			@license_category_name = c.license_category_name,	
			@license_category_description = c.license_category_description,
			@capability_type_id = ca.capability_type_id,
			@start_date = lc.start_date,
			@end_date = lc.end_date
	from license_capability ca with(nolock)
	inner join license_category_license lc with(nolock)
		on ca.license_id = lc.license_id 
	inner join license_category c with(nolock)
		on lc.license_category_id = c.license_category_id and ca.capability_id = c.base_capability_id
	where lc.license_id = @license_id

	-- 1.7) @oem_type
	select @oem_type = case
							when license_feature_license_id is null then null
							else 'Fixed expiration'
						end
	from license_feature_license
	where license_id = @license_id and license_feature_id = 8

	-- 1.8) @license_migration_keycode
	select @license_migration = case when count(*) > 0 then 'Yes' else 'No' end 
	from license_migration m
	where m.original_license_id = @license_id or m.new_license_id = @license_id

	
	if @parent_license_flag is not NULL
		begin
			-- 1.7) select parent license attributes
			select case when p.product_line_id = 300 then 'Pass product line check' else 'Fail product line check' end as product_line_check, 
				case when st.license_status_id = 1 then 'Pass license status check' else 'Fail license status check' end as license_status_check, 
				case when @license_category_id = 220 then 'Pass license category check' else 'Fail license category check' end as license_category_check,
				case when s.capability_type_id in (1,2) then 'Pass capability type check' else 'Fail capability type check' end as capability_type_check,
				case when l.license_keycode_type_id = 3 and s.capability_type_id in (
2) then 'usp_license_insert_license_migration' else 'usp_license_insert_child_license_new_parent_license' end as method
			from license l with(nolock)
			inner join product_line p with(nolock)
				on p.product_line_id = case when @license_category_id in (100,110,115,120) and l.product_line_id = 1 then 100 
											when @license_category_id in (100,110,115,120) and l.product_line_id = 6 then 200 
											else l.product_line_id
										end
			inner join license_type t with(nolock)
				on l.license_type_id = t.license_type_id
			inner join license_status st with(nolock)
				on l.license_status_id = st.license_status_id
			inner join license_summary s
				on l.license_id = s.license_id 
			left join license_seat se with(nolock)
				on l.license_id = se.license_id
			left join license_storage ls with(nolock)
				on l.license_id = ls.license_id
			left join license_keycode_alias a with(nolock)
				on l.license_id = a.license_id 
			left join subscription_distribution_method su
				on l.license_distribution_method_id = su.license_distribution_method_id
			left join sky_update_archive ar
				on l.license_id = ar.license_id
			where l.license_id = @license_id
		end
		else
		begin
			if @child_license_flag is not NULL
			begin
				-- 1.7) select parent license attributes
				select case when p.product_line_id = 300 then 'Pass product line check' else 'Fail product line check' end as product_line_check, 
				case when st.license_status_id = 1 then 'Pass license status check' else 'Fail license status check' end as license_status_check, 
				case when t.license_type_id = 4 then 'Pass OEM check' else 'Fail OEM check' end as license_type_check, 
				case when l.license_keycode_type_id = 3 then 'Fail GSM check' else 'Pass GSM check' end as license_keycode_type_check,
				case when @license_category_id = 220 then 'Pass license category check' else 'Fail license category check' end as license_category_check,
				case when s.capability_type_id = 1 then 'Pass capability type check' else 'Fail capability type check' end as capability_type_check,
				case when @license_migration = 'Yes' then 'usp_license_insert_child_license_new_parent_license' else 'usp_license_insert_license_migration' end as method
			from license l with(nolock)
			inner join product_line p with(nolock)
				on p.product_line_id = case when @license_category_id in (100,110,115,120) and l.product_line_id = 1 then 100 
											when @license_category_id in (100,110,115,120) and l.product_line_id = 6 then 200 
											else l.product_line_id
										end
			inner join license_type t with(nolock)
				on l.license_type_id = t.license_type_id
			inner join license_status st with(nolock)
				on l.license_status_id = st.license_status_id
			inner join license_summary s
				on l.license_id = s.license_id 
			left join license_seat se with(nolock)
				on l.license_id = se.license_id
			left join license_storage ls with(nolock)
				on l.license_id = ls.license_id
			left join license_keycode_alias a with(nolock)
				on l.license_id = a.license_id 
			left join subscription_distribution_method su
				on l.license_distribution_method_id = su.license_distribution_method_id
			left join sky_update_archive ar
				on l.license_id = ar.license_id
			where l.license_id = @license_id
		end
	end

		--parent_license_id = @parent_license_id,
		--parent_keycode = @parent_keycode,
		--license_category_id = @license_category_id, 
		--license_category_name = @license_category_name,	
		--license_category_description = @license_category_description,
		--start_date = @start_date,
		--end_date = @end_date,
		--account_id = @account_id,
		--account_user_name = @account_user_name,
		--license_key = @license_key,
		--license_attribute_id = @license_attribute_id,
		--license_attribute_description = @license_attribute_description,
		--license_attribute_tag = @license_attribute_tag,
		--license_attribute_license_value = @licens
e_attribute_license_value,
		--license_attribute_license_value_description = @license_attribute_license_value_description, 
		--license_attribute_last_modified = @license_attribute_last_modified,
		--oem_type = @oem_type,
		--license_migration = @license_migration


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select license migration failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_check_update_license_check]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_license_check_update_license_check] (
	@response_code INT OUTPUT,
	@message VARCHAR(100) OUTPUT,
	@opt_args VARCHAR(100) = ''
)

/*
	DATE		AUTHOR		REMARKS
	2008-11-13	esmart		Initial creation.
	2009-03-02	esmart		Add nolock
	2010-05-21	dsmelker	Added product_line_id
	2010-11-17	esmart		Add license_message support
	2011-07-22	esmart		Prevx support
	2011-09-02	esmart		Support for message_cycle
	2011-09-13	esmart		Add SME for prevx_update
	2011-09-30	esmart		Open prevx_update to all SS,AD,WSA product lines
	2011-10-13	esmart		Add cart_discount_id to license_message_check insert
	2011-12-20	esmart		Add license_keycode_alias copy
	2012-01-19	esmart		Add support for license_check_update_license.source
	2012-01-26	esmart		Update license_message_check insert to remove complete and abandoned messages
	2012-02-03	esmart		enable usp_licensing_update_license_keycode_alias
	2012-03-01	esmart		Add product_line_id 51 to Prevx queue
	2012-06-04	esmart		Add product_line_id 55 to Prevx queue
	2012-06-28	gjohnson	commented section 3.3.7, rewrote section 3.3.2 to use LEFT OUTER JOIN
	2013-08-28	esmart		subscription_history
	2014-06-18	acoffel		3.3.6 insert rows into wwss_update_license
	2015-07-15	acoffel		customer email opt_in
	2016-05-25	acoffel		sfdc license object update
	2016-11-07	acoffel		SFDC Parent Check
	2017-02-02	esmart		Add license_module_license support
	2017-07-19	esmart		Put left join on sfdc_opportunity_update to avoid duplicates
	2018-12-28	rvinoche	Use effective_object for usage billing attributes
	2019-01-23	acoffel		Exclude SOTI
	2019-04-15	esmart		Exclude legacy product_lines from customer_audit changes
	2020-03-20	cnovac		Added logic to write to sky_update when a CBEP hard cancel needs to take place
	2020-12-24	esmart		Remove CBEP hard cancel
	2021-09-28	psatish		Exclude the license update when there is no change on opt_in on the Customer
	2021-10-22	psatish		Netsuite Contracts are already provisioned, so stopped pushing the licenses into the Prevx Update table that are created from Contract Backfill
	2022-03-18	psatish		Added new license distribution method for contract Backfill
	2022-05-05	jberry		Per ALM defect 1193 - Adding back section 3.3.16 that was removed by Eric on 12/24/2020. This is being done to support the CBEP hard cancel for CYAN release 1. This needs to be removed for release 2
	2022-11-28	psatish		ALM# 3732 Removed the condition to insert the migrated licenses into sky_update
	2024-04-16	psatish		ECOM-3266 Modified section 3.3.4 to exclude Zuora licenses from being inserted into license_message_update_license
	2026-05-05	gblandford	IM-5354138 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5354138
				- identify bulk churned events and set lower priority by storing last license_service_archive_id in license_check_update
				- and then determining which license service updates were performed and whether they were license_churn events
				- use #temporary table to store the licenses, allowing us to remove table hints WITH (nolock) and setting TRANSACTION ISOLATION LEVEL
				- added schemas, casing and formatting changes
				- spelling correction: historty->history
				- added @opt_args for debugging purposes, allowing us to pass in arguments to identify specific runs in the logs if needed
					
								

	DESCRIPTION
    Identifies licenses changed since the last processed checkpoint, stages them, updates license summary, and queues downstream updates.

    RUN CONTEXT
    Called by SQL Agent job: license_check_maintenance_ecommerce
    Job step: exec usp_license_check_update_license_check

    HIGH-LEVEL FLOW
    1) Build changed license set from
 checkpointed source tables into temporary staging.
    2) Tag churn-related licenses with lower processing priority (priority = 9; default = 5).
	3) If @opt_args contains 'no_update', stop after staging and return before any persistent insert/update operations.
	4) Persist staged licenses for processing.
	5) Refresh license summary via dbo.usp_license_update_license_summary.
	6) Mark license_check_update rows as processed.
	7) Queue downstream work:
       - dbo.license_message_update_license
       - dbo.prevx_update_license (priority-aware)
       - dbo.sky_update_license
       - dbo.sfdc_opportunity_update
       - dbo.sky_update for CBEP cancel (template/type = CBEP_delete)
	8) Clear processed staging rows from dbo.license_check_update_license.

    PARAMETERS
    @response_code INT OUTPUT : Result code (-200 on failure)
    @message VARCHAR(100) OUTPUT : Result/error message
	@opt_args VARCHAR(100) = '' : Optional debug flag(s); pass 'no_update' to stop after staging and skip all persistent writes

    DEPENDENCIES
    dbo.usp_license_update_license_summary
    dbo.usp_licensing_update_license_keycode_alias
    dbo.usp_LogError
*/

AS

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

SET NOCOUNT ON

BEGIN TRY
                     
	DECLARE 
		@license_check_update_id INT,
		@last_license_check_update_id INT,
		@license_id INT,
		@last_license_id INT,
		@license_history_id INT,
		@last_license_history_id INT,
		@license_capability_history_id INT,
		@last_license_capability_history_id INT,
		@license_feature_license_id INT,
		@last_license_feature_license_id INT,
		@license_attribute_license_id INT,
		@last_license_attribute_license_id INT,
		@license_attribute_license_history_id INT,
		@last_license_attribute_license_history_id INT,
		@license_storage_id INT,
		@last_license_storage_id INT,
		@license_storage_history_id INT,
		@last_license_storage_history_id INT,
		@storage_account_id INT,
		@last_storage_account_id INT,
		@storage_account_audit_id INT,
		@last_storage_account_audit_id INT,
		@license_category_license_id INT,
		@last_license_category_license_id INT,
		@license_category_license_history_id INT,
		@last_license_category_license_history_id INT,
		@license_seat_id INT,
		@last_license_seat_id INT,
		@license_seat_history_id INT,
		@last_license_seat_history_id INT,
		@subscription_history_id INT,
		@last_subscription_history_id INT,
		@subscription_external_id INT,
		@last_subscription_external_id INT,
		@last_customer_audit_id INT,
		@customer_audit_id INT,
		@sfdc_template_id INT,
		@sfdc_update_type_id INT,
		@license_module_license_id INT,
		@last_license_module_license_id INT,
		@license_module_license_history_id INT,
		@last_license_module_license_history_id INT,
		@autobilling_effective_object_id INT,
		@last_autobilling_effective_object_id INT,
		@license_service_archive_id INT,
		@last_license_service_archive_id INT,
		@row_count INT

	DECLARE @license_table TABLE (license_id INT)

	DROP TABLE IF EXISTS #license_check_update_license;
	CREATE TABLE #license_check_update_license (
		license_id INT,
		[priority] INT DEFAULT (5) -- set default priority to 5 for non-churn events, allowing us to process them before churn events
	);

	DROP TABLE IF EXISTS #license_churn;
	CREATE TABLE #license_churn (
		license_id INT,
		[priority] INT DEFAULT (9)
	);

	DECLARE @debug TINYINT = 0,
		@no_update TINYINT = 0;

	IF @opt_args LIKE '%debug%' BEGIN
			SET @debug = 1;
			SELECT 'Initial variable declaration and temp table creation complete' AS debug_message;
		END
		
	IF @opt_args LIKE '%no_update%' BEGIN
			SET @no_update = 1;
			SELECT 'No update mode enabled' AS debug_message;
		END

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 1) set update data
	-- ----------------------------------------------------
------------------------------------------------------------------------------------

	-- 1.1) get license_check_update_ids

	SELECT @license_check_update_id = MAX(license_check_update_id) FROM dbo.license_check_update WHERE license_check_update_status = 0 
	SELECT @last_license_check_update_id = MAX(license_check_update_id) FROM dbo.license_check_update WHERE license_check_update_status = 1

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_check_update_id AS license_check_update_id,
				@last_license_check_update_id AS last_license_check_update_id;

		END

	-- 1.1.1) move any records from license_check_update_license into the temporary table, in case there are any records that were staged but not processed due to an error, 
	INSERT INTO #license_check_update_license (
		license_id
	)
	SELECT 
		DISTINCT license_id 
	FROM dbo.license_check_update_license lcul;

	CREATE NONCLUSTERED INDEX idx_license_check_update_license_license_id ON #license_check_update_license (license_id);

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 'from license_check_update_license' as step_name, priority, COUNT(*) AS row_count 
			FROM #license_check_update_license
			GROUP BY priority;
		END

	-- 1.1.2) get license_service_archive_id for bulk churn detection

	SELECT @last_license_service_archive_id = license_service_archive_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id;
	SELECT @license_service_archive_id = license_service_archive_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id;

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_service_archive_id AS license_service_archive_id,
				@last_license_service_archive_id AS last_license_service_archive_id;
		END

	-- 1.1.3) get license_churn records from license_service_archive 
	IF @last_license_service_archive_id <> @license_service_archive_id BEGIN

			PRINT 'license_service_archive'
			INSERT INTO #license_check_update_license (
				license_id,
				[priority]
			)
			OUTPUT Inserted.license_id, Inserted.[priority] INTO #license_churn (
				license_id,
				[priority]
			)
			SELECT DISTINCT
				l.license_id,
				9 -- set priority to 9 for churn events, allowing us to process them at the end 
			FROM dbo.license_service_archive lsa
				INNER JOIN dbo.license_service_type lst
					ON lst.license_service_type_id = lsa.license_service_type_id
				LEFT JOIN dbo.license_service_json lsj
					ON lsj.license_service_id = lsa.license_service_id
				CROSS APPLY OPENJSON(lsj.license_service_json, '$') WITH (
					[keycode] NVARCHAR(50) '$.keycode',
					[account_name] NVARCHAR(50) '$.account_name'
				) AS j
			INNER JOIN dbo.license l
				ON l.keycode = j.keycode
			LEFT JOIN dbo.license_check_update_license lcul
				ON lcul.license_id = l.license_id

			WHERE lsa.license_service_archive_id > @last_license_service_archive_id 
				AND lsa.license_service_archive_id <= @license_service_archive_id
				AND lsa.license_service_type_id = 21 -- license_update
				AND j.account_name = 'license_churn' -- churn events only
				AND lcul.license_id IS NULL;

			IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_service_archive->license_churn' as step_name, priority, COUNT(*) AS row_count 
					FROM #license_churn
					GROUP BY priority;
				END

		END

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 'license_check_update_license' AS step_name, priority, COUNT(*) AS row_count 
			FROM #license_check_update_license
			GROUP BY priority;
		END

	-- 1.2) license table
       
	SELECT @last_license_id = license_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_id = license_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_id AS license_id,
				@last_license_id AS la
st_license_id;
		END

	IF @last_license_id <> @license_id BEGIN
			PRINT 'license'
			INSERT INTO #license_check_update_license (license_id)
			SELECT DISTINCT license_id
			FROM dbo.license 
			WHERE license_id > @last_license_id 
				AND license_id <= @license_id

			SET @row_count = @@ROWCOUNT;
			IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license' as step_name, @row_count AS row_count
				END
		END
              
	-- 1.3) license_history
       
	SELECT @last_license_history_id = license_history_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_history_id = license_history_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_history_id AS license_history_id,
				@last_license_history_id AS last_license_history_id;
		END

	IF @last_license_history_id <> @license_history_id BEGIN
			PRINT 'license_history'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lh.license_id 
			FROM dbo.license_history lh
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = lh.license_id
			WHERE license_history_id > @last_license_history_id 
				AND license_history_id <= @license_history_id
				AND lcul.license_id IS NULL;


			SET @row_count = @@ROWCOUNT;	
			IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_history' as step_name, @row_count AS row_count
				END
		END

	-- 1.4) license_capability_history
       
	SELECT @last_license_capability_history_id = license_capability_history_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_capability_history_id = license_capability_history_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id
                     
	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_capability_history_id AS license_capability_history_id,
				@last_license_capability_history_id AS last_license_capability_history_id;
		END

	IF @last_license_capability_history_id <> @license_capability_history_id BEGIN
			PRINT 'license_capability_history'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lch.license_id 
			FROM dbo.license_capability_history lch
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = lch.license_id
			WHERE license_capability_history_id > @last_license_capability_history_id 
				AND license_capability_history_id <= @license_capability_history_id
				AND lcul.license_id IS NULL

			SET @row_count = @@ROWCOUNT;
			IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_capability_history' as step_name, @row_count AS row_count
				END
		END
       
	-- 1.5) license_feature_license
       
	SELECT @last_license_feature_license_id = license_feature_license_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_feature_license_id = license_feature_license_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_feature_license_id AS license_feature_license_id,
				@last_license_feature_license_id AS last_license_feature_license_id;
		END

	IF @last_license_feature_license_id <> @license_feature_license_id BEGIN
			PRINT 'license_feature_license'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lfl.license_id 
			FROM dbo.license_feature_license lfl
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = lfl.license_id
			WHERE license_feature_license_id > @last_license_feature_license_id 
				AND license_feature_license_id <= @license_feature_license_id
				AND lcul.license_id IS NULL

			SET @row_count = @@ROWCOUNT;	
	
		IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_feature_license' as step_name, @row_count AS row_count
				END
		END

	-- 1.6) license_attribute_license
       
	SELECT @last_license_attribute_license_id = license_attribute_license_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_attribute_license_id = license_attribute_license_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_attribute_license_id AS license_attribute_license_id,
				@last_license_attribute_license_id AS last_license_attribute_license_id;
		END

	IF @last_license_attribute_license_id <> @license_attribute_license_id BEGIN
			PRINT 'license_attribute_license'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lal.license_id 
			FROM dbo.license_attribute_license lal
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = lal.license_id
			WHERE license_attribute_license_id > @last_license_attribute_license_id 
				AND lal.license_attribute_license_id <= @license_attribute_license_id	
				AND lcul.license_id IS NULL

			SET @row_count = @@ROWCOUNT;	
			IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_attribute_license' as step_name, @row_count AS row_count
				END
		END

	-- 1.7) license_attribute_license_history
       
	SELECT @last_license_attribute_license_history_id = license_attribute_license_history_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_attribute_license_history_id = license_attribute_license_history_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_attribute_license_history_id AS license_attribute_license_history_id,
				@last_license_attribute_license_history_id AS last_license_attribute_license_history_id;
		END

	IF @last_license_attribute_license_history_id <> @license_attribute_license_history_id BEGIN
				PRINT 'license_attribute_license_history'
				INSERT INTO #license_check_update_license (
					license_id
				)
				SELECT DISTINCT lalh.license_id 
				FROM dbo.license_attribute_license_history lalh
					LEFT JOIN dbo.license_check_update_license lcul
						ON lcul.license_id = lalh.license_id
				WHERE lalh.license_attribute_license_history_id > @last_license_attribute_license_history_id 
					AND lalh.license_attribute_license_history_id <= @license_attribute_license_history_id
					AND lcul.license_id IS NULL


				SET @row_count = @@ROWCOUNT;
				IF @opt_args LIKE '%debug%' BEGIN
						SELECT 'license_attribute_license_history' as step_name, @row_count AS row_count
					END	
		END
                
	-- 1.8) autobilling for usage billing

	SELECT @last_autobilling_effective_object_id = autobilling_effective_object_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @autobilling_effective_object_id = autobilling_effective_object_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@autobilling_effective_object_id AS autobilling_effective_object_id,
				@last_autobilling_effective_object_id AS last_autobilling_effective_object_id;
		END

	IF @autobilling_effective_object_id <> @last_autobilling_effective_object_id BEGIN
			PRINT 'autobilling license_effective_object'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT leo.license_id 
			FROM dbo.license_effective_object leo
			LEFT JOIN dbo.license_check_update_license lcul
				ON lcul.license_id = leo.license_id

			WHERE effective_object_id = 2
				AND is_dup = 0
				AND license_effective_object_id > @last_autobilling_effective_object_id
				A
ND license_effective_object_id <= @autobilling_effective_object_id
				AND license_category_id = 220
				AND lcul.license_id IS NULL

				SET @row_count = @@ROWCOUNT;
				IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'autobilling license_effective_object' as step_name, @row_count AS row_count
				END
		END

	-- 1.9) license_storage
       
	SELECT @last_license_storage_id = license_storage_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_storage_id = license_storage_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_storage_id AS license_storage_id,
				@last_license_storage_id AS last_license_storage_id;
		END

	IF @last_license_storage_id <> @license_storage_id BEGIN
			PRINT 'license_storage'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lcul.license_id 
			FROM dbo.license_storage ls 
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = ls.license_id
			WHERE license_storage_id > @last_license_storage_id 
				AND ls.license_storage_id <= @license_storage_id
				AND lcul.license_id IS NULL

				SET @row_count = @@ROWCOUNT;
				IF @opt_args LIKE '%debug%' BEGIN
					SELECT 'license_storage' as step_name, @row_count AS row_count
				END
		END

	-- 1.10) license_storage_history
       
	SELECT @last_license_storage_history_id = license_storage_history_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @license_storage_history_id = license_storage_history_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@license_storage_history_id AS license_storage_history_id,
				@last_license_storage_history_id AS last_license_storage_history_id;
		END

	IF @last_license_storage_history_id <> @license_storage_history_id BEGIN
			PRINT 'license_storage_history'
			INSERT INTO #license_check_update_license (
				license_id
			)
			SELECT DISTINCT lsh.license_id 
			FROM dbo.license_storage_history lsh
				LEFT JOIN dbo.license_check_update_license lcul
					ON lcul.license_id = lsh.license_id
			WHERE lsh.license_storage_history_id > @last_license_storage_history_id 
				AND lsh.license_storage_history_id <= @license_storage_history_id
				AND lcul.license_id IS NULL;
		END

	-- 1.11) storage_account
       
	SELECT @last_storage_account_id = storage_account_id FROM dbo.license_check_update WHERE license_check_update_id = @last_license_check_update_id
	SELECT @storage_account_id = storage_account_id FROM dbo.license_check_update WHERE license_check_update_id = @license_check_update_id

	IF @opt_args LIKE '%debug%' BEGIN
			SELECT 
				@storage_account_id AS storage_account_id,
				@last_storage_account_id AS last_storage_account_id;
