	SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

	-- 1.22) Move records from temporary table 
	INSERT INTO dbo.license_check_update_license (
		license_id
	)
	SELECT 
		DISTINCT
		license_id
	FROM #license_check_update_license
	WHERE license_id IS NOT NULL;

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 2) insert license_summary
	-- ----------------------------------------------------------------------------------------------------------------------------------------
              
	EXECUTE [dbo].[usp_license_update_license_summary];

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 3) update and licensing maintenance
	-- ----------------------------------------------------------------------------------------------------------------------------------------

	-- 3.3) update license_check_update
	IF ( @@ERROR = 0 ) BEGIN

			-- 3.3.1 update license_check_update
			UPDATE dbo.license_check_update 
			SET license_check_update_status = 1, processed_date = GETDATE()
			WHERE @license_check_update_id <= @license_check_update_id AND license_check_update_status = 0
							
			-- 3.3.4 insert rows into license_message_update_license 
			INSERT INTO dbo.license_message_update_license (
				license_id
			)
			SELECT DISTINCT
				lc.license_id
			FROM dbo.license_check_update_license lc
				INNER JOIN dbo.license l
					ON l.license_id = lc.license_id
				LEFT JOIN dbo.license_distribution_method dm
					ON dm.license_distribution_method_id = l.license_distribution_method_id
				LEFT JOIN dbo.[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f
					ON f.[key] = dm.license_distribution_method_code
			WHERE f.[key] IS NULL

			-- 3.3.5 insert rows into prevx_update_license 
			INSERT INTO dbo.prevx_update_license (
				license_id,
				priority
			)
			SELECT 
				DISTINCT u.license_id,
				ISNULL(lc.[priority], 5) -- set priority to 5 for non-churn events, allowing us to process them before churn events
			FROM dbo.license_check_update_license u
				INNER JOIN dbo.license l
					ON l.license_id = u.license_id
				INN
ER JOIN dbo.license_distribution_method dm
					ON dm.license_distribution_method_id = l.license_distribution_method_id
				LEFT JOIN dbo.sky_api_license s
					ON s.license_id = u.license_id
				LEFT JOIN #license_churn lc
					ON lc.license_id = u.license_id 
			WHERE l.product_line_id IN ( 
						1, 		-- Webroot Secure Anywhere
						6, 		-- Webroot Secure Anywhere International
						50, 	-- Mobile
						51, 	-- Mobile International
						55, 	-- Mobile Business
						100, 	-- Webroot Secure Anywhere
						200, 	-- Webroot Secure Anywhere International
						300 	-- OpenText Business
					) -- AND u.source = 0 
				AND s.license_id IS NULL 
				AND l.license_distribution_method_id NOT IN ( 
						749, 	-- SOTT: SOTI Mobile Trials
						750, 	-- SOTF: SOTI Mobile Full
						919 	-- FRAU: Webroot Fraud
					);
			

				-- 3.3.5.1) sky_update_license
				INSERT INTO dbo.sky_update_license (
					license_id
				)
				SELECT DISTINCT u.license_id
				FROM dbo.license_check_update_license u
					INNER JOIN dbo.license l
						ON l.license_id = u.license_id
					INNER JOIN dbo.license_distribution_method dm
						ON dm.license_distribution_method_id = l.license_distribution_method_id
					INNER JOIN dbo.sky_api_license s
						ON s.license_id = u.license_id
				WHERE l.product_line_id IN ( 
							1, 		-- Webroot Secure Anywhere
							6, 		-- Webroot Secure Anywhere International
							50, 	-- Mobile
							51, 	-- Mobile International
							55, 	-- Mobile Business
							100, 	-- Webroot Secure Anywhere
							200, 	-- Webroot Secure Anywhere International
							300 	-- OpenText Business
						) -- AND u.source = 0 
					AND l.license_distribution_method_id NOT IN ( 
							749, 	-- SOTT: SOTI Mobile Trials
							750, 	-- SOTF: SOTI Mobile Full
							919 	-- FRAU: Webroot Fraud
						)

			-- 3.3.7) @sfdc parent check
			DECLARE @sfdc_license_parent TABLE (parent_license_id INT, child_license_id INT)

			INSERT INTO @sfdc_license_parent(
				parent_license_id, 
				child_license_id
			)
			SELECT DISTINCT 
				p.parent_license_id, 
				p.child_license_id
			FROM dbo.license_check_update_license u
			INNER JOIN dbo.license_key lk
				ON u.license_id = lk.license_id AND lk.salesforce_license_id IS NOT NULL
			INNER JOIN dbo.license_parent p
				ON lk.license_id = p.child_license_id
									
			IF (SELECT COUNT(*) FROM @sfdc_license_parent ) > 0 BEGIN
			
					-- 3.3.8) @sfdc_template_id
					SELECT @sfdc_template_id = sfdc_template_id FROM dbo.sfdc_template  WHERE sfdc_template_name = 'update_license'

					-- 3.3.9) @sfdc_update_type_id
					SELECT @sfdc_update_type_id = sfdc_update_type_id 
					FROM dbo.sfdc_template_update_type 
					WHERE sfdc_template_update_type_id = (
							SELECT MIN(sfdc_template_update_type_id)
							FROM dbo.sfdc_template_update_type
							WHERE sfdc_template_id = @sfdc_template_id
						)

					-- 3.3.10) insert rows into sfdc_opportunity_update
					INSERT INTO dbo.sfdc_opportunity_update(
						license_id, 
						trial_id, 
						sfdc_template_id, 
						sfdc_update_type_id, 
						process_date
					)
					SELECT DISTINCT 
						u.parent_license_id, 
						NULL, 
						@sfdc_template_id, 
						@sfdc_update_type_id, 
						GETDATE()
					FROM @sfdc_license_parent u
						INNER JOIN dbo.license_key lk
							ON u.parent_license_id = lk.license_id
					WHERE lk.salesforce_license_id IS NULL

				END

			-- 3.3.11) @sfdc_template_id
			SELECT @sfdc_template_id = sfdc_template_id FROM dbo.sfdc_template  WHERE sfdc_template_name = 'update_license'

			-- 3.3.12) @sfdc_update_type_id
			SELECT @sfdc_update_type_id = sfdc_update_type_id FROM dbo.sfdc_template_update_type WHERE sfdc_template_update_type_id = (SELECT min(sfdc_template_update_type_id)
			FROM dbo.sfdc_template_update_type
			WHERE sfdc_template_id = @sfdc_template_id)

			-- 3.3.13) insert rows into sfdc_opportunity_update

			INSERT INTO dbo.sfdc_opportunity_update (
				license_id, 
				trial_id, 
				sfdc_template_id, 
				sfdc_update_type_id, 
				process_date
			)
			SELECT DISTINCT 
				u.license_id, 
				NULL, 
				@sfdc_template_id, 
				@sfdc_update_type_id, 
				GETDATE()
			FROM dbo.license_check_update_license u
				INNER JOIN dbo.license_key lk
					ON u.license_id = lk.license_id AND lk.salesforce_license_id IS NOT NULL
				LEFT JOIN dbo.sfdc_opportunity_update s
					ON s.license_id = u.license_id AND s.sfdc_template_id = @sfdc_template_id
			WHERE s.sfdc_opportunity_update_id IS NULL -- u.source = 0 and 
					
						
			-- 3.3.14) delete licenses that have already been processed
			DELETE FROM dbo.license_check_update_license

			-- 3.3.15) license_keycode_alias copy to licensing DB (This section is being added back to support CBEP cancel for CYAN release 1 and will need to be removed for release 2)
			EXECUTE dbo.usp_licensing_update_license_keycode_alias

			-- 3.3.16) sky update for CBEP license cancel
			INSERT INTO dbo.sky_update (
				license_id, 
				sky_template_id, 
				sky_update_type_id
			)
			OUTPUT Inserted.license_id INTO @license_table (
					license_id
			)
			SELECT 
				lm.license_id, 
				sky_template_id = 13, 		-- CBEP_delete
				sky_update_type_id = 13 	-- CBEP_delete
			FROM dbo.license_message lm
			WHERE lm.message_type_id = 19 	-- cancel_cbep
				AND lm.message_status_id = 1 -- pending
				AND CAST(lm.process_date AS DATE) = CAST(GETDATE() AS DATE)

			IF @@ROWCOUNT > 0 BEGIN

					UPDATE lm
					SET lm.message_status_id = 3,
						lm.last_modified_date = GETDATE()
					FROM dbo.license_message lm
					INNER JOIN @license_table lt ON lt.license_id = lm.license_id
					WHERE lm.message_type_id = 19 --cancel_cbep
						AND lm.message_status_id = 1 --pending
						AND CAST(lm.process_date AS DATE) = CAST(GETDATE() AS DATE)
				END

		END

END TRY

BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'license check update license check failed'
                                         ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
       
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_cisco_autorenewal_opt_out]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_cisco_autorenewal_opt_out]
(
    @customer_email varchar(100),
    @first_name varchar(255) = NULL,
    @last_name varchar(255) = NULL,
    @reason_to_cancel varchar(500) = NULL,
    @request_uid varchar(255) = NULL,
    @request_open_category varchar(100) = NULL,
    @request_source varchar(100) = NULL,
    @request_ip varchar(100) = NULL,
    @response_code int output,
    @message varchar(100) output
)

/*    
    DATE        AUTHOR      REMARKS
    2019-08-11  jnavarra    Initial creation

    DESCRIPTION
    
*/

AS
    SET NOCOUNT ON
            
	DECLARE
        @license_id INT = NULL,
        @license_category_id INT = 240  -- Cisco/Brightcloud

    BEGIN TRY
        -- Track all requests (rather than just successfull ones). Might be a data-mining opportunity, or to help identify nefarious activity since we're not validating.
        INSERT INTO dbo.license_autorenewal_no_keycode_opt_out (first_name, last_name, customer_email, reason_to_cancel, request_uid, request_open_category, request_source, request_ip, license_category_id)
        SELECT @first_name, @last_name, @customer_email, @reason_to_cancel, @request_uid, @request_open_category, @request_source, @request_ip, @license_category_id



        SELECT
            @license_id = l.license_id
        FROM dbo.customer_email ce
            INNER JOIN dbo.license l
                ON l.customer_id = ce.customer_id
            INNER JOIN dbo.license_category_license lcl
                ON lcl.license_id = l.license_id
                    AND lcl.license_category_id = @license_category_id
        WHERE ce.customer_email = @customer_email



        IF (@license_id IS NULL)
            BEGIN
                -- Cisco email NOT found
                SELECT @response_code = -1, @message = 'License not found'
            END
        ELSE
            BEGIN
                -- Cisco email found

                EXEC dbo.usp_license_update_disable_autorenewal @license_id=@license_id, @csi_user_id='Website', @comment='Disabled from website'

                SELECT @response_code = 0, @message = 'Success'
            END
    END TRY
    BEGIN CATCH
        SET @response_code = -200
        SET @message = CASE
                WHEN @message IS NULL THEN 'Could not update license auto renewal flag for @license_id=' + ISNULL(CONVERT(VARCHAR(20), @license_id), '')
                ELSE @message
            END

        DECLARE @DBName NVARCHAR(128)
        SET @DBName = DB_NAME()
        EXEC usp_LogError @ErrorDB = @DBName

        RETURN 0
    END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_create_license]
-- =============================================================================




CREATE PROCEDURE usp_license_create_license

(
	@product_id int,
	@license_distribution_method_id int,
	@license_type_id int
)

AS
	set nocount on

	declare @keycode varchar(20),
		@product_line_id int,
		@license_id int,
		@error int,
		@message varchar(100)

	-- 1.) get product_line_id for product input
	set @product_line_id  = (select top 1 product_line_id
				from product_line_product
				where product_id = @product_id)
	
	if @product_line_id is null
		begin
			set @error = -100
			set @message = 'No product line for product_id'
			--print @error
			--print @message
			return
		end
--print @product_line_id

	-- 2.) create new keycode
	exec usp_license_generate_keycode @product_line_id, @license_distribution_method_id, @keycode output

	if @keycode is null
		begin
			set @error = -200
			set @message = 'Failure to generate keycode'
			--print @error
			--print @message
			return
		end

--print @keycode

	-- 3.) generate license
	
	insert into license (keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, max_daily_activations, max_child_licenses, license_expiration_date)
	values (@keycode, null, @product_line_id, 0, @license_type_id, @license_distribution_method_id, 30, null, null)
	
	set @error = @@error
		
	if @error <> 0
		begin
			set @error = -300
			set @message = 'License insert failure'
			--print @error
			--print @message
			return
		end
	
	set @license_id = scope_identity()
	--print @license_id
	
	-- 4.) add capabilities to the license
	
	if @license_id is not null	
		
		begin
	
			insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days)
			select license_id = @license_id,
				capability_id,
				capability_type_id,
				capability_activation_days
			from product_capability
			where product_id = @product_id
		
			set @error = @@error
				
			if @error <> 0
				begin
					set @error = -300
					set @message = 'License capability insert failure'
					--print @error
					--print @message
					
					delete from license_capability where license_id = @license_id
					delete from license where license_id = @license_id
									
					return
				end
		end
	-- 5.) return results
	
	select license_id = @license_id, keycode = @keycode




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_create_license_pool_msn]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_create_license_pool_msn]

/*	
	DATE		 AUTHOR			REMARKS
	2012-10-31	 acoffel		Initial creation. This sp needs to be called by a job once a day 

	DESCRIPTION
	
*/

as
	
	begin try
	set nocount on
	
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) set table variables and verify msn_keycode counts
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @keycode_table table (keycode varchar(40))
	declare @un_used_count int,
			@quantity int,
			@response_code int, 
			@message varchar(100)
	
			select @un_used_count = count(*)
			from msn_keycode 
			where msn_keycode_status_id = 0
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) if there are greater than 1k left exit from process
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
			if @un_used_count > 1000
				begin
					select 'There are at least Keycodes in the MSN Pool'
					return
				end
				
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) if there are 1k or less left, bring the pool back to 5k
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
			if @un_used_count <= 1000

			select @quantity = 5000 - @un_used_count
			
			select @quantity

			insert into @keycode_table
			exec usp_license_insert_license_cart 11100310,104,@quantity,@response_code OUTPUT,@message OUTPUT
			
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert new bacth into msn_keycode
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
			insert into msn_keycode (msn_hash_puid, license_id,insert_date,last_modified_date,msn_keycode_status_id)
			select NULL as msn_hash_puid, l.license_id, getdate(), getdate(),0
			from @keycode_table k
			inner join license l
				on k.keycode = l.keycode
			

end try
begin catch

   
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch


GO
