-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_delete_license_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_delete_license_message]
(
    @license_id INT,
    @message_type_name VARCHAR(50),
    @message_status_name VARCHAR(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2024-11-28	psatish		ECOM-5706/US-3039566 Initial creation
	
	DESCRIPTION
	Delete licenses from the license_message table and corresponding foreign key tables,
	excluding those with a COMPLETED message_status, regardless of message_type and message_status.
	
	DEPENDENCY
		
	This procedure is initiated by the procedure:usp_license_service_update_license for the autorenewal message_type

*/

AS
SET NOCOUNT ON;

BEGIN TRY

    IF @message_status_name = 'completed'
        RETURN


    DECLARE @message_type_id INT,
            @message_status_id INT

    DECLARE @license_message TABLE
    (
        license_message_id INT PRIMARY KEY
    )
    DECLARE @notifications TABLE
    (
        google_notification_id INT,
        apple_notification_id INT,
        account_order_staging_id INT
    )



    SELECT @message_type_id = message_type_id
    FROM dbo.message_type
    WHERE message_type_name = @message_type_name

    SELECT @message_status_id = message_status_id
    FROM dbo.message_status
    WHERE message_status_name = @message_status_name

    --Check if license exists in the license_message table with the requested message type and status
    IF EXISTS
    (
        SELECT 1
        FROM dbo.license_message lm 
        WHERE lm.license_id = @license_id
              AND lm.message_type_id = @message_type_id
              AND lm.message_status_id = @message_status_id
    )
    BEGIN


        INSERT INTO @license_message
        (
            license_message_id
        )
        SELECT lm.license_message_id
        FROM dbo.license_message lm
        WHERE lm.license_id = @license_id
              AND lm.message_type_id = @message_type_id
              AND lm.message_status_id = @message_status_id

        IF EXISTS (SELECT 1 FROM @license_message)
        BEGIN

            INSERT INTO @notifications
            (
                google_notification_id,
                account_order_staging_id
            )
            SELECT gn.google_notification_id,
                   aos.account_order_staging_id
            FROM @license_message lm
                INNER JOIN dbo.google_notifications gn
                    ON gn.license_message_id = lm.license_message_id
                LEFT JOIN dbo.account_order_staging aos
                    ON aos.google_notification_id = gn.google_notification_id

            INSERT INTO @notifications
            (
                apple_notification_id,
                account_order_staging_id
            )
            SELECT an.apple_notification_id,
                   aos.account_order_staging_id
            FROM @license_message lm
                INNER JOIN dbo.apple_notifications an
                    ON an.license_message_id = lm.license_message_id
                LEFT JOIN dbo.account_order_staging aos
                    ON aos.apple_notification_id = an.apple_notification_id



            --insert into license_message_archive
            INSERT INTO dbo.license_message_archive
            (
                license_message_id,
                license_id,
                license_message_key,
                message_type_id,
                message_status_id,
                insert_date,
                process_date,
                end_date,
                archive_date,
                message_campaign_id,
                message_campaign_class_id
            )
            SELECT lm.license_message_id,
                   lm.license_id,
                   lm.license_mes
sage_key,
                   lm.message_type_id,
                   lm.message_status_id,
                   lm.insert_date,
                   lm.process_date,
                   lm.end_date,
                   lm.archive_date,
                   lm.message_campaign_id,
                   lm.message_campaign_class_id
            FROM @license_message ml
                INNER JOIN dbo.license_message AS lm
                    ON lm.license_message_id = ml.license_message_id

            --insert into license_message_value_archive
            INSERT INTO dbo.license_message_value_archive
            (
                license_message_value_id,
                license_message_id,
                message_value_type_id,
                value_id
            )
            SELECT lmv.license_message_value_id,
                   lmv.license_message_id,
                   lmv.message_value_type_id,
                   lmv.value_id
            FROM @license_message AS ml
                INNER JOIN dbo.license_message_value AS lmv
                    ON lmv.license_message_id = ml.license_message_id


            --insert into account_order_history 
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN dbo.account_order ao
                        ON ao.license_message_id = lm.license_message_id
            )
            BEGIN

                INSERT INTO dbo.account_order_history
                (
                    account_order_id,
                    account_order_staging_id,
                    original_account_order_staging_id,
                    trial_id,
                    order_header_id,
                    license_id,
                    license_message_id,
                    is_trial_to_full_conversion,
                    modified_date,
                    insert_date
                )
                SELECT ao.account_order_id,
                       ao.account_order_staging_id,
                       ao.original_account_order_staging_id,
                       ao.trial_id,
                       ao.order_header_id,
                       ao.license_id,
                       ao.license_message_id,
                       ao.is_trial_to_full_conversion,
                       ao.modified_date,
                       ao.insert_date
                FROM @license_message lm
                    INNER JOIN dbo.account_order ao
                        ON ao.license_message_id = lm.license_message_id

                DELETE ao
                FROM @license_message lm
                    INNER JOIN dbo.account_order ao
                        ON ao.license_message_id = lm.license_message_id
            END

            --insert into the trial_registration_keycode_history
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN trial_registration_keycode tk
                        ON tk.license_message_id = lm.license_message_id
            )
            BEGIN
                INSERT INTO dbo.trial_registration_keycode_history
                (
                    trial_registration_id,
                    customer_id,
                    keycode,
                    product_id,
                    location_code,
                    language_code,
                    rc,
                    look_up_count,
                    insert_date,
                    BBY_Employee_Number,
                    license_message_id
                )
                SELECT tk.trial_registration_id,
                       tk.customer_id,
                       tk.keycode,
                       tk.product_id,
                       tk.location_code,
                       tk.language_code,
                       tk.rc,
                       tk.look_up_count,
                       tk.insert_date,

                       tk.BBY_Employee_Number,
                       tk.license_message_id
                FROM @license_message lm
                    INNER JOIN trial_registration_keycode tk
                        ON tk.license_message_id = lm.license_message_id

                DELETE tk
                FROM @license_message lm
                    INNER JOIN trial_registration_keycode tk
                        ON tk.license_message_id = lm.license_message_id


            END


            --license_message_check
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN dbo.license_message_check lmc
                        ON lmc.license_message_id = lm.license_message_id
            )
            BEGIN
                INSERT INTO dbo.license_message_check_archive
                (
                    license_message_id,
                    keycode,
                    license_id,
                    license_message_key,
                    process_date,
                    end_date,
                    message_campaign_id,
                    message_platform_id,
                    massage_platform_name,
                    message_content_id,
                    serial_number,
                    contract_id,
                    cart_discount_id
                )
                SELECT lmc.license_message_id,
                       lmc.keycode,
                       lmc.license_id,
                       lmc.license_message_key,
                       lmc.process_date,
                       lmc.end_date,
                       lmc.message_campaign_id,
                       lmc.message_platform_id,
                       lmc.massage_platform_name,
                       lmc.message_content_id,
                       lmc.serial_number,
                       lmc.contract_id,
                       lmc.cart_discount_id
                FROM @license_message lm
                    INNER JOIN dbo.license_message_check lmc
                        ON lmc.license_message_id = lm.license_message_id

                DELETE lmc
                FROM @license_message lm
                    INNER JOIN dbo.license_message_check lmc
                        ON lmc.license_message_id = lm.license_message_id

            END
            --order_license_usage	
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage ol
                        ON ol.license_message_id = lm.license_message_id
            )
            BEGIN
                INSERT INTO dbo.order_license_usage_archive
                (
                    order_license_usage_id,
                    order_header_id,
                    license_id,
                    usage_seats,
                    unit_price,
                    start_date,
                    end_date,
                    license_message_id,
                    insert_date,
                    modified_date,
                    archive_reason,
                    license_seats,
                    license_attribute_license_value,
                    license_category_id,
                    oracle_update_status_id,
                    currency_id,
                    usage
                )
                SELECT ol.order_license_usage_id,
                       ol.order_header_id,
                       ol.license_id,
                       ol.usage_seats,
                       ol.unit_price,
                       ol.start_date,
                       ol.end_date,
                       ol.license_message_id,
                       ol.insert_date,
                       ol.modified_date,
                       'Deleting the corresponding the license_message_id records',
                       ol.license_seats,
                
       ol.license_attribute_license_value,
                       ol.license_category_id,
                       ol.oracle_update_status_id,
                       ol.currency_id,
                       ol.usage
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage ol
                        ON ol.license_message_id = lm.license_message_id

                --insert into forecast_calc_archive
                IF EXISTS
                (
                    SELECT 1
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id
                        INNER JOIN dbo.forecast_calc fc
                            ON fc.forecast_usage_id = fu.forecast_usage_id
                )
                BEGIN
                    INSERT INTO dbo.forecast_calc_archive
                    (
                        forecast_calc_id,
                        forecast_core_id,
                        forecast_usage_id,
                        license_id,
                        license_category_id,
                        period,
                        growth_rate,
                        forecast_start_date,
                        forecast_end_date,
                        forecast_type,
                        forecast_usage,
                        forescast_usage_delta,
                        forecast_sold_quantity_total,
                        acv_sold,
                        acv_new,
                        acv_cancel_new,
                        acv_renew,
                        acv_cancel_renew,
                        acv_total,
                        insert_date
                    )
                    SELECT fc.forecast_calc_id,
                           fc.forecast_core_id,
                           fc.forecast_usage_id,
                           fc.license_id,
                           fc.license_category_id,
                           fc.period,
                           fc.growth_rate,
                           fc.forecast_start_date,
                           fc.forecast_end_date,
                           fc.forecast_type,
                           fc.forecast_usage,
                           fc.forescast_usage_delta,
                           fc.forecast_sold_quantity_total,
                           fc.acv_sold,
                           fc.acv_new,
                           fc.acv_cancel_new,
                           fc.acv_renew,
                           fc.acv_cancel_renew,
                           fc.acv_total,
                           fc.insert_date
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id
                        INNER JOIN dbo.forecast_calc fc
                            ON fc.forecast_usage_id = fu.forecast_usage_id

                    DELETE fc
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id
                        INNER JOIN dbo.forecast_calc fc
                            ON fc.forecast_usage_id = fu.forecast_usage_id


                END

                --insert into forecast_usage_archive
                IF EXISTS
                (
                  
  SELECT 1
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id
                )
                BEGIN
                    INSERT INTO dbo.forecast_usage_archive
                    (
                        forecast_usage_id,
                        forecast_core_id,
                        license_id,
                        license_category_id,
                        order_license_usage_id,
                        usage_start_date,
                        usage_end_date,
                        price,
                        model,
                        usage,
                        insert_date
                    )
                    SELECT fu.forecast_usage_id,
                           fu.forecast_core_id,
                           fu.license_id,
                           fu.license_category_id,
                           fu.order_license_usage_id,
                           fu.usage_start_date,
                           fu.usage_end_date,
                           fu.price,
                           fu.model,
                           fu.usage,
                           fu.insert_date
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id


                    DELETE fu
                    FROM @license_message lm
                        INNER JOIN dbo.order_license_usage ol
                            ON ol.license_message_id = lm.license_message_id
                        INNER JOIN dbo.forecast_usage fu
                            ON fu.order_license_usage_id = ol.order_license_usage_id

                END

                DELETE ol
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage ol
                        ON ol.license_message_id = lm.license_message_id

            END
            --order_license_usage_accrual 	
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage_accrual ol
                        ON ol.license_message_id = lm.license_message_id
            )
            BEGIN
                INSERT INTO dbo.order_license_usage_accrual_archive
                (
                    order_license_usage_accrual_id,
                    order_header_id,
                    license_id,
                    usage_seats,
                    unit_price,
                    process_date,
                    start_date,
                    end_date,
                    license_message_id,
                    insert_date,
                    modified_date,
                    license_seats,
                    license_attribute_license_value,
                    license_category_id,
                    usage_pricing_model_id
                )
                SELECT ol.order_license_usage_accrual_id,
                       ol.order_header_id,
                       ol.license_id,
                       ol.usage_seats,
                       ol.unit_price,
                       ol.process_date,
                       ol.start_date,
                       ol.end_date,
                       ol.license_message_id,
                       ol.insert_date,
                       ol.modified_date,
                       ol.license_seats,
                       ol.license_attribute_license_value,
                       ol.license_category_id,
 
                      ol.usage_pricing_model_id
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage_accrual ol
                        ON ol.license_message_id = lm.license_message_id

                DELETE ol
                FROM @license_message lm
                    INNER JOIN dbo.order_license_usage_accrual ol
                        ON ol.license_message_id = lm.license_message_id

            END

            --insert into the payment_subscription_credit_card_update
            IF EXISTS
            (
                SELECT 1
                FROM @license_message lm
                    INNER JOIN dbo.payment_subscription_credit_card_update cc
                        ON cc.license_message_id = lm.license_message_id
            )
            BEGIN
                INSERT INTO dbo.payment_subscription_credit_card_update_audit
                (
                    payment_subscription_credit_card_update_id,
                    payment_subscription_credit_card_id,
                    license_message_id,
                    payment_header_id,
                    credit_card_subscription_id,
                    response_code,
                    reason_code,
                    last_modified_date,
                    payment_subscription_credit_card_batch_id,
                    insert_date
                )
                SELECT cc.payment_subscription_credit_card_update_id,
                       cc.payment_subscription_credit_card_id,
                       cc.license_message_id,
                       cc.payment_header_id,
                       cc.credit_card_subscription_id,
                       cc.response_code,
                       cc.reason_code,
                       cc.last_modified_date,
                       cc.payment_subscription_credit_card_batch_id,
                       cc.insert_date
                FROM @license_message lm
                    INNER JOIN dbo.payment_subscription_credit_card_update cc
                        ON cc.license_message_id = lm.license_message_id


                DELETE cc
                FROM @license_message lm
                    INNER JOIN dbo.payment_subscription_credit_card_update cc
                        ON cc.license_message_id = lm.license_message_id

            END

            IF EXISTS (SELECT 1 FROM @notifications)
            BEGIN

                --insert into the google_notifications_history
                INSERT INTO dbo.google_notifications_history
                (
                    google_notification_id,
                    license_message_id,
                    notification_string,
                    transaction_id,
                    purchase_date_utc,
                    expiration_date_utc,
                    cancellation_date_utc,
                    cancel_reason,
                    auto_renewing,
                    insert_date
                )
                SELECT DISTINCT
                       gn.google_notification_id,
                       gn.license_message_id,
                       gn.notification_string,
                       gn.transaction_id,
                       gn.purchase_date_utc,
                       gn.expiration_date_utc,
                       gn.cancellation_date_utc,
                       gn.cancel_reason,
                       gn.auto_renewing,
                       gn.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.google_notifications gn
                        ON gn.google_notification_id = nt.google_notification_id

                --insert into the apple_notifications_by_receipt_history
                INSERT INTO dbo.apple_notifications_by_receipt_history
                (
                    apple_notifications_by_receipt_id,
                    apple_notification_id,
                    transaction_id,
                  
  original_transaction_id,
                    product_id,
                    cancellation_reason,
                    cancellation_date,
                    purchase_date,
                    expires_date,
                    insert_date
                )
                SELECT DISTINCT
                       anr.apple_notifications_by_receipt_id,
                       anr.apple_notification_id,
                       anr.transaction_id,
                       anr.original_transaction_id,
                       anr.product_id,
                       anr.cancellation_reason,
                       anr.cancellation_date,
                       anr.purchase_date,
                       anr.expires_date,
                       anr.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.apple_notifications_by_receipt anr
                        ON anr.apple_notification_id = nt.apple_notification_id

                --insert into the apple_notifications_history
                INSERT INTO dbo.apple_notifications_history
                (
                    apple_notification_id,
                    license_message_id,
                    notification_string,
                    latest_receipt,
                    latest_receipt_info,
                    original_transaction_id,
                    auto_renew_product_id,
                    product_id,
                    auto_renew_status,
                    expiration_intent,
                    insert_date
                )
                SELECT DISTINCT
                       an.apple_notification_id,
                       an.license_message_id,
                       an.notification_string,
                       an.latest_receipt,
                       an.latest_receipt_info,
                       an.original_transaction_id,
                       an.auto_renew_product_id,
                       an.product_id,
                       an.auto_renew_status,
                       an.expiration_intent,
                       an.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.apple_notifications an
                        ON an.apple_notification_id = nt.apple_notification_id

                --insert into the account_order_history 
                INSERT INTO dbo.account_order_history
                (
                    account_order_id,
                    account_order_staging_id,
                    original_account_order_staging_id,
                    trial_id,
                    order_header_id,
                    license_id,
                    license_message_id,
                    is_trial_to_full_conversion,
                    modified_date,
                    insert_date
                )
                SELECT DISTINCT
                       ao.account_order_id,
                       ao.account_order_staging_id,
                       ao.original_account_order_staging_id,
                       ao.trial_id,
                       ao.order_header_id,
                       ao.license_id,
                       ao.license_message_id,
                       ao.is_trial_to_full_conversion,
                       ao.modified_date,
                       ao.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.account_order ao
                        ON ao.account_order_staging_id = nt.account_order_staging_id
                    LEFT JOIN @license_message lm
                        ON lm.license_message_id = ao.license_message_id
                WHERE lm.license_message_id IS NULL

                --insert into the account_order_staging_history
                INSERT INTO dbo.account_order_staging_history
                (
                    account_order_staging_id,
                    skytell_notification_id,
                    apple_notification_id,
              
      google_notification_id,
                    pending_account_id,
                    account_hash_id,
                    account_id,
                    console_id,
                    payment_merchant_id,
                    email,
                    opt_in,
                    merchant_product_id,
                    order_token,
                    order_receipt,
                    vendor_order_date,
                    vendor_expiration_date,
                    modified_date,
                    insert_date
                )
                SELECT DISTINCT
                       aos.account_order_staging_id,
                       aos.skytell_notification_id,
                       aos.apple_notification_id,
                       aos.google_notification_id,
                       aos.pending_account_id,
                       aos.account_hash_id,
                       aos.account_id,
                       aos.console_id,
                       aos.payment_merchant_id,
                       aos.email,
                       aos.opt_in,
                       aos.merchant_product_id,
                       aos.order_token,
                       aos.order_receipt,
                       aos.vendor_order_date,
                       aos.vendor_expiration_date,
                       aos.modified_date,
                       aos.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.account_order_staging aos
                        ON aos.account_order_staging_id = nt.account_order_staging_id

                --insert into the account_order_staging_log_history
                INSERT INTO dbo.account_order_staging_log_history
                (
                    account_order_staging_log_id,
                    account_order_staging_id,
                    account_order_api_reference_id,
                    account_order_api_status,
                    account_order_api_message,
                    insert_date
                )
                SELECT DISTINCT
                       aol.account_order_staging_log_id,
                       aol.account_order_staging_id,
                       aol.account_order_api_reference_id,
                       aol.account_order_api_status,
                       aol.account_order_api_message,
                       aol.insert_date
                FROM @notifications nt
                    INNER JOIN dbo.account_order_staging_log aol
                        ON aol.account_order_staging_id = nt.account_order_staging_id
            END


            --Delete the records from the foreign key tables and the license_message table
            BEGIN TRANSACTION delete_license_message


            IF EXISTS (SELECT 1 FROM @notifications)
            BEGIN

                DELETE aos
                FROM @notifications nt
                    INNER JOIN dbo.account_order_staging_log aos
                        ON aos.account_order_staging_id = nt.account_order_staging_id

                DELETE ao
                FROM @notifications nt
                    INNER JOIN dbo.account_order ao
                        ON ao.account_order_staging_id = nt.account_order_staging_id

                DELETE st
                FROM @notifications nt
                    INNER JOIN dbo.account_order_staging st
                        ON st.account_order_staging_id = nt.account_order_staging_id

                DELETE gn
                FROM @notifications nt
                    INNER JOIN dbo.google_notifications gn
                        ON gn.google_notification_id = nt.google_notification_id

                DELETE anr
                FROM @notifications nt
                    INNER JOIN dbo.apple_notifications_by_receipt anr
                        ON anr.apple_notification_id = nt.apple_notification_id

                DELETE an
                FROM @notifications nt
     
               INNER JOIN dbo.apple_notifications an
                        ON an.apple_notification_id = nt.apple_notification_id
            END


            DELETE lmv
            FROM @license_message AS lm
                INNER JOIN dbo.license_message_value AS lmv
                    ON lmv.license_message_id = lm.license_message_id


            DELETE lms
            FROM @license_message lm
                INNER JOIN dbo.license_message AS lms
                    ON lms.license_message_id = lm.license_message_id

            COMMIT TRANSACTION delete_license_message
        END

    END

END TRY
BEGIN CATCH

    IF @@TRANCOUNT >= 1
    BEGIN
        ROLLBACK TRANSACTION delete_license_message
    END

    DECLARE @dbname NVARCHAR(128);
    SET @dbname = DB_NAME();
    EXEC usp_LogError @ErrorDB = @dbname;
END CATCH;

GO
