-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_effective_object_cancel_transaction]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_effective_object_cancel_transaction]
(
	@order_item_id INT = NULL,
	@order_header_id INT = NULL,
	@license_service_id INT = NULL
)

as

begin try

	set nocount on	

	declare	@min_row int = 1,
			@max_row int,
			@transaction_item int,
			@transaction_type tinyint,
			@modify_date datetime = getdate(),
			@next_effective_record_start_date date,
			@response_code int, 
			@message varchar(100)

	declare @transaction_items table (row_id int identity(1,1), transaction_item int, effective_object_transaction_type_id tinyint)
	declare @effective_transactions table (row_id int identity(1,1), license_effective_object_id int, license_id int, license_category_id int, effective_object_id tinyint, start_date date, end_date date)

	--1.) order_items

	if @order_item_id IS not NULL
		insert into @transaction_items (transaction_item, effective_object_transaction_type_id)
		values (@order_item_id, 1)

	if @order_header_id is not null
		insert into @transaction_items (transaction_item, effective_object_transaction_type_id)
		select order_item_id, 1 from dbo.order_item where order_header_id = @order_header_id

	--2.) license_service

	if @license_service_id is not null
		insert into @transaction_items (transaction_item, effective_object_transaction_type_id)
		values (@license_service_id, 2)

	--3.) update license_effective_object

	if exists (select 1 from @transaction_items)
	begin
		
		select @max_row = max(row_id) from @transaction_items

		while @min_row <= @max_row
		begin

			select @transaction_item = transaction_item, @transaction_type = effective_object_transaction_type_id 
			from @transaction_items 
			where row_id = @min_row
			
			insert into @effective_transactions (license_effective_object_id, license_id, license_category_id, effective_object_id, start_date, end_date)
			select leo.license_effective_object_id, leo.license_id, leo.license_category_id, leo.effective_object_id,  leo.effective_start_date, leo.effective_end_date
			from dbo.license_effective_object leo
			inner join dbo.license_effective_object_transaction leot
				on leot.license_effective_object_transaction_id = leo.license_effective_object_transaction_id
			where leot.effective_object_transaction_type_value = @transaction_item
				and leot.effective_object_transaction_type_id = @transaction_type
				and leo.is_dup = 0

			if @@rowcount > 0
			begin
				update leo
				set is_dup = 1,leo.effective_end_date = leo.effective_start_date ,leo.modified_date = @modify_date
				from dbo.license_effective_object leo
				inner join @effective_transactions et
					on et.license_effective_object_id = leo.license_effective_object_id

				--find if there's a future approved record for that category and object
				select top (1) @next_effective_record_start_date = effective_start_date 
				from dbo.license_effective_object leo
				inner join @effective_transactions et
					on et.license_id = leo.license_id
				where leo.license_category_id = et.license_category_id
					and	leo.effective_object_id = et.effective_object_id
					and leo.effective_start_date > et.end_date
					and leo.is_dup = 0
				order by leo.effective_start_date

				update leo
				set leo.effective_end_date = dateadd(dd, -1, @next_effective_record_start_date), leo.modified_date = @modify_date 
				from dbo.license_effective_object leo
				inner join @effective_transactions et
					on et.license_id = leo.license_id
						and et.effective_object_id = leo.effective_object_id
						and et.license_category_id = leo.license_category_id
				where leo.is_dup = 0 
					and leo.effective_end_date = dateadd(dd,-1,et.start_date)
			end
				
			select @order_item_id = n
ull, @min_row = @min_row + 1
			delete from @effective_transactions
		end
     end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'failed to update license_effective_object'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_generate_keycode_cart]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_generate_keycode_cart]

(
	@product_id int,
	@license_distribution_method_id int,
	@keycode varchar(40) output,
	@response_code int output,
	@message varchar(100) output	
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-08-31	esmart		Initial creation.
	2006-10-03	esmart		Add check for missing product version, use product_version from root_product_id
	2010-08-25	esmart		NULL product version set = '1.0'
	2011-08-22	esmart		Add support for new keycode format (MD5 hash)
	2011-08-31	towens		added support for keycode collision - change from MD5 to SHA1
	2011-12-19	esmart		Add environment lookup to all
	2012-06-13	esmart		Add Android to new keycode format

	DESCRIPTION
	Generates new keycode
*/
	set nocount on

	declare @product_family_prefix varchar(2), 
		@product_family_id int,
		@product_version varchar(2),
		@product_version_char varchar(2),
		@license_distribution_method_code varchar(4),
		@keycode_sequence_id int,
		@keycode_sequece_string varchar(12),
		@base int
	
	set @base = 26
	set @keycode_sequece_string = ''

	-- check @product_id
		select @response_code =  case when count(*) = 0 then -103 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid product_id or non-keycoded product' else '' end
		from product 
		where product_id = @product_id and uses_keycode = 1
			
		if @response_code < 0 	
			begin 
				set @keycode = ' '
				return 
			end	

	-- check @license_distribution_method_id
		select @response_code =  case when count(*) = 0 then -107 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_distribution_method_id' else '' end
		from license_distribution_method 
		where license_distribution_method_id = @license_distribution_method_id
	
		if @response_code < 0 	
			begin 
				set @keycode = null
				return 
			end	


	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get product family prefix	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @product_family_prefix = product_family_prefix,
				@product_family_id = p.product_family_id
		from product_family f
		inner join product p
			on f.product_family_id = p.product_family_id
		where product_id = @product_id

--select product_family_prefix = @product_family_prefix

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get max major and minor version for product_line
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @product_version = replace(max(product_version),'.','')
		from product_versions
		where product_id = @product_id

		if @product_version is null 
			begin
			select @product_version = replace(max(product_version),'.','')
			from product_versions v
			inner join product p	
				on p.root_product_id = v.product_id
			where p.product_id = @product_id
			end

			if @product_version is null 
				begin
				select @product_version = '10'
				end

	
	set @product_version_char = char(ascii('A') + ascii(left(@product_version, 1)) - ascii('0')) + CHAR(ascii('A') + ascii(right(@product_version, 1)) - ascii('0'))
	
--select product_version_char = @product_version_char

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) get license distribution method code
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select @license_distribution_method_code = license_distribution_method_code
		from license_distribution_method
		where license_distribution_method_id = @license_distribution_method_id
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) get keycode sequence id	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		insert into keycode_sequence (insert_date)
		values (getdate())
		
		set @keycode_sequence_id = scope_identity()
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) create sequence portion of keycode
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		while @keycode_sequence_id >= @base 
			begin	
				set @keycode_sequece_string = char(@keycode_sequence_id % @base + ascii('A')) + @keycode_sequece_string
				set @keycode_sequence_id = @keycode_sequence_id / @base
			end
		
		set @keycode_sequece_string = CHAR(@keycode_sequence_id + ASCII('A')) + @keycode_sequece_string;
	
		while len(@keycode_sequece_string) < 9 
			begin
				set @keycode_sequece_string = 'A' + @keycode_sequece_string;
			end
	
--select keycode_sequece_string = @keycode_sequece_string

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.) keycode minus checksum
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	set @keycode =  @product_family_prefix + @product_version_char + @license_distribution_method_code + @keycode_sequece_string
	
--select keycode = @keycode
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.) check sum
	-- ------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		declare @sum int,
			@zn int,
			@ch int,
			@chk_sum varchar(3)
		
		-- this is our checksum building component of the keycode generator.
		set @sum = 0
		set @zn = 1
	
		while @zn < 18 
			begin
				set @ch = ascii(substring(@keycode,@zn,1))
				set @sum = @sum + (( @ch * 128 ) * 5 ) + (( @ch * 1024 ) * 3 ) + ( @ch * 17 )
				set @zn = @zn + 1
			end
		
		set @sum = @sum % ( 26 * 26 * 26 )

		-- base26 the checksum
		set @chk_sum = ''
		while @sum >= @base 
			begin
				set @chk_sum = (char((@sum % @base) + ascii('A'))) + @chk_sum
				set @sum = @sum / @base
			end
	
		set @chk_sum = char(@sum + ascii('A')) + @chk_sum
		-- pad the returned value of checksums with As representing 0s
		while datalength(@chk_sum) < 3 
			begin
				set @chk_sum = 'A' + @chk_sum
			end

		--print @chk_sum

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	-- 7.) generate the keycode
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @product_family_id in (100,200,300,50,51,55)
		begin
			declare @md5_string varchar(40)
			declare @cnt int
			declare @inc int -- this will be the new starting point is the ketcode has a collision
			set @inc = 2

			select @md5_string = upper(convert(varchar(40),sys.fn_sqlvarbasetostr(HashBytes('SHA1',@keycode))))

		--	set @md5_string = REPLACE(REPLACE(@md5_string,'0','O'),'1','I') -- replace so there are no 1's or 0's

			set @md5_string = REPLACE(REPLACE(@md5_string,'0',''),'1','')
		
			if len(@md5_string) < 14
				begin
					select @md5_string = upper(convert(varchar(40),sys.fn_sqlvarbasetostr(HashBytes('SHA1',@keycode))))
					set @md5_string = REPLACE(REPLACE(@md5_string,'0',''),'1','')
				end


			select @keycode = @product_family_prefix+left(right(@md5_string,14),2)+@license_distribution_method_code+right(@md5_string,12)

			select @cnt = count(*) from license where keycode = @keycode -- check for keycode collision

			while @cnt > 0 -- if there is a collision loop until there is not one
				begin

				select @keycode = @product_family_prefix+left(right(@md5_string,14),2)+@license_distribution_method_code+SUBSTRING(@md5_string,@inc,12)

				select @cnt = count(*) from license where keycode = @keycode

				set @inc = @inc + 1


				end -- end the keycode loop sillyness

		end
	else
		begin
			select @keycode = @keycode + @chk_sum 
		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	-- 8.) update for test keycode from QA
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @keycode_modification_string varchar(4)

	select @keycode_modification_string = keycode_modification_string from environment

	if @keycode_modification_string is not null
		begin
			if @product_family_id in (100,200,300,50,51,55)
				begin 
				select @keycode = substring(@keycode,1,16) + @keycode_modification_string
				end
			else
				begin 
				select @keycode = substring(@keycode,1,8) + substring(@key
code,13,8) + @keycode_modification_string
				end
		end


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_activation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_activation]

(
	@keycode varchar(40),
	@GUID varchar(50),
	@machine_name varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.
	2010-02-25	dsmelker	Commented out section 1.5 for licenese seat enforcement. Added activation_success and fraud_type_id
	2012-05-23	esmart		Add support for keycode alias

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @license_id int,
			@license_activations int,
			@license_seats int,
			@license_status_id int,
			@license_type_id int,
			@license_activation_id int,
			@current_machine_name varchar(20),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- 1.1) get info from the license	
		
		select @license_id = license_id, @license_status_id = license_status_id, @license_type_id = license_type_id
		from license
		where keycode = @keycode

		-- 1.1.1) keycode_alias
		if @license_id is null 
			begin
			select @license_id = l.license_id, @license_status_id = l.license_status_id, @license_type_id = l.license_type_id
			from license_keycode_alias a
			inner join license l
				on a.license_id = l.license_id
			where keycode_alias = @keycode
			end 

		if @license_id is null
			begin
			set @response_code = -100
			set @message = 'Keycode not found'
		--	select response_code = @response_code, message = @message
			select activation_success = 0,
			  	   fraud_type_id = 0
			return
			end

		if @license_type_id in (2,3)
			begin
			set @response_code = -110
			set @message = 'OEM and Trial parents cannot be activated'
		--	select response_code = @response_code, message = @message
			select activation_success = 0,
			  	   fraud_type_id = 0
			return
			end

	-- 1.2)get activations count
	
		select @license_activations = count(*)
		from license_activation
		where license_id = @license_id
	
	-- 1.3) validate guid and machine_name

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end

		if @machine_name is null or @machine_name = '' 
			begin
				select @machine_name = 'Computer ' + convert(varchar(3),@license_activations+1)
			end

	-- 1.4) see if activation exists
	
		select @license_activation_id = license_activation_id, @current_machine_name = machine_name
		from license_activation
		where license_id = @license_id and guid = @guid

		-- 1.4.1) update machine name
		if @license_activation_id is not null 
			begin
			if @current_machine_name is null or @current_machine_name <> @machine_name
				begin
				update license_activation
				set machine_name = @machine_name
				where license_activation_id = @license_activation_id
				end
			set @response_code = 0
			set @message = 'License already activated'
			--select response_code = @response_code, message = @message
			exec usp_license_update_activate @license_id--, @response_code output, @message output
			select activation_success = 1,
			  	   fraud_type_id = 0
			return
			end	


	-- 1.5) get seats 
/*	
		select @license_seats = license_seats
		from license_seat 
		where license_id = @license_id

		if @license_activations >= @license_seats
			begin
			set @response_code = -130
			set @message = 'Maximum activations reached'
			select response_code = @response_code, message = @message
			return
			
end
*/
--select license_id = @license_id, license_activations = @license_activations, license_seats = @license_seats, machine_name = @machine_name, guid = @guid

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert activation
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into license_activation (license_id, guid, machine_name)
	values (@license_id, @guid, @machine_name)

	if @@error = 0
		begin
		set @response_code = 0
		set @message = 'License activated'	
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) activate capabilities
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--	if @license_status_id = 0
--		begin
		exec usp_license_update_activate @license_id
--		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) insert message
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	DECLARE @load_type int, @dbsource varchar(100)
			
	select @dbsource = db_name()

	--exec [tasks].[dbo].[usp_Licensing_Send_Tasks] @license_id = @license_id,@dbsource = @dbsource

	--select response_code = @response_code, message = @message

			select activation_success = 1,
			  	   fraud_type_id = 0

	end try
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'license activation failed for keycode, guid, machine_name (' + @keycode + ', ' + @guid + ', ' + @machine_name + ')'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_activation_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_activation_service]

(	

	@keycode varchar(40),
	@guid varchar(50),
	@machine_name varchar(20),
	@insert_by varchar(20)

)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-09-02	esmart		Initial creation.

	DESCRIPTION
	Insert activation record for professional services license. 
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@capability_activation_date datetime,
			@license_change_reason_id int,
			@response_code int,
			@message varchar(100)

	select @license_change_reason_id = 6

	begin try
	
	-- 1) insert activation
	select @license_id = license_id from license where keycode = @keycode

	if @license_id is not null
		begin
			insert into license_activation(license_id, guid, insert_by, machine_name)
			values(@license_id, @guid, @insert_by, @machine_name)
		end	

	-- 2) check to see if license is activated and if not insert activation

		-- 2.1) check activation
		select @capability_activation_date = capability_activation_date 
		from license_capability
		where license_id = @license_id

		-- 2.2) insert capability activation
		if @capability_activation_date is null
			begin

				-- 2.2.1) add existing data to license_history
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
				select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, getdate(), system_user
				from license
				where license_id = @license_id					

				-- 2.2.2) update license
				update license
				set license_status_id = 1,
					modified_date = getdate(),
					modified_by = system_user
				where license_id = @license_id

				-- 2.2.3) update license activations that need activation and expiration date

				set @capability_activation_date = getdate()		

				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
				select  license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by,@license_change_reason_id, getdate(), system_user,
					days_used = 0, 
					days_remaining = 0, 
					days_added = 0, 
					days_new = capability_activation_days, 
					days_contiguous = capability_activation_days
				from license_capability
				where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4

				update license_capability
				set capability_activation_date = 
						case
							when capability_activation_days is null then null
							else @capability_activation_date
						end,
					capability_expiration_date =
						case
							when capability_activation_days is null then null
							else dateadd(dd,capability_activation_days,@capability_activation_date)
						end,
					modified_date = getdate(),
					modified_by = system_user
				where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capab
ility_type_id <> 4
			end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select activations failed failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_bulk_licenses]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_insert_bulk_licenses]
	
(
	@license_bulk_load_description varchar(100),
	@quantity int,
	@product_id int,
	--@product_line_id int,
	@distribution_rc int,
	@license_status_id int,
	@license_type_id int,
	@license_distribution_method_id int,
	@license_keycode_type_id int,
	@max_daily_activations int,
	@max_child_licenses int,
	@license_expiration_date datetime,
	@system_user varchar(50),
	@response_code int output,
	@message varchar(100) output
)

AS

	/*	
		DATE		AUTHOR		REMARKS
		2006-08-31	esmart		Initial creation
		2007-03-13	esmart		Modified section 4 to call a different keycode generator for enterprise licenses
		2007-06-04	esmart		Add license_seats for enterprise and multi-seat products
		2008-07-15	esmart		Add license_storage for WISE	

		DESCRIPTION
		Create licenses in bulk and returns license_bulk_load_id	
	*/

	set nocount on

	declare 	@license_bulk_load_id int,
		@product_line_id int,
		@keycode_count int,
		@insert_date datetime,
		@keycode_sequence_id bigint,
		@keycode varchar(40),
		@error int,
		@seats int,
		@storage_gb int

	set @keycode_count = 0
	set @insert_date = getdate()
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- @license_bulk_load_description
		if @license_bulk_load_description is null or @license_bulk_load_description = '' 
			begin
				set @response_code = -101
				set @message = 'No bulk load description'
				return
			end
	-- @quanity	
		if @quantity <= 0
			begin
				set @response_code = -102
				set @message = 'Invalid quantity'
				return
			end
	-- @product_id
		select @response_code =  case when count(*) = 0 then -103 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid product_id' else '' end
		from product 
		where product_id = @product_id

		if @response_code < 0 	begin return end	


	-- @product_line_id

	set @product_line_id = (select top 1 product_line_id from product_line_product where product_id = @product_id)

		if @product_line_id is null 
			begin
				set @response_code =   -104
				set @message = 'Invalid product_line_id'
				return
			end

	-- @license_status_id
		select @response_code =  case when count(*) = 0 then -105 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_status_id' else '' end
		from license_status 
		where license_status_id = @license_status_id
		
		if @response_code < 0 	begin return end

	-- @license_type_id
		select @response_code =  case when count(*) = 0 then -106 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_type_id' else '' end
		from license_type 
		where license_type_id = @license_type_id
	
		if @response_code < 0 	begin return end

	-- @license_distribution_method_id
		select @response_code =  case when count(*) = 0 then -107 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_distribution_method_id' else '' end
		from license_distribution_method 
		where license_distribution_method_id = @license_distribution_method_id
	
		if @response_code < 0 	begin return end

	-- @license_keycode_type_id
		
		
		select @response_code =  case when count(*) = 0 then -108 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_keycode_type_id' else '' end
		from license_keycode_type 
		where license_keycode_type_id = @license_keycode_type_id
	
		if @response_code < 0 	begin return end

	--  @d
istribution_rc
		if @distribution_rc <> 0 and @distribution_rc <> null and @distribution_rc <> ''
			begin
				select @response_code =  case when count(*) = 0 then -109 else 0	 end,
					@message = case when count(*) = 0 then 'Invalid distribution_rc' else '' end
				from affiliates 
				where assigned_num = @distribution_rc
			end

		if @response_code < 0 	begin return end

	-- @seats 

		select @seats = isnull(seats,0)
		from product_seat
		where product_id = @product_id

	-- @storage_gb 

		select @storage_gb = storage_gb
		from product_storage
		where product_id = @product_id
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Set deaults
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
	-- @distribution_rc
		if @distribution_rc = 0
			begin
				set @distribution_rc = null
			end

	-- @max_daily_activations
		if @max_daily_activations = 0 or @max_daily_activations is null
			begin
				set @max_daily_activations = 30
			end
	
	-- @max_child_licenses
		if @max_child_licenses = 0
			begin
				set @max_child_licenses = null
			end

	-- @max_daily_activations
		if @license_expiration_date = ''
			begin
				set @license_expiration_date = null
			end

	-- @system_user
		if @system_user is null or @system_user = ''
			begin
				set @system_user = system_user
			end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) Insert bulk load header
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		insert into license_bulk_load (license_bulk_load_description, quantity, product_id, product_line_id, distribution_rc, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by)
		values (@license_bulk_load_description,@quantity,@product_id,@product_line_id, @distribution_rc, @license_status_id, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, @max_daily_activations, @max_child_licenses, @license_expiration_date, @insert_date,@system_user, @insert_date,@system_user)

		set @error = @@error
			
		set @license_bulk_load_id = scope_identity()

		if @error > 0
			begin
				set @response_code = -300
				set @message = 'General database error - insert license_bulk_load'
				goto backout
			end		
	
		

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4) Insert preliminary license_bulk_load_license records
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	while @keycode_count < @quantity
		begin

			set @keycode_count = @keycode_count + 1

			if @license_keycode_type_id = 1
				begin
					exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					if @response_code < 0
						begin
						set @response_code = -401
						set @message = 'General database error - generate keycode'
						goto backout
						return
						end
					--select ke
ycode = @keycode
				end
			else if @license_keycode_type_id = 2
				begin 
					exec usp_license_generate_enterprise_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					if @response_code < 0
						begin
						set @response_code = -402
						set @message = 'General database error -  generate keycode'
						goto backout
						return
						end
				end
			
			-- exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
			
			--select @keycode

			insert into license_bulk_load_license (license_bulk_load_id, keycode, product_id, insert_date)
			values (@license_bulk_load_id, @keycode, @product_id, @insert_date)
			
			set @error = @@error
				
			if @error > 0
				begin
					set @response_code = -403
					set @message = 'General database error - insert license_bulk_load_license'
					goto backout
				end	

		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5) Insert license records and update license_bulk_load_license with new license_id's 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		insert into license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by)
		select 	l.keycode,
			b.product_line_id,
			b.license_status_id,
			b.license_type_id,
			b.license_distribution_method_id,
			b.max_daily_activations,
			b.max_child_licenses, 
			b.license_expiration_date,
			b.insert_date,
			b.insert_by,
			b.modified_date,
			b.modified_by
		from license_bulk_load_license l
		inner join license_bulk_load b
			on l.license_bulk_load_id = b.license_bulk_load_id
		where l.license_bulk_load_id = @license_bulk_load_id
	
		set @error = @@error
			
		if @error > 0
				begin
					set @response_code = -500
					set @message = 'General database error - insert license'
					goto backout
				end	
		
		update license_bulk_load_license
		set license_id = l.license_id
		from license_bulk_load_license b
		inner join license l
			on b.keycode = l.keycode
		where license_bulk_load_id = @license_bulk_load_id

		set @error = @@error
			
		if @error > 0
				begin
					set @response_code = -510
					set @message = 'General database error - update license_bulk_load_license'
					goto backout
				end	

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6) Insert license_capability records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
	select license_id, 
		capability_id, 
		capability_type_id, 
		capability_activation_days,
		insert_date = @insert_date,
		insert_by = @system_user,
		modified_date = @insert_date,
		modified_by = @system_user		
	from license_bulk_load_license b
	inner join product_capability c
		on b.product_id = c.product_id
	where license_bulk_load_id = @license_bulk_load_id
	order by b.license_id, c.capability_id
	
	
		set @error = @@error
			
		if @error > 0
				begin
					set @response_code = -600
					set @message = 'General database error - update license_capabil
ity'
					goto backout
				end	

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7) Insert license_seat records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @product_line_id in (11,13) 
		begin
			insert into license_seat (license_id, license_seats)
			select license_id, @max_child_licenses
			from license_bulk_load_license b
			where license_bulk_load_id = @license_bulk_load_id
		end

	if @product_line_id not in (11,13) and @seats > 0
		begin
			insert into license_seat (license_id, license_seats)
			select license_id, @seats
			from license_bulk_load_license b
			where license_bulk_load_id = @license_bulk_load_id
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8) Insert license_storage records 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @storage_gb is not null
		begin
			insert into license_storage (license_id, storage_gb)
			select license_id, @storage_gb
			from license_bulk_load_license b
			where license_bulk_load_id = @license_bulk_load_id
		end


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9) insert prevx queue
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @product_line_id in (100,200)
		begin
		insert into prevx_update(license_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
		select b.license_id, prevx_update_type_id = 100, prevx_update_status_id = 0, insert_date = @insert_date, modified_date = @insert_date, process_date = @insert_date
		from license_bulk_load_license b
		left join prevx_update u
			on b.license_id = u.license_id
		where b.license_bulk_load_id = @license_bulk_load_id and u.prevx_update_id is null
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9) backout
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	backout: 
		if @response_code < 0
			begin
				-- delete license_capability records
				delete from license_capability
				where license_id in (select license_id from license_bulk_load_license where license_bulk_load_id = @license_bulk_load_id)
				
				-- delete license_seat records
				delete from license_seat
				where license_id in (select license_id from license_bulk_load_license where license_bulk_load_id = @license_bulk_load_id)
				
				-- delete license_storage records
				delete from license_storage
				where license_id in (select license_id from license_bulk_load_license where license_bulk_load_id = @license_bulk_load_id)
				
				-- set license_id to null to allow for delete of license records
				update license_bulk_load_license
				set license_id = null
				where license_bulk_load_id = @license_bul
k_load_id
				
				-- delete license records
				delete from license
				where keycode in (select keycode from license_bulk_load_license where license_bulk_load_id = @license_bulk_load_id)
				
				-- delete license_bulk_load_license
				delete from license_bulk_load_license where license_bulk_load_id = @license_bulk_load_id

				-- delete license_bulk_load_license
				delete from license_bulk_load where license_bulk_load_id = @license_bulk_load_id
				--print ('backout')

				return
			end	

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9) select output
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select license_bulk_load_id = @license_bulk_load_id


set ANSI_NULLS ON
set QUOTED_IDENTIFIER ON

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_bulk_load]
-- =============================================================================

CREATE procedure [dbo].[usp_license_insert_bulk_load]
	
(
	@license_bulk_load_description varchar(100),
	@quantity int,
	@product_id int,
	@license_type_id int,
	@license_distribution_method_id int,
	@max_child_licenses int,
	@license_expiration_date datetime,
	@system_user varchar(50),
	@license_bulk_load_group_id int = 1,
	@response_code int output,
	@message varchar(100) output
)

AS

	/*	
		DATE			AUTHOR		REMARKS
		2008-01-21		mscardino	Initial creation
		2010-08-31		dsmelker	Added bulk_load_group_id
		2011-11-09		esmart		Update enterprise/SME license type
		2012-06-25		esmart		Update to make mobile enterprise with correct license_type
		2012-08-27		esmart		Allow enterprise OEM keycodes

		DESCRIPTION
		Create licenses in bulk and returns license_bulk_load_id	

	*/

set nocount on

begin try

--	begin transaction

	declare 	
		@license_bulk_load_id int,
		@product_line_id int,
		@keycode_count int,
		@insert_date datetime,
		@keycode_sequence_id bigint,
		@keycode varchar(40),
		@error int,
		@seats int,
		@license_keycode_type_id int,
		@max_daily_activations int,
		@distribution_rc int,
		@license_status_id int,
		@license_bulk_status_id int, 
		@sql_string varchar(4000),
		@command varchar(1000),
		@task_number varchar(20),	
		@db_name varchar(100)

	set @keycode_count = 0
	set @insert_date = getdate()
	set @db_name = db_name()

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- @license_bulk_load_description
	if @license_bulk_load_description is null or @license_bulk_load_description = '' 
	begin
		RAISERROR ('No bulk load description', -- Message text.
               16, -- Severity.
               1 -- State.
               );
	end

	-- @quanity	
	if @quantity <= 0 or @quantity > 50000
	begin
		RAISERROR ('Invalid license quantity. Must be <= 50000.', -- Message text.
               16, -- Severity.
               1 -- State.
               );
	end

	-- @product_id
	select @response_code =  case when count(*) = 0 then -103 else 0	 end,
		@message = case when count(*) = 0 then 'Invalid product_id' else '' end
	from product 
	where product_id = @product_id

	-- @product_line_id
	set @product_line_id = (select top 1 product_line_id from product_line_product where product_id = @product_id)
	if @product_line_id is null 

	-- @license_type_id
	select @response_code =  case when count(*) = 0 then -106 else 0	 end,
		@message = case when count(*) = 0 then 'Invalid license_type_id' else '' end
	from license_type 
	where license_type_id = @license_type_id

	

	-- @license_distribution_method_id
	select @response_code =  case when count(*) = 0 then -107 else 0	 end,
		@message = case when count(*) = 0 then 'Invalid license_distribution_method_id' else '' end
	from license_distribution_method 
	where license_distribution_method_id = @license_distribution_method_id
	if @response_code < 0 	
	begin 
		RAISERROR ('Invalid license_distribution_method_id', -- Message text.
               16, -- Severity.
               1 -- State.
               );
	end

	-- @seats 
	select @seats = isnull(seats,0)
	from product_seat
	where product_id = @product_id
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Set deaults
	-----------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
	-- @distribution_rc
	set @distribution_rc = null

	-- @license_keycode_type_id
	select @license_keycode_type_id = license_keycode_type_id
	from license_keycode_type 
	where license_keycode_type_description = 'Consumer Char(20)'

	-- @license_status_id
	select @license_status_id = license_status_id from license_status where license_status_description = 'Active'

	-- @max_daily_activations
	if @max_daily_activations = 0 or @max_daily_activations is null
	begin
		set @max_daily_activations = 30
	end
	
	-- @max_child_licenses
	if @max_child_licenses = 0 
	begin
		set @max_child_licenses = null
	end

	-- @license_expiration_date
	if @license_expiration_date = ''
	begin
		set @license_expiration_date = null
	end

	-- @system_user
	if @system_user is null or @system_user = ''
	begin
		set @system_user = system_user
	end

	-- @license_type_id
	if @product_line_id in (300,55) and @license_type_id = 1
		begin
		select @license_type_id = 4
		end

	select @license_bulk_status_id = (select license_bulk_status_id from license_bulk_status where license_bulk_status_description = 'load initiated')

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) Insert bulk load header
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into license_bulk_load (license_bulk_load_description, quantity, product_id, product_line_id, distribution_rc, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, license_bulk_status_id, insert_date, insert_by, modified_date, modified_by,license_bulk_load_group_id)
	values (@license_bulk_load_description,@quantity,@product_id,@product_line_id, @distribution_rc, @license_status_id, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, @max_daily_activations, @max_child_licenses, @license_expiration_date, @license_bulk_status_id, @insert_date,@system_user, @insert_date,@system_user,@license_bulk_load_group_id)

	set @license_bulk_load_id = scope_identity()

	select @task_number = (select isnull(max(task_number),0) from tasks..task_table) + 10
	select @command = 'exec usp_insert_bulk_licenses ' + convert(varchar(10),@license_bulk_load_id) + ', ' + '' + @system_user + '' + ''''

	--print @command

	select @sql_string = 
		'insert into tasks..task_table (task_number, Command, NoTransaction) ' + 
		' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_insert_bulk_licenses ' + convert(varchar(10),@license_bulk_load_id) + ', ' + '''' + '''' + @system_user + '''' + '''' + '''' + ',0) '

	--print @sql_string

	execute(@sql_string)	

	execute tasks..QueueTasksProc
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9) select output
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select license_bulk_load_id = @license_bulk_load_id

--	commit transaction

end try 
begin catch
	
	if @@trancount > 0 
		rollback transaction
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	update
		license_bulk_load
	set
		license_bulk_status_id
 = 0
	where
		license_bulk_load_id = @license_bulk_load_id
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_child_license]
-- =============================================================================

CREATE procedure [dbo].[usp_license_insert_child_license]

(
	@keycode varchar(40),
	@guid varchar(50),
	@machine_name varchar(20) = null,
	@external_keycode varchar(40) = null,
	@license_seats_specified int = null,
	@trial tinyint = null,
	@first_name nvarchar(225) = null,
	@last_name nvarchar(225) = null,
	@customer_email varchar(100) = null,
	@company_name nvarchar(255) = null,
	@nfr_flag BIT = NULL,
	@license_service_id INT = NULL
)

/*	
	DATE			AUTHOR			REMARKS
	2006-06-26		esmart			Initial creation
	2006-08-11		esmart			1.) Add modification to add license_distribution_method_id to the child license. NOTE: This will change when
									we add a child_distribution_method_id to the license table. For now we will use the license_distibution_id from 
									the parent license.
									2.) Replace old sproc usp_license_keycode_generator with new sproc usp_license_generate_keycode
									3.) Add support for the two columns max_child_licenses, license_expiration_date
									4.) Add backout routine in case of insert errors
	2006-09-04		esmart			Add support for new column license_keycode_type_id. Modified @keycode to varchar(40) from char(20)
	2007-03-16		esmart			Add support for enterprise child licenses
	2008-07-16		esmart			Add support for license_storage
	2009-05-01		esmart			Add order_item_id to usp_license_insert_license_storage sub procedure
	2010-06-11		dsmelker		Added machine_name to the parameters and the insert into license_activation
	2011-03-04		esmart			Fix duplicate child issue. Fix issues with license_capability data. 
	2011-09-19		towens			Make a big mess for android
	2011-09-22		esmart			Add insert into prevx_update
	2011-10-31		esmart			Fixed expiration date OEM
	2011-12-05		towens			undo swap mess
	2012-02-21		acoffel			Derby Trial OEM
	2012-03-29		esmart			Add exception for duplicate GUID and parent for Derby trials
	2012-05-31		esmart			Add license_module_license support
	2012-08-09		acoffel			Added SAEP child creation support
	2012-08-16		acoffel			Added Extra seat management
	2012-09-07		esmart			Added WSRM to seat management
	2012-10-08		acoffel			Added Support for Australia Bank
	2012-10-29		esmart			Modify enterprise child license support
	2014-02-10		esmart			Extend for trial child keycodes
	2015-11-13		acoffel			NFR Support
	2016-04-18		acoffel			Inline license_summary insert
	2016-04-20		acoffel			Sky update
	2016-11-15		esmart			Add support for parent module class
	2017-08-04		surpal			Proc usp_license_generate_enterprise_keycode_cart is missing, hence commented out the section
	2018-05-10		cnovac			Added code to call usp_license_insert_effective_object
	2018-08-07		cnovac			Changed code to exclude mobile sdk from writing to effective object
	2018-09-07		rvinoche		Allow past record updates when calling usp_license_insert_effective_object
	2019-04-03		cnovac			Added code to start writing to license contract object
	2019-08-07		esmart			Add insert into sky_api_license for business and remove explicit insert into prevx_update
	2019-09-06		cnovac			Updated code to remove @allow_past_record_update variable and always allow that code to fire and Added check to see if @license_contract_json is not null
	2019-11-07		abelenkiy		Added support for license_parent effective_object (sections 1.0.2, 1.3, 1.4, 2.3)
	2020-05-22		esmart			Add @trial_days
	2020-10-21		esmart			Update business trial days to 30
	2024-02-15		cibach			Add edge case for trials to be 30 days if null parent capability exp. date
	2024-10-07		vsingh8			ECOM-5533: 1. Added PLRP child creation support. 
									2. Also, used app_config to store the primary license categories for which child creation support is required.
									3. Added schema to the objects
.
	2025-11-05      psatish			D-5061224 Insert ecom-created keycodes into prevx queue rather than sky_api_license
	2026-04-14      thejashwini		5096725- insert new consumer licenses into license_active_seats as a part of seat count enforcement 
	DESCRIPTION
	create child license from parent OEM or Trial licenses

	DEPENDENCIES
	Used by [dbo].[usp_license_service_update_service]
	and [dbo].[usp_partner_service_process_child_license]	

*/


AS
set nocount on

		declare	@license_id int,
				@new_license_id int,
				@new_keycode varchar(40), 
				@customer_code varchar(16), 
				@product_line_id int, 
				@product_id int,
				@license_distribution_method_id int,
				@license_distribution_method_code varchar(4),
				@license_keycode_type_id int,
				@license_status_id int, 
				@license_type_id int,
				@max_daily_activations int, 
				@max_child_licenses int, 
				@license_expiration_date datetime,
				@activation_days int,
				@capability_activation_date datetime,
				@current_child_licenses int,
				@error int,
				@response_code int,
				@message varchar(100),
				@license_seats int,
				@storage_gb int,
				@license_feature_check int,
				@license_category_id tinyint,
				@insert_date datetime,
				@insert_by varchar(20),
				@lic int,
				@cnt int,
				@fixed_expiration_OEM int,
				@parent_capability_expiration_date datetime,
				@external_check_id int,
				@cart_discount_id int,
				@parent_license_category_id int,
				@existing_nfr varchar(40),
				@process_date datetime,
				@license_effective_object_json varchar(max),
				@license_contract_json varchar(max),
				@license_parent_json nvarchar(max),
				@trial_days INT,
				@ecom_create_license TINYINT,
				@parent_capability_activation_date DATETIME

		declare @PRIMARY_LICENSE_CATEGORIES TABLE(
			license_category_id tinyint,
			[status] tinyint
		);
        insert into @PRIMARY_LICENSE_CATEGORIES
		select lc.license_category_id, lc.[status]
		from [dbo].[fn_app_config_select_key_values]('PRIMARY_LICENSE_CATEGORIES', 'LICENSE_SERVICE') f
		join [dbo].[license_category] lc on f.[key] = lc.license_category_name;

		select	@error = 0,
				@insert_date = getdate(),
				@insert_by = suser_sname(),
				@process_date = dateadd(minute,5,getdate())


		begin try

		------------------------------------------------------------------------------------------------------------------------------------
		-- 1.0) select
		------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.0) check to see if external keycode already exists in ecom
			if @external_keycode is not NULL
				begin
					select @external_check_id = license_id from dbo.license where keycode = @external_keycode
				end
			if @external_check_id is not NULL
				begin
					select keycode = @external_keycode, 'already exists in ecom' as response_code
				return
			end

		-- 1.0.1) get values from parent license
	
			select 	@license_id = l.license_id,
					@product_line_id = l.product_line_id, 
					@license_status_id = l.license_status_id, 
					@license_distribution_method_id = license_distribution_method_id,
					@license_type_id = l.license_type_id, 
					@license_keycode_type_id = license_keycode_type_id,
					@max_daily_activations = l.max_daily_activations, 
					@max_child_licenses = l.max_child_licenses, 
					@license_expiration_date = license_expiration_date
			from dbo.license l
			where l.keycode = @keycode
		
			select @capability_activation_date = getdate()

		-- 1.0.2) verify parent doesn't already have an NFR key
			if @nfr_flag is not NULL
				begin 
					select @existing_nfr = l.keycode 
					from dbo.license l 
					inner join dbo.license_parent p
						on l.license_id = p.child_license_id
					where p.parent_license_id = @license_id and l.license_distribution_method_id = 973

					--new read code below:
					--s
elect @existing_nfr = l.keycode 
					--from fn_select_license_parent(default, default, @license_id, getdate()) p
					--	inner join license l on l.license_id = p.parent_license_id
					--		and l.license_distribution_method_id = 973
						
						if @existing_nfr is not NULL
							begin 
								select 'NFR child already exists for this Parent' as response, @existing_nfr as child_nfr_keycode
								return
							end
				 end

		-- 1.0.3) insert license_category			
			select @license_category_id = license_category_id 
			from dbo.license_category_license 
			where license_id = @license_id

		-- 1.1) get root_product_id to be used in keycode generation
			select @product_id = root_product_id 
			from dbo.product_line
			where product_line_id = @product_line_id


		-- 1.2) check license_feature for fixed expiration date OEM
			select @fixed_expiration_OEM = case when count(*) > 0 then 1 else 0 end from dbo.license_feature_license where license_id = @license_id and license_feature_id = 8 
			
			if @nfr_flag is not NULL
				begin	
				select @fixed_expiration_OEM = 1
				end

			
		-- 1.2.0.1) check license_feature for cart_discount
			select @cart_discount_id = cart_discount_id 							
			from dbo.license_cart_discount 
			where license_id = @license_id 

			-- 1.2.1) get parent expiration_date
			if @fixed_expiration_OEM = 1
				begin
					select @parent_capability_expiration_date = c.capability_expiration_date
					from dbo.license_category_license cl
					inner join dbo.license_category lc
						on cl.license_category_id = lc.license_category_id
					inner join dbo.license_capability c
						on c.license_id = cl.license_id and c.capability_id = lc.base_capability_id
					where cl.license_id = @license_id

				-- 1.2.2) @parent_capability_expiration_date
					if @parent_capability_expiration_date is null
						begin
							exec dbo.usp_license_update_activate @license_id

							select @parent_capability_expiration_date = c.capability_expiration_date
							from dbo.license_category_license cl
							inner join dbo.license_category lc
								on cl.license_category_id = lc.license_category_id
							inner join dbo.license_capability c
								on c.license_id = cl.license_id and c.capability_id = lc.base_capability_id
							where cl.license_id = @license_id
						end

				end
				
			-- 1.2.3) @parent_capability_expiration_date
			--if @parent_capability_expiration_date < getdate()
			--	begin
			--		select 	new_keycode =  null, failure_type_id = -122
			--		return
			--	end

			-- 1.2.4) @parent_license_category_id
			select @parent_license_category_id = license_category_id from dbo.license_category_license where license_id = @license_id

		-- 1.3) check to see if the guid has been used to create a child license and return original
		if @external_keycode is null or @external_keycode = ''
			begin
			--print '1.3.1'
				select @new_license_id = (select license_id = max(p.child_license_id)
											from dbo.license_parent p with (nolock)
											inner join dbo.license_activation a with (nolock)
												on p.child_license_id = a.license_id
											inner join dbo.license l with (nolock)
												on p.child_license_id = l.license_id
											where p.parent_license_id = @license_id and guid = @guid)

				--new read code below:
				--select @new_license_id = (select license_id = max(p.child_license_id)
				--							from fn_select_license_parent(default, default, @license_id, getdate()) p
				--							inner join license_activation a with (nolock)
				--								on p.child_license_id = a.license_id
				--									and a.guid = @guid
				--							inner join license l with (nolock)
				--								on p.child_license_id = l.license_id)

			end
				
		if @new_license_id is not null
			begin
			select new_keycode = keycode, failure_type_id = 0 from dbo.license where license_id = @new_license_id
			return
			end
		
		-- 1.4) g
et count of current child licenses and complete max child and expiration test
		if @max_child_licenses >= 10000
			begin
			select @current_child_licenses = 1
			end
		else
			begin
				select @current_child_licenses = count(*) 
				from dbo.license_parent
				where parent_license_id = @license_id

				--new read code below:
				--select @current_child_licenses = count(*) 
				--from fn_select_license_parent(default, default, @license_id, getdate()) p

			end

		-- 1.5) @trial_days
		if @product_line_id in (300)
			begin
			select @trial_days = 30
			end
		else
			begin
			select @trial_days = 30
			end

		-- 1.6) check to see if this is an enterprise/SME parent. If child license exists, then look it up and return the keycode. Only one child license allowed for enterprise
		--if @current_child_licenses > 0 and @license_type_id in (4,5)
		--	begin
		--		select @new_keycode = keycode 
		--		from license l
		--		inner join license_parent p
		--			on l.license_id = p.child_license_id
		--		where parent_license_id = @license_id

		--		select new_keycode = @new_keycode,	
		--				failure_type_id = 0
		
		--		return
		--	end

		------------------------------------------------------------------------------------------------------------------------------------
		-- 2.0) Insert child
		------------------------------------------------------------------------------------------------------------------------------------
	
		if @license_id is not null and @license_type_id <> 1 and @license_status_id not in (2,3)
			
			begin
			
			-- 2.1 ) generate new keycode
				
				-- 2.2.0) NFR disti set
				if @nfr_flag is not NULL
					begin
						select @license_distribution_method_id = 973,
								@license_seats = 25
					end
				
				--select @license_distribution_method_id, @trial return

				-- 2.2.1) create keycode
				IF @license_keycode_type_id IN ( 1, 3 )
					   AND ISNULL(@external_keycode, '') = ''
					BEGIN
						--print '2.2.1'
						EXEC usp_license_generate_keycode_cart @product_id,
															   @license_distribution_method_id,
															   @new_keycode OUTPUT,
															   @response_code OUTPUT,
															   @message OUTPUT
						SET @ecom_create_license = 1
						IF @response_code < 0
						BEGIN
							GOTO backout
							RETURN
						END
					--select keycode = @keycode
					END
					--- Commented due to usp_license_generate_enterprise_keycode_cart was missing
					/*
				else if @license_keycode_type_id = 2
					begin 
						--print '2.2.2'
						exec usp_license_generate_enterprise_keycode_cart @product_id, @license_distribution_method_id, @new_keycode output, @response_code output, @message output
						if @response_code < 0
							begin
							goto backout
							return
							end
					end
					*/

				-- 2.2 ) insert license record

					-- 2.2.1) set license_type_id
					if @license_type_id in (2,3) -- for OEM and Trials set @license_type_id = 1 for the child license
						begin
							set @license_type_id = 1
						end
			
					if @license_type_id in (4,5) -- for Enterprise set @license_type_id = 1 for the Enterprise Mobile license
						begin
							set @license_type_id = 6 
						end

					-- 2.2.2) @external_keycode 
					if @external_keycode is not NULL
						begin
						select @new_keycode = @external_keycode
						END
                       
				
					select @license_distribution_method_code = license_distribution_method_code
					from dbo.license_distribution_method 
					where license_distribution_method_id = @license_distribution_method_id

					if exists (select 1 from @PRIMARY_LICENSE_CATEGORIES where license_category_id = @parent_license_category_id and [status] = 1)
					begin
						select @license_type_id = 4
					end


					--- test

					insert into dbo.license_gdstest(keycode,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_
keycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by)
					values (@new_keycode, @product_line_id, 1, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, 30, null, null, @insert_date, @insert_by, @insert_date, @insert_by)

				
				-- 2.2.3) insert license
					insert into dbo.license(keycode,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id,max_daily_activations,max_child_licenses,license_expiration_date,insert_date,insert_by,modified_date,modified_by)
					values (@new_keycode, @product_line_id, 1, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, 30, null, null, @insert_date, @insert_by, @insert_date, @insert_by)

					set @error = @@error
					set @new_license_id = @@identity

					if @error <> 0 
						begin
							set @error = -220
							goto backout	
						end 
		
				-- 2.2.4) insert license
					if @cart_discount_id is not NULL and @new_keycode is not NULL 
					insert dbo.license_cart_discount (license_id, cart_discount_id, [start_date], end_date, last_modified_date)
					select @new_license_id, @cart_discount_id, getdate(), getdate()+1095, getdate()
		
				-- 2.3 insert license_parent record
					select @license_parent_json = (select @new_license_id as child_license_id, @license_category_id as license_category_id, @license_id as parent_license_id, @insert_date as effective_start_date, @license_service_id as license_service_id for json path)  

					if @license_parent_json is not null
						exec dbo.usp_license_insert_license_parent
							@license_parent_json = @license_parent_json,
							@license_effective_source_caller = 'usp_license_insert_child_license'
					
					--legacy insert code below:
					--insert into license_parent (parent_license_id, child_license_id, insert_by, insert_date)
					--values (@license_id, @new_license_id, @insert_by, @insert_date)
	
					set @error = @@error
				
					if @error <> 0 
						begin
							set @error = -230	
							goto backout	
						end 


				-- 2.4) add license capabilities
					declare @product_capability table (capability_id int, capability_type_id int, capability_activation_days int, capability_activation_date datetime, capability_expiration_date datetime)

					insert into @product_capability(capability_id,capability_type_id,capability_activation_days,capability_activation_date,capability_expiration_date)
					select l.capability_id, 
						capability_type_id = case when ((@trial = 1 and l.capability_type_id = 1) or (@nfr_flag is not NULL)) then 2 else l.capability_type_id end, 
						capability_activation_days = 
								case
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and @fixed_expiration_OEM = 1 and capability_type_id <> 4 and e.capability_ext_type_id is not null then datediff(dd,getdate(),@parent_capability_expiration_date)
									when @trial = 1 and l.capability_type_id = 1 and datediff(dd,getdate(),@parent_capability_expiration_date) >= @trial_days then @trial_days
									when @trial = 1 and l.capability_type_id = 1 and datediff(dd,getdate(),@parent_capability_expiration_date) < @trial_days then datediff(dd,getdate(),@parent_capability_expiration_date)
									WHEN @trial = 1 AND l.capability_type_id = 1 THEN @trial_days
									WHEN @nfr_flag is not NULL then datediff(dd,getdate(),@parent_capability_expiration_date)
									else l.capability_activation_days
								end,
						capability_activation_date = 
								case
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and @fixed_expiration_OEM = 1 and capability_type_id <> 4 and e.capability_ext_type_id is not null then dateadd(dd,-(datediff(dd,getdate(),@parent_capability_expiration_date)),@parent_capability_expiration_date)
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and capabilit
y_type_id = 4 or e.capability_ext_type_id is null then null -- no activation date if the capability is turned off
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and @license_type_id = 6 then capability_activation_date
									else @capability_activation_date
								end, 
						capability_expiration_date = 
								case
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and @fixed_expiration_OEM = 1 and capability_type_id <> 4 and e.capability_ext_type_id is not null then @parent_capability_expiration_date
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and capability_type_id = 4 or e.capability_ext_type_id is null then null -- no activation date if the capability is turned off
									when (@trial <> 1 or (@trial = 1 and l.capability_type_id = 2)) and @license_type_id = 6 then capability_expiration_date
									when @trial = 1 and l.capability_type_id = 1 and datediff(dd,getdate(),@parent_capability_expiration_date) >= @trial_days  then dateadd(dd,@trial_days,@capability_activation_date)
									when @trial = 1 and l.capability_type_id = 1 and datediff(dd,getdate(),@parent_capability_expiration_date) < @trial_days then dateadd(dd,(datediff(dd,getdate(),@parent_capability_expiration_date)),@capability_activation_date)
									WHEN @trial = 1 AND l.capability_type_id = 1 THEN dateadd(dd,@trial_days,@capability_activation_date)
									WHEN @fixed_expiration_OEM = 1 then @parent_capability_expiration_date
									else dateadd(dd,capability_activation_days,@capability_activation_date)
								end
					from license_capability l
					left join capability_ext e 
						on l.capability_id = e.capability_id and e.capability_ext_type_id = 1
					where license_id = @license_id


					insert into dbo.license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by) 
					select 	@new_license_id, 
						capability_id, 
						capability_type_id, 
						capability_activation_days,
						capability_activation_date,
						capability_expiration_date,
						@insert_date, @insert_by, @insert_date, @insert_by		
					from @product_capability c
				
					set @error = @@error
				
					if @error <> 0 
						begin
							set @error = -240
							goto backout		
						end 

					-- 2.4.1) write to license contract object
					if @product_line_id in (55, 300)
					begin

						select @license_contract_json = (
						select license_id = @new_license_id, license_category_id = @license_category_id, license_category_type_id = pc.capability_type_id, license_start_date = pc.capability_activation_date, license_end_date = pc.capability_expiration_date, license_service_id = @license_service_id
						from @product_capability pc
						for json path)

						--if data exists, call the insert now
						if @license_contract_json is not null
						begin
							exec dbo.usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_insert_child_license'
						end

					end

					-- 2.4.2) get activation and expiration_dates
					declare @child_capability_activation_date datetime,
							@child_capability_expiration_date datetime

					select @child_capability_activation_date = min(capability_activation_date),
							@child_capability_expiration_date = max(capability_expiration_date)
					from @product_capability		

				-- 2.5 ) insert activation records

					if @machine_name is null or @machine_name = '' 
					begin
						select @machine_name = 'Computer 1' 
					end
					
					if @guid is null 
						begin
						select @guid = ''
						end

					insert into dbo.license_activation(license_id, guid, insert_date, insert_by,machine_name)
					values(@new_license_id, @guid, @insert_date, @insert_by,@machine_name)

	
			-- 2.6 insert license_storage if needed
		
					select @storage_gb = storage_gb
					from dbo.license_storage
					where license_id = @license_id
				
					if @storage_gb is not null
				
						begin
						insert into dbo.license_storage(license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by)
						values(@new_license_id, @storage_gb, @child_capability_activation_date, @child_capability_expiration_date, @insert_date, @insert_by, @insert_date, @insert_by)
					
						if @response_code < 0
							begin 
							goto backout
							end
						end

				-- 2.7) Primary license category seat handling
					if exists (select 1 from @PRIMARY_LICENSE_CATEGORIES where license_category_id = @parent_license_category_id)
						and @nfr_flag is NULL
					begin
						select @license_seats = isnull(@license_seats_specified, 5)
					end

					-- 2.7.1) for NULL
					if @license_seats is null
					begin 
						select @license_seats = license_seats from dbo.license_seat where license_id = @license_id 
					end
				

				-- 2.7.2) seat handling for NULL seats
					if @license_seats is null
					begin
						select @license_seats = 1

						insert into dbo.license_seat(license_id, license_seats, insert_date, insert_by, modified_date, modified_by) 
						values(@license_id, @license_seats, @insert_date, @insert_by, @insert_date, @insert_by)

						--license_active_seats

						IF (@product_line_id NOT IN (55, 300))
							BEGIN

							SELECT @parent_capability_expiration_date = lc.capability_expiration_date, 
							       @parent_capability_activation_date= lc.capability_activation_date
							       FROM dbo.license_capability AS lc

								INSERT INTO dbo.license_active_seats (license_id, start_date, end_date, consumed_seats)
								SELECT @license_id, @parent_capability_activation_date, @parent_capability_expiration_date, 0
								WHERE NOT EXISTS (
									SELECT 1 FROM dbo.license_active_seats las 
									WHERE las.license_id = @license_id 
								);
							END
							
						-- write to license_effective_object if business product, but not mobile SDK
						if @product_line_id in (55, 300) and @license_category_id not in (56, 57) --Mobile SDK, Mobile Browser SDK
						begin

							select @license_effective_object_json = (
							select license_id = @license_id, license_category_id = @license_category_id, license_seats = @license_seats, effective_start_date = @capability_activation_date
							for json path)

							exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_insert_child_license'

						end
					end
					
				
					begin
						insert into dbo.license_seat(license_id, license_seats, insert_date, insert_by, modified_date, modified_by) 
						values(@new_license_id, @license_seats, @insert_date, @insert_by, @insert_date, @insert_by)

						--license_active_seats
						IF (@product_line_id NOT IN (55, 300))
							BEGIN
								INSERT INTO dbo.license_active_seats (license_id, start_date, end_date, consumed_seats)
								SELECT @new_license_id, @child_capability_activation_date, @child_capability_expiration_date, 0
								WHERE NOT EXISTS (
									SELECT 1 FROM dbo.license_active_seats las 
									WHERE las.license_id = @new_license_id 
								);
							END
							
						-- write to license_effective_object if business product, but not mobile SDK
						if @product_line_id in (55, 300) and @license_category_id not in (56, 57) --Mobile SDK, Mobile Browser SDK
						begin

							select @license_effective_object_json = (
							select license_id = @new_license_id, license_category_id = @license_category_id, license_seats = @license_seats, effective_start_date = @capability_activation_date
							for json path)

							exec dbo.usp_license_insert_effective_object 
@license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_insert_child_license'

						end
					end
				
				-- 2.8 insert license_feature if needed

					select @license_feature_check = count(*)
					from license_feature_license
					where license_id = @license_id and license_feature_id not in (8,10)
	
					if @license_feature_check > 0
				
						begin
							insert into dbo.license_feature_license (license_feature_id, license_id, license_feature_value, insert_date, insert_by)
							select license_feature_id, @new_license_id, license_feature_value, @insert_date, @insert_by
							from dbo.license_feature_license
							where license_id = @license_id and license_feature_id <> 8					

							set @error = @@error
					
							if @error <> 0 
								begin
									set @error = -270	
									goto backout	
								end 
						end


				-- 2.9.1) insert license_category record on parent if not set
				if @license_category_id is null 
					begin
					select @license_category_id = dbo.fn_GetLicenseCategoryId(@license_id) 
			
					insert into dbo.license_category_license(license_id, license_category_id, last_modified_date, last_modified_by)
					values(@license_id,@license_category_id, @insert_date, @insert_by)
					end
			
				-- 2.9.2) insert child license category
					begin
					insert into dbo.license_category_license(license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by)
					values(@new_license_id,@license_category_id,@child_capability_activation_date,@child_capability_expiration_date, @insert_date, @insert_by)					
					end	
				
			-- 2.10) license_module_license
				if (select count(*) from dbo.license_module_license where license_id = @license_id) > 0
					begin
					insert into dbo.license_module_license(license_id,license_module_id,license_module_type_id,start_date,end_date)
					select @new_license_id,m.license_module_id,m.license_module_type_id,@child_capability_activation_date,@child_capability_expiration_date
					from dbo.license_module_license m
					inner join dbo.license_module lm
						on lm.license_module_id = m.license_module_id
					where m.license_id = @license_id and lm.license_module_class_id in (1,2)
					end		
		

			-- 2.11) sky_api_license
			if @product_line_id in (55,300) AND ISNULL(@ecom_create_license,0) =0
				begin
					insert into dbo.sky_api_license (license_id)
					select l.license_id
					from dbo.license l
					left join dbo.sky_api_license a
						on l.license_id = a.license_id
					where l.license_id = @new_license_id and a.license_id is null
				end
			else
				begin
					insert into dbo.prevx_update(license_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
					values(@new_license_id, 1, 0, getdate(), getdate(), getdate())
				end	

			-- 2.12) insert prevx_update monitor record
				if @nfr_flag is not NULL
					begin
						exec dbo.usp_sky_insert_update @new_license_id, 2, @process_date, NULL
					end		
		
			-- 2.13) insert license_summary
				exec dbo.usp_license_insert_license_summary_data @new_license_id
			
		end

	
				else
					begin
						set @error = -100
		end

	-------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) OUTPUT	
	-------------------------------------------------------------------------------------------------------------------------------------

		backout: 
		if @error < 0
			begin
				delete from dbo.license_feature_license where license_id = @new_license_id
				delete from dbo.license_seat where license_id = @new_license_id
				delete from dbo.license_category_license where license_id = @new_license_id
				delete from dbo.license_storage where license_id = @new_license_id
				delete from dbo.license_capability where license_id = @new_license_id

				delete from dbo.license_parent where child_license_id = @new_license_id
				delete from dbo.license_activation where license_id = @new_license_id
				delete from dbo.license where license_id = @new_license_id
				delete from dbo.license_active_seats where license_id = @new_license_id
			end
			
		select 	new_keycode = 
				case 
					when @error < 0 then null
					else @new_keycode
				end, 
			failure_type_id = @error


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert child failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec dbo.usp_LogError @ErrorDB = @DBName
		
	end catch;








GO
