-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_effective_object]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_effective_object]
	@license_effective_object_json varchar(max),
	@license_effective_source_caller varchar(50)

/*	
	DATE		AUTHOR		REMARKS
	2017-04-30	cnovac		Initial creation.
	2018-02-15	cnovac		Updated to have license_category and revamped all code.
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2020-02-07	wbarton		Adding logic to mark previous effective_object_id 1 inserts via license_service as dup when their start_date >= the start_date of an effective_object_id 1 insert from an order
	2020-11-13	g.lagos		Adding logic, to use last record inserted as king, all others will be set as_is_dup=1 Story LAGER-2347

*/
as

set nocount on

begin try

	declare @license_effective_object_json_id int,
			@current_date_time datetime = getdate(),
			@current_date date = getdate(),
			@rowcount_json int,
			@rowcount_leo int,
			@start int = 1
	declare @effective_json table (id int identity (1,1), [key] int, value varchar(max))
	declare @effective_transaction table (license_effective_object_transaction_id int, effective_object_transaction_type_index int, effective_object_transaction_type_id int)
	declare @license_effective_object table 
			(id int identity (1,1), 
			license_id int, 
			license_category_id tinyint, 
			license_effective_object_transaction_id int, 
			effective_object_id tinyint, 
			effective_value int, 
			effective_start_date date)
	declare @license_effective_object_insert table (license_effective_object_id int)

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_effective_object_json
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--log the json first and return the id back
	insert into dbo.license_effective_object_json (license_effective_object_json, license_effective_source_caller)
	values (@license_effective_object_json, @license_effective_source_caller)

	set @license_effective_object_json_id = scope_identity()

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_effective_object_transaction
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--now basically seperate the number of JSON license objects
	insert into @effective_json ([key], value)
	select [Key], Value
	from openjson(@license_effective_object_json)
	order by [Key]

	select @rowcount_json = @@ROWCOUNT

	--insert the rows which have order_item_id/license_service_id/trial_registration_id in it
	insert into dbo.license_effective_object_transaction (license_effective_object_json_id, effective_object_transaction_type_index, effective_object_transaction_type_id, effective_object_transaction_type_value)
	output Inserted.license_effective_object_transaction_id, Inserted.effective_object_transaction_type_index, Inserted.effective_object_transaction_type_id 
			INTO @effective_transaction(license_effective_object_transaction_id, effective_object_transaction_type_index, effective_object_transaction_type_id)
	select @license_effective_object_json_id, ej.[key], eott.effective_object_transaction_type_id, ej2.Value
	from @effective_json ej cross apply openjson(ej.value) ej2
	inner join dbo.effective_object_transaction_type eott on ej2.[Key] = eott.effective_object_transaction_type_name c
ollate Latin1_General_BIN2
	order by ej.[key]

	if @@ROWCOUNT = 0
	begin
		--this means couldn't find order_item_id/license_service_id/trial_registration_id, so just write the json
		insert into dbo.license_effective_object_transaction (license_effective_object_json_id, effective_object_transaction_type_index)
		output Inserted.license_effective_object_transaction_id, Inserted.effective_object_transaction_type_index 
			INTO @effective_transaction(license_effective_object_transaction_id, effective_object_transaction_type_index)
		select @license_effective_object_json_id, ej.[key]
		from @effective_json ej
		order by ej.[key]
	end

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_effective_object
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--now loop through each JSON license objects and pull all the elements out which are defined in effective_object and put in @license_effective_object
	while @rowcount_json > = @start
	begin
		insert into @license_effective_object (license_id, license_category_id, license_effective_object_transaction_id, effective_object_id, effective_value, effective_start_date)
		select ej4.Value, ej6.Value, et.license_effective_object_transaction_id, eo.effective_object_id, ej2.Value, ej8.Value
		from @effective_json ej cross apply openjson(ej.value) ej2
		inner join @effective_transaction et on ej.[key] = et.effective_object_transaction_type_index
		inner join dbo.effective_object eo on ej2.[Key] = eo.object_element_name collate Latin1_General_BIN2
		inner join @effective_json ej3 cross apply openjson(ej3.value) ej4 on ej4.[Key] = 'license_id'
		inner join @effective_json ej5 cross apply openjson(ej5.value) ej6 on ej6.[Key] = 'license_category_id'
		inner join @effective_json ej7 cross apply openjson(ej7.value) ej8 on ej8.[Key] = 'effective_start_date'
		where ej.id = @start
		and ej3.id = @start
		and ej5.id = @start
		and ej7.id = @start
		order by ej.id

		set @start = @start + 1
	end

	--insert the data into license_effective_object from the temp table
	insert into license_effective_object (license_id, license_category_id, license_effective_object_transaction_id, effective_object_id, effective_value, effective_start_date, modified_date, insert_date)
	output Inserted.license_effective_object_id into @license_effective_object_insert(license_effective_object_id)
	select leo.license_id, leo.license_category_id, leo.license_effective_object_transaction_id, leo.effective_object_id, leo.effective_value, leo.effective_start_date, @current_date_time, @current_date_time
	from @license_effective_object leo
	order by leo.id

	select @rowcount_leo = @@ROWCOUNT

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- update license_effective_object with is_dup if applicable
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--mark the older record as a dup if the newer record start date = old record start date
	update leo2
	set leo2.effective_end_date = leo2.effective_start_date,
		leo2.is_dup = 1,
		leo2.modified_date = @current_date_time
	from @license_effective_object_insert leo_temp
	inner join license_effective_object leo on 
			leo.license_effective_object_id = leo_temp.license_effective_object_id
	inner join license_effective_object leo2 on 
			leo2.license_id = leo.license_id and 
			leo.license_category_id = leo2.license_category_id	and 
			leo.effective_object_id = leo2.effective_object_id and 
			leo.effective_start_date = leo2.effective_start_date
	where leo2.license_eff
ective_object_id < leo.license_effective_object_id
	and leo2.is_dup != 1

	--START mark the newer record by effective date as isdup=1 if the newest inserted record has older effective start date LAGER-2374

	update leo2
	set leo2.effective_end_date = leo2.effective_start_date,
		leo2.is_dup = 1,
		leo2.modified_date = @current_date_time
	from @license_effective_object_insert leo_temp
	inner join license_effective_object leo on leo.license_effective_object_id = leo_temp.license_effective_object_id
	inner join license_effective_object leo2 on leo2.license_id = leo.license_id and leo.license_category_id = leo2.license_category_id	and leo.effective_object_id = leo2.effective_object_id
	where leo2.effective_start_date > leo.effective_start_date
	and leo2.is_dup != 1

	--END mark the newer record by effective date as isdup=1 if the newest inserted record has older effective start date LAGER-2374

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- update license_effective_object effective_end_date column
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	set @start = 1

	while @rowcount_leo > = @start
	begin
		--this code basically updates all the end dates for any records not marked as dups by license
		update leo
		set leo.effective_end_date = dateadd(dd, -1, leo2.effective_start_date),
			leo.modified_date = @current_date_time
		from @license_effective_object leo_temp
		inner join license_effective_object leo on 
					leo.license_id = leo_temp.license_id and 
					leo.license_category_id = leo_temp.license_category_id and 
					leo.effective_object_id = leo_temp.effective_object_id
		inner join license_effective_object leo2 on 
					leo2.license_id = leo.license_id and 
					leo.license_category_id = leo2.license_category_id	and 
					leo.effective_object_id = leo2.effective_object_id
		where leo_temp.id = @start
		and leo.effective_start_date < leo2.effective_start_date
		and (leo.effective_end_date >= leo2.effective_start_date or leo.effective_end_date is null)
		and leo2.is_dup != 1

		set @start = @start + 1
	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_license_insert_effective_object'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_external_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_external_license]

(

@service_json varchar(max)

)

              
/*     
       DATE          AUTHOR        REMARKS
       2019-05-01    acoffel              Initial creation.
       
       DESCRIPTION
       select or insert license 
*/

AS
       set nocount on                           

       declare       @keycode varchar(40),
                     @license_id int,
                     @license_service_type_name varchar(20),
                     @url_link varchar(500),
                     @response_code int,
                     @sky_template_id int,
                     @message varchar(100)

                     select @sky_template_id = sky_template_id from dbo.sky_template where sky_template_name = 'brtc_update'


       begin try

       
        ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        --1.) keycode lookup
        ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                 declare @service_json_table table (license_service_value_type_id int, column_value varchar(500))

       -- 1.1) get key
                 insert into @service_json_table (license_service_value_type_id, column_value)
                 select license_service_value_type_id = case when t.license_service_value_type_id is null then a.license_service_value_type_id else t.license_service_value_type_id end,
                              nullif(nullif(StringValue, 'null'), '') as column_value
                 from dbo.fn_parse_json(@service_json) j
                 left join license_service_value_type t
                        on j.Name = t.value_type_name
                 left join license_service_value_type_alias a
                        on j.Name = a.value_type_name
                 where Object_ID is null and (t.license_service_value_type_id is not null or a.license_service_value_type_id is not null)
                 order by 2

       -- 1.2) set key
                 select @keycode = column_value
                 from @service_json_table
                 where license_service_value_type_id = 2

       -- 1.3) set url
                 select @url_link = column_value
                 from @service_json_table
                 where license_service_value_type_id = 31

       -- 1.4)   set license_id
                 select @license_id = license_id
                 from dbo.license
                 where keycode = @keycode

       -- 1.5) return result or create new license
                 if @license_id is not null
                        begin
                              select keycode = @keycode, license_id = @license_id, url_link = @url_link
                              return
                end
                        else
                begin
                              select @license_service_type_name = 'license_create'
                              declare @license_service_id table (license_service_id int)
                              insert into @license_service_id (license_service_id)
                              exec usp_license_service_insert_service @license_service_type_name, @service_json
                        end
    
       select @license_id = license_id from license where keycode = @keycode

       --1.5) insert sky brtc update
          --insert into sky_update (license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, pro
cess_date)
          --select @license_id, @sky_template_id, @sky_template_id, 0, getdate(), 0, getdate()          
                       
       --1.5) set license_id and keycode
          select l.license_id, l.keycode, c.url_link
          from license l
          INNER JOIN cisco_license c
                 ON l.license_id = c.license_id
          where l.keycode = @keycode


       end try

       begin catch

            set @response_code = -200
            set @message = case when @message is null then 'insert license failed'
                                              else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
              
		end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_external_reference]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_insert_external_reference]
	@license_id int,
	@license_category_id tinyint,
	@effective_object_id tinyint,
	@external_reference_value varchar(100),
	@license_external_reference_vault_id int = null,
	@company_id int =null,
	@vault_id int =null,
	@reseller_flag int =null,
	@reseller_partner varchar(100) =null,
	@return_license_external_reference_id bit = 1


/*	
	DATE		AUTHOR		REMARKS
	2019-10-02	cnovac		Initial creation.
	2020-04-17	cnovac		Return @license_external_reference_id back to PHP
	2020-04-30	cnovac		Took out call to insert into effective object
	2020-06-29	wbarton		Adding @license_external_reference_vault_id to lay down a relationship between vault and tenant
	2020-02-02	wbarton		Adding the option to not return the license_external_reference_id so we can control what PHP gets back in cases where this is called as a subroutine.
	2022-06-03  psatish		ALM# 1377 Added the reseller logic and populated the reseller data into the reseller_license table
	2022-06-15  psatish		ALM# 1571 Added @reseller_partner parameter to check the partner_id already exists for the reseller
*/
as

set nocount on

begin try

	declare @license_external_reference_id int,
			@reseller_provisioning int,
			@reseller_company_id int
			
	declare @reseller table(company_id int,vault_id int,effective_object_id int,license_id int)

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_external_reference
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @license_external_reference_id = license_external_reference_id
	from fn_license_select_external_reference(@license_id, @license_category_id, @effective_object_id, @external_reference_value, @license_external_reference_vault_id)

	if @license_external_reference_id is null
	begin

		insert into license_external_reference (license_external_reference_vault_id, license_id, license_category_id, effective_object_id, external_reference_value)
		select @license_external_reference_vault_id, @license_id, @license_category_id, @effective_object_id, @external_reference_value

		select @license_external_reference_id = scope_identity()
	end
	------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into reseller_license
	-----------------------------------------------------------------------------------------------------------------------------------------------------------
	if isnull(@reseller_partner,'') <>'' and @reseller_flag=1 and @license_category_id=234
	begin
		select @reseller_company_id=oc.company_id
		from order_header oh
		inner join order_item oi
		on oi.order_header_id = oh.order_header_id
		inner join dbo.order_item_license ol
		on ol.order_item_id = oi.order_item_id
		inner join dbo.order_company oc
		on oc.order_header_id = oh.order_header_id
		inner join dbo.order_company_type oct
		on oct.order_company_type_id = oc.order_company_type_id
		where ol.license_id=@license_id
		and oct.order_company_type_name='reseller_partner_account'


		if exists(select 1 from dbo.reseller_provisioning where vault_id=@vault_id and cep_partner_id=@reseller_partner and company_id=@reseller_company_id)
		begin
			insert into dbo.license_external_reference
			(
			    license_external_reference_vault_id,
			    license_id,
			    license_category_id,
			    effective_object_id,
			    external_reference_value
			    
			)
			selec
t distinct @license_external_reference_vault_id,
			@license_id,
			@license_category_id,
			ex.effective_object_id,
			ex.external_reference_value
			from dbo.reseller_license rl
			inner join dbo.reseller_provisioning pv
			on pv.company_id = rl.company_id
			and pv.vault_id = rl.vault_id
			inner join dbo.license_external_reference ex
			on ex.license_external_reference_id = rl.license_external_reference_id
			and ex.effective_object_id = rl.effective_object_id
			and ex.license_id = rl.license_id
			left join dbo.license_external_reference exr
			on exr.effective_object_id = ex.effective_object_id
			and exr.external_reference_value=ex.external_reference_value
			and exr.license_id=@license_id
			and exr.license_category_id=@license_category_id
			and exr.license_external_reference_vault_id=@license_external_reference_vault_id
			where pv.company_id=@reseller_company_id
			and pv.vault_id=@vault_id
			and pv.cep_partner_id=@reseller_partner
			and exr.license_external_reference_id is null
            
			insert into dbo.reseller_license
			(
			    license_id,
			    effective_object_id,
			    vault_id,
			    company_id,
			    license_external_reference_id
			)
			select distinct ex.license_id,
			ex.effective_object_id,
			rv.vault_id,
			@reseller_company_id,
			ex.license_external_reference_id
			from dbo.license_external_reference ex
			inner join dbo.license_external_reference_vault rv
			on rv.license_external_reference_vault_id = ex.license_external_reference_vault_id
			left join dbo.reseller_license rl
			on rl.license_external_reference_id = ex.license_external_reference_id
			and rl.license_id=ex.license_id
			where ex.license_id=@license_id
			and ex.license_category_id=@license_category_id
			and ex.license_external_reference_vault_id=@license_external_reference_vault_id
			and ex.license_external_reference_id <> @license_external_reference_id
			and rl.reseller_license_id is null
		
		end

	end
		
	if @reseller_flag=1 and @license_category_id=234 
	begin
	
		if not exists(select 1 from reseller_license where license_id=@license_id and company_id=@company_id and vault_id =@vault_id AND license_external_reference_id=@license_external_reference_id)
		begin
			insert into reseller_license(license_id,vault_id,company_id,license_external_reference_id,effective_object_id)
			values(@license_id,@vault_id,@company_id,@license_external_reference_id,@effective_object_id)
		end

		insert into @reseller
		(
		company_id,
		vault_id,
		effective_object_id,
		license_id
		)
		select distinct oc.company_id,rv.vault_id,eo.effective_object_id,rv.license_id
		from dbo.order_company oc
		inner join order_item oi
		on oi.order_header_id = oc.order_header_id
		inner join dbo.order_item_license ol
		on ol.order_item_id = oi.order_item_id
		inner join dbo.license_external_reference_vault rv
		on rv.license_id = ol.license_id
		inner join dbo.vault vt
		on vt.vault_id = rv.vault_id
		inner join dbo.product_platform pp
		on pp.product_platform_id = vt.product_platform_id
		inner join dbo.license_category lc
		on lc.license_category_id = rv.license_category_id
		inner join dbo.effective_object eo
		on eo.object_name=lc.license_category_description
		where ol.license_id=@license_id
		and eo.object_element_name not in('cep_vault_id','cep_partner_id')
		and pp.product_platform_name='saas'

		if(select count(*) 
		from @reseller rs
		inner join dbo.license_external_reference_vault rv
		on rv.vault_id=rs.vault_id
		and rv.license_id = rs.license_id
		left join dbo.reseller_license rl
		on rl.company_id = rs.company_id
		and rl.license_id = rs.license_id
		and rl.vault_id = rs.vault_id
		and rl.effective_object_id=rs.effective_object_id
		left join dbo.license_external_reference ex
		on ex.effective_object_id = rs.effective_object_id
		and ex.license_external_reference_vault_id = rv.license_external_reference_vault_id
		and ex.license_id 
= rs.license_id
		and ex.license_external_reference_id=rl.license_external_reference_id
		where rs.license_id=@license_id
		and (ex.license_external_reference_id is null or rl.reseller_license_id is null))=0
				set @reseller_provisioning=1
		else
				set @reseller_provisioning=0
       
	end
	
	
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- update license_external_reference_vault is_provisioned.
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @license_external_reference_vault_id is not null
		begin
			if @reseller_flag =1 and isnull(@reseller_provisioning,0)=1 and @license_category_id=234
				exec usp_license_update_external_reference_vault @license_external_reference_vault_id = @license_external_reference_vault_id, @is_provisioned = 1,@reseller_provisioning=@reseller_provisioning
			else if isnull(@reseller_flag,0)=0
				exec usp_license_update_external_reference_vault @license_external_reference_vault_id = @license_external_reference_vault_id, @is_provisioned = 1
		end

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- return
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @return_license_external_reference_id = 1
		begin
			select @license_external_reference_id as license_external_reference_id
		end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_license_insert_external_reference'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_external_reference_vault]
-- =============================================================================

CREATE procedure [dbo].[usp_license_insert_external_reference_vault]

	@license_external_reference_vault_json nvarchar(max),
	@license_service_type_name varchar(50) = null

/*	
	DATE		AUTHOR		REMARKS
	2020-06-24	wbarton		Initial creation
	2020-10-06	wbarton		Adding logging insert. Also Bug fixes in QA to correctly default vault(s) by customer address, and prevent a vault insert for license categories that do not already exist on the license
	2020-10-21	wbarton		Commenting out code that prevents the license_external_reference_vault insert for GSM OTSF
	2020-11-02	wbarton		Adding validation against vault_license_category for non-license-service transactions to prevent vault inserts if bad data is passed into the procedure
	2020-01-29	wbarton		Extending license_vault_add handling to support DMC vault creation 
	2020-02-28	wbarton		Adding order_header_id as an option in the input data, to be used conditionally for the Carbonite backfill
	2021-03-05	esmart		Extend for billing_type, storage_GB
	2022-02-09  rambasana	Do not set default Vault_id, when a vault or vaults are not explicitly supplied for CEP OnPrem and Azure
	2022-03-09  psatish		Added update_license_vault template into sfdc_opportunity_update to update the license vault in Salesforce
	2022-06-16  psatish		ALM# 1573 Handled Multi vault for Trial license
	2022-29-11	psatish		ALM# 3732 Added section 2.4.1 and set Is_Provisioned to 1 for the renewals on the migrated licenses as we already have provisioned data
	2023-16-02  psatish		ALM# 4835 Use the existing vault for CBEP renewal orders created for the US region
	DESCRIPTION
	Inserts records into license_external_reference_vault

*/
as

set nocount on

begin try

	declare @loop_value int, 
		@loop_max int, 
		@record_json nvarchar(max), 
		@license_id int, 
		@keycode varchar(40), 
		@country varchar(75), 
		@license_category_json nvarchar(max),
		@license_category_id int,
		@effective_object_id tinyint,
		@external_reference_value varchar(100),
		@license_external_reference_vault_id int,
		@status varchar(100),
		@result nvarchar(max),
		@order_header_id int

		
		
	declare @license_external_reference_vault_json_objects table (
		id int identity (1,1),
		[key] int,
		value nvarchar(max)
	)
	
	declare @vault table (
		id int identity(1,1),
		license_id int,
		license_category_id tinyint,
		license_category_name varchar(10),
		country varchar(75),
		vault_id int,
		is_provisioned bit,
		billing_type varchar(20),
		storage_GB int,
		case_number varchar(20),
		notes nvarchar(max),
		vault_name nvarchar(100),
		vault_guid nvarchar(100),
		customer_short_name varchar(100),
		csb_portal_name varchar(100),
		csb_portal_company_name varchar(100),
		license_external_reference_vault_id int,
		license_external_reference_id INT,
		order_header_id int

	)

	declare @external_reference table (license_id int, license_category_id tinyint, license_external_reference_vault_id int, object_element_name varchar(50), external_reference_value varchar(100))

	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1. Insert logging data
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into license_external_reference_vault_json_log(processing_procedure, input_json, license_service_type_name)
	select 'usp_license_insert_external_reference_vault', @license_external_reference_vault_json, @license_service_type_name

	----------------------------------------------------------------------------------
----------------------------------------------------------------------------------------
	--2. Parse @license_external_reference_vault_json into @vault maintaining compatibility for either singular vault_id key-value or vault array
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.1) In case there are multiple objects within @license_external_reference_vault_json (multi-category trials or orders needing vault maintenance), we need to check the vault properties for each object
	insert into @license_external_reference_vault_json_objects([key], value)
	select [key], value
	from openjson(@license_external_reference_vault_json)
	where type = 5

	-- 2.2) If multiple objects do not exist within the json, insert @license_external_reference_vault_json as-is. Using the table variable allows the next steps to process records consistently.
	if @@rowcount = 0
		begin
			insert into @license_external_reference_vault_json_objects(value)
			select @license_external_reference_vault_json
		end

	-- 2.3) Parse data from each json object in @license_external_reference_vault_json_object.
	select @loop_value = (select min(id) from @license_external_reference_vault_json_objects), @loop_max = (select max(id) from @license_external_reference_vault_json_objects)
	while @loop_value <= @loop_max
		begin
			select @record_json = value
			from @license_external_reference_vault_json_objects
			where id = @loop_value

			select @license_id = j.license_id, @keycode = j.keycode, @country = j.country, @license_category_json = j.license_category, @order_header_id = j.order_header_id
			from openjson(@record_json)
			with (
				license_id int '$.license_id',
				keycode varchar(40) '$.keycode',
				country varchar(75) '$.country',
				license_category nvarchar(max) as json,
				order_header_id int '$.order_header_id'
			) j

			-- 2.3.1) If license_id is null (scenarios like license_service which pass in keycode), find the license_id
			if @license_id is null and @keycode is not null
				begin
					select @license_id = l.license_id
					from license l with (nolock)
					where l.keycode = @keycode
				end
			

			-- 2.3.2) Checking the license category array for either a singular vault_id (backward compatibility) or for a vault array. If the later exists, those values get inserted into @vault.
			insert into @vault(license_id, order_header_id,license_category_id, license_category_name, country, vault_id, is_provisioned, billing_type, storage_GB, case_number, notes, vault_name, vault_guid, customer_short_name, csb_portal_name, csb_portal_company_name)
			select @license_id, @order_header_id,j.license_category_id, j.license_category_name, @country, iif(v.vault_id is null, j.vault_id, v.vault_id), iif(v.is_provisioned is null, 0, v.is_provisioned), v.billing_type, v.storage_gb, v.case_number, v.notes, v.vault_name, v.vault_guid, v.customer_short_name, v.csb_portal_name, v.csb_portal_company_name
			from openjson(@license_category_json)
			with (
				license_category_id tinyint '$.license_category_id',
				license_category_name varchar(10) '$.license_category_name',
				vault_id int '$.vault_id',
				vault_array nvarchar(max) '$.vault' as json
			) j
				outer apply (

					select vault_id, is_provisioned, billing_type, storage_gb, case_number, notes, vault_name, vault_guid, customer_short_name, csb_portal_name, csb_portal_company_name
					from openjson(j.vault_array)
					with (
						vault_id int '$.vault_id',
						is_provisioned bit '$.is_provisioned',
						billing_type varchar(100) '$.billing_type',
						storage_gb int '$.storage_GB',
						case_number varchar(20) '$.case_id',
						notes nvarchar(max) '$.notes',
						vault_name nvarchar(100) '$.vault_name',
						vault_guid nvarchar(100) '$.vault_guid',
						customer_short_name varchar(100) '$.customer_short_name',
						csb_portal_name varchar(100) '$.csb_portal_name',
						csb_portal_company_name varchar(100) '$.csb_portal_company_name'

					)
				) v


				select @record_json = null, @license_category_json = null, @license_id = null, @keycode = null, @loop_value = @loop_value + 1
		end

		-- 2.4) If license_category_id is null (scenarios like license service which pass only license_category_name), find the license_category_id
		update v 
		set license_category_id = lc.license_category_id
		from @vault v
			inner join license_category lc
				on lc.license_category_name = v.license_category_name
		where v.license_category_id is null
        
		
		---2.4.1 set is_provisioned to 1 for the migrated licenses
		update v
		set v.is_provisioned=case when  dm.license_distribution_method_code='NSBF' 
										and exists(select 1 from dbo.license_external_reference ex
											       where ex.license_id=v.license_id)
								  then 1 
								  else isnull(v.is_provisioned,0) end
		from @vault v
		inner join license lc
		on lc.license_id = v.license_id
		inner join dbo.license_distribution_method dm
		on dm.license_distribution_method_id = lc.license_distribution_method_id
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--3. For license_service license_vault_add requests, skip any defaulting and run the insert
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @license_service_type_name = 'license_vault_add'
		begin
			--3.1 Check if we don't have vault_id explicitly provided, and if so set vault_id from vault_guid
			if exists (select 1 from @vault where vault_id is null)
				begin
					update vv 
					set vv.vault_id = v.vault_id
					from @vault vv
						inner join vault v
							on v.vault_datacenter_key = vv.vault_guid
					where vv.vault_id is null
				end

			--3.2 Remove instances where we don't have a vault_id set
			delete from @vault
			where vault_id is null

			if not exists (select 1 from @vault)
				begin
					set @status = 'license_external_reference_vault record not inserted: vault_id not found'
					goto license_service_return
				end

			--3.3 Inserting into license_external_reference_vault only if the specified vault_id does not yet exist for the license and category, as is_active = 1
			declare @current_license_vaults table (license_id int, license_category_id tinyint, vault_id int, billing_type varchar(20), storage_gb int, case_number varchar(20), customer_short_name varchar(100))

			insert into @current_license_vaults(license_id,license_category_id,vault_id,billing_type,storage_gb,case_number,customer_short_name)
			select v.license_id, v.license_category_id, v.vault_id, v.billing_type, v.storage_GB, v.case_number, er.external_reference_value
			from @vault v
			cross apply dbo.fn_license_select_license_profile(v.license_id) p
			inner join license_external_reference_vault lrv
				on lrv.license_id = v.license_id and lrv.license_category_id = v.license_category_id and lrv.vault_id = v.vault_id and lrv.is_active = 1
			inner join license_external_reference er
				on er.license_external_reference_vault_id = lrv.license_external_reference_vault_id and er.effective_object_id = 19
			where p.license_category_id = v.license_category_id


			insert into license_external_reference_vault(license_id, license_category_id, vault_id, is_provisioned, billing_type, storage_GB, case_number, notes)
			select v.license_id, v.license_category_id, v.vault_id, v.is_provisioned, v.billing_type, v.storage_GB, v.case_number, v.notes
			from @vault v
			left join @current_license_vaults c
				on c.vault_id = v.vault_id and c.license_id = v.license_id and c.license_category_id = v.license_category_id and c.customer_short_nam
e = v.customer_short_name
			where c.license_id is null

			select @license_external_reference_vault_id = scope_identity()

			if @license_external_reference_vault_id is not null
				begin
					set @status = 'success'
				end

			update vv 
			set vv.license_external_reference_vault_id = @license_external_reference_vault_id
			from @vault vv
				
			--3.4 license_external_reference management for DMC created vaults

				-- 3.4.1) build up external reference data
				insert into @external_reference(license_id,license_category_id,license_external_reference_vault_id,object_element_name,external_reference_value)	
				select v.license_id, v.license_category_id, v.license_external_reference_vault_id, 'customer_short_name', v.customer_short_name from @vault v where v.customer_short_name is not null and v.license_external_reference_vault_id is not null
		
				insert into @external_reference(license_id,license_category_id,license_external_reference_vault_id,object_element_name,external_reference_value)	
				select v.license_id, v.license_category_id, v.license_external_reference_vault_id, 'csb_portal_name', v.csb_portal_name from @vault v where v.csb_portal_name is not null and v.license_external_reference_vault_id is not null
		
				insert into @external_reference(license_id,license_category_id,license_external_reference_vault_id,object_element_name,external_reference_value)	
				select v.license_id, v.license_category_id, v.license_external_reference_vault_id, 'csb_portal_company_name', v.csb_portal_company_name from @vault v where v.csb_portal_company_name is not null and v.license_external_reference_vault_id is not null

				-- 3.4.2) insert license_external_reference
				insert into license_external_reference(license_external_reference_vault_id,license_id,license_category_id,effective_object_id,external_reference_value)			
				select e.license_external_reference_vault_id,e.license_id,e.license_category_id,eo.effective_object_id,e.external_reference_value
				from @external_reference e
				inner join effective_object eo
					on eo.object_element_name = e.object_element_name
				left join license_external_reference er
					on er.effective_object_id = eo.effective_object_id and er.license_category_id = e.license_category_id and er.license_external_reference_vault_id = e.license_external_reference_vault_id and er.license_id = e.license_id
				where er.license_external_reference_id is null

			--3.5 Inserting sky_update records for scenarios that require automated provisioning	
			insert into sky_update (license_id, sky_template_id, sky_update_type_id, process_date)
			select distinct license_id, ss.sky_template_id, st.sky_update_type_id, getdate()
			from @vault v
				inner join vault vlt
					on vlt.vault_id = v.vault_id
				inner join product_platform p
					on p.product_platform_id = vlt.product_platform_id and p.vault_provisioning = 'automated'
				inner join dbo.sky_supplemental_template ss
					on ss.license_category_id = v.license_category_id
				inner join dbo.sky_template_update_type st
					on st.sky_template_id = ss.sky_template_id
			where v.is_provisioned = 0

			-- 3.6) license_service_return
			license_service_return:
			if @status is null 
				begin
					set @status = 'license_external_reference_vault record not inserted: duplicate request or invalid license category'
				end

			select @result = (
				select license_external_reference_vault_id, license_external_reference_id
				from @vault
				for json path
			)
			select @status as status, @result as result
			return
		end

	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--4. Select a default vault_id for instances when a vault or vaults are not explicitly supplied
	-----------------------------------------------------------------------------------------------------------------
---------------------------------------------------------
	--Not Updating vault to Default Vault_id, when a vault or vaults are not explicitly supplied for CEP OnPrem and Azure.  
		
		DELETE v
		FROM @vault v
		INNER JOIN  dbo.license_effective_object leo ON leo.license_id = v.license_id
		WHERE v.license_category_id = 234
		AND leo.effective_object_id = 17
		And leo.effective_value IN (2,3)
		AND leo.is_dup = 0
		AND v.vault_id IS null
	
	UPDATE v 
	set vault_id = va.vault_id
	from @vault v
		-- country_id from @vault when explicitly supplied. Supporting both iso and description, as PHP has used both in trial registration JSON over time.
		left join lu_countries lc1
			on lc1.iso = v.country
		left join lu_countries lc2
			on lc2.description = v.country
		--country_id from customer_address
		left join (
			select top 1 l.license_id, ca.country_id
			from license l
				inner join @vault v2
					on v2.license_id = l.license_id
				inner join customer_address ca
					on l.customer_id = ca.customer_id and ca.address_status_id = 1
			order by ca.customer_address_id desc --most recent active address record
		) c2
			on v.license_id = c2.license_id 
		inner join vault_country vc
			--If country exists on the @vault record, that mapping to country_id is used.  If it doesn't exist, the customer_address country_id is used. If neither exist, 0 (unknown) is the default.
			on vc.country_id = iif(lc1.country_id is null, iif(lc2.country_id is null, iif(c2.country_id is null, 0, c2.country_id), lc2.country_id), lc1.country_id)
		inner join vault_license_category vlc
			on vlc.vault_id = vc.vault_id and vlc.license_category_id = v.license_category_id
		inner join vault va
			on va.vault_id = vlc.vault_id and va.vault_status = 'active'
	where v.vault_id is NULL
     

	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--5. Insert into license_external_reference_vault.  Blocking the insert for licenses and categories that already have a vault or vaults provisioned.
		--The agreed-upon business logic is that vault configuration should not be changed outside of support requests (handled through license_service).
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Not inserting a vault record when the license is OTSF GSM - commented out per business logic requirements change
	--delete v 
	--from @vault v
	--	inner join license l with (nolock)
	--		on l.license_id = v.license_id and l.license_keycode_type_id = 3
	--where v.license_category_id = 233

	--Not inserting a vault record when site_id = CARBONITEBACKFILL
	delete v
	from @vault v
		inner join order_header oh with (nolock)
			on oh.order_header_id = v.order_header_id
	where oh.site_id = 'CARBONITEBACKFILL'

	--Blocking the insert for licenses and categories that already have a vault or vaults provisioned. The agreed-upon business logic is that vault configuration should not be changed outside of support requests (handled through license_service).	
	--Blocking the insert for license_category_ids that are not present on the license. NOTE: we can't use the license profile for this, because in cases where a new license is created this insert takes place before all data is available through the profile.
	insert into license_external_reference_vault(license_id, license_category_id, vault_id,is_provisioned)
	select distinct v.license_id, v.license_category_id, v.vault_id,v.is_provisioned
	from @vault v
		inner join vault vt
			on vt.vault_id = v.vault_id
		--inserting only vaults that are applicable to the license category. This prevents inserts from bad vault data passed-into the procedure.
		inner join vault_license_category vlc
			on vlc.vault_id = v.vault_id and vlc.license_category_id
 = v.license_category_id
		--inserting only license categories that already exist on the license
		left join license_category_license lcl
			on lcl.license_id = v.license_id and lcl.license_category_id = v.license_category_id
		left join license_module_license lml
			on lml.license_id = v.license_id
		left join license_module_category lmc
			on lmc.license_module_id = lml.license_module_id and lmc.license_category_id = v.license_category_id
		left join license_external_reference_vault lrv
			on lrv.license_id = v.license_id and lrv.license_category_id = v.license_category_id and lrv.is_active = 1 and lrv.vault_id= v.vault_id
	where lrv.license_external_reference_vault_id is null
		and (lcl.license_category_id is not null or lmc.license_category_id is not null)
		and not exists(select 1 from dbo.license_external_reference_vault ex 
					where ex.license_id=v.license_id
					and   ex.license_category_id=v.license_category_id
					and   ex.license_category_id=234
					and   vt.vault_datacenter_name='US')

		--6) update-license_vault template
			exec [usp_sfdc_create_update_license_vault_template] @license_id=@license_id,@sfdc_template_name='update_license_vault'

end try
begin catch

	declare @response_code int,
			@DBName nvarchar(128)

	set @response_code = -200
	set @status = case when @status is null then 'error processing license_external_reference_vault insert'
						else @status end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_autorenewal_discount]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_autorenewal_discount]
(
    @discount_update_json NVARCHAR(MAX),
    @message VARCHAR(100) OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2024-10-22	psatish		ECOM-6086/US-3510091 Initial creation
	
	DESCRIPTION
	To save the Autorenewal discount information for the Zuora keycodes in the license_autorenewal_discount table. 
	Zuora applies the discount for the first renewal during the AR process, but it is not applicable during the renewal or upgrade flow.
		
	DEPENDENCY
	
	
	This procedure is initiated by the new Endpoint: add-discount

*/

AS
SET NOCOUNT ON;

BEGIN TRY
    DECLARE @license_id INT,
            @keycode VARCHAR(40),
            @license_distribution_method_code VARCHAR(5),
            @discount_start_date VARCHAR(50),
            @discount_end_date VARCHAR(50),
            @discount_type VARCHAR(50),
            @portal_disti_code VARCHAR(50),            
            @autorenewal_discount_type_id INT

    DECLARE @APP_CONFIG TABLE
    (
        distribution_method_code VARCHAR(4)
    );



    IF ISJSON(@discount_update_json) = 0
    BEGIN
        SET @message = 'Invalid JSON provided';
        RETURN;
    END;
    ELSE
    BEGIN
        SELECT @keycode = ISNULL(j.keycode, ''),
               @discount_type = ISNULL(j.discount_type, ''),
               @discount_start_date = j.discount_start_date,
               @discount_end_date = j.discount_end_date
        FROM
            OPENJSON(@discount_update_json)
            WITH
            (
                keycode VARCHAR(40) '$.keycode',
                discount_type VARCHAR(50) '$.discount_type',
                discount_start_date VARCHAR(50) '$.discount_start_date',
                discount_end_date VARCHAR(50) '$.discount_end_date'
            ) j;

        IF @keycode = ''
        BEGIN
            SET @message = 'Required parameters not provided';
            RETURN;
        END;
    END;


    IF @keycode <> ''
       AND @license_id IS NULL
    BEGIN

        SELECT @license_id = lc.license_id,
               @license_distribution_method_code = dm.license_distribution_method_code
        FROM dbo.license lc
            INNER JOIN dbo.license_distribution_method dm
                ON dm.license_distribution_method_id = lc.license_distribution_method_id
        WHERE lc.keycode = @keycode;

    END;

    IF @license_id IS NULL
    BEGIN
        SET @message = 'Invalid keycode';
        RETURN;

    END;

    SELECT @autorenewal_discount_type_id = autorenewal_discount_type_id
    FROM dbo.autorenewal_discount_type
    WHERE autorenewal_discount_type_description = @discount_type


    IF @autorenewal_discount_type_id IS NULL
    BEGIN
        SET @message = 'Invalid discount type';
        RETURN;

    END

    IF ISNULL(@discount_start_date,'')='' OR ISDATE(@discount_start_date) = 0
    BEGIN
        SET @message = 'Invalid discount start date';
        RETURN;

    END

    IF ISNULL(@discount_end_date,'')='' OR ISDATE(@discount_end_date) = 0
    BEGIN
        SET @message = 'Invalid discount end date';
        RETURN;

    END



    INSERT INTO @APP_CONFIG
    (
        distribution_method_code
    )
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f;

    SELECT @portal_disti_code
        = STUFF(
          (
              SELECT '/ ' + distribution_method_code FROM @APP_CONFIG FOR XML PATH('')
          ),
          1,
          2,
          ''
               );


    --insert the discount info into the license_autorenewal_discount
    IF EXISTS
    (
        SELECT 1
        FROM @APP_CONFIG 
a
        WHERE a.distribution_method_code = @license_distribution_method_code
    )
    BEGIN


        INSERT INTO dbo.license_autorenewal_discount
        (
            license_id,
            autorenewal_discount_type_id,
            discount_start_date,
            discount_end_date
        )
        VALUES
        (@license_id, @autorenewal_discount_type_id, @discount_start_date, @discount_end_date)


        SET @message = 'Discount details updated successfully';
        RETURN;

    END;

    ELSE
    BEGIN
        SET @message = 'Keycode is not associated with ' + @portal_disti_code + ' distribution method';
        RETURN;

    END;


END TRY
BEGIN CATCH

    SET @message = 'Failed to update the discount details';

    DECLARE @dbname NVARCHAR(128);
    SET @dbname = DB_NAME();
    EXEC usp_LogError @ErrorDB = @dbname;
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_autorenewal_opt_out]
-- =============================================================================

 CREATE   PROCEDURE [dbo].[usp_license_insert_license_autorenewal_opt_out]
(
    @keycode VARCHAR(40)
)

/*
    DATE        AUTHOR      REMARKS
    2012-10-24  esmart      Initial creation
    2016-05-02  mrobbins    added discount info to output
                            added look up in keycode alias table so alias keycodes can opt out
    2018-05-25  mrobbins    extended message_campaign_name
    2020-02-27  jnavarra    Block ineligible licenses
    2020-07-13  jnavarra    Include customer email and name in return data
    2020-09-09  jnavarra    New AR auto opt out rules
    2025-02-28  jberry      US-4429096 - Remove block for WIFI and Brightcloud licenses

    DESCRIPTION
    insert license_autorenewal_opt_out

	Dependencies:This procedure is called by PHP(Auto renewal opt out page)
*/

AS
    SET NOCOUNT ON

    BEGIN TRY

        DECLARE
            @response_code INT,
            @message VARCHAR(100)



        -- Log every request
        declare
            @license_id int = null,
            @license_category_id tinyint = null,
            @license_seats int = null,
            @status varchar(10) = null,
            @message_campaign_id int = null,
            @license_autorenewal_opt_out_id int

        insert into dbo.license_autorenewal_opt_out (requested_keycode, license_id, license_category_id, license_seats, status, message_campaign_id, insert_date)
        values (@keycode, @license_id, @license_category_id, @license_seats, @status, @message_campaign_id, getdate())

        -- Save ID and update the record later to fill in the blanks
        select @license_autorenewal_opt_out_id = scope_identity()



        -- Find license_id
        select @license_id = license_id
        from dbo.license with (nolock)
        where keycode = @keycode

        if @license_id is null
            begin
                -- Couldn't find the keycode in the license table, look for an alias
                select @license_id = license_id
                from dbo.license_keycode_alias with (nolock)
                where keycode_alias = @keycode
            end



        IF @license_id IS NULL 
            begin
                set @status = 'not found'
                SET @message = 'insert failed'
            END
        ELSE
            BEGIN
                -- Default. Set to this, the opt out action will occur.
                set @status = 'pending'



                -- Gather license details
                declare @is_business int

                select
                    @license_seats = isnull(s.license_seats,1),
                    @license_category_id = isnull(lcl.license_category_id, dbo.fn_GetLicenseCategoryId(@license_id)),
                    @is_business = case when l.product_line_id in (55, 300) then 1 else 0 end
                from dbo.license l with (nolock)
                    left join dbo.license_seat s with (nolock)
                        on s.license_id = l.license_id
                    left join dbo.license_category_license lcl with (nolock)
                        on lcl.license_id = l.license_id
                where l.license_id = @license_id

                declare @parent_license_id int = (select parent_license_id from dbo.license_parent with (nolock) where child_license_id = @license_id)

                declare @child_license_count int = (select count(*) from dbo.license_parent with (nolock) where parent_license_id = @license_id)

                declare @sibling_license_count int = (select count(*) from dbo.license_parent with (nolock) where parent_license_id = @parent_license_id)

                declare @is_parent bit = case when @child_license_count > 0 th
en 1 else 0 end

                declare @is_child bit = case when @parent_license_id is not null then 1 else 0 end

                declare @latest_order_item_id int = (select max(order_item_id) from dbo.order_item_license with (nolock) where license_id = @license_id)

                DECLARE @latest_order_is_sfdc INT = CASE WHEN EXISTS (
                    SELECT *
                    FROM dbo.order_item_license oil WITH (NOLOCK)
                        INNER JOIN dbo.order_item oi WITH (NOLOCK)
                            ON oi.order_item_id = oil.order_item_id
                        INNER JOIN dbo.order_header oh WITH (NOLOCK)
                            ON oh.order_header_id = oi.order_header_id
                        --inner join dbo.order_opportunity oo with (nolock)
                        --    on oo.order_header_id = oh.order_header_id
                        --inner join dbo.sfdc_opportunity_renewal sor with (nolock)
                        --    on sor.order_opportunity_id = oo.order_opportunity_id
                    WHERE oi.order_item_id = @latest_order_item_id AND oh.site_id = 'SFDC'
                ) THEN 1 ELSE 0 END
                


                --message campaigns
                DECLARE @message_platform_name VARCHAR(50) = 'AR_opt_out'
                DECLARE @message_campaigns TABLE (message_campaign_id INT, message_campaign_name VARCHAR(65), message_campaign_description VARCHAR(256))

                INSERT INTO @message_campaigns(message_campaign_id,message_campaign_name,message_campaign_description)
                EXEC usp_message_select_license_message_campaigns_platform @license_id, @message_platform_name

                SELECT @message_campaign_id = MAX(message_campaign_id) FROM @message_campaigns

                --check for existing discount if there is one - then just opt them out
                IF @message_campaign_id = 51
                    BEGIN
                        DECLARE @message_platform_id INT = (SELECT message_platform_id FROM message_platform WHERE massage_platform_name = @message_platform_name)

                        DECLARE @discount_count INT = (
                            SELECT COUNT(*) 
                            FROM license_cart_discount lcd
                                INNER JOIN message_campaign_cart_discount mccd
                                    ON lcd.cart_discount_id = mccd.cart_discount_id
                                INNER JOIN message_campaign mc
                                    ON mccd.message_campaign_id = mc.message_campaign_id
                                INNER JOIN message_campaign_platform mcp
                                        ON mc.message_campaign_id = mcp.message_campaign_id
                            WHERE license_id = @license_id 
                                and mcp.message_platform_id = @message_platform_id
                        )
                
                        if @discount_count > 0
                            begin
                                set @message_campaign_id = NULL
                            end	
                    end



                -- Make decisions. Changing the status will ultimately change the action that's taken by the PHP code that called this proc.

                -- License is being handled by SFDC
                if @latest_order_is_sfdc = 1
                    begin
                        set @status = 'sfdc'
                    END                

                -- License is consumer-child
                else if @is_business = 0 and @is_child = 1
                    begin
                        -- Go ahead, opt out
                        set @status = @status   -- Do nothing
                    end

                -- License is a business-parent
                else if @is_business = 1 and @is_parent = 1
                    begin
                        -- Go ahead, opt out
             
           set @status = @status   -- Do nothing
                    end

                -- License is a business-child (only child)
                else if @is_business = 1 and @is_child = 1 and @sibling_license_count = 1
                    begin
                        -- Opt out parent, instead
                        set @license_id = @parent_license_id
                    end

                -- Any remaining parent or child situations
                else if @is_parent = 1 or @is_child = 1
                    begin
                        set @status = 'prnt_chld'
                    end
            end



        -- Update license_autorenewal_opt_out with the data/decision from above
        update dbo.license_autorenewal_opt_out
            set license_id = @license_id,
                license_category_id = @license_category_id,
                license_seats = @license_seats,
                message_campaign_id = @message_campaign_id,
                status = @status
        where license_autorenewal_opt_out_id = @license_autorenewal_opt_out_id

        -- Return result
        -- Select the latest active email in the case of an error where this customer has multiple active email addresses
        select top(1) ar.license_autorenewal_opt_out_id, ar.license_id, ar.license_category_id, ar.license_seats,ar.message_campaign_id, ar.status, m.message_campaign_cart_discount_int, c.cart_discount_id, c.cart_discount_description, cu.first_name, cu.last_name, ce.customer_email
        from dbo.license_autorenewal_opt_out ar
            inner join dbo.license l with (nolock)
                on l.license_id = ar.license_id
            inner join dbo.customer cu with (nolock)
                on cu.customer_id = l.customer_id
            inner join dbo.customer_email ce with (nolock)
                on ce.customer_id = cu.customer_id and ce.email_status_id = 1
            left join dbo.message_campaign_cart_discount m
                on ar.message_campaign_id = m.message_campaign_id
            left join dbo.cart_discount c
                on m.cart_discount_id = c.cart_discount_id
        where ar.license_autorenewal_opt_out_id = @license_autorenewal_opt_out_id
        order by ce.customer_email_id desc

    end try
    begin catch

        set @response_code = -200
        set @message = case
            when @message is null then 'insert failed'
            else @message
        end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_capability]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_license_insert_license_capability]

(
	@license_id int, 
	@capability_id int, 
	@capability_type_id int, 
	@capability_activation_days int,
	@capability_activation_date datetime = null, 
	@capability_expiration_date datetime = null,
	@activation_days int = null
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2007-10-09	bjordan		Added Try/Catch

	DESCRIPTION
	Insert license_capability	
*/

begin try
	
	if (select count(*) from license_capability where license_id = @license_id and capability_id = @capability_id) > 0
		begin
		return
		end

	insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date)
	values (@license_id, @capability_id, @capability_type_id, @capability_activation_days, @capability_activation_date, @capability_expiration_date)

end try
begin catch
	
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_capability_audit]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_insert_license_capability_audit]

(
	@license_id int
)

/*	
	DATE		AUTHOR	REMARKS
	2006-10-05	esmart		Initial creation
	2007-10-09	bjordan		Added Try/Catch

	DESCRIPTION
	Insert license_capability_audit 	
*/

AS
begin try
	insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by)
	select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by
	from license_capability 
	where license_id = @license_id

end try
begin catch
	
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_cart]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_cart]

(
	@product_id int,
	@license_distribution_method_id int, 
	@quantity int,
	@response_code int output,
	@message varchar(100) output
)

AS
/*	
		DATE		AUTHOR		REMARKS
		2006-09-11	esmart		Initial creation.	
		2006-11-14	esmart		Add support for enterprise/sme keycode generator. Add support for SME multiple seat products.
		2006-12-05	esmart		Modify logic to better handle @seats and @quantity for SME products
		2007-02-08	esmart		Add activation step (2.2.6) for enterprise and SME license. capability_activation_date = license.insert_date
		2007-03-15	esmart		Add support for license_seat table
		2007-03-20	esmart		Check for linense_feature_license_distribution_method records
		2007-07-14	esmart		Add support for license_storage WISE
		2010-08-25	esmart		Add activation for premium services license
		2011-08-08	esmart		New enterprise support
		2011-10-25	esmart		SOHO support
		2011-12-16	esmart		Remove restriction of 9 quantity on consumer
		2012-01-12	esmart		Add WSA Enterprise product line to automatic activation
		2012-05-16	esmart		Add product_license_module support
		2012-07-02	esmart		Add Mobile Enterprise product line to automatic activation
		2012-08-09	acoffel		added SAEP handling
		2012-08-28	esmart		license_autorenewal_cycle support
		2013-01-11	esmart		Add ENTP for mobile enterprise
		2013-10-30	esmart		Partner specific disti method
		2014-01-27	esmart		Parent license support

		DESCRIPTION
		Create licenses for cart
	*/

	set nocount on

	declare @license_id int,
			@keycode varchar(40),
			@product_line_id int,
			@license_count int,
			@license_status_id int, 
			@license_type_id int,
			@license_keycode_type_id int,
			@max_daily_activations int,
			@max_child_licenses int,
			@license_expiration_date datetime,
			@insert_date datetime,
			@uses_keycode int,
			@seats int,
			@license_change_reason_id int,
			@license_features int,
			@product_seats int,
			@storage_gb int,
			@license_distribution_method_code char(4),
			@activation_date datetime,
			@license_category_id tinyint,
			@message_autorenewal_cycle_id tinyint,
			@capability_activation_date datetime, 
			@capability_expiration_date datetime, 
			@capability_id int

	set @license_count = 0
	set @insert_date = getdate()
	set @max_daily_activations = 30
	set @response_code = 0
	set @message = 'Success'
	set @license_change_reason_id = 6
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- @quanity	
		if @quantity <= 0
			begin
				set @response_code = -101
				set @message = 'Invalid quantity'
				return
			end
	-- @product_id
		select @response_code =  case when count(*) = 0 then -102 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid product_id' else '' end
		from product 
		where product_id = @product_id

		if @response_code < 0 	begin return end	

	-- @uses_keycode
		select @uses_keycode = uses_keycode
		from product
		where product_id = @product_id

		if @uses_keycode = 0
			begin

				return
			end

	-- @product_line_product
		select @response_code =  case when count(*) = 0 then -103 else 0	 end,
			@message = case when count(*) = 0 then 'Product does not have a product_line' else '' end
		from product_line_product 
		where product_id = @product_id


		if @response_code < 0 	begin return end

	-- product_capability
		select @response_code =  case when count(*) = 0 then -104 else 0	 end,
			@message = case when count(*) = 0 then 'Product does not have capabilities' else '' end
		from product_capability 
		where product_id = @product_id

		if @response_code < 0 	begin return end

	-- @license_distribution_method_id
		select @response_code =  case when count(*) = 0 then -105 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid license_distribution_method_id' else '' end,
			@license_distribution_method_code = license_distribution_method_code
		from license_distribution_method 
		where license_distribution_method_id = @license_distribution_method_id
		group by license_distribution_method_code

		if @response_code < 0 	begin return end

	-- @license_keycode_type_id 
		select @license_keycode_type_id = license_keycode_type_id
		from product
		where product_id = @product_id

	-- @product_line_id
		set @product_line_id = (select top 1 product_line_id
					from product_line_product 
					where product_id = @product_id)

	-- @seats
		select @seats = seats			
		from product_seat
		where product_id = @product_id

		if @seats in (10,25) and @product_line_id in (100,200)
			begin
			select @license_distribution_method_id = license_distribution_method_id,
					@license_distribution_method_code = license_distribution_method_code
			from license_distribution_method 
			where license_distribution_method_code = 'SOHO'
			end

	-- @license_category_id
		select @license_category_id = license_category_id			
		from product_license_category
		where product_id = @product_id

		if @license_category_id in (100,110,120) and @product_line_id in (300)
			begin
			select @license_distribution_method_id = license_distribution_method_id,
					@license_distribution_method_code = license_distribution_method_code
			from license_distribution_method 
			where license_distribution_method_code = 'FLEX'
			end
		if @license_category_id not in (100,110,120) and @product_line_id in (300,55)
			begin
			if (select license_distribution_method_code from license_distribution_method where license_distribution_method_id = @license_distribution_method_id) not in ('INSC','WRSM','SAEP') and
				(select count(*) from partner_license_distribution_method where license_distribution_method_id = @license_distribution_method_id) = 0
				begin
					select @license_distribution_method_id = license_distribution_method_id,
							@license_distribution_method_code = license_distribution_method_code
					from license_distribution_method 
					where license_distribution_method_code = 'ENTP'
				end
			end

	-- @license_features
		select @license_features = 
					case
						when count(*) > 0 then 1
						else 0
					end
		from license_feature_license_distribution_method
		where license_distribution_method_id = @license_distribution_method_id

	-- @storage_gb
		select @storage_gb = storage_gb
		from product_storage
		where product_id = @product_id
		
	-- @message_autorenewal_cycle_id
		select @message_autorenewal_cycle_id = message_autorenewal_cycle_id
		from product_autorenewal_cycle
		where product_id = @product_id

	--select seats = @seats, product_line_id = @product_line_id

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Generate licenses
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) create temp table to store license_ids and keycodes
	CREATE TABLE [dbo].[#temp_license] (
		[license_id] [int] NOT NULL ,
		[keycode] [varchar] (40) NOT NULL 
	) ON [PRIMARY]

	-- 2.1) check quantity and set parameters

	if @product_line_id = 13
		-- 2.1.1) SME
		begin
			set @product_seats = @seats
			set @max_child_licenses = 

					case 
						when @seats is null then @quantity
						else @seats
					end
			set @max_daily_activations = 
						case
							when @seats > 30 then @seats
							else 30
						end
			set @seats = 
					case 
						when @seats is null then @quantity
						else @seats
					end
			set @quantity = 
					case 
						when @product_seats is null then 1
						else @quantity
					end
			set @license_type_id = 5
			set @license_status_id = 1 
			set @license_expiration_date = null		
		end
	else if @product_line_id = 11
		-- 2.1.2) Enterprise
		begin
			set @max_child_licenses = @quantity
			set @seats = @quantity
			set @max_daily_activations = 
						case
							when @quantity > 30 then @quantity
							else 30
						end
			set @quantity = 1
			set @license_type_id = 4
			set @license_status_id = 1 
			set @license_expiration_date = null
		end
	else if @product_line_id in (300,55)
		-- 2.1.2) Enterprise
		begin
			set @max_child_licenses = @quantity
			set @seats = @quantity
			set @max_daily_activations = @quantity
			set @quantity = 1
			set @license_type_id = case when @license_keycode_type_id = 3 then 2 else 4 end
			set @license_status_id = 1 
			set @license_expiration_date = null
		end
	else 
		-- 2.1.3) Consumer/OEM
		begin		
		
		set @license_type_id = case when @license_keycode_type_id = 3 then 2 else 1 end
		set @license_status_id = 0 
		set @max_child_licenses = null
		set @license_expiration_date = null
		
--		if @quantity >= 10 and @license_distribution_method_code <> 'OPRS'
--			begin
--				set @max_child_licenses = @quantity
--				set @max_daily_activations = 
--						case
--							when @quantity > 30 then @quantity
--							else 30
--						end
--				set @quantity = 1
--				set @license_type_id = 2
--				set @license_status_id = 1 
--				set @license_expiration_date = null
--			end
--		else
--			begin
--				set @license_type_id = 1
--				set @license_status_id = 0 
--				set @max_child_licenses = null
--				set @license_expiration_date = null
--			end
		end

	-- 2.2) Create licenses		
	while @license_count < @quantity

		begin -- begin while

			-- 2.2.1) create keycode
			if @license_keycode_type_id in (1,3)
				begin
					exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					if @response_code < 0
						begin
						goto backout
						return
						end
					--select keycode = @keycode
				end
			else if @license_keycode_type_id = 2
				begin 
					exec usp_license_generate_enterprise_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
					if @response_code < 0
						begin
						goto backout
						return
						end
				end
			else 
				begin
					set @keycode = ''
				end

			-- 2.2.2) insert license
			insert into license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses,license_expiration_date, insert_date, insert_by, modified_date, modified_by)
			values (@keycode, @product_line_id, @license_status_id, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, @max_daily_activations, @max_child_licenses, @license_expiration_date, @insert_date, system_user, @insert_date, system_user)

			if @@error <> 0 
				begin
					set @response_code = -222
					set @message = 'General SQL error - insert license'
					goto backout
				return
				end

			set @license_id = scope_identity()

			-- 2.2.3 insert license_capability
			insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modifi
ed_date, modified_by)
			select 	@license_id, 
				capability_id, 
				capability_type_id, 
				capability_activation_days,
				insert_date = @insert_date,
				insert_by = system_user,
				modified_date = @insert_date,
				modified_by = system_user		
			from product_capability c
			where product_id = @product_id

			if @@error <> 0 
				begin
					set @response_code = -223
					set @message = 'General SQL error - insert license_capability'
					goto backout
				return
				end

			-- 2.2.4 insert license_id and keycode into #temp_license
			insert into #temp_license (license_id, keycode)
			values (@license_id, @keycode)

			-- 2.2.5 increment license_count
			set @license_count = @license_count + 1

			-- 2.2.6 activate enterprise and sme licenses
			if @product_line_id in (11,13,300,55)
				begin
					insert into license_activation (license_id, guid)
					values (@license_id, '')

					-- 2.2.6.1) check if license_status is inactive. change status to active and update activation and exirpation dates on the capabiltes

					-- add existing data to license_history
					insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
					select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, getdate(), system_user
					from license
					where license_id = @license_id					

					-- update license
					update license
					set license_status_id = 1,
						modified_date = getdate(),
						modified_by = system_user
					where license_id = @license_id

					-- 2.2.6.2) update license activations that need activation and expiration date

					set @activation_date = getdate()		

					insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
					select  license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by,@license_change_reason_id, getdate(), system_user,
						days_used = 0, 
						days_remaining = 0, 
						days_added = 0, 
						days_new = capability_activation_days, 
						days_contiguous = capability_activation_days
					from license_capability
					where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4

					update license_capability
					set capability_activation_date = 
							case
								when capability_activation_days is null then null
								else @activation_date
							end,
						capability_expiration_date =
							case
								when capability_activation_days is null then null
								else dateadd(dd,capability_activation_days,@activation_date)
							end,
						modified_date = getdate(),
						modified_by = system_user
					where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4
				end

			-- 2.2.7 professional services are activated when created
			if @product_line_id in (18,19)
				begin
					-- 2.2.7.1) check if license_status is inactive. change status to active and update activation and exirpation dates
 on the capabiltes

					-- add existing data to license_history
					insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
					select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, getdate(), system_user
					from license
					where license_id = @license_id					

					-- update license
					update license
					set license_status_id = 1,
						modified_date = getdate(),
						modified_by = system_user
					where license_id = @license_id

					-- 2.2.7.2) update license activations that need activation and expiration date

					set @activation_date = getdate()		

					insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
					select  license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by,@license_change_reason_id, getdate(), system_user,
						days_used = 0, 
						days_remaining = 0, 
						days_added = 0, 
						days_new = capability_activation_days, 
						days_contiguous = capability_activation_days
					from license_capability
					where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4

					update license_capability
					set capability_activation_date = 
							case
								when capability_activation_days is null then null
								else @activation_date
							end,
						capability_expiration_date =
							case
								when capability_activation_days is null then null
								else dateadd(dd,capability_activation_days,@activation_date)
							end,
						modified_date = getdate(),
						modified_by = system_user
					where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4
				end

			-- 2.2.8 insert license_seat records
			if @seats is not null
				begin
				insert into license_seat (license_id, license_seats)
				values (@license_id, @seats)

				if @@error <> 0 
					begin
						set @response_code = -227
						set @message = 'General SQL error - insert license_seat'
						goto backout
					return
					end				
				end

			-- 2.2.9 insert license_feature_license_distribution_method records
			if @license_features = 1
				begin

				insert into license_feature_license (license_feature_id, license_id)
				select license_feature_id, @license_id
				from license_feature_license_distribution_method
				where license_distribution_method_id = @license_distribution_method_id

				if @@error <> 0 
					begin
						set @response_code = -228
						set @message = 'General SQL error - insert license_feature_license_distribution_method'
						goto backout
						return
					end				
				end

			-- 2.2.10 insert license_storage record
			if @storage_gb is not null
				begin
				exec usp_license_insert_license_storage @license_id, @storage_gb, NULL, @response_code output, @message output
				
				if @response_code < 0
					begin
						goto backout
						return
					end
				end
			

			-- 2.2.11 insert lic
ense_storage record
			--select @license_category_id = license_category_id from product_license_category where product_id = @product_id

			if @license_category_id is not null
				begin
				select @capability_id = base_capability_id from license_category where license_category_id = @license_category_id

				select @capability_activation_date = capability_activation_date, @capability_expiration_date = capability_expiration_date
				from license_capability
				where license_id = @license_id and capability_id = @capability_id
				
				insert into license_category_license (license_id, license_category_id, start_date, end_date)				
				values (@license_id, @license_category_id, @capability_activation_date, @capability_expiration_date)		
				if @response_code < 0
					begin
						goto backout
						return
					end
				end
				
			-- 2.2.12 license_module
			if (select COUNT(*) from product_license_module where product_id = @product_id) > 0
				begin
				insert into license_module_license(license_id,license_module_id,license_module_type_id)
				select @license_id, license_module_id, license_module_type_id
				from product_license_module 
				where product_id = @product_id
					
				if @response_code < 0
					begin
						goto backout
						return
					end
				end		
				
			-- 2.2.13) usp_license_insert_license_cart
			if @message_autorenewal_cycle_id is not null
				begin
				insert into license_autorenewal_cycle(license_id,message_autorenewal_cycle_id)
				values(@license_id,@message_autorenewal_cycle_id)				
				end

		end -- end while

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) OUTPUT
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	backout:
		if @response_code < 0
			begin
				delete from license_storage where license_id in (select license_id from #temp_license)
				delete from license_capability where license_id in (select license_id from #temp_license)
				delete from license_seat where license_id in (select license_id from #temp_license)
				delete from license_feature_license where license_id in (select license_id from #temp_license)
				delete from license where license_id in (select license_id from #temp_license)
				drop table #temp_license
				return
			end		


	select keycode
	from #temp_license
	where keycode <> ''

	drop table #temp_license






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_cart_discount]
-- =============================================================================

 CREATE PROCEDURE [dbo].[usp_license_insert_license_cart_discount]

(
		@license_id int, 
		@cart_discount_id int, 
		@start_date datetime = null, 
		@end_date datetime = null			
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-24	esmart		Initial creation

	DESCRIPTION
	insert license_cart_discount
*/

AS
	set nocount on				

	declare @license_cart_discount_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @start_date is null
		begin
		select @start_date = getdate()
		end

	insert into license_cart_discount(license_id, cart_discount_id, start_date, end_date)
	values(@license_id, @cart_discount_id, @start_date, @end_date)
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_contract]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_contract]
	@license_contract_json varchar(max),
	@license_contract_source_caller varchar(50) = null

/*	
	DATE		AUTHOR		REMARKS
	2019-03-28	cnovac		Initial creation.
	2019-06-12	cnovac		Took out check to make license_contract_transaction a required entity
	2019-07-12	cnovac		Updated query on setting license_contract_status_id = 2, --Transaction record that was refunded
	2019-07-30	cnovac		Took out lct.effective_object_transaction_type_id = 2 from setting obsolete records since regular orders can pull date back if going from utility to annual for example
	2019-08-14	cnovac		Updated logic to use @license_contract_object_insert so that it can handle ugrage/renewal correctly when setting lc.license_contract_status_id = 5
	2019-10-25	cnovac		Updated code to use new variable for loop - @start2 and @license_contract_refunded
	2019-11-04	cnovac		Removed license_start_date_epoch and license_end_date_epoch
	2019-12-12	cnovac		Updated logic to set license_contract_status_id = 2 and added logic to align child records with parents end date on full refunds
	2020-02-12	cnovac		Added logic for handling license_status_id and setting license_contract_status_id to use that if passed in
	2020-03-05	cnovac		Updated logic where license_contract_status_id was being set to fix issue where future dated rows where being set to 4

*/
as

set nocount on

begin try

	declare @license_contract_json_id int,
			@current_date_time datetime = getdate(),
			@rowcount_json int,
			@rowcount_lco int,
			@rowcount_refund int,
			@start int = 1,
			@is_full_refund bit,
			@keycode varchar(50),
			@license_category_name varchar(10),
			@license_end_date date,
			@license_service_json varchar(max),
			@license_service_type_name varchar(50) = 'site_update',
			@is_license_enable_call bit = 0
	declare @contract_json table (id int identity (1,1), [key] int, value varchar(max))
	declare @contract_transaction table (license_contract_transaction_id int, contract_transaction_type_index int)
	declare @license_contract_object table (license_id int, license_category_id tinyint, license_status_id tinyint, license_category_type_id int, originating_license_contract_id int, license_contract_transaction_id int, originating_license_contract_transaction_id int, license_start_date date, license_end_date date, license_contract_original_order_header_id int, license_contract_refunded_order_header_id int, is_full_refund bit)
	declare @license_contract_object_insert table (id int identity (1,1), license_contract_id int, license_id int, license_category_id tinyint, license_contract_status_id int, originating_license_contract_id int, license_start_date date, license_end_date date)
	declare @license_contract_refunded table (originating_license_contract_id int)
	declare @license_contract_refunded_child table (id int identity (1, 1), keycode varchar(50), license_category_name varchar(10), license_end_date date)

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_contract_json
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--log the json first and return the id back
	insert into license_contract_json (license_contract_json, license_contract_source_caller, insert_date)
	values (@license_contract_json, @license_contract_source_caller, @current_date_time)

	set @license_contract_json_id = scope_identity()

	-------------------------------------------------------------------------------------------------------------------------
---------------------------------------
	-- insert into license_contract_transaction
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--now basically seperate the number of JSON license objects
	insert into @contract_json ([key], value)
	select [Key], Value
	from openjson(@license_contract_json)
	order by [Key]

	select @rowcount_json = @@ROWCOUNT

	--insert the rows which have order_item_id/license_service_id/trial_registration_id in it
	insert into license_contract_transaction (license_contract_json_id, contract_transaction_type_index, effective_object_transaction_type_id, contract_transaction_type_value, insert_date)
	output Inserted.license_contract_transaction_id, Inserted.contract_transaction_type_index into @contract_transaction(license_contract_transaction_id, contract_transaction_type_index)
	select @license_contract_json_id, ej.[key], eott.effective_object_transaction_type_id, ej2.Value, @current_date_time
	from @contract_json ej cross apply openjson(ej.value) ej2
	inner join effective_object_transaction_type eott on ej2.[Key] = eott.effective_object_transaction_type_name collate Latin1_General_BIN2
	order by ej.[key]

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into @license_contract_object
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--now loop through each JSON license objects and pull all the elements and put in @license_contract_object
	while @rowcount_json >= @start
	begin
		insert into @license_contract_object (license_id, license_category_id, license_status_id, license_category_type_id, originating_license_contract_id, license_contract_transaction_id, originating_license_contract_transaction_id, license_start_date, license_end_date, license_contract_original_order_header_id, license_contract_refunded_order_header_id, is_full_refund)
		select json_value(ej.value, '$.license_id'), json_value(ej.value, '$.license_category_id'), json_value(ej.value, '$.license_status_id'), json_value(ej.value, '$.license_category_type_id'), json_value(ej.value, '$.originating_license_contract_id'), et.license_contract_transaction_id,
		json_value(ej.value, '$.originating_license_contract_transaction_id'), json_value(ej.value, '$.license_start_date'), json_value(ej.value, '$.license_end_date'), json_value(ej.value, '$.license_contract_original_order_header_id'),
		json_value(ej.value, '$.license_contract_refunded_order_header_id'), json_value(ej.value, '$.is_full_refund')
		from @contract_json ej
		left join @contract_transaction et on ej.[key] = et.contract_transaction_type_index
		where ej.id = @start
		and json_value(ej.value, '$.license_start_date') is not null
		and json_value(ej.value, '$.license_end_date') is not null
		and json_value(ej.value, '$.license_category_type_id') is not null

		set @start = @start + 1
	end

	select @rowcount_lco = (select count(*) from @license_contract_object)

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- look for all exceptions now and return out of proc if you hit any
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--this means that either the start_date or end_date or license_category_type_id on license was not set in JSON
	if @rowcount_json != @rowcount_lco
	begin
		insert into license_contract_exceptions (license_contract_exception_reason_id, license_contract_json_id, insert_date)
		select 2, @license_contract_json_id, @current_date_time

		return
	
end

	--this means there was already a row in license_contract for same license_id/category and originating_license_contract_id wasn't passed into JSON
	insert into license_contract_exceptions (license_contract_exception_reason_id, license_contract_json_id, insert_date)
	select distinct 3, @license_contract_json_id, @current_date_time
	from @license_contract_object lco
	cross apply fn_license_select_license_contract_table(lco.license_id, default, 'all') lc
	where lc.license_category_id = lco.license_category_id
	and lco.originating_license_contract_id is null

	if @@ROWCOUNT > 0
		return

	--this means there is a full refund, but order_header_id refunded does not match correspending order_header_id from fn_license_select_license_contract_table
	insert into license_contract_exceptions (license_contract_exception_reason_id, license_contract_json_id, insert_date)
	select distinct 4, @license_contract_json_id, @current_date_time
	from @license_contract_object lco
	where lco.is_full_refund = 1 
	and lco.originating_license_contract_transaction_id is not null --this is in where clause because I don't want to fail refunds on licenses that were backfilled and don't have license_contract_transaction_id yet
	and isnull(lco.license_contract_original_order_header_id, '') != isnull(lco.license_contract_refunded_order_header_id, '')

	if @@ROWCOUNT > 0
		return

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- update source caller if an enable or disable is done explicitly; this is more just for debugging
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	update license_contract_json
	set license_contract_source_caller = license_contract_source_caller + iif(lco.license_status_id = 1, ' - enable', ' - disable'),
		@is_license_enable_call = iif(lco.license_status_id = 1, 1, 0)
	from @license_contract_object lco
	cross apply fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
	where license_contract_json_id = @license_contract_json_id
	and lco.license_status_id is not null --only time this is passed into JSON is in usp_license_service_update_license
	and lco.license_status_id != fn.license_contract_status_id

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into license_contract
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	--insert the data into license_contract from the temp table (this means there are no exceptions)
	insert into license_contract (license_id, license_category_id, license_category_type_id, originating_license_contract_id, license_contract_transaction_id, license_contract_status_id, license_start_date, license_end_date, modified_date, insert_date)
	output Inserted.license_contract_id, Inserted.license_id, Inserted.license_category_id, Inserted.license_contract_status_id, Inserted.originating_license_contract_id, Inserted.license_start_date, Inserted.license_end_date into @license_contract_object_insert(license_contract_id, license_id, license_category_id, license_contract_status_id, originating_license_contract_id, license_start_date, license_end_date)
	select lco.license_id, lco.license_category_id, lco.license_category_type_id, lco.originating_license_contract_id, lco.license_contract_transaction_id, isnull(lco.license_status_id, 1), lco.license_start_date, lco.license_end_date, @current_date_time, @current_date_time
	from @license_contract_object lco
	order by lco.license_id, lco.license_category_id, lco.license_end_date

	------------------------------------------------
----------------------------------------------------------------------------------------------------------------
	-- update license_contract license_contract_status_id column
	----------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @is_full_refund = is_full_refund
	from @license_contract_object

	if @is_full_refund = 1
	begin

		update lc
		set lc.license_contract_status_id = 3, --Full refund transaction
			lc.modified_date = @current_date_time
		from @license_contract_object_insert lco_temp
		inner join license_contract lc on lc.license_contract_id = lco_temp.license_contract_id

		update lc
		set lc.license_contract_status_id = 2, --Transaction record that was refunded
			lc.modified_date = @current_date_time
		output Inserted.originating_license_contract_id into @license_contract_refunded(originating_license_contract_id)
		from @license_contract_object_insert lco_temp
		inner join license_contract lc on lc.license_contract_id = lco_temp.originating_license_contract_id

		update lc
		set lc.license_contract_status_id = 2, --Transaction record that was refunded; this use case is an upgrade/renew where the originating_license_contract_id is the same, so we need to mark both positive trans as 2
			lc.modified_date = @current_date_time
		from @license_contract_refunded lcr
		inner join license_contract lc on lc.originating_license_contract_id = lcr.originating_license_contract_id
		where lc.license_contract_status_id = 1 --Transaction record

		update lc
		set lc.license_contract_status_id = 2, --Transaction record that was refunded; mark any other records as 2 that end on same end date as refund if done by license service (like end date change or license create call)
			lc.modified_date = @current_date_time
		from @license_contract_object_insert lco_temp
		inner join license_contract lc on lc.license_id = lco_temp.license_id
		inner join license_contract_transaction lct on lct.license_contract_transaction_id = lc.license_contract_transaction_id
		where lc.license_category_id = lco_temp.license_category_id
		and lc.license_end_date = lco_temp.license_end_date
		and lc.license_contract_status_id = 1 --Transaction record
		and lct.effective_object_transaction_type_id = 2 --license_service_id

		--this check is to make sure the child records end date matches the new parents end date
		insert into @license_contract_refunded_child (keycode, license_category_name, license_end_date)
		select l.keycode, lc.license_category_name, lco.license_end_date
		from @license_contract_object lco
		inner join @license_contract_object lco2 on lco2.license_category_id = lco.license_category_id and lco2.license_category_type_id = lco.license_category_type_id
		cross apply fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') parent
		cross apply fn_license_select_license_contract_table(lco2.license_id, lco2.license_category_id, 'max_row') child
		inner join license l on l.license_id = lco2.license_id
		inner join license_category lc on lc.license_category_id = lco2.license_category_id
		where lco.license_contract_refunded_order_header_id is not null
		and lco2.license_contract_refunded_order_header_id is null
		and parent.license_end_date != child.license_end_date

		select @rowcount_refund = @@ROWCOUNT
		set @start = 1

		while @start <= @rowcount_refund
		begin

			select @keycode = null, @license_category_name = null, @license_end_date = null

			select @keycode = keycode, @license_category_name = license_category_name, @license_end_date = license_end_date
			from @license_contract_refunded_child
			where id = @start

			select @license_service_json = 
			(select @keycode as keycode, @license_service_type_name as account_name,
				(select @license_category_name as license_category_name, @license_end_date as expiration_date for json
 path) license_category
			for json path, without_array_wrapper)

			if @license_service_json is not null
			begin
				exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @license_service_json, @return_license_service_id = 0
			end

			set @start = @start + 1

		end

	end
	else if @is_license_enable_call = 1
	begin

		update lc
		set lc.license_contract_status_id = 1, --basically mark all future records which are already marked as 'obsolete (5)' as 'transaction (1)' if we detected that an enable was triggered
			lc.modified_date = @current_date_time
		from @license_contract_object_insert lco_temp
		inner join license_contract lc on lc.license_id = lco_temp.license_id
		where lc.license_category_id = lco_temp.license_category_id
		and lc.license_contract_status_id = 5 --only look at obsolete rows to update
		and lco_temp.license_contract_status_id = 1 --indicates that it's enabled
		and lco_temp.license_start_date = lco_temp.license_end_date --only if the start and end dates passed in are equal, do we want enable future rows back to what they were.
		and lco_temp.license_end_date < lc.license_end_date

	end
	else
	begin

		update lc
		set lc.license_contract_status_id = 5, --Obsolete record due to end date being pulled back;  this implies the new row's end_date is less than the end date of a row(s) that came before it
			lc.modified_date = @current_date_time
		from @license_contract_object_insert lco_temp
		cross apply fn_license_select_license_contract_table(lco_temp.license_id, lco_temp.license_category_id, 'all') fn --this join is there so we don't update a row which is deleted or refunded which function will weed out
		inner join license_contract lc on lc.license_contract_id = fn.license_contract_id
		where fn.license_contract_status_id = 1
		and lco_temp.license_contract_id > lc.license_contract_id
		and lco_temp.license_end_date < lc.license_end_date

		update lc
		set lc.license_contract_status_id = 6, --Obsolete record due to newer record created with same end date as another record wth later start date
			lc.modified_date = @current_date_time
		from @license_contract_object_insert lco_temp
		cross apply fn_license_select_license_contract_table(lco_temp.license_id, lco_temp.license_category_id, 'all') fn --this join is there so we don't update a row which is deleted or refunded which function will weed out
		inner join license_contract lc on lc.license_contract_id = fn.license_contract_id
		where fn.license_contract_status_id = 1
		and lco_temp.license_contract_id > lc.license_contract_id
		and lco_temp.license_end_date = lc.license_end_date
		and lco_temp.license_start_date < lc.license_start_date

	end

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_license_insert_license_contract'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_distribution_method]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_insert_license_distribution_method]

(
	@license_distribution_method_code  char(4), 
	@license_distribution_method_name varchar(50),
	@channel_id int,
	@license_distribution_method_active tinyint = 1,
	@distribution_business_unit_id tinyint = NULL,
	@distribution_geography_id tinyint = NULL,
	@distribution_class_id tinyint = NULL,
	@distribution_account_id tinyint = NULL,
	@best_buy_s2 tinyint = null,
	@response_code int output,
	@message varchar(100) output,
    @auto_extend TINYINT = NULL,
    @churn_days_add INT = NULL,
    @churn_days_measure INT = NULL,
    @do_not_send_email TINYINT = NULL,
	@insert_by varchar(20) =NULL,
	@seat_count_enforcement TINYINT = 0,
	@license_category_id INT = 100  ---currently it is WSAV only in phase 1 
)

AS

/*	
		DATE			AUTHOR		REMARKS
		2006-12-15		esmart		Initial creation.	
		2010-07-06		dsmelker	Added license_distribution_method_active
		2013-09-04		esmart		Add business unit	
		2024-05-12      spatil6     consumer code creation added two options Do not send emiail and auto extend functionality 
		2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968
		2026-02-19      spatil6    ve: 5095466 adding seat_count_enforcement column
		
		DESCRIPTION
		Insert license distribution method and channel
*/


	set nocount on

	declare @license_distribution_method_id int

	set @response_code = 0
	set @message = 'Successfully inserted license distribution method'


	IF @insert_by IS NULL
    BEGIN
        SELECT @insert_by = SUSER_SNAME()
    END
	
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) Check distribution method code to see if it already exists
	select @response_code =  case when count(*) = 1 then -100 else 0	 end,
		@message = case when count(*) = 1 then 'License distribution method code already exists' else '' end
	from license_distribution_method 
	where license_distribution_method_code = @license_distribution_method_code

	if @response_code < 0 	
		begin 
			return 
		end	
	
	-- 1.1) Check channel_id
	select @response_code =  case when count(*) = 0 then -110 else 0	 end,
		@message = case when count(*) = 0 then '' else '' end
	from channel 
	where channel_id = @channel_id

	if @response_code < 0 	
		begin 
			return 
		end	

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Insert license_distribution_method 
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_distribution_method (license_distribution_method_code, license_distribution_method_name,license_distribution_method_active)
	values (@license_distribution_method_code, @license_distribution_method_name,@license_distribution_method_active)

	if @@error <> 0 
		begin
			set @response_code = -200
			set @message = 'General SQL error - insert license_distrib
ution_method'
			
		return
		end

	set @license_distribution_method_id = scope_identity()

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) Insert license_distribution_method_channel
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_distribution_method_channel(license_distribution_method_id, channel_id,distribution_business_unit_id,distribution_geography_id,distribution_class_id,distribution_account_id)
	values (@license_distribution_method_id, @channel_id,@distribution_business_unit_id,@distribution_geography_id,@distribution_class_id,@distribution_account_id)

	if @@error <> 0 
		begin
			set @response_code = -300
			set @message = 'General SQL error - insert license_distribution_method_channel'
			
		return
		end

	
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4) subscription
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @best_buy_s2 = 1
		begin
		insert into subscription_distribution_method(license_distribution_method_id)
		values(@license_distribution_method_id)
		end
	IF @auto_extend = 1
	BEGIN
		INSERT INTO dbo.license_distribution_method_churn
		(
		    license_distribution_method_id,
		    churn_days_add,
		    churn_days_measure,
		    insert_date,
		    insert_by
		)
		VALUES
		(@license_distribution_method_id, @churn_days_add, @churn_days_measure, GETDATE(), DEFAULT);
	END;


	IF @do_not_send_email = 1
	BEGIN
		INSERT INTO dbo.message_campaign_license_distribution_method
		(
		    message_campaign_id,
		    license_distribution_method_id,
		    inclusive,
			insert_by,
			modified_by
		)
		SELECT DISTINCT
		       mc.message_campaign_id,
		       @license_distribution_method_id,
		       0,
			   @insert_by,
			   @insert_by
		FROM dbo.message_campaign mc
		    INNER JOIN dbo.message_campaign_license_distribution_method mcldm
		        ON mcldm.message_campaign_id = mc.message_campaign_id
		WHERE mcldm.inclusive = 0
		      AND mc.message_campaign_class_id = 4
		      AND mcldm.license_distribution_method_id <> @license_distribution_method_id;

	END;
	
	-----------------------------------------------------------------------
    -- Seat Count Enforcement Insert (NEW LOGIC)
    -----------------------------------------------------------------------
     INSERT INTO dbo.product_line_license_seat_distribution
    (
        product_line_id,
        license_distribution_method_id,
        license_category_id,
        seat_count_enforcement
    )
    VALUES
    (
        100,  -- WSAV product_line_id (update if different)
        @license_distribution_method_id,
        ISNULL(@license_category_id, 100),
        @seat_count_enforcement
    );


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_distribution_method_module]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_distribution_method_module]

(
	@license_distribution_method_id int,
	@license_module_id tinyint,
	@license_module_type_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-15	esmart		Initial creation.

	DESCRIPTION
	insert license_distribution_method_module
*/

AS
	set nocount on				

	declare @license_distribution_method_module_id int,
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) delete
	delete from license_distribution_method_module
	where license_distribution_method_id = @license_distribution_method_id and license_module_id = @license_module_id

	-- 1.2) insert
	insert into license_distribution_method_module(license_distribution_method_id, license_module_id,license_module_type_id)
	values(@license_distribution_method_id,@license_module_id,@license_module_type_id)

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_migration]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_insert_license_migration]

(
	@migration_keycodes varchar(max),
	@product_id int, 
	@seats int, 
	@start_date datetime, 
	@end_date datetime, 
	@customer_email varchar(100),
	@license_distribution_method_id int = null,
	@new_keycode varchar(40),
	@modified_by varchar(20) = NULL
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-11-05		esmart			Initial creation
	2016-04-28		esmart			autobilling and license_parent updates
	2016-10-13		acoffel			suppress responses from usp_license_update_license_capability_load and usp_license_update_license_capability_CSI
	2016-12-01		acoffel			insert child keys into license_check_update_license
	2018-05-04		rvinoche		update order_item_license with new parent license
	2018-09-07		rvinoche		Allow past record updates when calling usp_license_update_license_attribute_license
	2018-09-26		rvinoche		change sky_template_id to RegisterAndMigrate API
	2019-02-26		rvinoche		refactor to insert new license into license_effective_object and transfer license_cart_discount
	2019-04-03		cnovac			Took out reference to license_attribute_license
	2019-04-22		rvinoche		Backfill license_capability_history.activation_date for messaging
	2019-05-08		abelenkiy		Added support for license_usage_pricing_value in effective_object
	2019-06-21		esmart			add @company_id_input
	2019-07-16		jnavarra		Refactor, use usp_license_update_license_attribute_license, and add handling for partner_billing
	2019-09-06		cnovac			Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2019-09-20		abelenkiy		Added logic to prevent duplicate inserts to order_item_license (section 4.6)
	2019-11-07		abelenkiy		Added support for license_parent in effective_object (section 5)
	
	DESCRIPTION
	update license migration
*/

AS
	
	set nocount on			

	declare
		@customer_id int, 
		@license_id int, 
		@months int, 
		@external_keycode varchar(40),
		@sky_template_id tinyint, 
		@process_date datetime,
		@order_type_group_id int, 
		@order_item_id int, 
		@effective_date datetime,
		@license_attribute_id int, 
		@license_attribute_license_value int,
		@cancel_license_attribute_license_value int,
		@capability_expiration_date datetime,
		@cancel_license_id int,
		@days int,
		@sky_license_id INT,
		@first_name nvarchar(225),
		@last_name nvarchar(225),
		@company_name nvarchar(255),
		@company_type_name varchar(20),
		@phone_number varchar(64),
		@address_1 nvarchar(255),
		@address_2 nvarchar(255),
		@city nvarchar(130),
		@state nvarchar(2),
		@postal_code nvarchar(32),
		@country varchar(75),
		@vendor_id int,
		@vendor_customer_code varchar(100),
		@partner_id int,
		@opt_in int,
		@salesforce_account_id char(18),
		@salesforce_contact_id char(18),
		@transaction_user varchar(20),
		@customer_id_input int,
		@sql_string varchar(4000),
		@db_name varchar(100) = db_name(),
		@company_id_input int,
		@message varchar(100),
		@response_code int,
		@license_parent_json nvarchar(max)

	declare @keycode table (keycode varchar(40))
	declare @keycodes table (license_id int, keycode varchar(40), license_attribute_license_value int)
	declare @partner_licenses table (partner_license_id int)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @months = datediff(mm,@start_date,@end_date), @sky_template_id = 5,
 @process_date = dateadd(mi,5,getdate()), @effective_date = getdate()

	if @modified_by is null
		begin
		select @modified_by = suser_name()
		end

	-- 1.1) @license_distribution_method_id
	if @license_distribution_method_id is null 
		begin
		select @license_distribution_method_id = 147
		end

	-- 1.2) @customer_id
	select @customer_id = max(customer_id) 
	from dbo.customer_email
	where customer_email = @customer_email and email_status_id = 1

	-- 1.2.1) insert customer
	if @customer_id is null
		begin
		--print '1.2.1 insert customer'
		select @transaction_user = 'license_migration'
		exec usp_customer_insert_customer_service @customer_email,@first_name,@last_name,@company_name,@company_type_name,@phone_number,@address_1,@address_2,@city,@state,@postal_code,@country,@vendor_id,@vendor_customer_code,@partner_id,@opt_in,@salesforce_account_id,@salesforce_contact_id,@transaction_user,@customer_id_input,@company_id_input,@customer_id output
		end


	--select customer_id = @customer_id

	--return
	
	-- 1.3) @keycodes
	insert into @keycodes (license_id,keycode)
	select l.license_id,l.keycode
	from dbo.fn_string_to_table(@migration_keycodes) f
	inner join dbo.license l
		on f.string_value = l.keycode

	-- 1.4) license_attribute_license_value
	update k
	set license_attribute_license_value = dbo.fn_license_select_effective_object_element(k.license_id, lcl.license_category_id, 'license_attribute_license_value', @effective_date)
	from @keycodes k
	inner join license_category_license lcl on lcl.license_id = k.license_id

	-- 1.5) duplicate migration //PROBLEM HERE?? HOW OFTEN ARE THERE MULTIPLE LICENSES? the @license_id is then arbitrary
	select @license_id = max(m.new_license_id)
	from dbo.license_migration m
	inner join @keycodes k
		on m.original_license_id = k.license_id

	if @license_id is not null
		begin
		select @new_keycode = keycode from dbo.license where license_id = @license_id
		end
	else
		begin
		select @license_id = license_id from dbo.license where keycode = @new_keycode
		end
	
	if @license_id is null and @new_keycode is not null
		begin
		--print 'no matching new license'
		return
		end



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert GSM keycode
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) new migration keycode
	if @new_keycode is null
		begin
		-- 2.1.1) insert parent
		insert into @keycode(keycode)
		execute [usp_license_insert_license_service] @product_id,@license_distribution_method_id,@seats,@start_date,@end_date,@months,@external_keycode

		select @license_id = license_id
		from license l
		where keycode = (select keycode from @keycode)

		update license set customer_id = @customer_id where license_id = @license_id

		-- 2.1.2) gsm registration
		select @sky_license_id = license_id from @keycodes
		execute [usp_sky_insert_update] @sky_license_id,@sky_template_id,@process_date
		
		-- 2.1.3) Update capability history for messaging
		update lch 
		set lch.capability_activation_date = lc.capability_activation_date,
			lch.capability_expiration_date = lc.capability_expiration_date
		from dbo.license_capability_history lch
		inner join dbo.license_capability lc
			on lc.license_id = lch.license_id
		where lch.license_id = @license_id
			and lch.capability_activation_date is null
			and lch.capability_expiration_date is null
		end
	-- 2.2) convert keycode
	else
		begin
		-- 2.2.1) convert trial
		select @order_type_group_id = 1
		
		if (SELECT capability_type_id from license_summary where keycode = @new_keycode) = 2
			begin 		
				
				select @sql_string = 
						'insert into tasks
..task_table (task_number, Command, NoTransaction, StartTime) ' + 
						' values	(' + left(@license_id,10) + ',' + '''' + 'declare @response_code int, @message varchar(100), @effective_date datetime, @license_id int exec ' + @db_name + '..usp_license_update_license_capability_load ' + convert(varchar(10),@product_id) + ',' + convert(varchar(40),@new_keycode) + ',' + convert(varchar(4),@order_type_group_id) + ',' + isnull(convert(varchar(4),@order_item_id),'NULL') + ',@effective_date output,@license_id output,@response_code output,@message output' + '''' + ',0,getdate()) '

				---print @sql_string

				exec (@sql_string)

				exec tasks..usp_queue_task @license_id	
				
   end

		-- 2.2.2) set expiration date
		select @capability_expiration_date = capability_expiration_date -- IMPROVE TO USE base_capability_id??
		from dbo.license_capability 
		where license_id = @license_id

		select @days = datediff(dd,@capability_expiration_date,@end_date)

	
	if @days <> 0
			begin
				
				select @sql_string = 
						'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
						' values	(' + left(@license_id,10) + ',' + '''' + 'declare @response_code int, @message varchar(100) exec ' + @db_name + '..usp_license_update_license_capability_CSI ' + convert(varchar(10),@days) + ',' + '''' + '''' + convert(varchar(40),@new_keycode) + '''' + '''' + ',' + '''' + '''' + system_user + '''' + '''' + ',@response_code output,@message output' + '''' + ',0,getdate()) '

				--print select @sql_string

				exec (@sql_string)

				exec tasks..usp_queue_task @license_id		
			end
		end



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) license_migration
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) insert license_migration
	insert into dbo.license_migration(original_license_id,new_license_id,insert_by)
	select k.license_id, @license_id, @modified_by
	from @keycodes k 
	left join dbo.license_migration lm
		on k.license_id = lm.original_license_id and lm.new_license_id = @license_id
	where lm.license_migration_id is null



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) autobilling setup
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select top (1) @cancel_license_id = k.license_id
	from @keycodes k
	order by k.license_id desc

	select @effective_date = getdate()

	-- 4.1) update license_effective_object

	declare @license_effective_objects table (row_id int identity(1,1), license_effective_object_id int, license_id int, license_category_id tinyint, effective_object_id tinyint, effective_value int, effective_start_date date)

	--autobilling attributes
	insert into @license_effective_objects (license_effective_object_id,  license_id, license_category_id, effective_object_id, effective_value, effective_start_date)
	select license_effective_object_id,
     license_id,
     license_category_id,
		   2,
     effective_value,
     effective_start_date
	from dbo.fn_license_select_effective_object_element_history(@cancel_license_id, 'license_attribute_license_value', default)
	where effective_end_date > @effective_date or effective_end_date is null
	
	--billing_day_of month
	insert into @license_effective_objects (license_effective_object_id,  license_id, license_category_id, effective_object_id, effective_value, effective_start_date)

	select license_effective_object_id,
     license_id,
     license_category_id,
		   3,
     effective_value,
     effective_start_date	 
	from dbo.fn_license_select_effective_object_element_history(@cancel_license_id, 'billing_day_of_month', default)
	where effective_end_date > @effective_date or effective_end_date is NULL

	--license_usage_pricing_value
	insert into @license_effective_objects (license_effective_object_id,  license_id, license_category_id, effective_object_id, effective_value, effective_start_date)
	select license_effective_object_id,
           license_id,
           license_category_id,
		   5,
           effective_value,
           effective_start_date	 
	from dbo.fn_license_select_effective_object_element_history(@cancel_license_id, 'license_usage_pricing_value', default)
	where effective_end_date > @effective_date or effective_end_date is NULL


	if exists (select 1 from @license_effective_objects WHERE effective_object_id = 2) 
		begin
			declare @min int = 1, @max int, @license_category_id tinyint, @effective_object_id tinyint, @effective_value int, @effective_start_date date, @effective_json nvarchar(max)

			select @max = count(*) from @license_effective_objects

			while @min <= @max
				begin
					select @effective_object_id = effective_object_id,
							@effective_value = effective_value,
							@effective_start_date = effective_start_date,
							@license_category_id = license_category_id
					from @license_effective_objects
					where row_id = @min

					if @effective_object_id = 2 -- autobilling_attribute
						select @effective_json = (select license_id = @license_id, license_category_id = @license_category_id, license_attribute_license_value = @effective_value, effective_start_date  = @effective_start_date for json path)  
			
					if @effective_object_id = 3 -- billing_day_of_month
						select @effective_json = (select license_id = @license_id, license_category_id = @license_category_id, billing_day_of_month = @effective_value, effective_start_date  = @effective_start_date for json path)  

					if @effective_object_id = 5 -- license_usage_pricing_value
						select @effective_json = (select license_id = @license_id, license_category_id = @license_category_id, license_usage_pricing_value = @effective_value, effective_start_date  = @effective_start_date for json path)  

					if @effective_json is not null
						exec usp_license_insert_effective_object @license_effective_object_json = @effective_json, @license_effective_source_caller = 'gsm migration'

					select @effective_object_id = null, @license_category_id = null, @effective_value = null, @effective_start_date = null, @effective_json = null, @min = @min + 1
				end
		end
    
	-- 4.2) Update AR record license_attribute_license
	SELECT @license_attribute_license_value=license_attribute_license_value
	FROM dbo.license_attribute_license
    WHERE license_id = @cancel_license_id AND license_attribute_id = 1

    IF @license_attribute_license_value IS NOT NULL
        BEGIN
	        -- Copy AR status to new license
	        EXEC dbo.usp_license_update_license_attribute_license
		        @license_id=@license_id,
		        @license_attribute_id=1,
		        @license_attribute_license_value=@license_attribute_license_value,
		        @modified_by=@modified_by,
		        @effective_date=@effective_date

	        -- Disable AR on old license
            EXEC dbo.usp_license_update_license_attribute_license
                @license_id=@cancel_license_id,
                @license_attribute_id=1,
                @license_attribute_license_value=0,
                @modified_by=@modified_by,
                @effective_date=@effective_date
        END

	-- 4.3) update license_autorenewal_cycle
	insert into dbo.license_autorenewal_cycle (license_id,message_autorenewal_cycle_id,billing_day_of_month,last_modified_date)
	select @license_id,message_autorenewal_cycle_id,billing
_day_of_month,@effective_date
	from dbo.license_autorenewal_cycle
	where license_id = @cancel_license_id

	-- 4.4) process license_message
	insert into dbo.license_message_archive (license_message_id, license_id,license_message_key, message_type_id,message_status_id, insert_date,process_date, end_date, archive_date,license_message_archive_date,message_campaign_id,message_campaign_class_id)
	select license_message_id, license_id,license_message_key, message_type_id,message_status_id, insert_date,process_date, end_date, archive_date,@effective_date,message_campaign_id,message_campaign_class_id
	from dbo.license_message 
	where message_status_id = 1 and message_type_id IN (3, 10) and license_id = @cancel_license_id

	update dbo.license_message
	set license_id = @license_id, last_modified_date = @effective_date
	where message_status_id = 1 and message_type_id IN (3, 10) and license_id = @cancel_license_id

	-- 4.5) oracle_contract_line
	insert into dbo.oracle_contract_line_license_audit (oracle_contract_line_license_id,oracle_contract_line_id,license_id,insert_date,audit_date)
	select oracle_contract_line_license_id,oracle_contract_line_id,license_id,insert_date,@effective_date
	from dbo.oracle_contract_line_license
	where license_id = @cancel_license_id

	update dbo.oracle_contract_line_license		
	set license_id = @license_id
	from dbo.oracle_contract_line_license
	where license_id = @cancel_license_id

	-- 4.6) order_item_license
	insert into dbo.order_item_license_audit (order_item_license_id,order_item_id,license_id,insert_date,insert_by,modified_date,modified_by,audit_date)
	select oil.order_item_license_id, oil.order_item_id, oil.license_id, oil.insert_date, oil.insert_by, oil.modified_date, oil.modified_by, @effective_date 
	from dbo.order_item_license oil
	inner join dbo.order_item oi
		on oi.order_item_id = oil.order_item_id
	where oil.license_id = @cancel_license_id
		and (oi.capability_expiration_date > @effective_date or oi.capability_expiration_date is null)

	update oil 
	set license_id = @license_id, oil.modified_date = @effective_date, oil.modified_by = @modified_by
	from dbo.order_item_license oil
	inner join dbo.order_item oi
		on oi.order_item_id = oil.order_item_id
	left join order_item_license oil2
		on oil2.order_item_id = oi.order_item_id and oil2.license_id = @license_id
	where oil.license_id = @cancel_license_id
		and (oi.capability_expiration_date > @effective_date or oi.capability_expiration_date is null)
		and oil2.order_item_license_id is null

	--4.7) cart discount
	insert into dbo.license_cart_discount(license_id, cart_discount_id, start_date, end_date, last_modified_date)
	select @license_id, cart_discount_id, start_date, end_date, @effective_date
	from dbo.license_cart_discount
	where license_id = @cancel_license_id



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5) license_parent
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 5.1) license_parent
	select @license_parent_json = (	select k.license_id as child_license_id, lc.license_category_id as license_category_id, @license_id as parent_license_id, @effective_date as effective_start_date
									from @keycodes k
									cross apply fn_license_select_license_profile(k.license_id) lp
									inner join license_category lc on lp.license_category_name = lc.license_category_name 
									for json path)  

	if @license_parent_json is not null
		exec usp_license_insert_license_parent
			@license_parent_json = @license_parent_json,
			@license_effective_source_caller = 'gsm migration'

	--legacy insert code
	--delete p
	--from @keycodes k 
	--inner join dbo.license_paren
t p on k.license_id = p.child_license_id

	--insert into dbo.license_parent (child_license_id, parent_license_id, insert_date, insert_by)
	--select k.license_id, @license_id, @effective_date, @modified_by
	--from @keycodes k 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6) partner_license
	-- -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into @partner_licenses (partner_license_id)
	select partner_license_id
	from dbo.partner_license
	where license_id = @cancel_license_id
		and partner_license_status_id = 2
		and (end_date is null or end_date > @effective_date)

	if @@rowcount > 0
	begin	
		insert into dbo.partner_license_audit (partner_license_id,license_id,partner_id, partner_license_status_id, partner_license_source_id, last_modified_user_id, last_modified_date, insert_date, start_date, end_date, order_header_id, audit_date)
		select pl.partner_license_id, pl.license_id, pl.partner_id, pl.partner_license_status_id, pl.partner_license_source_id, pl.last_modified_user_id, pl.last_modified_date, pl.insert_date, pl.start_date, pl.end_date, pl.order_header_id, @effective_date
		from dbo.partner_license pl
		inner join @partner_licenses l
			on l.partner_license_id = pl.partner_license_id

		update pl 
		set license_id = @license_id, pl.last_modified_user_id = 'gsm_migration', pl.last_modified_date = @effective_date
		from dbo.partner_license pl
		inner join @partner_licenses p
			on p.partner_license_id = pl.partner_license_id
	end
 

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7) partner_billing
	-- -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	INSERT INTO dbo.partner_billing_audit(partner_billing_id, partner_billing_report_id, customer_id, customer_code, company_name, location_code, state, webroot_entity, reseller_customer_id, reseller_customer_code, reseller_company_name, reseller_location_code, reseller_state, license_id, keycode, keycode_age, order_header_id, order_date, product_id, license_category_id, license_seats, retail_price, extended_amount, usage_seats, usage_price, usage_extended_amount, total_extended_amount, cap_amount, last_modified_date, license_attribute_license_value, total_cap_amount, currency_id, partner_pricing_model_id, total_seats, audit_date, company_id)
	SELECT partner_billing_id, partner_billing_report_id, customer_id, customer_code, company_name, location_code, state, webroot_entity, reseller_customer_id, reseller_customer_code, reseller_company_name, reseller_location_code, reseller_state, license_id, keycode, keycode_age, order_header_id, order_date, product_id, license_category_id, license_seats, retail_price, extended_amount, usage_seats, usage_price, usage_extended_amount, total_extended_amount, cap_amount, last_modified_date, license_attribute_license_value, total_cap_amount, currency_id, partner_pricing_model_id, total_seats, @effective_date, company_id
	FROM dbo.partner_billing
	WHERE license_id = @cancel_license_id 

	UPDATE dbo.partner_billing
	SET
		license_id = @license_id,
		last_modified_date = @effective_date
	WHERE license_id = @cancel_license_id



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8) return
	-- ------------------------------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into dbo.license_check_update_license (license_id, source, insertdate)
	select license_id, 6, getdate()
	from @keycodes

	select m.*, new_keycode = l.keycode, original_keycode = l2.keycode
	from dbo.license_migration m
	inner join dbo.license l
		on m.new_license_id = l.license_id
	inner join dbo.license l2
		on m.original_license_id = l2.license_id
	where new_license_id = @license_id	

	
	return


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_module]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_module]

(
	@license_module_code varchar(50), 
	@license_module_name varchar(50), 
	@license_module_class_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2014-12-30	esmart		Initial creation.

	DESCRIPTION
	Select status
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) verify unique code
	if (select count(*) from license_module where license_module_code = @license_module_code) > 0
		begin
		select @response_code = -110, @message = 'Duplicate code'
		select response_code = @response_code, message = @message
		return
		end
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_module(license_module_code, license_module_name, license_module_class_id)
	values(@license_module_code, @license_module_name, @license_module_class_id)

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_parent]
-- =============================================================================
CREATE procedure [dbo].[usp_license_insert_license_parent]
(
	@license_parent_json nvarchar(max)
  , @license_effective_source_caller varchar(50)
)

/*	
	DATE			AUTHOR			REMARKS
	2019-08-17		abelenkiy		Initial creation
	2019-09-06		abelenkiy		Rewrote to accept multiple records via json
	2019-11-11		abelenkiy		Added license_service_id capability
	2020-01-16		abelenkiy		IAMROOT-795 - Bug fix on insert to license category;
									joined to license_category_license on license and category to make distinct and not hit constraint
	2020-02-24		cnovac			Hotfix to take out join to license_category_license since that record doesn't exist yet on child create so no rows returned

	DESCRIPTION
	Insert license_parent record to license_parent table and also effective_object if product_line_id = 300
*/

as
set nocount on;

declare @license_effective_object_json varchar(max);

declare @tmp_license_parent table
(
	child_license_id int
  , license_category_id tinyint
  , parent_license_id int
  , effective_start_date date
  , license_service_id int
);

	begin try
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) parse out json into table variable
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		insert into @tmp_license_parent (child_license_id, license_category_id, parent_license_id, effective_start_date, license_service_id)
		select child_license_id, license_category_id, parent_license_id, effective_start_date, license_service_id
		from
			openjson(@license_parent_json)
			with(
				child_license_id int '$.child_license_id'
			  , license_category_id tinyint '$.license_category_id'
			  , parent_license_id int '$.parent_license_id'
			  , effective_start_date date '$.effective_start_date'
			  , license_service_id int '$.license_service_id'
				);

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) insert license_parent record
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1) insert audit record if child exists with different parent
		insert into license_parent_audit (license_parent_id, parent_license_id, child_license_id, insert_date, insert_by)
		select distinct lp.license_parent_id, lp.parent_license_id, lp.child_license_id, lp.insert_date, lp.insert_by
		from	license_parent lp
			inner join @tmp_license_parent tlp on tlp.child_license_id = lp.child_license_id
												  and	tlp.parent_license_id != lp.parent_license_id

		-- 2.2) update license_parent with new parent if child already exists
		if @@rowcount > 0
			begin
				delete	license_parent
				from	license_parent lp
					inner join @tmp_license_parent tlp on tlp.child_license_id = lp.child_license_id
														  and	tlp.parent_license_id != lp.parent_license_id
			end;
		-- 2.3) insert new license_parent record if child does not already exists
		insert into license_parent (parent_license_id, child_license_id, insert_by)
		select distinct tlp.parent_license_id, tlp.child_license_id, @license_effective_source_caller
		from	@tmp_license_parent tlp
			left join license_parent lp on tlp.child_license_id = lp.child_license_id
										   and	tlp.parent_license_id = lp.pa
rent_license_id
		where	lp.license_parent_id is null;

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) effective_object insert
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		select	@license_effective_object_json = (select tlp.child_license_id as license_id
													  , tlp.license_category_id
													  , tlp.parent_license_id as license_parent_value
													  , tlp.effective_start_date
													  , tlp.license_service_id
												 from	@tmp_license_parent tlp
													 inner join license l on tlp.child_license_id = l.license_id
																			 and l.product_line_id = 300
												 for json path)

		if @license_effective_object_json is not null
			exec dbo.usp_license_insert_effective_object
				@license_effective_object_json
			  , @license_effective_source_caller;

	end try
	begin catch

		declare @DBName nvarchar(128);
		set @DBName = db_name();
		exec usp_LogError @ErrorDB = @DBName;

	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_seat_ramp]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_seat_ramp]

(
	@license_id int,
	@license_seats int,
	@effective_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-11-13	esmart		Initial creation
    2015-10-01  cnovac      Added check to see if the row exists already
	
	DESCRIPTION
	insert ramp
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if not exists (select 1 from license_seat_ramp where license_id = @license_id and effective_date = @effective_date)
	    insert into license_seat_ramp(license_id, license_seats, effective_date)
	    values(@license_id, @license_seats, @effective_date)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_service]

(
	@product_id int,
	@license_distribution_method_id int,
	@quantity int,
	@start_date datetime = null,
	@end_date datetime = null,
	@months int = null,
	@external_keycode varchar(40) = null,
	@order_item_id int = null,
	@trial_registration_id int = null,
	@only_create_keycode bit = 0
)

AS
/*	
		DATE		AUTHOR		REMARKS
		2013-11-05	esmart		Initial creation.	
		2014-03-27	esmart		license_key
		2014-04-09	esmart		Add license_feature_license insert on parent
		2017-05-15	cnovac		Added call to usp_license_insert_effective_object
		2017-05-22	cnovac		update to usp_license_insert_effective_object call
		2017-07-06	esmart		Fix issue with external_keycode
		2018-04-22	cnovac		modified call to usp_license_insert_effective_object
		2018-06-29	cnovac		added @trial_registration_id as possible value to be saved in effective object
		2018-07-11	cnovac		WIFI changes to override certain values
		2018-07-17	esmart		Activate consumer keycode at runtime
		2018-09-07	rvinoche	Allow past record updates when calling usp_license_insert_effective_object
		2019-04-04	cnovac		Changed call to usp_license_update_activate to pass in @trial_registration_id
		2019-06-11	cnovac		Changed call to usp_license_update_activate to pass in @order_item_id
		2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
		2020-08-24	esmart		Storage for mid market
		2020-10-14	cnovac		added logic for storage_gb
		2021-01-28	cnovac		added @only_create_keycode since this proc is called in usp_license_service_insert_license and it does all other inserts, so trying to avoid doing it 2X

		DESCRIPTION
		Create licenses
	*/

	set nocount on

	declare @license_id int,
			@keycode varchar(40),
			@product_line_id int,
			@product_type_id int,
			@license_count int,
			@license_status_id int, 
			@license_type_id int,
			@license_keycode_type_id int,
			@max_daily_activations int,
			@max_child_licenses int,
			@license_expiration_date datetime,
			@insert_date datetime,
			@uses_keycode int,
			@seats int,
			@license_change_reason_id int,
			@product_seats int,
			@storage_gb int,
			@license_distribution_method_code char(4),
			@activation_date datetime,
			@license_category_id tinyint,
			@license_category_name varchar(10),
			@message_autorenewal_cycle_id tinyint,
			@capability_activation_days int,
			@sky_insert TINYINT,
			@response_code int,
			@message varchar(100),
			@license_effective_object_json varchar(max)


		select @license_count = 0
		select @insert_date = getdate()
		select @max_daily_activations = 30
		select @response_code = 0
		select @message = 'Success'
		select @license_change_reason_id = 6

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	begin try

	-- 1.1) select product values
		select @license_keycode_type_id = license_keycode_type_id from product where product_id = @product_id
		select @product_line_id = product_line_id from product_line_product where product_id = @product_id
		select @product_type_id = product_type_id from product where product_id = @product_id
		select @seats = seats from product_seat	where product_id = @product_id
		select @license_category_id = license_category_id from product_license_category
	where product_id = @product_id
		select @license_category_name = license_category_name from license_category where license_category_id = @license_category_id
		select @storage_gb = dbo.fn_get_item_storage_gb(@quantity, default, @product_id, default, default, default)
		select @message_autorenewal_cycle_id = message_autorenewal_cycle_id from product_autorenewal_cycle where product_id = @product_id

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Generate licenses
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.0) create temp table to store license_ids and keycodes
	declare @licenses table (license_id int, keycode varchar(40))

	-- 2.1) check quantity and set parameters
	if @product_line_id in (300,55)
		-- 2.1.2) Enterprise
		begin
			select @max_child_licenses = @quantity
			select @max_daily_activations = @quantity
			select @seats = @quantity
			select @quantity = 1
			select @license_type_id = case when @license_keycode_type_id = 3 then 2 else 4 end
			select @license_status_id = 1 
			select @license_expiration_date = null
		end
	else 
		-- 2.1.3) Consumer/OEM
		begin		
			select @license_type_id = case when @license_keycode_type_id = 3 then 2 else 1 end
			select @license_status_id = 0 
			select @max_child_licenses = null
			select @license_expiration_date = null
		end

	-- 2.1.4) WIFI
	if @license_category_name = 'WIFI' --override this for WIFI
	begin
		set @license_status_id = 1
		set @quantity = 1
	end

	-- 2.2) activation and expiration dates
	if @start_date is null and @months is not null and @months <> 0
		begin
		select @start_date = getdate(), @end_date = dateadd(mm,@months,getdate())
		select @capability_activation_days = datediff(dd,@start_date,@end_date)
		end

	if @start_date is not null and @end_date is not null
		begin
		select @capability_activation_days = datediff(dd,@start_date,@end_date)
		end
	
	-- 2.2) Create licenses		
	while @license_count < @quantity
	begin -- begin while

		-- 2.2.1)
		if @external_keycode is null
			begin
				exec usp_license_generate_keycode_cart @product_id, @license_distribution_method_id, @keycode output, @response_code output, @message output
			end
		else
			begin
				select @keycode = @external_keycode
				select @sky_insert = 1
			end

		-- 2.2.3) added this in so if @only_create_keycode = 1, then we skip this whole section since it's not needed
		if @only_create_keycode = 0
		begin

			-- 2.2.2) insert license
			insert into license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses,license_expiration_date, insert_date, insert_by, modified_date, modified_by)
			values (@keycode, @product_line_id, @license_status_id, @license_type_id, @license_distribution_method_id, @license_keycode_type_id, @max_daily_activations, @max_child_licenses, @license_expiration_date, @insert_date, system_user, @insert_date, system_user)

			select @license_id = scope_identity()

			insert into license_key(license_id) values(@license_id)

			IF @sky_insert =1 
				begin	
					insert into dbo.sky_api_license (license_id) values (@license_id)
				end

			-- 2.2.3 insert license_capability
			insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
			select 	@license_id, 
				capability_id, 
				capability_type_id, 
				capability_activation_days = case
												when @capability_activation_days is not null then @capability_activati
on_days 
												else c.capability_activation_days
											end,
				insert_date = @insert_date,
				insert_by = system_user,
				modified_date = @insert_date,
				modified_by = system_user		
			from product_capability c
			where product_id = @product_id
			
			-- 2.2.4 insert license_id and keycode into @licenses
			insert into @licenses (license_id, keycode) values (@license_id, @keycode)

			-- 2.2.5 increment license_count
			select @license_count = @license_count + 1

			-- 2.2.6 insert license_storage record
			if @storage_gb is not null
			begin

				--build up the JSON now based on data in @effective_json only for business licenses
				set @license_effective_object_json = null
				select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @storage_gb as storage_gb, isnull(@start_date, @insert_date) as effective_start_date, @order_item_id as order_item_id, @trial_registration_id as trial_registration_id
				from license l
				where l.license_id = @license_id 
				and l.product_line_id in (55, 300)
				for json path)

				--if data exists, call the insert now
				if @license_effective_object_json is not null
				begin
					exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_insert_license_service'
				end
			
			end
			-- 2.2.7 insert license_seat records
			if @seats is not null
			begin
				insert into license_seat (license_id, license_seats) values (@license_id, @seats)

				--build up the JSON now based on data in @effective_json only for business licenses
				set @license_effective_object_json = null
				select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @seats as license_seats, isnull(@start_date, @insert_date) as effective_start_date, @order_item_id as order_item_id, @trial_registration_id as trial_registration_id
				from license l
				where l.license_id = @license_id 
				and l.product_line_id in (55, 300)
				for json path)

				--if data exists, call the insert now
				if @license_effective_object_json is not null
				begin
					exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_insert_license_service'
				end

			end
			-- 2.2.8 insert license_category_license record
			if @license_category_id is not null
				begin
				insert into license_category_license (license_id, license_category_id) 	
				values (@license_id, @license_category_id)	
				end
				
			-- 2.2.9 license_module
			if (select COUNT(*) from product_license_module where product_id = @product_id) > 0
				begin
					insert into license_module_license(license_id,license_module_id,license_module_type_id)
					select @license_id, license_module_id, license_module_type_id
					from product_license_module 
					where product_id = @product_id
				end		
				
			-- 2.2.10) usp_license_insert_license_cart
			if @message_autorenewal_cycle_id is not null
				begin
				insert into license_autorenewal_cycle(license_id,message_autorenewal_cycle_id)
				values(@license_id,@message_autorenewal_cycle_id)				
				end

			-- 2.2.11) set parent as fixed expiration date 
			if @license_keycode_type_id = 3
				begin
				insert into license_feature_license(license_id,license_feature_id) values(@license_id,8)
				end

			-- 2.2.12) activite
			exec usp_license_update_activate @license_id = @license_id, @start_date = @start_date, @end_date = @end_date, @order_item_id = @order_item_id, @trial_registration_id = @trial_registration_id

		end
		else
		begin
			-- insert keycode into @licenses
			insert into @licenses (keycode) values (@keycode)

			-- increment license_count
			select @license_count = @license_count + 1

		end

	end -
- end while

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) OUTPUT
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select keycode
	from @licenses
	where keycode <> ''
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;











GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_storage]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_storage]

(
	@license_id int, 
	@storage_gb int,
	@order_item_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-07-14		esmart		Initial creation
	
	DESCRIPTION
	insert license_storage
*/

AS

	set nocount on


	begin try

		declare @capability_activation_date datetime,
				@capability_expiration_date datetime,
				@log_type int

		select @log_type = 1
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1 @license_id
		select @response_code =  case when license_id is null then -110 else 0	 end,
			@message = case when license_id is null then '@license_id not valid' else '' end
		from license
		where license_id = @license_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end

		-- 1.2 @storage_gb	
		if @storage_gb <= 0
			begin
				set @response_code = -120
				set @message = '@storage_gb must be greater than 0'
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end
	
		-- 1.3 record exists
		select @response_code =  case when count(*) > 0 then -130 else 0	 end,
			@message = case when count(*) > 0 then 'license_storage record exists' else '' end
		from license_storage
		where license_id = @license_id

		if @response_code < 0 	
			begin
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end
	
		-- 1.4 check to see if the capability activation and expiration dates have been set on the secure backup capability
		select 	@capability_activation_date = capability_activation_date,
				@capability_expiration_date	= capability_expiration_date
		from license_capability
		where license_id = @license_id and capability_id = 11

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert license_storage
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 2.0) Add license_storage_record
		insert into license_storage (license_id, storage_gb, storage_activation_date, storage_expiration_date)
		values (@license_id, @storage_gb, @capability_activation_date, @capability_expiration_date)
		
		-- 2.1) Add row to license_storage_history if the order_item_id is not null. This is needed for refund logic.
		if @order_item_id is not null
			begin
					
			insert into license_storage_history (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, order_item_id)
			select license_storage_id, license_id, 
					storage_gb = 0, 
					storage_activation_date = null,
					storage_expiration_date = null,
					insert_date, insert_by, modified_date, modified_by, 3, @order_item_id
			from license_storage
			where license_id = @license_id

			end

	end try

	begin catch
			
			declare @DBName nvarchar(128)
			
			set @DBName = 
db_name()
			set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
			set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
			set @message = case 
								when @message is null then 'license_storage insert failed'
								else @message 
							end
			
			exec usp_LogError @log_type, @ErrorDB = @DBName
			
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_summary_data]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_insert_license_summary_data]

(
	@new_license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-18	acoffel		Initial creation
	2018-02-09	esmart		Add left join to insert
	2023-06-05	schindar	Add customer_id data insert logic for license_summary for all state data pull

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@rowcnt int,
			@rowcnt_key int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert summary date
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- add a condition to avoid duplicate license_id rows

		select @rowcnt = count(license_id) from license_summary where license_id =  @new_license_id
		select @rowcnt_key = count(license_id) from license_key where license_id =  @new_license_id

	
		-- 2.1) inseert @license_summary
		if @rowcnt = 0
			begin  
				--establish license_key entry
				if @rowcnt_key = 0
					begin 
						insert into license_key(license_id) 
						select l.license_id
						from license l
						left join license_key k
							on k.license_id = l.license_id
						where l.license_id = @new_license_id and k.license_id is null
					end

				insert into license_summary(license_id, license_key, keycode, license_distribution_method_id, license_type_id, license_status_id, product_line_id, license_seats, license_category_id, opt_in, autorenewal_opt_id, capability_id, capability_type_id, capability_activation_date, capability_expiration_date, subscription_id, serial_number, contract_id, contract_detail_update, subscription_type_id, keycode_alias,customer_id)
				select l.license_id,
						license_key = convert(varchar(36),k.license_key),
						l.keycode,
						l.license_distribution_method_id,
						l.license_type_id,
						l.license_status_id,
						l.product_line_id,
						case when st.license_seats is NULL then 1 else st.license_seats end,
						lcl.license_category_id,
						opt_in = isnull(c.opt_in,1),
						autorenewal_opt_id = case 
												when s.subscription_id is null and al.license_attribute_license_value = 1 then 1 
												when s.subscription_id is not null and s.opt_status = 0 then 1
												else 0 
											end,
						lc.capability_id,
						lc.capability_type_id,
						lc.capability_activation_date,
						lc.capability_expiration_date,
						s.subscription_id,
						s.serial_number,
						s.contract_id,
						s.contract_detail_update,
						subscription_type_id = case when e.subscription_type_id is not null then e.subscription_type_id else s.subscription_type_id end,
						ka.keycode_alias,
						l.customer_id
				from license l with (nolock)
				inner join license_category_license lcl with (nolock)
					on l.license_id = lcl.license_id
				inner join license_category ct with (nolock)
					on lcl.license_category_id = ct.license_category_id
				left join license_keycode_alias ka with (nolock)
					on l.license_id = ka.license_id
				left join license_key k with (nolock)
					on l.license_id = k.license_id
				left join license_seat st with (nolock)
					on l.license_id = st.license_id
				left join license_capability lc with (nolock)
					on l.license_id = lc.license_id and lc.capability_id = ct.base_capability_id
				left join customer c with (nolock)
					on l.customer_id = c.customer_id
				left join license_attribute_license al with (nolock)
	
				on l.license_id = al.license_id
				left join subscription s with (nolock)
					on l.license_id = s.license_id
				left join subscription_external e with (nolock)
					on s.subscription_id = e.subscription_id
				left join license_summary ls
					on ls.license_id = l.license_id
				where l.license_id = @new_license_id and s.license_id is null

			end
						
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_license_usage_pricing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_license_usage_pricing]

(
	@license_id int,
	@order_item_id int,
	@effective_date datetime,
	@usage_price money,
	@partner_license_status_id tinyint = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-11-23		esmart			Initial creation
	2017-06-07		esmart			Add license_category_id
	2019-01-31		rvinoche		Add logic to match license_effective_object
	2019-06-11		abelenkiy		Added billing entity logic and removed insert logic now in effective object
	2019-07-19		rvinoche		Abstracted partner license decision to usp_partner_license_transaction_controller
	2019-09-30		cnovac			Updated code to remove @allow_past_record_update variable and always allow that code to fire

	DESCRIPTION
	insert license_usage_pricing
*/

AS
	
	set nocount on			

	declare	@comment nvarchar(max),
			@license_category_id tinyint,
			@license_effective_object_json varchar(max),
			@license_transaction varchar(max),
			@message varchar(100),
			@order_header_id int,
			@partner_license_id int,
			@modified_by varchar(20),
			@pending_partner_license_transaction int, 
			@response_code int,
			@site_id varchar(65)

	begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @product_line_id
		select @license_category_id = isnull(plc.license_category_id, lcl.license_category_id)
		from license l
		left join license_category_license lcl on lcl.license_id = l.license_id
		left join order_item oi on oi.order_item_id = @order_item_id
		left join product_license_category plc on plc.product_id = oi.product_id
		where l.license_id = @license_id

		select @order_header_id = order_header_id
		from dbo.order_item
		where order_item_id = @order_item_id

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) partner_license
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) partner_license
		declare @is_allowed bit, @partner_id int, @partner_license_source_id tinyint;

		if @partner_license_status_id <> 2 or @partner_license_status_id is NULL
			select @is_allowed = is_allowed, @partner_id = partner_id, @partner_license_source_id = partner_license_source_id
			from dbo.fn_partner_license_transaction_controller(@license_id, @effective_date, @order_header_id, null)

		if @is_allowed = 0
		begin
        
			-- 2.1.1) insert partner_license
			exec usp_partner_insert_partner_license @license_id,@partner_id,1,@partner_license_source_id,@modified_by,@comment,@order_header_id,@partner_license_id output

				select @license_transaction = (select 'usp_license_insert_license_usage_pricing' as 'procedure', @license_id as '@license_id', @usage_price as '@usage_price', @order_item_id as '@order_item_id', @effective_date as '@effective_date' for json Path, without_array_wrapper)

				exec usp_partner_insert_partner_license_transaction @partner_license_id,1,@license_transaction
            
            return
		end
		
		-- --------------------------------------------------------------------------------------------------------------------------------------------------
-------------------------------------------------
		-- 3.) effective_object insert
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @license_effective_object_json = (select license_id = @license_id, license_category_id = @license_category_id, 
														license_usage_pricing_value = cast(@usage_price*100 as int), effective_start_date = @effective_date, 
														order_item_id = @order_item_id for json path)

		exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_insert_license_usage_pricing'

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert pricing failed for license_id ' + convert(varchar(20), @license_id)
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;









GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_next_bill_date]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_next_bill_date]

/*	
    DATE		AUTHOR		REMARKS
    2024-02-01	msoni		ECOM_3124 Initial creation.
    2024-03-18  msoni		ECOM_3907 Added new field subscription_payment_status_id.
    2024-04-30  msoni		ECOM-3308 Insert/Update CONF_HIDE_DAYS based on subscription_payment_status
    2024-08-29	rambasana	ECOM-5408 Add filter to update only ZARB license and optimize query
    2024-11-08  msoni       D-3045614 (ECOM-5629) Update last_modified_by for license_next_bill_date  
    2024-11-19	rambasana	US-4149414 Added filter to check from target table before update license_next_bill_status_id (section 2.5)
    2025-03-18	rambasana	US-4529659 Handle duplicate records in license_next_bill_date
	2025-05-05	rambasana	US-4726462 Send email for autorenewal discrepancy between ecom and zuora (section 3)
	2025-07-10	rambasana	US-4857133 Handle AR discrepancy for Cancelled payment status and update file name (section 3)
	2025-09-03	rambasana	US-4968354 Update License AR status in dbo.license_attribute_license and remove email notification 

    DESCRIPTION
    Objective of this procedure is to capture Zuora keycodes with NextBillDate/subscription_payment_status and map those with existing license_ids in Produciton table (dbo.license).
    This proc will insert new data into Target table and also insert data in Audit table (dbo.license_next_bill_date_audit ) if any row is updated in Target table.
    Final result will move Zuora keycode with NextBillDate,subscription_payment_status and license_ids in newly created target table named as dbo.license_next_bill_date.
    This procedure is being called from SQL JOB - Zuora Update Next Bill Date in ecomdb(prod) server.
    
    ECOM - 3308: Insert into dbo.license_module_license based on the subscription_payment_status for license_id
    1. UPDATE CONF_HIDE_DAYS: IF license_module_id = 25 (CONF_HIDE_DAYS) is EXISTING, AND if subscription_payment_status will change to Success(now) from Failed (Initially),
       Then UPDATE license_module_type_id = 1.Once CONF_HIDE_DAYS is addded to the license with failed status, and in future if payment_status will change to Success/Cancelled.
       Then UPDATE license_module_type_id = 22 (NULL) from 1 (Y) for license_module_id = 25 (CONF_HIDE_DAYS).		
    2. INSERT CONF_HIDE_DAYS:IF license_module_id = 25 (CONF_HIDE_DAYS) is NOT EXIST for the license_id, AND if subscription_payment_status = Failed,
       Then INSERT new module (CONF_HIDE_DAYS /25 with license_module_type_id = 1 ) for that license_id into dbo.license_module_license.
        
*/
AS
SET NOCOUNT ON;
BEGIN TRY

    ------------------------------------------------------------------------------------------------------------------------
    -- 1. Create temp table to dump staging data into FEED DB table: ECOM - 3124
    ------------------------------------------------------------------------------------------------------------------------
    DECLARE @license_module_id INT,
            @license_module_type_id_y INT,
            @license_module_type_id_null INT,
            @license_change_reason_id INT,
            @subscription_payment_status_id INT,
            @count INT,
            @last_modified_by VARCHAR(50),
			@license_id INT,
			@license_attribute_license_value INT,
			@loop_cnt INT = 1,
			@license_cnt int


    SELECT @license_module_id = license_module_id
    FROM dbo.license_module
    WHERE license_module_code = 'CONF_HIDE_DAYS';

    SELECT @license_module_type_id_y = license_module_type_id
    FROM dbo.license_module_type
    WHERE license_module_type_name = 'Y';

    SELECT @license_module_type_id_null = license_module_type_id
    FROM dbo.license_module_type
    WHER
E license_module_type_name = 'NULL';

    SELECT @license_change_reason_id = license_change_reason_id
    FROM dbo.license_change_reason
    WHERE license_change_reason = 'Consumer Portal Update';

    SELECT @subscription_payment_status_id = subscription_payment_status_id
    FROM dbo.subscription_payment_status
    WHERE subscription_payment_status_name = 'Failed';

	DECLARE @APP_CONFIG TABLE
    (
        license_distribution_method_id INT,
        license_distribution_code NVARCHAR(50)
    );

    INSERT INTO @APP_CONFIG
    (
        license_distribution_method_id,
        license_distribution_code
    )
    SELECT dm.license_distribution_method_id,
           f.[key]
    FROM dbo.[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_code = f.[key];


    SET @count = 10000;

    --1.1) Validation
    --get data from source
    DROP TABLE IF EXISTS #license_next_bill_date_update;
    SELECT TOP (@count)
           lu.license_next_bill_date_update_id,
           lu.keycode,
           lu.next_bill_date,
           lu.payment_status_name,
           lu.license_id,
           lu.license_next_bill_date_status_id,
           lu.last_modified_date,
           lu.insert_date
    INTO #license_next_bill_date_update
    FROM dbo.license_next_bill_date_update lu
    WHERE lu.license_next_bill_date_status_id = 0
    ORDER BY lu.insert_date,
             lu.keycode;

    UPDATE ldu
    SET ldu.license_id = l.license_id
    FROM dbo.license_next_bill_date_update ldu
        INNER JOIN #license_next_bill_date_update lu
            ON lu.license_next_bill_date_update_id = ldu.license_next_bill_date_update_id
               AND lu.keycode = ldu.keycode
        INNER JOIN dbo.license l
            ON l.keycode = ldu.keycode;

    --get distinct records to process
    DROP TABLE IF EXISTS #temp;
    SELECT DISTINCT TOP (@count)
           lu.keycode,
           lu.next_bill_date,
           lu.payment_status_name,
           lu.license_id,
           lu.license_next_bill_date_status_id,
           lu.last_modified_date,
           lu.insert_date
    INTO #temp
    FROM dbo.license_next_bill_date_update lu
        INNER JOIN #license_next_bill_date_update ldu
            ON ldu.license_next_bill_date_update_id = lu.license_next_bill_date_update_id
        INNER JOIN
        (
            SELECT lu.license_id,
                   MAX(lu.last_modified_date) last_modified_date
            FROM dbo.license_next_bill_date_update lu
            WHERE lu.license_next_bill_date_status_id = 0
            GROUP BY lu.license_id
        ) l1
            ON l1.license_id = lu.license_id
               AND l1.last_modified_date = lu.last_modified_date
    WHERE lu.license_next_bill_date_status_id = 0
    ORDER BY lu.insert_date,
             lu.license_id;

    CREATE NONCLUSTERED INDEX idx_temp_key
    ON #temp (keycode)
    INCLUDE (insert_date);

    --Update status to inprogress from staging table
    UPDATE lnu
    SET lnu.license_next_bill_date_status_id = 1
    FROM dbo.license_next_bill_date_update lnu
        INNER JOIN #temp t
            ON t.keycode = lnu.keycode
               AND t.insert_date = lnu.insert_date
    WHERE lnu.next_bill_date IS NOT NULL
          AND lnu.license_next_bill_date_status_id = 0;

    --Null License_id 
    UPDATE lnu
    SET lnu.license_next_bill_date_status_id = 2
    FROM dbo.license_next_bill_date_update lnu
        INNER JOIN #temp t
            ON t.keycode = lnu.keycode
               AND t.insert_date = lnu.insert_date
    WHERE lnu.license_id IS NULL
          AND lnu.license_next_bill_date_status_id = 1;

    ----Multiple nextbill date
    UPDATE lnu
    SET lnu.license_next_bill_date_status_id = 2
    FROM dbo.license_next_bill_date_update lnu
        INNER JOIN #temp t
         
   ON t.keycode = lnu.keycode
        INNER JOIN
        (
            SELECT keycode
            FROM #temp
            WHERE license_next_bill_date_status_id = 0
            GROUP BY keycode
            HAVING COUNT(next_bill_date) > 1
        ) c
            ON c.keycode = lnu.keycode
    WHERE lnu.license_next_bill_date_status_id IN (0,1);

    --1.2) Get license with ZARB disti code

    DROP TABLE IF EXISTS #next_bill_date_staging;
    SELECT t.*
    INTO #next_bill_date_staging
    FROM dbo.license_next_bill_date_update t
        INNER JOIN dbo.license l
            ON l.license_id = t.license_id
        INNER JOIN @APP_CONFIG ap
            ON ap.license_distribution_method_id = l.license_distribution_method_id
    WHERE t.license_next_bill_date_status_id = 1;

    --Non ZARB Disti code
    UPDATE lnu
    SET lnu.license_next_bill_date_status_id = 4
    FROM dbo.license_next_bill_date_update lnu
        INNER JOIN #temp t
            ON t.keycode = lnu.keycode
               AND t.insert_date = lnu.insert_date
        LEFT JOIN #next_bill_date_staging ns
            ON ns.keycode = lnu.keycode
    WHERE ns.keycode IS NULL
          AND lnu.license_next_bill_date_status_id = 1;


    DROP TABLE IF EXISTS #NextBillDate_dump;

    CREATE TABLE #NextBillDate_dump
    (
        [id] [INT] NOT NULL IDENTITY(1, 1),
        [license_id] [INT] NULL,
        [keycode] [VARCHAR](40),
        [next_bill_date] [DATETIME],
        [payment_status_name] [VARCHAR](20),
        [Subscription_payment_status_id] INT,
        license_module_type_id INT,
        license_module_id INT,
		AutoRenew int, 
		IsAutoRenewChanged INT
            PRIMARY KEY (id)
    );

    INSERT INTO #NextBillDate_dump
    (
        license_id,
        keycode,
        next_bill_date,
        payment_status_name,
        Subscription_payment_status_id,
        license_module_type_id,
        license_module_id,
		AutoRenew, 
		IsAutoRenewChanged
    )
    SELECT nbs.license_id,
           nbs.keycode,
           nbs.next_bill_date,
           nbs.payment_status_name,
           sp.subscription_payment_status_id,
           CASE
               WHEN sp.subscription_payment_status_name = 'Failed' THEN
                   @license_module_type_id_y
               WHEN sp.subscription_payment_status_name IN ( 'Success', 'Cancelled' ) THEN
                   @license_module_type_id_null
           END AS license_module_type_id,
           @license_module_id AS license_module_id,
		   CASE WHEN nbs.payment_status_name = 'Cancelled' and nbs.AutoRenew = 'Active' THEN 0
		   WHEN nbs.AutoRenew = 'Active' THEN 1
		   ELSE 0 END AS AutoRenew,
		   nbs.IsAutoRenewChanged
    FROM #next_bill_date_staging nbs
        LEFT JOIN dbo.subscription_payment_status sp
            ON nbs.payment_status_name = sp.subscription_payment_status_name;

    CREATE NONCLUSTERED INDEX idx_license_id
    ON #NextBillDate_dump ([license_id])
    INCLUDE (
                [Subscription_payment_status_id],
                [license_module_type_id],
                [license_module_id],
                next_bill_date
            );

    IF EXISTS
    (
        SELECT l.license_id
        FROM #NextBillDate_dump t
            INNER JOIN dbo.license_next_bill_date nb
                ON nb.license_id = t.license_id
            LEFT JOIN dbo.license_next_bill_date l
                ON t.license_id = l.license_id
                   AND t.next_bill_date = l.next_bill_date
                   AND t.Subscription_payment_status_id = l.subscription_payment_status_id
        WHERE l.license_id IS NULL
    )
    BEGIN

        -- 1.3) Insert into audit table before doing the update. 
        INSERT INTO dbo.license_next_bill_date_audit
        (
            license_next_bill_date_id,
            license_id,
            keycode,
            next_bill_date,
            subscription_payment_status_id,
 
           last_modified_by,
            last_modified_date
        )
        SELECT nb.license_next_bill_date_id,
               nb.license_id,
               nb.keycode,
               nb.next_bill_date,
               nb.subscription_payment_status_id,
               nb.last_modified_by,
               nb.last_modified_date
        FROM #NextBillDate_dump t
            INNER JOIN dbo.license_next_bill_date nb
                ON nb.license_id = t.license_id
            LEFT JOIN dbo.license_next_bill_date l
                ON t.license_id = l.license_id
                   AND t.next_bill_date = l.next_bill_date
                   AND t.Subscription_payment_status_id = l.subscription_payment_status_id
        WHERE l.license_id IS NULL;

        -- 1.4) Update next_bill_date and subscription_payment_status for existing keycode in Production

        SET @last_modified_by = SYSTEM_USER;

        UPDATE lnb
        SET lnb.next_bill_date = t.next_bill_date,
            lnb.subscription_payment_status_id = t.Subscription_payment_status_id,
            lnb.last_modified_date = GETDATE(),
            lnb.last_modified_by = @last_modified_by
        FROM #NextBillDate_dump t
            INNER JOIN dbo.license_next_bill_date lnb
                ON lnb.license_id = t.license_id
            LEFT JOIN dbo.license_next_bill_date l
                ON t.license_id = l.license_id
                   AND t.next_bill_date = l.next_bill_date
                   AND t.Subscription_payment_status_id = l.subscription_payment_status_id
        WHERE l.license_id IS NULL;
    END;

    --1.5) Insert into Production teble IF KC does not exist in Production.
    INSERT INTO dbo.license_next_bill_date
    (
        license_id,
        keycode,
        next_bill_date,
        subscription_payment_status_id
    )
    SELECT  DISTINCT
	t.license_id,
           t.keycode,
           t.next_bill_date,
           t.Subscription_payment_status_id
    FROM #NextBillDate_dump t
        LEFT JOIN dbo.license_next_bill_date lnb
            ON lnb.license_id = t.license_id
    WHERE lnb.license_id IS NULL;

    ------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2. Insert/Update 'CONF_HIDE_DAYS' module into dbo.license_module_license - ECOM_3308
    ------------------------------------------------------------------------------------------------------------------------------------------------ 
    -- 2.1) Insert into history table before doing the update. 
    DROP TABLE IF EXISTS #license_module_license;

    SELECT license_id,
           license_module_id,
           license_module_type_id,
           Subscription_payment_status_id
    INTO #license_module_license
    FROM #NextBillDate_dump
    WHERE license_module_type_id IS NOT NULL;

    IF EXISTS
    (
        SELECT *
        FROM #license_module_license t
            INNER JOIN dbo.license_module_license lml
                ON lml.license_id = t.license_id
                   AND lml.license_module_id = t.license_module_id
    )
    BEGIN

        --2.2) Insert into history table before doing the update. 
        SET @last_modified_by = 'safe_update';

        INSERT INTO dbo.license_module_license_history
        (
            license_module_license_id,
            license_id,
            license_module_id,
            license_module_type_id,
            start_date,
            end_date,
            last_modified_date,
            last_modified_by,
            license_change_reason_id,
            history_date,
            license_status_id
        )
        SELECT lml.license_module_license_id,
               lml.license_id,
               lml.license_module_id,
               lml.license_module_type_id,
               lml.start_date,
               lml.end_date,
               GETDATE(),
               @
last_modified_by,
               @license_change_reason_id,
               GETDATE(),
               lml.license_status_id
        FROM #license_module_license t
            INNER JOIN dbo.license_module_license lml
                ON lml.license_id = t.license_id
                   AND lml.license_module_id = t.license_module_id;

        -- 2.3) CHECK 1: Update dbo.license_module_license if 'CONF_HIDE_DAYS' module is existing.
        UPDATE lml
        SET lml.license_module_type_id = t.license_module_type_id
        FROM #license_module_license t
            INNER JOIN dbo.license_module_license lml
                ON lml.license_id = t.license_id
                   AND lml.license_module_id = t.license_module_id;

    END;

    --2.4) Payment status = Failed: Set 'CONF_HIDE_DAYS = Y'
    INSERT INTO dbo.license_module_license
    (
        license_id,
        license_module_id,
        license_module_type_id,
        start_date,
        end_date,
        last_modified_date,
        last_modified_by
    )
    SELECT lnb.license_id,
           @license_module_id,
           @license_module_type_id_y,
           lcl.start_date,
           lcl.end_date,
           GETDATE(),
           @last_modified_by
    FROM #license_module_license lnb
        INNER JOIN dbo.license_category_license lcl
            ON lcl.license_id = lnb.license_id
        LEFT JOIN dbo.license_module_license lml
            ON lml.license_id = lnb.license_id
               AND lml.license_module_id = lnb.license_module_id
    WHERE lnb.Subscription_payment_status_id = @subscription_payment_status_id
          AND lml.license_module_license_id IS NULL;

    --2.5) Update status

    UPDATE lnu
    SET lnu.license_next_bill_date_status_id = 3,
        lnu.license_id = ld.license_id
    FROM dbo.license_next_bill_date_update lnu
        INNER JOIN #NextBillDate_dump t
            ON t.license_id = lnu.license_id
        INNER JOIN dbo.license_next_bill_date ld
            ON ld.license_id = lnu.license_id
    WHERE lnu.license_next_bill_date_status_id IN (0,1);

	------------------------------------------------------------------------------------------------------------------------------------------------
    -- 3. Update license autorenewal status for discrepancy
    ------------------------------------------------------------------------------------------------------------------------------------------------ 

	DECLARE  @autoreneal_discrepancy TABLE  (
	id INT NOT NULL IdENTITY(1,1),license_id int, AutoRenew_status_zuora int, AutoRenew_status_ecom int)

	INSERT INTO @autoreneal_discrepancy
	(
	    license_id,
	    AutoRenew_status_zuora,
	    AutoRenew_status_ecom
	)
	SELECT DISTINCT 
			nd.license_id,
    	    nd.AutoRenew,
		    la1.license_attribute_license_value
	FROM #NextBillDate_dump nd
	left JOIN dbo.license_attribute_license la ON la.license_id = nd.license_id 
	AND la.license_attribute_id = 1
	AND (CASE WHEN la.license_attribute_license_value = 1 THEN 1 ELSE 0 END ) = nd.AutoRenew 
	LEFT JOIN dbo.license_attribute_license la1 ON la1.license_id = nd.license_id AND la1.license_attribute_id = 1
	WHERE la.license_id IS NULL
	AND nd.IsAutoRenewChanged = 1

	SELECT @license_cnt = COUNT(*) FROM @autoreneal_discrepancy

	WHILE @loop_cnt <= @license_cnt
	BEGIN

    SELECT @license_id = ar.license_id,
           @license_attribute_license_value = ar.AutoRenew_status_zuora
    FROM @autoreneal_discrepancy ar
    WHERE ar.id = @loop_cnt;

    EXEC dbo.usp_license_update_license_attribute_license @license_id = @license_id,                                           -- int
                                                          @license_attribute_id = 1,                                           -- Autorenewal							  
                                                          @license_attribute_license_value = @license_attribute_license_value, -- int
            
                                              @modified_by = @last_modified_by;                                    -- varchar(20)

    SELECT @loop_cnt = @loop_cnt + 1,
           @license_id = NULL,
           @license_attribute_license_value = NULL;

	END;

    DROP TABLE IF EXISTS #next_bill_date_staging;
    DROP TABLE IF EXISTS #NextBillDate_dump;
    DROP TABLE IF EXISTS #license_module_license;
	
END TRY
BEGIN CATCH

    DECLARE @error_severity INT = ERROR_SEVERITY(),
            @error_state INT = ERROR_STATE(),
            @message NVARCHAR(4000);
    SET @message = N'Failed to load Next Bill Date:' + ERROR_MESSAGE();
    RAISERROR(@message, @error_severity, @error_state) WITH LOG;

    INSERT INTO dbo.DBErrorlog
    (
        ErrorNumber,
        ErrorSeverity,
        ErrorState,
        ErrorProcedure,
        ErrorLine,
        ErrorMessage,
        ErrorServer,
        ErrorDB,
        ErrorUser
    )
    SELECT ERROR_NUMBER(),
           ERROR_SEVERITY(),
           ERROR_STATE(),
           ERROR_PROCEDURE(),
           ERROR_LINE(),
           @message,
           @@servername,
           DB_NAME(),
           SUSER_NAME();

END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_payment_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_payment_account]
(
    @account_update_json NVARCHAR(MAX),
    @message VARCHAR(100) OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2024-01-02	psatish		ECOM-3264 Initial creation
	2024-03-20  psatish		ECOM-3685 Save the payment method/credit card info at the license level and update the payment status 
	2024-04-30  msoni       ECOM-3308 Insert/Update CONF_HIDE_DAYS based on subscription_payment_status

	DESCRIPTION
	1.Calls usp_payment_update_payment_header	: It is used to update the payment method at the license level.
	2.Calls usp_payment_update_payment_account	: It is used to insert the credit card information at the license level.
	3.Calls usp_license_update_license_attribute_license: It is used to insert/update the AR status(license_attribute_license_value)
												  in the license_attribute_license table for a Zuora license.
		
	DEPENDENCY
	usp_payment_update_payment_header - To update the payment method
	usp_payment_update_payment_account - To save the credit card information
	usp_license_update_license_attribute_license - To save the AR status
	
	This procedure is initiated by the new Endpoint:update-account-info

*/

AS
SET NOCOUNT ON;

BEGIN TRY
    DECLARE @license_id INT,
            @keycode VARCHAR(40),
            @license_attribute_license_value INT,
            @account_number VARCHAR(50),
            @expiration_month VARCHAR(50),
            @expiration_year VARCHAR(50),
            @card_type_id INT,
            @payment_method VARCHAR(50),
            @payment_header_id INT,
            @license_distribution_method_code VARCHAR(5),
            @payment_method_name VARCHAR(50),
            @current_payment_method_name VARCHAR(50),
            @payment_merchant_name VARCHAR(40),
            @currency_code VARCHAR(3),
            @autorenewal_status VARCHAR(50),
            @payment_status_id INT,
            @license_key VARCHAR(40),
            @payment_status VARCHAR(50),
            @portal_disti_code VARCHAR(50),
            @payment_method_id INT,
            @modified_by VARCHAR(200) = 'Portal_Update',
            @payment_merchant_id INT,
            @subscription_payment_status_id INT,
            @CARD_TYPE VARCHAR(50),
            @license_module_id INT,
            @license_module_type_id_y INT,
            @license_module_type_id_null INT,
            @license_change_reason_id INT;


    DECLARE @APP_CONFIG TABLE
    (
        distribution_method_code VARCHAR(4)
    );


    SELECT @CARD_TYPE = [key]
    FROM [dbo].[fn_app_config_select_key_values]('PAYMENT_METHOD', 'CREDIT_CARD_ORDERS');

    IF ISJSON(@account_update_json) = 0
    BEGIN
        SET @message = 'Invalid JSON provided';
        RETURN;
    END;
    ELSE
    BEGIN
        SELECT @keycode = ISNULL(j.keycode, ''),
               @payment_status = ISNULL(j.payment_status, ''),
               @account_number = ISNULL(j.account_number, ''),
               @autorenewal_status = j.autorenewal_status,
               @payment_method = ISNULL(j.payment_method, ''),
               @expiration_month = ISNULL(j.expiration_month, ''),
               @expiration_year = ISNULL(j.expiration_year, ''),
               @license_key = ISNULL(j.license_key, '')
        FROM
            OPENJSON(@account_update_json)
            WITH
            (
                keycode VARCHAR(40) '$.keycode',
                payment_status VARCHAR(100) '$.payment_status',
                autorenewal_status VARCHAR(50) '$.autorenewal_status',
                payment_method VARCHAR(50) '$.payment_method',
                account_number VARCHAR(50) '$.credit_card_last_four',
                expiration_month VARCHAR(50) '$
.expiration_month',
                expiration_year VARCHAR(50) '$.expiration_year',
                license_key VARCHAR(40) '$.license_key'
            ) j;

        IF @keycode = ''
           AND @license_key = ''
        BEGIN
            SET @message = 'Required parameters not provided';
            RETURN;
        END;
    END;

    IF @keycode <> ''
       AND NOT EXISTS
    (
        SELECT 1
        FROM license
        WHERE keycode = @keycode
    )
    BEGIN
        SET @message = 'Invalid keycode';
        RETURN;

    END;

    IF @license_key <> ''
       AND TRY_CONVERT(UNIQUEIDENTIFIER, @license_key) IS NULL
    BEGIN
        SET @message = 'Invalid license_key';
        RETURN;

    END;


    IF @license_key <> ''
       AND TRY_CONVERT(UNIQUEIDENTIFIER, @license_key) IS NOT NULL
       AND NOT EXISTS
    (
        SELECT 1
        FROM license_key
        WHERE license_key = @license_key
    )
    BEGIN
        SET @message = 'License key does not exist';
        RETURN;

    END;


    IF @license_key <> ''
    BEGIN
        SELECT @license_id = lc.license_id,
               @license_distribution_method_code = dm.license_distribution_method_code
        FROM dbo.license_key lk
            INNER JOIN dbo.license lc
                ON lc.license_id = lk.license_id
            INNER JOIN dbo.license_distribution_method dm
                ON dm.license_distribution_method_id = lc.license_distribution_method_id
        WHERE license_key = @license_key;

    END;


    IF @keycode <> ''
       AND @license_id IS NULL
    BEGIN

        SELECT @license_id = lc.license_id,
               @license_distribution_method_code = dm.license_distribution_method_code
        FROM dbo.license lc
            INNER JOIN dbo.license_distribution_method dm
                ON dm.license_distribution_method_id = lc.license_distribution_method_id
        WHERE lc.keycode = @keycode;

    END;


    IF @keycode <> ''
       AND @license_key <> ''
       AND NOT EXISTS
    (
        SELECT 1
        FROM license lc
            INNER JOIN dbo.license_key lk
                ON lk.license_id = lc.license_id
        WHERE lc.keycode = @keycode
              AND lk.license_key = @license_key
    )
    BEGIN
        SET @message = 'Invalid keycode associated with the license key';
        RETURN;

    END;

    IF @license_id IS NOT NULL
       AND ISNULL(@autorenewal_status, '') = ''
    BEGIN
        SET @message = 'AR status should not be blank';
        RETURN;
    END;

    SELECT @payment_method_name = payment_method_name
    FROM dbo.payment_method
    WHERE payment_method_name = @payment_method;

    SELECT @card_type_id = card_type_id
    FROM dbo.card_type
    WHERE card_type_description = @payment_method;


    --Set the payment_method to credit card if @card_type_id is not null
    IF @payment_method_name IS NULL
       AND @card_type_id IS NOT NULL
    BEGIN
        SET @payment_method_name = @CARD_TYPE;
    END;


    IF @autorenewal_status IS NOT NULL
       AND
       (
           @autorenewal_status LIKE '%[a-z]%'
           OR @autorenewal_status = ''
           OR @autorenewal_status NOT IN ( 0, 1 )
       )
    BEGIN
        SET @message = 'Invalid auto-renewal status';
        RETURN;
    END;

    IF @payment_status <> ''
    BEGIN
        SELECT @subscription_payment_status_id = subscription_payment_status_id
        FROM dbo.subscription_payment_status
        WHERE subscription_payment_status_name = @payment_status;
    END;

    IF @payment_status <> ''
       AND @subscription_payment_status_id IS NULL
    BEGIN
        SET @message = 'Invalid payment status';
        RETURN;

    END;

    IF @subscription_payment_status_id IS NOT NULL
       AND NOT EXISTS
    (
        SELECT 1
        FROM dbo.license_next_bill_date
        WHERE license_id = @license_id
    )

    BEGIN
        SET @message = 'Failed to update payment status on missing license with next bill date';
        RETURN;

    END;


    IF @payment_method = ''
       AND
       (
           @account_number <> ''
           OR @expiration_month <> ''
           OR @expiration_year <> ''
       )
    BEGIN
        SET @message = 'Missing payment method';
        RETURN;
    END;


    IF @payment_method <> ''
       AND @payment_method_name IS NULL
    BEGIN
        SET @message = 'Payment method does not exist';
        RETURN;
    END;

    IF @payment_method <> ''
    BEGIN
        IF NOT EXISTS
        (
            SELECT 1
            FROM [dbo].[fn_app_config_select_key_values]('PORTAL_PAYMENT_METHOD', 'PORTAL') f
            WHERE f.[key] = @payment_method_name
        )
           AND @card_type_id IS NULL
        BEGIN
            SET @message = 'Invalid payment method';
            RETURN;
        END;
    END;


    IF @payment_method_name = @CARD_TYPE
       OR @card_type_id IS NOT NULL
    BEGIN

        IF @expiration_year = ''
           OR @expiration_month = ''
           OR @account_number = ''
        BEGIN
            SET @message = 'Invalid credit card details';
            RETURN;
        END;

        IF @account_number LIKE '%[a-z]%'
           OR @account_number = ''
           OR LEN(@account_number) <> 4
        BEGIN
            SET @message = 'Invalid credit card number';
            RETURN;
        END;
        IF @expiration_month LIKE '%[a-z]%'
           OR @expiration_month = ''
           OR @expiration_month < 1
           OR @expiration_month > 12
           OR
           (
               @expiration_month < DATEPART(MONTH, GETDATE())
               AND @expiration_year <= DATEPART(YEAR, GETDATE())
           )
        BEGIN
            SET @message = 'Invalid expiration month in the credit card information';
            RETURN;
        END;


        IF @expiration_year LIKE '%[a-z]%'
           OR @expiration_year = ''
           OR @expiration_year < DATEPART(YEAR, GETDATE())
           OR @expiration_year > 9999
        BEGIN
            SET @message = 'Invalid expiration year in the credit card information';
            RETURN;
        END;
    END;

    INSERT INTO @APP_CONFIG
    (
        distribution_method_code
    )
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f;

    SELECT @portal_disti_code
        = STUFF(
          (
              SELECT '/ ' + distribution_method_code FROM @APP_CONFIG FOR XML PATH('')
          ),
          1,
          2,
          ''
               );

    SELECT @payment_method_id = payment_method_id
    FROM dbo.payment_method
    WHERE payment_method_name = @payment_method_name;

    SELECT @payment_merchant_id = payment_merchant_id
    FROM dbo.payment_merchant pm
        INNER JOIN [dbo].[fn_app_config_select_key_values]('PORTAL_PAYMENT_MERCHANT', 'PORTAL') f
            ON f.[key] = pm.merchant_id;


    SELECT @payment_status_id = ps.payment_status_id
    FROM dbo.payment_status ps
        INNER JOIN [dbo].[fn_app_config_select_key_values]('PORTAL_PAYMENT_STATUS', 'PORTAL') f
            ON f.[key] = ps.payment_status_name;


    --Update CC info and AR status only for Zuora license
    IF EXISTS
    (
        SELECT 1
        FROM @APP_CONFIG a
        WHERE a.distribution_method_code = @license_distribution_method_code
    )
    BEGIN


        SET @license_attribute_license_value = @autorenewal_status;
        IF @license_attribute_license_value IS NOT NULL
        BEGIN
            --Update AR status
            EXEC dbo.usp_license_update_license_attribute_license @license_id = @license_id,                                           -- int
                                                                  @license_attribute_id = 1,                       
                    -- Autorenewal							  
                                                                  @license_attribute_license_value = @license_attribute_license_value, -- int
                                                                  @modified_by = @modified_by;                                         -- varchar(20)
        END;

        --insert/update the Payment method at the license level
        SELECT @current_payment_method_name = pm.payment_method_name,
               @payment_header_id = ph.payment_header_id
        FROM dbo.payment_header ph
            INNER JOIN dbo.payment_license pl
                ON ph.payment_header_id = pl.payment_header_id
            INNER JOIN dbo.payment_method pm
                ON pm.payment_method_id = ph.payment_method_id
        WHERE pl.license_id = @license_id;


        IF @payment_header_id IS NULL
           AND @payment_method_id IS NOT NULL
        BEGIN
            INSERT INTO dbo.payment_header
            (
                payment_merchant_id,
                payment_status_id,
                payment_method_id
            )
            VALUES
            (   @payment_merchant_id, -- payment_merchant_id - tinyint
                @payment_status_id,   -- payment_status_id - tinyint
                @payment_method_id    -- payment_method_id - tinyint

                );

            SELECT @payment_header_id = SCOPE_IDENTITY();


            INSERT INTO dbo.payment_license
            (
                payment_header_id,
                license_id,
                last_modified_by
            )
            VALUES
            (   @payment_header_id, -- payment_header_id - int
                @license_id,        -- license_id - int
                @modified_by        -- last_modified_by - varchar(200)

                );

        END;
        ELSE
        BEGIN
            IF @payment_header_id IS NOT NULL
               AND ISNULL(@current_payment_method_name, '') <> @payment_method_name
            BEGIN

                --Update the payment method on the order 
                EXEC dbo.usp_payment_update_payment_header @vendor_order_code = NULL,                   -- varchar(50)
                                                           @payment_method_name = @payment_method_name, -- varchar(50)
                                                           @payment_action_name = NULL,                 -- varchar(50)
                                                           @request_id = NULL,                          -- varchar(24)
                                                           @request_token = NULL,                       -- varchar(100)
                                                           @response_code = NULL,                       -- int
                                                           @response_message = NULL,                    -- varchar(10)
                                                           @response_text = NULL,                       -- nvarchar(max)
                                                           @merchant_id = NULL,                         -- varchar(50)
                                                           @currency_code = NULL,                       -- char(3)
                                                           @payment_header_id = @payment_header_id;

            END;
        END;

        IF @payment_header_id IS NOT NULL
           AND
           (
               @card_type_id IS NOT NULL
               OR @payment_method_name = @CARD_TYPE
           )
           AND @account_number IS NOT NULL
           AND @expiration_month IS NOT NULL
           AND @expiration_year IS NOT NULL
        BEGIN
            SET @card_type_id = ISNULL(@card_type_id, 0);
            --insert the CC info into the payment_account table
            EXEC dbo.usp_payment_update_payment_account @account_number = @account_number,   
  -- varchar(50)
                                                        @expiration_month = @expiration_month, -- tinyint
                                                        @expiration_year = @expiration_year,   -- smallint
                                                        @card_type_id = @card_type_id,         -- int
                                                        @payment_header_id = @payment_header_id;
        END;

        IF @subscription_payment_status_id IS NOT NULL
           AND EXISTS
        (
            SELECT 1
            FROM dbo.license_next_bill_date
            WHERE license_id = @license_id
        )
        BEGIN

            INSERT INTO dbo.license_next_bill_date_audit
            (
                license_next_bill_date_id,
                license_id,
                keycode,
                next_bill_date,
                last_modified_by,
                last_modified_date,
                subscription_payment_status_id,
                audit_by
            )
            SELECT license_next_bill_date_id,
                   license_id,
                   keycode,
                   next_bill_date,
                   last_modified_by,
                   last_modified_date,
                   subscription_payment_status_id,
                   @modified_by
            FROM dbo.license_next_bill_date
            WHERE license_id = @license_id
                  AND ISNULL(subscription_payment_status_id, 0) <> @subscription_payment_status_id;

            UPDATE dbo.license_next_bill_date
            SET subscription_payment_status_id = @subscription_payment_status_id,
                last_modified_date = GETDATE(),
                last_modified_by = @modified_by
            WHERE license_id = @license_id
                  AND ISNULL(subscription_payment_status_id, 0) <> @subscription_payment_status_id;



            -- Insert/Update 'CONF_HIDE_DAYS'module into dbo.license_module_license - ECOM_3308
            -- ---------------------------------------------------------------------------------
            -- 1.select
            -- ---------------------------------------------------------------------------------
            --- 1.1) 

            SELECT @license_module_id = license_module_id
            FROM dbo.license_module
            WHERE license_module_code = 'CONF_HIDE_DAYS';

            SELECT @license_module_type_id_y = license_module_type_id
            FROM dbo.license_module_type
            WHERE license_module_type_name = 'Y';

            SELECT @license_module_type_id_null = license_module_type_id
            FROM dbo.license_module_type
            WHERE license_module_type_name = 'NULL';

            --- 1.2)
            SELECT @license_change_reason_id = license_change_reason_id
            FROM dbo.license_change_reason
            WHERE license_change_reason = 'Consumer Portal Update';

            --- 1.3)
            SELECT @subscription_payment_status_id = subscription_payment_status_id
            FROM dbo.subscription_payment_status
            WHERE subscription_payment_status_name = 'Failed';

            IF EXISTS
            (
                SELECT *
                FROM dbo.license_next_bill_date lnb
                    INNER JOIN dbo.license_module_license lml
                        ON lml.license_id = lnb.license_id
                    INNER JOIN dbo.license_module lm
                        ON lm.license_module_id = lml.license_module_id
                WHERE lm.license_module_id = @license_module_id
            )
            BEGIN

                -- 2.) Insert into history table before doing the update. 
                INSERT INTO dbo.license_module_license_history
                (
                    license_module_license_id,
                    license_id,
                    license_module_id,
                    license_module_type_id,
            
        start_date,
                    end_date,
                    last_modified_date,
                    last_modified_by,
                    license_change_reason_id,
                    history_date,
                    license_status_id
                )
                SELECT lml.license_module_license_id,
                       lml.license_id,
                       lml.license_module_id,
                       lml.license_module_type_id,
                       lml.start_date,
                       lml.end_date,
                       GETDATE(),
                       'safe_update',
                       @license_change_reason_id,
                       GETDATE(),
                       lml.license_status_id
                FROM dbo.license_module_license lml
                    INNER JOIN dbo.license_next_bill_date lnb
                        ON lnb.license_id = lml.license_id
                    INNER JOIN dbo.license_module lm
                        ON lm.license_module_id = lml.license_module_id
                    INNER JOIN dbo.subscription_payment_status sps
                        ON sps.subscription_payment_status_id = lnb.subscription_payment_status_id
                WHERE lm.license_module_id = @license_module_id
                      AND lml.license_module_type_id <> (CASE
                                                             WHEN sps.subscription_payment_status_name = 'Failed' THEN
                                                                 @license_module_type_id_y
                                                             WHEN sps.subscription_payment_status_name IN ( 'Success',
                                                                                                            'Cancelled'
                                                                                                          ) THEN
                                                                 @license_module_type_id_null
                                                         END
                                                        );
                -- 2.1) CHECK 1: Update dbo.license_module_license if 'CONF_HIDE_DAYS' module is existing.
                UPDATE lml
                SET lml.license_module_type_id = (CASE
                                                      WHEN sps.subscription_payment_status_name = 'Failed' THEN
                                                          @license_module_type_id_y
                                                      WHEN sps.subscription_payment_status_name IN ( 'Success',
                                                                                                     'Cancelled'
                                                                                                   ) THEN
                                                          @license_module_type_id_null
                                                  END
                                                 )
                FROM dbo.license_next_bill_date nb
                    INNER JOIN dbo.license_module_license lml
                        ON lml.license_id = nb.license_id
                    INNER JOIN dbo.license_module lm
                        ON lm.license_module_id = lml.license_module_id
                    INNER JOIN dbo.subscription_payment_status sps
                        ON sps.subscription_payment_status_id = nb.subscription_payment_status_id
                WHERE lm.license_module_id = @license_module_id
                      AND lml.license_module_type_id <> (CASE
                                                             WHEN sps.subscription_payment_status_name = 'Failed' THEN
                                                                 @license_module_type_id_y
                                                             WHEN sps.subscription_payment_status_name IN ( 'Success',
                    
                                                                                        'Cancelled'
                                                                                                          ) THEN
                                                                 @license_module_type_id_null
                                                         END
                                                        );

            END;

            IF EXISTS
            (
                SELECT *
                FROM dbo.license_next_bill_date lnb
                    LEFT JOIN dbo.license_module_license lml
                        ON lml.license_id = lnb.license_id
                           AND lml.license_module_id = @license_module_id
                WHERE lnb.subscription_payment_status_id = @subscription_payment_status_id
                      AND lml.license_module_license_id IS NULL
            )

            --- 2.2) CHECK 2: INSERT into dbo.license_module_license if 'CONF_HIDE_DAYS' module is not existing.

            BEGIN
                INSERT INTO dbo.license_module_license
                (
                    license_id,
                    license_module_id,
                    license_module_type_id,
                    start_date,
                    end_date,
                    last_modified_date,
                    last_modified_by
                )
                SELECT lnb.license_id,
                       @license_module_id,
                       @license_module_type_id_y,
                       lcl.start_date,
                       lcl.end_date,
                       GETDATE(),
                       'safe_update'
                FROM dbo.license_next_bill_date lnb
                    INNER JOIN dbo.license_category_license lcl
                        ON lcl.license_id = lnb.license_id
                    INNER JOIN dbo.subscription_payment_status sps
                        ON sps.subscription_payment_status_id = lnb.subscription_payment_status_id
                    LEFT JOIN dbo.license_module_license lml
                        ON lml.license_id = lnb.license_id
                           AND lml.license_module_id = @license_module_id
                WHERE sps.subscription_payment_status_id = @subscription_payment_status_id
                      AND lml.license_module_license_id IS NULL;

            END;

        END;

        SET @message = 'Payment details or AR status updated successfully';
        RETURN;

    END;

    ELSE
    BEGIN
        SET @message = 'Keycode is not associated with ' + @portal_disti_code + ' distribution method';
        RETURN;

    END;


END TRY
BEGIN CATCH

    SET @message = 'Failed to update the Payment details or AR status';

    DECLARE @dbname NVARCHAR(128);
    SET @dbname = DB_NAME();
    EXEC usp_LogError @ErrorDB = @dbname;
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_registration]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_insert_registration]

(
	@product_line_id int = null,
	@keycode varchar(40),
	@first_name nvarchar(32) = null,
	@last_name nvarchar(32) = null,
	@company_name nvarchar(48) = null,
	@customer_email varchar(64) = null,
	@lang varchar(3) = null,
	@loc varchar(3) = null,
	@opt_in int = 1,
	@license_registration_invalid_id int = null,
	@customer_id int = null
--	@address_1 nvarchar(255) = null, 
--	@city nvarchar(130) = null, 
--	@state nvarchar(2) = null, 
--	@postal_code nvarchar(32) = null, 
--	@country_id int = null
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-07-24	esmart		Initial creation
	2006-08-12	esmart		Add additional error trapping
	2006-09-08	esmart		Add new input parameters for extended product registration
	2006-09-19	esmart		Add insert into license_history
	2006-11-15	esmart		Build support for WW
	2009-04-30	esmart		Invalid email release
	2015-05-27	esmart		

	DESCRIPTION
	Check to see if an customer exists, if not create a customer. Complete update to customer_id on the license table.		

*/

	set nocount on

	-- declare variables
	declare @is_existing_customer int,
		@error int,
		@system_user varchar(50),
		@response_code int,
		@message varchar(100),
		@license_change_reason_id int,
		@serial_match int,
		@license_id int,
		@customer_email_invalid_id int
	
	set @response_code = 0
	set @system_user = system_user
	set @is_existing_customer = 1
	set @license_change_reason_id = 7

	select @license_id = license_id from license where keycode = @keycode

--	select @license_id

	-- --------------------------------------------------------------------------------------------------
	-- 1) Customer
	-- --------------------------------------------------------------------------------------------------

	-- 1.1)check email against customer_email_invalid
	select @customer_email_invalid_id = customer_email_invalid_id
	from customer_email_invalid
	where customer_email = @customer_email

	
	if @customer_email_invalid_id is not null
		begin
		-- 1.1.1) insert row into license_registration_invalid
--		select customer_email_invalid_id = @customer_email_invalid_id

		if @license_registration_invalid_id is null or @license_registration_invalid_id = 0
			begin
			insert into license_registration_invalid (first_name, last_name, customer_email, lang, loc, keycode)
			values (@first_name, @last_name, @customer_email, @lang, @loc, @keycode)

			select @license_registration_invalid_id = scope_identity()

			select @response_code = -111, @message = 'invalid registration', @is_existing_customer = 0		
			end
		-- 1.1.2) set no registration required license feature
		else
			begin

			insert into license_registration_invalid (first_name, last_name, customer_email, lang, loc, keycode)
			values (@first_name, @last_name, @customer_email, @lang, @loc, @keycode)
			
			if (select count(*) from license_feature_license where license_id = @license_id and license_feature_id = 3) = 0
				begin
				-- 1.1.2.1 insert license_feature_license
				insert into license_feature_license (license_feature_id, license_id) values (3, @license_id)
				
				-- 1.1.2.2 insert comment
				insert into csi_comments (subject, comment, insert_date, insert_by, customer_id, invoice_id, license_id)
				values ('Invalid email registration', 'Attempted to register with email '+@customer_email+'. No Registration Required license feature set.', getdate(), suser_sname(), null, null, @license_id) 
				end

			select @response_code = -112, @message = 'set no registration feature', @is_existing_customer = 0	
			
			end
		
		end
	else if @customer_id is null
		begin
		-- 1.2) select customer_id for match on first_name, last_name, email
 		select @customer_id = c.customer_id
		from customer c
		inner join customer_email e
			on c.customer_id
 = e.customer_id
		where e.customer_email = @customer_email and 
			((c.first_name = @first_name and c.last_name = @last_name)) and
			e.email_status_id = 1
		
--		select customer_id = @customer_id

		-- 1.3) if customer match fails call usp_customer_insert_customer
		if @customer_id is null  -- create new customer
			begin
				
				set @is_existing_customer = 0
				exec usp_customer_insert_customer @first_name, null, @last_name, null, @opt_in, @customer_email, @company_name, @customer_id output
		
				if @customer_id is null or @customer_id = 0
					begin
						set @response_code = -200
						set @message = 'Customer insert failure'
					end	
			end
		end

	
	
	
	-- 3) add data to licence_history and update license. For WW product follow different path
	if @response_code = 0
	begin
	-- 3.1) All product line is WW
	if @product_line_id in (3,8)
		begin
		
		select @serial_match = count(*)
		from license_serial_number s
		inner join license l
			on s.license_id = s.license_id
		inner join customer c
			on l.customer_id = c.customer_id
		inner join customer_email e
			on l.customer_id = e.customer_id
		where s.serial_number = @keycode and e.customer_email = @customer_email and 
			c.first_name = @first_name and 
			c.last_name = @last_name

		--select serial_match = @serial_match

		if @serial_match = 0
			begin
			
			--select customer_id = @customer_id
			
			-- 3.1.0) insert license
			insert into license (keycode, customer_id, product_line_id, license_status_id, license_type_id, license_keycode_type_id, license_distribution_method_id, max_daily_activations, max_child_licenses, license_expiration_date)
			values ('', @customer_id, @product_line_id, 1, 1, 0, 4, 0, 0, null)
			
			if @@error <> 0 
				begin
					set @response_code = -310
					set @message = 'General SQL error - insert license'
					goto backout
				end

			set @license_id = scope_identity()
			
			-- 3.1.1) insert license_serial_number
			insert into license_serial_number (license_id,serial_number)
			values (@license_id, @keycode)

			if @@error <> 0 
				begin
					set @response_code = -311
					set @message = 'General SQL error - insert license_serial_number'
					goto backout					
				end
			
			-- 3.1.2) insert license_capability
			insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date)
			values (@license_id, 4, 1, 365, getdate(),dateadd(dd,365,getdate()))

			if @@error <> 0 
				begin
					set @response_code = -312
					set @message = 'General SQL error - insert license_capability'
					goto backout
				end

			-- 3.1.3) backout transaction if error
			backout:
			if @response_code < 0
				begin
					delete from license_capability where license_id = @license_id
					delete from license_serial_number where license_id = @license_id
					delete from license where license_id = @license_id
				end	
						
			end		
		end
	-- 3.2) All keycoded products
	else
		begin
			begin transaction
			-- 3.2.1) add existing data to license_history
			insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
			select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, getdate(), system_user
			from license
			where keycode = @keycode

			if @@error <> 0 
				begin
					set @response_code = -321
					set @message = 'General SQL error - insert license_history'
					rollback transaction
				end

			-- 3.2.2) update license
			update license
			set custom
er_id = @customer_id,
				modified_date = getdate(),
				modified_by = @system_user
			where keycode = @keycode

			if @@error <> 0 
				begin
					set @response_code = -321
					set @message = 'General SQL error - insert license_history'
					rollback transaction
				end
			commit transaction
		
		end
	end
	
	-- 5.) return results 
	select registration_success = 
			case 				when @response_code = 0 then 1
				else 0
			end,
		existing_customer = @is_existing_customer,
		license_registration_invalid_id = 
			case 				when @response_code = 0 then null
				else @license_registration_invalid_id
			end,
		response_code = @response_code,
		message = @message
		

	/*		
 
	
	success (Boolean 0/1) – did the procedure work
	existing (Boolean 0/1) – is this an already existing customer?
	*/


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_insert_site_transfer]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_insert_site_transfer]

(
	@parent_keycode varchar(40), 
	@site_keycodes nvarchar(max) = null, 
	@from_parent_keycode varchar(40) = null,
	@license_service_id	int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-08-19	esmart		Initial creation.
	2019-11-07	abelenkiy	Added support for license_parent effective_object (section 3); removed unused variables from catch
	2020-01-15	abelenkiy	Added optional license_service_id input for license_parent insert; moved license_parent insert above site_update/site_enable license_service call;
							Refactored to optimize and care for modules; added comments; added logging to permanent table license_site_transfer_log;
							Added validation that removes records from update if intended child/parent relationships already exist (to avoid multiple request timing issues);
							Added error handling if procedure called from DB and CSI validation doesn't occur 

	DESCRIPTION
	Completes site transfer from one existing parent to another. Updates end dates to be constrained by new parent for all products. 
	Called by CSI Site Transfer Tool through license_service and sends email of updated sites to Derby when complete.
		@from_parent_keycode provided and status = 1 (active) - all active sites transferred to @parent_keycode (new parent)
		@from_parent_keycode provided and status != 1 (inactive, disabled, etc.) - all sites transferred to @parent_keycode (new parent) where child end_date matches @from_parent_keycode end_date
		@from_parent_keycode not provided - all sites in @site_keycodes array transferred to @parent_keycode (new parent)

             //   ) )                          /__  ___/                                     
            //   / /       __        ___         / /         ___        ___        _   __    
           //   / /     //   ) )   //___) )     / /        //___) )   //   ) )   // ) )  ) ) 
          //   / /     //   / /   //           / /        //         //   / /   // / /  / /  
         ((___/ /     //   / /   ((____       / /        ((____     ((___( (   // / /  / /   

                                                                                                 
    //   ) )                             //    ) )                                               
   //   / /       __        ___         //    / /      __        ___        ___        _   __    
  //   / /     //   ) )   //___) )     //    / /     //  ) )   //___) )   //   ) )   // ) )  ) ) 
 //   / /     //   / /   //           //    / /     //        //         //   / /   // / /  / /  
((___/ /     //   / /   ((____       //____/ /     //        ((____     ((___( (   // / /  / /   

*/

AS

set nocount on				

begin try

		declare @from_license_status_id int, 
				@disable_date date, 
				@from_parent_license_id int, 	
				@parent_license_id int, 
				@child_license_id int, 
				@license_service_type_name varchar(50),
				@license_service_json nvarchar(max), 
				@license_parent_json nvarchar(max), 
				@modified_by varchar(20) = 'site_transfer',
				@log_guid uniqueidentifier = newid()

		declare @license_table table (license_id int, keycode varchar(50), license_category_name varchar(10), expiration_date datetime, category_type_name varchar(50),
										item_hierarchy_id tinyint, license_status_id int, license_service_id int, license_service_type_name varchar(50))
		declare @child_keycodes table (license_id int, keycode varchar(40))
		declare @license_service table (license_service_id int)
		declare @module_update_table table (license_module_license_id int)
		declare @parent_license_table table (license_id int, keycode varchar(50), license_category_name varchar(10), expiration_date datetime, catego
ry_type_name varchar(50),
										item_hierarchy_id tinyint, license_status_id int)

		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) create child keycode table from @site_keycodes input OR children belonging to @from_parent_keycode; handle errors
		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.1) return out if neither source parent nor site array provided
		if @from_parent_keycode is null and @site_keycodes is null
		begin
			raiserror ('No source parent or sites provided.',16,1)
			return
		end

		-- 1.2) set license_id from new parent keycode
		select @parent_license_id = license_id from license where keycode = @parent_keycode

		insert into @parent_license_table (license_id, keycode, license_category_name, expiration_date, category_type_name, item_hierarchy_id, license_status_id)
		select pp.license_id, pp.keycode, pp.license_category_name, pp.expiration_date, pp.category_type_name, pp.item_hierarchy_id, pp.license_status_id
		from fn_license_select_license_profile(@parent_license_id) pp

		-- 1.3) return out destination parent ineligible
		if exists (select 1 from @parent_license_table plt where plt.item_hierarchy_id = 1 and (plt.expiration_date < getdate() or plt.category_type_name = 'trial'))
		begin
			raiserror ('Destination parent ineligible due to primary category trial and/or expired.',16,1)
			return
		end

		-- 1.4) populate @child_keycodes based on @from_parent_keycode if provided
		if @from_parent_keycode is not null and @site_keycodes is null
		begin
			-- 1.4.1) set parameters
			select @from_license_status_id = l.license_status_id, 
					@disable_date = lcl.end_date,
					@from_parent_license_id = l.license_id
			from license l
				inner join license_category_license lcl on lcl.license_id = l.license_id
			where l.keycode = @from_parent_keycode

			-- 1.4.2) get all active sites from old parent if parent is active
			if @from_license_status_id = 1
			begin
				insert into @child_keycodes (license_id, keycode)
				select l.license_id, l.keycode
				from license_parent lp
					inner join license l on lp.child_license_id = l.license_id
					left join license_parent lp2 on lp2.child_license_id = l.license_id--verifying intended child/parent relationship doesn't already exist
												and lp2.parent_license_id = @parent_license_id
				where lp.parent_license_id = @from_parent_license_id 
					and l.license_status_id = 1--excluding disabled sites
					and lp2.license_parent_id is null
			end
			-- 1.4.3) if old parent is disabled, get all sites where site end_date = parent end_date
			--			e.g. partner manually disables MSP and another partner picks up sites from that parent 
			--				but only those that were ended on same date as parent
			if @from_license_status_id <> 1
			begin
				insert into @child_keycodes (license_id, keycode)
				select l.license_id, l.keycode
				from license_parent lp
					inner join license l on lp.child_license_id = l.license_id
					inner join license_category_license lcl on lcl.license_id = l.license_id
					left join license_parent lp2 on lp2.child_license_id = l.license_id--verifying intended child/parent relationship doesn't already exist
												and lp2.parent_license_id = @parent_license_id
				where lp.parent_license_id = @from_parent_license_id 
					and cast(lcl.end_date as date) = @disable_date
					and lp2.license_parent_id is null
			end

			-- 1.4.4) return out if no keys in child table; without raise error
			if not exists (select 1 from @child_keycodes)
			begin
				return
			end
		end

		-- 1.5) populate @child_keycodes with @site_keycodes json provided
		if @site_keycodes is not null
		begin
			insert into @child_keycodes (license_id, keycode)
			select l.license_id, k.keycode
			from openjson(@site_keycodes)
						with (keycode varchar(40) '$.keycode') k
			inner join license l on l.keycode = k.keycode
			left join license_parent lp2 on lp2.child_license_id = l.license_id--verifying intended child/parent relationship doesn't already exist
								and lp2.parent_license_id = @parent_license_id
			where lp2.license_parent_id is null
				and l.license_status_id = 1--excluding disabled sites
		end

		-- 1.6) raise error if @from_parent_keycode also provided and sites belong to different parents
		if @from_parent_keycode is not null
		begin
			if (select count(distinct lp.parent_license_id) from @child_keycodes ck inner join license_parent lp on lp.child_license_id = ck.license_id) > 1
			begin
				raiserror ('Site keycodes belong to multiple parents.',16,1)
				return
			end
		end

		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) call usp_license_insert_license_parent for insert/update of license_parent/license_effective_object
		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1) create json
		select @license_parent_json = (select k.license_id as child_license_id, 
											lc.license_category_id,
											@parent_license_id as parent_license_id,
											getdate() as effective_start_date,
											@license_service_id as license_service_id
									   from @child_keycodes k
										   cross apply fn_license_select_license_profile(k.license_id) p --needed to gather all categories on child license
										   inner join license_category lc on p.license_category_name = lc.license_category_name
									  for json path);

		-- 2.2) pass json above to insert proc
		if @license_parent_json is not null
			exec usp_license_insert_license_parent @license_parent_json = @license_parent_json,
													@license_effective_source_caller = 'usp_license_insert_site_transfer'

		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) update site modules to comply with site transfer business requirements
		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.1) write to history and update parent-level modules on children to site-level - license_change_reason_id 27-'Category audit'
		insert into license_module_license_history (license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, 
												last_modified_date, last_modified_by, license_change_reason_id, module_seats, license_status_id, history_by)
		output Inserted.license_module_license_id
			into @module_update_table (license_module_license_id)
		select lml.license_module_license_id, lml.license_id, lml.license_module_id, lml.license_module_type_id, lml.start_date, lml.end_date, 
				lml.last_modified_date, lml.last_modified_by, 27, lml.module_seats, lml.license_status_id, @modified_by
		from license_module_license lml
			inner join @child_keycodes k on k.license_id = lml.license_id
			inner join license_module lm on lm.parent_license_module_id = lml.license_module_id;

		if @@rowcount > 0
		begin
			-- 3.1.1) if output table was populated, update license_module_license
			update lml
			set lml.license_module_id = lm.license_module_id, 
				lml.last_modified_date = getdate(), 
				lml.last_modified_by = @modified_by
			from license_module_license lml
				inner join @module_update_table mu on mu.license_module_license_id = lml.license_module_license_id
				inner join license_module lm on lm.parent_license_module_id = lml.license_module_id;

			-- 3.1.2) delete output table for use in section 3.2
			delete @module_update_table
		end

		-- 3.2) write to
 history and update full modules to trial if parent only has trial or module is missing on parent - license_change_reason_id 30-'Full to Trial'
		--		left join to update if parent doesn't have module OR if parent has full (20) module and site has full (19)
		insert into license_module_license_history (license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, 
												last_modified_date, last_modified_by, license_change_reason_id, module_seats, license_status_id, history_by)
		output Inserted.license_module_license_id
			into @module_update_table (license_module_license_id)
		select lml.license_module_license_id, lml.license_id, lml.license_module_id, lml.license_module_type_id, lml.start_date, lml.end_date, 
				lml.last_modified_date, lml.last_modified_by, 30, lml.module_seats, lml.license_status_id, @modified_by
		from license_module_license lml
			inner join @child_keycodes k on k.license_id = lml.license_id
			inner join license_module lm on lml.license_module_id = lm.license_module_id
			left join license_module_license lml2 on lml2.license_module_id = lm.parent_license_module_id
											and lml2.license_id = @parent_license_id
		where lml.license_module_type_id < isnull(lml2.license_module_type_id, 20)

		if @@rowcount > 0
		begin
			-- 3.2.1) if output table was populated, update category_type
			update lml
			set lml.license_module_type_id = 20, --trial
				lml.last_modified_date = getdate(), 
				lml.last_modified_by = @modified_by
			from license_module_license lml
				inner join @module_update_table mu on mu.license_module_license_id = lml.license_module_license_id
		end

		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) prepare @license_table with all sites/modules to be updated/enabled with correct effective dates by license_service
		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.1) populate license table with all categories from children (even if categories don't exist on new parent)
		insert into @license_table (license_id, keycode, license_category_name, expiration_date, category_type_name, item_hierarchy_id, license_status_id)
		select cp.license_id, cp.keycode, cp.license_category_name, cp.expiration_date, cp.category_type_name
			 , cp.item_hierarchy_id, cp.license_status_id
		from @child_keycodes k
			cross apply dbo.fn_license_select_license_profile(k.license_id) cp

		-- 4.2) update expiration dates on children according to business rules and determine license_service_type to be used in update
		update lt
		set expiration_date = case when plt.license_status_id = 1 and plt.category_type_name = 'full'
										then plt.expiration_date
									when lt.expiration_date > isnull(plt.expiration_date, plt2.expiration_date)
										then isnull(plt.expiration_date, plt2.expiration_date)
									else lt.expiration_date
								end,
			lt.license_service_type_name = case when lt.license_status_id != 1 and plt.license_status_id = 1
													then 'site_enable'
												when lt.license_status_id = 1 and plt.license_status_id = 1
													then 'site_update'
												when lt.item_hierarchy_id != 1 and isnull(plt.license_status_id, 2) != 1
													then 'site_disable'
												else 'site_update'
											end
		from @license_table lt
			left join @parent_license_table plt on plt.category_type_name = lt.category_type_name
												and plt.license_category_name = lt.license_category_name
			left join @parent_license_table plt2 on plt2.item_hierarchy_id = 1--joining parent primary to children with products not on parent

		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 5.) loop licenses 
through license_service to update or enable, write to logging table to be picked up by sendmail
		-- ------------------------------------------------------------------------------------------------------------------------------------------
		-- 5.1) loop while updated flag is null in @license_table
		--		loop is based on license_id rather than record to only call license_service once per license with multiple categories
		while exists (select 1 from @license_table lt where lt.license_service_id is null)
		begin
			-- 5.1.1) select @child_license_id not yet updated and license_service_type based on the status
			select top 1 @child_license_id = lt.license_id,
						@license_service_type_name = lt.license_service_type_name
			from @license_table lt 
			where lt.license_service_id is null
			order by lt.item_hierarchy_id

			-- 5.1.2) create @license_service_json
			select @license_service_json = (select top 1 lt.keycode, @modified_by as account_name, 
													iif(@from_parent_keycode is not null, 
														'site transfer from parent keycode: ' + @from_parent_keycode,
														'site transfer to parent keycode: ' + @parent_keycode) as comment,
													(select lt2.license_category_name, lt2.expiration_date, lt2.category_type_name
													from @license_table lt2 
													where lt2.license_id = @child_license_id
														and lt2.license_service_type_name = @license_service_type_name for json path) as license_category 
											from @license_table lt
											where lt.license_id = @child_license_id
											for json path, without_array_wrapper)

			-- 5.1.3) exec license_service if not null
			if @license_service_json is not null
			begin
				insert into @license_service(license_service_id)						
				exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, 
														@service_json = @license_service_json,
														@return_license_service_id = 1
			end				
			
			-- 5.1.4) update all records in table with license_id just processed and reset vars
			update @license_table
			set license_service_id = (select top 1 license_service_id from @license_service)
			where license_id = @child_license_id
				and license_service_type_name = @license_service_type_name
				
			delete @license_service

			select @license_service_json = null, @child_license_id = null, @license_service_type_name = null
				
		end

		-- 5.2) update @license_table with new values
		update @license_table
		set lt.expiration_date = lp.expiration_date, 
			lt.category_type_name = lt.category_type_name,
			lt.license_status_id = lt.license_status_id 
		from @license_table lt
			cross apply fn_license_select_license_profile(lt.license_id) lp
		where lt.license_category_name = lp.license_category_name

		-- 5.3) write to logging table; guid will be used to group records by procedure call (because site_transfer_license_service_id may not be available)
		insert into license_site_transfer_log (site_transfer_guid, site_transfer_license_service_id, new_parent_license_id, license_id, keycode, license_category_name, expiration_date
				, category_type_name, item_hierarchy_id, license_status_id, license_service_id, license_service_type_name)
		select @log_guid, @license_service_id, @parent_license_id, lt.license_id, lt.keycode, lt.license_category_name, lt.expiration_date, lt.category_type_name
				, lt.item_hierarchy_id, lt.license_status_id, lt.license_service_id, lt.license_service_type_name
		from @license_table lt

end try

begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
