CREATE PROCEDURE [dbo].[usp_license_insert_sky_license]

/*	
	DATE		AUTHOR		REMARKS
	
	2017-01-30	acoffel		Initial creation.
	
	DESCRIPTION
	insert license_scan_license records
*/

as
  set nocount on

  begin try
  
	declare	@response_code int,
				@message varchar(100)	

		
		declare @license_remove table ([license_id] [int])

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get license data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		  --1.1) insert into @license_scan_license
		  insert into sky_license (license_id, insert_date)               
		  select distinct a.license_id,
				 getdate()
		  from sky_license_activity a
		  left join sky_license l with (nolock) 
			on a.license_id = l.license_id
		  where l.license_id is NULL
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) deletes 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		  --2.1) insert deletes 
		  insert into @license_remove (license_id)               
		  select license_id
		  from sky_license l
		  where not exists (select *
							from sky_license_activity a
							where l.license_id = a.license_id)
	
		
		 --2.2) delete
		delete from sky_license where license_id in (select license_id from @license_remove)


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
