-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_insert_trial_license]

(
		@customer_email varchar(100),
		@first_name nvarchar(225),
		@last_name nvarchar(225),
		@source varchar(20),
		@license_category_name varchar(10),
		@capability_activation_days int,
		@language_code varchar(2),
		@location_code varchar(3)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-31	esmart		Initial creation.
	2011-12-02	acoffel		added 14 day support

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@keycode varchar(40),
			@product_id int,
			@license_distribution_method_id int,
			@quantity int,
			@customer_id int,
			@response_code int,
			@message varchar(100)

			if @capability_activation_days = 14
				begin
					select @license_distribution_method_id = 676
				end
			else  
				begin
					select @license_distribution_method_id = 83
				end


			select @quantity = 1
			
			if @language_code = '' or @language_code is null
				begin
				select @language_code = 'EN'
				end

			if @location_code = '' or @location_code is null
				begin
				select @location_code = 'USA'
				end
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get customer_id
		select @customer_id = e.customer_id
		from customer_email e
		inner join customer c
			on e.customer_id = c.customer_id and c.first_name = @first_name and c.last_name = @last_name
		where e.customer_email = @customer_email and e.email_status_id = 1

		if @customer_id is null
			begin
			select @customer_id = max(e.customer_id)
			from customer_email e
			where e.customer_email = @customer_email and e.email_status_id = 1
			end

	-- 1.2) if no match for customer then insert a new customer
		if @customer_id is null
			begin
			exec usp_customer_insert_customer @first_name, null, @last_name, null, 1, @customer_email, NULL, @customer_id output
			end
					
	-- 1.3) get trial product
		select @product_id = p.product_id
		from product p
		inner join product_line_product pl
			on p.product_id = pl.product_id
		inner join product_capability c
			on p.product_id = c.product_id
		inner join product_license_category plc
			on p.product_id = plc.product_id
		inner join license_category lc
			on plc.license_category_id = lc.license_category_id
		where lc.license_category_name = @license_category_name and		
			c.capability_activation_days = @capability_activation_days and
			c.capability_id = lc.base_capability_id and 
			c.capability_type_id = 2 and
			pl.product_line_id = case
									when @location_code = 'USA' then 1
									else 6
									end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.3) insert keycode
		declare @keycode_table table (keycode varchar(40))

		insert into @keycode_table
		exec usp_license_insert_license_cart @product_id,@license_distribution_method_id,@quantity,@response_code OUTPUT,@message OUTPUT
		
		select @keycode = keycode from @keycode_table

	-- 2.8) update license with customer_id
		update license
		set customer_id = @customer_id 
		where keycode = @keycode

	-- 2.8) return keycode
		select keycode = @keycode

	end 
try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'upgrade failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

	

GO
