-- =============================================================================






CREATE PROCEDURE [dbo].[usp_license_keycode_lookup]

(
	@keycode varchar(40),
	@GUID varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2006-06-26	esmart		Initial creation.
	2006-08-11 	esmart		Add new functionality to check for capabilities that have change for upgrade. 
	2006-09-04	esmart		Modified @keycode to varchar(40) from char(20)
	2007-03-20	esmart		Add lookup into license_feature_license to see if needs_registriion can be turned off
	2008-05-09	bjordan		Added join to license_attribute_license to get autorenewal flag
	2009-03-12	esmart		Modification for new license_check table
	2010-06-28	dsmelker	Added check for mobile client license_activation records

	DESCRIPTION
	return results needed for license check
*/

AS
	set nocount on

	declare @license_id int,
		    @license_type_id int,
			@license_activation_cnt int,
			@error int
			

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) cleanup @guid before performing query and select license_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check for Mobile client and activate if not active
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		select top 1 @license_id = license_id,
					 @license_type_id = license_type_id
		from vw_license_check with (nolock) 
		where keycode = @keycode

		if @license_type_id = 6 
		Begin
			select @license_activation_cnt = count(*) 
			from license_activation with(nolock)
			where license_id = @license_id
			and guid = @guid

			if @license_activation_cnt = 0
			Begin
				begin try
					insert into license_activation
					(license_id,guid,insert_date,insert_by)
					values
					(@license_id, @guid,getdate(),system_user)
				end try
				Begin catch
					set @error = 1
				end catch
			End
		End

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) retrun results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select	--license_id,
			keycode, 
			license_status_id, 
			license_type_id, 
			capability_id, 
			capability_name, 
			capability_description, 
			capability_type_id = 
				case
					when capability_id = 11 and capability_type_id in (1,9) then 8
					else capability_type_id
				end, 
			capability_expiration_date,
			days_left = 
				case 
					when datediff(dd,getdate(),c.capability_expiration_date) > 0 then datediff(dd,getdate(),c.capability_expiration_date)
					else 0
				end,
			needs_activation = 
				(select needs_activation = 
									case
										when count(*) = 0 then 1
										when capability_type_id <> 4 and capability_activation_days > 0 and capability_activation_days is not null and capability_activation_date is null then 1
										else 0
									end
				from license_activation with (nolock)
				where license_id = @license_id and guid = @guid), 
			needs_registration,

			auto_renewal, 
			storage_account_username
		from vw_license_check c with (nolock)
		where keycode = @keycode







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_keycode_lookup_ironport]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_keycode_lookup_ironport]

(
	@keycode varchar(40),
	@GUID varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2006-06-26	esmart			Initial creation.
	2006-08-11 	esmart			Add new functionality to check for capabilities that have change for upgrade. 
	2006-09-04	esmart			Modified @keycode to varchar(40) from char(20)
	2007-03-20	esmart			Add lookup into license_feature_license to see if needs_registriion can be turned off
	2007-05-10  mscardino		Created copy for ironport, writing results to admin db
	2009-03-12		esmart		Modification for new license_check table

	DESCRIPTION
	return results needed for license check

	sample call: exec [dbo].[usp_license_keycode_lookup_ironport] 'SSDCRETLAAAAYVDJMPPQ', null
	select * from ironport_license_check_results 

*/

AS
set nocount on

	declare @needs_activation int,
		@needs_capability_activation int,
		@needs_registration int,
		@license_id int,
		@license_status_id int,
		@license_type_id int,
		@customer_id int,
		@error int,
		@row_count int,
		@insert_date datetime
	
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) cleanup @guid before performing query and select license_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end

		select @license_id = (select top 1 license_id from license with (nolock) where keycode = @keycode)
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) retrun results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select	--license_id,
			keycode, 
			license_status_id, 
			license_type_id, 
			capability_id, 
			capability_name, 
			capability_description, 
			capability_type_id = 
				case
					when capability_id = 11 and capability_type_id in (1,9) then 8
					else capability_type_id
				end, 
			capability_expiration_date,
			days_left = 
				case 
					when datediff(dd,getdate(),c.capability_expiration_date) > 0 then datediff(dd,getdate(),c.capability_expiration_date)
					else 0
				end,
			needs_activation = 
				(select needs_activation = 
									case
										when count(*) = 0 then 1
										when capability_type_id <> 4 and capability_activation_days > 0 and capability_activation_days is not null and capability_activation_date is null then 1
										else 0
									end
				from license_activation with (nolock)
				where license_id = @license_id and guid = @guid), 
			needs_registration,
			auto_renewal, 
			storage_account_username
		into #temp_license_check
		from vw_license_check c with (nolock)
		where keycode = @keycode

		select @row_count = @@rowcount, @error = @@error, @insert_date = getdate()

		if OBJECT_ID(N'ecommerce..ironport_license_check_results') IS NOT NULL
		begin
			
			if (@row_count > 0)
			begin
			
				insert into ecommerce..ironport_license_check_results
				select 	keycode, license_type_id, license_status_id, capability_id, capability_name, capability_description, capability_type_id, capability_expiration_date, days_left, needs_activation, needs_registration, auto_renewal
					, @insert_date,
 @row_count, @error
				from
					#temp_license_check
			end
			else if (@row_count = 0)
			begin
				insert into  ecommerce..ironport_license_check_results (insert_date, row_count, error)
				select @insert_date, @row_count, @error
			end

		
		end

		select * from #temp_license_check



GO
