-- PROCEDURE: [dbo].[usp_license_keycode_lookup_mercury]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_keycode_lookup_mercury]

(
	@keycode varchar(40),
	@GUID varchar(100),
	@mjv int = NULL,
	@machine_name varchar(50) = null
)

/*	
	DATE		AUTHOR			REMARKS
	2009-02-23	esmart			Initial creation.
	2009-09-10  dsmelker		Added activation
	2009-10-06	dsmelker		Added Machine Name
	2010-01-20	dsmelker		Modified to check for license category and add if not found
	2010-03-16	dsmelker		Added check for the backup capability	
	2010-04-06	dsmelker		Modified for performance
	2010-05-20	dsmelker		Added product_line_id
	2010-06-24	dsmelker		Added enterprise needs_activation change
	2010-08-31	dsmelker		Removed backup from <7.x licenses where no storage account exists
	2011-04-14	towens			add insert for missing license_check rows
	2011-11-18	esmart			keycode_alias
	2012-01-19	esmart			Add support for license_check_update_license.source 
	2012-03-06	esmart			Add @license_module_list
	2012-06-04	esmart			license_seats
	2014-05-07	acoffel			added SAUP seat handling
	2016-04-18	acoffel			forced license_check_update_license insert
	2016-05-09	acoffel			invalid keycode
	2019-04-14	esmart			Commented out section 7 - Suspect bad licenses getting into check process


	DESCRIPTION
	return results needed for license check
*/

AS
BEGIN
	set nocount on

	declare @needs_activation int,
			@needs_capability_activation int,
			@needs_registration int,
			@license_id int,
			@license_status_id int,
			@license_type_id int,
			@customer_id int,
			@auto_renewal int,
			@storage_account_username varchar(50),
			@license_category varchar(10),
			@license_category_id_calculated tinyint,
			@license_category_id tinyint,
			@capability_change_reason_id int,
			@order_item_id int,
			@modified_by varchar(50),
			@product_line_id int,
			@account_ck int,
			@cnt int,
			@keycode_alias varchar(40),
			@license_module_list varchar(max),
			@new_license_id int
			
	select @modified_by = suser_sname()

	declare @activation table (response_code int null,
							   message varchar(100) null)	
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) cleanup @guid before performing query
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.0) @license_id
		select @license_id = l.license_id,
				@product_line_id = product_line_id
		from license l with(nolock)
		where keycode = @keycode	
		
		-- 2.1) keycode_alias
		if @license_id is null 
			begin
			select @license_id = l.license_id,
					@product_line_id = l.product_line_id,
					@keycode_alias = a.keycode_alias,
					@keycode = a.keycode
			from license_keycode_alias a with(nolock)
			inner join license l with(nolock)
				on a.license_id = l.license_id
			where keycode_alias = @keycode
			end 

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
---
	-- 3.) check to see if a new activation is needed for the guid
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @needs_activation = 
			case
				when @keycode like '{%' then 0
				when count(*) = 0 then 1
				else 0
			end
		from license_activation la with(nolock)
		where license_id = @license_id
		and guid = @guid

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) Register New activation
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/*
			if @needs_activation = 1
			begin
				insert into @activation(response_code,message)
				exec usp_license_insert_activation @keycode,@guid,@machine_name
				set @needs_activation = 0
			end
*/
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) get license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select 
			@license_status_id = l.license_status_id,
			@license_type_id = l.license_type_id,
			@needs_registration = 
					case
						when l.customer_id is null then 1
						else 0
					end,
			@auto_renewal = case when license_attribute_license_value = 1 then 1 else 0 end
		from license l with(nolock)
		left join license_attribute_license lal with(nolock) 
			on l.license_id = lal.license_id
		where l.license_id = @license_id	

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.) needs registration and storage account info
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- if the license has the no registration feature override needs_registration
		select @needs_registration =
					case
						when count(*) > 0 then 0
						else @needs_registration
					end
		from license_feature_license  with(nolock)
		where license_id = @license_id and license_feature_id = 3	

		select @storage_account_username = storage_account_username
		from storage_account a with(nolock)
		inner join license_storage ls with(nolock)
			on a.license_storage_id = ls.license_storage_id
		where ls.license_id = @license_id and a.storage_account_status_id <> 1
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.) Get License Category
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 7.1) @license_category
		select @license_category = lc.license_category_name
		from license_category_license lcl with(nolock)
		inner join license_category lc with(nolock)
			on lcl.license_category_id = lc.license_category_id
		where lcl.license_id = @license_id

		-- 7.2) @license_category_id_calculated
		if @license_category is null
		Begin
			
			select @license_category_id_calculated = dbo.fn_GetLicenseCategoryId(@license_id)

			select @license_category = license_catego
ry_name
			from license_category with(nolock)
			where license_category_id = @license_category_id_calculated

			set @capability_change_reason_id = 4
			set @order_item_id = null

		End

		-- 7.3) @license_module_list
		select @license_module_list = dbo.fn_license_module_license_category_xml(@license_id,@license_category)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 8.) Check For Account
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		if @mjv >= 7 
		Begin
			select @account_ck = count(*)
			from account_license with(nolock)
			where license_id = @license_id
		end
		Else
		Begin
			set @account_ck = 0
		End
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 9.) return results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select 	keycode = case
							when @keycode_alias is not null then @keycode_alias
							else @keycode
						end,
			license_type_id = @license_type_id,
			license_status_id = @license_status_id,
			c.capability_id,
			ca.capability_name,
			ca.capability_description,
			capability_type_id = case 
									when c.capability_id = 11 and @license_category not in ('WISE','WISC') and len(isnull(@storage_account_username,'')) = 0 then 4
									when @mjv >= 7 and c.capability_id = 11 and capability_type_id in (6,7,8) then 9
					   				when @mjv < 7 and c.capability_id = 11 and c.capability_type_id in (1,9) then 8
					   				else c.capability_type_id 
								end,
			c.capability_expiration_date,
			days_left = case 
							when datediff(dd,getdate(),c.capability_expiration_date) > 0 then datediff(dd,getdate(),c.capability_expiration_date)
							when ((isnull(@product_line_id,1) in (50,51,55)) or (isnull(@product_line_id,1) not in (50,51,55) and @license_module_list like '%name="mobile"%')) and
							 ((capability_expiration_date is not null and capability_expiration_date > getdate()) or (capability_expiration_date is null)) then capability_activation_days
							else 0
						end,
			needs_activation = @needs_activation,
			needs_registration = case when @license_category in ('WISE','WISC') and @mjv >= 7 then 0 
																when @account_ck > 0 then 0
																else @needs_registration end,
			auto_renewal = @auto_renewal,
			storage_account_username = case
											when c.capability_id = 11 then @storage_account_username
											else ''
										end,
			seat_limit_reached = 0,
			license_category_desc = @license_category,
			product_line_id = @product_line_id,
			license_module_list = @license_module_list,
			license_seats = case when @license_category = 'SAUP' then s.license_seats*4 else isnull(s.license_seats,1) end 
		from license_capability c with(nolock)
		inner join capability ca with(nolock)
			on c.capability_id = ca.capability_id
		left join license_seat s with(nolock)
			on c.license_id = s.license_id
		where c.license_id = @license_id



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.) Initiate Movement of License Data to licensing DB
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--if @l
icense_category_id_calculated is not null and @license_id is not null
--Begin
	
--	insert into @activation(response_code,message)		
--	exec usp_license_update_license_category @license_id, @license_category_id_calculated, @capability_change_reason_id, @modified_by, @order_item_id

--End

--	select @cnt = count(*) from license_check_update_license
--	where license_id =  @license_id 

--if @license_id is not null and @cnt = 0 
--Begin
--	-- 2.12) insert license_summary
--	select @new_license_id = @license_id
--	exec	 @new_license_id
	
--End

--if @license_id is null 
--Begin
--	-- 2.13) insert keycode_invalid
--	insert into keycode_invalid (keycode, insert_date)
--	select @keycode, getdate()
	
--End

END




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_keycode_lookup_OLTP]
-- =============================================================================






CREATE PROCEDURE [dbo].[usp_license_keycode_lookup_OLTP]

(
	@keycode varchar(40),
	@GUID varchar(100)
)

/*	
	DATE		AUTHOR			REMARKS
	2009-02-23	esmart			Initial creation.

	DESCRIPTION
	return results needed for license check
*/

AS
	set nocount on

	declare @needs_activation int,
			@needs_capability_activation int,
			@needs_registration int,
			@license_id int,
			@license_status_id int,
			@license_type_id int,
			@customer_id int,
			@auto_renewal int,
			@storage_account_username varchar(50)
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) cleanup @guid before performing query
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @guid is null or @guid = '0' 
			begin
				set @guid = ''
			end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get license_data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @license_id = l.license_id,
			@license_status_id = l.license_status_id,
			@license_type_id = l.license_type_id,
			@needs_registration = 
					case
						when l.customer_id is null then 1
						else 0
					end,
			@auto_renewal = case when license_attribute_license_value = 1 then 1 else 0 end
		from license l with (nolock)
		left join license_attribute_license lal with (nolock)
			on l.license_id = lal.license_id
		where keycode = @keycode		
		
		-- if the license has the no registration feature override needs_registration
		select @needs_registration =
					case
						when count(*) > 0 then 0
						else @needs_registration
					end
		from license_feature_license  with (nolock)
		where license_id = @license_id and license_feature_id = 3	

		select @storage_account_username = storage_account_username
		from storage_account a with (nolock)
		inner join license_storage ls with (nolock)
			on a.license_storage_id = ls.license_storage_id
		where ls.license_id = @license_id and a.storage_account_status_id <> 1
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check to see if a new activation is needed for the guid
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @needs_activation = 
			case
				when count(*) = 0 then 1
				else 0
			end
		from license_activation with (nolock)
		where license_id = @license_id and guid = @guid

--		select @needs_capability_activation = 
--			case
--				when count(*) = 0 then 0
--				else 1
--			end	
--		from license_capability
--		where license_id = @license_id and
--			capability_type_id <> 4 and
--			capability_activation_days > 0 and capability_activation_days is not null and
--			capability_activation_date is null

	--print @needs_activation
	--print @needs_capability_activation

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return results
	-- -------------------------
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select 	keycode = @keycode,
			license_type_id = @license_type_id,
			license_status_id = @license_status_id,
			c.capability_id,
			ca.capability_name,
			ca.capability_description,
			capability_type_id = 
				case
					when c.capability_id = 11 and c.capability_type_id in (1,9) then 8
					else c.capability_type_id
				end,
			c.capability_expiration_date,
			days_left = 
				case 
					when datediff(dd,getdate(),c.capability_expiration_date) > 0 then datediff(dd,getdate(),c.capability_expiration_date)
					else 0
				end,
			needs_activation = 
				case
					when @needs_activation = 1 or @needs_capability_activation = 1 then 1
					else 0
				end,
			needs_registration = @needs_registration,
			auto_renewal = @auto_renewal,
			storage_account_username = 
				case
					when c.capability_id = 11 then @storage_account_username
					else ''
				end
		from license_capability c with (nolock)
		inner join capability ca with (nolock)
			on c.capability_id = ca.capability_id
		where c.license_id = @license_id




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_bulk_update]
-- =============================================================================

CREATE PROCEDURE  [dbo].[usp_license_message_bulk_update]

(
	@month int = null
)

/*     
	DATE                 AUTHOR        REMARKS
	2011-01-11           esmart        Initial creation
	2011-03-08           esmart        Add support for ad hoc campaigns
	2011-04-05           esmart        Add archiving
	2011-07-22           esmart        Enhance message campaign specific insert
	2011-09-05           esmart        Add bulk process for license_message_check
	2011-09-20           esmart        Add support for multiple campaign specific bulk loads by license
	2012-06-04           esmart        Modification to 2.2 to better performance
	2015-10-29           esmart        Autobilling
	2016-01-16           acoffel       remove license_message_check calc and insert
	2017-08-02           mrobbins      added usp_sfdc_update_license_message_journey call
	2020-03-20           cnovac        added logic to write to license_message on a CBEP change to set the hard cancel date if the license expires
	2020-12-24           esmart        Remove explicit CBEP logic and replace with usp_message_update_license_message_deprovision
	2022-05-04           jberry        Eric's change from 2020-12-24 is being rolled back for Cyan release 1 and will be used in release 2 to support CEP Azure on-prem - ALM defect 1193

	DESCRIPTION

*/

AS 

declare @message_count int,
        @current_count int,
        @license_id int,
        @message_campaign_id int,
        @license_message_value_str varchar(MAX),
        @batch_size int,
        @response_code int,
        @message varchar(100)

set nocount on

begin try
              
    --------------------------------------------------------------------------------------------------------------------------------
    -- 1) process licenses
    --------------------------------------------------------------------------------------------------------------------------------

	select @current_count = 1,
			@batch_size = 5000

    -- 1.1) create table with first batch. Bulk updates are handled after normal license updates
    declare @license_message_update_license table (license_id int, bulk_update int, message_campaign_id int, license_message_value_str varchar(MAX))

    insert into @license_message_update_license(license_id, bulk_update, message_campaign_id, license_message_value_str)
    select distinct top(@batch_size) license_id, bulk_update, message_campaign_id, license_message_value_str
    from license_message_update_license
    where license_id is not null
    order by bulk_update

    -- 1.2) get message count to begin loop
    select @message_count = count(*)
    from @license_message_update_license

	while @current_count <= @message_count
	begin

		select @message_campaign_id = null,
				@license_message_value_str = null

		-- 1.2.1) get @license_id, @message_campaign_id
		select @license_id = (select top 1 license_id from @license_message_update_license)

		-- 1.2.2) see if there is an explicit campaign in queue for the license= null -- we don't want the previous set to persist
		select @message_campaign_id = message_campaign_id,
				@license_message_value_str = license_message_value_str
		from license_message_update_license where license_id = @license_id and bulk_update = 2

		-- 1.2.3) if @message_campaign_id is not null then there is a ad hoc campaign to insert
		if @message_campaign_id is not null
		begin
			exec usp_message_insert_license_message_campaign @license_id, @message_campaign_id, @license_message_value_str
		end

		-- 1.2.4) autorenewal bulk update
		exec usp_message_update_license_message_autorenewal @license_id

		-- 1.2.5) autorenewal bulk update
		EXEC usp_message_update_license_messag
e_autobilling @license_id, @month

		-- 1.2.6) update license messages
		exec usp_message_update_license_messages @license_id

		-- 1.2.7) update journey license messages
		exec usp_sfdc_update_license_message_journey @license_id

		-- 1.2.8) deprovisioning

		--The explicit code for CEP in this section will be removed for Cyan release 2 and will be replaced by "usp_message_update_license_message_deprovision"
		update lm
		set lm.process_date = dateadd(dd, 90, cast(fn.expiration_date as date)),
			lm.last_modified_date = getdate()
		from license_message lm
		cross apply fn_license_select_license_profile(lm.license_id) fn
		where lm.license_id = @license_id
		and lm.message_type_id = 19 --cancel_cbep
		and lm.message_status_id = 1 --pending
		and fn.license_category_name = 'CBEP' --Carbonite endpoint product

		if @@ROWCOUNT = 0
		begin
			--if no record found to do the update, insert CBEP license
			insert into license_message (license_id, message_type_id, process_date)
			select distinct fn.license_id, 19, dateadd(dd, 90, cast(fn.expiration_date as date))
			from fn_license_select_license_profile(@license_id) fn
			where fn.license_category_name = 'CBEP'
			and fn.category_type_name = 'full'

		end
			
			--This code is being rolled back for release 1 and will be used in Cyan release 2 to support Azure on-prem.  Expiration date extension needs to be 90 days out.
			--exec usp_message_update_license_message_deprovision @license_id  

		-- 1.2.9) delete from tables
		delete from @license_message_update_license where license_id = @license_id and (message_campaign_id is null or message_campaign_id = @message_campaign_id)
		delete from license_message_update_license where license_id = @license_id and (message_campaign_id is null or message_campaign_id = @message_campaign_id)

		select @current_count = @current_count + 1

	end

end try 

begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
			   
	exec usp_LogError @ErrorDB = @DBName
              
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_insert_message_queue]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_insert_message_queue]



/*	
	DATE			AUTHOR		REMARKS
	2021-08-18		mrobbins	Initial creation.
	2022-04-26		mrobbins	altered for RED-130
	2023-04-05		schindar	altered for ecom-523. 
								608 and 611 should exclude customers already have safe account. 
								Remove additional conditions.
								Add trial keys for 611.
								change select count from 100k to 25k.
	2024-04-18		cibach		add campaign for hsbc keycodes that are over usage (>3 devices)
	2024-05-02		psatish		ECOM-4186 Fixed HSBC code bug to prevent duplicate records from being inserted into license_message table and tuned the procedure.
								Commented on campaigns 608 and 611 as no longer required

	DESCRIPTION
	Queue and manage explicit messages - was old WH progress
*/

AS
	SET NOCOUNT ON				


	DECLARE	@response_code INT,
			@message VARCHAR(100),
			@campaign_start_date DATE,
			@campaign_end_date DATE,
			@message_campaign_id INT,
			@message_campaign_class_id INT,
			@LICENSE_STATUS_ID INT

	BEGIN TRY	
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) Under utilization
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		DECLARE @HSBC_LICENSE_CAPABILITY_TYPE TABLE
		(
			CAPABILITY_TYPE_ID INT
		)


		DECLARE @message_campaigns TABLE
		(
			message_campaign_id INT,
			message_campaign_name VARCHAR(50),
			message_campaign_class_id INT,
			message_campaign_start_date DATE,
			message_campaign_end_date DATE,
			license_distribution_method_id INT,
			license_seats INT,
			product_line_id INT,
			opt_in INT,
			autorenewal_opt_in INT,
			license_category_id INT
		)
		--HSBC Capability type
		INSERT INTO @HSBC_LICENSE_CAPABILITY_TYPE
		(
			CAPABILITY_TYPE_ID
		)
		SELECT [key]
		FROM [dbo].[fn_app_config_select_key_values]('HSBC_LICENSE_CAPABILITY_TYPE', 'EMAIL_MESSAGE_CAMPAIGNS')

		--HSBC Campaign attributes
		INSERT INTO @message_campaigns
		(
			message_campaign_id,
			message_campaign_name,
			message_campaign_class_id,
			message_campaign_start_date,
			message_campaign_end_date,
			license_distribution_method_id,
			license_seats,
			product_line_id,
			opt_in,
			autorenewal_opt_in,
			license_category_id
		)
		SELECT ms.message_campaign_id,
			   ms.message_campaign_name,
			   ms.message_campaign_class_id,
			   ms.message_campaign_start_date,
			   ms.message_campaign_end_date,
			   dm.license_distribution_method_id,
			   st.license_seats,
			   pl.product_line_id,
			   ee.message_email_opt_id,
			   ar.autorenewal_opt_id,
			   lc.license_category_id
		FROM dbo.message_campaign ms
			INNER JOIN [dbo].[fn_app_config_select_key_values]('HSBC_CAMPAIGN_NAME', 'EMAIL_MESSAGE_CAMPAIGNS') f
				ON f.[key] = ms.message_campaign_name
			INNER JOIN dbo.message_campaign_license_distribution_method dm
				ON dm.message_campaign_id = ms.message_campaign_id
			INNER JOIN message_campaign_seat st
				ON st.message_campaign_id = ms.message_campaign_id
			INNER JOIN dbo.message_campaign_product_line pl
				ON pl.message_campaign_id = ms.message_campaign_id
			INNER JOIN dbo.message_campaign_license_category ct
				ON ct.message_campaign_id = pl.message_campaign_id
			INNER JOIN dbo.message_campaign_autorenewal ar
				ON ar.message_campaign_id = ms.message_campaign_id
			INNER JOIN dbo.message_campaign_email_election ee
				ON ee.message_campaign_id = ar.message_campaign_id
			INNER 
JOIN dbo.message_campaign_license_category lc
				ON lc.message_campaign_id = ms.message_campaign_id
		WHERE ms.message_campaign_enabled = 1


		SELECT @LICENSE_STATUS_ID = [key]
		FROM [dbo].[fn_app_config_select_key_values]('ACTIVE_LICENSE_STATUS', 'GENERAL')

		-- 1.0) find S2 licenses that can use more seats
		IF EXISTS(SELECT 1 FROM dbo.message_campaign WHERE message_campaign_name='280 - Explicit - S2 Churn - Underutilization')
		BEGIN
			SELECT @message_campaign_class_id=message_campaign_class_id,
				   @message_campaign_id=message_campaign_id
			FROM dbo.message_campaign
			WHERE message_campaign_name='280 - Explicit - S2 Churn - Underutilization'
			
			INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
			SELECT ls.license_id, 1, 1, GETDATE(), GETDATE()-730, GETDATE()+30, GETDATE()+30, GETDATE(), @message_campaign_id, @message_campaign_class_id, 0
			FROM [vw_explicit_campaign_license_attributes] ls
			WHERE ((CONVERT(DATE,capability_activation_date) = CONVERT(DATE,GETDATE()-14)) 
					OR  (CONVERT(DATE,capability_activation_date) = CONVERT(DATE,GETDATE()-120)) 
					OR (CONVERT(DATE,capability_activation_date) = CONVERT(DATE,GETDATE()-300)))
				AND ls.capability_expiration_date >= GETDATE()+90
				AND NOT EXISTS (SELECT license_id FROM dbo.license_message m WITH (NOLOCK) WHERE ls.license_id = m.license_id AND m.message_campaign_id IN (170,171,337,342,323,280))
				AND EXISTS (SELECT license_id FROM dbo.subscription s WITH (NOLOCK) WHERE ls.license_id = s.license_id)
		END
		IF EXISTS(SELECT 1 FROM dbo.message_campaign WHERE message_campaign_name='463 - Explicit - ONLN Underutilization')
		BEGIN
			SELECT @message_campaign_id =NULL, @message_campaign_class_id =NULL
			SELECT @message_campaign_class_id=message_campaign_class_id,
				   @message_campaign_id=message_campaign_id
			FROM dbo.message_campaign
			WHERE message_campaign_name='463 - Explicit - ONLN Underutilization'

		-- 1.1) ONLN licenses that can use more seats
			INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
			SELECT ls.license_id, 1, 1, GETDATE(), GETDATE()-730, GETDATE()+30, GETDATE()+30, GETDATE(), @message_campaign_id, @message_campaign_class_id, 0
			FROM [vw_explicit_campaign_license_attributes] ls
			WHERE --((convert(date,a2.insert_date) = convert(date,getdate()-14)) or  (convert(date,a2.insert_date) = convert(date,getdate()-120)) or (convert(date,a2.insert_date) = convert(date,getdate()-300)))
				 ls.license_distribution_method_id = 4
				AND ls.capability_expiration_date >= GETDATE()+180
				AND NOT EXISTS (SELECT license_id FROM dbo.license_message m WITH (NOLOCK) WHERE ls.license_id = m.license_id AND m.message_campaign_id IN (170,171,337,342,323,463))
				AND NOT EXISTS (SELECT license_id FROM dbo.subscription s WITH (NOLOCK) WHERE ls.license_id = s.license_id)
		END

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) cancel reason 210 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF EXISTS(SELECT 1 FROM dbo.message_campaign WHERE message_campaign_name='342 - Explicit - BBY - Auto Renewal Failure')
		BEGIN
			SELECT @message_campaign_id =NULL, @message_campaign_class_id =NULL
			SELECT @message_campaign_class_id=message_campaign_class_id,
				   @message_campaign_id=message_campaign_id
			FROM dbo.message_campaign
			WHERE message_campaign_name='342 - E
xplicit - BBY - Auto Renewal Failure'

			INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
			SELECT s.license_id, 1, 1, GETDATE(), GETDATE()-730, cancel_date, s.cancel_date, GETDATE(), @message_campaign_id, @message_campaign_class_id, 0
			FROM dbo.subscription s WITH (NOLOCK)
			INNER JOIN dbo.license_summary ls WITH (NOLOCK)
				ON s.license_id = ls.license_id
			WHERE NOT EXISTS (SELECT lm.license_id 
							 FROM dbo.license_message lm WITH (NOLOCK)
							 WHERE ls.license_id = lm.license_id
							 AND lm.message_campaign_id = @message_campaign_id)
	 			AND s.cancel_date BETWEEN GETDATE() AND GETDATE()+60
				AND s.cancel_reason = '210'
				AND ((ls.contract_detail_update IN (1,3) OR ls.contract_detail_update IS NULL))
				AND ls.autorenewal_opt_id = 1


			UPDATE lm
			SET lm.message_status_id = 6,
				lm.end_date = GETDATE(),
				lm.archive_date = GETDATE(),
				lm.last_modified_date = GETDATE()
			FROM dbo.license_message lm WITH (NOLOCK)
				INNER JOIN subscription s WITH (NOLOCK)
					ON lm.license_id = s.license_id
				INNER JOIN dbo.license_summary ls WITH (NOLOCK)
					ON lm.license_id = ls.license_id 
			WHERE ((s.contract_detail_update IN (2,4)) OR (s.cancel_date > lm.archive_date) OR (s.cancel_date IS NULL) OR (ls.autorenewal_opt_id = 0))
			AND lm.message_campaign_id = @message_campaign_id
				 
		END
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) S2 churn install
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF EXISTS(SELECT 1 FROM dbo.message_campaign WHERE message_campaign_name='491 - Explicit - S2 Churn Installation')
		BEGIN
			SELECT @message_campaign_id =NULL, @message_campaign_class_id =NULL
			SELECT @message_campaign_class_id=message_campaign_class_id,
				   @message_campaign_id=message_campaign_id
			FROM dbo.message_campaign
			WHERE message_campaign_name='491 - Explicit - S2 Churn Installation'
			
			INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
		   	SELECT  TOP 10000 com.license_id, 1, 1, GETDATE(), GETDATE()-730, GETDATE()+730, GETDATE()+730, GETDATE(), @message_campaign_id, @message_campaign_class_id, 0 
			FROM cart_order_message com WITH (NOLOCK)
				INNER JOIN subscription s WITH (NOLOCK)
					ON com.license_id = s.license_id 
				INNER JOIN cart_order_header co WITH (NOLOCK)
					ON com.cart_order_id = co.cart_order_id
				INNER JOIN order_header oh WITH (NOLOCK)
					ON oh.order_header_id = co.order_header_id
				INNER JOIN vendor_order vo WITH (NOLOCK)
					ON vo.vendor_order_id = oh.vendor_order_id
				INNER JOIN order_item oi WITH (NOLOCK)
					ON oh.order_header_id = oi.order_header_id
				INNER JOIN order_item_license oil WITH (NOLOCK)
					ON oi.order_item_id = oil.order_item_id
				INNER JOIN license_summary ls WITH (NOLOCK)
					ON oil.license_id = ls.license_id 
			WHERE vo.insert_date >= CONVERT(DATE,GETDATE()-365)
					AND NOT EXISTS (SELECT license_id FROM dbo.license_install li  WITH (NOLOCK) WHERE ls.license_id = li.license_id)	--New license is not installed
					AND NOT EXISTS (SELECT license_id FROM dbo.license_message m  WITH (NOLOCK) WHERE com.license_id = m.license_id)	--Old S2 license doesn't already have messaging
			GROUP BY com.license_id
			ORDER BY com.license_id
		


			UPDATE lm	
			SET lm.message_status_id = 6,
				lm.end_date = GETDATE(),
				lm.arc
hive_date = GETDATE(),
				lm.last_modified_date = GETDATE()
			FROM dbo.license_message lm  WITH (NOLOCK)
				INNER JOIN dbo.license_install li  WITH (NOLOCK)
					ON li.license_id = lm.license_id
			WHERE lm.message_campaign_id = @message_campaign_id
		END
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) Redbull Portal Campaign
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		/*
			SELECT @campaign_start_date = CAST(message_campaign_start_date AS DATE),
				@campaign_end_date = CAST(message_campaign_end_date AS DATE)
			FROM dbo.message_campaign
			WHERE message_campaign_id = 608

			IF CAST(GETDATE() AS DATE) >= @campaign_start_date
				AND CAST(GETDATE() AS DATE) <= @campaign_end_date
				AND DATENAME(WEEKDAY, GETDATE()) IN ('Monday','Tuesday','Wednesday','Thursday','Friday')
				BEGIN
					INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
					SELECT DISTINCT TOP 25000 ls.license_id, 1, 1, GETDATE(), GETDATE()-730, GETDATE()+90, GETDATE()+100, GETDATE(), 608, 2, 0 
					FROM dbo.license_summary ls WITH (NOLOCK)
						INNER JOIN dbo.exact_target_license_activation etla WITH (NOLOCK)
							ON etla.license_id = ls.license_id
						INNER JOIN dbo.license l
							ON ls.license_id = l.license_id
						INNER JOIN dbo.customer c
							ON c.customer_id = l.customer_id
					WHERE ls.capability_expiration_date >= GETDATE() - 7
						AND ls.product_line_id IN (SELECT product_line_id FROM  message_campaign_product_line WHERE message_campaign_id = 608)
						AND ls.capability_type_id = 1 --FULL
						AND ls.license_distribution_method_id NOT IN (SELECT license_distribution_method_id FROM dbo.message_campaign_license_distribution_method WHERE message_campaign_id =608)
						AND NOT EXISTS (SELECT license_id FROM dbo.license_message m WITH (NOLOCK) WHERE ls.license_id = m.license_id AND m.message_campaign_id = 608)
						AND NOT EXISTS (SELECT sauc.customer_id FROM dbo.safe_account_user_customer sauc WITH (NOLOCK) WHERE sauc.customer_id = c.customer_id)

				END 


				SELECT @campaign_start_date = CAST(message_campaign_start_date AS DATE),
					@campaign_end_date = CAST(message_campaign_end_date AS DATE)
				FROM dbo.message_campaign
				WHERE message_campaign_id = 611

				IF CAST(GETDATE() AS DATE) >= @campaign_start_date
					AND CAST(GETDATE() AS DATE) <= @campaign_end_date
					AND DATENAME(WEEKDAY, GETDATE()) IN ('Monday','Tuesday','Wednesday','Thursday','Friday')
					BEGIN
						INSERT INTO license_message (license_id, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
						SELECT DISTINCT TOP 25000 ls.license_id, 1, 1, GETDATE(), GETDATE()-730, GETDATE()+90, GETDATE()+100, GETDATE(), 611, 2, 0 
						FROM dbo.license_summary ls WITH (NOLOCK)
							INNER JOIN dbo.exact_target_license_activation etla WITH (NOLOCK)
								ON etla.license_id = ls.license_id
							INNER JOIN dbo.license l
								ON ls.license_id = l.license_id
							INNER JOIN dbo.customer c
								ON c.customer_id = l.customer_id
						WHERE ls.capability_expiration_date >= GETDATE() - 7
							AND ls.product_line_id IN (SELECT product_line_id FROM  message_campaign_product_line WHERE message_campaign_id = 611)
							AND ls.capability_type_id IN( 1,2) --FULL and TRIAL
							AND ls.license_distribution_method_id IN (SELECT license_distribution_method_id FROM dbo.message_campaign_license_distribution_method W
HERE message_campaign_id =611)
							AND NOT EXISTS (SELECT license_id FROM dbo.license_message m WITH (NOLOCK) WHERE ls.license_id = m.license_id AND m.message_campaign_id = 611)
							AND NOT EXISTS (SELECT sauc.customer_id FROM dbo.safe_account_user_customer sauc WITH (NOLOCK) WHERE sauc.customer_id = c.customer_id)


				END 
				*/

		IF EXISTS
		(
			SELECT 1
			FROM @message_campaigns
			WHERE CAST(GETDATE() AS DATE) >= message_campaign_start_date
				  AND CAST(GETDATE() AS DATE) <= message_campaign_end_date
		)
		BEGIN
				;WITH cte
				AS (SELECT DISTINCT
						   ls.license_id,
						   ms.opt_in,
						   ms.license_category_id,
						   ms.license_seats,
						   ms.message_campaign_id,
						   ms.message_campaign_class_id,
						   ms.message_campaign_end_date
					FROM dbo.license_summary ls
						INNER JOIN dbo.sky_license_activity sla
							ON sla.license_id = ls.license_id
						INNER JOIN @message_campaigns ms
							ON ms.license_distribution_method_id = ls.license_distribution_method_id
							   AND ms.product_line_id = ls.product_line_id
							   AND ms.autorenewal_opt_in = ls.autorenewal_opt_id
						INNER JOIN @HSBC_LICENSE_CAPABILITY_TYPE ct
							ON ct.CAPABILITY_TYPE_ID = ls.capability_type_id
					WHERE  ls.license_status_id = @LICENSE_STATUS_ID
						  AND sla.device_count > 3)
				INSERT INTO dbo.license_message
				(
					license_id,
					message_type_id,
					message_status_id,
					insert_date,
					process_date,
					end_date,
					archive_date,
					last_modified_date,
					message_campaign_id,
					message_campaign_class_id,
					update_attempts
				)
				SELECT ls.license_id,
					   1,
					   1,
					   GETDATE(),
					   GETDATE() - 730,
					   ct.message_campaign_end_date,
					   ct.message_campaign_end_date,
					   GETDATE(),
					   ct.message_campaign_id,
					   ct.message_campaign_class_id,
					   0
				FROM cte ct
					INNER JOIN dbo.license_summary ls
						ON ls.license_id = ct.license_id
						   AND ls.license_category_id=ct.license_category_id
						   AND ls.opt_in=ct.opt_in
						   AND ls.license_seats=ct.license_seats
					LEFT JOIN dbo.license_message lm
						ON lm.license_id = ls.license_id
						   AND lm.message_campaign_id = ct.message_campaign_id
				WHERE lm.license_message_id IS NULL

		END
		END TRY 

		BEGIN CATCH

			SET @response_code = -200
			SET @message = CASE WHEN @message IS NULL THEN 'insert failed'
								ELSE @message END

			DECLARE @DBName NVARCHAR(128)
			SET @DBName = DB_NAME()
			EXEC usp_LogError @ErrorDB = @DBName
		
		END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_insert_next_message_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_insert_next_message_batch]

/*	
	DATE		AUTHOR		REMARKS
	2013-07-02	esmart		Initial creation.

	DESCRIPTION
	Select license messages to be processed and insert bulk update
*/

AS
	set nocount on				

	declare @transaction_date datetime,
			@response_code int,
			@message varchar(100)
			
			select @transaction_date = getdate()
			
			select @transaction_date = dateadd(dd,1,@transaction_date)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_message_update_license table (license_message_id int, license_id int, bulk_update tinyint, next_message_campaign_id int, license_message_value_str varchar(max), process_date datetime default getdate())
	
	insert into @license_message_update_license(license_message_id, license_id, bulk_update, next_message_campaign_id, license_message_value_str)
	select distinct m.license_message_id, m.license_id, bulk_update = 2, s.next_message_campaign_id, 
		license_message_value_str = 'message_campaign_id='+convert(varchar(20),s.next_message_campaign_id)
		--license_message_value_str = case
		--								when v.value_id is not null then 'message_campaign_id='+convert(varchar(20),s.next_message_campaign_id)+',cart_discount_id='+convert(varchar(20),v.value_id)
		--								else 'message_campaign_id='+convert(varchar(20),s.next_message_campaign_id)
		--							end
		--,m.process_date
		--, m.message_campaign_id
	from license_message m with (nolock) 
	inner join message_campaign_sequence s with (nolock) 
		on m.message_campaign_id = s.message_campaign_id
	--left join license_message_value v with (nolock)
	--	on m.license_message_id = v.license_message_id and v.message_value_type_id = 1
	left join license_message mn with (nolock)
		on m.license_id = mn.license_id and mn.message_campaign_id = s.next_message_campaign_id
	where mn.license_message_id is null and m.message_status_id = 1 and m.message_type_id = 1 and m.process_date < @transaction_date 
	
	select license_id, bulk_update, next_message_campaign_id, license_message_value_str from @license_message_update_license

	update license_message
	set message_status_id = 3
	where license_message_id in (select license_message_id from @license_message_update_license)
		
	insert into license_message_update_license(license_id, bulk_update)
	select license_id, bulk_update from @license_message_update_license
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
