CREATE PROCEDURE [dbo].[usp_license_message_insert_update_message_queue]

(		
	@license_message_id int,
	@message_status_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2012-01-26	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	begin try

	set nocount on 

	-- 1) insert task queue 
	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100)

	select @system_user = suser_sname(),
			@db_name = db_name()

	select @task_number = @license_message_id --(select isnull(max(task_number),0) from tasks..task_table) + 10
		select @sql_string = 
			'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
			' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_message_update_message ' + convert(varchar(10),@license_message_id) + ',' + convert(varchar(10),@message_status_id) + '''' + ',0,getdate()) '

--	print @sql_string

	exec (@sql_string)

	exec tasks..usp_queue_task @license_message_id

	end try

	begin catch


	set @response_code = -200
	set @message = case when @message is null then 'Could not insert task for @license_message_id = ' + convert(varchar(20),@license_message_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_PURGE]
-- =============================================================================
CREATE PROC usp_license_message_PURGE
AS
		

	DECLARE	@archive_date DATETIME,
			@message_count INT,
			@batch_size INT,
			@current_batch INT,
			@total_batch INT,
			@response_code INT,
			@message VARCHAR(100),
			@last_dropcount INT

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) Set up batch
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	SELECT @archive_date = GETDATE(),
			@batch_size = 1800,
			@current_batch = 1,
			@last_dropcount = 1 -- anything positive to get the loop going
	
	-- build the "pillar" table...
	CREATE TABLE #batchlist (
		lm_id INT NOT NULL PRIMARY KEY CLUSTERED
	)



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) Archive 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) loop through batches
	WHILE @last_dropcount > 0
	BEGIN
			
	
		-- flush and fill the batch "pillar"
		TRUNCATE TABLE #batchlist
	
		INSERT INTO #batchlist (lm_id)
		SELECT TOP (@batch_size) license_message_id
		FROM license_message 
		WHERE archive_date < @archive_date
		ORDER BY license_message_id -- helps with the clustered PK



		-- 2.1) insert into license_message_value_archive and delete
		INSERT INTO license_message_value_archive(
			license_message_value_id, 
			license_message_id, 
			message_value_type_id, 
			value_id)
		SELECT 
			v.license_message_value_id, 
			v.license_message_id, 
			v.message_value_type_id, 
			v.value_id
		FROM 
			license_message_value v
		INNER JOIN
			#batchlist bl
			ON bl.lm_id = v.license_message_id


		DELETE
			v
		FROM 
			license_message_value v
		INNER JOIN
			#batchlist bl
			ON bl.lm_id = v.license_message_id
		


		-- 2.2) insert into license_message_archive and delete
		INSERT INTO license_message_archive(
			license_message_id, 
			license_id, 
			license_message_key, 
			message_type_id, 
			message_status_id, 
			insert_date, 
			process_date, 
			end_date)
		SELECT
			lm.license_message_id, 
			lm.license_id, 
			lm.license_message_key, 
			lm.message_type_id, 
			lm.message_status_id, 
			lm.insert_date, 
			lm.process_date, 
			lm.end_date
		FROM 
			license_message lm
		INNER JOIN
			#batchlist bl
			ON bl.lm_id = lm.license_message_id

		

		DELETE 
			lm
		FROM 
			license_message lm
		INNER JOIN
			#batchlist bl
			ON bl.lm_id = lm.license_message_id

		SET @last_dropcount = @@ROWCOUNT


		SELECT @current_batch = @current_batch + 1
	END

	DROP TABLE #batchlist


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_retry_autorenewal_message]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_license_message_retry_autorenewal_message]


(
	@days_back INT, 
	@update_attempts INT,
	@simulation BIT = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2019-12-16	esmart		Initial creation.
	2022-12-02	gblandford	https://jira.opentext.com/browse/ECOM-367 
							- use new payment_gateway architecture to determine	the response codes to retry
							- added schemas

	DESCRIPTION
	Update license_message for failed AR carts
*/

AS

SET NOCOUNT ON				

BEGIN TRY

		DECLARE	@reprocess_date DATE, 
				@start_date DATE, 
				@end_date DATE, 
				@min_license_expiration_date DATE, 
				@response_code INT,
				@message VARCHAR(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) set values
		select @reprocess_date = getdate(), 
				@start_date = dateadd(dd,-@days_back,@reprocess_date),
				@end_date = dateadd(dd,1,@start_date)

		select @start_date, @end_date
		
		-- 1.2) find carts to reprocess
		declare @reprocess table (
			license_message_id int
			, license_id int
			, response_code varchar(50)
			, payment_merchant_id int)

		insert into @reprocess (
			license_message_id
			, license_id
			, response_code
			, payment_merchant_id
		)
		select 
			lm.license_message_id
			, lm.license_id
			, r.response_code
			, ph.payment_merchant_id
		from dbo.cart_order c with (nolock)
		inner join dbo.cart_order_message m with (nolock)
			on c.cart_order_id = m.cart_order_id
		inner join dbo.license_message lm with (nolock)
			on m.message_key = lm.license_message_key
		inner join dbo.payment_header ph with (nolock)
			on c.cart_order_id = ph.cart_order_id
		inner join dbo.payment_response r with (nolock)
			on ph.payment_header_id = r.payment_header_id --and r.response_message <> ''Successful''
		where c.site_id = 'AUTORENEWAL' and c.insert_date >= @start_date  and c.insert_date < @end_date and lm.message_status_id = 6 and ph.payment_method_id <> 14
			and lm.process_date >= @start_date and lm.process_date < @end_date
		order by lm.process_date

		-- 1.3) view messages to update
		if @simulation = 1
			begin
				SELECT t.*, cl.end_date, lm.*
				from @reprocess t
				inner join license_message lm with (nolock)
					on t.license_message_id = lm.license_message_id
				inner join license_category_license cl with (nolock)
					on lm.license_id = cl.license_id
				inner join dbo.payment_merchant pm 
					on pm.payment_merchant_id = t.payment_merchant_id
				inner join dbo.payment_merchant_gateway pmg 
					on pm.payment_merchant_id = pmg.payment_merchant_id
				inner join dbo.payment_response_code prc 
					on prc.response_code = t.response_code 
					and	prc.payment_gateway_id = pmg.payment_gateway_id
				where prc.retry = 1
				and lm.message_status_id = 6 
				and lm.update_attempts = @update_attempts  --and cl.end_date < dateadd(dd,8,@end_date)
						order by lm.process_date

				return
			end

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) update
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) update for reprocess
		update lm
			set lm.message_status_id = 1
				, lm.last_modified_date = getdate()
		from @reprocess t
		inner join dbo
.license_message lm
			on t.license_message_id = lm.license_message_id
		inner join dbo.license_category_license cl
			on lm.license_id = cl.license_id
		inner join dbo.payment_merchant pm 
			on pm.payment_merchant_id = t.payment_merchant_id
		inner join dbo.payment_merchant_gateway pmg 
			on pm.payment_merchant_id = pmg.payment_merchant_id
		inner join dbo.payment_response_code prc 
			on prc.response_code = t.response_code 
			and	prc.payment_gateway_id = pmg.payment_gateway_id
		where prc.retry = 1
		and lm.message_status_id = 6 
		and lm.update_attempts = @update_attempts 
		and cl.end_date < dateadd(dd,8,@end_date)
	

end TRY

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_select_autorenewal_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_select_autorenewal_batch]

(
	@message_type_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-01-29	esmart		initial create
	2012-04-02	esmart		Performance improvement
	2016-07-25	cnovac		added @message_type_id

	DESCRIPTION
	select license message 
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = getdate()
	from license_message m with (nolock)
	where m.process_date <= getdate() and 
		m.message_type_id = isnull(@message_type_id, 3) and 
		m.message_status_id in (1,2,4) 

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
