CREATE PROCEDURE [dbo].[usp_license_message_select_message_campaign_summary]

(
	@message_campaign_name varchar(256) = null,
	@message_campaign_enabled_description varchar(50) = null,
	@message_campaign_class_name varchar(50) = null,
	@product_line_id int = null,
	@license_category_id int = null,
	@license_seats int = null,
	@inclusive tinyint = null,
	@license_distribution_method_code varchar(4) = null,
	@start_date datetime = null, 
	@end_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2013-03-29	esmart		Results when distribution method is not set
	2014-04-29	esmart		Cart discount list for multiple cart_discounts
	2016-12-01	mrobbins	added license_renewal list and account_created list
	2018-05-25	mrobbins	extended message_campaign_name
	2018-08-22	acoffel		license_keycode_type
	2019-02-02	jnavarra	Added app store status
	2019-05-29	mrobbins	changed to allow 
for no license_category in campaign for AR notification campaigns on insert into @message_campaign_summary

	DESCRIPTION
	select message campaigns
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @message_campaigns int, @message_campaign_id int

		declare @message_campaign_autorenewal_list varchar(20),
				@message_campaign_seat_list varchar(20),
				@message_campaign_license_distribution_method_list varchar(max),
				@message_campaign_license_category_list varchar(100),
				@message_campaign_email_election_list varchar(20),
				@message_campaign_platform_list varchar(100),
				@message_campaign_product_line_list varchar(100),
				@license_distribution_method_list varchar(200),
				@language_location_list varchar(200),
				@trial_list varchar(20),
				@cart_discount_list varchar(500),
				@message_campaign_renewal_status_list varchar(500),
				@message_campaign_account_creation_status_list varchar(500),
				@message_campaign_license_keycode_type_list varchar(100),
				@message_app_store_status_list VARCHAR(500)

		declare @message_campaign_summary table 
			(
				message_campaign_id int, 
				message_campaign_name varchar(65), 
				message_campaign_key varchar(36),
				next_message_campaign_id int, 
				message_campaign_enabled_description varchar(50),
				message_campaign_start_date datetime,
				message_campaign_end_date datetime,
				message_campaign_class_name varchar(50), 
				message_measure_point_name varchar(50),
				message_measure_days int, message_measure_end_days int, message_duration_days int,
				message_campaign_seat_list varchar(20), 
				message_campaign_license_category_list varchar(100), 
				message_campaign_autorenewal_list varchar(20),
				message_campaign_email_election_list varchar(20),
				message_campaign_platform_list varchar(100),
				message_campaign_product_line_list varchar(100),
				license_distribution_method_inclusive tinyint,
				license_distribution_method_list varchar(200),
				language_location_list varchar(200),
				trial_list varchar(20),
				cart_discount_list varchar(500),
				message_campaign_renewal_status_list varchar(500),
				message_campaign_account_creation_status_list varchar(500),
				message_campaign_license_keycode_type_list varchar(100),
				message_app_store_status_list VARCHAR(500)
			)

		IF @license_category_id IS NOT NULL
			BEGIN

				insert into @message_campaign_summary(message_campaign_id, message_campaign_name, message_campaign_key, next_message_campaign_id, message_campaign_class_name, message_campaign_enabled_description, message_campaign_start_date, message_campaign_end_date, message_measure_point_name, message_measure_days, message_measure_end_days, message_duration_days, license_distribution_method_inclusive)
				select distinct m.message_campaign_id, isnull(m.message_campaign_name,m.message_campaign_description), m.message_campaign_key, s.next_message_campaign_id, c.message_campaign_class_name, e.message_campaign_enabled_description, m.message_campaign_start_date, m.message_campaign_end_date, p.message_measure_point_name, mp.message_measure_days, mp.message_measure_end_days, mp.message_duration_days,
					license_distribution_method_inclusive = (select top 1 inclusive from message_campaign_license_distribution_method where message_campaign_id = m.message_campaign_id)
				from message_campaign m
				inner join message_campaign_class c
					on m.message_campaign_class_id = c.message_campaign_class_id
				inner join message_c
ampaign_measure_point mp
					on m.message_campaign_id = mp.message_campaign_id
				inner join message_measure_point p
					on mp.message_measure_point_id = p.message_measure_point_id
				inner join message_campaign_enabled e
					on m.message_campaign_enabled = e.message_campaign_enabled
				left join message_campaign_sequence s
					on m.message_campaign_id = s.message_campaign_id
				left join message_campaign_product_line pl
					on m.message_campaign_id = pl.message_campaign_id
				left join message_campaign_seat st
					on m.message_campaign_id = st.message_campaign_id
				left join message_campaign_license_category lc
					on m.message_campaign_id = lc.message_campaign_id
				where pl.product_line_id = case when @product_line_id is null then pl.product_line_id else @product_line_id end and
						st.license_seats = case when @license_seats is null then st.license_seats else @license_seats END  AND
						lc.license_category_id = case when @license_category_id is null then lc.license_category_id else @license_category_id END
			END
		ELSE
			BEGIN 
				insert into @message_campaign_summary(message_campaign_id, message_campaign_name, message_campaign_key, next_message_campaign_id, message_campaign_class_name, message_campaign_enabled_description, message_campaign_start_date, message_campaign_end_date, message_measure_point_name, message_measure_days, message_measure_end_days, message_duration_days, license_distribution_method_inclusive)
				select distinct m.message_campaign_id, isnull(m.message_campaign_name,m.message_campaign_description), m.message_campaign_key, s.next_message_campaign_id, c.message_campaign_class_name, e.message_campaign_enabled_description, m.message_campaign_start_date, m.message_campaign_end_date, p.message_measure_point_name, mp.message_measure_days, mp.message_measure_end_days, mp.message_duration_days,
					license_distribution_method_inclusive = (select top 1 inclusive from message_campaign_license_distribution_method where message_campaign_id = m.message_campaign_id)
				from message_campaign m
				inner join message_campaign_class c
					on m.message_campaign_class_id = c.message_campaign_class_id
				inner join message_campaign_measure_point mp
					on m.message_campaign_id = mp.message_campaign_id
				inner join message_measure_point p
					on mp.message_measure_point_id = p.message_measure_point_id
				inner join message_campaign_enabled e
					on m.message_campaign_enabled = e.message_campaign_enabled
				left join message_campaign_sequence s
					on m.message_campaign_id = s.message_campaign_id
				left join message_campaign_product_line pl
					on m.message_campaign_id = pl.message_campaign_id
				left join message_campaign_seat st
					on m.message_campaign_id = st.message_campaign_id
				left join message_campaign_license_category lc
					on m.message_campaign_id = lc.message_campaign_id
				where pl.product_line_id = case when @product_line_id is null then pl.product_line_id else @product_line_id end and
						st.license_seats = case when @license_seats is null then st.license_seats else @license_seats END
           END

		
		if @start_date is not null
			begin
			delete from @message_campaign_summary
			where message_campaign_start_date > @start_date
			end

		if @end_date is not null
			begin
			delete from @message_campaign_summary
			where message_campaign_end_date < @end_date
			end		

		select @message_campaigns = count(*), @message_campaign_id = 1 from message_campaign

		while @message_campaigns >= @message_campaign_id
			begin
			-- 1) @message_campaign_seat_list
			select @message_campaign_seat_list = coalesce(@message_campaign_seat_list+', ','')+ cast(convert(varchar(10),license_seats) as varchar(100)) from message_campaign_seat where message_campaign_id = @message_campaign_id
	
			-- 2) @message_campaign_license_category_list
			select @message_campaign_license_category_list = coalesce(@message_campaign_licen
se_category_list+', ','')+ cast(c.license_category_name as varchar(100)) 
			from message_campaign_license_category m
			inner join license_category c
				on m.license_category_id = c.license_category_id
			where message_campaign_id = @message_campaign_id

			-- 3) @message_campaign_autorenewal_list
			select @message_campaign_autorenewal_list = coalesce(@message_campaign_autorenewal_list+', ','')+ cast(convert(varchar(10),autorenewal_opt_id) as varchar(100)) from message_campaign_autorenewal where message_campaign_id = @message_campaign_id
	
			-- 4) @message_campaign_email_election_list
			select @message_campaign_email_election_list = coalesce(@message_campaign_email_election_list+', ','')+ cast(convert(varchar(10),message_email_opt_id) as varchar(100)) from message_campaign_email_election where message_campaign_id = @message_campaign_id
	
			-- 5) message_campaign_platform_list
			select @message_campaign_platform_list = coalesce(@message_campaign_platform_list+', ','')+ cast(c.massage_platform_name+'('+ isnull(mc.message_cycle_description,'') +')' as varchar(100))
			from message_campaign_platform m
			inner join message_platform c
				on m.message_platform_id = c.message_platform_id
			left join message_cycle mc
				on m.message_cycle_id = mc.message_cycle_id
			where message_campaign_id = @message_campaign_id

			-- 6) @message_campaign_product_line_list
			select @message_campaign_product_line_list = coalesce(@message_campaign_product_line_list+', ','')+ cast(convert(varchar(50),product_line_description) as varchar(100)) 
			from message_campaign_product_line m
			inner join product_line l
				on m.product_line_id = l.product_line_id
			where message_campaign_id = @message_campaign_id
	
			-- 7) license_distribution_method_list
			select @license_distribution_method_list = coalesce(@license_distribution_method_list+', ','')+ cast(convert(varchar(4),license_distribution_method_code) as varchar(100)) 
			from message_campaign_license_distribution_method m
			inner join license_distribution_method d
				on m.license_distribution_method_id = d.license_distribution_method_id
			where message_campaign_id = @message_campaign_id

			if @license_distribution_method_list is null
				select @license_distribution_method_list = '  '

			-- 9) license_distribution_method_list
			select @language_location_list = coalesce(@language_location_list+', ','')+ cast(language_code+'/'+location_code as varchar(100)) 
			from message_campaign_language_location
			where message_campaign_id = @message_campaign_id

			-- 10) @@trial_list
			select @trial_list = coalesce(@trial_list+', ','')+ cast(convert(varchar(10),trial) as varchar(100)) from message_campaign_trial where message_campaign_id = @message_campaign_id
	
			-- 11) @cart_discount_list
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')+ cast(convert(varchar(50),d.cart_discount_description) as varchar(500)) 
			from message_campaign_cart_discount m
			inner join cart_discount d
				on m.cart_discount_id = d.cart_discount_id
			where m.message_campaign_id = @message_campaign_id

			 --12) @message_campaign_renewal_status_list
			select @message_campaign_renewal_status_list = coalesce(@message_campaign_renewal_status_list+', ','')+ cast(convert(varchar(100),lrs.license_renewal_status_description) as varchar(100)) 
			from message_campaign_renewal_status  mcrs
				inner join license_renewal_status lrs
					on mcrs.renewal_status = lrs.license_renewal_status_id
			where message_campaign_id = @message_campaign_id

			-- 13) @message_campaign_account_creation_status_list
			select @message_campaign_account_creation_status_list = coalesce(@message_campaign_account_creation_status_list+', ','')+ cast(convert(varchar(100),acs.account_creation_status_description) as varchar(100)) 
			from message_campaign_account_creation_status mcacs
				inner join account_creation_status acs
					on mcacs.account_creation_status 
= acs.account_creation_status_id
			where message_campaign_id = @message_campaign_id

			-- 14) @message_campaign_license_keycode_type_list
			select @message_campaign_license_keycode_type_list = coalesce(@message_campaign_license_keycode_type_list+', ','')+ cast(convert(varchar(100),t.license_keycode_type_id) as varchar(100)) 
			from message_campaign_license_keycode_type t 
			where t.message_campaign_id = @message_campaign_id

			-- 15) @message_app_store_status_list
			SELECT @message_app_store_status_list = COALESCE(@message_app_store_status_list + ', ', '') + CAST(CONVERT(VARCHAR(500), s.app_store_status) AS VARCHAR(500))
			FROM dbo.message_campaign_app_store_status s
			WHERE s.message_campaign_id = @message_campaign_id

			-- 16) update @message_campaign_summary
			update @message_campaign_summary
			set message_campaign_seat_list = @message_campaign_seat_list, 
				message_campaign_license_category_list = @message_campaign_license_category_list,
				message_campaign_autorenewal_list = @message_campaign_autorenewal_list,
				message_campaign_email_election_list = @message_campaign_email_election_list,
				message_campaign_platform_list = @message_campaign_platform_list,
				message_campaign_product_line_list = @message_campaign_product_line_list,
				license_distribution_method_list = @license_distribution_method_list,
				language_location_list = @language_location_list,
				trial_list = @trial_list,
				cart_discount_list = @cart_discount_list,
				message_campaign_renewal_status_list = @message_campaign_renewal_status_list,
				message_campaign_account_creation_status_list = @message_campaign_account_creation_status_list,
				message_campaign_license_keycode_type_list = @message_campaign_license_keycode_type_list,
				message_app_store_status_list = @message_app_store_status_list
			where message_campaign_id = @message_campaign_id

			--select message_campaign_seat_list = @message_campaign_seat_list, message_campaign_license_category_list = @message_campaign_license_category_list
	
			select @message_campaign_seat_list = null, 
					@message_campaign_license_category_list = null,
					@message_campaign_autorenewal_list = null,
					@message_campaign_email_election_list = null,
					@message_campaign_platform_list = null,
					@message_campaign_product_line_list = null,
					@license_distribution_method_list = null,
					@language_location_list = null,
					@trial_list = null,
					@cart_discount_list = null,
					@message_campaign_renewal_status_list = null,
					@message_campaign_account_creation_status_list = NULL,
					@message_campaign_license_keycode_type_list = NULL,
					@message_app_store_status_list = NULL

			select @message_campaign_id = @message_campaign_id + 1
			end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) return results
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if @message_campaign_name is null begin select @message_campaign_name = '' end
		if @license_distribution_method_code is null begin select @license_distribution_method_code = '' end
		update @message_campaign_summary set license_distribution_method_inclusive = 0 where license_distribution_method_inclusive is null 

		select message_campaign_id,
		message_campaign_name, 
		message_campaign_key,
		next_message_campaign_id,
		message_campaign_enabled_description, 
		message_campaign_start_date, 
		message_campaign_end_date,
		message_campaign_class_name,
		message_measure_point_name,
		message_measure_days,
		message_measure_end_days,
		message_duration_days,
		message_campaign_seat_list,
		message_campaign_license_category_list,
		message_campaign
_autorenewal_list,
		message_campaign_email_election_list,
		message_campaign_platform_list,
		message_campaign_product_line_list,
		license_distribution_method_inclusive,
		license_distribution_method_list, 
		language_location_list, 
		trial_list, 
		cart_discount_list,
		message_campaign_renewal_status_list,
		message_campaign_account_creation_status_list,
		message_campaign_license_keycode_type_list,
		message_app_store_status_list
		from @message_campaign_summary
		where message_campaign_name like '%'+@message_campaign_name+'%' and
			message_campaign_enabled_description = case
														when @message_campaign_enabled_description is null then message_campaign_enabled_description
														else @message_campaign_enabled_description
													end and
			message_campaign_class_name = case
														when @message_campaign_class_name is null then message_campaign_class_name
														else @message_campaign_class_name
													end and
			license_distribution_method_inclusive = case
														when @inclusive is null then license_distribution_method_inclusive
														else @inclusive
													end and
			license_distribution_method_list like '%'+@license_distribution_method_code+'%'

			


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_select_message_details]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_select_message_details]

(
		@license_message_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-07-18	esmart		Initial creation.
	2011-10-25	esmart		Add nolock hints	
	2012-12-03	esmart		Add lookup in license_key
	2019-10-03	jnavarra	Add license_channel_id

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@keycode varchar(40),
			@license_message_id int,	
			@license_channel_id int,	
			@customer_id int,
			@customer_email varchar(100),
			@first_name nvarchar(225),
			@last_name nvarchar(225),
			@insert_date datetime,
			@message_value_list varchar(max),
			@message_campaign_id int,
			@message_campaign_class_id tinyint,
			@response_code int,
			@message varchar(100)

	select	@response_code = 0,
			@insert_date = getdate()

	if @customer_email = '' 
		begin
			select @customer_email = null
		end

	begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1) get license_message data
		select @license_id = lm.license_id,
				@keycode = l.keycode,
				@customer_id = l.customer_id,
				@customer_email = e.customer_email,
				@first_name = c.first_name,
				@last_name = c.last_name,
				@license_message_id = lm.license_message_id,
				@message_campaign_id = lm.message_campaign_id,
				@message_campaign_class_id = mc.message_campaign_class_id,
				@license_channel_id = lcl.license_channel_id
		from dbo.license_message lm with (nolock)
		inner join dbo.license l with (nolock)
			on lm.license_id = l.license_id
		left join dbo.customer c with (nolock)
			on l.customer_id = c.customer_id
		left join dbo.customer_email e with (nolock)
			on l.customer_id = e.customer_id and e.email_status_id = 1
		left join dbo.message_campaign mc with (nolock)
			on lm.message_campaign_id = mc.message_campaign_id
		left join dbo.license_channel_license lcl with (nolock)
			on lcl.license_id = l.license_id
		where lm.license_message_key = @license_message_key

		-- 1.1.1) get @message_value_list
		select @message_value_list = coalesce(@message_value_list+'|','')+ cast(t.message_value_type_name+'='+convert(varchar(20),v.value_id) as varchar(100))		
		from license_message_value v with (nolock)
		inner join message_value_type t with (nolock)
			on v.message_value_type_id = t.message_value_type_id
		where license_message_id = @license_message_id

		if @license_id is null
		-- 1.3) check license_key
			begin
				select @license_id = l.license_id,
						@keycode = l.keycode,
						@customer_id = l.customer_id,
						@customer_email = e.customer_email,
						@first_name = c.first_name,
						@last_name = c.last_name,
						@license_channel_id = lcl.license_channel_id
				from dbo.license_key lk with (nolock)
				inner join dbo.license l with (nolock)
					on lk.license_id = l.license_id
				left join dbo.customer c with (nolock)
					on l.customer_id = c.customer_id
				left join dbo.customer_email e with (nolock)
					on l.customer_id = e.customer_id and e.email_status_id = 1
				left join dbo.license_channel_license lcl with (nolock)
					on lcl.license_id = l.license_id
				where lk.license_key = @license_message_key
			end

		if @license_id is null
		-- 1.2) check license_message archive
			begin
				-- 1.2.1) get details
				select @license_id = lm.license_id,
						@keycode = l.
keycode,
						@customer_id = l.customer_id,
						@customer_email = e.customer_email,
						@first_name = c.first_name,
						@last_name = c.last_name,
						@license_message_id = lm.license_message_id,
						@license_channel_id = lcl.license_channel_id
				from dbo.license_message_archive lm with (nolock)
				inner join dbo.license l with (nolock)
					on lm.license_id = l.license_id
				left join dbo.customer c with (nolock)
					on l.customer_id = c.customer_id
				left join dbo.customer_email e with (nolock)
					on l.customer_id = e.customer_id and e.email_status_id = 1
				left join dbo.license_channel_license lcl with (nolock)
					on lcl.license_id = l.license_id
				where lm.license_message_key = @license_message_key
			
				-- 1.2.2) get @message_value_list
				select @message_value_list = coalesce(@message_value_list+'|','')+ cast(t.message_value_type_name+'='+convert(varchar(20),v.value_id) as varchar(100))		
				from license_message_value_archive v with (nolock)
				inner join message_value_type t with (nolock)
					on v.message_value_type_id = t.message_value_type_id
				where license_message_id = @license_message_id

				select	@message_campaign_id = c.message_campaign_id,
						@message_campaign_class_id = c.message_campaign_class_id
				from license_message_value_archive v with (nolock)
				inner join message_campaign c with (nolock)
					on v.value_id = c.message_campaign_id
				where v.license_message_id = @license_message_id and message_value_type_id = 2
				
				if @license_id is null
				-- 1.4) if license_message_key is not found send user to manual new registration
					begin
						select response_code = -112, message = 'Invalid license_message_key'
						return
					end		
			end
	

		-- 1.3) return result		
		select license_message_id = @license_message_id,
				license_message_key = convert(varchar(36),@license_message_key),
				license_id = @license_id,
				keycode = @keycode,
				message_campaign_id = @message_campaign_id,
				message_campaign_class_id = @message_campaign_class_id,
				message_value_list = @message_value_list,
				customer_id = @customer_id,
				customer_email = @customer_email,
				first_name = @first_name,
				last_name = @last_name,
				license_channel_id = @license_channel_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_select_message_history]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_message_select_message_history]

(
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select message_state = 'current', m.license_message_id, m.message_status_id, license_message_keyc = convert(varchar(36),m.license_message_key), m.process_date, m.end_date, c.message_campaign_id, c.message_campaign_name, c.message_campaign_description
	from license_message m
	--inner join message_status s
	--	on m.message_status_id = s.message_status_id
	inner join message_campaign c
		on m.message_campaign_id = c.message_campaign_id
	where license_id = @license_id
	union
	select message_state = 'archive', m.license_message_id, m.message_status_id, license_message_keyc = convert(varchar(36),m.license_message_key), m.process_date, m.end_date, c.message_campaign_id, c.message_campaign_name, c.message_campaign_description
	from license_message_archive m
	--inner join message_status s
	--	on m.message_status_id = s.message_status_id
	inner join license_message_value_archive v
		on m.license_message_id = v.license_message_id and v.message_value_type_id = 2
	left join message_campaign c
		on v.value_id = c.message_campaign_id
	where m.license_id = @license_id
	order by process_date desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_select_next_account_order_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_select_next_account_order_message]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2018-07-11	cnovac		Initial creation.
	
	DESCRIPTION
	select next message to process

*/

as

set nocount on

begin try			

	declare	@license_message_id int,
			@response_code int,
			@message varchar(100)
	
	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get next license_message_id
	select @license_message_id = (select top 1 m.license_message_id
								  from license_message m
								  where m.process_date <= @batch_limit_date
								  and m.message_type_id = 18
								  and m.message_status_id = 1
								  order by m.process_date)

	-- 1.2) insert data into table
	select m.license_message_id, 
		   cast(m.license_message_key as varchar(50)) as license_message_key,
		   mt.message_type_name,
		   m.license_id,
		   lmv.value_id as account_order_staging_id,
		   m.process_date
	from license_message m
	inner join message_type mt on mt.message_type_id = m.message_type_id
	inner join license_message_value lmv on m.license_message_id = lmv.license_message_id
	where m.license_message_id = @license_message_id
	and lmv.message_value_type_id = 25 --account_order_staging_id

	 --1.3) if no result then abandon message
	if @@rowcount = 0
	begin
		update license_message 
		set message_status_id = 6, last_modified_date = getdate()
		where license_message_id = @license_message_id
		return
	end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'usp_license_message_select_next_account_order_message failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_select_next_autorenewal_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_select_next_autorenewal_message]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2011-04-19	esmart		Initial creation.
	2012-04-02	esmart		Performance improvements
	2012-12-10	esmart		Add license_attribute_license check
	2016-06-21	cnovac		Add logic to handle CB Cart
	2017-07-10	cnovac		Added currency_id to result list for autorenewal (Cleverbridge) and updated language_code in select
	2019-09-19	wbarton		Refactoring to remove legacy joins and message_value_list logic which is not used by PHP. Removing checks against license_message_value for payment_header_id and customer_id.
	2019-10-15	wbarton		Explicitly setting @order_payment_header_id.  Certain payment_header_ids, such as 16044135, create dupes when joining.
	2020-10-05	wbarton		1.4 - improvements to failure logging

	DESCRIPTION
	select next message to process
	
*/

AS
	set nocount on				

	declare	@license_message_id int,
			@response_code int,
			@message varchar(100),
			@license_id INT,
			@payment_header_id INT,
			@customer_id int,
			@order_payment_header_id int,
			@failure_message varchar(100)

	begin try
	
	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) Get next license_message_id
	SELECT @license_message_id = lm.license_message_id, @license_id = lm.license_id
	FROM (
		SELECT TOP 1 license_message_id, license_id
		FROM license_message
		WHERE process_date <= @batch_limit_date
			AND message_type_id = 3
			AND message_status_id IN (1, 2, 4)
		ORDER BY process_date ASC) lm

	--1.2) Look up order_payment_header_id, payment_header_id, and customer_id from the license's most recent transaction
	SELECT @order_payment_header_id = oph.order_payment_header_id, @payment_header_id = oph.payment_header_id, @customer_id = co.customer_id
	FROM dbo.order_payment_header oph
		INNER JOIN (
			SELECT oil.license_id, MAX(oi.order_header_id) AS most_recent_order
			FROM dbo.order_item_license oil
				INNER JOIN dbo.order_item oi
					ON oi.order_item_id = oil.order_item_id
			WHERE oil.license_id = @license_id
			GROUP BY oil.license_id) oi
			ON oph.order_header_id = oi.most_recent_order
		LEFT JOIN dbo.customer_order co
			ON co.order_header_id = oph.order_header_id
				AND co.customer_type_id = 1
	
	-- 1.3) insert data into table
		declare @auto_renewal_message table (license_message_id int,process_date datetime,license_id int,keycode varchar(40),license_message_key varchar(40),customer_id int,payment_header_id int,payment_method_name varchar(50),merchant_id varchar(50), credit_card_subscription_id varchar(24), billing_agreement_id varchar(24), paypal_customer_email varchar(100), subscription_id varchar(50), vendor_order_code varchar(100), currency_id tinyint, currency_code char(3), language_code varchar(2), location_code varchar(3))

		insert into @auto_renewal_message(license_message_id, process_date, license_id, keycode, license_message_key, customer_id, payment_header_id, merchant_id, credit_card_subscription_id, billing_agreement_id, paypal_customer_email, subscription_id, vendor_order_code, currency_id, currency_code, language_code, location_code)
		select m.license_message_id, 
					m.process_date, 
					m.license_id, 
		
			l.keycode, 
					license_message_key = convert(varchar(40),m.license_message_key),
					@customer_id,
					@payment_header_id,
					pmr.merchant_id,
					cc.credit_card_subscription_id,
					pp.billing_agreement_id,
					pp.paypal_customer_email,
					ps.subscription_id,
					vo.vendor_order_code,
					iif(pmr.merchant_id = 'cleverbridge', c.currency_id, null) as currency_id,
					c.currency_code,
					coalesce(cll.language_code, substring(oh.locale,1,2), 'en') as language_code,
					lc.iso3 as location_code
		from license_message m
		inner join license l
			on m.license_id = l.license_id
		inner join payment_header h
			on @payment_header_id = h.payment_header_id
		inner join payment_merchant pmr
			on h.payment_merchant_id = pmr.payment_merchant_id
		inner join currency c
			on h.currency_id = c.currency_id
		inner join license_attribute_license al
			on l.license_id = al.license_id and al.license_attribute_license_value = 1
		left join payment_subscription_credit_card cc
			on @payment_header_id = cc.payment_header_id
		left join payment_subscription_paypal pp
			on @payment_header_id = pp.payment_header_id
		left join payment_subscription ps
			on @payment_header_id = ps.payment_header_id
		left join order_payment_header oph
			on @order_payment_header_id = oph.order_payment_header_id
		left join order_header oh
			on oh.order_header_id = oph.order_header_id
		left join lu_countries lc
			on substring(oh.locale,4,2) = lc.iso
		left join currency_language_location cll
			on lc.iso3 = cll.location_code and c.currency_id = cll.currency_id and cll.language_code = substring(oh.locale,1,2)
		left join vendor_order vo
			on vo.vendor_order_id = oh.vendor_order_id
		where m.license_message_id = @license_message_id

	-- 1.4) Abandon the record and log the failure if there were issues selecting data
		if exists (select 1 from @auto_renewal_message where merchant_id <> 'cleverbridge' and credit_card_subscription_id is null and billing_agreement_id is null) --No credit card subscription or paypal billing agreement; unprocessable
			begin
				select @failure_message = 'AR record missing credit_card_subscription_id and billing_agreement_id'
			end

		if exists (select 1 from @auto_renewal_message where merchant_id = 'cleverbridge' and subscription_id is null) --No subscription_id for a cleverbridge autorenewal; unprocessable
			begin
				select @failure_message = 'failed to select subscription_id for cleverbridge autorenewal'
			end

		if not exists (select 1 from @auto_renewal_message) --select failed due to missing data or license has been opted out of autorenewal
			begin
				--License is currently opted in
				if exists (select 1 from license_attribute_license where license_id = @license_id and license_attribute_license_value = 1)
					begin
						select @failure_message = 'failed to select data for opt-in license'
					end
				else
					begin
						select @failure_message = 'license opted-out'
					end
			end

		if @failure_message is not null
			begin
				update license_message 
				set message_status_id = 6, last_modified_date = getdate()
				where license_message_id = @license_message_id
				
				if @license_message_id is not null and @failure_message <> 'license opted-out'
					begin
						insert into dbo.license_message_failure(license_message_id, message_response_code, message_response_text)		
						select @license_message_id, 'ARSelectFailure', @failure_message
					end
			return
			end

	-- 1.5) return results
	select license_message_id, process_date, license_id, keycode, license_message_key, customer_id, payment_header_id, merchant_id, credit_card_subscription_id, billing_agreement_id, paypal_customer_email, subscription_id, vendor_order_code, currency_id, currency_code, language_code, location_code
	from @auto_renewal_message

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'lic
ense_message select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_update_account_order_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_update_account_order_message]

(
	@account_order_staging_id int,
	@license_message_key varchar(36),
	@message_response_code varchar(50),
	@message_response_text varchar(255) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2018-08-19	cnovac		Initial creation.
	2018-09-27	cnovac		Added code to not add another license_message if vendor_expiration_date is in past
	2018-09-28	cnovac		Made the oracle_update_status_id be 3 when inserting into order_license_usage
	2018-10-08	cnovac		Added code for OrderCancelled status to remove remaining days from license if necessary
	2018-10-12	cnovac		Refactored all the code to only process google AR until we have notifications
	2022-10-19	rambasana	Update data type from tinyint to int for update_attempts

	DESCRIPTION
	usp_license_message_update_account_order_message
	
*/

AS
	set nocount on				

	declare	@license_message_id int,
			@message_status_id tinyint,
			@update_attempts int,
			@message_response_id tinyint,
			@modified_date datetime = getdate(),
			@response_code int,
			@message varchar(50)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select current license_message data
	select @license_message_id = license_message_id,
		   @update_attempts = update_attempts
	from license_message
	where license_message_key = @license_message_key

	-- 1.2) @message_response_id
	select @message_response_id = message_response_id
	from message_response
	where message_response_code = @message_response_code

	-- 1.3) map new response_code to messaage_status_id
	select @message_status_id = iif(@message_response_id in (21, 22), 3, 4) --completed, submit failure

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @message_status_id = 3
	begin
		-- 2.1) update message success
		insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
		select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
		from license_message
		where license_message_id = @license_message_id

		update license_message
		set message_status_id = @message_status_id,
			update_attempts = @update_attempts + 1,
			last_modified_date = @modified_date
		where license_message_id = @license_message_id

	end
	else
	begin 	
		-- 2.2) insert into license_message_failure
		insert into license_message_failure(license_message_id, message_response_code, message_response_text, insert_date)
		values(@license_message_id, @message_response_code, @message_response_text, @modified_date)

		update license_message
		set process_date = dateadd(dd, 1, process_date),
			message_status_id = 1,
			update_attempts = @update_attempts + 1,
			last_modified_date = @modified_date
		where license_message_id = @license_message_id
	end
	
	end try

	begin catch

		set @response_code = -200
		set @m
essage = case when @message is null then 'usp_license_message_update_account_order_message failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_update_autorenewal_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_update_autorenewal_message]

(
	@license_message_key varchar(36),
	@message_response_code varchar(50),
	@message_response_text varchar(255) = null
)
	
/*	
	DATE		AUTHOR		REMARKS
	2011-04-19	esmart		Initial creation.
	2016-07-25	cnovac		Updated for CB implementation
	2022-10-19	rambasana	Update data type from tinyint to int for @update_attempts

	DESCRIPTION
	update license message
	
*/

AS
	set nocount on				

	declare @license_message_id int,
			@current_message_status_id tinyint,
			@message_status_id tinyint,
			@update_attempts int,
			@message_response_id tinyint,
			@modified_date datetime,
			@response_code int,
			@message varchar(50)

	begin try
	
	select @modified_date = getdate()
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select current license_message data
		select @license_message_id = license_message_id,
				@current_message_status_id = message_status_id,
				@update_attempts = update_attempts
		from license_message
		where license_message_key = @license_message_key

	-- 1.2) @message_response_id
		select @message_response_id = message_response_id
		from message_response
		where message_response_code = @message_response_code

	-- 1.3) map new response_code to messaage_status_id
	select @message_status_id = case
									when @message_response_id = 1 then 3
									when @message_response_id = 2 and @update_attempts = 0 then 4
									when @message_response_id = 2 and @update_attempts = 1 then 6
									when @message_response_id = 3 then 6
									when @message_response_id = 4 and @update_attempts < 4 then 4
									when @message_response_id = 4 and @update_attempts >= 4 then 6
									when @message_response_id in (10, 11) then 3
									when @message_response_id in (12, 13, 14) then 7
									when @message_response_id in (15, 16, 17, 18, 19) then 6
									when @message_response_id = 20 and @update_attempts < 4 then 4
									when @message_response_id = 20 and @update_attempts >= 4 then 6
								end
	
	-- 1.4) insert into license_message_failure
	if @message_response_id not in (1, 10, 11)
		begin
		insert into license_message_failure(license_message_id, message_response_code, message_response_text, insert_date)
		values(@license_message_id, @message_response_code, @message_response_text,@modified_date)
		end
	
--message_status_id	message_status_name
--1	pending
--2	submitted
--3	completed
--4	submit failure
--5	sent failure
--6	abandoned

--message_response_id	message_response_code	message_response_description
--1	Success	Message processed successfully
--2	AuthFailure	Authorization failure. Set for reattempt. 2 maximum
--3	FullFailure	Complete failure. Abandon message
--4	ProcessFailure	Increment update_attempts. 5 maximum.
--5	Selected	Message selected. Platform needs to be recorded.
--6	CartCreated	Cart created from message.
--7	EmailSubmitted	Email submitted.
--8	EmailVerified	Delivery confirmed.
--9	EmailBounced	Delivery failure.

--	select * 
--	from cart_order_message_in_process
--	where message_key = @license_message_key

--select message_response_id = @message_response_id, message_status_id = @message_status_id
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ------------------
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @message_status_id = 3
	-- 2.1) update message success
		begin
		--select '2.1) update message success'
		insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
		select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
		from license_message
		where license_message_id = @license_message_id

		update license_message
		set message_status_id = @message_status_id,
			update_attempts = @update_attempts + 1,
			last_modified_date = @modified_date
		where license_message_id = @license_message_id
	
		end
	else
	-- 2.2) update message failure
		begin
		--select '2.2) update message failure'
		insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
		select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
		from license_message
		where license_message_id = @license_message_id

		update license_message
		set process_date = 
				case
					when @message_status_id = 2 then dateadd(dd,1,process_date)
					when @message_status_id = 4 then dateadd(hh,@update_attempts + 1,process_date)
					else process_date
				end,
			message_status_id = @message_status_id,
			update_attempts = @update_attempts + 1,
			last_modified_date = @modified_date
		where license_message_id = @license_message_id
		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update license message failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_update_license_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_update_license_message]


/*     
       DATE                 AUTHOR        REMARKS
       2016-01-06           acoffel                    Initial creation

       
       DESCRIPTION
       Roll Price Tests
*/

AS
       set nocount on

       declare @response_code int,
              @message varchar(100),
              @last_modifed_date datetime,
              @modified_by varchar(20)
       
       set @last_modifed_date = getdate()
              
begin try

       -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) churn license_message price test
       -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

              ---- 1.0) Pre 30 day activate
              --update m
              --set m.message_campaign_class_id = 2,
              --     m.last_modified_date = getdate()
              --from license_message m
              --inner join license_summary s
              --     on m.license_id = s.license_id 
              --where m.message_campaign_id = 170
              --and cast(s.capability_expiration_date as date) between cast(getdate()+1 as date) and cast(getdate()+30 as date) 
              --and m.message_campaign_class_id in (3)

              ---- 1.1) Day 0 activate
              --update m
              --set m.message_campaign_id = 323,
              --     m.message_campaign_class_id = 2,
              --     m.last_modified_date = getdate()
              --from license_message m
              --inner join license_summary s
              --     on m.license_id = s.license_id 
              --where m.message_campaign_id in (170,171)
              --and cast(s.capability_expiration_date as date) = cast(getdate() as date) 
              --and m.message_campaign_class_id in (2,3)

              ---- 1.2) Less than 0 activate
              --update m
              --set m.message_campaign_id = 171,
              --     m.message_campaign_class_id = 2,
              --     m.last_modified_date = getdate()
              --from license_message m
              --inner join license_summary s
              --     on m.license_id = s.license_id 
              --where m.message_campaign_id in (170,323,171)
              --and cast(s.capability_expiration_date as date) < cast(getdate() as date) 
              --and m.message_campaign_class_id in (2,3)


              --update m
              --set m.message_campaign_class_id = 2,
              --     m.last_modified_date = getdate()
              --from license_message m
              --inner join license_summary s
              --     on m.license_id = s.license_id 
              --where m.message_campaign_id in (332,333)
              --and cast(s.capability_expiration_date as date) < cast(getdate()-60 as date) 
              --and m.message_campaign_class_id in (3)


              -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              -- 2.) insert and update
              -- ----------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------


              insert into license_message (license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
              select license_id, newid(), message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts
              from datawarehousereadonly.feed.dbo.license_message 
              where convert(date,insert_date) = convert(date,getdate())
              and message_campaign_class_id = 2
              --and message_campaign_id = 491
              
              update m
                     set m.message_campaign_class_id = 3,
                           m.last_modified_date = getdate()
              from license_message m
              inner join datawarehousereadonly.feed.dbo.license_message l
                     on m.license_id = l.license_id and m.message_campaign_id in (337,342,491)
              where m.message_campaign_class_id = 2
              and l.message_campaign_class_id = 3

              update l
              set l.message_campaign_class_id = 3,
                     l.last_modified_date = getdate()
              from license_message l
              inner join license_summary s
                     on l.license_id = s.license_id
              where l.message_campaign_class_id = 2
              and s.capability_expiration_date >= getdate()+60
              and l.message_campaign_id = 337


              -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              -- 3.) archive
              -- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

              --3.0) find archive records
              declare @license_message_archive table (license_message_id int)
              insert into @license_message_archive (license_message_id)
              select license_message_id
              from license_message 
              where message_campaign_id in (170,171,337,342,323,463,491)
              and archive_date <= getdate()-7
              and message_type_id = 1

              --3.1) archive
              insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
              select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
              from license_message with (nolock)
              where license_message_id in (select license_message_id from @license_message_archive)

              --3.2) delete from license_message
              delete
              from license_message 
              where message_campaign_id in (170,171,337,342,323,463,491)
              and archive_date <= getdate()-7
              and message_type_id = 1


end try

begin catch

       set @response_code = -200
       set @message = case when @message is null then 'license message update failed' 
                                         else @message end

       declare @DBName nvarchar(128)
       set @DBName = db_name()
       exec usp_LogError @ErrorDB = @DBName
       
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_message_update_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_message_update_message]

(
	@license_message_id int,
	@message_status_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2012-01-25	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@customer_id int,
			@license_status_id int,
			@current_message_status_id tinyint,
			@current_process_date datetime,
			@message_campaign_id int,
			@update_attempts tinyint,
			@next_message_campaign_id tinyint,
			@last_modified_date datetime,
			@message_type_id tinyint,
			@process_date datetime, 
			@end_date datetime, 
			@archive_date datetime, 
			@license_message_value_str varchar(max),
			@response_code int,
			@message varchar(100)

	begin try

	declare @message_campaign_output table (license_message_id int, license_message_key varchar(36))

	select @last_modified_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) license_message data
	select @license_id = l.license_id,
			@license_status_id = l.license_status_id,
			@current_message_status_id = m.message_status_id,
			@message_campaign_id = m.message_campaign_id,
			@current_message_status_id = m.message_status_id,
			@current_process_date = m.process_date,
			@update_attempts = m.update_attempts
	from license_message m with (nolock)
	inner join license l with (nolock)
		on m.license_id = l.license_id
	where license_message_id = @license_message_id
	
	-- 1.2) @next_message_campaign_id
	select @next_message_campaign_id = next_message_campaign_id
	from message_campaign_sequence with (nolock) 
	where message_campaign_id = @message_campaign_id

	-- 1.3)@customer_id
	select @customer_id = value_id
	from license_message_value with (nolock)
	where license_message_id = @license_message_id and message_value_type_id = 10

--	select license_status_id = @license_status_id, current_process_date = @current_process_date, current_message_status_id = @current_message_status_id, message_campaign_id = @message_campaign_id, next_message_campaign_id = @next_message_campaign_id, update_attempts = @update_attempts
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @license_status_id = 0
	-- 2.1) non-activated trialware campaigns
		begin
		-- 2.1.1) abandon after 5 attempts
		if @update_attempts = 4 and @message_status_id <> 3
			begin
			select @message_status_id = 6
			end

		-- 2.1.2) update message
		if @message_status_id <> @current_message_status_id
			begin
			update license_message
			set message_status_id = @message_status_id, update_attempts = @update_attempts + 1, last_modified_date = @last_modified_date
			where license_message_id = @license_message_id
			end

		-- 2.1.3)
		if @next_message_campaign_id is not null
			begin
			select @message_type_id = 1 

			-- 2.1.3.1) verify next message not exist
			if (select count(*) from license_message where license_id = @license_id and message_campaign_id = @next_message_campaign_id) > 0
				begin
				return
				end
				
			-- 2.1.3.2) insert next message
			select	@process_date = dateadd(dd,p.message_measure_day
s,@current_process_date),
					@end_date = dateadd(dd,(p.message_measure_days + p.message_duration_days),@current_process_date),
					@archive_date = dateadd(dd,(p.message_measure_days + p.message_duration_days + 30),@current_process_date),
					@license_message_value_str = 'message_campaign_id=' + convert(varchar(20),m.message_campaign_id) + ',customer_id = ' + convert(varchar(20),@customer_id)
			from message_campaign m with (nolock)
			inner join message_campaign_measure_point p with (nolock)
				on m.message_campaign_id = p.message_campaign_id
			where m.message_campaign_id = @next_message_campaign_id

			-- 2.4.2) insert campaign
			insert into @message_campaign_output(license_message_id, license_message_key)
			exec usp_message_insert_license_message @license_id,@message_type_id,@process_date,@end_date,@archive_date,@license_message_value_str,@license_message_id OUTPUT

			end
		end
	else
	-- 2.2) activated campaigns
		begin
		-- 2.2.1) abandon after 5 attempts
		if @update_attempts = 4 and @message_status_id <> 3
			begin
			select @message_status_id = 6
			end

		-- 2.2.2) update message
		if @message_status_id <> @current_message_status_id
			begin
			insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
			select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
			from license_message with (nolock)
			where license_message_id = @license_message_id

			update license_message
			set message_status_id = @message_status_id, update_attempts = @update_attempts + 1, last_modified_date = @last_modified_date
			where license_message_id = @license_message_id
			end
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_module_license_dedup]
-- =============================================================================
-------------------------------------------------------------------------------
--  Description:
--    Removes duplicate rows from the ecommerce license_module_license table.
--  Maintenance:
--    20161108 - mandersen - Created.
-------------------------------------------------------------------------------
--  Copyright © 2016-2017 Webroot Inc.
-------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_license_module_license_dedup]
AS

  set nocount on;

  --select license_module_license row
  DELETE FROM
    ecommerce.dbo.license_module_license
  WHERE
    license_module_license_id IN
    (
     SELECT
       license_module_license_id
     FROM
      (SELECT
         *,
         RANK() OVER(partition BY license_id, license_module_id ORDER BY license_id, license_module_id, license_module_license_id) AS rank
       FROM
         ecommerce.dbo.license_module_license) lml
     WHERE
       lml.rank > 1
    );
    

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_promo_activate_offer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_promo_activate_offer]
(
		@license_promo_campaign_id int,
		@activated_date datetime
)
/*	
	DATE				AUTHOR			REMARKS
	2008-03-18			ybarkalov		Initial creation

	DESCRIPTION
	Record the event of activating offer by the customer by updating activated_date
	OUTPUT:
		NULL when license_promo_campaign_id is not found
		0 when activated_date is already set to non-NULL value
		1 when activated_date is updated sucessfully
*/
as
set nocount on
declare @v_license_promo_campaign_id int,
		@v_activated_date datetime,
		@v_expiration_date datetime
begin try
	begin transaction;
	SELECT
			@v_license_promo_campaign_id = license_promo_campaign_id,
			@v_activated_date = activated_date,
			@v_expiration_date = expiration_date
		FROM dbo.license_promo_campaign
		WHERE @license_promo_campaign_id = license_promo_campaign_id
	IF @v_license_promo_campaign_id IS NULL -- license_promo_campaign_id is not found
		SELECT execution_status = NULL
	ELSE
		IF @v_activated_date IS NOT NULL -- activated_date is already set to non-NULL value
				OR (@v_expiration_date IS NOT NULL
					AND @v_expiration_date < @activated_date) -- offer is expired
			SELECT execution_status = 0
		ELSE -- update activated_date
			BEGIN
				UPDATE dbo.license_promo_campaign
					SET activated_date = @activated_date
					WHERE license_promo_campaign_id = @v_license_promo_campaign_id
				SELECT execution_status = 1
			END
	commit transaction;
end try
begin catch
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		if @@trancount > 0
	      rollback transaction;
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_promo_insert_offer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_promo_insert_offer]
(
		@license_id int,
		@customer_id int,
		@customer_email varchar(100), 
		@source_type varchar(15),
		@offer_type varchar(15),
		@product_id int,
		@price decimal(9,2),
		@days int,
		@language char(2),
		@location varchar(3),
		@rc int,
		@expiration_date datetime = NULL
)
/*	
	DATE				AUTHOR			REMARKS
	2008-03-18			ybarkalov		Initial creation

	DESCRIPTION
	Create/Save offer sent to the customer.
	SP will lookup language and location IDs from corresponding lookup tables
	
*/
as
set nocount on
declare @v_language_id int,
		@v_country_id int,
		@v_license_promo_campaign_id int
begin try
	begin transaction;
	SELECT
			@v_language_id = language_id
		FROM dbo.lu_language
		WHERE language_code = @language
	SELECT
			@v_country_id = country_id
		FROM dbo.lu_countries
		WHERE iso3 = @location
	INSERT INTO dbo.license_promo_campaign
			(license_id,
			customer_id,
			customer_email, 
			source_type,
			offer_type,
			price,
			days,
			product_id,
			language_id,
			country_id,
			rc,
			insert_date,
			expiration_date)
		VALUES
			(@license_id,
			@customer_id,
			@customer_email, 
			@source_type,
			@offer_type,
			@price,
			@days,
			@product_id,
			@v_language_id,
			@v_country_id,
			@rc,
			Getdate(),
			@expiration_date)
	SET @v_license_promo_campaign_id = scope_identity()
	SELECT license_promo_campaign_id = @v_license_promo_campaign_id
	commit transaction;
end try
begin catch
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		if @@trancount > 0
	      rollback transaction;
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_promo_select_offer]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_promo_select_offer]
(
		@license_promo_campaign_id int
)
/*	
	DATE				AUTHOR			REMARKS
	2008-03-18			ybarkalov		Initial creation

	DESCRIPTION
	Select Promo Campaign Offer details
	SP will lookup language and location IDs and return values in standard local format

*/
as
set nocount on
DECLARE @v_license_id int,
		@v_customer_id int,
		@v_customer_email varchar(100),
		@v_source_type varchar(15), /* cart or email */
		@v_offer_type varchar(15), /* OneMonthFree, ssUpgrade, TwoMonthFree */
		@v_product_id int,
		@v_price decimal(9,2),
		@v_days int,
		@v_language_id int,
		@v_language char(2),
		@v_country_id int,
		@v_location varchar(3),
		@v_rc int,
		@v_insert_date datetime,
		@v_expiration_date datetime,
		@v_sent_date datetime,
		@v_activated_date datetime
begin try
	begin transaction;
	SELECT
			@v_license_id = license_id,
			@v_customer_id = customer_id,
			@v_customer_email = customer_email,
			@v_source_type = source_type, /* cart or email */
			@v_offer_type = offer_type, /* OneMonthFree, ssUpgrade, TwoMonthFree */
			@v_product_id = product_id,
			@v_price = price,
			@v_days = days,
			@v_language_id = language_id,
			@v_country_id = country_id,
			@v_rc = rc,
			@v_insert_date = insert_date,
			@v_expiration_date = expiration_date,
			@v_sent_date = sent_date,
			@v_activated_date = activated_date
		FROM dbo.license_promo_campaign
		WHERE license_promo_campaign_id = @license_promo_campaign_id

	SELECT
			@v_language = language_code
		FROM dbo.lu_language
		WHERE language_id = @v_language_id

	SELECT
			@v_location = iso3
		FROM dbo.lu_countries
		WHERE country_id = @v_country_id

	SELECT
			license_promo_campaign_id = @license_promo_campaign_id,
			license_id = @v_license_id,
			customer_id = @v_customer_id,
			customer_email = @v_customer_email,
			source_type = @v_source_type,
			offer_type = @v_offer_type,
			product_id = @v_product_id,
			price = @v_price,
			days = @v_days,
			language = @v_language,
			location = @v_location,
			rc = @v_rc,
			insert_date = @v_insert_date,
			expiration_date = @v_expiration_date,
			sent_date = @v_sent_date,
			activated_date = @v_activated_date
	commit transaction;
end try
begin catch
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		if @@trancount > 0
	      rollback transaction;
end catch;

GO
