-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_accounts_by_keycode]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_accounts_by_keycode]

(
	@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-09-15	acoffel		Initial creation.
	2012-01-09	esmart		Add alias keycode support

	DESCRIPTION
	select accounts by keycode
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@license_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--1.1 get license_id
	select @license_id = license_id
	from license
	where keycode = @keycode

	-- 1.1.1) check if keycode is alias	
	if @license_id is null
		begin
			select @license_id = license_id
			from license_keycode_alias
			where keycode_alias = @keycode
		end

	declare @license_accounts table (account_id int, account_user_name varchar(100), account_status_id tinyint, account_status varchar(20), account_type_id tinyint, account_type_description varchar(20), phone_number varchar(64), device_guid varchar(50))

	-- 1.2) account_license path
	insert into @license_accounts(account_id, account_user_name, account_status_id, account_status, account_type_id, account_type_description, phone_number, device_guid)
	select a.account_id, a.account_user_name, s.account_status_id, s.account_status, t.account_type_id, t.account_type_description, ad.phone_number, ad.device_guid
	from account_license al
	inner join account a
		on al.account_id = a.account_id
	inner join account_status s
		on a.account_status_id = s.account_status_id
	inner join account_type t
		on a.account_type_id = t.account_type_id
	left join account_device ad
		on ad.license_id = al.license_id
	where al.license_id = @license_id and a.account_status_id <> 2

	-- 1.3) account_device path
	insert into @license_accounts(account_id, account_user_name, account_status_id, account_status, account_type_id, account_type_description, phone_number, device_guid)
	select a.account_id, a.account_user_name, s.account_status_id, s.account_status, t.account_type_id, t.account_type_description, ad.phone_number, ad.device_guid
	from account_device ad
	inner join account a
		on ad.account_id = a.account_id
	inner join account_status s
		on a.account_status_id = s.account_status_id
	inner join account_type t
		on a.account_type_id = t.account_type_id
	where ad.license_id = @license_id and a.account_status_id <> 2

	-- 1.4) select result
	select distinct account_id, account_user_name, account_status_id, account_status, account_type_id, account_type_description, phone_number, device_guid
	from @license_accounts

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_activation_count_csi]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_activation_count_csi]

(	
	@license_id int
)

/*	
	DATE		AUTHOR	REMARKS
	2006-09-19	esmart		Initial creation.
	2009-11-18	dsmelker	Modified to use the new table in weblog license_activity_guid
	2010-04-27	dsmelker	Added keycode to query
	2014-05-07  surpal	    weblog db outdated

	DESCRIPTION
	Select last activity record for a license
*/

AS
Begin
	set nocount on

	declare @license_activation_count int

	select @license_activation_count = 0


	/*
	
	-- weblog db outdated 
	select @license_activation_count = count(*)
	from weblog.dbo.license_activity_guid lag with (nolock)
	inner join license l with (nolock)
		on lag.license_id = l.license_id
		and lag.keycode = l.keycode
	where lag.license_id = @license_id
	and max_insert_date >= (select max(first_insert_date) from weblog.dbo.license_activity_guid with (nolock)
							 where license_id = @license_id)

							 */

	if @license_activation_count = 0
	Begin
		select @license_activation_count = count(*)
		from license_activation with (nolock)
		where license_id = @license_id
	End

	select @license_activation_count as license_activation_count


End


GO
