-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_bulk_licenses]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_bulk_licenses]

(	
	@license_bulk_load_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2006-09-07	esmart		Initial creation.
	2010-12-13	towens		add fn_AddDashes
	2014-09-10	esmart		Add serial number
	2019-06-19	wbarton		Adding compatibility for WiFi

	DESCRIPTION
	Select all keycodes for a bulk load
*/

AS
	set nocount on

	DECLARE @license_category_id INT
	SELECT @license_category_id = lc.license_category_id
	FROM license_category lc
		INNER JOIN dbo.product_license_category plc
			ON plc.license_category_id = lc.license_category_id
		INNER JOIN dbo.license_bulk_load lbl
			ON lbl.product_id = plc.product_id
	WHERE lbl.license_bulk_load_id = @license_bulk_load_id

	IF @license_category_id = 135
		BEGIN

			SELECT abl.account_registration_url
			FROM dbo.account_order_bulk_load abl
			WHERE abl.license_bulk_load_id = @license_bulk_load_id

		END
        ELSE
		BEGIN

			select keycode = substring(keycode,1,4)+'-'+substring(keycode,5,4)+'-'+substring(keycode,9,4)+'-'+substring(keycode,13,4)+'-'+substring(keycode,17,4),
					serial_number = case
										when s.subscription_id is not null then substring(serial_number,1,9)+' '+substring(serial_number,10,5)+' '+substring(serial_number,15,5)
										else ''
									end
			from license_bulk_load_license l
			left join subscription s
				on l.license_id = s.license_id
			where license_bulk_load_id = @license_bulk_load_id

		END

GO
