-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_bulk_load_detail]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_bulk_load_detail]

(	
	
	@p_start_date datetime = null,
	@p_end_date datetime = NULL,
	@license_bulk_load_group_id int = 1,
	@license_distribution_method_id int = null

)

/*	
	DATE		AUTHOR	REMARKS
	2006-09-07	esmart		Initial creation.
	2010-08-31	dsmelker	Added bulk_load_group_id to filter results

	DESCRIPTION
	Select all keycodes for a bulk load
*/

AS
	set nocount on

	if @p_start_date is null
		begin
		select @p_start_date = '2006-09-18'
		end 
	if @p_end_date is null
		begin
		select @p_end_date = getdate()
		end
	
	select @p_end_date = dateadd(dd,1,@p_end_date)

	select lbl.license_bulk_load_id, 
			lbl.license_bulk_load_description, 
			lbl.product_line_id,  
			p.product_id, 
			p.product_description,
			lbl.days_override,
			lbl.module_product_id, 
			module_product_description = p2.product_description,
			lbl.license_distribution_method_id, 
			m.license_distribution_method_code,
			m.license_distribution_method_name,
			lbl.license_type_id, 
			t.license_type_description,
			lbl.fixed_expiration_OEM, 
			lbl.quantity,
			lbl.enterprise_seats, 
			lbl.distribution_rc, 
			lbl.license_status_id, 
			lbl.license_keycode_type_id, 
			lbl.max_daily_activations, 
			lbl.max_child_licenses, 
			lbl.license_expiration_date, 
			lbl.insert_date, lbl.insert_by, 
			lbl.license_bulk_status_id, 
			lbl.license_bulk_load_group_id 
	from license_bulk_load lbl with (nolock)
	inner join product p
		on lbl.product_id = p.product_id
	left join product p2
		on lbl.module_product_id = p2.product_id
	inner join license_distribution_method m with (nolock)
		on lbl.license_distribution_method_id = m.license_distribution_method_id
	inner join license_type t
		on lbl.license_type_id = t.license_type_id
	where lbl.insert_date between @p_start_date and @p_end_date
		and lbl.license_bulk_load_group_id = @license_bulk_load_group_id and
		lbl.license_distribution_method_id = case
													when @license_distribution_method_id is null then lbl.license_distribution_method_id
													else @license_distribution_method_id
												end
	order by lbl.license_bulk_load_id desc



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_bulk_load_license_status]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_bulk_load_license_status]

(	
	@keycode varchar(40) = NULL,
	@license_bulk_load_id int = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2017-01-05	acoffel		Initial creation.
	
	DESCRIPTION
	Select all keycodes for a bulk load
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) check for bulk load id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @keycode is not NULL
		begin
			select @license_bulk_load_id = license_bulk_load_id from license_bulk_load_license where keycode = @keycode
				if @license_bulk_load_id is NULL
					begin 
						select @message = 'Keycode not part of a bulk load' select @message
						return
					end		
						
		end 
	


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get bulk load info
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_bulk_load_detail table (license_bulk_load_license_update_type varchar(40), license_bulk_load_id int, license_count int)

	insert into @license_bulk_load_detail (license_bulk_load_license_update_type, license_bulk_load_id, license_count)
	select license_bulk_load_license_update_type = 'Not Activated',
			lbl.license_bulk_load_id, 
			license_count = count(s.license_id)
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 0
	and lbl.license_bulk_load_id = @license_bulk_load_id
	group by lbl.license_bulk_load_id

	insert into @license_bulk_load_detail (license_bulk_load_license_update_type, license_bulk_load_id, license_count)
	select license_bulk_load_license_update_type = 'Active with days',
			lbl.license_bulk_load_id, 
			license_count = count(s.license_id)
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 1
	and s.capability_expiration_date >= getdate()
	and lbl.license_bulk_load_id = @license_bulk_load_id
	group by lbl.license_bulk_load_id


	insert into @license_bulk_load_detail (license_bulk_load_license_update_type, license_bulk_load_id, license_count)
	select license_bulk_load_license_update_type = 'Active with no days',
			lbl.license_bulk_load_id, 
			license_count = count(s.license_id)
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 1
	and s.capability_expiration_date < getdate()
	and lbl.license_bulk_load_id = @license_bulk_load_id
	group by lbl.license_bulk_load_id
	
	insert into @license_bulk_load_detail (license_bulk_load_license_update_type, license_bulk_load_id, license_count)
	select license_bulk_load_license_update_type = 'Previously Deactivated',
			lbl.license_bulk_load_id, 
			license_count = count(s.license_id)
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id in (
2,3)
	and lbl.license_bulk_load_id = @license_bulk_load_id
	group by lbl.license_bulk_load_id


	select * from @license_bulk_load_detail

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
