-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_category_discount_model]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_category_discount_model]
(
	@item_json NVARCHAR(MAX),
	@source_caller VARCHAR(50) NULL,
	@item_discount_profile_json NVARCHAR(MAX) OUTPUT
)
/*	
	DATE			AUTHOR		REMARKS
	2019-11-22		wbarton		Initial creation
	2020-02-13		wbarton		Refactoring to output a JSON object. Also fixing a discount-inheritance issue in sections 3 and 6.
	2020-03-20		wbarton		Removing years from joins to cart_discount_item. Discount tiers will apply regardless of years.
	2025-18-20		jberry		US-5004939 - Added usage pricing model, retention model and storage to @item_discount_profile
	          		      		- Added sec 2.4 to populate usage_pricing_model_id
	          		      		- Added sec 12.4 to get standard discount for licenses with a usage pricing model/retention
	          		      		- Made general formatting changes and added section numbering
	2025-11-14		jberry		US-5076905 - Added sap_material_number to @item_discount_profile
	          		      		- Added sap_material_number to 12.4 to capture the sap_material_number for the correct pricing tier
	2026-06-04		jberry		US-5437436 - Changed sec 9.1 to handle cases where license_attribute_license_value is applied to standard discounts

	Dependencies:
	dbo.usp_cart_insert_cart_order_item
	dbo.usp_cart_select_license_configurator_pricing
	dbo.usp_cart_update_cart_order_item
*/
AS
SET NOCOUNT ON

BEGIN TRY

	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED

	DECLARE @item_discount_profile TABLE (
		item_id INT,
		license_id INT,
		license_category_name VARCHAR(10),
		license_category_id INT,
		license_seats INT,
		product_type_id INT,
		years FLOAT,
		license_attribute_license_value INT,
		discount_model INT,
		discount_model_license_attribute_license_value INT,
		discount FLOAT,
		cart_discount_method_id INT,
		cart_discount_id INT,
		retention_model_id INT,
		usage_pricing_model_id INT,
		storage_gb INT,
		sap_material_number INT
	)

	DECLARE @orders_by_product_type TABLE (
		license_id INT, 
		license_category_id INT,
		product_type_id INT, 
		order_header_id INT
	)

	DECLARE @last_order_discount_profile TABLE (
		license_id INT,
		last_order_header_id INT,
		last_order_item_id INT,
		last_order_product_id INT,
		last_order_language_code VARCHAR(2),
		last_order_location_code VARCHAR(3),
		last_order_license_category_id INT,
		last_order_product_type_id INT,
		last_order_years FLOAT,
		last_order_quantity INT,
		last_order_discount FLOAT,
		last_order_license_attribute_license_value INT,
		last_order_discount_model INT,
		last_order_discount_model_license_attribute_license_value INT
	)

	 DECLARE @CARBONITE_LICENSE_CATEGORIES TABLE
    (
        license_category_id INT,
		license_category_name VARCHAR(10)
    )

    INSERT INTO @CARBONITE_LICENSE_CATEGORIES
    (
        license_category_id,
		license_category_name
    )
    SELECT f.[key],
			f.value
    FROM [dbo].[fn_app_config_select_key_values]('CARBONITE_LICENSE_CATEGORIES', 'CARBONITE') f

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.  Log the incoming request
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @license_category_discount_model_json_id INT

	INSERT INTO dbo.license_category_discount_model_json (license_category_discount_model_json, license_category_discount_model_source_caller)
	SELECT @item_json, @source_caller

	SET @license_category_discount_model_json_id = SCOPE_IDENTITY()

	--------------------------------------------------------------
----------------------------------------------------------------------------------------------
	--2.  Parse json and set initial values
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--2.1 insert into @item_discount_profile
	INSERT INTO @item_discount_profile (item_id, license_id, license_category_name, license_seats, product_type_id, years, license_attribute_license_value, retention_model_id, storage_gb)
	SELECT item_id, license_id, license_category_name, license_seats, product_type_id, years, license_attribute_license_value, retention_model_id, storage_gb
	FROM OPENJSON(@item_json)
	WITH (
		item_id INT '$.item_id',
		license_id INT '$.license_id',
		license_category_name VARCHAR(10) '$.license_category_name',
		license_seats INT '$.license_seats',
		product_type_id INT '$.product_type_id',
		years FLOAT '$.years',
		license_attribute_license_value INT '$.license_attribute_license_value',
		retention_model_id INT '$.retention_model_id',
		storage_gb INT '$.storage_gb'
	)

		--2.2 license_category_id lookup
		UPDATE idp 
		SET license_category_id = lc.license_category_id
		FROM @item_discount_profile idp
			INNER JOIN dbo.license_category lc
				ON lc.license_category_name = idp.license_category_name

		--2.3 Default years to 1 for current request if no value provided
		UPDATE idp 
		SET years = 1
		FROM @item_discount_profile idp
		WHERE years IS NULL

		--2.4 Update usage_pricing_model
		UPDATE idp
		SET idp.usage_pricing_model_id = lp.usage_pricing_model_id
		FROM @item_discount_profile idp
		CROSS APPLY dbo.fn_license_select_license_profile(idp.license_id) lp

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--3.  If there is no license (new order) default to standard discount model
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	IF EXISTS (SELECT license_category_id FROM @item_discount_profile WHERE license_id IS NULL)
		BEGIN
			UPDATE idp 
			SET idp.discount_model = 4
			FROM @item_discount_profile idp

			GOTO current_request_lookup
		END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--4.  Set discount_model to standard if license belongs to a partner
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	UPDATE idp 
	SET idp.discount_model = 4 --Standard
	FROM @item_discount_profile idp
		INNER JOIN dbo.partner_license pl 
			ON pl.license_id = idp.license_id
	WHERE pl.partner_id NOT IN (3291, 5559) --Webroot and Webroot Direct Partner	
		AND (pl.end_date IS NULL OR pl.end_date > GETDATE())
		AND pl.start_date < GETDATE()

	IF @@rowcount > 0
		BEGIN
			--Proceed to the final section of the procedure
			GOTO current_request_lookup
		END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--5.  If discount_model is not yet set via the above, get the license's most recent order_header_id and associated lang/loc for each license_category_id
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--5.1 Populating orders_by_product_type with the license's most recent orders by product_type. This will be used for separate logic based on whether the most recent is an upsell or new/renewal
	IF EXISTS (SELECT license_id FROM @item_discount_profile WHERE discount_model IS NULL)
		BEGIN 
			INSERT INTO
 @orders_by_product_type (license_id, license_category_id, product_type_id, order_header_id)
			SELECT o.license_id, o.license_category_id, o.product_type_id, o.max_order_header
			FROM (
				SELECT idp.license_id, plc.license_category_id, p.product_type_id, MAX(oh.order_header_id) AS max_order_header
				FROM @item_discount_profile idp
					INNER JOIN dbo.order_item_license oil 
						ON oil.license_id = idp.license_id
					INNER JOIN dbo.order_item oi 
						ON oi.order_item_id = oil.order_item_id
					INNER JOIN dbo.product_license_category plc
						ON plc.product_id = oi.product_id
					INNER JOIN dbo.product p
						ON p.product_id = oi.product_id
					INNER JOIN dbo.order_header oh 
						ON oh.order_header_id = oi.order_header_id AND oh.order_status_id <> 3 --Excluding refunded orders
				GROUP BY idp.license_id, plc.license_category_id, p.product_type_id
			) o

			--5.1.1 Adding only the most recent new or renewal order to the @last_order_discount_profile table
			INSERT INTO @last_order_discount_profile (license_id, last_order_header_id, last_order_language_code, last_order_location_code, last_order_license_category_id)
			SELECT o.license_id, o.last_order_header_id, l.language_code, l.location_code, o.license_category_id
			FROM (
					SELECT idp.license_id, opt.license_category_id, MAX(opt.order_header_id) AS last_order_header_id
					FROM @orders_by_product_type opt
						INNER JOIN @item_discount_profile idp
							ON idp.license_id = opt.license_id
					WHERE opt.product_type_id IN (1, 2) --Limiting discount calculations to new and renewal orders only
					GROUP BY idp.license_id, opt.license_category_id
				) o
				INNER JOIN dbo.order_header oh2 
					ON oh2.order_header_id = o.last_order_header_id
				CROSS APPLY dbo.fn_locale_to_lang_loc(oh2.locale) l
		END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--6.  Set discount_model to standard if license has no order history
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	IF EXISTS (SELECT license_id FROM @last_order_discount_profile WHERE last_order_header_id IS NULL)
		BEGIN
			UPDATE @item_discount_profile
			SET discount_model = 4 --Standard

			--Proceed to the final section of the procedure
			GOTO current_request_lookup
		END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--7.  Set discount_model to standard if there was a distributor or reseller on the license's most recent order regardless of product_type_id
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	ELSE
		BEGIN
			UPDATE idp 
			SET idp.discount_model = 4 --Standard
			FROM @item_discount_profile idp
				INNER JOIN (
					SELECT license_id, MAX(order_header_id) AS most_recent_order
					FROM @orders_by_product_type
					GROUP BY license_id
				) o
					ON o.license_id = idp.license_id
				INNER JOIN dbo.order_company oc 
					ON oc.order_header_id = o.most_recent_order AND oc.order_company_type_id IN (3, 4) --Reseller, Distributor

			IF @@rowcount > 0
				BEGIN
				--Proceed to the final section of the procedure
				GOTO current_request_lookup
				END
		END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--8.  If discount_model is not yet set, evaluate attributes from @last_order_discount_profile and compare it against established discount models
	---------------------------------------------------------------------------------------------------------------------------------
---------------------------
	IF EXISTS (SELECT license_category_id FROM @item_discount_profile WHERE discount_model IS NULL)
		BEGIN

		--8.1. If different license categories have different last_order_header_ids, only the most recent order's attributes should be evaluated for discount model comparisons
			IF (SELECT COUNT(DISTINCT last_order_header_id) FROM @last_order_discount_profile) > 1
				BEGIN
					DELETE FROM @last_order_discount_profile
					WHERE last_order_header_id <> (SELECT MAX(last_order_header_id) FROM @last_order_discount_profile)
				END

		--8.2 Find the applicable last_order_item_id and calculate its discount and associated billing model
			UPDATE lodp
			SET last_order_item_id = oi.order_item_id, lodp.last_order_product_id = oi.product_id, last_order_product_type_id = p.product_type_id, lodp.last_order_years = py.years, last_order_quantity = oi.quantity, last_order_discount = ROUND(1 - (CONVERT(FLOAT, oi.unit_price) / CONVERT(FLOAT, pp.retail_price)), 5) * 100
			FROM @last_order_discount_profile lodp
				INNER JOIN dbo.order_item oi 
					ON oi.order_header_id = lodp.last_order_header_id
				INNER JOIN dbo.order_item_license oil --Joining here in case there are ever multiple licenses in an order
					ON oil.license_id = lodp.license_id
				INNER JOIN dbo.product p
					ON p.product_id = oi.product_id AND p.product_type_id IN (1, 2) --New or renewal only
				INNER JOIN dbo.product_years py
					ON py.product_id = p.product_id
				INNER JOIN dbo.product_license_category plc
					ON plc.product_id = oi.product_id AND plc.license_category_id = lodp.last_order_license_category_id
				INNER JOIN dbo.product_pricing pp
					ON pp.product_id = oi.product_id AND pp.language_code = lodp.last_order_language_code AND pp.location_code = lodp.last_order_location_code
			WHERE lodp.last_order_license_category_id = plc.license_category_id

			--8.2.1 Set the last_order_license_attribute_license_value when applicable
			UPDATE lodp 
			SET last_order_license_attribute_license_value = le.effective_value 
			FROM @last_order_discount_profile lodp
				CROSS APPLY dbo.fn_license_select_effective_object_element_history(lodp.license_id, 'license_attribute_license_value', lodp.last_order_license_category_id) le
				INNER JOIN dbo.license_effective_object_transaction leot
					ON le.license_effective_object_transaction_id = leot.license_effective_object_transaction_id
			WHERE lodp.last_order_item_id = leot.effective_object_transaction_type_value
				AND lodp.last_order_license_category_id = le.license_category_id

		--8.3 If the last order was Utility, qualify the current request into the SFDC discount model based on the usage price set by the last order
			IF EXISTS (SELECT last_order_license_category_id FROM @last_order_discount_profile WHERE last_order_license_attribute_license_value = 12)
				BEGIN 
					--8.3.1 Get pricing attributes for categories from the last Utility order
					DECLARE @last_order_usage_attributes TABLE (license_category_id INT, last_order_product_list_price MONEY, standard_usage_price FLOAT, last_order_usage_price FLOAT, last_order_usage_discount FLOAT, last_order_usage_discount_model INT)
					INSERT INTO @last_order_usage_attributes (license_category_id, last_order_product_list_price, standard_usage_price, last_order_usage_price, last_order_usage_discount)
					SELECT lodp.last_order_license_category_id, pp.retail_price, pp.usage_price, last_order_usage_price = ROUND(CONVERT(FLOAT, leo.effective_value) / 100.00, 2), last_order_usage_discount = ROUND(1 - ((CONVERT(FLOAT, leo.effective_value) / 100.00) / CONVERT(FLOAT, pp.usage_price)), 5) * 100
					FROM @last_order_discount_profile lodp
						INNER JOIN dbo.product_pricing pp
							ON pp.product_id = lodp.last_order_product_id AND pp.language_code = lodp.last_order_language_code AND pp.location_code = lodp.last_order_location_code
						CROSS APPLY dbo.fn_license_select_effective_object_element_history
(lodp.license_id, 'license_usage_pricing_value', lodp.last_order_license_category_id) leo
						INNER JOIN dbo.license_effective_object_transaction leot
							ON leot.license_effective_object_transaction_id = leo.license_effective_object_transaction_id AND leot.effective_object_transaction_type_value = lodp.last_order_item_id
					WHERE lodp.last_order_license_category_id = leo.license_category_id
						AND lodp.last_order_license_attribute_license_value = 12 --Utility

					--8.3.2 Attempt to match the previous Utility order's discount to a discount model, and update @last_order_usage_attributes accordingly
					UPDATE a 
					SET last_order_usage_discount_model = cd.cart_discount_type_id
					FROM @last_order_usage_attributes a
						INNER JOIN @last_order_discount_profile lodp
							ON lodp.last_order_license_category_id = a.license_category_id
						INNER JOIN dbo.cart_discount_item cdi
							ON cdi.license_category_id = a.license_category_id AND cdi.license_attribute_license_value = lodp.last_order_license_attribute_license_value
						INNER JOIN dbo.cart_discount cd
							ON cd.cart_discount_id = cdi.cart_discount_id AND cd.cart_discount_status_id = 1
					WHERE cdi.low_range <= lodp.last_order_quantity AND cdi.high_range > lodp.last_order_quantity
						AND cdi.discount <= a.last_order_usage_discount --<= so we assign the SFDC discount model when the last_order_usage_discount was larger
						AND lodp.last_order_license_attribute_license_value = 12

					--8.3.3 Give the current request the discount model determined for the license categories above
					UPDATE idp 
					SET idp.discount_model = a.last_order_usage_discount_model, idp.discount_model_license_attribute_license_value = 
						CASE
							WHEN idp.license_attribute_license_value = 11 AND a.last_order_usage_discount_model = 7 THEN idp.license_attribute_license_value ELSE NULL END
					FROM @item_discount_profile idp
						INNER JOIN @last_order_usage_attributes a
							ON a.license_category_id = idp.license_category_id
				
					--8.3.4 License categories that are not in the current request should inherit the best discount model established via the matching logic above
					IF EXISTS (SELECT license_category_id FROM @item_discount_profile WHERE discount_model IS NULL)
						BEGIN
							DECLARE @inherited_usage_discount_model_id INT
							SET @inherited_usage_discount_model_id = (SELECT MAX(last_order_usage_discount_model) FROM @last_order_usage_attributes)
							UPDATE idp 
							SET idp.discount_model = @inherited_usage_discount_model_id, idp.discount_model_license_attribute_license_value = 
								CASE
									WHEN idp.license_attribute_license_value = 11 AND @inherited_usage_discount_model_id = 7 THEN idp.license_attribute_license_value ELSE NULL END
							FROM @item_discount_profile idp
								LEFT JOIN @last_order_usage_attributes a
									ON a.license_category_id = idp.license_category_id
							WHERE a.license_category_id IS NULL
						END
                        
				--Proceed to the final section of the procedure
				GOTO current_request_lookup
			END

	--------------------------------------------------------------------------------------------------------------------------------------------------------
	--9. Check if we have a cart_discount_type_id exact-match based on properties from the last_order_item_id above
	--------------------------------------------------------------------------------------------------------------------------------------------------------

		--9.1 update discount model and license attribute license value on exact match
		    UPDATE p
		        SET p.last_order_discount_model = c.cart_discount_type_id,
		            p.last_order_discount_model_license_attribute_license_value = CASE WHEN c.cart_discount_type_id = 4 THEN NULL ELSE i.license_attribute_license_value END
		    FROM @last_order_discount_profile p
		        INNER JOIN dbo.cart_discount_item i
	
	            ON p.last_order_product_type_id = i.product_type_id
		                AND p.last_order_license_category_id = i.license_category_id
		                AND p.last_order_quantity >= i.low_range
		                AND p.last_order_quantity < i.high_range
		        INNER JOIN dbo.cart_discount c
		            ON c.cart_discount_id = i.cart_discount_id
		    WHERE c.cart_discount_status_id = 1  --active
		        AND c.cart_discount_type_id IN (4, 7)
		        AND ABS(p.last_order_discount - i.discount) < 0.0005   --compare last order discount to cart item discount to determine if there's a close match
		        AND (i.license_attribute_license_value IS NULL 
		            OR i.license_attribute_license_value <> 12);  --Removing utility discounts from having an exact match, as that's covered in section 3

	--------------------------------------------------------------------------------------------------------------------------------------------------------
	--10. If an exact match exists, update @item_discount_profile with the matched model
	--------------------------------------------------------------------------------------------------------------------------------------------------------
		IF EXISTS (SELECT last_order_license_category_id FROM @last_order_discount_profile WHERE last_order_discount_model IS NOT NULL)
			BEGIN
				--10.1 Update discount model and license attribute license value
				UPDATE idp 
				SET idp.discount_model = lodp.last_order_discount_model, idp.discount_model_license_attribute_license_value = lodp.last_order_discount_model_license_attribute_license_value
				FROM @item_discount_profile idp
					INNER JOIN @last_order_discount_profile lodp
						ON lodp.license_id = idp.license_id
				WHERE idp.license_category_id = lodp.last_order_license_category_id
				
				--10.2 License categories that are not in @last_order_discount_profile should inherit the discount model from whatever had an exact match
				UPDATE idp 
				SET idp.discount_model = lodp.discount_model, idp.discount_model_license_attribute_license_value = lodp.last_order_discount_model_license_attribute_license_value
				FROM @item_discount_profile idp
					INNER join (
						select license_id, last_order_discount_model_license_attribute_license_value, max(last_order_discount_model) as discount_model --Selecting only the max (best) discount in case there are multiple discount model matches between other license categories
						from @last_order_discount_profile
						group by license_id, last_order_discount_model_license_attribute_license_value
					) lodp
						on lodp.license_id = idp.license_id
				where idp.discount_model is null
			
				--Proceed to the final section of the procedure
				GOTO current_request_lookup
			END

	--------------------------------------------------------------------------------------------------------------------------------------------------------
	--11. If @item_discount_profile still does not have a discount_model set, check if last_order_discount falls in-between models for each license category
	--------------------------------------------------------------------------------------------------------------------------------------------------------
		IF EXISTS (SELECT license_category_id FROM @item_discount_profile WHERE discount_model IS NULL)
			BEGIN

				declare @discount_model_attributes table (
					discount_model_attributes_id int identity(1,1),
					discount_model_id int,
					discount_model_license_category_id int,
					discount_model_license_attribute_license_value int,
					low_range int,
					high_range int,
					discount float
				)

				declare @next_model_match table (
					license_category_id int,
					discount_model_attributes_id int,
					match_type varchar(25)
				)
				--11.1  Insert the SFDC Overage discount only when the last order had overage
				insert into @discount_model_attributes (discount_model_id, discount_model
_license_category_id, discount_model_license_attribute_license_value, low_range, high_range, discount)
				select c.cart_discount_type_id, i.license_category_id, i.license_attribute_license_value, i.low_range, i.high_range, i.discount
				from dbo.cart_discount_item i
					inner join dbo.cart_discount c
						on i.cart_discount_id = c.cart_discount_id and c.cart_discount_status_id = 1 and c.cart_discount_type_id in (4, 7) --Standard and SFDC models, active
					inner join @last_order_discount_profile lodp
						on lodp.last_order_license_category_id = i.license_category_id and lodp.last_order_product_type_id = i.product_type_id
				where lodp.last_order_quantity >= i.low_range and lodp.last_order_quantity < i.high_range
					--and lodp.last_order_years = i.years
					and (i.license_attribute_license_value is null or i.license_attribute_license_value = lodp.last_order_license_attribute_license_value) --Inserting the SFDC Overage discount only when the last order had overage
				order by i.discount ASC

				--11.2 If the last_order_discount falls in-between models, grab the closest discount model up and add it to the table variable
				INSERT INTO @next_model_match (license_category_id, discount_model_attributes_id, match_type)
				SELECT dma.discount_model_license_category_id, MIN(dma.discount_model_attributes_id), 'between-models'
				FROM @discount_model_attributes dma
					INNER JOIN @last_order_discount_profile lodp
						ON lodp.last_order_license_category_id = dma.discount_model_license_category_id
				WHERE lodp.last_order_discount < dma.discount
				GROUP BY dma.discount_model_license_category_id

				--11.3 Condition to select the appropriate discount model when the last_order_discount is beneath all models
				IF NOT EXISTS (SELECT 1 FROM @next_model_match)
					BEGIN
						INSERT INTO @next_model_match (license_category_id, discount_model_attributes_id, match_type)
						SELECT dma.discount_model_license_category_id, MAX(dma.discount_model_attributes_id), 'below-models'
						FROM @discount_model_attributes dma
							INNER JOIN @last_order_discount_profile lodp
								ON lodp.last_order_license_category_id = dma.discount_model_license_category_id
						WHERE lodp.last_order_discount > dma.discount
							AND (lodp.last_order_license_attribute_license_value IS NULL OR lodp.last_order_license_attribute_license_value <> 12) --Cases where the last order was utility (discount is 100%) should not qualify for the next-level-up model
							AND (lodp.last_order_license_attribute_license_value IS NULL AND dma.discount_model_license_attribute_license_value IS NULL) OR (lodp.last_order_license_attribute_license_value = dma.discount_model_license_attribute_license_value) --Making the SFDC discount model with overage only available when the last order had overage 
						GROUP BY dma.discount_model_license_category_id
					END

				--11.4 Set discount on @item_discount_profile to last_order_discount for the appropriate categories if a between-match was found
				IF EXISTS (SELECT 1 FROM @next_model_match)
					BEGIN
						--14.4.1 Update @next_model_match
						UPDATE idp 
						SET idp.discount_model = dma.discount_model_id, idp.discount_model_license_attribute_license_value = dma.discount_model_license_attribute_license_value, 
						idp.discount = 
							CASE WHEN ntm.match_type = 'between-models' AND idp.license_seats >= dma.low_range AND idp.license_seats < dma.high_range THEN lodp.last_order_discount
							else null end
						from @discount_model_attributes dma
							inner join @next_model_match ntm
								on ntm.discount_model_attributes_id = dma.discount_model_attributes_id
							inner join @item_discount_profile idp
								on idp.license_category_id = dma.discount_model_license_category_id
							inner join @last_order_discount_profile lodp
								on lodp.last_order_license_category_id = idp.license_category_id

						--11.4.2 If a match is made in @next_model_m
atch, but the license_category_id from @last_order_discount_profile is not in the current request, the current request's license categories should inherit the matched discount
						IF EXISTS (SELECT 1 FROM @item_discount_profile WHERE discount_model IS NULL)
							BEGIN
								--Get values from the @next_model_match discount
								declare @inherited_discount_model_id int, @inherited_discount_model_license_attribute_license_value int
								SELECT @inherited_discount_model_id = dma.discount_model_id, @inherited_discount_model_license_attribute_license_value = dma.discount_model_license_attribute_license_value
								FROM @discount_model_attributes dma
									INNER JOIN @next_model_match nmm
										ON nmm.discount_model_attributes_id = dma.discount_model_attributes_id

								--Update the current rquest with the above values for license categories that don't exist in @last_order_discount_profile, and have yet to be assigned a discount model
								UPDATE idp 
								SET idp.discount_model = @inherited_discount_model_id, idp.discount_model_license_attribute_license_value = @inherited_discount_model_license_attribute_license_value
								FROM @item_discount_profile idp
									LEFT JOIN @last_order_discount_profile lodp
										ON lodp.last_order_license_category_id = idp.license_category_id
								WHERE idp.discount_model IS NULL
									AND lodp.last_order_license_category_id IS NULL
							END
					END
					GOTO current_request_lookup
				
			END
	END

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--12.  Current Request Lookup: setting discount on @item_discount_profile based on the model(s) seleced from the above
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	current_request_lookup:

	--12.1 Default discount_model to standard if any categories failed to be defined
	IF EXISTS (SELECT license_category_id FROM @item_discount_profile WHERE discount_model IS NULL)
		BEGIN
			UPDATE idp 
			SET idp.discount_model = 4 --Standard model
			FROM @item_discount_profile idp
			WHERE discount_model IS NULL
		END

	--12.2 Discount for Utility when the last order was not Utility and matched SFDC discount model
	UPDATE idp 
	SET idp.discount_model_license_attribute_license_value = i.license_attribute_license_value, idp.discount = i.discount, idp.cart_discount_method_id = i.cart_discount_method_id, idp.cart_discount_id = i.cart_discount_id
	FROM @item_discount_profile idp
		INNER JOIN dbo.cart_discount c
			ON c.cart_discount_type_id = idp.discount_model AND c.cart_discount_status_id = 1 --Active
		INNER JOIN dbo.cart_discount_item i
			ON i.cart_discount_id = c.cart_discount_id AND i.license_category_id = idp.license_category_id AND i.license_attribute_license_value = idp.license_attribute_license_value
	WHERE i.low_range <= idp.license_seats AND idp.license_seats < i.high_range
		AND idp.license_attribute_license_value = 12

	--12.3 Hack to set discount to 0 for Utility when discount model is Standard
	UPDATE idp 
	SET idp.discount = 0
	FROM @item_discount_profile idp
		WHERE idp.license_attribute_license_value = 12
			AND idp.discount_model = 4

	--12.4 get standard discount for licenses based on usage pricing model and retention
	UPDATE idp 
	SET idp.discount = i.discount, idp.cart_discount_method_id = i.cart_discount_method_id, idp.cart_discount_id = i.cart_discount_id, idp.sap_material_number = i.sap_material_number
	FROM @item_discount_profile idp
		INNER JOIN dbo.cart_discount c
			ON c.cart_discount_type_id = idp.discount_model AND c.cart_discount_status_id = 1 --Active
		INNER JOIN dbo.cart_discount_item i
			ON i.cart_discount_id = c.cart_discount_id AND i.product_type_id = idp.product_type_id
		INNER JOIN dbo.product_extension
 pe 
			ON pe.product_id = i.product_id
		INNER JOIN @CARBONITE_LICENSE_CATEGORIES clc
			ON CLC.license_category_id = idp.license_category_id
		CROSS APPLY dbo.fn_product_select_product_extension(pe.product_extension_json) ex
		CROSS APPLY dbo.fn_license_select_license_profile(idp.license_id) f
	WHERE idp.discount_model_license_attribute_license_value IS NULL
		AND i.license_attribute_license_value IS NULL
		AND (
				(idp.usage_pricing_model_id = 2 AND idp.storage_gb > i.low_range AND idp.storage_gb <= i.high_range)
				OR
				(idp.usage_pricing_model_id <> 2 AND i.low_range <= idp.license_seats AND idp.license_seats < i.high_range)
			)
		AND idp.license_category_id = i.license_category_id
		AND idp.years = i.years
		AND ex.usage_pricing_model_id = idp.usage_pricing_model_id
		AND ISNULL(ex.retention_model_id,0) = ISNULL(idp.retention_model_id,0)

	--12.5 Standard and SFDC non-overage
	UPDATE idp 
	SET idp.discount = i.discount, idp.cart_discount_method_id = i.cart_discount_method_id, idp.cart_discount_id = i.cart_discount_id
	FROM @item_discount_profile idp
		INNER JOIN dbo.cart_discount c
			ON c.cart_discount_type_id = idp.discount_model AND c.cart_discount_status_id = 1 --Active
		INNER JOIN dbo.cart_discount_item i
			ON i.cart_discount_id = c.cart_discount_id AND i.product_type_id = idp.product_type_id
	WHERE idp.discount IS NULL
		AND idp.discount_model_license_attribute_license_value IS NULL
		AND i.license_attribute_license_value IS NULL
		AND i.low_range <= idp.license_seats AND idp.license_seats < i.high_range
		AND idp.license_category_id = i.license_category_id
		--and idp.years = i.years

	--12.6 Cases where the current request qualifies for SFDC model with Overage based on discount history
	UPDATE idp 
	SET idp.discount = i.discount, idp.cart_discount_method_id = i.cart_discount_method_id, idp.cart_discount_id = i.cart_discount_id
	FROM @item_discount_profile idp
		INNER JOIN dbo.cart_discount c
			ON c.cart_discount_type_id = idp.discount_model AND c.cart_discount_status_id = 1 --Active
		INNER JOIN dbo.cart_discount_item i
			ON i.cart_discount_id = c.cart_discount_id AND i.product_type_id = idp.product_type_id
	WHERE idp.discount IS NULL
		AND idp.discount_model = 7 --Overage discounting only applies to SFDC model
		AND i.low_range <= idp.license_seats AND idp.license_seats < i.high_range
		AND i.license_attribute_license_value = idp.discount_model_license_attribute_license_value
		--and idp.years = i.years
		AND idp.license_category_id = i.license_category_id

	--12.7 If no discount exists, set 0
	UPDATE idp 
	SET discount = 0
	FROM @item_discount_profile idp
	WHERE discount IS NULL

	------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Return
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	SET @item_discount_profile_json = (SELECT * FROM @item_discount_profile FOR JSON PATH)

	UPDATE dbo.license_category_discount_model_json 
	SET item_discount_profile_json = @item_discount_profile_json
	WHERE license_category_discount_model_json_id = @license_category_discount_model_json_id

END TRY

BEGIN CATCH

	DECLARE @DBName NVARCHAR(128) = DB_NAME()
	EXEC usp_LogError @ErrorDB = @DBName

	UPDATE dbo.license_category_discount_model_json
	SET db_error_message = ERROR_MESSAGE()
	WHERE license_category_discount_model_json_id = @license_category_discount_model_json_id

	--returning whatever does exist in the table variable
	select *
	from @item_discount_profile

end catch

GO
