-- PROCEDURE: [dbo].[usp_license_select_child_license_count]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_child_license_count]

(	
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2006-08-31	esmart		Initial creation.
	2016-05-25	cnovac		Breaking out active vs. inactive counts

	DESCRIPTION
	Returns a count child license_ids	
*/

AS
	set nocount on

	declare @child_license_count int,
			@child_license_count_disabled int

	select @child_license_count = count(lp.child_license_id)
	from license_parent lp
	inner join license l on l.license_id = lp.child_license_id
	where lp.parent_license_id = @license_id
	and l.license_status_id = 1 --only get active

	select @child_license_count_disabled = count(lp.child_license_id)
	from license_parent lp
	inner join license l on l.license_id = lp.child_license_id
	where lp.parent_license_id = @license_id
	and l.license_status_id != 1 --only get non-active

	select @child_license_count as child_license_count, @child_license_count_disabled as child_license_count_disabled

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_child_licenses]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_child_licenses]

(	
	@license_id int = NULL,
	@keycode varchar(40) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2006-08-31	esmart		Initial creation.
	2013-01-31	esmart		Add child license details
	2014-03-30	esmart		Add additional columns
	2016-02-19	acoffel		Added license_status_description
	2016-06-10	esmart		license migration
	2017-06-08	acoffel		select and concatenate modules
	2019-07-23	wbarton		Adding the option to call the proc with keycode, for partner cart GET child license API.
	2020-01-16	abelenkiy	Added mar_name to output if exists; removed unnecessary license_module_license join for count
	2020-04-24	abelenkiy	Hard-coded select top to 1000; removed unused logic and variables
	2020-09-17	abelenkiy	Changed datatypes in @child_license table to match source fields
	2021-07-26  abelenkiy   Moved marname out of select and into update

	DESCRIPTION
	Return top 1000 child licenses for parent input. Called by CSI.
*/

AS
	set nocount on

	if @license_id IS NULL 
		begin 
			select @license_id = l.license_id
			from dbo.license l with (nolock)
			where l.keycode = @keycode
		end
	
	declare @child_license table (license_id int, keycode varchar(40), customer_id int, product_line_id int, license_status_id int, license_type_id int, license_distribution_method_id int, 
								license_keycode_type_id int, insert_date datetime, insert_by varchar(50), modified_date datetime, modified_by varchar(50), license_seats int, license_category_id int, 
								license_category_name varchar(10), capability_type_id int, capability_type_description varchar(20), capability_activation_date datetime, capability_expiration_date datetime,
								license_status_description varchar(20), license_migration varchar(3), license_module_name varchar(50), license_module_type_name varchar(50), mar_name nvarchar(1000))	
	
	insert into @child_license (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, 
								license_keycode_type_id, insert_date, insert_by, modified_date, modified_by, license_seats, license_category_id, 
								license_category_name, capability_type_id, capability_type_description, capability_activation_date, capability_expiration_date,
								license_status_description, license_migration, license_module_name, license_module_type_name)
	select top(1000) l.license_id, 
					l.keycode, 
					l.customer_id, 
					l.product_line_id, 
					l.license_status_id, 
					l.license_type_id, 
					l.license_distribution_method_id, 
					l.license_keycode_type_id, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by,
					s.license_seats,
					c.license_category_id, 
					c.license_category_name,
					t.capability_type_id, 
					t.capability_type_description,
					cp.capability_activation_date,
					cp.capability_expiration_date,
					ls.license_status_description,
					license_migration = case when m.license_migration_id is not null then 'Yes' else 'No' end,
					lm.license_module_name,
					mt.license_module_type_name
					--mn.mar_name
	from license_parent p with (nolock)
	inner join license l with (nolock)
		on p.child_license_id = l.license_id
	inner join license_status ls
		on l.license_status_id = ls.license_status_id
	left join license_seat s with (nolock)
		on l.license_id = s.license_id
	left join license_category_license cl with (nolock)
		on l.license_id = cl.license_id
	left join license_category c with (nolock)
		on cl.license_category_id = c.license_category_id
	left join license_capability cp with (nolock)
		on l.license_id = cp.license_id and cp.capability_id = c.base_capability_id
	left join capability_
type t with (nolock)
		on cp.capability_type_id = t.capability_type_id
	left join license_migration m
		on p.child_license_id = m.original_license_id
	left join license_module_license ml
		on l.license_id = ml.license_id 
	left join license_module lm
		on ml.license_module_id = lm.license_module_id
	left join license_module_type mt
		on ml.license_module_type_id = mt.license_module_type_id
	--outer apply fn_license_select_mar_name(l.license_id) mn
	where p.parent_license_id = @license_id
	order by l.license_id desc

	
	update cl
	set mar_name = f.mar_name
	from @child_license cl
		cross apply fn_license_select_mar_name(cl.license_id) f

	select distinct l.license_id, l.keycode, l.customer_id, l.product_line_id, l.license_status_id, l.license_type_id, l.license_distribution_method_id, 
								l.license_keycode_type_id, l.insert_date, l.insert_by, l.modified_date, l.modified_by, license_seats, l.license_category_id, 
								l.license_category_name, l.capability_type_id, l.capability_type_description, l.capability_activation_date, l.capability_expiration_date,
								l.license_status_description, l.license_migration, stuff((select distinct '|' + license_module_name + ':' + license_module_type_name  from @child_license where license_id = l.license_id --+ '|' + left(license_id,10)
            for xml path('')) ,1,1,'') as license_module_name, l.mar_name
	from @child_license l

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_child_parent_license]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_license_select_child_parent_license]

(	
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-20	esmart		Initial creation.

	DESCRIPTION
	Return all child license_ids	
*/

AS
	set nocount on

	declare @parent_license_id int,
			@parent_keycode varchar(40),
			@child_keycode varchar(40)

	select @parent_license_id = p.parent_license_id,
			@child_keycode = l.keycode
	from license_parent p
	inner join license l
		on p.child_license_id = l.license_id 
	where p.child_license_id = @license_id

	select @parent_keycode = keycode
	from license 
	where license_id = @parent_license_id

	select parent_keycode = @parent_keycode, child_keycode = @child_keycode



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_console_activity]
                @license_id int,
                @gsm bit,
                @process_date date

/*           
                DATE                     AUTHOR                              REMARKS
                2016-05-11          cnovac                  Initial creation.
                2016-09-06          cnovac                  Changed queries to only use sky_console_usage
                2016-12-28          cnovac                  Changed queries to seperate out full licenses vs trial licenses
				2018-06-18			rvinoche				Remove win10pcs
				2018-08-16			rvinoche				Simplify to remove homogenous result set
*/
as

begin try

	declare @keycode varchar(50)
	declare @console_activity table (sum_active_last_30_day_devices_full int, sum_active_last_30_day_devices_trial int, proxy_sum_active_last_30_day_devices_full int, proxy_sum_active_last_30_day_devices_trial int, billing_day_of_month tinyint, license_id int, 
				keycode varchar(50), marnames varchar(100), parentkeycode varchar(50), active_last_30_day_devices int, licensetype varchar(50), license_category_name varchar(10), proxy_active_last_30_day_devices int)

	select @keycode = keycode
	from dbo.license
	where license_id = @license_id

	if @gsm = 1
	begin                      
		insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices)
		select lac.billing_day_of_month,
			scu.license_id,
			scu.keycode,
			scu.marnames,
			scu.parentkeycode,
			isnull(scu.dbactivelast30days, 0),
			iif(scu.licensetype = 'enterprise,full', 'full', 'trial'),
			'SAEP',
			null -- proxy usage data
		from DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage scu
		left join license_autorenewal_cycle lac 
			on lac.license_id = @license_id
		where scu.parentkeycode = @keycode
		and scu.effective_date = (select max(scu2.effective_date)
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage scu2
								where scu.license_id = scu2.license_id 
									and scu2.effective_date <= @process_date)
		group by lac.billing_day_of_month,
										scu.license_id,
										scu.keycode,
										scu.marnames,
										scu.parentkeycode,
										scu.dbactivelast30days,
										scu.licensetype

		;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_full from @console_activity where licensetype = 'full')
		update @console_activity
		set sum_active_last_30_day_devices_full = temp.sum_active_last_30_day_devices_full
		from temp

		;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_trial from @console_activity where licensetype = 'trial')
		update @console_activity
		set sum_active_last_30_day_devices_trial = temp.sum_active_last_30_day_devices_trial
		from temp

		select sum_active_last_30_day_devices_full, sum_active_last_30_day_devices_trial, proxy_sum_active_last_30_day_devices_full, proxy_sum_active_last_30_day_devices_trial, billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices
		from @console_activity

	end
	else
	begin

		select null, null, null, null, --sum fields for parent licenses
			lac.billing_day_of_month,
			scu.license_id,
			scu.keycode,
			scu.marnames,
			scu.parentkeycode,
			scu.dbactivelast30days as active_last_30_day_devices,
			iif(scu.licensetype = 'enterprise,full', 'full', 'trial') as licensetype,
			'SAEP' license_category_name,
			null -- proxy data
		from DATAWAREHOUSEREADONLY.Fe
ed.dbo.sky_console_usage scu
		left join license_autorenewal_cycle lac on lac.license_id = scu.license_id
		where scu.license_id = @license_id
		and scu.effective_date = (select max(scu2.effective_date) 
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage scu2
								where scu.license_id = scu2.license_id 
								and scu2.effective_date <= @process_date)
	end

	end try
begin catch

    declare @response_code int,
            @message varchar(100),
            @DBName nvarchar(128)

    set @response_code = -200
    set @message = case when @message is null then 'error processing usp_license_select_console_activity'
						else @message end
    set @DBName = db_name()

    exec usp_LogError @ErrorDB = @DBName

end catch;
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_all]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_console_activity_all]
	@keycode varchar(50),
	@report_type varchar(50), --ACTIVE|ACTIVE_WITHOUT_HIDDEN|SEEN_LAST_30_DAYS
	@report_date date,
	@site_keycode varchar(50) = null

/*
	DATE		AUTHOR		REMARKS
	2018-01-16	cnovac		Initial creation.
	2018-03-05	cnovac		Added SDNS/SECA data from SkyLake
	2018-06-21	cnovac		Added logging to console_activity_all_log
	2019-04-25	rvinoche	Refactor to use activity functions used for billing and CSI display
	2019-05-10	cnovac		Hotfix to change how agentless_units are calculated
	2019-05-13	cnovac		Updated SDNS line to get agentless_units from dns_ip_requests_calculated since the math is now done in fn_license_select_license_activity_sites
	2019-10-09	abelenkiy	Declared and set @category_type_name for parent from fn_license_select_license_profile and selected in parent section of output
							Updated stand-alone 'else' to return all categories instead of just SAEP
							Replaced usage table variables with single @usage_all table that includes expiration_date and removed fn_license_select_license_profile call from inserts to @console_activity
							Changed proxy DNS to pull SAEP data from SAEP full when both full and trial exist for DNS
	2020-03-31	cnovac		Added usage for OTSF

*/
as

begin try

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

set nocount on

	declare @parent_license_id int,
			@license_type_id int,
			@keycode_local varchar(50) = @keycode,
			@report_type_local varchar(50) = @report_type, --ACTIVE|ACTIVE_WITHOUT_HIDDEN|SEEN_LAST_30_DAYS
			@report_date_local date = @report_date,
			@site_keycode_local varchar(50) = @site_keycode,
			@console_activity_all_guid uniqueidentifier = newid(),
			@license_id int,
			@license_expiration_date datetime,
			@category_type_name varchar(50)

	declare @usage_all table (license_id int, keycode varchar(50), license_category_name varchar(50), license_type varchar(50), dns_ip_requests_calculated int, dns_ip_requests int, dns_agent_requests int, units int, license_category_expiration_date date)
	declare @console_activity table (license_id int, keycode varchar(50), license_keycode_type varchar(50), license_category_name varchar(50), license_category_expiration_date date,  
									license_type varchar(50), unit_type varchar(50), units int, sum_sites_full int, sum_sites_trial int, sum_units_full int, sum_units_trial int)

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	--log the start of the call with an 'S' for start
	insert into console_activity_all_log (console_activity_all_guid, console_activity_all_type, keycode, report_type, report_date, site_keycode)
	values (@console_activity_all_guid, 'S', @keycode_local, @report_type_local, @report_date_local, @site_keycode_local)

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	select @license_id = license_id from dbo.license where keycode = @keycode

	--see if this keycode is a GSM
	select @parent_license_id = lp.parent_license_id,
		   @license_type_id = l.license_type_id,
		   @license_expiration_date = f.expiration_date,
		   @category_type_name = f.category_type_name
	from dbo.fn_license_select_license_profile(@license_id) f
	inner join dbo.license l on l.license_id = f.license_id
	le
ft join dbo.license_parent lp
		on lp.child_license_id = l.license_id
	where f.license_category_name in ('SAEP', 'OTSF') --endpoint protection|O365
	and f.item_hierarchy_id = 1

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	--only get into this code if it's a GSM keycode
	if @parent_license_id is not null or @license_type_id <> 4 --Enterprise which is standalone
	begin

		select @license_id = iif(@parent_license_id is not null, @parent_license_id, @license_id)

		--get usage for all products/sites into one table
		insert into @usage_all (license_id, keycode, license_category_name, license_type, units, dns_ip_requests_calculated, dns_ip_requests, dns_agent_requests, license_category_expiration_date)
		select f.license_id,
				p.keycode,
				f.license_category_name,
				iif(f.capability_type_id = 1, 'full', 'trial'),
		       case when f.license_category_name = 'SAEP' and @report_type_local = 'active' then f.active_devices
                    when f.license_category_name = 'SAEP' and @report_type_local = 'active_without_hidden' then f.total_devices
                    else f.console_activity
                end,
				f.dns_ip_requests_calculated,
				f.dns_ip_requests,
				f.dns_agent_requests,
				p.expiration_date
		from dbo.fn_license_select_license_activity_sites(@license_id, @report_date, default) f
		cross apply dbo.fn_license_select_license_profile(f.license_id) p
		where p.license_category_name = f.license_category_name
                    
		--add SAEP usage to @console_activity
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_category_expiration_date,
			   u.license_type,
			   'AGENT',
			   u.units
		from @usage_all u
		where u.license_category_name in ('SAEP', 'OTSF')

		--add SDNS usage to @console_activity for proxy
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_category_expiration_date,
			   u.license_type,
			   'PROXY',
			   ca.units
		from (select license_id, keycode, license_category_name, license_type, license_category_expiration_date, rank() over(partition by license_id order by license_type) as rank
				from @usage_all
				where license_category_name = 'SDNS') u
		inner join  @console_activity ca on ca.license_id = u.license_id-- pulling from SAEP data above because as proxy we want to get the SAEP usage data for those sites
			and ca.license_category_name = 'SAEP' 
		where u.rank = 1

		--add SDNS usage to @console_activity from @usage_dns for agent
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_category_expiration_date,
			   u.license_type,
			   'AGENT',
			   u.dns_agent_requests
		from @usage_all u
		where u.dns_agent_requests is not null
			and u.license_category_name = 'SDNS'

		--add SDNS usage to @console_activity from @usage_dns for non-agent (agentless_units)
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_
category_expiration_date,
			   u.license_type,
			   'AGENTLESS',
			   u.dns_ip_requests_calculated
		from @usage_all u
		where u.dns_ip_requests_calculated is not null
			and u.license_category_name = 'SDNS'

		--add SDNS usage to @console_activity from @usage_dns for non-agent (agentlessrequests_units)
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_category_expiration_date,
			   u.license_type,
			   'AGENTLESSREQUESTS',
			   u.dns_ip_requests
		from @usage_all u
		where u.dns_ip_requests is not null
			and u.license_category_name = 'SDNS'

		--add SECA usage to @console_activity from @@usage_seca
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   u.license_category_name,
			   u.license_category_expiration_date,
			   u.license_type,
			   'USER',
			   u.units
		from @usage_all u
		where u.license_category_name = 'SECA'

		--sum up the units and count the sites for the parent summary
		;with temp as (select sum(isnull(units, 0)) as sum_units,
							  count(*) as sum_sites,
							  license_category_name,
							  license_type,
							  unit_type
					   from @console_activity
					   group by license_category_name, license_type, unit_type)
		update ca
		set sum_units_full = isnull(t.sum_units, 0),
			sum_sites_full = isnull(t.sum_sites, 0),
			sum_units_trial = isnull(t2.sum_units, 0),
			sum_sites_trial = isnull(t2.sum_sites, 0)
		from @console_activity ca
		left join temp t on t.license_category_name = ca.license_category_name and ca.unit_type = t.unit_type and t.license_type = 'FULL'
		left join temp t2 on t2.license_category_name = ca.license_category_name and ca.unit_type = t2.unit_type and t2.license_type = 'TRIAL'

	end
	else --this would be for all stand-alone keycodes
	begin

		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, sum_units_full)
		select f.license_id,
			   l.keycode,
			   'STANDARD',
			   f.license_category_name,
			   p.expiration_date,
			   'FULL',
			   'AGENT',
			   case @report_type_local
					when 'ACTIVE' then f.active_devices
					when 'ACTIVE_WITHOUT_HIDDEN' then f.total_devices
					when 'SEEN_LAST_30_DAYS' then f.console_activity
					else -1 --some unsupported parameter passed in
				end
		from dbo.fn_license_select_license_activity(@license_id,@report_date,'full',default) f
		inner join dbo.license l on l.license_id = f.license_id
		cross apply dbo.fn_license_select_license_profile(@license_id) p

		--just do this to get rid of NULLS in result set
		update ca
		set ca.units = ca.sum_units_full + ca.sum_units_trial
		from @console_activity ca

		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, sum_units_trial)
		select f.license_id,
			l.keycode,
			'STANDARD',
			f.license_category_name,
			p.expiration_date,
			'TRIAL',
			'AGENT',
			case @report_type_local
				when 'ACTIVE' then f.active_devices
				when 'ACTIVE_WITHOUT_HIDDEN' then f.total_devices
				when 'SEEN_LAST_30_DAYS' then f.console_activity
				else -1 --some unsupported parameter passed in
			END
		from dbo.fn_license_select_license_activity(@license_id,@report_date,'trial',default) f
		inner join dbo.license l ON l.license_id = f.license_id
		cross apply dbo.fn_license_select_license_profile(@license_id) p

		--just do this to get rid of NULLS in result set
		update ca
		set ca.units = ca.sum_units_full + ca.sum_units
_trial
		from @console_activity ca
	end

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

		select @report_type_local as report_type, @report_date_local as report_date, @license_id as license_id, @keycode_local as keycode, ca.license_keycode_type,
			   ca.license_category_name as categories, @category_type_name as license_type, @license_expiration_date as expiration_date,
			   ca.sum_sites_full as total_sites_with_full, ca.sum_sites_trial as total_sites_with_trial, ca.unit_type, ca.sum_units_full as total_units_with_full, 
			   ca.sum_units_trial as total_units_with_trial, ca.license_id as site_license_id, ca.keycode as site_keycode, ca.license_category_name as site_categories, 
			   ca.license_category_expiration_date as site_expiration_date, ca.license_type as site_license_type, ca.unit_type as site_unit_type, ca.units as site_total_units
		from @console_activity ca
		where keycode = case when @site_keycode_local is not null then @site_keycode_local else ca.keycode end
		order by ca.license_category_name, ca.unit_type, ca.license_id

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	--log the end of the call with an 'E' for end
	insert into console_activity_all_log (console_activity_all_guid, console_activity_all_type, keycode, report_type, report_date, site_keycode)
	values (@console_activity_all_guid, 'E', @keycode_local, @report_type_local, @report_date_local, @site_keycode_local)

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

--Types
--•	Endpoint
	--o Agent
--•	DNS
	--o Agent
	--o Agentless
	--o Agentlessrequests
	--o	Proxy
--•	WSAT
	--o User

end try
begin catch
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_all_NEW]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_console_activity_all_NEW]
	@keycode varchar(50),
	@report_type varchar(50), --ACTIVE|ACTIVE_WITHOUT_HIDDEN|SEEN_LAST_30_DAYS
	@report_date date,
	@site_keycode varchar(50) = null

/*
	DATE		AUTHOR		REMARKS
	2018-01-16	cnovac		Initial creation.
	2018-03-05	cnovac		Added SDNS/SECA data from SkyLake
	2018-06-21	cnovac		Added logging to console_activity_all_log
	2019-04-25	rvinoche	Refactor to use activity functions used for billing and CSI display
	2019-05-10	cnovac		Hotfix to change how agentless_units are calculated
	2019-05-13	cnovac		Updated SDNS line to get agentless_units from dns_ip_requests_calculated since the math is now done in fn_license_select_license_activity_sites

*/
as

begin try

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

set nocount on

	declare @parent_license_id int,
			@license_type_id int,
			@keycode_local varchar(50) = @keycode,
			@report_type_local varchar(50) = @report_type, --ACTIVE|ACTIVE_WITHOUT_HIDDEN|SEEN_LAST_30_DAYS
			@report_date_local date = @report_date,
			@site_keycode_local varchar(50) = @site_keycode,
			@console_activity_all_guid uniqueidentifier = newid(),
			@license_id int,
			@license_expiration_date datetime

	declare @usage table (license_id int, keycode varchar(50), license_category_id int, license_type varchar(50), units int)
	declare @usage_dns table (license_id int, keycode varchar(50), license_category_id int, license_type varchar(50), ipagent varchar(50), agent_units int, agentless_units int, agentlessrequests_units int)
	declare @usage_seca table (license_id int, keycode varchar(50), license_category_id int, license_type varchar(50), user_units int)
	declare @console_activity table (license_id int, keycode varchar(50), license_keycode_type varchar(50), license_category_name varchar(50), license_category_expiration_date date,  
									license_type varchar(50), unit_type varchar(50), units int, sum_sites_full int, sum_sites_trial int, sum_units_full int, sum_units_trial int)

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	--log the start of the call with an 'S' for start
	insert into console_activity_all_log (console_activity_all_guid, console_activity_all_type, keycode, report_type, report_date, site_keycode)
	values (@console_activity_all_guid, 'S', @keycode_local, @report_type_local, @report_date_local, @site_keycode_local)

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------

	select @license_id = license_id from dbo.license where keycode = @keycode

	--see if this keycode is a GSM
	select @parent_license_id = lp.parent_license_id,
		   @license_type_id = l.license_type_id,
		   @license_expiration_date = f.expiration_date
	from dbo.fn_license_select_license_profile(@license_id) f
	inner join dbo.license l on l.license_id = f.license_id
	left join dbo.license_parent lp
		on lp.child_license_id = l.license_id
	where f.license_category_name = 'SAEP' --endpoint protection

	-----------------------------------------------------------------------------------------------------------------------------------------------
	-----------------------------------------------------------------------------------------------------------------------------------------------


	--only get into this code if it's a GSM keycode
	if @parent_license_id is not null or @license_type_id <> 4 --Enterprise which is standalone
	begin
   
		select @license_id = iif(@parent_license_id is not null, @parent_license_id, @license_id)

		--get all usage for SAEP child sites
		insert into @usage (license_id, keycode, license_category_id, license_type, units)
		select f.license_id,
				l.keycode,
				220,
				iif(f.capability_type_id = 1, 'full', 'trial'),
				case @report_type_local
					when 'active' then f.active_devices
					when 'active_without_hidden' then f.total_devices 
					when 'seen_last_30_days' then f.console_activity
				end 
		from dbo.fn_license_select_license_activity_sites(@license_id, @report_date, 'SAEP') f
		inner join dbo.license l on l.license_id = f.license_id

		--get all usage for SDNS child sites
		insert into @usage_dns (license_id, keycode, license_category_id, license_type, agent_units, agentless_units, agentlessrequests_units)
		select f.license_id,
				l.keycode,
				230,
			    iif(f.capability_type_id = 1, 'full', 'trial'),
			    f.dns_agent_requests,
			    f.dns_ip_requests_calculated,
			    f.dns_ip_requests
		from dbo.fn_license_select_license_activity_sites(@license_id, @report_date, 'SDNS') f
		inner join dbo.license l on l.license_id = f.license_id

		--get all usage for SECA child sites
		insert into @usage_seca (license_id, keycode, license_category_id, license_type, user_units)
		select f.license_id,
			l.keycode,
			231,
			iif(f.capability_type_id = 1, 'full', 'trial'),
			f.console_activity
		from dbo.fn_license_select_license_activity_sites(@license_id, @report_date, 'SECA') f
		inner join dbo.license l ON l.license_id = f.license_id
		
		--add SAEP usage to @console_activity
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SAEP',
			   f.expiration_date,
			   u.license_type,
			   'AGENT',
			   u.units
		from @usage u
		cross apply dbo.fn_license_select_license_profile(u.license_id) f
		where f.license_category_name = 'SAEP'
		
		--add SDNS usage to @console_activity for proxy
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SDNS',
			   p.expiration_date,
			   u.license_type,
			   'PROXY',
			   f.console_activity
		from @usage_dns u
		cross apply dbo.fn_license_select_license_profile(u.license_id) p
		outer apply dbo.fn_license_select_license_activity(u.license_id,@report_date,license_type,'SAEP') f -- SAEP because as proxy we want to get the SAEP usage data for those sites
		where p.license_category_name = 'SDNS'
		
		--add SDNS usage to @console_activity from @usage_dns for agent
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SDNS',
			   p.expiration_date,
			   u.license_type,
			   'AGENT',
			   u.agent_units
		from @usage_dns u
		cross apply dbo.fn_license_select_license_profile(u.license_id) p
		where u.agent_units is not null
			AND p.license_category_name = 'SDNS'

		--add SDNS usage to @console_activity from @usage_dns for non-agent (agentless_units)
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SDNS',
			   p.expiration_date,
			   u.license_type,
			   'AGENTLESS',
			   u.agentless_units
		from @usage_dns u
		cross apply dbo.fn_license_select
_license_profile(u.license_id) p
		where u.agentless_units is not null
			and p.license_category_name = 'SDNS'

		--add SDNS usage to @console_activity from @usage_dns for non-agent (agentlessrequests_units)
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SDNS',
			   p.expiration_date,
			   u.license_type,
			   'AGENTLESSREQUESTS',
			   u.agentlessrequests_units
		from @usage_dns u
		cross apply dbo.fn_license_select_license_profile(u.license_id) p
		where u.agentlessrequests_units is not null
			and p.license_category_name = 'SDNS'

		--add SECA usage to @console_activity from @@usage_seca
		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, units)
		select u.license_id,
			   u.keycode,
			   'PARENT',
			   'SECA',
			   p.expiration_date,
			   u.license_type,
			   'USER',
			   u.user_units
		from @usage_seca u
		cross apply dbo.fn_license_select_license_profile(u.license_id) p
		where p.license_category_name = 'SECA'

		--sum up the units and count the sites for the parent summary
		;with temp as (select sum(isnull(units, 0)) as sum_units,
							  count(*) as sum_sites,
							  license_category_name,
							  license_type,
							  unit_type
					   from @console_activity
					   group by license_category_name, license_type, unit_type)
		update ca
		set sum_units_full = isnull(t.sum_units, 0),
			sum_sites_full = isnull(t.sum_sites, 0),
			sum_units_trial = isnull(t2.sum_units, 0),
			sum_sites_trial = isnull(t2.sum_sites, 0)
		from @console_activity ca
		left join temp t on t.license_category_name = ca.license_category_name and ca.unit_type = t.unit_type and t.license_type = 'FULL'
		left join temp t2 on t2.license_category_name = ca.license_category_name and ca.unit_type = t2.unit_type and t2.license_type = 'TRIAL'

	end
	else --this would be for all stand-alone keycodes
	begin

		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, sum_units_full)
		select f.license_id,
			   l.keycode,
			   'STANDARD',
			   p.license_category_name,
			   p.expiration_date,
			   'FULL',
			   'AGENT',
			   case @report_type_local
					when 'ACTIVE' then f.active_devices
					when 'ACTIVE_WITHOUT_HIDDEN' then f.total_devices
					when 'SEEN_LAST_30_DAYS' then f.console_activity
					else -1 --some unsupported parameter passed in
				end
		from dbo.fn_license_select_license_activity(@license_id,@report_date,'full','SAEP') f
		inner join dbo.license l on l.license_id = f.license_id
		cross apply dbo.fn_license_select_license_profile(@license_id) p

		--just do this to get rid of NULLS in result set
		update ca
		set ca.units = ca.sum_units_full + ca.sum_units_trial
		from @console_activity ca

		insert into @console_activity (license_id, keycode, license_keycode_type, license_category_name, license_category_expiration_date, license_type, unit_type, sum_units_trial)
		select f.license_id,
			l.keycode,
			'STANDARD',
			p.license_category_name,
			p.expiration_date,
			'TRIAL',
			'AGENT',
			case @report_type_local
				when 'ACTIVE' then f.active_devices
				when 'ACTIVE_WITHOUT_HIDDEN' then f.total_devices
				when 'SEEN_LAST_30_DAYS' then f.console_activity
				else -1 --some unsupported parameter passed in
			END
		from dbo.fn_license_select_license_activity(@license_id,@report_date,'trial','SAEP') f
		inner join dbo.license l ON l.license_id = f.license_id
		cross apply dbo.fn_license_select_license_profile(@license_id) p

		--just do this to get rid of NULLS in result set
		update ca
		set ca.units = ca.sum_units_full + ca.sum_units_trial
		from
 @console_activity ca
	end


-------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 
-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_summary table (license_id int, parent_license_id int, license_type_id int, capability_expiration_date date, license_type varchar(50), license_category_name varchar(50))
	
		--get the summary data for endpoint parent or standalone key
	insert into @license_summary (license_id, parent_license_id, license_type_id, capability_expiration_date, license_type, license_category_name)
	select distinct
		   l.license_id,
		   lp.parent_license_id,
		   l.license_type_id,
		   lcap.capability_expiration_date,
		   iif(lcap.capability_type_id = 1, 'FULL', 'TRIAL'),
		   lc.license_category_name
	from license l
	inner join dbo.license_category_license lcl on lcl.license_id = l.license_id
	inner join dbo.license_category lc on lc.license_category_id = lcl.license_category_id
	inner join dbo.license_capability lcap on lcap.license_id = l.license_id and lcap.capability_id = lc.base_capability_id
	left join dbo.license_parent lp on lp.parent_license_id = l.license_id
	where l.keycode = @keycode_local

	--get the summary data for parent module products
	insert into @license_summary (license_id, capability_expiration_date, license_type, license_category_name)
	select l.license_id,
		   lml.end_date,
		   upper(lmt.license_module_type_name),
		   lc.license_category_name
	from dbo.license l
	inner join dbo.license_module_license lml on lml.license_id = l.license_id
	inner join dbo.license_module_type lmt on lmt.license_module_type_id = lml.license_module_type_id
	inner join dbo.license_module_category lmc on lmc.license_module_id = lml.license_module_id
	inner join dbo.license_category lc on lc.license_category_id = lmc.license_category_id
	where l.keycode = @keycode_local
	and lml.license_module_id in (30, 32) --DNS Protection parent, Security Awareness Training parent

	--see if this keycode is a GSM
	select @parent_license_id = parent_license_id,
		   @license_type_id = license_type_id
	from @license_summary
	where license_category_name = 'SAEP'

	if @site_keycode_local is null
	begin

		insert into temp_console_activity_all_log (report_type, report_date, license_id, keycode, license_keycode_type, categories, license_type, expiration_date, total_sites_with_full, total_sites_with_trial, unit_type, total_units_with_full, total_units_with_trial, site_license_id, site_keycode, site_categories, site_expiration_date, site_license_type, site_unit_type, site_total_units)
		select @report_type_local as report_type, @report_date_local as report_date, ls.license_id, @keycode_local as keycode, ca.license_keycode_type,
			   ls.license_category_name as categories, ls.license_type, ls.capability_expiration_date as expiration_date,
			   ca.sum_sites_full as total_sites_with_full, ca.sum_sites_trial as total_sites_with_trial, ca.unit_type, ca.sum_units_full as total_units_with_full, 
			   ca.sum_units_trial as total_units_with_trial, ca.license_id as site_license_id, ca.keycode as site_keycode, ca.license_category_name as site_categories, 
			   ca.license_category_expiration_date as site_expiration_date, ca.license_type as site_license_type, ca.unit_type as site_unit_type, ca.units as site_total_units
		from @console_activity ca
		inner join @license_summary ls on ls.license_category_name = ca.license_category_name
		order by 6

	end
	else
	begin
		insert into temp_console_activity_all_log (report_type, report_date, license_id, keycode, license_keycode_type, categories, license_type, expiration_date, total_sites_with_full, total_sites_with_trial, unit_type, total_units_with_full, total_units_with_trial, site_license_id, sit
e_keycode, site_categories, site_expiration_date, site_license_type, site_unit_type, site_total_units)
		select @report_type_local as report_type, @report_date_local as report_date, ls.license_id, @keycode_local as keycode, ca.license_keycode_type,
			   ls.license_category_name as categories, ls.license_type, ls.capability_expiration_date as expiration_date,
			   ca.sum_sites_full as total_sites_with_full, ca.sum_sites_trial as total_sites_with_trial, ca.unit_type, ca.sum_units_full as total_units_with_full, 
			   ca.sum_units_trial as total_units_with_trial, ca.license_id as site_license_id, ca.keycode as site_keycode, ca.license_category_name as site_categories, 
			   ca.license_category_expiration_date as site_expiration_date, ca.license_type as site_license_type, ca.unit_type as site_unit_type, ca.units as site_total_units
		from @console_activity ca
		inner join @license_summary ls on ls.license_category_name = ca.license_category_name
		where keycode = @site_keycode_local
		order by 6

	end

	-------------------------------------------------------------------------------------------------------------------------------------------------
	-------------------------------------------------------------------------------------------------------------------------------------------------

	--	select @report_type_local as report_type, @report_date_local as report_date, @license_id as license_id, @keycode_local as keycode, ca.license_keycode_type,
	--		   ca.license_category_name as categories, ca.license_type, @license_expiration_date as expiration_date,
	--		   ca.sum_sites_full as total_sites_with_full, ca.sum_sites_trial as total_sites_with_trial, ca.unit_type, ca.sum_units_full as total_units_with_full, 
	--		   ca.sum_units_trial as total_units_with_trial, ca.license_id as site_license_id, ca.keycode as site_keycode, ca.license_category_name as site_categories, 
	--		   ca.license_category_expiration_date as site_expiration_date, ca.license_type as site_license_type, ca.unit_type as site_unit_type, ca.units as site_total_units
	--	from @console_activity ca
	--	where keycode = case when @site_keycode_local is not null then @site_keycode_local else ca.keycode end
	--	order by ca.license_category_name, ca.unit_type, ca.license_id

	-------------------------------------------------------------------------------------------------------------------------------------------------
	-------------------------------------------------------------------------------------------------------------------------------------------------

	----log the end of the call with an 'E' for end
	--insert into console_activity_all_log (console_activity_all_guid, console_activity_all_type, keycode, report_type, report_date, site_keycode)
	--values (@console_activity_all_guid, 'E', @keycode_local, @report_type_local, @report_date_local, @site_keycode_local)

	-------------------------------------------------------------------------------------------------------------------------------------------------
	-------------------------------------------------------------------------------------------------------------------------------------------------

--Types
--•	Endpoint
	--o Agent
--•	DNS
	--o Agent
	--o Agentless
	--o Agentlessrequests
	--o	Proxy
--•	WSAT
	--o User

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_license_select_console_activity_all'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_headers]
-- =============================================================================
CREATE  procedure [dbo].[usp_license_select_console_activity_headers]
(
  @license_category_name varchar(10)
)
	

/*	
	DATE		AUTHOR		REMARKSprocedure 
	2020-10-30	g.lagos		Initial Version for story LAGER-2232
	2020-10-30	g.lagos		returning only headers by category_name, category_name is recieved as input
	2020-11-05	g.lagos		use standardized colunm names 
	2020-11-06	g.lagos		use join to get the name from license_category using new structure in license_category_activity_child_headers
	2020-11-12	g.lagos		renamed procedure and removed the 'child' wording since it's misleading, this is mapping of headers for Child and Parent records


*/
AS
set nocount on;
begin try

	declare @json varchar(max)


	select @json = 
	(select lc.license_category_name, lch.ecomm_column_name, lch.php_column_header
       from dbo.license_category_activity_headers lch JOIN dbo.license_category lc 
	   ON lch.license_category_id=lc.license_category_id 
       where lc.license_category_name = @license_category_name for json path, without_array_wrapper)


		select @json as license_category_activity_headers


end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@dbname nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_license_select_console_activity_child_headers'
						else @message end
	set @dbname = db_name()

	exec usp_logerror @errordb = @dbname

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_sdns]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_console_activity_sdns]
                @license_id int,
                @gsm bit,
                @process_date date

/*           
                DATE                     AUTHOR                              REMARKS
                2018-06-07				 rvinoche							 Initial creation
				2018-08-16				 rvinoche							 Add proxy data and return homogenous result set
				2018-10-22				 rvinoche							 Fix code to include agent usage correctly

*/
as

begin try

    declare @keycode varchar(50)
    declare @console_activity table (sum_active_last_30_day_devices_full int, sum_active_last_30_day_devices_trial int, proxy_sum_active_last_30_day_devices_full int, proxy_sum_active_last_30_day_devices_trial int, billing_day_of_month tinyint, license_id int, 
                                                                                                                                        keycode varchar(50), marnames varchar(100), parentkeycode varchar(50), active_last_30_day_devices float, licensetype varchar(50),license_category_name varchar(10), proxy_active_last_30_day_devices int, type tinyint, ipagent varchar(50))

    select @keycode = keycode
    from license
    where license_id = @license_id

    if @gsm = 1
    begin
       -- IP address usage only                             
        insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices, type, ipagent)
        select lac.billing_day_of_month,
                        l.license_id,
                        scu.keycode,
                        scu.marnames,
                        scu.parentkeycode,
                        isnull(iif(ipagent = 'agent', SUM(scu.dbseenlast30days), SUM(ceiling(cast(scu.dbseenlast30days as float)/30000))), 0),
                        iif(scu.licensetype IN ('enterprise,full', 'full', 'sme,full'), 'full', 'trial') as licensetype,
						'SDNS',
						ISNULL(sca.dbactivelast30days,0),
						1, -- IP address and agent usage data
						scu.ipagent
        from DATAWAREHOUSEREADONLY.Feed.dbo.sky_sdns_usage scu
		inner join dbo.license l
			on l.keycode = scu.keycode
        left join license_autorenewal_cycle lac 
			on lac.license_id = @license_id
		left join DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage sca
			on sca.license_id = l.license_id
        where scu.parentkeycode = @keycode
			and scu.log_date = (select max(scu3.log_date)
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_sdns_usage scu3
								where scu.keycode = scu3.keycode 
									and scu.ipagent = scu3.ipagent
									and scu3.log_date <= @process_date)
			and sca.effective_date = (select max(sca2.effective_date)
										from DATAWAREHOUSEREADONLY.feed.dbo.sky_console_usage sca2
										where sca2.license_id = sca.license_id
										and sca2.effective_date <= @process_date )
        group by lac.billing_day_of_month,
                                        l.license_id,
                                        scu.keycode,
                                        scu.marnames,
                                        scu.parentkeycode,
                                        scu.licensetype,
										sca.dbactivelast30days,
										scu.ipagent

		--sum both IP address usage and agent
		insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices, type)
		select  billing_day_of_month,
                license_id,
                keycode,
                marnames,
         
       parentkeycode,
                isnull(sum(active_last_30_day_devices),0),
                licensetype,
				license_category_name,
				isnull(sum(proxy_active_last_30_day_devices),0),
				2
		FROM @console_activity
		group by billing_day_of_month,
			    license_id,
				keycode,
				marnames,
				parentkeycode,
				licensetype,
				license_category_name

        ;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_full from @console_activity where licensetype = 'full' AND type = 2)
        update @console_activity
        set sum_active_last_30_day_devices_full = temp.sum_active_last_30_day_devices_full
        from temp

        ;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_trial from @console_activity where licensetype = 'trial' AND type = 2)
        update @console_activity
        set sum_active_last_30_day_devices_trial = temp.sum_active_last_30_day_devices_trial
        from temp

		;with temp as (select isnull(sum(proxy_active_last_30_day_devices),0) as proxy_sum_active_last_30_day_devices_full from @console_activity where licensetype = 'full' AND type = 2)
		update @console_activity
		set proxy_sum_active_last_30_day_devices_full = temp.proxy_sum_active_last_30_day_devices_full
		from temp
								
		;with temp as (select isnull(sum(proxy_active_last_30_day_devices),0) as proxy_sum_active_last_30_day_devices_trial from @console_activity where licensetype = 'trial' AND type = 2)
		update @console_activity
		set proxy_sum_active_last_30_day_devices_trial = temp.proxy_sum_active_last_30_day_devices_trial
		from temp
								 
    end
    else
    begin

		insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices, type, ipagent)
        select lac.billing_day_of_month,
			l.license_id,
			scu.keycode,
			scu.marnames,
			scu.parentkeycode,
			isnull(iif(ipagent = 'agent', SUM(scu.dbseenlast30days), SUM(ceiling(cast(scu.dbseenlast30days as float)/30000))),0),
			iif(scu.licensetype IN ('enterprise,full', 'full', 'sme,full'), 'full', 'trial') as licensetype,
			'SDNS' license_category_name,
			sca.dbactivelast30days,
			1,
			ipagent
        from DATAWAREHOUSEREADONLY.Feed.dbo.sky_sdns_usage scu
		inner join dbo.license l
			on l.keycode = scu.keycode
        left join dbo.license_autorenewal_cycle lac 
			on lac.license_id = l.license_id
		left join DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage sca
			on sca.license_id = l.license_id
        where l.license_id = @license_id
			and scu.log_date = (select max(scu3.log_date) 
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_sdns_usage scu3
								where scu.keycode = scu3.keycode 
								and scu.ipagent = scu3.ipagent
								and scu3.log_date <= @process_date)
			and sca.effective_date = (select max(sca2.effective_date)
									from DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage sca2
									where sca2.license_id = sca.license_id
									and sca2.effective_date <= @process_date )
		group by lac.billing_day_of_month,
			l.license_id,
			scu.keycode,
			scu.marnames,
			scu.parentkeycode,
			scu.licensetype,
			sca.dbactivelast30days,
			ipagent


		--sum both IP address usage and agent
		insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices, type)
		select  billing_day_of_month,
                license_id,
                keycode,
                marnames,
                parentkeycode,
                isnull(sum(active_last_30_day_devices),0),
                licensetype,
				license_category_name,
				isnull(sum(proxy_active_last_30_day_devices),0),
				2
		from @console_activity
		group by billing_d
ay_of_month,
			    license_id,
				keycode,
				marnames,
				parentkeycode,
				licensetype,
				license_category_name
	end
    
	select sum_active_last_30_day_devices_full, sum_active_last_30_day_devices_trial, proxy_sum_active_last_30_day_devices_full, proxy_sum_active_last_30_day_devices_trial, billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices
    from @console_activity
	where type = 2


end try
begin catch

    declare @response_code int,
            @message varchar(100),
            @DBName nvarchar(128)

    set @response_code = -200
    set @message = case when @message is null then 'error processing usp_license_select_console_activity'
                        else @message end
    set @DBName = db_name()

    exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_seca]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_console_activity_seca]
                @license_id int,
                @gsm bit,
                @process_date date

/*           
                DATE                     AUTHOR                              REMARKS
                2018-06-07				 rvinoche							 Initial creation
				2018-08-16				 rvinoche							 Add proxy data and return homogenous result set
*/
as

begin try

    declare @keycode varchar(50)
    declare @console_activity table (sum_active_last_30_day_devices_full int, sum_active_last_30_day_devices_trial int, proxy_sum_active_last_30_day_devices_full int, proxy_sum_active_last_30_day_devices_trial int, billing_day_of_month tinyint, license_id int, 
						keycode varchar(50), marnames varchar(100), parentkeycode varchar(50), active_last_30_day_devices int, licensetype varchar(50), license_category_name varchar(10), proxy_active_last_30_day_devices int)

    select @keycode = keycode
    from dbo.license
    where license_id = @license_id

    if @gsm = 1
    begin
                                
		insert into @console_activity (billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices)
		select lac.billing_day_of_month,
						l.license_id,
						scu.keycode,
						scu.marnames,
						scu.parentkeycode,
						isnull(scu.dbactivelast30days, 0),
						scu.licensetype,
						'SECA',
						sca.dbactivelast30days
		from DATAWAREHOUSEREADONLY.Feed.dbo.sky_seca_usage scu
		inner join dbo.license l
			ON l.keycode = scu.keycode
		left join license_autorenewal_cycle lac 
			ON lac.license_id = @license_id
		left join DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage sca
			on sca.license_id = l.license_id
		where scu.parentkeycode = @keycode
			and scu.log_date = (select max(scu2.log_date)
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_seca_usage scu2
								where scu.keycode = scu2.keycode 
									and scu2.log_date <= @process_date)
			and sca.effective_date = (select max(sca2.effective_date)
									from DATAWAREHOUSEREADONLY.feed.dbo.sky_console_usage sca2
									where sca2.license_id = sca.license_id
										AND sca2.effective_date <= @process_date)
		group by lac.billing_day_of_month,
										l.license_id,
										scu.keycode,
										scu.marnames,
										scu.parentkeycode,
										scu.dbactivelast30days,
										scu.licensetype,
										sca.dbactivelast30days

		;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_full from @console_activity where licensetype = 'full')
		update @console_activity
		set sum_active_last_30_day_devices_full = temp.sum_active_last_30_day_devices_full
		from temp

		;with temp as (select isnull(sum(active_last_30_day_devices), 0) as sum_active_last_30_day_devices_trial from @console_activity where licensetype = 'trial')
		update @console_activity
		set sum_active_last_30_day_devices_trial = temp.sum_active_last_30_day_devices_trial
		from temp

		;with temp as (select isnull(sum(proxy_active_last_30_day_devices),0) as proxy_sum_active_last_30_day_devices_full from @console_activity where licensetype = 'full')
		update @console_activity
		set proxy_sum_active_last_30_day_devices_full = temp.proxy_sum_active_last_30_day_devices_full
		from temp
								
		;with temp as (select isnull(sum(proxy_active_last_30_day_devices),0) as proxy_sum_active_last_30_day_devices_trial from @console_activity where licensetype = 'trial')
		update @console_activity
		set proxy_sum_active_last_30_day_devices_trial = temp.proxy_sum_active_last_30_day_devices_trial
		from temp

		select sum
_active_last_30_day_devices_full, sum_active_last_30_day_devices_trial, proxy_sum_active_last_30_day_devices_full, proxy_sum_active_last_30_day_devices_trial, billing_day_of_month, license_id, keycode, marnames, parentkeycode, active_last_30_day_devices, licensetype, license_category_name, proxy_active_last_30_day_devices
		from @console_activity

    end
    else
    begin

        select null, null, null, null, --sum fields for parent licenses
			lac.billing_day_of_month,
			l.license_id,
			scu.keycode,
			scu.marnames,
			scu.parentkeycode,
			scu.dbactivelast30days as active_last_30_day_devices,
			scu.licensetype,
			'SECA' license_category_name,
			sca.dbseenlast30days
        from DATAWAREHOUSEREADONLY.Feed.dbo.sky_seca_usage scu
		inner join dbo.license l
			on l.keycode = scu.keycode
        left join license_autorenewal_cycle lac 
			on lac.license_id = l.license_id
		left join DATAWAREHOUSEREADONLY.Feed.dbo.sky_console_usage sca
			on sca.license_id = l.license_id
        where l.license_id = @license_id
			and scu.log_date = (select max(scu2.log_date) 
								from DATAWAREHOUSEREADONLY.Feed.dbo.sky_seca_usage scu2
								where scu.keycode = scu2.keycode 
									and scu2.log_date <= @process_date)
			and sca.effective_date = (select max(sca2.effective_date)
									from DATAWAREHOUSEREADONLY.feed.dbo.sky_console_usage sca2
									where sca2.license_id = sca.license_id
										and sca2.effective_date <= @process_date)
    end

end try
begin catch

    declare @response_code int,
            @message varchar(100),
            @DBName nvarchar(128)

    set @response_code = -200
    set @message = case when @message is null then 'error processing usp_license_select_console_activity'
						else @message END
    set @DBName = db_name()

    exec usp_LogError @ErrorDB = @DBName

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_console_activity_wrapper]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_console_activity_wrapper]
    @license_id INT,
    @process_date DATE,
    @license_category_name VARCHAR(10),
    @opt_args VARCHAR(50) = ''

/*	
    DATE		AUTHOR		REMARKS
    2016-09-06	cnovac		Initial creation.
    2018-06-19	rvinoche	Adding usage for SECA and SDNS
    2018-08-16	rvinoche	Add proxy data and simplify 
    2019-05-10	cnovac		Updated logic for sum_active_last_30_day_devices_full and sum_active_last_30_day_devices_trial
    2019-02-26	rvinoche	Refactor to use activity function
    2019-05-13	cnovac		Took out update to calc active_last_30_day_devices since it's now done in fn_license_select_license_activity_sites
    2019-07-08	rvinoche	Switch dns_ip_requests to dns_ip_calculated field from sites function
    2019-09-24	abelenkiy	LAGER-1091/IAMROOT-591 - Changed sum_active_last_30_day_devices_full and sum_active_last_30_day_devices_trial calculations to be product-specific
    2019-12-19	cnovac		Updated to populate marnames column from fn_license_select_license_activity_sites()
    2020-10-01	cnovac		Revamped whole procedure and now return JSON back to PHP on activity tab in CSI
    2020-07-30	psatish		Added an index on the table:license_external_reference_vault to optimize the procedure and added if condition to avoid checking for empty records(Ticket# 3613642)
    2021-09-19  g.lagos     Include VAULT information OTSF and CEBP section SMCI-4856, resolving merge-conflict
    2025-09-24	pachanta	Usage for EDR/MDR are not showing in CSI. IM-4985490
    2025-12-03	gblandford	US-5110076 - https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5110076
                            - include usage information for CRSB products
                            - TRANSACTION ISOLATION LEVEL added
                            - formatting and casing changes
                            - added schemas
                            - Use of EXISTS instead of COUNT(*) >
                            - Removed unecessary duplication of @json assignment/RETURN statement and execute at end of logic
                            - added @opt_args for debugging purposes
    2026-03-12  psatish		US-5276743 Added a status column in the Child JSON section
                            Updated the Activity Full and Activity Trial fields to display usage data for active keycodes.
                            Optimized the stored procedure by refactoring logic and implementing a table variable for Pillr categories.
	2026-04-21  psatish		US-5304849 Refactored logic by moving the usp_license_select_console_activity_headers procedure logic into the wrapper procedure,
							eliminating separate PHP calls to header and wrapper procedures for displaying Activity tab data.
	2026-06-05  psatish		D-5455795 Removed the logic that calculates usage based on active keycodes for the Activity Full and Trial fields,
							as the fn_license_select_license_activity_sites function already handles deactivated sites correctly.
	2026-05-14  psatish		US-5401639 Update the datatype of cbepcapacity from INT to Decimal in the @activity_table table

    DESCRIPTION
    Calls [fn_license_select_license_activity_sites] and returns encoded JSON containing
    usage info for child keys on license/category. Called by Usage Portal (usage summary
    and site usage summary), Partner Cart (license view page), API (partner service call),
    CSI (activity tab on license view page).

*/
AS
SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;


BEGIN TRY

    DECLARE @json NVARCHAR(MAX),
            @activity_json NVARCHAR(MAX),
			@header_json NVARCHAR(max)

    DECLARE @license_category_details TABLE
 
   (
        parent_keycode VARCHAR(50),
        license_type_id INT,
        license_category_name VARCHAR(10),
        category_type_name VARCHAR(20),
        expiration_date DATE,
        billing_day_of_month INT,
        billing_model INT,
        seats INT
    );
    DECLARE @activity_table TABLE
    (
        license_id INT,
        license_category_name VARCHAR(10),
        marname NVARCHAR(1000),
        category_type_name VARCHAR(20),
        console_activity INT,
        dns_ip_requests_calculated INT,
        dns_ip_requests INT,
        dns_agent_requests INT,
        office365assigneduserseatshigh INT,
        office365capacityhigh INT,
        cbepsubscribeddevices INT,
        cbepcapacity  DECIMAL(18, 2),
        active_devices INT,
        vault VARCHAR(MAX),
        keycode VARCHAR(40),
        license_status_id INT,
        status VARCHAR(20),
        effective_date DATE
    );
    DECLARE @CRSB_LICENSE_CATEGORIES TABLE
    (
        license_category_name VARCHAR(10)
    );
    DECLARE @PILLR_LICENSE_CATEGORIES TABLE
    (
        license_category_name VARCHAR(20)
    );

    INSERT INTO @CRSB_LICENSE_CATEGORIES
    (
        license_category_name
    )
    SELECT f.[key]
    FROM dbo.fn_app_config_select_key_values('CRSB_LICENSE_CATEGORIES', 'CRSB') f;

    /*	Retrieve Pillr categories	*/
    INSERT INTO @PILLR_LICENSE_CATEGORIES
    (
        license_category_name
    )
    SELECT f.[key]
    FROM dbo.fn_app_config_select_key_values('PILLR_LICENSE_CATEGORIES', 'PILLR') f;
	
    IF @opt_args LIKE '%debug%'
    BEGIN
        SELECT f.[key]
        FROM dbo.fn_app_config_select_key_values('CRSB_LICENSE_CATEGORIES', 'CRSB') f;

        SELECT 1
        FROM @CRSB_LICENSE_CATEGORIES
        WHERE license_category_name = @license_category_name;
    END;

    INSERT INTO @license_category_details
    (
        parent_keycode,
        license_type_id,
        license_category_name,
        category_type_name,
        expiration_date,
        billing_day_of_month,
        billing_model,
        seats
    )
    SELECT l.keycode,
           l.license_type_id,
           lp.license_category_name,
           lp.category_type_name,
           lp.expiration_date,
           dbo.fn_license_select_effective_object_element(
                                                             lp.license_id,
                                                             lp.license_category_id,
                                                             'billing_day_of_month',
                                                             @process_date
                                                         ),
           dbo.fn_license_select_effective_object_element(
                                                             lp.license_id,
                                                             lp.license_category_id,
                                                             'license_attribute_license_value',
                                                             @process_date
                                                         ),
           dbo.fn_license_select_effective_object_element(
                                                             lp.license_id,
                                                             lp.license_category_id,
                                                             'license_seats',
                                                             @process_date
                                                         )
    FROM dbo.license l
        CROSS APPLY dbo.fn_license_select_license_profile(l.license_id) lp
    WHERE l.license_id = @license_id
          AND lp.license_category_name = @license_category_name;

	SELECT @header_json =
	(
		SELECT lc.license_category_name,
			   lch.column_name ,
			   lch.column_header 
		FROM dbo.license_category_activity_headers lch

			JOIN dbo.license_category lc
				ON lch.license_category_id = lc.license_category_id
		WHERE lc.license_category_name = @license_category_name
		FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
	);



    IF EXISTS (SELECT 1 FROM @license_category_details)
    BEGIN
        INSERT INTO @activity_table
        (
            license_id,
            license_category_name,
            marname,
            category_type_name,
            console_activity,
            dns_ip_requests_calculated,
            dns_ip_requests,
            dns_agent_requests,
            office365assigneduserseatshigh,
            office365capacityhigh,
            cbepsubscribeddevices,
            cbepcapacity,
            active_devices,
            vault,
            keycode,
            license_status_id,
            status
        )
        SELECT fn.license_id,
               fn.license_category_name,
               fn.marname,
               ct.capability_type_description,
               fn.console_activity,
               fn.dns_ip_requests_calculated,
               fn.dns_ip_requests,
               fn.dns_agent_requests,
               fn.office365assigneduserseatshigh,
               fn.office365capacityhigh,
               fn.cbepsubscribeddevices,
               fn.cbepcapacity,
               fn.active_devices,
               fn.otsfcbep_vault,
               lc.keycode,
               ls.license_status_id,
               ls.license_status_description
        FROM dbo.fn_license_select_license_activity_sites(@license_id, @process_date, @license_category_name) fn
            INNER JOIN dbo.capability_type ct
                ON ct.capability_type_id = fn.capability_type_id
            INNER JOIN dbo.license lc
                ON lc.license_id = fn.license_id
            INNER JOIN dbo.license_status ls
                ON ls.license_status_id = lc.license_status_id;



        IF @license_category_name = 'SAEP'
        BEGIN
            SELECT @json =
            (
                SELECT
            (
                SELECT at.keycode,
                       at.marname,
                       at.console_activity,
                       at.category_type_name,
                       at.status
                FROM @activity_table at
                FOR JSON PATH
            )       Child
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );

        END;
        ELSE IF @license_category_name = 'SDNS'
        BEGIN

            SELECT @json =
            (
                SELECT
            (
                SELECT at.keycode,
                       at.marname,
                       at.console_activity,
                       at.category_type_name,
                       at.dns_ip_requests_calculated,
                       at.dns_ip_requests,
                       at.dns_agent_requests,
                       at.status
                FROM @activity_table at
                FOR JSON PATH
            )       Child
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );

        END;
        ELSE IF @license_category_name = 'SECA'
                OR EXISTS
             (
                 SELECT 1
                 FROM
                 (
                     SELECT license_category_name
                     FROM @CRSB_LICENSE_CATEGORIES
                     UNION
                     SELECT license_category_name
                     FROM @PILLR_LICENSE_CATEGORIES
                 ) lc
                 WHERE lc.license_category_name = @license_category_name
             )
        BEGIN -- OpenText Server Backup

            IF @opt_args LIKE '%debug%'
            BEGIN
                SELECT 'CRSB' AS step_name;
            END;



            SELECT @json =
            (
                SELECT
            (
                SELECT at.keycode,
                       at.marname,
                       at.
console_activity,
                       at.category_type_name,
                       at.active_devices,
                       at.status
                FROM @activity_table at
                FOR JSON PATH
            )       Child
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );
        END;

        ELSE IF @license_category_name = 'OTSF'
        BEGIN


            SELECT @json =
            (
                SELECT
            (
                SELECT at.keycode,
                       at.marname,
                       /*lcd.parent_keycode, */
                       /*lcd.license_category_name,*/
                       at.console_activity,
                       at.category_type_name,
                       at.office365assigneduserseatshigh,
                       at.office365capacityhigh,
                       at.vault,
                       at.status
                FROM @activity_table at
                    INNER JOIN license l
                        ON l.license_id = at.license_id
                FOR JSON PATH
            )       Child
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );

        END;
        ELSE IF @license_category_name = 'CBEP'
        BEGIN

            SELECT @json =
            (
                SELECT
            (
                SELECT at.keycode,
                       at.marname,
                       /* lcd.parent_keycode, */
                       /*lcd.license_category_name,*/
                       at.console_activity,
                       at.category_type_name,
                       at.cbepsubscribeddevices,
                       at.cbepcapacity,
                       at.vault,
                       at.status
                FROM @activity_table at
                FOR JSON PATH
            )       Child
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );

        END;

        SELECT @activity_json =
               (
                   SELECT lcd.license_category_name,
                          lcd.expiration_date,
                          lcd.category_type_name,
                          lav.license_attribute_license_value_description,
                          lcd.billing_day_of_month,
                          (
                              SELECT SUM(console_activity)
                              FROM @activity_table
                              WHERE category_type_name = 'full'                                    
                          ) AS 'Activity Full',
                          (
                              SELECT SUM(console_activity)
                              FROM @activity_table
                              WHERE category_type_name = 'trial'                                   
                          ) AS 'Activity Trial'
                   FROM @license_category_details lcd
                       LEFT JOIN license_attribute_license_value lav
                           ON lcd.billing_model = lav.license_attribute_license_value
                   WHERE lcd.license_category_name = @license_category_name
                   FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
               );

        SELECT @json = JSON_MODIFY(@activity_json, '$.Child', JSON_QUERY(@json, '$.Child'));

		SELECT @header_json AS license_category_activity_headers,@json AS usage
     

        RETURN 1;



    END;
    ELSE
    BEGIN

		SELECT @header_json AS license_category_activity_headers,@json AS usage
		
        RETURN;
    END;

END TRY
BEGIN CATCH

    DECLARE @response_code INT,
            @message VARCHAR(100),
            @dbname NVARCHAR(128);

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'error processing usp_license_select_console_activity_wrapper'
                       ELSE
                           @message
      
             END;
    SET @dbname = DB_NAME();

    EXEC usp_LogError @ErrorDB = @dbname;

END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_credit_card_subscription]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_credit_card_subscription]
(
	@keycode VARCHAR(40)
)

/*    
    DATE        AUTHOR      REMARKS
    2019-03-20  jnavarra    Initial creation
    2019-05-13  jnavarra    Implement Grayson's changes improving subscription selection and returned data
                            Slightly modified to remove expired credit cards and invalid data

    DESCRIPTION
    Retrieve a customer's credit card subscription details to simplify their customer service experience

*/

AS
	SET NOCOUNT ON
	DECLARE
    	@response_code INT,
        @message VARCHAR(100)
    BEGIN TRY
		SELECT TOP(1)
			oph.payment_header_id,
			l.license_id,
			l.keycode,
			pscc.credit_card_subscription_id,
			pa.account_number,
			CONCAT(pa.expiration_month, '/', pa.expiration_year) AS credit_card_expiration,
			ct.card_type_description,
			c.first_name,
			c.last_name,
			ca.address_1,
			ca.address_2,
			ca.city,
			state.state_iso3 as state,
			ca.postal_code,
			ce.customer_email,
			country.description as country_description
		FROM dbo.order_item_license oil
			INNER JOIN dbo.license l
                ON oil.license_id = l.license_id
			INNER JOIN dbo.order_item oi
                ON oil.order_item_id = oi.order_item_id
			INNER JOIN dbo.order_header oh
                ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.customer_order co
                ON oh.order_header_id = co.order_header_id AND co.customer_type_id = 1  -- billing
			INNER JOIN dbo.customer_order_address coa
                ON oh.order_header_id = coa.order_header_id
			INNER JOIN dbo.customer c
                ON co.customer_id = c.customer_id
			INNER JOIN dbo.customer_address ca
                ON coa.customer_address_id = ca.customer_address_id AND ca.address_status_id = 1
			INNER JOIN dbo.customer_email ce
                ON co.customer_id = ce.customer_id AND ce.email_status_id = 1
			INNER JOIN dbo.lu_countries country
                ON ca.country_id = country.country_id
			INNER JOIN dbo.lu_states state
                ON ca.state = state.state_id
			INNER JOIN dbo.order_payment_header oph
                ON oh.order_header_id = oph.order_header_id
			INNER JOIN dbo.payment_account pa
                ON oph.payment_header_id = pa.payment_header_id
			INNER JOIN dbo.payment_subscription_credit_card pscc
                ON oph.payment_header_id = pscc.payment_header_id AND pscc.credit_card_subscription_id IS NOT NULL
			INNER JOIN dbo.card_type ct
                ON pa.card_type_id = ct.card_type_id
		WHERE l.keycode = @keycode
            AND (pa.expiration_year > DATEPART(year, GETDATE())
                OR (pa.expiration_year = DATEPART(year, GETDATE())
                    AND pa.expiration_month >= DATEPART(month, GETDATE())))
		ORDER BY oi.effective_date DESC,
            oh.order_header_id DESC
    END TRY
    
    BEGIN CATCH
        SET @response_code = -200
        SET @message = CASE
                WHEN @message IS NULL THEN 'select credit card subscription failed'
                ELSE @message
            END
        DECLARE @DBName NVARCHAR(128)
        SET @DBName = DB_NAME()
        EXEC usp_LogError @ErrorDB = @DBName
    END CATCH;

GO
