-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_effective_object_table]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_effective_object_table]


(
	@license_id int,
	@effective_start_date date = null,
	@object_element_name varchar(50) = null,
	@license_category_name varchar(10) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-11-07	esmart		Initial creation.

	DESCRIPTION
	select effective object data
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @effective_start_date
		if @effective_start_date is null begin select @effective_start_date = getdate() end

		-- 1.2) return results
		select f.license_effective_object_id, f.license_id, f.license_category_id, lc.license_category_name, f.effective_object_id, f.object_element_name, 
			case when v.effective_object_value_name is null then convert(varchar(100),f.effective_value) else v.effective_object_value_name end as object_element_value, f.effective_start_date, f.effective_end_date
		from fn_license_select_effective_object_table(@license_id,@effective_start_date) f
		inner join license_category lc
			on f.license_category_id = lc.license_category_id
		left join effective_object_value v
			on f.effective_object_id = v.effective_object_id and f.effective_value = v.effective_value 
		where f.object_element_name = case when @object_element_name is not null then @object_element_name else f.object_element_name end and
				lc.license_category_name = case when @license_category_name is not null then @license_category_name else lc.license_category_name end
		order by f.effective_object_id, lc.license_category_name


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_entity_dates]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_entity_dates]

(
       @license_id int
)

/*     
       DATE                 AUTHOR               REMARKS
       2018-10-16           rvinoche             Initial creation
	   2019-06-11			rvinoche			 Default to today for annual license with expired contract
	   2019-07-12			rvinoche			 Allow same day approval as billing day
	   2020-01-18			g.lagos				 Story 2448, there's going to be only one date presented Billing Entity: 
       2021-12-09			psatish				 Added Perpetual billing model id to get the next usage date
       DESCRIPTION
       select list of appropriate dates based on the current billing model and contract
*/

AS
     
	set nocount on                    

	declare		@license_attribute_license_value int,
				@effective_date date = getdate(),
				@contract_end_date date,
				@contract_site_id varchar(65),
				@next_usage_process_date datetime,
				@license_expiration_date date,
				@license_category_id tinyint,
				@billing_day_of_month tinyint,
				@response_code int,
				@count_dates INT,
				@message varchar(100)

	declare @dates table (row_id int identity(1,1),effective_date datetime)
	


	select @license_expiration_date = c.capability_expiration_date, @license_category_id = lc.license_category_id
	from dbo.license_category_license lcl
	inner join dbo.license_category lc
		on lc.license_category_id = lcl.license_category_id
	inner join dbo.license_capability c
		on c.license_id = lcl.license_id and c.capability_id = lc.base_capability_id
	where lcl.license_id = @license_id

	-- 1.) Expired licenses

	if @license_expiration_date < @effective_date
	begin 
		insert into @dates (effective_date) values(@effective_date)

		goto results
	end
		
	select  @license_attribute_license_value = dbo.fn_license_select_effective_object_element(@license_id, @license_category_id,'license_attribute_license_value',@effective_date)

	-- 2.) Annual licenses

	if @license_attribute_license_value in (120,220,20,11) or @license_attribute_license_value is null -- annual billing models should be expired no sooner than 3 months prior to end of contract
	begin	
		select top (1) @contract_end_date = oi.capability_expiration_date,
			@contract_site_id = oh.site_id
		from dbo.order_item_license oil
		inner join dbo.order_item oi
			on oi.order_item_id = oil.order_item_id
		inner join dbo.product_license_category plc
			on plc.product_id = oi.product_id
		inner join dbo.product p
			on p.product_id = oi.product_id
		inner join dbo.order_header oh
			on oh.order_header_id = oi.order_header_id
		left join dbo.partner_license pl
			on pl.order_header_id = oi.order_header_id
			and pl.partner_license_status_id = 1
		where plc.license_category_id = @license_category_id 
			and p.product_type_id in (1,2)
			and pl.partner_license_id is null
            and oi.capability_expiration_date >= @effective_date
			and oil.license_id = @license_id
        order by oi.order_item_id DESC
        
		select @billing_day_of_month = dbo.fn_license_select_effective_object_element(@license_id, @license_category_id,'billing_day_of_month', @contract_end_date)

		if @contract_site_id = 'sfdc' and day(@contract_end_date) <> @billing_day_of_month
			select @contract_end_date = dateadd(dd,1,@contract_end_date) --because sfdc substracts a day from the contract compared to ecom

		if @license_attribute_license_value in (120,220) and @contract_end_date is not null --direct contracts have a 3 month grace period from their expiration date (per sales), annual partner contracts have no grace periods
			insert @dates (effective_date) values (@contract_end_date)
		
		else if @contract_end_date is not null
			insert @dates (effective_d
ate) values (@contract_end_date), (dateadd(mm,-1,@contract_end_date)), (dateadd(mm,-2,@contract_end_date)), (dateadd(mm,-3,@contract_end_date))
		
        else
			insert into @dates (effective_date) values (@effective_date)

        SELECT @count_dates = (SELECT COUNT(*) FROM @dates)

		goto results
	end
    
	-- 3.) Monthly licenses
        
	else if @license_attribute_license_value in (12,110,111,112,210,211,212,13,113,213) -- monthly billing models can be expired as soon as the next usage check date
	begin	
		
		select @next_usage_process_date = process_date
		from dbo.license_message
		where message_status_id = 3
			and message_type_id = 10
			and cast(process_date as date) = @effective_date
			and license_id = @license_id

		select @next_usage_process_date = isnull(@next_usage_process_date, process_date) 
		from dbo.license_message 
		where message_status_id = 1
			and license_id = @license_id
			and message_type_id = 10
			--and process_date >= @effective_date
		

		insert @dates (effective_date)
		values (@next_usage_process_date), (dateadd(mm,1,@next_usage_process_date)), (dateadd(mm,2,@next_usage_process_date))


        SELECT @count_dates = (SELECT COUNT(*) FROM @dates)

		goto results
    end
    
	else 
	begin	
		insert into @dates(effective_date)values(@license_expiration_date)

		goto results
	end
    
	-- 4.) Return results
    
	results:

-- Original code	delete from @dates where effective_date < @effective_date

	IF @count_dates > 1 and @license_attribute_license_value in (20,11)  -- Story lager-2448
		begin
				
			delete from @dates where effective_date < (select MAX(effective_date ) FROM @dates)
		end
	ELSE
		BEGIN
        
			delete from @dates where effective_date < @effective_date 
		end


	select row_id, effective_date from @dates



GO
