CREATE PROCEDURE [dbo].[usp_license_select_external_reference]
	@license_id int,
	@license_category_id tinyint = null,
	@effective_object_id tinyint = null

/*	
	DATE		AUTHOR		REMARKS
	2019-11-08	cnovac		Initial creation.
	2020-04-30	cnovac		Took out call to query from effective object
	2020-10-21	wbarton		Adding license_external_reference_vault_id to the select
	2020-02-02	wbarton		Adding license_external_reference_vault_id default to the fn_license_select_external_reference call

*/
as

set nocount on

begin try

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- select data from fn_license_select_external_reference
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	select license_id,
           license_category_id,
           effective_object_id,
           object_element_name,
           external_reference_value,
		   license_external_reference_vault_id
