-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_license]
(
    @keycode VARCHAR(40) = NULL,
    @license_key VARCHAR(36) = NULL
)
AS

/*	
	DATE			AUTHOR		REMARKS
	2006-07-24		esmart		Initial creation
	2006-09-04		esmart		Added column license_keycode_type_id. Modified @keycode to varchar(40) from char(20)
	2006-09-13		esmart		Add column root_product_id from product_line
	2007-03-13		esmart		Add parent_license_id for child licenses, and license_seat columns
	2008-07-16		esmart		Add license_storage 
	2011-08-05		esmart		Account lookup
	2011-11-07		esmart		Keycode alias
	2013-06-20		esmart		Add join to license_keycode_alias
	2014-09-02		esmart		oem_type
	2016-01-11		acoffel		S2 Flag
	2016-06-10		esmart		license migration
	2016-09-15		esmart		salesforce_license_id
	2017-03-22		esmart		change lookup of license_key to license_key table
	2019-01-09		rvinoche	Support autobilling attributes living only in license_effective_object
	2024-03-05		cibach		Add customer GUID to return (safe_account_user_guid)
	2024-04-23		singaravelam	ECOM-2749 added column portal_flag to return license belongs to portal
	2026-03-25		pachanta	US-5117514 Added Consumed License seats for consumer.

	DESCRIPTION
	select license details

	DEPENDENCIES
	Called from the PHP
*/

SET NOCOUNT ON

DECLARE @response_code INT,
        @message VARCHAR(100)

BEGIN TRY

    DECLARE @license_id INT,
            @keycode_alias VARCHAR(40),
            @account_id INT,
            @account_user_name VARCHAR(100),
            @license_attribute_id INT,
            @license_attribute_description VARCHAR(100),
            @license_attribute_tag VARCHAR(20),
            @license_attribute_license_value INT,
            @license_attribute_license_value_description VARCHAR(50),
            @license_attribute_last_modified DATETIME,
            -- @license_key varchar(36),
            @parent_license_id INT,
            @parent_keycode VARCHAR(40),
            @parent_salesforce_license_id VARCHAR(18),
            @license_category_id TINYINT,
            @license_category_name VARCHAR(10),
            @license_category_description VARCHAR(50),
            @license_migration VARCHAR(10),
            @start_date DATETIME,
            @end_date DATETIME,
            @oem_type VARCHAR(50),
            @salesforce_license_id VARCHAR(18),
            @capability_type_id INT,
            @capability_type_description VARCHAR(20),
            @customer_guid VARCHAR(36)

    DECLARE @PORTAL_DISTRIBUTION_METHOD TABLE
    (
        portal_distribution_method_code VARCHAR(4)
    )

    --0.0) Portal distribution methods
    INSERT INTO @PORTAL_DISTRIBUTION_METHOD
    (
        portal_distribution_method_code
    )
    SELECT f.[key]
    FROM [dbo].[fn_app_config_select_key_values]('PORTAL_DISTI_CODES', 'PORTAL') f

    -- 1.0) @keycode
    IF @keycode IS NULL
    BEGIN
        SELECT @keycode = l.keycode
        FROM license_key k
            INNER JOIN license l
                ON l.license_id = k.license_id
        WHERE k.license_key = @license_key
    END

    -- 1.0) @license_id
    SELECT @license_id = license_id
    FROM license
    WHERE keycode = @keycode

    IF @license_id IS NULL
    BEGIN
        SELECT @license_id = license_id,
               @keycode_alias = keycode_alias
        FROM license_keycode_alias
        WHERE keycode_alias = @keycode
    END

    -- 1.1) select account_id
    SELECT @account_id = a.account_id,
           @account_user_name = a.account_user_name
    FROM account_license al
        INNER JOIN account a
            ON al.account_id = a.account_id
               AND a.account_type_id = 1
               AND a.account_status_id <> 2
    WHERE al
.license_id = @license_id

    -- 1.2) check account_device
    IF @account_id IS NULL
    BEGIN
        SELECT @account_id = account_id,
               @account_user_name = account_user_name
        FROM account
        WHERE account_id IN
              (
                  SELECT account_id FROM account_device WHERE license_id = @license_id
              )
    END

    -- 1.3) select license_key
    IF
    (
        SELECT COUNT(*)FROM license_key WHERE license_id = @license_id
    ) = 0
    AND @license_id IS NOT NULL
    BEGIN
        INSERT INTO license_key
        (
            license_id
        )
        VALUES
        (@license_id)
    END

    SELECT @license_key = CONVERT(VARCHAR(36), lk.license_key),
           @salesforce_license_id = lk.salesforce_license_id
    FROM license_key lk WITH (NOLOCK)
    WHERE license_id = @license_id

    -- 1.4) license_attribute_license
    SELECT @license_attribute_id = la.license_attribute_id,
           @license_attribute_description = la.license_attribute_description,
           @license_attribute_tag = la.license_attribute_tag,
           @license_attribute_license_value = v.license_attribute_license_value,
           @license_attribute_license_value_description = v.license_attribute_license_value_description,
           @license_attribute_last_modified = f.effective_start_date
    FROM dbo.fn_license_select_effective_object_table(@license_id, GETDATE()) f
        INNER JOIN dbo.license_category_license lcl
            ON lcl.license_id = f.license_id
        LEFT JOIN license_attribute_license_value v WITH (NOLOCK)
            ON f.effective_value = v.license_attribute_license_value
        LEFT JOIN license_attribute la WITH (NOLOCK)
            ON v.license_attribute_id = la.license_attribute_id
    WHERE f.license_category_id = lcl.license_category_id --endpoint only for now
          AND f.effective_object_id = 2 --autobilling attribute

    IF @license_attribute_license_value IS NULL --meaning the license does not have an autobilling attribute, so we'll check for ar
    BEGIN
        SELECT @license_attribute_id = lal.license_attribute_id,
               @license_attribute_description = la.license_attribute_description,
               @license_attribute_tag = la.license_attribute_tag,
               @license_attribute_license_value = v.license_attribute_license_value,
               @license_attribute_license_value_description = v.license_attribute_license_value_description,
               @license_attribute_last_modified = lal.modified_date
        FROM license_attribute_license lal WITH (NOLOCK)
            LEFT JOIN license_attribute la WITH (NOLOCK)
                ON lal.license_attribute_id = la.license_attribute_id
            LEFT JOIN license_attribute_license_value v WITH (NOLOCK)
                ON lal.license_attribute_license_value = v.license_attribute_license_value
        WHERE lal.license_id = @license_id
    END

    -- 1.5) select license_parent
    SELECT @parent_license_id = l2.license_id,
           @parent_keycode = l2.keycode,
           @parent_salesforce_license_id = k.salesforce_license_id
    FROM license_parent lp WITH (NOLOCK)
        INNER JOIN license l2 WITH (NOLOCK)
            ON lp.parent_license_id = l2.license_id
        INNER JOIN license_key k WITH (NOLOCK)
            ON l2.license_id = k.license_id
    WHERE lp.child_license_id = @license_id

    -- 1.6) select license_category
    SELECT @license_category_id = c.license_category_id,
           @license_category_name = c.license_category_name,
           @license_category_description = c.license_category_description,
           @start_date = lc.start_date,
           @end_date = lc.end_date,
           @capability_type_id = cp.capability_type_id,
           @capability_type_description = ct.capability_type_description
    FROM license_category_license lc WITH (NOLOCK)
        INNER JOIN license_
category c WITH (NOLOCK)
            ON lc.license_category_id = c.license_category_id
        INNER JOIN license_capability cp
            ON cp.license_id = lc.license_id
               AND cp.capability_id = c.base_capability_id
        INNER JOIN capability_type ct
            ON ct.capability_type_id = cp.capability_type_id
    WHERE lc.license_id = @license_id

    -- 1.3) @oem_type
    SELECT @oem_type = CASE
                           WHEN license_feature_license_id IS NULL THEN
                               NULL
                           ELSE
                               'Fixed expiration'
                       END
    FROM license_feature_license
    WHERE license_id = @license_id
          AND license_feature_id = 8

    -- 1.8) @license_migration_keycode
    SELECT @license_migration = CASE
                                    WHEN COUNT(*) > 0 THEN
                                        'Yes'
                                    ELSE
                                        'No'
                                END
    FROM license_migration m
    WHERE m.original_license_id = @license_id
          OR m.new_license_id = @license_id

    -- 1.9) @customer_GUID
    SELECT @customer_guid = sauc.safe_account_user_guid
    FROM dbo.safe_account_user_customer sauc
        INNER JOIN dbo.license l
            ON l.customer_id = sauc.customer_id
    WHERE l.license_id = @license_id

    -- 1.10) select license
    SELECT l.license_id,
           l.keycode,
           keycode_alias = a.keycode_alias,
           l.customer_id,
           p.product_line_id,
           p.product_line_description,
           p.root_product_id,
           st.license_status_id,
           st.license_status_description,
           t.license_type_id,
           t.license_type_description,
           capability_type_id = @capability_type_id,
           capability_type_description = @capability_type_description,
           l.license_distribution_method_id,
           l.license_keycode_type_id,
           l.max_daily_activations,
           l.max_child_licenses,
           l.license_expiration_date,
           l.insert_date,
           l.insert_by,
           l.modified_date,
           l.modified_by,
           parent_license_id = @parent_license_id,
           parent_keycode = @parent_keycode,
           parent_salesforce_license_id = @parent_salesforce_license_id,
           s.license_seats,
		   las.consumed_seats,
           seats_used = 0,
           ls.storage_gb,
           license_category_id = @license_category_id,
           license_category_name = @license_category_name,
           license_category_description = @license_category_description,
           start_date = @start_date,
           end_date = @end_date,
           account_id = @account_id,
           account_user_name = @account_user_name,
           license_key = @license_key,
           salesforce_license_id = @salesforce_license_id,
           license_attribute_id = @license_attribute_id,
           license_attribute_description = @license_attribute_description,
           license_attribute_tag = @license_attribute_tag,
           license_attribute_license_value = @license_attribute_license_value,
           license_attribute_license_value_description = @license_attribute_license_value_description,
           license_attribute_last_modified = @license_attribute_last_modified,
           oem_type = @oem_type,
           license_migration = @license_migration,
           bestbuy_flag = CASE
                              WHEN su.license_distribution_method_id IS NOT NULL THEN
                                  1
                              ELSE
                                  0
                          END,
           autorenewal_status = CASE
                                    WHEN lal.license_attribute_license_value = 1 THEN
                                        1
             
                       ELSE
                                        0
                                END,
           autorenewal_status_description = lalv.license_attribute_license_value_description,
           user_guid = @customer_guid,
           portal_flag = CASE
                             WHEN pdm.portal_distribution_method_code IS NOT NULL THEN
                                 1
                             ELSE
                                 0
                         END
    FROM license l WITH (NOLOCK)
        INNER JOIN product_line p WITH (NOLOCK)
            ON p.product_line_id = CASE
                                       WHEN @license_category_id IN ( 100, 110, 115, 120 )
                                            AND l.product_line_id = 1 THEN
                                           100
                                       WHEN @license_category_id IN ( 100, 110, 115, 120 )
                                            AND l.product_line_id = 6 THEN
                                           200
                                       ELSE
                                           l.product_line_id
                                   END
        INNER JOIN license_type t WITH (NOLOCK)
            ON l.license_type_id = t.license_type_id
        INNER JOIN license_status st WITH (NOLOCK)
            ON l.license_status_id = st.license_status_id
        LEFT JOIN dbo.license_distribution_method AS ldm
            ON l.license_distribution_method_id = ldm.license_distribution_method_id
        LEFT JOIN @PORTAL_DISTRIBUTION_METHOD AS pdm
            ON ldm.license_distribution_method_code = pdm.portal_distribution_method_code
        LEFT JOIN license_seat s WITH (NOLOCK)
            ON l.license_id = s.license_id
		LEFT JOIN license_active_seats las WITH (NOLOCK)
            ON l.license_id = las.license_id
        LEFT JOIN license_storage ls WITH (NOLOCK)
            ON l.license_id = ls.license_id
        LEFT JOIN license_keycode_alias a WITH (NOLOCK)
            ON l.license_id = a.license_id
        LEFT JOIN subscription_distribution_method su
            ON l.license_distribution_method_id = su.license_distribution_method_id
        LEFT JOIN dbo.license_attribute_license lal
            ON lal.license_id = l.license_id
        LEFT JOIN dbo.license_attribute_license_value lalv
            ON lalv.license_attribute_license_value = lal.license_attribute_license_value
    WHERE l.license_id = @license_id

END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC usp_LogError @ErrorDB = @DBName

END CATCH;










GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_activity]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_activity]

(
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2016-01-06	esmart		Limit result to 100

	DESCRIPTION
	Insert opportunity
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_activity table (license_activity_id int,mjv smallint,version varchar(10),grabword varchar(30),rc int,operating_system smallint,platform int,language_code varchar(2),location_code varchar(3),device_mid varchar(40),instance_mid varchar(64),threats_removed int,current_threats smallint,number_scans int,average_scan_time int,number_events bigint,bytes_cleaned bigint,time_protected bigint,first_activity_date datetime,last_activity_date datetime,max_activity_id bigint,total_checks int,max_threats_removed int,max_current_threats smallint,hostname varchar(64),sa_score tinyint,sa_software_status char(1),sa_hardware_status char(1),sa_threat_status char(1))
	
	insert into @license_activity(license_activity_id,mjv,version,grabword,rc,operating_system,platform,language_code,location_code,device_mid,instance_mid,threats_removed,current_threats,number_scans,average_scan_time,number_events,bytes_cleaned,time_protected,first_activity_date,last_activity_date,max_activity_id,total_checks,max_threats_removed,max_current_threats,hostname,sa_score,sa_software_status,sa_hardware_status,sa_threat_status)
	select license_activity_id, 
			mjv, 
			version, 
			grabword, 
			rc, 
			operating_system, 
			platform, 
			language_code, 
			location_code, 
			device_mid, 
			instance_mid, 
			threats_removed, 
			current_threats, 
			number_scans, 
			average_scan_time = average_scan_time/1000, -- seconds
			number_events, 
			bytes_cleaned = bytes_cleaned/1000000, -- MB 
			time_protected, 
			first_activity_date, 
			last_activity_date,
			max_activity_id, 
			total_checks, 
			max_threats_removed, 
			max_current_threats, 
			hostname, 
			sa_score, 
			sa_software_status, 
			sa_hardware_status, 
			sa_threat_status
	from license_activity
	where license_id = @license_id

	if (select count(*) from @license_activity) < 100 
		begin
			select license_activity_id,mjv, version, grabword, rc, operating_system, platform, language_code, location_code, device_mid, instance_mid, threats_removed, current_threats, number_scans, average_scan_time,number_events, bytes_cleaned, time_protected, first_activity_date, last_activity_date,max_activity_id, total_checks, max_threats_removed, max_current_threats, hostname, sa_score, sa_software_status, sa_hardware_status, sa_threat_status
			from @license_activity
		end
	else
		begin
			select license_activity_id,mjv, version, grabword, rc, operating_system, platform, language_code, location_code, device_mid, instance_mid, threats_removed, current_threats, number_scans, average_scan_time,number_events, bytes_cleaned, time_protected, first_activity_date, last_activity_date,max_activity_id, total_checks, max_threats_removed, max_current_threats, hostname, sa_score, sa_software_status, sa_hardware_status, sa_threat_status
			from @license_activity
			where license_activity_id = 0
		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName
 = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
