CREATE PROCEDURE [dbo].[usp_license_select_license_attribute]

(
	@license_attribute_id int = null
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-11-13	esmart		Initial creation
	
	DESCRIPTION
	select license attribute
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select license_attribute_id, license_attribute_description, license_attribute_tag, license_attribute_default_value, insert_date, insert_by, modified_date, modified_by
	from license_attribute a
	where a.license_attribute_id = case when @license_attribute_id is null then a.license_attribute_id else @license_attribute_id end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
