CREATE PROCEDURE [dbo].[usp_license_select_license_attribute_license_value]

(
	@license_attribute_id int,
	@license_attribute_license_value int = null
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-11-13	esmart		Initial creation
	
	DESCRIPTION
	select license attribute
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select license_attribute_license_value, license_attribute_id, license_attribute_license_value_description
	from license_attribute_license_value v
	where v.license_attribute_id = @license_attribute_id and 
		v.license_attribute_license_value = case when @license_attribute_license_value is null then v.license_attribute_license_value else @license_attribute_license_value end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
