CREATE PROCEDURE [dbo].[usp_license_select_license_autorenewal_cycle]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-09-22	esmart		Initial creation
	
	DESCRIPTION
	select license autorenewal 
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select a.message_autorenewal_cycle_id, a.autorenewal_cycle_name, a.autorenewal_cycle, c.billing_day_of_month	
	from license_autorenewal_cycle c
	inner join message_autorenewal_cycle a
		on c.message_autorenewal_cycle_id = a.message_autorenewal_cycle_id
	where license_id = @license_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
