CREATE PROCEDURE [dbo].[usp_license_select_license_autorenewal_opt_out]


(
	@license_id int,
	@status varchar(10) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2020-03-26	esmart		Initial creation.

	DESCRIPTION
	select license_autorenewal_opt_out
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select top(1) l.license_autorenewal_opt_out_id, l.license_id, l.license_category_id, l.license_seats, l.status, l.message_campaign_id, l.insert_date
		from license_autorenewal_opt_out l
		where l.license_id = @license_id and
			l.status = case when @status is null then l.status else @status end
		order by l.insert_date desc
		

		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
