-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_by_email_last_name_product_line]

(
	@customer_email varchar(100),
	@last_name nvarchar(225),
	@product_line_prefix char(2)
)

/*	
	DATE		AUTHOR		REMARKS
	2006-09-25	esmart		Initial creation.
	2006-10-20	esmart		Add check for high match email address to eliminate performance issues
	2006-11-17	esmart		Remove spaces from inputs. 
	2007-02-22	esmart		Add lookup of license related to orders for the customer. Modify max_email_count to include match on last_name.
	2007-07-12  bjordan		Changed temp tables to table variables and in to join
	2010-10-24	esmart		Add support for keycoded WW and include license category
	2012-05-21	esmart		Add support for SS and SA for product_line
	2012-10-31	esmart		Enhancements
	2015-02-20	emsart		Add license category description

	DESCRIPTION
	Select best licenses for customer email, last name, and product line
*/

AS
	set nocount on

	declare @last_expiration_date datetime

	select @last_expiration_date = dateadd(mm,-3,getdate())
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	-- 1) check for leading or trailing spaces
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set @customer_email = ltrim(rtrim(@customer_email))
	set @last_name = ltrim(rtrim(@last_name))
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) check to see if this is widely used email. If count is greater than 5 then stop
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @product_line_list table (product_line_prefix char(2))
	
	insert into @product_line_list(product_line_prefix) values(@product_line_prefix)

	if @product_line_prefix = 'SA'
		begin
		insert into @product_line_list(product_line_prefix) values('SS')
		end
		
	if @product_line_prefix = 'SS'
		begin
		insert into @product_line_list(product_line_prefix) values('SA')
		end
	
	-- 2.2)
	declare @email_count int,
		@max_email_count int

	set @max_email_count = 5

	select @email_count = count(*)
	from customer_email e with (nolock)
	inner join customer c with (nolock)
		on e.customer_id = c.customer_id
	where c.last_name = @last_name and customer_email = @customer_email and email_status_id = 1
	
	if @email_count > @max_email_count
		begin
			insert into temp_redownload_attempts (customer_email, last_name, product_line_prefix, keycode, total_keycodes)
			values (@customer_email, @last_name, @product_line_prefix, 'EXCEED_EMAIL_COUNT',0)
			return
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	-- 3) look up keycode
	------------------------------------------------------------------------------------------------------------------------------------------------
-------------------------------------------------------------------------------------------------------------------------------
	else 
		begin
			
		-- 3.1) create temp table	
		
		declare @license table (license_id int, keycode varchar(40), product_line_id int, license_category_id tinyint)

		insert into @license(license_id,keycode, product_line_id)
		select l2.license_id, l2.keycode, p2.product_line_id
		from license l2 with (nolock)
		inner join order_item_license ol with (nolock)
			on l2.license_id = ol.license_id
		inner join order_item i with (nolock)
			on ol.order_item_id = i.order_item_id
		inner join customer_order co with (nolock)
			on i.order_header_id = co.order_header_id
		inner join product_line p2 with (nolock)
			on l2.product_line_id = p2.product_line_id
		inner join (select c.customer_id
				from customer c with (nolock)
				inner join customer_email e with (nolock)
					on c.customer_id = e.customer_id and email_status_id = 1
				where c.last_name = @last_name and e.customer_email = @customer_email) cust on
			co.customer_id = cust.customer_id
		where p2.product_line_prefix in (select product_line_prefix from @product_line_list) and p2.product_line_id not in (300,11)
			and l2.license_status_id in (1,0) 

		insert into @license(license_id,keycode, product_line_id)
		select l.license_id, l.keycode, p.product_line_id
		from license l with (nolock)
		inner join product_line p with (nolock)
			on l.product_line_id = p.product_line_id
		inner join (select c.customer_id
				from customer c with (nolock)
				inner join customer_email e with (nolock)
					on c.customer_id = e.customer_id and email_status_id = 1
				where c.last_name = @last_name and e.customer_email = @customer_email) cust 
			on l.customer_id = cust.customer_id
		where p.product_line_prefix in (select product_line_prefix from @product_line_list) and p.product_line_id not in (300,11)
			and l.license_status_id in (1,0)

		update @license
		set license_category_id = isnull(cl.license_category_id,dbo.fn_GetLicenseCategoryId(t.license_id))
		from @license t
		left join license_category_license cl
			on t.license_id = cl.license_id

		-- 3.2) insert into temp table
		declare @keycode varchar(40), @total_keycodes int

		select @keycode = (select top 1 keycode 
							from @license l
							inner join license_category c
								on l.license_category_id = c.license_category_id
							inner join license_capability cp
								on l.license_id = cp.license_id and cp.capability_id = c.base_capability_id
							order by cp.capability_expiration_date desc)

		select @total_keycodes = (select count(*) from @license)

		insert into temp_redownload_attempts (customer_email, last_name, product_line_prefix, keycode, total_keycodes)
		values (@customer_email, @last_name, @product_line_prefix, @keycode, @total_keycodes)

		-- 3.3) return result
		select distinct l.license_id, l.keycode, a.keycode_alias, l.product_line_id, l.license_category_id, c.license_category_name, c.license_category_description, cp.capability_activation_days, t.capability_type_description, cp.capability_expiration_date, s.license_seats
		from @license l
		inner join license_category c
			on l.license_category_id = c.license_category_id
		inner join license_capability cp
			on l.license_id = cp.license_id and cp.capability_id = c.base_capability_id
		inner join capability_type t
			on cp.capability_type_id = t.capability_type_id
		left join license_seat s
			on l.license_id = s.license_id
		left join license_keycode_alias a
			on l.license_id = a.license_id
		where cp.capability_activation_days is not null and cp.capability_activation_days > 0 and (cp.capability_expiration_date > @last_expiration_date or cp.capability_expiration_date is null)
		order by cp.capability_expiration_date desc
				
		end



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_by_id]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_license_by_id] (	
	@license_id INT
)

/*	
	DATE		AUTHOR		REMARKS
	2006-09-01	esmart			Initial creation.
	2007-03-13	esmart			Add parent_license_id for child licenses, and license_seat columns
	2008-09-15	esmart			Add license_storage 
	2011-08-05	esmart			Account lookup
	2011-11-07	esmart			Keycode alias
	2013-08-12	mrobbins		add product_line_description, license_status_description, license_type_description, license_attribute_tag, license_attribute_license_value, license_attribute_license_value_description
	2013-10-18	esmart			Change license_key to varchar(36)
	2014-09-02	esmart			oem_type
	2016-06-10	esmart			license migration
	2016-09-15	esmart			salesforce_license_id
	2017-02-27	acoffel			dish
	2017-08-09	esmart			Add capability_type
	2019-01-09	rvinoche		Support autobilling attributes living only in license_effective_object
	2019-04-08	cnovac			Updated to just use effective object and return autorenewal_cycle
	2024-05-23	singaravelam	ECOM-4285 added column portal_flag to return license belongs to portal
    2025-11-27  rdobariya		US-5028433: Added renewal_count, license_origin_channel_name, email_opt_in and license_distribution_method_code to the return select
    2026-02-09	rdobariya		US-5164088 Add license_original_activation_date,next_bill_date in the returned result
	2026-03-25	pachanta		US-5117514 Added Consumed License seats for consumer.
	2026-04-28	gblandford		US-5366187 - https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5366187
								- add 'SMBC_Product_Interests__c' which is now mapped to license_category and returned as a ;-delimited column smbc_product_interests
								- formatting & casing changes
								- optimizations; adding schemas, NOT EXISTS/JOINS
								- SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED for performance gains over WITH (UNLOCK)
								- insert of license_key moved wrapped in READ COMMITTED 
								- refactored section numbers
								- merged in 2025-11-27 to 2026-03-25 changes and optimized code; was impacting performance

	DESCRIPTION
	Select all details from license

*/

AS

SET NOCOUNT ON

DECLARE @response_code INT,
	@message VARCHAR(100)

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

BEGIN TRY

    DECLARE @keycode_alias VARCHAR(40),
        @account_id INT,
        @account_user_name VARCHAR(100),
        @license_attribute_id INT,
        @license_attribute_description VARCHAR(100),
        @license_attribute_tag VARCHAR(20),
        @license_attribute_license_value INT,
        @license_attribute_license_value_description VARCHAR(50),
        @license_attribute_last_modified DATETIME,
        @license_key VARCHAR(36),
        @parent_license_id INT,
        @parent_keycode VARCHAR(40),
        @parent_salesforce_license_id VARCHAR(18),
        @license_category_id TINYINT,
        @license_category_name VARCHAR(10),
        @license_category_description VARCHAR(50),
        @license_migration VARCHAR(10),
        @start_date DATETIME,
        @end_date DATETIME,
        @oem_type VARCHAR(50),
        @salesforce_license_id VARCHAR(18),
        @base_capability_id INT,
        @capability_type_id INT,
        @capability_type_description VARCHAR(20),
        @renewal_count INT,
        @license_origin_channel_name VARCHAR(100),
        @license_original_activation_date DATETIME

    DECLARE @PORTAL_DISTRIBUTION_METHOD TABLE (
        portal_distribution_method_code VARCHAR(4)
    )

    -- 1.0) Portal distribution methods
    INSERT INTO @PORTAL_DISTRIBUTION_METHOD (
        portal_distribution_method_code
    )
    SELECT 
		f.[key]
    FROM [dbo].[fn_app_config_select_key_v
alues]('PORTAL_DISTI_CODES', 'PORTAL') f

    -- 1.1) @keycode_alias
    SELECT 
		@keycode_alias = keycode_alias
    FROM dbo.license_keycode_alias
    WHERE license_id = @license_id

    -- 1.2) select account_id
    SELECT @account_id = a.account_id,
           @account_user_name = a.account_user_name
    FROM dbo.account_license al
        INNER JOIN dbo.account a
            ON al.account_id = a.account_id
               AND a.account_type_id = 1
               AND a.account_status_id <> 2
    WHERE al.license_id = @license_id

    -- 1.3) check account_device
    IF @account_id IS NULL BEGIN
			SELECT @account_id = a.account_id,
				   @account_user_name = a.account_user_name
			FROM dbo.account a
				INNER JOIN dbo.account_device ad 
					ON ad.license_id = @license_id
						AND ad.account_id = a.account_id
		END

	-- 1.4) select license_key
	IF ( NOT EXISTS ( SELECT 1 FROM dbo.license_key WHERE license_id = @license_id ) AND @license_id IS NOT NULL ) BEGIN

			SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

				INSERT INTO dbo.license_key (
					license_id
				) VALUES ( @license_id )

			SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		END

    SELECT 
		@license_key = CONVERT(VARCHAR(36), lk.license_key),
        @salesforce_license_id = lk.salesforce_license_id
    FROM dbo.license_key lk 
    WHERE license_id = @license_id

    -- 1.5) license_attribute_license
    SELECT 
		@license_attribute_id = la.license_attribute_id,
        @license_attribute_description = la.license_attribute_description,
        @license_attribute_tag = la.license_attribute_tag,
        @license_attribute_license_value = v.license_attribute_license_value,
        @license_attribute_license_value_description = v.license_attribute_license_value_description,
        @license_attribute_last_modified = f.effective_start_date
    FROM dbo.fn_license_select_effective_object_table(@license_id, GETDATE()) f
        INNER JOIN dbo.license_category_license lcl 
            ON lcl.license_id = f.license_id
        LEFT JOIN dbo.license_attribute_license_value v 
            ON f.effective_value = v.license_attribute_license_value
        LEFT JOIN dbo.license_attribute la 
            ON v.license_attribute_id = la.license_attribute_id
    WHERE f.license_category_id = lcl.license_category_id --endpoint only for now
          AND f.effective_object_id = 2 --autobilling attribute

    IF ( @license_attribute_license_value IS NULL ) BEGIN --meaning the license does not have an autobilling attribute, so we'll check for ar

			SELECT 
				@license_attribute_id = lal.license_attribute_id,
				@license_attribute_description = la.license_attribute_description,
				@license_attribute_tag = la.license_attribute_tag,
				@license_attribute_license_value = v.license_attribute_license_value,
				@license_attribute_license_value_description = v.license_attribute_license_value_description,
				@license_attribute_last_modified = lal.modified_date
			FROM dbo.license_attribute_license lal 
				LEFT JOIN dbo.license_attribute la 
					ON lal.license_attribute_id = la.license_attribute_id
				LEFT JOIN dbo.license_attribute_license_value v 
					ON lal.license_attribute_license_value = v.license_attribute_license_value
			WHERE lal.license_id = @license_id
		END

    -- 1.6) select license_parent
    SELECT 
		@parent_license_id = l2.license_id,
        @parent_keycode = l2.keycode,
		@parent_salesforce_license_id = k.salesforce_license_id
    FROM dbo.license_parent lp
        INNER JOIN dbo.license l2 
            ON lp.parent_license_id = l2.license_id
        INNER JOIN dbo.license_key k
            ON l2.license_id = k.license_id
    WHERE lp.child_license_id = @license_id

    -- 1.7) select license_category
    SELECT 
		@license_category_id = c.license_category_id,
        @license_category_name = c.license_category_name,
        @license_category_description 
= c.license_category_description,
        @base_capability_id = c.base_capability_id,
        @start_date = lc.start_date,
        @end_date = lc.end_date
    FROM dbo.license_category_license lc 
        INNER JOIN dbo.license_category c
            ON lc.license_category_id = c.license_category_id
    WHERE lc.license_id = @license_id

    -- 1.8) select capability_type
    SELECT 
		@capability_type_id = t.capability_type_id,
        @capability_type_description = t.capability_type_description
    FROM dbo.license_capability c
        INNER JOIN dbo.capability_type t
            ON t.capability_type_id = c.capability_type_id
    WHERE c.license_id = @license_id
          AND c.capability_id = @base_capability_id

    -- 1.9) @oem_type
    SELECT @oem_type = ( CASE
							   WHEN license_feature_license_id IS NULL THEN
								   NULL
							   ELSE
								   'Fixed expiration'
						END )
    FROM dbo.license_feature_license
    WHERE license_id = @license_id
          AND license_feature_id = 8

    -- 1.10) @license_migration_keycode
    SELECT @license_migration = ( CASE
										WHEN COUNT(*) > 0 THEN
											'Yes'
										ELSE
											'No'
									END )
    FROM dbo.license_migration m
    WHERE m.original_license_id = @license_id
          OR m.new_license_id = @license_id

    -- 1.11) @renewal_count
	SELECT 
		@renewal_count = COUNT( oil.license_id )
	FROM dbo.order_item_license  AS oil
		INNER JOIN dbo.order_item AS oi 
			ON oi.order_item_id = oil.order_item_id
		INNER JOIN dbo.product AS p  
			ON oi.product_id = p.product_id
		INNER JOIN dbo.product_type pt
			ON pt.product_type_id = p.product_type_id
	WHERE oil.license_id = @license_id
		AND pt.product_type_id = 2; -- Renewals

	-- 1.12) @license_origin_channel_name
	SELECT TOP 1 
		@license_origin_channel_name = c.channel_name,
		@license_original_activation_date = lh.insert_date
	FROM dbo.license_history lh
		INNER JOIN dbo.license_distribution_method_channel ldmc 
			ON ldmc.license_distribution_method_id = lh.license_distribution_method_id
		INNER JOIN dbo.channel c 
			ON c.channel_id = ldmc.channel_id
	WHERE lh.license_id = @license_id
	ORDER BY lh.history_date ASC;

	IF @license_origin_channel_name IS NULL BEGIN
			SELECT 
				@license_origin_channel_name = c.channel_name,
				@license_original_activation_date = l.insert_date
			FROM dbo.license l 
				INNER JOIN dbo.license_distribution_method_channel ldmc 
					ON ldmc.license_distribution_method_id = l.license_distribution_method_id
				INNER JOIN dbo.channel c
					ON c.channel_id = ldmc.channel_id
			WHERE l.license_id = @license_id;
		END

    -- 2.0) select license
    SELECT 
		l.license_id,
		l.keycode,
		keycode_alias = a.keycode_alias,
		l.customer_id,
		p.product_line_id,
		p.product_line_description,
		p.root_product_id,
		st.license_status_id,
		st.license_status_description,
		t.license_type_id,
		t.license_type_description,
		l.license_distribution_method_id,
		l.license_keycode_type_id,
		l.max_daily_activations,
		l.max_child_licenses,
		l.license_expiration_date,
		l.insert_date,
		l.insert_by,
		l.modified_date,
		l.modified_by,
		parent_license_id = @parent_license_id,
		parent_keycode = @parent_keycode,
		parent_salesforce_license_id = @parent_salesforce_license_id,
		s.license_seats,
		las.consumed_seats,
		seats_used = 0,
		ls.storage_gb,
		license_category_id = @license_category_id,
		license_category_name = @license_category_name,
		license_category_description = @license_category_description,
		start_date = @start_date,
		end_date = @end_date,
		capability_type_id = @capability_type_id,
		capability_type_description = @capability_type_description,
		account_id = @account_id,
		account_user_name = @account_user_name,
		license_key = @license_key,
		salesforce_license_id = @salesforce_license_id,
		license_attribute_id = @license_attribute_id,
		licens
e_attribute_description = @license_attribute_description,
		license_attribute_tag = @license_attribute_tag,
		license_attribute_license_value = @license_attribute_license_value,
		license_attribute_license_value_description = @license_attribute_license_value_description,
		license_attribute_last_modified = @license_attribute_last_modified,
		oem_type = @oem_type,
		license_migration = @license_migration,
		bestbuy_flag = ( CASE
								WHEN su.license_distribution_method_id IS NOT NULL THEN
									1
								ELSE
									0
							END ),
		dish_license_subscription_id = ( CASE
												WHEN d.dish_license_subscription_id IS NULL THEN
													0
												ELSE
													d.dish_license_subscription_id
											END ),
		autorenewal_status = ( CASE
									WHEN lal.license_attribute_license_value = 1 THEN
										1
									ELSE
										0
								END ),
		autorenewal_status_description = lalv.license_attribute_license_value_description,
		autorenewal_cycle = dbo.fn_license_select_effective_object_element(
																				l.license_id,
																				@license_category_id,
																				'billing_day_of_month',
																				GETDATE()
																			),
		portal_flag = ( CASE
								WHEN pdm.portal_distribution_method_code IS NOT NULL THEN
									1
								ELSE
									0
							END ),
        renewal_count = @renewal_count,
        license_origin_channel_name = @license_origin_channel_name,
        license_original_activation_date = @license_original_activation_date,
        email_opt_in = c.opt_in,
        ldm.license_distribution_method_code,
        nb.next_bill_date,

		smbc_product_interest = dbo.fn_license_select_sfdc_license_category_mapping_values( l.license_id, 'SMBC_Product_Interests__c' )

    FROM dbo.license l 
        INNER JOIN dbo.product_line p 
            ON p.product_line_id = ( CASE
										   WHEN @license_category_id IN ( 100, 110, 115, 120 )
												AND l.product_line_id = 1 THEN
											   100
										   WHEN @license_category_id IN ( 100, 110, 115, 120 )
												AND l.product_line_id = 6 THEN
											   200
										   ELSE
											   l.product_line_id
									   END )

        INNER JOIN dbo.license_type t
            ON l.license_type_id = t.license_type_id
        INNER JOIN dbo.license_status st
            ON l.license_status_id = st.license_status_id
        LEFT JOIN dbo.customer c 
			ON c.customer_id = l.customer_id
		LEFT JOIN dbo.license_distribution_method AS ldm
            ON l.license_distribution_method_id = ldm.license_distribution_method_id
        LEFT JOIN @PORTAL_DISTRIBUTION_METHOD AS pdm
            ON ldm.license_distribution_method_code = pdm.portal_distribution_method_code
        LEFT JOIN dbo.license_seat s
            ON l.license_id = s.license_id
		LEFT JOIN dbo.license_active_seats las 
            ON l.license_id = las.license_id
        LEFT JOIN dbo.license_storage ls
            ON l.license_id = ls.license_id
        LEFT JOIN dbo.license_keycode_alias a
            ON l.license_id = a.license_id
        LEFT JOIN dbo.subscription_distribution_method su
            ON l.license_distribution_method_id = su.license_distribution_method_id
        LEFT JOIN dbo.dish_license_subscription d
            ON l.license_id = d.license_id
        LEFT JOIN dbo.license_attribute_license lal
            ON lal.license_id = l.license_id
        LEFT JOIN dbo.license_attribute_license_value lalv
            ON lalv.license_attribute_license_value = lal.license_attribute_license_value
        LEFT JOIN dbo.license_next_bill_date nb
			ON nb.license_id = l.license_id
    WHERE l.license_id = @license_id

END TRY

BEGIN CATCH

    SET @response_code = -200
    SET @message = ( CASE
						   WHEN @message IS NULL THEN
							   'select failed'
						   ELSE
							   @message
					   END )

    DECLARE @DBName NVARCHAR(12
8)
    SET @DBName = DB_NAME()
    EXECUTE dbo.usp_LogError @ErrorDB = @DBName

END CATCH;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_capability]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_capability]

(
	@license_id int
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2010-02-03	dsmelker	Added with(nolock)

	DESCRIPTION
	select capabilities for a license	
*/

	select c.license_capability_id, 
		c.license_id, 
		c.capability_id, 
		ca.capability_name,
		ca.capability_description,
		c.capability_type_id, 
		c.capability_activation_days, 
		c.capability_activation_date, 
		c.capability_expiration_date, 
		c.insert_date,
		c.insert_by,
		c.modified_date,
		c.modified_by,
		t.capability_ext_type_id,
		t.capability_ext_type_name
	from license_capability c with(nolock)
	inner join capability ca with(nolock)
		on c.capability_id = ca.capability_id
	left join capability_ext e with(nolock)
		on c.capability_id = e.capability_id and e.capability_ext_type_id = 1
	left join capability_ext_type t with(nolock)
		on e.capability_ext_type_id = t.capability_ext_type_id
	where license_id = @license_id
	order by ca.capability_sort_order


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_capability_history]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_capability_history]

(
	@license_id int,
	@capability_id int

)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-10-04	esmart		Initial creation
	2006-10-10	esmart		modified days_remaining to show 0 instead of negative number
	2006-11-07	esmart		Modified original_capability_activation_date to reflect first activation date regardless of contiguous days. 
								NOTE: Days, activation_date, and expiration date in result set will no longer tie together.
	2010-02-04	dsmelker	Added with(nolock)
	2011-09-12	esmart		Modified days_remaining to use Prevx formula

	DESCRIPTION
	select license capability history for a license
*/

	select license_capability_id, 
		capability_id, 
		license_id, 
		capability_description, 
		days_contiguous, 
		days_remaining, 
		original_capability_activation_date = capability_activation_date,
		capability_expiration_date
	from (select 	l.license_capability_id,
			l.capability_id,
			l.license_id,
			c.capability_description,
			capability_activation_date = isnull((select min(capability_activation_date) 
							from license_capability_history with(nolock)
							where license_capability_id = l.license_capability_id),l.capability_activation_date),
			l.capability_expiration_date,
			days_contiguous = isnull((select days_contiguous 
						from license_capability_history with(nolock)
						where license_capability_id = l.license_capability_id and license_capability_history_id = 
							(select max(license_capability_history_id)
							from license_capability_history with(nolock) 
							where license_capability_id = l.license_capability_id)
						),capability_activation_days),
			days_remaining = 
				case
					when datediff(ss,getdate(),capability_expiration_date)/86400 < 0 then 0
					else datediff(ss,getdate(),capability_expiration_date)/86400
				end
	from license_capability l with(nolock)
	inner join capability c with(nolock)
		on l.capability_id = c.capability_id
	where	l.license_id = @license_id  and c.capability_id = @capability_id) t


GO
