CREATE PROCEDURE [dbo].[usp_license_select_license_capability_history_detail]

(
	@license_id int
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-09-17	esmart		Initial creation

	DESCRIPTION
	select license capability history for a license
*/



	declare @temp_capability_history table (
		modified_date datetime,
		modified_by varchar(20),
		first_name varchar(255),
		last_name varchar(255),
		license_change_reason varchar(100),
		capability_description varchar(50),
		capability_type_description varchar(20),
		capability_activation_days int,
		capability_activation_date datetime,
		capability_expiration_date datetime,
		capability_id int,
		days_used int,
		days_remaining int,
		days_added int,
		days_new int,
		days_contiguous int,
		sort_order int,
		license_capability_history_id int
	)

--	insert into @temp_capability_history (modified_date, modified_by, first_name, last_name, license_change_reason, capability_description, capability_type_description, capability_activation_days, capability_activation_date, capability_expiration_date, capability_id, days_used, days_remaining, days_added, days_new, days_contiguous, sort_order, license_capability_history_id)
--	select 	h.modified_date,
--		h.modified_by,
--		first_name = case 
--						when u.csi_users_id = '' then ''	
--						when u.first_name is null then h.modified_by
--						else u.first_name 
--					end,
--		last_name = case 
--						when u.csi_users_id = '' then '' 
--						when u.last_name is null then '' 
--						else u.last_name 
--					end,	 
--		license_change_reason = convert(varchar(100),''),
--		c.capability_description,
--		t.capability_type_description,
--		capability_activation_days,
--		capability_activation_date,
--		capability_expiration_date,
--		c.capability_id,
--		days_used = 0, 
--		days_remaining = 0, 
--		days_added = 0, 
--		days_new = 0, 
--		days_contiguous = 0,
--		sort_order = 1,
--		license_capability_history_id = 1
--	from license_capability h
--	inner join capability c
--		on h.capability_id = c.capability_id
--	inner join capability_type t
--		on h.capability_type_id = t.capability_type_id
--	left join csi_users u 
--		on h.modified_by = u.csi_users_id 
--	where h.license_id = @license_id
	
	insert into @temp_capability_history (modified_date, modified_by, first_name, last_name, license_change_reason, capability_description, capability_type_description, capability_activation_days, capability_activation_date, capability_expiration_date, capability_id, days_used, days_remaining, days_added, days_new, days_contiguous, sort_order, license_capability_history_id)
	select 	h.history_date,
		h.history_by,
		first_name = case 
						when u.csi_users_id = '' then ''	
						when u.first_name is null then h.history_by
						else u.first_name 
					end,
		last_name = case 
						when u.csi_users_id = '' then '' 
						when u.last_name is null then '' 
						else u.last_name 
					end,
		r.license_change_reason,
		c.capability_description,
		t.capability_type_description,
		capability_activation_days,
		capability_activation_date,
		capability_expiration_date,
		c.capability_id,
		isnull(days_used,0), 
		isnull(days_remaining,0), 
		isnull(days_added,0), 
		isnull(days_new,0), 
		isnull(days_contiguous,0),
		sort_order = 2,
		license_capability_history_id
	from license_capability_history h 
	inner join license_change_reason r
		on h.capability_change_reason_id = r.license_change_reason_id
	inner join capability c
		on h.capability_id = c.capability_id
	inner join capability_type t
		on h.capability_type_id = t.capability_type_id
	left join csi_users u 
		on h.history_by = u.csi_users_id 
	where h.license_id = @license_
id and capability_change_reason_id not in (6,7,12)
	order by license_capability_history_id desc
	
	select modified_date, modified_by, first_name, last_name, license_change_reason, capability_description, capability_type_description, capability_activation_days, capability_activation_date, capability_expiration_date, days_used, days_remaining, days_added, days_new, days_contiguous
	from @temp_capability_history
	order by sort_order, 
		modified_date desc,
		--license_capability_history_id desc, 
		capability_id



GO
