-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_category_license_history]

(
		@keycode varchar(40)
)

/*	
	DATE        AUTHOR    REMARKS
	2011-09-06  esmart    Initial creation.
  2012-10-29  cfaulkner Added (nolock) hints.

	DESCRIPTION
	select license_category_license_history
*/

AS
	set nocount on				

	declare	@license_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @license_id
	select @license_id = license_id from license (nolock) where keycode = @keycode


	-- 1.2) select history
	select lcl.license_category_license_id, lcl.license_id, lc.license_category_id, lc.license_category_name, lc.license_category_description, start_date, end_date, last_modified_date, license_change_reason = convert(varchar(100),'')
	from license_category_license lcl (nolock)
	inner join license_category lc (nolock)
		on lcl.license_category_id = lc.license_category_id
	where lcl.license_id = @license_id
	union
	select lcl.license_category_license_id, lcl.license_id, lc.license_category_id, lc.license_category_name, lc.license_category_description, start_date, end_date, last_modified_date, r.license_change_reason
	from license_category_license_history lcl (nolock)
	inner join license_category lc (nolock)
		on lcl.license_category_id = lc.license_category_id
	inner join license_change_reason r (nolock)
		on lcl.license_change_reason_id = r.license_change_reason_id
	where lcl.license_id = @license_id
	order by last_modified_date desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
