CREATE PROCEDURE [dbo].[usp_license_select_license_category_module]

(
                                @license_category_name varchar(10) 
)

/*           
                DATE                     AUTHOR                              REMARKS
                2011-06-22          esmart                  Initial creation.

                DESCRIPTION
                select license_category_module
*/

AS
                set nocount on                                                 

                declare @response_code int,
                                                @message varchar(100)

                begin try

                -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                -- 1.) select
                -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                
                -- 1.0) 
                select m.license_module_code, t.license_module_type_name
                from license_category_module cm
                inner join license_module m 
                                on cm.license_module_id = m.license_module_id
                inner join license_module_type t
                                on cm.license_module_type_id = t.license_module_type_id
                inner join license_category c
                                on cm.license_category_id = c.license_category_id
                where c.license_category_name = @license_category_name
                

                end try

                begin catch

                                set @response_code = -200
                                set @message = case when @message is null then 'insert failed'
                                                                                                                else @message end

                                declare @DBName nvarchar(128)
                                set @DBName = db_name()
                                exec usp_LogError @ErrorDB = @DBName
                                
                end catch;
                
                

GO
