CREATE  PROCEDURE [dbo].[usp_license_select_license_category_module_by_license_id]
(
    @license_id INT,
    @license_category_name VARCHAR(10),
    @cart_order_id INT = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2014-09-22	esmart		Initial creation
	2020-11-09	abelenkiy	Added null iso input to function (not being used here but function changed to return generic module string when called from another proc)
	2024-09-03  lpraharsha  Added cart order id as part of php requirement as part of ecom-5185 which is needed in fn_license_module_license_category_key_value.(pill sky-provisoning changes) 
	DESCRIPTION
	select license module license
	
	DEPENDENCY
	This procedure is invoked by Item class when it is trying to build the sky requests when CreateMasterKey is Called at models/cart_order/Item.php
	
*/

AS
SET NOCOUNT ON;

DECLARE @response_code INT,
        @message VARCHAR(100);

BEGIN TRY

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    SELECT license_module_license_string = [dbo].[fn_license_module_license_category_key_value](
                                                                                                   @license_id,
                                                                                                   @license_category_name,
                                                                                                   NULL,
                                                                                                   @cart_order_id
                                                                                               );

END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'update account update failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;



GO
