-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_license_category_storage]

(
	@license_category_name varchar(10), 
	@usage_pricing_model_id tinyint = null, 
	@product_platform_id tinyint = null, 
	@retention_model_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2020-10-08	esmart		Initial creation.

	DESCRIPTION
	Insert license_category_storage
*/

AS

	declare @response_code int,
			@message varchar(100)
	

begin try


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------



	select s.license_category_storage_id, s.license_category_id, s.storage_TB, s.quantity, e.usage_pricing_model_name, e.retention_model_name, e.product_platform_name, e.usage_pricing_model_id, e.retention_model_id, pp.product_platform_id, s.product_extension_json
	from license_category_storage s
	inner join license_category lc
		on lc.license_category_id = s.license_category_id
	outer apply fn_product_select_product_extension(s.product_extension_json) e
	left join product_platform pp
		on e.product_platform_id = pp.product_platform_id
	where lc.license_category_name = @license_category_name
		and (e.usage_pricing_model_id = @usage_pricing_model_id or @usage_pricing_model_id is null)
		and (e.product_platform_id = @product_platform_id or @product_platform_id is null)
		and (e.retention_model_id = @retention_model_id or @retention_model_id is null)

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_distribution_method]
-- =============================================================================

CREATE procedure [dbo].[usp_license_select_license_distribution_method]


/*	
	DATE		AUTHOR		REMARKS
	2008-03-31	??????		Initial creation.
	2008-10-01	esmart		Removed restriction on bulk load table
	2010-07-06	dsmelker	Added license_distribution_method_active		

	DESCRIPTION
	returns all distribution methods
*/


as
set nocount on 


	select distinct license_distribution_method_id, 
					license_distribution_method_code, 
					license_distribution_method_name 
	from license_distribution_method
	where license_distribution_method_active = 1
	order by license_distribution_method_code, license_distribution_method_name

	/*
	select distinct lm.license_distribution_method_id, 
					lm.license_distribution_method_code, 
					lm.license_distribution_method_name 
	from license_bulk_load lbl with (nolock)
	inner join license_distribution_method lm with (nolock)
		on lbl.license_distribution_method_id = lm.license_distribution_method_id
	where lbl.modified_date >= dateadd(dd,-540,getdate())
	order by lm.license_distribution_method_code, lm.license_distribution_method_name
	*/

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_distribution_method_detail]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_license_distribution_method_detail]

(
	@license_distribution_method_id int
)
/*	
	DATE		AUTHOR		REMARKS
	2012-11-09	esmart		Initial creation.
	2013-09-04	esmart		Add business unit	
	2014-01-22	esmart		Add license_count
	2025-06-02 spatil6      Added two new fields do_not_send_email and auto_extend
	2026-03-06  spatil6     Added seat_count_enforcement info

	DESCRIPTION
	select license distribution method detail
*/

AS
	set nocount on				
		

	declare	@best_buy_s2 tinyint,
	        @auto_extend TINYINT,
			@do_not_send_email TINYINT,
			@response_code int,
			@seat_count_enforcement TINYINT,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @best_buy_s2
	if (select count(*) from subscription_distribution_method where license_distribution_method_id = @license_distribution_method_id) > 0
		begin
		select @best_buy_s2 = 1
		end
	else
		begin
		select @best_buy_s2 = 0
		END
       

		---1.1.a) Auto extend
		if (select count(*) from license_distribution_method_churn where license_distribution_method_id = @license_distribution_method_id) > 0
		begin
		select @auto_extend = 1
		end
	else
		begin
		select @auto_extend = 0
		end

		----1.1.b)
		if (select count(*) from message_campaign_license_distribution_method where license_distribution_method_id = @license_distribution_method_id) > 0
		begin
		select @do_not_send_email = 1
		end
	else
		begin
		select @do_not_send_email = 0
		end
		
		--1.1.c) seat count enforcement
	SELECT @seat_count_enforcement = 
    ISNULL(MAX(pllsd.seat_count_enforcement), 0)
    FROM dbo.product_line_license_seat_distribution pllsd
    WHERE pllsd.license_distribution_method_id = @license_distribution_method_id;

	-- 1.2) result
	select m.license_distribution_method_id,m.license_distribution_method_code,m.license_distribution_method_name,
			m.license_distribution_method_active,mc.license_distribution_method_channel_id,
			c.channel_id,c.channel_name,
			b.distribution_business_unit_id, b.distribution_business_unit,
			a.distribution_account_id,a.distribution_account,
			cl.distribution_class_id,cl.distribution_class,
			g.distribution_geography_id,g.distribution_geography,
			m.insert_date,m.insert_by,m.modified_date,m.modified_by,
			best_buy_s2 = @best_buy_s2,
			seat_count_enforcement = @seat_count_enforcement,
			ldmc.churn_days_add,
			auto_extend = @auto_extend,
			do_not_send_email = @do_not_send_email,
			ldmc.churn_days_measure,
			license_count = (select count(*) from license with (nolock) where license_distribution_method_id = m.license_distribution_method_id)
	from license_distribution_method m
	inner join license_distribution_method_channel mc
		on m.license_distribution_method_id = mc.license_distribution_method_id
	inner join channel c
		on mc.channel_id = c.channel_id
	left join distribution_business_unit b
		on mc.distribution_business_unit_id = b.distribution_business_unit_id
	left join distribution_account a
		on mc.distribution_account_id = a.distribution_account_id
	left join distribution_class cl
		on mc.distribution_class_id = cl.distribution_class_id
	left join distribution_geography g
		on mc.distribution_geography_id = g.distribution_geography_id
	LEFT JOIN dbo.license_distribution_method_churn AS
 ldmc 
		ON ldmc.license_distribution_method_id = m.license_distribution_method_id
	LEFT JOIN message_campaign_license_distribution_method mcldm
		ON mcldm.license_distribution_method_id = m.license_distribution_method_id
	where m.license_distribution_method_id = @license_distribution_method_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
