-- PROCEDURE: [dbo].[usp_license_select_license_distribution_method_module]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_license_distribution_method_module]

(
	@license_distribution_method_id int,
	@license_module_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-15	esmart		Initial creation.

	DESCRIPTION
	select license_distribution_method_module
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select dm.license_distribution_method_module_id, dm.license_distribution_method_id, m.license_distribution_method_code, m.license_distribution_method_name,
		lm.license_module_code, license_module_name, lm.license_module_class_id, lm.license_module_status,
		dm.license_module_id, dm.license_module_type_id, t.license_module_type_name
	from license_distribution_method_module dm
	inner join license_distribution_method m
		on dm.license_distribution_method_id = m.license_distribution_method_id
	inner join license_module lm
		on dm.license_module_id = lm.license_module_id
	inner join license_module_type t
		on dm.license_module_type_id = t.license_module_type_id
	where dm.license_distribution_method_id = @license_distribution_method_id
	order by dm.license_module_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_distribution_method_search]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_distribution_method_search]

(
	@license_distribution_method_code char(4), 
	@license_distribution_method_name varchar(50),
	@license_distribution_method_active tinyint = 1,
	@channel_id int,
	@distribution_geography_id tinyint,
	@distribution_class_id tinyint,
	@distribution_account_id tinyint,
	@distribution_business_unit_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-09	esmart		Initial creation.
	2013-09-04	esmart		Add business unit	

	DESCRIPTION
	select license distribution method detail
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @license_distribution_method_code
	if @license_distribution_method_code is null 
		begin
		select @license_distribution_method_code = ''
		end

	-- 1.2) @license_distribution_method_name
	if @license_distribution_method_name is null
		begin
		select @license_distribution_method_name = ''
		end

	select @license_distribution_method_name = '%'+@license_distribution_method_name+'%'

	-- 1.3) @license_distribution_method_active
	if @license_distribution_method_active is null
		begin
		select @license_distribution_method_active = 1
		end

	-- 1.4) results
	select m.license_distribution_method_id,m.license_distribution_method_code,m.license_distribution_method_name,
			m.license_distribution_method_active,mc.license_distribution_method_channel_id,
			c.channel_id,c.channel_name,
			b.distribution_business_unit_id, b.distribution_business_unit,
			a.distribution_account_id,a.distribution_account,
			cl.distribution_class_id,cl.distribution_class,
			g.distribution_geography_id,g.distribution_geography,
			m.insert_date,m.insert_by,m.modified_date,m.modified_by
	from license_distribution_method m
	inner join license_distribution_method_channel mc
		on m.license_distribution_method_id = mc.license_distribution_method_id
	inner join channel c
		on mc.channel_id = c.channel_id
	left join distribution_business_unit b
		on mc.distribution_business_unit_id = b.distribution_business_unit_id
	left join distribution_account a
		on mc.distribution_account_id = a.distribution_account_id
	left join distribution_class cl
		on mc.distribution_class_id = cl.distribution_class_id
	left join distribution_geography g
		on mc.distribution_geography_id = g.distribution_geography_id
	where m.license_distribution_method_code = case when @license_distribution_method_code = '' then m.license_distribution_method_code else @license_distribution_method_code end 
		and m.license_distribution_method_name like @license_distribution_method_name
		and m.license_distribution_method_active = @license_distribution_method_active
		and mc.channel_id = case when (@channel_id = 0 or @channel_id is null) then mc.channel_id else @channel_id end 
		and mc.distribution_geography_id = case when (@distribution_geography_id = 0 or @distribution_geography_id is null) then mc.distribution_geography_id else @distribution_geography_id end 
		and mc.distribution_account_id = case when (@distribution_account_id = 0 or @distribution_account_id is null) then mc.distribution_account_id else @distribution_account_id end 
		and mc.distribution_class_id = case when (@distribution_class_id = 0 or @distribution_cla
ss_id is null) then mc.distribution_class_id else @distribution_class_id end 
		and mc.distribution_business_unit_id = case when (@distribution_business_unit_id = 0 or @distribution_business_unit_id is null) then mc.distribution_business_unit_id else @distribution_business_unit_id end 


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_distribution_seat_count_enforced]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_select_license_distribution_seat_count_enforced]
(
    @license_distribution_method_code CHAR(4), 
    @license_category_name VARCHAR(50)
)
AS

/*	
		DATE			AUTHOR		REMARKS
		2026-023-31      spatil6    ve: 5117515 select seat_count_enforcement value based on license distribution method and license category name 
		
		DESCRIPTION
		select license distribution seat count enforcement data 
*/

BEGIN
    SET NOCOUNT ON;

     SELECT ISNULL(pls.seat_count_enforcement, 0) AS seat_count_enforcement
    FROM dbo.license_distribution_method AS ldm
    LEFT JOIN dbo.license_category lc
        ON lc.license_category_name = @license_category_name
    LEFT JOIN dbo.product_line_license_seat_distribution AS pls
        ON pls.license_distribution_method_id = ldm.license_distribution_method_id
       AND pls.license_category_id = lc.license_category_id   
    WHERE ldm.license_distribution_method_code = @license_distribution_method_code;
END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_license_full_history]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_full_history]

(
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2012-12-01	esmart		Initial creation
	2024-04-12	singaravelam	modified storage_gb datatype smallint to int in @license_fact table
	
	DESCRIPTION
	Return full license history

	DEPENDENCY
	This procedure will be used history tab for the license in CSI.
*/

AS
SET NOCOUNT ON

DECLARE @product_line_id INT,
        @response_code INT,
        @message VARCHAR(100)

BEGIN TRY

    SELECT @product_line_id = product_line_id
    FROM license
    WHERE license_id = @license_id

    DECLARE @license_fact TABLE
    (
        [license_fact_id] [INT] IDENTITY(1, 1) NOT NULL,
        [license_id] [INT] NOT NULL,
        [license_category_id] [TINYINT] NULL,
        [license_seats] [INT] NULL,
        [storage_gb] [INT] NULL,
        [license_status_id] [TINYINT] NULL,
        [license_distribution_method_id] [INT] NULL,
        [license_change_reason_id] [TINYINT] NULL,
        [order_header_id] [INT] NULL,
        [activation_date] [DATETIME] NULL,
        [expiration_date] [DATETIME] NULL,
        [capability_type_id] [TINYINT] NULL,
        [activation_days] [INT] NULL,
        [days_remaining] [INT] NULL,
        [days_added] [INT] NULL,
        [history_date] [DATETIME] NULL,
        [history_by] VARCHAR(20)
    )


    IF @product_line_id IN ( 300, 55 )
    BEGIN
        -- 1.1) insert license_fact history
        INSERT INTO @license_fact
        (
            license_id,
            license_status_id,
            license_distribution_method_id,
            order_header_id,
            activation_date,
            expiration_date,
            capability_type_id,
            history_by,
            license_category_id,
            license_seats,
            storage_gb,
            license_change_reason_id,
            activation_days,
            days_remaining,
            days_added,
            history_date
        )
        SELECT ch.license_id,
               lh.license_status_id,
               lh.license_distribution_method_id,
               i.order_header_id,
               ch.capability_activation_date,
               ch.capability_expiration_date,
               ch.capability_type_id,
               ch.history_by,
               license_category_id = MAX(h.license_category_id),
               license_seats = MAX(s.license_seats),
               storage_gb = MAX(st.storage_gb),
               license_change_reason_id = MIN(ch.capability_change_reason_id),
               activation_days = MAX(ch.capability_activation_days),
               days_remaining = MAX(ch.days_remaining),
               days_added = MAX(ch.days_added),
               history_date = MIN(ch.history_date)
        FROM license_capability_history ch
            INNER JOIN license_change_reason r
                ON ch.capability_change_reason_id = r.license_change_reason_id
            LEFT JOIN license_category_license_history h
                ON h.license_id = ch.license_id
                   AND (h.order_item_id = ch.order_item_id)
                   AND h.license_change_reason_id NOT IN ( 18 )
            LEFT JOIN license_category c
                ON h.license_category_id = c.license_category_id
            LEFT JOIN license_seat_history s
                ON ch.license_id = s.license_id
                   AND (s.order_item_id = ch.order_item_id)
                   AND s.license_change_reason_id NOT IN ( 18 )
            LEFT JOIN license_storage_history st
                ON ch.license_id = st.license_id
                   AND (st.order_item_id = ch.order_item_id)
                   AND st.license_change_re
ason_id NOT IN ( 18 )
            LEFT JOIN license_history lh
                ON lh.license_id = ch.license_id
                   AND ABS(DATEDIFF(ss, lh.history_date, ch.history_date)) < 5
            LEFT JOIN order_item i
                ON ch.order_item_id = i.order_item_id
        WHERE --ch.license_capability_history_id > 67757356 and 
            ch.license_id = @license_id
            AND ch.capability_id = CASE
                                       WHEN c.base_capability_id IS NULL THEN
                                           1
                                       ELSE
                                           c.base_capability_id
                                   END
            AND capability_change_reason_id NOT IN ( 12, 18 )
        GROUP BY ch.license_id,
                 lh.license_status_id,
                 lh.license_distribution_method_id,
                 i.order_header_id,
                 ch.capability_activation_date,
                 ch.capability_expiration_date,
                 ch.capability_type_id,
                 ch.history_by
        UNION
        SELECT ch.license_id,
               lh.license_status_id,
               lh.license_distribution_method_id,
               i.order_header_id,
               ch.capability_activation_date,
               ch.capability_expiration_date,
               ch.capability_type_id,
               ch.history_by,
               license_category_id = MAX(h.license_category_id),
               license_seats = MAX(s.license_seats),
               storage_gb = MAX(st.storage_gb),
               license_change_reason_id = MIN(ch.capability_change_reason_id),
               activation_days = MAX(ch.capability_activation_days),
               days_remaining = MAX(ch.days_remaining),
               days_added = MAX(ch.days_added),
               history_date = MIN(ch.history_date)
        FROM license_capability_history ch
            INNER JOIN license_change_reason r
                ON ch.capability_change_reason_id = r.license_change_reason_id
            LEFT JOIN license_category_license_history h
                ON h.license_id = ch.license_id
                   AND
                   (
                       h.order_item_id IS NULL
                       AND ABS(DATEDIFF(ss, h.history_date, ch.history_date)) < 5
                   )
                   AND h.license_change_reason_id NOT IN ( 18 )
            LEFT JOIN license_category c
                ON h.license_category_id = c.license_category_id
            LEFT JOIN license_seat_history s
                ON ch.license_id = s.license_id
                   AND
                   (
                       s.order_item_id IS NULL
                       AND ABS(DATEDIFF(ss, s.history_date, ch.history_date)) < 5
                   )
                   AND s.license_change_reason_id NOT IN ( 18 )
            LEFT JOIN license_storage_history st
                ON ch.license_id = st.license_id
                   AND
                   (
                       st.order_item_id IS NULL
                       AND ABS(DATEDIFF(ss, st.history_date, ch.history_date)) < 5
                   )
                   AND st.license_change_reason_id NOT IN ( 18 )
            LEFT JOIN license_history lh
                ON lh.license_id = ch.license_id
                   AND ABS(DATEDIFF(ss, lh.history_date, ch.history_date)) < 5
            LEFT JOIN order_item i
                ON ch.order_item_id = i.order_item_id
        WHERE --ch.license_capability_history_id > 67757356 and 
            ch.license_id = @license_id
            AND ch.capability_id = CASE
                                       WHEN c.base_capability_id IS NULL THEN
                                           1
                                       ELSE
                                           c.base_capability_id
                                   END
            AND capa
bility_change_reason_id NOT IN ( 12, 18 )
        GROUP BY ch.license_id,
                 lh.license_status_id,
                 lh.license_distribution_method_id,
                 i.order_header_id,
                 ch.capability_activation_date,
                 ch.capability_expiration_date,
                 ch.capability_type_id,
                 ch.history_by
        ORDER BY ch.license_id,
                 MIN(ch.history_date)
    END
    ELSE
    BEGIN
        -- 1.1) insert license_fact history
        INSERT INTO @license_fact
        (
            license_id,
            license_status_id,
            license_distribution_method_id,
            order_header_id,
            activation_date,
            expiration_date,
            capability_type_id,
            history_by,
            license_category_id,
            license_seats,
            storage_gb,
            license_change_reason_id,
            activation_days,
            days_remaining,
            days_added,
            history_date
        )
        SELECT ch.license_id,
               lh.license_status_id,
               lh.license_distribution_method_id,
               i.order_header_id,
               ch.capability_activation_date,
               ch.capability_expiration_date,
               ch.capability_type_id,
               ch.history_by,
               license_category_id = MAX(h.license_category_id),
               license_seats = MAX(s.license_seats),
               storage_gb = MAX(st.storage_gb),
               license_change_reason_id = MIN(ch.capability_change_reason_id),
               activation_days = MAX(ch.capability_activation_days),
               days_remaining = MAX(ch.days_remaining),
               days_added = MAX(ch.days_added),
               history_date = MIN(ch.history_date)
        FROM license_capability_history ch
            INNER JOIN license_change_reason r
                ON ch.capability_change_reason_id = r.license_change_reason_id
            LEFT JOIN license_category_license_history h
                ON h.license_id = ch.license_id
                   AND
                   (
                       h.order_item_id = ch.order_item_id
                       OR ABS(DATEDIFF(ss, h.history_date, ch.history_date)) < 5
                   )
                   AND h.license_change_reason_id NOT IN ( 18, 20 )
            LEFT JOIN license_category c
                ON h.license_category_id = c.license_category_id
            LEFT JOIN license_seat_history s
                ON ch.license_id = s.license_id
                   AND
                   (
                       s.order_item_id = ch.order_item_id
                       OR ABS(DATEDIFF(ss, s.history_date, ch.history_date)) < 5
                   )
                   AND s.license_change_reason_id NOT IN ( 18, 20 )
            LEFT JOIN license_storage_history st
                ON ch.license_id = st.license_id
                   AND
                   (
                       st.order_item_id = ch.order_item_id
                       OR ABS(DATEDIFF(ss, st.history_date, ch.history_date)) < 5
                   )
                   AND st.license_change_reason_id NOT IN ( 18, 20 )
            LEFT JOIN license_history lh
                ON lh.license_id = ch.license_id
                   AND ABS(DATEDIFF(ss, lh.history_date, ch.history_date)) < 5
            LEFT JOIN order_item i
                ON ch.order_item_id = i.order_item_id
        WHERE --ch.license_capability_history_id > 67757356 and 
            ch.license_id = @license_id
            AND ch.capability_id = CASE
                                       WHEN c.base_capability_id IS NULL THEN
                                           1
                                       ELSE
                                           c.base_capability_id
                                   END
            AND capability_chang
e_reason_id NOT IN ( 12, 18, 20 )
        GROUP BY ch.license_id,
                 lh.license_status_id,
                 lh.license_distribution_method_id,
                 i.order_header_id,
                 ch.capability_activation_date,
                 ch.capability_expiration_date,
                 ch.capability_type_id,
                 ch.history_by
        ORDER BY ch.license_id,
                 MIN(ch.history_date)
    END

    -- 1.2) insert license_fact
    INSERT INTO @license_fact
    (
        license_id,
        license_category_id,
        license_seats,
        storage_gb,
        license_status_id,
        license_distribution_method_id,
        activation_date,
        expiration_date,
        capability_type_id,
        activation_days,
        history_date,
        days_remaining
    )
    SELECT ch.license_id,
           h.license_category_id,
           s.license_seats,
           st.storage_gb,
           lh.license_status_id,
           lh.license_distribution_method_id,
           ch.capability_activation_date,
           ch.capability_expiration_date,
           ch.capability_type_id,
           ch.capability_activation_days,
           ch.modified_date,
           DATEDIFF(dd, GETDATE(), ch.capability_expiration_date)
    FROM license_capability ch
        INNER JOIN license lh
            ON lh.license_id = ch.license_id
        LEFT JOIN license_category_license h
            ON ch.license_id = h.license_id
        LEFT JOIN license_category c
            ON h.license_category_id = c.license_category_id
        LEFT JOIN license_seat s
            ON ch.license_id = s.license_id
        LEFT JOIN license_storage st
            ON ch.license_id = st.license_id
    WHERE ch.capability_id = CASE
                                 WHEN c.base_capability_id IS NULL THEN
                                     1
                                 ELSE
                                     c.base_capability_id
                             END
          AND ch.license_id = @license_id


    -- 1.3) update missing data
    UPDATE @license_fact
    SET license_seats =
        (
            SELECT license_seats
            FROM @license_fact lf
                INNER JOIN
                (
                    SELECT license_fact_id = MIN(license_fact_id)
                    FROM @license_fact
                    WHERE license_id = f.license_id
                          AND license_seats IS NOT NULL
                ) t
                    ON lf.license_fact_id = t.license_fact_id
        )
    FROM @license_fact f
    WHERE f.license_seats IS NULL

    UPDATE @license_fact
    SET license_category_id =
        (
            SELECT license_category_id
            FROM @license_fact lf
                INNER JOIN
                (
                    SELECT license_fact_id = MIN(license_fact_id)
                    FROM @license_fact
                    WHERE license_id = f.license_id
                          AND license_category_id IS NOT NULL
                ) t
                    ON lf.license_fact_id = t.license_fact_id
        )
    FROM @license_fact f
    WHERE f.license_category_id IS NULL

    UPDATE @license_fact
    SET license_status_id =
        (
            SELECT license_status_id
            FROM @license_fact lf
                INNER JOIN
                (
                    SELECT license_fact_id = MIN(license_fact_id)
                    FROM @license_fact
                    WHERE license_id = f.license_id
                          AND license_status_id IS NOT NULL
                ) t
                    ON lf.license_fact_id = t.license_fact_id
        )
    FROM @license_fact f
    WHERE f.license_status_id IS NULL

    -- license_status_id
    UPDATE @license_fact
    SET license_distribution_method_id = l.license_distribution_method_id
    FROM @license_fact f
        INNER JO
IN license l
            ON f.license_id = l.license_id
    WHERE f.license_distribution_method_id IS NULL


    -- 1.4) return results
    SELECT f.license_fact_id,
           f.license_id,
           l.keycode,
           f.license_status_id,
           s.license_status_description,
           f.license_distribution_method_id,
           f.order_header_id,
           v.vendor_order_code,
           f.activation_date,
           f.expiration_date,
           f.capability_type_id,
           ct.capability_type_description,
           f.license_category_id,
           c.license_category_name,
           c.license_category_description,
           f.license_seats,
           f.storage_gb,
           f.license_change_reason_id,
           r.license_change_reason,
           f.activation_days,
           f.days_remaining,
           f.days_added,
           f.history_date,
           f.history_by
    FROM @license_fact f
        INNER JOIN capability_type ct
            ON f.capability_type_id = ct.capability_type_id
        INNER JOIN license l
            ON f.license_id = l.license_id
        LEFT JOIN license_status s
            ON f.license_status_id = s.license_status_id
        LEFT JOIN license_category c
            ON f.license_category_id = c.license_category_id
        LEFT JOIN license_change_reason r
            ON f.license_change_reason_id = r.license_change_reason_id
        LEFT JOIN order_header h
            ON f.order_header_id = h.order_header_id
        LEFT JOIN vendor_order v
            ON h.vendor_order_id = v.vendor_order_id
    ORDER BY f.license_fact_id DESC



END TRY
BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'insert failed'
                       ELSE
                           @message
                   END

--declare @DBName nvarchar(128)
    --set @DBName = db_name()
    --exec usp_LogError @ErrorDB = @DBName

END CATCH;



GO
