CREATE PROCEDURE [dbo].[usp_license_select_license_module]

(	
	@license_module_id int = null,
	@license_module_status varchar(20) = null,
	@license_module_class_id tinyint = null
)


/*	
	DATE			AUTHOR		REMARKS
	2014-08-04		esmart		Initial creation.
	2015-01-15		esmart		

	DESCRIPTION
	select license modules
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select m.license_module_id, m.license_module_code, m.license_module_name, m.license_module_status, c.license_module_class_id, c.license_module_class_name
	from license_module m
	inner join license_module_class c
		on m.license_module_class_id = c.license_module_class_id
	where m.license_module_id = case when @license_module_id is null then m.license_module_id else @license_module_id end and
		m.license_module_status = case when @license_module_status is null then m.license_module_status else @license_module_status end and
		m.license_module_class_id = case when @license_module_class_id is null then m.license_module_class_id else @license_module_class_id end
		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
