CREATE PROCEDURE [dbo].[usp_license_select_license_module_license_detail]

(
	@license_id int
)
	
/*	
	DATE			AUTHOR			REMARKS
	2017-02-03		esmart			Initial creation
	2017-08-02		acoffel			last change reason lookup
	2017-09-26		esmart			add effective columns
	2018-11-01		cnovac			removed effective columns

	DESCRIPTION
	select license_module_license
*/

as

	set nocount on
	

	declare @response_code int,
			@message varchar(100),
			@license_module_license_history_id int,
			@last_module_change_reason varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--1.1) last module change reason
	select @license_module_license_history_id = max(license_module_license_history_id) from license_module_license_history where license_id = @license_id
	select @last_module_change_reason = r.license_change_reason 
	from license_module_license_history h
	inner join license_change_reason r
		on h.license_change_reason_id = r.license_change_reason_id
	where h.license_module_license_history_id = @license_module_license_history_id

	--1.2) select module
	select m.license_module_license_id, m.license_id, m.license_module_id, lm.license_module_code, lm.license_module_name, m.license_module_type_id, t.license_module_type_name, m.start_date, m.end_date, m.last_modified_date, m.last_modified_by, m.module_seats, last_module_change_reason = @last_module_change_reason
	from license_module_license m
	inner join license_module lm
		on lm.license_module_id = m.license_module_id
	inner join license_module_type t
		on t.license_module_type_id = m.license_module_type_id
	where m.license_id = @license_id



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license_module_license failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
