-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_select_license_next_bill_date]
(@license_id INT)

/*	
	DATE			AUTHOR			REMARKS
	2024-04-04		singaravelam	Initial creation.
	

	DESCRIPTION
	The procedure selects next bill date and payment status information for the license.		

	DEPENDENCY
	This procedure will be used by Portal Billing details Tab for the license in CSI (https://csi.webroot.com/en_US/licenses/view/<<license_id>>).
		
*/
AS
SET NOCOUNT ON

BEGIN TRY

    SELECT lnbd.next_bill_date AS nextbilldate,
           sps.subscription_payment_status_name,
           lnbd.last_modified_date AS insert_date,
           lnbd.last_modified_by AS insert_user
    FROM dbo.license_next_bill_date AS lnbd
        LEFT OUTER JOIN dbo.subscription_payment_status AS sps
            ON lnbd.subscription_payment_status_id = sps.subscription_payment_status_id
    WHERE lnbd.license_id = @license_id

    UNION 

    SELECT lnbda.next_bill_date AS nextbilldate,
           sps.subscription_payment_status_name,
           lnbda.last_modified_date AS insert_date,
           lnbda.last_modified_by AS insert_user
    FROM dbo.license_next_bill_date_audit AS lnbda
        LEFT OUTER JOIN dbo.subscription_payment_status AS sps
            ON lnbda.subscription_payment_status_id = sps.subscription_payment_status_id
    WHERE lnbda.license_id = @license_id

    ORDER BY insert_date DESC

END TRY
BEGIN CATCH

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXEC dbo.usp_LogError @ErrorDB = @DBName

END CATCH;


GO
