CREATE PROCEDURE [dbo].[usp_license_select_license_OEM_details]

(	
	@license_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2006-09-13		esmart		Initial creation.
	2013-02-01		esmart		Add license_id and keycode

	DESCRIPTION
	Select all OEM details from license

*/

AS
	set nocount on

	declare @parent table (license_id int, keycode varchar(40), last_child_license_date datetime, last_child_license_id int, child_license_activations int)

	insert into @parent(license_id, keycode, last_child_license_date, last_child_license_id, child_license_activations)
	select l.license_id, 
			l.keycode,
		last_child_license_date = max(p.insert_date),
		last_child_license_id = max(p.child_license_id),
		child_license_activations = count(*)
	from license_parent p
	inner join license l
		on p.parent_license_id = l.license_id
	where parent_license_id = @license_id
	group by l.license_id, l.keycode

	select p.license_id, p.keycode, p.last_child_license_date, p.last_child_license_id, last_child_keycode = l.keycode, p.child_license_activations
	from @parent p
	left join license l
		on p.last_child_license_id = l.license_id



GO
