-- PROCEDURE: [dbo].[usp_license_select_license_seat_effective]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_license_seat_effective]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2016-01-07	cnovac		Initial creation
	2019-04-08	cnovac		Updated to just use effective object
	
	DESCRIPTION
	select license seat effective date and effective seats.  This feature is used when early renewal happens and you want see what seat count
    was within the billing procedures for excess usage or whatever other usage offerings we have in future.
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	declare @effective_table table (object_element_name varchar(50), object_element_value varchar(50), license_category_name varchar(50))

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into @effective_table (object_element_name, object_element_value, license_category_name)
	select 'license_seats', fn.effective_value, lc.license_category_name
	from fn_license_select_effective_object_table(@license_id, getdate()) fn
	inner join license_category lc on lc.license_category_id = fn.license_category_id
	where fn.object_element_name = 'license_seats'

	insert into @effective_table (object_element_name, object_element_value, license_category_name)
	select 'billing_day_of_month', fn.effective_value, lc.license_category_name
	from fn_license_select_effective_object_table(@license_id, getdate()) fn
	inner join license_category lc on lc.license_category_id = fn.license_category_id
	where fn.object_element_name = 'billing_day_of_month'

	insert into @effective_table (object_element_name, object_element_value, license_category_name)
	select 'license_attribute_license_value', lalv.license_attribute_license_value_description, lc.license_category_name
	from fn_license_select_effective_object_table(@license_id, getdate()) fn
	inner join license_category lc on lc.license_category_id = fn.license_category_id
	inner join license_attribute_license_value lalv on lalv.license_attribute_license_value = fn.effective_value
	where fn.object_element_name = 'license_attribute_license_value'

	select object_element_name, object_element_value, license_category_name
	from @effective_table
	order by object_element_name, license_category_name

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
