-- PROCEDURE: [dbo].[usp_license_select_license_seat_usage]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_license_seat_usage]

(
	@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2014-12-11	acoffel		Initial creation.

	DESCRIPTION
*/

as
	set nocount on	

			declare	@license_id int,
					@last_activity_date datetime,
					@license_seats int,
					@current_license_seats int,
					@current_seat_usage int,
					@last_over_usage int,
					@response_code int,
					@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select current seat count
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @keycode is not NULL
			begin 
				select @license_id = (select license_id from license where keycode = @keycode)	
				
				select @last_activity_date = max(activity_date) 
				from license_usage 
				where license_id = @license_id

				select @current_seat_usage = devices
				from license_usage 
				where license_id = @license_id and activity_date = @last_activity_date


			end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @keycode as keycode, @current_seat_usage as current_seat_usage, @license_id as license_id


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
