CREATE PROCEDURE [dbo].[usp_license_select_module_string_default] 

(@license_category_name varchar(10), @iso varchar(3) = NULL)

/*	
	DATE			AUTHOR		REMARKS
	2020-09-29		abelenkiy	Initial creation.
	2020-11-09		abelenkiy	Changed function to fn_license_module_license_category_key_value
	2024-09-03      lpraharsha  Added null for cart order id  as part of php requirement as part of ecom-5185 which is needed in fn_license_module_license_category_key_value.(pill sky-provisoning changes) 

