-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_sap_order_item]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_license_select_sap_order_item]
(
    @license_id INT,
    @effective_date DATETIME = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2022-06-16	gblandford	Initial creation.
							ALM-1512: adapted for SAP from usp_license_select_oracle_contract_line, 
							targets sap_order objects
	2022-10-18	gblandford	ALM-2734: Modified the output now that we have sap order data in production.
							- ensure we're not returning duplicate rows caused by multi-lines in order_item/sap_order_item
							- removed sap_order_item_id 
							- use effective_date and capability_expiration_date from order_item for start_date & end_date values
	2025-03-17  psatish		US-4404934 Return the start_date and end_date from the sap_order_item table 				

	DESCRIPTION
	Pulls 'contract' information for CSI. Respresented by sap_order, sap_order_item and sap_order_item_license objects
	

*/

AS
SET NOCOUNT ON;

BEGIN TRY

    DECLARE @response_code INT,
            @message VARCHAR(100);

    -------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1) select
    -------------------------------------------------------------------------------------------------------------------------------------------------------------------

	SELECT 
		DISTINCT
		
		--soi.sap_order_item_id,
		--soi.sap_item_number,
		soi.sap_order_status_id,
		sos.sap_order_status_name,
		--soi.order_item_id,

		soi.start_date AS start_date,
		soi.end_date AS end_date,

		--soi.start_date,
		--soi.end_date,
		--soi.insert_date,
		--soi.modified_date,
		i.effective_date,
		--i.capability_expiration_date,
		--lc.license_category_name,
		--so.sap_order_id,
		so.sap_order_number

    FROM dbo.sap_order_item_license soil
    INNER JOIN dbo.sap_order_item soi
        ON soi.sap_order_item_id = soil.sap_order_item_id
	INNER JOIN dbo.sap_order so 
		ON so.sap_order_id = soi.sap_order_id
    INNER JOIN dbo.sap_order_status sos
        ON sos.sap_order_status_id = soi.sap_order_status_id
    LEFT JOIN dbo.order_item i
        ON soi.order_item_id = i.order_item_id
    LEFT JOIN dbo.product_license_category plc
        ON plc.product_id = i.product_id
    LEFT JOIN dbo.license_category lc
        ON lc.license_category_id = plc.license_category_id

    WHERE soil.license_id = @license_id
          AND i.effective_date >= CASE
                                   WHEN @effective_date IS NOT NULL THEN
                                       @effective_date
                                   ELSE
                                       i.effective_date
                               END
    ORDER BY i.effective_date DESC;

	
END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'select failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_security_summary]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_security_summary]

(
	@license_key varchar(36) 
)

/*	
	DATE		AUTHOR		REMARKS
	2013-10-22	esmart		Initial creation
	2014-02-21	esmart		Correct logic for selecting devices from activity data

	DESCRIPTION
	
	--Scans
	--•	number_scans = sum(number_scans)
	--•	average_scan_time = avg(average_scan_time)
	--•	last_scan  = max(last_activity_date) – we do not currently receive last scan date so this is the best we can do.

	--Threats
	--•	threats_removed = sum(threats_removed) 
	--•	max_threats_removed = max(max_threats_removed)

	--System Optimizer
	--•	megabytes_cleaned = sum(megabytes_cleaned) 

	Report beginning = min(first_activity_date)
	Keycode: SACD-1234-1234-1234-1234
	Number of Devices Protected: 4
	Expiration date: 09/30/13

*/


AS
	set nocount on				

	declare	@license_id int,
			@keycode varchar(40),
			@keycode_alias varchar(40),
			@number_scans int, 
			@average_scan_time_seconds int,
			@first_activity_date datetime,
			@last_scan datetime,
			@threats_removed int,
			@max_threats_removed int,
			@megabytes_cleaned bigint,
			@number_devices int,
			@capability_expiration_date datetime,
			@number_accounts int,
			@serial_number varchar(19),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @keycode
	select @license_id = l.license_id, @keycode = l.keycode, @keycode_alias = a.keycode_alias
	from license l
	inner join license_key k
		on l.license_id = k.license_id
	left join license_keycode_alias a
		on l.license_id = a.license_id
	where k.license_key = @license_key

	-- 1.2) expiration 
	select @capability_expiration_date = capability_expiration_date
	from license_summary where license_id = @license_id

	-- 1.3) activity data
	select @number_scans = sum(number_scans), 
			@average_scan_time_seconds = avg(average_scan_time)/1000,
			@last_scan  = max(last_activity_date),
			@threats_removed = sum(threats_removed),
			@max_threats_removed = max(max_threats_removed),
			@megabytes_cleaned = sum(bytes_cleaned)/1000000,
			@first_activity_date = min(first_activity_date),
			@number_devices = count(*)
	from license_activity a
	where (keycode = @keycode or keycode = @keycode_alias) and last_activity_date >= dateadd(dd,-30,getdate())
	group by keycode
	
	-- 1.4) accounts
	select @number_accounts = count(*)
	from account_license al
	where al.license_id = @license_id

	-- 1.5) S2 subscription
	select @serial_number = serial_number
	from subscription
	where license_id = @license_id

	-- 1.5) return results
	select license_id = @license_id,
			keycode = @keycode, 
			keycode_dashed = dbo.fn_FormatKeycode(@keycode),
			keycode_alias = @keycode_alias,
			keycode_alias_dashed = dbo.fn_FormatKeycode(@keycode_alias),
			serial_number = @serial_number,
			first_activity_date = @first_activity_date,
			number_devices = @number_devices,
			capability_expiration_date = @capability_expiration_date,
			days_remaining = case when datediff(dd,getdate(),@capability_expiration_date) <= 0 then 0 else datediff(dd,getdate(),@capability_expiration_date) end,
			number_accounts = @number_accounts,
			number_scans = @number_scans, 
			average_scan_time_seconds = @average_scan_time_seconds, 
			last_scan = @last_scan, 
			threats_removed = @threats_removed, 
			max_threats_removed = @max_threats_removed, 
			megabytes_cleaned = @megabytes_cleaned

	end t
ry

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
