-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_select_swap_detail]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_select_swap_detail]
(
	@license_key varchar(36)
)

/*	
	DATE			AUTHOR		REMARKS
	2015-11-12		acoffel			Initial creation

	
	DESCRIPTION
	Call to action taken from license swap IPM. Swaps days if still a valid swap
*/

AS
	set nocount on

	declare @original_license_id int,
		@original_product_line_id int,
		@original_license_status_id int,
		@original_license_type_id int,
		@original_account_id int,
		@original_days_remaining int, 
		@original_distribution_class varchar(20),
		@original_capability_type_id int,
		@original_category_id int,
		@original_ar_status tinyint,
		@original_keycode varchar(40),
		@original_seats int,
		@original_category_description varchar(50),
		@original_license_category_name varchar(10), 
		@new_license_id int,
		@new_product_line_id int,
		@new_license_status_id int,
		@new_license_type_id int,
		@new_account_id int,
		@new_capability_type_id int,
		@new_category varchar(20),
		@new_days_remaining int, 
		@new_distribution_class varchar(20),
		@new_category_id int,
		@new_ar_status tinyint,
		@new_keycode varchar(40),
		@new_seats int,
		@new_category_description varchar(50),
		@new_license_category_name varchar(10),
		@license_swap_id int,
		@license_swap_status_id int,
		@transaction_date datetime,
		@system_user varchar(50),
		@response_code int,
		@message varchar(100),
		@effective_date datetime,
		@modified_by varchar(20)
	

	set @modified_by = suser_sname()
	set @transaction_date = getdate()
	set @system_user = @modified_by
		
begin try
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) verify swap is still record is ready to go
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--1.0) convert license_key to new_license_id
		if @license_key is not NULL 
			begin 
				select @new_license_id = l.license_id, @new_keycode = l.keycode from license_key k inner join license l on k.license_id = l.license_id where k.license_key = @license_key
			end

		--1.1) stop if key can't be converted to license_id
		if @new_license_id is null
			begin
				declare @swap_success table (swap_success int)
				set @message = 'new keycode not found'
				select swap_success from @swap_success
				return
			end

		--1.2) get license_swap_id 
		select @license_swap_id = license_swap_id, @original_license_id = original_license_id, @license_swap_status_id = license_swap_status_id from license_swap where new_license_id = @new_license_id --and license_swap_status_id = 1

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) Get license detail
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 2.0) get new license
		select @new_license_id = l.license_id,
			@new_product_line_id = l.product_line_id,
			@new_license_type_id = l.license_type_id,
			@new_days_remaining = case when lc.capability_activation_date is not NULL then datediff(dd,getdate(),lc.capability_expiration_date) else lc.capability_activation_days end,
			@new_license_status_id = l.license_status_id,
			@new_distribution_c
lass = dc.distribution_class,
			@new_category_id = cl.license_category_id,
			@new_ar_status = case when at.license_attribute_license_value = 1 then 1 
									when at.license_attribute_license_value in (2,3) then 2 
									else 0 end,
			@license_key = k.license_key,
			@new_keycode = l.keycode,
			@new_seats = s.license_seats,
			@new_category_description = ca.license_category_description,
			@new_license_category_name = case when ca.license_category_name = 'WSAV' and m.license_id is not NULL then 'GAMR' else ca.license_category_name end
		from license l
		inner join license_capability lc 
			on l.license_id = lc.license_id and lc.capability_id = 2
 		inner join license_category_license cl
			on l.license_id = cl.license_id 
		inner join license_category ca
			on cl.license_category_id = ca.license_category_id
		inner join license_seat s
			on l.license_id = s.license_id
		left join license_attribute_license at
			on l.license_id = at.license_id 
		inner join license_distribution_method_channel ldmc 
		   on l.license_distribution_method_id = ldmc.license_distribution_method_id
		inner join distribution_class dc
		   on ldmc.distribution_class_id = dc.distribution_class_id
		left join account_license al
			on l.license_id = al.license_id
		left join license_key k
			on l.license_id = k.license_id
		left join license_module_license m
			on l.license_id = m.license_id and m.license_module_id = 12
		where l.license_id = @new_license_id

		-- 2.1) get original license
		select @original_license_id = l.license_id,
			@original_product_line_id = l.product_line_id,
			@original_license_status_id = l.license_status_id,
			@original_license_type_id = l.license_type_id,
			@original_capability_type_id = lc.capability_type_id,
			@original_days_remaining = datediff(dd,getdate(),lc.capability_expiration_date),
			@original_distribution_class = dc.distribution_class,
			@original_category_id = cl.license_category_id,
			@original_account_id = al.license_id,
			@original_ar_status = case when at.license_attribute_license_value = 1 then 1 
									when at.license_attribute_license_value in (2,3) then 2 
									else 0 end,
			@original_keycode = l.keycode,
			@original_seats = s.license_seats,
			@original_category_description = ca.license_category_description,
			@original_license_category_name = ca.license_category_name,
			@original_license_category_name = case when ca.license_category_name = 'WSAV' and m.license_id is not NULL then 'GAMR' else ca.license_category_name end
		from license l
		inner join license_capability lc 
			on l.license_id = lc.license_id and lc.capability_id = 2
 		inner join license_category_license cl
			on l.license_id = cl.license_id 
		inner join license_category ca
			on cl.license_category_id = ca.license_category_id
		inner join license_seat s
			on l.license_id = s.license_id
		left join license_attribute_license at
			on l.license_id = at.license_id 
		inner join license_distribution_method_channel ldmc 
		   on l.license_distribution_method_id = ldmc.license_distribution_method_id
		inner join distribution_class dc
		   on ldmc.distribution_class_id = dc.distribution_class_id
		left join account_license al
			on l.license_id = al.license_id
		left join license_key k
			on l.license_id = k.license_id
		left join license_module_license m
			on l.license_id = m.license_id and m.license_module_id = 12
		where l.license_id = @original_license_id


		-- 2.2) do validation for pending swap
		if @license_swap_status_id = 1 
			and @original_distribution_class in ('Japan', 'Online', 'Retail', 'Other', 'Test', 'UK Retail', 'E-tail', 'Shelf') and @new_distribution_class in ('Japan', 'Online', 'Retail', 'Other', 'Test', 'UK Retail', 'E-tail', 'Shelf')
			and @original_product_line_id in (1,6,100,200) and @new_product_line_id in (1,6,100,200)
			and @original_license_category_name = @new_license_category_name
			and @original_account_id is NULL
			and @original_license_type_id = 1 and @new_license_type_id = 1
	
		and @original_days_remaining >= 1 and @original_days_remaining <= 90
			and @original_license_status_id = 1 and @new_license_status_id in (0,1)
			begin
				select @license_swap_status_id as license_swap_status_id, @new_keycode as new_keycode, @new_license_id as new_license_id, @new_ar_status as new_ar_status, @new_days_remaining as new_days_remaining, 
						@new_seats as new_seats, @new_category_description as new_category_description, @new_license_category_name as new_license_category_name,
						@original_keycode as original_keycode, @original_license_id as original_license_id, @original_ar_status as original_ar_status, @original_days_remaining as original_days_remaining, 
						@original_seats as original_seats, @original_category_description as original_category_description, @original_license_category_name as original_license_category_name, @license_swap_id as license_swap_id
			end


		-- 2.3) select data for processed swap
		if @license_swap_status_id = 2
			begin
				select @license_swap_status_id as license_swap_status_id, @new_keycode as new_keycode, @new_license_id as new_license_id, @new_ar_status as new_ar_status, @new_days_remaining as new_days_remaining, 
						@new_seats as new_seats, @new_category_description as new_category_description, @new_license_category_name as new_license_category_name,
						@original_keycode as original_keycode, @original_license_id as original_license_id, @original_ar_status as original_ar_status, @original_days_remaining as original_days_remaining, 
						@original_seats as original_seats, @original_category_description as original_category_description, @original_license_category_name as original_license_category_name, @license_swap_id as license_swap_id
			end

		--2.4) stop if key can't be converted to license_id
		if @new_keycode is null
			begin
				set @response_code = -200
				set @message = 'Swap Select Failed'
				return
			end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select license swap data failed @keycode = ' + isnull(@original_keycode,'') + ' and @new_keycode = ' +  isnull(@new_keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_bulk_load_file]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_service_bulk_load_file]
(
    @keycode_list_json NVARCHAR(MAX),
    @insert_by NVARCHAR(50) = NULL
)

-- =============================================
-- DATE        AUTHOR        REMARKS
--2025-10-20  vgangatharan   Insert data into bulkload file --https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4539952
-- =============================================

AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @filename NVARCHAR(500),
            @license_service_type_name NVARCHAR(50) = N'license_disable',
            @license_service_type_id INT,
            @file_id INT,
            @DBName NVARCHAR(128);
    DECLARE @License_keycode TABLE
    (
        keycode NVARCHAR(40)
    );
    BEGIN TRY
        -- Default insert_by if null
        IF @insert_by IS NULL
            SET @insert_by = SUSER_SNAME();
        -- Extract filename
        SET @filename = JSON_VALUE(@keycode_list_json, '$.filename');
        -- Parse keycodes from JSON array
        INSERT INTO @License_keycode
        (
            keycode
        )
        SELECT value
        FROM OPENJSON(@keycode_list_json, '$.keycode');

        -- Get service type ID
        SELECT @license_service_type_id = license_service_type_id
        FROM license_service_type
        WHERE license_service_type_name = @license_service_type_name;

        BEGIN TRANSACTION;
        -- Insert into bulk_load_file
        INSERT INTO license_service_bulk_load_file
        (
            file_name,
            insert_by,
            insert_date,
            [load_status]
        )
        VALUES
        (@filename, @insert_by, GETDATE(), 'Pending');
        SET @file_id = SCOPE_IDENTITY();
        -- Insert data into license_service_bulk_update
        INSERT INTO license_service_bulk_update
        (
            license_id,
            license_service_type_id,
            expiration_date,
            modified_by,
            license_service_bulk_load_file_id
        )
        SELECT l.license_id,
               @license_service_type_id,
               GETDATE(),
               @insert_by,
               @file_id
        FROM license l
            JOIN @License_keycode lk
                ON l.keycode = lk.keycode;
        COMMIT TRANSACTION;
        SELECT 'Insert successful.' AS message;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @DBName = DB_NAME();
        EXEC usp_LogError @ErrorDB = @DBName;
        SELECT ERROR_MESSAGE() AS message;
    END CATCH;
END;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_insert_license]
-- =============================================================================
CREATE procedure [dbo].[usp_license_service_insert_license]


(
		@license_service_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2017-10-19	esmart		Initial creation.
	2019-05-29	acoffel		Bright Cloud support
	2019-06-21	esmart		add @company_id_input
	2019-07-19	cnovac		Added logic to write to license_contract
	2019-09-18	esmart		Add sky_api_license and fix mapping to license_distribution_method
	2019-10-28	esmart		Fixes for cart release
	2019-11-08	abelenkiy	Added support for license_parent effective_object (section 3.1)
	2020-02-13	esmart		Modify GSM registration insert to only include SAEP (3.6)
	2020-03-05	esmart		Add @customer_id output to return new customer_id for registration and license_key.salesforce_license_id
	2020-05-28	cnovac		Added call to write to effective object for seats
	2020-06-24	wbarton		2.7 - vault now uses usp_license_insert_external_reference_vault to insert when applicable. Supporting an optional vault array in @license_service_json for multiple vaults, and backward compatibility for singular vault_id.
	2020-08-03	wbarton		Hotfix in 2.7.1 to allow @country_id to be set by description or iso
	2020-08-20	esmart		Add license_storage
	2020-09-15	abelenkiy	Update usp_customer_insert_customer_service call to figure out company_type_name from company_type_id if provided (section 2.1); minor bug fixes
	2020-10-14	cnovac		added logic for storage_gb
	2020-12-14	cnovac		Extracted product_platform_id from license_category JSON array Story LAGER-2446 and include it in JSON array to pass on to license_insert_effective_object
	2021-01-27	cnovac		added section 1.10 to create license for CB if skyrise call fails as a backup
	2021-10-22  psatish		Bybass the Sky Update logic and usp_license_insert_external_reference_vault for backfilling the Netsuite Contracts
	2021-11-01	abelenkiy	Changed section 2.4 to exclude record being written to license_storage if storage_gb for product = 0
	2022-01-06	gblandford	SMCI-6215 - Add retention_term
	2022-03-18	psatish		Added new license distribution method i.e. NSBF for Contract backfill
	2022-29-11  psatish		ALM# 3732 Removed the logic to block the migrated licenses into sky_api_license
	2023-03-08  psatish     ECOM-1080 Extract the vault_id from the JSON
	2023-04-05  psatish		ECOM-899 Modified the section: 1.3.3 to update the storage_gb from cart_order_item table
	2023-06-07  jberry		ECOM-1169 Added support for CBEP capacity products to section 1.3.3
	2024-10-09  vsingh8		ECOM-6025: 1. Added support for PILLR licenses for msp registration to section 3.6) MSP registration
								2. Also, used app_config to store the license categories for which msp registration is required.
								3. Added schema to the objects.
	2025-10-27	psatish		D-5045328 Modified section 3.5 to insert ecom-created keycodes into the prevx_update_license
	2026-04-14  thejashwini 5096725- insert new consumer licenses into license_active_seats as a part of seat count enforcement

	DESCRIPTION
	This procedure is used to setup new licenses in ECOM.
	It configures the license modules, seats, capabilities, etc. for the new licenses.

	DEPENDENCIES
	Used by [dbo].[usp_license_service_insert_service]
*/

AS
	SET NOCOUNT ON				
	BEGIN TRY

	DECLARE @keycode VARCHAR(40), 
			@parent_keycode VARCHAR(40), 
			@parent_license_id INT,
			@account_name VARCHAR(100), 
			@console_site_name NVARCHAR(255),
			@license_category NVARCHAR(MAX), 
			@cart_order_item NVARCHAR(MAX), 
			@partner NVARCHAR(MAX),
			@sfdc NVARCHAR(MAX),
			@license_distribution_method_code CHAR(4), 
			@license_distribution_method_id INT,
			@product_line_id INT,
			@license_id INT,
			@license_status_id INT,
			@license_type_id INT,
			@license_keycode_type_id INT,
			@license_
seats INT,
			@oem_id VARCHAR(255),
			@device_id VARCHAR(255),
			@url_link VARCHAR(500),
			@customer_id INT,
			@insert_date DATETIME,
			@insert_by VARCHAR(20),
			@license_service_json NVARCHAR(MAX), 
			@service_type VARCHAR(20),
			@response_code INT,
			@message VARCHAR(100),
			@ecom_create_license TINYINT
			

	DECLARE @customer_email VARCHAR(100),
			@first_name NVARCHAR(225),
			@last_name NVARCHAR(225),
			@company_name NVARCHAR(255),
			@company_type_name VARCHAR(20),
			@phone_number VARCHAR(64),
			@address_1 NVARCHAR(255),
			@address_2 NVARCHAR(255),
			@city NVARCHAR(130),
			@state NVARCHAR(2),
			@postal_code NVARCHAR(32),
			@country VARCHAR(75),
			@vendor_id INT,
			@vendor_customer_code VARCHAR(100),
			@partner_id INT,
			@opt_in INT,
			@salesforce_account_id CHAR(18),
			@salesforce_contact_id CHAR(18),
			@salesforce_license_id char(18),
			@transaction_user varchar(20),
			@update_attempts int,
			@customer_id_input int,
			@company_id_input int,
			@license_contract_json varchar(max),
			@license_parent_json nvarchar(max),
			@trial int,
			@license_category_id tinyint,
			@process_date datetime,
			@vault_json nvarchar(max),
			@license_effective_object_json varchar(max),
			@application varchar(50),
			@product_id int,
			@years tinyint

	declare @license_category_table table (license_category_name varchar(10),license_seats int, storage_gb int,days int,start_date datetime,expiration_date datetime,category_type_name varchar(50),item_hierarchy_id tinyint,vault_id int,vault_array nvarchar(max),usage_pricing_model_id tinyint,retention_model_id tinyint,retention_term tinyint, product_platform_id tinyint)
	declare @parent_license_table table (license_id int, license_category_name varchar(10),license_seats int,storage_gb int,license_keycode_type_id int,license_attribute_license_value int,start_date datetime,expiration_date datetime,category_type_name varchar(50),item_hierarchy_id tinyint, license_status_id int)
	declare @keycodetable table (keycode varchar(50))
	declare @MSP_REGISTRATION_LICENSE_CATEGORIES table (
		license_category_id tinyint
	);
    insert into @MSP_REGISTRATION_LICENSE_CATEGORIES
	select lc.license_category_id
	from [dbo].[fn_app_config_select_key_values]('MSP_REGISTRATION_LICENSE_CATEGORIES', 'LICENSE_SERVICE') f
	join [dbo].[license_category] lc on f.[key] = lc.license_category_name;

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select @insert_date = getdate(), @license_status_id = 1
		
		-- 1.1) @license_service_json
		select @license_service_json = license_service_json
		from dbo.license_service_json 
		where license_service_id = @license_service_id

		select @service_type = case when license_service_type_name like 'site%' then 'site' else 'license' end
		from dbo.license_service s
		inner join dbo.license_service_type t 
			on t.license_service_type_id = s.license_service_type_id
		where s.license_service_id = @license_service_id
	
		-- 1.2) parse json
		select @keycode = keycode,
				@parent_keycode = parent_keycode,
				@account_name = account_name,
				@console_site_name = console_site_name,
				@license_category = license_category,
				@cart_order_item = cart_order_item,
				@partner = partner,
				@sfdc = sfdc,
				@license_distribution_method_code = case when license_distribution_method_code = '' then null else license_distribution_method_code end,
				@license_keycode_type_id = license_keycode_type_id,
				@oem_id = oem_id,
				@device_id = device_id,
				@url_link = url_link,
				@application = application,
				@ecom_create_license =ecom_create_license
		from openjson(@license_se
rvice_json)
		with (keycode varchar(40) '$.keycode',
			parent_keycode varchar(40) '$.parent_keycode',
			account_name varchar(20) '$.account_name',
			console_site_name varchar(20) '$.site_name',
			license_distribution_method_code char(4) '$.license_distribution_method_code',
			license_keycode_type_id int '$.license_keycode_type_id',
			oem_id varchar(255) '$.oem_id',
			device_id varchar(255) '$.device_id',
			url_link varchar(500) '$.url_link',
			application varchar(50) '$.application',
			license_category nvarchar(max) as json,
			cart_order_item nvarchar(max) as json,
			partner nvarchar(max) as json,
			sfdc nvarchar(max) as JSON,
			ecom_create_license TINYINT) 
	
			-- 1.2.1) @parent_license_id
			if @parent_keycode is not null and @parent_keycode <> ''
				begin
					select @parent_license_id = license_id from dbo.license where keycode = @parent_keycode
				end

			-- 1.2.2) @insert_by
			if @account_name is not null
				begin
				select @insert_by = @account_name
				end
			else
				begin
				select @insert_by = @service_type
				end

		-- 1.3) @license_category_table
		insert into @license_category_table(license_category_name,license_seats,storage_gb,days,start_date,expiration_date,category_type_name,item_hierarchy_id,usage_pricing_model_id,retention_model_id,retention_term, product_platform_id,vault_array)
		select license_category_name,license_seats,storage_gb,days,start_date,expiration_date,category_type_name,item_hierarchy_id,usage_pricing_model_id,retention_model_id,retention_term,product_platform_id,vault_id
		from openjson(@license_category)
		with (license_category_name varchar(10) '$.license_category_name',
					license_seats int '$.license_seats',
					storage_gb int '$.storage_gb',
					days int '$.days',
					start_date datetime '$.start_date',
					expiration_date datetime '$.expiration_date',
					category_type_name varchar(50) '$.category_type_name',
					item_hierarchy_id tinyint '$.item_hierarchy_id',
					usage_pricing_model_id tinyint '$.usage_pricing_model_id',
					retention_model_id tinyint '$.retention_model_id',
					retention_term tinyint '$.retention_term',
					product_platform_id tinyint '$.product_platform_id',
					vault_id NVARCHAR(MAX) AS JSON)

		where license_category_name is not null

		-- 1.3.1) @cart_order_item
		declare @cart_order_item_table table (cart_order_item_id int)

		insert into @cart_order_item_table(cart_order_item_id)
		select cart_order_item_id
		from openjson(@cart_order_item)
		with (cart_order_item_id int '$.cart_order_item_id')

		-- 1.3.2) update days for trial
		update @license_category_table
		SET days = case
						when expiration_date is null and days is null then 30
					end
		where category_type_name = 'trial'

		-- 1.3.3) update storage for storage products
		--Get the storage_gb from Cart_order_item table if exists
		update c
		set c.storage_gb = (select isnull
								(
									(select distinct coi.storage_gb
									from @cart_order_item_table coit
									inner join dbo.cart_order_item coi 
										on coi.cart_order_item_id = coit.cart_order_item_id
									inner join dbo.sap_material_product_mapping pd
										on pd.sap_material_number = coi.sap_material_number
									inner join dbo.license_category ct
										on ct.license_category_id = pd.license_category_id
									where ct.license_category_name=c.license_category_name									)
									,dbo.fn_get_item_storage_gb(c.license_seats, c.license_category_name, DEFAULT, c.usage_pricing_model_id, DEFAULT, DEFAULT)
								)
							)
		from @license_category_table c
		where c.storage_gb is null        

		-- 1.3.4) update storage for storage products if still NULL (this would be for consumer products)
		update @license_category_table
		set storage_gb = dbo.fn_get_item_storage_gb(coi.quantity, default, coi.product_id, default, default, default)
		from @cart_order_item_table coit
		inner join dbo.car
t_order_item coi on coi.cart_order_item_id = coit.cart_order_item_id
		where [@license_category_table].storage_gb is null

		-- 1.3.5) default the product_platform_id to 1 where it's not passed into JSON but needed to set for certain categories
		update lct
		set lct.product_platform_id = 1
		from @license_category_table lct
		inner join dbo.license_category lc on lc.license_category_name = lct.license_category_name
		inner join dbo.partner_product_platform ppp on ppp.license_category_id = lc.license_category_id
		where lct.product_platform_id is null

		-- 1.4) @partner_id
		select @partner_id = partner_id
		from openjson(@partner)
		with (partner_id int '$.partner_id')

		-- 1.5) @parent_license_table
		if @parent_license_id is not null
			begin 
				insert @parent_license_table(license_id,license_category_name,license_seats,storage_gb,license_keycode_type_id,license_attribute_license_value,start_date,expiration_date,category_type_name,item_hierarchy_id,license_status_id)		
				select license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id, license_status_id
				from dbo.fn_license_select_license_profile(@parent_license_id)
				--where item_hierarchy_id = 1
			end

		-- 1.5) license_category_product_line
		select @product_line_id = lcp.product_line_id, @license_category_id = lc.license_category_id, @trial = case when lct.category_type_name = 'trial' then 1 else 0 end
		from @license_category_table lct
		inner join dbo.license_category lc
			on lc.license_category_name = lct.license_category_name
		inner join dbo.license_category_product_line lcp
			on lcp.license_category_id = lc.license_category_id
		where item_hierarchy_id = 1 and lcp.language_code = 'EN' and lcp.location_code = 'USA'

		-- 1.6) @license_type_id, @license_keycode_type_id
		if @license_keycode_type_id is null
			begin
				select @license_keycode_type_id = 1
			end

			-- 1.6.1) @license_type_id
			select @license_type_id = case
										when @product_line_id in (300,55) and @license_keycode_type_id = 1 then 4
										when @product_line_id in (300,55) and @license_keycode_type_id = 3 then 2
										else 1
									end

		-- 1.7) @license_distribution_method_id
		if @license_distribution_method_code is null and @parent_keycode is not null
			begin
				select @license_distribution_method_id = license_distribution_method_id
				from license
				where keycode = @parent_keycode
			end
		else
			begin
				select	@license_distribution_method_id = license_distribution_method_id
				from dbo.license_distribution_method
				where license_distribution_method_code = @license_distribution_method_code
			end

		-- 1.7.1) usp_product_select_license_distribution_method
		if @license_distribution_method_id is null
				begin
					exec dbo.usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
				end

		-- 1.8) start and end dates
		if @parent_license_id is not null
			begin
				update @license_category_table
				set start_date = case 
										when l.start_date is null then convert(date,getdate())
										else l.start_date
									end,
						expiration_date = case
												when l.expiration_date is null and l.category_type_name = 'full' and p.expiration_date is not null then p.expiration_date
												when l.expiration_date is null and l.category_type_name = 'trial' and p.expiration_date < dateadd(dd,l.days,isnull(l.start_date,convert(date,getdate()))) then p.expiration_date
												when l.expiration_date is null and l.category_type_name = 'trial' and p.expiration_date >= dateadd(dd,l.days,isnull(l.start_date,convert(date,getdate()))) then dateadd(dd,l.days,isnull(l.start_date,convert(date,getdate())))
										end
				from @license_category_table l

				left join @parent_license_table p
					on p.license_category_name = l.license_category_name
			end

		-- 1.9) @license_distribution_method_id

		-- 1.9.1) license_distribution_method_id for partner
		if @license_distribution_method_id is null
			begin
				select @license_distribution_method_id = pm.license_distribution_method_id
				from dbo.partner_license_distribution_method pm
				where pm.partner_id = @partner_id
			end

		-- 1.9.2) get disti based on product dimensions
		if @license_distribution_method_id is null
			begin
				select @license_category_id = lc.license_category_id, @trial = case when l.category_type_name = 'full' then 0 else 1 end
				from @license_category_table l
				inner join dbo.license_category lc
					on l.license_category_name = lc.license_category_name
				where l.item_hierarchy_id = 1

				exec dbo.usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
			end

	-- 1.9) @license_distribution_method_id

		-- 1.9.1) license_distribution_method_id for partner
		if @license_distribution_method_id is null
			begin
				select @license_distribution_method_id = pm.license_distribution_method_id
				from dbo.partner_license_distribution_method pm
				where pm.partner_id = @partner_id
			end

		-- 1.9.2) get disti based on product dimensions
		if @license_distribution_method_id is null
			begin
				select @license_category_id = lc.license_category_id, @trial = case when l.category_type_name = 'full' then 0 else 1 end
				from @license_category_table l
				inner join dbo.license_category lc
					on l.license_category_name = lc.license_category_name
				where l.item_hierarchy_id = 1

				exec dbo.usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
			end

		if @license_distribution_method_code is null and @parent_keycode is not null
			begin
				select @license_distribution_method_id = license_distribution_method_id
				from dbo.license
				where keycode = @parent_keycode
			end
		else
			begin
				select	@license_distribution_method_id = license_distribution_method_id
				from dbo.license_distribution_method
				where license_distribution_method_code = @license_distribution_method_code
			end

		-- 1.10) look to see if keycode passed in is empty for CB. This is a backup if sky call fails to retrieve one
		if @application = 'Cleverbridge' and nullif(ltrim(rtrim(@keycode)), '') is null
		begin
			select @license_seats = iif(lc.license_category_id < 200, lct.license_seats, 1), --for consumer use seats passed in, else default to 1 for business
				   @license_category_id = lc.license_category_id,
				   @years = datediff(year, lct.start_date, lct.expiration_date)
			from @license_category_table lct
			inner join dbo.license_category lc on lc.license_category_name = lct.license_category_name

			select @product_id = product_id
			from dbo.cb_product_mapping
			where product_type_id = 1 --we only want new product
			and is_included_in_url = 1 --weed out cd's
			and license_category_id = @license_category_id
			and seats = @license_seats
			and years = @years

			if @@ROWCOUNT = 1
			begin
				insert into @keycodetable(keycode)			
				exec dbo.usp_license_insert_license_service @product_id = @product_id, @license_distribution_method_id = @license_distribution_method_id, @quantity = 1, @start_date = null, @end_date = null, @months = null, @external_keycode = null, @order_item_id = null, @trial_registration_id = null, @only_create_keycode = 1

				select @keycode = keycode
				from @keycodetable

				select @license_service_json = json_modify(@license_service_json, '$.keycode', @keycode)

				update dbo.license_service_json
				set license_service_json = @license_service_json
				where license_service_id = @license_service_
id
			end
		end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) customer
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) customer data 
	select @customer_email = customer_email,
			@first_name = first_name,
			@last_name = last_name,
			@company_name = company_name,
			@company_type_name = company_type_name,
			@phone_number = phone_number,
			@address_1 = address_1,
			@address_2 = address_2,
			@city = city,
			@state = state,
			@postal_code = postal_code,
			@country = country,
			@vendor_id = vendor_id,
			@vendor_customer_code = vendor_customer_code,
			@partner_id = partner_id,
			@opt_in = opt_in,
			@salesforce_account_id = salesforce_account_id,
			@salesforce_contact_id = salesforce_contact_id
	from openjson(@license_service_json)
	with (customer_email varchar(100) '$.customer.customer_email',
			first_name nvarchar(225) '$.customer.first_name',
			last_name nvarchar(225) '$.customer.last_name',
			company_name nvarchar(255) '$.customer.company_name',
			company_type_name varchar(20) '$.customer.company_type_name',
			phone_number varchar(64) '$.customer.phone_number',
			address_1 nvarchar(255) '$.customer.address_1',
			address_2 nvarchar(255) '$.customer.address_2',
			city nvarchar(130) '$.customer.city',
			state nvarchar(2) '$.customer.state',
			postal_code nvarchar(32) '$.customer.postal_code',
			country varchar(75) '$.customer.country',
			vendor_id int '$.customer.vendor_id',
			vendor_customer_code varchar(100) '$.customer.vendor_customer_code',
			partner_id int '$.customer.partner_id',
			opt_in int '$.customer.opt_in',
			salesforce_account_id char(18) '$.customer.salesforce_account_id',
			salesforce_contact_id char(18) '$.customer.salesforce_contact_id',
			transaction_user varchar(20) '$.customer.transaction_user')

		if @customer_email is null and @vendor_customer_code is null
			begin
				select @vendor_customer_code = partner_account_code
				from openjson(@partner)
				with (partner_account_code varchar(100) '$.partner_account_code')
			end

		if @customer_email is not null or @vendor_customer_code is not null
			begin
				exec dbo.usp_customer_insert_customer_service @customer_email, @first_name, @last_name, @company_name, @company_type_name, @phone_number, @address_1, @address_2, @city, @state, @postal_code, @country, @vendor_id, @vendor_customer_code, @partner_id, @opt_in, @salesforce_account_id, @salesforce_contact_id, @insert_by, @customer_id_input, @company_id_input, @customer_id output
			end
		
		--select customer_id = @customer_id
		--return
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert license data
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) license
		insert into dbo.license(keycode,customer_id,product_line_id,license_status_id,license_type_id,license_distribution_method_id,license_keycode_type_id,insert_date,insert_by,modified_date,modified_by)
		select @keycode, @customer_id, @product_line_id, @license_status_id, @license_type_id, @license_distribution_method_id,@license_keycode_type_id,@insert_date,@insert_by,@insert_date,@insert_by

		select @license_id = scope_identity()

		-- 2.2) license_category_license
		insert into dbo.license_category_license(license_id,license_category_id,start_date,end_date,last_modified_date,last_modified_by)
		select license_id = @license_id, license_category_id, t.start_date, t.expiration_date, @insert_date, @insert_by
		from @license_category_table t
		inner join dbo.
license_category lc
			on lc.license_category_name = t.license_category_name
		where t.item_hierarchy_id = 1

		-- 2.3) license_capability
		insert into dbo.license_capability(license_id,capability_id,capability_type_id,capability_activation_days,capability_activation_date,capability_expiration_date,insert_date,insert_by,modified_date,modified_by)
		select license_id = @license_id, lcc.capability_id, ct.capability_type_id, capability_activation_days = datediff(dd,t.start_date,t.expiration_date), t.start_date, t.expiration_date, @insert_date, @insert_by, @insert_date, @insert_by
		from @license_category_table t
		inner join dbo.license_category lc
			on lc.license_category_name = t.license_category_name
		inner join dbo.license_category_capability lcc
			on lcc.license_category_id = lc.license_category_id
		inner join dbo.capability_type ct
			on t.category_type_name = ct.capability_type_description
		where t.item_hierarchy_id = 1

		-- 2.4) license_seat
		insert into dbo.license_seat(license_id,license_seats,start_date,end_date,insert_date,insert_by,modified_date,modified_by)
		select license_id = @license_id, license_seats, start_date, expiration_date, @insert_date, @insert_by, @insert_date, @insert_by
		from @license_category_table
		where item_hierarchy_id = 1
		
		--license_active_seats
		IF (@product_line_id NOT IN (55, 300))
			BEGIN
				INSERT INTO dbo.license_active_seats (license_id, start_date, end_date, consumed_seats)
				SELECT @license_id,start_date,expiration_date,0
				FROM @license_category_table t
				WHERE item_hierarchy_id = 1
				AND NOT EXISTS (
					SELECT 1 FROM dbo.license_active_seats las WHERE las.license_id = @license_id
					);
			END

		-- 2.4) license_storage
		insert into dbo.license_storage(license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date,modified_by)
		select license_id = @license_id, storage_gb, start_date, expiration_date, @insert_date, @insert_by, @insert_date, @insert_by
		from @license_category_table
		where item_hierarchy_id = 1
		and nullif(storage_gb, 0) is not null
		and @product_line_id not in (55, 300) --only do for consumer since we are saving for business down below in effective object
	
		-- 2.5) license_module_license
		insert into dbo.license_module_license(license_id,license_module_id,license_module_type_id,start_date,end_date,license_status_id,last_modified_date,last_modified_by,module_seats)
		select @license_id, lm.license_module_id, mt.license_module_type_id, l.start_date, l.expiration_date, @license_status_id, @insert_date, @insert_by, l.license_seats
		from @license_category_table l
		inner join dbo.license_category lc
			on lc.license_category_name = l.license_category_name
		inner join dbo.license_module_category lmc
			on lmc.license_category_id = lc.license_category_id
		inner join dbo.license_module lm
			on lm.license_module_id = lmc.license_module_id
		inner join dbo.license_module_type mt
			on l.category_type_name = mt.license_module_type_name
		where lm.license_module_class_id = case when @service_type = 'site' then 1 else 3 end and l.item_hierarchy_id = 2
		
		-- 2.6) license_key

		-- 2.6.1) @salesforce_license_id
		select @salesforce_license_id = json_value(@sfdc,'$.salesforce_license_id')

		-- 2.6.2) license
		insert into dbo.license_key (license_id, salesforce_license_id)
		select @license_id, @salesforce_license_id

		-- 2.7) vault
		--Build up a JSON object for any license categories in @license_category_table that require vault provisioning/maintenance
		--Doing this for trial categories. For full categories, usp_license_insert_external_reference_vault is called in license management where we have vault_id(s) explicitly supplied or we have country from the customer's address
		select @vault_json = (
			select distinct @license_id as license_id, @country as country, lc.license_category_id as [license_category.license_catego
ry_id], l.vault_id as [license_category.vault_id], json_query(l.vault_array) as [license_category.vault]
			from @license_category_table l
				inner join dbo.license_category lc
					on lc.license_category_name = l.license_category_name
				inner join dbo.vault_license_category v

					on v.license_category_id = lc.license_category_id
				where l.category_type_name = 'trial'
			for json path
		)
		
		--Call usp_license_insert_external_reference_vault if @vault_json exists. If vault_ids have not been set via license_service_json, defaulting will take place via this procedure.
		if @vault_json is not null and not exists(select 1 from dbo.license_distribution_method dm inner join dbo.license lc on lc.license_distribution_method_id = dm.license_distribution_method_id
													where lc.license_id=@license_id and license_distribution_method_code='NSBF')
			begin
				exec dbo.usp_license_insert_external_reference_vault @license_external_reference_vault_json = @vault_json, @license_service_type_name = @service_type
			end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) extended data
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) license_parent
	if @parent_license_id is not null
		begin
			select @license_parent_json = ( select @license_id as child_license_id, lc.license_category_id, @parent_license_id as parent_license_id, lct.start_date as effective_start_date, @license_service_id as license_service_id 
											from @license_category_table lct
												inner join dbo.license_category lc on lc.license_category_name = lct.license_category_name
											for json path)  

			if @license_parent_json is not null
				exec dbo.usp_license_insert_license_parent
					@license_parent_json = @license_parent_json,
					@license_effective_source_caller = 'usp_license_service_insert_license'

		end


	-- 3.2) console_site
	if @console_site_name is not null
		begin
			insert into dbo.console_site(console_site_name,license_id,insert_date,modified_date) 
			values(@console_site_name,@license_id,@insert_date,@insert_date)
		end	
	
	-- 3.3) From [usp_license_insert_license_service] 2.2.14) set parent as fixed expiration date 
			if @license_keycode_type_id = 3
				begin
				insert into dbo.license_feature_license(license_id,license_feature_id) values(@license_id,8)
				end
                
	-- 3.4) insert cisco license
		if (select license_category_name from @license_category_table where item_hierarchy_id = 1) = 'BRTC'
			begin 
				insert into dbo.cisco_license (license_id, oem_id, device_id, url_link, insert_date, insert_by)
				select @license_id, @oem_id, @device_id, @url_link, getdate(), system_user
			end
  
	-- 3.5) insert ecom-created keycodes into prevx_update_license else sky_api_license
		IF @ecom_create_license = 1
		BEGIN
			INSERT INTO dbo.prevx_update_license
			(
				license_id
			)
			VALUES
			(@license_id -- license_id - int
			)
		END
		ELSE
		BEGIN
			INSERT INTO dbo.sky_api_license
			(
				license_id
			)
			SELECT l.license_id
			FROM dbo.license l
				LEFT JOIN dbo.sky_api_license a
					ON l.license_id = a.license_id
			WHERE l.license_id = @license_id
		END
			
	-- 3.6) MSP registration
       if @license_type_id = 2 and @product_line_id in (300) and
		exists (select 1 from @MSP_REGISTRATION_LICENSE_CATEGORIES where license_category_id = @license_category_id)
		begin
			declare @sky_template_id tinyint
			select @sky_template_id = sky_template_id from dbo.sky_template where sky_template_name = 'msp_registration'

			select @process_date = getdate()

			exec [dbo].[usp_sky_insert_update] @license_id, @sky_template_id, @process_date
		end

	-----------------------------------
--------------------------------------------------------------------------------------------------------------------------------
	-- 4.) cart_order_item
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @cart_order_item is not null	
		begin 
		insert into dbo.cart_order_item_license (cart_order_item_id, keycode, insert_date, insert_by, modified_date, modified_by, cart_order_status_id)
		select i.cart_order_item_id, @keycode, @insert_date, @insert_by, @insert_date, @insert_by, 1
		from @cart_order_item_table i
		--left join cart_order_item_license il
		--	on il.cart_order_item_id = i.cart_order_item_id
		--where il.cart_order_item_license_id is null
		

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) update license_service
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 5.1) archive
	insert into dbo.license_service_archive(license_service_id, license_service_type_id, license_service_status_id, insert_date)
	select license_service_id, license_service_type_id, license_service_status_id, insert_date
	from dbo.license_service
	where license_service_id = @license_service_id

	-- 5.2) delete service record
	delete from dbo.license_service
	where license_service_id = @license_service_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.)  License Contract call
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--build up the JSON now based on data in @license_contract_object only for business licenses
	select @license_contract_json = (
	select license_id = @license_id, license_category_id = lc.license_category_id, license_category_type_id = ct.capability_type_id, license_start_date = lct.start_date, license_end_date = lct.expiration_date, 
           license_service_id = @license_service_id, originating_license_contract_id = fn.license_contract_id
	from @license_category_table lct
	inner join dbo.license_category lc on lc.license_category_name = lct.license_category_name
	inner join dbo.capability_type ct on ct.capability_type_description = lct.category_type_name
	outer apply dbo.fn_license_select_license_contract_table(@license_id, lc.license_category_id, 'max_row') fn
	where @product_line_id in (55, 300)
	for json path)

	--if data exists, call the insert now
	if @license_contract_json is not null
	begin
		exec dbo.usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_service_insert_license'
	end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 7.0 ) effective object call
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--build up the JSON now based on data in @license_contract_object only for business licenses
	set @license_effective_object_json = null
	select @license_effective_object_json = (
	select license_id = @license_id, license_category_id = 
			lc.license_category_id,
			license_seats = lct.license_seats,
			storage_gb = lct.storage_gb,
			product_platform_id = lct.product_platform_id,
			effective_start_date = l
ct.start_date,
			license_service_id = @license_service_id
	from @license_category_table lct
	inner join dbo.license_category lc on lc.license_category_name = lct.license_category_name
	where @product_line_id in (55, 300)
	for json path)

	--if data exists, call the insert now
	if @license_effective_object_json is not null
	begin
		exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_service_insert_license'
	end

end try

begin catch
	
	if @update_attempts = 30
	-- 4.1) move to failure when attempted 5
		begin
			insert into dbo.license_service_failure(license_service_id,license_service_type_id,license_service_status_id, insert_date)
			select license_service_id,license_service_type_id,license_service_status_id, insert_date
			from dbo.license_service
			where license_service_id = @license_service_id

			delete from dbo.license_service
			where license_service_id = @license_service_id
		end
	else
	-- 4.2) update process_date and update_attempts
		begin
			update dbo.license_service set process_date = dateadd(ss,30,getdate()), update_attempts = update_attempts + 1 where license_service_id = @license_service_id
		end


	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec dbo.usp_LogError @ErrorDB = @DBName

end catch; 



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_insert_service]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_service_insert_service]

(
	@license_service_type_name varchar(50),
	@service_json nvarchar(max) = null,
	@return_license_service_id bit = 1
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2015-04-03	esmart		Make @company_name nvarchar(255)
	2015-05-01	esmart		Add process_type
	2016-05-25	esmart		Include license_service_id in result
	2016-06-15	cnovac		Updated throughout for CB implementation using new json variable
	2017-03-21	esmart		SDNS site creation
	2017-08-31	esmart		license_service_json
	2017-11-15	esmart		site_create
	2019-03-22	cnovac		added back in @return_license_service_id = 1 which was not implemented on code push on 3/6/2019
	2020-03-18	esmart		remove redundent @license_service_id result set
	2020-11-11	abelenkiy	added subscription_create call (section 3.1)
	2021-01-29	cnovac		updated small bug in section 3.1 to add else if

	DESCRIPTION
	Insert license_service
*/

as

begin try

	set nocount on				

	declare @keycode varchar(40),
			@license_id int, 
			@license_type_id int,
			@license_service_type_id tinyint, 
			@license_service_status_id tinyint,
			@license_service_id int,
			@process_type varchar(20),
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert license service records
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) empty json
	if @service_json = '[]'
		begin
		select @response_code = -100, @message = 'Empty JSON'
		return
		end

	-- 1.1) @license_service_type_id
	select @license_service_type_id = license_service_type_id, @process_type = process_type
	from license_service_type
	where license_service_type_name = @license_service_type_name

	-- 1.2) @license_service_status_id
	select @license_service_status_id = license_service_status_id
	from license_service_status
	where license_service_status_name = 'Pending'

	-- 1.3) insert license_service
	insert into license_service(license_service_type_id, license_service_status_id)
	values(@license_service_type_id, @license_service_status_id)

	select @license_service_id = scope_identity()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) license_service_json
	insert into license_service_json(license_service_id,license_service_json) values(@license_service_id,@service_json)	

	if @service_json is not null and @license_service_type_id < 20
	begin
		-- 2.1) service json
			insert into license_service_value(license_service_id, license_service_value_type_id, license_service_value)
			select	license_service_id = @license_service_id,
					license_service_value_type_id = case when t.license_service_value_type_id is null then a.license_service_value_type_id else t.license_service_value_type_id end,
					nullif(nullif(StringValue, 'null'), '')
			from dbo.fn_parse_json(@service_json) j
			left join license_service_value_type t
				on j.Name = t.value_type_name
			left join license_service_value_type_alias a
				on j.Name = a.value_type_name
			where Object_ID is n
ull and (t.license_service_value_type_id is not null or a.license_service_value_type_id is not null)
			order by 2

		-- 2.2) license

		-- 2.2.1) @keycode
		select @keycode = license_service_value
		from license_service_value
		where license_service_id = @license_service_id 
		and license_service_value_type_id = 2

		-- 2.2.2) @license_id
		select @license_id = license_id, 
			   @license_type_id = license_type_id 
		from license
		where keycode = @keycode

		if @license_id is null
		begin
			select @license_id = l.license_id,
				   @license_type_id = l.license_type_id 
			from license_keycode_alias a
			inner join license l on a.license_id = l.license_id 
			where keycode_alias = @keycode
		end

		if @license_id is null and @license_service_type_name not in ('create_license','sitedns','sitedns_trial','license_swap')
		begin
		
			select @response_code = -110, @message = 'Invalid keycode'
			select response_code = @response_code, message = @message
			return
		end

		-- 2.2.3) @license_id
		if @license_id is not null 
		begin 
			insert into license_service_value(license_service_id, license_service_value_type_id, license_service_value) values(@license_service_id,1,@license_id) 
		end

		-- 2.3) make sure create_child_license is for parent keycode
		if @license_service_type_name = 'create_child_license' and @license_type_id not in (2,3)
		begin
			insert into license_service_failure(license_service_id,license_service_type_id,license_service_status_id,insert_date,failure_date)
			select license_service_id,license_service_type_id,license_service_status_id,insert_date,failure_date=getdate()
			from license_service
			where license_service_id = @license_service_id
		
			delete from license_service where license_service_id = @license_service_id
			return
		end
	
		-- 2.4) make sure keycode_alias is not for parent keycode
		if @license_service_type_name = 'keycode_alias' and @license_type_id in (2,3)
		begin
			insert into license_service_failure(license_service_id,license_service_type_id,license_service_status_id,insert_date,failure_date)
			select license_service_id,license_service_type_id,license_service_status_id,insert_date,failure_date=getdate()
			from license_service
			where license_service_id = @license_service_id
		
			delete from license_service where license_service_id = @license_service_id
			return
		end	
	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) synchronous
	if @process_type = 'synchronous'
	begin
		if @license_service_type_id >= 20
			begin
				if @license_service_type_id in (50,20) -- site_create, license_create
					begin
						exec usp_license_service_insert_license @license_service_id
					end
				else if @license_service_type_id = 56 -- subscription_create 
					begin
						exec usp_license_service_insert_subscription @license_service_id
					end
				else
					begin
						exec usp_license_service_update_license @license_service_id
					end

				if @return_license_service_id = 1
					select license_service_id = @license_service_id

			end
		else
			begin
				exec usp_license_service_update_service @license_service_id
			end
	end

	-- 3.2) asynchronous
	if @process_type = 'asynchronous'
	begin

		declare @sql_string varchar(4000),
				@task_number varchar(10),	
				@db_name varchar(100),
				@system_user varchar(50)

		select @system_user = suser_sname(),
				@db_name = db_name()

		select @task_number = @license_service_id
			select @sql_string = 
				'insert into tasks..task_table (task_number, Command, NoTransaction, 
StartTime) ' + 
				' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_service_update_service ' + convert(varchar(10),@license_service_id) + '''' + ',0,getdate()) '

		exec (@sql_string)

		exec tasks..usp_queue_task @license_service_id
		select @response_code = 0, @message = 'Insert successful'
		select license_service_id = @license_service_id, response_code = @response_code, message = @message

	end

	return

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_insert_sfdc_update]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_service_insert_sfdc_update]


/*     
       DATE          AUTHOR        REMARKS
       2018-01-17    esmart        Initial creation.
	   2018-05-02	 rvinoche	   Fix defects and remove debug code

       DESCRIPTION
*/

AS
       set nocount on                           
       begin try

       
       declare @license_service_type_id tinyint,
                     @temp_id int, 
                     @total_ids int, 
                     @license_id int, 
                     @insert_date datetime, 
                     @license_service_id int, 
                     @sfdc_opportunity_update_id int, 
                     @sfdc_template_id tinyint, 
                     --@sfdc_update_type_id tinyint, 
                     @sfdc_template_name varchar(50),
                     @sfdc_update_json nvarchar(max),
                     @response_code int,
                     @message varchar(100)

       declare @license_service table (license_service_id int, insert_date datetime, keycode varchar(40), account_name varchar(100))
       declare @sfdc_opportunity_update table (temp_id int identity(1,1), license_service_id int, license_id int, insert_date datetime)
       declare @sfdc_opportunity_update_archive table (sfdc_opportunity_update_id int, license_service_id int)

       -------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) select
       -------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       select @license_service_type_id = 24
       --select @sfdc_template_id = 24, @sfdc_update_type_id = 124
       select @sfdc_template_name = 'create_sfdc_trial_task'
       
       select @sfdc_template_id = sfdc_template_id
       from sfdc_template
       where sfdc_template_name = @sfdc_template_name
       
       -- 1.1) select license_service_archive
       insert into @license_service(license_service_id,insert_date,keycode,account_name)
       select a.license_service_id, 
              a.insert_date, 
              keycode = convert(varchar(40),isnull(json_value(license_service_json,'$.keycode'),json_value(license_service_json,'$[0].keycode'))), 
              account_name = convert(varchar(100),isnull(json_value(license_service_json,'$.account_name'),json_value(license_service_json,'$[0].account_name')))
       from license_service_archive a
       inner join license_service_json j
              on j.license_service_id = a.license_service_id
       where a.license_service_type_id = @license_service_type_id and a.license_service_status_id = 2
       order by 1

       -- 1.2) select license_service records already processed into sfdc
       insert into @sfdc_opportunity_update_archive(sfdc_opportunity_update_id,license_service_id)
       select a.sfdc_opportunity_update_id, license_service_id = json_value(j.sfdc_update_json,'$.license_service_id')
       from sfdc_opportunity_update_archive a
       inner join sfdc_opportunity_update_json j
              on j.sfdc_opportunity_update_id = a.sfdc_opportunity_update_id
       where a.sfdc_template_id = @sfdc_template_id
       
              -- 1.2.1) check for active updates
              insert into @sfdc_opportunity_update_archive(sfdc_opportunity_update_id,license_service_id)
              select u.sfdc_opportunity_update_id, license_service_id = json_value(j.sfdc_update_json,'$.license_service_id')
              from sfdc_opportunity_update u
              inner join sfdc_opportunity_update_json j
                     on j.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
 
             where u.sfdc_template_id = @sfdc_template_id

       -- 1.3) select new records
       insert into @sfdc_opportunity_update(license_service_id,license_id,insert_date)
       select t.license_service_id, l.license_id, l.insert_date
       from @license_service t
       inner join license l
              on l.keycode = t.keycode
       inner join license_key k
              on k.license_id = l.license_id
       left join partner_license pl
              on pl.license_id = l.license_id and pl.partner_license_status_id = 2 and pl.start_date < t.insert_date and (pl.end_date > t.insert_date or pl.end_date is null)
       left join sfdc_user su
              on t.account_name = su.Name or t.account_name = su.Username
       left join @sfdc_opportunity_update_archive a
              on a.license_service_id = t.license_service_id
       where (pl.partner_id is null or pl.partner_id = 5559) and su.User2Id is null and a.license_service_id is null and k.salesforce_license_id is not null
       order by 1 desc


       -------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 2.) insert sfdc_opportuntity_update
       -------------------------------------------------------------------------------------------------------------------------------------------------------------------
       

       -- 2.1) @sfdc_opportunity_update
       select @temp_id = 1, @total_ids = max(temp_id) from @sfdc_opportunity_update

       while @total_ids >= @temp_id
              begin

              -- 2.1.1) select values
              select @license_service_id = license_service_id, @license_id = license_id, @insert_date = insert_date
              from @sfdc_opportunity_update
              where temp_id = @temp_id

              select @sfdc_update_json = (select license_service_id
                                                              from @sfdc_opportunity_update
                                                              where temp_id = @temp_id
                                                              for json auto, without_array_wrapper)


              exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = @sfdc_template_name, @sfdc_update_json = @sfdc_update_json
              
       
              ---- 2.1.2) insert sfdc_opportunity_update
              --insert into sfdc_opportunity_update(sfdc_template_id,sfdc_update_type_id,process_date,license_id)
              --values(@sfdc_template_id,@sfdc_update_type_id,@insert_date,@license_id)

              --select @sfdc_opportunity_update_id = scope_identity()

              ---- 2.1.3) insert sfdc_opportunity_update_json
              --insert into sfdc_opportunity_update_json(sfdc_opportunity_update_id,sfdc_update_json)
              --values(@sfdc_opportunity_update_id, @sfdc_update_json)

              -- 2.1.4) reset variables
              select @license_service_id = null, @license_id = null, @insert_date = null, @sfdc_opportunity_update_id = null, @sfdc_update_json = null

              select @temp_id = @temp_id + 1
              end

end try

begin catch
       
       set @response_code = -200
       set @message = case when @message is null then 'insert failed'
                                         else @message end

       declare @DBName nvarchar(128)
       set @DBName = db_name()
       exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_insert_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_service_insert_subscription] (@license_service_id INT)

/*	
	DATE			AUTHOR			REMARKS
    2020-11-11      abelenkiy       Initial creation.
    2025-02-21      jberry          US-3508865 - Changed sec 3.6 to remove serial number prefix hardcoding
    2026-06-25      jberry          US-5461418 - Added app config name to call to fn_app_config_select_key_values

	DESCRIPTION
	Creates S2 Best Buy subscription for /CreateSubscription API call.
	PHP calls usp_license_service_insert_service with JSON and 'subscription_create' license_service_type.
	This procedure creates the license and subscription, then returns keycode and serial_number.


	EXAMPLE JSON:
	{"partnerServiceSku": "4B08DF4B-E798-4D07-AF9C-929572", "bbyPlanSku": "1556231", "requestId": "1234"}

	JSON INPUT KEYS
	partnerServiceSku   subscription_partner_product.subscription_partner_product_key
						Indicates licence_distribution_method and product which will be used for license creation
	bbyPlanSku          subscription_plan_sku.plan_sku
	                    Currently the only use of this is validation that it exists in our tables and setting opt_value
	requestId           Best Buy's id for the call - we don't use this other than logging in license_service_json

	RESPONSES
	CODE	PHP MAPPING							MESSAGE
	0		Success								Success - keycode and serial_number created and added to input JSON
	10		unrecognized_plan_sku				Unrecognized Bestbuy Plan Sku
	19		unrecognized_partner_service_sku	Unrecognized Partner Service Sku
	99		unknown								Unknown error (this returns the error message in the CATCH block)


*/
AS
SET NOCOUNT ON

    BEGIN TRY
    
        DECLARE @APP_CONFIG TABLE
        (
          [app_config_name] NVARCHAR(50),
          [key] NVARCHAR(50),
          [value] NVARCHAR(MAX)
        );

        INSERT INTO @APP_CONFIG
        (
          app_config_name,
         [key],
         [value]
        )
        SELECT f.app_config_name,
          f.[key],
          f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('BBY_S2_SERIAL_NUMBER_PREFIX','BBY_S2') f;

        DECLARE
            @keycode VARCHAR(40)
          , @license_id INT
          , @serial_number VARCHAR(19)
          , @license_service_json NVARCHAR(MAX)
          , @plan_sku VARCHAR(10)
		  , @subscription_partner_product_key VARCHAR(30)
          , @subscription_type_id INT
          , @opt_status TINYINT
          , @product_id INT
          , @license_distribution_method_id INT
          , @subscription_partner_product_id INT
          , @serial_number_prefix VARCHAR(20)
          , @insert_date DATETIME = GETDATE()
          , @response_code INT
          , @message VARCHAR(100)
		  , @php_response_text VARCHAR(100)
          , @transaction_user VARCHAR(20) = 's2_api'

        -- 1) select and parse
        -- 1.1) @license_service_json
        select @license_service_json = license_service_json
        from dbo.license_service_json
        where license_service_id = @license_service_id

        -- 1.2) parse json - set variables from joined tables
        --      using left joins because missing subscription_partner_product_key and plan_sku are different error cases - we need to know which one we hit
        select
           @plan_sku = pls.plan_sku
		  , @subscription_partner_product_key = spp.subscription_partner_product_key
		  , @subscription_partner_product_id = spp.subscription_partner_product_id
		  , @product_id = spp.product_id
		  , @license_distribution_method_id = spp.license_distribution_method_id
		  , @opt_status = pls.plan_sku_opt_out
		  , @subscription_type_id = pls.subscription_type_id
        from openjson(@lic
ense_service_json)
            with (plan_sku varchar(11) '$.bbyPlanSku', subscription_partner_product_key varchar(31) '$.partnerServiceSku') j
            left join dbo.subscription_plan_sku pls
                on pls.plan_sku = j.plan_sku
			left join dbo.subscription_partner_product spp on spp.subscription_partner_product_key = j.subscription_partner_product_key

		-- 2) error handling
        if @plan_sku is null
            begin
                select @response_code = 10, @message = 'Unrecognized Bestbuy Plan Sku', @php_response_text = 'unrecognized_plan_sku'
            end
		if @subscription_partner_product_key is null
            begin
                select @response_code = 19, @message = 'Unrecognized Partner Service Sku', @php_response_text = 'unrecognized_partner_service_sku'
            end

		-- 3) create license and subscription if no error (error case handled in ELSE)
		if @response_code is null
			begin
				-- 3.1) generate keycode from product_id and disti in subscription_service_product table
				exec dbo.usp_license_generate_keycode_cart
					@product_id = @product_id
				  , @license_distribution_method_id = @license_distribution_method_id
				  , @keycode = @keycode output
				  , @response_code = @response_code output
				  , @message = @message output

				-- 3.2) insert license
				--      expiration because it will be set in activate call; hard-coded values are consistent with how bby bulk loads are currently done
				insert into dbo.license (keycode, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id
									 , max_daily_activations, max_child_licenses, insert_by, modified_by)
				select @keycode, plp.product_line_id
				  , 1 -- Active
				  , 1 -- Consumer
				  , @license_distribution_method_id, p.license_keycode_type_id, 1, 1, @transaction_user, @transaction_user
				from dbo.product p
				inner join 	dbo.product_line_product plp on plp.product_id = p.product_id
				where p.product_id = @product_id

				select @license_id = scope_identity()

				-- 3.3) license_category_license 
				insert into dbo.license_category_license (license_id, license_category_id)
				select @license_id, plc.license_category_id
				from dbo.product_license_category plc
				where plc.product_id = @product_id

				-- 3.4) license_capability
				insert into dbo.license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_by, modified_by)
				select @license_id, c.capability_id, c.capability_type_id, c.capability_activation_days, @transaction_user, @transaction_user
				from dbo.product_capability c
				where c.product_id = @product_id
				order by c.capability_id

				-- 3.5) license_seat 
				insert into dbo.license_seat (license_id, license_seats, modified_by, insert_by)
				select @license_id, ps.seats, @transaction_user, @transaction_user
				from dbo.product_seat ps
				where ps.product_id = @product_id

				-- 3.6) subscription
				SELECT @serial_number_prefix = c.[value]
				FROM dbo.license_category_license lcl
				JOIN dbo.license_category lc ON lc.license_category_id = lcl.license_category_id
				JOIN @APP_CONFIG c ON c.[key] = lc.license_category_name
				WHERE lcl.license_id = @license_id

				insert into dbo.subscription (subscription_type_id, license_id, serial_number, plan_sku, opt_status, insert_date, subscription_partner_product_id)
				select @subscription_type_id, @license_id, @serial_number_prefix + convert(varchar(9), @license_id), @plan_sku, @opt_status, @insert_date, @subscription_partner_product_id

				select @serial_number = s.serial_number
				from dbo.subscription s
				where s.license_id = @license_id

				-- 4) insert prevx queue
				insert into dbo.prevx_update (license_id, prevx_update_type_id, prevx_update_status_id, process_date)
				select @license_id, 100, 0, @insert_date process_date

				-- 5) update license_se
rvice success
				-- 5.1) set response_code and message
				select @response_code = 0, @message = 'Success - keycode and serial_number created and added to input JSON', @php_response_text = 'success'

				-- 6.1) license_service_archive
				insert into dbo.license_service_archive (license_service_id, license_service_type_id, license_service_status_id, insert_date)
				select ls.license_service_id, ls.license_service_type_id, 2, ls.insert_date
				from dbo.license_service ls
				where license_service_id = @license_service_id
	        end
		-- 7) license_service_failure
		else
			begin
				insert into dbo.license_service_failure (license_service_id, license_service_type_id, license_service_status_id, insert_date)
				select ls.license_service_id, ls.license_service_type_id, 3, ls.insert_date
				from dbo.license_service ls
				where license_service_id = @license_service_id
			end

		-- 8) license_service management
		-- 8.1) update input json with serial_number/keycode (if success) and response message
		select @license_service_json = json_modify(json_modify(json_modify(@license_service_json,'$.keycode',@keycode)
																		, '$.serial_number', @serial_number)
																		, '$.message', @message)

		update dbo.license_service_json
		set license_service_json = @license_service_json
		where license_service_id = @license_service_id

        -- 8.2) delete service record
        delete from dbo.license_service where license_service_id = @license_service_id

		-- 9) return
        select @keycode as keycode, @serial_number as serial_number, @subscription_partner_product_key as subscription_partner_product_key
			, @response_code as response_code, @message as message, @php_response_text as php_response_text

    end try
    begin catch
		-- 10) procedure/db error
		-- 10.1) concat error_message() with license_service_id
		set @message = 'license_service_id = ' + convert(varchar(20), @license_service_id) + ': ' + error_message()

		-- 10.2) return same schema as in TRY block (this will not be used by PHP but may be useful for debugging)
		select @keycode as keycode, @serial_number as serial_number, @subscription_partner_product_key as subscription_partner_product_key
				, 99 as response_code, @message as message, 'unknown' as php_response_text

		-- 10.3) return and log error
		raiserror(@message, 16, 1)

    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_search_license_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_service_search_license_service]

(	
	@keycode varchar(40),  
	@license_service_type_id tinyint,
	@start_date datetime,
	@end_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2015-02-06	esmart		Initial creation
	2016-07-03	cnovac		updated license_service references for CB changes
	
	DESCRIPTION
	search license service
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--select a.license_service_archive_id, a.license_service_id, a.license_id, a.license_service_type_id, t.license_service_type_name, a.license_service_status_id, a.keycode, a.external_keycode, a.guid, a.trial, a.license_seats, a.effective_date, a.insert_date, a.archive_date
	--from license_service_archive a
	--inner join license_service_type t
	--	on a.license_service_type_id = t.license_service_type_id
	--where (a.keycode = case when @keycode is not null then @keycode else a.keycode end or a.external_keycode = case when @keycode is not null then @keycode else a.external_keycode end) and
	--		a.license_service_type_id = case when @license_service_type_id is not null then @license_service_type_id else a.license_service_type_id end and
	--		(a.insert_date > @start_date or @start_date is null) and
	--		(a.insert_date < @end_date or @end_date is null)
	--order by a.license_service_archive_id desc

	select a.license_service_archive_id, a.license_service_id, lsv.license_service_value as license_id, a.license_service_type_id, t.license_service_type_name,
	       a.license_service_status_id, lsv2.license_service_value as keycode, lsv3.license_service_value as external_keycode, lsv4.license_service_value as guid,
		   lsv5.license_service_value as trial, lsv6.license_service_value as license_seats, lsv7.license_service_value as effective_date, a.insert_date, a.archive_date
	from license_service_archive a
	left join license_service_value lsv on lsv.license_service_id = a.license_service_id and lsv.license_service_value_type_id = 1
	left join license_service_type t on a.license_service_type_id = t.license_service_type_id
	left join license_service_value lsv2 on lsv2.license_service_id = a.license_service_id and lsv2.license_service_value_type_id = 2
	left join license_service_value lsv3 on lsv3.license_service_id = a.license_service_id and lsv3.license_service_value_type_id = 3
	left join license_service_value lsv4 on lsv4.license_service_id = a.license_service_id and lsv4.license_service_value_type_id = 4
	left join license_service_value lsv5 on lsv5.license_service_id = a.license_service_id and lsv5.license_service_value_type_id = 5
	left join license_service_value lsv6 on lsv6.license_service_id = a.license_service_id and lsv6.license_service_value_type_id = 6
	left join license_service_value lsv7 on lsv7.license_service_id = a.license_service_id and lsv7.license_service_value_type_id = 7
	where (lsv2.license_service_value = case when @keycode is not null then @keycode else lsv2.license_service_value end or lsv3.license_service_value = case when @keycode is not null then @keycode else lsv3.license_service_value end) and
			a.license_service_type_id = case when @license_service_type_id is not null then @license_service_type_id else a.license_service_type_id end and
			(a.insert_date > @start_date or @start_date is null) and
			(a.insert_date < @end_date or @end_
date is null)
	order by a.license_service_archive_id desc


	


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
