-- PROCEDURE: [dbo].[usp_license_service_select_json]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_service_select_json]

(
		@license_service_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2017-08-21	esmart		Initial creation.

	DESCRIPTION
*/

AS
	set nocount on				
	begin try

	declare @response_code int,
			@message varchar(100)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select a.license_service_id, t.license_service_type_id, t.license_service_type_name, j.license_service_json,
		keycode = convert(varchar(40),isnull(json_value(j.license_service_json,'$.keycode'),json_value(j.license_service_json,'$[0].keycode'))),
		l.license_id
	from license_service_archive a
	inner join license_service_type t
		on t.license_service_type_id = a.license_service_type_id
	inner join license_service_json j
		on j.license_service_id = a.license_service_id
	left join license l 
		on l.keycode = convert(varchar(40),isnull(json_value(j.license_service_json,'$.keycode'),json_value(j.license_service_json,'$[0].keycode')))
	where a.license_service_id = @license_service_id

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
