-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_service_update_bulk_update]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_service_update_bulk_update]

/*	
	DATE		AUTHOR		REMARKS
	2019-09-20	esmart		Initial creation.
	2020-05-28	esmart		Add override_billing_entity
	2025-10-29  vgangatharan Added section 1.4 to update the bulk load file status
	https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4539952

	DESCRIPTION
	Process pending update from license_service_bulk_update
*/

AS

declare @response_code int,
			@message varchar(100)

set nocount on				

begin try

		declare @update_id int, @total_updates int, @license_service_bulk_update_id int, @keycode varchar(40), @license_id int, @license_service_type_name varchar(50), @expiration_date datetime, @modified_by varchar(20), @comment nvarchar(max), @service_json nvarchar(max)

		declare @license_service_update table (update_id int identity(1,1), license_service_bulk_update_id int, license_id int, keycode varchar(40), license_service_type_id tinyint, expiration_date datetime, modified_by varchar(100))
		declare @license_table table (license_service_bulk_update_id int, license_id int, license_category_name varchar(10),license_seats int,storage_gb int,license_keycode_type_id int,license_attribute_license_value int,start_date datetime,expiration_date datetime,category_type_name varchar(50),item_hierarchy_id tinyint, license_status_id int,min_start_date datetime)
		declare @license_service table (license_service_id int)

		-- 1.1) @temp_update
		insert into @license_service_update (license_service_bulk_update_id, license_id, keycode, license_service_type_id, expiration_date, modified_by)
		select u.license_service_bulk_update_id, u.license_id, l.keycode, u.license_service_type_id, u.expiration_date, u.modified_by
		from license_service_bulk_update u 
		inner join license l
			on u.license_id = l.license_id
		where u.update_status = 'pending'
		order by u.license_service_bulk_update_id

		-- 1.2) set values - limit to 100 in a batch		
		select @update_id = 1, @total_updates = max(update_id) from @license_service_update
		select @total_updates = case when @total_updates > 200 then 200 else @total_updates end
				
		-- 1.3) loop through licenses to update
		while @total_updates >= @update_id
		begin
				-- 1.3.1) select values
				select @license_service_bulk_update_id = u.license_service_bulk_update_id, @keycode = u.keycode, @license_id = u.license_id, @license_service_type_name = t.license_service_type_name, @expiration_date = u.expiration_date, @modified_by = u.modified_by, @comment = 'license service bulk update - '+ @modified_by
				from @license_service_update u
				inner join license_service_type t
					on u.license_service_type_id = t.license_service_type_id
				where update_id = @update_id

				-- 1.3.2) create json
				insert into @license_table (license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id, license_status_id)
				select license_id, license_category_name, license_seats, storage_gb, license_keycode_type_id, license_attribute_license_value, start_date, expiration_date, category_type_name, item_hierarchy_id, license_status_id
				from dbo.fn_license_select_license_profile(@license_id)
				where category_type_name = 'full' and license_status_id = case when @license_service_type_name in ('license_enable') then license_status_id else 1 end

				select @service_json = (select ll.keycode, @modified_by as account_name, @comment as comment, 1 as override_billing_entity,
												(select l.license_category_name, expiration_date = @expiration_date
												from @license_table l for json path) license_ca
tegory 
												from license ll
												where ll.license_id = @license_id
				for json path, without_array_wrapper)

				-- 1.3.3) exec license service
				insert into @license_service(license_service_id)						
				exec usp_license_service_insert_service @license_service_type_name,@service_json

				-- 1.3.4) cleanup
				update license_service_bulk_update
				set update_status = 'complete'
				where license_service_bulk_update_id = @license_service_bulk_update_id

				print @license_service_bulk_update_id
				print @keycode

				select @license_service_bulk_update_id = null, @keycode = null, @license_id = null, @license_service_type_name = null, @expiration_date = null, @modified_by = null, @service_json = null, @comment = null
				delete from @license_table

		select @update_id = @update_id + 1
		end
		
		-- 1.4) Update bulk_load_file status if all related updates are complete
				UPDATE blf
				SET load_status = 'Completed',
					modified_date = GETDATE()
				FROM license_service_bulk_load_file blf
				WHERE NOT EXISTS
				(
					SELECT 1
					FROM license_service_bulk_update bsu
					WHERE bsu.license_service_bulk_load_file_id = blf.license_service_bulk_load_file_id
						  AND bsu.update_status <> 'complete'
				)
					  AND blf.load_status <> 'Completed';

	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'license_service_bulk_update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
