-- PROCEDURE: [dbo].[usp_license_service_update_service_retry]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_service_update_service_retry]

	
/*	
	DATE			AUTHOR			REMARKS
	2017-03-22		esmart			Initial creation
	2017-04-03		esmart			Make retry only select transactions that have been attempted once
	2017-10-03		esmart			Support new license service license management
	
	DESCRIPTION
	Retry failed license_service updates
*/

as

	set nocount on
	

	declare	@license_service_id int,
			@license_service_type_id tinyint,
			@retry_id int,
			@total_ids int,	
			@sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100)
			
	-- begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @system_user = suser_sname(),
			@db_name = db_name()

	declare @license_service table (retry_id int identity(1,1), license_service_id int, license_service_type_id int)

	insert into @license_service (license_service_id, license_service_type_id)
	select license_service_id, license_service_type_id
	from license_service
	where process_date < getdate() and update_attempts > 0

	select @retry_id = 1, @total_ids = max(retry_id)
	from @license_service

	while @total_ids >= @retry_id
		begin
		select @license_service_id = license_service_id, @license_service_type_id = license_service_type_id
		from @license_service
		where retry_id = @retry_id

		print @license_service_id

		if @license_service_type_id < 20
			begin
				exec usp_license_service_update_service @license_service_id	
			end
		else
			begin
				exec usp_license_service_update_license @license_service_id
			end

		-- NOTE: service broker process would be better, but I think SB is capturing failure for the transactions processed rather than the procedure being executed. Removing try-catch from
		-- 		this procedure and call the subroutine will trigger the try-catch on the usp_license_service_update_service. The way it is now is that only one record can be processed rather than all 
		--		pending records. First failure will stop processing.
				

		--select @task_number = @license_service_id
		
		--select @sql_string = 
		--	'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
		--	' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_service_update_service ' + convert(varchar(10),@license_service_id) + '''' + ',0,getdate()) '

		--exec (@sql_string)
		--print @sql_string

		--exec tasks..usp_queue_task @license_service_id

		--select @task_number = null, @license_service_id = null, @sql_string = null

		select @retry_id = @retry_id + 1
		end


	--end try

	--begin catch

	--	set @response_code = -200
	--	set @message = case when @message is null then 'insert license_module_license failed'
	--						else @message end

	--	declare @DBName nvarchar(128)
	--	set @DBName = db_name()
	--	exec usp_LogError @ErrorDB = @DBName
		
	--end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_insert_product_capability_working]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_insert_product_capability_working]
(
	@license_id int,
	@days int,
	@modified_by varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-12		esmart		Initial creation
	2011-11-11		esmart		Open up updates to trial keycodes
	2017-04-21		esmart		product_license_module_working

	DESCRIPTION
	insert product_capability_working 
*/

AS

set nocount on

begin try

	declare @log_type int

	set @log_type = 1
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1 @license_id
			select @response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then '@license_id not valid' else '' end
			from license
			where license_id = @license_id

			if @response_code < 0 	
				begin
					RAISERROR (@message, 11, 0)
				end

		-- 1.2 @days
			if @days = 0 	
				begin
					set @response_code = -120
					set @message = 'Days cannot = 0'
					RAISERROR (@message, 11, 0)
				end

		-- 1.3 @modified_by
			if @modified_by is null
				begin 
				set @modified_by = suser_sname()
				end
			
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert product_capability_working
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 2.1) remove previous records from product_capability_working
		if (select count(*) from product_capability_working where product_id = @license_id) > 0
			begin
			delete from product_capability_working where product_id = @license_id
			end

		-- 2.2) insert product_capability_working
		insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by)
		select	product_id = license_id, 
				c.capability_id, 
				capability_type_id, 
				capability_activation_days =
									case
										when capability_ext_id is not null and capability_type_id in (1,2,3,6,7,8,9) and capability_activation_days >= 0 then @days
										else null
									end, 
				insert_date = getdate(), 
				insert_by = @modified_by
		from license_capability c
		left join capability_ext e
			on c.capability_id = e.capability_id and e.capability_ext_type_id = 1
		where license_id = @license_id
		order by c.capability_id

		-- 2.3) insert product_license_module_working
		insert into product_license_module_working (product_id, license_module_id,license_module_type_id, days, module_seats)
		select product_id = license_id, 
			license_module_id, 
			license_module_type_id, 
			days = @days, 
			module_seats
		from license_module_license
		where license_id = @license_id
	
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'product_capability_working insert failed @license_id = ' + isnull(convert(varchar(10),@license_id),'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @Erro
rDB = @DBName
	
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_refund_license_capability]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_refund_license_capability]
(
	@product_id int,
	@keycode varchar(40),
	@update_source varchar(10),
	@modified_by varchar(20),
	@order_item_id int,
	@effective_date datetime output,
	@license_id int output,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-10		esmart		Initial creation
	2014-03-28		mrobbins	fixed issue with null expiration date

	DESCRIPTION
	complete renewal and upgrade
*/

AS
set nocount on

	declare @capability_change_reason_id int,
			@new_capability_count int,
			@max_days_new int,
			@product_type_id int,
			@product_capability_license_id int,
			@original_order_item_id int,
			@product_capability_count int

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.2) get product_type_id
			
			if @update_source = 'CSI'
				begin 
					select @product_type_id = 2
				end
			else 
				begin
					select @product_type_id = product_type_id
					from product 
					where product_id = @product_id
				end

			if @product_type_id is null
				begin
					set @response_code = -120
					set @message = 'No matching product or NULL product_type_id @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
					RAISERROR (@message, 11, 0)
				end

		-- 1.1) @capability_change_reason_id
			set @capability_change_reason_id =
			case
				when @product_type_id = 1 then 8 -- New - License refund
				when @product_type_id = 2 then 9 -- Renewal - License refund
				when @product_type_id = 3 then 10 -- Upgrade - License refund
				when @product_type_id = 4 then 10 -- Upgrade - License refund
			end

		-- 1.2) get original order_item_id for refunded line item
		
			select @original_order_item_id = i.order_item_id 
			from order_item ir
			inner join order_item i
				on ir.order_header_id = i.order_header_id 
			where ir.order_item_id = @order_item_id and 
				i.order_item_id <> @order_item_id and
				i.product_id = @product_id

begin try

--	select product_type_id = @product_type_id, product_id = @product_id, capability_change_reason_id = @capability_change_reason_id, original_order_item_id = @original_order_item_id
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
			-- 2.1) get license
			select @license_id = license_id
			from license 
			where keycode = @keycode	

			delete from product_capability_working where product_id = @license_id 
			
			-- 2.2) check for legacy orders where order_item_id was not added to the license_capability history
			insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days)
			select product_id = license_id,
					capability_id,
					capability_type_id,
					capability_activation_days = -1 * days_added
			from license_capability_history
			where license_id = @license_id 
				and order_item_id
 = @original_order_item_id
				
			select @product_capability_count = count(*) from fn_license_select_product_capability(@license_id,@update_source)

			if @product_capability_count = 0  
				begin
					insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days)
					select product_id = @license_id,
							capability_id,
							capability_type_id,
							capability_activation_days = -1 * capability_activation_days
					from product_capability
					where product_id = @product_id 
				end			

--			select 'fn_license_select_product_capability', * from fn_license_select_product_capability(@license_id,@update_source)

--			-- 2.2) check to see if seed values in license_capability_history are in place
--			exec usp_license_sub_insert_initial_license_capability_history @license_id		
		
			-- 2.3) create temp table and add data
			declare @temp_license_capability_update table(
				[license_capability_id] [int] NOT NULL,
				[license_id] [int] NOT NULL,
				[capability_id] [int] NOT NULL,
				[capability_type_id] [int] NOT NULL,
				[product_capability_type_id] [int] NOT NULL,
				[capability_activation_days] [int] NULL,
				[capability_activation_date] [datetime] NULL,
				[capability_expiration_date] [datetime] NULL,
				[insert_date] [datetime] NOT NULL,
				[insert_by] [varchar](50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
				[modified_date] [datetime] NOT NULL,
				[modified_by] [varchar](50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
				[days_used] [int] NULL,
				[days_remaining] [int] NULL,
				[days_added] [int] NULL,
				[days_new] [int] NULL,
				[days_contiguous] [int] NULL,
				[last_days_contiguous] [int] NULL,
				[new_activation_date] [datetime] NULL
			)

			-- 2.3.1
			insert into @temp_license_capability_update (license_capability_id, license_id, capability_id, capability_type_id, product_capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, days_used, days_remaining, days_added, days_contiguous, last_days_contiguous, new_activation_date)
			select	l.license_capability_id, 
					l.license_id, 
					l.capability_id, 
					l.capability_type_id, 
					f.capability_type_id,
					l.capability_activation_days, 
					l.capability_activation_date, 
					l.capability_expiration_date, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by,
					days_used =  
							case 
								when datediff(dd,l.capability_activation_date,getdate()) > l.capability_activation_days then l.capability_activation_days
								else isnull(datediff(dd,l.capability_activation_date,getdate()),0)
							end,
					days_remaining = 0,
					days_added = isnull(f.capability_activation_days,0),
					days_contiguous = 0,
					last_days_contiguous = 0,
					new_activation_date = getdate()
			from license_capability l
			inner join fn_license_select_product_capability(@license_id,@update_source) f
				on l.capability_id = f.capability_id
			where license_id = @license_id
			
			-- 2.3.2) update days_remaining columns
				update @temp_license_capability_update
				set days_remaining = 
					case
						when capability_activation_days - days_used < 0 then capability_activation_days
						else isnull(capability_activation_days - days_used,0)
					end	

			-- 2.3.3) update days_new
				update @temp_license_capability_update
				set days_new = 
							case 
								when days_remaining + days_added > 0 then days_remaining + days_added
								else 0
							end

			-- 2.3.4) update last_days_contiguous
				update @temp_license_capability_update
				set last_days_contiguous = isnull((select top 1 days_contiguous from license_capability_history with (nolock) where license_capability_id = t.license_capability_id order by license_capability_history_id desc),0)
				from @temp_license_capability_update t

			-- 2.3.5) update days_contiguous
				update @temp_license_capability_upd
ate
				set days_contiguous = 
							case 
								when last_days_contiguous + days_added <= 0 and days_used > 0 then days_used
								else last_days_contiguous + days_added
							end

				update @temp_license_capability_update
				set days_contiguous = 0
				where days_contiguous < 0

			--select '@temp_license_capability_update', * from @temp_license_capability_update			
			
			-- 2.4) insert rows into license_capability_audit
			
			insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
			select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = getdate(), audit_by = system_user
			from license_capability
			where license_id = @license_id

			-- 2.5) insert rows into license_capability_history
				
				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)
				select license_capability_id, license_id, capability_id, capability_type_id, 
					capability_activation_days = isnull(days_used,0), 
					capability_activation_date, 
					capability_expiration_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
					insert_date, insert_by, modified_date, modified_by, 
					capability_change_reason_id = @capability_change_reason_id, 
					history_date = getdate(), history_by = system_user, 
					days_used = isnull(days_used,0), 
					days_remaining = isnull(days_remaining,0), 
					days_added = isnull(days_added,0), 
					days_new = isnull(days_new,0), 
					days_contiguous = isnull(days_contiguous,0),
					@order_item_id
				from @temp_license_capability_update 

			-- 2.6) update license_capability 
				update license_capability
				set capability_type_id = t.product_capability_type_id,
--					capability_type_id = 
--							case
--								when t.days_new = 0 and t.capability_id not in (1) then 4
--								else t.product_capability_type_id
--							end,
					capability_activation_days = t.days_new,
					capability_activation_date = 
							case
								when t.days_new = 0 then dateadd(dd,isnull(days_used,0),t.capability_activation_date)
								when t.capability_activation_date is null then null
								else new_activation_date
							end,
					capability_expiration_date = 
							case
								when t.days_new = 0 then dateadd(dd,isnull(days_used,0),t.capability_activation_date)
								when t.capability_activation_date is null then null
								else dateadd(dd,t.days_new,new_activation_date)
							end,
					modified_date = getdate(),
					modified_by = system_user
				from license_capability c
				inner join @temp_license_capability_update t
					on c.license_capability_id = t.license_capability_id	
		
			-- 2.7) refund license_storage 		
			exec usp_license_sub_refund_license_storage @license_id,@product_id,@capability_change_reason_id,@order_item_id,@response_code OUTPUT,@message OUTPUT

			-- 2.8) refund license_category_license 		
			exec usp_license_sub_refund_license_category_license @license_id,@product_id,@capability_change_reason_id,@order_item_id,@modified_by,@response_code OUTPUT,@message OUTPUT

			-- 2.9) usp_license_sub_refund_license_seat
			exec usp_license_sub_refund_license_seat @license_id,@product_id,@capability_change_reason_id,@order_item_id,@modified_by,@response_code OUTPUT,@message OUTPUT

			-- 2.10) usp_license_sub_refund_license_seat
			exec usp_license_sub_refund_license_module_license @lice
nse_id,@product_id,@capability_change_reason_id,@order_item_id,@modified_by,@response_code OUTPUT,@message OUTPUT

		-- 4.1) delete rows from product_capability_working
			delete from product_capability_working where product_id = @license_id 

		-- 5.1) insert message

				declare @load_type int, 
						@dbsource varchar(100)
						
				select @dbsource = db_name(),
						@load_type = 0

				exec [tasks].[dbo].[usp_Licensing_Send_Tasks] @license_id = @license_id,@load_type=@load_type,@dbsource = @dbsource
			


end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


SET ANSI_NULLS ON

GO
