-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_refund_license_category_license]

(
	@license_id int, 
	@product_id int,
	@license_change_reason_id int,
	@order_item_id int,
	@modified_by varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-25		esmart		Initial creation
	
	DESCRIPTION
	refund license_category_license upgrade
*/

AS
set nocount on

	begin try

	declare @original_order_item_id int,
			@history_license_category_id int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@start_date datetime,
			@end_date datetime,
			@days_used int,
			@transaction_date datetime,
			@log_type int
		
	select @log_type = 1, @transaction_date = getdate()

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1 @license_id
		select @response_code =  case when license_id is null then -110 else 0	 end,
			@message = case when license_id is null then 'license_category_license record does not exist' else '' end
		from license_category_license
		where license_id = @license_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
		-- 1.2 @license_change_reason_id
		select @response_code =  case when count(*) = 0 then -120 else 0	 end,
			@message = case when count(*) = 0 then '@license_change_reason_id is not valid' else '' end
		from license_change_reason
		where license_change_reason_id = @license_change_reason_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end


		-- 1.2) get original order_item_id for refunded line item
		select @original_order_item_id = i.order_item_id 
		from order_item ir
		inner join order_item i
			on ir.order_header_id = i.order_header_id 
		where ir.order_item_id = @order_item_id and 
			i.order_item_id <> @order_item_id and
			i.product_id = @product_id

--select original_order_item_id = @original_order_item_id

		-- 1.3) @history_storage_gb
		select @history_license_category_id = license_category_id
		from license_category_license_history
		where license_id = @license_id and order_item_id = @original_order_item_id
		
		if @history_license_category_id is null
			begin
			select @history_license_category_id = license_category_id
			from license_category_license
			where license_id = @license_id
			end

--select history_license_category_id = @history_license_category_id

		-- 1.4) select current capability dates
		select @capability_activation_date = min(capability_activation_date),
				@capability_expiration_date = max(capability_expiration_date)
		from license_capability
		where license_id = @license_id
	
--	select capability_activation_date = @capability_activation_date,
--			capability_expiration_date = @capability_expiration_date

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) update license_storage
	-- -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-------------------------------------------------------------------
			-- 2.2.1) get start, end, and days used
			select @start_date = start_date, @end_date = end_date, @days_used = datediff(dd,@capability_activation_date,getdate())
			from license_category_license
			where license_id = @license_id
			
			-- 2.2.2) check date against capabilities
			if @capability_expiration_date < @end_date
				begin
					select @end_date = @capability_expiration_date
				end

--select start_date = @start_date, end_date = @end_date, days_used = @days_used

			-- 2.2.3) upgrade or update
			insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, license_change_reason_id, last_modified_date, last_modified_by, history_date, history_by, order_item_id)
			select license_category_license_id, 
					license_id, 
					license_category_id, 
					start_date, 
					end_date = dateadd(dd,isnull(@days_used,0),start_date), 
					license_change_reason_id = @license_change_reason_id, 
					last_modified_date, last_modified_by, 
					history_date = @transaction_date, 
					history_by = @modified_by,
					order_item_id = @order_item_id
			from license_category_license
			where license_id = @license_id

			update license_category_license
			set license_category_id = @history_license_category_id,
				start_date = dateadd(dd,isnull(@days_used,0),start_date),
				end_date = @end_date,
				last_modified_date = @transaction_date, 
				last_modified_by = @modified_by
			from license_category_license
			where license_id = @license_id	

	end try

	begin catch
		
		declare @DBName nvarchar(128)
		
		set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
		set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
		set @message = case 
							when @message is null then 'license_category_license refund failed'
							else @message 
						end

--		print @log_type
--		print @response_code
--		print @message
		
		exec usp_LogError @log_type, @ErrorDB = @DBName
		
	end catch;




GO
