-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_refund_license_module_license]

(
	@license_id int, 
	@product_id int,
	@license_change_reason_id int,
	@order_item_id int,
	@modified_by varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2012-01-10	esmart		Initial creation.

	DESCRIPTION
	select license_modules for upgrade
*/

AS
	set nocount on				

	declare @original_order_item_id int,
			@license_module_license_id int,
			@license_module_type_id int,
			@start_date datetime,
			@end_date datetime,
			@category_start_date datetime,
			@category_end_date datetime,
			@last_modified_date datetime

	select @last_modified_date = getdate()

	begin try
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @original_order_item_id
	select @original_order_item_id = i.order_item_id 
	from order_item ir
	inner join order_item i
		on ir.order_header_id = i.order_header_id 
	where ir.order_item_id = @order_item_id and 
		i.order_item_id <> @order_item_id and
		i.product_id = @product_id

	-- 1.2) 
	select @license_module_license_id = license_module_license_id,
			@license_module_type_id = license_module_type_id,
			@start_date = start_date,
			@end_date = end_date
	from license_module_license_history
	where license_id = @license_id and order_item_id = @original_order_item_id

	-- 1.3) select current capability dates
	select @category_start_date = start_date,
			@category_end_date = end_date
	from license_category_license
	where license_id = @license_id

	--select original_order_item_id = @original_order_item_id,
	--		license_module_license_id = @license_module_license_id,
	--		license_module_type_id = @license_module_type_id,
	--		start_date = @start_date,
	--		end_date = @end_date,
	--		category_start_date = @category_start_date,
	--		category_end_date = @category_end_date
--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update/insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) refund upgrade only
	if @license_module_license_id is null
		begin
			-- 2.1.1) insert history record
			insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date)
			select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
					m.start_date, 
					end_date = dateadd(dd,(datediff(dd,start_date,getdate())),m.start_date),
					m.last_modified_date, m.last_modified_by, @order_item_id, @license_change_reason_id, @last_modified_date
			from license_module_license m
			where m.license_module_license_id = @license_module_license_id

			-- 2.1.2) delete license_module_license
			delete from license_module_license
			where license_id = @license_id
			
			return
		end
	
	-- 2.2) rollback renewal
	if (select count(*) from license_module_license where license_module_license_id = @license_module_license_id) > 0
		begin
			-- 2.2.1) insert history record
			insert into license_module_license_hist
ory(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date)
			select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
					m.start_date, 
					end_date = dateadd(dd,(datediff(dd,start_date,getdate())),m.start_date),
					m.last_modified_date, m.last_modified_by, @order_item_id, @license_change_reason_id, @last_modified_date
			from license_module_license m
			where license_id = @license_id
			order by m.license_module_id

			-- 2.2.2) delete license_module_license
			update license_module_license
			set start_date = @category_start_date, end_date = @category_end_date, last_modified_date = @last_modified_date
			from license_module_license m
			where m.license_module_license_id = @license_module_license_id
			
			return
		end
	
	-- 2.3) rollback license_category upgrade
	if (select count(*) from license_module_license where license_module_license_id = @license_module_license_id) = 0
		begin
			set identity_insert license_module_license on
			
			insert into license_module_license(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date)
			select license_module_license_id, license_id, license_module_id, license_module_type_id, @category_start_date, @category_end_date, @last_modified_date
			from license_module_license_history
			where license_id = @license_id and order_item_id = @original_order_item_id

			set identity_insert license_module_license off
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_refund_license_seat]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_refund_license_seat]

(
	@license_id int, 
	@product_id int,
	@license_change_reason_id int,
	@order_item_id int,
	@modified_by varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-25		esmart		Initial creation
	
	DESCRIPTION
	refund license_seat upgrade
*/

AS
set nocount on

	begin try

	declare @original_order_item_id int,
			@history_license_seats int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@start_date datetime,
			@end_date datetime,
			@days_used int,
			@transaction_date datetime,
			@log_type int
		
	select @log_type = 1, @transaction_date = getdate()

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1 @license_id
		select @response_code =  case when license_id is null then -110 else 0	 end,
			@message = case when license_id is null then 'license_seat record does not exist' else '' end
		from license_seat
		where license_id = @license_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
		-- 1.2 @license_change_reason_id
		select @response_code =  case when count(*) = 0 then -120 else 0	 end,
			@message = case when count(*) = 0 then '@license_change_reason_id is not valid' else '' end
		from license_change_reason
		where license_change_reason_id = @license_change_reason_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end


		-- 1.2) get original order_item_id for refunded line item
		select @original_order_item_id = i.order_item_id 
		from order_item ir
		inner join order_item i
			on ir.order_header_id = i.order_header_id 
		where ir.order_item_id = @order_item_id and 
			i.order_item_id <> @order_item_id and
			i.product_id = @product_id

--select original_order_item_id = @original_order_item_id

		-- 1.3) @history_license_seats
		select @history_license_seats = license_seats
		from license_seat_history
		where license_id = @license_id and order_item_id = @original_order_item_id
		
		if @history_license_seats is null
			begin
			select @history_license_seats = license_seats
			from license_seat
			where license_id = @license_id
			end

--select history_license_seats = @history_license_seats

		-- 1.4) select current capability dates
		select @capability_activation_date = min(capability_activation_date),
				@capability_expiration_date = max(capability_expiration_date)
		from license_capability
		where license_id = @license_id
	
--	select capability_activation_date = @capability_activation_date,
--			capability_expiration_date = @capability_expiration_date

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) update license_storage
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 2.2.1) get start, end, and days used
			select @start
_date = start_date, @end_date = end_date, @days_used = datediff(dd,@capability_activation_date,getdate())
			from license_seat
			where license_id = @license_id
			
			-- 2.2.2) check date against capabilities
			if @capability_expiration_date < @end_date
				begin
					select @end_date = @capability_expiration_date
				end

--select start_date = @start_date, end_date = @end_date, days_used = @days_used

			-- 2.2.3) upgrade or update
			insert into license_seat_history(license_seat_id, license_id, license_seats, seats_used, start_date, end_date, license_change_reason_id, insert_date, insert_by, modified_date, modified_by, history_date, history_by, order_item_id)
			select license_seat_id, 
					license_id, 
					license_seats, 
					seats_used,
					start_date, 
					end_date = dateadd(dd,isnull(@days_used,0),start_date), 
					license_change_reason_id = @license_change_reason_id, 
					insert_date, insert_by, modified_date, modified_by,
					history_date = @transaction_date, 
					history_by = @modified_by,
					order_item_id = @order_item_id
			from license_seat
			where license_id = @license_id

			update license_seat
			set license_seats = @history_license_seats,
				start_date = dateadd(dd,isnull(@days_used,0),start_date),
				end_date = @end_date,
				modified_date = @transaction_date, 
				modified_by = @modified_by
			from license_seat
			where license_id = @license_id	

	end try

	begin catch
		
		declare @DBName nvarchar(128)
		
		set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
		set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
		set @message = case 
							when @message is null then 'license_seat refund failed'
							else @message 
						end

--		print @log_type
--		print @response_code
--		print @message
		
		exec usp_LogError @log_type, @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_refund_license_storage]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_sub_refund_license_storage]

(
	@license_id int, 
	@product_id int,
	@license_change_reason_id int,
	@order_item_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-07-14		esmart		Initial creation
	
	DESCRIPTION
	refund license_storage upgrade
*/

AS
set nocount on

	begin try

	declare @history_storage_gb int,
			@current_storage_gb int,
			@product_storage_gb int,
			@original_order_item_id int,
			@max_non_refunded_storage_gb int,
			@log_type int
		
	set @log_type = 1

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1 @license_id
		select @response_code =  case when license_id is null then -110 else 0	 end,
			@message = case when license_id is null then 'license_storage record does not exist' else '' end,
			@current_storage_gb = storage_gb
		from license_storage with (nolock)
		where license_id = @license_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
		-- 1.2 @license_change_reason_id
		select @response_code =  case when count(*) = 0 then -120 else 0	 end,
			@message = case when count(*) = 0 then '@license_change_reason_id is not valid' else '' end
		from license_change_reason with (nolock)
		where license_change_reason_id = @license_change_reason_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end


		-- 1.2) get original order_item_id for refunded line item
		select @original_order_item_id = i.order_item_id 
		from order_item ir with (nolock)
		inner join order_item i with (nolock)
			on ir.order_header_id = i.order_header_id 
		where ir.order_item_id = @order_item_id and 
			i.order_item_id <> @order_item_id and
			i.product_id = @product_id

--select original_order_item_id = @original_order_item_id

		-- 1.3) @history_storage_gb
		select @history_storage_gb = storage_gb
		from license_storage_history with (nolock)
		where license_id = @license_id and order_item_id = @original_order_item_id
		
		-- 1.3.1)
			if @history_storage_gb is null 
				begin
				select @history_storage_gb = current_storage_gb
				from product_storage with (nolock)
				where product_id = @product_id	
				
				if @history_storage_gb is null
					begin
					select @product_storage_gb = 0
					end	
				end

		-- 1.4) product_storage
		select @product_storage_gb = storage_gb
		from product_storage with (nolock)
		where product_id = @product_id

		-- 1.4.1) 
			if @product_storage_gb is null
				begin
				select @product_storage_gb = 0
				end

--select history_storage_gb = @history_storage_gb, current_storage_gb = @current_storage_gb, product_storage_gb = @product_storage_gb

		-- 1.5) determine if the storage_gb needs to be updated based on the current and product storage
		if @current_storage_gb > @product_storage_gb
			begin
				select @history_storage_gb = @current_storage_gb
				select @order_item_id = null
			end

--select history_storage_gb = @history_storage_gb

		-- 1.6) determine if refunding the current product would reduce the storage lower than other products applied to the product.
		
		select @max_non_refunded_storage_gb = isnull(max(storage_gb),0)
		from product_storage s with
 (nolock)
		where product_id in (
					select i.product_id 
					from order_item i with (nolock)
					inner join (select i.order_header_id, i.product_id
							from order_item_license l with (nolock)
							inner join order_item i with (nolock)
								on l.order_item_id = i.order_item_id and i.product_id <> @product_id
							where l.license_id = @license_id) t
					on i.order_header_id = t.order_header_id and i.product_id = t.product_id
					group by i.product_id having sum(i.quantity) > 0)

--select max_non_refunded_storage_gb = @max_non_refunded_storage_gb

		if @max_non_refunded_storage_gb > @history_storage_gb
			begin
				select @history_storage_gb = @max_non_refunded_storage_gb
			end
		
--select history_storage_gb = @history_storage_gb

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) update license_storage
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		
		declare @storage_activation_date datetime,
				@storage_expiration_date datetime,
				@new_storage_activation_date datetime,
				@new_storage_expiration_date datetime

		-- 2.1 get current activation and expiration dates
		select @storage_expiration_date = capability_expiration_date
		from license_capability with (nolock)
		where license_id = @license_id and capability_id = 11
		
--select storage_expiration_date = @storage_expiration_date

		-- 2.2 insert record into license_storage_audit
		insert into license_storage_audit (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by)
		select license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by
		from license_storage with (nolock)
		where license_id = @license_id

		-- 2.3 insert license_storage_history
		insert into license_storage_history (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, order_item_id)
		select license_storage_id, license_id, storage_gb, 
				storage_activation_date,
				storage_expiration_date = dateadd(dd,datediff(dd,storage_expiration_date,getdate()),storage_expiration_date),
				insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @order_item_id
		from license_storage with (nolock)
		where license_id = @license_id

		-- 2.4 update license_storage
		update license_storage
		set 
			storage_gb = @history_storage_gb,
			storage_activation_date = dateadd(dd,datediff(dd,@storage_expiration_date,getdate()),@storage_expiration_date),
			storage_expiration_date = @storage_expiration_date,
			modified_date = getdate(),
			modified_by = suser_sname()
		from license_storage with (nolock)
		where license_id = @license_id
		
	end try

	begin catch
		
		declare @DBName nvarchar(128)
		
		set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
		set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
		set @message = case 
							when @message is null then 'license_storage insert failed'
							else @message 
						end

--		print @log_type
--		print @response_code
--		print @message
		
		exec usp_LogError @log_type, @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_renew_license_capability]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_renew_license_capability]
(
	@product_id int,
	@keycode varchar(40),
	@update_source varchar(10),
	@modified_by varchar(20),
	@order_item_id int,
	@effective_date datetime output,
	@license_id int output,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-10		esmart		Initial creation
	2010-01-05		dsmelker	Modified the swap change reasons 
	2010-07-20		esmart		Merge changes for SStoAV and seats
	2010-09-09		esmart		Add @base_capability_id for non SS licenses
	2011-02-15		acoffel		added fix to effective date to support backup renewals
	2011-11-11		esmart		Open up updates to trial keycodes
	2012-02-03		esmart		module product_type support
	2012-10-24		esmart		add autorenewal_cycle support
	2012-11-09		esmart		add enterprise mobile seat
	2014-05-12		acoffel		added seat enforcement flag handling
	2014-09-09		esmart		modify expiration for zero days
	2016-01-21		esmart		capability_activation_days correction
	2016-01-25		esmart		Add usp_license_update_license_autorenewal_cycle sub
	2016-07-03		cnovac		updated license_service references for CB changes
	2016-11-02		esmart		Check billing model for utility
	2017-02-07		esmart		Add module_seats to usp_license_update_license_module_license
	2017-04-19		esmart		Fix issue with module products updates
	2017-08-02		acoffel		license_renewals
	2019-01-08		rvinoche	Support autobilling attributes living only in license_effective_object
	2021-12-08		psatish		Added Perpetual billing model to update the Contract end date
	2024-03-25		cibach		Modifed temp table to use varchar(200) for insert/modified by


	DESCRIPTION
	complete renewal and upgrade
*/

AS
set nocount on

	declare @capability_change_reason_id int,
			@new_capability_count int,
			@max_days_new int,
			@product_type_id int,
			@capability_activation_count int,
			@product_storage_gb int,
			@storage_gb int,
			@storage_capability_count int,
			@storage_capability_count_product int,
			@ss_check int,
			@transaction_date datetime,
			@license_category_id_product tinyint,
			@license_category_id_calculated tinyint,
			@license_category_id tinyint,
			@license_seats_current int,		
			@license_status_id int,
			@seats int,
			@base_capability_id int,
			@product_line_id int,
			@product_license_module_id int,
			@message_autorenewal_cycle_id tinyint,
			@license_attribute_license_value int,
			@billing_day_of_month tinyint,
			@license_type_id int,
			@max_child_licenses int,
			@capability_expiration_date datetime,
			@contract_start_date datetime,
			@contract_end_date datetime,
			@contract_days int,
			@module_seats int, 
			@license_change_reason_id int, 
			@license_module_id int, 
			@module_end_date DATETIME,
			@order_header_id int

			select @capability_activation_count = 0
			select @transaction_date = getdate()

			if @modified_by is null or @modified_by = ''
				begin
				select @modified_by = suser_sname()
				end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) get license and capability data
		select @license_id = license_id, @license_status_id = license_status_id, @product_line_id = product_line_id, @license_type_id = license_type_id, @max_child_license
s = max_child_licenses
		from license 
		where keycode = @keycode	
	
		select @capability_activation_count = count(*)
		from license_capability
		where license_id = @license_id and capability_activation_date is not null

		-- 1.2) get product_type_id
			
			if @update_source in ('CSI','CSI Type','swap')
				begin 
					select @product_type_id = 2
				end
			else 
				begin
					select @product_type_id = product_type_id
					from product 
					where product_id = @product_id
				end

			if @product_type_id is null
				begin
					set @response_code = -120
					set @message = 'No matching product or NULL product_type_id @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
					RAISERROR (@message, 11, 0)
				end

		-- 1.2) @capability_change_reason_id
			set @capability_change_reason_id =
			case
				when @product_type_id = 1 and @update_source = 'rebill' then 1
				when @product_type_id = 2 and @update_source not in ('CSI','CSI Type','swap')  then 2 -- Renewal - License capability update
				when @product_type_id = 2 and @update_source in ('CSI','CSI Type') then 4
				when @product_type_id = 3 and @update_source = 'load' then 3 -- Upgrade - License capability update
				when @product_type_id = 3 and @update_source = 'downgrade' then 29 -- Downgrade
				when @product_type_id = 3 and @update_source = 'upgrade' then 18 -- Upgrade - Product update	
				when @product_type_id = 2 and @update_source in ('swap') and @product_id = @license_id then 25
				when @product_type_id = 2 and @update_source in ('swap') and @product_id <> @license_id then 26
				when @update_source = 'sstoav' then 19
				--when @product_type_id = 2 and @update_source in ('swap') then 11
				when @product_type_id = 3 and @update_source = 'account' then 20 -- account update
				when @product_type_id = 4 then  3 -- Upgrade - License capability update
			end

		-- 1.3) get license_category_id for product
		select @license_category_id_product = license_category_id
		from product_license_category 
		where product_id = @product_id

		-- 1.4) get current license_category_id, and if null calculate based on capability
		select @license_category_id = license_category_id
		from license_category_license
		where license_id = @license_id

		if @license_category_id is null
			begin
			select @license_category_id_calculated = dbo.fn_GetLicenseCategoryId(@license_id)
			end

		-- 1.5) seats
		select @license_seats_current = license_seats
		from license_seat 
		where license_id = @license_id

		if @product_line_id in (55,300)
			begin
				select @seats = quantity, 
						@contract_start_date = case
													when effective_date > @transaction_date then dateadd(dd,- datediff(dd,@transaction_date,effective_date),effective_date)
													else effective_date
												end,
						@contract_end_date = capability_expiration_date
				from order_item
				where order_item_id = @order_item_id 
					
				select @contract_days = datediff(dd,@contract_start_date,@contract_end_date)

			if @modified_by = 'license_service'
				begin
				select @seats = case when @capability_change_reason_id = 29 then lsv2.license_service_value else lsv2.license_service_value - @license_seats_current end
				from license_service_value lsv
				inner join license_service_value lsv2 on lsv.license_service_id = lsv2.license_service_id and lsv2.license_service_value_type_id = 6
				where lsv.license_service_value = @license_id
				and lsv.license_service_value_type_id = 1
				and lsv.license_service_id = (select max(lsv3.license_service_id) 
				                              from license_service_value lsv3 
											  where lsv3.license_service_value = lsv.license_service_value
											  and lsv3.license_service_value_type_id = 1)
				end

			if @seats is null 
				begin
				select @seats = @license_seats_current
				end
			end
		else
			begin
				select @seats = seats
				from product_seat
				w
here product_id = @product_id
			end

		-- 1.6) get base capability_id
		select @base_capability_id = base_capability_id
		from license_category
		where license_category_id = @license_category_id or license_category_id = @license_category_id_calculated
		
		select @capability_expiration_date = capability_expiration_date
		from license_capability 
		where license_id = @license_id and capability_id = @base_capability_id

			-- 1.6.1) correct delta between days and dates
			update license_capability
			set capability_activation_days = datediff(dd,capability_activation_date,capability_expiration_date)
			where license_id = @license_id and capability_activation_days <> datediff(dd,capability_activation_date,capability_expiration_date)

		-- 1.7) determine if keycode is a trial
		declare @trial int

		set @trial = (select count(*) 
				from license_capability c
				where license_id = @license_id and capability_id = @base_capability_id and capability_type_id in (2,3))

		-- 1.8) @product_license_module_id
		select @product_license_module_id = product_id
		from dbo.fn_license_select_product_license_module(@product_id)

		-- 1.9) @message_autorenewal_cycle_id
		select @message_autorenewal_cycle_id = message_autorenewal_cycle_id
		from product_autorenewal_cycle
		where product_id = @product_id

		-- 1.10) Utility license_attribute_license_value
		select @license_attribute_license_value = f.effective_value
		from dbo.fn_license_select_effective_object_table(@license_id, @transaction_date) f
		inner join dbo.license_attribute_license_value v
			on f.effective_value = v.license_attribute_license_value
		where (v.license_attribute_license_value_description like '%utility%'
		or  v.license_attribute_license_value_description like '%Perpetual%')
			--and f.license_category_id = 220 --endpoint only for now
			and f.effective_object_id = 2 --autobilling attribute

						
		if @license_attribute_license_value is not null
			begin
			select @contract_days = 365, @contract_end_date = dateadd(dd,365,@contract_start_date)
			end


		-- 1.7.1 don't add days to trial through CSI
--			if @update_source in ('CSI','CSI Type') and @trial > 0 
--				begin
--				return
--				end 

--		select license_category_id_calculated = @license_category_id_calculated
	
begin try

--	select product_type_id = @product_type_id, product_id = @product_id, capability_change_reason_id = @capability_change_reason_id

-- select capability_expiration_date = @capability_expiration_date, contract_start_date = @contract_start_date, contract_end_date = @contract_end_date, contract_days = @contract_days
--return

		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			-- 2.1 check to see if the current license has all capabilities

			select @new_capability_count = count(*)
			from fn_license_select_product_capability(@product_id,@update_source)
			where capability_id not in (select capability_id from license_capability where license_id = @license_id)	

			if @new_capability_count > 0
				begin
					-- 2.1.1) insert new capabilities
					insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
					select 	@license_id, 
						f.capability_id, 
						capability_type_id = 4, --f.capability_type_id, 
						capability_activation_days = 0,
						insert_date = @transaction_date,
						insert_by = @modified_by,
						modified_date = @tr
ansaction_date,
						modified_by = @modified_by		
					from fn_license_select_product_capability(@product_id,@update_source) f
					inner join capability c
						on f.capability_id = c.capability_id
					where product_id = @product_id and 
							f.capability_id not in (select capability_id from license_capability where license_id = @license_id)
					order by capability_sort_order

					-- 2.1.2) if renewal product change change reason to renewal with upgrade
					if @product_type_id = 2
						begin
						select @product_type_id = 17 -- Renewal w/ Upgrade - License capability update
						end
				end

			-- 2.1.2) Check to see if we are doing a storage upgrade without a storage capability
			select @storage_capability_count_product = count(*)
			from product_capability p
			where p.capability_id = 11 and p.product_id = @product_id

			select @product_storage_gb = storage_gb
			from product_storage
			where product_id = @product_id

			select @storage_capability_count = count(*)
			from license_capability
			where license_id = @license_id and capability_id = 11

--			select storage_capability_count = @storage_capability_count, storage_capability_count_product = @storage_capability_count_product, storage_gb = @product_storage_gb
--
--			-- if no product or license capability exist for storage then call upgrade product_ids
--			if @storage_capability_count = 0 and @storage_capability_count_product = 0 and @product_storage_gb > 0
--				begin
--					-- check to see if the upgrade needs to be for a ss or wav license
--					select @ss_check = count(*)
--					from license_capability 
--					where license_id = @license_id and capability_id in (1,2) and capability_type_id = 1
--
----					if @ss_check = 1
----						begin
----						exec usp_license_sub_renew_license_capability 67004, @keycode, 'load', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output
----						end
--					if @ss_check = 2
--						begin
--						exec usp_license_sub_renew_license_capability 67005, @keycode, 'load', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output
--						end
--				end
--			
--
			-- 2.3) create temp table and add data
			declare @temp_license_capability_update table (
				[license_capability_id] [int] NOT NULL,
				[license_id] [int] NOT NULL,
				[capability_id] [int] NOT NULL,
				[capability_type_id] [int] NOT NULL,
				[product_capability_type_id] [int] NULL,
				[capability_activation_days] [int] NULL,
				[capability_activation_date] [datetime] NULL,
				[capability_expiration_date] [datetime] NULL,
				[insert_date] [datetime] NOT NULL,
				[insert_by] [varchar](200) NOT NULL,
				[modified_date] [datetime] NOT NULL,
				[modified_by] [varchar](200) NOT NULL,
				[days_used] [int] NULL,
				[days_remaining] [int] NULL,
				[days_added] [int] NULL,
				[days_new] [int] NULL,
				[days_contiguous] [int] NULL,
				[last_days_contiguous] [int] NULL,
				[new_activation_date] [datetime] NULL
			) 

--select 'fn_license_select_product_capability', * from fn_license_select_product_capability(@product_id,@update_source)
			-- 2.3.1
			insert into @temp_license_capability_update (license_capability_id, license_id, capability_id, capability_type_id, product_capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, days_used, days_remaining, days_added, days_contiguous, last_days_contiguous, new_activation_date)
			select	l.license_capability_id, 
					l.license_id, 
					l.capability_id, 
					l.capability_type_id, 
					product_capability_type_id = isnull(f.capability_type_id,l.capability_type_id),
					l.capability_activation_days, 
					l.capability_activation_date, 
					l.capability_expiration_date, 
					l.insert_date, 
					l.insert_by, 
					l.mod
ified_date, 
					l.modified_by,
					days_used =  
							case 
								when datediff(dd,l.capability_activation_date,getdate()) > l.capability_activation_days then l.capability_activation_days
								else isnull(datediff(dd,l.capability_activation_date,getdate()),0)
							end,
					days_remaining = 0,
					days_added = 
							case 
								when f.capability_type_id is null and l.capability_id = 11 and l.capability_type_id <> 4 then isnull((select capability_activation_days from fn_license_select_product_capability(@product_id,@update_source) where capability_id = @base_capability_id),0)
								else isnull(f.capability_activation_days,0)
							end,
					days_contiguous = 0,
					last_days_contiguous = 0,
					new_activation_date = getdate()
			from license_capability l
			left join fn_license_select_product_capability(@product_id,@update_source) f
				on l.capability_id = f.capability_id
			where license_id = @license_id	


			-- 2.3.2) update days_remaining columns
				update @temp_license_capability_update
				set days_remaining = 
					case
						when capability_activation_days - days_used < 0 then capability_activation_days
						else isnull(capability_activation_days - days_used,0)
					end	

			-- 2.3.3) update days_new
				update @temp_license_capability_update
				set days_new = 
							case 
								when e.capability_ext_type_id is null then null		
								when @trial = 1 and t.product_capability_type_id not in (2,3) then days_remaining + days_added
								when days_remaining + days_added > 0 then days_remaining + days_added
								else 0
							end
				from @temp_license_capability_update t
				left join capability_ext e 
					on t.capability_id = e.capability_id and e.capability_ext_type_id = 1

--				select	'days_new', 
--						e.capability_ext_type_id,
--						t.capability_id,
--						days_new = 
--							case 
--								when e.capability_ext_type_id is null then null
--								when @trial = 1 then days_added
--								when days_remaining + days_added > 0 then days_remaining + days_added
--								else null
--							end
--				from @temp_license_capability_update t
--				left join capability_ext e 
--					on t.capability_id = e.capability_id and e.capability_ext_type_id = 1

				if (@update_source = 'upgrade' or @update_source = 'load' or @update_source = 'account' or @update_source = 'sstoav' or @update_source = 'downgrade') --and @product_type_id = 3 NOTE: Need to change back (no comment) for 7.0 cart
					begin
						select @max_days_new = max(days_new) from @temp_license_capability_update

						update @temp_license_capability_update
						set days_new =
									case 
										when product_capability_type_id <> 4 then @max_days_new
										else days_new
									end
						from @temp_license_capability_update t
						inner join capability_ext e 
							on t.capability_id = e.capability_id and e.capability_ext_type_id = 1

					end

				update @temp_license_capability_update
				set days_added = days_new
				where days_new > 0 and days_remaining = 0

			-- 2.3.4) update last_days_contiguous
				update @temp_license_capability_update
				set last_days_contiguous = 
							case 
								when (select top 1 days_contiguous from license_capability_history with (nolock) where license_capability_id = t.license_capability_id order by license_capability_history_id desc) is not null then (select top 1 days_contiguous from license_capability_history with (nolock) where license_capability_id = t.license_capability_id order by license_capability_history_id desc)
								else t.capability_activation_days
							end
				from @temp_license_capability_update t

			-- 2.3.5) update days_contiguous
				update @temp_license_capability_update
				set days_contiguous = 
							case
								when @trial = 1 and product_capability_type_id not in (2,3) then days_new 
								when last_days_contiguous + days_added <= 0 and days_used > 0 t
hen days_used
								when last_days_contiguous + days_added <= 0 then 0
								when days_remaining > 0 then last_days_contiguous + days_added
								when days_remaining = 0 then days_new
								else last_days_contiguous + days_added
							end

			-- 2.3.6) update new_activation_date NOTE: needed for renewals on expired licenses, and to insure that adding days to inactive licenses
			--											does not active the license
				declare @new_activation_date datetime

				select @new_activation_date = 
							case
								when capability_expiration_date < getdate() or days_new = 0 then getdate()
								else dateadd(dd,- isnull(days_remaining,0),capability_expiration_date)
							end
				from @temp_license_capability_update
				where capability_expiration_date is not null and capability_id = @base_capability_id

				--select * from @temp_license_capability_update
				--select new_activation_date = @new_activation_date
				--return
				
				update @temp_license_capability_update
				set new_activation_date = 
							case
								when e.capability_ext_type_id is null then null 
								when days_new > 0 then @new_activation_date
								when days_new = 0 and capability_expiration_date is not null then @new_activation_date	
								else null
							end
				from @temp_license_capability_update t
				left join capability_ext e 
					on t.capability_id = e.capability_id and e.capability_ext_type_id = 1

--				select	'new_activation_date', 
--						e.capability_ext_type_id,
--						t.capability_id,
--						new_activation_date = 
--							case
--								when e.capability_ext_type_id is null then null 
--								when days_new > 0 then @new_activation_date
--								when days_new = 0 and capability_expiration_date is not null then @new_activation_date	
--								else null
--							end
--				from @temp_license_capability_update t
--				left join capability_ext e 
--					on t.capability_id = e.capability_id and e.capability_ext_type_id = 1
--
 --select '@temp_license_capability_update', * from @temp_license_capability_update
--return
--select capability_activation_count = @capability_activation_count

			-- 2.4) insert rows into license_capability_audit
			
			--insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
			--select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = getdate(), audit_by = system_user
			--from license_capability
			--where license_id = @license_id

			-- 2.5) insert rows into license_capability_history
			if @product_type_id <> 4
				begin	
				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)
				select license_capability_id, license_id, capability_id, capability_type_id, 
					capability_activation_days = isnull(days_used,0), 
					capability_activation_date, 
					capability_expiration_date = case
													when @contract_start_date is not null then @contract_start_date
													else dateadd(dd,isnull(days_used,0),capability_activation_date)
												end, 
					insert_date, insert_by, modified_date, modified_by, 
					capability_change_reason_id = @capability_change_reason_id, 
					history_date = @transaction_date, history_by = @modified_by, 
					days_used = isnull(days_used,0), 
					days_remaining = isnull(days_remaining,
0), 
					days_added = isnull(days_added,0), 
					days_new = isnull(days_new,0), 
					days_contiguous = isnull(days_contiguous,0),
					order_item_id = @order_item_id
				from @temp_license_capability_update 
				where @order_item_id is not null or (product_capability_type_id <> capability_type_id or capability_activation_days <> days_new)

			-- 2.6) update license_capability 
				update license_capability
				set 
				--select 
					capability_type_id = 
							case
								when t.days_new > 0 and t.product_capability_type_id = 4 then c.capability_type_id
								else t.product_capability_type_id
							end,
					capability_activation_days = case 
													when @contract_start_date is not null and @contract_end_date is not null then datediff(dd,@contract_start_date,@contract_end_date)
													else t.days_new
												end,
					capability_activation_date = 
							case
								when @contract_start_date is not null then @contract_start_date
								when t.product_capability_type_id = 4 and (t.days_new = 0 or t.days_new is null) then null
								when (t.days_new = 0 or @capability_activation_count = 0) and new_activation_date is null then null
								else new_activation_date
							end,
					capability_expiration_date = 
							case
								when @contract_end_date is not null then @contract_end_date
								when t.product_capability_type_id = 4 and (t.days_new = 0 or t.days_new is null) then null
								when (t.days_new = 0 or @capability_activation_count = 0) and new_activation_date is null  then null
								else dateadd(dd,t.days_new,new_activation_date)
							end,
					modified_date = @transaction_date,
					modified_by = @modified_by
				from license_capability c
				inner join @temp_license_capability_update t
					on c.license_capability_id = t.license_capability_id	
				end
			--return

			-- 2.7) update or insert license_storage 
				 -- 2.7.1 get product storage 
					
				select @storage_gb = storage_gb
				from license_storage
				where license_id = @license_id

				-- 2.7.2 if product storage exist and license_storage does not exist
				if @product_storage_gb is not null and @storage_gb is null
					begin
						exec usp_license_insert_license_storage @license_id,@product_storage_gb,@order_item_id,@response_code OUTPUT,@message OUTPUT
					end

				-- 2.7.3 if product storage exist and license_storage does exist 
				if @product_storage_gb is not null and @storage_gb is not null		
					begin
						exec usp_license_update_license_storage @license_id,@product_storage_gb,@capability_change_reason_id,@order_item_id,@response_code OUTPUT,@message OUTPUT
					end				

				-- 2.7.4 if product storage not exist and license_storage does not exist - CSI path
				if @product_storage_gb is null and @storage_gb is not null
					begin
						-- 2.7.4.1) downgrade
						if @order_item_id is not null and @order_item_id <> 0
							begin
							select @storage_gb = 0
							end

						exec usp_license_update_license_storage @license_id,@storage_gb,@capability_change_reason_id,@order_item_id,@response_code OUTPUT,@message OUTPUT
					end

			-- 3.1) set effective_date
			set @effective_date = (select effective_date =
					case
						when @product_type_id = 3 then new_activation_date
						when @product_type_id = 2 and days_remaining = 0 then new_activation_date
						when @product_type_id = 2 and days_remaining > 0 and datediff(dd,capability_activation_date,dateadd(dd,isnull(days_used,0),capability_activation_date)) <> 0 then capability_expiration_date  
						else new_activation_date
					end
			from @temp_license_capability_update 
			where capability_id = @base_capability_id)

			-- 4.1) license_category
			if @license_category_id_product is not null and @product_type_id <> 4
				begin
					exec usp_license_update_license_category @license_id, @license_category_id_product, @capability_change_reason_id, @modified_by, @order_item
_id
				end	
			else
				begin
				if @license_category_id is null
					begin
					select @license_category_id = @license_category_id_calculated
					end

					exec usp_license_update_license_category @license_id, @license_category_id, @capability_change_reason_id, @modified_by, @order_item_id
				end	

			-- 5.1) license_seat
			if @seats is not null and @product_type_id <> 4
				begin
				exec usp_license_update_license_seats @license_id, @seats, @capability_change_reason_id, @order_item_id, @response_code, @message
				end

			-- 6.1) license_module_license
			if @product_license_module_id is not null
				begin
					-- 6.1.1) @module_seats
					select @module_seats = @seats, @license_change_reason_id = @capability_change_reason_id

					-- 6.1.2) @module_end_date for customer service
					if @license_change_reason_id = 4
						begin
							select @module_end_date = dateadd(dd,f.days,ml.end_date), @product_id = null, @license_module_id = ml.license_module_id
							from dbo.fn_license_select_product_license_module(@product_id) f
							inner join license_module_license ml
								on f.product_id = ml.license_id and f.license_module_id = ml.license_module_id
						end

					-- select '6.1) license_module_license', licnese_id = @license_id, product_id = @product_id, license_change_reason_id = @capability_change_reason_id, order_item_id = @order_item_id, license_module_id = @license_module_id, module_seats = @module_seats, module_end_date = @module_end_date, modified_by = @modified_by
				
					-- 6.1.3) usp_license_update_license_module_license
					exec usp_license_update_license_module_license @license_id, @product_id, @license_change_reason_id, @order_item_id, @module_seats,  @license_module_id, @module_end_date, @modified_by
				end

			-- 7.1) re-enable license_status_id if manually disabled
			if @license_status_id in (2) 
				begin
					insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
					select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @capability_change_reason_id, @transaction_date, @modified_by
					from license
					where license_id = @license_id

					update license
					set license_status_id = 1,


						modified_date = @transaction_date,
						modified_by = @modified_by
					where license_id = @license_id
				end			
			
			-- 8.1) usp_license_insert_license_cart
			if @message_autorenewal_cycle_id is not null
				begin
					exec usp_license_update_license_autorenewal_cycle @license_id, @message_autorenewal_cycle_id, @billing_day_of_month, @product_type_id
				end
				
			-- 	9.1) update max_child_licenses
			if @license_type_id = 2 and @max_child_licenses <> @seats
				begin
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
				select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @capability_change_reason_id, @transaction_date, @modified_by
				from license
				where license_id = @license_id

				update license
				set max_chil
d_licenses = @seats,
					modified_date = @transaction_date,
					modified_by = @modified_by
				where license_id = @license_id
				END
                
			-- 9.2) license_renewals
			if @capability_change_reason_id = 2 
				begin
					select @order_header_id = order_header_id from order_item where order_item_id = @order_item_id
					insert into license_renewals(license_id,order_header_id_1)
					select distinct u.license_id, @order_header_id
					from @temp_license_capability_update u
					where not exists (select * from license_renewals l where u.license_id = l.license_id)
				end 

			-- 9.1) insert message

			--declare @load_type int, 
			--		@dbsource varchar(100)
					
			--select @dbsource = db_name(),
			--		@load_type = 0

			--exec [tasks].[dbo].[usp_Licensing_Send_Tasks] @license_id = @license_id,@load_type=@load_type,@dbsource = @dbsource

			-- 10.1) cleanup
			delete from product_capability_working where product_id = @product_id
			delete from product_license_module_working where product_id = @product_id

			select response_code = @response_code, message = @message
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_update_full_to_trial]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_sub_update_full_to_trial]
(
	@keycode varchar(40),
	@license_distribution_method_id int = NULL,
	@license_seats int = NULL,
	@modified_by varchar(20),
	@license_id int output,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2016-04-11		acoffel		Initial creation
	2019-11-12		cnovac		Added code to write to license contract

	DESCRIPTION
	complete update of full to trial
*/

AS
set nocount on				

begin try
	
	declare @parent_capability_expiration_date datetime,
			@storage_account int,
			@subscription_id int,
			@base_capability_id int,
			@license_distribution_method_id_existing int,
			@existing_nfr varchar(40),
			@transaction_date datetime,
			@capability_change_reason_id int,
			@parent_license_id int,
			@license_status_id int, 
			@capability_activation_days int,
			@capability_activation_date datetime, 
			@capability_expiration_date datetime,
			@capability_type_id int,
			@license_contract_json varchar(max)
	declare @license_contract_object table (license_id int, license_category_id tinyint, license_category_type_id int, license_start_date date, license_end_date date)

	select @transaction_date = getdate(), @capability_change_reason_id = 30

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) verify keycode
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) get license info
	select @license_id = license_id
	from license 
	where keycode = @keycode
	and license_status_id = 1

	-- 1.1) escape if keycode is not valid
	if @license_id is NULL 
		begin 
			select @license_id = l.license_id 
			from license_keycode_alias a
			inner join license l
				on a.license_id = l.license_id and l.license_status_id = 1
			where @keycode = keycode_alias
				if @license_id is NULL
					begin 
						select @license_id = NULL, @response_code = -110, @message = 'Invalid License'
						return
					end
		end


	-- 1.2) Verify that it's not S2
		if (select subscription_id from subscription where license_id = @license_id) is not NULL
			begin 
				select @license_id = NULL, @response_code = -110, @message = 'Cannot convert S2 license to NFR'
				return
			end		

	-- 1.3) Verify that it's not S2
		if (select license_distribution_method_id from license where license_id = @license_id) = 973
			begin 
				select @license_id = NULL, @response_code = -110, @message = 'Child keycode is already NFR'
				return
			end	

	-- 1.4) Verify that it's not S2
		if (select license_type_id from license where license_id = @license_id) = 2
			begin 
				select @license_id = NULL, @response_code = -110, @message = 'Parent keycodes cannot be converted to NFR'
				return
			end	

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) license detail 
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
	-- 2.0) select parent license values
	select @license_status_id = l.license_sta
tus_id, 
			@capability_activation_days = c.capability_activation_days,
			@capability_activation_date = c.capability_activation_date, 
			@capability_expiration_date = c.capability_expiration_date,
			@capability_type_id = c.capability_type_id,
			@parent_license_id = p.parent_license_id
	from license l
	inner join license_category_license cl
		on l.license_id = cl.license_id
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	inner join license_capability c
		on l.license_id = c.license_id and c.capability_id = lc.base_capability_id
	left join license_parent p	
		on l.license_id = p.child_license_id 
	where l.license_id = @license_id

	
	-- 2.1) parent license values
	if @parent_license_id is not NULL
		begin 
			select @parent_capability_expiration_date = c.capability_expiration_date
			from license l
			inner join license_category_license cl
				on l.license_id = cl.license_id
			inner join license_category lc
				on cl.license_category_id = lc.license_category_id
			inner join license_capability c
				on l.license_id = c.license_id and c.capability_id = lc.base_capability_id
			where c.license_id = @parent_license_id
				-- 2.2) Co-term to parent if parent key expires after child
				if @parent_capability_expiration_date > @capability_expiration_date
					begin 
						select @capability_expiration_date = @parent_capability_expiration_date
					end
		end

	-- 2.2) parent license values
	if @parent_license_id is not NULL
		begin 
			select @existing_nfr = keycode 
			from license l 
			inner join license_parent p
				on l.license_id = p.child_license_id
			where p.parent_license_id = @parent_license_id and l.license_distribution_method_id = 973
				if @existing_nfr is not NULL
					begin 
						select @license_id = NULL, @response_code = -110, @message = 'NFR child already exists for this Parent'								return
					end
		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set up capability data
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	declare @license_capability_update table (license_capability_id int NOT NULL,license_id int NOT NULL,capability_id int NOT NULL,capability_type_id int NOT NULL,product_capability_type_id int NULL,capability_activation_days int NULL,capability_activation_date datetime NULL,capability_expiration_date datetime NULL,insert_date datetime NOT NULL,insert_by varchar(50) NOT NULL,modified_date datetime NOT NULL,modified_by varchar(50) NOT NULL,days_used int NULL default 0,days_remaining int NULL default 0,days_added int NULL default 0,days_new int NULL default 0,days_contiguous int NULL default 0,last_days_contiguous int NULL default 0,new_activation_date datetime NULL,license_status_id int NOT NULL, license_distribution_method_id int NOT NULL)	

	-- 3.0) get child license_data
	insert into @license_capability_update(license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, license_status_id, license_distribution_method_id)
	select c.license_capability_id, c.license_id, c.capability_id, c.capability_type_id, c.capability_activation_days, c.capability_activation_date, c.capability_expiration_date, c.insert_date, c.insert_by, c.modified_date, c.modified_by, l.license_status_id, m.license_distribution_method_id
	from license l
	inner join license_category_license cl
		on l.license_id = cl.license_id
	inner join license_category lc
		on cl.license_categ
ory_id = lc.license_category_id
	inner join license_capability c
		on l.license_id = c.license_id and c.capability_id = lc.base_capability_id
	inner join license_distribution_method m
		on l.license_distribution_method_id = m.license_distribution_method_id
	where l.license_id = @license_id 

	-- 3.1) days_used
		update @license_capability_update
		set days_used = datediff(dd,capability_activation_date,getdate())

	-- 3.2) days_remaining
		update @license_capability_update
		set days_remaining = datediff(dd,getdate(),capability_expiration_date)

	-- 3.3) days_added
		update @license_capability_update
		set days_added = datediff(dd,capability_expiration_date,@capability_expiration_date)

	-- 3.4) days_new
		update @license_capability_update
		set days_new = days_remaining + days_added

	-- 3.4) days_contiguous
		update @license_capability_update
		set days_contiguous = days_new


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 4.0) license distribution method changes
		if @license_distribution_method_id is not NULL
			begin 
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
				select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @capability_change_reason_id, @transaction_date, @modified_by
				from license
				where license_id = @license_id

				update license set modified_date = getdate(), modified_by = 'dist_method_change', license_distribution_method_id = @license_distribution_method_id where license_id = @license_id
			end

		
		
		-- 4.1) insert history			
		insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)
		select license_capability_id, license_id, capability_id, capability_type_id, 
			capability_activation_days = isnull(days_used,0), 
			capability_activation_date, 
			capability_expiration_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
			insert_date, insert_by, modified_date, modified_by, 
			capability_change_reason_id = @capability_change_reason_id, 
			history_date = @transaction_date, history_by = @modified_by, 
			days_used = isnull(days_used,0), 
			days_remaining = isnull(days_remaining,0), 
			days_added = isnull(days_added,0), 
			days_new = isnull(days_new,0), 
			days_contiguous = isnull(days_contiguous,0),
			order_item_id = NULL
		from @license_capability_update 


		-- 4.2) update
		update license_capability
		set capability_type_id = 2,
			capability_activation_days = datediff(dd,dateadd(dd,isnull(days_used,0),t.capability_activation_date),@capability_expiration_date), --@capability_activation_days,
			capability_activation_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), --@capability_activation_date,
			capability_expiration_date = @capability_expiration_date,
			modified_date = @transaction_da
te,
			modified_by = @modified_by
		output Inserted.license_id, Inserted.capability_type_id, Inserted.capability_activation_date, Inserted.capability_expiration_date into @license_contract_object(license_id, license_category_type_id, license_start_date, license_end_date)
		from license_capability c
		inner join @license_capability_update t
			on c.license_capability_id = t.license_capability_id

		--set the primary license category
		update lco
		set license_category_id = lcl.license_category_id
		from @license_contract_object lco
		inner join license_category_license lcl on lcl.license_id = lco.license_id


		-- 4.3) insert license_seat history
		insert into license_seat_history(license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by, order_item_id)
		select s.license_seat_id, s.license_id, s.license_seats, s.seats_used,  
				s.start_date, 
				end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
				s.insert_date, s.insert_by, s.modified_date, s.modified_by, 
				license_change_reason_id = @capability_change_reason_id, history_date = @transaction_date, history_by = @modified_by,
				order_item_id = NULL
		from license_seat s
		inner join @license_capability_update t
			on s.license_id = t.license_id

		-- 4.4) update license_seat
		update license_seat
		set	license_seats = isnull(@license_seats,s.license_seats),
			start_date = @capability_activation_date,
			end_date = @capability_expiration_date,
			modified_date = @transaction_date,
			modified_by = @modified_by
		from license_seat s
		inner join @license_capability_update t
			on s.license_id = t.license_id


		-- 4.5) insert history
		insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date, history_by, order_item_id)
		select c.license_category_license_id, c.license_id, c.license_category_id, 
			c.start_date, 
			end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
			c.last_modified_date, c.last_modified_by, 
			license_change_reason_id = @capability_change_reason_id, history_date = @transaction_date, history_by = @modified_by, order_item_id = NULL
		from license_category_license c
		inner join @license_capability_update t
			on c.license_id = t.license_id

		-- 4.6) update
		update license_category_license
		set	start_date = @capability_activation_date,
			end_date = @capability_expiration_date,
			last_modified_date = @transaction_date,
			last_modified_by = @modified_by
		from license_category_license s
		inner join @license_capability_update t
			on s.license_id = t.license_id


		--build up the JSON now based on data in @license_contract_object only for business licenses
		select @license_contract_json = (
		select license_id = lco.license_id, license_category_id = lco.license_category_id, license_category_type_id = lco.license_category_type_id, license_start_date = lco.license_start_date, license_end_date = lco.license_end_date, 
			   originating_license_contract_id = fn.license_contract_id
		from @license_contract_object lco
		inner join license l on l.license_id = lco.license_id
		outer apply fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
		where l.product_line_id in (55, 300)
		for json path)

		--if data exists, call the insert now
		if @license_contract_json is not null
		begin
			exec usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_sub_update_full_to_trial'
		end


end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'full to trial update failed @keycode = ' + isnull(@keycode,'')
						else
 @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_sub_update_trial_to_full]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_sub_update_trial_to_full]
(
	@product_id int,
	@keycode varchar(40),
	@update_source varchar(10),
	@modified_by varchar(20),
	@order_item_id int,
	@effective_date datetime output,
	@license_id int output,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-12-12		esmart		Initial creation
	2011-12-20		esmart		Change to support enterprise trial-to-full
	2012-03-22		esmart		Add order_item_id to license_capability_history to allow better refund logic
	2012-05-31		esmart		Add support for Trial license_module
	2012-10-24		esmart		add autorenewal_cycle support
	2012-11-09		esmart		add enterprise mobile seat
	2013-07-07		esmart		downgrade trial
	2014-03-25		esmart		Lookup contract start/end date from item
	2016-01-25		esmart		Add usp_license_update_license_autorenewal_cycle sub
	2016-11-02		esmart		Check billing model for utility
	2017-05-22		cnovac		Added call to usp_license_insert_effective_object
	2018-04-22		cnovac		Updated call to usp_license_insert_effective_object
	2018-09-07		rvinoche	Allow past record updates when calling usp_license_insert_effective_object
	2019-09-06		cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2021-12-09		psatish		Added Perpetual billing model to update the Contract end date
	DESCRIPTION
	complete update of trial to full
*/

AS
set nocount on				

begin try
	
	declare @backup_capability int,
			@storage_account int,
			@new_capability_count int,
			@transaction_date datetime,
			@system_user varchar(20),
			@backup_license_capability_id int,
			@storage_gb int,
			@product_storage_gb int,
			@license_category_id_product tinyint,
			@license_category_id_calculated tinyint,
			@license_category_id tinyint,
			@capability_change_reason_id int,
			@license_seats_current int,	
			@seats int,
			@base_capability_id int,
			@product_line_id int,
			@message_autorenewal_cycle_id tinyint,
			@license_attribute_license_value int,
			@billing_day_of_month tinyint,
			@product_type_id int,
			@license_type_id int,
			@max_child_licenses int,
			@capability_expiration_date datetime,
			@contract_start_date datetime,
			@contract_end_date datetime,
			@contract_days int,
			@effective_start_date date,
			@license_effective_object_json varchar(max)
			
	select @transaction_date = getdate(), @capability_change_reason_id = 14

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
			-- 1.1) Does the new product have backup capability
			select @backup_capability = count(*)
			from product_capability 
			where product_id = @product_id and capability_id = 11

			select @license_id = license_id, @product_line_id = product_line_id, @license_type_id = license_type_id, @max_child_licenses = max_child_licenses
			from license 
			where keycode = @keycode

			select @effective_start_date = effective_date
			from order_item
			where order_item_id = @order_item_id
			
			-- 1.1) Check to see if storage_account on trial has been activated
			select @storage_account = count(*)
			from license_storage s
			inner join storage_account a
				on s.license_storage_id = a.license_storage_id
			where s.license_id = @license_id
			
--				
	if @storage_account > 0 and @backup_capability = 0
--						begin
--						select 'extended backup capability'
--						end
					if @storage_account = 0 and @backup_capability = 0
						begin
						delete from license_capability_history where license_id = @license_id and capability_id = 11
						delete from license_capability where license_id = @license_id and capability_id = 11
--						select 'remove backup capability'
						end	

			-- 1.2) check to see if new product has additional capabilities
			select @new_capability_count = count(*)
			from product_capability
			where capability_id not in (select capability_id from license_capability where license_id = @license_id) and
				product_id = @product_id

			-- 1.3) validate modified by
			if @modified_by is null or @modified_by = ''
				begin
				select @modified_by = suser_sname()
				end 
				
			-- 1.4) get license_category_id for product
			select @license_category_id_product = license_category_id
			from product_license_category 
			where product_id = @product_id

			-- 1.5) get current license_category_id, and if null calculate based on capability
			select @license_category_id = license_category_id
			from license_category_license
			where license_id = @license_id

			if @license_category_id is null
				begin
				select @license_category_id_calculated = dbo.fn_GetLicenseCategoryId(@license_id)
				end

			-- 1.6) get base capability_id
			select @base_capability_id = base_capability_id
			from license_category
			where license_category_id = @license_category_id or license_category_id = @license_category_id_calculated

			select @capability_expiration_date = capability_expiration_date
			from license_capability 
			where license_id = @license_id and capability_id = @base_capability_id

			-- 1.7) @message_autorenewal_cycle_id
			select @message_autorenewal_cycle_id = message_autorenewal_cycle_id
			from product_autorenewal_cycle
			where product_id = @product_id

			-- 1.8) seats
			select @license_seats_current = license_seats
			from license_seat 
			where license_id = @license_id

			if @product_line_id in (300,55)
				begin
					select @seats = quantity, 
							@contract_start_date = case
														when effective_date > @transaction_date then dateadd(dd,- datediff(dd,@transaction_date,effective_date),effective_date)
														else effective_date
													end,
							@contract_end_date = capability_expiration_date
					from order_item
					where order_item_id = @order_item_id 
					
					select @contract_days = datediff(dd,@contract_start_date,@contract_end_date)

					
					if @seats is null 
						begin
						select @seats = @license_seats_current
						end
				end
			else
				begin
					select @seats = seats
					from product_seat
					where product_id = @product_id
				end
	
			-- 1.9) Utility license_attribute_license_value
			select @license_attribute_license_value = al.license_attribute_license_value
			from license_attribute_license al
			inner join license_attribute_license_value v
				on v.license_attribute_license_value = al.license_attribute_license_value
			where license_id = @license_id and v.license_attribute_license_value_description like '%utility%'
			or  v.license_attribute_license_value_description like '%Perpetual%'
						
			if @license_attribute_license_value is not null
				begin
				select @contract_days = 365, @contract_end_date = dateadd(dd,365,@contract_start_date)
				end

			--select license_attribute_license_value = @license_attribute_license_value
			--return

--select license_seats_current = @license_seats_current, seats = @seats
--
--select @license_category_id_calculated

--select capability_expiration_date = @capability_expiration_date, contract_start_date = @contract_start_date, contract_end_date = @contract_end_date, contract_days = @contract_days
--return


	-- ----------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
			-- 2.1) check to see if the product has new capabilities not on the license
			if @new_capability_count > 0
				begin
					insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
					select 	@license_id, 
						capability_id, 
						capability_type_id = 4, 
						capability_activation_days = 0,
						insert_date = getdate(),
						insert_by = @modified_by,
						modified_date = getdate(),
						modified_by = @modified_by		
					from product_capability
					where product_id = @product_id and 
							capability_id not in (select capability_id from license_capability where license_id = @license_id)	
				end

--select storage_account = @storage_account, new_capability_count = @new_capability_count, backup_capability = @backup_capability

			-- 2.3) delete backup capability if needed
			if @storage_account = 0 and @backup_capability = 0
				begin
				select @backup_license_capability_id = license_capability_id from license_capability where license_id = @license_id and capability_id = 11
				
				delete from license_capability_history where license_capability_id = @backup_license_capability_id		
				delete from license_capability where license_capability_id = @backup_license_capability_id	
				end

			-- 2.2 add rows to history
				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)
				select 	l.license_capability_id, 
					l.license_id, 
					l.capability_id, 
					l.capability_type_id, 
					l.capability_activation_days, 
					l.capability_activation_date, 
					capability_expiration_date = 
						case 
							when @contract_start_date is not null then @contract_start_date
							when l.capability_expiration_date is null then null
							when l.capability_expiration_date < @transaction_date then l.capability_expiration_date
							else dateadd(dd,-(datediff(dd,@transaction_date,l.capability_expiration_date)),l.capability_expiration_date)
						end, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by, 
					capability_change_reason_id = @capability_change_reason_id,
					@transaction_date, 
					@modified_by, 
					days_used = l.capability_activation_days - isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0),  
					days_remaining = 
								case 
									when datediff(dd,@transaction_date,l.capability_expiration_date) < 0 then 0
									else isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
								end, 
					days_added = 
								case 
									when @storage_account > 0 and @backup_capability = 0 and l.capability_id = 11 then (select capability_activation_days from product_capability where product_id = @product_id and capability_id = @base_capability_id)
									else isnull(c.capability_activation_days,0)
								end, 
					days_new = 
								case 
									when @storage_account > 0 and @backup_capability = 0 and l.capability_id = 11 then (select capability_activation_days from product_capability where product_id = @product_id and capability_id = @base_capability_id)
									else isnull(c.capab
ility_activation_days,0)
								end,
					days_contiguous = 
								case 
									when @storage_account > 0 and @backup_capability = 0 and l.capability_id = 11 then (select capability_activation_days from product_capability where product_id = @product_id and capability_id = @base_capability_id)
									else isnull(c.capability_activation_days,0)
								end,
					@order_item_id
				from license_capability l
				left join product_capability c
					on c.capability_id = l.capability_id and c.product_id = @product_id
				where license_id = @license_id		
 
				-- 2.1.4 correct discrepancy 
				update license_capability
				set 	
				--select
					capability_type_id = 
								case 
									when c.capability_type_id is null then 4
									when c.capability_id in (11,17) and l.capability_type_id = 1 then 1
									else c.capability_type_id
								end, 	
					capability_activation_days = 
								case 
									when @contract_days is not null then @contract_days
									when @storage_account > 0 and @backup_capability = 0 and l.capability_id = 11 then (select capability_activation_days from product_capability where product_id = @product_id and capability_id = @base_capability_id)
									else isnull(c.capability_activation_days,0)
								end, 
					capability_activation_date = 
								case 
									when @contract_start_date is not null then @contract_start_date
									when e.capability_ext_type_id is null then null 
									when c.capability_type_id <> 4 or l.capability_id = 11 then @transaction_date
									else null
								end, 
					capability_expiration_date = 
								case 
									when @contract_end_date is not null then @contract_end_date
									when e.capability_ext_type_id is null then null 
									when c.capability_type_id <> 4 or l.capability_id = 11 then dateadd(dd,(select capability_activation_days from product_capability where product_id = @product_id and capability_id = @base_capability_id),@transaction_date)
									else null
								end, 
					modified_date = @transaction_date, 
					modified_by = @modified_by
				from  license_capability l
				left join product_capability c 
					on c.capability_id = l.capability_id and c.product_id = @product_id
				left join capability_ext e 
					on l.capability_id = e.capability_id and e.capability_ext_type_id = 1
				where license_id = @license_id

				-- 2.1.5 Check to see if license storage exist and is needed
				select @storage_gb = storage_gb
				from license_storage
				where license_id = @license_id

				select @product_storage_gb = storage_gb
				from product_storage
				where product_id = @product_id

					-- 2.1.5.1 if product storage exist and license_storage does not exist
					if @product_storage_gb is not null and @storage_gb is null
						begin
							exec usp_license_insert_license_storage @license_id,@product_storage_gb,@order_item_id,@response_code OUTPUT,@message OUTPUT
						end

					-- 2.1.5.2 if product storage exist and license_storage does exist 
					if @product_storage_gb is not null and @storage_gb is not null		
						begin
							exec usp_license_update_license_storage @license_id,@product_storage_gb,14,@order_item_id,@response_code OUTPUT,@message OUTPUT
						end			

					-- 2.1.5.2 if product storage does not exist and license_storage does exist 
					if @product_storage_gb is null and @storage_gb is not null		
						begin
							exec usp_license_update_license_storage @license_id,@product_storage_gb,14,@order_item_id,@response_code OUTPUT,@message OUTPUT
						end			

				-- 2.1.6) license_category
					if @license_category_id_product is not null 
						begin
							exec usp_license_update_license_category @license_id, @license_category_id_product, @capability_change_reason_id, @modified_by, @order_item_id
						end	
					else
						begin
							if @license_category_id is null
								begin
								select @license_category_id = @license
_category_id_calculated
								end
							exec usp_license_update_license_category @license_id, @license_category_id, @capability_change_reason_id, @modified_by, @order_item_id
						end

				-- 2.1.6.2) check to see if the baseline license category has been set. If not set the initial row
					if @license_category_id_product is not null and @license_category_id is null and @order_item_id is not null
						begin
							insert into license_category_license_history(license_category_license_id, license_id, license_category_id, order_item_id, last_modified_date, last_modified_by, license_change_reason_id)
							select license_category_license_id, license_id, @license_category_id_calculated, @order_item_id, last_modified_date, last_modified_by, @capability_change_reason_id
							from license_category_license
							where license_id = @license_id
						end
				

		-- 3.1) license_seat
		if @seats is not null
		begin
			exec usp_license_update_license_seats @license_id, @seats, @capability_change_reason_id, @order_item_id, @response_code, @message

			-- 3.1.1) write to license_effective_object if business product
			if @product_line_id in (55, 300)
			begin

				select @license_effective_object_json = (
				select license_id = @license_id, license_category_id = @license_category_id, license_seats = @seats, effective_start_date = isnull(@effective_start_date, @transaction_date), order_item_id = @order_item_id
				for json path)

				exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_sub_update_trial_to_full'

			end
		end
				
		-- 4.1) license_module_license
		declare @license_module_license_id int
	
		select @license_module_license_id = ml.license_module_license_id from license_module_license ml inner join license_module m on ml.license_module_id = m.license_module_id where ml.license_id = @license_id and  m.license_module_code = 'Trial'
		
		if @license_module_license_id is not null
			begin
			insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date)
			select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
					m.start_date, 
					end_date = dateadd(dd,(datediff(dd,start_date,getdate())),m.start_date),
					m.last_modified_date, m.last_modified_by, @order_item_id, @capability_change_reason_id, @transaction_date
			from license_module_license m
			where license_module_license_id = @license_module_license_id
			order by license_module_license_id

			delete from license_module_license
			where license_module_license_id = @license_module_license_id
			end

		-- 5.1) usp_license_insert_license_cart
		if @message_autorenewal_cycle_id is not null
			begin
				exec usp_license_update_license_autorenewal_cycle @license_id, @message_autorenewal_cycle_id, @billing_day_of_month, @product_type_id
			end

		-- 6.1) update max_child_licenses
		if @license_type_id = 2 and @max_child_licenses <> @seats
			begin
			insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
			select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @capability_change_reason_id, @transaction_date, @modified_by
			from license
			where license_id = @license_id

			update license
			s
et max_child_licenses = @seats,
				modified_date = @transaction_date,
				modified_by = @modified_by
			where license_id = @license_id
			end
		

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;










GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_swap_history]
-- =============================================================================

CREATE PROCEDURE usp_license_swap_history

(
	@license_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2006-11-10		esmart			Initial creation

	DESCRIPTION
	Get swap records for a license
*/

AS


	select license_swap_id, 
		original_license_id, 
		original_keycode = l.keycode, 
		new_license_id, 
		new_keycode = l2.keycode, 
		s.insert_date
	from license_swap s
	inner join license l
		on l.license_id = s.original_license_id
	inner join license l2
		on l2.license_id = s.new_license_id
	where original_license_id = @license_id or new_license_id = @license_id

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_swap_keycode]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_swap_keycode]

(
	@keycode varchar(40),
	@new_keycode varchar(40)
)

/*	
	DATE			AUTHOR		REMARKS
	2006-06-26		esmart			Initial creation
	2006-10-02		esmart			Modifications to support license_capability_history
	2006-10-24		esmart			Add check on keycode inputs. 1.) @keycode cannot be the same as @new_keycode, 2.) license_status_id on original keycode cannot be disabled
	2006-10-30		esmart			Add check for @new_keycode. If new keycode is already activated do not allow swap.
	2006-11-08		esmart			Modified days_added for new_license for license_capabiity_history
	2006-11-22		esmart			Add check for new license that was just activated. In this case allow the swap.
	2006-11-27		esmart			Correct days_added and days_remaining for license_capability_history
	2007-02-13		esmart			Add check for site license keycodes. Restrict swap in these instances. Site license will be defined as a license with license_type_id = 1 and
										max_child_license > 0. This is a temporary fix until we can implement better logic for site license/OEM licenses.
	2007-03-20		esmart			Add lookup into license_feature for no swap
	2007-12-26		ybarkalov		TTP 13820: Added check for disabled (turned OFF) or missing SS capability on original or new license;
											prevent swap when the new kc is Non-SS and swap without capability transfer when 
									Re-numbered validation steps and response codes
	2008-07-16		esmart			Correct issues with mismatched capabilities to support WISE
	2008-10-10		esmart			Update to use new license capability update methods
	2010-01-06		dsmelker		Add check to validate the new and old keycodes are the same product, storage, and seats.
	2010-11-08		esmart			Add check for license associated with another account.	
	2011-03-08		esmart			Add support for Android. 
	
	DESCRIPTION
	Takes a the remaining days from an existing keycode and applies them to a new keycode
*/

AS
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 1.) get license data for two keycodes
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set nocount on

begin try

	declare @original_license_id int,
		@customer_id int,
		@original_product_type_id int,
		@original_license_status_id int,
		@original_license_type_id int,
		@original_max_child_licenses int,
		@original_no_swap int,
		@original_account_id int,
		@new_license_id int,
		@new_license_type_id int,
		@new_license_type_id_output int,
		@new_max_child_licenses int,
		@new_days_used int,
		@new_no_swap int,
		@new_account_id int,
		@product_line_id int,
		@license_change_reason_id int,
		@transaction_date datetime,
		@system_user varchar(50),
		@product_type_id int,
		@license_status_id int,
		@original_ss_capability_type_id int,
		@new_ss_capability_type_id int,
		@response_code int,
		@message varchar(100),
		@effective_date datetime,
		@modified_by varchar(20),
		@order_item_id int,
		@orig_category varchar(20),
		@orig_seats varchaR(20),
		@orig_storage varchar(20),
		@new_category varchar(20),
		@new_seats varchaR(20),
		@new_storage varchar(20)
	

	set @modified_by = suser_sname()
		
	-- 1.0) get new license
	select @new_license_id = l.license_id,
		@product_line_id = product_line_id,
		@new_license_type_id = license_type_id,
		@license_status_id = license_status_id,
		@new_max_child_licenses = isnull(max_child_licenses,0),
		@new_no_swap =
			case
				when lf.license_feature_id i
s null then 0
				else 1
			end, 
		@new_account_id = al.account_id
	from license l
	left join license_feature_license lf
		on l.license_id = lf.license_id and lf.license_feature_id = 5
	left join account_license al
		on l.license_id = al.license_id
	where keycode = @new_keycode

	if @new_license_id is null
		begin
			set @response_code = -100
			set @message = 'new keycode not found'
			select swap_success = 0
			return
		end

	-- 1.1) get original license
	select @original_license_id = l.license_id,
		@customer_id = customer_id,
		@original_product_type_id = product_line_id,
		@original_license_status_id = license_status_id,
		@original_license_type_id = license_type_id,
		@original_max_child_licenses = isnull(max_child_licenses,0),
		@original_no_swap =
			case
				when lf.license_feature_id is null then 0
				else 1
			end, 
		@original_account_id = al.account_id
	from license l
	left join license_feature_license lf
		on l.license_id = lf.license_id and lf.license_feature_id = 5
	left join account_license al
		on l.license_id = al.license_id
	where keycode = @keycode

	-- 1.2) get original license SS capability type
	select
		@original_ss_capability_type_id = lc.capability_type_id
	from license_capability lc
	where license_id = @original_license_id
		and capability_id = 1

	-- 1.3) get new license SS capability type
	select
		@new_ss_capability_type_id = lc.capability_type_id
	from license_capability lc
	where license_id = @new_license_id
		and capability_id = 1

	-- 1.4) check license category, seats, and storage
		declare @keycode_orig table
		(cart_item_in_process_ext_type_id tinyint,
		 ext_type_name varchar(100),
		 ext_type_value varchaR(100))

		insert into @keycode_orig
		exec dbo.usp_cart_select_license_ext_types @keycode


		declare @keycode_new table
		(cart_item_in_process_ext_type_id tinyint,
		 ext_type_name varchar(100),
		 ext_type_value varchaR(100))

		insert into @keycode_new
		exec dbo.usp_cart_select_license_ext_types @new_keycode

		select	@orig_category=max(isnull(category,' ')),
				@orig_seats=max(isnull(seats,' ')),
				@orig_storage=max(isnull(storage,' '))
		from
			(select case when cart_item_in_process_ext_type_id = 1 then ext_type_value end category,
					case when cart_item_in_process_ext_type_id = 2 then ext_type_value end seats,
					case when cart_item_in_process_ext_type_id = 3 then ext_type_value end storage
			 from @keycode_orig ko) tbl

		select	@new_category=max(isnull(category,' ')), 
				@new_seats=max(isnull(seats,' ')),
				@new_storage=max(isnull(storage,' '))
		from
		(select case when cart_item_in_process_ext_type_id = 1 then ext_type_value end category,
				case when cart_item_in_process_ext_type_id = 2 then ext_type_value end seats,
				case when cart_item_in_process_ext_type_id = 3 then ext_type_value end storage
		 from @keycode_new ko) tbl

--			select orig_category = @orig_category, new_category = @new_category
		-- 1.4.1) check for Android license_category and call subroutine
		if @orig_category in( 'AD','ADP') and @new_category in( 'AD','ADP')
			begin
--			select '1.4.1'
			declare @account_user_name varchar(100), @phone_number varchar(64), @device_guid varchar(50)
		
			select @account_user_name = a.account_user_name, @phone_number = d.phone_number, @device_guid = d.device_guid
			from account a
			inner join account_device d
				on a.account_id = d.account_id
			where d.license_id = @original_license_id

			if @account_user_name is not null
				begin
					declare @update_result table (response_code int, message varchar(50))
	
					insert into @update_result(response_code,message)			
					exec usp_account_update_account_device @account_user_name, @new_keycode, @phone_number, @device_guid
				end

			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)

			select swap_success = 1
			return			
			end

	-- 1.5)  check to see if the original keycode doesn't 
exist
	if @original_license_id is null
		begin
			set @response_code = -110
			set @message = 'keycode not found'
			select swap_success = 1
			return
		end

	-- 1.6)  check to see if original keycode is disabled
	if @original_license_status_id in (2,3)
		begin
			set @response_code = -120
			set @message = 'original license is disabled. no swap allowed'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.7)  check to see if the swap request is for the matching keycodes
	if @new_license_id = @original_license_id
		begin
			set @response_code = -130
			set @message = 'keycode cannot be swapped for itself'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.8) check for trial or OEM
	if @new_license_type_id in (2,3) or @original_license_type_id in (2,3)
		begin
			set @response_code = -140
			set @message = 'trial or OEM swap'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.9) check to see if @new_keycode is already activated
	select @new_days_used = capability_activation_days - datediff(dd,getdate(),capability_expiration_date)
	from license_capability
	where capability_id = 1 and license_id = @new_license_id
	
	if @license_status_id  in (2,3) or (@license_status_id in (0,1) and @new_days_used > 0)
		begin
			set @response_code = -150
			set @message = 'new license active'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.10) check to see the licenses is a site license
	if (@original_license_type_id = 1 and @original_max_child_licenses > 0) or (@new_license_type_id = 1 and @new_max_child_licenses > 0)
		begin
			set @response_code = -160
			set @message = 'site license swap'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.11) check to see if either license has the no swap feature turned on
	if @new_no_swap = 1 or @original_no_swap = 1
		begin
			set @response_code = -170
			set @message = 'no swap license feature'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.12) check for trial or OEM
	if @new_license_type_id in (2,3) or @original_license_type_id in (2,3) or @original_ss_capability_type_id in (2,3) or @new_ss_capability_type_id in (2,3)
		begin
			set @response_code = -180
			set @message = 'trial or OEM swap'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.13) check if new keycode doesn't have SS capability or it's turned OFF
	if (@new_ss_capability_type_id IS NULL OR @new_ss_capability_type_id = 4)
		begin
			set @response_code = -190
			set @message = 'new keycode is not a valid SS keycode'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 0
			return
		end

	-- 1.14) check if original keycode doesn't have SS capability or it's turned OFF
	if (@original_ss_capability_type_id IS NULL OR @original_ss_capability_
type_id = 4)
		begin
			set @response_code = -200
			set @message = 'original keycode is not a valid SS keycode'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.15) check product, storage, seat exact match
	if ((@orig_category <> @new_category) or (@orig_seats <> @new_seats) or (@orig_storage <> @new_storage))
		begin
			set @response_code = -210
			set @message= 'Original (' + @orig_category + '-' + @orig_seats + 's-' + @orig_storage+'gb) not the same as New (' + @new_category + '-' + @new_seats + 's-' + @new_storage+'gb)'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

	-- 1.16) check for existing accounts
	if @new_account_id is not null-- or @original_account_id is not null
		begin
			set @response_code = -220
			set @message= 'New or original license already associated with an account'
			insert into license_swap_invalid (original_license_id,new_license_id,response_code,message)
			values (@original_license_id, @new_license_id, @response_code,@message)
			select swap_success = 1
			return
		end

--	-- 1.14) check to see if original license has capabilities not in new license
--	declare @new_capability_count int
--
--	select @new_capability_count = count(*)
--	from license_capability
--	where license_id = @original_license_id and 
--			capability_id not in (select capability_id from license_capability where license_id = @new_license_id)	
--
--
--	if @new_capability_count > 0
--		begin
--		print 'add new capabilities'	
--		insert into license_capability (license_id, capability_id, capability_type_id)
--		select @new_license_id, capability_id, 4
--		from license_capability
--		where license_id = @original_license_id and 
--			capability_id not in (select capability_id from license_capability where license_id = @new_license_id)	
--		--return
--		end

	
	set @transaction_date = getdate()
	set @system_user = @modified_by

-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 2.) update licenses
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @max_days_remaining int

		-- 2.1) @original_license_id - remove previous records from product_capability_working 

		delete from product_capability_working where product_id = @original_license_id

		-- 2.2) @max_days_remaining

		select @max_days_remaining = isnull(max(t.days_remaining),0)
		from (select days_remaining =
							case 
								when datediff(dd,@transaction_date,capability_expiration_date) > 0 then datediff(dd,@transaction_date,capability_expiration_date)	
								else 0
							end
			from license_capability
			where license_id = @original_license_id and capability_type_id in (1,6,7,8,9)) t

		-- 2.3) @original_license_id - insert product_capability_working
		insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by)
		select	product_id = c1.license_id, 
				c.capability_id, 
				capability_type_id =
						case
							when c1.capability_id in (11,17) then c1.capability_type_id
							else c.capability_type_id
						end,
				capability_activation_days =
						case 
							when c.capability_type_id in (1,6,7,8,9) and e.capability_ext_type_id is not null then @max_days_remaining
							else 0
						end, 
				insert_date = @transaction_date, 
				insert_by = @modified_by
		f
rom license_capability c
		left join capability_ext e
			on c.capability_id = e.capability_id and e.capability_ext_type_id = 1
		left join license_capability c1
			on c.capability_id = c1.capability_id
		where c.license_id = @new_license_id and c1.license_id = @original_license_id
		order by c.capability_id


--		select *
--		from fn_license_select_product_capability(@original_license_id,'swap')

		exec usp_license_sub_renew_license_capability @original_license_id, @new_keycode, 'swap', @modified_by, @order_item_id, @effective_date output, @new_license_type_id_output output, @response_code output, @message output

		-- 2.4) remove previous records from product_capability_working

		delete from product_capability_working where product_id = @original_license_id

		-- 2.5) insert product_capability_working
		insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by)
		select	product_id = @original_license_id, 
				capability_id, 
				capability_type_id =	
						case 
							when capability_type_id not in (6,7,8,9) then 4
							else capability_type_id
						end, 
				capability_activation_days =	
						case 
							when capability_activation_date is not null and datediff(dd,@transaction_date,capability_expiration_date) > 0 then datediff(dd,@transaction_date,capability_expiration_date)*-1
							when capability_activation_date is null then capability_activation_days*-1
							else 0
						end, 
				insert_date = @transaction_date, 
				insert_by = @modified_by
		from license_capability 
		where license_id = @original_license_id
		order by capability_id

--		select *
--		from fn_license_select_product_capability(@original_license_id,'swap')

		exec usp_license_sub_renew_license_capability @original_license_id, @keycode, 'swap', @modified_by, @order_item_id, @effective_date output, @new_license_type_id_output output, @response_code output, @message output

	
	-- 2.6) update license records
	

		-- 2.6.1) insert original license history

		set @license_change_reason_id = 25 -- Swap Source

		insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
		select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, history_date = @transaction_date, history_by = @system_user
		from license
		where license_id = @original_license_id

		if @@error <> 0
			begin
			set @response_code = -231
			set @message = 'General SQL Error - license_history insert'
			select swap_success = 0
			return
			end

		-- 2.6.2) update original license
		update license
		set license_status_id = 2,
			modified_date = @transaction_date,
			modified_by = @modified_by
		where license_id = @original_license_id

		if @@error <> 0
			begin
			set @response_code = -232
			set @message = 'General SQL Error - license update'
			select swap_success = 0
			return
			end

		-- 2.3.3) insert new license history
		set @license_change_reason_id = 26 -- Swap Destination
		insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
		select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_c
hild_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, history_date = @transaction_date, history_by = @system_user
		from license
		where license_id = @new_license_id

		if @@error <> 0
			begin
			set @response_code = -233
			set @message = 'General SQL Error - license_history insert'
			select swap_success = 0
			return
			end

		-- 2.3.4) update new license
		update license
		set license_status_id = 1, 
			customer_id = @customer_id,
			modified_date = @transaction_date,
			modified_by = @modified_by
		where license_id = @new_license_id

		if @@error <> 0
			begin
			set @response_code = -234
			set @message = 'General SQL Error - license update'
			select swap_success = 0
			return
			end
		

		-- 2.6.2) insert license_swap
		insert into license_swap (original_license_id, new_license_id, insert_date, insert_by)
		values (@original_license_id, @new_license_id,@transaction_date, @modified_by)

		if @@error <> 0
			begin
			set @response_code = -247
			set @message = 'General SQL Error - license_swap insert'
			
			select swap_success = 0
			return
			end


-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 3.) update storage account
-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		

		declare	@storage_account_id int,
				@storage_account_username nvarchar(50),
				@storage_account_password nvarchar(40),
				@security_question varchar(100),
				@secret_answer varchar(100),
				@license_storage_id int,
				@storage_account_status_id int,
				@new_storage_account_id int,
				@new_license_storage_id int
	
		-- 3.1) get license storage data for new license
		select @new_storage_account_id =  a.storage_account_id,
				@new_license_storage_id = ls.license_storage_id
		from license l
		inner join license_storage ls
			on l.license_id = ls.license_id
		left join storage_account a
			on ls.license_storage_id = a.license_storage_id
		where l.license_id = @new_license_id

--		select new_storage_account_id = @new_storage_account_id, new_license_storage_id = @new_license_storage_id

		if @new_storage_account_id is not null
			begin
			select @response_code = '-310', @message = 'storage account already exists on new license'
			return
			end
	
		-- 3.1) get storage account values from original license

		select	@storage_account_id = storage_account_id,
				@storage_account_username = storage_account_username,
				@storage_account_password = storage_account_password,
				@security_question = security_question,
				@secret_answer = secret_answer,
				@storage_account_status_id = storage_account_status_id
		from license l
		inner join license_storage ls
			on l.license_id = ls.license_id
		inner join storage_account a
			on ls.license_storage_id = a.license_storage_id
		where l.license_id = @original_license_id

		
		-- 3.3) update storage_account 
		if @storage_account_id is not null
			begin
				exec usp_storage_update_storage_account @storage_account_id,@storage_account_username,@storage_account_password,@security_question,@secret_answer,@new_license_storage_id,@storage_account_status_id,@response_code OUTPUT,@message OUTPUT
			end

-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- 4.) update account_license
-- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------
		
		-- 4.1) see if the original license is assoicated with an account
		if (select count(*) from account_license where license_id = @original_license_id) > 0 
			begin
			-- 4.1.1) archive current account_license data
			insert into account_license_audit(account_license_id, account_id, license_id, license_change_reason_id, last_modified_date, last_modified_by, audit_date, audit_by)
			select account_license_id, account_id, license_id, license_change_reason_id = 25, last_modified_date, last_modified_by, audit_date = @transaction_date, audit_by = @modified_by	
			from account_license
			where license_id = @original_license_id

			-- 4.1.2) update account_license with new license_id
			update account_license
			set license_id = @new_license_id, last_modified_date = @transaction_date, last_modified_by = @modified_by	
			where license_id = @original_license_id

			end

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license swap failed @keycode = ' + isnull(@keycode,'') + ' and @new_keycode = ' +  isnull(@new_keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


		select swap_success = 1

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_swap_license_insert]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_swap_license_insert]

(
	@keycode varchar(40),
	@new_keycode varchar(40)
)

/*	
	DATE			AUTHOR		REMARKS
	2015-10-26		acoffel		Initial creation
	2017-03-06		cnovac		Updated misspelled "as swap_sucess" per Jade request to make automated test

	
	DESCRIPTION
	Insert license pair and identify valid vs invalid
*/

AS
	set nocount on

	declare @original_license_id int,
		@original_product_line_id int,
		@original_license_status_id int,
		@original_license_type_id int,
		@original_account_id int,
		@original_days_remaining int, 
		@original_distribution_class varchar(20),
		@original_capability_type_id int,
		@original_category_id int,
		@original_license_category_name varchar(10),
		@original_ar_status tinyint,
		@new_license_id int,
		@new_product_line_id int,
		@new_license_status_id int,
		@new_license_type_id int,
		@new_account_id int,
		@new_capability_type_id int,
		@new_category varchar(20),
		@new_days_remaining int, 
		@new_distribution_class varchar(20),
		@new_category_id int,
		@new_license_category_name varchar(10),
		@new_ar_status tinyint,
		@license_key varchar(36),
		@transaction_date datetime,
		@system_user varchar(50),
		@license_swap_id int,
		@response_code int,
		@existing_record bit,
		@message varchar(100),
		@effective_date datetime,
		@modified_by varchar(20)
	

	set @modified_by = suser_sname()
	set @transaction_date = getdate()
	set @system_user = @modified_by
		
begin try

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get license data for two keycodes
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.0) get new license
		select @new_license_id = l.license_id,
			@new_product_line_id = l.product_line_id,
			@new_license_type_id = l.license_type_id,
			@new_days_remaining = case when lc.capability_activation_date is not NULL then datediff(dd,getdate(),lc.capability_expiration_date) else lc.capability_activation_days end,
			@new_license_status_id = l.license_status_id,
			@new_distribution_class = dc.distribution_class,
			@new_category_id = cl.license_category_id,
			@new_ar_status = case when at.license_attribute_license_value = 1 then 1 
									when at.license_attribute_license_value in (2,3) then 2 
									else 0 end,
			@license_key = k.license_key,
			@new_license_category_name = case when ca.license_category_name = 'WSAV' and m.license_id is not NULL then 'GAMR' else ca.license_category_name end
		from license l
		inner join license_capability lc 
			on l.license_id = lc.license_id and lc.capability_id = 2
 		inner join license_category_license cl
			on l.license_id = cl.license_id 
		inner join license_category ca	
			on cl.license_category_id = ca.license_category_id
		left join license_attribute_license at
			on l.license_id = at.license_id 
		inner join license_distribution_method_channel ldmc 
		   on l.license_distribution_method_id = ldmc.license_distribution_method_id
		inner join distribution_class dc
		   on ldmc.distribution_class_id = dc.distribution_class_id
		left join account_license al
			on l.license_id = al.license_id
		left join license_key k
			on l.license_id = k.license_id
		left join license_module_license m
			on l.license_id = m.license_id and m.license_module_id = 12
		where keycode = @new_keycode


		if @new_license_id is null
			begin
				set @response_code = -100
				set @message = 'new keycode not found'
		
		select swap_success = 0
				return
			end


		-- 1.1) get original license
		select @original_license_id = l.license_id,
			@original_product_line_id = l.product_line_id,
			@original_license_status_id = l.license_status_id,
			@original_license_type_id = l.license_type_id,
			@original_capability_type_id = lc.capability_type_id,
			@original_days_remaining = datediff(dd,getdate(),lc.capability_expiration_date),
			@original_distribution_class = dc.distribution_class,
			@original_category_id = cl.license_category_id,
			@original_account_id = al.license_id,
			@original_ar_status = case when at.license_attribute_license_value = 1 then 1 
									when at.license_attribute_license_value in (2,3) then 2 
									else 0 end,
			@original_license_category_name = case when ca.license_category_name = 'WSAV' and m.license_id is not NULL then 'GAMR' else ca.license_category_name end
		from license l
		inner join license_capability lc 
			on l.license_id = lc.license_id and lc.capability_id = 2
 		inner join license_category_license cl
			on l.license_id = cl.license_id 
		inner join license_category ca	
			on cl.license_category_id = ca.license_category_id
		left join license_attribute_license at
			on l.license_id = at.license_id 
		inner join license_distribution_method_channel ldmc 
		   on l.license_distribution_method_id = ldmc.license_distribution_method_id
		inner join distribution_class dc
		   on ldmc.distribution_class_id = dc.distribution_class_id
		left join account_license al
			on l.license_id = al.license_id
		left join license_key k
			on l.license_id = k.license_id
		left join license_module_license m
			on l.license_id = m.license_id and m.license_module_id = 12
		where keycode = @keycode



		-- 1.2)  check to see if the original keycode doesn't exist
		if @original_license_id is null
			begin
				set @response_code = -110
				set @message = 'keycode not found'
				select swap_success = 0
				return
			end

		--1.3) verify record is not already in table
		if (select count(*) from license_swap where original_license_id = @original_license_id and new_license_id = @new_license_id) > 0
			begin 
				set @response_code = -120
				set @message = 'swap entry already exists'
				select swap_success = 0
				return
			end				

		-- 1.4) insert license_swap
		insert into license_swap (original_license_id, new_license_id, insert_date, insert_by, original_days_remaining, new_days_remaining, modified_date, license_swap_status_id)
		values (@original_license_id, @new_license_id, @transaction_date, @modified_by, NULL, NULL, getdate(), 0)
	
		select @license_swap_id = scope_identity()

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update swap status according to existing license settings  
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.0) see if the original license is assoicated with an account
		if @original_distribution_class in ('Japan', 'Online', 'Retail', 'Other', 'Test', 'UK Retail', 'E-tail', 'Shelf') and @new_distribution_class in ('Japan', 'Online', 'Retail', 'Other', 'Test', 'UK Retail', 'E-tail', 'Shelf')
			and @original_product_line_id in (1,6,100,200) and @new_product_line_id in (1,6,100,200)
			and @original_license_category_name = @new_license_category_name
			and @original_account_id is NULL
			and @original_license_type_id = 1 and @new_license_type_id = 1
			and @original_days_remaining >= 1 and @original_days_remaining <= 90 and ((@new_days_remaining) > 8 or (@new_days_remaining is NULL))
			and @original_license_status_id = 1 and @new_license_status_id in (0,1)
			begin
				update license_swap set l
icense_swap_status_id = 1, original_days_remaining = @original_days_remaining, new_days_remaining = @new_days_remaining where license_swap_id = @license_swap_id
			end
			else
			begin	
				update license_swap set license_swap_status_id = 3, original_days_remaining = @original_days_remaining, new_days_remaining = @new_days_remaining  where license_swap_id = @license_swap_id
			end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert campaign record if valid swap  
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if (select license_swap_status_id from license_swap where license_swap_id = @license_swap_id) = 1
			begin
				insert into license_message (license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, last_modified_date, message_campaign_id, message_campaign_class_id, update_attempts)
				select @new_license_id, @license_key, 1, 1, getdate(), getdate()-720, getdate()+8, getdate()+8, getdate(), 317, 2, 0 
			end

		select @message = 'Swap Insert Complete' select @message, 1 as swap_success

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license swap failed @keycode = ' + isnull(@keycode,'') + ' and @new_keycode = ' +  isnull(@new_keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_activate]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_activate]

(
	@license_id int,
	@start_date datetime = null,
	@end_date datetime = null,
	@order_item_id int = null,
	@trial_registration_id int = null
)

/*
	DATE		AUTHOR		REMARKS
	2009-07-20	esmart		Initial creation.
	2009-08-07	bjordan		Added logic to set the license_expiration_date in license
	2009-08-14	bjordan		Added logic to get @license_status_id from license
	2012-01-16	esmart		license_module_license support
	2019-04-03	cnovac		Added code to start writing to license contract object
	2019-06-11	cnovac		Changed license contract code to look for orders with no @order_item_id and @trial_registration_id since these are child record activations
	2020-04-08	cnovac		Added license_status_id to license contract call
	2020-05-14	wbarton		Adding section 1.7 to maintain autorenewal status on license_effective_object

	DESCRIPTION

*/

AS
	set nocount on

	declare @transaction_date datetime,
			@license_status_id int,
			@license_change_reason_id int,
			@capability_expiration_date datetime,
			@capability_activation_date datetime,
			@capability_type_id int,
			@modified_by varchar(20),
			@needs_storage_activation tinyint,
			@activation_days int,
			@response_code int,
			@message varchar(100),
			@license_contract_json varchar(max),
			@license_effective_object_json nvarchar(max),
			@procedure varchar(100)


	select @license_change_reason_id = 6
	select @transaction_date = getdate()
	select @modified_by = suser_sname()
	select @procedure = object_name(@@procid)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.1) update license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @license_status_id = license_status_id
	from license
	where license_id = @license_id

	if @license_status_id = 0
		begin
			-- add existing data to license_history
			insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
			select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @modified_by
			from license
			where license_id = @license_id

			-- update license
			update license
			set license_status_id = 1,
				modified_date = @transaction_date,
				modified_by = @modified_by
			where license_id = @license_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.2) update capabilities
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modi
fied_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
	select  license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by,@license_change_reason_id, @transaction_date, @modified_by,
		days_used = 0,
		days_remaining = 0,
		days_added = 0,
		days_new = capability_activation_days,
		days_contiguous = capability_activation_days
	from license_capability
	where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4

	update license_capability
	set capability_activation_date =
			case
				when capability_activation_days is null then null
				when @start_date is not null then @start_date
				else @transaction_date
			end,
		capability_expiration_date =
			case
				when capability_activation_days is null then null
				when @end_date is not null then @end_date
				else dateadd(dd,capability_activation_days,@transaction_date)
			end,
		modified_date = @transaction_date,
		modified_by = @modified_by
	from license_capability
	where license_id = @license_id and capability_activation_days is not null and capability_activation_date is null and capability_type_id <> 4

	select @capability_expiration_date = c.capability_expiration_date, @capability_activation_date = c.capability_activation_date, @capability_type_id = c.capability_type_id
	from license_capability c
	inner join license_category_license cl
		on c.license_id = cl.license_id
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	where c.license_id = @license_id and c.capability_id = lc.base_capability_id

	--Ensure the license_expiration_date matches the max capability expiration date
--	update license
--	set license_expiration_date = @capability_expiration_date
--	where license_id = @license_id and license_expiration_date is null


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.3) update license_category
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, license_change_reason_id, last_modified_date, last_modified_by, history_date, history_by)
	select license_category_license_id, license_id, license_category_id, start_date, end_date, license_change_reason_id = @license_change_reason_id, last_modified_date, last_modified_by, @transaction_date, @modified_by
	from license_category_license
	where license_id = @license_id and start_date is null

	update license_category_license
	set start_date = @capability_activation_date,
		end_date = @capability_expiration_date,
		last_modified_date = @transaction_date,
		last_modified_by = @modified_by
	from license_category_license where license_id = @license_id and start_date is null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.4.) update storage
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.4.1 check to see if storage is activated
	select @needs_storage_activation = count(*)
	from license_storage
	where license_id = @license_id and storage_activation_date is null

	if @needs_storage_activatio
n > 0
		-- 1.4.2 activate storage
		begin
			-- insert audit
			insert into license_storage_audit (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
			select license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, @transaction_date, @modified_by
			from license_storage
			where license_id = @license_id

			-- insert license_storage_history
			insert into license_storage_history (license_storage_id, license_id, storage_gb, storage_activation_date, storage_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
			select license_storage_id, license_id, storage_gb, storage_activation_date,	storage_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @modified_by
			from license_storage
			where license_id = @license_id

			-- update license_storage
			update license_storage
			set storage_activation_date = @capability_activation_date,
				storage_expiration_date = @capability_expiration_date,
				modified_date = @transaction_date,
				modified_by = @modified_by
			where license_id = @license_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.5) update license_seat
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_seat_history (license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
	select license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @modified_by
	from license_seat
	where license_id = @license_id and start_date is null

	update license_seat
	set start_date = @capability_activation_date,
		end_date = @capability_expiration_date,
		modified_date = @transaction_date,
		modified_by = @modified_by
	from license_seat where license_id = @license_id and start_date is null

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.5) update license_module_license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date)
	select license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, @license_change_reason_id, @transaction_date
	from license_module_license
	where license_id = @license_id and start_date is null

	update license_module_license
	set start_date = @capability_activation_date,
		end_date = @capability_expiration_date,
		last_modified_date = @transaction_date,
		last_modified_by = @modified_by
	from license_module_license
	where license_id = @license_id and start_date is null

	-- -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--
	-- 1.6)  License Contract call
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--build up the JSON now only for business licenses where @trial_registration_id is not null
	select @license_contract_json = (
	select license_id = @license_id, license_category_id = lcl.license_category_id, license_status_id = iif(l.license_status_id = 1, 1, 4), license_category_type_id = @capability_type_id, license_start_date = @capability_activation_date, license_end_date = @capability_expiration_date, trial_registration_id = @trial_registration_id, originating_license_contract_id = fn.license_contract_id
	from license l
	inner join license_category_license lcl on lcl.license_id = l.license_id
	outer apply fn_license_select_license_contract_table(l.license_id, lcl.license_category_id, 'max_row') fn
	where l.license_id = @license_id
	and l.product_line_id in (55, 300)
	and (@trial_registration_id is not null --don't pick up any rows where it's a full license transaction
	 or (@trial_registration_id is null and @order_item_id is null)) --this will pick up any child type transactions that don't have trial or full transaction data
	for json path)

	--if data exists, call the insert now
	if @license_contract_json is not null
	begin
		exec usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_update_activate'
	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.7)  Autorenewal status maintenance on license_effective_object when applicable
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if exists (select 1 from license_attribute_license where license_id = @license_id and license_attribute_id = 1 and license_attribute_license_value is not null) begin
		select @license_effective_object_json = (
			select lal.license_id, lcl.license_category_id, lal.license_attribute_license_value as license_autorenewal_value, lal.modified_date as effective_start_date
				from license_attribute_license lal
					inner join license_category_license lcl
						on lcl.license_id = lal.license_id
					left join (
						select license_effective_object_id, license_id, license_category_id, effective_value
						from dbo.fn_license_select_effective_object_table(@license_id, @transaction_date)
						where effective_object_id = 4 --license_autorenewal_value
					) e
						on e.license_id = lal.license_id and e.license_category_id = lcl.license_category_id and e.effective_value = lal.license_attribute_license_value
				where lal.license_id = @license_id
					and lal.license_attribute_id = 1 --Autorenewal
					and e.license_effective_object_id is null --Excluding instances where we already have a matching effective_value for the current license_category_id
					--Excluding business child licenses. Should these have a license_attribute_license_value from a migration, they don't need to be maintained into license_effective_object
					and not exists (
						select 1
						from license l
							inner join license_parent lp
								on lp.child_license_id = l.license_id
						where l.license_id = @license_id
							and l.product_line_id in (300, 55)
					)
			for json path
		)

		if @license_effective_object_json is not null begin
			exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = @procedure
		end
	end

	end try
	begin catch

		set @response_code = -200
		set @message = case when @message is null then 
'license activate failed for @license_id: ' + convert(varchar(10),@license_id)
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_bulk_load_license]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_update_bulk_load_license]

(	
	@license_bulk_load_id int,
	@license_bulk_load_license_update_type varchar(max),
	@hard_cancel bit = NULL
)

AS
	set nocount on				

		declare @capability_activation_days int,
				@capability_activation_date datetime,	
				@capability_expiration_date datetime,
				@capability_expiration_date_parent datetime,
				@base_capability_id int,
				@capability_type_id int,
				@license_status_id int,
				@license_change_reason_id int,
				@transaction_date datetime,
				@product_type_id int,
				@max_process_date datetime,
				@modified_by varchar(20),
				@response_code int,
				@message varchar(100)	


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) build deactivation groupings
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_bulk_load_detail table (license_id int, license_bulk_load_license_update_type varchar(40), license_bulk_load_id int, capability_expiration_date datetime)

	insert into @license_bulk_load_detail (license_id, license_bulk_load_license_update_type, license_bulk_load_id, capability_expiration_date)
	select	s.license_id,
			license_bulk_load_license_update_type = 'Not Activated',
			lbl.license_bulk_load_id,
			capability_expiration_date = NULL
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 0
	and lbl.license_bulk_load_id = @license_bulk_load_id
	
	insert into @license_bulk_load_detail (license_id, license_bulk_load_license_update_type, license_bulk_load_id, capability_expiration_date)
	select	s.license_id,
			license_bulk_load_license_update_type = 'Active with days',
			lbl.license_bulk_load_id,
			capability_expiration_date = NULL
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 1
	and s.capability_expiration_date >= getdate()
	and lbl.license_bulk_load_id = @license_bulk_load_id


	insert into @license_bulk_load_detail (license_id, license_bulk_load_license_update_type, license_bulk_load_id, capability_expiration_date)
	select s.license_id,
			license_bulk_load_license_update_type = 'Active with no days',
			lbl.license_bulk_load_id,
			capability_expiration_date = NULL
	from license_bulk_load_license lbl with (nolock)
	inner join license_summary s with (nolock)
		on lbl.license_id = s.license_id
	where s.license_status_id = 1
	and s.capability_expiration_date < getdate()
	and lbl.license_bulk_load_id = @license_bulk_load_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) run deativation activated with days
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @license_bulk_load_license_update table (license_bulk_load_license_update_type varchar(40))

	-- 2.0) @license_bulk_load_license_update
	insert into @license_bulk_load_license_update (license_bulk_load_license_update_type)
	select l.license_bulk_load_license_update_type
	from dbo.fn_string_to_table(@license_bulk_load_license_update_type) f
	inner join license
_bulk_load_license_update l
		on f.string_value = l.license_bulk_load_license_update_type


	-- 2.1) check @license_bulk_load_license_update for deactivation groupings
	if (select count(*) from @license_bulk_load_license_update where license_bulk_load_license_update_type = 'Active with days') > 0
		begin 
			declare @capability_update table  (license_capability_id int, license_id int, capability_id int, capability_type_id int, capability_activation_days int, capability_activation_date datetime, capability_expiration_date datetime, insert_date datetime,
										insert_by varchar(50), modified_date datetime, modified_by varchar(50), days_used int, days_remaining int, days_added int, days_new int, days_contiguous int, new_expiration_date datetime)

					-- 2.2) insert licence_capability records
					insert into @capability_update (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date,
													insert_date, insert_by, modified_date, modified_by, new_expiration_date)
					select lc.*, getdate()
					from @license_bulk_load_detail t
					inner join license_capability lc with (nolock)
						on t.license_id = lc.license_id
					where lc.capability_activation_date is not null
					and t.license_bulk_load_license_update_type = 'Active with days'

					-- 2.3) update day_used columns
					update @capability_update
					set days_used =  
						case 
							when capability_expiration_date <= getdate() then capability_activation_days
						else datediff(dd, capability_activation_date, getdate())
						end

					-- 2.4) update days_remaining columns
					update @capability_update
					set days_remaining = 
						case
							when capability_expiration_date <= getdate() then 0
						else datediff(dd, getdate(), capability_expiration_date)
						end

					-- 2.5) update days_added columns
					update @capability_update
					set days_added  = datediff(dd, getdate(), new_expiration_date) - days_remaining

					-- 2.6) update days_new
					update @capability_update
					set days_new =
						case
							when days_added <= 0 then 0
						else days_added
						end

					-- 2.7) update days_contiguous
					update @capability_update
					set days_contiguous = days_remaining + days_added


					-- 2.8) insert rows into license_capability_history 
					insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
					select license_capability_id, license_id, capability_id, capability_type_id,
						capability_activation_days = isnull(days_used,0),
						capability_activation_date,
						capability_expiration_date = getdate(),
						insert_date, insert_by, modified_date, modified_by, capability_change_reason_id = 4, history_date = getdate(), history_by = 'bulk_load_deactivation',
						days_used = isnull(days_used,0),
						days_remaining = isnull(days_remaining,0),
						days_added = isnull(days_added,0),
						days_new = isnull(days_new,0),
						days_contiguous = isnull(days_contiguous,0)
					from @capability_update
					order by license_id, capability_id

					-- 2.9) update license_capability 
					update license_capability
					set capability_activation_days = datediff(dd, getdate(), t.new_expiration_date),
						capability_activation_date = getdate(),
						capability_expiration_date = t.new_expiration_date,
						modified_date = getdate(),
						modified_by = system_user
					from license_capability c
					inner join @capability_update t
						on c.license_capability_id = t.license_capability_id


					--2.10) hard cancel if we want to block from cart
					if @hard_cancel = 1
						begin 
							insert into license_history (license_id, ke
ycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
							select distinct l.license_id, l.keycode, l.customer_id, l.product_line_id, l.license_status_id, l.license_type_id, l.license_distribution_method_id, l.license_keycode_type_id, l.max_daily_activations, l.max_child_licenses, l.license_expiration_date, l.insert_date, l.insert_by, l.modified_date, l.modified_by, 4, getdate(),  'eComWebP'
							from @capability_update c
							inner join license l with (nolock)
								on c.license_id = l.license_id
		
							update l
							set l.license_status_id = 3,
								l.modified_date = getdate(),
								l.license_distribution_method_id = 919,
								l.modified_by = 'bulk_load_deactivation'
							from @capability_update c
							inner join license l with (nolock)
								on c.license_id = l.license_id
						end
		
					--declare @max_process_date datetime
					--2.11) check to see if there are any waiting in prevx_update table
					select @max_process_date = max(p.process_date)
					from prevx_update p
					where prevx_update_type_id = 2 and response_text is NULL

					insert into prevx_update (license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date)
					select distinct license_id, NULL as license_bulk_load_id, 100 as prevx_update_type_id, 0 as prevx_update_status_id, NULL response_id, 
					NULL as response_text, 0 as update_attempts, getdate() as insert_date, getdate() as modified_date, case when @max_process_date is not NULL then dateadd(minute,3,@max_process_date) else getdate() end as process_date
					from @capability_update


			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) run deativation for unactivated licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 3.0) deactivate 'Not activated'
		if (select count(*) from @license_bulk_load_license_update where license_bulk_load_license_update_type = 'Not activated') > 0
			begin 
				update license_capability
				set capability_activation_days = 0,
					modified_date = getdate(),
					modified_by = 'bulk_load_deactivate'
				from license_capability c
				inner join @license_bulk_load_detail t
					on c.license_id = t.license_id
				where t.license_bulk_load_license_update_type = 'Not Activated'
					
					-- 3.1) hard cancel for 'Not activated'
					if @hard_cancel = 1
						begin 
							-- 3.2) insert license_history
							insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
							select distinct l.license_id, l.keycode, l.customer_id, l.product_line_id, l.license_status_id, l.license_type_id, l.license_distribution_method_id, l.license_keycode_type_id, l.max_daily_activations, l.max_child_licenses, l.license_expiration_date, l.insert_date, l.insert_by, l.modified_date, l.modified_by, 4, getdate(),  'eComWebP'
							from @license_bulk_load_detail c
							inner join license l with (nolock)
								on c.license_id = l.license_id
							where c.license_bulk_load_license_update_type = 'Not Activated'
							
							-- 3.2) update license
							update l
							set l.license_status_id
 = 3,
								l.modified_date = getdate(),
								l.license_distribution_method_id = 919,
								l.modified_by = 'bulk_load_deactivation'
							from @license_bulk_load_detail c
							inner join license l with (nolock)
								on c.license_id = l.license_id
							where c.license_bulk_load_license_update_type = 'Not Activated'
						end

				--3.3) check to see if there are any waiting in prevx_update table
				select @max_process_date = max(p.process_date)
				from prevx_update p
					where prevx_update_type_id = 2 and response_text is NULL

				--3.4) check to see if there are any waiting in prevx_update table
				insert into prevx_update (license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date)
				select distinct license_id, NULL as license_bulk_load_id, 100 as prevx_update_type_id, 0 as prevx_update_status_id, NULL response_id, 
				NULL as response_text, 0 as update_attempts, getdate() as insert_date, getdate() as modified_date, case when @max_process_date is not NULL then dateadd(minute,3,@max_process_date) else getdate() end as process_date
				from @license_bulk_load_detail c
				where c.license_bulk_load_license_update_type = 'Not Activated'
			
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) run deativation for unactivated licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 4.0) deactivate 'Active with no days'
		if (select count(*) from @license_bulk_load_license_update where license_bulk_load_license_update_type = 'Active with no days') > 0 and @hard_cancel = 1
			begin
				-- 4.1) insert license_history
				insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
				select distinct l.license_id, l.keycode, l.customer_id, l.product_line_id, l.license_status_id, l.license_type_id, l.license_distribution_method_id, l.license_keycode_type_id, l.max_daily_activations, l.max_child_licenses, l.license_expiration_date, l.insert_date, l.insert_by, l.modified_date, l.modified_by, 4, getdate(),  'eComWebP'
				from @license_bulk_load_detail c
				inner join license l with (nolock)
					on c.license_id = l.license_id
				where c.license_bulk_load_license_update_type = 'Active with no days'
							
				-- 4.2) update license
				update l
				set l.license_status_id = 3,
					l.modified_date = getdate(),
					l.license_distribution_method_id = 919,
					l.modified_by = 'bulk_load_deactivation'
				from @license_bulk_load_detail c
				inner join license l with (nolock)
					on c.license_id = l.license_id
				where c.license_bulk_load_license_update_type = 'Active with no days'
			
				--4.3) check to see if there are any waiting in prevx_update table
				select @max_process_date = max(p.process_date)
				from prevx_update p
					where prevx_update_type_id = 2 and response_text is NULL

				--4.4) check to see if there are any waiting in prevx_update table
				insert into prevx_update (license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date)
				select distinct license_id, NULL as license_bulk_load_id, 100 as prevx_update_type_id, 0 as prevx_update_status_id, NULL response_id, 
				NULL as response_text, 0 as update_attempts, getdate() as insert_date, getdate() as modified_date
, case when @max_process_date is not NULL then dateadd(minute,3,@max_process_date) else getdate() end as process_date
				from @license_bulk_load_detail c
				where c.license_bulk_load_license_update_type = 'Active with no days'

			end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_cb_ar_reconciliation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_cb_ar_reconciliation] 
(
	@insert_date date = null	
)
	
/*     
	DATE			AUTHOR		REMARKS
	2018-08-29		rvinoche	Initial creation
       
	DESCRIPTION
	Daily reconcile procedure to sync data with CB in regards to AutoRenewal
*/

AS
	declare @modified_date datetime = getdate(),
		@min int , 
		@max int, 
		@license int,
		@new_attribute int, 
		@cb_ar_id int,
		@response_code int,
		@message varchar(100)

	begin try	

		if @insert_date is null
		begin
			select @insert_date = getdate()
		end
    
		declare @reconcialition table (id int identity(1,1), license_id int, old_license_attribute int, new_license_attribute int, cb_ar_id int)

		insert into @reconcialition (license_id, old_license_attribute, new_license_attribute, cb_ar_id)
		select license_id,
			   license_attribute_license_value,
			   license_attribute_license_value_updated,
			   cb_ar_check_id
		from DATAWAREHOUSEREADONLY.Feed.dbo.cb_ar_check
		where license_attribute_license_value <> license_attribute_license_value_updated
			and cast (insert_date as date) = @insert_date
			and license_id is not null
			and updated_date is null

		select @min = min(id), @max = max(id) from @reconcialition

		while @min <= @max 
		begin
			select @license = license_id, @new_attribute = new_license_attribute, @cb_ar_id = cb_ar_id 
			from @reconcialition 
			where id = @min

			exec dbo.usp_license_update_license_attribute_license @license_id = @license,                        
																  @license_attribute_id = 1,               
																  @license_attribute_license_value = @new_attribute,    
																  @modified_by = 'cb_reconciliation',                       
																  @effective_date = @modified_date,
																  @allow_past_record_update = 1     

			if @@error = 0 
			begin 
				update DATAWAREHOUSEREADONLY.Feed.dbo.cb_ar_check
				set updated_date = getdate()
				where cb_ar_check_id = @cb_ar_id
			end

			select @license = null, @new_attribute = null, @cb_ar_id = null, @min = @min +1
		end	
	end try

	begin catch

        set @response_code = -200
        set @message = case when @message is null then 'failure to update cb ar license_attribute'
                                        else @message end

        declare @dbname nvarchar(128)
        set @dbname = db_name()
        exec dbo.usp_logerror @errordb = @dbname;
        throw 51001, @message,1;
	
	end catch;
		


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_child_license_capability]
-- =============================================================================

create procedure dbo.usp_license_update_child_license_capability
	@parent_license_id int,
	@response_code int output,
	@message varchar(100) output
as
/*
Purpose: This will update all child license capabilities for the parent_license_id

DATE		AUTHOR		REMARKS
2010-06-14	dsmelker	Created


*/
Begin

-----------------------------------------------------------------------------------
-- 1) Build Data Set
--
-----------------------------------------------------------------------------------

declare @child_license_capability table (
 license_id int,
 parent_license_id int,
 capability_id int,
 capability_type_id int,
 capability_activation_days int,
 capability_activation_date datetime,
 capability_expiration_date datetime
)

declare @row_cnt int

Begin Try


insert into @child_license_capability
select distinct l.license_id, lp.parent_license_id, 
lc.capability_id, lc.capability_type_id,lc.capability_activation_days,
lc.capability_activation_date,lc.capability_expiration_date
from license l with(nolock)
inner join license_parent lp with(nolock)
	on l.license_id = lp.child_license_id
inner join license_capability lc with(nolock)
	on lp.parent_license_id = lc.license_id
where lp.parent_license_id = @parent_license_id

set @row_cnt = @@rowcount

if @row_cnt = 0
Begin
	set @response_code = 0
	set @message = 'No Child Licenses'
End
Else
Begin

-----------------------------------------------------------------------------------
-- 2) insert audit data
--
-----------------------------------------------------------------------------------
	insert into license_capability_audit(license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
	select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = getdate(), audit_by = suser_sname()
	from license_capability lc
	where exists (select * from @child_license_capability tlc
					where lc.license_id = tlc.license_id)
	order by 1


-----------------------------------------------------------------------------------
-- 3) insert history data
--
-----------------------------------------------------------------------------------
	
	insert into license_capability_history(license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)	
	select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id = 4, history_date = getdate(), history_by = suser_sname(), days_used = 0, days_remaining = 0, days_added = 0, days_new = 0, days_contiguous = 0, order_item_id = null
	from license_capability lc
		where exists (select * from @child_license_capability tlc
						where lc.license_id = tlc.license_id)
	order by 1
	

-----------------------------------------------------------------------------------
-- 4) Update license_capability
--
-----------------------------------------------------------------------------------

	update lc
	set capability_type_id = tlc.capability_type_id,
	capability_activation_days = tlc.capability_activa
tion_days,
	capability_activation_date = tlc.capability_activation_date,
	capability_expiration_date = tlc.capability_expiration_date,
	modified_date = getdatE(),
	modified_by = system_user
	from license_capability lc
	inner join @child_license_capability tlc
		on lc.license_id = tlc.license_id
		and lc.capability_id = tlc.capability_id


	set @response_code = 0
	set @message = 'Update completed successfully'
End

End Try

Begin Catch

	set @response_code = -200
	set @message = case when @message is null then 'update failed on children of @parent_license_id = ' + isnull(cast(@parent_license_id as varchar(10)),'')
						else @message end

	
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName


End Catch

End

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_child_licenses]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_child_licenses]

(
	@parent_license_id int, 
	@order_item_id int, 
	@child_license_id int = null
)


/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2014-10-06	esmart		Fix issue with days and activation data on new capability record
	2015-02-10	esmart		Disable fix
	2015-11-17	acoffel		child inclusions
	2016-07-03	cnovac		updated license_service references for CB changes
	2017-02-21	esmart		license_module_license support
	2017-03-27	esmart		Fix issue with update to child license_module_license
	2019-07-09	cnovac		Added code to start writing to license contract object
	2019-10-29	cnovac		Added check to see if @license_contract_json is not null

	DESCRIPTION
	update child licenses from parent
*/

AS
	set nocount on				

	declare @capability_activation_date datetime,	
			@capability_expiration_date datetime,
			@capability_type_id int,
			@license_change_reason_id int,
			@transaction_date datetime,
			@product_type_id int,
			@modified_by varchar(20),
			@license_service_type_id tinyint,
			@product_line_id int,
			@license_contract_json varchar(max),
			@response_code int,
			@message varchar(100)
			
	declare @license_contract table (license_id int, license_category_id tinyint, license_category_type_id tinyint, start_date date, end_date date)		

	begin try


	--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) parent data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) 
	select @transaction_date = getdate(),
		   @modified_by = 'parent_update',
		   @license_service_type_id = 0

	-- 1.1) select parent license values
	select 	@capability_activation_date = c.capability_activation_date, 
			@capability_expiration_date = c.capability_expiration_date,
			@capability_type_id = c.capability_type_id,
			@product_line_id = l.product_line_id
	from license l
	inner join license_category_license cl
		on l.license_id = cl.license_id
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	inner join license_capability c
		on l.license_id = c.license_id and c.capability_id = lc.base_capability_id
	where l.license_id = @parent_license_id

	-- 1.2) @license_change_reason_id
	if @order_item_id is null
		begin
		select @license_change_reason_id = 13	-- OEM License maintenance
		end
	else
		begin
		select @license_change_reason_id = case
												when p.product_type_id = 1 then 14	-- New - Trial to Full
												when p.product_type_id = 2 then 2	-- Renewal - License capability update
												when p.product_type_id in (3,4) then 3	-- 3	Upgrade - License capability update
											end,
				@product_type_id = p.product_type_id
		from order_item i
		inner join product p
			on i.product_id = p.product_id
		where i.order_item_id = @order_item_id
		end
		
	if @product_type_id is null 
		begin
		select @product_type_id = 2
		end

	if @license_change_reason_id = 3
		begin
		-- TODO: sort out upgrades
		return
		end

	-- 1.3) @license_service_type_id
	select @license_service_type_id = ls.license_service_type_id
	from license_service_value lsv
	inner join license_service ls 
		on ls.license_service_id = lsv.license_service_id and lsv.license_service_value_type_id = 1
	where lsv.license_service_value = @child_license_id

	-- 1.4) @parent_license_module
	declare @parent_license_module_license table (license_modul
e_id tinyint, license_module_type_id tinyint, start_date datetime, end_date datetime)

	insert into @parent_license_module_license (license_module_id,license_module_type_id,start_date, end_date)
	select m.license_module_id, m.license_module_type_id, m.start_date, m.end_date
	from license_module_license m
	where m.license_id = @parent_license_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) process
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_capability_update table (license_capability_id int NOT NULL,license_id int NOT NULL,capability_id int NOT NULL,capability_type_id int NOT NULL,product_capability_type_id int NULL,capability_activation_days int NULL,capability_activation_date datetime NULL,capability_expiration_date datetime NULL,insert_date datetime NOT NULL,insert_by varchar(50) NOT NULL,modified_date datetime NOT NULL,modified_by varchar(50) NOT NULL,days_used int NULL default 0,days_remaining int NULL default 0,days_added int NULL default 0,days_new int NULL default 0,days_contiguous int NULL default 0,last_days_contiguous int NULL default 0,new_activation_date datetime NULL,license_status_id int NOT NULL, license_distribution_method_id int NOT NULL)	

	-- 2.0) get child license_data
	insert into @license_capability_update(license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, license_status_id, license_distribution_method_id)
	select c.license_capability_id, c.license_id, c.capability_id, c.capability_type_id, c.capability_activation_days, c.capability_activation_date, c.capability_expiration_date, c.insert_date, c.insert_by, c.modified_date, c.modified_by, l.license_status_id, m.license_distribution_method_id
	from license_parent p
	inner join license l
		on p.child_license_id = l.license_id
	inner join license_category_license cl
		on p.child_license_id = cl.license_id
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	inner join license_capability c
		on p.child_license_id = c.license_id and c.capability_id = lc.base_capability_id
	inner join license_distribution_method m
		on l.license_distribution_method_id = m.license_distribution_method_id
	where p.parent_license_id = @parent_license_id and
		p.child_license_id = case when @child_license_id is null then p.child_license_id else @child_license_id end and
		((c.capability_type_id = case 
									when @capability_type_id is not null and @product_type_id <> 1 and @license_service_type_id <> 4 then @capability_type_id 
									else c.capability_type_id 
								end) or (m.license_distribution_method_id in (select license_distribution_method_id from child_update_distribution_method_include)))
	and l.license_status_id = 1

	-- 2.1) days_used
	update @license_capability_update
	set days_used = datediff(dd,capability_activation_date,getdate())

	-- 2.2) days_remaining
	update @license_capability_update
	set days_remaining = datediff(dd,getdate(),capability_expiration_date)

	-- 2.3) days_added
	update @license_capability_update
	set days_added = datediff(dd,capability_expiration_date,@capability_expiration_date)

	-- 2.4) days_new
	update @license_capability_update
	set days_new = days_remaining + days_added

	-- 2.4) days_contiguous
	update @license_capability_update
	set days_contiguous = days_new

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3
.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1.1) insert history			
	insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous, order_item_id)
	select license_capability_id, license_id, capability_id, capability_type_id, 
		capability_activation_days = isnull(days_used,0), 
		capability_activation_date, 
		capability_expiration_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
		insert_date, insert_by, modified_date, modified_by, 
		capability_change_reason_id = @license_change_reason_id, 
		history_date = @transaction_date, history_by = @modified_by, 
		days_used = isnull(days_used,0), 
		days_remaining = isnull(days_remaining,0), 
		days_added = isnull(days_added,0), 
		days_new = isnull(days_new,0), 
		days_contiguous = isnull(days_contiguous,0),
		order_item_id = @order_item_id
	from @license_capability_update 
	where @order_item_id is not null or (product_capability_type_id <> capability_type_id or capability_activation_days <> days_new) 

	-- 3.1.2) update
	update license_capability
	set capability_type_id = case when i.license_distribution_method_id is not NULL then t.capability_type_id else @capability_type_id end,
		capability_activation_days = datediff(dd,dateadd(dd,isnull(days_used,0),t.capability_activation_date),@capability_expiration_date),
		capability_activation_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date),
		capability_expiration_date = @capability_expiration_date,
		modified_date = @transaction_date,
		modified_by = @modified_by
	output Inserted.license_id, Inserted.capability_type_id, Inserted.capability_activation_date, Inserted.capability_expiration_date into @license_contract(license_id, license_category_type_id, start_date, end_date)
	from license_capability c
	inner join @license_capability_update t
		on c.license_capability_id = t.license_capability_id	
	left join child_update_distribution_method_include i
		on t.license_distribution_method_id = i.license_distribution_method_id

	-- 3.1.3) new dates
	select @capability_activation_date = c.capability_activation_date, @capability_expiration_date = c.capability_expiration_date
	from license_capability c
	inner join @license_capability_update t
		on c.license_capability_id = t.license_capability_id
	inner join license_category_license cl
		on c.license_id = cl.license_id
	inner join license_category lc
		on cl.license_category_id = lc.license_category_id
	where c.capability_id = lc.base_capability_id

	update lc
	set lc.license_category_id = lcl.license_category_id
	from @license_contract lc
	inner join license_category_license lcl on lcl.license_id = lc.license_id
	where lc.license_category_id is null

	-- 3.2 license_seat

	-- 3.2.1) insert history
	insert into license_seat_history(license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by, order_item_id)
	select s.license_seat_id, s.license_id, s.license_seats, s.seats_used,  
			s.start_date, 
			end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
			s.insert_date, s.insert_by, s.modified_date, s.modified_by, 
			license_change_reason_id = @license_change_reason_id, history_date = @transaction_date, history_by = @modified_by, order_item_id = @order_item_id
	from license_seat s
	inner join @license_capability_update t
		on s.license_id = t.license_id

	-- 3.2.2) update
	update license_
seat
	set start_date = @capability_activation_date,
			end_date = @capability_expiration_date,
			modified_date = @transaction_date,
			modified_by = @modified_by
	from license_seat s
	inner join @license_capability_update t
		on s.license_id = t.license_id

	-- 3.3) license_category

	-- 3.3.1) insert history
	insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date, history_by, order_item_id)
	select c.license_category_license_id, c.license_id, c.license_category_id, 
		c.start_date, 
		end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
		c.last_modified_date, c.last_modified_by, 
		license_change_reason_id = @license_change_reason_id, history_date = @transaction_date, history_by = @modified_by, order_item_id = @order_item_id
	from license_category_license c
	inner join @license_capability_update t
		on c.license_id = t.license_id

	-- 3.3.2) update
	update license_category_license
	set	start_date = @capability_activation_date,
		end_date = @capability_expiration_date,
		last_modified_date = @transaction_date,
		last_modified_by = @modified_by
	from license_category_license s
	inner join @license_capability_update t
		on s.license_id = t.license_id

	-- 3.4) license_module_license

	-- 3.4.1) insert history
	insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date, module_seats)
	select ml.license_module_license_id, ml.license_id, ml.license_module_id, ml.license_module_type_id, 
			ml.start_date,
			end_date = dateadd(dd,datediff(dd,ml.start_date,getdate()),ml.start_date), 
			ml.last_modified_date, ml.last_modified_by, order_item_id = @order_item_id, license_change_reason_id = @license_change_reason_id, 
			history_date = @transaction_date, 
			ml.module_seats
	from license_module_license ml
	inner join license_module m
		on m.license_module_id = ml.license_module_id
	inner join license_module_type t
		on t.license_module_type_id = ml.license_module_type_id
	inner join @parent_license_module_license p
		on m.parent_license_module_id = p.license_module_id and p.license_module_type_id = ml.license_module_type_id
	inner join @license_capability_update u
		on u.license_id = ml.license_id
	where ml.license_status_id = 1

	-- 3.4.2) update
	update license_module_license
	set start_date = p.start_date,
		end_date = p.end_date,
		last_modified_date = @transaction_date,
		last_modified_by = @modified_by
	output Inserted.license_id, Inserted.start_date, Inserted.end_date into @license_contract(license_id, start_date, end_date)
	from license_module_license ml
	inner join license_module m
		on m.license_module_id = ml.license_module_id
	inner join license_module_type t
		on t.license_module_type_id = ml.license_module_type_id
	inner join @parent_license_module_license p
		on m.parent_license_module_id = p.license_module_id and p.license_module_type_id = ml.license_module_type_id
	inner join @license_capability_update u
		on u.license_id = ml.license_id
	where ml.license_status_id = 1

	update lc
	set lc.license_category_id = lmc.license_category_id,
		lc.license_category_type_id = iif(lml.license_module_type_id = 19, 1, 2)
	from @license_contract lc
	inner join license_module_license lml on lml.license_id = lc.license_id
	inner join license_module_category lmc on lmc.license_module_id = lml.license_module_id
	where lc.license_category_id is null

	-- 3.5) license_contract

	-- 3.5.1) write to license contract object
	if @product_line_id in (55, 300)
	begin

		select @license_contract_json = (
		select license_id = lc.license_id, license_category_id = lc.license_category_id, license_category_type_id = lc
.license_category_type_id, license_start_date = lc.start_date, license_end_date = lc.end_date, 
				order_item_id = @order_item_id, originating_license_contract_id = fn.license_contract_id
		from @license_contract lc
		outer apply fn_license_select_license_contract_table(lc.license_id, lc.license_category_id, 'max_row') fn
		for json path)

		--if data exists, call the insert now
		if @license_contract_json is not null
		begin
			exec usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_update_child_licenses'
		end

	end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_child_licenses_banking]
-- =============================================================================

 

CREATE PROCEDURE [dbo].[usp_license_update_child_licenses_banking]

 

 

(

       --@parent_license_id int = NULL,

       --@child_license_id int = NULL,

       @keycode varchar(40) = NULL,

       @expiration_date datetime = NULL

)

 

/*    

       DATE          AUTHOR        REMARKS

       2014-03-27    acoffel              Initial creation.

 

       DESCRIPTION

       update child licenses from parent

*/

 

AS

       set nocount on                          

 

       begin try

 

       declare @capability_activation_days int,

                     @capability_activation_date datetime,   

                     @capability_expiration_date datetime,

                     @capability_expiration_date_parent datetime,

                     @base_capability_id int,

                     @capability_type_id int,

                     @license_status_id int,

                     @license_change_reason_id int,

                     @transaction_date datetime,

                     @product_type_id int,

                     @max_process_date datetime,

                     @modified_by varchar(20),

                     @response_code int,

                     @message varchar(100)

                     --,@parent_license_id int  select @parent_license_id = 97487009

 

 

                     --drop table #temp_parents

create table #temp_parents (

       keycode varchar(40) not null,

       license_id int null,

       expiration_date date null

)

 

--truncate table #temp_parents

 

--parents

insert into #temp_parents (keycode,expiration_date)

select @keycode, @expiration_date

 

update t

set t.license_id = l.license_id

from #temp_parents t

inner join license l with (nolock)

       on t.keycode = l.keycode

 

 

--children

create table #temp_children (

       license_id int not null,

       expiration_date date not null

)

 

insert into #temp_children (

       license_id,

       expiration_date

)

select top 1000 lp.child_license_id as license_id,

       t.expiration_date

from #temp_parents t

inner join license_parent lp with (nolock)

       on t.license_id = lp.parent_license_id

inner join license_capability c

       on lp.child_license_id = c.license_id and c.capability_id = 2

inner join license l

       on lp.child_license_id = l.license_id

where convert(date,c.capability_expiration_date) <> convert(date,t.expiration_date)

       and l.license_status_id in (3)
AND l.modified_date >= '2019-07-31'

 

 

 

--drop table #temp_asp_update

create table #temp_asp_update (

       license_capability_id int,

       license_id int,

       capability_id int,

       capability_type_id int,

       capability_activation_days int,

       capability_activation_date datetime,

       capability_expiration_date datetime,

       insert_date datetime,

       insert_by varchar(50),

       modified_date datetime,

       modified_by varchar(50),

       days_used int,

       days_remaining int,

       days_added int,

       days_new int,

       days_contiguous int,

       new_expiration_date datetime

)

 

--parents

insert into #temp_asp_update (

       license_capability_id,

       license_id,

       capability_id,

       capability_type_id,

       capability_activation_days,

       capability_activation_date,

       capability_expiration_date,

       insert_date,

       insert_by,

       modified_date,

       modified_by,

       new_expiration_date

)

select lc.*,

       t.expiration_date

from #t
emp_parents t

inner join license_capability lc with (nolock)

       on t.license_id = lc.license_id

and convert(date,lc.capability_expiration_date) <> convert(date,t.expiration_date)

 

--children

insert into #temp_asp_update (

       license_capability_id,

       license_id,

       capability_id,

       capability_type_id,

       capability_activation_days,

       capability_activation_date,

       capability_expiration_date,

       insert_date,

       insert_by,

       modified_date,

       modified_by,

       new_expiration_date

)

select lc.*,

       t.expiration_date

from #temp_children t

inner join license_capability lc with (nolock)

       on t.license_id = lc.license_id

where lc.capability_activation_date is not null

 

 

-- 5.0) update license_capability

update license_capability

set capability_activation_days = DATEDIFF(dd, getdate(), t.new_expiration_date),

       capability_activation_date = getdate(),

       capability_expiration_date = t.new_expiration_date,

       modified_date = getdate(),

       modified_by = 'oem_maintenence'

from license_capability c

inner join #temp_asp_update t

       on c.license_capability_id = t.license_capability_id

 

insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)

select DISTINCT license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, 4, getdate(),  'eComWebP'

from license

where license_id in (SELECT license_id FROM #temp_asp_update)

 

update license

set           license_distribution_method_id = 773,

              customer_id = NULL,

              license_status_id = 1,

              modified_date = getdate(),

              modified_by = 'oem_maintenence'

where license_id in (SELECT license_id FROM #temp_asp_update)

 

 
       --4.0) check to see if there are any waiting in prevx_update table
       select @max_process_date = max(p.process_date)
       from prevx_update p
       where prevx_update_type_id = 2 and response_text is NULL

       --4.1) load prevx queue
       insert into dbo.sky_update (license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, process_date)
       SELECT distinct n.license_id, 4, 4, 0, GETDATE(), 0, GETDATE() 
       from #temp_asp_update n
	   INNER JOIN dbo.sky_api_license s
			ON n.license_id = s.license_id

		--4.2) load prevx queue
		insert into prevx_update (license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date)
		SELECT distinct n.license_id, NULL as license_bulk_load_id, 2 as prevx_update_type_id, 0 as prevx_update_status_id, NULL response_id, NULL as response_text, 0 as update_attempts, getdate() as insert_date, getdate() as modified_date, CASE WHEN @max_process_date IS NOT NULL then DATEADD(MINUTE,2,@max_process_date)  ELSE GETDATE() END AS process_date
		from #temp_asp_update n
		left JOIN dbo.sky_api_license s
			ON n.license_id = s.license_id
		WHERE s.license_id IS NULL

 

                    

 

       end try

 

       begin catch  

 

              set @response_code = -200

              set @message = case when @message is null then 'insert failed'

                                                else @message end

 

              declare @DBName nvarchar(128)

              set @DBName = d
b_name()

              exec usp_LogError @ErrorDB = @DBName

             

       end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_disable_autorenewal]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_disable_autorenewal]

(
        @license_id int,
		@csi_user_id varchar(50),
		@comment varchar(100)
		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-04-16	esmart		Initial creation.
	2016-01-25	esmart		usp_license_update_license_attribute_license
	2018-09-07	rvinoche	Allow past record updates when calling usp_license_update_license_attribute_license
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire

	DESCRIPTION
	
*/

AS
	set nocount on			

	declare @license_attribute_id int,
			@license_attribute_license_value int,
			@effective_date datetime,
			@response_code int, 
			@message varchar(100),
			@autorenewal_status int
			
begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @license_attribute_id
	select @license_attribute_id = license_attribute_id
	from license_attribute 
	where license_attribute_tag = 'AUTORENEWAL'

	-- 1.2) @license_attribute_license_value
	select @license_attribute_license_value = license_attribute_license_value
	from license_attribute_license_value
	where license_attribute_id = @license_attribute_id and license_attribute_license_value_description = 'CSI disable'
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update licenses
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	exec usp_license_update_license_attribute_license @license_id,@license_attribute_id,@license_attribute_license_value,@csi_user_id,@effective_date

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert refund reason
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into csi_comments (subject, comment, insert_date, insert_by, license_id,csi_users_id)
	values ('Auto Renewal Cancel: ',@comment,getdate(),@csi_user_id,@license_id,@csi_user_id)

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not update license auto renewal flag for @license_id = ' + convert(varchar(20),@license_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	
	





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_external_reference_vault]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_update_external_reference_vault]
	@license_external_reference_vault_id int = null,
	@is_provisioned bit = null,
	@is_active bit = null,
	@service_json nvarchar(max) = null,
	@license_service_type_name varchar(50) = null,
	@reseller_provisioning int=null
/*	
	DATE		AUTHOR		REMARKS
	2020-06-29	wbarton		Initial creation
	2020-10-06	wbarton		Adding logging insert
	2020-01-29	wbarton		Adding an vault_guid from service_json to support DMC initiated license_vault_deactivate
	2022-03-03  psatish		SMCI-6349 Added Update_license_vault template into sfdc_opportunity_load to update the license vault object in Salesforce
	2022-06-08  psatish		ALM# 1377 Updated the is_provisioned flag for reseller orders
*/
as

set nocount on

begin try

	declare @vault table (
		license_id int,
		license_category_id tinyint,
		vault_id int,
		vault_guid nvarchar(100)
	)

	declare @license_category_json nvarchar(max), @license_id int

	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Insert logging data
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into license_external_reference_vault_json_log(processing_procedure, input_json, license_service_type_name, license_external_reference_vault_id, is_provisioned, is_active)
	select 'usp_license_update_external_reference_vault', @service_json, @license_service_type_name, @license_external_reference_vault_id, @is_provisioned, @is_active

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Update license_external_reference_vault explicitly
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @license_external_reference_vault_id is not null
		begin
			update v 
			set v.is_provisioned = iif(@is_provisioned is null, v.is_provisioned, @is_provisioned), v.is_active = iif(@is_active is null, v.is_active, @is_active), v.modified_date = getdate()
			from license_external_reference_vault v
				where v.license_external_reference_vault_id = @license_external_reference_vault_id
		end

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Update license_external_reference_vault from license service
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @service_json is not null
		begin
			select @license_id = l.license_id, @license_category_json = j.license_category
			from openjson(@service_json)
			with (
				keycode varchar(40) '$.keycode',
				license_category nvarchar(max) as json
			) j
				inner join license l with (nolock)
					on l.keycode = j.keycode

			insert into @vault(license_id, license_category_id, vault_id, vault_guid)
			select @license_id, lc.license_category_id, v.vault_id, v.vault_guid
			from openjson(@license_category_json)
			with (
				license_category_name varchar(10) '$.license_category_name',
				vault_array nvarchar(max) '$.vault' as json
			) j
				outer apply (
					select vault_id, vault_guid
					from openjson(j.vault_array)
					with (
						vault_id int '$.vault_id',
						vault_guid nvarchar(100) '$.vault_guid'
					)
				) v
				inner join license_category lc
	
				on lc.license_category_name = j.license_category_name

			--If vault_guid was passed via @service_json without vault_id, find the correct vault_id
			update vv 
			set vv.vault_id = v.vault_id
			from @vault vv
				inner join vault v
					on v.vault_datacenter_key = vv.vault_guid
			where vv.vault_id is null

			update v
			set v.is_provisioned = iif(@is_provisioned is null, v.is_provisioned, @is_provisioned), v.is_active = iif(@is_active is null, v.is_active, @is_active), v.modified_date = getdate()
			from license_external_reference_vault v 
				inner join @vault vt
					on v.license_id = vt.license_id and v.license_category_id = vt.license_category_id and v.vault_id = vt.vault_id

		end
        if @license_id is NULL AND @license_external_reference_vault_id IS NOT null
		begin 
			select @license_id=license_id 
			from dbo.license_external_reference_vault
			where license_external_reference_vault_id=@license_external_reference_vault_id
		end
--update is_provisioned for reseller       
        if @reseller_provisioning =1 and @license_external_reference_vault_id is not NULL and @license_id is not null
		begin
			update v 
			set v.is_provisioned = iif(@is_provisioned is null, v.is_provisioned, @is_provisioned), v.is_active = iif(@is_active is null, v.is_active, @is_active), v.modified_date = getdate()
			from license_external_reference_vault v
				where v.license_id = @license_id
		end
		--update_license_vault
			exec [usp_sfdc_create_update_license_vault_template] @license_id=@license_id,@sfdc_template_name='update_license_vault'

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error updating license_external_reference_vault'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_keycode_alias]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_keycode_alias]

(		
	@prevx_keycode_update_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-10-16	esmart		Initial creation.
	2014-12-05	esmart		Trap changes when keycode = alias keycode

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @license_id int,
			@license_keycode_alias_id int,
			@keycode varchar(40),
			@prevx_keycode varchar(40),
			@last_modified_date datetime,
			@response_code int,
			@message varchar(100)
			
	begin try

	select @last_modified_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select data
	select @license_id = l.license_id, 
			@keycode = p.keycode, 
			@prevx_keycode = p.prevx_keycode, 
			@license_keycode_alias_id = a.license_keycode_alias_id
	from prevx_keycode_update p
	inner join license l
		on p.keycode = l.keycode 
	left join license_keycode_alias a
		on l.license_id = a.license_id
	where prevx_keycode_update_id = @prevx_keycode_update_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @license_keycode_alias_id is null and @license_id is not null
	-- 2.1) update
		begin
			if @keycode <> @prevx_keycode
				begin
				insert into license_keycode_alias(license_id, keycode, keycode_alias)
				values(@license_id, @keycode, @prevx_keycode)
			
				select @license_keycode_alias_id = scope_identity()
				end
		end
	else
	-- 2.2) insert
		begin
			if @keycode <> @prevx_keycode
				begin
				-- 2.2.1) audit
					insert into license_keycode_alias_audit(license_keycode_alias_id, license_id, keycode, keycode_alias, last_modified_date, audit_date)
					select license_keycode_alias_id, license_id, keycode, keycode_alias, last_modified_date, @last_modified_date
					from license_keycode_alias
					where license_keycode_alias_id = @license_keycode_alias_id

				-- 2.2.2) update
					update license_keycode_alias
					set keycode_alias = @prevx_keycode, last_modified_date = @last_modified_date
					where license_keycode_alias_id = @license_keycode_alias_id
				end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) archive
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) insert archive
	insert into prevx_keycode_update_archive(prevx_keycode_update_id, keycode, prevx_keycode, insert_date, audit_date)
	select prevx_keycode_update_id, keycode, prevx_keycode, insert_date, @last_modified_date
	from prevx_keycode_update
	where prevx_keycode_update_id = @prevx_keycode_update_id

	-- 3.2) delete
	delete from prevx_keycode_update
	where prevx_keycode_update_id = @prevx_keycode_update_id
	

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
---
	-- 3.) update licensing
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into license_keycode_alias_update(license_id) values(@license_id)
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license]

(
	@license_id int, 
	@license_status_id int, 
	@license_type_id int, 
	@license_distribution_method_id int, 
	@max_daily_activations int, 
	@max_child_licenses int, 
	@license_expiration_date datetime,
	@parent_warning_user varchar(50) = NULL
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2006-09-29	esmart		Add error trapping, history insert
	2017-08-24	acoffel		Parent Warning

	DESCRIPTION
	update license
*/

	
	declare @transaction_date datetime,
		@license_change_reason_id int,
		@current_license_status_id int,
		@last_license_status_id int,
		@system_user varchar(50),
		@response_code int,
		@message varchar(100)
	
	begin try

	set @transaction_date = getdate()
	set @license_change_reason_id = 4 -- customer service
	set @system_user = system_user
	if @parent_warning_user is not NULL
		begin 
		set @system_user = @parent_warning_user
		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- @license_id
	select @response_code =  case when count(*) = 0 then -110 else 0	 end,
		@message = case when count(*) = 0 then '@license_id not valid' else '' end
	from license
	where license_id = @license_id

	if @response_code < 0 	begin return end	
	
	-- @license_status_id
	select @response_code =  case when count(*) = 0 then -120 else 0	 end,
		@message = case when count(*) = 0 then '@license_status_id not valid' else '' end
	from license_status
	where license_status_id = @license_status_id

	if @response_code < 0 	begin return end	

	-- @license_type_id
	select @response_code =  case when count(*) = 0 then -120 else 0	 end,
		@message = case when count(*) = 0 then '@license_type_id not valid' else '' end
	from license_type
	where license_type_id = @license_type_id

	if @response_code < 0 	begin  return end	
	
	-- @license_distribution_method_id
	select @response_code =  case when count(*) = 0 then -120 else 0	 end,
		@message = case when count(*) = 0 then '@license_distribution_method_id not valid' else '' end
	from license_distribution_method
	where license_distribution_method_id = @license_distribution_method_id

	if @response_code < 0 	begin return end	

	-- @license_expiration_date
	if @license_expiration_date = '' or @license_expiration_date = '1900-01-01 00:00:00'
		begin
		set @license_expiration_date = null
		end

	-- @max_daily_activations
	if @max_daily_activations = '' or @max_daily_activations is null 
		begin
		set @max_daily_activations = 30
		end

	if @license_type_id in (2,3)
		begin
		if @max_child_licenses is null or @max_child_licenses = 0
			begin
			set @max_child_licenses = 1
			end
		set @max_daily_activations = @max_child_licenses
		end
	
	-- @max_child_licenses
	if @max_child_licenses = 0
		begin
		set @max_child_licenses = null
		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check history of license_status to determine if modification of @license_status_id is needed
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------
	select @current_license_status_id = license_status_id
	from license
	where license_id = @license_id
	
	if @current_license_status_id <> @license_status_id
		begin
		set  @last_license_status_id = (select top 1 license_status_id
					from license_history
					where license_id = @license_id
					order by history_date desc)
		
		-- move license back to inactive		
		if @last_license_status_id = 0 and  @license_status_id = 1 and @current_license_status_id in (2,3)
			begin
			set @license_status_id = 0
			end

		end
	--select  @last_license_status_id, @current_license_status_id, @license_status_id
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update licesne
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- add existing data to license_history
	insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
	select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @system_user
	from license
	where license_id = @license_id


	update license
	set 	license_status_id = @license_status_id,
		license_type_id = @license_type_id,
		license_distribution_method_id = @license_distribution_method_id,
		max_daily_activations = @max_daily_activations,
		max_child_licenses = @max_child_licenses,
		license_expiration_date = @license_expiration_date,
		modified_date = @transaction_date,
		modified_by = @system_user
	where license_id = @license_id

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_update_license failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_attribute_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_attribute_license]

(
	@license_id int, 
	@license_attribute_id int,
	@license_attribute_license_value int,
	@modified_by varchar(20),
	@effective_date datetime = null,
	@order_header_id int = null,
	@partner_license_status_id tinyint = null,
	@vendor_initiated bit = null,
	@order_item_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-11-13	esmart		Initial creation
	2015-03-10	cnovac		Add usp_license_update_license_attribute_license_history
	2016-01-18	esmart		Add effective_date and effective_license_attribute_license_value
	2016-04-13	esmart		Add support for change in license_attribute_id
	2016-06-16	acoffel		Oracle contract cancel
	2016-07-27	cnovac		cleverbridge subscription disable
	2016-08-08	cnovac		added @vendor_initiated to suppress creating license_message for cleverbridge
	2016-12-01	cnovac		added check to make sure effective_date is not null on update within table
	2017-05-11	esmart		remove check for process date in the case of non-cancel
	2017-05-16	esmart		Change use of start/end date on partner_license
	2017-11-02	cnovac		Added part to check if you are updating same values for attribute id = 10 to return out of proc
	2018-04-20	cnovac		Added 1.1 to make call to usp_license_insert_effective_object
	2018-12-04	rvinoche	Ignoring order_items with secondary hierarchies for billing entity logic 
	2019-01-02	rvinoche	Re-factor for gsmc phase 2 - moving usage autobilling attributes to effective_object model only
	2019-03-07	cnovac		took out references to effective columns in attribute
	2019-05-07	cnovac		Added code in section 4.1 where it looks for cancels to make sure we cancel all license_categories
	2019-05-30	cnovac		Fixed bug where we weren't writing to effective object if there were no rows already in table object
	2019-07-16	jnavarra	Allow execution without order_header_id or order_item_id. Remove restriction on AR update.
	2019-07-19	rvinoche	Abstracted partner license decision to usp_partner_license_transaction_controller
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2019-09-25	cnovac		Changed code to skip entity approval if just dealing with AR status change
	2020-04-01	wbarton		Adding section 3.4.3 to handle AR opt-out logic in license_effective_object
	2020-06-22	wbarton		Modifying section 3.4.3 to also handle AR opt-in logic in license_effective_object for cases where the license has more than 1 category returned via the profile.
	2021-12-08  psatish		Added Perpetual billing model id if the perpertual auto renewal contract is cancelled
	DESCRIPTION
	insert license attribute license

*/

AS

	set nocount on

	declare	@license_attribute_license_id int,
			@license_category_id tinyint,
			@modified_date datetime = getdate(),	
			@current_license_attribute_license_value int,	
			@current_autobilling_attribute int,
			@additional_cycles int,
			@cancel_effective_date datetime,
			@oracle_template_name varchar(50), 
			@partner_license_id int,
			@order_partner_id int,
			@salesforce_opportunity_id varchar(18),
			@payment_header_id int,
			@order_license_usage_id int,
			@oracle_invoice_number int,
			@comment nvarchar(max),
			@license_transaction varchar(max),	
			@merchant_id varchar(50),
			@line_item int,
			@payment_subscription_id int,
			@license_message_value_str varchar(200),
			@license_message_id int,
			@license_effective_object_json varchar(max),
			@pending_partner_license_transaction int, 
			@response_code int,
			@message varchar(100),
			@loop_value int,
			@loop_max int

	declare @license_effective_object_additional_categories table (id int identity(1,1), license_category
_id tinyint)

	begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.0) @license_category_id
		select @license_category_id = isnull(plc.license_category_id, lcl.license_category_id)
		from license l
		left join license_category_license lcl on lcl.license_id = l.license_id
		left join order_item oi on oi.order_item_id = @order_item_id
		left join product_license_category plc on plc.product_id = oi.product_id
		where l.license_id = @license_id

		select @order_header_id = isnull(@order_header_id, order_header_id)
		from dbo.order_item
		where order_item_id = @order_item_id

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) partner_license
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--do not go into entity approval if change is for AR since it's not needed.
		if @license_attribute_id != 1
		begin

			-- 2.1) partner_license
			declare @is_allowed bit, @partner_id int, @partner_license_source_id tinyint;

			if @partner_license_status_id <> 2 or @partner_license_status_id is null
				select @is_allowed = is_allowed, @partner_id = partner_id, @partner_license_source_id = partner_license_source_id
				from dbo.fn_partner_license_transaction_controller(@license_id, @effective_date, @order_header_id, null)

			if @is_allowed = 0
			begin
        
				-- 2.1.1) insert partner_license
				exec usp_partner_insert_partner_license @license_id,@partner_id,1,@partner_license_source_id,@modified_by,@comment,@order_header_id,@partner_license_id output

				select @license_transaction = (select 'usp_license_update_license_attribute_license' as 'procedure', @license_id as '@license_id', @license_attribute_id as '@license_attribute_id', @license_attribute_license_value as '@license_attribute_license_value', @modified_by as '@modified_by', @order_header_id as 'order_header_id', @order_item_id as '@order_item_id', @effective_date as '@effective_date' for json Path, without_array_wrapper)

				exec usp_partner_insert_partner_license_transaction @partner_license_id,1,@license_transaction

				return
			end

		end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) autorenewal 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @license_attribute_id = 1 -- not usage autobilling attributes
		begin
			select @license_attribute_license_id = license_attribute_license_id,
				@current_license_attribute_license_value = license_attribute_license_value
			from dbo.license_attribute_license
			where license_id = @license_id and license_attribute_id = @license_attribute_id

			-- 3.1) insert new
			if @license_attribute_license_id is null
			begin
				-- 3.1.1) insert
				insert into license_attribute_license(license_attribute_id, license_id, license_attribute_license_value, insert_date, insert_by, modified_date, modified_by)
				select @license_attribute_id, @license_id, @license_attribute_license_value, @modified_date, @modified_by, @modified_date, @modified_by
			end
			else if @current_licens
e_attribute_license_value <> @license_attribute_license_value
			begin
				-- 3.3.1) insert history
				insert into license_attribute_license_history (license_attribute_license_id, license_attribute_id, license_id, license_attribute_license_value, insert_date, insert_by, modified_date, modified_by, start_date, end_date)
				select distinct cla.license_attribute_license_id, cla.license_attribute_id, cla.license_id, cla.license_attribute_license_value, cla.insert_date, cla.insert_by, cla.modified_date, cla.modified_by, isnull(clah.modified_date, cla.modified_date), @modified_date
				from license_attribute_license cla
				left outer join license_attribute_license_history clah 
					on cla.license_id = clah.license_id and cla.license_attribute_id = clah.license_attribute_id
				where cla.license_attribute_license_id = @license_attribute_license_id

				update license_attribute_license
				set license_attribute_id = @license_attribute_id,
					license_attribute_license_value = @license_attribute_license_value,
					modified_date = @modified_date,
					modified_by = @modified_by
				from license_attribute_license
				where license_attribute_license_id = @license_attribute_license_id

			end

			 -- 3.4.2) license_effective_object
			select @license_effective_object_json = (
			select license_id = @license_id, license_category_id = @license_category_id, license_autorenewal_value = @license_attribute_license_value, effective_start_date = isnull(@effective_date, @modified_date), order_item_id = @order_item_id
			for json path)

			exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_attribute_license'

			-- 3.4.3) license_effective_object maintenance. This is needed so a license_attribute_license_value change can apply to other license categories that are not specified in the transaction being processed
			--Finding instances where there are additional full license categories in the profile, whose effective license_autorenewal_value doesn't match the current change being processed
			insert into @license_effective_object_additional_categories (license_category_id)
			select p.license_category_id
			from dbo.fn_license_select_license_profile(@license_id) p
			where p.license_category_id <> @license_category_id	
				and p.category_type_id = 1 --Full only
				--Category either has no effective_value for AR, or <> @license_attribute_license_value
				and (dbo.fn_license_select_effective_object_element(@license_id, p.license_category_id, 'license_autorenewal_value', isnull(@effective_date, @modified_date)) is null or dbo.fn_license_select_effective_object_element(@license_id, p.license_category_id, 'license_autorenewal_value', isnull(@effective_date, @modified_date)) <> @license_attribute_license_value)		
			
			--For opt-outs only: Finding additional license categories that exist in license_effective_object with a license_autorenewal_value. This is common for Consumer refunds, where category will change and the previous category will not be in the license profile.
			if @license_attribute_license_value <> 1
				begin		
					insert into @license_effective_object_additional_categories (license_category_id)
					select e.license_category_id
					from dbo.fn_license_select_effective_object_table(@license_id, isnull(@effective_date, @modified_date)) e
						left join @license_effective_object_additional_categories ac
							on ac.license_category_id = e.license_category_id
					where e.effective_object_id = 4 --license_autorenewal_value
						and e.license_category_id <> @license_category_id
						and e.effective_value <> @license_attribute_license_value
						and ac.license_category_id is null --Not already inserted into @license_effective_object_additional_categories
				end

			if exists (select 1 from @license_effective_object_additional_categories)
				begin
					select @
loop_value = 1, @loop_max = (select max(id) from @license_effective_object_additional_categories)
					while @loop_value <= @loop_max
						begin
							select @license_effective_object_json = (
							select license_id = @license_id, license_category_id = license_category_id, license_autorenewal_value = @license_attribute_license_value, effective_start_date = isnull(@effective_date, @modified_date)
							from @license_effective_object_additional_categories
							where id = @loop_value
							for json path)

							exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_attribute_license'

							set @license_effective_object_json = null
							set @loop_value = @loop_value + 1
						end
				end
		END

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) autobilling
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @license_attribute_id <> 1 --usage autobilling attributes
		begin

			select @current_autobilling_attribute = dbo.fn_license_select_effective_object_element(@license_id, 220, 'license_attribute_license_value', isnull(@effective_date, @modified_date))

			-- 4.1) cancel
			if @license_attribute_license_value in (20,120,220)
			begin
				if @effective_date is null
				begin
					-- 4.1.1) @cancel_effective_date
					select @additional_cycles = case when @license_attribute_license_value in (120,220) then -1 else 0 end
					exec usp_billing_select_cancel_effective_date @license_id, @additional_cycles, @cancel_effective_date output

					-- 4.1.2) verify @effective_date in the case of cancel
					if @cancel_effective_date is not null
					begin
						select @effective_date = case when @effective_date < @cancel_effective_date then @cancel_effective_date else @effective_date end
					end
				end

				--basically we want to cancel all license_attribute_license_value records for every license_category
				select @license_effective_object_json = (
				select license_id = @license_id, license_category_id = fn.license_category_id, license_attribute_license_value = @license_attribute_license_value, effective_start_date = isnull(@effective_date, @modified_date), order_item_id = @order_item_id
				from fn_license_select_effective_object_table(@license_id, getdate()) fn
				where fn.effective_object_id = 2 --license_attribute_license_value
				for json path)

				if @license_effective_object_json is not null
					exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_attribute_license'
		
			end

			select @license_effective_object_json = null
			select @license_effective_object_json = (
			select license_id = @license_id, license_category_id = @license_category_id, license_attribute_license_value = @license_attribute_license_value, effective_start_date = isnull(@effective_date, @modified_date), order_item_id = @order_item_id
			for json path)

			if @license_effective_object_json is not null
				exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_attribute_license'

		end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 5.) oracle contract cancel 
		-- -----------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------

		-- 5.1) insert oracle contract cancel when moving from Utility to other
		if @current_autobilling_attribute in( 12,13) and @license_attribute_license_value not in( 12,13)
		begin 
			select @oracle_template_name = 'cancel_autobilling'

			declare @oracle_update_output table (oracle_update_id int)

			insert into @oracle_update_output (oracle_update_id)
			exec usp_oracle_insert_oracle_update @salesforce_opportunity_id, @payment_header_id, @oracle_template_name, @oracle_invoice_number, @order_license_usage_id, @license_id

		end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 5.) cleverbridge subscription disable
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 5.1) see if license last purchase came through CB and if disabled, send to license_message to disable
		if isnull(@vendor_initiated, 0) = 0 and @current_license_attribute_license_value != @license_attribute_license_value and @license_attribute_license_value in (0, 2, 3) --Inactive, Back office disable, CSI disable
		begin
			exec usp_order_select_payment_merchant @license_id = @license_id, @merchant_id = @merchant_id output, @line_item = @line_item output, @payment_subscription_id = @payment_subscription_id output

			if @merchant_id = 'cleverbridge' and @line_item is not null and @payment_subscription_id is not null
			begin
				set @license_message_value_str = 'line_item=' + str(@line_item) + ',' + 'payment_subscription_id=' + str(@payment_subscription_id)
				select @effective_date = isnull(@effective_date, getdate())
				exec usp_message_insert_license_message @license_id, 11, @effective_date, @effective_date, @effective_date, @license_message_value_str, @license_message_id output, @return_result = 0
			end

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_attribute_license_history]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_attribute_license_history]

(
	@license_attribute_license_object type_license_attribute_license_history READONLY,
	@modified_date datetime
)

AS

	set nocount on		

	declare	@current_license_attribute_license type_license_attribute_license_history,
			@current_license_attribute_license_history type_license_attribute_license_history,
			@modified_by varchar(20) = suser_sname(),
			@response_code int,
			@message varchar(100)

	begin try

	--set the current license_attribute_license object passed in to local variable and join back to license_attribute_license to validate it's a good license_id and not a duplicate update that just happened
	insert @current_license_attribute_license (license_id, license_attribute_id, license_attribute_license_value, modified_date)
	select lalo.license_id, lalo.license_attribute_id, lalo.license_attribute_license_value , lalo.modified_date
	from @license_attribute_license_object lalo, license_attribute_license lal
	where lalo.license_id = lal.license_id
	and lal.license_attribute_license_value != lalo.license_attribute_license_value
		
	if @@rowcount > 0
		
		begin
		--set the license_attribute_license_history object to most current row to ensure we don't insert dups in next procedure
		insert @current_license_attribute_license_history (license_id, license_attribute_id, license_attribute_license_value, modified_date)
		select lah.license_id, lah.license_attribute_id, lah.license_attribute_license_value, lah.modified_date
		from @current_license_attribute_license tla, license_attribute_license_history lah
		where lah.license_id = tla.license_id
		and lah.license_attribute_license_history_id = (select max(license_attribute_license_history_id) from license_attribute_license_history where license_id = tla.license_id)

		--insert only records that have changed or that don't exist at all from query above, meaning this is first insert into history table
		insert into license_attribute_license_history (license_attribute_id, license_id, license_attribute_license_value, modified_date, start_date, end_date)
		select distinct cla.license_attribute_id, cla.license_id, cla.license_attribute_license_value, @modified_date, isnull(clah.modified_date, cla.modified_date), @modified_date
		from @current_license_attribute_license cla
		left outer join @current_license_attribute_license_history clah on cla.license_id = clah.license_id
		where cla.license_attribute_license_value != clah.license_attribute_license_value
		or clah.license_id is null

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_attribute_parent_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_attribute_parent_license]

(
	@license_id int,
	@parent_warning_status varchar(10),
	@modified_by varchar(20)

)
	
/*	
	DATE		AUTHOR		REMARKS
	2017-08-24	acoffel		Initial creation
	2019-01-09	rvinoche	Support autobilling attributes living only in license_effective_object

	DESCRIPTION
	insert license attribute license
	
*/

AS
		set nocount on			

	declare	@license_attribute_license_id int,
			@modified_date datetime = getdate(),
			@current_license_attribute_id int,
			@current_license_attribute_license_value int,
			@last_license_attribute_license_value int,
			@cancel_attribute_value INT,
			@response_code int,
			@message varchar(100)

	begin try

	if @modified_by is NULL
		begin 
			select @modified_by = system_user
		end

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) select
	select @current_license_attribute_id = f.effective_value,
			@current_license_attribute_license_value = f.effective_value
	from dbo.fn_license_select_effective_object_table(@license_id, @modified_date) f
	inner join dbo.license_category_license lcl
		on lcl.license_id = @license_id
	inner join dbo.license_attribute_license_value v
		on v.license_attribute_license_value = f.effective_value
	where f.effective_object_id = 2
		and f.license_category_id = lcl.license_category_id

	-- 1.1) set last license_attribute_license_value
	select top (1) @last_license_attribute_license_value = f.effective_value
	from  dbo.license_category_license lcl
	cross apply dbo.fn_license_select_effective_object_element_history(@license_id,'license_attribute_license_value',lcl.license_category_id) f
	inner join dbo.license_attribute_license_value v
		on v.license_attribute_license_value = f.effective_value
	where lcl.license_id = @license_id
		and f.effective_end_date < @modified_date
	order by f.effective_end_date desc

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--2.1) update on apply
	if @parent_warning_status = 'apply'
	begin
        select @cancel_attribute_value = license_attribute_license_value
		from dbo.license_attribute_license_value
		where license_attribute_id = @current_license_attribute_id
			and license_attribute_license_value_description like '%annual%'

		exec dbo.usp_license_update_license_attribute_license @license_id, @current_license_attribute_id, @cancel_attribute_value, @modified_by, @modified_date, @allow_past_record_update = 1            

	end

	
	--2.1) update on remove
	if @parent_warning_status = 'remove'
	begin
		exec dbo.usp_license_update_license_attribute_license @license_id, @current_license_attribute_id, @last_license_attribute_license_value, @modified_by, @modified_date, @allow_past_record_update = 1            
	end

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_attribute_license failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_na
me()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_autorenewal_cycle]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_update_license_autorenewal_cycle]

(
	@license_id INT,
	@message_autorenewal_cycle_id TINYINT,
	@billing_day_of_month TINYINT = NULL,
	@product_type_id INT = NULL,
	@effective_date DATETIME = NULL,
	@order_header_id INT = NULL,
	@partner_license_status_id TINYINT = NULL,
	@order_item_id INT = NULL
)

/*	
	DATE			AUTHOR		REMARKS
	2014-11-13		esmart		Initial creation
	2016-01-25		esmart		
	2016-05-11		esmart		Add @effective_date
	2016-12-02		acoffel		set partner_id based on active start and end date
	2017-05-11		esmart		Change logic for updating effective date
	2017-05-16		esmart		Change use of start/end date on partner_license
	2018-04-20		cnovac		Added 1.1 to make call to usp_license_insert_effective_object
	2018-10-24		rvinoche	Keep current billing day of month when upsells come in during months with less days	
	2018-11-01		cnovac		took out references to effective columns
	2018-12-04		rvinoche	Ignoring order_items with secondary hierarchies for billing entity logic 
	2019-07-19		rvinoche	Abstracted partner license decision to usp_partner_license_transaction_controller
	2019-09-06		cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2019-09-26		cnovac		Updated code to skip entity approval part if not a business license
	2019-11-06		esmart		Modify check for effective object to not insert in case of NULL @billing_day_of_month
	2021-08-23		gblandford	Added NOLOCK hints to queries to prevent deadlocking issues (ITSM#3560296)
	2021-12-09		kconvery	Add a check for CSB license then modify billing_date_of_month = 15
	2022-03-21      psatish		ALM#992 Set the billing date of month as 15 for CEP and OTSF licenses

	DESCRIPTION
	insert license_autorenewal_cycle

*/

AS
	
	SET NOCOUNT ON			

	DECLARE	@license_autorenewal_cycle_id INT,
			@current_message_autorenewal_cycle_id TINYINT,
			@current_billing_day_of_month TINYINT,
			@last_modified_date DATETIME,
			@partner_license_id INT,
			@comment NVARCHAR(MAX),
			@modified_by VARCHAR(20), 
			@product_line_id INT, 
			@license_transaction VARCHAR(MAX),
			@process_date DATETIME,
			@license_category_id TINYINT,
			@license_effective_object_json VARCHAR(MAX),
			@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

	SELECT @last_modified_date = GETDATE()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @product_line_id
	SELECT @product_line_id = l.product_line_id,
		   @license_category_id = ISNULL(plc.license_category_id, lcl.license_category_id)
	FROM license l WITH (NOLOCK)
	LEFT JOIN license_category_license lcl WITH (NOLOCK) ON lcl.license_id = l.license_id
	LEFT JOIN order_item oi WITH (NOLOCK) ON oi.order_item_id = @order_item_id
	LEFT JOIN product_license_category plc WITH (NOLOCK) ON plc.product_id = oi.product_id
	WHERE l.license_id = @license_id

	-- 1.1) current record
	SELECT @license_autorenewal_cycle_id = license_autorenewal_cycle_id,
		@current_message_autorenewal_cycle_id = message_autorenewal_cycle_id,
		@current_billing_day_of_month = billing_day_of_month
	FROM license_autorenewal_cycle WITH (NOLOCK)
	WHERE license_id = @license_id

	-- 1.2) @effective_date
	
	-- 1.2.1) @process_date for autobilling
	SELECT @process_date = process_date
	FROM license_message WITH (NOLOCK)
	WHERE license_id = @license_
id AND message_type_id = 10 AND message_status_id = 1
	
	IF @process_date IS NOT NULL AND @effective_date IS NULL
		BEGIN
		SELECT @effective_date = @process_date
		END

	--1.3) last day of month
	IF @billing_day_of_month IS NOT NULL AND DAY(EOMONTH(@effective_date)) = @billing_day_of_month AND @current_billing_day_of_month > @billing_day_of_month
		BEGIN 
		SELECT @billing_day_of_month = @current_billing_day_of_month -- this will ensure that upsells from SFDC coming in on last day of month like the 30th with not change from billing day of month as 31st
		END

	--1.3.1) CSB product check, locking billing day of month to the 15th
	if @license_category_id = 200
		begin
			set @billing_day_of_month = 15
		end

	if exists(select 1 from dbo.license_category_license where license_id=@license_id and license_category_id in(233,234))
		begin
			set @billing_day_of_month = 15
		end
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--only get into entity approval if a business keycode.  Otherwise, it's not relevant
	IF @product_line_id IN (55, 300)
	BEGIN

		-- 2.1) partner_license
		DECLARE @is_allowed BIT, @partner_id INT, @partner_license_source_id TINYINT;

		IF @partner_license_status_id <> 2 OR @partner_license_status_id IS NULL
			SELECT @is_allowed = is_allowed, @partner_id = partner_id, @partner_license_source_id = partner_license_source_id
			FROM dbo.fn_partner_license_transaction_controller(@license_id, @effective_date, @order_header_id, NULL)
            

		-- 2.2) billing_day_of_month override for partners
		SELECT @billing_day_of_month = CASE WHEN cp.configuration_value IS NULL THEN @billing_day_of_month ELSE cp.configuration_value END
		FROM partner_configuration_partner cp WITH (NOLOCK)
		INNER JOIN partner_configuration c WITH (NOLOCK)
			ON c.partner_configuration_id = cp.partner_configuration_id
		WHERE cp.partner_id = @partner_id AND c.configuration_name = 'billing_day_of_month'

		-- 2.3) insert pending partner_license
		IF @is_allowed = 0
		BEGIN

			-- 2.3.1) insert partner_license
			EXEC usp_partner_insert_partner_license @license_id,@partner_id,1,@partner_license_source_id,@modified_by,@comment,@order_header_id,@partner_license_id OUTPUT

			-- 2.3.2) insert partner_license_transaction	
			SELECT @license_transaction = (SELECT 'usp_license_update_license_autorenewal_cycle' AS 'procedure', @license_id AS '@license_id', @message_autorenewal_cycle_id AS '@message_autorenewal_cycle_id', @billing_day_of_month AS '@billing_day_of_month', @modified_by AS '@modified_by', @order_header_id AS 'order_header_id', @order_item_id AS '@order_item_id', @effective_date AS '@effective_date' FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)

			EXEC usp_partner_insert_partner_license_transaction @partner_license_id,1,@license_transaction

			RETURN
		END

	END
        
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) insert
	IF @license_autorenewal_cycle_id IS NULL
	BEGIN
		INSERT INTO license_autorenewal_cycle(license_id, message_autorenewal_cycle_id, billing_day_of_month)
		VALUES(@license_id, @message_autorenewal_cycle_id, @billing_day_of_month)
	END
	-- 3.2) update
	ELSE IF (@current_message_autorenewal_cycle_id <> @message_aut
orenewal_cycle_id) OR 
			(@current_billing_day_of_month IS NULL AND @billing_day_of_month IS NOT NULL) OR
			(@current_billing_day_of_month IS NOT NULL AND @billing_day_of_month IS NOT NULL AND @current_billing_day_of_month <> @billing_day_of_month)
	BEGIN

	-- 3.2.1) insert audit
		INSERT INTO license_autorenewal_cycle_audit(license_id, message_autorenewal_cycle_id, billing_day_of_month, license_autorenewal_cycle_id, last_modified_date, audit_date)
		SELECT license_id, message_autorenewal_cycle_id, billing_day_of_month, license_autorenewal_cycle_id, last_modified_date, @last_modified_date
		FROM license_autorenewal_cycle WITH (NOLOCK)
		WHERE license_id = @license_id

	-- 3.2.2) update
		UPDATE license_autorenewal_cycle
		SET	message_autorenewal_cycle_id = @message_autorenewal_cycle_id, billing_day_of_month = @billing_day_of_month, last_modified_date = @last_modified_date
		WHERE license_id = @license_id
	END

	-- 3.2.3) write to license_effective_object if business product
	IF @product_line_id IN (55, 300) AND @billing_day_of_month IS NOT NULL
	BEGIN

		SELECT @license_effective_object_json = (
		SELECT license_id = @license_id, license_category_id = @license_category_id, @billing_day_of_month AS billing_day_of_month, effective_start_date = ISNULL(@effective_date, @last_modified_date), order_item_id = @order_item_id
		FOR JSON PATH)

		EXEC usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_autorenewal_cycle'

	END

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'failed to update license_autorenewal_cycle for license_id ' + CONVERT(VARCHAR(20),@license_id)
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_autorenewal_opt_out]
-- =============================================================================

 CREATE PROCEDURE [dbo].[usp_license_update_license_autorenewal_opt_out]

(
		@license_autorenewal_opt_out_id int,
		@status varchar(10)
			
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-24	esmart		Initial creation
	2016-05-02	mrobbins	added expiration_date pull to set dates on discount
	2016-08-15	mrobbins	added check for AR charge and returned variable to PHP for email confirmation

	DESCRIPTION
	update license_autorenewal_opt_out
*/

AS
	set nocount on				

	declare	@license_id int,
			@cart_discount_id int,
			@opt_in_license_autorenewal_opt_out_id int,
			@response_code int,
			@message varchar(100),
			@start_date datetime,
			@end_date datetime,
			@charge_likely int

	begin try

	set @charge_likely = 0
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select details
	select @license_id = license_id,
			@cart_discount_id = d.cart_discount_id
	from license_autorenewal_opt_out o
	left join message_campaign_cart_discount d
		on o.message_campaign_id = d.message_campaign_id
	where license_autorenewal_opt_out_id = @license_autorenewal_opt_out_id

	--select license_id = @license_id, cart_discount_id = @cart_discount_id
	--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) opt out
	if @status = 'opt_out'
		begin

			--select count(*) oil_count from order_item_license where license_id = @license_id and insert_date >= getdate()-30 and insert_date <= getdate()

			if (select count(*) from order_item_license where license_id = @license_id and insert_date >= getdate()-30 and insert_date <= getdate()) > 0
				begin 
					set @charge_likely = 1
				end
			
			if @charge_likely = 0
				begin
					
					--select @license_id license_id

					--select count(*) lal_count
					--	from license_summary ls
					--		inner join license_attribute_license lal
					--			on ls.license_id = lal.license_id
					--	where ls.license_id = @license_id
					--		and lal.license_attribute_license_value = 1
					--		and ls.capability_expiration_date >= getdate()
					--		and ls.capability_expiration_date <= getdate() + 7

					if (select count(*)
						from license_summary ls
							inner join license_attribute_license lal
								on ls.license_id = lal.license_id
						where ls.license_id = @license_id
							and lal.license_attribute_license_value = 1
							and ls.capability_expiration_date >= getdate()
							and ls.capability_expiration_date <= getdate() + 7) > 0 
					begin
						set @charge_likely = 1
					end
				end


			-- 2.1.1) update license_autorenewal_opt_out
			update license_autorenewal_opt_out 
			set status = @status
			where license_autorenewal_opt_out_id = @license_autorenewal_opt_out_id

			-- 2.1.2) usp_license_update_disable_autorenewal
			exec usp_license_update_disable_autorenewal @license_id,@csi_user_id='WEBSITE',@comment='disabled from website'

			-- 2.1.3) remove AR license_cart_discount from previous opt_in
			select @opt_in_license_autorenewal_opt_out_id  = (select max(license_autorenewal_opt_out_id) from license_autorenewal_opt_out where license_id = @license
_id and status = 'opt_in')
		
			--select opt_in_license_autorenewal_opt_out_id = @opt_in_license_autorenewal_opt_out_id

			if @opt_in_license_autorenewal_opt_out_id is not null
				begin
					select @cart_discount_id = d.cart_discount_id
					from license_autorenewal_opt_out o
					inner join message_campaign_cart_discount d
						on o.message_campaign_id = d.message_campaign_id
					where license_autorenewal_opt_out_id = @opt_in_license_autorenewal_opt_out_id

					--select cart_discount_id = @cart_discount_id, license_id = @license_id

					delete from license_cart_discount where license_id = @license_id and cart_discount_id = @cart_discount_id

				end	
			


		end

	-- 2.2) opt int
	if @status = 'opt_in'
		begin
			-- 2.2.1) update license_autorenewal_opt_out
			update license_autorenewal_opt_out 
			set status = @status
			where license_autorenewal_opt_out_id = @license_autorenewal_opt_out_id

			select @start_date = capability_expiration_date - 8,
				@end_date = capability_expiration_date + 30
			from license_summary
			where license_id = @license_id

			-- 2.2.2) usp_license_insert_license_cart_discount
			exec usp_license_insert_license_cart_discount @license_id, @cart_discount_id, @start_date,@end_date
		end

	select @charge_likely charge_likely
	end try



	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_update_license_capability]

(
	@license_capability_id int, 
	@capability_type_id int, 
	@capability_activation_days int, 
	@capability_activation_date datetime, 
	@capability_expiration_date datetime,
	@response_code int output,
	@message varchar(100) output
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2006-08-08	esmart		Put check for blank dates and set to NULL
	2006-09-19	esmart		Add support for capability history and error messaging
	2006-10-10	esmart		Modified logic to be CSI only
	2006-12-05	esmart		Create support for enterprise and SME. Add logic to take expiration date instead of days.
	2007-02-12	esmart		Correct problem with updates to non-activated licenses
	2008-03-04  bjordan		added error handling
	2024-08-13  eteo        ECOM-4318 Commented out 2 instances of "exec usp_license_sub_insert_initial_license_capability_history @license_id"

	DESCRIPTION
	update license_capability
*/
begin try
set nocount on

	declare @license_id int,
		@license_status_id int,
		@capability_id int,
		@transaction_date datetime,
		@product_line_id int,
		@capability_change_reason_id int,
		@system_user varchar(50),
		@current_capability_activation_date datetime,
		@current_capability_expiration_date datetime,
		@days_remaining int
		

	set @transaction_date = getdate()
	set @capability_change_reason_id = 4 -- customer service
	set @system_user = system_user

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- @license_capability_id
	select @license_id = license_id,
		@capability_id = capability_id,
		@current_capability_activation_date = capability_activation_date,
		@current_capability_expiration_date = capability_expiration_date
	from license_capability
	where license_capability_id = @license_capability_id

	if @license_id is null 
		begin
		set @response_code = -100
		set @message = '@license_capability_id not found'
		return
		end

	-- @capability_type_id
		select @response_code =  case when count(*) = 0 then -110 else 0	 end,
			@message = case when count(*) = 0 then 'Invalid capability_type_id' else '' end
		from capability_type
		where capability_type_id = @capability_type_id

		if @response_code < 0 	
			begin 
				RAISERROR (@message, 11, 0)
			end	

	-- @capability_activation_days
	if @capability_activation_days = 0 or @capability_activation_days is null
		begin
		if @capability_expiration_date is not null and datediff(dd,@transaction_date,@capability_expiration_date) <> 0
			begin
			if @current_capability_expiration_date < @transaction_date -- if expired
				begin
				set @capability_activation_days = datediff(dd,@transaction_date,@capability_expiration_date)
				end
			else 
				begin
				set @capability_activation_days = datediff(dd,@current_capability_expiration_date,@capability_expiration_date)
				end
			end
		else 
			begin
				set @response_code = -120
				set @message = 'capability_activation_days must be greater than 0'
				RAISERROR (@message, 11, 0)
			end
		end
	
	set @days_remaining = 
			case
				when @current_capability_activation_date is null then @capability_activation_days
				else isnull(datediff(dd,@transaction_date,@current_capability_expiration_date),0)	
			en
d

	-- @product_line_id 
	select @product_line_id = product_line_id,
		@license_status_id = license_status_id
	from license
	where license_id = @license_id		
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) setup temp product_capability table
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select capability_id, 
			capability_type_id =
				case 
					when license_capability_id = @license_capability_id then @capability_type_id
					else capability_type_id
				end,
			capability_activation_days =
				case
					when @days_remaining >= 0 and license_capability_id = @license_capability_id and isnull(datediff(dd,@transaction_date,capability_expiration_date),0)+@capability_activation_days < 0 then isnull(datediff(dd,@transaction_date,capability_expiration_date),0)*-1
					when @days_remaining >= 0 and license_capability_id = @license_capability_id and isnull(datediff(dd,@transaction_date,capability_expiration_date),0)+@capability_activation_days >= 0 then @capability_activation_days
					when @days_remaining < 0 and license_capability_id = @license_capability_id then @capability_activation_days
					else 0
				end
		into #temp_product_capability
		from license_capability 
		where license_id = @license_id
	
-- select '#temp_product_capability', * from #temp_product_capability
	
	if @product_line_id in (1,6,11,13)
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) SS+AV
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin	
		-- 3.1) check to see if seed values in license_capability_history are in place
		-- exec usp_license_sub_insert_initial_license_capability_history @license_id	


		-- 3.2) Set up temp table with the current and product capability data
				select 	days_remaining = 
						case 
							when @license_status_id = 0 and l.capability_activation_date is null then isnull(l.capability_activation_days,0)
							when @license_status_id = 0 and l.capability_activation_date is not null then isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
							when @license_status_id = 1 and l.capability_activation_date is null then isnull(l.capability_activation_days,0)
							when @license_status_id = 1 and l.capability_activation_date is not null and datediff(dd,@transaction_date,l.capability_expiration_date) < 0 then 0
							when @license_status_id = 1 and l.capability_activation_date is not null and datediff(dd,@transaction_date,l.capability_expiration_date) >= 0 then isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
							else isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
						end,
					l.license_capability_id,
					l.license_id,
					l.capability_id,
					l.capability_type_id,
					product_capability_type_id = c.capability_type_id,
					l.capability_activation_days, 
					product_capability_activation_days = c.capability_activation_days,
					l.capability_activation_date, 
					l.capability_expiration_date, 
					l.insert_date, 
					l.insert_by, 
					l.modified_date, 
					l.modified_by,
					last_capability_type_id = (select top 1 capability_type_id from license_capability_history where license_capability
_id = l.license_capability_id),
					last_days_contiguous = isnull((select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc),0)
				into #temp_renew_license
				from license_capability l
				left join #temp_product_capability c 
					on c.capability_id = l.capability_id
				where  l.license_id = @license_id
	
 -- select '#temp_renew_license', * from #temp_renew_license
				
				-- 3.2) Get spy sweeper details 
				declare @ss_days_remaining int,
					@ss_activation_days int,
					@ss_activation_days_product int,
					@ss_activation_date datetime,
					@ss_new_activation_date datetime,
					@ss_expiration_date datetime,
					@max_activation_days int,
					@min_expiration_date datetime
	
				if @product_line_id in (1,6,11,13) -- SS Suite
					begin
						select @ss_days_remaining = days_remaining,
							@ss_activation_days = capability_activation_days,
							@ss_activation_days_product = product_capability_activation_days,
							@ss_activation_date = capability_activation_date,
							@ss_new_activation_date = 
								case 
									when capability_activation_date is null then null
									when  capability_activation_date is not null and days_remaining = 0 then @transaction_date 
									else  dateadd(dd,-1*days_remaining,capability_expiration_date)
								end,
							@ss_expiration_date = capability_expiration_date 
						from #temp_renew_license
						where  capability_id = 1
	
						select @max_activation_days = 
								case
									when @capability_activation_days < 0 then min(product_capability_activation_days)
									else max(product_capability_activation_days)

								end,
							@min_expiration_date = min(capability_expiration_date)
						from #temp_renew_license
					end		

/*	 			select ss_activation_days = @ss_activation_days , 
	 				ss_days_remaining = @ss_days_remaining, 
	 				ss_activation_days_product = @ss_activation_days_product, 
	 				ss_activation_date = @ss_activation_date,
	 				ss_new_activation_date = @ss_new_activation_date, 
					ss_expiration_date = @ss_expiration_date,
	 				max_activation_days = @max_activation_days,
					min_expiration_date = @min_expiration_date
*/
				-- 3.3) create second temp table that takes the current and new capability data to determine new days, activation date, and capability type						

				select 
					new_capability_type_id = 
						case

							-- SS
							when capability_id = 1 then capability_type_id
							-- Non-SS (AV)
							when capability_id <> 1 and product_capability_type_id = 1  then product_capability_type_id
							when capability_id <> 1 and capability_type_id in (1,2,3) and product_capability_type_id =  4 and days_remaining > 0 then capability_type_id
							when capability_id <> 1 and capability_type_id in (1,2,3) and product_capability_type_id in (2,3) and days_remaining > 0 then product_capability_type_id
							when capability_id <> 1 and days_remaining = 0 then product_capability_type_id
						end,
					new_capability_activation_days = 
						case
							-- SS
							when capability_id = 1 and @ss_activation_days_product <> 0 then @ss_activation_days_product + @ss_days_remaining
							when capability_id = 1 and @ss_activation_days_product = 0 and @max_activation_days < 0 then @ss_days_remaining
							when capability_id = 1 and @ss_activation_days_product = 0 and @max_activation_days > 0 and @min_expiration_date <> @ss_expiration_date and dateadd(dd,@max_activation_days,@min_expiration_date) > @ss_expiration_date then datediff(dd,@ss_expiration_date,dateadd(dd,@max_activation_days,@min_expiration_date)) + @ss_days_remaining
							when capability_id = 1 and @ss_activation_days_product = 0 and @max_activation_days > 0 and @min_expiration_date = @ss_expiration_date and @capability_id <> 1 then @max_activation_days + @ss_days_remaining
							when capability_id
 = 1 and @ss_activation_days_product = 0 and @max_activation_days > 0 and @min_expiration_date = @ss_expiration_date and @capability_id = 1 then @ss_days_remaining
							
							-- Non-SS (AV)
							when capability_id <> 1 and @ss_activation_days_product = 0 then @max_activation_days + days_remaining
							when capability_id <> 1 and @ss_activation_days_product < 0 and capability_expiration_date > dateadd(dd,@ss_activation_days_product,@ss_expiration_date)  then datediff(dd,capability_expiration_date, dateadd(dd,@ss_activation_days_product,@ss_expiration_date)) + days_remaining
							when capability_id <> 1 and @ss_activation_days_product < 0 and capability_expiration_date <= dateadd(dd,@ss_activation_days_product,@ss_expiration_date)  then days_remaining
							else days_remaining
						end,
					new_capability_activation_date =	
						case
							-- SS
							when capability_id = 1 then  @ss_new_activation_date
							-- Non-SS (AV)
							when  capability_id <> 1 and product_capability_type_id = 1 then @ss_new_activation_date
							when capability_id <> 1 and capability_type_id = 4 and  product_capability_type_id in (2,3) then @ss_new_activation_date
							else capability_activation_date
/*
							when  capability_id <> 1 and product_capability_type_id = 1 then @ss_new_activation_date
							when capability_id <> 1 and capability_type_id = 4 and  product_capability_type_id in (2,3) then @ss_new_activation_date
							when capability_id <> 1 and capability_type_id in (1,2,3) and product_capability_type_id in (2,3) and days_remaining > 0 then @ss_new_activation_date
							when capability_id <> 1 and product_capability_type_id = 4 and days_remaining > 0 then @ss_new_activation_date
							when capability_id <> 1 and product_capability_type_id = 4 and days_remaining = 0 then null
*/						end,
					*
				into #temp_renew_license2
				from #temp_renew_license								

 --select '#temp_renew_license2', * from #temp_renew_license2

				-- 3.4) update license_capability
				-- add audit records
				exec usp_license_insert_license_capability_audit @license_id

				update license_capability
				set capability_type_id = t.new_capability_type_id,
					capability_activation_days = t.new_capability_activation_days,
					capability_activation_date = t.new_capability_activation_date,
					capability_expiration_date = dateadd(dd, t.new_capability_activation_days,t.new_capability_activation_date),
					modified_date = @transaction_date,
					modified_by = @system_user
				from #temp_renew_license2 t
				inner join license_capability l
					on t.license_capability_id = l.license_capability_id

				
				-- 3.5) add rows to history
				insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, capability_change_reason_id, insert_date, insert_by, modified_date, modified_by, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
				select license_capability_id,					 
					license_id, 
					capability_id, 
					capability_type_id, 
					capability_activation_days = capability_activation_days - days_remaining, 
					capability_activation_date, 
					capability_expiration_date = 
						case
							when capability_activation_date is null then null 
							when capability_activation_date is not null  and t.days_remaining = 0 then capability_expiration_date
							else t.new_capability_activation_date
						end,
					capability_change_reason_id = @capability_change_reason_id,
					insert_date, 
					insert_by, 
					modified_date, 
					modified_by, 
					history_date = @transaction_date,
					history_by = @system_user,
					days_used = isnull(capability_activation_days - days_remaining,0), 
					days_remaining,
					days_added = isnull(new_capability_activation_days,0) - days_remaining, -- isnull(product_capa
bility_activation_days,0),
					days_new = isnull(new_capability_activation_days,0),
					days_contiguous = 
						case 
							when days_remaining > 0 and last_capability_type_id = capability_type_id and isnull(new_capability_activation_days,0) - days_remaining = 0 then last_days_contiguous
							when days_remaining > 0 and last_capability_type_id = capability_type_id and isnull(new_capability_activation_days,0) - days_remaining <> 0 then last_days_contiguous + isnull(new_capability_activation_days,0) - days_remaining 
							when days_remaining = 0 and capability_type_id = product_capability_type_id then last_days_contiguous + isnull(new_capability_activation_days,0)
							when days_remaining = 0 and capability_type_id <> product_capability_type_id then isnull(new_capability_activation_days,0)
							else isnull(new_capability_activation_days,0)
						end
				from #temp_renew_license2 t
	
				
	
				-- 3.6) set effective_date
				--set @effective_date = (select new_capability_activation_date from #temp_renew_license2 where capability_id = 1)
	
	
	 			drop table #temp_renew_license
	 			drop table #temp_renew_license2
		end
	
	else if @product_line_id not in (1,6)
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  Non SS+AV
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin

			--select 'Non SS+AV'
			-- 4.1)  check to see if seed values in license_capability_history are in place
			-- exec usp_license_sub_insert_initial_license_capability_history @license_id				

			-- 4.2) Set up temp table with the current and product capability data
			select 	days_remaining = 
					case 
						when @license_status_id = 0 then isnull(l.capability_activation_days,0)
						when datediff(dd,@transaction_date,l.capability_expiration_date) < 0 then 0
						else isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
					end,
				l.license_capability_id,
				l.license_id,
				l.capability_id,
				l.capability_type_id,
				product_capability_type_id = c.capability_type_id,
				l.capability_activation_days, 
				product_capability_activation_days = c.capability_activation_days,
				l.capability_activation_date, 
				l.capability_expiration_date, 
				l.insert_date, 
				l.insert_by, 
				l.modified_date, 
				l.modified_by,
				last_capability_type_id = (select top 1 capability_type_id from license_capability_history where license_capability_id = l.license_capability_id),
				last_days_contiguous = isnull((select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc),0),
				last_days_total = isnull((select top 1 days_contiguous from license_capability_history where license_capability_id = l.license_capability_id order by license_capability_history_id desc),0)
			into #temp_nonssav_renew_license
			from license_capability l
			left join #temp_product_capability c 
				on c.capability_id = l.capability_id
			where  l.license_id = @license_id


			-- 4.2) create second temp table that takes the current and new capability data to determine new days, activation date, and capability type						
			select new_capability_activation_days = 
					case
				/* case 1 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (1) then days_remaining + product_capability_activation_days
				/* case 2 */	when capability_type_id in (4) then product_capability_activation_days
				/* case 3 */	when days_remaining <= 0 then product_capability_activation_days

				/* case 4 */	when days_remaining > 0 and capability_type_id in (2,3) and product_capability_type_id in (1,2,3) then product_capability_activation_days
				/* case 5 */	when days_remaining > 0 and capability_type_id in (1,2,3) and product_capability_type_id in (4) then capability_activation_days
				/* case 6 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (2,3) then capability_activation_days
					end,
				new_capability_activation_date = 
					case
				/* case 1 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (1) then dateadd(dd,-1*days_remaining,capability_expiration_date)
				/* case 2 */	when capability_type_id in (4) then  dateadd(dd,-1*days_remaining,capability_expiration_date)
				/* case 3 */	when days_remaining <= 0 then null
				/* case 4 */	when days_remaining > 0 and capability_type_id in (2,3) and product_capability_type_id in (1,2,3) then  dateadd(dd,-1*days_remaining,capability_expiration_date)
				/* case 5 */	when days_remaining > 0 and capability_type_id in (1,2,3) and product_capability_type_id in (4) then capability_activation_date
				/* case 6 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (2,3) then capability_activation_date
					end,
				new_capability_type_id = 
					case
				/* case 1 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (1) then product_capability_type_id
				/* case 2 */	when capability_type_id in (4) then product_capability_type_id
				/* case 3 */	when days_remaining <= 0 then product_capability_type_id
				/* case 4 */	when days_remaining > 0 and capability_type_id in (2,3) and product_capability_type_id in (1,2,3) then product_capability_type_id
				/* case 5 */	when days_remaining > 0 and capability_type_id in (1,2,3) and product_capability_type_id in (4) then capability_type_id
				/* case 6 */	when days_remaining > 0 and capability_type_id in (1) and product_capability_type_id in (2,3) then capability_type_id
					end,
				*

			into #temp_nonssav_renew_license2
			from #temp_nonssav_renew_license


			-- 4.4) update license_capability
			-- add audit records
			exec usp_license_insert_license_capability_audit @license_id

			update license_capability
			set capability_type_id = t.new_capability_type_id,
				capability_activation_days = t.new_capability_activation_days,
				capability_activation_date = t.new_capability_activation_date,
				capability_expiration_date = dateadd(dd, t.new_capability_activation_days,t.new_capability_activation_date),
				modified_date = @transaction_date,
				modified_by = @system_user
			from #temp_nonssav_renew_license2 t
			inner join license_capability l
				on t.license_capability_id = l.license_capability_id

		
			-- 4.5) add rows to history
			insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, capability_change_reason_id, insert_date, insert_by, modified_date, modified_by, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
			select license_capability_id, 
				license_id, 
				capability_id, 
				capability_type_id, 
				capability_activation_days = capability_activation_days - days_remaining, 
				capability_activation_date, 
				capability_expiration_date = t.new_capability_activation_date,
				capability_change_reason_id = @capability_change_reason_id,
				insert_date, 
				insert_by, 
				modified_date, 
				modified_by, 
				history_date = @transaction_date,
				history_by = @system_user,
				days_used = isnull(capability_activation_days - days_remaining,0), 
				days_remaining,
				days_added = isnull(product_capability_activation_days,0),
				days_new = isnull(new_capability_activation_days,0),
				days_contiguous = 

						case 
							when days_remaining > 0 and isnull(capability_activation_days - days_remaining,0) > 0 and last_capability_type_id = capability_type_id and days_remaining = new_capability_activation_days then last_days_contiguous
							when days_remaining > 0 and isnull(capability_activation_days - days_remaining,0) > 0 and last_capability_type_id = capability_type_id and days_remaining <> new_capability_activation_days then capability_activation_days - days_remaining + new_capability_activation_days
							when days_remaining > 0 and isnull(capability_activation_days - days_remaining,0) = 0 and last_capability_type_id = capability_type_id then last_days_contiguous + product_capability_activation_days
							else isnull(new_capability_activation_days,0)
						end
			from #temp_nonssav_renew_license2 t


			-- 4.5) set effective_date
			--	set @effective_date = (select new_capability_activation_date from #temp_renew_license2)	

			drop table #temp_nonssav_renew_license
			drop table #temp_nonssav_renew_license2
		end
			
end try
begin catch

      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		
end catch




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_CSI]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_update_license_capability_CSI]
(
	@days int,
	@keycode varchar(40),
	@modified_by varchar(20),
	@parent_warning int = NULL,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-10		esmart		Initial creation
	2010-06-15		dsmelker	Added call to usp_license_update_child_license_capability for Enterprise Licenses
	2014-05-15		esmart		Update child keycode when extending parent
	2015-07-31		esmart		partner_license 
	2015-10-19		esmart		use permission_group_membership to identity Webroot users
	2015-10-27		esmart		Reduce string length for matching on @modified_by
	2016-01-08		esmart		extend @order_entity_approval
	2016-07-27		cnovac		cleverbridge subscription expiration date update
	2016-08-03		esmart		partner_license enhancements
	2017-05-16		esmart		Change use of start/end date on partner_license
	2017-06-19		esmart		Billing entity override based on user group
	2017-08-24		acoffel		Parent warning
	2020-08-27		abelenkiy	Removed license_capability_id from being passed into usp_message_insert_license_message (section 4.1) so end date can be figured out downstream
	

	DESCRIPTION
	update license capability through CSI 
*/

AS

	set nocount on

	declare @license_id int,
			@effective_date datetime,
			@order_item_id int,
			@product_line_id int,
			@license_type_id int,
			@child_license_id int,
			@salesforce_trial_id varchar(18),
			@trial_id int,
			@sfdc_template_id tinyint, 
			@sfdc_update_type_id tinyint,
			@capability_type_id int,
			@insert_license_extension int,

			@partner_license_id int,
			@license_partner_id int,
			@license_entity_approval varchar(500),
			@pending_license_partner_id int,
			@pending_entity_approval varchar(20),
			@partner_entity_approval varchar(20),
			@partner_license_status_id tinyint, 
			@partner_license_source_id tinyint, 
			@comment nvarchar(max),
			@last_modified_user_id varchar(20), 
			@license_transaction varchar(max),
			@partner_id int,

			@merchant_id varchar(50),
			@line_item int,
			@payment_subscription_id int,
			@license_message_value_str varchar(200),
			@license_message_id int,
			@process_date datetime = getdate(),
			@order_header_id int

begin try

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @license_id
			select 
				@license_id = license_id,
				@response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then '@license_id not valid' else '' end,
				@product_line_id = product_line_id,
				@license_type_id = license_type_id
			from license
			where keycode = @keycode
			group by license_id,product_line_id,license_type_id

			if @response_code < 0 	
				begin
					RAISERROR (@message, 11, 0)
				end

		-- 1.2) @days
			if @days = 0 	
				begin
					set @response_code = -120
					set @message = 'Days cannot = 0'
					RAISERROR (@message, 11, 0)
				end

		-- 1.3) @modified_by
			if @modified_by is null
				begin 
				set @modified_by = suser_sname()
				end

		-- 1.4) @salesforce_trial_id
		select @salesforce_trial_id = s.salesforce_trial_id, @trial_id = s.trial_id
		from sfdc_trial s
		inner join trial t
			on s.trial_id = t.trial_id
		where 
t.license_id = @license_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) partner
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) get partner for account
		select @partner_id = pa.partner_id
		from partner_account pa
		inner join account a
			on a.account_id = pa.account_id
		where left(a.account_user_name,20) = @modified_by

		-- 2.1) CSI updates
		if @partner_id is null
			begin
			if (select count(*) from permission_group_membership m where m.permission_application_id = 1 and left(m.user_name,20) = @modified_by) > 0
				begin
				-- 2.1.1) CSI Online group use current partner
				if (select count(*)
					from permission_group_membership m
					inner join permission_group_resource gr
						on gr.permission_group_id = m.permission_group_id
					inner join permission_resource r
						on r.permission_resource_id = gr.permission_resource_id
					where m.permission_application_id = 1 and left(m.user_name,20) = @modified_by and gr.permission_group_id = 17 and r.permission_resource_id = 30) > 0
					begin
						select @partner_id = pl.partner_id
						from partner_license pl
						left join partner_configuration_partner pc
							on pl.partner_id = pc.partner_id and pc.partner_configuration_id = 4
						where pl.license_id = @license_id and pl.partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))
					end
				-- 2.1.2) CSI user but not in CSI Online group
				else
					begin
						select @partner_id = 5559 -- Webroot Direct Partner
					end
				end
			end

		if @partner_id is not null
			begin
			--select @partner_entity_approval

			select @partner_license_source_id = 3

			select @partner_entity_approval = isnull(pc.configuration_value,'Open')
												--case 
												--	when pc.configuration_value is null then 'Open'
												--	else pc.configuration_value
												--end
			from partner_configuration_partner pc
			where pc.partner_id = @partner_id and pc.partner_configuration_id = 4
			end
		
		-- 1.5.1) partner service
		if @modified_by = 'partner_service'
			begin
			select @partner_id = l.partner_id
			from partner_service_cancel c
			inner join partner_service_log l
				on c.partner_service_log_id = l.partner_service_log_id
			where keycode = @keycode
			
			select @partner_license_source_id = 2
			end
			
			if @partner_license_source_id is null
				begin
				select @partner_license_source_id = 1
				end

		-- 1.5) partner_license
			select @license_partner_id =  pl.partner_id,
					@license_entity_approval = case 
													when pc.configuration_value is null then 'Open'
													else pc.configuration_value
												end
			from partner_license pl
			left join partner_configuration_partner pc
				on pl.partner_id = pc.partner_id and pc.partner_configuration_id = 4
			where pl.license_id = @license_id and pl.partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))

			select @pending_license_partner_id =  pl.partner_id,
					@pending_entity_approval = case 
													when pc.configuration_value is null then 'Open'
													else pc.configuration_value
												end
			from partner_license pl
			left join partner_configuration_partner pc
				on pl.partner_id = pc.partner_id and pc.partner_configuration_id = 4
			where pl.license_id = @license_id and pl.partner_license_status_id = 1 and pl.partner_id <> @license_partner_id

			select @last_modified_user_id = @modified_by

			--select partner_id = @partner_id, partner_entity_approval = @partner_entity_approval, license_partner_id = @license_partner_id, license_entity_approval = @lice
nse_entity_approval, 
			--	pending_license_partner_id = @pending_license_partner_id, pending_entity_approval = @pending_entity_approval
			--return

			if (@license_entity_approval is not null or @pending_entity_approval is not null or @partner_entity_approval is not null) and @parent_warning is NULL
				begin
				-- 2.2.1) partner change
				if (@license_partner_id is not null and (@license_partner_id <> @partner_id or @partner_id is null) and @modified_by <> 'partner_license') 
					or
					(@pending_license_partner_id <> @partner_id)
					or 
				   (@partner_entity_approval = 'Required' and @license_partner_id is null)
					begin

					--print('2.2.1) partner change')
					--return

					if @partner_id is null 
						begin
						select @partner_id = 5559
						end

					-- 2.2.1) @order_item_update_type_id
					select @partner_license_status_id = 1

					-- 2.2.2) insert partner_license_transaction
					select @license_transaction = '{"procedure":"usp_license_update_license_capability_CSI","@days":"'+ convert(varchar(20),@days) + '","@keycode":"' + @keycode + '","@modified_by":"'+ @modified_by + '"}'
	
				
					-- 2.2.2) insert partner_license
					exec usp_partner_insert_partner_license @license_id,@partner_id,@partner_license_status_id,@partner_license_source_id,@last_modified_user_id,@comment,@order_header_id,@partner_license_id output

					-- select license_transaction = @license_transaction

					exec usp_partner_insert_partner_license_transaction @partner_license_id,@partner_license_status_id,@license_transaction
					return
					end

				end
			
					
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert product_capability_working
	
			exec usp_license_sub_insert_product_capability_working @license_id, @days, @modified_by, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

		-- 2.2) renew
		
			exec usp_license_sub_renew_license_capability @license_id, @keycode, 'CSI', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

		-- 2.3) Check for Enterprise and update Mobile Clients
			if @product_line_id  in (11,13)

			begin
				exec usp_license_update_child_license_capability @license_id,@response_code output, @message output

				if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end
			End

		-- 2.4) 
			if @license_type_id = 2
				begin
				exec usp_license_update_child_licenses @license_id, @order_item_id, @child_license_id
				end

		-- 2.5) extend sfdc trial
		if @salesforce_trial_id is not null
			begin
			-- 2.5.1) @capability_type_id
			select @capability_type_id = capability_type_id
			from license_capability c
			inner join license_category_license cl
				on c.license_id = cl.license_id
			inner join license_category lc
				on cl.license_category_id = lc.license_category_id
			where c.license_id = @license_id and c.capability_id = lc.base_capability_id

			if @capability_type_id = 1
				begin
				return
				end

			-- 2.5.2) @sfdc_template_id
			select @sfdc_template_id =  9
 
			-- 2.5.3) 
			select @sfdc_update_type_id = sfdc_update_type_id
			from sfdc_template_update_type
			where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
												from sfdc_template_
update_type
												where sfdc_template_id = @sfdc_template_id)

			-- 2.5.4) insert sfdc_opportunity_update				
			insert into sfdc_opportunity_update(trial_id, sfdc_template_id, sfdc_update_type_id, process_date)
			values(@trial_id, @sfdc_template_id, @sfdc_update_type_id, getdate())
			end
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert into license_extension
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			set @insert_license_extension = 0

			select @insert_license_extension = count(*)
			from license_extension
			where license_id = @license_id

			if @insert_license_extension = 0
				insert into license_extension (license_id)
				values(@license_id)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) cleverbridge subscription expiration date change
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 4.1) see if license last purchase came through CB and change subscription expiration date by putting in license queue for cron job to pick up
		exec usp_order_select_payment_merchant @license_id = @license_id, @merchant_id = @merchant_id output, @line_item = @line_item output, @payment_subscription_id = @payment_subscription_id output

		if @merchant_id = 'cleverbridge' and @line_item is not null and @payment_subscription_id is not null
		begin
			set @license_message_value_str = 'line_item=' + str(@line_item) + ',' + 'payment_subscription_id=' + str(@payment_subscription_id)
			exec usp_message_insert_license_message @license_id, 12, @process_date, @process_date, @process_date, @license_message_value_str, @license_message_id output, @return_result = 0
		end

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_expiration_date]
-- =============================================================================

create procedure dbo.[usp_license_update_license_capability_expiration_date]
(
	@license_id int,
	@capability_id int,
	@capability_expiration_date datetime
)
/*	
	DATE				AUTHOR			REMARKS
	2007-09-20			ybarkalov		Initial creation

	DESCRIPTION
	Update capability_expiration_date for license/capability.
	The sp created for as part of Webroot Desktop Firewall integration project
		for synchronizing expiration of WDF capability with SS capability
	
*/
as
set nocount on
begin try
	begin transaction;

	UPDATE license_capability   
		SET capability_expiration_date = @capability_expiration_date
		WHERE license_id = @license_id
			AND capability_id = @capability_id

	commit transaction;
end try
begin catch

      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		
		if @@trancount > 0
	      rollback transaction;

end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_load]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_capability_load]
(
	@product_id int,
	@keycode varchar(40),
	@order_type_group_id int,
	@order_item_id int,
	@effective_date datetime output,
	@license_id int output,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR	REMARKS
	2006-09-24	esmart		Initial creation
	2006-10-02	esmart		Add support for inactive licenses
	2006-10-20	esmart		Add better support for new products applied to keycoded trial
	2006-11-10	esmart		Correct problems with the setting of capability_type_id and days_remaining on SS
	2006-11-20	esmart		Added product lines for enterprise and SME to section 2. 	
	2006-12-08	esmart		DR - Add check on renewals that distribute a new keycode so they do not readd the days to the new keycode. 
	2006-12-26	esmart		Modify new product update to better support purchases from a keycoded trial. 
	2007-01-02	esmart		Correct problem that was causing Upgrades to be ignored.
	2007-01-05	esmart		Improve logic for handling of renewals
	2007-01-10	esmart		Added international license_distribution_method_id (88) for DR to renewal logic
	2007-01-18	esmart		Put trap in for Trial parent license_ids
	2007-04-20	esmart		Correct problem when new product is sold on activated license. Need to update all capabilities.
	2007-08-29	bjordan		Removed logic to check for renewals that have previously expired
	2007-10-08	ybarkalov	Added check allowing renewal of subset of capabilities
	2007-10-09	bjordan		Added try/catch
	2007-10-10	bjordan		changed renewal @new_product logic to be <> 0 rather than = 0
	2007-11-27	bjordan		Added logic to prevent purchases of renewals without a prior purchase resulting in double days
	2008-07-16	esmart		Add support for WISE
	2010-06-15	dsmelker	Added call to usp_license_update_child_license_capability for Enterprise Licenses
	2011-05-18	esmart		Fix new product update to use capability_ext
	2011-03-01	esmart		License category update for new product override
	2012-03-02	esmart		module product_type support
	2014-08-13	esmart		Add trial designation for WWSS
	2016-04-15	mrobbins	add customer locale call
	2016-04-21	cnovac		Added section 6 to process forecasting code for select keycodes
	2016-10-11	cnovac		Commented section 6 out since we no longer want sold events
	2016-11-21	esmart		Include addition site_ids to ignore in section 2.2

	DESCRIPTION
	update license capability
*/


AS
begin try
	set nocount on
	
	declare 	@product_type_id int,
				@product_line_id int,
				@system_user varchar(50),
				@capability_change_reason_id int,
				@non_licensed_product int,
				@license_status_id int,
				@customer_id int,
				@license_insert_date datetime,
				@license_distribution_method_id int,
				@new_product_check int,
				@new_days_used int,
				@transaction_date datetime, 	
				@capability_activation_date datetime,
				@modified_by varchar(20),
				@new_capability_count int,
				@product_storage_gb int,
				@storage_gb int,
				@site_id varchar(65),
				@license_category_id int,
				@capability_type_id int,
				@license_attribute_license_value int
		

	set @response_code = 0
	set @message = 'License updated successfully'
	set @system_user = system_user
	set @transaction_date = getdate()
	set @modified_by = suser_sname()
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1 ) Get product type and product_line
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) check to see if product is non-licensed and return
	select @non_licensed_product = count(*)
	from product wit
h (nolock)
	where product_id = @product_id and uses_keycode = 0

	if @non_licensed_product = 1
		begin
			set @response_code = 0
			set @message = 'No update needed'
			return
		end

	-- 1.1) get license_id for keycode
	select @license_id = license_id,
		@license_status_id = license_status_id,
		@license_distribution_method_id = license_distribution_method_id,
		@license_insert_date = insert_date
	from license with (nolock)
	where keycode = @keycode
		
	if @license_id is null
		begin
			set @response_code = -110
			set @message = 'No matching keycode @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
			RAISERROR (@message, 11, 0)
		end

	if @license_id in (1089,1090,1091)
		begin
			set @response_code = -111
			set @message = 'Update attempt on trial parent license @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
			RAISERROR (@message, 11, 0)
		end

	-- 1.2) get product_type_id
	select @product_type_id = product_type_id
	from product  with (nolock)
	where product_id = @product_id
	
	if @product_type_id is null
		begin
			set @response_code = -120
			set @message = 'No matching product or NULL product_type_id @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
			RAISERROR (@message, 11, 0)
		end
	
	-- 1.3) get product_type_id
	select @product_line_id = product_line_id
	from product_line_product with (nolock)
	where product_id = @product_id
	
	if @product_line_id is null
		begin
			set @response_code = -120
			set @message = 'No matching product line or NULL product_line_id @keycode - ' + isnull(ltrim(rtrim(@keycode)),'Null @keycode') + ''
			RAISERROR (@message, 11, 0)
		end

	-- 1.4) set @capability_change_reason_id
	set @capability_change_reason_id =
		case
			when @order_type_group_id not in (2,3,4) and @product_type_id = 1 then 1
			when @order_type_group_id not in (2,3,4) and @product_type_id = 2 then 2
			when @order_type_group_id not in (2,3,4) and @product_type_id in (3,4) then 3
			when @order_type_group_id in (2,3,4) and @product_type_id = 1 then 8
			when @order_type_group_id in (2,3,4) and @product_type_id = 2 then 9
			when @order_type_group_id in (2,3,4) and @product_type_id in (3,4)  then 10
		end
	
	-- 1.5) @site_id
		select @site_id = h.site_id
		from order_header h
		inner join order_item i
			on h.order_header_id = i.order_header_id
		where i.order_item_id = @order_item_id

		if @site_id is null begin select @site_id = '' end

	-- 1.6) customer locale update
		select @customer_id = customer_id from license where license_id = @license_id

		if @customer_id is not NULL
			begin 
				exec usp_customer_update_customer_locale @customer_id
			end

	-- 1.7) @license_category_id
		select @license_category_id = license_category_id
		from product_license_category
		where product_id = @product_id

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2 ) New Product -  Validate license capabilities
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @product_type_id = 1 and @order_type_group_id not in (2,3,4)
		begin

		--	print '2 ) New Product -  Validate license capabilities'
				
			declare @needs_update int,
					@trial int,	
					@storage_account int,
					@max_capability_activation_days int
			
			-- 2.1) needs update
			set @needs_update = (select count(*)
				from product_capability c  with (nolock)
				inner join license_capability l with (nolock)
					on c.capability_id = l.capability_id 
				where product_id = @product_id and l.license_id = @license_id and
					(c.capability_type_id <> l.capability_type_id or c.capability_activation_days <> l.capability_activation_days))
			
			-- 2.2) is trial?
			select @trial = (select count(*) 
							from license_capability c with (nolock)
							where c.license_id = @lic
ense_id and c.capability_id in (1,2,25) and c.capability_type_id in (2,3))
				
			-- 2.2.1) pull of trial to full to their own procedure
			if @trial > 0
				begin
				exec usp_license_sub_update_trial_to_full @product_id, @keycode, 'load', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output
				end
			else
				begin
					-- if license_capability don't match product_capability complete update		
					if @needs_update > 0 and @site_id not in ('SFDC','MSP','RESELLER','PARTNERSERVICE')
						begin
--						select needs_update = @needs_update

						-- 2.1 check to see if the current license has all capabilities

							select @new_capability_count = count(*)
							from product_capability with (nolock)
							where capability_id not in (select capability_id from license_capability where license_id = @license_id) and
								product_id = @product_id

							-- 2.1.1) insert new capabilities
							if @new_capability_count > 0
								begin
									insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by, modified_date, modified_by)
									select 	@license_id, 
										capability_id, 
										capability_type_id, 
										capability_activation_days = 0,
										insert_date = getdate(),
										insert_by = system_user,
										modified_date = getdate(),
										modified_by = system_user		
									from product_capability with (nolock)
									where product_id = @product_id and 
											capability_id not in (select capability_id from license_capability where license_id = @license_id)	
								end
								
								-- 2.1.2 add rows to history
								insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
								select 	l.license_capability_id, 
									l.license_id, 
									l.capability_id, 
									l.capability_type_id, 
									l.capability_activation_days, 
									l.capability_activation_date, 
									capability_expiration_date = 
										case 
											when l.capability_expiration_date is null then null
											when l.capability_expiration_date < @transaction_date then l.capability_expiration_date
											else dateadd(dd,-(datediff(dd,@transaction_date,l.capability_expiration_date)),l.capability_expiration_date)
										end, 
									l.insert_date, 
									l.insert_by, 
									l.modified_date, 
									l.modified_by, 
									capability_change_reason_id =
										case
											when @trial = 0 then @capability_change_reason_id
											else 14
										end, 
									@transaction_date, 
									@system_user, 
									days_used = 
										case 
											when @trial = 0 and @license_status_id = 0 then 0
											else l.capability_activation_days - isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
										end,  
									days_remaining = 
										case 
											when @trial = 0 and @license_status_id = 0 then isnull(l.capability_activation_days,0)
											when datediff(dd,@transaction_date,l.capability_expiration_date) < 0 then 0
											else  isnull(datediff(dd,@transaction_date,l.capability_expiration_date),0)
										end, 
									days_added =  
										case 
											when @trial = 0 and @license_status_id = 0 then c.capability_activation_days - l.capability_activation_days
											else isnull(c.capability_activation_days,0)
										end, 
									days_new = isnull(c.capability_activation_days,0),
									days_contiguous = isnull(c.capability_activation_days,0)
								from license_capability l with (nolock)
								left join product_capability c with (nolock)
									on c.capability_id =
 l.capability_id and c.product_id = @product_id
								where license_id = @license_id		
							
								-- 2.1.3 add audit records
								exec usp_license_insert_license_capability_audit @license_id
						
								-- 2.1.4 correct discrepancy 
								update license_capability
								set 	
--								select
									capability_type_id = case
															when c.capability_type_id is null then 4 
															else c.capability_type_id
														end, 
									capability_activation_days = c.capability_activation_days, 
									capability_activation_date = case 
																	when e.capability_ext_type_id is null then null 
																	when (@trial = 0 and @license_status_id = 0) or c.capability_type_id is null or c.capability_type_id = 4 then null
																	else @transaction_date
																end, 
									capability_expiration_date = case 
																	when e.capability_ext_type_id is null then null 
																	when (@trial = 0 and @license_status_id = 0) or c.capability_type_id is null or c.capability_type_id = 4 then null
																	else dateadd(dd,c.capability_activation_days,@transaction_date)
																end, 
									modified_date = @transaction_date, 
									modified_by = @system_user
								from  license_capability l with (nolock)
								left join product_capability c  with (nolock)
									on c.capability_id = l.capability_id and c.product_id = @product_id
								left join capability_ext e  with (nolock)
									on l.capability_id = e.capability_id and e.capability_ext_type_id = 1
								where license_id = @license_id

								-- 2.1.5 Check to see if license storage exist and is needed
								select @storage_gb = storage_gb
								from license_storage with (nolock)
								where license_id = @license_id

								select @product_storage_gb = storage_gb
								from product_storage with (nolock)
								where product_id = @product_id

								-- 2.1.5.1 if product storage exist and license_storage does not exist
								if @product_storage_gb is not null and @storage_gb is null
									begin
										exec usp_license_insert_license_storage @license_id,@product_storage_gb,@order_item_id,@response_code OUTPUT,@message OUTPUT
									end

								-- 2.1.5.2 if product storage exist and license_storage does exist 
								if @product_storage_gb is not null and @storage_gb is not null		
									begin
										exec usp_license_update_license_storage @license_id,@product_storage_gb,@capability_change_reason_id,@order_item_id,@response_code OUTPUT,@message OUTPUT
									end			
									
								-- 2.1.5.3) license_category update								
								if @license_category_id is not null
									begin
									exec usp_license_update_license_category @license_id, @license_category_id, @capability_change_reason_id, @modified_by, @order_item_id	
									end		

						end
					else
						begin
						set @response_code = 0
						set @message = 'License capability data verified correct'
						return
						end
					
					set @response_code = 0
					set @message = 'License capability update successful'
			end
		end 

	else if (@product_type_id = 2 or @product_type_id = 3 or @product_type_id = 4) and @product_line_id in (1,6,11,13) and @order_type_group_id not in (2,3,4)
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  3 )  SS+AV Renewal
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin

--			 3.0) Check to see if the license was created during the transaction
			if datediff(dd,@license_insert_date,@transaction_date) = 0 and @product_type_id = 2
				begin
				
				-- 3.0.1) Is this a WRTL license
				if @license_distribution_method_id <> 83 
					begin
					-- 3.0.2) check to see if there was a new product purchase 
on the license
						select @new_product_check = count(*)
						from order_item_license ol  with (nolock)
						inner join order_item i with (nolock)
							on ol.order_item_id = i.order_item_id
						inner join product p with (nolock)
							on i.product_id = p.product_id
						where ol.license_id = @license_id 
								and p.product_type_id = 1
	
						if @new_product_check = 0 --10/10/07 change, was = 0
							begin
							set @response_code = 0
							set @message = 'Renewal sold on new license. Do not apply renewal days.'
							return
							end
					end
				end

				-- 3.0.3) Check to see if this is a DIRI license, check activation_date, and if in the last day skip update
				if @license_distribution_method_id in (1,88) and @product_type_id = 2-- DIRI license
					begin
						select @new_days_used = 
								case
									when datediff(hh,capability_activation_date,@transaction_date) >= 24 then 1
									else 0
								end
						from license_capability with (nolock)
						where capability_id = 1 and license_id = @license_id

						select @new_product_check = count(*)
						from order_item_license ol  with (nolock)
						inner join order_item i with (nolock)
							on ol.order_item_id = i.order_item_id
						inner join product p with (nolock)
							on i.product_id = p.product_id
						where ol.license_id = @license_id and p.product_type_id = 1
			
						if @new_days_used = 0 and @new_product_check = 0
							begin
								set @response_code = 0
								set @message = 'DR Renewal sold on new license. Do not apply renewal days.'
								return
							end
					end

		exec usp_license_sub_renew_license_capability @product_id, @keycode, 'load', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end
		end

	else if (@product_type_id = 2 or @product_type_id = 3 or @product_type_id = 4) and @product_line_id not in (1,6) and @order_type_group_id not in (2,3,4)
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  4 )  Non-SS+AV Renewal
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin

		exec usp_license_sub_renew_license_capability @product_id, @keycode, 'load', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

		end
	else if @order_type_group_id in (2,3,4)
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  4 )  Refund
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin
			
			exec usp_license_sub_refund_license_capability @product_id, @keycode, 'refund', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

		end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  5) Check for Enterprise and update Mobile Clients
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		--if @product_line_id  in (11,13)
		--begin
		--	exec usp_license_update_child_license_capability @license_id,@response_code output, @message output

		--	if @response_code < 0 	
		--	beg
in
		--			RAISERROR (@message, 11, 0)
		--	end
		--end
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--  6) Check for Licenses which need to go through the forecasting logic
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	/*	select @capability_type_id = lc.capability_type_id,
			   @license_attribute_license_value = lal.license_attribute_license_value
		from dbo.license_capability lc
		left join dbo.license_attribute_license lal on lal.license_id = lc.license_id
		where lc.license_id = @license_id

		--@license_category_id = 220 (endpoint business keys only)
		--@capability_type_id = 1 (only full keycodes, not trial)
		--@site_id = 'SFDC' (only SFDC orders)
		--@license_attribute_license_value = 12 - (only licenses on utility billing)
		if @license_category_id = 220 and @capability_type_id = 1 and @site_id = 'SFDC' and @license_attribute_license_value = 12
		begin
			--insert the service broker transaction to run the forecast on this license now
			exec usp_forecast_insert_license_process_queue @license_id, 1
		end
	*/
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName


	
	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_QA]
-- =============================================================================


CREATE PROCEDURE usp_license_update_license_capability_QA

(
	@license_capability_id int, 
	@capability_type_id int, 
	@capability_activation_days int, 
	@capability_activation_date datetime, 
	@capability_expiration_date datetime
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-07-24	esmart		Initial creation
	2006-08-08	esmart		Put check for blank dates and set to NULL

	DESCRIPTION
	update license_capability
*/

	-- check for blanks
	if @capability_activation_date = ''
		begin 
			set @capability_activation_date = null
			set @capability_expiration_date = null
		end

	if @capability_activation_date <> ''  and @capability_activation_date is not null
		begin
			set @capability_expiration_date = dateadd(dd,@capability_activation_days,@capability_activation_date)
		end

	-- complete update
	update license_capability
	set capability_type_id = @capability_type_id, 
		capability_activation_days = @capability_activation_days, 
		capability_activation_date = @capability_activation_date, 
		capability_expiration_date = @capability_expiration_date
	where license_capability_id = @license_capability_id



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_type_CSI]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_update_license_capability_type_CSI]
(
	@keycode varchar(40),
	@capability_id_string varchar(20),
	@modified_by varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-10		esmart		Initial creation

	DESCRIPTION
	update license capability type through CSI 
*/

AS

	set nocount on

	declare @license_id int,
			@effective_date datetime,
			@order_item_id int,
			@license_category_id tinyint,
			@capability_change_reason_id int

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @license_id
			select 
				@license_id = license_id,
				@response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then '@license_id not valid' else '' end
			from license
			where keycode = @keycode
			group by license_id

			if @response_code < 0 	
				begin
					RAISERROR (@message, 11, 0)
				end

		-- 1.2) @days
			if len(@capability_id_string) = 0 	
				begin
					set @response_code = -120
					set @message = 'No capabilities selected'
					RAISERROR (@message, 11, 0)
				end

		-- 1.3) @modified_by
			if @modified_by is null
				begin 
				set @modified_by = suser_sname()
				end

begin try

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) remove previous records from product_capability_working

		delete from product_capability_working where product_id = @license_id

		-- 2.2) insert product_capability_working
		insert into product_capability_working (product_id, capability_id, capability_type_id, capability_activation_days, insert_date, insert_by)
		select	product_id = license_id, 
				capability_id, 
				capability_type_id =	
						case 
							when t.integer_value is not null then 4
							else c.capability_type_id
						end, 
				capability_activation_days =	
						case 
							when t.integer_value is not null and c.capability_activation_date is not null then datediff(dd,getdate(),c.capability_expiration_date)*-1
							when t.integer_value is not null and c.capability_activation_date is null then c.capability_activation_days*-1
							else 0
						end, 
				insert_date = getdate(), 
				insert_by = @modified_by
		from license_capability c
		left join dbo.fn_integer_string_to_table(@capability_id_string) t
			on c.capability_id = t.integer_value
		where license_id = @license_id
		order by capability_id


		-- 2.2) renew
			
			exec usp_license_sub_renew_license_capability @license_id, @keycode, 'CSI Type', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

			if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

		-- 2.3) update license_category
 
		select @license_category_id = dbo.fn_GetLicenseCategoryId(@license_id)

		if @license_category_id	<> (select license_category_id from license_category_license where license_id = @license_id)
			begin		
			select @capability_change_reason_id = 4

			exec usp_license_update_license_category @license_id, @license_category_id, @capability_change_reason_id, @modified_by, @order_item_id
			end	

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'capability_type_id update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_capability_upgrade]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_update_license_capability_upgrade]
(
	@keycode varchar(40),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-10		esmart		Initial creation
	2009-04-27		esmart		Add check for No Backup feature

	DESCRIPTION
	update license capability through upgrade 
*/

AS
set nocount on

	declare @effective_date datetime,
			@modified_by varchar(20),
			@license_id int,
			@product_id int,
			@keycode_type varchar(10),
			@order_item_id int,
			@license_feature int,
			@trial int

	select @modified_by = suser_sname(), @license_feature = 0

begin try
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) get type of keycode and correct product_id for upgrade
	
			select @keycode_type =
					case 
						when count(*) = 1 then 'SS'
						when count(*) = 2 then 'WAV'
						else 'NA'
					end,
					@license_id = l.license_id
			from license l
			inner join license_capability c
				on l.license_id = c.license_id
			where l.keycode = @keycode and c.capability_id in (1,2) and capability_type_id = 1
			group by l.license_id
			

			if @keycode_type = 'SS'
				begin
					--select @product_id = 67004
					return
				end
			
			if @keycode_type = 'WAV'
				begin
					select @product_id = 67005
				end

			if @keycode_type = 'NA'
				begin
					set @response_code = -110
					set @message = 'keycode not able to upgrade (' + @keycode + ')'
					RAISERROR (@message, 11, 0)
				end

		-- 1.2) check to see if the backup capability has already been added
		
			select @response_code =  case when count(*) > 0 then -120 else 0	 end,
					@message = case when count(*) > 0 then 'backup capability has already been added ' else '' end
			from license l
			inner join license_capability c
				on l.license_id = c.license_id
			where l.keycode = @keycode and c.capability_id = 11

			if @response_code < 0
				begin
					RAISERROR (@message, 11, 0)
					return
				end

		-- 1.3) check for the no backup feature
			
			select @license_feature = count(*)
			from license_feature_license f
			where f.license_id = @license_id and license_feature_id = 6

		-- 1.4) determine if license is a trial
		set @trial = (select count(*) 
			from license_capability c
			where license_id = @license_id and capability_id = 1 and capability_type_id in (2,3))

		if @trial > 0
			begin
			return
			end

--select keycode_type = @keycode_type, product_id = @product_id
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update license_capability
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 2.1) upgrade

			if @license_feature > 0
				begin
	
				insert into license_capability (license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_dat
e)
				values (@license_id, 11, 4, 0, null, null)

				end
			else 
				begin
				exec usp_license_sub_renew_license_capability @product_id, @keycode, 'upgrade', @modified_by, @order_item_id, @effective_date output, @license_id output, @response_code output, @message output

				if @response_code < 0 	
						begin
							RAISERROR (@message, 11, 0)
						end
				end
	
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'license_capability update failed @keycode = ' + isnull(@keycode,'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_category]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_update_license_category]

(
		@license_id int,
		@license_category_id tinyint,
		@license_change_reason_id int,
		@modified_by varchar(20),
		@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-08-04	esmart		Initial creation.
	2012-01-18	esmart		license_module_license

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@current_license_category_id int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@start_date datetime,
			@end_date datetime,
			@base_capability_id int,
			@days_used int,
			@transaction_date datetime

	select @response_code = 0,
			@transaction_date = getdate()
			
	if @modified_by is null or @modified_by = ''
		begin
		select @modified_by = suser_sname()
		end

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @base_capability_id
	select @base_capability_id = base_capability_id
	from license_category 
	where license_category_id = @license_category_id

	-- 1.2) select current capability dates
	select @capability_activation_date = capability_activation_date,
			@capability_expiration_date = capability_expiration_date
	from license_capability with (nolock)
	where license_id = @license_id and capability_id = @base_capability_id
	
	-- 1.3) check if license has license_category_license record
	select @current_license_category_id = license_category_id
	from license_category_license
	where license_id = @license_id

--	select current_license_category_id = @current_license_category_id,
--			capability_activation_date = @capability_activation_date,
--			capability_expiration_date = @capability_expiration_date
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @current_license_category_id is null
	-- 2.1) insert	
		begin
			insert into license_category_license(license_id, license_category_id, start_date, end_date)
			values(@license_id,@license_category_id,@capability_activation_date,@capability_expiration_date)	

		-- 2.1.1) Add row to license_category_license_history if the order_item_id is not null. This is needed for refund logic.
		if @order_item_id is not null
			begin
				insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, license_change_reason_id, last_modified_date, last_modified_by, history_date, history_by, order_item_id)
				select license_category_license_id, 
						license_id, 
						license_category_id, 
						start_date= null, 
						end_date = null, 
						license_change_reason_id = 3, 
						last_modified_date, last_modified_by, 
						history_date = @transaction_date, 
						history_by = @modified_by,
						order_item_id = @order_item_id
				from license_category_license with (nolock)
				where license_id = @license_id
			end	
		end
	else
	-- 2.2) update
		begin
			-- 2.2.1) get start, end, and days used
			select @start_date = start_date, @end_date = end_date, @days_used = datediff(dd,start_date,getdate())
			from license_category_lic
ense with (nolock)
			where license_id = @license_id
			
			-- 2.2.2) check date against capabilities
			if @capability_expiration_date <> @end_date or @end_date is null
				begin
					select @end_date = @capability_expiration_date
				end
			if @start_date is null
				begin
					select @start_date = dateadd(dd,@days_used,@capability_activation_date)
				end
			else
				begin
					select @start_date = @capability_activation_date
				end

--			select start_date = @start_date, end_date = @end_date, days_used = @days_used

			-- 2.2.3) upgrade or update
			insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, license_change_reason_id, last_modified_date, last_modified_by, history_date, history_by, order_item_id)
			select license_category_license_id, 
					license_id, 
					license_category_id, 
					start_date, 
					end_date = dateadd(dd,isnull(@days_used,0),start_date), 
					license_change_reason_id = @license_change_reason_id, 
					last_modified_date, last_modified_by, 
					history_date = @transaction_date, 
					history_by = @modified_by,
					order_item_id = @order_item_id
			from license_category_license with (nolock)
			where license_id = @license_id

			update license_category_license
			set license_category_id = @license_category_id,
				start_date = @start_date,
				end_date = @end_date,
				last_modified_date = @transaction_date, 
				last_modified_by = @modified_by
			from license_category_license with (nolock)
			where license_id = @license_id	
		end

	-- 2.3) check license_module_license to see if upgrade changes independent modules
		declare @license_modules table (license_module_license_id int, 
										license_id int, 
										license_module_id tinyint, 
										license_module_type_id tinyint, 
										start_date datetime, 
										end_date datetime)

		insert into @license_modules(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date)
		select lml.license_module_license_id, lml.license_id, lml.license_module_id, lml.license_module_type_id, lml.start_date, lml.end_date
		from license_category_license cl with (nolock)
		inner join license_category_module m with (nolock)
			on cl.license_category_id = m.license_category_id
		inner join license_module_license lml with (nolock)
			on m.license_module_id = lml.license_module_id and cl.license_id = lml.license_id
		where cl.license_id = @license_id

		if (select count(*) from @license_modules) > 0 
			begin
			insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date)
			select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
					m.start_date, 
					end_date = dateadd(dd,(datediff(dd,start_date,getdate())),m.start_date),
					m.last_modified_date, m.last_modified_by, @order_item_id, @license_change_reason_id, @transaction_date
			from license_module_license m with (nolock)
			where license_module_license_id in (select license_module_license_id from @license_modules)
			order by license_module_license_id

			delete from license_module_license
			where license_module_license_id in (select license_module_license_id from @license_modules)
			end

	select response_code = @response_code, [message] = @message 

	end try

	begin catch

		set @response_code = -200
		set @message = case 
							when @message is null then 'update license category failed'
							else @message 
						end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_category_endpoint]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_category_endpoint]

(
		@license_id int,
		@csi_user_id varchar(50)
			
)


/*	
	DATE		AUTHOR		REMARKS
	2018-10-05	acoffel		Initial creation
	2019-11-04	esmart		Change to use license_service
	2019-11-18	abelenkiy	Removed unused variables
							Added insert to license_category_license_history
							Added error handling and return out when non-qualifying license is passed in
							Rearranged steps to only perform update after all checks are completed

	DESCRIPTION
	update license_category from 250 to 220
*/

AS
	set nocount on

	begin try

	declare @service_json nvarchar(max)
	declare @license_table table (license_id int, license_category_name varchar(10), expiration_date date, category_type_name varchar(50), keycode varchar(50))

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) setup and error handling
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.1) raise error if license is out of 250/220 scope
	if (select 1 
		from license_category_license lcl
		inner join license_parent lp on lp.child_license_id = lcl.license_id
		inner join license_category_license lcl2 on lp.parent_license_id = lcl2.license_id
		where lcl.license_id = @license_id
		and lcl.license_category_id = 250
		and lcl2.license_category_id = 220) is null

		begin
			raiserror ('Incorrect category on child and/or parent.',16,1)
			return
		end
	
	-- 1.2) populate table variable with information to be used in service_json creation; use expiration date from parent if parent exists and no expiration exists on child 
	insert into @license_table (license_id, license_category_name, expiration_date, category_type_name, keycode)
	select p.license_id, 'SAEP', isnull(p.expiration_date, lcl.end_date), p.category_type_name, p.keycode
	from fn_license_select_license_profile(@license_id) p
	inner join license_parent lp on lp.child_license_id = p.license_id
	inner join license_category_license lcl on lcl.license_id = lp.parent_license_id
											and lcl.license_category_id = 220
 	where p.license_category_name = 'SAUP'

	-- 1.3) create and set json to be passed into usp_license_service_insert_service
	select @service_json = (select lt.keycode, @csi_user_id as account_name,
									(select l.license_category_name, l.expiration_date, l.category_type_name from @license_table l for json path) license_category
							from @license_table lt for json path, without_array_wrapper)

	-- 1.4) raise error if json is null
	if @service_json is null
		begin
			raiserror ('Service_json is null.',16,1)
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update tables and execute usp_license_service_insert_service
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert to license_category_license_history
	insert into license_category_license_history (license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_by)
	select lcl.license_category_license_id, lcl.license_id, lcl.license_category_id, lcl.start_da
te, lcl.end_date, lcl.last_modified_date, lcl.last_modified_by, 27, @csi_user_id -- license_change_reason_id 27 = category audit
	from  license_category_license lcl
	where lcl.license_id = @license_id

	-- 2.2) update license_category_license
	update license_category_license
	set license_category_id = 220, last_modified_date = getdate(), last_modified_by = @csi_user_id
	from license_category_license cl
	where cl.license_id = @license_id

	-- 2.3) correct effective_object
	update leo
	set leo.effective_end_date = iif(lt.expiration_date < getdate() and leo.effective_start_date <= dateadd(dd,-1,lt.expiration_date), dateadd(dd,-1,lt.expiration_date), getdate()-1)
	from license_effective_object leo
	inner join @license_table lt on lt.license_id = leo.license_id
	where leo.is_dup = 0 and leo.license_category_id = 250 and leo.effective_end_date is null

	-- 2.4) insert license_service
	exec usp_license_service_insert_service @license_service_type_name = 'license_update', @service_json = @service_json, @return_license_service_id = 0

	end try

	begin catch

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_churn]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_update_license_churn]

( 
       @batch_size int 
)

/*     
       DATE          AUTHOR        REMARKS
       2016-09-27    acoffel       Initial creation.
	   2019-04-25	 acoffel	   fix variables			

       DESCRIPTION
       update churn licenses
*/

AS
       set nocount on                           


       begin try

       declare @capability_activation_days int,
                     @capability_activation_date datetime,    
                     @capability_expiration_date datetime,
                     @base_capability_id int,
                     @capability_type_id int,
                     @license_status_id int,
                     @license_change_reason_id int,
                     @order_item_id int,
                     @transaction_date datetime,
                     @product_type_id int,
                     @max_process_date datetime,
                     @modified_by varchar(20),
                     @response_code int,
                     @message varchar(100)

       select @license_change_reason_id = 4,
                     @transaction_date = getdate(),
                     @modified_by = 'license_churn'
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) get churn licenses from license_churn 
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       declare @license_churn table (license_id int not null, capability_expiration_date datetime not null, churn_days_add int, churn_days_measure int)      

       --1.0) get @top churn licenses
       insert into @license_churn (license_id, capability_expiration_date, churn_days_add, churn_days_measure)
       select top (@batch_size) lc.license_id, dateadd(dd,lc.churn_days_add,c.capability_expiration_date), lc.churn_days_add, lc.churn_days_measure
       from license_churn lc
       inner join license_capability c
              on lc.license_id = c.license_id and c.capability_id = 2

       --1.1) fix licenses still below thresholds
       update @license_churn set capability_expiration_date = getdate()+365 where capability_expiration_date < getdate()

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 2.) process
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       declare @license_capability_churn table (license_capability_id int, license_id int, capability_id int, capability_type_id int, capability_activation_days int, capability_activation_date datetime, capability_expiration_date datetime,
                     insert_date datetime, insert_by varchar(50), modified_date datetime, modified_by varchar(50), days_used int, days_remaining int, days_added int, days_new int, days_contiguous int, new_expiration_date datetime)
       
       --2.0) insert licenses into @license_capability_churn
       insert into @license_capability_churn (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, new_expiration_date)
       select lc.license_capability_id, lc.lice
nse_id, lc.capability_id, lc.capability_type_id, lc.capability_activation_days, lc.capability_activation_date, lc.capability_expiration_date, lc.insert_date, lc.insert_by, lc.modified_date, lc.modified_by, c.capability_expiration_date
       from @license_churn c 
       inner join license_capability lc with (nolock)
              on c.license_id = lc.license_id
       where lc.capability_activation_date is not null

	   	select @license_status_id = l.license_status_id, 
			@capability_activation_days = c.capability_activation_days,
			@capability_activation_date = c.capability_activation_date, 
			@capability_expiration_date = c.capability_expiration_date,
			@capability_type_id = c.capability_type_id
		FROM @license_churn ch
		INNER JOIN license l
			ON ch.license_id = l.license_id
		INNER join license_category_license cl
			ON l.license_id = cl.license_id
		INNER join license_category lc
			ON cl.license_category_id = lc.license_category_id
		INNER join license_capability c
			ON l.license_id = c.license_id and c.capability_id = lc.base_capability_id

       -- 2.1) update day_used columns
       update @license_capability_churn
       set days_used =  
       case 
              when capability_expiration_date <= getdate() then capability_activation_days
       else datediff(dd, capability_activation_date, getdate())
       end

       -- 2.2) update days_remaining columns
       update @license_capability_churn
       set days_remaining = 
       case
              when capability_expiration_date <= getdate() then 0
       else datediff(dd, getdate(), capability_expiration_date)
       end

       -- 2.3) update days_added columns
       update @license_capability_churn
       set days_added  = datediff(dd, getdate(), new_expiration_date) - days_remaining

       -- 2.4) update days_new
       update @license_capability_churn
       set days_new =
       case
              when days_added <= 0 then 0
       else days_added
       end

       -- 2.5) update days_contiguous
       update @license_capability_churn
       set days_contiguous = days_remaining + days_added


       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 3.) update
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       --3.0) insert capability history         
       insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
       select license_capability_id, license_id, capability_id, capability_type_id,
       capability_activation_days = isnull(days_used,0),
       capability_activation_date,
       capability_expiration_date = getdate(),
       insert_date, insert_by, modified_date, modified_by, capability_change_reason_id = @license_change_reason_id, history_date = @transaction_date, history_by = @modified_by,
       days_used = isnull(days_used,0),
       days_remaining = isnull(days_remaining,0),
       days_added = isnull(days_added,0),
       days_new = isnull(days_new,0),
       days_contiguous = isnull(days_contiguous,0)
       from @license_capability_churn
       order by license_id, capability_id


       -- 3.1) update license_capability 
       update license_capability
       set capability_activation_days = datediff(dd, getdate(), t.new_expiration_date),
              capability_activation_date = getdate(),
              capability_ex
piration_date = t.new_expiration_date,
              modified_date = @transaction_date,
              modified_by = @modified_by
       from license_capability c
       inner join @license_capability_churn t
              on c.license_capability_id = t.license_capability_id

		-- 3.1.3) new dates
		select @capability_activation_date = c.capability_activation_date, @capability_expiration_date = c.capability_expiration_date
		from license_capability c
		inner join @license_capability_churn t
			on c.license_capability_id = t.license_capability_id
		inner join license_category_license cl
			on c.license_id = cl.license_id
		inner join license_category lc
			on cl.license_category_id = lc.license_category_id
		where c.capability_id = lc.base_capability_id

       -- 3.2) insert history
       insert into license_seat_history(license_seat_id, license_id, license_seats, seats_used, start_date, end_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by, order_item_id)
       select s.license_seat_id, s.license_id, s.license_seats, s.seats_used,  
                           s.start_date, 
                           end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
                           s.insert_date, s.insert_by, s.modified_date, s.modified_by, 
                           license_change_reason_id = @license_change_reason_id, history_date = @transaction_date, history_by = @modified_by, order_item_id = @order_item_id
              from license_seat s
              inner join @license_capability_churn t
                     on s.license_id = t.license_id

       -- 3.3) update
       update license_seat
       set start_date = @capability_activation_date,
                     end_date = @capability_expiration_date,
                     modified_date = @transaction_date,
                     modified_by = @modified_by
       from license_seat s
       inner join @license_capability_churn t
              on s.license_id = t.license_id

       -- 3.4) insert history
       insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date, history_by, order_item_id)
       select c.license_category_license_id, c.license_id, c.license_category_id, 
              c.start_date, 
              end_date = dateadd(dd,isnull(days_used,0),t.capability_activation_date), 
              c.last_modified_date, c.last_modified_by, 
              license_change_reason_id = @license_change_reason_id, history_date = @transaction_date, history_by = @modified_by, order_item_id = @order_item_id
       from license_category_license c
       inner join @license_capability_churn t
              on c.license_id = t.license_id


       -- 3.5) update
       update license_category_license
       set    start_date = @capability_activation_date,
              end_date = @capability_expiration_date,
              last_modified_date = @transaction_date,
              last_modified_by = @modified_by
       from license_category_license s
       inner join @license_capability_churn t
              on s.license_id = t.license_id
                     
		-- 3.6) insert history
		insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date, module_seats, license_status_id)
		select ml.license_module_license_id, ml.license_id, ml.license_module_id, ml.license_module_type_id, 
				ml.start_date,
				end_date = dateadd(dd,datediff(dd,ml.start_date,getdate()),ml.start_date), 
				ml.last_modified_date, ml.last_modified_by, order_item_id = NULL, license_change_reason_id = @license_change_reason_id, 
				history_date = @tr
ansaction_date, 
				ml.module_seats,
				ml.license_status_id
		from license_module_license ml
		inner join license_module m
			on m.license_module_id = ml.license_module_id
		inner join license_module_type t
			on t.license_module_type_id = ml.license_module_type_id
		inner join @license_capability_churn u
			on u.license_id = ml.license_id
		WHERE ml.license_status_id = 1


		-- 3.7) update
		update license_module_license
		set start_date = @capability_activation_date,
			end_date = @capability_expiration_date,
			last_modified_date = @transaction_date,
			last_modified_by = @modified_by
		from license_module_license ml
		inner join license_module m
			on m.license_module_id = ml.license_module_id
		inner join license_module_type t
			on t.license_module_type_id = ml.license_module_type_id
		inner join @license_capability_churn u
			on u.license_id = ml.license_id
		WHERE ml.license_status_id = 1

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 4.) prevx update management
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       --4.0) check to see if there are any waiting in prevx_update table
       select @max_process_date = max(p.process_date)
       from prevx_update p
       where prevx_update_type_id = 2 and response_text is NULL

       --4.1) load prevx queue
       insert into dbo.sky_update (license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, process_date)
       SELECT distinct n.license_id, 4, 4, 0, GETDATE(), 0, GETDATE() 
       from @license_churn n
	   INNER JOIN dbo.sky_api_license s
			ON n.license_id = s.license_id

		--4.2) load prevx queue
		insert into prevx_update (license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date)
		SELECT distinct n.license_id, NULL as license_bulk_load_id, 2 as prevx_update_type_id, 0 as prevx_update_status_id, NULL response_id, NULL as response_text, 0 as update_attempts, getdate() as insert_date, getdate() as modified_date, CASE WHEN @max_process_date IS NOT NULL then DATEADD(MINUTE,2,@max_process_date)  ELSE GETDATE() END AS process_date
		from @license_churn n
		left JOIN dbo.sky_api_license s
			ON n.license_id = s.license_id
		WHERE s.license_id IS NULL

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 4.) archive license churn records
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       insert into license_churn_archive (license_id, churn_days_add, churn_days_measure, insert_date, insert_by)
       select license_id, churn_days_add, churn_days_measure, insert_date, @modified_by
       from license_churn
       where license_id in (select license_id from @license_churn)

       delete from license_churn where license_id in (select license_id from @license_churn)

       end try

       begin catch   

              set @response_code = -200
              set @message = case when @message is null then 'license update failed'
                                                else @message end

              declare @DBName nvarchar(128)
              set @DBName = db_name()
              exec usp_LogError @ErrorDB = @DBName
              
       end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_customer]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_license_update_license_customer]

(	
	@customer_email varchar(100) = NULL,
	@license_id int = NULL, 
	@customer_id int = NULL,
	@csi_user varchar(50)
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2016-05-16	acoffel		Initial creation

	DESCRIPTION
	update license 
*/

		set nocount on
			
		declare @modified_date datetime,
			@license_change_reason_id int,
			@current_license_status_id int,
			@last_license_status_id int,
			@customer_id_check int,
			@response_code int,
			@message varchar(100)
		
		begin try

		set @modified_date = getdate()
		set @license_change_reason_id = 7 -- customer service

		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) check customer_id
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		
		-- 1.1) check to see if customer  
		if @customer_id is not NULL
			begin
				select @response_code =  case when count(*) = 0 then -110 else 0	end,
					@message = case when count(*) = 0 then '@customer_id not valid' else '' end
				from customer
				where customer_id = @customer_id

				if @response_code < 0 	
				begin 
					return 
				end	
			end


		select @customer_id_check = customer_id from license where license_id = @license_id
		-- 1.2) check to see if customer_is is already registered to the license
		if @customer_id is not NULL and @customer_id = @customer_id_check
			begin
				select @response_code =  case when count(*) = 0 then -110 else 0	end,
					@message = case when count(*) = 0 then '@customer_id is already registered to this license' else '' end

				if @response_code < 0 	
				begin 
					return 
				end	
			end
			
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check license is eligible for the update and what it's partner info might be
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 2.0) check license status
		select @current_license_status_id = license_status_id
		from license
		where license_id = @license_id
	
		if @current_license_status_id in (2,3)
			begin
				select  @response_code = -110,
						@message = '@license_status_id not valid'
				return
			end



	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update licesne
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @customer_id is not NULL 
		-- 3.0) add existing data to license_history
		insert into license_history (license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_chil
d_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by)
		select license_id, keycode, customer_id, product_line_id, license_status_id, license_type_id, license_distribution_method_id, license_keycode_type_id, max_daily_activations, max_child_licenses, license_expiration_date, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @modified_date, @csi_user
		from license
		where license_id = @license_id

		-- 3.1) update license with new customer
		update license
		set customer_id = @customer_id,
			modified_date = @modified_date,
			modified_by = @csi_user
		where license_id = @license_id


		end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_distribution_method]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_license_update_license_distribution_method]

(
	@license_distribution_method_id INT,
	@license_distribution_method_code  char(4), 
	@license_distribution_method_name varchar(50),
	@channel_id int,
	@license_distribution_method_active tinyint = 1,
	@distribution_business_unit_id tinyint = NULL,
	@distribution_geography_id tinyint = NULL,
	@distribution_class_id tinyint = NULL,
	@distribution_account_id tinyint = NULL,
	@best_buy_s2 tinyint = null,
	@auto_extend TINYINT,
	@churn_days_add INT ,
    @churn_days_measure INT ,
    @do_not_send_email TINYINT = NULL,
	@seat_count_enforcement TINYINT = NULL,
	@response_code INT OUTPUT,
	@message VARCHAR(100) OUTPUT,
	@insert_by VARCHAR(20) = NULL
)

AS
	

/*	
		DATE			AUTHOR		REMARKS
		2006-12-15		esmart		Initial creation.	
		2010-07-06		dsmelker	Added license_distribution_method_active
		2012-11-09		esmart		Add new columns
		2025-06-02      spatil6     Add new fields do_not_send_email and auto_extend logic 
		2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968
        2026-03-23   spatil6    Add seat_count_enforcement new field US-5117515
		2026-07-22		pachanta	D-5600814 Providing the hotfix for updating the license_distribution_method_code

		DESCRIPTION
		Update license distribution method and channel
*/


	SET NOCOUNT ON

	DECLARE @current_license_distribution_method_code CHAR(4),
			@transaction_date DATETIME,
			@system_user VARCHAR(50)

	SET @transaction_date = GETDATE()
	SET @system_user = SYSTEM_USER
	SET @response_code = 0
	SET @message = 'Successfully inserted license distribution method'
	SET @seat_count_enforcement = ISNULL(@seat_count_enforcement, 0)

	IF @insert_by IS NULL
    BEGIN
        SELECT @insert_by = SUSER_SNAME()
    END
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) Validate inputs
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) Check distribution method code to see if it already exists
	SELECT @response_code =  CASE WHEN COUNT(*) = 1 THEN -100 ELSE 0	 END,
		@message = CASE WHEN COUNT(*) = 1 THEN 'License distribution method code already exists' END
	FROM license_distribution_method 
	WHERE license_distribution_method_code = @license_distribution_method_code AND license_distribution_method_id <> @license_distribution_method_id

	IF @response_code < 0 	
		BEGIN 
			RETURN 
		END	
	
	-- 1.1) Check channel_id
	SELECT @response_code =  CASE WHEN COUNT(*) = 0 THEN -110 ELSE 0	 END,
		@message = CASE WHEN COUNT(*) = 0 THEN 'Channel_id is not valid' END
	FROM channel 
	WHERE channel_id = @channel_id

	IF @response_code < 0 	
		BEGIN 
			RETURN 
		END	

	-- 1.2) check license_distribution_method_id

	SELECT @response_code =  CASE WHEN COUNT(*) = 0 THEN -120 ELSE 0	 END,
		@message = CASE WHEN COUNT(*) = 0 THEN 'license_distribution_method_id is not valid' END
	FROM license_distribution_method 
	WHERE license_distribution_method_id = @license_distribution_method_id

	IF @response_code < 0 	
		BEGIN 
			RETURN 
		END	

	-- 1.3) @current_license_distribution_method_code
	SELECT @current_license_distribution_method_code = license_distribution_method_code
	FROM license_distribution_method
	WHERE license_dist
ribution_method_id = @license_distribution_method_id

	IF @current_license_distribution_method_code <> @license_distribution_method_code
		BEGIN



		IF (SELECT COUNT(*) FROM license WITH (NOLOCK) WHERE license_distribution_method_id = @license_distribution_method_id) > 0
			BEGIN
			SELECT @response_code =  -130, @message = 'License exist for current code, no change to code allowed'
			RETURN
			END
		END

	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) Insert license_distribution_method 
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	UPDATE license_distribution_method
	SET license_distribution_method_code = @license_distribution_method_code,
		license_distribution_method_name = @license_distribution_method_name,
		modified_date = @transaction_date,
		modified_by = @system_user,
		license_distribution_method_active = @license_distribution_method_active
	WHERE license_distribution_method_id = @license_distribution_method_id

	IF @@error <> 0 
		BEGIN
			SET @response_code = -200
			SET @message = 'General SQL error - update license_distribution_method'
			
		RETURN
		END
		
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) Insert license_distribution_method_channel
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	UPDATE license_distribution_method_channel
	SET channel_id = @channel_id,
		distribution_business_unit_id = @distribution_business_unit_id,
		distribution_geography_id = @distribution_geography_id,
		distribution_class_id = @distribution_class_id,
		distribution_account_id = @distribution_account_id,
		modified_date = @transaction_date,
		modified_by = @system_user
	WHERE license_distribution_method_id = @license_distribution_method_id
	
	IF @@error <> 0 
		BEGIN
			SET @response_code = -300
			SET @message = 'General SQL error - update license_distribution_method_channel'
			
		RETURN
		END
		
	
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4) subscription
	-- -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
            
	IF @best_buy_s2 = 1
		BEGIN
		DELETE FROM subscription_distribution_method WHERE license_distribution_method_id = @license_distribution_method_id

		INSERT INTO subscription_distribution_method(license_distribution_method_id)
		VALUES(@license_distribution_method_id)
		END
        
			------if auto extend checked
	IF @auto_extend = 1
	
		BEGIN
		DELETE FROM license_distribution_method_churn WHERE license_distribution_method_id = @license_distribution_method_id

		
		INSERT INTO dbo.license_distribution_method_churn
		(
		    license_distribution_method_id,
		    churn_days_add,
		    churn_days_measure,
		    insert_date,
		    insert_by
		)
		VALUES
		(@license_distribution_method_id, @churn_days_add, @churn_days_measure, GETDATE(), DEFAULT);
	
		END;
	ELSE
	BEGIN
        DELETE FROM license_distribution_method_churn WHERE license_distribution_method_id = @license_distribution_metho
d_id
    END ;
	
		------if Do not send Email checekd--------------------
		IF @do_not_send_email = 1
			BEGIN

			DELETE from message_campaign_license_distribution_method where license_distribution_method_id = @license_distribution_method_id
	

			INSERT INTO dbo.message_campaign_license_distribution_method
			(
				message_campaign_id,
				license_distribution_method_id,
				inclusive,
				insert_by, 
				modified_by
			)
			SELECT DISTINCT
				   mc.message_campaign_id,
				   @license_distribution_method_id,
				   0,
				   @insert_by, 
				   @insert_by
			FROM dbo.message_campaign mc
				INNER JOIN dbo.message_campaign_license_distribution_method mcldm
					ON mcldm.message_campaign_id = mc.message_campaign_id
			WHERE mcldm.inclusive = 0
				  AND mc.message_campaign_class_id = 4
				  AND mcldm.license_distribution_method_id <> @license_distribution_method_id;

	
		END;
	ELSE
		BEGIN
			DELETE from message_campaign_license_distribution_method where license_distribution_method_id = @license_distribution_method_id
		END
		------------------ Adding Product, license_category and license_distribution_code -----------------------------
		IF EXISTS (
			SELECT 1
			FROM product_line_license_seat_distribution
			WHERE product_line_id = 100
			AND license_distribution_method_id = @license_distribution_method_id
			AND license_category_id = 100
		)
		BEGIN
			UPDATE product_line_license_seat_distribution
			SET seat_count_enforcement = @seat_count_enforcement
			WHERE product_line_id = 100
			AND license_distribution_method_id = @license_distribution_method_id
			AND license_category_id = 100
		END
		ELSE
		BEGIN
		INSERT INTO product_line_license_seat_distribution
		(
			product_line_id,
			license_distribution_method_id,
			license_category_id,
			seat_count_enforcement
		)
		VALUES
		(
			100,
			@license_distribution_method_id,
			100,
			@seat_count_enforcement
		)
     END


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_distribution_method_language_location]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_license_update_license_distribution_method_language_location]

(
	@license_distribution_method_id int, 
	@language_code varchar(2) = null, 
	@location_code varchar(3) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-09-04	esmart		Initial creation.

	DESCRIPTION
	update license_distribution_method_language_location
*/

AS
	set nocount on				

	declare	@license_distribution_method_language_location_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @order_opportunity_id
	select @license_distribution_method_language_location_id = license_distribution_method_language_location_id 
	from license_distribution_method_language_location 
	where license_distribution_method_id = @license_distribution_method_id


	if @license_distribution_method_language_location_id is null
		begin
		insert into license_distribution_method_language_location(license_distribution_method_id, language_code, location_code) 
		values(@license_distribution_method_id, @language_code, @location_code)
		end
	else if @license_distribution_method_language_location_id is not null and @language_code = '' or @language_code is null
		begin
		delete 
		from license_distribution_method_language_location 
		where license_distribution_method_language_location_id = @license_distribution_method_language_location_id
		end
	else if @license_distribution_method_language_location_id is not null and @language_code <> '' or @language_code is not null
		begin
		delete 
		from license_distribution_method_language_location 
		where license_distribution_method_language_location_id = @license_distribution_method_language_location_id
		
		insert into license_distribution_method_language_location(license_distribution_method_id, language_code, location_code) 
		values(@license_distribution_method_id, @language_code, @location_code)
		end
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_module]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_module]

(
	@license_module_id int,
	@license_module_code varchar(50), 
	@license_module_name varchar(50), 
	@license_module_class_id tinyint,
	@license_module_status varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2014-12-30	esmart		Initial creation.

	DESCRIPTION
	Update license module
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) verify unique code
	if (select count(*) from license_module where license_module_code = @license_module_code and @license_module_id <> license_module_id) > 0
		begin
		select @response_code = -110, @message = 'Duplicate code'
		select response_code = @response_code, message = @message
		return
		end
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	update license_module
	set license_module_code = @license_module_code, 
		license_module_name = @license_module_name, 
		license_module_class_id = @license_module_class_id,
		license_module_status = @license_module_status
	where license_module_id = @license_module_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_module_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_module_license]

(
		@license_id int,
		@product_id int = null,
		@license_change_reason_id int = null,
		@order_item_id int = null,
		@module_seats int = null,
		@license_module_id int = null,
		@module_end_date datetime = null,
		@modified_by varchar(20) = null,
		@license_service_id int = null
)



/*	
	DATE		AUTHOR		REMARKS
	2012-01-10	esmart		Initial creation
	2014-01-08	esmart		Add support for changes in license_module_type
	2015-01-30	esmart		module_seats
	2016-11-18	esmart		product_license_module.days support for trials
	2017-02-14	esmart		support for module_seat upgrades
	2017-04-25	esmart		sky dns_registration
	2017-04-26	esmart		fix logic for new end_date on update
	2017-05-16	esmart		Fix defects
	2019-01-09	rvinoche	Support autobilling attributes living only in license_effective_object
	2019-09-16	cnovac		Updated code to support writing to license_contract when called by license service ('update_license_module')
	2020-04-22	cnovac		Added logic to pass in license_status_id into license contract
	2021-12-09	psatish		Added Perpetual billing model to update the end date
	DESCRIPTION
	insert/update license_module_license
*/

AS
	set nocount on				

	declare	@license_module_license_id int,
			@current_license_module_type_id tinyint,
			@current_license_module_type_name varchar(50),
			@current_module_seats int,
			@current_start_date datetime,
			@current_end_date datetime,
			@license_module_type_id tinyint,
			@license_module_type_name varchar(50),
			@license_category_start_date datetime,
			@license_category_end_date datetime,
			@capabilty_type_id int,
			@capability_type_description varchar(20),
			@days int,
			@last_modified_date datetime,
			@order_item_start_date datetime,
			@order_item_end_date datetime,
			@product_line_id int,
			@sky_template_id tinyint, 
			@process_date datetime,
			@parent_license_id int,
			@license_type_id int,
			@child_license_id int,
			@autobilling_attribute int,
			@response_code int,
			@message varchar(100),
			@license_contract_json varchar(max)
	declare @license_contract_object table (license_id int, license_category_id tinyint, license_status_id tinyint, license_category_type_id int, license_start_date date, license_end_date date, license_service_id int)


	begin try

	select @last_modified_date = getdate()
	if @modified_by is null
		begin
		select @modified_by = suser_sname()
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) license_category_license @license_category_start_date and @license_category_end_date
	select @license_category_start_date = start_date, @license_category_end_date = end_date, @capabilty_type_id = t.capability_type_id, @capability_type_description = t.capability_type_description,
		@license_type_id = l.license_type_id
	from license_category_license cl
	inner join license l
		on l.license_id = cl.license_id
	inner join license_category c
		on c.license_category_id = cl.license_category_id
	inner join license_capability lc
		on lc.license_id = cl.license_id and lc.capability_id = c.base_capability_id
	inner join capability_type t
		on t.capability_type_id = lc.capability_type_id
 	where cl.license_id = @license_id 

	select @autobilling_attribute = f.effective_value
	from dbo.fn_license_select_effective_object_t
able(@license_id, @last_modified_date) f
	inner join dbo.license_attribute_license_value v
		on f.effective_value = v.license_attribute_license_value
	where (v.license_attribute_license_value_description like '%utility%'
		--and f.license_category_id = 220 --endpoint only for now
		or v.license_attribute_license_value_description like '%perpetual%')
		and f.effective_object_id = 2 --autobilling attribute
		
	-- 1.2) @order_item_start_date and @order_item_end_date
	select @order_item_start_date = effective_date, 
		   @order_item_end_date = case when @autobilling_attribute is not null then @license_category_end_date else capability_expiration_date end
	from order_item 
	where order_item_id = @order_item_id

	-- 1.3) product data
	if @product_id is not null
		begin
			-- 1.3.1) @product_line_id
			select @product_line_id = product_line_id
			from product_line_product
			where product_id = @product_id

			-- 1.3.1) product_license_module
			select @license_module_id = p.license_module_id, @license_module_type_id = p.license_module_type_id, @license_module_type_name = t.license_module_type_name, @days = p.days
			from product_license_module p
			inner join license_module_type t
				on t.license_module_type_id = p.license_module_type_id
			where p.product_id = @product_id
		end	
	else
	-- 1.4) license_module data
		begin
			-- 1.4.1) @product_line_id
			select @product_line_id = product_line_id
			from license
			where license_id = @license_id

			-- 1.4.2) license_module_license
			select @license_module_type_id = t.license_module_type_id, @license_module_type_name = t.license_module_type_name
			from license_module_license m
			inner join license_module_type t
				on t.license_module_type_id = m.license_module_type_id
			where license_id = @license_id and m.license_module_id = @license_module_id

		end

	-- 1.5) @license_change_reason_id
	if @license_change_reason_id is null
		begin
			select @license_change_reason_id = 3
		end

	-- 1.6) @license_type_id 

	--select * from @license_modules order by category_license_module_id
	--return

	if @product_line_id in (55,300)
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update/insert business
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	begin

		-- 2.0) module_seats
		if @module_seats is null
			begin
			select @module_seats = license_seats from license_seat where license_id = @license_id
			end
		
		-- delete from @license_modules where category_license_module_id is not null

		-- 2.1) @license_module_license_id
		select @license_module_license_id = ml.license_module_license_id, 
				@current_license_module_type_id = ml.license_module_type_id, 
				@current_license_module_type_name = t.license_module_type_name,
				@current_module_seats = ml.module_seats,
				@current_start_date = ml.start_date,
				@current_end_date = ml.end_date
		from license_module_license ml
		inner join license_module_type t
			on t.license_module_type_id = ml.license_module_type_id
		where license_id = @license_id and license_module_id = @license_module_id
				
		if @module_end_date is null
			begin
			select @module_end_date = @current_end_date
			end

		-- 1.5) @parent_license_module_license
		select @parent_license_id = parent_license_id
		from license_parent
		where child_license_id = @license_id

		if @parent_license_id is not null
			begin
			declare @parent_license_module_end_date datetime

			select @parent_license_module_end_date = ml.end_date
			from license_module m
			inner join license_module_license ml
				on m.parent_license_module_id = ml.license_module_id 
			where m.license_module_id
 = @license_module_id and ml.license_id = @parent_license_id

			if @license_category_end_date > @parent_license_module_end_date
				begin
				select @license_category_end_date = @parent_license_module_end_date
				end

			end

		--select current_license_module_type_name = @current_license_module_type_name, license_module_type_name = @license_module_type_name
		--select license_category_start_date = @license_category_start_date, current_start_date = @current_start_date, order_item_start_date = @order_item_start_date
		--select license_category_end_date = @license_category_end_date, current_end_date = @current_end_date, order_item_end_date = @order_item_end_date
		--select module_seats = @module_seats, module_end_date = @module_end_date
		--return

		if @license_module_license_id is null
			-- 2.2) insert license_module_license
			begin
			
			-- 2.2.1) 
			insert into license_module_license_history(license_id, license_module_id, license_module_type_id, start_date, end_date, order_item_id, license_change_reason_id, history_date, module_seats)
			select @license_id, @license_module_id, @license_module_type_id, start_date = null, end_date = null, @order_item_id, license_change_reason_id = 1, @last_modified_date, @module_seats
			
			-- 2.2.2) 
			insert into license_module_license(license_id, license_module_id, license_module_type_id, module_seats, start_date, end_date)
			select license_id = @license_id, license_module_id = @license_module_id, license_module_type_id = @license_module_type_id, module_seats = @module_seats,
				start_date = case
									when @license_module_type_name = 'full' then isnull(@order_item_start_date,convert(date,getdate()))
									when @license_module_type_name = 'trial' then convert(date,getdate())
							end,
				end_date = case
									when @license_module_type_name = 'full' then isnull(@order_item_end_date,@license_category_end_date)
									when @license_module_type_name = 'trial' and dateadd(dd,@days,convert(date,getdate())) > @license_category_end_date then @license_category_end_date
									when @license_module_type_name = 'trial' and dateadd(dd,@days,convert(date,getdate())) <= @license_category_end_date  then dateadd(dd,@days,convert(date,getdate()))
							end

			-- 2.2.3) sky dns_registration
			if @license_module_id = 30 
				begin
				select @sky_template_id = 3, @process_date = dateadd(mi,5,getdate())

				if not exists (select sky_update_id from sky_update where license_id = @license_id and sky_template_id = 1)
					begin
						exec usp_sky_insert_update @license_id, @sky_template_id, @process_date
					end
				end
			end
		else
			-- 2.3) update license_modules_license
			begin
			-- print '2.3) update license_modules_license'
			if @current_license_module_type_name <> @license_module_type_name or 
				@current_module_seats <> @module_seats or (@current_module_seats = @module_seats and @order_item_id is not null) or
				@current_start_date <> @license_category_start_date or
				@current_end_date <> @license_category_end_date or
				@current_end_date <> @module_end_date

				begin
				-- print 'update'
				if @order_item_id is not null
					begin
					-- 2.3.2) full module_seat upgrade
					if @current_end_date = @order_item_end_date and @current_license_module_type_name = @license_module_type_name and @license_module_type_name = 'full'
						begin
						-- print '-- 2.3.2) full module_seat upgrade'
						select @module_seats = @module_seats + @current_module_seats
						end

					-- 2.3.3) full renewal
					if @current_end_date < @order_item_end_date and @current_license_module_type_name = @license_module_type_name and @license_module_type_name = 'full'
						begin
						select @license_change_reason_id = 2
						end

					-- 2.3.4) trial to full
					if @current_license_module_type_name = 'trial' and @license_module_type_name = 'full'
						begin
						select @license_change_reason_id = 1
						end
		
			end
				else
					begin
					-- 2.3.5) end data chenge
					if @current_end_date <> @module_end_date
						begin
						select @license_change_reason_id = case when @module_end_date > @current_end_date then 4 else 31 end
						end
					-- 2.3.6) module seat change
					if @current_module_seats <> @module_seats
						begin
						select @license_change_reason_id = case when  @current_module_seats < @module_seats then 4 else 29 end
						end
					end

				-- 2.3.1) license_module_license_history
				insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date, module_seats)
				select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
						m.start_date, 
						end_date = convert(date,getdate()),
						m.last_modified_date, m.last_modified_by, order_item_id = @order_item_id, license_change_reason_id = @license_change_reason_id, last_modified_date = @last_modified_date,
						m.module_seats
				from license_module_license m
				where m.license_module_license_id = @license_module_license_id


			-- 2.2.2) update license_module_license
				update license_module_license
				set license_module_type_id = @license_module_type_id, 
						start_date = convert(date,getdate()), 
						end_date = case 
										when @order_item_id is not null and @order_item_end_date is not null then @order_item_end_date
										when @order_item_id is not null and @order_item_end_date is null and @capability_type_description = @license_module_type_name then @license_category_end_date
										when @order_item_id is not null and @order_item_end_date is null and @capability_type_description = 'full' and @license_module_type_name = 'trial' then dateadd(dd,@days,convert(date,getdate()))
										
										when @order_item_id is null and @license_change_reason_id = 29 then end_date -- seat downgrade
										when @order_item_id is null and @license_change_reason_id in (31,4) then @module_end_date -- disable/manually extend

										when @order_item_id is null and @license_module_type_name = 'full' then @license_category_end_date
										when @order_item_id is null and @license_module_type_name = 'trial' and dateadd(dd,@days,convert(date,getdate())) > @license_category_end_date then @license_category_end_date
										when @order_item_id is null and @license_module_type_name = 'trial' and dateadd(dd,@days,convert(date,getdate())) <= @license_category_end_date  then dateadd(dd,@days,convert(date,getdate()))
									end,
						module_seats = @module_seats,
						last_modified_date = @last_modified_date,
						last_modified_by = @modified_by
				from license_module_license m
				where license_module_license_id = @license_module_license_id
				end

			-- 2.2.3) update child license
			if @license_type_id = 2 and @order_item_id is null
				begin
					declare @parent_license_module_license table (license_module_id tinyint, license_module_type_id tinyint, start_date datetime, end_date datetime)

					-- 2.2.3.1) get parent modules
					insert into @parent_license_module_license (license_module_id,license_module_type_id,start_date, end_date)
					select m.license_module_id, m.license_module_type_id, m.start_date, m.end_date
					from license_module_license m
					where m.license_id = @license_id

					-- 2.2.3.2) insert history
					insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date, module_seats)
					select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
							m.start_date, 
							end_date = convert(date,getdate()),
							m.last_modified_date, m.la
st_modified_by, order_item_id = @order_item_id, license_change_reason_id = @license_change_reason_id, last_modified_date = @last_modified_date,
							m.module_seats
					from license_parent lp
					inner join license_module_license m
						on lp.child_license_id = m.license_id
					inner join license_module lm
						on m.license_module_id = lm.license_module_id
					inner join @parent_license_module_license p
						on lm.parent_license_module_id = p.license_module_id and m.license_module_type_id = p.license_module_type_id
					where lp.parent_license_id = @license_id

					-- 2.2.3.3) update license_module_license
					update license_module_license
							set start_date = p.start_date,
								end_date = p.end_date,
								last_modified_date = @last_modified_date,
								last_modified_by = @modified_by
					from license_parent lp
					inner join license_module_license ml
						on lp.child_license_id = ml.license_id
					inner join license_module m
						on m.license_module_id = ml.license_module_id
					inner join @parent_license_module_license p
						on m.parent_license_module_id = p.license_module_id and ml.license_module_type_id = p.license_module_type_id
					where lp.parent_license_id = @license_id
				end
			end

		--Populate the license contract object with parent level first
		insert into @license_contract_object (license_id, license_category_id, license_status_id, license_category_type_id, license_start_date, license_end_date, license_service_id)
		select lml.license_id, lmc.license_category_id, iif(lml.license_status_id = 1, 1, 4), iif(lml.license_module_type_id = 19, 1, 2), lml.start_date, lml.end_date, @license_service_id
		from license_module_license lml
		inner join license_module_category lmc on lmc.license_module_id = lml.license_module_id
		where lml.license_id = @license_id
		and lml.license_module_id = isnull(@license_module_id, lml.license_module_id)
		and @license_service_id is not null

		--Populate the license contract object with child level next
		insert into @license_contract_object (license_id, license_category_id, license_status_id, license_category_type_id, license_start_date, license_end_date, license_service_id)
		select lml.license_id, lmc.license_category_id, iif(lml.license_status_id = 1, 1, 4), iif(lml.license_module_type_id = 19, 1, 2), lml.start_date, lml.end_date, @license_service_id
		from license_parent lp
		inner join license_module_license lml on lml.license_id = lp.child_license_id
		inner join license_module_category lmc on lmc.license_module_id = lml.license_module_id
		inner join license_module lm on lm.license_module_id = lml.license_module_id
		where lp.parent_license_id = @license_id
		and lm.parent_license_module_id = isnull(@license_module_id, lm.parent_license_module_id)
		and @license_service_id is not null

		--build up the JSON now based on data in @license_contract_object only for business licenses
		select @license_contract_json = (
		select license_id = lco.license_id, license_category_id = lco.license_category_id, license_status_id = lco.license_status_id, license_category_type_id = lco.license_category_type_id, license_start_date = lco.license_start_date, license_end_date = lco.license_end_date, license_service_id = lco.license_service_id, originating_license_contract_id = fn.license_contract_id
		from @license_contract_object lco
		outer apply fn_license_select_license_contract_table(lco.license_id, lco.license_category_id, 'max_row') fn
		where (lco.license_end_date != fn.license_end_date or fn.license_end_date is null) --end date changed
		   or (lco.license_category_type_id != fn.capability_type_id or fn.capability_type_id is null) --trial/full status changed
		   or (lco.license_status_id != fn.license_contract_status_id or fn.license_contract_status_id is null) --enabled/disabled (using license_contract_status_id as license status)
		for json path)

		--if data exists, call the insert now
		if @licen
se_contract_json is not null
		begin
			exec usp_license_insert_license_contract @license_contract_json = @license_contract_json, @license_contract_source_caller = 'usp_license_update_license_module_license'
		end

	end

	else
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update/insert consumer
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin

		select @module_seats = 0

		-- 3.1) select @license_modules data
		declare @license_modules table (license_module_id tinyint,license_module_license_id int, license_id int, license_module_type_id tinyint, start_date datetime, end_date datetime, module_seats int,module_days int,product_license_module_id tinyint, product_license_module_type_id tinyint,category_license_module_id tinyint, category_license_module_type_id tinyint, category_start_date datetime, category_end_date datetime,product_line_id int)

			-- 3.1.1) product_license_module
			insert into @license_modules(license_module_id, product_license_module_id, product_license_module_type_id, license_module_license_id, license_id, license_module_type_id, start_date, end_date, module_seats, module_days, product_line_id)
			select pm.license_module_id, 
					pm.license_module_id, 
					product_license_module_type_id = pm.license_module_type_id, 
					ml.license_module_license_id, 
					ml.license_id, 
					ml.license_module_type_id, 
					ml.start_date, 
					ml.end_date,
					ml.module_seats,
					pm.days,
					pl.product_line_id
			from product_license_module pm
			inner join product_line_product pl
				on pl.product_id = pm.product_id
			left join license_module_license ml
				on pm.license_module_id = ml.license_module_id and ml.license_id = @license_id
			where pm.product_id = @product_id

			-- 3.1.2) license_category_module
			insert into @license_modules(license_module_id, category_license_module_id, category_license_module_type_id, license_id, category_start_date, category_end_date)
			select t.license_module_id, t.license_module_id, t.license_module_type_id, t.license_id, t.start_date, t.end_date
			from @license_modules lm
			right join (select m.license_module_id, m.license_module_type_id, cl.license_id, cl.start_date, cl.end_date
						from license_category_license cl
						inner join license_category_module m
							on cl.license_category_id = m.license_category_id
						where license_id = @license_id) t
				on lm.license_module_id = t.license_module_id

		-- 3.2) add new modules where they don't exist
	
			-- 3.2.1) add initial history record
			insert into license_module_license_history(license_id, license_module_id, license_module_type_id, start_date, end_date, order_item_id, license_change_reason_id, history_date, module_seats)
			select @license_id, product_license_module_id, product_license_module_type_id, start_date = null, end_date = null, @order_item_id, @license_change_reason_id, @last_modified_date, @module_seats
			from @license_modules
			where product_license_module_id is not null and category_license_module_id is null and license_module_license_id is null
			order by license_module_id

			-- 3.2.2) insert license_module_license
			insert into license_module_license(license_id, license_module_id, license_module_type_id, start_date, end_date, module_seats)
			select @license_id, product_license_module_id, product_license_module_type_id, 
				start_date = dateadd(dd,-(datediff(dd,getdate(),@license_category_end_date)),@license_category_end_date), 
				end_date = case when module_days is not null then dateadd(dd,module_days,dateadd(dd,-(datediff(dd,getdate(),@license_category_end_date)),@license_category_end_date)) else @license_catego
ry_end_date end, 
				@module_seats
			from @license_modules
			where product_license_module_id is not null and category_license_module_id is null and license_module_license_id is null
			order by license_module_id

		-- 3.3) update license_modules_license

			-- 3.3.1) license_module_license_history
			insert into license_module_license_history(license_module_license_id, license_id, license_module_id, license_module_type_id, start_date, end_date, last_modified_date, last_modified_by, order_item_id, license_change_reason_id, history_date)
			select m.license_module_license_id, m.license_id, m.license_module_id, m.license_module_type_id, 
					m.start_date, 
					end_date = dateadd(dd,datediff(dd,m.start_date,@license_category_start_date),m.start_date),
					m.last_modified_date, m.last_modified_by, @order_item_id, @license_change_reason_id, @last_modified_date
			from license_module_license m
			inner join @license_modules l
				on m.license_module_license_id = l.license_module_license_id
			where l.product_license_module_id is not null and l.category_license_module_id is null and l.license_module_license_id is not null and (l.start_date <> @license_category_start_date or l.end_date <> @license_category_end_date)
			order by m.license_module_id
	
			-- 3.3.2) update license_module_license
			update license_module_license
			set license_module_type_id = l.product_license_module_type_id, start_date = @license_category_start_date, end_date = @license_category_end_date, last_modified_date = @last_modified_date
			from license_module_license m
			inner join @license_modules l
				on m.license_module_license_id = l.license_module_license_id
			where l.product_license_module_id is not null and l.category_license_module_id is null and l.license_module_license_id is not null and (l.start_date <> @license_category_start_date or l.end_date <> @license_category_end_date or m.license_module_type_id <> l.product_license_module_type_id)
		end
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_scan_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_scan_license]

/*	
	DATE		AUTHOR		REMARKS
	
	2017-01-30	acoffel		Initial creation.
	
	DESCRIPTION
	update license_scan_license records
*/

as
  set nocount on

  begin try
  
	declare	@response_code int,
				@message varchar(100)	

		
		declare @license_scan_license table ([license_id] [int],[keycode] [varchar](40),[good_scans] [bigint],[bad_scans] [bigint], [modified_date] [date])
		declare @license_scan_license_dups table ([license_id] [int])

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get license data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		  --1.1) insert into @license_scan_license
		  insert into @license_scan_license (license_id, keycode, good_scans, bad_scans, modified_date)               
		  select dw.license_id,
				 keycode = dw.keycode,
				 good_scans = dw.good_scans,
				 bad_scans = dw.bad_scans,
				 modified_date = dw.modified_date
		  from datawarehousereadonly.feed.dbo.license_scan_license dw
		  inner join license_scan_license l with (nolock) 
			on dw.license_id = l.license_id
		  where dw.modified_date > l.modified_date
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update/insert license_scan_license
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		   --2.1) updates to license_scan_license
		   update license_scan_license
			set good_scans = s.good_scans,
				bad_scans = s.bad_scans,
				modified_date = s.modified_date
			from license_scan_license l
			inner join @license_scan_license s
				on l.license_id = s.license_id

			--2.2) insert into license_scan_license
		  insert into license_scan_license (license_id, keycode, good_scans, bad_scans, modified_date)               
		  select dw.license_id,
				 keycode = dw.keycode,
				 good_scans = dw.good_scans,
				 bad_scans = dw.bad_scans,
				 modified_date = dw.modified_date
		  from datawarehousereadonly.feed.dbo.license_scan_license dw
		  left join license_scan_license l with (nolock) 
			on dw.license_id = l.license_id
		  where l.license_id is NULL
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update license_scan_license failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_license_update_license_seats]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_license_update_license_seats]

(
	@license_id int,
	@license_seats int,
	@license_change_reason_id int,
	@order_item_id int,
	@response_code int output,
	@message varchar(100) output 
)

/*	
	DATE			AUTHOR			REMARKS
	2007-03-13		esmart			Initial creation
	2007-05-17		esmart			Add update to license..max_child_licenses for enterprise 
	2007-09-18		bjordan			added try/catch
	2010-01-06		esmart			date and order_item_id fields
	2010-06-14		dsmelker		Removed the Enterprise restriction on reducing the number of seats
	2014-10-23		esmart			Modify for SMB seat upgrade
	2015-10-22		esmart			Effective seats support
	2016-01-07		esmart			Correct setting end_date on license_seat_history
	2016-03-25		esmart			Add future dated seat upsells to effective seats
	2016-06-03		esmart			Fix issue with upgrade/renewal overwriting effective_seats
	2017-03-02		cnovac			Fix issue where effective seats not getting set properly
	2017-05-01		cnovac			Added call to usp_license_insert_effective_object to save data into effective object
	2017-05-22		cnovac			update to usp_license_insert_effective_object call
	2017-06-13		cnovac			update to usp_license_insert_effective_object call added dateadd(dd, 1, @effective_expiration_date)
	2018-04-22		cnovac			update to usp_license_insert_effective_object call to use JSON
	2018-09-07		rvinoche		Allow past record updates when calling usp_license_insert_effective_object
	2018-11-01		cnovac			Took out references to effective columns in license_seats
	2019-09-06		cnovac			Updated code to remove @allow_past_record_update variable and always allow that code to fire

	DESCRIPTION
	Update license_seat record

*/


AS
	set nocount on

	begin try

	declare @license_seat_id int,
			@transaction_date datetime,
			@system_user varchar(50),
			@rowcnt int,
			@current_license_seats int,
			@product_line_id int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@product_upgrade int,
			@license_effective_object_json varchar(max),
			@effective_start_date date

	declare @effective_json table (license_id int, license_seats int)

	
	if @license_change_reason_id is null
		begin
		select @license_change_reason_id = 4 
		end

	select @transaction_date = getdate(),
			@system_user = suser_sname(),
			@product_upgrade = 0

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @license_seats
	if @license_seats <= 0 
		begin
			set @response_code = -110
			set @message = 'license seats must be greater than or equal to 0'
			return
		end

	-- 1.2) @license_seat_id
	select @license_seat_id = license_seat_id, @current_license_seats = license_seats
	from license_seat
	where license_id = @license_id	

	-- 1.3) determine is this is an enterprise license
	select @product_line_id = product_line_id
	from license
	where license_id = @license_id

	-- 1.4) select current capability dates
	select @capability_activation_date = min(capability_activation_date),
			@capability_expiration_date = max(capability_expiration_date)
	from license_capability
	where license_id = @license_id

	-- 1.5) check if product vs seat upgrade
	select @product_upgrade = count(*)
	from order_item i
	inner join product_license_category lc
		on i.product_id = lc.product_id
	where order_item_id = @o
rder_item_id and lc.current_license_category_id <> lc.license_category_id

	-- 1.6) seat upgrade
	if @license_change_reason_id = 3 and @product_line_id in (55,300) and @product_upgrade = 0
		begin
		select @license_seats = @license_seats + @current_license_seats
		end

	-- 1.7) get the start date of the change to seat
	select @effective_start_date = effective_date
	from order_item
	where order_item_id = @order_item_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) write to history and update license_seat
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @license_seat_id is null
	-- 2.1) insert license_seat record
		begin
			insert into license_seat(license_id, license_seats, seats_used, start_date, end_date)
			output Inserted.license_id, Inserted.license_seats into @effective_json (license_id, license_seats) --added this code to capture what row was inserted
			values (@license_id, @license_seats, 0, @capability_activation_date, @capability_expiration_date)

		-- 2.1.1) Add row to license_seat_history if the order_item_id is not null. This is needed for refund logic.
			if @order_item_id is not null
				begin
				insert into license_seat_history (license_seat_id, license_id, license_seats, seats_used, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by, start_date, end_date, order_item_id)
				select license_seat_id, license_id, license_seats = 1, seats_used, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @system_user, start_date, end_date, @order_item_id
				from license_seat
				where license_id = @license_id
				end	
		end
	-- 2.2) update license_seat
	else
		begin
			insert into license_seat_history (license_seat_id, license_id, license_seats, seats_used, insert_date, insert_by, modified_date, modified_by, license_change_reason_id, history_date, history_by, start_date, end_date, order_item_id)
			select license_seat_id, license_id, license_seats, seats_used, insert_date, insert_by, modified_date, modified_by, @license_change_reason_id, @transaction_date, @system_user, start_date, @capability_activation_date, @order_item_id
			from license_seat
			where license_id = @license_id

			update license_seat 
			set license_seats = @license_seats, 
				start_date = @capability_activation_date,
				end_date = @capability_expiration_date,
				modified_date = @transaction_date, modified_by = @system_user
			output Inserted.license_id, Inserted.license_seats into @effective_json (license_id, license_seats) --added this code to capture what row was updated
			where license_id = @license_id
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3) write to license_effective_object
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--build up the JSON now based on data in @effective_json only for business licenses
	select @license_effective_object_json = (
	select license_id = ej.license_id, license_category_id = lcl.license_category_id, license_seats = ej.license_seats, effective_start_date = isnull(@effective_start_date, @transaction_date), order_item_id = @order_item_id
	from @effective_json ej
	inner join license l on l.license_id = ej.license_id
	inner join license_category_license lcl on lcl
.license_id = ej.license_id
	where l.product_line_id in (55, 300)
	for json path)

	--if data exists, call the insert now
	if @license_effective_object_json is not null
	begin
		exec usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = 'usp_license_update_license_seats'
	end
	
	
	set @response_code = 0
	set @message = 'Successfully updated license_seat'

end try
begin catch

	  if @@trancount > 0
	     
      declare @DBName nvarchar(128)
      set @DBName = db_name()

		set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
		set @message = case 
							when @message is null then 'license_seat update failed'
							else @message 
						end
      exec usp_LogError @ErrorDB = @DBName
		


end catch





GO
