CREATE PROCEDURE [dbo].[usp_license_update_license_seats_csi]

(
	@keycode varchar(64),
	@license_seats int,
	@license_change_reason_id int = NULL,
	@response_code int output,
	@message varchar(100) output 
)

/*	
	DATE			AUTHOR			REMARKS
	2013-08-13		acoffel			Initial creation
	2014-10-17		esmart			Change to use license_service to better manage history data
	2016-07-25		cnovac			Maded changes for license service call now JSON format

	DESCRIPTION
	Update license_seat record	
*/

AS
	set nocount on
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) license service
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @license_service_type_name varchar(50),
			@service_json nvarchar(max)
	declare @output table (license_service_id int, response_code int, message varchar(100))

	select @license_service_type_name = 'update_license'
	select @service_json = '{"keycode":"' + @keycode + '","license_seats":"' + str(@license_seats) + '"}'

	insert into @output(license_service_id,response_code,message)
	exec usp_license_service_insert_service @license_service_type_name, @service_json
		
	set @response_code = 0
	set @message = 'Successfully updated license_seat'

end try
begin catch

	  if @@trancount > 0
	     
      declare @DBName nvarchar(128)
      set @DBName = db_name()

		set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
		set @message = case 
							when @message is null then 'license_seat update failed'
							else @message 
						end
      exec usp_LogError @ErrorDB = @DBName
		
end catch



GO
