CREATE procedure [dbo].[usp_licensing_insert_license_check]
(@license_id int,
 @load_type int = 0 --0 = all, 1 = license only, 2 = account only, 3 = activation only, 10 = Delete the account_check rec

)

as
/*
	DATE		AUTHOR		REMARKS
	2009-06-15	bjordan		Initial creation.
