							,@product_line_id=l.product_line_id
				from license l
				where license_id = @license_id
				
				select
						 @license_status_description=lst.license_status_description
						,@license_status_id=lst.license_status_id
				from license_status lst
				where license_status_id = @license_status_id
				
				select
						@license_feature_id=license_feature_id
				from license_feature_license f with (nolock)
				where f.license_feature_id = 3
				and license_id = @license_id
				
				select
