			,c.capability_id
			,ca.capability_name
			,ca.capability_description
			,c.capability_type_id
			,c.capability_activation_days
			,c
.capability_activation_date
			,c.capability_expiration_date
			,needs_registration = case when @customer_id is null and @license_feature_id is null then 1 else 0 end
			,auto_renewal = case when @license_attribute_license_id is null then 0 else 1 end
			,storage_account_username = case when c.capability_id = 11 then @storage_account_username else '' end
			,customer_id=isnull(@customer_id,' ')
			,@license_status_description as license_status
			,@license_type_description as license_type
			,@product_line_id as product_line_id
			,p_rc = NULL
			,@license_category_name as license_category_id
			,@license_seats as license_seats
			,@seats_used as seats_used
			,@subscription_id as subscription_id
			,isnull(@end_date, dateadd(dd,45,getdate()) ) expiration_date
			,isnull(@start_date, getdate()) start_date
			,getdate() insert_date
			from license_capability c
			inner join capability ca
				on c.capability_id = ca.capability_id
			where c.license_id = @license_id
		FOR XML PATH)

		set @xml='<record>'+replace(@xml,'''','''''')+'</record>'

		set @sql = 'exec ' + @dbconnect + '.dbo.usp_license_check_insert ' + cast(@license_id as varchar(50)) + ', '''+ @xml + ''''

		exec sp_executesql @sql
		--select @xml
  end

-- Load Account_check data
if @load_type in (0,2)
	begin

	select @xml = (
			select
			a.account_id
