	set @xml='<record>'+replace(@xml,'''','''''')+'</record>'

	set @sql = 'exec ' + @dbconnect + '.dbo.usp_account_check_insert ' + cast(@license_id as varchar(50)) + ', '''+ @xml + ''''

	--exec sp_executesql @sql


	end

/*
