		exec sp_executesql @sql


	end

*/

if @load_type = 10
Begin

	set @sql = 'exec ' + @dbconnect + '.dbo.usp_account_check_delete ' + cast(@license_id as varchar(50)) 

	--exec sp_executesql @sql

	
End
*/
select 0

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert failed for license_id: ' + cast(@license_id as varchar(20))
						else @message + ' - license_id: ' + cast(@license_id as varchar(20)) end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch;

End

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_licensing_insert_static_content_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_licensing_insert_static_content_update]

(
	@static_content_type varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100)

	select @system_user = suser_sname(),
			@db_name = db_name()

	select @task_number =  datepart(ms,getdate())
	
	if @static_content_type is null
		begin
		select @sql_string = 
				'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
				' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_licensing_update_static_content'',0,getdate()) '
		end
	else
		begin
		select @sql_string = 
				'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
				' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_licensing_update_static_content ''''' + @static_content_type + '''''' + ''',0,getdate()) '
		end
	
	--select @sql_string

	exec (@sql_string)

	exec tasks..usp_queue_task @task_number

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_licensing_license_message_bulk_load]
-- =============================================================================

CREATE PROCEDURE  [dbo].[usp_licensing_license_message_bulk_load]


/*	
	DATE		AUTHOR		REMARKS
	2010-11-23	esmart	Initial creation.

	DESCRIPTION
	
*/

AS
	declare @max_insert_date datetime,
			@total_licenses int,
			@batch_size int,
			@batch_count int,
			@current_batch int,
			@sql nvarchar(max),
			@xml nvarchar(max),
			@dbconnect varchar(100),
			@response_code int,
			@message varchar(100)


	begin try

	--------------------------------------------------------------------------------------------------------------------------------
	-- 1) select
	--------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) set db connection for appropriate licensing server
		select @dbconnect=dbo.getConnection('licensing')
	
	-- 1.2) get max data and total licenses
		select @batch_size = 1000,
				@current_batch = 1

		select @max_insert_date = max(insert_date) from license_message_check_update_license with (nolock)

		select @total_licenses = count(*) 
		from license_message_check_update_license with (nolock)
		where insert_date <= @max_insert_date

	-- 1.2) calculate the number of batches
		if  @total_licenses < @batch_size
			begin
				select @batch_count = 1
			end
		else
			begin		 
				select @batch_count = round(@total_licenses/@batch_size,0)
			end	

--select max_insert_date = @max_insert_date, total_licenses = @total_licenses, batch_count = @batch_count

	--------------------------------------------------------------------------------------------------------------------------------
	-- 2) run updates
	--------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) batch
	while @current_batch <= @batch_count
		begin
		print @current_batch
		
		-- 2.1.1) select data
		select @xml = (	select license_message_id, keycode, license_id, license_message_key, process_date, end_date, message_campaign_id, message_platform_id, massage_platform_name, message_content_id, serial_number, contract_id, cart_discount_id
						from license_message_check l with (nolock)
						where license_id in (select top(@batch_size) license_id from license_message_check_update_license with (nolock) where insert_date <= @max_insert_date order by insert_date, license_id)
						FOR XML PATH)

		-- 2.1.2) format xml and create dynamic statement
			set @xml='<record>'+replace(@xml,'''','''''')+'</record>'

			set @sql = 'exec ' + @dbconnect + '.dbo.usp_license_message_check_insert_bulk '''+ @xml + ''''

		-- 2.1.3) execute
			exec sp_executesql @sql

		-- 2.1.4)
		select @xml = (	select top(@batch_size) license_id 
						from license_message_check_update_license with (nolock) 
						where insert_date <= @max_insert_date 
							and license_id not in (select license_id from license_message_check l with (nolock))
						FOR XML PATH)

--		select _xml = @xml

		-- 2.1.5) format xml and create dynamic statement
			set @xml='<record>'+replace(@xml,'''','''''')+'</record>'

			set @sql = 'exec ' + @dbconnect + '.dbo.usp_license_message_check_delete_bulk '''+ @xml + ''''

		-- 2.1.6) execute
			exec sp_executesql @sql

		-- 2.1.7) delete row from batch
			delete from license_message_check_update_license where license_id in (select top(@batch_size) license_id from license_message_check_update_license with (nolock) where insert_date <= @max_insert_date order by insert_date, license_id)

		select @current_batch = @current_batch + 1
		end



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'usp_licensing_license_message_bulk_load batch failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @Error
DB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_licensing_select_license_account]
-- =============================================================================

CREATE procedure [dbo].[usp_licensing_select_license_account]
(@license_id int)
as
/*****************************************************************************
	DATE		AUTHOR		REMARKS
	2009-09-02	dsmelker	Initial creation.
	2015-03-12	acoffel		added license_summary and capability_activation_date
	

	DESCRIPTION
	Called from the Licensing DB to return account information



*****************************************************************************/
begin

select 
	a.account_id
	,l.license_id
	,account_user_name
	,account_password
	,account_type
	,account_type_description
	,account_status
	,isnull(parent_account_id,0) as parent_account_id
	,isnull(warn_opt_in,0) as warn_opt_in
	,capability_activation_date
	 from account a with (nolock)
	inner join account_license l with (nolock) on
	a.account_id = l.account_id
	left join account_type t on
	a.account_type_id = t.account_type_id
	left join account_status s on
	a.account_status_id = s.account_status_id
	left join license_summary ls
		on l.license_id = ls.license_id 
	where l.license_id = @license_id

	declare @dbsource sysname
		
	set @dbsource = db_name()
	
	exec tasks..usp_licensing_send_tasks @license_id = @license_id, @load_type = 6, @dbsource = @dbsource

end


GO
