-- PROCEDURE: [dbo].[usp_licensing_select_license_subscription]
-- =============================================================================
Create procedure [dbo].[usp_licensing_select_license_subscription]
(@license_id int)
as
/*****************************************************************************
	DATE		AUTHOR		REMARKS
	2009-09-02	dsmelker	Initial creation.
	

	DESCRIPTION
	Called from the Licensing DB to return license subscription information



*****************************************************************************/
begin

select license_id,
		serial_number,
		start_date,
		cancel_date,
		expiration_date,
		term =case when subscription_type in (0,1) then 'Monthly' else 'Yearly' end 
	from subscription s with (nolock)
	inner join subscription_type st on
	s.subscription_type_id = st.subscription_type_id
	where license_id = @license_id

	declare @dbsource sysname
		
	set @dbsource = db_name()

	exec tasks..usp_licensing_send_tasks @license_id = @license_id, @load_type = 5, @dbsource = @dbsource

end

GO
