-- =============================================================================

CREATE PROCEDURE [dbo].[usp_licensing_update_license_keycode_alias]

/*	
	DATE		AUTHOR		REMARKS
	2011-11-18	esmart		Initial creation.
	2012-01-03	esmart		Max of 1000 rows per batch

	DESCRIPTION
	
*/

AS
	set nocount on			
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON		

	declare @xml nvarchar(max),
			@dbconnect varchar(50),
			@update_sql nvarchar(max),
			@max_insert_date datetime,
			@response_code int,
			@message varchar(2000)	

	begin try

	/*
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @max_insert_date = max(t.insert_date) 
	from (select top 1000 license_id, insert_date from license_keycode_alias_update order by insert_date) t
	
	-- 1.1) update licensing server
	select @dbconnect=dbo.getConnection('licensing')
	
	select @xml = (
			select distinct a.license_keycode_alias_id, a.license_id, a.keycode, a.keycode_alias, a.last_modified_date
			from license_keycode_alias a
			inner join license_keycode_alias_update u
				on a.license_id = u.license_id
			where u.insert_date <= @max_insert_date
		FOR XML PATH)

	select @xml='<record>'+replace(@xml,'''','''''')+'</record>'
	
	--select @xml

	select @update_sql = 'exec ' + @dbconnect + '.dbo.usp_license_update_license_keycode_alias '''+ @xml + ''''

--	select @update_sql
	exec sp_executesql @update_sql

	-- 1.2) delete license_id from license_keycode_alias_update
	delete from license_keycode_alias_update where insert_date <= @max_insert_date
	*/

	select 0

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_licensing_update_static_content]
-- =============================================================================

CREATE PROCEDURE  [dbo].[usp_licensing_update_static_content]

(
	@static_content_type varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-09	esmart		Initial creation.
	2013-01-11	esmart		Add @static_content_type
	
	DESCRIPTION
	
*/

AS 

declare		@dbconnect varchar(100),
			@response_code int,
			@message_content_sql nvarchar(max),
			@message_content_display_sql nvarchar(max),
			@cart_discount_summary_sql nvarchar(max),
			@license_category_module_sql nvarchar(max),
			@message varchar(100)

set nocount on

begin try

	--------------------------------------------------------------------------------------------------------------------------------
	-- 1) create temp table for xml data
	--------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) set db connection for appropriate licensing server
		select @dbconnect=dbo.getConnection('licensing')

		select dbconnect = @dbconnect

	-- 1.2) create dynamic SQL and execute

		select @message_content_sql = 'delete from ' + @dbconnect + '.dbo.message_content insert into ' + @dbconnect + '.dbo.message_content(message_content_id, message_content_name, message_action, last_modified_date, last_modified_by) select message_content_id, message_content_name, message_action, last_modified_date, last_modified_by from message_content'
		select @message_content_display_sql = 'delete from ' + @dbconnect + '.dbo.message_content_display insert into ' + @dbconnect + '.dbo.message_content_display(message_content_display_id, message_content_id, offer_tagline, offer_body, offer_button, image_url, language_code, location_code, last_modified_date, last_modified_by) select message_content_display_id, message_content_id, offer_tagline, offer_body, offer_button, image_url, language_code, location_code, last_modified_date, last_modified_by from message_content_display'
		select @cart_discount_summary_sql = 'delete from ' + @dbconnect + '.dbo.cart_discount_summary insert into ' + @dbconnect + '.dbo.cart_discount_summary(cart_discount_id, discount, language_code, location_code, currency, currency_code, symbol_html, symbol_utf8, symbol_text, cart_discount_method_name) select i.cart_discount_id, isnull(d.discount,i.discount), d.language_code, d.location_code, d.currency, c.currency_code, c.symbol_html, c.symbol_utf8, c.symbol_text, m.cart_discount_method_name from cart_discount_item i left join cart_discount_item_discount d on i.cart_discount_item_id = d.cart_discount_item_id left join currency c on d.currency_id = c.currency_id inner join  cart_discount cd on cd.cart_discount_id = i.cart_discount_id  inner join  cart_discount_method m on i.cart_discount_method_id = m.cart_discount_method_id where cart_discount_type_id <> 4' 
		select @license_category_module_sql = 'delete from ' + @dbconnect + '.dbo.license_category_module insert into ' + @dbconnect + '.dbo.license_category_module(license_category_module_id,license_category_id,license_category_name,license_module_id,license_module_code,license_module_name,license_module_type_id,license_module_type_name) select c.license_category_module_id,lc.license_category_id,lc.license_category_name,m.license_module_id,m.license_module_code,m.license_module_name,t.license_module_type_id,t.license_module_type_name from license_category_module c inner join  license_category lc on c.license_category_id = lc.license_category_id inner join  license_module m on c.license_module_id = m.license_module_id inner join  license_module_type t on c.license_module_type_id = t.license_module_type_id'
			
			
		--select @message_content_sql
		--select @message_content_display_sql
		--select @cart_discount_summary_sql
		--select @license_category_module_sql

	-- 1.3 spectify content

		if 
@static_content_type is null 
			begin
			exec sp_executesql @message_content_sql
			exec sp_executesql @message_content_display_sql
			exec sp_executesql @cart_discount_summary_sql
			exec sp_executesql @license_category_module_sql
			end
		if @static_content_type = 'message_content' 
			begin
			exec sp_executesql @message_content_sql
			exec sp_executesql @message_content_display_sql
			end
		if @static_content_type = 'discount' 
			begin
			exec sp_executesql @cart_discount_summary_sql
			end
		if @static_content_type = 'license_category' 
			begin
			exec sp_executesql @license_category_module_sql
			end

		

end try 

begin catch

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_load_update_complete]
-- =============================================================================

CREATE procedure [dbo].[usp_load_update_complete]
(

	@vendor_order_id bigint,
	@vendor_id int,
	@system_user varchar(50) = null,
    @no_soa smallint = 0,
	@response_code int OUTPUT,
	@message varchar(100) OUTPUT
)

as
/*
	DATE		AUTHOR		REMARKS
	08/27/2006	tblazek		Initial creation
	10/05/2006	tblazek		Add insert into audit table for error tracking
	11/27/2006	tblazek		Add logic to skip archive process for DR orders with status of 'LOADCOMPLETE'
	12/05/2006	tblazek		Change @vendor_order_id from int to bigint
	03/30/2007	mscardino	Cleaned up the code to make more readable
    05/11/2007	bjordan		added @no_soa parameter and setting of order_load_definition_id to 8 for 
							CD2Go products or future products that do not have an SOA
	10/03/07	bjordan		added try/catch

	DESCRIPTION
	Change the status of the order to transaction complete for webroot cart, change the status to load complete for DR, call wrapper procedure to 
	transform the data from the load tables in to the ecommerce tables.
*/
begin try
set NOCOUNT on

declare 
	@order_load_definition_id int, 	
	@order_notification_status_id int,
	@order_load_error_definition_id int ,
	@debug_flag bit,
	@insert_date datetime
	
---Set to 1 for test from query analyzer.  Has to be off when transaction originates from PHP
select @debug_flag = 0,
	   @system_user = user,
	   @insert_date = getdate()

--NOTE:  still need to analyze the impact of multiple records for a single order - DR duplicates,  Refunds, etc..
--This query will probably need to be modified once all scenarios are known. tcb 8/28/6
select 
	@order_notification_status_id = 
	(select 
		top 1 order_notification_status_id 
		from order_notification_status 
		where vendor_order_id = @vendor_order_id 
		and vendor_id = @vendor_id 
		order by insert_date desc)

if not exists (select order_notification_status_id from order_notification_status where order_notification_status_id = @order_notification_status_id)
	begin
		select @response_code = -100
		select @message =  'Invalid order_notification_status_id Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
		RAISERROR (@message, 11, 0)
	end
else
begin
	--Verify records are loaded, if records exist, drill down to row level validation
	if not exists (select top 1 customer_load_id from customer_load where vendor_order_id = @vendor_order_id and vendor_id = @vendor_id)
		begin
			select @response_code = -105
			select @message =  'customer load record missing, Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' order completion failed'
			RAISERROR (@message, 11, 0)
		end

	if not exists (Select order_load_id from order_load where vendor_order_id = @vendor_order_id and vendor_id = @vendor_id)
		begin
			select @response_code = -110
			select @message =  'order load record missing, Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' order completion failed'
			RAISERROR (@message, 11, 0)
		end

	if not exists (Select top 1 order_item_load_id from order_item_load where vendor_order_id = @vendor_order_id and vendor_id = @vendor_id)
		begin
			select @response_code = -115
			select @message =  'order item load record(s) missing, Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' order completion failed'
			RAISERROR (@message, 11, 0)
		end

	--add validation - if order item product id a keycoded product, validate keycode record exists in license load
	if @vendor_id in (1,3,4,5) or @no_soa = 1 --CD2Go
	--If webroot, ATT, MSN, complete transaction (NOTE: make this table driven in second phase!!)
		begin
			select @order_load_d
efinition_id = order_load_definition_id
				 from order_load_status_definition
				 where order_load_status = 'TRANSCOMPLETE'
		end
	else
		begin  
		--if DR , put status to load complete pending SOA file
			select @order_load_definition_id = order_load_definition_id
				 from order_load_status_definition
				 where order_load_status = 'LOADCOMPLETE'
		end

	update 
		order_notification_status
	set 
		order_load_definition_id = @order_load_definition_id
	where 
		vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id

	select @response_code = 0,@message = 'order_notification_status update complete'	

	--If trans complete - call wrapper to insert/update ecommerce tables
	execute usp_process_customer_order @vendor_order_id, @vendor_id,  @system_user, @debug_flag,@response_code output,@message output
	
	if @response_code <> 0
		begin
			RAISERROR (@message, 11, 0)
		end

	---if the transaction is complete, archive the load table records
	execute usp_customer_order_load_archive @vendor_order_id, @vendor_id,@order_notification_status_id, @system_user, 
							     @response_code output,@message output
	
	if @response_code <> 0
		begin
			RAISERROR (@message, 11, 0)
		end

	
end  --end order notification status record exists
end try
begin catch

	select @order_load_error_definition_id = order_load_error_definition_id
		from order_load_error_definition
		where order_load_error = 'PROCESSCUSTOMERORDERFAIL'

	update 
		order_notification_status
	set 
		order_load_error_definition_id = @order_load_error_definition_id
	where 
		vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id

	--INSERT INTO AUDIT TABLE FOR ERROR TRACKING
	insert order_load_audit
	values (@vendor_order_id, @vendor_id, @response_code, @message, @insert_date, @system_user)
	
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;

GO
