Create  PROCEDURE usp_location_select 
 AS
/*	DATE		AUTHOR		REMARKS
	04/12/06	TBlazek		Initial creation.


	DESCRIPTION
		Return a list of locations for the "Create/Edit Spy Alert" UI
*/

SET NOCOUNT ON
Declare @return int
Select @return = 0

Select 	country_id,
	description
From lu_countries
where country_id > 0 --filter out 0, unknown


If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END



