-- =============================================================================
-- PROCEDURE: [dbo].[usp_LogError]
-- =============================================================================


/**********************************************************************
 * SP Name:  usp_LogError
 * Dependancy(s):   DBErrorLog, Application Event Log
 *
 * Purpose:  Centralized handling and logging of db errors.  Allows for 
 *			 logging to a table and/or event log/database log depending on
 *           need
 * 
 *
 * Changes Log:
 * Date					Author				Desc
 **********************************************************************
 * 8/1/2007 10:12am	Bob Jordan		    Initial Creation
 *
 */
 
create PROCEDURE [dbo].[usp_LogError](
	@log_type smallint = 1,  --0 = both database and event log, 1 = database, 2 = event log
	@ErrorDB nvarchar(128) = null
	)
AS
DECLARE @ErrorMessage NVARCHAR(4000)
DECLARE @ErrorSeverity INT
DECLARE @ErrorState INT
DECLARE @ErrorProcedure nvarchar(128)
DECLARE @ErrorLine INT
DECLARE @ErrorNumber INT
DECLARE @ErrorServer nvarchar(128)
DECLARE @ErrorUser nvarchar(128)
DECLARE @SQL varchar(8000)
set nocount on

	SELECT 
	@ErrorNumber = ERROR_NUMBER(),
	@ErrorSeverity = ERROR_SEVERITY(),
	@ErrorState = ERROR_STATE(),
	@ErrorProcedure = ERROR_PROCEDURE(),
	@ErrorLine = ERROR_LINE(),
	@ErrorMessage = ERROR_MESSAGE(),
	@ErrorServer = @@servername,
	@ErrorDB = isnull(@ErrorDB,db_name()),
	@ErrorUser = suser_name()

	if @log_type <= 1
		begin

			insert into [DBErrorlog]
			(ErrorNumber,
			ErrorSeverity,
			ErrorState,
			ErrorProcedure,
			ErrorLine,
			ErrorMessage,
			ErrorServer,
			ErrorDB,
			ErrorUser)
			Values(
			@ErrorNumber,
			@ErrorSeverity,
			@ErrorState,
			@ErrorProcedure,
			@ErrorLine,
			@ErrorMessage,
			@ErrorServer,
			@ErrorDB,
			@ErrorUser)
		
		end

	if @log_type = 1
		begin

		Set @ErrorMessage = 'Message has been logged to ' + db_name() + '..DBErrorLog' + Char(10) + @ErrorMessage

		RAISERROR (@ErrorMessage, 
				   @ErrorSeverity,
				   @ErrorState);
		end
	else
		begin
		Set @ErrorMessage = @ErrorMessage + char(10) + 
						'Error Number: ' + ltrim(rtrim(str(@ErrorNumber))) + char(10) + 
						'Procedure: ' + isnull(@ErrorProcedure,'N/A') + char(10) + 
						'Line: ' + ltrim(rtrim(Str(@ErrorLine))) + char(10) + 
						'Server: ' + @ErrorServer + char(10) + 
						'Database: ' + @ErrorDB + char(10) + 
						'User: ' + @ErrorUser

		RAISERROR (@ErrorMessage, 
				   @ErrorSeverity,
				   @ErrorState)
				   with Log;
		end
	
		
/*

Testing - Create procedure that will fail when executed

View entry in table to verify it collects failed info

*/

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mar_select_update_details]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_mar_select_update_details]

(
	@account_user_name varchar(100),
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2011-08-26	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

if (select @license_id) is NULL
	
	begin

		select m.insert_date, m.mar_name, t.mar_type_name, 
		case when l.mar_id is not NULL then 'mar license created' else 'mar license not created' end as mar_license_status, 
		isnull(l2.keycode,'') as keycode,
		case when u.mar_id is not NULL then 'mar user created' else 'mar user not created' end as mar_user_status,
		u.user_email, u.first_name, u.last_name, u.display_name, u.insert_date, s.mar_status_name,
		case when ua.account_id is not NULL then 'mar account user created' else 'mar account user not created' end as mar_account_user_status,
		a.account_user_name, a.password_hint, at.account_type_description, sa.account_status, a.email_opt_in
		from mar m
		left join mar_type t
			on m.mar_type_id = t.mar_type_id
		left join mar_license l
			on m.mar_id = l.mar_id
		left join license l2
			on l.license_id = l2.license_id
		left join mar_user u
			on m.mar_id = u.mar_id 
		left join mar_status s
			on u.mar_status_id = s.mar_status_id
		left join mar_user_license ul
			on u.mar_user_id = ul.mar_user_id
		left join mar_user_account ua
			on u.mar_user_id = ua.mar_user_id
		left join account a
			on ua.account_id = a.account_id
		left join account_type at
			on a.account_type_id = at.account_type_id
		left join account_status sa
			on a.account_status_id = sa.account_status_id
		where a.account_user_name = @account_user_name 

end
	else
	begin

		select m.insert_date, m.mar_name, t.mar_type_name, 
		case when l.mar_id is not NULL then 'mar license created' else 'mar license not created' end as mar_license_status, 
		isnull(l2.keycode,'') as keycode,
		case when u.mar_id is not NULL then 'mar user created' else 'mar user not created' end as mar_user_status,
		u.user_email, u.first_name, u.last_name, u.display_name, u.insert_date, s.mar_status_name,
		case when ua.account_id is not NULL then 'mar account user created' else 'mar account user not created' end as mar_account_user_status,
		a.account_user_name, a.password_hint, at.account_type_description, sa.account_status, a.email_opt_in
		from mar m
		left join mar_type t
			on m.mar_type_id = t.mar_type_id
		left join mar_license l
			on m.mar_id = l.mar_id
		left join license l2
			on l.license_id = l2.license_id
		left join mar_user u
			on m.mar_id = u.mar_id 
		left join mar_status s
			on u.mar_status_id = s.mar_status_id
		left join mar_user_license ul
			on u.mar_user_id = ul.mar_user_id
		left join mar_user_account ua
			on u.mar_user_id = ua.mar_user_id
		left join account a
			on ua.account_id = a.account_id
		left join account_type at
			on a.account_type_id = at.account_type_id
		left join account_status sa
			on a.account_status_id = sa.account_status_id
		where l2.license_id = @license_id

end

	end try

begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mar_update_mar]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_mar_update_mar]

(
		@prevx_mar_update_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-06-23	esmart		Initial creation.
	2011-08-16	esmart		General modifications
	2015-01-29	esmart		Account creation license registration

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@reference_id int,
			@mar_id int,
			@mar_name varchar(50),
			@mar_type_id tinyint, 
			@parent_mar_id int,
			@current_parent_mar_id int, 
			@license_id int, 
			@mar_user_id bigint, 
			@user_email varchar(100), 
			@user_password varchar(64), 
			@first_name nvarchar(225), 
			@last_name nvarchar(225), 
			@display_name nvarchar(225),
			@mar_user_type_id tinyint,

			@mar_status_id tinyint,
			@mar_relation_id int,
			@encryption_key_hash varchar(128),

			@admin_account_id int,
			@account_id int,
			@account_user_name varchar(100),
			@account_password varchar(64),
			@password_hint varchar(50), 
			@account_type_id tinyint, 
			@account_status_id tinyint,
			@parent_account_id int,
			@insert_by varchar(20),
			@keycode varchar(40),
			@WARN_opt_in tinyint,
			@email_opt_in tinyint,
			
			@customer_id int,
			@vendor_customer_code varchar(20),
			@capability_expiration_date datetime,
			
			@transaction_date datetime,
			@email_domain varchar(100),
			@response_code int,
			@message varchar(100)

	select @response_code = 0,
			@transaction_date = getdate()
			

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select parameters	
	select @mar_id = mar_id,
			@mar_user_id = mar_user_id,
			@mar_type_id = mar_type_id,
			@mar_name = mar_name,
			@parent_mar_id = parent_mar_id, 
			@license_id = license_id, 
			@mar_user_id = mar_user_id, 
			@user_email = user_email, 
			@user_password = user_password, 
			@first_name = first_name, 
			@last_name = last_name, 
			@display_name = display_name,
			@mar_status_id = isnull(mar_status_id,1),
			@encryption_key_hash = encryption_key_hash,
			@mar_user_type_id = mar_user_type_id
	from prevx_mar_update
	where prevx_mar_update_id = @prevx_mar_update_id

	-- 1.3)@keycode
	if @license_id is not null
		begin
			select @keycode	= keycode from license where license_id = @license_id
		end
	else
		-- 1.3.1) if @keycode is null grab the license_id from the mar_license
		begin
			select @license_id = m.license_id,
					 @keycode	= keycode
			from mar_license m
			inner join license l
				on m.license_id = l.license_id
			where m.mar_id = @mar_id
		end
	
	-- 1.4) mar_type
	if @mar_type_id = 0
		begin
			select @mar_type_id = mar_type_id from mar where mar_id = @mar_id
			if @mar_type_id = 0 or @mar_type_id is null begin select @mar_type_id = 5 end
		end

	-- 1.5) mar_user_type
	if @mar_user_type_id is null
		begin
			select @mar_user_type_id = 2
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) mar
	if @mar_id is null
		begin
		select response_code = - 210, message = 'no mar_id'
		return
		end

	if (select count(*) from mar where mar_id = @mar_id) > 0 
		-- 2.1.1) update mar
		begin
		--print '2.1.1) update mar'

		if (select count
(*) from mar where mar_id = @mar_id and (mar_name <> @mar_name or mar_type_id <> @mar_type_id or mar_status_id <> @mar_status_id)) > 0
			begin
			-- 2.1.1.1) insert audit
			insert into mar_audit(mar_id, mar_name, mar_type_id, mar_status_id, insert_date, modified_date, audit_date)
			select mar_id, mar_name, mar_type_id, mar_status_id, insert_date, modified_date, @transaction_date
			from mar
			where mar_id = @mar_id
	
			-- 2.1.1.2) update
			update mar
			set mar_name = @mar_name, mar_type_id = @mar_type_id, mar_status_id = @mar_status_id, modified_date = @transaction_date
			where mar_id = @mar_id
	
			end
		end
	else
		-- 2.1.2) insert mar
		begin
		--print '2.1.2) insert mar'
		insert into mar(mar_id, mar_name, mar_type_id, mar_status_id, insert_date, modified_date)
		values(@mar_id, @mar_name, @mar_type_id, @mar_status_id, @transaction_date, @transaction_date)
		end

	-- 2.2) mar_user
	if (select count(*) from mar_user where mar_user_id = @mar_user_id) > 0
		-- 2.2.1) update mar_user
		begin
		--print '2.2.1) update mar_user'
			if (select count(*) from mar_user where mar_user_id = @mar_user_id 
					and (user_email <> @user_email or user_password <> @user_password or mar_status_id <> @mar_status_id or mar_id <> @mar_id or first_name <> @first_name or last_name <> @last_name or display_name <> @display_name)) > 0
				begin
				-- 2.2.1.1) insert audit
				insert into mar_user_audit(mar_user_id, user_email, user_password, mar_status_id, mar_id, first_name, last_name, display_name, insert_date, modified_date, audit_date, mar_user_type_id)
				select mar_user_id, user_email, user_password, mar_status_id, mar_id, first_name, last_name, display_name, insert_date, modified_date, @transaction_date, mar_user_type_id
				from mar_user
				where mar_user_id = @mar_user_id
		
				-- 2.2.1.2) update
				update mar_user
				set user_email = @user_email, user_password = @user_password, mar_status_id = @mar_status_id, mar_id = @mar_id, first_name = @first_name, last_name = @last_name, display_name = @display_name, modified_date = @transaction_date
				where mar_user_id = @mar_user_id

				-- 2.2.1.3) @encryption_key_hash
				if (select count(*) from mar_user_ext where mar_user_id = @mar_user_id) > 0
					begin
					if @encryption_key_hash is not null
						begin
							update mar_user_ext
							set encryption_key_hash = @encryption_key_hash
							where mar_user_id = @mar_user_id
						end
					end
				else
					begin
					if @encryption_key_hash is not null
						begin
							insert into mar_user_ext(mar_user_id,encryption_key_hash)
							values(@mar_user_id,@encryption_key_hash)				
						end
					end
				end
			end
	else
		-- 2.2.2) insert mar_user
		begin
		if @mar_user_id <> 0 and @mar_user_id is not null
			begin
			--print '2.2.2) insert mar_user'
			insert into mar_user(mar_user_id, user_email, user_password, mar_status_id, mar_id, first_name, last_name, display_name, insert_date, modified_date, mar_user_type_id)
			values(@mar_user_id, @user_email, @user_password, @mar_status_id, @mar_id, @first_name, @last_name, @display_name, @transaction_date, @transaction_date, @mar_user_type_id)

			if @encryption_key_hash is not null
				begin
				insert into mar_user_ext(mar_user_id,encryption_key_hash)
				values(@mar_user_id,@encryption_key_hash)				
				end
			end
		end	

	-- 2.3) mar_license
		if (select count(*) from mar_license where mar_id = @mar_id and license_id = @license_id) = 0 and @license_id <> 0 and @license_id is not null
			begin
			insert into mar_license(mar_id, license_id) values(@mar_id, @license_id)
			end

	-- 2.4) mar_user_license
		if (select count(*) from mar_user_license where mar_user_id = @mar_user_id and license_id = @license_id) = 0 and @mar_user_id <> 0 and @license_id <> 0 and @license_id is not null
			begin
			insert into mar_user_license(mar_user_id, license_id) values(@mar_user_id, @license_id)
			end
		
	-- 2.5) mar_relation
		if @parent_mar_id is not null and @parent_mar_id <> 0
			begin
			-- 
2.5.1) check existing
			select @mar_relation_id = mar_relation_id, @current_parent_mar_id = parent_mar_id from mar_relation where child_mar_id = @mar_id

			if @mar_relation_id is null
			-- 2.5.2) insert
				begin
					insert into mar_relation(parent_mar_id,child_mar_id) 
					values(@parent_mar_id,@mar_id)
				end
			else
			-- 2.5.3) update
				begin
				if @current_parent_mar_id <> @parent_mar_id
					begin
					insert into mar_relation_audit(mar_relation_id, parent_mar_id, child_mar_id, insert_date, modified_date, audit_date)
					select mar_relation_id, parent_mar_id, child_mar_id, insert_date, modified_date, @transaction_date
					from mar_relation
					where mar_relation_id = @mar_relation_id

					update mar_relation
					set parent_mar_id = @parent_mar_id, modified_date = @transaction_date
					where mar_relation_id = @mar_relation_id
					end
				end
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) mar_user_account
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--select mar_user_id = @mar_user_id, license_id = @license_id

		if (select count(*) from mar_user_account where mar_user_id = @mar_user_id) > 0
		-- 3.1) update mar_user_account	
			begin
			select '3.1) update mar_user_account'
			-- 3.1.1) change user_name

			-- 3.1.2) change password

			-- 3.1.3) change first/last name

			-- 3.1.4) change license

			end
		else
		-- 3.2) insert mar_user_account
			--print '3.2) insert mar_user_account'
			begin
			if @mar_user_id is not null and @mar_user_id <> 0 and @mar_user_type_id <> 4
				begin
				--print '3.2.1) select current account info'
				-- 3.2.1) select current account info
				select @account_id = account_id, @account_password = account_password, @account_status_id = account_status_id
				from account 
				where account_user_name = @user_email
				
				if @account_id is null and @keycode is not null and @mar_status_id = 1
				-- 3.2.2) insert account
					begin
					
					select @capability_expiration_date = capability_expiration_date
					from mar_user_license u
					inner join license_category_license lcl
						on u.license_id = lcl.license_id
					inner join license_category lc
						on lcl.license_category_id = lc.license_category_id
					inner join license_capability c
						on u.license_id = c.license_id and c.capability_id = lc.base_capability_id
					where u.mar_user_id = @mar_user_id
			
					if @capability_expiration_date is null or @capability_expiration_date < getdate()
						begin 
						exec usp_prevx_insert_mar_update_archive @prevx_mar_update_id
						return			
						end

					--print '3.2.2) insert account'
--						select mar_status_id = @mar_status_id,account_id = @account_id,keycode = @keycode	
					-- 3.2.2.1) see if license has an admin account
					select @admin_account_id = a.account_id
					from account a
					inner join account_license al
						on a.account_id = al.account_id
					where al.license_id = @license_id and a.account_type_id = 1

					-- 3.2.2.2) does the user data map to an existing customer
					select @customer_id = 
						(select top 1 c.customer_id 
						from customer c
						inner join customer_email e
							on c.customer_id = e.customer_id and e.customer_email = @user_email and e.email_status_id = 1
						where c.first_name = @first_name and c.last_name = @last_name
						order by c.customer_id desc)
					
					if @customer_id is null and @first_name = '' and @last_name = ''
						begin
						select @customer_id = 
						(select top 1 c.customer_id 
						from customer c
						inner join customer_email e
							on c.customer_id = e.customer_id
						where e.customer_email = @user_email and e.email_status_id = 1
						order by c.customer_id des
c)
						end

					-- 3.2.2.3) insert new customer
					if @customer_id is null 
						begin
							insert into customer (first_name, last_name, opt_in)
							values(@first_name, @last_name, 1)

							select @customer_id  = scope_identity()

							if @user_email is not null 
								begin
								select @email_domain=SUBSTRING(@user_email,CHARINDEX('@',@user_email)+1,len(@user_email))

								insert into customer_email(customer_id,customer_email,email_status_id,email_domain) values(@customer_id,@user_email,1,@email_domain)
								end

							exec usp_customer_generate_customer_code @vendor_customer_code OUTPUT
							insert into vendor_customer(vendor_id, customer_id, vendor_customer_code) values (1,@customer_id,@vendor_customer_code) 

							update license 
							set customer_id = @customer_id
							where license_id = @license_id
						end

					-- 3.2.2.4) set account values
					select @password_hint = 'Prevx',
							@account_status_id = 0,
							@parent_account_id = case 
													when @admin_account_id is not null then @admin_account_id
													else null
												end,
							@account_type_id = case 
													when @admin_account_id is not null then 2
													else 1
												end,
							@insert_by = 'PrevxAPI',
							@WARN_opt_in = 0,
							@email_opt_in = 0

				-- 3.2.3) insert account
					exec usp_account_insert_account @user_email,@user_password,@password_hint,@account_type_id,@account_status_id,@parent_account_id,@insert_by,@keycode,@WARN_opt_in,@email_opt_in

					select @account_id = account_id from account where account_user_name = @user_email
					
					-- 3.2.3.1) update account status
					if @account_id is not null
						begin
						if @encryption_key_hash is not null
							begin
							insert into account_ext(account_id, encryption_key_hash)
							values(@account_id,@encryption_key_hash)
							end

						select @account_status_id = 1
						exec usp_account_update_account_status @account_id, @account_status_id
						
						end

					end	

			-- 3.3) insert mar_user_account
					if (@account_password = @user_password or @account_password is null) and @account_id is not null
						begin
						--print '3.3) insert mar_user_account'
						insert into mar_user_account(mar_user_id,account_id)
						values(@mar_user_id,@account_id)
						end
					else
						begin
						select 'passwords do not match!'
						end
				end
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) archive update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	exec usp_prevx_insert_mar_update_archive @prevx_mar_update_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_match_companyexceptions]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_match_companyexceptions]
@delta_flag CHAR(1)='Y'
AS
BEGIN
/*
	DATE			AUTHOR			REMARKS
	2021-08-25		psatish			Initial creation.

*/

SET NOCOUNT on
DECLARE
	@batch_size int = 80,
	@batch_start int,
	@batch_end int,
	@backfill_id int,
	@email_domain varchar(100),
	@company_name nvarchar(255),
	@address_1 nvarchar(255),
	@city nvarchar(130),
	@state nvarchar(2),
	@postal_code nvarchar(32),
	@country_id int,
	@loop_value int,
	@loop_max int,
	@email_domain_count INT,@id INT=1,@count int
--This would only be necessary if we have multi-email domain scenarios in the backfill data
declare @email_domains table (id int identity(1,1), email_domain varchar(100), email_domain_type_id tinyint) 
DECLARE @backfilltable TABLE
(
id INT IDENTITY(1,1) PRIMARY key,
backfillid INT
)
INSERT INTO @backfilltable
(
    backfillid
)
SELECT TOP 300  backfill_id from DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill
WHERE  Delta_flag='Y'  AND Ready_for_load='Pending'

select @count=MAX(id) FROM @backfilltable

WHILE @id<=@count
BEGIN
SELECT @backfill_id=backfillid FROM @backfilltable WHERE id=@id
select @company_name = bc.company_name, @address_1 = a.address_1, @city = a.city, @state = a.state, @postal_code = a.postal_code, @country_id = a.country_id
		from DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill bc
		left join DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_address_master_backfill a
		on a.sap_account_number = bc.sap_account_number
		where bc.backfill_id = @backfill_id

	insert into @email_domains(email_domain)
		select bce.email_domain
		from DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill b 
			inner join DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_email_domain_master_backfill bce
				on bce.sap_account_number = b.sap_account_number
		where b.backfill_id = @backfill_id

		select @email_domain_count = @@rowcount

		if @email_domain_count > 0
			begin
				select @loop_value = (select min(id) from @email_domains), @loop_max = (select max(id) from @email_domains)
				while @loop_value <= @loop_max
					begin
						select @email_domain = email_domain 
						from @email_domains
						where id = @loop_value

						update DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill
						set staging_company_id = m.company_id, company_match_type = m.company_match_type, exception_reason = m.exception_reason, exception_json = m.exception_json,
							is_blocked = iif(m.exception_reason is not null, 1, 0), blocked_reason = iif(m.exception_reason is not null, 'match exception', null)
		
					FROM dbo.fn_select_company_match(@company_name, @email_domain, @address_1, null, @city, @state, @postal_code, @country_id, null, null, null, null) m
						where backfill_id = @backfill_id
						

						select @email_domain = null, @loop_value = @loop_value + 1
					end
			end
		else
			begin
				select @email_domain = email_domain 
				from @email_domains
				where id = 1

				update DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill
				set staging_company_id = m.company_id, company_match_type = m.company_match_type, exception_reason = m.exception_reason, exception_json = m.exception_json,
					is_blocked = iif(m.exception_reason is not null, 1, 0), blocked_reason = iif(m.exception_reason is not null, 'match exception', null)
			
				from dbo.fn_select_company_match(@company_name, @email_domain, @address_1, null, @city, @state, @postal_code, @country_id, null, null, null, null) m
				where backfill_id = @backfill_id
			
			END
		
		update DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill
		SET Ready_for_load='Processed'
		WHERE Delta_flag='Y' AND backfill_id=@backfill_id

		delete @emai
l_domains
		select @backfill_id = null, @loop_value = null, @loop_max = null, @company_name = null, @email_domain = null, @address_1 = null, @city = null, @state = null, @postal_code = null, @country_id = null, @batch_start = @batch_start + 1
	


	SET @id=@id+1


END
END

GO
