CREATE PROCEDURE [dbo].[usp_message_campaign_delete_message_campaign_configuration]

(
	@message_campaign_id INT 
)

/*	
	DATE		AUTHOR		REMARKS
	2020-05-19	mrobbins	initial creation

	DESCRIPTION
	Clears data for campaign
*/

AS
	SET NOCOUNT ON 			

	DECLARE @response_code INT,
			@message VARCHAR(100)

	BEGIN TRY 

	-- 2.1) delete
	DELETE FROM message_campaign_configuration_message_campaign 
	WHERE message_campaign_id = @message_campaign_id
	
	END TRY 

	BEGIN CATCH 

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END 

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
