-- =============================================================================
CREATE PROCEDURE [dbo].[usp_message_campaign_insert_message_campaign_configuration]

(
	@message_campaign_id INT,
	@message_campaign_configuration_id tinyint, 
	@configuration_value varchar(500),
	@insert_by VARCHAR(20)= NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2020-05-19	mrobbins	Initial creation.
	2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968

	DESCRIPTION
	
*/

AS
	SET NOCOUNT ON				

	DECLARE	@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY
      IF @insert_by IS NULL
		BEGIN
			SELECT @insert_by = SUSER_SNAME()
		END

	-- 1.1) delete
	DELETE FROM message_campaign_configuration_message_campaign 
	WHERE message_campaign_id = @message_campaign_id 
		AND message_campaign_configuration_id = @message_campaign_configuration_id
	
	-- 1.2) insert
	INSERT INTO dbo.message_campaign_configuration_message_campaign
	(
	    message_campaign_id,
	    message_campaign_configuration_id,
	    configuration_value,
		insert_by,
		modified_by
	)
	VALUES
	(   @message_campaign_id,
	    @message_campaign_configuration_id,
	    @configuration_value,
		@insert_by,
		@insert_by)

	
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_campaign_select_app_store_status]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_message_campaign_select_app_store_status]
(
    @message_campaign_id INT
)
/*     
       DATE          AUTHOR        REMARKS
       2019-02-02    jnavarra      Initial creation

       DESCRIPTION
       select
*/
AS
    SET NOCOUNT ON;

    DECLARE
        @response_code INT,
        @message VARCHAR(100);

    BEGIN TRY

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 1.1) select message_campaign_app_store_status
        SELECT m.message_campaign_app_store_status_id, m.message_campaign_id, s.license_app_store_status_id AS app_store_status_id, s.license_app_store_status_description
            FROM dbo.message_campaign_app_store_status m
                INNER JOIN dbo.license_app_store_status s
                    ON m.app_store_status = s.license_app_store_status_id
        WHERE m.message_campaign_id = @message_campaign_id

    END TRY

    BEGIN CATCH
        SET @response_code=-200;
        SET @message=CASE WHEN @message IS NULL THEN 'select failed' ELSE @message END;
        DECLARE @DBName NVARCHAR(128);
        SET @DBName=DB_NAME();
        EXEC usp_LogError @ErrorDB=@DBName;
    END CATCH;

GO
