-- PROCEDURE: [dbo].[usp_message_campaign_select_email_message_transactional_value]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_message_campaign_select_email_message_transactional_value]

(
	@message_campaign_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2016-06-13	acoffel		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select message_campaign_license_renewal_status
	select e.email_message_transactional_value_id, v.message_campaign_id, e.email_message_transactional_value_description, t.message_value_type_name
	from email_message_transactional_value e
	inner join message_campaign_value v
		on e.email_message_transactional_value_id = v.value_id
	inner join message_value_type t
		on v.message_value_type_id = t.message_value_type_id
	where v.message_campaign_id = @message_campaign_id



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
