CREATE PROCEDURE [dbo].[usp_message_campaign_select_message_campaign_configuration]

(
	@status VARCHAR(10) = NULL 
)

/*	
	DATE		AUTHOR		REMARKS
	2020-05-19	mrobbins	Initial creation.

	DESCRIPTION
	
*/

AS
	SET NOCOUNT ON 				

	DECLARE	@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	IF @status is null 
		BEGIN
		SELECT @status = 'active'
		END

	SELECT message_campaign_configuration_id, 
		configuration_name, 
		status
	FROM message_campaign_configuration
	WHERE status = @status
	
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
