CREATE PROCEDURE [dbo].[usp_message_campaign_select_message_campaign_configurations]

(
	@message_campaign_id INT,
	@configuration_name varchar(50) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2020-05-19	mrobbins	Initial creation.

	DESCRIPTION
	
*/

AS
	SET NOCOUNT ON 			

	DECLARE	@response_code int,
			@message varchar(100)

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select partner_campaign
	select m.message_campaign_configuration_message_campaign_id, 
		c.message_campaign_configuration_id, 
		c.configuration_name, 
		m.configuration_value
	from message_campaign_configuration_message_campaign m
	inner join message_campaign_configuration c
		on m.message_campaign_configuration_id = c.message_campaign_configuration_id
	where m.message_campaign_id = @message_campaign_id and
		c.configuration_name = 
			CASE WHEN @configuration_name IS NULL THEN 
				c.configuration_name 
			ELSE @configuration_name END
	ORDER BY c.message_campaign_configuration_id
	
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
