CREATE PROCEDURE [dbo].[usp_message_insert_message_campaign]

(
		@message_campaign_name VARCHAR(65),
		@message_campaign_description VARCHAR(256),
		@message_campaign_class_id TINYINT,
		@message_campaign_enabled TINYINT,
		@message_campaign_start_date DATETIME,
		@message_campaign_end_date DATETIME,
		@message_measure_point_id TINYINT,
		@message_measure_days INT,
		@message_measure_end_days INT,
		@message_duration_days INT,
		@message_campaign_priority_id INT = NULL,
		@insert_by VARCHAR(20)= NULL,
		@message_campaign_id INT OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2010-12-08	esmart		Initial creation.
	2011-07-22	esmart		Add message_campaign_autorenewal
	2012-12-06	esamrt		Modify insert
	2018-05-25	mrobbins	extended message_campaign_name
	2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968
	2026-05-01	jberry		US-4774432 - Added sec 2.3 to insert message campaign priority

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
      IF @insert_by IS NULL
    BEGIN
        SELECT @insert_by = SUSER_SNAME()
    END
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	-- 2.1) insert message_campaign
		insert into message_campaign(message_campaign_name, message_campaign_description, message_campaign_class_id, message_campaign_enabled, message_campaign_start_date, message_campaign_end_date, insert_by, modified_by)
		values(@message_campaign_name, @message_campaign_description, @message_campaign_class_id, @message_campaign_enabled, @message_campaign_start_date, @message_campaign_end_date, @insert_by, @insert_by)

		select @message_campaign_id = scope_identity()

	-- 2.2) insert message_campaign_measure_point
		insert into message_campaign_measure_point(message_campaign_id, message_measure_point_id, message_measure_days, message_measure_end_days, message_duration_days, insert_by, modified_by)
		values(@message_campaign_id, @message_measure_point_id, @message_measure_days, @message_measure_end_days, @message_duration_days,@insert_by, @insert_by)

	-- 2.3) insert message_campaign_message_priority
		IF @message_campaign_priority_id IS NOT NULL
		BEGIN
			INSERT INTO dbo.message_campaign_message_priority
			(
				message_campaign_id,
				message_campaign_priority_id
			)
			VALUES
			(@message_campaign_id, @message_campaign_priority_id)
		END;	
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
