	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into message_content_display_ext(replace_tag, replace_string, rule_parameter, low_range, high_range, language_code, location_code)
	values(@replace_tag, @replace_string, @rule_parameter, @low_range, @high_range, @language_code, @location_code)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
