-- =============================================================================


CREATE PROCEDURE [dbo].[usp_message_insert_message_cycle]

(
	@message_cycle_description varchar(50), 
	@cycles int, 
	@cycle_duration_days int, 
	@cycle_limit_days int,
	@cycle_gap_days_list varchar(300),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-30	esmart		Initial creation.
	2013-01-14	esmart		Add check for duplicate name
	2016-02-04	acoffel		Bumped @cycle_gap_days_list

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@message_cycle_id int,
			@line_id int, 
			@cycle_id int

	begin try

	set @response_code = 0
	set @message = 'Successfully updated message cycle'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @cycle_limit_days
	if @cycle_limit_days = 0
		begin select @cycle_limit_days = null end

	-- 1.2) @message_cycle_description
	if (select count(*) from message_cycle where message_cycle_description = @message_cycle_description) > 0 
		begin
			select @response_code = -120, @message = 'Duplicate @message_cycle_description'
			--select response_code = @response_code, message = @message
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert message_cycle
	insert into message_cycle(message_cycle_description, cycles, cycle_duration_days, cycle_limit_days)
	values(@message_cycle_description, @cycles, @cycle_duration_days, @cycle_limit_days)

	select @message_cycle_id = scope_identity()

	-- 2.2) insert message_cycle_line
	declare @message_cycle_line table (cycle_id int, line_id int,cycle_gap_days int)

	select @line_id = 0, @cycle_id = 1

	while @cycles >= @cycle_id
		begin
		insert into @message_cycle_line(cycle_id, line_id) values(@cycle_id,@line_id)
		select @line_id = @line_id + 1, @cycle_id = @cycle_id + 1
		end
		
	insert into message_cycle_line(message_cycle_id,line_id,cycle_gap_days)
	select @message_cycle_id,
			line_id, 
			cycle_gap_days =  case
								when t.cycle_gap_days is null or t.cycle_gap_days = 0 then null
								else t.cycle_gap_days
							end
	from @message_cycle_line m
	left join (select cycle_id = interger_list_id, cycle_gap_days = integer_value from dbo.fn_integer_string_to_table(@cycle_gap_days_list)) t
		on m.cycle_id = t.cycle_id

	-- 2.3) return @message_cycle_id
	select message_cycle_id = @message_cycle_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
