-- PROCEDURE: [dbo].[usp_message_select_ipm_license_messages]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_select_ipm_license_messages]
    @message_campaign_id INT,
    @qualified_license_count INT OUTPUT
AS
/*
    DATE        AUTHOR              REMARKS
    2025-08-21  vgangatharan        https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4774430 
    DESCRIPTION:
    This procedure populates the qualified licenses for the given IPM campaign ID
    Dependency:
    This procedere will be invoked from PHP.
    2025-11-11  vgangatharan       https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5036237 
    DESCRIPTION:
    Modified procedure to filter email election,subscription and next bill date
    2026-02-23  vgangatharan	   https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5197072
    DESCRIPTION:
    Updated the procedure to handle cases where the subscription type value is NULL as well

*/
SET NOCOUNT ON;

DECLARE @inclusive INT,
        @license_renewal INT,
        @message_measure_point_id INT,
        @measure_days INT,
        @message_duration_days INT,
        @has_idp INT,
        @startdate DATE,
        @enddate DATE,
        @total_count INT,
        @row_count INT,
        @today DATE = CAST(GETDATE() AS DATE);

BEGIN TRY
    ---------------------------------------------------
    -- 1. Create temp tables
    ---------------------------------------------------
    IF OBJECT_ID('tempdb..#ipm_message_campaign_parameters') IS NOT NULL
        DROP TABLE #ipm_message_campaign_parameters;

    CREATE TABLE #ipm_message_campaign_parameters
    (
        message_campaign_id INT,
        license_seats INT,
        license_category_id INT,
        product_line_id INT,
        message_platform_id INT,
        capability_type_id INT,
        autorenewal_opt_id INT,
        message_email_opt_id INT,
        license_status_id INT,
        renewal_status INT,
        license_distribution_method_id INT
    );

    IF OBJECT_ID('tempdb..#ipm_message_license_candidates') IS NOT NULL
        DROP TABLE #ipm_message_license_candidates;

    CREATE TABLE #ipm_message_license_candidates
    (
        license_id INT,
        capability_activation_date DATE,
        capability_expiration_date DATE,
        keycode VARCHAR(40),
        license_distribution_method_id INT,
        subscription_type_id INT,
        message_campaign_id INT
    );

    IF OBJECT_ID('tempdb..#ipm_message_license_candidates_processed') IS NOT NULL
        DROP TABLE #ipm_message_license_candidates_processed;

    CREATE TABLE #ipm_message_license_candidates_processed
    (
        license_id INT,
        keycode VARCHAR(40),
        license_distribution_method_id INT,
        message_campaign_id INT,
        subscription_type_id INT,
        capability_activation_date DATE,
        capability_expiration_date DATE
    );

    DECLARE @ipm_message_campaign_disti_codes TABLE
    (
        message_campaign_id INT,
        license_distribution_method_id INT
    );
    DECLARE @ipm_message_allstate_dimension TABLE
    (
        message_campaign_id INT,
        has_account INT,
        has_wsa INT
    );
    DECLARE @IPM_APP_CONFIG TABLE
    (
        config_value NVARCHAR(100),
        config_key INT
    );

    ---------------------------------------------------
    -- 2. Campaign Config Data
    ---------------------------------------------------
    SET @inclusive =
    (
        SELECT TOP (1)
               inclusive
        FROM dbo.message_campaign_license_distribution_method
        WHERE message_campaign_id = @message_campaign_id
    );

    SELECT @li
cense_renewal = CASE
                                  WHEN COUNT(DISTINCT renewal_status) > 1 THEN
                                      2
                                  ELSE
                                      MIN(renewal_status)
                              END
    FROM dbo.message_campaign_renewal_status
    WHERE message_campaign_id = @message_campaign_id;

    --load config Data
    INSERT INTO @IPM_APP_CONFIG
    (
        config_value,
        config_key
    )
    SELECT f.[value],
           CAST(f.[key] AS INT)
    FROM dbo.fn_app_config_select_key_values('IPM_Campaign_Measures', 'IPM_MESSAGE_CAMPAIGNS') f;

    SELECT @total_count = config_key
    FROM @IPM_APP_CONFIG
    WHERE config_value = 'Qualifed_License_Count';

    SELECT @row_count = config_key
    FROM @IPM_APP_CONFIG
    WHERE config_value = 'Row_Count';

    ---------------------------------------------------
    -- 3. Populate Disti Code
    ---------------------------------------------------
    IF @inclusive = 1
    BEGIN
        INSERT INTO @ipm_message_campaign_disti_codes
        (
            message_campaign_id,
            license_distribution_method_id
        )
        SELECT message_campaign_id,
               license_distribution_method_id
        FROM dbo.message_campaign_license_distribution_method
        WHERE message_campaign_id = @message_campaign_id;
    END;
    ELSE
    BEGIN
        INSERT INTO @ipm_message_campaign_disti_codes
        (
            message_campaign_id,
            license_distribution_method_id
        )
        SELECT @message_campaign_id,
               ldm.license_distribution_method_id
        FROM dbo.license_distribution_method ldm
            LEFT JOIN dbo.message_campaign_license_distribution_method mcldm
                ON ldm.license_distribution_method_id = mcldm.license_distribution_method_id
                   AND mcldm.message_campaign_id = @message_campaign_id
        WHERE mcldm.message_campaign_id IS NULL;
    END;

    ---------------------------------------------------
    -- 4. Populate Message Campaign Parameters
    ---------------------------------------------------
    INSERT INTO #ipm_message_campaign_parameters
    SELECT mc.message_campaign_id,
           mcs.license_seats,
           mclc.license_category_id,
           mcpl.product_line_id,
           mcp.message_platform_id,
           mct.trial,
           mca.autorenewal_opt_id,
           mcee.message_email_opt_id,
           mcls.license_status_id,
           mcrs.renewal_status,
           mcd.license_distribution_method_id
    FROM dbo.message_campaign mc WITH (NOLOCK)
        JOIN dbo.message_campaign_seat mcs WITH (NOLOCK)
            ON mcs.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_license_category mclc WITH (NOLOCK)
            ON mclc.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_product_line mcpl WITH (NOLOCK)
            ON mcpl.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_platform mcp WITH (NOLOCK)
            ON mcp.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_platform mp WITH (NOLOCK)
            ON mp.message_platform_id = mcp.message_platform_id
        JOIN dbo.message_campaign_trial mct WITH (NOLOCK)
            ON mct.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_autorenewal mca WITH (NOLOCK)
            ON mca.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_email_election mcee WITH (NOLOCK)
            ON mcee.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_license_status mcls WITH (NOLOCK)
            ON mcls.message_campaign_id = mc.message_campaign_id
        JOIN dbo.message_campaign_contract_detail mccd WITH (NOLOCK)
            ON mccd.message_campaign_id = mc.message_campaign_id
        J
OIN dbo.message_campaign_renewal_status mcrs WITH (NOLOCK)
            ON mcrs.message_campaign_id = mc.message_campaign_id
        JOIN @ipm_message_campaign_disti_codes mcd
            ON mcd.message_campaign_id = mc.message_campaign_id
    WHERE mc.message_campaign_id = @message_campaign_id
          AND mc.message_campaign_enabled = 1
          AND mc.message_campaign_class_id = 3;

    ---------------------------------------------------
    -- 5. Populate License Data
    ---------------------------------------------------
    IF @license_renewal = 1
    BEGIN
        INSERT INTO #ipm_message_license_candidates
        (
            license_id,
            capability_activation_date,
            capability_expiration_date,
            keycode,
            license_distribution_method_id,
            subscription_type_id,
            message_campaign_id
        )
        SELECT DISTINCT
               ls.license_id,
               ls.capability_activation_date,
               ls.capability_expiration_date,
               ls.keycode,
               ls.license_distribution_method_id,
               ls.subscription_type_id,
               @message_campaign_id
        FROM dbo.license_summary ls WITH (NOLOCK)
            JOIN dbo.license_renewals lr WITH (NOLOCK)
                ON lr.license_id = ls.license_id
            JOIN #ipm_message_campaign_parameters mcp
                ON ls.license_distribution_method_id = mcp.license_distribution_method_id
                   AND ls.license_seats = mcp.license_seats
                   AND ls.license_category_id = mcp.license_category_id
                   AND ls.product_line_id = mcp.product_line_id
                   AND ls.autorenewal_opt_id = mcp.autorenewal_opt_id
                   AND ls.license_status_id = mcp.license_status_id
                   AND ls.opt_in = mcp.message_email_opt_id
                   AND mcp.capability_type_id = CASE
                                                    WHEN (ls.capability_type_id) IN ( 2, 3 ) THEN
                                                        1
                                                    ELSE
                                                        0
                                                END;
    END;
    ELSE IF @license_renewal = 0
    BEGIN
        INSERT INTO #ipm_message_license_candidates
        (
            license_id,
            capability_activation_date,
            capability_expiration_date,
            keycode,
            license_distribution_method_id,
            subscription_type_id,
            message_campaign_id
        )
        SELECT DISTINCT
               ls.license_id,
               ls.capability_activation_date,
               ls.capability_expiration_date,
               ls.keycode,
               ls.license_distribution_method_id,
               ls.subscription_type_id,
               @message_campaign_id
        FROM dbo.license_summary ls WITH (NOLOCK)
            LEFT JOIN dbo.license_renewals lr WITH (NOLOCK)
                ON lr.license_id = ls.license_id
            JOIN #ipm_message_campaign_parameters mcp
                ON ls.license_distribution_method_id = mcp.license_distribution_method_id
                   AND ls.license_seats = mcp.license_seats
                   AND ls.license_category_id = mcp.license_category_id
                   AND ls.product_line_id = mcp.product_line_id
                   AND ls.autorenewal_opt_id = mcp.autorenewal_opt_id
                   AND ls.license_status_id = mcp.license_status_id
                   AND ls.opt_in = mcp.message_email_opt_id
                   AND mcp.capability_type_id = CASE
                                                    WHEN (ls.capability_type_id) IN ( 2, 3 ) THEN
                                                        1
                                                    ELSE
                                                
        0
                                                END
        WHERE lr.license_id IS NULL;
    END;
    ELSE
    BEGIN
        INSERT INTO #ipm_message_license_candidates
        (
            license_id,
            capability_activation_date,
            capability_expiration_date,
            keycode,
            license_distribution_method_id,
            subscription_type_id,
            message_campaign_id
        )
        SELECT DISTINCT
               ls.license_id,
               ls.capability_activation_date,
               ls.capability_expiration_date,
               ls.keycode,
               ls.license_distribution_method_id,
               ls.subscription_type_id,
               @message_campaign_id
        FROM dbo.license_summary ls WITH (NOLOCK)
            JOIN #ipm_message_campaign_parameters mcp
                ON ls.license_distribution_method_id = mcp.license_distribution_method_id
                   AND ls.license_seats = mcp.license_seats
                   AND ls.license_category_id = mcp.license_category_id
                   AND ls.product_line_id = mcp.product_line_id
                   AND ls.autorenewal_opt_id = mcp.autorenewal_opt_id
                   AND ls.license_status_id = mcp.license_status_id
                   AND ls.opt_in = mcp.message_email_opt_id
                   AND mcp.capability_type_id = CASE
                                                    WHEN (ls.capability_type_id) IN ( 2, 3 ) THEN
                                                        1
                                                    ELSE
                                                        0
                                                END;
    END;

    ---------------------------------------------------
    -- 6. Populate Data based on measure points
    ---------------------------------------------------
    --mesaure_point_id,measure_days,message_duration_days
    SELECT @message_measure_point_id = MAX(message_measure_point_id),
           @measure_days = message_measure_days,
           @message_duration_days = message_duration_days
    FROM dbo.message_campaign_measure_point
    WHERE message_campaign_id = @message_campaign_id
    GROUP BY message_measure_days,
             message_duration_days;

   
    --calculate startdate and enddate
    SET @enddate = DATEADD(DAY, - (@measure_days), @today);
    SET @startdate = DATEADD(DAY, - (@message_duration_days + @measure_days), @today);

    --Populate Data
    IF EXISTS
    (
        SELECT 1
        FROM @IPM_APP_CONFIG
        WHERE config_value = 'Activation_Measure_Point'
              AND config_key = @message_measure_point_id
    )
    BEGIN

        SET @qualified_license_count =
        (
            SELECT COUNT(license_id)
            FROM #ipm_message_license_candidates
            WHERE capability_activation_date
            BETWEEN @startdate AND @enddate
        );

        IF @qualified_license_count < @total_count
        BEGIN
            INSERT INTO #ipm_message_license_candidates_processed
            (
                license_id,
                keycode,
                license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT license_id,
                   keycode,
                   license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   capability_activation_date,
                   capability_expiration_date
            FROM #ipm_message_license_candidates
            WHERE capability_activation_date
            BETWEEN @startdate AND @enddate
            ORDER BY capability_activation_date DESC;
        END;
        ELSE
        BEGIN
            INSERT INTO #ipm_message_license_
candidates_processed
            (
                license_id,
                keycode,
                license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT TOP (@row_count)
                   license_id,
                   keycode,
                   license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   capability_activation_date,
                   capability_expiration_date
            FROM #ipm_message_license_candidates
            WHERE capability_activation_date
            BETWEEN @startdate AND @enddate
            ORDER BY capability_activation_date DESC;
	
        END;

    END;
    ELSE IF EXISTS
    (
        SELECT 1
        FROM @IPM_APP_CONFIG
        WHERE config_value = 'Expiration_Measure_Point'
              AND config_key = @message_measure_point_id
    )
    BEGIN


        SET @qualified_license_count =
        (
            SELECT COUNT(license_id)
            FROM #ipm_message_license_candidates
            WHERE capability_expiration_date
            BETWEEN @startdate AND @enddate
        );

        IF @qualified_license_count < @total_count
        BEGIN
            INSERT INTO #ipm_message_license_candidates_processed
            (
                license_id,
                keycode,
                license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT license_id,
                   keycode,
                   license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   capability_activation_date,
                   capability_expiration_date
            FROM #ipm_message_license_candidates
            WHERE capability_expiration_date
            BETWEEN @startdate AND @enddate
            ORDER BY capability_expiration_date DESC;
        END;
        ELSE
        BEGIN
            INSERT INTO #ipm_message_license_candidates_processed
            (
                license_id,
                keycode,
                license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT TOP (@row_count)
                   license_id,
                   keycode,
                   license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   capability_activation_date,
                   capability_expiration_date
            FROM #ipm_message_license_candidates
            WHERE capability_expiration_date
            BETWEEN @startdate AND @enddate
            ORDER BY capability_expiration_date DESC;

        END;
    END;

    ELSE IF EXISTS
    (
        SELECT 1
        FROM @IPM_APP_CONFIG
        WHERE config_value = 'NextBill_Measure_Point'
              AND config_key = @message_measure_point_id
    )
    BEGIN
        SET @qualified_license_count =
        (
            SELECT COUNT(ld.license_id)
            FROM #ipm_message_license_candidates ld
                JOIN dbo.license_next_bill_date lnbd
                    ON lnbd.license_id = ld.license_id
            WHERE CAST(lnbd.next_bill_date AS DATE)
            BETWEEN @startdate AND @enddate
        );

        IF @qualified_license_count < @total_count
        BEGIN
            INSERT INTO #ipm_message_license_candidates_processed
            (
                license_id,
                keycode,
      
          license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT ld.license_id,
                   ld.keycode,
                   ld.license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   ld.capability_activation_date,
                   ld.capability_expiration_date
            FROM #ipm_message_license_candidates ld
                JOIN dbo.license_next_bill_date lnbd
                    ON lnbd.license_id = ld.license_id
            WHERE CAST(lnbd.next_bill_date AS DATE)
            BETWEEN @startdate AND @enddate
            ORDER BY lnbd.next_bill_date DESC;

        END;
        ELSE
        BEGIN
            INSERT INTO #ipm_message_license_candidates_processed
            (
                license_id,
                keycode,
                license_distribution_method_id,
                message_campaign_id,
                subscription_type_id,
                capability_activation_date,
                capability_expiration_date
            )
            SELECT TOP (@row_count)
                   ld.license_id,
                   ld.keycode,
                   ld.license_distribution_method_id,
                   @message_campaign_id,
                   subscription_type_id,
                   ld.capability_activation_date,
                   ld.capability_expiration_date
            FROM #ipm_message_license_candidates ld
                JOIN dbo.license_next_bill_date lnbd
                    ON lnbd.license_id = ld.license_id
            WHERE CAST(lnbd.next_bill_date AS DATE)
            BETWEEN @startdate AND @enddate
            ORDER BY lnbd.next_bill_date DESC;
        END;
    END;

	---------------------------------------------------
    -- 8. Remove campaigns that don't match @subscription_type_id
    ---------------------------------------------------

    IF EXISTS
    (
        SELECT 1
        FROM dbo.message_campaign_subscription_type AS mcst
        WHERE mcst.message_campaign_id = @message_campaign_id
    )
    BEGIN

        DELETE c
        FROM #ipm_message_license_candidates_processed c
        WHERE c.subscription_type_id IS NOT NULL
              AND NOT EXISTS
        (
            SELECT 1
            FROM message_campaign_subscription_type t
            WHERE t.message_campaign_id = @message_campaign_id
                  AND t.subscription_type_id = c.subscription_type_id
        );

    END;

    SELECT lp.license_id,
           lp.keycode,
           ldm.license_distribution_method_code,
           lp.capability_activation_date,
           lp.capability_expiration_date,
           @qualified_license_count AS qualified_license_count
    FROM #ipm_message_license_candidates_processed lp
        JOIN dbo.license_distribution_method ldm WITH (NOLOCK)
            ON ldm.license_distribution_method_id = lp.license_distribution_method_id;

    ---------------------------------------------------
    -- 9. All state filtering if enabled
    ---------------------------------------------------
    SELECT @has_idp = MAX(allstate.has_idp)
    FROM #ipm_message_license_candidates_processed lp
        LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate WITH (NOLOCK)
            ON lp.license_id = allstate.license_id;

    IF @has_idp = 1
    BEGIN
        INSERT INTO @ipm_message_allstate_dimension
        SELECT mc.message_campaign_id,
               COALESCE(has_account.dimension_value, 0),
               COALESCE(has_wsa.dimension_value, 0)
        FROM dbo.message_campaign mc
            LEFT JOIN dbo.message_campaign_allstate has_account
                ON has_account.message_campaign_id = mc.message_campaign_id
                   
AND has_account.dimension_type = 'has-account'
            LEFT JOIN dbo.message_campaign_allstate has_wsa
                ON has_wsa.message_campaign_id = mc.message_campaign_id
                   AND has_wsa.dimension_type = 'has-wsa'
        WHERE mc.message_campaign_id = @message_campaign_id;

        -- Remove licenses not matching Allstate logic
        DELETE f
        FROM #ipm_message_license_candidates_processed f
            LEFT JOIN dbo.vw_message_campaign_license_dimensions_allstate allstate WITH (NOLOCK)
                ON f.license_id = allstate.license_id
            LEFT JOIN @ipm_message_allstate_dimension ad
                ON f.message_campaign_id = ad.message_campaign_id
        WHERE ad.message_campaign_id IS NULL;
    END;

	---------------------------------------------------
    -- 10. Clean up temp tables
    ---------------------------------------------------
    DROP TABLE #ipm_message_campaign_parameters;

    DROP TABLE #ipm_message_license_candidates;

    DROP TABLE #ipm_message_license_candidates_processed;
END TRY
BEGIN CATCH
    DECLARE @DBName NVARCHAR(128);

    SET @DBName = DB_NAME();

    EXEC dbo.usp_LogError @ErrorDB = @DBName;

    RETURN;
END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_select_license_message_campaigns_platform]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_message_select_license_message_campaigns_platform]

(
	@license_id int,
	@message_platform_name varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-23	esmart		Initial creation.
	2016-05-02	mrobbins	added message_campaign_enabled = 1 to select
							added trial check against campaign
							added auto renewal opt status against campaign


	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@license_distribution_method_id int,
			@license_seats int,
			@license_category_id int,
			@product_line_id int,
			@message_platform_id tinyint,
			@capability_type_id tinyint,
			@autorenewal_opt_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) select license data
		select	@license_distribution_method_id = license_distribution_method_id,
				@license_seats = isnull(s.license_seats,1),
				@license_category_id = isnull(lcl.license_category_id,dbo.fn_GetLicenseCategoryId(@license_id)),
				@product_line_id = l.product_line_id,
				@capability_type_id = case when l.capability_type_id = 1 then 0
					when l.capability_type_id = 2 then 1 end,
				@autorenewal_opt_id = l.autorenewal_opt_id
		from license_summary l with (nolock)
		left join license_seat s with (nolock)
			on l.license_id = s.license_id
		left join license_category_license lcl with (nolock)
			on l.license_id = lcl.license_id
		where l.license_id = @license_id

		-- 1.2) @message_platform_name
		select @message_platform_id = message_platform_id from message_platform where massage_platform_name = @message_platform_name	
		
		-- 1.3) select campaigns
		
		declare @message_campaign table (message_campaign_id int)	

		-- 2.4.1) get campaigns matching distribution methods
		insert into @message_campaign(message_campaign_id) 
		select message_campaign_id from message_campaign with (nolock)
		except
		select message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id = @license_distribution_method_id and inclusive = 0
		except
		(select message_campaign_id from message_campaign with (nolock)
		intersect 
		select distinct message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id <> @license_distribution_method_id and inclusive = 1
		except
		select distinct message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id = @license_distribution_method_id and inclusive = 1)

		select c.message_campaign_id, c.message_campaign_name, c.message_campaign_description
		from message_campaign c
		inner join message_campaign_class cc
			on c.message_campaign_class_id = cc.message_campaign_class_id
		inner join message_campaign_seat s
			on c.message_campaign_id = s.message_campaign_id
		inner join message_campaign_license_category lc
			on c.message_campaign_id = lc.message_campaign_id
		inner join message_campaign_platform p
			on c.message_campaign_id = p.message_campaign_id
		inner join @message_campaign mc
			on c.message_campaign_id = mc.message_campaign_id
		inner join message_campaign_product_line pl
			on c.message_campaign_id = pl.message_campaign_id
		inner join message_campaign_trial t
			on c.message_campaign_id = t.message_campaign_id
		inner join message_campaign_autorenewal mca
r
			on c.message_campaign_id = mcar.message_campaign_id
		where p.message_platform_id = @message_platform_id and 
			lc.license_category_id = @license_category_id and
			s.license_seats = @license_seats and 
			pl.product_line_id = @product_line_id and
			t.trial = @capability_type_id and
			mcar.autorenewal_opt_id = @autorenewal_opt_id and
			c.message_campaign_enabled = 1

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_select_license_message_content]
-- =============================================================================

 CREATE PROCEDURE [dbo].[usp_message_select_license_message_content]

(
		@message_campaign_id int,
		@language_code varchar(2) = null,
		@location_code varchar(3) = null		
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-24	esmart		Initial creation

	DESCRIPTION
	select discount
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@message_date datetime,
			@keycode_alias varchar(40)

	select @message_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) 
	if @language_code is null
		begin
		select @language_code = 'EN', @location_code = 'USA'
		end

	-- 1.2) set up table variable @message_campaign
	declare @message_campaign table (message_campaign_id int, start_date datetime NULL,end_date datetime NULL,message_content_id int NOT NULL,offer_tagline nvarchar(4000) NULL,offer_body nvarchar(4000) NULL,offer_button nvarchar(4000) NULL,image_url varchar(500) NULL,language_code varchar(2) NOT NULL,location_code varchar(3) NOT NULL,message_action varchar(50) NULL, symbol_utf8 nvarchar(10),discount money)	

	insert into @message_campaign(message_campaign_id, start_date, end_date, message_content_id, offer_tagline, offer_body, offer_button, image_url, language_code, location_code, message_action,symbol_utf8,discount)
	select m.message_campaign_id, m.message_campaign_start_date, m.message_campaign_end_date, mc.message_content_id, d.offer_tagline, d.offer_body, d.offer_button, d.image_url, d.language_code, d.location_code, c.message_action, 
		cu.symbol_utf8,
		discount = case  
					when i.cart_discount_method_id = 3 then round(i.discount,0)
					when id.discount is null then i.discount 
					else id.discount 
				end
	from message_campaign m
	inner join message_campaign_content mc
		on m.message_campaign_id = mc.message_campaign_id
	inner join message_content c
		on c.message_content_id = mc.message_content_id
	inner join message_content_display d
		on c.message_content_id = d.message_content_id and d.language_code = @language_code-- and d.location_code = @location_code
	left join message_campaign_cart_discount cd
		on mc.message_campaign_id = cd.message_campaign_id
	left join cart_discount_item i
		on cd.cart_discount_id = i.cart_discount_id
	left join cart_discount_item_discount id
		on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
	left join currency cu
		on id.currency_id = cu.currency_id
	where m.message_campaign_id = @message_campaign_id

	--select * from @message_campaign
	
--select convert(varchar(5),discount), symbol_utf8, replace(offer_tagline,'<$dis>',symbol_utf8+convert(varchar(5),discount)), * from @message_campaign

	-- 1.3) replace wild card

	-- 1.3.1) discount <$dis>
		update @message_campaign
		set offer_tagline = case 
								when offer_tagline like '%<$dis>%' then replace(offer_tagline,'<$dis>',symbol_utf8+convert(varchar(10),discount))
								else offer_tagline
							end, 
			offer_body = case 
								when offer_body like '%<$dis>%' then replace(offer_body,'<$dis>',symbol_utf8+convert(varchar(10),discount))
								else offer_body
							end,
			offer_button = case 
								when offer_button like '%<$dis>%' then replace(offer_button,'<$dis>',symbol_utf8+convert(varchar(10),discount))
								else offer_button
							end

	-- 1.3.2) <end_date> 
		update @message_campaign
		set offer_taglin
e = case 
								when offer_tagline like '%<end_date>%' then replace(offer_tagline,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
								else offer_tagline
							end, 
			offer_body = case 
								when offer_body like '%<end_date>%' then replace(offer_body,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
								else offer_body
							end, 
			offer_button = case 
								when offer_button like '%<end_date>%' then replace(offer_button,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
								else offer_button
							end

	-- 1.3.3) <end_date> 
		update @message_campaign
		set offer_tagline = case 
								when offer_tagline like '%<%dis>%' then replace(offer_tagline,'<%dis>',convert(varchar(2),convert(int,discount)))
								else offer_tagline
							end,
			offer_body = case 
								when offer_body like '%<%dis>%' then replace(offer_body,'<%dis>',convert(varchar(2),convert(int,discount)))
								else offer_body
							end,
			offer_button = case 
								when offer_button like '%<%dis>%' then replace(offer_button,'<%dis>',convert(varchar(2),convert(int,discount)))
								else offer_button
							end

	select *
	from @message_campaign
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_select_license_messages]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_message_select_license_messages]

(
       @keycode VARCHAR(40),
       @message_platform_name_list VARCHAR(200),
       @language_code VARCHAR(2) = NULL,
       @location_code VARCHAR(3) = NULL,
       @show_all TINYINT = 0
)

/*     
       DATE                 AUTHOR        REMARKS
       2013-08-23           esmart        Initial creation
       2013-10-01           esmart        Include @location_code in content lookup
       2013-10-22           esmart        Add @autorenewal_opt_id to fn_message_select_message_content_image
       2013-11-20           esmart        Remove cycle rows that go beyond end_date
       2014-03-12           acoffel       Extend seat enforcement into SP
       2014-09-10           acoffel       Added Modify 02 
       2014-11-06           acoffel       Added Agent Status
       2015-03-09           acoffel       Added transactional
       2015-04-23           acoffel       consolidated agent behavior into one location
       2015-06-28           acoffel       under utilization
       2015-09-04           mrobbins      adding code for trigger for email campaign for security summary
       2015-10-27           mrobbins      added trap for duplicate exact_target_batch inserts
       2015-12-15			acoffel		  fix bug associated with product IPM issues in oc_200 call and clean up
	   2016-01-06			acoffel		  Percent discount fix
	   2016-04-05			acoffel		  Renewal Status
	   2016-10-13			acoffel		  Portal Support
	   2017-02-08			acoffel		  pointed @max_threats_removed at license_scan_license
	   2017-06-22			acoffel		  Security Summary exclusion
	   2017-06-22			acoffel		  Days remaining support
	   2017-07-12			acoffel		  S2 6 month Security Summary
	   2017-09-06			acoffel		  Change max threats handling
	   2020-04-02			mrobbins	  removed security summary email insert waterbears-236
	   2020-07-09			wbarton		  Fixing and issue in 2.3.5 that causes offer_body to be returned improperly to the api
	   2021-01-26			mrobbins	  Updated @devices to default to 0 if null and “if @devices = 1” to “if @devices <= 1” AXIOM-2376
	   2023-09-22			schindar	  ecom-737. Added All state filtering logic 
	   2024-01-26			schindar	  ECOM-3277 - Added logic to filter based on product line. Also added logic for legacy product lines 1 and 6.
	   2024-04-04			schindar	  ECOM-2403 - Next bill date changes for Zoura
       2026-04-20           vgangatharan  https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5355007 -- Process Date Change logic, Inactive Explicit
                                          Campaign filtering.
	   2026-05-08			jberry		  US-4756862 - Added sec 3.2.1 to implement priority-based IPM conflict resolution for @show_all = null senario

	   DESCRIPTION
	   Retrieves targeted marketing and transactional messages for software licenses based on license attributes and active campaign eligibility.
	   The procedure evaluates license properties (seats, category, product line, trial/renewal status), 
	   filters matching runtime campaigns against dimension tables, assembles localized content with dynamic token replacement, 
	   and applies priority-based conflict resolution to return the highest-priority active message for display.
		
	   RUN CONTEXT
	   - Invoked by external messaging API and CSI for real-time message retrieval
	   - Executes under READ UNCOMMITTED isolation level for performance
	   - Supports both current-active messages and historical/future messages via @show_all parameter
	   - Includes built-in error logging to usp_LogError on failure
		
	   HIGH-LEVEL FLOW		
	   1) Validate and lookup license
	   - Verify keycode format (must be 20 chara
cters)
	   - Retrieve license from license_summary; redirect to ecommerce DB if not found
	   - Escape processing for enterprise product lines (55, 300)
	   2) Extract license context
	   - Load license metadata: seats, category, product line, trial status, renewal status
	   - Calculate subscription days, days remaining, active devices
	   - Retrieve AllState account dimensions and next billing date
	   3) Select matching campaigns
	   - Inner join 12+ campaign dimension tables to find eligible campaigns
	   - Filter by: category, seats, product line, trial/renewal/subscription status, email opt-in, contract details
	   - Apply AllState account/WSA filtering if IDP-enabled
	   - Exclude distribution method-restricted campaigns
	   4) Assemble localized content
	   - Join campaign content and display records using language/location codes
	   - Retrieve message metadata: tray state, transactional flag, agent state
	   - Link discount and currency data
	   5) Apply dynamic value replacement
	   - Replace tokens: <$dis> (discount), <days> (remaining), <end_date>, device usage, malware counts
	   - Filter security campaigns if not Sky-licensed
	   6) Rank and return results
	   - If @show_all = 1: Return all eligible campaigns unranked, ordered by date
	   - If @show_all = 0: Rank by campaign priority ID > transactional flag > process date; return rank-1 only
		 
	   PARAMETERS
	   Parameter                    Type            Default     Purpose
	   @keycode                     VARCHAR(40)     Required    Unique license identifier (20-char format)
	   @message_platform_name_list  VARCHAR(200)    Required    Comma-delimited platforms (email, tray, ui, product)
	   @language_code			    VARCHAR(2)      NULL        ISO language code for content localization
	   @location_code			    VARCHAR(3)      NULL        ISO location/country code for content localization
	   @show_all					TINYINT         0           1 = all campaigns; 0 = current active only (with priority ranking)

	   DEPENDENCIES
	   Procedures
	   - dbo.usp_LogError - Error logging and database context capture
	   Functions
	   - dbo.fn_char_string_to_table - Parses comma-delimited platform list
	   - dbo.fn_message_select_message_campaign_cart_discount - Retrieves discount for campaign/subscription
	   - dbo.fn_message_select_message_content_image - Resolves image URL based on renewal state
	   - dbo.getConnection - Returns connection string to ecommerce database
*/

AS
       SET NOCOUNT ON                           

       DECLARE       @license_id INT,
                     @customer_id INT,
                     @license_distribution_method_id INT,
                     @license_seats INT,
                     @license_category_id INT,
                     @product_line_id INT,
                     @capability_type_id TINYINT,
                     @trial TINYINT,
                     @autorenewal_opt_id TINYINT,
                     @opt_in INT,
                     @activity_date DATE,
                     @devices INT,
                     @devices_str VARCHAR(10),
                     @activation_date DATETIME,
                     @expiration_date DATETIME,
                     @license_key VARCHAR(36),
                     @run_date DATETIME,
					 @term_exception_check BIT,
					 @subscription_days INT,
                     @months INT,
                     @license_status_id INT,
                     @contract_detail_update INT,
                     @max_threats_removed BIGINT,
					 @days_remaining INT,
					 @sky_check BIT,
                     @subscription_id INT,
                     @subscription_type_id INT,
					 @renewal_status TINYINT,
                     @response_code INT,
                     @message VARCHAR(100),
                     @dbconnect VARCHAR(50),
                     @sql NVARCHAR(MAX),
					 @has_idp TINYINT,
					 @has_account TINYINT,
					 @has_wsa TINYINT,
					 @next_bill_date DATETIME

       BEGIN TRY

       SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) select
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              
              SELECT @run_date = GETDATE()
              SELECT @months = -7

              -- 1.0) blank keycode
              IF @keycode = '' OR @keycode IS NULL OR LEN(@keycode) <> 20
                     BEGIN
                     RETURN
                     END

              -- 1.1) select license data
              SELECT @license_id = ls.license_id,
                           @license_distribution_method_id = ls.license_distribution_method_id,
                           @license_seats = ls.license_seats,
                           @license_category_id = ls.license_category_id,
                           @product_line_id = ls.product_line_id,
                           @capability_type_id = ls.capability_type_id,
                           @activation_date = ls.capability_activation_date,
                           @expiration_date = ls.capability_expiration_date,
                           @license_key = ls.license_key,
                           @subscription_id = ls.subscription_id,
                           @subscription_type_id = ls.subscription_type_id,
                           @autorenewal_opt_id = ls.autorenewal_opt_id,
                           @opt_in = ls.opt_in,
                           @license_status_id = ls.license_status_id,
                           @contract_detail_update = CASE WHEN ls.contract_detail_update = 1 THEN 1 ELSE 0 END,
						   @days_remaining = DATEDIFF(dd,GETDATE(),ls.capability_expiration_date),
						   @subscription_days = DATEDIFF(dd,ls.capability_activation_date,ls.capability_expiration_date),
						   @has_idp = ISNULL(allstate.has_idp,0),
						   @has_account =ISNULL(allstate.has_account,0),
						   @has_wsa =ISNULL(allstate.has_wsa,0),
						   @next_bill_date = ISNULL(lnbl.next_bill_date,ls.capability_expiration_date)	
              FROM dbo.license_summary ls
			  LEFT OUTER JOIN  dbo.vw_message_campaign_license_dimensions_allstate allstate
			  ON allstate.license_id = ls.license_id
			  LEFT OUTER JOIN dbo.license_next_bill_date lnbl
			  ON lnbl.license_id = ls.license_id
              WHERE ls.keycode = @keycode OR ls.keycode_alias = @keycode

			

			-- 1.2) do home run to ecommerce
              IF @license_id IS NULL
                     BEGIN
                           SELECT @dbconnect=dbo.getConnection('ecommerce')
                           SELECT @sql ='exec ' +@dbconnect + '.dbo.usp_message_select_license_messages ''' + @keycode + ''','+'''' + @message_platform_name_list + ''',''' + @language_code +''',''' + @location_code +''','+ CONVERT(varchar(10),@show_all)
                           --print @sql 
                           EXEC sp_executesql @sql    
                           RETURN
                     END
              
			  -- Update @product_line_id for legacy keycodes
			 SET @product_line_id = CASE
                           WHEN @product_line_id = 1
                                AND @license_category_id IN
                                    (
                                        SELECT license_category_id
                                        FROM dbo.license_category_product_line
                                        WHERE product_line_id = 100
                                    ) THEN
                               100
                           WHEN @product_line_id = 6
                                AND @license
_category_id IN
                                    (
                                        SELECT license_category_id
                                        FROM dbo.license_category_product_line
                                        WHERE product_line_id = 200
                                    ) THEN
                               200
                           ELSE
                               @product_line_id
                       END;
                
              -- 1.2.5) escape out of sp if product_line '300 Webroot Secure Anywhere Business' or '55 Mobile Business'
              IF @product_line_id IN (55,300)
                     BEGIN
                           DECLARE @enterprise_escape TABLE ([license_message_id] [TINYINT],[keycode] [TINYINT], [license_id] [TINYINT], [license_message_key] [TINYINT], [process_date] [TINYINT],
                           [end_date] [TINYINT], [message_campaign_id] [TINYINT], [message_platform_id] [TINYINT], [massage_platform_name] [TINYINT], [serial_number] [TINYINT], [contract_id] [TINYINT],
                           [message_content_display_id] [TINYINT], [offer_tagline] [TINYINT], [offer_body] [TINYINT], [offer_button] [TINYINT], [language_code] [TINYINT], [location_code] [TINYINT],
                           [symbol_utf8] [TINYINT], [discount] [TINYINT], [message_content_id] [TINYINT], [message_action] [TINYINT], [image_url] [TINYINT], [message_url] [TINYINT], tray_state [TINYINT],
                           transactional [TINYINT], agent_state [TINYINT])
                           SELECT license_message_id, keycode, license_id, license_message_key, process_date, end_date, message_campaign_id, message_platform_id, 
                           massage_platform_name, serial_number, contract_id, message_content_display_id, offer_tagline, offer_body, 
                           offer_button, language_code, location_code, symbol_utf8, discount, message_content_id, message_action, image_url, message_url, tray_state,
                           transactional, agent_state
                           FROM @enterprise_escape
                     RETURN
                     END
              
              -- 1.3) @max_threats_removed
              SELECT @max_threats_removed = CASE WHEN bad_scans >= 1000 THEN 1000 ELSE bad_scans END FROM dbo.license_scan_license WHERE license_id = @license_id

              -- 1.3.1) @devices
              SELECT @devices = devices FROM dbo.license_usage_license WHERE license_id = @license_id	  
			  SET @devices = ISNULL(@devices,0)


			  -- 1.3.2) set @renewal_status value
			 SELECT @renewal_status = CASE WHEN COUNT(license_id) > 0 THEN 1 ELSE 0 END FROM dbo.license_renewals WHERE license_id = @license_id

              -- 1.4) @trial 
              SELECT @trial = CASE WHEN @capability_type_id IN (2,3) THEN 1 ELSE 0 END
              -- select run_date = @run_date, expiration_date = @expiration_date, license_distribution_method_id = @license_distribution_method_id, license_seats = @license_seats, license_category_id = @license_category_id, product_line_id = @product_line_id
              
			  -- 1.5) sky_license_activity check
              SELECT @sky_check = CASE WHEN COUNT(license_id) > 0 THEN 1 ELSE 0 END FROM dbo.sky_license WHERE license_id = @license_id

			  -- 1.6) S2 6 month check
			  SELECT @term_exception_check = CASE WHEN @subscription_days BETWEEN 135 AND 210 THEN 1 ELSE 0 END
			
              ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              -- 2.) select campaigns
              ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			  
              -- 2.2) get campaigns
 
             DECLARE @message_campaigns TABLE (message_source VARCHAR(20), message_campaign_id INT,message_campaign_start_date DateTime, message_campaign_name VARCHAR(65), message_campaign_description VARCHAR(256), message_platform_id TINYINT, message_platform_name VARCHAR(50), message_cycle_id INT, process_date DATETIME, end_date DATETIME, message_key VARCHAR(36), license_message_id INT, message_content_id INT, cart_discount_id INT)

              INSERT INTO @message_campaigns(message_source, message_campaign_id,message_campaign_start_date,message_campaign_name, message_campaign_description, message_platform_id, message_platform_name, message_cycle_id, process_date, end_date,message_key, cart_discount_id)
              SELECT message_source = 'runtime', c.message_campaign_id,c.message_campaign_start_date,c.message_campaign_name, c.message_campaign_description, 
                     mp.message_platform_id,
                     mp.massage_platform_name,
                     p.message_cycle_id,
                     m.process_date,
                     m.end_date,
                     license_key = @license_key,
                     cart_discount_id = [dbo].[fn_message_select_message_campaign_cart_discount](c.message_campaign_id,@subscription_id)
              FROM dbo.message_campaign c
              INNER JOIN dbo.message_campaign_seat s
                     ON c.message_campaign_id = s.message_campaign_id
              INNER JOIN dbo.message_campaign_license_category lc
                     ON c.message_campaign_id = lc.message_campaign_id
              INNER JOIN dbo.message_campaign_platform p
                     ON c.message_campaign_id = p.message_campaign_id
              inner join dbo.message_platform mp
                     on p.message_platform_id = mp.message_platform_id
              inner join dbo.message_campaign_trial ct
                     on c.message_campaign_id = ct.message_campaign_id
              inner join dbo.message_campaign_autorenewal a
                     on c.message_campaign_id = a.message_campaign_id
              inner join dbo.message_campaign_email_election e
                     on c.message_campaign_id = e.message_campaign_id
              inner join dbo.message_campaign_license_status st
                     on c.message_campaign_id = st.message_campaign_id
              inner join dbo.message_campaign_contract_detail cd
                     on c.message_campaign_id = cd.message_campaign_id
			  inner join dbo.message_campaign_renewal_status rs 
					 on c.message_campaign_id = rs.message_campaign_id
			  inner join dbo.message_campaign_subscription_days sd
					on c.message_campaign_id = sd.message_campaign_id				
              inner join (select mp.message_campaign_id, 
                                                --process_date = dateadd(dd,mp.message_measure_days,@expiration_date), 
                                                --end_date = dateadd(dd,mp.message_measure_end_days,@expiration_date)
                                                process_date = case
                                                              when mp.message_measure_point_id = 1 then dateadd(dd,mp.message_measure_days,@activation_date)
                                                              when mp.message_measure_point_id = 2 and mp.message_measure_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@expiration_date)),@expiration_date)),@expiration_date)
                                                              when mp.message_measure_point_id = 2 and mp.message_measure_days <> -180 then dateadd(dd,mp.message_measure_days,@expiration_date)
															  when mp.message_measure_point_id = 7 and mp.message_measure_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@next_bill_date)),@next_bill_date)),@next_bill_date)
                                                              when mp.message_measure
_point_id = 7 and mp.message_measure_days <> -180 then dateadd(dd,mp.message_measure_days,@next_bill_date)
                                                              when mp.message_measure_point_id = 4 then dateadd(dd,mp.message_measure_days,@activation_date)
															end,
                                                end_date = case
                                                              when mp.message_measure_point_id = 1 then dateadd(dd,mp.message_measure_days+mp.message_duration_days,@activation_date)
                                                              when mp.message_measure_point_id = 2 then dateadd(dd,mp.message_measure_days+mp.message_duration_days,@expiration_date)
															  when mp.message_measure_point_id = 7 then dateadd(dd,mp.message_measure_days+mp.message_duration_days,@next_bill_date)
                                                              when mp.message_measure_point_id = 4 and mp.message_measure_end_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@expiration_date)),@expiration_date)),@expiration_date)
                                                              when mp.message_measure_point_id = 4 and mp.message_measure_end_days <> -180 then dateadd(dd,mp.message_measure_end_days,@expiration_date)
															end
                                  from dbo.message_campaign_measure_point mp) m
                                   on p.message_campaign_id = m.message_campaign_id

              inner join dbo.message_campaign_product_line pl
              on c.message_campaign_id = pl.message_campaign_id 
              where mp.message_platform_id in (2,3,5,6) and --mp.massage_platform_name in (select char_value from dbo.fn_char_string_to_table(@message_platform_name_list)) and
                     lc.license_category_id = @license_category_id and
                     s.license_seats = @license_seats and 
                     pl.product_line_id = @product_line_id
                     AND ct.trial = @trial and
					 rs.renewal_status = @renewal_status and
					 sd.subscription_days = @term_exception_check and
                     a.autorenewal_opt_id = @autorenewal_opt_id and 
                     e.message_email_opt_id = @opt_in and
                     c.message_campaign_enabled = 1 and
                     c.message_campaign_class_id = 3 -- runtime
                     and st.license_status_id = @license_status_id
                     and cd.contract_detail_update = @contract_detail_update
                     and (c.message_campaign_start_date < getdate() and (getdate() <= c.message_campaign_end_date or c.message_campaign_end_date is null))
					 and c.message_campaign_id in (select message_campaign_id from dbo.message_campaign
                                                                     except
                                                                     select message_campaign_id 
                                                                     from dbo.message_campaign_license_distribution_method
                                                                     where license_distribution_method_id = @license_distribution_method_id and inclusive = 0
                                                                     except
                                                                     (select message_campaign_id from dbo.message_campaign
                                                                     intersect 
                                                                     select message_campaign_id 
                                                                     from dbo.message_campaign_license_distribution_method
                                                                     where license_distribution_method_id <> @license_distribution_method_id and inclusive = 1
                                                                     except
       
                                                              select message_campaign_id 
                                                                     from dbo.message_campaign_license_distribution_method
                                                                     where license_distribution_method_id = @license_distribution_method_id and inclusive = 1)); 

																	 
              -- 2.2.1) filter on AllState logic
              IF @has_idp = 1
              BEGIN
                     DECLARE @message_campaigns_allstate TABLE ( message_campaign_id INT,hasaccount TINYINT,haswsa TINYINT)
                     INSERT INTO @message_campaigns_allstate(message_campaign_id,hasaccount,haswsa)
                     SELECT message_campaign_id,hasaccount,haswsa
                     from
                     (SELECT mc.message_campaign_id,COALESCE(hasaccount.dimension_value,0) AS hasaccount ,COALESCE(haswsa.dimension_value,0) AS haswsa
                              FROM @message_campaigns mc
                                  LEFT OUTER JOIN
                                  (
                                      SELECT dimension_value AS dimension_value,
                                             message_campaign_id
                                      FROM dbo.message_campaign_allstate
                                      WHERE dimension_type = 'has-account'
                                  ) hasaccount
                                      ON hasaccount.message_campaign_id = mc.message_campaign_id
                                  LEFT OUTER JOIN
                                  (
                                      SELECT dimension_value AS dimension_value,
                                             message_campaign_id
                                      FROM dbo.message_campaign_allstate
                                      WHERE dimension_type = 'has-wsa'
                                  ) haswsa
                                      ON haswsa.message_campaign_id = mc.message_campaign_id)mca
                              WHERE @has_account = mca.hasaccount
                                    and @has_wsa = mca.haswsa

                     DELETE @message_campaigns
                     FROM @message_campaigns mc
                         LEFT OUTER JOIN @message_campaigns_allstate mca
                             ON mca.message_campaign_id = mc.message_campaign_id
                     WHERE mca.message_campaign_id IS NULL;
			  END;

              -- 2.2.2) remove campaigns that don't match @subscription_type_id
              if @subscription_id is not null
                     begin
                     delete from @message_campaigns 
                     where message_campaign_id not in (select t.message_campaign_id
                                                       from message_campaign_subscription_type t
                                                       where t.subscription_type_id = @subscription_type_id)
                     end

              -- 2.3) license_message
              insert into @message_campaigns(message_source, message_campaign_id, message_campaign_name, message_campaign_description, message_platform_id, message_platform_name, message_cycle_id, process_date, end_date, message_key, license_message_id, cart_discount_id)
              select message_source = 'license message', c.message_campaign_id, c.message_campaign_name, c.message_campaign_description, 
                     mp.message_platform_id,
                     mp.massage_platform_name,
                     p.message_cycle_id,
                     lm.process_date,
                     lm.end_date,
                     lm.license_message_key,
                     lm.license_message_id,
                     v.value_id
              from dbo.license_message lm
              inner join dbo.message_campaign c
                     on c.message_campaign_id
 = lm.message_campaign_id
              inner join dbo.message_campaign_platform p
                     on c.message_campaign_id = p.message_campaign_id
              inner join dbo.message_platform mp
                     on p.message_platform_id = mp.message_platform_id
              left join dbo.license_message_value v
                     on lm.license_message_id = v.license_message_id and v.message_value_type_id = 1
              where lm.license_id = @license_id and mp.massage_platform_name in (select char_value from dbo.fn_char_string_to_table(@message_platform_name_list)) and 
                     c.message_campaign_class_id <> 3
					 and lm.message_campaign_class_id = 2
					 AND c.message_campaign_enabled = 1
			
              -- 2.4) add content to @license_message_check
              declare @license_message_check table (license_message_id int NULL,keycode varchar(40) NULL,license_id int NULL,license_message_key varchar(36) NOT NULL,process_date datetime NULL,       end_date datetime NULL,message_campaign_id int NOT NULL,message_platform_id tinyint NOT NULL,massage_platform_name varchar(20) NOT NULL,serial_number varchar(19) NULL,contract_id varchar(10) NULL,message_content_id int NOT NULL,message_content_display_id int NOT NULL,offer_tagline nvarchar(4000) NULL,offer_body nvarchar(4000) NULL, 
              offer_body_short nvarchar(1000), tray_state varchar(15), offer_button nvarchar(4000) NULL,image_url varchar(500) NULL,language_code varchar(2) NOT NULL,location_code varchar(3) NOT NULL,territory varchar(2) NULL,message_action varchar(50) NULL, symbol_utf8 nvarchar(10),discount money, campaign_process_date datetime NULL, campaign_end_date datetime NULL, message_url varchar(500) NULL, transactional bit NULL, agent_state varchar(15) NULL)      

              insert into @license_message_check(license_message_id, keycode, license_id, license_message_key, process_date, end_date, message_campaign_id, message_platform_id, massage_platform_name, serial_number, contract_id, message_content_id, message_content_display_id, offer_tagline, 
              offer_body, offer_body_short, tray_state, offer_button, image_url, language_code, location_code, territory, message_action,symbol_utf8,discount,campaign_process_date,campaign_end_date,message_url, transactional, agent_state)
              select m.license_message_id, 
                           keycode = @keycode, 
                           license_id = @license_id, 
                           message_key = m.message_key,
						   CASE WHEN process_date< m.message_campaign_start_date THEN  
                                         CASE WHEN l.message_cycle_line_id is null then m.message_campaign_start_date
                                         when l.message_cycle_line_id is not null and l.cycle_gap_days is null then dateadd(dd,(cy.cycle_duration_days+((datediff(dd,m.message_campaign_start_date,m.end_date)-(cy.cycles*cy.cycle_duration_days))/cy.cycles))*l.line_id,m.message_campaign_start_date)
                                         when l.message_cycle_line_id is not null and l.cycle_gap_days is not null then dateadd(dd,(cy.cycle_duration_days*l.line_id)+l.cycle_gap_days,m.message_campaign_start_date)
										END
                           ELSE CASE when l.message_cycle_line_id is null then m.process_date
                                         when l.message_cycle_line_id is not null and l.cycle_gap_days is null then dateadd(dd,(cy.cycle_duration_days+((datediff(dd,m.process_date,m.end_date)-(cy.cycles*cy.cycle_duration_days))/cy.cycles))*l.line_id,m.process_date)
                                         when l.message_cycle_line_id is not null and l.cycle_gap_days is not null then dateadd(dd,(cy.cycle_duration_days*l.line_id)+l.cycle_gap_days,m.process_date)
										 END
										 END AS process_date,

                           CASE WHEN process_date <m.message_campaign_start_date THEN
						   CASE
										when l.mess
age_cycle_line_id is null then end_date
                                        when l.message_cycle_line_id is not null and l.cycle_gap_days is null then dateadd(dd,(cy.cycle_duration_days+(cy.cycle_duration_days+((datediff(dd,m.message_campaign_start_date,m.end_date)-(cy.cycles*cy.cycle_duration_days))/cy.cycles))*l.line_id),m.message_campaign_start_date)
                                        when l.message_cycle_line_id is not null and l.cycle_gap_days is not null then dateadd(dd,(cy.cycle_duration_days+(cy.cycle_duration_days*l.line_id)+l.cycle_gap_days),m.message_campaign_start_date)
                                        END
                            ELSE 
							 CASE
										when l.message_cycle_line_id is null then end_date
                                        when l.message_cycle_line_id is not null and l.cycle_gap_days is null then dateadd(dd,(cy.cycle_duration_days+(cy.cycle_duration_days+((datediff(dd,m.process_date,m.end_date)-(cy.cycles*cy.cycle_duration_days))/cy.cycles))*l.line_id),m.process_date)
                                        when l.message_cycle_line_id is not null and l.cycle_gap_days is not null then dateadd(dd,(cy.cycle_duration_days+(cy.cycle_duration_days*l.line_id)+l.cycle_gap_days),m.process_date)
                                        END 
										END end_date,
                           m.message_campaign_id, 
                           m.message_platform_id, 
                           m.message_platform_name, 
                           serial_number = null, 
                           contract_id = null, 
                           mc.message_content_id, 
                           cd.message_content_display_id, 
                           cd.offer_tagline, 
                           cd.offer_body,
                           cd.offer_body_short,
                           ab.tray_state,
                           cd.offer_button, 
                           cd.image_url, 
                           cd.language_code, 
                           cd.location_code, 
						   territory = (select iso from lu_countries where iso3 = cd.location_code),
                           mc.message_action,
                           c.symbol_utf8,
                           i.discount,
                           m.process_date,
                           m.end_date,
                           mc.message_url,
                           ab.transactional,
                           ab.agent_state
              from @message_campaigns m
              inner join dbo.message_campaign_content cc
                     on m.message_campaign_id = cc.message_campaign_id
              inner join dbo.message_content mc
                     on cc.message_content_id = mc.message_content_id
              inner join dbo.message_content_display cd
                     on cc.message_content_id = cd.message_content_id and cd.language_code = @language_code and cd.location_code = @location_code
              left join dbo.message_campaign_agent_behavior ab
                     on m.message_campaign_id = ab.message_campaign_id
              left join dbo.message_cycle cy
                     on m.message_cycle_id = cy.message_cycle_id
              left join dbo.message_cycle_line l
                     on m.message_cycle_id = l.message_cycle_id
              left join dbo.cart_discount_item i
                     on m.cart_discount_id = i.cart_discount_id
              left join dbo.cart_discount_item_discount id
                     on i.cart_discount_item_id = id.cart_discount_item_id and id.language_code = @language_code and id.location_code = @location_code
              left join dbo.currency c
                     on id.currency_id = c.currency_id


              -- 2.4.1) discount <$dis>
                     update @license_message_check
                     set offer_tagline = case when offer_tagline like '%<$dis>%' then replace(offer_tagline,'<$di
s>',symbol_utf8+convert(varchar(10),discount))
                                              else offer_tagline
                                         end, 
                           offer_body = case when offer_body like '%<$dis>%' then replace(offer_body,'<$dis>',symbol_utf8+convert(varchar(10),discount))
                                             else offer_body
                                         end,
                           offer_button = case when offer_button like '%<$dis>%' then replace(offer_button,'<$dis>',symbol_utf8+convert(varchar(10),discount))
											else offer_button
                                          end

              -- 2.4.2) <end_date> 
                     update @license_message_check
                     set offer_tagline = case when offer_tagline like '%<end_date>%' then replace(offer_tagline,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
                                              else offer_tagline
                                         end, 
                           offer_body = case 
											when offer_body like '%<end_date>%' then replace(offer_body,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
                                            else offer_body
                                        end, 
                           offer_button = case when offer_button like '%<end_date>%' then replace(offer_button,'<end_date>',convert(varchar(10),datepart(mm,end_date))+'/'+convert(varchar(2),datepart(dd,end_date)))
                                               else offer_button
                                          end

              -- 2.4.3) <end_date> 
                     update @license_message_check
                     set offer_tagline = case when offer_tagline like '%<%dis>%' then replace(offer_tagline,'<%dis>',convert(varchar(10),convert(int,round(discount,0))))
                                              else offer_tagline
                                         end, 
                           offer_body = case when offer_body like '%<%dis>%' then replace(offer_body,'<%dis>',convert(varchar(10),convert(int,round(discount,0))))
                                             else offer_body
                                         end,
                           offer_button = case when offer_button like '%<%dis>%' then replace(offer_button,'<%dis>',convert(varchar(10),convert(int,round(discount,0))))
                                               else offer_button
                                          end
				
				-- 2.4.4) <days_remaining> 
                     update @license_message_check
                     set offer_tagline = case when offer_tagline like '%<days>%' then replace(offer_tagline,'<days>',left(@days_remaining,10))
                                              else offer_tagline
                                         end, 
                           offer_body = case 
											when offer_body like '%<days>%' then replace(offer_body,'<days>',left(@days_remaining,10))
                                            else offer_body
                                        end, 
                           offer_button = case when offer_button like '%<days>%' then replace(offer_button,'<days>',left(@days_remaining,10))
                                               else offer_button
                                          end

				if @max_threats_removed is null 
                     begin
                     select @max_threats_removed = 0
                     END
                     
              -- 2.4.5) threat data
				update c 
				set offer_body = replace(c.offer_body, e.replace_tag, replace(e.replace_string, e.rule_parameter, cast(@max_threats_removed as nvarchar(10))))
				from @license_message_check c
					inner join dbo.message_content_display_content_displa
y_ext ce
						on c.message_content_display_id = ce.message_content_display_id
					inner join dbo.message_content_display_ext e
						on e.message_content_display_ext_id = ce.message_content_display_ext_id and e.low_range <= @max_threats_removed and @max_threats_removed < e.high_range

              -- 2.4.6) <bby_discount>
              declare @bby_discount nvarchar(100)

              update @license_message_check
              set offer_button = case when discount is null then replace(offer_button,'<bby_discount>','Now')
										else replace(offer_button,'<bby_discount>','& Save '+symbol_utf8+convert(varchar(10),discount)) end
              where offer_button like '%<bby_discount>%'


              -- 2.4.7) license seats 
              if @devices is not NULL and @devices < @license_seats
                     begin 
                           if @devices <= 1 
                                  begin
                                  select @devices_str = left(@devices,2) + ' is' 
                                  end
              
                           if @devices > 1 
                                  begin 
                                  select @devices_str = left(@devices,2) + ' are' 
                                  END
                                  
              
							update @license_message_check
							set offer_body = case when offer_body like '%<%used>%' then replace(offer_body,'<%used>',@devices_str)
												else offer_body
											end
							UPDATE @license_message_check
							SET offer_body = CASE WHEN offer_body LIKE '%<%alot>%' THEN REPLACE(offer_body,'<%alot>',@license_seats)
												ELSE offer_body
											END
                     END
                                  
              -- 2.4.8) sky license check
			  IF @sky_check = 0
				BEGIN
					delete from @license_message_check where message_campaign_id in (select message_campaign_id from message_campaign_security_exclusion)
				END 

              ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              -- 3.) return results
              ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

              -- 3.1) select all
              IF @show_all = 1
              BEGIN
                     SELECT license_message_id = ISNULL(lmc.license_message_id, lmc.license_id),
                            lmc.keycode,
                            lmc.license_id,
                            lmc.license_message_key,
                            lmc.process_date,
                            lmc.end_date,
                            lmc.message_campaign_id,
                            lmc.message_platform_id,
                            massage_platform_name = CASE
                                                        WHEN lmc.massage_platform_name = 'product' THEN
                                                            'ui'
                                                        ELSE
                                                            lmc.massage_platform_name
                                                    END,
                            lmc.serial_number,
                            lmc.contract_id,
                            lmc.message_content_display_id,
                            lmc.offer_tagline,
                            CASE
                                WHEN lmc.massage_platform_name = 'tray'
                                    AND lmc.offer_body_short <> ''
                                    AND lmc.offer_body_short IS NOT NULL THEN
                                    lmc.offer_body_short
                                ELSE
    
                                lmc.offer_body
                            END AS offer_body,
                            lmc.offer_button,
                            lmc.language_code,
                            lmc.location_code,
                            lmc.territory,
                            lmc.symbol_utf8,
                            lmc.discount,
                            lmc.message_content_id,
                            lmc.message_action,
                            image_url = [dbo].[fn_message_select_message_content_image](
                                                                                            lmc.message_content_id,
                                                                                            @expiration_date,
                                                                                            lmc.process_date,
                                                                                            @autorenewal_opt_id
                                                                                        ),
                            lmc.message_url,
                            ISNULL(lmc.tray_state, '') AS tray_state,
                            ISNULL(lmc.transactional, 0) AS transactional,
                            ISNULL(lmc.agent_state, '') AS agent_state
                     FROM @license_message_check lmc
                     WHERE lmc.process_date <= lmc.campaign_end_date
                           AND lmc.end_date <= lmc.campaign_end_date
                     ORDER BY lmc.process_date,
                              lmc.end_date DESC,
                              lmc.message_platform_id;
              END
              -- 3.2) select current
              ELSE
              BEGIN 
              
                     -- 3.2.1) - rank campaigns based on campaign priority, transaction/promotional, max_process_date
                     DECLARE @license_message_rank TABLE
                     (
                         license_id INT NOT NULL,
                         message_campaign_id INT NOT NULL,
                         message_campaign_priority_id INT NULL,
                         transactional INT NULL,
                         max_process_date DATETIME NULL,
                         campaign_rank INT NULL
                     )

                     INSERT INTO @license_message_rank
                     (
                         license_id,
                         message_campaign_id,
                         message_campaign_priority_id,
                         transactional,
                         max_process_date,
                         campaign_rank
                     )
                     SELECT
                         lmc.license_id,
                         lmc.message_campaign_id,
                         ISNULL(mcmp.message_campaign_priority_id, 0) AS message_campaign_priority_id,
                         ISNULL(lmc.transactional, 0) AS transactional,
                         MAX(lmc.process_date) AS max_process_date,
                         ROW_NUMBER() OVER
                         (
                             PARTITION BY lmc.license_id
                             ORDER BY
                                 CASE 
                                     WHEN ISNULL(mcmp.message_campaign_priority_id, 0) = 0 THEN 1 
                                     ELSE 0 
                                 END,
                                 ISNULL(mcmp.message_campaign_priority_id, 0) ASC,
                                 ISNULL(lmc.transactional, 0) DESC,
                                 MAX(lmc.process_date) DESC
                         ) AS campaign_rank
                     FROM @license_message_check lmc
                     INNER JOIN dbo.message_campaign mc
                         ON mc.message_campaign_id = lmc.message_campaign_id
                     IN
NER JOIN dbo.message_campaign_message_priority mcmp
                         ON mcmp.message_campaign_id = mc.message_campaign_id
                     WHERE lmc.process_date < @run_date
                         AND @run_date <= lmc.end_date
                         AND lmc.process_date <= lmc.campaign_end_date
                         AND lmc.end_date <= lmc.campaign_end_date
                     GROUP BY 
                     lmc.license_id,
                     lmc.message_campaign_id,
                     mcmp.message_campaign_priority_id,
                     lmc.transactional;

                     -- 3.2.2) get results based on ranking
                     SELECT license_message_id = ISNULL(lmc.license_message_id, lmc.license_id),
                            lmc.keycode,
                            lmc.license_id,
                            lmc.license_message_key,
                            lmc.process_date,
                            lmc.end_date,
                            lmc.message_campaign_id,
                            lmc.message_platform_id,
                            massage_platform_name = CASE
                                                        WHEN lmc.massage_platform_name = 'product' THEN
                                                            'ui'
                                                        ELSE
                                                            lmc.massage_platform_name
                                                    END,
                            lmc.serial_number,
                            lmc.contract_id,
                            lmc.message_content_display_id,
                            lmc.offer_tagline,
                            CASE
                                WHEN lmc.massage_platform_name = 'tray'
                                    AND lmc.offer_body_short <> ''
                                    AND lmc.offer_body_short IS NOT NULL THEN
                                    lmc.offer_body_short
                                ELSE
                                    lmc.offer_body
                            END AS offer_body,
                            lmc.offer_button,
                            lmc.language_code,
                            lmc.location_code,
                            lmc.territory,
                            lmc.symbol_utf8,
                            lmc.discount,
                            lmc.message_content_id,
                            lmc.message_action,
                            image_url = [dbo].[fn_message_select_message_content_image](
                                                                                            lmc.message_content_id,
                                                                                            @expiration_date,
                                                                                            @run_date,
                                                                                            @autorenewal_opt_id
                                                                                        ),
                            lmc.message_url,
                            ISNULL(lmc.tray_state, '') AS tray_state,
                            ISNULL(lmc.transactional, 0) AS transactional,
                            ISNULL(lmc.agent_state, '') AS agent_state
                     FROM @license_message_check lmc
                     INNER JOIN @license_message_rank lmr
                            ON lmr.license_id = lmc.license_id 
                               AND lmr.message_campaign_id = lmc.message_campaign_id
                     WHERE lmc.process_date < @run_date
                           AND @run_date <= lmc.end_date
                           AND lmc.process_date <= lmc.campaign_end_date
                           AND lmc.end_date <= lmc.campaign_end_date
                  
         AND lmr.campaign_rank = 1
                     ORDER BY lmc.process_date,
                              lmc.end_date DESC,
                              lmc.message_platform_id;
              END

       END TRY

       BEGIN CATCH

              set @response_code = -200
              set @message = case when @message is null then 'select failed'
                                                else @message end

              declare @DBName nvarchar(128)
              set @DBName = db_name()
              exec usp_LogError @ErrorDB = @DBName
              
       END CATCH;
       

GO
