CREATE PROCEDURE [dbo].[usp_message_select_message_campaign]

(
	@message_campaign_id INT
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-30	esmart		Initial creation.
	2020-11-24	abelenkiy	Added message_campaign_key to output
	2026-05-04	jberry		US-4774432 - Added message_campaign_priority_id to output

	DESCRIPTION
	Called by PHP to return message campaign info; it's the select procedure for the Campaign model:
	applications/csi/libraries/li3_wr/extensions/procedures/message/select/Campaign.php

*/

AS
	SET NOCOUNT ON				

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select message_content
	SELECT c.message_campaign_id,
		   c.message_campaign_name,
		   c.message_campaign_description,
		   c.message_campaign_key,
		   cc.message_campaign_class_id,
		   cc.message_campaign_class_name,
		   cc.message_campaign_class_description,
		   e.message_campaign_enabled,
		   e.message_campaign_enabled_description,
		   c.message_campaign_start_date,
		   c.message_campaign_end_date,
		   p.message_measure_point_id,
		   p.message_measure_point_name,
		   m.message_duration_days,
		   m.message_measure_days,
		   m.message_measure_end_days,
		   mcmp.message_campaign_priority_id,
		   c.insert_date,
		   c.insert_by,
		   c.modified_date,
		   c.modified_by
	FROM dbo.message_campaign c
		INNER JOIN dbo.message_campaign_class cc
			ON c.message_campaign_class_id = cc.message_campaign_class_id
		INNER JOIN dbo.message_campaign_enabled e
			ON c.message_campaign_enabled = e.message_campaign_enabled
		INNER JOIN dbo.message_campaign_measure_point m
			ON c.message_campaign_id = m.message_campaign_id
		INNER JOIN dbo.message_measure_point p
			ON m.message_measure_point_id = p.message_measure_point_id
		LEFT JOIN dbo.message_campaign_message_priority mcmp
			ON mcmp.message_campaign_id = c.message_campaign_id
	WHERE c.message_campaign_id = @message_campaign_id;

	END TRY

	BEGIN CATCH

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
