CREATE   PROCEDURE [dbo].[usp_message_select_message_campaign_child_license] (
	@message_campaign_id INT
    , @dimension_type VARCHAR(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2026-01-09	gblandford	US-5146908 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5146908
							- Initial creation

	DESCRIPTION
	
*/

AS
	SET NOCOUNT ON;
	
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	DECLARE	@response_code INT,
		@message VARCHAR(100)

	BEGIN TRY

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	   
		-- 1.1) select message_campaign_child_license
		SELECT 
			mccl.message_campaign_child_license_id, 
			mccl.message_campaign_id, 
			mccl.dimension_type, 
			mccl.dimension_value
		FROM dbo.message_campaign_child_license mccl
		WHERE mccl.message_campaign_id = @message_campaign_id
			AND dimension_type = @dimension_type

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;
	



GO
