CREATE PROCEDURE [dbo].[usp_message_select_message_campaign_contract_detail]

(
	@message_campaign_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2015-03-02	acoffel		Initial creation.

	DESCRIPTION
	select 
*/

AS
