-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_select_message_content]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_message_select_message_content]

(
	@message_content_id INT = NULL,
	@message_content_status VARCHAR(20) = NULL,
	@message_content_name varchar(50) = NULL,
	@message_action VARCHAR(50) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-30	esmart		Initial creation
	2013-08-25	esmart		Add message_content_status
	2026-07-09	pachanta	US-5519994: Adding Message action to find the messages based on actions.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@message_content_image_schedule_list varchar(500),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @message_content_status
	if @message_content_status is null or @message_content_status = ''
		begin
		select @message_content_status = 'active'
		end

	-- 1.1) 
	if @message_content_name is null or @message_content_name = ''
		begin
		select @message_content_name = '%%'
		end
	else
		begin
		select @message_content_name = '%'+@message_content_name+'%'
		end
	

	declare @message_content_list table (list_id int identity(1,1),message_content_id int,message_content_name varchar(50),message_action varchar(50),last_modified_date datetime,last_modified_by varchar(20),message_content_status varchar(20),message_content_image_id tinyint,image_name varchar(50),image_url varchar(500),message_url varchar(500), message_content_image_schedule_list varchar(500))

	-- 1.1) select message_content
	insert into @message_content_list(message_content_id, message_content_name, message_action, last_modified_date, last_modified_by, message_content_status, message_content_image_id, image_name, image_url, message_url)
	select c.message_content_id, c.message_content_name, c.message_action, c.last_modified_date, c.last_modified_by, c.message_content_status,
		i.message_content_image_id, 
		i.image_name,
		i.image_url,
		c.message_url
	from message_content c
	left join message_content_image i
		on c.message_content_image_id = i.message_content_image_id
	where c.message_content_id = case	
									when @message_content_id is null or @message_content_id = 0 then c.message_content_id
									else @message_content_id
								end and
			c.message_content_status = case	
									when @message_content_id is null or @message_content_id = 0 then @message_content_status
									else c.message_content_status
								END AND
            c.message_action = CASE WHEN @message_action IS NULL OR @message_action = '' THEN c.message_action ELSE @message_action END


	declare @list_id int, @list_ids int

	select @list_ids = count(*), @list_id = 1 from @message_content_list
	
	while @list_ids >= @list_id
		begin
		select @message_content_id = message_content_id from @message_content_list where list_id = @list_id

		select @message_content_image_schedule_list = coalesce(@message_content_image_schedule_list+', ','')+ cast(s.image_schedule_desription as varchar(100)) 
		from message_content_image_schedule s
		inner join message_content_image_schedule_content c
			on s.message_content_image_schedule_id = c.message_content_image_schedule_id
		where c.message_content_id = @message_content_id

		update @message_content_list
		set message_content_image_schedule_list = @message_content_image_schedule_list
		where list_id = @list_id

		select @message_content_image_sch
edule_list = null
		select @list_id = @list_id + 1
		end
					
	
	select message_content_id, message_content_name, message_action, last_modified_date, last_modified_by, message_content_status, message_content_image_id, image_name, image_url, message_url, message_content_image_schedule_list
	from @message_content_list
	where message_content_name like @message_content_name
	order by message_content_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
