-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_insert_message_service]

(
	@message_service_json varchar(max),
	@message_service_type_name varchar(50),
	@message_service_client_id int,
	@customer_email varchar(100)
)

AS

/*	
	DATE			AUTHOR		REMARKS
	2018-05-10		acoffel		Initial creation.
		

	DESCRIPTION
	insert message_service
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100),
			@message_service_id int,
			@message_service_type_id int
   

	begin try
   
	select @message_service_type_id = message_service_type_id from message_service_type where message_service_type_name = @message_service_type_name
    
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  insert message_service
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) insert new message
	insert into message_service(message_service_type_id, message_service_client_id, message_service_status_id, customer_email, process_date, update_attempts, insert_by, last_modified_date, last_modified_by) values(@message_service_type_id, @message_service_client_id, 1, @customer_email, getdate(), 0, system_user, getdate(), system_user)

	-- 1.2) set @message_service_id
	select @message_service_id = SCOPE_IDENTITY()

	-- 1.3) log json 
	if @message_service_json is not NULL
		begin 
			insert into message_service_log_json(message_service_id, message_service_json, insert_date)
			select @message_service_id, @message_service_json, getdate()
		end
	
	select message_service_id = @message_service_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_message_service]
-- =============================================================================

	CREATE PROCEDURE [dbo].[usp_message_service_select_message_service]

	(
		@message_service_id int
	)
	
	/*	
		DATE		AUTHOR		REMARKS
		2018-05-11	acoffel		Initial Creation
		2018-10-15	mrobbins	changed json to left join - ALCHEMISTS 1971

		DESCRIPTION
	
		select outbound message_service records	
	
	*/


	AS
			set nocount,
			concat_null_yields_null,
			ansi_nulls, 
			ansi_padding, 
			ansi_warnings on;
				

		declare	@response_code int,
				@message varchar(100)

		begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select record
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select top 1 s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name
		from message_service s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.message_service_id = @message_service_id
		union
		select top 1 s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name
		from message_service_archive s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.message_service_id = @message_service_id
		union
        select top 1 s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name
		from message_service_failure s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.message_service_id = @message_service_id

		end try

		begin catch

			set @response_code = -200
			set @message = case when @message is null then 'select message_service record failed'
								else @message end

			declare @DBName nvarchar(128)
			set @DBName = db_name()
			exec usp_LogError @ErrorDB = @DBName
		
		end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_message_service_archive_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_select_message_service_archive_batch]

/*	
	DATE		AUTHOR		REMARKS
	2019-10-24	mrobbins	Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select getdate() batch_limit_date ,
		msp.message_service_platform_name,
		count(*) batch_count
	FROM message_service_response msr
		INNER JOIN dbo.message_service_archive msa
			ON msr.message_service_id = msa.message_service_id
		INNER JOIN message_service_type mst
			ON mst.message_service_type_id = msa.message_service_type_id
		INNER JOIN dbo.message_service_platform msp
			ON msp.message_service_platform_id = mst.message_service_platform_id
	WHERE  msa.message_service_status_id = 2
		AND msa.message_service_vendor_response_status IS NULL 
		AND msr.recipient_send_id IS NOT NULL
		AND msa.archive_date <= GETDATE()
	GROUP BY msp.message_service_platform_name


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



SET ANSI_NULLS ON

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_message_service_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_select_message_service_batch]

/*	
	DATE		AUTHOR		REMARKS
	2018-05-10	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select batch_count = count(*), batch_limit_date = getdate()
	from message_service
	where message_service_status_id in (1,3) and process_date <= getdate()


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_message_service_by_email]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_select_message_service_by_email]

	(
		@customer_email varchar(100),
		@message_service_type_id int
	)
	
	/*	
		DATE		AUTHOR		REMARKS
		2018-10-18	cnovac		Intitial Creation

		DESCRIPTION

	*/


	AS
			set nocount,
			concat_null_yields_null,
			ansi_nulls, 
			ansi_padding, 
			ansi_warnings on;
				

		declare	@response_code int,
				@message varchar(100)

		begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select record
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		select s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name, s.insert_date
		from message_service s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.customer_email = @customer_email
		and t.message_service_type_id = @message_service_type_id
		union
		select s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name, s.insert_date
		from message_service_archive s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.customer_email = @customer_email
		and t.message_service_type_id = @message_service_type_id
		union
		select s.message_service_id, s.customer_email, t.message_service_type_name, j.message_service_json, st.message_service_status_name, s.insert_date
		from message_service_failure s
		left join message_service_log_json j
			on s.message_service_id = j.message_service_id
		inner join dbo.message_service_type t
			on s.message_service_type_id = t.message_service_type_id
		inner join message_service_status st
			on s.message_service_status_id = st.message_service_status_id
		where s.customer_email = @customer_email
		and t.message_service_type_id = @message_service_type_id

		end try

		begin catch

			set @response_code = -200
			set @message = case when @message is null then 'select usp_message_service_select_message_service_by_email record failed'
								else @message end

			declare @DBName nvarchar(128)
			set @DBName = db_name()
			exec usp_LogError @ErrorDB = @DBName
		
		end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_next_message_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_select_next_message_service]

(
	@batch_limit_date DATETIME
)
	
/*	
	DATE		AUTHOR		REMARKS
	2018-05-11	acoffel		Initial Creation
	2018-09-05	mrobbins	added message_service_platform
    2018-10-15	mrobbins	changed json to left join - ALCHEMISTS 1971

	DESCRIPTION
	
	select outbound message_service records	
	
*/


AS
		set nocount,
		concat_null_yields_null,
		ansi_nulls, 
		ansi_padding, 
		ansi_warnings on;
				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select record
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select top 1 s.message_service_id, s.customer_email, t.message_service_type_name, t.process_type, j.message_service_json, p.message_service_platform_name,p.message_service_platform_id
	from message_service s
	left join message_service_log_json j
		on s.message_service_id = j.message_service_id
	inner join dbo.message_service_type t
		on s.message_service_type_id = t.message_service_type_id
	INNER JOIN dbo.message_service_platform p
		ON t.message_service_platform_id = p.message_service_platform_id
	where s.message_service_status_id in (1,3) and s.process_date <= @batch_limit_date 
	order by s.process_date
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select next message_service record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_select_next_message_service_archive]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_select_next_message_service_archive]

(
	@batch_limit_date DATETIME,
	@message_service_platform_name VARCHAR(50)
)
	
/*	
	DATE		AUTHOR		REMARKS
	2019-10-24	mrobbins	Initial Creation


	DESCRIPTION
	
	select outbound message_service_archive records	to check for ESP response
	
*/


AS
		SET NOCOUNT,
		CONCAT_NULL_YIELDS_NULL,
		ANSI_NULLS, 
		ANSI_PADDING, 
		ANSI_WARNINGS ON;
				

	DECLARE	@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

	SELECT @batch_limit_date = DATEADD(MINUTE,10,@batch_limit_date)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select record
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	

	IF @message_service_platform_name = 'SFMC'
		BEGIN
			SELECT TOP 500 msa.message_service_archive_id,
				msa.message_service_id,
				mst.message_service_type_name,
				msr.recipient_send_id recipientSendId
			FROM message_service_response msr
				INNER JOIN dbo.message_service_archive msa
					ON msr.message_service_id = msa.message_service_id
				INNER JOIN message_service_type mst
					ON mst.message_service_type_id = msa.message_service_type_id
				INNER JOIN dbo.message_service_platform msp
					ON msp.message_service_platform_id = mst.message_service_platform_id
			WHERE msp.message_service_platform_name = @message_service_platform_name
				AND msa.message_service_status_id = 2
				AND msa.message_service_vendor_response_status IS NULL 
				AND msr.recipient_send_id IS NOT NULL
				AND msa.archive_date <= @batch_limit_date
			ORDER BY msa.message_service_archive_id
		END 
	 
	

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select next message_service_archive record failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_update_message_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_update_message_service]

(
	@message_service_id int,
	@message_service_status_id tinyint,
	@message_service_response varchar(max) = NULL

)
	
/*	
	DATE		AUTHOR		REMARKS
	2018-05-10	acoffel		Initial Creation
	2019-10-24	mrobbins	added JSON into recipient_send_id

	DESCRIPTION
	
	
*/


AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@update_attempts tinyint

	select @update_attempts = update_attempts from message_service where message_service_id = @message_service_id

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update success record
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) success
	if @message_service_status_id = 2
		begin 
			-- 1.1) update record
			update message_service 
			set message_service_status_id = @message_service_status_id,
				update_attempts = update_attempts + 1,
				last_modified_date = getdate(),
				last_modified_by = system_user 
			where message_service_id = @message_service_id
			
			-- 1.2) archive record
			insert into dbo.message_service_archive (message_service_id, message_service_type_id, message_service_client_id, message_service_status_id, customer_email, insert_date, process_date, update_attempts, insert_by, last_modified_date, last_modified_by, archive_date)
			select message_service_id, message_service_type_id, message_service_client_id, message_service_status_id, customer_email, insert_date, process_date, update_attempts, insert_by, last_modified_date, last_modified_by, getdate()
			from message_service
			where message_service_id = @message_service_id 

			-- 1.3) delete record
			delete
			from message_service 
			where message_service_id = @message_service_id

				if @message_service_response is not null
					begin 
						insert into dbo.message_service_response (message_service_id, message_service_response, insert_date, recipient_send_id)
						select @message_service_id, @message_service_response, getdate(), 
							CASE WHEN ISJSON(@message_service_response) > 0 THEN 
								JSON_VALUE(@message_service_response,'$.recipientSendId')
							END 
					end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update failure record
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) update failures
	if @message_service_status_id = 3 and @update_attempts < 5
		begin
			-- 2.1) update record
			update message_service 
			set message_service_status_id = @message_service_status_id,
				update_attempts = update_attempts + 1,
				last_modified_date = getdate(),
				last_modified_by = system_user,
				process_date = dateadd(ss,10,getdate()) 
			where message_service_id = @message_service_id
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update abandoned record
	-- -------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------

	-- 3.0) update abandoned
	if @message_service_status_id = 3 and @update_attempts = 5
		begin
			-- 3.1) update record
			update message_service 
			set message_service_status_id = 4,
				update_attempts = update_attempts + 1,
				last_modified_date = getdate(),
				last_modified_by = system_user,
				process_date = dateadd(ss,10,getdate()) 
			where message_service_id = @message_service_id
		
			-- 3.2) archive record
			insert into dbo.message_service_failure (message_service_id, message_service_type_id, message_service_client_id, message_service_status_id, customer_email, insert_date, process_date, update_attempts, insert_by, last_modified_date, last_modified_by, failure_date)
			select message_service_id, message_service_type_id, message_service_client_id, message_service_status_id, customer_email, insert_date, process_date, update_attempts, insert_by, last_modified_date, last_modified_by, getdate()
			from message_service
			where message_service_id = @message_service_id 

			-- 3.3) delete record
			delete
			from message_service 
			where message_service_id = @message_service_id
		end	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





SET ANSI_NULLS ON

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_service_update_message_service_archive]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_service_update_message_service_archive]

(
	@message_service_id INT,
	@message_service_archive_id INT,
	@message_service_vendor_response_status VARCHAR(255),
	@message_service_response VARCHAR(MAX) = NULL

)
	
/*	
	DATE		AUTHOR		REMARKS
	2019-10-24	mrobbins	Initial Creation

	DESCRIPTION
	
	
*/


AS
	SET NOCOUNT ON				

	DECLARE	@response_code INT,
			@message VARCHAR(100)


	BEGIN TRY
		
		UPDATE dbo.message_service_archive
		SET message_service_vendor_response_status = @message_service_vendor_response_status,
			last_modified_date = GETDATE(),
			last_modified_by = SYSTEM_USER
		WHERE message_service_archive_id = @message_service_archive_id

		INSERT INTO dbo.message_service_response (message_service_id, message_service_response, insert_date)
		SELECT @message_service_id, @message_service_response, GETDATE()



	END TRY 

	BEGIN CATCH 
		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'update failed'
							ELSE @message END 

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
