-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_license_message_autobilling]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_message_update_license_message_autobilling]
(
    @license_id INT,
    @month INT = NULL
)

/*	
	DATE			AUTHOR			REMARKS
	2015-10-22		esmart			Initial creation
	2015-11-17		esmart			Add logic for process_date past expiration_date
	2016-10-03		esmart			Check to see if process date > expiration date before creating message
	2017-01-23		esmart			Fix for last message on expiring license
	2018-03-16		rvinoche		Add logic to find order_item.effective_date
	2019-01-16		rvinoche		Major refactor, use license_effective_object for autobilling license_message 
	2019-09-05		wbarton			Updating @day_spread, @billing_day_of_month, @previous_billing_day, and @end_of_month from tinyint to int. An edge case where 30-31 exists causes the proc to fail with tinyints.  
	2020-01-02		wbarton			Hotfix in 1.8.1 and 1.9.2 to fix scenarios where date logic needs to cross years, and when date logic was able to assign 13 as month
	2020-02-14		esmart			Add support for O365
	2020-03-11		wbarton			Major refactor to clean-up legacy code, improve effective_date logic, and allow license_message inserts when hierarchy 2 products require autobilling and hierarchy 1 does not.
	2020-08-18		wbarton			Adding section 3.4.1 for cases when Overage or Utility licenses have a billing day of month change becoming effective in the future
	2020-11-19		wbarton			Fixing an edge-case in 3.4.1 where billing day of month 0 will cause an error
	2021-12-06		psatish			Added a Perpetaul billing model to calculate the billing day of month
	2022-03-23		psatish			ALM#961 Added Process_date logic for the migrated contracts and added the autobilling_enabled
									condition to get the license_attribute_id
	2024-06-10		vsingh8			ECOM-4750 Updated logic for calculating year when calculating previous month for January shifts the year.

	DESCRIPTION
	insert license_message for autobilling

	DEPENDENCIES
	usp_billing_process_autobilling
	usp_license_message_bulk_update
	usp_partner_update_partner_license_transaction
*/

AS
SET NOCOUNT ON;

DECLARE @license_attribute_id INT,
        @license_attribute_license_value INT,
        @autobilling_license_category_id TINYINT,
        @primary_license_category_id TINYINT,
        @effective_date DATETIME,
        @current_autobilling_license_message_id INT,
        @last_license_message_process_date DATETIME,
        @expiration_date DATETIME,
        @message_type_id TINYINT,
        @process_date DATETIME,
        @end_date DATETIME,
        @archive_date DATETIME,
        @license_status_id INT,
        @license_message_value_str VARCHAR(MAX),
        @license_message_id INT,
        @cycle_months INT,
        @day_spread INT,
        @billing_day_of_month INT,
        @process_date_billing_day_of_month INT,
        @previous_billing_day INT,
        @end_of_month INT,
        @year INT,
        @insert_date DATE,
        @response_code INT,
        @message VARCHAR(100),
        @license_distribution_method_code VARCHAR(5),
        @license_insert_date DATETIME,
        @previous_month_effective_date DATETIME;

DECLARE @license_effective_object_history TABLE
(
    license_effective_object_id INT,
    license_category_id INT,
    effective_value INT,
    effective_start_date DATE,
    effective_end_date DATE
);

BEGIN TRY

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --1. Setting initial variables
    --------------------------------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------
    SELECT @message_type_id = 10,
           @insert_date = GETDATE(),
           @cycle_months = 1;

    --1.1 license_message data - same logic as prior to procedure refactor
    SELECT @current_autobilling_license_message_id = license_message_id
    FROM license_message
    WHERE license_id = @license_id
          AND message_type_id = 10
          AND message_status_id = 1;

    SELECT @last_license_message_process_date = MAX(process_date)
    FROM license_message
    WHERE license_id = @license_id
          AND message_type_id = 10
          AND message_status_id = 3
          AND DATEDIFF(dd, process_date, @insert_date) <= 31; --this is to exclude usage contracts from the past

    --1.2 Setting license variables - using license_category_license to determine @primary_license_category_id
    SELECT @license_status_id = l.license_status_id,
           @primary_license_category_id = lcl.license_category_id,
           @expiration_date = lcl.end_date
    FROM license l
        INNER JOIN license_category_license lcl
            ON lcl.license_id = l.license_id
    WHERE l.license_id = @license_id;

    --Go to archive section if the license has been disabled
    IF @license_status_id IN ( 2, 3 )
    BEGIN
        GOTO archive;
    END;

    --1.3 Business logic steps to define key variables: @effective_date, @license_attribute_license_value, @autobilling_license_category_id
    --1.3.1 Get license_effective_object records for autobilling models that are either currently-effective or future-effective
    INSERT INTO @license_effective_object_history
    (
        license_effective_object_id,
        license_category_id,
        effective_value,
        effective_start_date,
        effective_end_date
    )
    SELECT license_effective_object_id,
           license_category_id,
           effective_value,
           effective_start_date,
           effective_end_date
    FROM dbo.fn_license_select_effective_object_element_history(@license_id, 'license_attribute_license_value', NULL) e
        INNER JOIN dbo.license_attribute_license_value v
            ON e.effective_value = v.license_attribute_license_value
               AND v.autobilling_enabled = 1 --selecting only autobilling enabled attribute values
    WHERE (
              e.effective_end_date IS NULL
              OR e.effective_end_date > @insert_date
          ); --removing records that are no longer effective

    --1.3.2 If a currently-effective autobilling record exists for the @primary_license_category, use its data
    IF EXISTS
    (
        SELECT 1
        FROM @license_effective_object_history
        WHERE license_category_id = @primary_license_category_id
              AND effective_start_date <= @insert_date
    )
    BEGIN
        SELECT @effective_date = eo.effective_start_date,
               @license_attribute_license_value = eo.effective_value,
               @autobilling_license_category_id = eo.license_category_id
        FROM
        (
            SELECT TOP (1)
                   h.effective_start_date,
                   h.effective_value,
                   h.license_category_id
            FROM @license_effective_object_history h
            WHERE h.license_category_id = @primary_license_category_id
                  AND effective_start_date <= @insert_date
            ORDER BY h.effective_start_date DESC --In case of multiple, we want the closest-starting record to when this is being evaluated
        ) eo;
    END;
    --1.3.3 Otherwise, if a currently-effective autobilling record exists for another license_category_id, use its data. And in case of multiple, use the earliest effective
    ELSE IF EXISTS
    (
        SELECT 1
        FROM @license_effective_object_history
        WHERE license_category_id <> @primary_license_category_id
              AND effective_start_date <= @insert_date
    )
    BEGIN
     
   SELECT @effective_date = eo.effective_start_date,
               @license_attribute_license_value = eo.effective_value,
               @autobilling_license_category_id = eo.license_category_id
        FROM
        (
            SELECT TOP (1)
                   h.effective_start_date,
                   h.effective_value,
                   h.license_category_id
            FROM @license_effective_object_history h
            WHERE h.license_category_id <> @primary_license_category_id
                  AND effective_start_date <= @insert_date
            ORDER BY h.effective_start_date ASC
        ) eo;
    END;
    --1.3.4 If none of the above is met, meaning the license_effective_object records are future-effective, use data from the one starting soonest
    ELSE
    BEGIN
        SELECT @effective_date = eo.effective_start_date,
               @license_attribute_license_value = eo.effective_value,
               @autobilling_license_category_id = eo.license_category_id
        FROM
        (
            SELECT TOP (1)
                   h.effective_start_date,
                   h.effective_value,
                   h.license_category_id
            FROM @license_effective_object_history h
            WHERE h.license_category_id = @primary_license_category_id
            ORDER BY h.effective_start_date,
                     h.license_category_id ASC
        ) eo;
    END;

    --1.3 If the license doesn't have a currently-effective or future-effective autobilling record from license_effective_object, find the current-effective value and proceed to the archive section
    IF @license_attribute_license_value IS NULL
    BEGIN
        SELECT @license_attribute_license_value
            = dbo.fn_license_select_effective_object_element(
                                                                @license_id,
                                                                @primary_license_category_id,
                                                                'license_attribute_license_value',
                                                                @insert_date
                                                            );
        GOTO archive;
    END;

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --2. Determining @billing_day_of_month
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --2.1 Setting billing_day_of_month to either the effective value on a future-dated autobilling record from license_effective_object, or to the currently effective value
    IF @effective_date > @insert_date
    BEGIN
        SELECT @billing_day_of_month
            = dbo.fn_license_select_effective_object_element(
                                                                @license_id,
                                                                @autobilling_license_category_id,
                                                                'billing_day_of_month',
                                                                @effective_date
                                                            );
    END;
    ELSE
    BEGIN
        SELECT @billing_day_of_month
            = dbo.fn_license_select_effective_object_element(
                                                                @license_id,
                                                                @autobilling_license_category_id,
                                                                'billing_day_of_month',
                                                                @insert_date
                                                            );
    END;

    -
-2.2 Should billing_day_of_month be 0 or null, check one more time via fn_license_select_effective_object_element_history for the closest currently-effective or future-effective billing_day_of_month on the primary license_category that is not 0
    IF @billing_day_of_month IS NULL
       OR @billing_day_of_month = 0
    BEGIN
        SELECT @billing_day_of_month = eo.effective_value
        FROM
        (
            SELECT TOP (1)
                   e.effective_value
            FROM fn_license_select_effective_object_element_history(
                                                                       @license_id,
                                                                       'billing_day_of_month',
                                                                       @primary_license_category_id
                                                                   ) e
            WHERE (
                      e.effective_end_date IS NULL
                      OR e.effective_end_date > @insert_date
                  )
                  AND e.effective_value <> 0
            ORDER BY e.effective_start_date,
                     e.license_effective_object_id ASC
        ) eo;
    END;

    --2.3 Go to archive section if billing_day_of_month could not be accurately determined
    IF @billing_day_of_month IS NULL
       OR @billing_day_of_month = 0
    BEGIN
        GOTO archive;
    END;

    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --3. Date logic to define elements of the eventual license_message insert
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --3.1 @effective_date update logic - when @effective_date is in the past, we need to update it to align with either:
    --A: the @last_license_message_process_date when one exists
    SET @effective_date
        = IIF(@last_license_message_process_date > @effective_date, @last_license_message_process_date, @effective_date);
    --B: 1 month ago, should @last_license_message_process_date not exist, or if it's more than a month ago
    SET @effective_date
        = IIF(DATEDIFF(dd, @effective_date, @insert_date) > 31, DATEADD(mm, -1, @insert_date), @effective_date);

    --3.2 set @license_attribute_id; used in 3.3 below for partner logic
    SELECT @license_attribute_id = v.license_attribute_id
    FROM dbo.license_attribute_license_value v
    WHERE v.license_attribute_license_value = @license_attribute_license_value
          AND v.autobilling_enabled = 1;

    --3.2.1 set @license_distribution_method_code for migrated contracts
    SELECT @license_distribution_method_code = dm.license_distribution_method_code
    FROM license lc
        INNER JOIN dbo.license_distribution_method dm
            ON dm.license_distribution_method_id = lc.license_distribution_method_id
    WHERE lc.license_id = @license_id;


    --3.3 @month and @year - keeping the business logic prior to the refactor in place
    SELECT @year = YEAR(@effective_date);

    IF @month IS NULL
    BEGIN
        SELECT @previous_billing_day = DAY(@last_license_message_process_date);

        IF @previous_billing_day = @billing_day_of_month
           OR @previous_billing_day IS NULL
        BEGIN --normal sequence, nothing has changed
            IF (
                   @billing_day_of_month > DAY(@effective_date)
                   AND @license_attribute_id IS NOT NULL
               ) -- for new partner licenses that start this month and need to be billed asap
            BEGIN
                SELECT @previous_month_effective_date = DATEADD(MONTH, -1, @effective_date);
                SELECT @month = MONTH(@previous_month_e
ffective_date);
                -- Take previous year when calculating previous month for January shifts the year.
                SELECT @year = YEAR(@previous_month_effective_date);
            END;
            ELSE
            BEGIN
                SELECT @month = MONTH(@effective_date);
            END;
            --For contract Backfill
            IF @license_distribution_method_code = 'nsbf'
               AND @previous_billing_day IS NULL
            BEGIN
                SELECT @license_insert_date = le.insert_date
                FROM dbo.license_effective_object le
                    INNER JOIN dbo.effective_object eo
                        ON eo.effective_object_id = le.effective_object_id
                WHERE eo.object_element_name = 'billing_day_of_month'
                      AND le.license_id = @license_id;

                IF (
                       @billing_day_of_month > DAY(@license_insert_date)
                       AND @license_attribute_id IS NOT NULL
                   )
                BEGIN
                    SELECT @month = MONTH(DATEADD(MONTH, -1, @license_insert_date));
                    -- Take previous year when calculating previous month for January shifts the year.
                    SELECT @year = IIF(@month = 12, YEAR(@effective_date) - 1, YEAR(@effective_date));
                END;
                ELSE
                BEGIN
                    SELECT @month = MONTH(@license_insert_date);
                END;
            END;
        END;
        ELSE
        BEGIN
            SELECT @end_of_month = DAY(EOMONTH(@effective_date));

            --business logic: if the day spread is less than 15 days then allow concession, else bill asap on new billing day of month
            SELECT @day_spread
                = IIF(@billing_day_of_month < @previous_billing_day,
                      (@end_of_month - @previous_billing_day) + @billing_day_of_month,
                      @billing_day_of_month - @previous_billing_day);

            SELECT @month
                = CASE
                      WHEN @billing_day_of_month < @previous_billing_day
                           AND @day_spread >= 15
                           AND @license_attribute_license_value NOT IN ( 11, 12, 13 ) THEN
                          MONTH(@last_license_message_process_date)                     -- if the spread is 15 days or more, bill ASAP. Updated 8/18/20 to exempt Overage and Utility licenses from this logic; it's causing a day-of-order autobilling record.
                      WHEN @billing_day_of_month < @previous_billing_day
                           AND @day_spread < 15 THEN
                          MONTH(DATEADD(MONTH, 1, @last_license_message_process_date))  -- else concede the period and skip a billing_day. Updated to not assign month 13.
                      WHEN @billing_day_of_month > @previous_billing_day
                           AND @day_spread < 15 THEN
                          MONTH(@last_license_message_process_date)                     -- else concede the period and skip a billing_day
                      WHEN @billing_day_of_month > @previous_billing_day
                           AND @day_spread >= 15
                           AND @license_attribute_license_value NOT IN ( 11, 12, 13 ) THEN
                          MONTH(DATEADD(MONTH, -1, @last_license_message_process_date)) -- bill ASAP (-1 because function below will add 1 month). Updated 8/18/20 to exempt Overage and Utility licenses from this logic; it's causing a day-of-order autobilling record.
                      ELSE
                          MONTH(@effective_date)
                  END;

            SELECT @year = IIF(
                               @month = 12
                               AND @billing_day_of_month > @previous_billing_day
                               AND @day_spread >= 15
                               AND @license_attribute_license_value 
NOT IN ( 11, 12, 13 ),
                               @year - 1,
                               @year);
        END;
    END;

    --3.4 @process_date and @archive_date
    SELECT @process_date = dbo.fn_billing_select_billing_date(@billing_day_of_month, @month, @year, @cycle_months);

    --3.4.1 For cases when Overage or Utility licenses have a billing day of month change taking place in the future between the @effective_date and the calculated @process_date, we need to change @process_date to reflect what billing day of month will be.
    --Using the day before the calculated process_date, as under normal circumstances the @process_date will be the end of a contract and effective beginning of a new billing model or billing day of month
    SELECT @process_date_billing_day_of_month
        = dbo.fn_license_select_effective_object_element(
                                                            @license_id,
                                                            @autobilling_license_category_id,
                                                            'billing_day_of_month',
                                                            DATEADD(DAY, -1, @process_date)
                                                        );
    IF @license_attribute_license_value IN ( 11, 12, 13 )
       AND @billing_day_of_month <> @process_date_billing_day_of_month
       AND @process_date_billing_day_of_month > 0
    BEGIN
        SELECT @process_date
            = dbo.fn_billing_select_billing_date(
                                                    @process_date_billing_day_of_month,
                                                    MONTH(@insert_date),
                                                    YEAR(@insert_date),
                                                    @cycle_months
                                                );
    END;

    --3.4.2 @archive_date
    SELECT @archive_date = DATEADD(mm, 1, @process_date);

    --3.5 Return if the license's expiration date is more than 1 day before the @process_date. 1 day before @process_date is normal in the license's final billing period.
    IF DATEADD(DAY, 1, @expiration_date) < @process_date
    BEGIN
        GOTO archive;
    END;




    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    --4. license_message inserts and updates
    -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


    --4.1 Insert license_message record
    IF @current_autobilling_license_message_id IS NULL
       AND @license_status_id NOT IN ( 2, 3 )
       AND DATEADD(dd, 1, @expiration_date) > GETDATE()
    BEGIN
        EXEC usp_message_insert_license_message @license_id,
                                                @message_type_id,
                                                @process_date,
                                                @end_date,
                                                @archive_date,
                                                @license_message_value_str,
                                                @license_message_id OUTPUT;
        RETURN;
    END;

    --4.2 Archive existing license_message or update license_message_value
    archive:

    IF @current_autobilling_license_message_id IS NOT NULL
    BEGIN
        --4.2.1) if @license_attribute_license_value is no longer autobilling enabled then archive the message
        IF @license_attribute_license_value NOT IN
           (
               SELECT license_attribute_license_value
               FROM dbo.license_attribute_license_value
               WHERE autobilling_enabled = 1
           )
           OR @license_status_id IN 
( 2, 3 )
        BEGIN
            --4.2.1.1) archive autorenewal license_message data
            INSERT INTO license_message_archive
            (
                license_message_id,
                license_id,
                license_message_key,
                message_type_id,
                message_status_id,
                insert_date,
                process_date,
                end_date
            )
            SELECT license_message_id,
                   license_id,
                   license_message_key,
                   message_type_id,
                   message_status_id,
                   insert_date,
                   process_date,
                   end_date
            FROM license_message
            WHERE license_message_id = @current_autobilling_license_message_id;

            INSERT INTO license_message_value_archive
            (
                license_message_value_id,
                license_message_id,
                message_value_type_id,
                value_id
            )
            SELECT v.license_message_value_id,
                   v.license_message_id,
                   v.message_value_type_id,
                   v.value_id
            FROM license_message_value v
            WHERE v.license_message_id = @current_autobilling_license_message_id;

            --4.2.1.2) delete message
            DELETE FROM license_message_value
            WHERE license_message_id = @current_autobilling_license_message_id;
            DELETE FROM license_message
            WHERE license_message_id = @current_autobilling_license_message_id;

            RETURN;
        END;
    END;

END TRY
BEGIN CATCH

    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'autobilling license_message update failed'
                       ELSE
                           @message
                   END;

    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;

END CATCH;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_license_message_autorenewal]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_update_license_message_autorenewal]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2011-04-05	esmart		Initial creation
	2011-07-23	esmart		Support for AR discount campaigns
	2011-12-16	esmart		1.4.1) don't add new message if with 30 days
	2012-03-26	esmart		Correct duplicate trap in 1.4.1
	2012-05-21	esmart		Correct issue with opt out not archiving active messages (2.2)
	2012-10-13	esmart		Monthly AR
	2015-06-01	acoffel		Start processing SMB
	2016-07-06	acoffel		Lookup most recent payment that is AR true
	2019-09-19	wbarton		Modifying process_date logic in section 1.5 so we use the date calculated from capability_expiration_date, but the time from GETDATE(). This will help us avoid clusters of midnight license_message records.
	2019-11-21	wbarton		Retiring legacy autorenewal_cycle logic which would set @process_date_offset to -37 in some cases
	2020-06-02	wbarton		Additional logic in 1.2 to handle scenarios where multiple pending license_message records exist, which can cause erroneous autorenewal transactions
	2020-10-26	jnavarra	Prevent AR process_date in the past (Sections 2.1 and 2.1.1)
	
	DESCRIPTION
	update messages related to autorenewal
	
*/

AS
	
	set nocount on				
	SET CONCAT_NULL_YIELDS_NULL ON
	SET ANSI_WARNINGS ON
	SET ANSI_PADDING ON
	SET ARITHABORT ON				

	declare	@license_attribute_license_value int,
			@current_AR_license_message_id int,
			@current_AR_message_status_id tinyint,
			@base_capability_id int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@message_type_id tinyint,
			@process_date datetime,
			@end_date datetime,
			@archive_date datetime,
			@license_message_value_str varchar(max),
			@license_message_id int,
			@payment_header_id int,
			@customer_id int,
			@license_seats int, 
			@license_category_id tinyint,
			@license_status_id int,
			@license_type_id int,
			@payment_method_autorenewal_flag tinyint,
			@response_code int,
			@message varchar(100),
			@environment_type varchar(50),
			@last_AR_order_date datetime,
			@process_date_offset int,
			@message_autorenewal_cycle_id tinyint
			--@autorenewal_cycle float

	begin try

	select @process_date_offset = -7

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) declare table variables
	declare @order_message_value table (message_value_type_id tinyint, message_value_type_name varchar(50), value_id int)
	declare @message_details table (license_message_id int,license_message_key varchar(36),license_id int, keycode varchar(40),message_campaign_id int,message_campaign_class_id tinyint,message_value_list varchar(max),customer_id int,customer_email varchar(100),first_name nvarchar(225),last_name  nvarchar(225))
	declare @ar_messages table (id int identity(1,1), license_message_id int, message_status_id tinyint)

	-- 1.1) @license_attribute_license_value
	select @license_attribute_license_value = license_attribute_license_value	
	from license_attribute_license with (nolock)
	where license_id = @license_id

	-- 1.2) @current_AR_license_message_id
	--Populate @ar_messages with uncompleted license_message records, ordering by status and recency
	insert into @ar_messages (license_message_id, message_status_id)
	select license_message_id, message_status_id 
	from license_message with (nolock)

	where license_id = @license_id
		and message_type_id = 3
		and message_status_id <> 3
	order by message_status_id asc, license_message_id desc

	--Trapping duplicate pending records, and archiving/deleting so we can prevent erroneous autorenewal transactions
	if (select count(license_message_id) from @ar_messages where message_status_id = 1) > 1
		begin
			--archive license_message
			insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
			select lm.license_message_id, lm.license_id, lm.license_message_key, lm.message_type_id, lm.message_status_id, lm.insert_date, lm.process_date, lm.end_date
			from license_message lm
				inner join @ar_messages am
					on am.license_message_id = lm.license_message_id
			where am.id > 1
				and am.message_status_id = 1
			
			--archive license_message_value			
			insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
			select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
			from license_message_value v
				inner join @ar_messages am
					on am.license_message_id = v.license_message_id
			where am.id > 1
				and am.message_status_id = 1
			
			--delete license_message_value		
			delete lmv
			from dbo.license_message_value lmv
				inner join @ar_messages am
					on am.license_message_id = lmv.license_message_id
			where am.id > 1
				and am.message_status_id = 1
			
			--delete license_message
			delete lm 
			from license_message lm
				inner join @ar_messages am
					on am.license_message_id = lm.license_message_id
			where am.id > 1
				and am.message_status_id = 1		
		end
	
	--Setting @current_AR_license_message_id and @current_AR_message_status_id to the top record from @ar_messages
	select @current_AR_license_message_id = am.license_message_id, @current_AR_message_status_id = am.message_status_id
	from (
		select top 1 id, license_message_id, message_status_id
		from @ar_messages
		order by id asc
	) am
	
	-- 1.3) @base_capability_id
		select @base_capability_id = c.base_capability_id,
				@license_category_id = c.license_category_id
		from license_category c with (nolock)
		inner join license_category_license cl with (nolock)
			on c.license_category_id = cl.license_category_id
		where cl.license_id = @license_id

	-- 1.4) capability data
	select @capability_activation_date = capability_activation_date,
			@capability_expiration_date = capability_expiration_date
	from license_capability with (nolock)
	where license_id = @license_id and capability_id = @base_capability_id

	-- 1.5) @license_seats
	select @license_seats = license_seats
	from license_seat
	where license_id = @license_id 
	
	---- 1.6) @autorenewal_cycle
	--select @message_autorenewal_cycle_id = m.message_autorenewal_cycle_id,
	--		@autorenewal_cycle = m.autorenewal_cycle
	--from license_autorenewal_cycle c
	--inner join message_autorenewal_cycle m
	--	on c.message_autorenewal_cycle_id = m.message_autorenewal_cycle_id
	--where c.license_id = @license_id
	
	--if @autorenewal_cycle is not null
	--	begin
	--	if @autorenewal_cycle <> 1
	--		begin
	--		select @process_date_offset = -37
	--		end
	--	end

--select	license_attribute_license_value = @license_attribute_license_value, 
--		current_AR_license_message_id = @current_AR_license_message_id,
--		current_AR_message_status_id = @current_AR_message_status_id,
--		capability_activation_date = @capability_activation_date,
--		capability_expiration_date = @capability_expiration_date

	-- 1.5) set license_message values
	select @message_type_id = 3,
			@process_date = DATEADD(dd, @process_date_offset, CONVERT(DATE, @capability_expiration_date)), --stripping time off process_date
			@process_date = DATETIMEFROMPARTS(DATEPART(yyyy, @process_date), DATEPART(mm, @process_date), 
DATEPART(dd, @process_date), DATEPART(hh, GETDATE()), DATEPART(mi, GETDATE()), DATEPART(ss, GETDATE()), DATEPART(ms, GETDATE())), --adding time from getdate()
			@end_date = @capability_expiration_date,
			@archive_date = dateadd(dd,30,@capability_expiration_date),
			@license_message_value_str = null
			
		-- 1.5.1) don't add new message if within 30 days
		select @environment_type = environment_type from environment
		if @environment_type is null begin select @environment_type = 'PROD' end

		--select @last_AR_order_date = max(om.insert_date)
		--from license_message m with (nolock)
		--inner join order_message om with (nolock)
		--	on m.license_message_key = om.message_key
		--inner join order_header h with (nolock)
		--	on om.order_header_id = h.order_header_id 
		--where m.message_type_id = 3 and license_id = @license_id
		
		declare @message_keys table (message_key varchar(36))

		insert into @message_keys(message_key)
		select license_message_key
		from license_message m with (nolock)
		where m.message_type_id = 3 and m.license_id = @license_id

		select @last_AR_order_date = max(om.insert_date)
		from @message_keys k
		inner join order_message om with (nolock)
			on k.message_key = om.message_key

		--if @process_date < dateadd(dd,30,@last_AR_order_date) and @environment_type not in ('QA','DEV')
		--	begin
		--	insert into license_message_AR_duplicate(license_id, last_AR_order_date, process_date)
		--	values(@license_id, @last_AR_order_date, @process_date)
		--	return
		--	end			
			
	-- 1.6) get payment_header 

	select @payment_header_id = (select top 1 oph.payment_header_id
								from order_payment_header oph with (nolock)
								inner join payment_header ph with (nolock)
									on ph.payment_header_id = oph.payment_header_id
								inner join payment_method m with (nolock)
									on m.payment_method_id = ph.payment_method_id
								inner join order_header h with (nolock)
									on oph.order_header_id = h.order_header_id
								inner join order_item i with (nolock)
									on h.order_header_id = i.order_header_id
								inner join product p with (nolock)
									on i.product_id = p.product_id
								inner join product_family_autorenewal ar with (nolock)
									on p.product_family_id = ar.product_family_id
								inner join order_item_license il with (nolock)
									on i.order_item_id = il.order_item_id
								where il.license_id = @license_id and m.autorenewal_flag = 1
								order by oph.payment_header_id desc) 




	-- 1.7) customer_id
	select @customer_id = customer_id
	from order_payment_header h
	inner join customer_order o
		on h.order_header_id = o.order_header_id
	where h.payment_header_id = @payment_header_id

	-- 1.8) @license_status_id
	select @license_status_id = license_status_id, @license_type_id = license_type_id 
	from license 
	where license_id = @license_id

		---- 1.8.1) only consumer licenses get AR - need to modify for enterprise at some point
		--if @license_type_id <> 1
		--	begin	
		--	return
		--	end

	-- 1.9) @license_status_id
	select @payment_method_autorenewal_flag = m.autorenewal_flag
	from payment_header h
	inner join payment_method m
		on h.payment_method_id = m.payment_method_id
	where h.payment_header_id = @payment_header_id

	-- 1.10) order_message
	declare @message_key varchar(36),
			@message_value_list varchar(max)
	
	select @message_key = message_key
	from order_message m
	inner join order_payment_header p
		on m.order_header_id = p.order_header_id
	where p.payment_header_id = @payment_header_id
	
	---if @message_key is not null -- Causing issue due to New shopping cart release, hence commented as per Eric suggestion - surpal(1)

	--if @message_key is not null and (select count(*) from cart_discount where cart_discount_key = @message_key) = 0 and (select count(*) from license_key where license_key = @message_key) = 0
	                 -- added above condition
 the new cart allows for different keys to create the cart
                     --and they are not compatible with the AR proc -- surpal(2)
	--	begin
	--	-- 1.10.1) get details
	--	insert into @message_details(license_message_id,license_message_key,license_id,keycode,message_campaign_id,message_campaign_class_id,message_value_list,customer_id,customer_email,first_name,last_name)
	--	exec usp_license_message_select_message_details @message_key
	
		declare @message_campaign_class_id tinyint

	--	-- 1.10.2) @message_campaign_class_id
	--	select @message_campaign_class_id = message_campaign_class_id from @message_details

	---- 1.11) check discounting for AR message
	--if @message_campaign_class_id = 5
	--	begin
	--	select @message_value_list = message_value_list from @message_details

	--	insert into @order_message_value(message_value_type_id, message_value_type_name, value_id)
	--	select v.message_value_type_id, v.message_value_type_name, t.value_id
	--	from message_value_type v
	--	inner join (select message_value_type_name, value_id
	--				from [dbo].[fn_key_value_to_table_pipe](@message_value_list)) t
	--		on v.message_value_type_name = t.message_value_type_name
	--	where v.message_value_type_id = 1
			
	--	end			
	--end

	-- 1.11) create string 

	insert into @order_message_value(message_value_type_id, message_value_type_name, value_id)
	values(9,'payment_header_id',@payment_header_id)

	insert into @order_message_value(message_value_type_id, message_value_type_name, value_id)
	values(10,'customer_id',@customer_id)

	select @license_message_value_str = coalesce(@license_message_value_str+',','')+ cast(message_value_type_name+'='+convert(varchar(20),value_id) as varchar(100))
	from @order_message_value

--	select license_message_value_str = @license_message_value_str

--	select @license_message_value_str = 'payment_header_id=' + convert(varchar(20),@payment_header_id) + ',customer_id=' + convert(varchar(20),@customer_id)
--	select * from @order_message_value
--
--select message_type_id = @message_type_id,
--		process_date = @process_date,
--		end_date = @end_date,
--		archive_date = @archive_date,
--		license_message_value_xml_str = @license_message_value_str,	
--		current_AR_license_message_id = @current_AR_license_message_id,
--		license_attribute_license_value = @license_attribute_license_value,
--		license_status_id = @license_status_id,
--		payment_method_autorenewal_flag = @payment_method_autorenewal_flag
		
--return


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) autorenewal license_message
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.1) insert license_message
		if @current_AR_license_message_id is null and @process_date > getdate() and @license_status_id not in (2,3) and @license_attribute_license_value = 1 and @payment_method_autorenewal_flag = 1
			begin
				--	print '2.1) insert license_message'
				--select @message_type_id = 3	
			
				if @process_date < dateadd(dd,15,@last_AR_order_date) and @environment_type not in ('QA','DEV')
					begin
						insert into license_message_AR_duplicate(license_id, last_AR_order_date, process_date)
						values(@license_id, @last_AR_order_date, @process_date)
						return
					end		

					exec usp_message_insert_license_message @license_id,@message_type_id,@process_date,@end_date,@archive_date,@license_message_value_str,@license_message_id output
					--return
			end -- 2.1 end

		-- 2.1.1) insert license_message for abandoned message with new manual renewals
		if @current_AR_license_message_id is not null and @current_AR_message_status_id = 6 and @process_date > getdate() and @license
_status_id not in (2,3) and @license_attribute_license_value = 1 and @payment_method_autorenewal_flag = 1
			begin
				if @payment_header_id <> (select value_id from license_message_value where license_message_id = @current_AR_license_message_id and message_value_type_id = 9)
					begin
						exec usp_message_insert_license_message @license_id,@message_type_id,@process_date,@end_date,@archive_date,@license_message_value_str,@license_message_id output
					end
			end

		-- 2.2) update license_message
		if (@current_AR_license_message_id is not null and @process_date is not null and @current_AR_message_status_id = 1) or (@current_AR_message_status_id = 1 and @license_attribute_license_value <> 1)
			begin		
				-- 2.2.1) if @license_attribute_license_value is no longer = 1 then archive the message
				if @license_attribute_license_value <> 1 or @license_status_id in (2,3) or @payment_method_autorenewal_flag = 0
					begin
						-- 2.2.1.1) archive autorenewal license_message data
						insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
						select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
						from license_message
						where license_message_id = @current_AR_license_message_id
					
						insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
						select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
						from license_message_value v
						where v.license_message_id = @current_AR_license_message_id
				
						-- 2.2.1.2) delete message
						delete from license_message_value where license_message_id = @current_AR_license_message_id
						delete from license_message where license_message_id = @current_AR_license_message_id	

						-- 2.2.1.3)  archive autorenewal campaign license_message data	
						insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
						select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
						from license_message
						where license_message_id = @current_AR_license_message_id
					
						insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
						select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
						from license_message_value v
						where v.license_message_id = @current_AR_license_message_id
					
						return
					end

				-- 2.2.2) update license_message if process date has changed
				if @process_date <> (select process_date from license_message where license_message_id = @current_AR_license_message_id) and @current_AR_message_status_id = 1
					begin
				--	print '2.2.2) update license_message process date'
						insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
						select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
						from license_message
						where license_message_id = @current_AR_license_message_id

						update license_message
						set process_date = @process_date,
							end_date = @end_date,
							archive_date = @archive_date,
							last_modified_date = getdate()
						where license_message_id = @current_AR_license_message_id
		
					end
		
				-- 2.3) update license_message_values 
				if @current_AR_message_status_id = 1
					begin
						-- 2.3.1) create table
						declare @license_message_value table (message_value_type_id tinyint, value_i
d int)

						insert into @license_message_value(message_value_type_id, value_id)
						select v.message_value_type_id, t.value_id
						from message_value_type v
						inner join (select message_value_type_name, value_id
									from [dbo].[fn_key_value_to_table](@license_message_value_str)) t
							on v.message_value_type_name = t.message_value_type_name

						-- 2.3.2) update and delete
						insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
						select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
						from @license_message_value nv
						full join license_message_value v
							on nv.message_value_type_id = v.message_value_type_id
						where v.license_message_id = @current_AR_license_message_id and ((nv.value_id <> v.value_id) or nv.value_id is null) and v.message_value_type_id <> 1

						update license_message_value
						set value_id = nv.value_id
						from @license_message_value nv
						full join license_message_value v
							on nv.message_value_type_id = v.message_value_type_id
						where v.license_message_id = @current_AR_license_message_id and nv.value_id <> v.value_id and v.message_value_type_id <> 1

						delete from license_message_value
						where license_message_value_id in (select v.license_message_value_id
						from @license_message_value nv
						full join license_message_value v
							on nv.message_value_type_id = v.message_value_type_id
						where v.license_message_id = @current_AR_license_message_id and nv.value_id is null and v.message_value_type_id <> 1)

						-- 2.3.3) insert	
						insert into license_message_value(license_message_id, message_value_type_id, value_id)	
						select @current_AR_license_message_id, message_value_type_id, value_id
						from @license_message_value
						where message_value_type_id not in (select message_value_type_id from license_message_value where license_message_id = @current_AR_license_message_id)
					end
			end
				
		-- 3.0) If autorenewal campaign archive message archive message
		if @message_key is not null and @message_campaign_class_id = 5
			begin
				declare @ar_campaign_license_message_id int

				select @ar_campaign_license_message_id = license_message_id from license_message where license_message_key = @message_key

				-- 3.1) archive autorenewal license_message data
				insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
				select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
				from license_message
				where license_message_id = @ar_campaign_license_message_id
				
				insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
				select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
				from license_message_value v
				where v.license_message_id = @ar_campaign_license_message_id
			
				-- 3.2) delete message
				delete from license_message_value where license_message_id = @ar_campaign_license_message_id
				delete from license_message where license_message_id = @ar_campaign_license_message_id	
			end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_license_message_deprovision]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_message_update_license_message_deprovision]

(
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2020-12-22	esmart		Initial creation.

	DESCRIPTION
	Manage deprovisioning messages   
*/

AS

	declare @message_type_id int,
			@transaction_date datetime,
			@sky_template_id tinyint,
			@reregister tinyint,
			@sfdc_update_json nvarchar(max),
			@sfdc_template_name varchar(50),
			@order_header_id int,
			@license_message_id int,
			@response_code int,
			@message varchar(100)
			

begin try

	select @message_type_id = 19, @transaction_date = getdate()

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check for existing messages
	declare @active_license_message table (license_message_id int, message_campaign_id int, message_campaign_class_id tinyint, license_id int, message_type_id int, message_status_id int, process_date datetime, deprovision_type varchar(50), sfdc_case_type_name varchar(50), sky_update_type_name varchar(50)) 

	insert into @active_license_message(license_message_id, message_campaign_id, message_campaign_class_id, license_id, message_type_id, message_status_id, process_date, deprovision_type,sfdc_case_type_name, sky_update_type_name)
	select m.license_message_id, m.message_campaign_id, m.message_campaign_class_id, m.license_id, m.message_type_id, m.message_status_id, m.process_date,		
		json_value(j.campaign_extension_json,'$.deprovision_type') as deprovision_type,
		json_value(j.campaign_extension_json,'$.sfdc_case_type_name') as sfdc_case_type_name,
		json_value(j.campaign_extension_json,'$.sky_update_type_name') as sky_update_type_name 
	from license_message m 
	inner join message_campaign_extension_json j
		on j.message_campaign_id = m.message_campaign_id
	cross apply fn_license_select_license_profile(m.license_id) lp
	outer apply fn_product_select_product_extension(j.campaign_extension_json) f
	where m.message_type_id = @message_type_id and m.message_status_id in (1,3) and m.license_id = @license_id and 
		j.license_category_id = lp.license_category_id and f.product_platform_id = lp.product_platform_id

	-- select '@active_license_message', * from @active_license_message

	-- 1.2) find active campaigns
	declare @active_campaigns table (message_campaign_id int, message_campaign_class_id tinyint, license_id int, message_type_id int, process_date datetime, deprovision_type varchar(50), sfdc_case_type_name varchar(50), sky_update_type_name varchar(50)) 

	insert into @active_campaigns(message_campaign_id, message_campaign_class_id, license_id, message_type_id, process_date, deprovision_type, sfdc_case_type_name, sky_update_type_name)
	select c.message_campaign_id, c.message_campaign_class_id,lp.license_id, @message_type_id as message_type_id, 
		case 
			when p.message_measure_point_id = 2 then dateadd(dd,mp.message_measure_days,lp.expiration_date)
		end as process_date,		
		json_value(j.campaign_extension_json,'$.deprovision_type') as deprovision_type,
		json_value(j.campaign_extension_json,'$.sfdc_case_type_name') as sfdc_case_type_name,
		json_value(j.campaign_extension_json,'$.sky_update_type_name') as sky_update_type_name	
	from message_campaign c
	inner join message_campaign_class cc
		on cc.message_campaign_class_id = c.message_campaign_class_id
	inner join message_campaign_license_category mlc
		on mlc.message_campaign_id = c.message_campaign_id
	inner join license_ca
tegory lc
		on lc.license_category_id = mlc.license_category_id
	inner join message_campaign_measure_point mp
		on mp.message_campaign_id = c.message_campaign_id
	inner join message_measure_point p
		on p.message_measure_point_id = mp.message_measure_point_id
	inner join message_campaign_extension_json j 
		on j.message_campaign_id = c.message_campaign_id and j.license_category_id = lc.license_category_id
	outer apply fn_product_select_product_extension(j.campaign_extension_json) f
	cross apply fn_license_select_license_profile(@license_id) lp
	where c.message_campaign_class_id = 10 and mlc.license_category_id = lp.license_category_id 
		and f.product_platform_id = lp.product_platform_id
		
	-- select '@active_campaigns', * from @active_campaigns

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update messages
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) update existing messages
		
		-- 2.1.1) license_message_archive
		insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, license_message_archive_date, message_campaign_id, message_campaign_class_id)
		select m.license_message_id, m.license_id, m.license_message_key, m.message_type_id, m.message_status_id, m.insert_date, m.process_date, m.end_date, m.archive_date, @transaction_date, m.message_campaign_id, m.message_campaign_class_id
		from @active_campaigns ac
		inner join @active_license_message lm
			on lm.message_campaign_id = ac.message_campaign_id
		inner join license_message m
			on m.license_message_id = lm.license_message_id 
		where ac.process_date <> lm.process_date 

		-- 2.1.2) update license_message
		update m 
		set m.process_date = ac.process_date, m.last_modified_date = @transaction_date
		from @active_campaigns ac
		inner join @active_license_message lm
			on lm.message_campaign_id = ac.message_campaign_id
		inner join license_message m
			on m.license_message_id = lm.license_message_id 
		where ac.process_date <> lm.process_date

	-- 2.2) insert new messages
	insert into license_message(license_id, message_type_id, process_date, message_campaign_id, message_campaign_class_id, insert_date, last_modified_date)
	select ac.license_id, @message_type_id, ac.process_date, ac.message_campaign_id, ac.message_campaign_class_id, @transaction_date, @transaction_date
	from @active_campaigns ac
	left join @active_license_message lm
		on lm.message_campaign_id = ac.message_campaign_id and (lm.message_status_id = 1 or (lm.message_status_id = 3 and ac.process_date = ac.process_date))
	where lm.message_campaign_id is null

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) process messages
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) process automated messages

		-- 3.1.1) get template for automated sky_update
		select @sky_template_id = t.sky_template_id, @reregister = 0, @license_message_id = m.license_message_id
		from license_message m 
		inner join message_campaign_extension_json j
			on j.message_campaign_id = m.message_campaign_id
		cross apply fn_license_select_license_profile(m.license_id) lp
		outer apply fn_product_select_product_extension(j.campaign_extension_json) f
		inner join sky_template t
			on t.sky_template_name =  json_value(j.campaign_extension_json,'$.sky_template_name')
		where m.message_type_id = @message_type_id and m.message_status_id = 1 and m.lic
ense_id = @license_id and 
			j.license_category_id = lp.license_category_id and f.product_platform_id = lp.product_platform_id and
			m.process_date < @transaction_date and json_value(j.campaign_extension_json,'$.deprovision_type') = 'automated'
	
		-- 3.1.2) usp_sky_insert_update
		if @sky_template_id is not null
			begin
				exec usp_sky_insert_update @license_id = @license_id, @sky_template_id = @sky_template_id, @process_date = @transaction_date, @reregister = @reregister

				insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, license_message_archive_date, message_campaign_id, message_campaign_class_id)
				select m.license_message_id, m.license_id, m.license_message_key, m.message_type_id, m.message_status_id, m.insert_date, m.process_date, m.end_date, m.archive_date, @transaction_date, m.message_campaign_id, m.message_campaign_class_id
				from license_message m
				where m.license_message_id = @license_message_id

				update license_message
				set message_status_id = 3, last_modified_date = @transaction_date
				where license_message_id = @license_message_id
			end

	-- 3.2) process case messages

		-- 3.2.1)
		select @sfdc_update_json = (select (select lp.license_category_id, lp.license_category_name, lp.product_platform_id, lp.product_platform_name, ct.sfdc_case_type_id, ct.sfdc_case_type_name, lp.license_id, lp.keycode
									from license_message m 
									inner join message_campaign_extension_json j
										on j.message_campaign_id = m.message_campaign_id
									cross apply fn_license_select_license_profile(m.license_id) lp
									outer apply fn_product_select_product_extension(j.campaign_extension_json) f
									inner join sfdc_case_type ct
										on ct.sfdc_case_type_name = json_value(j.campaign_extension_json,'$.sfdc_case_type_name')
									where m.message_type_id = @message_type_id and m.message_status_id = 1 and m.license_id = @license_id and 
										j.license_category_id = lp.license_category_id and f.product_platform_id = lp.product_platform_id and
										m.process_date < @transaction_date and json_value(j.campaign_extension_json,'$.deprovision_type') = 'case'
								for json path) as case_items
								for json path, without_array_wrapper)
	
		select @license_message_id = m.license_message_id
		from license_message m 
		inner join message_campaign_extension_json j
			on j.message_campaign_id = m.message_campaign_id
		cross apply fn_license_select_license_profile(m.license_id) lp
		outer apply fn_product_select_product_extension(j.campaign_extension_json) f
		inner join sfdc_case_type ct
			on ct.sfdc_case_type_name = json_value(j.campaign_extension_json,'$.sfdc_case_type_name')
		where m.message_type_id = @message_type_id and m.message_status_id = 1 and m.license_id = @license_id and 
			j.license_category_id = lp.license_category_id and f.product_platform_id = lp.product_platform_id and
			m.process_date < @transaction_date and json_value(j.campaign_extension_json,'$.deprovision_type') = 'case'

		-- 3.2.2) insert sfdc_opportunity_update
		if @sfdc_update_json is not null and @sfdc_update_json <> '{}'
			begin
				select @sfdc_template_name = 'create_case'

				exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = @sfdc_template_name, @order_header_id = @order_header_id, @sfdc_update_json = @sfdc_update_json

				insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date, archive_date, license_message_archive_date, message_campaign_id, message_campaign_class_id)
				select m.license_message_id, m.license_id, m.license_message_key, m.message_type_id, m.message_status_id, m.insert_date, m.process_date, m.end_date, m.archive_date, @transaction_date, m.message_campaign_id, m.message_campaign_cla
ss_id
				from license_message m
				where m.license_message_id = @license_message_id

				update license_message
				set message_status_id = 3, last_modified_date = @transaction_date
				where license_message_id = @license_message_id
			end
		
	
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_license_messages]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_update_license_messages]

(
		@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2010-11-16	esmart		Initial creation
	2010-12-14	esmart		Change logic for message_measure_point
	2011-02-17	esmart		Add better archiving
	2011-07-22	esmart		New message_message_point
	2013-07-19	esmart		BBY Tech Support
	2013-08-25	esmart		Update for message_campaign_trial
	2014-01-29	esmart		Archive runtime messages class

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_distribution_method_id int,
			@license_seats int,
			@license_category_id int,
			@license_type_id int,
			@license_status_id int,
			@base_capability_id int,
			@opt_in int,
			@capability_activation_date datetime,
			@capability_expiration_date datetime,
			@subscription_start_date datetime,
			@subscription_expiration_date datetime,
			@trial tinyint,
			@months int,
			@hard_cancel int,
			@bestbuy_adjustment int,
			@subscription_type_id int,
			@autorenewal_opt_id int,
			@subscription_id int,
			@cart_discount_id int,
			@response_code int,
			@message varchar(100)

	begin try

	--------------------------------------------------------------------------------------------------------------------------------
	-- 1) select license date
	--------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get license details
		select @license_distribution_method_id = license_distribution_method_id,
				@license_seats = isnull(s.license_seats,1),
				@license_category_id = isnull(lcl.license_category_id,dbo.fn_GetLicenseCategoryId(@license_id)),
				@opt_in = isnull(c.opt_in,1),
				@license_type_id = l.license_type_id,
				@autorenewal_opt_id = case
											when al.license_attribute_license_value = 1 then 1
											else 0
									end,
				@license_status_id = l.license_status_id
		from license l with (nolock)
		left join license_seat s with (nolock)
			on l.license_id = s.license_id
		left join license_category_license lcl with (nolock)
			on l.license_id = lcl.license_id
		left join customer c with (nolock)
			on l.customer_id = c.customer_id
		left join license_attribute_license al
			on l.license_id = al.license_id
		where l.license_id = @license_id

		-- 1.1.1) OEM keycodes no messages
		if @license_type_id in (2,3)
			begin
			return
			end
	
	-- 1.2) @base_capability_id
		select @base_capability_id = base_capability_id from license_category where license_category_id = @license_category_id

	-- 1.3) capability data
		select @capability_activation_date = capability_activation_date,
				@capability_expiration_date = capability_expiration_date
		from license_capability with (nolock)
		where license_id = @license_id and capability_id = @base_capability_id

		-- 1.4.1) if capability expiration date is not set the exit
		if @capability_expiration_date is null 
			begin
			return
			end

	-- 1.4) Best Buy data
		select @bestbuy_adjustment = 39

		select @subscription_id = s.subscription_id,
				@subscription_type_id = s.subscription_type_id,
				@subscription_start_date = s.start_date,
				@subscription_expiration_date = case
											when s.cancel_reason is not null then s.cancel_date
											when s.start_date is not null and s.cancel_reason is null and s.expiration_date is null then @capability_expiration_date
											else s.expiration_date
										end,
				@hard_cancel = case
								when s.cancel_reason like '1%' or s.opt_status = 1 then 1
								else 0
							end
		from subscription s with (nolock)
		where license_id = @license_id

		-- 1.4.1) subscription_external
		if (select count(*) from subscription_external where subscription_id = @subscription_id) > 0
			begin
			select @subscription_type_id = subscription_type_id from
 subscription_external where subscription_id = @subscription_id
			end
			
	-- 1.5) trial
		select 	@trial = case when count(*) > 0 then 1 else 0 end
		from license_capability with (nolock)
		where license_id = @license_id and capability_type_id in (2,3)

	-- 1.6) set @months to support the dynamic calculation of days remaining to be in the 6 months remaining
		select @months = -7
	
--	select autorenewal_opt_id = @autorenewal_opt_id, trial = @trial, base_capability_id = @base_capability_id, opt_in = @opt_in, license_distribution_method_id = @license_distribution_method_id, license_seats = @license_seats, license_category_id = @license_category_id, subscription_start_date = @subscription_start_date, subscription_expiration_date = @subscription_expiration_date, capability_activation_date = @capability_activation_date, capability_expiration_date = @capability_expiration_date

	--------------------------------------------------------------------------------------------------------------------------------
	-- 2) select campaign data
	--------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) find existing campaigns
		declare @message_campaigns_current table (message_campaigns_id int identity(1,1), license_message_id int, message_campaign_id int, message_duration_days int, process_date datetime, end_date datetime, archive_date datetime,new_process_date datetime, new_end_date datetime)

		insert into @message_campaigns_current(license_message_id, message_campaign_id, message_duration_days, process_date, end_date, archive_date, new_process_date, new_end_date)
		select m.license_message_id, c.message_campaign_id, message_duration_days, process_date, end_date, archive_date,
				new_process_date = case 
									when message_measure_point_id = 1 then dateadd(dd,message_measure_days,@capability_activation_date)
									when message_measure_point_id = 2 and message_measure_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
									when message_measure_point_id = 2 and message_measure_days <> -180 then dateadd(dd,message_measure_days,@capability_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 1 then dateadd(dd,message_measure_days,@subscription_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 0 then dateadd(dd,message_measure_days+@bestbuy_adjustment,@subscription_expiration_date)
									when message_measure_point_id = 4 then dateadd(dd,message_measure_days,@capability_activation_date)
									when message_measure_point_id = 5 then message_campaign_start_date
								end,
				new_end_date = case
									when message_measure_point_id = 1 then dateadd(dd,message_measure_days+message_duration_days,@capability_activation_date)
									when message_measure_point_id = 2 then dateadd(dd,message_measure_days+message_duration_days,@capability_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 1 then dateadd(dd,message_measure_days+message_duration_days,@subscription_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 0 then dateadd(dd,message_measure_days+message_duration_days+@bestbuy_adjustment,@subscription_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days <> -180 then dateadd(dd,message_measure_end_days,@capability_expiration_date)
									when message_measure_point_id = 5 then message_campaign_end_date
								end
		from license_message m with (nolock)
		--left join license_message_value v with (nolock)
		--	on m.license_message_id = v.license_message_id
		inner join mes
sage_campaign c with (nolock)
			on m.message_campaign_id = c.message_campaign_id
		inner join message_campaign_measure_point mp with (nolock)
			on c.message_campaign_id = mp.message_campaign_id
		where m.license_id = @license_id and c.message_campaign_class_id in (2,3)

	-- 2.2) insert into archive table
	declare @message_campaigns_current_archive table (license_message_id int)
	
		-- 2.2.1) date changes
		insert into @message_campaigns_current_archive(license_message_id)
		select license_message_id from @message_campaigns_current where process_date <> new_process_date or end_date <> new_end_date

		-- 2.2.2) license profile changes
		insert into @message_campaigns_current_archive(license_message_id)
		select license_message_id
		from @message_campaigns_current
		where license_message_id not in (select t.license_message_id
										from @message_campaigns_current t
										inner join message_campaign c
											on t.message_campaign_id = c.message_campaign_id
										inner join message_campaign_class cc with (nolock)
											on c.message_campaign_class_id = cc.message_campaign_class_id
										inner join message_campaign_seat s with (nolock)
											on c.message_campaign_id = s.message_campaign_id
										inner join message_campaign_license_category lc with (nolock)
											on c.message_campaign_id = lc.message_campaign_id
										inner join message_campaign_email_election e with (nolock)
											on c.message_campaign_id = e.message_campaign_id
										inner join message_campaign_measure_point mp with (nolock)
											on c.message_campaign_id = mp.message_campaign_id
										inner join message_campaign_autorenewal a with (nolock)
											on c.message_campaign_id = a.message_campaign_id
										inner join message_campaign_trial ct with (nolock)
											on c.message_campaign_id = ct.message_campaign_id
										where ct.trial = @trial
											and s.license_seats = @license_seats 
											and lc.license_category_id = @license_category_id
											and e.message_email_opt_id = @opt_in
											and a.autorenewal_opt_id = @autorenewal_opt_id
											and c.message_campaign_enabled in (1,2)
											and c.message_campaign_class_id = 2)

		-- 2.2.3) @subscription_type_id
		if @subscription_type_id is not null	
			begin
			insert into @message_campaigns_current_archive(license_message_id)
			select distinct license_message_id
			from @message_campaigns_current
			where license_message_id not in (select license_message_id
											from @message_campaigns_current c
											inner join message_campaign_subscription_type t
												on c.message_campaign_id = t.message_campaign_id
											where t.subscription_type_id = @subscription_type_id)
			end

	-- 2.3) archive messages

		-- 2.3.1) insert license_message_value_archive and delete license_message
			insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
			select license_message_value_id, license_message_id, message_value_type_id, value_id
			from license_message_value with (nolock)
			where license_message_id in (select license_message_id from @message_campaigns_current_archive)

			delete from license_message_value
			where license_message_id in (select license_message_id from @message_campaigns_current_archive)
			
		-- 2.3.2) insert license_message_value_archive and delete license_message
			
			insert into license_message_archive(license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
			select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
			from license_message with (nolock)
			where license_message_id in (select license_message_id from @message_campaigns_current_archive)

			delete from license_message
			where license_message_id in (select license_message_id from @message_campaigns_current_archive)

	-
- 2.4) find matching campaigns
		
		declare @message_campaign table (message_campaign_id int)	

		-- 2.4.1) get campaigns matching distribution methods
		insert into @message_campaign(message_campaign_id) 
		select message_campaign_id from message_campaign with (nolock)
		except
		select message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id = @license_distribution_method_id and inclusive = 0
		except
		(select message_campaign_id from message_campaign with (nolock)
		intersect 
		select distinct message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id <> @license_distribution_method_id and inclusive = 1
		except
		select distinct message_campaign_id 
		from message_campaign_license_distribution_method with (nolock)
		where license_distribution_method_id = @license_distribution_method_id and inclusive = 1)
		
		-- 2.4.2) insert matching campaigns into table variable
		declare @message_campaigns table (message_campaigns_id int identity(1,1), message_campaign_id int, next_message_campaign_id int, message_duration_days int, process_date datetime, end_date datetime, archive_date datetime)

		insert into @message_campaigns(message_campaign_id, next_message_campaign_id, message_duration_days, process_date, end_date, archive_date)
		select c.message_campaign_id,
				ms.next_message_campaign_id,
				message_duration_days,
				process_date = case
									when message_measure_point_id = 1 then dateadd(dd,message_measure_days,@capability_activation_date)
									when message_measure_point_id = 2 and message_measure_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
									when message_measure_point_id = 2 and message_measure_days <> -180 then dateadd(dd,message_measure_days,@capability_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 1 then dateadd(dd,message_measure_days,@subscription_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 0 then dateadd(dd,message_measure_days+@bestbuy_adjustment,@subscription_expiration_date)
									when message_measure_point_id = 4 then dateadd(dd,message_measure_days,@capability_activation_date)
									when message_measure_point_id = 5 then message_campaign_start_date
								end,
				end_date = case
									when message_measure_point_id = 1 then dateadd(dd,message_measure_days+message_duration_days,@capability_activation_date)
									when message_measure_point_id = 2 then dateadd(dd,message_measure_days+message_duration_days,@capability_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 1 then dateadd(dd,message_measure_days+message_duration_days,@subscription_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 0 then dateadd(dd,message_measure_days+message_duration_days+@bestbuy_adjustment,@subscription_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days <> -180 then dateadd(dd,message_measure_end_days,@capability_expiration_date)
									when message_measure_point_id = 5 then message_campaign_end_date
								end,
				archive_date = case
									when message_measure_point_id = 1 then dateadd(dd,message_measure_days+message_duration_days+30,@capability_activation_date)
									when message_measure_point_id = 2 then dateadd(dd,message_measure_days+message_duration_days+30,@capability_expiration_date)
									when message_measure_point_id = 3 and @hard_cancel = 1 then dateadd(dd,message_measure_days+message_duration_days+30,@subscription_expiration_date)
									when m
essage_measure_point_id = 3 and @hard_cancel = 0 then dateadd(dd,message_measure_days+message_duration_days+@bestbuy_adjustment+30,@subscription_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days = -180 then dateadd(dd,-(datediff(dd,dateadd(dd,1,dateadd(mm,@months,@capability_expiration_date)),@capability_expiration_date)),@capability_expiration_date)
									when message_measure_point_id = 4 and message_measure_end_days <> -180 then dateadd(dd,message_measure_end_days+30,@capability_expiration_date)
									when message_measure_point_id = 5 then dateadd(dd,30,message_campaign_end_date)
								end
		from message_campaign c with (nolock)
		inner join message_campaign_class cc with (nolock)
			on c.message_campaign_class_id = cc.message_campaign_class_id
		inner join message_campaign_seat s with (nolock)
			on c.message_campaign_id = s.message_campaign_id
		inner join message_campaign_license_category lc with (nolock)
			on c.message_campaign_id = lc.message_campaign_id
		inner join message_campaign_email_election e with (nolock)
			on c.message_campaign_id = e.message_campaign_id
		inner join message_campaign_measure_point mp with (nolock)
			on c.message_campaign_id = mp.message_campaign_id
		inner join message_campaign_autorenewal a with (nolock)
			on c.message_campaign_id = a.message_campaign_id
		inner join message_campaign_trial ct with (nolock)
			on c.message_campaign_id = ct.message_campaign_id
		left join message_campaign_sequence ms with (nolock)
			on c.message_campaign_id = ms.message_campaign_id
		where c.message_campaign_id in (select message_campaign_id from @message_campaign) 
			and c.message_campaign_id not in (select m.message_campaign_id
											from license_message m with (nolock)
											where m.license_id = @license_id)
			and ct.trial = @trial
			and s.license_seats = @license_seats 
			and lc.license_category_id = @license_category_id
			and e.message_email_opt_id = @opt_in
			and a.autorenewal_opt_id = @autorenewal_opt_id
			and c.message_campaign_enabled = 1
			and c.message_campaign_class_id in (2)
			and c.message_campaign_start_date <= getdate() and (c.message_campaign_end_date > getdate() or c.message_campaign_end_date is null)
		order by process_date	

		-- 2.4.3) remove campaigns that are passed
		delete from @message_campaigns where end_date < getdate()

		-- 2.4.4) remove message campaigns with prior sequence campaigns
		delete from @message_campaigns where message_campaign_id in (select next_message_campaign_id from @message_campaigns)

		delete from @message_campaigns where message_campaign_id in (select s.next_message_campaign_id 		
																	from @message_campaigns_current t
																	inner join license_message m
																		on t.license_message_id = m.license_message_id
																	inner join message_campaign_sequence s
																		on t.message_campaign_id = s.message_campaign_id
																	where m.message_status_id in (1,2))

		-- 2.4.5) subscription type
		if @subscription_type_id is not null
			begin
			delete from @message_campaigns where message_campaign_id not in (select c.message_campaign_id
																		from @message_campaigns c
																		inner join message_campaign_subscription_type t
																			on c.message_campaign_id = t.message_campaign_id
																		where t.subscription_type_id = @subscription_type_id)
			end

	--------------------------------------------------------------------------------------------------------------------------------
	-- 3) insert license_message
	--------------------------------------------------------------------------------------------------------------------------------

	declare @message_campaign_id int,
			@message_type_id int,
			@process_date datetime,
			@end_date datetime,
			@archive_date datetime,
			@license_message_id int,
			@message_value_type_id tinyint,
			@message_campaigns_id int,
			@max_message_campaigns_id int,
			@licen
se_message_value_str varchar(max)

	-- 3.1) create loop
	select @message_campaigns_id = min(message_campaigns_id),
			@max_message_campaigns_id = max(message_campaigns_id) 
	from @message_campaigns

	while @message_campaigns_id <= @max_message_campaigns_id
		begin
		-- 3.2 select values
		select @message_type_id = 1,
				@process_date = process_date,
				@end_date = end_date,
				@archive_date = archive_date,
				@message_campaign_id = c.message_campaign_id
		from @message_campaigns c
		where message_campaigns_id = @message_campaigns_id

		-- 3.2.1) check for subscription discount 
		if @subscription_id is not null 
			begin
				select @cart_discount_id = d.cart_discount_id
				from subscription_message m with (nolock)
				inner join subscription_message_promo_campaign c with (nolock)
					on m.promo_type = c.promo_type
				inner join subscription_message_promo_discount d with (nolock)
					on m.promo_sku = d.promo_sku
				where m.subscription_id = @subscription_id and c.message_campaign_id = @message_campaign_id
			end
		else
		-- 3.2.2) check for message campaign discount
			begin
			select @cart_discount_id = cart_discount_id from message_campaign_cart_discount where message_campaign_id = @message_campaign_id
			end
	

			select	@license_message_value_str = case
												when @cart_discount_id is not null then 'message_campaign_id='+ convert(varchar(20),@message_campaign_id)+',cart_discount_id='+convert(varchar(20),@cart_discount_id)
												else 'message_campaign_id='+ convert(varchar(20),@message_campaign_id)
											end


		if @message_campaign_id is not null
			begin
			print ' 3.3) insert license_message'
			-- 3.3) insert license_message
			exec usp_message_insert_license_message @license_id,@message_type_id,@process_date,@end_date,@archive_date,@license_message_value_str,@license_message_id output
			end

		select @message_campaign_id = null
		select @cart_discount_id = null
		select @message_campaigns_id = @message_campaigns_id+1
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_license_usage_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_update_license_usage_license]


	
/*	
	DATE		AUTHOR		REMARKS
	2015-07-06	acoffel		Initial creation
	
	DESCRIPTION
	insert license usage records
	
*/

as
	
	set nocount on				
	set concat_null_yields_null on
	set ansi_warnings on
	set ansi_padding on
	set arithabort on	

	declare	@days_back int,
			@response_code int,
			@message varchar(100)

	select @days_back = 30

	
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update existing records
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	update l
	set  l.devices = u.devices,
		l.activity_date = u.activity_date,
		last_modified_date = getdate()
	from license_usage_license l
	inner join license_usage u
		on l.license_id = u.license_id 
	where l.activity_date < u.activity_date
	and l.devices <> u.devices

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert new records
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into license_usage_license (license_id, devices, activity_date, insert_date, last_modified_date)
	select distinct u.license_id, u.devices, u.activity_date, getdate(), getdate()
	from license_usage u with (nolock)
	inner join (select license_id, max(activity_date) as activity_date
				from license_usage with (nolock) 
				group by license_id) lu on u.license_id = lu.license_id and u.activity_date = lu.activity_date
	inner join license_summary s with (nolock)
		on u.license_id = s.license_id
	where not exists (select *
					from license_usage_license l with (nolock)
					where u.license_id = l.license_id)
	and s.capability_expiration_date >= getdate() - @days_back


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update license_usage_license failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_message_campaign]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_update_message_campaign]

(
		@message_campaign_id int,
		@message_campaign_name varchar(65),
		@message_campaign_description varchar(256),
		@message_campaign_class_id tinyint,
		@message_campaign_enabled tinyint,
		@message_campaign_start_date datetime,
		@message_campaign_end_date datetime,
		@message_measure_point_id tinyint,
		@message_measure_days INT,
		@message_measure_end_days INT,
		@message_campaign_priority_id INT = NULL,
		@message_duration_days INT,
		@modified_by VARCHAR(20) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2010-12-08	esmart		Initial creation.
	2011-07-22	esmart		Add message_campaign_autorenewal
	2012-12-06	esamrt		Modify insert
	2018-05-25	mrobbins	extended message_campaign_name
	2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968
	2026-05-01	jberry		US-4774432 - Added sec 2.3 to update message campaign priority

	DESCRIPTION
	
*/

AS
	SET NOCOUNT ON				

	DECLARE	@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	IF @modified_by IS NULL
		BEGIN
			SELECT @modified_by = SUSER_SNAME()
		END
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	-- 2.1) update message_campaign
		UPDATE dbo.message_campaign
		SET message_campaign_name = @message_campaign_name,
			message_campaign_description = @message_campaign_description,
			message_campaign_class_id = @message_campaign_class_id,
			message_campaign_enabled = @message_campaign_enabled,
			message_campaign_start_date = @message_campaign_start_date,
			message_campaign_end_date = @message_campaign_end_date,
			modified_by = @modified_by,
			modified_date = GETDATE()
		WHERE message_campaign_id = @message_campaign_id;

	-- 2.2) update message_campaign_measure_point
		UPDATE dbo.message_campaign_measure_point
		SET message_measure_point_id = @message_measure_point_id,
			message_measure_days = @message_measure_days,
			message_measure_end_days = @message_measure_end_days,
			message_duration_days = @message_duration_days,
			modified_by = @modified_by,
			modified_date = GETDATE()
		WHERE message_campaign_id = @message_campaign_id;

	-- 2.3) update message_campaign_message_priority
		IF @message_campaign_priority_id IS NOT NULL
		BEGIN
			UPDATE dbo.message_campaign_message_priority
			SET message_campaign_priority_id = @message_campaign_priority_id,
				modified_by = @modified_by,
				modified_date = GETDATE()
			WHERE message_campaign_id = @message_campaign_id;
		END;

	-- 2.4) update licensing
		EXEC dbo.usp_licensing_insert_static_content_update 'message_content';
	
	
	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message is null THEN 'insert failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = db_name()
		EXEC usp_Lo
gError @ErrorDB = @DBName
		
	END CATCH;
	


GO
