        -- 1.18) insert dbo.message_campaign_app_store_status
        DELETE FROM dbo.message_campaign_app_store_status WHERE message_campaign_id = @message_campaign_id 

        IF @app_store_status_id_list IS NULL OR @app_store_status_id_list = '' OR @app_store_status_id_list = '0'
            BEGIN
                INSERT INTO dbo.message_campaign_app_store_status(message_campaign_id, app_store_status, insert_by, Modified_by) VALUES (@message_campaign_id, NULL, @insert_by, @insert_by)
            END
        ELSE
            BEGIN
