            END

		-- 1.19) insert dbo.message_campaign_allstate
		DELETE FROM dbo.message_campaign_allstate WHERE message_campaign_id = @message_campaign_id

		--has idp
		if ISNULL(@allstate_has_idp_list, '') > ''
