			end

              
		-- 1.20) insert message_campaign_child_license 
		
		DELETE mccl
		FROM dbo.message_campaign_child_license mccl 
		WHERE mccl.message_campaign_id = @message_campaign_id;

		-- child-capability-type
		IF ISNULL( @child_license_capability_type_list, '' ) > '' BEGIN

