					'child-license-category',
					dimension_value = f.integer_value
				FROM dbo.fn_integer_string_to_table( @child_license_category_list ) f

			END

		 -- 1.21) insert dbo.message_campaign_seatcount_enforcement

		DELETE FROM message_campaign_seat_count_enforcement
		WHERE message_campaign_id = @message_campaign_id;

