		END;

		-- 1.22) insert dbo.message_campaign_seatcount_enforcement

		DELETE FROM message_campaign_seat_overage
		WHERE message_campaign_id = @message_campaign_id;

		IF @seat_overage IS NOT NULL
		BEGIN

			INSERT INTO message_campaign_seat_overage
			(
				message_campaign_id,
				seat_overage
			)
			VALUES
			(@message_campaign_id, @seat_overage);

		END;

		-- 1.23) insert dbo.message_campaign_seatcount_enforcement

		DELETE FROM message_campaign_seat_available 
		WHERE message_campaign_id = @message_campaign_id;

		IF ISNULL( @seat_available, '' ) > ''
		BEGIN

			INSERT INTO message_campaign_seat_available
