				@message_campaign_id,
				seat_available = f.integer_value
			FROM dbo.fn_integer_string_to_table( @seat_available ) f

		END;

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_message_campaign_license_distribution_method]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_message_update_message_campaign_license_distribution_method]
(
	@message_campaign_id int,
	@inclusive tinyint,
	@license_distribution_method_id_list varchar(max) = NULL,
	@bby_s2 tinyint = null,
	@distribution_class_id_list varchar(max) = NULL,
	@insert_by VARCHAR(20) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-30	esmart		Initial creation.
	2015-06-03	acoffel		Adding class dimension as select criteria
	2026-01-20  thejashwini US-4867968 Added the @insert_by parameter to enable auditing of change history -https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4867968

	DESCRIPTION
	update 
*/


AS
	set nocount on				

	declare	@s2_list varchar(100),
			@response_code int,
			@distribution_class_id_list_2 varchar(max),
			@message varchar(100)

	begin try
	
	   IF @insert_by IS NULL
    BEGIN
        SELECT @insert_by = SUSER_SNAME()
    END

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) check to see for S2 and add all S2 distribution methods to list
	if @bby_s2 = 1
		begin
		select @s2_list = coalesce(@s2_list+', ','')+ cast(convert(varchar(10),license_distribution_method_id) as varchar(100)) 
		from subscription_distribution_method
		where license_distribution_method_id not in (select integer_value from dbo.fn_integer_string_to_table(@license_distribution_method_id_list))
		end

		if len(@license_distribution_method_id_list) > 0 and len(@s2_list) > 0
			begin
			select @license_distribution_method_id_list = @license_distribution_method_id_list+','+@s2_list
			end
		if len(@license_distribution_method_id_list) = 0 and len(@s2_list) > 0
			begin
			select @license_distribution_method_id_list = @s2_list
			end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) delete/insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	-- 2.1) delete current rows
	delete from message_campaign_license_distribution_method where message_campaign_id = @message_campaign_id

	-- 2.2) insert new rows
	if len(@license_distribution_method_id_list) > 0 and @distribution_class_id_list is NULL
		begin 
			insert into message_campaign_license_distribution_method(message_campaign_id, license_distribution_method_id, inclusive, insert_by, modified_by)
			select @message_campaign_id, license_distribution_method_id = integer_value, @inclusive, @insert_by, @insert_by
			from dbo.fn_integer_string_to_table(@license_distribution_method_id_list)
		end


	if len(@license_distribution_method_id_list) > 0 and len(@distribution_class_id_list) > 0
		begin 
			insert into message_campaign_license_distribution_method(message_campaign_id, license_distribution_method_id, inclusive, insert_by, modified_by )
			select @message_campaign_id, license_distribution_method_id = integer_value, @inclusive, @insert_by, @insert_by
			from dbo.fn_integer_string_to_table(@license_distribution_method_id_list)
			union 
			select @message_campaign_id, m.license_distribution_method_id, @inclusive, @insert_by, @ins
ert_by
			from license_distribution_method m 
			inner join license_distribution_method_channel ch
				on m.license_distribution_method_id = ch.license_distribution_method_id
			inner join distribution_class dc
				on ch.distribution_class_id = dc.distribution_class_id
			where dc.distribution_class_id in (select integer_value from dbo.fn_integer_string_to_table(@distribution_class_id_list))
		end



	if @license_distribution_method_id_list is NULL and len(@distribution_class_id_list) > 0
		begin 
			insert into message_campaign_license_distribution_method(message_campaign_id, license_distribution_method_id, inclusive, insert_by, modified_by)
			select @message_campaign_id, m.license_distribution_method_id, @inclusive, @insert_by, @insert_by
			from license_distribution_method m 
			inner join license_distribution_method_channel ch
				on m.license_distribution_method_id = ch.license_distribution_method_id
			inner join distribution_class dc
				on ch.distribution_class_id = dc.distribution_class_id
			where dc.distribution_class_id in (select integer_value from dbo.fn_integer_string_to_table(@distribution_class_id_list))
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_message_update_message_content]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_message_update_message_content]

(
	@message_content_id int,
	@message_content_name varchar(50),
	@message_action varchar(50),
	@message_content_status varchar(20),
	@message_url varchar(500),
	@message_content_image_id tinyint,
	@message_content_image_schedule_list varchar(200)
)
/*	
	DATE		AUTHOR		REMARKS
	2013-10-22	esmart		Initial creation

	DESCRIPTION
	update message_content
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) update
	update message_content
	set message_content_name = @message_content_name,
		message_action = @message_action,
		message_content_status = @message_content_status,
		message_url = @message_url,
		message_content_image_id = @message_content_image_id
	where message_content_id = @message_content_id

	-- 1.2) message_content_image_schedule_content
	delete from message_content_image_schedule_content
	where message_content_id = @message_content_id

	insert into message_content_image_schedule_content(message_content_id,message_content_image_schedule_id)
	select @message_content_id,message_content_image_schedule_id=integer_value
	from dbo.fn_integer_string_to_table(@message_content_image_schedule_list)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
