-- =============================================================================


CREATE PROCEDURE [dbo].[usp_message_update_message_cycle]

(
	@message_cycle_id int,
	@message_cycle_description varchar(50), 
	@cycles int, 
	@cycle_duration_days int, 
	@cycle_limit_days int,
	@cycle_gap_days_list varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-11-30	esmart		Initial creation.
	2013-01-14	esmart		Add check for duplicate name

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@line_id int, 
			@cycle_id int
						
	begin try

	set @response_code = 0
	set @message = 'Successfully updated message cycle'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @cycle_limit_days
	if @cycle_limit_days = 0
		begin select @cycle_limit_days = null end

	-- 1.2) @message_cycle_description
	if (select count(*) from message_cycle where message_cycle_description = @message_cycle_description and message_cycle_id <> @message_cycle_id) > 0 
		begin
			select @response_code = -120, @message = 'Duplicate @message_cycle_description'
			--select response_code = @response_code, message = @message
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) update message_cycle
	update message_cycle
	set message_cycle_description = @message_cycle_description, 
		cycles = @cycles, 
		cycle_duration_days = @cycle_duration_days, 
		cycle_limit_days = @cycle_limit_days
	where message_cycle_id = @message_cycle_id

	-- 1.2) update message_cycle_line
	declare @message_cycle_line table (cycle_id int, line_id int,cycle_gap_days int)

	select @line_id = 0, @cycle_id = 1

	while @cycles >= @cycle_id
		begin
		insert into @message_cycle_line(cycle_id, line_id) values(@cycle_id,@line_id)
		select @line_id = @line_id + 1, @cycle_id = @cycle_id + 1
		end
		
	delete from message_cycle_line where message_cycle_id = @message_cycle_id

	insert into message_cycle_line(message_cycle_id,line_id,cycle_gap_days)
	select @message_cycle_id,
			line_id, 
			t.cycle_gap_days
	from @message_cycle_line m
	left join (select cycle_id = interger_list_id, cycle_gap_days = integer_value from dbo.fn_integer_string_to_table(@cycle_gap_days_list)) t
		on m.cycle_id = t.cycle_id
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_missing_sky_keycode_create]
-- =============================================================================
CREATE procedure [dbo].[usp_missing_sky_keycode_create]

/*	
	DATE		AUTHOR		REMARKS
	2019-12-12	abelenkiy	Initial creation
	2020-01-02	abelenkiy	Added detailed summary in description, removed debug code, clarified error case titles.
	2020-02-21	abelenkiy	Updated to use SKYLAKE instead of DATAWAREHOUSE

	DESCRIPTION
	Identifies SAEP keycodes with usage in skylake that don't exist in ecom and creates through license_service.
		Pulls keycodes from daily SKYLAKE.Feed.dbo.sky_saep_usage_raw_stage table that don't exists in ecomm license table AND have DBActiveLast30Days usage.
		Writes missing keycodes to sky_active_key_sync_saep table or updates existing records to most recent values from sky_saep_usage_raw_stage.
		Identifies keycodes as error cases if criteria not met for creation in ecomm (parent doesn't exist in ecomm, distribution ID doesn't exist in ecomm, etc.
		Creates qualifying records through license_service and logs license_service_id to sky_active_key_sync_saep logging table.
		Keycodes that previously didn't pass business logic checks are re-tried daily based on most recent values.
*/

as
set nocount on;

begin try

	-------------------------------------------------------------------------------------------------
	-- 1 -- setup initial temp tables and variables and stage data for insert to logging table
	-------------------------------------------------------------------------------------------------

	-- 1.1 declare vars for loop
	declare @child_keys_id int = 1
		  , @max_row int
		  , @license_service_json nvarchar(max);

	declare @license_service table (license_service_id int, response_code int, message varchar(100));

	-- 1.2 create staging temp table for insert to logging table
	drop table if exists #saep_active_key_sync_stage;

	create table #saep_active_key_sync_stage (keycode varchar(40), marname varchar(1000), parentkeycode varchar(40), licensecategoryid int
										  , licensetype varchar(60), DBActiveLast30Days int, log_date date, effective_date date);

	-- 1.3 create temp table to loop records through license_service later
	drop table if exists #child_keys;

	create table #child_keys (child_keys_id int identity(1, 1), sky_active_key_sync_saep_id int, keycode varchar(40), effective_date date, trial int, license_seats int
						  , external_keycode varchar(40), first_name nvarchar(225), last_name nvarchar(225), customer_email varchar(100), company_name nvarchar(255));

	-- 1.4 insert all keys with usage from sky_saep_usage_raw_stage that don't exist in ecom into staging table
	insert into #saep_active_key_sync_stage (keycode, marname, parentkeycode, licensecategoryid, licensetype, DBActiveLast30Days, log_date, effective_date)
	select s.keycode, s.marname, s.parentkeycode, s.licensecategoryid, s.licensetype, s.DBActiveLast30Days, s.log_date, s.effective_date
	from SKYLAKE.Feed.dbo.sky_saep_usage_raw_stage s
		left join license l on l.keycode = s.keycode
	where (l.license_id is null and s.DBActiveLast30Days > 0) --only include records with usage

	-- 1.5 return out if staging table failed to populate
	if @@rowcount = 0
		begin
			return;
		end;

	-------------------------------------------------------------------------------------------------
	-- 2 -- update existing errors in logging table and insert new records; identify error cases
	-------------------------------------------------------------------------------------------------

	-- 2.1 if logging table already has record for keycode, update all attributes and last report values in logging table (instead of inserting duplicate records)
	-- and clear resolution_status so record can be re-checked against ecom; only do this for failure cases.
	update saks
	set saks.marname = sak
ss.marname
	  , saks.licensecategoryid = sakss.licensecategoryid
	  , saks.licensetype = sakss.licensetype
	  , saks.parentkeycode = sakss.parentkeycode
	  , saks.last_DBActiveLast30Days = sakss.DBActiveLast30Days
	  , saks.last_log_date = sakss.log_date
	  , saks.last_effective_date = sakss.effective_date
	  , saks.last_report_date = getdate()
	  , saks.resolution_status = null
	from sky_active_key_sync_saep saks
		inner join #saep_active_key_sync_stage sakss on sakss.keycode = saks.keycode
	where saks.resolution_status != 'CREATE_CHILD_LICENSE_SERVICE';

	-- 2.2 now insert records not seen before in logging table
	insert into sky_active_key_sync_saep (keycode, marname, parentkeycode, licensecategoryid, licensetype, last_DBActiveLast30Days, last_log_date, last_effective_date)
	select sakss.keycode, sakss.marname, sakss.parentkeycode, sakss.licensecategoryid, sakss.licensetype, sakss.DBActiveLast30Days, sakss.log_date, sakss.effective_date
	from #saep_active_key_sync_stage sakss
		left join sky_active_key_sync_saep saks on sakss.keycode = saks.keycode
	where saks.sky_active_key_sync_saep_id is null;

	-- 2.3.1 error case: license_distribution_method_code doesn't exist in ecom
	update saks
	set saks.resolution_status = 'INVALID_LICENSE_DISTRIBUTION_METHOD'
	from sky_active_key_sync_saep saks
		left join license_distribution_method ldm on ldm.license_distribution_method_code = substring(saks.keycode, 5, 4)
	where ldm.license_distribution_method_id is null
		  and saks.resolution_status is null;

	-- 2.3.1 error case: parent exists in derby but not in ecom
	update saks
	set saks.resolution_status = 'DERBY_PARENT_MISSING_IN_ECOM'
	from sky_active_key_sync_saep saks
		left join license l on l.keycode = saks.parentkeycode
	where saks.parentkeycode is not null
		  and l.license_id is null
		  and saks.resolution_status is null;

	-- 2.3.2 error case: parent exists in both but license type on parent not suitable for site create
	update saks
	set saks.resolution_status = 'WRONG_PARENT_LICTYPE'
	from sky_active_key_sync_saep saks
		inner join license l on l.keycode = saks.parentkeycode
	where saks.parentkeycode is not null
		  and saks.resolution_status is null
		  and l.license_type_id not in ( 2, 3 );

	-- 2.3.3 error case: derby shows no parent relationship
	update saks
	set saks.resolution_status = 'NULL_DERBY_PARENT'
	from sky_active_key_sync_saep saks
	where saks.parentkeycode is null
		  and saks.resolution_status is null;

	-------------------------------------------------------------------------------------------------
	-- 3 -- stage data for license service insert attempt into temp table and loop through
	-------------------------------------------------------------------------------------------------

	-- 3.1 insert records not caught as error cases above into temp table
	-- left join all relevant tables on the parent for the child to inherit and to be used in license service json creation
	insert into #child_keys (sky_active_key_sync_saep_id, keycode, effective_date, trial, license_seats, external_keycode, first_name, last_name, customer_email, company_name)
	select saks.sky_active_key_sync_saep_id
		 , saks.parentkeycode as keycode
		 , isnull(saks.last_log_date, dateadd(day, -1, getdate())) as effective_date--using logdate as effective_date because that's when usage is from (we probably don't want to have usage on a key from before it's created)
		 , iif(saks.licensetype like '%trial%', 1, 0) as trial, 1 as license_seats--seats hardcoded as '1' because they don't matter on children
		 , saks.keycode as external_keycode
		 , c.first_name, c.last_name, ce.customer_email
		 , isnull(c2.company_name, saks.marname) as company_name--marname used as company name if no company name is found
	from sky_active_key_sync_saep saks
		inner join license l on l.keycode = saks.parentkeycode
		left join customer c on c.customer_id = l.customer_id
		left join customer_emai
l ce on ce.customer_id = c.customer_id
									  and ce.email_status_id = 1
		left join customer_company cc on c.customer_id = cc.customer_id
		left join company c2 on c2.company_id = cc.company_id
	where saks.resolution_status is null

	-- 3.2 set max row for loop from count of records in above table
	select @max_row = @@rowcount;

	-- 3.3 begin looping if records to be created are found
	if @max_row > 0
		begin
			while @max_row >= @child_keys_id
				begin

					-- 3.3.1 create json to pass into usp_license_service_insert_service
					select @license_service_json = (select ck.keycode, ck.effective_date, ck.trial, ck.license_seats
														 , ck.external_keycode, ck.first_name, ck.last_name
														 , ck.customer_email, ck.company_name
													from #child_keys ck
													where ck.child_keys_id = @child_keys_id
												   for json path, without_array_wrapper);

					-- 3.3.2 remove previous record's license_service output from table var
					delete @license_service;

					-- 3.3.3 exec usp_license_service_insert_service and store output for writing back to logging table
					insert into @license_service (license_service_id, response_code, message)
					exec usp_license_service_insert_service @license_service_type_name = 'create_child_license'
														  , @service_json = @license_service_json
														  , @return_license_service_id = 1;

					-- 3.3.4 update logging table with resolution and license_service_id
					-- resolution = 'failure' if no output from usp_license_service_insert_service
					update saks
					set license_service_id = (select ls.license_service_id from @license_service ls)
					  , saks.resolution_status = iif((select 1 from @license_service) = 1
													 , 'CREATE_CHILD_LICENSE_SERVICE'
													 , 'LICENSE_SERVICE_FAILURE')
					from sky_active_key_sync_saep saks
						inner join #child_keys ck on ck.sky_active_key_sync_saep_id = saks.sky_active_key_sync_saep_id
					where ck.child_keys_id = @child_keys_id;

					-- 3.3.5 reset/update loop vars
					select @child_keys_id = @child_keys_id + 1, @license_service_json = null;
				end;

	-------------------------------------------------------------------------------------------------
	-- 4 -- send email if license service was attempted
	-------------------------------------------------------------------------------------------------
			-- 4.1 decare vars for send_dbmail
			declare @subject varchar(500)  = convert(varchar(50), getdate(), 23) + ' - Sky Keycodes Missing in Ecom Created'
				  , @tab	 char(1)	   = char(9)
				  , @body	 varchar(max)  = '<html><body><h3>Sky Keycodes Missing in Ecom Created</h3>
												<p>Please see the table for Sky child keycodes missing from Ecom where creation was attempted by sync process.</p>
												<table cellspacing = 20><th colspan=6 align="left" bgcolor="#DEB887">Sky Parent Keycodes Missing in Ecom Created</th>
												<tr><th align="left">keycode</th><th align="left">marname</th><th align="left">parentkeycode</th>
												<th align="left">licensecategoryid</th><th align="left">resolution_status</th><th align="left">license_service_id</th></tr>'
				  , @xml	 nvarchar(max) = cast((select saks.keycode as 'td', ' ', saks.marname as 'td', ' '
														, saks.parentkeycode as 'td', ' ', saks.licensecategoryid as 'td', ' '
														, saks.resolution_status as 'td', ' ', saks.license_service_id as 'td'
														, ' '
												   from sky_active_key_sync_saep saks
													   inner join #child_keys ck on ck.sky_active_key_sync_saep_id = saks.sky_active_key_sync_saep_id
												   where saks.resolution_status like '%LICENSE_SERVICE%'
												  for xml path('tr'), elements) as nvarchar(max));

			-- 4.2 concat body of email from values above
			set @body = @body + isnull(@xml, '') + '</table></body></html>';

			-- 4.3 execute send_dbmail
			exec msdb..sp_send_dbmail @r
ecipients = 'abelenkiy@webroot.com;cnovac@webroot.com'
									, @subject = @subject, @body_format = 'HTML', @body = @body
									, @query_result_separator = @tab, @exclude_query_output = 1
									, @query_result_no_padding = 1, @query_result_width = 1000;
		end;

end try
begin catch

	declare @dbname nvarchar(128);
	set @dbname = db_name();
	exec usp_LogError @ErrorDB = @dbname;

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mnt_tbl_DBErrorlog_archive]
-- =============================================================================

CREATE PROCEDURE dbo.usp_mnt_tbl_DBErrorlog_archive
AS
/*----------------------------------------------------------------------------

     AUTHOR: Craig Faulkner, DBA
       DATE: January 13, 2014

    SP NAME: dbo.usp_mnt_tbl_DBErrorlog_archive
DESCRIPTION: Archive eCommerce tables to eCommerce_archive

     SYNTAX: EXEC usp_mnt_tbl_DBErrorlog_archive

----------------------------------------------------------------------------*/

print ''
print 'ARCHIVING DBErrorlogTABLE STARTING'
/*
Archive process for eCommerce..DBErrorlog table
This is a delete only process.  Due to the nature of the data on 6 months is retained 
in the production table.  Older data is deleted.

20121204 CFaulkner Code implemented.

sp_spaceused DBErrorlog
select min(Add_Date), max(Add_Date) from DBErrorlog
*/
set nocount on
set deadlock_priority low;

declare @t_pkey table (Record_ID int NOT NULL PRIMARY KEY); 
declare @i int, @d int, @maxloops int, @dateminus datetime;

--Keep @i at 5000 or less help in avoiding locking.
select @d = 1000, @maxloops = 100, @dateminus = getDate()-180; -- < Days to keep (20121204 6 months per Eric Smart)
while @d = 1000 and @maxloops <> 0
begin

  insert into @t_pkey 
  select top 1000 Record_ID 
    from dbo.DBErrorlog (nolock)
    where Add_Date < @dateminus
    order by Add_Date asc;

  delete d
    from dbo.DBErrorlog d
    inner join @t_pkey t
      on d.Record_ID = t.Record_ID;
  set @d = @@rowcount; 
  print @d

  delete @t_pkey;
  select @maxloops = @maxloops - 1;
end

set nocount off

print 'ARCHIVING EBErrorlogTABE COMPLETE'
print ''

------------------------------------------------------------------------------
------------------------------------------------------------------------------
RETURN 0

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mnt_tbl_email_log_archive]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_mnt_tbl_email_log_archive]
AS
/*----------------------------------------------------------------------------

     AUTHOR: Craig Faulkner, DBA
       DATE: January 13, 2014

    SP NAME: dbo.usp_mnt_tbl_email_log_archive
DESCRIPTION: Archive eCommerce tables to eCommerce_archive
             Archive process for eCommerce..email_log table
             This is a delete only process.  Due to the nature of the data on 6 months is retained 
             in the production table.  Older data is deleted.

     SYNTAX: EXEC usp_mnt_tbl_email_log_archive

----------------------------------------------------------------------------*/

print ''
print 'ARCHIVING email_log TABLE STARTING'

exec eCommerce_Archive..usp_ArchivingTable_CompareSchema
        @source_table_catalog  = 'eCommerce'
      , @source_table_name     = 'email_log'
      , @source_table_schema   = 'dbo'
      , @archive_table_catalog = 'eCommerce_Archive'
      , @archive_table_name    = 'email_log'
      , @archive_table_schema  = 'dbo'
      , @email_to              = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com'; 

set nocount on
set deadlock_priority low;

declare @t_pkey table (email_log_id int NOT NULL PRIMARY KEY);  -- match to pk of table
declare @i int, @d int, @maxloops int, @totalcount bigint, @dateminus datetime;

--Keep @i at 5000 or less help in avoiding locking.
select @i = 444, @d = 0, @totalcount = 0, @maxloops = 200, @dateminus = getDate()-30;
while @i = 444 and @maxloops <> 0
begin

  insert into @t_pkey 
  select top 444 email_log_id 
    from dbo.email_log (nolock)
    where sent_date < @dateminus
    order by sent_date asc;

  begin transaction
    insert into eCommerce_Archive.dbo.email_log (email_log_id, email_address, email_type, email_parameters, email_body, sent_date, sent_by)
    select d.email_log_id, email_address, email_type, email_parameters, email_body, sent_date, sent_by
      from dbo.email_log d (nolock)
      inner join @t_pkey t
        on d.email_log_id = t.email_log_id;
    set @i = @@rowcount; 

    delete d
      from dbo.email_log d
      inner join @t_pkey t
        on d.email_log_id = t.email_log_id;
    set @d = @@rowcount; 

  select @totalcount = @totalcount + @d;

  if @i = @d
  begin
    commit transaction;
    delete @t_pkey;
    select @maxloops = @maxloops - 1;
    waitfor delay '000:00:01.000' -- 'Helps' to avoid locks (recommend 5 secs)
  end
  else
  begin
    rollback transaction
    raiserror (N'INSERT and DELETE counts do NOT match - Rolling back!', 16, 1);
    break;
  end
end
print '--> '+ltrim(str(@totalcount))+' rows deleted <--'
set nocount off

print 'ARCHIVING email_log TABLE COMPLETE'
print ''

------------------------------------------------------------------------------
------------------------------------------------------------------------------
RETURN 0




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mnt_tbl_prevx_update_archive_archive]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_mnt_tbl_prevx_update_archive_archive]
AS
/*----------------------------------------------------------------------------

     AUTHOR: Craig Faulkner, DBA
       DATE: January 13, 2014

    SP NAME: dbo.usp_mnt_tbl_prevx_update_archive_archive
DESCRIPTION: Archive eCommerce tables to eCommerce_archive

     SYNTAX: EXEC usp_mnt_tbl_prevx_update_archive_archive

----------------------------------------------------------------------------*/

print ''
print 'ARCHIVING prevx_update_archive TABLE STARTING'

exec eCommerce_Archive..usp_ArchivingTable_CompareSchema
        @source_table_catalog  = 'eCommerce'
      , @source_table_name     = 'prevx_update_archive'
      , @source_table_schema   = 'dbo'
      , @archive_table_catalog = 'eCommerce_Archive'
      , @archive_table_name    = 'prevx_update_archive'
      , @archive_table_schema  = 'dbo'
      , @email_to              = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com'; 

set nocount on
set deadlock_priority low;

declare @t_pkey     table (prevx_update_archive_id int NOT NULL PRIMARY KEY);  -- holds population to move
declare @t_pkey_del table (prevx_update_archive_id int NOT NULL PRIMARY KEY);  -- holds batch to move
declare @cte_cnt int, @batch_cnt int, @start_dt datetime
select  @cte_cnt = 0, @batch_cnt = 1, @start_dt = getDate();

--select all of the prevx_update_archive_id's to be processed for thie license_id range into the @t_pkey table variable.
;with cte
  as (select prevx_update_archive_id, row_number() over (partition by license_id order by license_id desc, archive_date desc) rn 
        from prevx_update_archive (nolock)) 
insert into @t_pkey (prevx_update_archive_id)
select prevx_update_archive_id from cte where RN > 1 
set @cte_cnt = @@rowcount; 

if @cte_cnt > 0
begin
--                       Date added for safety - in case of a large data
while @batch_cnt > 0 and dateadd(mi, 120, @start_dt) >  getDate()
  begin

  --get batch _del to process
  insert into @t_pkey_del (prevx_update_archive_id)
    select top 4000 prevx_update_archive_id from @t_pkey;
  set @batch_cnt = @@rowcount;

  --start transaction
  begin transaction

    --insert rows into _archive
    insert into eCommerce_archive..prevx_update_archive (prevx_update_archive_id, prevx_update_id, license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date)
    select a.prevx_update_archive_id, prevx_update_id, license_id, license_bulk_load_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date
      from dbo.prevx_update_archive a (nolock)
      inner join @t_pkey_del b
        on a.prevx_update_archive_id = b.prevx_update_archive_id;

    --delete rows from production
    delete a
      from dbo.prevx_update_archive a
      inner join @t_pkey_del b
        on a.prevx_update_archive_id = b.prevx_update_archive_id;

  --end transaction - committing before the table var delete to commit transaction faster.
  commit transaction

  --update batch _del table
  delete a
    from @t_pkey a
    inner join @t_pkey_del b
      on a.prevx_update_archive_id = b.prevx_update_archive_id;

  end
end

print '-->' + isnull(ltrim(str(@cte_cnt)),0) + 'rows deleted <--'
print 'ARCHIVING prevx_update_archive TABLE COMPLETE'
print ''


------------------------------------------------------------------------------
------------------------------------------------------------------------------
RETURN 0




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_mnt_tbl_user_emails_archive]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_mnt_tbl_user_emails_archive]
AS
/*----------------------------------------------------------------------------

     AUTHOR: Craig Faulkner, DBA
       DATE: January 13, 2014

    SP NAME: dbo.usp_mnt_tbl_user_emails_archive
DESCRIPTION: Archive eCommerce tables to eCommerce_archive
             Archive process for eCommerce..user_emails table
             This is a delete only process.  Due to the nature of the data on 6 months is retained 
             in the production table.  Older data is deleted.

     SYNTAX: EXEC usp_mnt_tbl_user_emails_archive

----------------------------------------------------------------------------*/

print ''
print 'ARCHIVING user_emails TABLE STARTING'
exec eCommerce_Archive..usp_ArchivingTable_CompareSchema
        @source_table_catalog  = 'eCommerce'
      , @source_table_name     = 'user_emails'
      , @source_table_schema   = 'dbo'
      , @archive_table_catalog = 'eCommerce_Archive'
      , @archive_table_name    = 'user_emails'
      , @archive_table_schema  = 'dbo'
      , @email_to              = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com'; 

set nocount on;
set deadlock_priority low;
--NOTE: There is no PK on this table. product_id is NOT unique.
begin transaction insdel;
  insert into eCommerce_Archive..user_emails
    select * from user_emails (nolock) where date_received < getDate() - 365;

    delete from user_emails where date_received < getDate() - 365;
commit transaction insdel;

set nocount off;
print 'ARCHIVING user_emails TABLE COMPLETE'
print ''

------------------------------------------------------------------------------
------------------------------------------------------------------------------
RETURN 0





GO
