-- PROCEDURE: [dbo].[usp_mnt_tbl_websales_Accounting_archive]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_mnt_tbl_websales_Accounting_archive]
AS
/*----------------------------------------------------------------------------

     AUTHOR: Craig Faulkner, DBA
       DATE: January 13, 2014

    SP NAME: dbo.usp_mnt_tbl_websales_Accounting_archive
DESCRIPTION: Archive eCommerce tables to eCommerce_archive

     SYNTAX: EXEC usp_mnt_tbl_websales_Accounting_archive

----------------------------------------------------------------------------*/

print ''
print 'ARCHIVING websales_Accounting TABLE STARTING'

exec eCommerce_Archive..usp_ArchivingTable_CompareSchema
        @source_table_catalog  = 'eCommerce'
      , @source_table_name     = 'websales_Accounting'
      , @source_table_schema   = 'dbo'
      , @archive_table_catalog = 'eCommerce_Archive'
      , @archive_table_name    = 'websales_Accounting'
      , @archive_table_schema  = 'dbo'
      , @email_to              = 'wr-DLGlobalDatabaseSupport@opentext.com;CARB-DBMonitoring@opentext.com'; 

set nocount on
set deadlock_priority low;

declare @t_pkey table (account_id int NOT NULL PRIMARY KEY);  -- match to pk of table
declare @i int, @d int, @maxloops int, @totalcount bigint, @dateminus datetime;

--Keep @i at 5000 or less help in avoiding locking.
select @i = 4000, @d = 0, @totalcount = 0, @maxloops = 100, @dateminus = getDate()-365;
while @i = 4000 and @maxloops <> 0
begin

  insert into @t_pkey 
  select top 4000 account_id 
    from dbo.websales_Accounting (nolock)
    where auth_batch_id < @dateminus
    order by auth_batch_id asc;

  begin transaction
    insert into eCommerce_Archive.dbo.websales_Accounting (account_id, invoice_code, product_id, quantity, extended_price, tax_item_amount, auth_batch_id, payment_method, TranProcessID, effective_date, order_item_id, vendor_order_date, capability_expiration_date, processed, finance_push_date, insert_date, insert_by, modified_date, modified_by)
    select d.account_id, invoice_code, product_id, quantity, extended_price, tax_item_amount, auth_batch_id, payment_method, TranProcessID, effective_date, order_item_id, vendor_order_date, capability_expiration_date, processed, finance_push_date, insert_date, insert_by, modified_date, modified_by
      from dbo.websales_Accounting d (nolock)
      inner join @t_pkey t
        on d.account_id = t.account_id;
    set @i = @@rowcount; 

    delete d
      from dbo.websales_Accounting d
      inner join @t_pkey t
        on d.account_id = t.account_id;
    set @d = @@rowcount; 

  select @totalcount = @totalcount + @d;

  if @i = @d
  begin
    commit transaction;
    delete @t_pkey;
    select @maxloops = @maxloops - 1;
    waitfor delay '000:00:01.000' -- 'Helps' to avoid locks (recommend 5 secs)
  end
  else
  begin
    rollback transaction
    raiserror (N'INSERT and DELETE counts do NOT match - Rolling back!', 16, 1);
    break;
  end
end
print '--> '+ltrim(str(@totalcount))+' rows deleted <--'
set nocount off

print 'ARCHIVING websales_Accounting TABLE COMPLETE'
print ''

------------------------------------------------------------------------------
------------------------------------------------------------------------------
RETURN 0




GO
