---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_monitor_message_campaign]

(@email VARCHAR(200))
   AS

/*

Date            Author         version              Remarks
============================================================
05/23/2018       ugangichetty       1.0       
  Monitor Online Message Campaign
2018-05-25		mrobbins			1.1			extended message_campaign_name
*/

DECLARE  @count INT
              ,@alertemail VARCHAR(200)
              ,@subject    VARCHAR(200)
              ,@query      NVARCHAR(4000)
              ,
@body       NVARCHAR (500);

    -- SELECT  @count=COUNT(*) from [dbo].[message_campaign] where message_campaign_enabled = 1 and message_campaign_end_date < getdate() + 365

CREATE table #campaign_alerts (
message_campaign_id int,
message_campaign_name varchar(100),
message_campaign_description varchar(256),
message_campaign_class_name VARCHAR(255),
message_campaign_enabled_description VARCHAR(255),
message_campaign_end_date datetime
)

/*
create table tempresults1 (message_campaign_id int, message_campaign_name nvarchar(65), 
--message_campaign_description varchar(50), 
message_campaign_class_id tinyint,
  message_campaign_enabled tinyint, message_campaign_start_date datetime, message_campaign_end_date datetime)
 insert into tempresults1 
 select message_campaign_id	
,
 CAST(message_campaign_name AS VARCHAR)
--, message_campaign_description
, message_campaign_class_id
, message_campaign_enabled
, message_campaign_start_date
, message_campaign_end_date
 from [dbo].[message_campaign] where message_campaign_enabled = 1 and
 message_campaign_end_date < getdate() + 365 
 
*/
--Campaigns classes where we care about both Active and Inactive status
insert into #campaign_alerts
select mc.message_campaign_id, 
       mc.message_campaign_name, 
       mc.message_campaign_description, 
       mcc.message_campaign_class_name, 
       mce.message_campaign_enabled_description, 
       message_campaign_end_date
from message_campaign mc
       INNER JOIN dbo.message_campaign_class mcc
              ON mc.message_campaign_class_id = mcc.message_campaign_class_id
       INNER JOIN dbo.message_campaign_enabled mce
              ON mc.message_campaign_enabled = mce.message_campaign_enabled
where mc.message_campaign_class_id in (1, 2, 7) --Event driven emails, Automated product campaigns, Site pricing
       and mc.message_campaign_enabled in (1, 2) --Active and Inactive
       and mc.message_campaign_end_date >= getdate()
       and mc.message_campaign_end_date <= dateadd(dd, 30, getdate()) --30 days from now


--Campaigns classes where we care about only Active status
insert into #campaign_alerts
select mc.message_campaign_id, 
       mc.message_campaign_name, 
       mc.message_campaign_description, 
       mcc.message_campaign_class_name, 
       mce.message_campaign_enabled_description, 
       message_campaign_end_date
from message_campaign mc
       INNER JOIN dbo.message_campaign_class mcc
              ON mc.message_campaign_class_id = mcc.message_campaign_class_id
       INNER JOIN dbo.message_campaign_enabled mce
              ON mc.message_campaign_enabled = mce.message_campaign_enabled
where mc.message_campaign_class_id in (3, 4, 5, 6) --Runtime, Automated email, License driven website/cart, Routing
       and mc.message_campaign_enabled = 1 --Active 
       and mc.message_campaign_end_date >= getdate()
       and mc.message_campaign_end_date <= dateadd(dd, 30, getdate()) --30 days from now


	   
SELECT  @count=COUNT(*)
 from #campaign_alerts



DECLARE @html nvarchar(MAX);
EXEC admin.dbo.spQueryToHtmlTable @html = @html OUTPUT, 
 @query = N'
select  *
from #campaign_alerts'

  SELECT @alertemail = @email
            ,@subject   = 'Online Message Campain Alerts '+@@SERVERNAME
           
	 IF @count>1
     BEGIN
              EXEC msdb.dbo.sp_send_dbmail
                           @recipients  = @alertemail
						   
                          ,@query       = @query
                       , @subject     = @subject
					   , @body        = @html
                       , @importance  = 'High'
                       , @body_format = 'HTML';
          END
  ELSE
       PRINT 'Online Message Campaign is fine '
Drop table #campaign_alerts




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_monitor_orders]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_monitor_orders] (
	@opt_args VARCHAR(20) = NULL
) AS
/*	
	DATE		AUTHOR		REMARKS
	2022-11-01	mrobbins	intial creation

	2025-01-20	gblandford	US-3040347 - RB2 - Orders Alert - Update Order monitoring job to reflect lower consumer order frequency https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=3040347
							- use app_config to add more sophisticated order checking since Zuora now handles majority of consumer records
							- check threshold should be configured hourly as most non-Zuora traffic now occurs between 7AM and 9PM
							- apply casing and formatting, schemas added, modified message
							- use SET TRANSACTION ISOLATION LEVEL over NOLOCK
							- added @opt_args for debugging

	DESCRIPTION

*/

SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

BEGIN TRY

	DECLARE @THRESHOLD_CHECK_COUNT INT,
		@THRESHOLD_CHECK_MINUTES INT,
		@CRLF VARCHAR(2) = CHAR(13) + CHAR(10);

	DECLARE @APP_CONFIG TABLE (
			[key] VARCHAR(50),
			[value] VARCHAR(10)
	);

	INSERT INTO @APP_CONFIG (
	    [key],
	    [value]
	)
	SELECT
		cfg.[key],
		cfg.[value]
	FROM dbo.fn_app_config_select_key_values( 'MONITOR_QUEUES_MONITOR_ORDERS', 'SQL_SERVER_AGENT_JOBS' ) cfg;

	SELECT
		@THRESHOLD_CHECK_COUNT = ( CASE 
										WHEN cfg.[key] = 'THRESHOLD-CHECK-COUNT' THEN CAST( cfg.[value] AS INT )
										ELSE @THRESHOLD_CHECK_COUNT 
									END ),
		@THRESHOLD_CHECK_MINUTES = ( CASE 
										WHEN cfg.[key] = 'THRESHOLD-CHECK-MINUTES' THEN CAST( cfg.[value] AS INT )
										ELSE @THRESHOLD_CHECK_MINUTES 
									END )
	FROM @APP_CONFIG cfg;

	-- Double-check NULLs
	SELECT @THRESHOLD_CHECK_COUNT = ISNULL( @THRESHOLD_CHECK_COUNT, 10),
		@THRESHOLD_CHECK_MINUTES = ISNULL( @THRESHOLD_CHECK_MINUTES, 240)


	DECLARE @reccount BIGINT, 
		@servername VARCHAR(100),
		@subject VARCHAR(400),
		@body VARCHAR(4000),
		@recipients VARCHAR(800),
		@current_date DATETIME = GETDATE(),
		@check_date DATETIME;

		SELECT @check_date = DATEADD( MINUTE, 0 - @THRESHOLD_CHECK_MINUTES, @current_date )

		IF @opt_args = 'debug' BEGIN
				SELECT @check_date, @current_date
				SELECT @THRESHOLD_CHECK_COUNT, @THRESHOLD_CHECK_MINUTES;
			END

		SELECT 
			@reccount = COUNT(*)
		FROM dbo.vendor_order 
		WHERE insert_date >= @check_date 

		IF ( @reccount < @THRESHOLD_CHECK_COUNT ) BEGIN   

				SELECT
					@servername = @@SERVERNAME,
					@subject = 'Orders Alert',
					@body = IIF( @reccount > 0, 'Only ' + LEFT(@reccount, 5), 'No' ) + ' (Non-Zuora) orders have been created in the past ' 
						+ IIF( DATEDIFF( MINUTE, @check_date, @current_date ) > 60, CAST( CAST( DATEDIFF( MINUTE, @check_date, @current_date ) / 60 AS INTEGER ) AS VARCHAR(10) ) + ' hour(s)', '' ) 
						+ IIF( ( DATEDIFF( MINUTE, @check_date, @current_date ) % 60 ) > 0, ' ' + CAST( ( DATEDIFF( MINUTE, @check_date, @current_date ) % 60 ) AS VARCHAR(10) ) + ' minute(s)', '' ) 
						+ ' (no orders after ' + CONVERT(VARCHAR(30),GETDATE(),100) + ').'
						+ @CRLF + @CRLF
						+ 'Possible issue, please investigate. '
						+ @CRLF + @CRLF
						+ 'Email generated via SQL Job Monitor email message on ' + RTRIM(@servername) + '.',
					@recipients = 'wr-DLGlobalDatabaseSupport@opentext.com;wr-DLWebDevDB@opentext.com;CARB-DBMonitoring@opentext.com'; 


				EXECUTE msdb..sp_send_dbmail   
					@recipients = @recipients,
					@body = @body,
					@subject = @subject,
					@importance = 'High';
			END 

END TRY

BEGIN CATCH

END CATCH

GO
