CREATE PROCEDURE [dbo].[usp_monitorservicebroker]

( @email VARCHAR(200)
  ,@start INT
  , @end  INT
  )
   AS

/*

Date            Author         version              Remarks
============================================================
10/7/2015            ugangichetty       1.0         Monitor Service Broke Queue
10/12/2015           ugangichetty       1.1         Included datetime range and also updated start and end time as input parameters.
10/27/2015 	     ugangichetty 	1.2	    Adding nolock hint to avoid deadlocks
*/

DECLARE  @count INT
              ,@alertemail VARCHAR(200)
              ,@subject    VARCHAR(200)
              ,@query      NVARCHAR(4000)
              ,@body       NVARCHAR (500);

     SELECT  @count=COUNT(task_id) from tasks..task_table with (nolock) where processstatus is null and errorXML is null
  and starttime > DATEADD(mi, @start, GETDATE()) and starttime < DATEADD(mi, @end, GETDATE())

 --create table tempresults (commands nvarchar(max), starttime DAtetime, processstatus varchar(20), endtime varchar(10), errorxml xml)
 --insert into tempresults select top 10 command, starttime,processstatus,endtime,errorxml from tasks..task_table where processstatus is null and errorXML is null and starttime > DATEADD(mi, @start, GETDATE()) and starttime < DATEADD(mi, @end, GETDATE())


create table tempresults (commands nvarchar(max), starttime DAtetime, processstatus varchar(20), 
  endtime varchar(10), errorxml xml)
 insert into tempresults 
 select top 20 command, starttime,processstatus,endtime,errorxml
 from tasks..task_table where processstatus is null and errorXML is null 
 and starttime > DATEADD(mi, @start, GETDATE()) and starttime < DATEADD(mi, @end, GETDATE())
update tempresults set processstatus='NULL' where processstatus IS NULL
update tempresults set endtime='NULL' where endtime IS NULL
update tempresults set errorxml='NULL' where errorxml IS NULL

DECLARE @html nvarchar(MAX);
EXEC admin.dbo.spQueryToHtmlTable @html = @html OUTPUT, 
 @query = N'
select * from eCommerce..tempresults'

  SELECT @alertemail = @email
            ,@subject   = 'CRITICAL!!! Service Broker Queue Alert On '+@@SERVERNAME
           
	 IF @count>1
     BEGIN
              EXEC msdb.dbo.sp_send_dbmail
                           @recipients  = @alertemail
						   --@profile_name='DCO DBA'
                          ,@query       = @query
                       , @subject     = @subject
					   , @body        = @html
                       , @importance  = 'High'
                       , @body_format = 'HTML';
          END
  ELSE
       PRINT 'Service Broker working fine'
Drop table tempresults





GO
