                       , @subject     = @subject
					 --  , @body        = @html
                       , @importance  = 'High'
                       , @body_format = 'HTML';
          END
END
  ELSE
       PRINT 'Sky Update is working fine'
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_msn_insert_msn_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_msn_insert_msn_order]


(
		@msn_hash_puid varchar(64), 
		@p_rc varchar(50) = '1673', 
		@p_ac varchar(50)
)

/*	
	DATE		 AUTHOR			REMARKS
	2012-10-31	 acoffel		Initial creation.
	2012-12-10	 acoffel	    Adding sequencing
	
	DESCRIPTION
	
*/

as
	
	begin try
	set nocount on
	
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) set table variables and retrive an available keycode - mark as pending
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	
	declare @keycode varchar(40),
			@keycode_check int,
			@license_id int,
			@msn_keycode_id int,
			@task_number varchar(10),	
			@db_name varchar(100),
			@response_code int, 
			@message varchar(100)
			
			select @keycode_check = license_id 
			from msn_keycode 
			where msn_hash_puid = @msn_hash_puid
			
			if @keycode_check is not NULL
			begin
				select @keycode = keycode 
				from license 
				where license_id = @keycode_check  
				
				select 'PUID was already be used to redeem a keycode, here it is:' as used_response, @keycode as keycode
				return
			end

			select top 1 @license_id = license_id
			from msn_keycode
			where msn_hash_puid is NULL
			order by 1 desc

			select @keycode = keycode from license where license_id = @license_id
			
			if @license_id is NULL
			begin
				select @response_code = -200, @message = 'out of available MSN keycodes'
				return
			end
			
			update msn_keycode
			set msn_keycode_status_id = 2,
				msn_hash_puid = @msn_hash_puid,
				last_modified_date = getdate()
			where license_id = @license_id

			
				
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) prep internal service broker transaction 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	-- 2.0 set db name
		select @db_name = db_name()
		
	-- 2.1 load task table
		insert into [tasks].[dbo].[task_table]([task_number],[Command],[NoTransaction],[StartTime])
		values (@license_id,'exec ' + @db_name + '..usp_msn_load_msn_order  ''' + @msn_hash_puid + '''' + ',' + '''' + @p_rc + '''' + ',' + '''' + @p_ac + '''' + ',' + '''' + @keycode + '''' + ',' + left(@license_id,10),0,getdate())

	-- 2.2 prime the pump
		exec tasks..usp_queue_task @license_id


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return @keycode 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		
		select @keycode as keycode


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'msn order insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	
	
GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_msn_load_msn_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_msn_load_msn_order]


(

			@msn_hash_puid varchar(64),
			@p_rc varchar(50),
			@p_ac varchar(50),
			@keycode varchar(40),
			@license_id int
)

/*	
	DATE		 AUTHOR			REMARKS
	2012-10-31	 acoffel		Initial creation.
	2013-03-29	 esmart		    Support multiple customer orders
	2019-12-13   wbarton		Updating the procedure to use usp_cart_load_order rather than usp_cart_process_order to load orders

	DESCRIPTION
	
*/

as
	
	begin try
	set nocount on
	
			
	declare @cart_customer_id varchar(4000),
			@cart_order_id int,
			@cart_order_item_id int,
			@customer_in_process_id int,
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100)
			
			
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) start loading cart tables - cart_customer first
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) insert cart_customer
		insert into cart_customer(customer_in_process_id, external_customer_key, first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, bill_postal_code, bill_country, ship_address_1, ship_address_2, ship_address_3, ship_city, ship_state, ship_postal_code, ship_country, phone_number, fax_number, company_name, customer_email, opt_in, vat_id)
		select 0, @msn_hash_puid, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0 as opt_in, NULL
	
	-- 1.2) set cart_customer_id to match transaction		
		select @cart_customer_id = scope_identity()
		
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) cart_order
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) cart_order create vendor_order_code
		declare @next_id table (invoice_code_int int)
		declare @vendor_order_code_prefix varchar(5), @vendor_order_code varchar(100)

		insert into @next_id(invoice_code_int)
		exec usp_next_id @Type=3

		select @vendor_order_code_prefix = 'E0000'

		select @vendor_order_code = @vendor_order_code_prefix + convert(varchar(8),invoice_code_int) from @next_id

	-- 2.2) insert cart_order
		insert into cart_order(cart_customer_id,invoice_in_process_id,vendor_order_code,order_type
			   ,site_id,site_url,p_rc,p_rsc,p_ac,trx_rc,trx_rsc,trx_ac,aid,pid,sid,offer_id,offer_amount
			   ,total_amount,sub_total_amount,tax_amount,payment_method,exchange_rate,session_id
			   ,submission_date,sales_order_date,locale,subject,comment,insert_by,modified_by
			   ,cart_order_status_id,currency_id,customer_profile_token)
		 values
			   (@cart_customer_id,0,@vendor_order_code,'MSN','MSN','WRCART',@p_rc,NULL,@p_ac,NULL,NULL,NULL,NULL,
			   NULL,NULL,NULL,0.00,0.00,0.00,0.00,0,1.00,0,getdate(),getdate(),'en_US',NULL,NULL,getdate(),'MSN',
			   1,1,NULL)
           
	-- 2.3) set cart_order_id to match transaction
		select @cart_order_id  = scope_identity()

		-- 2.3.1) update cart_customer
			update cart_customer
			set cart_order_id = @cart_order_id
			where cart_customer_id = @cart_customer_id
	
	
	-- -------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) cart_order_item 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) cart_order_item
		insert into cart_order_item(cart_order_id, invoice_item_in_process_id, vendor_id, line_item, vendor_product_id, quantity, order_item_offer_code, order_item_offer_amount, list_price, unit_price, tax_item_total, tax_exempt, product_id, conversion_product_id, product_locale, insert_date, insert_by, modified_date, modified_by, cart_order_status_id, cart_order_item_in_process_id, cart_item_bundle_id)
		select @cart_order_id, invoice_item_in_process_id = 0, 4, 1, 11100310, 1, NULL, 49.99, 49.99, 0.00, 0.00, 0, 11100310, 11100310, 'En_US', getdate(), 'MSN', getdate(), 'MSN', 1, NULL, 1
	
	-- 3.2) set cart_order_item_id to match transaction
		select @cart_order_item_id  = scope_identity()
		
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) cart_order_item 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 4.1) cart_order_item_license
		insert into cart_order_item_license(cart_order_item_id, keycode)
		select @cart_order_item_id, @keycode

	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) load the order by calling usp_cart_process_order @cart_order_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		exec usp_cart_load_order @cart_order_id = @cart_order_id, @return_result = 0

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'something failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_MSN_select_hash_puid_by_keycode]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_MSN_select_hash_puid_by_keycode]

(
	   @keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-04-29	esmart		Initial creation

	DESCRIPTION
	
*/

AS
	
	declare @vendor_customer_code varchar(100), 
			@min_activation_date datetime,
			@response_code int,
			@message varchar(100)

	
set nocount on
begin try

	select @vendor_customer_code = (select top 1 v.vendor_customer_code
								from license l 
								inner join order_item_license ol 
									 on l.license_id = ol.license_id 
								inner join order_item i 
									 on ol.order_item_id = i.order_item_id 
								inner join order_code c 
									 on i.order_header_id = c.order_header_id and code_type_id = 1 and code_value = 1673 
								inner join customer_order co 
									 on i.order_header_id = co.order_header_id 
								inner join vendor_customer v 
									 on co.customer_id = v.customer_id and v.vendor_id = 4
								where l.keycode = @keycode
								order by v.vendor_customer_id)

	select @min_activation_date = min(capability_activation_date) 
	from license_capability_history h
	inner join license l
		on h.license_id = l.license_id
	where l.keycode = @keycode
	
	if @min_activation_date is null 
		begin
		select @min_activation_date = min(capability_activation_date) 
		from license_capability c
		inner join license l
			on c.license_id = l.license_id
		where l.keycode = @keycode
		end

	select vendor_customer_code = @vendor_customer_code, 
			min_activation_date = convert(varchar(30),@min_activation_date,121)

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'Could not find MSN vendor_customer_code (hash puid) for keycode ' + @keycode
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_MSN_update_churn_license_capability_expiration]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_MSN_update_churn_license_capability_expiration]

AS
/*	
		DATE			AUTHOR			REMARKS
		2007-03-20		esmart			Initial creation.	
		2009-10-15		esmart			Modification for new MSN process

		DESCRIPTION
		Copy MSN data from PECOMWH1.MSN and complete update to all licenses in temp table
*/


	set nocount on

-- -------------------------------------------------------------------------------------------------------------------------------------------
-- 3) update license_capability in batches of 250
-- -------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_capability_count int,
		@current_set int

	set @current_set = 1

	select @license_capability_count = convert(int,count(*)/250) + 1
	from msn_churn_expiration_update

	while @current_set <= @license_capability_count
		begin
			print @current_set
			-- 3.1) insert rows into license_capability_audit (0:03)
			
			insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
			select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = getdate(), audit_by = system_user
			from msn_churn_expiration_update
			where license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)
			order by license_capability_id
			
			print ('insert into audit complete')	
			
			-- 3.2) insert rows into license_capability_history (0:59)
		
			insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
			select license_capability_id, license_id, capability_id, capability_type_id, 
				capability_activation_days = isnull(days_used,0), 
				capability_activation_date, 
				capability_expiration_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
				insert_date, insert_by, modified_date, modified_by, capability_change_reason_id = 15, history_date = getdate(), history_by = system_user, 
				days_used = isnull(days_used,0), 
				days_remaining = isnull(days_remaining,0), 
				days_added = isnull(days_added,0), 
				days_new = isnull(days_new,0), 
				days_contiguous = isnull(days_contiguous,0)
			from msn_churn_expiration_update 
			where license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)
			order by license_capability_id
			
			print ('insert into history complete')

			-- 3.3) update license_capability (0:35)
		
			update license_capability
			set	capability_activation_days = t.days_new,
				capability_activation_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then t.capability_expiration_date
						when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
					end,
				capability_expiration_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then dateadd(dd,t.days_new,t.capability_expiration_date)
						
when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
					end,
				modified_date = getdate(),
				modified_by = system_user	
			from license_capability c
			inner join msn_churn_expiration_update t
				on c.license_capability_id = t.license_capability_id
			where t.license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)
		

			print ('update license_capability complete')

		-- 3.4) insert license_category_license_history
			insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date, history_by)
			select l.license_category_license_id, 
					l.license_id, 
					l.license_category_id, 
					l.start_date, 
					end_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
					l.last_modified_date, l.last_modified_by, license_change_reason_id = 15, history_date = getdate(), history_by = suser_sname()
			from msn_churn_expiration_update t
			inner join license_category_license l
				on t.license_id = l.license_id
			where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)
		
		-- 3.5) update license_category_license
			-- 3.5.1) update where exist
			update license_category_license
			set start_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then t.capability_expiration_date
						when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
					end,
				end_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then dateadd(dd,t.days_new,t.capability_expiration_date)
						when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
					end,
				last_modified_date = getdate(),
				last_modified_by = suser_sname()	
			from msn_churn_expiration_update t
			inner join license_category_license l
				on t.license_id = l.license_id
			where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)

			-- 3.5.2) insert license_category_license
			insert into license_category_license(license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by)
			select t.license_id, license_category_id = 1, 
				start_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then t.capability_expiration_date
						when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
					end,
				end_date = 
					case
						when t.capability_id = 1 and t.days_remaining = 0 then dateadd(dd,t.days_new,t.capability_expiration_date)
						when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
					end,
				last_modified_date = getdate(),
				last_modified_by = suser_sname()
			from msn_churn_expiration_update t
			left join license_category_license l
				on t.license_id = l.license_id
			where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id) and
				l.license_category_license_id is null

			-- 3.4) update license_capability (0:35)
			
			update msn_churn_expiration_update 
			set update_complete = 1
			where license_capability_id in (select top 250 license_capability_id from msn_churn_expiration_update where update_complete = 0 order by license_capability_id)

			pri
nt ('msn_churn_expiration_update table update complete')

			

		set @current_set = @current_set + 1
		end



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_MSN_update_license_capability_expiration]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_MSN_update_license_capability_expiration]

AS

/*	
		DATE			AUTHOR		REMARKS
		2007-01-26		esmart			Initial creation.	
		2007-01-29		esmart			Added on extra loop to WHILE to catch the last set of licenses.

		DESCRIPTION
		Copy MSN data from PECOMWH1..admin and complete update to all licenses in temp table
*/


	set nocount on
	
-- -------------------------------------------------------------------------------------------------------------------------------------------
-- 3) update license_capability in batches of 250
-- -------------------------------------------------------------------------------------------------------------------------------------------

	declare @license_capability_count int,
		@current_set int

	set @current_set = 1

	select @license_capability_count = convert(int,count(*)/250) + 1
	from msn_expiration_extension

	while @current_set <= @license_capability_count
		begin
			print @current_set
			-- 3.1) insert rows into license_capability_audit (0:03)
			
			insert into license_capability_audit (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date, audit_by)
			select license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, audit_date = getdate(), audit_by = suser_sname()
			from msn_expiration_extension
			where license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)
			order by license_capability_id
			
			print ('insert into audit complete')	
			
			-- 3.2) insert rows into license_capability_history (0:59)
		
			insert into license_capability_history (license_capability_id, license_id, capability_id, capability_type_id, capability_activation_days, capability_activation_date, capability_expiration_date, insert_date, insert_by, modified_date, modified_by, capability_change_reason_id, history_date, history_by, days_used, days_remaining, days_added, days_new, days_contiguous)
			select license_capability_id, license_id, capability_id, capability_type_id, 
				capability_activation_days = isnull(days_used,0), 
				capability_activation_date, 
				capability_expiration_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
				insert_date, insert_by, modified_date, modified_by, capability_change_reason_id = 15, history_date = getdate(), history_by = suser_sname(), 
				days_used = isnull(days_used,0), 
				days_remaining = isnull(days_remaining,0), 
				days_added = isnull(days_added,0), 
				days_new = isnull(days_new,0), 
				days_contiguous = isnull(days_contiguous,0)
			from msn_expiration_extension 
			where license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)
			order by license_capability_id
			
			print ('insert into history complete')

			-- 3.3) update license_capability (0:35)
		
			update license_capability
			set	capability_activation_days = t.days_new,
				capability_activation_date = 
					case
						when t.days_remaining = 0 then getdate()
						when t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
					end,
				capability_expiration_date = 
					case
						when t.days_remaining = 0 then dateadd(dd,t.days_new,getdate())
						when t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
					end,
				modified_date = getdate(),
				modified_by = suser_sn
ame()	
			from license_capability c
			inner join msn_expiration_extension t
				on c.license_capability_id = t.license_capability_id
			where t.license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)
		

			print ('update license_capability complete')

			-- 3.4) insert license_category_license_history
			insert into license_category_license_history(license_category_license_id, license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by, license_change_reason_id, history_date, history_by)
			select l.license_category_license_id, 
					l.license_id, 
					l.license_category_id, 
					l.start_date, 
					end_date = dateadd(dd,isnull(days_used,0),capability_activation_date), 
					l.last_modified_date, l.last_modified_by, license_change_reason_id = 15, history_date = getdate(), history_by = suser_sname()
			from msn_expiration_extension t
			inner join license_category_license l
				on t.license_id = l.license_id
			where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)
		
			-- 3.5) update license_category_license
				-- 3.5.1) update where exist
				update license_category_license
				set start_date = 
						case
							when t.capability_id = 1 and t.days_remaining = 0 then getdate()
							when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
						end,
					end_date = 
						case
							when t.capability_id = 1 and t.days_remaining = 0 then dateadd(dd,t.days_new,getdate())
							when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
						end,
					last_modified_date = getdate(),
					last_modified_by = suser_sname()	
				from msn_expiration_extension t
				inner join license_category_license l
					on t.license_id = l.license_id
				where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)

				-- 3.5.2) insert license_category_license
				insert into license_category_license(license_id, license_category_id, start_date, end_date, last_modified_date, last_modified_by)
				select t.license_id, license_category_id = 1, 
						start_date = 
						case
							when t.capability_id = 1 and t.days_remaining = 0 then getdate()
							when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_used,t.capability_activation_date)
						end,
					end_date = 
						case
							when t.capability_id = 1 and t.days_remaining = 0 then dateadd(dd,t.days_new,getdate())
							when t.capability_id = 1 and t.days_remaining > 0 then dateadd(dd,t.days_new,dateadd(dd,t.days_used,t.capability_activation_date))
						end,
					last_modified_date = getdate(),
					last_modified_by = suser_sname()
				from msn_expiration_extension t
				left join license_category_license l
					on t.license_id = l.license_id
				where t.capability_id = 1 and t.license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id) and
					l.license_category_license_id is null

			-- 3.6) update license_capability (0:35)
			
			update msn_expiration_extension 
			set update_complete = 1
			where license_capability_id in (select top 250 license_capability_id from msn_expiration_extension where update_complete = 0 order by license_capability_id)

			print ('msn_expiration_extension table update complete')

		set @current_set = @current_set + 1
		end




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_nec_select_nec_mobile_orders]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_nec_select_nec_mobile_orders]


/*	
	DATE		AUTHOR		REMARKS
	2013-02-24	acoffel		Initial Creation
	2013-07-19	acoffel		adjusted to pull from merchant order id

	DESCRIPTION
	
*/
AS


declare @max_nec_id int, 
		@temp_nec_id int,
		@nec_update_id int,
		@keycode varchar(40),
		@google_order_id varchar(100), 
		@merchant_order_id varchar(100),
		@insert_date datetime,
		@google_order_status_id tinyint,
		@modified_by varchar(20), 
		@response_code int, 
		@google_order_id_dup varchar(100), 
		@message varchar(100)


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) create unprocessed set from google tables
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) get new records
		if object_id('dbo.nec_order') is not null
			drop table dbo.nec_order;
		select distinct substring(o.merchant_order_id,22,16) as google_order_id, o.merchant_order_id, g.order_status_id as google_order_status_id, g.keycode, g.insert_date, 0 as processed
		into dbo.nec_order
		from goognec_order o
		inner join google_order g
			on substring(o.merchant_order_id,22,16) = substring(g.google_order_number,22,16) 
		where g.processed = 0
		and o.financial_status in ('CHARGED','CANCELLED')

		-- 1.2) find charges and cancels from same drop and delete cancel
		if object_id('dbo.nec_order_dup') is not null
			drop table dbo.nec_order_dup;
		select google_order_id
		into dbo.nec_order_dup
		from dbo.nec_order
		where google_order_id in (select google_order_id from dbo.nec_order group by google_order_id having count(google_order_id) > 1)

		-- 1.3) delete cancels from table when they have a charge in the same drop
		delete from dbo.nec_order where google_order_id in (select google_order_id from dbo.nec_order_dup) and google_order_status_id = 3

		-- 1.4) create working table
		if object_id('dbo.nec_order_working') is not null
			drop table dbo.nec_order_working;
		select temp_nec_id = identity(int,1,1), google_order_id, merchant_order_id, google_order_status_id, keycode, insert_date, processed
		into dbo.nec_order_working
		from dbo.nec_order

		--select * from  dbo.nec_order_working

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) set working parameters based on dbo.nec_order_working
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @max_nec_id = max(temp_nec_id),
		@temp_nec_id = min(temp_nec_id)
		from dbo.nec_order_working
		where processed = 0

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) enter loop and process records
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @modified_by = 'nec_batch_load'

			while @temp_nec_id <= @max_nec_id
				begin
				select @nec_update_id = temp_nec_id
				from dbo.nec_order_working 
				where temp_nec_id = @temp_nec_id

				if @temp_nec_id is null
					begin
						update usp_nec_process_nec_mobile_orders set processed = 1 
					end
				el
se
					begin		
					select @google_order_id = google_order_id, @merchant_order_id = merchant_order_id, @keycode = keycode, @insert_date = insert_date, @google_order_status_id = google_order_status_id
					from dbo.nec_order_working  where temp_nec_id = @temp_nec_id
					print @google_order_id print @merchant_order_id print @keycode print @insert_date print @google_order_status_id
					exec usp_nec_process_nec_mobile_orders @google_order_id,@merchant_order_id,@keycode,@insert_date,@google_order_status_id


					update dbo.nec_order_working set processed = 1 where temp_nec_id = @temp_nec_id
					end

				set @temp_nec_id = @temp_nec_id + 1
				end




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_netsuite_order_license_insert]
-- =============================================================================
CREATE procedure [dbo].[usp_netsuite_order_license_insert]

	@contract_id int,
	@contract_line_id int,
	@overage_line_id int = null,
	@failover_line_id int = null,
	@sap_material_number int,
	@site_id varchar(20),
	@license_distribution_method_id int,
	@locale char(5) = null,
	@currency_code char(3),
	@effective_date date,
	@expiration_date date,
	@license_seats int,
	@license_attribute_license_value int, 
	@license_keycode_type_id int, 
	@unit_price money, 
	@total_price money, 
	@usage_price money,
	@billing_day_of_month int,
	@bill_to_json nvarchar(max),
	@ship_to_json nvarchar(max) = null,
	@reseller_json nvarchar(max) = null,
	@distributor_json nvarchar(MAX) = NULL,
	@purchase_order varchar(100) = null,
	@sap_order_number varchar(20) = null,
	@sap_item_json nvarchar(max) = null,
	@provisioning_json nvarchar(max) = NULL,
	@msp_flag int=null,
	@storage_gb int=null,
	@suppression_flag int=NULL,
	@license_keycode varchar(40)=null
   

/*	
	DATE		AUTHOR			REMARKS
	2020-11-05	wbarton			Initial creation
	2020-01-10	wbarton			Refactored version using new inputs that will need to be passed-in from staged netsuite contract data
	2020-02-28	wbarton			Modifying provisioning-data handling
	2021-09-23  psatish			Added a DistributorJson as an inparameter and passed the customertype to the usp_cart_update_cart_customer
	2021-11-19  psatish			Added BillingType and Storage GB in the Provisioning Json to populate into license_external_reference_vault and 
								commented the prevx_update insertion for the Contract Backfill
	2021-12-30	psatish			Added order_header_id to check the same sap_order# can associate with multiple orders
	2022-01-07	gblandford		SMCI-6217 - Add retention_term
	2022-02-22	psatish			SMCI-6064 - Modified the Linked server name
	2022-05-18  psatish			ALM# 990 - Pass sap_material_number in the cart_order_item proc and added section 8.1 for MSP Flag 
	2022-07-21  psatish			ALM# 1672 - Pass calacultated_included_storage value as storage_gb as an in-parameter for ecomm overage calculation
	2022-07-29  psatish			ALM# 1658 - Added License keycode as an in-parameter to create new orders for early renewals from Netsuite
	DESCRIPTION
	Processes order and license creation for staged Netsuite Carbonite contracts

*/
as

set nocount on

begin try

	declare
		@vendor_order_code_prefix varchar(5),
		@vendor_order_code varchar(100),
		@cart_extension_json nvarchar(max),
		@response_code int, 
		@message varchar(200),
		@cart_order_id int,
		@item_json nvarchar(max), 
		@bundle_json nvarchar(max), 
		@quantity int = 1, 
		@item_hierarchy_id int = 1, 
		@license_category_name varchar(10), 
		@retention_model_id int, 
		@retention_term tinyint,
		@usage_pricing_model_id int, 
		@product_platform_id int, 
		@years int, 
		@cart_item_bundle_id int = 1, 
		@product_id int, 
		@keycode varchar(40),
		@license_service_type_name varchar(50),
		@service_json nvarchar(max),
		@license_distribution_method_code varchar(10),
		@cart_order_item_id int,
		@application varchar(50) = 'carbonite_backfill',
		@license_id int,
		@order_header_id int,
		@license_external_reference_vault_json nvarchar(max),
		@loop_value int,
		@loop_max int,
		@license_category_id tinyint, 
		@effective_object_id tinyint, 
		@external_reference_value varchar(100), 
		@license_external_reference_vault_id int, 
		@sap_order_id int,
		@sap_item nvarchar(max),
		@license_effective_object_json nvarchar(max),
		@record_json nvarchar(max)

	declare @next_id table (id int)

	declare @item_json_processing table (
		id int identity(1,1),
		item_json nvarchar(max)
	)

	declare @sap_order_item table (
		sap_order_id int,
		sap_order_status_id int,
		sap_item_num
ber varchar(20),
		order_item_id int,
		usage_item char(1),
		start_date date,
		end_date date
	)

	declare @provisioning_json_processing table (
		id int identity(1,1),
		json_object nvarchar(max)
	)

	declare @provisioning_data table (
		id int identity(1,1),
		license_id int,
		license_category_id int,
		vault_id int,
		tenant varchar(250),
		customer_short_name varchar(250),
		effective_object_id int,
		license_external_reference_vault_id INT,
		billing_type varchar(20),
		total_storage int
	)
		
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1. Setting vendor_order_code explicitly so it can be used to set other variables throughout the procedure
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------		 
	insert into @next_id(id)
	exec usp_next_id @Type = 3

	select @vendor_order_code_prefix = vendor_order_code_prefix 
	from cart_site_id_order_code_prefix 
	where site_id = @site_id

	select @vendor_order_code = @vendor_order_code_prefix + (select top 1 convert(varchar(20), id) from @next_id order by id)

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2. usp_cart_insert_cart_order
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @locale is null
		begin
			select @locale = 'en_US'
		end

	select @cart_extension_json = (
		select @currency_code as currency_code, @effective_date as sales_order_date, 'true' as date_override, @contract_id as netsuite_contract_id, @vendor_order_code as vendor_order_code
		for json path, without_array_wrapper
	)

	exec usp_cart_insert_cart_order @site_id = @site_id, @locale = @locale, @user_ip = '', @cart_extension_json = @cart_extension_json, @response_code = @response_code output, @message = @message output

	select @cart_order_id = co.cart_order_id
	from cart_order co with (nolock)
	where co.vendor_order_code = @vendor_order_code

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--3. usp_cart_insert_cart_order_item
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @license_category_name = lc.license_category_name, @license_category_id = m.license_category_id, @years = m.years, @product_platform_id = json_value(j.product_extension_json, '$.product_platform_id'), @usage_pricing_model_id = json_value(j.product_extension_json, '$.usage_pricing_model_id'), @retention_model_id = json_value(j.product_extension_json, '$.retention_model_id'), @retention_term = json_value(j.product_extension_json, '$.retention_term')
	from sap_material_product_mapping m
		inner join license_category lc
			on lc.license_category_id = m.license_category_id
		left join sap_material_product_json j
			on j.sap_material_product_mapping_id = m.sap_material_product_mapping_id
	where m.sap_material_number = @sap_material_number

	select @item_json = (
		select @quantity as quantity, @item_hierarchy_id as item_hierarchy_id, @license_category_name as license_category_name, @license_seats as license_seats, @years as years
, @product_platform_id as product_platform_id, @usage_pricing_model_id as usage_pricing_model_id, @retention_model_id as retention_model_id, @retention_term as retention_term, @cart_item_bundle_id as cart_item_bundle_id, @effective_date as start_date, @expiration_date as expiration_date, 
		@unit_price as unit_price, @usage_price as usage_price, @contract_line_id as netsuite_contract_line_id, @overage_line_id as netsuite_overage_contract_line_id, @failover_line_id as netsuite_failover_contract_line_id,
		@sap_material_number as sap_material_number
		FOR json path
	)
	select @bundle_json = (
		select @license_attribute_license_value as license_attribute_license_value, @license_keycode_type_id as license_keycode_type_id,@license_keycode AS keycode
		for json path, without_array_wrapper
	)

	exec usp_cart_insert_cart_order_item @vendor_order_code = @vendor_order_code, @item_json = @item_json, @bundle_json = @bundle_json, @response_code = @response_code output, @message = @message output

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--4. Update pricing to match Netsuite contract data
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	update cart_order 
	set total_amount = @total_price, sub_total_amount = @total_price
	where cart_order_id = @cart_order_id

	update dbo.cart_order_item
	set unit_price = @unit_price, unit_price_pre_vat = @unit_price, usage_price = @usage_price
	where cart_order_id = @cart_order_id

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--5. usp_cart_update_cart_customer
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--bill-to
	exec usp_cart_update_cart_customer @vendor_order_code = @vendor_order_code,@customer_type_id=1, @cart_customer_json = @bill_to_json, @response_code = @response_code output, @message = @message output

	--ship-to
	if @ship_to_json is not null
		begin
			exec usp_cart_update_cart_customer @vendor_order_code = @vendor_order_code,@customer_type_id=2, @cart_customer_json = @ship_to_json, @response_code = @response_code output, @message = @message output
		end

	--reseller
	if @reseller_json is not null
		begin
			exec usp_cart_update_cart_customer @vendor_order_code = @vendor_order_code, @customer_type_id=3,@cart_customer_json = @reseller_json, @response_code = @response_code output, @message = @message output
		end
	--distributor
	if @distributor_json is not null
		begin
			exec usp_cart_update_cart_customer @vendor_order_code = @vendor_order_code, @customer_type_id=4,@cart_customer_json = @distributor_json, @response_code = @response_code output, @message = @message output
		end

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--6. Setting PO number when applicable
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @purchase_order is not null
		begin
			exec usp_cart_insert_payment_header @vendor_order_code = @vendor_order_code, @merchant_id = 'carbonite_backfill', @payment_method_name = N'Purcha
seOrder', @response_code = @response_code output, @message = @message output
			exec usp_payment_update_purchase_order @vendor_order_code = @vendor_order_code, @purchase_order = @purchase_order
		end

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--7. Create keycode and license - single item orders
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Keycode
	select @product_id = product_id
	from cart_order_item
	where cart_order_id = @cart_order_id

	IF @license_keycode IS NOT NULL
		SET @keycode=@license_keycode

	IF @license_keycode IS NULL
    begin
		EXEC usp_license_generate_keycode_cart @product_id = @product_id, @license_distribution_method_id = @license_distribution_method_id, @keycode = @keycode output, @response_code = @response_code output, @message = @message output

		IF @keycode = ''
			BEGIN;
			throw 50001, 'Keycode was not created by usp_license_generate_keycode_cart', 1;
			END
	
	
	--License
	select @license_distribution_method_code = license_distribution_method_code 
	from license_distribution_method
	where license_distribution_method_id = @license_distribution_method_id

	select @cart_order_item_id = cart_order_item_id
	from cart_order_item
	where cart_order_id = @cart_order_id

	select @service_json = (
		select @keycode as keycode, @license_keycode_type_id as license_keycode_type_id, @license_distribution_method_code as license_distribution_method_code, @cart_order_item_id as [cart_order_item.cart_order_item_id], @license_category_name as [license_category.license_category_name], @license_seats as [license_category.license_seats], @effective_date as [license_category.start_date], @expiration_date as [license_category.expiration_date], 'full' as [license_category.category_type_name], 1 as [license_category.item_hierarchy_id], @application as application
		for json path, without_array_wrapper
	)

	select @license_service_type_name = 'license_create'
	exec usp_license_service_insert_service @license_service_type_name = @license_service_type_name, @service_json = @service_json, @return_license_service_id = 0
	end
	select @license_id = license_id 
	from license with (nolock)
	where keycode = @keycode

	----Since ecom is generating the keycode in this flow, it initially needs to interface to Derby via prevx_update
	--insert into prevx_update(license_id, prevx_update_type_id, prevx_update_status_id, update_attempts, process_date)
	--select @license_id, 1, 0, 0, getdate()

	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--8. Load order and update license
	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	exec usp_cart_load_order @cart_order_id = @cart_order_id, @return_result = 0

	select @order_header_id = order_header_id 
	from dbo.cart_order_header
	where cart_order_id = @cart_order_id

	--asynchronous:
	--exec usp_cart_insert_license_update_queue @order_header_id = @order_header_id, @order_type_group_id = 1
	--synchronous:
	--exec usp_cart_update_order_license @order_header_id = @order_header_id, @order_type_group_id = 1
	exec usp_cart_update_order_license_new @vendor_order_code = @vendor_order_code

	--Update billing day of month
	if @billing_day_of_month is not null and @billing_day_of_month <> (select dbo.fn_license_select_effective_object_element(@lic
ense_id, @license_category_id, 'billing_day_of_month', @effective_date))
		begin
			select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @billing_day_of_month as billing_day_of_month, @effective_date as effective_start_date
				for json path
			)

			exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = @application
		end
--------------------------------------------------------------------------------------------------------------------------------------
	--8.1 MSP Flag
---------------------------------------------------------------------------------------------------------------------------------------
	--insert MSP_Flag
	if @msp_flag is not null
		begin
			select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @msp_flag as msp_flag, @effective_date as effective_start_date
				for json path
			)

			exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = @application
		end
--------------------------------------------------------------------------------------------------------------------------------------
	--8.2 storage_gb for M365 Capacity based licenses
---------------------------------------------------------------------------------------------------------------------------------------
	
	if @storage_gb is not NULL and @license_category_id=233 and @usage_pricing_model_id=2
		begin
			select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @storage_gb as storage_gb, @effective_date as effective_start_date
				for json path
			)

			exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = @application
		end
--------------------------------------------------------------------------------------------------------------------------------------
	--8.3 suppression_flag 
---------------------------------------------------------------------------------------------------------------------------------------
	
	if @suppression_flag=1
		begin
			select @license_effective_object_json = (
				select @license_id as license_id, @license_category_id as license_category_id, @suppression_flag as suppression_flag, @effective_date as effective_start_date
				for json path
			)

			exec dbo.usp_license_insert_effective_object @license_effective_object_json = @license_effective_object_json, @license_effective_source_caller = @application
		end


	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--9. Maintaining SAP order objects
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--sap_order
	if @sap_order_number is not null and not exists (select 1 from sap_order where sap_order_number = @sap_order_number and order_header_id=@order_header_id)
		begin
			insert into sap_order(sap_order_number, order_header_id, sap_order_status_id)
			select @sap_order_number, @order_header_id, 1
			from order_header h
				left join sap_order s
					on s.order_header_id = h.order_header_id
			where h.order_header_id = @order_header_id
				and s.sap_order_id is null

			select @sap_order_id = scope_identity()

			--sap_order_item insert
			--parse the provided @sap_item_json into @@item_json_processing. This expects @sap_item_json to be an array of objects.
			insert into @item_json_proce
ssing (item_json)
			select [Value]
			from openjson(@sap_item_json)

			--For each object, insert sap_item_number and usage_item into @sap_order_item
			select @loop_value = (select min(id) from @item_json_processing), @loop_max = (select max(id) from @item_json_processing)
			while @loop_value <= @loop_max
				begin
					select @sap_item = item_json 
					from @item_json_processing
					where id = @loop_value

					insert into @sap_order_item (sap_item_number, usage_item)
					select sap_item_number, usage_item 
					from openjson(@sap_item)
					with (
						sap_item_number varchar(20) '$.sap_item_number',
						usage_item char(1) '$.usage_item'
					)

					select @sap_item = null, @loop_value = @loop_value + 1
				end
				
			--Update @sap_order_item with data from order_item. Doing this as an update outside of the loop, so we query order_item only once. The order_item data will be the same for all sap_item_numbers (usage, failover, etc.)
			--This will need to be changed if there are contracts that involve multiple order_item records.
			update @sap_order_item
			set sap_order_id = @sap_order_id, sap_order_status_id = 1, order_item_id = i.order_item_id, start_date = i.effective_date, end_date = i.capability_expiration_date
			from order_item i
			where i.order_header_id = @order_header_id
			
			
			--Insert, preventing duplicates
			insert into sap_order_item (sap_order_id, sap_order_status_id, sap_item_number, order_item_id, usage_item, start_date, end_date)
			select i.sap_order_id, i.sap_order_status_id, i.sap_item_number, i.order_item_id, i.usage_item, i.start_date, i.end_date
			from @sap_order_item i
				left join sap_order_item s
					on s.order_item_id = i.order_item_id
			where s.order_item_id is null

			--sap_order_item_license insert, preventing duplicates
			insert into sap_order_item_license(sap_order_item_id, license_id)
			select s.sap_order_item_id, il.license_id
			from sap_order_item s
				inner join order_item i
					on i.order_item_id = s.order_item_id
				inner join order_item_license il
					on il.order_item_id = i.order_item_id
				left join sap_order_item_license sil
					on sil.sap_order_item_id = s.sap_order_item_id 
			where s.sap_order_id = @sap_order_id 
				and sil.sap_order_item_license_id is null
	
		end


	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	----10. Provisioning data
	--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @provisioning_json is not null
		begin
			--10.1 Populate @provisioning_data from @provision_json input
			insert into @provisioning_json_processing (json_object)
			select [Value] 
			from openjson(@provisioning_json)

			select @loop_value = (select min(id) from @provisioning_json_processing), @loop_max = (select max(id) from @provisioning_json_processing)
			while @loop_value <= @loop_max
				begin
					select @record_json = (select json_object from @provisioning_json_processing where id = @loop_value)

					insert into @provisioning_data (license_id, license_category_id, vault_id, tenant, customer_short_name, effective_object_id,billing_type,total_storage)
					select @license_id, @license_category_id, j.vault_id, j.tenant, j.customer_short_name, j.effective_object_id,j.Billing_type,j.Total_Storage
					from openjson(@record_json)
					with (
						vault_id int '$.vault_id',
						tenant varchar(250) '$.tenant',
						customer_short_name varchar(250) '$.customer_short_name',
						effective_object_id int '$.effective_object_id',
						Billing_type varchar(20) '$.Billing_type',
						Total_Storage INT '$.Total_Storage'
					) j


					select @record_json = null, @loop_value = @loop_value + 1
				end

			--10.2 Insert license_external_reference_vault records for each vault_id present in @provisioning_data
			select @license_external_reference_vault_json = (
				select @license_id as license_id, @license_category_id as [license_category.license_category_id], (
					select distinct vault_id, 'true' as is_provisioned,billing_type,total_storage
					from @provisioning_data
					for json path
				) as [license_category.vault]
				for json path
			)
		
			--We can bypass license_service and call the vault insert directly
			exec usp_license_insert_external_reference_vault @license_external_reference_vault_json = @license_external_reference_vault_json, @license_service_type_name = 'license_vault_add'

			--10.3 Update @provisioning_data with license_external_reference_vault_ids inserted via the above
			update p 
			set p.license_external_reference_vault_id = lrv.license_external_reference_vault_id
			from @provisioning_data p
				inner join dbo.license_external_reference_vault lrv
					on lrv.license_id = p.license_id and lrv.license_category_id = p.license_category_id and lrv.vault_id = p.vault_id

			--10.4 Inserting external reference data
			select @loop_value = (select min(id) from @provisioning_data), @loop_max = (select max(id) from @provisioning_data)
			while @loop_value <= @loop_max
				begin
					select @effective_object_id = p.effective_object_id, @license_external_reference_vault_id = p.license_external_reference_vault_id, 
						@external_reference_value = case when e.object_element_name = 'customer_short_name' then p.customer_short_name else p.tenant end
					from @provisioning_data p
						inner join dbo.effective_object e
							on e.effective_object_id = p.effective_object_id
					where p.id = @loop_value

					if @effective_object_id is not null and @external_reference_value is not null
						begin
							exec usp_license_insert_external_reference @license_id = @license_id, @license_category_id = @license_category_id, @effective_object_id = @effective_object_id, @external_reference_value = @external_reference_value, @license_external_reference_vault_id = @license_external_reference_vault_id, @return_license_external_reference_id = 0
						end

					select @effective_object_id = null, @license_external_reference_vault_id = null, @external_reference_value = null, @loop_value = @loop_value + 1
				end
		end

		
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--11. Update staging data
	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	----Commenting out for testing in dev, to not disturb the Feed dataset
	--Uncommented the below code to update the licenseid/Order_itemid in the backfill_contract table
	update bc 
	set order_item_id = oi.order_item_id, license_id = @license_id
	from DATAWAREHOUSEREADONLY.Feed.dbo.backfill_contract bc
		inner join order_item oi with (nolock)
			on oi.order_header_id = @order_header_id
	where bc.contract_line_id = @contract_line_id

	select @order_header_id as order_header_id, @license_id as license_id

end try
begin catch

	declare @DBName nvarchar(128)
	select @message = 'Netsuite order and license insert failed for contract_line_id ' + convert(varchar(20), @contract_line_id)
	select @message as message
	select @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_next_id]
-- =============================================================================

CREATE PROC [dbo].[usp_next_id] @Type int
WITH EXECUTE AS CALLER
AS
BEGIN
	declare @sqlStmt varchar(1024)
	declare @sequenceName varchar(1024)
	declare @activated int

	if ( @Type <1) OR (@Type > 12) OR (@Type in (1, 2, 12))
	begin
		select -1
		return
	end
	--------------------------------------------------------
	-- Table schema 'dbo' should not be added 
	-- Check against information schema will fail.
	--------------------------------------------------------
	set @sequenceName = CASE @Type
				WHEN 3 THEN 'Invoices'
				WHEN 4 THEN 'Affiliate_Assigned_Number'
				WHEN 5 THEN 'Prices'
				WHEN 6 THEN 'Price_Dates'
				WHEN 7 THEN 'Authorizations'
				WHEN 8 THEN 'Commissions'
				WHEN 9 THEN 'Comm_Dates'
				WHEN 10 THEN 'Groups'
				WHEN 11 THEN 'UPDATE_Requests'
			    END + '_sequence'
	
	set nocount on
	begin transaction
	if  not exists( select 1 from information_schema.tables
			where table_type= 'BASE TABLE'
			and table_name= @sequenceName)
	begin
		UPDATE ids SET 
			next_id = next_id + 1, 
			last_modified = GetDate()
		WHERE id_type = @Type

		SELECT next_id
		FROM ids
		WHERE id_type = @Type
	end
	else begin
		create table #rows (
			rows int
		)
		exec ('insert into #rows select top 1 SEQUENCE_ID from '+ @sequenceName)
		select @activated = rows from #rows
		drop table #rows

		if (@activated is NULL)
		begin
			set nocount on
			UPDATE ids SET 
				next_id = next_id + 1, 
				last_modified = GetDate()
			WHERE id_type = @Type

			SELECT next_id
			FROM ids
			WHERE id_type = @Type
		end
		else begin
			set 	@sqlStmt = 'insert into ' + 
				@sequenceName + 
				' (insert_date) values (getdate())
				select scope_identity() as next_id'
			exec (@sqlStmt)

		end
	end
	set nocount off
	Commit transaction
END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_billing_multi_account_audit_obsolete]
-- =============================================================================

CREATE procedure [dbo].[usp_oracle_billing_multi_account_audit_obsolete]
/*	
	DATE		AUTHOR		REMARKS
	2019-10-01	abelenkiy	Initial creation.

	DESCRIPTION
	Creates and sends report of Oracle company records with a unique account_number but same company_id.
*/
as
	begin try

		-- 1) stage data
		drop table if exists ##multi_account;

		-- 1.1) create cte with in-scope comany_ids
		with multi_company
		as (select company_id
			from openquery (ORACLEEBS, 'select * from XXWEB_EXT_CUSTOMER_SUMMARY') --could pull from oracle_ext_customer_summary instead
			group by company_id
			having count(distinct account_number) > 1)

		-- 1.2) select into temp table; sky_account_customer left joined in case of of these manages to register
		select sac.sky_account_customer_id
			 , cs.company_id
			 , cs.cust_account_id
			 , cs.account_number
			 , cs.party_id
			 , cs.party_name
			 , cs.currency_code
		into ##multi_account
		from multi_company mc
			inner join openquery (ORACLEEBS, 'select * from XXWEB_EXT_CUSTOMER_SUMMARY') cs on mc.company_id = cs.company_id
			left join dbo.sky_account_customer sac on sac.company_id = cs.company_id;

		-- 1.3) return if no records found
		if @@rowcount = 0
			return;

		-- 2) decare vars for send_dbmail
		declare @subject  nvarchar(255) = convert(varchar(50), getdate(), 23) + ' - Companies with more than one account in Oracle'
			  , @filename nvarchar(260) = convert(varchar(50), getdate(), 23) + ' - Companies with more than one account in Oracle.csv'
			  , @tab	  char(1)	   = char(9);

		-- 3) execute send_dbmail
		exec msdb..sp_send_dbmail @recipients = 'abelenkiy@webroot.com'
								--, @copy_recipients = 'abelenkiy@webroot.com'
								, @subject = @subject
								, @body_format = 'HTML'
								, @body = '<html><body><h4>Companies with more than one account in Oracle</h4>
											<p>Please see the attached report for companies with more than one account in Oracle.</p>
											</body></html>'
								, @query = 'select * from ##multi_account order by sky_account_customer_id desc, company_id desc'
								, @attach_query_result_as_file = 1
								, @query_result_header = 1
								, @query_attachment_filename = @filename
								, @query_result_separator = @tab
								, @exclude_query_output = 1
								, @query_result_no_padding = 1
								, @query_result_width = 500;
	end try
	begin catch
		declare @DBName nvarchar(128);
		set @DBName = db_name();
		exec usp_LogError @ErrorDB = @DBName;
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_billing_select_current_status_obsolete]
-- =============================================================================
CREATE procedure [dbo].[usp_oracle_billing_select_current_status_obsolete]
(@company_id int)

/*	
	DATE		AUTHOR		REMARKS
	2019-04-15	abelenkiy	Initial creation.
	2019-04-29	abelenkiy	Updated to use company_id as input instead of keycode
	2019-07-25	abelenkiy	Updated to select only summary records with not null currency; if only summaries available have null currencies, summary with max account_number is selected
	2019-09-11	abelenkiy	Added [TAX_INFORMATION] field to output

	DESCRIPTION
	Billing portal - Selects current status and balance information for a company.
*/

as
set nocount on;
set transaction isolation level read uncommitted;

	begin try

		--select
		--	oecs.account_number
		--  , oecs.party_name
		--  , oecs.currency_code
		--  , oecs.amount_due_total
		--  , oecs.amount_past_due
		--  , oecs.amount_current
		--  , oecs.amount_credits
		--  , oecs.address_line_1
		--  , oecs.address_line_2
		--  , oecs.address_line_3
		--  , oecs.address_line_4
		--  , oecs.city
		--  , oecs.state
		--  , oecs.zip
		--  , oecs.country
		--from	dbo.oracle_ext_customer_summary oecs
		--where	oecs.company_id = @company_id;

		declare @comp_summary table
		(
			account_number varchar(50)
		  , party_name nvarchar(200)
		  , currency_code varchar(50)
		  , amount_due_total money
		  , amount_past_due money
		  , amount_current money
		  , amount_credits money
		  , address_line_1 nvarchar(200)
		  , address_line_2 nvarchar(200)
		  , address_line_3 nvarchar(200)
		  , address_line_4 nvarchar(200)
		  , city nvarchar(200)
		  , state nvarchar(200)
		  , zip nvarchar(200)
		  , country nvarchar(200)
		  , tax_information nvarchar(200)
		);

		insert	@comp_summary
		select
			oecs.account_number
		  , oecs.party_name
		  , oecs.currency_code
		  , oecs.amount_due_total
		  , oecs.amount_past_due
		  , oecs.amount_current
		  , oecs.amount_credits
		  , oecs.address_line_1
		  , oecs.address_line_2
		  , oecs.address_line_3
		  , oecs.address_line_4
		  , oecs.city
		  , oecs.state
		  , oecs.zip
		  , oecs.country
		  , oecs.tax_information
		from	dbo.oracle_ext_customer_summary oecs
		where	oecs.company_id = @company_id
				and oecs.currency_code is not null;

		if @@rowcount = 0
			insert	@comp_summary
			select	top 1
					oecs.account_number
				  , oecs.party_name
				  , oecs.currency_code
				  , oecs.amount_due_total
				  , oecs.amount_past_due
				  , oecs.amount_current
				  , oecs.amount_credits
				  , oecs.address_line_1
				  , oecs.address_line_2
				  , oecs.address_line_3
				  , oecs.address_line_4
				  , oecs.city
				  , oecs.state
				  , oecs.zip
				  , oecs.country
				  , oecs.tax_information
			from	dbo.oracle_ext_customer_summary oecs
			where	oecs.company_id = @company_id
			order by oecs.account_number desc;

		select
			cs.account_number
		  , cs.party_name
		  , cs.currency_code
		  , cs.amount_due_total
		  , cs.amount_past_due
		  , cs.amount_current
		  , cs.amount_credits
		  , cs.address_line_1
		  , cs.address_line_2
		  , cs.address_line_3
		  , cs.address_line_4
		  , cs.city
		  , cs.state
		  , cs.zip
		  , cs.country
		  , cs.tax_information
		from	@comp_summary cs;

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;






GO
