CREATE procedure [dbo].[usp_oracle_billing_select_payment_summary_obsolete]
(@company_id int)

/*	
	DATE		AUTHOR		REMARKS
	2019-06-28	abelenkiy	Initial creation.

	DESCRIPTION
	Billing portal - Selects payment summary for a company.
*/

as
set nocount on;
