-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_billing_select_pending_payments_obsolete]
-- =============================================================================

CREATE procedure [dbo].[usp_oracle_billing_select_pending_payments_obsolete] 

(@company_id int, @transaction_number int = null)

/*	
	DATE		AUTHOR		REMARKS
	2019-07-23	abelenkiy	Initial creation
	2019-08-23	abelenkiy	Changed logic to allow for multiple payment_header records on one invoice
	2019-09-20	abelenkiy	Added comments and re-formatted

	DESCRIPTION
	Billing portal - Selects open transactions with pending payments.
*/
as
set nocount on;

set transaction isolation level read uncommitted;

	begin try
		-- 1.1) create temp table of all invoices for a company with open balances and existing payment_header_id
		drop table if exists #pending_payment_table;

		select oets.transaction_id
			 , oets.transaction_number
			 , oph.payment_header_id
			 , oets.po_number
			 , cast(null as tinyint) as status
		into #pending_payment_table
		from oracle_ext_trans_summary oets
			inner join oracle_ext_trans_balance oetb on oetb.transaction_id = oets.transaction_id
			inner join order_payment_header oph on oph.oracle_invoice_number = oets.transaction_number
		where oetb.remaining_balance != 0
			  and oets.company_id = @company_id;

		-- 1.2) set status to 1 if invoice exists in oracle_update table
		update #pending_payment_table
		set status = 1
		from #pending_payment_table t
			inner join oracle_update ou on ou.payment_header_id = t.payment_header_id
		where exists (select 1
					  from oracle_update ou2
					  where ou2.oracle_update_id = ou.oracle_update_id
							and ou.oracle_template_id = 1);

		--invoice_credit_card

		-- 1.3) set status to 2 if invoice exists in oracle_update_archive table
		update #pending_payment_table
		set status = 2
		from #pending_payment_table t
			inner join oracle_update_archive oua on oua.payment_header_id = t.payment_header_id
		where exists (select 1
					  from oracle_update_archive oua2
					  where oua2.oracle_update_id = oua.oracle_update_id
							and oua.oracle_template_id = 1 --invoice_credit_card
							and oua.oracle_update_type_id = 3 --update_invoice
							and oua.oracle_update_status_id = 1 --Processed
							and oua.archive_date > getdate() - 1) --in order to not show payments as pending if they still have a balance in oracle 24 hours after payment

		-- 1.4) select all records with a status from temp table
		select distinct t.transaction_id
					  , t.transaction_number
					  , t.payment_header_id
					  , t.po_number
					  , t.status
		from #pending_payment_table t
		where t.status is not null
			  and t.transaction_number = isnull(@transaction_number, t.transaction_number);

		drop table if exists #pending_payment_table;
	end try

	begin catch
		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_billing_select_transaction_detail]
-- =============================================================================
CREATE procedure [dbo].[usp_oracle_billing_select_transaction_detail]
(@transaction_number int)

/*	
	DATE		AUTHOR		REMARKS
	2019-04-15	abelenkiy	Initial creation.
	2019-04-29	abelenkiy	Updated to use company_id as input instead of keycode
	2019-06-27	abelenkiy	Added po_number to select
	2019-06-28	abelenkiy	Removed company_id from required params
	2019-07-01	abelenkiy	Added company_id to output
	2019-07-23	abelenkiy	Changed transaction_id input to transaction_number
	2020-03-24	abelenkiy	Added inner join to oracle_ext_customer_summary on company_id; this ensures no transactions from 
								merged companies are picked up because old company will not exist in customer_summary refresh

	DESCRIPTION
	Billing portal - Selects transaction lines for one transaction.
*/

as
set nocount on;
set transaction isolation level read uncommitted;

	begin try

		select
			oetd.transaction_id
		  , oets.transaction_number
		  , oetd.transaction_line_id
		  , oetd.product_id
		  , oetd.product_code
		  , oetd.product_description
		  , oetd.trans_line_description
		  , oetd.currency_code
		  , oetd.line_number
		  , oetd.quantity
		  , oetd.uom
		  , oetd.line_amount
		  , oetd.tax_amount
		  , oetd.total_line_amount
		  , oetd.from_date
		  , oetd.to_date
		  , oetd.contract_term
		  , oetd.po_number
		  , oets.company_id
		from	oracle_ext_trans_details oetd
			inner join oracle_ext_trans_summary oets on oets.transaction_id = oetd.transaction_id
			inner join oracle_ext_customer_summary oecs on oecs.company_id = oets.company_id
		where	oets.transaction_number = @transaction_number
		order by oetd.transaction_line_id asc;

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_billing_select_transaction_summary]
-- =============================================================================

CREATE procedure [dbo].[usp_oracle_billing_select_transaction_summary]
(
	@company_id int = null
  , @transaction_number int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-04-15	abelenkiy	Initial creation.
	2019-04-29	abelenkiy	Updated to use company_id as input instead of keycode
	2019-07-03	abelenkiy	Included nullable transaction_id variable to return summary for one transaction
	2019-07-23	abelenkiy	Changed transaction_id input to transaction_number
	2019-08-21	abelenkiy	Added join to oracle_ext_customer_summary on cust_account_id to always traverse to invoices from summary
	2022-06-08	abelenkiy	Made company_id nullable to support use of this proc for legacy invoices in Pay Your Invoice
							Added order_opportunity join to return array of opportunities for Oracle invoice when available
							Improved error handling

	DESCRIPTION
	Billing portal - Selects header level transaction list for a company or limits to one transaction if optional transaction_id passed in.

	For the SAP integration, this proc now selects salesforce_opportunity based on a join through the new oracle_ext_oracle_invoice_order_header 
	table, which will be populated during the backfill. This procedure and usp_oracle_billing_select_transaction_detail are the only procedures 
	with the prefix "usp_oracle_billing_select..." that will continue to be used post-integration.
*/

as
set nocount on;
set transaction isolation level read uncommitted;

	begin try

		select distinct
			oets.transaction_id
		  , oets.transaction_number
		  , oets.currency_code
		  , oets.transaction_amount
		  , oets.pretax_amount
		  , oets.tax_amount
		  , oets.transaction_creation_date
		  , oets.transaction_date
		  , oets.due_date
		  , oetb.remaining_balance
		  , oets.po_number
		  , oecs.account_number
		  , sa.sap_account_number
		  , oecs.company_id
		  , (select oo.salesforce_opportunity_id
			from oracle_ext_oracle_invoice_order_header oioh 
				inner join order_opportunity oo 
					on oo.order_header_id = oioh.order_header_id 
			where oioh.oracle_transaction_number = oets.transaction_number
			order by oo.order_opportunity_id desc
			for json path) order_opportunity_json
		from	oracle_ext_trans_summary oets
			inner join oracle_ext_trans_balance oetb on oetb.transaction_id = oets.transaction_id
			inner join oracle_ext_customer_summary oecs on oecs.cust_account_id = oets.cust_account_id
			left join sap_account sa on sa.company_id = oecs.company_id
		where	oecs.company_id = isnull(@company_id, oecs.company_id)
				and oets.transaction_number = isnull(@transaction_number, oets.transaction_number)
		order by oets.transaction_date desc;

	end try
	begin catch

		declare
			@error_severity int = error_severity(), @error_state int = error_state(), @message nvarchar(4000)
		set @message = 'company_id = ' + convert(varchar(20), isnull(@company_id, 'null')) 
					+ ', transaction_number = ' + convert(varchar(20), isnull(@transaction_number, 'null'))
					+ ': ' + error_message()
		raiserror(@message, @error_severity, @error_state) with log

		insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_insert_failure_reprocess]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_insert_failure_reprocess]

(
	@oracle_update_failure_id int, 
	@process_date datetime = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-11-23		esmart			Initial creation
	
	DESCRIPTION
	select oracle_contract
*/

as

	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @process_date is null begin select @process_date = getdate() end

	insert into oracle_update(oracle_template_id,oracle_update_type_id,process_date,update_attempts,payment_header_id,order_license_usage_id,license_id)
	select oracle_template_id, oracle_update_type_id, @process_date, update_attempts, payment_header_id, order_license_usage_id, license_id
	from oracle_update_failure f
	where oracle_update_failure_id = @oracle_update_failure_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'reprocess failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
