-- PROCEDURE: [dbo].[usp_oracle_insert_invoice_payment_log]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_oracle_insert_invoice_payment_log]
	@oracle_invoice_number int = null,
	@oracle_invoice_json varchar(max) = null,
	@oracle_invoice_payment_log_id int = null,
	@oracle_invoice_response_text varchar(1000) = null

/*	
	DATE		AUTHOR		REMARKS
	2020-05-06	cnovac		Initial creation.

*/
as

set nocount on

begin try

	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- insert into oracle_invoice_payment_log
	----------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @oracle_invoice_payment_log_id is null
	begin

		insert into oracle_invoice_payment_log (oracle_invoice_number, oracle_invoice_json)
		select @oracle_invoice_number, @oracle_invoice_json

		select @oracle_invoice_payment_log_id = scope_identity()
	end
	else
	begin

		update oracle_invoice_payment_log
		set oracle_invoice_response_text = @oracle_invoice_response_text,
			modified_date = getdate()
		where oracle_invoice_payment_log_id = @oracle_invoice_payment_log_id
	end

	select @oracle_invoice_payment_log_id as oracle_invoice_payment_log_id

end try
begin catch

	declare @response_code int,
			@message varchar(100),
			@DBName nvarchar(128)

	set @response_code = -200
	set @message = case when @message is null then 'error processing usp_oracle_insert_invoice_payment_log'
						else @message end
	set @DBName = db_name()

	exec usp_LogError @ErrorDB = @DBName

end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_insert_oracle_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_insert_oracle_update]

(
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null,
	@oracle_template_name varchar(50),
	@oracle_invoice_number int = null,
	@order_license_usage_id int = null,
	@license_id int = null,
	@sap_invoice_number varchar(20) = null,
	@oracle_update_json nvarchar(2000) = null
)

/*	
	DATE		AUTHOR			REMARKS
	2015-01-27	esmart			Initial creation.
	2015-05-16	esmart			Move @payment_header_id as an input parameter
	2015-10-22	esmart			@order_license_usage
	2022-02-18	abelenkiy		Added @sap_invoice_number as input parameter; updated section 2.3 to use sap_invoice_number; 
								updated error handling in catch block; changed @oracle_template_name to required input
	2022-03-17	abelenkiy		Added @oracle_update_json as input parameter and updated section 2.2 to log @oracle_update_json
	2022-06-09	abelenkiy		Added back handling of @oracle_invoice_number to support payment of converted invoices;

	DESCRIPTION
	Inserts records to the oracle_update queue, which is now being used for SAP.

	This should be the only procedure doing direct inserts into the oracle_update table, though, as of 2022-03-17,
	usp_company_update_company_configuration also does a direct insert; that should probably be changed in the future.

*/

AS
	set nocount on				
    
	declare	@oracle_template_id tinyint,
			@oracle_update_type_id tinyint,
			@oracle_update_id int,
			@process_date datetime,
			@message nvarchar(4000)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select 
	if @payment_header_id is null
		begin
			select @payment_header_id = payment_header_id
			from dbo.payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
		end

	-- 1.2) check for existing oracle update
	select @oracle_update_id = oracle_update_id		
	from dbo.oracle_update
	where payment_header_id = @payment_header_id
	

	if @oracle_update_id is null
		begin
		select @oracle_update_id = oracle_update_id		
		from dbo.oracle_update
		where order_license_usage_id = @order_license_usage_id
		end

	if @oracle_update_id is not null
		begin
		select oracle_update_id = @oracle_update_id
		end

	-- 1.3) @oracle_template_id
	select @oracle_template_id = oracle_template_id from dbo.oracle_template where oracle_template_name = @oracle_template_name

	if @oracle_template_id is null
		begin
			raiserror ('Invalid oracle_template_name.', 16, 1)
		end

	-- 1.4) @oracle_update_type_id
	select @oracle_update_type_id = (select top 1 oracle_update_type_id 
									from dbo.oracle_template_update_type 
									where oracle_template_id = @oracle_template_id
									order by oracle_template_update_type_id)
									

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) @process_date
	select @process_date = dateadd(second, 60, getdate())	

	-- 2.2) insert oracle_update
	insert into dbo.oracle_update (payment_header_id, oracle_template_i
d, oracle_update_type_id, process_date, order_license_usage_id, license_id)
	values (@payment_header_id, @oracle_template_id, @oracle_update_type_id, @process_date, @order_license_usage_id, @license_id)

	select @oracle_update_id = scope_identity()

	if @oracle_update_json is not null
	begin
		insert into oracle_update_json (oracle_update_id, oracle_update_json)
		values(@oracle_update_id, @oracle_update_json)
	end

	-- 2.3) update order_payment_header
	if @payment_header_id is not null
		begin
			update dbo.order_payment_header 
			set sap_invoice_number = @sap_invoice_number,
				oracle_invoice_number = @oracle_invoice_number
			where payment_header_id = @payment_header_id
		end

	select oracle_update_id = @oracle_update_id
	
	end try

	begin catch

		declare
			@error_severity int = error_severity(), @error_state int = error_state()
		set @message = 'salesforce_opportunity_id = ' + convert(varchar(20), isnull(@salesforce_opportunity_id, 'null')) 
					+ ', sap_invoice_number = ' + convert(varchar(20), isnull(@sap_invoice_number, 'null'))
					+ ', oracle_invoice_number = ' + convert(varchar(20), isnull(@oracle_invoice_number, 'null'))
					+ ': ' + error_message()
		raiserror(@message, @error_severity, @error_state) with log

		insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_process_ext_objects]
-- =============================================================================

CREATE procedure [dbo].[usp_oracle_process_ext_objects]

/*	
	DATE		AUTHOR		REMARKS
	2019-02-11	cnovac		Initial creation.
	2019-04-25	abelenkiy	Added support for company_email table.
	2019-06-06	abelenkiy	Removed support for company_email and renamed ecom_customer_id to company_id
	2019-06-10	abelenkiy	Changed all tables to trunc/insert
	2019-06-27	abelenkiy	Added payment_summary table and po_number field to trans_details table
	2019-06-28	abelenkiy	Reverted to incremental load for select tables
	2019-09-11	abelenkiy	Added [TAX_INFORMATION] field to customer_summary
	2019-09-26	abelenkiy	Changed hard-coded link server name to ORACLEEBS
	2019-10-25	abelenkiy	Changed select from link server to use OPENQUERY
	2020-03-23	abelenkiy	Added oracle_ext_customer_merge_data table as incremental input; added section comments

	DESCRIPTION
	Imports data from Oracle views to ecom for billing portal.
*/

as
set nocount on;

	begin try

		-- 1) set up variables and drop temp tables if exist
		declare
			@max_trans_summary_record_id   int
		  , @max_trans_details_record_id   int
		  , @max_payment_summary_record_id int
		  , @max_cust_merge_record_id  int

		drop table if exists #oracle_ext_customer_summary
		drop table if exists #oracle_ext_trans_summary
		drop table if exists #oracle_ext_trans_balance
		drop table if exists #oracle_ext_trans_details
		drop table if exists #oracle_ext_payment_summary
		drop table if exists #oracle_ext_customer_merge_data

		-- 2) load truncate/insert tables
		-- 2.1) oracle_ext_customer_summary
		select	cust_summary_record_id, record_creation_date, cust_account_id, account_number, party_id, party_name, company_id, currency_code, amount_due_total, amount_past_due, amount_current, amount_credits
		  , address_line_1, address_line_2, address_line_3, address_line_4, city, state, zip, country, tax_information
		into	#oracle_ext_customer_summary
		from	openquery(ORACLEEBS, 'select cust_summary_record_id, record_creation_date, cust_account_id, account_number, party_id, party_name, company_id, currency_code, amount_due_total, amount_past_due, amount_current, amount_credits
		  , address_line_1, address_line_2, address_line_3, address_line_4, city, state, zip, country, tax_information from XXWEB.XXWEB_EXT_CUSTOMER_SUMMARY')

		if @@rowcount > 0
			begin

				truncate table oracle_ext_customer_summary;
				insert into oracle_ext_customer_summary
				(cust_summary_record_id, record_creation_date, cust_account_id, account_number, party_id, party_name, company_id, currency_code, amount_due_total, amount_past_due, amount_current, amount_credits
				  , address_line_1, address_line_2, address_line_3, address_line_4, city, state, zip, country, tax_information)
				select	cust_summary_record_id, record_creation_date, cust_account_id, account_number, party_id, party_name, company_id, currency_code, amount_due_total, amount_past_due, amount_current, amount_credits
				  , address_line_1, address_line_2, address_line_3, address_line_4, city, state, zip, country, tax_information
				from	#oracle_ext_customer_summary;

			end;

		-- 2.2) oracle_ext_trans_balance
		select	BALANCE_RECORD_ID, RECORD_CREATION_DATE, TRANSACTION_ID, CURRENCY_CODE, TRANSACTION_AMOUNT, REMAINING_BALANCE
		into	#oracle_ext_trans_balance
		from	openquery(ORACLEEBS, 'select BALANCE_RECORD_ID, RECORD_CREATION_DATE, TRANSACTION_ID, CURRENCY_CODE, TRANSACTION_AMOUNT, REMAINING_BALANCE from XXWEB.XXWEB_EXT_TRANS_BALANCE')

		if @@rowcount > 0
			begin

				truncate table oracle_ext_trans_balance
				insert into oracle_ext_trans_balance
				(balance_record_id, record_creation_date, transaction_id, currency_code, transaction_amount, remaining_balance)
				select	balance_record_id
, record_creation_date, transaction_id, currency_code, transaction_amount, remaining_balance
				from	#oracle_ext_trans_balance;

			end;

		-- 3) load incremental tables
		-- 3.1) oracle_ext_trans_summary
		select	@max_trans_summary_record_id = isnull(max(trans_summary_record_id), 0)
		from	oracle_ext_trans_summary;

		select	trans_summary_record_id, record_creation_date, cust_account_id, company_id, transaction_id, transaction_number, currency_code, transaction_amount, pretax_amount, tax_amount, transaction_creation_date
		  , transaction_date, due_date, po_number
		into	#oracle_ext_trans_summary
		from	openquery(ORACLEEBS, 'select trans_summary_record_id, record_creation_date, cust_account_id, company_id, transaction_id, transaction_number, currency_code, transaction_amount, pretax_amount, tax_amount, transaction_creation_date
		  , transaction_date, due_date, po_number from XXWEB.XXWEB_EXT_TRANS_SUMMARY')
		where	trans_summary_record_id > @max_trans_summary_record_id;

		if @@rowcount > 0
			begin

				insert into oracle_ext_trans_summary
				(trans_summary_record_id, record_creation_date, cust_account_id, company_id, transaction_id, transaction_number, currency_code, transaction_amount, pretax_amount, tax_amount, transaction_creation_date
				  , transaction_date, due_date, po_number)
				select	trans_summary_record_id, record_creation_date, cust_account_id, company_id, transaction_id, transaction_number, currency_code, transaction_amount, pretax_amount, tax_amount, transaction_creation_date
				  , transaction_date, due_date, po_number
				from	#oracle_ext_trans_summary;

			end;

		-- 3.2) oracle_ext_trans_details
		select	@max_trans_details_record_id = isnull(max(trans_details_record_id), 0)
		from	oracle_ext_trans_details;

		select	TRANS_DETAIL_RECORD_ID, RECORD_CREATION_DATE, TRANSACTION_ID, TRANSACTION_LINE_ID, PRODUCT_ID, PRODUCT_CODE, PRODUCT_DESCRIPTION, TRANS_LINE_DESCRIPTION, CURRENCY_CODE, LINE_NUMBER, QUANTITY, UOM
		  , LINE_AMOUNT, TAX_AMOUNT, TOTAL_LINE_AMOUNT, FROM_DATE, TO_DATE, CONTRACT_TERM, PO_NUMBER
		into	#oracle_ext_trans_details
		from	openquery(ORACLEEBS, 'select TRANS_DETAIL_RECORD_ID, RECORD_CREATION_DATE, TRANSACTION_ID, TRANSACTION_LINE_ID, PRODUCT_ID, PRODUCT_CODE, PRODUCT_DESCRIPTION, TRANS_LINE_DESCRIPTION, CURRENCY_CODE, LINE_NUMBER, QUANTITY, UOM
		  , LINE_AMOUNT, TAX_AMOUNT, TOTAL_LINE_AMOUNT, FROM_DATE, TO_DATE, CONTRACT_TERM, PO_NUMBER from XXWEB_EXT_TRANS_DETAILS')
		where	TRANS_DETAIL_RECORD_ID > @max_trans_details_record_id;

		if @@rowcount > 0
			begin

				insert into oracle_ext_trans_details
				(trans_details_record_id, record_creation_date, transaction_id, transaction_line_id, product_id, product_code, product_description, trans_line_description, currency_code, line_number, quantity, uom
				  , line_amount, tax_amount, total_line_amount, from_date, to_date, contract_term, po_number)
				select	TRANS_DETAIL_RECORD_ID, record_creation_date, transaction_id, transaction_line_id, product_id, product_code, product_description, trans_line_description, currency_code, line_number, quantity, uom
				  , line_amount, tax_amount, total_line_amount, from_date, to_date, contract_term, po_number
				from	#oracle_ext_trans_details;

			end;

		-- 3.3) oracle_ext_payment_summary
		select	@max_payment_summary_record_id = isnull(max(payment_summary_record_id), 0)
		from	oracle_ext_payment_summary;

		select	PAYMENT_SUMMARY_RECORD_ID, RECORD_CREATION_DATE, CUST_ACCOUNT_ID, COMPANY_ID, PAYMENT_DATE, PAYMENT_RECEIPT_ID, CURRENCY_CODE, PAYMENT_AMOUNT
		into	#oracle_ext_payment_summary
		from	openquery(ORACLEEBS, 'select PAYMENT_SUMMARY_RECORD_ID, RECORD_CREATION_DATE, CUST_ACCOUNT_ID, COMPANY_ID, PAYMENT_DATE, PAYMENT_RECEIPT_ID, CURRENCY_CODE, PAYMENT_AMOUNT from XXWEB.XXWEB_EXT_PAYMENT_SUMMARY')
		where	PAYMENT_SUMMARY_RECORD_ID > @max_payment_summary_record_id;

		if @@rowcount > 0
			begin

				insert into oracle_ext_payment_sum
mary
				(payment_summary_record_id, record_creation_date, cust_account_id, company_id, payment_date, payment_receipt_id, currency_code, payment_amount)
				select	payment_summary_record_id, record_creation_date, cust_account_id, company_id, payment_date, payment_receipt_id, currency_code, payment_amount
				from	#oracle_ext_payment_summary;

			end;

		-- 3.4) oracle_ext_customer_merge_data
		select	@max_cust_merge_record_id = isnull(max(cust_merge_record_id), 0)
		from	oracle_ext_customer_merge_data;

		select	CUST_MERGE_RECORD_ID, RECORD_CREATION_DATE, CUST_ACCOUNT_ID, ACCOUNT_NUMBER, PARTY_ID, COMPANY_ID, MERGE_DATE
		into	#oracle_ext_customer_merge_data
		from	openquery(OracleEBS, 'select CUST_MERGE_RECORD_ID, RECORD_CREATION_DATE, CUST_ACCOUNT_ID, ACCOUNT_NUMBER, PARTY_ID, COMPANY_ID, MERGE_DATE from XXWEB.XXWEB_EXT_CUSTOMER_MERGE_DATA')
		where	CUST_MERGE_RECORD_ID > @max_cust_merge_record_id;

		if @@rowcount > 0
			begin
				select	@max_cust_merge_record_id = isnull(max(cust_merge_record_id), 0)
				from	oracle_ext_customer_merge_data;

				insert into oracle_ext_customer_merge_data
				(cust_merge_record_id, record_creation_date, cust_account_id, account_number, party_id, company_id, merge_date)
				select	cust_merge_record_id, record_creation_date, cust_account_id, account_number, party_id, company_id, merge_date
				from	#oracle_ext_customer_merge_data;

			end;



	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_next_oracle_update]
-- =============================================================================

CREATE procedure [dbo].[usp_oracle_select_next_oracle_update]

/*	
	DATE		AUTHOR			REMARKS
	2015-01-27	esmart			Initial creation.
	2015-10-29	esmart			Support order_license_usage and JSON update details
	2019-08-01	esmart			oracle_update_json
	2022-02-18	abelenkiy		Removed oracle_invoice_number, oracle_contract_number, and oracle_receipt_id;
								Updated error handling in catch block
	2022-06-09	abelenkiy		Added back handling of @oracle_invoice_number to support payment of converted invoices;

	DESCRIPTION
	Select next oracle_update 
*/

as

begin try

	set nocount on				

	declare	@update_details nvarchar(2000),
			@message nvarchar(4000)			

	declare @oracle_update table (oracle_update_id int, oracle_template_id tinyint, oracle_template_name varchar(50), 
								oracle_update_type_id tinyint, oracle_update_type_name varchar(50), payment_header_id int, 
								order_license_usage_id int, sap_invoice_number varchar(20), oracle_update_status_id tinyint, 
								insert_date datetime, process_date datetime, order_header_id int, oracle_invoice_number int,
								vendor_order_code varchar(100), salesforce_opportunity_id varchar(18), license_id int)

	insert into @oracle_update(oracle_update_id, oracle_template_id, oracle_template_name, oracle_update_type_id, 
			oracle_update_type_name, payment_header_id, order_license_usage_id, sap_invoice_number, oracle_update_status_id, 
			insert_date, process_date, order_header_id, vendor_order_code, salesforce_opportunity_id, license_id, 
			oracle_invoice_number)
	select top(1) o.oracle_update_id, t.oracle_template_id, t.oracle_template_name, ut.oracle_update_type_id, 
		ut.oracle_update_type_name, o.payment_header_id, o.order_license_usage_id, h.sap_invoice_number, 
		o.oracle_update_status_id, o.insert_date, o.process_date, h.order_header_id, v.vendor_order_code, 
		po.salesforce_opportunity_id, o.license_id, h.oracle_invoice_number
	from dbo.oracle_update o
	inner join dbo.oracle_template t
		on o.oracle_template_id = t.oracle_template_id
	inner join dbo.oracle_update_type ut
		on o.oracle_update_type_id = ut.oracle_update_type_id
	left join dbo.order_payment_header h
		ON o.payment_header_id = h.payment_header_id
	LEFT JOIN dbo.order_opportunity oo
		ON h.order_header_id = oo.order_header_id
	LEFT JOIN dbo.order_header oh
		ON h.order_header_id = oh.order_header_id
	LEFT JOIN dbo.vendor_order v
		ON oh.vendor_order_id = v.vendor_order_id
	LEFT JOIN dbo.payment_header_opportunity po
		ON o.payment_header_id = po.payment_header_id
	WHERE o.process_date <= GETDATE()
	ORDER BY o.process_date

	SELECT @update_details = (SELECT payment_header_id, order_license_usage_id, sap_invoice_number, oracle_invoice_number, 
									vendor_order_code, salesforce_opportunity_id, license_id, order_header_id
							FROM @oracle_update 
							FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)

	SELECT u.oracle_update_id, u.oracle_template_id, u.oracle_template_name, u.oracle_update_type_id, 
		u.oracle_update_type_name, u.oracle_update_status_id, u.insert_date, u.process_date,
		update_details = CASE WHEN j.oracle_update_json_id IS NOT NULL THEN j.oracle_update_json ELSE @update_details END
	FROM @oracle_update u
	LEFT JOIN dbo.oracle_update_json j
		ON u.oracle_update_id = j.oracle_update_id

end try

begin catch

	declare
		@error_severity int = error_severity(), @error_state int = error_state()
	set @message = error_message()
	raiserror(@message, @error_severity, @error_state) with log

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), 
@message, @@servername, db_name(), suser_name()

		
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_oracle_contract]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_select_oracle_contract]

(
	@order_item_id int = null,
	@order_header_id int = NULL,
	@oracle_template_name varchar(50) = NULL,
	@opportunity_line_item_id varchar(18) = null,
	@oracle_contract_status_name varchar(50) = null,
	@oracle_contract_line_status_name varchar(50) = null,
	@license_id int = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-11-23		esmart			Initial creation
	2016-03-27		esmart			Remove terminated lines from available list
	2017-02-07		esmart			module product support for SDNS
	2017-07-06		acoffel			Cancel Support
	2019-08-06		rvinoche		Refactor contract selection for cancel_autobilling template
	
	DESCRIPTION
	select oracle_contract
*/

as

	set nocount on			

	declare	@oracle_contract_line_status_id tinyint,
			@product_type_id int,
			@min_contract_line_id int,
			@license_category_id int,
			@min_cancellation_date DATE,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @license_id is not NULL and @oracle_template_name = 'cancel_autobilling'
	begin 
		
		select @min_cancellation_date = getdate() -1 --only records which were affected today (previous records were ended yesterday) at the earliest

		-- 1.1) all attributes where utility is ending
		declare @license_attributes table (license_id int, start_date datetime, end_date datetime, license_category_id tinyint)

		insert into @license_attributes (license_id, start_date, end_date, license_category_id)
		select @license_id, f.effective_start_date, f.effective_end_date, f.license_category_id 
		from dbo.fn_license_select_license_profile(@license_id) p
		inner join dbo.license_category lc
			on lc.license_category_name = p.license_category_name
		cross apply dbo.fn_license_select_effective_object_element_history(p.license_id,'license_attribute_license_value', lc.license_category_id) f
		where f.effective_value = 12
		and f.effective_end_date >= @min_cancellation_date
		and f.effective_end_date is not null

		-- 1.2) distinct contracts per license and category
		declare @oracle_contracts table (order_item_id int, license_category_id int, oracle_contract_id int, license_id int, effective_date datetime)

		insert into @oracle_contracts (order_item_id,license_category_id, oracle_contract_id, license_id, effective_date)
		select min(ocl.order_item_id), la.license_category_id, ocl.oracle_contract_id, la.license_id, la.end_date
        from @license_attributes la
		inner join dbo.oracle_contract_line_license ocll
			on ocll.license_id = la.license_id
		inner join dbo.oracle_contract_line ocl
			on ocl.oracle_contract_line_id = ocll.oracle_contract_line_id
		inner join dbo.order_item oi
			on oi.order_item_id = ocl.order_item_id
		inner join dbo.product_license_category plc
			on plc.product_id = oi.product_id
			and plc.license_category_id = la.license_category_id
		where ocl.oracle_contract_status_id not in (9) 
			and la.start_date <= ocl.end_date
		group by la.license_category_id, ocl.oracle_contract_id, la.license_id, la.end_date
		
		-- 1.3) results
		select t.oracle_contract_id, 
				oc.oracle_contract_number,
				oi.order_header_id,
				s.oracle_contract_status_name,
				oc.insert_date,
				oc.last_modified_date,
				ocl.oracle_contract_line_id,
				ocl.oracle_line_id,
				t.order_item_id,
				oracl
e_contract_line_start_date = ocl.start_date,
				oracle_contract_line_end_date = ocl.end_date,
				oracle_contract_line_status_name = s2.oracle_contract_status_name,
				t.license_id,
				l.keycode,
				p.product_type_id,
				t.license_category_id,
				t.effective_date
		from @oracle_contracts t
		inner join dbo.oracle_contract_line ocl
			on ocl.order_item_id = t.order_item_id
		inner join dbo.oracle_contract oc
			on oc.oracle_contract_id = t.oracle_contract_id
		inner join dbo.oracle_contract_status s
			on s.oracle_contract_status_id = oc.oracle_contract_status_id
		inner join dbo.oracle_contract_status s2
			on s2.oracle_contract_status_id = ocl.oracle_contract_status_id
		inner join dbo.order_item oi
			on oi.order_item_id = t.order_item_id
		inner join dbo.product p
			on p.product_id = oi.product_id
		inner join dbo.license l
			on l.license_id = t.license_id

	end
	else
	begin
		-- 1.1) check order_opportunity if @order_header_id is null
		if @order_item_id is null
			begin
			select @order_item_id = order_item_id from order_item_opportunity_line_item where opportunity_line_item_id = @opportunity_line_item_id
			end

		-- 1.2) @license_id contract order_item_id lookup
		if @order_item_id is null
			begin
			select @order_item_id = (select top 1 cl.order_item_id 
									from oracle_contract_line_license l
									inner join oracle_contract_line cl
										on cl.oracle_contract_line_id = l.oracle_contract_line_id
									where l.license_id = @license_id and cl.oracle_contract_status_id not in (9) -- and cl.start_date <= getdate() and getdate() < cl.end_date
									order by cl.order_item_id desc)
			end

			--print @order_item_id

		-- 1.3) @oracle_contract_status_name
		if @oracle_contract_status_name is null
			begin
			select @oracle_contract_status_name = 'Active'
			end

		-- 1.4) @oracle_contract_status_name
		if @oracle_contract_line_status_name is null
			begin
			select @oracle_contract_line_status_name = 'Active'
			end

		-- 1.5) @oracle_contract_line_status_id
		select @oracle_contract_line_status_id = oracle_contract_status_id
		from oracle_contract_status
		where oracle_contract_status_name = @oracle_contract_line_status_name

		-- 1.6) @product_type_id
		select @product_type_id = p.product_type_id, @license_category_id = plc.license_category_id
		from order_item i
		inner join product p
			on p.product_id = i.product_id
		inner join product_license_category plc
			on plc.product_id = p.product_id
		where i.order_item_id = @order_item_id

		--select @license_category_id

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) return 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @contract table (oracle_contract_id int,oracle_contract_number varchar(20),order_header_id int,oracle_contract_status_name varchar(50),insert_date datetime,last_modified_date datetime,oracle_contract_line_id int,
						oracle_line_id varchar(40),order_item_id int,oracle_contract_line_start_date datetime,oracle_contract_line_end_date datetime,oracle_contract_line_status_name varchar(50),license_id int,keycode varchar(40),
						product_type_id int,license_category_id int)


		-- 2.1) return data
		insert into @contract(oracle_contract_id, oracle_contract_number, order_header_id, oracle_contract_status_name, insert_date, last_modified_date, oracle_contract_line_id, oracle_line_id, order_item_id, oracle_contract_line_start_date, oracle_contract_line_end_date, oracle_contract_line_status_name, license_id, keycode, product_type_id, license_category_id)
		select oc.oracle_contract_id, 
					oc.oracle_contract_number, 
					i.order_
header_id, 
					s.oracle_contract_status_name, 
					--oracle_contract_start_date = oc.start_date, 
					--oracle_contract_end_date = oc.end_date, 
					oc.insert_date, 
					oc.last_modified_date,
					cl.oracle_contract_line_id, 
					cl.oracle_line_id, 
					i.order_item_id, 
					oracle_contract_line_start_date = cl.start_date, 
					oracle_contract_line_end_date = cl.end_date, 
					oracle_contract_line_status_name = sl.oracle_contract_status_name,
					ll.license_id, l.keycode,
					p.product_type_id,
					plc.license_category_id
		from order_item i
		inner join order_item_license il
			on il.order_item_id = i.order_item_id
		inner join license l
			on l.license_id = il.license_id
		inner join oracle_contract_line_license ll
			on ll.license_id = il.license_id
		inner join oracle_contract_line cl
			on cl.oracle_contract_line_id = ll.oracle_contract_line_id and cl.oracle_contract_status_id not in (9) and cl.start_date <= i.effective_date and i.effective_date < cl.end_date
		inner join order_item cli
			on cl.order_item_id = cli.order_item_id
		inner join product p
			on p.product_id = cli.product_id
		left join product_license_category plc
			on plc.product_id = p.product_id
		inner join oracle_contract_status sl
			on sl.oracle_contract_status_id = cl.oracle_contract_status_id
		inner join  oracle_contract oc
			on cl.oracle_contract_id = oc.oracle_contract_id
		inner join oracle_contract_status s
			on s.oracle_contract_status_id = oc.oracle_contract_status_id
		where i.order_item_id = @order_item_id-- and p.product_type_id = case when @product_type_id = 4 then @product_type_id else p.product_type_id end

		--select '@@ROWCOUNT' =  @@ROWCOUNT

		-- 2.2) no contract
		if @@ROWCOUNT = 0
			begin
			insert into @contract(order_header_id,order_item_id,license_id,keycode)
			select i.order_header_id,i.order_item_id,l.license_id,l.keycode
			from order_item i
			left join order_item_license il
				on il.order_item_id = i.order_item_id
			left join license l
				on l.license_id = il.license_id
			where i.order_item_id = @order_item_id
			end

		-- 2.3) null license_category_id on 
		update @contract
		set license_category_id = @license_category_id 
		where license_category_id is null

		-- 2.4) return
		select top 1 oracle_contract_id, oracle_contract_number, order_header_id, oracle_contract_status_name, insert_date, last_modified_date, oracle_contract_line_id, oracle_line_id, order_item_id, oracle_contract_line_start_date, oracle_contract_line_end_date, oracle_contract_line_status_name, license_id, keycode, product_type_id, license_category_id--, license_module_code = NULL
		from @contract
		where license_category_id = @license_category_id
		order by oracle_contract_line_id desc
	
	end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_oracle_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_select_oracle_update]

(
	@salesforce_opportunity_id varchar(20) = null, 
	@oracle_invoice_number int = null,
	@keycode varchar(40) = null,
	@oracle_template_name varchar(50) = null,
	@oracle_update_type_name varchar(50) = null,
	@oracle_update_status_name varchar(50) = null,
	@start_date datetime = null,
	@end_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-27	esmart		Initial creation.
	2016-03-01	esmart		
	2016-10-03	esmart		Add oracle_update_failure_id

	DESCRIPTION
	Select oracle update
*/

AS
	set nocount on				

	declare	@license_id int,
			@oracle_template_id tinyint,
			@oracle_update_type_id tinyint,
			@oracle_update_status_id tinyint,
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @license_id
	if @keycode is not null
		begin
		select @license_id = license_id from license where keycode = @keycode
		end

	-- 1.1) @oracle_template_id
	select @oracle_template_id = oracle_template_id from oracle_template where oracle_template_name = @oracle_template_name

	-- 1.1) @oracle_update_type_id
	select @oracle_update_type_id = oracle_update_type_id from oracle_update_type where oracle_update_type_name = @oracle_update_type_name

	-- 1.1) @oracle_update_status_id
	select @oracle_update_status_id = oracle_update_status_id from oracle_update_status where oracle_update_status_name = @oracle_update_status_name

	-- select oracle_update_status_id = @oracle_update_status_id, oracle_template_id = @oracle_template_id, oracle_update_type_id = @oracle_update_type_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	
	declare @oracle_update table (source varchar(20), oracle_update_id int,oracle_template_id tinyint,oracle_update_type_id tinyint,oracle_update_status_id tinyint,insert_date datetime,process_date datetime,update_attempts tinyint,payment_header_id int,order_license_usage_id int,license_id int, archive_date datetime, oracle_update_failure_id int, failure_description varchar(255))
	
	insert into @oracle_update(source, oracle_update_id,oracle_template_id,oracle_update_type_id,oracle_update_status_id,insert_date,process_date,update_attempts,payment_header_id,order_license_usage_id,license_id)
	select source = 'queue', o.oracle_update_id, o.oracle_template_id, o.oracle_update_type_id, o.oracle_update_status_id, o.insert_date, o.process_date, o.update_attempts, o.payment_header_id, o.order_license_usage_id, o.license_id
	from oracle_update o
	where o.oracle_template_id = case when @oracle_template_id is null then o.oracle_template_id else @oracle_template_id end and
			o.oracle_update_type_id = case when @oracle_update_type_id is null then o.oracle_update_type_id else @oracle_update_type_id end and
			o.oracle_update_status_id = case when @oracle_update_status_id is null then o.oracle_update_status_id else @oracle_update_status_id end and
		(o.process_date > @start_date or @start_date is null) and
		(o.process_date < @end_date or @end_date is null)

	insert into @oracle_update(
source, oracle_update_id,oracle_template_id,oracle_update_type_id,oracle_update_status_id,insert_date,process_date,update_attempts,payment_header_id,order_license_usage_id,license_id,archive_date)
	select source = 'archive', o.oracle_update_id, o.oracle_template_id, o.oracle_update_type_id, o.oracle_update_status_id, o.insert_date, o.process_date, o.update_attempts, o.payment_header_id, o.order_license_usage_id, o.license_id,o.archive_date
	from oracle_update_archive o
	where o.oracle_template_id = case when @oracle_template_id is null then o.oracle_template_id else @oracle_template_id end and
			o.oracle_update_type_id = case when @oracle_update_type_id is null then o.oracle_update_type_id else @oracle_update_type_id end and
			o.oracle_update_status_id = case when @oracle_update_status_id is null then o.oracle_update_status_id else @oracle_update_status_id end and
		(o.process_date > @start_date or @start_date is null) and
		(o.process_date < @end_date or @end_date is null)

	insert into @oracle_update(source, oracle_update_id,oracle_template_id,oracle_update_type_id,oracle_update_status_id,insert_date,process_date,update_attempts,payment_header_id,order_license_usage_id,license_id,archive_date,oracle_update_failure_id,failure_description)
	select source = 'failure', o.oracle_update_id, o.oracle_template_id, o.oracle_update_type_id, o.oracle_update_status_id, o.insert_date, o.process_date, o.update_attempts, o.payment_header_id, o.order_license_usage_id, o.license_id,o.failure_date,o.oracle_update_failure_id,o.failure_description
	from oracle_update_failure o
	where o.oracle_template_id = case when @oracle_template_id is null then o.oracle_template_id else @oracle_template_id end and
			o.oracle_update_type_id = case when @oracle_update_type_id is null then o.oracle_update_type_id else @oracle_update_type_id end and
		(o.process_date > @start_date or @start_date is null) and
		(o.process_date < @end_date or @end_date is null)




	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) delete non-matching
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @license_id is not null
		begin
		delete from @oracle_update
		where oracle_update_id not in (select oracle_update_id 
									from @oracle_update 
									where license_id = @license_id or order_license_usage_id in (select order_license_usage_id from order_license_usage where license_id = @license_id))


		end
	if @salesforce_opportunity_id is not null or @oracle_invoice_number is not null
		begin
		delete from @oracle_update
		where oracle_update_id not in (select oracle_update_id 
										from @oracle_update
										where payment_header_id in (select payment_header_id from payment_header_opportunity where salesforce_opportunity_id = @salesforce_opportunity_id) 
											or payment_header_id in (select payment_header_id from order_payment_header where oracle_invoice_number = @oracle_invoice_number and oracle_invoice_number is not null)
											)

		end

	select *  from @oracle_update o
	return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		select o.source, o.oracle_update_id, o.oracle_template_id, t.oracle_template_name, o.oracle_update_type_id, ut.oracle_update_type_name, o.oracle_update_status_id, s.oracle_update_status_name, o.insert_date, o.process_date, o.update_attempts, o.payment_header_id
, o.order_license_usage_id, o.license_id, l.keycode, payment_status_name = ps.payment_status_name,archive_date,o.oracle_update_failure_id,o.failure_description
		from @oracle_update o
		inner join oracle_template t
			on o.oracle_template_id = t.oracle_template_id
		inner join oracle_update_type ut
			on o.oracle_update_type_id = ut.oracle_update_type_id
		inner join oracle_update_status s
			on o.oracle_update_status_id = s.oracle_update_status_id
		left join order_license_usage u
			on u.order_license_usage_id = o.order_license_usage_id
		left join license l
			on l.license_id = u.license_id or o.license_id = l.license_id
		left join payment_header h
			on h.payment_header_id = o.payment_header_id
		left join payment_status ps
			on ps.payment_status_id = h.payment_status_id
		order by o.process_date

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_order_item]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_oracle_select_order_item]

(
	@order_header_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2018-10-25	esmart		Initial creation.
	2019-02-26	esmart		Make left join to license for opps without license (e.g. manual excess usage, bulk load)
	2019-04-22	cnovac		Added symbol columns to output
	2019-05-08	abelenkiy	Added support for license_usage_pricing_value in effective_object
	2019-06-24	abelenkiy	Added line_item and product_id to output

	DESCRIPTION
	select order_item data for Oracle interface
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select i.order_item_id,
				p.product_id,
				p.root_product_id, 
				p.product_description, 
				pt.product_type_id, 
				pt.product_type_description, 
				lc.license_category_name, 
				i.quantity, 
				i.unit_price, 
				c.currency_code, 
				i.item_total, 
				i.tax, 
				i.effective_date, 
				i.capability_expiration_date, 
				i.item_hierarchy_id, 
				i.line_item,
				il.license_id, 
				l.keycode, 
				license_key = convert(varchar(36),k.license_key), 
				k.salesforce_license_id, 
				usage_price = cast(dbo.fn_license_select_effective_object_element(il.license_id, lc.license_category_id, 'license_usage_pricing_value', i.effective_date) as money)/100,
				v.license_attribute_license_value, 
				v.license_attribute_license_value_description,
				c.symbol_html, 
				c.symbol_utf8, 
				c.symbol_text
		from order_item i
		inner join order_currency oc
			on i.order_header_id = oc.order_header_id
		inner join currency c
			on oc.currency_id = c.currency_id
		inner join product p
			on i.product_id = p.product_id
		inner join product_type pt
			on p.product_type_id = pt.product_type_id
		inner join product_license_category plc
			on p.product_id = plc.product_id
		inner join license_category lc
			on plc.license_category_id = lc.license_category_id
		left join order_item_license il
			on i.order_item_id = il.order_item_id
		left join license l
			on il.license_id = l.license_id
		left join license_key k
			on l.license_id = k.license_id
		left join license_attribute_license_value v
			on v.license_attribute_license_value = dbo.fn_license_select_effective_object_element(il.license_id, lc.license_category_id, 'license_attribute_license_value', i.effective_date)
		where i.order_header_id = @order_header_id
		order by i.order_item_id

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_order_item_contract_line]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_oracle_select_order_item_contract_line]

(
	@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2018-10-25	esmart		Initial creation.
	2018-12-21	esmart		Support for utility contract lines

	DESCRIPTION
	select oracle_contract_line data for Oracle interface
*/

AS

set nocount on				

begin try

		declare	@license_id int, 
				@effective_date datetime, 
				@capability_expiration_date datetime, 
				@evergreen_order_extension_value varchar(50),
				@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @license_id and @effective_date
		select @license_id = il.license_id, @effective_date = i.effective_date, @capability_expiration_date = i.capability_expiration_date, @evergreen_order_extension_value = e.order_extension_value
		from order_item i
		inner join order_item_license il
			on i.order_item_id = il.order_item_id
		left join order_extension e
			on i.order_header_id = e.order_header_id and e.order_extension_type_id = 8
		where i.order_item_id = @order_item_id

		-- 1.2) @contract_line
		declare @contract_line table (oracle_contract_number varchar(20), oracle_contract_line_id int, oracle_contract_id int, oracle_line_id varchar(40), license_id int, license_category_name varchar(10), oracle_contract_status_name varchar(50), order_item_id int, start_date datetime, end_date datetime, evergreen varchar(50))

		insert into @contract_line (oracle_contract_number, oracle_contract_line_id, oracle_contract_id, oracle_line_id, license_id, license_category_name, oracle_contract_status_name, order_item_id, start_date, end_date, evergreen)
		select oc.oracle_contract_number, cl.oracle_contract_line_id, cl.oracle_contract_id, cl.oracle_line_id, cll.license_id, lc.license_category_name, cs.oracle_contract_status_name, cl.order_item_id, cl.start_date, cl.end_date, e.order_extension_value
		from oracle_contract_line_license cll
		inner join oracle_contract_line cl
			on cll.oracle_contract_line_id = cl.oracle_contract_line_id 
				and cl.oracle_contract_status_id not in (9) 
				--and cl.start_date <= @effective_date -- remove this so we see the future dated renewal contract on an upsell
		inner join oracle_contract_status cs
			on cl.oracle_contract_status_id = cs.oracle_contract_status_id
		inner join oracle_contract oc
			on cl.oracle_contract_id = oc.oracle_contract_id
		inner join order_item i
			on cl.order_item_id = i.order_item_id
		inner join product_license_category plc
			on i.product_id = plc.product_id
		inner join license_category lc
			on plc.license_category_id = lc.license_category_id
		left join order_extension e
			on i.order_header_id = e.order_header_id and e.order_extension_type_id = 8
		where cll.license_id = @license_id

		delete cl 
		from @contract_line cl
		where cl.end_date > @capability_expiration_date
		
		-- 1.3) contract lines
		select lp.license_id, lp.license_category_name, lp.category_type_name, lp.item_hierarchy_id, cl.oracle_contract_line_id, cl.oracle_contract_id, cl.oracle_contract_number, cl.oracle_line_id, cl.oracle_contract_status_name, cl.order_item_id, cl.start_date, cl.end_date
		from dbo.fn_license_select_license_profile(@license_id) lp
		left join @contract_line cl
				on lp.license_id = cl.license_id and lp.license_category_name = cl.license_category_name --and lp.item_hierarchy_id = 1
					and cl.end_date > case when cl.evergr
een = 'Y' and cl.evergreen = @evergreen_order_extension_value then dateadd(dd,-1,cl.end_date) else @effective_date end  -- for selecting primary contract line on evergreen

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_select_template_update_type]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_select_template_update_type]

(
	@oracle_template_id tinyint = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	

		DESCRIPTION
		select template update type
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) create table
	declare @template_update_type table (step_id tinyint identity(1,1), oracle_template_id tinyint, oracle_template_name varchar(50), oracle_update_type_id tinyint, oracle_update_type_name varchar(50), next_update_type_id tinyint, next_update_type_name varchar(50))

	-- 1.2) insert rows
	insert into @template_update_type(oracle_template_id, oracle_template_name, oracle_update_type_id, oracle_update_type_name, next_update_type_id, next_update_type_name)
	select t.oracle_template_id, 
			t.oracle_template_name, 
			u.oracle_update_type_id, 
			u.oracle_update_type_name, 
			next_update_type_id = n.oracle_update_type_id, 
			next_update_type_name = n.oracle_update_type_name
	from oracle_template_update_type tu
	inner join oracle_template t
		on tu.oracle_template_id = t.oracle_template_id
	inner join oracle_update_type u
		on tu.oracle_update_type_id = u.oracle_update_type_id
	left join oracle_update_type n
		on tu.next_update_type_id = n.oracle_update_type_id
	where tu.oracle_template_id = case when @oracle_template_id is null then tu.oracle_template_id else @oracle_template_id end
	order by tu.oracle_template_update_type_id

	-- 1.3) return results
	select step_id, oracle_template_id, oracle_template_name, oracle_update_type_id, oracle_update_type_name, next_update_type_id, next_update_type_name
	from @template_update_type
	order by step_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_update_oracle_contract]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_oracle_update_oracle_contract]

(
	@order_header_id int,
	@order_item_id int,
	@oracle_contract_id int,
	@oracle_contract_number varchar(20),
	@oracle_contract_status_name varchar(50) = null,
	@oracle_line_id varchar(40),
	@oracle_contract_line_start_date datetime,
	@oracle_contract_line_end_date datetime,
	@oracle_contract_line_status_name varchar(50) = null,
	@previous_oracle_line_id varchar(40) = null,
	@previous_contract_line_status_name varchar(50) = null,
	@previous_contract_line_effective_date datetime = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-11-23		esmart			Initial creation
	
	DESCRIPTION
	update oracle_contract
*/

AS
	
	set nocount on			

	declare	@oracle_contract_status_id tinyint,
			@oracle_contract_line_status_id tinyint,
			@last_modified_date datetime,
			@oracle_contract_line_id int,
			@license_id int,
			@response_code int,
			@message varchar(100)

	begin try

	select @last_modified_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @oracle_contract_status_id
	select @oracle_contract_status_id = oracle_contract_status_id from oracle_contract_status where oracle_contract_status_name = @oracle_contract_status_name

	if @oracle_contract_status_id is null
		begin
		select @oracle_contract_status_id = 1
		end
	
	-- 1.0) @oracle_contract_line_status_id
	select @oracle_contract_line_status_id = oracle_contract_status_id from oracle_contract_status where oracle_contract_status_name = @oracle_contract_line_status_name

	if @oracle_contract_line_status_id is null
		begin
		select @oracle_contract_line_status_id = 1
		end

	-- 1.1) oracle_contract
	if @oracle_contract_id is not null and not exists (select oracle_contract_id from oracle_contract where oracle_contract_id = @oracle_contract_id)
		-- 1.1.1) insert oracle_contract
		begin
		-- print('1.1.1 insert oracle_contract')
		insert into oracle_contract(oracle_contract_id,oracle_contract_number,oracle_contract_status_id,insert_date,last_modified_date)
		select @oracle_contract_id,@oracle_contract_number,@oracle_contract_status_id,@last_modified_date,@last_modified_date
		end
	else
		-- 1.1.2) update oracle_contract
		begin
		if (select oracle_contract_status_id from oracle_contract where oracle_contract_id = @oracle_contract_id) <> @oracle_contract_status_id
			begin
			-- print('1.1.2) update oracle_contract')
			update oracle_contract
			set oracle_contract_status_id = @oracle_contract_status_id, 
				last_modified_date = @last_modified_date
			where oracle_contract_id = @oracle_contract_id
			end
		end

	-- 1.2) oracle_contract_line
	
	-- 1.2.1) previous contract line
	if @previous_oracle_line_id is not null
		begin
		-- print '1.2.1 previous'
		--select @license_id = license_id
		--from oracle_contract_line
		--where oracle_line_id = @previous_oracle_line_id

		update oracle_contract_line
		set end_date = @previous_contract_line_effective_date
		where oracle_contract_line_id = @previous_oracle_line_id
		end

	if @oracle_line_id is not null and not exists (select oracle_contract_line_id from oracle_contract_line where oracle_line_id = @oracle_line_id)
		-- 1.2.1) insert oracle_contract_line
		begin
		--print '1.2.1) insert oracle_contract_line'
		insert into oracle_contract_line(oracle_contract_id, oracle_line_id, oracle_contract_status_id, start_date, end_date, order_item_id, insert_date, last_modified_date)
		values(@oracle_
contract_id, @oracle_line_id, @oracle_contract_line_status_id, @oracle_contract_line_start_date, @oracle_contract_line_end_date, @order_item_id, @last_modified_date, @last_modified_date)

		select @oracle_contract_line_id = scope_identity()
		end
	else
		-- 1.2.2) update oracle_contract_line
		begin
		
		select @oracle_contract_line_id = oracle_contract_line_id from oracle_contract_line where oracle_line_id = @oracle_line_id
		
		if (select oracle_contract_status_id from oracle_contract_line where oracle_line_id = @oracle_line_id) <> @oracle_contract_line_status_id
			begin
			insert into oracle_contract_line_audit(oracle_contract_line_id,oracle_contract_id,oracle_line_id,oracle_contract_status_id,order_item_id,start_date,end_date,insert_date,last_modified_date)
			select oracle_contract_line_id,oracle_contract_id,oracle_line_id,oracle_contract_status_id,order_item_id,start_date,end_date,insert_date,last_modified_date
			from oracle_contract_line
			where oracle_line_id = @oracle_line_id

			--print('1.2.2) update oracle_contract_line')
			update oracle_contract_line 
			set oracle_contract_status_id = @oracle_contract_line_status_id,  
				-- start_date = @oracle_contract_line_start_date,
				end_date = @oracle_contract_line_end_date,
				last_modified_date = @last_modified_date
			where oracle_line_id = @oracle_line_id
			end
		end

	-- 1.3) oracle_contract_order
	if @oracle_contract_id is not null and not exists (select oracle_contract_id from oracle_contract_order where oracle_contract_id = @oracle_contract_id and order_header_id = @order_header_id) and @order_header_id is not null
		-- 1.3.1) insert oracle_contract_order
		begin
		--print('1.3.1) insert oracle_contract_order')
		insert into oracle_contract_order(oracle_contract_id,order_header_id,insert_date)
		values(@oracle_contract_id,@order_header_id,@last_modified_date)
		end
	--else
	--	-- 1.3.2) update oracle_contract_order
	--	begin
	--	print('1.3.2) update oracle_contract_order')

	--	end
	
	-- 1.4) oracle_contract_line_license
	insert into oracle_contract_line_license(oracle_contract_line_id,license_id,insert_date)
	select l.oracle_contract_line_id,il.license_id,@last_modified_date
	from oracle_contract_line l
	inner join order_item_license il
		on l.order_item_id = il.order_item_id
	left join oracle_contract_line_license cl
		on cl.oracle_contract_line_id = l.oracle_contract_line_id and il.license_id = cl.license_id
	where l.oracle_contract_id = @oracle_contract_id and l.order_item_id = @order_item_id and cl.license_id is null
		
	


	return

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_oracle_update_oracle_update]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_oracle_update_oracle_update]

(
	@oracle_update_id int,
	@oracle_update_status_name varchar(20),
	@failure_description varchar(255) = null,
	@oracle_invoice_number int = null,
	@oracle_receipt_id int = null,
	@sap_invoice_number varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-27	esmart		Initial creation.
	2016-01-12	esmart		Add order_license_usage_id to audit and failure insert
	2016-08-16	esmart		Add update to order_item for utility
	2017-06-06	esmart		Add update to order_license_usage.oracle_update_status_id
	2019-01-10	rvinoche	Support autobilling attributes living only in license_effective_object
	2019-03-05	rvinoche	Update utility contract end dates with overage template
	2022-02-18	abelenkiy	Added @sap_invoice_number as input parameter; 
							updated all oracle_invoice_number references to sap_invoice_number in 2.1.0 and 2.2.0; 
							removed references to oracle_receipt_id; updated error handling in catch block
	2022-06-05	abelenkiy	Append @sap_invoice_number to update_json if received/exists (section 2.1.1);
							reinstated logic to reattempt on failure (section 2.2.1)
							reinstated @oracle_invoice_number handling to support payments on legacy Oracle invoices
							added code to update Oracle invoice balance to show correct balance in Billing Portal on 
								paid legacy Oracle invoices (section 2.1.2.4)
	2022-10-21	abelenkiy	Removed extra delete from section 2.2 to fix incrementing on failure
	2023-07-03	gblandford	https://jira.opentext.com/browse/ECOM-1582 - Update the code around extension of capability_expiration on order_item and oracle_contract_line 
								to use sap objects (section 2.1.2.1) and also write to order_item_audit and new table sap_order_item_audit
	2025-03-18  psatish		US-4404934 Commented out the script that updated the sap_end_date to the next billing process date
	
	DESCRIPTION
	Called by PHP to report success or failure of an oracle_update record. This queue was repurposed for use with SAP.
	Records are written to the oracle_update table by usp_oracle_insert_oracle_update and selected by 
	usp_oracle_select_next_oracle_update. 

	The oracle_contract and oracle_contract_line code of this procedure remain intact despite the procedure being repurposed.
	This code will not have any impact where there is no mapping to those tables. Future consideration should be given to 
	whether this procedure should update sap_order_item in a similar way.

*/

as

	begin try

	set nocount on				

	declare	@oracle_update_type_id tinyint,
			@oracle_template_id tinyint,
			@next_update_type_id tinyint,
			@oracle_update_status_id tinyint,
			@transaction_date datetime,
			@payment_header_id int,
			@update_attempts tinyint,
			@sfdc_template_name varchar(50), 
			@order_header_id int, 
			@trial_id int, 
			@form_submit_id int, 
			@process_date datetime, 
			@order_license_usage_id int,
			@license_attribute_license_value int,
			@order_license_attribute_value int,
			@message nvarchar(4000)			




	-- ----------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ----------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get update data
	select @oracle_update_type_id = oracle_update_type_id, @oracle_template_id = oracle_template_id, 
		@payment_header_id = payment_header_id, @order_license_usage_id = order_license_usage_id
	from oracle_update
	where oracle_update_id = @oracle_update_id

	select @order_license_attribute_value = license_attribute_license_value 
	from dbo.order_license_usage 
	where order_license_usage_id =
 @order_license_usage_id

	select @transaction_date = getdate()

	-- ----------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ----------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) processed
	if @oracle_update_status_name = 'Processed'
		begin
			
			select @oracle_update_status_id = 1

			-- 2.1.0) @sap_invoice_number / @oracle_invoice_number 
			if @sap_invoice_number is not null or @oracle_invoice_number is not null
				begin
					update order_payment_header 
					set sap_invoice_number = @sap_invoice_number,
						oracle_invoice_number = @oracle_invoice_number -- this is only to support legacy Oracle payments
					where payment_header_id = @payment_header_id

					-- 2.1.1) update json with sap_invoice_number if both exist
					update oracle_update_json
					set oracle_update_json = json_modify(oracle_update_json, '$.sap_invoice_number', @sap_invoice_number)
					where oracle_update_id = @oracle_update_id
				end

			-- 2.1.1) insert archive
			insert into oracle_update_archive(oracle_update_id, oracle_template_id, oracle_update_type_id, 
				oracle_update_status_id, insert_date, process_date, update_attempts, payment_header_id, archive_date, 
				order_license_usage_id, license_id)
			select oracle_update_id, oracle_template_id, oracle_update_type_id, @oracle_update_status_id, insert_date, 
				process_date, update_attempts, payment_header_id, @transaction_date, order_license_usage_id, license_id
			from oracle_update
			where oracle_update_id = @oracle_update_id

			select @next_update_type_id = next_update_type_id
			from oracle_template_update_type 
			where oracle_update_type_id = @oracle_update_type_id and oracle_template_id = @oracle_template_id
	

			if @next_update_type_id is null
			-- 2.1.2) final queue update
				begin
					-- 2.1.2.1) update contract_line end date on utility
					if @oracle_template_id = 2 -- process_license_usage_overage
						and @oracle_update_type_id = 7 -- sfdc_update_usage
						and @order_license_attribute_value = 12 -- utility

						begin
						select @license_attribute_license_value = dbo.fn_license_select_effective_object_element(
																			u.license_id, 
																			lcl.license_category_id,
																			'license_attribute_license_value',
																			m.process_date)
						from dbo.order_license_usage u
						inner join dbo.license_message m
							on u.license_id = m.license_id
						inner join dbo.license_category_license lcl
							on lcl.license_id = u.license_id
						where u.order_license_usage_id = @order_license_usage_id 
							and m.message_type_id = 10 
							and m.message_status_id = 1


						if @license_attribute_license_value = 12

							BEGIN
												
								--INSERT INTO dbo.sap_order_item_audit (
								--	sap_order_item_id,
								--    sap_order_id,
								--    sap_order_status_id,
								--    sap_item_number,
								--    order_item_id,
								--    usage_item,
								--    start_date,
								--    end_date,
								--    insert_date,
								--    insert_by,
								--    modified_date,
								--    modified_by,
								--    delivery_item_number,
								--    po_line_number
								--)
								--SELECT soi.sap_order_item_id
								--	  , soi.sap_order_id
								--	  , soi.sap_order_status_id
								--	  , soi.sap_item_number
								--	  , soi.order_item_id
								--	  , soi.usage_item
								--	  , soi.start_date
								--	  , soi.end_date
								--	  , soi.insert_date
								--	  , soi.insert_by
								--	  , soi.modified_date
								--	  , soi.modified_by
								--	  , soi.delivery_item_number
								--	  , soi.po_line_number
								--FROM dbo.order_license_usage olu
								--INNER JOIN dbo.sap_order_item_license soil
								--	ON soil.license
_id = olu.license_id
								--INNER JOIN dbo.sap_order_item soi
								--	ON soi.sap_order_item_id = soil.sap_order_item_id
								--INNER JOIN dbo.license_message m
								--	ON olu.license_id = m.license_id and m.message_status_id = 1
								--WHERE olu.order_license_usage_id = @order_license_usage_id
								--	AND soi.start_date <= olu.end_date 
								--	AND olu.end_date <= soi.end_date

								--UPDATE soi
								--	SET end_date = DATEADD(dd, -1, m.process_date)
								--FROM dbo.order_license_usage olu
								--INNER JOIN dbo.sap_order_item_license soil
								--	ON soil.license_id = olu.license_id
								--INNER JOIN dbo.sap_order_item soi
								--	ON soi.sap_order_item_id = soil.sap_order_item_id
								--INNER JOIN dbo.license_message m
								--	ON olu.license_id = m.license_id and m.message_status_id = 1
								--WHERE olu.order_license_usage_id = @order_license_usage_id
								--	AND soi.start_date <= olu.end_date 
								--	AND olu.end_date <= soi.end_date;

								INSERT INTO dbo.order_item_audit (
									order_item_id,
									order_header_id,
									line_item,
									product_id,
									quantity,
									list_price,
									unit_price,
									tax,
									order_item_offer_id,
									order_item_offer_amount,
									item_total,
									tax_exempt,
									effective_date,
									order_item_status_id,
									insert_date,
									insert_by,
									modified_date,
									modified_by,
									capability_expiration_date,
									item_bundle_id,
									order_item_update_type_id,
									audit_date,
									sap_material_number
								)
								SELECT 
									oi.order_item_id,
									oi.order_header_id,
									oi.line_item,
									oi.product_id,
									oi.quantity,
									oi.list_price,
									oi.unit_price,
									oi.tax,
									oi.order_item_offer_id,
									oi.order_item_offer_amount,
									oi.item_total,
									oi.tax_exempt,
									oi.effective_date,
									oi.order_item_status_id,
									oi.insert_date,
									oi.insert_by,
									oi.modified_date,
									oi.modified_by,
									oi.capability_expiration_date,
									oi.item_bundle_id,
									oi.order_item_update_type_id,
									GETDATE(),
									oi.sap_material_number
								FROM dbo.order_license_usage olu
								INNER JOIN dbo.sap_order_item_license soil
									ON soil.license_id = olu.license_id
								INNER JOIN dbo.sap_order_item soi
									ON soi.sap_order_item_id = soil.sap_order_item_id
								INNER JOIN dbo.license_message m
									ON olu.license_id = m.license_id AND m.message_status_id = 1
								INNER JOIN dbo.order_item oi
									ON oi.order_item_id = soi.order_item_id
								WHERE olu.order_license_usage_id = @order_license_usage_id;


								UPDATE oi
									SET oi.capability_expiration_date = DATEADD(mm , 1, oi.capability_expiration_date)
								FROM dbo.order_license_usage olu
								INNER JOIN dbo.sap_order_item_license soil
									ON soil.license_id = olu.license_id
								INNER JOIN dbo.sap_order_item soi
									ON soi.sap_order_item_id = soil.sap_order_item_id
								INNER JOIN dbo.license_message m
									ON olu.license_id = m.license_id AND m.message_status_id = 1
								INNER JOIN dbo.order_item oi
									ON oi.order_item_id = soi.order_item_id
								WHERE olu.order_license_usage_id = @order_license_usage_id

							END
					END
			
					-- 2.1.2.2) update order_license_usage oracle_update_status_id
					UPDATE order_license_usage
					SET oracle_update_status_id = 1, modified_date = @transaction_date
					WHERE order_license_usage_id = @order_license_usage_id

					-- 2.1.2.3) delete oracle_update
					DELETE FROM oracle_update
					WHERE oracle_update_id = @oracle_update_id

					-- 2.1.2.4) handle legacy oracle invoice balance update
					IF @oracle_invoice_number IS NOT NULL
						BEGIN
							INSER
T INTO oracle_ext_trans_balance_audit (oracle_ext_trans_balance_id, balance_record_id, 
								record_creation_date, transaction_id, currency_code, transaction_amount, remaining_balance, 
								insert_date, oracle_update_id)
							SELECT oetb.oracle_ext_trans_balance_id, oetb.balance_record_id, oetb.record_creation_date, 
								oetb.transaction_id, oetb.currency_code, oetb.transaction_amount, oetb.remaining_balance, 
								oetb.insert_date, @oracle_update_id
							FROM oracle_ext_trans_balance oetb
								INNER JOIN oracle_ext_trans_summary oets 
									ON oets.transaction_id = oetb.transaction_id
							WHERE oets.transaction_number = @oracle_invoice_number

							UPDATE oracle_ext_trans_balance
							SET remaining_balance = 0
							FROM oracle_ext_trans_summary oets 
							WHERE oets.transaction_id = oracle_ext_trans_balance.transaction_id
								AND oets.transaction_number = @oracle_invoice_number

						END

				END
			ELSE
			-- 2.1.3) update queue
				BEGIN
					-- print '2.1.3'
					UPDATE oracle_update
					SET oracle_update_type_id = @next_update_type_id, process_date = @transaction_date
					WHERE oracle_update_id = @oracle_update_id

				END

			-- 2.1.4) set up next update table 
			DECLARE @next_update TABLE (oracle_update_id INT, payment_header_id INT, oracle_update_type_id TINYINT, 
				oracle_update_type_name VARCHAR(50))

			INSERT INTO @next_update(oracle_update_id, payment_header_id, oracle_update_type_id, oracle_update_type_name)
			SELECT TOP 1 u.oracle_update_id, u.payment_header_id, t.oracle_update_type_id, t.oracle_update_type_name
			FROM oracle_update u
			INNER JOIN oracle_update_type t
				ON u.oracle_update_type_id = t.oracle_update_type_id
			WHERE u.process_date <= @transaction_date AND u.oracle_update_id = @oracle_update_id
			ORDER BY u.oracle_update_id

			-- 2.1.5) return results
			IF (SELECT COUNT(*) FROM @next_update) = 0
				BEGIN
				-- 2.1.5.1) final result
				SELECT oracle_update_id = @oracle_update_id, payment_header_id = @payment_header_id, 
					oracle_update_type_id=NULL, oracle_update_type_name=NULL

				END
			ELSE
				BEGIN
				--print '2.1.5.2'
				-- 2.1.5.3) next result
				SELECT oracle_update_id, payment_header_id, oracle_update_type_id, oracle_update_type_name
				FROM @next_update
				END
			
		END

	-- 2.2) failed
	IF @oracle_update_status_name = 'Failed'
		BEGIN
		
		SELECT @oracle_update_status_id = 2

		-- 2.2.0) @oracle_invoice_number and @oracle_receipt_id
		IF @sap_invoice_number IS NOT NULL
			BEGIN
				UPDATE order_payment_header 
				SET sap_invoice_number = @sap_invoice_number,
					oracle_invoice_number = @oracle_invoice_number -- this is only to support legacy Oracle payments
				WHERE payment_header_id = @payment_header_id
			END

		-- 2.2.1) insert failure
		INSERT INTO oracle_update_failure(oracle_update_id, oracle_template_id, oracle_update_type_id, 
			oracle_update_status_id, insert_date, process_date, update_attempts, payment_header_id, failure_description, 
			failure_date, order_license_usage_id, license_id)
		SELECT oracle_update_id, oracle_template_id, oracle_update_type_id, @oracle_update_status_id, insert_date, 
			process_date, update_attempts, payment_header_id, @failure_description, @transaction_date, 
			order_license_usage_id, license_id
		FROM oracle_update
		WHERE oracle_update_id = @oracle_update_id

		SELECT @update_attempts = update_attempts
		FROM oracle_update
		WHERE oracle_update_id = @oracle_update_id

		IF @update_attempts < 5
			-- 2.2.2) update queue
			BEGIN
				UPDATE oracle_update
				SET process_date = DATEADD(HOUR,1,@transaction_date), update_attempts = @update_attempts + 1
				WHERE oracle_update_id = @oracle_update_id
			END
		ELSE
			-- 2.2.3) delete queue
			BEGIN
				DELETE FROM oracle_update
				WHERE oracle_update_id = @oracle_update_id
			END

		END

	END TRY


	BEGIN CATCH


	DECLARE
		@
error_severity INT = ERROR_SEVERITY(), @error_state INT = ERROR_STATE()
	SET @message = 'oracle_update_id = ' + CONVERT(VARCHAR(20), ISNULL(@oracle_update_id, 'null')) 
				+ ', sap_invoice_number = ' + CONVERT(VARCHAR(20), ISNULL(@sap_invoice_number, 'null'))
				+ ', oracle_invoice_number = ' + CONVERT(VARCHAR(20), ISNULL(@oracle_invoice_number, 'null'))
				+ ', oracle_update_status_name = ' + CONVERT(VARCHAR(20), ISNULL(@oracle_update_status_name, 'null'))
				+ ': ' + ERROR_MESSAGE()
	RAISERROR(@message, @error_severity, @error_state)

	INSERT INTO DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, 
		ErrorDB, ErrorUser)
	SELECT ERROR_NUMBER(), ERROR_SEVERITY(), ERROR_STATE(), ERROR_PROCEDURE(), ERROR_LINE(), @message, @@servername, 
		DB_NAME(), SUSER_NAME()
		
	end catch;


GO
