-- =============================================================================
CREATE PROCEDURE [dbo].[usp_oracle_update_split_order_item]

(
	@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2019-01-14	esmart		Initial creation.
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
	DESCRIPTION
	Split order_item accross two oracle_contract_line records
*/

AS

set nocount on				

begin try

		declare	@order_header_id int, 
				@new_order_item_id int, 
				@new_effective_date datetime, 
				@capability_expiration_date datetime, 
				@unit_price money, 
				@daily_unit_price money, 
				@current_contract_days int, 
				@new_contract_days int, 
				@current_unit_price money, 
				@new_unit_price money,
				@daily_tax money, 
				@tax money, 
				@current_tax money, 
				@new_tax money, 
				@quantity int, 
				@max_line_item int,
				@license_id int,
				@response_code int,
				@message varchar(100)

		declare @contract_line table (license_id int, license_category_name varchar(10), category_type_name varchar(50), item_hierarchy_id tinyint, oracle_contract_line_id int, oracle_contract_id int, oracle_contract_number varchar(20), oracle_line_id varchar(40), oracle_contract_status_name varchar(50), order_item_id int, start_date datetime, end_date datetime)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) select contract lines
		insert into @contract_line (license_id, license_category_name, category_type_name, item_hierarchy_id, oracle_contract_line_id, oracle_contract_id, oracle_contract_number, oracle_line_id, oracle_contract_status_name, order_item_id, start_date, end_date)
		exec usp_oracle_select_order_item_contract_line @order_item_id

			-- 1.1.1) if only one contract line return
			if @@ROWCOUNT = 1 return
		
			-- 1.1.2) @new_effective_date
			select @new_effective_date = max(start_date)
			from @contract_line

		-- 1.2) select current order_item data
		select	@daily_unit_price = i.unit_price/datediff(dd,i.effective_date,i.capability_expiration_date),
				@unit_price = i.unit_price,
				@daily_tax = i.tax/datediff(dd,i.effective_date,i.capability_expiration_date),
				@tax = i.tax,				
				@current_contract_days = datediff(dd,i.effective_date,@new_effective_date),
				@new_contract_days = datediff(dd,@new_effective_date,i.capability_expiration_date),
				@capability_expiration_date = i.capability_expiration_date,
				@quantity = i.quantity,
				@license_id = il.license_id,
				@order_header_id = i.order_header_id
		from order_item i
		inner join order_item_license il
			on i.order_item_id = il.order_item_id
		where i.order_item_id = @order_item_id

		-- 1.3) @max_line_item
		select @max_line_item = max(i.line_item)
		from order_item i
		where i.order_header_id = @order_header_id

		-- 1.4) set price
		select @current_unit_price = round(@daily_unit_price*@current_contract_days,2)
		select @new_unit_price = @unit_price - @current_unit_price

		select @current_tax = round(@daily_tax*@current_contract_days,2)
		select @new_tax = @tax - @current_tax
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) insert/update
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert new item
		insert into order_item (order_header_id, line
_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, item_hierarchy_id)
		select order_header_id, line_item = i.line_item + 1, product_id, quantity, list_price, unit_price = @new_unit_price, tax = @new_tax, order_item_offer_id, order_item_offer_amount, item_total = @new_unit_price*i.quantity, tax_exempt, effective_date = @new_effective_date, order_item_status_id, getdate(), 'contract_split', getdate(), 'contract_split', capability_expiration_date, item_bundle_id, order_item_update_type_id, item_hierarchy_id
		from order_item i
		where i.order_item_id = @order_item_id

		select @new_order_item_id = scope_identity()

			-- 2.1.1) insert order_item_license
			insert into order_item_license (order_item_id, license_id) values(@new_order_item_id,@license_id)

		-- 2.2) update

			-- 2.2.1) insert audit
			insert into order_item_audit(order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
			select order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, getdate(), sap_material_number
			from order_item
			where order_item_id = @order_item_id

			-- 2.2.2) update order_item
			update i
			set unit_price = @current_unit_price,
					item_total =  @current_unit_price*i.quantity,
					tax = @current_tax,
					capability_expiration_date =  @new_effective_date, -- dateadd(dd,-1,@new_effective_date),
					modified_date = getdate(), 
					modified_by = 'contract_split'
			from order_item i
			where i.order_item_id = @order_item_id

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_affiliate_daily_sales]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_affiliate_daily_sales]

(
	  @affiliate_code varchar(16),
	  @for_month datetime
)

AS
/*    
	    DATE    		AUTHOR  		REMARKS
	    2006-09-05 		pwilliams  		Initial creation.
	
	    DESCRIPTION
	    Yields sales summary data for affiliates

  */       

	  select 
				affiliate_order_history.product_id,    
	         product_description,
				affiliate_order_history.promotion_code,
	         dateadd(day, datediff(day,0,order_date), 0) as order_day, 
	         sum(units_sold) as units_sold, 
	         sum(dollars_sold) as dollars_sold, 
	         sum(units_returned) as units_returned, 
	         sum(dollars_returned) as dollars_returned
	    from affiliate_order_history 
	    join product 
		on product.product_id = affiliate_order_history.product_id
	    where affiliate_code = @affiliate_code and
	          order_date between dateadd(mm, datediff(mm,0,@for_month), 0) and 
	                             dateadd(ms,-3, dateadd(mm, datediff(m,0,@for_month)+1, 0))
	    group by affiliate_order_history.product_id,
	             dateadd(day, datediff(day,0,order_date), 0),
	             product_description,
					 affiliate_order_history.promotion_code
	    order by dateadd(day, datediff(day,0,order_date), 0),
	             affiliate_order_history.product_id

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_affiliate_monthly_sales]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_affiliate_monthly_sales]

(
	@affiliate_code varchar(16),
	@start_month datetime,
	@end_month datetime
)

AS
/*    
	    DATE    	AUTHOR 	 REMARKS
	    2006-09-05	esmart    	Initial creation.
	
	    DESCRIPTION
	    Yields sales summary data for affiliates

  */       

	  select 
			p.product_id, 
			p.product_description,
			h.promotion_code,
		         dateadd(mm, datediff(mm,0,order_date), 0) as order_month, 
		         sum(units_sold) as units_sold, 
		         sum(dollars_sold) as dollars_sold, 
		         sum(units_returned) as units_returned, 
		         sum(dollars_returned) as dollars_returned
	    from affiliate_order_history h
	    join product p
		on h.product_id = p.product_id
	    where affiliate_code = @affiliate_code and
	        		  order_date between dateadd(mm, datediff(mm,0,@start_month), 0) and 
	                             dateadd(ms,-3, dateadd(mm, datediff(m,0,@end_month)+1, 0))
	    group by 
		p.product_id, 
		p.product_description,
		h.promotion_code,
	             dateadd(mm, datediff(mm,0,order_date), 0)
	    order by dateadd(mm, datediff(mm,0,order_date), 0),
	             p.product_id

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_disable_autorenewal]
-- =============================================================================
create PROCEDURE [dbo].[usp_order_disable_autorenewal]
	-- Add the parameters for the stored procedure here
	@order_header_id int = 0
AS

/*	select * from dberrorlog
	date				author			remarks
	2007-09-18			bjordan			Initial Creation

	description
	Adjusts the number of seats based on quantity for renewal Enterprise and SME orders
	
*/
set nocount on
BEGIN Try
	DECLARE @keycode varchar(40), @license_id int, @customer_id int
	DECLARE @product_family_id int, @product_id int
	DECLARE @cybs_customer_profile_id int, @license_customer_id int
	declare @autorenewal_status int
	declare @result int, @message varchar(100)

	begin transaction
	-- Auto renewal product family
	select @product_family_id = 22
	select top 1 @product_id = p.product_id from order_item oi
	inner join product p with (nolock) on
	oi.product_id = p.product_id
	where oi.order_header_id = @order_header_id
		and	p.product_family_id = @product_family_id

	-- Auto renewal disable

	if (@product_id = 302 or @product_id = 303)
		BEGIN
			SELECT @license_id = oil.license_id 
			from order_item_license oil with (nolock)
			inner join order_item oi with (nolock) on 
			oi.order_item_id = oil.order_item_id 
			inner join product p with (nolock) on 
			oi.product_id = p.product_id
			inner join license l with (nolock) on 
			oil.license_id = l.license_id
			where oi.order_header_id = @order_header_id

			if (@license_id is NOT NULL)
				begin
				
					set @autorenewal_status = case when @product_id = 302 then 3
												   when @product_id = 303 then 2
												   else null end

					exec usp_license_attribute_license_update_by_tag @license_id, 'AUTORENEWAL', @autorenewal_status, NULL, @result OUT, @message OUT
					-- we ignore that the flag is updated twice.
				end
		END

commit transaction;
end try
begin catch

	 if @@trancount > 0
			  rollback transaction;

      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		
	
end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_header_select_by_id]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_order_header_select_by_id]

	@order_header_id int

/*	
	DATE		AUTHOR	REMARKS
	2006-08-23	tblazek		Initial creation.
	2006-08-29	tblazek		To support refund application, add p_rc to result set.
	2006-09-28	tblazek		Per ticket #5022, add p_ac to result set
	2006-12-18	tblazek		Suppress customer record of type 'shipping' for DR orders.  
	2011-07-11	esmart		Currency updates  
	2011-12-29	acoffel		Added technical contact lookup
	2013-08-16	esmart		Add SFDC opportunity
	2014-03-21	esmart		PO data
	2015-04-14	acoffel		added download type flag
	2017-09-15	esmart		Add partner_license_status_name
	2018-06-11	cnovac		Added order_header_token to be returned out for Wifi code.
	2019-02-22	rvinoche	Add oracle contract number to end of results

	DESCRIPTION
	Select order_header record by order_header_id
	Return result set to PHP

*/

AS
	SET NOCOUNT ON
	
	declare	@p_rc varchar(50),
			@p_ac varchar(50),
			@salesforce_opportunity_id varchar(20),
			@purchase_order_id int, 
			@purchase_order varchar(100), 
			@purchase_order_date datetime,
			@partner_license_status_name varchar(50),
			@oracle_contract_number VARCHAR(20)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1. Select
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @p_rc
	select 	@p_rc =  oc.code_value
	from order_code oc
	join order_header oh
		on oc.order_header_id = oh.order_header_id
	join vendor_order vo
		on vo.vendor_order_id = oh.vendor_order_id
	where oh.order_header_id = @order_header_id
		and code_type_id = 1 --p_rc 
	
	-- 1.2) @p_ac
	select 	@p_ac =  oc.code_value
	from order_code oc
	join order_header oh
		on oc.order_header_id = oh.order_header_id
	join vendor_order vo
		on vo.vendor_order_id = oh.vendor_order_id
	where oh.order_header_id = @order_header_id
		and code_type_id = 3 --and p_ac
	
	-- 1.3) @salesforce_opportunity_id
	select @salesforce_opportunity_id = salesforce_opportunity_id
	from order_opportunity
	where order_header_id = @order_header_id

	-- 1.4) purchase order
	select @purchase_order_id = purchase_order_id, @purchase_order = purchase_order, @purchase_order_date = purchase_order_date
	from purchase_order
	where order_header_id = @order_header_id

	--1.5) @oracle_contract_number
	select top (1) @oracle_contract_number = oracle_contract_number
	from dbo.oracle_contract_order oco
	inner join dbo.oracle_contract oc
		on oc.oracle_contract_id = oco.oracle_contract_id
	where oco.order_header_id = @order_header_id
	order by oc.oracle_contract_id desc

	-- 1.7) partner license status
	select @partner_license_status_name = (select top 1 s.partner_license_status_name
											from partner_license pl
											inner join partner_license_status s
												on s.partner_license_status_id = pl.partner_license_status_id
											where pl.order_header_id = @order_header_id
											order by pl.last_modified_date)

	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2. Results
	-------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) return results
	select 		oh.order_header_id,
			oh.vendor_order_id,
			v.vendor_id,
			v.vendor_name, 
			oh.order_offer_id,
			oh.order_offer_amount,
			oh.total_amount,
			oh.sub_total_amount,
			oh.tax_total,
			oh.payment_metho
d_id,
			pmt.payment_method_type_description,
			oh.session_id,
			oh.vendor_order_date,
			oh.locale,
			oh.exchange_rate,
			oh.site_id,
			oh.site_url,
			oh.order_status_id,
			os.order_status_description , 
			c.customer_id ,
			@p_rc as 'p_rc',
			@p_ac as 'p_ac',
			affiliate_name = 
				case 
					when a.assigned_num_str is null then @p_rc
					when a.company1 is null or a.company1 = '' then a.first_name + ' ' + a.last_name
					else a.company1
				end,
			vo.vendor_order_code,
			cu.currency_id,
			cu.currency_code,
			cu.symbol_html,
			cu.symbol_utf8,
			cu.symbol_text,
			technical_contact_customer_id = tc.customer_id,
			salesforce_opportunity_id = @salesforce_opportunity_id,
			purchase_order_id = @purchase_order_id, 
			purchase_order = @purchase_order, 
			purchase_order_date = @purchase_order_date,
			oh.download_instruction_type_id,
			partner_license_status_name = @partner_license_status_name,
			order_header_token = convert(varchar(36),oh.order_header_token),
			oracle_contract_number = @oracle_contract_number
		from order_header oh
	 	join vendor_order vo
	 		on vo.vendor_order_id = oh.vendor_order_id
	 	join vendor v
	 		on v.vendor_id = vo.vendor_id
	 	join payment_method_type pmt
	 		on pmt.payment_method_type_id = oh.payment_method_id
	 	join order_status os
	 		on os.order_status_id = oh.order_status_id
	 	join customer_order co
	 		on oh.order_header_id = co.order_header_id
	 	join customer c
	 		on co.customer_id = c.customer_id
	 	left outer join affiliates a
	 		on @p_rc = a.assigned_num_str
		left join order_currency oc
			on oh.order_header_id = oc.order_header_id
		left join currency cu
			on oc.currency_id = cu.currency_id
		left join order_technical_contact tc
			on oh.order_header_id = tc.order_header_id
	 	where oh.order_header_id = @order_header_id
		and co.customer_type_id = 1







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_header_select_by_order_code]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_order_header_select_by_order_code]

	@vendor_order_code varchar(100) = null,
	@vendor_id int = null,
	@salesforce_opportunity_id varchar(18) = null

/*	
	DATE		AUTHOR	REMARKS
	2006-08-30	tblazek		Initial creation.
	2006-09-07	esmart		Modifications to correct outdated joins
	2006-09-12	tblazek		Per ticket 5071, add vendor_id as input variable and
					use in where clause
	2006-09-28	tblazek		Per ticket to ticket 5071, ad p_ac.  Ignore passed @vendor_id and reset the variable to the correct value.
					Note: this is temporary until CSI is fixed to pass the correct vendor_id
	2006-10-27	esmart		Add case for company1 = ''. Use first and last name instead.
	2006-12-18	tblazek		Suppress customer record of type 'shipping' for DR orders.
	2011-07-11	esmart		Currency updates  
	2013-08-16	esmart		Add SFDC opportunity
	2014-03-21	esmart		PO data
	2014-11-12	esmart		@salesforce_opportunity_id search
	2015-04-09	acoffel		added download_instruction_type_id 
	2016-02-10	mrobbins	added
	2017-09-15	esmart		Add partner_license_status_name
	2018-06-11	cnovac		Added order_header_token to be returned out for Wifi code.

	DESCRIPTION
	Select order record data for the vendor_order_code passed to procedure
	Return result set to PHP
*/

AS

	SET NOCOUNT ON 

	declare	@p_rc varchar(50),
			@trx_rc varchar(50),
			@p_ac varchar(50),
			@order_header_id int,	
			@purchase_order_id int, 
			@purchase_order varchar(100), 
			@purchase_order_date datetime,
			@partner_license_status_name varchar(50)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1. Select
	------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @vendor_order_code
	if @vendor_order_code is not null
		begin
		select @order_header_id = h.order_header_id, @vendor_id = v.vendor_id
		from order_header h
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		where v.vendor_order_code = @vendor_order_code and v.vendor_id = case when @vendor_id is null then v.vendor_id else @vendor_id end
		end

	-- 1.2) @salesforce_opportunity_id
	if @salesforce_opportunity_id is not null
		begin
		-- 1.2.1) check length
			if len(@salesforce_opportunity_id) = 15
			begin
			select @salesforce_opportunity_id = dbo.fn_ConvertSalesforceID_15to18(@salesforce_opportunity_id)
			end
		-- 1.2.2) @order_header_id
			select @order_header_id = order_header_id 
			from order_opportunity
			where salesforce_opportunity_id = @salesforce_opportunity_id
		end	

	-- 1.3) @p_rc
	select 	@p_rc =  oc.code_value
	from order_code oc
	where oc.order_header_id = @order_header_id
		and oc.code_type_id = 1 --p_rc 

	-- 1.3.1) @p_rc
	select 	@trx_rc =  oc.code_value
	from order_code oc
	where oc.order_header_id = @order_header_id
		and oc.code_type_id = 4 --p_rc 
	
	-- 1.4) @p_ac
	select 	@p_ac =  oc.code_value
	from order_code oc
	where oc.order_header_id = @order_header_id
		and oc.code_type_id = 3 --and p_ac

	-- 1.5) @salesforce_opportunity_id
	if @salesforce_opportunity_id is null
		begin
		select @salesforce_opportunity_id = salesforce_opportunity_id
		from order_opportunity
		where order_header_id = @order_header_id
		end

	-- 1.6) purchase order
	select @purchase_order_id = purchase_order_id, @purchase_order = purchase_order, @purchase_order_date = purchase_order_date
	from purchase_order
	where order_header_id = @order_header_id

	-- 1.7) partner license status
	select @partner_license_status_name = (select top 1 s.partner_license_st
atus_name
											from partner_license pl
											inner join partner_license_status s
												on s.partner_license_status_id = pl.partner_license_status_id
											where pl.order_header_id = @order_header_id
											order by pl.last_modified_date)

	--select order_header_id
	--from partner_license
	--where order_header_id is not null
	--group by order_header_id having count(*) > 1
	--order by 1

	--select * from partner_license where order_header_id = 21812562

	--select * from order_header h inner join vendor_order v on v.vendor_order_id = h.vendor_order_id where h.order_header_id = 21812562 

	-------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2. Results
	-------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.0) return results
	select oh.order_header_id,
		oh.vendor_order_id,
		v.vendor_id,
		v.vendor_name, 
		oh.order_offer_id,
		oh.order_offer_amount,
		oh.total_amount,
		oh.sub_total_amount,
		oh.tax_total,
		oh.payment_method_id,
		pmt.payment_method_type_description,
		oh.session_id,
		oh.vendor_order_date,
		oh.locale,
		oh.exchange_rate,
		oh.site_id,
		oh.site_url,
		oh.order_status_id,
		os.order_status_description , 
		co.customer_id,
		@p_rc as 'p_rc', 
		@trx_rc as 'trx_rc',
		@p_ac as 'p_ac', 
		affiliate_name = 
			case 
				when a.assigned_num_str is null then @p_rc
				when a.company1 is null or a.company1 = '' then a.first_name + ' ' + a.last_name
				else a.company1
			end,
		vo.vendor_order_code,
		online_refund_flag = (select online_refund_flag = case when count(*) > 0 then 0 else 1 end
						from order_item oi
						inner join product p
							on oi.product_id = p.product_id
						where p.online_refund_flag = 0 and oi.order_header_id = oh.order_header_id),
		cu.currency_id,
		cu.currency_code,
		cu.symbol_html,
		cu.symbol_utf8,
		cu.symbol_text,
		technical_contact_customer_id = tc.customer_id,
		salesforce_opportunity_id = @salesforce_opportunity_id,
		purchase_order_id = @purchase_order_id, 
		purchase_order = @purchase_order, 
		purchase_order_date = @purchase_order_date,
		oh.download_instruction_type_id,
		partner_license_status_name = @partner_license_status_name,
		order_header_token = convert(varchar(36),oh.order_header_token)
	from order_header oh
	inner join vendor_order vo
		on vo.vendor_order_id = oh.vendor_order_id
	inner join vendor v
		on v.vendor_id = vo.vendor_id
	inner join payment_method_type pmt
		on pmt.payment_method_type_id = oh.payment_method_id
	inner join order_status os
		on os.order_status_id = oh.order_status_id
	inner join customer_order co
		on oh.order_header_id = co.order_header_id
	left join affiliates a
		on @p_rc = a.assigned_num_str
	left join order_currency oc
		on oh.order_header_id = oc.order_header_id
	left join currency cu
		on oc.currency_id = cu.currency_id
	left join order_technical_contact tc
		on oh.order_header_id = tc.order_header_id
	where oh.order_header_id = @order_header_id
		and co.customer_type_id = 1





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_header_select_item_id]
-- =============================================================================

CREATE     PROCEDURE [dbo].[usp_order_header_select_item_id]
@order_header_id int
/*	
	DATE		AUTHOR	REMARKS
	2006-08-21	tblazek		Initial creation.

	DESCRIPTION
	Return order item id result set to PHP code

INPUT:
order_header_id

Result set:
order_item_id

*/

AS
SET NOCOUNT ON
	select 	order_item_id
	from 	order_item i
	inner join product p
		on i.product_id = p.product_id
	where order_header_id = @order_header_id
	order by p.product_type_id desc, p.product_id desc

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_insert_order_extension]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_insert_order_extension]

(
	@order_header_id int,
	@order_extension_json nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2015-07-23	esmart		Initial creation.
	2015-11-13	esmart		remove NULL strings
	2018-11-15	esmart		Use openjson

	DESCRIPTION
	Insert order_extension
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @extension_key_value table (order_extension_type_name varchar(50), order_extension_value varchar(50))

	-- 1.1) parse json
	insert into @extension_key_value (order_extension_type_name, order_extension_value)
	select [Key], [Value]
	from openjson(@order_extension_json)
	where [Value] is not null
	
	insert into order_extension(order_header_id, order_extension_type_id, order_extension_value)
	select order_header_id = @order_header_id, t.order_extension_type_id, e.order_extension_value
	from @extension_key_value e
	inner join order_extension_type t
		on e.order_extension_type_name = t.order_extension_type_name

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_insert_order_license_usage]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_insert_order_license_usage]

(
	@order_header_id int,
	@license_id int, 
	@license_seats int,
	@usage_seats int, 
	@unit_price money, 
	@start_date datetime, 
	@end_date datetime,
	@license_message_id int,
	@license_attribute_license_value int,
	@license_category_id tinyint,
	@currency_id int,
	@order_license_usage_id int output
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-10-22		esmart			Initial creation
	2015-11-02		esmart			Add license_seats to order_license_usage
	2015-12-23		esmart			Add insert into oracle_update
	2017-02-09		esmart			Add order_license_usage.license_attribute_license_value and order_license_usage.license_category_id
	2021-12-09		psatish			Added the perpetual billing model id to select the Oracle template name
	DESCRIPTION
	insert order_license_usage
*/

AS
	
	set nocount on			

	declare	@oracle_template_name varchar(50),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @order_license_usage_id = null

	-- 1.1) check for duplicate usage
	select @order_license_usage_id = order_license_usage_id
	from order_license_usage 
	where order_header_id = @order_header_id and license_id = @license_id and start_date = @start_date and license_category_id = @license_category_id

	-- 1.1.1) duplicate
	if @order_license_usage_id is not null
		begin
		 --print '1.1.1) duplicate order_license_usage_id'
		 --select license_category_id = @license_category_id, order_license_usage_id = @order_license_usage_id
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) insert usage
	insert into order_license_usage(order_header_id, license_id, license_seats, usage_seats, unit_price, start_date, end_date, license_message_id, license_attribute_license_value,license_category_id,currency_id)
	values(@order_header_id, @license_id, @license_seats, @usage_seats, @unit_price, @start_date, @end_date, @license_message_id, @license_attribute_license_value,@license_category_id,@currency_id)

	select @order_license_usage_id = scope_identity()

	-- select order_license_usage_id = @order_license_usage_id

	-- 2.2) usp_oracle_insert_oracle_update
	select @oracle_template_name = case 
										when @license_attribute_license_value in(11,13)  then 'process_license_usage_overage'
										when @license_attribute_license_value = 12 then 'process_license_usage_utility'
										else null
									end

	-- 2.3) oracle_update
	if @oracle_template_name is not null
		begin
		-- 2.3.1) insert oracle update
		exec usp_oracle_insert_oracle_update @oracle_template_name=@oracle_template_name, @order_license_usage_id=@order_license_usage_id

		-- 2.3.2) set oracle_update_status_id to pending
		update order_license_usage set oracle_update_status_id = 0 where order_license_usage_id = @order_license_usage_id

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update
 account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_delete]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_item_delete]

( 
	@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2021-04-05	esmart		Initial creation.
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
	DESCRIPTION
	Delete order_item
*/

AS

	declare @order_header_id int,
			@response_code int,
			@message varchar(100)
			

begin try

	set nocount on

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check to see that more than one item exists on order
	if not exists (select ie.order_item_id from order_item i inner join order_item ie on ie.order_header_id = i.order_header_id and i.order_item_id <> ie.order_item_id where i.order_item_id = @order_item_id)
		begin
		select @response_code = -110, @message = 'only one item on order'
		select @response_code as response_code, @message as message
		return
		end
	
	-- 1.2) @order_header_id
	select @order_header_id = i.order_header_id
	from order_item i
	where i.order_item_id = @order_item_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) delete
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) order_item_audit
	insert into order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
	select order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, getdate(), sap_material_number
	from order_item 
	where order_item_id = @order_item_id

	-- 2.2) delete 
	delete from order_item_license where order_item_id in (@order_item_id)
	delete from order_item_opportunity_line_item where order_item_id in (@order_item_id)
	update license_capability_history set order_item_id = null where order_item_id in (@order_item_id)
	delete from oracle_contract_line_license where oracle_contract_line_id in (select oracle_contract_line_id  from oracle_contract_line where order_item_id = @order_item_id)
	delete from oracle_contract_line where order_item_id in (@order_item_id)
	delete from forecast_calc where forecast_core_id in (select forecast_core_id from forecast_core where order_item_id = @order_item_id)
	delete from forecast_core where order_item_id in (@order_item_id)
	delete from order_item_json where order_item_id in (@order_item_id)
	delete from license_storage_history where order_item_id in (@order_item_id)
	delete from order_item where order_item_id in (@order_item_id)
		
	-- 2.3) order_header_audit
	insert into order_header_audit (order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,mo
dified_by, fee_total,download_instruction_type_id, audit_date)
	select order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, getdate()
	from order_header
	where order_header_id = @order_header_id

	-- 2.4) order_header
	update h1
	set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount
	from order_header h1
	inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), total_amount = sum(i.item_total)
			from order_header h 
			inner join order_item i
				on i.order_header_id = h.order_header_id
			where h.order_header_id = @order_header_id
			group by h.order_header_id) x	
		on x.order_header_id = h1.order_header_id


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_license_load]
-- =============================================================================


CREATE          PROCEDURE [dbo].[usp_order_item_license_load] 
@vendor_order_id bigint,
@vendor_id int,
@order_item_load_id int,
@keycode varchar(40),
@response_code int OUTPUT,
@message varchar(100) OUTPUT,
@order_item_license_load_id int OUTPUT
			
AS
/*	DATE		AUTHOR		REMARKS
	08/19/06	TBlazek		Initial creation.
	09/21/06	TBlazek		Add logic to check for a null keycode.  The PHP code calls this procedure even when there is no keycode
					Present.  Return a 0 with a message indicating the insert is not needed.
	11/21/06	TBlazek		Change @vendor_order_id from int to bigint
	10/03/07	bjordan		Added Try/Catch

	DESCRIPTION
		Insert order_item_license_load table for order notification from 3rd party shopping cart vendor and webroot cart
*/
Begin Try
SET NOCOUNT ON
Declare @insert_date datetime,
	@insert_by varchar(50),
	@order_notification_status_id int,
	@order_load_definition_id int,
	@order_load_error_definition_id int

declare @proctrancount int
set @proctrancount = @@trancount

If @keycode = null
	BEGIN
		set @response_code = 0
		set @message = 'keycode is null, insert into order_item_license_load is not needed'
		RETURN	
	END
Select @response_code = 0
Select @insert_date = getdate()
Select @insert_by = user

Select @order_notification_status_id = order_notification_status_id 
					from order_notification_status 
					where vendor_order_id = @vendor_order_id
					and vendor_id = @vendor_id

Select @order_load_definition_id = order_load_definition_id 
						from order_load_status_definition 
						where order_load_status = 'LOADDATALICENSE'

BEGIN TRANSACTION order_load_item_license_insert 
	If not exists (Select order_item_license_load_id 
			from order_item_license_load 
			where order_item_load_id = @order_item_load_id
			and keycode = @keycode)
		BEGIN

			Insert order_item_license_load
				(order_item_load_id	,
				keycode,
				insert_date	,
				insert_by	,
				modified_date	,
				modified_by	,
				order_notification_status_id)
			Values
				(@order_item_load_id	,
				@keycode,
				@insert_date	,
				@insert_by	,
				@insert_date	,
				@insert_by	,
				@order_notification_status_id)

			Select @order_item_license_load_id = SCOPE_IDENTITY()
		END
	Else
		BEGIN
			set @response_code = -5
			set @message = 'order item license already loaded Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
			RAISERROR (@message, 11, 0)
		END


	update order_notification_status
		set order_load_definition_id = @order_load_definition_id
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id

	COMMIT TRANSACTION order_load_item_license_insert
	
	set @response_code = 0
	set @message = 'order item license record loaded successfully'

end try
begin catch
	
   if (@proctrancount + 1) = @@trancount
	      rollback transaction order_load_item_license_insert;	

	Select @order_load_error_definition_id = order_load_error_definition_id
						 From order_load_error_definition
						 Where order_load_error = 'LOADDATAORDERLISTLICENSEFAIL'

	update order_notification_status
		set order_load_error_definition_id = @order_load_error_definition_id
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id



	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	SET @response_code = -100
	Set @message = 'Error loading order_item_license_load table Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
	
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_load]
-- =============================================================================


CREATE          PROCEDURE [dbo].[usp_order_item_load] 
@vendor_order_id	bigint	,
@vendor_id int,
@line_item	int	,
@vendor_product_id	int	,
@quantity	int	,
@order_item_offer_id	varchar	(65),
@order_item_offer_amount	money	,
@list_price	money	,
@unit_price	money	,
@tax_item_total	money	,
@tax_exempt	bit	,
@product_id	int	,
@conversion_product_id int,
@product_locale char(5),
@response_code int OUTPUT,
@message varchar(100) OUTPUT,
@order_item_load_id int OUTPUT
			
AS
/*	DATE		AUTHOR		REMARKS
	07/20/06	TBlazek		Initial creation.
	11/06/06	tblazek		Change vendor_order_id from int to bigint
	10/03/07	bjordan		Added Try/Catch

	DESCRIPTION
		Insert order item load table for order notification from 3rd party shopping cart vendor and webroot cart
*/
begin try
SET NOCOUNT ON
Declare @insert_date datetime,
	@insert_by varchar(50),
	@order_notification_status_id int,
	@order_load_definition_id int,
	@order_load_error_definition_id int

declare @proctrancount int
set @proctrancount = @@trancount

Select @response_code = 0
Select @insert_date = getdate()
Select @insert_by = user
Select @order_notification_status_id = order_notification_status_id 
					from order_notification_status 
					where vendor_order_id = @vendor_order_id
					and vendor_id = @vendor_id

Select @order_load_definition_id = order_load_definition_id 
						from order_load_status_definition 
						where order_load_status = 'LOADDATAORDERITEM'

BEGIN TRANSACTION order_load_item_insert 
	If not exists (Select order_item_load_id 
			from order_item_load 
			where vendor_order_id = @vendor_order_id
			and vendor_id = @vendor_id
			and line_item = @line_item)
		BEGIN
			Insert order_item_load
				(vendor_order_id	,
				vendor_id,
				line_item	,
				vendor_product_id	,
				quantity	,
				order_item_offer_id	,
				order_item_offer_amount	,
				list_price	,
				unit_price	,
				tax_item_total	,
				tax_exempt	,
				product_id	,
				conversion_product_id,
				product_locale,
				insert_date	,
				insert_by	,
				modified_date	,
				modified_by	,
				order_notification_status_id)
			Values
				(@vendor_order_id	,
				@vendor_id,
				@line_item	,
				@vendor_product_id	,
				@quantity	,
				@order_item_offer_id	,
				@order_item_offer_amount	,
				@list_price	,
				@unit_price	,
				@tax_item_total	,
				@tax_exempt	,
				@product_id	,
				@conversion_product_id,
				@product_locale,
				@insert_date	,
				@insert_by	,
				@insert_date	,
				@insert_by	,
				@order_notification_status_id)
				
			Select @order_item_load_id = SCOPE_IDENTITY()

		END
	Else
		BEGIN
			
			set @response_code = -5
			set @message = 'order item already loaded Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
			RAISERROR (@message, 11, 0)
		END


	update order_notification_status
		set order_load_definition_id = @order_load_definition_id
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id

	COMMIT TRANSACTION order_load_item_insert
	set @response_code = 0
	set @message = 'order item record loaded successfully'

end try

begin catch
	
   if (@proctrancount + 1) = @@trancount 
	     ROLLBACK TRANSACTION order_load_item_insert;	


	Select @order_load_error_definition_id = order_load_error_definition_id
												 From order_load_error_definition
												 Where order_load_error = 'LOADDATAORDERLISTFAIL'

	update order_notification_status
		set order_load_error_definition_id = @order_load_error_definition_id
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id


	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	SET @response_
code = -100
	Set @message = 'Error loading order_item_load table Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
	
	
end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_select_item]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_item_select_item]

(
	@order_item_id int
)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-21	tblazek		Initial creation.
	2006-09-14	tblazek		Change column name tax_item_total to item_total
	2012-02-08	esmart		Add currency support

	DESCRIPTION
	Return order item data result set to PHP code
*/

AS
SET NOCOUNT ON
	select i.order_item_id,
			i.order_header_id,
			i.line_item,
			i.product_id,
			i.quantity,
			i.list_price,
			i.unit_price,
			i.order_item_offer_id,
			i.order_item_offer_amount,
			i.tax,
			i.item_total,
			i.tax_exempt,
			i.effective_date,
			i.order_item_status_id,
			cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
	from order_item i
	left join order_currency oc
		on i.order_header_id = oc.order_header_id
	left join currency cu
		on oc.currency_id = cu.currency_id
	where i.order_item_id = @order_item_id
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_select_keycodes]
-- =============================================================================


CREATE       PROCEDURE [dbo].[usp_order_item_select_keycodes]

(
	@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2006-08-29	tblazek		Initial creation.
	2013-02-12	esmart		Add alias keycode as output if exists

	DESCRIPTION
	Return keycode data result set to PHP code

INPUT:
order_item_id

Result set:
keycode
*/

AS

	SET NOCOUNT ON

	select keycode = case when a.keycode_alias is not null then a.keycode_alias	else l.keycode end
	from license l with (nolock)
	join order_item_license oil with (nolock)
		on oil.license_id = l.license_id
	join order_item oi with (nolock)
		on oi.order_item_id = oil.order_item_id
	left join license_keycode_alias a with (nolock)
		on l.license_id = a.license_id
	where oil.order_item_id = @order_item_id






GO
