CREATE PROCEDURE [dbo].[usp_order_item_select_redepemption]

(
	@order_item_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-11-07	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select ir.order_item_id, rc.redemption_code, r.redemption_name, v.redemption_vendor_name
	from order_item_redemption ir
	inner join redemption_code rc
		on ir.redemption_code_id = rc.redemption_code_id
	inner join redemption r
		on ir.redemption_id = r.redemption_id
	inner join redemption_vendor v
		on r.redemption_vendor_id = v.redemption_vendor_id
	where ir.order_item_id = @order_item_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
