-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_update_item_details]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_item_update_item_details]

( 
	@order_header_id int,
	@item_json nvarchar(max),
	@modified_by varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2021-04-05	esmart		Initial creation.
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit


	DESCRIPTION
	Update order item details (effective_date, capability_expiration_date, quantity, retail_price)
*/

AS

	declare @modified_date datetime,
			@response_code int,
			@message varchar(100)
			

begin try

	set nocount on

	declare @order_item table (order_item_id int, quantity int, unit_price money, effective_date datetime, capability_expiration_date datetime)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @modified_by is null begin select @modified_by = suser_sname() end
	select @modified_date = getdate()

	-- 1.1) parse json into @order_item
	insert into @order_item(order_item_id,quantity,unit_price,effective_date,capability_expiration_date)
	select order_item_id,quantity,unit_price,effective_date,capability_expiration_date
	from openjson(@item_json)
	with (order_item_id int '$.order_item_id',
		quantity int '$.quantity',
		unit_price money '$.unit_price',
		effective_date datetime '$.effective_date',
		capability_expiration_date datetime '$.capability_expiration_date')

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) order_item

		-- 2.1.1)
		insert into order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
		select oi.order_item_id, oi.order_header_id, oi.line_item, oi.product_id, oi.quantity, oi.list_price, oi.unit_price, oi.tax, oi.order_item_offer_id, oi.order_item_offer_amount, oi.item_total, oi.tax_exempt, oi.effective_date, oi.order_item_status_id, oi.insert_date, oi.insert_by, oi.modified_date, oi.modified_by, oi.capability_expiration_date, oi.item_bundle_id, oi.order_item_update_type_id, @modified_date, oi.sap_material_number
		from @order_item i
		inner join order_item oi 
			on oi.order_item_id = i.order_item_id
		where i.quantity <> oi.quantity or i.unit_price <> oi.unit_price or i.effective_date <> oi.effective_date or i.capability_expiration_date <> oi.capability_expiration_date

		-- 2.1.2) order_item
		update oi
		set oi.quantity = i.quantity,
			oi.unit_price = i.unit_price,
			oi.effective_date = i.effective_date,
			oi.capability_expiration_date = i.capability_expiration_date,
			oi.item_total = i.quantity * i.unit_price,
			modified_date = @modified_date, 
			modified_by = @modified_by
		from @order_item i
		inner join order_item oi 
			on oi.order_item_id = i.order_item_id
		where i.quantity <> oi.quantity or i.unit_price <> oi.unit_price or i.effective_date <> oi.effective_date or i.capability_expiration_date <> oi.capability_expiration_date

	-- 2.2) order_header

		-- 
2.2.1) order_header_audit
		insert into order_header_audit (order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, audit_date)
		select order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, getdate()
		from order_header
		where order_header_id = @order_header_id

		-- 2.2.2) order_header
		update h1
		set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount
		from order_header h1
		inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), total_amount = sum(i.item_total)
				from order_header h 
				inner join order_item i
					on i.order_header_id = h.order_header_id
				where h.order_header_id = @order_header_id
				group by h.order_header_id) x	
			on x.order_header_id = h1.order_header_id

	-- 2.3) partner pricing
	if exists (select partner_id from partner_order where order_header_id = @order_header_id)
		begin
			exec usp_partner_update_order_pricing @order_header_id = @order_header_id
		end



end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_item_update_price]
-- =============================================================================

CREATE procedure [dbo].[usp_order_item_update_price]

	@item_json nvarchar(max),
	@response_code int output,
	@message varchar(100) output

/*	
	DATE		AUTHOR		REMARKS
	2020-12-2	wbarton		Initial creation
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
	DESCRIPTION
	Updates pricing on order_item and order_header for a given array including order_item_id and unit_price. Expected JSON schema for @item_json (single or multiple items):
	[{"order_item_id":int,"unit_price":money},{"order_item_id":int,"unit_price":money}]

*/
as
set nocount on
begin try

	declare @json_table table (id int identity(1,1), [key] int, [value] nvarchar(max))
	declare @item_table table (order_item_id int, unit_price money)
	declare @header_table table (id int identity(1,1), order_header_id int)
	declare @audit_date datetime = getdate(), @modified_by varchar(50) = 'usp_order_item_update_price', @loop_value int, @loop_max int, @json_record nvarchar(max), @order_header_id int

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Parse the @item_json into @item_table
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into @json_table([key], value)
	select [key], [value]
	from openjson(@item_json)

	select @loop_value = (select min(id) from @json_table), @loop_max = (select max(id) from @json_table)

	while @loop_value <= @loop_max
		begin
			select @json_record = [value] 
			from @json_table
			where id = @loop_value

			insert into @item_table(order_item_id, unit_price)
			select j.order_item_id, j.unit_price
			from openjson(@json_record)
			with (
				order_item_id int '$.order_item_id',
				unit_price money '$.unit_price'			
			) j

			select @json_record = null, @loop_value = @loop_value + 1
		end


	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Select order_header_id, single or multiple, from the item data
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into @header_table(order_header_id)
	select distinct oi.order_header_id
	from order_item oi
		inner join @item_table it
			on it.order_item_id = oi.order_item_id

	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Validate that all orders included in the request are paid for by either PurchaseOrder or PhysicalCheck
	--For other payment methods, we are not allowing order data to be updated through this process
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if exists (
		select 1
		from @header_table h
			inner join order_payment_header oph
				on oph.order_header_id = h.order_header_id
			inner join payment_header ph
				on ph.payment_header_id = oph.payment_header_id
		where ph.payment_method_id not in (4,5)
	)
		begin
			select @response_code = -1, @message = 'Pricing cannot be updated due to the payment method used'
			return
		end

	------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------
	--Update order_item
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price,tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
	select oi.order_item_id, oi.order_header_id, oi.line_item, oi.product_id, oi.quantity, oi.list_price, oi.unit_price,tax, oi.order_item_offer_id, oi.order_item_offer_amount, oi.item_total, oi.tax_exempt, oi.effective_date, oi.order_item_status_id, oi.insert_date, oi.insert_by, oi.modified_date, oi.modified_by, oi.capability_expiration_date, oi.item_bundle_id, oi.order_item_update_type_id, @audit_date, oi.sap_material_number
	from order_item oi
		inner join @item_table it
			on it.order_item_id = oi.order_item_id

	update oi
	set oi.item_total = oi.quantity * it.unit_price, oi.unit_price = it.unit_price, oi.modified_date = @audit_date, oi.modified_by = @modified_by
	from order_item oi
		inner join @item_table it
			on it.order_item_id = oi.order_item_id

 	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Update order_header - doing this via a loop in case the items passed in the item_json relate to separate/multiple orders
	---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @loop_value = (select min(id) from @header_table), @loop_max = (select max(id) from @header_table)
	while @loop_value <= @loop_max
		begin
			select @order_header_id = order_header_id 
			from @header_table
			where id = @loop_value

			insert into order_header_audit (order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, fee_total, download_instruction_type_id, audit_date)
			select order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, @audit_date
			from order_header
			where order_header_id = @order_header_id

			update h1
			set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount, h1.modified_date = @audit_date, h1.modified_by = @modified_by
			from order_header h1
			inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), total_amount = sum(i.item_total)
					from order_header h 
					inner join order_item i
						on i.order_header_id = h.order_header_id
					where h.order_header_id = @order_header_id
					group by h.order_header_id) x
				on x.order_header_id = h1.order_header_id

			select @order_header_id = null, @loop_value = @loop_value + 1
		end

	select @response_code = 0, @message = 'Pricing updated successfully'

end try
begin catch

	declare @DBName nvarchar(128)
	select @response_code = -1, @message = 'Pricing update failed', @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_license_opportunity_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_license_opportunity_update]

(
	@order_header_id int,
	@disable_wrong_key bit,
	@move_billing_attributes bit,
	@keycode varchar(40),
	@correct_keycode varchar(40)
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2018-01-29		acoffel		Initial creation.
	2018-11-27		rvinoche	change json schema for license_service
	2019-01-10		rvinoche	Support autobilling attributes living only in license_effective_object
	2019-05-13		abelenkiy	Added support for license_usage_pricing in effective object
	2019-09-30		cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
		

	DESCRIPTION
	attribute order and opportunity to correct license
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100),
			@license_id int,
			@license_service_json nvarchar(max),
			@license_service_type_name varchar(50) = 'license_disable',
			@correct_license_id int,
			@effective_date date = getdate(),
			@effective_json varchar(max)
	declare @original_keycode_table table (license_id int, keycode varchar(40), license_category_id tinyint, order_item_id int)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  get license detail 
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) license_id on wrong keycode
		insert into @original_keycode_table (license_id, keycode, license_category_id, order_item_id)
		select l.license_id, l.keycode, plc.license_category_id, oi.order_item_id
		from order_item oi
		inner join order_item_license oil on oil.order_item_id = oi.order_item_id
		inner join license l on l.license_id = oil.license_id
		inner join product_license_category plc on plc.product_id = oi.product_id
		where oi.order_item_status_id = 1
		and l.keycode = @keycode
		and oi.order_header_id = @order_header_id

		-- 1.2) license_id on correct keycode
		select @correct_license_id = license_id from license where keycode = @correct_keycode

		select @license_id = license_id from license where keycode = @keycode

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  set values for order and reload opp 
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--2.1) oracle contract clean up write audit record
		insert into oracle_contract_line_license_audit (oracle_contract_line_license_id,oracle_contract_line_id,license_id, insert_date)
		select l.oracle_contract_line_license_id,l.oracle_contract_line_id,l.license_id, l.insert_date
		from oracle_contract_line_license l
		inner join oracle_contract_line cl on cl.oracle_contract_line_id = l.oracle_contract_line_id
		inner join @original_keycode_table okt on okt.license_id = l.license_id and okt.order_item_id = cl.order_item_id

		--2.2) oracle contract clean up attribute to the correct license
		update l
		set license_id = @correct_license_id
		from oracle_contract_line_license l
		inner join oracle_contract_line cl on cl.oracle_contract_line_id = l.oracle_contract_line_id
		inner join @original_keycode_table okt on okt.license_id = l.license_id and okt.order_item_id = cl.order_item_id

		--2.3) history clean up atttribute to co
rrect license
		update lch
		set lch.order_item_id = null
		from license_capability_history lch
		inner join @original_keycode_table okt on okt.license_id = lch.license_id and okt.order_item_id = lch.order_item_id

		update lsh
		set lsh.order_item_id = null
		from license_seat_history lsh
		inner join @original_keycode_table okt on okt.license_id = lsh.license_id and okt.order_item_id = lsh.order_item_id

		update lclh
		set lclh.order_item_id = null
		from license_category_license_history lclh
		inner join @original_keycode_table okt on okt.license_id = lclh.license_id and okt.order_item_id = lclh.order_item_id

		--2.4) order_item_license clean up attribute to correct license
		update oil
		set oil.license_id = @correct_license_id
		from order_item_license oil
		inner join @original_keycode_table okt on okt.license_id = oil.license_id and okt.order_item_id = oil.order_item_id

		--2.5) reprocess order on correct license
		exec usp_cart_update_order_license @order_header_id, 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.)  attribute billing info to correct license 
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		if @move_billing_attributes = 1
			begin 
				--3.1) order_license_usage
				update order_license_usage 
				set license_id = @correct_license_id
				where license_id = @license_id 
				and order_header_id = @order_header_id

				--3.2) update AR record license_attribute_license
				select @effective_json = (
										select	@correct_license_id as license_id
												, flseot.license_category_id
												, flseot.effective_value as license_attribute_license_value
												, @effective_date as effective_start_date
												, okt.order_item_id
										from dbo.fn_license_select_effective_object_element_history(@license_id, 'license_attribute_license_value', default) flseot
										inner join @original_keycode_table okt on okt.license_category_id = flseot.license_category_id
										where okt.license_id = flseot.license_id
										and (flseot.effective_end_date >= @effective_date or flseot.effective_end_date is null)
										for json path)

				if @effective_json is not null
					exec dbo.usp_license_insert_effective_object @license_effective_object_json = @effective_json, @license_effective_source_caller = 'usp_order_license_opportunity_update'

				set @effective_json = null
				select @effective_json = (
										select okt.license_id
												, okt.license_category_id
												, 20 as license_attribute_license_value
												, @effective_date as effective_start_date
												, okt.order_item_id
										from @original_keycode_table okt
										for json path)

				if @effective_json is not null
					exec dbo.usp_license_insert_effective_object @license_effective_object_json = @effective_json, @license_effective_source_caller = 'usp_order_license_opportunity_update'

				set @effective_json = null
				select @effective_json = (
										select @correct_license_id as license_id
												, flseot.license_category_id
												, flseot.effective_value as billing_day_of_month
												, @effective_date as effective_start_date
												, okt.order_item_id
										from dbo.fn_license_select_effective_object_element_history(@license_id, 'billing_day_of_month', default) flseot
										inner join @original_keycode_table okt on okt.license_category_id = flseot.license_category_id								
										where okt.license_id = flseot.license_id
										and (flseot.effective_end_date >= @effective_date or flseot.effective_end_date is null)
										for json path)

				if @effective_json
 is not null
					exec dbo.usp_license_insert_effective_object @license_effective_object_json = @effective_json, @license_effective_source_caller = 'usp_order_license_opportunity_update'

				set @effective_json = null
				select @effective_json = (
										select @correct_license_id as license_id
												, flseot.license_category_id
												, flseot.effective_value as license_usage_pricing_value
												, flseot.effective_start_date
												, okt.order_item_id
											from dbo.fn_license_select_effective_object_element_history(@license_id, 'license_usage_pricing_value', default) flseot
										inner join @original_keycode_table okt on okt.license_category_id = flseot.license_category_id								
										where okt.license_id = flseot.license_id
										and (flseot.effective_end_date >= @effective_date or flseot.effective_end_date is null)
										for json path)

				if @effective_json is not null
					exec dbo.usp_license_insert_effective_object @license_effective_object_json = @effective_json, @license_effective_source_caller = 'usp_order_license_opportunity_update'

				--3.5) update message queue record license_message
				update license_message
				set license_id = @correct_license_id
				where license_id = @license_id
				and message_status_id = 1
				and message_type_id = 10

			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.)  disable license
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			
			if @disable_wrong_key = 1 
			begin 
				--4.0) Disable routine				
				select @license_service_json = (select @keycode as keycode, @license_service_type_name as account_name,
													(select lc.license_category_name
													from @original_keycode_table okt
													inner join dbo.license_category lc on lc.license_category_id = okt.license_category_id for json path) license_category for json path, without_array_wrapper)

				exec usp_license_service_insert_service @license_service_type_name, @license_service_json
			end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_load]
-- =============================================================================


CREATE            PROCEDURE [dbo].[usp_order_load] 
@vendor_order_id	bigint	,
@vendor_id	int	,
@vendor_order_code varchar(100),
@order_type	varchar	(30)	,
@site_id	varchar	(65)	,
@site_url	varchar	(1025)	,
@p_rc	varchar	(50)	,
@p_rsc	varchar	(50)	,
@p_ac	varchar	(100)	,
@trx_rc	varchar	(50)	,
@trx_rsc	varchar	(50)	,
@trx_ac	varchar	(100)	,
@aid	varchar	(50)	,
@pid	varchar	(50)	,
@sid	varchar	(100)	,
@offer_id	varchar	(65)	,
@offer_amount	money	,
@total_amount	money	,
@sub_total_amount	money	,
@tax_amount	money	,
@payment_method varchar(255),
@exchange_rate	money	,
@session_id	bigint	,
@submission_date	datetime	,
@sales_order_date	datetime	,
@locale	char	(5)	,
@where_heard	varchar	(64)	,
@test_order	bit	,
@response_code int OUTPUT,
@message varchar(100) OUTPUT,
@order_load_id int OUTPUT
			
AS
/*	DATE		AUTHOR		REMARKS
	07/20/06	TBlazek		Initial creation.
	11/06/06	tblazek		Change vendor_order_id from int to bigint
	10/03/07	bjordan		Added Try/Catch

	DESCRIPTION
		Insert order load table for order notification from 3rd party shopping cart vendor and webroot cart
*/
begin try
SET NOCOUNT ON
Declare @insert_date datetime,
	@insert_by varchar(50),
	@order_notification_status_id int,
	@order_load_definition_id int,
	@order_load_error_definition_id int

declare @proctrancount int
set @proctrancount = @@trancount

Select @response_code = 0
Select @insert_date = getdate()
Select @insert_by = user
Select @order_notification_status_id = order_notification_status_id 
					from order_notification_status 
					where vendor_order_id = @vendor_order_id
					and vendor_id = @vendor_id

Select @order_load_definition_id = order_load_definition_id
						from order_load_status_definition 
						where order_load_status = 'LOADDATAORDER'

BEGIN TRANSACTION order_load_insert 
	If not exists (Select order_load_id 
			from order_load 
			where vendor_order_id = @vendor_order_id
			and vendor_id = @vendor_id)
		BEGIN
			Insert order_load
				(vendor_order_id	,
				vendor_id	,
				vendor_order_code,
				order_type	,
				site_id	,
				site_url	,
				p_rc	,
				p_rsc	,
				p_ac	,
				trx_rc	,
				trx_rsc	,
				trx_ac	,
				aid	,
				pid	,
				sid	,
				offer_id	,
				offer_amount	,
				total_amount	,
				sub_total_amount	,
				tax_amount	,
				payment_method,
				exchange_rate	,
				session_id	,
				submission_date	,
				sales_order_date	,
				locale	,
				where_heard	,
				test_order,
				insert_date	,
				insert_by	,
				modified_date	,
				modified_by	,
				order_notification_status_id)
			Values
				(@vendor_order_id,
				@vendor_id,
				@vendor_order_code,
				@order_type,
				@site_id,
				@site_url,
				@p_rc,
				@p_rsc,
				@p_ac,
				@trx_rc,
				@trx_rsc,
				@trx_ac,
				@aid,
				@pid,
				@sid,
				@offer_id,
				@offer_amount,
				@total_amount,
				@sub_total_amount,
				@tax_amount,
				@payment_method,
				@exchange_rate,
				@session_id,
				@submission_date,
				@sales_order_date,
				@locale,
				@where_heard,
				@test_order,
				@insert_date	,
				@insert_by	,
				@insert_date	,
				@insert_by	,
				@order_notification_status_id)

			Select @order_load_id = SCOPE_IDENTITY()

		END
	Else
		BEGIN
			
			set @response_code = -5
			set @message = 'order already loaded Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
			RAISERROR (@message, 11, 0)
		END


	update order_notification_status
		set order_load_definition_id = @order_load_definition_id
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id

	COMMIT TRANSACTION order_load_insert
	set @response_code = 0
	set @message = 'order record loaded successfully'
	





end try
begin catch
	
   if (@proctrancount + 1) = @@trancount
	      ROLLBACK TRANSACTION order_load_insert;	


	Select @order_load_error_definition_id = order_load_error_definition_id
	 From order_load_error_definition
	 Where order_load_error = 'LOADDATAORDERFAIL'

	update order_notification_status
	set order_load_error_definition_id = @order_load_error_definition_id
	where vendor_order_id = @vendor_order_id
	and vendor_id = @vendor_id
	


	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	SET @response_code = -100
	Set @message = 'Error loading order_load table Vendor_order_id - ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ''
	
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_load_external_order]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_load_external_order]


(
	@order_header_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2019-05-01	esmart		Initial creation.

	DESCRIPTION
	load external order
*/

AS

set nocount on				

begin try

		declare	@min_order_date datetime, 
				@site_id varchar(65),
				@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get min order date
		select @min_order_date = datefromparts(datepart(yyyy,getdate()),datepart(mm,getdate()),1)

		-- 1.2) @site_id
		select @site_id = site_id from order_header where order_header_id = @order_header_id


		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2) update
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------	

		-- 2.1) add order_extenstions
		insert into order_extension (order_header_id, order_extension_type_id, order_extension_value)
		select @order_header_id, f.order_extension_type_id, f.order_extension_value
		from dbo.fn_order_select_default_order_extension(@site_id,300,11,null) f
		left join order_extension e
			on f.order_extension_type_id = e.order_extension_type_id and e.order_header_id = @order_header_id
		where e.order_extension_id is null

		-- 2.2) update vendor_order_date
		if (select h.vendor_order_date from order_header h where h.order_header_id = @order_header_id) < @min_order_date
			begin
				select 'update vendor_order_date'
		
				insert into order_header_audit (order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, fee_total, download_instruction_type_id, audit_date)
				select order_header_id, vendor_order_id, order_offer_id, order_offer_amount, total_amount, sub_total_amount, tax_total, payment_method_id, session_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id, insert_date, insert_by, modified_date, modified_by, fee_total, download_instruction_type_id, getdate()
				from order_header h
				where h.order_header_id = @order_header_id

				update h
				set h.vendor_order_date = convert(date,getdate()), h.modified_date = getdate(), h.modified_by = 'esmart'
				from order_header h
				where h.order_header_id = @order_header_id
			end

		-- 2.3) check for previous or active load
		if (select count(*) from sfdc_opportunity_update_archive where order_header_id = @order_header_id and sfdc_template_id = 17 and sfdc_update_type_id = 115 and sfdc_response_code = 'success') > 0
			or (select count(*) from sfdc_opportunity_update where order_header_id = @order_header_id and sfdc_template_id = 17 and sfdc_update_type_id = 115) > 0
			begin
			select 'order update already completed'
			return
			end

		-- 2.4) insert sfdc_opportunity_update
		insert into sfdc_opportunity_update (order_header_id, sfdc_template_id, sfdc_update_type_id,process_date) 
		select @order_header_id, 17, 115, getdate()

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'load failed'
						else @message end

	declare @DB
Name nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_load_external_order_batch_obsolete]
-- =============================================================================

CREATE     PROCEDURE [dbo].[usp_order_load_external_order_batch_obsolete]

(
	@start_date DATETIME = NULL
)

/*	
	DATE			AUTHOR			REMARKS
	2022-05-18		abelenkiy		Initial creation
	2022-06-01		abelenkiy		Added section 1.3.1 to remove records from processing if pending service exists on company
	2022-09-29		abelenkiy		Added Step 3 and Step 4 from production external_order_batch_load job.
	2022-10-07		gblandford		Update call from usp_order_select_external_orders_legacy to new procedure usp_order_select_external_orders
									which has been refactored without processing code
									- part of refactor for ALM-3008	
	2023-08-07		gblandford		https://jira.opentext.com/browse/ECOM-1760 - Marked as obsolete. Code moved/merged to dbo.usp_process_external_orders


	DESCRIPTION
	Create to abstract logic from job [external_order_batch_load] into procedure. The job info and schedule (every 5 minutes) 
	will remain in place except procedure will be called instead of having code in job step text. The original job description 
	below: 
	
		This job will gather all online business orders that have yet to be interfaced into oracle. It will run a match on 
		company and if successful will update order data and add it to the sfdc queue.

	Other than a cursory cleanup and basic annotation of the code, no business logic is changed in the initial creation 
	of this procedure. It's not entirely clear what is supposed to be happening and whether it's compatible with the 
	future-state SAP integration, so further revision will be required.

	The procedure sections retain the original Step 1 and Step 2 sections of the job despite the ambiguous naming of those 
	sections. This separation may or may not prove to be meaningful as we discover what this code is supposed to do.

	Step 3 and Step 4 are proprietary to Kaseya and test orders.

*/

as

begin try

	set nocount on

	declare @sfdc_template_id tinyint
		, @sfdc_update_type_id tinyint
		, @cybs_subscription_id int
		, @site_id varchar(65)
		, @product_line_id int
		, @license_attribute_license_value int
		, @order_header_id int
		, @company_id int
		, @company_type_id tinyint
		, @temp_id int
		, @total_ids int
		, @modified_date datetime = getdate()

	declare @orders table (temp_id int identity(1,1), order_header_id int, company_id int, company_name nvarchar(255), 
		company_type_id tinyint, site_id varchar(20), order_item_id int, effective_date datetime, license_category_id int, 
		license_attribute_license_value int)

	declare @order_company table (order_external_load_exception_id int, order_header_id int, company_id int, 
		order_company_type_id tinyint, customer_id int)

	-- 1) "Step 1"

	-- 1.1) all references to the SFDC queue use sfdc_template 'external_order' and sfdc_update_type 'create_contract'
	select @sfdc_template_id = st.sfdc_template_id 
	from sfdc_template st 
	where st.sfdc_template_name = 'external_order'

	select @sfdc_update_type_id = sut.sfdc_update_type_id 
	from sfdc_update_type sut 
	where sut.sfdc_update_type_name = 'create_contract'

	-- 1.2) insert failed orders into external order exception in a pending state
	--		these will be excluded from the order list in section 1.3 and then handled in section 2

	insert into order_external_load_exception (order_header_id, exception_status, insert_date)
	select distinct a.order_header_id, 'pending', getdate()
	from sfdc_opportunity_update_archive a
		inner join order_header h
			on a.order_header_id = h.order_header_id 
				and h.order_status_id = 1 -- Transaction
		left join sfdc_opportunity_update_archive a2 -- excluding orders with update already successful
			on a.order_header_id = a2.order_header_id 
				and a.sfdc
_template_id = @sfdc_template_id
				and a.sfdc_update_type_id = @sfdc_update_type_id 
				and a2.sfdc_response_code = 'Success'
		left join sfdc_opportunity_update u -- excluding orders with updates not yet processed
			on a.order_header_id = u.order_header_id
		left join order_external_load_exception e -- excluding orders that already have pending order_external_load_exception
			on a.order_header_id = e.order_header_id 
				and e.exception_status = 'pending'
		where a.sfdc_template_id = @sfdc_template_id 
			and a.sfdc_update_type_id = @sfdc_update_type_id 
			and a.sfdc_response_code <> 'Success' 
			and a2.sfdc_opportunity_update_archive_id is null 
			and e.order_external_load_exception_id is null 
			and u.order_header_id is null
	order by a.order_header_id desc

	-- 1.3) procedure will get all orders from previous month if no value is passed in
	--		this is consistent with how the job was executed before
	if @start_date is null 
		begin
			select @start_date = dateadd(month, -1, getdate())
		end

	insert into @orders(order_header_id, company_id, company_name, company_type_id, site_id, order_item_id, effective_date
		, license_category_id)
	select distinct co.order_header_id, cp.company_id, cp.company_name, cp.company_type_id, h.site_id, i.order_item_id
		, i.effective_date, plc.license_category_id
	from customer_order co
		inner join order_company oc
			on co.order_header_id = oc.order_header_id 
				and oc.order_company_type_id = 2
		inner join company cp
			on oc.company_id = cp.company_id
		inner join order_header h
			on co.order_header_id = h.order_header_id
		inner join order_item i
			on co.order_header_id = i.order_header_id
		inner join product_license_category plc
			on i.product_id = plc.product_id
		inner join product p
			on i.product_id = p.product_id
		inner join order_payment_header op
			on h.order_header_id = op.order_header_id
		inner join payment_header ph
			on op.payment_header_id = ph.payment_header_id
		inner join payment_merchant m 
			on ph.payment_merchant_id = m.payment_merchant_id
		left join sfdc_opportunity_update_archive a with (nolock) -- excluding successful 'create contract' sfdc updates for order
			on a.order_header_id = h.order_header_id 
				and a.sfdc_response_code <> 'Failure' 
				and a.sfdc_update_type_id = @sfdc_update_type_id
		left join sfdc_opportunity_update su with (nolock) -- excluding all orders with pending sfdc update
			on su.order_header_id = h.order_header_id
		left join order_external_load_exception le -- excluding external order exceptions created in section 1.2
			on co.order_header_id = le.order_header_id 
				and le.exception_status = 'pending'
		left join partner_license pl -- excluding unapproved partner license records
			on co.order_header_id = pl.order_header_id 
				and pl.partner_license_status_id <> 2 -- approved
	where co.customer_type_id = 1 -- Billing
		and p.product_family_id in (55,300) -- business
		and h.order_status_id = 1 -- Transaction
		and h.site_id in ('WRCART','CSI','AUTORENEWAL')
		and h.insert_date >= @start_date
		and m.merchant_id <> 'cleverbridge'
		and a.sfdc_opportunity_update_archive_id is null 
		and su.sfdc_opportunity_update_id is null
		and le.order_external_load_exception_id is null
		and pl.partner_license_id is null
	order by co.order_header_id

	-- 1.3.1) remove records from table above with pending customer_service records
	delete o
	from customer_service cs 
		inner join customer_service_json csj			
			on cs.customer_service_id = csj.customer_service_id
		inner join customer_service_status css
			on css.customer_service_status_id = cs.customer_service_status_id
				and css.customer_service_status_name = 'pending'
		inner join @orders o 
			on json_value(csj.customer_service_json, '$.company_id') = o.company_id

	-- 1.4) set license_attribute_license_value for each order
	update o
	set o.license_attribute_license_value = av.license_attrib
ute_license_value
	from @orders o
		inner join order_item_license il
			on o.order_item_id = il.order_item_id
		inner join license l
			on il.license_id = l.license_id
		cross apply fn_license_select_effective_object_table(il.license_id, o.effective_date) eo
		inner join license_attribute_license_value av
			on eo.effective_value = av.license_attribute_license_value
	where il.license_id = eo.license_id 
		and eo.license_category_id = o.license_category_id 
		and eo.effective_object_id = 2 --license_attribute_license_value

	-- 1.5) process batch, whatever that means
	--		I left the original debug code in place in case it's useful in the future

	-- 1.5.1) set initial loop variables and begin loop
	select @temp_id = 1, @total_ids = max(temp_id) from @orders

	while @total_ids >= @temp_id
		begin
		
			-- 1.5.2) select parameters
			select @order_header_id = order_header_id, @site_id = site_id, @company_type_id = company_type_id
				, @product_line_id = 300, @license_attribute_license_value = license_attribute_license_value
				, @company_id = company_id
			from @orders where temp_id = @temp_id

			print @temp_id 
			print @order_header_id
			print 'no exception, load order'
	
			-- 1.5.3) insert order_extension where one doesn't already exist for order and extension type
			insert into order_extension (order_header_id, order_extension_type_id, order_extension_value)
			select @order_header_id, f.order_extension_type_id, f.order_extension_value
			from dbo.fn_order_select_default_order_extension(@site_id,@product_line_id,@company_type_id
				, @license_attribute_license_value) f
			left join order_extension e
				on f.order_extension_type_id = e.order_extension_type_id 
					and e.order_header_id = @order_header_id
			where e.order_extension_id is null
	
			-- 1.5.4) insert cybs_subscription records
			--			this may need to be changed for paymentech compatibility

			-- 1.5.4.1) select existing cybs_subscription subscription record
			select @cybs_subscription_id = s.cybs_subscription_id
				from order_payment_header op
				inner join payment_header h
					on op.payment_header_id = h.payment_header_id
				inner join payment_subscription_credit_card cc
					on op.payment_header_id = cc.payment_header_id
				inner join payment_account pa
					on h.payment_header_id = pa.payment_header_id
				inner join cybs_subscription s
					on cc.credit_card_subscription_id = s.credit_card_subscription_id
			where op.order_header_id = @order_header_id

			-- 1.5.4.2) attempt to insert new record if one doesn't exist
			if @@rowcount = 0
				begin
					insert into cybs_subscription (credit_card_subscription_id, payment_merchant_id, insert_date, account_number
						, expiration_month, expiration_year, card_type_id)
					select cc.credit_card_subscription_id, h.payment_merchant_id, getdate(), right(pa.account_number,4)
						, pa.expiration_month, pa.expiration_year, pa.card_type_id
					from order_payment_header op
						inner join payment_header h
							on op.payment_header_id = h.payment_header_id
						inner join payment_subscription_credit_card cc
							on op.payment_header_id = cc.payment_header_id
						inner join payment_account pa
							on h.payment_header_id = pa.payment_header_id
						left join cybs_subscription s
							on cc.credit_card_subscription_id = s.credit_card_subscription_id
					where op.order_header_id = @order_header_id 
						and s.cybs_subscription_id is null

					select @cybs_subscription_id = scope_identity()
				end

			-- 1.5.4.3) insert cybs_subscription_customer record if cybs_subscription exists but customer does not
			if @cybs_subscription_id is not null
				begin
					insert into cybs_subscription_customer (cybs_subscription_id, customer_id, company_id, insert_date)
					select @cybs_subscription_id, oc.customer_id, oc.company_id, getdate()
					from order_company oc
						left join cybs_subscription_customer cs
							
on oc.company_id = cs.company_id 
								and oc.customer_id = cs.customer_id 
								and cs.cybs_subscription_id = @cybs_subscription_id
					where oc.order_company_type_id = 2 -- bill_to_account
						and oc.order_header_id = @order_header_id 
						and cs.cybs_subscription_customer_id is null
				end
				
			-- 1.5.5) insert into sfdc queue if criteria are met
			--			this logic is pretty wonky and already seems to exist in section 1.3 but I'm leaving it alone at this stage
			if (select count(*) 
				from sfdc_opportunity_update_archive 
				where order_header_id = @order_header_id 
					and sfdc_template_id = @sfdc_template_id
					and sfdc_update_type_id = @sfdc_update_type_id
					and sfdc_response_code = 'success') = 0
					-- this criteria should already be met by logic in section 1.3
				and (select count(*) 
					from sfdc_opportunity_update 
					where order_header_id = @order_header_id 
						and sfdc_template_id = @sfdc_template_id 
						and sfdc_update_type_id = @sfdc_update_type_id) = 0
					-- this criteria should also already be met by logic in section 1.3
				and (select count(*) 
					from order_company 
					where order_header_id = @order_header_id) > 0
					-- this criteria should already be met by inner join to order_company in section 1.3
				and (select count(*) 
					from sap_account 
					where company_id = @company_id) > 0
					-- this basically means there is a record of the company in sap_account
					-- this isn't yet met in section 1.3 but it could be added with an inner join
					-- the only reason we *would not* do that is if there are cases of external orders without sap companies
				begin
					insert into sfdc_opportunity_update (order_header_id, sfdc_template_id, sfdc_update_type_id,process_date) 
					values(@order_header_id, @sfdc_template_id, @sfdc_update_type_id, getdate())
				end
			else
				begin
					--select 'order already interfaced' as message
					print 'order already interfaced'
				end

			-- 1.5.6) null parameters 
			select @cybs_subscription_id = null, @order_header_id = null, @site_id = null, @company_type_id = null
				, @company_id = null, @license_attribute_license_value = null, @cybs_subscription_id = null

			select @temp_id = @temp_id + 1
	end

	-- 2) "Step 2"

	-- 2.1) mark cleverbridge orders as resolved
	--		I'm not actually sure why those were added to the exception table in the first place if they're being resolved
	--		without being processed
	update e 
	set exception_status = 'resolved', resolved_date = h.insert_date
	from order_external_load_exception e
		inner join order_header h 
			on e.order_header_id = h.order_header_id
	where e.exception_status = 'pending' and site_id = 'CBCART'

	-- 2.2) mark orders with a successful update as resolved
	--		these should already have been excluded in section 1.2 from being added to the exception queue
	update e 
	set exception_status = 'resolved', e.resolved_date = a.archive_date
	from order_external_load_exception e
		inner join order_header h 
			on e.order_header_id = h.order_header_id
		inner join sfdc_opportunity_update_archive a
			on e.order_header_id = a.order_header_id 
				and a.sfdc_update_type_id = @sfdc_update_type_id 
				and a.sfdc_response_code = 'Success'
	where e.exception_status = 'pending' 

	-- 2.3) select pending order_external_load_exception records inserted in section 1.2
	--		because this select includes some additional criteria not used in section 1.2, some pending records may not be
	--		processed by this (or potentially any other) process
	insert into @order_company (order_external_load_exception_id, order_header_id, company_id, order_company_type_id
		, customer_id)
	select e.order_external_load_exception_id, co.order_header_id, cc.company_id, t.order_company_type_id, cc.customer_id
	from order_external_load_exception e
		inner join order_header h
			on e.order_header_id = h.order_header_id
		inner join ve
ndor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join customer_order co
			on h.order_header_id = co.order_header_id 
				and co.customer_type_id = 1 -- Billing
		inner join customer_email ce
			on co.customer_id = ce.customer_id 
				and ce.email_status_id = 1 -- active
		inner join order_company_type t 
			on t.order_company_type_id in (1,2,4) -- account, bill_to_account, distributor_account (excluding reseller_partner_account)
		left join partner_order po 
			on h.order_header_id = po.order_header_id
			-- this join does not appear to be doing anything because it's neither excluding NTTCommunications in the WHERE
			-- clause not using any value from the partner_order table. this is probably a mistake and my guess is that 
			-- NTTCommunications should be an exclusion criteria
		left join customer_company cc
			on ce.customer_id = cc.customer_id
		left join order_company oc
			on h.order_header_id = oc.order_header_id 
				and oc.order_company_type_id = t.order_company_type_id
	where e.exception_status = 'pending' 
		and e.order_header_id not in (23610603, 23605990) 
		and (po.partner_id in (7943)) -- NTTCommunications
		and oc.order_company_id is null
	order by e.order_external_load_exception_id, t.order_company_type_id

	-- 2.2) proceed if orders are found
	if @@rowcount > 0
		begin 

			-- 2.3) insert order_company records
			insert into order_company (order_header_id, company_id, order_company_type_id, customer_id)
			select order_header_id, company_id, order_company_type_id, customer_id
			from @order_company
			order by order_header_id, order_company_type_id

			-- 2.4) update status of exceptions to 'resolved'
			update e
			set e.exception_status = 'resolved', resolved_date = getdate() 
			from @order_company oc
				inner join order_external_load_exception e
					on oc.order_external_load_exception_id = e.order_external_load_exception_id
			where e.exception_status = 'pending'

		end

	-- 3) "Step 3: Kaseya Canada assignment"

	-- 3.1) declare table variable with schema that matches the output of usp_order_select_external_orders_legacy
	declare @orders_kaseya table (order_header_id int, vendor_order_date date, vendor_order_code varchar(100), partner_id int
		, partner_name nvarchar(255), company_id int, company_name nvarchar(255), customer_email varchar(100)
		, site_id varchar(20), license_id int, keycode varchar(40), license_attribute_license_value int
		, license_attribute_license_value_description varchar(100))

	-- 3.2) populate table with usp_order_select_external_orders_legacy (previously usp_order_select_external_orders but that proc has other uses now)
	insert into @orders_kaseya (order_header_id, vendor_order_date, vendor_order_code, partner_id, partner_name, company_id, company_name
		, customer_email, site_id, license_id, keycode, license_attribute_license_value
		, license_attribute_license_value_description)
	exec usp_order_select_external_orders @partner_id = 5582
		

	-- 3.3) stage order headers to be updated
	--		these are Kaseya orders that have their order_company address in Canada
	declare @orders_to_update table (temp_id int identity(1, 1), order_header_id int)

	insert into @orders_to_update (order_header_id)
	select distinct o.order_header_id
	from @orders_kaseya o
		inner join order_company oc
			on oc.order_header_id = o.order_header_id
		inner join company_address ca
			on ca.company_id = o.company_id
	where ca.address_class_id = 1 -- primary
		and ca.address_status_id = 1 -- active
		and ca.country_id = 39 -- Canada
		and oc.order_company_type_id = 2 -- bill_to_account
		and oc.company_id <> 134802 -- Kaseya Canada

	-- 3.4) set initial loop variables and begin loop
	select @temp_id = 1, @total_ids = max(temp_id)from @orders_to_update

	while @total_ids >= @temp_id
		begin
			select @order_header_id = order_header_id
			from @orders_to_update
			where temp_id = @temp_id

			-- 3.4.1) ins
ert an audit record for the order_company record we're about to update
			insert into order_company_audit (order_company_id, order_header_id, company_id, order_company_type_id, insert_date
				, customer_id, audit_date)
			select order_company_id, order_header_id, company_id, order_company_type_id, insert_date, customer_id, getdate()
			from order_company oc
			where oc.order_header_id = @order_header_id

			-- 3.4.2) update the order_company record to Kaseya Canada
			update oc
			set oc.company_id = 134802 -- Kaseya Canada
				, oc.customer_id = 34243653 -- Accounts Payable (for Kaseya Canada)
			from order_company oc
			where oc.order_header_id = @order_header_id 
				and oc.company_id = 14088 -- Kaseya Corp

			select @temp_id = @temp_id + 1
		end

	-- 4) "Step 4: Arnold test order disable"

	-- 4.1) update status on all Arnold orders in order_external_load_exception
	update e
	set e.exception_status = 'test_order', e.resolved_date = getdate()
	from order_external_load_exception e
		inner join partner_order po
			on po.order_header_id = e.order_header_id
	where po.partner_id = 9275 and e.exception_status <> 'test_order'

	-- 4.2) do a bunch of weird updates the spirit of which seem to basically disable test keys
	--		this eventually needs to be refactored since updating these license tables directly is bad news bears
	update l
	set l.license_status_id = 2, l.customer_id = null, l.modified_date = @modified_date, l.modified_by = 'test_key_disable'
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 1

	update cl
	set cl.end_date = @modified_date, cl.last_modified_date = @modified_date, cl.last_modified_by = 'test_key_disable'
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
		inner join license_category_license cl
			on cl.license_id = l.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 2
		  and cl.end_date > @modified_date

	update cl
	set cl.end_date = @modified_date, cl.modified_date = @modified_date, cl.modified_by = 'test_key_disable'
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
		inner join license_seat cl
			on cl.license_id = l.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 2
		  and cl.end_date > @modified_date

	update cl
	set cl.capability_expiration_date = @modified_date, cl.modified_date = @modified_date, cl.modified_by = 'test_key_disable'
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
		inner join license_capability cl
			on cl.license_id = l.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 2
		  and cl.capability_expiration_date > @modified_date

	update cl
	set cl.end_date = @modified_date, cl.last_modified_date = @modified_date, cl.last_modified_by = 'test_key_disable'
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
		inner join license_module_license cl
			on cl.license_id = l.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 2
		  and cl.end_date > @modified_date

	update cl
	set cl.license_end_date = @modified_date, cl.
modified_date = @modified_date
	from partner_license pl
		inner join license l
			on l.license_id = pl.license_id
		inner join license_contract cl
			on cl.license_id = l.license_id
	where pl.partner_id = 9275
		  and pl.partner_license_status_id = 2
		  and (pl.start_date <= @modified_date and (pl.end_date is null or pl.end_date > pl.start_date))
		  and l.license_status_id = 2
		  and cl.license_end_date > @modified_date
		  and cl.license_contract_status_id = 1


end try

begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_notification_load]
-- =============================================================================

CREATE       procedure usp_order_notification_load
	@vendor_order_id	bigint,
	@submission_date	nvarchar(60),
	@site_id		nvarchar(130),
	@total_amount		money,
	@sub_total_amount	money,
	@tax_total		money,
	@order_offer_amount	money,
	@exchange_rate		float,
	@payment_method		nvarchar(100),
	@bill_to_vendor_id	nvarchar(100),
	@bill_to_last_name	nvarchar(200),
	@bill_to_first_name	nvarchar(100),
	@bill_to_address1	nvarchar(300),
	@bill_to_address2	nvarchar(200),
	@bill_to_address3	nvarchar(200),
	@bill_to_phone_number	nvarchar(30),
	@bill_to_postal_code	varchar	(32),
	@bill_to_city		nvarchar(50),
	@bill_to_state		nvarchar(4),
	@bill_to_email		nvarchar(128),
	@bill_to_fax		nvarchar(128),
	@bill_to_company_name	nvarchar(100),
	@bill_to_alt_phone	nvarchar(128),
	@bill_to_country	nvarchar(4),
	@line_item_id		nvarchar(100),
	@transaction_Description	nvarchar(50),
	@quantity		bigint,
	@vendor_product_id	nvarchar(200),
	@product_id		nvarchar(40),
	@product_locale		nvarchar(10),
	@ship_to_vendor_address_id	nvarchar(40),
	@ship_to_city		nvarchar(96),
	@ship_to_country	nvarchar(100),
	@ship_to_address1	nvarchar(400),
	@ship_to_address2	nvarchar(200),
	@ship_to_address3	nvarchar(200),
	@ship_to_last_name	nvarchar(100),
	@ship_to_first_name	nvarchar(100),
	@ship_to_phone_number	nvarchar(128),
	@ship_to_postal_code	nvarchar(64),
	@ship_to_state		nvarchar(4),
	@ship_to_email		nvarchar(128),
	@ship_to_fax		nvarchar(128),
	@ship_to_company_name	nvarchar(128),
	@ship_to_alt_phone	nvarchar(128),
	@line_unit_price	money,
	@line_list_price	money,
	@line_price_per_qty	money,
	@line_tax_amount	money,
	@tax_exempt		nvarchar(100),
	@line_offer_id		nvarchar(100),
	@line_offer_amount	money,
	@key_code		nvarchar(200),
	@Line_value_name	nvarchar(40),
	@line_value		nvarchar(40),
	@Program_id		nvarchar(40),
	@bill_to_customer_id	nvarchar(40),
	@order_offer_id		nvarchar(100),
	@order_locale		nvarchar(20),
	@opt_in			nvarchar(20),
	@where_heard		nvarchar(100),
	@test_order_ind		nvarchar(20),
	@order_value_name	nvarchar(50),
	@order_value		nvarchar(200),
	@order_load_status	nvarchar(100),
	@server_loc 		nvarchar(30),
	@ts 			datetime,
	@process_flag 		bit,
	@response_code 		int 		OUTPUT,
	@message 		varchar(100) 	OUTPUT		
AS
/*	DATE		AUTHOR		REMARKS
	11/21/06	TBlazek		Initial creation.
	02/08/07	TBlazek		Add call to usp_process_order_notification_load  if process_flag = 1
					(this eliminates the call from the PHP code - OrderNotification.php)

	DESCRIPTION
	Insert order_notification_load load table for order notification from 3rd party shopping cart vendor. 
	Call usp_process_order_notification_load procedure to process the order through the system.
*/
SET NOCOUNT ON

declare	@insert_date	datetime,
	@insert_by 	varchar(100),
	@order_load_definition_id int,
	@vendor_id int,
	@order_type  varchar(30),
	@system_user varchar(50)


SET @vendor_id = 2 --Digital River 
SET @insert_by = system_user
SET @insert_date = getdate()
SET @order_type = 'DRE5'
SET @system_user = system_user

--Check to see if this is a duplicate order
If exists (select vendor_order_id from order_notification_load_archive where vendor_order_id = @vendor_order_id)
	BEGIN
		SET @response_code = -900
		SET @message =  'order exists in order_notification_load_archive'
		RETURN
	END
Else If exists (select vendor_order_id from vendor_order where vendor_order_code = convert(varchar(100), @vendor_order_id))
	BEGIN
		SET @response_code = -905
		SET @message =  'order exists in vendor_order, order complete'
		RETURN
	END
Else If exists (select vendor_order_id from order_notification_load where vendor_order_id = @vendor_order_id and process_flag = 1)
	BEGIN
		SET @response_code = -910

		SET @message =  'order exists in order_notification_load'
		RETURN
	END

Select @order_load_definition_id = (Select order_load_definition_id 
						from order_load_status_definition 
						where order_load_status = 'ONLOADCOMPLETE')

If not exists (Select order_notification_status_id 
		from order_notification_status 
		where vendor_order_id = @vendor_order_id
		and vendor_id = @vendor_id)
	BEGIN
		Insert order_notification_status
		Values (@vendor_order_id, @vendor_id, @order_load_definition_id, null, 	
			@insert_date, @insert_by, @insert_date,	@insert_by)
		If @@ERROR <> 0
			BEGIN
				SET @response_code = -912
				SET @message = 'Error inserting table order_notification_status in usp_order_notification_load'
				Insert order_load_audit
				Values (@vendor_order_id, @vendor_id, @response_code, @message, @insert_date, @insert_by)
				RETURN
			END
	END

--Insert order_notification_load records for a single order.  This procedure will be called multiple times to insert a single order.
insert  order_notification_load
	(vendor_order_id,
	submission_Date,
	site_id,
	total_amount,
	sub_total_amount,
	tax_total,
	order_offer_amount,
	exchange_rate,
	payment_method,
	bill_to_vendor_id,
	bill_to_last_name,
	bill_to_first_name,
	bill_to_address1,
	bill_to_address2,
	bill_to_address3,
	bill_to_phone_number,
	bill_to_postal_code,
	bill_to_city,
	bill_to_state,
	bill_to_email,
	bill_to_fax,
	bill_to_company_name,
	bill_to_alt_phone,
	bill_to_country,
	line_item_ID,
	transaction_Description,
	quantity,
	vendor_product_ID,
	product_ID,
	product_locale,
	ship_to_vendor_address_id,
	ship_to_city,
	ship_to_country,
	ship_to_address1,
	ship_to_address2,
	ship_to_address3,
	ship_to_last_name,
	ship_to_first_name,
	ship_to_phone_number,
	ship_to_postal_code,
	ship_to_state,
	ship_to_email,
	ship_to_fax,
	ship_to_company_name,
	ship_to_alt_phone,
	line_unit_price,
	line_list_price,
	line_price_per_qty,
	line_tax_amount,
	tax_exempt,
	line_offer_ID,
	line_offer_amount,
	key_code,
	line_value_name,
	line_value,program_id,
	bill_to_customer_id,
	order_offer_ID,
	order_locale,
	opt_in,
	where_heard,
	test_order_ind,
	order_value_name,
	order_value,
	order_load_status,
	server_loc,
	ts,
	process_flag) 
values 
	(@vendor_order_id	,
	@submission_date	,
	@site_id	,
	@total_amount	,
	@sub_total_amount	,
	@tax_total	,
	@order_offer_amount	,
	@exchange_rate	,
	@payment_method	,
	@bill_to_vendor_id	,
	@bill_to_last_name	,
	@bill_to_first_name	,
	@bill_to_address1	,
	@bill_to_address2	,
	@bill_to_address3	,
	@bill_to_phone_number	,
	@bill_to_postal_code	,
	@bill_to_city	,
	case  when  @bill_to_state is null then '' else @bill_to_state end,
	@bill_to_email	,
	@bill_to_fax	,
	@bill_to_company_name	,
	@bill_to_alt_phone	,
	@bill_to_country	,
	@line_item_id	,
	@transaction_Description	,
	@quantity	,
	@vendor_product_id	,
	@product_id	,
	@product_locale	,
	@ship_to_vendor_address_id	,
	@ship_to_city	,
	@ship_to_country	,
	@ship_to_address1	,
	@ship_to_address2	,
	@ship_to_address3	,
	@ship_to_last_name	,
	@ship_to_first_name	,
	@ship_to_phone_number	,
	@ship_to_postal_code	,
	case  when  @ship_to_state is null then '' else @ship_to_state end,
	@ship_to_email	,
	@ship_to_fax	,
	@ship_to_company_name	,
	@ship_to_alt_phone	,
	@line_unit_price	,
	@line_list_price	,
	@line_price_per_qty	,
	@line_tax_amount	,
	@tax_exempt	,
	@line_offer_id	,
	@line_offer_amount	,
	@key_code	,
	@Line_value_name	,
	@line_value	,
	@Program_id	,
	@bill_to_customer_id	,
	@order_offer_id	,
	@order_locale	,
	@opt_in	,
	@where_heard	,
	@test_order_ind	,
	@order_value_name	,
	@order_value	,
	@order_load_status	,
	@server_loc 	,
	@ts,
	@process_flag)
	If @@ERROR <> 0
		BEGIN
			SET @response_code = -915
			SET @message = 'Error inserting table order_notification_load in usp_order_notification_load'
			Insert order_load_audit
			Values (@vendor_order_id, @vendor_id, @response_code, @message, @insert_date, @insert_by)
			RETURN
		END


If @process_flag = 1
BEGIN
 exec usp_process_order_notification_load @vendor_order_id, @order_type,@response_code  OUTPUT,@message OUTPUT
		 
	If @response_code <> 0
			BEGIN
		Insert order_load_audit
		Values (@vendor_order_id, @vendor_id, @response_code, @message, @insert_date, @system_user)
			if @@ERROR > 0
				BEGIN
					set @response_code = -110
					set @message = 'Error inserting order_load_audit after usp_process_order_notification_load in usp_process_sales_order_load.'
					RETURN
				END
			END
	Else
		BEGIN
			SET @response_code = 0
			SET @message = 'Order Notification Load insert complete'
		END
END

GO
