CREATE PROCEDURE [dbo].[usp_order_notification_load_archive_exists]

@vendor_order_id varchar(20)

/*	
	DATE		AUTHOR	REMARKS
	2007-04-06	cswarts	Initial creation.

	DESCRIPTION
	Called  to determine if the order exists in the order_load_notification_archive table in eCommerce database 
	prior to initiating an order load

	Logic rules:
	- If pass in vendor_order_id and record(s) are found in  order_load_notification_archive table, return the 
	order_load_status. 

	INPUT:
	vendor_order_id (required)
	
	OUTPUT:
	order_load_status
*/

AS

	BEGIN
		Select order_load_status  
		from order_notification_load_archive
		where vendor_order_id = @vendor_order_id
	END

RETURN



