-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_post_process]
-- =============================================================================

create PROCEDURE [dbo].[usp_order_post_process]
	(@order_header_id int)
AS
/*	
	date				author			remarks
	2007-09-18			bjordan			Initial Creation

	description
	Executes post processing sps based on product family
	
*/
set nocount on
BEGIN Try
	DECLARE @procedure_name varchar(255),
		    @rec_id int,
			@max_rec_id int

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
--	begin transaction
	-- Auto renewal product family
	
	declare @post_process table (rec_id int identity(1,1) not null,
								 procedure_name varchar(100) null)

	insert into @post_process(procedure_name)
	SELECT oppf.procedure_name from order_post_process_family oppf with (nolock)
	inner join product p with (nolock) 
	on p.product_family_id = oppf.product_family_id
	inner join order_item oi with (nolock)
	on oi.product_id = p.product_id
	inner join order_header oh with (nolock)
	on oi.order_header_id = oh.order_header_id
	where oi.order_header_id = @order_header_id
	order by priority

	select @rec_id = min(rec_id),@max_rec_id = max(rec_id)
	from @post_process
		
		begin transaction;

		while @rec_id <= @max_rec_id 
			begin
			
			select @procedure_name = procedure_name
			from @post_process
			where rec_id = @rec_id
		
			exec @procedure_name @order_header_id
	    
			set @rec_id = @rec_id + 1
			end
	
		commit transaction;
end try
begin catch

	  if @@trancount > 0
	      rollback transaction;

      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		
end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_process_external_online_orders_caller_obsolete]
-- =============================================================================

CREATE procedure [dbo].[usp_order_process_external_online_orders_caller_obsolete] 

/*	
	DATE		AUTHOR		REMARKS
	2022-09-29	gblandford	Initial creation.
	2022-10-07	gblandford	Renamed from dbo.usp_order_process_external_online_orders, as that name is now used for
							what was previously	dbo.usp_order_select_external_online_orders
							- part of refactor for ALM-3008
	2022-12-07	abelenkiy	Deprecated and renamed to [usp_order_process_external_online_orders_caller_obsolete]
							Also deprecated [usp_order_process_external_online_orders] because [usp_order_process_external_orders] 
								can now be called directly by the [External order] job

	DESCRIPTION
	Top-level procedure (job) to process external_orders AND external_online_orders

*/

AS

SET NOCOUNT ON				

BEGIN TRY

	DECLARE	@start_date DATETIME = NULL,
		@site_json NVARCHAR(MAX),
		@payment_merchant_json NVARCHAR(MAX)

	DECLARE @site TABLE (
			site_id VARCHAR(20)
		);	

	DECLARE @payment_merchant TABLE (
			payment_merchant_id INT
		);	

	/*
	| Setup sites
	*/

	INSERT INTO @site (
	    site_id
	) VALUES 
	( 'WRCART' )
	, ( 'CSI' )
	, ( 'AUTORENEWAL' );

	SELECT @site_json = (
		SELECT 
			s.site_id
		FROM @site s
		FOR JSON AUTO );

	/*
	|
	| Setup payment merchants
	|
	| These _should_ be setup in configuration and NOT hard-coded
	|
	*/	
	INSERT INTO @payment_merchant (
	    payment_merchant_id
	)
	SELECT
		pm.payment_merchant_id
	FROM dbo.payment_merchant pm
	WHERE pm.merchant_id IN (
		'428346'
		, '428328'
		, '441274'
		, '441275'
		, '441276'
		, '441282'
		, '441283'
		, '441284'
		, '441288'
		, '441289'
	);

	SELECT @payment_merchant_json = (
		SELECT 
			pm.payment_merchant_id
		FROM @payment_merchant pm
		FOR JSON AUTO );

	SELECT @site_json
	SELECT @payment_merchant_json

	/*
	|
	| Step 1. usp_order_select_external_online_orders
	|
	*/
	EXECUTE dbo.usp_order_process_external_online_orders
		@start_date = @start_date
		, @sites = @site_json
		, @payment_merchants = @payment_merchant_json

	/*
	|
	| Step 2. usp_order_select_external_orders
	|
	*/
	EXECUTE dbo.usp_order_process_external_orders
		@partner_id = NULL
		, @site_id = NULL
		, @license_attribute_license_value = NULL
		, @license_id = NULL
		, @start_date = NULL  
		, @order_header_id = NULL
		, @has_pending_sap_account = 1
		, @source = NULL
       
END TRY

BEGIN CATCH

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXEC usp_LogError @ErrorDB = @DBName

END CATCH; 

GRANT EXECUTE ON [dbo].[usp_order_process_external_online_orders_caller] TO execsprocs;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_process_external_online_orders_obsolete]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_order_process_external_online_orders_obsolete] (
		@start_date datetime,
		@sites nvarchar(max),
		@payment_merchants nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2020-09-22	esmart		Initial creation.
	2021-09-16  psatish		Added Orderheaderid to check the SAP_Create_Customer
	2021-12-16  psatish		Replaced the correct parameter in the fn_order_select_order_item_json function
	2022-10-07	gblandford	Renamed from usp_order_select_external_online_orders as this is a processing procedure _NOT_ select
							- part of refactor for ALM-3008
	2022-12-07	abelenkiy	Deprecated and renamed to [usp_order_process_external_online_orders_obsolete]
							Merged logic from Section 4 into [usp_order_process_external_orders] so that procedure can handle all orders
							Also deprecated [usp_order_process_external_online_orders_caller] because [usp_order_process_external_orders] 
								can now be called directly by the [External order] job

	DESCRIPTION
	select partner_billing_order
*/

AS

SET NOCOUNT ON				

BEGIN TRY

		DECLARE @company_id INT, 
				@sfdc_template_name VARCHAR(50), 
				@order_header_id INT, 
				@trial_id INT, 
				@form_submit_id INT, 
				@process_date DATETIME, 
				@license_id INT, 
				@sfdc_update_json NVARCHAR(MAX), 
				@temp_id INT, 
				@total_ids INT,
				@ShipTo VARCHAR(20), 
				@BillTo VARCHAR(20),
				@EndUser VARCHAR(20),
				@SoldTo VARCHAR(20),
				@Payer VARCHAR(20),
				@ShipTo_SoldTo CHAR(1),
				@cybs_subscription_id INT, 
				@site_id VARCHAR(65), 
				@company_type_id TINYINT, 
				@product_line_id INT, 
				@license_attribute_license_value INT,
				@sfdc_opportunity_update_id INT,
				@customer_service_type_id TINYINT,
				@customer_service_status_id TINYINT,
				@customer_service_id INT,
				@response_code INT,
				@message VARCHAR(100)

		DECLARE @orders TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT, company_name NVARCHAR(255), company_type_id TINYINT, site_id VARCHAR(20), order_item_id INT, effective_date DATETIME, license_category_id INT, license_attribute_license_value INT)
		DECLARE @sites_table TABLE (site_id VARCHAR(20))
		DECLARE @merchant_table TABLE (payment_merchant_id INT)
		DECLARE @sap_accounts_pending TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT, company_name NVARCHAR(255))
		DECLARE @sap_accounts_update_pending TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT, company_name NVARCHAR(255), change_reason VARCHAR(50))

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) get list of orders
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
					
		-- 1.1) @start_date
		IF @start_date IS NULL 
			BEGIN
			SELECT @start_date = DATEADD(mm,-1,GETDATE())
			END

		-- 1.2) @sites_table
		INSERT INTO @sites_table(site_id)
		SELECT site_id
		FROM OPENJSON(@sites)
		WITH (site_id VARCHAR(20) '$.site_id')

		-- 1.3) @merchant_table
		INSERT INTO @merchant_table(payment_merchant_id)
		SELECT payment_merchant_id
		FROM OPENJSON(@payment_merchants)
		WITH (payment_merchant_id VARCHAR(20) '$.payment_merchant_id')
			   
		-- 1.4) @orders	
		INSERT INTO @orders(order_header_id, company_id, company_name, company_type_id, site_id)
		SELECT DISTINCT oc.order_header_id, cp.company_id, cp.company_name, cp.company_type_id, h.site_id
		FROM order_company oc WITH (NOLOCK)
		INNER JOIN company cp WITH (NOLOCK)
			ON oc.company_id = cp.company_id
		INNER JOIN o
rder_header h WITH (NOLOCK)
			ON oc.order_header_id = h.order_header_id
		INNER JOIN @sites_table s
			ON s.site_id = h.site_id
		INNER JOIN order_item i WITH (NOLOCK)
			ON oc.order_header_id = i.order_header_id
		INNER JOIN product_license_category plc WITH (NOLOCK)
			ON i.product_id = plc.product_id
		INNER JOIN product p WITH (NOLOCK)
			ON i.product_id = p.product_id
		INNER JOIN order_payment_header op WITH (NOLOCK)
			ON h.order_header_id = op.order_header_id
		inner join payment_header ph with (nolock)
			on op.payment_header_id = ph.payment_header_id
		inner join @merchant_table mt
			on mt.payment_merchant_id = ph.payment_merchant_id
		left join sfdc_opportunity_update_archive a with (nolock)
			on a.order_header_id = h.order_header_id and a.sfdc_response_code <> 'Failure' and a.sfdc_update_type_id = 115
		left join sfdc_opportunity_update su with (nolock)
			on su.order_header_id = h.order_header_id
		left join order_external_load_exception le with (nolock)
			on oc.order_header_id = le.order_header_id and le.exception_status = 'pending'
		left join partner_license pl with (nolock)
			on oc.order_header_id = pl.order_header_id and pl.partner_license_status_id <> 2
		where  oc.order_company_type_id = 2 and p.product_family_id in (55,300)  and h.order_status_id = 1 
			and h.insert_date >= @start_date
			and a.sfdc_opportunity_update_archive_id is null 
			and su.sfdc_opportunity_update_id is null
			and le.order_external_load_exception_id is null
			and pl.partner_license_id is null
	
		-- 1.5) license_attribute_license_value
		update o
		set o.license_attribute_license_value = ij.license_attribute_license_value
		from @orders o
		inner join order_item i
			on i.order_header_id = o.order_header_id
		inner join order_item_json j
			on j.order_item_id = i.order_item_id
		cross apply fn_order_select_order_item_json(j.order_item_id) ij
					


		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) check for new sap accounts
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) @sap_account_pending
		
		select @sfdc_template_name = 'sap_create_customer'

		insert into @sap_accounts_pending(order_header_id, company_id, company_name)
		select distinct o.order_header_id, c.company_id, c.company_name
		from @orders o
		inner join order_company oc
			on oc.order_header_id = o.order_header_id
		inner join company c
			on c.company_id = oc.company_id
		left join sap_account a
			on a.company_id = c.company_id
		left join sfdc_opportunity_update_archive u
			on u.order_header_id = o.order_header_id and u.sfdc_response_code = 'Success'
		left join sfdc_template t
			on t.sfdc_template_id = u.sfdc_template_id and t.sfdc_template_name = @sfdc_template_name
		where a.sap_account_id is null and u.sfdc_opportunity_update_archive_id is null

		-- 2.2) sap_create_customer
		if exists (select company_id from @sap_accounts_pending)
			begin

			select @temp_id = 1, @total_ids = max(temp_id) from @sap_accounts_pending

			while @total_ids >= @temp_id
				begin
				-- print @temp_id

				-- 2.2.1) @company_id and @order_header_id
				select @company_id = company_id, @order_header_id = order_header_id
				from @sap_accounts_pending
				where temp_id = @temp_id

				
				select @sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
				from sfdc_opportunity_update u
				inner join sfdc_opportunity_update_json j
					on j.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
				where json_value(j.sfdc_update_json,'$.company_id') = @company_id and u.order_header_id=@order_header_id


				if @sfdc_opportunity_update_id is null
					begin
					-- 2.2.2) @partner_function_json
					select @ShipTo = case when 
oc.company_id is null then 'false' else 'true' end, 
                        @EndUser = case when oc.company_id is null then 'false' else 'true' end,
                        @BillTo = case when oc2.company_id is null then 'false' else 'true' end,
                        @SoldTo = case when oc2.company_id is null then 'false' else 'true' end,
                        @Payer = case when oc2.company_id is null then 'false' else 'true' end
                    from order_company_type t
                    left join order_company oc
                            on oc.order_company_type_id = 1 and oc.order_header_id = @order_header_id and oc.company_id = @company_id
                    left join order_company oc2
                            on oc2.order_company_type_id = 2 and oc2.order_header_id = @order_header_id and oc2.company_id = @company_id
                    where t.order_company_type_id in (1,2)

				
					-- 2.2.3) @sfdc_update_json
                    select @sfdc_update_json = (select c.company_id, (select distinct cc.customer_id
                                                                                                        from customer_company cc
                                                                                                        inner join order_company oc
                                                                                                            on oc.company_id = cc.company_id and oc.customer_id = cc.customer_id
                                                                                                        where cc.company_id = c.company_id 
                                                                                                        for json path) customers, 
                                                                                                        @BillTo as [PartnerFunctions.BillTo],@ShipTo as [PartnerFunctions.ShipTo],@EndUser as [PartnerFunctions.EndUser],@SoldTo as [PartnerFunctions.SoldTo],@Payer as [PartnerFunctions.Payer]
                                                                    from company c
                                                                    where c.company_id = @company_id
                                                                    for json path, without_array_wrapper)

					
						-- 2.2.4) usp_sfdc_insert_sfdc_opportunity_update
						exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name=@sfdc_template_name,@order_header_id=@order_header_id,@trial_id=@trial_id,@form_submit_id=@form_submit_id,@process_date=@process_date,@license_id=@license_id,@sfdc_update_json=@sfdc_update_json
					
					end

				select @sfdc_update_json = null, @company_id = null, @order_header_id = null, @sfdc_opportunity_update_id = null, @sfdc_update_json = null, @BillTo = null, @ShipTo = null
				select @temp_id = @temp_id + 1

				end

			-- 2.3) delete orders that need accounts created
			delete o
			from @orders o
			inner join @sap_accounts_pending p
				on p.order_header_id = o.order_header_id

			end

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) sap_update_customer
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 3.1) partner functions
		insert into @sap_accounts_update_pending(order_header_id, company_id, company_name, change_reason)
		select distinct o.order_header_id, o.company_id, o.company_name, 'partner_function'
		from @orders o
		inner join order_company oc
			on oc.order_header_id = o.order_header_id
		inner join sap_account a
			on a.company_id = o.company_id
		inner join sap_partner_function_order_company_type f
			on f.order_company_type_id = oc.order_company_type_id
		outer apply fn_sap_s
elect_partner_function(oc.company_id,null,f.partner_function_name_german) pf
		where oc.order_company_type_id in (1,2,3) and pf.sap_partner_function_id is null

		-- 3.2) company_name and address
		insert into @sap_accounts_update_pending(order_header_id, company_id, company_name, change_reason)
		select distinct o.order_header_id, o.company_id, o.company_name, case when a.sap_account_name <> c.company_name then 'company_name' else 'address' end
		from @orders o
		inner join sap_account a
			on a.company_id = o.company_id
		inner join company c
			on c.company_id = a.company_id
		inner join company_address ca
			on ca.company_id = a.company_id
		left join @sap_accounts_update_pending p
			on p.company_id = a.company_id
		where p.company_id is null and ca.address_type_id = 1 and ca.address_class_id = 1 and ca.address_status_id = 1
			and (ca.address_1 <> a.address_1 or
				ca.address_2 <> a.address_2 or
				ca.city <> a.city or
				ca.state <> a.state or
				ca.country_id <> a.country_id or
				a.sap_account_name <> c.company_name)

		-- 3.3) remove update pending
		delete p
		from customer_service cs 
		inner join customer_service_json j
			on j.customer_service_id = cs.customer_service_id
		inner join @sap_accounts_update_pending p
			on p.company_id = json_value(j.customer_service_json,'$.company_id')
		where cs.customer_service_type_id = 4

		delete p
		from customer_service cs 
		inner join customer_service_json j
			on j.customer_service_id = cs.customer_service_id
		inner join @orders p
			on p.company_id = json_value(j.customer_service_json,'$.company_id')
		where cs.customer_service_type_id =  4

		-- 3.2) sap_update_customer

		select @sfdc_template_name = 'sap_update_customer'

		if exists (select company_id from @sap_accounts_update_pending)
			begin

			select @temp_id = 1, @total_ids = max(temp_id) from @sap_accounts_update_pending

			while @total_ids >= @temp_id
				begin
				-- print @temp_id

				-- 3.2.1) @company_id and @order_header_id
				select @company_id = company_id, @order_header_id = order_header_id, @ShipTo_SoldTo = case when change_reason = 'partner_function' then 'T' else 'F' end
				from @sap_accounts_update_pending
				where temp_id = @temp_id

				
				select @sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
				from sfdc_opportunity_update u
				inner join sfdc_opportunity_update_json j
					on j.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
				where json_value(j.sfdc_update_json,'$.company_id') = @company_id


				if @sfdc_opportunity_update_id is null
					begin
					-- 3.2.2) @partner_function_json
					select @ShipTo = case when oc.company_id is null then 'false' else 'true' end, 
                        @EndUser = case when oc.company_id is null then 'false' else 'true' end,
                        @BillTo = case when oc2.company_id is null then 'false' else 'true' end,
                        @SoldTo = case when oc2.company_id is null then 'false' else 'true' end,
                        @Payer = case when oc2.company_id is null then 'false' else 'true' end
                    from order_company_type t
                    left join order_company oc
                            on oc.order_company_type_id = 1 and oc.order_header_id = @order_header_id and oc.company_id = @company_id
                    left join order_company oc2
                            on oc2.order_company_type_id = 2 and oc2.order_header_id = @order_header_id and oc2.company_id = @company_id
                    where t.order_company_type_id in (1,2)


				
					-- 3.2.3) @sfdc_update_json
                    select @sfdc_update_json = (select c.company_id, @ShipTo_SoldTo as ShipTo_SoldTo, (select distinct cc.customer_id
                                                                                                        from customer_company cc
                                                                  
                                      inner join order_company oc
                                                                                                            on oc.company_id = cc.company_id and oc.customer_id = cc.customer_id
                                                                                                        where cc.company_id = c.company_id 
                                                                                                        for json path) customers, 
                                                                                                        @BillTo as [PartnerFunctions.BillTo],@ShipTo as [PartnerFunctions.ShipTo],@EndUser as [PartnerFunctions.EndUser],@SoldTo as [PartnerFunctions.SoldTo],@Payer as [PartnerFunctions.Payer]
                                                                    from company c
                                                                    where c.company_id = @company_id
                                                                    for json path, without_array_wrapper)

					-- 3.2.4) customer_service
					
					if @sfdc_update_json is not null
						begin

						-- 3.2.4.1) @customer_service_type_id
						select @customer_service_type_id = customer_service_type_id
						from customer_service_type
						where customer_service_type_name = 'sap_account_change'

						-- 3.2.4.2) @customer_service_status_id
						select @customer_service_status_id = customer_service_status_id
						from customer_service_status
						where customer_service_status_name = 'Pending'

						-- 3.2.4.3) insert customer_service
						insert into customer_service(customer_service_type_id, customer_service_status_id)
						values(@customer_service_type_id, @customer_service_status_id)

						select @customer_service_id = scope_identity()
					
						insert into customer_service_json(customer_service_id,customer_service_json) values(@customer_service_id,@sfdc_update_json)	
					

						-- 3.2.4.4) usp_sfdc_insert_sfdc_opportunity_update
						exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name=@sfdc_template_name,@order_header_id=@order_header_id,@trial_id=@trial_id,@form_submit_id=@form_submit_id,@process_date=@process_date,@license_id=@license_id,@sfdc_update_json=@sfdc_update_json
						
						end
					end

				select @sfdc_update_json = null, @company_id = null, @order_header_id = null, @sfdc_opportunity_update_id = null, @sfdc_update_json = null, @BillTo = null, @ShipTo = null
				select @temp_id = @temp_id + 1

				end

			-- 3.3) delete orders that need partner functions updated
			delete o
			from @orders o
			inner join @sap_accounts_update_pending p
				on p.order_header_id = o.order_header_id

			end

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) process orders
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		select @temp_id = 1, @total_ids = max(temp_id) from @orders

		while @total_ids >= @temp_id
			begin
		
			-- 4.1) select @order_header_id
			select @order_header_id = order_header_id from @orders where temp_id = @temp_id

			if exists (select oc.company_id from order_company oc left join sap_account a on a.company_id = oc.company_id where oc.order_header_id = @order_header_id and a.sap_account_id is null)
				begin
				select @order_header_id = null
				end

			if @order_header_id is not null
				begin
					
					-- 4.2) select parameters
					select @site_id = site_id, @company_type_id = company_type_id, @product_line_id = 300, @license_attribute_license_value = license_attribute_license_value
					from @orders
					where order_header_id = @order_header_id
		
					-- 4.3) insert order_extension
	
				insert into order_extension (order_header_id, order_extension_type_id, order_extension_value)
					select @order_header_id, f.order_extension_type_id, f.order_extension_value
					from dbo.fn_order_select_default_order_extension(@site_id,@product_line_id,@company_type_id,@license_attribute_license_value) f
					left join order_extension e
						on f.order_extension_type_id = e.order_extension_type_id and e.order_header_id = @order_header_id
					where e.order_extension_id is null
	
					-- 4.4) cybs_subscription
					insert into cybs_subscription (credit_card_subscription_id, payment_merchant_id, insert_date, account_number, expiration_month, expiration_year, card_type_id)
					select cc.credit_card_subscription_id, h.payment_merchant_id, getdate(), right(pa.account_number,4), pa.expiration_month, pa.expiration_year, pa.card_type_id
					from order_payment_header op
					inner join payment_header h
						on op.payment_header_id = h.payment_header_id
					inner join payment_subscription_credit_card cc
						on op.payment_header_id = cc.payment_header_id
					inner join payment_account pa
						on h.payment_header_id = pa.payment_header_id
					left join cybs_subscription s
						on cc.credit_card_subscription_id = s.credit_card_subscription_id
					where op.order_header_id = @order_header_id and s.cybs_subscription_id is null

					select @cybs_subscription_id = s.cybs_subscription_id
					from order_payment_header op
					inner join payment_header h
						on op.payment_header_id = h.payment_header_id
					inner join payment_subscription_credit_card cc
						on op.payment_header_id = cc.payment_header_id
					inner join payment_account pa
						on h.payment_header_id = pa.payment_header_id
					inner join cybs_subscription s
						on cc.credit_card_subscription_id = s.credit_card_subscription_id
					where op.order_header_id = @order_header_id

					if @cybs_subscription_id is not null
						begin
							insert into cybs_subscription_customer (cybs_subscription_id, customer_id, company_id, insert_date)
							select @cybs_subscription_id, oc.customer_id, oc.company_id, getdate()
							from order_company oc
							left join cybs_subscription_customer cs
								on oc.company_id = cs.company_id and oc.customer_id = cs.customer_id and cs.cybs_subscription_id = @cybs_subscription_id
							where oc.order_company_type_id = 2 and oc.order_header_id = @order_header_id and cs.cybs_subscription_customer_id is null
						end

						select @cybs_subscription_id = null

					-- 4.5) insert into sfdc queue
					if not exists (select sfdc_opportunity_update_archive_id from sfdc_opportunity_update_archive where order_header_id = @order_header_id and sfdc_template_id = 17 and sfdc_update_type_id = 115 and sfdc_response_code <> 'failure')
						begin
							select @sfdc_template_name = 'external_order'

							exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name=@sfdc_template_name,@order_header_id=@order_header_id,@trial_id=@trial_id,@form_submit_id=@form_submit_id,@process_date=@process_date,@license_id=@license_id,@sfdc_update_json=@sfdc_update_json
							
						end
					else
						begin
						select 'order already interfaced' as message
						end
				
				end 

				-- 4.5) null parameters 
				select @cybs_subscription_id = null, @order_header_id = null, @site_id = null, @license_attribute_license_value = null, @company_type_id = null
				
				select @temp_id = @temp_id + 1
		end
		
		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_process_external_orders]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_order_process_external_orders] (
	
	@start_date DATETIME = NULL,
	@order_header_id INT = NULL
)

/*	
	DATE			AUTHOR			REMARKS
	2019-02-11		rvinoche		Initial creation.
	2019-05-01		esmart			Enhancements
	2019-07-16		esmart			Performance improvements
	2020-01-07		esmart			OT integration enhancements
	2021-09-01		psatish			Performance improvements and to avoid inserting duplicate records into sfdc_opportunity_update
	2021-10-01      nprimo          Added a new parameter that will be used to filter to order source
	2021-12-24      nprimo          Merged changes from 'usp_order_select_external_orders_new' and 'usp_order_select_external_orders'
	2021-12-24		psatish			Modified the join to pick the external orders/CSI orders 
	2021-12-27		psatish		    Fixed the duplciate records in sfdc_opportunity_update_Archive table
	2022-01-18      nprimo          Filters down the results to the desired partner_id that was passed in to the procedure, (section 1.1)
	2022-01-18      nprimo          Determines weather the results should be only orders with sap accounts (@has_pending_sap_account=0), or only orders without sap accounts (@has_pending_sap_account=1), (section 4.1)
	2022-01-19      nprimo          Fixed @license_attribute_license_value and @license_id filters not working, (section 4.1.1, 4.1.2)
	2022-01-19      nprimo          Removed unused parameter and changed @sap_account to @has_pending_sap_account (for clarity)
	2022-05-05		psatish			ALM# 1206 Fixed the duplicate entries in the sfdc_opportunity_update 

	<< usp_order_load_external_order_batch >>

	2022-05-18		abelenkiy		Initial creation
	2022-06-01		abelenkiy		Added section 1.3.1 to remove records from processing if pending service exists on company
	2022-09-29		abelenkiy		Added Step 3 and Step 4 from production external_order_batch_load job.
	2022-10-07		gblandford		Update call from usp_order_select_external_orders_legacy to new procedure usp_order_select_external_orders
									which has been refactored without processing code
									- part of refactor for ALM-3008	

	<< usp_order_load_external_order_batch >>

	2022-10-07		gblandford		New procedure with processing code extracted from usp_order_select_external_orders 
									- part of refactor for ALM-3008
	2022-10-14		abelenkiy		ALM-3007 - Fixed issue with second unique customer not being created (Section 2.2.3) and missing partner_function on customer update (Section 3.1)
									other minor refactoring and removal of unused variables
	2022-12-13		abelenkiy		ECOM-220 - Major refactor to streamline procedure and have robust address matching when determining to update; 
									Merged in logic from section 4 of [usp_order_process_external_online_orders] to deprecate that and called procedure; added documentation
	2023-01-04		abelenkiy		ECOM-446 - Added exclusion of Cleverbridge orders
	2023-08-07		gblandford		https://jira.opentext.com/browse/ECOM-1760 - Major refactor - merge code with dbo.usp_order_load_external_order_batch 
									Premilimary fix was address incorrect logic loop in 4.2) that was causing NULL order_header_id and JSON values to be passed
									to sfdc opportunity update queue, but that code is superceded by that from other procedure
									Also made some performance tweaks; replace SELECT COUNT(*)s with EXISTS/NOT EXISTS, moved index creation of temp table to AFTER table load
	2025-04-23		rambasana		D-4388095 Exclude business paypal order from external order process
	
	DESCRIPTION
	Select all pending external orders to be loaded into SFDC/SAP. Called by [External order] job, which is scheduled to run every 5 minutes.

	Records are written to SFDC update queue (which actually interfaces to SAP for the pro
cess types in this procedure):
	
		sap_create_customer - order has an order_company record that does not have a corresponding record in sap_account
		sap_update_customer - order_company does have a corresponding record in sap_account but the address is different in company_address or sap_account is missing requisite partner functions for order_company_type

	Then, external online orders are processed through Section 4 with the external_order process type.

	Section 4 of the original procedure is now omitted as the code was not being executed AND the loading of external order (and exception) logic
	was better handled in dbo.usp_order_load_external_order_batch. This order load code has been imported and sections 1 thru 4 have been relabelled 4 thru 7


	Tech debt: 
		
		- The logic for formatting JSON and calling usp_sfdc_insert_sfdc_opportunity_update is similar enough that it should probably be combined into one section instead of repeating code.
		- The address comparison leaves out state since the state field isn't normalized or standardized across different tables in ecom. Once that standardization is complete, state can be reimplemented into the comparison.


	<< usp_order_load_external_order_batch Legacy notes >>

		DESCRIPTION
		Create to abstract logic from job [external_order_batch_load] into procedure. The job info and schedule (every 5 minutes) 
		will remain in place except procedure will be called instead of having code in job step text. The original job description 
		below: 
	
			This job will gather all online business orders that have yet to be interfaced into oracle. It will run a match on 
			company and if successful will update order data and add it to the sfdc queue.

		Other than a cursory cleanup and basic annotation of the code, no business logic is changed in the initial creation 
		of this procedure. It's not entirely clear what is supposed to be happening and whether it's compatible with the 
		future-state SAP integration, so further revision will be required.

		The procedure sections retain the original Step 1 and Step 2 sections of the job despite the ambiguous naming of those 
		sections. This separation may or may not prove to be meaningful as we discover what this code is supposed to do.

		Step 3 and Step 4 are proprietary to Kaseya and test orders.

	<< usp_order_load_external_order_batch >>


*/

AS

	SET NOCOUNT ON	

	BEGIN TRY

	DECLARE	@company_id INT, 
		@sfdc_template_name VARCHAR(50),
		@sfdc_opportunity_update_id INT,
		@sfdc_update_json NVARCHAR(MAX), 
		@temp_id INT, 
		@total_ids INT,
		@shipto VARCHAR(20), 
		@billto VARCHAR(20),
		@enduser VARCHAR(20),
		@soldto VARCHAR(20),
		@payer VARCHAR(20),
		@shipto_soldto CHAR(1),
		@customer_service_type_id TINYINT,
		@customer_service_status_id TINYINT,
		@customer_service_id INT,
		@resellerpartner VARCHAR(2),
		@order_company_type_id INT,
		@cybs_subscription_id INT, 
		@site_id VARCHAR(65), 
		@company_type_id TINYINT,
		@product_line_id INT, 
		@license_attribute_license_value INT

	--<< usp_order_load_external_order_batch >>

		DECLARE @sfdc_template_id TINYINT
			, @sfdc_update_type_id TINYINT
			, @modified_date DATETIME = GETDATE()
	
	--<< usp_order_load_external_order_batch >>


	DROP TABLE IF EXISTS #orders
	CREATE TABLE #orders (id INT IDENTITY(1,1), order_header_id INT, vendor_order_date DATE, 
		vendor_order_code VARCHAR(100), company_id INT, company_name NVARCHAR(255), 
		order_company_type_id INT, sap_account_id INT, site_id VARCHAR(65), company_type_id TINYINT)

	DECLARE @sap_create_customer TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT,
		order_company_type_id INT)

	DECLARE @sap_update_customer TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT, 
		company_name NVARCHAR(255), change_reason VARCHAR(50))

	DECLARE @sap_address TABLE (company_id INT, address_1 NVARCHAR(255), address_2 NVARC
HAR(255), 
		city NVARCHAR(130), state NVARCHAR(3), postal_code NVARCHAR(32), country_id SMALLINT, 
		clean_address NVARCHAR(510), clean_city NVARCHAR(130), clean_postal_code NVARCHAR(32))

	DECLARE @current_address TABLE (company_id INT, address_1 NVARCHAR(255), address_2 NVARCHAR(255), 
		city NVARCHAR(130), state NVARCHAR(3), postal_code NVARCHAR(32), country_id SMALLINT, 
		clean_address NVARCHAR(510), clean_city NVARCHAR(130), clean_postal_code NVARCHAR(32))

	DECLARE @external_online_order TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT,
		company_type_id TINYINT, license_attribute_license_value INT, site_id VARCHAR(65))

	DECLARE @APP_CONFIG TABLE (business_product_line INT)

    INSERT INTO @APP_CONFIG
    (
       business_product_line
    )
    SELECT f.[key]
    FROM dbo.[fn_app_config_select_key_values]('BUSINESS_PRODUCT_LINE', 'GENERAL') f
	
	IF @start_date IS NULL 
		BEGIN
			SELECT @start_date = DATEADD(MONTH, -1, GETDATE())
		END

	INSERT INTO #orders(order_header_id, vendor_order_date, vendor_order_code, company_id, company_name,
		order_company_type_id, sap_account_id, site_id, company_type_id)

	SELECT h.order_header_id, h.vendor_order_date, v.vendor_order_code,	c.company_id, c.company_name,
		oc.order_company_type_id, sa.sap_account_id, h.site_id, c.company_type_id
	FROM dbo.order_header h WITH (NOLOCK)
		INNER JOIN dbo.order_company oc WITH (NOLOCK)
			ON h.order_header_id = oc.order_header_id 
		INNER JOIN dbo.company c WITH (NOLOCK)
			ON oc.company_id = c.company_id
		INNER JOIN dbo.vendor_order v WITH (NOLOCK)
			ON h.vendor_order_id = v.vendor_order_id
		LEFT JOIN dbo.sap_account sa WITH (NOLOCK)
			ON sa.company_id = c.company_id
		LEFT JOIN dbo.sfdc_opportunity_update_archive a WITH (NOLOCK)
			ON a.order_header_id = h.order_header_id 
				AND a.sfdc_response_code <> 'Failure' 
				AND a.sfdc_update_type_id = 115
		LEFT JOIN dbo.sfdc_opportunity_update su WITH (NOLOCK)
			ON su.order_header_id = h.order_header_id 
				AND a.sfdc_update_type_id = 115

	WHERE h.order_status_id = 1
		AND v.vendor_id <> 9 --cleverbridge
		AND h.order_header_id = ISNULL(@order_header_id , h.order_header_id)
		AND a.sfdc_opportunity_update_archive_id IS NULL
		AND su.sfdc_opportunity_update_id IS NULL
		AND h.insert_date > @start_date
	ORDER BY h.order_header_id

	-- create index AFTER orders are loaded for quick execution
	CREATE NONCLUSTERED INDEX indx_orders ON #orders(order_header_id, company_id)

	-- delete records with pending sap_account_change
	DELETE o
	FROM #orders o
		INNER JOIN dbo.customer_service_json j
			ON o.company_id = JSON_VALUE(j.customer_service_json,'$.company_id')
		INNER JOIN dbo.customer_service cs 
			ON j.customer_service_id = cs.customer_service_id
	WHERE cs.customer_service_type_id = 4 -- sap_account_change

	-- delete records with business paypal orders
	DELETE o 
			FROM #orders o
			INNER JOIN  dbo.order_item oi
				ON oi.order_header_id = o.order_header_id
			inner JOIN dbo.product p 
				ON oi.product_id = p.product_id   
			inner JOIN dbo.product_line_product plp 
				ON plp.product_id = p.product_id
			inner JOIN @APP_CONFIG ap 
				ON ap.business_product_line = plp.product_line_id
			inner JOIN dbo.order_payment_header oph 
				ON o.order_header_id = oph.order_header_id
			inner JOIN dbo.payment_header ph 
				ON ph.payment_header_id = oph.payment_header_id
			inner JOIN dbo.payment_method pm 
				ON pm.payment_method_id = ph.payment_method_id AND pm.payment_method_name = 'Paypal' 

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) check for new sap accounts
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) @sap_account_pending
		

	SELECT @sfdc_template_name = 'sap_create_customer'

	INSERT INTO @sap_create_customer (order_header_id, company_id, order_company_type_id)
	SELECT DISTINCT o.order_header_id, o.company_id, o.order_company_type_id
	FROM #orders o
		LEFT JOIN dbo.sfdc_opportunity_update u 
			ON u.order_header_id = o.order_header_id 
		LEFT JOIN dbo.sfdc_opportunity_update_json j 
			ON j.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
				AND JSON_VALUE(j.sfdc_update_json,'$.company_id') = o.company_id
	WHERE o.sap_account_id IS NULL
		AND j.sfdc_opportunity_update_id IS NULL
	ORDER BY o.order_header_id

	-- 2.2) sap_create_customer
	IF EXISTS (SELECT 1 FROM @sap_create_customer)
		BEGIN

		SELECT @temp_id = 1, @total_ids = MAX(temp_id) FROM @sap_create_customer
			
		WHILE @total_ids >= @temp_id
			BEGIN
			-- print @temp_id

			-- 2.2.1) @company_id and @order_header_id
			SELECT @company_id = company_id, @order_header_id = order_header_id, 
				@order_company_type_id = order_company_type_id
			FROM @sap_create_customer
			WHERE temp_id = @temp_id
			
			IF @order_company_type_id = 3
			BEGIN
				SELECT @resellerpartner = 'z1', @shipto = 'true', @enduser = 'true', @billto = 'true',
				@soldto = 'true', @payer = 'true'
			END
			ELSE 
			BEGIN
				-- 2.2.2) @partner_function_json
				SELECT @shipto = CASE WHEN oc.company_id IS NULL THEN 'false' ELSE 'true' END, 
					@enduser = CASE WHEN oc.company_id IS NULL THEN 'false' ELSE 'true' END,
					@billto = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END,
					@soldto = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END,
					@payer = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END
				FROM dbo.order_company_type t
					LEFT JOIN dbo.order_company oc
							ON oc.order_company_type_id = 1 
								AND oc.order_header_id = @order_header_id 
								AND oc.company_id = @company_id
					LEFT JOIN dbo.order_company oc2
							ON oc2.order_company_type_id = 2 
								AND oc2.order_header_id = @order_header_id 
								AND oc2.company_id = @company_id
				WHERE t.order_company_type_id IN (1,2)
			END
				
			-- 2.2.3) @sfdc_update_json
			SELECT @sfdc_update_json = (SELECT @company_id AS company_id, @resellerpartner AS ResellerPartner, 
											(SELECT DISTINCT cc.customer_id
												FROM dbo.customer_company cc
													INNER JOIN dbo.order_company oc
														ON oc.company_id = cc.company_id 
															AND oc.customer_id = cc.customer_id
												WHERE cc.company_id = @company_id 
												FOR JSON PATH) customers, 
											@billto AS [PartnerFunctions.BillTo],
											@shipto AS [PartnerFunctions.ShipTo],
											@enduser AS [PartnerFunctions.EndUser],
											@soldto AS [PartnerFunctions.SoldTo],
											@payer AS [PartnerFunctions.Payer]
										FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)

			--To check the order already exists with the template:sap_create_customer
			--IF (SELECT COUNT(*) 
			IF NOT EXISTS(SELECT 1 
				FROM dbo.sfdc_opportunity_update u 
					INNER JOIN dbo.sfdc_opportunity_update_json souj
						ON souj.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
							AND JSON_VALUE(souj.sfdc_update_json,'$.company_id') = @company_id 
					INNER JOIN dbo.sfdc_template t 
						ON t.sfdc_template_id = u.sfdc_template_id 
				WHERE u.order_header_id = @order_header_id 
					--AND t.sfdc_template_name = @sfdc_template_name) = 0
					AND t.sfdc_template_name = @sfdc_template_name)
			--AND (SELECT COUNT(*) 
			AND NOT EXISTS(SELECT 1 
				FROM dbo.sfdc_opportunity_update_archive u 
					INNER JOIN dbo.sfdc_opportunity_update_json souj
						ON souj.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
							AND JSON_VALUE(souj.sfdc_update_json,'$.company_id') = @company_id 
					INNER JOIN dbo.sfdc_template t 
						ON t.sfdc_template_id = u.sfdc_template_id 
				WHERE u.order_header_id = @order_head
er_id 
					AND t.sfdc_template_name = @sfdc_template_name 
					--AND u.sfdc_response_code = 'success') = 0
					AND u.sfdc_response_code = 'success')
			BEGIN
				-- 2.2.4) usp_sfdc_insert_sfdc_opportunity_update
				EXEC dbo.usp_sfdc_insert_sfdc_opportunity_update 
					@sfdc_template_name = @sfdc_template_name,
					@order_header_id = @order_header_id,
					@sfdc_update_json = @sfdc_update_json
						
			END

			SELECT @sfdc_update_json = NULL, @company_id = NULL, @order_header_id = NULL, 
				@sfdc_opportunity_update_id = NULL, @resellerpartner = NULL, @billto = NULL, @shipto = NULL, 
				@enduser = NULL, @soldto = NULL, @payer = NULL, @temp_id = @temp_id + 1

			END

		END

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) sap_update_customer
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.0.1) get addresses from sap_account table for order companies
	INSERT INTO @sap_address (company_id, address_1, address_2, city, state, postal_code, country_id, 
		clean_address, clean_city, clean_postal_code)
	SELECT DISTINCT sa.company_id, sa.address_1, sa.address_2, sa.city, sa.state, sa.postal_code, sa.country_id,
		cva.clean_address, cva.clean_city, cva.clean_postal_code
	FROM #orders o
		INNER JOIN dbo.sap_account sa
			ON sa.company_id = o.company_id
		CROSS APPLY dbo.fn_clean_validate_address(sa.address_1, sa.address_2, sa.city, sa.state, sa.postal_code,
			NULL, sa.country_id) cva

	-- 3.0.2) get active address from company_address table for order companies
	;WITH active_address AS (
	SELECT DISTINCT ca.company_id, ca.address_1, ca.address_2, ca.city, ca.state, ca.postal_code, 
		ca.country_id, ROW_NUMBER() OVER(PARTITION BY ca.company_id ORDER BY ca.insert_date DESC) AS row_num
	FROM @sap_address sa
		INNER JOIN dbo.company_address ca
			ON ca.company_id = sa.company_id
	WHERE ca.address_status_id = 1
		AND ca.address_class_id = 1
		AND ca.address_type_id = 1)
	INSERT INTO @current_address (company_id, address_1, address_2, city, state, postal_code, country_id, 
		clean_address, clean_city, clean_postal_code)
	SELECT aa.company_id, aa.address_1, aa.address_2, aa.city, aa.state, aa.postal_code, aa.country_id, 
		cva.clean_address, cva.clean_city, cva.clean_postal_code
	FROM active_address aa
		CROSS APPLY dbo.fn_clean_validate_address(aa.address_1, aa.address_2, aa.city, aa.state, aa.postal_code,
		NULL, aa.country_id) cva
	WHERE aa.row_num = 1

	-- 3.0.3) stage update where address is different
	INSERT INTO @sap_update_customer (order_header_id, company_id, company_name, change_reason)
	SELECT o.order_header_id, sa.company_id, o.company_name, 'address'
	FROM #orders o
		INNER JOIN @sap_address sa 
			ON sa.company_id = o.company_id
		LEFT JOIN @current_address ca 
			ON ca.company_id = sa.company_id
				AND ca.clean_address = sa.clean_address
				AND ca.clean_city = sa.clean_city
				AND ca.clean_postal_code = sa.clean_postal_code
				AND ca.country_id = sa.country_id
	WHERE ca.company_id IS NULL

	-- 3.1) partner functions
	INSERT INTO @sap_update_customer (order_header_id, company_id, company_name, change_reason)
	SELECT DISTINCT o.order_header_id, o.company_id, o.company_name, 'partner_function'
	FROM #orders o
		INNER JOIN dbo.sap_partner_function_order_company_type f
			ON f.order_company_type_id = o.order_company_type_id
		OUTER APPLY dbo.fn_sap_select_partner_function(o.company_id, NULL, f.partner_function_name_german) pf
	WHERE pf.sap_partner_function_id IS NULL
		AND o.sap_account_id IS NOT NULL


	-- 3.2) sap_update_customer

	SELECT @sfdc_template_name = 'sap_update_customer'

	IF EXISTS (SELECT 1 FROM @sap_update_customer)
		BEGIN

		SELECT @temp_id = 1, @total_ids = MAX(temp_id) FROM @sa
p_update_customer

		WHILE @total_ids >= @temp_id
			BEGIN

			-- 3.2.1) @company_id and @order_header_id
			SELECT @company_id = company_id, @order_header_id = order_header_id, 
				@shipto_soldto = CASE WHEN change_reason = 'partner_function' THEN 'T' ELSE 'F' END
			FROM @sap_update_customer
			WHERE temp_id = @temp_id

			SELECT @sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
			FROM dbo.sfdc_opportunity_update u
			INNER JOIN dbo.sfdc_opportunity_update_json j
				ON j.sfdc_opportunity_update_id = u.sfdc_opportunity_update_id
			WHERE JSON_VALUE(j.sfdc_update_json,'$.company_id') = @company_id

			IF @sfdc_opportunity_update_id IS NULL
				BEGIN
				-- 3.2.2) @partner_function_json
				SELECT @shipto = CASE WHEN oc.company_id IS NULL THEN 'false' ELSE 'true' END, 
					@enduser = CASE WHEN oc.company_id IS NULL THEN 'false' ELSE 'true' END,
					@billto = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END,
					@soldto = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END,
					@payer = CASE WHEN oc2.company_id IS NULL THEN 'false' ELSE 'true' END
				FROM dbo.order_company_type t
					LEFT JOIN dbo.order_company oc
						ON oc.order_company_type_id = 1 
							AND oc.order_header_id = @order_header_id 
							AND oc.company_id = @company_id
					LEFT JOIN dbo.order_company oc2
						ON oc2.order_company_type_id = 2 
							AND oc2.order_header_id = @order_header_id 
							AND oc2.company_id = @company_id
				WHERE t.order_company_type_id IN (1,2)
				
				-- 3.2.3) @sfdc_update_json
				SELECT @sfdc_update_json = (SELECT @company_id AS company_id, @shipto_soldto AS ShipTo_SoldTo, 
												(SELECT DISTINCT cc.customer_id
													FROM dbo.customer_company cc
														INNER JOIN dbo.order_company oc
															ON oc.company_id = cc.company_id 
																AND oc.customer_id = cc.customer_id
													WHERE cc.company_id = @company_id 
													FOR JSON PATH) customers, 
												@billto AS [PartnerFunctions.BillTo],
												@shipto AS [PartnerFunctions.ShipTo],
												@enduser AS [PartnerFunctions.EndUser],
												@soldto AS [PartnerFunctions.SoldTo],
												@payer AS [PartnerFunctions.Payer]
											FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)

				-- 3.2.4) customer_service
					
				IF @sfdc_update_json IS NOT NULL
					BEGIN

					--print @sfdc_update_json
					-- 3.2.4.1) @customer_service_type_id
					SELECT @customer_service_type_id = customer_service_type_id
					FROM dbo.customer_service_type
					WHERE customer_service_type_name = 'sap_account_change'

					-- 3.2.4.2) @customer_service_status_id
					SELECT @customer_service_status_id = customer_service_status_id
					FROM dbo.customer_service_status
					WHERE customer_service_status_name = 'Pending'

					-- 3.2.4.3) insert customer_service
					IF NOT EXISTS (SELECT 1 
									FROM dbo.customer_service cs 
										INNER JOIN dbo.customer_service_json csj
											ON csj.customer_service_id = cs.customer_service_id
									WHERE cs.customer_service_type_id = @customer_service_type_id
										AND csj.customer_service_json = @sfdc_update_json)
					BEGIN
						INSERT INTO dbo.customer_service(customer_service_type_id, customer_service_status_id)
						VALUES(@customer_service_type_id, @customer_service_status_id)

						SELECT @customer_service_id = SCOPE_IDENTITY()
					
						INSERT INTO dbo.customer_service_json (customer_service_id, customer_service_json) 
						VALUES (@customer_service_id, @sfdc_update_json)	
					END

					-- 3.2.4.4) usp_sfdc_insert_sfdc_opportunity_update
					EXEC dbo.usp_sfdc_insert_sfdc_opportunity_update 
						@sfdc_template_name = @sfdc_template_name,
						@order_header_id = @order_header_id,
						@sfdc_update_json = @sfdc_update_json
						
					END
				END

			SELECT @sfdc_update_json = NULL, @company_id = NULL, @order_header_id = NULL, 
				@sfdc_
opportunity_update_id = NULL, @billto = NULL, @shipto = NULL, @enduser = NULL, 
				@soldto = NULL, @payer = NULL, @temp_id = @temp_id + 1

			END

		END


	--<< usp_order_load_external_order_batch >>

		DECLARE @orders TABLE (temp_id INT IDENTITY(1,1), order_header_id INT, company_id INT, company_name NVARCHAR(255), 
			company_type_id TINYINT, site_id VARCHAR(20), order_item_id INT, effective_date DATETIME, license_category_id INT, 
			license_attribute_license_value INT)

		DECLARE @order_company TABLE (order_external_load_exception_id INT, order_header_id INT, company_id INT, 
			order_company_type_id TINYINT, customer_id INT)

		DECLARE @order_external_load_exception AS TABLE(order_header_id int,  is_business_Paypal INT)


		-- 4) "Step 4"

		-- 4.1) all references to the SFDC queue use sfdc_template 'external_order' and sfdc_update_type 'create_contract'
		SELECT @sfdc_template_id = st.sfdc_template_id 
		FROM dbo.sfdc_template st 
		WHERE st.sfdc_template_name = 'external_order'

		SELECT @sfdc_update_type_id = sut.sfdc_update_type_id 
		FROM dbo.sfdc_update_type sut 
		WHERE sut.sfdc_update_type_name = 'create_contract'


		-- 4.2) insert failed orders into external order exception in a pending state
		--		these will be excluded from the order list in section 1.3 and then handled in section 2

		INSERT INTO @order_external_load_exception
		(
		    order_header_id,
		    is_business_Paypal
		)
		SELECT DISTINCT 
			a.order_header_id
			, CASE WHEN ap.business_product_line IS NOT NULL AND pm.payment_method_id IS NOT NULL THEN 1 ELSE 0 END 
		FROM dbo.sfdc_opportunity_update_archive a
			INNER JOIN dbo.order_header h
				ON a.order_header_id = h.order_header_id 
					AND h.order_status_id = 1 -- Transaction
			LEFT JOIN dbo.sfdc_opportunity_update_archive a2 -- excluding orders with update already successful
				ON a.order_header_id = a2.order_header_id 
					AND a.sfdc_template_id = @sfdc_template_id
					AND a.sfdc_update_type_id = @sfdc_update_type_id 
					AND a2.sfdc_response_code = 'Success'
			LEFT JOIN dbo.sfdc_opportunity_update u -- excluding orders with updates not yet processed
				ON a.order_header_id = u.order_header_id
			LEFT JOIN dbo.order_external_load_exception e -- excluding orders that already have pending order_external_load_exception
				ON a.order_header_id = e.order_header_id 
					AND e.exception_status = 'pending'
			LEFT JOIN dbo.order_item oi 
				ON oi.order_header_id = h.order_header_id
			LEFT JOIN dbo.product p 
				ON oi.product_id = p.product_id   
			LEFT JOIN dbo.product_line_product plp 
				ON plp.product_id = p.product_id
			LEFT JOIN @APP_CONFIG ap 
				ON ap.business_product_line = plp.product_line_id
			LEFT JOIN dbo.order_payment_header oph 
				ON h.order_header_id = oph.order_header_id
			LEFT JOIN dbo.payment_header ph 
				ON ph.payment_header_id = oph.payment_header_id
			LEFT JOIN dbo.payment_method pm  --excluding business paypal orders
				ON pm.payment_method_id = ph.payment_method_id  
					AND pm.payment_method_name = 'Paypal'   
			WHERE a.sfdc_template_id = @sfdc_template_id 
				AND a.sfdc_update_type_id = @sfdc_update_type_id 
				AND a.sfdc_response_code <> 'Success' 
				AND a2.sfdc_opportunity_update_archive_id IS NULL 
				AND e.order_external_load_exception_id IS NULL 
				AND u.order_header_id IS NULL
				AND h.order_header_id = ISNULL(@order_header_id , h.order_header_id) -- specific order_header_id
		ORDER BY a.order_header_id DESC

		INSERT INTO dbo.order_external_load_exception (
			order_header_id
			, exception_status
			, insert_date
		)
		SELECT order_header_id, 
			'pending'
			, GETDATE()  
			FROM @order_external_load_exception 
			WHERE is_business_Paypal = 0

		-- 4.3) procedure will get all orders from previous month if no value is passed in
		--		this is consistent with how the job was executed before

		INSERT INTO @orders (
			order_header_id
			
, company_id
			, company_name
			, company_type_id
			, site_id
			, order_item_id
			, effective_date
			, license_category_id
		)
		SELECT DISTINCT 
			co.order_header_id
			, cp.company_id
			, cp.company_name
			, cp.company_type_id
			, h.site_id
			, i.order_item_id
			, i.effective_date
			, plc.license_category_id
		FROM dbo.customer_order co
			INNER JOIN dbo.order_company oc
				ON co.order_header_id = oc.order_header_id 
					AND oc.order_company_type_id = 2
			INNER JOIN dbo.company cp
				ON oc.company_id = cp.company_id
			INNER JOIN dbo.order_header h
				ON co.order_header_id = h.order_header_id
			INNER JOIN dbo.order_item i
				ON co.order_header_id = i.order_header_id
			INNER JOIN dbo.product_license_category plc
				ON i.product_id = plc.product_id
			INNER JOIN dbo.product p
				ON i.product_id = p.product_id
			INNER JOIN dbo.order_payment_header op
				ON h.order_header_id = op.order_header_id
			INNER JOIN dbo.payment_header ph
				ON op.payment_header_id = ph.payment_header_id
			INNER JOIN dbo.payment_merchant m 
				ON ph.payment_merchant_id = m.payment_merchant_id
			LEFT JOIN dbo.sfdc_opportunity_update_archive a WITH (NOLOCK) -- excluding successful 'create contract' sfdc updates for order
				ON a.order_header_id = h.order_header_id 
					AND a.sfdc_response_code <> 'Failure' 
					AND a.sfdc_update_type_id = @sfdc_update_type_id
			LEFT JOIN dbo.sfdc_opportunity_update su WITH (NOLOCK) -- excluding all orders with pending sfdc update
				ON su.order_header_id = h.order_header_id
			LEFT JOIN order_external_load_exception le -- excluding external order exceptions created in section 1.2
				ON co.order_header_id = le.order_header_id 
					AND le.exception_status = 'pending'
			LEFT JOIN dbo.partner_license pl -- excluding unapproved partner license records
				ON co.order_header_id = pl.order_header_id 
					AND pl.partner_license_status_id <> 2 -- approved
			LEFT JOIN @APP_CONFIG ap ON ap.business_product_line = p.product_family_id -- business product line
			LEFT JOIN dbo.payment_method pm  -- excluding business paypal orders 
				ON pm.payment_method_id = ph.payment_method_id 
					AND pm.payment_method_name = 'Paypal' 
		WHERE co.customer_type_id = 1 -- Billing
			--AND p.product_family_id IN (55, 300) -- business
			AND ap.business_product_line IS NOT NULL --business
			AND h.order_status_id = 1 -- Transaction
			AND h.site_id IN ('WRCART', 'CSI', 'AUTORENEWAL')
			AND h.insert_date >= @start_date
			AND m.merchant_id <> 'cleverbridge'
			AND a.sfdc_opportunity_update_archive_id IS NULL 
			AND su.sfdc_opportunity_update_id IS NULL
			AND le.order_external_load_exception_id IS NULL
			AND pl.partner_license_id IS NULL
			AND pm.payment_method_id IS null
			AND h.order_header_id = ISNULL(@order_header_id , h.order_header_id) -- specific order_header_id
		ORDER BY co.order_header_id

		-- 4.3.1) remove records from table above with pending customer_service records
		DELETE o
		FROM dbo.customer_service cs 
			INNER JOIN dbo.customer_service_json csj			
				ON cs.customer_service_id = csj.customer_service_id
			INNER JOIN dbo.customer_service_status css
				ON css.customer_service_status_id = cs.customer_service_status_id
					AND css.customer_service_status_name = 'pending'
			INNER JOIN @orders o 
				ON JSON_VALUE(csj.customer_service_json, '$.company_id') = o.company_id

		-- 4.4) set license_attribute_license_value for each order
		UPDATE o
			SET o.license_attribute_license_value = av.license_attribute_license_value
		FROM @orders o
			INNER JOIN dbo.order_item_license il
				ON o.order_item_id = il.order_item_id
			INNER JOIN dbo.license l
				ON il.license_id = l.license_id
			CROSS APPLY dbo.fn_license_select_effective_object_table(il.license_id, o.effective_date) eo
			INNER JOIN dbo.license_attribute_license_value av
				ON eo.effective_value = av.license_attribute_license_value
		WHERE il.lic
ense_id = eo.license_id 
			AND eo.license_category_id = o.license_category_id 
			AND eo.effective_object_id = 2 --license_attribute_license_value

		-- 4.5) process batch, whatever that means
		--		I left the original debug code in place in case it's useful in the future

		-- 4.5.1) set initial loop variables and begin loop
		SELECT @temp_id = 1, @total_ids = MAX(temp_id) FROM @orders

		WHILE @total_ids >= @temp_id
			BEGIN
		
				-- 4.5.2) select parameters
				SELECT 
					@order_header_id = order_header_id
					, @site_id = site_id
					, @company_type_id = company_type_id
					, @product_line_id = 300
					, @license_attribute_license_value = license_attribute_license_value
					, @company_id = company_id
				FROM @orders WHERE temp_id = @temp_id

				PRINT @temp_id 
				PRINT @order_header_id
				PRINT 'no exception, load order'
	
				-- 4.5.3) insert order_extension where one doesn't already exist for order and extension type
				INSERT INTO dbo.order_extension (
					order_header_id
					, order_extension_type_id
					, order_extension_value
				)
				SELECT 
					@order_header_id
					, f.order_extension_type_id
					, f.order_extension_value
				FROM dbo.fn_order_select_default_order_extension(@site_id,@product_line_id,@company_type_id
					, @license_attribute_license_value) f
				LEFT JOIN dbo.order_extension e
					ON f.order_extension_type_id = e.order_extension_type_id 
						AND e.order_header_id = @order_header_id
				WHERE e.order_extension_id IS NULL
	
				-- 4.5.4) insert cybs_subscription records
				--			this may need to be changed for paymentech compatibility

				-- 4.5.4.1) select existing cybs_subscription subscription record
				SELECT @cybs_subscription_id = s.cybs_subscription_id
				FROM dbo.order_payment_header op
				INNER JOIN dbo.payment_header h
					ON op.payment_header_id = h.payment_header_id
				INNER JOIN dbo.payment_subscription_credit_card cc
					ON op.payment_header_id = cc.payment_header_id
				INNER JOIN dbo.payment_account pa
					ON h.payment_header_id = pa.payment_header_id
				INNER JOIN dbo.cybs_subscription s
					ON cc.credit_card_subscription_id = s.credit_card_subscription_id
				WHERE op.order_header_id = @order_header_id

				-- 4.5.4.2) attempt to insert new record if one doesn't exist
				IF @@rowcount = 0
					BEGIN
						INSERT INTO dbo.cybs_subscription (credit_card_subscription_id, payment_merchant_id, insert_date, account_number
							, expiration_month, expiration_year, card_type_id)
						SELECT cc.credit_card_subscription_id, h.payment_merchant_id, GETDATE(), RIGHT(pa.account_number,4)
							, pa.expiration_month, pa.expiration_year, pa.card_type_id
						FROM dbo.order_payment_header op
							INNER JOIN dbo.payment_header h
								ON op.payment_header_id = h.payment_header_id
							INNER JOIN dbo.payment_subscription_credit_card cc
								ON op.payment_header_id = cc.payment_header_id
							INNER JOIN dbo.payment_account pa
								ON h.payment_header_id = pa.payment_header_id
							LEFT JOIN dbo.cybs_subscription s
								ON cc.credit_card_subscription_id = s.credit_card_subscription_id
						WHERE op.order_header_id = @order_header_id 
							AND s.cybs_subscription_id IS NULL

						SELECT @cybs_subscription_id = SCOPE_IDENTITY()
					END

				-- 4.5.4.3) insert cybs_subscription_customer record if cybs_subscription exists but customer does not
				IF @cybs_subscription_id IS NOT NULL
					BEGIN
						INSERT INTO dbo.cybs_subscription_customer (cybs_subscription_id, customer_id, company_id, insert_date)
						SELECT @cybs_subscription_id, oc.customer_id, oc.company_id, GETDATE()
						FROM dbo.order_company oc
							LEFT JOIN dbo.cybs_subscription_customer cs
								ON oc.company_id = cs.company_id 
									AND oc.customer_id = cs.customer_id 
									AND cs.cybs_subscription_id = @cybs_subscription_id
						WHERE oc.order_company_type_id = 2 -- bill_
to_account
							AND oc.order_header_id = @order_header_id 
							AND cs.cybs_subscription_customer_id IS NULL
					END
				
				-- 4.5.5) insert into sfdc queue if criteria are met
				--			this logic is pretty wonky and already seems to exist in section 1.3 but I'm leaving it alone at this stage
				--IF (SELECT COUNT(*) 
				IF NOT EXISTS(SELECT 1 
					FROM dbo.sfdc_opportunity_update_archive 
					WHERE order_header_id = @order_header_id 
						AND sfdc_template_id = @sfdc_template_id
						AND sfdc_update_type_id = @sfdc_update_type_id
						--AND sfdc_response_code = 'success') = 0
						AND sfdc_response_code = 'success') 
						-- this criteria should already be met by logic in section 1.3
					--AND (SELECT COUNT(*) 
					AND NOT EXISTS(SELECT 1 
						FROM dbo.sfdc_opportunity_update 
						WHERE order_header_id = @order_header_id 
							AND sfdc_template_id = @sfdc_template_id 
							--AND sfdc_update_type_id = @sfdc_update_type_id) = 0
							AND sfdc_update_type_id = @sfdc_update_type_id)
						-- this criteria should also already be met by logic in section 1.3
					--AND (SELECT COUNT(*) 
					AND EXISTS(SELECT 1 
						FROM dbo.order_company 
						--WHERE order_header_id = @order_header_id) > 0
						WHERE order_header_id = @order_header_id)
						-- this criteria should already be met by inner join to order_company in section 1.3
					--AND (SELECT COUNT(*) 
					AND EXISTS(SELECT 1 
						FROM dbo.sap_account 
						--WHERE company_id = @company_id) > 0
						WHERE company_id = @company_id) 
						-- this basically means there is a record of the company in sap_account
						-- this isn't yet met in section 1.3 but it could be added with an inner join
						-- the only reason we *would not* do that is if there are cases of external orders without sap companies
					BEGIN
						INSERT INTO dbo.sfdc_opportunity_update (order_header_id, sfdc_template_id, sfdc_update_type_id,process_date) 
						VALUES(@order_header_id, @sfdc_template_id, @sfdc_update_type_id, GETDATE())
					END
				ELSE
					BEGIN
						--select 'order already interfaced' as message
						PRINT 'order already interfaced'
					END

				-- 4.5.6) null parameters 
				SELECT @cybs_subscription_id = NULL, @order_header_id = NULL, @site_id = NULL, @company_type_id = NULL
					, @company_id = NULL, @license_attribute_license_value = NULL, @cybs_subscription_id = NULL

				SELECT @temp_id = @temp_id + 1
		END


		-- 5) "Step 5"

		-- 5.1) mark cleverbridge orders as resolved
		--		I'm not actually sure why those were added to the exception table in the first place if they're being resolved
		--		without being processed
		UPDATE e 
			SET exception_status = 'resolved', resolved_date = h.insert_date
		FROM dbo.order_external_load_exception e
			INNER JOIN dbo.order_header h 
				ON e.order_header_id = h.order_header_id
		WHERE e.exception_status = 'pending' AND h.site_id = 'CBCART'

		-- 5.2) mark orders with a successful update as resolved
		--		these should already have been excluded in section 4.2 from being added to the exception queue
		UPDATE e 
			SET exception_status = 'resolved', e.resolved_date = a.archive_date
		FROM dbo.order_external_load_exception e
			INNER JOIN dbo.order_header h 
				ON e.order_header_id = h.order_header_id
			INNER JOIN dbo.sfdc_opportunity_update_archive a
				ON e.order_header_id = a.order_header_id 
					AND a.sfdc_update_type_id = @sfdc_update_type_id 
					AND a.sfdc_response_code = 'Success'
		WHERE e.exception_status = 'pending' 

		-- 5.3) select pending order_external_load_exception records inserted in section 4.2
		--		because this select includes some additional criteria not used in section 4.2, some pending records may not be
		--		processed by this (or potentially any other) process
		INSERT INTO @order_company (order_external_load_exception_id, order_header_id, company_id, order_company_type_id
			, customer_id)
		SE
LECT 
			e.order_external_load_exception_id, co.order_header_id, cc.company_id, t.order_company_type_id, cc.customer_id
		FROM dbo.order_external_load_exception e
			INNER JOIN dbo.order_header h
				ON e.order_header_id = h.order_header_id
			INNER JOIN dbo.vendor_order v
				ON h.vendor_order_id = v.vendor_order_id
			INNER JOIN dbo.customer_order co
				ON h.order_header_id = co.order_header_id 
					AND co.customer_type_id = 1 -- Billing
			INNER JOIN dbo.customer_email ce
				ON co.customer_id = ce.customer_id 
					AND ce.email_status_id = 1 -- active
			INNER JOIN dbo.order_company_type t 
				ON t.order_company_type_id IN (1,2,4) -- account, bill_to_account, distributor_account (excluding reseller_partner_account)
			LEFT JOIN dbo.partner_order po 
				ON h.order_header_id = po.order_header_id
				-- this join does not appear to be doing anything because it's neither excluding NTTCommunications in the WHERE
				-- clause not using any value from the partner_order table. this is probably a mistake and my guess is that 
				-- NTTCommunications should be an exclusion criteria
			LEFT JOIN dbo.customer_company cc
				ON ce.customer_id = cc.customer_id
			LEFT JOIN dbo.order_company oc
				ON h.order_header_id = oc.order_header_id 
					AND oc.order_company_type_id = t.order_company_type_id
		WHERE e.exception_status = 'pending' 
			AND e.order_header_id NOT IN (23610603, 23605990) 
			AND (po.partner_id IN (7943)) -- NTTCommunications
			AND oc.order_company_id IS NULL
		ORDER BY e.order_external_load_exception_id, t.order_company_type_id

		-- 5.2) proceed if orders are found
		IF @@rowcount > 0
			BEGIN 

				-- 2.3) insert order_company records
				INSERT INTO dbo.order_company (order_header_id, company_id, order_company_type_id, customer_id)
				SELECT order_header_id, company_id, order_company_type_id, customer_id
				FROM @order_company
				ORDER BY order_header_id, order_company_type_id

				-- 2.4) update status of exceptions to 'resolved'
				UPDATE e
				SET e.exception_status = 'resolved', resolved_date = GETDATE() 
				FROM @order_company oc
					INNER JOIN dbo.order_external_load_exception e
						ON oc.order_external_load_exception_id = e.order_external_load_exception_id
				WHERE e.exception_status = 'pending'

			END

		-- 6) "Step 6: Kaseya Canada assignment"

		-- 6.1) declare table variable with schema that matches the output of usp_order_select_external_orders_legacy
		DECLARE @orders_kaseya TABLE (order_header_id INT, vendor_order_date DATE, vendor_order_code VARCHAR(100), partner_id INT
			, partner_name NVARCHAR(255), company_id INT, company_name NVARCHAR(255), customer_email VARCHAR(100)
			, site_id VARCHAR(20), license_id INT, keycode VARCHAR(40), license_attribute_license_value INT
			, license_attribute_license_value_description VARCHAR(100))

		-- 6.2) populate table with usp_order_select_external_orders_legacy (previously usp_order_select_external_orders but that proc has other uses now)
		INSERT INTO @orders_kaseya (order_header_id, vendor_order_date, vendor_order_code, partner_id, partner_name, company_id, company_name
			, customer_email, site_id, license_id, keycode, license_attribute_license_value
			, license_attribute_license_value_description)
		EXECUTE dbo.usp_order_select_external_orders @partner_id = 5582
		

		-- 6.3) stage order headers to be updated
		--		these are Kaseya orders that have their order_company address in Canada
		DECLARE @orders_to_update TABLE (temp_id INT IDENTITY(1, 1), order_header_id INT)

		INSERT INTO @orders_to_update (order_header_id)
		SELECT DISTINCT o.order_header_id
		FROM @orders_kaseya o
			INNER JOIN dbo.order_company oc
				ON oc.order_header_id = o.order_header_id
			INNER JOIN dbo.company_address ca
				ON ca.company_id = o.company_id
		WHERE ca.address_class_id = 1 -- primary
			AND ca.address_status_id = 1 -- active
			AND ca.country_id = 39 -- Canada
			AND oc.ord
er_company_type_id = 2 -- bill_to_account
			AND oc.company_id <> 134802 -- Kaseya Canada

		-- 6.4) set initial loop variables and begin loop
		SELECT @temp_id = 1, @total_ids = MAX(temp_id)FROM @orders_to_update

		WHILE @total_ids >= @temp_id
			BEGIN
				SELECT @order_header_id = order_header_id
				FROM @orders_to_update
				WHERE temp_id = @temp_id

				-- 6.4.1) insert an audit record for the order_company record we're about to update
				INSERT INTO dbo.order_company_audit (order_company_id, order_header_id, company_id, order_company_type_id, insert_date
					, customer_id, audit_date)
				SELECT order_company_id, order_header_id, company_id, order_company_type_id, insert_date, customer_id, GETDATE()
				FROM dbo.order_company oc
				WHERE oc.order_header_id = @order_header_id

				-- 6.4.2) update the order_company record to Kaseya Canada
				UPDATE oc
					SET oc.company_id = 134802 -- Kaseya Canada
					, oc.customer_id = 34243653 -- Accounts Payable (for Kaseya Canada)
				FROM dbo.order_company oc
				WHERE oc.order_header_id = @order_header_id 
					AND oc.company_id = 14088 -- Kaseya Corp

				SELECT @temp_id = @temp_id + 1
			END

		-- 7) "Step 7: Arnold test order disable"

		-- 7.1) update status on all Arnold orders in order_external_load_exception
		UPDATE e
			SET e.exception_status = 'test_order', e.resolved_date = GETDATE()
		FROM dbo.order_external_load_exception e
			INNER JOIN dbo.partner_order po
				ON po.order_header_id = e.order_header_id
		WHERE po.partner_id = 9275 AND e.exception_status <> 'test_order'

		-- 7.2) do a bunch of weird updates the spirit of which seem to basically disable test keys
		--		this eventually needs to be refactored since updating these license tables directly is bad news bears
		UPDATE l
			SET l.license_status_id = 2, l.customer_id = NULL, l.modified_date = @modified_date, l.modified_by = 'test_key_disable'
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 1

		UPDATE cl
			SET cl.end_date = @modified_date, cl.last_modified_date = @modified_date, cl.last_modified_by = 'test_key_disable'
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
			INNER JOIN dbo.license_category_license cl
				ON cl.license_id = l.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 2
			  AND cl.end_date > @modified_date

		UPDATE cl
			SET cl.end_date = @modified_date, cl.modified_date = @modified_date, cl.modified_by = 'test_key_disable'
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
			INNER JOIN dbo.license_seat cl
				ON cl.license_id = l.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 2
			  AND cl.end_date > @modified_date

		UPDATE cl
			SET cl.capability_expiration_date = @modified_date, cl.modified_date = @modified_date, cl.modified_by = 'test_key_disable'
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
			INNER JOIN dbo.license_capability cl
				ON cl.license_id = l.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 2
			  AND cl.capability_expiration_date > @modified_date

		UPDATE cl
			SET cl.end_date = @modified_date, cl.last_modified_
date = @modified_date, cl.last_modified_by = 'test_key_disable'
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
			INNER JOIN dbo.license_module_license cl
				ON cl.license_id = l.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 2
			  AND cl.end_date > @modified_date

		UPDATE cl
			SET cl.license_end_date = @modified_date, cl.modified_date = @modified_date
		FROM dbo.partner_license pl
			INNER JOIN dbo.license l
				ON l.license_id = pl.license_id
			INNER JOIN dbo.license_contract cl
				ON cl.license_id = l.license_id
		WHERE pl.partner_id = 9275
			  AND pl.partner_license_status_id = 2
			  AND (pl.start_date <= @modified_date AND (pl.end_date IS NULL OR pl.end_date > pl.start_date))
			  AND l.license_status_id = 2
			  AND cl.license_end_date > @modified_date
			  AND cl.license_contract_status_id = 1

	--<< usp_order_load_external_order_batch >>


	END TRY

	BEGIN CATCH

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_addresses]
-- =============================================================================

CREATE procedure [dbo].[usp_order_select_addresses] 

(@order_header_id int, @vendor_id int = null)

as

	/*	
	DATE		AUTHOR		REMARKS
	2006-10-03	TBlazek		Initial creation.
	2013-07-16	acoffel		refactor for new data structure 
	2020-08-20	abelenkiy	Streamlined logic and removed unnecessary joins	

	DESCRIPTION
	Return a result set for customer addresses assoicated with an order to the PHP code
	*/
	begin
		set nocount on;

		select ca.customer_address_id, ca.address_type_id, ca.address_1, ca.address_2, ca.address_3, ca.city, ca.state, ca.postal_code, ca.country_id
			 , s.state_iso3, ca.address_status_id, ca.customer_id, co.customer_type_id
		from customer_address ca
			inner join customer_order co
				on ca.customer_id = co.customer_id
			inner join order_header oh
				on co.order_header_id = oh.order_header_id
			left join customer_email e
				on ca.customer_id = e.customer_id and e.email_status_id = 1
			left join customer_company cc
				on ca.customer_id = cc.customer_id
			left join lu_countries lc
				on lc.country_id = ca.country_id
			left join lu_states s
				on ca.state = s.state_id and s.iso2 = lc.iso
		where co.order_header_id = @order_header_id;
	end;

GO
