CREATE PROCEDURE [dbo].[usp_order_select_order_extension]

(
	@order_header_id int,
	@order_extension_type_name varchar(50) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2016-07-19	esmart		Initial creation.

	DESCRIPTION
	select order_extension
*/

AS
	set nocount on				

	declare	@license_id int,
			@license_key_id int,
			@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) 
	select e.order_extension_id, e.order_header_id, e.order_extension_type_id, t.order_extension_type_name, t.order_extension_type_description, e.order_extension_value, e.insert_date
	from order_extension e
