		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_order_external_load_exception]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_select_order_external_load_exception]

(
	@start_date datetime =  null,
	@site_id varchar(65) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2020-11-03	esmart		Initial creation.

	DESCRIPTION
	select pending 
*/

AS

	declare @response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update partner_billing
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @start_date is null 
		begin
		select @start_date = dateadd(mm,-1,getdate())
		end

	select	e.order_external_load_exception_id, 
			e.order_header_id, 
			e.exception_status, 
			case when exists (select oc.order_company_id from order_company oc where oc.order_header_id = e.order_header_id) then 'complete' else 'pending' end as order_company_status,
			e.insert_date, 
			e.resolved_date, 
			e.exception_json,
			v.vendor_order_code, 
			h.site_id, 
			case when po.partner_id is null then ce.customer_id else ce2.customer_id end as customer_id,
			case when po.partner_id is null then ce.customer_email else ce2.customer_email end as customer_email,
			case when po.partner_id is null then ce.email_domain else ce2.email_domain end as email_domain,
			case when po.partner_id is null then cc.company_name else cc2.company_name end as company_name,
			case when po.partner_id is null then cc.company_id else cc2.company_id end as company_id, 
			po.partner_id, 
			p.partner_name,
			oo.salesforce_opportunity_id,
			(select top 1 sfdc_response_message from sfdc_opportunity_update_failure where order_header_id = e.order_header_id order by sfdc_opportunity_update_failure_id desc) as sfdc_response_message
		from order_external_load_exception e
		inner join order_header h
			on e.order_header_id = h.order_header_id
		inner join order_payment_header ph 
			on ph.order_header_id = h.order_header_id
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join customer_order co
			on h.order_header_id = co.order_header_id and co.customer_type_id = 1
		inner join customer_order co2
			on h.order_header_id = co2.order_header_id and co2.customer_type_id = 2
		inner join customer_email ce
			on co.customer_id = ce.customer_id and ce.email_status_id = 1
		inner join customer_email ce2
			on co2.customer_id = ce2.customer_id and ce2.email_status_id = 1
		left join payment_subscription_paypal pp
			on pp.payment_header_id = ph.payment_header_id
		left join partner_order po
			on h.order_header_id = po.order_header_id
		left join partner p
			on po.partner_id = p.partner_id
		left join customer_company cc
			on ce.customer_id = cc.customer_id
		left join customer_company cc2
			on ce2.customer_id = cc2.customer_id
		left join order_opportunity oo
			on h.order_header_id = oo.order_header_id
		left join sfdc_opportunity_update_archive ua
			on e.order_header_id = ua.order_header_id and ua.sfdc_template_id = 17 and ua.sfdc_update_type_id = 115 and ua.sfdc_response_code = 'SUCCESS'	
		where h.insert_date > @start_date and e.exception_status = 'pending' 
			and h.site_id = case when @site_id is null then h.site_id else @site_id end
			and ua.sfdc_opportunity_update_archive_id is null
			and pp.payment_subscription_paypal_id is null
			and (p.partner_id is null or p.partner_id <> 9275)
		order by e.order_external_load_exception_id


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select fa
iled'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_order_header_by_opp]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_select_order_header_by_opp]

(
	@sfdc_opportunity_id varchar(20),
	@correct_keycode varchar(40)
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2018-01-29		acoffel		Initial creation.
		

	DESCRIPTION
	attribute order and opportunity to correct license
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100),
			@product_id int,
			@product_type_id int,
			@capability_type_id int


	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  verify product is compatible with license
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--1.1) product_type_id
		select @product_type_id = pt.product_type_id,
				@product_id = p.product_id
		from product p
		inner join product_type pt
			on p.product_type_id = pt.product_type_id
		inner join order_item i
			ON p.product_id = i.product_id
		inner join order_opportunity oo
			on i.order_header_id = oo.order_header_id
		where oo.salesforce_opportunity_id = @sfdc_opportunity_id

		--1.2) check for order info
		if @product_id is null
			begin
			 select error_message_text = 'product info not found' 
             return
             end

		--1.3) license_type
		select @capability_type_id = c.capability_type_id
		from license l
		inner join license_capability c
			on l.license_id = c.license_id
		inner join license_category_license cl
			on c.license_id = cl.license_id
		inner join dbo.license_category lc
			on cl.license_category_id = lc.license_category_id and c.capability_id = lc.base_capability_id
		where l.keycode = @correct_keycode

		--1.2) check for order info
		if @capability_type_id is null
			begin
			 select error_message_text = 'license info not found' 
             return
             end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  get order_header_id 
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		--2.1) check product and capability compatibilty
		if (@product_type_id = 1 and @capability_type_id = 2) or (@product_type_id = 2 and @capability_type_id = 1) or @product_type_id = 3
			begin
				select order_header_id = order_header_id from order_opportunity where salesforce_opportunity_id = @sfdc_opportunity_id
			end
			else 
			begin 
				select error_message_text = 'product not compatible with license'
			end
            

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_order_item_summary]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_order_select_order_item_summary]

(
	
		@order_header_id int	
		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-08-23	esmart		Initial creation.
	2010-11-08	esmart		Add support for PS licenses
	2013-05-21	esmart		Add product_line_cart_type
	2013-11-13	esmart		Add bundle description details

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @order_item_summary table(	item_bundle_id int, 
										product_id int,
										product_description varchar(100),
										product_family_id int,
										product_family_description varchar(50),
										license_keycode_type_id int,
										license_category_name varchar(10),
										product_line_id int,
										years float,
										seats int,
										storage_gb int,
										quantity int,
										unit_price money,
										tax money,
										item_total money,
										license_id int,
										keycode varchar(40),
										keycode_alias varchar(40),
										product_type_id int,
										end_date datetime)
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) items
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		insert into @order_item_summary (item_bundle_id, product_id, product_description, product_family_id, product_family_description, license_keycode_type_id, license_category_name, product_line_id, keycode, keycode_alias, product_type_id, years, seats, storage_gb, quantity, unit_price, tax, item_total, end_date)
		select	i.item_bundle_id,
				product_id = il.license_id, 
				product_description = isnull(lc.license_category_description,f.product_family_description), 
				p.product_family_id, f.product_family_description, p.license_keycode_type_id,lc.license_category_name, pl.product_line_id, l.keycode, ka.keycode_alias, product_type_id = min(p.product_type_id), years = max(y.years), 
				seats = case when pl.product_line_id in (55,300) then max(i.quantity) else max(s.seats) end, 
				storage_gb = max(ps.storage_gb), quantity = max(i.quantity), unit_price = sum(i.unit_price), tax = sum(i.tax), item_total = sum(i.item_total), end_date = max(end_date)
		from order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		inner join order_item_license il with (nolock)
			on i.order_item_id = il.order_item_id
		inner join license l with (nolock)
			on il.license_id = l.license_id
		left join license_keycode_alias ka with (nolock)
			on il.license_id = ka.license_id
		inner join license_category_license lcl with (nolock)
			on il.license_id = lcl.license_id
		inner join license_category lc with (nolock)
			on lcl.license_category_id = lc.license_category_id
		inner join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage
 ps with (nolock)
			on i.product_id = ps.product_id
		where i.order_header_id = @order_header_id
		group by i.item_bundle_id, il.license_id, p.product_family_id, f.product_family_description, p.license_keycode_type_id, lc.license_category_name, pl.product_line_id, lc.license_category_description, l.keycode, ka.keycode_alias
		
		insert into @order_item_summary (item_bundle_id, product_id, product_description, product_family_id, product_family_description, license_keycode_type_id, keycode, product_type_id, years, seats, storage_gb, quantity, unit_price, tax, item_total)
		select i.item_bundle_id, i.product_id, p.product_description, p.product_family_id, f.product_family_description, p.license_keycode_type_id, l.keycode, p.product_type_id, y.years, s.seats, ps.storage_gb, i.quantity, i.unit_price, i.tax, i.item_total
		from order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		inner join order_item_license il with (nolock)
			on i.order_item_id = il.order_item_id
		inner join license l with (nolock)
			on il.license_id = l.license_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		where i.order_header_id = @order_header_id and f.product_family_id in (9,17,21,29)

		insert into @order_item_summary (item_bundle_id, product_id, product_description, product_family_id, product_family_description, license_keycode_type_id, product_type_id, years, seats, storage_gb, quantity, unit_price, tax, item_total)
		select i.item_bundle_id, i.product_id, p.product_description, p.product_family_id, f.product_family_description, p.license_keycode_type_id, p.product_type_id, y.years, s.seats, ps.storage_gb, i.quantity, i.unit_price, i.tax, i.item_total
		from order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join order_item_license il with (nolock)
			on i.order_item_id = il.order_item_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		where i.order_header_id = @order_header_id  and il.order_item_license_id is null
		
		-- 2.1) get bundle details
		declare @cart_discount_bundle_description varchar(200), @cart_discount_bundle_details_list varchar(1000), @license_distribution_method_id int, @license_distribution_method_code varchar(4)

		select @cart_discount_bundle_description = cart_discount_bundle_description, @cart_discount_bundle_details_list = cart_discount_bundle_details_list
		from cart_discount_bundle b
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join order_message m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.order_header_id = @order_header_id

		select @license_distribution_method_id = dm.license_distribution_method_id, @license_distribution_method_code = dm.license_distribution_method_code
		from cart_discount_license_distribution_method b
		inner join license_distribution_method dm
			on b.license_distribution_method_id = dm.license_distribution_method_id
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join order_message m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.order_header_id = @order_header_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return results
	
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		select product_id, product_description, product_family_id, product_family_description, license_keycode_type_id, license_category_name, keycode, keycode_alias, t.product_type_description, years, seats, storage_gb, quantity, unit_price, tax, item_total, end_date, o.product_line_id, pl.product_line_cart_type
				,
				cart_discount_bundle_description = case when o.item_bundle_id = 1 then @cart_discount_bundle_description else null end, 
				cart_discount_bundle_details_list = case when o.item_bundle_id = 1 then @cart_discount_bundle_details_list else null end,
				license_distribution_method_id = case when o.item_bundle_id = 1 then @license_distribution_method_id else null end, 
				license_distribution_method_code = case when o.item_bundle_id = 1 then @license_distribution_method_code else null end
		from @order_item_summary o
		inner join product_type t
			on o.product_type_id = t.product_type_id
		left join product_line pl
			on o.product_line_id = pl.product_line_id
		order by o.item_bundle_id


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select product failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_order_items]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_order_select_order_items]

(
		@order_header_id INT		
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-16	esmart		Initial creation.
	2013-05-24	acoffel		added seats and years
	2014-03-22	esmart		Add bulk load
	2016-05-11	esmart		Add product.root_product_id and capability_expiration_date
	2016-12-15	esmart		Set order_item.capability_expiration_date based on site to support differences in SFDC and the other order sources
	2017-06-29	esmart		Add default product type for module products when calculated type is null
	2018-01-31	acoffel		Opp reload
	2018-09-04	cnovac		Added search results for WIFI
	2019-11-13	esmart		Add product_extension data
	2020-07-20	wbarton		Adding support for an array of multiple vault_ids and datacenters from fn_order_select_order_item_json
	2020-08-10	esmart		fn_order_select_order_item_json
	2020-10-14	cnovac		added logic for storage_gb
	2020-12-21	esmart		Remove objects and add license_attribute_license_value
	2021-02-12	wbarton		Adding item_bundle_id and item_hierarchy_id to the select for PartnerCart API
	2022-01-06	gblandford	SMCI-6215 - Add retention_term and retention_model_type_id to results (from fn_order_select_order_item_json)
	2023-11-09	jberry		ECOM-2795 - Add a sort on order_item line_item field to return the result set in the proper order
	2024-01-22	pachanta	ECOM-2679 - Enhance the Partner Cart API provisioning response.
	2025-10-14	jberry		US-5004939 - added @order_item_storage variable table to convert storage_gb to TBs.  Allows CSI to properly display storage for the order.

	DESCRIPTION

*/

AS
SET NOCOUNT ON

BEGIN TRY

	DECLARE @response_code INT,
			@message VARCHAR(100)

	DECLARE @order_item_storage TABLE
	(
		order_item_id INT,
		storage_gb INT,
		actual_storage_quantity DECIMAL(12, 5)
	);

	--get storage for capacity licenses
	INSERT INTO @order_item_storage
	(
	    order_item_id,
	    storage_gb,
		actual_storage_quantity
	)
	SELECT oi.order_item_id,
		   coi.storage_gb,
		   CASE
			   WHEN coi.storage_gb >= 1024 THEN
				   CONVERT(DECIMAL(12, 5), CONVERT(DECIMAL(12, 5), coi.storage_gb) / 1024)
			   ELSE
				   1
		   END
	FROM dbo.cart_order_item coi
		INNER JOIN dbo.cart_order co
			ON co.cart_order_id = coi.cart_order_id
		INNER JOIN dbo.vendor_order vo
			ON vo.vendor_order_code = co.vendor_order_code
		INNER JOIN dbo.order_header oh
			ON oh.vendor_order_id = vo.vendor_order_id
		INNER JOIN dbo.order_item oi
			ON oi.order_header_id = oh.order_header_id
			   AND oi.line_item = coi.line_item
		CROSS APPLY dbo.fn_order_select_order_item_json(oi.order_item_id) jp
	WHERE jp.usage_pricing_model_id = 2
		  AND coi.storage_gb IS NOT NULL
		  AND oh.order_header_id = @order_header_id;
	
	SELECT i.order_item_id,
		   i.order_header_id,
		   i.line_item,
		   i.product_id,
		   ISNULL(s.seats, 0) AS seats,
		   ISNULL(y.years, 0) AS years,
		   p.product_description,
		   f.product_family_id,
		   f.product_family_description,
		   p.license_keycode_type_id,
		   i.quantity,
		   i.list_price,
		   i.unit_price,
		   i.order_item_offer_id,
		   i.order_item_offer_amount,
		   i.tax,
		   i.item_bundle_id,
		   i.item_hierarchy_id,
		   i.item_total,
		   i.tax_exempt,
		   i.effective_date,
		   capability_expiration_date = CASE
											WHEN h.site_id = 'SFDC' THEN
												i.capability_expiration_date
											WHEN h.site_id IN ( 'MSP', 'RESELLER', 'PARTNERSERVICE' ) THEN
												DATEADD(dd, -1, i.capability_expiration_date)
											ELSE
												i.capability_expiration_date
										END,
		   i.order_item_status_id,
		   il.license_id,
		   l.keycode,
		   lk.license_key,
		   ka.keycode_alias,
		   cu.currency_id,
		  
 cu.currency_code,
		   cu.currency_description,
		   cu.symbol_html,
		   cu.symbol_utf8,
		   cu.symbol_text,
		   bl.license_bulk_load_id,
		   lc.license_category_name,
		   m.license_distribution_method_code,
		   m.license_distribution_method_id,
		   plp.product_line_id,
		   pt.product_type_description,
		   ISNULL(oit.storage_gb, dbo.fn_get_item_storage_gb(i.quantity, DEFAULT, i.product_id, DEFAULT, DEFAULT, DEFAULT)) AS storage_gb,
		   oi.opportunity_line_item_id,
		   p.root_product_id,
		   aos.account_order_staging_id,
		   aos.email,
		   jp.usage_pricing_model_id,
		   jp.usage_pricing_model_name,
		   jp.retention_model_id,
		   jp.retention_model_name,
		   jp.retention_term,
		   jp.retention_model_type_id,
		   jp.product_platform_id,
		   jp.product_platform_name,
		   jp.vault_id,
		   jp.vault_datacenter_name,
		   jp.vault,
		   jp.product_pricing_level_id,
		   jp.pricing_level_description,
		   jp.license_attribute_license_value,
		   jp.license_attribute_license_value_description,
		   oit.actual_storage_quantity
	FROM order_item i WITH (NOLOCK)
		INNER JOIN order_header h
			ON h.order_header_id = i.order_header_id
		INNER JOIN product p WITH (NOLOCK)
			ON i.product_id = p.product_id
		INNER JOIN product_family f WITH (NOLOCK)
			ON p.product_family_id = f.product_family_id
		LEFT JOIN product_seat s WITH (NOLOCK)
			ON p.product_id = s.product_id
		LEFT JOIN product_years y WITH (NOLOCK)
			ON p.product_id = y.product_id
		LEFT JOIN product_type pt WITH (NOLOCK)
			ON p.product_type_id = pt.product_type_id
		LEFT JOIN product_line_product plp WITH (NOLOCK)
			ON p.product_id = plp.product_id
		LEFT JOIN product_license_category plc
			ON plc.product_id = p.product_id
		LEFT JOIN license_category lc WITH (NOLOCK)
			ON plc.license_category_id = lc.license_category_id
		LEFT JOIN order_item_license il WITH (NOLOCK)
			ON i.order_item_id = il.order_item_id
		LEFT JOIN license l WITH (NOLOCK)
			ON il.license_id = l.license_id
		LEFT JOIN license_key lk WITH (NOLOCK)
			ON il.license_id = lk.license_id
		LEFT JOIN license_keycode_alias ka WITH (NOLOCK)
			ON il.license_id = ka.license_id
		LEFT JOIN license_distribution_method m WITH (NOLOCK)
			ON l.license_distribution_method_id = m.license_distribution_method_id
		LEFT JOIN order_currency oc WITH (NOLOCK)
			ON i.order_header_id = oc.order_header_id
		LEFT JOIN currency cu WITH (NOLOCK)
			ON oc.currency_id = cu.currency_id
		LEFT JOIN order_item_license_bulk_load bl WITH (NOLOCK)
			ON i.order_item_id = bl.order_item_id
		LEFT JOIN order_item_opportunity_line_item oi WITH (NOLOCK)
			ON i.order_item_id = oi.order_item_id
		LEFT JOIN account_order ao WITH (NOLOCK)
			ON ao.order_header_id = h.order_header_id
		LEFT JOIN account_order_staging aos WITH (NOLOCK)
			ON aos.account_order_staging_id = ao.account_order_staging_id
		LEFT JOIN @order_item_storage oit
			ON oit.order_item_id = i.order_item_id
		OUTER APPLY fn_order_select_order_item_json(i.order_item_id) jp
	WHERE i.order_header_id = @order_header_id
	ORDER BY i.line_item;

END TRY

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message is null THEN 'select product failed'
						ELSE @message END

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = db_name()
	EXEC usp_LogError @ErrorDB = @DBName
		
END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_order_license_usage]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_select_order_license_usage]

(
	@order_license_usage_id int,
	@oracle_contract_status_name varchar(50) = N'ACTIVE'
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-10-22		esmart			Initial creation
	2015-11-16		esmart			Add contract data
	2016-03-27		esmart			Remove terminated lines from available list
	2016-11-16		esmart			Add sort to oracle_contract_line.start_date	
	2017-02-27		esmart			Remove oracle_counter_id and oracle_invoice_number. Support DNS.

	DESCRIPTION
	select order_license_usage
*/

AS
	
	set nocount on			

	declare	@license_id int,
			@end_date datetime,
			@oracle_contract_status_id tinyint,
			@license_category_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @license_id, @end_date	
	select @license_id = license_id, @end_date = end_date, @license_category_id = license_category_id
	from order_license_usage 
	where order_license_usage_id = @order_license_usage_id

	-- 1.2) @oracle_contract_status_id
	if @oracle_contract_status_name is null
		begin
		select @oracle_contract_status_id = 1
		end
	else
		begin
		select @oracle_contract_status_id = oracle_contract_status_id
		from oracle_contract_status 
		where oracle_contract_status_name = @oracle_contract_status_name
		end
	
	
	-- 1.2) @contract
	declare @contract table (license_id int, oracle_line_id varchar(40), order_item_id int,	oracle_contract_line_status_name varchar(50), oracle_contract_id int, oracle_contract_number varchar(20), oracle_contract_status_name varchar(50), start_date datetime,	end_date datetime) 

	insert into @contract(license_id,oracle_line_id,order_item_id,oracle_contract_line_status_name,oracle_contract_id,oracle_contract_number,oracle_contract_status_name,start_date,end_date)
	select top 1 cl.license_id, l.oracle_line_id, l.order_item_id, oracle_contract_line_status_name =  s.oracle_contract_status_name, c.oracle_contract_id, c.oracle_contract_number, cs.oracle_contract_status_name, l.start_date, l.end_date
	from oracle_contract_line_license cl
	inner join oracle_contract_line l
		on l.oracle_contract_line_id = cl.oracle_contract_line_id
	inner join order_item i
		on i.order_item_id = l.order_item_id
	inner join product_license_category lc
		on lc.product_id = i.product_id
	inner join oracle_contract_status s
		on s.oracle_contract_status_id = l.oracle_contract_status_id
	inner join oracle_contract c
		on c.oracle_contract_id = l.oracle_contract_id
	inner join oracle_contract_status cs
		on cs.oracle_contract_status_id = c.oracle_contract_status_id
	where cl.license_id = @license_id and lc.license_category_id = @license_category_id and l.oracle_contract_status_id not in (9) and l.start_date <= @end_date and @end_date <= l.end_date
	order by l.start_date desc

	-- 1.3) return usage
	select u.order_license_usage_id, u.order_header_id, u.license_id, u.usage_seats, u.unit_price, 
		u.start_date, u.end_date, 
		contract_end_date = case when m.process_date is null then u.end_date else m.process_date end,
		u.license_message_id, u.insert_date, u.modified_date, s.oracle_update_status_id, s.oracle_update_status_name,
		c.oracle_line_id, 
		c.oracle_contract_line_status_name,
		c.oracle_contract_id,
		c.oracle_contract_number,
		c.oracle_contract_status_name
	from order_license_usage u
	left join oracle_update_status s
		on s.oracle_update_status_id = u.oracle_u
pdate_status_id
	left join @contract c
		on c.license_id = u.license_id
	left join license_message m
		on u.license_id = m.license_id and m.message_type_id = 10 and m.message_status_id = 1
	where u.order_license_usage_id = @order_license_usage_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_payment_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_select_payment_account]

(
	@vendor_order_code varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-05-12	esmart		Initial creation.

	DESCRIPTION
	select payment account for order
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select v.vendor_order_code, oph.payment_header_id, pm.payment_method_name, pmr.merchant_id, c.currency_code, a.account_number, a.expiration_month, a.expiration_year, t.card_type_id, t.card_type_description, pp.paypal_customer_email
	from  vendor_order v
	inner join order_header h
		on h.vendor_order_id = v.vendor_order_id
	inner join order_payment_header oph
		on oph.order_header_id = h.order_header_id 
	inner join payment_header ph
		on oph.payment_header_id = ph.payment_header_id 
	inner join payment_method pm
		on ph.payment_method_id = pm.payment_method_id
	inner join payment_merchant pmr
		on ph.payment_merchant_id = pmr.payment_merchant_id
	inner join currency c
		on ph.currency_id = c.currency_id
	left join payment_account a
		on oph.payment_header_id = a.payment_header_id
	left join card_type t
		on a.card_type_id = t.card_type_id
	left join payment_subscription_paypal pp
		on oph.payment_header_id = pp.payment_header_id
	where v.vendor_order_code = @vendor_order_code
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_payment_merchant]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_select_payment_merchant]

(
	@license_id int = null,
	@order_header_id int = null,
	@merchant_id varchar(50) output,
	@line_item int output,
	@payment_subscription_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2016-07-27	cnovac		Initial creation.

	DESCRIPTION
	select latest payment merchant for license
	
*/

as

set nocount on

begin try			

	declare	@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @license_id is not null
	begin
		select @merchant_id = pm.merchant_id,
			   @line_item = right(oi.line_item, 1),
			   @payment_subscription_id = ps.payment_subscription_id
		from order_item_license oil
		inner join order_item oi on oi.order_item_id = oil.order_item_id
		inner join order_payment_header oph on oph.order_header_id = oi.order_header_id
		inner join payment_subscription ps on ps.payment_header_id = oph.payment_header_id
		inner join payment_header ph on ph.payment_header_id = oph.payment_header_id
		inner join payment_merchant pm on pm.payment_merchant_id = ph.payment_merchant_id
		where oil.license_id = @license_id
		and oil.order_item_license_id = (select max(oil2.order_item_license_id) 
										   from order_item_license oil2
										   where oil.license_id = oil2.license_id)
	end
	else if @order_header_id is not null
	begin
		select @merchant_id = pm.merchant_id,
			   @line_item = right(oi.line_item, 1),
			   @payment_subscription_id = ps.payment_subscription_id
		from order_item oi
		inner join order_payment_header oph on oph.order_header_id = oi.order_header_id
		inner join payment_subscription ps on ps.payment_header_id = oph.payment_header_id
		inner join payment_header ph on ph.payment_header_id = oph.payment_header_id
		inner join payment_merchant pm on pm.payment_merchant_id = ph.payment_merchant_id
		where oi.order_header_id = @order_header_id

	end
	
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_select_technical_contact]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_order_select_technical_contact]

(
	@customer_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-12-19	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select c.first_name, c.last_name, e.customer_email, p.phone_number
	from customer c with (nolock)
	left join customer_email e with (nolock)
		on c.customer_id = e.customer_id
	left join customer_phone p with (nolock)
		on e.customer_id = p.customer_id
	where c.customer_id = @customer_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_order_update_external_order]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_order_update_external_order]

(
       @order_item_id int = null,
	   @order_header_id int = null,
	   @action varchar(50)
)

/*     
       DATE                 AUTHOR               REMARKS
       2019-02-28           rvinoche             Initial creation
	   2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
       DESCRIPTION
       Alter partner external orders
*/

AS
       
	set nocount on                    

	declare @modified_date datetime = getdate(), 
			@vendor_order_code varchar(100),
			@response_code int,
			@message varchar(100)

	declare @order_items table (row_id int identity(1,1), order_item_id int)

	begin try
    
		if @order_item_id is NULL
        begin
			insert into @order_items (order_item_id)
			select order_item_id from dbo.order_item where order_header_id = @order_header_id
		end
		else
        begin
			insert into @order_items (order_item_id)
			values (@order_item_id)

			select @order_header_id = order_header_id from dbo.order_item where order_item_id = @order_item_id
		end
        
		if not exists (select 1 from @order_items)
		begin
			print 'no orders provided for cancellation'
			return
		end
        
		--1.) Delete orders
       
		if @action = 'delete_order'
		begin	

			--1.1) delete order_items
			
			insert into dbo.order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date,
					order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
			select oi.order_item_id, oi.order_header_id, oi.line_item, oi.product_id, oi.quantity, oi.list_price, oi.unit_price, oi.tax, oi.order_item_offer_id, oi.order_item_offer_amount, oi.item_total,
                   oi.tax_exempt, oi.effective_date, oi.order_item_status_id, oi.insert_date, oi.insert_by, oi.modified_date, oi.modified_by, oi.capability_expiration_date, oi.item_bundle_id, oi.order_item_update_type_id, @modified_date, oi.sap_material_number
			from @order_items t
			inner join dbo.order_item oi
				on oi.order_item_id = t.order_item_id

			delete oil from order_item_license oil
			inner join @order_items t on t.order_item_id = oil.order_item_id

			delete oio from order_item_opportunity_line_item oio 
			inner join @order_items t on t.order_item_id = oio.order_item_id 

			update lch 
			set order_item_id = null, lch.modified_date = @modified_date, lch.modified_by = system_user
			from license_capability_history lch
			inner join @order_items t on t.order_item_id = lch.order_item_id

			delete oi from order_item oi
			inner join @order_items t on t.order_item_id = oi.order_item_id

			--1.2) undo license_effective_object

			exec dbo.usp_license_effective_object_cancel_transaction @order_header_id = @order_header_id
			
		end
        
		--2.) Update order expiration date

		if @action = 'update_order_expiration_date'
		begin

			insert into dbo.order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date,
					order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
			select oi.order_item_id, oi.order_header_id, oi.line_item, oi.product_id, oi.quantity, oi.list_price, oi.unit_price, oi.tax, oi.order_item_offer_id, oi.order_item_offer_amount, oi.item_total,
                   oi.tax
_exempt, oi.effective_date, oi.order_item_status_id, oi.insert_date, oi.insert_by, oi.modified_date, oi.modified_by, oi.capability_expiration_date, oi.item_bundle_id, oi.order_item_update_type_id, @modified_date, oi.sap_material_number
			from @order_items t
			inner join dbo.order_item oi
				on oi.order_item_id = t.order_item_id

			update oi 
			set oi.capability_expiration_date = cast(@modified_date as date), oi.modified_date = @modified_date, oi.modified_by = system_user
			from dbo.order_item oi
			inner join @order_items t on t.order_item_id = oi.order_item_id    
		end
        
		--3.) Update pricing

		if @action = 'update_pricing'
		begin

			insert into dbo.order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date,
					order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
			select oi.order_item_id, oi.order_header_id, oi.line_item, oi.product_id, oi.quantity, oi.list_price, oi.unit_price, oi.tax, oi.order_item_offer_id, oi.order_item_offer_amount, oi.item_total,
                   oi.tax_exempt, oi.effective_date, oi.order_item_status_id, oi.insert_date, oi.insert_by, oi.modified_date, oi.modified_by, oi.capability_expiration_date, oi.item_bundle_id, oi.order_item_update_type_id, @modified_date, oi.sap_material_number
			from @order_items t
			inner join dbo.order_item oi
				on oi.order_item_id = t.order_item_id
			
			update order_item
			set list_price = round((t.retail_price/365.0) * datediff(dd,i.effective_date,i.capability_expiration_date),2), 
				unit_price = round((t.retail_price/365.0) * datediff(dd,i.effective_date,i.capability_expiration_date),2)
			from order_item i
			inner join @order_items ta 
				on ta.order_item_id = i.order_item_id
			inner join product_license_category plc
				on plc.product_id = i.product_id
			inner join order_item_license il
				on il.order_item_id = i.order_item_id
			inner join order_header h
				on h.order_header_id = i.order_header_id
			inner join vendor_order v
				on v.vendor_order_id = h.vendor_order_id
			inner join partner_order po
				on po.order_header_id = h.order_header_id
			left join license_seat_history sh
				on il.license_id = sh.license_id and i.order_item_id = sh.order_item_id and sh.license_change_reason_id not in (2,14)
			inner join partner_pricing_tier t
				on t.site_id = h.site_id and t.partner_id = po.partner_id and t.low_range <= (i.quantity+isnull(sh.license_seats,0)) and (i.quantity+isnull(sh.license_seats,0)) < t.high_range and t.license_category_id = plc.license_category_id
					and t.pricing_term = 'annual' and t.pricing_status = 'active'

			update order_item
			set item_total = quantity * unit_price
			from dbo.order_item oi
			inner join @order_items t on t.order_item_id = oi.order_item_id
			
			insert into order_header_audit (order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, audit_date)
			select order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, @modified_date
			from order_header
			where order_header_id = @order_header_id

			update h1
			set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount
			from order_header h1
			inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), tot
al_amount = sum(i.item_total)
					from order_header h 
					inner join order_item i
						on i.order_header_id = h.order_header_id
					where h.order_header_id = @order_header_id
					group by h.order_header_id) x
				on x.order_header_id = h1.order_header_id

		END

		--4.) Refund order
        
		if @action = 'refund_orders'
		begin
        
			--4.1) refund order	

			select @vendor_order_code = vo.vendor_order_code 
			from dbo.vendor_order vo
			inner join dbo.order_header oh
				on oh.vendor_order_id = vo.vendor_order_id
			where oh.order_header_id = @order_header_id

			update order_header 
			set order_status_id = 3, modified_date = getdate(), modified_by = suser_sname()
			from order_header h 
			inner join vendor_order v
				on h.vendor_order_id = v.vendor_order_id
			where v.vendor_order_code = @vendor_order_code

			exec usp_cart_refund_order_license @vendor_order_code
			
			--4.2) undo license_effective_object

			exec dbo.usp_license_effective_object_cancel_transaction @order_header_id = @order_header_id
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'failed to edit order for order_header_id '+ cast(@order_header_id as varchar(20))
										else @message end

		declare @dbname nvarchar(128)
		set @dbname = db_name()
		exec dbo.usp_logerror @errordb = @dbname;
		throw 51001, @message,1;
	end catch;



GO
