	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_part_archive_dr_order_notification_xml]
-- =============================================================================

create procedure dbo.usp_part_archive_dr_order_notification_xml
as
/***********************************************************************
 Procedure:	 usp_part_archive_dr_order_notification_xml

PURPOUSE: To reliably move the data from the %_switch table to the archive destination.
          In this case the destination is on the same server.  It should be recoverable/rerunnable.

   NOTES: Separating from partition specific code because this is not as generic as the partitioning function.

----------------------------------------------------------------------
 M O D I F I C A T I O N  H I S T O R Y
  				  Rev
  Date	    Nbr  Author     Details
----------------------------------------------------------------------
 20131007   0.0   cfaulkner  Original version

*********************************************************************/
set nocount on;

declare @sourceCount int, @destinationCountBefore int, @destinationCountAfter int, @raiserror nvarchar(1024);

select @sourceCount = count(*) from eCommerce.dbo.dr_order_notification_xml_switch
select @destinationCountBefore = count(*) from eCommerce_archive.dbo.dr_order_notification_xml

--MOVE DATA
--Not a lot of rows so doing it in one insert.
--Primary key will keep duplicates from being inserted.
insert into eCommerce_archive.dbo.dr_order_notification_xml
  select * from eCommerce.dbo.dr_order_notification_xml_switch

--IF COUNTS AGREE TRUNCATE THE TABLE, OTHERWISE RAISERROR
select @destinationCountAfter = count(*) from  eCommerce_archive.dbo.dr_order_notification_xml
if @sourceCount = 0
begin 
  print 'Nothing to do! The table eCommerce.dbo.dr_order_notification_xml_switch is empty.'
end
else
begin
  if @sourceCount + @destinationCountBefore = @destinationCountAfter
  begin
    truncate table eCommerce.dbo.dr_order_notification_xml_switch
    print 'truncate table eCommerce.dbo.dr_order_notification_xml_switch'
    print 'TABLE COUNTS '
    + '   @sourceCount: ' + ltrim(str(@sourceCount))
    + '   @destinationCountBefore: ' + ltrim(str(@destinationCountBefore))
    + '   @destinationCountAfter: ' + ltrim(str(@destinationCountAfter));
  end
  else
  begin
    select @raiserror = 'CRITICAL ERROR! The counts do not match.  All data may not have been copied.  Aborting truncate!'
    + '   @sourceCount: ' + ltrim(str(@sourceCount))
    + '   @destinationCountBefore: ' + ltrim(str(@destinationCountBefore))
    + '   @destinationCountAfter: ' + ltrim(str(@destinationCountAfter));
    raiserror (N'%s', 16, 1,@raiserror);
  end
end
--END OF CODE


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_part_manage_dr_order_notification_xml]
-- =============================================================================

create procedure dbo.usp_part_manage_dr_order_notification_xml
as
/***********************************************************************
 Procedure:	 usp_part_manager_dr_order_notification_xml

PURPOUSE: To switch out the oldest month of data from and merger that partition IF needed.  
          To add a new future monthly partition IF needed.

   NOTES: Separating from data archiving code because this is more generic.

----------------------------------------------------------------------
 M O D I F I C A T I O N  H I S T O R Y
  				  Rev
  Date	    Nbr  Author     Details
----------------------------------------------------------------------
 20131007   0.0   cfaulkner  Original version

*********************************************************************/
set nocount on;

declare @TableName          varchar(255)
      , @PartFuncion        varchar(255)
      , @PartSchema         varchar(255)
      , @FileGroup          varchar(255)
      , @PartMonthsPast     int
      , @PartMonthsFuture   int
      , @PartOneDate        datetime
      , @PartLastDate       datetime
      , @PartNextDate       datetime --
      , @PartOneTargetDate  datetime
      , @PartLastTargetDate datetime
      , @sql                varchar(4000)
      , @sqlErr             varchar(4000)
      , @PartInfoDisplay    bit;

select  @TableName        = 'dbo.dr_order_notification_xml'
      , @PartFuncion      = 'dr_order_notification_xml_function'
      , @PartSchema       = 'dr_order_notification_xml_scheme'
      , @FileGroup        = 'primary'
      , @PartMonthsPast   = -5
      , @PartMonthsFuture = 12
      , @PartInfoDisplay  = 0;

select @PartOneTargetDate  = dateadd(m, @PartMonthsPast, dateadd(month, datediff(month, 0, Getdate()), 0))
     , @PartLastTargetDate = dateadd(m, @PartMonthsFuture, dateadd(month, datediff(month, 0, Getdate()), 0));

--GET OLDEST AND NEWEST PARTION DATE VALUES
select @PartOneDate = min(cast(prf.value as date)), @PartLastDate = max(cast(prf.value as date))
  from sys.partition_schemes ps
  join sys.partition_functions pf on pf.function_id = ps.function_id
  join sys.partition_range_values prf on pf.function_id = prf.function_id
  where ps.name like 'dr_order_notification_xml%'; 

select @PartOneDate as 'partonedate', @PartOneTargetDate as 'partonetarget'
     , @PartLastDate as 'partlastdate', @PartLastTargetDate as 'partlasttarget'

--ADD A MONTH IF NEEDED
if @PartLastDate < @PartLastTargetDate
begin
select @PartNextDate = dateadd(m, 1, @PartLastDate)
  select @sql = 'alter partition scheme ['+@PartSchema+'] next used ['+@FileGroup+'];'
  exec(@sql); 
  print @sql; 
  select @sql = 'alter partition function ['+@PartFuncion+']() split range (''' + CONVERT(VARCHAR, @PartNextDate, 120) + ''');'
  exec(@sql); 
  print @sql; 
  if not exists (
     select value from sys.partition_range_values where function_id = 
           (select function_id from sys.partition_functions where name = @PartFuncion)
        and value = @PartNextDate)
     begin
        select @sqlErr = 'Partition '+CONVERT(VARCHAR, @PartNextDate, 120)+' for '+@PartFuncion+' was not created.';
        raiserror (N'%s', 16, 1,@sqlErr);
        select @sqlErr
     end   
end

--SWITCH OUT A MONTH IF NEEDED
--The swtich will fail if the partition _switch table is not empty. The merge will not occur.
if @PartOneDate < @PartOneTargetDate
begin
select 'switch out a month'
  select @sql = 'ALTER TABLE '+@TableName+' SWITCH PARTITION 1 TO '+@TableName+'_switch;'  --+'_Archive PARTITION ['+ @PartNumToSwitch+'];'
  print @sql
  exec(@sql);
  select @sql = 'ALTER PARTITION FUNCTION '+@PartFuncion+'() MERGE RANGE ('''+convert(varchar, @PartOneDate, 120)+''
');'
  print @sql
  exec(@sql);
end

if @PartInfoDisplay = 1
begin
  select distinct  object_name(p.object_id) AS ObjectName,
        --i.name as IndexName, p.index_id as IndexID,
        ds.name as PartitionScheme, p.partition_number as PartitionNumber,
        fg.name as FileGroupName, prv_left.value as LowerBoundaryValue,
        prv_right.value as UpperBoundaryValue,
        case pf.boundary_value_on_right when 1 then 'RIGHT' else 'LEFT' end  as range,
       p.rows AS Rows
    from sys.partitions as p
    join sys.indexes as i on i.object_id = p.object_id and i.index_id = p.index_id
    join sys.data_spaces as ds on ds.data_space_id = i.data_space_id
    join sys.partition_schemes as ps on ps.data_space_id = ds.data_space_id
    join sys.partition_functions as pf on pf.function_id = ps.function_id
    join sys.destination_data_spaces AS dds2 on dds2.partition_scheme_id = ps.data_space_id AND dds2.destination_id = p.partition_number
    join sys.filegroups as fg on fg.data_space_id = dds2.data_space_id
    left join sys.partition_range_values as prv_left on ps.function_id = prv_left.function_id AND prv_left.boundary_id = p.partition_number - 1
    left join sys.partition_range_values as prv_right on ps.function_id = prv_right.function_id AND prv_right.boundary_id = p.partition_number  
    where objectpropertY(p.object_id, 'ISMSShipped') = 0 and i.name LIKE 'PK%' and ds.name = @PartSchema
    order by ObjectName, PartitionNumber
end
--END OF CODE




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_account_activate]
-- =============================================================================
-------------------------------------------------------------------------------
--  Description:
--    Activates/deactivates individual rows in ecommerce partner_account.
--  Maintenance:
--    20161109 - mandersen - Created.
-------------------------------------------------------------------------------
--  Copyright © 2016-2017 Webroot Inc.
-------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_partner_account_activate]
(
  @partner_id       int,
  @account_id       int
)
AS

  set nocount on;

  --Activate account for the partner
  UPDATE
    dbo.partner_account
  SET
    partner_account_status_id  = '1'
  WHERE
    partner_id  = @partner_id  AND
    account_id  = @account_id;

  --Raise error if partner_account was not found
  IF (@@rowcount = 0)
      raiserror(15600, -1, -1, 'usp_partner_account_activate');

  --Deactivate account for any other partners
  UPDATE
    dbo.partner_account
  SET
    partner_account_status_id  = '2'
  WHERE
    partner_id <> @partner_id  AND
    account_id  = @account_id;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_account_deactivate]
-- =============================================================================
-------------------------------------------------------------------------------
--  Description:
--    Deactivates individual rows in ecommerce partner_account.
--  Maintenance:
--    20161109 - mandersen - Created.
-------------------------------------------------------------------------------
--  Copyright © 2016-2017 Webroot Inc.
-------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_partner_account_deactivate]
(
  @partner_id       int,
  @account_id       int
)
AS

  set nocount on;

  --Deactivate account for the partner
  UPDATE
    dbo.partner_account
  SET
    partner_account_status_id  = '2'
  WHERE
    partner_id  = @partner_id  AND
    account_id  = @account_id;

  --Raise error if partner_account was not found
  IF (@@rowcount = 0)
      raiserror(15600, -1, -1, 'usp_partner_account_deactivate');

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_cart_select_order_item_options]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_cart_select_order_item_options]

(
	@cart_order_in_process_id int,
	@cart_item_bundle_id int,
	@cart_discount_method_id tinyint = null,
	@partner_key varchar(36) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2010-10-25		esmart		Initial creation.
	2014-03-31		esmart		Add fixed price discounts
	2014-08-21		esmart		GSM purchase support
	2014-08-01		esmart		Add CD product
	2016-02-15		esmart		site_id support
	2017-03-06		esmart		modules
	2017-08-07		acoffel		fix years being truncated
	
	DESCRIPTION
	select seat, year, storage, license_category, and discounts for item
*/

AS
	set nocount on				

	declare	@language_code varchar(2),
			@location_code varchar(3),
			@license_category_id tinyint,
			@product_line_id int,
			@product_type_id int,
			@cart_discount_id int, 
			@storage_gb int,
			@seat_list varchar(50), 
			@years_list varchar(200),
			@storage_gb_list varchar(100),
			@license_category_list varchar(100), 
			@cart_discount_list nvarchar(200),
			@keycode_type_list varchar(200),
			@pricing_level_list varchar(200),
			@module_list varchar(200),
			@partner_license_attribute_list varchar(200),
			@partner_id int,
			@years int,
			@cd_product_id int,
			@site_id varchar(20),
			@response_code int,
			@message varchar(100)


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @item_summary table (cart_item_bundle_id int, product_family_id int, product_line_id int, cart_order_item_in_process_id int, product_id int, keycode varchar(40), product_type_id int, max_product_type_id int,	current_license_category_id int,license_category_id int,current_seats int,seats int,current_storage_gb int,storage_gb int,quantity int,years float,retail_price money,net_price money,discount money,standard_discount money,cart_discount_id int)

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.2) @site_id
	select @site_id = site_id from cart_order_in_process where cart_order_in_process_id = @cart_order_in_process_id



	-- 1.3) new product that can be bundled
		insert into @item_summary(cart_item_bundle_id,product_family_id,product_line_id,cart_order_item_in_process_id,product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id)
		select i.cart_item_bundle_id,  
				p.product_family_id,
				plp.product_line_id,
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = max(s.seats), 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = sum(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price), 
				net_price = sum(i.net_price),
				discount = sum(i.discount), 
				standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inner join product_line_product plp with (nolock)
			on p.product_i
d = plp.product_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		left join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		where i.cart_order_in_process_id = @cart_order_in_process_id and i.cart_item_bundle_id = @cart_item_bundle_id and il.cart_order_item_license_in_process_id is null and p.product_family_id in (1,2,30,31,50,51,55,100,200,300)
			and p.product_type_id <> 4
		group by i.cart_item_bundle_id,
				p.product_family_id,
				plp.product_line_id

	-- 1.4) renewal/upgrade products that can be bundled
		insert into @item_summary(cart_item_bundle_id, product_family_id, product_line_id, keycode, cart_order_item_in_process_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,retail_price,net_price,discount,standard_discount,cart_discount_id)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				plp.product_line_id,
				l.keycode, 
				cart_order_item_in_process_id = min(i.cart_order_item_in_process_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = max(s.seats), 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				retail_price = sum(i.retail_price), 
				net_price = sum(i.net_price),
				discount = sum(i.discount), 
				standard_discount = sum(i.standard_discount),
				cart_discount_id = max(i.cart_discount_id)
		from cart_order_item_in_process i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		inner join product_line_product plp with (nolock)
			on p.product_id = plp.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license_in_process il with (nolock)
			on i.cart_order_item_in_process_id = il.cart_order_item_in_process_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_in_process_id = @cart_order_in_process_id and i.cart_item_bundle_id = @cart_item_bundle_id and il.keycode <> '' and p.product_family_id in (1,2,30,31,50,51,55,100,200,300)
			and p.product_type_id <> 4
		group by i.cart_item_bundle_id,
				p.product_family_id,
				plp.product_line_id,
				l.keycode

	-- 1.5) get values
		select @language_code = language_code, 
			@location_code = location_code
		from cart_order_in_process 
		where cart_order_in_process_id = @cart_order_in_process_id

		select @license_category_id = license_category_id, 
			@product_line_id = product_line_id, 
			@product_type_id = product_type_id,
			@cart_discount_id = cart_discount_id,
			@storage_gb = storage_gb,
			@years = years
		from @item_summary

	-- 1.6) @cart_discount_method_id
	if @cart_discount_id is not null
		begin
		select @cart_discount_method_id = cart_discount_method_id
		from cart_discount_item
		where cart_discount_id
 = @cart_discount_id
		end
	else
		begin
		if @cart_discount_method_id is null
			begin
			select @cart_discount_method_id = 3
			end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) get values 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 2.1) @seat_list
		select @seat_list = coalesce(@seat_list+', ','')+ cast(convert(varchar(10),seats) as varchar(100)) 
		from product_license_category_seat 
		where license_category_id = @license_category_id
			and seats in 
			(select distinct(s.seats)
			from product_seat s
			inner join product_license_category plc
				on s.product_id = plc.product_id 
			inner join license_category_product_line pl
				on plc.license_category_id = pl.license_category_id
			inner join product_line_product plp
				on s.product_id = plp.product_id and pl.product_line_id = plp.product_line_id
			inner join product p
				on p.product_lifecycle_id = 1 and p.product_type_id = @product_type_id
			where plc.license_category_id = @license_category_id and pl.language_code = @language_code and pl.location_code = @location_code and pl.product_line_id = @product_line_id)

		-- 2.2) @years_list
		select @years_list = coalesce(@years_list+', ','')+ cast(years_description +'|'+convert(varchar(10),years) as varchar(100)) 
		from product_license_category_years 
		where license_category_id = @license_category_id 
			and years in 
			(select distinct(y.years)
			from product_years y
			inner join product_license_category plc
				on y.product_id = plc.product_id 
			inner join license_category_product_line pl
				on plc.license_category_id = pl.license_category_id
			inner join product_line_product plp
				on y.product_id = plp.product_id and pl.product_line_id = plp.product_line_id
			inner join product p
				on p.product_lifecycle_id = 1 and p.product_type_id = @product_type_id
			where plc.license_category_id = @license_category_id and pl.language_code = @language_code and pl.location_code = @location_code and pl.product_line_id = @product_line_id)

		if @product_type_id in (2,3)
			begin
			select @years_list = '0|0,' + @years_list
			end

		-- 2.3) @storage_gb_list
		select @storage_gb_list = coalesce(@storage_gb_list+', ','')+ cast(convert(varchar(10),s.storage_gb) +' GB |'+convert(varchar(10),s.storage_gb) as varchar(100)) 
		from product_license_category_storage s
		where s.license_category_id = @license_category_id
			

		-- 2.4) @license_category_list
		select @license_category_list = coalesce(@license_category_list+', ','')+ cast(c.license_category_name +'|'+convert(varchar(10),c.license_category_id) as varchar(100)) 
		from product_license_category_upgrade u
		inner join license_category_product_line pl
			on u.upgrade_license_category_id = pl.license_category_id and pl.language_code = @language_code and pl.location_code = @location_code
		inner join license_category c
			on u.upgrade_license_category_id = c.license_category_id
		inner join partner_license_category_product_line pc
			on u.upgrade_license_category_id = pc.license_category_id and pc.partner_id = @partner_id
		where u.license_category_id = @license_category_id and u.language_code = @language_code and u.location_code = @location_code and pl.product_line_id = @product_line_id and pc.site_id = @site_id
		order by c.license_category_id
		
		-- 2.5) @cart_discount_list
		if @cart_discount_method_id = 1
			begin
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')+ cast(isnull(symbol_utf8,'')+convert(varchar(10),id.discount)+'|'+convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
			from cart_discount_item_discount id
			inner join currency c
				on id.currency_id = c.currency_id
			inner join cart_discount_item 
i
				on id.cart_discount_item_id = i.cart_discount_item_id
			inner join cart_discount d
				on i.cart_discount_id = d.cart_discount_id
			inner join partner_cart_discount pd
				on d.cart_discount_id = pd.cart_discount_id and pd.partner_id = @partner_id
			where cart_discount_method_id = @cart_discount_method_id and product_type_id = @product_type_id and product_line_id = @product_line_id and i.license_category_id is null and pd.site_id = @site_id
				and id.language_code = @language_code and id.location_code = @location_code and d.cart_discount_status_id = 1
			order by id.discount
			end
		else if @cart_discount_method_id = 3
			begin
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')+ cast(convert(varchar(10),i.discount)+'% |'+convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
			from cart_discount_item i
			inner join cart_discount d
				on i.cart_discount_id = d.cart_discount_id
			inner join partner_cart_discount pd
				on d.cart_discount_id = pd.cart_discount_id and pd.partner_id = @partner_id
			where cart_discount_method_id = @cart_discount_method_id and product_type_id = @product_type_id and product_line_id = @product_line_id and i.license_category_id is null and pd.site_id = @site_id and d.cart_discount_status_id = 1
			order by i.discount
			end
		else if @cart_discount_method_id = 2
			begin
			select @cart_discount_list = coalesce(@cart_discount_list+', ','')+ cast(convert(varchar(10),i.discount)+'|'+convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
			from cart_discount_item i
			inner join cart_discount d
				on i.cart_discount_id = d.cart_discount_id
			inner join partner_cart_discount pd
				on d.cart_discount_id = pd.cart_discount_id and pd.partner_id = @partner_id
			where cart_discount_method_id = @cart_discount_method_id and product_type_id = @product_type_id and product_line_id = @product_line_id and pd.site_id = @site_id and d.cart_discount_status_id = 1
			order by i.discount
			end
	
	-- 2.6) @keycode_type_list
		select @keycode_type_list = coalesce(@keycode_type_list+', ','')+ cast(t.license_keycode_type_description +'|'+convert(varchar(10),t.license_keycode_type_id) as varchar(100)) 
		from product_license_category_keycode_type l
		inner join license_keycode_type t
			on l.license_keycode_type_id = t.license_keycode_type_id
		where license_category_id = @license_category_id and t.license_keycode_type_id = case when @license_category_id = 220 then 3 else l.license_keycode_type_id end
		order by l.license_keycode_type_id desc


	-- 2.7) @pricing_level_list
		if @license_category_id in (212,220,250,55)
			begin
			select @pricing_level_list = coalesce(@pricing_level_list+', ','')+ cast(convert(varchar(10),pricing_level) as nvarchar(100)) 
			from product_pricing_level
			end
		else 
			begin
			select @pricing_level_list = ''
			end

	-- 2.8) cd_product_id
		select @cd_product_id = p.product_id
		from product p
		inner join product_license_category lc
			on p.product_id = lc.product_id 
		where p.product_family_id = 8 and p.product_lifecycle_id = 1 and lc.license_category_id = @license_category_id

	-- 2.9) @partner_license_attribute_list
		select @partner_license_attribute_list = coalesce(@partner_license_attribute_list+', ','')+ cast(v.license_attribute_license_value_description+'|'+convert(varchar(10),pl.license_attribute_license_value) as varchar(100)) 
		from partner_license_attribute pl
		inner join license_attribute a
			on a.license_attribute_id = pl.license_attribute_id
		inner join license_attribute_license_value v
			on v.license_attribute_license_value = pl.license_attribute_license_value
		where pl.partner_id = @partner_id and pl.site_id = @site_id and pl.license_category_id = @license_category_id

		-- 2.9.1) if no default add a select list item
		if (select count(*) from partner_license_attribute pl where pl.partner_id = @partner_id and pl.site_id = @site_id and pl.license_category_id = @license_category_id and pl.default_value = 1) = 0 and
			@partn
er_license_attribute_list <> ''
			begin
			select @partner_license_attribute_list = 'Annual Sold|,'+@partner_license_attribute_list
			end

	-- 2.10) @module_list
		select @module_list = coalesce(@module_list+', ','')+ cast(convert(varchar(10),m.license_module_code) as nvarchar(100)) 
		from partner_license_module pm
		inner join license_module m
			on m.license_module_id = pm.license_module_id
		where pm.partner_id = @partner_id and pm.site_id = @site_id and pm.license_category_id = @license_category_id
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select seat_list = @seat_list, 
			years_list = @years_list, 
			storage_gb_list = @storage_gb_list, 
			license_category_list = @license_category_list, 
			cart_discount_list = @cart_discount_list, 
			keycode_type_list = @keycode_type_list, -- case when @product_type_id = 1 then @keycode_type_list else '' end, 
			pricing_level_list = @pricing_level_list, 
			cd_product_id = @cd_product_id,
			partner_license_attribute_list = @partner_license_attribute_list,
			module_list = @module_list,
			language_code = @language_code,
			location_code = @location_code

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_cart_select_order_page_details]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_cart_select_order_page_details]

(
	@partner_key varchar(36),
	@language_code varchar(2) = null,
	@location_code varchar(3) = null,
	@product_line_cart_type varchar(20) = null,
	@site_id varchar(65) = null,
	@license_category_id int = null,
	@item_hierarchy_id tinyint = 1
)

/*	
	DATE			AUTHOR		REMARKS
	2012-10-15		esmart		Initial creation.
	2014-08-21		esmart		GSM purchase support
	2015-12-19		esmart		Fix discounts
	2016-02-15		esmart		site_id support
	2017-03-07		esmart		module products
	2017-08-21		esmart		secondary_license_category_list
	2019-05-20		esmart		Suspend purchase of mobile and user
	2019-08-08		esmart		reset module list
	2019-11-06		esmart		Add usage_pricing_model
	2020-02-21		esmart		Add vault
	2020-06-17		wbarton		Adding license_category_brand for the Partner Cart UI redesign
	2020-07-15		esmart		Add retention_model, product_platform, convert to json
	2020-09-03		esmart		Add storage
	2121-10-29      nprimo      Change the label of display retention_model_id=2:'2 Years' to retention_model_id=2:7 Years' when retention_model_id=2
	2022-01-07      gblandford  SMCI-6216 - Revert previous change of converting retention_model 2->7
	2023-03-06		gblandford	https://jira.opentext.com/browse/ECOM-863 - add additional criteria using new column cart_display in partner_license_attribute to determine if we offer
								MSP/RESELLER product options

	DESCRIPTION
	select order page details for partner cart
*/

AS
	set nocount on				

	declare	@product_line_list nvarchar(max),
			@seat_list nvarchar(max),
			@years_list nvarchar(max), 
			@cart_discount_list nvarchar(max),
			@keycode_type_list nvarchar(max),
			@pricing_level_list nvarchar(max),
			@partner_license_attribute_list nvarchar(max),
			@module_list nvarchar(max),
			@secondary_license_category_list nvarchar(max),
			@product_order_id int,
			@total_order_set int,
			@usage_pricing_model nvarchar(max),		
			@retention_model nvarchar(max),			
			@retention_term nvarchar(max),			
			@product_platform nvarchar(max),			
			@vault nvarchar(max),
			@storage_list nvarchar(max),
			-- @license_category_id int,
			@product_line_id int,
			@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @site_id
	if @site_id is null
		begin
		select @site_id = 'MSP'
		end

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.2) setup table
	declare @product_order table (product_order_id int identity(1,1), item_hierarchy_id tinyint, license_category_id int, license_category_name varchar(20), license_category_description varchar(100), license_category_brand varchar(50),
								seat_list nvarchar(max), years_list nvarchar(max), cart_discount_list nvarchar(max), pricing_level_list nvarchar(max), product_line_id int, product_line_cart_type varchar(20), keycode_type_list nvarchar(max), partner_license_attribute_list nvarchar(max),module_list nvarchar(max),secondary_license_category_list nvarchar(max), usage_pricing_model nvarchar(max), vault nvarchar(max), retention_model nvarchar(max), retention_term nvarchar(max), product_platform nvarchar(max), storage_list nvarchar(max))

	if @item_hierarchy_id = 1
		begin
			insert into @product_order(item_hierarch
y_id,license_category_id,license_category_name,license_category_description,license_category_brand,product_line_id,product_line_cart_type)
			select distinct 1 as item_hierarchy_id, c.license_category_id,c.license_category_name,c.license_category_description, c.license_category_brand, pl.product_line_id,l.product_line_cart_type
			from partner_license_category_product_line pl
			inner join license_category c
				on pl.license_category_id = c.license_category_id AND c.status = 1
			inner join product_line l
				on pl.product_line_id = l.product_line_id
			inner join partner p
				on pl.partner_id = p.partner_id 
			where p.partner_id = @partner_id and pl.site_id = @site_id and
				pl.license_category_id = case when @license_category_id is null then pl.license_category_id else @license_category_id end and
				pl.license_category_id not in (250,55)
			order by pl.product_line_id, c.license_category_id
		end
	else
		begin
			insert into @product_order(item_hierarchy_id,license_category_id,license_category_name,license_category_description,license_category_brand,product_line_id,product_line_cart_type)
			select distinct 2 as item_hierarchy_id, lc.license_category_id, lc.license_category_name, lc.license_category_description, lc.license_category_brand, l.product_line_id, l.product_line_cart_type
			from partner_license_module pm
			inner join license_module m
				on m.license_module_id = pm.license_module_id
			inner join license_module_category mc
				on m.license_module_id = mc.license_module_id
			inner join license_category lc
				on mc.license_category_id = lc.license_category_id AND lc.status = 1
			inner join license_category_product_line pl
				on pl.license_category_id = lc.license_category_id and pl.language_code = @language_code and pl.location_code = @location_code
			inner join product_line l
				on l.product_line_id = pl.product_line_id
			where pm.partner_id = @partner_id and pm.site_id = @site_id and pm.license_category_id = @license_category_id
			order by l.product_line_id, lc.license_category_id
		end

	--select * from @product_order
	--return

	select @product_order_id= 1, @total_order_set = max(product_order_id) from @product_order

	while @total_order_set >= @product_order_id
		begin
		---select @product_order_id
		select @license_category_id = license_category_id, @product_line_id = product_line_id from @product_order where product_order_id = @product_order_id

		-- 1.2.1) @seat_list
		select @seat_list = coalesce(@seat_list+', ','')+ cast(convert(varchar(10),seats) as varchar(100)) from product_license_category_seat where license_category_id = @license_category_id and site_display = 1
		update @product_order set seat_list = @seat_list where product_order_id = @product_order_id
		select @seat_list = null
		
		-- 1.2.2) @years_list
		if @item_hierarchy_id = 1
			begin
				select @years_list = (select convert(decimal(18,2),y.years) as years, y.years_description
									from product_license_category_years y
									where y.license_category_id = @license_category_id and y.years in (1,2,3)
									order by y.years
									for json path)

				update @product_order set years_list = @years_list where product_order_id = @product_order_id
				select @years_list = null
			end

		-- 1.2.3) @cart_discount_list
		--select @cart_discount_list = coalesce(@cart_discount_list+', ','')+ cast(convert(varchar(10),i.discount)+'|'+convert(varchar(10),i.cart_discount_id) as nvarchar(100)) 
		--from partner_cart_discount pd
		--inner join cart_discount d
		--	on pd.cart_discount_id = d.cart_discount_id
		--inner join cart_discount_item i
		--	on d.cart_discount_id = i.cart_discount_id
		--where pd.partner_id = @partner_id and i.product_line_id = @product_line_id and i.product_type_id = 1 and pd.site_id = @site_id
		--order by i.discount

		--update @product_order set cart_discount_list = @cart_discount_list where product_order_id = @product_order_id

		--sele
ct @cart_discount_list = null

		-- 1.2.4) @keycode_type_list
		if @item_hierarchy_id = 1
			begin
				select @keycode_type_list  =  (select t.license_keycode_type_id, t.license_keycode_type_description
				from product_license_category_keycode_type l
				inner join license_keycode_type t
					on l.license_keycode_type_id = t.license_keycode_type_id
				where license_category_id = @license_category_id and t.license_keycode_type_id = case when @license_category_id = 220 then 3 else l.license_keycode_type_id end
				order by l.license_keycode_type_id desc
				for json path)

				update @product_order set keycode_type_list = @keycode_type_list where product_order_id = @product_order_id
				select @keycode_type_list = null
			end

		-- 1.2.5) @pricing_level_list
		if @product_line_id = 300 and @item_hierarchy_id = 1
			begin
				select @pricing_level_list = (select pl.product_pricing_level_id, pl.pricing_level, pl.pricing_level_description
												from product_pricing_level pl
												inner join partner_pricing_level p
													on p.product_pricing_level_id = pl.product_pricing_level_id
												where p.partner_id = @partner_id
												for json path)

				update @product_order set pricing_level_list = @pricing_level_list where product_order_id = @product_order_id

				select @pricing_level_list = null
			end

		-- 1.2.6) @partner_license_attribute_list
		if @item_hierarchy_id = 1
			begin
				select @partner_license_attribute_list = (select pl.license_attribute_license_value, v.license_attribute_license_value_description, pl.default_value
														from partner_license_attribute pl
														inner join license_attribute a
															on a.license_attribute_id = pl.license_attribute_id
														inner join license_attribute_license_value v
															on v.license_attribute_license_value = pl.license_attribute_license_value
														where pl.partner_id = @partner_id and pl.site_id = @site_id and pl.license_category_id = @license_category_id
														and isnull(pl.cart_display, 1) = 1
														for json path)

				update @product_order set partner_license_attribute_list = @partner_license_attribute_list where product_order_id = @product_order_id

				select @partner_license_attribute_list = null
			end

		-- 1.2.7) @module_list
		--if @item_hierarchy_id = 1
		--	begin
		--		select @module_list = coalesce(@module_list+', ','')+ cast(convert(varchar(10),m.license_module_code) as nvarchar(100)) 
		--		from partner_license_module pm
		--		inner join license_module m
		--			on m.license_module_id = pm.license_module_id
		--		where pm.partner_id = @partner_id and pm.site_id = @site_id and pm.license_category_id = @license_category_id

		--		update @product_order set module_list = @module_list where product_order_id = @product_order_id
		--	end

		-- 1.2.8) @secondary_license_category_list
		if @item_hierarchy_id = 1
			begin
				select @secondary_license_category_list = (select lc.license_category_description, lc.license_category_name, lc.license_category_brand, (select upm.usage_pricing_model_id, upm.usage_pricing_model_name
																					from partner_usage_pricing_model ppm
																					inner join usage_pricing_model upm
																						on upm.usage_pricing_model_id = ppm.usage_pricing_model_id
																					where ppm.partner_id = pm.partner_id and ppm.license_category_id = lc.license_category_id
																					for json path) usage_pricing_model
															from partner_license_module pm
															inner join license_module m
																on m.license_module_id = pm.license_module_id
															inner join license_module_category mc
																on m.license_module_id = mc.license_module_id
															inner join license_category lc
																on mc.license_category_id = lc.license_category_id AND lc.status = 1
															where pm.partner_id = @part
ner_id and pm.site_id = @site_id and pm.license_category_id = @license_category_id
															for json path)
													
				update @product_order set secondary_license_category_list = @secondary_license_category_list where product_order_id = @product_order_id
			end

		-- 1.2.9) usage_pricing_model
		select @usage_pricing_model = (select upm.usage_pricing_model_id, upm.usage_pricing_model_name
										from partner_usage_pricing_model ppm
										inner join usage_pricing_model upm
											on upm.usage_pricing_model_id = ppm.usage_pricing_model_id
										where ppm.partner_id = @partner_id and ppm.license_category_id = @license_category_id and ppm.site_id = @site_id
										for json path)

		update @product_order set usage_pricing_model = @usage_pricing_model where product_order_id = @product_order_id

		-- 1.2.10) vault
		select @vault = (select v.vault_id, v.vault_name, v.vault_datacenter_name
						from vault v
						inner join vault_license_category vlc
							on v.vault_id = vlc.vault_id
						where vlc.license_category_id = @license_category_id and v.vault_status = 'active'
						for json path)

		update @product_order set vault = @vault where product_order_id = @product_order_id

		select @module_list = null, @secondary_license_category_list = null, @usage_pricing_model = null, @vault = null

		-- 1.2.11) retention_model
		--declare @retention_model_table TABLE (license_category_id int, retention_model_id int, retention_model_name varchar(255))

		--insert into @retention_model_table
		--select ppm.license_category_id, upm.retention_model_id, upm.retention_model_name
		--								from partner_retention_model ppm
		--								inner join retention_model upm
		--									on upm.retention_model_id = ppm.retention_model_id
		--								where ppm.partner_id = @partner_id and ppm.license_category_id = @license_category_id and ppm.site_id = @site_id
		--update rmt
		--	set rmt.retention_model_name = (select top 1 rm.retention_model_name from retention_model rm where rm.retention_model_id = 7)
		--from @retention_model_table rmt
		--where rmt.license_category_id = 233 and rmt.retention_model_id = 2

		--select @retention_model = (select rmt.retention_model_id, rmt.retention_model_name from @retention_model_table rmt
		--								for json path)
		SELECT @retention_model = (SELECT upm.retention_model_id, upm.retention_model_name
										FROM partner_retention_model ppm
										INNER JOIN retention_model upm
											ON upm.retention_model_id = ppm.retention_model_id
										WHERE ppm.partner_id = @partner_id AND ppm.license_category_id = @license_category_id AND ppm.site_id = @site_id
										FOR JSON PATH)

		UPDATE @product_order SET retention_model = @retention_model WHERE product_order_id = @product_order_id
		
		-- 1.2.12) product_platform
		select @product_platform = (select pp.product_platform_id, pp.product_platform_name
										from partner_product_platform ppl
										inner join product_platform pp
											on pp.product_platform_id = ppl.product_platform_id
										where ppl.partner_id = @partner_id and ppl.license_category_id = @license_category_id and ppl.site_id = @site_id
										for json path)

		update @product_order set product_platform = @product_platform where product_order_id = @product_order_id
		
		-- 1.2.13) @storage_list
		select @storage_list = (select distinct lc.license_category_id, f.usage_pricing_model_id, f.product_platform_id,
									(select s.storage_TB, s.quantity
									from license_category_storage s
									cross apply fn_product_select_product_extension(s.product_extension_json) fs
									where s.license_category_id = lc.license_category_id and (fs.product_platform_id = f.product_platform_id or fs.product_platform_id is null) and fs.usage_pricing_model_id = f.usage_pricing_model_id 
									for json path) as storage 
								from license_category_storage lc
								cross apply fn_prod
uct_select_product_extension(lc.product_extension_json) f
								where lc.license_category_id = @license_category_id
								for json path)

		update @product_order set storage_list = @storage_list where product_order_id = @product_order_id

		select @storage_list = null, @module_list = null, @secondary_license_category_list = null, @usage_pricing_model = null, @vault = null, @retention_model = null, @product_platform = null
		select @product_order_id = @product_order_id + 1
		end

	-- 1.5) return results
	select product_order_id,item_hierarchy_id,license_category_id,license_category_name,license_category_description,license_category_brand,seat_list,years_list,keycode_type_list,pricing_level_list,product_line_id,product_line_cart_type, 
		partner_license_attribute_list, secondary_license_category_list, usage_pricing_model, vault, retention_model, product_platform, storage_list
	from @product_order
	where product_line_cart_type = case
										when @product_line_cart_type is null then product_line_cart_type
										else @product_line_cart_type 
									end 
	order by product_line_id desc, license_category_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;







GO
