CREATE PROCEDURE [dbo].[usp_partner_insert_partner]

(
	@partner_name nvarchar(100), 
	@partner_type_id tinyint,
	@partner_status_id tinyint,
	@salesforce_id varchar(20) = null, 
	@oracle_id varchar(20) = null,
	@parent_partner_id int = null,
	@insert_by varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @insert_by
	if @insert_by is null begin select @insert_by = suser_sname() end

	-- 1.2) duplicate
	if (select count(*) from partner where partner_name = @partner_name and partner_type_id = @partner_type_id) > 0
		begin
		select @response_code = -120, @message = 'Duplicate partner'
		select response_code = @response_code, message = @message
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert partner
	insert into partner(partner_name, partner_type_id, partner_status_id, parent_partner_id, salesforce_id, oracle_id, last_modified_by)
	values(@partner_name, @partner_type_id, @partner_status_id, @parent_partner_id, @salesforce_id, @oracle_id, @insert_by)

	select @partner_id = scope_identity()

	select partner_key = convert(varchar(36),partner_key)
	from partner 
	where partner_id = @partner_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_account]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_partner_insert_partner_account]

(
  @partner_key varchar(36),
  @account_user_name varchar(100),
  @insert_by varchar(20) = null
)

/*
  DATE    AUTHOR    REMARKS
  2013-01-07  esmart    Initial creation.
  2016-11-10  mandersen Added call to usp_partner_account_activate.

  DESCRIPTION
  select partner types
*/

AS
  set nocount on

  declare @partner_id int,
      @account_id int,
      @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) select
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.0) @insert_by
  if @insert_by is null begin select @insert_by = suser_sname() end

  -- 1.1) @partner_id
  select @partner_id = partner_id from partner where partner_key = @partner_key

  -- 1.2) @account_id
  select @account_id = account_id from account where account_user_name = @account_user_name

  if @account_id is null
    begin
    insert into account(account_user_name, account_password, password_hint, account_type_id, account_status_id, insert_by, WARN_opt_in)
    values(@account_user_name,'','',1,0,@insert_by,0)

    select @account_id = scope_identity()
    end

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 2.) insert
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  if (select count(*) from partner_account where partner_id = @partner_id and account_id = @account_id) = 0 and @account_id is not null
    begin
    -- 2.1) insert
    insert into partner_account(partner_id,account_id)
    values(@partner_id, @account_id)

    -- 2.2) activate new partner_account, and deactivate account for other partners
    execute dbo.usp_partner_account_activate @partner_id, @account_id;  

    end

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 3.) return
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  select pa.partner_account_id, partner_account_key = convert(varchar(36),pa.partner_account_key), pa.insert_by, pa.partner_id, a.account_id, a.account_user_name, a.account_status_id, s.account_status, pa.partner_account_status_id, ps.partner_account_status_name
  from partner_account pa
  inner join account a
    on pa.account_id = a.account_id
  inner join account_status s
    on a.account_status_id = s.account_status_id
  inner join partner_account_status ps
    on pa.partner_account_status_id = ps.partner_account_status_id
  where pa.account_id = @account_id


  end try

  begin catch

    set @response_code = -200
    set @message = case when @message is null then 'select failed'
              else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

  end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_account_reset]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_insert_partner_account_reset]

(
	@account_user_name varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_account_key uniqueidentifier,
			@partner_account_reset_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get partner_account_key
	select @partner_account_key = p.partner_account_key
	from partner_account p
	inner join account a
		on p.account_id = a.account_id
	where a.account_user_name = @account_user_name

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) update any existing reset attempts
	update partner_account_reset
	set reset_status = 1
	where partner_account_key = @partner_account_key and reset_status = 0
	
	-- 2.2) insert new
	if @partner_account_key is not null
		begin
			insert into partner_account_reset(partner_account_key)
			values(@partner_account_key)

			select @partner_account_reset_id = scope_identity()
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select partner_account_reset_key = convert(varchar(36),partner_account_reset_key)
	from partner_account_reset
	where partner_account_reset_id = @partner_account_reset_id

	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_monthly_reports]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_insert_partner_billing_monthly_reports]

(
	@billing_date datetime 
)

/*	
	DATE		AUTHOR		REMARKS
	2020-11-02	esmart		Initial creation.

	DESCRIPTION
	Insert partner_usage_override for DNS
*/

AS

	declare @license_attribute_json nvarchar(max), 
			@usage_override_json nvarchar(max),
			@partner_billing_id int, 
			@total_billing_ids int, 
			@partner_id int, 
			@site_id varchar(20), 
			@partner_billing_report_name varchar(100), 
			@configuration_json nvarchar(max), 
			@partner_billing_report_id int, 
			@partner_billing_type_id tinyint,
			@response_code int,
			@message varchar(100)
			

begin try


	select @partner_billing_type_id = 1

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) gathter activity
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @partner_billing table (partner_billing_id int identity(1,1), partner_id int, site_id varchar(20), partner_billing_report_name varchar(100), configuration_json nvarchar(max))

	-- 1.1) find partners to run for billing date
	insert into @partner_billing(partner_id, site_id, partner_billing_report_name, configuration_json)
	select cp.partner_id, 
		bc.site_id,
		p.partner_name + ' ' + bc.site_id + ' - ' + convert(varchar(10),@billing_date,23) as partner_billing_report_name,
		bc.configuration_json
	from partner_configuration_partner cp
	inner join partner p
		on p.partner_id = cp.partner_id
	inner join partner_configuration_partner cpb
		on cpb.partner_id = cp.partner_id 
	inner join partner_billing_configuration bc
		on bc.partner_id = cp.partner_id
	left join partner_billing_report r
		on r.partner_id = cp.partner_id and r.partner_billing_type_id = 1 and r.billing_date = @billing_date and r.site_id = bc.site_id
	where cp.partner_configuration_id = 30 and cp.configuration_value = 'Active' and cpb.partner_configuration_id = 8 and datepart(dd,@billing_date) = cpb.configuration_value
		and r.partner_billing_report_id is null 
	order by p.partner_id

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) run reports
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @partner_billing_id = 1, @total_billing_ids = max(partner_billing_id) from @partner_billing 

	while @total_billing_ids >= @partner_billing_id
		begin
		select @partner_id = b.partner_id, @partner_billing_report_name = b.partner_billing_report_name, @site_id = b.site_id, @configuration_json = b.configuration_json
		from @partner_billing b
		where b.partner_billing_id = @partner_billing_id

		--  2.1) insert partner_billing_report
		insert into partner_billing_report(partner_id, partner_billing_report_name, partner_billing_type_id, billing_date,site_id)
		values(@partner_id,@partner_billing_report_name,@partner_billing_type_id,@billing_date,@site_id)

		select @partner_billing_report_id = scope_identity()

		-- 2.2) insert partner_billing_license_attribute
		select @license_attribute_json = license_attribute, @usage_override_json = usage_override
		from openjson(@configuration_json)
		with (license_attribute nvarchar(max) as json,
			usage_override nvarchar(max) as json)

		-- 2.3) insert partner_billing_license_attribute
		insert into partner_billing_license_att
ribute(partner_billing_report_id, license_attribute_id, license_attribute_license_value)
		select @partner_billing_report_id, license_attribute_id, license_attribute_license_value
		from openjson(@license_attribute_json)
		with (license_attribute_id int '$.license_attribute_id',
			license_attribute_license_value int '$.license_attribute_license_value')

		-- 2.4) insert partner_billing_report_override
		insert into partner_billing_report_override(partner_billing_report_id, license_category_id)
		select @partner_billing_report_id, license_category_id
		from openjson(@usage_override_json)
		with (license_category_id int '$.license_category_id')

		-- 2.5) usp_partner_process_partner_billing
		exec usp_partner_process_partner_billing @partner_billing_report_id

	
		select @partner_id = null, @partner_billing_report_name = null, @site_id = null, @configuration_json = null
		select @partner_billing_id = @partner_billing_id + 1
		end


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_insert_partner_billing_order]

(
	@partner_billing_report_id INT
)

/*	
	DATE		AUTHOR		REMARKS
	2020-08-10	esmart		Initial creation.
	2020-09-09	esmart		Fixes - 0 qauntity, duplicate contracting entity, additional order_extensions, and purchase_order
	2020-09-17	esmart		Add usage_pricing_model, retention_model, product_platform to item aggregation
	2020-10-02	esmart		Extend fn_product_select_profile
    2021-12-02	g.lagos		request @merchant_id from PHP, cannot hardcode '1' webroot anymore SMCI=6012 -- REVERSED by BUG SMCI-6358
	2022-01-07	gblandford	SMCI-6216 - Add retention_term
	2022-02-09	g.lagos		Resolving BUG SMCI-6358, finding @payment_merchant of the order before uptaing header
	2022-08-31	abelenkiy	Added payment_merchant_id to @billing_item table; currency_code is now selected globally 
							in section 1.3 and used with location_code in section 2.1 to get payment_merchant_id;
							Enhanced error handling
	2022-10-26	gblandford	ALM-3478 - Correct multiple order line items being created because of different payment merchnants by
							consolidating rows into @order_item table
							- code also fixes the line_item counting over different orders within the same block
	2023-03-14	gblandford	https://jira.opentext.com/browse/ECOM-895 - In cases where we have > 1 webroot_entitiy, consolidate into single order
							- WI will translate to WIL where both exist
							- pre-select partner_billing rows for efficiency and to avoid repetitive webroot_entity criteria
							- added dbo. schemas and some clean-up for clarity
							- reviewed order_extension creation around webroot_entity and WIL for previously WI classification will
							  resolve correctly. e.g. WIL, Canada or US, will now resolve as Webroot International Ltd US
	2025-07-15	jberry		US-4396390 - added sap_material_number as a parameter for the call to fn_product_select_profile.  NULL will always be passed for this procedure
	2026-06-15   mgolla		US-5418343 - Retrieved partner-specific PO number details from App Config(section 1.2.1) and added a       											CASE statement in section 2.9 (Purchase Order) to insert the corresponding PO number into the 										   purchase_order table.

	DESCRIPTION
	Insert orders for approved partner_billing_reports
*/

AS


SET NOCOUNT ON				

BEGIN TRY

	DECLARE @message NVARCHAR(4000),
			@order_header_id INT, 
			@site_id VARCHAR(65),
			@webroot_entity VARCHAR(3), 
			@temp_id INT, 
			@total_ids INT, 
			@vendor_order_code_prefix VARCHAR(5), 
			@vendor_order_code VARCHAR(100), 
			@vendor_order_id INT,
			@billing_date DATETIME, 
			@partner_id INT, 
			@currency_id INT, 
			@country_id INT, 
			@payment_header_id INT,
            @currency_code VARCHAR(3),
			@po_number VARCHAR(50)

	DECLARE @partner_billing TABLE (
		[partner_billing_id] [INT] NOT NULL,
		[partner_billing_report_id] [INT] NOT NULL,
		[customer_id] [INT] NOT NULL,
		[customer_code] [VARCHAR](64) NOT NULL,
		[company_name] [NVARCHAR](100) NOT NULL,
		[location_code] [VARCHAR](3) NOT NULL,
		[state] [NVARCHAR](3) NOT NULL,
		[webroot_entity] [VARCHAR](3) NOT NULL,
		[reseller_customer_id] [INT] NULL,
		[reseller_customer_code] [VARCHAR](64) NULL,
		[reseller_company_name] [NVARCHAR](100) NULL,
		[reseller_location_code] [VARCHAR](3) NULL,
		[reseller_state] [NVARCHAR](3) NULL,
		[license_id] [INT] NOT NULL,
		[keycode] [VARCHAR](40) NOT NULL,
		[keycode_age] [INT] NOT NULL,
		[order_header_id] [INT] NOT NULL,
		[order_date] [DATETIME] NOT NULL,
		[product_id] [INT] NULL,
		[license_category_id] [TINYINT] NULL,
		[license_seats] [INT] NOT NULL,
		[retail_price] [MONEY] NOT NULL,
		[extended_amount] [MONEY] NOT
 NULL,
		[usage_seats] [INT] NOT NULL,
		[usage_price] [MONEY] NOT NULL,
		[usage_extended_amount] [MONEY] NOT NULL,
		[total_extended_amount] [MONEY] NOT NULL,
		[cap_amount] [MONEY] NOT NULL,
		[last_modified_date] [DATETIME] NOT NULL,
		[license_attribute_license_value] [INT] NULL,
		[total_cap_amount] [MONEY] NULL,
		[currency_id] [INT] NULL,
		[partner_pricing_model_id] [TINYINT] NULL,
		[total_seats] [INT] NULL,
		[company_id] [INT] NULL
	);

	declare @partner_billing_order table (temp_id int identity(1,1), partner_billing_report_id int, 
		billing_date datetime, webroot_entity varchar(3), site_id varchar(65), locale char(5), vendor_order_id int, 
		order_header_id int) 

	declare @billing_item table (line_item int identity(1,1), license_category_id tinyint, retail_price money, 
		quantity int, item_total money, effective_date datetime, capability_expiration_date datetime, 
		usage_pricing_model_id tinyint, retention_model_id tinyint, retention_term tinyint, 
		product_platform_id tinyint, payment_merchant_id tinyint)

	declare @order_item table (
        line_item int, 
        product_id int, 
        quantity int, 
        list_price money, 
        unit_price money, 
        tax money null, 
        order_item_offer_id varchar(65) null, 
        order_item_offer_amount money null, 
        item_total money null, 
        tax_exempt bit null, 
        order_item_status_id int, 
        item_bundle_id int, 
        effective_date datetime, 
        capability_expiration_date datetime, 
        order_item_update_type_id tinyint,
        item_hierarchy_id TINYINT
	);

	declare @order_extensions table (order_extension_type_id tinyint, order_extension_value varchar(100))

	declare @next_id table (invoice_code_int int)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0.1) insert @partner_billing
	insert into @partner_billing (
	    partner_billing_id,
	    partner_billing_report_id,
	    customer_id,
	    customer_code,
	    company_name,
	    location_code,
	    state,
	    webroot_entity,
	    reseller_customer_id,
	    reseller_customer_code,
	    reseller_company_name,
	    reseller_location_code,
	    reseller_state,
	    license_id,
	    keycode,
	    keycode_age,
	    order_header_id,
	    order_date,
	    product_id,
	    license_category_id,
	    license_seats,
	    retail_price,
	    extended_amount,
	    usage_seats,
	    usage_price,
	    usage_extended_amount,
	    total_extended_amount,
	    cap_amount,
	    last_modified_date,
	    license_attribute_license_value,
	    total_cap_amount,
	    currency_id,
	    partner_pricing_model_id,
	    total_seats,
	    company_id
	)
	select 
		b.partner_billing_id,
	    b.partner_billing_report_id,
	    b.customer_id,
	    b.customer_code,
	    b.company_name,
	    b.location_code,
	    b.state,
		b.webroot_entity,
	    b.reseller_customer_id,
	    b.reseller_customer_code,
	    b.reseller_company_name,
	    b.reseller_location_code,
	    b.reseller_state,
	    b.license_id,
	    b.keycode,
	    b.keycode_age,
	    b.order_header_id,
	    b.order_date,
	    b.product_id,
	    b.license_category_id,
	    b.license_seats,
	    b.retail_price,
	    b.extended_amount,
	    b.usage_seats,
	    b.usage_price,
	    b.usage_extended_amount,
	    b.total_extended_amount,
	    b.cap_amount,
	    b.last_modified_date,
	    b.license_attribute_license_value,
	    b.total_cap_amount,
	    b.currency_id,
	    b.partner_pricing_model_id,
	    b.total_seats,
	    b.company_id
	from dbo.partner_billing b
	where b.partner_billing_report_id = @partner_bil
ling_report_id;

	-- 1.0.2) check if we have > webroot_entity
	if (select count(distinct webroot_entity) from @partner_billing) > 1 begin
    
		update b 
			set b.webroot_entity = case
							when b.webroot_entity IN ('WI', 'WIL') then 'WIL'
							else b.webroot_entity 
							end
		from @partner_billing b
		
	end 

	-- 1.1) insert @partner_billing_order
	insert into @partner_billing_order(
		partner_billing_report_id
		, billing_date
		, webroot_entity
		, site_id
		, locale
	)
	select distinct 
		r.partner_billing_report_id
		, r.billing_date
		, b.webroot_entity
		, case
			when a.license_attribute_id = 200 then 'RESELLER'
			else 'MSP' end as site_id, 
		'en_US' as locale
	from dbo.partner_billing_report r 
	inner join @partner_billing b
		on b.partner_billing_report_id = r.partner_billing_report_id
	left join dbo.partner_billing_license_attribute a
		on a.partner_billing_report_id = r.partner_billing_report_id
	where r.partner_billing_report_id = @partner_billing_report_id

	-- 1.2) select @partner_id
	select @partner_id = r.partner_id
	from dbo.partner_billing_report r
	where r.partner_billing_report_id = @partner_billing_report_id

	-- 1.2.1) Retrieving the partner-specific PO number from App Config.
	SELECT @po_number=f.value
	FROM [dbo].[fn_app_config_select_key_values]('PURCHASE_ORDER_NUMBER', 'AGGREGATOR_BILLING') f
    WHERE  f.[key] = @partner_id

	-- 1.3) @currency_id
	select @currency_id = c.currency_id, @currency_code = c.currency_code
	from dbo.partner_configuration_partner cp 
	inner JOIN dbo.currency c
		on cp.configuration_value = c.currency_code
	where cp.partner_id = @partner_id and cp.partner_configuration_id = 15

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert reports
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @temp_id = 1, @total_ids = max(temp_id) from @partner_billing_order

	WHILE @total_ids >= @temp_id
		BEGIN

			-- 2.1) @billing_item
			select @webroot_entity = webroot_entity, @billing_date = billing_date, @site_id = site_id
			from @partner_billing_order where temp_id = @temp_id

			insert into @billing_item(license_category_id, retail_price, quantity, item_total, effective_date, 
				capability_expiration_date, usage_pricing_model_id, retention_model_id, retention_term, 
				product_platform_id, payment_merchant_id)

			select b.license_category_id, b.retail_price, sum(b.total_seats) as quantity, 
				sum(b.total_extended_amount) as item_total, dateadd(mm,-1,@billing_date) as effective_date, 
				@billing_date as capability_expiration_date, p.usage_pricing_model_id, p.retention_model_id, 
				p.retention_term, p.product_platform_id, sm.payment_merchant_id
			from @partner_billing b
				outer apply dbo.fn_license_select_license_profile(b.license_id) p
				outer apply dbo.fn_select_merchant(b.location_code, @currency_code, b.license_category_id) sm
			where b.partner_billing_report_id = @partner_billing_report_id 
				and b.webroot_entity = @webroot_entity 
				and b.license_category_id = p.license_category_id
			group by b.license_category_id, p.usage_pricing_model_id, p.retention_model_id, p.retention_term, 
				p.product_platform_id, b.retail_price, sm.payment_merchant_id
			having sum(b.total_seats) > 0
			order by b.license_category_id, p.usage_pricing_model_id, p.retention_model_id, p.retention_term, 
				p.product_platform_id, b.retail_price

			IF @@ROWCOUNT > 0 -- only create orders with quantity > 0
				BEGIN

				-- 2.2) insert vendor_order
				insert into @next_id(invoice_code_int)
				exec dbo.usp_next_id @Type=3

				select @vendor_order_code_prefix = vendor_order_code_prefix from dbo.cart_site_id_order_code_prefix wh
ere site_id = @site_id
				select @vendor_order_code = @vendor_order_code_prefix + convert(varchar(8),invoice_code_int) from @next_id

				insert into dbo.vendor_order(vendor_id, vendor_order_code)
				values(1,@vendor_order_code)

				select @vendor_order_id = scope_identity()

				update @partner_billing_order set vendor_order_id = @vendor_order_id where temp_id = @temp_id

				-- 2.3) insert order_header
				insert into dbo.order_header(vendor_order_id, total_amount, sub_total_amount, tax_total, payment_method_id, vendor_order_date, locale, exchange_rate, site_id, site_url, order_status_id)
				select b.vendor_order_id, 0 as total_amount, 0 as sub_total_amount, 0 as tax_total, 5 as payment_method_id, b.billing_date, b.locale, 0 as exchange_rate, b.site_id, b.site_id, 1 as order_status_id
				from @partner_billing_order b
				where b.temp_id = @temp_id

				select @order_header_id = scope_identity()

				update @partner_billing_order set order_header_id = @order_header_id where temp_id = @temp_id

					-- 2.3.1) order_currency
					insert into dbo.order_currency(order_header_id, currency_id) 
					values(@order_header_id,@currency_id)
					
					-- 2.3.2) payment_header
					insert into dbo.payment_header(payment_merchant_id, payment_status_id, payment_method_id, currency_id) 
					select distinct bi.payment_merchant_id,
						6, -- subscribed
						5, -- PurchaseOrder
						@currency_id
					from @billing_item bi

					select @payment_header_id = scope_identity()

					insert into dbo.order_payment_header(order_header_id, payment_header_id)
					values(@order_header_id,@payment_header_id)

				-- 2.4) insert order_item

					insert into @order_item	(
					    line_item,
					    product_id,
					    quantity,
					    list_price,
					    unit_price,
					    tax,
					    order_item_offer_id,
					    order_item_offer_amount,
					    item_total,
					    tax_exempt,
					    order_item_status_id,
					    item_bundle_id,
					    effective_date,
					    capability_expiration_date,
					    order_item_update_type_id,
					    item_hierarchy_id
					)
					select  
                        row_number() over (order by min(b.line_item)) as line_item, 
                        f.product_id, 
                        sum(b.quantity), 
                        b.retail_price, 
                        b.retail_price, 
                        0, 
                        0, 
                        null, 
                        sum(b.item_total), 
                        0, 
                        1, 
                        1, 
                        b.effective_date, 
                        b.capability_expiration_date, 
                        2, 
                        1 
				from @billing_item b
				cross apply dbo.fn_product_select_profile(300,b.license_category_id,1,1,null,0,1,3,b.usage_pricing_model_id,b.retention_model_id,b.product_platform_id,null) f
				group by b.license_category_id
					, b.usage_pricing_model_id
					, b.retention_model_id
					, b.product_platform_id
					, f.product_id, b.retail_price
					, b.effective_date, b.capability_expiration_date

				insert into dbo.order_item (
					order_header_id, 
                    line_item, 
                    product_id, 
                    quantity, 
                    list_price, 
                    unit_price, 
                    tax, 
                    order_item_offer_id, 
                    order_item_offer_amount, 
                    item_total, 
                    tax_exempt, 
                    order_item_status_id, 
                    item_bundle_id, 
                    effective_date, 
                    capability_expiration_date, 
                    order_item_update_type_id,
                    item_hierarchy_id
				)
				select @order_header_id, 
                    line_item, 
                    product_id, 
                    
quantity, 
                    list_price, 
                    unit_price, 
                    tax, 
                    order_item_offer_id, 
                    order_item_offer_amount, 
                    item_total, 
                    tax_exempt, 
                    order_item_status_id, 
                    item_bundle_id, 
                    effective_date, 
                    capability_expiration_date, 
                    order_item_update_type_id,
                    item_hierarchy_id
                from @order_item

				-- 2.5) insert customer_order and order_company
				insert into dbo.customer_order(customer_id, order_header_id, customer_type_id)
				select cc.customer_id, @order_header_id, t.customer_type_id
				from dbo.partner_customer pc
				inner join dbo.customer_company cc 
					on cc.customer_id = pc.customer_id 
				cross apply dbo.customer_type t
				where pc.partner_id = @partner_id and t.customer_type_id in (1,2,4)

				insert into dbo.order_company(order_header_id, company_id, order_company_type_id, customer_id)
				select @order_header_id, cc.company_id, t.order_company_type_id, cc.customer_id
				from dbo.partner_customer pc
				inner join dbo.customer_company cc 
					on cc.customer_id = pc.customer_id 
				cross apply dbo.order_company_type t
				where pc.partner_id = @partner_id and t.order_company_type_id in (1,2,4)

				-- 2.5.1) @country_id
				select @country_id = ca.country_id
				from dbo.order_company oc
				inner join dbo.company_address ca 
					on ca.company_id = oc.company_id and ca.address_status_id = 1 and ca.address_class_id = 1
				where oc.order_header_id = @order_header_id and oc.order_company_type_id = 2

				-- 2.6) insert order_extension
				insert @order_extensions(order_extension_type_id, order_extension_value) values(1,'Bill Up Front')
				insert @order_extensions(order_extension_type_id, order_extension_value) values(2,'From Start Day of Month')
				insert @order_extensions(order_extension_type_id, order_extension_value) values(3,'No')
				insert @order_extensions(order_extension_type_id, order_extension_value) values(7,'PO #')
				insert @order_extensions(order_extension_type_id, order_extension_value) values(8,'No')
				insert @order_extensions(order_extension_type_id, order_extension_value) 
					select 14, case when @site_id = 'RESELLER' then 'Channel Aggregator' else 'MSP Aggregator' end
				insert @order_extensions(order_extension_type_id, order_extension_value) select 15, p.account_owner_id from partner p where p.partner_id = @partner_id
				insert @order_extensions(order_extension_type_id, order_extension_value) 
					select 16, case 
							when @webroot_entity = 'WI' then 'Webroot Software, Inc.' 
							when @webroot_entity = 'WIL' and @country_id in (1,39) then 'Webroot International Ltd US'
							when @webroot_entity = 'WIL' and @country_id in (14) then 'Webroot International Ltd AU'
							when @webroot_entity = 'WIL' and @country_id not in (1,14,39) then 'Webroot International Ltd UK'
							else 'Webroot International Ltd US' 
							END
				insert @order_extensions(order_extension_type_id, order_extension_value) values(17,'Aggregator')


				insert into dbo.order_extension(order_header_id, order_extension_type_id, order_extension_value)
				select @order_header_id, order_extension_type_id, order_extension_value
				from @order_extensions

				-- 2.7) insert partner_billing_order
				insert into dbo.partner_billing_order(partner_billing_report_id, order_header_id)
				values(@partner_billing_report_id,@order_header_id)

				-- 2.8) update order_header
				update h1
				set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount
				from dbo.order_header h1
				inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), total_amount = sum(i.item_total)
						from dbo.order_header h 
						inner join dbo.order_item i
							on i.order_header_id = 
h.order_header_id
						where h.order_header_id = @order_header_id
						group by h.order_header_id) x
					on x.order_header_id = h1.order_header_id

				-- 2.9) purchase_order
				insert into dbo.purchase_order(order_header_id, purchase_order, purchase_order_date)
				SELECT @order_header_id,
				       CASE
				           WHEN @po_number IS NOT NULL THEN
				               @po_number
				           ELSE
				               DATENAME(MONTH, @billing_date) + ' PO'
				       END,
				       @billing_date


				select @order_header_id as order_header_id, @vendor_order_code as vendor_order_code
			end

			delete from @next_id
			delete from @billing_item
			delete from @order_extensions
			delete from @order_item
			select @vendor_order_code = null, @vendor_order_id = null
			select @temp_id = @temp_id + 1
	end

end try

begin catch

	declare	@error_severity int = error_severity(), @error_state int = error_state()
	set @message = 'partner_billing_report_id = ' + convert(varchar(20), isnull(@partner_billing_report_id, 'null')) 
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state)

	insert into dbo.DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, 
		ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, 
		@@servername, db_name(), suser_name()

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_report]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_insert_partner_billing_report]

(
		@partner_id int,
		@partner_billing_report_name varchar(100),
		@billing_date datetime, 
		@partner_billing_type_id tinyint = 2,
		@insert_by varchar(20) = null,
		@license_attribute_license_values varchar(100) = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-06-14		esmart			Initial creation
	2016-10-21		esmart			Add license_attribute_license_value
	
	DESCRIPTION
	insert partner billing report
*/

as

	set nocount on	

	declare	@partner_billing_report_id int,
			@sql_string varchar(4000),
			@command varchar(1000),
			@task_number varchar(20),	
			@db_name varchar(100),
			@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @insert_by
	if @insert_by is null
		begin
		select @insert_by = suser_name()
		end

	-- 1.1) insert partner_billing_report
	insert into partner_billing_report (partner_id, partner_billing_report_name, partner_billing_type_id, billing_date, insert_by, modified_by)
	values(@partner_id, @partner_billing_report_name, @partner_billing_type_id, @billing_date, @insert_by, @insert_by)

	select @partner_billing_report_id = scope_identity()

		-- 1.1.1) insert partner_billing_license_attribute
		if @license_attribute_license_values is not null
			begin
				insert into partner_billing_license_attribute(partner_billing_report_id,license_attribute_id,license_attribute_license_value)
				select @partner_billing_report_id, v.license_attribute_id, v.license_attribute_license_value
				from license_attribute_license_value v
				where v.license_attribute_license_value in (select integer_value from dbo.fn_integer_string_to_table(@license_attribute_license_values))
			end


	-- 1.2) insert service broker
	select @task_number = @partner_billing_report_id
	select @db_name = db_name()
	
	select @sql_string = 
		'insert into tasks..task_table (task_number, Command, NoTransaction) ' + 
		' values(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_partner_process_partner_billing ' + convert(varchar(10),@partner_billing_report_id) + '''' + ',0) '

	--select @sql_string

	exec(@sql_string)	

	exec tasks..QueueTasksProc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_revenue_report]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_partner_insert_partner_billing_revenue_report] (
	@report_date DATE = NULL,
	@opt_args VARCHAR(20) = '' -- 'debug', 'rerun',

)

/*	
	DATE			AUTHOR		REMARKS
	2025-01-31		gblandford	Initial creation
								For auditing purposes as part of https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4390153


	DESCRIPTION
	Produces a revenue comparison report for the current billing cycle of RMM aggregator reports.

	The report will detail the license and usage revenue per license for the current billing cycle and then provide the prior months
	equivalent license and usage reveue. In addition, it provides period averages (set to 3 months, including the prior month).

	These prior month and period averages can be used to identfy drop-off by partner, or by individual license.

	The report can be filtered on partner, site (MSP/RESELLER) and license category.
	
	We are going to EXCLUDE WORTMANN for now, unless specified individually as the seats counts are a mess

*/

AS
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	SET NOCOUNT ON

	BEGIN TRY

		IF @report_date IS NULL SET @report_date = GETDATE();

		IF EXISTS( SELECT 1 FROM dbo.partner_billing_revenue_fact WHERE report_date = @report_date ) BEGIN

				IF @opt_args LIKE '%rerun%' BEGIN

						BEGIN TRANSACTION

							DELETE fact
							FROM dbo.partner_billing_revenue_order_fact fact
							WHERE fact.report_date = @report_date

							DELETE fact
							FROM dbo.partner_billing_revenue_fact fact
							WHERE fact.report_date = @report_date

						COMMIT WORK;

					END
				ELSE BEGIN
						RETURN 0;
					END
			END;

		DECLARE @partner_billing_dates TABLE (
			dataset VARCHAR(20),
			partner_id INT,
			site_id VARCHAR(20),
			partner_billing_report_id INT,
			billing_date DATE
		);
		INSERT INTO @partner_billing_dates (
			dataset,
			partner_id,
			site_id,
			partner_billing_report_id,
			billing_date
		)
		SELECT 
			'current',
			pbr.partner_id,
			pbr.site_id,
			MAX( pbr.partner_billing_report_id ),
			MAX( pbr.billing_date )
		FROM dbo.partner_billing_report pbr
		WHERE pbr.billing_date >= DATEADD( day, -120, GETDATE()  )

		GROUP BY pbr.partner_id, pbr.site_id 
		ORDER BY pbr.partner_id, MAX(pbr.partner_billing_report_id);

		IF @opt_args LIKE '%debug%' BEGIN
				SELECT * FROM @partner_billing_dates
			END

		/*
		|
		|	Drop and Create empty reporting tables
		|
		*/
		DROP TABLE IF EXISTS #partner_billing_revenue_detail;
		DROP TABLE IF EXISTS #partner_billing_revenue_detail_prior_month;
		DROP TABLE IF EXISTS #partner_billing_revenue_detail_period_average;
		DROP TABLE IF EXISTS #partner_billing_revenue_fact;
		DROP TABLE IF EXISTS #partner_billing_revenue_order_fact;
		DROP TABLE IF EXISTS #partner_billing_revenue_report;
		
		CREATE TABLE #partner_billing_revenue_report (
			partner_billing_revenue_report_id INT IDENTITY (1, 1),
			report_date DATE DEFAULT GETDATE(),
			partner_id INT,
			partner_name VARCHAR(50),
			site_id VARCHAR(20),
			currency_code VARCHAR(10),
			license_id INT,
			keycode VARCHAR(20),
			license_category_name VARCHAR(10),

			current_billing_date DATE,
			current_license_seats INT,
			current_unit_price DECIMAL(10, 2),
			current_total DECIMAL(10, 2),
			current_usage_seats INT,
			current_usage_price DECIMAL(10, 2),
			current_usage_total DECIMAL(10, 2),
			current_billing_total DECIMAL(10, 2),
			current_actual_billed_order_total DECIMAL(10, 2),

			prior_billing_date DATE,
			prior_license_seats INT,
			prior_unit_price DECIMAL(10, 2),
			prior_total DECIMAL(10, 2),
			prior_usage_seats INT,
			prior_usage_pri
ce DECIMAL(10, 2),
			prior_usage_total DECIMAL(10, 2),
			prior_billing_total DECIMAL(10, 2),
			prior_actual_billed_order_total DECIMAL(10, 2),

			period_reports INT,
			period_billing_cycles INT,

			period_from DATE,
			period_to DATE,

			average_license_seats INT,
			average_retail_price DECIMAL(10, 2),
			average_extended_amount DECIMAL(10, 2),
			average_usage_seats INT,
			average_usage_price DECIMAL(10, 2),
			average_usage_extended_amount DECIMAL(10, 2),
			average_billing_total DECIMAL(10, 2),
			average_actual_billed_order_total DECIMAL(10, 2)

		);
		
		CREATE TABLE #partner_billing_revenue_order_fact (
			partner_billing_revenue_order_fact_id INT IDENTITY (1, 1),
			partner_billing_order_id INT,
			partner_billing_report_id INT,
			partner_id INT,
			site_id VARCHAR(20),
			currency_id INT,
			billing_date DATE,
			order_header_id INT,
			license_category_id INT,
			order_total DECIMAL(10, 2)
		);


		CREATE TABLE #partner_billing_revenue_detail (
			partner_billing_revenue_detail_id INT IDENTITY (1, 1),
			partner_billing_report_id INT,
			partner_billing_order_id INT,
			order_header_id INT,
			partner_id INT,
			site_id VARCHAR(20),
			billing_date DATE,
			partner_billing_id INT,
			currency_id INT,
			license_id INT,
			license_category_id INT,
			license_seats INT,
			unit_price DECIMAL(10, 2),
			total DECIMAL(10, 2),
			usage_seats INT,
			usage_price DECIMAL(10, 2),
			usage_total DECIMAL(10, 2),
			billing_total DECIMAL(10, 2)
		);

		CREATE TABLE #partner_billing_revenue_detail_prior_month (
			partner_billing_revenue_detail_prior_month_id INT IDENTITY (1, 1),
			partner_billing_report_id INT,
			partner_billing_order_id INT,
			order_header_id INT,
			partner_id INT,
			site_id VARCHAR(20),
			billing_date DATE,
			partner_billing_id INT,
			currency_id INT,
			license_id INT,
			license_category_id INT,
			license_seats INT,
			unit_price DECIMAL(10, 2),
			total DECIMAL(10, 2),
			usage_seats INT,
			usage_price DECIMAL(10, 2),
			usage_total DECIMAL(10, 2),
			billing_total DECIMAL(10, 2)
		);

		CREATE TABLE #partner_billing_revenue_detail_period_average (
			partner_billing_revenue_detail_period_average_id INT IDENTITY (1, 1),
			partner_id INT,
			site_id VARCHAR(20),
			currency_id INT,
			license_category_id INT,
			license_id INT,

			number_reports INT,
			billing_cycles INT,

			billing_date_min DATE,
			billing_date_max DATE,

			average_license_seats INT,
			average_retail_price DECIMAL(10, 2),
			average_extended_amount DECIMAL(10, 2),
			average_usage_seats INT,
			average_usage_price DECIMAL(10, 2),
			average_usage_extended_amount DECIMAL(10, 2),
			average_total_extended_amount DECIMAL(10, 2),

			average_billed_order_total DECIMAL(10, 2)
		);
	
		CREATE TABLE #partner_billing_revenue_fact (
			partner_billing_revenue_fact_id INT IDENTITY(1, 1),
			partner_id INT,
			site_id VARCHAR(20),
			currency_id INT,
			license_id INT,
			license_category_id INT,

			current_billing_date DATE,

			current_license_seats INT, 
			current_unit_price DECIMAL(10, 2),
			current_total DECIMAL(10, 2),
			current_usage_seats INT,
			current_usage_price DECIMAL(10, 2),
			current_usage_total DECIMAL(10, 2),
			current_billing_total DECIMAL(10, 2),

			prior_billing_date DATE,

			prior_license_seats INT,
			prior_unit_price DECIMAL(10, 2),
			prior_total DECIMAL(10, 2),
			prior_usage_seats INT,
			prior_usage_price DECIMAL(10, 2),
			prior_usage_total DECIMAL(10, 2),
			prior_billing_total DECIMAL(10, 2),

			period_reports INT,
			period_billing_cycles INT,

			period_from DATE,
			period_to DATE,
			average_license_seats INT,
			average_retail_price DECIMAL(10, 2),
			average_extended_amount DECIMAL(10, 2),
			average_usage_seats INT,
			average_usage_price DECIMAL(10, 2),
			average_usage_extended_amount DECIMAL(10, 2),
			average_billing_total  DECIMAL(10,
 2)
		);

		/*
		|
		|	Get CURRENT billing detail for all partner reports
		|
		*/ 
		INSERT INTO #partner_billing_revenue_detail (
			partner_billing_report_id,
			partner_billing_order_id,
			order_header_id,
			partner_id,
			site_id,
			billing_date,
			partner_billing_id,
			currency_id,
			license_id,
			license_category_id,
			license_seats,
			unit_price,
			total,
			usage_seats,
			usage_price,
			usage_total,
			billing_total
		)
		SELECT
			pbr.partner_billing_report_id,
			pbo.partner_billing_order_id,
			oh.order_header_id,
			pbr.partner_id,
			pbr.site_id,
			pbr.billing_date,
			pb.partner_billing_id,
			pb.currency_id,
			pb.license_id,
			pb.license_category_id,
			pb.license_seats,
			pb.retail_price,
			pb.extended_amount,
			pb.usage_seats,
			pb.usage_price,
			pb.usage_extended_amount,
			pb.total_extended_amount

		FROM dbo.partner_billing pb
			INNER JOIN dbo.partner_billing_report pbr
				ON pbr.partner_billing_report_id = pb.partner_billing_report_id
			INNER JOIN @partner_billing_dates pbd
				ON pbd.partner_billing_report_id = pb.partner_billing_report_id
					AND pbd.partner_id = pbr.partner_id
			LEFT JOIN dbo.partner_billing_order pbo
				ON pbo.partner_billing_report_id = pbr.partner_billing_report_id
			LEFT JOIN dbo.order_header oh
				ON oh.order_header_id = pbo.order_header_id
		WHERE pbd.dataset = 'current'
			AND pb.total_extended_amount > 0
		
		ORDER BY pbd.partner_billing_report_id, pb.partner_billing_id

		IF @opt_args LIKE '%debug%' BEGIN

				SELECT 
					detail.partner_billing_revenue_detail_id,
					detail.partner_billing_report_id,
					detail.partner_billing_order_id,
					detail.order_header_id,
					detail.partner_id,
					detail.site_id,
					detail.billing_date,
					detail.partner_billing_id,
					detail.currency_id,
					detail.license_id,
					detail.license_category_id,
					detail.license_seats,
					detail.unit_price,
					detail.total,
					detail.usage_seats,
					detail.usage_price,
					detail.usage_total,
					detail.billing_total
		
				FROM #partner_billing_revenue_detail detail
				ORDER BY partner_billing_revenue_detail_id;
			END;

		/*
		|
		| Get PRIOR month detail
		|
		*/
		INSERT INTO @partner_billing_dates (
			dataset,
			partner_id,
			site_id,
			partner_billing_report_id,
			billing_date
		) 
		SELECT 
			'prior',
			pbr.partner_id,
			pbr.site_id,
			MAX( pbr.partner_billing_report_id ),
			MAX( pbr.billing_date )
		FROM dbo.partner_billing_report pbr
			INNER JOIN #partner_billing_revenue_detail detail
				ON detail.partner_id = pbr.partner_id
					AND detail.site_id = pbr.site_id
		WHERE pbr.billing_date = DATEADD( MONTH, -1, detail.billing_date )

		GROUP BY pbr.partner_id, pbr.site_id 
		ORDER BY pbr.partner_id, MAX(pbr.partner_billing_report_id);

		IF @opt_args LIKE '%debug%' BEGIN
				SELECT * FROM @partner_billing_dates
			END

		INSERT INTO #partner_billing_revenue_detail_prior_month (
			partner_billing_report_id,
			partner_billing_order_id,
			order_header_id,
			partner_id,
			site_id,
			billing_date,
			partner_billing_id,
			currency_id,
			license_id,
			license_category_id,
			license_seats,
			unit_price,
			total,
			usage_seats,
			usage_price,
			usage_total,
			billing_total
		)
		SELECT
			pbr.partner_billing_report_id,
			pbo.partner_billing_order_id,
			oh.order_header_id,
			pbr.partner_id,
			pbr.site_id,
			pbr.billing_date,
			pb.partner_billing_id,
			pb.currency_id,
			pb.license_id,
			pb.license_category_id,
			ISNULL( pb.license_seats, 0 ) AS license_seats,
			ISNULL( pb.retail_price, 0 ) AS retail_price,
			ISNULL( pb.extended_amount, 0 ) AS extended_amount,
			ISNULL( pb.usage_seats, 0 ) AS usage_seats,
			ISNULL( pb.usage_price, 0 ) AS usage_price,
			ISNULL( pb.usage_extended_amount, 0 ) AS usage_extended_amount,
			ISNULL( pb.total_extended_amount, 0 ) AS t
otal_extended_amount
			
		FROM dbo.partner_billing pb
			INNER JOIN dbo.partner_billing_report pbr
				ON pbr.partner_billing_report_id = pb.partner_billing_report_id
			INNER JOIN @partner_billing_dates pbd
				ON pbd.partner_billing_report_id = pb.partner_billing_report_id
					AND pbd.partner_id = pbr.partner_id
			LEFT JOIN dbo.partner_billing_order pbo
				ON pbo.partner_billing_report_id = pbr.partner_billing_report_id
			LEFT JOIN dbo.order_header oh
				ON oh.order_header_id = pbo.order_header_id
		WHERE pbd.dataset = 'prior'
			AND pb.total_extended_amount > 0	

		IF @opt_args LIKE '%debug%' BEGIN

				SELECT 
					prior_month.partner_billing_revenue_detail_prior_month_id,
					prior_month.partner_billing_report_id,
					prior_month.partner_billing_order_id,
					prior_month.order_header_id,
					prior_month.partner_id,
					prior_month.site_id,
					prior_month.billing_date,
					prior_month.partner_billing_id,
					prior_month.currency_id,
					prior_month.license_id,
					prior_month.license_category_id,
					prior_month.license_seats,
					prior_month.unit_price,
					prior_month.total,
					prior_month.usage_seats,
					prior_month.usage_price,
					prior_month.usage_total,
					prior_month.billing_total

				FROM #partner_billing_revenue_detail_prior_month prior_month
				ORDER BY prior_month.partner_billing_revenue_detail_prior_month_id;
			END;

		/*
		|
		| Get PERIOD AVERAGE detail
		|
		*/
		INSERT INTO @partner_billing_dates (
			dataset,
			partner_id,
			site_id,
			partner_billing_report_id,
			billing_date
		) 
		SELECT 
			'period_average',
			pbr.partner_id,
			pbr.site_id,
			MAX( pbr.partner_billing_report_id ),
			pbr.billing_date
		FROM dbo.partner_billing_report pbr
			INNER JOIN #partner_billing_revenue_detail detail
				ON detail.partner_id = pbr.partner_id
					AND detail.site_id = pbr.site_id
		WHERE pbr.billing_date IN (
										SELECT 
												DATEADD( MONTH, -1, detail.billing_date )
											UNION
										SELECT 
												DATEADD( MONTH, -2, detail.billing_date )
											UNION
										SELECT
												DATEADD( MONTH, -3, detail.billing_date )
								)

		GROUP BY pbr.partner_id, pbr.site_id, pbr.billing_date 
		ORDER BY pbr.partner_id, MAX(pbr.partner_billing_report_id);

		IF @opt_args LIKE '%debug%' BEGIN
				SELECT * FROM @partner_billing_dates
			END

		INSERT INTO #partner_billing_revenue_detail_period_average (
			partner_id,
			site_id,
			currency_id,
			license_category_id,
			license_id,

			number_reports,
			billing_cycles,

			billing_date_min,
			billing_date_max,

			average_license_seats,
			average_retail_price,
			average_extended_amount,
	
			average_usage_seats,
			average_usage_price,
			average_usage_extended_amount,

			average_total_extended_amount,

			average_billed_order_total
		)
		SELECT
			pbr.partner_id,
			pbr.site_id,
			pb.currency_id,
			pb.license_category_id,
			pb.license_id,

			COUNT(pbr.partner_billing_report_id) AS number_reports,

			COUNT( pbr.billing_date ) AS billing_cycles,

			MIN( pbr.billing_date ) AS billing_date_min,
			MAX( pbr.billing_date ) AS billing_date_max,

			SUM( ISNULL( pb.license_seats, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_license_seats,
			SUM( ISNULL( pb.retail_price, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_retail_price,
			SUM( ISNULL( pb.extended_amount, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_extended_amount,

			SUM( ISNULL( pb.usage_seats, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_usage_seats,
			SUM( ISNULL( pb.usage_price, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_usage_price,
			SUM( ISNULL( pb.usage_extended_amount, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_usage_extended_amount,

			SUM( ISNULL( pb.total_extended_amount, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS
 average_total_extended_amount,
			SUM( ISNULL( pb.total_extended_amount, 0 ) ) / COUNT(pbr.partner_billing_report_id ) AS average_total_extended_amount


		FROM dbo.partner_billing pb
			INNER JOIN dbo.partner_billing_report pbr
				ON pbr.partner_billing_report_id = pb.partner_billing_report_id
			INNER JOIN @partner_billing_dates pbd
				ON pbd.partner_billing_report_id = pb.partner_billing_report_id
					AND pbd.partner_id = pbr.partner_id
			LEFT JOIN dbo.partner_billing_order pbo
				ON pbo.partner_billing_report_id = pbr.partner_billing_report_id
			LEFT JOIN dbo.order_header oh
				ON oh.order_header_id = pbo.order_header_id

		WHERE pbd.dataset = 'period_average'
			AND pb.total_extended_amount > 0

		GROUP BY 
			pbr.partner_id,
			pbr.site_id,
			pb.currency_id,
			pb.license_id,
			pb.license_category_id

		IF @opt_args LIKE '%debug%' BEGIN

				SELECT 
					average.partner_billing_revenue_detail_period_average_id,
					average.partner_id,
					average.site_id,
					average.currency_id,
					average.license_category_id,
					average.license_id,
					average.billing_date_min,
					average.billing_date_max,
					average.average_license_seats,
					average.average_retail_price,
					average.average_extended_amount,
					average.average_usage_seats,
					average.average_usage_price,
					average.average_usage_extended_amount,
					average.average_total_extended_amount

				FROM #partner_billing_revenue_detail_period_average average
				ORDER BY average.partner_billing_revenue_detail_period_average_id;

			END;

		/*
		|
		| Create order fact table for this instance with pool of orders for each billing period in this report
		|
		*/
		INSERT INTO #partner_billing_revenue_order_fact (
		    partner_billing_order_id,
		    partner_billing_report_id,
			partner_id,
			site_id,
			currency_id,
			billing_date,
		    order_header_id,
			license_category_id,
			order_total
		)
		SELECT
			DISTINCT
				pbo.partner_billing_order_id,
				pbo.partner_billing_report_id,
				pbr.partner_id,
				pbr.site_id,
				ISNULL( oc.currency_id, 1 ) AS currency_id,
				pbr.billing_date,
				pbo.order_header_id,
				plc.license_category_id,
				SUM(oi.quantity * ( oi.unit_price + oi.tax ) ) AS order_total

		FROM dbo.partner_billing_order pbo
			INNER JOIN dbo.partner_billing_report pbr
				ON pbr.partner_billing_report_id = pbo.partner_billing_report_id
			INNER JOIN @partner_billing_dates pbd
				ON pbd.partner_billing_report_id = pbo.partner_billing_report_id
					AND pbd.dataset IN ( 'current', 'period_average' ) -- exclude 'prior' as it exists in 'period_average' and would duplicate
			INNER JOIN dbo.order_item oi
				ON pbo.order_header_id = oi.order_header_id
					AND oi.order_item_status_id IN ( 1 ) -- don't include refunds
					AND oi.unit_price > 0
			LEFT JOIN dbo.order_currency oc
				ON oc.order_header_id = oi.order_header_id
			INNER JOIN dbo.product p
				ON p.product_id = oi.product_id
			INNER JOIN dbo.product_license_category plc
				ON plc.product_id = p.product_id

		GROUP BY pbo.partner_billing_order_id,
			pbo.partner_billing_report_id,
			pbr.partner_id,
			pbr.site_id,
			pbr.billing_date,
			pbo.order_header_id,
			oc.currency_id,
			plc.license_category_id

		ORDER BY pbo.partner_billing_order_id,
				pbo.partner_billing_report_id,
				pbo.order_header_id,
				plc.license_category_id

		IF @opt_args LIKE '%debug%' BEGIN

				SELECT 
					pbco.partner_billing_revenue_order_fact_id,
					pbco.partner_billing_order_id,
					pbco.partner_billing_report_id,
					pbco.partner_id,
					pbco.site_id,
					pbco.currency_id,
					pbco.billing_date,
					pbco.order_header_id,
					pbco.license_category_id,
					pbco.order_total

				FROM #partner_billing_revenue_order_fact pbco
					LEFT JOIN dbo.currency cu
						ON cu.currency_id = pbco.currency_id
				ORDER BY pbco.partner_billing_report_id, pbco.licens
e_category_id

			END

		/*
		|
		| Create fact table for this instance
		|
		*/
		INSERT INTO #partner_billing_revenue_fact (
			partner_id,
			site_id,
			currency_id,
			license_id,
			license_category_id,

			current_billing_date,
			current_license_seats,
			current_unit_price,
			current_total,
			current_usage_seats,
			current_usage_price,
			current_usage_total,
			current_billing_total,

			prior_billing_date,
			prior_license_seats,
			prior_unit_price,
			prior_total,
			prior_usage_seats,
			prior_usage_price,
			prior_usage_total,
			prior_billing_total,

			period_reports,
			period_billing_cycles,
			period_from,
			period_to,

			average_license_seats,
			average_retail_price,
			average_extended_amount,
			average_usage_seats,
			average_usage_price,
			average_usage_extended_amount,
			average_billing_total
		)
		SELECT DISTINCT
			COALESCE( detail.partner_id, prior.partner_id, average.partner_id ) AS partner_id,
			COALESCE( detail.site_id, prior.site_id, average.site_id ) AS site_id,
			COALESCE( detail.currency_id, prior.currency_id, average.currency_id, 1 ) AS currency_id,
			COALESCE( detail.license_id, prior.license_id, average.license_id ) AS license_id,
			COALESCE( detail.license_category_id, prior.license_category_id, average.license_category_id ) AS license_category_id,

			detail.billing_date as current_billing_date,

			detail.license_seats AS current_license_seats,
			detail.unit_price AS current_unit_price,
			detail.total AS current_total,
			detail.usage_seats AS current_usage_seats,
			detail.usage_price AS current_usage_price,
			detail.usage_total AS current_usage_total,
			detail.billing_total AS current_billing_total,

			prior.billing_date AS prior_billing_date,

			prior.license_seats AS prior_license_seats,
			prior.unit_price AS prior_unit_price,
			prior.total AS prior_total,
			prior.usage_seats AS prior_usage_seats,
			prior.usage_price AS prior_usage_price,
			prior.usage_total AS prior_usage_total,
			prior.billing_total AS prior_billing_total,

			average.number_reports AS period_reports,
			average.billing_cycles AS period_billing_cycles,

			average.billing_date_min,
			average.billing_date_max,

			average.average_license_seats,
			average.average_retail_price,
			average.average_extended_amount,
			average.average_usage_seats,
			average.average_usage_price,
			average.average_usage_extended_amount,
			average.average_total_extended_amount as average_billing_total

		FROM #partner_billing_revenue_detail detail
			FULL JOIN #partner_billing_revenue_detail_prior_month prior
				ON detail.license_id = prior.license_id
					AND prior.license_category_id = detail.license_category_id
			FULL JOIN #partner_billing_revenue_detail_period_average average
				ON average.license_id = COALESCE( detail.license_id, prior.license_id )
					AND average.license_category_id = COALESCE( detail.license_category_id, prior.license_category_id )

		ORDER BY COALESCE( detail.partner_id, prior.partner_id, average.partner_id ),
				COALESCE( detail.site_id, prior.site_id, average.site_id ),
				COALESCE( detail.currency_id, prior.currency_id, average.currency_id, 1 ),
				COALESCE( detail.license_id, prior.license_id, average.license_id ),
				COALESCE( detail.license_category_id, prior.license_category_id, average.license_category_id )

		IF @opt_args LIKE '%debug%' BEGIN
				SELECT
					fact.partner_billing_revenue_fact_id,
					fact.partner_id,
					fact.site_id,
					fact.currency_id,
					fact.license_id,
					fact.license_category_id,
					fact.current_billing_date,
					fact.current_license_seats,
					fact.current_unit_price,
					fact.current_total,
					fact.current_usage_seats,
					fact.current_usage_price,
					fact.current_usage_total,
					fact.current_billing_total,
					fact.prior_billing_date,
					fact.prior_license_seats,
					fact.prior_unit_price,
					fact.p
rior_total,
					fact.prior_usage_seats,
					fact.prior_usage_price,
					fact.prior_usage_total,
					fact.prior_billing_total,

					fact.period_reports,
					fact.period_billing_cycles,
					fact.period_from,
					fact.period_to,

					fact.average_license_seats,
					fact.average_retail_price,
					fact.average_extended_amount,
					fact.average_usage_seats,
					fact.average_usage_price,
					fact.average_usage_extended_amount

				FROM #partner_billing_revenue_fact fact
				ORDER BY fact.partner_id, fact.site_id, fact.license_id, fact.license_category_id;

			END



		/*
		|
		| Insert into real fact tables
		|
		*/
