		)
		SELECT 
			@report_date,
            fact.partner_billing_order_id,
            fact.partner_billing_report_id,
            fact.partner_id,
            fact.site_id,
            fact.currency_id,
            fact.billing_date,
            fact.order_header_id,
            fact.license_category_id,
            fact.order_total
		FROM #partner_billing_revenue_order_fact fact

		IF @opt_args LIKE '%debug' BEGIN
				SELECT 
					fact.partner_billing_revenue_order_fact_id,
                    fact.report_date,
                    fact.partner_billing_order_id,
                    fact.partner_billing_report_id,
                    fact.partner_id,
                    fact.site_id,
                    fact.currency_id,
                    fact.billing_date,
