-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_usage_override]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_insert_partner_billing_usage_override]

(
	@partner_billing_report_id int,
	@license_category_id tinyint,
	@usage_json nvarchar(max),
	@partner_billing_status_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2020-10-28	esmart		Initial creation.

	DESCRIPTION
	Insert partner_usage_override
*/

AS

	declare @sites_json nvarchar(max), 
			@parent_keycode varchar(40), 
			@effective_date datetime,
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) failure
	if @partner_billing_status_id = 5
		begin
		update r
		set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate()
		from partner_billing_report_override r
		where r.partner_billing_report_id = @partner_billing_report_id and r.license_category_id = @license_category_id
		return
		end

	-- 1.1) parse json
	select @sites_json = Sites, @parent_keycode = parent_keycode, @effective_date = effective_date
	from openjson(@usage_json)
	with (Sites nvarchar(max) as json,
		parent_keycode varchar(40) '$.ReportInfo.GSMKey',
		effective_date datetime '$.ReportInfo.EffectiveDate')

	-- 1.2) insert partner_billing_usage_override
	insert into partner_billing_usage_override(partner_billing_report_id, license_category_id, effective_date, parent_keycode, keycode, site_name, category_type_name, expiration_date, usage_seats)
	select @partner_billing_report_id, @license_category_id, @effective_date, @parent_keycode, keycode, site_name, category_type_name, expiration_date, usage_seats
	from openjson(@sites_json)
	with (keycode varchar(40) '$.SiteKey',
		site_name nvarchar(255) '$.SiteName',
		category_type_name varchar(20) '$.LicenseType',
		expiration_date datetime '$.ExpiryDate',
		usage_seats int '$.TotalEndpoints')

	-- 1.3) partner_billing_report_override
	update r
	set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate()
	from partner_billing_report_override r
	where r.partner_billing_report_id = @partner_billing_report_id and r.license_category_id = @license_category_id

		-- 1.3.1) if all overrides are complete update report to pending
		if (select count(*) from partner_billing_report_override r where r.partner_billing_report_id = @partner_billing_report_id and r.partner_billing_status_id <> @partner_billing_status_id) = 0
			begin
			update r
			set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate(), r.modified_by = 'override_process'
			from partner_billing_report r
			where partner_billing_report_id = @partner_billing_report_id
			end


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_billing_usage_override_DNS]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_insert_partner_billing_usage_override_DNS]

(
	@partner_billing_report_id int,
	@partner_billing_status_id tinyint 
)

/*	
	DATE		AUTHOR		REMARKS
	2020-11-02	esmart		Initial creation.

	DESCRIPTION
	Insert partner_usage_override for DNS
*/

AS

	declare @license_category_id tinyint, 
			@billing_date datetime,
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) gathter activity
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) failure
	if @partner_billing_status_id = 5
		begin
		update r
		set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate()
		from partner_billing_report_override r
		where r.partner_billing_report_id = @partner_billing_report_id and r.license_category_id = 230
		return
		end


	-- 1.2) select partner_billing_report
	select @license_category_id = 230

	select @billing_date = r.billing_date
	from partner_billing_report r
	where r.partner_billing_report_id = @partner_billing_report_id

	-- 1.3) gather detail data
	declare @report_keycodes table (temp_id int identity(1,1), keycode varchar(40))
	
	insert into @report_keycodes(keycode)
	select distinct keycode
	from partner_billing where partner_billing_report_id = @partner_billing_report_id and license_category_id = @license_category_id

	-- 1.4) loop 
	declare @temp_id int, @total_ids int, @keycode varchar(50), @report_type varchar(50), @report_date date, @site_keycode varchar(50)

	select @report_type = 'SEEN_LAST_30_DAYS',@report_date = @billing_date, @site_keycode = null

	select @total_ids = max(temp_id), @temp_id =1 from @report_keycodes

	-- select @total_ids = 1

	while @total_ids >= @temp_id
		begin
		select @keycode = keycode from @report_keycodes where temp_id = @temp_id
	
		print @keycode

		exec [usp_license_select_console_activity_all_NEW] @keycode = @keycode, @report_type = @report_type, @report_date = @report_date, @site_keycode = @site_keycode

		select @temp_id = @temp_id + 1
		end
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) partner_billing_usage_override
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) @unit_type_summary
	declare @unit_type_summary table (parent_keycode varchar(40), keycode varchar(40), license_category_id tinyint, site_unit_type varchar(20), category_type_name varchar(20), expiration_date datetime, site_total_units int)

	insert into @unit_type_summary(parent_keycode, keycode, license_category_id, site_unit_type, category_type_name, expiration_date, site_total_units)
	select l.keycode as parent_keycode, l.site_keycode as keycode, lc.license_category_id, l.site_unit_type, l.site_license_type as category_type_name, l.site_expiration_date as expiration_date, sum(l.site_total_units) as site_total_units
	from temp_console_activity_all_log l
	inner join @report_keycodes r
		on l.keycode = r.keycode
	inner join license_category lc
		on l.site_categories = lc.license_category_name
	where lc.license_category_id = @license_category_id
		and l.report_date = @billing_date
		and l.site_license_type = 'full'
	group by l.keycode, l.site_keycode, lc.license_category_id, l.site_
unit_type, l.site_license_type, l.site_expiration_date

	-- 2.2) partner_billing_usage_override
	insert into partner_billing_usage_override(partner_billing_report_id, license_category_id, effective_date, parent_keycode, keycode, category_type_name, expiration_date, agent_units, agentless_units, proxy_units, usage_seats)
	select @partner_billing_report_id, @license_category_id, @billing_date, p.parent_keycode, p.keycode, p.category_type_name, p.expiration_date, isnull(a.site_total_units,0) as agent_units, isnull(al.site_total_units,0) as agentless_units, isnull(p.site_total_units,0) as proxy_units,
			case
				when isnull(a.site_total_units,0) > 0 and isnull(al.site_total_units,0) = 0 then isnull(a.site_total_units,0) --If agent only – then use actuals/ utility
				when isnull(a.site_total_units,0) >= 0 and isnull(al.site_total_units,0) > 0 and isnull(p.site_total_units,0) > 0 then isnull(p.site_total_units,0) --If ip only – then use proxy number and If agent + ip – then user proxy numbers
				else 0
			end as usage_seats
	from @unit_type_summary p
	left join @unit_type_summary a
		on a.keycode = p.keycode and a.site_unit_type = 'AGENT' 
	left join @unit_type_summary al
		on al.keycode = p.keycode and al.site_unit_type = 'AGENTLESS' 
	where p.site_unit_type = 'PROXY'

	-- 2.2) partner_billing_report_override
	update r
	set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate()
	from partner_billing_report_override r
	where r.partner_billing_report_id = @partner_billing_report_id and r.license_category_id = 230

		-- 2.2.1) if all overrides are complete update report to pending
		if (select count(*) from partner_billing_report_override r where r.partner_billing_report_id = @partner_billing_report_id and r.partner_billing_status_id <> @partner_billing_status_id) = 0
			begin
			update r
			set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate(), r.modified_by = 'override_process'
			from partner_billing_report r
			where partner_billing_report_id = @partner_billing_report_id
			end
	
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
