-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_insert_partner_license]

(
	@license_id int,
	@partner_id int,
	@partner_license_status_id tinyint = null,
	@partner_license_source_id tinyint = null,
	@last_modified_user_id varchar(20) = null,
	@comment nvarchar(max) = null,
	@order_header_id int = null,
	@partner_license_id int OUTPUT
)


/*	
	DATE		AUTHOR		REMARKS
	2015-07-30	esmart		Initial creation.
	2016-05-17	esmart		Remove print
	2016-12-02	acoffel		add start date insert
	2017-02-10	acoffel		user default
	2017-05-11	esmart		add @order_header_id
	2019-08-27	rvinoche	archive previously approved and open-ended partner licenses when inserting newly approved partner_license record

	DESCRIPTION
	Insert partner_license
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @partner_license_id = null

	if @last_modified_user_id is null 
		begin
		select @last_modified_user_id = suser_sname()
		end

	-- 1.0) @partner_id
	if @partner_id is null
		begin
		select @partner_id = 5559
		end

	-- 1.1) check for existing record
	if @order_header_id is null
		begin
			select @partner_license_id = pl.partner_license_id
			from partner_license pl 
			where pl.license_id = @license_id and pl.partner_id = @partner_id and partner_license_status_id = @partner_license_status_id
		end
	else
		begin
			select @partner_license_id = pl.partner_license_id
			from partner_license pl 
			where pl.license_id = @license_id and pl.partner_id = @partner_id and partner_license_status_id = @partner_license_status_id and pl.order_header_id = @order_header_id
		end
		-- and partner_license_source_id = @partner_license_source_id

	-- 1.2) return existing @partner_license_id
	if @partner_license_id is not null
		begin
		-- print '1.2'
		--select @partner_license_id
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) partner_license
	insert into partner_license(license_id, partner_id, partner_license_status_id, partner_license_source_id, last_modified_user_id, start_date, order_header_id)
	select @license_id, @partner_id, @partner_license_status_id, @partner_license_source_id, @last_modified_user_id, 
		start_date = case when @partner_license_status_id = 2 then convert(date,getdate()) else null end,
		@order_header_id

	select @partner_license_id = scope_identity()

	-- 2.2) partner_license_comment
	if @comment is not null
		begin
		insert into partner_license_comment(partner_license_id, comment)
		values(@partner_license_id,@comment)
		end

	-- 2.3) archive previously approved partner license
	if @partner_license_status_id = 2
		begin
		insert into dbo.partner_license_audit (partner_license_id, license_id, partner_id,partner_license_status_id,partner_license_source_id,last_modified_user_id, last_modified_date, insert_date, start_date, end_date, order_header_id, audit_date)
		select partner_license_id, lice
nse_id, partner_id, partner_license_status_id, partner_license_source_id, last_modified_user_id, last_modified_date, insert_date, start_date, end_date, order_header_id, getdate()
		from dbo.partner_license 
		where license_id = @license_id
			and partner_license_id <> @partner_license_id
			and partner_license_status_id = 2
			and end_date is null
            
		update dbo.partner_license
		set end_date = convert(date,getdate()),
			last_modified_user_id = @last_modified_user_id, 
			last_modified_date = getdate(), 
			partner_license_status_id = case when cast(start_date as date) = cast(getdate() as date) then 4 else partner_license_status_id end -- if the previously approved partner_license records were approved the same day, the record should no longer be approved
		where license_id = @license_id
			and partner_license_id <> @partner_license_id
			and partner_license_status_id = 2
			and end_date is null
	end
    
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
