-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_insert_partner_license_transaction]

(
	@partner_license_id int, 
	@partner_license_status_id tinyint, 
	@license_transaction varchar(max)
)


/*	
	DATE		AUTHOR		REMARKS
	2015-07-30	esmart		Initial creation.
	2017-05-16	esmart		
	2017-08-23	esmart		openjson
	2019-07-23	rvinoche	Add catch for duplicate

	DESCRIPTION
	Insert partner_license_transaction
*/

AS
	set nocount on				

	declare	@transaction_procedure_name varchar(100),
			@effective_date datetime,
			@partner_license_transaction_procedure_id tinyint,
			@archive_duplicate varchar(10),
			@response_code int,
			@message varchar(100)			


	begin try
	
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	
	select @license_transaction = replace(@license_transaction,'@','')

	if exists (select 1 from dbo.partner_license_transaction where partner_license_id = @partner_license_id and partner_license_status_id = @partner_license_status_id and license_transaction = @license_transaction)
		return
	
	select @transaction_procedure_name = transaction_procedure_name, @effective_date = effective_date
	from openjson(@license_transaction)
	with (transaction_procedure_name varchar(100) '$.procedure',
			effective_date datetime '$.effective_date')


	--declare @transaction_data table (parameter_name varchar(100), parameter_value nvarchar(100))

	---- 1.1) insert transaction data
	--insert into @transaction_data(parameter_name,parameter_value)
	--select Name, StringValue
	--from dbo.fn_parse_json(@license_transaction)
	--where Object_ID is null

	---- 1.2) get procedure to process
	--select @transaction_procedure_name = parameter_value from @transaction_data where parameter_name = 'procedure'

	select @partner_license_transaction_procedure_id = partner_license_transaction_procedure_id, @archive_duplicate = archive_duplicate
	from partner_license_transaction_procedure 
	where transaction_procedure_name = @transaction_procedure_name

	--select effective_date = @effective_date, partner_license_transaction_procedure_id = @partner_license_transaction_procedure_id, archive_duplicate = @archive_duplicate

	--return

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	
	-- 2.1) update transactions with the same procedure to archived
	if @archive_duplicate = 'yes'
		begin
			--select 
			--from openjson(select license_transaction from partner_license_transaction where partner_license_id = @partner_license_id and partner_license_transaction_procedure_id = @partner_license_transaction_procedure_id)
			--with (effective_date datetime '$.effective_date')

			--return

			update partner_license_transaction 
			set partner_license_status_id = 4, last_modified_date = getdate()
			where partner_license_id = @partner_license_id and partner_license_transaction_procedure_id = @partner_license_transaction_procedure_id
		end

	-- 2.2) insert new transactiom
	insert into partner_license_transaction(partner_license_id, partner_license_status_id, license_transaction, partner_license_transaction_procedure_id)
	values(@partner_license_id, @partner_license_status_id, @license_transacti
on, @partner_license_transaction_procedure_id)


	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
