	if @insert_by is null begin select @insert_by = suser_sname() end

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) delete
	delete from partner_payment_term where partner_id = @partner_id

	-- 2.2) insert
	insert into partner_payment_term(partner_id, payment_term_id)
	values(@partner_id, @payment_term_id)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_pricing_tier]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_insert_partner_pricing_tier]

(
	@partner_id int,
	@product_id int,
	@retail_price money, 
	@currency_id tinyint, 
	@low_range int, 
	@high_range int,
	@license_category_id tinyint,
	@license_attribute_id tinyint, 
	@pricing_status varchar(10) = null
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-11-14	esmart		Initial creation
    2015-10-01  cnovac      Added check to see if row already exists
	
	DESCRIPTION
	insert partner_pricing_tier
	
*/

AS
	
	set nocount on			

	declare	@partner_pricing_tier_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @pricing_status is null
		begin
		select @pricing_status = 'active'
		end

    select @partner_pricing_tier_id = partner_pricing_tier_id
    from partner_pricing_tier
    where partner_id = @partner_id
		and product_id = @product_id
		and retail_price = @retail_price
		and currency_id = @currency_id
		and low_range = @low_range
		and high_range = @high_range
		--and (license_category_id is null or license_category_id = @license_category_id)

	--if (select from partner_pricing_tier where partner_pricing_tier_id = @partner_pricing_tier_id) = 0

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    if @partner_pricing_tier_id is null
    begin
	    insert into partner_pricing_tier(partner_id, product_id, retail_price, currency_id, low_range, high_range, pricing_status)
	    values(@partner_id, @product_id, @retail_price, @currency_id, @low_range, @high_range, @pricing_status)

	    select @partner_pricing_tier_id = SCOPE_IDENTITY()
    end

	select partner_pricing_tier_id = @partner_pricing_tier_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_insert_partner_quote]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_insert_partner_quote]

(
	@cart_order_in_process_id int = null,
	@cart_order_id int = null,
	@partner_key varchar(36)
)

/*	
	DATE			AUTHOR		REMARKS
	2013-01-07		esmart		Initial creation.
	2013-10-17		esmart		
	2016-03-03		esmart		Default routing_action to billing
	2018-05-08		esmart		Support cart_order_id

	DESCRIPTION
	insert cart_order_partner_in_process
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_quote_id int,
			@cart_discount_message_id int,
			@cart_discount_message_description varchar(50),
			@message_type_id tinyint,
			@message_value_type_id tinyint,
			@value_id varchar(20),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.2) @cart_discount_message_description

	-- 1.3) @message_type_id
	select @message_type_id = message_type_id from message_type where message_type_name = 'cart'
	
	if @cart_order_in_process_id is not null
		begin
			--print '@cart_order_in_process_id'
			select @message_value_type_id = message_value_type_id from message_value_type where message_value_type_name = 'cart_order_in_process_id'
			select @cart_discount_message_description = 'Partner quote ' + convert(varchar(20),@cart_order_in_process_id)
			select @value_id = @cart_order_in_process_id
		end
	if @cart_order_id is not null
		begin
			--print '@cart_order_id'
			select @message_value_type_id = message_value_type_id from message_value_type where message_value_type_name = 'cart_order_id'
			select @cart_discount_message_description = 'Partner quote ' + convert(varchar(20),@cart_order_id)
			select @value_id = @cart_order_id
		end
	-- 1.4) check for previous quote
	select @cart_discount_message_id = v.cart_discount_message_id
	from cart_discount_message_value v
	where v.message_value_type_id = @message_value_type_id and v.value_id = @value_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @cart_discount_message_id is null
		begin
		-- 2.1) insert cart_discount_message
		insert into cart_discount_message(cart_discount_message_description,message_type_id)
		values(@cart_discount_message_description,@message_type_id)

		select @cart_discount_message_id = scope_identity()

		insert into cart_discount_message_value(cart_discount_message_id,message_value_type_id,value_id)
		values(@cart_discount_message_id,@message_value_type_id,@value_id)

		-- 2.2) update cart_order_route_in_process
		update cart_order_route_in_process 
		set routing_action = 'billing'
		where cart_order_in_process_id = @cart_order_in_process_id

		-- 2.3) insert partner_quote
		insert into partner_quote(partner_id, cart_discount_message_id)
		values(@partner_id, @cart_discount_message_id)

		select @partner_quote_id = scope_identity()

		select partner_quote_id = @partner_quote_id
		end
	else
		begin
		select partne
r_quote_id
		from partner_quote 
		where cart_discount_message_id = @cart_discount_message_id
		end
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_license_transaction_simulation]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_license_transaction_simulation]
(
	@partner_license_id int,
	@effective_date date
)

/*	
	DATE			AUTHOR			REMARKS
	2018-10-10		rvinoche		Initial creation
	2020-06-25		cnovac			Updated logic a bit
	2020-11-05		cnovac			Updated logic on end date and category type

	DESCRIPTION
	Simulate approvals for partner_licenses
*/
AS

	declare @license_id int,
			@min int,
			@max int,
			@order_header_id int,
			@license_service_id int,
			@transaction_name varchar(100),
			@transaction_json nvarchar(max),
			@license_service_json nvarchar(max),
			@license_category nvarchar(max),
			@keycode varchar(50),
			@license_seats int,
			@license_service_description varchar(50),
			@current_partner_id int,
			@future_billing_model int,
			@response_code int,
            @message varchar(100)

	declare @transactions table (row_id int identity (1,1), partner_license_transaction_procedure_name varchar(100), partner_license_transaction_id int)
	declare @order_items table (order_item_id int, license_category_id int, license_category_name varchar(10), seats int, start_date date, end_date date)
	declare @license_service table (keycode varchar(50), license_category_name varchar(50), license_seats int, expiration_date date, license_service_id int)

	declare @license_current table (license_id int, keycode varchar(50), partner_id int, partner_name nvarchar(100), license_category_id int, license_category_name varchar(10), category_type_name varchar(50), category_seats int, expiration_date date, billing_model int, billing_model_description varchar(50))
	declare @license_pending table (license_id int, keycode varchar(50), partner_id int, partner_name nvarchar(100), license_category_id int, license_category_name varchar(10), category_type_name varchar(50), category_seats int, expiration_date date, billing_model int, billing_model_description varchar(50), order_item_id int, license_service_id int, action_requested varchar(500))

	begin try

		select @license_id = license_id 
		from partner_license pl
		where pl.partner_license_id = @partner_license_id

		-- 1.) Current license status
		insert into @license_current (license_id, keycode, license_category_id, license_category_name, category_type_name, category_seats, expiration_date, billing_model, billing_model_description)
		select fn.license_id, fn.keycode, fn.license_category_id, fn.license_category_name, fn.category_type_name, fn.license_seats, fn.expiration_date, fn.license_attribute_license_value, lalv.license_attribute_license_value_description
		from fn_license_select_license_profile(@license_id) fn
		left join license_attribute_license_value lalv on lalv.license_attribute_license_value = fn.license_attribute_license_value

		--Update partner info, if no partner_license record, default to Webroot Direct Partner
		select @current_partner_id = partner_id
		from partner_license
		where license_id = @license_id
		and partner_license_status_id = 2
		and start_date < getdate()
		and (end_date is null or end_date > getdate())

		update ln 
		set ln.partner_id = @current_partner_id,
			ln.partner_name = p.partner_name
		from @license_current ln
		inner join partner p on p.partner_id = isnull(@current_partner_id, 5559) --webroot direct

		--2.) Pending partner_license_transactions
		insert into @transactions (partner_license_transaction_procedure_name, partner_license_transaction_id)
		select p.transaction_procedure_name, plt.partner_license_transaction_id
		from partner_license_transaction plt
		inner join partner_license_transaction_procedure p on p.partner_license_transaction_procedure_id = plt.partner_license_transaction_procedure_id
		where plt.partner_license_id = @partner_lic
ense_id
		and plt.partner_license_status_id = 1
	
		select @min = min(row_id), @max = max(row_id) from @transactions

		while @min <= @max
		begin
			select @transaction_name = t.partner_license_transaction_procedure_name,
					@transaction_json = p.license_transaction
			from @transactions t
			inner join partner_license_transaction p on p.partner_license_transaction_id = t.partner_license_transaction_id
			where t.row_id = @min

			--2.1) license attribute value
			if @transaction_name = 'usp_license_update_license_attribute_license'
				select @future_billing_model = json_value(@transaction_json,'$.license_attribute_license_value')

			--2.2) order load
			if @transaction_name = 'usp_cart_update_order_license_new'
			begin 
				select @order_header_id = oh.order_header_id
				from vendor_order vo
				inner join order_header oh on oh.vendor_order_id = vo.vendor_order_id
				where vo.vendor_order_code = json_value(@transaction_json,'$.vendor_order_code')

				delete @order_items
				insert into @order_items (order_item_id, license_category_id, license_category_name, seats, start_date, end_date)
				select oi.order_item_id, plc.license_category_id, lc.license_category_name, oi.quantity, oi.effective_date, oi.capability_expiration_date
				from order_item oi
				inner join product p on p.product_id = oi.product_id
				inner join product_license_category plc on plc.product_id = oi.product_id
				inner join license_category lc on lc.license_category_id = plc.license_category_id
				where oi.order_header_id = @order_header_id

				insert into @license_pending (license_id, license_category_id, license_category_name, category_type_name, category_seats, expiration_date, order_item_id, action_requested)
				select @license_id, i.license_category_id, i.license_category_name, 'full', i.seats, i.end_date, i.order_item_id, 'cart_order_transaction'
				from @order_items i

			end
        
			--2.3) license service
			if @transaction_name = 'usp_license_service_update_license'
			begin

				select @license_service_id = json_value(@transaction_json,'$.license_service_id')

				-- 2.3.1) @license_service_json
				select @license_service_json = license_service_json,
						@license_service_description = lst.license_service_type_name 
				from license_service_json lsj
				inner join license_service ls on ls.license_service_id = lsj.license_service_id
				inner join license_service_type lst on lst.license_service_type_id = ls.license_service_type_id
				where ls.license_service_id = @license_service_id

				-- 2.3.2) parse json
				select @keycode = keycode,
						@license_seats = license_seats,
						@license_category = license_category
				from openjson(@license_service_json)
				with (keycode varchar(40) '$.keycode',
					license_seats int '$.license_seats',
					license_category nvarchar(max) as json)

				-- 2.3.3) parse @license_category		
				if @license_category is not null
				begin
					
					delete @license_service
					insert into @license_service(keycode, license_category_name, license_seats, expiration_date)
					select 	keycode = @keycode,
							license_category_name,
							license_seats,
							expiration_date
					from openjson(@license_category)
					with (keycode varchar(40) '$.keycode',
							license_category_name varchar(10) '$.license_category_name',
							license_seats int '$.license_seats',
							expiration_date datetime '$.expiration_date')
				end

				insert into @license_pending (license_id, keycode, partner_id, partner_name, license_category_id, license_category_name, category_type_name, category_seats, expiration_date, billing_model, billing_model_description, license_service_id, action_requested)
				select lc.license_id,
						lc.keycode,
						lc.partner_id,
						lc.partner_name,
						lc.license_category_id,
						lc.license_category_name,
						iif(@license_service_description in ('site_enable', 'license_enable'), 'full'
, lc.category_type_name),
						isnull(ls.license_seats, lc.category_seats),
						isnull(ls.expiration_date, lc.expiration_date),
						lc.billing_model,
						lc.billing_model_description,
						@license_service_id,
						@license_service_description
				from @license_current lc
				inner join @license_service ls on ls.keycode = lc.keycode and ls.license_category_name = lc.license_category_name

				if @@ROWCOUNT = 0
				begin

					insert into @license_pending (license_id, keycode, partner_id, partner_name, license_category_id, license_category_name, category_type_name, category_seats, expiration_date, billing_model, billing_model_description, license_service_id, action_requested)
					select lc.license_id,
							lc.keycode,
							lc.partner_id,
							lc.partner_name,
							lc.license_category_id,
							lc.license_category_name,
							iif(@license_service_description in ('site_enable', 'license_enable'), 'full', lc.category_type_name),
							isnull(@license_seats, lc.category_seats),
							iif(@license_service_description = 'license_disable', getdate(), lc.expiration_date),
							lc.billing_model,
							lc.billing_model_description,
							@license_service_id,
							@license_service_description
					from @license_current lc
					inner join license_category_license lcl on lcl.license_id = lc.license_id and lcl.license_category_id = lc.license_category_id
					where lc.keycode = @keycode

				end

			end

			select @transaction_json = null, @transaction_name = null, @license_service_description = null, @min = @min + 1

		end

		--3.) Final Updates
		--Update @license_pending with billing model
		if @future_billing_model is not null
		begin
			update lp 
			set lp.billing_model = @future_billing_model,
				lp.billing_model_description = lalv.license_attribute_license_value_description
			from @license_pending lp
			inner join license_attribute_license_value lalv on lalv.license_attribute_license_value = @future_billing_model

		end

		--Update @license_pending with partner_id
		update lt 
		set lt.partner_id = pl.partner_id,
			lt.partner_name = p.partner_name
		from @license_pending lt
		inner join partner_license pl on pl.partner_license_id = @partner_license_id
		inner join partner p on p.partner_id = pl.partner_id

		--4.) Return results
		select @license_id 'license_id',
               ln.partner_name 'current_partner_name',
               ln.license_category_name 'license_category_name',
               ln.category_type_name 'current_category_type_name',
               ln.category_seats 'current_category_seats',
               ln.expiration_date 'current_expiration_date',
               ln.billing_model 'current_billing_model',
               ln.billing_model_description 'current_billing_model_description',
               isnull(lt.partner_name, ln.partner_name) 'future_partner_name',
               isnull(lt.category_type_name, ln.category_type_name) 'future_category_type_name',
               isnull(lt.category_seats, ln.category_seats) 'future_category_seats',
               isnull(lt.expiration_date, ln.expiration_date) 'future_category_expiration_date',
               isnull(lt.billing_model, ln.billing_model) 'future_billing_model',
               isnull(lt.billing_model_description, ln.billing_model_description) 'future_billing_model_descpription',
			   lt.order_item_id 'future_order_item_id',
			   lt.license_service_id 'future_license_service_id',
			   isnull(lt.action_requested, 'No Action') 'future_action_requested'
		from @license_current ln
		full outer join @license_pending lt on lt.license_id = ln.license_id and lt.license_category_name = ln.license_category_name

	end try

    begin catch

            set @response_code = -200
            set @message = case when @message is null then 'partner_license_simulation failed for '+ cast(@partner_license_id as varchar(20))
                                           
 else @message end

            declare @dbname nvarchar(128)
            set @dbname = db_name()
            exec usp_logerror @errordb = @dbname;
            throw 51001, @message,1;
    end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_process_partner_billing]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_partner_process_partner_billing] (
		@partner_billing_report_id INT
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-02-23		esmart			Initial creation
	2016-06-14		esmart			Alter to use @partner_billing_report_id
	2016-07-22		esmart			Move license_fact back to ecom
	2016-10-19		esmart			Add support for partner_billing_license_attribute
	2016-12-06		esmart			Add partner_pricing_model support
	2017-04-16		esmart			Add support for time phased partner_license
	2017-06-01		esmart			Add module support
	2017-08-30		esmart			Full modules only
	2018-03-08		esmart			Updates to columns
	2018-07-19		rvinoche		Rewrite to use activity and profile functions
	2018-08-15		rvinoche		Use effective object
	2019-01-10		abelenkiy		Update to use order_date and keycode_age for each product; default to endpoint order when no order found for module/partner
	2020-06-24		esmart			Refector for new products and customer data changes
	2020-09-22		esmart			Restrict company_address to active and primary
	2020-09-29		esmart			Fix issues with address selection
	2020-11-02		esmart			Support for override
	2022-01-17		rvinoche		Support for pax8 customized pricing
	2022-03-03		gblandford		Fix customized pricing - also update retail_price #3894622
	2022-06-29		gblandford		ALM-1656: Increase partner_billing.state column width to VARCHAR(3) to match company_address.state
	2022-11-01		gblandford		ALM-3733: Do calculation for usage_seats on monthly overage licenses as a result of cyan change calculation
									in order_license_usage. This is a short-term correction until tech debt is addressed to revert the 
									order_license_usage.usage_seats calculation is reverted and additional columns are made available for 
									auto-billing to SAP
	2022-11-01		gblandford		ALM-3817: use partner_company.company_name by default for reporting purposes, fall back to company - this
									is a reversal of the current logic, but as DGO/SAP are potentially makig many changes, partner_company is more stable

	2023-11-21		gblandford		https://jira.opentext.com/browse/ECOM-2963 - Section 2.6) check new column end_date for customized_pricing as new 
									Pax8 transfers use regular tier-pricing

	2024-08-19		gblandford		https://jira.opentext.com/browse/ECOM-5111 - Handle Pillr products
									- Handle storage based product(s)
										- 2.3	- use storage_gb (simulation code)
										
									- Performance enhancements
										- add schemas
										- replace some @table variables with #temporary tables
										- clean up alias, etc.


	DESCRIPTION
	process billing report
*/

as
	set nocount on

	declare	@billing_date datetime, 
			@usage_end_date date,
			@partner_id int, 
			@partner_billing_type_id tinyint,
			@currency_id tinyint,  
			@billing_cap_percentage float, 
			@billing_cap_days int,
			@billing_currency varchar(3),
			@last_modified_date datetime,
			@return_result tinyint, 
			@reprocess tinyint,
			@response_code int,
			@message varchar(100)
			
begin try

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select variables
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.0) setup data
		select @partner_id = pbr.partner_id,
				@billing_date = pbr.billing_date,
				@partner_billing_type_id = pbr.partner_billing_type_id,
				@usage_end_date = dateadd(dd,-1,billing_date) -- need -1 day from billing day due to effective object st
ructure
		from dbo.partner_billing_report pbr
		where pbr.partner_billing_report_id = @partner_billing_report_id

		-- 1.1) @billing_cap_percentage, @billing_cap_days
		select @billing_cap_percentage = configuration_value from dbo.partner_configuration_partner where partner_id = @partner_id and partner_configuration_id = 6
		select @billing_cap_days = configuration_value from dbo.partner_configuration_partner where partner_id = @partner_id and partner_configuration_id = 7
		select @billing_currency = configuration_value from dbo.partner_configuration_partner where partner_id = @partner_id and partner_configuration_id = 15
		select @last_modified_date = getdate()

		-- 1.2) table variables
		--declare @partner_billing table (customer_id int,customer_code varchar(64), company_id int,company_name nvarchar(100),location_code varchar(3),state nvarchar(3),webroot_entity varchar(3) default ('WI'),reseller_customer_id int,reseller_customer_code varchar(64),reseller_company_name nvarchar(100),reseller_location_code varchar(3),reseller_state nvarchar(3),license_id int,keycode varchar(40),keycode_age int,order_header_id int,order_date datetime,product_id int,license_category_id tinyint,license_attribute_license_value int, license_attribute_id int,license_seats int,retail_price money,extended_amount money,usage_seats int default ((0)),usage_price money default ((0)),usage_extended_amount money default ((0)),total_seats int,total_extended_amount money,cap_amount money default ((0)),total_cap_amount money default ((0)),currency_id int,partner_pricing_model_id tinyint,usage_pricing_model_id tinyint)
		--declare #order_headers table (license_id int, max_order_header_id int, max_vendor_order_date datetime, min_order_header_id int, min_vendor_order_date datetime, license_category_id tinyint)

		DROP TABLE IF EXISTS #partner_billing;

		CREATE TABLE #partner_billing (
			customer_id INT,
			customer_code VARCHAR(64), 
			company_id INT,
			company_name NVARCHAR(100),
			location_code VARCHAR(3),
			state NVARCHAR(3),
			webroot_entity VARCHAR(3) DEFAULT ('WI'),
			reseller_customer_id INT,
			reseller_customer_code VARCHAR(64),
			reseller_company_name NVARCHAR(100),
			reseller_location_code VARCHAR(3),
			reseller_state NVARCHAR(3),
			license_id INT,
			keycode VARCHAR(40),
			keycode_age INT,
			order_header_id INT,
			order_date DATETIME,
			product_id INT,
			license_category_id INT,
			license_attribute_license_value INT, 
			license_attribute_id INT,
			license_seats INT,
			retail_price MONEY,
			extended_amount MONEY,
			usage_seats INT DEFAULT ((0)),
			usage_price MONEY DEFAULT ((0)),
			usage_extended_amount MONEY DEFAULT ((0)),
			total_seats INT,
			total_extended_amount MONEY,
			cap_amount MONEY DEFAULT ((0)),
			total_cap_amount MONEY DEFAULT ((0)),
			currency_id INT,
			partner_pricing_model_id TINYINT,
			usage_pricing_model_id TINYINT
		);

		DROP TABLE IF EXISTS #order_headers;

		CREATE TABLE #order_headers (
			license_id INT, 
			max_order_header_id INT, 
			max_vendor_order_date DATETIME, 
			min_order_header_id INT, 
			min_vendor_order_date DATETIME, 
			license_category_id INT
		);


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) get current license data
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) licenses
		SELECT @return_result = 0, @reprocess = 1

		IF @partner_billing_type_id = 1 -- always reprocess for billing purposes in case a report was previously made with a future date
			EXECUTE dbo.usp_partner_select_partner_license_usage @partner_id = @partner_id, @report_date = @billing_date,  @return_result = @return_resu
lt,  @reprocess = @reprocess --reprocess for billing purposes
		ELSE --if 
        BEGIN	
			IF NOT EXISTS (SELECT 1 FROM dbo.partner_license_usage WHERE partner_id = @partner_id AND report_date = @billing_date)
				EXECUTE dbo.usp_partner_select_partner_license_usage @partner_id = @partner_id, @report_date = @billing_date,  @return_result = @return_result,  @reprocess = @reprocess 
		END

		INSERT INTO #partner_billing (license_id, keycode, license_category_id, license_seats)
		SELECT DISTINCT u.license_id, l.keycode, u.license_category_id, u.license_seats
		FROM dbo.partner_license_usage u
		INNER JOIN dbo.license l
			ON l.license_id = u.license_id
		WHERE u.partner_id = @partner_id 
			AND u.report_date = @billing_date
			AND DATEADD(dd,1,@billing_date) < u.expiration_date AND u.activation_date <= DATEADD(dd,1,@billing_date)

		UPDATE p 
		SET p.license_attribute_license_value = dbo.fn_license_select_effective_object_element(p.license_id, p.license_category_id, 'license_attribute_license_value', @usage_end_date)
		FROM #partner_billing p

		UPDATE p 
		SET p.license_attribute_id = la.license_attribute_id
		FROM #partner_billing p
		INNER JOIN dbo.license_attribute_license_value la
			ON la.license_attribute_license_value = p.license_attribute_license_value

		UPDATE b
		SET b.usage_pricing_model_id = f.effective_value
		FROM #partner_billing b
		CROSS APPLY dbo.fn_license_select_effective_object_table(b.license_id,@billing_date) f
		WHERE f.effective_object_id = 6
		
		-- 2.2) delete rows with incorrect license_attribute_value
		IF EXISTS (SELECT partner_billing_license_attribute_id FROM dbo.partner_billing_license_attribute WHERE partner_billing_report_id = @partner_billing_report_id)
		BEGIN
			DELETE pb
			FROM #partner_billing pb
			WHERE pb.license_attribute_license_value NOT IN (SELECT license_attribute_license_value FROM dbo.partner_billing_license_attribute WHERE partner_billing_report_id = @partner_billing_report_id)
				OR pb.license_attribute_license_value IS NULL
		END
		ELSE
		BEGIN
			DELETE FROM #partner_billing WHERE license_attribute_license_value IN (120,220) OR license_attribute_license_value IS NULL
		END
		
		-- 2.3) get usage and seats
		IF @partner_billing_type_id = 1 -- Actual
			BEGIN
        
					UPDATE b
						--set usage_seats = u.usage_seats
						SET b.usage_seats = ( CASE
												WHEN b.license_attribute_license_value IN (11, 111, 211) THEN ( CASE 
																													WHEN (u.usage_seats > u.license_seats) THEN (u.usage_seats - u.license_seats) 
																													ELSE 0
																												END ) -- Overage
												ELSE u.usage_seats
												END )
					FROM #partner_billing b
					INNER JOIN dbo.order_license_usage u
						ON u.license_id = b.license_id
					WHERE u.end_date = @usage_end_date AND u.license_category_id = b.license_category_id AND b.license_attribute_license_value NOT IN (10, 110, 210)
			END
		ELSE -- Simulation
			BEGIN
        			UPDATE #partner_billing
					SET usage_seats = CASE
											WHEN b.license_attribute_license_value IN (11,111,211) THEN CASE WHEN (u.devices_30_days_active - b.license_seats) < 0 THEN 0 ELSE (u.devices_30_days_active - b.license_seats) END
											WHEN b.license_attribute_license_value IN (12, 112, 212) THEN 
																										( CASE 
																												WHEN b.usage_pricing_model_id = 2 THEN u.storage_gb
																												ELSE u.devices_30_days_active
																											END )

											WHEN b.license_attribute_license_value IN (10,110,210) THEN 0 --u.devices_30_days_active -- as reference
										END
					FROM #partner_billing b
					INNER JOIN dbo.partner_license_usage u
						ON u.license_id = b.license_id
					WHERE u.report_date = @billing_date AND u.license_category_id = b.license_category_id
			END


		UPDATE #partner_billing
		SET license_seats = CASE WHEN license_attribute_li
cense_value IN (12,112,212) THEN 0 ELSE license_seats END,
			total_seats = CASE
									WHEN license_attribute_license_value IN (10,110,210) THEN license_seats
									WHEN license_attribute_license_value IN (11,111,211) THEN license_seats + usage_seats
									WHEN license_attribute_license_value IN (12,112,212) THEN usage_seats
								END
		FROM #partner_billing

		-- 2.4) get pricing
		-- 2.4.1) partner_pricing_model_id 
		UPDATE #partner_billing
		SET partner_pricing_model_id = pl.partner_pricing_model_id
		FROM #partner_billing b
		INNER JOIN dbo.partner_license_attribute pl
			ON pl.license_attribute_id = b.license_attribute_id AND pl.license_attribute_license_value = b.license_attribute_license_value AND pl.license_category_id = b.license_category_id
		WHERE pl.partner_id = @partner_id

		-- 2.4.2) @billing_currency
		SELECT @currency_id = currency_id
		FROM dbo.currency
		WHERE currency_code = @billing_currency

		-- 2.4.3) total endpoints
		DECLARE @total_seat TABLE (license_category_id INT, total_seats INT)

		INSERT INTO @total_seat (license_category_id, total_seats)
		SELECT b.license_category_id, SUM(b.total_seats) AS total_seats
		FROM #partner_billing b
		GROUP BY b.license_category_id

		-- 2.4.4) retail_price	
		UPDATE #partner_billing
		SET retail_price = ISNULL(p.retail_price,0),
			currency_id = p.currency_id
		FROM #partner_billing b
		INNER JOIN @total_seat t
			ON b.license_category_id = t.license_category_id 
		INNER JOIN dbo.partner_pricing_tier p
			ON b.license_category_id = p.license_category_id AND 
				p.partner_id = @partner_id AND
				p.license_attribute_id = b.license_attribute_id AND
				p.low_range <= CASE 
									WHEN b.partner_pricing_model_id = 1 THEN t.total_seats
									WHEN b.partner_pricing_model_id = 2 THEN b.total_seats
								END AND
				p.high_range > CASE 
									WHEN b.partner_pricing_model_id = 1 THEN t.total_seats
									WHEN b.partner_pricing_model_id = 2 THEN b.total_seats
								END AND 
				p.pricing_status = 'active'
		WHERE p.currency_id = @currency_id

		-- 2.4.5) usage_price
		UPDATE #partner_billing
		SET usage_price = retail_price	
		WHERE license_attribute_license_value IN (11,12,111,112,211,212)
						
		-- 2.5) cap_amount
		IF @billing_cap_percentage IS NOT NULL
		BEGIN
			UPDATE #partner_billing
			SET cap_amount = ROUND((retail_price * license_seats)*@billing_cap_percentage,2)
			FROM #partner_billing
			WHERE keycode_age <= @billing_cap_days
		END
        
		-- 2.6) customized pricing for pax8
		IF EXISTS (SELECT 1 FROM dbo.customize_pricing_partner WHERE partner_id = @partner_id)
		BEGIN	
			UPDATE p 
				SET usage_price = cp.customized_price
					, retail_price = cp.customized_price
			FROM #partner_billing p
			INNER JOIN dbo.customize_pricing_license c
				ON c.license_id = p.license_id AND c.license_category_id = p.license_category_id
			INNER JOIN dbo.customize_pricing cp
				ON cp.license_category_id = p.license_category_id 
					AND p.usage_seats BETWEEN cp.low_range AND cp.high_range
					AND c.partner_transfer_date <= cp.end_date
			WHERE c.is_active = 1
		END 

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) get orders
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 3.1) get order_header
		insert into #order_headers(license_id,max_order_header_id,min_order_header_id,license_category_id)
		select b.license_id, max_order_header_id = max(h.order_header_id), min_order_header_id = min(h.order_header_id),b.license_category_id
		from #partner_billing b
		inner join dbo.order_item_license il with (nolock)
			on il.license_id = b.license_id

		inner join dbo.order_item i with (nolock)
			on il.order_item_id = i.order_item_id
		inner join dbo.product p with (nolock)
			on i.product_id = p.product_id-- and p.product_type_id in (1,2,3)
		inner join dbo.product_license_category plc with (nolock)
			on plc.product_id = p.product_id and b.license_category_id = plc.license_category_id
		inner join dbo.order_header h with (nolock)
			on i.order_header_id = h.order_header_id
		inner join dbo.partner_order po with (nolock)
			on po.order_header_id = h.order_header_id and po.partner_id = @partner_id
		--where i.unit_price > 0.00
		group by b.license_id,
				b.license_category_id

		-- 3.1.2) get vendor_order_date
		update #order_headers
		set max_vendor_order_date = oh.vendor_order_date,
			min_vendor_order_date = oh2.vendor_order_date
		from #order_headers oht
		inner join dbo.order_header oh
			on oht.max_order_header_id = oh.order_header_id
		inner join order_header oh2
			on oht.min_order_header_id = oh2.order_header_id

		-- 3.2) migrations
		update h
		set min_order_header_id = h2.min_order_header_id
		from #order_headers h
		inner join dbo.license_migration m
			on h.license_id = m.new_license_id
		inner join #order_headers h2
			on m.original_license_id = h2.license_id

		--delete licenses that have been migrated after capturing the min order_header
		delete from #partner_billing
		where license_id in (select original_license_id from license_migration)

		-- 3.3) keycode age, order_header
		update #partner_billing
		set keycode_age = datediff(dd,isnull(h.min_vendor_order_date, h2.min_vendor_order_date),@billing_date), 
			order_header_id = isnull(h.max_order_header_id, h2.max_order_header_id),
			order_date = isnull(h.min_vendor_order_date, h2.min_vendor_order_date)
		from #partner_billing b
		inner join #order_headers h2 
			on b.license_id = h2.license_id
		left join #order_headers h
			on b.license_id = h.license_id
				and h.license_category_id = b.license_category_id

		update #partner_billing
		set keycode_age = datediff(dd,order_date,@billing_date)
		from #partner_billing

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) get customers
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 4.1) customer
		update #partner_billing
		set customer_id = oc.customer_id,
			customer_code = isnull(pc.partner_customer_code,vc.vendor_customer_code),

			--company_name = isnull(c.company_name,'-unknown-'),
			company_name = coalesce(pc.company_name, c.company_name,'-unknown-'),

			location_code = case 
								when lcc.iso3 is not null then lcc.iso3
								when lcc2.iso3 is not null then lcc2.iso3
								else lc.iso3
							end,
			state = case 
								when ca.state is not null then ca.state
								when ca2.state is not null then ca2.state
								else a.state
							end, 
			webroot_entity = case 
								when lcc.webroot_entity is not null then lcc.webroot_entity
								when lcc2.webroot_entity is not null then lcc2.webroot_entity
								else lc.webroot_entity
							end,
			company_id = oc.company_id
		from #partner_billing t
		inner join dbo.order_company oc with (nolock)
			on oc.order_header_id = t.order_header_id 
		left join dbo.company c with (nolock)
			on c.company_id = oc.company_id
		left join dbo.company_address ca with (nolock)
			on ca.company_id = oc.company_id and ca.address_class_id = 1 and ca.address_status_id = 1 and ca.address_status_id = 1
		left join dbo.lu_countries lcc with (nolock)
			on lcc.country_id = ca.country_id
		left join dbo.company_address ca2 with (nolock)
			on ca2.company_id = oc.company_id and ca2.address_class_id = 2 and ca2.
address_status_id = 1 and ca2.address_status_id = 1
		left join dbo.lu_countries lcc2 with (nolock)
			on lcc2.country_id = ca2.country_id 
		left join dbo.customer_address a with (nolock)
			on oc.customer_id = a.customer_id and a.address_status_id = 1 and a.address_type_id = 1
		left join dbo.partner_company pc with (nolock)
			on pc.company_id = oc.company_id and pc.partner_id = @partner_id
		left join dbo.lu_countries lc with (nolock)
			on a.country_id = lc.country_id
		left join dbo.vendor_customer vc with (nolock)
			on vc.customer_id = oc.customer_id
		where oc.order_company_type_id = 1

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 5.) insert partner billing
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 5.1) trap failures on customer and retail price
		if exists (select 1 from #partner_billing where customer_id is null or retail_price is null) 
			begin

				-- 5.1.1) partner_billing_failure
				insert into dbo.partner_billing_failure (partner_billing_report_id, customer_id, customer_code, company_name,location_code, state, webroot_entity,reseller_customer_id,reseller_customer_code,reseller_company_name,
													reseller_location_code, reseller_state,license_id, keycode, keycode_age,order_header_id, order_date, product_id,license_category_id, license_attribute_license_value, license_seats,retail_price, extended_amount,
													usage_seats, usage_price,usage_extended_amount, total_seats, total_extended_amount, currency_id, partner_pricing_model_id, cap_amount, last_modified_date, failure_reason, company_id)
				select partner_billing_report_id = @partner_billing_report_id, customer_id, customer_code, company_name,location_code, state, webroot_entity,
						reseller_customer_id,reseller_customer_code, reseller_company_name,reseller_location_code, reseller_state,license_id, 
						keycode, keycode_age,order_header_id, order_date, product_id, license_category_id, license_attribute_license_value, 
						license_seats,
						retail_price, 
						extended_amount = license_seats * retail_price, 
						usage_seats, 
						usage_price, 
						usage_extended_amount = usage_seats * usage_price,
						total_seats, 
						total_extended_amount = (license_seats * retail_price + usage_seats * usage_price), currency_id, partner_pricing_model_id, 
						cap_amount, @last_modified_date, failure_reason = case when customer_id is null then 'customer_id' else 'retail_price' end,
						company_id
				from #partner_billing
				where customer_id is null or retail_price is null

				-- 5.1.2) update status
				update dbo.partner_billing_report
				set partner_billing_status_id = 5
				where partner_billing_report_id = @partner_billing_report_id

				print '5.1) partner_billing_failure'
			end
		else
		-- 5.2) insert
			begin

				-- 5.2.1) partner_billing
				insert into dbo.partner_billing (partner_billing_report_id, customer_id, company_id, customer_code, company_name,location_code, state, webroot_entity, reseller_customer_id,reseller_customer_code, reseller_company_name,reseller_location_code, reseller_state,
						license_id, keycode, keycode_age,order_header_id, order_date, product_id, license_category_id, license_attribute_license_value, license_seats,retail_price, extended_amount, usage_seats, usage_price, usage_extended_amount, total_seats, total_extended_amount, currency_id, partner_pricing_model_id, cap_amount, last_modified_date)	
				select @partner_billing_report_id, customer_id, company_id, customer_code, company_name,location_code, state, webroot_entity, 
						reseller_customer_id,reseller_customer_code, reseller_company_name,reseller_location_code
, reseller_state,license_id, 
						keycode, keycode_age,order_header_id, order_date, product_id, license_category_id, license_attribute_license_value, 
						license_seats,retail_price, extended_amount = license_seats * retail_price, 
						usage_seats, usage_price, usage_extended_amount = usage_seats * usage_price, total_seats,
						total_extended_amount = (license_seats * retail_price + usage_seats * usage_price), currency_id, partner_pricing_model_id, 
						cap_amount, @last_modified_date
				from #partner_billing
			
				-- 5.2.2) update reseller
				update dbo.partner_billing
				set reseller_customer_id = oc.customer_id, reseller_customer_code = vc.vendor_customer_code, reseller_state = a.state, reseller_company_name = c.company_name, reseller_location_code = lc.iso3
				from dbo.partner_billing b
				inner join dbo.order_company oc
					on oc.order_header_id = b.order_header_id and oc.order_company_type_id = 3
				inner join dbo.company c
					on c.company_id = oc.company_id
				inner join dbo.vendor_customer vc
					on vc.customer_id = oc.customer_id
				inner join dbo.customer_address a
					on a.customer_id = oc.customer_id and a.address_status_id = 1 and a.address_type_id = 1
				inner join dbo.lu_countries lc
					on lc.country_id = a.country_id
				where b.partner_billing_report_id = @partner_billing_report_id

				-- 5.2.3) total_cap_amount
				update l
				set	total_cap_amount = case 
									when l.cap_amount > 0 then (select sum(pb.cap_amount) 
															from partner_billing pb 
															inner join partner_billing_report pr
																on pr.partner_billing_report_id = pb.partner_billing_report_id
															where pr.partner_id = r.partner_id and pb.customer_code = l.customer_code and pb.license_category_id = l.license_category_id and pb.keycode = l.keycode and 
																	((pr.billing_date < r.billing_date and pr.partner_billing_status_id = 2 and pr.partner_billing_type_id = 1) or pr.partner_billing_report_id = r.partner_billing_report_id))
									else 0
								end
				from dbo.partner_billing_report r
				inner join dbo.partner_billing l
					on l.partner_billing_report_id = r.partner_billing_report_id
				where r.partner_billing_report_id = @partner_billing_report_id

				-- 5.2.4) update status
				if exists (select r.partner_billing_report_override_id from dbo.partner_billing_report_override r where r.partner_billing_report_id = @partner_billing_report_id)
					begin
						update dbo.partner_billing_report
						set partner_billing_status_id = 6, modified_date = getdate()
						where partner_billing_report_id = @partner_billing_report_id
					end
				else
					begin
						update dbo.partner_billing_report
						set partner_billing_status_id = 1, modified_date = getdate()
						where partner_billing_report_id = @partner_billing_report_id
					end

				print '5.2) partner_billing'
			end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'partner billing report failed to process'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec dbo.usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_campaign]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_campaign]

(
	@partner_key varchar(36),
	@salesforce_campaign_id varchar(18) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select available cart discounts for partners
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.1) select partner_campaign
	select partner_campaign_id, partner_id, salesforce_campaign_id
	from partner_campaign
	where partner_id = @partner_id and 
