CREATE PROCEDURE [dbo].[usp_partner_select_cart_locations]

(
	@partner_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-03	esmart		Initial creation.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key	

	declare @locations table (location_id int identity(1,1), country_id int,country_name varchar(75), language_code varchar(2), location_code varchar(3), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10))

	insert into @locations(country_id, country_name, language_code, location_code, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text)
	select lc.country_id, country_name = lc.description, cl.language_code, cl.location_code, 
		c.currency_id, c.currency_code, c.currency_description, c.symbol_html, c.symbol_utf8, c.symbol_text
	from currency_language_location cl
	inner join currency c
		on cl.currency_id = c.currency_id
	inner join lu_countries lc
		on cl.location_code = lc.iso3
	inner join partner_language_location pl
		on cl.language_code = pl.language_code and cl.location_code = pl.location_code
	where pl.partner_id = @partner_id and
		c.active = 1 
	
	
	select country_id, country_name, language_code, location_code, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text
	from @locations

	end try

	begin catch

