-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_select_keycode_order_status]

(
	@partner_key varchar(36),
	@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2021-03-24	esmart		Initial creation.

	DESCRIPTION
	Select orders related to license for the partner
*/

AS

	declare @partner_id int,
			@license_id int,
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	  			
	-- 1.1) @partner_id
	select @partner_id = p.partner_id
	from partner p
	left join company c
		on p.salesforce_id = c.salesforce_account_id
	where partner_key = @partner_key

	-- 1.2) @license_id 
	select @license_id = license_id from license where keycode = @keycode
	
	declare @orders table (order_header_id int, insert_date datetime, vendor_order_code varchar(100), exception_status varchar(50), partner_license_status_name varchar(50))

	insert into @orders(order_header_id,insert_date, vendor_order_code)	
	select distinct h.order_header_id, h.insert_date, v.vendor_order_code
	from order_item_license il
	inner join order_item i
		on i.order_item_id = il.order_item_id
	inner join order_header h
		on h.order_header_id = i.order_header_id
	inner join vendor_order v
		on v.vendor_order_id = h.vendor_order_id
	inner join partner_order po
		on po.order_header_id = i.order_header_id
	where il.license_id = @license_id and po.partner_id = @partner_id

	update o
	set o.exception_status = e.exception_status
	from @orders o
	inner join order_external_load_exception e
		on e.order_header_id = o.order_header_id
	--where e.exception_status = 'pending'

	update o
	set o.partner_license_status_name = s.partner_license_status_name
	from @orders o
	inner join partner_license pl
		on pl.order_header_id = o.order_header_id
	inner join partner_license_status s
		on s.partner_license_status_id = pl.partner_license_status_id
	--where pl.partner_license_status_id <> 2


	select @keycode as keycode, o.vendor_order_code, o.insert_date, o.exception_status, o.partner_license_status_name
	from @orders o 
	--- where o.exception_status is not null or o.partner_license_status_name is not null
	
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
