-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_license_expiration_summary]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_license_expiration_summary]

(
	@partner_key varchar(36),
	@start_date datetime = null,
	@end_date datetime = null,
	@category_type_name varchar(10) = null,
	@item_hierarchy_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-06	esmart		Initial creation.
	2017-07-26	esmart		Change to use partner_license
	2020-03-17	esmart		Refactor
	2020-11-19	wbarton		Adding storage_gb from fn_license_select_license_profile so it can be displayed to partners
	2021-05-06	esmart		Remove consumer for performance reasons
	2021-08-11  psatish		Ticket#:3620791(Created a new function:fn_license_select_license_profile_new to improve the performance)

	DESCRIPTION
	select license expriations for partners
*/

AS
	
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.2) @start_date/@end_date
	if @start_date is null or @end_date is null
		begin
		select @start_date = dateadd(mm,-1,getdate()),
				@end_date = dateadd(mm,3,@start_date)
		end

	declare @license_profile table (profile_id int identity(1,1), license_id int, license_category_name varchar(10), category_type_name varchar(10), item_hierarchy_id tinyint, expiration_date datetime, max_expiration_date datetime, license_seats int, storage_gb int)
--Added Table type for the new function:fn_license_select_license_profile_new
--Begins
	DECLARE @license_id AS License_TableType
	INSERT INTO @license_id
	select pl.license_id
	from partner_license pl with (nolock)
	inner join license_category_license cl with (nolock)
		on cl.license_id = pl.license_id
	left join license_parent lp with (nolock)
		on pl.license_id = lp.child_license_id
	where pl.partner_id = @partner_id and pl.partner_license_status_id = 2 and cl.license_category_id >= 190
	AND (pl.start_date < getdate() and (pl.end_date is null or pl.end_date > getdate())) and lp.license_parent_id is null
--ends
	-- 1.3) select licenses
	insert into @license_profile (license_id, license_category_name, category_type_name, item_hierarchy_id, expiration_date, license_seats, storage_gb)
	select 	f.license_id,f.license_category_name, f.category_type_name, f.item_hierarchy_id, f.expiration_date, f.license_seats, f.storage_gb
	from fn_license_select_license_profile_new(@license_id) f
	where @start_date <= f.expiration_date and f.expiration_date < @end_date 
	AND f.category_type_name=ISNULL(@category_type_name,f.category_type_name)
	AND f.item_hierarchy_id =ISNULL(@item_hierarchy_id,f.item_hierarchy_id)
		
	
	-- 1.4) update max_expistion_date
	update lp
	set lp.max_expiration_date = x.max_expiration_date
	from @license_profile lp 
	inner join (select p.license_id, max(p.expiration_date) as max_expiration_date
				from @license_profile p
				group by p.license_id) x
			on lp.license_id = x.license_id


	-- 1.5) results

	select lp.profile_id, l.license_id, l.keycode, license_key = convert(varchar(36),k.license_key), lp.license_category_name, lp.category_type_name, ih.item_hierarchy_id, ih.item_hierarchy_name, lp.expiration_date, lp.license_seats, lp.storage_gb,
			c.first_name, c.last_name, e.customer_email, cc.company_name
	from @license_
profile lp
	inner join item_hierarchy ih
		on lp.item_hierarchy_id = ih.item_hierarchy_id
	inner join license l with (nolock)
		on l.license_id = lp.license_id
	left join license_key k with (nolock)
		on l.license_id = k.license_id
	left join customer c with (nolock)
		on l.customer_id = c.customer_id
	left join customer_email e with (nolock)
		on l.customer_id = e.customer_id and e.email_status_id = 1
	left join customer_company cc with (nolock)
		on l.customer_id = cc.customer_id
	order by lp.max_expiration_date, lp.license_id, ih.item_hierarchy_id, lp.expiration_date desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
