-- PROCEDURE: [dbo].[usp_partner_select_partner]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner]

(
	@partner_key varchar(36) = null,
	@partner_configuration_id tinyint = null

)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2016-06-06	esmart		

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @partners table (partner_id int,partner_name nvarchar(100),partner_type_id tinyint,partner_type_name varchar(50),partner_status_id tinyint,partner_status_name varchar(50),partner_key varchar(36),salesforce_id varchar(20),oracle_id varchar(20),last_modified_date datetime,last_modified_by varchar(20),parent_partner_id int,parent_partner_name nvarchar(100),parent_partner_key varchar(36))

	-- 1.1) select partners
	insert into @partners(partner_id, partner_name, partner_type_id, partner_type_name, partner_status_id, partner_status_name, partner_key, salesforce_id, oracle_id, last_modified_date, last_modified_by, parent_partner_id, parent_partner_name, parent_partner_key)
	select p.partner_id, 
			p.partner_name, 
			t.partner_type_id, 
			t.partner_type_name, 
			s.partner_status_id, 
			s.partner_status_name, 
			partner_key = convert(varchar(36),p.partner_key), 
			p.salesforce_id, 
			p.oracle_id, 
			p.last_modified_date, 
			p.last_modified_by, 
			p.parent_partner_id, 
			parent_partner_name = pp.partner_name, 
			parent_partner_key = convert(varchar(36),pp.partner_key)
	from partner p
	inner join partner_type t
		on p.partner_type_id = t.partner_type_id
	inner join partner_status s
		on p.partner_status_id = s.partner_status_id
	left join partner pp
		on p.parent_partner_id = pp.partner_id
	where p.partner_key = case when @partner_key is null then p.partner_key else @partner_key end
	
	-- 1.2) @partner_configuration_id
	if @partner_configuration_id is not null
		begin
		delete from @partners
		where partner_id not in (select partner_id from partner_configuration_partner where partner_configuration_id = @partner_configuration_id)
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select partner_id, partner_name, partner_type_id, partner_type_name, partner_status_id, partner_status_name, partner_key, salesforce_id, oracle_id, last_modified_date, last_modified_by, parent_partner_id, parent_partner_name, parent_partner_key
	from @partners
	order by partner_name



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
