CREATE procedure [dbo].[usp_partner_select_partner_account]

(
  @partner_account_key varchar(36)
)

/*
  DATE			AUTHOR		REMARKS
  2013-01-07	esmart		Initial creation.
  2015-05-13	esmart		Add shared_account
  2016-11-10	mandersen	Added partner_account_status columns.
  2017-08-11	esmart		Add partner_key

  DESCRIPTION
  select partner account
*/

as 
  set nocount on

  declare @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) select
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  -- 1.2) select partner accounts
  select pa.partner_account_id, partner_key = convert(varchar(36),p.partner_key), partner_account_key = convert(varchar(36),pa.partner_account_key), pa.insert_by, pa.partner_id, a.account_id, a.account_user_name, a.account_status_id, s.account_status, pa.shared_account, a.password_reset_date, pa.partner_account_status_id, ps.partner_account_status_name
  from partner_account pa
  inner join partner p
	on p.partner_id = pa.partner_id
  inner join account a
    on pa.account_id = a.account_id
  inner join account_status s
    on a.account_status_id = s.account_status_id
  inner join partner_account_status ps
    on pa.partner_account_status_id = ps.partner_account_status_id
  where pa.partner_account_key = @partner_account_key

  end try

  begin catch

