CREATE PROCEDURE [dbo].[usp_partner_select_partner_account_reset]

(
	@partner_account_reset_key varchar(36),
	@reset_status tinyint = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select partner account reset
*/

AS
	set nocount on				

	declare @partner_account_key varchar(36),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get partner_account_key
	select @partner_account_key = partner_account_key 
	from partner_account_reset
	where partner_account_reset_key = @partner_account_reset_key and reset_status = 0 and expiration_date > getdate()

	-- 1.2) update status
	if @reset_status = 1
		begin
			update partner_account_reset 
			set reset_status = @reset_status
			where partner_account_reset_key = @partner_account_reset_key
		end

	-- 1.3) return account details
	exec usp_partner_select_partner_account @partner_account_key

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
