CREATE PROCEDURE [dbo].[usp_partner_select_partner_account_verify]

(
	@partner_key varchar(36),
	@account_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	Verify account is linked to partner
*/

AS
	set nocount on				

	declare	@partner_id int,
			@verified tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.1) select partner_status
	select @verified = count(*)
	from account a
	where a.account_id in (select account_id
							from partner_account 
							where partner_id = @partner_id)
			and a.account_id = @account_id

	-- 1.2) log failure
	if @verified = 0
		begin
		insert into partner_verify_failure(partner_id, verify_type, verify_value)
		values(@partner_id, 'account_id', @account_id)
		end

	select verified = @verified

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
