CREATE PROCEDURE [dbo].[usp_partner_select_partner_billing]

(
		@partner_billing_report_id int,
		@license_category_id int = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-05-31		esmart			Initial creation
	2017-06-01		esmart			Add license_category
	2018-03-06		esmart			update result set
	2020-09-22		esmart			remove summary results
	2020-10-28		esmart			Add @license_category_name optional input
	
	DESCRIPTION
	select billing report
*/

as

	set nocount on
	set ansi_warnings on
	set ansi_nulls on		

	declare	@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @report table (row_id int identity(1,1), billing_date date,customer_code varchar(64),company_name nvarchar(100),reseller_customer_code varchar(64),reseller_company_name nvarchar(100),webroot_entity varchar(3),location_code varchar(3),state nvarchar(2),keycode varchar(40),license_type_description varchar(20),license_seats int, usage_seats int, total_seats int,order_date date,license_category_id tinyint, license_category_name varchar(10),keycode_age int,retail_price money,total_extended_amount money,cap_amount money,total_cap_amount float, currency_id int)

	-- 1.1) insert report data
	insert into @report (billing_date, customer_code, company_name, reseller_customer_code, reseller_company_name, webroot_entity, location_code, state, keycode, license_type_description, license_seats, usage_seats, total_seats, order_date, license_category_id, license_category_name, keycode_age, retail_price, total_extended_amount, cap_amount, total_cap_amount, currency_id)
	select r.billing_date, l.customer_code, l.company_name, l.reseller_customer_code, l.reseller_company_name, l.webroot_entity, l.location_code, l.state, l.keycode, t.license_type_description, 
		l.license_seats, l.usage_seats, l.total_seats, l.order_date, l.license_category_id, lc.license_category_name, l.keycode_age, l.retail_price, l.total_extended_amount, 
		l.cap_amount,
		l.total_cap_amount,
		l.currency_id
	from partner_billing_report r
	inner join partner_billing l
		on l.partner_billing_report_id = r.partner_billing_report_id
	inner join license ll
		on l.license_id = ll.license_id
	inner join license_type t
		on ll.license_type_id = t.license_type_id
	inner join license_category lc
		on lc.license_category_id = l.license_category_id
	where r.partner_billing_report_id = @partner_billing_report_id and
		l.license_category_id = case when @license_category_id is null then lc.license_category_id else @license_category_id end
	order by keycode_age, l.license_id

	-- 1.3) return result
	select billing_date, r.customer_code, r.company_name, 
		isnull(r.reseller_customer_code,'') as reseller_customer_code, 
		isnull(r.reseller_company_name,'') as reseller_company_name, 
		r.webroot_entity, 
		r.location_code, 
		r.state, 
		r.keycode, 
		case when r.license_type_description = 'OEM' then 'GSM' else r.license_type_description end as license_type_description, 
		r.license_seats, 
		r.usage_seats, 
		r.total_seats, 
		r.order_date, 
		r.license_category_name, 
		r.keycode_age, 
		r.retail_price, 
		r.total_extended_amount, 
		r.cap_amount, 
		r.total_cap_amount,
		cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
	from @report r
	inner join currency cu
		on cu.currency_id = r.currency_id
	order by row_id

	end try

	begin catch

		set
 @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_billing_order]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_select_partner_billing_order]


(
	@partner_billing_report_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2020-09-22	esmart		Initial creation.

	DESCRIPTION
	select partner_billing_order
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select r.partner_billing_report_id, r.partner_billing_report_name, r.billing_date, h.order_header_id, h.site_id, v.vendor_order_code, h.insert_date
		from partner_billing_report r
		inner join partner_billing_order o
			on o.partner_billing_report_id = r.partner_billing_report_id
		inner join order_header h 
			on h.order_header_id = o.order_header_id
		inner join vendor_order v
			on v.vendor_order_id = h.vendor_order_id
		where r.partner_billing_report_id = @partner_billing_report_id

		
		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_billing_report]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_partner_select_partner_billing_report] (
		@partner_billing_report_id int = null,
		@partner_id int = null,
		@partner_billing_status_id tinyint = null,
		@partner_billing_type_id tinyint = null,
		@start_date datetime = null,
		@override_license_category_id int = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-02-23		esmart			Initial creation
	2020-09-22		esmart			Add additional data
	2020-11-02		esmart			Add @override_license_category_id
	2021-03-30		esmart			Change date for override to include previous dates
	2023-01-30		gblandford		https://jira.opentext.com/browse/ECOM-710 Handle NULL @partner_billing_status_id in @start_date check 
									- was causing timeout / service failure
	
	DESCRIPTION
	process billing report
*/

as

	set nocount on
	set ansi_warnings on
	set ansi_nulls on		

	declare	@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @partner_billing table (partner_billing_report_id int, partner_billing_report_name varchar(100), partner_id int,partner_name nvarchar(100),partner_billing_status_id tinyint,partner_billing_status_name varchar(50),partner_billing_type_id tinyint,partner_billing_type_name varchar(50),billing_date datetime, insert_date datetime, insert_by varchar(20), modified_date datetime, modified_by varchar(20),record_count int)

	-- 1.1) insert billing
	insert into @partner_billing (partner_billing_report_id, partner_billing_report_name, partner_id, partner_name, partner_billing_status_id, partner_billing_status_name, partner_billing_type_id, partner_billing_type_name, billing_date, insert_date, insert_by, modified_date, modified_by)
	select b.partner_billing_report_id, b.partner_billing_report_name, p.partner_id, p.partner_name, s.partner_billing_status_id, s.partner_billing_status_name, t.partner_billing_type_id, t.partner_billing_type_name, b.billing_date, b.insert_date, b.insert_by, b.modified_date, b.modified_by
	from partner_billing_report b
	inner join partner p
		on p.partner_id = b.partner_id
	inner join partner_billing_status s
		on s.partner_billing_status_id = b.partner_billing_status_id
	inner join partner_billing_type t
		on t.partner_billing_type_id = b.partner_billing_type_id
	where b.partner_id = case when @partner_id is null then b.partner_id else @partner_id end and
		b.partner_billing_report_id = case when @partner_billing_report_id is null then b.partner_billing_report_id else @partner_billing_report_id end and
		b.partner_billing_status_id = case when @partner_billing_status_id is null then b.partner_billing_status_id else @partner_billing_status_id end and 
		b.partner_billing_type_id = case when @partner_billing_type_id is null then b.partner_billing_type_id else @partner_billing_type_id end

	-- 1.2) remove report prior to @start_date
	if @start_date is not null and ( @partner_billing_status_id <> 6 OR @partner_billing_status_id IS NULL )
		begin
		delete from @partner_billing where billing_date < @start_date
		end

	-- 1.3) partner_billing_report_override
	if @override_license_category_id is not null
		begin
			delete b
			from @partner_billing b
			left join partner_billing_report_override r
				on r.partner_billing_report_id = b.partner_billing_report_id and b.partner_billing_status_id = r.partner_billing_status_id and r.lice
nse_category_id = @override_license_category_id
			where r.partner_billing_report_override_id is null
		end
		
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select b.partner_billing_report_id, b.partner_billing_report_name, b.partner_id, b.partner_name, b.partner_billing_status_id, b.partner_billing_status_name, b.partner_billing_type_id, b.partner_billing_type_name, b.billing_date, b.insert_date, b.insert_by, b.modified_date, b.modified_by, 
		 (select count(*) from partner_billing where partner_billing_report_id = b.partner_billing_report_id) as record_count,
		(select count(distinct license_id) from partner_billing_failure where partner_billing_report_id = b.partner_billing_report_id) as failure_count,
		(select sum(r.total_extended_amount) from partner_billing r where r.partner_billing_report_id = b.partner_billing_report_id) as total_extended_amount,
		cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
	from @partner_billing b
	inner join (select r.partner_billing_report_id, r.currency_id, sum(r.total_extended_amount) as total_extended_amount
				from partner_billing r 
				group by r.partner_billing_report_id, r.currency_id) x
		on b.partner_billing_report_id = x.partner_billing_report_id
	inner join currency cu
		on cu.currency_id = x.currency_id
	order by b.partner_billing_report_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_billing_revenue_report]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_partner_select_partner_billing_revenue_report] (
	@report_date DATE = NULL,
	@partner_id INT = NULL,
	@site_id VARCHAR(20) = NULL,
	@currency_id INT = NULL,
	@license_category_id INT = NULL,
	@report_type VARCHAR(20) = 'LICENSE', -- 'LICENSE', 'PARTNER', 'TOTALS'
	@opt_args VARCHAR(20) = ''

)

/*	
	DATE			AUTHOR		REMARKS
	2025-01-31		gblandford	Initial creation
								For auditing purposes as part of https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4390153
	2025-03-03		gblandford	Added partner key to results

	DESCRIPTION
	This procedure selects the partner billing revenue report that is created as part of the aggregator report run.

	The procedure dbo.usp_partner_insert_partner_billing_revenue_report creates the fact tables that support the report.
	
	The report will detail the license and usage revenue per license for the current billing cycle and then provide the prior months
	equivalent license and usage reveue. In addition, it provides period averages (set to 3 months, including the prior month).

	These prior month and period averages can be used to identfy drop-off by partner, or by individual license.

	The report can be filtered on partner, site (MSP/RESELLER) and license category.
	
*/

AS

	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	SET NOCOUNT ON

	BEGIN TRY

		IF @report_date IS NULL SET @report_date = ( SELECT MAX(report_date) 
														FROM dbo.partner_billing_revenue_fact )

		DROP TABLE IF EXISTS #partner_billing_revenue_report;
		DROP TABLE IF EXISTS #partner_billing_revenue_fact;
		
		CREATE TABLE #partner_billing_revenue_report (
			partner_billing_revenue_report_id INT IDENTITY (1, 1),
			report_date DATE DEFAULT GETDATE(),
			partner_id INT,
			partner_name VARCHAR(50),
			site_id VARCHAR(20),
			currency_code VARCHAR(10),
			license_id INT,
			keycode VARCHAR(20),
			license_category_name VARCHAR(10),

			current_billing_date DATE,
			current_license_seats INT,
			current_unit_price DECIMAL(10, 2),
			current_total DECIMAL(10, 2),
			current_usage_seats INT,
			current_usage_price DECIMAL(10, 2),
			current_usage_total DECIMAL(10, 2),
			current_billing_total DECIMAL(10, 2),
			current_actual_billed_order_total DECIMAL(10, 2),

			prior_billing_date DATE,
			prior_license_seats INT,
			prior_unit_price DECIMAL(10, 2),
			prior_total DECIMAL(10, 2),
			prior_usage_seats INT,
			prior_usage_price DECIMAL(10, 2),
			prior_usage_total DECIMAL(10, 2),
			prior_billing_total DECIMAL(10, 2),
			prior_actual_billed_order_total DECIMAL(10, 2),

			period_reports INT,
			period_billing_cycles INT,

			period_from DATE,
			period_to DATE,

			average_license_seats INT,
			average_retail_price DECIMAL(10, 2),
			average_extended_amount DECIMAL(10, 2),
			average_usage_seats INT,
			average_usage_price DECIMAL(10, 2),
			average_usage_extended_amount DECIMAL(10, 2),
			average_billing_total DECIMAL(10, 2),
			average_actual_billed_order_total DECIMAL(10, 2)
		);

		CREATE TABLE #partner_billing_revenue_fact (
			[partner_billing_revenue_fact_id] [int],
			[report_date] [date] NOT NULL,
			[partner_id] [int] NOT NULL,
			[site_id] [varchar](20) NOT NULL,
			[currency_id] [int] NOT NULL,
			[license_id] [int] NOT NULL,
			[license_category_id] [int] NOT NULL,
			[current_billing_date] [date] NULL,
			[current_license_seats] [int] NULL,
			[current_unit_price] [decimal](10, 2) NULL,
			[current_total] [decimal](10, 2) NULL,
			[current_usage_seats] [int] NULL,
			[current_usage_price] [decimal](10, 2) NULL,
			[current_usage_total] [decimal](10, 2) NULL,
			[current_billing_total] [decim
al](10, 2) NULL,
			[prior_billing_date] [date] NULL,
			[prior_license_seats] [int] NULL,
			[prior_unit_price] [decimal](10, 2) NULL,
			[prior_total] [decimal](10, 2) NULL,
			[prior_usage_seats] [int] NULL,
			[prior_usage_price] [decimal](10, 2) NULL,
			[prior_usage_total] [decimal](10, 2) NULL,
			[prior_billing_total] [decimal](10, 2) NULL,
			[period_reports] [int] NULL,
			[period_billing_cycles] [int] NULL,
			[period_from] [date] NULL,
			[period_to] [date] NULL,
			[average_license_seats] [int] NULL,
			[average_retail_price] [decimal](10, 2) NULL,
			[average_extended_amount] [decimal](10, 2) NULL,
			[average_usage_seats] [int] NULL,
			[average_usage_price] [decimal](10, 2) NULL,
			[average_usage_extended_amount] [decimal](10, 2) NULL,
			[average_billing_total] [decimal](10, 2) NULL
		);

		/*
		|
		| Get the fact data that we need
		|
		*/
		INSERT INTO #partner_billing_revenue_fact (
		    partner_billing_revenue_fact_id,
		    report_date,
		    partner_id,
		    site_id,
		    currency_id,
		    license_id,
		    license_category_id,
		    current_billing_date,
		    current_license_seats,
		    current_unit_price,
		    current_total,
		    current_usage_seats,
		    current_usage_price,
		    current_usage_total,
		    current_billing_total,
		    prior_billing_date,
		    prior_license_seats,
		    prior_unit_price,
		    prior_total,
		    prior_usage_seats,
		    prior_usage_price,
		    prior_usage_total,
		    prior_billing_total,
		    period_reports,
		    period_billing_cycles,
		    period_from,
		    period_to,
		    average_license_seats,
		    average_retail_price,
		    average_extended_amount,
		    average_usage_seats,
		    average_usage_price,
		    average_usage_extended_amount,
		    average_billing_total
		)
		SELECT
			fact.partner_billing_revenue_fact_id,
            fact.report_date,
            fact.partner_id,
            fact.site_id,
            fact.currency_id,
            fact.license_id,
            fact.license_category_id,
            fact.current_billing_date,
            fact.current_license_seats,
            fact.current_unit_price,
            fact.current_total,
            fact.current_usage_seats,
            fact.current_usage_price,
            fact.current_usage_total,
            fact.current_billing_total,
            fact.prior_billing_date,
            fact.prior_license_seats,
            fact.prior_unit_price,
            fact.prior_total,
            fact.prior_usage_seats,
            fact.prior_usage_price,
            fact.prior_usage_total,
            fact.prior_billing_total,
            fact.period_reports,
            fact.period_billing_cycles,
            fact.period_from,
            fact.period_to,
            fact.average_license_seats,
            fact.average_retail_price,
            fact.average_extended_amount,
            fact.average_usage_seats,
            fact.average_usage_price,
            fact.average_usage_extended_amount,
            fact.average_billing_total
		FROM dbo.partner_billing_revenue_fact fact

		WHERE fact.report_date = @report_date
			AND fact.partner_id = ISNULL( @partner_id, fact.partner_id ) 
			AND fact.site_id = ISNULL( @site_id, fact.site_id )
			AND 1 = ( CASE 
							WHEN @partner_id IS NULL AND fact.partner_id = 10269 THEN 0
							WHEN @partner_id = 10269 THEN 1
							ELSE 1
						END	)
			AND fact.license_category_id = ISNULL( @license_category_id, fact.license_category_id )
			AND ISNULL( fact.currency_id, 1 ) = ISNULL( @currency_id, ISNULL( fact.currency_id, 1 ) )		;
		
		/*
		|
		| Produce a detail report based on license
		|
		*/
		IF @report_type = 'LICENSE' BEGIN

				INSERT INTO #partner_billing_revenue_report (
					partner_id,
					partner_name,
					site_id,
					currency_code,
					license_id,
					keycode,
					license_category_name,
					current_billing_date,
			
		current_license_seats,
					current_unit_price,
					current_total,
					current_usage_seats,
					current_usage_price,
					current_usage_total,
					current_billing_total,
					current_actual_billed_order_total,
					prior_billing_date,
					prior_license_seats,
					prior_unit_price,
					prior_total,
					prior_usage_seats,
					prior_usage_price,
					prior_usage_total,
					prior_billing_total,
					prior_actual_billed_order_total,
					period_reports,
					period_billing_cycles,
					period_from,
					period_to,
					average_license_seats,
					average_retail_price,
					average_extended_amount,
					average_usage_seats,
					average_usage_price,
					average_usage_extended_amount,
					average_billing_total,
					average_actual_billed_order_total
				)
				SELECT
					fact.partner_id,
					p.partner_name,
					fact.site_id,
					cu.currency_code,
					fact.license_id,
					l.keycode,
					lc.license_category_name,

					fact.current_billing_date,
					fact.current_license_seats,
					fact.current_unit_price,
					fact.current_total,
					fact.current_usage_seats,
					fact.current_usage_price,
					fact.current_usage_total,
					fact.current_billing_total,
					NULL AS current_actual_billed_order_total,

					fact.prior_billing_date,
					fact.prior_license_seats,
					fact.prior_unit_price,
					fact.prior_total,
					fact.prior_usage_seats,
					fact.prior_usage_price,
					fact.prior_usage_total,
					fact.prior_billing_total,
					NULL AS prior_actual_billed_order_total,

					fact.period_reports,
					fact.period_billing_cycles,
					fact.period_from,
					fact.period_to,
	
					fact.average_license_seats,
					fact.average_retail_price,
					fact.average_extended_amount,
					fact.average_usage_seats,
					fact.average_usage_price,
					fact.average_usage_extended_amount,
					fact.average_billing_total,
					NULL AS average_actual_billed_order_total

				FROM #partner_billing_revenue_fact fact
					INNER JOIN dbo.partner p 
						ON p.partner_id = fact.partner_id
					INNER JOIN dbo.license_category lc
						ON lc.license_category_id = fact.license_category_id
					INNER JOIN dbo.license l 
						ON l.license_id = fact.license_id
					INNER JOIN dbo.currency cu
						ON cu.currency_id = fact.currency_id

				ORDER BY fact.partner_billing_revenue_fact_id;
		END

		IF @report_type = 'PARTNER' BEGIN

				INSERT INTO #partner_billing_revenue_report (
					partner_id,
					partner_name,
					site_id,
					currency_code,
					license_id,
					keycode,
					license_category_name,
					current_billing_date,
					current_license_seats,
					current_unit_price,
					current_total,
					current_usage_seats,
					current_usage_price,
					current_usage_total,
					current_billing_total,
					current_actual_billed_order_total,
					prior_billing_date,
					prior_license_seats,
					prior_unit_price,
					prior_total,
					prior_usage_seats,
					prior_usage_price,
					prior_usage_total,
					prior_billing_total,
					prior_actual_billed_order_total,
					period_reports,
					period_billing_cycles,
					period_from,
					period_to,
					average_license_seats,
					average_retail_price,
					average_extended_amount,
					average_usage_seats,
					average_usage_price,
					average_usage_extended_amount,
					average_billing_total,
					average_actual_billed_order_total
				)
				SELECT
					DISTINCT
					fact.partner_id AS partner_id,
					p.partner_name AS partner_name,
					fact.site_id AS site_id,
					cu.currency_code AS currency_code,
					NULL AS license_id,
					NULL AS keycode,
					NULL AS license_category_name,

					MAX( fact.current_billing_date ) AS current_billing_date,
					SUM( fact.current_license_seats ) AS current_license_seats,
					NULL AS current_unit_price,
					SUM( fact.current_total ) AS current_total,
					SUM( fact.current_usage_seats ) AS current_usage_seats
,
					NULL AS current_usage_price,
					SUM( fact.current_usage_total ) AS current_usage_total,
					SUM( fact.current_billing_total ) AS current_billing_total,
					NULL AS current_actual_billed_order_total,

					MAX(fact.prior_billing_date) AS prior_billing_date,
					SUM( fact.prior_license_seats ) AS prior_license_seats,
					NULL AS prior_unit_price,
					SUM( fact.prior_total ) AS prior_total,
					SUM( fact.prior_usage_seats ) AS prior_usage_seats,
					NULL AS prior_usage_price,
					SUM( fact.prior_usage_total ) AS prior_usage_total,
					SUM( fact.prior_billing_total ) AS prior_billing_total,
					NULL AS prior_actual_billed_order_total,

					MAX( fact.period_reports ) AS period_reports,
					MAX( fact.period_billing_cycles ) AS period_billing_cycles,

					MIN( fact.period_from ) AS period_from,
					MAX( fact.period_to ) AS period_to,

					SUM( fact.average_license_seats ) AS average_license_seats,
					NULL AS average_retail_price,
					SUM( fact.average_extended_amount ) AS average_extended_amount,
					SUM( fact.average_usage_seats ) AS average_usage_seats,
					NULL AS average_usage_price,
					SUM( fact.average_usage_extended_amount ) AS average_usage_extended_amount,
					SUM( fact.average_billing_total ) AS average_billing_total,
					NULL AS average_actual_billed_order_total			

				FROM #partner_billing_revenue_fact fact
					INNER JOIN dbo.partner p 
						ON p.partner_id = fact.partner_id
					INNER JOIN dbo.license_category lc
						ON lc.license_category_id = fact.license_category_id
					INNER JOIN dbo.license l 
						ON l.license_id = fact.license_id
					INNER JOIN dbo.currency cu
						ON cu.currency_id = fact.currency_id

				GROUP BY fact.partner_id, p.partner_name, fact.site_id, fact.currency_id, cu.currency_code
				ORDER BY fact.partner_id, p.partner_name, fact.site_id, cu.currency_code;

				/*
				|
				|	Update the actual billed values
				|
				*/
				UPDATE r
					SET 
						r.current_actual_billed_order_total = pbrof_current.order_total,
						r.prior_actual_billed_order_total = pbrof_prior.order_total,
						r.average_actual_billed_order_total = pbrof_average.order_total

				FROM #partner_billing_revenue_report r
					LEFT JOIN (
									SELECT
										r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
										cu.currency_code,
										SUM( pbrof.order_total ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
										INNER JOIN #partner_billing_revenue_report r
											ON r.partner_id = pbrof.partner_id
												AND r.site_id = pbrof.site_id
												AND pbrof.billing_date = r.current_billing_date
												AND cu.currency_code = r.currency_code
										WHERE pbrof.report_date = @report_date
									GROUP BY r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
										cu.currency_code
								) pbrof_current
						ON pbrof_current.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

					LEFT JOIN (
									SELECT
										DISTINCT
										r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
										cu.currency_code,
										SUM( pbrof.order_total ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
									INNER JOIN #partner_billing_revenue_report r
											ON r.partner_id = pbrof.partner_id
												AND r.site_id = pbrof.site_id
												AND pbrof.billing_date = r.prior_billing_date
												AND cu.currency_code = r.currency_code
									WHERE pbrof.report_date = @report_date
									GROUP BY r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
							
			cu.currency_code
								) pbrof_prior
						ON pbrof_prior.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

					LEFT JOIN (
									SELECT
										r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
										cu.currency_code,
										SUM( CASE WHEN r.period_billing_cycles = 0 THEN 0
												ELSE pbrof.order_total  / r.period_billing_cycles  
											END ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
										INNER JOIN #partner_billing_revenue_report r
											ON r.partner_id = pbrof.partner_id
												AND r.site_id = pbrof.site_id
												AND pbrof.billing_date <> r.current_billing_date
												AND cu.currency_code = r.currency_code
									WHERE pbrof.report_date = @report_date
									GROUP BY r.partner_billing_revenue_report_id,
										pbrof.partner_id,
										pbrof.site_id,
										cu.currency_code
								) pbrof_average
						ON pbrof_average.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

			END

		IF @report_type = 'TOTALS' BEGIN

				INSERT INTO #partner_billing_revenue_report (
					partner_id,
					partner_name,
					site_id,
					currency_code,
					license_id,
					keycode,
					license_category_name,
					current_billing_date,
					current_license_seats,
					current_unit_price,
					current_total,
					current_usage_seats,
					current_usage_price,
					current_usage_total,
					current_billing_total,
					current_actual_billed_order_total,
					prior_billing_date,
					prior_license_seats,
					prior_unit_price,
					prior_total,
					prior_usage_seats,
					prior_usage_price,
					prior_usage_total,
					prior_billing_total,
					prior_actual_billed_order_total,
					period_reports,
					period_billing_cycles,
					period_from,
					period_to,
					average_license_seats,
					average_retail_price,
					average_extended_amount,
					average_usage_seats,
					average_usage_price,
					average_usage_extended_amount,
					average_billing_total,
					average_actual_billed_order_total
				)
				SELECT
					NULL AS partner_id,
					'Totals' AS partner_name,
					NULL AS site_id,
					cu.currency_code AS currency_code,
					NULL AS license_id,
					NULL AS keycode,
					NULL AS license_category_name,

					MAX( fact.current_billing_date ) AS current_billing_date,
					SUM( fact.current_license_seats ) AS current_license_seats,
					NULL AS current_unit_price,
					SUM( fact.current_total ) AS current_total,
					SUM( fact.current_usage_seats ) AS current_usage_seats,
					NULL AS current_usage_price,
					SUM( fact.current_usage_total ) AS current_usage_total,
					SUM( fact.current_billing_total ) AS current_billing_total,
					NULL AS current_actual_billed_order_total,

					MAX( fact.prior_billing_date ) AS prior_billing_date,
					SUM( fact.prior_license_seats ) AS prior_license_seats,
					NULL AS prior_unit_price,
					SUM( fact.prior_total ) AS prior_total,
					SUM( fact.prior_usage_seats ) AS prior_usage_seats,
					NULL AS prior_usage_price,
					SUM( fact.prior_usage_total ) AS prior_usage_total,
					SUM( fact.prior_billing_total ) AS prior_billing_total,
					NULL AS prior_actual_billed_order_total,

					MAX( fact.period_reports ) AS period_reports,
					MAX( fact.period_billing_cycles ) AS period_billing_cycles,

					MIN( fact.period_from ) AS period_from,
					MAX( fact.period_to ) AS period_to,

					SUM( fact.average_license_seats ) AS average_license_seats,
					NULL AS average_retail_price,
					SUM( fact.average_extended_amount ) AS average_extended_amount,
					SUM( fact.average_usage_seats ) AS average_usage_seats,
					NULL AS average_usage_price,
					SUM( fact.average_usage_extended_amount ) AS average_usage_extended_amount,
					SUM( fac
t.average_billing_total ) AS average_billing_total,
					NULL AS average_actual_billed_order_total

				FROM #partner_billing_revenue_fact fact
					INNER JOIN dbo.partner p 
						ON p.partner_id = fact.partner_id
					INNER JOIN dbo.license_category lc
						ON lc.license_category_id = fact.license_category_id
					INNER JOIN dbo.license l 
						ON l.license_id = fact.license_id
					INNER JOIN dbo.currency cu
						ON cu.currency_id = fact.currency_id
		
				GROUP BY fact.currency_id, cu.currency_code;


				UPDATE r
					SET 
						r.current_actual_billed_order_total = pbrof_current.order_total,
						r.prior_actual_billed_order_total = pbrof_prior.order_total,
						r.average_actual_billed_order_total = pbrof_average.order_total

				FROM #partner_billing_revenue_report r
					LEFT JOIN (
									SELECT
										r.partner_billing_revenue_report_id,
										cu.currency_code,
										SUM( pbrof.order_total ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
										INNER JOIN #partner_billing_revenue_report r
											ON cu.currency_code = r.currency_code

									WHERE MONTH( pbrof.billing_date ) = MONTH( r.current_billing_date )
										AND pbrof.report_date = @report_date
									GROUP BY r.partner_billing_revenue_report_id,
										cu.currency_code
								) pbrof_current
						ON pbrof_current.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

					LEFT JOIN (
									SELECT
										DISTINCT
										r.partner_billing_revenue_report_id,
										cu.currency_code,
										SUM( pbrof.order_total ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
									INNER JOIN #partner_billing_revenue_report r
											ON cu.currency_code = r.currency_code
									
									WHERE MONTH( pbrof.billing_date ) = MONTH( r.prior_billing_date )
										AND pbrof.report_date = @report_date									
									GROUP BY r.partner_billing_revenue_report_id,
										cu.currency_code
								) pbrof_prior
						ON pbrof_prior.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

					LEFT JOIN (
									SELECT
										r.partner_billing_revenue_report_id,
										cu.currency_code,
										SUM( CASE WHEN r.period_billing_cycles = 0 THEN 0
												ELSE pbrof.order_total  / r.period_billing_cycles  
											END ) AS order_total
									FROM dbo.partner_billing_revenue_order_fact pbrof
										INNER JOIN dbo.currency cu
											ON cu.currency_id = pbrof.currency_id
										INNER JOIN #partner_billing_revenue_report r
											ON cu.currency_code = r.currency_code

									WHERE MONTH( pbrof.billing_date ) <> MONTH( r.current_billing_date )
										AND pbrof.report_date = @report_date
									GROUP BY r.partner_billing_revenue_report_id,
										cu.currency_code
								) pbrof_average
						ON pbrof_average.partner_billing_revenue_report_id = r.partner_billing_revenue_report_id

			END

		/*
		|
		| Return results
		|
		*/
		SELECT 
			r.partner_id,
			r.partner_name,
			p.partner_key,
			r.site_id,
			r.currency_code,
			r.license_id,
			r.keycode,
			r.license_category_name,
			r.current_billing_date,
			r.current_license_seats,
			r.current_unit_price,
			r.current_total,
			r.current_usage_seats,
			r.current_usage_price,
			r.current_usage_total,
			r.current_billing_total,
			r.current_actual_billed_order_total,

			r.prior_billing_date,
			r.prior_license_seats,
			r.prior_unit_price,
			r.prior_total,
			r.prior_usage_seats,
			r.prior_usage_price,
			r.prior_usage_total,
			r.prior_billing_total,
			r.prior_actual_billed_order_total,

			( ISNULL( r.current_billing_total, 0 ) - r.prior_billing_total ) AS current
_vs_prior_billing_total_difference,

			CAST( ( CASE 
					WHEN ( ISNULL( r.current_billing_total, 0 ) - r.prior_billing_total ) <> 0 THEN
							( ( ISNULL( r.current_billing_total, 0 ) - r.prior_billing_total ) / r.prior_billing_total ) * 100
					ELSE 0
				END ) AS DECIMAL( 10, 2) ) AS current_vs_prior_billing_total_difference_pct,

			r.period_reports,
			r.period_billing_cycles,
			r.period_from,
			r.period_to,
			r.average_license_seats,
			r.average_retail_price,
			r.average_extended_amount,
			r.average_usage_seats,
			r.average_usage_price,
			r.average_usage_extended_amount,
			r.average_billing_total,

			r.average_actual_billed_order_total,

			( ISNULL( r.current_billing_total, 0 ) - r.average_billing_total ) AS current_vs_average_billing_total_difference,

			CAST( ( CASE 
					WHEN ( ISNULL( r.current_billing_total, 0 ) - r.average_billing_total ) <> 0 THEN
							( ( ISNULL( r.current_billing_total, 0 ) - r.average_billing_total ) / r.average_billing_total ) * 100
					ELSE 0
				END ) AS DECIMAL( 10, 2) ) AS current_vs_average_billing_total_difference_pct

		FROM #partner_billing_revenue_report r
			LEFT JOIN dbo.partner p 
				ON p.partner_id = r.partner_id
		ORDER BY r.partner_billing_revenue_report_id;

	END TRY

	BEGIN CATCH
	
		DECLARE @DBName NVARCHAR(128);
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_billing_revenue_report_elements]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_partner_select_partner_billing_revenue_report_elements] (
	@report_date DATE = NULL,
	@opt_args VARCHAR(20) = ''

)

/*	
	DATE			AUTHOR		REMARKS
	2025-02-13		gblandford	Initial creation
								For auditing purposes as part of https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4390153
	2025-03-03		gblandford	Added default report date to results

	DESCRIPTION
	This procedure returns the values required to populate the CSI dropdown elements that are used to filter the partner billing revenue report.
	
	The report elements are partner, site (MSP/RESELLER) and license category and currency.


	
*/

AS

	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	SET NOCOUNT ON

	BEGIN TRY

		IF @report_date IS NULL SET @report_date = ( SELECT MAX(report_date) 
														FROM dbo.partner_billing_revenue_fact )

		DROP TABLE IF EXISTS #partner_billing_revenue_report_element;
		DROP TABLE IF EXISTS #partner_billing_revenue_fact;
		
		CREATE TABLE #partner_billing_revenue_report_element (
			partner_billing_revenue_report_element_id INT IDENTITY(1, 1),
			[key] VARCHAR(10),
			[value] VARCHAR(50),
			[element] VARCHAR(20)
		);

		/*
		|
		| Get the element data that we need
		| Not using UNION so we can manipulate the order
		|
		*/
		INSERT INTO #partner_billing_revenue_report_element (
		    [key],
		    [value],
		    element
		)
		SELECT 
			DISTINCT
				CAST( fact.partner_id AS VARCHAR(10) ),
				p.partner_name,
				'PARTNER'
		FROM dbo.partner_billing_revenue_fact fact
			INNER JOIN dbo.partner p
				ON p.partner_id = fact.partner_id
		WHERE fact.report_date = @report_date
		ORDER BY p.partner_name

		INSERT INTO #partner_billing_revenue_report_element (
		    [key],
		    [value],
		    element
		)
		SELECT 
			DISTINCT
				CAST( fact.site_id AS VARCHAR(10) ),
				fact.site_id,
				'SITE'
		FROM dbo.partner_billing_revenue_fact fact
		WHERE fact.report_date = @report_date

		INSERT INTO #partner_billing_revenue_report_element (
		    [key],
		    [value],
		    element
		)
		SELECT 
			DISTINCT
				CAST( fact.license_category_id AS VARCHAR(10) ),
				lc.license_category_name,
				'LICENSE_CATEGORY'
		FROM dbo.partner_billing_revenue_fact fact
			INNER JOIN dbo.license_category lc
				ON lc.license_category_id = fact.license_category_id
		WHERE fact.report_date = @report_date

		INSERT INTO #partner_billing_revenue_report_element (
		    [key],
		    [value],
		    element
		)		
		SELECT 
			DISTINCT
				CAST( fact.currency_id AS VARCHAR(10) ),
				cu.currency_code,
				'CURRENCY'
		FROM dbo.partner_billing_revenue_fact fact
			INNER JOIN dbo.currency cu
				ON cu.currency_id = fact.currency_id
		WHERE fact.report_date = @report_date

		INSERT INTO #partner_billing_revenue_report_element (
		    [key],
		    [value],
		    element
		)
		SELECT 
			DISTINCT
				'DEFAULT',
				@report_date,
				'REPORT_DATE'
		FROM dbo.partner_billing_revenue_fact fact
		WHERE fact.report_date = @report_date


		/*
		|
		|	Return results
		|
		*/
		SELECT
			e.[key],
			e.[value],
			e.[element]
		FROM #partner_billing_revenue_report_element e
		ORDER BY e.element
			, e.partner_billing_revenue_report_element_id

	END TRY

	BEGIN CATCH
	
		DECLARE @DBName NVARCHAR(128);
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
