-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_billing_summary]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_select_partner_billing_summary]


(
	@partner_billing_report_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2020-09-22	esmart		Initial creation.

	DESCRIPTION
	select aggregate summary from partner_billing
*/

AS



begin try
	
	set nocount on		
	set ansi_warnings on
	set ansi_nulls on		

	declare	@response_code int,
			@message varchar(100)
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @report table (license_category_name varchar(10), currency_id int, license_seats int, usage_seats int, total_seats int, total_extended_amount money, cap_amount money, total_cap_amount float)

	---- 1.1) insert report data
	insert into @report(license_category_name, currency_id, license_seats, usage_seats, total_seats, total_extended_amount, cap_amount, total_cap_amount)
	select lc.license_category_name,b.currency_id,sum(license_seats), sum(usage_seats), sum(total_seats), sum(total_extended_amount), sum(cap_amount), sum(total_cap_amount)
	from partner_billing b
	inner join license_category lc
		on lc.license_category_id = b.license_category_id
	where b.partner_billing_report_id = @partner_billing_report_id
	group by lc.license_category_name,b.currency_id
	   

	-- 1.2) return result
	select r.license_category_name, r.license_seats, r.usage_seats, r.total_seats, r.total_extended_amount, r.cap_amount, r.total_cap_amount,
		cu.currency_id, cu.currency_code, cu.currency_description, cu.symbol_html, cu.symbol_utf8, cu.symbol_text
	from @report r
	inner join currency cu
		on cu.currency_id = r.currency_id
	order by r.license_category_name desc
		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
