-- PROCEDURE: [dbo].[usp_partner_select_partner_cart_discount]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_cart_discount]

(
	@partner_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.1) select partner_status
	select d.cart_discount_id, 
			d.cart_discount_description, 
			i.product_line_id,
			p.product_line_description,
			d.cart_discount_type_id, 
			t.cart_discount_type_name,
			d.cart_discount_status_id, 
			i.cart_discount_method_id,
			m.cart_discount_method_name,
			i.discount
	from partner_cart_discount pd
	inner join cart_discount d
		on pd.cart_discount_id = d.cart_discount_id
	inner join cart_discount_type t
		on d.cart_discount_type_id = t.cart_discount_type_id
	inner join cart_discount_item i
		on d.cart_discount_id = i.cart_discount_id
	inner join cart_discount_method m
		on i.cart_discount_method_id = m.cart_discount_method_id
	inner join product_line p
		on i.product_line_id = p.product_line_id
	where pd.partner_id = @partner_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
