CREATE PROCEDURE [dbo].[usp_partner_select_partner_customer]

(
	@partner_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2013-10-08	esmart		Remove duplicates
	2013-10-24	esmart		Add additional details

	DESCRIPTION
	select partner account
*/

AS
	set nocount on				

	declare @partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	--print @partner_id

	-- 1.2) select partner accounts
	select c.customer_id, c.first_name, c.last_name, c.salesforce_contact_id,
		co.company_id, co.company_name, co.salesforce_account_id,
		e.customer_email, a.address_1, a.address_2, a.city, a.state, a.postal_code, a.country_id, cu.description, cu.iso, cu.iso3
	from partner_customer pc
	inner join customer c
		on pc.customer_id = c.customer_id
	inner join customer_email e
		on pc.customer_id = e.customer_id and e.email_status_id = 1
	left join customer_company cc
		on pc.customer_id = cc.customer_id
	left join company co
		on cc.company_id = co.company_id
	left join customer_address a
		on pc.customer_id = a.customer_id and a.address_type_id = 1 and a.address_status_id = 1
	left join lu_countries cu
		on a.country_id = cu.country_id
	where pc.partner_id = @partner_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_customer_verify]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_customer_verify]
  
(
	@partner_key varchar(36),
	@customer_id int
)

/*	
	DATE			AUTHOR		REMARKS
	2013-01-07		esmart		Initial creation.
	2015-09-28		esmart		Move none distributor verify to order_company
	2016-01-08		esmart		Add partner_configuration verification
	2017-06-13		acoffel		verify override
	2018-07-30		rvinoche	allow partners to search for email addresses on their own trials

	DESCRIPTION
	Verify customer is linked to partner
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_type_id tinyint,
			@company_id int,
			@verified tinyint,
			@exclude tinyint,
			@exclude_non_partner tinyint,
			@partner_verify_type varchar(20),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @excluded_partners table (partner_id int)

	-- 1.1) @partner_id
	select @partner_id = p.partner_id, 
			@partner_type_id = p.partner_type_id,
			@company_id = c.company_id
	from partner p
	left join company c
		on p.salesforce_id = c.salesforce_account_id
	where partner_key = @partner_key

	-- 1.2) @partner_verify_type
	select @partner_verify_type = cp.configuration_value
	from partner_configuration_partner cp
	inner join partner_configuration c
		on c.partner_configuration_id = cp.partner_configuration_id
	where cp.partner_id = @partner_id and c.configuration_name = 'keycode_verify'

	-- 1.3) @exclude_list
	if @partner_verify_type = 'Exclude'
		begin
			insert into @excluded_partners(partner_id)
			select cp.partner_id
			from partner_configuration_partner cp
			inner join partner_configuration c
				on c.partner_configuration_id = cp.partner_configuration_id
			where cp.partner_id <> @partner_id and c.configuration_name = 'keycode_verify' and cp.configuration_value = 'Exclude'
		end

		-- 1.3.1) Default
		if @partner_verify_type is null
			begin
			select @partner_verify_type = 'Restricted'
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) verify
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--2.1) allow customer emails for current trials in partner_trial
	if exists (select 1 from dbo.partner_trial pt 
				inner join dbo.trial t on t.trial_id = pt.trial_id 
				inner join dbo.license_category_license lcl on lcl.license_id = t.license_id 
				inner join dbo.license_category c on c.license_category_id = lcl.license_category_id 
				inner join dbo.license_capability lc on lc.license_id = t.license_id and c.base_capability_id = lc.capability_id 
				where t.customer_id = @customer_id and lc.capability_type_id = 2 and pt.partner_id = @partner_id)
	begin
		select @verified = 1

		goto return_verified
	end
	
	-- 2.2) exclude
	if @partner_verify_type = 'Exclude'
		begin
			-- if @partner_type_id = 1
				begin
					-- 2.1.1) distributor order license
					select @exclude = count(c.customer_id)
					from customer c
					where c.customer_id in (select co.customer_id
											from customer_order co
											inner join or
der_company oc
												on co.order_header_id = oc.order_header_id
											inner join company c
												on c.company_id = oc.company_id
											inner join partner p
												on c.salesforce_account_id = p.salesforce_id
											inner join @excluded_partners e
												on e.partner_id = p.partner_id
											where oc.order_company_type_id in (2,3,4) and co.customer_id = @customer_id)
						and c.customer_id not in (select co.customer_id
												from customer_order co
												inner join order_company oc
													on co.order_header_id = oc.order_header_id
												where oc.company_id = @company_id and oc.order_company_type_id in (2,3,4) and co.customer_id = @customer_id)
								and c.customer_id = @customer_id
						and c.customer_id = @customer_id
				end
					
				select @verified = case when @exclude > 0 or @exclude is null then 0 else 1 end
					
				
		end
	-- 2.2) Restricted
	else if @partner_verify_type = 'Restricted'
		begin
		-- print '2.2'
		if @partner_type_id = 1
			-- 2.2.1) distributor
			begin
				select @verified = count(c.customer_id)
				from customer c
				where c.customer_id in (select co.customer_id
										from customer_order co
										inner join order_company oc
											on co.order_header_id = oc.order_header_id
										where oc.company_id = @company_id and oc.order_company_type_id in (2,3,4) and co.customer_id = @customer_id)
						and c.customer_id = @customer_id

			end
		else if @partner_type_id = 2
			-- 2.2.2) reseller order
			begin
				select @verified = count(c.customer_id)
				from customer c
				where c.customer_id in (select co.customer_id
										from customer_order co
										inner join order_company oc
											on co.order_header_id = co.order_header_id
										where oc.company_id = @company_id and oc.order_company_type_id in (2,3))
						and c.customer_id = @customer_id
			end

			-- 2.2.3) trial
			if @verified = 0
				begin
					select @verified = count(c.customer_id)
					from customer c
					where c.customer_id in (select t.customer_id
											from partner_trial pt
											inner join trial t
												on pt.trial_id = t.trial_id
											where pt.partner_id = @partner_id)
							and c.customer_id = @customer_id
				end
			
		end
	-- 2.2) Restricted
	else if @partner_verify_type = 'Open'
		begin
		select @verified = 1
		end

	-- 2.3) look for partner_license relationship
	if @verified = 1 and @partner_verify_type <> 'Open'
		begin 
			select @exclude_non_partner = count(l.license_id)
			from license l
			inner join partner_license pl
				on l.license_id = pl.license_id
			inner join customer_email ce
				on l.customer_id = ce.customer_id and ce.email_status_id = 1
			where ce.customer_id = @customer_id
			and pl.partner_id = @partner_id
			and pl.partner_license_status_id = 2
		end

	-- 2.4) check for override
	if @verified = 1
		begin 
			select @verified = case when @exclude_non_partner = 0 then 0 else 1 end
		end

	-- 2.5) log failure
	if @verified = 0
		begin
		insert into partner_verify_failure(partner_id, verify_type, verify_value)
		values(@partner_id, 'customer_id', @customer_id)
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	return_verified:

	select verified = @verified

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_customers]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_customers]

(
	@partner_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	declare @customers table (customer_id int, first_name nvarchar(225), last_name nvarchar(225), company_name nvarchar(255), customer_email varchar(100))

	-- 1.2) select customer from orders
	insert into @customers(customer_id,first_name,last_name,company_name,customer_email)
	select distinct c.customer_id, c.first_name, c.last_name, cc.company_name, e.customer_email
	from partner_order po
	inner join order_header h
		on po.order_header_id = h.order_header_id
	inner join order_currency oc
		on h.order_header_id = oc.order_header_id
	inner join currency cu
		on oc.currency_id = cu.currency_id
	inner join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	inner join customer_order o
		on h.order_header_id = o.order_header_id and o.customer_type_id = 2
	inner join customer c
		on o.customer_id = c.customer_id
	left join customer_company cc
		on o.customer_id = cc.customer_id
	inner join customer_email e
		on o.customer_id = e.customer_id and e.email_status_id = 1
	where po.partner_id = @partner_id

	-- 1.3) from trials
	insert into @customers(customer_id,first_name,last_name,company_name,customer_email)
	select distinct c.customer_id, c.first_name, c.last_name, cc.company_name, e.customer_email
	from partner_trial pt
	inner join trial t
		on pt.trial_id = t.trial_id
	inner join customer c
		on t.customer_id = c.customer_id
	left join customer_company cc
		on t.customer_id = cc.customer_id
	inner join customer_email e
		on t.customer_id = e.customer_id and e.email_status_id = 1
	where pt.partner_id = @partner_id

	select customer_id,first_name,last_name,company_name,customer_email
	from @customers
	order by last_name, first_name

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_keycode_verify]
-- =============================================================================


CREATE   PROCEDURE [dbo].[usp_partner_select_partner_keycode_verify]

(
	@partner_key varchar(36),
	@keycode varchar(40),
	@verify_type varchar(20) = null
)

/*	
	DATE			AUTHOR		REMARKS
	2013-01-07		esmart		Initial creation.
	2013-10-04		esmart		Remove restriction on keycode lookup
	2015-06-05		esmart		Extend for distribution method and partner configuration
	2016-01-08		esmart		Add partner_configuration verification
	2016-12-02		acoffel		Set partner_id based on active start and end date
	2017-05-16		esmart		Change use of start/end date on partner_license
	2017-06-05		esmart		Make verified = 0 when NULL
	2017-06-13		acoffel		verify override
	2020-06-29		cnovac		Added code to look at start date when looking for active partner relationship
	2024-05-15		gblandford	https://jira.opentext.com/browse/ECOM-4417 - handle licenses that have been migrated to Zix partner. 
								These should redirect to a page that does not allow a renewal
								- @verified flag now int value, no longer true/false, added enumeration variables
								-
								-   0 = @NOT_VERIFIED_ALLOW_RENEW		- not verified, but allow renew
								-	1 = @VERIFIED_ALLOW_RENEW			- verified, allow renew
								-	2 = @NOT_VERIFIED_DENY_RENEW		- not verified, do not allow renew	
								-
								- added schema to object references
								

	DESCRIPTION
	Verify account is linked to partner
*/

AS
	set nocount on				

	declare	@partner_id int,
			@license_id int,
			@parent_license_id int,
			@license_partner_id int,
			@verified tinyint,
			@exclude_non_partner tinyint,
			@exclude tinyint,
			@partner_verify_type varchar(20),
			@partner_type_id tinyint,
			@company_id int,
			@exclude_list varchar(500),
			@response_code int,
			@message varchar(100)


	DECLARE @ZIX_PARTNER_ID INT

	-- 0.1) Zix partner_id
	SELECT 
		@ZIX_PARTNER_ID = cfg.[key]
	FROM [dbo].[fn_app_config_select_key_values] (	'ZIX_PARTNER', 'ZIX_MIGRATION' ) cfg;

	-- 0.2) Enums for @verified (for clarity)
	DECLARE @NOT_VERIFIED_ALLOW_RENEW TINYINT	= 0,
			@VERIFIED_ALLOW_RENEW TINYINT		= 1,
			@NOT_VERIFIED_DENY_RENEW TINYINT	= 2

	begin try

	if @verify_type is null
		begin
		select @verify_type = 'order'
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @excluded_partners table (partner_id int)

	-- 1.1) @partner_id
	select @partner_id = p.partner_id, 
			@partner_type_id = p.partner_type_id,
			@company_id = c.company_id
	from dbo.partner p
	left join dbo.company c
		on p.salesforce_id = c.salesforce_account_id
	where partner_key = @partner_key


	-- 1.2) @license_id 
	select @license_id = license_id from dbo.license where keycode = @keycode

		-- 1.2.1) verify on parent if child license
		select @parent_license_id = parent_license_id from dbo.license_parent where child_license_id = @license_id

		if @parent_license_id is not null
			begin
			select @license_id = @parent_license_id
			END
            
	-- 1.3) @license_partner_id
	select @license_partner_id = partner_id 
	from dbo.partner_license pl
	where license_id = @license_id and partner_license_status_id = 2 and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))

	-- 1.4) @partner_verify_type
	select @partner_verify_type = cp.configuration_value
	from dbo.partner_configuration_partner cp
	inner join dbo.
partner_configuration c
		on c.partner_configuration_id = cp.partner_configuration_id
	where cp.partner_id = @partner_id and c.configuration_name = 'keycode_verify'

	-- 1.5) @exclude_list
	if @partner_verify_type = 'Exclude'
		begin
			insert into @excluded_partners(partner_id)
			select cp.partner_id
			from dbo.partner_configuration_partner cp
			inner join dbo.partner_configuration c
				on c.partner_configuration_id = cp.partner_configuration_id
			where cp.partner_id <> @partner_id and c.configuration_name = 'keycode_verify' and cp.configuration_value = 'Exclude'
		end

		-- 1.5.1) Default
		if @partner_verify_type is null
			begin
			select @partner_verify_type = 'Restricted'
			end

	

	 -- select verify_type = @partner_verify_type, partner_id = @partner_id, license_partner_id = @license_partner_id
	--select * from @excluded_partners e inner join partner p on p.partner_id = e.partner_id

	if @verify_type = 'order'
		begin
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) partner_license
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		if @license_partner_id is not null
			begin
				--print '2.1) partner match'
				-- 2.1) partner match
				IF @license_partner_id = @partner_id BEGIN

						-- 2.1.1) DENY renewal if this is a ZIX partner license
						IF @partner_id = @ZIX_PARTNER_ID BEGIN
								SELECT @verified = @NOT_VERIFIED_DENY_RENEW
							END
						ELSE BEGIN
							SELECT @verified = @VERIFIED_ALLOW_RENEW
						END
					END

				ELSE if @license_partner_id <> @partner_id and @partner_verify_type = 'Exclude'
						begin
						if exists (select partner_id from @excluded_partners where partner_id = @license_partner_id)
							begin
							select @verified = @NOT_VERIFIED_ALLOW_RENEW
							--print 'excluded partner match'
							end
						end
					else 
						begin
						select @verified = @VERIFIED_ALLOW_RENEW
						end
				end

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) non partner_license
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if @license_partner_id is null
			begin
			--print '3.0 non partner_license'

			-- 3.1) @exclude
			if @partner_verify_type = 'Exclude'
				begin
					-- 3.1.1) order license
					select @exclude = count(*)
					from dbo.license l
					where l.license_id in (select license_id
										from dbo.order_item_license il
										inner join dbo.order_item i
											on il.order_item_id = i.order_item_id
										inner join dbo.partner_order po
											on i.order_header_id = po.order_header_id
										inner join @excluded_partners e
											on e.partner_id = po.partner_id
										)
						and l.license_id not in (select license_id
										from dbo.order_item_license il
										inner join dbo.order_item i
											on il.order_item_id = i.order_item_id
										inner join dbo.partner_order po
											on i.order_header_id = po.order_header_id
										where po.partner_id = @partner_id)
						and l.keycode = @keycode

				-- select order_license_exclude = @exclude

				-- 3.2.2) trial license
					if @exclude = 0
						begin
						select @exclude = count(*)
						from dbo.license l
						where l.license_id in (select t.license_id
											from dbo.partner_trial pt
											inner join dbo.trial t
												on pt.trial_id = t.trial_i
d
											inner join @excluded_partners e
												on e.partner_id = pt.partner_id)
							and l.license_id not in (select license_id
											from dbo.partner_trial pt
											inner join dbo.trial t
												on pt.trial_id = t.trial_id
											where pt.partner_id = @partner_id)
							and l.keycode = @keycode

							-- select trial_license_exclude = @exclude
						end
	
				-- 2.1.4) @verified
					select @verified = case when @exclude > 0 then @NOT_VERIFIED_ALLOW_RENEW else @VERIFIED_ALLOW_RENEW end
				end
			else if @partner_verify_type = 'Restricted'
			-- 3.2) Restricted
				begin
				--print '-- 3.2) Restricted'
				-- 3.2.1) order license
				select @verified = count(*)
				from dbo.license 
				where license_id in (select license_id
									from dbo.order_item_license il
									inner join dbo.order_item i
										on il.order_item_id = i.order_item_id
									inner join dbo.partner_order po
										on i.order_header_id = po.order_header_id
									where po.partner_id = @partner_id)
					and keycode = @keycode

				-- 3.2.1) order license
				select @verified = count(*)
				from dbo.license 
				where license_id in (select license_id
									from dbo.order_item_license il
									inner join dbo.order_item i
										on il.order_item_id = i.order_item_id
									inner join dbo.order_company oc
										on i.order_header_id = oc.order_header_id
									where oc.company_id = @company_id)
					and keycode = @keycode

				-- 3.2.2) trial license
				if @verified = @NOT_VERIFIED_ALLOW_RENEW
					begin
					select @verified = count(*)
					from dbo.license 
					where license_id in (select t.license_id
										from dbo.partner_trial pt
										inner join dbo.trial t
											on pt.trial_id = t.trial_id
										where pt.partner_id = @partner_id)
						and keycode = @keycode
					end

				-- 3.2.3) distribution_method
				if @verified = @NOT_VERIFIED_ALLOW_RENEW
					begin
					select @verified = count(*)
					from dbo.license l
					inner join dbo.partner_license_distribution_method p
						on l.license_distribution_method_id = p.license_distribution_method_id
					where l.keycode = @keycode and p.partner_id = @partner_id
					end
				END
                
				-- 3.2.1.1) ensure verified is 0 or 1
				IF @verified > 1 BEGIN
						SET @verified = @VERIFIED_ALLOW_RENEW
					END

			-- 3.3) Restricted
			else if @partner_verify_type = 'Open'
				begin
				select @verified = @VERIFIED_ALLOW_RENEW
				end
			end

		end
	else 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) license verification
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		begin
		-- 4.1) partner match
		if @license_partner_id = @partner_id 
			begin
			--print '-- 4.1) partner match'
			select @verified = @VERIFIED_ALLOW_RENEW
			end
		-- 4.2) no match
		else
			begin
			--print '-- 4.2) no match'
			select @verified = @NOT_VERIFIED_ALLOW_RENEW
			end
		end

		-- 4.2) look for partner_license relationship
		if @verified = @VERIFIED_ALLOW_RENEW and @partner_verify_type <> 'Open' and (select count(*) from dbo.partner_trial p inner join dbo.trial t on p.trial_id = t.trial_id where t.license_id = @license_id and p.partner_id = @partner_id) = 0
			begin 
				select @exclude_non_partner = count(l.license_id)
				from dbo.license l
				inner join dbo.partner_license pl
					on l.license_id = pl.license_id
				where pl.partner_id = @partner_id
				and pl.license_id = @license_id
				and pl.partner_license_status_id = 2
				and (pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate()))
			en
d

		-- 4.3) check for override
		if @verified = @VERIFIED_ALLOW_RENEW
			begin 
				select @verified = case when @exclude_non_partner = 0 then @NOT_VERIFIED_ALLOW_RENEW else @VERIFIED_ALLOW_RENEW end
			end
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @verified is null
		begin
			select @verified = @NOT_VERIFIED_ALLOW_RENEW
		end
		
	-- 5.1) log failure
	if @verified = @NOT_VERIFIED_ALLOW_RENEW and @partner_verify_type <> 'Open'
		begin
		insert into dbo.partner_verify_failure(partner_id, verify_type, verify_value)
		values(@partner_id, 'keycode', @keycode)
		end

	-- 5.2) result
	select verified = @verified

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_license]

(
	@license_id int = null,
	@user_name varchar(100) = null,
	@partner_license_status_id tinyint = null,
	@max_pending_record bit = null,
	@effective_date datetime = null,
	@partner_id int = null
)


/*	
	DATE		AUTHOR		REMARKS
	2015-07-30	esmart		Initial creation.
	2016-12-02	acoffel		partner_license start_date and end_date
	2017-04-14	acoffel		Pending logic
	2017-05-23	esmart		Add order_header_id and vendor_order_code
	2018-02-06  esmart		Add effective date
	2018-09-28	rvinoche	Adding partner_id as an optional parameter
	2018-10-24	rvinoche	Excluding partner_licenses where partner_id = approved_partner_id when other pending partner_ids exist
	2022-07-13  rambasana	Update variable length for @user_name to match table column length of dbo.sfdc_user 
	2022-09-13	gblandford	ALM-1652 - change sfdc_user to LEFT join to ensure rows returned if no matching salesforce account 
	2025-03-05	vsingh8  	US-4455631 - returning partner_key for the selected partner.

	DESCRIPTION
	Select partner_license

	DEPENDENCY
	This procedure is used on the php side, in the li3_wr\models\partner\License model class.
*/

AS
	set nocount on				

	declare	@account_owner_id varchar(18),
			@max_pending_record_id int,
			@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) 
	select @account_owner_id = User2Id
	from sfdc_user
	where UserName = @user_name or UserName = @user_name+'@webroot.com'

	--select account_owner_id = @account_owner_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @partner_license table (partner_license_id int NOT NULL, license_id int NOT NULL, keycode varchar(40) NULL, partner_id int NULL, partner_name nvarchar(100) null, partner_key uniqueidentifier null, salesforce_account_id varchar(18) null, partner_license_status_id tinyint NULL,  partner_license_status_name varchar(50) NULL, 
											start_date datetime NULL, end_date datetime NULL, partner_license_source_id tinyint NULL, partner_license_source_name varchar(50) NULL, last_modified_user_id varchar(20), last_modified_date datetime NULL, order_header_id int, vendor_order_code varchar(100),
											comment nvarchar(max) NULL, account_owner_name nvarchar(121) Null, pending_transactions int null, approved_partner_license_id int null, approved_partner_id int null, approved_partner_name nvarchar(100) null, approved_start_date datetime null, approved_end_date datetime null, exclude bit default 0)
	
	insert into @partner_license (partner_license_id, license_id, keycode, partner_id, partner_name, partner_key, salesforce_account_id, partner_license_status_id, partner_license_status_name, start_date, end_date, partner_license_source_id, partner_license_source_name, last_modified_user_id, last_modified_date, order_header_id, vendor_order_code,
											comment, account_owner_name, pending_transactions, approved_partner_license_id, approved_partn
er_id, approved_partner_name, approved_start_date, approved_end_date)
	select pl.partner_license_id, l.license_id, l.keycode, p.partner_id, p.partner_name, 
		p.partner_key,
		salesforce_account_id = p.salesforce_id,
		s.partner_license_status_id, 
		s.partner_license_status_name, 
		pl.start_date,
		pl.end_date,
		sc.partner_license_source_id, 
		sc.partner_license_source_name,
		pl.last_modified_user_id,
		pl.last_modified_date,
		pl.order_header_id,
		v.vendor_order_code,
		c.comment,
		account_owner_name = u.Name,
		pending_transactions = (select count(*) from partner_license_transaction where partner_license_id = pl.partner_license_id and partner_license_status_id = 1),
		approved_partner_license_id = pla.partner_license_id,
		approved_partner_id = pa.partner_id,
		approved_partner_name = pa.partner_name,
		approved_start_date = pla.start_date,
		approved_end_date = pla.end_date
	from dbo.partner_license pl
	inner join dbo.license l
		on pl.license_id = l.license_id
	inner join dbo.partner p
		on pl.partner_id = p.partner_id
	left join dbo.sfdc_user u
		on p.account_owner_id = u.User2Id
	inner join dbo.partner_license_status s
		on pl.partner_license_status_id = s.partner_license_status_id
	inner join dbo.partner_license_source sc
		on pl.partner_license_source_id = sc.partner_license_source_id
	left join dbo.partner_license_comment c
		on pl.partner_license_id = c.partner_license_id
	left join dbo.partner_license pla
		on pla.license_id = pl.license_id and pla.partner_license_id <> pl.partner_license_id and pla.partner_license_status_id = 2 and (pla.start_date < getdate() and (pla.end_date is null or pla.end_date >= getdate())) 
	left join dbo.partner pa
		on pa.partner_id = pla.partner_id
	left join dbo.order_header h
		on h.order_header_id = pl.order_header_id
	left join dbo.vendor_order v
		on v.vendor_order_id = h.vendor_order_id
	where pl.license_id = case when @license_id is null then pl.license_id else @license_id end and
		p.account_owner_id = case when  @account_owner_id is null then p.account_owner_id else @account_owner_id end and
		pl.partner_license_status_id = case when @partner_license_status_id is null then pl.partner_license_status_id else @partner_license_status_id end and 
		p.partner_id = case when @partner_id is null then pl.partner_id else @partner_id end
	-- order by pl.partner_license_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) check for @max_pending_record
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @max_pending_record = 1 
		begin 
			update p
			set exclude = 1 --this ensures that if there is a pending partner_license record from a different partner, we display that instead of the current partner disabling the license
			from @partner_license p
			where partner_id = approved_partner_id
				and exists (select 1 from @partner_license p2 where p2.partner_id <> p2.approved_partner_id and p2.license_id = p.license_id)

				select partner_license_id, license_id, keycode, partner_id, partner_name, partner_key, pl.salesforce_account_id, partner_license_status_id, partner_license_status_name, start_date, end_date, partner_license_source_id, partner_license_source_name, last_modified_user_id, last_modified_date, order_header_id, vendor_order_code, comment, account_owner_name, pending_transactions, approved_partner_license_id, approved_partner_id, approved_partner_name, approved_start_date, approved_end_date
			from @partner_license pl
			where partner_license_id in (select max_pending_record_id = max(partner_license_id)
										from @partner_license 
										where partner_license_status_name = 'pending'
									
		and exclude = 0
										group by license_id)
			order by pl.partner_license_id
		end
	else if @effective_date is not null
		begin 
			select partner_license_id, license_id, keycode, partner_id, partner_name, partner_key, salesforce_account_id, partner_license_status_id, partner_license_status_name, start_date, end_date, partner_license_source_id, partner_license_source_name, last_modified_user_id, last_modified_date, order_header_id, vendor_order_code, comment, account_owner_name, pending_transactions, approved_partner_license_id, approved_partner_id, approved_partner_name, approved_start_date, approved_end_date
			from @partner_license 
			where start_date <= @effective_date and (end_date > @effective_date or end_date is null)
			order by partner_license_id
		end
	else
		begin 
			select partner_license_id, license_id, keycode, partner_id, partner_name, partner_key, salesforce_account_id, partner_license_status_id, partner_license_status_name, start_date, end_date, partner_license_source_id, partner_license_source_name, last_modified_user_id, last_modified_date, order_header_id, vendor_order_code, comment, account_owner_name, pending_transactions, approved_partner_license_id, approved_partner_id, approved_partner_name, approved_start_date, approved_end_date
			from @partner_license 
			order by partner_license_id
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license_attribute]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_license_attribute]

(
		@partner_key varchar(36) = null,
		@partner_license_attribute_id int = null,
		@partner_id int = null,
		@license_category_id int = null,
		@license_attribute_id int = null,
		@license_attribute_license_value int = null,
		@partner_pricing_model_id tinyint = null,
		@site_id varchar(20) = null	
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-02-23		esmart			Initial creation
	
	DESCRIPTION
	select partner_license_attribute
*/

as

	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @partner_key is not null
		begin
		select @partner_id = partner_id from partner where partner_key = @partner_key
		end

	select pl.partner_license_attribute_id, 
			p.partner_id, p.partner_name, 
			pl.site_id,
			c.license_category_id, c.license_category_name, 
			a.license_attribute_id, a.license_attribute_description, a.license_attribute_tag, 
			v.license_attribute_license_value, v.license_attribute_license_value_description,
			m.partner_pricing_model_id, m.partner_pricing_model_name
	from partner_license_attribute pl
	inner join partner p
		on p.partner_id = pl.partner_id
	inner join license_category c
		on c.license_category_id = pl.license_category_id
	inner join license_attribute a
		on a.license_attribute_id = pl.license_attribute_id
	inner join license_attribute_license_value v
		on v.license_attribute_license_value = pl.license_attribute_license_value
	inner join partner_pricing_model m
		on m.partner_pricing_model_id = pl.partner_pricing_model_id
	where pl.partner_id = @partner_id and
			pl.site_id = case when @site_id is null then pl.site_id else @site_id end and 
			pl.license_attribute_id = case when @license_attribute_id is null then pl.license_attribute_id else @license_attribute_id end and
			pl.license_category_id = case when @license_category_id is null then pl.license_category_id else @license_category_id end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license_category_product_line]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_license_category_product_line]

(
	@partner_key varchar(36),
	@license_category_id int = null
)

/*	
	DATE			AUTHOR		REMARKS
	2013-01-07		esmart		Initial creation.
	2015-05-31		esmart		Add site_id
	2019-05-20		esmart		Suspend purchase of mobile and user

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.1) select partner_status
	select l.partner_license_category_product_line_id, l.partner_id, l.license_category_id, l.site_id, c.license_category_name, c.license_category_description, l.product_line_id, p.product_line_description, l.insert_by
	from partner_license_category_product_line l
	inner join product_line p
		on l.product_line_id = p.product_line_id
	inner join license_category c
		on l.license_category_id = c.license_category_id
	where l.partner_id = @partner_id and 
		l.license_category_id = case when @license_category_id is null then l.license_category_id else @license_category_id end and
		l.license_category_id not in (250,55)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license_entity_change]
-- =============================================================================

/*
	DATE		AUTHOR		REMARKS
	2016-04-25	blu			Initial creation with esmarts script.
	2016-08-02	acoffel		Showing Partner changes

	DESCRIPTION
	Selects partner license entity changes.

*/
CREATE PROCEDURE [dbo].[usp_partner_select_partner_license_entity_change]
(
	@partner_id int,
	@start_date date,
	@end_date date
)
as
set nocount on
begin try
	
	declare	@response_code int,
		@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @licenses table (
		license_id int,
		keycode varchar(40),
		partner_id int
	)

	insert into @licenses (
		license_id,
		keycode,
		partner_id
	)
	select distinct pl.license_id,
		l.keycode,
		pl2.partner_id
	from partner_license pl with (nolock)
	inner join license l with (nolock)
		on pl.license_id = l.license_id
	inner join partner_license pl2
		on pl.license_id = pl2.license_id
	where pl.partner_id = @partner_id
		and pl.partner_id <> pl2.partner_id
		and pl.partner_license_status_id <> 2
		and pl2.partner_license_status_id = 2
		and l.license_status_id = 1
		and @start_date <= pl.last_modified_date
		and pl.last_modified_date < @end_date
	
	select l.keycode,
		u.company_name,
		u.customer_email,
		u.license_seats,
		u.activation_date,
		u.expiration_date,
		u.licenses,
		u.devices,
		u.devices_30_days,
		u.devices_30_days_active, 
		u.devices_delta,
		u.devices_delta_abs,
		u.devices_delta_active,
		u.devices_delta_abs_active,
		u.report_date,
		p.partner_name
	from @licenses l
	left join partner_license_usage u
		on l.license_id = u.license_id
		and u.partner_license_usage_id = (
			select max(partner_license_usage_id)
			from partner_license_usage
			where license_id = l.license_id
		)
	inner join partner p
		on l.partner_id = p.partner_id

end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;



GO
