-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license_transaction]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_license_transaction]

(
		@partner_license_id int
)
	
/*	
	DATE			AUTHOR			REMARKS
	2017-01-20		esmart			Initial creation
	2017-05-16		esmart			Add partner_license_transaction_procedure
	2018-07-13		rvinoche		Change license_transaction json to license_service_json for license_service transactions
	DESCRIPTION
	select partner_license_transaction
*/

as

	set nocount on	

	declare	@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @partner_license_transactions table (partner_license_transaction_id int, partner_license_id int, partner_license_status_id tinyint, partner_license_status_name varchar(50), transaction_procedure_name varchar(100), transaction_procedure_description varchar(max), license_transaction varchar(max), insert_date datetime, last_modified_date datetime, partner_license_transaction_procedure_id tinyint, license_service_id int, license_service_type_description nvarchar(max))

	insert into @partner_license_transactions (partner_license_transaction_id, partner_license_id, partner_license_status_id, partner_license_status_name, transaction_procedure_name, transaction_procedure_description, license_transaction, insert_date, last_modified_date, partner_license_transaction_procedure_id, license_service_id)
	select t.partner_license_transaction_id, t.partner_license_id, t.partner_license_status_id, s.partner_license_status_name, p.transaction_procedure_name, p.transaction_procedure_description, t.license_transaction, t.insert_date, t.last_modified_date, p.partner_license_transaction_procedure_id, 
		cast(isnull(json_value(t.license_transaction,'$.license_service_id'),json_value(t.license_transaction,'$[0].license_service_id')) as int)
	from dbo.partner_license_transaction t
	inner join dbo.partner_license_status s
		on s.partner_license_status_id = t.partner_license_status_id
	inner join dbo.partner_license_transaction_procedure p
		on p.partner_license_transaction_procedure_id = t.partner_license_transaction_procedure_id
	where t.partner_license_id = @partner_license_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update json for license_service transactions 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	update p
	set p.license_transaction = j.license_service_json, p.license_service_type_description = t.license_service_type_description
	from @partner_license_transactions p
	inner join dbo.license_service s
		on p.license_service_id = s.license_service_id
	INNER JOIN dbo.license_service_type t
		ON t.license_service_type_id = s.license_service_type_id
	inner join dbo.license_service_json j
		on j.license_service_id = s.license_service_id
	where p.partner_license_transaction_procedure_id = 6
		and p.license_service_id is NOT NULL

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return re
sults
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select partner_license_transaction_id, partner_license_id, partner_license_status_id, partner_license_status_name, transaction_procedure_name, transaction_procedure_description, license_transaction, license_service_type_description, insert_date, last_modified_date
	from @partner_license_transactions 


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_license_usage]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_select_partner_license_usage] (
	@partner_id int,
	@report_date date = null,
	@return_result tinyint = 1,
	@reprocess tinyint = 0
)

/*	
	DATE			AUTHOR			REMARKS
	2015-10-22		esmart			Initial creation
	2015-12-14		mrobbins		Added Expiration Date
	2016-04-15		mrobbins		added state and country
	2016-07-03		cnovac			updated license_service references for CB changes
	2016-11-03		mrobbins		added order_date
	2016-11-07		acoffel			no child keys
	2016-11-18		acoffel			original order date on existing partner and date license went full
	2016-12-29		esmart			correct lookup of company name
	2017-05-16		esmart			Change use of start/end date on partner_license
	2017-06-01		esmart			Add module support
	2018-07-04		rvinoche		use activity function for usage and abstract core logic to be used separately 
	2024-08-19		gblandford		https://jira.opentext.com/browse/ECOM-5111 
									- Handle Pillr products
										- added storage_gb column for clarity on storage_products
									- Add schemas, changed casing/formattingchanged from @table variables to #temporary table
	
	DESCRIPTION
	report partner license usage
*/

AS
	
	SET NOCOUNT ON		
	SET ANSI_WARNINGS OFF	

	DECLARE	@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) delete existing data
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF @reprocess = 1 AND EXISTS (SELECT partner_license_usage_id FROM dbo.partner_license_usage WHERE partner_id = @partner_id AND report_date = @report_date)
		BEGIN
			DELETE FROM dbo.partner_license_usage WHERE partner_id = @partner_id AND report_date = @report_date;
		END;
		
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) select data
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

			-- 2.1) @partner_license_usage
			--DECLARE @partner_license_usage TABLE (license_id INT, keycode VARCHAR(24), license_category_id INT, license_category_name VARCHAR(4), company_name NVARCHAR(255), 
			--	customer_state VARCHAR(2),full_capability_date DATETIME, customer_country NVARCHAR(75), customer_email VARCHAR(100), oil_insert_date DATETIME, license_seats INT, 
			--	activation_date DATETIME, expiration_date DATETIME, licenses INT, devices INT, devices_30_days INT, devices_30_days_active INT, devices_delta INT, devices_delta_abs INT, devices_delta_active INT, 
			--	devices_delta_abs_active INT, seats_less_devices INT, license_attribute_license_value INT, license_attribute_description VARCHAR(100), license_attribute_license_value_description VARCHAR(50), report_date DATETIME
			--)

			DROP TABLE IF EXISTS #partner_license_usage;

			CREATE TABLE #partner_license_usage (
				license_id INT, 
				keycode VARCHAR(24), 
				license_category_id INT, 
				license_category_name VARCHAR(4), 
				company_name NVARCHAR(255), 
				customer_state VARCHAR(2),
				full_capability_date DATETIME, 
				customer_country NVARCHAR(75), 
				customer_email VARCHAR(100), 
				oil_insert_date DATETIME, 
				license_seats INT, 
				activation_date DATETIME, 
				expiration_date DATETIME, 
	
			licenses INT, 
				devices INT, 
				devices_30_days INT, 
				devices_30_days_active INT, 
				devices_delta INT, 
				devices_delta_abs INT, 
				devices_delta_active INT, 
				devices_delta_abs_active INT, 
				seats_less_devices INT, 
				license_attribute_license_value INT, 
				license_attribute_description VARCHAR(100), 
				license_attribute_license_value_description VARCHAR(50), 
				report_date DATETIME,
				storage_gb INT
			);
	
			-- INSERT INTO @partner_license_usage (
			INSERT INTO #partner_license_usage (
				license_id, 
				keycode, 
				license_category_id, 
				license_category_name,
				company_name, 
				customer_state, 
				full_capability_date, 
				customer_country, 
				customer_email, 
				oil_insert_date,
				license_seats, 
				activation_date, 
				expiration_date, 
				licenses, 
				devices, 
				devices_30_days, 
				devices_30_days_active, 
				devices_delta, 
				devices_delta_abs, 
				devices_delta_active,
				devices_delta_abs_active, 
				seats_less_devices, 
				license_attribute_license_value, 
				license_attribute_description, 
				license_attribute_license_value_description, 
				report_date,
				storage_gb
			)
			EXECUTE dbo.usp_license_select_partner_license_activity 
				@partner_id = @partner_id, 
				@report_date = @report_date;

			-- 2.2) insert into partner_license_usage
			IF @reprocess = 1
			BEGIN
				INSERT INTO dbo.partner_license_usage (
					partner_id, 
					report_date, 
					license_id, 
					license_category_id, 
					company_name, 
					customer_state, 
					customer_country, 
					customer_email, 
					license_seats, 
					activation_date, 
					expiration_date, 
					licenses, 
					devices, 
					devices_30_days, 
					devices_30_days_active, 
					devices_delta, 
					devices_delta_abs, 
					devices_delta_active, 
					devices_delta_abs_active, 
					storage_gb
				)
				SELECT 
					@partner_id,
					@report_date, 
					license_id, 
					license_category_id, 
					company_name, 
					customer_state, 
					customer_country, 
					customer_email, 
					license_seats, 
					activation_date, 
					expiration_date, 
					licenses, 
					devices, 
					devices_30_days, 
					devices_30_days_active, 
					devices_delta, 
					devices_delta_abs, 
					devices_delta_active, 
					devices_delta_abs_active,
					storage_gb
				FROM #partner_license_usage;
			END;
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) return results
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		IF @return_result = 1
		BEGIN
			SELECT 
				license_id, 
				keycode, 
				license_category_id, 
				license_category_name, 
				company_name, 
				customer_state, 
				full_capability_date, 
				customer_country,
				customer_email,
				oil_insert_date, 
				license_seats, 
				activation_date, 
				expiration_date, 
				licenses, 
				devices, 
				devices_30_days, 
				devices_30_days_active, 
				devices_delta, 
				devices_delta_abs,
				devices_delta_active, 
				devices_delta_abs_active, 
				seats_less_devices, 
				report_date,
				storage_gb
			FROM #partner_license_usage;
		END;

	END TRY

	BEGIN CATCH

		SET @response_code = -200;
		SET @message = CASE WHEN @message IS NULL THEN 'update account update failed'
							ELSE @message END;

		DECLARE @DBName NVARCHAR(128);
		SET @DBName = DB_NAME();
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName;
		
	END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_name]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_name]

(
	@license_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2015-03-11	acoffel		Initial creation
	2018-08-13	acoffel		order_comany
	2019-11-20	jnavarra	Give priority to reseller

	DESCRIPTION
	Select Partner Name for channel routing

*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)
	

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select top 1 isnull(c.company_name,'Is Unavailble') as partner_name
		from (select license_id, max(order_item_id) as order_item_id
			  from order_item_license 
			  group by license_id) oil
		inner join order_item_license oil2
			on oil.license_id = oil2.license_id and oil.order_item_id = oil2.order_item_id
		inner join order_item i
			on oil.order_item_id = i.order_item_id
		inner join order_company oc
		 	on i.order_header_id = oc.order_header_id and oc.order_company_type_id in (2, 3)
		inner join company c
			on oc.company_id = c.company_id
		where oil.license_id = @license_id
		order by oc.order_company_type_id desc


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_order_status]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_order_status]

(
	@partner_key varchar(36),
	@vendor_order_code varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2017-01-31	acoffel		Initial creation.
	2017-05-05	aocffel		Added pending.
	2017-05-16	esmart		Change use of start/end date on partner_license

	DESCRIPTION
	Select partner order licenses
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_type_id tinyint,
			@company_id int,
			@response_code int,
			@message varchar(100)

	begin try
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = p.partner_id, 
			@partner_type_id = p.partner_type_id,
			@company_id = c.company_id
	from partner p
	left join company c
		on p.salesforce_id = c.salesforce_account_id
	where partner_key = @partner_key

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


			select distinct p.partner_name, s.partner_status_name, ls.partner_license_status_name, l.license_id, l.keycode, cl.license_category_id, c.license_category_name, l.customer_id, 
							ca.capability_activation_days, pl.start_date, ca.capability_activation_date, ca.capability_expiration_date
			from license l with (nolock)
			inner join order_item_license il with (nolock)
				on l.license_id = il.license_id
			inner join order_item i with (nolock)
				on il.order_item_id = i.order_item_id
			inner join partner_order po with (nolock)
				on i.order_header_id = po.order_header_id
			inner join order_header h with (nolock)
				on po.order_header_id = h.order_header_id
			inner join vendor_order v with (nolock)
				on h.vendor_order_id = v.vendor_order_id
			inner join partner p with (nolock)
				on po.partner_id = p.partner_id 
			inner join partner_license pl with (nolock)
				on p.partner_id = pl.partner_id and pl.license_id = l.license_id 
			inner join partner_license_status ls with (nolock)
				on pl.partner_license_status_id = ls.partner_license_status_id
			inner join partner_type t with (nolock)
				on p.partner_type_id = t.partner_type_id
			inner join partner_status s with (nolock)
				on p.partner_status_id = s.partner_status_id
			inner join license_category_license cl with (nolock)
				on l.license_id = cl.license_id
			inner join license_category c with (nolock)
				on cl.license_category_id = c.license_category_id
			inner join license_capability ca with (nolock)
				on l.license_id = ca.license_id and ca.capability_id = isnull(c.base_capability_id,1)
			where po.partner_id = @partner_id and 
				v.vendor_order_code = @vendor_order_code and 
				((pl.start_date <= getdate() and (pl.end_date is null or pl.end_date > getdate())) or (ls.partner_license_status_name = 'declined') or (ls.partner_license_status_name = 'pending'))


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_order_user]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_partner_select_partner_order_user]

(
  @order_header_id int
)

/*
  DATE			AUTHOR		REMARKS
  2017-07-17	acoffel		Initial Creation		 

  DESCRIPTION
  select partner account
*/

AS
  set nocount on

  declare @response_code int,
      @message varchar(100)

  begin try

  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  -- 1.) select
  -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  -- 1.1) select partner accounts
  select pa.partner_account_id, partner_account_key = convert(varchar(36),pa.partner_account_key), pa.insert_by, pa.partner_id, a.account_id, a.account_user_name, a.account_status_id, s.account_status, pa.shared_account, a.password_reset_date, pa.partner_account_status_id, ps.partner_account_status_name
  from partner_order po
  inner join partner_account pa
	on po.partner_account_id = pa.partner_account_id
  inner join account a
    on pa.account_id = a.account_id
  inner join account_status s
    on a.account_status_id = s.account_status_id
  inner join partner_account_status ps
    on pa.partner_account_status_id = ps.partner_account_status_id
  where po.order_header_id = @order_header_id

  end try

  begin catch

    set @response_code = -200
    set @message = case when @message is null then 'select failed'
              else @message end

    declare @DBName nvarchar(128)
    set @DBName = db_name()
    exec usp_LogError @ErrorDB = @DBName

  end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_order_verify]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_order_verify]

(
	@partner_key varchar(36),
	@vendor_order_code varchar(100)
)

/*	
	DATE			AUTHOR		REMARKS
	2013-01-07		esmart		Initial creation.
	2015-09-28		esmart		Move none distributor verify to order_company
	2016-01-08		esmart		Add partner_configuration verification

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_type_id tinyint,
			@company_id int,
			@verified tinyint,
			@exclude tinyint,
			@partner_verify_type varchar(20),
			@exclude_list varchar(500),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @excluded_partners table (partner_id int)

	-- 1.1) @partner_id
	select @partner_id = p.partner_id, 
			@partner_type_id = p.partner_type_id,
			@company_id = c.company_id
	from partner p
	left join company c
		on p.salesforce_id = c.salesforce_account_id
	where partner_key = @partner_key
		
	-- 1.2) @partner_verify_type
	select @partner_verify_type = cp.configuration_value
	from partner_configuration_partner cp
	inner join partner_configuration c
		on c.partner_configuration_id = cp.partner_configuration_id
	where cp.partner_id = @partner_id and c.configuration_name = 'keycode_verify'

	-- 1.3) @exclude_list
	if @partner_verify_type = 'Exclude'
		begin
			insert into @excluded_partners(partner_id)
			select cp.partner_id
			from partner_configuration_partner cp
			inner join partner_configuration c
				on c.partner_configuration_id = cp.partner_configuration_id
			where cp.partner_id <> @partner_id and c.configuration_name = 'keycode_verify' and cp.configuration_value = 'Exclude'
		end

		-- 1.3.1) Default
		if @partner_verify_type is null
			begin
			select @partner_verify_type = 'Restricted'
			end


	--select company_id = @company_id, partner_type_id = @partner_type_id, verify_type = @partner_verify_type
	--select * from @excluded_partners

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) verify
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) Exclude
	if @partner_verify_type = 'Exclude'
		begin
			--print '2.1 Exclude'
			--if @partner_type_id = 1
				begin
					-- 2.1.1) distributor order license
					select @exclude = count(vo.vendor_order_id)
					from vendor_order vo
					where vo.vendor_order_code in (select v.vendor_order_code
											from order_company oc
											inner join order_header h
												on oc.order_header_id = h.order_header_id
											inner join vendor_order v
												on h.vendor_order_id = v.vendor_order_id
											inner join company c
												on c.company_id = oc.company_id
											inner join partner p
												on c.salesforce_account_id = p.salesforce_id
											inner join @excluded_partners e
												on e.partner_id = p.partner_id)
						and vo.vendor_order_code not in (select v.vendor_order_code
												from order_company oc
												inner join order_header h
													on oc.order_header_id = h.order_header_id
												inner join vendor_order v
													on h.vendor_or
der_id = v.vendor_order_id
												where oc.company_id = @company_id and oc.order_company_type_id in (2,3,4) and v.vendor_order_code = @vendor_order_code)
						and vo.vendor_order_code = @vendor_order_code
				end
			--else
			--	begin
			--		-- 2.1.2) reseller order license
			--		select @exclude = count(vo.vendor_order_id)
			--		from vendor_order vo
			--		where vo.vendor_order_code in (select v.vendor_order_code
			--								from order_company oc
			--								inner join order_header h
			--									on oc.order_header_id = h.order_header_id
			--								inner join vendor_order v
			--									on h.vendor_order_id = v.vendor_order_id
			--								inner join company c
			--									on c.company_id = oc.company_id
			--								inner join partner p
			--									on c.salesforce_account_id = p.salesforce_id
			--								inner join @excluded_partners e
			--									on e.partner_id = p.partner_id)
			--			and vo.vendor_order_code not in (select v.vendor_order_code
			--									from order_company oc
			--									inner join order_header h
			--										on oc.order_header_id = h.order_header_id
			--									inner join vendor_order v
			--										on h.vendor_order_id = v.vendor_order_id
			--									where oc.company_id = @company_id and oc.order_company_type_id in (2,3) and v.vendor_order_code = @vendor_order_code)
			--			and vo.vendor_order_code = @vendor_order_code
			--	end

				-- 2.1.4) @verified
				select @verified = case when @exclude > 0 then 0 else 1 end
				
		end
	-- 2.2) Restricted
	else if @partner_verify_type = 'Restricted'
		begin
			-- print '2.2 Restricted'
			--select partner_type_id = @partner_type_id, company_id = @company_id
			if @partner_type_id = 1
				-- 2.2.1) distributor
				begin
					select @verified = count(oc.order_header_id)
					from order_company oc
					inner join order_header h
						on oc.order_header_id = h.order_header_id
					inner join vendor_order v
						on h.vendor_order_id = v.vendor_order_id
					where oc.company_id = @company_id and oc.order_company_type_id in (2,3,4) and v.vendor_order_code = @vendor_order_code
				end
			else
				-- 2.2.2) reseller
				begin
					select @verified = count(oc.order_header_id)
					from order_company oc
					inner join order_header h
						on oc.order_header_id = h.order_header_id
					inner join vendor_order v
						on h.vendor_order_id = v.vendor_order_id
					where oc.company_id = @company_id and oc.order_company_type_id in (2,3) and v.vendor_order_code = @vendor_order_code
				end
		end
	-- 2.2) Restricted
	else if @partner_verify_type = 'Open'
		begin
		select @verified = 1
		end

	-- 2.3) log failure
	if @verified = 0
		begin
		insert into partner_verify_failure(partner_id, verify_type, verify_value)
		values(@partner_id, 'vendor_order_code', @vendor_order_code)
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select verified = @verified


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;









GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_orders]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_orders]

(
    @partner_key varchar(36),
    @start_date datetime = NULL,
    @end_date datetime = NULL,
    @customer_id int = null,
    @top int = null,
    @pos int = null
)

/*    
    DATE        AUTHOR      REMARKS
    2013-01-07  esmart      Initial creation.
    2013-11-04  esmart      Left join on customer_email
    2016-01-10  esmart      Add @top
    2016-08-04  esmart      Performance 
    2016-09-28  acoffel     Performance
    2017-01-10  acoffel     item and customer info
    2016-12-08  mandersen   Add @pos and @tot to support pagination
    2017-01-18  mandersen   Altered to work with null pagination parameters
    2017-03-03  esmart      Add order_item effective_date and capability_expiration_date
    2019-06-08  rvinoche    Add columns for php
    2019-09-13  jnavarra    Improved row counting and selection
    2019-11-12  wbarton     Adding product_type_description to the selects
    2020-07-22  cnovac      Added 'future approved' status where prior it was just null
	2020-08-19	wbarton		Adding purchase_order to the section 3 select
	2021-03-23	esmart		Add hack for Kaseya Canada to be added to Kaseya partner

    DESCRIPTION
    select partner orders
*/

AS
    set nocount on

    declare @partner_id int,
            @partner_type_id tinyint,
            @company_id int,
            @response_code int,
            @message varchar(100)

    begin try

		declare @partner_company table (company_id int)

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @partner_id
		select @partner_id = p.partner_id, 
				@partner_type_id = p.partner_type_id,
				@company_id = c.company_id
		from partner p
		left join company c
			on p.salesforce_id = c.salesforce_account_id
		where partner_key = @partner_key

		-- 1.2) @partner_company
		insert into @partner_company(company_id) values(@company_id)

			-- 1.2.1) Kaseya Canada
			if @partner_id = 5582
				insert into @partner_company(company_id) values(134802)
				
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) orders
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    
		declare @order_headers table (order_header_id int, vendor_order_code varchar(100), vendor_order_date datetime, total_amount money, sub_total_amount money, tax_total money,
									 product_id int, product_type_description varchar(50), quantity int, years int, list_price money, unit_price money, license_id int, keycode varchar(40), license_seats int, order_item_id int,
									 effective_date datetime, capability_expiration_date datetime, license_category_name varchar(10), partner_license_status_name varchar(50))

		-- 2.1) distributor orders    
		insert into @order_headers(order_header_id, vendor_order_code, vendor_order_date, total_amount, sub_total_amount, tax_total,
						product_id, product_type_description, quantity, years, list_price, unit_price, license_id, keycode, license_seats, order_item_id, effective_date, capability_expiration_date, license_category_name)
		select h.ord
er_header_id, v.vendor_order_code, h.vendor_order_date, h.total_amount, h.sub_total_amount, h.tax_total, i.product_id, pt.product_type_description, i.quantity, y.years,
		i.list_price, i.unit_price, l.license_id, l.keycode, s.license_seats, i.order_item_id, i.effective_date, i.capability_expiration_date, lc.license_category_name
		from order_company cm
		inner join @partner_company pc
			on pc.company_id = cm.company_id
		inner join order_header h
			on cm.order_header_id = h.order_header_id
		inner join vendor_order v
			on h.vendor_order_id = v.vendor_order_id
		inner join order_item i
			on h.order_header_id = i.order_header_id
		inner join order_item_license oi
			on i.order_item_id = oi.order_item_id 
		inner join license l
			on oi.license_id = l.license_id
		inner join license_seat s
			on l.license_id = s.license_id  
		inner join product p
			on i.product_id = p.product_id 
		inner join product_type pt 
			on pt.product_type_id = p.product_type_id
		inner join dbo.product_license_category plc
			on plc.product_id = p.product_id
		inner join dbo.license_category lc
			on lc.license_category_id = plc.license_category_id
		inner join product_years y
			on p.product_id = y.product_id 
		where cm.order_company_type_id in (2,3,4)
			and h.insert_date between @start_date and dateadd(dd,1,@end_date)
		group by h.order_header_id, v.vendor_order_code, h.vendor_order_date, h.total_amount, h.sub_total_amount, h.tax_total,
			i.product_id, pt.product_type_description, i.quantity, y.years, i.list_price, i.unit_price, l.license_id, l.keycode, s.license_seats, i.order_item_id, i.effective_date, i.capability_expiration_date, lc.license_category_name
    
		--2.2) update the partner_license status
		update oh
		set partner_license_status_name = case when pls.partner_license_status_name is not null then pls.partner_license_status_name
											when oh.effective_date > getdate() then 'future approved'
											else 'approved'
										end
		from @order_headers oh
		inner join dbo.partner_order po with (nolock)
		on po.order_header_id = oh.order_header_id and po.partner_id = @partner_id
		left join dbo.partner_license pl with (nolock)
		on pl.partner_id = po.partner_id and pl.license_id = oh.license_id and pl.order_header_id = po.order_header_id
		left join dbo.partner_license_status pls with (nolock)
		on pls.partner_license_status_id = pl.partner_license_status_id

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) results
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		set @pos = isnull(@pos,1)

		;with
		results as (
			select distinct h.order_header_id, h.vendor_order_code, po.purchase_order, h.vendor_order_date, h.order_item_id,
							h.total_amount, h.sub_total_amount, h.tax_total, cu.currency_code, cu.symbol_html, cu.symbol_utf8, cu.symbol_text,
							c.customer_id, c.first_name, c.last_name, cc.company_name, e.customer_email,
							h.product_id, h.product_type_description, h.quantity, h.years, h.list_price, h.unit_price, h.effective_date, h.capability_expiration_date, h.license_id, h.keycode, h.license_seats,
							a.address_1, a.address_2, a.city, a.state, a.postal_code, country_code = lc.iso3, ph.phone_number, h.license_category_name, h.partner_license_status_name
			from @order_headers h
			inner join order_currency oc
				on h.order_header_id = oc.order_header_id
			inner join currency cu
				on oc.currency_id = cu.currency_id
			inner join customer_order o
				on h.order_header_id = o.order_header_id and o.customer_type_id = 2
			inner join customer c
				on o.customer_id = c.customer_id
			left join customer_address a
				on o.customer_id =
 a.customer_id and a.address_type_id = 1 and a.address_status_id = 1
			left join lu_countries lc
				on a.country_id = lc.country_id 
			left join customer_company cc
				on o.customer_id = cc.customer_id
			left join customer_email e
				on o.customer_id = e.customer_id and e.email_status_id = 1
			left join customer_phone ph
				on o.customer_id = ph.customer_id and ph.phone_type_id = 1
			left join purchase_order po
				on po.order_header_id = h.order_header_id
			where c.customer_id = case when @customer_id is not null then @customer_id else c.customer_id end
		),
		vars as (
			select count(*) as total_count
			from results
		),
		counted_results as (
			select *, ROW_NUMBER() OVER(ORDER BY vendor_order_date desc) AS pos, (select total_count from vars) as tot
			from results
		)
		select top(isnull(@top, (select total_count from vars))) *
		from counted_results
		where pos >= @pos

    end try

    begin catch

        set @response_code = -200
        set @message = case when @message is null then 'select failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;


GO
