-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_select_partner_pricing_tier]

(
	@partner_id int,
	@partner_pricing_tier_id int = null,
	@product_id int = null,
	@pricing_status varchar(10) = null

)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-09-22	esmart		Initial creation
	
	DESCRIPTION
	select license ramps
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select t.partner_pricing_tier_id, t.partner_id, t.product_id, p.product_description, t.retail_price, t.currency_id, t.low_range, t.high_range, t.pricing_status, t.last_modified_date 
	from partner_pricing_tier t
	inner join product p
		on t.product_id = p.product_id
	where t.partner_id = @partner_id and
		t.partner_pricing_tier_id = case when @partner_pricing_tier_id is null then t.partner_pricing_tier_id else @partner_pricing_tier_id end and
		t.product_id = case when @product_id is null then t.product_id else @product_id end and
		t.pricing_status = case when @pricing_status is null then t.pricing_status else @pricing_status end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_quote]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_quote]

(
	@partner_quote_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2015-11-18	esmart		Modify for left join
	2017-09-26	esmart		Add locale

	DESCRIPTION
	insert partner_quote
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select q.partner_quote_id, q.partner_id, a.account_user_name, q.insert_date, m.cart_discount_message_id, m.cart_discount_message_description, cart_discount_message_key = convert(varchar(36),m.cart_discount_message_key),
		c.cart_order_in_process_id, st.cart_order_status_id, st.cart_order_status_description, c.locale, c.total_amount, c.sub_total_amount, c.tax_amount,
		cc.first_name, cc.last_name, cc.company_name, cc.customer_email
	from partner_quote q
	inner join cart_discount_message m
		on q.cart_discount_message_id = m.cart_discount_message_id
	inner join cart_discount_message_value v
		on m.cart_discount_message_id = v.cart_discount_message_id
	inner join cart_order_in_process c
		on v.value_id = c.cart_order_in_process_id
	inner join cart_order_status st
		on c.cart_order_in_process_status_id = st.cart_order_status_id
	left join cart_order_customer_in_process cc
		on c.cart_order_in_process_id = cc.cart_order_in_process_id
	left join cart_order_partner_in_process cp
		on c.cart_order_in_process_id = cp.cart_order_in_process_id
	left join partner_account pa
		on cp.partner_account_id = pa.partner_account_id
	left join account a
		on pa.account_id = a.account_id
	where q.partner_quote_id = @partner_quote_id
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_quotes]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_select_partner_quotes]

(
	@partner_key varchar(36),
	@customer_email varchar(100) = null,
	@first_name nvarchar(255) = null,
	@last_name nvarchar(255) = null,
	@account_user_name varchar(100) = null,
	@start_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2015-11-18	esmart		Modify for left join
	2017-09-27	esmart		Add search functionality

	DESCRIPTION
	insert cart_order_partner_in_process
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @quotes table (partner_quote_id int,partner_id int,account_user_name varchar(100),insert_date datetime,cart_discount_message_id int,cart_discount_message_description varchar(50),cart_discount_message_key varchar(36),cart_order_in_process_id int, cart_order_status_id int, cart_order_status_description varchar(50),total_amount money,sub_total_amount money,tax_amount money,first_name nvarchar(255),last_name nvarchar(255),company_name nvarchar(255),customer_email varchar(255))


	insert into @quotes(partner_quote_id,partner_id,account_user_name,insert_date,cart_discount_message_id,cart_discount_message_description,cart_discount_message_key,cart_order_in_process_id,cart_order_status_id, cart_order_status_description,total_amount,sub_total_amount,tax_amount,first_name,last_name,company_name,customer_email)	
	select q.partner_quote_id, q.partner_id, a.account_user_name, q.insert_date, m.cart_discount_message_id, m.cart_discount_message_description, cart_discount_message_key = convert(varchar(36),m.cart_discount_message_key),
		c.cart_order_in_process_id, st.cart_order_status_id, st.cart_order_status_description, c.total_amount, c.sub_total_amount, c.tax_amount,
		cc.first_name, cc.last_name, cc.company_name, cc.customer_email
	from partner_quote q
	inner join cart_discount_message m
		on q.cart_discount_message_id = m.cart_discount_message_id
	inner join cart_discount_message_value v
		on m.cart_discount_message_id = v.cart_discount_message_id
	inner join cart_order_in_process c
		on v.value_id = c.cart_order_in_process_id
	inner join cart_order_status st
		on c.cart_order_in_process_status_id = st.cart_order_status_id
	left join cart_order_customer_in_process cc
		on c.cart_order_in_process_id = cc.cart_order_in_process_id and cc.customer_type_id = 2
	left join cart_order_partner_in_process cp
		on c.cart_order_in_process_id = cp.cart_order_in_process_id
	left join partner_account pa
		on cp.partner_account_id = pa.partner_account_id
	left join account a
		on pa.account_id = a.account_id
	left join cart_order co
		on c.cart_order_in_process_id = co.cart_order_in_process_id
	left join vendor_order vo
		on co.vendor_order_code = vo.vendor_order_code
	where q.partner_id = @partner_id and vo.vendor_order_id is null

	

	if @start_date is not null
		begin
		delete from @quotes where insert_date < @start_date
		end

	select partner_quote_id,partner_id,account_user_name,insert_date,cart_discount_message_id,cart_discount_message_description,cart_discount_message_key,cart_order_in_process_id,cart_order_status_id, cart_order_status_description,total_amount,sub_total_amount,tax_amount,first_name,last_name,company_name,customer_email
	from @quotes q
	where q.customer_email = case when @customer_email is not null then @customer_email else customer_email end and
			q.last_name = case when @last_name is not null then @last_name else last_name end and
			q.first_name = case when @first_name is not null then @first_name else first_name end and
			q.account_user_name = case when @account_user_name is not null then @account_user_name else account_user_name end 
			
		
	order by partner_quote_id desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_partner_search]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_partner_select_partner_search]

(
	@partner_name nvarchar(100), 
	@partner_type_id tinyint = null,
	@partner_status_id tinyint = null,
	@salesforce_id varchar(20) = '', 
	@oracle_id varchar(20) = '',
	@top int = null,
	@pos int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2017-01-20	mandersen	Add @top, @pos, and @tot to support pagination. Altered to work from temp table for performance.

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@tot int,
			@min int,
			@max int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_name 
	if @partner_name is null
		begin select @partner_name = '%%' end
	else
		begin select @partner_name = '%'+@partner_name+'%' end

	-- 1.2) @salesforce_id 
	if @salesforce_id is null
		begin select @salesforce_id = '%%' end
	else
		begin select @salesforce_id = '%'+@salesforce_id+'%' end

	-- 1.3) @oracle_id 
	if @oracle_id is null
		begin select @oracle_id = '%%' end
	else
		begin select @oracle_id = '%'+@oracle_id+'%' end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @partners table (partner_id int, partner_name nvarchar(100), partner_type_id tinyint, partner_status_id tinyint, partner_key varchar(36), parent_partner_id int, salesforce_id varchar(20), oracle_id varchar(20), last_modified_date datetime, last_modified_by varchar(20))
  
	insert into @partners(partner_id, partner_name, partner_type_id, partner_status_id, partner_key, parent_partner_id, salesforce_id, oracle_id, last_modified_date, last_modified_by)
	select p.partner_id, p.partner_name, p.partner_type_id, p.partner_status_id, p.partner_key, p.parent_partner_id, p.salesforce_id, p.oracle_id, p.last_modified_date, p.last_modified_by
	from partner p
	where p.partner_name like @partner_name and
			p.salesforce_id like @salesforce_id and
			p.oracle_id like @oracle_id and
			p.partner_type_id = case when @partner_type_id is null then p.partner_type_id else @partner_type_id end and
			p.partner_status_id = case when @partner_status_id is null then p.partner_status_id else @partner_status_id end 

	set @tot = @@rowcount  
	set @min = isnull(@pos,1)
	set @max = @min + isnull(@top,@tot)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top(isnull(@top,@tot)) p.partner_id, p.partner_name, p.partner_type_id, t.partner_type_name, p.partner_status_id, s.partner_status_name, partner_key = convert(varchar(36),p.partner_key), p.parent_partner_id, parent_partner_name = p2.partner_name, p.salesforce_id, p.oracle_id, p.last_modified_date, p.last_modified_by, pg.pos, @tot as tot

	from @partners p
	inner join 
   (select partner_id, row_number() over (order by partner_name) as pos from @partners) pg
		on pg.partner_id = p.partner_id
	inner join partner_status s
		on p.partner_status_id = s.partner_status_id
	inner join partner_type t
		on p.partner_type_id = t.partner_type_id
	left join partner p2
		on p.parent_partner_id = p2.partner_id
	where (pg.pos between @min and @max)
	order by p.partner_name

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
