-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_select_trial]
-- =============================================================================


CREATE    PROCEDURE [dbo].[usp_partner_select_trial]

(
    @partner_key varchar(36),
    @trial_id int = null,
    @top int = null,
    @pos int = null
)

AS
    /*    
        DATE        AUTHOR      REMARKS
        2014-02-10  esmart      Initial creation.
        2014-03-31  esmart      Remove converted trials from list
        2016-06-10  esmart      Add additional columns
        2016-12-08  mandersen   Add @top, @pos, and @tot to support pagination. Altered to work from temp table for performance.
        2017-01-18  mandersen   Altered to work with null pagination parameters
        2019-09-13  jnavarra    Improved row counting and selection

        DESCRIPTION
        select trial
    */

    set nocount on

    declare @partner_id int,
            @response_code int,
            @message varchar(100)

    begin try


    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    
    -- 1.1) @partner_id
    select @partner_id = partner_id from partner where partner_key = @partner_key

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.2) trials
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    declare @trials table (trial_id int, trial_registration_id int, license_id int, customer_id int, partner_id int, partner_account_id int, insert_date datetime, capability_expiration_date datetime)
  
    insert into @trials(trial_id, trial_registration_id, license_id, customer_id, partner_id, partner_account_id, insert_date, capability_expiration_date)
    select distinct pt.trial_id, t.trial_registration_id, t.license_id, t.customer_id, pt.partner_id, pt.partner_account_id, t.insert_date, cap.capability_expiration_date
    from partner_trial pt
    inner join trial t
        on pt.trial_id = t.trial_id
    inner join license_capability cap
        on t.license_id = cap.license_id and cap.capability_type_id <> 1
    where ((pt.partner_id = @partner_id) and
           (pt.trial_id = case when @trial_id is null then t.trial_id else @trial_id end))


    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 2.) results
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    set @pos = isnull(@pos,1)

    ;with
        results as (
            select
                t.trial_id, t.trial_registration_id, c.customer_id, vc.vendor_customer_code, c.first_name, c.last_name, cc.company_name, ph.phone_number, e.customer_email, a.address_1, a.address_2, a.state, a.postal_code, country = lc.description, 
                t.license_id, license_key = convert(varchar(36),k.license_key), l.keycode, l.license_type_id, lt.license_type_description, t.capability_expiration_date,
                p.partner_key, p.partner_name, p.salesforce_id, pa.partner_account_key, aa.account_user_name,
                st.s
alesforce_lead_id, st.salesforce_opportunity_id, st.salesforce_trial_id, t.insert_date
            from @trials t
            inner join license l
                on l.license_id = t.license_id
            inner join license_type lt
                on l.license_type_id = lt.license_type_id
            inner join license_key k
                on k.license_id = t.license_id
            inner join customer c
                on t.customer_id = c.customer_id
            left join customer_email e
                on c.customer_id = e.customer_id and e.email_status_id = 1
            left join vendor_customer vc
                on c.customer_id = vc.customer_id
            left join customer_company cc
                on c.customer_id = cc.customer_id
            left join customer_phone ph
                on c.customer_id = ph.customer_id
            left join customer_address a
                on c.customer_id = a.customer_id and a.address_status_id = 1 and a.address_type_id = 1
            left join lu_countries lc
                on a.country_id = lc.country_id
            left join partner p
                on t.partner_id = p.partner_id
            left join partner_account pa
                on t.partner_account_id = pa.partner_account_id
            left join account aa
                on pa.account_id = aa.account_id
            left join sfdc_trial st
                on t.trial_id = st.trial_id
        ),
        vars as (
            select count(*) as total_count
            from results
        ),
        counted_results as (
            select *, ROW_NUMBER() OVER(ORDER BY trial_id desc) AS pos, (select total_count from vars) as tot
            from results
        )
        select top(isnull(@top, (select total_count from vars))) *
        from counted_results
        where pos >= @pos
    

    end try

    begin catch

        set @response_code = -200
        set @message = case when @message is null then 'select failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_insert_log]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_service_insert_log]

(
	@partner_account_key varchar(36),
	@partner_service_method_id tinyint,
	@partner_json varchar(max) = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2017-03-21	acoffel		Extend to log json input	

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_key varchar(36),
			@partner_service_method_name varchar(50),
			@partner_account_id int,
			@partner_service_log_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_account_id
	select @partner_account_id = partner_account_id, @partner_id = partner_id from partner_account where partner_account_key = @partner_account_key

	-- 1.2) check @partner_service_method_id
	if (select count(*) from partner_service_method_partner where partner_id = @partner_id and partner_service_method_id = @partner_service_method_id) = 0
		begin
		-- 1.2.1) log failure and return
		select @partner_service_method_name = partner_service_method_name from partner_service_method where partner_service_method_id = @partner_service_method_id
		select @response_code = -120, @message = @partner_service_method_name + ' is not supported for this partner'
		
		insert into partner_service_log_failure(partner_id, partner_account_id, partner_service_method_id, response_code, message)
		values(@partner_id, @partner_account_id, @partner_service_method_id, @response_code, @message)
		
		select response_code = @response_code, message = @message
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert partner_service_log
	insert into partner_service_log(partner_id, partner_service_method_id, partner_account_id) values(@partner_id, @partner_service_method_id, @partner_account_id)

	-- 2.2) return partner_service_log_id
	select @partner_service_log_id = SCOPE_IDENTITY()

	-- 2.3) log json 
	if @partner_json is not NULL
		begin 
			insert into partner_service_log_json (partner_service_log_id, partner_json, insert_date)
			select @partner_service_log_id, @partner_json, getdate()
		end

	select partner_service_log_id = @partner_service_log_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_insert_order]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_service_insert_order]

(
	@partner_service_log_id int,
	@partner_order_code varchar(20)=null,
	@partner_order_date datetime = null,
	@language_code varchar(2) = null,
	@location_code varchar(3) = null,
	@purchase_order varchar(100) = null,
	@site_id varchar(65) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2014-03-13	esmart		Check for null values
	2014-04-21	esmart		Setup default billing location
	2016-11-04	esmart		site_id

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare	@partner_id int,
			@partner_service_order_id int,
			@date_override_value varchar(500),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner_service_log where partner_service_log_id = @partner_service_log_id

	-- 1.2) @partner_order_date
	select @date_override_value = p.configuration_value
	from partner_configuration_partner p
	inner join partner_configuration c
		on c.partner_configuration_id = p.partner_configuration_id
	where p.partner_id = @partner_id and c.configuration_name = 'date_override'

	if @date_override_value is null begin select @date_override_value = 'No' end

	if @partner_order_date is null or @date_override_value = 'No'
		begin
		select @partner_order_date = getdate()
		end

	-- 1.3) default billing
	if (select count(*) from partner_language_location where partner_id = @partner_id and billing_default = 1) > 0
		begin
		select @language_code = language_code, @location_code = location_code
		from partner_language_location 
		where partner_id = @partner_id and billing_default = 1
		end

	-- 1.3) @language_code/@location_code
	if @language_code is null
		begin
		select @language_code = 'EN'
		end
	if @location_code is null
		begin
		select @location_code = 'USA'
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into partner_service_order(partner_service_log_id, partner_id, partner_order_code, partner_order_date, language_code, location_code, purchase_order, site_id)
	values(@partner_service_log_id, @partner_id, @partner_order_code, @partner_order_date, @language_code, @location_code, @purchase_order, @site_id)
	
	select @partner_service_order_id = SCOPE_IDENTITY()

	select partner_service_order_id = @partner_service_order_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_insert_order_item]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_service_insert_order_item]

(
		@partner_service_order_id int,
		@partner_product_id varchar(20) = null,
		@quantity int,
		@seats int = NULL,
		@list_price money = NULL,
		@unit_price money = NULL,
		@start_date datetime = NULL,
		@expiration_date datetime = NULL,
		@keycode varchar(40) = NULL,
		@pricing_level varchar(20) = NULL,
		@external_item_id varchar(36) = null,
		@order_item_update_type_id tinyint = null,
		@license_attribute_license_value int = null,
		@autobilling_attribute int,
		@item_bundle_id tinyint = null,
		@module_json nvarchar(500) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-10-10	esmart		Initial creation.
	2015-01-13	esmart		Support for parent products
	2015-07-21	esmart		@external_item_id, @order_item_update_type_id
	2016-05-25	esmart		Change upgrade to use @seats as the total new seats not additional seats
	2016-08-24	esmart		Fix issue with partner_product mapping
	2016-10-19	esmart		Trap new product against full licenses to fix issue with partner_license on cart update
	2016-11-02	esmart		license_attribute_license_value
	2017-03-21	esmart		item_bundle_id
	2019-01-10	rvinoche	Support autobilling attributes living only in license_effective_object

	DESCRIPTION
	insert partner_service_order_item
*/

AS
	set nocount on				

	declare	@line_item tinyint,
			@product_id int,
			@product_type_id int,
			@product_line_id int,
			@partner_id int,
			@license_id int,
			@license_attribute_id int,
			@license_category_name varchar(10),
			@license_category_id int,
			@capability_type_id int,
			@license_seats int,
			@storage_gb int,
			@years float,
			@language_code varchar(2), 
			@location_code varchar(3),
			@cart_discount_id int,
			@partner_service_order_item_id int,
			@partner_service_method_name varchar(50),
			@cart_type_id int, 
			@trial_days int, 
			@license_keycode_type_id int,
			@site_id varchar(20),
			@date_override_value varchar(500),
			@contract_days float,
			@days_remaining float,
			@transaction_date datetime, 
			@capability_expiration_date datetime,
			@capability_activation_date datetime,
			@current_license_attribute_license_value int,
			@current_license_attribute_id int,
			@next_billing_process_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	
-- Status is 0 for Disabled, 1 for Active, 2 for Trial

--select * from license_status
--select * from license_type

	--select @module_json = '{"product": [{"license_module_code":"DNS","license_seats":"100"},]}'

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @partner_product_id = ''
		begin
		select @partner_product_id = null
		end

	-- remove inbound pricing. not sure if we will ever allow this.
	select @list_price = null, @unit_price = null

	-- 1.1) header data
	select @partner_id = o.partner_id, @language_code = o.language_code, @location_code = o.location_code, @partner_service_method_name = m.partner_service_method_name
	from partner_service_order o 
	inner join partner_service_log l
		on o.partner_service_log_id = l.partner_service_log_id
	inner join partner_service_method m
		on l.partner_service_method_id = m.partner_service_method_id
	where o.partner_service_order_id = @partner_service_order_id

	-- 1.1) @capability_type_id
	select @capability_type_id = s.capability_type_id
	from license_summary s
	where s.keycode = @keycode

	-- 1.2) product
	if @partner_product_id is null
		begin
		--select keycode = @keycode
		select @product_type_id = 3,
				@product_line_id = l.product_line_id,
				@license_category_name = lc.license_category_name,
				@license_category_id = lc.license_category_id,
				@license_seats = @seats,			
				@storage_gb = st.storage_gb,
				@years = 0,
				@license_id = l.license_id
		from license l
		inner join license_category_license lcl
			on l.license_id = lcl.license_id
		inner join license_category lc
			on lcl.license_category_id = lc.license_category_id
		inner join license_seat s
			on l.license_id = s.license_id
		left join license_storage st
			on l.license_id = st.license_id
		where l.keycode = @keycode

		select @license_attribute_license_value = dbo.fn_license_select_effective_object_element(@license_id, license_category_id,'license_attribute_license_value',getdate())
		from dbo.license_category_license
		where license_id = @license_id

		select @site_id = pa.site_id
		from dbo.partner_license_attribute pa
		inner join dbo.license_attribute_license_value v
			on v.license_attribute_license_value = pa.license_attribute_license_value
		where pa.partner_id = @partner_id and pa.license_category_id = @license_category_id
			and pa.license_attribute_id = v.license_attribute_id
			and v.license_attribute_license_value = @license_attribute_license_value

		if @site_id is null
			begin
			select @site_id = site_id
			from partner_license_category_product_line
			where partner_id = @partner_id and license_category_id = @license_category_id and product_line_id = @product_line_id
			end

		end
	else
		begin
			select @product_id = p.product_id,
					@product_type_id = case when p.product_type_id = 1 and @capability_type_id = 1 then 2 else p.product_type_id end,
					@product_line_id = pl.product_line_id,
					@license_category_name = c.license_category_name,
					@license_category_id = lc.license_category_id,
					@license_seats = @seats,
					@storage_gb = st.storage_gb,
					@years = y.years,
					@license_keycode_type_id = p.license_keycode_type_id,
					@trial_days = case when capability_type_id <> 1 then pc.capability_activation_days else 0 end,
					@license_attribute_license_value = pp.license_attribute_license_value,
					@site_id = pp.site_id
			from partner_service_product pp 
			inner join product p
				on pp.product_id = p.product_id
			inner join product_line_product pl
				on pp.product_id = pl.product_id
			inner join product_license_category lc
				on pp.product_id = lc.product_id
			inner join license_category c
				on lc.license_category_id = c.license_category_id
			left join product_capability pc
				on p.product_id = pc.product_id and pc.capability_id = c.base_capability_id
			inner join product_seat s
				on pp.product_id = s.product_id
			inner join product_years y
				on pp.product_id = y.product_id
			left join product_storage st
				on pp.product_id = st.product_id
			where pp.partner_product_id = @partner_product_id and pp.partner_id = @partner_id
		end
		
	-- 1.3) check to see currency, lang, loc are on header
	if @language_code is null or @location_code is null
		begin
		select @language_code = t.language_code, @location_code = t.location_code
		from (select top 1 pl.language_code, pl.location_code
			from partner_language_location pl
			where partner_id = @partner_id
			order by partner_language_location_id) t
		end

	-- 1.4) @module_json
	--if @product_type_id = 4
	--	begin
	--		select @module_json = '{"license_module_code":"'+ m.license_module_code +'","module_seats":"'+ convert(varchar(20),@license_seats) +'"}'
	--		from product_license_module pm
	--		inner join license_module m
	--			on m.license_module_id = pm.license_module_id
	--		where product_id = @product_id
	--	end

	-- 1.4) @list_price, @unit_price
	declare @product_set table(line_item int
 identity(1,1), product_id int, product_description varchar(100), quantity int default 1, retail_price money, upgrade_price money, discount money, standard_discount money, net_price money, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), cart_item_class_id tinyint, cart_item_bundle_id int, keycode varchar(40), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int, license_category_id int, license_attribute_id int, license_attribute_license_value int, start_date datetime, expiration_date datetime, contract_days float)

	if @list_price is null and @unit_price is null or @partner_product_id is null
		begin
			-- 1.4.1) Business
			if @product_line_id in (300,55)
				begin
				-- 1.4.1.1) new purchase
				if @keycode is null
					begin
						-- print '1.4.1.1) new purchase'
						if @partner_service_method_name = 'create_trial_license'
							begin
							insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years)
							select p.product_id,p.product_description,retail_price=0,retail_price=0,discount=0,standard_discount=0,net_price=0,p.product_type_id,c.license_category_name,s.seats,y.years
							from product p
							inner join product_line_product pl
								on p.product_id = pl.product_id
							inner join product_license_category lc
								on p.product_id = lc.product_id
							inner join license_category c
								on lc.license_category_id = c.license_category_id
							inner join product_seat s
								on p.product_id = s.product_id
							inner join product_years y
								on p.product_id = y.product_id
							left join product_storage st
								on p.product_id = st.product_id
							where p.product_id = @product_id
							end
						else
							begin
							--print '1.4.1.2'
							--select @license_category_name, @seats, @storage_gb, @years, @cart_discount_id, @language_code, @location_code, @cart_type_id, @trial_days, @license_keycode_type_id, @pricing_level
							insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)
							exec usp_cart_select_new_product_set_ENT @license_category_name, @seats, @storage_gb, @years, @cart_discount_id, @language_code, @location_code, @cart_type_id, @trial_days, @license_keycode_type_id, @pricing_level, @module_json
							end
					end
				-- 1.4.1.2) renewal purchase
				else
					begin
						-- print '1.4.1.2) renewal purchase'
						-- select '1.4.1.2', keycode = @keycode, license_category_name = @license_category_name, license_seats = @license_seats, years = @years, cart_discount_id = @cart_discount_id,language_code = @language_code, location_code = @location_code, pricing_level =  @pricing_level, module_json = @module_json

						--select @keycode,@license_category_name,@seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@pricing_level,@module_json
						insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type,currency_id,currency_code,currency_description,symbol_html,symbol_utf8,symbol_text,cart_discount_id)	
						exec usp_cart_select_renewal_product_set_ENT @keycode,@license_category_name,@seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@pricing_level,@module_json
					end
				end
			-- 1.4.2) Consumer
			else
				begin
				-- 1.4.2.1) new purchase
				if @keycode is null
					begin
						insert into @product_set(product_id,product_description,retail_price,
upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)
						--exec usp_cart_select_new_product_set @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code	
						exec usp_cart_select_new_product_set @license_category_name, @license_seats, @storage_gb, @years, @cart_discount_id, @language_code, @location_code, @cart_type_id, @trial_days, @license_keycode_type_id
					end
				-- 1.4.2.2) renewal purchase
				else
					begin
						insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)	
						exec usp_cart_select_renewal_product_set @keycode,@license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code
					end
				end

		end
	-- 1.5) add product set
	else
		begin
		insert into @product_set(product_id,retail_price,net_price,quantity,seats)	
		values(@product_id,@list_price,@unit_price,@quantity,@seats)
		end

	-- 1.6) license_attribute_license_value
		
		-- 1.6.1) update @product_set.license_attribute
		--update @product_set
		--set license_attribute_id = case when @license_attribute_license_value in (120,220) then null else v.license_attribute_id end
		--from license_attribute_license_value v
		--where v.license_attribute_license_value = @license_attribute_license_value
		
		-- 1.6.2) update @product_set.license_category_id
		update @product_set 
		set license_category_id = c.license_category_id, cart_discount_id = null
		from @product_set s
		inner join license_category c
			on c.license_category_name = s.license_category_name

		-- 1.6.3) @current_license_attribute_id and @current_license_attribute_license_value
		select @autobilling_attribute = dbo.fn_license_select_effective_object_element(@license_id, license_category_id,'license_attribute_license_value',getdate())
		from dbo.license_category_license
		where license_id = @license_id

		-- 1.6.4) @next_billing_process_date
		if @current_license_attribute_id in (10,100,200)
			begin
			select @next_billing_process_date = process_date
			from license_message
			where license_id = @license_id and message_type_id = 10 and message_status_id = 1
			end


	-- 1.7) @date_override_value
		select @date_override_value = p.configuration_value
		from partner_configuration_partner p
		inner join partner_configuration c
			on c.partner_configuration_id = p.partner_configuration_id
		where p.partner_id = @partner_id and c.configuration_name = 'date_override'

		if @date_override_value is null
			begin
			select @date_override_value = 'No'
			end
	
	
	-- 1.13) @item_bundle_id
		if @item_bundle_id is null
			begin
			select @item_bundle_id = max(item_bundle_id) + 1
			from partner_service_order_item
			where partner_service_order_id = @partner_service_order_id

			if @item_bundle_id is null
				begin
					select @item_bundle_id = 1
				end
			end

			update @product_set
			set cart_item_bundle_id = @item_bundle_id
			

	-- 1.8) partner tier pricing
	select @capability_expiration_date = convert(date,capability_expiration_date), @capability_activation_date = convert(date,c.capability_activation_date), @days_remaining = datediff(dd,getdate(),capability_expiration_date)
	from license l
	inner join license_capability c
		on c.license_id = l.license_id
	where l.keycode = @keycode

	select @transaction_date = getdate()
	
		-- 1.8.1) new
		if @keycode is null
			begin
				update @product_set
				set start_date = case
									when @date_override_value = 'Yes' and @start_date is not null then @start_date
									else convert(date,getd
ate())
								end,
					expiration_date = case
									when @date_override_value = 'Yes' and @expiration_date is not null then @expiration_date
									-- when @date_override_value <> 'Yes' and @start_date is not null then dateadd(dd,c.capability_activation_days,@start_date)
									else dateadd(dd,c.capability_activation_days,convert(date,getdate()))
								end
				from @product_set p
				inner join product_capability c
					on c.product_id = p.product_id
				where c.capability_type_id = 1

				update p
				set start_date = p2.start_date, expiration_date = p2.expiration_date
				from @product_set p
				inner join @product_set p2
					on p2.cart_item_bundle_id = p.cart_item_bundle_id and p2.product_type_id <> 4
				where p.product_type_id = 4
			end
		-- 1.8.2) renewal/upgrade
		else
			begin
			--print '1.8.2) renewal/upgrade'
				update @product_set
				set start_date = case
									when @autobilling_attribute in (12,110,111,112,210,211,212) and @license_attribute_license_value in (20,120,220) then @next_billing_process_date
									when p_type = 'renewal' and @capability_expiration_date > getdate() then @capability_expiration_date
									else convert(date,getdate())
								end
				from @product_set p

				update @product_set
				set expiration_date = case
									when @date_override_value = 'Yes' and p_type = 'Renewal' and @expiration_date is not null then @expiration_date
									when @date_override_value = 'Yes' and p_type = 'Renewal' and @expiration_date is null then dateadd(dd,c.capability_activation_days,start_date)
									when @date_override_value <> 'Yes' and p_type = 'Renewal' then dateadd(dd,c.capability_activation_days,start_date)
									else @capability_expiration_date
								end
				from @product_set p
				inner join product_capability c
					on c.product_id = p.product_id
				where c.capability_type_id = 1

				-- 3.4.3) update expiration on module product

				--select expiration_date = case
				--					when @date_override_value = 'Yes' and p2.p_type = 'Renewal' and @expiration_date is not null then 1
				--					when @date_override_value = 'Yes' and p2.p_type = 'Renewal' and @expiration_date is null then 2
				--					when @date_override_value <> 'Yes' and p2.p_type = 'Renewal' then 3
				--					else 4
				--				end
				--from @product_set p
				--inner join product pp
				--	on pp.product_id = p.product_id
				--left join @product_set p2
				--	on p2.cart_item_bundle_id = p.cart_item_bundle_id and p2.product_id <> p.product_id
				--where pp.product_type_id = 4

				update p
				set expiration_date = case
									when @date_override_value = 'Yes' and p2.p_type = 'Renewal' and @expiration_date is not null then @expiration_date
									when @date_override_value = 'Yes' and p2.p_type = 'Renewal' and @expiration_date is null then p2.expiration_date -- dateadd(dd,c.capability_activation_days,start_date)
									when @date_override_value <> 'Yes' and p2.p_type = 'Renewal' then p2.expiration_date
									else @capability_expiration_date
								end
				from @product_set p
				inner join product pp
					on pp.product_id = p.product_id
				left join @product_set p2
					on p2.cart_item_bundle_id = p.cart_item_bundle_id and p2.product_id <> p.product_id
				where pp.product_type_id = 4
			end

	-- 1.13) @module_json_table
		declare @module_json_table table (license_module_code varchar(50), module_seats int, product_id int)

		if @module_json is not null
			begin
				-- 1.13.1) parse json
				insert into @module_json_table (license_module_code, module_seats)
				select license_module_code, p.module_seats
				from (select row_id = parent_ID, parameter_name = NAME, input_value = case when StringValue = '' then null else StringValue end
					from dbo.fn_parse_json(@module_json) 
					where Object_ID is null and StringValue is not null) j 
				pivot (max(input_value) for parameter_name in (license_module_code, module_seats
)) as p

				-- 1.13.2) update product
				update @module_json_table
				set product_id = p.product_id
				from @module_json_table mp
				inner join license_module m 
					on m.license_module_code = mp.license_module_code
				inner join product_license_module pm
					on m.license_module_id = pm.license_module_id
				inner join license_module_type t
					on t.license_module_type_id = pm.license_module_type_id
				inner join product p
					on p.product_id = pm.product_id
				where t.license_module_type_name = 'full'
			end

	

	-- 1.9) @contract_days
		update @product_set
		set contract_days = datediff(dd,start_date,expiration_date)
		
	--select contract_months = @contract_months
	--return 

	-- 1.10) partner pricing
		--update @product_set 
		--set license_category_id = c.license_category_id, cart_discount_id = null
		--from @product_set s
		--inner join license_category c
		--	on c.license_category_name = s.license_category_name

		--select license_attribute_license_value = @license_attribute_license_value, license_attribute_id = @license_attribute_id, capability_expiration_date = @capability_expiration_date, license_seats = @license_seats, 
		--	contract_days = @contract_days,	days_remaining = @days_remaining, partner_id = @partner_id, site_id = @site_id
						
		if @license_attribute_license_value is null or @license_attribute_license_value in (120,220)
		-- 1.10.1) not monthly
			begin

			-- testing model
			--select 
			--model = case
			--						when s.product_type_id = 3 and t.pricing_term = 'monthly' then 1
			--						when s.product_type_id <> 3 and t.pricing_term = 'monthly' then 2

			--						when s.product_type_id = 3 and t.pricing_term = 'annual' then 3
			--						when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is null then 4
			--						when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is not null then 5
			--					end,
			--					s.quantity, license_seats = @license_seats, t.retail_price, s.contract_days, m.module_seats,
			--					pricing_seats = case 
			--								when m.module_seats is not null then m.module_seats
			--								else @license_seats 
			--							end
			--from partner_pricing_tier t 
			--inner join @product_set s
			--	on t.license_category_id = s.license_category_id
			--left join @module_json_table m
			--	on m.product_id = s.product_id
			--where t.pricing_status = 'active' and t.partner_id = @partner_id and t.license_attribute_id is null and t.site_id = @site_id and t.currency_id = s.currency_id
			--		and t.low_range <= case 
			--								when m.module_seats is not null then m.module_seats
			--								else @license_seats 
			--							end
			--		and t.high_range >  case 
			--								when m.module_seats is not null then m.module_seats
			--								else @license_seats 
			--							end
						
			-- print '1.10.1) not monthly'
			update @product_set
			set retail_price = case
									when s.product_type_id = 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)
									when s.product_type_id <> 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)

									when s.product_type_id = 3 and t.pricing_term = 'annual' then (s.quantity * (t.retail_price/365) * @days_remaining)
									when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is null then (s.quantity * t.retail_price * s.years)
									when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is not null then (s.quantity * t.retail_price * (contract_days/365))
								end,
				upgrade_price = case
									when s.product_type_id = 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)
									when s.product_type_id <> 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)

									when s.product_type_id = 3 and t.pricing_term = 'annual' then (s.quantity * (t.retail_price/365) * @days_remaining)
									when 
s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is null then (s.quantity * t.retail_price * s.years)
									when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is not null then (s.quantity * t.retail_price * (contract_days/365))
								end,
				net_price = case
									when s.product_type_id = 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)
									when s.product_type_id <> 3 and t.pricing_term = 'monthly' then (s.quantity * t.retail_price)

									when s.product_type_id = 3 and t.pricing_term = 'annual' then (s.quantity * (t.retail_price/365) * @days_remaining)
									when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is null then (s.quantity * t.retail_price * s.years)
									when s.product_type_id <> 3 and t.pricing_term = 'annual' and contract_days is not null then (s.quantity * t.retail_price * (contract_days/365))
								end,
				discount = 0,
				standard_discount = 0,
				cart_discount_id = null
			from partner_pricing_tier t 
			inner join @product_set s
				on t.license_category_id = s.license_category_id
			left join @module_json_table m
				on m.product_id = s.product_id
			where t.pricing_status = 'active' and t.partner_id = @partner_id and t.license_attribute_id is null and t.site_id = @site_id and t.currency_id = s.currency_id
					and t.low_range <= case 
											when m.module_seats is not null then m.module_seats
											else @license_seats 
										end
					and t.high_range >  case 
											when m.module_seats is not null then m.module_seats
											else @license_seats 
										end
			
			end 
		else 
		-- 1.10.2) monthly
			begin
			-- print '1.10.2) monthly'
			update @product_set
			set retail_price = (t.retail_price),
				upgrade_price = (t.retail_price),
				net_price = (t.retail_price),
				discount = 0,
				standard_discount = 0,
				cart_discount_id = null
			from partner_pricing_tier t
			inner join @product_set s
				on t.license_category_id = s.license_category_id
			left join @module_json_table m
				on m.product_id = s.product_id
			where t.pricing_status = 'active' and t.partner_id = @partner_id and t.license_attribute_id is null and t.site_id = @site_id and t.currency_id = s.currency_id
					and t.low_range <= case 
											when m.module_seats is not null then m.module_seats
											else @license_seats 
										end
					and t.high_range >  case 
											when m.module_seats is not null then m.module_seats
											else @license_seats 
										end
			end

		-- 1.11) round
		update @product_set
		set retail_price = round(retail_price,2), upgrade_price = round(upgrade_price,2), net_price = round(net_price,2)

		-- 1.12) update negative values
		update @product_set
		set retail_price = 0, net_price = 0
		where retail_price < 0

	--select line_item = @line_item, product_line_id = @product_line_id, product_id = @product_id, list_price = @list_price, unit_price = @unit_price, language_code = @language_code, location_code = @location_code, cart_discount_id = @cart_discount_id
	--select * from @product_set
	-- return

	 --select item_bundle_id = @item_bundle_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) partner_service_order_item
	if @partner_service_method_name = 'cancel_license'
		-- 2.1.1) cancel
		begin
		-- print '2.1.1) cancel'
		insert into partner_service_order_item(line_item,partner_service_order_id)
		values(1,@partner_service_order_id)
		end
	else
		-- 2.1.2) insert item
		begin
		-- print '2.1.2) ins
ert item'
		insert into partner_service_order_item(partner_service_order_id, line_item, product_id, quantity, seats, list_price, unit_price, start_date, expiration_date, external_item_id, order_item_update_type_id, license_attribute_license_value, item_bundle_id)
		select partner_service_order_id = @partner_service_order_id, 
			line_item, 
			product_id, 
			quantity = @quantity, 
			seats, 
			retail_price = isnull(retail_price,0),
			net_price = isnull(net_price,0),
			--list_price = case when product_type_id <> 1 then isnull(retail_price,0)/@seats else isnull(retail_price,0) end, 
			--unit_price = case when product_type_id <> 1 then isnull(net_price,0)/@seats else isnull(net_price,0) end, 
			start_date, 
			expiration_date, 
			@external_item_id,
			@order_item_update_type_id,
			@license_attribute_license_value,
			@item_bundle_id
		from @product_set
		end

	-- 2.2) partner_service_order_item_license
	if @keycode is not null
		begin
		insert into partner_service_order_item_license(partner_service_order_item_id,keycode)
		select i.partner_service_order_item_id, @keycode
		from partner_service_order_item i
		left join partner_service_order_item_license il
			on i.partner_service_order_item_id = il.partner_service_order_item_id
		where i.partner_service_order_id = @partner_service_order_id and il.partner_service_order_item_license_id is null
		end

	-- 2.3)
	if @site_id is not null
		begin
		update partner_service_order
		set site_id = @site_id
		where partner_service_order_id = @partner_service_order_id
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;









GO
