CREATE PROCEDURE [dbo].[usp_partner_service_insert_order_process]

(
	@partner_key varchar(36),
	@site_id varchar(20),
	@partner_service_order_process_id tinyint,
	@license_attribute_id int = null,
	@license_attribute_license_value int = NULL,
	@insert_by varchar(20),
	@delete tinyint = 0
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2016-05-02	esmart		Add

	DESCRIPTION
	select partner service methods
*/

AS
	set nocount on				

	declare @partner_id int,
			@partner_service_order_process_partner_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @insert_by
	if @insert_by is null begin select @insert_by = suser_sname() end

	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	-- 1.2) @partner_service_order_process_partner_id
	select @partner_service_order_process_partner_id = partner_service_order_process_partner_id
	from partner_service_order_process_partner where partner_id = @partner_id and site_id = @site_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) delete from partner_cart_discount
	if @delete = 1
		begin
		delete from partner_service_order_process_partner where partner_service_order_process_partner_id = @partner_service_order_process_partner_id
		end

	if @partner_service_order_process_partner_id is null
	-- 2.2) insert
		begin
			insert into partner_service_order_process_partner(partner_id, site_id, partner_service_order_process_id, license_attribute_id, license_attribute_license_value, insert_by)
			values(@partner_id,@site_id,@partner_service_order_process_id,@license_attribute_id,@license_attribute_license_value,@insert_by)
		end
	else
	-- 2.3) update
		begin
			update partner_service_order_process_partner
			set site_id = @site_id, partner_service_order_process_id = @partner_service_order_process_id, license_attribute_id = @license_attribute_id, license_attribute_license_value = @license_attribute_license_value
			where partner_service_order_process_partner_id = @partner_service_order_process_partner_id
		end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
