CREATE PROCEDURE [dbo].[usp_partner_service_process_cancel]

(
	@partner_service_log_id int,
	@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2014-01-07	esmart		Initial creation.
	2014-12-14	esmart		Add partner_service_cancel
	2015-08-07	esmart		Move insert partner_service_cancel in front of license update
	2017-10-18	esmart		Refactor to use license service

	DESCRIPTION
	process cancel
*/

AS
	set nocount on				

	declare @license_service_json nvarchar(max), 
			@license_service_id int, 
			@license_service_type_name varchar(50),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @license_service_json
	select @license_service_json = (select keycode = @keycode, account_name = a.account_user_name
									from partner_service_log l
									inner join partner_account pa
										on pa.partner_account_id = l.partner_account_id
									inner join account a
										on a.account_id = pa.account_id
									where l.partner_service_log_id = @partner_service_log_id
									for json path)

	-- 1.2) @license_service_type_name
	select @license_service_type_name = 'license_disable'
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert license service
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) partner_service_cancel
	insert into partner_service_cancel(partner_service_log_id,keycode) 
	values(@partner_service_log_id,@keycode)

	-- 2.2) license service
	exec usp_license_service_insert_service @license_service_type_name, @license_service_json

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_process_child_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_service_process_child_license]

(
	@partner_service_log_id int,
	@parent_keycode varchar(40),
	@license_seats int
)


/*	
	DATE		AUTHOR		REMARKS
	2014-12-29	esmart		Initial creation.

	DESCRIPTION
	select partners registered for service
*/

AS
	set nocount on				

	declare	@partner_service_license_parent_id int,
			@first_name nvarchar(225), 
			@last_name nvarchar(225), 
			@customer_email varchar(100), 
			@company_name varchar(255),	
			@machine_name varchar(20),
			@guid varchar(36),
			@external_keycode varchar(40),
			@trial tinyint,
			@child_keycode varchar(40),
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @partner_service_license_parent_id = partner_service_license_parent_id
	from partner_service_license_parent
	where partner_service_log_id = @partner_service_log_id

	if @partner_service_license_parent_id is not null
		begin
		select child_keycode
		from partner_service_license_parent
		where partner_service_license_parent_id = @partner_service_license_parent_id 
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) @partner_service_license_parent_id
	insert into partner_service_license_parent(partner_service_log_id, parent_keycode, license_seats)
	values(@partner_service_log_id,@parent_keycode,@license_seats)

	select @partner_service_license_parent_id = scope_identity()

	select @guid = @partner_service_license_parent_id

	declare @child_keycode_table table (keycode varchar(40), failure_type_id int)
	
	-- 2.2) create_child_license
	insert into @child_keycode_table(keycode,failure_type_id)
	exec usp_license_insert_child_license @parent_keycode, @guid, @machine_name, @external_keycode, @license_seats, @trial, @first_name, @last_name, @customer_email, @company_name
	

	-- 2.3) update partner_service_license_parent
	select @child_keycode = keycode
	from @child_keycode_table

	update partner_service_license_parent
	set child_keycode = @child_keycode
	where partner_service_license_parent_id = @partner_service_license_parent_id

	select child_keycode = @child_keycode

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_search_partner_service]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_service_search_partner_service]

(
	@partner_id int = null,
	@partner_service_method_id tinyint = null,
	@partner_service_status_id tinyint = null,
	@partner_order_code varchar(20) = null,
	@purchase_order varchar(100) = null,
	@start_date datetime = null,
	@end_date datetime = null,
	@order_company_type_id tinyint = 1,
	@company_name nvarchar(255) = null,
	@customer_email varchar(100) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-12-20	esmart		Initial creation.

	DESCRIPTION
	Search partner service
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	---- 1.1) @partner_order_code
	--if @partner_order_code is null 
	--	begin select @partner_order_code = '%%' end
	--else
	--	begin select @partner_order_code = '%'+@partner_order_code+'%' end

	---- 1.2) @purchase_order
	--if @purchase_order is null 
	--	begin select @purchase_order = '%%' end
	--else
	--	begin select @purchase_order = '%'+@purchase_order+'%' end

	-- 1.3) @start_date
	if @start_date is null or @start_date = ''
		begin
		select @start_date = '2013-01-01'
		end
	if @end_date is null or @end_date = ''
		begin
		select @end_date = getdate()
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) search
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) build list
	declare @partner_service_log table (partner_service_log_id int, partner_id int, partner_name nvarchar(100), partner_service_method_id tinyint, partner_service_method_name varchar(50), partner_service_status_id tinyint, partner_service_status_name varchar(50), insert_date datetime, partner_order_code varchar(20), purchase_order varchar(100), company_name nvarchar(255), customer_email varchar(100), order_company_type_id tinyint, keycode varchar(40))

	insert into @partner_service_log(partner_service_log_id, partner_id, partner_name, partner_service_method_id, partner_service_method_name, partner_service_status_id, partner_service_status_name, insert_date, partner_order_code, purchase_order, company_name, customer_email, order_company_type_id, keycode)
	select l.partner_service_log_id, l.partner_id, p.partner_name, l.partner_service_method_id, m.partner_service_method_name, l.partner_service_status_id, s.partner_service_status_name, l.insert_date,
		o.partner_order_code, o.purchase_order, 
		c.company_name, c.customer_email, c.order_company_type_id,
		cn.keycode
	from partner_service_log l
	inner join partner p
		on l.partner_id = p.partner_id
	inner join partner_service_method m
		on l.partner_service_method_id = m.partner_service_method_id
	inner join partner_service_status s
		on l.partner_service_status_id = s.partner_service_status_id
	left join partner_service_cancel cn
		on l.partner_service_log_id = cn.partner_service_log_id
	left join partner_service_order o
		on l.partner_service_log_id = o.partner_service_log_id
	left join partner_service_order_customer c
		on o.partner_service_order_id = c.partner_service_order_id
	where l.partner_id = case when @partner_id is null then l
.partner_id else @partner_id end and
		l.partner_service_method_id = case when @partner_service_method_id is null then l.partner_service_method_id else @partner_service_method_id end and
		l.partner_service_status_id = case when @partner_service_status_id is null then l.partner_service_status_id else @partner_service_status_id end and
		(l.insert_date > @start_date or @start_date is null) and
		(l.insert_date < @end_date or @end_date is null)
		
	-- 2.2) update for @company_name
	if @company_name is not null
		begin
		delete from @partner_service_log where company_name <> @company_name or company_name is null
		end
	
	-- 2.2) update for @customer_email
	if @customer_email is not null
		begin
		delete from @partner_service_log where customer_email <> @customer_email or customer_email is null
		end	
	
	-- 2.2) update for @partner_order_code
	if @partner_order_code is not null
		begin
		delete from @partner_service_log where partner_order_code <> @partner_order_code or partner_order_code is null
		end	
	
	-- 2.2) update for @purchase_order
	if @purchase_order is not null
		begin
		delete from @partner_service_log where purchase_order <> @purchase_order or purchase_order is null
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select partner_service_log_id, partner_id, partner_name, partner_service_method_id, partner_service_method_name, partner_service_status_id, partner_service_status_name, insert_date, partner_order_code, purchase_order, company_name, customer_email, l.order_company_type_id, t.order_company_type_name, t.order_company_type_description, keycode
	from @partner_service_log l
	left join order_company_type t
		on l.order_company_type_id = t.order_company_type_id
	where l.order_company_type_id = @order_company_type_id or l.order_company_type_id is null

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_select_child_license]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_service_select_child_license]

(
		@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2015-02-04	esmart		Initial creation.
	2015-11-01	esmart		New activity format
	2016-02-05	esmart		Remove deactive licenses and remove required activity
	2016-07-03	cnovac		updated license_service references for CB changes
	2016-08-10	esmart		Change company_name lookup from license_service_customer to license_service_value
	2016-11-11	acoffel		capability type description
	2017-12-11	esmart		add logging into partner_service_child_license_data_log
	2019-07-02	cnovac		changed out reference to console_activity to fn_license_select_license_activity_sites
	2020-03-09	cnovac		changed where company name is being read from


	DESCRIPTION
	Select child license data from parent
*/

AS
	set nocount on				

	declare @license_id int,
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get license_id
	select @license_id = license_id
	from license
	where keycode = @keycode

	declare @child_license_data table (license_id int, keycode varchar(40), capability_type_description varchar(20), company_name nvarchar(1000), devices int default 0, total_devices int default 0, deactivated_devices int default 0)

	declare @results table (license_id int, keycode varchar(40), capability_type_description varchar(20), company_name nvarchar(1000), devices int default 0, total_devices int default 0, deactivated_devices int default 0, effective_date datetime)

	-- 1.2) select all child licenses
	insert into @child_license_data(license_id, keycode, capability_type_description)
	select l.license_id, l.keycode, t.capability_type_description
	from license_parent lp with (nolock)
	inner join license l with (nolock)
		on lp.child_license_id = l.license_id
	inner join license_summary s
		on l.license_id = s.license_id 
	inner join capability_type t
		on s.capability_type_id = t.capability_type_id
	where lp.parent_license_id = @license_id and l.license_status_id = 1
	

	update @child_license_data
	set company_name = m.mar_name
	from @child_license_data c
	inner join mar_license ml with (nolock)
		on c.license_id = ml.license_id 
	inner join mar m with (nolock)
		on ml.mar_id = m.mar_id
	where m.mar_type_id = 3

	-- 1.3) update company_name where mar_name is blank
	update @child_license_data
	set company_name = lc.license_service_value
	from @child_license_data c
	inner join license_service_value lsv with (nolock)
		on c.keycode = lsv.license_service_value and lsv.license_service_value_type_id = 3
	inner join license_service_value lc with (nolock)
		on lsv.license_service_id = lc.license_service_id and lc.license_service_value_type_id = 11
	where c.company_name = '' or c.company_name is null

	-- 1.4) return result

	-- 1.4.1) @results
	insert into @results(license_id,keycode,capability_type_description,company_name,devices,total_devices,deactivated_devices,effective_date)
	select c.license_id,
			c.keycode, 
			c.capability_type_description,
			isnull(fn.marname, c.company_name),
			isnull(fn.active_devices, 0),
			isnull(fn.total_devices, 0),
			isnull(fn.deactivated_devices, 0),
			getdate()
	from @child_license_data c
	outer apply fn_license_select_license_activity_sites(c.license_id, getdate(), 'saep') 
fn

	-- 1.4.2) partner_service_child_license_data_log
	insert into partner_service_child_license_data_log(parent_license_id,license_id,keycode,capability_type_description,company_name,devices,total_devices,deactivated_devices,effective_date)
	select @license_id,license_id,keycode,capability_type_description,isnull(company_name,'MISSING_SITE_NAME'),devices,total_devices,deactivated_devices,effective_date
	from @results

	-- 1.4.3) result
	select license_id,keycode,capability_type_description,company_name,devices,total_devices,deactivated_devices,effective_date
	from @results
	order by 1


	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
