CREATE PROCEDURE [dbo].[usp_partner_service_select_order_process]

(
	@partner_key varchar(36) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2017-08-22	acoffel		added license values

	DESCRIPTION
	select partner service methods
*/

AS
	set nocount on				

	declare @partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	

	if @partner_key is not null and @partner_key <> ''
	-- 1.1) partner specific methods
		begin
		select @partner_id = partner_id from partner where partner_key = @partner_key

		select o.partner_service_order_process_id, o.order_process_name, o.order_process_description, p.site_id, p.license_attribute_id, p.license_attribute_license_value, v.license_attribute_license_value_description
		from partner_service_order_process o
		inner join partner_service_order_process_partner p
			on o.partner_service_order_process_id = p.partner_service_order_process_id
		left join license_attribute_license_value v
			on p.license_attribute_license_value = v.license_attribute_license_value
		where p.partner_id = @partner_id
		end

	else
	-- 1.2) all order_processs	
		begin
		select o.partner_service_order_process_id, o.order_process_name, o.order_process_description, site_id = null, license_attribute_id = NULL, license_attribute_license_value = NULL, license_attribute_license_value_description = NULL
		from partner_service_order_process o
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
