CREATE PROCEDURE [dbo].[usp_partner_service_select_partner_products]

(
	@partner_key varchar(36),
	@partner_product_id varchar(20) = NULL
)

/*	
	DATE			AUTHOR			REMARKS
	2013-01-07		esmart			Initial creation.
	2017-04-24		acoffel			@partner_product_id input
	2017-08-28		esmart			extend for new cart

	DESCRIPTION
	select partner service products
*/

AS
	set nocount on				

	declare @partner_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @partner_id
	select @partner_id = partner_id from partner where partner_key = @partner_key

	if @partner_product_id is NULL
		begin 
			select pp.partner_service_product_id, pp.site_id, pp.license_attribute_license_value, pp.partner_id, pp.partner_product_id, p.product_id, p.product_description, t.product_type_id, t.product_type_description,p.license_keycode_type_id, lc.license_category_id, lc.license_category_name, y.years
			from partner_service_product pp
			inner join product p
				on pp.product_id = p.product_id
			inner join product_type t
				on p.product_type_id = t.product_type_id
			inner join product_license_category plc
				on plc.product_id = p.product_id
			inner join license_category lc
				on lc.license_category_id = plc.license_category_id
			inner join product_years y
				on y.product_id = p.product_id
			where pp.partner_id = @partner_id
		end
		else 
		begin 
			select pp.partner_service_product_id, pp.site_id, pp.license_attribute_license_value, pp.partner_id, pp.partner_product_id, p.product_id, p.product_description, t.product_type_id, t.product_type_description,p.license_keycode_type_id, lc.license_category_id, lc.license_category_name, y.years
			from partner_service_product pp
			inner join product p
				on pp.product_id = p.product_id
			inner join product_type t
				on p.product_type_id = t.product_type_id
			inner join product_license_category plc
				on plc.product_id = p.product_id
			inner join license_category lc
				on lc.license_category_id = plc.license_category_id
			inner join product_years y
				on y.product_id = p.product_id
			where pp.partner_id = @partner_id and pp.partner_product_id = @partner_product_id
		end
		


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
