CREATE PROCEDURE [dbo].[usp_partner_service_select_pending_orders]

(
	@partner_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-08-26	esmart		Initial creation.

	DESCRIPTION
	select partner service orders without opportunity
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select l.partner_service_log_id, 
			p.partner_id, p.partner_name, 
			m.partner_service_method_id, m.partner_service_method_name,
			o.partner_service_order_id, o.order_header_id, o.partner_order_code, o.partner_order_date, o.purchase_order,
			c.external_account_id, c.first_name, c.last_name, c.company_name, c.customer_email, c.address_1, c.city, c.state, c.postal_code, c.country
	from partner_service_log l
	inner join partner p
		on l.partner_id = p.partner_id
	inner join partner_service_method m
		on l.partner_service_method_id = m.partner_service_method_id
	inner join partner_service_order o
		on l.partner_service_log_id = o.partner_service_log_id
	inner join partner_service_order_customer c
		on o.partner_service_order_id = c.partner_service_order_id and c.order_company_type_id = 1
	left join order_opportunity oo
		on o.order_header_id = oo.order_header_id
	where oo.order_header_id is null
		and l.partner_id = case when @partner_id is null then l.partner_id else @partner_id end
	order by l.partner_service_log_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
