CREATE PROCEDURE [dbo].[usp_partner_service_select_vendor_customer_code]

(
	@vendor_customer_code varchar(36),
	@partner_key varchar(36) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-08-26	esmart		Initial creation.

	DESCRIPTION
	select vendor_order_item
*/

AS
	set nocount on				

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @partner_id = partner_id from partner where partner_key = @partner_key

	select p.partner_id, p.partner_name, p.partner_key, vi.vendor_order_item_id, vi.vendor_order_item_code, i.order_item_id, i.quantity, i.unit_price, i.item_total, i.order_header_id, i.product_id, l.license_id, l.keycode
	from vendor_customer v
	left join partner p
		on p.partner_id = v.partner_id
	left join license l
		on l.customer_id = v.customer_id
	left join order_item_license il
		on l.license_id = il.license_id
	left join order_item i
		on il.order_item_id = i.order_item_id
	left join vendor_order_item vi
		on i.order_item_id = vi.order_item_id
	where v.vendor_customer_code = @vendor_customer_code and
		v.partner_id = case when @partner_id is not null then @partner_id else v.partner_id end

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
