*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select v.vendor_order_item_id, v.vendor_order_item_code, i.order_item_id, i.quantity, i.unit_price, i.item_total, i.order_header_id, i.product_id, l.license_id, l.keycode, s.capability_expiration_date
	from vendor_order_item v
	inner join order_item i
		on i.order_item_id = v.order_item_id
	inner join order_item_license il
		on il.order_item_id = i.order_item_id
	inner join license l
		on l.license_id = il.license_id
	left join license_summary s
		on l.license_id = s.license_id
	where v.vendor_order_item_code = @vendor_order_item_code

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_service_update_log]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_partner_service_update_log]

(
	@partner_service_log_id int,
	@partner_service_status_id tinyint = null,
	@partner_service_method_id tinyint = null,
	@response_code int = null,
	@message varchar(100) = null,
	@license_service_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-07	esmart		Initial creation.
	2016-05-25	esmart		Add license_service_id

	DESCRIPTION
	select partner types
*/

AS
	set nocount on				

	declare @modified_date datetime

	begin try

	select @modified_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) insert audit
	insert into partner_service_log_audit(partner_service_log_id, partner_id, partner_account_id, partner_service_method_id, partner_service_status_id, insert_date, modified_date, audit_date)
	select partner_service_log_id, partner_id, partner_account_id, partner_service_method_id, partner_service_status_id, insert_date, modified_date, @modified_date
	from partner_service_log
	where partner_service_log_id = @partner_service_log_id

	if @partner_service_status_id = 3
		begin
		insert into partner_service_log_failure(partner_service_log_id, partner_id, partner_account_id, partner_service_method_id, partner_service_status_id, insert_date, modified_date, response_code, message)
		select partner_service_log_id, partner_id, partner_account_id, partner_service_method_id, partner_service_status_id, insert_date, @modified_date, @response_code, @message
		from partner_service_log
		where partner_service_log_id = @partner_service_log_id
		end

	-- 1.2) update partner_service_log
	update partner_service_log
	set partner_service_status_id = case when @partner_service_status_id is null then l.partner_service_status_id else @partner_service_status_id end,
		partner_service_method_id = case when @partner_service_method_id is null then l.partner_service_method_id else @partner_service_method_id end,
		modified_date = @modified_date,
		license_service_id = case when @license_service_id is null then l.license_service_id else @license_service_id end
	from partner_service_log l
	where partner_service_log_id = @partner_service_log_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_update_order_pricing]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_update_order_pricing]

( 
	@order_header_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2021-04-05	esmart		Initial creation.
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
	DESCRIPTION
	Update order pricing based on new item data
*/

AS

	declare @response_code int,
			@message varchar(100)
			

begin try

	set nocount on

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) order_item_audit
	insert into order_item_audit (order_item_id, order_header_id, line_item,product_id, quantity, list_price, unit_price,tax, order_item_offer_id,order_item_offer_amount, item_total, tax_exempt,effective_date, order_item_status_id,insert_date, insert_by, modified_date,modified_by, capability_expiration_date,item_bundle_id, order_item_update_type_id,audit_date, sap_material_number)
	select order_item_id, order_header_id, line_item,product_id, quantity, list_price, unit_price,tax, order_item_offer_id,order_item_offer_amount, item_total, tax_exempt,effective_date, order_item_status_id,insert_date, insert_by, modified_date,modified_by, capability_expiration_date,item_bundle_id, order_item_update_type_id,getdate(), sap_material_number
	from order_item 
	where order_header_id = @order_header_id

	-- 1.2) update order_item
	update i
	set --i.unit_price = f.retail_price, item_total = i.quantity * f.retail_price
		list_price = case
						-- when t.pricing_term = 'monthly' then f.retail_price
						when f.pricing_term = 'annual' and p.product_type_id in (1,2) then round(f.retail_price * (convert(float, datediff(dd,i.effective_date,i.capability_expiration_date) - dbo.fn_leap_days_between(i.effective_date, i.capability_expiration_date))/365.0),2)
						when f.pricing_term = 'annual' and p.product_type_id in (3) then round(f.retail_price * (convert(float, datediff(dd,i.effective_date,i.capability_expiration_date))/365.0),2)
						else i.list_price
					end, 
		unit_price = case
							-- when t.pricing_term = 'monthly' then f.retail_price
							when f.pricing_term = 'annual' and p.product_type_id in (1,2) then round(f.retail_price * (convert(float, datediff(dd,i.effective_date,i.capability_expiration_date) - dbo.fn_leap_days_between(i.effective_date, i.capability_expiration_date))/365.0),2)
							when f.pricing_term = 'annual' and p.product_type_id in (3) then round(f.retail_price * (convert(float, datediff(dd,i.effective_date,i.capability_expiration_date))/365.0),2)
							else i.unit_price
						end
	from order_item i
	inner join product p
		on i.product_id = p.product_id
	left join product_extension e
		on e.product_id = p.product_id
	inner join product_years y
		on y.product_id = p.product_id
	outer apply fn_product_select_product_extension(e.product_extension_json) pe
	inner join product_license_category plc
		on plc.product_id = i.product_id
	inner join order_item_license il
		on il.order_item_id = i.order_item_id
	inner join order_header h
		on h.order_header_id = i.order_header_id
	inner join order_currency oc
		on oc.order_header_id = h.order_header_id
	inner join vendor_order v
		on v.vendor_order_id = h.vendor_order_id
	inner join partner_order po
		on po.order_header_id = h.order_header_id
	left join order_item_json j
		on j.order_item_id = i.order_item_id
	left join license_attribute_license_value la
		on json_value(j.order_item_json,'$.license_attribute_license_value') = la.license_attrib
ute_license_value
	left join license_seat_history sh
		on il.license_id = sh.license_id and i.order_item_id = sh.order_item_id and sh.license_change_reason_id not in (2,14)
	outer apply fn_partner_select_pricing(po.partner_id,h.site_id,plc.license_category_id,la.license_attribute_id,i.quantity,case
												when p.product_type_id = 3 and datediff(dd,i.effective_date,i.capability_expiration_date) <= 365 then 1
												when p.product_type_id = 3 and datediff(dd,i.effective_date,i.capability_expiration_date) > 365 and datediff(dd,i.effective_date,i.capability_expiration_date) <= 730 then 2
												when p.product_type_id = 3 and datediff(dd,i.effective_date,i.capability_expiration_date) > 730 then 3
												else y.years
											end,'annual',isnull(json_value(j.order_item_json,'$.product_pricing_level_id'),1),oc.currency_id,pe.usage_pricing_model_id,pe.retention_model_id,pe.product_platform_id,'active') f
	where i.order_header_id in (@order_header_id)

		-- 1.2.1) item_total
		update order_item
		set item_total = quantity * unit_price
		where order_header_id in (@order_header_id)

	-- 1.3) order_header_audit
	insert into order_header_audit (order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, audit_date)
	select order_header_id, vendor_order_id,order_offer_id, order_offer_amount,total_amount, sub_total_amount, tax_total,payment_method_id, session_id,vendor_order_date, locale, exchange_rate,site_id, site_url, order_status_id,insert_date, insert_by, modified_date,modified_by, fee_total,download_instruction_type_id, getdate()
	from order_header
	where order_header_id = @order_header_id

	-- 1.4) update order_header totals
	update h1
	set sub_total_amount = x.sub_total_amount, total_amount = x.total_amount
	from order_header h1
	inner join (select h.order_header_id, sub_total_amount = sum(i.item_total), total_amount = sum(i.item_total)
			from order_header h 
			inner join order_item i
				on i.order_header_id = h.order_header_id
			where h.order_header_id = @order_header_id
			group by h.order_header_id) x
		on x.order_header_id = h1.order_header_id


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_update_partner_billing_report]
-- =============================================================================
-- Stored Procedure

CREATE PROCEDURE [dbo].[usp_partner_update_partner_billing_report]

(
		@partner_billing_report_id int,
		@partner_billing_status_id tinyint,
		@modified_by varchar(20)
)

/*	
	DATE			AUTHOR			REMARKS
    2016-06-14      esmart          Initial creation
    2020-09-22      esmart          Add partner_billing_order and insert into sfdc_opportunity_update
    2022-03-09      g.lagos         Correcting wrong question below where it said  "po.partner_billing_order_id = @partner_billing_report_id"
                                    it says now: "po.partner_billing_report_id = @partner_billing_report_id"

	DESCRIPTION
	update partner billing report
*/

as

	set nocount on	

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) update partner_billing_report
	update partner_billing_report
	set partner_billing_status_id = @partner_billing_status_id, modified_date = getdate(), modified_by = @modified_by
	where partner_billing_report_id = @partner_billing_report_id

	-- 1.2) partner_billing_order
	if @partner_billing_status_id = 2
		begin

		if not exists (select po.order_header_id from partner_billing_order po where po.partner_billing_report_id = @partner_billing_report_id) -- This was WRONG
			begin

			-- 1.2.1) usp_partner_insert_partner_billing_order
			exec usp_partner_insert_partner_billing_order @partner_billing_report_id

			-- 1.2.2) sfdc_opportunity_update
			insert into sfdc_opportunity_update (order_header_id, sfdc_template_id, sfdc_update_type_id,process_date) 
			select po.order_header_id, 17, 115, getdate()
			from partner_billing_order po
			where po.partner_billing_report_id = @partner_billing_report_id

			end

		end		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_update_partner_billing_usage_override]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_partner_update_partner_billing_usage_override]

(
	@partner_billing_report_id int, 
	@license_category_id tinyint
)

/*	
	DATE		AUTHOR		REMARKS
	2020-11-02	esmart		Initial creation.

	DESCRIPTION
	update partner_billing with override usage
*/

AS

	declare @partner_billing_status_id tinyint,
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update partner_billing
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @usage_update as table (keycode varchar(40), license_category_id tinyint, usage_seats int)

	insert into @usage_update(keycode, license_category_id, usage_seats)
	select o.parent_keycode, o.license_category_id, sum(o.usage_seats) as usage_seats
	from partner_billing_usage_override o
	where o.partner_billing_report_id = @partner_billing_report_id and o.license_category_id = @license_category_id
	group by o.parent_keycode, o.license_category_id

	insert into partner_billing_audit(partner_billing_id, partner_billing_report_id, customer_id, customer_code, company_name, location_code, state, webroot_entity, reseller_customer_id, reseller_customer_code, reseller_company_name, reseller_location_code,reseller_state, license_id, keycode, keycode_age, order_header_id, order_date, product_id, license_category_id,license_seats, retail_price, extended_amount, usage_seats, usage_price, usage_extended_amount, total_extended_amount,cap_amount, last_modified_date, license_attribute_license_value, total_cap_amount, currency_id,partner_pricing_model_id, total_seats, audit_date, company_id)
	select b.partner_billing_id, b.partner_billing_report_id, b.customer_id, b.customer_code, b.company_name, b.location_code, b.state, b.webroot_entity, b.reseller_customer_id, b.reseller_customer_code, b.reseller_company_name, b.reseller_location_code,reseller_state, b.license_id, b.keycode, b.keycode_age, b.order_header_id, b.order_date, b.product_id, b.license_category_id,license_seats, b.retail_price, b.extended_amount, b.usage_seats, b.usage_price, b.usage_extended_amount, b.total_extended_amount,cap_amount, b.last_modified_date, b.license_attribute_license_value, b.total_cap_amount, b.currency_id,partner_pricing_model_id, b.total_seats, getdate() as audit_date, b.company_id
	from partner_billing b
	inner join @usage_update u
		on u.keycode = b.keycode and u.license_category_id = b.license_category_id
	where b.partner_billing_report_id = @partner_billing_report_id and b.usage_seats <> u.usage_seats

	update b
	set b.usage_seats = u.usage_seats,
		b.usage_extended_amount = u.usage_seats * b.usage_price,
		b.total_seats = u.usage_seats,
		b.total_extended_amount = u.usage_seats * b.usage_price,
		b.last_modified_date = getdate()
	from partner_billing b
	inner join @usage_update u
		on u.keycode = b.keycode and u.license_category_id = b.license_category_id
	where b.partner_billing_report_id = @partner_billing_report_id and b.usage_seats <> u.usage_seats

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update partner_billing_report_override
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @partner_billing_status_id = 8

	-- 2.1)
	update r
	set r.partner_bil
ling_status_id = @partner_billing_status_id, r.modified_date = getdate()
	from partner_billing_report_override r
	where r.partner_billing_report_id = @partner_billing_report_id and r.license_category_id = @license_category_id

		-- 2.1.1) if all overrides are complete update report to pending
		if (select count(*) from partner_billing_report_override r where r.partner_billing_report_id = @partner_billing_report_id and r.partner_billing_status_id <> @partner_billing_status_id) = 0
			begin
			
			select @partner_billing_status_id = 1

			update r
			set r.partner_billing_status_id = @partner_billing_status_id, r.modified_date = getdate(), r.modified_by = 'override_process'
			from partner_billing_report r
			where partner_billing_report_id = @partner_billing_report_id
			end


end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_update_partner_license_attribute]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_partner_update_partner_license_attribute]

(
			@partner_license_attribute_id int = null,
			@partner_id int,
			@site_id varchar(20),
			@license_category_id int,
			@license_attribute_id int,
			@license_attribute_license_value int,
			@partner_pricing_model_id tinyint, 
			@last_modified_by varchar(20) = null,
			@delete tinyint = 0
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-02-23		esmart			Initial creation
	
	DESCRIPTION
	insert partner_license_attribute
*/

as

	set nocount on			

	declare	@last_modifed_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

	begin try

	if @last_modified_by is null
		begin
		select @last_modified_by = suser_sname()
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @partner_license_attribute_id
	if @partner_license_attribute_id is null
		begin
			select @partner_license_attribute_id = partner_license_attribute_id
			from partner_license_attribute
			where partner_id = @partner_id and 
					site_id = @site_id and 
					license_category_id = @license_category_id and
					license_attribute_id = @license_attribute_id and 
					license_attribute_license_value = @license_attribute_license_value
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert
	if @partner_license_attribute_id is null
		begin
		insert into partner_license_attribute(partner_id,site_id,license_category_id,license_attribute_id,license_attribute_license_value,partner_pricing_model_id,last_modified_by)
		values(@partner_id,@site_id,@license_category_id,@license_attribute_id,@license_attribute_license_value,@partner_pricing_model_id,@last_modified_by)
		end

	-- 2.2) update
	if @partner_license_attribute_id is not null and @delete = 0
		begin
		update partner_license_attribute
		set license_attribute_license_value = @license_attribute_license_value, partner_pricing_model_id = @partner_pricing_model_id, last_modified_date = @last_modifed_date, last_modified_by = @last_modified_by
		where partner_license_attribute_id = @partner_license_attribute_id
		end

	-- 2.3) delete
	if @partner_license_attribute_id is not null and @delete = 1
		begin
		delete from partner_license_attribute where partner_license_attribute_id = @partner_license_attribute_id
		end
		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_partner_update_partner_license_transaction]
-- =============================================================================

CREATE    PROCEDURE [dbo].[usp_partner_update_partner_license_transaction] 
(
	@partner_license_id INT,
	@partner_license_status_id TINYINT,
	@last_modified_user_id VARCHAR(20) = NULL,
	@effective_date_override DATETIME = NULL
)


/*	
	DATE		AUTHOR		REMARKS
	2015-07-30	esmart		Initial creation.
	2015-10-20	esmart		Support Archive status
	2016-03-22	esmart		Add child license updates
	2016-04-15	esmart		Support for more than one transaction
	2016-06-16	esmart		Add time-phased approved partner_license
	2016-12-21	acoffel		effective date override
	2017-06-09	esmart		Fix bug with @partner_license_effective_date on CSI updates
	2017-08-22	esmart		Add new procedure usp_cart_update_order_license_new
	2017-11-07	esmart		Add new procedure usp_license_service_update_license
	2018-05-10	cnovac		Added @order_item_id to sp calls for attribute and cycle
	2018-08-07	rvinoche	archive partner_license_status for partner_licenses approved same day
	2019-01-20	rvinoche	Fix subquery bug in 2.3)
	2019-05-20	esmart		Flag order_header as refunded when declined.
	2019-06-07	rvinoche	Resume sfdc_opportunity_update if previously interrupted 3.5	
	2019-06-13	abelenkiy	Added support for new license_usage_pricing insert in 3.9
	2019-07-12	rvinoche	Re-create future license_message when license transfered on same day as billing
	2019-07-19	rvinoche	Delete @allow_code_update and reset variables in approval loop
	2019-09-06	cnovac		Updated code to remove @allow_past_record_update variable and always allow that code to fire
	2022-01-16	rvinoche	Add logic for pax8 to record license categories which have usage and were poached from other partners
	2024-04-23	vsingh8		ECOM-4257, queue SAP update for SFDC orders which have been approved for billing entity approval.
	2024-05-09	gblandford	https://jira.opentext.com/browse/ECOM-4416 - create a sky_update for 'MSPPartnerMigrate' if we are approving the migration of a license to Zix.
							- https://confluence.opentext.com/display/UGUS/MSPPartnerMigrate
							- get ZIX_PARTNER_ID from configuration
							- minor indentation changes for readability
							- added schema to objects
	2024-06-14	gblandford	https://jira.opentext.com/browse/ECOM-4765 - defect
							- in zix migration logic, was not using license_id to check for previous partner id
							- handle a NULL return for previous partner id (in the case of ZIX renewing an online cart order where no partner existed)

	DESCRIPTION
	Inserts/updates a partner_license. This procedure is called whenever there is a change of partner on a license.

	This procedure is called directly from PHP
*/

AS
    SET NOCOUNT ON;

    DECLARE @current_partner_license_status_id TINYINT,
			@license_transaction VARCHAR(MAX),
			@product_id INT,
			@keycode VARCHAR(40),
			@order_type_group_id INT,
			@order_item_id INT,
			@effective_date DATETIME,
			@partner_license_effective_date DATETIME,
			@license_id INT,
			@days INT,
			@modified_by VARCHAR(20) = 'partner_license',
			@procedure VARCHAR(100),
			@last_modified_date DATETIME,
			@parent_license_id INT,
			@child_license_id INT,
			@license_attribute_id INT, 
			@license_attribute_license_value INT,
			@partner_license_transaction_id INT,
			@order_header_id INT,
			@message_autorenewal_cycle_id TINYINT,
			@billing_day_of_month TINYINT,
			@product_type_id TINYINT,
			@vendor_order_code VARCHAR(100),
			@license_service_id INT,
			@usage_price MONEY,
			@license_message_cancel INT,
			@partner_id INT,
			@response_code INT,
			@message VARCHAR(100),
			@SFDC_ORDER_HEADER_SITE_ID VARCHAR(20),
			@previous_partner_id INT,
			@parent_keycode VARCHAR(40),
			@sky_update_json VARCHAR(MAX),
			@sky_template_id INT;


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 0.) get configuration values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	DECLARE @ZIX_PARTNER_ID INT

	-- 0.1) Zix partner_id
	SELECT 
		@ZIX_PARTNER_ID = cfg.[key]
	FROM [dbo].[fn_app_config_select_key_values] (	'ZIX_PARTNER', 'ZIX_MIGRATION' ) cfg;

	-- 0.2) Get sky template
	SELECT
		@sky_template_id = st.sky_template_id
	FROM dbo.sky_template st
	WHERE st.sky_template_name = 'msp_migration'


    BEGIN TRY

        SELECT
            @last_modified_date = GETDATE();


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) @last_modified_user_id
		IF @last_modified_user_id IS NULL 
			BEGIN
			SELECT @last_modified_user_id = SUSER_SNAME()
			END

		-- 1.2) @partner_license_status_id
		SELECT @current_partner_license_status_id = partner_license_status_id, @order_header_id = order_header_id, @license_id = license_id
		FROM dbo.partner_license
		WHERE partner_license_id = @partner_license_id

		IF @current_partner_license_status_id <> 1
			BEGIN
			SELECT @response_code = -120, @message = 'Transaction processing allowed on pending transactions only'
			SELECT response_code = @response_code, message = @message
			RETURN
			END

        -- 1.3) @SFDC_ORDER_HEADER_SITE_ID
        SELECT
            @SFDC_ORDER_HEADER_SITE_ID = [key]
        FROM dbo.fn_app_config_select_key_values('ORDER_HEADER_SITE_ID', 'SFDC');

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 2.) Declined - no license update
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        IF @partner_license_status_id = 3
            BEGIN

                -- 2.1) update partner_license
                INSERT INTO dbo.partner_license_audit (
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                )
                SELECT
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                FROM dbo.partner_license
                WHERE license_id = @license_id;

                UPDATE dbo.partner_license
					SET
						partner_license_status_id = @partner_license_status_id,
						last_modified_user_id = @last_modified_user_id,
						last_modified_date = @last_modified_date
				WHERE partner_license_id = @partner_licens
e_id;

                -- 2.2) update partner_license_transaction
                UPDATE dbo.partner_license_transaction
					SET
						partner_license_status_id = @partner_license_status_id,
						last_modified_date = @last_modified_date
                WHERE partner_license_id = @partner_license_id;

                -- 2.3) license service archive
                IF EXISTS ( SELECT
								1
							FROM dbo.partner_license_transaction
							WHERE partner_license_id = @partner_license_id
								AND partner_license_transaction_procedure_id = 6
					) BEGIN

							-- 2.3.1) 
							SELECT
								@license_service_id = JSON_VALUE(t.license_transaction, '$.license_service_id')
							FROM dbo.partner_license_transaction t
							WHERE t.partner_license_id = @partner_license_id
								AND t.partner_license_transaction_procedure_id = 6;

							-- 2.3.2) archive
							INSERT INTO dbo.license_service_archive (
								license_service_id,
								license_service_type_id,
								license_service_status_id,
								insert_date
							)
							SELECT
								license_service_id,
								license_service_type_id,
								license_service_status_id = 4,
								insert_date
							FROM dbo.license_service
							WHERE license_service_id = @license_service_id;

							-- 2.3.3) delete service record
							DELETE 
							FROM dbo.license_service
							WHERE license_service_id = @license_service_id;

						END;

                -- 2.4) update order status
                INSERT INTO dbo.order_header_audit (
                    order_header_id,
                    vendor_order_id,
                    order_offer_id,
                    order_offer_amount,
                    total_amount,
                    sub_total_amount,
                    tax_total,
                    payment_method_id,
                    session_id,
                    vendor_order_date,
                    locale,
                    exchange_rate,
                    site_id,
                    site_url,
                    order_status_id,
                    insert_date,
                    insert_by,
                    modified_date,
                    modified_by,
                    fee_total,
                    download_instruction_type_id,
                    audit_date
                )
				SELECT 
					order_header_id,
					vendor_order_id,
					order_offer_id,
					order_offer_amount,
					total_amount,
					sub_total_amount,
					tax_total,
					payment_method_id,
					session_id,
					vendor_order_date,
					locale,
					exchange_rate,
					site_id,
					site_url,
					order_status_id,
					insert_date,
					insert_by,
					modified_date,
					modified_by,
					fee_total,
					download_instruction_type_id,
					GETDATE() AS audit_date
				FROM dbo.order_header
				WHERE order_header_id = @order_header_id;

                UPDATE dbo.order_header
					SET
						order_status_id = 3,
						modified_date = @last_modified_date,
						modified_by = @last_modified_user_id
                WHERE order_header_id = @order_header_id;

                -- 2.4.1) delete pending sfdc_opportunity_update records
                INSERT INTO dbo.sfdc_opportunity_update_archive (
					sfdc_opportunity_update_id,
					order_header_id,
					trial_id,
					sfdc_template_id,
					sfdc_update_type_id,
					sfdc_update_status_id,
					update_attempts,
					sfdc_response_code,
					sfdc_response_message,
					insert_date,
					process_date,
					modified_date,
					archive_date,
					form_submit_id,
					license_id
				)
				SELECT
					sfdc_opportunity_update_id,
					order_header_id,
					trial_id,
					sfdc_template_id,
					sfdc_update_type_id,
					sfdc_update_status_id,
					update_attempts,
					sfdc_response_code,
					sfdc_response_message,
					insert_date,
					process_date,
					modified_date,
					@last_modified_date,
					for
m_submit_id,
					license_id
				FROM dbo.sfdc_opportunity_update
				WHERE order_header_id = @order_header_id
					AND sfdc_template_id = 4
					AND sfdc_update_status_id = 4;

                DELETE 
				FROM dbo.sfdc_opportunity_update
                WHERE order_header_id = @order_header_id
                    AND sfdc_template_id = 4
                    AND sfdc_update_status_id = 4;

                -- 2.5) return
                SELECT
                    response_code = 200,
                    message = 'Completed partner license decline';
                RETURN;
            END;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 3.) Approved - update partner_license_transaction
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        IF @partner_license_status_id = 2 BEGIN

                -- 3.1) @effective_date_override
                IF @effective_date_override IS NOT NULL BEGIN

                        UPDATE i
							SET i.effective_date = @effective_date_override
                        FROM dbo.order_item    i
                            INNER JOIN dbo.order_header  h
								ON i.order_header_id = h.order_header_id
                            INNER JOIN dbo.product       p
                                ON i.product_id = p.product_id
                            INNER JOIN dbo.product_years y
                                ON p.product_id = y.product_id
                        WHERE h.order_header_id = @order_header_id;

                    END;

                -- 3.2) loop through pending transactions		
                DECLARE @transactions TABLE (
                    temp_id INT IDENTITY(1, 1),
                    partner_license_transaction_id INT,
                    license_transaction VARCHAR(MAX)
                );

                INSERT INTO @transactions (
                    partner_license_transaction_id,
                    license_transaction
                )
                SELECT
                    partner_license_transaction_id,
                    license_transaction
                FROM dbo.partner_license_transaction
                WHERE partner_license_id = @partner_license_id
                ORDER BY partner_license_transaction_id;

                DECLARE @transaction_data TABLE (
                    parameter_name  VARCHAR(100),
                    parameter_value NVARCHAR(100)
                );
                DECLARE @temp_id INT,
                    @total_ids INT;

                SELECT @temp_id   = 1,
                    @total_ids = COUNT(*)
                FROM @transactions;

                WHILE @total_ids >= @temp_id BEGIN

						-- 3.1) @license_transaction
						SELECT
							@partner_license_transaction_id = partner_license_transaction_id,
							@license_transaction = license_transaction
						FROM @transactions
						WHERE temp_id = @temp_id;

                        INSERT INTO @transaction_data (
                            parameter_name,
                            parameter_value
                        )
						SELECT
                            [Key],
                            Value
                        FROM OPENJSON(@license_transaction);

                        -- 3.2) get procedure to process
                        SELECT
                            @procedure = parameter_value
                        FROM @transaction_data
                        WHERE parameter_name = 'procedure';

                        -- 3.3) usp_license_update_license_capability_load
                        IF @procedure = 'usp_license_update_license_capabilit
y_load' BEGIN

                                -- 3.3.1) get inputs and update
                                SELECT
                                    @product_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'product_id';

                                SELECT
                                    @keycode = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'keycode';

                                SELECT
                                    @order_type_group_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'order_type_group_id';

                                SELECT
                                    @order_item_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'order_item_id';

                                EXECUTE dbo.usp_license_update_license_capability_load
                                    @product_id,
                                    @keycode,
                                    @order_type_group_id,
                                    @order_item_id,
                                    @effective_date OUTPUT,
                                    @license_id OUTPUT,
                                    @response_code OUTPUT,
                                    @message OUTPUT;

                                -- 3.3.2) parent update
                                IF ( SELECT
                                        license_type_id
									FROM dbo.license
                                    WHERE keycode = @keycode ) = 2 BEGIN
                                        SELECT
                                            @parent_license_id = license_id
                                        FROM dbo.license
                                        WHERE keycode = @keycode;

                                        EXECUTE dbo.usp_license_update_child_licenses
                                            @parent_license_id,
                                            @order_item_id,
                                            @child_license_id;
                                    END;

                                IF @partner_license_effective_date IS NULL BEGIN
                                        SELECT
                                            @partner_license_effective_date = @effective_date;
                                    END;
                            END;

                        -- 3.4) usp_license_update_license_capability_CSI			
						IF @procedure = 'usp_license_update_license_capability_CSI' BEGIN

								-- 3.4.1) get inputs and update
								SELECT 
									@days = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'days';
							
								SELECT 
									@keycode = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'keycode';

								EXECUTE dbo.usp_license_update_license_capability_CSI 
									@days,
									@keycode,
									@modified_by,
									NULL,
									@response_code OUTPUT,
									@message OUTPUT;

								-- 3.4.2) parent update
								IF ( SELECT 
										license_type_id 
									FROM dbo.license 
									WHERE keycode = @keycode ) = 2 BEGIN
										SELECT 
											@parent_license_id = license_id
										FROM dbo.license
										WHERE keycode = @keycode;

										EXECUTE dbo.usp_license_update_child_licenses 
											@parent_license_id,
											@order_item_id,
											@child_license_id;
									END;
							END;

                        -- 3.5) usp_cart_update_order_license_new																					
                        IF @procedure = 'usp_cart_update_order_license_new' B
EGIN

                                -- 3.5.1) get inputs and update
                                SELECT
                                    @vendor_order_code = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'vendor_order_code';

                                EXECUTE dbo.usp_cart_update_order_license_new
                                    @vendor_order_code,
                                    @partner_license_status_id;
                            END;

                        -- 3.6) usp_license_service_update_license																					
                        IF @procedure = 'usp_license_service_update_license'

                            BEGIN
                                -- 3.6.1) get inputs and update
                                SELECT
                                    @license_service_id = parameter_value
                                FROM
                                    @transaction_data
                                WHERE parameter_name = 'license_service_id';

                                EXECUTE dbo.usp_license_service_update_license
                                    @license_service_id,
                                    @partner_license_status_id;
                            END;


                        -- 3.7) usp_license_update_license_attribute_license																					
                        IF @procedure = 'usp_license_update_license_attribute_license' BEGIN

                                -- 3.7.1) get inputs and update
								SELECT 
									@license_id = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'license_id';
								
								SELECT 
									@license_attribute_id = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'license_attribute_id';
								
								SELECT 
									@license_attribute_license_value = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'license_attribute_license_value';
								
								SELECT 
									@effective_date = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'effective_date';
								
								SELECT 
									@order_header_id = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'order_header_id';
								
								SELECT 
									@order_item_id = parameter_value
								FROM @transaction_data
								WHERE parameter_name = 'order_item_id';

                                -- 3.7.2) @effective_date_override
                                IF @effective_date_override IS NOT NULL BEGIN
                                        SELECT
                                            @effective_date = @effective_date_override;
                                    END;

                                SELECT
                                    @partner_license_effective_date = @effective_date;

                                EXECUTE dbo.usp_license_update_license_attribute_license
                                    @license_id,
                                    @license_attribute_id,
                                    @license_attribute_license_value,
                                    @modified_by,
                                    @effective_date,
                                    @order_header_id,
                                    @partner_license_status_id,
                                    @order_item_id = @order_item_id;

                            END;

                        -- 3.8) usp_license_update_license_attribute_license																					
                        IF @procedure = 'usp_license_update_license_autorenewal_cycle' BEGIN

                                -- 3.8.1) get inputs and update
                                SELECT
                                    @license_id = parameter_value
      
                          FROM @transaction_data
                                WHERE parameter_name = 'license_id';

                                SELECT
                                    @message_autorenewal_cycle_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'message_autorenewal_cycle_id';
                                
								SELECT
                                    @billing_day_of_month = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'billing_day_of_month';
                                
								SELECT
                                    @effective_date = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'effective_date';
                                
								SELECT
                                    @order_header_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'order_header_id';
                                
								SELECT
                                    @order_item_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'order_item_id';

                                -- 3.8.2) @effective_date_override
                                IF @effective_date_override IS NOT NULL BEGIN
                                        SELECT
                                            @effective_date = @effective_date_override;
                                    END;

                                SELECT
                                    @partner_license_effective_date = @effective_date;

                                EXECUTE dbo.usp_license_update_license_autorenewal_cycle
                                    @license_id,
                                    @message_autorenewal_cycle_id,
                                    @billing_day_of_month,
                                    @product_type_id,
                                    @effective_date,
                                    @order_header_id,
                                    @partner_license_status_id,
                                    @order_item_id;

                            END;

                        -- 3.9) usp_license_insert_license_usage_pricing
                        IF @procedure = 'usp_license_insert_license_usage_pricing' BEGIN

                                -- 3.9.1) get inputs and update
                                SELECT
                                    @license_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'license_id';

                                SELECT
                                    @effective_date = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'effective_date';

                                SELECT
                                    @order_item_id = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'order_item_id';

                                SELECT
                                    @usage_price = parameter_value
                                FROM @transaction_data
                                WHERE parameter_name = 'usage_price';

                                -- 3.9.2) @effective_date_override
                                IF @effective_date_override IS NOT NULL
                                    BEGIN
                                        SELECT
                                            @effective_date = @effective_date_override;
                                    E
ND;

                                SELECT
                                    @partner_license_effective_date = @effective_date;

                                EXECUTE dbo.usp_license_insert_license_usage_pricing
                                    @license_id,
                                    @order_item_id,
                                    @effective_date,
                                    @usage_price,
                                    @partner_license_status_id;
                            END;

                        -- 3.10) update partner_license_transaction
                        UPDATE dbo.partner_license_transaction
							SET partner_license_status_id = @partner_license_status_id,
								last_modified_date = @last_modified_date
                        WHERE partner_license_transaction_id = @partner_license_transaction_id;

                        -- 3.11) clean up variables
                        SELECT
                            @effective_date = NULL,
                            @partner_license_transaction_id = NULL,
                            @license_transaction = NULL,
                            @procedure = NULL,
                            @keycode = NULL;

                        DELETE 
						FROM @transaction_data;

                        SELECT
                            @temp_id = @temp_id + 1;

                    END; --end of while loop

                -- 3.3) finish opportunity and oracle contract if previously interrupted
                UPDATE dbo.sfdc_opportunity_update
					SET sfdc_update_status_id = 0,
						process_date = @last_modified_date
                WHERE order_header_id = @order_header_id
                    AND sfdc_template_id = 4
                    AND sfdc_update_status_id = 4;

                IF EXISTS ( SELECT 1
							FROM dbo.order_header
							WHERE order_header_id = @order_header_id
								AND site_id = @SFDC_ORDER_HEADER_SITE_ID ) BEGIN
                        EXECUTE dbo.usp_sap_insert_sap_order
                            @order_header_id = @order_header_id;
                    END;

                -- 3.4) re-process license_message if approval date is today
                IF CAST(@effective_date_override AS DATE) = CAST(@last_modified_date AS DATE) -- checking for same day approval as billing day
                   AND EXISTS
                    (
                        SELECT
                            1
                        FROM
                            dbo.license_message lm
                        WHERE
                            lm.license_id = @license_id
                            AND lm.message_status_id = 3
                            AND lm.message_type_id = 10
                            AND CAST(lm.process_date AS DATE) = CAST(@last_modified_date AS DATE)
                    ) -- checking to see if license_message for today has already been processed
                    BEGIN

                        SELECT
                            @license_message_cancel = license_message_id -- checks for autobilling license_message with future approved date
                        FROM dbo.license_message
                        WHERE license_id = @license_id
                            AND message_status_id = 1
                            AND message_type_id = 10
                            AND CAST(process_date AS DATE) > CAST(@last_modified_date AS DATE);

                        IF @license_message_cancel IS NOT NULL BEGIN -- delete future approved process date and re-create license_message

                                DELETE 
								FROM dbo.license_message
                                WHERE license_message_id = @license_message_cancel;

                                DECLARE @license_message_table TABLE (
                                    license_message_id  INT,
                                    license_message_key VARCHAR(36)
 
                               );

                                INSERT INTO @license_message_table (
                                    license_message_id,
                                    license_message_key
                                ) -- this is done to prevent the results from usp_message_insert_license_message (sub-routine) from displaying when calling this proc
                                EXECUTE dbo.usp_message_update_license_message_autobilling
                                    @license_id = @license_id;
                            END;
                    END;


                -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                -- 4.) Approved - update partner_license
                -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                IF @partner_license_effective_date IS NULL
                    BEGIN
                        SELECT
                            @partner_license_effective_date = @effective_date_override;
                    END;

                -- 4.1) update partner_license
                INSERT INTO dbo.partner_license_audit (
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                )
                SELECT
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                FROM dbo.partner_license
                WHERE partner_license_id = @partner_license_id;

                UPDATE dbo.partner_license
					SET
						partner_license_status_id = @partner_license_status_id,
						last_modified_user_id = @last_modified_user_id,
						last_modified_date = @last_modified_date,
						start_date = @partner_license_effective_date
                WHERE partner_license_id = @partner_license_id;

                -- 4.2) mark previously approved partner_license as archive
                INSERT INTO dbo.partner_license_audit (
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                )
                SELECT
                    pl.partner_license_id,
                    pl.license_id,
                    pl.partner_id,
                    pl.partner_license_status_id,
                    pl.partner_license_source_id,
                    pl.last_modified_user_id,
                    pl.last_modified_date,
                    pl.insert_date,
                    pl.start_date,
                    pl.end_date,
                    pl.order_header_id
                FROM dbo.partner_license pl
                    INNER JOIN dbo.partner_license pl2
						ON pl.license_id = pl2.license_id
                WHERE pl.
partner_license_status_id = 2
					AND pl2.partner_license_id = @partner_license_id
					AND pl.partner_license_id <> @partner_license_id
					AND pl.end_date IS NULL;

                UPDATE pl SET 
					pl.last_modified_user_id = @last_modified_user_id,
					pl.last_modified_date = @last_modified_date,
					pl.end_date = @partner_license_effective_date,
					pl.partner_license_status_id = CASE
                                                        WHEN CAST(pl.start_date AS DATE) = CAST(@partner_license_effective_date AS DATE)
                                                            THEN
                                                            4
                                                        ELSE
                                                            pl.partner_license_status_id
                                                    END -- if the previously approved partner_license records were approved the same day, the record should no longer be approved
                FROM dbo.partner_license pl
                    INNER JOIN dbo.partner_license pl2
						ON pl.license_id = pl2.license_id
                WHERE pl.partner_license_status_id = 2
                    AND pl2.partner_license_id = @partner_license_id
                    AND pl.partner_license_id <> @partner_license_id
                    AND pl.end_date IS NULL;

				-- 4.2.1) send a sky_update if we are migrating license to Zix
				SELECT 
					@partner_id = pl.partner_id,
					@parent_keycode = l.keycode				
				FROM dbo.partner_license pl
					INNER JOIN dbo.license l
						ON l.license_id = pl.license_id
				WHERE pl.partner_license_id = @partner_license_id

				IF @partner_id = @ZIX_PARTNER_ID BEGIN

						-- determine if this is a switch of partner
						SELECT TOP 1 
							@previous_partner_id = pl.partner_id
						FROM dbo.partner_license pl 
						WHERE pl.partner_license_id <> @partner_license_id
							AND pl.license_id = @license_id
						ORDER BY pl.partner_license_id DESC;

						IF ISNULL( @previous_partner_id, '' ) <> @ZIX_PARTNER_ID BEGIN

								SELECT @sky_update_json = (
																SELECT 
																	'ZIX' AS partner, 
																	@parent_keycode AS parentkeycode
																FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
															)
								-- insert sky_update
								EXECUTE dbo.usp_sky_insert_update
									@license_id = @license_id,
									@sky_template_id = @sky_template_id,
									@sky_update_json = @sky_update_json
									
							END

					END

                -- 4.3) flag license for customized pricing, pax8 code for poaching license
                IF EXISTS ( SELECT 1 
							FROM dbo.partner_license pl
								INNER JOIN dbo.customize_pricing_partner cpp
                                    ON cpp.partner_id = pl.partner_id
							WHERE pl.partner_license_id = @partner_license_id ) BEGIN

                        DECLARE @categories TABLE (
                            license_id INT,
                            license_category_id TINYINT,
                            min_start_date DATE,
                            usage BIT DEFAULT 0
                        );

                        SELECT
                            @partner_id = partner_id
                        FROM dbo.partner_license
                        WHERE partner_license_id = @partner_license_id;

                        INSERT INTO @categories (
                            license_id,
                            license_category_id
                        )
                        SELECT
                            @license_id,
                            plc.license_category_id
                        FROM dbo.order_item oi
                            INNER JOIN dbo.product p
								ON p.product_id = oi.product_id
                            INNER JOIN dbo.product_license_category plc
                                ON plc.product_i
d = p.product_id
                        WHERE oi.order_header_id = @order_header_id;

                        -- check to see if the categories existed on license prior to partner order
                        UPDATE c
							SET c.min_start_date = f.license_start_date
                        FROM @categories c
                            CROSS APPLY dbo.fn_license_select_license_contract_table( c.license_id,
                                                                                        c.license_category_id,
                                                                                        'min_row' ) f
                        WHERE f.license_start_date < @partner_license_effective_date
							AND f.capability_type_id = 1;

                        -- check to see if categories had usage in last 30 days
                        UPDATE c SET 
							c.usage = 1
                        FROM @categories c
                            INNER JOIN dbo.license_category lc
								ON lc.license_category_id = c.license_category_id
                            CROSS APPLY dbo.fn_license_select_license_activity( c.license_id, GETDATE(), 'full',
                                                                                  lc.license_category_name ) fn
                        WHERE fn.console_activity > 0
							AND c.min_start_date IS NOT NULL;

                        -- check to see if categories had usage in last 60 days, in case it didn't have any in the last 30
                        UPDATE c 
							SET c.usage = 1
                        FROM @categories c
                            INNER JOIN dbo.license_category lc
                                ON lc.license_category_id = c.license_category_id
                            CROSS APPLY dbo.fn_license_select_license_activity( c.license_id, GETDATE() - 30, 'full',
                                                                                  lc.license_category_name ) fn
                        WHERE fn.console_activity > 0
                            AND c.min_start_date IS NOT NULL
                            AND c.usage = 0;

                        -- insert into license tracking table
						INSERT INTO dbo.customize_pricing_license (
							license_id,
							partner_id,
							license_category_id,
							partner_transfer_date,
							category_start_date
						)
                        SELECT
                            c.license_id,
                            @partner_id,
                            c.license_category_id,
                            @partner_license_effective_date,
                            GETDATE()
                        FROM @categories c
                        WHERE c.min_start_date IS NOT NULL
                            AND c.usage = 1;

                    END;

                -- 4.4) return
                SELECT
                    response_code = 300,
                    message       = 'Completed partner license approval';
                RETURN;

            END;

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 5.) Archive - no license update
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        IF @partner_license_status_id = 4 BEGIN

                -- 5.1) update partner_license
                INSERT INTO dbo.partner_license_audit (
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
        
            insert_date,
                    start_date,
                    end_date,
                    order_header_id
                )
				SELECT
                    partner_license_id,
                    license_id,
                    partner_id,
                    partner_license_status_id,
                    partner_license_source_id,
                    last_modified_user_id,
                    last_modified_date,
                    insert_date,
                    start_date,
                    end_date,
                    order_header_id
                FROM dbo.partner_license
                WHERE license_id = @license_id;

                UPDATE dbo.partner_license SET
                    partner_license_status_id = @partner_license_status_id,
                    last_modified_user_id = @last_modified_user_id,
                    last_modified_date = @last_modified_date
                WHERE partner_license_id = @partner_license_id;

                -- 5.2) update partner_license_transaction
                UPDATE dbo.partner_license_transaction SET
                    partner_license_status_id = @partner_license_status_id,
                    last_modified_date = @last_modified_date
                WHERE partner_license_id = @partner_license_id;

                -- 5.3) license service archive
                IF ( SELECT
							partner_license_transaction_procedure_id
                        FROM dbo.partner_license_transaction
                        WHERE partner_license_id = @partner_license_id ) = 6 BEGIN

                        -- 5.3.1) 
                        SELECT
                            @license_service_id = JSON_VALUE(t.license_transaction, '$.license_service_id')
                        FROM dbo.partner_license_transaction t
                        WHERE t.partner_license_id = @partner_license_id
                            AND t.partner_license_transaction_procedure_id = 6;

                        -- 5.3.2) archive
                        INSERT INTO dbo.license_service_archive (
                            license_service_id,
                            license_service_type_id,
                            license_service_status_id,
                            insert_date
                        )
                        SELECT
                            license_service_id,
                            license_service_type_id,
                            license_service_status_id = 4,
                            insert_date
                        FROM dbo.license_service
                        WHERE license_service_id = @license_service_id;

                        -- 5.3.3) delete service record
                        DELETE 
						FROM dbo.license_service
                        WHERE license_service_id = @license_service_id;

                    END;

                -- 5.4) update order status
                INSERT INTO dbo.order_header_audit (
                    order_header_id,
                    vendor_order_id,
                    order_offer_id,
                    order_offer_amount,
                    total_amount,
                    sub_total_amount,
                    tax_total,
                    payment_method_id,
                    session_id,
                    vendor_order_date,
                    locale,
                    exchange_rate,
                    site_id,
                    site_url,
                    order_status_id,
                    insert_date,
                    insert_by,
                    modified_date,
                    modified_by,
                    fee_total,
                    download_instruction_type_id,
                    audit_date
                )
                SELECT
                    order_header_id,
                    vendor_order_id,
                    order_offer_id,
                    order_offer_amount
,
                    total_amount,
                    sub_total_amount,
                    tax_total,
                    payment_method_id,
                    session_id,
                    vendor_order_date,
                    locale,
                    exchange_rate,
                    site_id,
                    site_url,
                    order_status_id,
                    insert_date,
                    insert_by,
                    modified_date,
                    modified_by,
                    fee_total,
                    download_instruction_type_id,
                    GETDATE() AS audit_date
                FROM dbo.order_header
                WHERE order_header_id = @order_header_id;

                UPDATE dbo.order_header SET
					order_status_id = 3,
					modified_date = @last_modified_date,
					modified_by = @last_modified_user_id
                WHERE order_header_id = @order_header_id;

                -- 5.5) return
                SELECT
                    response_code = 200,
                    message = 'Completed partner license archive';
                RETURN;
            END;

    END TRY
    BEGIN CATCH

        SET @response_code = -200;
        SET @message
            = CASE
                  WHEN @message IS NULL THEN
                      'error processing update to partner_license_id ' + CONVERT(VARCHAR(20), @partner_license_id)
                  ELSE @message
              END;

        DECLARE @DBName NVARCHAR(128);
        SET @DBName = DB_NAME();
        EXECUTE dbo.usp_LogError
            @ErrorDB = @DBName;

    END CATCH;



GO
