			select @partner_pricing_tier_id = SCOPE_IDENTITY()

		select partner_pricing_tier_id = @partner_pricing_tier_id
		return
		end


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--if @delete = 1
	---- 3.1) delete
