	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is nu
ll then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


