-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_insert_credit_card_update]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_payment_insert_credit_card_update] (
	@process_start_date DATE = NULL,
	@process_end_date DATE = NULL,
	@opt_args VARCHAR(50) = NULL
)


		
/*	
	DATE		AUTHOR		REMARKS
	2016-10-10	acoffel		Initial creation.
	2020-02-17	wbarton		Refactoring the procedure for flexibility, performance, and to select additional records
	2020-03-31	wbarton		Adding logic to de-dupe the insert for scenarios where Overage licenses have multiple order_payment_header records associated with the same order_header_id
	2020-05-14	wbarton		Adding insert_date for easier de-bugging with Cybersource
	2024-06-04	gblandford	https://jira.opentext.com/browse/ECOM-4618
							- Rework to manage batches more efficiently
							- Implement configuration for batch size, preview start and end days for when pramaters are passed as NULL
							- Format/casing changes
							- Added parameter @opt_args for debugging purposes
							- Added use of TRANSACTION

	
	DESCRIPTION
	Inserts batch header records into payment_subscription_credit_card_batch and individual subscription records into payment_subscription_credit_card_update

	BY DEFAULT we should now be calling this procedure with NULL in all parameters to allow configuration to determine ranges

	This procedure is currently called from SQL Agent Job 'Insert credit cart'. 
	As part of https://jira.opentext.com/browse/ECOM-4618 changes, will be renamed to 'Cybersource Account Updater - Create Batches'

*/

AS

SET NOCOUNT ON				

BEGIN TRY

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 0.1) Setup default start/end variables and configuration values
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	DECLARE @CYBERSOURCE_ACCOUNT_UPDATER_CONFIG TABLE (
		[key] VARCHAR(50)
		, [value] VARCHAR(50)
	);

	DECLARE @MAXIMUM_BATCH_SIZE INT
		, @PREVIEW_DAYS_START INT = 0
		, @PREVIEW_DAYS_END INT = 0

	INSERT INTO @CYBERSOURCE_ACCOUNT_UPDATER_CONFIG (
	    [key],
	    [value]
	)
	SELECT
	    f.[key],
	    f.[value]	
	FROM dbo.fn_app_config_select_key_values('CYBERSOURCE_ACCOUNT_UPDATER', 'AUTORENEWAL') f;

	IF @opt_args = 'debug' SELECT * FROM @CYBERSOURCE_ACCOUNT_UPDATER_CONFIG;

	SELECT 
		@MAXIMUM_BATCH_SIZE = ( CASE cfg.[key]
									WHEN 'MAXIMUM_BATCH_SIZE' THEN cfg.[value] 
									ELSE @MAXIMUM_BATCH_SIZE 
								END ),
		@PREVIEW_DAYS_START = CONVERT(INT, ( CASE cfg.[key]
									WHEN 'PREVIEW_DAYS_START' THEN cfg.[value] 
									ELSE @PREVIEW_DAYS_START 
								END ) ),
		@PREVIEW_DAYS_END = CONVERT(INT, ( CASE cfg.[key]
									WHEN 'PREVIEW_DAYS_END' THEN cfg.[value] 
									ELSE @PREVIEW_DAYS_END 
								END ) )

    FROM @CYBERSOURCE_ACCOUNT_UPDATER_CONFIG cfg

	IF @opt_args = 'debug' SELECT @MAXIMUM_BATCH_SIZE AS MAXIMUM_BATCH_SIZE, @PREVIEW_DAYS_START AS PREVIEW_DAYS_START, @PREVIEW_DAYS_END AS PREVIEW_DAYS_END

	IF @process_start_date IS NULL BEGIN
			SELECT @process_start_date = CONVERT(DATE, DATEADD(DAY, @PREVIEW_DAYS_START, GETDATE()))
		END

	IF @process_end_date IS NULL BEGIN
			SELECT @process_end_date = CONVERT(DATE, DATEADD(DAY, @PREVIEW_DAYS_END, GETDATE()))
		END

	IF @opt_args = 'debug' SELECT @process_start_date AS process_start_date, @process_end_date AS process_end_date 

	DECLARE @payment_subscription_credit_card_batch_id INT,
			@response_code INT,
			@message VARCHAR(100);

	DECLARE @batch_merchant_loop_value INT = 1
		, @batch_merchant_record
_count INT
		, @sub_batch_loop_value INT = 1
		, @id INT
		, @merchant_id VARCHAR(50)
		, @batch_record_count INT
		, @sub_batch_record_count INT

	DECLARE @payment_subscription_credit_card_update TABLE (
		payment_merchant_id INT,
		merchant_id VARCHAR(50),
		payment_subscription_credit_card_id INT,
		license_message_id INT,
		payment_header_id INT,
		credit_card_subscription_id VARCHAR(24),
		response_code VARCHAR(50),
		reason_code VARCHAR(10),
		payment_subscription_credit_card_batch_id INT,
		sub_batch_id INT NULL
	);

	DECLARE @batch_merchants TABLE (
		id INT IDENTITY(1, 1),
		payment_merchant_id INT,
		merchant_id VARCHAR(50),
		record_count INT,
		sub_batch_count INT
	);

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 0.0) Default start/end variables
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	IF @process_start_date IS NULL BEGIN
			SET @process_start_date = CONVERT(DATE, GETDATE());
		END;

	IF @process_end_date IS NULL BEGIN
			SET @process_end_date = CONVERT(DATE, DATEADD(DAY, 1, GETDATE()));
		END;

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) Populate @payment_subscription_credit_card_update
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	INSERT INTO @payment_subscription_credit_card_update (
		payment_merchant_id,
		merchant_id,
		payment_subscription_credit_card_id,
		license_message_id,
		payment_header_id,
		credit_card_subscription_id,
		response_code,
		reason_code
	)
	SELECT pum.payment_merchant_id,
		   pum.merchant_id,
		   cc.payment_subscription_credit_card_id,
		   lm.license_message_id,
		   ph.payment_header_id,
		   cc.credit_card_subscription_id,
		   NULL,
		   NULL
	FROM dbo.license_message lm
		INNER JOIN
			(
				SELECT oil.license_id,
					   MAX(oi.order_header_id) AS max_order
				FROM dbo.order_item_license oil
					INNER JOIN dbo.order_item oi
						ON oi.order_item_id = oil.order_item_id
				GROUP BY oil.license_id
			) o
				ON o.license_id = lm.license_id
		INNER JOIN
			(
				SELECT order_header_id,
					   MAX(order_payment_header_id) AS max_order_payment_header
				FROM dbo.order_payment_header
				GROUP BY order_header_id
			) oph1
				ON oph1.order_header_id = o.max_order
		INNER JOIN dbo.order_payment_header oph
			ON oph.order_payment_header_id = oph1.max_order_payment_header
		INNER JOIN dbo.payment_header ph
			ON oph.payment_header_id = ph.payment_header_id
		INNER JOIN dbo.payment_method pm
			ON pm.payment_method_id = ph.payment_method_id
		INNER JOIN dbo.payment_merchant pmr
			ON pmr.payment_merchant_id = ph.payment_merchant_id
		INNER JOIN dbo.license_attribute_license lal
			ON lm.license_id = lal.license_id
			   AND lal.license_attribute_id = 1
			   AND lal.license_attribute_license_value = 1
		INNER JOIN dbo.payment_subscription_credit_card cc
			ON cc.payment_header_id = ph.payment_header_id
		INNER JOIN dbo.payment_subscription_credit_card_update_merchant pum
			ON pum.payment_merchant_id = ph.payment_merchant_id
		LEFT JOIN dbo.payment_account ac
			ON ac.payment_header_id = ph.payment_header_id
		LEFT JOIN dbo.payment_subscription_credit_card_update u
			ON u.license_message_id = lm.license_message_id
	WHERE u.payment_subscription_credit_card_update_id IS NULL --license_message record has not already been sent to Cybes
		  AND lm.message_type_id = 3

		  AND lm.message_status_id NOT IN ( 3, 6, 7 ) --sending Cybes any not-completely-processed status. Excluding message_status_id 7; cleverbridge
		  AND lm.process_date >= @process_start_date --The window of time we're selecting can be controlled by the job
		  AND lm.process_date < @process_end_date
		  AND
			  (
				  ac.card_type_id IS NULL
				  OR ac.card_type_id IN ( 1, 2 )
			  ) --limiting the select to unknown or Visa and MC
	ORDER BY pum.payment_merchant_id;

	IF @opt_args = 'debug' SELECT * FROM @payment_subscription_credit_card_update;


	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) Create header records in payment_subscription_credit_card_batch by merchant, and update @payment_subscription_credit_card_update
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	IF EXISTS (SELECT 1 FROM @payment_subscription_credit_card_update) BEGIN

			IF @opt_args = 'debug' BEGIN
					SELECT DISTINCT
						payment_merchant_id,
						merchant_id,
						COUNT(*) AS record_count,
						CEILING( CAST( COUNT(*) AS DECIMAL) / @MAXIMUM_BATCH_SIZE ) AS sub_batch_count

					FROM @payment_subscription_credit_card_update
					GROUP BY payment_merchant_id,
						   merchant_id
				END

			-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 2.1) Based on the batch details, determine what header records are needed. Cybs requires batches by merchant
			-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			INSERT INTO @batch_merchants (
				payment_merchant_id,
				merchant_id,
				record_count,
				sub_batch_count
			)
			SELECT DISTINCT
				   payment_merchant_id,
				   merchant_id,
				   COUNT(*),
				   CEILING( CAST( COUNT(*) AS DECIMAL) / @MAXIMUM_BATCH_SIZE )

			FROM @payment_subscription_credit_card_update
			GROUP BY payment_merchant_id,
				   merchant_id

			IF @opt_args = 'debug' SELECT * FROM @batch_merchants

			-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 2.2) Calculate sub-batches to break up large batches that exceed the maximum allowed size
			-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			DECLARE @fake_identity INT = 1

			SELECT 
				@batch_merchant_record_count = MAX(id) 
			FROM @batch_merchants

			IF @opt_args = 'debug' BEGIN
					SELECT @batch_merchant_loop_value AS batch_merchant_loop_value, @batch_merchant_record_count AS batch_merchant_record_count
				END


			BEGIN TRANSACTION

				WHILE ( @batch_merchant_loop_value <= @batch_merchant_record_count ) BEGIN

						SELECT 
							@id = bm.id
							, @merchant_id = bm.merchant_id
							, @batch_record_count = bm.record_count
							, @sub_batch_record_count = bm.sub_batch_count

						FROM @batch_merchants bm
						WHERE bm.id = @batch_merchant_loop_value

						SET @sub_batch_loop_value = 1

						WHILE ( @sub_batch_loop_value <= @sub_batch_record_count ) BEGIN
					
								PRINT CAST(@batch_merchant_loop_value AS VARCHAR(10) ) + ' - ' + CAST(@sub_batch_loop_value AS VARCHAR(10) )

								-------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------
								-- 2.3) Create batch
								-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

								IF @opt_args = 'debug' BEGIN

										SELECT GETDATE(),
											   b.merchant_id,
											   NULL,
											   1,
											   NULL,
											   0,
											   GETDATE(),
											   GETDATE()
										FROM @batch_merchants b
										WHERE b.id = @batch_merchant_loop_value;

										SET @fake_identity = @batch_merchant_loop_value
										SET @payment_subscription_credit_card_batch_id = @fake_identity; 

									END
								ELSE BEGIN
										 INSERT INTO dbo.payment_subscription_credit_card_batch (
											process_date
											, merchant_id
											, cybs_batch_id
											, payment_subscription_credit_card_batch_status_id
											, cybs_batch_response, attempts
											, last_modified_date
											, insert_date
										)
										SELECT GETDATE(),
											   b.merchant_id,
											   NULL,
											   1,
											   NULL,
											   0,
											   GETDATE(),
											   GETDATE()
										FROM @batch_merchants b
										WHERE b.id = @batch_merchant_loop_value;

										SET @payment_subscription_credit_card_batch_id = SCOPE_IDENTITY();

									END

								-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
								-- 2.4) Update the batch records up to the maximum batch size
								-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
								SET ROWCOUNT @MAXIMUM_BATCH_SIZE;

								UPDATE u
									SET u.payment_subscription_credit_card_batch_id = @payment_subscription_credit_card_batch_id
										, u.sub_batch_id = @sub_batch_loop_value	
							
								FROM @payment_subscription_credit_card_update u
									INNER JOIN @batch_merchants b
										ON b.payment_merchant_id = u.payment_merchant_id
											AND b.id = @batch_merchant_loop_value
								WHERE u.sub_batch_id IS NULL
									AND u.payment_subscription_credit_card_batch_id IS NULL

								SET ROWCOUNT 0;

								IF @opt_args = 'debug' BEGIN
										SELECT * 
										FROM @payment_subscription_credit_card_update 
										WHERE payment_subscription_credit_card_batch_id = @batch_merchant_loop_value 
											AND sub_batch_id = @sub_batch_loop_value;
									END

								-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
								-- Increment sub batch loop
								-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
								SET @sub_batch_loop_value = @sub_batch_loop_value + 1
							END

						-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
						-- Increment batch loop
						-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
						SET	@batch_merchant_loop_value = @batch_merchant_loop_value + 1
					END

				-------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------
				-- 3.0) Insert records into payment_subscription_credit_card_update
				-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

				IF @opt_args = 'debug' BEGIN
						SELECT payment_subscription_credit_card_id,
							license_message_id,
							payment_header_id,
							credit_card_subscription_id,
							response_code,
							reason_code,
							GETDATE(),
							payment_subscription_credit_card_batch_id,
							GETDATE(),
							sub_batch_id
						FROM @payment_subscription_credit_card_update
						ORDER BY payment_subscription_credit_card_batch_id;

					END
				ELSE BEGIN
						INSERT INTO dbo.payment_subscription_credit_card_update (
							payment_subscription_credit_card_id
							, license_message_id
							, payment_header_id
							, credit_card_subscription_id
							, response_code
							, reason_code
							, last_modified_date
							, payment_subscription_credit_card_batch_id
							, insert_date
						)
						SELECT payment_subscription_credit_card_id,
							license_message_id,
							payment_header_id,
							credit_card_subscription_id,
							response_code,
							reason_code,
							GETDATE(),
							payment_subscription_credit_card_batch_id,
							GETDATE()
						FROM @payment_subscription_credit_card_update
						ORDER BY payment_subscription_credit_card_batch_id;

					END

			COMMIT WORK;

	END;

END TRY

BEGIN CATCH

	IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'payment_subscription_credit_card batch insert failed' ELSE @message END

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXECUTE dbo.usp_LogError @ErrorDB = @DBName

	SELECT @response_code AS response_code, @message AS message
		
END CATCH;

GO
