CREATE PROCEDURE [dbo].[usp_payment_insert_cybs_subscription]

(
	@cybs_subscription_id int = null,
	@payment_merchant_id tinyint = null,
	@merchant_id varchar(50) = null,
	@credit_card_subscription_id varchar(24) = null,
	@account_number varchar(4) = null,
	@expiration_month tinyint = null,
	@expiration_year smallint = null,
	@card_type_id tinyint = null,
	@salesforce_account_id varchar(18) = null,
	@customer_id int = null,
	@company_id int = null

)
	
/*	
	DATE			AUTHOR		REMARKS
	2015-09-10		esmart		Initial creation
	2016-02-05		esmart		Add payment_account data
	2019-01-18		esmart		Add @company_id as input
	2019-06-21		esmart		add @company_id_input
	2019-08-27		abelenkiy	Optimized and removed unsused variables
	
	DESCRIPTION
	insert cybs_subscription
	
*/

AS
	
	set nocount on			

	declare	@log_text nvarchar(max),
			@customer_email varchar(100), 
			@first_name nvarchar(225), 
			@last_name nvarchar(225), 
			@company_name nvarchar(255), 
			--@company_type_name varchar(20), 
			--@phone_number varchar(64), 
			@address_1 nvarchar(255), 
			--@address_2 nvarchar(255), 
			@city nvarchar(130), 
			@state nvarchar(2), 
			@postal_code nvarchar(32), 
			@country varchar(75), 
			--@vendor_id int, 
			--@vendor_customer_code varchar(100), 
			--@partner_id int, 
			--@opt_in int, 
			--@salesforce_contact_id char(18), 
			@transaction_user varchar(20), 
			--@customer_id_input int, 
			--@company_id_input int, 
			--@customer_id int,
			--@company_id int,	
			--@response_code int, 
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @payment_merchant_id
	if @merchant_id is not null
		begin
			select @payment_merchant_id = payment_merchant_id from payment_merchant where merchant_id = @merchant_id
		end

	-- 1.2) update cybs_subscription
	if @cybs_subscription_id is not null
		begin
		update cybs_subscription
		--set payment_merchant_id = case when @payment_merchant_id is null then payment_merchant_id else @payment_merchant_id end,
		--	credit_card_subscription_id = case when @credit_card_subscription_id is null then credit_card_subscription_id else @credit_card_subscription_id end,
		--	account_number = case when @account_number is null then account_number else @account_number end,
		--	expiration_month = case when @expiration_month is null then expiration_month else @expiration_month end,
		--	expiration_year = case when @expiration_year is null then expiration_year else @expiration_year end,
		--	card_type_id = case when @card_type_id is null then card_type_id else @card_type_id end
		set payment_merchant_id = isnull(@payment_merchant_id, payment_merchant_id),
			credit_card_subscription_id = isnull(@credit_card_subscription_id, credit_card_subscription_id),
			account_number = isnull(@account_number, account_number),
			expiration_month = isnull(@expiration_month, expiration_month),
			expiration_year = isnull(@expiration_year, expiration_year),
			card_type_id = isnull(@card_type_id, card_type_id)
		where cybs_subscription_id = @cybs_subscription_id
		end
	-- 1.3) insert cybs_subscription
	else
		begin
		insert into cybs_subscription(credit_card_subscription_id,payment_merchant_id,account_number,expiration_month,expiration_year,card_type_id)
		values(@credit_card_subscription_id,@payment_merchant_id,@account
_number,@expiration_month,@expiration_year,@card_type_id)

		select @cybs_subscription_id = scope_identity()
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) cybs_subscription_customer
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @credit_card_subscription_id is not null
		begin

		-- 2.1) @log_text
		select @log_text = log_text from cybs_subscription_log where cybs_subscription_id = @cybs_subscription_id and log_type = 'Request'
		
		if @log_text is not null
			begin

			--select @log_text

			-- 2.2) select parameters
			--select @first_name = StringValue from fn_parse_json(@log_text) where NAME = 'firstName'
			--select @last_name = StringValue from fn_parse_json(@log_text) where NAME = 'lastName'
			--select @customer_email = StringValue from fn_parse_json(@log_text) where NAME = 'email'
			--select @company_name = StringValue from fn_parse_json(@log_text) where NAME = 'company'
			--select @address_1 = StringValue from fn_parse_json(@log_text) where NAME = 'street1'
			--select @city = StringValue from fn_parse_json(@log_text) where NAME = 'city'
			--select @state = StringValue from fn_parse_json(@log_text) where NAME = 'state'
			--select @postal_code = StringValue from fn_parse_json(@log_text) where NAME = 'postalCode'
			--select @country = StringValue from fn_parse_json(@log_text) where NAME = 'country'
			--select @transaction_user = 'cybs_subscription'

			select
				@first_name = first_name,
				@last_name = last_name,
				@customer_email = customer_email,
				@company_name = company_name,
				@address_1 = address_1,
				@city = city,
				@state = state,
				@postal_code = postal_code,
				@country = country,
				@transaction_user = 'cybs_subscription'
			from
				openjson(@log_text, '$.billTo')
				with(
					first_name nvarchar(225) '$.firstName',
					last_name nvarchar(225) '$.lastName',
					customer_email varchar(100) '$.email',
					company_name nvarchar(255) '$.company',
					address_1 nvarchar(255) '$.street1',
					city nvarchar(130) '$.city',
					state nvarchar(2) '$.state',
					postal_code nvarchar(32) '$.postalCode',
					country varchar(75) '$.country'
					)


			

			if @company_name is null and @company_id is not null
				begin
				select @company_name = company_name
				from company 
				where company_id = @company_id
				end

			if @company_name is null and @salesforce_account_id is not null and @company_id is null
				begin
				select @company_name = company_name,
					@company_id = company_id
				from company 
				where salesforce_account_id = @salesforce_account_id
				end
		
			--select @customer_email,@first_name,@last_name,@company_name,@company_type_name,@phone_number,@address_1,@address_2,@city,@state,@postal_code,@country,@vendor_id,@vendor_customer_code,@partner_id,@opt_in,@salesforce_account_id,@salesforce_contact_id,@transaction_user,@customer_id_input,@customer_id
			--return

			-- 2.3) usp_customer_insert_customer_service
			if @customer_id is null
				begin
					exec usp_customer_insert_customer_service
						@customer_email = @customer_email,
						@first_name = @first_name,
						@last_name = @last_name,
						@company_name = @company_name,
						@address_1 = @address_1,
						@city = @city,
						@state = @state,
						@postal_code = @postal_code,
						@country = @country,
						@salesforce_account_id = @salesforce_account_id,
						@transaction_user = @transaction_user,
						@customer_id_input = @customer_id,
						@company_id_input = @company_id,
						@customer_id = @customer_id output
				
					--exec usp_customer_insert_customer_service
					--	@custom
er_email
					--  , @first_name
					--  , @last_name
					--  , @company_name
					--  , @company_type_name
					--  , @phone_number
					--  , @address_1
					--  , @address_2
					--  , @city
					--  , @state
					--  , @postal_code
					--  , @country
					--  , @vendor_id
					--  , @vendor_customer_code
					--  , @partner_id
					--  , @opt_in
					--  , @salesforce_account_id
					--  , @salesforce_contact_id
					--  , @transaction_user
					--  , @customer_id_input
					--  , @company_id_input
					--  , @customer_id output;

				end;

			-- 2.4) cybs_subscription_company
			if @company_id is null
				begin
					select @company_id = company_id from customer_company where customer_id = @customer_id
				end

			insert into cybs_subscription_customer(cybs_subscription_id,customer_id,company_id)
			values(@cybs_subscription_id,@customer_id,@company_id)

			end
		end




	select cybs_subscription_id = @cybs_subscription_id

	end try

	begin catch

		--set @response_code = -200
		--set @message = case when @message is null then 'insert failed'
		--					else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
