-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_insert_export_violation]

(
	@payment_response_id int
)
	
/*	
	DATE			AUTHOR			REMARKS
	2015-12-09		esmart			Initial creation
	2016-01-04		esmart			Remove logging of some tags
	
	DESCRIPTION
	insert payment_export_violation
*/

AS
	
	set nocount on			

	declare	@response_text nvarchar(max),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) response_text
	select @response_text = response_text
	from payment_response
	where payment_response_id = @payment_response_id

	-- 1.2) insert payment_export_violation
	if @response_text is not null
		begin

		declare @response_data table (object_id int, name varchar(255), value nvarchar(max), value_type varchar(50))

		insert into @response_data(object_id,name,value,value_type)
		select t.object_id, t.name, t.StringValue,t.ValueType
		from fn_parse_json(@response_text) t
		inner join (select Object_ID
					from fn_parse_json(@response_text)
					where Name = 'deniedPartiesMatch' or Name = 'exportReply' or Name = 'name') x
			on (x.Object_ID = t.parent_ID or x.Object_ID = t.Object_ID)
		where t.Object_ID is not null

		insert into payment_export_violation(payment_response_id,response_name,response_value)
		select distinct @payment_response_id, response_name = case when t.NAME is null then r.Name + '_list' else t.Name end, response_value = t.StringValue
		from fn_parse_json(@response_text) t
		inner join @response_data r
			on t.parent_ID = r.object_id
		left join payment_export_violation v
			on v.payment_response_id = @payment_response_id and v. response_name  = case when t.NAME is null then r.Name + '_list' else t.Name end and v.response_value = t.StringValue
		where v.payment_export_violation_id is null and isnull(t.NAME,'') <> 'ipCountryConfidence' and not (isnull(t.NAME,'') = 'reasonCode' and t.StringValue = 100) and t.Object_ID is null
		--order by t.sequenceNo

		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_insert_payment_fee]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_insert_payment_fee]

(
	@vendor_order_code varchar(50),
	@payment_fee money
)

/*	
	DATE		AUTHOR		REMARKS
	2011-04-14	esmart		Initial creation.
	2013-05-21	esmart		Add payment_fee table support for new cart

	DESCRIPTION
	Insert payment_fee 
	
*/

AS
	set nocount on				

	declare @order_header_id int,
			@cart_order_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate()

	-- 1.1) @order_heder_id

	select @order_header_id = h.order_header_id 
	from order_header h
	inner join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	where v.vendor_order_code = @vendor_order_code

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @order_header_id is not null
		begin
		-- 2.1) insert order_fee
		insert into order_fee(order_header_id, payment_fee, insert_date)
		values(@order_header_id,@payment_fee,@transaction_date)

		-- 2.2) update order_header
		update order_header
		set fee_total = (select sum(payment_fee) from order_fee where order_header_id = @order_header_id),
			modified_date = @transaction_date,
			modified_by = suser_sname()
		where order_header_id = @order_header_id

		end
	else
		begin
		select @cart_order_id = cart_order_id from cart_order where vendor_order_code = @vendor_order_code

		if @cart_order_id is not null
			begin
			insert into payment_fee(cart_order_id,payment_fee)
			values(@cart_order_id,@payment_fee)
			end
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_insert_payment_header_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_insert_payment_header_in_process]

(
	@vendor_order_code varchar(50),
	@merchant_id varchar(50),
	@payment_method_name varchar(50) = null,
	@currency_code char(3) = null,
	@message_key varchar(36) = null
	
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-25	esmart		Initial creation.

	DESCRIPTION
	Temporary procedure to insert payment_header from old in_process
	
*/

AS
	set nocount on				

	declare @payment_header_id int,
			@cart_in_process_id int,
			@payment_status_id tinyint,
			@payment_merchant_id tinyint,
			@payment_method_id tinyint,
			@transaction_date datetime,
			@currency_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate(),
			@payment_status_id = 1
	
	-- 1.1) get @cart_in_process_id
	select @cart_in_process_id = cart_in_process_id
	from cart_in_process
	where invoice_code = @vendor_order_code

	-- 1.2) get @payment_merchant_id
	select @payment_merchant_id = payment_merchant_id
	from payment_merchant
	where merchant_id = @merchant_id

	-- 1.3 get @payment_method_id
	select @payment_method_id = payment_method_id
	from payment_method 
	where payment_method_name = @payment_method_name

	-- 1.4) @currency_id
	select @currency_id = currency_id
	from currency 
	where currency_code = @currency_code

	if @currency_id is null
		begin
		select @currency_id = 1
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert payment_header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert payment_header
	insert into payment_header(payment_merchant_id, payment_status_id, payment_method_id, currency_id)
	values(@payment_merchant_id, @payment_status_id, @payment_method_id, @currency_id)
	
	select @payment_header_id = scope_identity()

	-- 2.2) insert payment_header_cart_in_process
	insert into payment_header_cart_in_process(payment_header_id, cart_in_process_id)
	values(@payment_header_id, @cart_in_process_id)

	-- 2.3) insert cart_message_in_process
--select @message_key = '822C456C-CED5-45EF-8CC3-275497E5F058'

	if @message_key is not null
		begin
		insert into cart_message_in_process(cart_in_process_id,message_key)
		values(@cart_in_process_id,@message_key)

		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_insert_payment_header_opportunity]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_insert_payment_header_opportunity]

(
	@salesforce_opportunity_id varchar(500) = null,
	@vendor_order_code varchar(500) = null,
	@merchant_id varchar(50) = null,
	@payment_method_name varchar(50) = null,
	@currency_iso_code varchar(3) = null,
	@oracle_invoice_number int = null,
	@sap_invoice_number varchar(20) = null
)

/*	
	DATE		AUTHOR			REMARKS
	2015-01-27	esmart			Initial creation.
	2018-01-08	esmart			Add @vendor_order_code as alternate 
	2022-02-18	abelenkiy		Added @sap_invoice_number as input parameter; 
								updated all oracle_invoice_number references to sap_invoice_number; 
								updated error handling in catch block
	2022-06-09	abelenkiy		Added back handling of @oracle_invoice_number to support payment of converted invoices;
								removed unused code

	DESCRIPTION
	Insert payment_header_opportunity record. Multiple comma-delimited records may be passed in @salesforce_opportunity_id
	and parsed by the somewhat old-school fn_string_to_table function (changing this to use JSON would require PHP work and 
	isn't worth it).

	This is called by PHP during the Pay Your Invoice (PYI) process. A vendor_order_code OR salesforce_opportunity_id could be 
	passed in but post-integration, only salesforce_opportunity_id will be passed in for PYI. There may be other PHP dependencies 
	so the code for handling vendor_order_code will remain intact for now. There are no DB dependencies. 
*/

as
begin try
	set nocount on				

	declare	@payment_header_opportunity_id int,
			@payment_merchant_id tinyint,
			@payment_method_id tinyint,
			@payment_status_id tinyint,
			@currency_id tinyint,
			@payment_header_id int,
			@order_header_id int,
			@order_payment_header_id int,
			@message nvarchar(4000)			


	select @payment_status_id = 1

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	---- 1.1) verify not loaded
	--select @payment_header_opportunity_id = payment_header_opportunity_id
	--from payment_header_opportunity po
	--left join order_payment_header o
	--	on po.payment_header_id = o.payment_header_id and o.oracle_invoice_number = @oracle_invoice_number
	--where salesforce_opportunity_id = @salesforce_opportunity_id

	--if @payment_header_opportunity_id is not null
	--	begin
		
	--	select payment_header_opportunity_id, payment_header_id, salesforce_opportunity_id
	--	from  payment_header_opportunity
	--	where payment_header_opportunity_id = @payment_header_opportunity_id

	--	return
	--	end

	-- 1.2) @payment_merchant_id
	if @merchant_id is not null and @merchant_id <> ''
		begin
			select @payment_merchant_id = payment_merchant_id
			from payment_merchant
			where merchant_id = @merchant_id
		end
	else
		begin
			select @payment_merchant_id = 1 -- webroot
		end
	
	-- 1.3) @payment_method_id
	if @payment_method_name is not null and @payment_method_name <> ''
		begin
		select @payment_method_id = payment_method_id 
		from payment_method
		where payment_method_name = @payment_method_name
		end
	else
		begin
		select @payment_method_id = 1
		end
	
	-- 1.4) @currency_id
	if @currency_iso_code is not null and @currency_iso_code <> ''
		begin
		select @currency_id = currency_id
		from currency
		where currency_code = @currency_iso_code
		end
	else
		begin
		select @currency_id = 1
		end

	-- 1.5) paymen
t_header_id
	if @salesforce_opportunity_id is not null
		begin
			select @payment_header_id = (select top 1 o.payment_header_id 
										from dbo.fn_string_to_table(@salesforce_opportunity_id) s
										inner join order_opportunity oo
											on s.string_value = oo.salesforce_opportunity_id
										left join order_payment_header o
											on oo.order_header_id = o.order_header_id 
												and o.sap_invoice_number = @sap_invoice_number
										left join order_payment_header o2
											on oo.order_header_id = o2.order_header_id 
												and o2.oracle_invoice_number = @oracle_invoice_number
										where o.order_payment_header_id is null
											and o2.order_payment_header_id is null
										order by o.order_payment_header_id desc)
		end

	if @vendor_order_code is not null
		begin
			select @payment_header_id = (select top 1 o.payment_header_id 
										from dbo.fn_string_to_table(@vendor_order_code) s
										inner join vendor_order v
											on s.string_value = v.vendor_order_code
										inner join order_header h
											on v.vendor_order_id = h.vendor_order_id
										left join order_payment_header o
											on h.order_header_id = o.order_header_id 
												and o.sap_invoice_number = @sap_invoice_number
										left join order_payment_header o2
											on h.order_header_id = o2.order_header_id 
												and o2.oracle_invoice_number = @oracle_invoice_number
										where o.order_payment_header_id is null
											and o2.order_payment_header_id is null
										order by o.order_payment_header_id desc)
		end
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) insert payment_header
	if @payment_header_id is null
		begin
			insert into payment_header(payment_merchant_id, payment_method_id, payment_status_id, currency_id)
			values(@payment_merchant_id, @payment_method_id, @payment_status_id, @currency_id)

			select @payment_header_id = scope_identity()
		end

	-- 2.2) insert payment_header_opportunity_id
	insert into payment_header_opportunity(payment_header_id, salesforce_opportunity_id)
	select @payment_header_id, salesforce_opportunity_id = s.string_value
	from dbo.fn_string_to_table(@salesforce_opportunity_id) s
	--inner join order_opportunity oo
	--	on s.string_value = oo.salesforce_opportunity_id
	left join payment_header_opportunity o
		on o.salesforce_opportunity_id = s.string_value and o.payment_header_id = @payment_header_id
	where o.payment_header_opportunity_id is null
				
	-- 2.3) order_payment_header
	if @salesforce_opportunity_id is not null
		begin
			insert into order_payment_header(order_header_id, payment_header_id, oracle_invoice_number, sap_invoice_number)
			select oo.order_header_id, @payment_header_id, @oracle_invoice_number, @sap_invoice_number
			from dbo.fn_string_to_table(@salesforce_opportunity_id) s
			inner join order_opportunity oo
				on s.string_value = oo.salesforce_opportunity_id
			left join order_payment_header o
				on oo.order_header_id = o.order_header_id 
					and o.sap_invoice_number = @sap_invoice_number
					and o.payment_header_id = @payment_header_id
			left join order_payment_header o2
				on oo.order_header_id = o2.order_header_id 
					and o2.oracle_invoice_number = @oracle_invoice_number
					and o2.payment_header_id = @payment_header_id
			where o.order_payment_header_id is null
				and o2.order_payment_header_id is null
		end
				
	if @vendor_order_code is not null
		begin
			insert into order_payment_header(order_header_id, payment_header_id, sap_invoice_number)

			select h.order_header_id, @payment_header_id, @sap_invoice_number
			from dbo.fn_string_to_table(@vendor_order_code) s
			inner join vendor_order v
				on s.string_value = v.vendor_order_code
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			left join order_payment_header o
				on h.order_header_id = o.order_header_id 
					and o.sap_invoice_number = @sap_invoice_number 
					and o.payment_header_id = @payment_header_id
			left join order_payment_header o2
				on h.order_header_id = o2.order_header_id 
					and o2.oracle_invoice_number = @oracle_invoice_number
					and o2.payment_header_id = @payment_header_id
			where o.order_payment_header_id is null
		end
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select payment_header_id = @payment_header_id

end try

begin catch

	declare
		@error_severity int = error_severity(), @error_state int = error_state()
	set @message = 'salesforce_opportunity_id = ' + convert(varchar(20), isnull(@salesforce_opportunity_id, 'null')) 
				+ ', vendor_order_code = ' + convert(varchar(20), isnull(@vendor_order_code, 'null'))
				+ ', sap_invoice_number = ' + convert(varchar(20), isnull(@sap_invoice_number, 'null'))
				+ ', oracle_invoice_number = ' + convert(varchar(20), isnull(@oracle_invoice_number, 'null'))
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state) with log

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()
		
end catch;


GO
