-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_insert_payment_request]

(
	@vendor_order_code varchar(50) = null,
	@payment_method_name varchar(50),
	@payment_action_name varchar(50),
	@request_text nvarchar(max),
	@account_number varchar(4) = null, 
	@expiration_month char(2) = null, 
	@expiration_year char(4) = null, 
	@card_type_id char(3) = null, 
	@cv_number varchar(4) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-04-28	esmart		Initial creation.
	2012-03-15	esmart		Modify request_text to be nvarchar
	2012-10-26	esmart		Add generic payment action and payment_header_lookup
	2014-05-24	esmart		Add support for new account number columns
	2014-06-17	esmart		Paypal fix
	2015-01-27	esmart		Salesforce payments
	2019-02-12	esmart		Exclude AUTORENEWAL
	2019-02-15	rvinoche	Parse Json correctly
	2023-02-06	schindar	Updated error handling 

	DESCRIPTION
	Insert payment_request
	
*/

AS
	set nocount on				

	declare	@payment_action_id tinyint,
			@payment_method_id tinyint,
			@message NVARCHAR(4000)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

	-- 1.2) get @payment_action_id
	select @payment_action_id = payment_action_id
	from payment_action
	where payment_action_name = @payment_action_name

	if @payment_action_id is null
		begin
		select @payment_action_id = payment_action_id
		from payment_action
		where payment_action_name = 'Generic'
		end

	-- 1.3) get @payment_method_id
	select @payment_method_id = payment_method_id
	from payment_method
	where payment_method_name = @payment_method_name

	-- 1.4) 
	if @account_number is null and @payment_action_id = 1 and @payment_method_id = 1 
		begin
			select @account_number = accountNumber,
				@expiration_month = expirationMonth,
				@expiration_year = expirationYear,
				@card_type_id = cardType,
				@cv_number = cvNumber
			from openjson(@request_text)
			with (accountNumber VARCHAR(4) '$.card.accountNumber',
				expirationMonth CHAR(2) '$.card.expirationMonth',
				expirationYear CHAR(4) '$.card.ex
pirationYear',
				cardType CHAR(3) '$.card.cardType',
				cvNumber VARCHAR(4) '$.card.cvNumber')
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into payment_request(payment_header_id, payment_action_id, payment_method_id, request_text, account_number, expiration_month, expiration_year, card_type_id, cv_number)
	values(@payment_header_id, @payment_action_id, @payment_method_id, @request_text, @account_number, @expiration_month, @expiration_year, @card_type_id, @cv_number)
	
	end try

	begin catch
	declare
		@error_severity int = error_severity(), @error_state int = error_state()
			
		SET @message = 'vendor_order_code = ' + isnull(@vendor_order_code, 'null')
					 + ' payment_method_name = ' +  isnull(@payment_method_name, 'null')
					 + ' payment_action_name = ' + isnull(@payment_action_name, 'null')
					 + ' request_text = ' + isnull(@request_text, 'null')
					 + ' salesforce_opportunity_id = ' + isnull(@salesforce_opportunity_id, 'null')
					 + ' payment_header_id = ' + ISNULL(CONVERT (VARCHAR(20),@payment_header_id), 'null')
					 + ' payment_action_id = ' + ISNULL(CONVERT (VARCHAR(20),@payment_action_id), 'null')
					 + ' payment_method_id = ' +ISNULL(CONVERT (VARCHAR(20),@payment_method_id), 'null')
					 + ': ' + error_message()
	
				raiserror(@message, @error_severity, @error_state)
		
	  insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, 
        ErrorDB, ErrorUser)
    select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, 
        db_name(), suser_name()
			
	end catch;
	




GO
