CREATE PROCEDURE [dbo].[usp_payment_insert_payment_subscription]

(
	@payment_header_id int,
	@subscription_id varchar(50),
	@payment_subscription_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2016-07-12	cnovac		Initial creation.

	DESCRIPTION
	
*/

as

set nocount on

begin try			

	declare @transaction_date datetime = getdate(),
			@response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @payment_subscription_id = payment_subscription_id
	from payment_subscription
	where subscription_id = @subscription_id	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_subscription_id is null
	begin
		insert into payment_subscription(payment_header_id, subscription_id)
		values(@payment_header_id, @subscription_id)

		select @payment_subscription_id = scope_identity()
	end
	else
	begin
		insert into payment_subscription_audit(payment_subscription_id, payment_header_id, subscription_id, last_modified_date, audit_date)
		select payment_subscription_id, payment_header_id, subscription_id, last_modified_date, @transaction_date
		from payment_subscription 
		where payment_subscription_id = @payment_subscription_id

		update payment_subscription 
		set payment_header_id = @payment_header_id,
			last_modified_date = @transaction_date
		where payment_subscription_id = @payment_subscription_id
	end

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch

GO
