CREATE PROCEDURE [dbo].[usp_payment_select_cart_customer]

(
	@vendor_order_code varchar(50),
	@customer_type_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2013-03-12	esmart		@customer_type_id
	2013-07-03	acoffel		extended vat_id into select
	2013-10-11	esmart		

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @customer_type_id is null
		begin
		select @customer_type_id = 1
		end

	select c.cart_customer_id, customer_in_process_id, first_name, last_name, bill_address_1, bill_address_2, bill_address_3, bill_city, bill_state, sb.state_iso3, bill_postal_code, bill_country,phone_number, company_name, customer_email, opt_in, c.vat_id, c.insert_date, c.insert_by, c.modified_date, c.modified_by, c.cart_order_status_id
	from cart_customer c
	inner join cart_order o
		on c.cart_order_id = o.cart_order_id
	inner join lu_countries lc
		on c.bill_country = lc.iso3
	left join lu_states sb
		on c.bill_state = sb.state_id and lc.iso = sb.iso2
	where o.vendor_order_code = @vendor_order_code and c.customer_type_id = @customer_type_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
