CREATE PROCEDURE [dbo].[usp_payment_select_cart_order]

(
	@vendor_order_code varchar(50)	
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2017-03-02	esmart		Add currency_code

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select c.cart_order_id, c.cart_customer_id, c.invoice_in_process_id, c.vendor_order_code, c.order_type, c.site_id, c.site_url, c.p_rc, c.p_rsc, c.p_ac, c.trx_rc, c.trx_rsc, c.trx_ac, c.aid, c.pid, c.sid, c.offer_id, c.offer_amount, c.total_amount, c.sub_total_amount, c.tax_amount, c.payment_method, c.exchange_rate, c.session_id, c.submission_date, c.sales_order_date, c.locale, c.subject, c.comment, c.insert_date, c.insert_by, c.modified_date, c.modified_by, c.cart_order_status_id, c.currency_id, c.customer_profile_token, c.cart_order_in_process_id,
		m.merchant_id, cu.currency_code
	from cart_order c
	left join currency cu
		on cu.currency_id = c.currency_id
	left join payment_header h
		on h.cart_order_id = c.cart_order_id
	left join payment_merchant m
		on h.payment_merchant_id = m.payment_merchant_id
	where c.vendor_order_code = @vendor_order_code

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
