-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_cart_order_item]

(
	@vendor_order_code varchar(50)	
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2014-10-24	esmart		Add columns
	2016-11-21	esmart		Add start_date and expiration_date

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select i.cart_order_item_id, i.cart_order_id, i.invoice_item_in_process_id, i.vendor_id, i.line_item, i.vendor_product_id, p.product_description, f.product_family_description, i.quantity, i.order_item_offer_code, i.order_item_offer_amount, i.list_price, i.unit_price, discount = i.list_price - i.unit_price, i.tax_item_total, i.tax_exempt, i.product_id, i.conversion_product_id, i.product_locale, i.insert_date, i.insert_by, i.modified_date, i.modified_by, i.cart_order_status_id, i.cart_order_item_in_process_id, i.cart_item_bundle_id, i.start_date, i.expiration_date
	from cart_order_item i
	inner join product p
		on i.product_id = p.product_id
	inner join product_family f
		on f.product_family_id = p.product_family_id
	inner join cart_order o
		on i.cart_order_id = o.cart_order_id
	where o.vendor_order_code = @vendor_order_code
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_cart_order_item_summary]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_cart_order_item_summary]

(
	@vendor_order_code varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-02-06	esmart		Initial creation.
	2013-03-12	esmart		Add product_line_cart_type
	2013-08-13	esmart		Trial-to-full support as new product
	2013-10-17	esmart		Align with in process summary
	2013-11-13	esmart		Add bundle description details
	2014-08-20	esmart		Make bundle data nvarchar
	2014-11-21	esmart		Update to match in process summary

	DESCRIPTION
	select cart_order_item_summary
*/

AS
	set nocount on				

	declare	@cart_order_id int,
			@cart_item_bundle_id int,
			@response_code int,
			@message varchar(100)


	begin try

	declare @item_summary table (cart_item_bundle_id int, product_family_id int, product_line_id int, product_locale char(5), cart_order_item_id int, product_id int, keycode varchar(40), product_type_id int, max_product_type_id int,	current_license_category_id int,license_category_id int,current_seats int,seats int,current_storage_gb int,storage_gb int,quantity int,years float,list_price money,unit_price money,tax_item_total money, order_item_offer_amount money, product_type varchar(50), product_description varchar(200))

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @cart_order_id = cart_order_id from cart_order where vendor_order_code = @vendor_order_code


	-- 1.1) new product that can be bundled

		insert into @item_summary(cart_item_bundle_id,product_family_id,product_line_id,product_locale,cart_order_item_id,product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,list_price,unit_price,tax_item_total,order_item_offer_amount)
		select i.cart_item_bundle_id,  
				p.product_family_id,
				pl.product_line_id,
				i.product_locale,
				cart_order_item_id = min(i.cart_order_item_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = case when pl.product_line_id in (55,300) then max(i.quantity) else max(s.seats) end, 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				list_price = sum(i.list_price), 
				unit_price = sum(i.unit_price),
				tax_item_total = sum(i.tax_item_total),
				order_item_offer_amount = sum(i.order_item_offer_amount)
		from cart_order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		left join cart_order_item_license il with (nolock)
			on i.cart_order_item_id = il.cart_order_item_id
		where i.cart_order_id = @cart_order_id and il.cart_order_item_license_id is null and p.product_family_id in (1,2,3
0,31,50,51,55,100,200,300)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id,
				i.product_locale

	-- 1.2) renewal/upgrade products that can be bundled
		insert into @item_summary(cart_item_bundle_id, product_family_id,product_line_id,product_locale, keycode, cart_order_item_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,list_price,unit_price,tax_item_total,order_item_offer_amount)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				pl.product_line_id,
				i.product_locale,
				l.keycode, 
				cart_order_item_id = min(i.cart_order_item_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = min(plc.current_license_category_id),
				license_category_id = max(plc.license_category_id),
				current_seats = min(s.current_seats), 
				seats = max(s.seats), 
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				list_price = sum(i.list_price), 
				unit_price = sum(i.unit_price), 
				tax_item_total = sum(i.tax_item_total),
				order_item_offer_amount = sum(i.order_item_offer_amount)
		from cart_order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license il with (nolock)
			on i.cart_order_item_id = il.cart_order_item_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_id = @cart_order_id and il.keycode <> '' and p.product_family_id in (1,2,30,31,50,51,100,200)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id,
				i.product_locale,
				l.keycode

	-- 1.3) renewal/upgrade products that can be bundled
		insert into @item_summary(cart_item_bundle_id, product_family_id,product_line_id,product_locale, keycode, cart_order_item_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,list_price,unit_price,tax_item_total,order_item_offer_amount)
		select	i.cart_item_bundle_id, 
				p.product_family_id,
				pl.product_line_id,
				i.product_locale,
				l.keycode, 
				cart_order_item_id = min(i.cart_order_item_id), 
				product_type_id = min(p.product_type_id),  
				max_product_type_id = max(p.product_type_id),
				current_license_category_id = case when min(plc.current_license_category_id) = 0 then max(plc.license_category_id) else min(plc.current_license_category_id) end,
				license_category_id = max(plc.license_category_id),
				current_seats = max(st.license_seats), 
				seats = max(i.quantity),
				current_storage_gb = min(ps.storage_gb), 
				storage_gb = max(ps.storage_gb), 
				quantity = max(i.quantity), 
				years = max(y.years), 
				list_price = sum(i.list_price), 
				unit_price = sum(i.unit_price), 
				tax_item_total = sum(i.tax_item_total),
				order_item_offer_amount = sum(i.order_item_offer_amount)
		from cart_order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_line_product pl with (nolock)
			on i.product_id = pl.product_id
		inner join product_family f with (nolock)
			on p.product_family_id = f.product_family_i
d
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		inner join cart_order_item_license il with (nolock)
			on i.cart_order_item_id = il.cart_order_item_id
		inner join license l with (nolock)
			on il.keycode = l.keycode
		inner join license_seat st with (nolock)
			on l.license_id = st.license_id
		where i.cart_order_id = @cart_order_id and il.keycode <> '' and p.product_family_id in (55,300)
		group by i.cart_item_bundle_id,
				p.product_family_id,
				pl.product_line_id,
				i.product_locale,
				l.keycode

	-- 1.4) other products

		insert into @item_summary(cart_item_bundle_id,product_family_id,product_locale, keycode, cart_order_item_id, product_id, product_type_id,max_product_type_id,current_license_category_id,license_category_id,current_seats,seats,current_storage_gb,storage_gb,quantity,years,list_price,unit_price,tax_item_total,order_item_offer_amount)
		select i.cart_item_bundle_id,	
				p.product_family_id,
				i.product_locale,
				l.keycode,
				i.cart_order_item_id,
				p.product_id,
				p.product_type_id,  
				p.product_type_id,
				plc.current_license_category_id,
				plc.license_category_id,
				s.current_seats, 
				s.seats,
				ps.storage_gb, 
				ps.storage_gb, 
				i.quantity, 
				y.years, 
				i.list_price, 
				i.unit_price,
				i.tax_item_total,
				i.order_item_offer_amount
		from cart_order_item i with (nolock)
		inner join product p with (nolock)
			on i.product_id = p.product_id
		left join product_license_category plc with (nolock)
			on i.product_id = plc.product_id
		left join license_category lc with (nolock)
			on plc.license_category_id = lc.license_category_id
		left join product_years y with (nolock)
			on i.product_id = y.product_id
		left join product_seat s with (nolock)
			on i.product_id = s.product_id
		left join product_storage ps with (nolock)
			on i.product_id = ps.product_id
		left join cart_order_item_license il with (nolock)
			on i.cart_order_item_id = il.cart_order_item_id
		left join license l with (nolock)
			on il.keycode = l.keycode
		where i.cart_order_id = @cart_order_id and p.product_family_id not in (1,2,30,31,50,51,55,100,200,300)


		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) return result
		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) update summary
		update @item_summary
		set product_type = case 
								when keycode is null or max_product_type_id = 1 then 'New'
								when s.max_product_type_id = 4 and s.product_type_id = 1 then 'New'
								when s.current_license_category_id = s.license_category_id and years > 0 and current_seats = seats and storage_gb > current_storage_gb then 'Renew/Storage Upgrade'
								
								when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years > 0 and current_seats <> seats then ' Upgrade/Renewal'
								--when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years > 0 and current_seats <> seats then convert(varchar(20),(seats - current_seats)) + ' Seat Upgrade/Renewal'
								when s.product_family_id in (55,300) and s.current_license_category_id = s.license_category_id and years = 0 then convert(varchar(20),(seats)) + ' Seat Upgrade'

								
								when s.product_family_id not in (55,300) and s.current_license_category_id = s
.license_category_id and years > 0 and current_seats <> seats then ' Upgrade/Renewal'
								when s.product_family_id not in (55,300) and s.current_license_category_id = s.license_category_id and years = 0 and current_seats <> seats then ' Upgrade'
								when s.current_license_category_id is null and current_storage_gb < storage_gb then 'Storage Upgrade'
								when s.current_license_category_id <> s.license_category_id and years = 0 then 'Product Upgrade'
								when s.current_license_category_id <> s.license_category_id and years > 0 then 'Product Upgrade/Renewal'
								when s.current_license_category_id = s.license_category_id and years > 0 then 'Renewal'
								else 'New'
							end,
				product_description = case 
						when s.product_family_id in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 then lc.license_category_description  + ' ' + convert(varchar(10),years) + ' Year' + ' ' + convert(varchar(10),seats) + ' Seat '
						when s.product_family_id in (55,300) and p.product_description is null and seats is not null and years = 0 then lc.license_category_description 
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 and storage_gb is null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),years) + ' Year'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years <> 0 and storage_gb is not null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),storage_gb) + ' GB ' + convert(varchar(10),years) + ' Year'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years = 0 and storage_gb is null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat'
						when s.product_family_id not in (55,300) and p.product_description is null and seats is not null and years is not null and years = 0 and storage_gb is not null then lc.license_category_description + ' ' + convert(varchar(10),seats) + ' Seat ' + convert(varchar(10),storage_gb) + ' GB'
						when p.product_description is null then lc.license_category_description
						else p.product_description
					end
		from @item_summary s
		left join product p
			on s.product_id = p.product_id
		left join license_category lc
			on s.license_category_id = lc.license_category_id

		
		-- 2.2) get bundle details
		declare @cart_discount_bundle_description nvarchar(200), @cart_discount_bundle_details_list nvarchar(1000), @license_distribution_method_id int, @license_distribution_method_code varchar(4)
		
		select @cart_discount_bundle_description = cart_discount_bundle_description, @cart_discount_bundle_details_list = cart_discount_bundle_details_list
		from cart_discount_bundle b
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join cart_order_message m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.cart_order_id = @cart_order_id

		select @license_distribution_method_id = dm.license_distribution_method_id, @license_distribution_method_code = dm.license_distribution_method_code
		from cart_discount_license_distribution_method b
		inner join license_distribution_method dm
			on b.license_distribution_method_id = dm.license_distribution_method_id
		inner join cart_discount d
			on b.cart_discount_id = d.cart_discount_id
		inner join cart_order_message m
			on d.cart_discount_key = m.message_key or d.cart_discount_id = m.cart_discount_id
		where m.cart_order_id = @cart_order_id

		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		--
 3.) return result
		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		select	s.cart_item_bundle_id,
				cart_order_item_id,
				product_locale,
				product_type,
				p.product_id,
				product_description = s.product_description + ' ' + s.product_type,
				f.product_family_description,
				lc.license_category_name,
				lc.license_category_description,
				seats,
				storage_gb,
				quantity,
				years,
				list_price,
				unit_price,
				tax_item_total,
				order_item_offer_amount,
				keycode,
				p.product_type_id,
				max_product_type_id,
				current_license_category_id,
				lc.license_category_id, 
				current_seats,
				current_storage_gb,
				pl.product_line_cart_type
				,
				cart_discount_bundle_description = case when s.cart_item_bundle_id = 1 then @cart_discount_bundle_description else null end, 
				cart_discount_bundle_details_list = case when s.cart_item_bundle_id = 1 then @cart_discount_bundle_details_list else null end,
				license_distribution_method_id = case when s.cart_item_bundle_id = 1 then @license_distribution_method_id else null end, 
				license_distribution_method_code = case when s.cart_item_bundle_id = 1 then @license_distribution_method_code else null end
		from @item_summary s
		left join product p
			on s.product_id = p.product_id
		left join product_family f
			on s.product_family_id = f.product_family_id
		left join product_line pl
			on s.product_line_id = pl.product_line_id
		left join license_category lc
			on s.license_category_id = lc.license_category_id
		where s.product_type_id is not null and
			s.cart_item_bundle_id = case
										when @cart_item_bundle_id is null then s.cart_item_bundle_id
										else @cart_item_bundle_id
									end
		order by s.cart_item_bundle_id, unit_price desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_cart_shipping]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_cart_shipping]

(
	@vendor_order_code varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select s.cart_shipping_id, s.cart_order_id, s.company_name, s.first_name, s.last_name, s.address_1, s.address_2, s.city, s.state, s.postal_code, s.country_id, s.last_modified
	from cart_shipping s
	inner join cart_order o
		on s.cart_order_id = o.cart_order_id
	where o.vendor_order_code = @vendor_order_code
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_credit_card_update_batch]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_payment_select_credit_card_update_batch]
(
@payment_subscription_credit_card_batch_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2016-10-10	acoffel		Initial creation.
	2020-02-18	wbarton		Modifying the select based on changes to payment_subscription_credit_card_batch and payment_subscription_credit_card_update

	DESCRIPTION
	Selects individual records associated with a payment_subscription_credit_card_batch_id
	
*/

AS
set nocount on				

begin try

declare	@response_code int, @message varchar(100)

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Selecting individual records associated with the payment_subscription_credit_card_batch_id
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select u.payment_subscription_credit_card_update_id, b.payment_subscription_credit_card_batch_id, u.license_message_id, u.payment_header_id, b.merchant_id, u.credit_card_subscription_id, b.attempts
	from payment_subscription_credit_card_update u
	inner join payment_subscription_credit_card_batch b
		on u.payment_subscription_credit_card_batch_id = b.payment_subscription_credit_card_batch_id
	where u.payment_subscription_credit_card_batch_id = @payment_subscription_credit_card_batch_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'selecting the batch failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	select @response_code as response_code, @message as message
		
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_customer_cybs_subscription]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_customer_cybs_subscription]

(
	@customer_id int = null,
	@company_id int = null,
	@salesforce_account_id varchar(18) = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-02-09		esmart			Initial creation
	2019-08-14		esmart			add json log_text
	
	DESCRIPTION
	select cybs_subscriptipons
*/

as

	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @company_id is null and @salesforce_account_id is not null
		begin
		select @company_id = company_id from company where salesforce_account_id = @salesforce_account_id
		end

	select sc.cybs_subscription_customer_id, 
		sc.customer_id, cu.first_name, cu.last_name, e.customer_email,
		sc.company_id,	co.company_name, co.salesforce_account_id,
		s.cybs_subscription_id, s.payment_merchant_id, m.merchant_id, s.credit_card_subscription_id, s.account_number, s.expiration_month, s.expiration_year, s.card_type_id, c.card_type_description, s.insert_date,
		l.log_text
	from cybs_subscription_customer sc
	inner join customer cu
		on cu.customer_id = sc.customer_id
	inner join customer_email e
		on e.customer_id = sc.customer_id and e.email_status_id = 1
	left join company co
		on co.company_id = sc.company_id
	inner join cybs_subscription s
		on s.cybs_subscription_id = sc.cybs_subscription_id
	inner join payment_merchant m
		on m.payment_merchant_id = s.payment_merchant_id
	left join card_type c
		on c.card_type_id = s.card_type_id
	left join cybs_subscription_log l
		on s.cybs_subscription_id = l.cybs_subscription_id and l.log_type = 'request'
	where sc.customer_id = @customer_id or
			sc.company_id = @company_id
	order by 1 desc


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update oracle contract failed'
							else @message end

