-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_export_violation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_export_violation]

(
	@start_date datetime,
	@end_date datetime,
	@vendor_order_code nvarchar(40)
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-06-01		mrobbins			Initial creation

	DESCRIPTION
	selects payment export violations
*/

AS
	
	set nocount on			

	declare	@response_text nvarchar(max),
			@response_code int,
			@message varchar(100)

	begin try

		declare @payment_violations  table (payment_response_id int)

		if (@start_date is not null and @end_date is not null)
			begin
				
				insert into @payment_violations
				select distinct pev.payment_response_id
				from payment_export_violation pev
					inner join payment_response pr
						on pev.payment_response_id = pr.payment_response_id
				where pev.response_name = 'list'
					and pev.payment_export_violation_status_id = 0
					and pr.insert_date >= @start_date
					and pr.insert_date < @end_date + 1

				select distinct pv.payment_response_id,
					stuff((select (', ' + response_value)
						from @payment_violations pv2
						inner join payment_export_violation p
							on pv2.payment_response_id = p.payment_response_id
						where p.response_name = 'list'
							and pv2.payment_response_id = pv.payment_response_id
						for xml path ('')), 1, 1, '') as list,
					stuff((select (', ' + response_value)
						from @payment_violations pv2
						inner join payment_export_violation p
							on pv2.payment_response_id = p.payment_response_id
						where p.response_name = 'program'
							and pv2.payment_response_id = pv.payment_response_id
						for xml path ('')), 1, 1, '') as program,
					co.total_amount,
					co.sub_total_amount,
					co.tax_amount,
					c.currency_code,
					co.submission_date,
					co.vendor_order_code,
					cu.first_name,
					cu.last_name
				from @payment_violations pv
					inner join payment_response pr
						on pv.payment_response_id = pr.payment_response_id
					inner join payment_header ph
						on pr.payment_header_id = ph.payment_header_id
					left join cart_order co
						on ph.cart_order_id = co.cart_order_id
					left join cart_order_customer coc
						on co.cart_order_id = coc.cart_order_id
					left join customer cu
						on coc.customer_id = cu.customer_id
					left join currency c
						on co.currency_id = c.currency_id
			end

		if @vendor_order_code is not null
			begin


				insert into @payment_violations
				select distinct pev.payment_response_id
				from payment_export_violation pev
					inner join payment_response pr
						on pev.payment_response_id = pr.payment_response_id
					inner join payment_header ph
						on pr.payment_header_id = ph.payment_header_id
					inner join cart_order co
						on ph.cart_order_id = co.cart_order_id
				where pev.response_name = 'list'
					and pev.payment_export_violation_status_id = 0
					and co.vendor_order_code = @vendor_order_code
					

				select distinct pv.payment_response_id,
					stuff((select (', ' + response_value)
						from @payment_violations pv2
						inner join payment_export_violation p
							on pv2.payment_response_id = p.payment_response_id
						where p.response_name = 'list'
							and pv2.payment_response_id = pv.payment_response_id
						for xml path ('')), 1, 1, '') as list,
					stuff((select (', ' + response_value)
						from @payment_violations pv2
						inner join payment_export_violation p
							on pv2.payment_response_id = p.payment_response_id
						where p.response_name = 'program'
							and pv2.payment_response_id = pv.payment_response_id
						for xml path ('')), 1, 1, '') as program,
					co.total_amount,
					co.sub_total_amount,
					co.tax_amount,
					c.currency_code,
					co.submission_date,
					co.vendor_order_code,
					cu.first_name,
					cu.last_name
				from @payment_violations pv
					
inner join payment_response pr
						on pv.payment_response_id = pr.payment_response_id
					inner join payment_header ph
						on pr.payment_header_id = ph.payment_header_id
					left join cart_order co
						on ph.cart_order_id = co.cart_order_id
					left join cart_order_customer coc
						on co.cart_order_id = coc.cart_order_id
					left join customer cu
						on coc.customer_id = cu.customer_id
					left join currency c
						on co.currency_id = c.currency_id
			end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_next_credit_card_update_batch]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_payment_select_next_credit_card_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2016-10-10	acoffel		Initial creation.
	2020-02-18	wbarton		Refactoring for performance and accomodating table changes

	DESCRIPTION
	Selects the next batch requiring processing
	
*/

AS
set nocount on				

begin try

declare @response_code int, @message varchar(100)

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Selecting the oldest batch that has not been completed or attempted 3 times, along with its record count
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select b.payment_subscription_credit_card_batch_id, s.payment_subscription_credit_card_batch_status_description, b.cybs_batch_id, b.merchant_id, count(u.credit_card_subscription_id) as batch_count
	from payment_subscription_credit_card_update u
		inner join (
			select min(payment_subscription_credit_card_batch_id) as min_batch_id
			from dbo.payment_subscription_credit_card_batch
			where payment_subscription_credit_card_batch_status_id <> 3
				and attempts <= 3
				and process_date < getdate()
		) ub
			on u.payment_subscription_credit_card_batch_id = ub.min_batch_id
		inner join payment_subscription_credit_card_batch b
			on b.payment_subscription_credit_card_batch_id = u.payment_subscription_credit_card_batch_id
		inner join payment_subscription_credit_card_batch_status s
			on s.payment_subscription_credit_card_batch_status_id = b.payment_subscription_credit_card_batch_status_id
	group by b.payment_subscription_credit_card_batch_id, s.payment_subscription_credit_card_batch_status_description, b.cybs_batch_id, b.merchant_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select batch failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	select @response_code as response_code, @message as message
		
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_payment_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_payment_account]

(
	@vendor_order_code varchar(50) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2015-01-27	esmart		Salesforce payments
	2019-03-07	esmart		Use credit card subscription@credit_card_subscription_id to fix null returned for AR orders.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @credit_card_subscription_id varchar(24),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

		-- 1.1.4) @payment_subscription_credit_card_id
		select @credit_card_subscription_id = c.credit_card_subscription_id
		from payment_subscription_credit_card c
		where c.payment_header_id = @payment_header_id

	-- 1.2) select payment_header_transaction
	select top(1) a.payment_account_id, a.payment_header_id, a.account_number, a.expiration_month, a.expiration_year, a.card_type_id, t.card_type_description, a.last_modified_date
	from payment_account a
	inner join payment_subscription_credit_card cc
		on a.payment_header_id = cc.payment_header_id
	left join card_type t
		on a.card_type_id = t.card_type_id
	where cc.credit_card_subscription_id = @credit_card_subscription_id and a.account_number is not null
	order by a.payment_account_id desc

	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_payment_account_by_customer_email]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_payment_account_by_customer_email]

(
	@customer_email varchar(100)
)
	
/*	
	DATE		AUTHOR		REMARKS
	2015-09-10	 esmart		Initial creation
	
	DESCRIPTION
	select payment accounts
	
*/

AS
	
	set nocount on			

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select distinct 
		a.payment_account_id,
		a.account_number,
		a.expiration_month,
		a.expiration_year,
		a.card_type_id,
		cc.payment_subscription_credit_card_id,
		cc.credit_card_subscription_id,
		op.payment_header_id, 
		m.merchant_id, 
		st.payment_status_id,
		st.payment_status_name, 
		pm.payment_method_name, 
		cu.currency_code,
		ct.card_type_description,
		h.last_modified_date
	from customer_email e
	inner join customer_order o
		on o.customer_id = e.customer_id
	inner join order_payment_header op
		on op.order_header_id = o.order_header_id
	inner join payment_header h
		on op.payment_header_id = h.payment_header_id
	inner join payment_merchant m
		on h.payment_merchant_id = m.payment_merchant_id
	inner join payment_status st
		on h.payment_status_id = st.payment_status_id
	inner join currency cu
		on h.currency_id = cu.currency_id
	inner join payment_method pm
		on h.payment_method_id = pm.payment_method_id
	inner join payment_subscription_credit_card cc
		on h.payment_header_id = cc.payment_header_id
	inner join payment_account a
		on h.payment_header_id = a.payment_header_id
	inner join card_type ct
		on a.card_type_id = ct.card_type_id
	where e.customer_email = @customer_email and e.email_status_id = 1
	order by a.payment_account_id desc

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
