-- =============================================================================
CREATE PROCEDURE [dbo].[usp_payment_select_payment_header]

(
	@vendor_order_code varchar(50) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null,
	@oracle_invoice_number int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation
	2011-09-08	esmart		Add currency 
	2012-11-13	esmart		Add generic payment action and payment_header_lookup
	2014-03-21	esmart		PO data
	2015-01-27	esmart		Salesforce payments
	2017-01-30	esmart		Add @oracle_invoice_number
	2017-03-15	cnovac		added subscription_id to select at end
	2021-05-11	g.lagos		SCA project returning new column ht.payment_network_transaction_string

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@payment_header_token_id int,
			@purchase_order_id int, 
			@purchase_order varchar(100), 
			@purchase_order_date datetime,
			@order_header_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	
	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

		
		-- 1.1.4) @order_invoice_number
		if @payment_header_id is null and @oracle_invoice_number is not null
			begin
			select @payment_header_id = (select top 1 payment_header_id from order_payment_header where oracle_invoice_number = @oracle_invoice_number order by payment_header_id desc)
			end


	-- 1.2) get last token
	select @payment_header_token_id = max(payment_header_token_id) 
	from payment_header_token
	where payment_header_id = @payment_header_id

	

	-- 1.4) purchase order
	select @purchase_order_id = purchase_order_id, @purchase_order = purchase_order, @purchase_order_date = purchase_order_date, @order_header_id = ph.order_header_id
	from purchase_order po
	inner join order_payment_header ph
		on po.order_header_id = ph.order_header_id
	where ph.payment_header_id = @payment_header_id

	
	select h.payment_header_id, 
			m.merchant_id, 
			s.payment_status_name, 
			pm.payment_method_name, 
			cu.currency_code,
			t.request_id, 
			t.request_token, 
			a.payment_action_name,
			ht.authorization_transaction_id, 
			ht.settlement_transaction_id,
			ht.payment
_network_transaction_string,   -- SCA Project
			purchase_order_id = @purchase_order_id, 
			purchase_order = @purchase_order, 
			purchase_order_date = @purchase_order_date,
			order_header_id = @order_header_id,
			isnull(pscc.credit_card_subscription_id, psp.billing_agreement_id) as subscription_id
	from payment_header h
	inner join payment_merchant m
		on h.payment_merchant_id = m.payment_merchant_id
	inner join payment_status s
		on h.payment_status_id = s.payment_status_id
	inner join currency cu
		on h.currency_id = cu.currency_id
	left join payment_method pm
		on h.payment_method_id = pm.payment_method_id
	left join payment_header_token t
		on h.payment_header_id = t.payment_header_id and t.payment_header_token_id = @payment_header_token_id
	left join payment_action a
		on t.payment_action_id = a.payment_action_id
	left join payment_header_transaction ht
		on h.payment_header_id = ht.payment_header_id
	left join payment_subscription_credit_card pscc
		on pscc.payment_header_id = h.payment_header_id
	left join payment_subscription_paypal psp
		on psp.payment_header_id = h.payment_header_id
	where h.payment_header_id = @payment_header_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_payment_header_paypal]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_payment_header_paypal]

(
	@vendor_order_code varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-11-13	esmart		Add generic payment action and payment_header_lookup
	2014-12-11	esmart		Add capture_request_id

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@payment_header_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get payment header data from old cart_in_process 
	select @payment_header_id = p.payment_header_id
	from cart_in_process c
	inner join payment_header_cart_in_process p
		on c.cart_in_process_id = p.cart_in_process_id
	where c.invoice_code = @vendor_order_code

		-- 1.1.1) get payment header data
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

	-- 1.2) select payment_header_transaction
	select payment_header_paypal_id, payment_header_id, setup_request_id, paypal_token, paypal_payer, paypal_payer_id, capture_request_id, last_modified_date
	from payment_header_paypal
	where payment_header_id = @payment_header_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
