-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_select_payment_request_response_audit]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_select_payment_request_response_audit]

(
	@vendor_order_code varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-03-15	esmart		Modify request/response text to be nvarchar
	2012-11-13	esmart		Add generic payment action and payment_header_lookup

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@payment_header_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get payment header data from old cart_in_process 
	select @payment_header_id = p.payment_header_id
	from cart_in_process c
	inner join payment_header_cart_in_process p
		on c.cart_in_process_id = p.cart_in_process_id
	where c.invoice_code = @vendor_order_code

		-- 1.1.1) get payment header data
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

	-- 1.2) select payment_header_transaction
	declare @request_response_audit table (payment_header_id int, data_type varchar(20), payment_method_name varchar(50), payment_action_name varchar(50), request_response_text nvarchar(max), response_code varchar(50), response_message varchar(120), insert_date datetime)

	insert into @request_response_audit(payment_header_id, data_type, payment_method_name, payment_action_name, request_response_text, response_code, response_message, insert_date)
	select payment_header_id, data_type = 'request', payment_method_name, payment_action_name, 
		request_text = case 
							when request_text is null then request_text_var
							else request_text
						end, 
		response_code = '', response_message = '', insert_date
	from payment_request r
	inner join payment_method m
		on r.payment_method_id = m.payment_method_id
	inner join payment_action a
		on r.payment_action_id = a.payment_action_id
	where r.payment_header_id = @payment_header_id

	insert into @request_response_audit(payment_header_id, data_type, payment_method_name, payment_action_name, request_response_text, response_code, response_message, insert_date)
	select r.payment_header_id, data_type = 'response', payment_method_name, payment_action_name, 
		response_text = case 
							when response_text is null then response_text_var
							else response_text
						end, 
		response_code, response_message, r.insert_date
	from payment_response r
	inner join payment_header h
		on r.payment_header_id = h.payment_header_id and r.insert_date = h.last_modified_date
	inner join payment_header_token t
		on r.payment_header_id = t.payment_header_id and r.insert_date = t.insert_date
	inner join payment_method m
		on h.payment_method_id = m.payment_method_id
	inner join payment_action a
		on t.payment_action_id = a.payment_action_id
	where r.payment_header_id = @payment_header_id

	insert into @request_response_audit(payment_header_id, data_type, payment_method_name, payment_action_name, request_response_text, response_code, response_message, insert_date)
	select r.payment_header_id, data_type = 'response', payment_method_name, payment_action_name, response_text = case 
							when response_text is null then response_text_var
							else response_text
						end, 
		response_code, response_message, r.insert_date
	from payment_response r
	
inner join payment_header h
		on r.payment_header_id = h.payment_header_id
	inner join payment_header_audit ha
		on r.payment_header_id = ha.payment_header_id and r.insert_date = ha.last_modified_date
	inner join payment_header_token t
		on r.payment_header_id = t.payment_header_id and r.insert_date = t.insert_date
	inner join payment_method m
		on h.payment_method_id = m.payment_method_id
	inner join payment_action a
		on t.payment_action_id = a.payment_action_id
	where r.payment_header_id = @payment_header_id

	select * 
	from @request_response_audit
	order by payment_header_id desc, insert_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
