CREATE PROCEDURE [dbo].[usp_payment_select_payment_subscription_credit_card]

(
	@vendor_order_code varchar(50) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = NULL,
	@credit_card_subscription_id varchar(24) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-23	esmart		Initial creation.
	2012-11-13	esmart		Add generic payment action and payment_header_lookup
	2022-04-21	gblandford	ALM-1119	- add column mit_id
										- add parameter @credit_card_subscription_id to allow retrieval of all rows for a specific
										  subscription, this will yield multiple rows and potentially different recordset
	2022-05-04	gblandford	Fixed optional parameter (= null)
										

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @payment_subscription_credit_card_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	if @credit_card_subscription_id is null begin

	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
				select @payment_header_id = payment_header_id
				from dbo.cart_order c
				inner join dbo.payment_header h
					on c.cart_order_id = h.cart_order_id
				where c.vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
				select @payment_header_id = payment_header_id
				from dbo.vendor_order v
				inner join dbo.order_header h
					on v.vendor_order_id = h.vendor_order_id
				inner join dbo.order_payment_header op
					on h.order_header_id = op.order_header_id
				where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
				select @payment_header_id = payment_header_id
				from dbo.payment_header_opportunity 
				where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from dbo.cart_in_process c
				inner join dbo.payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end


		-- 1.2) get @payment_subscription_credit_card_id
		select 
			payment_subscription_credit_card_id
			, payment_header_id
			, credit_card_subscription_id
			, mit_id
			, last_modified_date
		from dbo.payment_subscription_credit_card
		where payment_header_id = @payment_header_id	

	end	else begin 

		-- 2.1) get payment_subscription_credit_card using the credit_card_subscription_id
		select 
			payment_subscription_credit_card_id
			, payment_header_id
			, credit_card_subscription_id
			, mit_id
			, last_modified_date
		from dbo.payment_subscription_credit_card
		where credit_card_subscription_id = @credit_card_subscription_id	
	end
    
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
