CREATE PROCEDURE [dbo].[usp_payment_select_request_response_audit]

(
	@vendor_order_code varchar(50) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_request_id int = null,
	@payment_header_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-27	esmart		Initial creation.

	DESCRIPTION
	Select payment request and response
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get payment header data from cart_order 
	select @payment_header_id = payment_header_id
	from cart_order c
	inner join payment_header h
		on c.cart_order_id = h.cart_order_id
	where vendor_order_code = @vendor_order_code

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @request_response table (request_response int identity(1,1), payment_header_id int, payment_request_id int, payment_response_id int, payment_method_id tinyint, payment_action_id tinyint, response_code varchar(50), response_message varchar(120), request_text nvarchar(max), response_text nvarchar(max), insert_date datetime)

		-- 2.1) insert
		insert into @request_response(payment_request_id, payment_header_id, payment_method_id, payment_action_id, insert_date, request_text)
		select payment_request_id, payment_header_id, payment_method_id, payment_action_id, insert_date, request_text
		from payment_request r
		where payment_header_id = @payment_header_id
		order by 1
			
		insert into @request_response(payment_response_id, payment_header_id, response_code, response_message, insert_date, response_text)
		select payment_response_id, payment_header_id, response_code, response_message, insert_date, response_text
		from payment_response
		where payment_header_id = @payment_header_id
		order by 1

		-- 2.2) remove r
		if @payment_request_id is not null
			begin
			-- 2.1) 
				select request_response, payment_header_id, payment_request_id, payment_response_id, payment_method_id, payment_action_id, response_code, response_message, request_text, response_text, insert_date
				from @request_respon
se 
				where payment_request_id = @payment_request_id
			end
		else
			begin
			-- 2.2.2) return
				select request_response, payment_header_id, payment_request_id, payment_response_id, payment_method_id, payment_action_id, response_code, response_message, request_text, response_text, insert_date
				from @request_response
				order by insert_date, request_response
			end

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
