-- PROCEDURE: [dbo].[usp_payment_update_credit_card_batch]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_payment_update_credit_card_batch]

(
@payment_subscription_credit_card_batch_id int,
@cybs_batch_id varchar(50) = null,
@cybs_batch_response varchar(255) = null,
@payment_subscription_credit_card_batch_status varchar(20) 
)

/*	
	DATE		AUTHOR		REMARKS
	2016-10-10	acoffel		Initial creation.
	2020-02-18	wbarton		Refactoring process_date update logic and changes to support table modifications
	2020-05-14	wbarton		Updating last_modified_date on payment_subscription_credit_card_batch. This was missed originally.

	DESCRIPTION
	Inserts an archive record and updates payment_subscription_credit_card_batch 
	
*/

AS
set nocount on				

begin try

declare @response_code int, @message varchar(100), @payment_subscription_credit_card_batch_status_id tinyint

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Insert header record into archive table
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	insert into payment_subscription_credit_card_batch_archive (payment_subscription_credit_card_batch_id, process_date, merchant_id, cybs_batch_id, cybs_batch_response, attempts, last_modified_date, archive_date, payment_subscription_credit_card_batch_status_id)
	select payment_subscription_credit_card_batch_id, process_date, merchant_id, cybs_batch_id, cybs_batch_response, attempts, last_modified_date, getdate(), payment_subscription_credit_card_batch_status_id
	from payment_subscription_credit_card_batch
	where payment_subscription_credit_card_batch_id = @payment_subscription_credit_card_batch_id

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Find the proper status id, and update the payment_subscription_credit_card_batch record
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @payment_subscription_credit_card_batch_status_id = s.payment_subscription_credit_card_batch_status_id 
	from payment_subscription_credit_card_batch_status s
	where s.payment_subscription_credit_card_batch_status_description = @payment_subscription_credit_card_batch_status
	
	--Per Cybes' documentation, batches can take up to 3 days to fully process. Setting process_date 3 days out on the first update, and 1 day out for each subsequent attempt.
	update payment_subscription_credit_card_batch 
	set payment_subscription_credit_card_batch_status_id = @payment_subscription_credit_card_batch_status_id, cybs_batch_id = @cybs_batch_id, cybs_batch_response = @cybs_batch_response, 
		process_date = case when @payment_subscription_credit_card_batch_status_id <> 3 and attempts = 0 then dateadd(day, 3, getdate()) 
			when @payment_subscription_credit_card_batch_status_id <> 3 and attempts > 0 then dateadd(day, 1, getdate()) 
			else process_date end, 
		attempts = attempts + 1,
		last_modified_date = getdate()
	where payment_subscription_credit_card_batch_id = @payment_subscription_credit_card_batch_id

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'updating batch status failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	select @response_code as respon
se_code, @message as message
		
end catch;

GO
