CREATE PROCEDURE [dbo].[usp_payment_update_credit_card_update]
(
	@payment_subscription_credit_card_update_id int,
	@payment_subscription_credit_card_batch_id int,
	@credit_card_subscription_id varchar(24),
	@response_code varchar(50) = null,
	@reason_code varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2016-10-10	acoffel		Initial creation.
	2020-02-18	wbarton		Minor changes to support table modifications

	DESCRIPTION
	Updates records for a given batch in payment_subscription_credit_card_update
	
*/

AS
set nocount on				

declare	@response_code_sp int, @message varchar(100)

begin try


	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--Update payment_subscription_credit_card_update 
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	update payment_subscription_credit_card_update 
	set response_code = @response_code, reason_code = @reason_code, last_modified_date = getdate(), credit_card_subscription_id = @credit_card_subscription_id
	where payment_subscription_credit_card_update_id = @payment_subscription_credit_card_update_id
		and payment_subscription_credit_card_batch_id = @payment_subscription_credit_card_batch_id
	
end try

begin catch

	set @response_code_sp = -200
	set @message = case when @message is null then 'select failed' else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

	select @response_code_sp as response_code, @message as message
		
end catch;

GO
