(
	@vendor_order_code varchar(50),
	@status varchar(50)
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-06-03		mrobbins			Initial creation

	DESCRIPTION
	Updates payment_export_violation_status_id
*/

AS
	
	set nocount on			

	declare	@response_text nvarchar(max),
			@response_code int,
			@message varchar(100)

	begin try

		if @status = 'violation'
			begin
				update pev 
				set payment_export_violation_status_id = 1
				from payment_export_violation pev
					inner join payment_response pr
						on pev.payment_response_id = pr.payment_response_id
					inner join payment_header ph
						on pr.payment_header_id = ph.payment_header_id
					inner join cart_order co
						on ph.cart_order_id = co.cart_order_id
				where co.vendor_order_code = @vendor_order_code
			end
		
		if @status = 'completed'
			begin
				update pev 
				set payment_export_violation_status_id = 2
				from payment_export_violation pev
					inner join payment_response pr
						on pev.payment_response_id = pr.payment_response_id
					inner join payment_header ph
						on pr.payment_header_id = ph.payment_header_id
					inner join cart_order co
						on ph.cart_order_id = co.cart_order_id
				where co.vendor_order_code = @vendor_order_code
			end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update export violation failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_update_payment_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_update_payment_account]

(
	@vendor_order_code varchar(50) = null,
	@account_number varchar(50),
	@expiration_month tinyint,
	@expiration_year smallint,
	@card_type_id int,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null

)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-10-28	esmart		payment_header_id lookup
	2015-01-27	esmart		Salesforce payments

	DESCRIPTION
	•	account_number -  var $accountNumber; (Shrouded/last 4 digits, XXXXXXXXXXXX1234)
	•	expiration_month - var $expirationMonth;
	•	expiration_year -  var $expirationYear;
	•	card_type_id  - var $cardType;   integer

*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) insert into payment_account
	insert into payment_account(payment_header_id, account_number, expiration_month, expiration_year, card_type_id)	
	values(@payment_header_id, @account_number, @expiration_month, @expiration_year, @card_type_id)


	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_update_payment_header]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_update_payment_header]

(
	@vendor_order_code varchar(50) = null,
	@payment_method_name varchar(50),
	@payment_action_name varchar(50),
	@request_id varchar(24),
	@request_token varchar(100),
	@response_code int,
	@response_message varchar(10),
	@response_text nvarchar(max),
	@merchant_id varchar(50),
	@currency_code char(3),
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-03-15  esmart		Update @response_text to nvar
	2012-10-26	esmart		Add generic payment action and payment_header_id lookup
	2014-04-23	esmart		Check method changes
	2015-01-27	esmart		Salesforce payments

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @payment_status_id tinyint,
			@payment_action_id tinyint,
			@payment_method_id tinyint,
			@payment_merchant_id tinyint,
			@currency_id tinyint,
			@current_payment_status_id tinyint,
			@transaction_date datetime,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate()

	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = ph.payment_header_id,
					@current_payment_status_id = ph.payment_status_id	
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			inner join payment_header ph
				on op.payment_header_id = ph.payment_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = ph.payment_header_id,
					@current_payment_status_id = ph.payment_status_id	
			from payment_header_opportunity o
			inner join payment_header ph
				on o.payment_header_id = ph.payment_header_id
			where o.salesforce_opportunity_id = @salesforce_opportunity_id
			end

		-- 1.1.3) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id,
					@current_payment_status_id = h.payment_status_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				inner join payment_header h
					on h.payment_header_id = p.payment_header_id
				where c.invoice_code = @vendor_order_code
			end

	-- 1.2) determine @payment_status_id
		select @payment_status_id = payment_status_id
		from payment_status_method_action s
		inner join payment_method m
			on s.payment_method_id = m.payment_method_id
		inner join payment_action a
			on s.payment_action_id = a.payment_action_id
		where m.payment_method_name = @payment_method_name and 
			a.payment_action_name = @payment_action_name

		-- 1.2.1) if @payment_status_id is null
		if @payment_status_id is null
			begin
			select @payment_status_id = @current_payment_status_id
			end

		if @payment_status_id is null
			begin
			select @payment_status_id = payment_status_id from 
payment_header where payment_header_id = @payment_header_id
			end

	-- 1.3) get @payment_action_id
		select @payment_action_id = payment_action_id
		from payment_action
		where payment_action_name = @payment_action_name

	if @payment_action_id is null
		begin
		select @payment_action_id = payment_action_id
		from payment_action
		where payment_action_name = 'Generic'
		end

	-- 1.4) get @payment_method_id
	if @payment_method_name is null or @payment_method_name = ''
		begin
		select @payment_method_id = payment_method_id
		from payment_header
		where payment_header_id = @payment_header_id
		end
	else
		begin
		select @payment_method_id = payment_method_id
		from payment_method
		where payment_method_name = @payment_method_name
		end

	-- 1.5) @merchant_id
	if @merchant_id is null or @merchant_id = ''
		begin
		select @payment_merchant_id = payment_merchant_id
		from payment_header
		where payment_header_id = @payment_header_id
		end
	else
		begin
		select @payment_merchant_id = payment_merchant_id
		from payment_merchant
		where merchant_id = @merchant_id
		end

	-- 1.6) @currency_code
	if @currency_code is null or @currency_code = ''
		begin
		select @currency_id = currency_id
		from payment_header
		where payment_header_id = @payment_header_id
		end
	else
		begin
		select @currency_id = currency_id
		from currency 
		where currency_code = @currency_code
		end

--select cart_order_id = @cart_order_id, payment_header_id = @payment_header_id, payment_status_id = @payment_status_id, payment_action_id = @payment_action_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) update payment_header
		-- 2.1.1) insert payment_header_audit 
		insert into payment_header_audit(payment_header_id, cart_order_id, payment_merchant_id, payment_method_id, payment_status_id, currency_id, last_modified_date, audit_date)
		select payment_header_id, cart_order_id, payment_merchant_id, payment_method_id, payment_status_id, currency_id, last_modified_date, audit_date = @transaction_date
		from payment_header
		where payment_header_id = @payment_header_id		

		-- 2.1.2) update payment header
		update payment_header
		set payment_status_id = @payment_status_id, 
			payment_method_id = @payment_method_id, 
			payment_merchant_id = @payment_merchant_id, 
			currency_id = @currency_id,
			last_modified_date = @transaction_date
		where payment_header_id = @payment_header_id
		
	-- 2.2) insert payment_header_token
	if @request_id is not null 
		begin
		insert into payment_header_token(payment_header_id, request_id, request_token, payment_action_id, insert_date)
		values(@payment_header_id, @request_id, @request_token, @payment_action_id, @transaction_date)	
		end

	-- 2.3) insert payment_response
	if @response_code is not null
		begin
		insert into payment_response(payment_header_id, response_text, response_code, response_message, insert_date)
		values(@payment_header_id, @response_text, @response_code, @response_message, @transaction_date)
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_update_payment_header_in_process]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_update_payment_header_in_process]

(
	@vendor_order_code varchar(50),
	@merchant_id varchar(50),
	@payment_method_name varchar(50) = null,
	@currency_code char(3) = null,
	@message_key varchar(36) = null
	
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-25	esmart		Initial creation.

	DESCRIPTION
	Temporary procedure to insert payment_header from old in_process
	
*/

AS
	set nocount on				

	declare @payment_header_id int,
			@cart_in_process_id int,
			@payment_status_id tinyint,
			@payment_merchant_id tinyint,
			@payment_method_id tinyint,
			@transaction_date datetime,
			@currency_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate(),
			@payment_status_id = 1
	
	-- 1.1) get @cart_in_process_id
	select @cart_in_process_id = cart_in_process_id
	from cart_in_process
	where invoice_code = @vendor_order_code

	-- 1.2) get @payment_merchant_id
	select @payment_merchant_id = payment_merchant_id
	from payment_merchant
	where merchant_id = @merchant_id

	-- 1.3 get @payment_method_id
	if @payment_method_name is null or @payment_method_name = ''
		begin
		select @payment_method_id = payment_method_id
		from payment_header
		where payment_header_id = @payment_header_id
		end
	else
		begin
		select @payment_method_id = payment_method_id
		from payment_method
		where payment_method_name = @payment_method_name
		end


	-- 1.4) @currency_id
	select @currency_id = currency_id
	from currency 
	where currency_code = @currency_code

	if @currency_id is null
		begin
		select @currency_id = 1
		end

	-- 1.5) update payment_header
	select @payment_header_id = payment_header_id 
	from payment_header_cart_in_process
	where cart_in_process_id = @cart_in_process_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert payment_header
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) update payment_header
		-- 2.1.1) insert payment_header_audit 
		insert into payment_header_audit(payment_header_id, cart_order_id, payment_merchant_id, payment_method_id, payment_status_id, currency_id, last_modified_date, audit_date)
		select payment_header_id, cart_order_id, payment_merchant_id, payment_method_id, payment_status_id, currency_id, last_modified_date, audit_date = @transaction_date
		from payment_header
		where payment_header_id = @payment_header_id		

		-- 2.1.2) update payment header
		update payment_header
		set payment_method_id = @payment_method_id, 
			payment_merchant_id = @payment_merchant_id, 
			currency_id = @currency_id,
			last_modified_date = @transaction_date
		where payment_header_id = @payment_header_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_update_payment_header_paypal]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_update_payment_header_paypal]

(
	@vendor_order_code varchar(50),
	@setup_request_id varchar(24),
	@paypal_token varchar(24), 
	@paypal_payer varchar(100), 
	@paypal_payer_id varchar(24),
	@capture_request_id varchar(24) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-10-28	esmart		payment_header_id lookup
	2014-12-11	esmart		Add capture_request_id

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@payment_header_id int,
			@payment_header_paypal_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate()

	-- 1.1) get payment header data from old cart_in_process 
	select @payment_header_id = p.payment_header_id
	from cart_in_process c
	inner join payment_header_cart_in_process p
		on c.cart_in_process_id = p.cart_in_process_id
	where c.invoice_code = @vendor_order_code

		-- 1.1.1) get payment header data
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

	-- 1.2) get payment_header_paypal_id
	select @payment_header_paypal_id = payment_header_paypal_id
	from payment_header_paypal
	where payment_header_id = @payment_header_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_header_paypal_id is not null
	-- 2.1) update payment_header_paypal
		begin
		
		-- 2.1.1) get current transaction_ids if the inputs are NULL or blank
		if @setup_request_id is null or @setup_request_id = ''
			begin
			select @setup_request_id = setup_request_id from payment_header_paypal where payment_header_id = @payment_header_id 
			end

		if @paypal_token is null or @paypal_token = ''
			begin
			select @paypal_token = paypal_token from payment_header_paypal where payment_header_id = @payment_header_id 
			end

		if @paypal_payer is null or @paypal_payer = ''
			begin
			select @paypal_payer = paypal_payer from payment_header_paypal where payment_header_id = @payment_header_id 
			end

		if @paypal_payer_id is null or @paypal_payer_id = ''
			begin
			select @paypal_payer_id = paypal_payer_id from payment_header_paypal where payment_header_id = @payment_header_id 
			end

		if @capture_request_id is null or @capture_request_id = ''
			begin
			select @capture_request_id = capture_request_id from payment_header_paypal where payment_header_id = @payment_header_id 
			end

		-- 2.1.2) insert payment_header_paypal_audit
		insert into payment_header_paypal_audit(payment_header_paypal_id, payment_header_id, setup_request_id, paypal_token, paypal_payer, paypal_payer_id, capture_request_id, last_modified_date, audit_date)
		select payment_header_paypal_id, payment_header_id, setup_request_id, paypal_token, paypal_payer, paypal_payer_id, capture_request_id, last_modified_date, audit_date = @transaction_date
		from payment
_header_paypal
		where payment_header_id = @payment_header_id
	
		-- 2.1.3) update payment_header_paypal
		update payment_header_paypal
		set setup_request_id = @setup_request_id,
			paypal_token = @paypal_token, 
			paypal_payer = @paypal_payer, 
			paypal_payer_id = @paypal_payer_id, 
			capture_request_id = @capture_request_id,
			last_modified_date = @transaction_date
		where payment_header_id = @payment_header_id	

		end
	else
	-- 2.2) insert payment_header_paypal
		begin
		insert into payment_header_paypal(payment_header_id, setup_request_id, paypal_token, paypal_payer, paypal_payer_id, capture_request_id)
		values(@payment_header_id, @setup_request_id, @paypal_token, @paypal_payer, @paypal_payer_id, @capture_request_id)

		end

		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_payment_update_payment_header_transaction]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_payment_update_payment_header_transaction]

(
	@vendor_order_code varchar(50) = null,
	@authorization_transaction_id varchar(24), 
	@settlement_transaction_id varchar(24),
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = NULL,
	@payment_network_transaction_string varchar(30) = NULL  -- SCA Project

)

/*	
	DATE		AUTHOR		REMARKS
	2011-02-05	esmart		Initial creation.
	2012-10-28	esmart		payment_header_id lookup
	2015-01-27	esmart		Salesforce payments
	2021-05-11	g.lagos		SCA Project including SCA transaction string payment_network_transaction_string

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @payment_header_transaction_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @transaction_date = getdate()


	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data - order_payment_header
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from vendor_order v
			inner join order_header h
				on v.vendor_order_id = h.vendor_order_id
			inner join order_payment_header op
				on h.order_header_id = op.order_header_id
			where v.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) get payment header data - OLD CART
		if @payment_header_id is null 
			begin
				select @payment_header_id = p.payment_header_id
				from cart_in_process c
				inner join payment_header_cart_in_process p
					on c.cart_in_process_id = p.cart_in_process_id
				where c.invoice_code = @vendor_order_code
			end

		-- 1.1.3) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end

	-- 1.2) get payment_header_transaction_id
	select @payment_header_transaction_id = payment_header_transaction_id
	from payment_header_transaction
	where payment_header_id = @payment_header_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_header_transaction_id is not null
	-- 2.1) update payment_header_transaction
		begin
		
		-- 2.1.1) get current transaction_ids if the inputs are NULL or blank
		if @authorization_transaction_id is null or @authorization_transaction_id = ''
			begin
			select @authorization_transaction_id = authorization_transaction_id from payment_header_transaction where payment_header_id = @payment_header_id 
			end
		if @settlement_transaction_id is null or @settlement_transaction_id = ''
			begin
			select @settlement_transaction_id = settlement_transaction_id fro
m payment_header_transaction where payment_header_id = @payment_header_id 
			end
		
		-- 2.1.2) insert payment_header_transaction_audit
		insert into payment_header_transaction_audit(
			payment_header_transaction_id, 
			payment_header_id, 
			authorization_transaction_id, 
			settlement_transaction_id, 
			last_modified_date, 
			audit_date,
			payment_network_transaction_string) -- SCA Project 
		select 
			payment_header_transaction_id, 
			payment_header_id, 
			authorization_transaction_id, 
			settlement_transaction_id, 
			last_modified_date, 
			audit_date = @transaction_date,
			@payment_network_transaction_string 
		from payment_header_transaction
		where payment_header_id = @payment_header_id
	
		-- 2.1.3) update payment_header_transaction
		if @payment_network_transaction_string is NULL
		   begin
				update payment_header_transaction
				set authorization_transaction_id = @authorization_transaction_id, 
				settlement_transaction_id = @settlement_transaction_id,
				last_modified_date = @transaction_date
				where payment_header_id = @payment_header_id	
			end
		else
		   begin
				update payment_header_transaction
				set authorization_transaction_id = @authorization_transaction_id, 
				settlement_transaction_id = @settlement_transaction_id,
				last_modified_date = @transaction_date,
				payment_network_transaction_string=@payment_network_transaction_string -- SCA Project
				where payment_header_id = @payment_header_id	
			end
		end
	else
	-- 2.2) insert payment_header_transaction
		begin
		insert into payment_header_transaction(
			payment_header_id, 
			authorization_transaction_id, 
			settlement_transaction_id,
			Payment_network_transaction_string)
		values(
			@payment_header_id, 
			@authorization_transaction_id, 
			@settlement_transaction_id,
			@payment_network_transaction_string)

		end
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
