CREATE PROCEDURE [dbo].[usp_payment_update_payment_subscription_credit_card]

(
	@vendor_order_code varchar(50) = null,
	@credit_card_subscription_id varchar(24),
	@mit_id VARCHAR(15) = null,
	@salesforce_opportunity_id varchar(18) = null,
	@payment_header_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-23	esmart		Initial creation.
	2012-10-28	esmart		payment_header_id lookup
	2015-01-27	esmart		Salesforce payments
	2022-04-21	gblandford	ALM-1119 - add column mit_id
	2022-09-30	gblandford	Pre-deploy Cyan change - @mit_id is optional

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @payment_subscription_credit_card_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	select @transaction_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get payment header data from cart_order 
		if @payment_header_id is null 
			begin
			select @payment_header_id = h.payment_header_id
			from dbo.cart_order c
			inner join dbo.payment_header h
				on c.cart_order_id = h.cart_order_id
			where c.vendor_order_code = @vendor_order_code
			end

		-- 1.1.1) get payment header data
		if @payment_header_id is null 
			begin
			select @payment_header_id = h.payment_header_id
			from dbo.cart_order c
			inner join dbo.payment_header h
				on c.cart_order_id = h.cart_order_id
			where c.vendor_order_code = @vendor_order_code
			end

		-- 1.1.2) @salesforce_opportunity_id
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from dbo.payment_header_opportunity 
			where salesforce_opportunity_id = @salesforce_opportunity_id
			end


	-- 1.1) get @payment_subscription_credit_card_id
	select @payment_subscription_credit_card_id = payment_subscription_credit_card_id
	from dbo.payment_subscription_credit_card
	where payment_header_id = @payment_header_id	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_subscription_credit_card_id is null
	-- 2.1) insert row
		begin
			insert into payment_subscription_credit_card(
				payment_header_id
				, credit_card_subscription_id
				, mit_id)
			values(@payment_header_id
			, @credit_card_subscription_id
			, @mit_id)
		end
	else
	-- 2.2) update
		begin
			-- 2.2.1) get current transaction_ids if the inputs are NULL or blank
			if isnull(@credit_card_subscription_id, '') = '' OR isnull(@mit_id, '') = ''
				begin
					select 
						@credit_card_subscription_id = ( case 
															when isnull(@credit_card_subscription_id, '') = '' then credit_card_subscription_id 
															else @credit_card_subscription_id
														end )
						, @mit_id = ( case 
										when ISNULL(@mit_id, '') = '' then mit_id 
										else @mit_id
									end )

					from dbo.payment_subscription_credit_card 
					where payment_subscription_credit_card_id = @payment_subscription_credit_card_id 
				end
		
			-- 2.2.2) audit
			inser
t into dbo.payment_subscription_credit_card_audit(
				payment_subscription_credit_card_id
				, payment_header_id
				, credit_card_subscription_id
				, mit_id
				, last_modified_date
				, audit_date)
			select payment_subscription_credit_card_id
				, payment_header_id
				, credit_card_subscription_id
				, mit_id
				, last_modified_date
				, audit_date = @transaction_date
			from dbo.payment_subscription_credit_card 
			where payment_subscription_credit_card_id = @payment_subscription_credit_card_id

			-- 2.2.3) update
			update dbo.payment_subscription_credit_card 
				set credit_card_subscription_id = @credit_card_subscription_id,
					mit_id = @mit_id,
					last_modified_date = @transaction_date
			where payment_subscription_credit_card_id = @payment_subscription_credit_card_id
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
