CREATE PROCEDURE [dbo].[usp_payment_update_payment_subscription_paypal]

(
	@vendor_order_code varchar(50),
	@billing_agreement_id varchar(24),
	@paypal_customer_email varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-23	esmart		Initial creation.
	2012-10-28	esmart		payment_header_id lookup

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @payment_header_id int,
			@payment_subscription_paypal_id int,
			@transaction_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	select @transaction_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get payment header data from old cart_in_process 
	select @payment_header_id = p.payment_header_id
	from cart_in_process c
	inner join payment_header_cart_in_process p
		on c.cart_in_process_id = p.cart_in_process_id
	where c.invoice_code = @vendor_order_code

		-- 1.1.1) get payment header data
		if @payment_header_id is null 
			begin
			select @payment_header_id = payment_header_id
			from cart_order c
			inner join payment_header h
				on c.cart_order_id = h.cart_order_id
			where vendor_order_code = @vendor_order_code
			end

	-- 1.1) get @payment_subscription_paypal_id
	select @payment_subscription_paypal_id = payment_subscription_paypal_id
	from payment_subscription_paypal
	where payment_header_id = @payment_header_id	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_subscription_paypal_id is null
	-- 2.1) insert row
		begin
		insert into payment_subscription_paypal(payment_header_id, billing_agreement_id, paypal_customer_email)
		values(@payment_header_id, @billing_agreement_id, @paypal_customer_email)
		end
	else
	-- 2.2) update
		begin
		-- 2.2.1) get current transaction_ids if the inputs are NULL or blank
		if @billing_agreement_id is null or @billing_agreement_id = ''
			begin
			select @billing_agreement_id = billing_agreement_id 
			from payment_subscription_paypal
			where payment_subscription_paypal_id = @payment_subscription_paypal_id	
			end
		if @paypal_customer_email is null or @paypal_customer_email = ''
			begin
			select @paypal_customer_email = paypal_customer_email 
			from payment_subscription_paypal
			where payment_subscription_paypal_id = @payment_subscription_paypal_id	
			end
		
		-- 2.2.2) audit
		insert into payment_subscription_paypal_audit(payment_subscription_paypal_id, payment_header_id, billing_agreement_id, paypal_customer_email, last_modified_date, audit_date)
		select payment_subscription_paypal_id, payment_header_id, billing_agreement_id, paypal_customer_email, last_modified_date, audit_date = @transaction_date
		from payment_subscription_paypal 
		where payment_subscription_paypal_id = @payment_subscription_paypal_id

		-- 2.2.2) update
		update payment_subscription_paypal 
		set billing_agreement_id = @billing_agreement_id,
			paypal_customer_email = @paypal_customer_email,
			last_modified_date = @transaction_date
		where payment_subscription_paypal_id = @payment_subscription_paypal_id
		end

	end try

	begin catch

		set @respo
nse_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
