CREATE PROCEDURE [dbo].[usp_payment_update_purchase_order]

(
	@vendor_order_code varchar(50),
	@purchase_order varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-10-24	esmart		Initial creation.

	DESCRIPTION
	update purchase order
*/

AS
	set nocount on				

	declare	@payment_header_id int,
			@payment_header_purchase_order_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get payment header data from old cart_in_process 
	select @payment_header_id = p.payment_header_id
	from cart_in_process c
	inner join payment_header_cart_in_process p
		on c.cart_in_process_id = p.cart_in_process_id
	where c.invoice_code = @vendor_order_code

	-- 1.1.1) get payment header data
	if @payment_header_id is null 
		begin
		select @payment_header_id = payment_header_id
		from cart_order c
		inner join payment_header h
			on c.cart_order_id = h.cart_order_id
		where vendor_order_code = @vendor_order_code
		end

	-- 1.2) @payment_header_purchase_order_id
	select @payment_header_purchase_order_id = payment_header_purchase_order_id
	from payment_header_purchase_order
	where payment_header_id = @payment_header_id
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @payment_header_purchase_order_id is null
	-- 2.1) insert
		begin
			insert into payment_header_purchase_order(payment_header_id,purchase_order) 
			values(@payment_header_id,@purchase_order)
		end
	else
	-- 2.2) update
		begin
			update payment_header_purchase_order
			set purchase_order = @purchase_order
			where payment_header_id = @payment_header_id
		end

	-- 2.3) update payment_header
	insert into payment_header_audit(payment_header_id, cart_order_id, payment_merchant_id, payment_status_id, currency_id, last_modified_date, payment_method_id)
	select payment_header_id, cart_order_id, payment_merchant_id, payment_status_id, currency_id, last_modified_date, payment_method_id
	from payment_header
	where payment_header_id = @payment_header_id

	update payment_header
	set last_modified_date = getdate(), payment_method_id = 5 -- PurchaseOrder
	where payment_header_id = @payment_header_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
