CREATE PROCEDURE [dbo].[usp_permission_select_group]

(	
	@permission_application_id tinyint = null,
	@permission_group_name varchar(50) = null,
	@user_name varchar(100) = null
)


/*	
	DATE		AUTHOR		REMARKS
	2014-07-14	esmart		Initial creation.
	2015-05-27	esmart		Add user_name for select criteria
	2020-05-20	wbarton		Small change so we return only 'active' permission groups

	DESCRIPTION
	select
*/

AS
	set nocount on				

	declare	@admin_member tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @admin_member = count(*)
	from permission_group_membership m
	inner join permission_group g
		on m.permission_group_id = g.permission_group_id
	where m.user_name = @user_name and g.permission_group_id in (2,19) and g.permission_application_id = @permission_application_id

	if @admin_member > 0 
		begin 
		select @user_name = null
		end

	-- 1.1) @user_name
	if @user_name is not null
		begin
			select g.permission_group_id, g.permission_group_name, g.permission_group_status
			from permission_group_membership m
			inner join permission_group g
				on m.permission_group_id = g.permission_group_id
			where m.user_name = @user_name and g.permission_application_id = @permission_application_id
				and g.permission_group_status = 'active'
		end
	-- 1.2) all groups
	else
		begin
			select permission_group_id, permission_group_name, permission_group_status
			from permission_group
			where permission_application_id = case when @permission_application_id is null then permission_application_id else @permission_application_id end and
					permission_group_name = case when @permission_group_name is null then permission_group_name else @permission_group_name end
				and permission_group_status = 'active'
			order by permission_group_name
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
