	select a.permission_application_id, a.permission_application_name, g.permission_group_id, g.permission_group_name, g.permission_group_status, gm.user_name
	from permission_group_membership gm
	inner join permission_application a
		on gm.permission_application_id = a.permission_application_id
	inner join permission_group g
		on gm.permission_group_id = g.permission_group_id
	where gm.permission_application_id = case when @permission_application_id is null then gm.permission_application_id else @permission_application_id end and
		gm.user_name = case when @user_name is null then gm.user_name else @user_name end and
		gm.permission_group_id = case when @permission_group_id is null then gm.permission_group_id else @permission_group_id end
	order by g.permission_group_id, gm.user_name

	end try

	begin catch

