-- =============================================================================


CREATE PROCEDURE [dbo].[usp_permission_select_group_resource]

(	
	@permission_group_id int = null,
	@assigned varchar(20) = null
)


/*	
	DATE		AUTHOR		REMARKS
	2014-07-14	esmart		Initial creation.
	2015-07-06	esmart		Add @permission_application_id

	DESCRIPTION
	Select
*/

AS
	set nocount on				

	declare @permission_application_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @assigned
	if @assigned is null
		begin
		select @assigned = 'assigned'
		end

	-- 1.2) @permission_application_id
	select @permission_application_id = permission_application_id 
	from permission_group
	where permission_group_id = @permission_group_id
	
	-- 1.3) return list
	if @assigned = 'assigned'
		begin
			select g.permission_group_id, g.permission_group_name, r.permission_resource_id, r.resource_name, r.access_level, r.permission_application_id
			from permission_resource r
			inner join permission_group_resource gr
				on gr.permission_resource_id = r.permission_resource_id
			inner join permission_group g
				on gr.permission_group_id = g.permission_group_id
			where g.permission_group_id = case when @permission_group_id is null then g.permission_group_id else @permission_group_id end 
			order by g.permission_group_id, r.resource_name, r.access_level
		end
	else
		begin
			select g.permission_group_id, g.permission_group_name, r.permission_resource_id, r.resource_name, r.access_level, r.permission_application_id
			from permission_resource r
			left join permission_group_resource gr
				on gr.permission_resource_id = r.permission_resource_id and gr.permission_group_id = @permission_group_id
			left join permission_group g
				on gr.permission_group_id = g.permission_group_id
			where gr.permission_group_resource_id is null and r.permission_application_id = @permission_application_id
			order by g.permission_group_id, r.resource_name, r.access_level
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_permission_select_resource]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_permission_select_resource]

(	
	@permission_application_id tinyint,
	@permission_resource_id int = null,
	@resource_name varchar(50) = null, 
	@access_level varchar(50) = null
)


/*	
	DATE		AUTHOR		REMARKS
	2014-07-14	esmart		Initial creation.
	2015-07-06	esmart		Add @permission_application_id

	DESCRIPTION
	select
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @permission_resource_id
	if @permission_resource_id is not null
		begin
			select permission_resource_id, resource_name, access_level
			from permission_resource
			where permission_resource_id = @permission_resource_id and permission_application_id = @permission_application_id
		end
	-- 1.2) @resource_name and/or access_level
	else
		begin
			-- 1.2.1) no @access_level
			if @access_level is null
				begin
				select permission_resource_id, resource_name, access_level
				from permission_resource
				where resource_name = case when @resource_name is not null then @resource_name else resource_name end and 
					permission_application_id = @permission_application_id
				order by resource_name, access_level
				end
			-- 1.2.2) @access_level
			else
				begin
				select permission_resource_id, resource_name, access_level
				from permission_resource
				where resource_name = case when @resource_name is not null then @resource_name else resource_name end and
					  access_level = case when @access_level is not null then @access_level else access_level end and 
					  permission_application_id = @permission_application_id
				order by resource_name, access_level
				end
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_permission_select_user_resource]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_permission_select_user_resource]

(	
	@user_name varchar(100),
	@permission_application_name varchar(50)=null
)


/*	
	DATE		AUTHOR		REMARKS
	2014-07-14	esmart		Initial creation.
	2014-08-26	esmart		Add default group for RESELLER application
	2017-09-29	esmart		Remove reseller app default

	DESCRIPTION
	Select
*/

AS
	set nocount on				

	declare	@permission_application_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	if @permission_application_name is null
		begin
		select @permission_application_name = 'CSI'
		end
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get application
	select @permission_application_id = permission_application_id
	from permission_application
	where permission_application_name = @permission_application_name

	-- 1.2) log user
	insert into permission_log(permission_application_id, user_name)
	values(@permission_application_id,@user_name)

	-- 1.2) return results
	select r.permission_resource_id, r.resource_name, r.access_level
	from permission_group_membership m
	inner join permission_group_resource gr
		on m.permission_group_id = gr.permission_group_id
	inner join permission_resource r
		on gr.permission_resource_id = r.permission_resource_id
	where m.user_name = @user_name and m.permission_application_id = @permission_application_id
	union
	select r.permission_resource_id, r.resource_name, r.access_level
	from permission_group_resource gr
	inner join permission_resource r
		on gr.permission_resource_id = r.permission_resource_id
	where gr.permission_group_id =  case 
										when @permission_application_id = 1 then 1 
										-- when @permission_application_id = 2 then 18
									end
	order by r.resource_name, r.access_level

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_permission_update_group_resource]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_permission_update_group_resource]

(	
	@permission_group_id tinyint,
	@assigned varchar(20),
	@permission_resource_id_list varchar(500)
)


/*	
	DATE		AUTHOR		REMARKS
	2014-07-14	esmart		Initial creation.
	2015-01-06	esmart		@permission_resource.permission_resource_id to int 

	DESCRIPTION
	select
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @permission_resource table (permission_resource_id int)

	insert into @permission_resource(permission_resource_id)
	select integer_value from dbo.fn_integer_string_to_table(@permission_resource_id_list)

	select permission_resource_id from @permission_resource

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) assign
	if @assigned = 'assigned'
		begin
		
		insert into permission_group_resource(permission_group_id, permission_resource_id)
		select @permission_group_id, r.permission_resource_id
		from @permission_resource r
		left join permission_group_resource g
			on r.permission_resource_id = g.permission_resource_id and g.permission_group_id = @permission_group_id
		where g.permission_group_resource_id is null

		end

	-- 2.2) unassign
	if @assigned = 'unassigned'
		begin

		delete from permission_group_resource
		where permission_group_id = @permission_group_id and permission_resource_id in (select permission_resource_id from @permission_resource)

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
