-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_insert_beta_upgrade]

(
		@customer_email varchar(100),
		@first_name nvarchar(225),
		@last_name nvarchar(225),
		@opt_in int,
		@customer_id int = null,
		@license_message_key varchar(36)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-07-18	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@license_message_id int,
			@insert_date datetime,
			@response_code int,
			@message varchar(100)

	select	@response_code = 0,
			@message = 'Success',
			@insert_date = getdate()

	if @customer_email = '' 
		begin
		select @customer_email = null
		end

	if @customer_id = 0
		begin
		select @customer_id = null
		end

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) get license_message data
	select @license_id = lm.license_id,
			@license_message_id = lm.license_message_id
	from license_message lm
	where license_message_key = @license_message_key

	if @license_id is null
	-- 1.1.1) check license_message archive
		begin
		select @license_id = lm.license_id,
				@license_message_id = lm.license_message_id
		from license_message_archive lm
		where license_message_key = @license_message_key

		if @license_id is null
		-- 1.1.2) if license_message_key is not found send user to manual new registration
			begin
			select response_code = -112, message = 'Invalid license_message_key. Complete new license registration'
			return
			end
		end
	
	-- 1.2) insert license_registration
	if @customer_id is null
		begin
		-- 1.2.1) get customer_id
			select @customer_id = e.customer_id
			from customer_email e with (nolock)
			where e.customer_email = @customer_email and e.email_status_id = 1

			if @customer_id is null
				begin
				select @customer_id = max(e.customer_id)
				from customer_email e with (nolock)
				where e.customer_email = @customer_email and e.email_status_id = 1
				end

		-- 1.2.2) if no match for customer then insert a new customer
			if @customer_id is null
				begin
				exec usp_customer_insert_customer @first_name, null, @last_name, null, @opt_in, @customer_email, NULL, @customer_id output
				end

		--	1.2.3 update license
			update license 
			set customer_id = @customer_id 
			where license_id = @license_id
		end
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert registration
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) prevx_beta_upgrade
		insert into prevx_beta_upgrade(license_id, customer_email, first_name, last_name, insert_date)
		values(@license_id, @customer_email, @first_name, @last_name, @insert_date)

	-- 2.2) prevx_update
		insert into prevx_update(license_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
		select l.license_id, prevx_update_type_id = 1, prevx_update_status_id = 0, insert_date = getdate(), modified_date = getdate(), process_date = getdate()
		from license l
		left join prevx_update u
			on l.license_id = u.license_id
		where l.license_id = @license_id and u.prevx_update_id is null

	-- 2.3) archive license_message
		insert into license_message_archive(license_message_id
, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date)
		select license_message_id, license_id, license_message_key, message_type_id, message_status_id, insert_date, process_date, end_date
		from license_message
		where license_message_id = @license_message_id
		
		insert into license_message_value_archive(license_message_value_id, license_message_id, message_value_type_id, value_id)
		select v.license_message_value_id, v.license_message_id, v.message_value_type_id, v.value_id
		from license_message_value v
		where v.license_message_id = @license_message_id
		
		delete from license_message_value where license_message_id = @license_message_id
		delete from license_message where license_message_id = @license_message_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) retrun result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select keycode, response_code = @response_code, [message] = @message
		from license 
		where license_id = @license_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
