CREATE PROCEDURE [dbo].[usp_prevx_insert_license_update]

(
		@license_id int,
		@prevx_update_type_id tinyint, 
		@prevx_update_status_id tinyint,
		@process_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-18	esmart		Initial creation.
	2014-05-08	esmart		Add defaults

	DESCRIPTION

	We commented Out return as per Anthony for sky_api_license
	
*/

AS
	set nocount on				

	declare	@insert_date datetime,
			@license_status_id int,
			@response_code int,
			@message varchar(100)

	select @response_code = 0,
			@insert_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @process_date
	if @process_date is null
		begin
		select @process_date = @insert_date
		end	

	-- 1.2) @prevx_update_type_id
	if @prevx_update_type_id is null
		begin
		select @prevx_update_type_id = 2
		end

	-- 1.3) @prevx_update_status_id
	if @prevx_update_status_id is null
		begin
		select @prevx_update_status_id = 0
		end

	-- 1.4) sky_api_license
	if exists (select license_id from sky_api_license where license_id = @license_id)
		begin
		insert into sky_update (license_id, sky_template_id, sky_update_type_id,process_date)
		values(@license_id,4,4,@process_date)
		--return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into prevx_update(license_id, prevx_update_type_id, prevx_update_status_id, insert_date, modified_date, process_date)
	values(@license_id, @prevx_update_type_id, @prevx_update_status_id, @insert_date, @insert_date, @process_date)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
