CREATE PROCEDURE [dbo].[usp_prevx_insert_mar_update]

(
	@ReferenceID int,
	@MARID int,
	@MARType char(1),
	@MarName varchar(50),
	@MARIDParent int,
	@Keycode varchar(40),
	@UBID bigint,
	@Email varchar(100),
	@Password varchar(64),
	@FirstName nvarchar(225),
	@LastName nvarchar(225),
	@DisplayName nvarchar(225),
	@UserStatusName varchar(50),
	@EncryptionKeyHash varchar(128),
	@UberUserType varchar(20) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-06-23	esmart		Initial creation.
	2011-08-15	esmart		New columns
	2017-09-07	esmart		Suppress non-mar licenses

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@prevx_mar_update_id int,
			@license_id int,
			@mar_type_id tinyint,
			@mar_status_id tinyint,
			@mar_user_type_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @license_id
	if @keycode <> ''
		begin
		select @license_id = license_id from license where keycode = @keycode
		end

	-- 1.2) @mar_type_id
	select @mar_type_id = mar_type_id from mar_type where mar_type_code = @MARType
	
		-- 1.2.1) check for null type
		if @mar_type_id is null
			begin
			select @mar_type_id = mar_type_id from mar where mar_id = @MARID

			if @mar_type_id is null
				begin
				select @mar_type_id = 0
				end
			end

	-- 1.3) @MarName
	if @MarName is null
		begin
		select @MarName = ''
		end
	
	-- 1.4) @UserStatusName
	select @mar_status_id = mar_status_id from mar_status where mar_status_name = @UserStatusName

	-- 1.5) @UberUserType
	select @mar_user_type_id = mar_user_type_id from mar_user_type where mar_user_type_code = @UberUserType

		-- 1.5.1) check for null type
		if @mar_user_type_id is null
			begin
			select @mar_user_type_id = 2
			end
		
	-- 1.6) @EncryptionKeyHash
	if @EncryptionKeyHash = '00'
		begin
		select @EncryptionKeyHash = null
		end

	-- 1.7) suppress insert of non-marid
	if @MARID < 0
		begin
		select prevx_mar_update_id = -1
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert prevx_mar_update
	insert into prevx_mar_update(reference_id, mar_id, mar_type_id, mar_name, parent_mar_id, license_id, mar_user_id, user_email, user_password, first_name, last_name, display_name, mar_status_id, encryption_key_hash)
	values(@ReferenceID,@MARID,@mar_type_id,@MarName,@MARIDParent,@license_id,@UBID,@Email,@Password,@FirstName,@LastName,@DisplayName,@mar_status_id,@EncryptionKeyHash)

	select @prevx_mar_update_id = scope_identity()

	-- 2.2) add ServiceBroker
	--exec usp_prevx_insert_mar_update_queue @prevx_mar_update_id

	-- 2.3) return @prevx_mar_update_id
	select prevx_mar_update_id = @prevx_mar_update_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert prevx mar update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catc
h;
GO
