CREATE PROCEDURE [dbo].[usp_prevx_insert_prevx_keycode_update_queue]

(		
	@prevx_keycode_update_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2011-10-16	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	begin try

	set nocount on 

	-- 1) insert task queue 
	declare @sql_string varchar(4000),
			@task_number varchar(10),	
			@db_name varchar(100),
			@system_user varchar(50),
			@response_code int,
			@message varchar(100)

	select @system_user = suser_sname(),
			@db_name = db_name()

	select @task_number = @prevx_keycode_update_id --(select isnull(max(task_number),0) from tasks..task_table) + 10
		select @sql_string = 
			'insert into tasks..task_table (task_number, Command, NoTransaction, StartTime) ' + 
			' values	(' + @task_number + ',' + '''' + 'exec ' + @db_name + '..usp_license_update_keycode_alias ' + convert(varchar(10),@prevx_keycode_update_id) + '''' + ',0,getdate()) '

	--print @sql_string

	exec (@sql_string)

	exec tasks..usp_queue_task @prevx_keycode_update_id

	end try

	begin catch


	set @response_code = -200
	set @message = case when @message is null then 'Could not insert for @prevx_keycode_update_id = ' + convert(varchar(20),@prevx_keycode_update_id)
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	end catch;
	

GO
