CREATE PROCEDURE [dbo].[usp_prevx_insert_prevx_update]

(
		@keycode varchar(40)				
)

/*	
	DATE		AUTHOR		REMARKS
	2011-10-24	esmart		Initial creation.
	2017-06-23	esmart		sky_update_license

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @license_id
	select @license_id = license_id
	from license
	where keycode = @keycode

	-- 1.2) sky_api_license
	if exists (select license_id from sky_api_license where license_id = @license_id)
		begin
		insert into sky_update_license (license_id)
		values(@license_id)
		return
		end
	else
		begin
		insert into prevx_update_license(license_id)
		values(@license_id)
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_select_license_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_select_license_account]

(
	@license_id int
)


/*	
	DATE		AUTHOR		REMARKS
	2011-03-18	esmart		Initial creation.
	2011-09-27	esmart		Add andoid only account status exception	
	2011-09-29	esmart		Add lookup for device only licenses

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@mar_id int,
			@mar_user_id int,
			@account_user_name varchar(100),
			@account_password varchar(64),
			@account_customer_id int,
			@account_first_name nvarchar(225),
			@account_last_name nvarchar(225),
			@account_customer_email varchar(100),

			@license_category_id int,
			
			@customer_id int,
			@first_name nvarchar(225),
			@last_name nvarchar(225),
			@customer_email varchar(100),

			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) Select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) @license_category_id
		select @license_category_id = license_category_id 
		from license_category_license
		where license_id = @license_id	

		-- 1.2) mar data
		select @mar_id = ml.mar_id,
				@mar_user_id = mu.mar_user_id
		from mar_license ml
		left join mar_user mu
			on ml.mar_id = mu.mar_id
		left join mar_user_account ma
			on mu.mar_user_id = ma.mar_user_id
		left join account_license al
			on ma.account_id = al.account_id
		left join account a
			on al.account_id = a.account_id and a.account_type_id = 1
		where ml.license_id = @license_id
		
		-- 1.3) account data
		select  @account_user_name = account_user_name, 
				@account_password = account_password,
				@account_customer_id = ac.customer_id,
				@account_first_name = c.first_name,
				@account_last_name = c.last_name,
				@account_customer_email = e.customer_email
		from account_license al
		inner join account a
			on al.account_id = a.account_id and a.account_type_id = 1 and (a.account_status_id = 1 or (@license_category_id in (50,51) and a.account_status_id = 0))
		left join account_customer ac
			on al.account_id = ac.account_id
		left join customer c
			on ac.customer_id = c.customer_id
		left join customer_email e
			on c.customer_id = e.customer_id and e.email_status_id = 1
		where al.license_id = @license_id

		-- 1.3.1) check acccount device
			if @account_user_name is null
				begin
				select  @account_user_name = account_user_name, 
						@account_password = account_password,
						@account_customer_id = ac.customer_id,
						@account_first_name = c.first_name,
						@account_last_name = c.last_name,
						@account_customer_email = e.customer_email
				from account a
				left join account_customer ac
					on a.account_id = ac.account_id
				left join customer c
					on ac.customer_id = c.customer_id
				left join customer_email e
					on c.customer_id = e.customer_id and e.email_status_id = 1
				where a.account_id = (select top 1 account_id from account_device where license_id = @license_id order by account_id desc) and 
					a.account_type_id = 1 and 
					(a.account_status_id = 1 or (@license_category_id in (50,51) and a.account_status_id = 0))
				end
		

		-- 1.4) customer data
		select @customer_id = c.customer_id,
				@first_name = c.first_name,
				@last_name = c.last_name,
				@customer_email = e.customer_email
		from license l
		inner join customer c
			on l.customer_id = c.customer_id
		inner join customer_email e
			on c.customer_id = e.customer_id and e.email_status_id = 1
		where l.license_id = @license_id

--		select account_user_name = @
account_user_name, 
--				account_password = @account_password,
--				account_customer_id = @account_customer_id,
--				account_first_name = @account_first_name,
--				account_last_name = @account_last_name,
--				account_customer_email = @account_customer_email,
--				customer_id = @customer_id,
--				first_name = @first_name,
--				last_name = @last_name,
--				customer_email = @customer_email

		-----------------------------------------------------------------------------------------------------------------------------------------	
		-- 2) Results
		-----------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) return results
		select  MARID = @mar_id,
				UBID = @mar_user_id,
				account_user_name = @account_user_name, 
				account_password = @account_password,
				first_name = case
								when @account_customer_email is not null then @account_first_name
								when @account_customer_email is null and @account_user_name is not null and @account_user_name = @customer_email then @first_name
								when @account_customer_email is null and @account_user_name is null then @first_name
								else ''
							end,
				last_name = case
								when @account_customer_email is not null then @account_last_name
								when @account_customer_email is null and @account_user_name is not null and @account_user_name = @customer_email then @last_name
								when @account_customer_email is null and @account_user_name is null then @last_name
								else ''
							end,
				customer_email = case
								when @account_customer_email is not null then @account_customer_email
								when @account_customer_email is null and @account_user_name is not null and @account_user_name = @customer_email then @customer_email
								when @account_customer_email is null and @account_user_name is null then @customer_email
								else ''
							end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_select_mar_update_details]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_select_mar_update_details]

(
	@license_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2011-08-25	acoffel		Initial creation.
	2012-12-26	esmart		Change sort

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100),
			@mar_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		--1.1) set mar_id
		select @mar_id = m.mar_id
		from mar m inner join mar_license l on m.mar_id = l.mar_id 
		where l.license_id = @license_id

		if (select @mar_id) is NULL
			begin
				select @response_code = -110, @message = 'No mar_id found for that license'
				select response_code = @response_code, [message] = @message
				return
			end		

		--1.2 get entries
		select source = 'queue', u.insert_date, NULL as archive_date, u.reference_id, u.mar_name, t.mar_type_name, u.user_email, u.first_name, u.last_name, s.mar_status_name, m.mar_user_type_name
		from prevx_mar_update u
		left join mar_type t
			on u.mar_type_id = t.mar_type_id
		left join mar_status s
			on u.mar_status_id = s.mar_status_id
		left join mar_user_type m
			on u.mar_user_type_id = m.mar_user_type_id 
		where u.mar_id = @mar_id
		union
		select source = 'archive', a.insert_date, a.archive_date, a.reference_id, a.mar_name, t.mar_type_name, a.user_email, a.first_name, a.last_name, s.mar_status_name, m.mar_user_type_name
		from prevx_mar_update_archive a
		left join mar_type t
			on a.mar_type_id = t.mar_type_id
		left join mar_status s
			on a.mar_status_id = s.mar_status_id
		left join mar_user_type m
			on a.mar_user_type_id = m.mar_user_type_id
		where a.mar_id = @mar_id
		order by insert_date desc


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_select_next_s2_update_bulk]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_select_next_s2_update_bulk]

(
	@prevx_update_type_id tinyint,
	@batch_size int,
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-02	esmart		Initial creation.
	2011-10-10	esmart		Add left joins to license_category_license and license_seat
	2023-08-08	gblandford	https://jira.opentext.com/browse/ECOM-1984 - remove extra sb.contract_id from output
							- added dbo. schema to objects

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try
	
	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if @prevx_update_type_id in (1,2,3,4,100)
	-- 1.1) license data
		begin
		select x.prevx_update_s2_id,
				x.prevx_update_type_id,
				x.prevx_update_type_name,
				l.license_id, 
				l.keycode, 
				lt.license_type_id,
				lt.license_type_description,
				st.license_status_id,
				st.license_status_description,
				m.license_distribution_method_code,
				m.license_distribution_method_name,
				license_category_id = isnull(c.license_category_id,dbo.fn_GetLicenseCategoryId(l.license_id)),
				license_category_name = isnull(c.license_category_name,dbo.fn_GetLicenseCategoryName(l.license_id)),
				license_seats = isnull(s.license_seats,1),
				ls.storage_gb,
				bl.license_bulk_load_description,
				cp.capability_id,
				cp.capability_name,
				ct.capability_type_id,
				ct.capability_type_description,
				lc.capability_activation_days,
				lc.capability_activation_date, 
				lc.capability_expiration_date,
				sb.serial_number,
				sb.contract_id,
				sb.subscription_type_id, 
				sbt.description,
				sbt.subscription_type,
				sb.start_date, 
				sb.cancel_reason, 
				sb.cancel_date, 
				--sb.expiration_date, 
				expiration_date = case
								when sb.cancel_reason is not null then sb.cancel_date
								when sb.start_date is not null and sb.cancel_reason is null and sb.expiration_date is null then dateadd(dd,60,getdate())
								else sb.expiration_date
							end,
				sb.product_sku, 
				sb.plan_sku, 
				sb.contract_detail_update, 
				sb.opt_status
		from dbo.license l with (nolock)
		inner join dbo.license_type lt with (nolock)
			on l.license_type_id = lt.license_type_id
		inner join dbo.license_status st with (nolock)
			on l.license_status_id = st.license_status_id
		inner join dbo.license_distribution_method m with (nolock)
			on l.license_distribution_method_id = m.license_distribution_method_id
		left join dbo.license_category_license cl with (nolock)
			on l.license_id = cl.license_id
		left join dbo.license_category c with (nolock)
			on cl.license_category_id = c.license_category_id
		inner join dbo.license_capability lc with (nolock)
			on l.license_id = lc.license_id and lc.capability_id = isnull(c.base_capability_id,1)
		inner join dbo.capability cp with (nolock)
			on lc.capability_id = cp.capability_id
		inner join dbo.capability_type ct with (nolock)
			on lc.capability_type_id = ct.capability_type_id
		left join dbo.license_seat s with (nolock)
			on l.license_id = s.license_id
		left join dbo.license_storage ls with (nolock)
			on l.license_id = ls.license_id
		left join dbo.subscription sb with (nolock)
			on l.l
icense_id = sb.license_id
		left join dbo.subscription_type sbt with (nolock)
			on sb.subscription_type_id = sbt.subscription_type_id
		inner join (select top(@batch_size) 
							u.prevx_update_s2_id,
							t.prevx_update_type_id,
							t.prevx_update_type_name,
							u.license_id,
							u.license_bulk_load_id
					from dbo.prevx_update_s2 u
					inner join dbo.prevx_update_type t
						on u.prevx_update_type_id = t.prevx_update_type_id
					where u.prevx_update_status_id in (0,2) and 
						u.prevx_update_type_id = @prevx_update_type_id and 
						u.process_date <= @batch_limit_date and u.modified_date <= @batch_limit_date
					order by process_date) x
			on l.license_id = x.license_id
		left join dbo.license_bulk_load bl
			on x.license_bulk_load_id = bl.license_bulk_load_id
		order by l.license_id, cp.capability_id

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec dbo.usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_select_next_update_bulk]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_select_next_update_bulk] (
    @prevx_update_type_id TINYINT,
    @batch_size INT,
    @batch_limit_date DATETIME,
    @opt_args VARCHAR(100) = ''
)

/*     
        DATE        AUTHOR      REMARKS
        2011-04-02  esmart      Initial creation.
        2011-08-26  esmart      Change to one row per license
        2011-09-22  esmart      Fix issue with legacy licenses without license seat record.
        2011-10-03  esmart      Missing license_category
        2011-10-14  esmart      Add throttle to bulk
        2011-10-27  esmart      Extend for license_module_license data
        2013-02-12  esmart      Add seat devices based on license_category
        2014-03-14  acoffel     Added additional AR lookup support
        2014-03-18  esmart      S2 expire logic
        2014-03-24  acoffel     reset expire logic back to old
        2016-07-20  esmart		Add additional function parameter
        2019-02-01  jnavarra    Force option to correct errant leading comma
        2023-08-08	gblandford	https://jira.opentext.com/browse/ECOM-1984 - remove extra sb.contract_id from output
								- added dbo. schema to objects
	    2025-05-09  psatish		US-4775343 Moved the problematic licenses to the prevx_update_failure table to unblock the prevx queue
	    2026-05-05	gblandford	IM-5354138 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5354138
                                - order records by priority and process date to ensure churn events are processed after other updates for the same license
                                - added TRY/CATCH block
                                - added @opt_args for debugging purposes, allowing us to pass in arguments to identify specific runs in the logs if needed 
                                - added priority to the output table for visibility and troubleshooting

        DESCRIPTION
        Selects and returns a fully enriched batch of PrevX license updates for external queue processing, ordered by priority
        then process date to ensure churn events are deprioritised behind normal license operations.

        RUN CONTEXT
        Called by the external PrevX update queue processor (PHP service layer)
        Invocation: EXEC dbo.usp_prevx_select_next_update_bulk @prevx_update_type_id, @batch_size, @batch_limit_date
        Execution frequency: Continuous polling on a short interval per update type

        HIGH-LEVEL FLOW
        1) For type 100 (CreateLicenseBulk): count rows archived in the last 5 minutes; if > 2000, set @batch_size = 0 to throttle output.
        2) Load up to @batch_size qualifying queue rows from dbo.prevx_update (status 0 or 2, matching type, process_date <= limit)
           into #prevx_update, ordered by ISNULL(priority,5) then process_date.
        3) WHILE loop — for each queued row:
           a) Join to license, license_type, license_status, license_distribution_method, license_category_license,
              license_category, license_capability, capability, capability_type, license_seat, license_storage,
              subscription, subscription_type, license_attribute_license, license_bulk_load.
           b) Apply OEM/Trial license_type override for product_line_id IN (300, 55): remap type to 4 (Enterprise).
           c) Calculate expiration_date: cancelled = cancel_date; auto-renew with no expiry = capability_expiration_date; else sb.expiration_date.
           d) Calculate opt_status from subscription.opt_status, falling back to license_attribute_license (attribute_id=1) then default 1.
           e) Append module list via dbo.fn_license_module_license_key_value.
           f) On per-row error: INSERT the fa
iling row into dbo.prevx_update_failure, DELETE it from dbo.prevx_update, continue.
        4) SELECT the enriched result set from #result ordered by insertion id.
        5) On outer CATCH error: set @response_code = -200, log via dbo.usp_LogError.

        PARAMETERS
        @prevx_update_type_id TINYINT : Update type filter (1=CreateLicense, 2=UpdateLicense, 3=SuspendLicense, 4=ReactivateLicense, 100=CreateLicenseBulk)
        @batch_size INT               : Maximum number of queue rows to process and return
        @batch_limit_date DATETIME    : Upper bound on process_date for eligible queue rows (1 second added internally for PHP millisecond limitation)
        @opt_args VARCHAR(100) = ''   : Optional debug flag(s); e.g. 'debug' to enable debug output steps in the stored procedure

        DEPENDENCIES
        dbo.prevx_update                      (source queue — read, not modified here)
        dbo.prevx_update_type                 (update type name lookup)
        dbo.prevx_update_archive              (throttle row count check for type 100)
        dbo.prevx_update_failure              (error isolation — problematic rows moved here)
        dbo.license                           (core license data: keycode, type, status, product_line_id)
        dbo.license_type                      (type description)
        dbo.license_status                    (status description)
        dbo.license_distribution_method       (distribution method code/name)
        dbo.license_category_license          (category assignment)
        dbo.license_category                  (category name, base_capability_id, devices_per_seat)
        dbo.license_capability                (capability dates, activation days)
        dbo.capability                        (capability name)
        dbo.capability_type                   (capability type description)
        dbo.license_seat                      (seat count)
        dbo.license_storage                   (storage_gb)
        dbo.subscription                      (billing/contract data)
        dbo.subscription_type                 (subscription type description)
        dbo.license_attribute_license         (opt_status fallback, license_attribute_id = 1)
        dbo.license_bulk_load                 (bulk load description)
        dbo.fn_GetLicenseCategoryId           (fallback category ID when license_category_license is absent)
        dbo.fn_GetLicenseCategoryName         (fallback category name when license_category_license is absent)
        dbo.fn_license_module_license_key_value (module license key-value list)
        dbo.usp_LogError                      (error logging in outer CATCH block)

*/

AS

SET NOCOUNT ON
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
SET CONCAT_NULL_YIELDS_NULL ON

BEGIN TRY

    DECLARE @debug TINYINT = 0;
    IF @opt_args LIKE '%debug%' BEGIN
            SET @debug = 1
        END

    IF @debug = 1 BEGIN
            SELECT 'Input parameters' AS step_name, 
                @prevx_update_type_id AS prevx_update_type_id, 
                @batch_size AS batch_size, 
                @batch_limit_date AS batch_limit_date
        END 

    DECLARE @processed INT,
            @response_code INT,
            @message VARCHAR(100),
            @id INT = 1,
            @count INT,       
            @current_date DATETIME = GETDATE(),
            @prevx_update_id INT

    DROP TABLE IF EXISTS #prevx_update
    CREATE TABLE #prevx_update
    (
        id INT IDENTITY(1, 1) PRIMARY KEY,
        prevx_update_id INT,
        prevx_update_type_id INT,
        prevx_update_type_name VARCHAR(50),
        prevx_update_status_id INT,
        license_id INT,
        license_bulk_load_id INT,
        priority INT
    )
    CREATE NONCLUSTERED INDEX IX_prevx_update_temp
    ON #prevx_update (
                        prevx_update_id,
                        license_id
                    )

    CRE
ATE TABLE #result (
        id INT IDENTITY(1, 1) PRIMARY KEY,
        prevx_update_id INT,
        prevx_update_type_id INT,
        prevx_update_type_name VARCHAR(50),
        license_id INT,
        keycode VARCHAR(40),
        license_type_id INT,
        license_type_description VARCHAR(20),
        license_status_id INT,
        license_status_description VARCHAR(20),
        license_distribution_method_code CHAR(4),
        license_distribution_method_name VARCHAR(100),
        license_category_id INT,
        license_category_name VARCHAR(10),
        license_seats INT,
        storage_gb INT,
        license_bulk_load_description VARCHAR(100),
        capability_id INT,
        capability_name VARCHAR(50),
        capability_type_id INT,
        capability_type_description VARCHAR(20),
        capability_activation_days INT,
        capability_activation_date DATETIME,
        capability_expiration_date DATETIME,
        serial_number VARCHAR(19),
        contract_id VARCHAR(10),
        subscription_type_id INT,
        DESCRIPTION VARCHAR(200),
        subscription_type NVARCHAR(4),
        start_date SMALLDATETIME,
        cancel_reason VARCHAR(40),
        cancel_date SMALLDATETIME,
        expiration_date SMALLDATETIME,
        product_sku VARCHAR(8),
        plan_sku VARCHAR(8),
        contract_detail_update INT,
        opt_status INT,
        license_module_license_list VARCHAR(MAX),
        priority INT
    )

    SELECT @batch_limit_date = DATEADD(ss, 1, @batch_limit_date) -- php cannot handle milliseconds so add one second
    IF @debug = 1 BEGIN
            SELECT @batch_limit_date AS adjusted_batch_limit_date

            SELECT 'After setup, before main processing' AS step_name
        END;

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) return result
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    -- 1.1) add throttle to bulk load
    IF @prevx_update_type_id = 100 BEGIN
            SELECT @processed = COUNT(*)
            FROM dbo.prevx_update_archive
            WHERE archive_date > DATEADD(mi, -5, @current_date)
                AND prevx_update_type_id IN ( 100 )

            IF @processed > 2000
            BEGIN
                SELECT @batch_size = 0
            END
        END

    IF @prevx_update_type_id IN ( 
            1,          -- CreateLicense
            2,          -- UpdateLicense
            3,          -- SuspendLicense
            4,          -- ReactivateLicense
            100         -- CreateLicenseBulk
        ) BEGIN

        -- 1.1) license data
        INSERT INTO #prevx_update (
            prevx_update_id,
            prevx_update_type_id,
            prevx_update_type_name,
            license_id,
            license_bulk_load_id,
            prevx_update_status_id,
            priority
        )
        SELECT TOP ( @batch_size )
            u.prevx_update_id,
            t.prevx_update_type_id,
            t.prevx_update_type_name,
            u.license_id,
            u.license_bulk_load_id,
            u.prevx_update_status_id,
            priority = ISNULL( u.priority, 5 )
        FROM dbo.prevx_update u
            INNER JOIN dbo.prevx_update_type t
                ON u.prevx_update_type_id = t.prevx_update_type_id
        WHERE u.prevx_update_status_id IN ( 0, 2 )
            AND u.prevx_update_type_id = @prevx_update_type_id
            AND u.process_date <= @batch_limit_date --and u.modified_date <= @batch_limit_date
        ORDER BY ISNULL( u.priority, 5 ), u.process_date

        SET @count = @@ROWCOUNT

        IF @debug = 1 BEGIN
      
          SELECT 'After loading #prevx_update' AS step_name, COUNT(*) AS row_count FROM #prevx_update
            END;

        WHILE ( @id <= @count ) BEGIN
        
            BEGIN TRY

                SELECT @prevx_update_id = prevx_update_id
                FROM #prevx_update
                WHERE id = @id

                INSERT INTO #result (
                    prevx_update_id,
                    prevx_update_type_id,
                    prevx_update_type_name,
                    license_id,
                    keycode,
                    license_type_id,
                    license_type_description,
                    license_status_id,
                    license_status_description,
                    license_distribution_method_code,
                    license_distribution_method_name,
                    license_category_id,
                    license_category_name,
                    license_seats,
                    storage_gb,
                    license_bulk_load_description,
                    capability_id,
                    capability_name,
                    capability_type_id,
                    capability_type_description,
                    capability_activation_days,
                    capability_activation_date,
                    capability_expiration_date,
                    serial_number,
                    contract_id,
                    subscription_type_id,
                    DESCRIPTION,
                    subscription_type,
                    start_date,
                    cancel_reason,
                    cancel_date,
                    expiration_date,
                    product_sku,
                    plan_sku,
                    contract_detail_update,
                    opt_status,
                    license_module_license_list,
                    priority
                )
                SELECT x.prevx_update_id,
                    x.prevx_update_type_id,
                    x.prevx_update_type_name,
                    l.license_id,
                    l.keycode,
                    license_type_id = CASE
                                            WHEN l.product_line_id IN ( 300, 55 )
                                                AND l.license_type_id = 2 THEN
                                                4
                                            ELSE
                                                lt.license_type_id
                                        END,
                    license_type_description = CASE
                                                    WHEN l.product_line_id IN ( 300, 55 )
                                                        AND l.license_type_id = 2 THEN
                                                        'Enterprise'
                                                    ELSE
                                                        lt.license_type_description
                                                END,
                    st.license_status_id,
                    st.license_status_description,
                    m.license_distribution_method_code,
                    m.license_distribution_method_name,
                    license_category_id = ISNULL(c.license_category_id, dbo.fn_GetLicenseCategoryId(l.license_id)),
                    license_category_name = ISNULL(c.license_category_name, dbo.fn_GetLicenseCategoryName(l.license_id)),
                    license_seats = CASE
                                        WHEN c.license_category_id IS NOT NULL
                                                AND s.license_seats IS NOT NULL THEN
                                            s.license_seats * c.devices_per_seat
                                        ELSE
                                            ISNULL(s.license_seats, 1)
                                    END,
                    ls.storage_gb,
               
     bl.license_bulk_load_description,
                    cp.capability_id,
                    cp.capability_name,
                    ct.capability_type_id,
                    ct.capability_type_description,
                    lc.capability_activation_days,
                    lc.capability_activation_date,
                    lc.capability_expiration_date,
                    sb.serial_number,
                    sb.contract_id,
                    sb.subscription_type_id,
                    sbt.description,
                    sbt.subscription_type,
                    sb.start_date,
                    sb.cancel_reason,
                    sb.cancel_date,
                    --sb.expiration_date, 
                    --expiration_date = case when sb.cancel_reason is not null then sb.cancel_date
                    --                                   when sb.start_date is not null and sb.cancel_reason is null and sb.expiration_date is null then null--dateadd(dd,60,getdate())
                    --                                   else sb.expiration_date end,
                    expiration_date = CASE
                                            WHEN sb.cancel_reason IS NOT NULL THEN
                                                sb.cancel_date
                                            WHEN sb.start_date IS NOT NULL
                                                AND sb.cancel_reason IS NULL
                                                AND sb.expiration_date IS NULL
                                                AND sb.subscription_type_id = 1 THEN
                                                lc.capability_expiration_date
                                            ELSE
                                                sb.expiration_date
                                        END,
                    sb.product_sku,
                    sb.plan_sku,
                    sb.contract_detail_update,
                    opt_status = ISNULL(   CASE
                                                WHEN sb.opt_status IS NOT NULL THEN
                                                    sb.opt_status
                                                WHEN sb.opt_status IS NULL
                                                    AND lal.license_id IS NOT NULL THEN
                                            (CASE
                                                WHEN lal.license_attribute_license_value = 1 THEN
                                                    0
                                                ELSE
                                                    1
                                            END
                                            )
                                            END,
                                            1
                                        ),
                    license_module_license_list = dbo.fn_license_module_license_key_value(l.license_id, NULL),
                    x.priority
                FROM #prevx_update x
                    INNER JOIN dbo.license l
                        ON l.license_id = x.license_id
                    INNER JOIN dbo.license_type lt
                        ON l.license_type_id = lt.license_type_id
                    INNER JOIN dbo.license_status st
                        ON l.license_status_id = st.license_status_id
                    INNER JOIN dbo.license_distribution_method m
                        ON l.license_distribution_method_id = m.license_distribution_method_id
                    LEFT JOIN dbo.license_category_license cl
                        ON l.license_id = cl.license_id
                    LEFT JOIN dbo.license_category c
                        ON cl.license_category_id = c.license_category_id
                    INNER JOIN dbo.license_capability lc
                        ON l.license_id = lc.license_id
                        AND lc.capability_id = ISN
ULL(c.base_capability_id, 1)
                    INNER JOIN dbo.capability cp
                        ON lc.capability_id = cp.capability_id
                    INNER JOIN dbo.capability_type ct
                        ON lc.capability_type_id = ct.capability_type_id
                    LEFT JOIN dbo.license_seat s
                        ON l.license_id = s.license_id
                    LEFT JOIN dbo.license_storage ls
                        ON l.license_id = ls.license_id
                    LEFT JOIN dbo.subscription sb
                        ON l.license_id = sb.license_id
                    LEFT JOIN dbo.license_attribute_license lal
                        ON l.license_id = lal.license_id
                        AND lal.license_attribute_id = 1
                    LEFT JOIN dbo.subscription_type sbt
                        ON sb.subscription_type_id = sbt.subscription_type_id
                    LEFT JOIN dbo.license_bulk_load bl
                        ON x.license_bulk_load_id = bl.license_bulk_load_id
                WHERE x.prevx_update_id = @prevx_update_id
                ORDER BY l.license_id,
                        cp.capability_id


            END TRY

            BEGIN CATCH

                INSERT INTO dbo.prevx_update_failure (
                    prevx_update_id,
                    license_id,
                    prevx_update_type_id,
                    prevx_update_status_id,
                    insert_date,
                    modified_date,
                    process_date,
                    update_attempts
                )
                SELECT prevx_update_id,
                    license_id,
                    prevx_update_type_id,
                    prevx_update_status_id,
                    insert_date,
                    modified_date,
                    process_date,
                    update_attempts
                FROM dbo.prevx_update
                WHERE prevx_update_id = @prevx_update_id

                DELETE FROM dbo.prevx_update
                WHERE prevx_update_id = @prevx_update_id

                IF @debug = 1 BEGIN
                        SELECT 'Failed prevx_update_id ' + CAST(@prevx_update_id AS VARCHAR) AS step_name
                    END;

            END CATCH;

            SET @prevx_update_id = NULL
            SET @id = @id + 1

        END

        if @debug = 1 BEGIN
                SELECT 'After main processing loop, before final select' AS step_name, * FROM #result ORDER BY id;
            END;

        SELECT prevx_update_id,
            prevx_update_type_id,
            prevx_update_type_name,
            license_id,
            keycode,
            license_type_id,
            license_type_description,
            license_status_id,
            license_status_description,
            license_distribution_method_code,
            license_distribution_method_name,
            license_category_id,
            license_category_name,
            license_seats,
            storage_gb,
            license_bulk_load_description,
            capability_id,
            capability_name,
            capability_type_id,
            capability_type_description,
            capability_activation_days,
            capability_activation_date,
            capability_expiration_date,
            serial_number,
            contract_id,
            subscription_type_id,
            DESCRIPTION,
            subscription_type,
            start_date,
            cancel_reason,
            cancel_date,
            expiration_date,
            product_sku,
            plan_sku,
            contract_detail_update,
            opt_status,
            license_module_license_list
        FROM #result
        ORDER BY id;

    END

END TRY

BEGIN CATCH

    SET @response_code = -200
    SET @message = CASE WHEN @message IS NULL THEN 'usp_prevx_select_next_update_bulk 
failed'
                                        ELSE @message END

    DECLARE @DBName NVARCHAR(128)
    SET @DBName = DB_NAME()
    EXECUTE dbo.usp_LogError @ErrorDB = @DBName
       
END CATCH;


GO
