-- PROCEDURE: [dbo].[usp_prevx_select_s2_update_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_prevx_select_s2_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2011-03-18	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- TODO validate of process date so if an update does occur we do a double check

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select t.prevx_update_type_id, t.prevx_update_type_name, batch_count = count(*), batch_limit_date = max(process_date)
	from prevx_update_s2 u with (nolock)
	inner join prevx_update_type t with (nolock)
		on u.prevx_update_type_id = t.prevx_update_type_id
	where prevx_update_status_id in (0,2) and process_date <= getdate()
	group by t.prevx_update_type_id, t.prevx_update_type_name 
	order by t.prevx_update_type_id, t.prevx_update_type_name

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
