CREATE PROCEDURE [dbo].[usp_prevx_select_update_details]

(
	@license_id int
)
	
/*	
	DATE        AUTHOR     REMARKS
  2011-08-25  acoffel    Initial creation.
  2012-12-26  esmart     Change sort
  2013-12-16  cfaulkner  Added eCommerce_Archive..prevx_update_archive to select

	DESCRIPTION
	Use by CSI web interface.

*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		select source = 'queue', u.insert_date, t.prevx_update_type_name, s.prevx_update_status_name, u.response_text, u.update_attempts, u.process_date, NULL as archive_date
		  from prevx_update u
		  left join prevx_update_type t
			  on u.prevx_update_type_id = t.prevx_update_type_id
		  left join prevx_update_status s
			  on u.prevx_update_status_id = s.prevx_update_status_id
		  where license_id = @license_id
		union
		select source = 'archive', u.insert_date, t.prevx_update_type_name, s.prevx_update_status_name, u.response_text, u.update_attempts, u.process_date, u.archive_date
		  from prevx_update_archive u
		  left join prevx_update_type t
			  on u.prevx_update_type_id = t.prevx_update_type_id
		  left join prevx_update_status s
			  on u.prevx_update_status_id = s.prevx_update_status_id
		  where license_id = @license_id
		union
		select source = 'archive', u.insert_date, t.prevx_update_type_name, s.prevx_update_status_name, u.response_text, u.update_attempts, u.process_date, u.archive_date
		  from eCommerce_archive.dbo.prevx_update_archive u
		  left join prevx_update_type t
			  on u.prevx_update_type_id = t.prevx_update_type_id
		  left join prevx_update_status s
			  on u.prevx_update_status_id = s.prevx_update_status_id
		  where license_id = @license_id
		  order by insert_date desc
	end try

	begin catch
		set @response_code = -200
		set @message = case when @message is null then 'select failed' else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_update_license_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_prevx_update_license_update]

(
		@prevx_update_id int,
		@response_id smallint,
		@response_text varchar(5000)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-18	esmart		Initial creation
	2012-06-22	esmart		Extend failure retry interval
	2018-10-23	esmart		Move SMB license to sky_api_license after CreateLicense
	2019-01-07	esmart		Add left join to eliminate duplicate sky_api_license insert error
	2019-12-03	esmart		Add insert into sky_update_license on initial insert into sky_api_license
	2024-10-29  msoni       IM-3525038: Update @response_text from varchar(25) to varchar(5000)

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@response_message varchar(20),
			@prevx_update_status_id tinyint,
			@update_attempts tinyint,
			@current_prevx_update_status_id tinyint,
			@prevx_update_type_id tinyint,
			@new_prevx_update_type_id tinyint,
			@license_id int,
			@modified_date datetime,
			@capability_expiration_date datetime,
			@process_date datetime,
			@minutes_extension int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @modified_date = getdate(),
			@minutes_extension = 5

	-- 1.1) select @prevx_update_type_id
	select @prevx_update_status_id = case when @response_text = 'SUCCESS' then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_prevx_update_status_id = prevx_update_status_id,
			@prevx_update_type_id = prevx_update_type_id,	
			@license_id = license_id
	from prevx_update
	where prevx_update_id = @prevx_update_id

	if @current_prevx_update_status_id in (1,3)
		begin
		select @response_code = -120, @response_message = 'No update on processed or abandoned updates'
		select response_code = @response_code, response_message = @response_message
		return
		end

	-- 1.3) if 5 failed attempts, abandon update
	if @update_attempts > 10 and @prevx_update_status_id = 2 -- failed
		begin
		select @prevx_update_status_id = 3 -- abandoned
		end
		
	-- 1.4) @minutes_extension
	if @update_attempts > 1 and @update_attempts < 5
		begin
		select @minutes_extension = 5
		end
	if @update_attempts >= 5
		begin
		select @minutes_extension = 15
		end

	--select prevx_update_status_id = @prevx_update_status_id, update_attempts = @update_attempts

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) Processed
	if @prevx_update_status_id  = 1
		begin
		-- 2.1.1) insert archive record
			--print('2.1.1')
			insert into prevx_update_archive(prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date)
			select prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update
			where prevx_update_id = @prevx_update_id

			-- 2.1.1.1) add as sky_api
_license once CreateLicense has been completed
			insert into sky_api_license (license_id)
			select distinct u.license_id
			from prevx_update u
			inner join license l
				on u.license_id = l.license_id
			left join sky_api_license a
				on u.license_id = a.license_id
			where u.prevx_update_id =  @prevx_update_id and u.prevx_update_type_id = 1 and l.product_line_id in (300,55) and a.license_id is null

			if @@ROWCOUNT > 0
				begin
				insert into sky_update_license (license_id) values(@license_id)
				end

			-- 2.1.2) delete update record
			delete
			from prevx_update
			where prevx_update_id = @prevx_update_id
		
			select @response_code = 0, @response_message = 'Update processed'	
		end
	
	-- 2.2) Failure
	if @prevx_update_status_id = 2
		begin
--		print('2.2')
			-- 2.1) log failure
			insert into prevx_update_failure(prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, failure_date)
			select prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update
			where prevx_update_id = @prevx_update_id
	
			-- 2.2.2) update queue
			update prevx_update 
			set prevx_update_status_id = @prevx_update_status_id,
				update_attempts = @update_attempts,
				response_id = @response_id,
				response_text = @response_text,
				modified_date = @modified_date,
				process_date = dateadd(mi,@minutes_extension,process_date)
			where prevx_update_id = @prevx_update_id

			-- 2.2.3) set 
			select @response_code = -220, @response_message = 'Update failed'
		end
	
	-- 2.3) Abandoned
	if @prevx_update_status_id = 3
		begin
			-- 2.3.1) insert archive record
			--print('2.3.1')
			insert into prevx_update_archive(prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date)
			select prevx_update_id, license_id, prevx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update
			where prevx_update_id = @prevx_update_id

			-- 2.3.2) delete update record
			delete
			from prevx_update
			where prevx_update_id = @prevx_update_id
--		
			select @response_code = -230, @response_message = 'Update abandoned'	
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set up next queue transaction
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--	if @response_code = 0 and @response_message = 'Update processed' 
--		begin
--	
--		-- 3.1) get expiration date for license
--		--print('3.1')
--		select @capability_expiration_date = c.capability_expiration_date
--		from license_capability c
--		inner join license_category_license cl
--			on c.license_id = cl.license_id
--		inner join license_category lc
--			on cl.license_category_id = lc.license_category_id
--		where c.license_id = @license_id and c.capability_id = lc.base_capability_id
--
--		-- 3.2) determine next update type
--			if @prevx_update_type_id in (1,2,4) and @capability_expiration_date is not null
--			--print('3.2.1')
--			-- 3.2.1) insert deactivate record
--				begin
--					select @new_prevx_update_type_id = 3
--					select @process_date = @capability_expiration_date
--					exec usp_prevx_insert_license_update @license_id, @new_prevx_update_type_id, 0, @process_date
--				end
--		end

		select response_code = @response_code, [messag
e] = @response_message 
	end try

	begin catch

		set @response_code = -200
		set @response_message = case when @response_message is null then 'update account update failed'
							else @response_message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_update_queue]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_prevx_update_queue] (
	@response_code INT OUTPUT,
	@message VARCHAR(100) OUTPUT
)

/*	
	DATE			AUTHOR		REMARKS
	2010-04-13		esmart		Initial creation.
	2010-08-08		esmart		UpdateLicense
	2011-08-22		esmart		Add distinct
	2011-09-08		esmart		Add support for bulk loads. Eliminated direct insert of bulk loads.
	2011-10-21		esmart		Modify to support immediate load of older bulk load keycodes
	2011-12-12		esmart		Restrict terminated status
	2012-01-20		esmart		Remove updates on OEM keycodes
	2012-03-08		esmart		Check for missing licenses
	2012-04-03		esmart		Check for success in archive when restricting another CreateLicense
	2012-04-24		esmart		Remove suspendService records instead of update
	2013-07-08      surpal		Modified 4.2 to improve performance of the query	
	2014-04-28		esmart		Add support for UpdateLicense on parent keycodes with order transactions
	2017-01-03		acoffel		Removed order_item_license dependency for Parent updates to be sent to Derby
	2017-03-29		acoffel		Validate license is fully built out
	2021-10-22		psatish		Bypass the prevx_update_license for the new licenses that are created from Contract Backfill
	2022-03-21		psatish		Added new License distribution method as NSBF for Contract Backfill
	2026-05-05	  	gblandford	IM-5354138 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=5354138
								- forward the priority value from prevx_update_license to prevx_update to ensure that the processing job processes the updates in the correct order
								and deprioritizes license_churn updates
								- removing unused (commented) code
								- added schemas, modified casing, formatting for readability, added comments for clarity
								

	DESCRIPTION
	Builds and maintains the PrevX update processing queues for eligible licenses, routing them into the appropriate
	queue table (dbo.prevx_update or dbo.prevx_update_s2) based on license type and state. Called on a schedule by
	the SQL Agent job that drives Sky API synchronisation.

	RUN CONTEXT
	Called by SQL Agent job: prevx_update_processing_ecommerce (or equivalent scheduler)
	Job step: exec usp_prevx_update_queue
	Execution frequency: scheduled (runs continuously on a short interval)

	HIGH-LEVEL FLOW
	1) Remove staged rows from dbo.prevx_update_license where a Sky API license already exists
	   (dbo.sky_api_license), preventing duplicate processing.
	2) Insert CreateLicense (type 1) or CreateLicenseBulk (type 100) rows into dbo.prevx_update for licenses
	   that are fully built out (capability, category, seat all present) and have no prior success archive entry.
	   Priority is forwarded from dbo.prevx_update_license (default 5).
	3) Archive SuspendService-type queue rows from dbo.prevx_update to dbo.prevx_update_archive (response = 'archive'),
	   then delete them, to make way for UpdateLicense re-queuing.
	4) Insert UpdateLicense (type 2) rows into dbo.prevx_update for:
	   - Standard licenses (license_type_id NOT IN 2/3) with prior archive entries.
	   - OEM/Trial licenses (license_type_id IN 2 OEM, 3 Trial) with prior archive entries.
	   - Trial licenses joined to dbo.trial with prior archive entries.
	5) Insert Best Buy rows (type 1) into dbo.prevx_update_s2 for licenses with a dbo.subscription record.
	6) Delete processed staged rows from dbo.prevx_update_license (insert_date <= snapshot timestamp).
	7) Backfill: find the MAX successful archive license_id and re-queue any recent licenses (within -1000 of that
	   high-water mark) that have never been sent, are in eligible product lines, have a non-empty keycode,
	   are not in dbo.sky_api_license, and were not distributed via NSBF.

	PARAMETERS
	@response_code INT OUTPUT
 : 0 on success (implicit), -200 on failure
	@message VARCHAR(100) OUTPUT : Failure message set in CATCH block; not set on success

	DEPENDENCIES
	dbo.prevx_update_license     (staging source — read and deleted from)
	dbo.prevx_update             (primary queue — inserted into and archived from)
	dbo.prevx_update_s2          (Best Buy queue — inserted into)
	dbo.prevx_update_archive     (archive for processed/superseded queue rows)
	dbo.sky_api_license          (exclusion filter — skip licenses already in Sky API)
	dbo.license                  (license metadata: status, type, product_line_id, keycode)
	dbo.license_bulk_load_license (bulk load detection for CreateLicenseBulk routing)
	dbo.license_capability       (license build-out validation for CreateLicense)
	dbo.license_category_license (license build-out validation for CreateLicense)
	dbo.license_seat             (license build-out validation for CreateLicense)
	dbo.subscription             (Best Buy queue eligibility check)
	dbo.trial                    (trial license identification for UpdateLicense trial path)
	dbo.license_distribution_method (NSBF exclusion filter in backfill step)
	dbo.usp_LogError             (error logging in CATCH block)

*/

AS
	
SET NOCOUNT ON

BEGIN TRY

	DECLARE @modified_date DATETIME
	DECLARE @license_id INT 

	DROP TABLE IF EXISTS #prevx_update_archive; 
	CREATE TABLE #prevx_update_archive (
		prevx_update_id INT
	);

	SELECT @modified_date = GETDATE()
		
	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 1.0) updates to existing queue records
	-- ----------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) delete from prevx_update_license where sku_license exists
	DELETE FROM dbo.prevx_update_license
	WHERE license_id IN (SELECT license_id FROM dbo.sky_api_license)

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 2.0) insert queue records
	-- ----------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) CreateLicense
	INSERT INTO dbo.prevx_update (
		license_id, 
		license_bulk_load_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		insert_date, 
		modified_date, 
		process_date,
		[priority]
	)
	SELECT DISTINCT 
		ul.license_id, 
		bl.license_bulk_load_id, 
		prevx_update_type_id = CASE
									WHEN bl.license_bulk_load_license_id IS NOT NULL 
										AND bl.insert_date > DATEADD( mi, -10, GETDATE() ) THEN 100
									ELSE 1
								END, 
		prevx_update_status_id = 0, 
		insert_date = @modified_date, 
		modified_date = @modified_date, 
		process_date = @modified_date,
		[priority] = ISNULL( ul.priority, 5 )

	FROM dbo.prevx_update_license ul WITH (NOLOCK)
		INNER JOIN dbo.license l WITH (NOLOCK)
			ON ul.license_id = l.license_id	
		LEFT JOIN dbo.license_bulk_load_license bl
			ON ul.license_id = bl.license_id
		LEFT JOIN dbo.prevx_update u WITH (NOLOCK)
			ON ul.license_id = u.license_id
		LEFT JOIN dbo.license_capability c WITH (NOLOCK)
			ON l.license_id = c.license_id 
		LEFT JOIN dbo.license_category_license cl WITH (NOLOCK)
			ON l.license_id = cl.license_id
		LEFT JOIN dbo.license_seat s WITH (NOLOCK)
			ON l.license_id = s.license_id 
		LEFT JOIN dbo.prevx_update_archive pua WITH (NOLOCK)
			ON ul.license_id = pua.license_id
				AND pua.response_text = 'success'			
	WHERE ul.insert_date <= @modified_date 
		AND u.prevx_update_id IS NULL 
		AND c.license_id IS NOT NULL
		AND cl.license_id IS NOT NULL
		AND s.license_id IS NOT NULL
		AND pua.prevx_update_archive_id IS NULL;
		-- AND ul.license_id NOT IN ( SELECT license_id FROM dbo.prevx_update_archive WITH (NOLOCK) WHERE
 response_text = 'success') AND l.keycode <> ''

	-- 2.2) UpdateLicense

	-- 2.2.1) Archive SuspendService records existing records
	INSERT INTO dbo.prevx_update_archive (
		prevx_update_id, 
		license_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		response_id, 
		response_text,
		update_attempts, 
		insert_date, 
		modified_date, 
		process_date, 
		archive_date
	)
	OUTPUT Inserted.prevx_update_id INTO #prevx_update_archive (
		prevx_update_id	
	)
	SELECT 
		u.prevx_update_id, 
		u.license_id, 
		u.prevx_update_type_id, 
		u.prevx_update_status_id, 
		response_id = 0, 
		response_text = 'archive', 
		u.update_attempts, 
		u.insert_date, 
		u.modified_date, 
		u.process_date, 
		@modified_date
	FROM dbo.prevx_update u WITH (NOLOCK)
		INNER JOIN dbo.license_category_license cl WITH (NOLOCK)
			ON u.license_id = cl.license_id
		LEFT JOIN dbo.prevx_update_license ul WITH (NOLOCK)
			ON u.license_id = ul.license_id
				AND ul.insert_date <= @modified_date
	WHERE u.prevx_update_type_id NOT IN ( 
				1, 		-- CreateLicense
				2, 		-- UpdateLicense
				100 	-- CreateLicenseBulk
			) 
		-- AND u.license_id IN (SELECT license_id FROM dbo.prevx_update_license WITH (NOLOCK) WHERE insert_date <= @modified_date)
		AND ul.license_id IS NOT NULL;

	DELETE u
	FROM dbo.prevx_update u
		INNER JOIN #prevx_update_archive a 
			ON u.prevx_update_id = a.prevx_update_id;
	-- DELETE u
	-- FROM dbo.prevx_update u
	-- WHERE prevx_update_id IN (SELECT u.prevx_update_id
	-- 						FROM dbo.prevx_update u WITH (NOLOCK)
	-- 						INNER JOIN dbo.license_category_license cl WITH (NOLOCK)
	-- 							ON u.license_id = cl.license_id
	-- 						WHERE u.prevx_update_type_id NOT IN (1,2,100) AND u.license_id IN (SELECT license_id FROM dbo.prevx_update_license WITH (NOLOCK) WHERE insert_date <= @modified_date))

	-- 2.2.2) Insert UpdateLicense
	INSERT INTO dbo.prevx_update (
		license_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		insert_date, 
		modified_date, 
		process_date,
		[priority]
	)
	SELECT DISTINCT ul.license_id, 
		prevx_update_type_id = 2, 
		prevx_update_status_id = 0, 
		insert_date = @modified_date, 
		modified_date = @modified_date, 
		process_date = @modified_date,
		[priority] = ISNULL( ul.[priority], 5 )
	FROM dbo.prevx_update_license ul WITH (NOLOCK)
		INNER JOIN dbo.license l WITH (NOLOCK)
			ON ul.license_id = l.license_id	
		LEFT JOIN dbo.prevx_update u WITH (NOLOCK)
			ON ul.license_id = u.license_id
		LEFT JOIN dbo.prevx_update_archive a WITH (NOLOCK)
			ON ul.license_id = a.license_id
				AND a.insert_date <= @modified_date
	WHERE l.license_status_id <> 0 
		AND l.license_type_id NOT IN (
				2,
				3
			) 
		AND u.prevx_update_id IS NULL 
		-- AND ul.license_id IN (SELECT license_id FROM dbo.prevx_update_archive WITH (NOLOCK) WHERE ul.insert_date <= @modified_date)
		AND a.prevx_update_archive_id IS NOT NULL;

	-- 2.2.3) Insert UpdateLicense Parent
	INSERT INTO dbo.prevx_update (
		license_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		insert_date, 
		modified_date, 
		process_date,
		[priority]
	)
	SELECT DISTINCT ul.license_id, 
		prevx_update_type_id = 2, 
		prevx_update_status_id = 0, 
		insert_date = @modified_date, 
		modified_date = @modified_date, 
		process_date = @modified_date,
		[priority] = ISNULL( ul.[priority], 5 )
	FROM dbo.prevx_update_license ul WITH (NOLOCK)
		INNER JOIN dbo.license l WITH (NOLOCK)
			ON ul.license_id = l.license_id	
		LEFT JOIN dbo.prevx_update u WITH (NOLOCK)
			ON ul.license_id = u.license_id
		LEFT JOIN dbo.prevx_update_archive a WITH (NOLOCK)
			ON ul.license_id = a.license_id
				AND a.insert_date <= @modified_date
	WHERE l.license_status_id <> 0 
		AND l.license_type_id IN (
				2,	-- OEM
				3	-- Trial
			) 
		AND u.prevx_update_id IS NULL 
		-- AND ul.license_id IN (SELECT license_id FROM dbo.prevx_update_archive WITH (NOLOCK) WHERE ul.i
nsert_date <= @modified_date) 
		AND a.prevx_update_archive_id IS NOT NULL;

	-- 2.2.4) Insert UpdateLicense Parent for trials
	INSERT INTO dbo.prevx_update (
		license_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		insert_date, 
		modified_date, 
		process_date, [priority]
	)
	SELECT DISTINCT 
		ul.license_id, 
		prevx_update_type_id = 2, 
		prevx_update_status_id = 0, 
		insert_date = @modified_date, 
		modified_date = @modified_date, 
		process_date = @modified_date, 
		[priority] = ISNULL( ul.[priority], 5 )
	FROM dbo.prevx_update_license ul WITH (NOLOCK)
		INNER JOIN dbo.license l WITH (NOLOCK)
			ON ul.license_id = l.license_id	
		INNER JOIN dbo.trial t WITH (NOLOCK)
			ON l.license_id = t.license_id
		LEFT JOIN dbo.prevx_update u WITH (NOLOCK)
			ON ul.license_id = u.license_id
		LEFT JOIN dbo.prevx_update_archive a WITH (NOLOCK)
			ON ul.license_id = a.license_id
				AND a.insert_date <= @modified_date
			
	WHERE l.license_status_id <> 0 
		AND l.license_type_id IN (2,3) 
		AND u.prevx_update_id IS NULL 
		-- AND ul.license_id IN (SELECT license_id FROM dbo.prevx_update_archive WITH (NOLOCK) WHERE ul.insert_date <= @modified_date)
		AND a.prevx_update_archive_id IS NOT NULL; 

	-- 2.3) prevx_update_bestbuy
	INSERT INTO dbo.prevx_update_s2 (
		license_id, 
		prevx_update_type_id, 
		prevx_update_status_id, 
		insert_date, 
		modified_date, 
		process_date
	)
	SELECT 
		DISTINCT 
		ul.license_id, 
		prevx_update_type_id = 1, 
		prevx_update_status_id = 0, 
		insert_date = @modified_date, 
		modified_date = @modified_date, 
		process_date = @modified_date
	FROM dbo.prevx_update_license ul WITH (NOLOCK)
		INNER JOIN dbo.license l WITH (NOLOCK)
			ON ul.license_id = l.license_id	
		INNER JOIN dbo.subscription s WITH (NOLOCK)
			ON l.license_id = s.license_id
		LEFT JOIN dbo.prevx_update_s2 u WITH (NOLOCK)
			ON ul.license_id = u.license_id
			WHERE ul.insert_date <= @modified_date AND u.prevx_update_s2_id IS NULL

	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 4.0) cleanup
	-- ----------------------------------------------------------------------------------------------------------------------------------------
	-- 4.1) delete rows from prevx_update
	DELETE FROM dbo.prevx_update_license WHERE insert_date <= @modified_date;
	
	-- 4.2) check for any licenses that have not been sent down to Prevx  --- commented by surpal to improve the performance
	SELECT @license_id = MAX( license_id ) 
	FROM dbo.prevx_update_archive 
	WHERE response_text='success';

	INSERT INTO dbo.prevx_update_license(
		license_id
	)
	SELECT l.license_id
	FROM dbo.license l WITH (NOLOCK)
		INNER JOIN dbo.license_distribution_method dm
				ON dm.license_distribution_method_id = l.license_distribution_method_id
		LEFT JOIN dbo.prevx_update_archive a WITH (NOLOCK)
				ON l.license_id = a.license_id 
		LEFT JOIN dbo.prevx_update u WITH (NOLOCK)
				ON l.license_id = u.license_id 
		LEFT JOIN dbo.sky_api_license s WITH (NOLOCK)
			ON s.license_id = l.license_id
	WHERE a.prevx_update_archive_id IS NULL 
		AND u.prevx_update_id IS NULL 
		AND l.product_line_id IN (
				1, 		-- Webroot Secure Anywhere
				6, 		-- Webroot Secure Anywhere International
				50, 	-- Mobile
				51, 	-- Mobile International
				100, 	-- Webroot Secure Anywhere
				200, 	-- Webroot Secure Anywhere International
				300 	-- OpenText Business
			) 
		AND l.license_id > @license_id - 1000 
		AND l.keycode <> ''
		AND s.license_id IS NULL 
		AND dm.license_distribution_method_code <> 'NSBF'

END TRY

BEGIN CATCH

	SET @response_code = -200
	SET @message = CASE WHEN @message IS NULL THEN 'usp_prevx_uodate_queue failed'
						ELSE @message END

	DECLARE @DBName NVARCHAR(128)
	SET @DBName = DB_NAME()
	EXECUTE dbo.usp_LogError @ErrorDB = @DBName
	
END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_prevx_update_s2_license_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_prevx_update_s2_license_update]

(
		@prevx_update_s2_id int,
		@response_id smallint,
		@response_text varchar(5000)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-03-18	esmart		Initial creation
	2024-10-29  msoni       IM-3525038: Update @response_text from varchar(25) to varchar(5000)

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@response_message varchar(20),
			@prevx_update_status_id tinyint,
			@update_attempts tinyint,
			@current_prevx_update_status_id tinyint,
			@prevx_update_type_id tinyint,
			@new_prevx_update_type_id tinyint,
			@license_id int,
			@modified_date datetime,
			@capability_expiration_date datetime,
			@process_date datetime

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @modified_date = getdate()

	-- 1.1) select @prevx_update_type_id
	select @prevx_update_status_id = case when @response_text = 'SUCCESS' then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_prevx_update_status_id = prevx_update_status_id,
			@prevx_update_type_id = prevx_update_type_id,	
			@license_id = license_id
	from prevx_update_s2
	where prevx_update_s2_id = @prevx_update_s2_id

	if @current_prevx_update_status_id in (1,3)
		begin
		select @response_code = -120, @response_message = 'No update on processed or abandoned updates'
		select response_code = @response_code, response_message = @response_message
		return
		end

	-- 1.3) if 5 failed attempts, abandon update
	if @update_attempts = 5 and @prevx_update_status_id = 2 -- failed
		begin
		select @prevx_update_status_id = 3 -- abandoned
		end

	select prevx_update_status_id = @prevx_update_status_id, update_attempts = @update_attempts

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) Processed
	if @prevx_update_status_id  = 1
		begin
		-- 2.1.1) insert archive record
			--print('2.1.1')
			insert into prevx_update_s2_archive(prevx_update_s2_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date)
			select prevx_update_s2_id, license_id, prevx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update_s2
			where prevx_update_s2_id = @prevx_update_s2_id

			-- 2.1.2) delete update record
			delete
			from prevx_update_s2
			where prevx_update_s2_id = @prevx_update_s2_id
		
			select @response_code = 0, @response_message = 'Update processed'	
		end
	
	-- 2.2) Failure
	if @prevx_update_status_id = 2
		begin
--		print('2.2')
			-- 2.1) log failure
			insert into prevx_update_s2_failure(prevx_update_s2_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, failure_date)
			select prevx_update_s2_id, license_id, pr
evx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update_s2
			where prevx_update_s2_id = @prevx_update_s2_id
	
			-- 2.2.2) update queue
			update prevx_update_s2 
			set prevx_update_status_id = @prevx_update_status_id,
				update_attempts = @update_attempts,
				response_id = @response_id,
				response_text = @response_text,
				modified_date = @modified_date,
				process_date = dateadd(mi,5,process_date)
			where prevx_update_s2_id = @prevx_update_s2_id

			-- 2.2.3) set 
			select @response_code = -220, @response_message = 'Update failed'
		end
	
	-- 2.3) Abandoned
	if @prevx_update_status_id = 3
		begin
			-- 2.3.1) insert archive record
			--print('2.3.1')
			insert into prevx_update_s2_archive(prevx_update_s2_id, license_id, prevx_update_type_id, prevx_update_status_id, response_id, response_text, update_attempts, insert_date, modified_date, process_date, archive_date)
			select prevx_update_s2_id, license_id, prevx_update_type_id, prevx_update_status_id, @response_id, @response_text, update_attempts, insert_date, modified_date, process_date, @modified_date
			from prevx_update_s2
			where prevx_update_s2_id = @prevx_update_s2_id

			-- 2.3.2) delete update record
			delete
			from prevx_update_s2
			where prevx_update_s2_id = @prevx_update_s2_id
--		
			select @response_code = -230, @response_message = 'Update abandoned'	
		end

		select response_code = @response_code, [message] = @response_message 
	end try

	begin catch

		set @response_code = -200
		set @response_message = case when @response_message is null then 'update account update failed'
							else @response_message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_process_delete_order_load_data]
-- =============================================================================
CREATE PROCEDURE usp_process_delete_order_load_data

(
	@invoice_code varchar(16),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2007-02-20		esmart			Initial creation
	2007-03-07		esmart			Change @vendor_order_id to int

	DESCRIPTION
	Update and delete rows so that an order can be re-processed
*/

AS

	set nocount on

	declare @vendor_order_id int
	
	set @response_code = 0
	set @message = 'Successfully removed order load data'

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) get vendor_order_id for the invoice_code
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @vendor_order_id = invoice_in_process_id from invoice_in_process where invoice_code = @invoice_code
	
	if @vendor_order_id is null
		begin
		set @response_code = -100	
		set @message = 'No matching invoice record in invoice_in_process'
		return
		end

	
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2) complete updates and deletes
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	begin transaction
		-- 2.1) update invoice_in_process
		update invoice_in_process set invoice_status_id = 1 where invoice_in_process_id = @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -210
				set @message = 'Error - update invoice_in_process'
				rollback transaction 
				return
			end		
	
		-- 2.2) delete order_notification_status
		delete from order_notification_status where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -220
				set @message = 'Error - delete order_notification_status'
				rollback transaction 
				return
			end		
	
		-- 2.3) delete customer_load
		delete from customer_load  where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -230
				set @message = 'Error - delete customer_load'
				rollback transaction 
				return
			end		
	
		-- 2.4) delete order_load
		delete from order_load  where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -240
				set @message = 'Error - delete order_load'
				rollback transaction 
				return
			end		
	
		-- 2.5) delete order_item_license_load
		delete order_item_license_load 
		from order_item_license_load
		inner join order_item_load 
			on order_item_license_load.order_item_load_id = order_item_load.order_item_load_id
		where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -250
				set @message = 'Error - delete order_item_license_load'
				rollback transaction 
				return
			end		
	
		-- 2.6) delete order_item_load
		delete from order_item_load where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -260
				set @message = 'Error - delete order_item_load'
				rollback transaction 
				return
			end		
	
		-- 2.7) delete order_load_audit
		delete from order_load_audit where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -270
				set @message = 'Error - delete order_load_audit'
				rollback transaction 

				return
			end		
	commit transaction


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_process_delete_order_load_data_DR]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_process_delete_order_load_data_DR]

(
	@vendor_order_id varchar(20),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR			REMARKS
	2007-04-12		esmart			Initial creation

	DESCRIPTION
	Update and delete rows so that an order can be re-processed
*/

AS

	set nocount on

	set @response_code = 0
	set @message = 'Successfully removed order load data'

	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1) complete updates and deletes
	-- ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	begin transaction
		-- 1.1) delete order_notification_status
		delete from order_notification_status where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -110
				set @message = 'Error - delete order_notification_status'
				rollback transaction 
				return
			end		
	
		-- 1.2) delete customer_load
		delete from customer_load  where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -120
				set @message = 'Error - delete customer_load'
				rollback transaction 
				return
			end		
	
		-- 1.3) delete order_load
		delete from order_load  where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -130
				set @message = 'Error - delete order_load'
				rollback transaction 
				return
			end		
	
		-- 1.4) delete order_item_license_load
		delete order_item_license_load 
		from order_item_license_load
		inner join order_item_load 
			on order_item_license_load.order_item_load_id = order_item_load.order_item_load_id
		where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -140
				set @message = 'Error - delete order_item_license_load'
				rollback transaction 
				return
			end		
	
		-- 1.5) delete order_item_load
		delete from order_item_load where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -150
				set @message = 'Error - delete order_item_load'
				rollback transaction 
				return
			end		
	
		-- 1.6) delete order_load_audit
		delete from order_load_audit where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -160
				set @message = 'Error - delete order_load_audit'
				rollback transaction 
				return
			end	

		-- 1.7) delete order_notification_load
		delete from order_notification_load where vendor_order_id= @vendor_order_id

		if @@error <> 0
			begin
				set @response_code = -170
				set @message = 'Error - delete order_notification_load'
				rollback transaction 
				return
			end	
			
			
	commit transaction


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_process_order_notification_load]
-- =============================================================================



CREATE procedure [dbo].[usp_process_order_notification_load]
(
	@vendor_order_id bigint,
	@order_type varchar(30),
	@response_code int OUTPUT,
	@message varchar(100)OUTPUT
)

as

/*	DATE		AUTHOR			REMARKS
	11/27/06	jegbert/tblazek		Initial creation 
	12/18/06	tblazek			Prevent test orders from processing.  Delete them out of the order_notification_laod table.
	12/27/06	tblazek			Add @order_type as input param to support refunds coming in from SOA file
	12/29/06	tblazek			Re-work line_item numbering logic and add insert to new line_item load mapping table
	01/02/07	tblazek			Exclude shipping customer for refunds
	01/05/07	tblazek			Sort items by product_type_id to order items by new, renew, upgrade
	03/30/07	mscardino		Added error handling for string functions, cleaned up code to make it easier to read,
									replaced set with select for better performance
	04/27/07 mscardino		Added transaction_description <> '' for the line item load (insert into temp_order_item_load), 
									because we need line_item_id for the line	level attributes on auto_renewal, however the code wasn't 
									smart enough to realize that these were not orders
	05/07/07    bjordan			Added usp_order_vendor_order_item to populate vendor_order_item table, removed contingency
								on temp_order_item_license_load and temp_order_item_load by using table variables and
								cleaned up variable assignments that did not need multiple select statements.
								Also added @product_id to usp_load_update_complete call for CD2go
	05/22/07					Removed usp_order_vendor_order_item and inserted it into usp_order_item_insert
	09/14/07	bjordan			Added check to order_value to ensure it is numeric when order_value_name =  'VISITORID'
	10/03/07	bjordan			Added Error Handling and moved usp_load_update_complete into the transaction
	10/24/07	bjordan			Added logic to trap null vendor_order_ids
	10/29/07	bjordan			@trx_rc had invalid length being passed because of a bad reference
	11/08/07	bjordan			Added logic to use the billing email address if a shipping one is not present
	11/30/10	acoffel			Added product_id = 'DR_EDS_PRODUCT' exception handling. Change to product_id = 129
	DESCRIPTION
		Insert load tables for order notification from Digital River cart.
*/
begin try

--set nocount on

declare
	@order_item_load_id bigint,
	@lineid bigint,
	@vendor_id int,
	@vendor_customer_id bigint,
	@vendor_address_id int,
	@customer_type varchar(10),
	@first_name nvarchar(255),
	@middle_name nvarchar(255),
	@last_name nvarchar(255),
	@address_1 nvarchar(255),
	@address_2 nvarchar(255),
	@address_3 nvarchar(255),
	@city nvarchar(130),
	@state  char(2),
	@postal_code varchar(32),
	@country char(3),
	@phone_number varchar(64),
	@fax_number varchar(64),
	@company_name nvarchar(255),
	@alternate_phone_number varchar(64),
	@customer_email nvarchar(255),
	@opt_in int,
	@line_item int,
	@line_item_big bigint,
	@vendor_product_id int,
	@quantity int,
	@order_item_offer_id varchar(65),
	@order_item_offer_amount money,
	@list_price money,
	@unit_price money,
	@tax_item_total	money,
	@tax_exempt bit	,
	@product_id int,
	@conversion_product_id int,
	@product_locale char(5),
	@vendor_order_code varchar(100),
	@site_id varchar	(65),
	@p_rc	varchar	(50),
	@p_rsc	varchar	(50),
	@p_ac	varchar	(100),
	@trx_rc	varchar	(50),
	@trx_rsc varchar(50),
	@trx_ac varchar	(100),
	@aid varchar(50)	,
	@pid varchar(50)	,
	@sid varchar(100),
	@offer_id varchar(65),
	@offer_amount money,
	@total_amount money ,
	@sub_total_amount money,
	@tax_amount money,
	@payment_method varchar(255),
	@exchange_rate	money,
	@visitor_id bigint,
	@submission_date datetime,
	@sales_order_date datetime,
	@locale	char(5),
	@where_heard varchar(64),
	@test_order bit,
	@order_load_id int,
	@str varchar(30),
	@ts
tr varchar(30),
	@vstr varchar (100),
	@cjstr varchar(30),
	@testord int,			
	@submissiondate datetime,
	@insert_date datetime,
	@insert_by varchar(50),
	@order_notification_status_id int,
	@order_load_definition_id int,
	@order_load_error_definition_id int,
	@customer_load_id int,
	@program_id varchar (20),
	@keycode varchar(60),
	@order_item_license_load_id bigint,
	@site_url varchar(20),
	@next_id int,
	@curr_id int,
	@loop_id smallint,
	@next_lic_id int,
	@curr_lic_id int,
	@loop_lic_id smallint,
	@system_user varchar(50),
	@line_item_cnt int,
	@order_item_line_item_load_id int,
    @no_soa smallint

		
-- 5/10/07 - Removed contingency on temp_order_item_license_load and temp_order_item_load for performance 
--		     and potential data corruption reasons

declare @temp_order_item_license_load TABLE ([temp_order_item_license_load_id] [int] IDENTITY(1,1) NOT NULL,
											[vendor_order_id] [bigint] NULL,
											[vendor_id] [int] NULL,
											[line_item_id] [bigint] NULL,
											[keycode] [varchar](40)  NULL) 
	
declare @temp_order_item_load TABLE ([temp_order_item_load_id] [int] IDENTITY(1,1) NOT NULL,
									[vendor_order_id] [bigint] NULL,
									[vendor_id] [int] NULL,
									[line_item_id] [bigint] NULL,
									[vendor_product_id] [int] NULL,
									[quantity] [int] NULL,
									[line_offer_ID] [bigint] NULL,
									[line_offer_amount] [money] NULL,
									[line_list_price] [money] NULL,
									[line_unit_price] [money] NULL,
									[line_tax_amount] [money] NULL,
									[tax_exempt] [bit] NULL,
									[product_id] [int] NULL,
									[conversion_product_id] [int] NULL,
									[product_locale] [char](5) NULL) 
	

declare @proctrancount int

set @proctrancount = @@trancount


--If test order, delete records and return
select 
	@test_order = 
	case 
		when onl.test_order_ind = 'False' then 0 else 1 
	end  
from 
	order_notification_load onl,  vendor ven
where 
	ven. vendor_name = 'Digital River'
	and  onl.vendor_order_id = @vendor_order_id
	and payment_method <> ''


if @test_order = 1
begin

	delete 
		order_notification_load 
	where 
		vendor_order_id = @vendor_order_id
	

end


	-- Initialize variables
	-- SET @order_type = 'DRE5'  
	-- NOTE this should be table driven in procedure. Hard coding for development only. need to determine how to identify each
	select @site_url = 'DRE5', -- DR platform programatically
		   @loop_id = 1,
		   @loop_lic_id = 1,
		   @system_user = system_user,
		   @insert_date = getdate(),
		   @response_code = 0,
		   @line_item_cnt = 1,
		   @vendor_id = 2

	--Process Billing customer 				
	select  
		@vendor_order_id = onl.vendor_order_id ,
		@vendor_id = ven.vendor_id,
		@customer_type = ct.customer_type_description,
		@vendor_customer_id = convert(bigint,onl.bill_to_customer_id),
		@first_name = onl.bill_to_first_name,
		@last_name = onl.bill_to_last_name,
		@address_1 = onl.bill_to_address1, 
		@address_2 = onl.bill_to_address2,
		@address_3 = onl.bill_to_address3,
		@city =  onl.bill_to_city, 
		@state = onl.bill_to_state,
		@postal_code = onl.bill_to_postal_code, 
		@country = case when onl.bill_to_country = c.iso then c.iso3 else onl.bill_to_country end, 
		@phone_number = case when onl.bill_to_phone_number = '' then null else onl.bill_to_phone_number end,  
		@fax_number = case when onl.bill_to_fax = '' then null else onl.bill_to_fax end,  
		@company_name = case when onl.bill_to_company_name = '' then null else onl.bill_to_company_name end, 
		@alternate_phone_number =case when onl.bill_to_alt_phone = '' then null else onl.bill_to_alt_phone end,
		@customer_email = onl.bill_to_email,
		@opt_in = case  when  onl.opt_in= 'false' then 0 else 1 end
	from 
		order_notification_load onl, vendor ven, customer_type ct, lu_countries c
	where 
		ven.vendor_name = 'digital river'
		and  onl.vendor_order_id = @vendor_order_id
		and ct.customer_type_description = 'billing'
		and onl.bill_to_first_name is not null
		and len(onl.bill_to_first_name) > 0 
		
and c.iso = onl.bill_to_country

	if @vendor_order_id is null or @vendor_id is null or @customer_type is null or @vendor_customer_id is null or @last_name is null
		begin
			select @response_code = -100,
				   @message = 'customer billing data missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' - Digital River order notification load fails'
			set @message = 'Invalid quantity, response code %d'
			RAISERROR (@message, 11, 0)
		end
	else
		begin

		execute usp_customer_load @vendor_order_id, @vendor_id, @vendor_customer_id, @vendor_address_id, @customer_type, 
			@first_name, @middle_name, @last_name, @address_1, @address_2,@address_3, @city, @state, @postal_code, @country, 
			@phone_number, @fax_number, @company_name, @alternate_phone_number, @customer_email, @opt_in, 
			@response_code OUTPUT, @message OUTPUT, @customer_load_id OUTPUT 
		
		if @response_code <> 0
			begin
				RAISERROR (@message, 11, 0)
			end
		end


-- Transaction management
--begin transaction PROCESS_ORDER_NOTIFICATION_LOAD

	-- load customer data


	--Process Shipping customer for new orders only.  Skip for refunds.
	if @order_type = 'DRE5'
	begin
		select  
			@vendor_order_id= onl.vendor_order_id,
			@vendor_id = ven.vendor_id,
			@customer_type = ct.customer_type_description,
			@vendor_customer_id = 0,  --MISSING FROM ONL table, defaulting to 0 until resolved
			@first_name = onl.ship_to_first_name,
			@last_name = onl.ship_to_last_name,
			@address_1 = onl.ship_to_address1, 
			@address_2 = onl.ship_to_address2,
			@address_3 = onl.ship_to_address3,
			@city =  onl.ship_to_city, 
			@state = onl.ship_to_state,
			@postal_code = onl.ship_to_postal_code, 
			@country = case when onl.ship_to_country = c.iso then c.iso3 else onl.ship_to_country end,
			@phone_number = case when onl.ship_to_phone_number = '' then null else onl.ship_to_phone_number end,  
			@fax_number = case when onl.ship_to_fax = '' then null else onl.ship_to_fax end,  
			@company_name = case when onl.ship_to_company_name = '' then null else onl.ship_to_company_name end, 
			@alternate_phone_number =case when onl.ship_to_alt_phone = '' then null else onl.ship_to_alt_phone end,
			@customer_email = case when isnull(onl.ship_to_email,'') = '' then onl.bill_to_email else onl.ship_to_email end,
			@opt_in = case   when  onl.opt_in= 'false' then 0 else 1 end
		from 
			order_notification_load onl,  vendor ven, customer_type ct, lu_countries c
		where
			ven. vendor_name = 'digital river'
			and  onl.vendor_order_id = @vendor_order_id
			and ct.customer_type_description = 'shipping' 
			and onl.ship_to_first_name is not null
			and onl.ship_to_first_name <> ''
			and c.iso = onl.bill_to_country

		if @vendor_order_id is null or @vendor_id is null or @customer_type is null or @vendor_customer_id is null or @last_name is null
			begin
				select @response_code = -105,
					   @message = 'customer shipping data missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' - Digital River order notification load fails'
				RAISERROR (@message, 11, 0)
			end
		else
			begin
				execute usp_customer_load @vendor_order_id, @vendor_id, @vendor_customer_id, @vendor_address_id, @customer_type, 
					@first_name, @middle_name, @last_name, @address_1, @address_2,@address_3, @city, @state, @postal_code, @country, 
					@phone_number, @fax_number, @company_name, @alternate_phone_number, @customer_email, @opt_in, 
					@response_code OUTPUT, @message OUTPUT, @order_load_id OUTPUT
				
				if @response_code <> 0
					begin 
						RAISERROR (@message, 11, 0)
					end
			end

	end -- shipping customer for new orders only
	
	-- Get Primary Ref values.  
	select @str = (select top 1 order_value from order_notification_load 
	where order_value_name =  'PrimaryRef' and vendor_order_id = @vendor_order_id)

	if len(@str) > 0 and charindex( '|' , @str ) > 0
		begin

			select @p_rc = left( @str, charindex( '|' , @str ) -1 ) 
			      ,@p_ac = substring( @str, 
charindex('|' , @str) +1  , charindex('|' , @str, charindex('|' , @str) + 1)  - charindex('|', @str) -1) 
			      ,@p_rsc = right( @str, charindex( '|', reverse( @str ) ) - 1 ) 
		end
	-- Get TrxRef values.

	select @tstr = (select top 1 order_value from order_notification_load 
	where order_value_name =  'TrxRef' and vendor_order_id = @vendor_order_id)

	if len(@tstr) > 0 and charindex( '|' , @tstr ) > 0
		begin
			select @trx_rc = left( @tstr, charindex('|', @tstr) -1)
				   ,@trx_ac = substring( @tstr, charindex('|', @tstr) +1  , charindex('|' , @tstr, charindex('|', @tstr) + 1)  - charindex('|', @tstr) -1) 
	               ,@trx_rsc = right( @tstr, charindex('|', reverse(@tstr)) - 1) 

		end
	-- Validate code types, convert to null if blank to prevent insert into order_code table with blank value for code
	if @p_rc is null or @p_rc = '' 
	begin
		select @p_rc = 1
	end
	if @p_ac = ''  
	begin
		select @p_ac = null
	end
	if @p_rsc = ''  
	begin
		select @p_rsc = null
	end
	if @trx_rc = ''  
	begin
		select @trx_rc = null
	end
	if @trx_ac = ''  
	begin
		select @trx_ac = null
	end
	if @trx_rsc = ''  
	begin
		select @trx_rsc = null
	end

	-- Auto Renewal
      insert into auto_renewal_feed (vendor_order_id, keycode, product_id, line_item_id, vendor_order_date, enroll_date, auto_renewal_description)
      select
            @vendor_order_id, key_code, case when product_id = 'DR_EDS_PRODUCT' then 129 
										when product_id like 'DR_CDTOGO_%' then 128 else product_id end as product_id, 
			line_item_id, convert( datetime, substring(submission_date, 1, 10) + ' ' + substring(submission_date, 12,11)), getdate(), 'Auto-Renewal'
      from
            order_notification_load onl
      where 
            exists
            (select distinct vendor_order_id, line_item_id 
            from order_notification_load 
            where vendor_order_id = onl.vendor_order_id 
            and line_item_id = onl.line_item_id
            and line_value_name = 'autobill'
            and line_value = 'True')
            and vendor_order_id = @vendor_order_id
            and product_id <> ''


	-- Get Visitor Id 
	select @visitor_id = (select top 1 order_value 
							from order_notification_load 
							where order_value_name =  'VISITORID'
						    and vendor_order_id = @vendor_order_id
							and isnumeric(order_value)=1)

	-- For digital river, default visitor_id to 1 if it comes in as blank or null
	if @visitor_id is null or @visitor_id = ''
	begin
		select @visitor_id = 1
	end

	--Get Commission Junction Values

	--12/04/06 COMMENT OUT cj parsing logic.  Currently, coming in as a blank with no "|" dividers.  cj is not implemented yet with question about
	--if it ever will be implemented.  
	-- Select @cjstr = (select distinct order_value from order_notification_load 
	-- where order_value_name =  'CJref' and vendor_order_id = @vendor_order_id)
	-- 
	-- select 	@aid= left(@cjstr, charindex('|' , @cjstr) -1), 
	-- 	@pid = substring(@cjstr, charindex('|', @cjstr) + 1 , charindex('|', @cjstr, charindex('|', @cjstr) + 1)  - charindex('|', @cjstr) -1), 
	-- 	@sid = right(@cjstr, charindex('|', reverse(@cjstr)) - 1)

	-- load order header info
	select 
		@vendor_order_id = onl.vendor_order_id, 
		@vendor_id =  ven.vendor_id, 
		@vendor_order_code = @vendor_order_id ,
		@site_id = onl.site_ID, 
		@offer_id = onl.order_offer_id, 
		@program_id = onl.program_id,
		@offer_amount = onl.order_offer_amount, 
		@total_amount = onl.total_amount, 
		@sub_total_amount = onl.sub_total_amount, 
		@tax_amount = onl.tax_total, 
		@payment_method = onl.payment_method, 
		@exchange_rate = onl.exchange_rate,
		@submission_date = convert( datetime, substring(onl.submission_date, 1, 10) + ' ' + substring(onl.submission_date, 12,11)), 
		@sales_order_date = convert( datetime, substring(onl.submission_date, 1, 10) + ' ' + substring(onl.submission_date, 12,11)), 
		@locale = onl.order_locale, 
		@where_heard = CASE WHEN  onl.where_heard is null THEN '' else onl.wher
e_heard end , 
		@test_order = CASE WHEN  onl.test_order_ind = 'False' THEN 0 else 1 end  
	from 
		order_notification_load onl,  vendor ven
	where 
		ven.vendor_name = 'Digital River'
		and onl.vendor_order_id = @vendor_order_id
		and payment_method <> ''

	if @vendor_order_id is null or @vendor_id is null or @vendor_order_code is null or @order_type is null or @site_id is null or @site_url is null
	   or @p_rc is null or @total_amount is null or @sub_total_amount is null or @payment_method is null or @visitor_id is null or @submission_date is null
	   or @locale is null
	begin
		select @response_code = -110,
			   @message = 'order data missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' - Digital River order notification load fails'
		RAISERROR (@message, 11, 0)
	end

	exec usp_order_load @vendor_order_id, @vendor_id, @vendor_order_code, @order_type, @site_id, @site_url, @p_rc, @p_rsc, @p_ac, @trx_rc, @trx_rsc, 
		@trx_ac, @aid, @pid, @sid, @offer_id, @offer_amount, @total_amount, @sub_total_amount, @tax_amount, @payment_method, @exchange_rate,
		@visitor_id, @submission_date, @sales_order_date, @locale, @where_heard, @test_order, @response_code OUTPUT , @message OUTPUT , @order_load_id OUTPUT 

	if @response_code <> 0
		begin
			RAISERROR (@message, 11, 0)
		end

	-- update internal product ids prior to insert for proper sorting of items. (new, renewal, upgrade)
	update 
		order_notification_load 
	set 
		product_id = vendor_product.product_id
	from 
		order_notification_load, vendor_product
	where 
		order_notification_load.vendor_product_id = vendor_product.vendor_product_code
		and order_notification_load.vendor_order_id = @vendor_order_id
		and vendor_product.vendor_id = 2 

	update order_notification_load 
	set product_id = 129
	where product_id = 'DR_EDS_PRODUCT' 

	update order_notification_load 
	set product_id = 128
	where product_id like 'DR_CDTOGO_%' 

	-- Update Line Items Detail
	insert @temp_order_item_load (vendor_order_id ,
		vendor_id ,
		line_item_id ,
		vendor_product_id ,
		quantity ,
		line_offer_ID ,
		line_offer_amount ,
		line_list_price ,
		line_unit_price ,
		line_tax_amount ,
		tax_exempt ,
		product_id ,
		conversion_product_id ,
		product_locale)
 	select  
		onl.vendor_order_id,
	 	@vendor_id,
	 	onl.line_item_id,
		onl.vendor_product_id,
	 	onl.quantity,
	 	onl.line_offer_id,
		onl.line_offer_amount ,
	 	onl.line_price_per_qty, ---line_list_price,
		onl.line_unit_price,
	 	onl.line_tax_amount,
	 	case when onl.tax_exempt= 'False' then 0 else 1 end,
		onl.product_ID, 
	 	null, --onl.line_value,
	 	onl.product_locale
	from 
		order_notification_load onl
	inner join 
		product p
		on onl.product_id = p.product_id
	inner join 
		product_type pt
		on p.product_type_id = pt.product_type_id
	where   
		onl.vendor_order_id = @vendor_order_id
	 	and line_item_id <> ''
		-- added, because we need line_item_id for the line
		-- level attributes on auto_renewal, however the code
		-- wasn't smart enough to realize that these were not orders
		and transaction_description <> ''
	group by 
		onl.vendor_order_id,
		-- ven.vendor_id,
		onl.line_item_id,
		onl.vendor_product_ID,
		onl.quantity,
		onl.line_offer_ID,
		onl.line_offer_amount ,
		onl.line_price_per_qty, --oln.line_list_price,
		onl.line_unit_price,
		onl.line_tax_amount,
		onl.tax_exempt,
		onl.product_ID,
		--'', --oln.line_value,
		onl.product_locale,
		pt.product_type_id
	order by 
		pt.product_type_id 

	-- update conversion_product_id
	update  
		t
	set  
		t.conversion_product_id = 
		case 
			when isnumeric(order_notification_load.line_value) = 1 then order_notification_load.line_value
			else null 
		end  
	from 
		order_notification_load 
	inner join 
		@temp_order_item_load t
		on t.vendor_order_id = order_notification_load.vendor_order_id
		and t.line_item_id  = order_notification_load.line_item_id
	where
		order_notification_load.line_value_name = 'ConvID'

	insert @temp_order_item_license_load (vendor_o
rder_id ,
		vendor_id ,
		line_item_id ,
		keycode)
	select 
		onl.vendor_order_ID, 
		ven.vendor_id,
		onl.line_item_id, 
		dbo.fn_RemoveDashes(onl.key_code) 
	from 
		order_notification_load onl,  vendor ven
	where 
		ven.vendor_name = 'Digital River'
		and onl.vendor_order_id = @vendor_order_id
		and key_code is not null
		and key_code <> ''
	group by 
		onl.vendor_order_ID, 
		ven.vendor_id,
		onl.line_item_id, 
		onl.key_code

	select @next_id = min(temp_order_item_load_id) from @temp_order_item_load where vendor_order_id = @vendor_order_id and vendor_id = @vendor_id

	select @curr_id = @next_id

	while @loop_id = 1
	begin 
		---BEGIN ORDER ITEM LOAD WHILE LOOP  
		select 
			@vendor_order_id = vendor_order_id,
			@vendor_id =vendor_id,
			@line_item = @line_item_cnt, --Set line item to sequencial number of order items instead of bigint value in line_item_id,
			@line_item_big = line_item_id,
			@vendor_product_id = vendor_product_ID,
			@quantity = quantity,
			@order_item_offer_id= line_offer_ID,
			@order_item_offer_amount =line_offer_amount ,
			@list_price = line_list_price,
			@unit_price =line_unit_price,
			@tax_item_total = line_tax_amount,
			@tax_exempt =tax_exempt,
			@product_id = product_ID,
			@product_locale = product_locale
		from 
			@temp_order_item_load 
		where 
			temp_order_item_load_id = @next_id

		if @product_id is null  
		begin
			select @response_code = -113,
				   @message = 'product_id missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + '. cannot process order item - Digital River order notification load fails'
			RAISERROR (@message, 11, 0)
		end
	
		if @vendor_order_id is null or @vendor_id is null or @line_item is null or @quantity is null or @list_price is null or @unit_price is null
			or @tax_item_total is null or @tax_exempt is null or @product_locale is null
			or @locale is null
		begin
			
			select @response_code = -115,
			       @message = 'order item data missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' - Digital River order notification load fails'
			
			RAISERROR (@message, 11, 0)
		end

		if @order_type <> 'DRE5'  --All other types are refunds
		begin
		-- Reset the line item to the original order line item for refund processing

		-- Set quantity and list price on Full refunds
		if @order_type = 'DRSOAREFUNDFULL'
		begin

			select  
				@line_item = oila.line_item , 
				@quantity = (oila.quantity * -1) 
			from 
				order_item_load_archive oila
			inner join 
				order_item_line_item_load_archive oitila
				on oitila.order_item_load_id = oila.order_item_load_id
			where 
				oitila.line_item_big = @line_item_big
				and vendor_order_id = @vendor_order_id
	
			select @list_price = abs(@list_price)

		end
		else if @order_type = 'DRSOAREFUNDPARTIAL' and @quantity < 0  --Set list price to positive number for full line item refund
		begin

			select 
				@line_item = oila.line_item 
			from 
				order_item_load_archive oila
			inner join
				order_item_line_item_load_archive oitila
				on oitila.order_item_load_id = oila.order_item_load_id
			where 
				oitila.line_item_big = @line_item_big
				and vendor_order_id = @vendor_order_id
	
			select @list_price = abs(@list_price)

		end
		else
		begin

			select 
				@line_item = oila.line_item 
			from 
				order_item_load_archive oila
			inner join 
				order_item_line_item_load_archive oitila
				on oitila.order_item_load_id = oila.order_item_load_id
			where 
				oitila.line_item_big = @line_item_big
				and vendor_order_id = @vendor_order_id
		end

	end

	execute usp_order_item_load @vendor_order_id, @vendor_id, @line_item, @vendor_product_id, @quantity, @order_item_offer_id, @order_item_offer_amount, 
			@list_price, @unit_price, @tax_item_total, @tax_exempt, @product_id, @conversion_product_id, @product_locale, 
			@response_code OUTPUT, @message OUTPUT, @order_item_load_id OUTPUT
	if @response_code <> 0
	begin 
		RAISERROR (@message, 11, 0)
	end

	execute u
sp_order_item_line_item_load @vendor_order_id, @vendor_id, @order_item_load_id, @line_item_big, @response_code OUTPUT, @message OUTPUT, 
		   @order_item_line_item_load_id OUTPUT
	if @response_code <> 0
	begin 
		RAISERROR (@message, 11, 0)
	end
    
	select
		@next_lic_id = min(temp_order_item_license_load_id) 
	from 
		@temp_order_item_license_load toill
	inner join  
		@temp_order_item_load toil
		on toill.vendor_order_id = toil.vendor_order_id
		and toill.vendor_id = toil.vendor_id
		and toill.line_item_id = toil.line_item_id
	where 
		toil.temp_order_item_load_id = @next_id 

	select @curr_lic_id = @next_lic_id

	if @next_lic_id > 0
	begin
		while @loop_lic_id = 1
		-- BEGIN ORDER ITEM LICENSE LOAD WHILE LOOP
		begin

			select 
				@vendor_order_id = vendor_order_id, 
				@vendor_id = vendor_id, 
				@keycode = keycode
			from 
				@temp_order_item_license_load
			where 
				temp_order_item_license_load_id = @next_lic_id

			if @vendor_order_id is null or @vendor_id is null or @keycode is null
			begin
				select @response_code = -115,
					   @message = 'order item license data missing, ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') + ' - Digital River order notification load fails'
				RAISERROR (@message, 11, 0)
			end

			exec usp_order_item_license_load @vendor_order_id, @vendor_id, @order_item_load_id, @keycode, @response_code OUTPUT,@message OUTPUT,
				 @order_item_license_load_id OUTPUT
			if @response_code <> 0
			begin
				RAISERROR (@message, 11, 0)
			end

			select @next_lic_id = null

			select 
				@next_lic_id = min(temp_order_item_license_load_id) 
			from 
				@temp_order_item_license_load toill
			inner join  
				@temp_order_item_load toil
				on toill.vendor_order_id = toil.vendor_order_id
				and toill.vendor_id = toil.vendor_id
				and toill.line_item_id = toil.line_item_id
				where toil.temp_order_item_load_id = @next_id 
				and temp_order_item_license_load_id > @curr_lic_id
			
			if ISNULL(@next_lic_id,0) = 0
			begin
				break
			end
			select @curr_lic_id = @next_lic_id
		end -- END ORDER ITEM LICENSE LOAD WHILE LOOP
	end
 
	select @line_item_cnt = @line_item_cnt + 1,
		   @next_id = null

	select 
		@next_id = min(temp_order_item_load_id) 
	from 
		@temp_order_item_load 
	where 
		vendor_order_id = @vendor_order_id 
		and vendor_id = @vendor_id
		and temp_order_item_load_id > @curr_id

	if ISNULL(@next_id,0) = 0
	begin
		select @line_item_cnt = 1
		if @product_id in ('128','129')--5/11/2007 addition for CD2Go,EDS
			set @no_soa = 1
		else
			set @no_soa = 0
		break
	end

	select @curr_id = @next_id

	end -- END ORDER ITEM LOAD WHILE LOOP

	
	select @order_load_error_definition_id = order_load_error_definition_id
	from order_notification_status 
	where vendor_order_id = @vendor_order_id and
		  vendor_id = @vendor_id

	if @order_load_error_definition_id is not null
		begin
			update onl
				set order_load_status = order_load_error
				from order_notification_load onl
				inner join order_notification_status s on
				onl.vendor_order_id = s.vendor_order_id
				inner join order_load_error_definition e on
				s.order_load_error_definition_id = e.order_load_error_definition_id
				where onl.vendor_order_id = @vendor_order_id

			RAISERROR (@message, 11, 0)
		end
	else
		begin

		--Archive order_notification_load data
		insert order_notification_load_archive			 
		select 
			vendor_order_id	,
			submission_date	,
			site_id	,
			total_amount	,
			sub_total_amount	,
			tax_total	,
			order_offer_amount	,
			exchange_rate	,
			payment_method	,
			bill_to_vendor_id	,
			bill_to_last_name	,
			bill_to_first_name	,
			bill_to_address1	,
			bill_to_address2	,
			bill_to_address3	,
			bill_to_phone_number	,
			bill_to_postal_code	,
			bill_to_city	,
			bill_to_state	,
			bill_to_email	,
			bill_to_fax	,
			bill_to_company_name	,
			bill_to_alt_phone	,
			bill_to_country	,
			line_item_id	,
			transaction_Description	,
			quantity	,
			vendor_product_id	,
			product_id,
			produc
t_locale	,
			ship_to_vendor_address_id	,
			ship_to_city	,
			ship_to_country	,
			ship_to_address1	,
			ship_to_address2	,
			ship_to_address3	,
			ship_to_last_name	,
			ship_to_first_name	,
			ship_to_phone_number	,
			ship_to_postal_code	,
			ship_to_state	,
			ship_to_email	,
			ship_to_fax	,
			ship_to_company_name	,
			ship_to_alt_phone	,
			line_unit_price	,
			line_list_price	,
			line_price_per_qty	,
			line_tax_amount	,
			tax_exempt	,
			line_offer_id	,
			line_offer_amount	,
			key_code	,
			Line_value_name	,
			line_value	,
			Program_id	,
			bill_to_customer_id	,
			order_offer_id	,
			order_locale	,
			opt_in	,
			where_heard	,
			test_order_ind	,
			order_value_name	,
			order_value	,
			order_load_status	,
			server_loc	,
			ts,
			process_flag 
		from 
			order_notification_load 
		where 
			vendor_order_id = @vendor_order_id

		delete from order_notification_load where vendor_order_id = @vendor_order_id

		execute usp_load_update_complete @vendor_order_id, @vendor_id, @system_user, @no_soa, @response_code OUTPUT, @message OUTPUT
			if @response_code <> 0
				begin
					-- If error returned from proc, proceed to endgame, all errors logged within proc
					RAISERROR (@message, 11, 0)
				end

		end
		


--commit transaction PROCESS_ORDER_NOTIFICATION_LOAD


end try
begin catch
	
--   if (@proctrancount + 1) = @@trancount
--	      rollback transaction PROCESS_ORDER_NOTIFICATION_LOAD;	
--
--	if @@trancount > 1 --roll back everything if there are still uncommitted transactions
--		  rollback transaction 

	if @message is null
		set @message = 'PROCESS_ORDER_NOTIFICATION_LOAD Failure ' + isnull(ltrim(rtrim(str(@vendor_order_id))),'Null Vendor_order_id') 

	exec usp_order_load_insert_audit @vendor_order_id, @vendor_id, @response_code, @message, @system_user, @insert_date, @response_code OUTPUT

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_process_pending_sap_customer]
-- =============================================================================
/*	
	date		author		remarks
	2022-01-18	psatish		initial creation
	2022-02-17  psatish		Updated the linked server name
	description
	intended for loading missing sap_account# into ecomm

*/
CREATE procedure [dbo].[usp_process_pending_sap_customer]
as
begin
	-- set nocount on added to prevent extra result sets from
	-- interfering with select statements.
	set nocount on;

		   declare @count int=1,@max_count int,@backfillid int

		--missing sap customers are not loaded into ecomm
		drop table if exists #temp1
		select cs.sap_account_number into #temp1
		from DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill cs
		inner join DATAWAREHOUSEREADONLY.feed.dbo.sap_partnerfunction_json js
		on js.sapcustomernumber=cs.sap_account_number
		left join sap_account sa
		on cs.sap_account_number=sa.sap_account_number
		where 
		sa.sap_account_number is null
		group by cs.sap_account_number


		declare @missing_sapaccount table
		(
		id int identity(1,1) primary key,
		sap_account_number int,
		backfillid int
		)

		insert into @missing_sapaccount
		(
			sap_account_number,
			backfillid
		)
		select  distinct top 750 cs.sap_account_number,cs.backfill_id
		from DATAWAREHOUSEREADONLY.feed.dbo.sap_customer_master_backfill cs
		inner join #temp1 tm
		on tm.sap_account_number=cs.sap_account_number
		
		
		select @max_count=count(*) from @missing_sapaccount
		
		while @count <=@max_count
		begin
		select @backfillid=backfillid from @missing_sapaccount where id=@count
	
		exec dbo.usp_sap_customer_backfill_new @backfill_id = @backfillid -- int


		set @count=@count+1
		end
end

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_offer]
-- =============================================================================
CREATE procedure [dbo].[usp_product_offer] 
(@product_id varchar(250) = null,
@offer_dest_id int = null,
@offer_code varchar(10) = null)
/*	

	DATE		AUTHOR		REMARKS
	2008-06-07	bjordan		Initial creation
	2008-07-30	bjordan		Enabled the ability to pass a series of products
							separated by a comma and get back all of the offers
	
	DESCRIPTION
	Generates a list of product offers


*/
as
begin try
set nocount on


----Testing

--declare @product_id varchar(250)
--declare @offer_dest_id int
--declare @offer_code int

----Testing end

declare @offer_count int
declare @lid int
declare @max_lid int
declare @working_pid varchar(10)

declare @product_rs table(rec_id int identity(1,1) not null,
						  offer_id int null,
						  product_id int null,
					      offer_product_id int null,
						  offer_dest_id int null,
						  product_offer_price money null,
						  offer_type int null,
						  offer_type_group int null,
						  product_offer_desc varchar(100))

declare @return_rs table (rec_id int identity(1,1) not null,
							offer_id [int] NOT NULL,
							product_id [int] NULL,
							offer_product_id [int] NULL,
							offer_dest_id [int] NULL,
							product_offer_price [money] NULL,
							offer_type [int] NULL,
							offer_type_group [int] NULL,
							product_offer_desc [varchar](100) NULL
							)



--set @product_id = '4060,38971,64151,64152,64153,64502,64503,64507,65101,65102,65103,65401,65402,65403'


--remove spaces from product list
set @product_id = replace(@product_id,' ','') 

--Create a working table of products based on list
select @lid = 1, @max_lid = (len(@product_id) - (len(replace(@product_id,',','')))+1)

while @lid <= @max_lid
	begin

	if @product_id like '%,%'
		begin

		set @working_pid = left(@product_id,charindex(',',@product_id)-1)
		--print @working_pid

		set @product_id = substring(@product_id,charindex(',',@product_id)+1,len(@product_id) - charindex(',',@product_id)+1)

		end
	else
		set @working_pid = @product_id

	insert into @product_rs (product_id)
	values(@working_pid)
	
	set @lid = @lid + 1

	end

	

if @product_id is null and @offer_code is null
	begin

	RAISERROR ('Both product_id and offer_code cannot be null', 11, 0)

	end

if @offer_dest_id is null 
	begin
		--Retrieve first page with interstitial being first

		update rs
			set offer_dest_id = od.offer_dest_id
			from @product_rs rs
			inner join (select min(po.offer_dest_id) as offer_dest_id,po.product_id
						from product_offer po
						inner join @product_rs prs 
						on po.product_id = prs.product_id
						where offer_enabled = 1
						group by po.product_id) od on
			rs.product_id = od.product_id
			
	
		
	end
else
	begin

	update rs
			set offer_dest_id = od.offer_dest_id
			from @product_rs rs
			inner join product_offer od on
			rs.product_id = od.product_id
			where od.offer_dest_id = @offer_dest_id

	end

--Gather offer_count if present on any products
select @offer_count = offer_count
from product_offer_scenario pos
inner join @product_rs rs on
pos.product_id = rs.product_id
where pos.offer_dest_id = @offer_dest_id
and pos.scenario_enabled = 1




if @offer_count is null --Proceed with Candy Rack selection
	begin

	if @offer_code is not null
		begin

			INSERT INTO @return_rs
				   ([offer_id]
				   ,[product_id]
				   ,[offer_product_id]
				   ,[offer_dest_id]
				   ,[product_offer_price]
				   ,[offer_type]
				   ,[offer_type_group]
				   ,[product_offer_desc])
			select po.offer_id,po.product_id,po.offer_product_id,po.offer_dest_id,po.product_offer_price
			,po.offer_type,po.offer_type_group,po.product_offer_desc
			from product_offer po
			inner join @produ
ct_rs pr on
			po.product_id = pr.product_id and
			po.offer_dest_id = pr.offer_dest_id
			where po.offer_code = @offer_code
				and po.offer_enabled = 1 
			order by po.display_order
		end
	else
		begin
		INSERT INTO @return_rs
				   ([offer_id]
				   ,[product_id]
				   ,[offer_product_id]
				   ,[offer_dest_id]
				   ,[product_offer_price]
				   ,[offer_type]
				   ,[offer_type_group]
				   ,[product_offer_desc])
		select po.offer_id,po.product_id,po.offer_product_id,po.offer_dest_id,po.product_offer_price
		,po.offer_type,po.offer_type_group,po.product_offer_desc
		from product_offer po
		inner join @product_rs pr on
			po.product_id = pr.product_id and
			po.offer_dest_id = pr.offer_dest_id
		where  po.offer_enabled = 1 
		order by display_order

		end

	end
else
	begin
	INSERT INTO @return_rs
				   ([offer_id]
				   ,[product_id]
				   ,[offer_product_id]
				   ,[offer_dest_id]
				   ,[product_offer_price]
				   ,[offer_type]
				   ,[offer_type_group]
				   ,[product_offer_desc])
	select top (@offer_count) po.offer_id,po.product_id,po.offer_product_id,po.offer_dest_id
	,po.product_offer_price,po.offer_type,po.offer_type_group,po.product_offer_desc
	from product_offer po
	inner join @product_rs pr on
			po.product_id = pr.product_id and
			po.offer_dest_id = pr.offer_dest_id
	where  po.offer_enabled = 1 
	order by newid()

	end


--Remove Duplicate 

--First remove duplicate offers based on price by setting it = null
update t
	set offer_product_id = null,
		offer_dest_id = null,
		product_offer_price = null,
		offer_type = null,
		product_offer_desc = null
	from @return_rs t
	inner join (select offer_product_id
				from @return_rs
				group by offer_product_id
				having count(*)>1) d on
	t.offer_product_id = d.offer_product_id
	left join (select offer_product_id,max(product_offer_price) as product_offer_price
				from @return_rs
				group by offer_product_id) u on
	t.offer_product_id = u.offer_product_id and
	t.product_offer_price = u.product_offer_price
	where u.offer_product_id is null


--Then remove duplicate offers that have the same price point by setting it = null
update t
	set offer_product_id = null,
		offer_dest_id = null,
		product_offer_price = null,
		offer_type = null,
		product_offer_desc = null
	from @return_rs t
	inner join (select offer_product_id
				from @return_rs
				group by offer_product_id
				having count(*)>1) d on
	t.offer_product_id = d.offer_product_id
	left join (select min(rec_id) as rec_id
				from @return_rs
				group by offer_product_id) u on
	t.rec_id = u.rec_id
	where u.rec_id is null


select [offer_id]
	   ,[product_id]
	   ,[offer_product_id]
	   ,[offer_dest_id]
	   ,[product_offer_price]
	   ,[offer_type]
	   ,[offer_type_group]
	   ,[product_offer_desc] 
from @return_rs
order by rec_id --preserves the order from above



end try
begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select]
-- =============================================================================






CREATE       PROCEDURE [dbo].[usp_product_select]

(
	@product_id int
)

AS

/*	DATE		AUTHOR			REMARKS
	2006-08-15	TBlazek			Initial creation.
	2006-09-04	esmart			Modified procedure to point to columns from new product table	
	2006-10-09	esmart			Add product_family_prefix
	2010-07-23	dsmelker		Added product_line_id to the output of the query
	2017-06-28	esmart			Additional columns

	DESCRIPTION
		Return a result set of a product row to the PHP code
*/

	set nocount on
	
	declare @return int
	select @return = 0
	
	
	select 	p.product_id, 
			p.product_description, 
			p.product_type_id, 
			t.product_type_description,
			p.product_family_id, 
			f.product_family_description,
			f.product_family_prefix,
			p.product_lifecycle_id, 
			l.product_lifecycle_description,
			p.root_product_id, 
			p.uses_keycode, 
			p.cd_product_id, 
			p.retail_price, 
			p.pict, 
			p.basename, 
			p.insert_date, 
			p.insert_by, 
			p.modified_date, 
			p.modified_by,
			plp.product_line_id,
			lc.license_category_id,
			lc.license_category_name,
			pc.capability_activation_days,
			license_type_id = case 
									when plp.product_line_id in (300,55) and p.license_keycode_type_id = 3 then 2
									when plp.product_line_id in (300,55) and p.license_keycode_type_id <> 3 then 4
									when plp.product_line_id not in (300,55) and p.license_keycode_type_id = 3 then 2
									when plp.product_line_id not in (300,55) and p.license_keycode_type_id <> 3 then 1
								end,
			ps.seats
			--select @license_type_id = case when @license_keycode_type_id = 3 then 2 else 4 end
			--select @license_type_id = case when @license_keycode_type_id = 3 then 2 else 1 end
	from product p
	inner join product_type t
		on p.product_type_id = t.product_type_id
	inner join product_family f
		on p.product_family_id = f.product_family_id
	inner join product_lifecycle l
		on p.product_lifecycle_id = l.product_lifecycle_id
	left outer join product_line_product plp
		on p.product_id = plp.product_id
	left join product_license_category plc
		on plc.product_id = p.product_id
	left join license_category lc
		on lc.license_category_id = plc.license_category_id
	left join product_capability pc
		on pc.product_id = p.product_id and pc.capability_id = lc.base_capability_id
	left join product_seat ps
		on ps.product_id = p.product_id
	Where p.product_id = @product_id



GO
