-- =============================================================================


CREATE PROCEDURE [dbo].[usp_product_select_configurator_pricing]
(
	@keycode varchar(40),
	@storage_product_id int,
	@renewal_product_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-25		esmart		Initial creation

	DESCRIPTION
	select available storage upgrade products for a given keycode. Calculate the price for the remaining months on a subscription
*/

AS
set nocount on

begin try

	declare @log_type int,
			@license_id int,
			@license_status_id int,
			@product_line_id int,
			@current_storage_gb int,
			@product_storage_gb int,
			@months_remaining int,
			@renewal_months int,
			@total_months int,
			@capability_activation_days int,
			@capability_expiration_date datetime,
			@transaction_date datetime,
			@license_activated int

	set @log_type = 1

	set @transaction_date = getdate()
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get license information
		select @license_id = l.license_id,
				@product_line_id = l.product_line_id,
				@current_storage_gb = isnull(s.storage_gb,1),
				@license_status_id = license_status_id
		from license l
		left join license_storage s
			on l.license_id = s.license_id
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -110,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

		if @current_storage_gb = 0
			begin
			select @current_storage_gb = 1
			end

		-- 1.2) get license_capability days
		--			NOTE: Need to calculate this for edge case of refunded purchase prior to activation
		select @capability_activation_days = max(capability_activation_days)
		from license_capability
		where license_id = @license_id --and capability_id = 11 (removed for SS w/o backup)


		-- 1.3) get remaining months on license
		if @license_status_id = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,max(capability_activation_days),@transaction_date),
						@license_activated = case when max(capability_expiration_date) is null then 0 else 1 end
				from license_capability
				where license_id = @license_id
			end
		else
			begin
				select @capability_expiration_date = max(capability_expiration_date),
						@license_activated = case when max(capability_expiration_date) is null then 0 else 1 end
				from license_capability
				where license_id = @license_id 
			end

		if @license_status_id = 1 and @license_activated = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,max(capability_activation_days),@transaction_date)
				from license_capability
				where license_id = @license_id
			end

			select @months_remaining = 0

		if @capability_expiration_date >= getdate()
			begin

				while dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
					begin
					select @months_remaining = @months_remaining + 1
					end

				select @months_remaining = 
						case
							when @months_remaining <= 1 and @capability_expiration_date is not null then 1
							when @months_remaining <= 1 and @capability_expiration_date is null then 0
							else @months_re
maining - 1
						end
			end

		-- 1.4) validate @storage_product_id
		if @storage_product_id is not null or @storage_product_id <> 0 
			begin
				select @response_code =  case when count(*) = 0 then -130 else 0	 end,
					@message = case when count(*) = 0 then '@storage_product_id ' + convert(varchar(10),@storage_product_id) + ' is not valid' else '' end
				from product
				where product_id = @storage_product_id

				if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end
			end

		-- 1.5) validate @renewal_product_id
		if @renewal_product_id is not null or @renewal_product_id <> 0 
			begin
				select @response_code =  case when count(*) = 0 then -140 else 0	 end,
					@message = case when count(*) = 0 then '@renewal_product_id ' + convert(varchar(10),@renewal_product_id) + ' is not valid' else '' end
				from product
				where product_id = @renewal_product_id

				if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end
				
				-- 1.5.1) get days from renewal or upgrade product to add to months remaining
				select @renewal_months = convert(int,capability_activation_days/30)
				from product_capability
				where product_id = @renewal_product_id and capability_id = 1 
			end 

		-- 1.6) get product_storage_gb

		select @product_storage_gb = storage_gb
		from product_storage
		where product_id = @storage_product_id


		-- 1.7) check for best buy monthly subscribers and set months remaining = 12
		declare @best_buy_monthly int

		select @best_buy_monthly = 
					case
						when count(*) > 0 then 1
						else 0
					end
		from subscription 
		where license_id = @license_id and subscription_type_id <> 2
		
		if @best_buy_monthly = 1
			begin
				select @months_remaining = 12
			end

--select capability_expiration_date = @capability_expiration_date, months_remaining = @months_remaining
		

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return products and pricing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select product_id, retail_price
		from product p
		where product_id = @renewal_product_id
		union
		select product_id, 
				retail_price = 
					case
						when @product_storage_gb = @current_storage_gb then retail_price
						else round(convert(money,(isnull(@months_remaining,0)) * (p.retail_price/12)),2) +  round(convert(money,(isnull(@renewal_months,0)) * (p.retail_price/12)),2)
					end
		from product p
		where product_id = @storage_product_id
		
end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_configurator_pricing_INT]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_product_select_configurator_pricing_INT]
(
	@storage_upgrade_dr_product_id int,
	@addition_year_product_id int,
	@renewal_upgrade_product_id int,
	@language_code varchar(2),
	@location_code varchar(3),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-30		esmart		Initial creation

	DESCRIPTION
	select available storage upgrade products for a given keycode. Calculate the price for the remaining months on a subscription
*/

AS
set nocount on

begin try

	declare @addition_year_dr_product_id int,
			@renewal_upgrade_dr_product_id int,
			@bundle_type int,
			@dr_bundle_id int,
			@log_type int,
--			@dr_product_id_1 int,
--			@dr_product_id_2 int,
--			@dr_product_id_3 int,
			@transaction_date datetime,
			@offer_id int,
			@parent_product_id int,
			@dr_product_id int,
			@2nd_product_id int
	
	set @log_type = 1
	set @transaction_date = getdate()	
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.0) change values to null if inputs are blank
		if @storage_upgrade_dr_product_id = 0
			begin
			select @storage_upgrade_dr_product_id = null
			end 

		if @addition_year_product_id = 0
			begin
			select @addition_year_product_id = null
			end 

		if @renewal_upgrade_product_id = 0
			begin
			select @renewal_upgrade_product_id = null
			end 

		-- 1.1 check to see if the renewal includes a WISE upgrade
		declare @current_storage_gb int, 
				@storage_gb int,
				@renewal_storage_gb int,
				@start_months int,
				@end_months int,
				@renewal_product_type_id int

		select @current_storage_gb = p.current_storage_gb,
				@storage_gb = p.storage_gb,
				@start_months = pp.start_months,
				@end_months = pp.end_months
		from dr_product_price pp 
		inner join product_storage p
			on pp.product_id = p.product_id
		where dr_product_id = @storage_upgrade_dr_product_id
					and language_code = @language_code 
					and location_code = @location_code

		select @renewal_storage_gb = storage_gb,
				@renewal_product_type_id = p.product_type_id 
		from product p
		left join product_storage s
			on s.product_id = p.product_id 
		where p.product_id = @renewal_upgrade_product_id
	
--select renewal_storage_gb = @renewal_storage_gb, current_storage_gb = @current_storage_gb, renewal_product_type_id = @renewal_product_type_id

		if @current_storage_gb = 1 and @renewal_storage_gb = 2 and @renewal_product_type_id in (2)
			begin
				select @storage_upgrade_dr_product_id = dr_product_id
				from dr_product_price pp 
				inner join product_storage p
					on pp.product_id = p.product_id
				where start_months = @start_months 
						and end_months = @end_months
						and current_storage_gb = 2
						and storage_gb = @storage_gb
						and language_code = @language_code 
						and location_code = @location_code
			end

--select storage_upgrade_dr_product_id = @storage_upgrade_dr_product_id
--select renewal_product_type_id = @renewal_product_type_id

		-- 1.2) get DR product_ids for renewal/upgrade and additional year of backup
		if @renewal_product_type_id = 1
			begin
				select @renewal_upgrade_dr_product_id = dr_product_id
				from dr_product_price
				where product_id = @renewa
l_upgrade_product_id 
							and language_code = @language_code 
							and location_code = @location_code
			end
		else
			begin
				select @renewal_upgrade_dr_product_id = dr_product_id
				from dr_product_price
				where product_id = @renewal_upgrade_product_id 
							and language_code = @language_code 
							and location_code = @location_code and 
						dr_product_id in (select dr_product_id from dr_bundle_product)
			end

		if @renewal_upgrade_dr_product_id is null and @renewal_upgrade_product_id is not null
			begin
				select @response_code = -110,
						@message = '@renewal_upgrade_product_id (' + convert(varchar(20),@renewal_upgrade_product_id) + ',' + @language_code + ',' + @location_code +') is not valid'
				RAISERROR (@message, 11, 0)
			end

		-- 1.3) get DR product_ids for renewal/upgrade and additional year of backup

		select @addition_year_dr_product_id = dr_product_id
		from dr_product_price
		where product_id = @addition_year_product_id
					and language_code = @language_code 
					and location_code = @location_code and 
				dr_product_id in (select dr_product_id from dr_bundle_product)

		if @addition_year_dr_product_id is null and @addition_year_product_id is not null
			begin
				select @response_code = -120,
						@message = '@addition_year_dr_product_id (' + convert(varchar(20),@addition_year_dr_product_id) + ',' + @language_code + ',' + @location_code +') is not valid'
				RAISERROR (@message, 11, 0)
			end

		-- 1.4) determine the number of product_ids in the bundle
		select @bundle_type = count(distinct dr_product_id) 
		from dr_product_price 
		where (dr_product_id = @storage_upgrade_dr_product_id or
				dr_product_id = @renewal_upgrade_dr_product_id or
				dr_product_id = @addition_year_dr_product_id) and 
				language_code = @language_code and 
				location_code = @location_code 
		
--		select storage_upgrade_dr_product_id = @storage_upgrade_dr_product_id,  
--			renewal_upgrade_dr_product_id = @renewal_upgrade_dr_product_id, 
--			addition_year_dr_product_id = @addition_year_dr_product_id,
--			bundle_type = @bundle_type,
--			language_code = @language_code,
--			location_code = @location_code	


			-- 1.4.1) find bundle if all three products are submitted
			if @bundle_type = 3
				begin
--					print '@bundle_type = 3'
					select @dr_bundle_id = (select dr_bundle_id
									from dr_bundle_product
									where dr_product_id = @storage_upgrade_dr_product_id
									intersect
									select dr_bundle_id
									from dr_bundle_product
									where dr_product_id = @renewal_upgrade_dr_product_id
									intersect
									select dr_bundle_id
									from dr_bundle_product
									where dr_product_id = @addition_year_dr_product_id)
	
					select @offer_id = offer_id,
							@parent_product_id = parent_product_id
					from dr_bundle
					where dr_bundle_id = @dr_bundle_id

				end
	
			-- 1.4.2) find bundle if two products are submitted
			if @bundle_type = 2
				begin
--				print '@bundle_type = 2'
				
				-- 1.4.2.1 storage update plus additional product
				if @storage_upgrade_dr_product_id is not null
					begin 
					--select @storage_upgrade_dr_product_id
					if @renewal_upgrade_dr_product_id is not null
						begin
							select @2nd_product_id = @renewal_upgrade_product_id
						end
					else 
						begin
							select @2nd_product_id = @addition_year_product_id
						end
					
					select @dr_bundle_id = (select b1.dr_bundle_id
											from dr_bundle_product b1
											where dr_product_id = @storage_upgrade_dr_product_id and
																		(select count(*) from dr_bundle_product where dr_bundle_id = b1.dr_bundle_id) = 2
											intersect
											select b2.dr_bundle_id
											from dr_product_price p
											inner join dr_bundle_product b2
												on p.dr_product_id = b2.dr_product_id
											where product_id = @2nd_product_id
														and lan
guage_code = @language_code 
														and location_code = @location_code  and
																		(select count(*) from dr_bundle_product where dr_bundle_id = b2.dr_bundle_id) = 2)
					end
				-- 1.4.2.1 renewal plus additionl year backup
				else 
					begin
					select @dr_bundle_id = (select b1.dr_bundle_id
											from dr_product_price p
											inner join dr_bundle_product b1
												on p.dr_product_id = b1.dr_product_id
											where product_id = @renewal_upgrade_product_id 
														and language_code = @language_code 
														and location_code = @location_code  and
																		(select count(*) from dr_bundle_product where dr_bundle_id = b1.dr_bundle_id) = 2
											intersect
											select b2.dr_bundle_id
											from dr_product_price p
											inner join dr_bundle_product b2
												on p.dr_product_id = b2.dr_product_id
											where product_id = @addition_year_product_id
														and language_code = @language_code 
														and location_code = @location_code  and
																		(select count(*) from dr_bundle_product where dr_bundle_id = b2.dr_bundle_id) = 2)
					end

					select @offer_id = offer_id,
							@parent_product_id = parent_product_id
					from dr_bundle
					where dr_bundle_id = @dr_bundle_id
			end
		
		
		
		-- 1.4.3) find bundle if on products are submitted
			if @bundle_type = 1
				begin
--				print '@bundle_type = 1'
				select @dr_product_id = (select dr_product_id
										from dr_product_price 
										where (dr_product_id = @storage_upgrade_dr_product_id or
											dr_product_id = @renewal_upgrade_dr_product_id or
											dr_product_id = @addition_year_dr_product_id) 
												and language_code = @language_code 
												and location_code = @location_code)
				end		

		-- 2.1 return dr_bundle_id

		if @offer_id is null and @parent_product_id is null and @dr_product_id is null
			begin
				select @response_code = -120,
						@message = convert(varchar(20),isnull(@storage_upgrade_dr_product_id,'')) + ',' + convert(varchar(20),isnull(@addition_year_product_id,'')) + ',' + convert(varchar(20),isnull(@renewal_upgrade_product_id,'')) + ',' + @language_code + ',' + @location_code + ' do not have a matching offer'
				RAISERROR (@message, 11, 0)
			end

		select offer_id = @offer_id,
				parent_product_id = @parent_product_id,
				dr_product_id = @dr_product_id

end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_CSI_products_INT]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_product_select_CSI_products_INT]
(
	@language_code varchar(2),
	@location_code varchar(3),
	@product_type_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-30		esmart		Initial creation
	2010-09-09		esmart		Add new WW and PS product family

	DESCRIPTION
	select new products and pricing for international CSI
*/

AS
set nocount on

begin try

		declare @product_type_id_list varchar(10)
		
	-- 1.0) set product type
		if @product_type_id = 1
			begin select @product_type_id_list = '1' end
		if @product_type_id = 2
			begin select @product_type_id_list = '2,3' end

	-- 2.0) create table variable
	declare @products table (product_id int,
								description varchar(150),
								currency varchar(10),
								retail_price money,
								product_family_description varchar(50),
								product_family_id int,
								product_type_id int,
								dr_product_id int,
								current_license_category_id tinyint, 
								license_category_id tinyint, 
								seats int, 
								years tinyint)

	-- 2.1) get SS suite products
		insert into @products(product_id, description, currency, retail_price, product_family_description, product_family_id, product_type_id, dr_product_id, current_license_category_id, license_category_id, seats, years)
		select p.product_id, 
			description = case 
							when p.product_type_id = 3 then pp.dr_product_name 
							else p.product_description
						end, 
			pp.currency,
			retail_price = case
								when pp.currency = 'yen' then convert(money,round((pp.retail_price * 1.05),0))
								else pp.retail_price
							end, 
			pf.product_family_description, 
			pf.product_family_id,
			p.product_type_id,   
			pp.dr_product_id,c.current_license_category_id,c.license_category_id, s.seats, y.years
		from product p
		inner join product_family pf
			on p.product_family_id = pf.product_family_id
		inner join dr_product_price pp
			on p.product_id = pp.product_id and language_code = @language_code and location_code = @location_code
		left join product_years y
			on p.product_id = y.product_id
		left join product_seat s
			on p.product_id = s.product_id
		left join product_license_category c
			on p.product_id = c.product_id
		where p.product_family_id in (2,32,30)        
			and p.product_lifecycle_id = 1        
			and p.product_type_id in (select integer_value from dbo.fn_integer_string_to_table(@product_type_id_list))  
			and p.retail_price > 0        
			and p.product_id not in (64150, 64250)


	-- 2.2) get non SS suite products
		insert into @products(product_id, description, currency, retail_price, product_family_description, product_family_id, product_type_id, dr_product_id)
		select p.product_id, 
			description = case 
							when p.product_type_id = 3 then pp.dr_product_name 
							else p.product_description
						end, 
			pp.currency,
			retail_price = case
								when pp.currency = 'yen' then convert(money,round((pp.retail_price * 1.05),0))
								else pp.retail_price
							end, 
			pf.product_family_description, 
			pf.product_family_id,
			p.product_type_id,   
			pp.dr_product_id
		from product p
		inner join product_family pf
			on p.product_family_id = pf.product_family_id
		inner join dr_product_price pp
			on p.product_id = pp.product_id and language_code = @language_code and location_code = @location_code
		where p.product_family_id in (10,12,14,15,16,20,28)        
			and p.product_lifecycle_id = 1        
			and p.product_type_id in (select integer_value from dbo.fn_integer_string_to_table(@product_type_id_list))  
			and p.retail_price > 0        
			and p.product_id not in (64150, 64250)

	-- 3.0) return results
		select product_id, description, currency, retail_price, product_family_desc
ription, product_family_id, product_type_id, dr_product_id
		from @products
		order by product_type_id, current_license_category_id, license_category_id, seats, years, product_id, retail_price, description     

end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_license_category_by_product_line]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_product_select_license_category_by_product_line]

(
	@product_lines varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2024-09-23	jberry		ECOM-5762 - Created an app-config to exclude license categories from the CSI bulk keycode generator screen

	DESCRIPTION
	select 

	DEPENDENCIES
	Called from CSI Bulk Keycode Generator screen
*/

AS
set nocount on				

declare	@response_code int,
		@message varchar(100)

begin TRY
    
	DECLARE @APP_CONFIG TABLE
	(
		app_config_name NVARCHAR(50),
		[key] NVARCHAR(50),
		[value] NVARCHAR(MAX)
	);
	INSERT INTO @APP_CONFIG
	(
		app_config_name,
		[key],
		value
	)
	SELECT f.app_config_name,
			f.[key],
			f.[value]
		FROM [dbo].[fn_app_config_select_key_values]('BULK_LOAD_LICENSE_CATEGORY_EXCLUDE', 'GENERAL') f;

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select license categories
	SELECT DISTINCT
		   c.license_category_id,
		   c.license_category_name,
		   c.license_category_description,
		   c.base_capability_id
	FROM dbo.license_category_product_line lp
		INNER JOIN dbo.license_category c
			ON lp.license_category_id = c.license_category_id
		LEFT JOIN @APP_CONFIG a
			ON a.[key] = c.license_category_id
	WHERE lp.product_line_id IN
		  (
			  SELECT integer_value FROM dbo.fn_integer_string_to_table(@product_lines)
		  )
		  AND a.value IS NULL
	ORDER BY c.license_category_id;
	
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;

GO
