CREATE PROCEDURE [dbo].[usp_product_select_license_category_upgrade]

(
		@license_category_name varchar(10),	
		@language_code varchar(2) = null,
		@location_code varchar(3) = null,
		@locale char(5) = null,
		@item_hierarchy_id tinyint = null
)

/*	
	DATE		AUTHOR		REMARKS
	2011-05-26	esmart		Initial creation.
	2018-04-25	esmart		Extend for item_hierarchy_id

	DESCRIPTION
	select product_license_category_upgrade
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @language_code and @location_code
	select @language_code = language_code, @location_code = location_code
	from dbo.fn_locale_to_lang_loc(@locale)

	if @language_code is null
		begin set @language_code = 'EN' end
	if @location_code is null
		begin set @location_code = 'USA' end

	-- 1.2) @item_hierarchy_id
	if @item_hierarchy_id is null
		begin
		select @item_hierarchy_id = 1
		end

	-- 1.2) select @license_category_id
		select c.license_category_id, 
				c.license_category_name, 
				upgrade_license_category_id = c2.license_category_id, 
				upgrade_license_category_name = c2.license_category_name, 
				h.item_hierarchy_id, 
				h.item_hierarchy_name
		from license_category c
		inner join product_license_category_upgrade u
			on c.license_category_id = u.license_category_id
		inner join license_category c2
			on u.upgrade_license_category_id = c2.license_category_id
		inner join item_hierarchy h
			on h.item_hierarchy_id = u.item_hierarchy_id
		where c.license_category_name = @license_category_name and
			  u.language_code = @language_code and
			  u.location_code = @location_code and 
			  u.item_hierarchy_id = @item_hierarchy_id
		order by c2.license_category_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
