-- =============================================================================
CREATE PROCEDURE [dbo].[usp_product_select_license_distribution_method_code]

(
	@license_keycode_type_id int,
	@license_category_id tinyint,
	@trial bit = 0,
	@partner_id int = null,
	@license_distribution_method_id int = null,
	@license_distribution_method_code varchar(4) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2019-10-29	cnovac		Initial creation.
	2020-01-13	cnovac		Added logic if @partner_id is passed in
	2024-01-22	pachanta	ECOM-2638 - Ecom to support 2 distribution method codes.
	2024-03-01	pachanta	ECOM-2638 - Adding validation to the invalid distribution method code.

	DESCRIPTION
	select product license_distribution_method_code
*/

AS
	set nocount on				

	declare	@product_line_id int,
			-- @license_distribution_method_id int,
			@response_code int,
			@message varchar(100)

	begin try

		select @product_line_id = product_line_id
		from license_category_product_line
		where license_category_id = @license_category_id

		if @partner_id is not null and @license_distribution_method_id is not null
		begin
			select @license_distribution_method_id = license_distribution_method_id
			from partner_license_distribution_method
			where partner_id = @partner_id and license_distribution_method_id = @license_distribution_method_id
		end
		else if @partner_id is not null and @license_distribution_method_code is not null
		begin
			select @license_distribution_method_id = ldm.license_distribution_method_id
			from partner_license_distribution_method as pldm
			join license_distribution_method as ldm
			on ldm.license_distribution_method_id = pldm.license_distribution_method_id
			where pldm.partner_id = @partner_id and ldm.license_distribution_method_code = @license_distribution_method_code
			if @license_distribution_method_id is null
			begin
				set @response_code = -201
				set @message = 'invalid license distribution method.'
				return
			end
		end

		if @partner_id is not null and @license_distribution_method_id is null
		begin
			select TOP 1 @license_distribution_method_id = license_distribution_method_id
			from partner_license_distribution_method
			where partner_id = @partner_id order by partner_license_distribution_method_id desc
		end

		if @license_distribution_method_id is null
		begin
			exec usp_product_select_license_distribution_method @product_line_id = @product_line_id, @license_keycode_type_id = @license_keycode_type_id, @trial = @trial, @license_category_id = @license_category_id, @license_distribution_method_id = @license_distribution_method_id output
		end

		select license_distribution_method_code
		from license_distribution_method
		where license_distribution_method_id = @license_distribution_method_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_product_select_license_distribution_method_code'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
