-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_products_by_license_category]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_product_select_products_by_license_category]

(
	@license_category_id int,
	@product_type_id int = null,
	@product_line_id int = null,
	@license_keycode_type_id int = NULL,
    @years FLOAT = NULL,
	@capability_type_id INT = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-15	esmart		Initial creation.
	2019-07-23	wbarton		Adding optional parameters for years and capability_type_id so we can selectively return certain WiFi products within the CSI bulk-load tool.

	DESCRIPTION
	select 
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	--if @license_keycode_type_id is null 
	--	begin
	--	select @license_keycode_type_id = 1
	--	end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select p.product_id, p.product_description, p.product_family_id, p.retail_price, s.seats, c.license_category_id, pl.product_line_id, y.years, pc.capability_activation_days, p.license_keycode_type_id
	from product p
	inner join product_seat s
		on p.product_id = s.product_id
	inner join product_years y
		on p.product_id = y.product_id
	inner join product_line_product pl
		on p.product_id = pl.product_id
	left join product_license_category c
		on p.product_id = c.product_id 
	left join license_category lc
		on c.license_category_id = lc.license_category_id
	left join product_capability pc
		on lc.base_capability_id = pc.capability_id and p.product_id = pc.product_id
	where p.product_lifecycle_id = 1
		and	c.license_category_id = @license_category_id
		and p.product_type_id = case when @product_type_id is null then p.product_type_id else @product_type_id end 
		and pl.product_line_id = case when @product_line_id is null then pl.product_line_id else @product_line_id end
		and p.license_keycode_type_id = case when @license_keycode_type_id is null then p.license_keycode_type_id else @license_keycode_type_id END
		AND pc.capability_type_id = CASE WHEN @capability_type_id IS NULL THEN pc.capability_type_id ELSE @capability_type_id END 
        AND y.years = CASE WHEN @years IS NULL THEN y.years ELSE @years END 
	order by s.seats, y.years
	

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_sfdc_license_category]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_product_select_sfdc_license_category]

(
	@Product2ID varchar(18)
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2019-04-17		acoffel		Initial creation.
	2019-11-13		esmart		Add seats
	2020-07-01		esnart		Add retention_model_id
		

	DESCRIPTION
	select category from Product2ID
	
*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  select license_category
 	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		--1.1) license_category
		select sfdc_product_category_mapping_id, Product2Id, ProductCode, license_category_name, license_category_id, seats, usage_pricing_model_id, retention_model_id, insert_date, insert_by
		from sfdc_product_category_mapping
		where Product2Id = @Product2ID

	     

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_storage_upgrade_options]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_product_select_storage_upgrade_options]
(
	@keycode varchar(40),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-25		esmart		Initial creation

	DESCRIPTION
	select available storage upgrade products for a given keycode. Calculate the price for the remaining months on a subscription
*/

AS
set nocount on

begin try

	declare @log_type int,
			@license_id int,
			@license_status_id int,
			@product_line_id int,
			@storage_gb int,
			@current_storage_gb int,
			@months_remaining int,
			@capability_expiration_date datetime,
			@capability_activation_days int,
			@transaction_date datetime,
			@license_activated int

	set @log_type = 1
	set @transaction_date = getdate()	
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get license information
		select @license_id = l.license_id,
				@product_line_id = l.product_line_id,
				@current_storage_gb = isnull(s.storage_gb,1),
				@license_status_id = l.license_status_id
		from license l with (nolock)
		left join license_storage s with (nolock)
			on l.license_id = s.license_id
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -100,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

		if @current_storage_gb = 0
			begin
			select @current_storage_gb = 1
			end

		-- 1.2) get license_capability days
		select @capability_activation_days = capability_activation_days
		from license_capability with (nolock)
		where license_id = @license_id and capability_id = 1

				
		-- 1.3) get remaining months on license
		if @license_status_id = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,@capability_activation_days,@transaction_date),
						@license_activated = case when capability_expiration_date is null then 0 else 1 end
				from license_capability with (nolock)
				where license_id = @license_id and capability_id = 1
			end
		else
			begin
				select @capability_expiration_date = capability_expiration_date,
						@license_activated = case when capability_expiration_date is null then 0 else 1 end
				from license_capability with (nolock)
				where license_id = @license_id  and capability_id = 1
			end

		if @license_status_id = 1 and @license_activated = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,@capability_activation_days,@transaction_date)
				from license_capability with (nolock)
				where license_id = @license_id and capability_id = 1
			end

			select @months_remaining = 0

--select capability_expiration_date = @capability_expiration_date, license_status_id = @license_status_id, license_activated = @license_activated, capability_activation_days = @capability_activation_days

		if @capability_expiration_date >= @transaction_date
			begin

				while dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
					begin
					select @months_remaining = @months_remaining + 1
					end

				select @months_remaining = 
						case
							when @months_remaining <= 1 and @capability_expiration_date is not null
 then 1
							when @months_remaining <= 1 and @capability_expiration_date is null then 0
							else @months_remaining - 1
						end
			end

		-- 1.4) check for best buy monthly subscribers and set months remaining = 12
		declare @best_buy_monthly int

		select @best_buy_monthly = 
					case
						when count(*) > 0 then 1
						else 0
					end
		from subscription with (nolock)
		where license_id = @license_id and subscription_type_id <> 2
		
		if @best_buy_monthly = 1
			begin
				select @months_remaining = 12
			end

--select capability_expiration_date = @capability_expiration_date, months_remaining = @months_remaining, current_storage_gb = @current_storage_gb
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return products and pricing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select p.product_id, 
				p.product_description,
				ps.storage_gb,
				upgrade_price = round(convert(money,@months_remaining * (p.retail_price/12)),2),
				p.retail_price
		from product p
		inner join product_line_product pl
			on p.product_id = pl.product_id
		inner join product_storage  ps
			on p.product_id = ps.product_id
		where pl.product_line_id = @product_line_id and
				current_storage_gb = @current_storage_gb and
				p.retail_price > 0

end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_storage_upgrade_options_INT]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_product_select_storage_upgrade_options_INT]
(
	@keycode varchar(40),
	@language_code varchar(2),
	@location_code varchar(3),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-09-25		esmart		Initial creation

	DESCRIPTION
	select available storage upgrade products for a given keycode. Calculate the price for the remaining months on a subscription
*/

AS
set nocount on

begin try

	declare @log_type int,
			@license_id int,
			@license_status_id int,
			@storage_gb int,
			@current_storage_gb int,
			@months_remaining int,
			@months_remaining_remainder int,
			@capability_expiration_date datetime,
			@capability_activation_days int,
			@transaction_date datetime,
			@license_activated int

	set @log_type = 1
	set @transaction_date = getdate()	
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get license information
		select @license_id = l.license_id,
				@current_storage_gb = isnull(s.storage_gb,1),
				@license_status_id = l.license_status_id
		from license l with (nolock)
		left join license_storage s with (nolock)
			on l.license_id = s.license_id
		where keycode = @keycode

		if @license_id is null 	
			begin
				select @response_code = -100,
						@message = '@keycode ' + @keycode + ' is not valid'
				RAISERROR (@message, 11, 0)
			end

		if @current_storage_gb = 0
			begin
			select @current_storage_gb = 1
			end

		-- 1.2) get license_capability days
		--			NOTE: Need to calculate this for edge case of refunded purchase prior to activation
		select @capability_activation_days = capability_activation_days
		from license_capability with (nolock)
		where license_id = @license_id and capability_id = 1

--select license_status_id = @license_status_id
				
		-- 1.3) get remaining months on license
		if @license_status_id = 0 and @capability_activation_days > 0
			begin
				select @capability_expiration_date = dateadd(dd,@capability_activation_days,@transaction_date),
						@license_activated = case when capability_expiration_date is null then 0 else 1 end
				from license_capability with (nolock)
				where license_id = @license_id and capability_id = 1
			end
		else
			begin
				select @capability_expiration_date = capability_expiration_date,
						@license_activated = case when capability_expiration_date is null then 0 else 1 end
				from license_capability with (nolock)
				where license_id = @license_id  and capability_id = 1
			end

--select license_activated = @license_activated
		
		-- 1.3.1) if not expired calculate months remaining
			select @months_remaining = 0

			if @capability_expiration_date >= @transaction_date
				begin

					while dateadd(mm,@months_remaining,@transaction_date) <= @capability_expiration_date
						begin
						select @months_remaining = @months_remaining + 1
						end
				select @months_remaining = 
						case
							when @months_remaining <= 1 and @capability_expiration_date is not null then 1
							when @months_remaining <= 1 and @capability_expiration_date is null then 0
							when @months_remaining >= 13 and @license_activated = 1 then @months_remaining
							else @months_remaining - 1
						end
			end

				select @months_remaining_remainder = @months_remaining % 12
		
			-- 1.3.2) if months remaining > 12 then return the prorated portion of the total months remaining. 
				if @months_remaining > 12 and @months_remaining_remainder = 0
					begin
						select @months_remaining = 12
					end
				if @months_remaining > 12 and @months_remaining_remainder > 0
					begin
						select @months_remaining = @months_remaining % 12
					end

--select months_remaining = @months_remaining, months_remaining_remainder = @months_remaining_remainder	
--select capability_expiration_date = @capability_expiration_date, months_remaining = @months_remaining, current_storage_gb = @current_storage_gb, product_line_id = @product_line_id
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return products and pricing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select	pp.product_id,
				pp.dr_product_id,
				product_description = pp.dr_product_name, 
				ps.storage_gb,	
				upgrade_price = --pp.retail_price
						case 
							when @months_remaining = 0 then 0
							else pp.retail_price
						end
				,
				pp.retail_price
		from dr_product_price pp
		inner join product_storage  ps
			on pp.product_id = ps.product_id
		where pp.language_code = @language_code 
			and pp.location_code = @location_code
			and pp.start_months is not null 
			and ps.current_storage_gb = @current_storage_gb 
			and ((pp.start_months >= @months_remaining and @months_remaining > pp.end_months) or (@months_remaining = 0 and pp.start_months = 12))	
		order by pp.product_id
		
end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_select_volume_price]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_product_select_volume_price]

(
	@product_id int,
	@quantity int,
	@response_code int output,
	@message varchar(100) output
)

AS

/*	
	DATE		AUTHOR	REMARKS
	2006-12-12	esmart		Initial creation
	2009-09-30  dsmelker	changed @discount_percent to decimal(9,7)

	DESCRIPTION
	update license_capability
*/


	declare @retail_price money,
		@product_family_id int,
		@discount_id int,
		@discount_percent decimal(9, 7)

	set @response_code = 0
	set @message = ''

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) @quantity 
	if @quantity is null or @quantity = 0
		begin
		set @response_code = -100
		set @message = '@quantity must be greater than 0'
		return
		end

	-- 1.1) @product_family_id and  @retail_price
	select @product_family_id = product_family_id,
		@retail_price = retail_price
	from product 
	where product_id = @product_id

	if @product_family_id is null or (@retail_price is null or @retail_price = 0)
		begin
		set @response_code = -110
		set @message = 'Product family or retail price not valid'
		return
		end

	-- 1.2) @discount_id
	select @discount_id = discount_id
	from product_family_discount
	where product_family_id = @product_family_id

	if @discount_id is null 
		begin
		set @response_code = -120
		set @message = 'No discount for product family'
		return
		end


	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) Calculate discounted price 
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) get @discount_percent
	
	select @discount_percent = discount_percent
	from discount_range 
	where discount_id = @discount_id and
		low_quantity <= @quantity and @quantity <= high_quantity

	if @discount_percent is null
		begin
		set @response_code = -210
		set @message = 'No discount percentage for discount_id and quantity'
		return
		end
	
	--select @retail_price * (1 - @discount_percent)
	--select convert(money,(@retail_price * (1 - @discount_percent)))
	select price = @quantity * convert(money,(@retail_price * (1 - @discount_percent)))
	--select price = (@quantity * @retail_price) * (1 - @discount_percent)
	--select price = convert(money,@quantity*(@retail_price * (1 - @discount_percent)))

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_update_international_cart_discount]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_product_update_international_cart_discount]

(
	@cart_discount_method_id tinyint,
	@language_code varchar(2), 
	@location_code varchar(3),
	@modified_by varchar(20) = null,
	@cart_discount_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-10-05	esmart		Initial creation
	2012-11-30	esmart		Add cart_discount_id option

	DESCRIPTION
	Update internation cart_discounts
*/

AS
	set nocount on				
			
	declare @response_code int,
			@message varchar(100),
			@currency_id tinyint,
			@currency varchar(50),
			@exchange_rate float, 
			@exchange_multiplier float,
			@modified_date datetime
			
	begin try
	
	if @modified_by is null or @modified_by = ''
		begin
		select @modified_by = suser_name()
		end
		
	select @modified_date = getdate()
	
	--------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	--------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @currency_id = c.currency_id,
			@currency = c.currency_description,
			@exchange_rate = c.exchange_rate,
			@exchange_multiplier = c.exchange_multiplier
	from currency_language_location cl
	inner join currency c
		on cl.currency_id = c.currency_id
	where cl.language_code = @language_code and cl.location_code = @location_code
	
	--select currency_id = @currency_id, exchange_rate = @exchange_rate, exchange_multiplier = @exchange_multiplier
	
	--------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	--------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) Setup discount table
	declare @discounts table (cart_discount_item_id int, cart_discount_description varchar(50), discount float, current_discount float, calculated_discount float)

	insert into @discounts(cart_discount_item_id,cart_discount_description,discount,current_discount)
	select d.cart_discount_item_id, c.cart_discount_description, i.discount, d.discount
	from cart_discount_item i
	inner join cart_discount c
		on i.cart_discount_id = c.cart_discount_id
	inner join cart_discount_item_discount d
		on i.cart_discount_item_id = d.cart_discount_item_id
	where cart_discount_method_id = @cart_discount_method_id and d.language_code = @language_code and d.location_code = @location_code and i.discount > 0 and
		i.cart_discount_id = case
								when @cart_discount_id is not null then @cart_discount_id
								else i.cart_discount_id
							end
	

	insert into @discounts(cart_discount_item_id,cart_discount_description,discount,current_discount)
	select i.cart_discount_item_id, c.cart_discount_description, i.discount, d.discount
	from cart_discount_item i
	inner join cart_discount c
		on i.cart_discount_id = c.cart_discount_id
	left join cart_discount_item_discount d
		on i.cart_discount_item_id = d.cart_discount_item_id and d.language_code = @language_code and d.location_code = @location_code
	where cart_discount_method_id = @cart_discount_method_id and d.cart_discount_item_discount_id is null and i.discount > 0
			
	-- 2.2) 
	update @discounts
	set calculated_discount = case 
						when @exchange_rate <= 1 then round(dbo.fn_round_pricing(discount*@exchange_rate*@exchange_multiplier,2.5),1) 
						when @exchange_rate > 1 and @exchange_rate <= 2 then round(dbo.fn_round_pricing(discount*@exchange_rate*@exchange_multiplier,5.0),0) 
						when @exchange_rate > 2 and @exchange_rate <= 100 then round(discount*@exchange_rate*@exchange_multiplier,-1) 
						when @exchange_rate > 100 a
nd @exchange_rate <= 1000 then round(discount*@exchange_rate*@exchange_multiplier,-1) 
						when @exchange_rate > 1000 then round(discount*@exchange_rate*@exchange_multiplier,-3) 
					end
	from @discounts
	
	--select * from @discounts order by discount	
	
	-- 2.2) archive data
	insert into cart_discount_item_discount_history(cart_discount_item_discount_id, cart_discount_item_id, discount, language_code, location_code, currency, currency_id)
	select cart_discount_item_discount_id, cart_discount_item_id, discount, language_code, location_code, currency, currency_id
	from cart_discount_item_discount
	where cart_discount_item_id in (select cart_discount_item_id from @discounts) and language_code = @language_code and location_code = @location_code
	
	-- 2.3) update pricing
	delete from cart_discount_item_discount
	where cart_discount_item_id in (select cart_discount_item_id from @discounts) and language_code = @language_code and location_code = @location_code
	
	insert into cart_discount_item_discount(cart_discount_item_id, discount, language_code, location_code, currency, currency_id)
	select cart_discount_item_id, calculated_discount, @language_code, @location_code, @currency, @currency_id
	from @discounts
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_product_update_international_product_pricing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_product_update_international_product_pricing]

(
	@product_line_id int,
	@language_code varchar(2), 
	@location_code varchar(3),
	@modified_by varchar(20) = null,
	@product_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2012-09-01	esmart		Initial creation
	2012-09-19	esmart		Add product_id override

	DESCRIPTION
	Update internation product_pricing
*/

AS
	set nocount on				
			
	declare @response_code int,
			@message varchar(100),
			@currency_id tinyint,
			@exchange_rate float, 
			@exchange_multiplier float,
			@modified_date datetime
			
	begin try
	
	if @modified_by is null or @modified_by = ''
		begin
		select @modified_by = suser_name()
		end
		
	select @modified_date = getdate()
	
	--------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	--------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @currency_id = c.currency_id,
			@exchange_rate = c.exchange_rate,
			@exchange_multiplier = c.exchange_multiplier
	from currency_language_location cl
	inner join currency c
		on cl.currency_id = c.currency_id
	where cl.language_code = @language_code and cl.location_code = @location_code
	
	--select currency_id = @currency_id, exchange_rate = @exchange_rate, exchange_multiplier = @exchange_multiplier
	
	--------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	--------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) set up new product table
	declare @products table (product_id int, product_description varchar(200), product_type_id int, retail_price money, calculated_retail_price money)
	
	if @product_id is null
		begin
			insert into @products(product_id,product_description,product_type_id,retail_price)
			select p.product_id, p.product_description, p.product_type_id, p.retail_price
			from product p
			inner join product_line_product pl
				on p.product_id = pl.product_id
			where pl.product_line_id = @product_line_id and p.product_lifecycle_id = 1 and p.product_description not like '%trial%' 
		end
	else
		begin
			insert into @products(product_id,product_description,product_type_id,retail_price)
			select p.product_id, p.product_description, p.product_type_id, p.retail_price
			from product p
			where p.product_id = @product_id
		end
	
	update @products
	set calculated_retail_price = case 
						when @exchange_rate <= 1 and (product_description like '%storage%' or product_type_id = 3) and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= -2.5 then round(retail_price*@exchange_rate*@exchange_multiplier,-1)-5
						when @exchange_rate <= 1 and (product_description like '%storage%' or product_type_id = 3) and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > - 2.5 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= 0  then round(retail_price*@exchange_rate*@exchange_multiplier,-1)
						when @exchange_rate <= 1 and (product_description like '%storage%' or product_type_id = 3) and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > 0 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= 2.5  then round(retail_price*@exchange_rate*@exchange_multiplier,
-1) 
						when @exchange_rate <= 1 and (product_description like '%storage%' or product_type_id = 3) and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > 2.5 then round(retail_price*@exchange_rate*@exchange_multiplier,-1)+5
						when @exchange_rate <= 1 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= -2.5 then round(retail_price*@exchange_rate*@exchange_multiplier,-1)-.01-5
						when @exchange_rate <= 1 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > - 2.5 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= 0  then round(retail_price*@exchange_rate*@exchange_multiplier,-1)-.01 
						when @exchange_rate <= 1 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > 0 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) <= 2.5  then round(retail_price*@exchange_rate*@exchange_multiplier,-1)-.01 
						when @exchange_rate <= 1 and (retail_price*@exchange_rate*@exchange_multiplier - round(retail_price*@exchange_rate*@exchange_multiplier,-1)) > 2.5 then round(retail_price*@exchange_rate*@exchange_multiplier,-1)-.01+5 
						when @exchange_rate > 1 and @exchange_rate <= 2 and (product_description like '%storage%' or product_type_id = 3) then round(p.retail_price*@exchange_rate*@exchange_multiplier,-1)
						when @exchange_rate > 1 and @exchange_rate <= 2 then round(p.retail_price*@exchange_rate*@exchange_multiplier,-1)-.01  
						when @exchange_rate > 2 and @exchange_rate <= 100 then round(retail_price*@exchange_rate*@exchange_multiplier,-1) 
						when @exchange_rate > 100 and @exchange_rate <= 1000 then round(retail_price*@exchange_rate*@exchange_multiplier,-2) 
						when @exchange_rate > 1000 then round(retail_price*@exchange_rate*@exchange_multiplier,-4) 
					end  
	from @products p
	
	-- 2.2) archive data
	insert into product_pricing_history(product_pricing_id, product_id, language_code, location_code, currency_id, retail_price, last_modified_date, last_modified_by, history_date, history_by)
	select product_pricing_id, product_id, language_code, location_code, currency_id, retail_price, last_modified_date, last_modified_by, @modified_date, @modified_by
	from product_pricing
	where product_id in (select product_id from @products) and language_code = @language_code and location_code = @location_code
	
	-- 2.3) update pricing
	delete from product_pricing
	where product_id in (select product_id from @products) and language_code = @language_code and location_code = @location_code
	
	insert into product_pricing(product_id, language_code, location_code, currency_id, retail_price, last_modified_date, last_modified_by)
	select product_id, @language_code, @location_code, @currency_id, calculated_retail_price, @modified_date, @modified_by
	from @products
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_rebate_insert_order_item_rebate]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_rebate_insert_order_item_rebate]

(
	@order_header_id int,
	@product_id int,
	@rebate_value_code varchar(10),	
	@rebate_alternate_type varchar(50) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2009-11-16	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@rebate_id int,
			@rebate_value money,
			@order_item_id int,
			@rebate_tens varchar(10),
			@rebate_ones varchar(10)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		if @rebate_value_code like 'w%'
			begin
				-- 1.1) @rebate_value
				select @rebate_tens = replace((left(@rebate_value_code,patindex('%x%',@rebate_value_code)-1)),'w',''),
						@rebate_ones = right(@rebate_value_code,len(@rebate_value_code)-patindex('%x%',@rebate_value_code))

				select @rebate_ones = case 
										when len(@rebate_ones) = 1 then @rebate_ones+'00'
										when len(@rebate_ones) = 2 then @rebate_ones+'0'
										else @rebate_ones
									end

				select @rebate_value = (convert(money,@rebate_tens)*10)+convert(money,left(@rebate_ones,1)+'.'+ right(@rebate_ones,2))

				if @rebate_value is null	
					begin
						select @response_code = -110, @message = 'Invalid rebate value'
						select response_code = @response_code, [message] = @message
						return
					end 

				-- 1.2) @rebate_id
				select @rebate_id = r.rebate_id
				from product_rebate pr
				left join rebate r
					on r.rebate_id = pr.rebate_id
				where pr.product_id = @product_id and
						r.rebate_value = @rebate_value
			end
		else
			begin
				-- 1.3) select a specific rebate
				select @rebate_id = r.rebate_id
				from rebate r
				inner join product_rebate pr
					on r.rebate_id = pr.rebate_id
				inner join rebate_type t
					on r.rebate_type_id = t.rebate_type_id
				where r.rebate_id = @rebate_value_code
			end

		if @rebate_id is null	
			begin
				select @response_code = -120, @message = 'Invalid rebate code'
				select response_code = @response_code, [message] = @message
				return
			end 

		-- 1.2) @order_item_id
		declare @order_item_ids table (order_item_id int)

		insert into @order_item_ids(order_item_id)
		select order_item_id
		from order_item
		where order_header_id = @order_header_id and product_id = @product_id

		if (select count(*) from @order_item_ids) = 0
			begin
				select @response_code = -130, @message = 'No order_item_id found for order header and product'
				select response_code = @response_code, [message] = @message
				return
			end 
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert order_item_rebate
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		insert into order_item_rebate(order_item_id, license_id, rebate_id, rebate_status_id)
		select i.order_item_id, l.license_id, @rebate_id, 1
		from @order_item_ids i
		left join order_item_license l
			on i.order_item_id = l.order_item_id	
	
	select response_code = 0, [message] = 'Rebate inserted successfully'

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert order_item_rebate failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_rebate_insert_rebate]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_rebate_insert_rebate]

(
	@rebate_id int,
	@rebate_description varchar(100), 
	@rebate_code varchar(20), 
	@rebate_type_id tinyint, 
	@rebate_value money
)

/*	
	DATE		AUTHOR		REMARKS
	2009-11-16	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) @rebate_type_id
		select @response_code =  case when count(*) = 0 then -110 else 0	 end,
			@message = case when count(*) = 0 then '@rebate_type_id(' + convert(varchar(10),@rebate_type_id) + ') not valid' else '' end
		from rebate_type
		where rebate_type_id = @rebate_type_id

		if @response_code < 0 	
			begin
				select response_code = @response_code, [message] = @message
				return
			end 
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		set identity_insert rebate on

		insert into rebate(rebate_id, rebate_description, rebate_code, rebate_type_id, rebate_value)
		values(@rebate_id, @rebate_description, @rebate_code, @rebate_type_id, @rebate_value)

		set identity_insert rebate off

		select response_code = 0, [message] = 'Rebate inserted successfully'

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert rebate failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
