CREATE PROCEDURE [dbo].[usp_rebate_update_order_item_rebate]

(
	@order_item_rebate_id int,
	@rebate_status_id tinyint,
	@rebate_delivery_order_item_id int,
	@rebate_delivery_guid varchar(50) 
)

/*	
	DATE		AUTHOR		REMARKS
	2009-11-16	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@last_modified_date datetime,
			@last_modified_by varchar(20)

	begin try

	select @last_modified_date = getdate(),
			@last_modified_by = suser_sname()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into order_item_rebate_history(order_item_rebate_id, order_item_id, rebate_id, rebate_status_id, rebate_delivery_order_item_id, rebate_delivery_guid, last_modified_date, last_modified_by, history_date, history_by)
	select order_item_rebate_id, order_item_id, rebate_id, rebate_status_id, rebate_delivery_order_item_id, rebate_delivery_guid, last_modified_date, last_modified_by, @last_modified_date, @last_modified_by
	from order_item_rebate 
	where order_item_rebate_id = @order_item_rebate_id
	

	update order_item_rebate
	set rebate_status_id = @rebate_status_id,
		rebate_delivery_order_item_id = @rebate_delivery_order_item_id,
		rebate_delivery_guid = @rebate_delivery_guid,
		last_modified_date = @last_modified_date,
		last_modified_by = @last_modified_by
	where order_item_rebate_id = @order_item_rebate_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select rebate failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_redemption_insert_order_item_redemption]
-- =============================================================================




CREATE PROCEDURE [dbo].[usp_redemption_insert_order_item_redemption]

(
	@order_header_id int,
	@product_id int,
	@redemption_id varchar(10)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-07-12	acoffel		Initial creation.
	2011-11-09	esmart		Add default @redemption_value

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@redemption_code_id int,
			@order_item_id int,
			@license_category_name varchar(6),
			@seats tinyint,
			@license_storage_gb int,
			@redemption_value tinyint
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) find order_item_ids
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @order_item_id
		declare @order_item_ids table (order_item_id int)

		insert into @order_item_ids(order_item_id)
		select top 1 order_item_id
		from order_item
		where order_header_id = @order_header_id and product_id = @product_id

		if (select count(*) from @order_item_ids) = 0
			begin
				select @response_code = -110, @message = 'No order_item_id found for order header and product'
				select response_code = @response_code, [message] = @message
				return
			end		

		select @order_item_id = order_item_id from @order_item_ids

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) set redemption product details
	-- -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) build attribute table
	declare @product_attributes table (cart_item_in_process_ext_type_id int,ext_type_name varchar(20),ext_type_value varchar(20))
	
	insert into @product_attributes(cart_item_in_process_ext_type_id,ext_type_name,ext_type_value)
	exec dbo.usp_cart_select_product_ext_types @product_id

	if (select count(*) from @product_attributes) = 0
			begin
				select @response_code = -210, @message = 'Product details not availible for given product_id'
				select response_code = @response_code, [message] = @message
				return
			end		

	-- 2.2) assign parameters
	select 	@license_category_name = (select ext_type_value from @product_attributes where ext_type_name = 'category')
			,@seats = isnull((select ext_type_value from @product_attributes where ext_type_name = 'seats'),1)
			,@license_storage_gb = (select ext_type_value from @product_attributes where ext_type_name = 'storage')
	
	select @redemption_value = redemption_value
	from redemption_product_details
	where redemption_id = @redemption_id
	and license_category_name = @license_category_name
	and seats = @seats
	
	if @redemption_value is null
		begin
		select @redemption_value = 1
		end 

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) commit redemption code 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	begin transaction
		
		declare @redemption_code_ids table (redemption_code_id int)
	
		insert into @redemption_code_ids(redemption_code_id)
		select top(@redemption_value) redemption_code_id 
		f
rom redemption_code
		where redemption_id = @redemption_id
		and [status] = 0

		update redemption_code
		set [status] = 1
		where redemption_code_id in (select redemption_code_id from @redemption_code_ids)
		
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert order_item_redemption
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		insert into order_item_redemption(order_item_id, redemption_code_id, redemption_id,[status])
		select @order_item_id, redemption_code_id, @redemption_id, 1
		from @redemption_code_ids

	--select * from order_item_redemption

	if @@error <> 0
    begin
      rollback transaction
      set @response_code = -300
      set @message = 'General SQL Error - redemption insert'
      return
    end

	commit transaction		

	--select response_code = 0, [message] = 'Redemption inserted successfully'

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert order_item_redemption failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_redemption_select_redemption_details]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_redemption_select_redemption_details]

(
	@redemption_name varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-07-01	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@redemption_id int,
			@redemptions_left int
			
			

	begin try  

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @redemption_name is not NULL
		begin
		-- 1.1) set @redemption_id
			select @redemption_id = redemption_id
			from redemption 
			where redemption_name = @redemption_name


		-- 1.2) verify proper availability
			select @redemptions_left = count(*) 
			from redemption_code 
			where [status] = 0
			and redemption_id = @redemption_id		
		
			if @redemptions_left < 5	
				begin
					select @response_code = -110, @message = 'out of redemption codes'
					select response_code = @response_code, [message] = @message
					return
				end 

		else 
			begin
				select redemption_id = @redemption_id 
			end 

	end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select redemption failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_refresh_license_activity_from_wh]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_refresh_license_activity_from_wh]
AS
/*

Date            Author       version              Remarks
============================================================

Initial	           surpal       1.0         Refresh license_activity table from warehouse.license_warehouse.license_activity table
1/14/2013          surpal       1.1         sa_* columns added to activity as per original table  
*/

SET NOCOUNT ON

DECLARE @object_name VARCHAR(150)
DECLARE @rename_str NVARCHAR(MAX)

SET @object_name = 'license_activity_refresh_l1a2r3' + REPLACE(CONVERT(VARCHAR,GETDATE(),102), '.', '') + REPLACE(SUBSTRING(CONVERT(VARCHAR,GETDATE(),120),12,5),':', '')

SELECT @rename_str=
'
BEGIN TRY
      IF (OBJECT_ID('''+@object_name+''') IS NOT NULL)
      DROP TABLE '+@object_name+'
      
	 /* CREATE TABLE [dbo].['+@object_name+'](
	  [license_activity_id] [int] IDENTITY(1,1) NOT NULL,
	  [license_id] [int] NULL,
	  [keycode] [varchar](40) NOT NULL,
	  [device_mid] [varchar](40) NOT NULL, 
	  [instance_mid] [varchar](64) NOT NULL,
	  [max_threats_removed] [int] NULL
      ) ON [PRIMARY]


      INSERT INTO ['+@object_name+']([license_id], [keycode], [device_mid], [instance_mid],[max_threats_removed])
      SELECT [license_id], [keycode], [device_mid], [instance_mid],[max_threats_removed] FROM [datawarehouse].[license_warehouse].[dbo].[license_activity]
	  */

	  	  
CREATE TABLE  [dbo].['+@object_name+'](
    [license_activity_id] [int] IDENTITY(1,1) NOT NULL,
	[license_id] [int] NULL,
	[keycode] [varchar](40) NOT NULL,
	[mjv] [smallint] NULL,
	[version] [varchar](10) NULL,
	[grabword] [varchar](30) NULL,
	[rc] [int] NULL,
	[operating_system] [smallint] NULL,
	[platform] [int] NULL,
	[language_code] [varchar](2) NULL,
	[location_code] [varchar](3) NULL,
	[device_mid] [varchar](40) NOT NULL,
	[instance_mid] [varchar](64) NOT NULL,
	[threats_removed] [int] NULL,
	[current_threats] [smallint] NULL,
	[number_scans] [int] NULL,
	[average_scan_time] [int] NULL,
	[number_events] [bigint] NULL,
	[bytes_cleaned] [bigint] NULL,
	[time_protected] [bigint] NULL,
	[first_activity_date] [datetime] NULL,
	[last_activity_date] [datetime] NULL,
	[max_activity_id] [bigint] NULL,
	[total_checks] [int] NULL,
	[max_threats_removed] [int] NULL,
	[max_current_threats] [smallint] NULL,
	[hostname] [varchar](64) NULL,
	[sa_score] tinyint NULL,
	[sa_software_status] char(1) NULL,
	[sa_hardware_status] char(1) NULL,
	[sa_threat_status] char(1) NULL
) ON [PRIMARY]



      INSERT INTO ['+@object_name+']([license_id], [keycode],[mjv], [version],[grabword], [rc],[operating_system], [platform], 
	  [language_code], [location_code] ,[device_mid],[instance_mid],[threats_removed],[current_threats],[number_scans],[average_scan_time],[number_events],[bytes_cleaned],[time_protected],[first_activity_date],[last_activity_date],[max_activity_id],[total_checks],[max_threats_removed],[max_current_threats],[hostname],[sa_score],[sa_software_status],[sa_hardware_status],[sa_threat_status])
      SELECT [license_id], [keycode], [mjv], [version],[grabword], [rc],[operating_system], [platform],
	  [language_code], [location_code] ,[device_mid],[instance_mid],[threats_removed],[current_threats],[number_scans],[average_scan_time],[number_events],[bytes_cleaned],[time_protected],[first_activity_date],[last_activity_date],[max_activity_id],[total_checks],[max_threats_removed],[max_current_threats],[hostname],[sa_score],[sa_software_status],[sa_hardware_status],[sa_threat_status] FROM [datawarehouse].[license_warehouse].[dbo].[license_activity]


      ALTER TABLE [dbo].['+@object_name+']
      ADD CONSTRAINT  [PK_'+@object_name+'_license_activity_id] PRIMARY KEY CLUSTER
ED (license_activity_id);


       CREATE NONCLUSTERED INDEX [IX_'+@object_name+'_license_id_include] ON [dbo].['+@object_name+']
      (

[license_id] ASC

) 

INCLUDE(last_activity_date,max_threats_removed,average_scan_time,number_scans,threats_removed,bytes_cleaned) WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, DROP_EXISTING = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, FILLFACTOR = 90) ON [PRIMARY]


	   CREATE NONCLUSTERED INDEX [IX_'+@object_name+'_keycode] ON [dbo].['+@object_name+']
       (
	    [keycode] 
       )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, DROP_EXISTING = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, FILLFACTOR = 90) ON [PRIMARY]



       IF EXISTS(SELECT name FROM sys.synonyms WHERE name=''license_activity'')
       DROP SYNONYM license_activity

       CREATE SYNONYM license_activity
       FOR dbo.'+@object_name+'

	   PRINT ''License_activity table refreshed from Warehouse.license_warehouse.license_warehouse table Successfully!!!''
  END TRY

  BEGIN CATCH
       DECLARE @dbname VARCHAR(100)
       SET @dbname = DB_NAME()
	   EXEC usp_LogError @ErrorDB = @dbname

	   RAISERROR(''License_activity table refreshed from Warehouse.license_warehouse.license_warehouse table Failed!!!'', 16,1)


  END CATCH

'

--PRINT @rename_str

EXECUTE sp_executesql @rename_str


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_renewal_insert_license_id]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_renewal_insert_license_id]


/*	
	DATE		AUTHOR		REMARKS
	2011-02-01	acoffel		Initial creation.

	DESCRIPTION
	insert renewal licenses
*/

as
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	begin try


		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) truncate table
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		--1.0) truncate table
		--truncate table license_renewals

	
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) insert records 
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		--2.0) most recent renewals not yet loaded
		insert into license_renewals(license_id,order_header_id_1)
		select f.license_id, order_header_id_1 = max(f.order_header_id)
		from datawarehousereadonly.license_warehouse.dbo.license_fact f
		where f.license_change_reason_id = 2
		and f.order_header_id is not NULL 
		and not exists (select * from license_renewals l where f.license_id = l.license_id) 
		group by license_id
		order by license_id

	

	end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_reseller_insert_partner_company]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_reseller_insert_partner_company]
@salesforce_account_id varchar(20),
@vault_datacenter_key varchar(200),
@partnerid varchar(100)
/*

	DATE		AUTHOR		REMARKS
	2022-05-30	psatish		Initial creation.
	2022-06-09  psatish		ALM# 1377 Modified the column name
	DESCRIPTION
	Insert Partnerid for the Reseller company
*/

as


	set nocount on
	begin try
		declare @company_id int,
				@vault_id	int,
				@response_code int,
				@message varchar(100)


		select @company_id=company_id
		from dbo.company
		where salesforce_account_id=@salesforce_account_id

		select @vault_id=vault_id
		from dbo.vault
		where vault_datacenter_key=@vault_datacenter_key

		if not exists(select 1 from reseller_provisioning where vault_id=@vault_id and company_id=@company_id)
		begin
			insert into reseller_provisioning
			(
			company_id,
			vault_id,
			cep_partner_id
			)
			values(@company_id,@vault_id,@partnerid)

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_reseller_select_partner_company]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_reseller_select_partner_company] 
@salesforce_account_id varchar(20),
@vault_datacenter_key varchar(200)
/*

	DATE		AUTHOR		REMARKS
	2022-05-30	psatish		Initial creation.
	2022-06-09  psatish		ALM# 1377 Modified the column name
	DESCRIPTION
	 Select CEP Partnerid for the Reseller company
*/

as
begin

	set nocount on

	declare @response_code int,
			@message varchar(100)

		
	begin try
    
		select	cm.company_id,
				cm.company_name,
				cm.company_type_id,
				cm.salesforce_account_id,
				pv.cep_partner_id,
				vt.vault_id,
				vt.vault_name,
				vt.vault_datacenter_key,
				vt.vault_datacenter_name,
				vt.vault_status,
				vt.salesforce_vault_id
        from reseller_provisioning pv
		inner join dbo.company cm
		on cm.company_id=pv.company_id
		inner join vault vt
		on vt.vault_id=pv.vault_id
		where cm.salesforce_account_id=@salesforce_account_id
		and vt.vault_datacenter_key=@vault_datacenter_key

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName

	end catch;




end

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_select_customer_keycode]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_safe_account_select_customer_keycode]
(
    @order_header_token VARCHAR(40) = '',
    @license_key VARCHAR(40) = '',
    @keycode VARCHAR(40) = '',
    @input_json NVARCHAR(1000) = NULL,
    @message VARCHAR(100) OUTPUT,
    @response_code INT OUTPUT
)

/*	
    DATE		AUTHOR			REMARKS
    2021-02-01	abelenkiy		Initial creation
    2021-03-18	abelenkiy		Added license_distribution_method_code to return
    2021-03-18	abelenkiy		Made @input_json nullable
    2021-06-24	abelenkiy		Added Amazon license info to output
    2022-07-26	gblandford		AIP-11: Collect additional PII info:
                                    First Name, Last Name
                                    Street Address, City, State, Postal Code
                                    Country
                                Added schema to objects
    2022-07-28	gblandford		AIP-39: Allow for return of multiple keycodes when passing order_header_token
                                        (WSA) license first
                                        Added Allstate registration status to output
    2022-08-04	gblandford		AIP-52:	For Allstate, translate NULL registration status to 0 (Unregistered) only if
                                webroot premium is purchased (WSAP) or if add-on (WSID) is purchased across the same order_header_token (oht)
                                regardless of whether we are returning single keycode or all for the oht
                                Return NULL start_date and expiration_date for unregistered add-on licenses
    2022-08-07	gblandford		AIP-52: Remove start_date & expiration_date juggle
    2023-02-10	abelenkiy		ECOM-778: Added check and error return if all inputs are null
    2023-08-14	jberry			ECOM-1642: Added support for additional Allstate license categories for WSID and WSAP
    2024-08-01	mgolla			THIS CHANGE HAS BEEN REMOVED TO BE HANDLED IN A SEPARATE PROCEDURE
									- ECOM-2950: Implemented code to retrieve details for keycodes that have been modified within the specified time period.
									this logic is implemented for the [Modified-account] API.
    2024-05-26	rambasana		ECOM-4414: Added license_key and Product_term to return
    2024-08-19	ugangichetty	HOT FIX for RB2: Added ISOLATION LEVEL READ UNCOMMITTED
    2024-08-23	jberry			HOT FIX for RB2: Switched @license_keys variable table to temp table #license_list
												 Added new temp tables for account registration logic, product_term, most recent order and orders
												 Cleaned up product term cte
    2024-09-03	jberry			ECOM-5425: Remove CASE statements from WHERE statements and table joins
											Removed GOTOs and optimized to remove bottlenecks
											Added TRY_CONVERT to handle invalid GUID for license_key and order_header_token
								ECOM-5482: Changed product term for S2 subscriptions to properly indicate the term based on plan sku subscription days and license expiration duration
    2024-12-04	jberry			D-4230626: Added keycode alias to return select
	2025-01-17  psatish			IM-4400324 Fixed the Product term for the requested keycode
								Get the product term from the latest order if it exists. 
								If not, retrieve the product term from the subscription table for S2, otherwise, use the bulk load table.
	2026-05-27  psatish			US-5427922 Added customer_id to the #account_registration table and included in the resultset
    DESCRIPTION
    Selects keycode and customer email info by input value. 

    DEPENDENCY
    This sp used by [Modified-account] and [Account-info] API's.
*/

AS
SET NOCOUNT ON;
 
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
 
BEGIN TRY
	DECLARE @license_category_id INT,
			@startdate DATETIM
E = NULL,
			@enddate DATETIME = NULL,
			@license_category_name VARCHAR(20) = NULL,
			@license_key_count INT = 0;

    DECLARE @product_term TABLE
    (
        license_id INT,
        product_term INT
    );

	DROP TABLE IF EXISTS #license_list;
	CREATE TABLE #license_list
	(
		license_id INT,
		license_distribution_method_id INT,
		product_line_id INT,
		keycode VARCHAR(100),
		license_category_id INT
	);

	DROP TABLE IF EXISTS #account_registration;
	CREATE TABLE #account_registration
	(
		license_id INT,
		license_category_id TINYINT,
		customer_email VARCHAR(100),
		first_name NVARCHAR(225),
		last_name NVARCHAR(225),
		address_1 NVARCHAR(255),
		address_2 NVARCHAR(255),
		city NVARCHAR(130),
		state NVARCHAR(2),
		postal_code NVARCHAR(32),
		country_id SMALLINT,
		country VARCHAR(2),
		safe_account_user_guid UNIQUEIDENTIFIER,
		allstate_registration_status_id TINYINT,
		allstate_registration_status VARCHAR(20),
		customer_id INT
	);

	DROP TABLE IF EXISTS #most_recent_order;
	CREATE TABLE #most_recent_order
	(
		license_id INT,
		license_distribution_method_id int,
		order_header_id INT,
		distribution_class VARCHAR(50)
	);


	DROP TABLE IF EXISTS #orders
	CREATE TABLE #orders
	(
	order_header_id int
	);

    DECLARE @APP_CONFIG TABLE
    (
        app_config_name NVARCHAR(50),
        [key] VARCHAR(50),
        [value] NVARCHAR(MAX)
    );
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('S2_DISTRIBUTION_CLASS_NAME', 'GENERAL') f;

    -- get license category lists for webroot premium and allstate add-on
    DECLARE @allstate_premium_category TABLE
    (
        license_category_id INT,
        license_category_name VARCHAR(10)
    );
    INSERT INTO @allstate_premium_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSAP', 'WSAPF', 'WSAIA' );

    DECLARE @allstate_addon_category TABLE
    (
        license_category_id INT
    );
    INSERT INTO @allstate_addon_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' );

    IF ISJSON(@input_json) = 1
    BEGIN
       SELECT @keycode = ISNULL(dbo.fn_RemoveDashes(j.keycode), ''),
               @license_key = ISNULL(j.license_key, ''),
               @order_header_token = ISNULL(j.order_header_token, ''),
               @startdate = j.startdate,
               @enddate = j.enddate,
               @license_category_name = j.license_category_name
        FROM
            OPENJSON(@input_json)
            WITH
            (
                keycode VARCHAR(40) '$.keycode',
                license_key VARCHAR(40) '$.license_key',
                order_header_token VARCHAR(40) '$.order_header_token',
                startdate DATETIME '$.startdate',
                enddate DATETIME '$.enddate',
                license_category_name VARCHAR(50) '$.license_category_name'
            ) j;
    END;
	   
	IF CONCAT(@keycode, @order_header_token, @license_key) = ''
    BEGIN
        SELECT @message = 'keycode or license_key or order_header_token required but not provided.';
        RETURN;
    END;

	IF @license_key <> ''
	BEGIN
		IF(SELECT TRY_CONVERT(UNIQUEIDENTIFIER, @license_key)) IS NULL
		BEGIN
			SELECT @message = 'Invalid license_key';
			RETURN;
		END;

		SELECT @keycode = l.keycode
		FROM dbo.license_key lk
			INNER JOIN dbo.license l
				ON l.license_id = lk.license_id
		WHERE lk.license_key = @license_key;

		IF @keycode = ''
		BEGIN
			SELECT @message = 'Invalid license_key';
			RETURN;
		END;
	END;

    IF @order_header_token <> ''
    BEGIN
		IF(SEL
ECT TRY_CONVERT(UNIQUEIDENTIFIER, @order_header_token)) IS NULL
		BEGIN
			SELECT @message = 'Invalid order_header_token';
			RETURN;
		END;

		INSERT INTO #orders
		(
			order_header_id
		)
		SELECT order_header_id
		FROM dbo.order_header
		WHERE order_header_token = @order_header_token;

        INSERT INTO #license_list
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT DISTINCT
               oil.license_id,
               l.product_line_id,
               l.license_distribution_method_id
        FROM #orders oh
            INNER JOIN dbo.order_item oi
                ON oi.order_header_id = oh.order_header_id
            INNER JOIN dbo.order_item_license oil
                ON oil.order_item_id = oi.order_item_id
            INNER JOIN dbo.license l
                ON l.license_id = oil.license_id

		SELECT @license_key_count = COUNT(*)
		FROM #license_list;

        IF @license_key_count = 0
        BEGIN
            SELECT @message = 'Invalid order_header_token';
            RETURN;
        END;		
    END;

    IF @keycode <> '' AND @license_key_count = 0
    BEGIN
        INSERT INTO #license_list
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT license_id = l.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.license l
        WHERE l.keycode = @keycode;

		SELECT @license_key_count = COUNT(*) FROM #license_list

        IF @license_key_count = 0
        BEGIN
            INSERT INTO #license_list
            (
                license_id,
                product_line_id,
                license_distribution_method_id
            )
            SELECT license_id = l.license_id,
                   product_line_id = l.product_line_id,
                   license_distribution_method_id = l.license_distribution_method_id
            FROM dbo.license_keycode_alias lka
                INNER JOIN dbo.license l
                    ON l.license_id = lka.license_id
            WHERE lka.keycode_alias = @keycode;
        END;

		SELECT @license_key_count = COUNT(*) FROM #license_list

        IF @license_key_count = 0
        BEGIN
            SELECT @message = 'Invalid keycode';
            RETURN;
        END;
    END;

    IF EXISTS (SELECT 1 FROM #license_list WHERE product_line_id = 300)
    BEGIN
        SELECT @message = 'Business keycode ineligible for portal registration';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM #license_list
        WHERE license_distribution_method_id = 919
    ) -- fraud 
    BEGIN
        SELECT @message = 'Fraud keycode';
        RETURN;
    END;

	-- Get Most recent order
	INSERT INTO #most_recent_order
	(
		license_id,
		license_distribution_method_id,
		order_header_id,
		distribution_class
	)
	SELECT lk.license_id,
		   lk.license_distribution_method_id,
		   MAX(oi.order_header_id) AS order_header_id,
		   cl.distribution_class
	FROM #license_list lk
		LEFT JOIN dbo.order_item_license oil
			ON oil.license_id = lk.license_id
		LEFT JOIN dbo.order_item oi
			ON oi.order_item_id = oil.order_item_id
		LEFT JOIN dbo.license_distribution_method_channel ch
			ON ch.license_distribution_method_id = lk.license_distribution_method_id
		LEFT JOIN dbo.distribution_class cl
			ON cl.distribution_class_id = ch.distribution_class_id
	GROUP BY lk.license_id,
			 lk.license_distribution_method_id,
			 cl.distribution_class

	--Product term 
	--Begins
	--Get the maximum product_term from the latest order if it exists
	INSERT INTO @product_term
	(
		license_id,
		product_term
	)
	SELECT ol.license_id,
		   MAX(py.years)
	FROM #most_recent_order ms
		INNER JOIN dbo.order_item o
i
			ON oi.order_header_id = ms.order_header_id
		INNER JOIN dbo.order_item_license ol
			ON ol.order_item_id = oi.order_item_id
			   AND ol.license_id = ms.license_id
		INNER JOIN dbo.product_years py
			ON py.product_id = oi.product_id
	GROUP BY ol.license_id

	--Get the product term from the subscription table for S2 keycodes
	IF EXISTS
	(
		SELECT 1
		FROM #most_recent_order ms
			INNER JOIN @APP_CONFIG ac
				ON ac.[key] = ms.distribution_class
	)
	   AND NOT EXISTS
	(
		SELECT 1
		FROM @product_term
	)
	BEGIN
		INSERT INTO @product_term
		(
			license_id,
			product_term
		)
		SELECT ms.license_id,
			   CASE
				   WHEN sp.subscription_days < 365
						AND (DATEDIFF(dd, s.start_date, s.expiration_date) + 1) < 365 THEN
					   0
				   WHEN sp.subscription_days >= 365 THEN
					   sp.subscription_days / 365
				   ELSE
					   1
			   END
		FROM #most_recent_order ms
			INNER JOIN @APP_CONFIG ac
				ON ac.[key] = ms.distribution_class
			LEFT JOIN dbo.subscription s
				ON s.license_id = ms.license_id
			LEFT JOIN dbo.subscription_plan_sku sp
				ON sp.plan_sku = s.plan_sku
	END

	--Get the product from the bulk load table
	IF NOT EXISTS (SELECT 1 FROM @product_term)
	BEGIN
		INSERT INTO @product_term
		(
			license_id,
			product_term
		)
		SELECT ms.license_id,
			   py.years
		FROM #most_recent_order ms
			INNER JOIN dbo.license_bulk_load_license lb
				ON lb.license_id = ms.license_id
			INNER JOIN dbo.product_years py
				ON py.product_id = lb.product_id
			LEFT JOIN @APP_CONFIG ac
				ON ac.[key] = ms.distribution_class
		WHERE ac.[key] IS NULL

	END
	--Ends

			
    -- check for allstate add-on for keycode or indirectly related via order header token
	DECLARE @addon_exists INT = 0;

	IF (@order_header_token <> '')
	BEGIN
		IF EXISTS
		(
			SELECT 1
			FROM #license_list lk
				INNER JOIN dbo.license_category_license lcl
					ON lcl.license_category_id = lk.license_category_id
				INNER JOIN @allstate_addon_category aac
					ON aac.license_category_id = lcl.license_category_id
		)
		BEGIN
			SET @addon_exists = 1;
		END;
	END;
	ELSE IF @addon_exists = 0
	BEGIN		
		WITH order_header_token AS(
		SELECT oh.order_header_id
		FROM dbo.order_header oh
			INNER JOIN dbo.order_item oi
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_license oil
				ON oil.order_item_id = oi.order_item_id
			INNER JOIN dbo.license l
				ON l.license_id = oil.license_id
		WHERE l.keycode = @keycode
			  AND oh.order_header_token IS NOT NULL)		
		INSERT INTO #orders
		(
			order_header_id
		)
		SELECT oh.order_header_id
		FROM order_header_token oh
			INNER JOIN dbo.order_item oi
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_license oil
				ON oil.order_item_id = oi.order_item_id
			INNER JOIN dbo.license l
				ON l.license_id = oil.license_id
			INNER JOIN dbo.license_category_license lcl
				ON lcl.license_id = l.license_id
			INNER JOIN @allstate_addon_category aac
				ON aac.license_category_id = lcl.license_category_id

		IF EXISTS
		(
			SELECT 1 FROM #orders
		)
		BEGIN
			SET @addon_exists = 1;
		END;
	END;

	--get account registration details
	INSERT INTO #account_registration
	(
		license_id,
		license_category_id,
		customer_email,
		first_name,
		last_name,
		address_1,
		address_2,
		city,
		state,
		postal_code,
		country_id,
		country,
		safe_account_user_guid,
		allstate_registration_status_id,
		allstate_registration_status,
		customer_id
	)	
	SELECT DISTINCT
			lk.license_id,
			lcl.license_category_id,
			ce.customer_email,
			c.first_name,
			c.last_name,
			ca.address_1,
			ca.address_2,
			ca.city,
			ca.state,
			ca.postal_code,
			ca.country_id,
			lu.iso AS country, -- iso2
			sauc.safe_account_user_guid,
			ars.allstate_registration_status_id,
			ars.allstate_registration_status,
			l.customer_id
	F
ROM #license_list lk
		INNER JOIN dbo.license l 
			ON l.license_id = lk.license_id
		INNER JOIN dbo.license_category_license lcl
			ON lcl.license_id = l.license_id
		LEFT JOIN dbo.customer_email ce
			ON ce.customer_id = l.customer_id
				AND ce.email_status_id = 1
		LEFT JOIN dbo.safe_account_user_customer sauc
			ON sauc.customer_id = ce.customer_id   
		LEFT JOIN dbo.customer c
			ON c.customer_id = l.customer_id
		LEFT JOIN dbo.customer_address ca
			ON ca.customer_id = c.customer_id
				AND ca.address_type_id = 1 -- bill-to
				AND ca.address_status_id = 1 -- active
		LEFT JOIN dbo.lu_countries lu
			ON lu.country_id = ca.country_id
		LEFT JOIN dbo.allstate_registration_status ars
			ON ars.allstate_registration_status_id = sauc.allstate_registration_status_id

		UPDATE r
		SET r.allstate_registration_status_id = 
			CASE 
			WHEN sauc.allstate_registration_status_id IS NULL
			AND
			(
				EXISTS
				(
					SELECT 1
					FROM @allstate_premium_category AS apc
					WHERE apc.license_category_id = r.license_category_id
				)
				OR EXISTS
					(
						SELECT 1
						FROM @allstate_addon_category AS apc
						WHERE apc.license_category_id = r.license_category_id
					)
				OR @addon_exists = 1
			) THEN
			0
			ELSE
				sauc.allstate_registration_status_id
			END
		FROM #account_registration r
		LEFT JOIN dbo.safe_account_user_customer sauc
					ON sauc.safe_account_user_guid = r.safe_account_user_guid

		UPDATE r
		SET allstate_registration_status = ars.allstate_registration_status
		FROM #account_registration r
		JOIN dbo.allstate_registration_status ars ON ars.allstate_registration_status_id = r.allstate_registration_status_id
	
	--return select
    SELECT DISTINCT
           p.item_id,
           p.license_category_id,
           p.license_category_name,
           p.license_category_description,
           p.license_seats,
           p.storage_gb,
           p.license_keycode_type_id,
           p.license_attribute_id,
           p.license_attribute_description,
           p.license_attribute_license_value,
           p.license_attribute_license_value_description,
           p.start_date,
           p.expiration_date,
           p.category_type_id,
           p.category_type_name,
           p.item_hierarchy_name,
           p.license_status_description,
           p.keycode,
           lky.license_key,
           pt.product_term,
           p.license_autorenewal_value,
           ldm.license_distribution_method_code,
           ldm.license_distribution_method_name,
           r.customer_email,
           r.first_name,
           r.last_name,
           r.address_1,
           r.address_2,
           r.city,
           r.state,
           r.postal_code,
           r.country_id,
           r.country,  -- iso2
           r.safe_account_user_guid,
           r.allstate_registration_status_id,
           r.allstate_registration_status,
           asu.amazon_subscription_key,
           ass.amazon_subscription_status_name,
           l.modified_date,
           lka.keycode_alias,
		   r.customer_id
    FROM #license_list lk
        CROSS APPLY dbo.fn_license_select_license_profile(lk.license_id) p
        INNER JOIN dbo.license l
            ON l.license_id = p.license_id
        INNER JOIN dbo.license_distribution_method ldm
            ON ldm.license_distribution_method_id = l.license_distribution_method_id
        INNER JOIN dbo.license_distribution_method_channel ldmc
            ON ldmc.license_distribution_method_id = ldm.license_distribution_method_id
        LEFT JOIN dbo.license_key lky
            ON lky.license_id = lk.license_id
        LEFT JOIN dbo.license_keycode_alias lka
            ON lka.license_id = l.license_id
        LEFT JOIN @product_term pt
            ON pt.license_id = lk.license_id
	    LEFT JOIN dbo.amazon_account aa
            ON aa.customer_id = l.customer_id
        LEFT JOIN d
bo.amazon_subscription asu
            ON asu.amazon_account_id = aa.amazon_account_id
               AND asu.license_id = l.license_id
        LEFT JOIN dbo.amazon_subscription_status ass
            ON ass.amazon_subscription_status_id = asu.amazon_subscription_status_id
		LEFT JOIN #account_registration r
			ON r.license_id = lk.license_id AND r.license_category_id = p.license_category_id        
    ORDER BY p.license_category_id;

    IF @@rowcount > 0
    BEGIN
        SELECT @message = 'Success';
    END;

END TRY
BEGIN CATCH
    DECLARE @dbname NVARCHAR(128);

    SET @dbname = DB_NAME();

    EXEC dbo.usp_LogError @ErrorDB = @dbname;
END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_select_customer_keycode_backup]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_safe_account_select_customer_keycode_backup]
(
    @order_header_token VARCHAR(40) = '',
    @license_key VARCHAR(40) = '',
    @keycode VARCHAR(40) = '',
    @input_json NVARCHAR(1000) = NULL,
    @message VARCHAR(100) OUTPUT,
    @response_code INT OUTPUT
)

/*	
    DATE		AUTHOR			REMARKS
    2021-02-01	abelenkiy		Initial creation
    2021-03-18	abelenkiy		Added license_distribution_method_code to return
    2021-03-18	abelenkiy		Made @input_json nullable
    2021-06-24	abelenkiy		Added Amazon license info to output
    2022-07-26	gblandford		AIP-11: Collect additional PII info:
                                    First Name, Last Name
                                    Street Address, City, State, Postal Code
                                    Country
                                Added schema to objects
    2022-07-28	gblandford		AIP-39: Allow for return of multiple keycodes when passing order_header_token
                                        (WSA) license first
                                        Added Allstate registration status to output
    2022-08-04	gblandford		AIP-52:	For Allstate, translate NULL registration status to 0 (Unregistered) only if
                                webroot premium is purchased (WSAP) or if add-on (WSID) is purchased across the same order_header_token (oht)
                                regardless of whether we are returning single keycode or all for the oht
                                Return NULL start_date and expiration_date for unregistered add-on licenses
    2022-08-07	gblandford		AIP-52: Remove start_date & expiration_date juggle
    2023-02-10	abelenkiy		ECOM-778: Added check and error return if all inputs are null
    2023-08-14	jberry			ECOM-1642: Added support for additional Allstate license categories for WSID and WSAP
    2024-08-01  mgolla			ECOM-2950: Implemented code to retrieve details for keycodes that have been modified within the specified time period.
                                            this logic is implemented for the [Modified-account] API.
    2024-05-26	rambasana		ECOM-4414: Added license_key and Product_term to return
    
    DESCRIPTION
    Selects keycode and customer email info by input value. 
    Maybe add TRY_CONVERT for GUIDS
    More robust error handling (e.g. "invalid license_key")

    DEPENDENCY
    This sp used by [Modified-account] and [Account-info] API's.
*/

AS
SET NOCOUNT ON;

BEGIN TRY
    DECLARE @license_category_id INT,
            @startdate DATETIME = NULL,
            @enddate DATETIME = NULL,
            @license_category_name VARCHAR(20) = NULL;

    DECLARE @product_term TABLE
    (
        license_id INT,
        product_term INT
    );

    DECLARE @license_keys TABLE
    (
        license_id INT,
        license_distribution_method_id INT,
        product_line_id INT,
        keycode VARCHAR(100),
        license_category_id INT
    );

    DECLARE @APP_CONFIG TABLE
    (
        app_config_name NVARCHAR(50),
        [key] NVARCHAR(50),
        [value] NVARCHAR(MAX)
    );
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('S2_DISTRIBUTION_CLASS_NAME', 'GENERAL') f;

    -- get license category lists for webroot premium and allstate add-on
    DECLARE @allstate_premium_category TABLE
    (
        license_category_id INT,
        license_category_name VARCHAR(10)
    );
    INSERT INTO @allstate_premium_category
    (
        license_category_id
    )
    SELECT license_category_id
    F
ROM license_category
    WHERE license_category_name IN ( 'WSAP', 'WSAPF' );

    DECLARE @allstate_addon_category TABLE
    (
        license_category_id INT
    );
    INSERT INTO @allstate_addon_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' );

    IF ISJSON(@input_json) = 1
    BEGIN
        SELECT @keycode = ISNULL(dbo.fn_RemoveDashes(j.keycode), ''),
               @license_key = ISNULL(j.license_key, ''),
               @order_header_token = ISNULL(j.order_header_token, ''),
               @startdate = j.startdate,
               @enddate = j.enddate,
               @license_category_name = j.license_category_name
        FROM
            OPENJSON(@input_json)
            WITH
            (
                keycode VARCHAR(40) '$.keycode',
                license_key VARCHAR(40) '$.license_key',
                order_header_token VARCHAR(40) '$.order_header_token',
                startdate DATETIME '$.startdate',
                enddate DATETIME '$.enddate',
                license_category_name VARCHAR(50) '$.license_category_name'
            ) j;
    END;

    IF ISNULL(CONCAT(@startdate, @enddate), '') <> ''
    BEGIN

        IF ((SELECT DATEDIFF(dd, @startdate, @enddate)) > 7)
        BEGIN
            SELECT @message = 'provided date range should be seven days or less';
            RETURN;
        END;

        IF ISNULL(@license_category_name, '') <> ''
        BEGIN
            SELECT @license_category_id = license_category_id
            FROM dbo.license_category AS lc
            WHERE license_category_name = @license_category_name;

            IF @@rowcount = 0
            BEGIN
                SELECT @message = 'provide a valid license category name';

                RETURN;
            END;
        END;


        INSERT INTO @license_keys
        (
            license_id,
            license_distribution_method_id,
            product_line_id,
            keycode,
            license_category_id
        )
        SELECT l.license_id,
               l.license_distribution_method_id,
               l.product_line_id,
               l.keycode,
               lc.license_category_id
        FROM dbo.license AS l
            JOIN dbo.license_category_license AS lcl
                ON lcl.license_id = l.license_id
                   AND l.modified_date >= @startdate
                   AND l.modified_date <= @enddate
            JOIN dbo.license_category AS lc
                ON lc.license_category_id = lcl.license_category_id
        WHERE (
                  ISNULL(@license_category_name, '') <> ''
                  AND lc.license_category_id = @license_category_id
              ) -- fetching data based on the license category name
              OR (
                     -----------if category name is not passed then pulling only all state product details.--------------------------
                     ISNULL(@license_category_name, '') = ''
                     AND
                     (
                         EXISTS
        (
            SELECT 1
            FROM @allstate_premium_category AS apc
            WHERE apc.license_category_id = lc.license_category_id
        )
                         OR EXISTS
        (
            SELECT 1
            FROM @allstate_addon_category AS apc
            WHERE apc.license_category_id = lc.license_category_id
        )
                     )
                 )
                 AND l.license_distribution_method_id <> 123; -- Excluding Test Data(123	TEST	Internal Test Distribution Method )
        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'there is no licenses added or modified for specific period';
            RETURN;
        END;

        GOTO select_section;
    END;
    IF CONCAT(@keycode, @license_key, @order_he
ader_token) = ''
    BEGIN
        SELECT @message = 'keycode or license_key or order_header_token required but not provided.';
        RETURN;
    END;

    IF @order_header_token <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT DISTINCT
               license_id = oil.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.order_header oh
            INNER JOIN dbo.customer_order co
                ON co.order_header_id = oh.order_header_id
            INNER JOIN dbo.order_item oi
                ON oi.order_header_id = oh.order_header_id
            INNER JOIN dbo.order_item_license oil
                ON oil.order_item_id = oi.order_item_id
            INNER JOIN dbo.license l
                ON l.license_id = oil.license_id
        WHERE oh.order_header_token = @order_header_token;

        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'Invalid order_header_token';
            RETURN;
        END;

        GOTO return_section;
    END;

    IF @license_key <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT license_id = l.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.license_key lk
            INNER JOIN dbo.license l
                ON l.license_id = lk.license_id
        WHERE lk.license_key = @license_key;

        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'Invalid license_key';
            RETURN;
        END;

        GOTO return_section;
    END;

    IF @keycode <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT license_id = l.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.license l
        WHERE l.keycode = @keycode;

        IF @@rowcount = 0
        BEGIN
            INSERT INTO @license_keys
            (
                license_id,
                product_line_id,
                license_distribution_method_id
            )
            SELECT license_id = l.license_id,
                   product_line_id = l.product_line_id,
                   license_distribution_method_id = l.license_distribution_method_id
            FROM dbo.license_keycode_alias lka
                INNER JOIN dbo.license l
                    ON l.license_id = lka.license_id
            WHERE lka.keycode_alias = @keycode;
        END;

        IF NOT EXISTS (SELECT 1 FROM @license_keys)
        BEGIN
            SELECT @message = 'Invalid keycode';
            RETURN;
        END;

        GOTO return_section;
    END;

    return_section:
    IF EXISTS (SELECT 1 FROM @license_keys WHERE product_line_id = 300)
    BEGIN
        SELECT @message = 'Business keycode ineligible for portal registration';
        RETURN;
    END;
    IF EXISTS
    (
        SELECT 1
        FROM @license_keys
        WHERE license_distribution_method_id = 919
    ) -- fraud 
    BEGIN
        SELECT @message = 'Fraud keycode';
        RETURN;
    END;

    -- Get Product_term 
    WITH cte
    AS (SELECT DISTINCT
               a.license_id,ol.license_id order_item_license_id,
               py.years order_product_term,
               (sp.subscription_days / 365) subscription_product_term,
               py1.years bulk_key_product_term,
               dc.distribution_class
        FROM
        (
            SELECT lk.license_id,
                   lk.license_distribution_method_id,
                   MAX(oi.order_header_id) AS order_header_id
            FROM @license_keys lk
                LEFT JOIN dbo.order_item_license oil
                    ON oil.license_id = lk.license_id
                LEFT JOIN dbo.order_item oi
                    ON oi.order_item_id = oil.order_item_id
            GROUP BY lk.license_id,
                     lk.license_distribution_method_id
        ) a
            LEFT JOIN dbo.order_item oi1
                ON oi1.order_header_id = a.order_header_id
            LEFT JOIN dbo.order_item_license ol
                ON ol.license_id = a.license_id
                   AND ol.order_item_id = oi1.order_item_id
				   	and ol.license_id IS NOT null
            LEFT JOIN dbo.license_distribution_method_channel lmch
                ON lmch.license_distribution_method_id = a.license_distribution_method_id
            LEFT JOIN dbo.distribution_class dc
                ON dc.distribution_class_id = lmch.distribution_class_id
            LEFT JOIN dbo.product_years py
                ON py.product_id = oi1.product_id
            LEFT JOIN dbo.license_summary ls
                ON ls.license_id = a.license_id
            LEFT JOIN dbo.subscription s
                ON s.subscription_id = ls.subscription_id
            LEFT JOIN dbo.subscription_plan_sku sp
                ON sp.plan_sku = s.plan_sku
            LEFT JOIN dbo.license_bulk_load_license lbl
                ON lbl.license_id = a.license_id
            LEFT JOIN dbo.product_years py1
                ON py1.product_id = lbl.product_id
			
				)
				
    INSERT @product_term
    (
        license_id,
        product_term
    )
    SELECT cte.license_id,
           CASE
               WHEN cte.subscription_product_term IS NOT NULL
                    AND ap.[key] IS NOT NULL then
                   cte.subscription_product_term
               WHEN cte.subscription_product_term IS NULL
                    AND ap.[key] IS NOT NULL THEN 
                   1
               WHEN cte.order_product_term IS NOT NULL
			   AND cte.order_product_term <> 0
			   THEN
                   cte.order_product_term     
               ELSE
                   cte.bulk_key_product_term
           END
    FROM cte
        LEFT JOIN @APP_CONFIG ap
            ON ap.[key] = cte.distribution_class;
   
  
    -- check for allstate add-on for any keycodes that exist here or are indirectly related ia header token

    -- check if we have an allstate add-on
    DECLARE @addon_exists INT = 0;

    IF (@order_header_token <> '')
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM @license_keys lk
                CROSS APPLY dbo.fn_license_select_license_profile(lk.license_id) p
                JOIN @allstate_addon_category aac
                    ON aac.license_category_id = p.license_category_id
        )
        BEGIN
            SET @addon_exists = 1;
        END;
        GOTO select_section;
    END;
    ELSE
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM dbo.order_header oh
                INNER JOIN dbo.customer_order co
                    ON co.order_header_id = oh.order_header_id
                INNER JOIN dbo.order_item oi
                    ON oi.order_header_id = oh.order_header_id
                INNER JOIN dbo.order_item_license oil
                    ON oil.order_item_id = oi.order_item_id
                INNER JOIN dbo.license l
                    ON l.license_id = oil.license_id
                CROSS APPLY dbo.fn_license_select_license_profile(l.license_id) p
                JOIN @allstate_addon_category aac
                    ON aac.license_category_id = p.license_category_id
                INNER JOIN
                (
                    SELECT oh.order_header_token
                 
   FROM dbo.order_header oh
                        INNER JOIN dbo.order_item oi
                            ON oi.order_header_id = oh.order_header_id
                        INNER JOIN dbo.order_item_license oil
                            ON oil.order_item_id = oi.order_item_id
                        INNER JOIN dbo.license l
                            ON l.license_id = oil.license_id
                    WHERE l.keycode = @keycode
                          AND oh.order_header_token IS NOT NULL
                ) oht
                    ON oht.order_header_token = oh.order_header_token
        )
        BEGIN
            SET @addon_exists = 1;
        END;
        GOTO select_section;
    END;

    select_section:
    SELECT DISTINCT
           p.item_id,
           p.license_category_id,
           p.license_category_name,
           p.license_category_description,
           p.license_seats,
           p.storage_gb,
           p.license_keycode_type_id,
           p.license_attribute_id,
           p.license_attribute_description,
           p.license_attribute_license_value,
           p.license_attribute_license_value_description,
           p.start_date,
           p.expiration_date,
           p.category_type_id,
           p.category_type_name,
           p.item_hierarchy_name,
           p.license_status_description,
           p.keycode,
           lky.license_key,
           pt.product_term,
           p.license_autorenewal_value,
           ldm.license_distribution_method_code,
           ldm.license_distribution_method_name,
           ce.customer_email,
           c.first_name,
           c.last_name,
           ca.address_1,
           ca.address_2,
           ca.city,
           ca.state,
           ca.postal_code,
           ca.country_id,
           lu.iso AS country, -- iso2
           sauc.safe_account_user_guid,
           ars.allstate_registration_status_id,
           ars.allstate_registration_status,
           asu.amazon_subscription_key,
           ass.amazon_subscription_status_name,
           l.modified_date
    FROM @license_keys lk
        CROSS APPLY dbo.fn_license_select_license_profile(lk.license_id) p
        INNER JOIN dbo.license l
            ON l.license_id = p.license_id
        INNER JOIN dbo.license_distribution_method ldm
            ON ldm.license_distribution_method_id = l.license_distribution_method_id
        INNER JOIN dbo.license_distribution_method_channel ldmc
            ON ldmc.license_distribution_method_id = ldm.license_distribution_method_id
        LEFT JOIN dbo.license_key lky
            ON lky.license_id = lk.license_id
        LEFT JOIN @product_term pt
            ON pt.license_id = lk.license_id
			AND pt.product_term IS NOT null
        LEFT JOIN dbo.amazon_account aa
            ON aa.customer_id = l.customer_id
        LEFT JOIN dbo.amazon_subscription asu
            ON asu.amazon_account_id = aa.amazon_account_id
               AND asu.license_id = l.license_id
        LEFT JOIN dbo.amazon_subscription_status ass
            ON ass.amazon_subscription_status_id = asu.amazon_subscription_status_id
        LEFT JOIN dbo.customer_email ce
            ON ce.customer_id = l.customer_id
               AND ce.email_status_id = 1
        LEFT JOIN dbo.safe_account_user_customer sauc
            ON sauc.customer_id = ce.customer_id
        LEFT JOIN dbo.allstate_registration_status ars
            ON ars.allstate_registration_status_id = (CASE
                                                          WHEN ISNULL(CONCAT(@startdate, @enddate), '') <> ''
                                                               AND sauc.allstate_registration_status_id IS NULL
                                                               AND
                                                               (
                                                                   EXISTS
               
                                                    (
                                                                       SELECT 1
                                                                       FROM @allstate_premium_category AS apc
                                                                       WHERE apc.license_category_id = p.license_category_id
                                                                   )
                                                                   OR EXISTS
                                                                      (
                                                                          SELECT 1
                                                                          FROM @allstate_addon_category AS apc
                                                                          WHERE apc.license_category_id = p.license_category_id
                                                                      )
                                                               ) THEN
                                                              0
                                                          WHEN
                                                          (
                                                              sauc.allstate_registration_status_id IS NULL
                                                              AND
                                                              (
                                                                  @addon_exists = 1
                                                                  OR p.license_category_id IN
                                                                     (
                                                                         SELECT license_category_id FROM @allstate_premium_category
                                                                     )
                                                              )
                                                          ) THEN
                                                              0
                                                          ELSE
                                                              sauc.allstate_registration_status_id
                                                      END
                                                     ) -- only translate NULL if an Allsate product or Allstate add-on has been purchased

        LEFT JOIN dbo.customer c
            ON c.customer_id = l.customer_id
        LEFT JOIN dbo.customer_address ca
            ON ca.customer_id = c.customer_id
               AND ca.address_type_id = 1 -- bill-to
               AND ca.address_status_id = 1 -- active
        LEFT JOIN dbo.lu_countries lu
            ON lu.country_id = ca.country_id
    ORDER BY p.license_category_id;

    IF @@rowcount > 0
    BEGIN
        SELECT @message = 'Success';
    END;

END TRY
BEGIN CATCH
    DECLARE @dbname NVARCHAR(128);

    SET @dbname = DB_NAME();

    EXEC dbo.usp_LogError @ErrorDB = @dbname;
END CATCH;


GO
