-- =============================================================================

CREATE PROCEDURE [dbo].[usp_safe_account_select_customer_keycode_pre_rb2]
(
    @order_header_token VARCHAR(40) = '',
    @license_key VARCHAR(40) = '',
    @keycode VARCHAR(40) = '',
    @input_json NVARCHAR(1000) = NULL,
    @message VARCHAR(100) OUTPUT,
    @response_code INT OUTPUT
)

/*	
    DATE		AUTHOR			REMARKS
    2021-02-01	abelenkiy		Initial creation
    2021-03-18	abelenkiy		Added license_distribution_method_code to return
    2021-03-18	abelenkiy		Made @input_json nullable
    2021-06-24	abelenkiy		Added Amazon license info to output
    2022-07-26	gblandford		AIP-11: Collect additional PII info:
                                    First Name, Last Name
                                    Street Address, City, State, Postal Code
                                    Country
                                Added schema to objects
    2022-07-28	gblandford		AIP-39: Allow for return of multiple keycodes when passing order_header_token
                                        (WSA) license first
                                        Added Allstate registration status to output
    2022-08-04	gblandford		AIP-52:	For Allstate, translate NULL registration status to 0 (Unregistered) only if
                                webroot premium is purchased (WSAP) or if add-on (WSID) is purchased across the same order_header_token (oht)
                                regardless of whether we are returning single keycode or all for the oht
                                Return NULL start_date and expiration_date for unregistered add-on licenses
    2022-08-07	gblandford		AIP-52: Remove start_date & expiration_date juggle
    2023-02-10	abelenkiy		ECOM-778: Added check and error return if all inputs are null
    2023-08-14	jberry			ECOM-1642: Added support for additional Allstate license categories for WSID and WSAP
    /*2024-08-01  mgolla			ECOM-2950: Implemented code to retrieve details for keycodes that have been modified within the specified time period.
                                            this logic is implemented for the [Modified-account] API.
											need to rewrite this logic*/
    2024-05-26	rambasana		ECOM-4414: Added license_key and Product_term to return
    
    DESCRIPTION
    Selects keycode and customer email info by input value. 
    Maybe add TRY_CONVERT for GUIDS
    More robust error handling (e.g. "invalid license_key")

    DEPENDENCY
    This sp used by [Modified-account] and [Account-info] API's.
*/

AS
SET NOCOUNT ON;

BEGIN TRY
    DECLARE @license_category_id INT,
            @startdate DATETIME = NULL,
            @enddate DATETIME = NULL,
            @license_category_name VARCHAR(20) = NULL;

    DECLARE @product_term TABLE
    (
        license_id INT,
        product_term INT
    );

    DECLARE @license_keys TABLE
    (
        license_id INT,
        license_distribution_method_id INT,
        product_line_id INT,
        keycode VARCHAR(100),
        license_category_id INT
    );

    DECLARE @APP_CONFIG TABLE
    (
        app_config_name NVARCHAR(50),
        [key] NVARCHAR(50),
        [value] NVARCHAR(MAX)
    );
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('S2_DISTRIBUTION_CLASS_NAME', 'GENERAL') f;

    -- get license category lists for webroot premium and allstate add-on
    DECLARE @allstate_premium_category TABLE
    (
        license_category_id INT,
        license_category_name VARCHAR(10)
    );
    INSERT INTO @allstate_premium_category
    (
        license_category_id
 
   )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSAP', 'WSAPF' );

    DECLARE @allstate_addon_category TABLE
    (
        license_category_id INT
    );
    INSERT INTO @allstate_addon_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' );

    IF ISJSON(@input_json) = 1
    BEGIN
        SELECT @keycode = ISNULL(dbo.fn_RemoveDashes(j.keycode), ''),
               @license_key = ISNULL(j.license_key, ''),
               @order_header_token = ISNULL(j.order_header_token, ''),
               @startdate = j.startdate,
               @enddate = j.enddate,
               @license_category_name = j.license_category_name
        FROM
            OPENJSON(@input_json)
            WITH
            (
                keycode VARCHAR(40) '$.keycode',
                license_key VARCHAR(40) '$.license_key',
                order_header_token VARCHAR(40) '$.order_header_token',
                startdate DATETIME '$.startdate',
                enddate DATETIME '$.enddate',
                license_category_name VARCHAR(50) '$.license_category_name'
            ) j;
    END;

  IF ISNULL(CONCAT(@startdate, @enddate), '') <> ''
  GOTO select_section;
  /*
  BEGIN

        IF ((SELECT DATEDIFF(dd, @startdate, @enddate)) > 7)
        BEGIN
            SELECT @message = 'provided date range should be seven days or less';
            RETURN;
        END;

        IF ISNULL(@license_category_name, '') <> ''
        BEGIN
            SELECT @license_category_id = license_category_id
            FROM dbo.license_category AS lc
            WHERE license_category_name = @license_category_name;

            IF @@rowcount = 0
            BEGIN
                SELECT @message = 'provide a valid license category name';

                RETURN;
            END;
        END;


        INSERT INTO @license_keys
        (
            license_id,
            license_distribution_method_id,
            product_line_id,
            keycode,
            license_category_id
        )
        SELECT l.license_id,
               l.license_distribution_method_id,
               l.product_line_id,
               l.keycode,
               lc.license_category_id
        FROM dbo.license AS l
            JOIN dbo.license_category_license AS lcl
                ON lcl.license_id = l.license_id
                   AND l.modified_date >= @startdate
                   AND l.modified_date <= @enddate
            JOIN dbo.license_category AS lc
                ON lc.license_category_id = lcl.license_category_id
        WHERE (
                  ISNULL(@license_category_name, '') <> ''
                  AND lc.license_category_id = @license_category_id
              ) -- fetching data based on the license category name
              OR (
                     -----------if category name is not passed then pulling only all state product details.--------------------------
                     ISNULL(@license_category_name, '') = ''
                     AND
                     (
                         EXISTS
        (
            SELECT 1
            FROM @allstate_premium_category AS apc
            WHERE apc.license_category_id = lc.license_category_id
        )
                         OR EXISTS
        (
            SELECT 1
            FROM @allstate_addon_category AS apc
            WHERE apc.license_category_id = lc.license_category_id
        )
                     )
                 )
                 AND l.license_distribution_method_id <> 123; -- Excluding Test Data(123	TEST	Internal Test Distribution Method )
        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'there is no licenses added or modified for specific period';
            RETURN;
        END;
		
        	GOTO se
lect_section;
    END;
    */

	IF CONCAT(@keycode, @license_key, @order_header_token) = ''
    BEGIN
        SELECT @message = 'keycode or license_key or order_header_token required but not provided.';
        RETURN;
    END;

    IF @order_header_token <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT DISTINCT
               license_id = oil.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.order_header oh
            INNER JOIN dbo.customer_order co
                ON co.order_header_id = oh.order_header_id
            INNER JOIN dbo.order_item oi
                ON oi.order_header_id = oh.order_header_id
            INNER JOIN dbo.order_item_license oil
                ON oil.order_item_id = oi.order_item_id
            INNER JOIN dbo.license l
                ON l.license_id = oil.license_id
        WHERE oh.order_header_token = @order_header_token;

        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'Invalid order_header_token';
            RETURN;
        END;

        GOTO return_section;
    END;

    IF @license_key <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT license_id = l.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.license_key lk
            INNER JOIN dbo.license l
                ON l.license_id = lk.license_id
        WHERE lk.license_key = @license_key;

        IF @@rowcount = 0
        BEGIN
            SELECT @message = 'Invalid license_key';
            RETURN;
        END;

        GOTO return_section;
    END;

    IF @keycode <> ''
    BEGIN
        INSERT INTO @license_keys
        (
            license_id,
            product_line_id,
            license_distribution_method_id
        )
        SELECT license_id = l.license_id,
               product_line_id = l.product_line_id,
               license_distribution_method_id = l.license_distribution_method_id
        FROM dbo.license l
        WHERE l.keycode = @keycode;

        IF @@rowcount = 0
        BEGIN
            INSERT INTO @license_keys
            (
                license_id,
                product_line_id,
                license_distribution_method_id
            )
            SELECT license_id = l.license_id,
                   product_line_id = l.product_line_id,
                   license_distribution_method_id = l.license_distribution_method_id
            FROM dbo.license_keycode_alias lka
                INNER JOIN dbo.license l
                    ON l.license_id = lka.license_id
            WHERE lka.keycode_alias = @keycode;
        END;

        IF NOT EXISTS (SELECT 1 FROM @license_keys)
        BEGIN
            SELECT @message = 'Invalid keycode';
            RETURN;
        END;

        GOTO return_section;
    END;

    return_section:
    IF EXISTS (SELECT 1 FROM @license_keys WHERE product_line_id = 300)
    BEGIN
        SELECT @message = 'Business keycode ineligible for portal registration';
        RETURN;
    END;
    IF EXISTS
    (
        SELECT 1
        FROM @license_keys
        WHERE license_distribution_method_id = 919
    ) -- fraud 
    BEGIN
        SELECT @message = 'Fraud keycode';
        RETURN;
    END;

    -- Get Product_term 
    WITH cte
    AS (SELECT DISTINCT
               a.license_id,ol.license_id order_item_license_id,
               py.years order_product_term,
               (sp.subscription_days / 365) subscription_product_term,
               py1.yea
rs bulk_key_product_term,
               dc.distribution_class
        FROM
        (
            SELECT lk.license_id,
                   lk.license_distribution_method_id,
                   MAX(oi.order_header_id) AS order_header_id
            FROM @license_keys lk
                LEFT JOIN dbo.order_item_license oil
                    ON oil.license_id = lk.license_id
                LEFT JOIN dbo.order_item oi
                    ON oi.order_item_id = oil.order_item_id
            GROUP BY lk.license_id,
                     lk.license_distribution_method_id
        ) a
            LEFT JOIN dbo.order_item oi1
                ON oi1.order_header_id = a.order_header_id
            LEFT JOIN dbo.order_item_license ol
                ON ol.license_id = a.license_id
                   AND ol.order_item_id = oi1.order_item_id
				   	and ol.license_id IS NOT null
            LEFT JOIN dbo.license_distribution_method_channel lmch
                ON lmch.license_distribution_method_id = a.license_distribution_method_id
            LEFT JOIN dbo.distribution_class dc
                ON dc.distribution_class_id = lmch.distribution_class_id
            LEFT JOIN dbo.product_years py
                ON py.product_id = oi1.product_id
            LEFT JOIN dbo.license_summary ls
                ON ls.license_id = a.license_id
            LEFT JOIN dbo.subscription s
                ON s.subscription_id = ls.subscription_id
            LEFT JOIN dbo.subscription_plan_sku sp
                ON sp.plan_sku = s.plan_sku
            LEFT JOIN dbo.license_bulk_load_license lbl
                ON lbl.license_id = a.license_id
            LEFT JOIN dbo.product_years py1
                ON py1.product_id = lbl.product_id
			
				)
				
    INSERT @product_term
    (
        license_id,
        product_term
    )
    SELECT cte.license_id,
           CASE
               WHEN cte.subscription_product_term IS NOT NULL
                    AND ap.[key] IS NOT NULL then
                   cte.subscription_product_term
               WHEN cte.subscription_product_term IS NULL
                    AND ap.[key] IS NOT NULL THEN 
                   1
               WHEN cte.order_product_term IS NOT NULL
			   AND cte.order_product_term <> 0
			   THEN
                   cte.order_product_term     
               ELSE
                   cte.bulk_key_product_term
           END
    FROM cte
        LEFT JOIN @APP_CONFIG ap
            ON ap.[key] = cte.distribution_class;
   
  
    -- check for allstate add-on for any keycodes that exist here or are indirectly related ia header token

    -- check if we have an allstate add-on
    DECLARE @addon_exists INT = 0;

    IF (@order_header_token <> '')
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM @license_keys lk
                CROSS APPLY dbo.fn_license_select_license_profile(lk.license_id) p
                JOIN @allstate_addon_category aac
                    ON aac.license_category_id = p.license_category_id
        )
        BEGIN
            SET @addon_exists = 1;
        END;
        GOTO select_section;
    END;
    ELSE
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM dbo.order_header oh
                INNER JOIN dbo.customer_order co
                    ON co.order_header_id = oh.order_header_id
                INNER JOIN dbo.order_item oi
                    ON oi.order_header_id = oh.order_header_id
                INNER JOIN dbo.order_item_license oil
                    ON oil.order_item_id = oi.order_item_id
                INNER JOIN dbo.license l
                    ON l.license_id = oil.license_id
                CROSS APPLY dbo.fn_license_select_license_profile(l.license_id) p
                JOIN @allstate_addon_category aac
                    ON aac.license_category_id = p.license_category_id
                INNER JOIN
       
         (
                    SELECT oh.order_header_token
                    FROM dbo.order_header oh
                        INNER JOIN dbo.order_item oi
                            ON oi.order_header_id = oh.order_header_id
                        INNER JOIN dbo.order_item_license oil
                            ON oil.order_item_id = oi.order_item_id
                        INNER JOIN dbo.license l
                            ON l.license_id = oil.license_id
                    WHERE l.keycode = @keycode
                          AND oh.order_header_token IS NOT NULL
                ) oht
                    ON oht.order_header_token = oh.order_header_token
        )
        BEGIN
            SET @addon_exists = 1;
        END;
        GOTO select_section;
    END;

    select_section:
    SELECT DISTINCT
           p.item_id,
           p.license_category_id,
           p.license_category_name,
           p.license_category_description,
           p.license_seats,
           p.storage_gb,
           p.license_keycode_type_id,
           p.license_attribute_id,
           p.license_attribute_description,
           p.license_attribute_license_value,
           p.license_attribute_license_value_description,
           p.start_date,
           p.expiration_date,
           p.category_type_id,
           p.category_type_name,
           p.item_hierarchy_name,
           p.license_status_description,
           p.keycode,
           lky.license_key,
           pt.product_term,
           p.license_autorenewal_value,
           ldm.license_distribution_method_code,
           ldm.license_distribution_method_name,
           ce.customer_email,
           c.first_name,
           c.last_name,
           ca.address_1,
           ca.address_2,
           ca.city,
           ca.state,
           ca.postal_code,
           ca.country_id,
           lu.iso AS country, -- iso2
           sauc.safe_account_user_guid,
           ars.allstate_registration_status_id,
           ars.allstate_registration_status,
           asu.amazon_subscription_key,
           ass.amazon_subscription_status_name,
           l.modified_date
    FROM @license_keys lk
        CROSS APPLY dbo.fn_license_select_license_profile(lk.license_id) p
        INNER JOIN dbo.license l
            ON l.license_id = p.license_id
        INNER JOIN dbo.license_distribution_method ldm
            ON ldm.license_distribution_method_id = l.license_distribution_method_id
        INNER JOIN dbo.license_distribution_method_channel ldmc
            ON ldmc.license_distribution_method_id = ldm.license_distribution_method_id
        LEFT JOIN dbo.license_key lky
            ON lky.license_id = lk.license_id
        LEFT JOIN @product_term pt
            ON pt.license_id = lk.license_id
			AND pt.product_term IS NOT null
        LEFT JOIN dbo.amazon_account aa
            ON aa.customer_id = l.customer_id
        LEFT JOIN dbo.amazon_subscription asu
            ON asu.amazon_account_id = aa.amazon_account_id
               AND asu.license_id = l.license_id
        LEFT JOIN dbo.amazon_subscription_status ass
            ON ass.amazon_subscription_status_id = asu.amazon_subscription_status_id
        LEFT JOIN dbo.customer_email ce
            ON ce.customer_id = l.customer_id
               AND ce.email_status_id = 1
        LEFT JOIN dbo.safe_account_user_customer sauc
            ON sauc.customer_id = ce.customer_id
        LEFT JOIN dbo.allstate_registration_status ars
            ON ars.allstate_registration_status_id = (CASE
                                                          WHEN ISNULL(CONCAT(@startdate, @enddate), '') <> ''
                                                               AND sauc.allstate_registration_status_id IS NULL
                                                               AND
                                                               (
           
                                                        EXISTS
                                                                   (
                                                                       SELECT 1
                                                                       FROM @allstate_premium_category AS apc
                                                                       WHERE apc.license_category_id = p.license_category_id
                                                                   )
                                                                   OR EXISTS
                                                                      (
                                                                          SELECT 1
                                                                          FROM @allstate_addon_category AS apc
                                                                          WHERE apc.license_category_id = p.license_category_id
                                                                      )
                                                               ) THEN
                                                              0
                                                          WHEN
                                                          (
                                                              sauc.allstate_registration_status_id IS NULL
                                                              AND
                                                              (
                                                                  @addon_exists = 1
                                                                  OR p.license_category_id IN
                                                                     (
                                                                         SELECT license_category_id FROM @allstate_premium_category
                                                                     )
                                                              )
                                                          ) THEN
                                                              0
                                                          ELSE
                                                              sauc.allstate_registration_status_id
                                                      END
                                                     ) -- only translate NULL if an Allsate product or Allstate add-on has been purchased

        LEFT JOIN dbo.customer c
            ON c.customer_id = l.customer_id
        LEFT JOIN dbo.customer_address ca
            ON ca.customer_id = c.customer_id
               AND ca.address_type_id = 1 -- bill-to
               AND ca.address_status_id = 1 -- active
        LEFT JOIN dbo.lu_countries lu
            ON lu.country_id = ca.country_id
    ORDER BY p.license_category_id;

    IF @@rowcount > 0
    BEGIN
        SELECT @message = 'Success';
    END;

END TRY
BEGIN CATCH
    DECLARE @dbname NVARCHAR(128);

    SET @dbname = DB_NAME();

    EXEC dbo.usp_LogError @ErrorDB = @dbname;
END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_select_keycodes_by_email]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_safe_account_select_keycodes_by_email]
(    
	@customer_email varchar(250)
	,@input_json nvarchar(1000) = NULL
)

/*
    DATE        AUTHOR      REMARKS
    2022-08-15  jberry      Initial creation
    2022-09-12  jberry      Made change to return key codes if they are WSAP or WSID but do not have user guid
    2023-08-03  jberry      ECOM-1642 - Added support for additional Allstate license categories for WSID and WSAP
    2024-05-28  spatil6     ECOM-4313 - Added product_term,license_key
    2024-09-03  jberry      ECOM-5482: Add WSAIA to list of Allstate premium products
    2024-12-04	jberry      D-4230626: Added keycode alias to @registered_keycodes variable table
	2026-05-27  psatish		US-5427922 Added customer_id to the @registered_keycodes table, as it was added in the [usp_safe_account_select_registered_keycodes] procedure
    DESCRIPTION
    Returns active keycodes for customer accounts that have purchased an Allstate product
    
*/

AS
SET NOCOUNT ON;

   begin try

	declare @safe_account_user_guid varchar(40)
		, @transaction_user varchar(100)
		,@rowcount int

	-- get license category lists for webroot premium and allstate add-on
	declare @allstate_premium_category table (
		license_category_id int,
		license_category_name varchar(10)
        );
	insert into @allstate_premium_category(license_category_id)
	select license_category_id
	from license_category
	where license_category_name in ('WSAP','WSAPF','WSAIA')

	declare @allstate_addon_category table (
	license_category_id int
        );
	insert into @allstate_addon_category(license_category_id)
	select license_category_id
	from license_category
	where license_category_name in ('WSID','WSIDP','WSIDPF')

        if isjson(@input_json) = 1 and @customer_email is null
			begin
				select @customer_email = isnull(j.customer_email, '')
					, @transaction_user = j.transaction_user
				from openjson(@input_json) 
					with (customer_email varchar(250) '$.customer_email'
						, transaction_user varchar(100) '$.transaction_user') j
			end
			
		-- get @safe_account_user_guid
		select @safe_account_user_guid  = sauc.safe_account_user_guid
		from dbo.customer cu
		inner join dbo.customer_email ce
			on ce.customer_id = cu.customer_id
		inner join dbo.safe_account_user_customer sauc
			on sauc.customer_id = ce.customer_id
		where ce.customer_email = @customer_email
		
		-- get keycodes
		declare @registered_keycodes table (item_id	int, license_category_id int, license_category_name	varchar(10), license_category_description varchar(50), license_seats int,
						storage_gb int, license_keycode_type_id	int, license_attribute_id int, license_attribute_description varchar(100), license_attribute_license_value int,
						license_attribute_license_value_description	varchar(250),start_date	date,expiration_date date,category_type_id int,category_type_name varchar(250),
						item_hierarchy_name	varchar(250), license_status_description varchar(250), keycode varchar(250), license_autorenewal_value	int, license_distribution_method_code char(4),
						license_distribution_method_name varchar(100), customer_email varchar(100),first_name nvarchar(255), last_name nvarchar(255), address_1	nvarchar(255), address_2 nvarchar(255),
						city nvarchar(250),state nvarchar(32), postal_code varchar(250), country_id int, country varchar(2), safe_account_user_guid	varchar(40), allstate_registration_status_id int,
						allstate_registration_status nvarchar(255), credit_card_type varchar(40), credit_card_last_four varchar(40), credit_card_expiration	varchar(40), amazon_subscription_key nvarchar(255),
						amazon_subscription_status_name	nvarchar(255),product_term INT,licen
se_key UNIQUEIDENTIFIER, keycode_alias VARCHAR(40), customer_id INT)
		
		insert into @registered_keycodes
		exec usp_safe_account_select_registered_keycodes @safe_account_user_guid = @safe_account_user_guid
				
		select @rowcount = count(*) from @registered_keycodes

		--return keycodes
	
		if @rowcount = 0
			begin

				-- return key codes if they are realted to an Allstate license category but do not have user guid
				select distinct 
					p.license_category_name
					, p.license_category_id
					, p.license_status_description
					, p.keycode
					, p.expiration_date
					, s.safe_account_user_guid   --safe_account_user_guid
					, null as allstate_registration_status_id
					,null as country
				from dbo.customer_email ce
				inner join dbo.customer_order co 
					on co.customer_id = ce.customer_id
				inner join dbo.order_item oi 
					on oi.order_header_id = co.order_header_id
				inner join dbo.order_item_license oil
					on oil.order_item_id = oi.order_item_id
				left join dbo.safe_account_user_customer s 
					on s.customer_id = ce.customer_id
				cross apply dbo.fn_license_select_license_profile(oil.license_id) p 
				where ce.customer_email = @customer_email
				and s.safe_account_user_guid is null
				and (p.license_category_id in (select license_category_id from @allstate_addon_category) 
					or p.license_category_id in (select license_category_id from @allstate_premium_category))
			end
		else 
			begin

				-- return key codes if they are WSAP or WSID, have a safe account and allstate_registration_status_id <> 2 (deleted)
				select license_category_name
					,license_category_id
					,license_status_description
					,keycode
					,expiration_date
					,safe_account_user_guid
					,allstate_registration_status_id
					,country
				from @registered_keycodes
				where allstate_registration_status_id <> 2
				and (license_category_id in (select license_category_id from @allstate_addon_category) 
					or license_category_id in (select license_category_id from @allstate_premium_category))
			end

    end try

    begin catch
        declare @dbname nvarchar(128);

        set @dbname = db_name();

        exec dbo.usp_LogError @ErrorDB = @dbname;
    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_select_registered_keycodes]
-- =============================================================================

CREATE PROCEDURE  [dbo].[usp_safe_account_select_registered_keycodes]
(@safe_account_user_guid VARCHAR(40))

/*	
	DATE		AUTHOR		REMARKS
	2021-02-01	abelenkiy	Initial creation
	2021-03-18	abelenkiy	Added 'where' to statement and license_distribution_method_code to return
	2021-04-23	abelenkiy	Added RTRIM to card_type_description
	2021-06-15	abelenkiy	Selecting payment details only for most recent payment 
	2021-06-24	abelenkiy	Added Amazon license info to output
	2022-07-26	gblandford	AIP-11: Collect additional PII info:
								First Name, Last Name
								Street Address, City, State, Postal Code
								Country
							Added schema to objects
	2022-07-28	gblandford	AIP-39: Allow for return of multiple keycodes when passing order_header_token
									(WSA) license first
									Added Allstate registration status to output
	2022-08-04	gblandford	AIP-52:	For Allstate, translate NULL registration status to 0 (Unregistered) only if
							webroot premium is purchased (WSAP) or if add-on (WSID) is purchased across the same order_header_token (oht)
							regardless of whether we are returning single keycode or all for the oht
	2022-08-07	gblandford	AIP-52: Remove start_date & expiration_date juggle
	2023-08-14	jberry		ECOM-1642: Added support for additional Allstate license categories for WSID and WSAP
	2024-05-28	spatil6		ECOM-4313: Add product_term,license_key in existing api
	2024-09-03	jberry		ECOM-5486:  Refactoring:
									     Replace CTEs with temp tables
									     Remove case logic from where statements and joins
									     Add SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED clause
							ECOM-5482:	BestBuy Changes:
										Changed product term for S2 subscriptions to properly indicate the term based on plan sku subscription days and license expiration duration
										Add WSAIA to list of Allstate premium products
	2024-12-04	jberry		D-4230626: Added keycode alias to return select
	2026-05-27  psatish		US-5427922 Added customer_id to the #account_registration table and included in the resultset
	DESCRIPTION
	Returns all licenses registered to safe account
	
	DEPENDENCY
	[dbo].[usp_safe_account_select_keycodes_by_email]

	
*/

AS
SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

BEGIN TRY

    DECLARE @license_list TABLE
    (
        license_id INT,
        customer_id INT,
        license_distribution_method_id INT
    );

    DECLARE @product_term TABLE
    (
        license_id INT,
        product_term INT
    );

	DROP TABLE IF EXISTS #product_term_details
	CREATE TABLE #product_term_details
	(
        license_id INT,
        order_product_term INT,
		subscription_product_term INT,
        bulk_key_product_term INT,
        distribution_class VARCHAR(50)
	);

	DROP TABLE IF EXISTS #most_recent_order;
	CREATE TABLE #most_recent_order
	(
		license_id INT,
		license_distribution_method_id INT,
		order_header_id INT
	);

	DROP TABLE IF EXISTS #cc_info
	CREATE TABLE #cc_info
	(
	credit_card_type VARCHAR(100),
	credit_card_last_four VARCHAR(10),
	credit_card_expiration VARCHAR(10),
	license_id INT NOT NULL,
	row_num INT
	)

	DROP TABLE IF EXISTS #orders
	CREATE TABLE #orders
	(
	order_header_id INT
	);

	DROP TABLE IF EXISTS #account_registration;
	CREATE TABLE #account_registration
	(
		license_id INT,
		license_category_id TINYINT,
		customer_email VARCHAR(100),
		first_name NVARCHAR(225),
		last_name NVARCHAR(225),
		address_1 NVARCHAR(255),
		address_2 NVARCHAR(255),
		city NVARCHAR(130),
		state NVARCHAR(2),
		postal_code NVARCHAR(32),
		country_id SMALLINT,
		country VARCHAR(2),
		safe_account_user_guid UNIQUEIDENTIFIER,
		allstate_registration_s
tatus_id TINYINT,
		allstate_registration_status VARCHAR(20),
		customer_id INT
	);

    DECLARE @APP_CONFIG TABLE
    (
        app_config_name NVARCHAR(50),
        [key] NVARCHAR(50),
        [value] NVARCHAR(MAX)
    );
    INSERT INTO @APP_CONFIG
    (
        app_config_name,
        [key],
        value
    )
    SELECT f.app_config_name,
           f.[key],
           f.[value]
    FROM [dbo].[fn_app_config_select_key_values]('S2_DISTRIBUTION_CLASS_NAME', 'GENERAL') f;
    DECLARE @customer_id INT;

    SELECT @customer_id = sauc.customer_id
    FROM dbo.safe_account_user_customer sauc
    WHERE sauc.safe_account_user_guid = @safe_account_user_guid;

    INSERT INTO @license_list
    (
        license_id,
        customer_id,
        license_distribution_method_id
    )
    SELECT l.license_id,
           l.customer_id,
           l.license_distribution_method_id
    FROM dbo.license l
    WHERE l.customer_id = @customer_id
          AND l.license_distribution_method_id <> 919; --fraud

    -- get license category lists for webroot premium and allstate add-on
    DECLARE @allstate_premium_category TABLE
    (
        license_category_id INT,
        license_category_name VARCHAR(10)
    );
    INSERT INTO @allstate_premium_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSAP', 'WSAPF','WSAIA');

    DECLARE @allstate_addon_category TABLE
    (
        license_category_id INT
    );
    INSERT INTO @allstate_addon_category
    (
        license_category_id
    )
    SELECT license_category_id
    FROM license_category
    WHERE license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' );


    -- check if we have an allstate add-on
    DECLARE @addon_exists INT = 0;

	INSERT into	#orders
	(
	    order_header_id
	)
	SELECT oh.order_header_id
	FROM dbo.order_header oh
		INNER JOIN dbo.customer_order co
			ON co.order_header_id = oh.order_header_id
		INNER JOIN dbo.order_item oi
			ON oi.order_header_id = oh.order_header_id
		INNER JOIN dbo.order_item_license oil
			ON oil.order_item_id = oi.order_item_id
		INNER JOIN @license_list ll
			ON ll.license_id = oil.license_id
		INNER JOIN dbo.license_category_license lcl
			ON lcl.license_id = ll.license_id
		INNER JOIN @allstate_addon_category aac
			ON aac.license_category_id = lcl.license_category_id;

    IF EXISTS
    (
     SELECT 1 FROM #orders
    )
    BEGIN
        SET @addon_exists = 1;
    END

	-- Get Most recent order
	INSERT INTO #most_recent_order
	(
		license_id,
		license_distribution_method_id,
		order_header_id
	)
	SELECT lk.license_id,
		   lk.license_distribution_method_id,
		   MAX(oi.order_header_id) AS order_header_id
	FROM @license_list lk
		LEFT JOIN dbo.order_item_license oil
			ON oil.license_id = lk.license_id
		LEFT JOIN dbo.order_item oi
			ON oi.order_item_id = oil.order_item_id
	GROUP BY lk.license_id,
			 lk.license_distribution_method_id;

    -- Get Product_term    
    INSERT INTO #product_term_details
	(
	    license_id,
	    order_product_term,
	    subscription_product_term,
	    bulk_key_product_term,
	    distribution_class
	)
	SELECT DISTINCT
		a.license_id,
		py.years,
		CASE
			WHEN sp.subscription_days < 365
				AND (DATEDIFF(dd, s.start_date, s.expiration_date) + 1) < 365 THEN
				0
			WHEN sp.subscription_days >= 365 THEN
				sp.subscription_days / 365
			ELSE
				1
		END,
		py1.years,
		dc.distribution_class
	FROM #most_recent_order a
	LEFT JOIN dbo.order_item oi1
		ON oi1.order_header_id = a.order_header_id
	LEFT JOIN dbo.order_item_license ol
		ON ol.license_id = a.license_id
			AND ol.order_item_id = oi1.order_item_id
			AND ol.license_id IS NOT NULL
	LEFT JOIN dbo.license_distribution_method_channel lmch
		ON lmch.license_distribution_method_id = a.license_distribution_method_id
	LEFT JOIN d
bo.distribution_class dc
		ON dc.distribution_class_id = lmch.distribution_class_id
	LEFT JOIN dbo.product_years py
		ON py.product_id = oi1.product_id
	LEFT JOIN dbo.license ls
		ON ls.license_id = a.license_id
	LEFT JOIN dbo.subscription s
		ON s.license_id = ls.license_id
	LEFT JOIN dbo.subscription_plan_sku sp
		ON sp.plan_sku = s.plan_sku
	LEFT JOIN dbo.license_bulk_load_license lbl
		ON lbl.license_id = a.license_id
	LEFT JOIN dbo.product_years py1
		ON py1.product_id = lbl.product_id;
		
	INSERT @product_term
    (
        license_id,
        product_term
    )
    SELECT pt.license_id,
           CASE
               WHEN pt.subscription_product_term IS NOT NULL
                    AND ap.[key] IS NOT NULL then
                   pt.subscription_product_term
               WHEN pt.subscription_product_term IS NULL
                    AND ap.[key] IS NOT NULL THEN 
                   1
               WHEN pt.order_product_term IS NOT NULL
			   AND pt.order_product_term <> 0
			   THEN
                   pt.order_product_term     
               ELSE
                   pt.bulk_key_product_term
           END
    FROM #product_term_details pt
        LEFT JOIN @APP_CONFIG ap
            ON ap.[key] = pt.distribution_class;

	INSERT INTO #cc_info
	(
	    credit_card_type,
	    credit_card_last_four,
	    credit_card_expiration,
	    license_id,
	    row_num
	)
    SELECT CASE
                WHEN ct.card_type_description IS NOT NULL THEN
                    RTRIM(ct.card_type_description)
                ELSE
                    CASE
                        WHEN payment_method_name IN ( 'Konbini', 'Paypal' ) THEN
                            payment_method_name
                    END
            END credit_card_type,
            RIGHT(pa.account_number, 4) credit_card_last_four,
            RIGHT('000' + CONVERT(VARCHAR(2), pa.expiration_month), 2) + '/'
            + CONVERT(VARCHAR(4), pa.expiration_year) credit_card_expiration,
            oil.license_id,
            ROW_NUMBER() OVER (PARTITION BY ll.license_id ORDER BY oh.order_header_id DESC) AS row_num
    FROM @license_list ll
        INNER JOIN dbo.order_item_license oil
            ON oil.license_id = ll.license_id
        INNER JOIN dbo.order_item oi
            ON oi.order_item_id = oil.order_item_id
        INNER JOIN dbo.order_header oh
            ON oh.order_header_id = oi.order_header_id
                AND oh.order_status_id IN ( 1, 2 )
        INNER JOIN dbo.order_payment_header oph
            ON oh.order_header_id = oph.order_header_id
        INNER JOIN dbo.payment_header ph
            ON ph.payment_header_id = oph.payment_header_id
        INNER JOIN dbo.payment_account pa
            ON pa.payment_header_id = ph.payment_header_id
        LEFT JOIN dbo.card_type ct
            ON ct.card_type_id = pa.card_type_id
        LEFT JOIN dbo.payment_method pm
            ON pm.payment_method_id = ph.payment_method_id

	--get account registration details
	INSERT INTO #account_registration
	(
		license_id,
		license_category_id,
		customer_email,
		first_name,
		last_name,
		address_1,
		address_2,
		city,
		state,
		postal_code,
		country_id,
		country,
		safe_account_user_guid,
		allstate_registration_status_id,
		allstate_registration_status,
		customer_id
	)	
	SELECT DISTINCT
			lk.license_id,
			lcl.license_category_id,
			ce.customer_email,
			c.first_name,
			c.last_name,
			ca.address_1,
			ca.address_2,
			ca.city,
			ca.state,
			ca.postal_code,
			ca.country_id,
			lu.iso AS country, -- iso2
			sauc.safe_account_user_guid,
			ars.allstate_registration_status_id,
			ars.allstate_registration_status,
			l.customer_id
	FROM @license_list lk
		INNER JOIN dbo.license l 
			ON l.license_id = lk.license_id
		INNER JOIN dbo.license_category_license lcl
			ON lcl.license_id = l.license_id
		LEFT JOIN dbo.customer_email ce
			ON ce.cust
omer_id = l.customer_id
				AND ce.email_status_id = 1
		LEFT JOIN dbo.safe_account_user_customer sauc
			ON sauc.customer_id = ce.customer_id   
		LEFT JOIN dbo.customer c
			ON c.customer_id = l.customer_id
		LEFT JOIN dbo.customer_address ca
			ON ca.customer_id = c.customer_id
				AND ca.address_type_id = 1 -- bill-to
				AND ca.address_status_id = 1 -- active
		LEFT JOIN dbo.lu_countries lu
			ON lu.country_id = ca.country_id
		LEFT JOIN dbo.allstate_registration_status ars
			ON ars.allstate_registration_status_id = sauc.allstate_registration_status_id

		UPDATE r
		SET r.allstate_registration_status_id = 
			CASE 
			WHEN sauc.allstate_registration_status_id IS NULL
			AND
			(
				EXISTS
				(
					SELECT 1
					FROM @allstate_premium_category AS apc
					WHERE apc.license_category_id = r.license_category_id
				)
				OR EXISTS
					(
						SELECT 1
						FROM @allstate_addon_category AS apc
						WHERE apc.license_category_id = r.license_category_id
					)
				OR @addon_exists = 1
			) THEN
			0
			ELSE
				sauc.allstate_registration_status_id
			END
		FROM #account_registration r
		LEFT JOIN dbo.safe_account_user_customer sauc
					ON sauc.safe_account_user_guid = r.safe_account_user_guid

		UPDATE r
		SET allstate_registration_status = ars.allstate_registration_status
		FROM #account_registration r
		JOIN dbo.allstate_registration_status ars ON ars.allstate_registration_status_id = r.allstate_registration_status_id

	--return
   SELECT p.item_id,
       p.license_category_id,
       p.license_category_name,
       p.license_category_description,
       p.license_seats,
       p.storage_gb,
       p.license_keycode_type_id,
       p.license_attribute_id,
       p.license_attribute_description,
       p.license_attribute_license_value,
       p.license_attribute_license_value_description,
       p.start_date,
       p.expiration_date,
       p.category_type_id,
       p.category_type_name,
       p.item_hierarchy_name,
       p.license_status_description,
       p.keycode,
       p.license_autorenewal_value,
       ldm.license_distribution_method_code,
       ldm.license_distribution_method_name,
       r.customer_email,
       r.first_name,
       r.last_name,
       r.address_1,
       r.address_2,
       r.city,
       r.state, --
       r.postal_code,
       r.country_id,
       r.country,
       @safe_account_user_guid AS safe_account_user_guid,
       r.allstate_registration_status_id,
       r.allstate_registration_status,
       cc.credit_card_type,
       cc.credit_card_last_four,
       cc.credit_card_expiration,
       asu.amazon_subscription_key,
       ass.amazon_subscription_status_name,
       pt.product_term,
       lk.license_key,
       lka.keycode_alias,
	   r.customer_id
	FROM @license_list ll
		CROSS APPLY dbo.fn_license_select_license_profile(ll.license_id) p
		INNER JOIN dbo.license_distribution_method ldm
			ON ldm.license_distribution_method_id = ll.license_distribution_method_id
		LEFT JOIN #cc_info cc
			ON cc.license_id = ll.license_id
			   AND cc.row_num = 1
		LEFT JOIN @product_term AS pt
			ON pt.license_id = ll.license_id
			   AND pt.product_term IS NOT NULL
		LEFT JOIN dbo.license_key AS lk
			ON ll.license_id = lk.license_id
		LEFT JOIN dbo.license_keycode_alias lka
			ON lka.license_id = ll.license_id
		LEFT JOIN dbo.amazon_account aa
			ON aa.customer_id = ll.customer_id
		LEFT JOIN dbo.amazon_subscription asu
			ON asu.amazon_account_id = aa.amazon_account_id
			   AND asu.license_id = ll.license_id
		LEFT JOIN dbo.amazon_subscription_status ass
			ON ass.amazon_subscription_status_id = asu.amazon_subscription_status_id
		LEFT JOIN #account_registration r
			ON r.license_id = lk.license_id
			   AND r.license_category_id = p.license_category_id;
        
END TRY
BEGIN CATCH
    DECLARE @dbname NVARCHAR(128);

    SET @dbname = DB_NAME();

    EXEC usp_LogErro
r @ErrorDB = @dbname;
END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_update_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_safe_account_update_account]

(@safe_account_user_guid VARCHAR(40) = ''
, @keycode VARCHAR(40) = ''
, @account_email VARCHAR(100) = ''
, @safe_account_register_keycode_json NVARCHAR(1000) = ''
, @amazon_redirect_url NVARCHAR(200) = ''
, @amazon_request_id NVARCHAR(40) = ''
, @message VARCHAR(2000) OUTPUT
, @response_code INT OUTPUT
)

/*	
	DATE		AUTHOR			REMARKS
	2021-01-26	abelenkiy		Initial creation
	2021-05-14	abelenkiy		Refactored to log JSON and use other Safe procs for validation
	2021-06-25	abelenkiy		Refactored to allow keycode override (no keycode requirement, currently only for Amazon flow) 
	2022-02-15	abelenkiy		Extended error handling to prevent bug where new customer record being inserted when account-link 
								sends different email than already on account with link request (RED-126)
	2022-09-03	gblandford		AIP-11: Need to capture additional columns returned from usp_safe_account_select_customer_keycode
	2024-04-08	rambasana		ECOM-4190: added license_key and product_term columns returned from usp_safe_account_select_customer_keycode
	2024-12-04	jberry			D-4230626: Added keycode alias to @registered_keycodes variable table
	2025-01-20  psatish			IM-4395397 Modify the IF condition to avoid returning a subquery if there is more than one entry in the @keycode_lookup table.
	2026-05-27  psatish			US-5427922 Added customer_id to the @keycode_lookup table, as it was added in the usp_safe_account_select_customer_keycode procedure
	DESCRIPTION
	This is used by consumer-api.webroot.com

	DEPENDENCY
	usp_safe_account_update_account_info
	usp_amazon_insert_amazon_account
	usp_customer_insert_customer_service
*/

AS
SET NOCOUNT ON;

    begin try
		declare @license_customer_id int, @customer_email varchar(100), @license_id int, @safe_customer_id int
		, @customer_service_json nvarchar(500), @safe_account_user_customer_id int, @safe_account_user_customer_json_id int
		
		declare @keycode_lookup table 
		(	item_id int
		  , license_category_id tinyint
		  , license_category_name varchar(10)
		  , license_category_description varchar(50)
		  , license_seats int
		  , storage_gb int
		  , license_keycode_type_id int
		  , license_attribute_id int
		  , license_attribute_description varchar(100)
		  , license_attribute_license_value int
		  , license_attribute_license_value_description varchar(50)
		  , start_date date
		  , expiration_date date
		  , category_type_id tinyint
		  , category_type_name varchar(50)
		  , item_hierarchy_name varchar(50)
		  , license_status_description varchar(20)
		  , keycode varchar(50)
		  , license_key uniqueidentifier
		  , product_term int
		  , license_autorenewal_value tinyint
		  , license_distribution_method_code char(4)
		  , license_distribution_method_name varchar(100)
		  , customer_email varchar(100)
		  , first_name varchar(255)
		  , last_name varchar(255)
		  , address_1 varchar(255)
 		  , address_2 varchar(255)
		  , city varchar(130)
		  , state varchar(3)
		  , postal_code varchar(32)
		  , country_id smallint
		  , country varchar(10)
		  , safe_account_user_guid uniqueidentifier
		  , allstate_registration_status_id smallint
		  , allstate_registration_status varchar(50)         
		  , amazon_subscription_key varchar(50)
		  , amazon_subscription_status_name varchar(50)
		  , modified_date DATETIME
		  , keycode_alias VARCHAR(40)
		  , customer_id INT
		)

        if isjson(@safe_account_register_keycode_json) = 1
            begin
                select @keycode = isnull(dbo.fn_RemoveDashes(j.keycode), '')
					, @account_email = isnull(j.account_email, '')
					, @safe_account_user_guid = isnull(j.safe_account_user_guid, '')
              
  from openjson(@safe_account_register_keycode_json) 
					with (keycode varchar(40) '$.keycode'
						, account_email varchar(100) '$.account_email'
						, safe_account_user_guid varchar(40) '$.safe_account_user_guid'
						, amazon_redirect_url varchar(200) '$.amazon_redirect_url'
						, amazon_request_id varchar(40) '$.amazon_request_id') j
            end
		else 
			begin
				select @safe_account_register_keycode_json = (select @keycode as [keycode]
																	, @account_email as [account_email]
																	, @safe_account_user_guid as [safe_account_user_guid]
																	, @amazon_redirect_url as [amazon_redirect_url]
																	, @amazon_request_id as [amazon_request_id]
																for json path, without_array_wrapper)
			end

		-- insert json to log
		insert into dbo.safe_account_user_customer_json (safe_account_user_customer_json)
		select @safe_account_register_keycode_json

		select @safe_account_user_customer_json_id = scope_identity()

		-- validate inputs: email and Safe GUID are required, keycode is required unless it's an Amazon request
		if (@account_email = '' or @safe_account_user_guid = '') or (@keycode = '' and @amazon_request_id = '')
			begin
				select @message = 'Required parameters not provided' goto log_response
			end
		-- if Amazon, skip keycode validation
		else if @amazon_request_id <> ''
			begin
				goto keycode_requirement_override
			end
		else
			begin

				insert into @keycode_lookup (item_id, license_category_id, license_category_name, license_category_description, license_seats, storage_gb
				                             , license_keycode_type_id, license_attribute_id, license_attribute_description, license_attribute_license_value
				                             , license_attribute_license_value_description, start_date, expiration_date, category_type_id, category_type_name
				                             , item_hierarchy_name, license_status_description, keycode, license_key, product_term, license_autorenewal_value 
											 , license_distribution_method_code
				                             , license_distribution_method_name, customer_email, first_name, last_name, address_1, address_2, city, state, postal_code
											 , country_id, country
											 , safe_account_user_guid
											 , allstate_registration_status_id , allstate_registration_status 
											 , amazon_subscription_key, amazon_subscription_status_name, modified_date, keycode_alias, customer_id)
				                            
				exec dbo.usp_safe_account_select_customer_keycode @keycode = @keycode
				  , @message = @message output
				  , @response_code = @response_code OUTPUT

				-- log failure and return early if one of the errors in the select procedure was hit
				if @message <> 'Success'
					begin 
						goto log_response
					end

				if exists (select 1 from @keycode_lookup where safe_account_user_guid is not null)
				begin
					IF EXISTS
					(
						SELECT 1
						FROM @keycode_lookup
						WHERE safe_account_user_guid = @safe_account_user_guid
					)
					BEGIN
						SELECT @message = 'Keycode already associated with customer'
						GOTO log_response
					END
					ELSE
					BEGIN
						SELECT @message = 'Keycode already registered to different customer'
						GOTO log_response
					END
				END
				else if @safe_account_user_guid <> ''
				begin
					if @account_email <> (select sauce.email_address
										from dbo.safe_account_user_customer sauc 
											inner join dbo.safe_account_user_customer_email sauce 
												on sauce.safe_account_user_customer_id = sauc.safe_account_user_customer_id
													and sauce.email_status_id = 1
										where sauc.safe_account_user_guid = @safe_account_user_guid)
						begin
							select @message = 'Keycode already registered to different customer' goto log_response
						end
					end

			end

		select @license_id = l.license_
id, @customer_email = kl.customer_email
			, @license_customer_id = l.customer_id
		from @keycode_lookup kl
			inner join dbo.license l on l.keycode = kl.keycode

		if @license_customer_id is not null
			begin

				if @account_email <> @customer_email 
					begin
						select @message = 'Keycode already registered to different customer' 
						goto log_response
					end
			end

		-- pick up on Amazon flow here
		keycode_requirement_override:

		select @customer_service_json = (select @license_customer_id as [customer.customer_id]
												, @account_email as [customer.customer_email]
												, @safe_account_user_guid as [customer.safe_account_user_guid]
												, 'usp_safe_account_update_account' as [transaction_user]
										for json path, without_array_wrapper)

		exec dbo.usp_safe_account_update_account_info
		    @safe_account_update_json = @customer_service_json
		  , @message = @message output


		if @message = 'Input email already tied to different Safe Account'
			begin
				goto log_response
			end
		if @message = 'Customer information updated'
			begin
				select @safe_customer_id = sauc.customer_id
				from dbo.safe_account_user_customer sauc
				where sauc.safe_account_user_guid = @safe_account_user_guid

				-- every case other than keycode override will hit this
				if @license_id is not null
					begin
						if @safe_customer_id <> @license_customer_id
							begin
								select @message = 'Duplicate customer in ecommerce' goto log_response
							end

						update dbo.license
						set customer_id = @safe_customer_id
						where license_id = @license_id

						select @message = 'Keycode associated with customer' goto log_response
					end
				else
					begin
						if @amazon_request_id is not null
							begin 
								exec dbo.usp_amazon_insert_amazon_account @customer_id = @safe_customer_id, @return_amazon_account_key = 0
							end

						select @message = 'Keycode override - Safe Account already exists' goto log_response
					end
			end

		if @message = 'Safe Account User GUID does not exist'
			begin
				if exists (select 1 
							from dbo.safe_account_user_customer_email sauce 
							where sauce.email_address = @account_email
								and sauce.email_status_id = 1)
					begin
						select @message = 'Input email already tied to different Safe Account' goto log_response
					end

				if @license_customer_id is null
					begin
						exec dbo.usp_customer_insert_customer_service
						   @customer_id = @license_customer_id output
						  , @input_json = @customer_service_json
					end

				insert dbo.safe_account_user_customer (safe_account_user_guid, customer_id)
				select @safe_account_user_guid, @license_customer_id

				select @safe_account_user_customer_id = scope_identity()

				insert dbo.safe_account_user_customer_email (safe_account_user_customer_id, email_address, email_status_id)
				select @safe_account_user_customer_id, @account_email, 1

				if @license_id is not null
					begin
						update dbo.license
						set customer_id = @license_customer_id
						where license_id = @license_id
					end
				else
					begin
						if @amazon_request_id is not null
							begin 
								exec dbo.usp_amazon_insert_amazon_account @customer_id = @license_customer_id, @return_amazon_account_key = 0
							end

						select @message = 'Keycode override - New Safe Account created' goto log_response
					end

				select @message = 'Keycode associated with customer' goto log_response

			end

	log_response:

	update dbo.safe_account_user_customer_json
	set safe_account_user_customer_json_message_id = m.safe_account_user_customer_json_message_id
	from dbo.safe_account_user_customer_json_message m 
	where m.safe_account_user_customer_json_message = @message
		and safe_account_user_customer_json.safe_account_user_customer_json_id = @safe_account_user_customer_json_id

    end try
    begi
n catch
		set @message = 'safe_account_user_customer_json_id = ' + convert(varchar(20), @safe_account_user_customer_json_id) 
			+ ': ' + error_message()

		insert into dbo.DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()

        declare @dbname nvarchar(128);
        set @dbname = db_name();
        exec dbo.usp_LogError @ErrorDB = @dbname;
    end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_update_account_info]
-- =============================================================================

create procedure [dbo].[usp_safe_account_update_account_info]

( @safe_account_update_json nvarchar(1000) = ''
, @message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2021-04-26	abelenkiy	Initial creation

	DESCRIPTION
	Updates customer information for existing Safe Account. Called by update info API.
	

*/

as
set nocount on;

    begin try
		declare @customer_id int, @input_email varchar(100), @safe_account_user_email varchar(100)
		, @safe_account_user_guid varchar(40), @safe_account_user_customer_id int
		, @transaction_user varchar(100)

        if isjson(@safe_account_update_json) = 0
			begin
				select @message = 'Invalid JSON provided' return
			end
		else
            begin
                select @input_email = isnull(j.customer_email, '')
					, @safe_account_user_guid = isnull(j.safe_account_user_guid, '')
					, @transaction_user = j.transaction_user
                from openjson(@safe_account_update_json) 
					with (customer_email varchar(100) '$.customer.customer_email'
						, safe_account_user_guid varchar(40) '$.customer.safe_account_user_guid'
						, transaction_user varchar(100) '$.transaction_user') j

				if @input_email = '' or @safe_account_user_guid = ''
					begin
						select @message = 'Required parameters not provided' return
					end
            end

		if isnull(@transaction_user, '') = ''
			begin
				select @transaction_user = suser_name()

				select @safe_account_update_json = json_modify(@safe_account_update_json
															, '$.transaction_user', @transaction_user)
			end

		select @customer_id = sauc.customer_id
			, @safe_account_user_email = sauce.email_address
			, @safe_account_user_customer_id = sauc.safe_account_user_customer_id
		from safe_account_user_customer sauc
			inner join safe_account_user_customer_email sauce 
				on sauce.safe_account_user_customer_id = sauc.safe_account_user_customer_id
				and sauce.email_status_id = 1
		where sauc.safe_account_user_guid = @safe_account_user_guid

		if @@rowcount = 0
			begin
				select @message = 'Safe Account User GUID does not exist' return		
			end

		if @input_email <> @safe_account_user_email
			begin
				if exists (select 1 
							from safe_account_user_customer_email sauce 
							where sauce.email_address = @input_email
								and sauce.email_status_id = 1
								and sauce.safe_account_user_customer_id <> @safe_account_user_customer_id)
					begin
						select @message = 'Input email already tied to different Safe Account' return
					end
				if exists (select 1 
							from safe_account_user_customer_email sauce 
							where sauce.email_address = @input_email
								and sauce.email_status_id = 2
								and sauce.safe_account_user_customer_id = @safe_account_user_customer_id)
					begin
						update safe_account_user_customer_email 
						set email_status_id = iif(@input_email = email_address, 1, 2)
							, modified_date = getdate()
							, modified_by = @transaction_user
						where safe_account_user_customer_id = @safe_account_user_customer_id
					end
				else 
					begin
						update safe_account_user_customer_email
						set email_status_id = 2
							, modified_date = getdate()
							, modified_by = @transaction_user
						where safe_account_user_customer_id = @safe_account_user_customer_id

						insert into safe_account_user_customer_email 
							(safe_account_user_customer_id, email_address, email_status_id, modified_by
							, insert_by)
						select @safe_account_user_customer_id, @input_email, 1, @transaction_user
							, @transaction_user
					end
			end

		select @safe_account_update_json = json_modify(@safe_account_update_json, '$.customer.customer_id'
														,
 @customer_id)

		exec usp_customer_insert_customer_service @input_json = @safe_account_update_json

		select @message = 'Customer information updated' return					

    end try
    begin catch
        declare @dbname nvarchar(128);

        set @dbname = db_name();

        exec usp_LogError @ErrorDB = @dbname;
    end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_safe_account_update_registration_status]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_safe_account_update_registration_status] ( 
	@safe_account_update_json NVARCHAR(1000) = ''
	, @message VARCHAR(100) OUTPUT
)

/*	
	DATE		AUTHOR		REMARKS
	2022-07-29	gblandford	Initial creation (AIP-24)
	2022-07-29	jberry		Changed @allstate_registration_status_id variable to type int (AIP-24)
	2025-04-18	jberry		US-4459014 - Populate allstate_registration_date, some minor formatting changes

	DESCRIPTION
	Updates the account registration status (Allstate)

    DEPENDENCY
    Portal API call: consumer api -> /allstate-status

*/

AS
SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @allstate_registration_status_id INT
        , @safe_account_user_guid VARCHAR(40)
        , @safe_account_user_customer_id INT
        , @ALLSTATE_ACTIVE_REGISTRATION_STATUS INT
        , @transaction_user VARCHAR(100)
		
		--app_configs
        SELECT @ALLSTATE_ACTIVE_REGISTRATION_STATUS = f.[key]
        FROM [dbo].[fn_app_config_select_key_values]('ALLSTATE_ACTIVE_REGISTRATION_STATUS', 'ALLSTATE') f;

        DECLARE @S2_ALLSTATE_LICENSE_REGISTRATION TABLE
        (
            license_category_id INT,
            license_category_name VARCHAR(10)
        );
        INSERT INTO @S2_ALLSTATE_LICENSE_REGISTRATION
        (
            license_category_id,
            license_category_name
        )
        SELECT f.[key],
               f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('S2_ALLSTATE_LICENSE_REGISTRATION', 'BBY_S2') f;

        --validations
        IF ISJSON(@safe_account_update_json) = 0
			BEGIN
				SELECT @message = 'Invalid JSON provided' RETURN
			END
		ELSE
            BEGIN
                SELECT @allstate_registration_status_id = ISNULL(j.allstate_registration_status_id, '')
					, @safe_account_user_guid = ISNULL(j.safe_account_user_guid, '')
					, @transaction_user = j.transaction_user
                FROM OPENJSON(@safe_account_update_json) 
					WITH (allstate_registration_status_id INT '$.customer.allstate_registration_status_id'
						, safe_account_user_guid VARCHAR(40) '$.customer.safe_account_user_guid'
						, transaction_user VARCHAR(100) '$.transaction_user') j

				IF @safe_account_user_guid = ''
					BEGIN
						SELECT @message = 'Required parameters not provided' RETURN
					END
            END

		IF ISNULL(@transaction_user, '') = ''
			BEGIN
				SELECT @transaction_user = SUSER_NAME()

				SELECT @safe_account_update_json = JSON_MODIFY(@safe_account_update_json , '$.transaction_user', @transaction_user)
			END

		SELECT @safe_account_user_customer_id = sauc.safe_account_user_customer_id
		FROM dbo.safe_account_user_customer sauc
		WHERE sauc.safe_account_user_guid = @safe_account_user_guid;

		IF @@rowcount = 0
			BEGIN
				SELECT @message = 'Safe Account User GUID does not exist' RETURN
			END

		IF NOT EXISTS(SELECT 1 
                      FROM dbo.allstate_registration_status 
                      WHERE allstate_registration_status_id = @allstate_registration_status_id)
			BEGIN
				SELECT @message = 'Registration status does not exist' RETURN
			END

		IF NOT EXISTS(SELECT 1
                      FROM safe_account_user_customer sauc
                      WHERE sauc.safe_account_user_customer_id = @safe_account_user_customer_id
                        AND ISNULL(sauc.allstate_registration_status_id,0) <> @allstate_registration_status_id)
			BEGIN
				SELECT @message = 'Registration status already exists, nothing to update' RETURN
			END

        --update allstate registration status
        UPDATE sauc
        SET sauc.allstate_registration_status_id = @allstate_registration_status_id,
            sauc.modified_date = GETDATE(),
   
         sauc.modified_by = @transaction_user,
            sauc.allstate_registration_date = CASE
                                              WHEN @allstate_registration_status_id = @ALLSTATE_ACTIVE_REGISTRATION_STATUS 
                                                AND sauc.allstate_registration_date IS NULL THEN GETDATE()
                                              ELSE sauc.allstate_registration_date
                                              END
        FROM dbo.safe_account_user_customer sauc
        WHERE sauc.safe_account_user_customer_id = @safe_account_user_customer_id;
				
        --insert records into sky_update for S2 allstate registrations
           --When processed this will send a call to the BBY RedemptionNotification api with the allstate registration date
           --Only applies to S2 Allstate subscriptions
        INSERT INTO dbo.sky_update (license_id, sky_template_id, sky_update_type_id, process_date)
        SELECT l.license_id,
               16,  --s2_registration
               16,  --s2_registration
               GETDATE()
        FROM dbo.license l
            INNER JOIN dbo.license_category_license lcl
                ON lcl.license_id = l.license_id
            INNER JOIN dbo.subscription s
                ON s.license_id = l.license_id
            INNER JOIN dbo.safe_account_user_customer sauc
                ON l.customer_id = sauc.customer_id
            INNER JOIN dbo.allstate_registration_status ars
                ON ars.allstate_registration_status_id = sauc.allstate_registration_status_id
            INNER JOIN @S2_ALLSTATE_LICENSE_REGISTRATION alc
                ON alc.license_category_id = lcl.license_category_id
        WHERE sauc.safe_account_user_customer_id = @safe_account_user_customer_id
        AND ars.allstate_registration_status_id = @ALLSTATE_ACTIVE_REGISTRATION_STATUS;

        SELECT @message = 'Registration status updated' RETURN

    END TRY
    BEGIN CATCH
        DECLARE @dbname NVARCHAR(128);

        SET @dbname = db_name();

        EXEC dbo.usp_LogError @ErrorDB = @dbname;
    END CATCH;



GO
