-- PROCEDURE: [dbo].[usp_sap_billing_select_current_status]
-- =============================================================================
CREATE procedure [dbo].[usp_sap_billing_select_current_status]
(@sap_account_number int)

/*	
	DATE		AUTHOR		REMARKS
	2021-05-19	abelenkiy	Initial creation.
    2022-13-11  abelenkiy   Updated error handling in catch block

	DESCRIPTION
	Billing portal - Selects current status and balance information for a company.
*/

as
set nocount on;
set transaction isolation level read uncommitted;

begin try

	select cs.sap_account_number
			, cs.party_name
			, cs.currency_code
			, cs.amount_due_total
			, cs.amount_past_due
			, cs.amount_current
			, cs.amount_credits
			, cs.address_line_1
			, cs.address_line_2
			, cs.address_line_3
			, cs.city
			, cs.state
			, cs.zip
			, cs.country
			, cs.tax_information
	from sap_ext_I094_customer_summary cs
	where cs.sap_account_number = @sap_account_number

end try
begin catch

	declare
		@error_severity int = error_severity(), @error_state int = error_state(), @message nvarchar(4000)
	set @message = 'sap_account_number = ' + convert(varchar(20), isnull(@sap_account_number, 'null')) 
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state) with log

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage
		, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message
		, @@servername, db_name(), suser_name()

end catch;



GO
