-- =============================================================================
-- PROCEDURE: [dbo].[usp_select_customer_invoices]
-- =============================================================================



CREATE   PROCEDURE usp_select_customer_invoices
(
	@customer_code varchar(16),
	@product_family varchar(50)
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-06-14	esmart			Initial creation.
	2006-06-14	pwilliams 		changed to use product family (rather than product id)
	2006-06-20 	esmart			Small change to query logic. Add order by

	DESCRIPTION
	select all invoices for a customer and product family
*/

	select distinct i.invoice_code, customer_code, affiliate_code, affiliate_subcode, master_override_affiliate_num, employee_id, promo_code, trial_product_id, wcode1, wcode2, wcode3, distribution_channel_code, distribution_role_code, cd_code, pop_under, page_design_1, page_design_2, page_design_3, referral_source_id, user_ip, order_type_id, amount, purchased_date, modified_date, payment_method_id, payment_authorization_id, invoice_status_id, completed_ship_date, alt_invoice_code, visitorid, coupon_amount, i.last_modified, tax_total, p_rc, p_rsc, p_ac, trx_rc, trx_rsc, trx_ac
	from invoices i
	inner join invoice_items ii
		on i.invoice_code = ii.invoice_code
	inner join products p
		on ii.product_id = p.product_id
	where p.productfamily = @product_family and
		i.customer_code = @customer_code
	order by i.purchased_date desc


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_select_customer_registrations]
-- =============================================================================



CREATE   PROCEDURE usp_select_customer_registrations

(
	@customer_code varchar(16),
	@product_family varchar(50)
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-06-14	esmart			Initial creation.
	2006-06-14	pwilliams		Change to match on product family (rather than product id)


	DESCRIPTION
	Yields the set of product registration by the specified customer for
	specified product family.
*/

	select customer_code, product_id, product_version, major_version, minor_version, initial_install_date, registration_date, product_registration_number, affiliate_code, cd_code, distribution_channel_code, distribution_role_code, master_override_affiliate_num, refer_to_product_code, program_status, build, referral_source_id, visitorid, last_modified, prKeycode, ID, IsKeycodeValid, language_code, location_code
	from product_registrations
	where customer_code = @customer_code and
		product_id in (select product_id 
                                 from products  
                                 where productfamily = @product_family)


