-- PROCEDURE: [dbo].[usp_select_keycode_search]
-- =============================================================================



CREATE  PROCEDURE usp_select_keycode_search

(
	@product_family varchar(50),
	@customer_code varchar(16)
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2006-06-08	esmart			Initial creation
	2006-06-26	esmart			Modify product lookup to use like rather than exact match on product family


	DESCRIPTION
	returns keycodes from a product_family for a customer
*/

	set @product_family = @product_family + '%'

	select k.keycode, 
		k.status_id,
		days_left = 
			case
				when datediff(dd,getdate(),k.expiration_date) < 0 then 0
				else datediff(dd,getdate(),k.expiration_date)
			end,
             	  	k.product_id
	from products p
	inner join keycodes k
		on k.product_id = p.product_id
	where p.ProductFamily like @product_family and
		k.customer_code = @customer_code



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_select_latest_product_version]
-- =============================================================================





CREATE PROCEDURE [dbo].[usp_select_latest_product_version]
	
	(
		@product_id int,
		@operation_code int,
		@operating_system_platform_id int, 
		@operating_system_major_version int, 
		@operating_system_minor_version int
	)
	
	/*	
		DATE		AUTHOR		REMARKS
		2006-05-24	esmart			Initial creation.
		2006-06-29 	esmart			Removed support for null operating system. If no operating system is provided use the latest product version 
							that is support by the upgrade method.
							Removed exception that returns two rows when the upgrade method is manual.
	
	
		DESCRIPTION
		Selects the lastest product version, or versions, that are support for the upgrade method (operation_code) and the operating system.
	*/
	
	AS
	
		set nocount on
	
		declare @operating_system_id int,
			@operating_system_name varchar(50),
			@product_upgrade_method_id int,
			@upgrade_method_description varchar(50),
			@max_product_version_id_operating_system int,
			@max_product_version_id_upgrade_method int,
			@rowcount int
	
		set @rowcount = 1
	
	
	-- 1.)  set operating system id for supplied parameters
	
		select @operating_system_id = operating_system_id, @operating_system_name = operating_system_name
		from operating_system
		where operating_system_platform_id = @operating_system_platform_id and
			operating_system_major_version = @operating_system_major_version and
			operating_system_minor_version = @operating_system_minor_version
		
		--select operating_system_id = @operating_system_id
	
	-- 2.) set product_upgrade_method_id for operation_code
	
		select @product_upgrade_method_id = product_upgrade_method_id, @upgrade_method_description = upgrade_method_description
		from product_upgrade_method
		where operation_code = @operation_code and product_id = @product_id
	
	/*	if @upgrade_method_description = 'Manual'
			begin
			set @rowcount = 2
			end
	*/
		--select upgrade_method_description = @upgrade_method_description
		
	-- 3.) select top product_version based on operating system supplied
	
		select @max_product_version_id_operating_system = 
			(select top 1 v.product_version_id
			from product_versions v
			inner join product_version_operating_system s
				on v.product_version_id = s.product_version_id
			where v.product_id = @product_id  and s.operating_system_id = @operating_system_id and s.support = 1
			order by v.major_version desc, v.minor_version desc, v.start_date desc)
	
		if @operating_system_id is null
			begin
			set @max_product_version_id_operating_system = null 
			
			/*
			-- This logic will return the latest product version that is supported on all supported operating systems
			
			select @max_product_version_id_operating_system = max(product_version_id)
			from product_versions
			where product_id = @product_id and product_version_id in (
				select product_version_id
				from product_version_operating_system
				where support = 1
				group by product_version_id having count(*) >= (select count(*) from operating_system where supported = 1))*/
			end
		
		--select max_product_version_id_operating_system = @max_product_version_id_operating_system
	
	-- 4.) select top product version based on upgrade method
	
		select @max_product_version_id_upgrade_method = 
			(select top 1 v.product_version_id
			from product_versions v
			inner join product_version_product_upgrade_method m
				on v.product_version_id = m.product_version_id
			where v.product_id = @product_id and m.product_upgrade_method_id = @product_upgrade_method_id and m.support = 1
			order by v.major_version desc, v.minor_version desc, v.start_date desc)
	
		--select max_product_version_id_upgrade_method = @max_product_version_id_upgrade_method
	
	
-- 5.) select product version to return. rowcount determines the number of rows to return. is_latest_version determines if the the product_version 
	--	being returned is the latest version for the upgrade method.
	
		set rowcount @rowcount
	
		select major_version, 
			minor_version, 
			release, 
			bld, 
			installer_exe, 
			operating_system_name = 
				case 
					when @operating_system_name is null then dbo.udf_SelectProductVersionOperatingSystems(product_version_id)
					else @operating_system_name
				end,
			is_latest_version = 
				case 
					when @max_product_version_id_operating_system < @max_product_version_id_upgrade_method then 0
					else 1
				end
	--		max_product_version_id_operating_system = @max_product_version_id_operating_system,
	--		max_product_version_id_upgrade_method = @max_product_version_id_upgrade_method
		from product_versions
		where product_version_id in (@max_product_version_id_operating_system,@max_product_version_id_upgrade_method)
		order by major_version, minor_version, start_date
	
		set rowcount 0





GO
