CREATE PROCEDURE [dbo].[usp_select_license_service_bulkload_status]

-- =============================================
-- DATE        AUTHOR            REMARKS
--2025-10-20  vgangatharan    Returns the status of the bulk load file upload for license disable
-- =============================================
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        SELECT license_service_bulk_load_file_id AS Id,
               [file_name] AS [FileName],
               insert_by AS InsertBy,
               insert_date AS InsertDate,
               load_status AS [Status]
        FROM license_service_bulk_load_file
        WHERE insert_date >= DATEADD(MONTH, -1, GETDATE())
        ORDER BY license_service_bulk_load_file_id desc;
    END TRY
    BEGIN CATCH
        DECLARE @DBName sysname = DB_NAME();
        -- Custom error logging procedure
        EXEC usp_LogError @ErrorDB = @DBName;
        SELECT ERROR_MESSAGE() AS message;
        RETURN;
    END CATCH;
END;

GO
