create procedure [usp_select_purchase_order]

(
	@vendor_order_code varchar(100),
	@response_code int output,
	@message varchar(100) output
)

as

set nocount on

begin try

	select 
		top 1 *
	from
		order_header oh
	inner join
		vendor_order vo
		on oh.vendor_order_id = vo.vendor_order_id
	inner join
		purchase_order po
		on oh.order_header_id = po.order_header_id
	where
		vo.vendor_order_code = @vendor_order_code
	order by 
		po.modified_date desc 

end try

begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_select_sales_territories]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_select_sales_territories]
(
    @iso VARCHAR(3),
    @state_code VARCHAR(10),
    @sfdc_segment_name VARCHAR(20)
)
AS
BEGIN
    /*
        DATE        AUTHOR      REMARKS
        2017-09-12  acoffel     Initial creation.
        2018-06-05  jnavarra    Link Salesforce account type name to sale type
        2018-06-19  jnavarra    Improve territory selection
        2018-08-02  jnavarra    Handle conversion of blank values to NULLs
		2020-12-27	abelenkiy	Refactored to receive sfdc_segment

        DESCRIPTION

    */

    SET NOCOUNT ON;

    BEGIN TRY
		declare @sale_type_id int

		select	@sfdc_segment_name = ss.sfdc_segment_name
				, @sale_type_id = ss.sfdc_sale_type_id
				, @state_code = isnull(@state_code, '')
		from sfdc_segment ss
			inner join sfdc_territories st
				on st.sfdc_sale_type_id = ss.sfdc_sale_type_id
		where ss.sfdc_segment_name = @sfdc_segment_name 
			and st.iso = @iso 
			and st.state_code = @state_code

		if @@rowcount = 0
			begin
				select @sfdc_segment_name = null, @sale_type_id = 1, @state_code = isnull(@state_code, '')
			end

		select st.country
             , st.state_code
             , st.geo
			 , iif(st.inside_sales_territory is null or sst.sale_type_name is null
					, st.inside_sales_territory
					, concat(sst.sale_type_name, ' ', st.inside_sales_territory)) as inside_sales_territory
             , st.renewals_territory
		from sfdc_territories st
			left join sfdc_sale_type sst
				on sst.sfdc_sale_type_id = st.sfdc_sale_type_id
		where st.iso = @iso 
			and st.sfdc_sale_type_id = @sale_type_id 
			and isnull(st.state_code, '') = @state_code

    END TRY
    BEGIN CATCH

        DECLARE @DBName NVARCHAR(128);
        SET @DBName = DB_NAME();
        EXEC dbo.usp_LogError @ErrorDB = @DBName;

    END CATCH;

END;




GO
