	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into session(expiration_date)
	values(@expiration_date)
	
	select @session_id = scope_identity()

	select session_key = convert(varchar(36),session_key)
	from session
	where session_id = @session_id

	end try

	begin catch

