-- PROCEDURE: [dbo].[usp_session_update_session]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_session_update_session]

(		
	@session_key varchar(36),
	@session_json varchar(max),
	@expiration_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-04-22	esmart		Initial creation.

	DESCRIPTION
	update session
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	update session
	set session_json = @session_json, expiration_date = case when @expiration_date is null then expiration_date else @expiration_date end
	where session_key = @session_key

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_cleanup_opportunity]
-- =============================================================================
-- stored procedure for deleting opportunity data
CREATE   PROCEDURE [dbo].[usp_sfdc_cleanup_opportunity] (
	@opportunity_id VARCHAR(18)
	,@response_code INT OUTPUT
	,@message VARCHAR(100) OUTPUT
)

/*
	DATE        AUTHOR		REMARKS
	2024-01-03  lpraharsha  Initial creation.
	2025-05-29	gblandford	US-4815207 https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4815207
							- Write delivery_document_number to sap_order_item_audit table to handle multi-document deliveries
							- cosmetic changes; casing, formatting
							- add schemas
							- add INNER to JOINs
							- implicitly state column names on INSERT..SELECTs

	DESCRIPTION
	Cleans up opportunity data. We can only clean up the data of latest opportunity.

	DEPENDENCY: 
	This procedure would be called from CSI Opportunity self-help page https://csi.webroot.com/en_US/opportunity/search
*/

AS
SET NOCOUNT ON

DECLARE @order_header_id INT
	,@vendor_order_code VARCHAR(40)
	,@license_id INT
	,@latest_order_for_license INT
	,@sfdc_update_type_id INT
	
BEGIN TRY

	SELECT 
		@order_header_id = order_header_id
	FROM dbo.order_opportunity
	WHERE salesforce_opportunity_id = @opportunity_id

	-- getting sfdc_update_type_id
	SELECT 
		@sfdc_update_type_id = sfdc_update_type_id
	FROM dbo.sfdc_update_type
	WHERE sfdc_update_type_name = 'cart_load'

	--getting vendor_order_code
	SELECT 
		@vendor_order_code = co.vendor_order_code
	FROM dbo.cart_order co
		INNER JOIN dbo.vendor_order vo 
			ON vo.vendor_order_code = co.vendor_order_code
		INNER JOIN dbo.order_header oh 
			ON oh.vendor_order_id = vo.vendor_order_id
	WHERE oh.order_header_id = @order_header_id

	--getting license_id as per order_header_id
	SELECT 
		@license_id = l.license_id
	FROM dbo.license AS l
		INNER JOIN dbo.order_item_license AS oil 
			ON oil.license_id = l.license_id
		INNER JOIN dbo.order_item AS oi 
			ON oi.order_item_id = oil.order_item_id
		INNER JOIN dbo.order_header AS oh 
			ON oh.order_header_id = oi.order_header_id
	WHERE oh.order_header_id = @order_header_id

	--getting the latest order for that license.
	SELECT 
		@latest_order_for_license = MAX(oh.order_header_id)
	FROM dbo.license AS l
		INNER JOIN dbo.order_item_license AS oil 
			ON oil.license_id = l.license_id
		INNER JOIN dbo.order_item AS oi 
			ON oi.order_item_id = oil.order_item_id
		INNER JOIN dbo.order_header AS oh 
			ON oh.order_header_id = oi.order_header_id
		INNER JOIN dbo.vendor_order AS vo 
			ON vo.vendor_order_id = oh.vendor_order_id
	WHERE l.license_id = @license_id

	-- we can delete opp only if it is the opp of recent/latest opportunity
	IF @latest_order_for_license <> @order_header_id BEGIN
		SET @response_code = -100
		SET @message = 'This opportunity cannot be deleted as new order is placed after this.'

		RETURN
	END

	BEGIN TRANSACTION

	-- we run usp_cart_refund_order_license for all the opps that have completed cart_load
		IF EXISTS (
				SELECT 1
				FROM dbo.sfdc_opportunity_load_archive
				WHERE opportunity_id = @opportunity_id
					AND sfdc_update_type_id = @sfdc_update_type_id
				) BEGIN
				EXECUTE dbo.usp_cart_refund_order_license 
							@vendor_order_code = @vendor_order_code
			END

		-- delete sap_order_item_license
		INSERT INTO dbo.sap_order_item_license_audit (
			sap_order_item_license_id
			,sap_order_item_id
			,license_id
			,insert_date
			,insert_by
			,modified_date
			,modified_by
		)
		SELECT 
			sol.sap_order_item_license_id
			, sol.sap_order_item_id
			, sol.license_id
			, sol.insert_date
			, sol.insert_by
			, sol.modified_date
			, sol.modified_by
		FROM dbo.sap_order so
			INNER JOIN dbo.sap_order_item soi 

				ON soi.sap_order_id = so.sap_order_id
			INNER JOIN dbo.sap_order_item_license sol 
				ON sol.sap_order_item_id = soi.sap_order_item_id
		WHERE so.order_header_id = @order_header_id

		DELETE sol
		FROM dbo.sap_order so
			INNER JOIN dbo.sap_order_item soi 
				ON soi.sap_order_id = so.sap_order_id
			INNER JOIN dbo.sap_order_item_license sol 
				ON sol.sap_order_item_id = soi.sap_order_item_id
		WHERE so.order_header_id = @order_header_id

		-- delete sap_order_item
		INSERT INTO dbo.sap_order_item_audit (
			sap_order_item_id
			,sap_order_id
			,sap_order_status_id
			,sap_item_number
			,order_item_id
			,usage_item
			,start_date
			,end_date
			,insert_date
			,insert_by
			,modified_date
			,modified_by
			,delivery_item_number
			,delivery_document_number
			,po_line_number
		)
		SELECT 
			soi.sap_order_item_id
			,soi.sap_order_id
			,soi.sap_order_status_id
			,soi.sap_item_number
			,soi.order_item_id
			,soi.usage_item
			,soi.start_date
			,soi.end_date
			,soi.insert_date
			,soi.insert_by
			,soi.modified_date
			,soi.modified_by
			,soi.delivery_item_number
			,soi.delivery_document_number
			,soi.po_line_number
		FROM dbo.sap_order so
			INNER JOIN dbo.sap_order_item soi 
				ON soi.sap_order_id = so.sap_order_id
		WHERE so.order_header_id = @order_header_id

		DELETE soi
		FROM dbo.sap_order so
			INNER JOIN dbo.sap_order_item soi 
				ON soi.sap_order_id = so.sap_order_id
		WHERE so.order_header_id = @order_header_id

		-- delete order_opportunity_item
		INSERT INTO dbo.order_item_opportunity_line_item_audit (
			order_item_opportunity_line_item_id
			,order_item_id
			,opportunity_line_item_id
		)
		SELECT 
			ooi.order_item_opportunity_line_item_id,
            ooi.order_item_id,
            ooi.opportunity_line_item_id	
		FROM dbo.order_header oh
			INNER JOIN dbo.order_item oi 
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_opportunity oo 
				ON oo.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_opportunity_line_item ooi 
				ON ooi.order_item_id = oi.order_item_id
		WHERE oh.order_header_id = @order_header_id

		DELETE ooi
		FROM dbo.order_header oh
			INNER JOIN dbo.order_item oi 
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_opportunity oo 
				ON oo.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_opportunity_line_item ooi 
				ON ooi.order_item_id = oi.order_item_id
		WHERE oh.order_header_id = @order_header_id

		--delete order_item_license
		INSERT INTO dbo.order_item_license_audit (
			order_item_license_id
			,order_item_id
			,license_id
			,insert_date
			,insert_by
			,modified_date
			,modified_by
		)
		SELECT 
			ol.order_item_license_id,
            ol.order_item_id,
            ol.license_id,
            ol.insert_date,
            ol.insert_by,
            ol.modified_date,
            ol.modified_by
		FROM dbo.order_header oh
			INNER JOIN dbo.order_item oi 
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_license ol 
				ON ol.order_item_id = oi.order_item_id
			INNER JOIN dbo.order_opportunity oo 
				ON oo.order_header_id = oh.order_header_id
		WHERE oh.order_header_id = @order_header_id

		DELETE ol
		FROM dbo.order_header oh
			INNER JOIN dbo.order_item oi 
				ON oi.order_header_id = oh.order_header_id
			INNER JOIN dbo.order_item_license ol 
				ON ol.order_item_id = oi.order_item_id
			INNER JOIN dbo.order_opportunity oo 
				ON oo.order_header_id = oh.order_header_id
		WHERE oh.order_header_id = @order_header_id

		-- deleting from order_opportunity
		INSERT INTO dbo.order_opportunity_audit (
			order_opportunity_id
			,order_header_id
			,salesforce_opportunity_id
			,oracle_contract_number
			,insert_date
			,insert_by
			,modified_date
			,modified_by
		) 
		SELECT order_opportunity_id
			,order_header_id
			,salesforce_op
portunity_id
			,oracle_contract_number
			,insert_date
			,insert_by
			,modified_date
			,modified_by 
		FROM dbo.order_opportunity 
		WHERE order_header_id = @order_header_id

		DELETE
		FROM dbo.order_opportunity
		WHERE order_header_id = @order_header_id

		--deleting from sap_order
		INSERT INTO dbo.sap_order_audit (
			sap_order_id
			,sap_order_number
			,order_header_id
			,sap_order_status_id
			,insert_date
			,modified_date
			,delivery_document_number
			,delivery_type
			,insert_by
			,modified_by
			)
		SELECT sap_order_id,
               sap_order_number,
               order_header_id,
               sap_order_status_id,
               insert_date,
               modified_date,
               delivery_document_number,
               delivery_type,
               insert_by,
               modified_by
		FROM dbo.sap_order
		WHERE order_header_id = @order_header_id

		DELETE dbo.sap_order
		WHERE order_header_id = @order_header_id

		-- clean up order_company
		INSERT INTO dbo.order_company_audit (
			order_company_id
			,order_header_id
			,company_id
			,order_company_type_id
			,insert_date
			,customer_id
			,audit_date
		)
		SELECT order_company_id
			,order_header_id
			,company_id
			,order_company_type_id
			,insert_date
			,customer_id
			,GETDATE()
		FROM dbo.order_company
		WHERE order_header_id = @order_header_id

		DELETE dbo.order_company
		WHERE order_header_id = @order_header_id

		SET @response_code = 0
		SET @message = 'Opportunity data is successfully deleted.'

	COMMIT TRANSACTION

END TRY

BEGIN CATCH

	IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION

	SELECT @response_code = ERROR_NUMBER()

	SELECT @message = CASE 
			WHEN @message IS NULL
				THEN 'transaction failed' + Error_message()
			ELSE @message
			END

	DECLARE @DBName NVARCHAR(128)

	SET @DBName = db_name()
	EXECUTE dbo.usp_LogError @ErrorDB = @DBName

END CATCH

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_create_update_license_vault_template]
-- =============================================================================

CREATE   procedure [dbo].[usp_sfdc_create_update_license_vault_template] (@license_id int, @sfdc_template_name varchar(50))

/*	
	DATE		AUTHOR		REMARKS
	2022-08-03	psatish		Initial creation.
	2022-05-05  psatish		ALM# 1152 Fixed the timing issue on the license vault 
	2022-08-26	abelenkiy	Change to get salesforce_account_id from account instead of bill_to_account (ALM# 2179)
							Removed unused variables; enhanced error handling; fixed indentation

	DESCRIPTION
	Create_license_vault/update_license_vault template into sfdc_opportunity_update.

	Templates types handled:
		create_license_vault - Executed every 10 minutes by the LicenseVault_creation job. 
		update_license_vault - Called synchronously by usp_license_insert_external_reference_vault and usp_license_update_external_reference_vault

*/
as

begin try

set nocount on

declare
    @sfdc_update_json nvarchar(max)
  , @order_header_id int
  , @salesforce_license_id varchar(50)
  , @salesforce_account_id varchar(50)

declare @license_vault table
(
    order_header_id int
  , license_id int
  , license_external_reference_vault_id int
  , external_reference_value varchar(150)
  , license_category_description varchar(50)
  , keycode varchar(50)
  , vault_guid varchar(50)
  , license_category_name varchar(25)
  , vault_name varchar(200)
  , is_provisioned bit
  , billing_type varchar(50)
  , storage_gb int
  , case_id int
  , notes varchar(max)
  , effective_object_name varchar(150)
  , vault_url varchar(510)
  , vault_status varchar(50)
  , effective_object_id int
  , is_active bit
  , product_account_id varchar(250)
  , license_external_reference_id int
  , vault_datacentername varchar(150)
  , salesforce_vault_id varchar(50)
  , object_element_name varchar(50)
  , product_platform varchar(50)
  , license_Category_id int
  , license_distribution_method varchar(5)
  , salesforce_account_id varchar(20)
)

    if exists (select 1 
				from dbo.license_external_reference ex 
					inner join dbo.license_external_reference_vault rv 
						on rv.license_external_reference_vault_id = ex.license_external_reference_vault_id 
				where rv.license_id = @license_id)
        begin
            select @salesforce_license_id = salesforce_license_id
            from dbo.license_key
            where license_id = @license_id

            insert into @license_vault (license_id, license_external_reference_vault_id, keycode, vault_guid, license_category_name, vault_name
                                        , is_provisioned, billing_type, storage_gb, case_id, notes, vault_url, vault_status, is_active
                                        , license_category_description, product_account_id, license_external_reference_id, effective_object_id
                                        , vault_datacentername, salesforce_vault_id, object_element_name, product_platform, license_Category_id
                                        , license_distribution_method, external_reference_value, salesforce_account_id)
            select distinct
                    lc.license_id
                    , ex.license_external_reference_vault_id
                    , lc.keycode
                    , vt.vault_datacenter_key
                    , lcl.license_category_name
                    , vt.vault_name
                    , v.is_provisioned
                    , v.billing_type
                    , v.storage_GB
                    , v.case_number
                    , v.notes
                    , vt.vault_url
                    , vt.vault_status
                    , v.is_active
                    , lcl.license_category_description
                    , ex.external_reference_value
          
          , ex.license_external_reference_id
                    , ex.effective_object_id
                    , vt.vault_datacenter_name
                    , vt.salesforce_vault_id
                    , eo.object_element_name
                    , pp.product_platform_name
                    , ex.license_category_id
                    , dm.license_distribution_method_code
                    , ex.external_reference_value
					, c.salesforce_account_id
            from license lc
                inner join dbo.license_distribution_method dm
                    on dm.license_distribution_method_id = lc.license_distribution_method_id
                inner join dbo.license_external_reference ex
                    on ex.license_id = lc.license_id
                inner join dbo.effective_object eo
                    on eo.effective_object_id = ex.effective_object_id
                inner join dbo.license_external_reference_vault v
                    on v.license_external_reference_vault_id = ex.license_external_reference_vault_id
                inner join dbo.license_category lcl
                    on lcl.license_category_id = ex.license_category_id
                inner join vault vt
                    on vt.vault_id = v.vault_id
                inner join dbo.product_platform pp
                    on pp.product_platform_id = vt.product_platform_id
				left join reseller_license rl
					on rl.license_external_reference_id = ex.license_external_reference_id
				left join company c
					on c.company_id = rl.company_id
            where lc.license_id = @license_id
                    and eo.object_element_name in ( case when lcl.license_category_id = 200 then 'customer_short_name' else eo.object_element_name end )
        end
    else
		begin
	        return
		end

	select @order_header_id = max(oi.order_header_id)
	from order_item oi
		inner join dbo.order_item_license ol
			on ol.order_item_id = oi.order_item_id
	where ol.license_id = @license_id

    select @salesforce_account_id = c.salesforce_account_id
    from dbo.order_company oc
        inner join dbo.company c
            on c.company_id = oc.company_id
        inner join dbo.order_company_type oct
            on oct.order_company_type_id = oc.order_company_type_id
    where oc.order_header_id = @order_header_id 
		and oct.order_company_type_name = 'account'

    if (select count(*)from @license_vault where license_distribution_method <> 'NSBF') > 0
        begin
            set @sfdc_template_name = 'create_license_vault'

            if (select count(*) 
				from sfdc_opportunity_update_archive ac 
					inner join dbo.sfdc_template tm 
						on tm.sfdc_template_id = ac.sfdc_template_id 
					inner join sfdc_update_type ut 
						on ut.sfdc_update_type_id = ac.sfdc_update_type_id 
				where license_id = @license_id
					and sfdc_template_name = @sfdc_template_name
                    and ut.sfdc_update_type_name = @sfdc_template_name
                    and sfdc_response_code = 'success') = 0

                and (select count(*)
					from sfdc_opportunity_update ac 
						inner join dbo.sfdc_template tm 
							on tm.sfdc_template_id = ac.sfdc_template_id 
					where order_header_id = @order_header_id
						and tm.sfdc_template_name = @sfdc_template_name) = 0

                and (select count(*)
					from dbo.sfdc_license_vault 
					where license_id = @license_id) = 0

                begin
                    set @sfdc_template_name = 'create_license_vault'
                end

            else if (select count(*)
					from dbo.sfdc_license_vault 
					where license_id = @license_id) > 0

                    and (select count(*)
						from sfdc_opportunity_update_archive ac 
							inner join dbo.sfdc_template tm 
								on tm.sfdc_template_id = ac.sfdc_template_id 
							inner join sfdc_update_type ut 
								on ut.sfdc_update_type_id = ac.sfdc_update_type_id 
						
where license_id = @license_id
							and sfdc_template_name = @sfdc_template_name
                            and ut.sfdc_update_type_name = @sfdc_template_name
                            and sfdc_response_code = 'success') > 0
                begin
                    set @sfdc_template_name = 'update_license_vault'
                end
            else
                return

            if ((select count(*)
				from @license_vault 
				where product_platform = 'Saas' 
					and license_Category_id in ( 233, 234 )) > 0
                
				and (select count(*)
					from @license_vault lv 
						inner join dbo.sky_update_archive ac 
							on ac.license_id = lv.license_id 
						inner join dbo.sky_template st 
							on st.sky_template_id = ac.sky_template_id 
						inner join dbo.sky_update_status ss 
							on ss.sky_update_status_id = ac.sky_update_status_id 
					where ss.sky_update_status_name = 'Processed'
                        and st.sky_template_name in ('CBEP_update', 'O365_update')
						and datediff(minute, ac.archive_date, getdate()) > 10) > 0)
                or ((select count(*)
					from @license_vault 
					where license_Category_id not in ( 233, 234 ) 
					or product_platform <> 'Saas') > 0)
                begin
                    if exists (select 1 from @license_vault v where v.object_element_name in ( 'tenant_id', 'cep_company_id' ))
                        begin
                            select @sfdc_update_json = 
								(select distinct
                                        v.license_id
                                        , v.keycode
                                        , v.license_category_name
                                        , v.license_category_description
                                        --, isnull(@salesforce_account_id, '') salesforce_account_id
                                        , isnull(@salesforce_license_id, '') salesforce_license_id
                                        , (select distinct
                                                    v.license_external_reference_id
                                                , v.is_active
                                                , v.is_provisioned
												, coalesce(v.salesforce_account_id, @salesforce_account_id, '') salesforce_account_id
                                                , isnull(v.salesforce_vault_id, '') salesforce_vault_id
                                                , isnull(v.vault_name, '') vault_name
                                                , isnull(v.vault_datacentername, '') vault_datacentername
                                                , isnull(v.vault_guid, '') vault_datacenter_key
                                                , isnull(v.vault_url, '') vault_url
                                                , isnull(v.vault_status, '') vault_status
                                                , isnull(v.billing_type, '') billing_type
                                                , isnull(convert(varchar, v.storage_gb), '') storage_GB
                                                , isnull(v.notes, '') Notes
                                                , (select isnull((select distinct er.external_reference_value 
																	from dbo.license_external_reference er 
																		inner join dbo.effective_object eo 
																			on eo.effective_object_id = er.effective_object_id 
																	where eo.object_element_name = 'customer_short_name'
                                                                        and er.license_id = v.license_id
                                                                        and er.license_external_reference_vault_id = v.license_external_reference_vault_id), '')) Customer_short_name
                                                , v.product_account_id
                                                , (select isnull((select 
distinct er.external_reference_value 
																	from dbo.license_external_reference er 
																		inner join dbo.effective_object eo 
																			on eo.effective_object_id = er.effective_object_id 
																	where eo.object_element_name in ('partner_tenant_id', 'cep_partner_id')
                                                                        and er.license_id = v.license_id
                                                                        and er.license_external_reference_vault_id = v.license_external_reference_vault_id), '')) vault_partner_id
                                            from @license_vault v
                                                inner join dbo.license_external_reference ec
                                                    on ec.license_id = v.license_id
                                                        and ec.license_external_reference_vault_id = v.license_external_reference_vault_id
                                                inner join dbo.effective_object eo
                                                    on eo.effective_object_id = ec.effective_object_id
                                            where v.object_element_name not in ( 'partner_tenant_id', 'cep_partner_id', 'cep_user_id' )
                                            for json path) License_vault
                                from @license_vault v
                                where v.object_element_name not in ( 'partner_tenant_id', 'cep_partner_id', 'cep_user_id' )
                                for json path)
						end
                    else
                        begin
                            select @sfdc_update_json = 
								(select distinct
                                        v.license_id
                                        , v.keycode
                                        , v.license_category_name
                                        , v.license_category_description
                                        --, isnull(@salesforce_account_id, '') salesforce_account_id
                                        , isnull(@salesforce_license_id, '') salesforce_license_id
                                        , (select distinct
                                                    v.license_external_reference_id
                                                , v.is_active
                                                , v.is_provisioned
												, coalesce(v.salesforce_account_id, @salesforce_account_id, '') salesforce_account_id
                                                , isnull(v.salesforce_vault_id, '') salesforce_vault_id
                                                , isnull(v.vault_name, '') vault_name
                                                , isnull(v.vault_datacentername, '') vault_datacentername
                                                , isnull(v.vault_guid, '') vault_datacenter_key
                                                , isnull(v.vault_url, '') vault_url
                                                , isnull(v.vault_status, '') vault_status
                                                , isnull(v.billing_type, '') billing_type
                                                , isnull(convert(varchar, v.storage_gb), '') storage_GB
                                                , isnull(v.notes, '') Notes
                                                , (select isnull((select distinct er.external_reference_value 
																	from @license_vault er 
																	where er.object_element_name = 'customer_short_name'
                                                                        and er.license_id = v.license_id
                                                                        and er.license_external_reference_id = v.license_external_reference_id), '')) Customer_short_name
                                                , '' product_Acc
ount_id
                                                , (select isnull((select distinct er.external_reference_value 
																	from @license_vault er 
																	where er.object_element_name in ('partner_tenant_id', 'cep_partner_id' )
																		and er.license_id = v.license_id
																		and er.license_external_reference_id = v.license_external_reference_id)
                                                , '')) vault_partner_id
                                            from @license_vault v
                                                inner join dbo.license_external_reference ec
                                                    on ec.license_id = v.license_id
                                                        and ec.license_external_reference_vault_id = v.license_external_reference_vault_id
                                            where v.object_element_name not in ( 'cep_user_id' )
                                            for json path) License_vault
                                from @license_vault v
                                where v.object_element_name not in ( 'cep_user_id' )
                                for json path)
                        end

                    set @sfdc_update_json = replace(@sfdc_update_json, '\/', '/')

                    if @sfdc_update_json is not null
                        exec usp_sfdc_insert_sfdc_opportunity_update
                            @sfdc_template_name = @sfdc_template_name
                            , @order_header_id = @order_header_id
                            , @license_id = @license_id
                            , @sfdc_update_json = @sfdc_update_json
                    else
                        return
                end
        end
end try
begin catch

	declare @error_severity int = error_severity(), @error_state int = error_state(), @message nvarchar(4000)
	set @message = 'license_id = ' + convert(varchar(20), isnull(@license_id , 'null')) 
				+ ', sfdc_template_name = ' + @sfdc_template_name
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state) with log

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message, @@servername, db_name(), suser_name()

end catch

GO
