-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_account_contact]

(
		@salesforce_account_id char(18),
		@company_name nvarchar(255),
		@company_type_name varchar(20),
		@salesforce_contact_id char(18),
		@first_name nvarchar(225),
		@last_name nvarchar(225), 
		@customer_email varchar(100), 
		@address_1  nvarchar(255), 
		@city nvarchar(130), 
		@state nvarchar(20) = null, 
		@postal_code nvarchar(32), 
		@country varchar(75),
		@vat_id varchar(20) = null,
		@shipping_address_1  nvarchar(255) = null, 
		@shipping_city nvarchar(130) = null, 
		@shipping_state nvarchar(20) = null, 
		@shipping_postal_code nvarchar(32) = null, 
		@shipping_country varchar(75) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2015-03-05	cnovac		Added @company_type_name to usp_customer_insert_customer_service call
	2016-05-12	acoffel		shipping address insert and vat support 
	2017-03-22	esmart		Support for 3 char state
	2019-06-21	esmart		Remove code to insert new partners	
	2019-06-21	esmart		add @company_id_input
	2020-08-20	abelenkiy	refactored to call usp_customer_insert_customer_service with json and consolidated ship_to insert into one call; removed unused variables
							set company_id output from customer_company not previously being set

	DESCRIPTION
	Insert customer and company from account and contact. Called by PHP in SFDC trial load.

*/

AS
	set nocount on				

	declare	@company_id int, 
			@customer_id int, 
			@input_json nvarchar(max)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) convert input parameters to json
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

    set @input_json = (select @customer_email as [customer.customer_email]
		, @first_name as [customer.first_name]
		, @last_name as [customer.last_name]
		, @address_1 as [customer.address.bill_to.address_1]
		, @city as [customer.address.bill_to.city]
		, @state as [customer.address.bill_to.state]
		, @postal_code as [customer.address.bill_to.postal_code]
		, @country as [customer.address.bill_to.country]
		, @shipping_address_1 as [customer.address.ship_to.address_1]
		, @shipping_city as [customer.address.ship_to.city]
		, @shipping_state as [customer.address.ship_to.state]
		, @shipping_postal_code as [customer.address.ship_to.postal_code]
		, @shipping_country as [customer.address.ship_to.country]
		, @salesforce_contact_id as [customer.salesforce_contact_id]
		--, @company_id_input as [company.company_id] --not being passed in
		, @company_name as [company.company_name]
		, @company_type_name as [company.company_type_name]
		, @salesforce_account_id as [company.salesforce_account_id]
		, 'sfdc_integration' as [transaction_user]
    for json path, without_array_wrapper)


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/select customer and select company
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) customer/company
	exec usp_customer_insert_customer_service @input_json = @input_json, @customer_id = @customer_id output

	-- 2.2) select company from customer_company
	select @company_id = company_id
	from cu
stomer_company cc
	where cc.customer_id = @customer_id


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) vat insert/update 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @vat_id is not null and @customer_id is not null
		begin 
			if (select count(*) from customer_vat where customer_id = @customer_id) > 0
				begin
					update customer_vat set vat_id = @vat_id, last_modified_date = getdate() where customer_id = @customer_id
				end
				else 
				begin 
					insert into customer_vat (customer_id, vat_id, last_modified_date)
					select @customer_id, @vat_id, getdate()
				end
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) return 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	select company_id = @company_id, customer_id = @customer_id

	return 

	end try

	begin catch

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
