	DESCRIPTION
	Insert sfdc_case
*/

AS

	declare @sfdc_case_type_id tinyint,
			@response_code int,
			@message varchar(100)
	

begin try


	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @sfdc_case_type_id
