-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_insert_opportunity_load]

(
	@sfdc_template_name varchar(50) = null,
	@opportunity_id varchar(18) = null,
	@salesforce_trial_id varchar(18) = null,
	@license_update_id varchar(18) = null,
	@sfdc_load_json nvarchar(max) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2015-02-19	esmart		@opportunity_id validation
	2015-11-06	esmart		Add return of sfdc_opportunity_load_id to 1.3.3
	2016-02-11	esmart		Remove template finalize_opportunity_autobilling
	2016-10-07	esmart		Allow re-load of opportunities.
	2017-07-17	esmart		license_update_id 
	2020-12-23	esmart		@sfdc_load_json

	DESCRIPTION
	Insert opportunity
*/

AS
	set nocount on				

	declare	@sfdc_opportunity_load_id int,
			@sfdc_template_id tinyint,
			@sfdc_update_type_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @sfdc_template_name is not null
		begin
		select @sfdc_template_id = sfdc_template_id
		from sfdc_template
		where sfdc_template_name = @sfdc_template_name 
		end

	-- 1.1) select template
	if @sfdc_template_id is null
		begin
			if @opportunity_id is not null 
				begin
				select @sfdc_template_id = 3
				end

			if @salesforce_trial_id is not null
				begin
				select @sfdc_template_id = 8
				end
		end

	-- 1.2) select update type
	select @sfdc_update_type_id = (select top 1 sfdc_update_type_id
									from sfdc_template_update_type 
									where sfdc_template_id = @sfdc_template_id
									order by sfdc_template_update_type_id)

	-- 1.3) @opportunity_id
	
	-- 1.3.1) verify length
	if len(@opportunity_id) = 15
		begin
			select @opportunity_id = dbo.fn_ConvertSalesforceID_15to18(@opportunity_id)
		end

	-- 1.3.2) check to see if opportunity is in queue
	select @sfdc_opportunity_load_id = sfdc_opportunity_load_id from sfdc_opportunity_load where opportunity_id = @opportunity_id
	
	if @sfdc_opportunity_load_id is not null
		begin
		select sfdc_opportunity_load_id = @sfdc_opportunity_load_id
		return
		end

	-- 1.3.3) @sfdc_load_json
	if @sfdc_load_json is null
		begin
		select @sfdc_load_json = (select @opportunity_id as opportunity_id, @salesforce_trial_id as salesforce_trial_id, @license_update_id as license_update_id for json path, without_array_wrapper)
		end
	else
		begin
		select @opportunity_id = opportunity_id, @salesforce_trial_id = salesforce_trial_id, @license_update_id = license_update_id
		from openjson(@sfdc_load_json)
		with (opportunity_id varchar(18) '$.opportunity_id',
				salesforce_trial_id varchar(18) '$.salesforce_trial_id',
				license_update_id varchar(18) '$.license_update_id')
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) sfdc_opportunity_load
	insert into sfdc_opportunity_load(opportunity_id,salesforce_trial_id,sfdc_template_id,sfdc_update_type_id,license_update_id) values(@opportunity_id,@salesforce_trial_id,@sfdc_template_id,@sfdc_update_type_id,@license_update_id)
	
	select @sfdc_opportunity_load_id = scope_identity()

	-- 2.2) sfdc_op
portunity_load_json
	insert into sfdc_opportunity_load_json(sfdc_opportunity_load_id, sfdc_load_json)
	values(@sfdc_opportunity_load_id,@sfdc_load_json)

	select sfdc_opportunity_load_id = @sfdc_opportunity_load_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;





GO
