-- PROCEDURE: [dbo].[usp_sfdc_insert_opportunity_update_task]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_insert_opportunity_update_task]



/*	
	DATE		AUTHOR		REMARKS
	2017-05-12	acoffel		Initial creation.

	DESCRIPTION
	Select parent_license_status
*/

AS
	set nocount on				

	declare	@sfdc_template_id int,
			@sfdc_update_type_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) get op update details
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--1.0) set @sfdc_template_id 
	select @sfdc_template_id = sfdc_template_id from sfdc_template  where sfdc_template_name = 'task_insert'

	-- 1.1) set @sfdc_update_type_id
	select @sfdc_update_type_id = sfdc_update_type_id from sfdc_template_update_type where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
																																from sfdc_template_update_type
																																where sfdc_template_id = @sfdc_template_id)
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert op update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.0) insert rows into sfdc_opportunity_update
	insert into license_parent_device_status (license_id, parentkeycode, license_seats, salesforce_license_id, salesforce_account_id, account_owner_id, active_last_30_day_devices, total_dbactivelast90days, percent_drop, processed, insert_date)
	select license_id, parentkeycode, license_seats, salesforce_license_id, salesforce_account_id, account_owner_id, active_last_30_day_devices, total_dbactivelast90days, percent_drop, 0, getdate()
	from datawarehousereadonly.feed.dbo.license_parent_device_status 
	where processed = 0

	-- 2.1) insert rows into sfdc_opportunity_update
	insert into sfdc_opportunity_update(license_id, trial_id, sfdc_template_id, sfdc_update_type_id, process_date)
	select license_id, NULL, @sfdc_template_id, @sfdc_update_type_id, getdate()
	from datawarehousereadonly.feed.dbo.license_parent_device_status
	where processed = 0

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_order_item_opportunity_line_item]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_order_item_opportunity_line_item]

(
	@order_item_id int = null,
	@opportunity_line_item_id varchar(18) = null,
	@opportunity_line_item_id_json varchar(max) = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-05-16	esmart		Initial creation.
		2019-08-28	cnovac		Added @opportunity_line_item_id_json as an alternative to add line items to be used for all external orders

		DESCRIPTION
		insert order_item_opportunity_line_item
	*/

	set nocount on

	declare	@order_item_opportunity_line_item_id int,
			@response_code int,
			@message varchar(100)
	declare @opportunity_line_item_id_json_table table ([index] varchar(50), [key] varchar(50), [value] varchar(50))

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @order_item_opportunity_line_item_id
	select @order_item_opportunity_line_item_id = order_item_opportunity_line_item_id
	from order_item_opportunity_line_item
	where order_item_id = @order_item_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) delete/insert if row found and have @order_item_id
	if @order_item_opportunity_line_item_id is not null and @order_item_id is not null
	begin
		delete from order_item_opportunity_line_item
		where order_item_opportunity_line_item_id = @order_item_opportunity_line_item_id 

		insert into order_item_opportunity_line_item(order_item_id, opportunity_line_item_id)
		values(@order_item_id, @opportunity_line_item_id)
	end
	-- 2.2) insert if no row found and have @order_item_id
	else if @order_item_opportunity_line_item_id is null and @order_item_id is not null
	begin
		insert into order_item_opportunity_line_item(order_item_id, opportunity_line_item_id)
		values(@order_item_id, @opportunity_line_item_id)
	end
	-- 2.3) insert if @opportunity_line_item_id_json is not null
	else if @opportunity_line_item_id_json is not null
	begin

		insert into @opportunity_line_item_id_json_table ([index], [key], [value])
		select olij.[Key], olij2.[Key], olij2.Value
		from openjson(@opportunity_line_item_id_json) olij
		cross apply openjson(olij.value) olij2

		insert into order_item_opportunity_line_item(order_item_id, opportunity_line_item_id)
		select distinct olijt2.[value] as order_item_id, olijt3.[value] as opportunity_line_item_id
		from @opportunity_line_item_id_json_table olijt
		left join @opportunity_line_item_id_json_table olijt2 on olijt2.[index] = olijt.[index] and olijt2.[Key] = 'order_item_id'
		left join @opportunity_line_item_id_json_table olijt3 on olijt3.[index] = olijt.[index] and olijt3.[Key] = 'opportunity_line_item_id'
	end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_salesforce_license_id]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_salesforce_license_id]

(
	@keycode varchar(40),
	@salesforce_license_id varchar(18)
)

/*	
	DATE		AUTHOR		REMARKS
	2016-04-12	esmart		Initial creation.

	DESCRIPTION
	update salesforce_license_id
*/

AS
	set nocount on				

	declare	@license_id int,
			@license_key_id int,
			@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id
	select @license_id = license_id
	from license
	where keycode = @keycode
	
	-- 1.2) @license_key_id
	if (select count(*) from license_key where license_id = @license_id and salesforce_license_id = @salesforce_license_id) = 0
		begin
			update license_key
			set salesforce_license_id = @salesforce_license_id
			where license_id = @license_id
		end

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_salesforce_license_vault_id]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_salesforce_license_vault_id]

(
	@keycode varchar(40),
	@license_external_reference_id int,
	@salesforce_license_vault_id varchar(25)
)

/*	
	DATE		AUTHOR		REMARKS
	2022-08-03	psatish		Initial creation.

	DESCRIPTION
	insert/update into sfdc_license_vault table
*/

AS
	set nocount on		


    declare	@license_id int,
			@response_code int,
			@message varchar(100)			

			
	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @license_id
	select @license_id = lc.license_id
	from license lc
	WHERE keycode = @keycode 
	
	
	-- 1.2) @license_key_id
	if (select count(*) from sfdc_license_vault where license_id = @license_id and license_external_reference_id=@license_external_reference_id) = 0
		begin
			insert into dbo.sfdc_license_vault
			(
				salesforce_license_vault_id,
				license_id,
				license_external_reference_id		 

			)
			select @salesforce_license_vault_id,er.license_id,er.license_external_reference_id
			from dbo.license_external_reference er
			where er.license_id=@license_id
			and er.license_external_reference_id=@license_external_reference_id
		end
        else
        begin
			update sfdc_license_vault
			set salesforce_license_vault_id=@salesforce_license_vault_id,
				modified_date=getdate()
			where license_id=@license_id
			and license_external_reference_id=@license_external_reference_id

		end

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_sfdc_opportunity_failure_reprocess]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_sfdc_opportunity_failure_reprocess]

(
	@sfdc_opportunity_load_failure_id int = null,
	@sfdc_opportunity_update_failure_id int = null,
	@process_date datetime = null
)
	
/*	
	DATE			AUTHOR			REMARKS
	2016-10-03		esmart			Initial creation
	
	DESCRIPTION
	I
*/

as

	set nocount on			

	declare	@sfdc_opportunity_load_id int,
			@sfdc_opportunity_update_id int,
			@sfdc_template_id tinyint, 
			@sfdc_update_type_id tinyint,
			@opportunity_id varchar(18), 
			@salesforce_trial_id varchar(18),
			@order_header_id int,
			@form_submit_id int,
			@license_id int,
			@trial_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) 
	if @process_date is null begin select @process_date = getdate() end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) @sfdc_opportunity_load_failure_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @sfdc_opportunity_load_failure_id is not null
		begin
			-- 2.1) select values from failure 
			select @opportunity_id = opportunity_id, @salesforce_trial_id = salesforce_trial_id, @sfdc_template_id = sfdc_template_id, @sfdc_update_type_id = sfdc_update_type_id
			from sfdc_opportunity_load_failure
			where sfdc_opportunity_load_failure_id = @sfdc_opportunity_load_failure_id

			-- 2.2) check sfdc_opportunity_load for @opportunity_id
			if @opportunity_id is not null
				begin
					select @sfdc_opportunity_load_id = sfdc_opportunity_load_id
					from sfdc_opportunity_load
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and opportunity_id = @opportunity_id
				end

			-- 2.3) check sfdc_opportunity_load for @salesforce_trial_id
			if @opportunity_id is not null
				begin
					select @sfdc_opportunity_load_id = sfdc_opportunity_load_id
					from sfdc_opportunity_load
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and salesforce_trial_id = @salesforce_trial_id
				end
	
			-- 2.4) insert new 
			if @sfdc_opportunity_load_id is null
				begin
					insert into sfdc_opportunity_load (opportunity_id, salesforce_trial_id, sfdc_template_id, sfdc_update_type_id, process_date)
					select @opportunity_id, @salesforce_trial_id, @sfdc_template_id, @sfdc_update_type_id, @process_date
				end
			
			return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) @sfdc_opportunity_update_failure_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @sfdc_opportunity_update_failure_id is not null
		begin
			-- 3.1) select values from failure 
			select @order_header_id = order_header_id, @trial_id = trial_id, @form_submit_id = form_submit_id, @license_id = license_id, @sfdc_template_id = sfdc_template_id, @sfdc_updat
e_type_id = sfdc_update_type_id
			from sfdc_opportunity_update_failure
			where sfdc_opportunity_update_failure_id = @sfdc_opportunity_update_failure_id

			-- 3.2) check sfdc_opportunity_update for @order_header_id
			if @order_header_id is not null
				begin
					select @sfdc_opportunity_update_id = sfdc_opportunity_update_id
					from sfdc_opportunity_update
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and order_header_id = @order_header_id
				end

			-- 3.3) check sfdc_opportunity_update for @trial_id
			if @trial_id is not null
				begin
					select @sfdc_opportunity_update_id = sfdc_opportunity_update_id
					from sfdc_opportunity_update
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and trial_id = @trial_id
				end

			-- 3.4) check sfdc_opportunity_update for @form_submit_id
			if @form_submit_id is not null
				begin
					select @sfdc_opportunity_update_id = sfdc_opportunity_update_id
					from sfdc_opportunity_update
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and form_submit_id = @form_submit_id
				end

			-- 3.5) check sfdc_opportunity_update for @license_id
			if @license_id is not null
				begin
					select @sfdc_opportunity_update_id = sfdc_opportunity_update_id
					from sfdc_opportunity_update
					where sfdc_template_id = @sfdc_template_id and sfdc_update_type_id = @sfdc_update_type_id and license_id = @license_id
				end
	
			-- 3.6) insert new 
			if @sfdc_opportunity_update_id is null
				begin
					insert into sfdc_opportunity_update(order_header_id, trial_id, sfdc_template_id, sfdc_update_type_id, form_submit_id, license_id, process_date)
					select @order_header_id, @trial_id, @sfdc_template_id, @sfdc_update_type_id, @form_submit_id, @license_id, @process_date
				end

			return
		end
		

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'reprocess failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_sfdc_opportunity_update]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_sfdc_insert_sfdc_opportunity_update]
 
(
    @sfdc_template_name VARCHAR(50),
    @order_header_id INT = NULL,
    @trial_id INT = NULL,
    @form_submit_id INT = NULL,
    @process_date DATETIME = NULL,
    @license_id INT = NULL,
    @sfdc_update_json NVARCHAR(MAX) = NULL
)

/*
    DATE        AUTHOR      REMARKS
    2015-04-16  esmart      Initial creation.
    2016-05-06  cnovac      Added @license_id which is used for forecasting
    2018-01-03  cnovac      Added @sfdc_update_json which will be used to store what elements we want to transact on
    2019-01-09  acoffel     Added person in process check
    2019-03-22  jnavarra    Add Service Broker delay
    2019-04-10  cnovac      Took out debug code which was blowing up WIFI trial to full requests
    2019-10-14  jnavarra    Counter "double-tap" without Service Broker
	2023-07-06  msoni       Remove max process date part

    DESCRIPTION
    Inset sfdc_opportunity_update
*/

AS
    SET NOCOUNT ON

    DECLARE @sfdc_template_id tinyint,
            @sfdc_update_type_id tinyint,
            @sfdc_opportunity_update_id int,
            @customer_id int,
            @new_customer_id int,
            @min_sfdc_opportunity_update_id int,
            @response_code int,
            @message varchar(100)
		
	    begin try
        
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 1.) select
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 1.0) @process_date
        if @process_date is null
            begin
                select @process_date = getdate()
            end

        -- 1.1) @sfdc_template_id
        select @sfdc_template_id = sfdc_template_id
        from sfdc_template
        where sfdc_template_name = @sfdc_template_name 

        -- 1.2) 
        select @sfdc_update_type_id = sfdc_update_type_id
        from sfdc_template_update_type
        where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
                                            from sfdc_template_update_type
                                            where sfdc_template_id = @sfdc_template_id)

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 2.) check for person create request
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 2.1)
        if @sfdc_template_id = 26 AND @sfdc_update_type_id = 129
            BEGIN
                declare @customer_email varchar(100)
				---,@form_submit_id INT = NULL
				---,@process_date DATETIME = NULL

                set @customer_email = (
                    select top(1) json_value(fs.form_json, '$.customer_email')
                    from dbo.form_submit fs
                    where isjson(fs.form_json) = 1
                        and (fs.form_submit_id =@form_submit_id )
                )
       
              --declare @max_customer_process_date datetime   --------- (1) Removed @max_customer_process_date  

                ;with
                    form_submits as (
                        select sou.form_submit_id, sou.process_date
    
                    from dbo.sfdc_opportunity_update sou
                            left join dbo.form_submit fs
                                on fs.form_submit_id = sou.form_submit_id
                        where isjson(fs.form_json) = 1
                            and json_value(fs.form_json, '$.customer_email') =@customer_email 
                            and sou.sfdc_template_id = 26       -- update_marketo
                            and sou.sfdc_update_type_id = 129   -- update_license

                        union
                        
                        SELECT soua.form_submit_id, soua.process_date
                        FROM dbo.sfdc_opportunity_update_archive soua
                            LEFT JOIN dbo.form_submit fs
                                ON fs.form_submit_id = soua.form_submit_id
                        WHERE ISJSON(fs.form_json) = 1
                            AND JSON_VALUE(fs.form_json, '$.customer_email') =@customer_email
                            AND soua.sfdc_template_id = 26       -- update_marketo
                            AND soua.sfdc_update_type_id = 129   -- update_license
                            AND soua.process_date > DATEADD(HOUR, -1, GETDATE())
                    )
                   SELECT @process_date =
				    (SELECT TOP(1) process_date
					 FROM form_submits 
					 ORDER BY form_submits.process_date desc) -----(2) removed max(process_date)
	
                IF @process_date IS NOT NULL
                    begin
                        -- Something isn't fully processed yet, this call needs to be delayed
                        set @process_date = dateadd(hour, 1, @process_date) -----(3) removed max(process_date)
                        -- set @process_date = case when @process_date > @max_customer_process_date then @process_date else @max_customer_process_date end -----(4) removed max(process_date)
                      END
					ELSE 
					  BEGIN
                       SET @process_date = GETDATE()
					  END
            end

        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
        -- 3.) insert
        -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

        -- 3.1) insert sfdc_opportunity_update
        insert into sfdc_opportunity_update(order_header_id, trial_id, form_submit_id, sfdc_template_id, sfdc_update_type_id, process_date, license_id)
        values(@order_header_id, @trial_id, @form_submit_id, @sfdc_template_id, @sfdc_update_type_id, @process_date, @license_id)
    
        set @sfdc_opportunity_update_id = scope_identity()
    
        -- 3.2) insert sfdc_opportunity_update_json which will be used to later to select data elements out
        if @sfdc_update_json is not null
        begin
            insert into dbo.sfdc_opportunity_update_json (sfdc_opportunity_update_id, sfdc_update_json)
            values (@sfdc_opportunity_update_id, @sfdc_update_json)
        END
    
    end try
    begin catch

        set @response_code = -200
        set @message = case when @message is null then 'usp_sfdc_insert_sfdc_opportunity_update failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_subscriber]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_subscriber]

AS

/*********************************************************************************
 * (C) 2016.  Webroot Software, Inc.
 *********************************************************************************
						dbo.usp_sfdc_insert_subscriber

	Purpose:  
	Inserts or updates a subscriber record

	History:
	DATE		AUTHOR		REMARKS
	2016-08-19	mrobbins	creation
	2018-03-21	mrobbins	updated to calculate hard and soft bounces on helds - ALCHEMISTS 335
	2018-03-28	mrobbins	updated to exclude helds for bounces

	sfdc_subscriber_status_id	sfdc_subscriber_status

	1							active
	2							bounce
	3							held - hard bounce
	4							unsubscribe
	5							held - soft bounce


*********************************************************************************/
	
begin try

	declare @response_code int,
			@message varchar(100)

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.) Find helds
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @helds table (held_id INT IDENTITY(1,1),
		subscriber_id int,
		subscriber_key [varchar](255) NULL);

	declare @customer_held table (customer_id int,
		subscriber_id int)

		
	insert into @helds (subscriber_id, subscriber_key)
	select distinct ets.subscriber_id,
		ets.subscriber_key
	from exact_target_subscriber ets
	where ets.activity = 'held'
		AND EXISTS(
			SELECT customer_email 
			FROM dbo.exact_target_subscriber ets2 
			WHERE ets.customer_email = ets2.customer_email 
				AND ets2.bounce_category in ('soft bounce','Technical/Other bounce'))

	insert into sfdc_subscriber_history(sfdc_subscriber_id,subscriber_id, subscriber_status_id)
	select sfdc_s.sfdc_subscriber_id,
		sfdc_s.subscriber_id, 
		sfdc_s.subscriber_status_id
	from sfdc_subscriber sfdc_s
		inner join @helds h
			on sfdc_s.subscriber_id = h.subscriber_id

	update sfdc_s
	set subscriber_status_id = 5,
		modified_date = getdate(),
		modified_by = suser_sname()
	from sfdc_subscriber sfdc_s
		inner join @helds h
			on sfdc_s.subscriber_id = h.subscriber_id

	

	insert into sfdc_subscriber(subscriber_id, subscriber_status_id)
	select h.subscriber_id,
		5 subscriber_status_id
	from @helds h
	where not exists (select subscriber_id from sfdc_subscriber sfdc_s where sfdc_s.subscriber_id = h.subscriber_id)


	insert into sfdc_subscriber_customer (customer_id, subscriber_id)
	select ce.customer_id,
		h.subscriber_id
	from customer_email ce
		inner join @helds h
			on ce.customer_email = h.subscriber_key

	DELETE FROM  @helds

	DELETE FROM @customer_held

		
	insert into @helds (subscriber_id, subscriber_key)
	select distinct ets.subscriber_id,
		ets.subscriber_key
	from exact_target_subscriber ets
	where ets.activity = 'held'
		AND EXISTS(
			SELECT customer_email 
			FROM dbo.exact_target_subscriber ets2 
			WHERE ets.customer_email = ets2.customer_email 
				AND ets2.bounce_category = 'hard bounce')

	insert into sfdc_subscriber_history(sfdc_subscriber_id,subscriber_id, subscriber_status_id)
	select sfdc_s.sfdc_subscriber_id,
		sfdc_s.subscriber_id, 
		sfdc_s.subscriber_status_id
	from sfdc_subscriber sfdc_s
		inner join @helds h
			on sfdc_s.subscriber_id = h.subscriber_id

	update sfdc_s
	set subscriber_status_id = 3,
		modified_date = getdate(),
		modified_by = suser_sname()
	from sfdc_subscriber sfdc_s
		inner join @helds h
			on sfdc_s.subscriber_id = h.subscriber_id

	

	insert into sfdc_subscriber(subscriber_id, subscriber_status_id)
	select h.subscriber_id,
		3 subscriber
_status_id
	from @helds h
	where not exists (select subscriber_id from sfdc_subscriber sfdc_s where sfdc_s.subscriber_id = h.subscriber_id)


	insert into sfdc_subscriber_customer (customer_id, subscriber_id)
	select ce.customer_id,
		h.subscriber_id
	from customer_email ce
		inner join @helds h
			on ce.customer_email = h.subscriber_key


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.) Find bounces
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------



	declare @bounces table (bounce_id INT IDENTITY(1,1),
		subscriber_id int,
		subscriber_key [varchar](255) NULL);

	declare @customer_bounce table (customer_id int,
		subscriber_id int)

		
	insert into @bounces (subscriber_id, subscriber_key)
	SELECT distinct subscriber_id,
		subscriber_key
	from exact_target_subscriber ets
	where activity = 'bounce'
		AND NOT EXISTS(
			SELECT customer_email 
			FROM dbo.exact_target_subscriber ets2 
			WHERE ets.customer_email = ets2.customer_email 
				AND ets2.activity = 'held')


	insert into sfdc_subscriber_history(sfdc_subscriber_id,subscriber_id, subscriber_status_id)
	select sfdc_s.sfdc_subscriber_id,
		sfdc_s.subscriber_id, 
		sfdc_s.subscriber_status_id
	from sfdc_subscriber sfdc_s
		inner join @bounces b
			on sfdc_s.subscriber_id = b.subscriber_id

	update sfdc_s
	set subscriber_status_id = 2,
		modified_date = getdate(),
		modified_by = suser_sname()
	from sfdc_subscriber sfdc_s
		inner join @bounces b
			on sfdc_s.subscriber_id = b.subscriber_id

	

	insert into sfdc_subscriber(subscriber_id, subscriber_status_id)
	select b.subscriber_id,
		2 subscriber_status_id
	from @bounces b
	where not exists (select subscriber_id from sfdc_subscriber sfdc_s where sfdc_s.subscriber_id = b.subscriber_id)

	insert into sfdc_subscriber_customer (customer_id, subscriber_id)
	select ce.customer_id,
		b.subscriber_id
	from customer_email ce
		inner join @bounces b
			on ce.customer_email = b.subscriber_key


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--3.) Find unsubs
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	declare @unsubscribe table (unsubscribe_id INT IDENTITY(1,1),
		subscriber_id int,
		subscriber_key [varchar](255) NULL);

	declare @customer_unsubscribe table (customer_id int,
		subscriber_id int)

		
	insert into @unsubscribe (subscriber_id, subscriber_key)
	select distinct subscriber_id,
		subscriber_key
	from exact_target_subscriber
	where activity = 'Unsubscribe'

	insert into sfdc_subscriber_history(sfdc_subscriber_id,subscriber_id, subscriber_status_id)
	select sfdc_s.sfdc_subscriber_id,
		sfdc_s.subscriber_id, 
		sfdc_s.subscriber_status_id
	from sfdc_subscriber sfdc_s
		inner join @unsubscribe u
			on sfdc_s.subscriber_id = u.subscriber_id

	update sfdc_s
	set subscriber_status_id = 4,
		modified_date = getdate(),
		modified_by = suser_sname()
	from sfdc_subscriber sfdc_s
		inner join @unsubscribe u
			on sfdc_s.subscriber_id = u.subscriber_id

	insert into sfdc_subscriber(subscriber_id, subscriber_status_id)
	select u.subscriber_id,
		4 subscriber_status_id
	from @unsubscribe u
	where not exists (select subscriber_id from sfdc_subscriber sfdc_s where sfdc_s.subscriber_id = u.subscriber_id)

	insert into sfdc_subscriber_customer (customer_id, subscriber_id)
	select ce.customer_id,
		u.subscriber_id
	from customer_email ce
		inner join @unsubscribe u
			on ce.customer_email = u.subscriber_key

	--Update customer opt stat
us and force a license check update
	update c
	set opt_in = 0,
		modified_date = getdate(),
		modified_by = suser_sname()
	from customer c
		inner join customer_email ce
			on c.customer_id = ce.customer_id
		inner join @unsubscribe u
			on ce.customer_email = u.subscriber_key
	where c.opt_in = 1

	insert into license_check_update_license (license_id,[source],insertdate)
	select distinct license_id,9,getdate()
	from customer c
		inner join customer_email ce
			on c.customer_id = ce.customer_id
		inner join @unsubscribe u
			on ce.customer_email = u.subscriber_key
		inner join license l
			on c.customer_id = l.license_id
	where cast(c.modified_date as date) = cast(getdate() as date)
		

	

end try
begin catch

	set @response_code = -200
	set @message = 'Could not insert subscriber'

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_insert_subscriber_held]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_insert_subscriber_held]
(
		@process_date datetime = null 
)


/*	
	DATE		AUTHOR		REMARKS
	2018-03-21	mrobbins	initial creation
	2018-04-12	mrobbins	changed to use sky_license_activity
	2019-09-25	mrobbins	changed to look in AR table for today's mail_date 
								held - soft bounce						enable
								held - hard bounce
									if webbula webroot status is valid	enable
									if no webbula record/not valid
										activity within 180 days		enable
										order within 90 days			enable


	DESCRIPTION
	
	
*/


AS

	BEGIN TRY

		DECLARE @response_code INT,
				@message VARCHAR(100),
				@date_value DATETIME 

		SET NOCOUNT ON 


		IF @process_date is null
			BEGIN
				SELECT @date_value = CAST(GETDATE() AS DATE)
			END
		ELSE
			SELECT @date_value = @process_date

		DECLARE @soft_bounces TABLE(soft_bounces_id INT IDENTITY(1,1) NOT NULL,
			sfdc_subscriber_id INT,
			subscriber_key VARCHAR(255) NOT NULL,
			member_id INT,
			customer_email VARCHAR(100),
			license_id INT,
			customer_id INT,
			update_opt_in INT)

		DECLARE @auto_renewal TABLE(auto_renewal_id INT IDENTITY(1,1) NOT NULL,
			sfdc_subscriber_id INT,
			subscriber_key VARCHAR(255) NOT NULL,
			customer_email VARCHAR(100),
			customer_id INT,
			license_id INT,
			enable INT DEFAULT 0)

		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.) Find soft helds
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		INSERT INTO @soft_bounces(subscriber_key,member_id,sfdc_subscriber_id,customer_email,license_id,customer_id,update_opt_in)
		SELECT DISTINCT ets.subscriber_key,
			ets.member_id,
			s.sfdc_subscriber_id,
			ets.customer_email,
			l.license_id,
			ce.customer_id,
			1 update_opt_in
		FROM dbo.sfdc_subscriber s
			INNER JOIN dbo.exact_target_subscriber ets
				ON s.subscriber_id = ets.subscriber_id
			INNER JOIN customer_email ce
				ON ets.customer_email = ce.customer_email
			INNER JOIN license l
				ON ce.customer_id = l.customer_id
		WHERE s.subscriber_status_id = 5
			--AND CAST(s.modified_date AS DATE) = CAST(@date_value AS date)
		UNION
        SELECT DISTINCT ets.subscriber_key,
			ets.member_id,
			s.sfdc_subscriber_id,
			ets.customer_email,
			l.license_id,
			ce.customer_id,
			1 update_opt_in
		FROM dbo.sfdc_subscriber s
			INNER JOIN dbo.exact_target_subscriber ets
				ON s.subscriber_id = ets.subscriber_id
			INNER JOIN customer_email ce
				ON ets.customer_email = ce.customer_email
			INNER JOIN license_customer lc
				ON ce.customer_id = lc.customer_id
			INNER JOIN license l
				ON lc.license_id = l.license_id
		WHERE s.subscriber_status_id = 5
			--AND CAST(s.modified_date AS DATE) = CAST(@date_value AS date)
		
		INSERT INTO @auto_renewal
		(
			sfdc_subscriber_id,
			subscriber_key,
			customer_email,
			customer_id,
			license_id
		)
		SELECT DISTINCT ss.sfdc_subscriber_id,
			arm.customer_email sfdc_subscriber_key,
			arm.customer_email,
			arm.customer_id,
			arm.license_id
		FROM dbo.sfdc_subscriber ss
			INNER JOIN dbo.sfdc_subscriber_customer ssc
				ON ss.subscriber_id = ssc.subscriber_id
			INNER JOIN customer_email ce
				ON ssc.customer_id = ce.customer_id
			INNER JOIN dbo.auto_renewal_message arm
				ON ce.customer_email = arm.customer_email
					AND CAST(arm.mail_date AS DATE) = CAST(@date_value AS DATE)
			--INNER JOIN license l
			--	ON ce.customer_id = l.
customer_id
		WHERE ss.subscriber_status_id = 3  --held - hard bounce
	


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.) Update records to not be opted out if activity or order
	--		check webbula,activity, and orders for AR notification 
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		UPDATE s
		SET s.update_opt_in = 0
		FROM (SELECT s.sfdc_subscriber_id,
					MAX(la.effective_date) effective_date
					from sky_license_activity la
						inner join @soft_bounces s
							on la.license_id = s.license_id
					group by s.sfdc_subscriber_id) a
			INNER JOIN @soft_bounces s
				ON a.sfdc_subscriber_id = s.sfdc_subscriber_id
		WHERE a.effective_date >= @date_value - 90


		UPDATE s
		SET s.update_opt_in = 0
		FROM (SELECT s.sfdc_subscriber_id,
					MAX(oh.vendor_order_date) vendor_order_date
					from  @soft_bounces s
							INNER JOIN order_item_license oil
								ON s.license_id = oil.license_id
							INNER JOIN order_item oi
								ON oi.order_item_id = oil.order_item_id
							INNER JOIN dbo.order_header oh
								ON oi.order_header_id = oh.order_header_id
					group by s.sfdc_subscriber_id) a
			INNER JOIN @soft_bounces s
				ON a.sfdc_subscriber_id = s.sfdc_subscriber_id
		WHERE a.vendor_order_date >= @date_value - 30
			AND NOT EXISTS(SELECT ssh.sfdc_subscriber_id FROM sfdc_subscriber_held ssh WHERE s.sfdc_subscriber_id = ssh.sfdc_subscriber_id AND CAST(ssh.insert_date AS DATE) = CAST(@date_value AS DATE))

		
		UPDATE ar
		SET ar.enable = 1
		FROM @auto_renewal ar
			INNER JOIN dbo.customer_email_verification cev
				ON ar.customer_id = cev.customer_id
			INNER JOIN dbo.customer_email_verification_status cevs
				ON cev.customer_email_verification_status_id = cevs.customer_email_verification_status_id
		WHERE cevs.webroot_status = 'valid'
			AND ar.enable = 0

		UPDATE ar
		SET ar.enable = 1
		FROM (SELECT a.sfdc_subscriber_id,
					MAX(la.effective_date) effective_date
					from sky_license_activity la
						inner join @auto_renewal a
							on la.license_id = a.license_id
					group by a.sfdc_subscriber_id) a
			INNER JOIN @auto_renewal ar
				ON a.sfdc_subscriber_id = ar.sfdc_subscriber_id
		WHERE a.effective_date >= @date_value - 180
			AND ar.enable = 0

		UPDATE ar
		SET ar.enable = 1
		FROM (SELECT ar.sfdc_subscriber_id,
					MAX(oh.vendor_order_date) vendor_order_date
					from  @auto_renewal ar
							INNER JOIN order_item_license oil
								ON ar.license_id = oil.license_id
							INNER JOIN order_item oi
								ON oi.order_item_id = oil.order_item_id
							INNER JOIN dbo.order_header oh
								ON oi.order_header_id = oh.order_header_id
					group by ar.sfdc_subscriber_id) a
			INNER JOIN @auto_renewal ar
				ON ar.sfdc_subscriber_id = a.sfdc_subscriber_id
		WHERE a.vendor_order_date >= @date_value - 90
			AND ar.enable = 0


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--3.) Insert into sfdc_subscriber_held to be processed by PHP
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


		INSERT INTO sfdc_subscriber_held(sfdc_subscriber_id,sfdc_subscriber_key, customer_email, member_id)
		SELECT DISTINCT s.sfdc_subscriber_id,
			s.subscriber_key, 
			s.customer_email, 
			s.member_id
		FROM @soft_bounces s

		--held - soft bounce update
		INSERT INTO sfdc_subscriber_held(sfdc_subscriber_id,sfdc_subscriber_key, 
customer_email, member_id)
		SELECT DISTINCT ss.sfdc_subscriber_id,
			arm.customer_email sfdc_subscriber_key,
			arm.customer_email,
			6011120 member_id
		FROM dbo.sfdc_subscriber ss
			INNER JOIN dbo.sfdc_subscriber_customer ssc
				ON ss.subscriber_id = ssc.subscriber_id
			INNER JOIN customer_email ce
				ON ssc.customer_id = ce.customer_id
			INNER JOIN dbo.auto_renewal_message arm
				ON ce.customer_email = arm.customer_email
					AND CAST(arm.mail_date AS DATE) = CAST(@date_value AS DATE)
		WHERE ss.subscriber_status_id = 5

		--held - hard bounce that match criteria need to be updated
		INSERT INTO sfdc_subscriber_held(sfdc_subscriber_id,sfdc_subscriber_key, customer_email, member_id)
		SELECT DISTINCT sfdc_subscriber_id,
			customer_email sfdc_subscriber_key,
			customer_email,
			6011120 member_id
		FROM @auto_renewal
		WHERE enable = 1

		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--4.) Update customer opt status
	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		UPDATE c
		SET c.opt_in = 0,
			c.modified_date = GETDATE(),
			c.modified_by = 'held processing'
		FROM @soft_bounces sb
			INNER JOIN customer c
				ON sb.customer_id = c.customer_id
		WHERE c.opt_in = 1
			AND sb.update_opt_in = 1

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = 'Could not insert held subscriber'

		DECLARE @DBName nvarchar(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_opportunity_failure_report]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_opportunity_failure_report]
    @from_date DATETIME,
    @to_date DATETIME,
    @send_email BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @subject VARCHAR(255),
                @filename VARCHAR(255),
                @body NVARCHAR(MAX),
                @statement NVARCHAR(MAX),
                @tab CHAR(1) = CHAR(9),
                @profile_name sysname,
                @recipients NVARCHAR(MAX);

        SET @subject = FORMAT(@to_date, 'yyyy-MM-dd') + ' - SFDC Opportunity Failures';
        SET @filename = 'sfdc_opportunity_failures_' + FORMAT(@to_date, 'yyyy-MM-dd') + '.csv';
        SET @profile_name = 'DBA';

        SET @body
            = N'
        <html><body>
        <h2>SFDC Opportunity Failure Report</h2>
        <p>Attached is the SFDC opportunity failure report for the past 30 days.</p>
        <p>This report is generated from eCommerce database.</p>
        </body></html>';

        --GET recipients list from app config function
        SELECT @recipients = value
        FROM dbo.fn_app_config_select_key_values('SFDC_OPPORTUNITY_FAILURE_BILLING_REPORT', 'SQL_SERVER_AGENT_JOBS');

        --Clean up global temp table if exists
        IF OBJECT_ID('tempdb..##FailureReport') IS NOT NULL
            DROP TABLE ##FailureReport;

        --Dump results into global temp table
        SELECT *
        INTO ##FailureReport
        FROM
        (
            SELECT oil.license_id,
                   fn.keycode,
                   fn.license_category_name AS Category,
                   fn.license_seats,
                   c.company_name,
                   f1.order_header_id,
                   vo.vendor_order_code,
                   oh.vendor_order_date,
                   fn.start_date AS Activated_Date,
                   fn.expiration_date AS Expiration_Date,
                   oo.salesforce_opportunity_id,
                   so.sap_order_number,
                   fn.license_attribute_license_value_description AS Billing_Model,
                   oh.total_amount,
                   oh.sub_total_amount,
                   oh.payment_method_id,
                   f1.sfdc_response_message,
                   f1.failure_date,
                   oh.exchange_rate,
                   oh.site_id,
                   oh.site_url,
                   CASE
                       WHEN leo.effective_object_id = 3 THEN
                           leo.effective_value
                       ELSE
                           NULL
                   END AS Billing_Date,
                   pm.merchant_id,
                   pm.payment_merchant_name,
                   ROW_NUMBER() OVER (PARTITION BY oil.license_id,
                                                   vo.vendor_order_code
                                      ORDER BY oil.license_id
                                     ) AS ROWNUM
            FROM dbo.sfdc_opportunity_update_failure f1
                INNER JOIN dbo.order_header oh
                    ON oh.order_header_id = f1.order_header_id
                INNER JOIN dbo.order_item oi
                    ON oi.order_header_id = oh.order_header_id
                INNER JOIN dbo.order_item_license oil
                    ON oil.order_item_id = oi.order_item_id
                INNER JOIN dbo.vendor_order vo
                    ON vo.vendor_order_id = oh.vendor_order_id
                INNER JOIN dbo.order_company oc
                    ON oc.order_header_id = oh.order_header_id
                INNER JOIN dbo.company c
                    ON c.company_id = oc.company_id
                LEFT JOIN dbo.sap_order so
                    ON so.order_header_id = oh.orde
r_header_id
                LEFT JOIN dbo.order_opportunity oo
                    ON oo.order_header_id = oh.order_header_id
                LEFT JOIN dbo.license_effective_object leo
                    ON leo.license_id = oil.license_id
                       AND leo.effective_object_id = 3
                LEFT JOIN dbo.order_payment_header oph
                    ON oph.order_header_id = f1.order_header_id
                LEFT JOIN dbo.payment_header ph
                    ON ph.payment_header_id = oph.payment_header_id
                LEFT JOIN dbo.payment_status ps
                    ON ps.payment_status_id = ph.payment_status_id
                LEFT JOIN dbo.payment_merchant pm
                    ON pm.payment_merchant_id = ph.payment_merchant_id
                OUTER APPLY dbo.fn_license_select_license_profile(oil.license_id) fn
                LEFT JOIN dbo.sfdc_opportunity_update_archive a
                    ON a.order_header_id = f1.order_header_id
                       AND a.sfdc_template_id = 33
                       AND a.sfdc_update_type_id = 158
            WHERE a.order_header_id IS NULL
                  AND f1.failure_date
                  BETWEEN @from_date AND @to_date
                  AND oc.order_company_type_id = 1
                  AND fn.item_hierarchy_id = 1
                  AND leo.effective_start_date <= @to_date
                  AND
                  (
                      leo.effective_end_date >= @to_date
                      OR leo.effective_end_date IS NULL
                  )
        ) AS sub
        WHERE sub.ROWNUM = 1;

        SELECT *
        FROM ##FailureReport AS fr;

        SET @statement = N'SELECT * FROM ##FailureReport';

        --SEND email only if report has data
        IF @send_email = 1 AND EXISTS (SELECT 1 FROM ##FailureReport)
        BEGIN
            EXEC msdb.dbo.sp_send_dbmail @profile_name = @profile_name,
                                         @recipients = @recipients,
                                         @subject = @subject,
                                         @body = @body,
                                         @body_format = 'HTML',
                                         @query = @statement,
                                         @attach_query_result_as_file = 1,
                                         @query_result_separator = @tab,
                                         @query_result_no_padding = 1,
                                         @query_result_header = 1,
                                         @query_attachment_filename = @filename,
                                         @exclude_query_output = 0;
        END;
        ELSE
        BEGIN
            PRINT 'No data found for SFDC Opportunity Failure Report, email not sent.';
        --send notification email about no data found here if needed
        END;

        --Cleanup the table
        DROP TABLE IF EXISTS ##FailureReport;

    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        DECLARE @ErrProc sysname = ERROR_PROCEDURE();
        DECLARE @ErrLine INT = ERROR_LINE();
        DECLARE @DBName sysname = DB_NAME();

        PRINT 'Procedure: ' + @ErrProc + ', Line: ' + CAST(@ErrLine AS VARCHAR);

        EXEC usp_LogError @ErrorDB = @DBName;
    END CATCH;
END;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_process_opportunity_renewal]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_sfdc_process_opportunity_renewal]

/*
		DATE			AUTHOR			REMARKS
		2018-01-03		cnovac			Initial creation.
		2019-01-10		rvinoche		Support autobilling attributes living only in license_effective_object
		2019-03-13		cnovac			Updated to be able to run daily and update the sfdc_opportunity_renewal_status_id on AR records
		2019-04-10		cnovac			Updated to subtract day from capability_expiration_date when doing check to see if license expiration matches process date

		DESCRIPTION
		This proc does both update next renewals and processes SFDC orders marked for autorenewal
*/

as

declare      @response_code int,
             @message varchar(100),
             @license_id int = null,
             @sfdc_opportunity_renewal_status_id smallint = null,
             @sfdc_opportunity_id varchar(18) = null,
             @process_date date,
             @sfdc_update_json nvarchar(max) = null,
             @start_row int = 1,
             @inserted_rows int
declare @sfdc_opportunity_renewal table (id int identity (1, 1), sfdc_opportunity_renewal_id int, salesforce_renewal_opportunity_id varchar(18), usage_type varchar(50), license_id int, license_category_name varchar(50), quantity int, process_date date)

begin try

       update sor
       set sor.sfdc_opportunity_renewal_status_id = null,
             sor.modified_date = getdate()
       from dbo.sfdc_opportunity_renewal sor
       where sor.is_autorenewal_enabled = 1
       and (sor.sfdc_opportunity_renewal_status_id != 1 or sor.sfdc_opportunity_renewal_status_id is null)

       --update the renewal opp and set the process to renewal opp's close date as seen in SFDC
       --this step is basically just processing new requests which have come in
       update sor
       set sor.salesforce_renewal_opportunity_id = c.SBQQ__RenewalOpportunity__c,
             sor.process_date = c.EndDate,
             sor.modified_date = getdate()
       from dbo.sfdc_opportunity_renewal sor
       inner join dbo.order_opportunity oo on oo.order_opportunity_id = sor.order_opportunity_id
       inner join SALESFORCE.Salesforce.dbo.Contract c on c.SBQQ__Opportunity__c = oo.salesforce_opportunity_id and c.IsDeleted = 0
       where sor.is_autorenewal_enabled = 1
       and sor.sfdc_opportunity_renewal_status_id is null

       -------------------------------------------------------------------------------------------------------------------------------------------------
       -------------------------------------------------------------------------------------------------------------------------------------------------
       
       --now getting records which have AR on and have not updated sfdc_opportunity_renewal_status_id
       --this will be used for series of checks to validate the licenses on renewal opp
       insert into @sfdc_opportunity_renewal (sfdc_opportunity_renewal_id, salesforce_renewal_opportunity_id, usage_type, license_id, quantity, process_date, license_category_name)
       select sor.sfdc_opportunity_renewal_id, sor.salesforce_renewal_opportunity_id, oli.Usage_Type__c, l.Ecomm_License_Id__c, oli.Quantity, sor.process_date,
                case when p.Name like '%Endpoint Protection%' then 'SAEP'
                           when p.Name like '%DNS Protection%' then 'SDNS'
                           when p.Name like '%Security Awareness Training%' then 'SECA'
                           when p.Name like '%Mobile Protection%' then 'ADE'
                end
       from dbo.sfdc_opportunity_renewal sor
       inner join SALESFORCE.Salesforce.dbo.Opportunity o on o.id = sor.salesforce_renewal_opportunity_id
       inner join SALESFORCE.Salesforce.dbo.OpportunityLineItem oli on oli.Oppor
tunityId = o.id and oli.IsDeleted = 0
       inner join SALESFORCE.Salesforce.dbo.Product2 p on p.id = oli.Product2Id
       inner join SALESFORCE.Salesforce.dbo.License__c l on l.id = oli.License__c
       where sor.is_autorenewal_enabled = 1
       and sor.sfdc_opportunity_renewal_status_id is null

       select @inserted_rows = @@rowcount

       while @start_row <= @inserted_rows
       begin

             select @license_id = license_id
             from @sfdc_opportunity_renewal
             where id = @start_row

             --AR is not checked checked on renewal contract so mark the status to not process AR
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 2,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join SALESFORCE.Salesforce.dbo.Contract c on c.SBQQ__RenewalOpportunity__c = sor.salesforce_renewal_opportunity_id and c.IsDeleted = 0
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and isnull(c.Automatic_Renewal__c, 0) = 0

             --check to make sure SFDC opp is not deleted
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 3,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join SALESFORCE.Salesforce.dbo.Opportunity o on o.id = sor.salesforce_renewal_opportunity_id and o.IsDeleted = 1
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --check to make sure SFDC opp is not in stages '5. Closed-Won', 'Lost'
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 4,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join SALESFORCE.Salesforce.dbo.Opportunity o on o.id = sor.salesforce_renewal_opportunity_id and o.StageName in ('5. Closed-Won', 'Lost')
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --check to see if license record is defined and is a business keycode
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 5,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license l on l.license_id = temp.license_id and l.product_line_id not in (55, 300) --mobile business and all other business
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --check to see if license is active
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 6,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license l on l.license_id = temp.license_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and l.license_status_id != 1

             --check to see if license expiration matches process date
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 7,
                    sor.modifie
d_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license_category_license lcl on lcl.license_id = temp.license_id
             inner join dbo.license_category lcat on lcat.license_category_id = lcl.license_category_id
             inner join dbo.license_capability lc on lc.license_id = temp.license_id and lc.capability_id = lcat.base_capability_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and dateadd(dd, -1, cast(lc.capability_expiration_date as date)) != sor.process_date

             --check to see if license is a trial
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 8,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license_category_license lcl on lcl.license_id = temp.license_id
             inner join dbo.license_category lcat on lcat.license_category_id = lcl.license_category_id
             inner join dbo.license_capability lc on lc.license_id = temp.license_id and lc.capability_id = lcat.base_capability_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and lc.capability_type_id != 1 --not full

             --check to see if license is a child
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 9,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license_parent lp on lp.child_license_id = temp.license_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --check to see if license billing entity belongs to a partner
             update sor
             set sor.sfdc_opportunity_renewal_status_id = case
															when pl.partner_id = 5559 then null --Webroot Direct Partner
															else 10
														  end,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.partner_license pl on pl.license_id = temp.license_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and pl.partner_license_status_id = 2
             and pl.start_date <= sor.process_date
             and (pl.end_date > sor.process_date or pl.end_date is null)

             --check to see if billing model doesn't match ecomm
             update sor
             set sor.sfdc_opportunity_renewal_status_id = case
															when temp.usage_type is null and dbo.fn_license_select_effective_object_element(temp.license_id, lc.license_category_id, 'license_attribute_license_value', sor.process_date) not in (0, 2, 3, 10, 20) then 11
															when temp.usage_type = 'Overage' and dbo.fn_license_select_effective_object_element(temp.license_id, lc.license_category_id, 'license_attribute_license_value', sor.process_date) != 11 then 11
															when temp.usage_type != 'Overage' then 11
														  end,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.license_category lc on lc.license_category_name = temp.license_category_name
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunit
y_renewal_id = temp.sfdc_opportunity_renewal_id
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --seats in ecomm doesn't match seats on renewal opp
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 13,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.fn_license_select_license_profile(@license_id) lprofile on lprofile.license_id = temp.license_id and lprofile.license_category_name = temp.license_category_name
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null
             and temp.quantity != lprofile.license_seats

             --make sure there's no pending license_message record for renewal
             update sor
             set sor.sfdc_opportunity_renewal_status_id = 14,
                    sor.modified_date = getdate()
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             inner join dbo.license_message lm on lm.license_id = temp.license_id and lm.message_type_id = 3 and lm.message_status_id = 1 --autorenewal and pending
             where temp.id = @start_row
             and sor.sfdc_opportunity_renewal_status_id is null

             --now query the record status and opp id which was just processed
             select @sfdc_opportunity_renewal_status_id = sor.sfdc_opportunity_renewal_status_id,
                           @sfdc_opportunity_id = sor.salesforce_renewal_opportunity_id,
                           @process_date = sor.process_date
             from @sfdc_opportunity_renewal temp
             inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
             where temp.id = @start_row

             if @sfdc_opportunity_renewal_status_id is null and @sfdc_opportunity_id is not null and @process_date <= dateadd(dd, 7, cast(getdate() as date)) --this basically means we found no issues
             begin

                    --check to see if primary quote is set on renewal opp, moved inside this piece of code to only process on AR date as
                    --there's a sfdc process that only runs on AR date to set this
                    update sor
                    set sor.sfdc_opportunity_renewal_status_id = 12,
                           sor.modified_date = getdate()
                    from @sfdc_opportunity_renewal temp
                    inner join dbo.sfdc_opportunity_renewal sor on sor.sfdc_opportunity_renewal_id = temp.sfdc_opportunity_renewal_id
                    inner join SALESFORCE.Salesforce.dbo.Opportunity o on o.id = sor.salesforce_renewal_opportunity_id
                    where temp.id = @start_row
                    and sor.sfdc_opportunity_renewal_status_id is null
                    and o.SBQQ__PrimaryQuote__c is null

                    if @@ROWCOUNT = 0
                    begin
             
                           select @sfdc_update_json = (select sfdc_opportunity_id = @sfdc_opportunity_id for json path, without_array_wrapper)

                           exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = 'book_sfdc_auto_renew', @sfdc_update_json = @sfdc_update_json

                           update sor
                           set sor.sfdc_opportunity_renewal_status_id = 1,
                                 sor.modified_date = getdate()
                           from @sfdc_opportunity_renewal temp
                           inner join dbo.sfdc_opportunity_renewal sor on sor.salesforce_renewal_opportunity_id = temp.salesforce_renewal_opportunity_id
    
                       where temp.id = @start_row
                           and sor.sfdc_opportunity_renewal_status_id is null

                    end

             end

             set @start_row = @start_row + 1
             set @license_id = null
             set @sfdc_opportunity_renewal_status_id = null
             set @sfdc_opportunity_id = null

       end

--Aggregator***(failure)
--Annual Subscription(no attribute)
--Annual Subscription with Excess Usage***
--Excess Usage PO***(failure)
--Monthly Usage Subscription***(failure)
--Not For Resale (NFR)***(failure)

end try


begin catch

       set @response_code = -200
       set @message = case when @message is null then 'usp_sfdc_process_opportunity_renewal failure'
                                        else @message end

       declare @DBName nvarchar(128)
       set @DBName = db_name()
       exec usp_LogError @ErrorDB = @DBName
             
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_all_subs_batch]
-- =============================================================================


