CREATE PROCEDURE [dbo].[usp_sfdc_select_all_subs_batch]

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial creation

	DESCRIPTION
	Used to get batchdate for cron
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	SELECT batch_count = count(*), batch_limit_date = GETDATE()
	FROM license_message
	WHERE message_status_id in (1) 
		and message_type_id = 15
		AND process_date <= GETDATE()

GO
