CREATE PROCEDURE [dbo].[usp_sfdc_select_campaign]

(
	@sfdc_campaign_id varchar(50)
)

/*	
	DATE		AUTHOR		REMARKS
	2020-09-21	cnovac		Initial creation on this day.
	2022-04-07  psatish		ALM:1028 Fetch the OT Campaign id 

	DESCRIPTION
	This proc is used to query and get the OT SFDC campaign ID from Webroot Old org

*/

AS

	begin try

	select sfdc_campaign_OT
	from sfdc_campaign
	where sfdc_campaign_old_org = @sfdc_campaign_id
	or sfdc_campaign_new_org = @sfdc_campaign_id
	or sfdc_campaign_OT = @sfdc_campaign_id

	end try

	begin catch

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_case]
-- =============================================================================

CREATE procedure [dbo].[usp_sfdc_select_case]


(
	@salesforce_case_id varchar(18) = null,
	@license_id int = null,
	@parent_sfdc_case_id int = null,
	@sfdc_case_status_name varchar(50) = null,
	@sfdc_case_type_name varchar(50) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2020-12-03	esmart		Initial creation.

	DESCRIPTION
	select case
*/

as

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select c.sfdc_case_id, c.license_id, c.salesforce_case_id, c.parent_sfdc_case_id, c.case_create_json, t.sfdc_case_type_id, t.sfdc_case_type_name, s.sfdc_case_status_id, s.sfdc_case_status_name, c.insert_date, c.modified_date
		from sfdc_case c
		inner join sfdc_case_status s
			on s.sfdc_case_status_id = c.sfdc_case_status_id
		inner join sfdc_case_type t
			on t.sfdc_case_type_id = c.sfdc_case_type_id
		where c.salesforce_case_id = case when @salesforce_case_id is null then c.salesforce_case_id else @salesforce_case_id end and
			c.license_id = case when @license_id is null then c.license_id else @license_id end and
			s.sfdc_case_status_name = case when @sfdc_case_status_name is null then s.sfdc_case_status_name else @sfdc_case_status_name end and
			t.sfdc_case_type_name = case when @sfdc_case_type_name is null then t.sfdc_case_type_name else @sfdc_case_type_name end 
			--and	c.parent_sfdc_case_id = case when @parent_sfdc_case_id is null then c.parent_sfdc_case_id else @parent_sfdc_case_id end
		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 



GO
