-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_sfdc_select_in_journey_batch]

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial creation

	DESCRIPTION
	Used to get batchdate for cron
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	SELECT batch_count = count(*), batch_limit_date = GETDATE()
	FROM license_message lm
	WHERE message_status_id = 1 
		and lm.message_type_id = 17
		AND lm.process_date <= GETDATE()
		AND NOT EXISTS
			(SELECT license_message_id 
				FROM license_message_value lmv 
				WHERE lm.license_message_id = lmv.license_message_id
					AND message_value_type_id = 23
					AND lmv.value_id = 1)


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_license_message_journey]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_license_message_journey]

(
       @license_id INT 
)

/*     
       DATE                 AUTHOR        REMARKS

       2017-08-02           mrobbins             Initial creatiON


       DESCRIPTION
       Selects journey campaign for license
*/

AS
       SET NOCOUNT ON                           

    DECLARE @keycode VARCHAR(40) ,
        @license_distributiON_method_id INT ,
        @license_seats INT ,
        @license_category_id INT ,
        @product_line_id INT ,
        @capability_type_id TINYINT ,
        @trial TINYINT ,
        @autorenewal_opt_id TINYINT ,
        @opt_in INT ,
        @activity_date DATE ,
        @devices INT ,
        @devices_str VARCHAR(10) ,
        @activation_date DATETIME ,
        @expiration_date DATETIME ,
        @license_key VARCHAR(36) ,
        @run_date DATETIME ,
        @license_status_id INT ,
        @contract_detail_update INT ,
        @max_threats_removed FLOAT ,
        @subscription_id INT ,
        @subscription_type_id INT ,
        @renewal_status TINYINT ,
        @respONse_code INT ,
        @message VARCHAR(100) ,
        @language_code VARCHAR(2) ,
        @location_code VARCHAR(3) ,
        @old_swap_license INT ,
        @new_swap_license INT,
              @refund INT,
              @non_mail_disti INT,
              @email_engine_start INT;


       BEGIN TRY


       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) SELECT
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              
              SET @run_date = GETDATE()

              SELECT @location_code = ISNULL(location_code,'USA'),
                     @language_code = ISNULL(language_code,'EN')
              FROM license l
                     LEFT JOIN customer_locale cl
                           ON l.customer_id = cl.customer_id
              WHERE l.license_id = @license_id

              SET @old_swap_license = 0

              SELECT @old_swap_license = COUNT(*)
              FROM license_swap
              WHERE original_license_id = @license_id  
                     and license_swap_status_id = 2


              SET @new_swap_license = 0

              SELECT @new_swap_license = COUNT(*)
              FROM license_swap
              WHERE new_license_id = @license_id 
                     and license_swap_status_id = 2

              

              -- 1.1) SELECT license_capability_history data

              DECLARE @license_capability_history TABLE ([license_id] [int],[capability_activation_date] [datetime] NULL)
                     
              INSERT INTO @license_capability_history
              SELECT lch.license_id, 
                     MIN(lch.capability_activation_date) AS capability_activation_date
              FROM license_capability_history lch 
              WHERE lch.license_id = @license_id
              GROUP BY lch.license_id

              
              -- 1.2) SELECT license data
              SELECT @license_id = ls.license_id,
                           @license_distribution_method_id = ls.license_distribution_method_id,
                           @license_seats = ls.license_seats,
                           @license_category_id =     ls.license_category_id,
                           @product_line_id = ls.product_line_id,
                           @capability_type_id = ls.capabil
ity_type_id,
                           @activation_date = CASE WHEN lch.capability_activation_date IS NULL THEN 
                                  ls.capability_activation_date
                           ELSE lch.capability_activation_date 
                           END,
                           @expiration_date = ls.capability_expiration_date,
                           @license_key = ls.license_key,
                           @subscription_id = ls.subscription_id,
                           @subscription_type_id = ls.subscription_type_id,
                           @autorenewal_opt_id = ls.autorenewal_opt_id,
                           @opt_in = ls.opt_in,
                           @license_status_id = ls.license_status_id,
                           @contract_detail_update = CASE WHEN ls.contract_detail_update = 1 THEN 1 ELSE 0 END
              FROM license_summary ls WITH (NOLOCK)
                     LEFT JOIN @license_capability_history lch 
                                  ON ls.license_id = lch.license_id
              WHERE ls.license_id = @license_id


              --SELECT      @license_id license_id,
              --            @license_distribution_method_id license_distribution_method_id,
              --            @license_seats license_seats,
              --            @license_category_id license_category_id,
              --            @product_line_id product_line_id,
              --            @capability_type_id capability_type_id,
              --            @activation_date capability_activation_date,
              --            @expiration_date capability_expiration_date,
              --            @license_key license_key,
              --            @subscription_id subscription_id,
              --            @subscription_type_id subscription_type_id,
              --            @autorenewal_opt_id autorenewal_opt_id,
              --            @opt_in opt_in,
              --            @license_status_id license_status_id,
              --            @contract_detail_update contract_detail_update

              -- 1.2) -- get license data IF @license_summary does not exist
              IF @license_id is null
                     BEGIN

                     SELECT @keycode = keycode
                     FROM license
                     WHERE license_id = @license_id

                     DECLARE @license_summary TABLE (
                           license_id INT,
                           license_key UNIQUEIDENTIFIER,
                           keycode VARCHAR(40),
                           license_distribution_method_id INT,
                           license_type_id TINYINT,
                           license_status_id TINYINT,
                           product_line_id SMALLINT,
                           license_seats INT,
                           license_category_id TINYINT,
                           opt_in INT,
                           autorenewal_opt_id TINYINT,
                           capability_id TINYINT,
                           capability_type_id TINYINT,
                           capability_activation_date DATETIME NULL,
                           capability_expiration_date DATETIME NULL,
                           subscription_id INT NULL,
                           serial_number VARCHAR(19) NULL,
                           contract_id VARCHAR(10) NULL,
                           contract_detail_update INT NULL,
                           subscription_type_id TINYINT NULL, 
                           keycode_alias VARCHAR(40) NULL)


                     INSERT INTO @license_summary(license_id, license_key, keycode, license_distribution_method_id, license_type_id, license_status_id, product_line_id, license_seats, license_category_id, opt_in, autorenewal_opt_id, capability_id, capability_type_id, capability_activation_date, capability_expiration_date, subscription_id, serial_number, contract_
id, contract_detail_update, subscription_type_id, keycode_alias)
                     EXEC usp_license_SELECT_license_summary_data  @keycode

                     SELECT @license_id = ls.license_id,
                           @license_distribution_method_id = ls.license_distribution_method_id,
                           @license_seats = ls.license_seats,
                           @license_category_id =     ls.license_category_id,
                           @product_line_id = ls.product_line_id,
                           @capability_type_id = ls.capability_type_id,
                           @activation_date = CASE WHEN lch.capability_activation_date IS NULL THEN 
                                  ls.capability_activation_date
                           ELSE lch.capability_activation_date 
                           END,
                           @expiration_date = ls.capability_expiration_date,
                           @license_key = ls.license_key,
                           @subscription_id = ls.subscription_id,
                           @subscription_type_id = ls.subscription_type_id,
                           @autorenewal_opt_id = ls.autorenewal_opt_id,
                           @opt_in = ls.opt_in,
                           @license_status_id = ls.license_status_id,
                           @contract_detail_update = CASE WHEN ls.contract_detail_update = 1 THEN 1 ELSE 0 END
                     FROM @license_summary ls
                           LEFT JOIN @license_capability_history lch
                                  ON ls.license_id = lch.license_id

                     --SELECT * FROM @license_summary

                     END

              SELECT @non_mail_disti = COUNT(*)
              FROM license_distribution_method_channel ldmc WITH (NOLOCK)
                     inner join distribution_class dc WITH (NOLOCK)
                           on ldmc.distribution_class_id = dc.distribution_class_id
              WHERE ldmc.license_distribution_method_id = @license_distribution_method_id
                     and dc.distribution_class in ('banking','partner','s2')

              --If the license started their renewal cycle in the email engine they need to continue through that engine
              SELECT @email_engine_start = COUNT(*)
              FROM dbo.exact_target_batch etb  WITH (NOLOCK)
                     INNER JOIN dbo.exact_target_master etm  WITH (NOLOCK)
                           ON etb.exact_target_master_id = etm.exact_target_master_id
                     INNER JOIN dbo.exact_target_message_campaign etmc  WITH (NOLOCK)
                           ON etm.exact_target_message_campaign_id = etmc.exact_target_message_campaign_id
              WHERE etmc.message_campaign_exact_target_name = 'ren3monthleft'
                     AND etb.mail_date = CAST(@expiration_date - 90 AS DATE)
                     AND @expiration_date >= GETDATE() - 90
                     AND etb.license_id = @license_id

              SELECT @refund = COUNT(*)
              FROM (
                           select max(oh.order_header_id) order_header_id,
                                  oil.license_id
                           from order_item_license oil  WITH (NOLOCK)
                                  inner join order_item oi  WITH (NOLOCK)
                                         on oil.order_item_id = oi.order_item_id
                                  inner join order_header oh  WITH (NOLOCK)
                                         on oi.order_header_id = oh.order_header_id
                           WHERE oil.license_id = @license_id
                           GROUP BY oil.license_id) A
                     INNER JOIN order_header oh  WITH (NOLOCK)
                           ON a.order_header_id = oh.order_header_id
              WHERE oh.order_status_id = 3
                     --AND @expiration_date <= GETDATE()

              -- 1.3.1) @devices
      
        SELECT @devices = devices FROM license_usage_license  WITH (NOLOCK) WHERE license_id = @license_id 

              -- 1.3.2) SET @renewal_status value
              SELECT @renewal_status = CASE WHEN count(license_id) > 0 THEN 1 ELSE 0 END FROM license_renewals  WITH (NOLOCK) WHERE license_id = @license_id

              -- 1.4) @trial 
              SELECT @trial = CASE WHEN @capability_type_id in (2,3) THEN 1 ELSE 0 END
              --SELECT run_date = @run_date, expiration_date = @expiration_date, license_distribution_method_id = @license_distribution_method_id, license_seats = @license_seats, license_category_id = @license_category_id, product_line_id = @product_line_id, message_platform_name_list = @message_platform_name_list
              --return
       
              ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
              -- 2.) SELECT campaigns
              ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

              -- 2.2) get campaigns
              DECLARE @message_campaigns TABLE (
                     message_source VARCHAR(50), 
                     message_campaign_id INT, 
                     message_campaign_name VARCHAR(50), 
                     message_campaign_description VARCHAR(256), 
                     process_date DATETIME, 
                     END_date DATETIME, 
                     message_key VARCHAR(36), 
                     license_message_id INT, 
                     message_content_id INT, 
                     cart_discount_id INT)

              IF @old_swap_license > 0 
                     OR @refund > 0
                     OR @non_mail_disti > 0
                     OR @email_engine_start > 0
                     BEGIN
                           SELECT * FROM @message_campaigns
                           RETURN
                     END

              INSERT INTO @message_campaigns(message_source, message_campaign_id, message_campaign_name, message_campaign_description, process_date, END_date, message_key, cart_discount_id)
              SELECT message_source = c.message_campaign_name, 
                     c.message_campaign_id, 
                     c.message_campaign_name, 
                     c.message_campaign_description, 
                     m.process_date,
                     m.END_date,
                     license_key = @license_key,
                     d.cart_discount_id 
              FROM message_campaign c WITH (NOLOCK)
              INNER JOIN message_campaign_seat s WITH (NOLOCK)
                     ON c.message_campaign_id = s.message_campaign_id
              INNER JOIN message_campaign_license_category lc WITH (NOLOCK)
                     ON c.message_campaign_id = lc.message_campaign_id
              INNER JOIN message_campaign_trial ct WITH (NOLOCK)
                     ON c.message_campaign_id = ct.message_campaign_id
              INNER JOIN message_campaign_autorenewal a WITH (NOLOCK)
                     ON c.message_campaign_id = a.message_campaign_id
              INNER JOIN message_campaign_email_electiON e WITH (NOLOCK)
                     ON c.message_campaign_id = e.message_campaign_id
              INNER JOIN message_campaign_license_status st WITH (NOLOCK)
                     ON c.message_campaign_id = st.message_campaign_id
              INNER JOIN message_campaign_renewal_status rs WITH (NOLOCK)
                     ON c.message_campaign_id = rs.message_campaign_id      
              LEFT JOIN message_campaign_cart_discount d WITH (NOLOCK)
                     ON c.message_campaign_id = d.message_campaign_id
              INNER JOIN dbo.message_campaign_product_line pl
 WITH (NOLOCK)
                     ON c.message_campaign_id = pl.message_campaign_id
              INNER JOIN (SELECT mp.message_campaign_id, 
                                                process_date = CASE
                                                              WHEN mp.message_measure_point_id = 1 THEN DATEADD(dd,mp.message_measure_days,@activation_date)
                                                              WHEN mp.message_measure_point_id = 2 THEN DATEADD(dd,mp.message_measure_days,@expiration_date)
                                                              WHEN mp.message_measure_point_id = 4 THEN DATEADD(dd,mp.message_measure_days,@activation_date)
                                                       END,
                                                END_date = CASE
                                                              WHEN mp.message_measure_point_id = 1 THEN DATEADD(dd,mp.message_measure_END_days,@activation_date)
                                                              WHEN mp.message_measure_point_id = 2 THEN DATEADD(dd,mp.message_measure_END_days,@expiration_date)
                                                              WHEN mp.message_measure_point_id = 4 THEN DATEADD(dd,mp.message_measure_END_days,@expiration_date)
                                                       END
                                  FROM message_campaign_measure_point mp WITH (NOLOCK)) m ON c.message_campaign_id = m.message_campaign_id
              INNER JOIN dbo.message_campaign_language_location ll WITH (NOLOCK)
                     ON c.message_campaign_id = ll.message_campaign_id
              WHERE c.message_campaign_enabled = 1 
                     and c.message_campaign_class_id = 8 
                     and lc.license_category_id = @license_category_id 
                     AND pl.product_line_id = @product_line_id
                     and s.license_seats = @license_seats 
                     and ct.trial = @trial
                     and rs.renewal_status = @renewal_status
                     and a.autorenewal_opt_id = @autorenewal_opt_id
                     and e.message_email_opt_id = @opt_in
                     and st.license_status_id = @license_status_id
                     AND ll.location_code = @location_code
                     AND ll.language_code = @language_code
                     and (c.message_campaign_start_date < GETDATE() and (GETDATE() <= c.message_campaign_END_date or c.message_campaign_END_date is null))
                     and c.message_campaign_id in (SELECT message_campaign_id FROM message_campaign WITH (NOLOCK)
                                                                     EXCEPT
                                                                     SELECT message_campaign_id 
                                                                     FROM message_campaign_license_distribution_method WITH (NOLOCK)
                                                                     WHERE license_distribution_method_id = @license_distribution_method_id and inclusive = 0
                                                                     EXCEPT
                                                                     (SELECT message_campaign_id FROM message_campaign WITH (NOLOCK)
                                                                     intersect 
                                                                     SELECT message_campaign_id 
                                                                     FROM message_campaign_license_distribution_method WITH (NOLOCK)
                                                                     WHERE license_distribution_method_id <> @license_distribution_method_id and inclusive = 1
                                                                     EXCEPT
                                                                     SELECT message_campaign_id 
               
                                                      FROM message_campaign_license_distribution_method WITH (NOLOCK)
                                                                     WHERE license_distribution_method_id = @license_distribution_method_id and inclusive = 1))

              --UPDATE @message_campaigns
              --SET process_date = GETDATE()
              --WHERE process_date < GETDATE()
              --     AND message_campaign_name NOT LIKE '%welcome%'

              DELETE FROM @message_campaigns 
              WHERE process_date < GETDATE() 
                     AND message_campaign_name LIKE '%welcome%'

              DELETE FROM @message_campaigns 
              WHERE process_date < GETDATE() 
                     AND message_campaign_name LIKE '%welcome%'

              IF @new_swap_license > 0
                     BEGIN
                           DELETE FROM @message_campaigns WHERE message_campaign_name like '%welcome%'
                     END

              SELECT * FROM @message_campaigns


       END try

       BEGIN CATCH

              SET @response_code = -200
              SET @message = CASE WHEN @message is null THEN 'SELECT failed'
                                                else @message END

              DECLARE @DBName NVARCHAR(128)
              SET @DBName = DB_NAME()
              EXEC usp_LogError @ErrorDB = @DBName
              
       END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_license_vault]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_license_vault]

(
	@license_id int
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2022-03-10	psatish		Initial creation.	

		DESCRIPTION
		select salesforce license vault object
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select vt.license_external_reference_id,vt.Salesforce_license_vault_id,vt.license_id
	from dbo.sfdc_license_vault vt
	INNER JOIN dbo.license_external_reference ex
	ON ex.license_external_reference_id = vt.license_external_reference_id
	where vt.license_id=@license_id


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_next_all_subs]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_next_all_subs]
(
	@batch_limit_date DATETIME
)

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial Creation


	DESCRIPTION
	selects the next license for the cron to update all subs
	
*/


AS
	SET NOCOUNT,
		CONCAT_NULL_YIELDS_NULL,
		ANSI_NULLS, 
		ANSI_PADDING, 
		ANSI_WARNINGS ON;	

	BEGIN TRY

		DECLARE	@response_code INT,
				@message VARCHAR(100),
				@customer_id INT,
				@license_message_id INT,
				@composite_key VARCHAR(150),
				@data_extension VARCHAR(150)

		SELECT @batch_limit_date = DATEADD(ss,1,GETDATE()) -- php cannot handle milliseconds so add one second

    
		DECLARE @lm TABLE(lm_id INT IDENTITY(1,1),
			license_message_id INT NULL, 
			license_id INT)
		 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		 --1.) Select
		 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		INSERT INTO @lm(license_id,license_message_id)
		SELECT license_id,
			lm.license_message_id
		FROM dbo.license_message lm
		WHERE lm.message_status_id = 1
			AND lm.message_type_id = 15
			AND lm.process_date <= @batch_limit_date


		DECLARE @all_subs TABLE(all_subs_id INT IDENTITY(1,1),
			license_message_id INT,
			customer_email_existing VARCHAR(255),
			customer_email_new VARCHAR(255))


		SELECT TOP 1 @composite_key = ls.keycode + ce.customer_email,
			@license_message_id = lm2.license_message_id,
			@data_extension = mcsde.data_extension,
			@customer_id = ce.customer_id
		FROM @lm lm2
			INNER JOIN license_message lm
				ON lm.license_id = lm2.license_id
			INNER JOIN message_campaign_sfdc_data_extension mcsde
				ON lm.message_campaign_id = mcsde.message_campaign_id
			INNER JOIN dbo.license_summary ls
				ON lm.license_id = ls.license_id
			INNER JOIN dbo.license_message_value lmv
				ON lm.license_message_id = lmv.license_message_id
					AND lmv.message_value_type_id = 22 --sfdc_customer_email_id
			INNER JOIN dbo.customer_email ce
				ON lmv.value_id = ce.customer_email_id

		INSERT INTO @all_subs(license_message_id ,
				  customer_email_existing)
		SELECT @license_message_id,
			@composite_key

		UPDATE a
		SET customer_email_new = ce.customer_email
		FROM @all_subs a
			INNER JOIN dbo.license_message lm
				ON a.license_message_id = lm.license_message_id
			INNER JOIN license l
				ON lm.license_id = l.license_id
			INNER JOIN (SELECT MAX(customer_email_id) customer_email_id,
				customer_id,
				customer_email 
				FROM customer_email
				WHERE customer_id = @customer_id
					AND email_status_id = 1
				GROUP BY customer_id,
				customer_email) ce
			ON l.customer_id = ce.customer_id
		WHERE lm.license_message_id = @license_message_id

		DELETE FROM @all_subs
		WHERE license_message_id IS NULL	
			AND customer_email_existing IS NULL
			AND customer_email_new IS null

		SELECT license_message_id,
				  customer_email_existing,
				  customer_email_new 
		FROM @all_subs

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'select next email record failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC usp_LogError @ErrorDB = @DBName
		
	END CATCH ;


GO
