CREATE PROCEDURE [dbo].[usp_sfdc_select_next_held]

/*	
	DATE		AUTHOR		REMARKS
	2018-03-21	mrobbins	initial creation

	DESCRIPTION
	Provides records to cron for processing of held records
	
*/


AS

	BEGIN TRY

		DECLARE @response_code INT,
				@message VARCHAR(100)

		SET NOCOUNT ON		

	
		SELECT TOP 1 sfdc_subscriber_held_id, 
			sfdc_subscriber_key,
			member_id
		FROM sfdc_subscriber_held
		WHERE processed = 0
		ORDER BY sfdc_subscriber_held_id

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = 'Could not select held subscriber'

		DECLARE @DBName nvarchar(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
