CREATE PROCEDURE [dbo].[usp_sfdc_select_next_in_journey]
(
	@batch_limit_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial Creation


	DESCRIPTION
	selects the next license for the cron to get test_group from SFMC
	
*/


AS
	set nocount,
		concat_null_yields_null,
		ansi_nulls, 
		ansi_padding, 
		ansi_warnings on;
				

	declare	@response_code int,
			@message varchar(100),
			@journey_data_id int,
			@max_journey_data_id int,
			@keycode varchar(40),
			@license_category_name varchar(10),
			@seats int,
			@storage int,
			@years float,
			@cart_discount_id int,
			@language_code varchar(2),
			@location_code varchar(3),
			@retail_price money,
			@net_price money,
			@discount money,
			@currency_symbol varchar(2),
			@product_line_id int

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	DECLARE @lm TABLE(lm_id INT IDENTITY(1,1),
			license_message_id INT NULL, 
			license_id INT)

	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	 --1.) Select
	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	INSERT INTO @lm(license_id,license_message_id)
	SELECT license_id,
		lm.license_message_id
	FROM dbo.license_message lm
	WHERE lm.message_status_id = 1
		AND lm.message_type_id = 17
		AND lm.process_date <= @batch_limit_date
		AND NOT EXISTS
			(SELECT license_message_id 
				FROM license_message_value lmv 
				WHERE lm.license_message_id = lmv.license_message_id
					AND message_value_type_id = 23
					AND lmv.value_id = 1)

	SELECT TOP 1 ls.keycode + ce.customer_email composite_key,
		lm2.license_message_id,
		mcsde.data_extension
	FROM @lm lm2
		INNER JOIN license_message lm
			ON lm.license_id = lm2.license_id
		INNER JOIN message_campaign_sfdc_data_extension mcsde
			ON lm.message_campaign_id = mcsde.message_campaign_id
		INNER JOIN dbo.license_summary ls
			ON lm.license_id = ls.license_id
		INNER JOIN dbo.license_message_value lmv
			ON lm.license_message_id = lmv.license_message_id
				AND lmv.message_value_type_id = 22 --sfdc_customer_email_id
		INNER JOIN dbo.customer_email ce
			ON lmv.value_id = ce.customer_email_id
	


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select next email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
