-- PROCEDURE: [dbo].[usp_sfdc_select_next_license_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_next_license_message]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial Creation
	2017-08-09	mrobbins	edited to give back all records for entire day
	2017-10-19	mrobbins	edited to give back 1 record at a time US27174
	2017-11-06	mrobbins	added md5 info SRIRACHA-310
	2017-12-19	mrobbins	fixed update/exit subquery to return all records if customer_id in license changes SRIRACHA-622
	2018-01-10	mrobbins	changed last_scan_date to be empty string
	2019-01-10	rvinoche	Support autobilling attributes living only in license_effective_object

	DESCRIPTION
	returns all the data for the cron to insert into SFMC
	
*/


AS
	set nocount,
		concat_null_yields_null,
		ansi_nulls, 
		ansi_padding, 
		ansi_warnings on;
				

	declare	@response_code int,
			@message varchar(100),
			@journey_data_id int,
			@max_journey_data_id int,
			@keycode varchar(40),
			@license_category_name varchar(10),
			@seats int,
			@storage int,
			@years float,
			@cart_discount_id int,
			@language_code varchar(2),
			@location_code varchar(3),
			@retail_price money,
			@net_price money,
			@discount money,
			@currency_symbol varchar(10),
			@product_line_id int

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	 --1.) Select
	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	DECLARE	@journey_data TABLE (journey_data_id INT IDENTITY(1,1),
		license_message_id INT NOT NULL,
		license_id INT NULL,
		composite_key VARCHAR(254) NOT NULL,
		campaign_class VARCHAR(50) NULL,
		data_extension VARCHAR(50) NOT NULL,
		email VARCHAR(100) NOT NULL,
		subscriber_key VARCHAR(1) NOT NULL,
		first_name NVARCHAR(225) NULL,
		last_name NVARCHAR(225) NULL,
		country VARCHAR(3) NULL,
		language VARCHAR(2) NULL,
		country_currency VARCHAR(3) NULL,
		license_category_description VARCHAR(50) NOT NULL,
		license_seats INT NOT NULL,
		capability_activation_date DATETIME NULL,
		capability_expiration_date DATETIME NULL,
		keycode VARCHAR(40) NOT NULL,
		license_key VARCHAR(40) NOT NULL,
		account_created INT NOT NULL,
		capability_type_description VARCHAR(20) NOT NULL,
		license_category_name VARCHAR(10) NOT NULL,
		license_attribute_license_value_description VARCHAR(50) NOT NULL,
		license_status_description VARCHAR(255) NOT NULL,
		exit_journey INT,
		in_journey INT,
		storage_gb INT,
		years FLOAT,
		product_line_id INT,
		retail_price MONEY,
		net_price MONEY,
		discount MONEY,
		currency_symbol NVARCHAR(10),
		md5_bad INT,
		md5_good INT 
	) 

	INSERT INTO @journey_data
		(license_message_id,
			license_id,
			composite_key,
			campaign_class,
			data_extension,
			email,
			subscriber_key,
			first_name,
			last_name,
			country,
			language,
			country_currency,
			license_category_description,
			license_seats,
			capability_activation_date,
			capability_expiration_date,
			keycode,
			license_key,
			account_created,
			capability_type_description,
			license_category_name,
			license_attribute_license_value_description,
			license_status_description,
			exit_journey,
			in_journey,
			storage_gb,
			years,
			product_line_id,
			md5_bad,
			md5_good)
	SELECT TOP 1 A.* 
	FROM (SELECT lm.license_message_id,
		lm.license_id,
		ls.key
code + ce.customer_email composite_key,
		mc.message_campaign_name campaign_class,
		mcsde.data_extension data_extension,
		ce.customer_email email,
		''subscriber_key,
		c.first_name,
		c.last_name,
		CASE WHEN cl.location_code is null THEN
			'us'
		ELSE 
			LOWER(luc.iso)
		END country,
		CASE WHEN cl.language_code is null THEN 
			'en'
		ELSE 
			LOWER(cl.language_code)
		END language,
		CASE WHEN cl.location_code is null THEN
			'USA'
		ELSE 
			cl.location_code
		END country_currency,
		lc.license_category_description,
		ls.license_seats,
		ls.capability_activation_date,
		ls.capability_expiration_date,
		ls.keycode keycode,
		left(ls.license_key,40) license_key,
		CASE WHEN al.license_id IS NULL THEN 0
		ELSE 1
		END account_created,
		ct.capability_type_description,
		lc.license_category_name,
		CASE WHEN lalv.license_attribute_license_value_description IS NULL THEN 'Inactive' 
		ELSE lalv.license_attribute_license_value_description
		END license_attribute_license_value_description,
		ls2.license_status_description,
		CASE WHEN message_type_id = 16 THEN 1
		ELSE 0
		END exit_journey,
		0 in_journey,
		lstore.storage_gb,
		1 years,
		ls.product_line_id,
		lsl.bad_scans md5_bad,
		lsl.good_scans md5_good
	FROM license_message lm
		INNER JOIN message_campaign mc
			ON lm.message_campaign_id = mc.message_campaign_id
		INNER JOIN message_campaign_sfdc_data_extension mcsde
			ON mc.message_campaign_id = mcsde.message_campaign_id
		INNER JOIN license l
			ON lm.license_id = l.license_id
		INNER JOIN customer c
			ON l.customer_id = c.customer_id
		INNER JOIN customer_email ce
			ON l.customer_id = ce.customer_id
				AND ce.email_status_id = 1
		INNER JOIN license_summary ls
			ON lm.license_id = ls.license_id
		LEFT JOIN dbo.customer_locale cl
			ON c.customer_id = cl.customer_id
		LEFT JOIN dbo.lu_countries luc
			ON cl.location_code = luc.iso3
		INNER JOIN dbo.license_category lc
			ON ls.license_category_id = lc.license_category_id
		INNER JOIN dbo.capability_type ct
			ON ls.capability_type_id = ct.capability_type_id
		LEFT JOIN dbo.license_attribute_license_value lalv
			ON lalv.license_attribute_license_value = dbo.fn_license_select_effective_object_element(l.license_id,lc.license_category_id,'license_attribute_license_value', getdate())
		INNER JOIN dbo.license_status ls2
			ON ls.license_status_id = ls2.license_status_id
		LEFT JOIN dbo.account_license al
			ON lm.license_id = al.license_id
		LEFT JOIN license_storage lstore
			on lm.license_id = lstore.license_id
		LEFT JOIN dbo.license_message_value lmv
			ON lm.license_message_id = lmv.license_message_id
				AND lmv.message_value_type_id = 23
		LEFT JOIN dbo.license_scan_license lsl
			ON lm.license_id = lsl.license_id
	WHERE message_status_id in (0,1) 
		AND message_type_id in (13)
		AND CAST(process_date AS DATE) <= CAST(@batch_limit_date AS DATE)		
	UNION
		SELECT lm.license_message_id,
		lm.license_id,
		ls.keycode + ce2.customer_email composite_key,
		mc.message_campaign_name campaign_class,
		mcsde.data_extension data_extension,
		ce2.customer_email email,
		''subscriber_key,
		c.first_name,
		c.last_name,
		CASE WHEN cl.location_code is null THEN
			'us'
		ELSE 
			LOWER(luc.iso)
		END country,
		CASE WHEN cl.language_code is null THEN 
			'en'
		ELSE 
			LOWER(cl.language_code)
		END language,
		CASE WHEN cl.location_code is null THEN
			'USA'
		ELSE 
			cl.location_code
		END country_currency,
		lc.license_category_description,
		ls.license_seats,
		ls.capability_activation_date,
		ls.capability_expiration_date,
		ls.keycode keycode,
		left(ls.license_key,40) license_key,
		CASE WHEN al.license_id IS NULL THEN 0
		ELSE 1
		END account_created,
		ct.capability_type_description,
		lc.license_category_name,
		CASE WHEN lalv.license_attribute_license_value_description IS NULL THEN 'Inactive' 
		ELSE lalv.license_attribute_license_value_descr
iption
		END license_attribute_license_value_description,
		ls2.license_status_description,
		CASE WHEN message_type_id = 16 THEN 1
		ELSE 0
		END exit_journey,
		CASE WHEN lmv2.value_id IS NULL THEN 0
		ELSE
			lmv2.value_id
		END in_journey,
		lstore.storage_gb,
		1 years,
		ls.product_line_id,
		lsl.bad_scans md5_bad,
		lsl.good_scans md5_good
	FROM license_message lm
		INNER JOIN message_campaign mc
			ON lm.message_campaign_id = mc.message_campaign_id
		INNER JOIN message_campaign_sfdc_data_extension mcsde
			ON mc.message_campaign_id = mcsde.message_campaign_id
		INNER JOIN license l
			ON lm.license_id = l.license_id
		INNER JOIN customer c
			ON l.customer_id = c.customer_id
		INNER JOIN license_summary ls
			ON lm.license_id = ls.license_id
		LEFT JOIN dbo.customer_locale cl
			ON c.customer_id = cl.customer_id
		LEFT JOIN dbo.lu_countries luc
			ON cl.location_code = luc.iso3
		INNER JOIN dbo.license_category lc
			ON ls.license_category_id = lc.license_category_id
		INNER JOIN dbo.capability_type ct
			ON ls.capability_type_id = ct.capability_type_id
		LEFT JOIN dbo.license_attribute_license_value lalv
			ON lalv.license_attribute_license_value = dbo.fn_license_select_effective_object_element(l.license_id,lc.license_category_id,'license_attribute_license_value', getdate())
		INNER JOIN dbo.license_status ls2
			ON ls.license_status_id = ls2.license_status_id
		LEFT JOIN dbo.account_license al
			ON lm.license_id = al.license_id
		LEFT JOIN license_storage lstore
			on lm.license_id = lstore.license_id
		LEFT JOIN (SELECT lm2.license_message_id,
						lm2.license_id,
						lmv.value_id
					FROM license_message lm2
						INNER JOIN license_message_value lmv
							ON lm2.license_message_id = lmv.license_message_id
								AND lmv.message_value_type_id = 23
					WHERE lm2.message_status_id = 3
							AND message_type_id = 17) lmv2
			ON lm.license_id = lmv2.license_id
		INNER JOIN (SELECT ce.customer_email,
				lm.license_id
			FROM dbo.customer_email ce
				INNER JOIN dbo.license_message_value lmv
					ON ce.customer_email_id = lmv.value_id
				INNER JOIN license_message lm
					ON lmv.license_message_id = lm.license_message_id
			WHERE lmv.message_value_type_id = 22) ce2
		ON ce2.license_id = lm.license_id
		LEFT JOIN dbo.license_scan_license lsl
			ON lm.license_id = lsl.license_id
	WHERE message_status_id in (0,1) 
		AND message_type_id in (14,16)
		AND CAST(process_date AS DATE) <= CAST(@batch_limit_date AS DATE)) A
		

	DECLARE @pricing_return table(
				product_id int, 
				product_description varchar(100), 
				retail_price money, 
				upgrade_price money, 
				discount money, 
				standard_discount money default 0, 
				net_price money,
				product_type_id int, 
				license_category_name varchar(10), 
				seats int, 
				years float, 
				p_type varchar(20), 
				currency_id tinyint, 
				currency_code char(3), 
				currency_description varchar(20), 
				symbol_html varchar(10), 
				symbol_utf8 nvarchar(10), 
				symbol_text varchar(10), 
				cart_discount_id int null)

	SELECT @journey_data_id = min(journey_data_id), @max_journey_data_id = max(journey_data_id)
	FROM @journey_data

	WHILE @journey_data_id <= @max_journey_data_id
		BEGIN	
			SELECT @keycode = keycode,
				@license_category_name = license_category_name,
				@seats = license_seats, 
				@storage = storage_gb, 
				@years = years,
				@language_code = language,
				@location_code = country_currency,
				@product_line_id = product_line_id
			FROM @journey_data
			WHERE journey_data_id = @journey_data_id


			IF @product_line_id = 300
					BEGIN 
						INSERT INTO @pricing_return 
						EXEC usp_cart_select_renewal_product_set_ENT
							@keycode, 
							@license_category_name, 
							@seats, 
							@storage,
							@years,
							@cart_discount_id, 
							@language_code,
							@location_code
							--exec ecommerce_daily.dbo.
usp_cart_select_renewal_product_set 'SSHAONLNAADJXGRBMLRI', 'WSAV', 5, 0,1
					END 
				ELSE 
					BEGIN 
						INSERT INTO @pricing_return 
						EXEC usp_cart_select_renewal_product_set 
							@keycode, 
							@license_category_name, 
							@seats, 
							@storage,
							@years,
							@cart_discount_id, 
							@language_code,
							@location_code
							--exec ecommerce_daily.dbo.usp_cart_select_renewal_product_set 'SSHAONLNAADJXGRBMLRI', 'WSAV', 5, 0,1
					END  

			SELECT @retail_price = retail_price,
				@net_price = net_price,
				@currency_symbol = symbol_utf8,
				@discount = discount
			FROM @pricing_return
			WHERE retail_price <> 0.00


			UPDATE @journey_data
			SET retail_price = @retail_price,
				net_price = @net_price,
				currency_symbol = @currency_symbol,
				discount = @discount
			WHERE keycode = @keycode

			delete from @pricing_return

			set @journey_data_id = @journey_data_id + 1

			SET @keycode = null
			SET @license_category_name = null
			SET @seats = null
			SET @storage = null 
			SET @years = null
			SET @cart_discount_id = null

			SET @retail_price = 0.00
			SET @net_price = 0.00

		END

		declare @sky_license_activity table(
			license_id int,
			Threats_removed int,
			Scan_count int,
			avg_scan_duration bigint,
			last_scan_date VARCHAR(50),
			latest_threat varchar(4000))

		insert into @sky_license_activity(license_id,
			Threats_removed,
			Scan_count,
			avg_scan_duration,
			last_scan_date,
			latest_threat)
		select sla.license_id,
			sla.Threats_removed,
			sla.Scan_count,
			CONVERT(bigint,sla.avg_scan_duration/60000.00) avg_scan_duration,
			CONVERT(VARCHAR(10),sla.last_scan_date,101) last_scan_date,
			replace(sla.latest_threat,'|','-') latest_threat
		from (
			select sla.license_id,
				max(sla.effective_date) effective_date
			from sky_license_activity sla
				inner join @journey_data j
					on sla.license_id = j.license_id
			group by sla.license_id) g1 
			inner join sky_license_activity sla
				on g1.license_id = sla.license_id
					and g1.effective_date = sla.effective_date

	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	 --2.) Function Call/Output Record
	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	--	select top 1 data_extension,
	--		composite_key,
	--		campaign_class,
	--		email,
	--		subscriber_key,
	--		first_name,
	--		last_name,
	--		country,
	--		language,
	--		license_category_description,
	--		license_seats,
	--		capability_activation_date,
	--		capability_expiration_date,
	--		keycode,
	--		license_key,
	--		ISNULL(Threats_removed,0) Threats_removed,
	--		ISNULL(Scan_count,0) Scan_count,
	--		CONVERT(VARCHAR(25),ISNULL(avg_scan_duration,0)) avg_scan_duration,
	--		ISNULL(latest_threat,'') latest_threat,
	--		ISNULL(last_scan_date,'') last_scan_date,
	--		account_created,
	--		capability_type_description,
	--		license_category_name,
	--		license_attribute_license_value_description,
	--		retail_price,
	--		CASE WHEN currency_symbol = '£' THEN '&#163;'
	--			WHEN currency_symbol = '¥' THEN '&#165;'
	--			WHEN currency_symbol = '€' THEN '&#8364;'
	--		ELSE currency_symbol
	--		END,
	--		license_status_description,
	--		exit_journey,
	--		in_journey,
	--		license_message_id
	--FROM @journey_data j
	--	LEFT join @sky_license_activity sla
	--		on j.license_id = sla.license_id

	 SELECT (SELECT data_extension,
			composite_key,
			campaign_class,
			email,
			subscriber_key,
			first_name,
			last_name,
			country,
			language,
			license_category_description,
			license_seats,
			CONVERT(VARCHAR(10),capability_activation_dat
e,101) capability_activation_date,
			CONVERT(VARCHAR(10),capability_expiration_date,101) capability_expiration_date,
			keycode,
			license_key,
			ISNULL(Threats_removed,0) max_threats_removed,
			ISNULL(Scan_count,0) number_scans,
			CONVERT(VARCHAR(25),ISNULL(avg_scan_duration,0)) average_scan_time,
			ISNULL(latest_threat,'') latest_threat,
			ISNULL(last_scan_date,'') last_scan_date,
			account_created,
			capability_type_description license_capability_type_name,
			license_category_name,
			license_attribute_license_value_description license_attribute_license_value,
			md5_bad,
			md5_good,
			retail_price,
			currency_symbol,
			license_status_description license_status,
			exit_journey,
			in_journey
	  FROM @journey_data j
		LEFT join @sky_license_activity sla
			on j.license_id = sla.license_id
	  FOR json path,  INCLUDE_NULL_VALUES) result,
			license_message_id
	  FROM @journey_data j2

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select next email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_next_opportunity_load]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_next_opportunity_load]

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2017-07-18	esmart		license_update_id
	2020-12-23	esmart		sfdc_opportunity_load_json

	DESCRIPTION
	Insert opportunity
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top(1) l.sfdc_opportunity_load_id, l.opportunity_id, l.salesforce_trial_id, l.license_update_id, t.sfdc_update_type_id, t.sfdc_update_type_name, tp.sfdc_template_id, tp.sfdc_template_name, l.load_attempts,
		j.sfdc_load_json
	from sfdc_opportunity_load l
	inner join sfdc_update_type t
		on l.sfdc_update_type_id = t.sfdc_update_type_id
	inner join sfdc_template tp
		on l.sfdc_template_id = tp.sfdc_template_id
	left join sfdc_opportunity_load_json j
		on j.sfdc_opportunity_load_id = l.sfdc_opportunity_load_id
	where l.process_date <= getdate()
	order by l.sfdc_opportunity_load_id
				
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_next_opportunity_update]
-- =============================================================================
CREATE   PROCEDURE [dbo].[usp_sfdc_select_next_opportunity_update]

(
	@batch_limit_date DATETIME,
	@queue_type_name VARCHAR(20)
)
	
/*	
	DATE		AUTHOR		REMARKS
	2013-10-30	esmart		Initial creation.
	2015-04-16	esmart		Add form_submit_id
	2016-04-15	esmart		Add license_id
	2016-08-24	cnovac		Added @queue_type_name so that we can split the queue on PHP side
	2025-01-17	gblandford	IM-4395435 - DB: Resolve Issue of Blocking Records in SFDC Opportunity Update Queue - https://ot-internal.saas.microfocus.com/ui/entity-navigation?p=4001/26009&entityType=work_item&id=4395435
							- changed casing and formatting, get external_order template id

	DESCRIPTION
	
	
*/

AS
	SET NOCOUNT ON				

	DECLARE	@response_code INT,
			@message VARCHAR(100),
			@sfdc_external_order_template_id INT

	BEGIN TRY

	SELECT 
		@sfdc_external_order_template_id = st.sfdc_template_id 
	FROM dbo.sfdc_template st
	WHERE st.sfdc_template_name = 'external_order';

	SELECT @batch_limit_date = DATEADD(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	SELECT 
		TOP 1 
			u.sfdc_opportunity_update_id, 
			u.order_header_id, 
			u.trial_id, 
			u.form_submit_id, 
			u.license_id, 
			t.sfdc_update_type_id, 
			t.sfdc_update_type_name, 
			u.process_date, 
			o.salesforce_lead_id, 
			st.sfdc_template_id, 
			st.sfdc_template_name, 
			u.update_attempts,
			oca.order_company_id,
			ocb.order_company_id
	FROM dbo.sfdc_opportunity_update u
		INNER JOIN dbo.sfdc_update_type t
			ON u.sfdc_update_type_id = t.sfdc_update_type_id
		INNER JOIN dbo.sfdc_template st
			ON u.sfdc_template_id = st.sfdc_template_id
		INNER JOIN dbo.sfdc_queue_type q
			ON q.sfdc_queue_type_id = st.sfdc_queue_type_id
		LEFT JOIN dbo.sfdc_lead_order o
			ON u.order_header_id = o.order_header_id
		LEFT JOIN dbo.order_company oca
			ON oca.order_header_id = u.order_header_id
				AND oca.order_company_type_id = 1 -- account
		LEFT JOIN dbo.order_company ocb
			ON ocb.order_header_id = u.order_header_id
				AND ocb.order_company_type_id = 2 -- bill_to_account

	WHERE u.sfdc_update_status_id IN (0, 2) 
		AND u.process_date <= @batch_limit_date --and u.modified_date < @batch_limit_date
		AND q.sfdc_queue_type_name = @queue_type_name
		AND ( 1 = ( CASE 
						WHEN st.sfdc_template_id = @sfdc_external_order_template_id THEN 
							( CASE WHEN oca.order_company_id IS NULL 
										OR ocb.order_company_id IS NULL THEN 0
									ELSE 1
								END )
						ELSE 1
					END ) 
			)

	ORDER BY u.process_date

	END TRY

	BEGIN CATCH

		SET @response_code = -200
		SET @message = CASE WHEN @message IS NULL THEN 'update account update failed'
							ELSE @message END

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXECUTE dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_next_test_group]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_next_test_group]
(
	@batch_limit_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial Creation


	DESCRIPTION
	selects the next license for the cron to get test_group from SFMC
	
*/


AS
	set nocount,
		concat_null_yields_null,
		ansi_nulls, 
		ansi_padding, 
		ansi_warnings on;
				

	declare	@response_code int,
			@message varchar(100),
			@journey_data_id int,
			@max_journey_data_id int,
			@keycode varchar(40),
			@license_category_name varchar(10),
			@seats int,
			@storage int,
			@years float,
			@cart_discount_id int,
			@language_code varchar(2),
			@location_code varchar(3),
			@retail_price money,
			@net_price money,
			@discount money,
			@currency_symbol varchar(2),
			@product_line_id int

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	DECLARE @lm TABLE(lm_id INT IDENTITY(1,1),
		license_message_id INT NULL, 
		license_id INT)
	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	 --1.) Select
	 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	INSERT INTO @lm(license_id,license_message_id)
	SELECT license_id,
		lm.license_message_id
	FROM dbo.license_message lm
	WHERE lm.message_status_id = 3
		AND lm.message_type_id = 17
		AND lm.process_date <= GETDATE()
		AND EXISTS
			(SELECT license_message_id 
				FROM license_message_value lmv 
				WHERE lm.license_message_id = lmv.license_message_id
					AND message_value_type_id = 23
					AND lmv.value_id = 1)
	AND NOT EXISTS 
		(SELECT license_message_id 
			FROM license_message_value lmv 
			WHERE lm.license_message_id = lmv.license_message_id
				AND message_value_type_id = 21)

	SELECT TOP 1 ls.keycode + ce.customer_email composite_key,
		lm2.license_message_id,
		mcsde.data_extension
	FROM @lm lm2
		INNER JOIN license_message lm
			ON lm.license_id = lm2.license_id
		INNER JOIN message_campaign_sfdc_data_extension mcsde
			ON lm.message_campaign_id = mcsde.message_campaign_id
		INNER JOIN dbo.license_summary ls
			ON lm.license_id = ls.license_id
		INNER JOIN dbo.license_message_value lmv
			ON lm.license_message_id = lmv.license_message_id
				AND lmv.message_value_type_id = 22 --sfdc_customer_email_id
		INNER JOIN dbo.customer_email ce
			ON lmv.value_id = ce.customer_email_id


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select next email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
