-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_opportunity] (
	@opportunity_id VARCHAR(18)
	,@response_code INT OUTPUT
	,@message VARCHAR(100) OUTPUT
	)
/*	
	DATE		AUTHOR		        REMARKS
	2024-01-09	msaiprasanna		Initial creation

	DESCRIPTION:
	This stored procedure will fetch latest opportunity status and details for a given sfdc opportunity.
	
	DEPENDENCY:
	This stored procedure is used in CSI opportunity self-help page.
*/

AS
BEGIN
	SET NOCOUNT ON
	
	DECLARE @order_header_id INT
	
	BEGIN TRY
	
		-- Check if opportunity has come to ECom
		IF NOT EXISTS (
			SELECT 1
			FROM dbo.sap_fulfillment_json
			WHERE salesforce_opportunity_id = @opportunity_id
		)
		BEGIN
			SET @response_code = -100
			SET @message = 'Opportunity fulfillment request has not come to ECom.'
			RETURN @response_code
		END
	
		DECLARE @sfdc_opportunity TABLE (
			opportunity_id VARCHAR(18)
			,sfdc_opportunity_update_id INT
			,sfdc_opportunity_load_id INT
			,order_header_id INT
			,sfdc_template_id TINYINT
			,sfdc_update_type_id TINYINT
			,sfdc_update_status_id TINYINT
			,insert_date DATETIME
			,process_date DATETIME
			,attempts_count TINYINT
			,execution_date DATETIME
			,failure_description VARCHAR(255)
		)
	
		-- First check sfdc_opportunity_update related tables
		SELECT @order_header_id = oo.order_header_id
		FROM dbo.order_opportunity oo
		LEFT JOIN dbo.sfdc_opportunity_update sou ON oo.order_header_id = sou.order_header_id
		LEFT JOIN dbo.sfdc_opportunity_update_archive soua ON oo.order_header_id = soua.order_header_id
		LEFT JOIN dbo.sfdc_opportunity_update_failure souf ON oo.order_header_id = souf.order_header_id
		WHERE oo.salesforce_opportunity_id = @opportunity_id
			AND (
				sou.sfdc_opportunity_update_id IS NOT NULL
				OR soua.sfdc_opportunity_update_archive_id IS NOT NULL
				OR souf.sfdc_opportunity_update_failure_id IS NOT NULL
			)

		IF @order_header_id IS NOT NULL
		BEGIN
			INSERT INTO @sfdc_opportunity (
				opportunity_id
				,sfdc_opportunity_update_id
				,order_header_id
				,sfdc_template_id
				,sfdc_update_type_id
				,sfdc_update_status_id
				,insert_date
				,process_date
				,attempts_count
				)
			SELECT TOP(1) @opportunity_id
				,sfdc_opportunity_update_id
				,order_header_id
				,sfdc_template_id
				,sfdc_update_type_id
				,sfdc_update_status_id
				,insert_date
				,process_date
				,update_attempts
			FROM dbo.sfdc_opportunity_update
			WHERE order_header_id = @order_header_id
			ORDER BY sfdc_opportunity_update_id DESC
	
			-- If there are no records in sfdc_opportunity_update then will look into 
			-- sfdc_opportunity_update_archive or sfdc_opportunity_update_failure
			IF @@ROWCOUNT = 0
			BEGIN
				WITH sfdc_opportunity_update_archive_failure_cte AS (
					SELECT TOP(1) sfdc_opportunity_update_id
						,order_header_id
						,sfdc_template_id
						,sfdc_update_type_id
						,sfdc_update_status_id
						,insert_date
						,process_date
						,archive_date AS execution_date
						,update_attempts
						,sfdc_response_message
					FROM dbo.sfdc_opportunity_update_archive
					WHERE order_header_id = @order_header_id
					ORDER BY sfdc_opportunity_update_archive_id DESC
					UNION
					SELECT TOP(1) sfdc_opportunity_update_id
						,order_header_id
						,sfdc_template_id
						,sfdc_update_type_id
						,sfdc_update_status_id
						,insert_date
						,process_date
						,failure_date AS execution_date
						,update_attempts
						,sfdc_response_message
					FROM dbo.sfdc_opportunity_update_failure
					WHERE order_header_id = @order_header_id
					ORDER BY sfdc_opportunity_update_failure_id DESC
				)
				INSERT INTO @sfdc_opportunity (
					opportunity_id
					,sfdc_
opportunity_update_id
					,order_header_id
					,sfdc_template_id
					,sfdc_update_type_id
					,sfdc_update_status_id
					,insert_date
					,process_date
					,execution_date
					,attempts_count
					,failure_description
					)
				SELECT TOP(1) @opportunity_id
					,sfdc_opportunity_update_id
					,order_header_id
					,sfdc_template_id
					,sfdc_update_type_id
					,sfdc_update_status_id
					,insert_date
					,process_date
					,execution_date
					,update_attempts
					,sfdc_response_message
				FROM sfdc_opportunity_update_archive_failure_cte
				ORDER BY execution_date DESC
			END
		END
		ELSE
		BEGIN
			-- Get entry from sfdc_opportunity_load table
			INSERT INTO @sfdc_opportunity (
				opportunity_id
				,sfdc_opportunity_load_id
				,sfdc_template_id
				,sfdc_update_type_id
				,sfdc_update_status_id
				,insert_date
				,process_date
				,attempts_count
				)
			SELECT TOP(1) opportunity_id
				,sfdc_opportunity_load_id
				,sfdc_template_id
				,sfdc_update_type_id
				,sfdc_update_status_id
				,insert_date
				,process_date
				,load_attempts
			FROM dbo.sfdc_opportunity_load
			WHERE opportunity_id = @opportunity_id
			ORDER BY sfdc_opportunity_load_id DESC
	
			-- If there is no records in sfdc_opportunity_load then will look into 
			-- sfdc_opportunity_load_archive or sfdc_opportunity_load_failure
			IF @@ROWCOUNT = 0
			BEGIN
				-- checks sfdc_opportunity_load_archive la
				WITH sfdc_opportunity_load_archive_failure_cte AS (
					SELECT TOP(1) sfdc_opportunity_load_id
						,opportunity_id
						,sfdc_template_id
						,sfdc_update_type_id
						,sfdc_update_status_id
						,insert_date
						,process_date
						,archive_date AS execution_date
						,load_attempts
						,'' AS failure_description
					FROM dbo.sfdc_opportunity_load_archive
					WHERE opportunity_id = @opportunity_id
					ORDER BY sfdc_opportunity_load_archive_id DESC
					UNION
					SELECT TOP(1) solf.sfdc_opportunity_load_id
						,solf.opportunity_id
						,solf.sfdc_template_id
						,solf.sfdc_update_type_id
						,solf.sfdc_update_status_id
						,solf.insert_date
						,solf.process_date
						,solf.failure_date AS execution_date
						,solf.load_attempts
						,solf0.failure_description
					FROM dbo.sfdc_opportunity_load_failure solf
					JOIN dbo.sfdc_opportunity_load_failure solf0
						ON solf.sfdc_opportunity_load_id = solf0.sfdc_opportunity_load_id
							AND solf0.load_attempts = 0
					WHERE solf.opportunity_id = @opportunity_id
					ORDER BY solf.sfdc_opportunity_load_failure_id DESC
				)
				INSERT INTO @sfdc_opportunity (
					opportunity_id
					,sfdc_opportunity_load_id
					,sfdc_template_id
					,sfdc_update_type_id
					,sfdc_update_status_id
					,insert_date
					,process_date
					,execution_date
					,attempts_count
					,failure_description
					)
				SELECT TOP(1) opportunity_id
					,sfdc_opportunity_load_id
					,sfdc_template_id
					,sfdc_update_type_id
					,sfdc_update_status_id
					,insert_date
					,process_date
					,execution_date
					,load_attempts
					,failure_description
				FROM sfdc_opportunity_load_archive_failure_cte
				ORDER BY execution_date DESC
			END
		END

		SET @response_code = 0 -- Success
		SET @message = 'Opportunity details found in ECom.'

		-- Return result
		SELECT so.opportunity_id
			,so.sfdc_opportunity_update_id
			,so.sfdc_opportunity_load_id
			,so.order_header_id
			,so.sfdc_template_id
			,st.sfdc_template_name
			,so.sfdc_update_type_id
			,sut.sfdc_update_type_name
			,so.sfdc_update_status_id
			,sus.sfdc_update_status_name
			,so.insert_date
			,so.process_date
			,so.attempts_count
			,so.execution_date
			,so.failure_description
		FROM @sfdc_opportunity so
		INNER JOIN dbo.sfdc_template st WITH (NOLOCK) ON so.sfdc_template_id = st.sfdc_template_id
		INNER JOIN dbo.sfdc_update_type sut WITH (NOLOCK) ON so.sfdc_update_type_i
d = sut.sfdc_update_type_id
		INNER JOIN dbo.sfdc_update_status sus WITH (NOLOCK) ON so.sfdc_update_status_id = sus.sfdc_update_status_id
		
	END TRY	
	BEGIN CATCH
		SET @response_code = ERROR_NUMBER()
		SET @message = 'Failed to fetch opportunity details.'
	
		-- Log error and return failure.
		DECLARE @db_name NVARCHAR(128)
		SET @db_name = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @db_name
	END CATCH
END

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_opportunity_load]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_opportunity_load]

(
	@opportunity_id varchar(18) = null,
	@salesforce_trial_id varchar(18) = null,
	@license_update_id varchar(18) = null,
	@sfdc_case_id varchar(18) = null,
	@sfdc_vault_id varchar(18) = null,
	@sfdc_update_status_name varchar(20) = null,
	@start_date datetime = null,
	@end_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2014-08-19	esmart		Use function to handle 15 char salesforce IDs
	2016-10-03	esmart		Add sfdc_opportunity_load_failure_id
	2021-01-04	esmart		Add @sfdc_case_id and @sfdc_vault_id

	DESCRIPTION
	Insert opportunity
*/

AS
	set nocount on				

	declare	@opportunity_id_length int,
			@salesforce_trial_id_length int,
			@sfdc_update_status_id tinyint,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) update to 18 char
	if @opportunity_id is not null and len(@opportunity_id) = 15
		begin
		select @opportunity_id = dbo.fn_ConvertSalesforceID_15to18(@opportunity_id)
		end

	if @salesforce_trial_id is not null and len(@salesforce_trial_id) = 15
		begin
		select @salesforce_trial_id = dbo.fn_ConvertSalesforceID_15to18(@salesforce_trial_id)
		end	

	if @license_update_id is not null and len(@license_update_id) = 15
		begin
		select @license_update_id = dbo.fn_ConvertSalesforceID_15to18(@license_update_id)
		end	


	-- 1.2) @sfdc_update_status_name
	select @sfdc_update_status_id = sfdc_update_status_id
	from sfdc_update_status
	where sfdc_update_status_name = @sfdc_update_status_name

	if @sfdc_update_status_id is null
		begin
		select @sfdc_update_status_id = 0
		end 

	-- 1.3) @start_date
	if @start_date is null
		begin
		select @start_date = '2013-01-01'
		end
	if @end_date is null
		begin
		select @end_date = getdate()
		end

	-- select opportunity_id = @opportunity_id
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert load data
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @sfdc_opportunity_load table (sfdc_opportunity_load_id int, opportunity_id varchar(18), salesforce_trial_id varchar(18), license_update_id varchar(18), sfdc_template_id tinyint, sfdc_update_status_id tinyint, sfdc_update_type_id tinyint, insert_date datetime, process_date datetime, load_attempts tinyint, archive_date datetime, sfdc_opportunity_load_failure_id int, failure_description varchar(255))

	--select salesforce_trial_id_length = @salesforce_trial_id_length

	insert into @sfdc_opportunity_load(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_update_status_id, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date)
	select sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_update_status_id, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date
	from sfdc_opportunity_load a
	where a.sfdc_update_status_id = case when @sfdc_update_status_id is null then a.sfdc_update_status_id else @sfdc_update_status_id end and	
		(a.insert_date > @start_date or @start_date
 is null) and
		(a.insert_date < @end_date or @end_date is null)
		
	insert into @sfdc_opportunity_load(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_template_id, sfdc_update_status_id, insert_date, sfdc_update_type_id, load_attempts, process_date, archive_date)
	select la.sfdc_opportunity_load_id, la.opportunity_id, la.salesforce_trial_id, la.license_update_id, la.sfdc_template_id, la.sfdc_update_status_id, la.insert_date, la.sfdc_update_type_id, la.load_attempts, la.process_date, la.archive_date
	from sfdc_opportunity_load_archive la
	inner join (select sfdc_opportunity_load_archive_id = max(sfdc_opportunity_load_archive_id)
				from sfdc_opportunity_load_archive a
				where a.sfdc_update_status_id = case when @sfdc_update_status_id is null then a.sfdc_update_status_id else @sfdc_update_status_id end and	
					(a.archive_date > @start_date or @start_date is null) and
					(a.archive_date < @end_date or @end_date is null)
				group by sfdc_opportunity_load_id) t
		on la.sfdc_opportunity_load_archive_id = t.sfdc_opportunity_load_archive_id
	
	insert into @sfdc_opportunity_load(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_template_id, sfdc_update_status_id, insert_date, sfdc_update_type_id, load_attempts, process_date, archive_date, sfdc_opportunity_load_failure_id, failure_description)
	select la.sfdc_opportunity_load_id, la.opportunity_id, la.salesforce_trial_id, la.license_update_id, la.sfdc_template_id, la.sfdc_update_status_id, la.insert_date, la.sfdc_update_type_id, la.load_attempts, la.process_date, la.failure_date, la.sfdc_opportunity_load_failure_id, la.failure_description
	from sfdc_opportunity_load_failure la
	inner join (select sfdc_opportunity_load_failure_id = max(sfdc_opportunity_load_failure_id)
				from sfdc_opportunity_load_failure a
				where a.sfdc_update_status_id = case when @sfdc_update_status_id is null then a.sfdc_update_status_id else @sfdc_update_status_id end and	
					(a.failure_date > @start_date or @start_date is null) and
					(a.failure_date < @end_date or @end_date is null)
				group by sfdc_opportunity_load_id) t
		on la.sfdc_opportunity_load_failure_id = t.sfdc_opportunity_load_failure_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) delete non-matching
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.1) @opportunity_id
	if @opportunity_id is not null
		begin
		-- print '3.1'
		delete from @sfdc_opportunity_load where sfdc_opportunity_load_id not in (select sfdc_opportunity_load_id from @sfdc_opportunity_load where opportunity_id = @opportunity_id)
		end

	-- 3.2) @@salesforce_trial_id
	if @salesforce_trial_id is not null
		begin
		-- print '3.2'
		delete from @sfdc_opportunity_load where sfdc_opportunity_load_id not in (select sfdc_opportunity_load_id from sfdc_opportunity_load where salesforce_trial_id = @salesforce_trial_id)
		end

	-- 3.3) @license_update_id
	if @license_update_id is not null
		begin
		-- print '3.2'
		delete from @sfdc_opportunity_load where sfdc_opportunity_load_id not in (select sfdc_opportunity_load_id from sfdc_opportunity_load where license_update_id = @license_update_id)
		end

	-- 3.4) @sfdc_case_id
	if @sfdc_case_id is not null
		begin
		delete from @sfdc_opportunity_load where sfdc_opportunity_load_id not in (select l.sfdc_opportunity_load_id
																				from @sfdc_opportunity_load l
																				inner join sfdc_opportunity_load_json j
																					on j.sfdc_opportunity_load_id = l.sfdc_opportunity_load_id
																				where json_value(j.sfdc_load_json,'$.sfdc_case_id') = @sfdc_case_id)
		end

	-- 3.5) @sfdc_vault_id
	if @sfdc_vault_id i
s not null
		begin
		delete from @sfdc_opportunity_load where sfdc_opportunity_load_id not in (select l.sfdc_opportunity_load_id
																				from @sfdc_opportunity_load l
																				inner join sfdc_opportunity_load_json j
																					on j.sfdc_opportunity_load_id = l.sfdc_opportunity_load_id
																				where json_value(j.sfdc_load_json,'$.sfdc_vault_id') = @sfdc_vault_id)
		end
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.) return result
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select l.sfdc_opportunity_load_id, 
			l.opportunity_id, 
			l.salesforce_trial_id, 
			l.license_update_id,
			tm.sfdc_template_id,
			tm.sfdc_template_name,	
			l.sfdc_update_status_id, 
			s.sfdc_update_status_name, 
			l.sfdc_update_type_id, 
			t.sfdc_update_type_name, 
			l.insert_date, 
			l.load_attempts, 
			l.process_date, 
			l.archive_date, 
			l.sfdc_opportunity_load_failure_id,
			l.failure_description, 
			l.sfdc_update_status_id, 
			oo.order_header_id, 
			v.vendor_order_code,
			j.sfdc_load_json
	from @sfdc_opportunity_load l
	inner join sfdc_template tm with (nolock)
		on l.sfdc_template_id = tm.sfdc_template_id
	inner join sfdc_update_status s
		on l.sfdc_update_status_id = s.sfdc_update_status_id
	inner join sfdc_update_type t
		on l.sfdc_update_type_id = t.sfdc_update_type_id
	left join order_opportunity oo
		on l.opportunity_id = oo.salesforce_opportunity_id
	left join order_header h
		on oo.order_header_id = h.order_header_id
	left join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	left join sfdc_opportunity_load_json j
		on j.sfdc_opportunity_load_id = l.sfdc_opportunity_load_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_opportunity_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_opportunity_update]

(
	@opportunity_id varchar(18) = null,
	@vendor_order_code varchar(100) = null,
	@keycode varchar(40) = null,
	@salesforce_trial_id varchar(18) = null,
	@sfdc_update_status_name varchar(20) = null,
	@start_date datetime = null,
	@end_date datetime = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2014-04-15	esmart		Add fort_submit_id
	2016-10-03	esmart		Add sfdc_opportunity_update_failure_id

	DESCRIPTION
	Select opportunity update
*/

AS
	set nocount on				

	declare	@opportunity_id_length int,
			@sfdc_update_status_id tinyint,
			@order_header_id int,
			@trial_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check to see length of sfdc id
	select @opportunity_id_length = len(@opportunity_id)

	if @opportunity_id_length is null 
		begin
		select @opportunity_id_length = 18
		end

	-- 1.2) @sfdc_update_status_name
	select @sfdc_update_status_id = sfdc_update_status_id
	from sfdc_update_status
	where sfdc_update_status_name = @sfdc_update_status_name

	-- 1.3) @order_header_id
	select @order_header_id = h.order_header_id
	from order_header h
	inner join vendor_order v
		on h.vendor_order_id = v.vendor_order_id
	where v.vendor_order_code = @vendor_order_code

	-- 1.3.1) order_header_id from opportunity_id
	if @order_header_id is null
		begin
		select @order_header_id = order_header_id
		from order_opportunity
		where left(salesforce_opportunity_id,@opportunity_id_length) COLLATE Latin1_General_CS_AS = @opportunity_id
		end

	-- 1.4) @trial_id
	select @trial_id = trial_id
	from trial t
	inner join license l
		on t.license_id = l.license_id
	where l.keycode = @keycode

	-- 1.5) @salesforce_trial_id
	select @trial_id = t.trial_id
	from trial t
	inner join trial_registration r
		on t.trial_registration_id = r.trial_registration_id
	where r.sfdc_trial_id = @salesforce_trial_id

	-- select order_header_id = @order_header_id, trial_id = @trial_id, sfdc_update_status_id = @sfdc_update_status_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert rows
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @sfdc_opportunity_update table (sfdc_opportunity_update_id int, order_header_id int, trial_id int, form_submit_id int, sfdc_template_id tinyint, sfdc_update_type_id tinyint, sfdc_update_status_id tinyint, insert_date datetime, process_date datetime, update_attempts tinyint, archive_date datetime, sfdc_opportunity_update_failure_id int, failure_description varchar(255))

	-- 2.1) sfdc_opportunity_update
	insert into @sfdc_opportunity_update (sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_template_id, sfdc_update_type_id, sfdc_update_status_id, insert_date, update_attempts, process_date)
	select sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_template_id, sfdc_update_type_id, sfdc_update_status_id, insert_date, update_attempts, process_date
	from sfdc_opportunity_update
	where sfdc_update_status_id = case when @sfdc_update_sta
tus_id is null then sfdc_update_status_id else @sfdc_update_status_id end


	-- 2.2) sfdc_opportunity_update_archive
	insert into @sfdc_opportunity_update (sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_template_id, sfdc_update_type_id, sfdc_update_status_id, insert_date, update_attempts, process_date, archive_date)
	select a.sfdc_opportunity_update_id, a.order_header_id, a.trial_id, a.form_submit_id, a.sfdc_template_id, a.sfdc_update_type_id, a.sfdc_update_status_id, a.insert_date, a.update_attempts, a.process_date, a.archive_date
	from sfdc_opportunity_update_archive a
	inner join (select sfdc_opportunity_update_archive_id = max(sfdc_opportunity_update_archive_id)
				from sfdc_opportunity_update_archive
				where sfdc_update_status_id = case when @sfdc_update_status_id is null then sfdc_update_status_id else @sfdc_update_status_id end and
					(archive_date > @start_date or @start_date is null) and
					(archive_date < @end_date or @end_date is null)
				group by sfdc_opportunity_update_id) t
		on a.sfdc_opportunity_update_archive_id = t.sfdc_opportunity_update_archive_id
	
	
	-- 2.2) sfdc_opportunity_update_failure
	insert into @sfdc_opportunity_update (sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_template_id, sfdc_update_type_id, sfdc_update_status_id, insert_date, update_attempts, process_date, archive_date, sfdc_opportunity_update_failure_id, failure_description)
	select a.sfdc_opportunity_update_id, a.order_header_id, a.trial_id, a.form_submit_id, a.sfdc_template_id, a.sfdc_update_type_id, a.sfdc_update_status_id, a.insert_date, a.update_attempts, a.process_date, a.failure_date, a.sfdc_opportunity_update_failure_id, a.sfdc_response_message
	from sfdc_opportunity_update_failure a
	inner join (select sfdc_opportunity_update_failure_id = max(sfdc_opportunity_update_failure_id)
				from sfdc_opportunity_update_failure
				where sfdc_update_status_id = case when @sfdc_update_status_id is null then sfdc_update_status_id else @sfdc_update_status_id end and
					(failure_date > @start_date or @start_date is null) and
					(failure_date < @end_date or @end_date is null)
				group by sfdc_opportunity_update_id) t
		on a.sfdc_opportunity_update_failure_id = t.sfdc_opportunity_update_failure_id

	select * from @sfdc_opportunity_update

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) remove rows not specific to order_header
	if @order_header_id is not null
		begin
		delete from @sfdc_opportunity_update where order_header_id <> @order_header_id or order_header_id is null
		end

	-- 3.2) remove rows not specific to trial
	if @trial_id is not null
		begin
		delete from @sfdc_opportunity_update where trial_id <> @trial_id or trial_id is null
		end

	-- 3.3) return results
	select u.sfdc_opportunity_update_id, 
			u.order_header_id, 
			v.vendor_order_code, 
			u.trial_id, 
			u.form_submit_id,
			l.license_id, 
			l.keycode, 
			u.sfdc_template_id, 
			tm.sfdc_template_name,
			t.sfdc_update_type_id, 
			t.sfdc_update_type_name, 
			s.sfdc_update_status_id, 
			s.sfdc_update_status_name, 
			u.insert_date, 
			u.process_date, 
			u.update_attempts,
			u.archive_date, 
			u.sfdc_opportunity_update_failure_id,
			u.failure_description,
			st.salesforce_lead_id, 
			salesforce_opportunity_id = case
											when oo.salesforce_opportunity_id is not null then oo.salesforce_opportunity_id
											else st.salesforce_opportunity_id
										end,
			st.salesforce_trial_id
	from @sfdc_opportunity_update u
	inner join sfdc_update_status s with (nolock)
		on u.sfdc_update_status_id = s.sfdc_update_status_id
	inne
r join sfdc_update_type t with (nolock)
		on u.sfdc_update_type_id = t.sfdc_update_type_id
	inner join sfdc_template tm with (nolock)
		on u.sfdc_template_id = tm.sfdc_template_id
	left join order_header h with (nolock)
		on u.order_header_id = h.order_header_id 
	left join order_opportunity oo
		on h.order_header_id = oo.order_header_id
	left join vendor_order v with (nolock)
		on h.vendor_order_id = v.vendor_order_id
	left join trial tr with (nolock)
		on u.trial_id = tr.trial_id
	left join license l with (nolock)
		on tr.license_id = l.license_id
	left join sfdc_trial st with (nolock)
		on tr.trial_id = st.trial_id
	order by u.archive_date desc
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_opportunity_update_batch]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_opportunity_update_batch]


/*	
	DATE		AUTHOR		REMARKS
	2013-09-06	esmart		Initial creation.
	2016-08-24	cnovac		Added sfdc_queue_type to be returned

	DESCRIPTION
	select sfdc update batch
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select q.sfdc_queue_type_id, q.sfdc_queue_type_name, batch_limit_date = max(u.process_date)
	from sfdc_opportunity_update u
	inner join sfdc_update_type t
		on u.sfdc_update_type_id = t.sfdc_update_type_id
	inner join sfdc_template st
		on u.sfdc_template_id = st.sfdc_template_id
	inner join sfdc_queue_type q
		on q.sfdc_queue_type_id = st.sfdc_queue_type_id
	where u.sfdc_update_status_id in (0,2)
	and u.process_date <= getdate()
	group by q.sfdc_queue_type_id, q.sfdc_queue_type_name 
	order by q.sfdc_queue_type_id, q.sfdc_queue_type_name
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
