-- PROCEDURE: [dbo].[usp_sfdc_select_opportunity_update_task]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_opportunity_update_task]

(
@license_id int,
@processed bit = NULL 
)

/*     
       DATE          AUTHOR        REMARKS
       2017-05-17    acoffel              Initial creation.
       
       DESCRIPTION
       Select task details
*/

AS
       set nocount on                           

       declare @response_code int,
                     @message varchar(100)                    

       begin try

              SET ANSI_NULLS ON
			  SET QUOTED_IDENTIFIER ON
              SET ANSI_WARNINGS ON

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 1.) select record per license_id 
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       if @processed is NULL
              begin 
			      select top 1 *
                     from  [license_parent_device_status]
                     where license_id = @license_id 
                     and processed = 0
              end

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 2.) update record as processed 
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       if @processed = 1
              begin
			    update [license_parent_device_status]
                     set processed = 1 
                     where license_id = @license_id 
                     and processed = 0
                     and @processed = 1
                  select response = 'License Updated'
            end

       end try

       begin catch

              set @response_code = -200
              set @message = case when @message is null then 'insert failed'
                                                else @message end

              declare @DBName nvarchar(128)
              set @DBName = db_name()
              exec usp_LogError @ErrorDB = @DBName
              
       end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_order_company]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_order_company]	

(
	@order_header_id int,
	@order_company_type_name varchar(50) = null

)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-06	esmart		Initial creation.
	2016-02-05	esmart		Add @order_company_type_name
	2016-05-13	acoffel		extend customer_id and address_type
	2016-09-26	esmart		Remove join to customer_company
	2017-01-30	esmart		Implement partner_configuration override
	2017-03-27	esmart		External order
	2021-05-19	esmart		Add reseller and distributer mapping when selecting from customer_order

	DESCRIPTION
	update customer.salesforce_contact_id
*/

AS
	set nocount on				

	declare @configuration_value varchar(500),
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) check for bill_to_account override configuration on partner
	if @order_company_type_name = 'bill_to_account'
		begin
		
		select @configuration_value = cp.configuration_value
		from order_company oc
		inner join order_company_type t
			on oc.order_company_type_id = t.order_company_type_id
		inner join company c
			on oc.company_id = c.company_id
		inner join partner p
			on c.salesforce_account_id = p.salesforce_id
		inner join partner_configuration_partner cp
			on cp.partner_id = p.partner_id and cp.partner_configuration_id = 18
		where oc.order_header_id = @order_header_id and
			t.order_company_type_name = @order_company_type_name

		if @configuration_value is not null
			begin
			set @order_company_type_name = @configuration_value
			end

		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) @order_company
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @order_company table (order_company_id int, order_header_id int, order_company_type_id tinyint, order_company_type_name varchar(50), order_company_type_description varchar(50), company_id int, company_name nvarchar(255), salesforce_account_id varchar(20), customer_id int)

	if exists (select order_company_id from order_company where order_header_id = @order_header_id)
		begin
		insert into @order_company (order_company_id, order_header_id, order_company_type_id, order_company_type_name, order_company_type_description, company_id, company_name, salesforce_account_id, customer_id)
		select distinct oc.order_company_id, oc.order_header_id,t.order_company_type_id,t.order_company_type_name, t.order_company_type_description, c.company_id,c.company_name,c.salesforce_account_id, oc.customer_id
		from order_company oc
		inner join order_company_type t
			on oc.order_company_type_id = t.order_company_type_id
		inner join company c
			on oc.company_id = c.company_id
		where oc.order_header_id = @order_header_id and
			t.order_company_type_name = case when @order_company_type_name is null then t.order_company_type_name else @order_company_type_name end
		end
	else
		begin
		insert into @order_company (order_company_id, order_header_id, order_company_type_id, order_company_type_name, order_company_type_description, company_id, company_name, salesforce_account_id, customer_id)
		select order_company_id = null, 
			co.order_h
eader_id, 
			t.order_company_type_id, 
			t.order_company_type_name, 
			t.order_company_type_description, 
			company_id = cc.company_id, 
			company_name = case when cm.company_name is null then cc.company_name else cm.company_name end, 
			cm.salesforce_account_id, 
			c.customer_id
		from customer_order co
		inner join order_company_type t
			on t.order_company_type_id = case 
											when co.customer_type_id = 1 then 2 
											when co.customer_type_id = 2 then 1 
											when co.customer_type_id = 3 then 3
											when co.customer_type_id = 4 then 4
										end
		inner join customer c
			on c.customer_id = co.customer_id
		inner join customer_company cc
			on cc.customer_id = co.customer_id
		left join company cm
			on cm.company_id = cc.company_id
		where co.order_header_id = @order_header_id
		
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select order_company_id, order_header_id, order_company_type_id, order_company_type_name, order_company_type_description, company_id, company_name, salesforce_account_id, customer_id
	from @order_company
	order by order_company_type_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_order_item_pricebook]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_select_order_item_pricebook]

(
	@order_header_id int 
)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-06	esmart		Initial creation.

	DESCRIPTION
	select item pricebook
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select p.PricebookEntryId,p.PricebookEntryName,p.Product2Id,p.Product2Name,p.CurrencyCode,p.PriceBookUnitPrice,i.product_id,i.list_price,i.unit_price,i.quantity,
			discount = p.PriceBookUnitPrice - i.unit_price,
			discount_percent = (p.PriceBookUnitPrice - i.unit_price)/p.PriceBookUnitPrice,
			y.years,
			i.order_item_id,
			oi.opportunity_line_item_id
			--,round(p.PriceBookUnitPrice * (1-((p.PriceBookUnitPrice - i.unit_price)/p.PriceBookUnitPrice)),2)
	from order_item i with (nolock)
	inner join order_currency oc with (nolock)
		on i.order_header_id = oc.order_header_id
	inner join currency c with (nolock)
		on oc.currency_id = c.currency_id
	inner join product_years y with (nolock)
		on i.product_id = y.product_id
	inner join sfdc_pricebook_product_mapping m with (nolock)
		on i.product_id = m.product_id
	inner join sfdc_pricebook_product p with (nolock)
		on m.sfdc_pricebook_product_id = p.sfdc_pricebook_product_id and p.CurrencyCode = c.currency_code
	left join order_item_opportunity_line_item oi with (nolock)
		on i.order_item_id = oi.order_item_id
	where i.order_header_id = @order_header_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
