-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_template_update_type]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_select_template_update_type]

(
	@sfdc_template_id tinyint = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	

		DESCRIPTION
		select template update type
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) create table
	declare @template_update_type table (step_id tinyint identity(1,1), sfdc_template_id tinyint, sfdc_template_name varchar(50), sfdc_update_type_id tinyint, sfdc_update_type_name varchar(20), next_update_type_id tinyint, next_update_type_name varchar(20))

	-- 1.2) insert rows
	insert into @template_update_type(sfdc_template_id, sfdc_template_name, sfdc_update_type_id, sfdc_update_type_name, next_update_type_id, next_update_type_name)
	select t.sfdc_template_id, 
			t.sfdc_template_name, 
			u.sfdc_update_type_id, 
			u.sfdc_update_type_name, 
			next_update_type_id = n.sfdc_update_type_id, 
			next_update_type_name = n.sfdc_update_type_name
	from sfdc_template_update_type tu
	inner join sfdc_template t
		on tu.sfdc_template_id = t.sfdc_template_id
	inner join sfdc_update_type u
		on tu.sfdc_update_type_id = u.sfdc_update_type_id
	left join sfdc_update_type n
		on tu.next_update_type_id = n.sfdc_update_type_id
	where tu.sfdc_template_id = case when @sfdc_template_id is null then tu.sfdc_template_id else @sfdc_template_id end
	order by tu.sfdc_template_update_type_id

	-- 1.3) return results
	select step_id, sfdc_template_id, sfdc_template_name, sfdc_update_type_id, sfdc_update_type_name, next_update_type_id, next_update_type_name
	from @template_update_type
	order by step_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_test_group_batch]
-- =============================================================================

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Cron Procedures - Test Group
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[usp_sfdc_select_test_group_batch]

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial creation

	DESCRIPTION
	Used to get batchdate for cron
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	SELECT batch_count = count(*), batch_limit_date = GETDATE()
	FROM license_message lm
	WHERE message_status_id in (3) 
		and lm.message_type_id in (17)
		AND lm.process_date <= GETDATE()
		AND NOT EXISTS 
			(SELECT license_message_id 
				FROM license_message_value lmv 
				WHERE lm.license_message_id = lmv.license_message_id
					AND message_value_type_id = 21)
		AND EXISTS
			(SELECT license_message_id 
				FROM license_message_value lmv 
				WHERE lm.license_message_id = lmv.license_message_id
					AND message_value_type_id = 23 --in_journey is 1
					AND lmv.value_id = 1)


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_select_update_batch]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_sfdc_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	Initial creation
	2017-08-09	mrobbins	edited to give back all records for entire day

	DESCRIPTION
	Used to get batchdate for cron
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)


	SELECT batch_count = count(*), batch_limit_date = CAST(GETDATE() AS DATE)
	FROM license_message
	WHERE message_status_id in (1) 
		and message_type_id in (13,14,16)
		AND CAST(process_date AS DATE) <= CAST(GETDATE() AS DATE)

GO
