-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_subscriber_held_processed]

(
		@sfdc_subscriber_held_id INT,
		@api_response VARCHAR(2000)
)

/*	
	DATE		AUTHOR		REMARKS
	2018-03-21	mrobbins	initial creation

	DESCRIPTION
	
	
*/


AS

	BEGIN TRY

		DECLARE @response_code INT,
				@message VARCHAR(100)

		SET NOCOUNT ON				

	
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		IF @api_response LIKE '%error%'
			BEGIN
				UPDATE sfdc_subscriber_held
				SET api_response = @api_response, 
					processed = 2,
					processed_date = GETDATE()
				WHERE sfdc_subscriber_held_id = @sfdc_subscriber_held_id
			END
        ELSE
			BEGIN
				UPDATE sfdc_subscriber_held
				SET api_response = @api_response, 
					processed = 1,
					processed_date = GETDATE()
				WHERE sfdc_subscriber_held_id = @sfdc_subscriber_held_id
			END 
		
		
		

	END TRY 

	BEGIN CATCH

		SET @response_code = -200
		SET @message = 'Could not update held subscriber'

		DECLARE @DBName nvarchar(128)
		SET @DBName = db_name()
		EXEC usp_LogError @ErrorDB = @DBName
	
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_case]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_sfdc_update_case]


(
	@salesforce_case_id varchar(18),
	@sfdc_case_status_name varchar(100),
	@case_update_json nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2020-08-27	esmart		Initial creation.
	2022-05-19  psatish		ALM# 990 Added sap_material_no in the order_item_audit
	DESCRIPTION
	Update sfdc_case
*/

AS

set nocount on				

begin try

		declare	@sfdc_case_id int,		
				@sfdc_case_status_id tinyint,
				@salesforce_opportunity_id varchar(18),
				@order_header_id int,
				@license_category_id int,
				@transaction_date datetime,
				@effective_date date,
				@vendor_order_code varchar(100),
				@partner_license_status_id tinyint,
				@account_order_json varchar(max),
				@sfdc_template_name varchar(50),	
				@trial_id int,
				@form_submit_id int,
				@process_date datetime,
				@license_id int,
				@sfdc_update_json nvarchar(max),
				@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @transaction_date = getdate(), @effective_date = getdate()

		-- 1.1) @sfdc_case_id
		select @sfdc_case_id = c.sfdc_case_id, @license_category_id = cl.license_category_id
		from sfdc_case c
		inner join license_category_license cl
			on cl.license_id = c.license_id
		where c.salesforce_case_id = @salesforce_case_id

		-- 1.1) @sfdc_case_status_id
		select @sfdc_case_status_id = t.sfdc_case_status_id
		from sfdc_case_status t
		where t.sfdc_case_status_name = @sfdc_case_status_name

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) order_item updates
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) @salesforce_opportunity_id and @order_header_id
		select @salesforce_opportunity_id = salesforce_opportunity_id
		from openjson(@case_update_json) 
		with (salesforce_opportunity_id varchar(18) '$.salesforce_opportunity_id')

		select @order_header_id = oo.order_header_id, @vendor_order_code = v.vendor_order_code
		from order_opportunity oo
		inner join order_header h
			on h.order_header_id = oo.order_header_id
		inner join vendor_order v
			on v.vendor_order_id = h.vendor_order_id
		where oo.salesforce_opportunity_id = @salesforce_opportunity_id

		-- 2.2) update order_item with new dates
		insert into order_item_audit (order_item_id, order_header_id, line_item, product_id, quantity, list_price, unit_price, tax, order_item_offer_id, order_item_offer_amount, item_total, tax_exempt, effective_date, order_item_status_id, insert_date, insert_by, modified_date, modified_by, capability_expiration_date, item_bundle_id, order_item_update_type_id, audit_date, sap_material_number)
		select i.order_item_id, i.order_header_id, i.line_item, i.product_id, i.quantity, i.list_price, i.unit_price, i.tax, i.order_item_offer_id, i.order_item_offer_amount, i.item_total, i.tax_exempt, i.effective_date, i.order_item_status_id, i.insert_date, i.insert_by, i.modified_date, i.modified_by, i.capability_expiration_date, i.item_bundle_id, i.order_item_update_type_id, @transaction_date as audit_date, i.sap_material_number
		from order_item i
		inner join product_license_category plc
			on plc.product_id = i.product_id
		where i.order_header_id = @order_header_id and 
plc.license_category_id = @license_category_id

		update i
		set i.effective_date = @effective_date, i.capability_expiration_date = dateadd(dd,datediff(dd,i.effective_date,i.capability_expiration_date),@effective_date)
		from order_item i
		inner join product_license_category plc
			on plc.product_id = i.product_id
		where i.order_header_id = @order_header_id and plc.license_category_id = @license_category_id
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) license updates
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 3.1) update start/end date - NOTE: This might need to change considering other products on the same order. Might be better to use license_service.
		exec usp_cart_update_order_license_new @vendor_order_code=@vendor_order_code, @partner_license_status_id=@partner_license_status_id, @account_order_json=@account_order_json
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 4.) finalize
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 4.1) update sfdc_case
		update sfdc_case 
		set sfdc_case_status_id = @sfdc_case_status_id, case_create_json = @case_update_json, modified_date = getdate()
		where sfdc_case_id = @sfdc_case_id

		-- 4.2) insert sfdc_opportunity_update
		select @sfdc_template_name = 'sap_update_license'

		exec usp_sfdc_insert_sfdc_opportunity_update @sfdc_template_name = @sfdc_template_name,@order_header_id = @order_header_id,@trial_id = @trial_id,@form_submit_id = @form_submit_id,@process_date = @transaction_date,@license_id = @license_id,@sfdc_update_json = @sfdc_update_json
		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'update failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_company_account]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_company_account]

(
    @company_id int = null,
    @customer_id int = null,
    @salesforce_account_id varchar(20)
)

/*
    DATE        AUTHOR      REMARKS
    2013-08-06  esmart      Initial creation.
    2020-06-16  jnavarra    Modify for new company_name

    DESCRIPTION
    update customer.salesforce_contact_id
*/

AS
    set nocount on                

    declare    @company_type_id tinyint,
            @company_name nvarchar(255),
            @response_code int,
            @message varchar(100)

    begin try

    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    -- 1.) select
    -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
    
    select @company_type_id = 14 -- Business

    -- 1.1) look up @company from customer
    if @company_id is null
        begin
        select
            @company_id = company_id,
            @company_name = company_name
        from customer_company
        where customer_id = @customer_id

        -- 1.1.1) insert new company
        if @company_id is null
            begin
            insert into company (company_name, salesforce_account_id, company_type_id)
            values (@company_name, @salesforce_account_id, @company_type_id)

            select @company_id = scope_identity()

            exec dbo.usp_company_insert_company_name @company_id = @company_id, @company_name = @company_name, @company_name_type = 'Primary'
            end
    
        -- 1.1.2) update customer_company
            insert into customer_company_audit(customer_company_id, customer_id,company_name, insert_date, insert_by,modified_date, modified_by, company_id,customer_type_id)
            select customer_company_id, customer_id,company_name, insert_date, insert_by,modified_date, modified_by, company_id,customer_type_id
            from customer_company
            where customer_id = @customer_id

            update customer_company
            set company_id = @company_id,modified_date = getdate()
            where customer_id = @customer_id
        end

    -- 1.2) update company
        insert into company_audit (company_id, company_name, salesforce_account_id,last_modified_date, company_type_id)
        select company_id, company_name, salesforce_account_id,last_modified_date, company_type_id
        from company
        where company_id = @company_id

        update company 
        set salesforce_account_id = @salesforce_account_id
        where company_id = @company_id
    
        
    end try

    begin catch

        set @response_code = -200
        set @message = case when @message is null then 'select failed'
                            else @message end

        declare @DBName nvarchar(128)
        set @DBName = db_name()
        exec usp_LogError @ErrorDB = @DBName
        
    end catch;


GO
