-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_in_journey]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_update_in_journey]

(
	@license_message_id int,
	@sfdc_in_journey int

)
	
/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	intial creation

	DESCRIPTION
	inserts test_group into license_message_value
	
*/


AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin TRY
    
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update/insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--if not in the journey - then set to check again tomorrow
	IF @sfdc_in_journey = 0 
		BEGIN
			UPDATE license_message
			SET process_date = GETDATE() + 1,
				end_date = GETDATE() + 2,
				archive_date = GETDATE() + 3
			WHERE license_message_id = @license_message_id
		END
    
	--if in a journey - save the record to license_message_value    
	IF @sfdc_in_journey = 1
		BEGIN
			insert into license_message_value(license_message_id,message_value_type_id,value_id)
			select @license_message_id,
				23,
				@sfdc_in_journey

			UPDATE license_message
			SET message_status_id = 3
			WHERE license_message_id = @license_message_id

		END 

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
