-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_license_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_update_license_message]

(
	@license_message_id int,
	@message_status_id tinyint,
	@API_status int

)
	
/*	
	DATE		AUTHOR		REMARKS
	2017-08-02	mrobbins	intial creation

	DESCRIPTION
	Updates license_message and sets API response in license_message_value

	20	sfdc_API_response
	21	sfdc_test_group
	22	sfdc_customer_email_id
	23	in_journey

	sfdc_status 200 successful - anything else failure
	
*/


AS
	set nocount on				

	declare	@sfdc_api_status_id INT,
			@response_code int,
			@message varchar(100),
			@message_type_id int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		SELECT @sfdc_api_status_id = sfdc_api_status_id
		FROM sfdc_api_status
		WHERE sfdc_http_status = @API_status

		SELECT @message_type_id = message_type_id
		FROM dbo.license_message
		where license_message_id = @license_message_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update/insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	update license_message set message_status_id = @message_status_id where license_message_id = @license_message_id

	--insert customer_email_id so we have id of the email address that was used for composite_key
	--if license_message record is a 13, status of 3 then do this
	IF @message_type_id = 13 
		AND @message_status_id = 3
		BEGIN
			insert into license_message_value(license_message_id,message_value_type_id,value_id)
			select @license_message_id,
					22,
					ce.customer_email_id
			FROM dbo.license_message lm
				INNER JOIN dbo.license l
					ON lm.license_id = l.license_id
				INNER JOIN dbo.customer_email ce
					ON l.customer_id = ce.customer_id
						AND ce.email_status_id = 1
			WHERE lm.license_message_id = @license_message_id

			INSERT INTO dbo.license_message
				( license_id ,
					message_type_id ,
					message_status_id ,
					insert_date ,
					process_date ,
					end_date ,
					archive_date,
					message_campaign_id,
					message_campaign_class_id
				)
			SELECT lm.license_id,
				17 message_type_id, --in journey
				1 message_status_id,
				GETDATE() insert_date,
				DATEADD(HOUR,2,GETDATE()) process_date,
				GETDATE() + 1 end_date,
				GETDATE() + 1 archive_date,
				lm.message_campaign_id,
				lm.message_campaign_class_id
			FROM license_message lm
			WHERE lm.license_message_id = @license_message_id
				
		END
    

	insert into license_message_value(license_message_id,message_value_type_id,value_id)
	select @license_message_id,
		20,
		CASE WHEN @sfdc_api_status_id IS NULL THEN 0 ELSE @sfdc_api_status_id end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_license_message_journey]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sfdc_update_license_message_journey]

(
       @license_id INT 
)

/*     
       DATE                 AUTHOR        REMARKS

       2017-08-02           mrobbins             Initial creatiON


       DESCRIPTION
       Compares existing campaigns in the license_message table to new return from the campaign procedure


              message_type_id            message_type_name    message_type_description
              13                                journey_insert             journey insert
              14                                journey_update             journey update
              15                                subscriber_update    subscriber update
              16                                journey_exit         journey exit
*/

AS
       SET NOCOUNT ON       


       DECLARE @min_new_campaigns_id INT,
              @max_new_campaigns_id INT,
              @min_existing_campaigns_id INT,
              @max_existing_campaigns_id INT,

              --new variables
              @message_source VARCHAR(20), 
              @message_campaign_id INT, 
              @message_campaign_name VARCHAR(50), 
              @message_campaign_description VARCHAR(256), 
              @process_date DATETIME, 
              @end_date DATETIME, 
              @archive_date DATETIME,
              @message_key VARCHAR(36), 
              @license_message_id INT, 
              @message_content_id INT, 
              @cart_discount_id INT,
              @message_type_id INT,
              @license_message_value_str VARCHAR(MAX),

              --existing variables
              @message_source_existing VARCHAR(20), 
              @message_campaign_id_existing INT, 
              @message_campaign_name_existing VARCHAR(50), 
              @message_campaign_description_existing VARCHAR(256), 
              @process_date_existing DATETIME, 
              @end_date_existing DATETIME, 
              @archive_date_existing DATETIME,
              @message_key_existing VARCHAR(36), 
              @license_message_id_existing INT, 
              @message_content_id_existing INT, 
              @cart_discount_id_existing INT,
              @message_type_id_existing INT,
              @license_message_value_str_existing VARCHAR(MAX),
              @message_status_id_existing INT,
              @max_license_message_id_existing INT,
              @capability_expiration_date DATETIME,
              @refund INT,
              @response_code INT,
        @message VARCHAR(100)   
       
       BEGIN TRY



              DECLARE @latest_campaigns TABLE(latest_campaigns_id INT IDENTITY(1,1),
                     max_license_message_id INT,
                     message_campaign_id INT)

              INSERT INTO @latest_campaigns
              SELECT MAX(license_message_id),
                     message_campaign_id
              FROM dbo.license_message  WITH (NOLOCK)
              WHERE  license_id = @license_id
                     AND message_type_id = 13
                     AND end_date > GETDATE()
              GROUP BY message_campaign_id

              --SELECT *
              --FROM @latest_campaigns

              DECLARE @existing_campaigns TABLE(existing_campaigns_id INT IDENTITY(1,1),
                     license_id INT,
                     message_type_id INT,
                     message_status_id INT,
                     message_campaign_id INT, 
                     message_campaign_class_id INT,
                     message_campaign_name VARCHAR(50), 
                     message_campaign_description VARCHAR(256), 
                     process_date DATETIME, 
                
     end_date DATETIME, 
                     license_message_id INT)

              INSERT INTO @existing_campaigns (license_id,
                     message_type_id,
                     message_status_id,
                     message_campaign_id, 
                     message_campaign_class_id,
                     message_campaign_name, 
                     message_campaign_description, 
                     process_date, 
                     end_date, 
                     license_message_id)
              SELECT lm.license_id,
                     lm.message_type_id,
                     lm.message_status_id,
                     lm.message_campaign_id, 
                     lm.message_campaign_class_id,
                     mc.message_campaign_name, 
                     mc.message_campaign_description, 
                     lm.process_date, 
                     lm.end_date, 
                     lm.license_message_id
              FROM dbo.license_message lm  WITH (NOLOCK)
                     INNER JOIN dbo.message_campaign mc  WITH (NOLOCK)
                           ON lm.message_campaign_id = mc.message_campaign_id
                     INNER JOIN @latest_campaigns lc
                           ON lm.license_message_id = lc.max_license_message_id

              --SELECT *
              --FROM @existing_campaigns

              DECLARE @new_campaigns TABLE(new_campaigns_id INT IDENTITY(1,1),
                     message_source VARCHAR(50), 
                     message_campaign_id INT, 
                     message_campaign_name VARCHAR(50), 
                     message_campaign_description VARCHAR(256), 
                     process_date DATETIME, 
                     end_date DATETIME, 
                     message_key VARCHAR(36), 
                     license_message_id INT, 
                     message_content_id INT, 
                     cart_discount_id INT)

              INSERT INTO @new_campaigns(message_source, 
                     message_campaign_id, 
                     message_campaign_name, 
                     message_campaign_description, 
                     process_date, 
                     end_date, 
                     message_key, 
                     license_message_id, 
                     message_content_id, 
                     cart_discount_id)
              EXEC usp_SFDC_select_license_message_journey @license_id

              SELECT @capability_expiration_date = capability_expiration_date
              FROM license_summary  WITH (NOLOCK)
              WHERE license_id = @license_id

              --Zero out the variables
              SET @min_new_campaigns_id = 0
              SET @max_new_campaigns_id = 0


              --Campaign in New Table not existing     13 - journey start
              SELECT @min_new_campaigns_id = MIN(n.new_campaigns_id),
                     @max_new_campaigns_id = MAX(n.new_campaigns_id)
              FROM @new_campaigns n
              WHERE NOT EXISTS (SELECT message_campaign_id FROM @existing_campaigns e WHERE e.message_campaign_id = n.message_campaign_id)

              WHILE @min_new_campaigns_id <= @max_new_campaigns_id
                     BEGIN 
                           
                           SELECT @message_source = message_source, 
                                  @message_campaign_id = message_campaign_id, 
                                  @message_campaign_name = message_campaign_name, 
                                  @message_campaign_description = message_campaign_description, 
                                  @process_date = process_date,
                                  --@process_date = CASE WHEN process_date < GETDATE() THEN
                                  --     GETDATE()
                                  --ELSE process_date END, 
                                  @end_date = end_date, 
                                  @arc
hive_date = end_date + 1,
                                  @message_key = message_key, 
                                  @license_message_id = license_message_id, 
                                  @message_content_id = message_content_id, 
                                  @cart_discount_id = cart_discount_id,
                                  @message_type_id = 13,
                                  @license_message_value_str = 'message_campaign_id='+ CONVERT(VARCHAR(20),message_campaign_id)
                           FROM @new_campaigns
                           WHERE new_campaigns_id = @min_new_campaigns_id

                           IF @capability_expiration_date > GETDATE() - 90
                                  BEGIN
                                         EXEC usp_message_insert_license_message 
                                                @license_id,
                                                @message_type_id,
                                                @process_date,
                                                @end_date,
                                                @archive_date,
                                                @license_message_value_str,
                                                @license_message_id OUTPUT
                                  END 


                           SET @min_new_campaigns_id = @min_new_campaigns_id + 1

                     END 

              --Campaign in existing table not new     16 - journey exit

              SET @min_existing_campaigns_id = 0
              SET @max_existing_campaigns_id = 0

              SELECT @min_existing_campaigns_id = MIN(e.existing_campaigns_id),
                     @max_existing_campaigns_id = MAX(e.existing_campaigns_id)
              FROM @existing_campaigns e
              WHERE NOT EXISTS (SELECT message_campaign_id FROM  @new_campaigns n WHERE n.message_campaign_id = e.message_campaign_id)

              WHILE @min_existing_campaigns_id <= @max_existing_campaigns_id
                     BEGIN

                           SELECT @message_status_id_existing = message_status_id,
                                  @license_message_id_existing = license_message_id
                           FROM @existing_campaigns
                           WHERE existing_campaigns_id = @min_existing_campaigns_id

                           --NOT in a journey abandon the record
                           IF @message_status_id_existing = 1
                                  BEGIN
                                         UPDATE dbo.license_message
                                         SET message_status_id = 6,
                                                end_date = GETDATE(),
                                                last_modified_date = GETDATE(),
                                                archive_date = GETDATE() + 1
                                         WHERE license_message_id = @license_message_id_existing
                                  END    
              
                           --IN a journey - send exit journey record
                           IF @message_status_id_existing = 3
                                  BEGIN

                                         UPDATE dbo.license_message
                                         SET end_date = GETDATE(),
                                                last_modified_date = GETDATE(),
                                                archive_date = GETDATE() + 1
                                         WHERE license_message_id = @license_message_id_existing

                                         INSERT INTO dbo.license_message
                                                ( license_id ,
                                                       message_type_id ,
                                                       message_status_id ,
                                                  
     insert_date ,
                                                       process_date ,
                                                       end_date ,
                                                       archive_date,
                                                       message_campaign_id,
                                                       message_campaign_class_id
                                                )
                                         SELECT e.license_id,
                                                16 message_type_id, --exit journey
                                                1 message_status_id,
                                                GETDATE() insert_date,
                                                GETDATE() process_date,
                                                GETDATE() + 1 end_date,
                                                GETDATE() + 1 archive_date,
                                                e.message_campaign_id,
                                                e.message_campaign_class_id
                                         FROM @existing_campaigns e
                                         WHERE e.existing_campaigns_id = @min_existing_campaigns_id
                                  END    


                           SET @min_existing_campaigns_id = @min_existing_campaigns_id + 1

                     END 


              --campaign in both tables                       14 - journey update

              --Zero out the variables
              SET @min_existing_campaigns_id = 0
              SET @max_existing_campaigns_id = 0
              SET @message_status_id_existing = 0

              SELECT @min_existing_campaigns_id = MIN(e.existing_campaigns_id),
                     @max_existing_campaigns_id = MAX(e.existing_campaigns_id)
              FROM @existing_campaigns e
                     INNER JOIN @new_campaigns n
                           ON e.message_campaign_id = n.message_campaign_id

              WHILE @min_existing_campaigns_id <= @max_existing_campaigns_id
                     BEGIN
              
                           SELECT @message_campaign_id_existing = message_campaign_id, 
                                  @message_campaign_name_existing = message_campaign_name, 
                                  @message_campaign_description_existing = message_campaign_description, 
                                  @process_date_existing = process_date, 
                                  @end_date_existing = end_date, 
                                  @archive_date_existing = end_date + 1,
                                  @message_type_id_existing = 13,
                                  @license_message_value_str_existing = 'message_campaign_id='+ CONVERT(VARCHAR(20),message_campaign_id),
                                  @message_status_id_existing = message_status_id,
                                  @license_message_id_existing = license_message_id
                           FROM @existing_campaigns
                           WHERE existing_campaigns_id = @min_existing_campaigns_id


                           SELECT @message_source = message_source, 
                                  @message_campaign_id = message_campaign_id, 
                                  @message_campaign_name = message_campaign_name, 
                                  @message_campaign_description = message_campaign_description, 
                                  --@process_date = CASE WHEN process_date < GETDATE() THEN
                                  --     GETDATE()
                                  --ELSE process_date END,  
                                  @process_date = process_date,
                                  @end_date = end_date, 
                                  @archive_date = end_date + 1,
                                  @message_key = message_key, 
              
                    @license_message_id = license_message_id, 
                                  @message_content_id = message_content_id, 
                                  @cart_discount_id = cart_discount_id,
                                  @message_type_id = 13,
                                  @license_message_value_str = 'message_campaign_id='+ CONVERT(VARCHAR(20),message_campaign_id)
                           FROM @new_campaigns
                           WHERE message_campaign_id = @message_campaign_id_existing

                           IF @message_status_id_existing = 1
                                  BEGIN 
                                         IF @process_date_existing <> @process_date
                                                BEGIN
                                                       --Abandon record
                                                       UPDATE dbo.license_message
                                                       SET message_status_id = 6,
                                                              end_date = GETDATE(),
                                                              last_modified_date = GETDATE(),
                                                              archive_date = GETDATE() + 1
                                                       WHERE license_message_id = @license_message_id_existing

                                                       --Insert new record
                                                       IF @capability_expiration_date > GETDATE() - 90
                                                              BEGIN
                                                                     EXEC usp_message_insert_license_message 
                                                                           @license_id,
                                                                           @message_type_id,
                                                                           @process_date,
                                                                           @end_date,
                                                                           @archive_date,
                                                                            @license_message_value_str,
                                                                           @license_message_id OUTPUT
                                                              END 
                                                END                  
                                  END

                           IF @message_status_id_existing = 6
                                  BEGIN 
                                         IF @process_date_existing <> @process_date
                                                BEGIN
                                                       --Insert new record
                                                       IF @capability_expiration_date > GETDATE() - 90
                                                              BEGIN
                                                                     EXEC usp_message_insert_license_message 
                                                                           @license_id,
                                                                           @message_type_id,
                                                                           @process_date,
                                                                           @end_date,
                                                                           @archive_date,
                                                                            @license_message_value_str,
                                                                           @license_message_id OUTPUT
                                                              END 
                                                END        
          
                                  END

                           IF @message_status_id_existing = 3
                                  BEGIN 
                                         IF @process_date_existing <> @process_date
                                                BEGIN

                                                       --Abandon record
                                                       UPDATE dbo.license_message
                                                       SET end_date = GETDATE(),
                                                              last_modified_date = GETDATE(),
                                                              archive_date = GETDATE() + 1
                                                       WHERE license_message_id = @license_message_id_existing

                                                       --insert journey exit record
                                                       INSERT INTO dbo.license_message
                                                              (license_id ,
                                                                     message_type_id ,
                                                                     message_status_id ,
                                                                     insert_date ,
                                                                     process_date ,
                                                                     end_date ,
                                                                     archive_date,
                                                                     message_campaign_id,
                                                                     message_campaign_class_id
                                                              )
                                                       SELECT e.license_id,
                                                              16 message_type_id, --exit journey
                                                              1 message_status_id,
                                                              GETDATE() insert_date,
                                                              GETDATE() process_date,
                                                              GETDATE() + 1 end_date,
                                                              GETDATE() + 1 archive_date,
                                                              e.message_campaign_id,
                                                              e.message_campaign_class_id
                                                       FROM @existing_campaigns e
                                                       WHERE e.existing_campaigns_id = @min_existing_campaigns_id


                                                       IF @capability_expiration_date > GETDATE() - 90
                                                              BEGIN
                                                                     --Insert new record
                                                                     EXEC usp_message_insert_license_message 
                                                                           @license_id,
                                                                           @message_type_id,
                                                                           @process_date,
                                                                           @end_date,
                                                                           @archive_date,
                                                                            @license_message_value_str,
                                                                           @license_message_id OUTPUT
                                                              END
                                                END
    
                                     IF @process_date_existing = @process_date
                                                BEGIN
                                                       --insert journey update record - something on the license changed
                                                       IF @capability_expiration_date > GETDATE() - 90
                                                              BEGIN
                                                                     INSERT INTO dbo.license_message
                                                                           (license_id ,
                                                                                  message_type_id ,
                                                                                  message_status_id ,
                                                                                  insert_date ,
                                                                                  process_date ,
                                                                                  end_date ,
                                                                                  archive_date,
                                                                                  message_campaign_id,
                                                                                  message_campaign_class_id
                                                                           )
                                                                     SELECT e.license_id,
                                                                           14 message_type_id, 
                                                                           1 message_status_id,
                                                                           GETDATE() insert_date,
                                                                           GETDATE() process_date,
                                                                           GETDATE() + 1 end_date,
                                                                           GETDATE() + 1 archive_date,
                                                                           e.message_campaign_id,
                                                                            e.message_campaign_class_id
                                                                     FROM @existing_campaigns e
                                                                     WHERE e.existing_campaigns_id = @min_existing_campaigns_id
                                                              END 
                                         
                                                       --license is expired and needs to exit
                                                       IF @capability_expiration_date <= GETDATE() - 90
                                                              BEGIN
                                                                     INSERT INTO dbo.license_message
                                                                           (license_id ,
                                                                                  message_type_id ,
                                                                                  message_status_id ,
                                                                                  insert_date ,
                                                                                  process_date ,
                                                                                  end_date ,
                                                                                  archive_date,
                                                                                  message_campaign_id,
                                                                                  message_campaign_class_id
    
                                                                       )
                                                                     SELECT e.license_id,
                                                                           16 message_type_id, 
                                                                           1 message_status_id,
                                                                           GETDATE() insert_date,
                                                                           GETDATE() process_date,
                                                                           GETDATE() + 1 end_date,
                                                                           GETDATE() + 1 archive_date,
                                                                           e.message_campaign_id,
                                                                            e.message_campaign_class_id
                                                                     FROM @existing_campaigns e
                                                                     WHERE e.existing_campaigns_id = @min_existing_campaigns_id

                                                              END 
                                                END 
                                  END 

                           SET @min_existing_campaigns_id = @min_existing_campaigns_id + 1
                     END 

       END TRY

       BEGIN CATCH

              SET @response_code = -200
              SET @message = CASE WHEN @message is null THEN 'SELECT failed'
                                                else @message END

              DECLARE @DBName NVARCHAR(128)
              SET @DBName = DB_NAME()
              EXEC usp_LogError @ErrorDB = @DBName
              
       END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_opportunity_load]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_opportunity_load]

(
	@sfdc_opportunity_load_id int,
	@update_status_name varchar(20),
	@failure_description varchar(255) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2013-03-06	esmart		Check for update type
	2015-10-28	esmart		Check for null failure description
	2017-06-01	acoffel		sfdc_opp_update changes	
	2017-07-18	esmart		license_update_id
	2019-06-10	rvinoche	Check partner_license for partners and webroot direct
	2019-07-24	esmart		Suppress insert into sfdc_opportunity_update if order_external_load_exception exist

	DESCRIPTION
	Insert opportunity
*/

AS
	set nocount on				

	declare	@sfdc_template_id tinyint,
			@sfdc_update_type_id tinyint,
			@next_update_type_id tinyint,
			@partner_id int,
			@transaction_date datetime,
			@pending_approval bit,
			@opportunity_id varchar(18),
			@salesforce_trial_id varchar(18),
			@license_update_id varchar(18),
			@load_attempts tinyint,
			@order_header_id int,
			@order_external_load_exception_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------				
	
	-- 1.1) 
	select @sfdc_update_type_id = sfdc_update_type_id, @opportunity_id = opportunity_id, @salesforce_trial_id = salesforce_trial_id, @license_update_id = license_update_id, @sfdc_template_id = sfdc_template_id
	from sfdc_opportunity_load
	where sfdc_opportunity_load_id = @sfdc_opportunity_load_id

	select @transaction_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------				
	
	-- 2.1) processed
	if @update_status_name = 'Processed'
		begin

			-- 2.1.1) insert archive
			insert into sfdc_opportunity_load_archive(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, sfdc_update_status_id, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date, archive_date, license_update_id)
			select sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, sfdc_update_status_id=1, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date, @transaction_date, license_update_id
			from sfdc_opportunity_load
			where sfdc_opportunity_load_id = @sfdc_opportunity_load_id

			select @next_update_type_id = next_update_type_id
			from sfdc_template_update_type 
			where sfdc_update_type_id = @sfdc_update_type_id and sfdc_template_id = @sfdc_template_id
		
			--select sfdc_template_id = @sfdc_template_id, next_update_type_id = @next_update_type_id
			--return

			if @next_update_type_id is null
			-- 2.1.2) delete queue
				begin
					delete from sfdc_opportunity_load
					where sfdc_opportunity_load_id = @sfdc_opportunity_load_id
				end
			else
			-- 2.1.3) update queue
				begin
					update sfdc_opportunity_load
					set sfdc_update_type_id = @next_update_type_id, process_date = @transaction_date
					where sfdc_opportunity_load_id = @sfdc_opportunity_load_id
				end

			-- 2.1.4) set up next update table 
			dec
lare @next_update table (sfdc_opportunity_load_id int, opportunity_id varchar(18), salesforce_trial_id varchar(18), license_update_id varchar(18), sfdc_update_type_id tinyint, sfdc_update_type_name varchar(20))

			insert into @next_update(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_update_type_id, sfdc_update_type_name)
			select top 1 l.sfdc_opportunity_load_id, l.opportunity_id, l.salesforce_trial_id, license_update_id, t.sfdc_update_type_id, t.sfdc_update_type_name
			from sfdc_opportunity_load l
			inner join sfdc_update_type t
				on l.sfdc_update_type_id = t.sfdc_update_type_id
			where l.process_date <= @transaction_date and l.sfdc_opportunity_load_id = @sfdc_opportunity_load_id
			order by l.sfdc_opportunity_load_id

			-- 2.1.5) return results
			if (select count(*) from @next_update) = 0
				begin

				if @opportunity_id is not null
					begin
					select @sfdc_template_id = 4
					end
					
				-- 2.1.5.1) insert opportunity update
				select @order_header_id = order_header_id from order_opportunity where salesforce_opportunity_id = @opportunity_id
				
				-- 2.1.5.2) @partner_id
				select @partner_id = partner_id
				from partner_order
				where order_header_id = @order_header_id

				--if no partner_order record is found, we still want to check partner_license for a webroot direct partner record
				select @partner_id = isnull(@partner_id, 5559)


				select @sfdc_update_type_id = u.sfdc_update_type_id
				from sfdc_template_update_type u
				inner join (select sfdc_template_update_type_id = min(sfdc_template_update_type_id)
							from sfdc_template_update_type 
							where sfdc_template_id = @sfdc_template_id) t
					on  u.sfdc_template_update_type_id = t.sfdc_template_update_type_id

				-- 2.1.5.3) set pending flag
						select @pending_approval = case when pl.partner_license_status_id = 1 then 1 else 0 end
						from partner_license pl
						where pl.order_header_id = @order_header_id
						and pl.partner_id = @partner_id

				-- 2.1.5.4) @order_external_load_exception_id
				select @order_external_load_exception_id = e.order_external_load_exception_id
				from order_external_load_exception e
				where e.order_header_id = @order_header_id

				if @sfdc_update_type_id is not null and @salesforce_trial_id is null and @order_external_load_exception_id is null
					begin
						insert into sfdc_opportunity_update(order_header_id, sfdc_update_type_id, sfdc_update_status_id, process_date, sfdc_template_id)
						values(@order_header_id,@sfdc_update_type_id,case when @pending_approval = 1 then 4 else 0 end,dateadd(ss,5,getdate()),@sfdc_template_id)
					end

				-- 2.1.5.4) final result
				select sfdc_opportunity_load_id = @sfdc_opportunity_load_id, opportunity_id = @opportunity_id, salesforce_trial_id = @salesforce_trial_id, license_update_id = @license_update_id, sfdc_update_type_id=null, sfdc_update_type_name=null

				end
			else
				begin
				-- 2.1.5.4) next result
				select sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, license_update_id, sfdc_update_type_id, sfdc_update_type_name
				from @next_update
				end
			
		end

	-- 2.2) failed
	if @update_status_name = 'Failed'
		begin

		if @failure_description is null
			begin
			select @failure_description = 'Setup failure'
			end

		-- 2.2.1) insert failure
		insert into sfdc_opportunity_load_failure(sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, sfdc_update_status_id, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date, failure_description, failure_date, license_update_id)
		select sfdc_opportunity_load_id, opportunity_id, salesforce_trial_id, sfdc_update_status_id=2, sfdc_template_id, sfdc_update_type_id, insert_date, load_attempts, process_date, @failure_description, @transaction_date, license_update_id
		from sfdc_opportunity_load
		where sfdc_opportunity_load_id = @sfdc_o
pportunity_load_id
		
		select @load_attempts = load_attempts
		from sfdc_opportunity_load
		where sfdc_opportunity_load_id = @sfdc_opportunity_load_id

		if @load_attempts < 5
			-- 2.2.2) update queue
			begin
				update sfdc_opportunity_load
				set process_date = dateadd(hh,1,@transaction_date), load_attempts = load_attempts + 1
				where sfdc_opportunity_load_id = @sfdc_opportunity_load_id
			end
		else
			-- 2.2.3) delete queue
			begin
				delete from sfdc_opportunity_load
				where sfdc_opportunity_load_id = @sfdc_opportunity_load_id
			end

		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


	
	 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_opportunity_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_opportunity_update]

(
	@sfdc_opportunity_update_id int,
	@sfdc_response_code varchar(50),
	@sfdc_response_message varchar(500)

)
	
/*	
	DATE		AUTHOR		REMARKS
	2013-10-01	esmart		Initial creation.
	2013-11-07	esmart		add @sfdc_template_id
	2014-03-10	esmart		Add sfdc_template_id to archive and failure
	2014-04-15	esmart		Add fort_submit_id
	2016-04-15	esmart		Add license_id
	2016-09-07	esmart		Add support for next_sfdc_template_id
	2020-11-03	esmart		Add failure insert into order_external_load_exception

	DESCRIPTION
	update sfdc opportunity update
	
	
*/

AS
	set nocount on				

	declare	@sfdc_update_status_id tinyint,
			@update_attempts tinyint,
			@current_sfdc_update_status_id tinyint,
			@sfdc_update_type_id tinyint,
			@sfdc_template_id tinyint,
			@order_header_id int,
			@trial_id int,
			@form_submit_id int,
			@license_id int,
			@next_sfdc_template_id tinyint,
			@next_template_delay_seconds tinyint,
			@process_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get status
	select @sfdc_update_status_id = case when @sfdc_response_code = 'Success' then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_sfdc_update_status_id = sfdc_update_status_id,
			@sfdc_update_type_id = sfdc_update_type_id,
			@sfdc_template_id = sfdc_template_id,
			@order_header_id = order_header_id,
			@trial_id = trial_id,
			@form_submit_id = form_submit_id,
			@license_id = license_id
	from sfdc_opportunity_update
	where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

	if @current_sfdc_update_status_id in (1,3)
		begin
		select @response_code = -120, @message = 'No update on processed or abandoned updates'
		select response_code = @response_code, [message] = @message
		return
		end

	if @sfdc_response_message = 'Failed to update quote line (License: id value of incorrect type: true)'
		begin
		select @sfdc_update_status_id = 1, @sfdc_response_code = 'Success'
		end

	-- 1.3) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @sfdc_update_status_id = 2 -- failed
		begin
		select @sfdc_update_status_id = 3 -- abandoned
		end

	-- 1.4) @next_sfdc_template_id and @next_template_delay_seconds
	select @next_sfdc_template_id = next_sfdc_template_id, @next_template_delay_seconds = next_template_delay_seconds
	from sfdc_template 
	where sfdc_template_id = @sfdc_template_id


	--select sfdc_update_status_id = @sfdc_update_status_id, update_attempts = @update_attempts


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) Processed
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1)  Processed
	if @sfdc_update_status_id = 1
		begin
			-- 2.1) insert archive
			insert into sfdc_opportunity_update_archive(sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, sfdc_update_status_id, update_attempts, sfdc_response_code, sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id, license_id)
			select
 sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, @sfdc_update_status_id, @update_attempts, @sfdc_response_code, @sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id, license_id
			from sfdc_opportunity_update
			where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

			-- 2.2) get next @sfdc_update_type_id
			select @sfdc_update_type_id = next_update_type_id
			from sfdc_template_update_type 
			where sfdc_update_type_id = @sfdc_update_type_id and sfdc_template_id = @sfdc_template_id

			if @sfdc_response_message = 'Failed to update quote line (License: id value of incorrect type: true)'
				begin
				select @sfdc_update_type_id = 115
				end

			--select sfdc_update_type_id = @sfdc_update_type_id, sfdc_template_id = @sfdc_template_id

			-- 2.3) update sfdc_opportunity_update
			if @sfdc_update_type_id is not null
				begin 
				-- 2.3) update
				update sfdc_opportunity_update 
				set sfdc_update_type_id = @sfdc_update_type_id,
					update_attempts = 0,
					sfdc_update_status_id = 0,
					sfdc_response_code = '',
					sfdc_response_message = '',
					modified_date = getdate()
				where sfdc_opportunity_update_id = @sfdc_opportunity_update_id
				end
			else
				begin
				-- 2.4) delete
				delete from sfdc_opportunity_update
				where sfdc_opportunity_update_id = @sfdc_opportunity_update_id
				end

			select @response_code = 0, @message = 'Update processed'
		
			-- 2.1.4) set up next update table 
			declare @next_update table (sfdc_opportunity_update_id int, order_header_id int, trial_id int, form_submit_id int, license_id int, sfdc_update_type_id tinyint, sfdc_update_type_name varchar(20), process_date datetime, salesforce_lead_id varchar(18))

			insert into @next_update(sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, license_id, sfdc_update_type_id, sfdc_update_type_name,process_date,salesforce_lead_id)
			select top 1 l.sfdc_opportunity_update_id, l.order_header_id, l.trial_id, l.form_submit_id, l.license_id, t.sfdc_update_type_id, t.sfdc_update_type_name,l.process_date,o.salesforce_lead_id
			from sfdc_opportunity_update l
			inner join sfdc_update_type t
				on l.sfdc_update_type_id = t.sfdc_update_type_id
			left join sfdc_lead_order o
				on l.order_header_id = o.order_header_id
			where l.sfdc_opportunity_update_id = @sfdc_opportunity_update_id
			order by l.sfdc_opportunity_update_id

			-- 2.1.5) return results
			if (select count(*) from @next_update) = 0
				begin

				-- 2.1.5.1) insert next template
				if @next_sfdc_template_id is not null
					begin

					-- 2.1.5.1.1) get first update for next template
					select @sfdc_update_type_id = sfdc_update_type_id
					from sfdc_template_update_type
					where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
														from sfdc_template_update_type
														where sfdc_template_id = @next_sfdc_template_id)
					-- 2.1.5.1.2) calculate process_date
					select @process_date = dateadd(ss,@next_template_delay_seconds,getdate())

					-- 2.1.5.1.3) insert sfdc_opportunity_update
					insert into sfdc_opportunity_update (order_header_id, trial_id, sfdc_template_id, sfdc_update_type_id, process_date, form_submit_id, license_id)
					values(@order_header_id,@trial_id,@next_sfdc_template_id,@sfdc_update_type_id,@process_date,@form_submit_id,@license_id)
					
					end

				-- 2.1.5.2) final result
				select sfdc_opportunity_update_id = @sfdc_opportunity_update_id, order_header_id = @order_header_id, trial_id = @trial_id, form_submit_id = @form_submit_id, license_id = @license_id, sfdc_update_type_id=null, sfdc_update_type_name=null, process_date=null, salesforce_lead_id=null

				end
			else
				begin
				-- 2.1.5.3) next result
				select sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, license_id, sfdc_update_type_id, sfdc_update_type_name, process_date, salesforce_lead_id
				from @next_update
				end
		
		e
nd

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Failure
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	if @sfdc_update_status_id in (2,3)
		begin
			-- 3.1) log failure
			insert into sfdc_opportunity_update_failure(sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, sfdc_update_status_id, update_attempts, sfdc_response_code, sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id,license_id)
			select sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, @sfdc_update_status_id, @update_attempts, @sfdc_response_code, @sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id, license_id
			from sfdc_opportunity_update
			where sfdc_opportunity_update_id = @sfdc_opportunity_update_id
	
			-- 3.2) update queue
			update sfdc_opportunity_update 
			set sfdc_update_status_id = @sfdc_update_status_id,
				update_attempts = @update_attempts,
				sfdc_response_code = @sfdc_response_code,
				sfdc_response_message = @sfdc_response_message,
				modified_date = getdate(),
				process_date =   dateadd(mi,5,process_date)
			where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

			-- 3.3) archive when exceed max update attempts
			if @sfdc_update_status_id = 3 and @update_attempts = 5
				begin
				
				-- 3.3.1) sfdc_opportunity_update_archive
				insert into sfdc_opportunity_update_archive(sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, sfdc_update_status_id, update_attempts, sfdc_response_code, sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id, license_id)
				select sfdc_opportunity_update_id, order_header_id, trial_id, form_submit_id, sfdc_update_type_id, @sfdc_update_status_id, @update_attempts, @sfdc_response_code, @sfdc_response_message, insert_date, process_date, modified_date,sfdc_template_id, license_id
				from sfdc_opportunity_update
				where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

				-- 3.3.2) log exception for contract create failures
				insert into order_external_load_exception (order_header_id, exception_status, exception_json, insert_date)
				select u.order_header_id, 'pending', (select u.sfdc_template_id, u.sfdc_update_type_id, @sfdc_response_message as sfdc_response_message for json path, without_array_wrapper) as exception_json, getdate()
				from sfdc_opportunity_update u
				left join order_external_load_exception e
					on u.order_header_id = e.order_header_id and e.exception_status = 'pending'
				where u.sfdc_opportunity_update_id = @sfdc_opportunity_update_id and u.sfdc_template_id in (4,17) and e.order_external_load_exception_id is null

				-- 3.3.3) delete
				delete from sfdc_opportunity_update
				where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

				end
			select @response_code = -220, @message = 'Update failed'
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;








GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_opportunity_update_json]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_opportunity_update_json]

(
	@sfdc_opportunity_update_id int,
	@sfdc_update_json varchar(max)

)

AS


/*	
	DATE			AUTHOR		REMARKS
	2018-06-12		acoffel		Initial creation.
		

	DESCRIPTION
	update @marketing_activity_id
	
*/

	set nocount on

	set nocount on				
	begin try

	declare @response_code int,
			@message varchar(100)

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	update sfdc_opportunity_update_json
	set sfdc_update_json = @sfdc_update_json
	where sfdc_opportunity_update_id = @sfdc_opportunity_update_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_order_company]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_order_company]

(
	@cart_order_id int, 
	@order_header_id int
	
)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-06	esmart		Initial creation.
	2016-07-01	esmart		Move sfdc_opportunity_update to finalize
	2016-11-07	esmart		order_company.customer_id support
	2018-10-04	esmart		add company_type_id
	2019-08-01	abelenkiy	Added logic to prevent duplicate inserts to order_company (sect 2.3)
	2020-06-16	jnavarra	Modify for new company_name

	DESCRIPTION
	update customer.salesforce_contact_id
*/

AS
	set nocount on				

	declare @site_id varchar(20),
			@sfdc_template_id varchar(20), 
			@sfdc_update_type_id int,
			@partner_id int, 
			@partner_type_id int,
			@partner_account_id int, 
			@partner_company_id int,  
			@partner_customer_id int,
			@ship_to_customer_id int, 
			@ship_to_company_id int, 
			@ship_to_company_name nvarchar(255), 
			@ship_to_company_type_id tinyint, 
			@bill_to_customer_id int, 
			@bill_to_company_id int, 
			@bill_to_company_name nvarchar(255),
			@bill_to_company_type_id tinyint, 
			@reseller_customer_id int,
			@reseller_company_id int,
			@reseller_company_name nvarchar(255),
			@reseller_to_company_type_id tinyint, 
			@license_attribute_id int,
			@response_code int,
			@message varchar(100)

	declare @order_company_insert table (order_header_id int, company_id int, order_company_type_id tinyint, customer_id int)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.0) @site_id
	select @site_id = site_id 
	from order_header
	where order_header_id = @order_header_id

	-- 1.1) cart_order_partner
	select @partner_id = partner_id, @partner_account_id = partner_account_id
	from cart_order_partner
	where cart_order_id = @cart_order_id

	-- 1.2) partner company
	select @partner_company_id = c.company_id, @partner_type_id = p.partner_type_id, @partner_customer_id = pc.customer_id
	from partner p
	inner join company c
		on p.salesforce_id = c.salesforce_account_id
	left join partner_customer pc
		on pc.partner_id = p.partner_id
	where p.partner_id = @partner_id
	
	-- 1.3) bill to company
	select @bill_to_company_id = cc.company_id, @bill_to_company_name = company_name, @bill_to_customer_id = co.customer_id, @bill_to_company_type_id = cc.company_type_id
	from customer_order co
	left join customer_company cc
		on co.customer_id = cc.customer_id
	where order_header_id = @order_header_id and co.customer_type_id = 1
	
	-- 1.4) ship to company
	select @ship_to_company_id = cc.company_id, @ship_to_company_name = company_name, @ship_to_customer_id = co.customer_id, @ship_to_company_type_id = cc.company_type_id
	from customer_order co
	left join customer_company cc
		on co.customer_id = cc.customer_id
	where order_header_id = @order_header_id and co.customer_type_id = 2

	-- 1.5) @reseller_company_id
	if @site_id = 'PARTNERSERVICE'
		begin
			select @reseller_customer_id = cc.customer_id, @reseller_company_id = cc.company_id, @reseller_company_name = cc.company_name, @reseller_to_company_type_id = cc.company_type_id
			from partner_service_order o
			inner join partner_service_order_customer p
				on o.partner_service_order_id = p.partner_service_order_id 
			left join customer_company cc
				on p.customer_id = cc.customer_id
			where o.order_header_id = @order_header_id and order_company_type_id =
 3
		end
	else
		begin
		select @reseller_customer_id = cc.customer_id, @reseller_company_id = cc.company_id, @reseller_company_name = cc.company_name, @reseller_to_company_type_id = cc.company_type_id
		from customer_order co
		left join customer_company cc
			on co.customer_id = cc.customer_id
		where order_header_id = @order_header_id and co.customer_type_id = 3
		end

	--select partner_company_id = @partner_company_id, 
	--	partner_type_id = @partner_type_id, 
	--	partner_id = @partner_id, 
	--	bill_to_customer_id = @bill_to_customer_id, 
	--	ship_to_customer_id = @ship_to_customer_id,
	--	ship_to_company_id = @ship_to_company_id,
	--	ship_to_company_name = @ship_to_company_name,
	--	reseller_company_id = @reseller_company_id,
	--	reseller_company_name = @reseller_company_name

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) check for new ship to company
	if @ship_to_company_id is null
		begin
			select @ship_to_company_id = company_id
			from company
			where company_name = @ship_to_company_name

			-- 2.1.1) if company does not exist insert and update
			if @ship_to_company_id is null and @ship_to_company_name is not null
				begin
					insert into company(company_name,company_type_id)
					values(@ship_to_company_name,@ship_to_company_type_id)

					select @ship_to_company_id = SCOPE_IDENTITY()

                    exec dbo.usp_company_insert_company_name @company_id = @ship_to_company_id, @company_name = @ship_to_company_name, @company_name_type = 'Primary'

					update customer_company
					set company_id = @ship_to_company_id
					where customer_id = @ship_to_customer_id
				end
			else 
				begin
					update customer_company
					set company_id = @ship_to_company_id
					where customer_id = @ship_to_customer_id
				end
		end

	-- 2.1) check for new ship to company
	if @reseller_company_id is null
		begin
			select @reseller_company_id = company_id
			from company
			where company_name = @reseller_company_name

			-- 2.1.1) if company does not exist insert and update
			if @reseller_company_id is null and @reseller_company_name is not null
				begin
					insert into company(company_name,company_type_id)
					values(@reseller_company_name,@reseller_to_company_type_id)

					select @reseller_company_id = SCOPE_IDENTITY()

                    exec dbo.usp_company_insert_company_name @company_id = @reseller_company_id, @company_name = @reseller_company_name, @company_name_type = 'Primary'

					update customer_company
					set company_id = @reseller_company_id
					where customer_id = @reseller_customer_id
				end
			else 
				begin
					update customer_company
					set company_id = @reseller_company_id
					where customer_id = @reseller_customer_id
				end
		end

	-- print '@ship_to_company_id=' + convert(varchar(20),@ship_to_company_id)

	-- 2.3.1) account
	if @ship_to_company_id is null
		begin
			--print '2.3.1.1'
			insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
			values(@order_header_id,@partner_company_id,1,@partner_customer_id)
		end
	else
		begin
			--print '2.3.1.2'
			insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
			values(@order_header_id,@ship_to_company_id,1,@ship_to_customer_id)
		end

	-- print '@bill_to_company_id=' + convert(varchar(20),@bill_to_company_id)

	-- 2.3.2) bill_to_account
	if @bill_to_company_id is null
		begin
			--print '2.3.2.1'
				insert into @order_company_insert(order_header_id,company_id,order_company_type_id,c
ustomer_id)
				values(@order_header_id,@partner_company_id,2,@partner_customer_id)
		end
	else
		begin
			--print '2.3.2.2'
			insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
			values(@order_header_id,@bill_to_company_id,2,@bill_to_customer_id)
		end


	
	-- 2.3.3) reseller_partner_account
	if @partner_type_id = 1 and @reseller_company_id is not null
		begin
		--print '2.3.3.1'
			insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
			values(@order_header_id,@reseller_company_id,3,@reseller_customer_id)
		end
	if @partner_type_id <> 1 and @reseller_company_id <> @partner_company_id and @partner_company_id is not null
		begin
		--print '2.3.3.2'
			insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
			values(@order_header_id,@partner_company_id,3,@partner_customer_id)
		end

	-- 2.3.4) distributor_account
	if @partner_type_id = 1
		begin
		--print '2.3.4'
		insert into @order_company_insert(order_header_id,company_id,order_company_type_id,customer_id)
		values(@order_header_id,@partner_company_id,4,@partner_customer_id)
		end

	-- 2.3.5) insert to order_company
	insert into order_company (order_header_id, company_id, order_company_type_id, customer_id)
	select distinct i.order_header_id, i.company_id, i.order_company_type_id, i.customer_id
	from @order_company_insert i
	left join order_company oc
		on i.order_header_id = oc.order_header_id and i.company_id = oc.company_id and i.order_company_type_id = oc.order_company_type_id and i.customer_id = oc.customer_id
	where oc.order_company_id is null
	order by i.order_company_type_id

	-- 2.4) partner_order
	if @partner_account_id is not null
		begin
			insert into partner_order(partner_id,order_header_id,partner_account_id)
			values(@partner_id,@order_header_id,@partner_account_id)
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sfdc_update_order_opportunity]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sfdc_update_order_opportunity]

(
	@order_header_id int,
	@salesforce_opportunity_id varchar(20)
	
)

/*	
	DATE		AUTHOR		REMARKS
	2013-08-06	esmart		Initial creation.
	2023-10-12	vsingh8		Created audit record for order_opportunity.

	DESCRIPTION
	update order_opportunity
*/

AS
	set nocount on				

	declare	@order_opportunity_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @order_opportunity_id
	select @order_opportunity_id = order_opportunity_id from order_opportunity where order_header_id = @order_header_id


	if @order_opportunity_id is null
		begin
		insert into order_opportunity(order_header_id,salesforce_opportunity_id) values(@order_header_id,@salesforce_opportunity_id)
		end
	else 
		begin
		-- Create audit record for order_opportunity
		INSERT INTO order_opportunity_audit(order_opportunity_id,order_header_id,salesforce_opportunity_id,
			oracle_contract_number,insert_date,insert_by,modified_date,modified_by)
		SELECT order_opportunity_id,order_header_id,salesforce_opportunity_id,
			oracle_contract_number,insert_date,insert_by,modified_date,modified_by
		FROM order_opportunity
		WHERE order_header_id = @order_header_id

		UPDATE order_opportunity 
		SET salesforce_opportunity_id = @salesforce_opportunity_id,
			modified_by = SUSER_SNAME(),
			modified_date = GETDATE()
		WHERE order_header_id = @order_header_id
		end
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
