-- =============================================================================
-- PROCEDURE: [dbo].[usp_ship_cd_insert_without_order]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_ship_cd_insert_without_order]
 
(
		@keycode varchar(40)
)

/*	
	DATE		AUTHOR		REMARKS
	2014-10-06	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@product_id int,
			@license_category_id int,
			@customer_id int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  get license info
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select distinct  @license_category_id = lc.license_category_id,
			@customer_id = a.customer_id
	from license l
	inner join license_category_license lc
		on l.license_id = lc.license_id
	left join customer_address a
		on l.customer_id = a.customer_id and a.address_type_id in (1,2)
	where l.keycode = @keycode

	
	if @customer_id is NULL	 
		begin
			select 'keycode does not have an address record'
			return
		end

	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  set product_id according to license category
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @license_category_id not in (1,2,3,4,100,110,115,120)
		begin 
			select 'no cd available for that license category'
			return
		end


	if @license_category_id in (1,2,3,4,100,110,115,120)
		begin
			select @product_id = case when @license_category_id in (1,2,100) then 18100000
										when @license_category_id in (3,110) then 18110000 
										when @license_category_id = (115) then 18115000
										when @license_category_id in (4,120) then 18120000 else 18100000 end
		end 
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) insert record into ship_cd_without_order
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------


	insert into ship_cd_without_order (customer_id, product_id, insert_date)
	select @customer_id, @product_id, getdate()


	select 'cd insert complete for customer'


	end try

	begin catch

		set @message = case when @message is null then 'cd insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
GO
