create procedure [dbo].[usp_sky_account_admin_select]

/*	
	DATE		AUTHOR		REMARKS
	2019-09-05	abelenkiy	Initial creation

	DESCRIPTION
	Selects sky_account_id by email for billing portal review in admin portal.
*/

(@customer_email varchar(100))
as
set nocount on;

	begin try

		select
			sa.sky_account_id
		  , sa.uber_id
		  , sa.customer_email
		  , sa.insert_date
		from	sky_account sa
		where	sa.customer_email = @customer_email;

	end try
	begin catch

		declare @dbname nvarchar(128);
