GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_customer_match_audit]
-- =============================================================================

CREATE procedure [dbo].[usp_sky_account_customer_match_audit]
/*	
	DATE		AUTHOR		REMARKS
	2019-10-01	abelenkiy	Initial creation.

	DESCRIPTION
	Creates and sends report of customer_id mismatches between sky_account_customer and customer_company.
*/
as
	begin try
		-- 1) check if in-scope records exists; return out if no records
		if not exists (select 1
					   from dbo.sky_account_customer sac
						   left join dbo.customer_company cc on cc.customer_id = sac.customer_id
					   where sac.company_id != cc.company_id)
			return;

		-- 2) decare vars for send_dbmail and stage data
		declare @subject nvarchar(255) = convert(varchar(50), getdate(), 23) + N' - Mismatches of customer_id between sky_account_customer and customer_company'
			  , @body	 nvarchar(max) = N'<html><body>
											<table cellspacing = 20>
											<th colspan=10 align="left" bgcolor="#36cf1f">Mismatches of customer_id between sky_account_customer and customer_company</th>
											<tr>
												<th align="left">sky_account_id</th>
												<th align="left">sky_account_customer_id</th>
												<th align="left">customer_id</th>
												<th align="left">sac_company_id</th>
												<th align="left">cc_company_id</th>
												<th align="left">sac_insert_date</th>
											</tr>'
			  , @xml	 nvarchar(max) = cast((select sac.sky_account_id as 'td', ' '
													, sac.sky_account_customer_id as 'td', ' '
													, sac.customer_id as 'td', ' '
													, sac.company_id as 'td', ' '
													, cc.company_id as 'td', ' '
													, cast(sac.insert_date as date) as 'td'
											   from dbo.sky_account_customer sac
												   left join dbo.customer_company cc on cc.customer_id = sac.customer_id
											   where sac.company_id != cc.company_id
											   order by sac.insert_date desc
											  for xml path('tr'), elements) as nvarchar(max));

		-- 2.1) concat body of email from values above
		set @body = @body + isnull(@xml, '') + N'</table></body></html>';

		-- 3) execute send_dbmail
		exec msdb..sp_send_dbmail @recipients = 'abelenkiy@webroot.com'
								--@copy_recipients = 'kmasand@webroot.com; abelenkiy@webroot.com',
								, @subject = @subject
								, @body_format = 'HTML'
								, @body = @body;
	end try
	begin catch
		declare @DBName nvarchar(128);
		set @DBName = db_name();
		exec usp_LogError @ErrorDB = @DBName;
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_disable_company]
-- =============================================================================

create procedure [dbo].[usp_sky_account_disable_company]

/*	
	DATE		AUTHOR		REMARKS
	2019-08-21	abelenkiy	Initial creation

	DESCRIPTION
	Inserts disabled_date to active sky_account_company_verify_key
*/

(
	@sky_account_customer_id int
)
as
set nocount on;

	begin try

		update	sacc
		set sacc.disabled_date = getdate()
		from	sky_account_customer_company_verify sacc
			cross apply fn_sky_account_company_verify_status(sacc.sky_account_customer_id) fn
		where	sacc.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id
				and sacc.sky_account_customer_id = @sky_account_customer_id
				and sacc.disabled_date is null

		select @@rowcount as disable_success_status


	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_insert_account]
-- =============================================================================
CREATE procedure [dbo].[usp_sky_account_insert_account]

/*	
	DATE		AUTHOR		REMARKS
	2019-06-19	abelenkiy	Initial creation

	DESCRIPTION
	Inserts and/or selects sky_account_id to be stored in session for billing portal on each log in.
*/

(
	@uber_id int
  , @customer_email varchar(100)
  , @sky_json nvarchar(max) = null
)
as
set nocount on;

	begin try

		declare
		    @sky_account_json_id int
		  , @sky_account_id		 int;

		--1.1 insert to sky account json and select pk
		if @sky_json is not null
			begin
				insert into sky_account_json	(sky_account_json)
				select	@sky_json;

				select	@sky_account_json_id = scope_identity();
			end;
		--1.2 insert and/or select sky_account_id
		if not exists (select 1	  from sky_account sa  where sa.uber_id = @uber_id)
			begin
				insert into sky_account
				(	uber_id
				  , customer_email
				  , sky_account_json_id)
				values
				(@uber_id, @customer_email, @sky_account_json_id);

				select	@sky_account_id = scope_identity();
			end;
		else
			begin
				select	@sky_account_id = sa.sky_account_id
				from	sky_account sa
				where	sa.uber_id = @uber_id;
			end;

		--1.3 update sky account json table with sky account pk
		update	sky_account_json
		set sky_account_id = @sky_account_id
		where	sky_account_json_id = @sky_account_json_id;

		--1.4 select sky account id
		select	@sky_account_id as sky_account_id;

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;







GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_insert_company]
-- =============================================================================

CREATE procedure [dbo].[usp_sky_account_insert_company]

/*	
	DATE		AUTHOR		REMARKS
	2019-06-19	abelenkiy	Initial creation
	2019-07-29	abelenkiy	Added @company_id to values passed to usp_customer_insert_customer_service_NEW
	2019-08-22	abelenkiy	Added logic to prevent associating companies with multiple account numbers in section 1.3.0
	2019-09-19	abelenky	Bug fix to limit new verify key insert to only passed-in or newly-created company
	2019-10-11	abelenkiy	Added logic to prevent associating companies that don't exist in Oracle data in section 1.3.0.1
	2020-12-18	abelenkiy	Update to have JSON passed in instead of variables. Update to use sap_customer_number instead 
							of company_id as part of Oracle to SAP integration.
	2021-05-24	abelenkiy	Refactor to use SAP data instead of Oracle

	DESCRIPTION
	Inserts new sky_account_customer record and verification key during billing portal registration 
	flow or just creates new verification key if sky_account_customer record already exists. Can be 
	optionally called with explicit sky_account_customer_id (for email resend)
*/

(
	@sky_account_id int
  , @sap_account_number int
  , @sky_json nvarchar(max)
  , @sky_account_customer_id int = null
)
as
set nocount on;

begin try

	declare
		@sky_account_customer_json_id int
		, @customer_id int
		, @company_id int
		, @first_name varchar(40)
		, @last_name varchar(40)
		, @customer_email varchar(100)
		, @customer_json nvarchar(2000)

	--1.1 insert to sky account json and select pk
	insert into sky_account_customer_json (sky_account_customer_json)
	values (@sky_json);

	select @sky_account_customer_json_id = scope_identity();

	--1.2 check if sky_account_customer_id passed in and attempt to select existing sky_account_customer_id if not
	if @sky_account_customer_id is null
		begin
			select @sky_account_customer_id = sac.sky_account_customer_id
			from sky_account_customer sac
			where sac.sky_account_id = @sky_account_id
				and sac.sap_account_number = @sap_account_number;
		end

	--1.3 begin insert if no sky_account_customer_id found
	if @sky_account_customer_id is null
		begin
			--1.3.0 make sure sap_account_number exists in ecom data
			select @company_id = sa.company_id
			from sap_account sa
			where sa.sap_account_number = @sap_account_number

			if @company_id is null
			begin
				return
			end

			--1.3.1 parse out and select variables
			select
				@first_name = first_name
			  , @last_name = last_name
			  , @customer_email = customer_email
			from openjson(@sky_json)
				with(first_name varchar(255) '$.first_name'
				  , last_name varchar(255) '$.last_name'
				  , customer_email varchar(100) '$.customer_email');

			select @customer_json = (select
				@customer_email [customer.customer_email]
			  , @first_name [customer.first_name]
			  , @last_name [customer.last_name]
			  , @company_id [company.company_id]
			  , @sap_account_number [company.sap_account_number]
			for json path, without_array_wrapper)
			
			--1.3.2 select customer id
			exec usp_customer_insert_customer_service
				@input_json = @customer_json
				, @customer_id = @customer_id output;

			--1.3.3 insert sky account customer
			insert into sky_account_customer (sky_account_id, customer_id, company_id
				, sap_account_number, sky_account_customer_json_id)
			values (@sky_account_id, @customer_id, @company_id, @sap_account_number
				, @sky_account_customer_json_id);

			--1.3.4 select new sky_account_customer_id
			select	@sky_account_customer_id = scope_identity();

		end;

	--1.4 update fk in json table
	update	sky_account_customer_json
	set sky_account_customer_id = @sky_account_customer_id
	where	sky_account_customer_json_id =
 @sky_account_customer_json_id;

	--1.5 insert verify key
	insert into sky_account_customer_company_verify
	(
		sky_account_customer_id
	)
	select	sac.sky_account_customer_id
	from	sky_account_customer sac
		outer apply fn_sky_account_company_verify_status(sac.sky_account_customer_id) fn
	where	fn.verified_date is null
		and fn.disabled_date is null
		and sac.sky_account_customer_id = @sky_account_customer_id;

	--1.6 select complete record with verify key
	exec usp_sky_account_select_company
		@sky_account_id = @sky_account_id
		, @sky_account_customer_id = @sky_account_customer_id;

end try
begin catch

	declare @dbname nvarchar(128);
	set @dbname = db_name();
	exec usp_LogError @ErrorDB = @dbname;

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_select_all_customers]
-- =============================================================================
CREATE procedure [dbo].[usp_sky_account_select_all_customers]

/*	
	DATE		AUTHOR		REMARKS
	2021-01-15	abelenkiy	Initial creation
	2023-03-27	abelenkiy	ECOM-1067 - Added order by sap_account_number asc per request from SAP

	DESCRIPTION
	Called by SAP over link server as the beginning of the process that will generate files for 
	Billing Portal. 

	If we decide in the future to include all customers instead of just those that have signed up for 
	Billing Portal, the query can be modified to select from the sap_account table instead of 
	sky_account_customer. This will solve the problem of the customer having to wait up to 24 hours
	to see data in Billing Portal after signing up BUT the amount of data would increase significantly.

*/

as
set nocount on;

	begin try

		select distinct sac.sap_account_number
		from sky_account_customer sac
		where sac.sap_account_number is not null
		order by sac.sap_account_number asc

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_select_company]
-- =============================================================================

CREATE procedure [dbo].[usp_sky_account_select_company]

/*	
	DATE		AUTHOR		REMARKS
	2019-06-19	abelenkiy	Initial creation
	2019-07-10	abelenkiy	Joined oracle_ext_customer_summary to add oracle company name to output
	2019-07-24	abelenkiy	Changed oracle_ext_customer_summary from inner to left join and added join to company to get company name if null in Oracle data
	2019-08-21	abelenkiy	Added disabled_date to output
	2019-09-16	abelenkiy	Changed verify_status function from cross to outer apply so companies are always listed even if token is expired
	2019-09-26	abelenkiy	Added order by party_name
	2019-10-30	abelenkiy	Added nullable @sky_account_customer_key param and made @sky_account_id nullable
	2019-12-02	abelenkiy	Added customer_id to output
	2020-03-10	abelenkiy	Added left join to new oracle_ext_customer_merge_data table and added merge_date to output
	2021-05-24	abelenkiy	Revised to point to SAP data tables
	2022-03-11	abelenkiy	Added company_id to return; added better error handling

	DESCRIPTION
	Selects all companies (verified AND unverified) associated with sky_account_id or returns record for specific company if optional param passed in.
*/

(
	@sky_account_id int = null
  , @sky_account_customer_id int = null
  , @sky_account_customer_key varchar(40) = null
)
as
set nocount on;

begin try
	if coalesce(cast(@sky_account_id as varchar(40)), cast(@sky_account_customer_id as varchar(40))
		, @sky_account_customer_key) is not null--only go into query if at least one input is populated
		begin
			select distinct--distinct in case of multiple records for same company in sap_ext_I094_customer_summary
					sac.sky_account_customer_id
					, sac.customer_id
					, sac.sap_account_number
					, sa.company_id
					, isnull(seics.party_name, sa.sap_account_name) as party_name
					, cast(sac.sky_account_customer_key as varchar(40)) as sky_account_customer_key
					, cast(vs.sky_account_customer_company_verify_key as varchar(40)) as sky_account_customer_company_verify_key
					, vs.insert_date
					, vs.expiration_date
					, vs.verified_date
					, vs.disabled_date
					, iif(seics.sap_ext_I094_customer_summary_id is null, 0, 1) as has_invoice_data
			from sky_account_customer sac
				outer apply fn_sky_account_company_verify_status(sac.sky_account_customer_id) vs
				left join sap_ext_I094_customer_summary seics on seics.sap_account_number = sac.sap_account_number
				left join sap_account sa on sa.sap_account_number = sac.sap_account_number
			where sac.sky_account_id = isnull(@sky_account_id, sac.sky_account_id)
					and sac.sky_account_customer_id = isnull(@sky_account_customer_id, sac.sky_account_customer_id)
					and sac.sky_account_customer_key = isnull(@sky_account_customer_key, sac.sky_account_customer_key)
					and vs.disabled_date is null
			order by party_name;
		end

end try
begin catch

	declare
		@error_severity int = error_severity(), @error_state int = error_state(), @message nvarchar(4000)
	set @message = 'sky_account_id = ' + convert(varchar(20), isnull(@sky_account_id, 'null')) 
				+ ', sky_account_customer_id = ' + convert(varchar(20), isnull(@sky_account_customer_id, 'null'))
				+ ', sky_account_customer_key = ' + convert(varchar(20), isnull(@sky_account_customer_key, 'null'))
				+ ': ' + error_message()
	raiserror(@message, @error_severity, @error_state) with log

	insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage
		, ErrorServer, ErrorDB, ErrorUser)
	select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message
		, @@servername, db_name(), suser_name()

end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_select_verify_key]
-- =============================================================================
CREATE procedure [dbo].[usp_sky_account_select_verify_key]

/*	
	DATE		AUTHOR		REMARKS
	2019-07-17	abelenkiy	Initial creation
	2019-08-26	abelenkiy	Added first_name and last_name from customer table to output
	2019-09-05	abelenkiy	Added party_name from oracle_ext_customer_summary or company table to output
	2019-09-10	abelenkiy	Modified to return row even if key is unverifiable; valid verify key will show if available
	2020-03-11	abelenkiy	IAMROOT-927: Bug fix to null out verify key parameters but still return row if passed in verify key is invalid

	DESCRIPTION
	Selects data associated with verification key (for billing portal) to be called when user clicks verification email. 
*/

(@sky_account_customer_company_verify_key varchar(40))
as
set nocount on;

	begin try

		select	distinct--distinct in case of multiple records for same company in oracle_ext_customer_summary
			cv.sky_account_customer_company_verify_id
		  , sac.sky_account_id
		  , sac.sky_account_customer_id
		  , sa.customer_email
		  , cu.first_name
		  , cu.last_name
		  , isnull(oecs.party_name,co.company_name) as party_name
		  , cast(sac.sky_account_customer_key as varchar(40)) as sky_account_customer_key
		  , sac.company_id
		  , iif(cv.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id, cast(fn.sky_account_customer_company_verify_key as varchar(40)), null) as sky_account_customer_company_verify_key
		  , iif(cv.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id, fn.expiration_date, null) as expiration_date
		  , iif(cv.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id, fn.verified_date, null) as verified_date
		  --, cv.insert_date
		from	sky_account_customer_company_verify cv
			inner join sky_account_customer sac on sac.sky_account_customer_id = cv.sky_account_customer_id
			inner join sky_account sa on sa.sky_account_id = sac.sky_account_id
			inner join customer cu on cu.customer_id = sac.customer_id
			left join oracle_ext_customer_summary oecs on oecs.company_id = sac.company_id
			left join company co on co.company_id = sac.company_id
			outer apply fn_sky_account_company_verify_status(cv.sky_account_customer_id) fn
		where	cast(cv.sky_account_customer_company_verify_key as varchar(40)) = @sky_account_customer_company_verify_key
				--and cv.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id;

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;








GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_account_update_verify_key]
-- =============================================================================
CREATE procedure [dbo].[usp_sky_account_update_verify_key]

/*	
	DATE		AUTHOR		REMARKS
	2019-07-17	abelenkiy	Initial creation
	2019-07-19	abelenkiy	Added success flag if update occurs

	DESCRIPTION
	Inserts verified_date on sky_account_customer_company_verify_key (for billing portal). Fails (returns 0) if passed in key doesn't match most recent key generated or key is already verified.
*/

(@sky_account_customer_company_verify_key varchar(40))
as
set nocount on;

	begin try

		update	sacc
		set sacc.verified_date = getdate()
		from	sky_account_customer_company_verify sacc
			cross apply fn_sky_account_company_verify_status(sacc.sky_account_customer_id) fn
		where	sacc.sky_account_customer_company_verify_id = fn.sky_account_customer_company_verify_id
				and sacc.sky_account_customer_company_verify_key = @sky_account_customer_company_verify_key
				and sacc.verified_date is null

		select @@rowcount as verify_success_status

	end try
	begin catch

		declare @dbname nvarchar(128);
		set @dbname = db_name();
		exec usp_LogError @ErrorDB = @dbname;

	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_insert_update]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_sky_insert_update] (
	@license_id int,
	@sky_template_id tinyint,
	@process_date datetime = null,
	@reregister tinyint = NULL,
	@sky_update_json NVARCHAR(MAX) = NULL
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-02-10	esmart		Initial creation.	
		2015-06-05	esmart		Enable reregistration
		2024-05-09	gblandford	https://jira.opentext.com/browse/ECOM-4416 - extended sky_update insert to allow additional JSON block in request. This is to support 
								additional parameters that may be required by the API endpoint.


		DESCRIPTION
		insert sky_update record and any attached JSON

		DEPENDENCIES
		dbo.usp_cart_update_order_license
		dbo.usp_license_insert_child_license
		dbo.usp_license_insert_license_migration
		dbo.usp_license_service_insert_license
		dbo.usp_license_update_license_module_license
		dbo.usp_message_update_license_message_deprovision
		dbo.usp_trial_insert_trial
		dbo.usp_partner_update_partner_license_transaction

	*/

	SET NOCOUNT ON

	DECLARE	@sky_update_type_id TINYINT,
			@sky_update_archive_id INT,
			@sky_update_id INT,
			@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @process_date
	IF @process_date IS NULL
		BEGIN
		SELECT @process_date = GETDATE()
		end

	-- 1.2) @sky_update_type_id
	select @sky_update_type_id = s.sky_update_type_id
	from sky_template_update_type s
	inner join (select sky_template_update_type_id = min(sky_template_update_type_id)
				from sky_template_update_type
				where sky_template_id = @sky_template_id) t
			on s.sky_template_update_type_id = t.sky_template_update_type_id



	-- 1.3) 
	if @reregister = 1
		begin
			update sky_update_archive 
			set sky_update_status_id = 4 
			where license_id = @license_id and sky_update_type_id = @sky_update_type_id and sky_update_status_id = 1
		end

	-- 1.3) do not duplicate msp_registration for the same license
	if @sky_update_type_id = 1
		begin
		select @sky_update_archive_id = sky_update_archive_id
		from sky_update_archive 
		where license_id = @license_id and sky_update_type_id = @sky_update_type_id and sky_update_status_id = 1

		if @sky_update_archive_id is not null
			begin
			return
			end
		end

			
	-- 1.4) do not duplicate msp_registration for the same license
	if @sky_update_type_id = 1
		begin
		select @sky_update_id = sky_update_id
		from sky_update
		where license_id = @license_id and @sky_update_type_id = @sky_update_type_id

		if @sky_update_id is not null
			begin
			return
			end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert update
	insert into sky_update(license_id, sky_template_id, sky_update_type_id,process_date)
	values(@license_id, @sky_template_id, @sky_update_type_id,@process_date)

	
	-- 2.1) insert sky_update_json
	SELECT @sky_update_id = SCOPE_IDENTITY();

	IF ISNULL(@sky_update_json, '' ) > '' BEGIN

			INSERT INTO dbo.sky_update_json (
				sky_update_id,
				sky_update_json
			) VALUES (
				@sky_update_id,
				@sky_update_json
			)
		
		END



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
