-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_license_activity_read]
-- =============================================================================

-------------------------------------------------------------------------------
--  Description:
--    Reads the sky_license_activity data for a license_id.
--  Maintenance:
--    20150810 - mandersen - Created.
--    20150909 - mandersen - Added license_key column.
--    20150928 - mandersen - Added avg_scan_duration column.
--    20151002 - mandersen - Added license_activity_devices column.
--    20191016 - abelenkiy - IAMROOT-630 added logic to figure out product_line and dynamically return results
-------------------------------------------------------------------------------
--  Copyright © 2014-2015 Webroot Inc.
-------------------------------------------------------------------------------

CREATE procedure [dbo].[usp_sky_license_activity_read]
(@license_id int)
as
begin
    set nocount on;

    declare @product_line_id int;

	-- set product line from license table
    select @product_line_id = l.product_line_id
    from license l
    where l.license_id = @license_id;

	-- return consumer object if not business
    if @product_line_id != 300 -- business
    begin
        --select sky_license_activity row
        select sla.license_id,
               sla.keycode,
               sla.license_key,
               sla.distribution,
               sla.device_count,
               sla.device_pc,
               sla.device_mac,
               sla.device_mobile,
               sla.health_status,
               sla.osfirewall_enabled,
               sla.protection_enabled,
               sla.rootkitshield_enabled,
               sla.webthreatshield_enabled,
               sla.usbshield_enabled,
               sla.offlineshield_enabled,
               sla.firewall_enabled,
               sla.infrared_enabled,
               sla.idshield_enabled,
               sla.phishingshield_enabled,
               sla.sku,
               sla.total_garbage_removal_size,
               sla.last_scan_date,
               sla.last_scan_duration,
               sla.scan_count,
               sla.threats_removed,
               sla.threat_blocked,
               sla.latest_threat,
               sla.system_analyzer_score,
               sla.hardware_score,
               sla.software_score,
               sla.threats_score,
               sla.gamer_license,
               sla.bby_license,
               sla.weak_hosts,
               sla.avg_scan_duration,
               sla.license_activity_devices,
               sla.effective_date
        from dbo.sky_license_activity sla
        where sla.license_id = @license_id;
    end;
	-- return last_30_day_devices as device_count if business
    else
    begin
        select sla.license_id,
               sla.keycode,
               sla.license_key,
               sla.distribution,
               f.last_30_day_devices as device_count,
               sla.device_pc,
               sla.device_mac,
               sla.device_mobile,
               sla.health_status,
               sla.osfirewall_enabled,
               sla.protection_enabled,
               sla.rootkitshield_enabled,
               sla.webthreatshield_enabled,
               sla.usbshield_enabled,
               sla.offlineshield_enabled,
               sla.firewall_enabled,
               sla.infrared_enabled,
               sla.idshield_enabled,
               sla.phishingshield_enabled,
               sla.sku,
               sla.total_garbage_removal_size,
               sla.last_scan_date,
               sla.last_scan_duration,
               sla.scan_count,
               sla.threats_removed,
               sla.threat_blocked,
               sla.latest_threat,
               sla.system_analyzer_score,
               sla.hardwa
re_score,
               sla.software_score,
               sla.threats_score,
               sla.gamer_license,
               sla.bby_license,
               sla.weak_hosts,
               sla.avg_scan_duration,
               sla.license_activity_devices,
               sla.effective_date
        from dbo.sky_license_activity sla
            cross apply fn_license_select_license_activity(sla.license_id, getdate(), 'full', 'SAEP') f
        where sla.license_id = @license_id;
    end;
end;

GO
