-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_select_next_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sky_select_next_update]

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2019-07-09	acoffel		removed brtc exclusion
	2020-08-11	esmart		restrict return of sky_update_type = 4 update_license
	2023-04-13	abelenkiy	Temporarily restricted return of sky_update_type_id = 13 (CBEP_delete); removed unused code; added comments
	2024-05-24	gblandford	https://jira.opentext.com/browse/ECOM-4416 - extended to return sky_update_json if it has been attached to the request.
							- added schema and formatting
	2026-04-09	pachanta	Added Restriction of sky_update_type_id = 17;

	DESCRIPTION
	Returns next record in [sky_update] queue to PHP. 

	Note that sky_update_type = 4 (update_license) records are processed by 
	[usp_sky_select_next_update_bulk] and are explicitly excluded from this procedure.
	The relevant PHP code is found in [skyrise_update/bin/process-queue].
*/

AS
	SET NOCOUNT ON				

	BEGIN TRY

	SELECT TOP(1) s.sky_update_id, s.license_id, t.sky_update_type_id, t.sky_update_type_name, tp.sky_template_id, tp.sky_template_name, j.sky_update_json
	FROM dbo.sky_update s
		INNER JOIN dbo.sky_update_type t
			ON s.sky_update_type_id = t.sky_update_type_id
		INNER JOIN dbo.sky_template tp
			ON s.sky_template_id = tp.sky_template_id
		LEFT JOIN dbo.sky_update_json j 
			ON j.sky_update_id = s.sky_update_id
	WHERE s.process_date <= GETDATE() 
		AND s.sky_update_type_id <> 4 -- update_license
		AND s.sky_update_type_id <> 17 -- update_license_seat
		AND s.sky_update_type_id <> 13 -- CBEP_delete (exclusion is temporary)
	ORDER BY s.process_date, s.sky_update_id
				
	END TRY

	BEGIN CATCH

		DECLARE @DBName NVARCHAR(128)
		SET @DBName = DB_NAME()
		EXEC dbo.usp_LogError @ErrorDB = @DBName
		
	END CATCH;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_select_next_update_bulk]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sky_select_next_update_bulk]

(

	@sky_update_type_id tinyint,
	@batch_size int
)

/*	
	DATE		AUTHOR		REMARKS
	2018-02-01	esmart		Initial creation.
	2019-07-09	acoffel		brtc exclusion
	2022-03-15	abelenkiy	Removing records with bad profile values to prevent queue from 
							breaking (update_license); improved error handling

	DESCRIPTION
	Selects bulk records from sky_update to be processed by PHP.

	As of 2022-03-15, this is called in [skyrise_update/bin/process-queue] with hardcoded 
	sky_update_type = 4 and batch_size = 100. May be called from elsewhere in the PHP as well.
*/

AS
	set nocount on				

	begin try

	declare @sky_update_table table (sky_update_id int, license_id int, sky_update_type_id tinyint, 
		sky_update_type_name varchar(30), sky_template_id tinyint, sky_template_name varchar(50))

	if @batch_size is null select @batch_size = 100
	-----Change in batch size-----
	--select @batch_size = 200

	insert into @sky_update_table (sky_update_id, license_id, sky_update_type_id, sky_update_type_name, 
		sky_template_id, sky_template_name)
	select top (@batch_size) s.sky_update_id, s.license_id, t.sky_update_type_id, t.sky_update_type_name, 
		tp.sky_template_id, tp.sky_template_name
	from sky_update s
	inner join sky_update_type t
		on s.sky_update_type_id = t.sky_update_type_id
	inner join sky_template tp
		on s.sky_template_id = tp.sky_template_id
	where s.process_date <= getdate()
		and s.sky_update_type_id = case when @sky_update_type_id is null then s.sky_update_type_id else @sky_update_type_id end
        and tp.sky_template_name <> 'brtc_update'
	order by s.process_date, s.sky_update_id
				
	/*
	-- this section can be used to exclude update_license records that fail downstream in the PHP
	-- as a temporary solution while the PHP code is updated to handle those errors

	if @sky_update_type_id = 4 -- update_license
		begin
			delete @sky_update_table
			from @sky_update_table su
				cross apply fn_license_select_license_profile(su.license_id) lp
			where lp.license_category_name is null
				or lp.category_type_name is null
		end
	*/


	select sut.sky_update_id, sut.license_id, sut.sky_update_type_id, sut.sky_update_type_name, 
		sut.sky_template_id, sut.sky_template_name 
	from @sky_update_table sut

	end try

	begin catch

		declare
			@error_severity int = error_severity(), @error_state int = error_state(), @message nvarchar(4000)
		set @message = 'sky_update_type_id = ' + convert(varchar(20), isnull(@sky_update_type_id, 'null')) 
					+ ': ' + error_message()
		raiserror(@message, @error_severity, @error_state) with log

		insert into DBErrorlog (ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage
			, ErrorServer, ErrorDB, ErrorUser)
		select error_number(), error_severity(), error_state(), error_procedure(), error_line(), @message
			, @@servername, db_name(), suser_name()

	end catch;
    

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sky_select_sky_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sky_select_sky_update]

(
	@license_id INT = NULL,
	@keycode VARCHAR(40) = NULL,
	@sky_update_status_name VARCHAR(20) = NULL,
	@start_date DATETIME = NULL,
	@end_date DATETIME = NULL
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2014-05-22	esmart		Extend for searching
	2024-05-09	gblandford	https://jira.opentext.com/browse/ECOM-4416 - extended to return sky_update_json if it has been attached to the request.

	DESCRIPTION
	Select a sky_update and any related json

	Called directly from PHP when processing a single sky_update record

*/

AS
	SET NOCOUNT ON				

	DECLARE	@sky_update_status_id INT,
			@response_code INT,
			@message VARCHAR(100)

	BEGIN TRY

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) @license_id
		IF @license_id IS NULL AND @keycode IS NOT NULL
			BEGIN
			SELECT @license_id = license_id FROM license WHERE keycode = REPLACE(@keycode,'-','')
			END

		-- 1.2) @sky_update_status_id
		SELECT @sky_update_status_id = sky_update_status_id 
		FROM sky_update_status
		WHERE sky_update_status_name = @sky_update_status_name

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) insert
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		DECLARE @sky_update TABLE (sky_update_id INT, license_id INT, sky_template_id TINYINT, sky_update_type_id TINYINT, sky_update_status_id TINYINT, insert_date DATETIME, update_attempts TINYINT, process_date DATETIME, archive_date DATETIME, failure_description VARCHAR(255))

		-- 2.1) sky_update
		INSERT INTO @sky_update(sky_update_id, license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, process_date)
		SELECT u.sky_update_id, u.license_id, u.sky_template_id, u.sky_update_type_id, u.sky_update_status_id, u.insert_date, u.update_attempts, u.process_date
		FROM sky_update u
		WHERE u.sky_update_status_id = CASE WHEN @sky_update_status_id IS NULL THEN u.sky_update_status_id ELSE @sky_update_status_id END AND	
			(u.insert_date > @start_date OR @start_date IS NULL) AND
			(u.insert_date < @end_date OR @end_date IS NULL)

		-- 2.2) sky_update_archive
		INSERT INTO @sky_update(sky_update_id, license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, process_date, archive_date)
		SELECT u.sky_update_id, u.license_id, u.sky_template_id, u.sky_update_type_id, u.sky_update_status_id, u.insert_date, u.update_attempts, u.process_date, u.archive_date
		FROM sky_update_archive u
		WHERE u.sky_update_status_id = CASE WHEN @sky_update_status_id IS NULL THEN u.sky_update_status_id ELSE @sky_update_status_id END AND	
			(u.insert_date > @start_date OR @start_date IS NULL) AND
			(u.insert_date < @end_date OR @end_date IS NULL)

		-- 2.3) sky_update_failure
		INSERT INTO @sky_update(sky_update_id, license_id, sky_template_id, sky_update_type_id, sky_update_status_id, insert_date, update_attempts, process_date, archive_date, failure_description)
		SELECT u.sky_update_id, u.license_id, u.sky_template_id, u.sky_up
date_type_id, u.sky_update_status_id, u.insert_date, u.update_attempts, u.process_date, u.failure_date, u.failure_description
		FROM sky_update_failure u
		WHERE u.sky_update_status_id = CASE WHEN @sky_update_status_id IS NULL THEN u.sky_update_status_id ELSE @sky_update_status_id END AND	
			(u.insert_date > @start_date OR @start_date IS NULL) AND
			(u.insert_date < @end_date OR @end_date IS NULL)

		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 3.) results
		-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		SELECT u.sky_update_id,
			   u.license_id,
			   l.keycode,
			   u.sky_template_id,
			   st.sky_template_name,
			   u.sky_update_type_id,
			   t.sky_update_type_name,
			   u.sky_update_status_id,
			   s.sky_update_status_name,
			   u.insert_date,
			   u.update_attempts,
			   u.process_date,
			   u.archive_date,
			   u.failure_description,
			   j.sky_update_json
		FROM @sky_update u
			INNER JOIN dbo.license l
				ON u.license_id = l.license_id
			INNER JOIN dbo.sky_template st
				ON u.sky_template_id = st.sky_template_id
			INNER JOIN dbo.sky_update_type t
				ON u.sky_update_type_id = t.sky_update_type_id
			INNER JOIN dbo.sky_update_status s
				ON u.sky_update_status_id = s.sky_update_status_id
			LEFT JOIN dbo.sky_update_json j 
				ON j.sky_update_id = u.sky_update_id
		WHERE u.license_id = CASE
								 WHEN @license_id IS NULL THEN
									 u.license_id
								 ELSE
									 @license_id
							 END
		ORDER BY u.insert_date DESC;
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
