-- =============================================================================
CREATE PROCEDURE [dbo].[usp_sky_select_template_update_type]

(
	@sky_template_id tinyint = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.
		2020-06-10	cnovac		Updated sky_update_type_name datatype in table variable to match what it is in sky_update_type

		DESCRIPTION
		select template update type
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) create table
	declare @template_update_type table (step_id tinyint identity(1,1), sky_template_id tinyint, sky_template_name varchar(50), sky_update_type_id tinyint, sky_update_type_name varchar(30), next_update_type_id tinyint, next_update_type_name varchar(30))

	-- 1.2) insert rows
	insert into @template_update_type(sky_template_id, sky_template_name, sky_update_type_id, sky_update_type_name, next_update_type_id, next_update_type_name)
	select t.sky_template_id, 
			t.sky_template_name, 
			u.sky_update_type_id, 
			u.sky_update_type_name, 
			next_update_type_id = n.sky_update_type_id, 
			next_update_type_name = n.sky_update_type_name
	from sky_template_update_type tu
	inner join sky_template t
		on tu.sky_template_id = t.sky_template_id
	inner join sky_update_type u
		on tu.sky_update_type_id = u.sky_update_type_id
	left join sky_update_type n
		on tu.next_update_type_id = n.sky_update_type_id
	where tu.sky_template_id = case when @sky_template_id is null then tu.sky_template_id else @sky_template_id end
	order by tu.sky_template_update_type_id

	-- 1.3) return results
	select step_id, sky_template_id, sky_template_name, sky_update_type_id, sky_update_type_name, next_update_type_id, next_update_type_name
	from @template_update_type
	order by step_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
