CREATE procedure [dbo].[usp_sky_select_update_license_batch]

/*	
	DATE		AUTHOR		REMARKS
	2017-06-29	esmart		Initial creation.
	2019-08-02	acoffel		add brtc

	DESCRIPTION
	select batch for sky_update
*/

as
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = max(process_date)
	from sky_update u
	inner join sky_update_type t
		on u.sky_update_type_id = t.sky_update_type_id
	where process_date <= getdate() and u.sky_template_id in (4,8)
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
