		--	(pe.product_platform_id = f.product_platform_id or pe.product_platform_id is null)

	-- 1.4) add supplemental template for secondary products
	insert into @sky_update(license_id, sky_template_id,sky_update_type_id, process_date)
	select s.license_id, st.sky_template_id, ut.sky_update_type_id, dateadd(ms,100,s.process_date)
	from @sky_update s
	cross apply fn_license_select_license_profile(s.license_id) f
	inner join license_category lc
		on f.license_category_name = lc.license_category_name
	inner join sky_supplemental_template st
		on st.license_category_id = lc.license_category_id
	inner join sky_template_update_type ut
		on ut.sky_template_id = st.sky_template_id
	outer apply fn_product_select_product_extension(st.product_extension_json) e
	where s.license_id = f.license_id and st.sky_templat
e_id <> 14 and (e.product_platform_id is null or e.product_platform_id = f.product_platform_id)
		
