CREATE PROCEDURE [dbo].[usp_sky_update_sky_update]

(
	@sky_update_id int,
	@sky_update_status_name varchar(20),
	@failure_description varchar(5000) = null
)

/*	
	DATE		AUTHOR		REMARKS
	2014-02-23	esmart		Initial creation.
	2019-12-03	cnovac		Updated @failure_description to be 5000 + changed column in table to accept
	2022-03-03  psatish		SMCI-6349 Added Section:2.1.6 to create the template:Create_License_vault into sfdc_opportunity_update to create license vault in Salesforce
	2022-04-29  psatish		ALM# 1152 Commented the logic for license vault and handled in SQL job to fix the timing issue
	DESCRIPTION
	update sky update
*/

AS
	set nocount on				

	declare @sky_template_id tinyint,
			@sky_update_type_id tinyint,
			@next_update_type_id tinyint,
			@transaction_date datetime,
			@license_id int,
			@update_attempts tinyint,
			@response_code int,
			@message varchar(100)
	
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------				
	
	-- 1.1) 
	select @sky_update_type_id = sky_update_type_id, @license_id = license_id, @sky_template_id = sky_template_id
	from sky_update
	where sky_update_id = @sky_update_id

	select @transaction_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------				
	
	-- 2.1) processed
	if @sky_update_status_name = 'Processed'
		begin
		
        --  Create-license_vault template for Saleforce
			--if exists(select 1 from dbo.sky_update su
			--					inner join dbo.sky_update_type st
			--					on st.sky_update_type_id = su.sky_update_type_id
			--					where su.sky_update_id=@sky_update_id AND license_id=@license_id
			--					AND st.sky_update_type_name IN('O365_update','CBEP_update'))
			--begin	
			--	exec [usp_sfdc_create_update_license_vault_template] @license_id=@license_id,@sfdc_template_name='create_license_vault'
			--end


			-- 2.1.1) insert archive
			insert into sky_update_archive(sky_update_id, license_id, sky_update_status_id, sky_template_id, sky_update_type_id, insert_date, update_attempts, process_date, archive_date)
			select sky_update_id, license_id, sky_update_status_id=1, sky_template_id, sky_update_type_id, insert_date, update_attempts, process_date, @transaction_date
			from sky_update
			where sky_update_id = @sky_update_id

			select @next_update_type_id = next_update_type_id
			from sky_template_update_type 
			where sky_update_type_id = @sky_update_type_id and sky_template_id = @sky_template_id
		
			--select sky_template_id = @sky_template_id, next_update_type_id = @next_update_type_id
			--return

			if @next_update_type_id is null
			-- 2.1.2) delete queue
				begin
					delete from sky_update
					where sky_update_id = @sky_update_id
				end
			else
			-- 2.1.3) update queue
				begin
					update sky_update
					set sky_update_type_id = @next_update_type_id, process_date = @transaction_date
					where sky_update_id = @sky_update_id
				end

			-- 2.1.4) set up next update table 
			declare @next_update table (sky_update_id int, license_id 
varchar(18), sky_update_type_id tinyint, sky_update_type_name varchar(20), sky_template_id tinyint, sky_template_name varchar(20))

			insert into @next_update(sky_update_id, license_id, sky_update_type_id, sky_update_type_name, sky_template_id, sky_template_name)
			select top 1 l.sky_update_id, l.license_id, t.sky_update_type_id, t.sky_update_type_name, tp.sky_template_id, tp.sky_template_name
			from sky_update l
			inner join sky_update_type t
				on l.sky_update_type_id = t.sky_update_type_id
			inner join sky_template tp
				on l.sky_template_id = tp.sky_template_id
			where l.process_date <= @transaction_date and l.sky_update_id = @sky_update_id
			order by l.sky_update_id

			-- 2.1.5) return results
			if (select count(*) from @next_update) = 0
				begin
				-- 2.1.5.2) final result
				select sky_update_id = @sky_update_id, license_id = @license_id, sky_update_type_id=null, sky_update_type_name=null, sky_template_id=null, sky_template_name=null

				end
			else
				begin
				-- 2.1.5.3) next result
				select sky_update_id, license_id, sky_update_type_id, sky_update_type_name
				from @next_update
				end
			
		end

	-- 2.2) failed
	if @sky_update_status_name = 'Failed'
		begin

		-- 2.2.1) insert failure
		insert into sky_update_failure(sky_update_id, license_id, sky_update_status_id, sky_template_id, sky_update_type_id, insert_date, update_attempts, process_date, failure_description, failure_date)
		select sky_update_id, license_id, sky_update_status_id=2, sky_template_id, sky_update_type_id, insert_date, update_attempts, process_date, @failure_description, @transaction_date
		from sky_update
		where sky_update_id = @sky_update_id
		
		select @update_attempts = update_attempts
		from sky_update
		where sky_update_id = @sky_update_id

		if @update_attempts < 5
			-- 2.2.2) update queue
			begin
				update sky_update
				set process_date = dateadd(hh,1,@transaction_date), update_attempts = update_attempts + 1
				where sky_update_id = @sky_update_id
			end
		else
			-- 2.2.3) delete queue
			begin
				delete from sky_update
				where sky_update_id = @sky_update_id
			end

		end
				
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
