-- =============================================================================
-- PROCEDURE: [dbo].[usp_skytell_insert_notification_json]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_skytell_insert_notification_json]

(
	@skytell_notification_type varchar(50), --"Account.Created"
	@skytell_notification_correlation_guid uniqueidentifier, --Correlation ID provided by caller of API used to track notification
	@skytell_notification_request_guid uniqueidentifier, --Reference Guid used to track notification
	@skytell_notification_action varchar(50), -- "Intent", "Publishing", "Finished", "Delivered", "Failed"
	@skytell_notification_json varchar(max)
)

/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	2018-10-11		cnovac		Updated call to usp_account_order_finalize

	DESCRIPTION
	usp_skytell_insert_notification_json

*/

AS
	
	set nocount on

	begin try

	declare @skytell_notification_type_id tinyint,
			@skytell_notification_status_id smallint = 0,
			@pending_account_id varchar(65),
			@account_hash_id varchar(65),
			@account_id bigint,
			@console_id bigint,
			@skytell_notification_id int,
			@account_order_staging_id int,
			@merchant_id varchar(50),
			@order_token varchar(max),
			@license_id int,
			@order_header_id int,
			@account_order_json varchar(100),
			@rows_updated tinyint,
			@response_code int,
			@message varchar(200)

	select @skytell_notification_type_id = skytell_notification_type_id
	from skytell_notification_type
	where skytell_notification_type = @skytell_notification_type 

	insert into skytell_notification_json (skytell_notification_type_id, skytell_notification_correlation_guid, skytell_notification_request_guid, skytell_notification_action, skytell_notification_json)
	select @skytell_notification_type_id, @skytell_notification_correlation_guid, @skytell_notification_request_guid, @skytell_notification_action, @skytell_notification_json

	set @skytell_notification_id = scope_identity()

	--this type is for new accounts that are created on Derby side for WIFI console along with existing consoles for different product other than WIFI
	if @skytell_notification_type in ('Account.Created', 'Account.Changed')
	begin

		set @pending_account_id = json_value(@skytell_notification_json, '$.NDATA.ACCOUNTTOKEN')
		set @account_hash_id = json_value(@skytell_notification_json, '$.NDATA.HASHEDACCOUNTID')
		set @account_id = json_value(@skytell_notification_json, '$.NDATA.ACCOUNTID')
		set @console_id = json_value(@skytell_notification_json, '$.NDATA.CONSOLEID')

		update account_order_staging
		set skytell_notification_id = @skytell_notification_id,
			modified_date = getdate()
		where pending_account_id = @pending_account_id
		and skytell_notification_id is null

		select @rows_updated = @@ROWCOUNT
	
		if @pending_account_id is null or @account_hash_id is null or @account_id is null or @console_id is null
			set @skytell_notification_status_id = -1
		else if (select count(*) from account_order_staging where pending_account_id = @pending_account_id) > 1
			set @skytell_notification_status_id = -2
		else if (select count(*) from account_order_staging where pending_account_id = @pending_account_id) = 0
			set @skytell_notification_status_id = -3
		else if @rows_updated = 0
			set @skytell_notification_status_id = -4
		else if exists (select 1
						from account_order_staging aos
						inner join account_order_staging aos2 on aos2.order_receipt = aos.order_receipt
						where aos.pending_account_id = @pending_account_id
						and aos.account_order_staging_id != aos2.account_order_staging_id
						and aos2.account_hash_id is not null)
			set @skytell_notification_status_id = -5
		else
			update account_order_staging
			set account_hash_id = @account_hash_id,
				account_id = @account_id,
				console_id = @console_id,
				modified_date = getdate()
		
	where skytell_notification_id = @skytell_notification_id
	end

	--this means no issues found
	if @skytell_notification_status_id = 0
	begin

		select @account_order_staging_id = aos.account_order_staging_id,
			   @merchant_id = pm.merchant_id,
			   @order_token = aos.order_token
		from account_order_staging aos
		inner join payment_merchant pm on pm.payment_merchant_id = aos.payment_merchant_id
		where skytell_notification_id = @skytell_notification_id

		--for www orders, we haven't associated the order to create account call to this proc
		if @merchant_id = 'webroot'
		begin

			select @order_header_id = oh.order_header_id, @license_id = oil.license_id
			from order_header oh
			inner join order_item oi on oi.order_header_id = oh.order_header_id
			inner join order_item_license oil on oil.order_item_id = oi.order_item_id
			cross apply fn_license_select_license_profile(oil.license_id) l
			left join account_order ao on ao.order_header_id = oh.order_header_id
			where oh.order_header_token = @order_token
			and l.license_category_name = 'WIFI'
			and ao.account_order_id is null

			if @license_id is not null and @order_header_id is not null
			begin
				set @account_order_json = (select @account_order_staging_id as account_order_staging_id, @order_header_id as order_header_id for json path,without_array_wrapper)
				exec usp_account_order_finalize @license_id = @license_id, @account_order_json = @account_order_json
			end

		end

	end

	update skytell_notification_json
	set skytell_notification_status_id = @skytell_notification_status_id,
		modified_date = getdate()
	output Inserted.skytell_notification_status_id, Inserted.skytell_notification_id
	where skytell_notification_id = @skytell_notification_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_skytell_insert_notification_json'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_skytell_select_notification_data]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_skytell_select_notification_data]

(
	@skytell_notification_id int
)
	
/*	
	DATE			AUTHOR		REMARKS
	2018-05-07		cnovac		Initial creation
	
	DESCRIPTION
	usp_skytell_select_notification_data
	
*/

AS
	
	set nocount on

	begin try

	declare @skytell_notification_type varchar(50), --"Account.Created"
			@response_code int,
			@message varchar(100)

	select @skytell_notification_type = snt.skytell_notification_type
	from skytell_notification_json snj
	inner join skytell_notification_type snt on snt.skytell_notification_type_id = snj.skytell_notification_type_id
	where skytell_notification_id = @skytell_notification_id

	if @skytell_notification_type in ('Account.Created', 'Account.Changed')
	begin

		select aos.account_order_staging_id,
			   aos.order_token,
			   aos.merchant_product_id,
			   pm.merchant_id
		from account_order_staging aos
		inner join payment_merchant pm on pm.payment_merchant_id = aos.payment_merchant_id
		where aos.skytell_notification_id = @skytell_notification_id

	end

	if @skytell_notification_type = 'Password.Changed'
	begin

		select aos.account_hash_id
		from skytell_notification_json snj
		inner join account_order_staging aos on json_value(snj.skytell_notification_json, '$.NDATA.ACCOUNTID') = aos.account_id
		where snj.skytell_notification_id = @skytell_notification_id
		group by aos.account_hash_id

	end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'error in usp_skytell_select_notification_data'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
