CREATE PROCEDURE [dbo].[usp_SOS_delete_SOS_processing]
(
	@license_id int,
	@SOS_method_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-02		esmart		Initial creation

	DESCRIPTION
	update SOS_processing record
*/

AS

set nocount on

begin try

	declare @log_type int

	set @log_type = 1
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1 Check to see if record exists.
			select @response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then 'SOS_processing does not exist. License_id (' + convert(varchar(20),@license_id) + ') and  @SOS_method_id (' + convert(varchar(20),@SOS_method_id) + ')' else '' end
			from SOS_processing
			where license_id = @license_id and SOS_method_id = @SOS_method_id

			if @response_code < 0 	
				begin
					return
				end
			
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) delete SOS_processing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
			delete from SOS_processing
			where license_id = @license_id and SOS_method_id = @SOS_method_id
	
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'SOS_processing delete failed @license_id = ' + isnull(convert(varchar(10),@license_id),'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_SOS_insert_SOS_processing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_SOS_insert_SOS_processing]
(
	@license_id int,
	@SOS_method_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-02		esmart		Initial creation

	DESCRIPTION
	insert SOS_processing record
*/

AS

set nocount on

begin try

	declare @log_type int

	set @log_type = 1
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1 @license_id
			select @response_code =  case when count(*) = 0 then -110 else 0	 end,
				@message = case when count(*) = 0 then '@license_id (' + convert(varchar(20),@license_id) + ')not valid' else '' end
			from license
			where license_id = @license_id

			if @response_code < 0 	
				begin
					RAISERROR (@message, 11, 0)
				end

		-- 1.2 @SOS_method_id
			select @response_code =  case when count(*) = 0 then -120 else 0	 end,
				@message = case when count(*) = 0 then '@SOS_method_id (' + convert(varchar(20),@SOS_method_id) + ') not valid' else '' end
			from SOS_method
			where SOS_method_id = @SOS_method_id

			if @response_code < 0 	
				begin
					RAISERROR (@message, 11, 0)
				end

		-- 1.3 Check to see if record already exists
			select @response_code =  case when count(*) > 0 then -130 else 0	 end,
				@message = case when count(*) > 0 then 'SOS_processing already exists. License_id (' + convert(varchar(20),@license_id) + ') and  @SOS_method_id (' + convert(varchar(20),@SOS_method_id) + ')' else '' end
			from SOS_processing
			where license_id = @license_id and SOS_method_id = @SOS_method_id

			if @response_code < 0 	
				begin
					return
				end
			

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert product_capability_working
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
			insert into SOS_processing(license_id, SOS_method_id)
			values (@license_id, @SOS_method_id)
	
end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'SOS_processing insert failed @license_id = ' + isnull(convert(varchar(10),@license_id),'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;



SET ANSI_NULLS OFF

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_SOS_select_product_mapping]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_SOS_select_product_mapping]
(
	@license_id varchar(40),
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-01		esmart		Initial creation

	DESCRIPTION
	get product information for SOS storage update
*/

AS

set nocount on

begin try

	declare @product_line_id int,
		@storage_gb int,
		@log_type int

	set @log_type = 1
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
		-- 1.1) get @product_line_id
			select @product_line_id = product_line_id
			from license 
			where license_id = @license_id			

		if @product_line_id is null 	
			begin
				select @response_code = -110,
						@message = '@product_line_id is null. @license_id = ' + convert(varchar(20),@license_id)
				RAISERROR (@message, 11, 0)
			end

		-- 1.2) get remaining months on license
			select @storage_gb = storage_gb 
			from license_storage 
			where license_id = @license_id 

		if @storage_gb is null 	
			begin
				select @response_code = -120,
						@message = '@storage_gb is null. @license_id = ' + convert(varchar(20),@license_id)
				RAISERROR (@message, 11, 0)
			end

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return products and pricing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select product_line_id, storage_gb, payment_plan_id, customer_type_code
		from SOS_product_mapping
		where product_line_id = @product_line_id and
			storage_gb = @storage_gb
		
end try
begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_SOS_select_SOS_processing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_SOS_select_SOS_processing]

/*	
	DATE			AUTHOR		REMARKS
	2008-10-02		esmart		Initial creation

	DESCRIPTION
	select SOS_processing records
*/

AS
set nocount on

declare @response_code int,
		@message varchar(100)

begin try

	declare @log_type int

	set @log_type = 1
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select SOS_processing
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
	select p.SOS_processing_id, p.license_id, m.SOS_method_id, m.SOS_method_name, p.insert_date, p.insert_by, p.modified_date, p.modified_by
	from SOS_processing p
	inner join SOS_method m
		on p.SOS_method_id = m.SOS_method_id
	order by p.license_id, p.insert_date
	
end try
begin catch

	set @response_code = -100
	set @message = case when @message is null then 'SOS_processing select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;



SET ANSI_NULLS OFF

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_specials_products_select]
-- =============================================================================




CREATE PROCEDURE usp_specials_products_select

(
	@specials_id int
)

AS
/*	DATE		AUTHOR		REMARKS
	2006-08-14	TBlazek			Initial creation.
	2006-09-04	esmart			Modification to point to new product table

	DESCRIPTION
	Return a result set of specials_products rows to the PHP code
*/
	
	set nocount on
	declare @return int
	select @return = 0
	
	select 	sp.product_id,
		sp.quantity,
		sp.visible_price,
		sp.stored_price,
		p.retail_price,
		sp.last_modified
	from specials_products sp
	left join product p
		on sp.product_id = p.product_id
	where  sp.specials_id = @specials_id
	
	If @@error > 0
		begin
			set @return = @@error
			return @return
		end




GO
