-- =============================================================================
-- PROCEDURE: [dbo].[usp_spy_alert_active_select]
-- =============================================================================



CREATE  PROCEDURE usp_spy_alert_active_select
	@sub_status int,
	@reg_status int,
	@expiration_date varchar(20),
	@product_id int,
	@reference_id int,
	@language_code varchar(3),
	@country_code_3 varchar(3),
	@product_version_str char(10)--,
	--@Totalcount INT OUTPUT
AS
/*	DATE		AUTHOR		REMARKS
	03/09/06	KKeating	Initial creation.
	04/19/06	TBlazek		Finalize procedure design, naming conventions, remove output parameter


	DESCRIPTION
		Return the list of active spy alerts for the UI that interacts with the product
*/


-- *************************************************************************************************************
-- 1.) Select all Spy Alerts that match the request
-- *************************************************************************************************************
DECLARE @count int
SELECT @count = 0

Declare @return int
Select @return = 0

DECLARE @current_date datetime
SELECT @current_date = getdate()

SELECT
	distinct saa.alert_active_id,
	saa.title,
	saa.short_description, 
	saa.link
FROM spy_alert_active saa
join spy_alert_active_detail saad on saa.alert_active_id = saad.alert_active_id
WHERE
	saa.alert_status = 1                                
	AND saa.start_date <= @current_date                 
	AND saa.end_date >= @current_date
	AND saa.language_code = @language_code     
	AND (saa.sub_status = @sub_status
		OR saa.sub_status is NULL)   
	AND (saa.reg_status is NULL 
		OR saa.reg_status = @reg_status)
	AND (saa.expire_start is NULL 
		OR (@current_date >= dateadd(day, saa.expire_start, convert( datetime, @expiration_date ) ) 
			AND @current_date <= dateadd(day, saa.expire_end, convert( datetime, @expiration_date ))))   
	AND saad.product_id = @product_id          
	AND (saad.country_code_3 = @country_code_3 
		OR saad.country_code_3 is NULL)
	AND (saad.product_version_str = @product_version_str
		OR saad.product_version_str is NULL)
	AND (saad.reference_id is NULL 
		OR saad.reference_id = @reference_id)

SELECT @return = @@ERROR--, @Totalcount = @@ROWcount

RETURN @return



GO
