-- PROCEDURE: [dbo].[usp_spy_alert_insert]
-- =============================================================================





CREATE         PROCEDURE usp_spy_alert_insert
	@title nvarchar(300),
	@description  nvarchar(1000),
	@link  nvarchar(500),
	@start_date datetime,
	@end_date datetime,
	@sub_status int,
	@expire_begin int,
	@expire_end int,
	@reg_status int,
	@language_id int,
	@alert_product_version_id int,
	@location_count int,
	@location_value varchar(850),
	@build_count int,
	@build_value varchar(8000), 
	@version_compare_id int,
	@alert_status smallint,
	@userid nvarchar(50),  
	@note nvarchar(4000),
	@alert_id int OUTPUT,
	@modified_date  datetime OUTPUT,
	@modified_by nvarchar(50) OUTPUT
AS
/*	DATE		AUTHOR		REMARKS
	04/12/06	TBlazek		Initial creation.


	DESCRIPTION
		Insert a single spy alert from the "Create/Edit Spy Alert" UI, return alert_id, modified_by, and modified_date
*/

SET NOCOUNT ON
Declare @return int,
	@len smallint,
	@string_len smallint,
	@current_date datetime

BEGIN TRANSACTION spy_alert_insert 

Select @return = 0
Select @current_date = getdate()

--Build spy_alert record
Insert	spy_alert(
	title,
	description,
	link,
	start_date,
	end_date,
	sub_status,
	expire_begin,
	expire_end,
	reg_status,
	language_id,
	alert_product_version_id,
	version_compare_id,
	insert_date,
	insert_by,
	modified_date,
	modified_by,
	alert_status)
Values
	(@title,
	@description,
	@link,
	@start_date,
	@end_date,
	@sub_status,
	@expire_begin,
	@expire_end,
	@reg_status,
	@language_id,
	@alert_product_version_id,
	@version_compare_id,
	@current_date,
	@userid,
	@current_date,
	@userid,
	@alert_status)

	If @@ERROR > 0
		BEGIN
			ROLLBACK TRANSACTION spy_alert_insert
			SET @return = -100
			RETURN @return
		END
--retrieve return values

Select 	@alert_id = SCOPE_IDENTITY(), 
	@modified_date  = modified_date,
	@modified_by = modified_by
from spy_alert
where alert_id = SCOPE_IDENTITY() 

--insert alert_location table
While @location_count > 0
BEGIN
	Insert alert_location
	values (@alert_id, substring(@location_value, 0, charindex(',', @location_value, 0)), @current_date, @userid, @current_date, @userid)
		If @@ERROR > 0
			BEGIN
				ROLLBACK TRANSACTION spy_alert_insert
				Select @alert_id = null, @modified_date = null, @modified_by = null
				SET @return = -105
				RETURN @return
			END

	Select @string_len = len(@location_value) 
	Select @len = len(substring(@location_value, 0, charindex(',', @location_value, 0)))
	Select @location_value = substring(@location_value, @len + 2, @string_len)
	Select @location_count = @location_count - 1
END
--insert alert_build table
While @build_count > 0
BEGIN
	Insert alert_build
	values (@alert_id, substring(@build_value, 0, charindex(',', @build_value, 0)), @current_date, @userid, @current_date, @userid)
		If @@ERROR > 0
			BEGIN
				ROLLBACK TRANSACTION spy_alert_insert
				Select @alert_id = null, @modified_date = null, @modified_by = null
				SET @return = -110
				RETURN @return
			END

	Select @string_len = len(@build_value) 
	Select @len = len(substring(@build_value, 0, charindex(',', @build_value, 0)))
	Select @build_value = substring(@build_value, @len + 2, @string_len)
	Select @build_count = @build_count - 1
END

--Insert note
If @note is not null
	Begin
		Insert spy_alert_note
		Values(@alert_id, @note, @current_date, @userid, @current_date, @userid)
		If @@ERROR > 0
			BEGIN
				ROLLBACK TRANSACTION spy_alert_insert
				Select @alert_id = null, @modified_date = null, @modified_by = null
				SET @return = -115
				RETURN @return
			END

	End

COMMIT TRANSACTION spy_alert_insert

GO
