-- =============================================================================



CREATE   PROCEDURE usp_spy_alert_list_select
AS
/*	DATE		AUTHOR		REMARKS
	04/11/06	TBlazek		Initial creation.


	DESCRIPTION
		Return the list of spy alerts to the "Spy Alerts List UI"
*/

SET NOCOUNT ON
Declare @return int
Select @return = 0

Select
	spa.alert_id,  			--used for action links
	spa.title,
	spa.start_date,
	spa.end_date,
	pg.Name, --product group name 
	ll.description,  		--Language description
	lvc.compare_code + 
	Convert(varchar(2), ISNULL(pv.major_version, 0)) + '.' + 
	Convert(varchar(2), ISNULL(pv.minor_version, 0)) + '.' + 
	Convert(varchar(2), ISNULL(pv.release, 0)) + '.' + 
	Convert(varchar(3), ISNULL(pv.bld, 0))  As 'version',
	spa.alert_status 		--used for action links
From spy_alert spa
Join alert_product_version apv
	On apv.alert_product_version_id = spa.alert_product_version_id
Join ProductGroup pg
	On apv.product_group_id = pg.id
Join lu_language ll
	On spa.language_id = ll.language_id 
Join product_versions pv
	On apv.product_version_id = pv.product_version_id
Join lu_version_compare lvc
	On lvc.version_compare_id = spa.version_compare_id

If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END


GO
