	Convert(varchar(2), ISNULL(pv.minor_version, 0)) + '.' + 
	Convert(varchar(2), ISNULL(pv.release, 0)) + '.' + 
	Convert(varchar(3), ISNULL(pv.bld, 0))  As 'version'
From alert_product_version apv
Join ProductGroup pg
	On apv.product_group_id = pg.id
Join product_versions pv
	On apv.product_version_id = pv.product_version_id

If @@ERROR > 0
