-- =============================================================================
-- PROCEDURE: [dbo].[usp_spy_alert_select]
-- =============================================================================



CREATE     PROCEDURE usp_spy_alert_select
@alert_id int
AS
/*	DATE		AUTHOR		REMARKS
	04/12/06	TBlazek		Initial creation.
	05/22/06	TBlazek		Add location count, string and build count, string to return result set


	DESCRIPTION
		Return a single spy alert to the "Create/Edit Spy Alert" UI
*/

SET NOCOUNT ON
Declare @return int
Select @return = 0

declare @location_count int, 
	@build_count int, 
	@location_value varchar(850), 
	@build_value varchar(8000)
--initialize variables
select @location_value = ''
select @build_value = ''

Select @location_count = count(country_id)from dbo.alert_location where alert_id = @alert_id
If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END

select @location_value = @location_value + convert(varchar(10),country_id) + ',' from dbo.alert_location where alert_id = @alert_id
If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END

Select @build_count = count(reference_id) 
from affiliate_build afb
join alert_build ab
on afb.build_id = ab.build_id
where alert_id = @alert_id
If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END

select @build_value = @build_value + convert(varchar(10), reference_id) +  ',' 
from affiliate_build afb
join alert_build ab
on afb.build_id = ab.build_id
where alert_id = @alert_id
If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END

Select
	sa.alert_id,  			
	sa.title,
	sa.description,
	sa.link,
	sa.start_date,
	sa.end_date,
	sa.sub_status,
	sa.expire_begin,
	sa.expire_end,
	sa.reg_status,
	sa.language_id,
	sa.alert_product_version_id,
	@location_count as 'location_count',
	@location_value as 'location_value',
	@build_count as 'build_count',
	@build_value as 'build_value',
	sa.version_compare_id,
	sa.modified_date,
	sa.modified_by,
	sa.alert_status,
	san.alert_note_id,
	san.note
From spy_alert sa
	Left Outer JOIN spy_alert_note san
	On sa.alert_id = san.alert_id
Where sa.alert_id = @alert_id

If @@ERROR > 0
	BEGIN
		SET @return = @@ERROR
		RETURN @return
	END



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_spy_alert_update]
-- =============================================================================



CREATE       PROCEDURE usp_spy_alert_update
	@alert_id int,
	@title nvarchar(300),
	@description  nvarchar(1000),
	@link  nvarchar(500),
	@start_date datetime,
	@end_date datetime,
	@sub_status int,
	@expire_begin int,
	@expire_end int,
	@reg_status int,
	@language_id int,
	@alert_product_version_id int,
	@location_count int,  --send null if no changes
	@location_value varchar(850),  --send null if no changes
	@build_count int, --send null if no changes
	@build_value varchar(8000),  --send null if no changes
	@version_compare_id int,
	@alert_status smallint,
	@userid varchar(50),  
	@alert_note_id int,
	@note nvarchar(4000),
	@modified_date  datetime OUTPUT,
	@modified_by nvarchar(50) OUTPUT
AS
/*	DATE		AUTHOR		REMARKS
	04/14/06	TBlazek		Initial creation.


	DESCRIPTION
		Update a single spy alert from the "Create/Edit Spy Alert" UI, return, modified_by, and modified_date
*/

SET NOCOUNT ON
Declare @return int,
	@len smallint,
	@string_len smallint,
	@current_date datetime


BEGIN TRANSACTION spy_alert_update 

Select @return = 0
SELECT @current_date = getdate()
--Update spy_alert record
Update	spy_alert
SET	title = @title,
	description = @description,
	link = @link,
	start_date = @start_date,
	end_date = @end_date,
	sub_status = @sub_status,
	expire_begin = @expire_begin,
	expire_end = @expire_end,
	reg_status = @reg_status,
	language_id = @language_id,
	alert_product_version_id = @alert_product_version_id,
	version_compare_id = @version_compare_id,
	modified_date = @current_date,
	modified_by = @userid,
	alert_status = @alert_status
Where alert_id = @alert_id

	If @@ERROR > 0
		BEGIN
				ROLLBACK TRANSACTION spy_alert_update
				SET @return = -120
				RETURN @return
		END

--retrieve return values
Select 	@modified_date  = modified_date,
	@modified_by = modified_by
from spy_alert
where alert_id = @alert_id

--update alert_location table
IF @location_count is not null
BEGIN
Delete from alert_location where alert_id = @alert_id
	While @location_count > 0
	BEGIN
		Insert alert_location
		values (@alert_id, substring(@location_value, 0, charindex(',', @location_value, 0)), @current_date, @userid, @current_date, @userid)
			If @@ERROR > 0
				BEGIN
						ROLLBACK TRANSACTION spy_alert_update
						Select @modified_date = null, @modified_by = null
						SET @return = -125
						RETURN @return
				END

		Select @string_len = len(@location_value) 
		Select @len = len(substring(@location_value, 0, charindex(',', @location_value, 0)))
		Select @location_value = substring(@location_value, @len + 2, @string_len)
		Select @location_count = @location_count - 1
	END
END
--update alert_build table
IF @build_count is not null
BEGIN
Delete from alert_build where alert_id = @alert_id
	If @@ERROR > 0
		BEGIN
				ROLLBACK TRANSACTION spy_alert_update
				Select @modified_date = null, @modified_by = null
				SET @return = -130
				RETURN @return
		END


	While @build_count > 0
	BEGIN
		Insert alert_build
		values (@alert_id, substring(@build_value, 0, charindex(',', @build_value, 0)), @current_date, @userid, @current_date, @userid)
		If @@ERROR > 0
			BEGIN
					ROLLBACK TRANSACTION spy_alert_update
					Select @modified_date = null, @modified_by = null
					SET @return = -135
					RETURN @return
			END
		Select @string_len = len(@build_value) 
		Select @len = len(substring(@build_value, 0, charindex(',', @build_value, 0)))
		Select @build_value = substring(@build_value, @len + 2, @string_len)
		Select @build_count = @build_count - 1
	END
END

--Update note
If @note is not null
	BEGIN
	If @alert_note_id is null  --there was no note on the initial insert
		BEGIN
			Insert spy_alert_note
			Values(@alert_id, 
@note, @current_date, @userid, @current_date, @userid)
			If @@ERROR > 0
				BEGIN
						ROLLBACK TRANSACTION spy_alert_update
						Select @modified_date = null, @modified_by = null
						SET @return = -140
						RETURN @return
				END

		END
	Else
		BEGIN
			Update spy_alert_note
			Set note = @note, modified_date = @current_date, modified_by = @userid
			Where alert_note_id = @alert_note_id
			If @@ERROR > 0
				BEGIN
						ROLLBACK TRANSACTION spy_alert_update
						Select @modified_date = null, @modified_by = null
						SET @return = -145
						RETURN @return
				END
		END
	END
COMMIT TRANSACTION spy_alert_update

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_state_select_states]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_state_select_states]
		
(@country varchar(4) = null)

/*	
	DATE		AUTHOR	REMARKS
	2006-08-11	esmart		Initial creation.	
	2012-04-03	acoffel		set up to handle new regions
	2016-06-02	acoffel		New Zealand
	2020-06-13	abelenkiy	AXIOM-1378: Removed some US states from return, removed 'ST' exclusion from JP
	2022-02-24  psatish		ALM# 629/758 Added the colulm external_description in the select clause and added South Africa
	2022-03-10  psatish		ALM# 758 Added the Countries India and Brazil
	DESCRIPTION
	Select all states from lu_states
*/

AS

-- check for num country
if @country is null 
set @country = 'US'

if @country = 'JP'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by convert(int,state_id)
if @country = 'CA'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id
if @country = 'AU'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id
if @country = 'US'
	select state_id, description, state_iso3, external_description
	from lu_states
	where admin_id not in (1, 8, 9, 10, 17, 31, 56, 65)--8,9,10-Armed Forces..., 17-Micronesia, 31-Marshall Islands, 56-Palau, 65-'State', 1-'No state'
	and iso2 = @country
	order by description
if @country = 'NZ'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id
if @country = 'ZA'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id
if @country = 'BR'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id
if @country = 'IN'
	select state_id, description, state_iso3, external_description
	from lu_states
	where iso2 = @country
	order by admin_id

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_storage_insert_storage_account]
-- =============================================================================



CREATE PROCEDURE [dbo].[usp_storage_insert_storage_account]

(
	@storage_account_username nvarchar(50), 
	@storage_account_password nvarchar(40), 
	@security_question varchar(100), 
	@secret_answer varchar(100), 
	@license_id int,
	@storage_account_status_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-07-22		esmart		Initial creation
	
	DESCRIPTION
	insert storage_account
*/

AS

	set nocount on


	begin try

		declare @log_type int,
				@license_storage_id int,
				@storage_account_id int

		set @log_type = 1

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.1 @storage_account_username
		select @response_code =  case when count(*) > 0 then -110 else 0	 end,
			@message = case when count(*) > 0 then '@storage_account_username already exists' else '' end
		from storage_account
		where storage_account_username = @storage_account_username

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end

		-- 1.2 @storage_account_password
--		if @storage_account_password is null
--			begin
--				set @response_code = -120
--				set @message = '@storage_account_password cannot be null'
--				set @log_type = -1
--				RAISERROR (@message, 11, 0)
--			end

		-- 1.3 @license_storage_id	
		if @license_id is not null
			begin
				-- get license_storage_id 
				select @license_storage_id = license_storage_id
				from license_storage 
				where license_id = @license_id and license_storage_id not in (select license_storage_id from storage_account where license_storage_id is not null)
				
--				select @response_code =  case when license_storage_id is null then -130 else 0	 end,
--					@message = case when license_storage_id is null then '@license_storage_id does not exist' else '' end
--				from license_storage
--				where license_storage_id = @license_storage_id

--				if @response_code < 0 	
--					begin
--						RAISERROR (@message, 11, 0)
--					end

				select @response_code =  case when license_storage_id is not null then -130 else 0	 end,
					@message = case when license_storage_id is not null then '@license_storage_id associated with another account' else '' end
				from storage_account
				where license_storage_id = @license_storage_id

				if @response_code < 0 	
					begin
						RAISERROR (@message, 11, 0)
					end

			end

		-- 1.4 @storage_account_status_id	
		select @response_code =  case when storage_account_status_id is null then -140 else 0	 end,
			@message = case when storage_account_status_id is null then '@storage_account_status_id is not valid' else '' end
		from storage_account_status
		where storage_account_status_id = @storage_account_status_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
		-- 1.5 check to see if the license type is OEM
		select @response_code =  case when license_type_id in (2,3) then -150 else 0	 end,
			@message = case when license_type_id in (2,3) then 'Activation of storage account on parent license is not allowed' else '' end
		from license
		where license_id = @license_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end


	-- --------------------------------------------
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert storage_account
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		insert into storage_account (storage_account_username, storage_account_password, security_question, secret_answer, license_storage_id, storage_account_status_id)
		values (@storage_account_username, @storage_account_password, @security_question, @secret_answer, @license_storage_id, @storage_account_status_id)

		SET @storage_account_id = scope_identity()
		SELECT storage_account_id = @storage_account_id

	end try

	begin catch
			
			declare @DBName nvarchar(128)
			
			set @DBName = db_name()
			set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
			set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
			set @message = case 
								when @message is null then 'storage_account insert failed'
								else @message 
							end
			
			exec usp_LogError @log_type, @ErrorDB = @DBName
			
	end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_storage_select_storage_account_by_keycode]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_storage_select_storage_account_by_keycode]

(
	@keycode varchar(40)
)

/*	
	DATE			AUTHOR		REMARKS
	2008-07-31		esmart		Initial creation
	
	DESCRIPTION
	select storage account by keycode
*/

AS

	set nocount on

	declare @license_id int

	select @license_id = license_id
	from license 
	where keycode = @keycode

	if @license_id is not null
		begin
			SELECT ls.license_storage_id,
				   ls.license_id,
				   ls.storage_gb,
				   ls.storage_activation_date,
				   ls.storage_expiration_date,
				   sa.storage_account_id,
				   sa.storage_account_username,
				   sa.storage_account_password,
				   sa.security_question,
				   sa.secret_answer,
				   sas.storage_account_status_id,
				   sas.storage_account_status_name
			FROM license_storage ls 
				LEFT OUTER JOIN storage_account sa 
					ON ls.license_storage_id = sa.license_storage_id 
				LEFT JOIN storage_account_status sas 
					ON sa.storage_account_status_id = sas.storage_account_status_id
			WHERE license_id = @license_id
		end




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_storage_select_storage_account_by_username]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_storage_select_storage_account_by_username]

(
	@storage_account_username nvarchar(50)
)

/*	
	DATE			AUTHOR		REMARKS
	2008-10-12		esmart		Initial creation
	
	DESCRIPTION
	select storage account by username
*/

AS

	set nocount on

	select ls.license_storage_id,
		   ls.license_id,
		   ls.storage_gb,
		   ls.storage_activation_date,
		   ls.storage_expiration_date,
		   sa.storage_account_id,
		   sa.storage_account_username,
		   sa.storage_account_password,
		   sa.security_question,
		   sa.secret_answer,
		   sas.storage_account_status_id,
		   sas.storage_account_status_name,
		   l.keycode
	from license_storage ls 
	inner join license l
		on ls.license_id = l.license_id
	inner join storage_account sa 
		on ls.license_storage_id = sa.license_storage_id 
	inner join storage_account_status sas 
		on sa.storage_account_status_id = sas.storage_account_status_id
	where storage_account_username = @storage_account_username


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_storage_update_link_storage_account_keycode]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_storage_update_link_storage_account_keycode]

(
	@storage_account_username nvarchar(50),	
	@keycode varchar(40),
	@response_code int output,
	@message varchar(100) output	
)

/*	
	DATE			AUTHOR		REMARKS
	2008-08-01		esmart		Initial creation
	
	DESCRIPTION
	Links storage_account to license with keycode input
*/

AS

	set nocount on
	
	begin try

	declare @log_type int

	set @log_type = 1

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1 @license_storage_id

		declare @license_storage_id int
	
		select @license_storage_id = license_storage_id
		from license l
		inner join license_storage ls
			on l.license_id = ls.license_id
		where keycode = @keycode

		if @license_storage_id is null
			begin
				set @response_code = -110
				set @message = '@license_storage_id cannot be null'
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end	

		-- 1.2 @storage_account_id

		declare @storage_account_id int
	
		select @storage_account_id = storage_account_id
		from storage_account
		where storage_account_username = @storage_account_username

		if @storage_account_id is null
			begin
				set @response_code = -120
				set @message = '@storage_account_id cannot be null'
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end	

		-- 1.3) check to see if storage_account is already related to a license

		declare @current_license_storage_id int

		select @current_license_storage_id = license_storage_id
		from storage_account
		where @storage_account_username = storage_account_username

		if @current_license_storage_id <> @license_storage_id
			begin
				set @response_code = -131
				set @message = 'storage_account is associated with different license_storage record'
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end
		if @current_license_storage_id = @license_storage_id
			begin
				set @response_code = 0
				set @message = 'storage_account is already associated license_storage record. No update needed'
				return
			end
	
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) udpate storage_account
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert storage_account_audit
		
		insert into storage_account_audit (storage_account_id, storage_account_username, storage_account_password, security_question, secret_answer, license_storage_id, storage_account_status_id, insert_date, insert_by, modified_date, modified_by)
		select storage_account_id, storage_account_username, storage_account_password, security_question, secret_answer, license_storage_id, storage_account_status_id, insert_date, insert_by, modified_date, modified_by
		from storage_account
		where storage_account_id = @storage_account_id

		-- 2.2) update storage_account
		
		update storage_account
		set license_storage_id = @licens
e_storage_id,
			modified_date = getdate(),
			modified_by = suser_sname()
		where storage_account_id = @storage_account_id
		
	end try

	begin catch
			
			declare @DBName nvarchar(128)
			
			set @DBName = db_name()
			set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
			set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
			set @message = case 
								when @message is null then 'storage_account update failed'
								else @message 
							end
			
			exec usp_LogError @log_type, @ErrorDB = @DBName
			
	end catch;





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_storage_update_storage_account]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_storage_update_storage_account]

(
	@storage_account_id int,
	@storage_account_username nvarchar(50), 
	@storage_account_password nvarchar(40), 
	@security_question varchar(100), 
	@secret_answer varchar(100),  
	@license_storage_id int,
	@storage_account_status_id int,
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE			AUTHOR		REMARKS
	2008-07-22		esmart		Initial creation
	
	DESCRIPTION
	update storage_account
*/

AS

	set nocount on


	begin try

		declare @log_type int

		set @log_type = 1

	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		-- 1.0 @license_storage_id	
		select @response_code =  case when storage_account_id is null then -100 else 0	 end,
			@message = case when storage_account_id is null then '@storage_account_id does not exist' else '' end
		from storage_account
		where storage_account_id = @storage_account_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end

		-- 1.1 @storage_account_username
		select @response_code =  case when count(*) > 0 then -110 else 0	 end,
			@message = case when count(*) > 0 then '@storage_account_username already exists' else '' end
		from storage_account
		where storage_account_username = @storage_account_username and storage_account_id <> @storage_account_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end

		-- 1.2 @storage_account_password
		if @storage_account_password is null
			begin
				set @response_code = -120
				set @message = '@storage_account_password cannot be null'
				set @log_type = -1
				RAISERROR (@message, 11, 0)
			end

		-- 1.3 @license_storage_id	
		select @response_code =  case when license_storage_id is null then -130 else 0	 end,
			@message = case when license_storage_id is null then '@license_storage_id does not exist' else '' end
		from license_storage
		where license_storage_id = @license_storage_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end

		-- 1.4 @license_storage_id	
		select @response_code =  case when license_storage_id is not null then -140 else 0	 end,
			@message = case when license_storage_id is not null then '@license_storage_id associated with another account' else '' end
		from storage_account
		where license_storage_id = @license_storage_id and storage_account_id <> @storage_account_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
		-- 1.5 @storage_account_status_id	
		select @response_code =  case when storage_account_status_id is null then -150 else 0	 end,
			@message = case when storage_account_status_id is null then '@storage_account_status_id is not valid' else '' end
		from storage_account_status
		where storage_account_status_id = @storage_account_status_id

		if @response_code < 0 	
			begin
				RAISERROR (@message, 11, 0)
			end
		
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) udpate storage_account
	-- --------------------------------------------------------------------
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert storage_account_audit
		
		insert into storage_account_audit (storage_account_id, storage_account_username, storage_account_password, security_question, secret_answer, license_storage_id, storage_account_status_id, insert_date, insert_by, modified_date, modified_by)
		select storage_account_id, storage_account_username, storage_account_password, security_question, secret_answer, license_storage_id, storage_account_status_id, insert_date, insert_by, modified_date, modified_by
		from storage_account
		where storage_account_id = @storage_account_id

		-- 2.2) update storage_account
		
		update storage_account
		set storage_account_username = @storage_account_username,
			storage_account_password = @storage_account_password,
			security_question = @security_question, 
			secret_answer = @secret_answer,
			license_storage_id = @license_storage_id,
			storage_account_status_id = @storage_account_status_id,
			modified_date = getdate(),
			modified_by = suser_sname()
		where storage_account_id = @storage_account_id

	end try

	begin catch
			
			declare @DBName nvarchar(128)
			
			set @DBName = db_name()
			set @log_type  = 
							case 
								when @log_type is null then 1
								else @log_type 
							end 
			set @response_code = 
							case 
								when @response_code is null then -200
								else @response_code 
							end 
			set @message = case 
								when @message is null then 'storage_account update failed'
								else @message 
							end
			
			exec usp_LogError @log_type, @ErrorDB = @DBName
			
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_insert_external_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_insert_external_message]
 
(
	@serial_number varchar(19),
	@offer_bundle varchar(20) = NULL,
	@creation_date datetime = NULL,
	@offer_bundle_request varchar(20) = NULL,
	@vendor_id varchar(5),
	@transaction_id varchar(50),
	@offer_bundle_details varchar(20) = NULL,
	@contract_id varchar(10),
	@message_type varchar(2),
	@association_code varchar(10) = NULL,
	@total_regular_price money = NULL,
	@total_renewal_price money = NULL,
	@process_response_code varchar(20) = NULL,
	@response_code int output, 
	@message varchar(100) output

)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-09	acoffel		Initial creation.
	2020-04-21	wbarton		Major refactor. This procedure now inserts records into subscription_update and subscription_update_json, after which they're processed syncronously or asyncronously by usp_subscription_update_external_message

	DESCRIPTION
	
*/

AS			

declare @start_date datetime,
		@cancel_date datetime,
		@current_contract_id varchar(10),
		@subscription_id int,
		@subscription_update_id int,
		@subscription_update_status_id int,
		@subscription_change_reason_id int,
		@subscription_update_json nvarchar(max),
		@process_flag bit

begin try

	set nocount on	
	select @response_code = 0

	select @subscription_change_reason_id = subscription_change_reason_id
	from subscription_change_reason
	where subscription_change_reason_name = 'Bundle'

	select @subscription_id = subscription_id, @start_date = start_date, @cancel_date = cancel_date, @current_contract_id = s.contract_id
	from subscription s
	where serial_number = @serial_number

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Validating inputs - keeping all the validation logic and error messaging as-is from prior to the refactor, however changing them syntactically for better performance and to set variables used in the JSON later on.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.1) No associated subscription_id
	if @subscription_id is null 
		begin 
			select @response_code = 05, @message = 'subscription_id does not exist', @process_flag = 1, @process_response_code = 'error 05'
			return @response_code
		end
	
	--1.2) Subscription not activated
	if @start_date is NULL or @start_date = ''
		begin
			select @response_code = 18, @message = 'subscription not activated', @process_flag = 1, @process_response_code = 'error 18B'
			goto inserts 
		end
	
	--1.3) Subscription already cancelled
	if @cancel_date < getdate() 
		begin
			select @response_code = 04, @message = 'subscription is already canceled', @process_flag = 1, @process_response_code = 'error 04B'
			goto inserts 
		end

	--1.4) contract_id does not match the current subscription record
	if @contract_id <> @current_contract_id
		begin
			select @response_code = 08, @message = 'subscription does not match contract_id', @process_flag = 1, @process_response_code = 'error 08'
			goto inserts 
		end
	
	--1.5) contract_id is associated with multiple subscriptions
	if (select count(subscription_id) from subscription with (nolock) where contract_id = @contract_id) > 1
		begin 
			select @response_code = 08, @message = 'subscription contract_id not unique', @process_flag = 1, @process_response_code = 'error 08'
			goto inserts 
		end

	--1.6) Invalid vendor_id or message_type
	if @vendor_id <> 'WBR00' or @message_type not in ('CR', 'CN', 'PR', 'OI')
		begin 
	
		select @response_code = 99, @message = 'subscription update not in scope', @process_flag = 1, @process_response_code = 'error 99'
			goto inserts 
		end

	--1.7) subscription_external record has already been created prior to the 'CR' (create) request
	if exists (select 1 from subscription_external where subscription_id = @subscription_id) and @message_type = 'CR'
		begin 
			select @response_code = 0, @message = '0 subscription external already exists', @process_flag = 1, @process_response_code = 'error 0 exists'
			goto inserts  
		end

	--1.8) subscription_external record has already been cancelled prior to the 'CN' (cancel) request
	if not exists (select 1 from subscription_external where subscription_id = @subscription_id) and @message_type = 'CN'
		begin 
			select @response_code = 0, @message = '0 subscription already canceled', @process_flag = 1, @process_response_code = 'error 0 canceled'
			goto inserts  
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Queue subscription_update and subscription_update_json
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	inserts: 
	
	set @subscription_update_json = (
		select 	@subscription_id as subscription_id, @serial_number as serial_number, @offer_bundle as offer_bundle, @creation_date as creation_date, @offer_bundle_request as offer_bundle_request, @vendor_id as vendor_id, @transaction_id as transaction_id, @offer_bundle_details as offer_bundle_details, @contract_id as contract_id, @message_type as message_type, @association_code as association_code, @total_regular_price as total_regular_price, @total_renewal_price as total_renewal_price, @process_flag as process_flag, @process_response_code as process_response_code
		for json path
	)

	select @subscription_update_status_id = subscription_update_status_id
	from subscription_update_status
	where subscription_update_status_name = 'pending'

	insert into subscription_update (subscription_id, subscription_change_reason_id, subscription_update_status_id, update_attempts)
	select @subscription_id, @subscription_change_reason_id, @subscription_update_status_id, 0

	set @subscription_update_id = scope_identity()

	insert into subscription_update_json (subscription_update_id, subscription_update_json)
	select @subscription_update_id, @subscription_update_json
			
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Syncronous processing of subscription_update_external_message if applicable
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
if exists (select 1 from subscription_change_reason where subscription_change_reason_id = @subscription_change_reason_id and process_type = 'synchronous')
	begin
		exec usp_subscription_update @subscription_update_id = @subscription_update_id
	end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--4.0) Return and failure management
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--If the request passed all of the validations in section 1, set @message for success back to the API
	if @response_code = 0
		begin
			set @message = 'subscription upda
ted'
		end

	return @response_code

end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'subscription_external_message_update failed @subscription_id = ' + isnull(convert(varchar(10),@subscription_id),'') else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_insert_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_insert_message]

(
	@subscription_update_json nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2011-09-18	esmart		Initial creation.
	2013-05-09	esmart		Suppress message for monthly plan skus
	2013-06-05	esmart		Enhancements
	2013-08-06	esmart		Fix double insert
	2018-02-09	esmart		Add logging
	2020-05-20	wbarton		Major refactor. This procedure is called asynchronously by usp_subscription_update

	DESCRIPTION
	
*/

AS

declare @subscription_message_id int,
		@current_promo_sku varchar(10), 
		@current_promo_type smallint,
		@last_modified_date datetime,
		@response_code int,
		@message varchar(100)

declare @subscription_message_update table (
	subscription_id int,
	contract_id varchar(10),
	promo_sku varchar(10),
	promo_price money,
	promo_start_date datetime,
	promo_end_date datetime,
	promo_type smallint
)


begin try 

	set nocount on

	select @last_modified_date = getdate()

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Extracting data from @subscription_update_json
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.1) Populate @subscription_message_update from @subscription_update_json
	insert into @subscription_message_update (subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type)
	select subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type
	from openjson(@subscription_update_json)
	with (
		subscription_id int '$.subscription_id',
		contract_id varchar(10) '$.contract_id',
		promo_sku varchar(10) '$.promo_sku',
		promo_price money '$.promo_price',
		promo_start_date datetime '$.promo_start_date',
		promo_end_date datetime '$.promo_end_date',
		promo_type smallint '$.promo_type'
	)

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Skip further processing in cases of bad data 
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.1) If the subscription is on a monthly plan - maintaining the '%monthly%' logic from prior to the refactor
	if exists (
		select 1
		from @subscription_message_update smu
			inner join subscription s
				on s.subscription_id = smu.subscription_id
			inner join subscription_plan_sku sps
				on sps.plan_sku = s.plan_sku
		where sps.plan_sku_description like '%monthly%'
	) begin
		return
	end

	--2.2) If the promo_sku is invalid
	if not exists (
		select 1 
		from @subscription_message_update u
			inner join subscription_promo_sku ps
				on ps.promo_sku = u.promo_sku
	) begin
		return
	end

	--2.3) If the promo_type is invalid
	if not exists (
		select 1
		from @subscription_message_update u
			inner join subscription_promo_type pt
				on pt.promo_type = u.promo_type
	) begin
		return
	end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Inserts and updates
---------------------------------------------------------------------------------------------------------------------------------------------
---------------------------------------------------------
	--3.1) Insert into subscription_message_log
	insert into dbo.subscription_message_log (subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type)
	select subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type
	from @subscription_message_update
	
	--3.2) Set current-state variables
	select @subscription_message_id = sm.subscription_message_id,
			@current_promo_sku = sm.promo_sku, 
			@current_promo_type = sm.promo_type
	from subscription_message sm
		inner join @subscription_message_update smu
			on smu.subscription_id = sm.subscription_id

	if @subscription_message_id is null
	--3.3) Insert subscription_message
		begin
			insert into subscription_message(subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type)
			select subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type
			from @subscription_message_update
		end
	else
	--3.4) Update as needed
		begin
			if exists (select 1 from @subscription_message_update where promo_sku <> @current_promo_sku or promo_type <> @current_promo_type)
			--3.4.1) archive and create new messages
				begin
					insert into subscription_message_archive(subscription_message_id, subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, last_modified_date, archive_date)
					select subscription_message_id, subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, last_modified_date, @last_modified_date
					from subscription_message
					where subscription_message_id = @subscription_message_id

					update sm 
					set sm.contract_id = smu.contract_id, sm.promo_sku = smu.promo_sku, sm.promo_price = smu.promo_price, sm.promo_start_date = smu.promo_start_date, sm.promo_end_date = smu.promo_end_date, sm.promo_type = smu.promo_type, sm.last_modified_date = @last_modified_date
					from subscription_message sm
						inner join @subscription_message_update smu
							on smu.subscription_id = sm.subscription_id
					where sm.subscription_message_id = @subscription_message_id
				end
		else
			--3.4.2) return no changes
			begin
				return
			end
		end
		
end try

begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert subscription message update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_select_by_keycode]
-- =============================================================================





CREATE PROCEDURE [dbo].[usp_subscription_select_by_keycode]

(
	@keycode varchar(20)
)

AS
/*	
		DATE			AUTHOR		REMARKS
		2008-05-14		isprod		Initial creation.
		2010-06-15		dsmelker	Added contract_detail_update to the select
		2011-10-21		esmart		Add subscription message data
		2012-01-12		esmart		Add license_keycode_alias lookup
		
		DESCRIPTION
	
*/

	set nocount on

	declare @license_id int

	select @license_id = license_id
	from license 
	where keycode = @keycode

	if @license_id is null
		begin
		select @license_id = license_id 
		from license_keycode_alias 
		where keycode_alias = @keycode
		end

	select distinct s.subscription_id,
			l.keycode,
			s.serial_number,
			st.subscription_type,
			CONVERT(varchar(10),s.start_date,101) as start_date,
			CONVERT(varchar(10),s.expiration_date,101) as expiration_date,
			CONVERT(varchar(10),s.cancel_date,101) as cancel_date,
			s.cancel_reason,
			pr.product_sku,
			pr.product_sku_opt_out,
			pl.plan_sku,
			pl.plan_sku_opt_out,
			s.contract_id,
			s.contract_detail_update,
			s.opt_status,
			m.promo_sku, 
			m.promo_price, 
			m.promo_start_date, 
			m.promo_end_date, 
			m.promo_type,
			a.keycode_alias
	from subscription (nolock) s
	inner join subscription_type (nolock) st
		on s.subscription_type_id=st.subscription_type_id
	left join subscription_plan_sku (nolock) pl
		on s.plan_sku = pl.plan_sku
	left join subscription_product_sku (nolock) pr
		on s.product_sku = pr.product_sku
	inner join license (nolock) l
		on l.license_id = s.license_id
	left join subscription_message (nolock) m
		on s.subscription_id = m.subscription_id
	left join license_keycode_alias (nolock) a
		on s.license_id = a.license_id
	where s.license_id = @license_id





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_select_by_serialnumber]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_select_by_serialnumber]

(
  @serialnumber varchar(20)
)

AS
/*  
		DATE			AUTHOR		REMARKS
		2008-05-15		isprod		Initial creation.
		2010-06-15		dsmelker	Added contract_detail_update to the select
		2010-08-13		dsmelker	Added opt_status
		2011-10-21		esmart		Add subscription message data
		2012-01-12		esmart		Add license_keycode_alias lookup
		2014-11-12		acoffel		tuning
		2015-02-24		acoffel		more tuning
		
		DESCRIPTION
  
*/

	set nocount on 

	begin try

	declare @serial_number_check varchar(20),
			@keycode varchar(40),
			@keycode_alias varchar(40),
			@license_id int,
			@response_code int,
			@message varchar(100)

			
	select @serial_number_check = serial_number from subscription with (nolock) where serial_number = @serialnumber

	if @serial_number_check is NULL
		begin 
			insert into DBErrorlog(Add_Date, ErrorNumber, ErrorSeverity, ErrorState, ErrorProcedure, ErrorLine, ErrorMessage, ErrorServer, ErrorDB, ErrorUser)
			values (getdate(), 1, 1, 1, 'usp_subscription_select_by_serialnumber', 37, @serialnumber, 'PRDDENECOM5', 'eCommerce', 'eComWebP')
		end

	--select @license_id = license_id from subscription with (nolock) where serial_number = @serialnumber

	--select @keycode = l.keycode, @keycode_alias = a.keycode_alias from license l with (nolock) left join license_keycode_alias a with (nolock) on l.license_id = a.license_id where l.license_id = @license_id 

	select distinct s.subscription_id,
			l.keycode,
			s.serial_number,
			st.subscription_type,
			CONVERT(varchar(10),s.start_date,101) as start_date,
			CONVERT(varchar(10),s.expiration_date,101) as expiration_date,
			CONVERT(varchar(10),s.cancel_date,101) as cancel_date,
			s.cancel_reason,
			pr.product_sku,
			pr.product_sku_opt_out,
			pl.plan_sku,
			pl.plan_sku_opt_out,
			s.contract_id,
			s.contract_detail_update,
			s.opt_status,
			m.promo_sku, 
			m.promo_price, 
			m.promo_start_date, 
			m.promo_end_date, 
			m.promo_type,
			isnull(a.keycode_alias,'') as keycode_alias
	from subscription s with (nolock)
	left join subscription_type st with (nolock)
		on s.subscription_type_id = st.subscription_type_id
	left join subscription_plan_sku pl with (nolock)
		on s.plan_sku = pl.plan_sku 
	left join subscription_product_sku pr with (nolock)
		on s.product_sku = pr.product_sku
	left join license l with (nolock)
		on l.license_id = s.license_id
	left join subscription_message m with (nolock)
		on s.subscription_id = m.subscription_id
	left join license_keycode_alias a with (nolock)
		on s.license_id = a.license_id
	where s.serial_number= @serialnumber


end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;





GO
