CREATE PROCEDURE [dbo].[usp_subscription_select_conversion_subscription]

(
	@conversion_serial_number varchar(19), 
	@conversion_contract_id varchar(10)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-10-16	esmart		Initial creation.

	DESCRIPTION
	select conversion subscription
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select sc.subscription_conversion_id, sc.conversion_serial_number, sc.conversion_contract_id, cs.subscription_conversion_status_id, cs.subscription_conversion_status, sc.insert_date, sc.modified_date, 
			s.subscription_id, s.serial_number, s.contract_id,
			l.license_id, l.keycode
	from subscription_conversion sc
	inner join subscription_conversion_status cs
		on sc.subscription_conversion_status_id = cs.subscription_conversion_status_id
	inner join subscription s
		on sc.subscription_id = s.subscription_id
	inner join license l
		on s.license_id = l.license_id
	where sc.conversion_serial_number = @conversion_serial_number and sc.conversion_contract_id = @conversion_contract_id
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_select_history]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_subscription_select_history]

(
	@subscription_id int
)

AS


/*	
	DATE			AUTHOR		REMARKS
	2008-09-24		esmart		Initial creation.
	2010-06-15		dsmelker	Added contract_detail_update
	2010-08-13		dsmelker	Added opt_status
	2011-10-21		esmart		Add subscription message data
		

	DESCRIPTION
	select union of subscription and subscription_history
	
*/

	set nocount on

	declare @subscription_history table (subscription_id int,subscription_type_id int,subscription_change_reason_name varchar(50),subscription_change_reason_id int,license_id int,serial_number varchar(19),start_date smalldatetime,cancel_reason varchar(40),cancel_date smalldatetime,insert_date smalldatetime,expiration_date smalldatetime,history_date datetime,history_by varchar(20),product_sku varchar(8),plan_sku varchar(8),contract_id varchar(10),contract_detail_update int,opt_status int,promo_sku varchar(10),promo_price money,promo_start_date datetime,promo_end_date datetime,promo_type smallint)

	-- 1.1) subscription_history
	insert into @subscription_history(subscription_id,subscription_type_id,subscription_change_reason_name,subscription_change_reason_id,license_id,serial_number,start_date,cancel_reason,cancel_date,insert_date,expiration_date,history_date,history_by,product_sku,plan_sku,contract_id,contract_detail_update,opt_status)
	select subscription_id, 
			subscription_type_id, 
			r.subscription_change_reason_name, 
			r.subscription_change_reason_id, 
			license_id, 
			serial_number, 
			start_date, 
			cancel_reason, 
			cancel_date, 
			h.insert_date, 
			expiration_date, 
			history_date, 
			history_by,
			product_sku,
			plan_sku,
			contract_id,
			contract_detail_update,
			h.opt_status
	from subscription_history h
	inner join subscription_change_reason r
		on h.subscription_change_reason_id = r.subscription_change_reason_id
	where subscription_id = @subscription_id
	order by history_date desc

	-- 1.2) subscription_message_history
	insert into @subscription_history(subscription_id,subscription_change_reason_name,subscription_change_reason_id,contract_id,promo_sku,promo_price,promo_start_date,promo_end_date,promo_type,history_date)
	select subscription_id,subscription_change_reason_name='Modify message',subscription_change_reason_id=4,contract_id,promo_sku,promo_price,promo_start_date,promo_end_date,promo_type,last_modified_date 
	from subscription_message	
	where subscription_id = @subscription_id 

	select * from @subscription_history order by history_date desc

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_select_profile]
-- =============================================================================

CREATE   PROCEDURE [dbo].[usp_subscription_select_profile] (@serial_number VARCHAR(19) = ''
                                                     , @keycode VARCHAR(40) = ''
                                                     , @contract_id VARCHAR(10) = ''
                                                     , @input_json NVARCHAR(4000) = NULL
                                                     , @message VARCHAR(100) = NULL OUTPUT
                                                     , @response_code INT = NULL OUTPUT
                                                    )
AS
    /*  
	DATE			AUTHOR			REMARKS
	2020-11-28		abelenkiy		Initial creation.
	2020-01-19		abelenkiy		Performance tuning on section 2.3
	2020-03-15		abelenkiy		Modified subscription_status return to evaluate cancel_reason and return "FailedAuth" when applicable
	2021-07-02		abelenkiy		Changed logic that evaluates subscription_status per BBY request
	2025-04-10		jberry			US-4459014 - Add AIP registration status and allstate registration date, some minor formatting changes
		
	DESCRIPTION
	Returns table and JSON output for BBY ResearchSubscription request. Procedure takes variables or JSON. Only one of the three values is required. 
	If a keycode alias is provided, a keycode is looked for in keycode_alias but the keycode returned (partnerSubscriptionCode) will be the keycode from the license table.
	The alias will be returned as keycode_alias but will not be used by the PHP for the response.

	This procedure will eventually replace other procedures that return the same information to PartnerCart and CSI. The additional fields being returned 
	but not used by the API serve that purpose. The two procedures to be replaced are below; thorough testing will need to be done to ensure all dependencies
	are cared for.
		usp_subscription_select_by_keycode
		usp_subscription_select_by_serialnumber


	INPUT JSON SCHEMA
	{ "$schema": "http://json-schema.org/draft-04/schema#", "type": "object", "description": "JSON schema for Best Buy /ResearchSubscription request",
	  "properties": {
		"serialNumber": {"type": "string", "minLength": 1, "maxLength": 19, "description": "Serial Number of the subscription product."},
		"partnerSubscriptionCode": {"type": "string", "minLength": 1, "maxLength": 40, "description": "A unique key code for the customer's subscription at each service level"},
		"bbyContractNumber": {"type": "string", "minLength": 1, "maxLength": 10, "description": "Contract number that's attached to the Customer''s subscription within Best Buy"}
	  }}

	SAMPLE JSON
	{"serialNumber":"","partnerSubscriptionCode":"SABDZDBB67DB0E552362",bbyContractNumber":""}

	RESPONSES
	CODE	DESCRIPTION
	0		Success.
	11 		Bad Request. Mandatory fields are missing.
	1001 	Invalid Contract ID/Serial Number/Partner Subscription Code

	ERROR HANDLING
	All three input fields are optional. If multiple inputs are provided and any one hits an error case, an error will be returned even if another field is valid.	

  
*/
    BEGIN TRY
        SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED

        SET NOCOUNT ON
        
        -- get license category list for Allstate products sold through Best Buy S2
        DECLARE @S2_ALLSTATE_LICENSE_CATEGORY TABLE
        (
            license_category_id INT,
            license_category_name VARCHAR(10)
        );
        INSERT INTO @S2_ALLSTATE_LICENSE_CATEGORY
        (
            license_category_id,
            license_category_name
        )
        SELECT f.[key],
               f.[value]
        FROM [dbo].[fn_app_config_select_key_values]('S2_ALLSTATE_LICENSE_CATEGORY', 'BBY_S2') f;
		
        --get license registration status
        DECLARE @allstate_r
egistration_status TABLE
        (
            license_id INT,
            allstate_registration_status_id INT,
            allstate_registration_status VARCHAR(20),
			allstate_registration_date datetime
        );

		-- 1) set variables if json was passed in
        declare
            @keycode_alias varchar(40), @license_id int

        if isjson(@input_json) = 1
            begin
                select @keycode = isnull(j.keycode, ''), @serial_number = isnull(j.serial_number, ''), @contract_id = isnull(j.contract_id, '')
                from openjson(@input_json) with (serial_number varchar(20) '$.serialNumber', keycode varchar(41) '$.partnerSubscriptionCode'
                          , contract_id varchar(11) '$.bbyContractNumber') j
            end

		-- 2) find license_id from provided inputs and handle errors
		-- 2.1) return if no values provided
        if concat(@keycode, @serial_number, @contract_id) = ''
            begin
                select @message = 'Bad Request. Mandatory fields are missing.', @response_code = 11
				RETURN
            END

		-- 2.2) look for keycode in license table
        if @keycode <> ''
            begin
                select @license_id = l.license_id
                from license l
                where l.keycode = @keycode

				-- 2.2.1) if not found, check keycode alias table
                IF @@rowcount = 0
                    BEGIN
                        select @license_id = lka.license_id, @keycode_alias = lka.keycode_alias, @keycode = lka.keycode
                        from license_keycode_alias lka
                        where lka.keycode_alias = @keycode

						-- 2.2.2) return if keycode not found in either table
                        IF @@rowcount = 0
                            BEGIN
                                select @message = 'Invalid Contract ID/Serial Number/Partner Subscription Code', @response_code = 1001
								RETURN
                            END
                    END
            END

		-- 2.3) if license_id found above, see if it matches license tied to other input params
		--      if license_id not found, find record based on other inputs
		if @serial_number <> '' or @contract_id <> ''-- skip this condition if only keycode was passed in and move on to select
			begin
				-- 2.3.1) license_id was found from passed in keycode
				if @license_id is not null
					begin
						if (@serial_number = '' 
							and not exists (select 1 from subscription s where s.license_id = @license_id and s.contract_id = @contract_id))
							or 
							(@contract_id = ''
							and not exists (select 1 from subscription s where s.license_id = @license_id and s.serial_number = @serial_number))
							or 
							(@contract_id <> '' and @serial_number <> ''
							and not exists (select 1 from subscription s where s.license_id = @license_id and s.serial_number = @serial_number and s.contract_id = @contract_id))
                            begin
                                select @message = 'Invalid Contract ID/Serial Number/Partner Subscription Code', @response_code = 1001
								RETURN
                            END
					END
				-- 2.3.2) keycode not passed in (invalid keycodes have already returned an error out in section 2.2.2)
				ELSE
					BEGIN
						if @serial_number = '' -- this condition is met when only the contract_id was passed in
							begin
								select @serial_number = s.serial_number
								from subscription s
								where s.contract_id = @contract_id
							end
						if @contract_id = '' -- this condition is met when only the serial_number was passed in
							begin
								select @contract_id = s.contract_id
								from subscription s
								where s.serial_number = @serial_number
							end
						select @license_id = s.license_id -- license_id is set from values set above and/or passed in; contract_id may be null 
						from subscription s
						where s.s
erial_number = @serial_number
							and isnull(s.contract_id, '') = isnull(@contract_id, '')

						IF @license_id IS NULL
							BEGIN
								select @message = 'Invalid Contract ID/Serial Number/Partner Subscription Code', @response_code = 1001
								RETURN
							END
					END
			END		

        -- 3) get allstate registration status	
        INSERT INTO @allstate_registration_status
        (
            license_id,
            allstate_registration_status_id,
            allstate_registration_status,
            allstate_registration_date
        )
        SELECT l.license_id, 
                ISNULL(sauc.allstate_registration_status_id, 0),
                ISNULL(ars.allstate_registration_status, 'Unregistered'),
                sauc.allstate_registration_date			   
        FROM dbo.license l
          INNER JOIN dbo.license_category_license lcl
            ON lcl.license_id = l.license_id
          JOIN dbo.subscription s
            ON s.license_id = l.license_id
          LEFT JOIN dbo.safe_account_user_customer sauc
            ON l.customer_id = sauc.customer_id
          LEFT JOIN dbo.allstate_registration_status ars
            ON ars.allstate_registration_status_id = sauc.allstate_registration_status_id
          INNER JOIN @S2_ALLSTATE_LICENSE_CATEGORY alc
            ON alc.license_category_id = lcl.license_category_id
        WHERE l.license_id = @license_id;        

        -- 4) select data if no error conditions are hit 
        SELECT DISTINCT
               s.subscription_id,
               s.contract_id,                                                                         -- bbyContractNumber
               s.serial_number,                                                                       -- serialNumber
               l.keycode,                                                                             -- partnerSubscriptionCode
               CASE
               WHEN s.cancel_reason = 210 THEN
                   'FailedAuth'
               WHEN s.cancel_reason IS NOT NULL THEN
                   'Cancelled'
               WHEN s.start_date IS NULL
               OR s.expiration_date < GETDATE() THEN
                   'Inactive'
               WHEN s.expiration_date > GETDATE()
                OR s.expiration_date IS NULL THEN
                   'Active'
               ELSE
                   'Inactive'
               END AS subscription_status,                                                            -- partnerSubscriptionStatus
               spp.subscription_partner_product_key,                                                  -- partnerServiceSku
               CONVERT(VARCHAR(10), s.start_date, 23) AS start_date,                                  -- startDate
               CONVERT(VARCHAR(10), s.expiration_date, 23) AS expiration_date,                        -- endDate
               CONVERT(VARCHAR(10), li.first_install_date, 23) AS first_install_date,                 -- redemptionDate
               IIF(li.first_install_date IS NULL, 'Not Installed', 'Installed') AS redemption_status, -- redemptionStatus
               CONVERT(VARCHAR(10), s.cancel_date, 23) AS cancel_date,                                -- cancellationDate
               s.cancel_reason,                                                                       -- cancelReasonCode
               pl.plan_sku,                                                                           -- bbyPlanSku 
               s.product_sku,                                                                         -- bbyProductSku
               CASE
               WHEN st.subscription_type_id = 1 THEN
                   'Monthly'
               WHEN st.subscription_type_id = 2 THEN
                   'Annual'
               ELSE
                   'Inactive'
               END AS subscription_type,                                                              -- partne
rSubscriptionService
               s.contract_detail_update,                                                              -- contractUpdateCode
               m.promo_sku,
               m.promo_price,
               m.promo_start_date,
               m.promo_end_date,
               m.promo_type,
               pl.plan_sku_opt_out,
               @keycode_alias AS keycode_alias,
               ars.allstate_registration_status_id,
               ars.allstate_registration_status,
               ars.allstate_registration_date
        FROM dbo.subscription s
          LEFT JOIN dbo.subscription_type st
            ON s.subscription_type_id = st.subscription_type_id
          LEFT JOIN dbo.subscription_plan_sku pl
            ON s.plan_sku = pl.plan_sku
          LEFT JOIN dbo.license l
            ON l.license_id = s.license_id
          LEFT JOIN dbo.subscription_message m
            ON s.subscription_id = m.subscription_id
          LEFT JOIN dbo.license_install li
           ON li.license_id = l.license_id
          LEFT JOIN dbo.subscription_partner_product spp
            ON spp.subscription_partner_product_id = s.subscription_partner_product_id
          LEFT JOIN @allstate_registration_status ars
            ON ars.license_id = l.license_id
        WHERE l.license_id = @license_id;

        SELECT @message = 'Success', @response_code = 0

    end try
    begin catch

		select @response_code = 99, @message = error_message()
		raiserror(@message, 16, 1)

    end catch;




GO
