-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_select_transaction_history]

(
	@license_id int = null,
	@subscription_id int = null
)

AS

/*	
	DATE		AUTHOR			REMARKS
	2020-08-20	wbarton			Initial creation

	DESCRIPTION
	Procedure returns a tabular view of transactions processed via subscription_update architecture
*/

begin try

----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Establish variables and working tables
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
declare @serial_number varchar(19), @loop_value int, @loop_max int, @processing_json nvarchar(max), @columns nvarchar(max) = '', @sql nvarchar(max), @id varchar(5)

create table #transactions (
	id int identity(1,1),
	subscription_update_archive_id int,
	archive_date datetime,
	subscription_change_reason_name varchar(50),
	subscription_update_json nvarchar(max)
)

create table #transaction_history (
	id int identity(1,1),
	license_id int,
	subscription_id int,
	serial_number varchar(19),
	subscription_update_archive_id int,
	archive_date datetime,
	subscription_change_reason_name varchar(50),
	subscription_type_id int,
	start_date datetime,
	cancel_reason varchar(40),
	cancel_date datetime,
	expiration_date datetime,
	product_sku varchar(8),
	plan_sku varchar(8),
	contract_id varchar(10),
	contract_detail_update int,
	promo_sku varchar(10),
	promo_price money,
	promo_start_date datetime,
	promo_end_date datetime,
	promo_type smallint,
	creation_date datetime,
	vendor_id varchar(20),
	transaction_id varchar(max),
	message_type varchar(2),
	association_code varchar(10),
	total_regular_price money,
	total_renewal_price money,
	process_flag bit,
	process_response_code varchar(20)
)

----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Set variables based on what was passed into the procedure
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
if @license_id is null and @subscription_id is null
	begin
		return
	end
else if @license_id is not null
	begin
		select @subscription_id = subscription_id 
		from subscription with (nolock)
		where license_id = @license_id
	end
else 
	begin
		select @license_id = license_id 
		from subscription with (nolock)
		where subscription_id = @subscription_id
	end

select @serial_number = serial_number 
from subscription s with (nolock)
where subscription_id = @subscription_id

----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Populate json data for transaction history
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
insert into #transactions(subscription_update_archive_id, archive_date, subscription_change_reason_name, subscription_update_json)
select a.subscription_update_archive_id, a.archive_date, r.subscription_change_reason_name, cj.[value]
from subscription_update_archive a with (nolock)
	inner join subscription_update_json j with (nolock)
		on j.subscription_update_id = a.subscription_update_id
	inner join subscripti
on_change_reason r
		on r.subscription_change_reason_id = a.subscription_change_reason_id
	cross apply openjson(j.subscription_update_json) cj
where a.subscription_update_status_id = 2 --processed
	and a.subscription_id = @subscription_id
	and cj.[type] = 5
order by a.subscription_update_archive_id asc

----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Parse json data into a tabular format
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
select @loop_value = (select min(id) from #transactions), @loop_max = (select max(id) from #transactions)
while @loop_value <= @loop_max
	begin
		select @processing_json = subscription_update_json 
		from #transactions
		where id = @loop_value

		select @columns += quotename([key]) + ','
		from (
			select * from openjson(@processing_json)
		) j
		set @columns = left(@columns, len(@columns) - 1)
		set @id = cast(@loop_value as varchar(10))

		set @sql = '
		insert into #transaction_history ('+ @columns +')
		select '+ @columns +' from   
		(
			select [key], [value] from openjson((select subscription_update_json from #transactions where id = '+@id+'))
		) t 
		pivot(
			max([value]) 
			for [key] in ('+ @columns +')
		) as pivot_table
		'
		exec sp_executesql @sql

		update th 
		set th.license_id = @license_id, th.subscription_id = @subscription_id, th.subscription_update_archive_id = t.subscription_update_archive_id, th.archive_date = t.archive_date, th.subscription_change_reason_name = t.subscription_change_reason_name
		from #transactions t
			inner join #transaction_history th
				on th.id = t.id
		where t.id = @loop_value

		update #transaction_history
		set serial_number = @serial_number
		where serial_number is null

		select @processing_json = null,  @columns = '', @loop_value = @loop_value + 1
	end

----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--Return
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
select license_id, subscription_id, serial_number, subscription_update_archive_id, archive_date, subscription_change_reason_name, subscription_type_id, start_date, cancel_reason, cancel_date, expiration_date, product_sku, plan_sku, contract_id, contract_detail_update, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, creation_date, message_type, association_code, total_regular_price, total_renewal_price, process_response_code
from #transaction_history
order by subscription_update_archive_id asc

end try

begin catch

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_update]

(
	@subscription_update_id int
)

AS

/*	
	DATE		AUTHOR			REMARKS
	2020-04-16	wbarton			Initial creation - combining functionality from various subscription management procedures, and utilizing license service
	2020-07-08	wbarton			4.1 - setting expiration_date on subscription to null for non-annual subscriptions. This matches behavior prior to the refactor.
	2020-08-04	wbarton			Added section 4.3.1 to handle subscription_message inserts/updates for contract_detail_update = 5
	2020-10-16	wbarton			Adding subscription_update_json validation and handling to section 1
	2021-08-04	abelenkiy		Updated section 2.6 to set all renewal and activation expiration dates on annual subscriptions 15 years out

	DESCRIPTION
	Procedure handles Best Buy S2 subscription management
*/

declare 
		@modified_date datetime,
		@modified_by varchar(20),
		@activation_date datetime,
		@license_id int,
		@license_seats int,
		@license_change_reason_id int,
		@license_category_id tinyint,
		@license_category_name varchar(10),
		@storage_gb int,
		@license_status_id int,
		@keycode varchar(40),
		@service_json nvarchar(max),
		@account_name varchar(20),
		@module_product_id int,
		@loop_value int,
		@loop_max int,
		@subscription_update_json nvarchar(max),
		@subscription_change_reason_id int,
		@expiration_date datetime,
		@response_code int,
		@message varchar(100)

declare @subscription_update table (
	subscription_id int,
	subscription_type_id int,
	start_date datetime,
	expiration_date datetime,
	product_sku varchar(8),
	plan_sku varchar(8),
	contract_id varchar(10), 
	cancel_date datetime,
	cancel_reason varchar(40),
	contract_detail_update int,
	opt_status int
)

declare @results table (
	response_code int, 
	message varchar(100)
)

declare @license_modules table (
	id int identity(1,1), 
	module_product_id int
)

begin try

	set nocount on
	select @modified_by = suser_sname(), @modified_date = getdate(), @account_name = 's2_api'
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Extracting data from the subscription_update and subscription_update_json record
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	select @subscription_change_reason_id = subscription_change_reason_id
	from subscription_update
	where subscription_update_id = @subscription_update_id
	
	set @subscription_update_json = (
		select subscription_update_json 
		from subscription_update_json
		where subscription_update_id = @subscription_update_id
	)

	--In rare edge cases the asynchronous batch job can attempt to process a subscription_update record before a subscription_update_json record gets inserted. Catching those instances here, otherwise they hit the catch section.  
	if @subscription_update_json is null
		begin
			update subscription_update
			set update_attempts = update_attempts + 1, process_date = dateadd(minute, 30, getdate())
			where subscription_update_id = @subscription_update_id

			if exists (select 1 from subscription_update where subscription_update_id = @subscription_update_id and update_attempts > 3)
				begin
					insert into dbo.subscription_update_failure (subscription_update_id, subscription_id, subscription_change_reason_id, subscription_update_status_id, insert_date, failure_date, failure_reason)
					select subscription_update_id, subscription_id, @subscription_change_reason_id, 3, insert_date, getdate
(), 'missing subscription_update_json'
					from subscription_update 
					where subscription_update_id = @subscription_update_id

					delete from subscription_update
					where subscription_update_id = @subscription_update_id
				end
			return
		end

	--For AssociationBundleOffer, subscription_change_reason_id 5, call usp_subscription_update_external_message to handle subscription_message and subscription_external_message_update inserts
	if @subscription_change_reason_id = 5
		begin
			exec usp_subscription_update_external_message @subscription_update_json = @subscription_update_json
			goto queue_management
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Establishing license, change, and date variables
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.1) parse @subscription_update_json
	insert into @subscription_update (subscription_id, subscription_type_id, start_date, expiration_date, product_sku, plan_sku, contract_id, cancel_date, cancel_reason, contract_detail_update)
	select subscription_id, subscription_type_id, start_date, expiration_date, product_sku, plan_sku, contract_id, cancel_date, cancel_reason, contract_detail_update
	from openjson(@subscription_update_json)
	with (
		subscription_id int '$.subscription_id',
		subscription_type_id int '$.subscription_type_id',
		start_date datetime '$.start_date',
		expiration_date datetime '$.expiration_date',
		product_sku varchar(8) '$.product_sku',
		plan_sku varchar(8) '$.plan_sku',
		contract_id varchar(10) '$.contract_id',
		cancel_date datetime '$.cancel_date',
		cancel_reason varchar(40) '$.cancel_reason',
		contract_detail_update int '$.contract_detail_update'
	)
	
	--2.2) Establish license variables
	select @license_id = s.license_id, @keycode = l.keycode, @license_status_id = l.license_status_id, @license_seats = ls.license_seats
	from @subscription_update su
		inner join subscription s
			on s.subscription_id = su.subscription_id
		inner join license l
			on l.license_id = s.license_id
		left join license_seat ls
			on ls.license_id = l.license_id
	
	--2.3) Setting @license_change_reason_id for use in subroutines
	select @license_change_reason_id = case
		when @subscription_change_reason_id = 1 then 22	--BBY Activation
		when @subscription_change_reason_id = 2 then 23	--BBY Renewal
		when @subscription_change_reason_id = 3 then 24 --BBY Cancel
		else 21 --BBY Maintenance
		end

	--2.4) Establish category and date variables
	select @license_category_id = lc.license_category_id, @license_category_name = p.license_category_name, @activation_date = p.start_date
	from fn_license_select_license_profile(@license_id) p
		inner join license_category lc
			on lc.license_category_name = p.license_category_name
	where p.item_hierarchy_id = 1

	--2.5) Activation-specific variables: @opt_status
	if @subscription_change_reason_id = 1 
		begin
			update su 
			set su.opt_status = sps.plan_sku_opt_out
			from @subscription_update su
				inner join dbo.subscription_plan_sku sps
					on sps.plan_sku = su.plan_sku
		end

	--2.6) Activations and renewals 
	if @subscription_change_reason_id in (1,2) 
		begin
			--if the subscription is not annual, set expiration date 5762 days into the future
			--historical business logic was to set expiration date 15+ years out for activations and 5 years out for renewals:
			--	iif(@subscription_change_reason_id = 1, dateadd(day, 5762, @modified_date), dateadd(day, 1825, @modified_date))
			--logic changed in 08-2021 due to issue where subscriptions renewed 5 years ago were expiring; now both renewals and 
			--activations will be set out 5762 days
			upda
te @subscription_update
			set expiration_date = dateadd(day, 5762, @modified_date)
			where (subscription_type_id <> 2 or subscription_type_id is null)

			--opt_status. This is consistent with our historical business logic
			update @subscription_update
			set contract_detail_update = iif(opt_status = 0, 3, 4)
			where opt_status is not null

			--For all activations and renewals, set expiration_date time to 23:59, cancel_date and cancel_reason null
			update @subscription_update
			set expiration_date = dateadd(mi, -1, convert(smalldatetime, convert(date, dateadd(dd, 1, expiration_date)))), cancel_date = null, cancel_reason = null
		end

	--2.7) Cancels
	if @subscription_change_reason_id = 3
		begin
			--setting cancel_date time to 23:59
			update @subscription_update
			set cancel_date = dateadd(mi, -1, convert(smalldatetime, convert(date, dateadd(dd, 1, cancel_date))))
		end

	--2.8) Contract detail updates: setting opt_status. This is consistent with our historical business logic
	if @subscription_change_reason_id = 4
		begin
			update @subscription_update
			set opt_status = case when contract_detail_update = 3 then 0 when contract_detail_update = 4 then 1 else opt_status end

			--setting cancel_date time to 23:59 if it's present in the contract detail update request - commenting out because it's not part of the existing processing prior to the re-factor
			--update @subscription_update
			--set cancel_date = dateadd(mi, -1, convert(smalldatetime, convert(date, dateadd(dd, 1, cancel_date))))
			--where cancel_date is not null
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Managing license category and seats to maintain compatiblity for legacy bulk loads
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------		
	--3.1) Compatibility for legacy bulk loads and licenses that pre-date the current S2 configuration
	if not exists (select 1 from subscription_license_category_module_configuration where license_category_id = @license_category_id)
		begin
			select @license_category_id = (select top 1 license_category_id 
				from subscription_license_category_module_configuration
				where is_default = 1
				order by subscription_license_category_module_configuration_id)
			select @license_category_name = license_category_name
			from license_category
			where license_category_id = @license_category_id

			--Inserting the return into a table variable to prevent output to the API for cases on synchronous processing
			insert into @results (response_code, message)
			exec usp_license_update_license_category @license_id = @license_id, @license_category_id = @license_category_id, @license_change_reason_id = @license_change_reason_id, @modified_by = @account_name, @order_item_id = null
		end

	--3.2) Defaulting license_seats for legacy bulk load licenses that do not yet have a license_seat record
	if @license_seats < (select top 1 license_seats from subscription_license_category_module_configuration where is_default = 1 order by subscription_license_category_module_configuration_id)
		begin
			select @license_seats = (select top 1 license_seats 
				from subscription_license_category_module_configuration 
				where license_category_id = @license_category_id 
				order by subscription_license_category_module_configuration_id)
		end
	
	if @license_seats is null
		begin
			select @license_seats = (select top 1 license_seats 
				from subscription_license_category_module_configuration 
				where license_category_id = @license_category_id 
				order by subscription_license_category_module_configuration_id)

				insert into license_seat (license_id, license_seats)
			
	select @license_id, @license_seats
		end		
				
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--4.0) Subscription data
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	--4.1) update subscription: activations, renewals, and cancels - keeping the subscription update before the history insert to maintain legacy order of operations.
	if @subscription_change_reason_id in (1,2,3)
		begin 
			update s
			set s.start_date = iif(su.start_date is null, s.start_date, su.start_date),
				s.subscription_type_id = iif(su.subscription_type_id is null, s.subscription_type_id, su.subscription_type_id),
				s.expiration_date = iif(su.expiration_date is null, s.expiration_date, iif(su.subscription_type_id = 2, su.expiration_date, null)), --for renewals and activations, setting expiration_date to null for non-annual subscription_type_ids
				s.product_sku = iif(su.product_sku is null, s.product_sku, su.product_sku),
				s.plan_sku = iif(su.plan_sku is null, s.plan_sku, su.plan_sku),
				s.contract_id = su.contract_id, --contract_id is always included in the JSON
				s.cancel_reason = su.cancel_reason, --cancel_reason should be overridden by null
				s.cancel_date = su.cancel_date, --cancel_date should be overridden by null
				s.last_modified_date = @modified_date,
				s.last_modified_by = @modified_by,
				s.contract_detail_update = iif(su.contract_detail_update is null, s.contract_detail_update, su.contract_detail_update),
				s.opt_status = iif(su.opt_status is null, s.opt_status, su.opt_status)
			from @subscription_update su
				inner join subscription s
					on s.subscription_id = su.subscription_id
		end

	--4.2) insert subscription_history
	insert into subscription_history (subscription_id, subscription_type_id, license_id, serial_number, start_date, cancel_reason, cancel_date, subscription_change_reason_id, insert_date, expiration_date, history_date, history_by, product_sku, plan_sku, contract_id,contract_detail_update,opt_status)
	select s.subscription_id, s.subscription_type_id, s.license_id, s.serial_number, s.start_date, s.cancel_reason, s.cancel_date, @subscription_change_reason_id, s.insert_date, s.expiration_date, history_date = @modified_date, history_by = @modified_by, s.product_sku, s.plan_sku, s.contract_id, s.contract_detail_update, s.opt_status
	from subscription s
		inner join @subscription_update su
			on su.subscription_id = s.subscription_id
	
	--4.3) update subscription: contract detail update - keeping the history insert before the subscription update to maintain legacy order of operations (unique to contract detail updates).
	if @subscription_change_reason_id = 4
		begin				
			update s
			set contract_id = su.contract_id, 
				contract_detail_update = su.contract_detail_update, 
				cancel_date = iif(su.cancel_date is null, s.cancel_date, su.cancel_date), 
				opt_status = iif(su.opt_status is null, s.opt_status, su.opt_status),
				last_modified_date = @modified_date,
				last_modified_by = @modified_by
			from @subscription_update su
				inner join subscription s
					on s.subscription_id = su.subscription_id

			--4.3.1 Calling usp_subscription_insert_message for instances of contract_detail_update 5
			if exists (select 1 from @subscription_update where contract_detail_update = 5)
				begin
					exec usp_subscription_insert_message @subscription_update_json = @subscription_update_json
				end
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--5.0) License management
-------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------------------------	
	--5.1) Setting @expiration_date, which will be used in the following license service calls
	--When the request is for a contract detail update, and it carries a cancel_date, @expiration_date is set to 30 days out from the cancel_date. This logic was previously in usp_subscription_update_contract_detail.
	select @expiration_date = iif(su.cancel_date is null, su.expiration_date, iif(@subscription_change_reason_id = 4, dateadd(day, 30, su.cancel_date), su.cancel_date))
	from @subscription_update su

	if @expiration_date is null
		begin
			--Skip license management if dates are not changing
			goto queue_management
		end
	
	--5.2) Activation
	if @activation_date is null or @license_status_id <> 1
		begin
			select @service_json = (
				select @keycode as keycode, @account_name as account_name, @license_category_name as [license_category.license_category_name], @expiration_date as [license_category.expiration_date], @license_seats as [license_category.license_seats]
				for json path, without_array_wrapper
			)

			exec usp_license_service_insert_service @license_service_type_name = 'license_enable', @service_json = @service_json, @return_license_service_id = 0

		end
	else
	--5.3) Renewal
		begin
			select @service_json = (
				select @keycode as keycode, @account_name as account_name, @license_category_name as [license_category.license_category_name], @expiration_date as [license_category.expiration_date], @license_seats as [license_category.license_seats]
				for json path, without_array_wrapper
			)
			exec usp_license_service_insert_service @license_service_type_name = 'license_update', @service_json = @service_json, @return_license_service_id = 0

		end

	--5.4) Establishing the proper modules on a license for cases where the license does not yet carry the correct configuration, and when existing modules need to have end dates updated
	insert into @license_modules (module_product_id)
	select sc.product_id
	from subscription_license_category_module_configuration sc
	where sc.license_category_id = @license_category_id

	if exists (select 1 from @license_modules)
		begin
			select @loop_value = 1, @loop_max = (select max(id) from @license_modules)
			while @loop_value <= @loop_max
				begin
					select @module_product_id = module_product_id
					from @license_modules
					where id = @loop_value

					exec usp_license_update_license_module_license @license_id = @license_id, @product_id = @module_product_id, @license_change_reason_id = @license_change_reason_id, @module_end_date = @expiration_date, @modified_by = @account_name
				
					select @module_product_id = null, @loop_value = @loop_value + 1
				end
		end

	--5.5) license_storage 
	if exists (select 1 from license_storage where license_id = @license_id)
		begin
			select @storage_gb = storage_gb
			from license_storage
			where license_id = @license_id

			exec usp_license_update_license_storage @license_id = @license_id, @storage_gb = @storage_gb, @license_change_reason_id = @license_change_reason_id, @order_item_id = null, @response_code = @response_code output, @message = @message output
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--6.0) Queue management
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	queue_management:

	insert into subscription_update_archive (subscription_update_id, subscription_id, subscription_change_reason_id, subscription_update_status_id, insert_date)
	select subscription_update_id, subscription_id, subscrip
tion_change_reason_id, 2, insert_date
	from subscription_update
	where subscription_update_id = @subscription_update_id

	delete from subscription_update
	where subscription_update_id = @subscription_update_id

end try

begin catch
	
	insert into dbo.subscription_update_failure (subscription_update_id, subscription_id, subscription_change_reason_id, subscription_update_status_id, insert_date, failure_date, failure_reason)
	select subscription_update_id, subscription_id, @subscription_change_reason_id, 3, insert_date, getdate(), error_message() 
	from subscription_update 
	where subscription_update_id = @subscription_update_id

	update subscription_update
	set update_attempts = update_attempts + 1, process_date = dateadd(minute, 30, getdate())
	where subscription_update_id = @subscription_update_id

	if exists (select 1 from subscription_update where subscription_update_id = @subscription_update_id and update_attempts > 3)
		begin
			delete from subscription_update
			where subscription_update_id = @subscription_update_id
		end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_update_activate]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_update_activate]

(
	@subscription_id int, 
	@start_date datetime,
	@subscription_type_id int,
	@expiration_date datetime,
	@subscription_change_reason_id int,
	@product_sku varchar(8),
	@plan_sku varchar(8),
	@contract_id varchar(10),
	@response_code int output,
	@message varchar(100) output
)

AS

/*	
	DATE		AUTHOR			REMARKS
	2008-05-15	isprod			Initial creation.
	2008-07-06  jsilverthorn	I updated the proc to assign the subscription type.  
								This is necessary so that Best Buy subscriptions will be
								in an inactive state until they are activated after the point
								of sale (through this stored procedure).
	2008-09-23	esmart			Add subscription_history and try/catch
	2009-12-08	esmart			Alter procedure to include license_capability updates
	2010-05-08	esmart			Added reactivation of license status
	2010-06-15	dsmelker		Added contract_detail_update to the insert into subscription_history
	2010-06-16	dsmelker		Added response codes of 16 and 17 and modified 9 and 10 to 14 and 15
	2010-06-21	dsmelker		Added 9 and 10 back in and have the procedure error out if 9 or 10 are reached
	2010-08-13	dsmelker	 	Added Opt_Status
	2010-11-18	esmart			Add messaging subroutine
	2011-08-31	esmart			Remove buffer days for Secure Anywhere licenses (1.15)
	2011-10-06	esmart			Add update to license status from pending to active
	2012-07-26	esmart			Add upgraded modules for BBY 2013
	2012-09-06	esmart			Add seat update for 1 to 3
	2012-10-08	esmart			Update upgrade to WSAI, and supress errors 16 and 17
	2013-10-15	esmart			Add upgrade for SysAnalyzer 2014
	2014-01-08	esmart			Add new module product for system analyzer for Geeksquad
	2014-03-24	acoffel			Pushed new AR sub dates out to 2030
	2015-02-13	acoffel			added set contract_detail_update -- 2.0.1)
	2016-05-16	blu				Set expiration_date time to 23:59.
	2017-06-23	esmart			Remove direct insert into prevx_license_update
	2018-09-19	acoffel			check cancel setting
	2020-03-06	wbarton			Removing @buffer_days from the expiration date setting logic so dates are consistent regardless of product_line_id. @buffer_days was previously used to add 31 days to the date provided by Best Buy, when product_line_id <> 100.
	2020-04-06	wbarton			For PHP7 - standardizing all validations with an un-commented return, so we set @response_code to the return value. Also commenting out the logging insert for '05 Invalid/unrecognized SN', which will always fail.
	2020-04-16	wbarton			Major refactor. This procedure now inserts records into subscription_update and subscription_update_json, after which they're processed syncronously or asyncronously by usp_subscription_update

	DESCRIPTION
	Procedure handles Best Buy S2 activations and renewals
*/

declare 
		@subscription_update_id int,
		@subscription_update_status_id int,
		@subscription_update_json nvarchar(max)

begin try

	set nocount on
	set @response_code = 0

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Queue subscription_update and subscription_update_json records
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set @subscription_update_json = (
		select 	@subscription_id as subscription_id, @start_date as start_date, @subscription_type_id as subscription_type_id, @expiration_date as expiration_date, @product_sku as product_sku, @plan_sku as plan_sku, @contract_id as contract_id
		for json path
	)

	select @subscriptio
n_update_status_id = subscription_update_status_id
	from subscription_update_status
	where subscription_update_status_name = 'pending'

	insert into subscription_update (subscription_id, subscription_change_reason_id, subscription_update_status_id, update_attempts)
	select @subscription_id, @subscription_change_reason_id, @subscription_update_status_id, 0

	set @subscription_update_id = scope_identity()

	insert into subscription_update_json (subscription_update_id, subscription_update_json)
	select @subscription_update_id, @subscription_update_json

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Validating Inputs
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.1) A license doesn't exist associated with the subscription_id passed-in
	if not exists (select 1 from subscription where subscription_id = @subscription_id)
		begin
			select @response_code = 5, @message = '05 Invalid/unrecognized SN'
			goto return_section
		end

	--2.2) product_sku validation
	if @product_sku is not null and @product_sku <> '' and @subscription_change_reason_id = 1
		begin
			if not exists (select 1 from subscription_product_sku where product_sku = @product_sku)
				begin
					select @response_code = 9, @message = '09 Invalid/unrecognized Product SKU'
					goto return_section
				end
		end

	--2.3) plan_sku validation
	if @plan_sku is not null and @plan_sku <> '' and @subscription_change_reason_id = 1
		begin
			if not exists (select 1 from subscription_plan_sku where plan_sku = @plan_sku)
				begin
					select @response_code = 10, @message = '10 Invalid/unrecognized Plan SKU'
					goto return_section
				end
		end
	
	--2.4) subscription_type_id validation
	if not exists (select 1 from subscription_type where subscription_type_id = @subscription_type_id) 
		begin
			select @response_code = -120, @message = '@subscription_type_id ' + convert(varchar(20),@subscription_type_id) + ' is not valid'
			goto return_section
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Syncronous processing of subscription updates
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
if exists (select 1 from subscription_change_reason where subscription_change_reason_id = @subscription_change_reason_id and process_type = 'synchronous')
	begin
		exec usp_subscription_update @subscription_update_id = @subscription_update_id
	end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--4.0) Return and failure management
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	return_section:
	--If the request passed all of the validations in section 2, set @message for success back to the API
	if @response_code = 0
		begin
			set @message = 'Subscription updated'
		end
	--Otherwise insert into the failure table, and remove the record from queue
	else
		begin
			select @subscription_update_status_id = subscription_update_status_id
			from subscription_update_status
			where subscription_update_status_name = 'failed'

			insert into subscription_update_failure (subscription_update_id, subscription_id, subscripti
on_change_reason_id, subscription_update_status_id, failure_reason)
			select subscription_update_id, subscription_id, subscription_change_reason_id, @subscription_update_status_id, @message
			from subscription_update
			where subscription_update_id = @subscription_update_id

			delete from subscription_update
			where subscription_update_id = @subscription_update_id
		end

	return @response_code

end try
begin catch

	set @response_code = case when @response_code is null then -200 else @response_code end
	set @message = case when @message is null then 'subscription update failed for: @subscription_id = ' + isnull(convert(varchar(10),@subscription_id),'') else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_update_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_update_batch]

(
	@batch_size int
)

AS

/*	
	DATE		AUTHOR			REMARKS
	2020-04-17	wbarton			Initial creation - processing batches of subscription updates via usp_subscription_update

	DESCRIPTION
	Procedure handles Best Buy S2 subscription management batch processing
*/

declare 
		@loop_value int,
		@loop_max int,
		@subscription_update_id int

declare @subscription_updates table (
	id int identity(1,1),
	subscription_update_id int
)

begin try

	set nocount on
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Select the batch, favoring subscription_change_reason_id order
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	insert into @subscription_updates (subscription_update_id)
	select top(@batch_size) subscription_update_id 
	from subscription_update
	where process_date <= getdate()
	order by subscription_change_reason_id, process_date asc

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Loop over the batch and process each record
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------	
	select @loop_value = (select min(id) from @subscription_updates), @loop_max = (select max(id) from @subscription_updates)
	while @loop_value <= @loop_max
		begin
			select @subscription_update_id = subscription_update_id 
			from @subscription_updates
			where id = @loop_value

			exec usp_subscription_update @subscription_update_id = @subscription_update_id

			select @subscription_update_id = null, @loop_value = @loop_value + 1
		end

end try

begin catch
	
	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
