-- =============================================================================


CREATE PROCEDURE [dbo].[usp_subscription_update_cancel]

(
	@subscription_id int, 
	@cancel_date datetime,
	@cancel_reason varchar(40),
	@contract_id varchar(10),
	@response_code int output,
	@message varchar(100) output
)

AS

/*	
	DATE		AUTHOR		REMARKS
	2008-05-15	isprod		Initial creation.
	2008-09-23	esmart		Add subscription_history and try/catch
	2010-06-15	dsmelker	Added contract_detail_update to the insert into subscription_history
	2010-08-13	dsmelker	Added opt_status to the insert into subscription_history
	2010-12-07	esmart		Removed 30 day extension for soft cancel and removed 1.3) validate cancel_reason
	2011-10-11	esmart		Update license status 
	2014-03-21	acoffel		set up to process future cancel dates
	2016-05-16	blu			Set cancel_date time to 23:59.
	2017-06-23	esmart		Remove direct insert into prevx_license_update
	2020-04-20	wbarton		Major refactor. This procedure now inserts records into subscription_update and subscription_update_json, after which they're processed syncronously or asyncronously by usp_subscription_update

	DESCRIPTION
*/

declare @subscription_change_reason_id int,
		@subscription_update_status_id int,
		@current_contract_id varchar(10),
		@subscription_update_id int,
		@subscription_update_json nvarchar(max)

begin try

	set nocount on
	set @response_code = 0

	select @subscription_change_reason_id = subscription_change_reason_id
	from subscription_change_reason
	where subscription_change_reason_name = 'Cancel'

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Queue subscription_update and subscription_update_json records
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	set @subscription_update_json = (
		select 	@subscription_id as subscription_id, @cancel_date as cancel_date, @cancel_reason as cancel_reason, @contract_id as contract_id
		for json path
	)

	select @subscription_update_status_id = subscription_update_status_id
	from subscription_update_status
	where subscription_update_status_name = 'pending'

	insert into subscription_update (subscription_id, subscription_change_reason_id, subscription_update_status_id, update_attempts)
	select @subscription_id, @subscription_change_reason_id, @subscription_update_status_id, 0

	set @subscription_update_id = scope_identity()

	insert into subscription_update_json (subscription_update_id, subscription_update_json)
	select @subscription_update_id, @subscription_update_json

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Validating inputs
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--2.1) validate @subscription_id
	if not exists (select 1 from subscription where subscription_id = @subscription_id)
		begin
			--Keeping this as response_code -100 since that's what the procedure has been doing historically
			select @response_code = -100, @message = '@subscription_id ' + convert(varchar(20),@subscription_id) + ' is not valid'
			--commenting out the subscription_cancel_error_log insert - this will always fail the foreign key constraint since the subscription_id doesn't exist on subscription
			--insert into subscription_cancel_error_log(subscriptio
n_id, cancel_date, cancel_reason, response_code, message)
			--values(@subscription_id, @cancel_date, @cancel_reason, @response_code, @message)
			return -100
		end
	
	-- 2.2) @contract_id
	select @current_contract_id = s.contract_id
	from subscription s
	where s.subscription_id = @subscription_id

	if @current_contract_id is not null and @contract_id <> @current_contract_id
		begin
			--select response_code = 8, @message = '8 ContractID supplied in request does not match ContractID associated with SN'
			insert into subscription_cancel_error_log(subscription_id, cancel_date, cancel_reason, response_code, message)
			values(@subscription_id, @cancel_date, @cancel_reason, 8, '8 ContractID supplied in request does not match ContractID associated with SN')
			--return 8
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Syncronous processing of subscription updates
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
if exists (select 1 from subscription_change_reason where subscription_change_reason_id = @subscription_change_reason_id and process_type = 'synchronous')
	begin
		exec usp_subscription_update @subscription_update_id = @subscription_update_id
	end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--4.0) Return and failure management
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	return_section:
	--If the request passed all of the validations in section 2, set @message for success back to the API
	if @response_code = 0
		begin
			set @message = 'Subscription updated'
		end
	--Otherwise insert into the failure table, and remove the record from queue
	else
		begin
			select @subscription_update_status_id = subscription_update_status_id
			from subscription_update_status
			where subscription_update_status_name = 'failed'

			insert into subscription_update_failure (subscription_update_id, subscription_id, subscription_change_reason_id, subscription_update_status_id, failure_reason)
			select subscription_update_id, subscription_id, subscription_change_reason_id, @subscription_update_status_id, @message
			from subscription_update
			where subscription_update_id = @subscription_update_id

			delete from subscription_update
			where subscription_update_id = @subscription_update_id
		end

	return @response_code

end try
begin catch

	set @response_code = case when @response_code is null then -200
						else @response_code end
	set @message = case when @message is null then 'subscription update failed @subscription_id = ' + isnull(convert(varchar(10),@subscription_id),'')
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
