-- =============================================================================


CREATE PROCEDURE [dbo].[usp_subscription_update_conversion_subscription]

(
	@subscription_conversion_id int,
	@subscription_conversion_status varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-10-16	esmart		Initial creation.

	DESCRIPTION
	update conversion subscription
*/

AS
	set nocount on				

	declare	@subscription_conversion_status_id tinyint,
			@current_subscription_conversion_status_id tinyint,
			@modified_date datetime,
			@response_code int,
			@message varchar(100)

	begin try

	select @modified_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @subscription_conversion_status_id
	select @subscription_conversion_status_id = subscription_conversion_status_id
	from subscription_conversion_status
	where subscription_conversion_status = @subscription_conversion_status

	-- 1.2) @current_subscription_conversion_status_id
	select @current_subscription_conversion_status_id = subscription_conversion_status_id
	from subscription_conversion
	where subscription_conversion_id = @subscription_conversion_id
	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @current_subscription_conversion_status_id < @subscription_conversion_status_id
		begin
		update subscription_conversion
		set subscription_conversion_status_id = @subscription_conversion_status_id, modified_date = @modified_date
		where subscription_conversion_id = @subscription_conversion_id
		end
	
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
