-- PROCEDURE: [dbo].[usp_subscription_update_external_message]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_subscription_update_external_message]
 
(
		@subscription_update_json nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2015-01-09	acoffel		Initial creation.
	2015-02-24	acoffel		Sorted out error codes and extended OI and PR requests into process
	2015-03-16	acoffel		added additional error handling
	2015-03-31	acoffel		added additional pricing options
	2020-04-22	wbarton		Major refactor. This procedure is called by usp_subscription_update to handle inserts and updates in subscription_message and subscription_external_message_update. Keeping the business logic for the inserts and updates as it was. Error handling has been moved upstream to usp_subscription_insert_external_message.

	DESCRIPTION
	Procedure handles Best Buy S2 subscription_message and subscription_external_message_update
*/

AS
			
declare @contract_id varchar(10),
		@serial_number varchar(19),
		@subscription_id int,
		@promo_amount int,
		@response_code int,
		@message varchar(100),
		@process_flag bit,
		@subscription_external_message_update_id int,
		@message_type varchar(2)

declare @subscription_external_message_update table (
	serial_number varchar(19),
	subscription_id int,
	offer_bundle varchar(20),
	creation_date datetime,
	offer_bundle_request varchar(20),
	vendor_id varchar(5),
	transaction_id varchar(50),
	offer_bundle_details varchar(20),
	contract_id varchar(10),
	message_type varchar(2),
	association_code varchar(10),
	total_regular_price money,
	total_renewal_price money,
	process_response_code varchar(20),
	process_flag bit
)

begin try

	set nocount on
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--1.0) Extracting data from @subscription_update_json, setting initial variables, and initial insert to subscription_external_message_update
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	--1.1) Populate @subscription_external_message_update from @subscription_update_json
	insert into @subscription_external_message_update (serial_number, subscription_id, offer_bundle, creation_date, offer_bundle_request, vendor_id, transaction_id, offer_bundle_details, contract_id, message_type, association_code, total_regular_price, total_renewal_price, process_response_code, process_flag)
	select serial_number, subscription_id, offer_bundle, creation_date, offer_bundle_request, vendor_id, transaction_id, offer_bundle_details, contract_id, message_type, association_code, total_regular_price, total_renewal_price, process_response_code, process_flag
	from openjson(@subscription_update_json)
	with (
		serial_number varchar(19) '$.serial_number',
		subscription_id int '$.subscription_id',
		offer_bundle varchar(20) '$.offer_bundle',
		creation_date datetime '$.creation_date',
		offer_bundle_request varchar(20) '$.offer_bundle_request',
		vendor_id varchar(5) '$.vendor_id',
		transaction_id varchar(50) '$.transaction_id',
		offer_bundle_details varchar(20) '$.offer_bundle_details',
		contract_id varchar(10) '$.contract_id',
		message_type varchar(2) '$.message_type',
		association_code varchar(10) '$.association_code',
		total_regular_price money '$.total_regular_price',
		total_renewal_price money '$.total_renewal_price',
		process_response_code varchar(20) '$.process_response_code',
		process_flag bit '$.process_flag'
	)

	--1.2) Key variables
	select @promo_amount = cast(total_regular_price - total_renewal_price as int), @message_type = message_
type, @process_flag = process_flag
	from @subscription_external_message_update

	--1.3) subscription_external_message_update insert
	insert into subscription_external_message_update (serial_number, subscription_id, offer_bundle, creation_date, offer_bundle_request, vendor_id, transaction_id, offer_bundle_details, contract_id, message_type, association_code, total_regular_price, total_renewal_price, process_response_code, process_flag)
	select serial_number, subscription_id, offer_bundle, creation_date, offer_bundle_request, vendor_id, transaction_id, offer_bundle_details, contract_id, message_type, association_code, total_regular_price, total_renewal_price, process_response_code, process_flag
	from @subscription_external_message_update

	set @subscription_external_message_update_id = scope_identity()

	--1.4) Return if process_flag was already set to 1 by the error handling in usp_subscription_insert_external_message
	if @process_flag = 1
		begin
			return
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--2.0) Opt-in: 'OI'
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @message_type = 'OI'
		begin
			--2.1) Update the subscription record for the opt-in event
			select @serial_number = serial_number, @contract_id = contract_id 
			from @subscription_external_message_update
			
			exec usp_subscription_update_contract_detail @serial_number = @serial_number, @contract_id = @contract_id, @contract_detail_update = 3, @response_code = @response_code output, @message = @message output

			--2.2) Update status in subscription_external_message_update
			update subscription_external_message_update
			set process_flag = 1, process_response_code = 'OI complete' 
			where subscription_external_message_update_id = @subscription_external_message_update_id

			--2.3) Keeping legacy direct-queue inserts for explicit campaign management. This can be revisited later
			insert into license_check_update_license (license_id, source, insertdate)
			select s.license_id, 10, getdate()
			from @subscription_external_message_update u
				inner join subscription s
					on s.subscription_id = u.subscription_id
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--3.0) Promo: 'PR'
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @message_type = 'PR'
		begin
			--3.1) Update the subscription_message record if one already exists
			if exists (select 1 from subscription_message m inner join @subscription_external_message_update u on u.subscription_id = m.subscription_id)
				begin
					update m 
					set m.promo_sku = k.promo_sku, m.promo_price = u.total_renewal_price, m.promo_type = '1001'
					from @subscription_external_message_update u
						inner join subscription_message m
							on m.subscription_id = u.subscription_id
						inner join subscription_promo_sku k
							on @promo_amount = k.promo_sku and k.promo_amount <> 0
				end
			else 
			--3.2) Or insert a new record
				begin
					insert into subscription_message (subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, last_modified_date)
					select s.subscription_id, s.contract_id, k.promo_sku, u.total_renewal_price, getdate(), s.expiration_date, '1001', getdate()
					from subscription s
						inner join @subscription_external_message_update u
							on u.subscription_id = s.subsc
ription_id
						inner join subscription_promo_sku k
							on @promo_amount = k.promo_amount and k.promo_amount <> 0
				end
			
			--3.3) Update status in subscription_external_message_update
			update subscription_external_message_update
			set process_flag = 1, process_response_code = 'PR complete'
			where subscription_external_message_update_id = @subscription_external_message_update_id
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--4.0) Create: 'CR' - load records in subscription_external and subscription message
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @message_type = 'CR'
		begin
			--4.1) Insert a record into subscription_external and subscription_message if the subscription is not yet in subscription_external
			if not exists (select 1 from subscription_external e inner join @subscription_external_message_update u on u.subscription_id = e.subscription_id)
				begin
					insert into subscription_external(subscription_id, subscription_customer_id, subscription_type_id, serial_number, contract_id, start_date, expiration_date, last_modified_date, last_modified_by) 
					select s.subscription_id, 0, 10, s.serial_number, s.contract_id, getdate(), s.expiration_date, getdate(), suser_sname()
					from subscription s
						inner join @subscription_external_message_update u
							on u.subscription_id = s.subscription_id

					insert into subscription_message (subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, last_modified_date, subscription_external_id)
					select s.subscription_id, s.contract_id,
						case when u.total_renewal_price = 119.98 then '4026448' when u.total_renewal_price = 129.98 then '4026218' else '4789612' end,
						u.total_renewal_price, getdate(), s.expiration_date, '2001', getdate(), e.subscription_external_id
					from subscription s
						inner join @subscription_external_message_update u
							on u.subscription_id = s.subscription_id
						inner join subscription_external e
							on e.subscription_id = u.subscription_id
				end

			--4.4) Update status in subscription_external_message_update
			update subscription_external_message_update
			set process_flag = 1, process_response_code = 'CR complete'
			where subscription_external_message_update_id = @subscription_external_message_update_id

			--4.5) Keeping legacy direct-queue inserts for explicit campaign management. This can be revisited later
			insert into license_message_update_license (license_id)
			select s.license_id
			from @subscription_external_message_update u
				inner join subscription s
					on u.subscription_id = s.subscription_id

			insert into license_check_update_license (license_id, source, insertdate)
			select s.license_id, 0, getdate()
			from @subscription_external_message_update u
				inner join subscription s
					on s.subscription_id = u.subscription_id
		end

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
--5.0) Cancel: 'CN' - archive and delete subscription_external and subscription_message records
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @message_type = 'CN'
		begin
			--5.1) insert into subscription_external_history
			insert into subscription_external_history (subscription_external_id, subscription_id, subscription_customer_id, subscription_type_id, serial_number, contract_id, sta
rt_date, expiration_date, last_usage_date, last_modified_date, last_modified_by)
			select distinct e.subscription_external_id, s.subscription_id, 0, s.subscription_type_id, e.serial_number, s.contract_id, e.start_date, e.expiration_date, e.last_usage_date, e.last_modified_date, e.last_modified_by
			from @subscription_external_message_update u
				inner join subscription s 
					on u.subscription_id = s.subscription_id
				inner join subscription_external e
					on s.subscription_id = e.subscription_id

			-- 5.2) insert into subscription_message_archive
			insert into subscription_message_archive (subscription_message_id, subscription_id, contract_id, promo_sku, promo_price, promo_start_date, promo_end_date, promo_type, last_modified_date, archive_date)
			select m.subscription_message_id, s.subscription_id, s.contract_id, m.promo_sku, m.promo_price, m.promo_start_date, m.promo_end_date, m.promo_type, m.last_modified_date, getdate()
			from subscription_message m
				inner join subscription s
					on m.subscription_id = s.subscription_id 
				inner join @subscription_external_message_update u 
					on s.subscription_id = u.subscription_id
				inner join subscription_external e
					on s.subscription_id = e.subscription_id

			--5.3) delete from subscription_external
			delete e
			from @subscription_external_message_update u
				inner join subscription_external e
					on u.subscription_id = e.subscription_id

			--5.4) delete subscription message
			delete m
			from @subscription_external_message_update u
				inner join subscription_message m
					on m.subscription_id = u.subscription_id

			--5.5) Update status in subscription_external_message_update
			update subscription_external_message_update
			set process_flag = 1, process_response_code = 'CN complete'
			where subscription_external_message_update_id = @subscription_external_message_update_id			

			--5.6) Keeping legacy direct-queue inserts for explicit campaign management. This can be revisited later
			insert into license_message_update_license (license_id)
			select s.license_id
			from @subscription_external_message_update u
				inner join subscription s
					on u.subscription_id = s.subscription_id

			insert into license_check_update_license (license_id, source, insertdate)
			select s.license_id, 0, getdate()
			from @subscription_external_message_update u
				inner join subscription s
					on s.subscription_id = u.subscription_id
		end
	
end try

begin catch

	set @response_code = -200
	set @message = case when @message is null then 'subscription_external_message_update failed @subscription_id = ' + isnull(convert(varchar(10),@subscription_id),'') else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
		
end catch;




GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_subscription_update_time]
-- =============================================================================
/*
	DATE		AUTHOR		REMARKS
	2016-06-20	blu			Initial creation.

	DESCRIPTION
	Updates subscription and license_capability times to 23:59.
*/

CREATE PROCEDURE [dbo].[usp_subscription_update_time]
(
	@batch_size int,		--batch size to update in ecomm
	@prevx_batch_size int,	--batch size to load prevx_update queue
	@delay_time int			--number of minutes to stagger prevx_update queue
)
as
set nocount on
begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) Licenses to update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	create table #update (
		license_id int
	)

	declare @date date,
		@max_date date

	select @date = min(cancel_date)
	from subscription with (nolock)
	where cancel_date >= convert(date, getdate())
		and datepart(hh, cancel_date) <> 23

	select @date = isnull(iif(min(expiration_date) < @date, min(expiration_date), @date), min(expiration_date))
	from subscription with (nolock)
	where expiration_date >= convert(date, getdate())
		and datepart(hh, expiration_date) <> 23

	select @max_date = dateadd(dd, 10, @date)
	
	insert into #update
	select top (@batch_size) license_id
	from subscription with (nolock)
	where (datepart(hh, expiration_date) <> 23 or datepart(hh, cancel_date) <> 23)
		and (convert(date, cancel_date) between @date and @max_date or convert(date, expiration_date) between @date and @max_date)
	order by license_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) Update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	update s
	set s.cancel_date = dateadd(mi, -1, dateadd(dd, 1, dateadd(dd, 0, datediff(dd, 0, s.cancel_date)))),
		s.expiration_date = dateadd(mi, -1, dateadd(dd, 1, dateadd(dd, 0, datediff(dd, 0, s.expiration_date))))
	from #update u
	inner join subscription s
		on u.license_id = s.license_id

	update lc
	set lc.capability_expiration_date = dateadd(mi, -1, dateadd(dd, 1, dateadd(dd, 0, datediff(dd, 0, lc.capability_expiration_date))))
	from license_capability lc
	inner join #update u
		on lc.license_id = u.license_id
	where lc.capability_expiration_date is not null
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) Load prevx_update queue
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	declare @min_id int = 1,
		@max_id int,
		@max_process_date datetime
	
	select @max_id = (@batch_size/iif(@prevx_batch_size > @batch_size, @batch_size, @prevx_batch_size)) + 1

	while @min_id <= @max_id
	begin
		select @max_process_date = isnull(max(process_date), getdate())
		from prevx_update
		where prevx_update_type_id = 2

		insert into prevx_update (
			license_id,
			prevx_update_type_id,
			prevx_update_status_id,
			update_attempts,
			insert_date,
			modified_date,
			process_date
		)
		select top (@prevx_batch_size) license_id,
			2,
			0,
			0,
			getdate(),
			getdate(),
			dateadd(mi, @delay_time, @max_process_date)
		from #update
		order by license_id

		set @min_
id += 1

		delete from #update
		where license_id in (
			select top (@prevx_batch_size) license_id
			from #update
			order by license_id
		)
	
	end

end try
begin catch

	print 'update failed'

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch

GO
