-- PROCEDURE: [dbo].[usp_sugarsync_insert_account_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sugarsync_insert_account_update]

(
		@account_id int,
		@sugarsync_update_type_id tinyint, 
		@sugarsync_update_status_id tinyint,
		@plan_code varchar(10),
		@process_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2010-04-01	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@insert_date datetime,
			@response_code int,
			@message varchar(100)

	select @response_code = 0,
			@insert_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @process_date
	if @process_date is null
		begin
		select @process_date = @insert_date
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into sugarsync_update(account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, insert_date, modified_date, process_date)
	values(@account_id, @sugarsync_update_type_id, @sugarsync_update_status_id, @plan_code, @insert_date, @insert_date, @process_date)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_select_create_account_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sugarsync_select_create_account_update]

(
		@account_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	select @response_code = 0

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select l.sugarsync_update_id, 
			a.account_user_name,
			a.account_password,
			l.plan_code,
			c.first_name,
			c.last_name
	from sugarsync_update l
	inner join account a
		on l.account_id = a.account_id
	left join account_customer ac
		on a.account_id = ac.account_id
	left join customer c
		on ac.customer_id = c.customer_id
	where l.account_id = @account_id and sugarsync_update_status_id in (0,2) and sugarsync_update_type_id in (1,9)

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select update account failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_select_next_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sugarsync_select_next_update]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-02	esmart		Initial creation.
	2010-08-17	esmart		Exclude the RenameSuspendService update type

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try
	
	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select top 1 u.sugarsync_update_id, a.account_id, a.account_user_name, a.account_password, t.sugarsync_update_type_id, t.sugarsync_update_type_name, u.process_date, u.plan_code
	from sugarsync_update u
	inner join sugarsync_update_type t
		on u.sugarsync_update_type_id = t.sugarsync_update_type_id
	inner join account a
		on u.account_id = a.account_id
	where u.sugarsync_update_type_id <> 13 and 
			u.sugarsync_update_status_id in (0,2) and u.process_date <= @batch_limit_date and u.modified_date <= @batch_limit_date
	order by process_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_select_update_batch]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sugarsync_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2010-04-02	esmart		Initial creation.
	2010-08-17	esmart		Exclude the RenameSuspendService update type

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- TODO validate of process date so if an update does occur we do a double check

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select batch_count = count(*), batch_limit_date = getdate()
	from sugarsync_update
	where sugarsync_update_type_id <> 13 and 
			sugarsync_update_status_id in (0,2) and process_date <= getdate()

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_select_update_history]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sugarsync_select_update_history]

(
	@account_id int
)
	
/*	
	DATE		AUTHOR		REMARKS
	2010-04-12	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select source = 'archive', sugarsync_update_archive_id, sugarsync_update_id, account_id, t.sugarsync_update_type_id, t.sugarsync_update_type_name, s.sugarsync_update_status_id, s.sugarsync_update_status_name, plan_code, status_code, update_attempts, insert_date, modified_date, process_date
	from sugarsync_update_archive a
	inner join sugarsync_update_type t
		on a.sugarsync_update_type_id = t.sugarsync_update_type_id
	inner join sugarsync_update_status s
		on a.sugarsync_update_status_id = s.sugarsync_update_status_id
	where a.account_id = @account_id 
	union 
	select source = 'queue', sugarsync_update_archive_id = 0, sugarsync_update_id, account_id, t.sugarsync_update_type_id, t.sugarsync_update_type_name, s.sugarsync_update_status_id, s.sugarsync_update_status_name, plan_code, status_code, update_attempts, insert_date, modified_date, process_date 
	from sugarsync_update u
	inner join sugarsync_update_type t
		on u.sugarsync_update_type_id = t.sugarsync_update_type_id
	inner join sugarsync_update_status s
		on u.sugarsync_update_status_id = s.sugarsync_update_status_id
	where account_id = @account_id 
	order by sugarsync_update_id, modified_date

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_update_account_reconciliation]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_sugarsync_update_account_reconciliation]

(
	@account_user_name varchar(100),
	@plan_code varchar(50), 
	@status varchar(20), 
	@create_date datetime, 
	@used_storage bigint, 
	@total_storage bigint
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-04	esmart		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@account_id int,
			@sugarsync_reconciliation_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	select @sugarsync_reconciliation_id = sugarsync_reconciliation_id
	from sugarsync_reconciliation
	where account_user_name = @account_user_name

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert or update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @sugarsync_reconciliation_id is null
		-- 2.1) insert account data
		begin
			-- 2.1.1) check account_user_name
			select @account_id = account_id 
			from account
			where account_user_name = @account_user_name
	
			if @account_id is not null
			-- 2.1.2) insert new record
				begin
				insert into sugarsync_reconciliation(account_id, account_user_name, plan_code, status, create_date, used_storage, total_storage)
				values(@account_id, @account_user_name, @plan_code, @status, @create_date, @used_storage, @total_storage)
				end
		end
	else
		-- 2.2) update account data
		begin
			-- 2.2.1) check account_user_name
			select @account_id = account_id 
			from account
			where account_user_name = @account_user_name
	
			if @account_id is not null
			-- 2.2.2) insert new record
				update sugarsync_reconciliation
				set account_id = @account_id,
					plan_code = @plan_code, 
					status = @status, 
					create_date = @create_date, 
					used_storage = @used_storage, 
					total_storage = @total_storage, 
					last_update_date = getdate()
				where account_user_name = @account_user_name
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sugarsync_update_account_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_sugarsync_update_account_update]

(
		@sugarsync_update_id int,
		@status_code varchar(25)
)

/*	
	DATE		AUTHOR		REMARKS
	2009-05-18	esmart		Initial creation.
	2010-08-17	esmart		Add support for RenameSuspendService

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@sugarsync_update_status_id tinyint,
			@current_sugarsync_update_status_id tinyint,
			@sugarsync_update_type_id tinyint,
			@account_id int,
			@update_attempts tinyint,
			@new_sugarsync_update_type_id tinyint,
			@capability_expiration_date datetime,
			@plan_code varchar(10),
			@process_date datetime,
			@storage_plan_code varchar(10),
			@response_code int,
			@message varchar(100)

	declare @account_message_type_id tinyint,
			@account_message_name varchar(20),
			@image_url varchar(200),
			@bold_text_value varchar(500),
			@text_value varchar(500),
			@button_text varchar(100),
			@button_url varchar(200),
			@sort_order tinyint,
			@start_date datetime,
			@end_date datetime

	select @response_code = 0

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select @sugarsync_update_type_id
	select @sugarsync_update_status_id = case when @status_code = 'SUCCESS' then 1 else 2 end

	-- 1.2) get update attempts
	select @update_attempts = update_attempts + 1,
			@current_sugarsync_update_status_id = sugarsync_update_status_id,
			@sugarsync_update_type_id = sugarsync_update_type_id,	
			@account_id = account_id,
			@plan_code = plan_code
	from sugarsync_update
	where sugarsync_update_id = @sugarsync_update_id

	if @current_sugarsync_update_status_id in (1,3)
		begin
		select @response_code = -120, @message = 'No update on processed or abandoned updates'
		select response_code = @response_code, [message] = @message
		return
		end

	-- 1.3) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @sugarsync_update_status_id = 2 -- failed
		begin
		select @sugarsync_update_status_id = 3 -- abandoned
		end

--	select sugarsync_update_status_id = @sugarsync_update_status_id, update_attempts = @update_attempts

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

--sugarsync_update_status_id	sugarsync_update_status_name
--0	Pending
--1	Processed
--2	Failed
--3	Abandoned

	-- 2.1) Processed
	if @sugarsync_update_status_id  = 1
		begin
		-- 2.1.1) insert archive record
		--print('2.1.1')
		insert into sugarsync_update_archive(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
		select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, @status_code, @update_attempts, insert_date, modified_date = getdate(), process_date
		from sugarsync_update
		where sugarsync_update_id = @sugarsync_update_id

		-- 2.1.2) delete update record
		delete
		from sugarsync_update
		where sugarsync_update_id = @sugarsync_
update_id
	
		select @response_code = 0, @message = 'Update processed'	
		end
	
	-- 2.2) Failure
	if @sugarsync_update_status_id = 2
		begin
--		print('2.2')
			-- 2.1) log failure
			insert into sugarsync_update_failure(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
			select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, @status_code, @update_attempts, insert_date, modified_date = getdate(), process_date
			from sugarsync_update
			where sugarsync_update_id = @sugarsync_update_id
	
			-- 2.2.2) update queue
			update sugarsync_update 
			set sugarsync_update_status_id = @sugarsync_update_status_id,
				update_attempts = @update_attempts,
				status_code = @status_code,
				modified_date = getdate(),
				process_date = case
								when sugarsync_update_type_id = 11 then dateadd(dd,3,process_date) -- UpdatePlanDowngrade
								else  dateadd(mi,5,process_date)
							end
			where sugarsync_update_id = @sugarsync_update_id

			-- 2.2.3) check to see if we need to add a message
			if @status_code = 'STORAGE_UPDATE_REQUIRED' --and @update_attempts = 1
				begin

				select    @account_message_type_id = 1
						  ,@account_message_name = 'MSG1'
						  ,@image_url = 'http://www.webroot.com/En_US/img_content/exclamation-point.png'
						  ,@bold_text_value = 'Your online storage usage is over your plan limit'
						  ,@text_value = 'You requested a new product or storage plan.  Please remove folders from synchronization'
						  ,@button_text = 'Help'
						  ,@button_url = '???'
						  ,@sort_order = 1
						  ,@start_date = getdate()
						  ,@end_date = null

				exec usp_account_insert_account_message @account_id,@account_message_type_id,@account_message_name,@image_url,@bold_text_value,@text_value,@button_text,@button_url,@sort_order,@start_date,@end_date
				end

			-- 2.2.4) set 
			select @response_code = -220, @message = 'Update failed'
		end
	
	-- 2.3) Abandoned
	if @sugarsync_update_status_id = 3
		begin
			-- 2.3.1) insert archive record
			--print('2.3.1')
			insert into sugarsync_update_archive(sugarsync_update_id, account_id, sugarsync_update_type_id, sugarsync_update_status_id, plan_code, status_code, update_attempts, insert_date, modified_date, process_date)
			select sugarsync_update_id, account_id, sugarsync_update_type_id, @sugarsync_update_status_id, plan_code, @status_code, @update_attempts, insert_date, modified_date = getdate(), process_date
			from sugarsync_update
			where sugarsync_update_id = @sugarsync_update_id

			-- 2.3.2) delete update record
			delete
			from sugarsync_update
			where sugarsync_update_id = @sugarsync_update_id
		
			-- 2.3.3) if abandoning a UpdatePlanDowngrade update type create EndServiceRecreate
			if @sugarsync_update_type_id = 11
				begin
				select @storage_plan_code = convert(varchar(8),storage_gb)+'GB'
				from license_storage s
				inner join account_license l
					on s.license_id = l.license_id
				where l.account_id = @account_id

				select @new_sugarsync_update_type_id = 12, @process_date = getdate()

				exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_type_id, 0, @storage_plan_code, @process_date
				end
		
			-- 2.3.4) if abandoning a SuspendService update type and @status_code = 'ACCOUNT_ALREADY_DISABLED' insert EndService
			if @sugarsync_update_type_id = 6 and @status_code = 'ACCOUNT_ALREADY_DISABLED'
				begin
				select @storage_plan_code = convert(varchar(8),storage_gb)+'GB'
				from license_storage s
				inner join account_license l
					on s.license_id = l.license_id
				where l.account_id = @account_id

				select @new_sugarsync_update_type_id = 7, @process_date = dateadd(dd,45,getdate())

				exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_
type_id, 0, @storage_plan_code, @process_date
				end
		
			-- 2.3.5) if abandoning a SuspendService update type and @status_code = 'ACCOUNT_ALREADY_EXIST' insert SuspendService
			if @sugarsync_update_type_id in (1,9) and @status_code = 'ACCOUNT_ALREADY_EXIST'
				begin
				select @storage_plan_code = convert(varchar(8),storage_gb)+'GB'
				from license_storage s
				inner join account_license l
					on s.license_id = l.license_id
				where l.account_id = @account_id

				select @capability_expiration_date = capability_expiration_date 
				from license_capability c
				inner join account_license l
					on c.license_id = l.license_id
				where l.account_id = @account_id and capability_id = 1

				select @new_sugarsync_update_type_id = 6, @process_date = @capability_expiration_date

				exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_type_id, 0, @storage_plan_code, @process_date
				end

			select @response_code = -230, @message = 'Update abandoned'	
		end

	-- 2.2) update license
	if @sugarsync_update_type_id in (1,9) and @status_code = 'Success'
		begin
		exec usp_account_insert_license_update_queue @account_id, 11
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set up next queue transaction
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	if @response_code = 0 and @status_code = 'Success' and @sugarsync_update_type_id <> 13
		begin
	
		-- 3.1) get expiration date for license
		--print('3.1')
		select @capability_expiration_date = capability_expiration_date 
		from license_capability c
		inner join account_license l
			on c.license_id = l.license_id
		where l.account_id = @account_id and capability_id = 1

		-- 3.2) get @storage_plan_code
		--print('3.2')
		select @storage_plan_code = convert(varchar(8),storage_gb)+'GB'
		from license_storage s
		inner join account_license l
			on s.license_id = l.license_id
		where l.account_id = @account_id

		-- 3.2) determine next update type
			if @sugarsync_update_type_id = 1 or
				@sugarsync_update_type_id = 8 or
				@sugarsync_update_type_id = 9 or
				@sugarsync_update_type_id = 10 or
				@sugarsync_update_type_id = 11
			--print('3.2.1')
			-- 3.2.1) insert deactivate record
				begin
					select @new_sugarsync_update_type_id = 6
					select @process_date = @capability_expiration_date
					exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_type_id, 0, @storage_plan_code, @process_date
				end

			if @sugarsync_update_type_id = 6 
			--print('3.2.2')
			-- 3.2.2) insert delete record
				begin
					select @new_sugarsync_update_type_id = 7
					select @process_date = dateadd(dd,45,getdate())
					exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_type_id, 0, @storage_plan_code, @process_date
				end

			if @sugarsync_update_type_id = 12 
			--print('3.2.3')
			-- 3.2.3) insert delete record
				begin
					select @new_sugarsync_update_type_id = 9
					select @process_date = dateadd(mi,5,getdate())
					exec usp_sugarsync_insert_account_update @account_id, @new_sugarsync_update_type_id, 0, @storage_plan_code, @process_date
				end
		end

		select response_code = @response_code, [message] = @message 
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_sweepstakes_insert_registration]
-- =============================================================================

CREATE PROCEDURE dbo.usp_sweepstakes_insert_registration

(
		@sweepstakes_id int,
		@customer_id int,
		@order_header_id int,
		@dob datetime,
		@phone_number varchar(64)
		
)

/*	
	DATE		AUTHOR		REMARKS
	2009-11-02	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare @response_code int,
			@message varchar(100),
			@current_phone_number varchar(64)
		


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) validate inputs
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.0) existing registration
		select @response_code =  case when count(*) = 1 then -100 else 0	 end,
			@message = case when count(*) = 1 then 'customer already registered for sweepstakes' else '' end
		from sweepstakes_registration
		where customer_id = @customer_id and sweepstakes_id = @sweepstakes_id and order_header_id = @order_header_id

		if @response_code < 0 	
			begin
				select response_code = @response_code, message = @message
				return
			end	
			
	-- 1.1) @customer_id
		select @response_code =  case when count(*) = 0 then -110 else 0	 end,
			@message = case when count(*) = 0 then '@customer_id not valid' else '' end
		from customer
		where customer_id = @customer_id

		if @response_code < 0 	
			begin
				select response_code = @response_code, message = @message
				return
			end

	-- 1.2) @dob
		if @dob is null or @dob = ''	
			begin
				select @response_code = -120,
						@message = '@dob must be valid'
				--RAISERROR (@message, 11, 0)
			end

	-- 1.3) @current_phone_number
		select @current_phone_number = phone_number
		from customer_phone
		where customer_id = @customer_id and phone_type_id = 1

	-- 1.4) @sweepstakes_id
		select @response_code =  case when count(*) = 0 then -140 else 0	 end,
			@message = case when count(*) = 0 then '@sweepstakes_id not valid' else '' end
		from sweepstakes
		where sweepstakes_id = @sweepstakes_id

		if @response_code < 0 	
			begin
				select response_code = @response_code, message = @message
				return
			end

	-- 1.5) @order_header_id
		select @response_code =  case when count(*) = 0 then -150 else 0	 end,
			@message = case when count(*) = 0 then '@order_header_id not valid' else '' end
		from order_header
		where order_header_id = @order_header_id

		if @response_code < 0 	
			begin
				select response_code = @response_code, message = @message
				return
			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert sweepstakes_registration
		insert into sweepstakes_registration(sweepstakes_id, customer_id, order_header_id, dob) values(@sweepstakes_id, @customer_id, @order_header_id, @dob)
		
		-- 2.2) update/insert phone number
		if @current_phone_number <> @phone_number or @current_phone_number is null
			begin
			if @current_phone_number is null
				begin
				insert into customer_phone (customer_id, phone_type_id, phone_number) values(@customer_id, 1, @phone_number)
				end
			else
				begin
				update customer_phone
				set phone_number = @phone_number, mo
dified_date = getdate(), modified_by = suser_sname() 
				where customer_id = @customer_id
				end			
			end
	
		-- 2.3) return success
		select @response_code = 0, @message = 'registration successful'
	
		select response_code = @response_code, message = @message
		
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert sweepstakes registration failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
