-- PROCEDURE: [dbo].[usp_trial_insert_external_registration]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_trial_insert_external_registration]

(
	@registration_key_value nvarchar(2000)
)

/*	
	DATE		AUTHOR		REMARKS
	2012-09-28	esmart		Initial creation.

	DESCRIPTION
	insert trial registration from external source
*/

AS
	set nocount on				

	declare @trial_external_registration_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into trial_external_registration(registration_key_value)
	values(@registration_key_value)

	select @trial_external_registration_id = scope_identity()
	
	select trial_external_registration_id = @trial_external_registration_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_trial_insert_trial]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_trial_insert_trial]

(
	@trial_registration_id INT,
	@keycode VARCHAR(40) = NULL,
	@account_order_json VARCHAR(MAX) = NULL
)

AS
       /*     
             DATE          AUTHOR       REMARKS
             2014-02-10    esmart       Initial creation.   
             2014-03-26    esmart       Fix partner_account_code 
             2014-04-09    esmart       Remove license_feature_license    
             2014-11-17    esmart       Add eloqua_guid
             2015-03-05    cnovac       Added @company_type_name = null to usp_customer_insert_customer_service call
             2015-05-06    esmart       Remove partner_id from restriction on 6.2
             2015-08-24    acoffel      License channel update
             2016-04-15    esmart       Add @salesforce_license_id 
             2016-07-12    acoffel      6.2 Extend additional process into update_eloqua_trial template
             2016-08-11    acoffel      fix sfdc op update process timing
             2017-02-02    esmart       trial_registration_json
             2017-06-21    esmart       Move MSP registration up to 3.6
             2017-07-05    esmart       Fix bug that is creating multiple license for consumer trials with seats > 1
             2017-07-06    esmart       sky licensing support
             2017-09-05    esmart       restrict interface to eloqua for partner trials
             2018-04-30    rvinoche     remove insert into sky_api_license as it's done in sub routine
             2018-06-13    acoffel      remove -- 6.2) @eloqua_guid
             2018-07-10    cnovac       added code for WIFI at bottom and @account_order_json
             2018-10-11    cnovac       Updated call to usp_account_order_finalize
             2019-06-21    esmart       add @company_id_input
             2019-12-03    esmart       Remove buffer on sky insert
             2020-02-13    esmart       Modify GSM registration insert to only include SAEP (3.6)
             2020-03-05    esmart       Refactor to use @trial_registration_json and vault
             2020-04-20    cnovac       Fix to set @license_category_name and @account_order_staging_id for WIFI
			 2020-07-23	   wbarton		Retiring the restriction for .ru and yandex. The webservers for api.webroot block repeat-requests, which was why this code was put in place.
			 2020-09-16	   abelenkiy	More accurate hadling of json and removed unused vars
			 2025-10-27	   psatish		D-5045328 Set the variable @ecom_create_license to 1 if a license generates through ecom

             DESCRIPTION
             insert trial
       */

       set nocount on

       declare @first_name nvarchar(225),
                @last_name nvarchar(225),
                @company_name nvarchar(255),
				@company_type_name varchar(50),
                @phone_number varchar(64),
                @customer_email varchar(100),
                @address_1 nvarchar(255),
                @address_2 nvarchar(255),
                @city nvarchar(130),
                @state nvarchar(2),
                @postal_code nvarchar(32),
                @country varchar(75),
                @license_category_name varchar(10), 
                @license_seats int,
                @trial_days int,
                @partner_key varchar(36),
                @partner_account_key varchar(36),
                @sfdc_lead_id varchar(18),
                @sfdc_opportunity_id varchar(18),
                @sfdc_trial_id varchar(18),
                @partner_id int,
                @partner_account_id int,
                @product_id int,
                @license_distribution_method_id int,
                @start_date datetime,
                @end_date datetime,
                @mo
nths int,
                @license_id int,
                @trial_id int,
                @customer_id int,
                @customer_id_input int,
                @request_type varchar(20),
                @vendor_id int,
                @vendor_customer_code varchar(100),
                @opt_in int, 
                @salesforce_account_id varchar(18), 
                @salesforce_contact_id varchar(18),
                @salesforce_license_id varchar(18), 
                @transaction_user varchar(20) = 'trial_registration',
                @process_date datetime,
                @product_line_id int,
                @trial_registration_json nvarchar(max),
                @module_seats int, 
                @license_change_reason_id int, 
                @order_item_id int, 
                @module_product_id int,
                @account_order_staging_id int,
				@company_id_input int,
				@license_service_type_name varchar(50),
				@return_license_service_id int,
                @response_code int,
                @message varchar(100),
				@ecom_create_license TINYINT
                

       BEGIN TRY


       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 0.) json
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 0.1) @trial_registration_json
		SELECT @trial_registration_json = j.trial_registration_json
		FROM trial_registration_json j
		WHERE j.trial_registration_id = @trial_registration_id

       -- 0.2) select values
	   IF ISJSON(@trial_registration_json) = 1
			BEGIN

			SELECT @license_service_type_name = 'license_create'
			
			-- 0.2.1) update json with keycode
				IF @keycode IS NULL OR @keycode = ''
				BEGIN
					SELECT @product_id = 152200130

					SELECT @license_distribution_method_id = license_distribution_method_id
					FROM trial_registration t
					WHERE t.trial_registration_id = @trial_registration_id


					EXEC usp_license_generate_keycode_cart @product_id,
														   @license_distribution_method_id,
														   @keycode OUTPUT,
														   @response_code OUTPUT,
														   @message OUTPUT
					SET @ecom_create_license = 1
					SELECT @trial_registration_json=JSON_MODIFY(@trial_registration_json,'$.ecom_create_license',@ecom_create_license)
				END
				
				-- modify json
				SELECT @trial_registration_json = JSON_MODIFY(@trial_registration_json,'$.keycode',@keycode)

				-- trial_registration_json
				UPDATE trial_registration_json 
				SET trial_registration_json = @trial_registration_json 
				WHERE trial_registration_id = @trial_registration_id

				-- trial_registration
				UPDATE trial_registration 
				SET keycode = @keycode
				WHERE trial_registration_id = @trial_registration_id

			-- 0.2.2) license_create
			EXEC usp_license_service_insert_service @license_service_type_name, @trial_registration_json, @return_license_service_id
			
			-- 0.2.3) @license_id
			SELECT @license_id = l.license_id, @customer_id = l.customer_id
			FROM license l
			WHERE l.keycode = @keycode

			-- 0.2.4) partner
			SELECT @partner_key = JSON_VALUE(@trial_registration_json,'$.partner.partner_key')

			SELECT @partner_id = p.partner_id
			FROM partner p
			WHERE p.partner_key = @partner_key

			-- return
			END
		ELSE --'else' code is obsolete because now php always passes json into [usp_trial_insert_trial_registration]; code can be removed once json standardization across systems is complete
			BEGIN		

		   -- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------
		   -- 1.) select
		   -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
		   -- 1.1) select values
		   select @first_name = first_name, 
				@last_name = last_name,
				@company_name = company_name,
				@company_type_name = company_type_name,
				@phone_number = phone_number, 
				@customer_email = customer_email, 
				@address_1 = address_1,
				@address_2 = address_2,
				@city = city,
				@state = case when state is null then '' else state end, 
				@postal_code = postal_code,
				@country = country, 
				@partner_key = partner_key, 
				@partner_account_key = partner_account_key, 
				@product_id = product_id,
				@license_category_name = license_category_name,
				@license_distribution_method_id = license_distribution_method_id, 
				@license_seats = license_seats,
				@request_type = request_type,
				@sfdc_lead_id = sfdc_lead_id,
				@sfdc_opportunity_id = sfdc_opportunity_id,
				@sfdc_trial_id = sfdc_trial_id,
				@vendor_customer_code = partner_account_code,
				@salesforce_license_id = salesforce_license_id,
				@trial_days = trial_days,
				@opt_in = opt_in
		   from trial_registration
		   where trial_registration_id = @trial_registration_id

			select @account_order_staging_id = json_value(@account_order_json, '$.account_order_staging_id')

			--if @customer_email like '%.ru' or @customer_email like '%yandex%'
			--	begin
			--	return
			--	end
       
		   -- 1.2) check for duplicate
		   select @trial_id = trial_id 
		   from trial
		   where trial_registration_id = @trial_registration_id

		   if @trial_id is not null
				 begin
				 select trial_id = @trial_id
             
				 select @license_id = license_id from trial where trial_id = @trial_id
				 goto insert_sfdc_opportunity_update
				 return
				 end

		   -- 1.3) update keycode
		   if @keycode is not null
			begin
				update trial_registration
				set keycode = @keycode
				where trial_registration_id = @trial_registration_id
			end

		   -- 1.4) @partner_id
		   select @partner_id = partner_id
		   from partner 
		   where partner_key = @partner_key

		   -- 1.5) @partner_account_id
		   select @partner_account_id = partner_account_id
		   from partner_account
		   where partner_account_key = @partner_account_key

		   -- 1.6) @product_line_id 
		   select @product_line_id = product_line_id
		   from product_line_product
		   where product_id = @product_id

		   if @product_line_id not in (300,55) and @license_category_name != 'WIFI'
			begin
				select @license_seats = 1
			end

		   -- 1.7) handle iso country in place of description
		   if not exists (select country_id from lu_countries where description = @country)
			begin
				select @country = description
				from lu_countries 
				where iso = @country
			end
		
			-- 1.8) correct invalid company_type_name
			if @company_type_name is not null
				begin
				select @company_type_name = case
												when @company_type_name = 'Managed Service Provider' then 'MSP'
												when @company_type_name = 'MSP/VAR (Hybrid)' then 'MSP/Reseller Hybrid'
												when @company_type_name = 'Value Added Reseller' then 'Reseller'
												when @company_type_name = '' then 'Business'
												else @company_type_name
											end
				end

		   -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		   -- 2.) customer
		   -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
		   -- 2.1) select customer match
	
	   exec usp_customer_insert_customer_service @customer_email, @first_name, @last_name, @company_name, @company_type_name, @phone_number, @address_1, @address_2, @city, @state, @postal_code, @country, @vendor_id, @vendor_customer_code, @partner_id, @opt_in, @salesforce_account_id, @salesforce_contact_id, @transaction_user, @customer_id_input, @company_id_input, @customer_id output
       
		   -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		   -- 3.) license
		   -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		   -- 3.1) license
		   declare @keycodes table (keycode varchar(40))

		   -- 3.2) insert license
		   insert into @keycodes(keycode)
		   exec usp_license_insert_license_service @product_id,@license_distribution_method_id,@license_seats,@start_date,@end_date,@months,@keycode,null,@trial_registration_id

		   -- 3.3) select @license_id
		   select @license_id = l.license_id
		   from @keycodes k
		   inner join license l
				 on k.keycode = l.keycode

		   -- 3.4) update license.customer_id
		   update license set customer_id = @customer_id where license_id = @license_id

		   -- 3.5) @salesforce_license_id
		   update license_key set salesforce_license_id = @salesforce_license_id where license_id = @license_id

		   -- 3.6) MSP registration
		   if @request_type = 'create_master' and @license_category_name = 'SAEP'
			begin
				declare @sky_template_id tinyint
				select @sky_template_id = sky_template_id from sky_template where sky_template_name = 'msp_registration'
             
				select @process_date = getdate()

				exec [usp_sky_insert_update] @license_id, @sky_template_id, @process_date
			end

		   -- 3.7) @trial_registration_json
		   select @trial_registration_json = trial_registration_json
		   from trial_registration_json
		   where trial_registration_id = @trial_registration_id

		   if @trial_registration_json is not null
			begin
				select @license_change_reason_id = 3

				declare @json_module_data table (license_module_code varchar(50), days int,     module_seats int)
				declare @module_products table (module_id int identity(1,1), module_product_id int, module_seats int)

				declare @module_id int, @modules int

				-- 2.1) parse json
				insert into @json_module_data (license_module_code, days, module_seats)
				select license_module_code, days, module_seats
				from openjson(@trial_registration_json)
				with (license_module_code varchar(50) '$.license_module_code',days int '$.days',module_seats int '$.module_seats')

				-- 2.2) get products
				insert into @module_products (module_product_id, module_seats)
				select p.product_id, t.module_seats
				from @json_module_data t
				inner join license_module lm 
						on lm.license_module_code = t.license_module_code
				inner join product_license_module pm
						on pm.license_module_id = lm.license_module_id and pm.days = t.days
				inner join product p
						on p.product_id = pm.product_id and p.product_type_id = 4
             
				select @modules = max(module_id), @module_id = 1 from @module_products 

				-- 2.3) add modules
				while @modules >= @module_id 
				begin
					select @module_product_id = module_product_id, @module_seats = module_seats
					from @module_products
					where module_id = @module_id

					exec usp_license_update_license_module_license @license_id, @module_product_id, @license_change_reason_id, @order_item_id, @module_seats

					select @module_id = @module_id + 1
				end

			end
		end
       -- -------------------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------
       -- 4.) trial
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       -- 4.1) insert trial
       insert into trial(trial_registration_id, license_id, customer_id)
       values(@trial_registration_id, @license_id, @customer_id)

       select @trial_id = scope_identity()

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 5.) post process
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       -- 5.3) insert partner_trial
       if @partner_id is not null
             begin
             insert into partner_trial(partner_id, trial_id, partner_account_id)
             values(@partner_id, @trial_id, @partner_account_id)
             end

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 6.0) sfdc update
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       
       insert_sfdc_opportunity_update:
       
       declare @sfdc_update_type_id tinyint, @sfdc_template_id tinyint

       -- 6.1) insert sfdc_trial
       if @sfdc_opportunity_id is not null or @sfdc_lead_id is not null or @sfdc_trial_id is not null or @salesforce_license_id is not null
             begin

             -- 6.1.2) @sfdc_template_id
             select @sfdc_template_id = sfdc_template_id
             from sfdc_template 
             where sfdc_template_name = 'update_license'

             -- 6.1.3) 
             select @sfdc_update_type_id = sfdc_update_type_id
             from sfdc_template_update_type
             where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
                                                                         from sfdc_template_update_type
                                                                         where sfdc_template_id = @sfdc_template_id)

             -- 6.1.4) insert sfdc_opportunity_update                
             insert into sfdc_opportunity_update(license_id, trial_id, sfdc_template_id, sfdc_update_type_id, process_date)
             values(@license_id, @trial_id, @sfdc_template_id, @sfdc_update_type_id, getdate())
                           
             end

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       -- 7.0)  WIFI specific code to log which account order staging id is associated to this trial
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select @license_category_name = license_category_name
		from trial_registration
		where trial_registration_id = @trial_registration_id

		select @account_order_staging_id = json_value(@account_order_json, '$.account_order_staging_id')

		if @license_category_name = 'WIFI' and @account_order_staging_id is not null
		begin
			set @account_order_json = (select @account_order_staging_id as account_order_staging_id, @trial_id as trial_id, @trial_days as days for json path,without_array_wrapper)
			exec
 usp_account_order_finalize @license_id = @license_id, @account_order_json = @account_order_json
		end

       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
       --
       -- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

       select trial_id = @trial_id

       end try

       begin catch

             set @response_code = -200
             set @message = case when @message is null then 'select failed'
                                               else @message end

             declare @DBName nvarchar(128)
             set @DBName = db_name()
             exec usp_LogError @ErrorDB = @DBName
             
       end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_trial_insert_trial_module]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_trial_insert_trial_module]

(
	@keycode varchar(40),
	@trial_registration_json varchar(max)
)
	
/*	
	DATE			AUTHOR			REMARKS
	2017-02-03		esmart			Initial creation
	
	DESCRIPTION
	insert trial license_module_license
*/

as

	set nocount on
	

	declare @license_module_code varchar(50), 
			@days int, 
			@module_seats int, 
			@license_change_reason_id int, 
			@order_item_id int, 
			@module_product_id int,
			@license_id int,

			@response_code int,
			@message varchar(100)
			
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @license_change_reason_id = 3

	declare @parameters table (parameter_name varchar(50), input_value nvarchar(100))

	-- 1.1) parse json
	insert into @parameters(parameter_name,input_value)
	select parameter_name = NAME, input_value = case when StringValue = '' then null else StringValue end
	from dbo.fn_parse_json(@trial_registration_json) 
	where Object_ID is null and StringValue is not null
	
	-- 1.2) select out values
	select @license_module_code = input_value from @parameters where parameter_name = 'license_module_code'
	select @days = input_value from @parameters where parameter_name = 'days'
	select @module_seats = input_value from @parameters where parameter_name = 'module_seats'

	-- 1.3) find module product
	select @module_product_id = m.product_id
	from product_license_module m
	inner join product p
		on p.product_id = m.product_id
	inner join license_module lm 
		on lm.license_module_id = m.license_module_id
	where p.product_type_id = 4 and lm.license_module_code = @license_module_code and m.days = @days

	-- 1.4) @license_id
	select @license_id = license_id
	from license 
	where keycode = @keycode
		
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert 
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	exec usp_license_update_license_module_license @license_id, @module_product_id, @license_change_reason_id, @order_item_id, @module_seats



	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert license_module_license failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_trial_insert_trial_registration]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_trial_insert_trial_registration]

(
	@first_name nvarchar(225) = null,
	@last_name nvarchar(225) = null,
	@company_name nvarchar(255) = null,
	@company_type_name varchar(50) = null,
	@phone_number varchar(64) = null,
	@customer_email varchar(100) = null,
	@address_1 nvarchar(255) = null,
	@address_2 nvarchar(255) = null,
	@city nvarchar(130) = null,
	@state nvarchar(2) = null,
	@postal_code nvarchar(32) = null,
	@country varchar(75) = null,
	@language_code varchar(2) = null,
	@location_code varchar(3) = null,
	@license_category_name varchar(10) = null, 
	@license_seats int = null,
	@years float = null,
	@trial_days int = null,
	@license_keycode_type_id int = null,
	@partner_key varchar(36) = null,
	@account_user_name varchar(100) = null,
	@partner_account_code varchar(50) = null,
	@sfdc_lead_id varchar(18) = null,
	@sfdc_opportunity_id varchar(18) = null,
	@sfdc_trial_id varchar(18) = null,
	@salesforce_campaign_id varchar(18) = null,
	@partner_product_id varchar(20) = null,
	@sfdc_distributor_id varchar(18) = null,
	@sfdc_reseller_id varchar(18) = null,
	@eloqua_parameters nvarchar(max) = null,
	@license_distribution_method_code char(4) = null,
	@salesforce_license_id varchar(18) = null,
	@trial_registration_json varchar(max) = NULL,
	@opt_in int = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-02-10	esmart		Initial creation.	
		2014-11-17	esmart		Add eloqua_guid
		2015-08-05	esmart		Move @license_distribution_method_code to input
		2015-09-11	acoffel		Added NFR disti support
		2016-04-15	esmart		Add @salesforce_license_id 
		2017-02-02	esmart		Add @trial_registration_json
		2017-09-08	esmart		Add product_line_id to result set
		2018-07-09	cnovac		Added code to not reset @years when creating WIFI trial
		2018-10-04	esmart		Add company_type_name
		2020-01-24	cnovac		Added @product_years to write to license_registration so that for WIFI we can tell if monthly or annual
		2020-03-05	esmart		Refactor to use @trial_registration_json
		2020-06-28	abelenkiy	AXIOM-1297: set @opt_in variable so value passed into usp_customer_insert_customer_service is no longer null
		2020-07-23	wbarton		Retiring the restriction for .ru and yandex. The webservers for api.webroot block repeat-requests, which was why this code was put in place.
		2020-08-28	 abelenkiy  AXIOM-1764: added handling of customer_type to get company_type_name from company_type_id in json and properly write to trial_registration table

		DESCRIPTION
		insert trial registration
	*/



	set nocount on

	declare @trial_registration_id int,
			@request_type varchar(20),
			@product_line_id int,
			@license_category_id tinyint,
			@license_type varchar(50),
			@license_type_id int,
			@product_years float = @years,
			@license_distribution_method_id int,
			@license_module_list varchar(max),
			@storage_gb int,
			@cart_discount_id int,
			@cart_type_id int,
			@capability_id int,
			@capability_type_id int,
			@capability_activation_days int,
			@product_id int,
			@trial tinyint,
			@partner_account_key varchar(36),
			@current_sfdc_trial_id varchar(18),
			@sfdc_update_type_id tinyint, 
			@sfdc_template_id tinyint,
			@trial_id int,
			@company_type_id int,
			@response_code int,
			@message varchar(100)

	declare @license_category_table table (license_category_name varchar(10),license_seats int,days int,start_date datetime,expiration_date datetime,category_type_name varchar(50),item_hierarchy_id tinyint)
	
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 0.) json
	-- 
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if isjson(@trial_registration_json) = 1
	begin
	declare @keycode varchar(40),
			@license_category nvarchar(max),
			@customer nvarchar(max),
			@partner nvarchar(max),
			@sfdc nvarchar(max)
			

	-- 0.1) parse json
		select @keycode = keycode,
				@license_distribution_method_code = case when license_distribution_method_code = '' then null else license_distribution_method_code end,
				@language_code = language_code,
				@location_code = location_code,
				@license_keycode_type_id = license_keycode_type_id,
				@license_category = license_category,
				@partner = partner,
				@customer = customer,
				@sfdc = sfdc,
				@eloqua_parameters = eloqua_parameters
		from openjson(@trial_registration_json)
		with (keycode varchar(40) '$.keycode',
			language_code varchar(2) '$.language_code',
			location_code varchar(40) '$.location_code',
			license_distribution_method_code char(4) '$.license_distribution_method_code',
			license_keycode_type_id int '$.license_keycode_type_id',
			license_category nvarchar(max) as json,
			customer nvarchar(max) as json,
			partner nvarchar(max) as json,
			sfdc nvarchar(max) as json,
			eloqua_parameters nvarchar(max) as json) 
	

	-- select @license_category as license_category, @customer as customer, @partner as partner, @sfdc as sfdc, @eloqua_parameters as eloqua_parameters

	-- TOP
	-- select @license_distribution_method_code,@license_keycode_type_id,@language_code,@location_code

	-- @license_category
	insert into @license_category_table(license_category_name,license_seats,days,start_date,expiration_date,category_type_name,item_hierarchy_id)
	select license_category_name,license_seats,days,start_date,expiration_date,category_type_name,item_hierarchy_id
	from openjson(@license_category)
	with (license_category_name varchar(10) '$.license_category_name',
				license_seats int '$.license_seats',
				days int '$.days',
				start_date datetime '$.start_date',
				expiration_date datetime '$.expiration_date',
				category_type_name varchar(50) '$.category_type_name',
				item_hierarchy_id tinyint '$.item_hierarchy_id')
	where license_category_name is not null

	select @license_category_name = t.license_category_name, @license_seats = t.license_seats, @years = 0, @trial_days = t.days
	from @license_category_table t
	where t.item_hierarchy_id = 1

	-- select @license_category_name,@license_seats,@years,@trial_days

	-- @customer
	select @customer_email = j.customer_email,
			@first_name = j.first_name,
			@last_name = j.last_name,
			@company_name = j.company_name,
			@company_type_name = ct.company_type_name,
			@phone_number = j.phone_number,
			@address_1 = j.address_1,
			@address_2 = j.address_2,
			@city = j.city,
			@state = j.state,
			@postal_code = j.postal_code,
			@country = j.country,
			@opt_in = j.opt_in
	from openjson(@customer)
	with (customer_email varchar(100) '$.customer_email',
			first_name nvarchar(225) '$.first_name',
			last_name nvarchar(225) '$.last_name',
			company_name nvarchar(255) '$.company_name',
			company_type_name varchar(20) '$.company_type_name',
			company_type_id int '$.company_type_id',
			phone_number varchar(64) '$.phone_number',
			address_1 nvarchar(255) '$.address_1',
			address_2 nvarchar(255) '$.address_2',
			city nvarchar(130) '$.city',
			state nvarchar(2) '$.state',
			postal_code nvarchar(32) '$.postal_code',
			country varchar(75) '$.country',
			opt_in int '$.opt_in') j
	left join company_type ct
		on ct.company_type_id = j.company_type_id

	-- select @first_name,@last_name,@company_name,@company_type_name,@phone_number,@customer_email,@address_1,@address_2,@city,@state,@postal_code,@country

	-- @partner
	select @partner_key = partner_key,
			@account_user
_name = account_user_name,
			@partner_account_code = partner_account_code,
			@partner_product_id = partner_product_id
	from openjson(@partner)
	with (partner_key varchar(36) '$.partner_key',
			account_user_name varchar(36) '$.account_user_name',
			partner_account_code varchar(36) '$.partner_account_code',
			partner_product_id varchar(36) '$.partner_product_id')

	-- select @partner_key,@account_user_name,@partner_account_code,@partner_product_id

	-- @sfdc
	select	@sfdc_lead_id = sfdc_lead_id,
			@sfdc_opportunity_id = sfdc_opportunity_id,
			@sfdc_trial_id = sfdc_trial_id,
			@salesforce_campaign_id = salesforce_campaign_id,
			@sfdc_distributor_id = sfdc_distributor_id,
			@sfdc_reseller_id = sfdc_reseller_id,
			@salesforce_license_id = salesforce_license_id
	from openjson(@sfdc)
	with (sfdc_lead_id varchar(18) '$.sfdc_lead_id',
		sfdc_opportunity_id varchar(18) '$.sfdc_opportunity_id',
		sfdc_trial_id varchar(18) '$.sfdc_trial_id',
		salesforce_campaign_id varchar(18) '$.salesforce_campaign_id',
		sfdc_distributor_id varchar(18) '$.sfdc_distributor_id',
		sfdc_reseller_id varchar(18) '$.sfdc_reseller_id',
		salesforce_license_id varchar(18) '$.salesforce_license_id')

	-- select @sfdc_lead_id,@sfdc_opportunity_id,@sfdc_trial_id,@salesforce_campaign_id,@sfdc_distributor_id,@sfdc_reseller_id,@salesforce_license_id
	end

	--return

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @license_keycode_type_id is null
		begin
		select @license_keycode_type_id = 1
		end

	--if @customer_email like '%.ru' or @customer_email like '%yandex%'
	--		begin
			
	--		select response_code = -100, message='Duplicate registration', trial_registration_id = 1600099
	--		return
	--		end

	-- 1.1) check for duplicate
	select @trial_registration_id = tr.trial_registration_id, @current_sfdc_trial_id = sfdc_trial_id, @trial_id = trial_id
	from trial_registration tr
	left join trial t
		on tr.trial_registration_id = t.trial_registration_id
	where tr.customer_email = @customer_email and tr.license_category_name = @license_category_name and tr.license_keycode_type_id = @license_keycode_type_id

	-- 1.1.1) @sfdc_trial_id
	if @trial_registration_id is null
		begin
		select @trial_registration_id = tr.trial_registration_id
		from trial_registration tr
		where tr.sfdc_trial_id = @sfdc_trial_id
		end

	-- 1.1.2) update trial
	if @trial_registration_id is not null
		begin
		if @sfdc_trial_id is not null and @sfdc_trial_id <> @current_sfdc_trial_id
			begin

			-- 1.1.2.1) insert audit
			insert into sfdc_trial_audit(sfdc_trial_id, trial_id, salesforce_lead_id, salesforce_opportunity_id, salesforce_trial_id)
			select sfdc_trial_id, trial_id, salesforce_lead_id, salesforce_opportunity_id, salesforce_trial_id
			from sfdc_trial
			where salesforce_trial_id = @current_sfdc_trial_id
			
			-- 1.1.2.2) update trial_registration
			update trial_registration
			set sfdc_trial_id = @sfdc_trial_id
			where trial_registration_id = @trial_registration_id
			
			-- 1.1.2.3) update sfdc_trial
			update sfdc_trial
			set salesforce_trial_id = @sfdc_trial_id
			where salesforce_trial_id = @current_sfdc_trial_id

			---- 1.1.2.4) @sfdc_template_id
			--select @sfdc_template_id =  9

			---- 1.1.2.5) @sfdc_update_type_id
			--select @sfdc_update_type_id = sfdc_update_type_id
			--from sfdc_template_update_type
			--where sfdc_template_update_type_id = (select min(sfdc_template_update_type_id)
			--									from sfdc_template_update_type
			--									where sfdc_template_id = @sfdc_template_id)

			---- 1.1.2.6) i
nsert sfdc_opportunity_update
			--insert into sfdc_opportunity_update(trial_id, sfdc_template_id, sfdc_update_type_id, process_date)
			--values(@trial_id, @sfdc_template_id, @sfdc_update_type_id, getdate())

			end

		select response_code = -110, message='Duplicate registration', trial_registration_id = @trial_registration_id
		return
		end

	-- 1.2) @partner_account_key
	select @partner_account_key = pa.partner_account_key
	from partner_account pa
	inner join account a
		on pa.account_id = a.account_id 
	where a.account_user_name = @account_user_name

	-- 1.3) @partner_product_id
	select @product_id = pp.product_id, @product_line_id = pl.product_line_id
	from partner_service_product pp
	inner join partner p
		on pp.partner_id = p.partner_id
	inner join product_line_product pl
		on pp.product_id = pl.product_id
	where pp.partner_product_id = @partner_product_id and p.partner_key = @partner_key

	-- 1.4) @years
	if @trial_days is not null and @trial_days > 0
		begin
		select @years = 0
		end
	
	-- 1.5 language/location
	if len(@location_code) = 2
		begin
		select @location_code = iso3 from lu_countries where iso = @location_code
		end

		-- 1.5.1) @language_code
		if @language_code is null or @language_code = ''
			begin
			select @language_code = 'EN'
			end
	
		if @location_code is null or @location_code = ''
			begin
			select @location_code = 'USA'
			end
			
	-- 1.6) @salesforce_campaign_id
	if len(@salesforce_campaign_id) = 15 and @salesforce_campaign_id is not null
		begin
		select @salesforce_campaign_id = dbo.fn_ConvertSalesforceID_15to18(@salesforce_campaign_id)
		end

	-- 1.7) @license_distribution_method_code
	if @license_distribution_method_code is not null
		begin
			select @license_distribution_method_id = license_distribution_method_id 
			from license_distribution_method 
			where license_distribution_method_code = @license_distribution_method_code

			if @license_distribution_method_id is null
				begin
				select @license_distribution_method_code = null
				end
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) product
	-- --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @product_id is null
		begin

		-- 2.2) @product_line_id
		select @product_line_id = product_line_id
		from license_category_product_line pl
		inner join license_category c
			on pl.license_category_id = c.license_category_id
		where c.license_category_name = @license_category_name and 
			language_code = @language_code and 
			location_code = @location_code

		-- 2.1) select @product_set
		declare @product_set table(line_item int identity(1,1), product_id int, product_description varchar(100), quantity int default 1, retail_price money, upgrade_price money, discount money, standard_discount money, net_price money, product_type_id int, license_category_name varchar(10), seats int, years float, p_type varchar(20), cart_item_class_id tinyint, cart_item_bundle_id int, keycode varchar(40), currency_id tinyint, currency_code char(3), currency_description varchar(20), symbol_html varchar(10), symbol_utf8 nvarchar(10), symbol_text varchar(10), cart_discount_id int)
	
		if @product_line_id in (55,300)
			begin
			-- 2.1.1) enterprise
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)
				exec usp_cart_select_new_product_set_ENT @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@
location_code,@cart_type_id,@trial_days,@license_keycode_type_id	
			end
		else
			begin
			-- 2.1.2) consumer
				insert into @product_set(product_id,product_description,retail_price,upgrade_price,discount,standard_discount,net_price,product_type_id,license_category_name,seats,years,p_type, currency_id, currency_code, currency_description, symbol_html, symbol_utf8, symbol_text, cart_discount_id)
				exec usp_cart_select_new_product_set @license_category_name,@license_seats,@storage_gb,@years,@cart_discount_id,@language_code,@location_code,@cart_type_id,@trial_days,@license_keycode_type_id
			end

		-- 2.3) license type
		select @product_id = p.product_id, @license_category_id = lc.license_category_id, @product_line_id = pl.product_line_id, @capability_type_id = c.capability_type_id, @capability_activation_days = c.capability_activation_days, @storage_gb = s.storage_gb, @license_keycode_type_id = pr.license_keycode_type_id
		from @product_set p
		inner join product pr
			on p.product_id = pr.product_id
		inner join product_line_product pl
			on p.product_id = pl.product_id
		inner join product_license_category plc
			on p.product_id = plc.product_id 
		inner join license_category lc
			on plc.license_category_id = lc.license_category_id 
		inner join product_capability c
			on p.product_id = c.product_id and c.capability_id = lc.base_capability_id and c.capability_id = lc.base_capability_id
		left join product_storage s
			on p.product_id = s.product_id

		end
	else
		begin
		select @product_id = p.product_id, @license_category_id = lc.license_category_id, @product_line_id = pl.product_line_id, @capability_type_id = c.capability_type_id, @capability_activation_days = c.capability_activation_days, @storage_gb = s.storage_gb, @license_keycode_type_id = p.license_keycode_type_id, @license_category_name = lc.license_category_name
		from product p
		inner join product_line_product pl
			on p.product_id = pl.product_id
		inner join product_license_category plc
			on p.product_id = plc.product_id 
		inner join license_category lc
			on plc.license_category_id = lc.license_category_id 
		inner join product_capability c
			on p.product_id = c.product_id and c.capability_id = lc.base_capability_id and c.capability_id = lc.base_capability_id
		left join product_storage s
			on p.product_id = s.product_id
		where p.product_id = @product_id
		end
	
	-- select product_line_id = @product_line_id, capability_type_id = @capability_type_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set values
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select @license_type_id = case 
								when @product_line_id in (300,55) and @capability_type_id = 1  then 4 
								when @product_line_id in (300,55) and @capability_type_id <> 1  then 104 
								when @product_line_id not in (300,55) and @capability_type_id = 1  then 1 
								when @product_line_id not in (300,55) and @capability_type_id <> 1  then 101
							end

	select @license_type = case 
								when @product_line_id in (300,55) and @capability_type_id = 1 then 'enterprise,full'
								when @product_line_id in (300,55) and @capability_type_id <> 1 then 'enterprise,trial'
								when @product_line_id not in (300,55) and @capability_type_id = 1 then 'consumer,full'
								when @product_line_id not in (300,55) and @capability_type_id <> 1 then 'consumer,trial'
							end

	-- 2.4) request type
	select @request_type = case
								when @license_keycode_type_id = 3 then 'create_master'
								else 'create_key'
							end

	-- 2.5) license_module_list
	select @license_module_list = coalesce(@license_module_list+',',
'')+ cast(lm.license_module_code+'='+convert(varchar(20),t.license_module_type_name) as varchar(100))	
	from license_category_module m
	inner join license_module lm
		on m.license_module_id = lm.license_module_id
	inner join license_module_type t
		on m.license_module_type_id = t.license_module_type_id
	inner join license_category c
		on m.license_category_id = c.license_category_id
	where c.license_category_name = @license_category_name


	-- 2.6) @license_distribution_method_code
	if @license_distribution_method_code <> 'NFRS' or @license_distribution_method_code is NULL
		begin
			select @license_distribution_method_code = m.license_distribution_method_code, @license_distribution_method_id = m.license_distribution_method_id
			from partner p
			inner join partner_license_distribution_method pm
				on p.partner_id = pm.partner_id
			inner join license_distribution_method m
				on pm.license_distribution_method_id = m.license_distribution_method_id
			where p.partner_key = @partner_key
		end
		

	if @license_distribution_method_code is null
		begin
			print 'new disti'
			select @trial = case when @trial_days > 0 then 1 else 0 end
			
			exec usp_product_select_license_distribution_method @product_line_id,@license_keycode_type_id,@trial,@license_category_id,@license_distribution_method_id OUTPUT
			select @license_distribution_method_code = license_distribution_method_code from license_distribution_method where license_distribution_method_id =  @license_distribution_method_id
		end

	--select @first_name, @last_name, @company_name, @phone_number, @customer_email, @address_1, @address_2, @city, @state, @postal_code, @country, @language_code, @location_code, @license_category_name, @license_seats, @years, @trial_days, @license_keycode_type_id, @partner_key, @partner_account_key, @partner_account_code, @sfdc_lead_id, @sfdc_opportunity_id,@product_id,@license_distribution_method_id,@request_type
	--return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 3.1) insert registration
	insert into trial_registration(first_name, last_name, company_name, company_type_name, phone_number, customer_email, address_1, address_2, city, state, postal_code, country, language_code, 
			location_code, license_category_name,	license_seats, years, trial_days, license_keycode_type_id, partner_key, partner_account_key, partner_account_code, sfdc_lead_id, sfdc_opportunity_id,
			product_id, license_distribution_method_id, request_type, sfdc_trial_id, salesforce_campaign_id, sfdc_distributor_id, sfdc_reseller_id, eloqua_parameters, salesforce_license_id, opt_in)
	values (@first_name, @last_name, @company_name, @company_type_name, @phone_number, @customer_email, @address_1, @address_2, @city, @state, @postal_code, @country, @language_code, @location_code, 
			@license_category_name, @license_seats, @product_years, @trial_days, @license_keycode_type_id, @partner_key, @partner_account_key, @partner_account_code, @sfdc_lead_id, @sfdc_opportunity_id,
			@product_id, @license_distribution_method_id, @request_type, @sfdc_trial_id, @salesforce_campaign_id, @sfdc_distributor_id, @sfdc_reseller_id, @eloqua_parameters, @salesforce_license_id, @opt_in)

	select @trial_registration_id = scope_identity()

	-- 3.2) @trial_registration_json
	if isjson(@trial_registration_json) = 1
		begin
		insert into trial_registration_json (trial_registration_id,trial_registration_json)
		values(@trial_registration_id,@trial_registration_json)
		end

	-- --------------------------------------------------------------------------------------------------------------
-------------------------------------------------------------------------------------
	-- 4.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select	trial_registration_id = @trial_registration_id, 
			request_type = @request_type, 

			first_name = @first_name,
			last_name = @last_name,
			customer_email = @customer_email,

			product_line_id = @product_line_id,
			license_category_name = @license_category_name,
			license_category_id=@license_category_id, 
			license_module_list = @license_module_list, 
			license_type = @license_type, 
			license_type_id = @license_type_id, 
			capability_activation_days = @capability_activation_days,
			license_seats = @license_seats,
			storage_gb = @storage_gb,
			license_distribution_method_code = @license_distribution_method_code

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_trial_select_trial]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_trial_select_trial]

(

	@trial_id int = null,
	@salesforce_trial_id varchar(18) = null,
	@salesforce_license_id varchar(18) = null,
	@customer_id int = NULL,
	@license_id int = NULL
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-02-10	esmart		Initial creation.
		2014-03-21	esmart		convert uniqueidentifier to varchar	
		2016-03-31	acoffel		add inputs @license_id and @customer_id 
		2016-04-15	esmart		Add @salesforce_license_id
		2021-12-21	kconvery	Read sfdc_lead_id, sfdc_opportunity_id, sfdc_trial_id from trial_registration table; remove reference to unused sfdc_trial table

		DESCRIPTION
		Select trial registration information. 
		Used by the Trial model in sfdc_update/models/SfdcLicense to associate Opportunities with trials in the fieldsByEcomLicense function.
	*/

	set nocount on

	declare @response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @salesforce_trial_id
	if @trial_id is null and @salesforce_trial_id is not null
		begin
		select @trial_id = t.trial_id
		from trial t
		inner join trial_registration r
			on t.trial_registration_id = r.trial_registration_id
		where r.sfdc_trial_id = @salesforce_trial_id
		end

	-- 1.1.1) @salesforce_license_id
	if @trial_id is null and @salesforce_license_id is not null
		begin
		select @trial_id = t.trial_id
		from trial t
		inner join trial_registration r
			on t.trial_registration_id = r.trial_registration_id
		where r.salesforce_license_id = @salesforce_license_id
		end


	-- 1.2) @customer_id or @license_id
	if @trial_id is null and @license_id is not null
		begin
		select @trial_id = t.trial_id
		from trial t
		where t.license_id = @license_id
		end

	-- 1.2) return result @trial_id
		select t.trial_id, t.trial_registration_id, c.customer_id, vc.vendor_customer_code, c.first_name, c.last_name, cc.company_name, ph.phone_number, e.customer_email, a.address_1, a.address_2, a.city, a.state, a.postal_code, country = lc.description, 
			l.license_id, l.keycode, l.license_type_id, lt.license_type_description, license_key = convert(varchar(36),k.license_key), k.salesforce_license_id, r.trial_days,
			partner_key = convert(varchar(36),p.partner_key), 
			p.partner_name, p.salesforce_id, partner_account_key = convert(varchar(36),pa.partner_account_key), aa.account_user_name,
			r.sfdc_lead_id as salesforce_lead_id, r.sfdc_opportunity_id as salesforce_opportunity_id, r.sfdc_trial_id as salesforce_trial_id, t.insert_date,
			r.eloqua_parameters
		from trial t with (nolock)
		inner join trial_registration r with (nolock)
			on t.trial_registration_id = r.trial_registration_id
		inner join license l with (nolock)
			on t.license_id = l.license_id
		inner join license_key k with (nolock)
			on t.license_id = k.license_id
		inner join license_type lt with (nolock)
			on l.license_type_id = lt.license_type_id
		inner join customer c with (nolock)
			on t.customer_id = c.customer_id
		left join customer_email e with (nolock)
			on c.customer_id = e.customer_id
		left join vendor_customer vc with (nolock)
			on c.customer_id = vc.customer_id
		left join customer_company cc with (nolock)
			on c.customer_id = cc.customer_id
		left join customer_phone ph with (nolock)
			on c.customer_id = ph.customer_id
		left join customer_address a with (nolock)
			on 
c.customer_id = a.customer_id and a.address_type_id = 1 and a.address_status_id = 1
		left join lu_countries lc with (nolock)
			on a.country_id = lc.country_id
		left join partner_trial pt with (nolock)
			on t.trial_id = pt.trial_id
		left join partner p with (nolock)
			on pt.partner_id = p.partner_id
		left join partner_account pa with (nolock)
			on pt.partner_account_id = pa.partner_account_id
		left join account aa with (nolock)
			on pa.account_id = aa.account_id
		where t.trial_id = @trial_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;






GO
