-- =============================================================================

CREATE PROCEDURE [dbo].[usp_unity_insert_refresh_token]

(
	@unity_login varchar(100),
	@refresh_token varchar(32),
	@token_expiration datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2016-10-11	esmart		Initial creation.

	DESCRIPTION
	insert unity refresh token
*/

AS
	set nocount on				

	declare	@unity_token_id int,
			@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) select @unity_token_id
	select @unity_token_id = unity_token_id
	from unity_token 
	where unity_login = @unity_login and refresh_token = @refresh_token
	
	-- 1.2) insert
	if @unity_token_id is null
		begin
		insert into unity_token (unity_login, refresh_token, token_expiration)
		values(@unity_login, @refresh_token, @token_expiration)
		end
	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_unity_select_refresh_token]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_unity_select_refresh_token]

(
	@unity_login varchar(100)
)

/*	
	DATE		AUTHOR		REMARKS
	2016-10-11	esmart		Initial creation.

	DESCRIPTION
	select unity refresh token
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select top 1 unity_login, refresh_token, token_expiration
	from unity_token
	where unity_login = @unity_login and token_expiration > getdate()
	order by token_expiration desc

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
