create procedure [dbo].[usp_update_cart_order_token]
	@cart_order_id int,
	@cart_order_token uniqueidentifier

/*	
	DATE		AUTHOR		REMARKS
	2017-11-16	cnovac		Initial creation.
*/
as

set nocount on

begin try

	declare @guid uniqueidentifier = newid()

	insert into dbo.cart_order_token_audit (cart_order_id, cart_order_token, transaction_type)
	values (@cart_order_id, @cart_order_token, 'U')

	update dbo.cart_order_token
	set cart_order_token = @guid,
		modified_date = getdate()
	where cart_order_id = @cart_order_id
