-- =============================================================================
-- PROCEDURE: [dbo].[usp_update_stats_index]
-- =============================================================================
CREATE PROC [dbo].[usp_update_stats_index]
	@debug VARCHAR(3) = 'YES'
AS


/****************** Update statistics of the table  ****************
 Version: 1.0
 Created By: Suresh Palanisamy on 29th July 2010 
 
 This proc updates statistics of all table indexes on the database it runs. It updates statistics of all indexes 
 only if avg_fragmentation_in_percent < 30 on Admin..Database_Maintenance_Index_Reorg_Results and defrag_option 
 values of 'REORGANIZE' on Admin..rebuilt_table_index.

Parameters:
   @Debug			flag specifies whether proc is running in debug mode (YES/NO, default = 'YES')

********/

	
	CREATE TABLE #object_name
	(
		rowid INT not null IDENTITY( 1, 1 ) ,
		tblname SYSNAME
	)
	
	DECLARE 
		@sql NVARCHAR( 200 ) ,
		@recordcount INT ,
		@rowno INT ,
        @schema_name VARCHAR(10),
		@tbl_name SYSNAME,
        @idx_name VARCHAR(200),
        @dt VARCHAR(12)
	
	INSERT INTO  #object_name
	SELECT NAME FROM sysobjects WHERE xtype= 'U' 
	ORDER BY name ;


	
	
	SELECT @recordcount = COUNT(rowid) , @rowno = 1 FROM #object_name
	WHILE @rowno <= @recordcount 
	BEGIN
		SELECT @tbl_name = tblname FROM #object_name WHERE rowid = @rowno
     
       SELECT  @schema_name = ss.name FROM sys.tables st JOIN sys.schemas ss 
		ON st.schema_id = ss.schema_id WHERE st.object_id=  OBJECT_ID(''+ @tbl_name +'')

DECLARE update_stats CURSOR FOR
SELECT name FROM sys.indexes WHERE object_id = OBJECT_ID(''+ @tbl_name +'')

OPEN update_stats 

FETCH NEXT FROM update_stats INTO @idx_name

WHILE @@FETCH_STATUS = 0
  BEGIN
   PRINT ' '
   IF NOT EXISTS(SELECT 1 FROM Admin.dbo.rebuild_table_index  WHERE table_name = ''+@tbl_name+'' AND index_name = ''+@idx_name+'' AND defrag_option ='REBUILD')
      BEGIN
       IF NOT EXISTS(SELECT 1 FROM Admin.dbo.Database_Maintenance_Index_Reorg_Results WHERE table_name = ''+@tbl_name+'' AND index_name = ''+@idx_name+'' AND avg_fragmentation_in_percent > 29 AND run_date > CONVERT(VARCHAR(8), GETDATE(), 1) )
       BEGIN
        PRINT ' '
		SELECT @sql = 'SET QUOTED_IDENTIFIER ON ' +  CHAR(13) + ' SET ARITHABORT ON ' +  CHAR(13) + 'UPDATE STATISTICS [' + @schema_name + '].[' + @tbl_name + '] [' + @idx_name + ']'
		PRINT @sql
		IF @debug = 'NO'
			EXEC ( @sql )
       END
         ELSE
    PRINT ' Update statistics excluded on '+@tbl_name+'.'+@idx_name+' since REBUILD already performed on this index!! '
    END
    ELSE
    PRINT ' Update statistics excluded on '+@tbl_name+'.'+@idx_name+' as per rebuild_table_index tableInfo!! '

    
		
       FETCH NEXT FROM update_stats INTO @idx_name
	END

CLOSE update_stats 
DEALLOCATE update_stats 

SELECT @rowno = @rowno + 1
END

DROP TABLE #object_name
	






GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_user_emails_insert]
-- =============================================================================

create procedure dbo.usp_user_emails_insert
(	@product_id int,
	@rc int,
	@email varchar(255),
	@language char(2),
	@locale char(3),
	@session_id bigint,
	@opt_in int
)
as
/*
Change		Modified		Reason:
Date:		By:
2010-07-07	dsmelker		Created

Purpose: Insert data into the user_emails table

*/
Begin

	set nocount on

	declare @log_type int,
			@response_code int,
			@message varchar(50),
			@DBName nvarchar(128),
			@date_received datetime

		set @log_type = 1

		set @date_received = getdate()

Begin try

	insert into user_emails
	(product_id, date_received, rc,email, [language],locale,session_id, opt_in)
	values
	(@product_id, @date_received, @rc,@email, @language,@locale,@session_id, @opt_in)

End try

Begin Catch

		
			
			set @DBName = db_name()
