-- =============================================================================
-- PROCEDURE: [dbo].[usp_vanity_get_vanity_url]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_vanity_get_vanity_url]

(
	@vanity_url nvarchar(100), 
	@host nvarchar(100) 
)

/*	
	DATE		AUTHOR		REMARKS
	2015-06-25	esmart		Initial creation.

	DESCRIPTION
	Verify vanity_url
*/

AS
	set nocount on				

	declare	@transaction_date datetime,	
			@vanity_url_id int,
			@target_url nvarchar(200),
			@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @transaction_date
	select @transaction_date = getdate()

	-- 1.2) look up vanity
	select @vanity_url_id = vanity_url_id,
			@target_url = case when activation_date <= @transaction_date and (@transaction_date < expiration_date or expiration_date is null) and status = 'active' then target_url else default_url end
	from vanity_url with (nolock)
	where vanity_url = @vanity_url and host = @host

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	if @target_url is not null
		-- 2.1) matching url
		begin
		insert into vanity_url_log(vanity_url_id) values(@vanity_url_id)
		select target_url = @target_url
		end
	else 
		-- 2.2) no match
		begin
		select target_url = ''
		end

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vanity_insert_vanity_url]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_vanity_insert_vanity_url]

(
		@vanity_url nvarchar(100), 
		@vanity_url_description nvarchar(100),
		@host nvarchar(100), 
		@target_url nvarchar(200), 
		@activation_date datetime = null,
		@expiration_date datetime = null,
		@default_url nvarchar(200) = null,
		@last_modified_by varchar(20) = null
)


/*	
	DATE		AUTHOR		REMARKS
	2015-06-15	esmart		Initial creation.

	DESCRIPTION
	Insert vanity_url
*/

AS
	set nocount on				

	declare	@vanity_url_id int,
			@response_code int,
			@message varchar(100)			


	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @vanity_url
	if (select count(*) from vanity_url where vanity_url = @vanity_url) > 0
		begin
		select response_code = -110, message = 'vanity_url already exists.'
		return
		end

	-- 1.2) defaults
	if @default_url is null
		begin
		select @default_url = 'http://www.webroot.com'
		end
	if @last_modified_by is null
		begin
		select @last_modified_by = suser_sname()
		end
	if @activation_date is null or @activation_date = 0
		begin
		select @activation_date = getdate()
		end
	if @expiration_date = 0
		begin
		select @expiration_date = null
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert/update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	insert into vanity_url(vanity_url, vanity_url_description, host, target_url, default_url, activation_date, expiration_date, last_modified_by)
	values(@vanity_url, @vanity_url_description, @host, @target_url, @default_url, @activation_date, @expiration_date, @last_modified_by)

	select @vanity_url_id = SCOPE_IDENTITY()

	select vanity_url_id = @vanity_url_id

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vanity_select_vanity_url]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_vanity_select_vanity_url]

(
	@vanity_url_id int = null,
	@vanity_url nvarchar(100) = null, 
	@host nvarchar(100) = null, 
	@target_url nvarchar(200) = null, 
	@default_url nvarchar(200) = null,
	@last_modified_by varchar(20) = null,
	@status varchar(10) = null
)


/*	
	DATE		AUTHOR		REMARKS
	2015-06-15	esmart		Initial creation.

	DESCRIPTION
	Select vanity_url
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)			


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1)
	select @vanity_url = '%' + @vanity_url + '%', 
			@host = '%' + @host + '%', 
			@target_url = '%' + @target_url + '%', 
			@default_url = '%' + @default_url + '%'

	if @vanity_url_id is not null
		begin
			select vanity_url_id, vanity_url, vanity_url_description, host, target_url, default_url, activation_date, expiration_date, status, last_modified_date, last_modified_by
			from vanity_url
			where vanity_url_id = @vanity_url_id
		end
	else
		begin
			select vanity_url_id, vanity_url, vanity_url_description, host, target_url, default_url, activation_date, expiration_date, status, last_modified_date, last_modified_by
			from vanity_url
			where (@vanity_url is null or vanity_url like @vanity_url) and
				(@host is null or host like @host) and
				(@target_url is null or target_url like @target_url) and
				(@default_url is null or default_url like @default_url) and
				status = case when @status is null then status else @status end
		end
		
	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vanity_update_vanity_url]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_vanity_update_vanity_url]

(
		@vanity_url_id int,
		@vanity_url nvarchar(100), 
		@vanity_url_description nvarchar(100),
		@host nvarchar(100), 
		@target_url nvarchar(200), 
		@activation_date datetime,
		@expiration_date datetime,
		@status varchar(10),
		@default_url nvarchar(200),
		@last_modified_by varchar(20)
)

/*	
	DATE		AUTHOR		REMARKS
	2015-06-15	esmart		Initial creation.

	DESCRIPTION
	Update vanity_url
*/

AS
	set nocount on				

	declare	@transaction_date datetime,
			@response_code int,
			@message varchar(100)			


	begin try

	select @transaction_date = getdate()

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @vanity_url
	if (select count(*) from vanity_url where vanity_url = @vanity_url and vanity_url_id <> @vanity_url_id) > 0
		begin
		select response_code = -110, message = 'vanity_url already exists.'
		return
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 2.1) insert audit
	insert into vanity_url_audit(vanity_url_id, vanity_url, vanity_url_description, host, target_url, default_url, activation_date, expiration_date, status, last_modified_date, last_modified_by,audit_date)
	select vanity_url_id, vanity_url, vanity_url_description, host, target_url, default_url, activation_date, expiration_date, status, last_modified_date, last_modified_by,@transaction_date
	from vanity_url
	where vanity_url_id = @vanity_url_id

	-- 2.2) update
	update vanity_url
	set vanity_url = @vanity_url, 
		vanity_url_description = @vanity_url_description, 
		host = @host, 
		target_url = @target_url, 
		default_url = @default_url, 
		activation_date = @activation_date,
		expiration_date = @expiration_date, 
		status = @status,
		last_modified_date = @transaction_date, 
		last_modified_by = @last_modified_by
	where vanity_url_id = @vanity_url_id

	
	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vault_select_license_vault]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_vault_select_license_vault]

(
	@vault_guid varchar(36),
	@is_active bit = null
)

/*	
	DATE		AUTHOR		REMARKS
	2021-03-10	esmart		Initial creation.

	DESCRIPTION
	Select all license_vaults 
*/

AS

	declare @vault_id int,
			@response_code int,
			@message varchar(100)
			

begin try

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	   
	-- 1.1) @vault_id
	select @vault_id = v.vault_id
	from vault v
	where v.vault_datacenter_key = @vault_guid

		-- 1.1.1) 
		if @vault_id is null
			begin
			select @response_code = -111, @message = 'Vault not found.'
			select @response_code as response_code, @message as message
			return
			end



	-- 1.2) @license_vault
	declare @license_vault table (license_external_reference_vault_id int, vault_name nvarchar(100), license_id int, customer_short_name varchar(100), csb_portal_name varchar(100), csb_portal_company_name varchar(100), is_active bit, billing_type varchar(20), storage_GB int, notes nvarchar(max), customer_id int, first_name nvarchar(225), last_name nvarchar(225),	customer_email varchar(100), salesforce_contact_id varchar(18),	company_name nvarchar(255), salesforce_account_id varchar(18), vault_guid nvarchar(100))

	insert into @license_vault(license_external_reference_vault_id,vault_name,license_id,customer_short_name,csb_portal_name,csb_portal_company_name,is_active,billing_type,storage_GB,notes,customer_id,first_name,last_name,customer_email,salesforce_contact_id,company_name,salesforce_account_id,vault_guid)	
	select lv.license_external_reference_vault_id, v.vault_name, lv.license_id,
		csn.external_reference_value as customer_short_name,
		cpn.external_reference_value as csb_portal_name,
		pcn.external_reference_value as csb_portal_company_name,
		lv.is_active,
		lv.billing_type,
		lv.storage_GB,
		lv.notes,
		c.customer_id, c.first_name, c.last_name, e.customer_email, c.salesforce_contact_id,
		co.company_name,
		co.salesforce_account_id,
		v.vault_datacenter_key as vault_guid
	from license_external_reference_vault lv
	inner join vault v
		on v.vault_id = lv.vault_id
	inner join license l
		on l.license_id = lv.license_id
	left join customer c
		on c.customer_id = l.customer_id
	left join customer_email e
		on e.customer_id = c.customer_id and e.email_status_id = 1
	left join customer_company cc
		on cc.customer_id = l.customer_id
	left join company co
		on co.company_id = cc.company_id
	outer apply fn_license_select_external_reference(lv.license_id,lv.license_category_id,19,null,lv.license_external_reference_vault_id) csn
	outer apply fn_license_select_external_reference(lv.license_id,lv.license_category_id,20,null,lv.license_external_reference_vault_id) cpn
	outer apply fn_license_select_external_reference(lv.license_id,lv.license_category_id,21,null,lv.license_external_reference_vault_id) pcn
	where lv.license_category_id = 200 and v.vault_datacenter_key = @vault_guid and
		lv.is_active = case when @is_active is null then lv.is_active else @is_active end

		-- 1.2.1) 
		if @@ROWCOUNT = 0
			begin
			select @response_code = -121, @message = 'No license vault records exist for vault.'
			select @response_code as response_code, @message as message
			return
			end

	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) retur
n
	-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select license_external_reference_vault_id,vault_name,license_id,customer_short_name,csb_portal_name,csb_portal_company_name,is_active,billing_type,storage_GB,notes,customer_id,first_name,last_name,customer_email,salesforce_contact_id,company_name,salesforce_account_id,vault_guid
	from @license_vault
	
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vault_select_vault]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_vault_select_vault]


(
	@vault_id int = null,
	@license_category_id tinyint = null,
	@license_category_name varchar(10) = null,
	@vault_status varchar(50) = null,
	@vault_name varchar(100) = null

)

/*	
	DATE		AUTHOR		REMARKS
	2020-02-20	esmart		Initial creation.
	2021-11-22  nprimo      Made procedure accepts the names of the vault so that the vault IDs don't have to be hardcoded

	DESCRIPTION
	select vault
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select v.vault_id, v.vault_name, v.vault_url, v.vault_datacenter_key, v.vault_datacenter_name, v.vault_status, v.insert_date, lc.license_category_id, lc.license_category_name
		from vault v
		inner join vault_license_category vlc
			on v.vault_id = vlc.vault_id
		inner join license_category lc
			on vlc.license_category_id = lc.license_category_id
		where v.vault_status = case when @vault_status is null then 'active' else @vault_status end and 
			v.vault_id = case when @vault_id is null then v.vault_id else @vault_id end and
			v.vault_name = case when @vault_name is null then v.vault_name else @vault_name end and
			vlc.license_category_id = case when @license_category_id is null then vlc.license_category_id else @license_category_id end and
			lc.license_category_name = case when @license_category_name is null then lc.license_category_name else @license_category_name end

		order by vlc.license_category_id, v.vault_id

		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
