-- PROCEDURE: [dbo].[usp_vault_select_vault_country]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_vault_select_vault_country]


(
	@vault_id int
)

/*	
	DATE		AUTHOR		REMARKS
	2020-02-20	esmart		Initial creation.

	DESCRIPTION
	select vault_country
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)

		-------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------

		select v.vault_id, v.vault_name, vlc.license_category_id, c.license_category_name, lc.country_id, lc.iso, lc.description as country
		from vault v
		inner join vault_country vc 
			on v.vault_id = vc.vault_id
		inner join vault_license_category vlc
			on v.vault_id = vlc.vault_id
		inner join license_category c
			on vlc.license_category_id = c.license_category_id
		inner join lu_countries lc
			on vc.country_id = lc.country_id
		where v.vault_id = @vault_id
		

		
end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'select failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vault_update_vault]
-- =============================================================================
CREATE PROCEDURE [dbo].[usp_vault_update_vault]


(
		@vault_json nvarchar(max)
)

/*	
	DATE		AUTHOR		REMARKS
	2020-09-22	esmart		Initial creation.

	DESCRIPTION
	insert/update vault
*/

AS

set nocount on				

begin try

		declare	@response_code int,
				@message varchar(100)
				
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 1.) select
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		declare @vault table (salesforce_vault_id varchar(18), billing_type varchar(20), hostname varchar(100), type_of_service varchar(100), vault_datacenter_key nvarchar(100), vault_datacenter_name nvarchar(100), vault_status varchar(50), vault_url nvarchar(255), product_platform_id tinyint, vault_id int)

		-- 1.1) parse json
		insert into @vault (salesforce_vault_id, billing_type, hostname, type_of_service, vault_datacenter_key, vault_datacenter_name, vault_status, vault_url)
		select salesforce_vault_id, billing_type, hostname, type_of_service, vault_datacenter_key, vault_datacenter_name, vault_status, vault_url
		from openjson(@vault_json) 
		with(salesforce_vault_id varchar(18) '$.ID',
			billing_type varchar(20) '$.Billing_Type__c',
			hostname varchar(100) '$.Hostname__c',
			type_of_service varchar(100) '$.Type_of_Service__c',
			vault_datacenter_key nvarchar(100) '$.GUID__c',
			vault_datacenter_name nvarchar(100) '$.Name',
			vault_status varchar(50) '$.Vault_Status__c',
			vault_url nvarchar(255) '$.External_FQDN__c')


		-- 1.2) set values
		update v 
		set v.product_platform_id = case 
					when type_of_service = 'Azure' then 2
					when type_of_service = 'On-Premise' then 3
					when pp.product_platform_id is null then 1 
					else pp.product_platform_id 
				end,
			v.vault_url = case
					when v.vault_url is null then ''
					else v.vault_url
				end
		from @vault v
		left join product_platform pp
			on v.type_of_service = pp.product_platform_name

		-- 1.3) existing vault_id
		update v
		set v.vault_id = vv.vault_id
		from @vault v
		inner join vault vv
			on v.salesforce_vault_id = vv.salesforce_vault_id or v.vault_datacenter_key = vv.vault_datacenter_key 


					
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		-- 2.) insert/update
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) insert
		insert into vault (product_platform_id, vault_name, vault_url, vault_datacenter_key, vault_datacenter_name, vault_status, billing_type, hostname, salesforce_vault_id)
		select v.product_platform_id, v.vault_datacenter_name, v.vault_url, v.vault_datacenter_key, v.vault_datacenter_name,v. vault_status, v.billing_type, v.hostname, v.salesforce_vault_id 
		from @vault v
		where v.vault_id is null

		-- 2.2) update vault
		update v
		set v.vault_url = vv.vault_url, v.vault_status = vv.vault_status, v.salesforce_vault_id = vv.salesforce_vault_id, v.hostname = vv.hostname, v.vault_datacenter_name = vv.vault_datacenter_name, v.billing_type = vv.billing_type
		from vault v
		inner join @vault vv
			on vv.vault_id = v.vault_id
		where v.vault_url <> vv.vault_url or v.vault_datacenter_name <> vv.vault_datacenter_name or v.billing_type <> vv.billing_type or v.hostname <> vv.hostname or 
v.vault_status <> vv.vault_status or v.salesforce_vault_id <> vv.salesforce_vault_id

end try

begin catch
	
	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName

end catch; 


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vendor_order_update_vendor_id]
-- =============================================================================

CREATE PROCEDURE dbo.usp_vendor_order_update_vendor_id (
   @vendor_order_code varchar(100),
   @vendor_id_current int,
   @vendor_id_new int
)

/*
   DATE            AUTHOR         REMARKS
   2008-04-30      bjensen        Initial creation

   DESCRIPTION
   Update the vendor_id and log the old id in the vendor_order_updated_vendor_order table
   Created specifically for the CyberSource Sync project

*/

AS
set nocount on

begin try
	begin transaction;

	INSERT INTO vendor_order_updated_vendor_order
	   (  vendor_order_code,
	      vendor_id_old,
	      insert_date,
	      insert_by)
	VALUES
	   (  @vendor_order_code,
	      @vendor_id_current,
         getdate(),
         suser_sname())

   UPDATE vendor_order
   SET
      vendor_id = @vendor_id_new
   WHERE
      (  vendor_order_code = @vendor_order_code AND
         vendor_id         = @vendor_id_current)

   commit transaction;
end try
begin catch
      declare @DBName nvarchar(128)
      set @DBName = db_name()
      exec usp_LogError @ErrorDB = @DBName
		if @@trancount > 0
	      rollback transaction;
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_vendor_product_select]
-- =============================================================================

CREATE       PROCEDURE usp_vendor_product_select

(
	@vendor_product_code varchar(100),
	@vendor_id int
)

AS

/*	DATE		AUTHOR		REMARKS
	2006-12-19	tblazek		Initial creation.

	DESCRIPTION
		Return a result set of a vendor product row to the PHP code
output params: 
- product_id
- root_product_id
- product_description
- basename
- product_type_id
- product_type_description
- cd_product_id
- uses_keycode
- modified_date
- product_family_id
- product_family_description
- retail_price
- pict
- product_lifecycle_id
- product_lifecycle_description

*/

	set nocount on
	
	declare @return int
	select @return = 0
	
	
	select 	p.product_id, 
		p.root_product_id, 
		p.product_description, 
		p.basename, 
		p.product_type_id, 
		t.product_type_description,
		p.cd_product_id, 
		p.uses_keycode, 
		p.modified_date, 
		p.product_family_id, 
		f.product_family_description,
		p.retail_price, 
		p.pict, 
		p.product_lifecycle_id, 
		l.product_lifecycle_description
	from product p
	inner join product_type t
		on p.product_type_id = t.product_type_id
	inner join product_family f
		on p.product_family_id = f.product_family_id
	inner join product_lifecycle l
		on p.product_lifecycle_id = l.product_lifecycle_id
	inner join vendor_product vp
		on vp.product_id = p.product_id
	Where vp.vendor_product_code = @vendor_product_code
	and vp.vendor_id = @vendor_id



GO
