CREATE PROCEDURE [dbo].[usp_web_insert_ip_activity]

(
	@ip_address varchar(24),
	@session_id varchar(20),
	@page_url varchar(120)
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-05	esmart		Initial creation.
	2013-01-15	esmart		NULL session

	DESCRIPTION
	insert ip activity
*/

AS
	set nocount on				

	declare	@web_ip_id int,
			@response_code int,
			@message varchar(100)

	begin try
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get web_ip_id
	select @web_ip_id = web_ip_id 
	from web_ip
	where ip_address = @ip_address
	
	-- 1.2) insert new ip_address
	if @web_ip_id is null
		begin
		insert into web_ip(ip_address)
		values(@ip_address)

		select @web_ip_id = scope_identity()
		end

	-- 1.3) @session_id
	if @session_id is null
		begin select @session_id = '' end

	-- 1.3) insert activity
	insert into web_ip_activity(web_ip_id, session_id, page_url)
	values(@web_ip_id, @session_id, @page_url)


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	


GO
