-- =============================================================================
-- PROCEDURE: [dbo].[usp_ww_64_insert_upgrade]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_ww_64_insert_upgrade]

(
		@customer_email varchar(100),
		@first_name nvarchar(225),
		@last_name nvarchar(225),
		@source varchar(20),
		@language_code varchar(2),
		@location_code varchar(3)
)

/*	
	DATE		AUTHOR		REMARKS
	2010-08-31	esmart		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@license_id int,
			@keycode varchar(40),
			@capability_activation_days int,
			@product_id int,
			@license_distribution_method_id int,
			@quantity int,
			@customer_id int,
			@response_code int,
			@message varchar(100)

			select @license_distribution_method_id = case
													when @source = 'update' then (select license_distribution_method_id from license_distribution_method where license_distribution_method_code = 'WWUD')
													when @source = 'trial' then 83
												end

			select @quantity = 1
			
			if @language_code = '' or @language_code is null
				begin
				select @language_code = 'EN'
				end

			if @location_code = '' or @location_code is null
				begin
				select @location_code = 'USA'
				end
	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) get customer_id
		select @customer_id = e.customer_id
		from customer_email e with (nolock)
		inner join customer c with (nolock)
			on e.customer_id = c.customer_id and c.first_name = @first_name and c.last_name = @last_name
		where e.customer_email = @customer_email and e.email_status_id = 1

		if @customer_id is null
			begin
			select @customer_id = max(e.customer_id)
			from customer_email e with (nolock)
			where e.customer_email = @customer_email and e.email_status_id = 1
			end

	-- 1.2) if no match for customer then insert a new customer
		if @customer_id is null
			begin
			exec usp_customer_insert_customer @first_name, null, @last_name, null, 1, @customer_email, NULL, @customer_id output
			end
					
	-- 1.3) check to see if customer email exists and return keycode
		select @keycode = keycode
		from ww_64_upgrade with (nolock)
		where customer_id = @customer_id

		if @keycode is not null
			begin
			select keycode = @keycode
			return
			end
	
--		select customer_id = @customer_id, keycode = @keycode

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @customer table (customer_id int, insert_date datetime)

	-- 2.1) insert customer orders
	if @source = 'update'
		begin
		-- 2.1.1) insert customer orders
			insert into @customer(customer_id, insert_date)
			select o.customer_id, insert_date = max(i.insert_date)
			from customer_order o with (nolock)
			left join order_item i with (nolock)
				on i.order_header_id = o.order_header_id
			left join product p with (nolock)
				on i.product_id = p.product_id
			where o.customer_id = @customer_id
			group by o.customer_id

		-- 2.1.2) insert license registrations
			insert into @customer(customer_id, insert_date)
			select l.customer_id, insert_date = max(l.insert_date)
			from license l with (nolock)
			where l.customer_id = @customer_id
			group by l.customer_id

		-- 2.1.3) add max insert into upgrade table

			if (select count(*) from @customer) > 0
				begin
				-- 2.3.1) registration or order found
				insert into ww_64_upgrade(customer_id, capability_activation_days, source)
				select customer_id, 
						capability_activation_days = case
													when datediff(dd,max(insert_date),getdate()) <= 365 then 365
													else 90
												end,
						source = @source
				from @customer
				group by customer_id
				end
			else
				begin	
				-- 2.3.2) no registration or order found
				insert into ww_64_upgrade(customer_id, capability_activation_days, source)
				select @customer_id, capability_activation_days = 90, source = @source
				end
		end
	if @source = 'trial'
		-- 2.2) insert trial 
		begin
		insert into ww_64_upgrade(customer_id, capability_activation_days, source)
		select @customer_id, capability_activation_days = 30, source = @source
		end
		
	
	-- 2.3) insert keycode
		declare @keycode_table table (keycode varchar(40))

		select @product_id = case
			when @language_code = 'EN' and @location_code = 'USA' then 41100110
			else 51100110
		end

		insert into @keycode_table
		exec usp_license_insert_license_cart @product_id,@license_distribution_method_id,@quantity,@response_code OUTPUT,@message OUTPUT
		
		select @keycode = keycode from @keycode_table

	-- 2.6) update license_capability
		select @capability_activation_days = capability_activation_days from ww_64_upgrade where customer_id = @customer_id

		if @capability_activation_days < 365 
			begin
			update license_capability
			set capability_activation_days = @capability_activation_days
			from license_capability c with (nolock)
			inner join license l
				on c.license_id = l.license_id
			where keycode = @keycode
			end

	-- 2.7) update ww_64_upgrade with keycode
		update ww_64_upgrade
		set keycode = @keycode 
		where customer_id = @customer_id

	-- 2.8) update license with customer_id
		update license
		set customer_id = @customer_id 
		where keycode = @keycode

	-- 2.8) return keycode
		select keycode = @keycode

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'upgrade failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_insert_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_insert_account]
 
(
		@customer_email varchar(100) = NULL,
		@license_id int = NULL,
		@trial_id int = NULL,
		@wwss_domain varchar(100) = NULL,
		@time_zone_id int = NULL,
		@wwss_ip_range varchar(max) = NULL,
		@wwss_external_id int = NULL,
		@wwss_account_user_name varchar(100) = NULL,
		@sfdc_opportunity_id varchar(40) = NULL, 
		@partner_id int = NULL,
		@distributor_id int = NULL,
		@wwss_account_id int output
)

/*	
	DATE		AUTHOR		REMARKS
	2013-01-22	acoffel		Initial creation.
	2015-07-01	esmart		Add lookup for wwss_account_id in archive
	2015-08-26  cnovac		Added call to usp_wwss_update_wwss_account if @wwss_account_id already exists
	2015-09-03	mrobbins	Added customer record create and customer_id to wwss_account insert

	DESCRIPTION
	
*/


AS
	set nocount on				

	declare
			@response_code int,
			@license_seats int,
			@capability_type_id int,
			@message varchar(100),
			@customer_id int,
			@customer_id2 int,
			@company_name varchar(255)

	select @response_code = 0

	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.)  get trial info if trial
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	if @trial_id is not NULL and @customer_email is NULL
		begin
			select @customer_email = ce.customer_email,
					@license_id = t.license_id
			from trial t
			inner join customer_email ce
				on t.customer_id = ce.customer_id
			where t.trial_id = @trial_id
		end	



	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.)  get account_id if customer_email already has registered account
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	--if @customer_email is not NULL
	--	begin
	--		select @account_id = account_id from account where account_user_name = @customer_email
	--	end	


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.)  get license info
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) get seats
	if @license_id is not NULL
		begin
			select @license_seats = license_seats from license_seat where license_id = @license_id
		end	

	-- 3.2) get license_type
	if @license_id is not NULL
		begin
			select @capability_type_id = (select lc.capability_type_id
											from license_capability lc
											inner join license_category_license lcl
												on lc.license_id = lcl.license_id
											inner join license_category c
												on lcl.license_category_id = c.license_category_id and lc.capability_id = c.base_capability_id
											where lc.license_id = @license_id)

		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 4.)  get partner and distributor info
	-- -------------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------
		if @license_id is not NULL and @trial_id is NULL
			begin
				--4.1) Set to Partner and Distributor
				select @partner_id =  p.partner_id, @distributor_id = p2.partner_id 
				from order_item_license il
				inner join order_item i
					on il.order_item_id = i.order_item_id
				left join order_company oc
					on i.order_header_id = oc.order_header_id and oc.order_company_type_id = 3
				left join company c
					on oc.company_id = c.company_id 
				left join partner p
					on c.salesforce_account_id = p.salesforce_id
				left join order_company oc2
					on i.order_header_id = oc2.order_header_id and oc2.order_company_type_id = 4
				left join company c2
					on oc2.company_id = c2.company_id 
				left join partner p2
					on c2.salesforce_account_id = p2.salesforce_id
				where il.license_id = @license_id

				if @partner_id is null begin select @partner_id = 5559 end
				if @distributor_id is null begin select @distributor_id = 5558 end

			end
		else if @license_id is not NULL and @trial_id is not NULL
			begin
				-- 4.2) trial partner or distributor
				select @partner_id =  p2.partner_id, @distributor_id = p.partner_id 
				from trial t
				inner join trial_registration tr
					on t.trial_registration_id = tr.trial_registration_id
				left join partner p
					on tr.sfdc_distributor_id = p.salesforce_id
				left join partner p2
					on tr.sfdc_reseller_id = p2.salesforce_id
				where t.trial_id = @trial_id

				if @partner_id is null begin select @partner_id = 5559 end
				if @distributor_id is null begin select @distributor_id = 5558 end

			end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 5.) insert account information
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 5.1) set @wwss_account_id according to trial or purchase path
	if @wwss_account_id is null-- and @trial_id is not NULL
		begin
			select @wwss_account_id = max(t.wwss_account_id)
			from (select wwss_account_id = isnull(max(wwss_account_id),100000000) + 1 
				from wwss_account_archive
				where wwss_account_id > 99999999
				union
				select wwss_account_id = isnull(max(wwss_account_id),100000000) + 1 
				from wwss_account 
				where wwss_account_id > 99999999) t

			-- 5.2) insert account record for any
			insert into wwss_account(wwss_account_id, license_id, license_seats, wwss_domain, wwss_ip_range, time_zone_id, wwss_external_id, wwss_account_user_name, partner_id, distributor_id, wwss_guid, insert_date, insert_by, modified_date, modified_by)
			select @wwss_account_id, @license_id, @license_seats, @wwss_domain, @wwss_ip_range, @time_zone_id, @wwss_external_id, @wwss_account_user_name, @partner_id, @distributor_id, newid(), getdate(), system_user, getdate(), system_user
		end
		else
		begin
			exec usp_wwss_update_wwss_account @wwss_account_id, null, @license_seats, @wwss_domain, @wwss_ip_range, @time_zone_id, @wwss_external_id, @wwss_account_user_name, @partner_id, @distributor_id
		end

	-- 5.2) Customer Records
	select @customer_id2 = customer_id
	from customer_email
	where customer_email = @customer_email

	if @customer_id2 is null
		begin
			--print 'customer did not exist'
			exec usp_customer_insert_customer '','','','',1,@customer_email,@company_name,@customer_id output
		end

	if @customer_id2 is not null set @customer_id = @customer_id2

	-- 5.3) insert account sfdc record for purchase
	--if @capability_type_id is not NULL
	--	begin 
	--		insert into wwss_sfdc_opportunity_account (wwss_account_id, sfdc_opportunity_id, insert_date)
	--		select @wwss_account_id, case when @capability_type_id = 2 then 'Trial' else @sfdc_opportunity_id end, getdate()
	--	end

	-- ---------
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 6.) retrieve wwss_account_id based on most recent license_id insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select @wwss_account_id as wwss_account_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'account insert failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	





GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_insert_account_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_insert_account_update]
 

(
		@wwss_account_id int,
		@wwss_template_id int,
		@wwss_update_type_id tinyint,
		@wwss_update_status_id tinyint, 
		@process_date datetime
)

/*	
	DATE		AUTHOR		REMARKS
	2014-06-30	acoffel		Initial creation.

	DESCRIPTION
	
*/

AS
	set nocount on				

	declare	@insert_date datetime,
			@response_code int,
			@message varchar(100)

	select @response_code = 0,
			@insert_date = getdate()

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @process_date
	if @process_date is null
		begin
		select @process_date = @insert_date
		end	

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	insert into wwss_update(wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, modified_date, process_date)
	values(@wwss_account_id, @wwss_template_id, @wwss_update_type_id, @wwss_update_status_id, @insert_date, @insert_date, @process_date)


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'update account update failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	



GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_insert_partner_wwss_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_insert_partner_wwss_account]

(
		@reseller_account_id varchar(20) = null,
		@distributor_account_id varchar(20) = null,
		@reseller_provisioning_admin_id varchar(20) = null,
		@distributor_provisioning_admin_id varchar(20) = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-08-12	esmart		Initial creation.	

		DESCRIPTION
		insert partner_wwss_account from trial lead
	*/

	set nocount on

	declare	@partner_id int,
			@response_code int,
			@message varchar(100)


	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) insert
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) reseller
	if @reseller_account_id is not null
		begin
			if @reseller_provisioning_admin_id is not null
				begin
				select @partner_id = partner_id from partner where salesforce_id = @reseller_account_id 

				if (select count(*) from partner_wwss_account where partner_id = @partner_id) = 0 and @partner_id is not null		
					begin
					insert into partner_wwss_account(partner_id, admin_email, salesforce_contact_id)		
					select @partner_id, e.customer_email, c.salesforce_contact_id
					from customer c
					inner join customer_email e
						on c.customer_id = e.customer_id and e.email_status_id = 1
					where c.salesforce_contact_id = @reseller_provisioning_admin_id

					update partner_wwss_account
					set oracle_account_id = DATEDIFF(ss,'1970-01-01',getdate())+SCOPE_IDENTITY()
					where partner_wwss_account_id = SCOPE_IDENTITY()
					end
				end
		end

	-- 1.2) distributor
	if @distributor_account_id is not null
		begin
			if @distributor_provisioning_admin_id is not null
				begin
				select @partner_id = partner_id from partner where salesforce_id = @distributor_account_id 

				if (select count(*) from partner_wwss_account where partner_id = @partner_id) = 0 and @partner_id is not null
					begin
					insert into partner_wwss_account(partner_id, admin_email, salesforce_contact_id)					
					select @partner_id, e.customer_email, c.salesforce_contact_id
					from customer c
					inner join customer_email e
						on c.customer_id = e.customer_id and e.email_status_id = 1
					where c.salesforce_contact_id = @distributor_provisioning_admin_id

					update partner_wwss_account
					set oracle_account_id = DATEDIFF(ss,'1970-01-01',getdate())+SCOPE_IDENTITY()
					where partner_wwss_account_id = SCOPE_IDENTITY()
					end
				end
		end


	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_data_issue_record]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_data_issue_record]

(
	@wwss_guid varchar(36)
)

	
/*	
	DATE		AUTHOR		REMARKS
	2014-01-24	acoffel		Initial Creation

	DESCRIPTION
	
	
*/


AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try


	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.2)
	select l.license_id, l.keycode, a.wwss_external_id, convert(varchar(36),a.wwss_guid) as wwss_guid, a.wwss_account_user_name as AccountName, 
			ce.customer_email as AdminEmail, z.time_zone_id as TimeZone, ls.license_seats as Licenses, a.wwss_domain as EmailDomain, ct.capability_type_description as AccountType, 
			'Site Logging' as Logging,
			'Total Web Protection' as Subscription,
			a.wwss_ip_range,
			'US' as Location,
			a.partner_id,
			a.distributor_id,
			isnull(p.partner_name,'Webroot Direct Partner') as partner_name,
			isnull(p2.partner_name,'Webroot Direct Distributor') as distributor_name,
			u.response_code,
			u.response_text
	from wwss_account a
	inner join license l
		on a.license_id = l.license_id
	inner join license_capability c
		on l.license_id = c.license_id and c.capability_id = 25
	inner join capability_type ct
		on c.capability_type_id = ct.capability_type_id
	left join partner p
		on a.partner_id = p.partner_id --and p.partner_type_id = 1
	left join partner p2
		on a.distributor_id = p2.partner_id --and p2.partner_type_id = 2
	left join time_zone z
		on a.time_zone_id = z.time_zone_id
	left join customer_email ce
		on l.customer_id = ce.customer_id
	left join license_seat ls
		on l.license_id = ls.license_id
	left join wwss_update u
		on a.wwss_account_id = u.wwss_account_id
	where a.wwss_guid = @wwss_guid
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select data issue record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
