-- PROCEDURE: [dbo].[usp_wwss_select_next_data_issue_record]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_next_data_issue_record]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2014-06-29	acoffel		Initial Creation

	DESCRIPTION
	
	
*/


AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) 


	--select @top_record_account_type

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select top 1 l.license_id, l.keycode, ls.license_seats, a.wwss_external_id, convert(varchar(36),a.wwss_guid) as wwss_guid, a.wwss_account_user_name as AccountName, 
			ce.customer_email as AdminEmail, z.time_zone_id as TimeZone, ls.license_seats as Licenses, a.wwss_domain as EmailDomain, 
			case when ct.capability_type_description = 'full' then 'Customer' else ct.capability_type_description end as AccountType, 
			'Site Logging' as Logging,
			'Total Web Protection' as Subscription,
			a.wwss_ip_range,
			'US' as Location,
			a.partner_id,
			a.distributor_id,
			isnull(p.partner_name,'Webroot Direct Partner') as partner_name,
			isnull(p2.partner_name,'Webroot Direct Distributor') as distributor_name
	from wwss_account a
	inner join license l
		on a.license_id = l.license_id
	inner join license_capability c
		on l.license_id = c.license_id and c.capability_id = 25
	inner join capability_type ct
		on c.capability_type_id = ct.capability_type_id
	left join partner p
		on a.partner_id = p.partner_id --and p.partner_type_id = 1
	left join partner p2
		on a.distributor_id = p2.partner_id --and p2.partner_type_id = 2
	left join time_zone z
		on a.time_zone_id = z.time_zone_id
	left join customer_email ce
		on l.customer_id = ce.customer_id
	left join license_seat ls
		on l.license_id = ls.license_id
	left join email_message e
		on a.license_id = e.license_id and e.message_campaign_id = 149
	where e.email_message_id is null and a.insert_date <= @batch_limit_date
	order by a.insert_date
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select data issue record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_next_queue_record]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_next_queue_record]

(
	@batch_limit_date datetime
)
	
/*	
	DATE		AUTHOR		REMARKS
	2013-09-30	acoffel		Initial Creation

	DESCRIPTION
	
	
*/


AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	select @batch_limit_date = dateadd(ss,1,@batch_limit_date) -- php cannot handle milliseconds so add one second


	--select @top_record_account_type

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	

			select top 1 u.wwss_update_id, 
						a.wwss_external_id, 
						l.license_id, 
						l.keycode, 
						ls.license_seats, 
						convert(varchar(36),a.wwss_guid) as wwss_guid, 
						u.response_code, u.response_text, 
						l.customer_id as OracleCustomerID, 
						
						--a.wwss_account_user_name as AccountName, 
						--ce.customer_email as AdminEmail, 
						AccountName = case when cc.company_name is not null and cc.company_name <> '' then cc.company_name else a.wwss_account_user_name end,
						AdminEmail = a.wwss_account_user_name, 
						
						z.time_zone_id as TimeZone, 
						ls.license_seats as Licenses, 
						a.wwss_domain as EmailDomain,
						case when ct.capability_type_description = 'full' then 'Customer' else ct.capability_type_description end as AccountType, 
						'Site Logging' as Logging,
						'Total Web Protection' as Subscription,
						a.wwss_ip_range,
						'US' as Location,
						te.wwss_template_name,
						t.wwss_update_type_name,
						u.process_date,
						a.partner_id,
						a.distributor_id,
						isnull(p.partner_name,'Webroot Direct Partner') as partner_name,
						isnull(p2.partner_name,'Webroot Direct Distributor') as distributor_name
			from wwss_update u
			inner join wwss_update_type t
				on u.wwss_update_type_id = t.wwss_update_type_id
			inner join wwss_template_update_type tt
				on t.wwss_update_type_id = tt.wwss_update_type_id
			inner join wwss_template te
				on tt.wwss_template_id = te.wwss_template_id
			inner join wwss_account a
				on u.wwss_account_id = a.wwss_account_id
			left join partner p
				on a.partner_id = p.partner_id --and p.partner_type_id = 1
			left join partner p2
				on a.distributor_id = p2.partner_id --and p2.partner_type_id = 2
			left join time_zone z
				on a.time_zone_id = z.time_zone_id
			inner join license l
				on a.license_id = l.license_id
			inner join license_capability c
				on l.license_id = c.license_id and c.capability_id = 25
			inner join capability_type ct
				on c.capability_type_id = ct.capability_type_id
			left join customer_company cc
				on l.customer_id = cc.customer_id
			left join customer_email ce
				on l.customer_id = ce.customer_id
			left join license_seat ls
				on l.license_id = ls.license_id
			where u.wwss_update_status_id in (0,2) and u.process_date <= @batch_limit_date --and u.modified_date <= @batch_limit_date
			order by process_date
	
		

	--select dateadd(hh,-1,getdate()) as 'us_west_coast'
	--select * from wwss_account a

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select next email record failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;
	

GO
