-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_template_update_type]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_template_update_type]

(
	@wwss_template_id tinyint = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	

		DESCRIPTION
		select template update type
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) create table
	declare @template_update_type table (step_id tinyint identity(1,1), wwss_template_id tinyint, wwss_template_name varchar(50), wwss_update_type_id tinyint, wwss_update_type_name varchar(20), next_update_type_id tinyint, next_update_type_name varchar(20))

	-- 1.2) insert rows
	insert into @template_update_type(wwss_template_id, wwss_template_name, wwss_update_type_id, wwss_update_type_name, next_update_type_id, next_update_type_name)
	select t.wwss_template_id, 
			t.wwss_template_name, 
			u.wwss_update_type_id, 
			u.wwss_update_type_name, 
			next_update_type_id = n.wwss_update_type_id, 
			next_update_type_name = n.wwss_update_type_name
	from wwss_template_update_type tu
	inner join wwss_template t
		on tu.wwss_template_id = t.wwss_template_id
	inner join wwss_update_type u
		on tu.wwss_update_type_id = u.wwss_update_type_id
	left join wwss_update_type n
		on tu.next_update_type_id = n.wwss_update_type_id
	where tu.wwss_template_id = case when @wwss_template_id is null then tu.wwss_template_id else @wwss_template_id end
	order by tu.wwss_template_update_type_id

	-- 1.3) return results
	select step_id, wwss_template_id, wwss_template_name, wwss_update_type_id, wwss_update_type_name, next_update_type_id, next_update_type_name
	from @template_update_type
	order by step_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
