CREATE PROCEDURE [dbo].[usp_wwss_select_update_batch]

/*	
	DATE		AUTHOR		REMARKS
	2014-06-29	acoffel		Initial creation.

	DESCRIPTION
	
	
*/

AS
	set nocount on				

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
