-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_wwss_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_wwss_account]

(
	@wwss_account_id int = null,
	@wwss_domain varchar(100) = null,
	@wwss_external_id int = null,
	@wwss_account_user_name varchar(100) = null,
	@partner_id int = null,
	@distributor_id int = null,
	@wwss_guid varchar(36) = null,
	@license_id int = null

)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	
		2015-09-11	cnovac		Added isnull to do proper comparison 
		2015-10-08	esmart		Allow search on archived accounts

		DESCRIPTION
		select wwss_account
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @wwss_account_user_name
	if @wwss_account_user_name is not null
		begin
		select @wwss_account_id = wwss_account_id from wwss_account where wwss_account_user_name = @wwss_account_user_name
		
		-- 1.1.1) archive
		if @wwss_account_user_name is not null
			begin
			select @wwss_account_id = wwss_account_id from wwss_account_archive where wwss_account_user_name = @wwss_account_user_name
			end
		end

		
	-- 1.2) @wwss_domain
	if @wwss_domain is not null
		begin
		select @wwss_account_id = wwss_account_id from wwss_account where wwss_domain = @wwss_domain
		
		-- 1.2.1) archive
		if @wwss_account_user_name is not null
			begin
			select @wwss_account_id = wwss_account_id from wwss_account_archive where wwss_domain = @wwss_domain
			end
		end

	-- 1.3) @wwss_external_id
	if @wwss_external_id is not null
		begin
		select @wwss_account_id = wwss_account_id from wwss_account where wwss_external_id = @wwss_external_id
		
		-- 1.3.1) archive
		if @wwss_account_user_name is not null
			begin
			select @wwss_account_id = wwss_account_id from wwss_account_archive where wwss_external_id = @wwss_external_id
			end
		end
		
	declare @wwss_account table (wwss_account_id int,license_id int,keycode varchar(40),license_seats int,wwss_domain varchar(100),wwss_ip_range varchar(max),time_zone_id int,time_zone_description varchar(50),wwss_external_id int,wwss_account_user_name varchar(100),partner_id int,partner_name nvarchar(100),distributor_id int,distributor_name nvarchar(100),insert_date datetime,insert_by varchar(50),modified_date datetime,modified_by varchar(50),wwss_guid varchar(36), account_type varchar(20), wwss_update_archive_id int, wwss_update_failure_id int)

	-- 1.4) insert into @wwss_account
	insert into @wwss_account(wwss_account_id, license_id, keycode, license_seats, wwss_domain, wwss_ip_range, time_zone_id, time_zone_description, wwss_external_id, wwss_account_user_name, partner_id, partner_name, distributor_id, distributor_name, insert_date, insert_by, modified_date, modified_by, wwss_guid, account_type)
	select a.wwss_account_id, 
			a.license_id, 
			l.keycode,
			a.license_seats,
			a.wwss_domain,
			a.wwss_ip_range, 
			a.time_zone_id, 
			z.time_zone_description,
			a.wwss_external_id, 
			a.wwss_account_user_name, 
			a.partner_id, 
			p2.partner_name,
			a.distributor_id, 
			distributor_name = p.partner_name,
			a.insert_date, 
			a.insert_by, 
			a.modified_date, 
			a.modified_by, 
			a.wwss_guid,
			account_type = 'Active'
	from wwss_account a
	inner join license l
		on a.license_id = l.license_id
	left join time_zone z
		on a.time_zone_id = z.time_zone_id
	left join partner p
		on a.distributor_id = p.partner_id
	left join partner p2
		on a.partner_id = p2.partner_id
	where a
.wwss_account_id = case when @wwss_account_id is null then a.wwss_account_id else @wwss_account_id end  
			and a.distributor_id = case when @distributor_id is null then a.distributor_id else @distributor_id end  
			and a.partner_id = case when @partner_id is null then a.partner_id else @partner_id end 
			and a.wwss_guid = case when @wwss_guid is null then a.wwss_guid else @wwss_guid end
			and a.license_id = case when @license_id is null then a.license_id else @license_id end 

	-- 1.5) wwss_account_archive
	if not exists (select wwss_account_id from @wwss_account)
	begin
		--select '1.1.1' return
		insert into @wwss_account(wwss_account_id, license_id, keycode, license_seats, wwss_domain, wwss_ip_range, time_zone_id, time_zone_description, wwss_external_id, wwss_account_user_name, partner_id, partner_name, distributor_id, distributor_name, insert_date, insert_by, modified_date, modified_by, wwss_guid, account_type)
		select a.wwss_account_id, 
				a.license_id, 
				l.keycode,
				a.license_seats,
				a.wwss_domain,
				a.wwss_ip_range, 
				a.time_zone_id, 
				z.time_zone_description,
				a.wwss_external_id, 
				a.wwss_account_user_name, 
				a.partner_id, 
				p2.partner_name,
				a.distributor_id, 
				distributor_name = p.partner_name,
				a.insert_date, 
				a.insert_by, 
				a.modified_date, 
				a.modified_by, 
				a.wwss_guid,
				account_type = 'Archived'
		from wwss_account_archive a
		inner join license l
			on a.license_id = l.license_id
		left join time_zone z
			on a.time_zone_id = z.time_zone_id
		left join partner p
			on a.distributor_id = p.partner_id
		left join partner p2
			on a.partner_id = p2.partner_id
		where a.wwss_account_id = case when @wwss_account_id is null then a.wwss_account_id else @wwss_account_id end  
				and a.distributor_id = case when @distributor_id is null then a.distributor_id else @distributor_id end  
				and a.partner_id = case when @partner_id is null then a.partner_id else @partner_id end 
				and a.wwss_guid = case when @wwss_guid is null then a.wwss_guid else @wwss_guid end
				and a.license_id = case when @license_id is null then a.license_id else @license_id end 
	end

	-- 1.5)
	update @wwss_account
	set wwss_update_archive_id = (select max(wwss_update_archive_id) from wwss_update_archive where wwss_account_id = a.wwss_account_id and response_code = 0),
		wwss_update_failure_id = (select max(wwss_update_archive_id) from wwss_update_archive where wwss_account_id = a.wwss_account_id and response_code <> 0)
	from @wwss_account a

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	select a.wwss_account_id, a.license_id, a.keycode, a.license_seats, a.wwss_domain, a.wwss_ip_range, a.time_zone_id, a.time_zone_description, a.wwss_external_id, a.wwss_account_user_name, a.partner_id, 
		a.partner_name, a.distributor_id, a.distributor_name, a.insert_date, a.insert_by, a.modified_date, a.modified_by, a.wwss_guid, a.account_type,
		--ua.wwss_update_type_id, ut.wwss_update_type_name,
		account_status = case
							when ut.wwss_update_type_name is null and a.wwss_external_id is null then 'Pending Configuration'
							when ut.wwss_update_type_name is null and a.wwss_external_id is not null then 'Active' -- backfilled accounts
							when ut.wwss_update_type_name in ('CreateAccount','ReactivateAccount') then 'Active'
							when ut.wwss_update_type_name in ('DeactivateAccount') then 'Deactivated'
							when ut.wwss_update_type_name in ('DeleteAccount') then 'Deleted'
							else 'Pending Configuration'
						end,
		--a.wwss_update_failure_id,
		failure_text = case 
							when a.wwss_update_failure_id > a.wwss_update_archive_
id then ua2.response_text
							else ''
						end
	from @wwss_account a
	left join wwss_update_archive ua
		on a.wwss_update_archive_id = ua.wwss_update_archive_id
	left join wwss_update_type ut
		on ua.wwss_update_type_id = ut.wwss_update_type_id
	left join wwss_update_archive ua2
		on a.wwss_update_failure_id = ua2.wwss_update_archive_id
	left join wwss_update_type ut2
		on ua2.wwss_update_type_id = ut2.wwss_update_type_id
		
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_wwss_partner_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_select_wwss_partner_account]

(
	@partner_id int = null,
	@partner_name nvarchar(100) = null,
	@partner_type_id tinyint = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	

		DESCRIPTION
		select partner_wwss_account_id
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	declare @partner_wwss_account table (partner_wwss_account_id int, partner_id int, partner_name nvarchar(100), admin_email varchar(100), salesforce_contact_id varchar(18), wwss_external_id int, last_modified_date datetime, oracle_account_id int) 

	-- 1.1) select partners
	insert into @partner_wwss_account(partner_wwss_account_id, partner_id, partner_name, admin_email, salesforce_contact_id, wwss_external_id, last_modified_date, oracle_account_id)
	select a.partner_wwss_account_id, a.partner_id, p.partner_name, a.admin_email, a.salesforce_contact_id, a.wwss_external_id, a.last_modified_date, a.oracle_account_id 
	from partner_wwss_account a
	inner join partner p
		on a.partner_id = p.partner_id
	where a.partner_id = case when @partner_id is null then a.partner_id else @partner_id end and
		p.partner_name = case when @partner_name is null then p.partner_name else @partner_name end and
		p.partner_type_id = case when @partner_type_id is null then p.partner_type_id else @partner_type_id end

	-- 1.2) partners not coded as 2, but are currently assigned
	if @partner_type_id = 2
		begin
		insert into @partner_wwss_account(partner_wwss_account_id, partner_id, partner_name, admin_email, salesforce_contact_id, wwss_external_id, last_modified_date, oracle_account_id)
		select distinct a.partner_wwss_account_id, a.partner_id, p.partner_name, a.admin_email, a.salesforce_contact_id, a.wwss_external_id, a.last_modified_date, a.oracle_account_id 
		from partner_wwss_account a
		inner join partner p
			on a.partner_id = p.partner_id
		inner join wwss_account w
			on a.partner_id = w.partner_id
		where partner_wwss_account_id not in (select partner_wwss_account_id from @partner_wwss_account)
		end
	
	-- 1.3) distributors not coded as 1, but are currently assigned
	if @partner_type_id = 1
		begin
		insert into @partner_wwss_account(partner_wwss_account_id, partner_id, partner_name, admin_email, salesforce_contact_id, wwss_external_id, last_modified_date, oracle_account_id)
		select distinct a.partner_wwss_account_id, a.partner_id, p.partner_name, a.admin_email, a.salesforce_contact_id, a.wwss_external_id, a.last_modified_date, a.oracle_account_id 
		from partner_wwss_account a
		inner join partner p
			on a.partner_id = p.partner_id
		inner join wwss_account w
			on a.partner_id = w.distributor_id
		where partner_wwss_account_id not in (select partner_wwss_account_id from @partner_wwss_account)
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) results
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	select partner_wwss_account_id, partner_id, partner_name, admin_email, salesforce_contact_id, wwss_external_id, last_modified_date, oracle_a
ccount_id 
	from @partner_wwss_account
	order by partner_name

	end try


	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_select_wwss_update]
-- =============================================================================


CREATE PROCEDURE [dbo].[usp_wwss_select_wwss_update]

(
	@wwss_update_id int = null,
	@wwss_account_user_name varchar(100) = null,
	@keycode varchar(40) = null,
	@wwss_update_status_name varchar(20) = null,
	@wwss_update_type_name varchar(20) = null,
	@start_date datetime = null,
	@end_date datetime = null,
	@wwss_account_id int = null
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-20	esmart		Initial creation.
	2015-10-08	esmart		Allow search on archived accounts

	DESCRIPTION
	Select update 
*/

AS
	set nocount on				

	declare	-- @wwss_account_id int,
			@wwss_update_status_id int,
			@wwss_update_type_id int,
			@license_id int,
			@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 1.1) @wwss_account_id	
	if @wwss_account_id is null
		begin
		select @wwss_account_id = wwss_account_id
		from wwss_account
		where wwss_account_user_name = @wwss_account_user_name
		end

	if @wwss_account_id is null
		begin
		select @wwss_account_id = wwss_account_id
		from wwss_account a
		inner join license l
			on a.license_id = l.license_id
		where l.keycode = @keycode
		end

		-- 1.1.1) account_id from archive
		if @wwss_account_id is null
			begin
			select @wwss_account_id = wwss_account_id
			from wwss_account_archive
			where wwss_account_user_name = @wwss_account_user_name

			if @wwss_account_id is null
				begin
				select @wwss_account_id = wwss_account_id
				from wwss_account_archive a
				inner join license l
					on a.license_id = l.license_id
				where l.keycode = @keycode
				end
			end

	-- 1.2) @wwss_update_status_name
	select @wwss_update_status_id = wwss_update_status_id
	from wwss_update_status
	where wwss_update_status_name = @wwss_update_status_name

	-- 1.3) @wwss_update_type_name
	select @wwss_update_type_id = wwss_update_type_id
	from wwss_update_type
	where wwss_update_type_name = @wwss_update_type_name
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) insert rows
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	declare @wwss_update table (wwss_update_id int, wwss_account_id int, license_id int, wwss_template_id tinyint, wwss_update_type_id tinyint, wwss_update_status_id tinyint, insert_date datetime, process_date datetime, update_attempts tinyint, archive_date datetime, failure_description varchar(255), queue_type varchar(20))

	if @wwss_update_id is null
		begin

		-- 2.1) wwss_update
		insert into @wwss_update (wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, queue_type)
		select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, queue_type = 'update'
		from wwss_update
		where wwss_update_status_id = case when @wwss_update_status_id is null then wwss_update_status_id else @wwss_update_status_id end and 
						(process_date < @end_date or @end_date is null)

		-- 2.2) wwss_update_archive
		insert into @wwss_update (wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id,
 insert_date, update_attempts, process_date, archive_date, failure_description, queue_type)
		select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, archive_date, response_text, queue_type = 'archive'
		from wwss_update_archive a
		inner join (select wwss_update_archive_id = max(wwss_update_archive_id)
					from wwss_update_archive
					where wwss_update_status_id = case when @wwss_update_status_id is null then wwss_update_status_id else @wwss_update_status_id end and
						(archive_date > @start_date or @start_date is null) and
						(archive_date < @end_date or @end_date is null)
					group by wwss_update_id) t
			on a.wwss_update_archive_id = t.wwss_update_archive_id
	
	
		-- 2.3) wwss_update_failure
		insert into @wwss_update (wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, archive_date, queue_type)
		select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, failure_date, queue_type = 'failure'
		from wwss_update_failure a
		inner join (select wwss_update_failure_id = max(wwss_update_failure_id)
					from wwss_update_failure
					where wwss_update_status_id = case when @wwss_update_status_id is null then wwss_update_status_id else @wwss_update_status_id end and
						(failure_date > @start_date or @start_date is null) and
						(failure_date < @end_date or @end_date is null)
					group by wwss_update_id) t
			on a.wwss_update_failure_id = t.wwss_update_failure_id

		end
	else
		begin
		-- 2.4) explicit @wwss_update_id
		insert into @wwss_update (wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, queue_type)
		select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, update_attempts, process_date, queue_type = 'update'
		from wwss_update
		where wwss_update_id = @wwss_update_id
		
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) return
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) remove rows not specific to order_header
	if @wwss_account_id is not null
		begin
		delete from @wwss_update where wwss_account_id <> @wwss_account_id or wwss_account_id is null
		end

	-- 3.2) @wwss_update_type_name
	if @wwss_update_type_id is not null
		begin
		delete from @wwss_update where wwss_update_type_id <> @wwss_update_type_id
		end
		
	--- 3.3) return results
	select t.wwss_update_id, 
			t.wwss_account_id, 
			wwss_account_user_name = case when a.wwss_account_user_name is null then a2.wwss_account_user_name else a.wwss_account_user_name end, 
			license_id = case when l.license_id is null then l2.license_id else l.license_id end, 
			keycode = case when l.keycode is null then l2.keycode else l.keycode end, 
			t.wwss_template_id, 
			tp.wwss_template_name, 
			t.wwss_update_type_id, 
			ty.wwss_update_type_name, 
			t.wwss_update_status_id, 
			s.wwss_update_status_name, 
			z.time_zone_id, 
			z.time_zone_description, 
			distributor_name = p.partner_name,
			p2.partner_name,
			t.insert_date, 
			t.process_date, 
			t.update_attempts, 
			t.archive_date, 
			t.failure_description,
			t.queue_type,
			account_type = case when a.wwss_account_id is null then 'archived' else 'active' end
	from @wwss_update t
	left join wwss_account a
		on t.wwss_account_id = a.wwss_account_id
	left join wwss_account_archive a2
		on t.wwss_account_id = a2.wwss_account_id
	left join license l
		on  l.license_id = a.license_id

	left join license l2
		on  l2.license_id = a2.license_id
	inner join wwss_update_status s
		on t.wwss_update_status_id = s.wwss_update_status_id
	inner join wwss_template tp
		on t.wwss_template_id = tp.wwss_template_id
	inner join wwss_update_type ty
		on t.wwss_update_type_id = ty.wwss_update_type_id
	inner join time_zone z
		on z.time_zone_id = case when a.time_zone_id is null then a2.time_zone_id else a.time_zone_id end
	left join partner p
		on p.partner_id = case when a.distributor_id is null then a2.distributor_id else a.distributor_id end
	left join partner p2
		on p2.partner_id = case when a.partner_id is null then a2.partner_id else a.partner_id end
	order by t.wwss_update_id desc, t.archive_date desc
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_update_queue]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_update_queue]

(
	@response_code int output,
	@message varchar(100) output
)

/*	
	DATE		AUTHOR		REMARKS
	2013-12-16	acoffel		Initial Creation

	DESCRIPTION
	update existing queue for any changes to the license
*/

AS	
		set nocount on

		declare @limit_date datetime,
				@new_accounts int,
				@new_account_id int,
				@customer_email varchar(100),
				@license_id int,
				@trial_id int,
				@wwss_domain varchar(100),
				@time_zone_id int,
				@wwss_ip_range varchar(max),
				@wwss_external_id int,
				@wwss_account_user_name varchar(100),
				@sfdc_opportunity_id varchar(40), 
				@partner_id int,
				@distributor_id int,
				@wwss_account_id int,
				@process_date datetime

begin try

		select @limit_date = min(insert_date) from wwss_update_license
		select @process_date = getdate()

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 1) check for new account
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		-- 1.1) 
		declare @new_account table (new_account_id int identity(1,1), license_id int, trial_id int)

		insert into @new_account(license_id, trial_id)
		select ul.license_id, t.trial_id
		from wwss_update_license ul
		left join trial t
			on ul.license_id = t.license_id
		left join wwss_account a
			on ul.license_id = a.license_id
		where ul.insert_date >= @limit_date and a.wwss_account_id is null
		order by ul.license_id

		select @new_accounts = count(*), @new_account_id = 1 from @new_account

		while @new_accounts >= @new_account_id
			begin
			select @license_id = license_id, @trial_id = trial_id
			from @new_account 
			where new_account_id = @new_account_id

			exec usp_wwss_insert_account @customer_email, @license_id, @trial_id, @wwss_domain, @time_zone_id, @wwss_ip_range, @wwss_external_id, @wwss_account_user_name, @sfdc_opportunity_id, @partner_id, @distributor_id, @wwss_account_id output
			
			select @wwss_account_id = null
			select @new_account_id = @new_account_id + 1
			end

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 2) update queue
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		-- 2.1) set up table with license updates
		declare @license_updates table (keycode varchar(40), 
										license_id int,
										license_status_id int, 
										capability_expiration_date datetime, 
										wwss_update_id int,
										wwss_account_id int,
										wwss_update_type_id tinyint,
										wwss_update_status_id tinyint,
										process_date datetime)
			
		insert into @license_updates(keycode,license_id,license_status_id,capability_expiration_date,wwss_update_id,wwss_account_id,wwss_update_type_id,wwss_update_status_id,process_date)
		select distinct l.keycode,l.license_id,l.license_status_id,c.capability_expiration_date,u.wwss_update_id,u.wwss_account_id,u.wwss_update_type_id,u.wwss_update_status_id,u.process_date
		from wwss_update_license ul
		inner join wwss_account a
			on ul.license_id = a.license_id
		inner join wwss_update u
			on a.wwss_account_id = u.wwss_account_id
		inner join license_capability c
			on a.license_id = c.license_id and c.capability_id = 25
		inner join license l
			on a.license_id = l.license_id


		-- 2.2) reactivate account after deactivation
		
			-- 2.2.1) archive data
			insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, inser
t_date, modified_date, process_date)
			select u.wwss_update_id, u.wwss_account_id, u.wwss_template_id, u.wwss_update_type_id, wwss_update_status_id = 3, u.response_code, u.response_text, u.update_attempts, u.insert_date, getdate(), u.process_date
			from wwss_update u
			inner join @license_updates t
				on u.wwss_update_id = t.wwss_update_id
			where t.wwss_update_type_id = 9 and t.process_date < t.capability_expiration_date and license_status_id = 1


			-- 2.2.2) set up temp table to hold accounts
			declare @reactivate_updates table (wwss_account_id int)
		
			insert into @reactivate_updates(wwss_account_id)
			select wwss_account_id
			from @license_updates
			where wwss_update_type_id = 9 and process_date < capability_expiration_date	and license_status_id = 1


			delete from wwss_update
			where wwss_update_id in (select wwss_update_id
										from @license_updates
										where wwss_update_type_id = 9 and process_date < capability_expiration_date)

			-- 2.2.3) insert reactivate queue
			insert into wwss_update(wwss_account_id, wwss_update_type_id, wwss_update_status_id, process_date)
			select wwss_account_id, wwss_update_type_id = 9, wwss_update_status_id = 0, process_date = getdate()
			from @reactivate_updates

		
		-- 2.3) extend process date for renewals 
		insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
		select u.wwss_update_id, u.wwss_account_id, u.wwss_template_id, u.wwss_update_type_id, wwss_update_status_id = 3, u.response_code, u.response_text, u.update_attempts, u.insert_date, getdate(), u.process_date
		from wwss_update u
		inner join @license_updates t
			on u.wwss_update_id = t.wwss_update_id
		where t.wwss_update_type_id in (6) and ((t.process_date <> t.capability_expiration_date) or 
			(t.process_date is null and t.capability_expiration_date is not null) or
			(t.process_date is not null and t.capability_expiration_date is null))

		update wwss_update 
		set process_date = isnull(t.capability_expiration_date,getdate()), modified_date = getdate()
		from wwss_update u
		inner join @license_updates t
			on u.wwss_update_id = t.wwss_update_id
		where t.wwss_update_type_id in (6) and ((t.process_date <> t.capability_expiration_date) or 
			(t.process_date is null and t.capability_expiration_date is not null) or
			(t.process_date is not null and t.capability_expiration_date is null))

		-- 2.4) process deactivation on disabled license	
		insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
		select u.wwss_update_id, u.wwss_account_id, u.wwss_template_id, u.wwss_update_type_id, u.wwss_update_status_id, u.response_code, u.response_text, u.update_attempts, u.insert_date, getdate(), u.process_date
		from wwss_update u
		inner join @license_updates t
			on u.wwss_update_id = t.wwss_update_id
		where t.wwss_update_type_id = 6 and t.license_status_id in (2,3)

		update wwss_update 
		set process_date = getdate(), modified_date = getdate()
		from wwss_update u
		inner join @license_updates t
			on u.wwss_update_id = t.wwss_update_id
		where t.wwss_update_type_id = 6 and t.license_status_id in (2,3)

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 2.0) check for license with updates without current queue records
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		---- 2.1) upgrades w/existing account and renewals after end service

		--declare @account_license_updates table (wwss_account_id int, wwss_template_id int, capability_type_id int null, capability_expiration_date datetime null, previous
_account_creation int, abandoned_account_creation int)

		---- 2.1.1) webfilter capability
		--insert into @account_license_updates(wwss_account_id, wwss_template_id, capability_type_id, capability_expiration_date, previous_account_creation, abandoned_account_creation)
		--select distinct a.wwss_account_id, 
		--	s.wwss_template_id,
		--	c.capability_type_id, 
		--	c.capability_expiration_date,
		--	previous_account_creation = (select count(*) from wwss_update_archive where wwss_account_id = a.wwss_account_id and wwss_update_type_id = 1 and wwss_update_status_id = 1),
		--	abandoned_account_creation = (select count(*) from wwss_update_archive where wwss_account_id = a.wwss_account_id and wwss_update_type_id = 1 and wwss_update_status_id = 3)
		--from wwss_update_license ul
		--inner join wwss_account a
		--	on ul.license_id = a.license_id
		--inner join wwss_update u
		--	on a.wwss_account_id = u.wwss_account_id
		--inner join license_capability c
		--	on a.license_id = c.license_id and c.capability_id = 25 and c.capability_expiration_date > getdate()
		--inner join license l
		--	on a.license_id = l.license_id
		--inner join wwss_update s
		--	on a.wwss_account_id = s.wwss_account_id


		---- 2.1.3) insert wwss_update
		--insert into wwss_update(wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, insert_date, modified_date, process_date)
		--select distinct wwss_account_id, wwss_template_id, wwss_update_type_id = 3, wwss_update_status_id = 0, insert_date=getdate(), modified_date=getdate(), process_date=getdate() 
		--from @account_license_updates 
		--where ((abandoned_account_creation = 0) or (abandoned_account_creation > 0 and previous_account_creation > 0))

		-- ----------------------------------------------------------------------------------------------------------------------------------------
		-- 4.0) remove wwss_update_license records
		-- ----------------------------------------------------------------------------------------------------------------------------------------

		delete from wwss_update_license where insert_date >= @limit_date


end try
begin catch

	set @response_code = -200
	set @message = case when @message is null then 'insert failed'
						else @message end

	declare @DBName nvarchar(128)
	set @DBName = db_name()
	exec usp_LogError @ErrorDB = @DBName
	
end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_update_wwss_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_update_wwss_account]

(
	@wwss_account_id int = null,
	@wwss_guid varchar(36) = null,
	@license_seats int, 
	@wwss_domain varchar(100), 
	@wwss_ip_range varchar(max), 
	@time_zone_id int, 
	@wwss_external_id int, 
	@wwss_account_user_name varchar(100), 
	@partner_id int, 
	@distributor_id int
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	
		2014-11-13	esmart		Make @wwss_external_id null when not set
		2015-08-03	mrobbins	Added customer record update
        2016-01-06  cnovac      Added code to call usp_wwss_update_wwss_update when external_id present

		DESCRIPTION
		select wwss_account
	*/

	set nocount on

	declare	@wwss_update_id int,
			@wwss_update_status_id tinyint,
			@wwss_update_type_id tinyint,
			@wwss_template_id tinyint,
			@response_code int,
			@message varchar(100),
			@customer_id int,
			@customer_id2 int

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) @wwss_account_id
	if @wwss_account_id is null
		begin
		select @wwss_account_id = wwss_account_id
		from wwss_account
		where wwss_guid = @wwss_guid
		end

	-- 1.2) @wwss_external_id
	if @wwss_external_id = 0
		begin
		select @wwss_external_id = null
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) update wwss_account
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1) wwss_account_audit
	insert into wwss_account_audit(wwss_account_id, license_id, license_seats, wwss_domain, wwss_ip_range, time_zone_id, wwss_external_id, wwss_account_user_name, partner_id, distributor_id, insert_date, insert_by, modified_date, modified_by)
	select wwss_account_id, license_id, license_seats, wwss_domain, wwss_ip_range, time_zone_id, wwss_external_id, wwss_account_user_name, partner_id, distributor_id, insert_date, insert_by, modified_date, modified_by
	from wwss_account
	where wwss_account_id = @wwss_account_id

	select @customer_id2 = customer_id
	from customer_email
	where customer_email = @wwss_account_user_name

	if @customer_id2 is null
		begin
			--print 'customer did not exist'
			exec usp_customer_insert_customer '','','','',1,@wwss_account_user_name,'',@customer_id output
		end

	if @customer_id2 is not null set @customer_id = @customer_id2

	-- 2.2) wwss_account
	update wwss_account
	set license_seats = case when @license_seats is null then license_seats else @license_seats end,
		wwss_domain = case when @wwss_domain is null then wwss_domain else @wwss_domain end,
		wwss_ip_range = case when @wwss_ip_range is null then wwss_ip_range else @wwss_ip_range end,
		time_zone_id = case when @time_zone_id is null then time_zone_id else @time_zone_id end,
		wwss_external_id = case when @wwss_external_id is null then wwss_external_id else @wwss_external_id end,
		wwss_account_user_name = case when @wwss_account_user_name is null then wwss_account_user_name else @wwss_account_user_name end,
		partner_id = case when @partner_id is null or @partner_id = 0 then partner_id else @partner_id end,
		distributor_id = case when @distributor_id is null or @partner_id = 0 then distributor_id else @distributor_id en
d,
		customer_id = @customer_id
	where wwss_account_id = @wwss_account_id

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) wwss_update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	-- 3.1) check wwss_update
	select @wwss_update_id = wwss_update_id, @wwss_update_status_id = wwss_update_status_id from wwss_update where wwss_account_id = @wwss_account_id
	
	if @wwss_update_id is not null 
	begin 
		if @wwss_update_status_id in (2,6)
		begin
			-- 3.1.1) insert archive
			insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id = 3, response_code, response_text, update_attempts, insert_date,modified_date, process_date
			from wwss_update
			where wwss_update_id = @wwss_update_id

            --if you have the external id, mark the record as processed and get it deleted from wwss_update
            --as we don't want the queuing process to pick up and try to hit wss web service
            if @wwss_external_id is not null
            begin
                exec usp_wwss_update_wwss_update @wwss_update_id, 'Processed', 0
            end
            else
            begin
                update wwss_update 
			    set wwss_update_status_id = 0, process_date = getdate(), modified_date = getdate()
			    from wwss_update
			    where wwss_update_id = @wwss_update_id
            end

		end
		return 
	end

	
	-- 3.2) check wwss_update_archive
	select @wwss_update_id = wwss_update_id from wwss_update_archive where wwss_account_id = @wwss_account_id
		
		if @wwss_update_id is not null begin return end
	
	-- 3.3) check for complete account data
	if (select count(wwss_account_id) 
		from wwss_account 
		where wwss_account_id = @wwss_account_id and 
				wwss_domain is not null and 
				wwss_ip_range is not null and 
				time_zone_id is not null and
				 wwss_account_user_name is not null and 
				 partner_id is not null and 
				 distributor_id is not null) > 0
		begin
		-- 3.3.1) insert wwss_update
		if @wwss_update_id is null
			begin
			select @wwss_template_id = 1, @wwss_update_status_id = 0
			
			select @wwss_update_type_id = min(wwss_update_type_id)
			from wwss_template_update_type tu
			where tu.wwss_template_id = @wwss_template_id

			-- 3.2.2) insert
			insert into wwss_update(wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id)
			values(@wwss_account_id, @wwss_template_id, @wwss_update_type_id, @wwss_update_status_id)
			end
		
		end





	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_update_wwss_partner_account]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_update_wwss_partner_account]

(
	@partner_id int,
	@admin_email varchar(100) = null, 
	@salesforce_contact_id varchar(18) = null, 
	@wwss_external_id int = null, 
	@oracle_account_id int = null
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	

		DESCRIPTION
		update partner_wwss_account
	*/

	set nocount on

	declare	@response_code int,
			@message varchar(100)

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) update
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) insert partner_wwss_account_audit
	insert into partner_wwss_account_audit(partner_wwss_account_id, partner_id, admin_email, salesforce_contact_id, wwss_external_id, oracle_account_id, last_modified_date)
	select partner_wwss_account_id, partner_id, admin_email, salesforce_contact_id, wwss_external_id, oracle_account_id, last_modified_date
	from partner_wwss_account
	where partner_id = @partner_id

	-- 1.2) update partner_wwss_account
	update partner_wwss_account
	set admin_email = case when @admin_email is null then admin_email else @admin_email end, 
		salesforce_contact_id = case when @salesforce_contact_id is null then salesforce_contact_id else @salesforce_contact_id end, 
		wwss_external_id = case when @wwss_external_id is null then wwss_external_id else @wwss_external_id end,
		oracle_account_id = case when @oracle_account_id is null then oracle_account_id else @oracle_account_id end
	where partner_id = @partner_id

	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;

GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_wwss_update_wwss_update]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_wwss_update_wwss_update]

(
	@wwss_update_id int, 
	@wwss_update_status_name varchar(20), 
	@responsecode int,
	@responsetext varchar(100) = NULL
)

AS
	/*	
		DATE		AUTHOR		REMARKS
		2014-04-21	esmart		Initial creation.	
		2015-04-16	esmart		Support for next update template

		DESCRIPTION
		update wwss_update
	*/

	set nocount on

	declare	@wwss_update_status_id tinyint,
			@current_wwss_update_status_id tinyint,
			@wwss_update_type_id tinyint,
			@wwss_template_id tinyint,
			@wwss_account_id int,
			@update_attempts tinyint,
			@capability_expiration_date datetime,
			@next_wwss_template_id tinyint,
			@process_date datetime,
			@archive_account tinyint,
			@response_code int,
			@message varchar(100)

	select @response_code = 0

	begin try

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 1.) select
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 1.1) select update data
	select @wwss_update_status_id = wwss_update_status_id from wwss_update_status where wwss_update_status_name = @wwss_update_status_name

	select @wwss_template_id = wwss_template_id, 
			@wwss_update_type_id = wwss_update_type_id,
			@update_attempts = update_attempts,
			@wwss_account_id = wwss_account_id
	from wwss_update
	where wwss_update_id = @wwss_update_id
	
	-- 1.2) select @wwss_update_type_id except for Create Account
	if @wwss_update_type_id in (1,2,6,9,10,11) 
		begin
		select @wwss_update_status_id = case when @responsecode = 0 then 1 else 2 end
		end

	-- 1.3) select @wwss_update_type_id for Create Account data failures
	if @wwss_update_type_id in (3) --and @wwss_external_id is NULL
		begin
		select @wwss_update_status_id = case when @responsecode = 0 then 1 else 6 end --and @wwss_external_id is not NULL
		end 

	-- 1.4) bail out of transaction
	if @current_wwss_update_status_id in (1,3)
		begin
		select @response_code = -120, @message = 'No update on processed or abandoned updates'
		select response_code = @response_code, [message] = @message
		return
		end

	-- 1.5) if 5 failed attempts, abandon subscription update
	if @update_attempts = 5 and @wwss_update_status_id in (2,4) -- failed
		begin
		select @wwss_update_status_id = 3 -- abandoned
		end
		
	-- 1.6) @archive_account
	select @archive_account = case when @wwss_update_type_id = 9 then 1 else 0 end

	--select wwss_update_status_id = @wwss_update_status_id, wwss_update_type_id = @wwss_update_type_id, wwss_template_id = @wwss_template_id, update_attempts = @update_attempts
	--return
	
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 2.) success
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	-- 2.1)  Processed
	if @wwss_update_status_id = 1 --and @wwss_update_type_id <= 3
		begin

			-- 2.1.1) insert archive record
			insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, @wwss_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from wwss_update
		
	where wwss_update_id = @wwss_update_id 

			-- 2.2) get next @wwss_update_type_id
			select @wwss_update_type_id = next_update_type_id, @next_wwss_template_id = next_wwss_template_id
			from wwss_template_update_type 
			where wwss_update_type_id = @wwss_update_type_id --and wwss_template_id = @wwss_template_id

			-- 2.3) update wwss_update
			if @wwss_update_type_id is not null
				begin 
				-- 2.3) update
					update wwss_update 
					set wwss_update_type_id = @wwss_update_type_id,update_attempts = 0,wwss_update_status_id = 0,response_code = '',response_text = '',modified_date = getdate()
					where wwss_update_id = @wwss_update_id
				end
			else
			-- 2.1.2) delete update record
				begin
					delete from wwss_update where wwss_update_id = @wwss_update_id
				end
			
			select @response_code = 0, @message = 'Update processed'
			
			-- 2.1.3) set up next update table
			declare @next_update table (wwss_update_id int, wwss_update_type_id tinyint, wwss_update_type_name varchar(20), process_date datetime)

			insert into @next_update(wwss_update_id, wwss_update_type_id, wwss_update_type_name,process_date)
			select top 1 w.wwss_update_id, t.wwss_update_type_id, t.wwss_update_type_name, w.process_date
			from wwss_update w
			inner join wwss_update_type t
				on w.wwss_update_type_id = t.wwss_update_type_id
			where w.wwss_update_id = @wwss_update_id
			order by w.wwss_update_id		

			-- 2.1.4) return results
			if (select count(*) from @next_update) = 0
				begin

				-- 2.1.4.1) final result
				select wwss_update_id = @wwss_update_id, wwss_update_type_id=null, wwss_update_type_name=null, process_date=null

				-- 2.1.4.2) archive account on delete
				if @archive_account = 1
					begin

					insert into wwss_account_archive(wwss_account_id, license_id, license_seats, wwss_domain, wwss_ip_range, time_zone_id, wwss_external_id, wwss_account_user_name, partner_id, distributor_id, insert_date, insert_by, modified_date, modified_by, wwss_guid)
					select wwss_account_id, license_id, license_seats, wwss_domain, wwss_ip_range, time_zone_id, wwss_external_id, wwss_account_user_name, partner_id, distributor_id, insert_date, insert_by, modified_date, modified_by, wwss_guid
					from wwss_account
					where wwss_account_id = @wwss_account_id

					delete from wwss_account
					where wwss_account_id = @wwss_account_id

					end

				end
			else
				begin
				-- 2.1.4.2) next result
				select wwss_update_id, wwss_update_type_id, wwss_update_type_name, process_date
				from @next_update
				end

			end

	-- 2.2) Failure
	if @wwss_update_status_id in (2)
		begin
			-- 2.2.1) log failure
			insert into wwss_update_failure(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, @wwss_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from wwss_update
			where wwss_update_id = @wwss_update_id

			-- 2.2.2) update queue
			update wwss_update 
			set wwss_update_status_id = @wwss_update_status_id,
				update_attempts = @update_attempts+1,
				response_code = @responsecode,
				response_text = @responsetext,
				modified_date = getdate(),
				process_date =   dateadd(dd,1,getdate())
			where wwss_update_id = @wwss_update_id

			select @response_code = -220, @message = 'Update failed'
			return
		end


	-- 2.3) Data Issue
	if @wwss_update_status_id in (6)
		begin
			-- 2.3.1) log failure
			insert into wwss_update_failure(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select wwss_update_id, wwss_account_id, wwss_update_type_id, wwss_template_id, @wwss_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), pro
cess_date
			from wwss_update
			where wwss_update_id = @wwss_update_id
	
			-- 2.3.2) update queue
			update wwss_update 
			set wwss_update_status_id = @wwss_update_status_id,
				update_attempts = @update_attempts+1,
				response_code = @responsecode,
				response_text = @responsetext,
				modified_date = getdate(),
				process_date = dateadd(dd,1,getdate())
			where wwss_update_id = @wwss_update_id

			select @response_code = -220, @message = 'Update had data issues'

		end

	-- 2.4) Abandonded
	if @wwss_update_status_id in (3)
		begin
			-- 2.4.1) insert archive record
			insert into wwss_update_archive(wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, response_code, response_text, update_attempts, insert_date, modified_date, process_date)
			select wwss_update_id, wwss_account_id, wwss_template_id, wwss_update_type_id, @wwss_update_status_id, @responsecode, @responsetext, @update_attempts, insert_date, getdate(), process_date
			from wwss_update
			where wwss_update_id = @wwss_update_id

			-- 2.4.2) delete update record
			delete
			from wwss_update
			where wwss_update_id = @wwss_update_id	

			select @response_code = 0, @message = 'Update processed'
		
		end

	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	-- 3.) set up next queue transaction
	-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	/*
	if @next_wwss_template_id is not null
		begin
		
		declare @process_date_basis varchar(50), @process_offset_days int

		select @wwss_update_status_id = 0

		-- 3.1) @wwss_update_type_id
		select @wwss_update_type_id = min(wwss_update_type_id)
		from wwss_template_update_type tu
		where tu.wwss_template_id = @next_wwss_template_id

		-- 3.2) @process_date_basis
		select @process_date_basis = process_date_basis, @process_offset_days = process_offset_days
		from wwss_template 
		where wwss_template_id = @next_wwss_template_id

		-- 3.2) @process_date
		select @process_date = case
									when @process_date_basis = 'Activation' then dateadd(dd,@process_offset_days,c.capability_activation_date)
									when @process_date_basis = 'Expiration' then dateadd(dd,@process_offset_days,c.capability_expiration_date)
									else getdate()
								end
		from wwss_account a
		inner join license_capability c
			on a.license_id = c.license_id and c.capability_id = 25
		where wwss_account_id = @wwss_account_id

		-- 3.2.2) insert
		insert into wwss_update(wwss_account_id, wwss_template_id, wwss_update_type_id, wwss_update_status_id, process_date)
		values(@wwss_account_id, @next_wwss_template_id, @wwss_update_type_id, @wwss_update_status_id, @process_date)

		end
	*/
	end try

	begin catch

		set @response_code = -200
		set @message = case when @message is null then 'select failed'
							else @message end

		declare @DBName nvarchar(128)
		set @DBName = db_name()
		exec usp_LogError @ErrorDB = @DBName
		
	end catch;


GO
-- =============================================================================
-- PROCEDURE: [dbo].[usp_zuora_insert_product_pricing]
-- =============================================================================

CREATE PROCEDURE [dbo].[usp_zuora_insert_product_pricing]
(
    @campaign_id INT,
    @product_catalog_json NVARCHAR(MAX)
)
/*
	DATE			AUTHOR		    REMARKS
	2024-02-01		rambasana		Initial creation.
	2024-03-05		psatish			Ecom-3796 Set up upgrade products in the zuora_product_pricing table
	2024-04-17		rambasana		Ecom-4248 Add CD product in product_pricing
	2024-07-22		rambasana		Ecom-4918 Handle multiple rate plan ID
									
	DESCRIPTION
	Insert Zuora product catalog from cpProduct api
*/
AS
SET NOCOUNT ON;
DECLARE @response_code INT,
        @message VARCHAR(100);
BEGIN TRY

    DECLARE @product_catalog TABLE
    (
        campaign_id INT,
        license_category_name VARCHAR(10),
        sku VARCHAR(200),
        license_category_id INT,
        retail_price MONEY,
        discount MONEY,
        rate_plan_id VARCHAR(50),
        years INT,
        renewal_price MONEY,
        seats INT,
        identities INT,
        product_id INT,
        product_type_id INT,
        is_upgrade BIT,
        preupgrade_license_category_name VARCHAR(10),
        preupgrade_license_seats INT NULL,
        max_remaining_day_rate_validity INT
    );

    DECLARE @zuora_product_price TABLE
    (
        campaign_id INT,
        license_category_id INT,
        sku VARCHAR(200),
        retail_price MONEY,
        discount MONEY,
        rate_plan_id VARCHAR(50),
        years INT,
        renewal_price MONEY,
        seats INT,
        identities INT,
        product_id INT,
        product_type_id INT,
        is_upgrade BIT,
        preupgrade_license_category_name VARCHAR(10),
        preupgrade_license_seats INT NULL,
        max_remaining_day_rate_validity INT
    );
    DECLARE @preupgrade_products_seats TABLE
    (
        current_license_category_name VARCHAR(10),
        upgrade_license_category_name VARCHAR(10),
        current_seats INT,
        upgrade_seats INT
    )
    INSERT INTO @product_catalog
    (
        campaign_id,
        license_category_name,
        sku,
        retail_price,
        renewal_price,
        discount,
        rate_plan_id,
        years,
        seats,
        identities,
        is_upgrade,
        preupgrade_license_category_name,
        preupgrade_license_seats,
        max_remaining_day_rate_validity
    )
    SELECT DISTINCT
           @campaign_id AS campaign_id,
           b.license_category_name,
           b.sku,
           c.retail_price,
           c.renewal_price,
           c.discount,
           c.rate_plan_id,
           c.months / 12 AS years,
           c.seats,
           c.identities,
           IIF(c.is_upgrade = 'true', '1', '0') AS is_upgrade,
           c.preupgrade_license_category_name,
           c.preupgrade_license_seats,
           c.max_remaining_day_rate_validity
    FROM
        OPENJSON(@product_catalog_json)
        WITH
        (
            catalogProducts NVARCHAR(MAX) AS JSON
        ) a
        CROSS APPLY
        OPENJSON(a.catalogProducts)
        WITH
        (
            license_category_name VARCHAR(10) '$.productLevel',
            sku VARCHAR(200) '$.sku',
            ratePlans NVARCHAR(MAX) AS JSON
        ) b
        CROSS APPLY
        OPENJSON(b.ratePlans)
        WITH
        (
            retail_price MONEY '$.newSubscriptionPrice',
            months INT '$.months',
            renewal_price MONEY '$.catalogPrice',
            seats INT '$.includedUnits',
            identities INT '$.includedIdentities',
            is_upgrade VARCHAR(10) '$.isFlatRateUpgrade',
            discount MONEY '$.percentSavings',
            preupgrade_license_category_name VARCHAR(10) '$.preUpgradeProductLevel',
            
preupgrade_license_seats INT '$.preUpgradeIncludedUnits',
            rate_plan_id VARCHAR(50) '$.ratePlanId',
            max_remaining_day_rate_validity INT '$.maxRemainingDaysRateValidity'
        ) c;

    --select the available seats for the current category
    INSERT INTO @preupgrade_products_seats
    (
        current_license_category_name,
        upgrade_license_category_name,
        current_seats,
        upgrade_seats
    )
    SELECT DISTINCT
           ct.preupgrade_license_category_name AS current_category,
           ct.license_category_name,
           CASE
               WHEN ct.preupgrade_license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' ) THEN
                   ct1.identities
               ELSE
                   ct1.seats
           END AS current_seats,
           ct.seats AS upgrade_seats
    FROM @product_catalog ct
        INNER JOIN @product_catalog ct1
            ON ct1.license_category_name = ct.preupgrade_license_category_name
        LEFT JOIN
        (
            SELECT cg.campaign_id,
                   preupgrade_license_seats,
                   cg.preupgrade_license_category_name,
                   cg.license_category_name
            FROM @product_catalog cg
            WHERE cg.is_upgrade = 1
                  AND ISNULL(cg.preupgrade_license_seats, 0) <> 0
        ) a
            ON ct.preupgrade_license_category_name = a.preupgrade_license_category_name
               AND ct.license_category_name = a.license_category_name
               AND ct1.seats = a.preupgrade_license_seats
    WHERE ct.is_upgrade = 1
          AND ct1.is_upgrade = 0
          AND a.campaign_id IS NULL


    INSERT INTO @zuora_product_price
    (
        campaign_id,
        license_category_id,
        sku,
        retail_price,
        renewal_price,
        discount,
        rate_plan_id,
        years,
        seats,
        identities,
        product_id,
        product_type_id,
        is_upgrade,
        preupgrade_license_category_name,
        preupgrade_license_seats,
        max_remaining_day_rate_validity
    )
    SELECT pc.campaign_id,
           lc.license_category_id,
           pc.sku,
           pc.retail_price,
           pc.renewal_price,
           pc.discount,
           pc.rate_plan_id,
           (ISNULL(pc.years, 0)),
           (ISNULL(pc.seats, 0)),
           (ISNULL(pc.identities, 0)),
           p.product_id,
           p.product_type_id,
           pc.is_upgrade,
           pc.preupgrade_license_category_name,
           pc.preupgrade_license_seats,
           (ISNULL(pc.max_remaining_day_rate_validity, 0))
    FROM @product_catalog pc
        INNER JOIN dbo.license_category lc
            ON pc.license_category_name = lc.license_category_name
        INNER JOIN dbo.product_license_category plc
            ON plc.license_category_id = lc.license_category_id
        INNER JOIN dbo.product p
            ON p.product_id = plc.product_id
        INNER JOIN dbo.product_years py
            ON py.product_id = p.product_id
               AND (ISNULL(pc.years, 0)) = py.years
        INNER JOIN dbo.product_seat ps
            ON ps.product_id = p.product_id
               AND ps.seats = CASE
                                  WHEN pc.license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' ) THEN
            (ISNULL(pc.identities, 0))
                                  ELSE
            (ISNULL(pc.seats, 0))
                              END
        INNER JOIN dbo.product_line_product plp
            ON plp.product_id = p.product_id
        INNER JOIN dbo.product_line pl
            ON pl.product_line_id = plp.product_line_id
    WHERE p.product_type_id IN ( 1, 2 )
          AND pc.is_upgrade = 0
          AND pl.product_line_id NOT IN ( 55, 300, 6, 200, 21, 51 )
          AND p.product_lifecycle_id = 1
    --Upgrade products
    UNION
    SELECT pc.campaign_id,
           lc.license_c
ategory_id,
           pc.sku,
           pc.retail_price,
           pc.renewal_price,
           pc.discount,
           pc.rate_plan_id,
           ISNULL(pc.years, 0),
           ISNULL(pc.seats, 0),
           ISNULL(pc.identities, 0),
           p.product_id,
           p.product_type_id,
           pc.is_upgrade,
           lc1.license_category_id,
           CASE
               WHEN pc.preupgrade_license_seats IS NOT NULL THEN
                   pc.preupgrade_license_seats
               ELSE
                   ps.current_seats
           END,
           ISNULL(pc.max_remaining_day_rate_validity, 0)
    FROM @product_catalog pc
        INNER JOIN dbo.license_category lc
            ON pc.license_category_name = lc.license_category_name
        INNER JOIN dbo.product_license_category plc
            ON plc.license_category_id = lc.license_category_id
        INNER JOIN dbo.license_category lc1
            ON lc1.license_category_name = pc.preupgrade_license_category_name
               AND plc.current_license_category_id = lc1.license_category_id
        INNER JOIN dbo.product p
            ON p.product_id = plc.product_id
        LEFT JOIN dbo.product_years py
            ON py.product_id = p.product_id
               AND ISNULL(pc.years, 0) = py.years
        INNER JOIN dbo.product_seat ps
            ON ps.product_id = p.product_id
               AND ps.seats = CASE
                                  WHEN pc.license_category_name IN ( 'WSID', 'WSIDP', 'WSIDPF' ) THEN
                                      ISNULL(pc.identities, 0)
                                  ELSE
                                      ISNULL(pc.seats, 0)
                              END
        INNER JOIN dbo.product_line_product plp
            ON plp.product_id = p.product_id
        INNER JOIN dbo.product_line pl
            ON pl.product_line_id = plp.product_line_id
        INNER JOIN @preupgrade_products_seats ups
            ON ups.current_license_category_name = lc1.license_category_name
               AND ups.upgrade_license_category_name = lc.license_category_name
               AND ps.current_seats = CASE
                                          WHEN ISNULL(pc.preupgrade_license_seats, 0) = 0 THEN
                                              ups.current_seats
                                          ELSE
                                              pc.preupgrade_license_seats
                                      END
    WHERE p.product_type_id = 3
          AND pc.is_upgrade = 1
          AND pl.product_line_id NOT IN ( 55, 300, 6, 200, 21, 51 )
          AND p.product_lifecycle_id = 1
	--CD Product
	UNION
    SELECT pc.campaign_id,
           NULL,
           pc.sku,
           pc.retail_price,
           pc.renewal_price,
           pc.discount,
           pc.rate_plan_id,
           (ISNULL(pc.years, 0)),
           (ISNULL(pc.seats, 0)),
           (ISNULL(pc.identities, 0)),
           null,
           1,
           pc.is_upgrade,
           pc.preupgrade_license_category_name,
           pc.preupgrade_license_seats,
           (ISNULL(pc.max_remaining_day_rate_validity, 0))
    FROM @product_catalog pc
	WHERE pc.license_category_name = 'S/H'

    --1.3)Insert or update camping id
    IF @campaign_id IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM dbo.zuora_product_pricing
            WHERE campaign_id = @campaign_id
        )
        BEGIN

            INSERT INTO dbo.zuora_product_pricing_history
            (
                zuora_product_pricing_id,
                campaign_id,
                rate_plan_id,
                license_category_id,
                retail_price,
                renewal_price,
                discount,
                product_id,
                product_type_id,
                seats,
                identities,
                years,
                is_u
pgrade,
                preupgrade_license_category_id,
                preupgrade_license_seats,
                max_remaining_days_rate_validity,
                insert_date,
                insert_by,
                modified_date,
                modified_by,
                sku
            )
            SELECT DISTINCT zp.*
            FROM dbo.zuora_product_pricing zp
                INNER JOIN @zuora_product_price pc
                    ON pc.campaign_id = zp.campaign_id
					   AND ISNULL(pc.product_id,0) = ISNULL(zp.product_id,0)
                       AND ISNULL(pc.license_category_id,0) = ISNULL(zp.license_category_id,0)
            WHERE zp.retail_price <> pc.retail_price
                  OR zp.renewal_price <> pc.renewal_price
				  OR zp.rate_plan_id <> pc.rate_plan_id

            UPDATE zp
            SET zp.retail_price = pc.retail_price,
                zp.renewal_price = pc.renewal_price,
				zp.rate_plan_id = pc.rate_plan_id,
                zp.discount = pc.discount,
                modified_date = GETDATE(),
                modified_by = SUSER_NAME()
            FROM dbo.zuora_product_pricing zp
                INNER JOIN @zuora_product_price pc
                    ON pc.campaign_id = zp.campaign_id
                       AND ISNULL(pc.product_id,0) = ISNULL(zp.product_id,0)
                       AND ISNULL(pc.license_category_id,0) = ISNULL(zp.license_category_id,0)
            WHERE zp.retail_price <> pc.retail_price
                  OR zp.renewal_price <> pc.renewal_price
				  OR zp.rate_plan_id <> pc.rate_plan_id
        END;




        INSERT INTO dbo.zuora_product_pricing
        (
            campaign_id,
            rate_plan_id,
            license_category_id,
            sku,
            retail_price,
            renewal_price,
            discount,
            product_id,
            product_type_id,
            seats,
            identities,
            years,
            is_upgrade,
            preupgrade_license_category_id,
            preupgrade_license_seats,
            max_remaining_days_rate_validity
        )
        SELECT pc.campaign_id,
               pc.rate_plan_id,
               pc.license_category_id,
               pc.sku,
               pc.retail_price,
               pc.renewal_price,
               pc.discount,
               pc.product_id,
               pc.product_type_id,
               CASE
                   WHEN pc.seats = 0 THEN
                       pc.identities
                   ELSE
                       pc.seats
               END,
               pc.identities,
               pc.years,
               pc.is_upgrade,
               pc.preupgrade_license_category_name,
               pc.preupgrade_license_seats,
               pc.max_remaining_day_rate_validity
        FROM @zuora_product_price pc
            LEFT JOIN dbo.zuora_product_pricing zp
                ON zp.campaign_id = pc.campaign_id
                   AND ISNULL(pc.product_id,0) = ISNULL(zp.product_id,0)
                   AND ISNULL(pc.license_category_id,0) = ISNULL(zp.license_category_id,0)
        WHERE zp.campaign_id IS NULL
              AND pc.campaign_id IS NOT NULL;

    END;

END TRY
BEGIN CATCH
    SET @response_code = -200;
    SET @message = CASE
                       WHEN @message IS NULL THEN
                           'Insertion failed'
                       ELSE
                           @message
                   END;
    DECLARE @DBName NVARCHAR(128);
    SET @DBName = DB_NAME();
    EXEC usp_LogError @ErrorDB = @DBName;
END CATCH;

GO

